module calculator(
    input wire [7:0] a,
    input wire [7:0] b,
    input wire [1:0] op,
    input wire start,
    output reg [7:0] result
);

    always @ (posedge start) begin
        case (op)
            2'b00: result <= a + b;
            2'b01: result <= a - b;
            2'b10: result <= a * b;
            2'b11: result <= a / b;
        endcase
    end
endmodule

sva:
module calculator_sva (
    input logic [7:0] a,
    input logic [7:0] b,
    input logic [1:0] op,
    input logic       start,
    input logic [7:0] result
);

    // On each start after the first, result holds the previous addition.
    check_previous_add_result: assert property (
        @(posedge start)
        (($past(start) === 1'b1) && ($past(op) == 2'b00))
        |-> (result == (($past(a) + $past(b)) & 16'h00FF))
    );

    // On each start after the first, result holds the previous subtraction.
    check_previous_sub_result: assert property (
        @(posedge start)
        (($past(start) === 1'b1) && ($past(op) == 2'b01))
        |-> (result == (($past(a) - $past(b)) & 16'h00FF))
    );

    // On each start after the first, result holds the low 8 bits of the previous product.
    check_previous_mul_result: assert property (
        @(posedge start)
        (($past(start) === 1'b1) && ($past(op) == 2'b10))
        |-> (result == (($past(a) * $past(b)) & 16'h00FF))
    );

    // On each start after the first, result holds the previous quotient when divisor was nonzero.
    check_previous_div_result: assert property (
        @(posedge start)
        (($past(start) === 1'b1) && ($past(op) == 2'b11) && ($past(b) != 8'h00))
        |-> (result == ($past(a) / $past(b)))
    );

endmodule

rtl:
module adder (
    input [7:0] a,
    input [7:0] b,
    output [7:0] s
);

    assign s = a + b;

endmodule

module overflow_detection (
    input [7:0] a,
    input [7:0] b,
    input [7:0] s,
    output overflow
);

    assign overflow = ((a[7] == b[7]) && (a[7] != s[7]));

endmodule

module overflow_indicator (
    input overflow,
    output overflow_detected
);

    assign overflow_detected = (overflow) ? 1'b1 : 1'b0;

endmodule

module top_module (
    input clk,
    input reset,
    input [7:0] a,
    input [7:0] b,
    output [7:0] s,
    output overflow,
    output overflow_detected
);

    wire [7:0] adder_output;
    wire overflow_signal;

    adder adder_inst (
        .a(a),
        .b(b),
        .s(adder_output)
    );

    overflow_detection overflow_inst (
        .a(a),
        .b(b),
        .s(adder_output),
        .overflow(overflow_signal)
    );

    overflow_indicator overflow_indicator_inst (
        .overflow(overflow_signal),
        .overflow_detected(overflow_detected)
    );

    assign s = adder_output;
    assign overflow = overflow_signal;

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic reset,
    input logic [7:0] a,
    input logic [7:0] b,
    input logic [7:0] s,
    input logic overflow,
    input logic overflow_detected
);

    // Sum output must match the 8-bit addition of a and b.
    check_sum_matches_adder: assert property (
        @(posedge clk) disable iff (reset) s == (a + b)
    );

    // Overflow must match the implemented signed overflow expression.
    check_overflow_matches_expression: assert property (
        @(posedge clk) disable iff (reset) overflow == ((a[7] == b[7]) && (a[7] != s[7]))
    );

    // Overflow indicator must be a direct copy of overflow.
    check_indicator_matches_overflow: assert property (
        @(posedge clk) disable iff (reset) overflow_detected == overflow
    );

    // Opposite-sign inputs cannot produce signed overflow.
    check_no_overflow_with_opposite_sign_inputs: assert property (
        @(posedge clk) disable iff (reset) (a[7] != b[7]) |-> !overflow
    );

    // Any reported overflow requires both inputs to have the same sign.
    check_overflow_requires_same_input_signs: assert property (
        @(posedge clk) disable iff (reset) overflow |-> (a[7] == b[7])
    );

    // Any reported overflow requires the sum sign to differ from the input sign.
    check_overflow_requires_result_sign_change: assert property (
        @(posedge clk) disable iff (reset) overflow |-> (s[7] != a[7])
    );

    // Positive plus positive yielding negative must assert overflow.
    check_positive_overflow_case: assert property (
        @(posedge clk) disable iff (reset) ((a[7] == 1'b0) && (b[7] == 1'b0) && (s[7] == 1'b1)) |-> overflow
    );

    // Negative plus negative yielding positive must assert overflow.
    check_negative_overflow_case: assert property (
        @(posedge clk) disable iff (reset) ((a[7] == 1'b1) && (b[7] == 1'b1) && (s[7] == 1'b0)) |-> overflow
    );

endmodule

rtl:
module resultcounter (resultID, newresult, done, reset, globalreset, clk);

    input[1:0] resultID; 
    input newresult; 
    output[1:0] done; 
    input reset; 
    input globalreset; 
    input clk; 

    reg[3:0] count; 
    reg[1:0] curr; 

    assign done = (count == 0) ? {curr[1], curr[0]} : 2'b00 ;

    always @(posedge clk)
    begin
        if (globalreset)
        begin
            count <= 4'b1000;
            curr <= 2'b00;
        end
        else if (reset || count == 0)
        begin
            count <= 4'b1000;
            curr <= 2'b00;
        end
        else if (newresult && resultID != 2'b00)
        begin
            count <= count - 1;
            curr <= resultID;
        end
    end 
endmodule

sva:
module resultcounter_sva (
    input logic [1:0] resultID,
    input logic       newresult,
    input logic [1:0] done,
    input logic       reset,
    input logic       globalreset,
    input logic       clk,
    input logic [3:0] count,
    input logic [1:0] curr
);

    // done is zero whenever the counter is nonzero.
    check_done_zero_when_count_nonzero: assert property (
        @(posedge clk) disable iff ($initstate)
        (count != 4'b0000) |-> (done == 2'b00)
    );

    // done matches curr only when the counter has reached zero.
    check_done_matches_curr_when_count_zero: assert property (
        @(posedge clk) disable iff ($initstate)
        (count == 4'b0000) |-> (done == curr)
    );

    // globalreset reloads the counter and clears curr on the next cycle.
    check_globalreset_loads_state: assert property (
        @(posedge clk) disable iff ($initstate)
        globalreset |=> (count == 4'b1000 && curr == 2'b00)
    );

    // reset reloads the counter and clears curr when globalreset is low.
    check_reset_loads_state: assert property (
        @(posedge clk) disable iff ($initstate)
        (!globalreset && reset) |=> (count == 4'b1000 && curr == 2'b00)
    );

    // A zero count causes the next cycle to reload the counter and clear curr.
    check_zero_count_reloads_state: assert property (
        @(posedge clk) disable iff ($initstate)
        (!globalreset && !reset && (count == 4'b0000))
        |=> (count == 4'b1000 && curr == 2'b00)
    );

    // A valid newresult decrements the counter.
    check_valid_newresult_decrements_count: assert property (
        @(posedge clk) disable iff ($initstate)
        (!globalreset && !reset && (count != 4'b0000) &&
         newresult && (resultID != 2'b00))
        |=> (count == ($past(count) - 4'b0001))
    );

    // A valid newresult updates curr with resultID.
    check_valid_newresult_updates_curr: assert property (
        @(posedge clk) disable iff ($initstate)
        (!globalreset && !reset && (count != 4'b0000) &&
         newresult && (resultID != 2'b00))
        |=> (curr == $past(resultID))
    );

    // Without reset, zero count, or a valid newresult, count holds.
    check_idle_holds_count: assert property (
        @(posedge clk) disable iff ($initstate)
        (!globalreset && !reset && (count != 4'b0000) &&
         !(newresult && (resultID != 2'b00)))
        |=> (count == $past(count))
    );

    // Without reset, zero count, or a valid newresult, curr holds.
    check_idle_holds_curr: assert property (
        @(posedge clk) disable iff ($initstate)
        (!globalreset && !reset && (count != 4'b0000) &&
         !(newresult && (resultID != 2'b00)))
        |=> (curr == $past(curr))
    );

    // The final valid decrement drives done with the accepted result ID.
    check_terminal_result_drives_done: assert property (
        @(posedge clk) disable iff ($initstate)
        (!globalreset && !reset && (count == 4'b0001) &&
         newresult && (resultID != 2'b00))
        |=> (count == 4'b0000 && curr == $past(resultID) && done == $past(resultID))
    );

endmodule

rtl:
module xor_adder (
  input clk,
  input [1:0] a,
  input [1:0] b,
  output reg [1:0] sum
);

reg [1:0] stage1_sum;
reg [1:0] stage2_sum;

always @(posedge clk) begin
  stage1_sum <= a ^ b;
  stage2_sum <= stage1_sum ^ sum;
  sum <= stage2_sum;
end

endmodule

sva:
module xor_adder_sva (
    input logic       clk,
    input logic [1:0] a,
    input logic [1:0] b,
    input logic [1:0] sum,
    input logic [1:0] stage1_sum,
    input logic [1:0] stage2_sum
);

property p_stage1_captures_input_xor;
    logic [1:0] exp_stage1;
    @(posedge clk)
        (exp_stage1 = (a ^ b), 1'b1)
        |=> (stage1_sum == exp_stage1);
endproperty

// stage1_sum loads a ^ b on the next clock.
check_stage1_captures_input_xor: assert property (p_stage1_captures_input_xor);

property p_stage2_captures_stage1_xor_sum;
    logic [1:0] exp_stage2;
    @(posedge clk)
        (exp_stage2 = (stage1_sum ^ sum), 1'b1)
        |=> (stage2_sum == exp_stage2);
endproperty

// stage2_sum loads stage1_sum ^ sum on the next clock.
check_stage2_captures_stage1_xor_sum: assert property (p_stage2_captures_stage1_xor_sum);

property p_sum_captures_stage2;
    logic [1:0] exp_sum;
    @(posedge clk)
        (exp_sum = stage2_sum, 1'b1)
        |=> (sum == exp_sum);
endproperty

// sum loads stage2_sum on the next clock.
check_sum_captures_stage2: assert property (p_sum_captures_stage2);

property p_stage2_matches_delayed_inputs_and_sum;
    logic [1:0] xor_ab;
    logic [1:0] exp_stage2;
    @(posedge clk)
        (xor_ab = (a ^ b), 1'b1) ##1
        (exp_stage2 = (xor_ab ^ sum), 1'b1)
        |=> (stage2_sum == exp_stage2);
endproperty

// stage2_sum matches the earlier input XOR combined with the prior sum.
check_stage2_matches_delayed_inputs_and_sum: assert property (p_stage2_matches_delayed_inputs_and_sum);

property p_sum_matches_stage1_and_sum_two_cycles_later;
    logic [1:0] exp_sum;
    @(posedge clk)
        (exp_sum = (stage1_sum ^ sum), 1'b1) ##1
        1'b1
        |=> (sum == exp_sum);
endproperty

// sum two clocks later equals the captured stage1_sum ^ sum value.
check_sum_matches_stage1_and_sum_two_cycles_later: assert property (p_sum_matches_stage1_and_sum_two_cycles_later);

property p_sum_matches_delayed_inputs_and_sum;
    logic [1:0] xor_ab;
    logic [1:0] exp_sum;
    @(posedge clk)
        (xor_ab = (a ^ b), 1'b1) ##1
        (exp_sum = (xor_ab ^ sum), 1'b1) ##1
        1'b1
        |=> (sum == exp_sum);
endproperty

// sum three clocks later matches the earlier input XOR and next-cycle sum.
check_sum_matches_delayed_inputs_and_sum: assert property (p_sum_matches_delayed_inputs_and_sum);

endmodule

