module calculator(
    input [7:0] A,
    input [7:0] B,
    input [1:0] op,
    output reg [7:0] Y
);

    always @* begin
        case(op)
            2'b00: Y = A + B;
            2'b01: Y = A - B;
            2'b10: Y = A * B;
            2'b11: Y = A / B;
        endcase
    end

endmodule

sva:
module calculator_sva (
    input logic clk,
    input logic [7:0] A,
    input logic [7:0] B,
    input logic [1:0] op,
    input logic [7:0] Y
);

    // Addition opcode drives Y with the 8-bit sum.
    check_addition_result: assert property (
        @(posedge clk)
        (op === 2'b00) |-> (Y === 8'(A + B))
    );

    // Subtraction opcode drives Y with the 8-bit difference.
    check_subtraction_result: assert property (
        @(posedge clk)
        (op === 2'b01) |-> (Y === 8'(A - B))
    );

    // Multiplication opcode drives Y with the low 8 bits of the product.
    check_multiplication_result: assert property (
        @(posedge clk)
        (op === 2'b10) |-> (Y === 8'(A * B))
    );

    // Division opcode drives Y with the quotient when the divisor is known and nonzero.
    check_division_result: assert property (
        @(posedge clk)
        ((op === 2'b11) && !$isunknown(B) && (B != 8'h00)) |-> (Y === 8'(A / B))
    );

endmodule

module xor_reset_sva (
    input logic in1,
    input logic in2,
    input logic reset,
    input logic out1
);

    // Reset forces the output low.
    check_reset_forces_zero: assert property (
        @($global_clock) reset |-> (out1 == 1'b0)
    );

    // Outside reset, the output matches in1 XOR in2.
    check_xor_function: assert property (
        @($global_clock) disable iff (reset) (out1 == (in1 ^ in2))
    );

    // Outside reset, 0 XOR 0 drives the output low.
    check_xor_00_case: assert property (
        @($global_clock) disable iff (reset)
            (((in1 == 1'b0) && (in2 == 1'b0)) |-> (out1 == 1'b0))
    );

    // Outside reset, 0 XOR 1 drives the output high.
    check_xor_01_case: assert property (
        @($global_clock) disable iff (reset)
            (((in1 == 1'b0) && (in2 == 1'b1)) |-> (out1 == 1'b1))
    );

    // Outside reset, 1 XOR 0 drives the output high.
    check_xor_10_case: assert property (
        @($global_clock) disable iff (reset)
            (((in1 == 1'b1) && (in2 == 1'b0)) |-> (out1 == 1'b1))
    );

    // Outside reset, 1 XOR 1 drives the output low.
    check_xor_11_case: assert property (
        @($global_clock) disable iff (reset)
            (((in1 == 1'b1) && (in2 == 1'b1)) |-> (out1 == 1'b0))
    );

endmodule

rtl:
module calculator(a, b, op, result, valid);
   input [7:0] a, b;
   input [1:0] op;
   output reg [7:0] result;
   output reg valid;

   always @(*) begin
      case (op)
         2'b00: result = a + b;
         2'b01: result = a - b;
         2'b10: result = a * b;
         2'b11: begin
            if (b == 0) begin
               result = 8'b0;
               valid = 1'b0;
            end else begin
               result = a / b;
               valid = 1'b1;
            end
         end
      endcase

      if (op == 2'b11 && b == 0) begin
         valid = 1'b0;
      end else begin
         valid = 1'b1;
      end
   end
endmodule

sva:
module calculator_sva (
    input logic clk,
    input logic [7:0] a,
    input logic [7:0] b,
    input logic [1:0] op,
    input logic [7:0] result,
    input logic valid
);

    // Addition returns the 8-bit sum and sets valid.
    check_add_result: assert property (
        @(posedge clk)
        (op == 2'b00) |-> ((result == (a + b)) && (valid == 1'b1))
    );

    // Subtraction returns the 8-bit difference and sets valid.
    check_sub_result: assert property (
        @(posedge clk)
        (op == 2'b01) |-> ((result == (a - b)) && (valid == 1'b1))
    );

    // Multiplication returns the low 8 bits of the product and sets valid.
    check_mul_result: assert property (
        @(posedge clk)
        (op == 2'b10) |-> ((result == ((a * b) & 16'h00FF)) && (valid == 1'b1))
    );

    // Division by zero forces a zero result and clears valid.
    check_div_zero_result: assert property (
        @(posedge clk)
        ((op == 2'b11) && (b == 8'h00)) |-> ((result == 8'h00) && (valid == 1'b0))
    );

    // Division by a nonzero operand returns the quotient and sets valid.
    check_div_nonzero_result: assert property (
        @(posedge clk)
        ((op == 2'b11) && (b != 8'h00)) |-> ((result == (a / b)) && (valid == 1'b1))
    );

    // valid can be low only for division by zero.
    check_valid_low_only_on_div_zero: assert property (
        @(posedge clk)
        (valid == 1'b0) |-> ((op == 2'b11) && (b == 8'h00))
    );

    // Any case other than division by zero must set valid.
    check_valid_high_otherwise: assert property (
        @(posedge clk)
        (!((op == 2'b11) && (b == 8'h00))) |-> (valid == 1'b1)
    );

    // valid depends only on op and b, not on a.
    check_valid_stable_when_op_b_stable: assert property (
        @(posedge clk)
        ($stable(op) && $stable(b)) |-> $stable(valid)
    );

endmodule

rtl:
module sky130_fd_sc_hd__o22ai (
    Y ,
    A1,
    A2,
    B1,
    B2
);

    output Y ;
    input  A1;
    input  A2;
    input  B1;
    input  B2;

    wire nor0_out ;
    wire nor1_out ;
    wire or0_out_Y;

    nor nor0 (nor0_out , B1, B2            );
    nor nor1 (nor1_out , A1, A2            );
    or  or0  (or0_out_Y, nor1_out, nor0_out);
    buf buf0 (Y        , or0_out_Y         );

endmodule

sva:
module sky130_fd_sc_hd__o22ai_sva (
    input logic clk,
    input logic Y,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic B2
);

    // Y matches the implemented O22AI boolean function.
    check_output_matches_o22ai_function: assert property (
        @(posedge clk) (Y == (((!A1) && (!A2)) || ((!B1) && (!B2))))
    );

    // If both A inputs are low, Y must be high.
    check_a_inputs_low_force_high: assert property (
        @(posedge clk) ((!A1 && !A2) |-> (Y == 1'b1))
    );

    // If both B inputs are low, Y must be high.
    check_b_inputs_low_force_high: assert property (
        @(posedge clk) ((!B1 && !B2) |-> (Y == 1'b1))
    );

    // If either A input and either B input are high, Y must be low.
    check_active_a_and_b_force_low: assert property (
        @(posedge clk) (((A1 || A2) && (B1 || B2)) |-> (Y == 1'b0))
    );

    // A high Y means at least one input pair is all low.
    check_high_output_means_one_pair_low: assert property (
        @(posedge clk) ((Y == 1'b1) |-> ((!A1 && !A2) || (!B1 && !B2)))
    );

    // A low Y means both input pairs have an asserted member.
    check_low_output_means_both_pairs_active: assert property (
        @(posedge clk) ((Y == 1'b0) |-> ((A1 || A2) && (B1 || B2)))
    );

endmodule

rtl:
module and3(
    X,
    A,
    B,
    C
);

    output X;
    input A;
    input B;
    input C;

    wire AB;
    wire ABC;

    assign AB = A & B;
    assign ABC = AB & C;
    assign X = ABC;

endmodule

sva:
module and3_sva(
    input logic clk,
    input logic A,
    input logic B,
    input logic C,
    input logic X
);

    // X must equal the AND of A, B, and C.
    check_x_matches_and3: assert property (
        @(posedge clk) X == (A & B & C)
    );

    // X high requires all three inputs to be high.
    check_x_high_implies_all_inputs_high: assert property (
        @(posedge clk) X |-> (A && B && C)
    );

    // All three inputs high must drive X high.
    check_all_inputs_high_implies_x_high: assert property (
        @(posedge clk) (A && B && C) |-> X
    );

    // Any low input must force X low.
    check_any_low_input_forces_x_low: assert property (
        @(posedge clk) ((!A) || (!B) || (!C)) |-> !X
    );

endmodule

rtl:
module MUX_2_TO_1
(
  input A,
  input B,
  input S,
  output Z
);

  assign Z = (S == 0) ? A : B;

endmodule

sva:
module MUX_2_TO_1_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic S,
    input logic Z
);

    // Output must implement the mux equation.
    check_mux_function: assert property (
        @(posedge clk) Z === ((S == 1'b0) ? A : B)
    );

    // Low select routes A to the output.
    check_select_a: assert property (
        @(posedge clk) (S === 1'b0) |-> (Z === A)
    );

    // High select routes B to the output.
    check_select_b: assert property (
        @(posedge clk) (S === 1'b1) |-> (Z === B)
    );

    // If both inputs match, the output must match them as well.
    check_equal_inputs_passthrough: assert property (
        @(posedge clk) (A === B) |-> (Z === A)
    );

