rtl:
module priority_mux (
    input [3:0] A, B, C, D,
    input [1:0] S,
    output reg Y, Z
);

always @(*) begin
    case(S)
        2'b00: begin
            if(A) begin
                Y = 1;
                Z = 0;
            end
            else if(B) begin
                Y = 0;
                Z = 1;
            end
            else if(C) begin
                Y = 0;
                Z = 0;
            end
            else if(D) begin
                Y = 0;
                Z = 0;
            end
            else begin
                Y = 0;
                Z = 0;
            end
        end
        2'b01: begin
            if(B) begin
                Y = 0;
                Z = 1;
            end
            else if(A) begin
                Y = 1;
                Z = 0;
            end
            else if(C) begin
                Y = 0;
                Z = 0;
            end
            else if(D) begin
                Y = 0;
                Z = 0;
            end
            else begin
                Y = 0;
                Z = 0;
            end
        end
        2'b10: begin
            if(C) begin
                Y = 0;
                Z = 0;
            end
            else if(A) begin
                Y = 1;
                Z = 0;
            end
            else if(B) begin
                Y = 0;
                Z = 1;
            end
            else if(D) begin
                Y = 0;
                Z = 0;
            end
            else begin
                Y = 0;
                Z = 0;
            end
        end
        2'b11: begin
            if(D) begin
                Y = 0;
                Z = 0;
            end
            else if(A) begin
                Y = 1;
                Z = 0;
            end
            else if(B) begin
                Y = 0;
                Z = 1;
            end
            else if(C) begin
                Y = 0;
                Z = 0;
            end
            else begin
                Y = 0;
                Z = 0;
            end
        end
    endcase
end

endmodule

sva:
module priority_mux_sva (
    input logic        clk,
    input logic [3:0]  A,
    input logic [3:0]  B,
    input logic [3:0]  C,
    input logic [3:0]  D,
    input logic [1:0]  S,
    input logic        Y,
    input logic        Z
);

    // Y and Z are never driven high together.
    check_outputs_not_both_high: assert property (
        @(posedge clk) !(Y && Z)
    );

    // For S=00, any nonzero A selects Y=1 and Z=0.
    check_sel00_a_priority: assert property (
        @(posedge clk)
        (S == 2'b00 && (A != 4'b0000)) |-> (Y == 1'b1 && Z == 1'b0)
    );

    // For S=00, B selects Y=0 and Z=1 when A is zero.
    check_sel00_b_priority: assert property (
        @(posedge clk)
        (S == 2'b00 && (A == 4'b0000) && (B != 4'b0000)) |-> (Y == 1'b0 && Z == 1'b1)
    );

    // For S=00, outputs are 0 when both A and B are zero.
    check_sel00_default_zero: assert property (
        @(posedge clk)
        (S == 2'b00 && (A == 4'b0000) && (B == 4'b0000)) |-> (Y == 1'b0 && Z == 1'b0)
    );

    // For S=01, any nonzero B selects Y=0 and Z=1.
    check_sel01_b_priority: assert property (
        @(posedge clk)
        (S == 2'b01 && (B != 4'b0000)) |-> (Y == 1'b0 && Z == 1'b1)
    );

    // For S=01, A selects Y=1 and Z=0 when B is zero.
    check_sel01_a_priority: assert property (
        @(posedge clk)
        (S == 2'b01 && (B == 4'b0000) && (A != 4'b0000)) |-> (Y == 1'b1 && Z == 1'b0)
    );

    // For S=01, outputs are 0 when both B and A are zero.
    check_sel01_default_zero: assert property (
        @(posedge clk)
        (S == 2'b01 && (B == 4'b0000) && (A == 4'b0000)) |-> (Y == 1'b0 && Z == 1'b0)
    );

    // For S=10, any nonzero C forces both outputs low.
    check_sel10_c_priority: assert property (
        @(posedge clk)
        (S == 2'b10 && (C != 4'b0000)) |-> (Y == 1'b0 && Z == 1'b0)
    );

    // For S=10, A selects Y=1 and Z=0 when C is zero.
    check_sel10_a_priority: assert property (
        @(posedge clk)
        (S == 2'b10 && (C == 4'b0000) && (A != 4'b0000)) |-> (Y == 1'b1 && Z == 1'b0)
    );

    // For S=10, B selects Y=0 and Z=1 when C and A are zero.
    check_sel10_b_priority: assert property (
        @(posedge clk)
        (S == 2'b10 && (C == 4'b0000) && (A == 4'b0000) && (B != 4'b0000)) |-> (Y == 1'b0 && Z == 1'b1)
    );

    // For S=10, outputs are 0 when C, A, and B are all zero.
    check_sel10_default_zero: assert property (
        @(posedge clk)
        (S == 2'b10 && (C == 4'b0000) && (A == 4'b0000) && (B == 4'b0000)) |-> (Y == 1'b0 && Z == 1'b0)
    );

    // For S=11, any nonzero D forces both outputs low.
    check_sel11_d_priority: assert property (
        @(posedge clk)
        (S == 2'b11 && (D != 4'b0000)) |-> (Y == 1'b0 && Z == 1'b0)
    );

    // For S=11, A selects Y=1 and Z=0 when D is zero.
    check_sel11_a_priority: assert property (
        @(posedge clk)
        (S == 2'b11 && (D == 4'b0000) && (A != 4'b0000)) |-> (Y == 1'b1 && Z == 1'b0)
    );

    // For S=11, B selects Y=0 and Z=1 when D and A are zero.
    check_sel11_b_priority: assert property (
        @(posedge clk)
        (S == 2'b11 && (D == 4'b0000) && (A == 4'b0000) && (B != 4'b0000)) |-> (Y == 1'b0 && Z == 1'b1)
    );

    // For S=11, outputs are 0 when D, A, and B are all zero.
    check_sel11_default_zero: assert property (
        @(posedge clk)
        (S == 2'b11 && (D == 4'b0000) && (A == 4'b0000) && (B == 4'b0000)) |-> (Y == 1'b0 && Z == 1'b0)
    );

endmodule

rtl:
module adder_16bit(
    input [15:0] A, B,
    output [15:0] S,
    output C
    );

    wire [15:0] temp;
    wire [16:0] sum;

    assign temp = A ^ B;
    assign sum = {1'b0, A} + {1'b0, B};
    assign S = sum[15:0];
    assign C = sum[16];

endmodule

sva:
module adder_16bit_sva (
    input logic        clk,
    input logic [15:0] A,
    input logic [15:0] B,
    input logic [15:0] S,
    input logic        C
);

    // Full output must match the 17-bit sum of A and B.
    check_full_sum: assert property (
        @(posedge clk) {C, S} == ({1'b0, A} + {1'b0, B})
    );

    // S must be the low 16 bits of the addition result.
    check_sum_low_bits: assert property (
        @(posedge clk) S == (({1'b0, A} + {1'b0, B})[15:0])
    );

    // C must be the carry-out bit of the addition result.
    check_carry_out: assert property (
        @(posedge clk) C == (({1'b0, A} + {1'b0, B})[16])
    );

    // Adding zero on A must return B with no carry.
    check_a_zero_identity: assert property (
        @(posedge clk) (A == 16'h0000) |-> ({C, S} == {1'b0, B})
    );

    // Adding zero on B must return A with no carry.
    check_b_zero_identity: assert property (
        @(posedge clk) (B == 16'h0000) |-> ({C, S} == {1'b0, A})
    );

    // Disjoint 1-bits must add as XOR with no carry.
    check_disjoint_bits_xor: assert property (
        @(posedge clk) ((A & B) == 16'h0000) |-> ({C, S} == {1'b0, (A ^ B)})
    );

    // Complementary inputs must sum to all ones with no carry.
    check_complementary_inputs: assert property (
        @(posedge clk) (B == ~A) |-> ((S == 16'hFFFF) && (C == 1'b0))
    );

    // If both MSBs are 0, the addition cannot produce a carry-out.
    check_no_carry_when_msbs_zero: assert property (
        @(posedge clk) ((!A[15]) && (!B[15])) |-> (C == 1'b0)
    );

    // If both MSBs are 1, the addition must produce a carry-out.
    check_carry_when_msbs_one: assert property (
        @(posedge clk) (A[15] && B[15]) |-> (C == 1'b1)
    );

    // Adding all ones to all ones must produce FFFE with carry.
    check_all_ones_corner: assert property (
        @(posedge clk) ((A == 16'hFFFF) && (B == 16'hFFFF)) |-> ((S == 16'hFFFE) && (C == 1'b1))
    );

endmodule

rtl:
module keypad_left_shift (
    input clk,
    input [3:0] col,
    output reg [7:0] out
);

    reg [3:0] row;
    reg [3:0] key_pressed;
    reg [3:0] shifted_key_pressed;

    // 4x4 matrix keypad scanner
    always @(posedge clk) begin
        row <= 4'b1110;
        if (col == 4'b1110) key_pressed <= 4'b0001;
        else if (col == 4'b1101) key_pressed <= 4'b0010;
        else if (col == 4'b1011) key_pressed <= 4'b0100;
        else if (col == 4'b0111) key_pressed <= 4'b1000;
        else key_pressed <= 4'b0000;
    end

    // 4-bit binary left shift module
    always @(posedge clk) begin
        shifted_key_pressed[3:1] <= key_pressed[2:0];
        shifted_key_pressed[0] <= key_pressed[3];
    end

    // Concatenate the output from the keypad scanner and the left shift module
    always @(posedge clk) begin
        out <= {shifted_key_pressed, key_pressed};
    end

endmodule

sva:
module keypad_left_shift_sva (
    input logic       clk,
    input logic [3:0] col,
    input logic [7:0] out,
    input logic [3:0] row,
    input logic [3:0] key_pressed,
    input logic [3:0] shifted_key_pressed
);

    // Row is forced to the fixed scan value each cycle.
    check_row_constant: assert property (
        @(posedge clk) 1'b1 |=> (row === 4'b1110)
    );

    // Column 1110 decodes to key 0001.
    check_key_decode_col_1110: assert property (
        @(posedge clk) (col === 4'b1110) |=> (key_pressed === 4'b0001)
    );

    // Column 1101 decodes to key 0010.
    check_key_decode_col_1101: assert property (
        @(posedge clk) (col === 4'b1101) |=> (key_pressed === 4'b0010)
    );

    // Column 1011 decodes to key 0100.
    check_key_decode_col_1011: assert property (
        @(posedge clk) (col === 4'b1011) |=> (key_pressed === 4'b0100)
    );

    // Column 0111 decodes to key 1000.
    check_key_decode_col_0111: assert property (
        @(posedge clk) (col === 4'b0111) |=> (key_pressed === 4'b1000)
    );

    // Any other column pattern decodes to 0000.
    check_key_decode_default: assert property (
        @(posedge clk)
        ((col !== 4'b1110) && (col !== 4'b1101) && (col !== 4'b1011) && (col !== 4'b0111))
        |=> (key_pressed === 4'b0000)
    );

    // Decoded key is always one-hot or zero.
    check_key_pressed_legal_values: assert property (
        @(posedge clk) 1'b1 |=> (
            (key_pressed === 4'b0000) ||
            (key_pressed === 4'b0001) ||
            (key_pressed === 4'b0010) ||
            (key_pressed === 4'b0100) ||
            (key_pressed === 4'b1000)
        )
    );

    // Shifted key is the previous key rotated left by one bit.
    check_shifted_key_rotation: assert property (
        @(posedge clk) 1'b1 |=> (
            shifted_key_pressed === { $past(key_pressed[2:0]), $past(key_pressed[3]) }
        )
    );

    // Output low nibble captures the previous key code.
    check_out_lower_captures_previous_key: assert property (
        @(posedge clk) 1'b1 |=> (out[3:0] === $past(key_pressed))
    );

    // Output high nibble captures the previous shifted key code.
    check_out_upper_captures_previous_shift: assert property (
        @(posedge clk) 1'b1 |=> (out[7:4] === $past(shifted_key_pressed))
    );

endmodule

rtl:
module BCD_Converter (
  input [3:0] bin,
  output [3:0] bcd
);

  wire [3:0] temp;

  assign temp[3] = bin[3] & bin[2] & bin[1] & bin[0];
  assign temp[2] = (~bin[3] & bin[2] & bin[1] & bin[0]) | (bin[3] & ~bin[2] & bin[1] & bin[0]) | (bin[3] & bin[2] & ~bin[1] & bin[0]) | (bin[3] & bin[2] & bin[1] & ~bin[0]);
  assign temp[1] = (~bin[3] & ~bin[2] & bin[1] & bin[0]) | (bin[3] & ~bin[2] & ~bin[1] & bin[0]) | (bin[3] & bin[2] & ~bin[1] & ~bin[0]) | (~bin[3] & bin[2] & bin[1] & ~bin[0]);
  assign temp[0] = (~bin[3] & ~bin[2] & ~bin[1] & bin[0]) | (bin[3] & ~bin[2] & ~bin[1] & ~bin[0]) | (bin[3] & bin[2] & ~bin[1] & ~bin[0]) | (bin[3] & ~bin[2] & bin[1] & ~bin[0]);

  assign bcd = temp;

endmodule

sva:
module BCD_Converter_sva (
    input logic clk,
    input logic [3:0] bin,
    input logic [3:0] bcd
);

    // bcd[3] is high only for an all-ones input.
    check_bcd_bit3_all_ones: assert property (
        @(posedge clk)
        (bcd[3] == (bin == 4'b1111))
    );

    // bcd[2] is high for the four three-ones input patterns.
    check_bcd_bit2_three_high_patterns: assert property (
