            (bin == 4'b0111) ||
            (bin == 4'b1011) ||
            (bin == 4'b1101) ||
            (bin == 4'b1110)
        ))
    );

    // bcd[1] is high for the four patterns encoded by the RTL.
    check_bcd_bit1_selected_patterns: assert property (
        @(posedge clk)
        (bcd[1] == (
            (bin == 4'b0011) ||
            (bin == 4'b0110) ||
            (bin == 4'b1001) ||
            (bin == 4'b1100)
        ))
    );

    // bcd[0] is high for the four patterns encoded by the RTL.
    check_bcd_bit0_selected_patterns: assert property (
        @(posedge clk)
        (bcd[0] == (
            (bin == 4'b0001) ||
            (bin == 4'b1000) ||
            (bin == 4'b1010) ||
            (bin == 4'b1100)
        ))
    );

    // Inputs 0, 2, 4, and 5 produce a zero output.
    check_zero_output_cases: assert property (
        @(posedge clk)
        (
            (bin == 4'b0000) ||
            (bin == 4'b0010) ||
            (bin == 4'b0100) ||
            (bin == 4'b0101)
        ) |-> (bcd == 4'b0000)
    );

    // Inputs 1, 8, and 10 produce 0001.
    check_one_output_cases: assert property (
        @(posedge clk)
        (
            (bin == 4'b0001) ||
            (bin == 4'b1000) ||
            (bin == 4'b1010)
        ) |-> (bcd == 4'b0001)
    );

    // Inputs 3, 6, and 9 produce 0010.
    check_two_output_cases: assert property (
        @(posedge clk)
        (
            (bin == 4'b0011) ||
            (bin == 4'b0110) ||
            (bin == 4'b1001)
        ) |-> (bcd == 4'b0010)
    );

    // Inputs 7, 11, 13, and 14 produce 0100.
    check_four_output_cases: assert property (
        @(posedge clk)
        (
            (bin == 4'b0111) ||
            (bin == 4'b1011) ||
            (bin == 4'b1101) ||
            (bin == 4'b1110)
        ) |-> (bcd == 4'b0100)
    );

    // Input 12 is the only case that produces 0011.
    check_three_output_case: assert property (
        @(posedge clk)
        (bin == 4'b1100) |-> (bcd == 4'b0011)
    );

    // Input 15 produces 1000.
    check_eight_output_case: assert property (
        @(posedge clk)
        (bin == 4'b1111) |-> (bcd == 4'b1000)
    );

endmodule

rtl:
module priority_encoder (
    input [7:0] in,
    output reg [2:0] pos
);
    always @(*) begin
        case (in)
            8'b0000_0001: pos = 3'b000;
            8'b0000_0010: pos = 3'b001;
            8'b0000_0100: pos = 3'b010;
            8'b0000_1000: pos = 3'b011;
            8'b0001_0000: pos = 3'b100;
            8'b0010_0000: pos = 3'b101;
            8'b0100_0000: pos = 3'b110;
            default: pos = 3'b111;
        endcase
    end
endmodule
module adder (
    input [2:0] a,
    input [2:0] b,
    output reg [2:0] sum
);
    always @(*) begin
        sum = a - b;
    end
endmodule
module top_module (
    input [7:0] in1,
    input [7:0] in2,
    output [2:0] pos_diff // reg is removed.
);
    wire [2:0] pos1, pos2, add_output;

    priority_encoder pe1 (
        .in(in1),
        .pos(pos1)
    );

    priority_encoder pe2 (
        .in(in2),
        .pos(pos2)
    );

    adder add_inst (
        .a(pos1),
        .b(pos2),
        .sum(add_output)
    );

    assign pos_diff = add_output;
endmodule

sva:
module top_module_sva (
    input logic [7:0] in1,
    input logic [7:0] in2,
    input logic [2:0] pos_diff
);

    function automatic logic [2:0] encode_pos(input logic [7:0] in);
        begin
            case (in)
                8'b0000_0001: encode_pos = 3'b000;
                8'b0000_0010: encode_pos = 3'b001;
                8'b0000_0100: encode_pos = 3'b010;
                8'b0000_1000: encode_pos = 3'b011;
                8'b0001_0000: encode_pos = 3'b100;
                8'b0010_0000: encode_pos = 3'b101;
                8'b0100_0000: encode_pos = 3'b110;
                default:      encode_pos = 3'b111;
            endcase
        end
    endfunction

    function automatic logic [2:0] expected_diff(
        input logic [7:0] a,
        input logic [7:0] b
    );
        begin
            expected_diff = encode_pos(a) - encode_pos(b);
        end
    endfunction

    // Output matches the encoded-position difference for all inputs.
    check_pos_diff_matches_encoded_difference: assert property (
        @($global_clock) pos_diff == expected_diff(in1, in2)
    );

    // With in2 at position 0, bit 0 on in1 produces difference 0.
    check_in1_bit0_maps_to_zero: assert property (
        @($global_clock) (in2 == 8'b0000_0001 && in1 == 8'b0000_0001) |-> (pos_diff == 3'b000)
    );

    // With in2 at position 0, bit 1 on in1 produces difference 1.
    check_in1_bit1_maps_to_one: assert property (
        @($global_clock) (in2 == 8'b0000_0001 && in1 == 8'b0000_0010) |-> (pos_diff == 3'b001)
    );

    // With in2 at position 0, bit 2 on in1 produces difference 2.
    check_in1_bit2_maps_to_two: assert property (
        @($global_clock) (in2 == 8'b0000_0001 && in1 == 8'b0000_0100) |-> (pos_diff == 3'b010)
    );

    // With in2 at position 0, bit 3 on in1 produces difference 3.
    check_in1_bit3_maps_to_three: assert property (
        @($global_clock) (in2 == 8'b0000_0001 && in1 == 8'b0000_1000) |-> (pos_diff == 3'b011)
    );

    // With in2 at position 0, bit 4 on in1 produces difference 4.
    check_in1_bit4_maps_to_four: assert property (
        @($global_clock) (in2 == 8'b0000_0001 && in1 == 8'b0001_0000) |-> (pos_diff == 3'b100)
    );

    // With in2 at position 0, bit 5 on in1 produces difference 5.
    check_in1_bit5_maps_to_five: assert property (
        @($global_clock) (in2 == 8'b0000_0001 && in1 == 8'b0010_0000) |-> (pos_diff == 3'b101)
    );

    // With in2 at position 0, bit 6 on in1 produces difference 6.
    check_in1_bit6_maps_to_six: assert property (
        @($global_clock) (in2 == 8'b0000_0001 && in1 == 8'b0100_0000) |-> (pos_diff == 3'b110)
    );

    // With in2 at position 0, all other in1 values map to 7.
    check_in1_default_maps_to_seven: assert property (
        @($global_clock)
        (in2 == 8'b0000_0001 &&
         !(in1 == 8'b0000_0001 ||
           in1 == 8'b0000_0010 ||
           in1 == 8'b0000_0100 ||
           in1 == 8'b0000_1000 ||
           in1 == 8'b0001_0000 ||
           in1 == 8'b0010_0000 ||
           in1 == 8'b0100_0000)) |-> (pos_diff == 3'b111)
    );

    // With in1 at position 0, all other in2 values subtract as encoded 7.
    check_in2_default_maps_to_one: assert property (
        @($global_clock)
        (in1 == 8'b0000_0001 &&
         !(in2 == 8'b0000_0001 ||
           in2 == 8'b0000_0010 ||
           in2 == 8'b0000_0100 ||
           in2 == 8'b0000_1000 ||
           in2 == 8'b0001_0000 ||
           in2 == 8'b0010_0000 ||
           in2 == 8'b0100_0000)) |-> (pos_diff == 3'b001)
    );

endmodule

rtl:
module pipelined_xor_gate(input a, b, clk, output out);

reg a_reg, b_reg, a_reg1, b_reg1;
wire xor_out, xor_out1;

assign out = xor_out1;

// Pipeline stage 1
always @(posedge clk) begin
    a_reg1 <= a_reg;
    b_reg1 <= b_reg;
end

// Pipeline stage 2
always @(posedge clk) begin
    a_reg <= a;
    b_reg <= b;
end

// XOR gate
assign xor_out = a_reg ^ b_reg;
assign xor_out1 = a_reg1 ^ b_reg1;

endmodule

sva:
module pipelined_xor_gate_sva (
    input logic a,
    input logic b,
    input logic clk,
    input logic out,
    input logic a_reg,
    input logic b_reg,
    input logic a_reg1,
    input logic b_reg1,
    input logic xor_out,
    input logic xor_out1
);

    // Stage 2 captures input a on the previous clock.
    check_stage2_capture_a: assert property (
        @(posedge clk) (!$initstate && !$past($initstate)) |-> (a_reg == $past(a))
    );

    // Stage 2 captures input b on the previous clock.
    check_stage2_capture_b: assert property (
        @(posedge clk) (!$initstate && !$past($initstate)) |-> (b_reg == $past(b))
    );

    // Stage 1 captures the previous value of a_reg.
    check_stage1_capture_a: assert property (
        @(posedge clk) (!$initstate && !$past($initstate)) |-> (a_reg1 == $past(a_reg))
    );

    // Stage 1 captures the previous value of b_reg.
    check_stage1_capture_b: assert property (
        @(posedge clk) (!$initstate && !$past($initstate)) |-> (b_reg1 == $past(b_reg))
    );

    // xor_out is the XOR of the stage 2 registers.
    check_stage2_xor_logic: assert property (
        @(posedge clk) (xor_out == (a_reg ^ b_reg))
    );

    // xor_out1 is the XOR of the stage 1 registers.
    check_stage1_xor_logic: assert property (
        @(posedge clk) (xor_out1 == (a_reg1 ^ b_reg1))
    );

    // The module output is directly driven by xor_out1.
    check_output_connection: assert property (
        @(posedge clk) (out == xor_out1)
    );

    // The stage 1 XOR is the previous cycle's stage 2 XOR.
    check_xor_pipeline_delay: assert property (
        @(posedge clk) (!$initstate && !$past($initstate)) |-> (xor_out1 == $past(xor_out))
    );

    // Equal inputs produce a low output two clocks later.
    check_equal_inputs_drive_zero: assert property (
        @(posedge clk) (a == b) |=> ##1 (out == 1'b0)
    );

    // Different inputs produce a high output two clocks later.
    check_different_inputs_drive_one: assert property (
        @(posedge clk) (a != b) |=> ##1 (out == 1'b1)
    );

    // After pipeline fill, out matches the XOR of inputs from two clocks earlier.
    check_output_two_cycle_latency: assert property (
        @(posedge clk) (!$initstate && !$past($initstate) && !$past($initstate, 2)) |-> (out == ($past(a, 2) ^ $past(b, 2)))
    );

endmodule

rtl:
module smallest_number(
    input [3:0] A,
    input [3:0] B,
    input [3:0] C,
    output reg [3:0] smallest
);

always @(*) begin
    if (A <= B && A <= C) begin
        smallest = A;
    end else if (B <= A && B <= C) begin
        smallest = B;
    end else begin
        smallest = C;
    end
end

endmodule

sva:
module smallest_number_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] C,
    input logic [3:0] smallest
);

    // smallest must match the RTL's minimum-selection function.
    check_smallest_function: assert property (
        @($global_clock)
        smallest == ((A <= B && A <= C) ? A :
                     ((B <= A && B <= C) ? B : C))
    );

    // smallest must not be greater than A.
    check_smallest_le_a: assert property (
        @($global_clock)
        smallest <= A
    );

    // smallest must not be greater than B.
    check_smallest_le_b: assert property (
        @($global_clock)
        smallest <= B
    );

    // smallest must not be greater than C.
    check_smallest_le_c: assert property (
        @($global_clock)
        smallest <= C
    );

    // smallest must equal one of the three inputs.
    check_smallest_matches_input: assert property (
        @($global_clock)
        (smallest == A) || (smallest == B) || (smallest == C)
    );

    // If A is no larger than both others, smallest must equal A.
    check_select_a_when_a_is_min: assert property (
        @($global_clock)
        (A <= B && A <= C) |-> (smallest == A)
    );

    // If B is no larger than both others, smallest must equal B.
    check_select_b_when_b_is_min: assert property (
        @($global_clock)
        (B <= A && B <= C) |-> (smallest == B)
    );

    // If C is no larger than both others, smallest must equal C.
    check_select_c_when_c_is_min: assert property (
        @($global_clock)
        (C <= A && C <= B) |-> (smallest == C)
    );

endmodule

rtl:
module top_module (
    input CLK,
    input UP_DOWN,
    input RESET,
    input EN,
    input select,
    input [3:0] A,
    input [3:0] B,
    output [3:0] OUT1,
    output [7:0] OUT2
);

wire [3:0] counter_out;
wire [7:0] multiplier_out;

up_down_counter udc (
    .CLK(CLK),
    .UP_DOWN(UP_DOWN),
    .RESET(RESET),
    .EN(EN),
    .OUT(counter_out)
);

binary_multiplier bm (
    .A(select ? A : B),
    .B(select ? B : A),
    .OUT(multiplier_out)
);

assign OUT1 = counter_out;
assign OUT2 = multiplier_out;

endmodule

module up_down_counter (
    input CLK,
    input UP_DOWN,
    input RESET,
    input EN,
    output [3:0] OUT
);

reg [3:0] count;

always @(posedge CLK or posedge RESET) begin
    if (RESET) begin
        count <= 4'b0;
    end else if (EN) begin
        count <= UP_DOWN ? count + 4'b1 : count - 4'b1;
    end
end

assign OUT = count;

endmodule

module binary_multiplier (
    input [3:0] A,
    input [3:0] B,
    output [7:0] OUT
);

assign OUT = A * B;

endmodule

sva:
module top_module_sva (
    input logic CLK,
    input logic UP_DOWN,
    input logic RESET,
    input logic EN,
    input logic select,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] OUT1,
    input logic [7:0] OUT2
);

    // After a sampled reset, the counter output is zero on the next clock.
    check_counter_clears_after_reset: assert property (
        @(posedge CLK) RESET |=> (OUT1 == 4'h0)
    );

    // A zero counter value stays at zero when counting is disabled.
    check_counter_zero_holds_when_disabled: assert property (
        @(posedge CLK) disable iff (RESET)
        (!EN && (OUT1 == 4'h0)) |=> (OUT1 == 4'h0)
    );

    // Incrementing from 4'hF wraps the 4-bit counter back to zero.
    check_counter_wraps_on_increment_from_max: assert property (
        @(posedge CLK) disable iff (RESET)
        (EN && UP_DOWN && (OUT1 == 4'hF)) |=> (OUT1 == 4'h0)
    );

    // OUT2 always equals the product of A and B.
    check_multiplier_matches_ab_product: assert property (
        @(posedge CLK) disable iff (RESET)
        (OUT2 == (A * B))
    );

    // A zero multiplier operand forces the product to zero.
    check_multiplier_zero_operand_gives_zero: assert property (
        @(posedge CLK) disable iff (RESET)
        ((A == 4'h0) || (B == 4'h0)) |-> (OUT2 == 8'h00)
    );

    // A value of one on A passes B through the multiplier.
    check_multiplier_a_one_passes_b: assert property (
        @(posedge CLK) disable iff (RESET)
        (A == 4'h1) |-> (OUT2 == {4'b0000, B})
    );

    // A value of one on B passes A through the multiplier.
    check_multiplier_b_one_passes_a: assert property (
        @(posedge CLK) disable iff (RESET)
        (B == 4'h1) |-> (OUT2 == {4'b0000, A})
    );

    // Changing select alone does not change the product.
    check_select_change_does_not_change_product: assert property (
        @(posedge CLK) disable iff (RESET)
        ($changed(select) && $stable(A) && $stable(B)) |-> (OUT2 == $past(OUT2))
    );

endmodule

rtl:
module four_bit_adder (
    A,
    B,
    CI,
    SUM,
    COUT
);

    input [3:0] A;
    input [3:0] B;
    input CI;
    output [3:0] SUM;
    output COUT;

    wire [3:0] a_xor_b;
    wire [3:0] a_xor_b_xor_ci;
    wire [3:0] a_and_b;
    wire [3:0] a_and_b_and_ci;
    wire [3:0] a_or_b;
    wire [3:0] a_or_b_or_ci;
    wire a_xor_b_xor_ci_xor_cout;

    // Implement the adder logic using only the allowed gates and the named wires
    xor xor0 (a_xor_b[0], A[0], B[0]);
    xor xor1 (a_xor_b[1], A[1], B[1]);
    xor xor2 (a_xor_b[2], A[2], B[2]);
    xor xor3 (a_xor_b[3], A[3], B[3]);

    xor xor4 (a_xor_b_xor_ci[0], a_xor_b[0], CI);
    xor xor5 (a_xor_b_xor_ci[1], a_xor_b[1], CI);
    xor xor6 (a_xor_b_xor_ci[2], a_xor_b[2], CI);
    xor xor7 (a_xor_b_xor_ci[3], a_xor_b[3], CI);

    and and0 (a_and_b[0], A[0], B[0]);
    and and1 (a_and_b[1], A[1], B[1]);
    and and2 (a_and_b[2], A[2], B[2]);
    and and3 (a_and_b[3], A[3], B[3]);

    and and4 (a_and_b_and_ci[0], a_and_b[0], CI);
    and and5 (a_and_b_and_ci[1], a_and_b[1], CI);
    and and6 (a_and_b_and_ci[2], a_and_b[2], CI);
    and and7 (a_and_b_and_ci[3], a_and_b[3], CI);

    or or0 (a_or_b[0], A[0], B[0]);
    or or1 (a_or_b[1], A[1], B[1]);
    or or2 (a_or_b[2], A[2], B[2]);
    or or3 (a_or_b[3], A[3], B[3]);

    or or4 (a_or_b_or_ci[0], a_or_b[0], CI);
    or or5 (a_or_b_or_ci[1], a_or_b[1], CI);
    or or6 (a_or_b_or_ci[2], a_or_b[2], CI);
    or or7 (a_or_b_or_ci[3], a_or_b[3], CI);

    xor xor8 (a_xor_b_xor_ci_xor_cout, a_xor_b_xor_ci[3], a_and_b_and_ci[3]);

    // Assign the output ports
    assign SUM = a_xor_b_xor_ci;
    assign COUT = a_xor_b_xor_ci_xor_cout;

endmodule

sva:
module four_bit_adder_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic CI,
    input logic [3:0] SUM,
    input logic COUT
);

    // External sampling clock; RTL has no clock or reset.

    // SUM must match the implemented bitwise XOR with replicated CI.
    check_sum_vector: assert property (
        @(posedge clk) SUM == (A ^ B ^ {4{CI}})
    );

    // SUM[0] is A[0] xor B[0] xor CI.
    check_sum_bit0: assert property (
        @(posedge clk) SUM[0] == (A[0] ^ B[0] ^ CI)
    );

    // SUM[1] is A[1] xor B[1] xor CI.
    check_sum_bit1: assert property (
        @(posedge clk) SUM[1] == (A[1] ^ B[1] ^ CI)
    );

    // SUM[2] is A[2] xor B[2] xor CI.
    check_sum_bit2: assert property (
        @(posedge clk) SUM[2] == (A[2] ^ B[2] ^ CI)
    );

    // SUM[3] is A[3] xor B[3] xor CI.
    check_sum_bit3: assert property (
        @(posedge clk) SUM[3] == (A[3] ^ B[3] ^ CI)
    );

    // COUT must match the implemented relation to SUM[3].
    check_cout_from_sum_msb: assert property (
        @(posedge clk) COUT == (SUM[3] ^ (A[3] & B[3] & CI))
    );

    // COUT must match the exact implemented MSB equation.
    check_cout_function: assert property (
        @(posedge clk) COUT == (A[3] ^ B[3] ^ CI ^ (A[3] & B[3] & CI))
    );

    // With CI low, SUM reduces to A xor B.
    check_sum_ci_low: assert property (
        @(posedge clk) (!CI) |-> (SUM == (A ^ B))
    );

    // With CI high, SUM reduces to bitwise complement of A xor B.
    check_sum_ci_high: assert property (
        @(posedge clk) CI |-> (SUM == ~(A ^ B))
    );

    // With CI low, COUT reduces to the MSB xor.
    check_cout_ci_low: assert property (
        @(posedge clk) (!CI) |-> (COUT == (A[3] ^ B[3]))
    );

    // With CI high, COUT is high only when both MSB inputs are low.
    check_cout_ci_high: assert property (
        @(posedge clk) CI |-> (COUT == ~(A[3] | B[3]))
    );

endmodule

rtl:
module Mealy(
  input in,
  output reg out
);

parameter n = 4; // number of states

// Define states
parameter s0 = 0;
parameter s1 = 1;
parameter s2 = 2;
parameter s3 = 3;

reg [1:0] state; // state register

// Define transition conditions
always @(posedge in or negedge out) begin
  if (!out) state <= s0;
  else begin
    case (state)
      s0: if (in) state <= s1; else state <= s2;
      s1: if (in) state <= s3; else state <= s0;
      s2: if (in) state <= s0; else state <= s3;
      s3: if (in) state <= s2; else state <= s1;
    endcase
  end
end

// Define output function
always @(posedge in or negedge out) begin
  if (!out) out <= 1'b0;
  else begin
    case (state)
      s0: out <= 1'b0;
      s1: out <= 1'b1;
      s2: out <= in;
      s3: out <= ~in;
    endcase
  end
end

endmodule

sva:
module Mealy_sva (
    input logic       in,
    input logic       out,
    input logic [1:0] state
);

    localparam logic [1:0] s0 = 2'd0;
    localparam logic [1:0] s1 = 2'd1;
    localparam logic [1:0] s2 = 2'd2;
    localparam logic [1:0] s3 = 2'd3;

    // Low out is absorbing and drives the state back to s0.
    check_low_out_sticks_and_resets_state: assert property (
        @(posedge in) !out |=> (!out && (state == s0))
    );

    // From s0 with out high, the next sampled state is s0 with out low.
    check_s0_drops_out_and_resets_state: assert property (
        @(posedge in) (out && (state == s0)) |=> (!out && (state == s0))
    );

    // From s3 with out high, the next sampled state is s0 with out low.
    check_s3_drops_out_and_resets_state: assert property (
        @(posedge in) (out && (state == s3)) |=> (!out && (state == s0))
    );

    // From s1 with out high, one input edge later the machine is in s3 and out stays high.
    check_s1_steps_to_s3_with_out_high: assert property (
        @(posedge in) disable iff (!out) (out && (state == s1)) |=> (out && (state == s3))
    );

    // From s2 with out high, one input edge later the machine is in s0 and out stays high.
    check_s2_steps_to_s0_with_out_high: assert property (
        @(posedge in) disable iff (!out) (out && (state == s2)) |=> (out && (state == s0))
    );

    // From s1 with out high, the machine reaches low out and s0 within two input edges.
    check_s1_reaches_low_out_in_two_edges: assert property (
        @(posedge in) (out && (state == s1)) |=> (out && (state == s3)) ##1 (!out && (state == s0))
    );

    // From s2 with out high, the machine reaches low out and s0 within two input edges.
    check_s2_reaches_low_out_in_two_edges: assert property (
        @(posedge in) (out && (state == s2)) |=> (out && (state == s0)) ##1 (!out && (state == s0))
    );

endmodule

rtl:
module logic_gate(
    input A1,
    input [1:0] select,
    input A2,
    input A3,
    input B1,
    input C1,
    input reset,
    output reg X,
    output reg valid
);

always @(A1, select, A2, A3, B1, C1, reset) begin
    if(reset) begin
        X <= 1'b0;
        valid <= 1'b0;
    end else begin
        if(select == 2'b00) begin
            if(A1 && A2 && A3) begin
                X <= 1'b1;
                valid <= 1'b1;
            end else begin
                X <= 1'b0;
                valid <= 1'b0;
            end
        end else begin
            if(A1 && B1 && C1) begin
                X <= 1'b1;
                valid <= 1'b1;
            end else begin
                X <= 1'b0;
                valid <= 1'b0;
            end
        end
    end
end

endmodule

sva:
module logic_gate_sva (
    input logic clk,
    input logic A1,
    input logic [1:0] select,
    input logic A2,
    input logic A3,
    input logic B1,
    input logic C1,
    input logic reset,
    input logic X,
    input logic valid
);

    // Reset forces both outputs low.
    check_reset_clears_outputs: assert property (
        @(posedge clk) disable iff (!reset)
            (X == 1'b0 && valid == 1'b0)
    );

    // Outside reset, X and valid always match.
    check_outputs_match: assert property (
        @(posedge clk) disable iff (reset)
            (X == valid)
    );

    // With select set to 00, all A inputs high drives both outputs high.
    check_select00_all_high_sets_outputs: assert property (
        @(posedge clk) disable iff (reset)
            ((select == 2'b00) && A1 && A2 && A3) |-> (X == 1'b1 && valid == 1'b1)
    );

    // With select set to 00, any low A input drives both outputs low.
    check_select00_missing_input_clears_outputs: assert property (
        @(posedge clk) disable iff (reset)
            ((select == 2'b00) && !(A1 && A2 && A3)) |-> (X == 1'b0 && valid == 1'b0)
    );

    // With select not equal to 00, A1/B1/C1 high drives both outputs high.
    check_select_nonzero_all_high_sets_outputs: assert property (
        @(posedge clk) disable iff (reset)
            (((select == 2'b01) || (select == 2'b10) || (select == 2'b11)) && A1 && B1 && C1)
            |-> (X == 1'b1 && valid == 1'b1)
    );

    // With select not equal to 00, any low selected input drives both outputs low.
    check_select_nonzero_missing_input_clears_outputs: assert property (
        @(posedge clk) disable iff (reset)
            (((select == 2'b01) || (select == 2'b10) || (select == 2'b11)) && !(A1 && B1 && C1))
            |-> (X == 1'b0 && valid == 1'b0)
    );

endmodule

rtl:
module emesh_if (
   cmesh_ready_out, cmesh_access_out, cmesh_packet_out,
   rmesh_ready_out, rmesh_access_out, rmesh_packet_out,
   xmesh_ready_out, xmesh_access_out, xmesh_packet_out,
   emesh_ready_out, emesh_access_out, emesh_packet_out,
   cmesh_access_in, cmesh_packet_in, cmesh_ready_in, rmesh_access_in,
   rmesh_packet_in, rmesh_ready_in, xmesh_access_in, xmesh_packet_in,
   xmesh_ready_in, emesh_access_in, emesh_packet_in, emesh_ready_in
   );

   parameter AW   = 32;   
   parameter PW   = 2*AW+40; 

   input 	   cmesh_access_in;
   input [PW-1:0]  cmesh_packet_in;
   output 	   cmesh_ready_out;
   output 	   cmesh_access_out;
   output [PW-1:0] cmesh_packet_out;
   input 	   cmesh_ready_in;

   input 	   rmesh_access_in;
   input [PW-1:0]  rmesh_packet_in;
   output 	   rmesh_ready_out;
   output 	   rmesh_access_out;
   output [PW-1:0] rmesh_packet_out;
   input 	   rmesh_ready_in;

   input 	   xmesh_access_in;
   input [PW-1:0]  xmesh_packet_in;
   output 	   xmesh_ready_out;  
   output 	   xmesh_access_out;
   output [PW-1:0] xmesh_packet_out;
   input 	   xmesh_ready_in;

   input 	   emesh_access_in;
   input [PW-1:0]  emesh_packet_in;
   output 	   emesh_ready_out;

   output 	   emesh_access_out;
   output [PW-1:0] emesh_packet_out;
   input 	   emesh_ready_in;

   assign cmesh_access_out = emesh_access_in & emesh_packet_in[0];

   assign rmesh_access_out = emesh_access_in & ~emesh_packet_in[0];

   assign xmesh_access_out = 1'b0;

   assign cmesh_packet_out[PW-1:0] = emesh_packet_in[PW-1:0];	 
   assign rmesh_packet_out[PW-1:0] = emesh_packet_in[PW-1:0];	 
   assign xmesh_packet_out[PW-1:0] = emesh_packet_in[PW-1:0];


   assign emesh_ready_out = cmesh_ready_in &
			    rmesh_ready_in &
			    xmesh_ready_in;

   assign emesh_access_out = cmesh_access_in &
			     rmesh_access_in &
			     xmesh_access_in;


   assign emesh_packet_out[PW-1:0] = cmesh_access_in ? cmesh_packet_in[PW-1:0] :
				     rmesh_access_in ? rmesh_packet_in[PW-1:0] :
				                       xmesh_packet_in[PW-1:0];

   assign cmesh_ready_out = ~(cmesh_access_in & ~emesh_ready_in);


   assign rmesh_ready_out = ~(rmesh_access_in & 
			    (~emesh_ready_in | ~cmesh_ready_in));

   assign xmesh_ready_out = ~(xmesh_access_in & 
			      (~emesh_ready_in | ~cmesh_access_in | ~rmesh_access_in));


endmodule

sva:
module emesh_if_sva #(
    parameter AW = 32,
    parameter PW = 2*AW+40
) (
    input logic          clk,
    input logic          cmesh_ready_out,
    input logic          cmesh_access_out,
    input logic [PW-1:0] cmesh_packet_out,
    input logic          rmesh_ready_out,
    input logic          rmesh_access_out,
    input logic [PW-1:0] rmesh_packet_out,
    input logic          xmesh_ready_out,
    input logic          xmesh_access_out,
    input logic [PW-1:0] xmesh_packet_out,
    input logic          emesh_ready_out,
    input logic          emesh_access_out,
    input logic [PW-1:0] emesh_packet_out,
    input logic          cmesh_access_in,
    input logic [PW-1:0] cmesh_packet_in,
    input logic          cmesh_ready_in,
    input logic          rmesh_access_in,
    input logic [PW-1:0] rmesh_packet_in,
    input logic          rmesh_ready_in,
    input logic          xmesh_access_in,
    input logic [PW-1:0] xmesh_packet_in,
    input logic          xmesh_ready_in,
    input logic          emesh_access_in,
    input logic [PW-1:0] emesh_packet_in,
    input logic          emesh_ready_in
);

    // cmesh access is selected when emesh is active and packet bit 0 is set.
    check_cmesh_access_decode: assert property (
        @(posedge clk)
        cmesh_access_out == (emesh_access_in & emesh_packet_in[0])
    );

    // rmesh access is selected when emesh is active and packet bit 0 is clear.
    check_rmesh_access_decode: assert property (
        @(posedge clk)
        rmesh_access_out == (emesh_access_in & ~emesh_packet_in[0])
    );

    // xmesh access output is permanently tied low.
    check_xmesh_access_tied_low: assert property (
        @(posedge clk)
        xmesh_access_out == 1'b0
    );

    // cmesh packet output mirrors the emesh packet input.
    check_cmesh_packet_forward: assert property (
        @(posedge clk)
        cmesh_packet_out == emesh_packet_in
    );

    // rmesh packet output mirrors the emesh packet input.
    check_rmesh_packet_forward: assert property (
        @(posedge clk)
        rmesh_packet_out == emesh_packet_in
    );

    // xmesh packet output mirrors the emesh packet input.
    check_xmesh_packet_forward: assert property (
        @(posedge clk)
        xmesh_packet_out == emesh_packet_in
    );

    // emesh ready is the AND of all downstream ready inputs.
    check_emesh_ready_and: assert property (
        @(posedge clk)
        emesh_ready_out == (cmesh_ready_in & rmesh_ready_in & xmesh_ready_in)
    );

    // emesh access out is the AND of all mesh access inputs.
    check_emesh_access_and: assert property (
        @(posedge clk)
        emesh_access_out == (cmesh_access_in & rmesh_access_in & xmesh_access_in)
    );

    // emesh packet out follows the documented priority mux.
    check_emesh_packet_priority_mux: assert property (
        @(posedge clk)
        emesh_packet_out == (cmesh_access_in ? cmesh_packet_in :
                             rmesh_access_in ? rmesh_packet_in :
                                               xmesh_packet_in)
    );

    // cmesh ready deasserts only when cmesh is accessing and emesh is not ready.
    check_cmesh_ready_backpressure: assert property (
        @(posedge clk)
        cmesh_ready_out == ~(cmesh_access_in & ~emesh_ready_in)
    );

    // rmesh ready deasserts only under the implemented rmesh backpressure condition.
    check_rmesh_ready_backpressure: assert property (
        @(posedge clk)
        rmesh_ready_out == ~(rmesh_access_in & (~emesh_ready_in | ~cmesh_ready_in))
    );

    // xmesh ready deasserts only under the implemented xmesh backpressure condition.
    check_xmesh_ready_backpressure: assert property (
        @(posedge clk)
        xmesh_ready_out == ~(xmesh_access_in & (~emesh_ready_in | ~cmesh_access_in | ~rmesh_access_in))
    );

endmodule

rtl:
module karnaugh_map(
  input wire A, B, C, D,
  output wire F
);

  // Simplified Boolean expression
  assign F = !A && (B || C);

endmodule

sva:
module karnaugh_map_sva (
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic F
);

    // F must match the implemented Boolean expression.
    check_f_matches_expression: assert property (
        @($global_clock) F == (!A && (B || C))
    );

    // A high forces F low.
    check_a_high_forces_f_low: assert property (
        @($global_clock) A |-> !F
    );

    // With A low, either B or C high forces F high.
    check_b_or_c_with_a_low_sets_f: assert property (
        @($global_clock) (!A && (B || C)) |-> F
    );

    // With B and C both low, F must be low.
    check_both_b_and_c_low_clear_f: assert property (
        @($global_clock) (!B && !C) |-> !F
    );

    // If A, B, and C do not change, F must not change.
    check_f_depends_only_on_a_b_c: assert property (
        @($global_clock) ($stable(A) && $stable(B) && $stable(C)) |-> $stable(F)
    );

    // If only D changes, F must remain stable.
    check_d_change_does_not_affect_f: assert property (
        @($global_clock) ($changed(D) && $stable(A) && $stable(B) && $stable(C)) |-> $stable(F)
    );

endmodule

rtl:
module math_op(
    input [7:0] a,
    input [7:0] b,
    input [1:0] op,
    output reg [7:0] result
);

always @(*) begin
    case (op)
        2'b00: result = a + b;
        2'b01: result = a - b;
        2'b10: result = a * b;
        2'b11: begin
            if (b == 0) begin
                result = 8'd0;
            end else begin
                result = a / b;
            end
        end
    endcase
end

endmodule

sva:
module math_op_sva (
    input logic clk,
    input logic [7:0] a,
    input logic [7:0] b,
    input logic [1:0] op,
    input logic [7:0] result
);

    typedef logic [7:0] byte_t;

    // Addition mode returns the 8-bit sum of a and b.
    check_add_result: assert property (
        @(posedge clk) (op == 2'b00) |-> (result == byte_t'(a + b))
    );

    // Subtraction mode returns the 8-bit difference of a and b.
    check_sub_result: assert property (
        @(posedge clk) (op == 2'b01) |-> (result == byte_t'(a - b))
    );

    // Multiplication mode returns the low 8 bits of the product.
    check_mul_result: assert property (
        @(posedge clk) (op == 2'b10) |-> (result == byte_t'(a * b))
    );

    // Division by zero forces the result to zero.
    check_div_by_zero_result: assert property (
        @(posedge clk) ((op == 2'b11) && (b == 8'd0)) |-> (result == 8'd0)
    );

    // Division mode returns the 8-bit quotient when b is nonzero.
    check_div_result: assert property (
        @(posedge clk) ((op == 2'b11) && (b != 8'd0)) |-> (result == byte_t'(a / b))
    );

endmodule

rtl:
module clock_generator(
    input clk_in,
    output reg clk_out
);

reg [23:0] counter;

always @(posedge clk_in) begin
    if(counter == 24'd4_999_999) begin
        counter <= 0;
        clk_out <= ~clk_out;
    end else begin
        counter <= counter + 1;
    end
end

endmodule

sva:
module clock_generator_sva (
    input logic clk_in,
    input logic clk_out,
    input logic [23:0] counter
);

localparam logic [23:0] TERMINAL_COUNT = 24'd4_999_999;

// Counter wraps to zero after the terminal count.
check_counter_wrap: assert property (
    @(posedge clk_in) disable iff (1'b0)
    (counter == TERMINAL_COUNT) |=> (counter == 24'd0)
);

// clk_out toggles when the terminal count is reached.
check_clk_out_toggle_on_wrap: assert property (
    @(posedge clk_in) disable iff (1'b0)
    (counter == TERMINAL_COUNT) |=> (clk_out != $past(clk_out))
);

// Counter increments by one on all non-terminal cycles.
check_counter_increment_otherwise: assert property (
    @(posedge clk_in) disable iff (1'b0)
    (counter != TERMINAL_COUNT) |=> (counter == ($past(counter) + 24'd1))
);

// clk_out holds its value on all non-terminal cycles.
check_clk_out_hold_otherwise: assert property (
    @(posedge clk_in) disable iff (1'b0)
    (counter != TERMINAL_COUNT) |=> (clk_out == $past(clk_out))
);

endmodule

rtl:
module latch (E, SE, CK, ECK);
  input E, SE, CK;
  output ECK;

  reg D;

  always @(posedge CK) begin
    if (E & SE) begin
      D <= 1;
    end else if (~E & SE) begin
      D <= 0;
    end
  end

  assign ECK = D;
endmodule

module clock_gate (CLK, EN, TE, ENCLK);
  input CLK, EN, TE;
  output ENCLK;

  reg D;
  wire G;

  assign G = EN & TE;
  always @(posedge CLK) begin
    if (G) begin
      D <= 1;
    end else begin
      D <= 0;
    end
  end

  latch latch_instance (.E(EN), .SE(TE), .CK(CLK), .ECK(ENCLK));

endmodule

sva:
module latch_sva (
    input logic E,
    input logic SE,
    input logic CK,
    input logic ECK
);

    // When SE is high and E is high, ECK is set on the next clock.
    latch_set_when_se_and_e_high: assert property (
        @(posedge CK) (SE && E) |=> (ECK == 1'b1)
    );

    // When SE is high and E is low, ECK is cleared on the next clock.
    latch_clear_when_se_high_and_e_low: assert property (
        @(posedge CK) (SE && !E) |=> (ECK == 1'b0)
    );

    // When SE is low, ECK holds its value across clocks.
    latch_hold_when_se_low: assert property (
        @(posedge CK) (!SE) |=> $stable(ECK)
    );

endmodule

module clock_gate_sva (
    input logic CLK,
    input logic EN,
    input logic TE,
    input logic ENCLK
);

    // When TE is high and EN is high, ENCLK is set on the next clock.
    clock_gate_set_when_te_and_en_high: assert property (
        @(posedge CLK) (TE && EN) |=> (ENCLK == 1'b1)
    );

    // When TE is high and EN is low, ENCLK is cleared on the next clock.
    clock_gate_clear_when_te_high_and_en_low: assert property (
        @(posedge CLK) (TE && !EN) |=> (ENCLK == 1'b0)
    );

    // When TE is low, ENCLK holds its value across clocks.
    clock_gate_hold_when_te_low: assert property (
        @(posedge CLK) (!TE) |=> $stable(ENCLK)
    );

endmodule

module FSM_assertions #(
    parameter n = 4,
    parameter m = 2,
    parameter s = 8,
    parameter t = 12
) (
    input logic [n-1:0] in,
    input logic [m-1:0] out,
    input logic [s-1:0] state
);

    localparam logic [s-1:0] ST0 = {{(s-3){1'b0}}, 3'b000};
    localparam logic [s-1:0] ST1 = {{(s-3){1'b0}}, 3'b001};
    localparam logic [s-1:0] ST2 = {{(s-3){1'b0}}, 3'b010};
    localparam logic [s-1:0] ST3 = {{(s-3){1'b0}}, 3'b011};
    localparam logic [s-1:0] ST4 = {{(s-3){1'b0}}, 3'b100};
    localparam logic [s-1:0] ST5 = {{(s-3){1'b0}}, 3'b101};
    localparam logic [s-1:0] ST6 = {{(s-3){1'b0}}, 3'b110};
    localparam logic [s-1:0] ST7 = {{(s-3){1'b0}}, 3'b111};

    // State and output only change when the input vector changes.
    check_hold_when_input_stable: assert property (
        @($global_clock) disable iff ($initstate)
        $stable(in) |-> ($stable(state) && $stable(out))
    );

    // An invalid state encoding causes no assignment because there is no default case.
    check_invalid_state_holds_on_input_change: assert property (
        @($global_clock) disable iff ($initstate)
        ($changed(in) &&
         ($past(state) != ST0) && ($past(state) != ST1) &&
         ($past(state) != ST2) && ($past(state) != ST3) &&
         ($past(state) != ST4) && ($past(state) != ST5) &&
         ($past(state) != ST6) && ($past(state) != ST7))
        |-> ($stable(state) && $stable(out))
    );

    // In states 0 or 1, in[0]&in[1] leads to state 1 with output 10.
    check_state01_cond_ab: assert property (
        @($global_clock) disable iff ($initstate)
        ($changed(in) &&
         (($past(state) == ST0) || ($past(state) == ST1)) &&
         in[0] && in[1])
        |-> ((state == ST1) && (out == 2'b10))
    );

    // In states 2 or 3, in[0]&in[1] leads to state 3 with output 10.
    check_state23_cond_ab: assert property (
        @($global_clock) disable iff ($initstate)
        ($changed(in) &&
         (($past(state) == ST2) || ($past(state) == ST3)) &&
         in[0] && in[1])
        |-> ((state == ST3) && (out == 2'b10))
    );

    // In states 0, 2, or 3, in[2] without in[0]&in[1] leads to state 2 with output 01.
    check_state023_cond_c: assert property (
        @($global_clock) disable iff ($initstate)
        ($changed(in) &&
         (($past(state) == ST0) || ($past(state) == ST2) || ($past(state) == ST3)) &&
         !(in[0] && in[1]) && in[2])
        |-> ((state == ST2) && (out == 2'b01))
    );

    // In state 1, in[2] without in[0]&in[1] leads to state 3 with output 01.
    check_state1_cond_c: assert property (
        @($global_clock) disable iff ($initstate)
        ($changed(in) &&
         ($past(state) == ST1) &&
         !(in[0] && in[1]) && in[2])
        |-> ((state == ST3) && (out == 2'b01))
    );

    // In states 0, 1, or 2, neither condition leads to state 0 with output 00.
    check_state012_else: assert property (
        @($global_clock) disable iff ($initstate)
        ($changed(in) &&
         (($past(state) == ST0) || ($past(state) == ST1) || ($past(state) == ST2)) &&
         !(in[0] && in[1]) && !in[2])
        |-> ((state == ST0) && (out == 2'b00))
    );

    // In state 3, neither condition leads to state 1 with output 00.
    check_state3_else: assert property (
        @($global_clock) disable iff ($initstate)
        ($changed(in) &&
         ($past(state) == ST3) &&
         !(in[0] && in[1]) && !in[2])
        |-> ((state == ST1) && (out == 2'b00))
    );

    // In states 4 or 5, in[1]&in[3] leads to state 5 with output 10.
    check_state45_cond_bd: assert property (
        @($global_clock) disable iff ($initstate)
        ($changed(in) &&
         (($past(state) == ST4) || ($past(state) == ST5)) &&
         in[1] && in[3])
        |-> ((state == ST5) && (out == 2'b10))
    );

    // In states 6 or 7, in[1]&in[3] leads to state 7 with output 10.
    check_state67_cond_bd: assert property (
        @($global_clock) disable iff ($initstate)
        ($changed(in) &&
         (($past(state) == ST6) || ($past(state) == ST7)) &&
         in[1] && in[3])
        |-> ((state == ST7) && (out == 2'b10))
    );

    // In states 4, 6, or 7, in[0] without in[1]&in[3] leads to state 6 with output 01.
    check_state467_cond_a: assert property (
        @($global_clock) disable iff ($initstate)
        ($changed(in) &&
         (($past(state) == ST4) || ($past(state) == ST6) || ($past(state) == ST7)) &&
         !(in[1] && in[3]) && in[0])
        |-> ((state == ST6) && (out == 2'b01))
    );

    // In state 5, in[0] without in[1]&in[3] leads to state 7 with output 01.
    check_state5_cond_a: assert property (
        @($global_clock) disable iff ($initstate)
        ($changed(in) &&
         ($past(state) == ST5) &&
         !(in[1] && in[3]) && in[0])
        |-> ((state == ST7) && (out == 2'b01))
    );

    // In states 4, 5, or 6, neither condition leads to state 4 with output 00.
    check_state456_else: assert property (
        @($global_clock) disable iff ($initstate)
        ($changed(in) &&
         (($past(state) == ST4) || ($past(state) == ST5) || ($past(state) == ST6)) &&
         !(in[1] && in[3]) && !in[0])
        |-> ((state == ST4) && (out == 2'b00))
    );

    // In state 7, neither condition leads to state 5 with output 00.
    check_state7_else: assert property (
        @($global_clock) disable iff ($initstate)
        ($changed(in) &&
         ($past(state) == ST7) &&
         !(in[1] && in[3]) && !in[0])
        |-> ((state == ST5) && (out == 2'b00))
    );

endmodule

rtl:
module Deco_Round_Mult(
	input wire [1:0] round_mode,
	input wire or_info, input wire xor_info, output reg ctrl );

wire round_ok;

always @*
  case ({xor_info,or_info,round_mode})
 4'b0101: ctrl <= 1'b0;

	4'b1101: ctrl <= 1'b1;

4'b0110: ctrl <= 1'b1;

	4'b1110: ctrl <= 1'b0;

   default: ctrl <= 1'b0; endcase

endmodule

sva:
module Deco_Round_Mult_sva (
    input logic       clk,
    input logic [1:0] round_mode,
    input logic       or_info,
    input logic       xor_info,
    input logic       ctrl
);

    // 0101 decodes ctrl low.
    check_case_0101_ctrl_low: assert property (
        @(posedge clk)
        ({xor_info, or_info, round_mode} == 4'b0101) |-> (ctrl == 1'b0)
    );

    // 1101 decodes ctrl high.
    check_case_1101_ctrl_high: assert property (
        @(posedge clk)
        ({xor_info, or_info, round_mode} == 4'b1101) |-> (ctrl == 1'b1)
    );

    // 0110 decodes ctrl high.
    check_case_0110_ctrl_high: assert property (
        @(posedge clk)
        ({xor_info, or_info, round_mode} == 4'b0110) |-> (ctrl == 1'b1)
    );

    // 1110 decodes ctrl low.
    check_case_1110_ctrl_low: assert property (
        @(posedge clk)
        ({xor_info, or_info, round_mode} == 4'b1110) |-> (ctrl == 1'b0)
    );

    // All unspecified input combinations drive ctrl low.
    check_default_ctrl_low: assert property (
        @(posedge clk)
        (({xor_info, or_info, round_mode} != 4'b0101) &&
         ({xor_info, or_info, round_mode} != 4'b1101) &&
         ({xor_info, or_info, round_mode} != 4'b0110) &&
         ({xor_info, or_info, round_mode} != 4'b1110)) |-> (ctrl == 1'b0)
    );

    // ctrl can only be high for the two explicit high-output cases.
    check_ctrl_high_only_on_explicit_high_cases: assert property (
        @(posedge clk)
        ctrl |-> (({xor_info, or_info, round_mode} == 4'b1101) ||
                  ({xor_info, or_info, round_mode} == 4'b0110))
    );

    // ctrl exactly matches the case decode.
    check_ctrl_matches_case_decode: assert property (
        @(posedge clk)
        ctrl == ((({xor_info, or_info, round_mode} == 4'b1101) ||
                  ({xor_info, or_info, round_mode} == 4'b0110)) ? 1'b1 : 1'b0)
    );

endmodule

rtl:
module shift_register (Clock, ALOAD, D, SO);
  input [8:0] D;
  input Clock, ALOAD;
  output reg SO;
  reg [8:0] tmp;
  wire n22;

  // D flip-flops to store the input data
  always@(posedge Clock)
  begin
    tmp[8] <= tmp[7];
    tmp[7] <= tmp[6];
    tmp[6] <= tmp[5];
    tmp[5] <= tmp[4];
    tmp[4] <= tmp[3];
    tmp[3] <= tmp[2];
    tmp[2] <= tmp[1];
    tmp[1] <= tmp[0];
    tmp[0] <= D[0];
  end

  // Perform the shift operation
  always@(posedge Clock)
  begin  
    SO <= (ALOAD)? D[0] : tmp[1];
    tmp[8] <= (ALOAD)? D[0] : tmp[1];
  end

  // Combinational logic to generate n22
  assign n22 = ALOAD & tmp[8];
endmodule

sva:
module shift_register_sva (
    input logic Clock,
    input logic ALOAD,
    input logic [8:0] D,
    input logic SO,
    input logic [8:0] tmp,
    input logic n22
);

    // tmp[0] captures D[0] on each clock.
    check_tmp0_captures_d0: assert property (
        @(posedge Clock) !$initstate |-> (tmp[0] == $past(D[0]))
    );

    // tmp[1] shifts the previous tmp[0].
    check_tmp1_shifts_tmp0: assert property (
        @(posedge Clock) !$initstate |-> (tmp[1] == $past(tmp[0]))
    );

    // tmp[2] shifts the previous tmp[1].
    check_tmp2_shifts_tmp1: assert property (
        @(posedge Clock) !$initstate |-> (tmp[2] == $past(tmp[1]))
    );

    // tmp[3] shifts the previous tmp[2].
    check_tmp3_shifts_tmp2: assert property (
        @(posedge Clock) !$initstate |-> (tmp[3] == $past(tmp[2]))
    );

    // tmp[4] shifts the previous tmp[3].
    check_tmp4_shifts_tmp3: assert property (
        @(posedge Clock) !$initstate |-> (tmp[4] == $past(tmp[3]))
    );

    // tmp[5] shifts the previous tmp[4].
    check_tmp5_shifts_tmp4: assert property (
        @(posedge Clock) !$initstate |-> (tmp[5] == $past(tmp[4]))
    );

    // tmp[6] shifts the previous tmp[5].
    check_tmp6_shifts_tmp5: assert property (
        @(posedge Clock) !$initstate |-> (tmp[6] == $past(tmp[5]))
    );

    // tmp[7] shifts the previous tmp[6].
    check_tmp7_shifts_tmp6: assert property (
        @(posedge Clock) !$initstate |-> (tmp[7] == $past(tmp[6]))
    );

    // SO loads the previous D[0] when ALOAD was high.
    check_so_load_path: assert property (
        @(posedge Clock) (!$initstate && $past(ALOAD)) |-> (SO == $past(D[0]))
    );

    // SO shifts the previous tmp[1] when ALOAD was low.
    check_so_shift_path: assert property (
        @(posedge Clock) (!$initstate && !$past(ALOAD)) |-> (SO == $past(tmp[1]))
    );

    // n22 is always the AND of ALOAD and tmp[8].
    check_n22_and_decode: assert property (
        @(posedge Clock) (n22 == (ALOAD & tmp[8]))
    );

endmodule

rtl:
module karnaugh_map(
  input wire A, B, C, D,
  output reg F
);

  // Parameter declarations, if needed

  // Verilog code to implement the Karnaugh map expression for F
  always @* begin
    F = (A & ~B & C & ~D) | (~A & B & ~C & D) | (A & ~B & ~C & D) | (~A & B & C & ~D);
  end

endmodule

sva:
module karnaugh_map_assertions (
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic F
);

    // F matches the implemented sum-of-products expression.
    check_f_matches_expression: assert property (
        @($global_clock)
        F == ((A & ~B & C & ~D) |
              (~A & B & ~C & D) |
              (A & ~B & ~C & D) |
              (~A & B & C & ~D))
    );

    // F is high for the minterm A=1, B=0, C=1, D=0.
    check_f_high_for_1010: assert property (
        @($global_clock)
        (A && !B && C && !D) |-> F
    );

    // F is high for the minterm A=0, B=1, C=0, D=1.
    check_f_high_for_0101: assert property (
        @($global_clock)
        (!A && B && !C && D) |-> F
    );

    // F is high for the minterm A=1, B=0, C=0, D=1.
    check_f_high_for_1001: assert property (
        @($global_clock)
        (A && !B && !C && D) |-> F
    );

    // F is high for the minterm A=0, B=1, C=1, D=0.
    check_f_high_for_0110: assert property (
        @($global_clock)
        (!A && B && C && !D) |-> F
    );

    // F is low when none of the implemented product terms is active.
    check_f_low_outside_implemented_minterms: assert property (
        @($global_clock)
        !((A & ~B & C & ~D) |
          (~A & B & ~C & D) |
          (A & ~B & ~C & D) |
          (~A & B & C & ~D)) |-> !F
    );

    // F can only be high when A and B differ.
    check_f_requires_ab_difference: assert property (
        @($global_clock)
        F |-> (A ^ B)
    );

    // F can only be high when C and D differ.
    check_f_requires_cd_difference: assert property (
        @($global_clock)
        F |-> (C ^ D)
    );

    // F is low whenever A and B are equal.
    check_f_low_when_ab_equal: assert property (
        @($global_clock)
        !(A ^ B) |-> !F
    );

    // F is low whenever C and D are equal.
    check_f_low_when_cd_equal: assert property (
        @($global_clock)
        !(C ^ D) |-> !F
    );

endmodule

rtl:
module priority_encoder (
    input [7:0] in,
    output reg [1:0] pos,
    output reg [3:0] out_sel,
    input clk // Added clock input
);

    always @ (posedge clk) begin
        if (in[7]) begin
            pos <= 3'b111;
            out_sel <= 4'b0001;
        end else if (in[6]) begin
            pos <= 3'b110;
            out_sel <= 4'b0010;
        end else if (in[5]) begin
            pos <= 3'b100;
            out_sel <= 4'b0100;
        end else if (in[4]) begin
            pos <= 3'b011;
            out_sel <= 4'b1000;
        end else if (in[3]) begin
            pos <= 3'b010;
            out_sel <= 4'b0000;
        end else if (in[2]) begin
            pos <= 3'b001;
            out_sel <= 4'b0000;
        end else if (in[1]) begin
            pos <= 3'b000;
            out_sel <= 4'b0000;
        end else begin
            pos <= 2'b00;
            out_sel <= 4'b0000;
        end
    end
endmodule

sva:
module priority_encoder_sva (
    input logic [7:0] in,
    input logic [1:0] pos,
    input logic [3:0] out_sel,
    input logic clk
);

    // Bit 7 has highest priority and drives the next registered outputs.
    check_bit7_priority: assert property (
        @(posedge clk)
        in[7] |=> (pos == 2'b11 && out_sel == 4'b0001)
    );

    // Bit 6 is selected when bit 7 is low.
    check_bit6_priority: assert property (
        @(posedge clk)
        ((in[7] == 1'b0) && (in[6] == 1'b1)) |=> (pos == 2'b10 && out_sel == 4'b0010)
    );

    // Bit 5 is selected when bits 7 and 6 are low.
    check_bit5_priority: assert property (
        @(posedge clk)
        ((in[7:6] == 2'b00) && (in[5] == 1'b1)) |=> (pos == 2'b00 && out_sel == 4'b0100)
    );

    // Bit 4 is selected when bits 7 through 5 are low.
    check_bit4_priority: assert property (
        @(posedge clk)
        ((in[7:5] == 3'b000) && (in[4] == 1'b1)) |=> (pos == 2'b11 && out_sel == 4'b1000)
    );

    // Bit 3 is selected when bits 7 through 4 are low.
    check_bit3_priority: assert property (
        @(posedge clk)
        ((in[7:4] == 4'b0000) && (in[3] == 1'b1)) |=> (pos == 2'b10 && out_sel == 4'b0000)
    );

    // Bit 2 is selected when bits 7 through 3 are low.
    check_bit2_priority: assert property (
        @(posedge clk)
        ((in[7:3] == 5'b00000) && (in[2] == 1'b1)) |=> (pos == 2'b01 && out_sel == 4'b0000)
    );

    // Bit 1 is selected when bits 7 through 2 are low.
    check_bit1_priority: assert property (
        @(posedge clk)
        ((in[7:2] == 6'b000000) && (in[1] == 1'b1)) |=> (pos == 2'b00 && out_sel == 4'b0000)
    );

    // When bits 7 through 1 are clear, bit 0 is ignored and outputs go to zero.
    check_no_selected_bit_or_bit0_only: assert property (
        @(posedge clk)
        (in[7:1] == 7'b0000000) |=> (pos == 2'b00 && out_sel == 4'b0000)
    );

endmodule

rtl:
module counter (clock, reset, enable, input_value, output_value);

  parameter WIDTH = 8;
  parameter DECREMENT_VALUE = 1;

  input clock, reset, enable;
  input [WIDTH-1:0] input_value;
  output [WIDTH-1:0] output_value;

  reg [WIDTH-1:0] counter_reg;

  always @(posedge clock) begin
    if (reset) begin
      counter_reg <= 0;
    end else if (enable) begin
      counter_reg <= input_value - DECREMENT_VALUE;
    end
  end

  assign output_value = counter_reg;

endmodule

sva:
module counter_sva #(
    parameter WIDTH = 8,
    parameter DECREMENT_VALUE = 1
) (
    input logic clock,
    input logic reset,
    input logic enable,
    input logic [WIDTH-1:0] input_value,
    input logic [WIDTH-1:0] output_value
);

    localparam logic [WIDTH-1:0] ZERO = '0;
    localparam logic [WIDTH-1:0] DEC_VALUE_W = DECREMENT_VALUE;

    // Reset clears the counter output on the following clock.
    check_reset_clears_output: assert property (
        @(posedge clock) reset |=> (output_value == ZERO)
    );

    // Reset has priority over enable when both are asserted.
    check_reset_priority_over_enable: assert property (
        @(posedge clock) reset && enable |=> (output_value == ZERO)
    );

    // Enable loads input_value minus the decrement value.
    check_enable_loads_decremented_input: assert property (
        @(posedge clock) disable iff (reset)
        enable |=> (output_value == ($past(input_value) - DEC_VALUE_W))
    );

    // When enable is low, the counter output holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clock) disable iff (reset)
        !enable |=> (output_value == $past(output_value))
    );

endmodule

rtl:
module altera_tse_false_path_marker 
#(
   parameter MARKER_WIDTH = 1
)
(
   input    reset,
   input    clk,
   input    [MARKER_WIDTH - 1 : 0] data_in,
   output   [MARKER_WIDTH - 1 : 0] data_out
);



 reg [MARKER_WIDTH - 1 : 0] data_out_reg;


assign data_out = data_out_reg;

always @(posedge clk or posedge reset) 
begin
   if (reset)
   begin
      data_out_reg <= {MARKER_WIDTH{1'b0}};
   end
   else
   begin
      data_out_reg <= data_in;
   end
end

endmodule

sva:
module altera_tse_false_path_marker_sva
#(
    parameter MARKER_WIDTH = 1
)
(
    input logic reset,
    input logic clk,
    input logic [MARKER_WIDTH - 1 : 0] data_in,
    input logic [MARKER_WIDTH - 1 : 0] data_out
);

    localparam logic [MARKER_WIDTH - 1 : 0] ZERO = {MARKER_WIDTH{1'b0}};

    // Reset forces the registered output low.
    check_reset_drives_zero: assert property (
        @(posedge clk) reset |-> (data_out == ZERO)
    );

    // A sampled reset keeps the output low until the next clock edge.
    check_reset_keeps_zero_next_cycle: assert property (
        @(posedge clk) reset |=> (data_out == ZERO)
    );

    // Outside reset, the sampled output is either zero or the prior sampled input.
    check_output_is_zero_or_prior_input: assert property (
        @(posedge clk) disable iff (reset)
        !$past(reset, 1, 1'b1) |-> ((data_out == ZERO) || (data_out == $past(data_in, 1, ZERO)))
    );

    // Any nonzero sampled output must match the prior sampled input.
    check_nonzero_output_matches_prior_input: assert property (
        @(posedge clk) disable iff (reset)
        (data_out != ZERO) && !$past(reset, 1, 1'b1) |-> (data_out == $past(data_in, 1, ZERO))
    );

    // A nonzero output is never observed while reset is sampled high.
    check_nonzero_output_not_during_reset: assert property (
        @(posedge clk) (data_out != ZERO) |-> !reset
    );

endmodule

module o311ai_sva (
    input logic clk,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic B1,
    input logic C1,
    input logic Y
);

    // Y must match the implemented combinational logic.
    check_y_matches_logic: assert property (
        @(posedge clk) Y == ((A2 | (A1 & B1)) & (~A3) & C1)
    );

    // A3 high forces Y low through the inverted A3 term.
    check_a3_masks_output: assert property (
        @(posedge clk) (A3 == 1'b1) |-> (Y == 1'b0)
    );

    // C1 low forces Y low through the final AND gate.
    check_c1_masks_output: assert property (
        @(posedge clk) (C1 == 1'b0) |-> (Y == 1'b0)
    );

    // A2 high drives Y high when the gating terms are enabled.
    check_a2_drives_output_when_enabled: assert property (
        @(posedge clk) ((A2 == 1'b1) && (A3 == 1'b0) && (C1 == 1'b1)) |-> (Y == 1'b1)
    );

    // A1 and B1 high together drive Y high when the gating terms are enabled.
    check_a1b1_drives_output_when_enabled: assert property (
        @(posedge clk) ((A1 == 1'b1) && (B1 == 1'b1) && (A3 == 1'b0) && (C1 == 1'b1)) |-> (Y == 1'b1)
    );

    // With no OR-path active and the gates enabled, Y must be low.
    check_no_or_term_keeps_output_low: assert property (
        @(posedge clk) ((A2 == 1'b0) && !((A1 == 1'b1) && (B1 == 1'b1)) && (A3 == 1'b0) && (C1 == 1'b1)) |-> (Y == 1'b0)
    );

    // A high Y requires C1 high, A3 low, and at least one OR input path true.
    check_y_high_has_valid_causes: assert property (
        @(posedge clk) (Y == 1'b1) |-> ((C1 == 1'b1) && (A3 == 1'b0) && ((A2 == 1'b1) || ((A1 == 1'b1) && (B1 == 1'b1))))
    );

endmodule

rtl:
module binary_counter (
  clk,
  reset,
  enable,
  out
);

input wire clk;
input wire reset;
input wire enable;
output reg [3:0] out;

always @(posedge clk) begin
  if (reset) begin
    out <= 4'b0000;
  end else if (enable) begin
    out <= out + 1;
  end
end

endmodule

sva:
module binary_counter_sva (
    input logic       clk,
    input logic       reset,
    input logic       enable,
    input logic [3:0] out
);

    // A sampled reset clears the counter on the next clock.
    check_reset_clears_out: assert property (
        @(posedge clk) reset |=> (out == 4'b0000)
    );

    // Reset has priority over enable when both are high.
    check_reset_overrides_enable: assert property (
        @(posedge clk) (reset && enable) |=> (out == 4'b0000)
    );

    // When enabled outside reset, the counter increments by one.
    check_increment_when_enabled: assert property (
        @(posedge clk) disable iff (reset)
        enable |=> (out == ($past(out) + 4'd1))
    );

    // When disabled outside reset, the counter holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset)
        !enable |=> (out == $past(out))
    );

    // Incrementing from 4'hF wraps the counter to 4'h0.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (reset)
        (enable && (out == 4'hF)) |=> (out == 4'h0)
    );

endmodule

rtl:
module my_module (
    Y   ,
    A1  ,
    A2  ,
    B1  ,
    C1  ,
    VPWR,
    VGND
);

    // Module ports
    output Y;
    input  A1;
    input  A2;
    input  B1;
    input  C1;
    input  VPWR;
    input  VGND;

    // Local signals
    wire and0_out         ;
    wire not0_out         ;
    wire or0_out          ;
    wire nor0_out_Y       ;

    // Module instantiations
    and and0 (and0_out, A1, A2);
    not not0 (not0_out, B1);
    or or0 (or0_out, not0_out, C1);
    nor nor0 (nor0_out_Y, and0_out, or0_out);
    buf buf0 (Y, nor0_out_Y);

endmodule

sva:
module my_module_sva (
    input logic Y,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic C1,
    input logic VPWR,
    input logic VGND,
    input logic clk
);

    // External clk samples this combinational DUT.

    // Y matches the implemented AND/NOT/OR/NOR function.
    check_full_boolean_function: assert property (
        @(posedge clk)
        Y == ~((A1 & A2) | ((~B1) | C1))
    );

    // B1 low forces the OR path high and Y low.
    check_b1_low_forces_y_low: assert property (
        @(posedge clk)
        !B1 |-> !Y
    );

    // C1 high forces the OR path high and Y low.
    check_c1_high_forces_y_low: assert property (
        @(posedge clk)
        C1 |-> !Y
    );

    // A1 and A2 high force the NOR output low.
    check_a1_a2_high_force_y_low: assert property (
        @(posedge clk)
        (A1 && A2) |-> !Y
    );

    // Y high requires B1 high, C1 low, and at least one A input low.
    check_y_high_requires_enable_terms: assert property (
        @(posedge clk)
        Y |-> (B1 && !C1 && (!A1 || !A2))
    );

    // B1 high, C1 low, and either A input low force Y high.
    check_enable_terms_force_y_high: assert property (
        @(posedge clk)
        (B1 && !C1 && (!A1 || !A2)) |-> Y
    );

    // Y low means at least one blocking term is active.
    check_y_low_requires_blocking_term: assert property (
        @(posedge clk)
        !Y |-> ((A1 && A2) || !B1 || C1)
    );

endmodule

rtl:
module XNOR3HD2X(A, B, C, Z);
  input A, B, C;
  output Z;

  assign Z = ~(A ^ B ^ C);
endmodule

sva:
module XNOR3HD2X_sva (
    input logic A,
    input logic B,
    input logic C,
    input logic Z
);

    // Z must always implement the 3-input XNOR function.
    check_function_exact: assert property (
        @($global_clock) Z == ~(A ^ B ^ C)
    );

    // If A and B match, Z must be the inverse of C.
    check_equal_ab: assert property (
        @($global_clock) (A == B) |-> (Z == ~C)
    );

    // If B and C match, Z must be the inverse of A.
    check_equal_bc: assert property (
        @($global_clock) (B == C) |-> (Z == ~A)
    );

    // If A and C match, Z must be the inverse of B.
    check_equal_ac: assert property (
        @($global_clock) (A == C) |-> (Z == ~B)
    );

    // If A and B differ, Z must match C.
    check_diff_ab: assert property (
        @($global_clock) (A != B) |-> (Z == C)
    );

    // If B and C differ, Z must match A.
    check_diff_bc: assert property (
        @($global_clock) (B != C) |-> (Z == A)
    );

    // If A and C differ, Z must match B.
    check_diff_ac: assert property (
        @($global_clock) (A != C) |-> (Z == B)
    );

    // When all inputs are low, Z must be high.
    check_all_zero: assert property (
        @($global_clock) (!A && !B && !C) |-> Z
    );

    // When exactly one input is high, Z must be low.
    check_one_hot: assert property (
        @($global_clock) ((A && !B && !C) || (!A && B && !C) || (!A && !B && C)) |-> !Z
    );

    // When exactly two inputs are high, Z must be high.
    check_two_hot: assert property (
        @($global_clock) ((A && B && !C) || (A && !B && C) || (!A && B && C)) |-> Z
    );

    // When all inputs are high, Z must be low.
    check_all_one: assert property (
        @($global_clock) (A && B && C) |-> !Z
    );

endmodule

