rtl:
module nand_gate(
    input a,
    input b,
    output reg y
);

always @ (a, b) begin
    y = ~(a & b);
end

endmodule
module decoder_2to4(
    input [1:0] in,
    output [3:0] out
);

wire n1, n2;

nand_gate nand1(
    .a(in[0]), 
    .b(in[1]), 
    .y(n1)
);

nand_gate nand2(
    .a(in[0]), 
    .b(~in[1]), 
    .y(n2)
);

assign out = {~n1 & ~n2, ~n1 & n2, n1 & ~n2, n1 & n2};

endmodule

sva:
module decoder_2to4_sva (
    input logic clk,
    input logic [1:0] in,
    input logic [3:0] out
);

    // Full output matches the implemented NAND-based logic.
    check_output_equation: assert property (
        @(posedge clk) out == {1'b0, (in[0] & in[1]), (in[0] & ~in[1]), ~in[0]}
    );

    // The MSB of out is never asserted by this implementation.
    check_out3_constant_low: assert property (
        @(posedge clk) out[3] == 1'b0
    );

    // out[2] is asserted only when both input bits are high.
    check_out2_equation: assert property (
        @(posedge clk) out[2] == (in[0] & in[1])
    );

    // out[1] is asserted only when in is 2'b01.
    check_out1_equation: assert property (
        @(posedge clk) out[1] == (in[0] & ~in[1])
    );

    // out[0] is asserted whenever in[0] is low.
    check_out0_equation: assert property (
        @(posedge clk) out[0] == ~in[0]
    );

    // Exactly one output bit is high for every input combination.
    check_output_onehot: assert property (
        @(posedge clk) $onehot(out)
    );

    // Any input with in[0] low maps to 4'b0001.
    check_low_in0_case: assert property (
        @(posedge clk) (!in[0]) |-> (out == 4'b0001)
    );

    // Input 2'b01 maps to 4'b0010.
    check_input_01_case: assert property (
        @(posedge clk) (in == 2'b01) |-> (out == 4'b0010)
    );

    // Input 2'b11 maps to 4'b0100.
    check_input_11_case: assert property (
        @(posedge clk) (in == 2'b11) |-> (out == 4'b0100)
    );

endmodule

rtl:
module mux_2to1 (
    input in0,
    input in1,
    input sel,
    output out
);

    assign out = (sel == 1'b0) ? in0 : in1;

endmodule

sva:
module mux_2to1_sva (
    input logic in0,
    input logic in1,
    input logic sel,
    input logic out
);

    // No RTL clock or reset; sample the combinational behavior on $global_clock.

    // When select is low, out must equal in0.
    check_sel_low_routes_in0: assert property (
        @($global_clock) (sel == 1'b0) |-> (out == in0)
    );

    // When select is high, out must equal in1.
    check_sel_high_routes_in1: assert property (
        @($global_clock) (sel == 1'b1) |-> (out == in1)
    );

    // A selected in0 change must be reflected at out.
    check_in0_change_updates_out_when_sel_low: assert property (
        @($global_clock)
        (!$initstate && ($past(sel) == 1'b0) && (sel == 1'b0) && $changed(in0)) |-> $changed(out)
    );

    // A selected in1 change must be reflected at out.
    check_in1_change_updates_out_when_sel_high: assert property (
        @($global_clock)
        (!$initstate && ($past(sel) == 1'b1) && (sel == 1'b1) && $changed(in1)) |-> $changed(out)
    );

    // An in1 change cannot affect out while sel stays low and in0 is stable.
    check_in1_change_ignored_when_sel_low: assert property (
        @($global_clock)
        (!$initstate && ($past(sel) == 1'b0) && (sel == 1'b0) && $stable(in0) && $changed(in1)) |-> $stable(out)
    );

    // An in0 change cannot affect out while sel stays high and in1 is stable.
    check_in0_change_ignored_when_sel_high: assert property (
        @($global_clock)
        (!$initstate && ($past(sel) == 1'b1) && (sel == 1'b1) && $stable(in1) && $changed(in0)) |-> $stable(out)
    );

    // A select change must toggle out when inputs are different and stable.
    check_sel_change_toggles_out_when_inputs_differ: assert property (
        @($global_clock)
        (!$initstate && $changed(sel) && $stable(in0) && $stable(in1) && (in0 != in1)) |-> $changed(out)
    );

    // A select change must not change out when inputs match and are stable.
    check_sel_change_holds_out_when_inputs_match: assert property (
        @($global_clock)
        (!$initstate && $changed(sel) && $stable(in0) && $stable(in1) && (in0 == in1)) |-> $stable(out)
    );

endmodule

rtl:
module gray_code_converter (
    input [3:0] data_in,
    output [3:0] gray_out
);

reg [3:0] stage1_out;
reg [3:0] stage2_out;

// Stage 1
always @(*) begin
    stage1_out[0] = data_in[0];
    stage1_out[1] = data_in[1] ^ data_in[0];
    stage1_out[2] = data_in[2] ^ data_in[1];
    stage1_out[3] = data_in[3] ^ data_in[2];
end

// Stage 2
always @(*) begin
    stage2_out[0] = stage1_out[0];
    stage2_out[1] = stage1_out[1] ^ stage1_out[0];
    stage2_out[2] = stage1_out[2] ^ stage1_out[1];
    stage2_out[3] = stage1_out[3] ^ stage1_out[2];
end

assign gray_out = stage2_out;

endmodule

sva:
module gray_code_converter_sva (
    input logic [3:0] data_in,
    input logic [3:0] gray_out
);

    // Purely combinational RTL with no explicit clock or reset; sample on $global_clock.

    // Output bit 0 directly mirrors input bit 0.
    check_gray_bit0_passthrough: assert property (
        @($global_clock) gray_out[0] === data_in[0]
    );

    // Output bit 1 directly mirrors input bit 1.
    check_gray_bit1_passthrough: assert property (
        @($global_clock) gray_out[1] === data_in[1]
    );

    // Output bit 2 is the XOR of input bits 2 and 0.
    check_gray_bit2_xor: assert property (
        @($global_clock) gray_out[2] === (data_in[2] ^ data_in[0])
    );

    // Output bit 3 is the XOR of input bits 3 and 1.
    check_gray_bit3_xor: assert property (
        @($global_clock) gray_out[3] === (data_in[3] ^ data_in[1])
    );

    // Full output matches the RTL's two-stage combinational expansion.
    check_gray_full_mapping: assert property (
        @($global_clock) gray_out === {data_in[3] ^ data_in[1], data_in[2] ^ data_in[0], data_in[1], data_in[0]}
    );

    // Stable input must keep the output stable.
    check_stable_input_stable_output: assert property (
        @($global_clock) $stable(data_in) |-> $stable(gray_out)
    );

    // A change only on input bit 0 cannot affect output bits 1 or 3.
    check_bit0_change_independence: assert property (
        @($global_clock)
        ($changed(data_in[0]) && $stable(data_in[1]) && $stable(data_in[2]) && $stable(data_in[3]))
        |-> ($stable(gray_out[1]) && $stable(gray_out[3]))
    );

    // A change only on input bit 1 cannot affect output bits 0 or 2.
    check_bit1_change_independence: assert property (
        @($global_clock)
        ($changed(data_in[1]) && $stable(data_in[0]) && $stable(data_in[2]) && $stable(data_in[3]))
        |-> ($stable(gray_out[0]) && $stable(gray_out[2]))
    );

    // A change only on input bit 2 cannot affect output bits 0, 1, or 3.
    check_bit2_change_independence: assert property (
        @($global_clock)
        ($changed(data_in[2]) && $stable(data_in[0]) && $stable(data_in[1]) && $stable(data_in[3]))
        |-> ($stable(gray_out[0]) && $stable(gray_out[1]) && $stable(gray_out[3]))
    );

    // A change only on input bit 3 cannot affect output bits 0, 1, or 2.
    check_bit3_change_independence: assert property (
        @($global_clock)
        ($changed(data_in[3]) && $stable(data_in[0]) && $stable(data_in[1]) && $stable(data_in[2]))
        |-> ($stable(gray_out[0]) && $stable(gray_out[1]) && $stable(gray_out[2]))
    );

endmodule

module up_down_counter_sva (
    input logic clk,
    input logic reset,
    input logic mode,
    input logic [3:0] initial_value,
    input logic [3:0] counter_value
);

    // Synchronous reset loads counter_value from initial_value.
    check_reset_load: assert property (
        @(posedge clk) reset |=> counter_value == $past(initial_value)
    );

    // In up mode, non-maximum values increment by one.
    check_up_increment: assert property (
        @(posedge clk) disable iff (reset)
        (mode == 1'b0 && counter_value != 4'b1111) |=> counter_value == ($past(counter_value) + 4'd1)
    );

    // In up mode, 15 wraps to 0.
    check_up_wrap: assert property (
        @(posedge clk) disable iff (reset)
        (mode == 1'b0 && counter_value == 4'b1111) |=> counter_value == 4'b0000
    );

    // In down mode, non-zero values decrement by one.
    check_down_decrement: assert property (
        @(posedge clk) disable iff (reset)
        (mode == 1'b1 && counter_value != 4'b0000) |=> counter_value == ($past(counter_value) - 4'd1)
    );

    // In down mode, 0 wraps to 15.
    check_down_wrap: assert property (
        @(posedge clk) disable iff (reset)
        (mode == 1'b1 && counter_value == 4'b0000) |=> counter_value == 4'b1111
    );

endmodule

rtl:
module adder_4bit(
    input [3:0] A,
    input [3:0] B,
    input reset,
    output [3:0] S
);

wire [3:0] carry;
wire [3:0] sum;

// Implement full-adder for each bit
full_adder fa0(A[0], B[0], reset, carry[0], sum[0]);
full_adder fa1(A[1], B[1], carry[0], carry[1], sum[1]);
full_adder fa2(A[2], B[2], carry[1], carry[2], sum[2]);
full_adder fa3(A[3], B[3], carry[2], carry[3], sum[3]);

// Assign output
assign S = sum;

endmodule

module full_adder(
    input a,
    input b,
    input cin,
    output reg cout,
    output reg sum
);

always @(*) begin
    sum = a ^ b ^ cin;
    cout = (a & b) | (a & cin) | (b & cin);
end

endmodule

sva:
module adder_4bit_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic       reset,
    input logic [3:0] S
);

    // The output matches 4-bit addition of A, B, and the bit-0 carry-in.
    check_sum_matches_addition: assert property (
        @($global_clock) S == (A + B + reset)
    );

    // Sum bit 0 is the XOR of A[0], B[0], and reset.
    check_bit0_sum: assert property (
        @($global_clock) S[0] == (A[0] ^ B[0] ^ reset)
    );

    // Sum bit 1 uses the carry generated from bit 0.
    check_bit1_sum: assert property (
        @($global_clock)
        S[1] == (A[1] ^ B[1] ^
                 ((A[0] & B[0]) | (A[0] & reset) | (B[0] & reset)))
    );

    // Sum bit 2 uses the carry generated from bits 0 and 1.
    check_bit2_sum: assert property (
        @($global_clock)
        S[2] == (A[2] ^ B[2] ^
                 ((A[1] & B[1]) |
                  (A[1] & ((A[0] & B[0]) | (A[0] & reset) | (B[0] & reset))) |
                  (B[1] & ((A[0] & B[0]) | (A[0] & reset) | (B[0] & reset)))))
    );

    // Sum bit 3 uses the carry generated from bits 0 through 2.
    check_bit3_sum: assert property (
        @($global_clock)
        S[3] == (A[3] ^ B[3] ^
                 ((A[2] & B[2]) |
                  (A[2] & ((A[1] & B[1]) |
                           (A[1] & ((A[0] & B[0]) | (A[0] & reset) | (B[0] & reset))) |
                           (B[1] & ((A[0] & B[0]) | (A[0] & reset) | (B[0] & reset))))) |
                  (B[2] & ((A[1] & B[1]) |
                           (A[1] & ((A[0] & B[0]) | (A[0] & reset) | (B[0] & reset))) |
                           (B[1] & ((A[0] & B[0]) | (A[0] & reset) | (B[0] & reset)))))))
    );

    // With no carry-in and B at zero, S passes A through.
    check_a_passthrough_when_b_zero: assert property (
        @($global_clock) ((B == 4'h0) && (reset == 1'b0)) |-> (S == A)
    );

    // With no carry-in and A at zero, S passes B through.
    check_b_passthrough_when_a_zero: assert property (
        @($global_clock) ((A == 4'h0) && (reset == 1'b0)) |-> (S == B)
    );

    // With both operands at zero, only the input carry appears on bit 0.
    check_zero_operands_follow_input_carry: assert property (
        @($global_clock) ((A == 4'h0) && (B == 4'h0)) |-> (S == {3'b000, reset})
    );

endmodule

rtl:
module binary_to_gray(
    input [3:0] binary,
    input clk,
    output reg [3:0] gray
);

    always @(posedge clk) begin
        gray <= binary ^ (binary >> 1);
    end

endmodule

sva:
module binary_to_gray_assertions(
    input logic [3:0] binary,
    input logic       clk,
    input logic [3:0] gray
);

    // Gray output is the registered binary-to-Gray conversion from the prior clock.
    check_gray_conversion: assert property (
        @(posedge clk) disable iff (1'b0)
        1'b1 |=> gray == ($past(binary) ^ ($past(binary) >> 1))
    );

    // Gray[3] matches the prior binary MSB.
    check_gray_bit3: assert property (
        @(posedge clk) disable iff (1'b0)
        1'b1 |=> gray[3] == $past(binary[3])
    );

    // Gray[2] is the XOR of the prior binary[3] and binary[2].
    check_gray_bit2: assert property (
        @(posedge clk) disable iff (1'b0)
        1'b1 |=> gray[2] == ($past(binary[3]) ^ $past(binary[2]))
    );

    // Gray[1] is the XOR of the prior binary[2] and binary[1].
    check_gray_bit1: assert property (
        @(posedge clk) disable iff (1'b0)
        1'b1 |=> gray[1] == ($past(binary[2]) ^ $past(binary[1]))
    );

    // Gray[0] is the XOR of the prior binary[1] and binary[0].
    check_gray_bit0: assert property (
        @(posedge clk) disable iff (1'b0)
        1'b1 |=> gray[0] == ($past(binary[1]) ^ $past(binary[0]))
    );

endmodule

module select_logic_sva (
    input logic i1,
    input logic i2,
    input logic i3,
    input logic i4,
    input logic i5,
    input logic i6,
    input logic i7,
    input logic i8,
    input logic s1,
    input logic s2,
    input logic s3,
    input logic a1
);

    // a1 must match the RTL mux equation.
    check_mux_equation: assert property (
        @($global_clock)
        a1 == ((i1 & (!s1) & (!s2) & (!s3)) |
               (i2 & (!s1) & (!s2) & ( s3)) |
               (i3 & (!s1) & ( s2) & (!s3)) |
               (i4 & (!s1) & ( s2) & ( s3)) |
               (i5 & ( s1) & (!s2) & (!s3)) |
               (i6 & ( s1) & (!s2) & ( s3)) |
               (i7 & ( s1) & ( s2) & (!s3)) |
               (i8 & ( s1) & ( s2) & ( s3)))
    );

    // When select is 000, a1 must equal i1.
    check_select_000_i1: assert property (
        @($global_clock)
        ({s1, s2, s3} == 3'b000) |-> (a1 == i1)
    );

    // When select is 001, a1 must equal i2.
    check_select_001_i2: assert property (
        @($global_clock)
        ({s1, s2, s3} == 3'b001) |-> (a1 == i2)
    );

    // When select is 010, a1 must equal i3.
    check_select_010_i3: assert property (
        @($global_clock)
        ({s1, s2, s3} == 3'b010) |-> (a1 == i3)
    );

    // When select is 011, a1 must equal i4.
    check_select_011_i4: assert property (
        @($global_clock)
        ({s1, s2, s3} == 3'b011) |-> (a1 == i4)
    );

    // When select is 100, a1 must equal i5.
    check_select_100_i5: assert property (
        @($global_clock)
        ({s1, s2, s3} == 3'b100) |-> (a1 == i5)
    );

    // When select is 101, a1 must equal i6.
    check_select_101_i6: assert property (
        @($global_clock)
        ({s1, s2, s3} == 3'b101) |-> (a1 == i6)
    );

    // When select is 110, a1 must equal i7.
    check_select_110_i7: assert property (
        @($global_clock)
        ({s1, s2, s3} == 3'b110) |-> (a1 == i7)
    );

    // When select is 111, a1 must equal i8.
    check_select_111_i8: assert property (
        @($global_clock)
        ({s1, s2, s3} == 3'b111) |-> (a1 == i8)
    );

endmodule

rtl:
module counter(clk, rst, en, count);
  input clk, rst, en;
  output reg [1:0] count;

  always @(posedge clk) begin
    if (rst) begin
      count <= 2'b0;
    end else if (en) begin
      count <= count + 2'b1;
    end
  end

endmodule

sva:
module counter_sva (
    input logic       clk,
    input logic       rst,
    input logic       en,
    input logic [1:0] count
);

    // Reset drives count to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |=> (count == 2'b00)
    );

    // Reset has priority even when enable is high.
    check_reset_priority_over_enable: assert property (
        @(posedge clk) (rst && en) |=> (count == 2'b00)
    );

    // Enable increments the counter by one.
    check_enable_increments_count: assert property (
        @(posedge clk) disable iff (rst) en |=> (count == ($past(count) + 2'b01))
    );

    // Disable holds the counter value.
    check_disable_holds_count: assert property (
        @(posedge clk) disable iff (rst) !en |=> (count == $past(count))
    );

    // The maximum count wraps to zero when enabled.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (rst) (en && (count == 2'b11)) |=> (count == 2'b00)
    );

endmodule

rtl:
module shift_mux (
    input [3:0] data_in,
    input [3:0] in_0,
    input [3:0] in_1,
    input [3:0] in_2,
    input [3:0] in_3,
    input [1:0] sel,
    input shift,
    output reg [3:0] out
);

reg [3:0] shift_reg;

always @ (posedge shift) begin
    shift_reg <= {shift_reg[2:0], data_in[3]};
end

always @ (*) begin
    case (sel)
        2'b00: out <= in_0;
        2'b01: out <= in_1;
        2'b10: out <= in_2;
        2'b11: out <= in_3;
        default: out <= shift_reg;
    endcase
end

endmodule

sva:
module shift_mux_assertions (
    input logic [3:0] data_in,
    input logic [3:0] in_0,
    input logic [3:0] in_1,
    input logic [3:0] in_2,
    input logic [3:0] in_3,
    input logic [1:0] sel,
    input logic shift,
    input logic [3:0] out,
    input logic [3:0] shift_reg
);

    // shift_reg upper bits shift from the previous lower bits.
    check_shift_reg_shift: assert property (
        @(posedge shift) 1'b1 |=> (shift_reg[3:1] === $past(shift_reg[2:0]))
    );

    // shift_reg loads data_in[3] into bit 0 on each shift edge.
    check_shift_reg_load_bit3: assert property (
        @(posedge shift) 1'b1 |=> (shift_reg[0] === $past(data_in[3]))
    );

    // out selects in_0 when sel is 2'b00.
    check_out_sel_00: assert property (
        @(posedge shift) (sel === 2'b00) |-> (out === in_0)
    );

    // out selects in_1 when sel is 2'b01.
    check_out_sel_01: assert property (
        @(posedge shift) (sel === 2'b01) |-> (out === in_1)
    );

    // out selects in_2 when sel is 2'b10.
    check_out_sel_10: assert property (
        @(posedge shift) (sel === 2'b10) |-> (out === in_2)
    );

    // out selects in_3 when sel is 2'b11.
    check_out_sel_11: assert property (
        @(posedge shift) (sel === 2'b11) |-> (out === in_3)
    );

    // out stays stable when sel and all mux inputs stay stable.
    check_out_stable_when_mux_inputs_stable: assert property (
        @(posedge shift)
        1'b1 |=> (
            !((sel  === $past(sel))  &&
              (in_0 === $past(in_0)) &&
              (in_1 === $past(in_1)) &&
              (in_2 === $past(in_2)) &&
              (in_3 === $past(in_3))) ||
            (out === $past(out))
        )
    );

endmodule

rtl:
module binary_counter(
   input clk,
   input rst,
   input [15:0] max_count,
   output reg [15:0] count,
   output reg done
   );

   always @(posedge clk or posedge rst) begin
      if (rst) begin
         count <= 0;
         done <= 0;
      end
      else begin
         if (count == max_count) begin
            count <= 0;
            done <= 1;
         end
         else begin
            count <= count + 1;
            done <= 0;
         end
      end
   end

endmodule

sva:
module binary_counter_sva (
    input logic        clk,
    input logic        rst,
    input logic [15:0] max_count,
    input logic [15:0] count,
    input logic        done
);

    // Reset keeps count and done cleared.
    check_reset_clears_outputs: assert property (
        @(posedge clk) rst |-> (count == 16'd0 && done == 1'b0)
    );

    // Reaching max_count wraps count and raises done on the next cycle.
    check_wrap_on_max_count: assert property (
        @(posedge clk) disable iff (rst)
        (count == max_count) |=> (count == 16'd0 && done == 1'b1)
    );

    // Any non-max count increments and keeps done low on the next cycle.
    check_increment_when_not_max: assert property (
        @(posedge clk) disable iff (rst)
        (count != max_count) |=> (count == ($past(count) + 16'd1) && done == 1'b0)
    );

    // The first clock after reset release still observes the reset state.
    check_hold_reset_state_after_release: assert property (
        @(posedge clk) disable iff (rst)
        $past(rst) |-> (count == 16'd0 && done == 1'b0)
    );

    // done reflects whether the previous cycle hit max_count.
    check_done_reflects_previous_match: assert property (
        @(posedge clk) disable iff (rst)
        !$past(rst) |-> (done == ($past(count) == $past(max_count)))
    );

endmodule

rtl:
module bitwise_or(
    input [2:0] a,
    input [2:0] b,
    output [2:0] out
);
    assign out = a | b;
endmodule

module logical_or(
    input [2:0] a,
    input [2:0] b,
    output out
);
    assign out = (a != 0) || (b != 0);
endmodule

module top_module( 
    input [2:0] a,
    input [2:0] b,
    output [2:0] out_or_bitwise,
    output out_or_logical,
    output [5:0] out_not
); 
    wire [2:0] a_not, b_not;
    wire [2:0] or_bitwise;

    bitwise_or bitwise_or_inst(
        .a(a),
        .b(b),
        .out(or_bitwise)
    );

    logical_or logical_or_inst(
        .a(a),
        .b(b),
        .out(out_or_logical)
    );

    assign a_not = ~a;
    assign b_not = ~b;

    assign out_not = {b_not, a_not};
    assign out_or_bitwise = or_bitwise;
endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic [2:0] a,
    input logic [2:0] b,
    input logic [2:0] out_or_bitwise,
    input logic out_or_logical,
    input logic [5:0] out_not
);

    // Bitwise OR output equals a | b.
    check_out_or_bitwise_value: assert property (
        @(posedge clk) out_or_bitwise === (a | b)
    );

    // Bit 0 of the bitwise OR output matches a[0] | b[0].
    check_out_or_bitwise_bit0: assert property (
        @(posedge clk) out_or_bitwise[0] === (a[0] | b[0])
    );

    // Bit 1 of the bitwise OR output matches a[1] | b[1].
    check_out_or_bitwise_bit1: assert property (
        @(posedge clk) out_or_bitwise[1] === (a[1] | b[1])
    );

    // Bit 2 of the bitwise OR output matches a[2] | b[2].
    check_out_or_bitwise_bit2: assert property (
        @(posedge clk) out_or_bitwise[2] === (a[2] | b[2])
    );

    // Logical OR output matches the RTL non-zero test.
    check_out_or_logical_value: assert property (
        @(posedge clk) out_or_logical === ((a != 3'b000) || (b != 3'b000))
    );

    // Lower half of out_not is the bitwise inversion of a.
    check_out_not_lower_half: assert property (
        @(posedge clk) out_not[2:0] === (~a)
    );

    // Upper half of out_not is the bitwise inversion of b.
    check_out_not_upper_half: assert property (
        @(posedge clk) out_not[5:3] === (~b)
    );

    // Full out_not matches the concatenation {~b, ~a}.
    check_out_not_concat: assert property (
        @(posedge clk) out_not === {~b, ~a}
    );

endmodule

rtl:
module sky130_fd_sc_hd__mux_2 (
  input [3:0] A,
  input [3:0] B,
  input S,
  output [3:0] Y
);

  assign Y = S ? B : A;

endmodule

sva:
module sky130_fd_sc_hd__mux_2_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic S,
    input logic [3:0] Y
);

    // Y must equal A when S is low.
    check_select_a: assert property (
        @(posedge clk) (!S) |-> (Y == A)
    );

    // Y must equal B when S is high.
    check_select_b: assert property (
        @(posedge clk) S |-> (Y == B)
    );

    // Y must always match the mux select equation.
    check_mux_equation: assert property (
        @(posedge clk) Y == (S ? B : A)
    );

    // If A and B are equal, Y must match that common value.
    check_equal_inputs_passthrough: assert property (
        @(posedge clk) (A == B) |-> (Y == A)
    );

endmodule

rtl:
module adder4bit_carry(A, B, cin, S, cout);

  input [3:0] A;
  input [3:0] B;
  input cin;
  output [3:0] S;
  output cout;

  wire [4:0] sum;

  assign sum = {1'b0, A} + {1'b0, B} + {1'b0, cin};

  assign S = sum[3:0];
  assign cout = sum[4];

endmodule

sva:
module adder4bit_carry_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic cin,
    input logic [3:0] S,
    input logic cout
);

    // Combined output must match the 5-bit sum of A, B, and cin.
    check_full_sum_relation: assert property (
        @(posedge clk) {cout, S} == ({1'b0, A} + {1'b0, B} + {4'b0000, cin})
    );

    // The least significant sum bit follows full-adder XOR behavior.
    check_lsb_sum_bit: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0] ^ cin)
    );

    // The next sum bit uses bit 0 carry as a full-adder would.
    check_bit1_sum_bit: assert property (
        @(posedge clk) S[1] == (A[1] ^ B[1] ^ ((A[0] & B[0]) | (A[0] & cin) | (B[0] & cin)))
    );

    // Carry-out is asserted when the arithmetic result is at least 16.
    check_carry_out_threshold: assert property (
        @(posedge clk) cout == (({1'b0, A} + {1'b0, B} + {4'b0000, cin}) >= 5'd16)
    );

    // Zero inputs must produce a zero sum and no carry-out.
    check_zero_addition: assert property (
        @(posedge clk) (A == 4'h0 && B == 4'h0 && cin == 1'b0) |-> (S == 4'h0 && cout == 1'b0)
    );

    // A passes through when B and cin are zero.
    check_a_passthrough: assert property (
        @(posedge clk) (B == 4'h0 && cin == 1'b0) |-> (S == A && cout == 1'b0)
    );

    // B passes through when A and cin are zero.
    check_b_passthrough: assert property (
        @(posedge clk) (A == 4'h0 && cin == 1'b0) |-> (S == B && cout == 1'b0)
    );

    // Carry-in increments A when B is zero.
    check_cin_increments_a: assert property (
        @(posedge clk) (B == 4'h0 && cin == 1'b1) |-> ({cout, S} == ({1'b0, A} + 5'd1))
    );

    // Carry-in increments B when A is zero.
    check_cin_increments_b: assert property (
        @(posedge clk) (A == 4'h0 && cin == 1'b1) |-> ({cout, S} == ({1'b0, B} + 5'd1))
    );

    // Adding bitwise complements without carry-in yields all ones and no carry.
    check_complement_without_carry: assert property (
        @(posedge clk) (B == ~A && cin == 1'b0) |-> (S == 4'hF && cout == 1'b0)
    );

    // Adding bitwise complements with carry-in yields zero and carry-out.
    check_complement_with_carry: assert property (
        @(posedge clk) (B == ~A && cin == 1'b1) |-> (S == 4'h0 && cout == 1'b1)
    );

endmodule

rtl:
module adder(
    input [3:0] a,
    input [3:0] b,
    output [3:0] sum,
    output carry
);

    assign {carry, sum} = a + b;

    // Buffers to drive the output ports
    reg [3:0] sum_buf;
    reg carry_buf;

    always @* begin
        sum_buf = sum;
        carry_buf = carry;
    end

endmodule

sva:
module adder_sva(
    input logic clk,
    input logic [3:0] a,
    input logic [3:0] b,
    input logic [3:0] sum,
    input logic carry
);

    // Packed outputs must equal the zero-extended 4-bit add result.
    check_packed_output: assert property (
        @(posedge clk) {carry, sum} == {1'b0, (a + b)}
    );

    // Carry is always low because the add result is only 4 bits wide.
    check_carry_low: assert property (
        @(posedge clk) carry == 1'b0
    );

    // Sum must match the 4-bit addition result.
    check_sum_result: assert property (
        @(posedge clk) sum == (a + b)
    );

    // Zero on a passes b through with no carry.
    check_a_zero_passthrough: assert property (
        @(posedge clk) (a == 4'h0) |-> ((sum == b) && (carry == 1'b0))
    );

    // Zero on b passes a through with no carry.
    check_b_zero_passthrough: assert property (
        @(posedge clk) (b == 4'h0) |-> ((sum == a) && (carry == 1'b0))
    );

    // 4'hF plus 4'h1 truncates to zero with no carry.
    check_f_plus_one_truncates: assert property (
        @(posedge clk) ((a == 4'hF) && (b == 4'h1)) |-> ((sum == 4'h0) && (carry == 1'b0))
    );

    // 4'hF plus 4'hF truncates to 4'hE with no carry.
    check_max_plus_max_truncates: assert property (
        @(posedge clk) ((a == 4'hF) && (b == 4'hF)) |-> ((sum == 4'hE) && (carry == 1'b0))
    );

endmodule

rtl:
module bidirectional_data_port (
  input clk,
  input reset,
  input [3:0] in,
  input dir,
  output reg [3:0] out,
  output reg [3:0] dout
);

  always @(posedge clk, negedge reset) begin
    if (!reset) begin
      out <= 4'b0;
      dout <= 4'b0;
    end else begin
      if (dir == 1) begin
        out <= {in[3], in[2], in[1], in[0]};
        dout <= {in[0], in[1], in[2], in[3]};
      end else begin
        out <= in;
      end
    end
  end

endmodule

sva:
module bidirectional_data_port_sva (
    input logic clk,
    input logic reset,
    input logic [3:0] in,
    input logic dir,
    input logic [3:0] out,
    input logic [3:0] dout
);

    // Sampled low reset clears both outputs.
    check_reset_clears_outputs: assert property (
        @(posedge clk) (reset == 1'b0) |-> (out == 4'b0000) && (dout == 4'b0000)
    );

    // With dir high, out loads the input value.
    check_out_loads_input_when_dir_high: assert property (
        @(posedge clk) disable iff (!reset) (dir == 1'b1) |=> (out == $past(in))
    );

    // With dir high, dout loads the reversed input value.
    check_dout_loads_reversed_input_when_dir_high: assert property (
        @(posedge clk) disable iff (!reset) (dir == 1'b1) |=> (dout == {$past(in[0]), $past(in[1]), $past(in[2]), $past(in[3])})
    );

    // With dir low, out still loads the input value.
    check_out_loads_input_when_dir_low: assert property (
        @(posedge clk) disable iff (!reset) (dir == 1'b0) |=> (out == $past(in))
    );

    // With dir low, dout holds its previous value.
    check_dout_holds_when_dir_low: assert property (
        @(posedge clk) disable iff (!reset) (dir == 1'b0) |=> (dout == $past(dout))
    );

endmodule

rtl:
module pio_latency (
                     // inputs:
                      address,
                      clk,
                      in_port,
                      reset_n,

                     // outputs:
                      readdata
                   )
;

  output  [ 15: 0] readdata;
  input   [  1: 0] address;
  input            clk;
  input   [ 15: 0] in_port;
  input            reset_n;

  wire             clk_en;
  wire    [ 15: 0] data_in;
  wire    [ 15: 0] read_mux_out;
  reg     [ 15: 0] readdata;
  assign clk_en = 1;
  //s1, which is an e_avalon_slave
  assign read_mux_out = {16 {(address == 0)}} & data_in;
  always @(posedge clk or negedge reset_n)
    begin
      if (reset_n == 0)
          readdata <= 0;
      else if (clk_en)
          readdata <= read_mux_out;
    end


  assign data_in = in_port;

endmodule

sva:
module pio_latency_assertions (
    input  logic [1:0]  address,
    input  logic        clk,
    input  logic [15:0] in_port,
    input  logic        reset_n,
    input  logic [15:0] readdata
);

    // After reset was sampled low, readdata is zero on the next active clock.
    check_post_reset_readdata_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        ($past(reset_n) === 1'b0) |-> (readdata == 16'h0000)
    );

    // A prior read of address 0 returns the prior input, unless reset forced zero.
    check_addr0_read_matches_input_or_reset_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (($past(reset_n) === 1'b1) && ($past(address) === 2'b00)) |->
        ((readdata == $past(in_port)) || (readdata == 16'h0000))
    );

    // A prior read of address 1 returns zero.
    check_addr1_reads_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (($past(reset_n) === 1'b1) && ($past(address) === 2'b01)) |-> (readdata == 16'h0000)
    );

    // A prior read of address 2 returns zero.
    check_addr2_reads_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (($past(reset_n) === 1'b1) && ($past(address) === 2'b10)) |-> (readdata == 16'h0000)
    );

    // A prior read of address 3 returns zero.
    check_addr3_reads_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (($past(reset_n) === 1'b1) && ($past(address) === 2'b11)) |-> (readdata == 16'h0000)
    );

    // Address 0 with zero input returns zero on the following clock.
    check_addr0_zero_input_reads_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (($past(reset_n) === 1'b1) && ($past(address) === 2'b00) && ($past(in_port) === 16'h0000)) |->
        (readdata == 16'h0000)
    );

    // Any nonzero readdata must come from a prior read of address 0.
    check_nonzero_readdata_from_addr0: assert property (
        @(posedge clk) disable iff (!reset_n)
        (($past(reset_n) === 1'b1) && (readdata != 16'h0000)) |->
        (($past(address) === 2'b00) && (readdata == $past(in_port)))
    );

endmodule

rtl:
module sky130_fd_sc_ms__nand4b (
    Y  ,
    A_N,
    B  ,
    C  ,
    D
);

    output Y  ;
    input  A_N;
    input  B  ;
    input  C  ;
    input  D  ;

    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    wire not0_out   ;
    wire nand0_out_Y;

    not  not0  (not0_out   , A_N              );
    nand nand0 (nand0_out_Y, D, C, B, not0_out);
    buf  buf0  (Y          , nand0_out_Y      );

endmodule

sva:
module sky130_fd_sc_ms__nand4b_sva (
    input logic Y,
    input logic A_N,
    input logic B,
    input logic C,
    input logic D,
    input logic clk
);

    // Sample on an external clock because this cell is combinational and has no reset.

    // Y matches the buffered 4-input NAND with A_N inverted internally.
    check_function_equivalence: assert property (
        @(posedge clk) Y == ~(D & C & B & ~A_N)
    );

    // All effective NAND inputs high drive the output low.
    check_all_active_inputs_drive_low: assert property (
        @(posedge clk) (!A_N && B && C && D) |-> !Y
    );

    // A low output requires the single active-input minterm.
    check_low_output_requires_all_active_inputs: assert property (
        @(posedge clk) !Y |-> (!A_N && B && C && D)
    );

    // A_N high forces the output high.
    check_a_n_high_forces_high: assert property (
        @(posedge clk) A_N |-> Y
    );

    // B low forces the output high.
    check_b_low_forces_high: assert property (
        @(posedge clk) !B |-> Y
    );

    // C low forces the output high.
    check_c_low_forces_high: assert property (
        @(posedge clk) !C |-> Y
    );

    // D low forces the output high.
    check_d_low_forces_high: assert property (
        @(posedge clk) !D |-> Y
    );

    // A high output means at least one input blocks the low minterm.
    check_high_output_has_blocking_input: assert property (
        @(posedge clk) Y |-> (A_N || !B || !C || !D)
    );

endmodule

