            ((s === 3'd1) && $stable(s) && $stable(d1)) ||
            ((s === 3'd2) && $stable(s) && $stable(d2)) ||
            ((s === 3'd3) && $stable(s) && $stable(d3)) ||
            ((s === 3'd4) && $stable(s) && $stable(d4)) ||
            ((s === 3'd5) && $stable(s) && $stable(d5)) ||
            ((s === 3'd6) && $stable(s) && $stable(d5)) ||
            ((s === 3'd7) && $stable(s) && $stable(d5))
