rtl:
module binary_to_onehot (
    input [3:0] B,
    output reg [7:0] O
);

always @(*)
begin
    case(B)
        4'b0001: O = 8'b00000001;
        4'b0010: O = 8'b00000010;
        4'b0100: O = 8'b00000100;
        4'b1000: O = 8'b00001000;
        default: O = 8'b00000000;
    endcase
end

endmodule

sva:
module binary_to_onehot_sva (
    input logic clk,
    input logic [3:0] B,
    input logic [7:0] O
);

    // 0001 maps to output bit 0.
    check_map_0001: assert property (
        @(posedge clk) (B == 4'b0001) |-> (O == 8'b00000001)
    );

    // 0010 maps to output bit 1.
    check_map_0010: assert property (
        @(posedge clk) (B == 4'b0010) |-> (O == 8'b00000010)
    );

    // 0100 maps to output bit 2.
    check_map_0100: assert property (
        @(posedge clk) (B == 4'b0100) |-> (O == 8'b00000100)
    );

    // 1000 maps to output bit 3.
    check_map_1000: assert property (
        @(posedge clk) (B == 4'b1000) |-> (O == 8'b00001000)
    );

    // All other input values drive zero.
    check_default_zero: assert property (
        @(posedge clk)
        ((B != 4'b0001) && (B != 4'b0010) && (B != 4'b0100) && (B != 4'b1000))
        |-> (O == 8'b00000000)
    );

    // The upper four output bits are always zero.
    check_upper_bits_zero: assert property (
        @(posedge clk) (O[7:4] == 4'b0000)
    );

endmodule

rtl:
module sky130_fd_sc_hd__and3b (
    X  ,
    A_N,
    B  ,
    C
);

    output X  ;
    input  A_N;
    input  B  ;
    input  C  ;

    wire not0_out  ;
    wire and0_out_X;

    not not0 (not0_out  , A_N            );
    and and0 (and0_out_X, C, not0_out, B );
    buf buf0 (X         , and0_out_X     );

endmodule

sva:
module sky130_fd_sc_hd__and3b_sva (
    input logic clk,
    input logic X,
    input logic A_N,
    input logic B,
    input logic C
);

    // No reset in RTL; combinational behavior is sampled on clk.

    // X must equal the AND of B, C, and the inversion of A_N.
    check_and3b_function: assert property (
        @(posedge clk) X == ((~A_N) & B & C)
    );

    // A_N high forces the inverted input low, so X must be low.
    check_a_n_high_blocks_output: assert property (
        @(posedge clk) A_N |-> !X
    );

    // B low forces the AND output low.
    check_b_low_blocks_output: assert property (
        @(posedge clk) !B |-> !X
    );

    // C low forces the AND output low.
    check_c_low_blocks_output: assert property (
        @(posedge clk) !C |-> !X
    );

    // When A_N is low and both B and C are high, X must be high.
    check_all_enables_drive_output_high: assert property (
        @(posedge clk) (!A_N && B && C) |-> X
    );

    // X high implies A_N is low and both B and C are high.
    check_x_high_requires_all_inputs: assert property (
        @(posedge clk) X |-> (!A_N && B && C)
    );

    // With A_N low, X reduces to B AND C.
    check_a_n_low_reduces_to_bc_and: assert property (
        @(posedge clk) !A_N |-> (X == (B & C))
    );

endmodule

rtl:
module shift_nor (
    input clk,
    input load,
    input [1:0] ena,
    input [99:0] data,
    input a,
    input b,
    output out
);

reg [99:0] shift_reg;
wire [99:0] shifted_data;

// Shift register module
always @(posedge clk) begin
    if (load) begin
        shift_reg <= data;
    end else if (ena == 2'b01) begin
        shift_reg <= {shift_reg[0], shift_reg[99:1]};
    end else if (ena == 2'b10) begin
        shift_reg <= {shift_reg[98:0], shift_reg[99]};
    end
end

assign shifted_data = shift_reg;

// NOR gate module
assign out = ~(a | b);

endmodule

sva:
module shift_nor_sva (
    input logic        clk,
    input logic        load,
    input logic [1:0]  ena,
    input logic [99:0] data,
    input logic        a,
    input logic        b,
    input logic        out,
    input logic [99:0] shift_reg,
    input logic [99:0] shifted_data
);

    // Load captures data into the shift register on the next clock.
    check_load_captures_data: assert property (
        @(posedge clk) load |=> (shift_reg == $past(data))
    );

    // ena=01 rotates the shift register right by one bit when load is low.
    check_rotate_right: assert property (
        @(posedge clk) (!load && (ena == 2'b01)) |=> (shift_reg == {$past(shift_reg[0]), $past(shift_reg[99:1])})
    );

    // ena=10 rotates the shift register left by one bit when load is low.
    check_rotate_left: assert property (
        @(posedge clk) (!load && (ena == 2'b10)) |=> (shift_reg == {$past(shift_reg[98:0]), $past(shift_reg[99])})
    );

    // ena=00 or ena=11 holds the shift register value when load is low.
    check_hold_when_not_enabled: assert property (
        @(posedge clk) (!load && ((ena == 2'b00) || (ena == 2'b11))) |=> (shift_reg == $past(shift_reg))
    );

    // shifted_data always mirrors the shift register.
    check_shifted_data_mirrors_shift_reg: assert property (
        @(posedge clk) shifted_data == shift_reg
    );

    // out is always the NOR of inputs a and b.
    check_nor_output: assert property (
        @(posedge clk) out == ~(a | b)
    );

endmodule

rtl:
module five_to_one(
    input input1,
    input input2,
    input input3,
    input input4,
    input input5,
    output output1
);

    wire and1, and2, and3, and4, or1;

    assign and1 = input1 & input2;
    assign and2 = input3 & input4;
    assign and3 = and2 & input5;
    assign or1 = and1 | and3;
    assign output1 = or1;

endmodule

sva:
module five_to_one_sva (
    input logic clk,
    input logic input1,
    input logic input2,
    input logic input3,
    input logic input4,
    input logic input5,
    input logic output1
);

    // Output matches the RTL sum-of-products equation.
    check_output_equation: assert property (
        @(posedge clk)
        output1 == ((input1 & input2) | (input3 & input4 & input5))
    );

    // The input1/input2 AND path forces the output high.
    check_first_path_drives_high: assert property (
        @(posedge clk)
        (input1 & input2) |-> output1
    );

    // The input3/input4/input5 AND path forces the output high.
    check_second_path_drives_high: assert property (
        @(posedge clk)
        (input3 & input4 & input5) |-> output1
    );

    // A high output must come from at least one implemented path.
    check_output_high_has_valid_cause: assert property (
        @(posedge clk)
        output1 |-> ((input1 & input2) | (input3 & input4 & input5))
    );

    // If the first path is inactive, output equals the second path.
    check_no_first_path_means_second_path_only: assert property (
        @(posedge clk)
        !(input1 & input2) |-> (output1 == (input3 & input4 & input5))
    );

    // If the second path is inactive, output equals the first path.
    check_no_second_path_means_first_path_only: assert property (
        @(posedge clk)
        !(input3 & input4 & input5) |-> (output1 == (input1 & input2))
    );

endmodule

rtl:
module top_module(
    input a,
    input b,
    input sel_b1,
    input sel_b2,
    output reg out_always,
    output out_and,
    output out_or,
    output out_xor
);

    wire mux_out;
    wire [3:0] logic_gate_out;

    // 2-to-1 Multiplexer
    assign mux_out = (sel_b1 & sel_b2) ? b : a;

    // 4-input Logic Gate
    and_gate logic_and(.and_out(logic_gate_out[0]), .a(a), .b(b), .c(sel_b1), .d(sel_b2));
    or_gate logic_or(.or_out(logic_gate_out[1]), .a(a), .b(b), .c(sel_b1), .d(sel_b2));
    xor_gate logic_xor(.xor_out(logic_gate_out[2]), .a(a), .b(b), .c(sel_b1), .d(sel_b2));
    assign logic_gate_out[3] = 1'b0;

    // Output assignments
    assign out_and = logic_gate_out[0];
    assign out_or = logic_gate_out[1];
    assign out_xor = logic_gate_out[2];
    always @* begin
        out_always = mux_out;
    end

endmodule

module and_gate(
    output and_out,
    input a,
    input b,
    input c,
    input d
);
    assign and_out = a & b & c & d;
endmodule

module or_gate(
    output or_out,
    input a,
    input b,
    input c,
    input d
);
    assign or_out = a | b | c | d;
endmodule

module xor_gate(
    output xor_out,
    input a,
    input b,
    input c,
    input d
);
    assign xor_out = a ^ b ^ c ^ d;
endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic a,
    input logic b,
    input logic sel_b1,
    input logic sel_b2,
    input logic out_always,
    input logic out_and,
    input logic out_or,
    input logic out_xor
);

    // out_always selects b when both select inputs are high.
    check_out_always_selects_b: assert property (
        @(posedge clk) (sel_b1 & sel_b2) |-> (out_always == b)
    );

    // out_always selects a when both select inputs are not high.
    check_out_always_selects_a: assert property (
        @(posedge clk) !(sel_b1 & sel_b2) |-> (out_always == a)
    );

    // out_and is the 4-input AND of a, b, sel_b1, and sel_b2.
    check_out_and_is_four_input_and: assert property (
        @(posedge clk) out_and == (a & b & sel_b1 & sel_b2)
    );

    // out_or is the 4-input OR of a, b, sel_b1, and sel_b2.
    check_out_or_is_four_input_or: assert property (
        @(posedge clk) out_or == (a | b | sel_b1 | sel_b2)
    );

    // out_xor is the 4-input XOR of a, b, sel_b1, and sel_b2.
    check_out_xor_is_four_input_xor: assert property (
        @(posedge clk) out_xor == (a ^ b ^ sel_b1 ^ sel_b2)
    );

endmodule

rtl:
module constant_voltage_driver (
  input control,
  input [7:0] vref,
  output reg vout
);


  always @ (control, vref) begin
    if (control) begin
      vout <= vref;
    end else begin
      vout <= 0;
    end
  end

endmodule

sva:
module constant_voltage_driver_sva (
    input logic clk,
    input logic control,
    input logic [7:0] vref,
    input logic vout
);

    // When control is low, the output must be low.
    check_output_zero_when_control_low: assert property (
        @(posedge clk) (control === 1'b0) |-> (vout === 1'b0)
    );

    // When control is high, the output must match the vref LSB.
    check_output_tracks_vref_lsb_when_control_high: assert property (
        @(posedge clk) (control === 1'b1) |-> (vout === vref[0])
    );

    // A high output requires control high and vref[0] high.
    check_high_output_requires_enable_and_lsb: assert property (
        @(posedge clk) (vout === 1'b1) |-> ((control === 1'b1) && (vref[0] === 1'b1))
    );

    // Changes in vref must not affect the output while control stays low.
    check_vref_ignored_when_control_low: assert property (
        @(posedge clk)
        ($past(control) === 1'b0) && (control === 1'b0) &&
        ($past(vref) !== vref) |-> $stable(vout)
    );

    // Changes in vref[7:1] alone must not affect the output while enabled.
    check_upper_vref_bits_do_not_affect_output: assert property (
        @(posedge clk)
        ($past(control) === 1'b1) && (control === 1'b1) &&
        ($past(vref[0]) === vref[0]) &&
        ($past(vref[7:1]) !== vref[7:1]) |-> $stable(vout)
    );

    // A change in vref[0] must change the output while enabled and upper bits stay the same.
    check_lsb_change_updates_output_when_enabled: assert property (
        @(posedge clk)
        ($past(control) === 1'b1) && (control === 1'b1) &&
        ($past(vref[7:1]) === vref[7:1]) &&
        ($past(vref[0]) !== vref[0]) |-> (vout !== $past(vout))
    );

endmodule

module binary_counter_sva (
    input logic       clk,
    input logic       reset,
    input logic [3:0] count
);

    // Reset forces the counter to zero on the following clock sample.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'h0)
    );

    // When below 15 and not in reset, the counter increments by one.
    check_increment_when_not_max: assert property (
        @(posedge clk) disable iff (reset)
        (count != 4'hF) |=> (count == ($past(count) + 4'h1))
    );

    // When at 15 and not in reset, the counter wraps to zero.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (reset)
        (count == 4'hF) |=> (count == 4'h0)
    );

    // On every non-reset cycle, the counter value changes.
    check_count_changes_each_cycle: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> (count != $past(count))
    );

endmodule

rtl:
module barrel_shifter_16bit (
    input [15:0] D,
    input [3:0] shift_ctrl,
    output reg [15:0] Q
);
    always @(*) begin
        case(shift_ctrl)
            4'b0000: Q = D << 1;
            4'b0001: Q = D << 2;
            4'b0010: Q = D << 4;
            4'b0011: Q = D << 8;
            4'b0100: Q = D >> 1;
            4'b0101: Q = D >> 2;
            4'b0110: Q = D >> 4;
            4'b0111: Q = D >> 8;
            default: Q = D;
        endcase
    end
endmodule

module alu_32bit (
    input [31:0] a,
    input [31:0] b,
    input [3:0] ctrl,
    output reg [31:0] result
);
    always @(*) begin
        case(ctrl)
            4'b0000: result = a + b;
            4'b0001: result = a - b;
            4'b0010: result = a & b;
            4'b0011: result = a | b;
            4'b0100: result = a ^ b;
            default: result = a;
        endcase
    end
endmodule

module top_module (
    input [15:0] D,
    input [3:0] shift_ctrl,
    input [31:0] a,
    input [31:0] b,
    input [3:0] alu_ctrl,
    output reg [31:0] result
);

    // 16-bit barrel shifter
    wire [15:0] shifted_D;
    barrel_shifter_16bit bs16 (
        .D(D),
        .shift_ctrl(shift_ctrl),
        .Q(shifted_D)
    );

    // 32-bit ALU
    wire [31:0] alu_result;
    alu_32bit alu32 (
        .a(a),
        .b(b),
        .ctrl(alu_ctrl),
        .result(alu_result)
    );

    // Bitwise OR module
    wire [31:0] or_result;
    assign or_result = shifted_D | alu_result;

    // Output
    always @* begin
        result = or_result;
    end

endmodule

sva:
module top_module_sva (
    input  logic        clk,
    input  logic [15:0] D,
    input  logic [3:0]  shift_ctrl,
    input  logic [31:0] a,
    input  logic [31:0] b,
    input  logic [3:0]  alu_ctrl,
    input  logic [31:0] result,
    input  logic [15:0] shifted_D,
    input  logic [31:0] alu_result,
    input  logic [31:0] or_result
);

    function automatic logic [15:0] expected_shift (
        input logic [15:0] d_i,
        input logic [3:0]  shift_i
    );
        case (shift_i)
            4'b0000: expected_shift = d_i << 1;
            4'b0001: expected_shift = d_i << 2;
            4'b0010: expected_shift = d_i << 4;
            4'b0011: expected_shift = d_i << 8;
            4'b0100: expected_shift = d_i >> 1;
            4'b0101: expected_shift = d_i >> 2;
            4'b0110: expected_shift = d_i >> 4;
            4'b0111: expected_shift = d_i >> 8;
            default: expected_shift = d_i;
        endcase
    endfunction

    function automatic logic [31:0] expected_alu (
        input logic [31:0] a_i,
        input logic [31:0] b_i,
        input logic [3:0]  ctrl_i
    );
        case (ctrl_i)
            4'b0000: expected_alu = a_i + b_i;
            4'b0001: expected_alu = a_i - b_i;
            4'b0010: expected_alu = a_i & b_i;
            4'b0011: expected_alu = a_i | b_i;
            4'b0100: expected_alu = a_i ^ b_i;
            default: expected_alu = a_i;
        endcase
    endfunction

    // Barrel shifter output matches the shift control decoding.
    check_shifted_d_matches_spec: assert property (
        @(posedge clk) shifted_D == expected_shift(D, shift_ctrl)
    );

    // Barrel shifter default case passes D through unchanged.
    check_shift_default_passthrough: assert property (
        @(posedge clk) shift_ctrl[3] |-> shifted_D == D
    );

    // ALU output matches the control decoding.
    check_alu_result_matches_spec: assert property (
        @(posedge clk) alu_result == expected_alu(a, b, alu_ctrl)
    );

    // ALU default case passes a through unchanged.
    check_alu_default_passthrough: assert property (
        @(posedge clk) (alu_ctrl > 4'b0100) |-> alu_result == a
    );

    // OR stage combines zero-extended shifted_D with alu_result.
    check_or_result_composition: assert property (
        @(posedge clk) or_result == ({16'b0, shifted_D} | alu_result)
    );

    // Top-level result follows the OR stage output.
    check_result_tracks_or_result: assert property (
        @(posedge clk) result == or_result
    );

    // Upper result bits come only from the ALU path.
    check_result_upper_half_matches_alu: assert property (
        @(posedge clk) result[31:16] == alu_result[31:16]
    );

    // Lower result bits preserve all ones from the shifted data.
    check_result_contains_shift_ones: assert property (
        @(posedge clk) (result[15:0] & shifted_D) == shifted_D
    );

    // Result preserves all ones from the ALU output.
    check_result_contains_alu_ones: assert property (
        @(posedge clk) (result & alu_result) == alu_result
    );

    // Top-level result matches the full end-to-end combinational spec.
    check_result_matches_full_spec: assert property (
        @(posedge clk) result == ({16'b0, expected_shift(D, shift_ctrl)} | expected_alu(a, b, alu_ctrl))
    );

endmodule

module binary_counter_sva (
    input logic clk,
    input logic reset,
    input logic load,
    input logic [3:0] load_value,
    input logic [3:0] q,
    input logic carry_out,
    input logic led
);

    // If reset is sampled low, the next sampled state is 5 and the status outputs are low.
    check_reset_state: assert property (
        @(posedge clk) (!reset) |=> ((q == 4'h5) && (carry_out == 1'b0) && (led == 1'b0))
    );

    // With load high, q takes load_value on the next cycle unless async reset intervenes.
    check_load_updates_q: assert property (
        @(posedge clk) disable iff (!reset)
        load |=> ((q == $past(load_value)) || (q == 4'h5))
    );

    // Without load, q increments by one when it is not at 15 unless async reset intervenes.
    check_increment_nonterminal: assert property (
        @(posedge clk) disable iff (!reset)
        (!load && (q != 4'hF)) |=> ((q == ($past(q) + 4'd1)) || (q == 4'h5))
    );

    // Without load, q wraps from 15 to 0 unless async reset intervenes.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (!reset)
        (!load && (q == 4'hF)) |=> ((q == 4'h0) || (q == 4'h5))
    );

    // carry_out is high exactly when q is 15.
    check_carry_matches_q: assert property (
        @(posedge clk) disable iff (!reset)
        (carry_out == (q == 4'hF))
    );

    // led always mirrors carry_out.
    check_led_matches_carry: assert property (
        @(posedge clk) disable iff (!reset)
        (led == carry_out)
    );

endmodule

rtl:
module and_delayed (
  input a,
  input b,
  input clk,
  output reg out
);

  reg delayed_a;
  reg delayed_b;

  always @(posedge clk) begin
    delayed_a <= a;
    delayed_b <= b;
  end

  always @(posedge clk) begin
    out <= delayed_a & delayed_b;
  end

endmodule

sva:
module and_delayed_sva (
    input logic a,
    input logic b,
    input logic clk,
    input logic out,
    input logic delayed_a,
    input logic delayed_b
);

    // Clock: clk.
    // Reset: none.
    // Sequential behavior: a and b are registered, then out registers their AND.

    // delayed_a captures a on the next clock.
    check_delayed_a_high_capture: assert property (
        @(posedge clk) a |=> delayed_a
    );

    // delayed_a captures a low value on the next clock.
    check_delayed_a_low_capture: assert property (
        @(posedge clk) !a |=> !delayed_a
    );

    // delayed_b captures b on the next clock.
    check_delayed_b_high_capture: assert property (
        @(posedge clk) b |=> delayed_b
    );

    // delayed_b captures a low value on the next clock.
    check_delayed_b_low_capture: assert property (
        @(posedge clk) !b |=> !delayed_b
    );

    // out goes high one clock after both delayed inputs are high.
    check_out_high_from_delayed_and: assert property (
        @(posedge clk) (delayed_a && delayed_b) |=> out
    );

    // out goes low one clock after either delayed input is low.
    check_out_low_from_delayed_zero: assert property (
        @(posedge clk) (!delayed_a || !delayed_b) |=> !out
    );

    // High inputs produce a high out after two clocks.
    check_out_high_two_cycles_after_inputs_high: assert property (
        @(posedge clk) (a && b) |-> ##2 out
    );

    // A low a forces out low after two clocks.
    check_out_low_two_cycles_after_a_low: assert property (
        @(posedge clk) !a |-> ##2 !out
    );

    // A low b forces out low after two clocks.
    check_out_low_two_cycles_after_b_low: assert property (
        @(posedge clk) !b |-> ##2 !out
    );

endmodule

rtl:
module power_ground_module (
    input clk,
    input rst_n,
    input enable,
    output reg VPWR,
    output reg VGND
);

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        VPWR <= 0;
        VGND <= 0;
    end else if (enable) begin
        VPWR <= 1;
        VGND <= 0;
    end else begin
        VPWR <= 0;
        VGND <= 0;
    end
end

endmodule

sva:
module power_ground_module_sva (
    input logic clk,
    input logic rst_n,
    input logic enable,
    input logic VPWR,
    input logic VGND
);

    // Clock: clk; reset: rst_n active-low; logic is sequential.
    // VPWR follows enable on the next clocked state update, and VGND is always low.

    // If reset is low, both outputs are low by the next sampled clock.
    check_reset_clears_outputs: assert property (
        @(posedge clk) !rst_n |=> (VPWR == 1'b0 && VGND == 1'b0)
    );

    // Outside reset, the next sampled outputs match the current enable value.
    check_outputs_follow_enable: assert property (
        @(posedge clk) disable iff (!rst_n)
        1'b1 |=> ((VPWR == $past(enable)) && (VGND == 1'b0))
    );

    // When enable is high, the next registered outputs are VPWR=1 and VGND=0.
    check_enable_sets_outputs: assert property (
        @(posedge clk) disable iff (!rst_n)
        enable |=> (VPWR == 1'b1 && VGND == 1'b0)
    );

    // When enable is low, the next registered outputs are VPWR=0 and VGND=0.
    check_disable_clears_outputs: assert property (
        @(posedge clk) disable iff (!rst_n)
        !enable |=> (VPWR == 1'b0 && VGND == 1'b0)
    );

endmodule

rtl:
module binary_adder(
    input [3:0] A,
    input [3:0] B,
    output [3:0] S,
    output C
);

    wire [3:0] sum;
    wire [3:0] carry;

    full_adder fa0(.A(A[0]), .B(B[0]), .C_in(1'b0), .S(sum[0]), .C_out(carry[1]));
    full_adder fa1(.A(A[1]), .B(B[1]), .C_in(carry[1]), .S(sum[1]), .C_out(carry[2]));
    full_adder fa2(.A(A[2]), .B(B[2]), .C_in(carry[2]), .S(sum[2]), .C_out(carry[3]));
    full_adder fa3(.A(A[3]), .B(B[3]), .C_in(carry[3]), .S(sum[3]), .C_out(C));

    assign S = sum;

endmodule

module full_adder(
    input A,
    input B,
    input C_in,
    output S,
    output C_out
);

    assign {C_out, S} = A + B + C_in;

endmodule

sva:
module binary_adder_sva(
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] S,
    input logic C
);

    // External sampling clock; the RTL has no native clock or reset.

    // The 5-bit output value matches the arithmetic sum of A and B.
    check_full_sum: assert property (
        @(posedge clk) ({C, S} == ({1'b0, A} + {1'b0, B}))
    );

    // The lower 4 bits of the arithmetic sum drive S.
    check_sum_lower_bits: assert property (
        @(posedge clk) ({1'b0, S} == (({1'b0, A} + {1'b0, B}) & 5'h0F))
    );

    // Bit 0 has no carry-in, so it is just A[0] xor B[0].
    check_lsb_sum: assert property (
        @(posedge clk) (S[0] == (A[0] ^ B[0]))
    );

    // Bit 1 includes the carry generated by bit 0.
    check_bit1_sum: assert property (
        @(posedge clk) (S[1] == (A[1] ^ B[1] ^ (A[0] & B[0])))
    );

    // Zero plus zero produces zero with no carry.
    check_zero_plus_zero: assert property (
        @(posedge clk) (((A == 4'h0) && (B == 4'h0)) |-> ({C, S} == 5'h00))
    );

    // A equal to zero passes B through with no carry.
    check_a_zero_identity: assert property (
        @(posedge clk) ((A == 4'h0) |-> ({C, S} == {1'b0, B}))
    );

    // B equal to zero passes A through with no carry.
    check_b_zero_identity: assert property (
        @(posedge clk) ((B == 4'h0) |-> ({C, S} == {1'b0, A}))
    );

    // Carry-out is high whenever the 5-bit sum exceeds 4 bits.
    check_carry_on_overflow: assert property (
        @(posedge clk) ((({1'b0, A} + {1'b0, B}) >= 5'h10) |-> (C == 1'b1))
    );

    // Carry-out stays low whenever the sum fits in 4 bits.
    check_no_carry_without_overflow: assert property (
        @(posedge clk) ((({1'b0, A} + {1'b0, B}) < 5'h10) |-> (C == 1'b0))
    );

    // The maximum input case produces decimal 30.
    check_max_plus_max: assert property (
        @(posedge clk) (((A == 4'hF) && (B == 4'hF)) |-> ({C, S} == 5'h1E))
    );

endmodule

rtl:
module mux4to1 (
    output reg [7:0] out,
    input [7:0] in0,
    input [7:0] in1,
    input [7:0] in2,
    input [7:0] in3,
    input sel0,
    input sel1
);

    // Local signals
    reg [7:0] selected;

    // Select the input based on the select lines
    always @*
    begin
        case ({sel1, sel0})
            2'b00: selected = in0;
            2'b01: selected = in1;
            2'b10: selected = in2;
            2'b11: selected = in3;
        endcase
    end

    // Assign the selected input to the output
    always @*
    begin
        out = selected;
    end

endmodule

sva:
module mux4to1_sva (
    input logic [7:0] out,
    input logic [7:0] in0,
    input logic [7:0] in1,
    input logic [7:0] in2,
    input logic [7:0] in3,
    input logic sel0,
    input logic sel1
);

    // Clockless combinational checks are sampled on the global formal clock.

    // When select is 00, the output must match in0.
    check_route_in0: assert property (
        @($global_clock) ({sel1, sel0} === 2'b00) |-> (out === in0)
    );

    // When select is 01, the output must match in1.
    check_route_in1: assert property (
        @($global_clock) ({sel1, sel0} === 2'b01) |-> (out === in1)
    );

    // When select is 10, the output must match in2.
    check_route_in2: assert property (
        @($global_clock) ({sel1, sel0} === 2'b10) |-> (out === in2)
    );

    // When select is 11, the output must match in3.
    check_route_in3: assert property (
        @($global_clock) ({sel1, sel0} === 2'b11) |-> (out === in3)
    );

    // With select held at 00 and in0 stable, other inputs must not affect out.
    check_stable_out_for_sel00: assert property (
        @($global_clock) (({sel1, sel0} === 2'b00) && $stable({sel1, sel0, in0})) |-> $stable(out)
    );

    // With select held at 01 and in1 stable, other inputs must not affect out.
    check_stable_out_for_sel01: assert property (
        @($global_clock) (({sel1, sel0} === 2'b01) && $stable({sel1, sel0, in1})) |-> $stable(out)
    );

    // With select held at 10 and in2 stable, other inputs must not affect out.
    check_stable_out_for_sel10: assert property (
        @($global_clock) (({sel1, sel0} === 2'b10) && $stable({sel1, sel0, in2})) |-> $stable(out)
    );

    // With select held at 11 and in3 stable, other inputs must not affect out.
    check_stable_out_for_sel11: assert property (
        @($global_clock) (({sel1, sel0} === 2'b11) && $stable({sel1, sel0, in3})) |-> $stable(out)
    );

endmodule

module up_down_counter_sva (
    input logic clk,
    input logic reset,
    input logic enable,
    input logic up_down,
    input logic [3:0] count
);

    // Reset drives the counter to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'b0000)
    );

    // When not enabled, the counter holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset)
        (!enable) |=> (count == $past(count))
    );

    // In up mode, the counter increments when below 15.
    check_increment_in_up_mode: assert property (
        @(posedge clk) disable iff (reset)
        (enable && up_down && (count != 4'b1111)) |=> (count == ($past(count) + 4'b0001))
    );

    // In up mode, the counter wraps from 15 to 0.
    check_wrap_in_up_mode: assert property (
        @(posedge clk) disable iff (reset)
        (enable && up_down && (count == 4'b1111)) |=> (count == 4'b0000)
    );

    // In down mode, the counter decrements when above 0.
    check_decrement_in_down_mode: assert property (
        @(posedge clk) disable iff (reset)
        (enable && !up_down && (count != 4'b0000)) |=> (count == ($past(count) - 4'b0001))
    );

    // In down mode, the counter wraps from 0 to 15.
    check_wrap_in_down_mode: assert property (
        @(posedge clk) disable iff (reset)
        (enable && !up_down && (count == 4'b0000)) |=> (count == 4'b1111)
    );

endmodule

rtl:
module AdderSubtractor (
    input [3:0] A,
    input [3:0] B,
    input Sub,
    output [3:0] S,
    output Cout
);

wire [3:0] A_comp;
wire [3:0] B_comp;

assign A_comp = ~A + 1;
assign B_comp = ~B + 1;

wire [4:0] temp_sum;
assign temp_sum = (Sub == 1) ? A + B_comp : A + B;

assign Cout = (Sub == 1) ? (A >= B) : (temp_sum[4] == 1);
assign S = (Sub == 1) ? temp_sum : temp_sum[3:0];

endmodule

sva:
module AdderSubtractor_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic Sub,
    input logic [3:0] S,
    input logic Cout
);

    // Addition mode returns the 4-bit sum.
    check_add_sum: assert property (
        @(posedge clk) (Sub == 1'b0) |-> (S == (A + B))
    );

    // Addition mode never asserts Cout.
    check_add_cout_low: assert property (
        @(posedge clk) (Sub == 1'b0) |-> (Cout == 1'b0)
    );

    // Subtraction mode returns the 4-bit difference.
    check_sub_diff: assert property (
        @(posedge clk) (Sub == 1'b1) |-> (S == (A - B))
    );

    // Subtraction mode uses A>=B as the Cout flag.
    check_sub_cout_no_borrow: assert property (
        @(posedge clk) (Sub == 1'b1) |-> (Cout == (A >= B))
    );

    // Equal operands subtract to zero with Cout asserted.
    check_sub_equal_zero: assert property (
        @(posedge clk) (Sub == 1'b1 && A == B) |-> (S == 4'b0000 && Cout == 1'b1)
    );

    // Adding zero passes A through and keeps Cout low.
    check_add_zero_passthrough: assert property (
        @(posedge clk) (Sub == 1'b0 && B == 4'b0000) |-> (S == A && Cout == 1'b0)
    );

    // Subtracting zero passes A through and asserts Cout.
    check_sub_zero_passthrough: assert property (
        @(posedge clk) (Sub == 1'b1 && B == 4'b0000) |-> (S == A && Cout == 1'b1)
    );

    // 0xF + 0x1 wraps to zero and still leaves Cout low.
    check_add_overflow_wrap: assert property (
        @(posedge clk) (Sub == 1'b0 && A == 4'hF && B == 4'h1) |-> (S == 4'h0 && Cout == 1'b0)
    );

    // 0x0 - 0x1 wraps to 0xF with Cout deasserted.
    check_sub_underflow_wrap: assert property (
        @(posedge clk) (Sub == 1'b1 && A == 4'h0 && B == 4'h1) |-> (S == 4'hF && Cout == 1'b0)
    );

endmodule

rtl:
module counter(clk, reset, count);
  input clk, reset;
  output reg [1:0] count;

  always @(posedge clk) begin
    if (reset) begin
      count <= 2'b0;
    end else if (count == 2'b11) begin
      count <= 2'b0;
    end else begin
      count <= count + 1;
    end
  end
endmodule

sva:
module counter_sva (
    input logic clk,
    input logic reset,
    input logic [1:0] count
);

    // After a reset cycle, count must be zero.
    check_reset_clears_count: assert property (
        @(posedge clk) disable iff ($initstate)
        $past(reset) |-> (count == 2'b00)
    );

    // From 0, the counter increments to 1 when not coming out of reset.
    check_count_0_to_1: assert property (
        @(posedge clk) disable iff ($initstate || $past(reset))
        ($past(count) == 2'b00) |-> (count == 2'b01)
    );

    // From 1, the counter increments to 2 when not coming out of reset.
    check_count_1_to_2: assert property (
        @(posedge clk) disable iff ($initstate || $past(reset))
        ($past(count) == 2'b01) |-> (count == 2'b10)
    );

    // From 2, the counter increments to 3 when not coming out of reset.
    check_count_2_to_3: assert property (
        @(posedge clk) disable iff ($initstate || $past(reset))
        ($past(count) == 2'b10) |-> (count == 2'b11)
    );

    // From 3, the counter wraps back to 0 when not coming out of reset.
    check_count_3_to_0: assert property (
        @(posedge clk) disable iff ($initstate || $past(reset))
        ($past(count) == 2'b11) |-> (count == 2'b00)
    );

endmodule

rtl:
module four_bit_adder(
    input [3:0] A,
    input [3:0] B,
    input C_in,
    output [3:0] S,
    output C_out
);

wire [3:0] sum;
wire [3:0] carry;

// Full adder for the least significant bit
full_adder fa0(A[0], B[0], C_in, sum[0], carry[0]);

// Full adder for the second least significant bit
full_adder fa1(A[1], B[1], carry[0], sum[1], carry[1]);

// Full adder for the third least significant bit
full_adder fa2(A[2], B[2], carry[1], sum[2], carry[2]);

// Full adder for the most significant bit
full_adder fa3(A[3], B[3], carry[2], sum[3], C_out);

assign S = sum;

endmodule
module full_adder(
    input A,
    input B,
    input C_in,
    output S,
    output C_out
);

assign S = A ^ B ^ C_in;
assign C_out = (A & B) | (C_in & (A ^ B));

endmodule

sva:
module four_bit_adder_sva (
    input logic       clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic       C_in,
    input logic [3:0] S,
    input logic       C_out
);

function automatic logic fa_sum(
    input logic a,
    input logic b,
    input logic cin
);
    fa_sum = a ^ b ^ cin;
endfunction

function automatic logic fa_carry(
    input logic a,
    input logic b,
    input logic cin
);
    fa_carry = (a & b) | (cin & (a ^ b));
endfunction

// The 5-bit output matches A + B + C_in.
check_total_addition: assert property (
    @(posedge clk) disable iff (1'b0)
    {C_out, S} == ({1'b0, A} + {1'b0, B} + {4'b0000, C_in})
);

// Bit 0 sum matches the least-significant full adder.
check_sum_bit0: assert property (
    @(posedge clk) disable iff (1'b0)
    S[0] == fa_sum(A[0], B[0], C_in)
);

// Bit 1 sum uses the carry from bit 0.
check_sum_bit1: assert property (
    @(posedge clk) disable iff (1'b0)
    S[1] == fa_sum(A[1], B[1], fa_carry(A[0], B[0], C_in))
);

// Bit 2 sum uses the ripple carry from bits 0 and 1.
check_sum_bit2: assert property (
    @(posedge clk) disable iff (1'b0)
    S[2] == fa_sum(A[2], B[2], fa_carry(A[1], B[1], fa_carry(A[0], B[0], C_in)))
);

// Bit 3 sum uses the ripple carry from bits 0 through 2.
check_sum_bit3: assert property (
    @(posedge clk) disable iff (1'b0)
    S[3] == fa_sum(A[3], B[3], fa_carry(A[2], B[2], fa_carry(A[1], B[1], fa_carry(A[0], B[0], C_in))))
);

// Carry out matches the final full adder carry.
check_carry_out: assert property (
    @(posedge clk) disable iff (1'b0)
    C_out == fa_carry(A[3], B[3], fa_carry(A[2], B[2], fa_carry(A[1], B[1], fa_carry(A[0], B[0], C_in))))
);

// Adding zero on B with no carry-in preserves A.
check_zero_b_no_carry: assert property (
    @(posedge clk) disable iff (1'b0)
    (B == 4'b0000 && C_in == 1'b0) |-> ({C_out, S} == {1'b0, A})
);

// Adding zero on A with no carry-in preserves B.
check_zero_a_no_carry: assert property (
    @(posedge clk) disable iff (1'b0)
    (A == 4'b0000 && C_in == 1'b0) |-> ({C_out, S} == {1'b0, B})
);

// Zero operands pass carry-in only to the least-significant sum bit.
check_zero_inputs: assert property (
    @(posedge clk) disable iff (1'b0)
    (A == 4'b0000 && B == 4'b0000) |-> (S == {3'b000, C_in} && C_out == 1'b0)
);

// All ones plus carry-in produces the maximum 5-bit result.
check_max_addition: assert property (
    @(posedge clk) disable iff (1'b0)
    (A == 4'hF && B == 4'hF && C_in == 1'b1) |-> (S == 4'hF && C_out == 1'b1)
);

endmodule

rtl:
module nor4bb (
    Y  ,
    A  ,
    B  ,
    C_N,
    D_N
);

    output Y  ;
    input  A  ;
    input  B  ;
    input  C_N;
    input  D_N;

    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;

    assign Y = ~(A | B | C_N | D_N);

endmodule

sva:
module nor4bb_sva (
    input logic clk,
    input logic Y,
    input logic A,
    input logic B,
    input logic C_N,
    input logic D_N
);

    // Y equals the implemented 4-input NOR.
    check_y_matches_nor_logic: assert property (
        @(posedge clk) Y == ~(A | B | C_N | D_N)
    );

    // All-low inputs drive Y high.
    check_all_inputs_low_set_y_high: assert property (
        @(posedge clk) (!A && !B && !C_N && !D_N) |-> (Y == 1'b1)
    );

    // A high drives Y low.
    check_a_high_forces_y_low: assert property (
        @(posedge clk) A |-> (Y == 1'b0)
    );

    // B high drives Y low.
    check_b_high_forces_y_low: assert property (
        @(posedge clk) B |-> (Y == 1'b0)
    );

    // C_N high drives Y low.
    check_cn_high_forces_y_low: assert property (
        @(posedge clk) C_N |-> (Y == 1'b0)
    );

    // D_N high drives Y low.
    check_dn_high_forces_y_low: assert property (
        @(posedge clk) D_N |-> (Y == 1'b0)
    );

    // Y high requires all inputs low.
    check_y_high_implies_all_inputs_low: assert property (
        @(posedge clk) Y |-> (!A && !B && !C_N && !D_N)
    );

    // Y low requires at least one input high.
    check_y_low_implies_some_input_high: assert property (
        @(posedge clk) !Y |-> (A || B || C_N || D_N)
    );

endmodule

rtl:
module dff(D, CLK, Q);
  input D, CLK;
  output Q;

  reg Q;

  always @(posedge CLK) begin
    Q <= D;
  end
endmodule

sva:
module dff_sva (
    input logic D,
    input logic CLK,
    input logic Q
);

    // Q reflects D sampled on the previous rising clock edge.
    check_q_matches_previous_d: assert property (
        @(posedge CLK) disable iff (1'b0) (!$initstate) |-> (Q == $past(D))
    );

    // A sampled high D is captured into Q on the next rising edge.
    check_high_d_captured: assert property (
        @(posedge CLK) disable iff (1'b0) D |=> Q
    );

    // A sampled low D is captured into Q on the next rising edge.
    check_low_d_captured: assert property (
        @(posedge CLK) disable iff (1'b0) !D |=> !Q
    );

    // If D is stable across clock edges, Q stays stable on the following edge.
    check_stable_d_keeps_q_stable: assert property (
        @(posedge CLK) disable iff (1'b0) (!$initstate && $stable(D)) |=> $stable(Q)
    );

    // If D changes across clock edges, Q changes on the following edge.
    check_changed_d_changes_q: assert property (
        @(posedge CLK) disable iff (1'b0) (!$initstate && !$stable(D)) |=> !$stable(Q)
    );

endmodule

rtl:
module four_input_module (
    input [1:0] A,
    input [1:0] B,
    output reg X
);

    wire C1 = A[0] & A[1];
    wire C2 = B[0] | B[1];

    always @(*) begin
        X = C1 ^ C2;
    end

endmodule

sva:
module four_input_module_sva (
    input logic [1:0] A,
    input logic [1:0] B,
    input logic X
);

    // X must equal the XOR of A's AND term and B's OR term.
    check_x_matches_logic: assert property (
        @($global_clock) X == ((A[0] & A[1]) ^ (B[0] | B[1]))
    );

    // If only the A AND term is high, X must be high.
    check_x_high_when_only_a_term_high: assert property (
        @($global_clock) ((A[0] & A[1]) && !(B[0] | B[1])) |-> (X == 1'b1)
    );

    // If only the B OR term is high, X must be high.
    check_x_high_when_only_b_term_high: assert property (
        @($global_clock) (!(A[0] & A[1]) && (B[0] | B[1])) |-> (X == 1'b1)
    );

    // If both terms are low, X must be low.
    check_x_low_when_both_terms_low: assert property (
        @($global_clock) (!(A[0] & A[1]) && !(B[0] | B[1])) |-> (X == 1'b0)
    );

    // If both terms are high, X must be low.
    check_x_low_when_both_terms_high: assert property (
        @($global_clock) ((A[0] & A[1]) && (B[0] | B[1])) |-> (X == 1'b0)
    );

endmodule

rtl:
module MUX4X1 (
    input [3:0] input_signals,
    input [1:0] select_signals,
    output reg output_signal
);

always @ (*)
begin
    case ({select_signals})
        2'b00: output_signal = input_signals[0];
        2'b01: output_signal = input_signals[1];
        2'b10: output_signal = input_signals[2];
        2'b11: output_signal = input_signals[3];
        default: output_signal = 1'bx;
    endcase
end

endmodule

sva:
module MUX4X1_sva (
    input logic       clk,
    input logic [3:0] input_signals,
    input logic [1:0] select_signals,
    input logic       output_signal
);

    // Select 00 routes input_signals[0] to the output.
    check_select_00_routes_input0: assert property (
        @(posedge clk)
        (select_signals === 2'b00) |-> (output_signal === input_signals[0])
    );

    // Select 01 routes input_signals[1] to the output.
    check_select_01_routes_input1: assert property (
        @(posedge clk)
        (select_signals === 2'b01) |-> (output_signal === input_signals[1])
    );

    // Select 10 routes input_signals[2] to the output.
    check_select_10_routes_input2: assert property (
        @(posedge clk)
        (select_signals === 2'b10) |-> (output_signal === input_signals[2])
    );

    // Select 11 routes input_signals[3] to the output.
    check_select_11_routes_input3: assert property (
        @(posedge clk)
        (select_signals === 2'b11) |-> (output_signal === input_signals[3])
    );

    // With select 00 held, a stable input_signals[0] keeps the output stable.
    check_select_00_stable_input0_keeps_output_stable: assert property (
        @(posedge clk)
        ($stable(select_signals) && (select_signals === 2'b00) && $stable(input_signals[0])) |-> $stable(output_signal)
    );

    // With select 01 held, a stable input_signals[1] keeps the output stable.
    check_select_01_stable_input1_keeps_output_stable: assert property (
        @(posedge clk)
        ($stable(select_signals) && (select_signals === 2'b01) && $stable(input_signals[1])) |-> $stable(output_signal)
    );

    // With select 10 held, a stable input_signals[2] keeps the output stable.
    check_select_10_stable_input2_keeps_output_stable: assert property (
        @(posedge clk)
        ($stable(select_signals) && (select_signals === 2'b10) && $stable(input_signals[2])) |-> $stable(output_signal)
    );

    // With select 11 held, a stable input_signals[3] keeps the output stable.
    check_select_11_stable_input3_keeps_output_stable: assert property (
        @(posedge clk)
        ($stable(select_signals) && (select_signals === 2'b11) && $stable(input_signals[3])) |-> $stable(output_signal)
    );

endmodule

rtl:
module Adder(
    input [19:0] Data_A_i,
    input [19:0] Data_B_i,
    output [20:0] O,
    output CO,
    output [3:0] S,
    output [3:0] DI
);

  wire [20:0] O;
  wire CO;
  wire [3:0] S;
  wire [3:0] DI;

  assign O = Data_A_i + Data_B_i;
  assign CO = (O[20] == 1'b1);
  assign S = Data_A_i + Data_B_i + CO;
  assign DI = {CO, S[3:1]};

endmodule

sva:
module Adder_sva (
    input logic [19:0] Data_A_i,
    input logic [19:0] Data_B_i,
    input logic [20:0] O,
    input logic CO,
    input logic [3:0] S,
    input logic [3:0] DI
);

    // O is the 20-bit sum zero-extended to 21 bits.
    check_o_zero_extended_sum: assert property (
        @($global_clock) disable iff (1'b0)
        O == {1'b0, (Data_A_i + Data_B_i)}
    );

    // O[20] is always 0 because the sum is zero-extended.
    check_o_msb_zero: assert property (
        @($global_clock) disable iff (1'b0)
        O[20] == 1'b0
    );

    // CO follows the top bit of O.
    check_co_matches_o_msb: assert property (
        @($global_clock) disable iff (1'b0)
        CO == O[20]
    );

    // S is the low 4-bit sum of the inputs plus CO.
    check_s_low_nibble_sum: assert property (
        @($global_clock) disable iff (1'b0)
        S == (Data_A_i[3:0] + Data_B_i[3:0] + CO)
    );

    // DI packs CO with S[3:1].
    check_di_packing: assert property (
        @($global_clock) disable iff (1'b0)
        DI == {CO, S[3:1]}
    );

endmodule

rtl:
module mux_4to2(
  input in0,
  input in1,
  input in2,
  input in3,
  input [1:0] sel,
  output reg [1:0] out
);

always @(*) begin
  case(sel)
    2'b00: out = {in0, 1'b0};
    2'b01: out = {in1, 1'b0};
    2'b10: out = {in2, 1'b0};
    2'b11: out = {in3, 1'b0};
  endcase
end

endmodule

sva:
module mux_4to2_sva (
    input logic       clk,
    input logic       in0,
    input logic       in1,
    input logic       in2,
    input logic       in3,
    input logic [1:0] sel,
    input logic [1:0] out
);

    // The low output bit is always driven low.
    check_out_lsb_zero: assert property (
        @(posedge clk) out[0] == 1'b0
    );

    // sel=00 routes in0 to the high output bit.
    check_sel_00_routes_in0: assert property (
        @(posedge clk) (sel == 2'b00) |-> (out == {in0, 1'b0})
    );

    // sel=01 routes in1 to the high output bit.
    check_sel_01_routes_in1: assert property (
        @(posedge clk) (sel == 2'b01) |-> (out == {in1, 1'b0})
    );

    // sel=10 routes in2 to the high output bit.
    check_sel_10_routes_in2: assert property (
        @(posedge clk) (sel == 2'b10) |-> (out == {in2, 1'b0})
    );

    // sel=11 routes in3 to the high output bit.
    check_sel_11_routes_in3: assert property (
        @(posedge clk) (sel == 2'b11) |-> (out == {in3, 1'b0})
    );

endmodule

rtl:
module decoder_3to8 (
    input A,
    input B,
    input C,
    output reg Y0,
    output reg Y1,
    output reg Y2,
    output reg Y3,
    output reg Y4,
    output reg Y5,
    output reg Y6,
    output reg Y7
);

    always @ (A or B or C) begin
        case ({A,B,C})
            3'b000: begin
                Y0 = 0;
                Y1 = 1;
                Y2 = 1;
                Y3 = 1;
                Y4 = 1;
                Y5 = 1;
                Y6 = 1;
                Y7 = 1;
            end
            3'b001: begin
                Y0 = 1;
                Y1 = 0;
                Y2 = 1;
                Y3 = 1;
                Y4 = 1;
                Y5 = 1;
                Y6 = 1;
                Y7 = 1;
            end
            3'b010: begin
                Y0 = 1;
                Y1 = 1;
                Y2 = 0;
                Y3 = 1;
                Y4 = 1;
                Y5 = 1;
                Y6 = 1;
                Y7 = 1;
            end
            3'b011: begin
                Y0 = 1;
                Y1 = 1;
                Y2 = 1;
                Y3 = 0;
                Y4 = 1;
                Y5 = 1;
                Y6 = 1;
                Y7 = 1;
            end
            3'b100: begin
                Y0 = 1;
                Y1 = 1;
                Y2 = 1;
                Y3 = 1;
                Y4 = 0;
                Y5 = 1;
                Y6 = 1;
                Y7 = 1;
            end
            3'b101: begin
                Y0 = 1;
                Y1 = 1;
                Y2 = 1;
                Y3 = 1;
                Y4 = 1;
                Y5 = 0;
                Y6 = 1;
                Y7 = 1;
            end
            3'b110: begin
                Y0 = 1;
                Y1 = 1;
                Y2 = 1;
                Y3 = 1;
                Y4 = 1;
                Y5 = 1;
                Y6 = 0;
                Y7 = 1;
            end
            3'b111: begin
                Y0 = 1;
                Y1 = 1;
                Y2 = 1;
                Y3 = 1;
                Y4 = 1;
                Y5 = 1;
                Y6 = 1;
                Y7 = 0;
            end
        endcase
    end

endmodule

sva:
module decoder_3to8_sva (
    input logic A,
    input logic B,
    input logic C,
    input logic Y0,
    input logic Y1,
    input logic Y2,
    input logic Y3,
    input logic Y4,
    input logic Y5,
    input logic Y6,
    input logic Y7
);

    // Y0 is low only for input 3'b000.
    check_y0_decode: assert property (
        @($global_clock) Y0 == (A | B | C)
    );

    // Y1 is low only for input 3'b001.
    check_y1_decode: assert property (
        @($global_clock) Y1 == (A | B | ~C)
    );

    // Y2 is low only for input 3'b010.
    check_y2_decode: assert property (
        @($global_clock) Y2 == (A | ~B | C)
    );

    // Y3 is low only for input 3'b011.
    check_y3_decode: assert property (
        @($global_clock) Y3 == (A | ~B | ~C)
    );

    // Y4 is low only for input 3'b100.
    check_y4_decode: assert property (
        @($global_clock) Y4 == (~A | B | C)
    );

    // Y5 is low only for input 3'b101.
    check_y5_decode: assert property (
        @($global_clock) Y5 == (~A | B | ~C)
    );

    // Y6 is low only for input 3'b110.
    check_y6_decode: assert property (
        @($global_clock) Y6 == (~A | ~B | C)
    );

    // Y7 is low only for input 3'b111.
    check_y7_decode: assert property (
        @($global_clock) Y7 == (~A | ~B | ~C)
    );

    // Exactly one output is active low at any time.
    check_single_active_low: assert property (
        @($global_clock) $onehot({~Y7, ~Y6, ~Y5, ~Y4, ~Y3, ~Y2, ~Y1, ~Y0})
    );

    // The output bus matches the active-low one-hot decode of {A,B,C}.
    check_output_vector_decode: assert property (
        @($global_clock) {Y7, Y6, Y5, Y4, Y3, Y2, Y1, Y0} == ~(8'b00000001 << {A, B, C})
    );

endmodule

rtl:
module sky130_fd_sc_lp__a22o (
    X ,
    A1,
    A2,
    B1,
    B2
);

    output X ;
    input  A1;
    input  A2;
    input  B1;
    input  B2;

    wire and0_out ;
    wire and1_out ;
    wire or0_out_X;

    and and0 (and0_out , B1, B2            );
    and and1 (and1_out , A1, A2            );
    or  or0  (or0_out_X, and1_out, and0_out);
    buf buf0 (X        , or0_out_X         );

endmodule

sva:
module sky130_fd_sc_lp__a22o_sva (
    input logic clk,
    input logic X,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic B2
);

    // X must implement the OR of the two AND terms.
    check_output_equation: assert property (
        @(posedge clk) X == ((A1 & A2) | (B1 & B2))
    );

    // If A1 and A2 are both high, X must be high.
    check_a_term_drives_high: assert property (
        @(posedge clk) (A1 & A2) |-> X
    );

    // If B1 and B2 are both high, X must be high.
    check_b_term_drives_high: assert property (
        @(posedge clk) (B1 & B2) |-> X
    );

    // If neither AND term is active, X must be low.
    check_no_active_term_drives_low: assert property (
        @(posedge clk) !((A1 & A2) | (B1 & B2)) |-> !X
    );

    // If A1 and B1 are both low, both product terms are blocked and X must be low.
    check_a1_b1_low_forces_low: assert property (
        @(posedge clk) (!A1 && !B1) |-> !X
    );

    // If A2 and B2 are both low, both product terms are blocked and X must be low.
    check_a2_b2_low_forces_low: assert property (
        @(posedge clk) (!A2 && !B2) |-> !X
    );

endmodule

rtl:
module sky130_fd_sc_ms__a21bo (
    X   ,
    A1  ,
    A2  ,
    B1_N
);

    output X   ;
    input  A1  ;
    input  A2  ;
    input  B1_N;

    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    wire nand0_out  ;
    wire nand1_out_X;

    nand nand0 (nand0_out  , A2, A1         );
    nand nand1 (nand1_out_X, B1_N, nand0_out);
    buf  buf0  (X          , nand1_out_X    );

endmodule

sva:
module sky130_fd_sc_ms__a21bo_sva (
    input logic X,
    input logic A1,
    input logic A2,
    input logic B1_N
);

    // Purely combinational RTL; assertions are sampled on the formal global clock.

    // X matches the implemented NAND/NAND/BUF logic.
    check_functional_equivalence: assert property (
        @($global_clock) X == ~(B1_N & ~(A1 & A2))
    );

    // A low B1_N forces the final NAND output high.
    check_b1n_low_forces_x_high: assert property (
        @($global_clock) ~B1_N |-> X
    );

    // High A1 and A2 force X high.
    check_a1_a2_high_force_x_high: assert property (
        @($global_clock) (A1 & A2) |-> X
    );

    // With B1_N high, if A1 and A2 are not both high then X is low.
    check_b1n_high_and_not_a1a2_forces_x_low: assert property (
        @($global_clock) (B1_N & ~(A1 & A2)) |-> ~X
    );

    // If X is high while B1_N is high, both A1 and A2 must be high.
    check_x_high_with_b1n_high_requires_a1_a2_high: assert property (
        @($global_clock) (X & B1_N) |-> (A1 & A2)
    );

    // A low X can only occur when B1_N is high and at least one A input is low.
    check_x_low_characterization: assert property (
        @($global_clock) ~X |-> (B1_N & (~A1 | ~A2))
    );

endmodule

rtl:
module clock_gate (CLK, EN, TE, ENCLK);
  input CLK, EN, TE;
  output ENCLK;

  reg gated_clk;

  always @ (posedge CLK) begin
    if (EN && !TE) begin
      gated_clk <= 1;
    end else begin
      gated_clk <= 0;
    end
  end

  assign ENCLK = gated_clk & CLK;

endmodule

sva:
module clock_gate_sva (
    input logic CLK,
    input logic EN,
    input logic TE,
    input logic ENCLK,
    input logic gated_clk
);

    // gated_clk follows the previous cycle's EN && !TE decision.
    check_gated_clk_next_state: assert property (
        @(posedge CLK)
        1'b1 |=> (gated_clk === (($past(EN) === 1'b1) && ($past(TE) === 1'b0)))
    );

    // EN high with TE low sets gated_clk on the next sampled cycle.
    check_gate_sets_when_enabled: assert property (
        @(posedge CLK)
        ((EN === 1'b1) && (TE === 1'b0)) |=> (gated_clk === 1'b1)
    );

    // TE high forces gated_clk low on the next sampled cycle.
    check_te_forces_gate_low: assert property (
        @(posedge CLK)
        (TE === 1'b1) |=> (gated_clk === 1'b0)
    );

    // EN low forces gated_clk low on the next sampled cycle.
    check_en_low_forces_gate_low: assert property (
        @(posedge CLK)
        (EN === 1'b0) |=> (gated_clk === 1'b0)
    );

    // ENCLK is low at each rising-edge sample.
    check_enclk_low_on_posedge: assert property (
        @(posedge CLK)
        (ENCLK === 1'b0)
    );

    // ENCLK matches gated_clk while CLK is high.
    check_enclk_matches_gate_on_negedge: assert property (
        @(negedge CLK)
        (ENCLK === gated_clk)
    );

endmodule

rtl:
module absolute_value (
    input signed [31:0] in,
    output reg signed [31:0] out
);

    always @(*) begin
        if (in < 0) begin
            out = -in;
        end else begin
            out = in;
        end
    end

endmodule

sva:
module absolute_value_sva (
    input logic clk,
    input logic signed [31:0] in,
    input logic signed [31:0] out
);

    // Output matches the implemented conditional expression.
    check_absolute_value_function: assert property (
        @(posedge clk) out == ((in < 32'sd0) ? -in : in)
    );

    // Non-negative inputs pass through unchanged.
    check_nonnegative_passthrough: assert property (
        @(posedge clk) (in >= 32'sd0) |-> (out == in)
    );

    // Negative inputs produce the two's-complement negation.
    check_negative_negation: assert property (
        @(posedge clk) (in < 32'sd0) |-> (out == -in)
    );

    // Zero maps to zero.
    check_zero_maps_to_zero: assert property (
        @(posedge clk) (in == 32'sd0) |-> (out == 32'sd0)
    );

    // The most-negative input remains unchanged after negation overflow.
    check_min_negative_corner_case: assert property (
        @(posedge clk) (in == 32'sh80000000) |-> (out == 32'sh80000000)
    );

    // Negative inputs other than the minimum value yield non-negative outputs.
    check_negative_nonmin_yields_nonnegative: assert property (
        @(posedge clk) ((in < 32'sd0) && (in != 32'sh80000000)) |-> (out >= 32'sd0)
    );

endmodule

rtl:
module four_to_one_circuit (
    output X   ,
    input  A1  ,
    input  A2  ,
    input  B1  ,
    input  B2  ,
    input  VPWR,
    input  VGND,
    input  VPB ,
    input  VNB
);

    wire not_A1, not_A2, not_B1, not_B2;

    assign not_A1 = ~A1;
    assign not_A2 = ~A2;
    assign not_B1 = ~B1;
    assign not_B2 = ~B2;

    wire and1, and2, or1;

    assign and1 = not_A1 & not_A2 & not_B1 & B2;
    assign and2 = A1 & A2 & not_B1 & not_B2;
    assign or1 = and1 | and2;

    assign X = ~or1;

endmodule

sva:
module four_to_one_circuit_sva (
    input logic clk,
    input logic X,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic B2,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB
);

    // X matches the RTL boolean equation.
    check_output_matches_boolean_equation: assert property (
        @(posedge clk)
        X == ~(((~A1) & (~A2) & (~B1) & B2) | (A1 & A2 & (~B1) & (~B2)))
    );

    // The first product term forces X low.
    check_first_product_term_drives_low: assert property (
        @(posedge clk)
        ((~A1) & (~A2) & (~B1) & B2) |-> (X == 1'b0)
    );

    // The second product term forces X low.
    check_second_product_term_drives_low: assert property (
        @(posedge clk)
        (A1 & A2 & (~B1) & (~B2)) |-> (X == 1'b0)
    );

    // X can be low only for the two implemented minterms.
    check_low_output_only_in_implemented_cases: assert property (
        @(posedge clk)
        (X == 1'b0) |-> (((~A1) & (~A2) & (~B1) & B2) | (A1 & A2 & (~B1) & (~B2)))
    );

    // B1 high blocks both product terms and makes X high.
    check_b1_high_forces_high: assert property (
        @(posedge clk)
        (B1 == 1'b1) |-> (X == 1'b1)
    );

    // With B1 low and B2 high, X reduces to A1 OR A2.
    check_b1_low_b2_high_reduces_to_or: assert property (
        @(posedge clk)
        ((~B1) & B2) |-> (X == (A1 | A2))
    );

    // With B1 low and B2 low, X reduces to NOT(A1 AND A2).
    check_b1_low_b2_low_reduces_to_nand: assert property (
        @(posedge clk)
        ((~B1) & (~B2)) |-> (X == ~(A1 & A2))
    );

endmodule

rtl:
module sp_mux_4to1_sel2_7_1 #(
parameter
    ID                = 0,
    NUM_STAGE         = 1,
    din1_WIDTH       = 32,
    din2_WIDTH       = 32,
    din3_WIDTH       = 32,
    din4_WIDTH       = 32,
    din5_WIDTH         = 32,
    dout_WIDTH            = 32
)(
    input  [6 : 0]     din1,
    input  [6 : 0]     din2,
    input  [6 : 0]     din3,
    input  [6 : 0]     din4,
    input  [1 : 0]    din5,
    output [6 : 0]   dout);

wire [1 : 0]     sel;
wire [6 : 0]         mux_1_0;
wire [6 : 0]         mux_1_1;
wire [6 : 0]         mux_2_0;

assign sel = din5;

assign mux_1_0 = (sel[0] == 0)? din1 : din2;
assign mux_1_1 = (sel[0] == 0)? din3 : din4;

assign mux_2_0 = (sel[1] == 0)? mux_1_0 : mux_1_1;

assign dout = mux_2_0;

endmodule

sva:
module sp_mux_4to1_sel2_7_1_sva (
    input logic [6:0] din1,
    input logic [6:0] din2,
    input logic [6:0] din3,
    input logic [6:0] din4,
    input logic [1:0] din5,
    input logic [6:0] dout
);

    // dout must implement the RTL's nested 4-to-1 mux function.
    check_dout_matches_mux_function: assert property (
        @($global_clock)
        dout === ((din5[1] == 1'b0) ? ((din5[0] == 1'b0) ? din1 : din2)
                                    : ((din5[0] == 1'b0) ? din3 : din4))
    );

    // Select value 00 must route din1 to dout.
    check_select_00_routes_din1: assert property (
        @($global_clock)
        (din5 == 2'b00) |-> (dout === din1)
    );

    // Select value 01 must route din2 to dout.
    check_select_01_routes_din2: assert property (
        @($global_clock)
        (din5 == 2'b01) |-> (dout === din2)
    );

    // Select value 10 must route din3 to dout.
    check_select_10_routes_din3: assert property (
        @($global_clock)
        (din5 == 2'b10) |-> (dout === din3)
    );

    // Select value 11 must route din4 to dout.
    check_select_11_routes_din4: assert property (
        @($global_clock)
        (din5 == 2'b11) |-> (dout === din4)
    );

    // With select 00 held and din1 stable, dout must stay stable.
    check_select_00_ignores_unselected_inputs: assert property (
        @($global_clock)
        ($stable(din5) && (din5 == 2'b00) && $stable(din1)) |-> $stable(dout)
    );

    // With select 01 held and din2 stable, dout must stay stable.
    check_select_01_ignores_unselected_inputs: assert property (
        @($global_clock)
        ($stable(din5) && (din5 == 2'b01) && $stable(din2)) |-> $stable(dout)
    );

    // With select 10 held and din3 stable, dout must stay stable.
    check_select_10_ignores_unselected_inputs: assert property (
        @($global_clock)
        ($stable(din5) && (din5 == 2'b10) && $stable(din3)) |-> $stable(dout)
    );

    // With select 11 held and din4 stable, dout must stay stable.
    check_select_11_ignores_unselected_inputs: assert property (
        @($global_clock)
        ($stable(din5) && (din5 == 2'b11) && $stable(din4)) |-> $stable(dout)
    );

endmodule

rtl:
module decoder_3to8 (
    input [2:0] in,
    output reg [7:0] out
);

always @(*) begin
    case (in)
        3'b000: out = 8'b11111110;
        3'b001: out = 8'b11111101;
        3'b010: out = 8'b11111011;
        3'b011: out = 8'b11110111;
        3'b100: out = 8'b11101111;
        3'b101: out = 8'b11011111;
        3'b110: out = 8'b10111111;
        3'b111: out = 8'b01111111;
        default: out = 8'b11111111;
    endcase
end

endmodule

sva:
module decoder_3to8_sva (
    input logic clk,
    input logic [2:0] in,
    input logic [7:0] out
);

    // Input 000 drives only bit 0 low.
    check_decode_000: assert property (
        @(posedge clk) (in == 3'b000) |-> (out == 8'b11111110)
    );

    // Input 001 drives only bit 1 low.
    check_decode_001: assert property (
        @(posedge clk) (in == 3'b001) |-> (out == 8'b11111101)
    );

    // Input 010 drives only bit 2 low.
    check_decode_010: assert property (
        @(posedge clk) (in == 3'b010) |-> (out == 8'b11111011)
    );

    // Input 011 drives only bit 3 low.
    check_decode_011: assert property (
        @(posedge clk) (in == 3'b011) |-> (out == 8'b11110111)
    );

    // Input 100 drives only bit 4 low.
    check_decode_100: assert property (
        @(posedge clk) (in == 3'b100) |-> (out == 8'b11101111)
    );

    // Input 101 drives only bit 5 low.
    check_decode_101: assert property (
        @(posedge clk) (in == 3'b101) |-> (out == 8'b11011111)
    );

    // Input 110 drives only bit 6 low.
    check_decode_110: assert property (
        @(posedge clk) (in == 3'b110) |-> (out == 8'b10111111)
    );

    // Input 111 drives only bit 7 low.
    check_decode_111: assert property (
        @(posedge clk) (in == 3'b111) |-> (out == 8'b01111111)
    );

    // Known inputs produce an active-low one-hot output.
    check_active_low_onehot: assert property (
        @(posedge clk) !$isunknown(in) |-> $onehot(~out)
    );

    // Unknown input bits select the default all-high output.
    check_default_unknown_input: assert property (
        @(posedge clk) $isunknown(in) |-> (out == 8'b11111111)
    );

endmodule

rtl:
module data_parser(
  input [3:0] data_in,
  output reg [1:0] data_out_1,
  output reg [1:0] data_out_2,
  output reg parity
);

  always @(*) begin
    data_out_1 = data_in[1:0];
    data_out_2 = data_in[3:2];
    parity = ^data_in;
  end

endmodule

sva:
module data_parser_sva(
    input logic clk,
    input logic [3:0] data_in,
    input logic [1:0] data_out_1,
    input logic [1:0] data_out_2,
    input logic parity
);

    // data_out_1 mirrors the low two bits of data_in.
    check_data_out_1_slice: assert property (
        @(posedge clk) data_out_1 == data_in[1:0]
    );

    // data_out_2 mirrors the high two bits of data_in.
    check_data_out_2_slice: assert property (
        @(posedge clk) data_out_2 == data_in[3:2]
    );

    // parity is the reduction XOR of data_in.
    check_parity_from_input: assert property (
        @(posedge clk) parity == (^data_in)
    );

    // The two output fields reconstruct the full input bus.
    check_outputs_reconstruct_input: assert property (
        @(posedge clk) {data_out_2, data_out_1} == data_in
    );

    // parity matches the XOR of the split output fields.
    check_parity_from_outputs: assert property (
        @(posedge clk) parity == (^({data_out_2, data_out_1}))
    );

endmodule

rtl:
module absolute_value_calculator (
  input signed [7:0] input_num,
  output reg [7:0] abs_value
);

  always @(*) begin
    if (input_num < 0) begin
      abs_value = ~input_num + 1;
    end else begin
      abs_value = input_num;
    end
  end

endmodule

sva:
module absolute_value_calculator_sva (
    input logic clk,
    input logic signed [7:0] input_num,
    input logic [7:0] abs_value
);

    // Output always matches the RTL's conditional function.
    check_absolute_value_function: assert property (
        @(posedge clk)
        abs_value == ((input_num < 0) ? (~input_num + 8'd1) : input_num)
    );

    // Non-negative inputs pass through unchanged.
    check_non_negative_passthrough: assert property (
        @(posedge clk)
        (input_num >= 0) |-> (abs_value == input_num)
    );

    // Negative inputs produce the two's-complement magnitude.
    check_negative_twos_complement: assert property (
        @(posedge clk)
        (input_num < 0) |-> (abs_value == (~input_num + 8'd1))
    );

    // Zero maps to zero.
    check_zero_case: assert property (
        @(posedge clk)
        (input_num == 8'sd0) |-> (abs_value == 8'd0)
    );

    // Negative one maps to one.
    check_negative_one_case: assert property (
        @(posedge clk)
        (input_num == -8'sd1) |-> (abs_value == 8'd1)
    );

    // The most-negative input wraps to 8'h80 in 8-bit two's complement.
    check_min_negative_case: assert property (
        @(posedge clk)
        (input_num == 8'sh80) |-> (abs_value == 8'h80)
    );

    // A stable input must keep the output stable.
    check_stable_input_stable_output: assert property (
        @(posedge clk)
        $stable(input_num) |-> $stable(abs_value)
    );

endmodule

rtl:
module register_4bit (
    input CLK,
    input [3:0] D,
    input LD,
    input RST,
    output reg [3:0] Q
);

    // Local signals
    reg [3:0] reg_Q;
    reg [3:0] reg_Q_N;
    reg [3:0] mux_out;
    reg [3:0] rst_d;

    // Instantiate the flip-flop modules
    always @(posedge CLK or posedge RST) begin
        if (RST) begin
            reg_Q <= 4'b0;
        end else begin
            reg_Q <= mux_out;
        end
    end

    // 4-to-1 multiplexer to select between D input and buffered output
    always @* begin
        mux_out[0] = (LD) ? D[0] : reg_Q[0];
        mux_out[1] = (LD) ? D[1] : reg_Q[1];
        mux_out[2] = (LD) ? D[2] : reg_Q[2];
        mux_out[3] = (LD) ? D[3] : reg_Q[3];
    end

    // Asynchronous reset
    always @* begin
        rst_d = (RST) ? 4'b0 : 4'b1;
    end

    // Output
    always @* begin
        Q = reg_Q;
    end

endmodule

sva:
module register_4bit_sva (
    input logic CLK,
    input logic [3:0] D,
    input logic LD,
    input logic RST,
    input logic [3:0] Q
);

    // Reset forces the register output to zero.
    check_reset_clears_q: assert property (
        @(posedge CLK) RST |-> (Q == 4'b0000)
    );

    // A load captures D into Q on the next clock.
    check_load_captures_d: assert property (
        @(posedge CLK) disable iff (RST) LD |=> (Q == $past(D))
    );

    // With load deasserted, Q holds its previous value.
    check_hold_when_ld_low: assert property (
        @(posedge CLK) disable iff (RST) !LD |=> $stable(Q)
    );

    // Loading a new value causes Q to change to that value.
    check_load_new_value_changes_q: assert property (
        @(posedge CLK) disable iff (RST) (LD && (D != Q)) |=> ((Q == $past(D)) && !$stable(Q))
    );

    // Loading the current value leaves Q unchanged.
    check_load_same_value_keeps_q_stable: assert property (
        @(posedge CLK) disable iff (RST) (LD && (D == Q)) |=> $stable(Q)
    );

    // After reset release, Q stays zero if no load is requested.
    check_reset_release_keeps_zero_without_load: assert property (
        @(posedge CLK) RST ##1 (!RST && !LD) |-> (Q == 4'b0000)
    );

endmodule

rtl:
module ripple_carry_adder (
    input [3:0] a,
    input [3:0] b,
    input cin,
    output [3:0] sum,
    output cout
);

    wire [3:0] carry;
    assign carry[0] = cin;

    full_adder fa0(a[0], b[0], carry[0], sum[0], carry[1]);
    full_adder fa1(a[1], b[1], carry[1], sum[1], carry[2]);
    full_adder fa2(a[2], b[2], carry[2], sum[2], carry[3]);
    full_adder fa3(a[3], b[3], carry[3], sum[3], cout);

endmodule

module full_adder (
    input a,
    input b,
    input cin,
    output sum,
    output cout
);

    assign {cout, sum} = a + b + cin;

endmodule

sva:
module ripple_carry_adder_sva (
    input logic clk,
    input logic [3:0] a,
    input logic [3:0] b,
    input logic cin,
    input logic [3:0] sum,
    input logic cout
);

    function automatic logic carry3(
        input logic x,
        input logic y,
        input logic z
    );
        carry3 = (x & y) | (x & z) | (y & z);
    endfunction

    function automatic logic c1_fn(
        input logic [3:0] x,
        input logic [3:0] y,
        input logic c
    );
        c1_fn = carry3(x[0], y[0], c);
    endfunction

    function automatic logic c2_fn(
        input logic [3:0] x,
        input logic [3:0] y,
        input logic c
    );
        c2_fn = carry3(x[1], y[1], c1_fn(x, y, c));
    endfunction

    function automatic logic c3_fn(
        input logic [3:0] x,
        input logic [3:0] y,
        input logic c
    );
        c3_fn = carry3(x[2], y[2], c2_fn(x, y, c));
    endfunction

    function automatic logic c4_fn(
        input logic [3:0] x,
        input logic [3:0] y,
        input logic c
    );
        c4_fn = carry3(x[3], y[3], c3_fn(x, y, c));
    endfunction

    function automatic logic [4:0] add5_fn(
        input logic [3:0] x,
        input logic [3:0] y,
        input logic c
    );
        add5_fn = {1'b0, x} + {1'b0, y} + c;
    endfunction

    // Combined output must equal the 4-bit addition with carry in.
    check_total_addition: assert property (
        @(posedge clk) disable iff (1'b0)
        {cout, sum} == add5_fn(a, b, cin)
    );

    // Bit 0 sum matches the first full-adder stage.
    check_sum_bit0: assert property (
        @(posedge clk) disable iff (1'b0)
        sum[0] == (a[0] ^ b[0] ^ cin)
    );

    // Bit 1 sum uses the carry rippled from bit 0.
    check_sum_bit1: assert property (
        @(posedge clk) disable iff (1'b0)
        sum[1] == (a[1] ^ b[1] ^ c1_fn(a, b, cin))
    );

    // Bit 2 sum uses the carry rippled from bit 1.
    check_sum_bit2: assert property (
        @(posedge clk) disable iff (1'b0)
        sum[2] == (a[2] ^ b[2] ^ c2_fn(a, b, cin))
    );

    // Bit 3 sum uses the carry rippled from bit 2.
    check_sum_bit3: assert property (
        @(posedge clk) disable iff (1'b0)
        sum[3] == (a[3] ^ b[3] ^ c3_fn(a, b, cin))
    );

    // Carry out matches the final ripple carry.
    check_carry_out: assert property (
        @(posedge clk) disable iff (1'b0)
        cout == c4_fn(a, b, cin)
    );

    // Carry out must be low when the total is below 16.
    check_no_overflow_range: assert property (
        @(posedge clk) disable iff (1'b0)
        (add5_fn(a, b, cin) < 5'd16) |-> !cout
    );

    // Carry out must be high when the total is 16 or more.
    check_overflow_range: assert property (
        @(posedge clk) disable iff (1'b0)
        (add5_fn(a, b, cin) >= 5'd16) |-> cout
    );

    // Adding zero with no carry-in passes a through unchanged.
    check_b_zero_passthrough: assert property (
        @(posedge clk) disable iff (1'b0)
        (b == 4'b0000 && cin == 1'b0) |-> (sum == a && cout == 1'b0)
    );

    // Adding zero with no carry-in passes b through unchanged.
    check_a_zero_passthrough: assert property (
        @(posedge clk) disable iff (1'b0)
        (a == 4'b0000 && cin == 1'b0) |-> (sum == b && cout == 1'b0)
    );

endmodule

rtl:
module BLOCK1 ( PIN1, PIN2, GIN1, GIN2, PHI, POUT, GOUT );
input  PIN1;
input  PIN2;
input  GIN1;
input  GIN2;
input  PHI;
output POUT;
output GOUT;
   assign POUT =  ~ (PIN1 | PIN2);
   assign GOUT =  ~ (GIN2 & (PIN2 | GIN1));
endmodule

sva:
module BLOCK1_sva (
    input logic PIN1,
    input logic PIN2,
    input logic GIN1,
    input logic GIN2,
    input logic PHI,
    input logic POUT,
    input logic GOUT
);

    // POUT must implement the NOR of PIN1 and PIN2.
    check_pout_equation: assert property (
        @(posedge PHI) POUT == ~(PIN1 | PIN2)
    );

    // GOUT must implement the inverted AND of GIN2 with (PIN2 | GIN1).
    check_gout_equation: assert property (
        @(posedge PHI) GOUT == ~(GIN2 & (PIN2 | GIN1))
    );

    // If either PIN input is high, POUT must be low.
    check_pout_low_when_any_pin_high: assert property (
        @(posedge PHI) ((PIN1 == 1'b1) || (PIN2 == 1'b1)) |-> (POUT == 1'b0)
    );

    // If both PIN inputs are low, POUT must be high.
    check_pout_high_when_both_pins_low: assert property (
        @(posedge PHI) ((PIN1 == 1'b0) && (PIN2 == 1'b0)) |-> (POUT == 1'b1)
    );

    // If GIN2 is low, GOUT must be high.
    check_gout_high_when_gin2_low: assert property (
        @(posedge PHI) (GIN2 == 1'b0) |-> (GOUT == 1'b1)
    );

    // If both PIN2 and GIN1 are low, GOUT must be high.
    check_gout_high_when_or_term_low: assert property (
        @(posedge PHI) ((PIN2 == 1'b0) && (GIN1 == 1'b0)) |-> (GOUT == 1'b1)
    );

    // If GIN2 and PIN2 are high, GOUT must be low.
    check_gout_low_when_gin2_and_pin2_high: assert property (
        @(posedge PHI) ((GIN2 == 1'b1) && (PIN2 == 1'b1)) |-> (GOUT == 1'b0)
    );

    // If GIN2 and GIN1 are high, GOUT must be low.
    check_gout_low_when_gin2_and_gin1_high: assert property (
        @(posedge PHI) ((GIN2 == 1'b1) && (GIN1 == 1'b1)) |-> (GOUT == 1'b0)
    );

endmodule

rtl:
module and_gate(
    input a,
    input b,
    output y
);

    assign y = a & b;

endmodule

sva:
module and_gate_sva (
    input logic clk,
    input logic a,
    input logic b,
    input logic y
);

    // Output must match the AND of both inputs.
    check_and_function: assert property (
        @(posedge clk) y == (a & b)
    );

    // If input a is low, the output must be low.
    check_a_low_forces_y_low: assert property (
        @(posedge clk) !a |-> !y
    );

    // If input b is low, the output must be low.
    check_b_low_forces_y_low: assert property (
        @(posedge clk) !b |-> !y
    );

    // If both inputs are high, the output must be high.
    check_both_high_drives_y_high: assert property (
        @(posedge clk) (a && b) |-> y
    );

    // A high output requires both inputs to be high.
    check_y_high_implies_both_high: assert property (
        @(posedge clk) y |-> (a && b)
    );

endmodule

rtl:
module Mult4x4
(
 input wire [3:0] A,
 input wire [3:0] B,
 output wire [7:0] Result
);

wire [5:0] wResInt1,wResInt2;

assign wResInt1 = A * B[1:0];
assign wResInt2 = A * B[3:2];

assign Result = ((wResInt2<<2) + wResInt1);

endmodule

sva:
module Mult4x4_sva (
    input logic        clk,
    input logic [3:0]  A,
    input logic [3:0]  B,
    input logic [7:0]  Result
);

    // Result matches the RTL sum of the two partial products.
    check_result_equation: assert property (
        @(posedge clk) Result == (((A * B[3:2]) << 2) + (A * B[1:0]))
    );

    // Result is the zero-extended low 6 bits of the full 4x4 product.
    check_result_product_mod64: assert property (
        @(posedge clk) Result == ((A * B) & 8'h3F)
    );

    // The upper two bits of Result are always zero after the 6-bit arithmetic.
    check_result_upper_bits_zero: assert property (
        @(posedge clk) Result[7:6] == 2'b00
    );

    // A zero multiplicand forces a zero result.
    check_zero_a: assert property (
        @(posedge clk) (A == 4'h0) |-> (Result == 8'h00)
    );

    // A zero multiplier forces a zero result.
    check_zero_b: assert property (
        @(posedge clk) (B == 4'h0) |-> (Result == 8'h00)
    );

    // When the upper two bits of B are zero, the result matches the full product.
    check_low_range_full_product: assert property (
        @(posedge clk) (B[3:2] == 2'b00) |-> (Result == (A * B))
    );

    // When the lower two bits of B are zero, only the shifted upper partial product contributes.
    check_upper_path_only: assert property (
        @(posedge clk) (B[1:0] == 2'b00) |-> (Result == ((A * B[3:2]) << 2))
    );

    // A zero lower slice in B leaves the two least-significant result bits clear.
    check_upper_path_lsb_zero: assert property (
        @(posedge clk) (B[1:0] == 2'b00) |-> (Result[1:0] == 2'b00)
    );

    // Multiplication by 4 is represented exactly by the aligned upper partial product.
    check_b_four: assert property (
        @(posedge clk) (B == 4'h4) |-> (Result == (A * 4'd4))
    );

    // Stable inputs keep the combinational result stable across sampled cycles.
    check_stable_inputs_stable_result: assert property (
        @(posedge clk) ($stable(A) && $stable(B)) |-> $stable(Result)
    );

endmodule

rtl:
module mux_4_to_1(
    input D0, D1, D2, D3,
    input S0, S1,
    output reg Y
);

    always @* begin
        case ({S1,S0})
            2'b00: Y = D0;
            2'b01: Y = D1;
            2'b10: Y = D2;
            2'b11: Y = D3;
        endcase
    end

endmodule

sva:
module mux_4_to_1_sva (
    input logic D0,
    input logic D1,
    input logic D2,
    input logic D3,
    input logic S0,
    input logic S1,
    input logic Y
);

    // Select 00 routes D0 to Y.
    check_select_00_routes_d0: assert property (
        @($global_clock) ({S1, S0} === 2'b00) |-> (Y === D0)
    );

    // Select 01 routes D1 to Y.
    check_select_01_routes_d1: assert property (
        @($global_clock) ({S1, S0} === 2'b01) |-> (Y === D1)
    );

    // Select 10 routes D2 to Y.
    check_select_10_routes_d2: assert property (
        @($global_clock) ({S1, S0} === 2'b10) |-> (Y === D2)
    );

    // Select 11 routes D3 to Y.
    check_select_11_routes_d3: assert property (
        @($global_clock) ({S1, S0} === 2'b11) |-> (Y === D3)
    );

endmodule

rtl:
module four_bit_adder(clk, rst, a, b, cin, sum, cout);

  input clk, rst;
  input [3:0] a, b;
  input cin;
  output [3:0] sum;
  output cout;

  reg [3:0] sum_reg;
  reg cout_reg;

  always @(posedge clk) begin
    if (rst) begin
      sum_reg <= 4'b0;
      cout_reg <= 1'b0;
    end
    else begin
      sum_reg <= a + b + cin;
      cout_reg <= (a[3] & b[3]) | (a[3] & cin) | (b[3] & cin);
    end
  end

  assign sum = sum_reg;
  assign cout = cout_reg;

endmodule

sva:
module four_bit_adder_sva (
    input logic clk,
    input logic rst,
    input logic [3:0] a,
    input logic [3:0] b,
    input logic cin,
    input logic [3:0] sum,
    input logic cout
);

    // Reset forces outputs low on the next cycle.
    check_reset_clears_outputs: assert property (
        @(posedge clk) rst |=> (sum == 4'b0000 && cout == 1'b0)
    );

    // Sum reflects the previous cycle's registered addition.
    check_sum_matches_previous_inputs: assert property (
        @(posedge clk) disable iff (rst)
            $past(!rst) |-> (sum == ($past(a) + $past(b) + $past(cin)))
    );

    // Cout reflects the previous cycle's registered MSB majority logic.
    check_cout_matches_previous_inputs: assert property (
        @(posedge clk) disable iff (rst)
            $past(!rst) |-> (cout == (($past(a[3]) & $past(b[3])) |
                                      ($past(a[3]) & $past(cin))  |
                                      ($past(b[3]) & $past(cin))))
    );

    // With b and cin low, sum passes through the previous a.
    check_a_passthrough_when_b_and_cin_zero: assert property (
        @(posedge clk) disable iff (rst)
            ($past(!rst) && ($past(b) == 4'b0000) && ($past(cin) == 1'b0))
            |-> (sum == $past(a) && cout == 1'b0)
    );

    // With a and cin low, sum passes through the previous b.
    check_b_passthrough_when_a_and_cin_zero: assert property (
        @(posedge clk) disable iff (rst)
            ($past(!rst) && ($past(a) == 4'b0000) && ($past(cin) == 1'b0))
            |-> (sum == $past(b) && cout == 1'b0)
    );

    // All-zero inputs produce all-zero outputs on the next cycle.
    check_zero_inputs_produce_zero_outputs: assert property (
        @(posedge clk) disable iff (rst)
            ($past(!rst) && ($past(a) == 4'b0000) && ($past(b) == 4'b0000) && ($past(cin) == 1'b0))
            |-> (sum == 4'b0000 && cout == 1'b0)
    );

    // High previous MSBs on a and b force cout high.
    check_cout_high_for_msb_pair: assert property (
        @(posedge clk) disable iff (rst)
            ($past(!rst) && $past(a[3]) && $past(b[3])) |-> (cout == 1'b1)
    );

    // Low previous MSBs and low cin force cout low.
    check_cout_low_for_zero_msb_inputs: assert property (
        @(posedge clk) disable iff (rst)
            ($past(!rst) && !$past(a[3]) && !$past(b[3]) && !$past(cin)) |-> (cout == 1'b0)
    );

endmodule

module clock_gate_assertions (
    input logic clk,
    input logic en,
    input logic te,
    input logic enclk
);

    // enclk must equal the previous cycle's en && te value.
    check_enclk_matches_previous_inputs: assert property (
        @(posedge clk) !$initstate |-> (enclk == ($past(en) && $past(te)))
    );

    // If both en and te are high, enclk must be high on the next clock.
    check_enclk_sets_after_en_and_te_high: assert property (
        @(posedge clk) (en && te) |=> enclk
    );

    // If en is low, enclk must be low on the next clock.
    check_enclk_clears_after_en_low: assert property (
        @(posedge clk) !en |=> !enclk
    );

    // If te is low, enclk must be low on the next clock.
    check_enclk_clears_after_te_low: assert property (
        @(posedge clk) !te |=> !enclk
    );

endmodule

rtl:
module top_module (
    input [3:0] DIN,
    input [1:0] SHIFT,
    input [3:0] a,
    input [3:0] b,
    input cin,
    output cout,
    output [3:0] sum,
    output [3:0] DOUT
);

    wire [3:0] shifted_input;
    wire [3:0] adder_input;
    wire [3:0] adder_output;

    barrel_shifter barrel_shifter_inst(
        .DIN(DIN),
        .SHIFT(SHIFT),
        .DOUT(shifted_input)
    );

    four_bit_adder adder_inst(
        .a(a),
        .b(shifted_input),
        .cin(cin),
        .cout(cout),
        .sum(adder_output)
    );

    assign adder_input = b;

    assign sum = adder_output + adder_input + cin;
    assign DOUT = adder_output;

endmodule
module four_bit_adder (
    input [3:0] a,
    input [3:0] b,
    input cin,
    output cout,
    output [3:0] sum
);

    assign {cout, sum} = a + b + cin;

endmodule
module barrel_shifter (
    input [3:0] DIN,
    input [1:0] SHIFT,
    output [3:0] DOUT
);

    assign DOUT = {DIN[SHIFT[1]], DIN[SHIFT[0]], DIN[3], DIN[2]};

endmodule

sva:
module top_module_sva (
    input logic        clk,
    input logic [3:0]  DIN,
    input logic [1:0]  SHIFT,
    input logic [3:0]  a,
    input logic [3:0]  b,
    input logic        cin,
    input logic        cout,
    input logic [3:0]  sum,
    input logic [3:0]  DOUT
);

    // SHIFT=00 selects DIN[0], DIN[0], DIN[3], DIN[2] into the first adder.
    check_first_stage_shift_00: assert property (
        @(posedge clk)
        (SHIFT == 2'b00) |-> ({cout, DOUT} == ({1'b0, a} + {1'b0, {DIN[0], DIN[0], DIN[3], DIN[2]}} + cin))
    );

    // SHIFT=01 selects DIN[0], DIN[1], DIN[3], DIN[2] into the first adder.
    check_first_stage_shift_01: assert property (
        @(posedge clk)
        (SHIFT == 2'b01) |-> ({cout, DOUT} == ({1'b0, a} + {1'b0, {DIN[0], DIN[1], DIN[3], DIN[2]}} + cin))
    );

    // SHIFT=10 selects DIN[1], DIN[0], DIN[3], DIN[2] into the first adder.
    check_first_stage_shift_10: assert property (
        @(posedge clk)
        (SHIFT == 2'b10) |-> ({cout, DOUT} == ({1'b0, a} + {1'b0, {DIN[1], DIN[0], DIN[3], DIN[2]}} + cin))
    );

    // SHIFT=11 selects DIN[1], DIN[1], DIN[3], DIN[2] into the first adder.
    check_first_stage_shift_11: assert property (
        @(posedge clk)
        (SHIFT == 2'b11) |-> ({cout, DOUT} == ({1'b0, a} + {1'b0, {DIN[1], DIN[1], DIN[3], DIN[2]}} + cin))
    );

    // sum is DOUT plus b plus cin, truncated to 4 bits.
    check_sum_from_dout_b_cin: assert property (
        @(posedge clk)
        ({1'b0, sum} == (({1'b0, DOUT} + {1'b0, b} + cin) & 5'h0f))
    );

    // DOUT and cout do not depend on b.
    check_first_stage_independent_of_b: assert property (
        @(posedge clk)
        ($stable(DIN) && $stable(SHIFT) && $stable(a) && $stable(cin)) |-> ($stable(DOUT) && $stable(cout))
    );

    // sum depends only on DOUT, b, and cin.
    check_sum_stable_when_inputs_stable: assert property (
        @(posedge clk)
        ($stable(DOUT) && $stable(b) && $stable(cin)) |-> $stable(sum)
    );

    // With b and cin both zero, sum matches DOUT.
    check_sum_equals_dout_when_b_and_cin_zero: assert property (
        @(posedge clk)
        ((b == 4'h0) && (cin == 1'b0)) |-> (sum == DOUT)
    );

    // All outputs remain stable when all inputs remain stable.
    check_outputs_stable_when_all_inputs_stable: assert property (
        @(posedge clk)
        ($stable(DIN) && $stable(SHIFT) && $stable(a) && $stable(b) && $stable(cin)) |-> ($stable(cout) && $stable(sum) && $stable(DOUT))
    );

endmodule

rtl:
module mux4(
    input A0, A1, A2, A3, S0, S1, VPWR, VGND, VPB, VNB,
    output X
);

wire w1, w2, w3;

assign w1 = (~S1 & ~S0) ? A0 : (~S1 & S0) ? A1 : (S1 & ~S0) ? A2 : A3;
assign w2 = (VGND == 0) ? 0 : VPWR;
assign w3 = (VPB == 0) ? 0 : VNB;

assign X = (w1 & w2 & w3);

endmodule

sva:
module mux4_sva (
    input logic clk,
    input logic A0,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic S0,
    input logic S1,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB,
    input logic X
);

    // X must match the RTL mux and gating function.
    check_output_matches_rtl_function: assert property (
        @(posedge clk)
        X == (
            (
                ((S1 == 1'b0) && (S0 == 1'b0)) ? A0 :
                ((S1 == 1'b0) && (S0 == 1'b1)) ? A1 :
                ((S1 == 1'b1) && (S0 == 1'b0)) ? A2 :
                A3
            ) &
            ((VGND == 1'b0) ? 1'b0 : VPWR) &
            ((VPB  == 1'b0) ? 1'b0 : VNB)
        )
    );

    // Select 00 routes A0 through the power gating.
    check_select_00_uses_a0: assert property (
        @(posedge clk)
        ((S1 == 1'b0) && (S0 == 1'b0)) |->
        (X == (A0 & ((VGND == 1'b0) ? 1'b0 : VPWR) & ((VPB == 1'b0) ? 1'b0 : VNB)))
    );

    // Select 01 routes A1 through the power gating.
    check_select_01_uses_a1: assert property (
        @(posedge clk)
        ((S1 == 1'b0) && (S0 == 1'b1)) |->
        (X == (A1 & ((VGND == 1'b0) ? 1'b0 : VPWR) & ((VPB == 1'b0) ? 1'b0 : VNB)))
    );

    // Select 10 routes A2 through the power gating.
    check_select_10_uses_a2: assert property (
        @(posedge clk)
        ((S1 == 1'b1) && (S0 == 1'b0)) |->
        (X == (A2 & ((VGND == 1'b0) ? 1'b0 : VPWR) & ((VPB == 1'b0) ? 1'b0 : VNB)))
    );

    // Select 11 routes A3 through the power gating.
    check_select_11_uses_a3: assert property (
        @(posedge clk)
        ((S1 == 1'b1) && (S0 == 1'b1)) |->
        (X == (A3 & ((VGND == 1'b0) ? 1'b0 : VPWR) & ((VPB == 1'b0) ? 1'b0 : VNB)))
    );

    // VGND low forces the output low.
    check_vgnd_low_forces_x_low: assert property (
        @(posedge clk)
        (VGND == 1'b0) |-> (X == 1'b0)
    );

    // VPB low forces the output low.
    check_vpb_low_forces_x_low: assert property (
        @(posedge clk)
        (VPB == 1'b0) |-> (X == 1'b0)
    );

    // With VGND high, low VPWR blocks the output.
    check_vpwr_low_blocks_x: assert property (
        @(posedge clk)
        ((VGND == 1'b1) && (VPWR == 1'b0)) |-> (X == 1'b0)
    );

    // With VPB high, low VNB blocks the output.
    check_vnb_low_blocks_x: assert property (
        @(posedge clk)
        ((VPB == 1'b1) && (VNB == 1'b0)) |-> (X == 1'b0)
    );

    // With all power controls high, X reduces to a plain 4:1 mux.
    check_fully_enabled_path_behaves_as_mux: assert property (
        @(posedge clk)
        ((VGND == 1'b1) && (VPB == 1'b1) && (VPWR == 1'b1) && (VNB == 1'b1)) |->
        (
            X == (
                ((S1 == 1'b0) && (S0 == 1'b0)) ? A0 :
                ((S1 == 1'b0) && (S0 == 1'b1)) ? A1 :
                ((S1 == 1'b1) && (S0 == 1'b0)) ? A2 :
                A3
            )
        )
    );

endmodule

rtl:
module add2_and_round
  #(parameter WIDTH=16)
    (input [WIDTH-1:0] in1,
     input [WIDTH-1:0] in2,
     output [WIDTH-1:0] sum);

   wire [WIDTH:0] sum_int;
   wire [WIDTH-1:0] sum_half;
  // wire [WIDTH-1:0] sum_rounded;

   assign sum_int = in1 + in2;
   assign sum_half = sum_int[WIDTH-1:0] + (sum_int[WIDTH] ? 1 : 0);
   assign sum = sum_half;

endmodule
module add2_and_round_reg
  #(parameter WIDTH=16)
    (input clk,
     input [WIDTH-1:0] in1,
     input [WIDTH-1:0] in2,
     output reg [WIDTH-1:0] sum);

   wire [WIDTH-1:0] sum_int;

   add2_and_round #(.WIDTH(WIDTH)) add2_n_rnd (.in1(in1),.in2(in2),.sum(sum_int));

   always @(posedge clk)
     sum <= sum_int;

endmodule

sva:
module add2_and_round_reg_sva
  #(parameter WIDTH=16)
  (
    input logic clk,
    input logic [WIDTH-1:0] in1,
    input logic [WIDTH-1:0] in2,
    input logic [WIDTH-1:0] sum
  );

    // Without carry-out, the registered sum is the truncated addition.
    check_no_carry_rounding: assert property (
        @(posedge clk)
        !$initstate &&
        (({1'b0, $past(in1)} + {1'b0, $past(in2)}) < {1'b1, {WIDTH{1'b0}}})
        |-> (sum == ($past(in1) + $past(in2)))
    );

    // With carry-out, the registered sum adds the carry back in.
    check_carry_rounding: assert property (
        @(posedge clk)
        !$initstate &&
        (({1'b0, $past(in1)} + {1'b0, $past(in2)}) >= {1'b1, {WIDTH{1'b0}}})
        |-> (sum == ($past(in1) + $past(in2) + 1'b1))
    );

    // Two zero inputs produce a zero output on the next clock.
    check_zero_inputs: assert property (
        @(posedge clk)
        !$initstate &&
        ($past(in1) == {WIDTH{1'b0}}) &&
        ($past(in2) == {WIDTH{1'b0}})
        |-> (sum == {WIDTH{1'b0}})
    );

    // A zero output can only come from two zero inputs.
    check_zero_output_only_from_zero_inputs: assert property (
        @(posedge clk)
        !$initstate &&
        (sum == {WIDTH{1'b0}})
        |-> (($past(in1) == {WIDTH{1'b0}}) &&
             ($past(in2) == {WIDTH{1'b0}}))
    );

    // A zero in1 passes in2 through to the registered output.
    check_in1_zero_passthrough: assert property (
        @(posedge clk)
        !$initstate &&
        ($past(in1) == {WIDTH{1'b0}})
        |-> (sum == $past(in2))
    );

    // A zero in2 passes in1 through to the registered output.
    check_in2_zero_passthrough: assert property (
        @(posedge clk)
        !$initstate &&
        ($past(in2) == {WIDTH{1'b0}})
        |-> (sum == $past(in1))
    );

    // All-ones plus one returns one after the end-around carry.
    check_all_ones_plus_one_returns_one: assert property (
        @(posedge clk)
        !$initstate &&
        ((($past(in1) == {WIDTH{1'b1}}) && ($past(in2) == 1'b1)) ||
         (($past(in2) == {WIDTH{1'b1}}) && ($past(in1) == 1'b1)))
        |-> (sum == 1'b1)
    );

    // All-ones plus all-ones returns all-ones after rounding.
    check_all_ones_plus_all_ones: assert property (
        @(posedge clk)
        !$initstate &&
        ($past(in1) == {WIDTH{1'b1}}) &&
        ($past(in2) == {WIDTH{1'b1}})
        |-> (sum == {WIDTH{1'b1}})
    );

endmodule

rtl:
module incrementer(input clk, input wire signed [31:0] in, output reg signed [31:0] out);
   always @(posedge clk) begin
      out <= in + 1;
   end
endmodule

sva:
module incrementer_assertions (
    input logic clk,
    input logic signed [31:0] in,
    input logic signed [31:0] out
);

    // Out is the previous cycle's input incremented by one.
    check_registered_increment: assert property (
        @(posedge clk) 1'b1 |=> (out == ($past(in) + 32'sd1))
    );

    // Zero increments to one on the next clock.
    check_zero_to_one: assert property (
        @(posedge clk) (in == 32'sd0) |=> (out == 32'sd1)
    );

    // Minus one increments to zero on the next clock.
    check_minus_one_to_zero: assert property (
        @(posedge clk) (in == -32'sd1) |=> (out == 32'sd0)
    );

    // Maximum positive value wraps to minimum negative on the next clock.
    check_positive_overflow_wrap: assert property (
        @(posedge clk) (in == 32'sh7fffffff) |=> (out == 32'sh80000000)
    );

    // Minimum negative value increments to the next signed value.
    check_negative_min_to_next: assert property (
        @(posedge clk) (in == 32'sh80000000) |=> (out == 32'sh80000001)
    );

endmodule

rtl:
module signal_combiner (
    input [3:0] input_signals,
    output output_signal
);

wire[1:0] input_sum;

assign input_sum[0] = input_signals[0] ^ input_signals[1];
assign input_sum[1] = input_signals[2] ^ input_signals[3];

assign output_signal = input_sum[0] ^ input_sum[1];

endmodule

sva:
module signal_combiner_sva (
    input logic       clk,
    input logic [3:0] input_signals,
    input logic       output_signal
);

    // Output matches the XOR tree implemented in the RTL.
    check_output_matches_xor_tree: assert property (
        @(posedge clk)
        output_signal == ((input_signals[0] ^ input_signals[1]) ^ (input_signals[2] ^ input_signals[3]))
    );

    // Output is the parity of all four input bits.
    check_output_matches_reduction_xor: assert property (
        @(posedge clk)
        output_signal == ^input_signals
    );

    // If the lower pair XOR is 0, the output equals the upper pair XOR.
    check_lower_pair_equal_passes_upper_pair: assert property (
        @(posedge clk)
        ((input_signals[0] ^ input_signals[1]) == 1'b0) |-> (output_signal == (input_signals[2] ^ input_signals[3]))
    );

    // If the lower pair XOR is 1, the output is the inverse of the upper pair XOR.
    check_lower_pair_diff_flips_upper_pair: assert property (
        @(posedge clk)
        ((input_signals[0] ^ input_signals[1]) == 1'b1) |-> (output_signal == ~(input_signals[2] ^ input_signals[3]))
    );

    // If the upper pair XOR is 0, the output equals the lower pair XOR.
    check_upper_pair_equal_passes_lower_pair: assert property (
        @(posedge clk)
        ((input_signals[2] ^ input_signals[3]) == 1'b0) |-> (output_signal == (input_signals[0] ^ input_signals[1]))
    );

    // If the upper pair XOR is 1, the output is the inverse of the lower pair XOR.
    check_upper_pair_diff_flips_lower_pair: assert property (
        @(posedge clk)
        ((input_signals[2] ^ input_signals[3]) == 1'b1) |-> (output_signal == ~(input_signals[0] ^ input_signals[1]))
    );

    // Equal pair parities force the output low.
    check_matching_pair_parities_drive_zero: assert property (
        @(posedge clk)
        ((input_signals[0] ^ input_signals[1]) == (input_signals[2] ^ input_signals[3])) |-> (output_signal == 1'b0)
    );

    // Different pair parities force the output high.
    check_different_pair_parities_drive_one: assert property (
        @(posedge clk)
        ((input_signals[0] ^ input_signals[1]) != (input_signals[2] ^ input_signals[3])) |-> (output_signal == 1'b1)
    );

endmodule

module shift_register_4bit_sva(
    input logic clk,
    input logic rst,
    input logic load,
    input logic [3:0] data_in,
    input logic shift,
    input logic [3:0] data_out
);

    // Reset forces the register output low.
    check_reset_clears_data_out: assert property (
        @(posedge clk) !rst |-> (data_out == 4'b0000)
    );

    // Load alone captures data_in on the next clock.
    check_load_captures_data_in: assert property (
        @(posedge clk) disable iff (!rst)
        (load && !shift) |=> (data_out == $past(data_in))
    );

    // Load has priority when load and shift are both asserted.
    check_load_priority_over_shift: assert property (
        @(posedge clk) disable iff (!rst)
        (load && shift) |=> (data_out == $past(data_in))
    );

    // Shift alone moves the register left and inserts zero.
    check_shift_left_with_zero_fill: assert property (
        @(posedge clk) disable iff (!rst)
        (!load && shift) |=> (data_out == {$past(data_out[2:0]), 1'b0})
    );

    // With no load or shift, the register holds its value.
    check_idle_holds_value: assert property (
        @(posedge clk) disable iff (!rst)
        (!load && !shift) |=> (data_out == $past(data_out))
    );

endmodule

rtl:
module binary_adder(
    input [3:0] A, 
    input [3:0] B, 
    input CIN, 
    output [3:0] S, 
    output COUT
);

    wire [3:0] sum;
    wire [3:0] carry;

    // Full Adder
    full_adder fa0(.A(A[0]), .B(B[0]), .CIN(CIN), .S(sum[0]), .COUT(carry[0]));
    full_adder fa1(.A(A[1]), .B(B[1]), .CIN(carry[0]), .S(sum[1]), .COUT(carry[1]));
    full_adder fa2(.A(A[2]), .B(B[2]), .CIN(carry[1]), .S(sum[2]), .COUT(carry[2]));
    full_adder fa3(.A(A[3]), .B(B[3]), .CIN(carry[2]), .S(sum[3]), .COUT(COUT));

    assign S = sum;

endmodule

module full_adder(
    input A, 
    input B, 
    input CIN, 
    output S, 
    output COUT
);

    assign S = A ^ B ^ CIN;
    assign COUT = (A & B) | (CIN & (A ^ B));

endmodule

sva:
module binary_adder_sva(
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic CIN,
    input logic [3:0] S,
    input logic COUT
);

    // No RTL clock or reset exists; clk is an external sampling clock for this combinational DUT.

    function automatic logic carry0_exp(
        input logic [3:0] a,
        input logic [3:0] b,
        input logic cin
    );
        carry0_exp = (a[0] & b[0]) | (cin & (a[0] ^ b[0]));
    endfunction

    function automatic logic carry1_exp(
        input logic [3:0] a,
        input logic [3:0] b,
        input logic cin
    );
        carry1_exp = (a[1] & b[1]) | (carry0_exp(a, b, cin) & (a[1] ^ b[1]));
    endfunction

    function automatic logic carry2_exp(
        input logic [3:0] a,
        input logic [3:0] b,
        input logic cin
    );
        carry2_exp = (a[2] & b[2]) | (carry1_exp(a, b, cin) & (a[2] ^ b[2]));
    endfunction

    // Full 5-bit result matches A + B + CIN.
    check_full_add_result: assert property (
        @(posedge clk) {COUT, S} == ({1'b0, A} + {1'b0, B} + {4'b0000, CIN})
    );

    // Bit 0 sum follows the first full-adder equation.
    check_sum_bit0: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0] ^ CIN)
    );

    // Bit 1 sum uses the carry from bit 0.
    check_sum_bit1: assert property (
        @(posedge clk) S[1] == (A[1] ^ B[1] ^ carry0_exp(A, B, CIN))
    );

    // Bit 2 sum uses the carry from bit 1.
    check_sum_bit2: assert property (
        @(posedge clk) S[2] == (A[2] ^ B[2] ^ carry1_exp(A, B, CIN))
    );

    // Bit 3 sum uses the carry from bit 2.
    check_sum_bit3: assert property (
        @(posedge clk) S[3] == (A[3] ^ B[3] ^ carry2_exp(A, B, CIN))
    );

    // Final carry-out follows the last full-adder equation.
    check_final_carry: assert property (
        @(posedge clk) COUT == ((A[3] & B[3]) | (carry2_exp(A, B, CIN) & (A[3] ^ B[3])))
    );

    // Outputs stay stable when sampled inputs stay stable.
    check_outputs_stable_when_inputs_stable: assert property (
        @(posedge clk) ($stable(A) && $stable(B) && $stable(CIN)) |-> ($stable(S) && $stable(COUT))
    );

endmodule

rtl:
module full_adder (
  input A,
  input B,
  input Cin,
  output reg S,
  output reg Cout
);

  always @ (A, B, Cin) begin
    S = A ^ B ^ Cin;
    Cout = (A & B) | (Cin & (A ^ B));
  end

endmodule


module four_bit_adder (
  input [3:0] A,
  input [3:0] B,
  input Cin,
  output [3:0] S,
  output Cout
);

  wire c1, c2, c3;
  full_adder fa1(A[0], B[0], Cin, S[0], c1);
  full_adder fa2(A[1], B[1], c1, S[1], c2);
  full_adder fa3(A[2], B[2], c2, S[2], c3);
  full_adder fa4(A[3], B[3], c3, S[3], Cout);

endmodule

sva:
module four_bit_adder_sva (
    input logic       clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic       Cin,
    input logic [3:0] S,
    input logic       Cout
);

    // The 5-bit output must equal A + B + Cin.
    check_full_sum_match: assert property (
        @(posedge clk)
        {Cout, S} == ({1'b0, A} + {1'b0, B} + Cin)
    );

    // Bit 0 sum follows the first full-adder equation.
    check_sum_bit0_equation: assert property (
        @(posedge clk)
        S[0] == (A[0] ^ B[0] ^ Cin)
    );

    // Bit 1 sum uses the carry generated by bit 0.
    check_sum_bit1_ripple: assert property (
        @(posedge clk)
        S[1] == (
            A[1] ^ B[1] ^
            ((A[0] & B[0]) | (Cin & (A[0] ^ B[0])))
        )
    );

    // Bit 2 sum uses the carry generated by bits 0 and 1.
    check_sum_bit2_ripple: assert property (
        @(posedge clk)
        S[2] == (
            A[2] ^ B[2] ^
            (
                (A[1] & B[1]) |
                (
                    ((A[0] & B[0]) | (Cin & (A[0] ^ B[0])))
                    & (A[1] ^ B[1])
                )
            )
        )
    );

    // Bit 3 sum uses the carry generated by bits 0 through 2.
    check_sum_bit3_ripple: assert property (
        @(posedge clk)
        S[3] == (
            A[3] ^ B[3] ^
            (
                (A[2] & B[2]) |
                (
                    (
                        (A[1] & B[1]) |
                        (
                            ((A[0] & B[0]) | (Cin & (A[0] ^ B[0])))
                            & (A[1] ^ B[1])
                        )
                    )
                    & (A[2] ^ B[2])
                )
            )
        )
    );

    // Carry-out matches the final ripple-carry equation.
    check_cout_ripple: assert property (
        @(posedge clk)
        Cout == (
            (A[3] & B[3]) |
            (
                (
                    (A[2] & B[2]) |
                    (
                        (
                            (A[1] & B[1]) |
                            (
                                ((A[0] & B[0]) | (Cin & (A[0] ^ B[0])))
                                & (A[1] ^ B[1])
                            )
                        )
                        & (A[2] ^ B[2])
                    )
                )
                & (A[3] ^ B[3])
            )
        )
    );

endmodule

