module full_adder (
    input A,
    input B,
    input CI,
    output COUT,
    output SUM
);

wire temp_sum;

one_bit_adder u_o1(.A(A), .B(B), .CI(CI), .COUT(COUT), .SUM(temp_sum));
assign SUM = temp_sum ^ CI;

endmodule
module one_bit_adder (
    input A,
    input B,
    input CI,
    output COUT,
    output SUM
);
    assign SUM = (A ^ B) ^ CI;
    assign COUT = (A & B) | (A & CI) | (B & CI);
endmodule
module four_bit_adder (
    input [3:0] A,
    input [3:0] B,
    input CI,
    output [3:0] SUM,
    output COUT
);

wire C1, C2, C3;
full_adder u_f1(.A(A[0]), .B(B[0]), .CI(CI), .COUT(C1), .SUM(SUM[0]));
full_adder u_f2(.A(A[1]), .B(B[1]), .CI(C1), .COUT(C2), .SUM(SUM[1]));
full_adder u_f3(.A(A[2]), .B(B[2]), .CI(C2), .COUT(C3), .SUM(SUM[2]));
full_adder u_f4(.A(A[3]), .B(B[3]), .CI(C3), .COUT(COUT), .SUM(SUM[3]));

endmodule

sva:
module four_bit_adder_sva (
    input logic        clk,
    input logic [3:0]  A,
    input logic [3:0]  B,
    input logic        CI,
    input logic [3:0]  SUM,
    input logic        COUT
);

    // SUM is the bitwise XOR of A and B.
    check_sum_matches_bitwise_xor: assert property (
        @(posedge clk) SUM == (A ^ B)
    );

    // COUT matches the arithmetic carry-out of A + B + CI.
    check_cout_matches_arithmetic_carry: assert property (
        @(posedge clk) COUT == (({1'b0, A} + {1'b0, B} + {4'b0, CI}) >= 5'd16)
    );

    // Changing CI alone does not change SUM.
    check_sum_ignores_carry_in_changes: assert property (
        @(posedge clk) ($stable(A) && $stable(B) && $changed(CI)) |-> $stable(SUM)
    );

    // Equal operands force all SUM bits low.
    check_equal_operands_force_zero_sum: assert property (
        @(posedge clk) (A == B) |-> (SUM == 4'b0000)
    );

    // Complementary operands force all SUM bits high and propagate CI to COUT.
    check_complementary_operands_propagate_carry: assert property (
        @(posedge clk) (A == ~B) |-> ((SUM == 4'b1111) && (COUT == CI))
    );

    // Zero operands clear both SUM and COUT.
    check_zero_operands_clear_outputs: assert property (
        @(posedge clk) (A == 4'b0000 && B == 4'b0000) |-> ((SUM == 4'b0000) && (COUT == 1'b0))
    );

    // All-one operands force zero SUM and a asserted carry-out.
    check_all_ones_operands_generate_carry: assert property (
        @(posedge clk) (A == 4'b1111 && B == 4'b1111) |-> ((SUM == 4'b0000) && (COUT == 1'b1))
    );

endmodule

module bus_hold_sva #(
    parameter n = 8
) (
    input  logic [n-1:0] bus_in,
    input  logic         clk,
    input  logic         reset,
    input  logic [n-1:0] bus_out
);

    // Reset forces the output to zero on the sampled cycle.
    check_reset_forces_zero: assert property (
        @(posedge clk) reset |-> (bus_out == '0)
    );

    // A sampled reset leaves the output at zero on the following cycle.
    check_reset_clears_output_next_cycle: assert property (
        @(posedge clk) reset |=> (bus_out == '0)
    );

    // In consecutive non-reset cycles, the output reflects the prior input sample.
    check_output_tracks_previous_input: assert property (
        @(posedge clk) disable iff (reset) 1'b1 |=> (bus_out == $past(bus_in))
    );

endmodule

rtl:
module comparator (
    input [7:0] A,
    input [7:0] B,
    output reg EQ,
    output reg GT,
    input clk
);

reg [7:0] A_reg, B_reg;
reg [2:0] stage;

always @(posedge clk) begin
    case(stage)
        0: begin
            A_reg <= A;
            B_reg <= B;
            stage <= 1;
        end
        1: begin
            if(A_reg == B_reg) begin
                EQ <= 1;
                GT <= 0;
            end
            else if(A_reg > B_reg) begin
                EQ <= 0;
                GT <= 1;
            end
            else begin
                EQ <= 0;
                GT <= 0;
            end
            stage <= 2;
        end
        2: begin
            EQ <= 0;
            GT <= 0;
            stage <= 0;
        end
    endcase
end

endmodule

sva:
module comparator_sva (
    input logic [7:0] A,
    input logic [7:0] B,
    input logic EQ,
    input logic GT,
    input logic clk,
    input logic [7:0] A_reg,
    input logic [7:0] B_reg,
    input logic [2:0] stage
);

    // Stage 0 captures the current inputs.
    check_stage0_captures_inputs: assert property (
        @(posedge clk)
        (stage === 3'd0) |=> (stage === 3'd1 && A_reg === $past(A) && B_reg === $past(B))
    );

    // Stage 0 does not change the outputs.
    check_stage0_holds_outputs: assert property (
        @(posedge clk)
        (stage === 3'd0) |=> (EQ === $past(EQ) && GT === $past(GT))
    );

    // Stage 1 advances and keeps the captured operands stable.
    check_stage1_advances_and_holds_operands: assert property (
        @(posedge clk)
        (stage === 3'd1) |=> (stage === 3'd2 && A_reg === $past(A_reg) && B_reg === $past(B_reg))
    );

    // Equal captured operands set EQ and clear GT.
    check_stage1_equal_result: assert property (
        @(posedge clk)
        (stage === 3'd1 && ((A_reg == B_reg) === 1'b1))
        |=> (stage === 3'd2 && EQ === 1'b1 && GT === 1'b0)
    );

    // Greater captured operands clear EQ and set GT.
    check_stage1_greater_result: assert property (
        @(posedge clk)
        (stage === 3'd1 && ((A_reg == B_reg) !== 1'b1) && ((A_reg > B_reg) === 1'b1))
        |=> (stage === 3'd2 && EQ === 1'b0 && GT === 1'b1)
    );

    // The stage 1 else path clears both outputs.
    check_stage1_else_result: assert property (
        @(posedge clk)
        (stage === 3'd1 && ((A_reg == B_reg) !== 1'b1) && ((A_reg > B_reg) !== 1'b1))
        |=> (stage === 3'd2 && EQ === 1'b0 && GT === 1'b0)
    );

    // Stage 2 clears the outputs and returns to stage 0.
    check_stage2_clears_outputs_and_wraps: assert property (
        @(posedge clk)
        (stage === 3'd2) |=> (stage === 3'd0 && EQ === 1'b0 && GT === 1'b0 &&
                              A_reg === $past(A_reg) && B_reg === $past(B_reg))
    );

    // Unhandled stage values leave all state unchanged.
    check_invalid_stage_holds_state: assert property (
        @(posedge clk)
        (stage !== 3'd0 && stage !== 3'd1 && stage !== 3'd2)
        |=> (stage === $past(stage) && A_reg === $past(A_reg) && B_reg === $past(B_reg) &&
             EQ === $past(EQ) && GT === $past(GT))
    );

endmodule

