module pipereg_w32(clk,resetn,d,squashn,en,q);

input clk;
input resetn;
input en;
input squashn;
input [31:0] d;
output [31:0] q;
reg [31:0] q;

always @(posedge clk)   //synchronous reset
begin
  if (resetn==0 || squashn==0)
    q<=0;
  else if (en==1)
    q<=d;
end

endmodule

sva:
module pipereg_w32_sva (
    input logic clk,
    input logic resetn,
    input logic [31:0] d,
    input logic squashn,
    input logic en,
    input logic [31:0] q
);

    // Reset or squash clears q.
    check_clear_on_reset_or_squash: assert property (
        @(posedge clk) (!resetn || !squashn) |=> (q == 32'h00000000)
    );

    // Reset has priority over enable.
    check_reset_priority_over_enable: assert property (
        @(posedge clk) (!resetn && en) |=> (q == 32'h00000000)
    );

    // Squash has priority over enable.
    check_squash_priority_over_enable: assert property (
        @(posedge clk) disable iff (!resetn) (!squashn && en) |=> (q == 32'h00000000)
    );

    // Enable loads d when reset and squash are inactive.
    check_load_when_enabled: assert property (
        @(posedge clk) disable iff (!resetn) (squashn && en) |=> (q == $past(d))
    );

    // q holds its value when enable is low and no clear is active.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (!resetn) (squashn && !en) |=> $stable(q)
    );

endmodule

rtl:
module sky130_fd_sc_ms__mux_2_1 (
    out ,
    in0 ,
    in1 ,
    sel ,
    VPWR,
    VGND,
    VPB ,
    VNB
);

    output out ;
    input  in0 ;
    input  in1 ;
    input  sel ;
    input  VPWR;
    input  VGND;
    input  VPB ;
    input  VNB ;

    assign out = sel ? in1 : in0;

endmodule

sva:
module sky130_fd_sc_ms__mux_2_1_sva (
    input logic out,
    input logic in0,
    input logic in1,
    input logic sel,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB
);

    // Out always equals the selected data input.
    check_mux_equation: assert property (
        @($global_clock) out == (sel ? in1 : in0)
    );

    // When sel is low, out matches in0.
    check_sel_low_selects_in0: assert property (
        @($global_clock) !sel |-> (out == in0)
    );

    // When sel is high, out matches in1.
    check_sel_high_selects_in1: assert property (
        @($global_clock) sel |-> (out == in1)
    );

    // A change on in0 is reflected when in0 is selected.
    check_in0_change_reflected_when_selected: assert property (
        @($global_clock) $stable(sel) && !sel && $changed(in0) |-> (out == in0)
    );

    // A change on in1 is reflected when in1 is selected.
    check_in1_change_reflected_when_selected: assert property (
        @($global_clock) $stable(sel) && sel && $changed(in1) |-> (out == in1)
    );

    // A change on in0 is ignored when in1 remains selected.
    check_in0_change_ignored_when_unselected: assert property (
        @($global_clock) $stable(sel) && sel && $stable(in1) && $changed(in0) |-> $stable(out)
    );

    // A change on in1 is ignored when in0 remains selected.
    check_in1_change_ignored_when_unselected: assert property (
        @($global_clock) $stable(sel) && !sel && $stable(in0) && $changed(in1) |-> $stable(out)
    );

    // A rising sel switches the output to in1 when data inputs are stable.
    check_sel_rise_selects_in1: assert property (
        @($global_clock) $rose(sel) && $stable(in0) && $stable(in1) |-> (out == in1)
    );

    // A falling sel switches the output to in0 when data inputs are stable.
    check_sel_fall_selects_in0: assert property (
        @($global_clock) $fell(sel) && $stable(in0) && $stable(in1) |-> (out == in0)
    );

    // Stable functional inputs keep the output stable.
    check_stable_inputs_keep_output_stable: assert property (
        @($global_clock) $stable(sel) && $stable(in0) && $stable(in1) |-> $stable(out)
    );

endmodule

module mux_2_1_syncreset_sva (
    input logic        clk,
    input logic        rst,
    input logic        sel,
    input logic [31:0] in1,
    input logic [31:0] in2,
    input logic [31:0] out
);

    // A reset sampled on the previous clock clears the registered output.
    check_prev_reset_clears_out: assert property (
        @(posedge clk) disable iff ($initstate)
        ($past(rst) === 1'b1) |-> (out === 32'd0)
    );

    // When previously not in reset and sel was high, out captures in1.
    check_prev_sel_high_captures_in1: assert property (
        @(posedge clk) disable iff ($initstate)
        (($past(rst) !== 1'b1) && ($past(sel) === 1'b1)) |-> (out === $past(in1))
    );

    // When previously not in reset and sel was not high, out captures in2.
    check_prev_sel_not_high_captures_in2: assert property (
        @(posedge clk) disable iff ($initstate)
        (($past(rst) !== 1'b1) && ($past(sel) !== 1'b1)) |-> (out === $past(in2))
    );

    // The output always matches the previous cycle's reset and mux decision.
    check_registered_mux_behavior: assert property (
        @(posedge clk) disable iff ($initstate)
        (($past(rst) === 1'b1) ?
            (out === 32'd0) :
            (($past(sel) === 1'b1) ? (out === $past(in1)) : (out === $past(in2)))
        )
    );

endmodule

