module and4 (
    output X,
    input  A,
    input  B,
    input  C,
    input  D
);

    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    wire temp1, temp2;

    and u1 (temp1, A, B, C);
    and u2 (temp2, temp1, C, D);
    assign X = temp2;

endmodule

sva:
module and4_sva (
    input logic clk,
    input logic X,
    input logic A,
    input logic B,
    input logic C,
    input logic D
);

    // X must equal the 4-input AND of A, B, C, and D.
    check_x_matches_and4: assert property (
        @(posedge clk) X === (A & B & C & D)
    );

    // If all inputs are high, X must be high.
    check_all_inputs_high_drive_x_high: assert property (
        @(posedge clk)
        ((A === 1'b1) && (B === 1'b1) && (C === 1'b1) && (D === 1'b1)) |-> (X === 1'b1)
    );

    // If any input is low, X must be low.
    check_any_low_input_drives_x_low: assert property (
        @(posedge clk)
        ((A === 1'b0) || (B === 1'b0) || (C === 1'b0) || (D === 1'b0)) |-> (X === 1'b0)
    );

    // A high X requires all inputs to be high.
    check_x_high_requires_all_inputs_high: assert property (
        @(posedge clk)
        (X === 1'b1) |-> ((A === 1'b1) && (B === 1'b1) && (C === 1'b1) && (D === 1'b1))
    );

endmodule

rtl:
module four_bit_adder(
  input [3:0] A,
  input [3:0] B,
  output reg [3:0] S,
  output reg C_out
);

  wire [4:0] carry;
  wire [4:0] sum;

  genvar i;
  generate
    for (i = 0; i < 4; i = i + 1) begin
      full_adder full_adder_inst(
        .A(A[i]),
        .B(B[i]),
        .C_in(carry[i]),
        .S(sum[i]),
        .C_out(carry[i+1])
      );
    end
  endgenerate

  assign carry[0] = 0;

  always @* begin
    S = sum[3:0];
    C_out = carry[4];
  end

endmodule
module full_adder (
  input A,
  input B,
  input C_in,
  output S,
  output C_out
);

  assign {C_out, S} = A + B + C_in;

endmodule

sva:
module four_bit_adder_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] S,
    input logic C_out
);

    // The 5-bit output value matches unsigned addition of A and B.
    check_total_sum: assert property (
        @(posedge clk)
        {C_out, S} == ({1'b0, A} + {1'b0, B})
    );

    // Carry-out is asserted exactly when the 4-bit addition overflows.
    check_carry_out_matches_overflow: assert property (
        @(posedge clk)
        C_out == (({1'b0, A} + {1'b0, B}) >= 5'h10)
    );

    // Bit 0 sum is the XOR of the least-significant input bits.
    check_lsb_sum: assert property (
        @(posedge clk)
        S[0] == (A[0] ^ B[0])
    );

    // Bit 1 sum includes the carry generated by bit 0.
    check_bit1_sum: assert property (
        @(posedge clk)
        S[1] == (A[1] ^ B[1] ^ (A[0] & B[0]))
    );

    // Bit 2 sum includes the ripple carry from the lower two bits.
    check_bit2_sum: assert property (
        @(posedge clk)
        S[2] == (A[2] ^ B[2] ^
                 ((A[1] & B[1]) |
                  (A[1] & (A[0] & B[0])) |
                  (B[1] & (A[0] & B[0]))))
    );

    // Zero on A passes B through with no carry.
    check_a_zero_passthrough: assert property (
        @(posedge clk)
        (A == 4'h0) |-> ({C_out, S} == {1'b0, B})
    );

    // Zero on B passes A through with no carry.
    check_b_zero_passthrough: assert property (
        @(posedge clk)
        (B == 4'h0) |-> ({C_out, S} == {1'b0, A})
    );

    // Two operands with clear MSBs cannot produce an overflow carry.
    check_no_overflow_small_operands: assert property (
        @(posedge clk)
        (!A[3] && !B[3]) |-> (C_out == 1'b0)
    );

endmodule

rtl:
module shift_register_ring_counter (input clk, input d, output reg q);

  reg [2:0] shift_reg;

  always @(posedge clk)
    shift_reg <= {shift_reg[1:0], d};

  always @*
    q = shift_reg[2];

endmodule

sva:
module shift_register_ring_counter_sva (
    input logic       clk,
    input logic       d,
    input logic       q,
    input logic [2:0] shift_reg
);

    // q always reflects the MSB of the shift register.
    check_q_tracks_shift_reg_msb: assert property (
        @(posedge clk) q == shift_reg[2]
    );

    // The shift register shifts left and appends d on each clock.
    check_shift_reg_update: assert property (
        @(posedge clk) 1'b1 |=> (shift_reg == {$past(shift_reg[1:0]), $past(d)})
    );

    // Bit 0 captures d from the previous clock edge.
    check_stage0_captures_d: assert property (
        @(posedge clk) 1'b1 |=> (shift_reg[0] == $past(d))
    );

    // Bit 1 captures the previous value of bit 0.
    check_stage1_shifts_stage0: assert property (
        @(posedge clk) 1'b1 |=> (shift_reg[1] == $past(shift_reg[0]))
    );

    // Bit 2 captures the previous value of bit 1.
    check_stage2_shifts_stage1: assert property (
        @(posedge clk) 1'b1 |=> (shift_reg[2] == $past(shift_reg[1]))
    );

    // q matches d from three sampled clock edges earlier.
    check_q_matches_delayed_d: assert property (
        @(posedge clk) 1'b1 |=> ##2 (q == $past(d,3))
    );

endmodule

rtl:
module d_ff_sync_reset (
    input CLK,
    input D,
    input RESET,
    output Q,
    output Q_N
);

    reg Q_buf;

    always @(posedge CLK) begin
        if (RESET) begin
            Q_buf <= 1'b0;
        end
        else begin
            Q_buf <= D;
        end
    end

    assign Q = Q_buf;
    assign Q_N = ~Q_buf;

endmodule

sva:
module d_ff_sync_reset_sva (
    input logic CLK,
    input logic D,
    input logic RESET,
    input logic Q,
    input logic Q_N
);

    // A sampled reset drives the outputs to the reset state by the next clock.
    check_reset_state: assert property (
        @(posedge CLK) RESET |=> (Q == 1'b0 && Q_N == 1'b1)
    );

    // Without reset, Q captures D on the next clock.
    check_q_captures_d: assert property (
        @(posedge CLK) disable iff (RESET) 1'b1 |=> (Q == $past(D))
    );

    // Without reset, Q_N captures the inverse of D on the next clock.
    check_qn_captures_inverse_d: assert property (
        @(posedge CLK) disable iff (RESET) 1'b1 |=> (Q_N == ~$past(D))
    );

    // Outside reset, the two outputs remain logical complements.
    check_outputs_are_complements: assert property (
        @(posedge CLK) disable iff (RESET) (Q_N == ~Q)
    );

endmodule

module counter_sva (
    input logic clk,
    input logic rst,
    input logic enable,
    input logic count_dir,
    input logic dual_count,
    input logic [7:0] count_out
);

    // Reset forces the counter output to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) !rst |-> (count_out == 8'h00)
    );

    // The counter holds its value when enable is low.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (!rst)
        (!$initstate && $past(rst) && !$past(enable))
        |-> (count_out == $past(count_out))
    );

    // Counting up from 8'hFF wraps to 8'h00.
    check_up_wrap_from_ff: assert property (
        @(posedge clk) disable iff (!rst)
        (!$initstate && $past(rst) && $past(enable) &&
         ($past(count_dir) == 1'b0) && ($past(count_out) == 8'hFF))
        |-> (count_out == 8'h00)
    );

    // Counting down from 8'h00 wraps to 8'hFF.
    check_down_wrap_from_zero: assert property (
        @(posedge clk) disable iff (!rst)
        (!$initstate && $past(rst) && $past(enable) &&
         ($past(count_dir) == 1'b1) && ($past(count_out) == 8'h00))
        |-> (count_out == 8'hFF)
    );

    // Single-step up counting increments by one.
    check_up_single_step: assert property (
        @(posedge clk) disable iff (!rst)
        (!$initstate && $past(rst) && $past(enable) &&
         ($past(count_dir) == 1'b0) && ($past(dual_count) == 1'b0))
        |-> (count_out == ($past(count_out) + 8'h01))
    );

    // Single-step down counting decrements by one.
    check_down_single_step: assert property (
        @(posedge clk) disable iff (!rst)
        (!$initstate && $past(rst) && $past(enable) &&
         ($past(count_dir) == 1'b1) && ($past(dual_count) == 1'b0))
        |-> (count_out == ($past(count_out) - 8'h01))
    );

    // Dual-step up counting increments by two except at 8'hFF.
    check_up_dual_step: assert property (
        @(posedge clk) disable iff (!rst)
        (!$initstate && $past(rst) && $past(enable) &&
         ($past(count_dir) == 1'b0) && ($past(dual_count) == 1'b1) &&
         ($past(count_out) != 8'hFF))
        |-> (count_out == ($past(count_out) + 8'h02))
    );

    // Dual-step down counting decrements by two except at 8'h00.
    check_down_dual_step: assert property (
        @(posedge clk) disable iff (!rst)
        (!$initstate && $past(rst) && $past(enable) &&
         ($past(count_dir) == 1'b1) && ($past(dual_count) == 1'b1) &&
         ($past(count_out) != 8'h00))
        |-> (count_out == ($past(count_out) - 8'h02))
    );

endmodule

module karnaugh_map_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic F
);

    // F matches the implemented truth table for all sampled inputs.
    check_function_matches_truth_table: assert property (
        @(posedge clk) F == (B ^ C ^ D)
    );

    // When BCD is 000, F must be low.
    check_bcd_000_output_low: assert property (
        @(posedge clk) ({B, C, D} == 3'b000) |-> (F == 1'b0)
    );

    // When BCD is 001, F must be high.
    check_bcd_001_output_high: assert property (
        @(posedge clk) ({B, C, D} == 3'b001) |-> (F == 1'b1)
    );

    // When BCD is 010, F must be high.
    check_bcd_010_output_high: assert property (
        @(posedge clk) ({B, C, D} == 3'b010) |-> (F == 1'b1)
    );

    // When BCD is 011, F must be low.
    check_bcd_011_output_low: assert property (
        @(posedge clk) ({B, C, D} == 3'b011) |-> (F == 1'b0)
    );

    // When BCD is 100, F must be high.
    check_bcd_100_output_high: assert property (
        @(posedge clk) ({B, C, D} == 3'b100) |-> (F == 1'b1)
    );

    // When BCD is 101, F must be low.
    check_bcd_101_output_low: assert property (
        @(posedge clk) ({B, C, D} == 3'b101) |-> (F == 1'b0)
    );

    // When BCD is 110, F must be low.
    check_bcd_110_output_low: assert property (
        @(posedge clk) ({B, C, D} == 3'b110) |-> (F == 1'b0)
    );

    // When BCD is 111, F must be high.
    check_bcd_111_output_high: assert property (
        @(posedge clk) ({B, C, D} == 3'b111) |-> (F == 1'b1)
    );

endmodule

