sva:
module my_module_assertions (
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic out
);

    // out matches the exact RTL expression.
    check_out_matches_rtl_function: assert property (
        @($global_clock)
        out === ((D == 1'b1) ? ~((B == 1'b1) ? A : C) : ((B == 1'b1) ? A : C))
    );

    // When B selects A and D is low, out equals A.
    check_select_a_no_invert: assert property (
        @($global_clock)
        ((B === 1'b1) && (D === 1'b0)) |-> (out === A)
    );

    // When B selects C and D is low, out equals C.
    check_select_c_no_invert: assert property (
        @($global_clock)
        ((B === 1'b0) && (D === 1'b0)) |-> (out === C)
    );

    // When B selects A and D is high, out equals inverted A.
    check_select_a_invert: assert property (
        @($global_clock)
        ((B === 1'b1) && (D === 1'b1)) |-> (out === ~A)
    );

    // When B selects C and D is high, out equals inverted C.
    check_select_c_invert: assert property (
        @($global_clock)
        ((B === 1'b0) && (D === 1'b1)) |-> (out === ~C)
    );

endmodule

module up_down_counter_sva (
    input logic       clk,
    input logic       reset,
    input logic       control,
    input logic [3:0] count
);

    // Count is zero on the first cycle after reset is released.
    check_post_reset_zero: assert property (
        @(posedge clk) disable iff (reset)
        $past(reset) |-> (count == 4'b0000)
    );

    // Each active cycle updates count by one in the selected direction.
    check_next_state_update: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> (count == ($past(control) ? ($past(count) + 4'd1) : ($past(count) - 4'd1)))
    );

    // control high causes an increment on the next clock.
    check_increment: assert property (
        @(posedge clk) disable iff (reset)
        control |=> (count == ($past(count) + 4'd1))
    );

    // control low causes a decrement on the next clock.
    check_decrement: assert property (
        @(posedge clk) disable iff (reset)
        !control |=> (count == ($past(count) - 4'd1))
    );

    // Incrementing from 4'hF wraps back to zero.
    check_increment_wrap: assert property (
        @(posedge clk) disable iff (reset)
        control && (count == 4'hF) |=> (count == 4'h0)
    );

    // Decrementing from zero wraps to 4'hF.
    check_decrement_wrap: assert property (
        @(posedge clk) disable iff (reset)
        !control && (count == 4'h0) |=> (count == 4'hF)
    );

endmodule

rtl:
module sky130_fd_sc_hd__fahcon (
    COUT_N,
    SUM   ,
    A     ,
    B     ,
    CI
);

    output COUT_N;
    output SUM   ;
    input  A     ;
    input  B     ;
    input  CI    ;

    wire xor0_out_SUM ;
    wire a_b          ;
    wire a_ci         ;
    wire b_ci         ;
    wire or0_out_coutn;

    xor xor0 (xor0_out_SUM , A, B, CI       );
    buf buf0 (SUM          , xor0_out_SUM   );
    nor nor0 (a_b          , A, B           );
    nor nor1 (a_ci         , A, CI          );
    nor nor2 (b_ci         , B, CI          );
    or  or0  (or0_out_coutn, a_b, a_ci, b_ci);
    buf buf1 (COUT_N       , or0_out_coutn  );

endmodule

sva:
module sky130_fd_sc_hd__fahcon_sva (
    input logic clk,
    input logic COUT_N,
    input logic SUM,
    input logic A,
    input logic B,
    input logic CI
);

    // SUM is the three-input XOR of A, B, and CI.
    check_sum_parity: assert property (
        @(posedge clk) SUM == (A ^ B ^ CI)
    );

    // COUT_N is the inverted carry-out from the three inputs.
    check_coutn_function: assert property (
        @(posedge clk) COUT_N == ~((A & B) | (A & CI) | (B & CI))
    );

    // The outputs encode a full-adder result with active-low carry.
    check_full_adder_encoding: assert property (
        @(posedge clk) ({1'b0, A} + {1'b0, B} + {1'b0, CI}) == {~COUT_N, SUM}
    );

    // All-zero inputs produce zero sum and deasserted carry.
    check_all_zero_case: assert property (
        @(posedge clk) (!A && !B && !CI) |-> (!SUM && COUT_N)
    );

    // Any single high input produces sum one and deasserted carry.
    check_one_high_case: assert property (
        @(posedge clk)
        ((A && !B && !CI) || (!A && B && !CI) || (!A && !B && CI)) |-> (SUM && COUT_N)
    );

    // Any two high inputs produce sum zero and asserted carry.
    check_two_high_case: assert property (
        @(posedge clk)
        ((A && B && !CI) || (A && !B && CI) || (!A && B && CI)) |-> (!SUM && !COUT_N)
    );

    // All-one inputs produce sum one and asserted carry.
    check_all_one_case: assert property (
        @(posedge clk) (A && B && CI) |-> (SUM && !COUT_N)
    );

endmodule

rtl:
module db_qp(
				clk					,
				rst_n				,
				cbf_4x4_i			,
				cbf_u_4x4_i			,
				cbf_v_4x4_i			,
				qp_left_i			,

				qp_flag_o		
);
input 				clk						;
input				rst_n					;
input				cbf_4x4_i			    ;
input				cbf_u_4x4_i			    ;
input				cbf_v_4x4_i			    ;
input               qp_left_i				;output				qp_flag_o				;

reg   			 	qp_flag_o				; 
wire  modified_flag   = !(cbf_4x4_i  ||cbf_u_4x4_i  ||cbf_v_4x4_i  );always@(posedge clk or negedge rst_n) begin
	if(!rst_n)
		qp_flag_o		<=	1'b0		;	
	else if(modified_flag)qp_flag_o		<=	qp_left_i	;else 
		qp_flag_o		<=	1'b0		;

end

endmodule

sva:
module db_qp_sva (
    input logic clk,
    input logic rst_n,
    input logic cbf_4x4_i,
    input logic cbf_u_4x4_i,
    input logic cbf_v_4x4_i,
    input logic qp_left_i,
    input logic qp_flag_o
);

    logic modified_flag;
    assign modified_flag = !(cbf_4x4_i || cbf_u_4x4_i || cbf_v_4x4_i);

    // Reset clears the registered output.
    check_reset_clears_qp_flag: assert property (
        @(posedge clk) !rst_n |-> (qp_flag_o == 1'b0)
    );

    // With no CBF activity and qp_left_i high, qp_flag_o sets on the next clock.
    check_unmodified_copies_high_left_qp: assert property (
        @(posedge clk) disable iff (!rst_n)
        (modified_flag && qp_left_i) |=> (qp_flag_o == 1'b1)
    );

    // With no CBF activity and qp_left_i low, qp_flag_o clears on the next clock.
    check_unmodified_copies_low_left_qp: assert property (
        @(posedge clk) disable iff (!rst_n)
        (modified_flag && !qp_left_i) |=> (qp_flag_o == 1'b0)
    );

    // Any CBF activity forces qp_flag_o low on the next clock.
    check_modified_block_clears_qp_flag: assert property (
        @(posedge clk) disable iff (!rst_n)
        (!modified_flag) |=> (qp_flag_o == 1'b0)
    );

    // qp_flag_o matches the previous cycle's RTL update function.
    check_registered_update_function: assert property (
        @(posedge clk) disable iff (!rst_n)
        1'b1 |=> (qp_flag_o == $past(modified_flag && qp_left_i))
    );

endmodule

rtl:
module complement_module (
    input [3:0] in_vec,
    input sel_comp,
    output [3:0] outv,
    output [3:0] complement
);

    assign outv = in_vec;

    assign complement = (sel_comp == 1) ? ~in_vec + 1 : ~in_vec;

