    // sel_comp high selects twos' complement.
    check_twos_complement_when_selected: assert property (
        @(posedge clk) (sel_comp == 1'b1) |-> (complement == (~in_vec + 4'b0001))
    );

    // Ones' complement output is the bitwise inverse of the input.
    check_ones_complement_inverse_relation: assert property (
        @(posedge clk) (sel_comp == 1'b0) |-> ((complement ^ in_vec) == 4'hF)
    );

    // Twos' complement output adds with the input to zero modulo 16.
    check_twos_complement_additive_inverse: assert property (
        @(posedge clk) (sel_comp == 1'b1) |-> ((complement + in_vec) == 4'b0000)
    );

endmodule

rtl:
module state_machine (
    input clk,
    input rst_,
    output reg [2:0] state_r
);

    // Define the states as enumerated types
    parameter [2:0] IDLE = 3'b000;
    parameter [2:0] SEND = 3'b001;
    parameter [2:0] WAIT1 = 3'b010;
    parameter [2:0] UPDATE1 = 3'b011;
    parameter [2:0] WAIT2 = 3'b100;
    parameter [2:0] UPDATE2 = 3'b101;

    // Define the next state variable
    reg [2:0] next_state;

    // Define the state transition logic
    always @(*) begin
        case (state_r)
            IDLE: next_state = SEND;
            SEND: next_state = WAIT1;
            WAIT1: next_state = UPDATE1;
            UPDATE1: next_state = WAIT2;
            WAIT2: next_state = UPDATE2;
            UPDATE2: next_state = IDLE;
            default: next_state = IDLE;
        endcase
    end

    // Define the state update logic
    always @(posedge clk or negedge rst_) begin
        if (~rst_) begin
            state_r <= IDLE;
        end else begin
            state_r <= next_state;
        end
    end

endmodule

sva:
module state_machine_sva (
    input logic clk,
    input logic rst_,
    input logic [2:0] state_r
);

    localparam logic [2:0] IDLE    = 3'b000;
    localparam logic [2:0] SEND    = 3'b001;
    localparam logic [2:0] WAIT1   = 3'b010;
    localparam logic [2:0] UPDATE1 = 3'b011;
    localparam logic [2:0] WAIT2   = 3'b100;
    localparam logic [2:0] UPDATE2 = 3'b101;

    // Reset drives the machine to IDLE.
    check_reset_idle: assert property (
        @(posedge clk)
        !rst_ |-> (state_r == IDLE)
    );

    // IDLE advances to SEND on the next clock.
    check_idle_to_send: assert property (
        @(posedge clk) disable iff (!rst_)
        (state_r == IDLE) |=> (state_r == SEND)
    );

    // SEND advances to WAIT1 on the next clock.
    check_send_to_wait1: assert property (
        @(posedge clk) disable iff (!rst_)
        (state_r == SEND) |=> (state_r == WAIT1)
    );

    // WAIT1 advances to UPDATE1 on the next clock.
    check_wait1_to_update1: assert property (
        @(posedge clk) disable iff (!rst_)
        (state_r == WAIT1) |=> (state_r == UPDATE1)
    );

    // UPDATE1 advances to WAIT2 on the next clock.
    check_update1_to_wait2: assert property (
        @(posedge clk) disable iff (!rst_)
        (state_r == UPDATE1) |=> (state_r == WAIT2)
    );

    // WAIT2 advances to UPDATE2 on the next clock.
    check_wait2_to_update2: assert property (
        @(posedge clk) disable iff (!rst_)
        (state_r == WAIT2) |=> (state_r == UPDATE2)
    );

    // UPDATE2 wraps back to IDLE on the next clock.
    check_update2_to_idle: assert property (
        @(posedge clk) disable iff (!rst_)
        (state_r == UPDATE2) |=> (state_r == IDLE)
    );

    // Any invalid state encoding returns to IDLE on the next clock.
    check_invalid_state_to_idle: assert property (
        @(posedge clk) disable iff (!rst_)
        !((state_r == IDLE) || (state_r == SEND) || (state_r == WAIT1) ||
          (state_r == UPDATE1) || (state_r == WAIT2) || (state_r == UPDATE2))
        |=> (state_r == IDLE)
    );

    // After any non-reset cycle, the next state is always a legal encoding.
    check_next_state_is_legal: assert property (
        @(posedge clk) disable iff (!rst_)
        1'b1 |=> ((state_r == IDLE) || (state_r == SEND) || (state_r == WAIT1) ||
                  (state_r == UPDATE1) || (state_r == WAIT2) || (state_r == UPDATE2))
    );

endmodule

rtl:
module shift_register (
    input CLK,
    input LOAD,
    input [3:0] DATA,
    output reg [3:0] Q
);

reg [3:0] reg_out;

always @(posedge CLK) begin
    if (LOAD) begin
        reg_out <= DATA;
    end else begin
        reg_out <= {reg_out[2:0], 1'b0};
    end
end

always @(*) begin
    Q = reg_out;
end

endmodule

sva:
module shift_register_sva (
    input logic       CLK,
    input logic       LOAD,
    input logic [3:0] DATA,
    input logic [3:0] Q
);

    // A load cycle captures DATA into Q by the next sampled clock.
    check_load_captures_data: assert property (
        @(posedge CLK) LOAD |=> (Q == $past(DATA))
    );

    // A non-load cycle shifts Q left and inserts 0 into bit 0.
    check_shift_behavior: assert property (
        @(posedge CLK) !LOAD |=> (Q == {$past(Q[2:0]), 1'b0})
    );

    // A non-load cycle always drives the next LSB low.
    check_shift_inserts_zero: assert property (
        @(posedge CLK) !LOAD |=> (Q[0] == 1'b0)
    );

    // A non-load cycle moves the prior lower bits into the upper bits.
    check_shift_moves_bits: assert property (
        @(posedge CLK) !LOAD |=> (Q[3:1] == $past(Q[2:0]))
    );

    // Four consecutive shift cycles clear the register.
    check_four_shifts_clear_register: assert property (
        @(posedge CLK) ((!LOAD)[*4]) |=> (Q == 4'b0000)
    );

endmodule

rtl:
module counter(
    input clk,
    input rst,
    output reg [3:0] count
);

always @(posedge clk or posedge rst) begin
    if (rst) begin
        count <= 4'b0;
    end else begin
        count <= count + 1;
    end
end

endmodule

sva:
module counter_sva (
    input logic       clk,
    input logic       rst,
    input logic [3:0] count
);

    // A sampled reset must leave the counter at zero on the next clock.
    check_sampled_reset_clears_count: assert property (
        @(posedge clk) disable iff ($initstate)
        rst |=> (count == 4'h0)
    );

    // The first sampled clock after reset deassertion still sees zero.
    check_reset_release_observes_zero: assert property (
        @(posedge clk) disable iff ($initstate)
        $fell(rst) |-> (count == 4'h0)
    );

    // Outside reset, any nonzero count must be the previous count plus one.
    check_nonzero_count_increments_by_one: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        (count != 4'h0) |-> (count == ($past(count) + 4'h1))
    );

    // Outside reset, a previous maximum count must wrap to zero.
    check_wrap_from_max_to_zero: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        ($past(count) == 4'hF) |-> (count == 4'h0)
    );

endmodule

rtl:
module nor_and_gate (
    input A, B, C, D,
    output Y
);

    // Local signals
    wire nor_out, and_out;

    // NOR gate
    nor (nor_out, A, B);

    // AND gate
    and (and_out, nor_out, C, D);

    // Output buffer
    buf (Y, and_out);

endmodule

sva:
module nor_and_gate_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic Y
);

    // Y must implement the full combinational function.
    check_output_function: assert property (
        @(posedge clk) Y == ((~(A | B)) & C & D)
    );

    // If either NOR input is high, the output must be low.
    check_a_or_b_blocks_output: assert property (
        @(posedge clk) (A || B) |-> !Y
    );

    // If C is low, the AND stage must force the output low.
    check_c_low_blocks_output: assert property (
        @(posedge clk) !C |-> !Y
    );

    // If D is low, the AND stage must force the output low.
    check_d_low_blocks_output: assert property (
        @(posedge clk) !D |-> !Y
    );

    // When A and B are low, Y must match C AND D.
    check_ab_low_reduces_to_cd: assert property (
        @(posedge clk) (!A && !B) |-> (Y == (C && D))
    );

    // A high output requires both NOR inputs low and both AND inputs high.
    check_high_output_requires_all_enables: assert property (
        @(posedge clk) Y |-> (!A && !B && C && D)
    );

endmodule

rtl:
module and_gate(
    input in1,
    input in2,
    output out
);

reg subsig1 ;
reg subsig2 ;

assign out = in1 & in2;

`ifdef iverilog
   // stop icarus optimizing signals away
   wire redundant = subsig1 | subsig2;
`endif

endmodule

sva:
module and_gate_sva (
    input logic in1,
    input logic in2,
    input logic out
);

    // The output must always equal the AND of the two inputs.
    check_out_equals_and_of_inputs: assert property (
        @($global_clock) out == (in1 & in2)
    );

    // A low first input must force the output low.
    check_in1_low_forces_out_low: assert property (
        @($global_clock) (in1 == 1'b0) |-> (out == 1'b0)
    );

    // A low second input must force the output low.
    check_in2_low_forces_out_low: assert property (
        @($global_clock) (in2 == 1'b0) |-> (out == 1'b0)
    );

    // Both high inputs must drive the output high.
    check_both_inputs_high_drive_out_high: assert property (
        @($global_clock) ((in1 == 1'b1) && (in2 == 1'b1)) |-> (out == 1'b1)
    );

endmodule

rtl:
module full_adder (
    input A,
    input B,
    input Cin,
    output Sum,
    output Cout
);

    wire w1, w2, w3;

    assign w1 = A ^ B;
    assign Sum = w1 ^ Cin;
    assign w2 = A & B;
    assign w3 = w1 & Cin;
    assign Cout = w2 | w3;

endmodule

module four_bit_adder (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] Sum,
    output Cout
);

    wire c1, c2, c3;

    full_adder FA0 (
        .A(A[0]),
        .B(B[0]),
        .Cin(Cin),
        .Sum(Sum[0]),
        .Cout(c1)
    );

    full_adder FA1 (
        .A(A[1]),
        .B(B[1]),
        .Cin(c1),
        .Sum(Sum[1]),
        .Cout(c2)
    );

    full_adder FA2 (
        .A(A[2]),
        .B(B[2]),
        .Cin(c2),
        .Sum(Sum[2]),
        .Cout(c3)
    );

    full_adder FA3 (
        .A(A[3]),
        .B(B[3]),
        .Cin(c3),
        .Sum(Sum[3]),
        .Cout(Cout)
    );

endmodule

sva:
module four_bit_adder_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic Cin,
    input logic [3:0] Sum,
    input logic Cout
);

    // Sum[0] matches the bit-0 full-adder equation.
    check_sum_bit0_equation: assert property (
        @(posedge clk) disable iff (1'b0)
            Sum[0] == (A[0] ^ B[0] ^ Cin)
    );

    // Sum[1] matches the bit-1 ripple-carry equation.
    check_sum_bit1_equation: assert property (
        @(posedge clk) disable iff (1'b0)
            Sum[1] == (A[1] ^ B[1] ^
                       ((A[0] & B[0]) | ((A[0] ^ B[0]) & Cin)))
    );

    // Sum[2] matches the bit-2 ripple-carry equation.
    check_sum_bit2_equation: assert property (
        @(posedge clk) disable iff (1'b0)
            Sum[2] == (A[2] ^ B[2] ^
                       ((A[1] & B[1]) |
                        ((A[1] ^ B[1]) &
                         ((A[0] & B[0]) | ((A[0] ^ B[0]) & Cin)))))
    );

    // Sum[3] matches the bit-3 ripple-carry equation.
    check_sum_bit3_equation: assert property (
        @(posedge clk) disable iff (1'b0)
            Sum[3] == (A[3] ^ B[3] ^
                       ((A[2] & B[2]) |
                        ((A[2] ^ B[2]) &
                         ((A[1] & B[1]) |
                          ((A[1] ^ B[1]) &
                           ((A[0] & B[0]) | ((A[0] ^ B[0]) & Cin)))))))
    );

    // Cout matches the final ripple-carry equation.
    check_cout_equation: assert property (
        @(posedge clk) disable iff (1'b0)
            Cout == ((A[3] & B[3]) |
                     ((A[3] ^ B[3]) &
                      ((A[2] & B[2]) |
                       ((A[2] ^ B[2]) &
                        ((A[1] & B[1]) |
                         ((A[1] ^ B[1]) &
                          ((A[0] & B[0]) | ((A[0] ^ B[0]) & Cin))))))))
    );

    // The outputs match 5-bit addition of A, B, and Cin.
    check_total_addition: assert property (
        @(posedge clk) disable iff (1'b0)
            {Cout, Sum} == ({1'b0, A} + {1'b0, B} + {4'b0000, Cin})
    );

endmodule

rtl:
module small_fifo_cntr (
    input aclr,       // Asynchronous clear input
    input clock,      // Clock input
    input cnt_en,     // Counter enable input
    input updown,     // Up/down counter select input
    output [2:0] q,   // Counter output
    input sclr        // Synchronous clear input
);

    // Internal registers
    reg [2:0] q_reg;

    // Counter logic
    always @ (posedge clock or posedge aclr) begin
        if (aclr) begin
            q_reg <= 3'b0;
        end else if (sclr) begin
            q_reg <= 3'b0;
        end else if (cnt_en) begin
            if (updown) begin
                q_reg <= q_reg + 1'b1;
            end else begin
                q_reg <= q_reg - 1'b1;
            end
        end
    end

    // Output assignment
    assign q = q_reg;

endmodule

sva:
module small_fifo_cntr_sva (
    input logic       aclr,
    input logic       clock,
    input logic       cnt_en,
    input logic       updown,
    input logic [2:0] q,
    input logic       sclr
);

    // Sampled async clear forces q low by the next clock.
    check_aclr_clears_q: assert property (
        @(posedge clock)
        aclr |=> (q == 3'b000)
    );

    // Sync clear forces q low on the following cycle.
    check_sclr_clears_q: assert property (
        @(posedge clock) disable iff (aclr)
        sclr |=> (q == 3'b000)
    );

    // Sync clear overrides an enabled count.
    check_sclr_priority_over_count: assert property (
        @(posedge clock) disable iff (aclr)
        sclr && cnt_en |=> (q == 3'b000)
    );

    // q increments by one when enabled to count up.
    check_count_up: assert property (
        @(posedge clock) disable iff (aclr)
        !sclr && cnt_en && updown |=> (q == ($past(q) + 3'b001))
    );

    // q decrements by one when enabled to count down.
    check_count_down: assert property (
        @(posedge clock) disable iff (aclr)
        !sclr && cnt_en && !updown |=> (q == ($past(q) - 3'b001))
    );

    // q holds its value when no clear or count is requested.
    check_hold_when_disabled: assert property (
        @(posedge clock) disable iff (aclr)
        !sclr && !cnt_en |=> (q == $past(q))
    );

endmodule

rtl:
module my_module(
    input clk,
    input [3:0] data_in,
    output reg data_out
);

    reg [3:0] data_reg;
    wire [3:0] data_wire;

    always @(posedge clk) begin
        data_reg <= data_in;
    end

    assign data_wire = data_reg;

    always @(*) begin
        if (data_wire <= 5) begin
            data_out = 1;
        end else begin
            data_out = 0;
        end
    end

endmodule

sva:
module my_module_sva (
    input logic       clk,
    input logic [3:0] data_in,
    input logic       data_out
);

    // Sampled inputs at or below 5 must drive the output high on the next cycle.
    check_low_or_equal_threshold_drives_high: assert property (
        @(posedge clk) (data_in <= 4'd5) |=> (data_out == 1'b1)
    );

    // Sampled inputs above 5 must drive the output low on the next cycle.
    check_above_threshold_drives_low: assert property (
        @(posedge clk) (data_in > 4'd5) |=> (data_out == 1'b0)
    );

    // The output must match the previous cycle's sampled input compared against 5.
    check_output_matches_previous_input: assert property (
        @(posedge clk) 1'b1 |=> (data_out == (($past(data_in) <= 4'd5) ? 1'b1 : 1'b0))
    );

    // The threshold comparison must include the boundary value 5.
    check_boundary_five_is_high: assert property (
        @(posedge clk) (data_in == 4'd5) |=> (data_out == 1'b1)
    );

    // The first value above the threshold, 6, must drive the output low.
    check_boundary_six_is_low: assert property (
        @(posedge clk) (data_in == 4'd6) |=> (data_out == 1'b0)
    );

endmodule

rtl:
module oh_iddr #(parameter DW      = 1 )
   (
    input 		clk, input 		ce, input [DW-1:0] 	din, output reg [DW-1:0] q1, output reg [DW-1:0] q2   );

   reg [DW-1:0]     q1_sl;
   reg [DW-1:0]     q2_sh;

   always @ (posedge clk)
     if(ce)
       q1_sl[DW-1:0] <= din[DW-1:0];

   always @ (negedge clk)
     q2_sh[DW-1:0] <= din[DW-1:0];

   always @ (posedge clk)
     begin
	q1[DW-1:0] <= q1_sl[DW-1:0];
	q2[DW-1:0] <= q2_sh[DW-1:0];
     end

endmodule

sva:
module oh_iddr_sva #(parameter int DW = 1) (
    input logic          clk,
    input logic          ce,
    input logic [DW-1:0] din,
    input logic [DW-1:0] q1,
    input logic [DW-1:0] q2,
    input logic [DW-1:0] q1_sl,
    input logic [DW-1:0] q2_sh
);

    // q1_sl captures din on an enabled rising edge.
    check_q1sl_captures_din: assert property (
        @(posedge clk) disable iff (1'b0)
        ce |=> (q1_sl == $past(din))
    );

    // q1_sl holds its value when ce is low.
    check_q1sl_holds_when_ce_low: assert property (
        @(posedge clk) disable iff (1'b0)
        !ce |=> (q1_sl == $past(q1_sl))
    );

    // q1 reflects the previously sampled q1_sl value.
    check_q1_updates_from_q1sl: assert property (
        @(posedge clk) disable iff (1'b0)
        1'b1 |=> (q1 == $past(q1_sl))
    );

    // q2 reflects the previously sampled q2_sh value.
    check_q2_updates_from_q2sh: assert property (
        @(posedge clk) disable iff (1'b0)
        1'b1 |=> (q2 == $past(q2_sh))
    );

    // An enabled din sample reaches q1 two rising-edge samples later.
    check_q1_enabled_path_latency: assert property (
        @(posedge clk) disable iff (1'b0)
        ce |=> ##1 (q1 == $past(din, 2))
    );

endmodule

rtl:
module top_module( 
    input wire [7:0] in_hi,
    input wire [7:0] in_lo,
    output wire [16:0] out );

    wire parity_bit;
    wire [15:0] half_word;

    // Concatenate the two input bytes into a half-word
    assign half_word = {in_hi, in_lo};

    // Generate parity bit using XOR gate
    assign parity_bit = ^half_word;

    // Append parity bit to half-word output
    assign out = {half_word, parity_bit};

endmodule

sva:
module top_module_sva (
    input logic        clk,
    input logic [7:0]  in_hi,
    input logic [7:0]  in_lo,
    input logic [16:0] out
);

    // Upper output byte mirrors in_hi.
    check_hi_byte_mapping: assert property (
        @(posedge clk) out[16:9] == in_hi
    );

    // Lower output byte mirrors in_lo.
    check_lo_byte_mapping: assert property (
        @(posedge clk) out[8:1] == in_lo
    );

    // The upper 16 output bits are the concatenated input bytes.
    check_half_word_concat: assert property (
        @(posedge clk) out[16:1] == {in_hi, in_lo}
    );

    // The parity bit matches the reduction XOR of both input bytes.
    check_parity_from_inputs: assert property (
        @(posedge clk) out[0] == ^({in_hi, in_lo})
    );

    // The full output is the concatenated half-word with its parity bit.
    check_full_output_encoding: assert property (
        @(posedge clk) out == {in_hi, in_lo, ^({in_hi, in_lo})}
    );

    // The parity bit equals the parity of the upper 16 output bits.
    check_parity_consistency: assert property (
        @(posedge clk) out[0] == ^(out[16:1])
    );

    // The 17-bit output has even overall parity.
    check_even_output_parity: assert property (
        @(posedge clk) (^out) == 1'b0
    );

    // If both inputs are stable, the output remains stable.
    check_stable_inputs_stable_output: assert property (
        @(posedge clk) $stable({in_hi, in_lo}) |-> $stable(out)
    );

endmodule

rtl:
module global_reset(
	input clock_i,
	input forced_reset_i,		output n_reset_o,				output n_limited_reset_o	);

	reg [7:0] reset_counter = 1;

	assign n_reset_o 				= (reset_counter <= 1) & !forced_reset_i;	
	assign n_limited_reset_o 	= (reset_counter <= 1);	
	always @(negedge clock_i)
		if( reset_counter != 0 )
			reset_counter <= reset_counter + 1'd1;

endmodule

sva:
module global_reset_sva (
    input logic       clock_i,
    input logic       forced_reset_i,
    input logic       n_reset_o,
    input logic       n_limited_reset_o,
    input logic [7:0] reset_counter
);

    // n_limited_reset_o decodes reset_counter <= 1.
    check_limited_reset_decode: assert property (
        @(negedge clock_i) n_limited_reset_o == (reset_counter <= 8'd1)
    );

    // n_reset_o decodes reset_counter <= 1 and forced_reset_i.
    check_reset_decode: assert property (
        @(negedge clock_i) n_reset_o == ((reset_counter <= 8'd1) & !forced_reset_i)
    );

    // n_reset_o is n_limited_reset_o masked by forced_reset_i.
    check_reset_is_masked_limited_reset: assert property (
        @(negedge clock_i) n_reset_o == (n_limited_reset_o & !forced_reset_i)
    );

    // forced_reset_i always drives n_reset_o low.
    check_forced_reset_forces_n_reset_low: assert property (
        @(negedge clock_i) forced_reset_i |-> !n_reset_o
    );

    // A nonzero counter increments by one on each falling edge.
    check_counter_increments_while_nonzero: assert property (
        @(negedge clock_i) (reset_counter != 8'd0) |=> (reset_counter == ($past(reset_counter) + 8'd1))
    );

    // Once the counter reaches zero, it stays at zero.
    check_counter_holds_at_zero: assert property (
        @(negedge clock_i) (reset_counter == 8'd0) |=> (reset_counter == 8'd0)
    );

    // The counter wraps from 8'hFF to 8'h00.
    check_counter_wraps_to_zero: assert property (
        @(negedge clock_i) (reset_counter == 8'hFF) |=> (reset_counter == 8'h00)
