module zynq_reset(
  input slowest_sync_clk,
  input ext_reset_in,
  input aux_reset_in,
  input mb_debug_sys_rst,
  input dcm_locked,
  output mb_reset,
  output [0:0]bus_struct_reset,
  output [0:0]peripheral_reset,
  output [0:0]interconnect_aresetn,
  output [0:0]peripheral_aresetn
);

  // Reset mb_reset when mb_debug_sys_rst or ext_reset_in is asserted, or when dcm_locked is not asserted
  assign mb_reset = (mb_debug_sys_rst || ext_reset_in || !dcm_locked) ? 1'b1 : 1'b0;

  // Reset bus_struct_reset when ext_reset_in is asserted
  assign bus_struct_reset = ext_reset_in ? 1'b1 : 1'b0;

  // Reset peripheral_reset when aux_reset_in is asserted
  assign peripheral_reset = aux_reset_in ? 1'b1 : 1'b0;

  // Reset interconnect_aresetn when mb_reset is asserted
  assign interconnect_aresetn = mb_reset ? 1'b0 : 1'b1;

  // Reset peripheral_aresetn when either mb_reset or peripheral_reset is asserted
  assign peripheral_aresetn = (mb_reset || peripheral_reset) ? 1'b0 : 1'b1;

endmodule

sva:
module zynq_reset_sva (
    input logic slowest_sync_clk,
    input logic ext_reset_in,
    input logic aux_reset_in,
    input logic mb_debug_sys_rst,
    input logic dcm_locked,
    input logic mb_reset,
    input logic [0:0] bus_struct_reset,
    input logic [0:0] peripheral_reset,
    input logic [0:0] interconnect_aresetn,
    input logic [0:0] peripheral_aresetn
);

    // mb_reset matches its combinational definition.
    check_mb_reset_definition: assert property (
        @(posedge slowest_sync_clk) disable iff (1'b0)
        mb_reset == (mb_debug_sys_rst || ext_reset_in || !dcm_locked)
    );

    // Debug reset forces mb_reset high.
    check_mb_reset_on_debug_reset: assert property (
        @(posedge slowest_sync_clk) disable iff (1'b0)
        mb_debug_sys_rst |-> mb_reset
    );

    // External reset forces mb_reset high.
    check_mb_reset_on_ext_reset: assert property (
        @(posedge slowest_sync_clk) disable iff (1'b0)
        ext_reset_in |-> mb_reset
    );

    // Loss of dcm lock forces mb_reset high.
    check_mb_reset_on_dcm_unlock: assert property (
        @(posedge slowest_sync_clk) disable iff (1'b0)
        !dcm_locked |-> mb_reset
    );

    // mb_reset is low when all of its causes are inactive.
    check_mb_reset_clear_condition: assert property (
        @(posedge slowest_sync_clk) disable iff (1'b0)
        (!mb_debug_sys_rst && !ext_reset_in && dcm_locked) |-> !mb_reset
    );

    // bus_struct_reset mirrors ext_reset_in.
    check_bus_struct_reset_definition: assert property (
        @(posedge slowest_sync_clk) disable iff (1'b0)
        bus_struct_reset[0] == ext_reset_in
    );

    // peripheral_reset mirrors aux_reset_in.
    check_peripheral_reset_definition: assert property (
        @(posedge slowest_sync_clk) disable iff (1'b0)
        peripheral_reset[0] == aux_reset_in
    );

    // interconnect_aresetn is the inverse of mb_reset.
    check_interconnect_aresetn_definition: assert property (
        @(posedge slowest_sync_clk) disable iff (1'b0)
        interconnect_aresetn[0] == !mb_reset
    );

    // peripheral_aresetn is low when mb_reset or peripheral_reset is high.
    check_peripheral_aresetn_definition: assert property (
        @(posedge slowest_sync_clk) disable iff (1'b0)
        peripheral_aresetn[0] == !(mb_reset || peripheral_reset[0])
    );

endmodule

rtl:
module alu (
    input [3:0] A,
    input [3:0] B,
    input [2:0] opcode,
    input carry_in,
    input invert,
    output [3:0] result,
    output carry_out
);

    reg [3:0] temp_result;

    assign carry_out = ((opcode == 3'b000) && ((A[3] & B[3]) | (A[3] & carry_in) | (B[3] & carry_in))) |
                        ((opcode == 3'b001) && ((A[3] & ~B[3] & ~carry_in) | (~A[3] & B[3] & carry_in)));

    always @(*) begin
        case (opcode)
            3'b000: temp_result = A + B + carry_in;
            3'b001: temp_result = A - B - carry_in;
            3'b010: temp_result = A & B;
            3'b011: temp_result = A | B;
            3'b100: temp_result = A ^ B;
            default: temp_result = 4'b0000;
        endcase

        if (invert) begin
            temp_result = ~temp_result;
        end
    end

    assign result = temp_result;

endmodule

sva:
module alu_assertions (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [2:0] opcode,
    input logic carry_in,
    input logic invert,
    input logic [3:0] result,
    input logic carry_out
);

    // Addition result is the 4-bit sum, optionally inverted.
    check_add_result: assert property (
        @(posedge clk)
        (opcode == 3'b000) |-> (result == (invert ? ~(A + B + carry_in) : (A + B + carry_in)))
    );

    // Subtraction result is the 4-bit difference, optionally inverted.
    check_subtract_result: assert property (
        @(posedge clk)
        (opcode == 3'b001) |-> (result == (invert ? ~(A - B - carry_in) : (A - B - carry_in)))
    );

    // AND opcode drives bitwise AND, optionally inverted.
    check_and_result: assert property (
        @(posedge clk)
        (opcode == 3'b010) |-> (result == (invert ? ~(A & B) : (A & B)))
    );

    // OR opcode drives bitwise OR, optionally inverted.
    check_or_result: assert property (
        @(posedge clk)
        (opcode == 3'b011) |-> (result == (invert ? ~(A | B) : (A | B)))
    );

    // XOR opcode drives bitwise XOR, optionally inverted.
    check_xor_result: assert property (
        @(posedge clk)
        (opcode == 3'b100) |-> (result == (invert ? ~(A ^ B) : (A ^ B)))
    );

    // Unsupported opcodes drive zero, optionally inverted to all ones.
    check_default_result: assert property (
        @(posedge clk)
        ((opcode == 3'b101) || (opcode == 3'b110) || (opcode == 3'b111))
        |-> (result == (invert ? 4'hF : 4'h0))
    );

    // Addition carry_out matches the RTL carry formula.
    check_add_carry_out: assert property (
        @(posedge clk)
        (opcode == 3'b000)
        |-> (carry_out == ((A[3] & B[3]) | (A[3] & carry_in) | (B[3] & carry_in)))
    );

    // Subtraction carry_out matches the RTL subtraction formula.
    check_subtract_carry_out: assert property (
        @(posedge clk)
        (opcode == 3'b001)
        |-> (carry_out == ((A[3] & ~B[3] & ~carry_in) | (~A[3] & B[3] & carry_in)))
    );

    // Logical opcodes force carry_out low.
    check_logical_carry_out_low: assert property (
        @(posedge clk)
        ((opcode == 3'b010) || (opcode == 3'b011) || (opcode == 3'b100))
        |-> (carry_out == 1'b0)
    );

    // Unsupported opcodes also force carry_out low.
    check_default_carry_out_low: assert property (
        @(posedge clk)
        ((opcode == 3'b101) || (opcode == 3'b110) || (opcode == 3'b111))
        |-> (carry_out == 1'b0)
    );

endmodule

