module signed_multiplier_32_sva #(
    parameter ID = 32'd1,
    parameter NUM_STAGE = 32'd1,
    parameter din0_WIDTH = 32'd1,
    parameter din1_WIDTH = 32'd1,
    parameter dout_WIDTH = 32'd1
) (
    input logic clk,
    input logic reset,
    input logic ce,
    input logic signed [din0_WIDTH - 1:0] din0,
    input logic signed [din1_WIDTH - 1:0] din1,
    input logic signed [dout_WIDTH + din0_WIDTH - 1:0] dout
);

    // Reset clears the registered output value.
    check_reset_clears_output: assert property (
        @(posedge clk) reset |=> (dout == '0)
    );

    // With clock enable low, the output holds its prior value.
    check_hold_when_ce_low: assert property (
        @(posedge clk) disable iff (reset)
        (!ce) |=> (dout == $past(dout))
    );

    // An enabled update drives the output to zero.
    check_enable_update_clears_output: assert property (
        @(posedge clk) disable iff (reset)
        ce |=> (dout == '0)
    );

    // The widened output is always a sign-extension of the stored value.
    check_output_sign_extension: assert property (
        @(posedge clk) disable iff (reset)
        dout[dout_WIDTH + din0_WIDTH - 1:dout_WIDTH] == {din0_WIDTH{dout[dout_WIDTH - 1]}}
    );

    // Input changes do not bypass the register when clock enable is low.
    check_input_changes_ignored_when_ce_low: assert property (
        @(posedge clk) disable iff (reset)
        (!ce && ($changed(din0) || $changed(din1))) |=> (dout == $past(dout))
    );

    // A zero output is retained across idle cycles.
    check_zero_retained_when_idle: assert property (
        @(posedge clk) disable iff (reset)
        (!ce && (dout == '0)) |=> (dout == '0)
    );

endmodule

module RegisterAdd_4_sva (
    input logic [3:0] Q_reg,
    input logic [3:0] D,
    input logic CLK,
    input logic RST
);

    // A reset cycle clears the register to zero.
    check_reset_clears_q: assert property (
        @(posedge CLK)
        !$initstate && $past(RST) |-> (Q_reg == 4'b0000)
    );

    // Outside reset, Q_reg updates as the prior value plus the prior D input.
    check_accumulate_update: assert property (
        @(posedge CLK) disable iff (RST)
        !$initstate && !$past(RST) |-> (Q_reg == ($past(Q_reg) + $past(D)))
    );

    // With zero input outside reset, the register holds its prior value.
    check_hold_when_d_zero: assert property (
        @(posedge CLK) disable iff (RST)
        !$initstate && !$past(RST) && ($past(D) == 4'b0000) |-> (Q_reg == $past(Q_reg))
    );

    // From a zero state outside reset, the next value matches the prior D input.
    check_load_from_zero: assert property (
        @(posedge CLK) disable iff (RST)
        !$initstate && !$past(RST) && ($past(Q_reg) == 4'b0000) |-> (Q_reg == $past(D))
    );

endmodule

rtl:
module binary_counter (
   clk,
   reset,
   count_out
);

    input            clk;
    input            reset;
    output  [3:0]    count_out;

    reg  [3:0]        count_out_reg;

    always @(posedge clk or negedge reset) begin
        if (~reset) begin
            count_out_reg <= 4'b0000;
        end
        else begin
            count_out_reg <= count_out_reg + 1;
        end
    end

    assign count_out = count_out_reg;

endmodule

sva:
module binary_counter_assertions (
    input logic       clk,
    input logic       reset,
    input logic [3:0] count_out
);

    // While active-low reset is asserted, the counter output is zero.
    check_reset_forces_zero: assert property (
        @(posedge clk) disable iff ($initstate)
        !reset |-> (count_out == 4'h0)
    );

    // On the first sampled clock after reset is released, the counter is one.
    check_release_from_reset_starts_at_one: assert property (
        @(posedge clk) disable iff (!reset || $initstate)
        $rose(reset) |-> (count_out == 4'h1)
    );

    // A sampled zero is followed by one on the next active clock.
    check_zero_advances_to_one: assert property (
        @(posedge clk) disable iff (!reset || $initstate)
        ($past(count_out) == 4'h0) |-> (count_out == 4'h1)
    );

    // Any active count value other than one must equal the previous value plus one.
    check_active_counts_increment_except_one: assert property (
        @(posedge clk) disable iff (!reset || $initstate)
        (count_out != 4'h1) |-> (count_out == ($past(count_out) + 4'd1))
    );

    // A zero during active counting can only occur after the maximum count.
    check_wrap_to_zero_from_fifteen: assert property (
        @(posedge clk) disable iff (!reset || $initstate)
        (count_out == 4'h0) |-> ($past(count_out) == 4'hF)
    );

endmodule

rtl:
module bitwise_or(
    input [7:0] a,
    input [7:0] b,
    output [7:0] c
);

assign c = a | b;

endmodule

sva:
module bitwise_or_sva(
    input logic clk,
    input logic [7:0] a,
    input logic [7:0] b,
    input logic [7:0] c
);

    // Output must equal the bitwise OR of the inputs.
    check_c_matches_or: assert property (
        @(posedge clk) (c == (a | b))
    );

    // Any high bit on a must remain high on c.
    check_a_ones_propagate: assert property (
        @(posedge clk) ((a & ~c) == 8'h00)
    );

    // Any high bit on b must remain high on c.
    check_b_ones_propagate: assert property (
        @(posedge clk) ((b & ~c) == 8'h00)
    );

    // c must not assert bits that are low on both inputs.
    check_c_has_no_extra_ones: assert property (
        @(posedge clk) ((c & ~(a | b)) == 8'h00)
    );

endmodule

