module sky130_fd_sc_lp__a211oi (
    Y ,
    A1,
    A2,
    B1,
    C1
);

    output Y ;
    input  A1;
    input  A2;
    input  B1;
    input  C1;

    wire and0_out  ;
    wire nor0_out_Y;

    and and0 (and0_out  , A1, A2          );
    nor nor0 (nor0_out_Y, and0_out, B1, C1);
    buf buf0 (Y         , nor0_out_Y      );

endmodule

sva:
module sky130_fd_sc_lp__a211oi_sva (
    input logic clk,
    input logic Y,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic C1
);

    // Y matches the implemented A211OI Boolean function.
    check_boolean_function: assert property (
        @(posedge clk) Y == ~((A1 & A2) | B1 | C1)
    );

    // Any high on B1 or C1 forces the NOR output low.
    check_b1_or_c1_force_low: assert property (
        @(posedge clk) (B1 == 1'b1 || C1 == 1'b1) |-> (Y == 1'b0)
    );

    // A1 and A2 high together force the output low.
    check_a1_a2_and_force_low: assert property (
        @(posedge clk) (A1 == 1'b1 && A2 == 1'b1) |-> (Y == 1'b0)
    );

    // Y high requires B1 and C1 low and the A1/A2 AND term low.
    check_high_output_conditions: assert property (
        @(posedge clk) (Y == 1'b1) |-> (B1 == 1'b0 && C1 == 1'b0 && !(A1 == 1'b1 && A2 == 1'b1))
    );

    // With B1 and C1 low, a low on either A1 or A2 makes Y high.
    check_missing_and_term_drives_high: assert property (
        @(posedge clk) (B1 == 1'b0 && C1 == 1'b0 && (A1 == 1'b0 || A2 == 1'b0)) |-> (Y == 1'b1)
    );

    // If Y is low while B1 and C1 are low, both A1 and A2 must be high.
    check_low_output_from_and_term_only: assert property (
        @(posedge clk) (Y == 1'b0 && B1 == 1'b0 && C1 == 1'b0) |-> (A1 == 1'b1 && A2 == 1'b1)
    );

endmodule

rtl:
module top_module (
    input signed [3:0] A,
    input signed [3:0] B,
    output signed [3:0] out,
    output eq,
    output gt,
    output lt,
    output overflow
);

    wire signed [3:0] sum;
    wire overflow_adder;
    signed_comparator comp(A, B, eq, gt, lt);
    signed_adder adder(A, B, sum, overflow_adder);

    assign overflow = overflow_adder;

    assign out = (eq) ? sum : (gt) ? A : B;

endmodule

module signed_adder (
    input signed [3:0] A,
    input signed [3:0] B,
    output signed [3:0] out,
    output overflow
);

    wire [3:0] sum;
    wire carry;

    assign overflow = (A[3] == B[3] && sum[3] != A[3]) ? 1 : 0;

    assign {carry, sum} = A + B;

    assign out = {overflow, sum};

endmodule

module signed_comparator (
    input signed [3:0] A,
    input signed [3:0] B,
    output eq,
    output gt,
    output lt
);

    assign eq = (A == B);

    assign gt = (A > B);

    assign lt = (A < B);

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic signed [3:0] A,
    input logic signed [3:0] B,
    input logic signed [3:0] out,
    input logic eq,
    input logic gt,
    input logic lt,
    input logic overflow
);

    // eq must reflect signed equality.
    check_eq_relation: assert property (
        @(posedge clk) (eq == (A == B))
    );

    // gt must reflect signed greater-than.
    check_gt_relation: assert property (
        @(posedge clk) (gt == (A > B))
    );

    // lt must reflect signed less-than.
    check_lt_relation: assert property (
        @(posedge clk) (lt == (A < B))
    );

    // Exactly one comparator result must be asserted.
    check_compare_onehot: assert property (
        @(posedge clk) (eq || gt || lt) && !(eq && gt) && !(eq && lt) && !(gt && lt)
    );

    // overflow must match 4-bit signed addition overflow.
    check_overflow_relation: assert property (
        @(posedge clk) (overflow == ((A[3] == B[3]) && ((A + B)[3] != A[3])))
    );

    // out must follow the top-level mux selection.
    check_out_mux_relation: assert property (
        @(posedge clk) (out == (eq ? (A + B) : (gt ? A : B)))
    );

    // When A equals B, out must be the wrapped 4-bit sum.
    check_out_when_equal: assert property (
        @(posedge clk) eq |-> (out == (A + B))
    );

    // When A is greater than B, out must pass through A.
    check_out_when_greater: assert property (
        @(posedge clk) gt |-> (out == A)
    );

    // When A is less than B, out must pass through B.
    check_out_when_less: assert property (
        @(posedge clk) lt |-> (out == B)
    );

endmodule

module mux4_1_sva (
    input logic clk,
    input logic Y,
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic [1:0] S
);

    // Y matches the RTL mux expression.
    check_mux_function: assert property (
        @(posedge clk)
        Y == ((S == 2'b00) ? A :
              (S == 2'b01) ? B :
              (S == 2'b10) ? C :
                             D)
    );

    // Select 00 routes A to Y.
    check_select_a: assert property (
        @(posedge clk)
        (S == 2'b00) |-> (Y == A)
    );

    // Select 01 routes B to Y.
    check_select_b: assert property (
        @(posedge clk)
        (S == 2'b01) |-> (Y == B)
    );

    // Select 10 routes C to Y.
    check_select_c: assert property (
        @(posedge clk)
        (S == 2'b10) |-> (Y == C)
    );

    // Select 11 routes D to Y.
    check_select_d: assert property (
        @(posedge clk)
        (S == 2'b11) |-> (Y == D)
    );

    // If all inputs and select are stable, Y stays stable.
    check_output_stable_when_inputs_stable: assert property (
        @(posedge clk)
        $stable({A, B, C, D, S}) |-> $stable(Y)
    );

endmodule

module and_logic_assertions (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic reset,
    input logic [3:0] C
);

    // During active-high reset, C is forced to zero.
    check_reset_forces_zero: assert property (
        @(posedge clk) reset |-> (C == 4'b0000)
    );

    // Outside reset, C matches the bitwise AND of A and B.
    check_and_output_matches_inputs: assert property (
        @(posedge clk) disable iff (reset) (C == (A & B))
    );

endmodule

rtl:
module and4_nor (
    Y  ,
    A  ,
    B  ,
    C  ,
    D  
);

    // Module ports
    output Y  ;
    input  A  ;
    input  B  ;
    input  C  ;
    input  D  ;

    // Local signals
    wire not_A;
    wire not_B;
    wire not_C;
    wire not_D;
    wire nor0_out;
    wire nor1_out;
    wire nor2_out;
    wire buf0_out;

    // Invert inputs
    not not_A (not_A, A);
    not not_B (not_B, B);
    not not_C (not_C, C);
    not not_D (not_D, D);

    // NOR gates
    nor nor0 (nor0_out, not_A, not_B);
    nor nor1 (nor1_out, nor0_out, not_C);
    nor nor2 (Y, nor1_out, not_D);

    // Buffer
    buf buf0 (buf0_out, Y);

endmodule

sva:
module and4_nor_assertions (
    input logic Y,
    input logic A,
    input logic B,
    input logic C,
    input logic D
);

    // Y must equal the AND of all four inputs.
    check_and_function: assert property (
        @($global_clock) Y == (A & B & C & D)
    );

    // All inputs high must drive Y high.
    check_all_high_drives_y_high: assert property (
        @($global_clock) (A & B & C & D) |-> Y
    );

    // A low must force Y low.
    check_a_low_forces_y_low: assert property (
        @($global_clock) !A |-> !Y
    );

    // B low must force Y low.
    check_b_low_forces_y_low: assert property (
        @($global_clock) !B |-> !Y
    );

    // C low must force Y low.
    check_c_low_forces_y_low: assert property (
        @($global_clock) !C |-> !Y
    );

    // D low must force Y low.
    check_d_low_forces_y_low: assert property (
        @($global_clock) !D |-> !Y
    );

    // Y high requires A high.
    check_y_high_requires_a_high: assert property (
        @($global_clock) Y |-> A
    );

    // Y high requires B high.
    check_y_high_requires_b_high: assert property (
        @($global_clock) Y |-> B
    );

    // Y high requires C high.
    check_y_high_requires_c_high: assert property (
        @($global_clock) Y |-> C
    );

    // Y high requires D high.
    check_y_high_requires_d_high: assert property (
        @($global_clock) Y |-> D
    );

endmodule

rtl:
module ad_datafmt #(
  parameter DATA_WIDTH = 16,
  parameter DISABLE = 0
) (
  input clk,
  input valid,
  input [(DATA_WIDTH-1):0] data,
  output valid_out,
  output [15:0] data_out,
  input dfmt_enable,
  input dfmt_type,
  input dfmt_se
);

  reg valid_int = 'd0;
  reg [15:0] data_int = 'd0;

  wire type_s;
  wire [15:0] data_out_s;

  generate
    if (DISABLE == 1) begin
      assign valid_out = valid;
      assign data_out = data;
    end else begin
      assign valid_out = valid_int;
      assign data_out = data_int;
    end
  endgenerate

  generate
    if (DATA_WIDTH < 16) begin
      wire signext_s;
      wire sign_s;

      assign signext_s = dfmt_enable & dfmt_se;
      assign sign_s = signext_s & (type_s ^ data[(DATA_WIDTH-1)]);
      assign data_out_s[15:DATA_WIDTH] = {(16-DATA_WIDTH){sign_s}};
    end
  endgenerate

  assign type_s = dfmt_enable & dfmt_type;
  assign data_out_s[(DATA_WIDTH-1)] = type_s ^ data[(DATA_WIDTH-1)];
  assign data_out_s[(DATA_WIDTH-2):0] = data[(DATA_WIDTH-2):0];

  always @(posedge clk) begin
    valid_int <= valid;
    data_int <= data_out_s[15:0];
  end

endmodule

sva:
module ad_datafmt_sva #(
    parameter DATA_WIDTH = 16,
    parameter DISABLE = 0
) (
    input logic clk,
    input logic valid,
    input logic [(DATA_WIDTH-1):0] data,
    input logic valid_out,
    input logic [15:0] data_out,
    input logic dfmt_enable,
    input logic dfmt_type,
    input logic dfmt_se
);

generate
if (DISABLE == 1) begin : g_disabled

    // valid_out directly mirrors valid when the block is disabled.
    check_disabled_valid_passthrough: assert property (
        @(posedge clk) valid_out == valid
    );

    if (DATA_WIDTH < 16) begin : g_disabled_narrow

        // data_out is a zero-extended copy of data when the block is disabled.
        check_disabled_data_zero_extend: assert property (
            @(posedge clk) data_out == {{(16-DATA_WIDTH){1'b0}}, data}
        );

        // Upper output bits stay zero for narrow disabled configurations.
        check_disabled_upper_zero: assert property (
            @(posedge clk) data_out[15:DATA_WIDTH] == {(16-DATA_WIDTH){1'b0}}
        );

    end else begin : g_disabled_wide

        // data_out directly mirrors the low 16 bits of data when disabled.
        check_disabled_data_word_copy: assert property (
            @(posedge clk) data_out == data[15:0]
        );

    end

end else begin : g_enabled

    // valid_out is the registered valid input.
    check_enabled_valid_pipeline: assert property (
        @(posedge clk) 1'b1 |=> (valid_out == $past(valid))
    );

    if (DATA_WIDTH > 1) begin : g_enabled_low_bits

        // Lower data bits are registered without modification.
        check_enabled_lower_bits_pipeline: assert property (
            @(posedge clk) 1'b1 |=> (data_out[DATA_WIDTH-2:0] == $past(data[DATA_WIDTH-2:0]))
        );

    end

    // The output sign bit is optionally inverted and then registered.
    check_enabled_sign_bit_format: assert property (
        @(posedge clk) 1'b1 |=> (data_out[DATA_WIDTH-1] == ($past(dfmt_enable & dfmt_type) ^ $past(data[DATA_WIDTH-1])))
    );

    // With dfmt_type inactive, the sign bit is preserved.
    check_enabled_type_zero_preserve_sign: assert property (
        @(posedge clk) 1'b1 |=> ($past(dfmt_enable & dfmt_type) || (data_out[DATA_WIDTH-1] == $past(data[DATA_WIDTH-1])))
    );

    // With dfmt_type active, the sign bit is inverted.
    check_enabled_type_one_invert_sign: assert property (
        @(posedge clk) 1'b1 |=> (!$past(dfmt_enable & dfmt_type) || (data_out[DATA_WIDTH-1] == ~$past(data[DATA_WIDTH-1])))
    );

    if (DATA_WIDTH < 16) begin : g_enabled_narrow

        // Upper bits clear when sign extension was not enabled.
        check_enabled_upper_zero_without_signext: assert property (
            @(posedge clk) 1'b1 |=> ($past(dfmt_enable & dfmt_se) || (data_out[15:DATA_WIDTH] == {(16-DATA_WIDTH){1'b0}}))
        );

        // Upper bits replicate the formatted sign bit when sign extension is enabled.
        check_enabled_upper_signext: assert property (
            @(posedge clk) 1'b1 |=> (!$past(dfmt_enable & dfmt_se) || (data_out[15:DATA_WIDTH] == {(16-DATA_WIDTH){data_out[DATA_WIDTH-1]}}))
        );

        // dfmt_enable low produces a zero-extended registered copy of data.
        check_enabled_dfmt_disable_zero_extend: assert property (
            @(posedge clk) 1'b1 |=> ($past(dfmt_enable) || (data_out == {{(16-DATA_WIDTH){1'b0}}, $past(data)}))
        );

    end else begin : g_enabled_wide

        // dfmt_enable low produces a registered copy of data.
        check_enabled_dfmt_disable_word_copy: assert property (
            @(posedge clk) 1'b1 |=> ($past(dfmt_enable) || (data_out == $past(data[15:0])))
        );

    end

end
endgenerate

endmodule

module shift_register_sva (
    input logic       clk,
    input logic       reset,
    input logic       shift_in,
    input logic       shift,
    input logic [7:0] data_out
);

    // Sampling reset high clears the register by the next clock sample.
    check_reset_clears_data_out: assert property (
        @(posedge clk) reset |=> (data_out == 8'b0)
    );

    // With shift high, the next value shifts in a zero at bit 0.
    check_shift_mode_updates_full_register: assert property (
        @(posedge clk) disable iff (reset)
        shift |=> (data_out == { $past(data_out[6:0]), 1'b0 })
    );

    // With shift low, the next value shifts in shift_in at bit 0.
    check_load_mode_updates_full_register: assert property (
        @(posedge clk) disable iff (reset)
        !shift |=> (data_out == { $past(data_out[6:0]), $past(shift_in) })
    );

    // Upper bits always come from the previous lower bits.
    check_upper_bits_always_shift: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> (data_out[7:1] == $past(data_out[6:0]))
    );

    // In shift mode, the next LSB is always zero.
    check_shift_mode_inserts_zero: assert property (
        @(posedge clk) disable iff (reset)
        shift |=> (data_out[0] == 1'b0)
    );

    // In non-shift mode, the next LSB captures shift_in.
    check_load_mode_captures_shift_in: assert property (
        @(posedge clk) disable iff (reset)
        !shift |=> (data_out[0] == $past(shift_in))
    );

endmodule

rtl:
module RegisterAdd_1 (
    input clk,
    input rst,
    input load,
    input [0:0] D,
    output [0:0] Q
);

    reg [0:0] Q_next;
    reg [0:0] Q_reg;
    reg [0:0] D_reg;

    assign Q = Q_reg;

    always @ (posedge clk or posedge rst) begin
        if (rst) begin
            Q_reg <= 1'b0;
        end else begin
            Q_reg <= Q_next;
        end
    end

    always @ (*) begin
        D_reg[0] = D[0];
        Q_next[0] = (load == 1'b1) ? D[0] : (Q_reg[0] + D_reg[0]);
    end

endmodule

sva:
module RegisterAdd_1_sva (
    input logic clk,
    input logic rst,
    input logic load,
    input logic [0:0] D,
    input logic [0:0] Q
);

    // clk is the sampling clock; rst is active high.
    // Mixed logic: Q is sequential, and next-state is combinational.

    // When load is high and D is 0, the next Q is 0.
    check_load_zero_captures_zero: assert property (
        @(posedge clk) disable iff (rst)
        (load && (D == 1'b0)) |=> (Q == 1'b0)
    );

    // When load is high and D is 1, the next Q is 1.
    check_load_one_captures_one: assert property (
        @(posedge clk) disable iff (rst)
        (load && (D == 1'b1)) |=> (Q == 1'b1)
    );

    // When load is low, D is 0, and Q is 0, Q stays 0.
    check_add_zero_holds_zero: assert property (
        @(posedge clk) disable iff (rst)
        (!load && (D == 1'b0) && (Q == 1'b0)) |=> (Q == 1'b0)
    );

    // When load is low, D is 0, and Q is 1, Q stays 1.
    check_add_zero_holds_one: assert property (
        @(posedge clk) disable iff (rst)
        (!load && (D == 1'b0) && (Q == 1'b1)) |=> (Q == 1'b1)
    );

    // When load is low, D is 1, and Q is 0, Q becomes 1.
    check_add_one_sets_one: assert property (
        @(posedge clk) disable iff (rst)
        (!load && (D == 1'b1) && (Q == 1'b0)) |=> (Q == 1'b1)
    );

    // When load is low, D is 1, and Q is 1, Q becomes 0.
    check_add_one_clears_zero: assert property (
        @(posedge clk) disable iff (rst)
        (!load && (D == 1'b1) && (Q == 1'b1)) |=> (Q == 1'b0)
    );

endmodule

rtl:
module comparator #(
  parameter n = 4, // number of bits in input signals
  parameter s = 0 // 0 for unsigned, 1 for signed
)(
  input [n-1:0] in1,
  input [n-1:0] in2,
  output out
);

  assign out = (s == 1) ? (in1[n-1] ^ in2[n-1] ? in1[n-1] : in1 > in2) : (in1 > in2);

endmodule

sva:
module comparator_sva #(
  parameter n = 4,
  parameter s = 0
)(
  input logic clk,
  input logic [n-1:0] in1,
  input logic [n-1:0] in2,
  input logic out
);

  // RTL is combinational; sample its behavior on an external clock.
  // Output must match the RTL expression on every sample.
  check_output_matches_rtl: assert property (
    @(posedge clk)
    out == ((s == 1) ? ((in1[n-1] ^ in2[n-1]) ? in1[n-1] : (in1 > in2)) : (in1 > in2))
  );

  generate
    if (s == 1) begin : gen_signed
      // Different sign bits make the output follow in1's sign bit.
      check_signed_diff_sign_behavior: assert property (
        @(posedge clk)
        (in1[n-1] ^ in2[n-1]) |-> (out == in1[n-1])
      );

      // Matching sign bits use the vector greater-than result.
      check_signed_same_sign_behavior: assert property (
        @(posedge clk)
        !(in1[n-1] ^ in2[n-1]) |-> (out == (in1 > in2))
      );

      // Sign pattern 10 forces the output high.
      check_signed_10_high: assert property (
        @(posedge clk)
        (in1[n-1] && !in2[n-1]) |-> out
      );

      // Sign pattern 01 forces the output low.
      check_signed_01_low: assert property (
        @(posedge clk)
        (!in1[n-1] && in2[n-1]) |-> !out
      );

      // Equal inputs never assert the output.
      check_signed_equal_inputs_low: assert property (
        @(posedge clk)
        (in1 == in2) |-> !out
      );
    end else begin : gen_unsigned
      // A larger in1 must assert the output.
      check_unsigned_gt_high: assert property (
        @(posedge clk)
        (in1 > in2) |-> out
      );

      // A smaller in1 must deassert the output.
      check_unsigned_lt_low: assert property (
        @(posedge clk)
        (in1 < in2) |-> !out
      );

      // Equal inputs never assert the output.
      check_unsigned_equal_inputs_low: assert property (
        @(posedge clk)
        (in1 == in2) |-> !out
      );
    end
  endgenerate

endmodule

rtl:
module absolute_counter (
    input clk,
    input rst,
    input en,
    input ld,
    input signed [31:0] in,
    input [3:0] load_data,
    output [35:0] out
);

    // Absolute value module
    wire [31:0] abs_val;
    assign abs_val = (in < 0) ? -in : in;

    // Binary counter module
    reg [3:0] counter;
    always @(posedge clk) begin
        if (rst) begin
            counter <= 4'b0000;
        end else if (en) begin
            counter <= counter + 1;
        end else if (ld) begin
            counter <= load_data;
        end
    end

    // Output module
    assign out = abs_val + {32'b0, counter};

endmodule

sva:
module absolute_counter_sva (
    input logic clk,
    input logic rst,
    input logic en,
    input logic ld,
    input logic signed [31:0] in,
    input logic [3:0] load_data,
    input logic [35:0] out
);

    // After a reset cycle, the counter contribution is cleared.
    check_reset_clears_counter: assert property (
        @(posedge clk)
        rst |=> (out == {4'b0000, ((in < 32'sd0) ? -in : in)})
    );

    // The output is always the absolute input plus a 4-bit counter value.
    check_counter_contribution_range: assert property (
        @(posedge clk) disable iff (rst)
        (out >= {4'b0000, ((in < 32'sd0) ? -in : in)}) &&
        ((out - {4'b0000, ((in < 32'sd0) ? -in : in)}) <= 36'd15)
    );

    // When en is high, the counter increments modulo 16 on the next cycle.
    check_enable_increments_counter: assert property (
        @(posedge clk) disable iff (rst)
        en |=> ((out - {4'b0000, ((in < 32'sd0) ? -in : in)}) ==
                (($past(out - {4'b0000, ((in < 32'sd0) ? -in : in)}) + 36'd1) & 36'hF))
    );

    // When ld is high and en is low, the next counter value comes from load_data.
    check_load_updates_counter: assert property (
        @(posedge clk) disable iff (rst)
        (!en && ld) |=> (out == ({4'b0000, ((in < 32'sd0) ? -in : in)} + {32'b0, $past(load_data)}))
    );

    // When neither en nor ld is high, the counter value holds.
    check_hold_preserves_counter: assert property (
        @(posedge clk) disable iff (rst)
        (!en && !ld) |=> ((out - {4'b0000, ((in < 32'sd0) ? -in : in)}) ==
                          $past(out - {4'b0000, ((in < 32'sd0) ? -in : in)}))
    );

endmodule

rtl:
module Round_Sgf_Dec(

    input wire [1:0] Data_i,
    input wire [1:0] Round_Type_i,
    input wire Sign_Result_i,
    output reg Round_Flag_o
    );

    always @*
    	case ({Sign_Result_i,Round_Type_i,Data_i})






    	5'b10101: Round_Flag_o <=1;  
    	5'b10110: Round_Flag_o <=1;  
    	5'b10111: Round_Flag_o <=1;  

    	5'b01001: Round_Flag_o <=1;  
    	5'b01010: Round_Flag_o <=1;  
    	5'b01011: Round_Flag_o <=1;  




    	default: Round_Flag_o <=0;

    	endcase

endmodule

sva:
module Round_Sgf_Dec_sva (
    input logic [1:0] Data_i,
    input logic [1:0] Round_Type_i,
    input logic Sign_Result_i,
    input logic Round_Flag_o
);

    // Round_Flag_o matches the six explicit case items in the RTL.
    check_round_flag_exact_decode: assert property (
        @($global_clock)
        Round_Flag_o === (
            ({Sign_Result_i, Round_Type_i, Data_i} === 5'b10101) ||
            ({Sign_Result_i, Round_Type_i, Data_i} === 5'b10110) ||
            ({Sign_Result_i, Round_Type_i, Data_i} === 5'b10111) ||
            ({Sign_Result_i, Round_Type_i, Data_i} === 5'b01001) ||
            ({Sign_Result_i, Round_Type_i, Data_i} === 5'b01010) ||
            ({Sign_Result_i, Round_Type_i, Data_i} === 5'b01011)
        )
    );

    // Sign 1, round type 01, and nonzero data set the flag.
    check_type01_positive_nonzero_sets_flag: assert property (
        @($global_clock)
        ((Sign_Result_i === 1'b1) &&
         (Round_Type_i === 2'b01) &&
         ((Data_i === 2'b01) || (Data_i === 2'b10) || (Data_i === 2'b11)))
        |-> (Round_Flag_o === 1'b1)
    );

    // Sign 0, round type 10, and nonzero data set the flag.
    check_type10_negative_nonzero_sets_flag: assert property (
        @($global_clock)
        ((Sign_Result_i === 1'b0) &&
         (Round_Type_i === 2'b10) &&
         ((Data_i === 2'b01) || (Data_i === 2'b10) || (Data_i === 2'b11)))
        |-> (Round_Flag_o === 1'b1)
    );

    // Zero data always clears the flag.
    check_zero_data_clears_flag: assert property (
        @($global_clock)
        (Data_i === 2'b00) |-> (Round_Flag_o === 1'b0)
    );

    // Round type 00 always clears the flag.
    check_round_type00_clears_flag: assert property (
        @($global_clock)
        (Round_Type_i === 2'b00) |-> (Round_Flag_o === 1'b0)
    );

    // Round type 11 always clears the flag.
    check_round_type11_clears_flag: assert property (
        @($global_clock)
        (Round_Type_i === 2'b11) |-> (Round_Flag_o === 1'b0)
    );

    // Round type 01 with sign 0 never sets the flag.
    check_type01_negative_clears_flag: assert property (
        @($global_clock)
        ((Sign_Result_i === 1'b0) && (Round_Type_i === 2'b01)) |-> (Round_Flag_o === 1'b0)
    );

    // Round type 10 with sign 1 never sets the flag.
    check_type10_positive_clears_flag: assert property (
        @($global_clock)
        ((Sign_Result_i === 1'b1) && (Round_Type_i === 2'b10)) |-> (Round_Flag_o === 1'b0)
    );

    // A high flag requires nonzero data.
    check_flag_high_requires_nonzero_data: assert property (
        @($global_clock)
        (Round_Flag_o === 1'b1) |-> ((Data_i === 2'b01) || (Data_i === 2'b10) || (Data_i === 2'b11))
    );

    // A high flag requires one of the two valid sign/type pairings.
    check_flag_high_requires_supported_sign_type: assert property (
        @($global_clock)
        (Round_Flag_o === 1'b1) |-> (
            ((Sign_Result_i === 1'b1) && (Round_Type_i === 2'b01)) ||
            ((Sign_Result_i === 1'b0) && (Round_Type_i === 2'b10))
        )
    );

endmodule

rtl:
module bitwise_shift(a, y);
  input [31:0] a;
  output [31:0] y;

  assign y = 12345 >> a;

endmodule

sva:
module bitwise_shift_sva (
    input logic        clk,
    input logic [31:0] a,
    input logic [31:0] y
);

    // y must always equal 12345 logically right-shifted by a.
    check_shift_result: assert property (
        @(posedge clk) y == (32'd12345 >> a)
    );

    // A zero shift must leave the constant unchanged.
    check_shift_by_zero: assert property (
        @(posedge clk) (a == 32'd0) |-> (y == 32'd12345)
    );

    // Shift amounts of 14 or more must produce zero.
    check_large_shift_zero: assert property (
        @(posedge clk) (a >= 32'd14) |-> (y == 32'd0)
    );

    // Right-shifting 12345 can never set bits above bit 13.
    check_upper_bits_zero: assert property (
        @(posedge clk) y[31:14] == 18'd0
    );

endmodule

rtl:
module sequential_circuit (
  input clk,
  input a,
  input b,
  output [1:0] q
);

  reg [1:0] counter;
  reg flip_flop;

  always @(posedge clk) begin
    if (b) begin
      counter <= 2'b0;
    end else if (a) begin
      counter <= counter + 2'b1;
    end
  end

  always @(posedge clk) begin
    flip_flop <= counter[1];
  end

  assign q = counter;

endmodule

sva:
module sequential_circuit_sva (
    input logic       clk,
    input logic       a,
    input logic       b,
    input logic [1:0] q,
    input logic [1:0] counter,
    input logic       flip_flop
);

    // q is a direct reflection of the counter register.
    check_q_matches_counter: assert property (
        @(posedge clk) disable iff ($initstate)
        (q == counter)
    );

    // When only b was high, the counter resets to zero on the next cycle.
    check_counter_resets_on_b: assert property (
        @(posedge clk) disable iff ($initstate)
        ($past(b) && !$past(a)) |-> (counter == 2'b00)
    );

    // When both a and b were high, b has priority and the counter resets.
    check_b_priority_over_a: assert property (
        @(posedge clk) disable iff ($initstate)
        ($past(b) && $past(a)) |-> (counter == 2'b00)
    );

    // When only a was high, the counter increments by one on the next cycle.
    check_counter_increments_on_a: assert property (
        @(posedge clk) disable iff ($initstate)
        (!$past(b) && $past(a)) |-> (counter == ($past(counter) + 2'b01))
    );

    // When neither input was high, the counter holds its value.
    check_counter_holds_when_idle: assert property (
        @(posedge clk) disable iff ($initstate)
        (!$past(b) && !$past(a)) |-> (counter == $past(counter))
    );

    // flip_flop captures the previous cycle's counter MSB.
    check_flip_flop_tracks_counter_msb: assert property (
        @(posedge clk) disable iff ($initstate)
        (flip_flop == $past(counter[1]))
    );

endmodule

rtl:
module adder_4bit_carry (
    input [3:0] a,
    input [3:0] b,
    input cin,
    output [3:0] sum,
    output cout
);

    wire [4:0] full_sum;
    assign full_sum = {1'b0, a} + {1'b0, b} + {1'b0, cin};

    assign sum = full_sum[3:0];
    assign cout = full_sum[4];

endmodule

sva:
module adder_4bit_carry_sva (
    input logic clk,
    input logic [3:0] a,
    input logic [3:0] b,
    input logic cin,
    input logic [3:0] sum,
    input logic cout
);

    // Combined outputs must match the 5-bit addition of a, b, and cin.
    check_full_add_result: assert property (
        @(posedge clk) {cout, sum} == ({1'b0, a} + {1'b0, b} + cin)
    );

    // Sum must match the lower 4 bits of the addition result.
    check_sum_lower_bits: assert property (
        @(posedge clk) {1'b0, sum} == (({1'b0, a} + {1'b0, b} + cin) & 5'h0F)
    );

    // Carry-out must indicate whether the addition result exceeds 4 bits.
    check_carry_overflow: assert property (
        @(posedge clk) cout == (({1'b0, a} + {1'b0, b} + cin) >= 5'd16)
    );

    // Zero inputs must produce a zero sum and no carry.
    check_zero_addition: assert property (
        @(posedge clk) (a == 4'h0 && b == 4'h0 && cin == 1'b0) |-> (sum == 4'h0 && cout == 1'b0)
    );

    // Maximum inputs with carry-in must produce 0xF with carry-out asserted.
    check_max_addition: assert property (
        @(posedge clk) (a == 4'hF && b == 4'hF && cin == 1'b1) |-> (sum == 4'hF && cout == 1'b1)
    );

endmodule

rtl:
module input_buffer (
    input in,
    input en,
    output out
);

reg stored_out;
always @ (posedge en) begin
    if (en) begin
        stored_out <= in;
    end
end

assign out = en ? in : stored_out;

endmodule

sva:
module input_buffer_assertions (
    input logic in,
    input logic en,
    input logic out,
    input logic stored_out
);

    // When en is low just before it rises, out must reflect the stored value.
    check_disabled_path_uses_stored_out: assert property (
        @(posedge en) out === stored_out
    );

    // When en is high just before it falls, out must reflect the live input.
    check_enabled_path_uses_input: assert property (
        @(negedge en) out === in
    );

    // On each later enable pulse, stored_out must still hold the input captured on the prior pulse.
    check_stored_out_keeps_last_captured_input: assert property (
        @(posedge en) 1'b1 |=> stored_out === $past(in)
    );

    // On each later enable pulse, out must present the value captured on the prior pulse while en is low.
    check_output_keeps_last_captured_input_while_disabled: assert property (
        @(posedge en) 1'b1 |=> out === $past(in)
    );

endmodule

rtl:
module up_down_counter (
    input UD,
    input RST,
    input clk,
    output reg [3:0] Q,
    output reg OVF
);

always @ (posedge clk or negedge RST) begin
    if (RST == 0) begin
        Q <= 4'b0;
        OVF <= 0;
    end
    else if (UD == 1) begin
        if (Q == 4'hF) begin
            Q <= 4'b0;
            OVF <= 1;
        end
        else begin
            Q <= Q + 1;
            OVF <= 0;
        end
    end
    else begin
        if (Q == 4'b0) begin
            Q <= 4'hF;
            OVF <= 1;
        end
        else begin
            Q <= Q - 1;
            OVF <= 0;
        end
    end
end

endmodule

sva:
module up_down_counter_sva (
    input logic       UD,
    input logic       RST,
    input logic       clk,
    input logic [3:0] Q,
    input logic       OVF
);

    // Reset forces Q and OVF low.
    check_reset_clears_state: assert property (
        @(posedge clk) !RST |-> ((Q == 4'h0) && (OVF == 1'b0))
    );

    // Counting up below 15 increments Q and clears OVF.
    check_count_up_increment: assert property (
        @(posedge clk) disable iff (!RST)
        (UD && (Q != 4'hF)) |=> ((Q == ($past(Q) + 4'h1)) && (OVF == 1'b0))
    );

    // Counting up at 15 wraps Q to 0 and sets OVF.
    check_count_up_wrap: assert property (
        @(posedge clk) disable iff (!RST)
        (UD && (Q == 4'hF)) |=> ((Q == 4'h0) && (OVF == 1'b1))
    );

    // Counting down above 0 decrements Q and clears OVF.
    check_count_down_decrement: assert property (
        @(posedge clk) disable iff (!RST)
        (!UD && (Q != 4'h0)) |=> ((Q == ($past(Q) - 4'h1)) && (OVF == 1'b0))
    );

    // Counting down at 0 wraps Q to 15 and sets OVF.
    check_count_down_wrap: assert property (
        @(posedge clk) disable iff (!RST)
        (!UD && (Q == 4'h0)) |=> ((Q == 4'hF) && (OVF == 1'b1))
    );

    // Overflow can only appear with a wrapped boundary value.
    check_ovf_implies_boundary_q: assert property (
        @(posedge clk) disable iff (!RST)
        OVF |-> ((Q == 4'h0) || (Q == 4'hF))
    );

    // Midrange counter values must not assert overflow.
    check_midrange_q_has_no_ovf: assert property (
        @(posedge clk) disable iff (!RST)
        ((Q != 4'h0) && (Q != 4'hF)) |-> (OVF == 1'b0)
    );

endmodule

rtl:
module sky130_fd_sc_ls__a311o (
    X ,
    A1,
    A2,
    A3,
    B1,
    C1
);

    output X ;
    input  A1;
    input  A2;
    input  A3;
    input  B1;
    input  C1;

    wire and0_out ;
    wire or0_out_X;

    and and0 (and0_out , A3, A1, A2      );
    or  or0  (or0_out_X, and0_out, C1, B1);
    buf buf0 (X        , or0_out_X       );

