rtl:
module sky130_fd_sc_hdll__nand3b (
    Y  ,
    A_N,
    B  ,
    C
);

    output Y  ;
    input  A_N;
    input  B  ;
    input  C  ;

    wire not0_out   ;
    wire nand0_out_Y;

    not  not0  (not0_out   , A_N            );
    nand nand0 (nand0_out_Y, B, not0_out, C );
    buf  buf0  (Y          , nand0_out_Y    );

endmodule

sva:
module sky130_fd_sc_hdll__nand3b_sva (
    input logic Y,
    input logic A_N,
    input logic B,
    input logic C
);

    // Y matches the implemented NAND-with-inverted-A function.
    check_functional_equivalence: assert property (
        @($global_clock) (Y == ~(B & ~A_N & C))
    );

    // A_N high forces Y high.
    check_a_n_high_forces_y_high: assert property (
        @($global_clock) A_N |-> Y
    );

    // B low forces Y high.
    check_b_low_forces_y_high: assert property (
        @($global_clock) (!B) |-> Y
    );

    // C low forces Y high.
    check_c_low_forces_y_high: assert property (
        @($global_clock) (!C) |-> Y
    );

    // With B and C high, Y reduces to A_N.
    check_b_c_high_reduces_to_a_n: assert property (
        @($global_clock) (B && C) |-> (Y == A_N)
    );

    // With A_N low and C high, Y reduces to inverted B.
    check_a_n_low_c_high_reduces_to_not_b: assert property (
        @($global_clock) ((!A_N) && C) |-> (Y == ~B)
    );

    // With A_N low and B high, Y reduces to inverted C.
    check_a_n_low_b_high_reduces_to_not_c: assert property (
        @($global_clock) ((!A_N) && B) |-> (Y == ~C)
    );

    // Y low requires A_N low with B and C high.
    check_y_low_requires_specific_inputs: assert property (
        @($global_clock) (!Y) |-> ((!A_N) && B && C)
    );

endmodule

rtl:
module Select_AB
          (
           in_select,
           in1,
           in2,
           A,
           B
          );


  input   in_select;
  input   in1;
  input   in2;
  output  A;
  output  B;


  wire Switch_out1;
  wire Switch1_out1;


  assign Switch_out1 = (in_select == 1'b0 ? in2 :
              in1);



  assign A = Switch_out1;

  assign Switch1_out1 = (in_select == 1'b0 ? in1 :
              in2);



  assign B = Switch1_out1;

endmodule

sva:
module Select_AB_sva (
    input logic clk,
    input logic in_select,
    input logic in1,
    input logic in2,
    input logic A,
    input logic B
);

    // A matches the RTL mux expression.
    check_a_function: assert property (
        @(posedge clk) A === ((in_select == 1'b0) ? in2 : in1)
    );

    // B matches the RTL mux expression.
    check_b_function: assert property (
        @(posedge clk) B === ((in_select == 1'b0) ? in1 : in2)
    );

    // When select is low, A routes in2 and B routes in1.
    check_select_low_routes_outputs: assert property (
        @(posedge clk) (in_select === 1'b0) |-> ((A === in2) && (B === in1))
    );

    // When select is high, A routes in1 and B routes in2.
    check_select_high_routes_outputs: assert property (
