module binary_counter_sva(
    input logic       clk,
    input logic       rst,
    input logic       en,
    input logic [3:0] out
);

    // Reset clears the counter on the next sampled cycle.
    check_reset_clears_out: assert property (
        @(posedge clk) rst |=> (out == 4'b0000)
    );

    // Reset takes priority over enable and still clears the counter.
    check_reset_priority_over_enable: assert property (
        @(posedge clk) (rst && en) |=> (out == 4'b0000)
    );

    // When enabled outside reset, the counter increments by one.
    check_increment_when_enabled: assert property (
        @(posedge clk) disable iff (rst)
        en |=> (out == ($past(out) + 4'd1))
    );

    // When disabled outside reset, the counter holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (rst)
        !en |=> (out == $past(out))
    );

    // Outside reset, the next state is either hold or increment.
    check_only_hold_or_increment: assert property (
        @(posedge clk) disable iff (rst)
        1'b1 |=> ((out == $past(out)) || (out == ($past(out) + 4'd1)))
    );

    // Enabling the counter at 4'hF wraps it back to 4'h0.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (rst)
        (en && (out == 4'hF)) |=> (out == 4'h0)
    );

endmodule

rtl:
module binary_counter
(
    input clk,
    input reset,
    output reg [3:0] count
);

    always @(posedge clk or posedge reset)
    begin
        if (reset)
            count <= 4'b0000;
        else
            count <= count + 1;
    end

endmodule

sva:
module binary_counter_sva (
    input logic       clk,
    input logic       reset,
    input logic [3:0] count
);

    // A sampled reset must leave the counter at zero by the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'b0000)
    );

    // Between non-reset samples, count can only advance by one or be cleared to zero.
    check_count_transition_is_increment_or_zero: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> ((count == ($past(count) + 4'd1)) || (count == 4'b0000))
    );

    // A sampled maximum count must wrap to zero on the next sample.
    check_wraps_after_max: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> (($past(count) != 4'hF) || (count == 4'h0))
    );

    // From a sampled zero, the next nonzero value can only be one.
    check_zero_advances_to_one: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> (($past(count) != 4'h0) || (count == 4'h0) || (count == 4'h1))
    );

endmodule

