module logic_expression(
    input A,
    input B,
    input C,
    input D,
    input E,
    output X
    );

    wire w1, w2, w3, w4, w5, w6, w7, w8, w9, w10, w11, w12;

    assign w1 = ~A & ~B & ~C & D & ~E;
    assign w2 = ~A & ~B & ~C & D & E;
    assign w3 = ~A & ~B & C & ~D & E;
    assign w4 = ~A & ~B & C & D & E;
    assign w5 = ~A & B & ~C & ~D & E;
    assign w6 = ~A & B & ~C & D & E;
    assign w7 = ~A & B & C & ~D & E;
    assign w8 = A & ~B & ~C & ~D & E;
    assign w9 = A & ~B & ~C & D & E;
    assign w10 = A & ~B & C & D & E;
    assign w11 = A & B & C & ~D & E;
    assign w12 = A & B & C & D & E;

    assign X = w1 | w2 | w3 | w4 | w5 | w6 | w7 | w8 | w9 | w10 | w11 | w12;

endmodule

sva:
module logic_expression_sva (
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic E,
    input logic X
);

    // X matches the full RTL sum-of-products expression.
    check_x_matches_full_expression: assert property (
        @($global_clock)
        X == ((~A & ~B & ~C & D & ~E) |
              (~A & ~B & ~C & D & E)  |
              (~A & ~B & C & ~D & E)  |
              (~A & ~B & C & D & E)   |
              (~A & B & ~C & ~D & E)  |
              (~A & B & ~C & D & E)   |
              (~A & B & C & ~D & E)   |
              (A & ~B & ~C & ~D & E)  |
              (A & ~B & ~C & D & E)   |
              (A & ~B & C & D & E)    |
              (A & B & C & ~D & E)    |
              (A & B & C & D & E))
    );

    // When E is low, only the w1 term can make X high.
    check_e_low_behavior: assert property (
        @($global_clock)
        (~E) |-> (X == (~A & ~B & ~C & D))
    );

    // For A=0, B=0, E=1, X reduces to C or D.
    check_ab00_e_high_behavior: assert property (
        @($global_clock)
        (~A & ~B & E) |-> (X == (C | D))
    );

    // For A=0, B=1, E=1, X reduces to not C or not D.
    check_ab01_e_high_behavior: assert property (
        @($global_clock)
        (~A & B & E) |-> (X == (~C | ~D))
    );

    // For A=1, B=0, E=1, X reduces to not C or D.
    check_ab10_e_high_behavior: assert property (
        @($global_clock)
        (A & ~B & E) |-> (X == (~C | D))
    );

    // For A=1, B=1, E=1, X reduces to C.
    check_ab11_e_high_behavior: assert property (
        @($global_clock)
        (A & B & E) |-> (X == C)
    );

endmodule

rtl:
module mux8to1 (
    output reg y,
    input s2,
    input s1,
    input s0,
    input d4,
    input d3,
    input d2,
    input d1,
    input d0
);

always @(*) begin
    case ({s2, s1, s0})
        3'b000: y = d0;
        3'b001: y = d1;
        3'b010: y = d2;
        3'b011: y = d3;
        3'b100: y = d4;
        default: y = 1'b0;
    endcase
end

endmodule

sva:
module mux8to1_sva (
    input logic y,
    input logic s2,
    input logic s1,
    input logic s0,
    input logic d4,
    input logic d3,
    input logic d2,
    input logic d1,
    input logic d0
);

    // Select 000 routes d0 to y.
    check_select_000_routes_d0: assert property (
        @($global_clock) ({s2, s1, s0} === 3'b000) |-> (y === d0)
    );

    // Select 001 routes d1 to y.
    check_select_001_routes_d1: assert property (
        @($global_clock) ({s2, s1, s0} === 3'b001) |-> (y === d1)
    );

    // Select 010 routes d2 to y.
    check_select_010_routes_d2: assert property (
        @($global_clock) ({s2, s1, s0} === 3'b010) |-> (y === d2)
    );

    // Select 011 routes d3 to y.
    check_select_011_routes_d3: assert property (
        @($global_clock) ({s2, s1, s0} === 3'b011) |-> (y === d3)
    );

    // Select 100 routes d4 to y.
    check_select_100_routes_d4: assert property (
        @($global_clock) ({s2, s1, s0} === 3'b100) |-> (y === d4)
    );

    // Any unsupported or unknown select value drives y low.
    check_unimplemented_select_drives_zero: assert property (
        @($global_clock)
        !(
            ({s2, s1, s0} === 3'b000) ||
            ({s2, s1, s0} === 3'b001) ||
            ({s2, s1, s0} === 3'b010) ||
            ({s2, s1, s0} === 3'b011) ||
            ({s2, s1, s0} === 3'b100)
        ) |-> (y === 1'b0)
    );

    // Unselected inputs do not affect y when select and the chosen source are unchanged.
    check_unselected_inputs_do_not_affect_y: assert property (
        @($global_clock)
        $stable({s2, s1, s0}) &&
        (
            (({s2, s1, s0} === 3'b000) && $stable(d0)) ||
            (({s2, s1, s0} === 3'b001) && $stable(d1)) ||
            (({s2, s1, s0} === 3'b010) && $stable(d2)) ||
            (({s2, s1, s0} === 3'b011) && $stable(d3)) ||
            (({s2, s1, s0} === 3'b100) && $stable(d4)) ||
            !(
                ({s2, s1, s0} === 3'b000) ||
                ({s2, s1, s0} === 3'b001) ||
                ({s2, s1, s0} === 3'b010) ||
                ({s2, s1, s0} === 3'b011) ||
                ({s2, s1, s0} === 3'b100)
            )
        ) |-> $stable(y)
    );

endmodule

