module top_module_sva (
    input logic clk,
    input logic reset,
    input logic [3:0] A,
    input logic [1:0] B,
    input logic UP,
    input logic DOWN,
    input logic [7:0] q,
    input logic [3:0] shifted,
    input logic [2:0] Q
);

    // B=00 leaves A unchanged.
    check_shift_passthrough: assert property (
        @(posedge clk) disable iff (reset)
        (B == 2'b00) |-> (shifted == A)
    );

    // B=01 rotates A left by 1.
    check_shift_rotate_left_1: assert property (
        @(posedge clk) disable iff (reset)
        (B == 2'b01) |-> (shifted == {A[2:0], A[3]})
    );

    // B=10 rotates A left by 2.
    check_shift_rotate_left_2: assert property (
        @(posedge clk) disable iff (reset)
        (B == 2'b10) |-> (shifted == {A[1:0], A[3:2]})
    );

    // B=11 rotates A left by 3.
    check_shift_rotate_left_3: assert property (
        @(posedge clk) disable iff (reset)
        (B == 2'b11) |-> (shifted == {A[0], A[3:1]})
    );

    // Reset clears the counter state.
    check_counter_reset_clears_Q: assert property (
        @(posedge clk)
        reset |=> (Q == 3'b000)
    );

    // UP without DOWN increments the counter.
    check_counter_increment: assert property (
        @(posedge clk) disable iff (reset)
        (UP && !DOWN) |=> (Q == ($past(Q) + 3'b001))
    );

    // DOWN without UP decrements the counter.
    check_counter_decrement: assert property (
        @(posedge clk) disable iff (reset)
        (!UP && DOWN) |=> (Q == ($past(Q) - 3'b001))
    );

    // No request leaves the counter unchanged.
    check_counter_hold_idle: assert property (
        @(posedge clk) disable iff (reset)
        (!UP && !DOWN) |=> (Q == $past(Q))
    );

    // Simultaneous UP and DOWN leaves the counter unchanged.
    check_counter_hold_both_high: assert property (
        @(posedge clk) disable iff (reset)
        (UP && DOWN) |=> (Q == $past(Q))
    );

    // Output q is the sum of shifted and Q with zero extension.
    check_output_sum: assert property (
        @(posedge clk) disable iff (reset)
        (q == ({4'b0000, shifted} + {3'b000, Q}))
    );

endmodule

module up_down_counter_sva (
    input logic       clk,
    input logic       reset,
    input logic       direction,
    input logic [3:0] count
);

    // Reset drives the counter to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'b0000)
    );

    // In up mode, 15 wraps to 0.
    check_up_wrap_from_max: assert property (
        @(posedge clk) disable iff (reset)
        direction && (count == 4'b1111) |=> (count == 4'b0000)
    );

    // In up mode, values below 15 increment by 1.
    check_up_increment: assert property (
        @(posedge clk) disable iff (reset)
        direction && (count != 4'b1111) |=> (count == ($past(count) + 4'd1))
    );

    // In down mode, 0 wraps to 15.
    check_down_wrap_from_zero: assert property (
        @(posedge clk) disable iff (reset)
        !direction && (count == 4'b0000) |=> (count == 4'b1111)
    );

    // In down mode, values above 0 decrement by 1.
    check_down_decrement: assert property (
        @(posedge clk) disable iff (reset)
        !direction && (count != 4'b0000) |=> (count == ($past(count) - 4'd1))
    );

endmodule

module add_sub_4bit_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic mode,
    input logic [3:0] O,
    input logic COUT
);

    // Addition mode must drive the concatenated result from A + B.
    check_add_result: assert property (
        @($global_clock) (mode == 1'b0) |-> ({COUT, O} == (A + B))
    );

    // Subtraction mode must drive the concatenated result from A - B.
    check_sub_result: assert property (
        @($global_clock) (mode == 1'b1) |-> ({COUT, O} == (A - B))
    );

    // Adding zero on B must pass A through unchanged.
    check_add_zero_b_identity: assert property (
        @($global_clock) ((mode == 1'b0) && (B == 4'b0000)) |-> ({COUT, O} == A)
    );

    // Adding zero on A must pass B through unchanged.
    check_add_zero_a_identity: assert property (
        @($global_clock) ((mode == 1'b0) && (A == 4'b0000)) |-> ({COUT, O} == B)
    );

    // Subtracting zero must pass A through unchanged.
    check_sub_zero_b_identity: assert property (
        @($global_clock) ((mode == 1'b1) && (B == 4'b0000)) |-> ({COUT, O} == A)
    );

    // Subtracting equal operands must produce zero.
    check_sub_equal_operands_zero: assert property (
        @($global_clock) ((mode == 1'b1) && (A == B)) |-> ({COUT, O} == 5'b00000)
    );

endmodule

