module logic_circuit (
    input A1,
    input A2,
    input B1,
    input B2,
    output X
);

    wire or0_out;
    wire or1_out;
    wire and0_out_X;

    or or0 (or0_out, A2, A1);
    or or1 (or1_out, B2, B1);
    and and0 (and0_out_X, or0_out, or1_out);
    buf buf0 (X, and0_out_X);

endmodule

