module mult_gate (
    output Y,
    input J,
    input I,
    input H,
    input G,
    input F,
    input E,
    input D,
    input C,
    input B,
    input A
);

    wire w3;
    wire w2;
    wire w1;

    and gate3(w3, I, H, G);
    and gate2(w2, F, E, D);
    and gate1(w1, C, B, A);
    or gate4(Y, w3, w2, w1, J);

endmodule

sva:
module mult_gate_sva (
    input logic clk,
    input logic Y,
    input logic J,
    input logic I,
    input logic H,
    input logic G,
    input logic F,
    input logic E,
    input logic D,
    input logic C,
    input logic B,
    input logic A
);

    // Y must equal J OR the three 3-input AND terms.
    check_output_equation: assert property (
        @(posedge clk)
        Y == (J | (I & H & G) | (F & E & D) | (C & B & A))
    );

    // J asserted must drive Y high.
    check_j_drives_y_high: assert property (
        @(posedge clk)
        J |-> Y
    );

    // I, H, and G all high must drive Y high.
    check_ihg_drives_y_high: assert property (
        @(posedge clk)
        (I & H & G) |-> Y
    );

    // F, E, and D all high must drive Y high.
    check_fed_drives_y_high: assert property (
        @(posedge clk)
        (F & E & D) |-> Y
    );

    // C, B, and A all high must drive Y high.
    check_cba_drives_y_high: assert property (
        @(posedge clk)
        (C & B & A) |-> Y
    );

    // Y high must come from J or one of the AND terms.
    check_y_high_has_valid_source: assert property (
        @(posedge clk)
        Y |-> (J | (I & H & G) | (F & E & D) | (C & B & A))
    );

    // With all source terms low, Y must be low.
    check_no_source_means_y_low: assert property (
        @(posedge clk)
        !(J | (I & H & G) | (F & E & D) | (C & B & A)) |-> !Y
    );

endmodule

module dff_rs_sva (
    input logic clk,
    input logic rst,
    input logic set,
    input logic d,
    input logic q
);

    // Reset forces q low on the following cycle.
    check_reset_clears_q: assert property (
        @(posedge clk) rst |=> (q == 1'b0)
    );

    // Reset has priority over set when both are asserted.
    check_reset_priority_over_set: assert property (
        @(posedge clk) (rst && set) |=> (q == 1'b0)
    );

    // Set drives q high when reset is not asserted.
    check_set_drives_q_high: assert property (
        @(posedge clk) disable iff (rst) set |=> (q == 1'b1)
    );

    // Set overrides d when d is low.
    check_set_priority_over_d: assert property (
        @(posedge clk) disable iff (rst) (set && !d) |=> (q == 1'b1)
    );

    // With no reset or set, d=1 is captured into q.
    check_capture_d_high: assert property (
        @(posedge clk) disable iff (rst) (!set && d) |=> (q == 1'b1)
    );

    // With no reset or set, d=0 is captured into q.
    check_capture_d_low: assert property (
        @(posedge clk) disable iff (rst) (!set && !d) |=> (q == 1'b0)
    );

endmodule

