    check_d_change_propagates: assert property (
        @(posedge CLK) (!$initstate && (D != $past(D))) |=> (Q != $past(Q))
    );

    // An unchanged sampled D keeps Q unchanged one cycle later.
    check_d_stable_keeps_q_stable: assert property (
        @(posedge CLK) (!$initstate && (D == $past(D))) |=> (Q == $past(Q))
    );

