    input  A2  ;
    input  B1  ;
    input  C1  ;
    input  VPWR;
    input  VGND;
    input  VPB ;
    input  VNB ;

    assign Y = (A1 & A2) | ((!A1) & (!A2) & B1 & (!C1)) | ((!A1) & (!A2) & (!B1) & C1);

