module counter_module (
    input clk,
    input reset,
    output [7:0] count
);

parameter max_count = 255;
reg [7:0] internal_count;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        internal_count <= 8'd0;
    end else if (internal_count == max_count) begin
        internal_count <= 8'd0;
    end else begin
        internal_count <= internal_count + 1;
    end
end

assign count = internal_count;

endmodule

sva:
module counter_module_sva #(
    parameter int unsigned max_count = 255
) (
    input logic       clk,
    input logic       reset,
    input logic [7:0] count
);

    // Count either increments or returns to zero on each active clock.
    check_count_step_or_zero: assert property (
        @(posedge clk) disable iff (reset)
        !$initstate |-> ((count == 8'd0) || (count == ($past(count) + 8'd1)))
    );

    // A sampled max_count value wraps to zero on the next active clock.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (reset)
        (!$initstate && ($past(count) == max_count)) |-> (count == 8'd0)
    );

    // Any nonzero count must come from incrementing the previous sampled value.
    check_nonzero_is_increment: assert property (
        @(posedge clk) disable iff (reset)
        (!$initstate && (count != 8'd0)) |-> (!$past(reset) && (count == ($past(count) + 8'd1)))
    );

    // The first active clock after a sampled reset still shows zero.
    check_post_reset_zero: assert property (
        @(posedge clk) disable iff (reset)
        (!$initstate && $past(reset)) |-> (count == 8'd0)
    );

    // Once the count is in range, the next sampled count stays in range.
    check_range_invariant: assert property (
        @(posedge clk) disable iff (reset)
        (!$initstate && ($past(count) <= max_count)) |-> (count <= max_count)
    );

endmodule

module counter_sva (
    input logic clk,
    input logic rst,
    input logic en,
    input logic up,
    input logic [3:0] count
);

    // While reset is high, count stays at zero.
    check_reset_holds_zero: assert property (
        @(posedge clk) rst |-> (count == 4'b0000)
    );

    // A reset assertion clears count by the next sampled edge.
    check_reset_clears_count: assert property (
        @(posedge clk or posedge rst) rst |=> (count == 4'b0000)
    );

    // When enable is low, count holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk or posedge rst) disable iff (rst)
        (!en) |=> (count == $past(count))
    );

    // When enabled and counting up, count increments by one.
    check_increment_when_enabled_up: assert property (
        @(posedge clk or posedge rst) disable iff (rst)
        (en && up) |=> (count == ($past(count) + 4'h1))
    );

    // When enabled and counting down, count decrements by one.
    check_decrement_when_enabled_down: assert property (
        @(posedge clk or posedge rst) disable iff (rst)
        (en && !up) |=> (count == ($past(count) - 4'h1))
    );

    // Counting up wraps from 15 to 0.
    check_wrap_up_from_max: assert property (
        @(posedge clk or posedge rst) disable iff (rst)
        (en && up && count == 4'hF) |=> (count == 4'h0)
    );

    // Counting down wraps from 0 to 15.
    check_wrap_down_from_zero: assert property (
        @(posedge clk or posedge rst) disable iff (rst)
        (en && !up && count == 4'h0) |=> (count == 4'hF)
    );

endmodule

