module rotator (
    input clk,
    input load,
    input [1:0] ena,
    input [99:0] data,
    output [99:0] q
);

reg [99:0] shift_reg;
reg [99:0] shifted_out;
reg [1:0] rotate_mode;

always @(posedge clk) begin
    if (load) begin
        shift_reg <= data;
    end else if (ena[0] == 1) begin
        // Rotate right by one bit
        shift_reg <= {shift_reg[0], shift_reg[99:1]};
    end else if (ena[1] == 1) begin
        // Rotate left by one bit
        shift_reg <= {shift_reg[98:0], shift_reg[99]};
    end else if (ena == 2'b11) begin
        // Rotate right by two bits
        shift_reg <= {shift_reg[0], shift_reg[99:2]};
    end
end

assign q = shift_reg;

endmodule
module top_module(
    input clk,
    input load,
    input [1:0] ena,
    input [99:0] data,
    output [99:0] q
);

rotator rotator_inst (
    .clk(clk),
    .load(load),
    .ena(ena),
    .data(data),
    .q(q)
);

endmodule

sva:
module rotator_sva (
    input logic         clk,
    input logic         load,
    input logic [1:0]   ena,
    input logic [99:0]  data,
    input logic [99:0]  q
);

    // load captures data into q on the next clock.
    check_load_captures_data: assert property (
        @(posedge clk) load |=> (q == $past(data))
    );

    // when load is low and ena[0] is set, q rotates right by one.
    check_rotate_right_one_on_ena0: assert property (
        @(posedge clk) (!load && ena[0]) |=> (q == { $past(q[0]), $past(q[99:1]) })
    );

    // when load is low and only ena[1] is set, q rotates left by one.
    check_rotate_left_one_on_ena1_only: assert property (
        @(posedge clk) (!load && !ena[0] && ena[1]) |=> (q == { $past(q[98:0]), $past(q[99]) })
    );

    // when load is low and ena is zero, q holds its value.
    check_hold_when_ena_zero: assert property (
        @(posedge clk) (!load && (ena == 2'b00)) |=> (q == $past(q))
    );

    // when both enable bits are set, the first ena[0] branch still wins.
    check_both_enable_bits_rotate_right_one: assert property (
        @(posedge clk) (!load && (ena == 2'b11)) |=> (q == { $past(q[0]), $past(q[99:1]) })
    );

endmodule

rtl:
module complement (
    input D,
    output reg Q,
    input CLK
);

    reg reg1 = 0;
    reg reg2 = 1;

    always @(posedge CLK) begin
        reg1 <= D;
    end

    always @(posedge CLK) begin
        reg2 <= reg1;
    end

    always @(posedge CLK) begin
        Q <= reg1;
        reg2 <= ~reg2;
    end

endmodule

sva:
module complement_sva (
    input logic D,
    input logic Q,
    input logic CLK,
    input logic reg1
);

    // reg1 captures a low D value on the next clock.
    check_reg1_captures_d_low: assert property (
        @(posedge CLK) disable iff (1'b0)
        (D === 1'b0) |=> (reg1 === 1'b0)
    );

    // reg1 captures a high D value on the next clock.
    check_reg1_captures_d_high: assert property (
        @(posedge CLK) disable iff (1'b0)
        (D === 1'b1) |=> (reg1 === 1'b1)
    );

    // Q captures a low reg1 value on the next clock.
    check_q_captures_reg1_low: assert property (
        @(posedge CLK) disable iff (1'b0)
        (reg1 === 1'b0) |=> (Q === 1'b0)
    );

    // Q captures a high reg1 value on the next clock.
    check_q_captures_reg1_high: assert property (
        @(posedge CLK) disable iff (1'b0)
        (reg1 === 1'b1) |=> (Q === 1'b1)
    );

    // Q reflects a low D value after two clocks.
    check_q_two_cycle_delay_low: assert property (
        @(posedge CLK) disable iff (1'b0)
        (D === 1'b0) |-> ##2 (Q === 1'b0)
    );

    // Q reflects a high D value after two clocks.
    check_q_two_cycle_delay_high: assert property (
        @(posedge CLK) disable iff (1'b0)
        (D === 1'b1) |-> ##2 (Q === 1'b1)
    );

endmodule

rtl:
module dff_preset_clear (
    input wire D,
    input wire CLK,
    input wire PRE,  // Preset
    input wire CLR,  // Clear
    output wire Q,
    output wire Q_N
);

    reg [0:0] _Q;
    assign Q = _Q[0];
    assign Q_N = ~_Q[0];

    always @(posedge CLK) begin
        if (CLR) begin // Clear
            _Q[0] <= 0;
        end else if (PRE) begin // Preset
            _Q[0] <= 1;
        end else begin // Normal Operation
            _Q[0] <= D;
        end
    end

endmodule

sva:
module dff_preset_clear_sva (
    input logic D,
    input logic CLK,
    input logic PRE,
    input logic CLR,
    input logic Q,
    input logic Q_N
);

    // Q_N is always the complement of Q.
    check_outputs_complement: assert property (
        @(posedge CLK) Q_N === ~Q
    );

    // Clear forces Q low on the next clock, regardless of PRE.
    check_clear_forces_q_low: assert property (
        @(posedge CLK) CLR |=> (Q == 1'b0)
    );

    // Clear forces Q_N high on the next clock, regardless of PRE.
    check_clear_forces_qn_high: assert property (
        @(posedge CLK) CLR |=> (Q_N == 1'b1)
    );

    // Preset forces Q high when clear is not asserted.
    check_preset_forces_q_high: assert property (
        @(posedge CLK) (!CLR && PRE) |=> (Q == 1'b1)
    );

    // Preset forces Q_N low when clear is not asserted.
    check_preset_forces_qn_low: assert property (
        @(posedge CLK) (!CLR && PRE) |=> (Q_N == 1'b0)
    );

    // Without clear or preset, Q captures D on the next clock.
    check_data_capture_without_controls: assert property (
        @(posedge CLK) (!CLR && !PRE) |=> (Q == $past(D))
    );

    // Without clear or preset, Q_N matches the complement of captured D.
    check_qn_capture_without_controls: assert property (
        @(posedge CLK) (!CLR && !PRE) |=> (Q_N == ~$past(D))
    );

endmodule

rtl:
module mem_soft_ecc
  #(
    parameter C_DATA_WIDTH          = 32,
    parameter C_ADDRB_WIDTH         = 10,
    parameter C_HAS_SOFTECC_OUTPUT_REGS_B= 1,
    parameter C_USE_SOFTECC         = 0,
    parameter FLOP_DELAY            = 100
  )
  (
   input                         CLK,
   input      [C_DATA_WIDTH-1:0] DIN,
   output reg [C_DATA_WIDTH-1:0] DOUT,
   input                         SBITERR_IN,
   input                         DBITERR_IN,
   output reg                    SBITERR,
   output reg                    DBITERR,
   input      [C_ADDRB_WIDTH-1:0] RDADDRECC_IN,
   output reg [C_ADDRB_WIDTH-1:0] RDADDRECC
);

  //******************************
  // Port and Generic Definitions
  //******************************
  // C_DATA_WIDTH                  : Memory write/read width
  // C_ADDRB_WIDTH                 : Width of the ADDRB input port
  // C_HAS_SOFTECC_OUTPUT_REGS_B   : Designates the use of a register at the output 
  //                                 of the RAM primitive
  // C_USE_SOFTECC                 : Determines if the Soft ECC feature is used or
  //                                 not. Only applicable Spartan-6
  // FLOP_DELAY                    : Constant delay for register assignments
  //////////////////////////////////////////////////////////////////////////
  // Port Definitions
  //////////////////////////////////////////////////////////////////////////
  // CLK    : Clock to synchronize all read and write operations
  // DIN    : Data input to the Output stage.
  // DOUT   : Final Data output
  // SBITERR_IN    : SBITERR input signal to the Output stage.
  // SBITERR       : Final SBITERR Output signal.
  // DBITERR_IN    : DBITERR input signal to the Output stage.
  // DBITERR       : Final DBITERR Output signal.
  // RDADDRECC_IN  : RDADDRECC input signal to the Output stage.
  // RDADDRECC     : Final RDADDRECC Output signal.
  //////////////////////////////////////////////////////////////////////////

  reg [C_DATA_WIDTH-1:0] dout_i = 0;
  reg sbiterr_i = 0;
  reg dbiterr_i = 0;
  reg [C_ADDRB_WIDTH-1:0] rdaddrecc_i = 0;

  //***********************************************
  // NO OUTPUT REGISTERS.
  //***********************************************
  generate if (C_HAS_SOFTECC_OUTPUT_REGS_B==0) begin : no_output_stage
    always @* begin
      DOUT = DIN;
      RDADDRECC = RDADDRECC_IN;
      SBITERR = SBITERR_IN;
      DBITERR = DBITERR_IN;
    end
  end
  endgenerate

  //***********************************************
  // WITH OUTPUT REGISTERS.
  //***********************************************
  generate if (C_HAS_SOFTECC_OUTPUT_REGS_B==1) begin : has_output_stage
      always @(posedge CLK) begin
      dout_i <= #FLOP_DELAY DIN;
      rdaddrecc_i <= #FLOP_DELAY RDADDRECC_IN;
      sbiterr_i <= #FLOP_DELAY SBITERR_IN;
      dbiterr_i <= #FLOP_DELAY DBITERR_IN;
      end

      always @* begin
      DOUT = dout_i;
      RDADDRECC = rdaddrecc_i;
      SBITERR = sbiterr_i;
      DBITERR = dbiterr_i;
      end //end always
  end //end in_or_out_stage generate statement
  endgenerate

endmodule

sva:
module mem_soft_ecc_sva
  #(
    parameter C_DATA_WIDTH = 32,
    parameter C_ADDRB_WIDTH = 10,
    parameter C_HAS_SOFTECC_OUTPUT_REGS_B = 1,
    parameter C_USE_SOFTECC = 0,
    parameter FLOP_DELAY = 100
  )
  (
    input logic                     CLK,
    input logic [C_DATA_WIDTH-1:0]  DIN,
    input logic [C_DATA_WIDTH-1:0]  DOUT,
    input logic                     SBITERR_IN,
    input logic                     DBITERR_IN,
    input logic                     SBITERR,
    input logic                     DBITERR,
    input logic [C_ADDRB_WIDTH-1:0] RDADDRECC_IN,
    input logic [C_ADDRB_WIDTH-1:0] RDADDRECC
  );

  generate
    if (C_HAS_SOFTECC_OUTPUT_REGS_B == 0) begin : gen_no_output_stage
      // DOUT directly mirrors DIN when output registers are disabled.
      check_dout_passthrough: assert property (
        @(posedge CLK) DOUT == DIN
      );

      // RDADDRECC directly mirrors RDADDRECC_IN when output registers are disabled.
      check_rdaddrecc_passthrough: assert property (
        @(posedge CLK) RDADDRECC == RDADDRECC_IN
      );

      // SBITERR directly mirrors SBITERR_IN when output registers are disabled.
      check_sbiterr_passthrough: assert property (
        @(posedge CLK) SBITERR == SBITERR_IN
      );

      // DBITERR directly mirrors DBITERR_IN when output registers are disabled.
      check_dbiterr_passthrough: assert property (
        @(posedge CLK) DBITERR == DBITERR_IN
      );
    end
  endgenerate

  generate
    if (C_HAS_SOFTECC_OUTPUT_REGS_B == 1) begin : gen_has_output_stage
      // DOUT reflects the previous-cycle DIN when output registers are enabled.
      check_dout_registered: assert property (
        @(posedge CLK) 1'b1 |=> DOUT == $past(DIN)
      );

      // RDADDRECC reflects the previous-cycle RDADDRECC_IN when output registers are enabled.
      check_rdaddrecc_registered: assert property (
        @(posedge CLK) 1'b1 |=> RDADDRECC == $past(RDADDRECC_IN)
      );

      // SBITERR reflects the previous-cycle SBITERR_IN when output registers are enabled.
      check_sbiterr_registered: assert property (
        @(posedge CLK) 1'b1 |=> SBITERR == $past(SBITERR_IN)
      );

      // DBITERR reflects the previous-cycle DBITERR_IN when output registers are enabled.
      check_dbiterr_registered: assert property (
        @(posedge CLK) 1'b1 |=> DBITERR == $past(DBITERR_IN)
      );
    end
  endgenerate

endmodule

