rtl:
module multiplier #(
  parameter n = 4 // number of bits for A and B
) (
  input [n-1:0] A,
  input [n-1:0] B,
  input mode,
  output reg signed [2*n-1:0] P
);


reg signed [2*n-1:0] A_signed, B_signed;

always @(*) begin
  if (mode) begin
    // Signed multiplication
    A_signed = $signed(A);
    B_signed = $signed(B);
    P = A_signed * B_signed;
  end else begin
    // Unsigned multiplication
    P = A * B;
  end
end

endmodule

sva:
module multiplier_sva #(
  parameter int n = 4
) (
  input logic clk,
  input logic [n-1:0] A,
  input logic [n-1:0] B,
  input logic mode,
  input logic signed [2*n-1:0] P
);

function automatic logic signed [2*n-1:0] sign_extend(input logic [n-1:0] v);
  sign_extend = $signed(v);
endfunction

function automatic logic [2*n-1:0] zero_extend(input logic [n-1:0] v);
  zero_extend = v;
endfunction

function automatic logic signed [2*n-1:0] signed_product(input logic [n-1:0] a, input logic [n-1:0] b);
  signed_product = $signed(a) * $signed(b);
endfunction

function automatic logic [2*n-1:0] unsigned_product(input logic [n-1:0] a, input logic [n-1:0] b);
  unsigned_product = a * b;
endfunction

// In signed mode, P must equal the signed product of A and B.
check_signed_mode_product: assert property (
  @(posedge clk) (mode == 1'b1) |-> (P == signed_product(A, B))
);

// In unsigned mode, P must equal the unsigned product of A and B.
check_unsigned_mode_product: assert property (
  @(posedge clk) (mode == 1'b0) |-> (P == unsigned_product(A, B))
);

// With unchanged inputs and mode, the sampled output must remain unchanged.
check_stable_inputs_hold_output: assert property (
  @(posedge clk) $stable(A) && $stable(B) && $stable(mode) |-> $stable(P)
);

// A rising mode selects the signed multiplication result.
check_mode_switch_to_signed: assert property (
  @(posedge clk) $rose(mode) && $stable(A) && $stable(B) |-> (P == signed_product(A, B))
);

// A falling mode selects the unsigned multiplication result.
check_mode_switch_to_unsigned: assert property (
  @(posedge clk) $fell(mode) && $stable(A) && $stable(B) |-> (P == unsigned_product(A, B))
);

// In signed mode, any zero operand must force a zero product.
check_signed_zero_operand: assert property (
  @(posedge clk) (mode == 1'b1) && ((A == '0) || (B == '0)) |-> (P == '0)
);

// In unsigned mode, any zero operand must force a zero product.
check_unsigned_zero_operand: assert property (
  @(posedge clk) (mode == 1'b0) && ((A == '0) || (B == '0)) |-> (P == '0)
);

// In signed mode, non-negative inputs must match the unsigned product.
check_signed_non_negative_matches_unsigned: assert property (
  @(posedge clk) (mode == 1'b1) && (A[n-1] == 1'b0) && (B[n-1] == 1'b0) |-> (P == unsigned_product(A, B))
);

// In signed mode, multiplying by -1 on A must negate the sign-extended B.
check_signed_a_is_minus_one: assert property (
  @(posedge clk) (mode == 1'b1) && (A == {n{1'b1}}) |-> (P == -sign_extend(B))
);

// In unsigned mode, multiplying by 1 on A must pass through B with zero extension.
check_unsigned_a_is_one: assert property (
  @(posedge clk) (mode == 1'b0) && (A == {{(n-1){1'b0}}, 1'b1}) |-> (P == zero_extend(B))
);

endmodule

rtl:
module top_module (
    input [3:0] A,
    input [3:0] B,
    input CIN,
    output [3:0] SUM,
    output COUT,
    output LT
);

    wire [3:0] adder_sum;
    wire adder_cout;
    wire lt;

    ripple_carry_adder adder(.A(A), .B(B), .CIN(CIN), .SUM(adder_sum), .COUT(adder_cout));
    magnitude_comparator comparator(.A(A), .B(B), .LT(lt));

    assign SUM = adder_sum;
    assign COUT = adder_cout;
    assign LT = lt;

endmodule
module ripple_carry_adder (
    input [3:0] A,
    input [3:0] B,
    input CIN,
    output [3:0] SUM,
    output COUT
);

    wire [3:0] fa1_sum;
    wire fa1_cout;
    wire [3:0] fa2_sum;
    wire fa2_cout;
    wire [3:0] fa3_sum;
    wire fa3_cout;
    wire [3:0] fa4_sum;

    full_adder fa1(.A(A[0]), .B(B[0]), .CIN(CIN), .SUM(fa1_sum[0]), .COUT(fa1_cout));
    full_adder fa2(.A(A[1]), .B(B[1]), .CIN(fa1_cout), .SUM(fa2_sum[1]), .COUT(fa2_cout));
    full_adder fa3(.A(A[2]), .B(B[2]), .CIN(fa2_cout), .SUM(fa3_sum[2]), .COUT(fa3_cout));
    full_adder fa4(.A(A[3]), .B(B[3]), .CIN(fa3_cout), .SUM(fa4_sum[3]), .COUT(COUT));

    assign SUM = {fa4_sum[3], fa3_sum[2], fa2_sum[1], fa1_sum[0]};

endmodule
module full_adder (
    input A,
    input B,
    input CIN,
    output SUM,
    output COUT
);

    assign SUM = A ^ B ^ CIN;
    assign COUT = (A & B) | (A & CIN) | (B & CIN);

endmodule
module magnitude_comparator (
    input [3:0] A,
    input [3:0] B,
    output LT
);

    assign LT = (A < B);

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic CIN,
    input logic [3:0] SUM,
    input logic COUT,
    input logic LT
);

    function automatic logic carry_bit(input logic a, input logic b, input logic cin);
        carry_bit = (a & b) | (a & cin) | (b & cin);
    endfunction

    // Sum and carry match A + B + CIN.
    check_add_result: assert property (
        @(posedge clk)
        {COUT, SUM} == ({1'b0, A} + {1'b0, B} + CIN)
    );

    // LT matches the unsigned less-than comparison.
    check_lt_equivalence: assert property (
        @(posedge clk)
        LT == (A < B)
    );

    // Bit 0 sum matches the first full-adder stage.
    check_sum_bit0: assert property (
        @(posedge clk)
        SUM[0] == (A[0] ^ B[0] ^ CIN)
    );

    // Bit 1 sum uses the carry from bit 0.
    check_sum_bit1: assert property (
        @(posedge clk)
        SUM[1] == (A[1] ^ B[1] ^ carry_bit(A[0], B[0], CIN))
    );

    // Bit 2 sum uses the carry from bit 1.
    check_sum_bit2: assert property (
        @(posedge clk)
        SUM[2] == (A[2] ^ B[2] ^ carry_bit(A[1], B[1], carry_bit(A[0], B[0], CIN)))
    );

    // Bit 3 sum uses the carry from bit 2.
    check_sum_bit3: assert property (
        @(posedge clk)
        SUM[3] == (A[3] ^ B[3] ^ carry_bit(A[2], B[2], carry_bit(A[1], B[1], carry_bit(A[0], B[0], CIN))))
    );

    // COUT matches the final full-adder carry.
    check_cout_final_stage: assert property (
        @(posedge clk)
        COUT == carry_bit(A[3], B[3], carry_bit(A[2], B[2], carry_bit(A[1], B[1], carry_bit(A[0], B[0], CIN))))
    );

    // Equal operands must not assert LT.
    check_lt_equal_case: assert property (
        @(posedge clk)
        (A == B) |-> (LT == 1'b0)
    );

    // Smaller A must assert LT.
    check_lt_less_case: assert property (
        @(posedge clk)
        (A < B) |-> (LT == 1'b1)
    );

    // Adding zero with no carry leaves A unchanged.
    check_add_identity_a: assert property (
        @(posedge clk)
        (B == 4'b0000 && CIN == 1'b0) |-> ({COUT, SUM} == {1'b0, A})
    );

    // Adding zero with no carry leaves B unchanged.
    check_add_identity_b: assert property (
        @(posedge clk)
        (A == 4'b0000 && CIN == 1'b0) |-> ({COUT, SUM} == {1'b0, B})
    );

endmodule

