module top_module (
    input  [31:0] a,
    input  [31:0] b,
    input         select, //Select input to choose between adder and multiplexer
    output [31:0] result
);

wire [1:0] sub_out;
wire [0:0] mux_out;
wire [31:0] final_out;

subtractor sub(
    .a(a),
    .b(b),
    .result(sub_out)
);

mux mux_inst(
    .a(a[0]),
    .b(b[0]),
    .c(a[1]),
    .d(b[1]),
    .out(mux_out) //Selecting only the LSBs of a and b
);

final_output final_inst(
    .sub_out(sub_out),
    .select(select),
    .a(a[0]),
    .b(b[0]),
    .c(32'h0),
    .d(32'h0),
    .final_out(final_out)
);

assign result = select ? {31'b0, mux_out} : final_out;

