    // Reset overrides enable when both are asserted.
    check_reset_priority_over_enable: assert property (
        @(posedge clk) (rst && en) |=> (out == 4'b0000)
    );

    // When enabled below max value, the counter increments by one.
    check_increment_when_enabled: assert property (
        @(posedge clk) disable iff (rst) (en && (out != 4'hF)) |=> (out == ($past(out) + 4'd1))
    );

    // When enabled at max value, the counter wraps to zero.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (rst) (en && (out == 4'hF)) |=> (out == 4'h0)
    );

    // When not enabled, the counter holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (rst) (!en) |=> (out == $past(out))
    );

endmodule

rtl:
module karnaugh_map (
  input [3:0] x,
  output f
);
  wire d1, d2, d3, d4;

  assign d1 = x[0] & x[1];
  assign d2 = x[0] & x[2];
  assign d3 = x[1] & x[3];
  assign d4 = x[2] & x[3];

  assign f = d1 | d2 | d3 | d4;
endmodule

sva:
module karnaugh_map_sva (
    input logic clk,
    input logic [3:0] x,
    input logic f
);

    // f must match the implemented sum-of-products equation.
    check_f_matches_sum_of_products: assert property (
        @(posedge clk)
        f == ((x[0] & x[1]) | (x[0] & x[2]) | (x[1] & x[3]) | (x[2] & x[3]))
    );

    // x[0] and x[1] high must drive f high.
    check_f_high_for_x0_x1: assert property (
        @(posedge clk)
        (x[0] & x[1]) |-> f
    );

    // x[0] and x[2] high must drive f high.
    check_f_high_for_x0_x2: assert property (
        @(posedge clk)
        (x[0] & x[2]) |-> f
    );

    // x[1] and x[3] high must drive f high.
    check_f_high_for_x1_x3: assert property (
        @(posedge clk)
        (x[1] & x[3]) |-> f
    );

    // x[2] and x[3] high must drive f high.
    check_f_high_for_x2_x3: assert property (
        @(posedge clk)
        (x[2] & x[3]) |-> f
    );

    // If all implemented product terms are low, f must be low.
    check_f_low_without_product_terms: assert property (
        @(posedge clk)
        !((x[0] & x[1]) | (x[0] & x[2]) | (x[1] & x[3]) | (x[2] & x[3])) |-> !f
    );

endmodule

rtl:
module concat_8bit (
  input clk,
  input reset,
  input [7:0] a,
  input [7:0] b,
  input ctrl,
  output [15:0] out
);

reg [15:0] temp;

always @ (posedge clk or posedge reset) begin
  if (reset) begin
    temp <= 16'b0;
  end else begin
    if (ctrl) begin
      temp <= {a, b};
    end else begin
      temp <= {b, a};
    end
  end
end

assign out = temp;

endmodule

sva:
module concat_8bit_sva (
    input logic        clk,
    input logic        reset,
    input logic [7:0]  a,
    input logic [7:0]  b,
    input logic        ctrl,
    input logic [15:0] out
);

    // A sampled reset must leave the registered output cleared on the next clock.
    check_reset_clears_output: assert property (
        @(posedge clk) reset |=> (out == 16'b0)
    );

    // The first clock after reset deassertion still sees the cleared register value.
    check_reset_release_keeps_zero_until_update: assert property (
        @(posedge clk) $fell(reset) |-> (out == 16'b0)
    );

    // When ctrl is high, the next registered output is {a, b}.
    check_ctrl_high_concatenates_a_then_b: assert property (
        @(posedge clk) disable iff (reset)
        ctrl |=> (out == {$past(a), $past(b)})
    );

    // When ctrl is low, the next registered output is {b, a}.
    check_ctrl_low_concatenates_b_then_a: assert property (
        @(posedge clk) disable iff (reset)
        !ctrl |=> (out == {$past(b), $past(a)})
    );

endmodule

rtl:
module xor_system (
  input a,
  input b,
  output out
);

  wire not_a, not_b, not_a_b;

  not_gate not1(a, not_a);
  not_gate not2(b, not_b);
  not_gate not3(not_a_b, not_a_b);

  xor_gate xor1(a, not_b, not_a_b);
  xor_gate xor2(not_a, b, out);

endmodule

module not_gate (
  input in,
  output out
);

  assign out = ~in;

endmodule

module xor_gate (
  input a,
  input b,
  output out
);

  assign out = a ^ b;

endmodule

sva:
module xor_system_sva (
    input logic a,
    input logic b,
    input logic out
);

    // Out matches the implemented not/xor datapath.
    check_out_matches_implemented_datapath: assert property (
        @($global_clock) out == ((~a) ^ b)
    );

    // Equal inputs drive the output high.
    check_equal_inputs_drive_high: assert property (
        @($global_clock) (a == b) |-> (out == 1'b1)
    );

    // Different inputs drive the output low.
    check_different_inputs_drive_low: assert property (
        @($global_clock) (a != b) |-> (out == 1'b0)
    );

    // With a low, the output is the inversion of b.
    check_a_low_inverts_b: assert property (
        @($global_clock) (!a) |-> (out == (~b))
    );

    // With a high, the output follows b.
    check_a_high_follows_b: assert property (
        @($global_clock) a |-> (out == b)
    );

    // With b low, the output is the inversion of a.
    check_b_low_inverts_a: assert property (
        @($global_clock) (!b) |-> (out == (~a))
    );

    // With b high, the output follows a.
    check_b_high_follows_a: assert property (
        @($global_clock) b |-> (out == a)
    );

    // Both inputs low produce a high output.
    check_00_maps_to_1: assert property (
        @($global_clock) ((!a) && (!b)) |-> (out == 1'b1)
    );

    // Only a high produces a low output.
    check_10_maps_to_0: assert property (
        @($global_clock) (a && (!b)) |-> (out == 1'b0)
    );

    // Only b high produces a low output.
    check_01_maps_to_0: assert property (
        @($global_clock) ((!a) && b) |-> (out == 1'b0)
    );

    // Both inputs high produce a high output.
    check_11_maps_to_1: assert property (
        @($global_clock) (a && b) |-> (out == 1'b1)
    );

endmodule

rtl:
module mux4_1 (
  input [3:0] D0,
  input [3:0] D1,
  input [3:0] D2,
  input [3:0] D3,
  input S0,
  input S1,
  output [3:0] Y
);

  wire [3:0] w1, w2, w3;

  assign w1 = S0 ? D3 : D2;
  assign w2 = S0 ? D1 : D0;
  assign w3 = S1 ? w1 : w2;

  assign Y = w3;

endmodule

sva:
module mux4_1_sva (
    input logic clk,
    input logic [3:0] D0,
    input logic [3:0] D1,
    input logic [3:0] D2,
    input logic [3:0] D3,
    input logic S0,
    input logic S1,
    input logic [3:0] Y
);

    // Y always matches the implemented 4-to-1 mux expression.
    check_mux_function: assert property (
        @(posedge clk) Y === (S1 ? (S0 ? D3 : D2) : (S0 ? D1 : D0))
    );

    // Y routes D0 when the select value is 2'b00.
    check_select_00_routes_d0: assert property (
        @(posedge clk) ({S1, S0} === 2'b00) |-> (Y === D0)
    );

    // Y routes D1 when the select value is 2'b01.
    check_select_01_routes_d1: assert property (
        @(posedge clk) ({S1, S0} === 2'b01) |-> (Y === D1)
    );

    // Y routes D2 when the select value is 2'b10.
    check_select_10_routes_d2: assert property (
        @(posedge clk) ({S1, S0} === 2'b10) |-> (Y === D2)
    );

    // Y routes D3 when the select value is 2'b11.
    check_select_11_routes_d3: assert property (
        @(posedge clk) ({S1, S0} === 2'b11) |-> (Y === D3)
    );

endmodule

rtl:
module my_ff (
    input  D    ,
    output Q    ,
    input  SET_B,
    input  CLK
);

    supply1 VPWR;
    supply0 VGND;

    reg Q_reg;

    always @(posedge CLK) begin
        if (SET_B == 1'b1) begin
            Q_reg <= 1'b0;
        end else begin
            Q_reg <= D;
        end
    end

    assign Q = Q_reg;

endmodule

sva:
module my_ff_sva (
    input logic D,
    input logic Q,
    input logic SET_B,
    input logic CLK
);

    // High SET_B forces Q low on the following sampled cycle.
    check_set_b_forces_zero: assert property (
        @(posedge CLK) disable iff (1'b0)
        ($past(SET_B) === 1'b1) |-> (Q === 1'b0)
    );

    // With SET_B low, a sampled 1 on D is captured into Q.
    check_capture_one_when_set_b_low: assert property (
        @(posedge CLK) disable iff (1'b0)
        (($past(SET_B) === 1'b0) && ($past(D) === 1'b1)) |-> (Q === 1'b1)
    );

    // With SET_B low, a sampled 0 on D is captured into Q.
    check_capture_zero_when_set_b_low: assert property (
        @(posedge CLK) disable iff (1'b0)
        (($past(SET_B) === 1'b0) && ($past(D) === 1'b0)) |-> (Q === 1'b0)
    );

endmodule

rtl:
module sky130_fd_sc_ls__fahcon (
    COUT_N,
    SUM   ,
    A     ,
    B     ,
    CI
);

    output COUT_N;
    output SUM   ;
    input  A     ;
    input  B     ;
    input  CI    ;

    wire xor0_out_SUM ;
    wire a_b          ;
    wire a_ci         ;
    wire b_ci         ;
    wire or0_out_coutn;

    xor xor0 (xor0_out_SUM , A, B, CI       );
    buf buf0 (SUM          , xor0_out_SUM   );
    nor nor0 (a_b          , A, B           );
    nor nor1 (a_ci         , A, CI          );
    nor nor2 (b_ci         , B, CI          );
    or  or0  (or0_out_coutn, a_b, a_ci, b_ci);
    buf buf1 (COUT_N       , or0_out_coutn  );

endmodule

sva:
module sky130_fd_sc_ls__fahcon_sva (
    input logic clk,
    input logic COUT_N,
    input logic SUM,
    input logic A,
    input logic B,
    input logic CI
);

    // SUM must be the XOR of the three inputs.
    check_sum_xor_function: assert property (
        @(posedge clk) SUM == (A ^ B ^ CI)
    );

    // COUT_N must match the implemented NOR/OR carry network.
    check_coutn_gate_function: assert property (
        @(posedge clk) COUT_N == ((~(A | B)) | (~(A | CI)) | (~(B | CI)))
    );

    // The outputs must encode the 2-bit result of A+B+CI.
    check_full_adder_result: assert property (
        @(posedge clk) ({1'b0, A} + {1'b0, B} + {1'b0, CI}) == {~COUT_N, SUM}
    );

    // 000 must produce SUM=0 and COUT_N=1.
    check_all_zero_case: assert property (
        @(posedge clk) (!A && !B && !CI) |-> ((SUM == 1'b0) && (COUT_N == 1'b1))
    );

    // 001 must produce SUM=1 and COUT_N=1.
    check_ci_only_case: assert property (
        @(posedge clk) (!A && !B && CI) |-> ((SUM == 1'b1) && (COUT_N == 1'b1))
    );

    // 010 must produce SUM=1 and COUT_N=1.
    check_b_only_case: assert property (
        @(posedge clk) (!A && B && !CI) |-> ((SUM == 1'b1) && (COUT_N == 1'b1))
    );

    // 011 must produce SUM=0 and COUT_N=0.
    check_b_ci_case: assert property (
        @(posedge clk) (!A && B && CI) |-> ((SUM == 1'b0) && (COUT_N == 1'b0))
    );

    // 100 must produce SUM=1 and COUT_N=1.
    check_a_only_case: assert property (
        @(posedge clk) (A && !B && !CI) |-> ((SUM == 1'b1) && (COUT_N == 1'b1))
    );

    // 101 must produce SUM=0 and COUT_N=0.
    check_a_ci_case: assert property (
        @(posedge clk) (A && !B && CI) |-> ((SUM == 1'b0) && (COUT_N == 1'b0))
    );

    // 110 must produce SUM=0 and COUT_N=0.
    check_a_b_case: assert property (
        @(posedge clk) (A && B && !CI) |-> ((SUM == 1'b0) && (COUT_N == 1'b0))
    );

    // 111 must produce SUM=1 and COUT_N=0.
    check_all_one_case: assert property (
        @(posedge clk) (A && B && CI) |-> ((SUM == 1'b1) && (COUT_N == 1'b0))
    );

endmodule

rtl:
module barrel_shifter (
    input [3:0] A,
    input [3:0] B,
    input [1:0] S,
    output reg [3:0] Y
);

always @(*) begin
    case(S)
        2'b00: Y = A;
        2'b01: Y = {A[2:0], A[3]};
        2'b10: Y = {A[0], A[3:1]};
        2'b11: Y = {A[1:0], A[3:2]};
    endcase
end

endmodule

sva:
module barrel_shifter_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [1:0] S,
    input logic [3:0] Y
);

    // Y must always match the selected rotation of A.
    check_output_matches_select: assert property (
        @(posedge clk)
        Y == ((S == 2'b00) ? A :
              (S == 2'b01) ? {A[2:0], A[3]} :
              (S == 2'b10) ? {A[0], A[3:1]} :
                             {A[1:0], A[3:2]})
    );

    // S=00 passes A through unchanged.
    check_sel_00_passthrough: assert property (
        @(posedge clk)
        (S == 2'b00) |-> (Y == A)
    );

    // S=01 rotates A left by one bit.
    check_sel_01_rotate_left_1: assert property (
        @(posedge clk)
        (S == 2'b01) |-> (Y == {A[2:0], A[3]})
    );

    // S=10 rotates A right by one bit.
    check_sel_10_rotate_right_1: assert property (
        @(posedge clk)
        (S == 2'b10) |-> (Y == {A[0], A[3:1]})
    );

    // S=11 rotates A by two bits.
    check_sel_11_rotate_2: assert property (
        @(posedge clk)
        (S == 2'b11) |-> (Y == {A[1:0], A[3:2]})
    );

endmodule

rtl:
module phase_detector (
  input clk, 
  input ref,
  input in,
  output reg error
);

reg ref_reg, in_reg;

always @(posedge clk) begin
  ref_reg <= ref;
  in_reg <= in;
end

always @(posedge clk) begin
  error <= ref_reg ^ in_reg; 
end

endmodule

sva:
module phase_detector_assertions (
    input logic clk,
    input logic \ref ,
    input logic in,
    input logic error
);

property p_error_matches_sampled_xor;
    logic ref_sampled, in_sampled;
    @(posedge clk)
        (1'b1, ref_sampled = \ref , in_sampled = in)
        |-> ##2 (error == (ref_sampled ^ in_sampled));
endproperty

// Error equals the XOR of ref and in sampled two clocks earlier.
check_error_matches_sampled_xor: assert property (p_error_matches_sampled_xor);

// Equal sampled inputs drive error low two clocks later.
check_equal_inputs_drive_zero: assert property (
    @(posedge clk) (\ref  == in) |-> ##2 (error == 1'b0)
);

// Different sampled inputs drive error high two clocks later.
check_different_inputs_drive_one: assert property (
    @(posedge clk) (\ref  != in) |-> ##2 (error == 1'b1)
);

// Stable inputs produce a stable error two clocks later.
check_stable_inputs_hold_error: assert property (
    @(posedge clk) ($stable(\ref ) && $stable(in)) |-> ##2 $stable(error)
);

// A toggle on exactly one input causes error to toggle two clocks later.
check_single_input_toggle_toggles_error: assert property (
    @(posedge clk)
        (($changed(\ref ) && $stable(in)) || ($stable(\ref ) && $changed(in)))
        |-> ##2 $changed(error)
);

// Simultaneous toggles on both inputs keep the XOR result unchanged two clocks later.
check_both_inputs_toggle_hold_error: assert property (
    @(posedge clk) ($changed(\ref ) && $changed(in)) |-> ##2 $stable(error)
);

endmodule

rtl:
module zero_to_one_counter (
    input clk,
    input reset, // Synchronous active-high reset
    input [15:0] in, // 16-bit input
    output reg out // Output
);

    always @(posedge clk) begin
        if (reset) begin
            out <= 1'b0;
        end else if (in == 16'hFFFF) begin
            out <= 1'b1;
        end else begin
            out <= out + 1'b1;
        end
    end

endmodule

module adder_4bit_cin_cout (
    input [3:0] A, // 4-bit input A
    input [3:0] B, // 4-bit input B
    input CIN, // Carry-in
    output [3:0] S, // 4-bit output sum
    output COUT // Carry-out
);

    assign {COUT, S} = A + B + CIN;

endmodule

module top_module (
    input clk,
    input reset, // Synchronous active-high reset
    input [3:0] A, // 4-bit input for the adder
    input [3:0] B, // 4-bit input for the adder
    input CIN, // Carry-in for the adder
    input [15:0] in, // 16-bit input for the zero-to-one counter
    output [3:0] S // 4-bit output for the final sum
);

    wire [3:0] adder_out;
    wire zero_to_one_out;

    adder_4bit_cin_cout adder_inst (
        .A(A),
        .B(B),
        .CIN(CIN),
        .S(adder_out),
        .COUT()
    );

    zero_to_one_counter zero_to_one_inst (
        .clk(clk),
        .reset(reset),
        .in(in),
        .out(zero_to_one_out)
    );

    assign S = adder_out + zero_to_one_out;

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic reset,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic CIN,
    input logic [15:0] in,
    input logic [3:0] S,
    input logic [3:0] adder_out,
    input logic zero_to_one_out
);

    // Internal adder output matches A + B + CIN.
    check_adder_out_matches_inputs: assert property (
        @(posedge clk) disable iff (reset)
        adder_out == (A + B + CIN)
    );

    // Top output is the adder result plus the counter bit.
    check_s_matches_adder_plus_counter: assert property (
        @(posedge clk) disable iff (reset)
        S == (adder_out + zero_to_one_out)
    );

    // Reset clears the counter bit on the next cycle.
    check_counter_resets_low: assert property (
        @(posedge clk)
        reset |=> (zero_to_one_out == 1'b0)
    );

    // An all-ones input sets the counter bit on the next cycle.
    check_counter_sets_on_all_ones: assert property (
        @(posedge clk) disable iff (reset)
        (in == 16'hFFFF) |=> (zero_to_one_out == 1'b1)
    );

    // A non-FFFF input toggles the counter bit from 0 to 1.
    check_counter_toggle_low_to_high: assert property (
        @(posedge clk) disable iff (reset)
        ((in != 16'hFFFF) && (zero_to_one_out == 1'b0)) |=> (zero_to_one_out == 1'b1)
    );

    // A non-FFFF input toggles the counter bit from 1 to 0.
    check_counter_toggle_high_to_low: assert property (
        @(posedge clk) disable iff (reset)
        ((in != 16'hFFFF) && (zero_to_one_out == 1'b1)) |=> (zero_to_one_out == 1'b0)
    );

    // After reset, the output reduces to the plain adder result.
    check_output_after_reset_is_plain_sum: assert property (
        @(posedge clk)
        reset |=> (S == (A + B + CIN))
    );

    // After an all-ones input, the output includes the extra one.
    check_output_after_all_ones_has_extra_one: assert property (
        @(posedge clk) disable iff (reset)
        (in == 16'hFFFF) |=> (S == (A + B + CIN + 1'b1))
    );

    // With a non-FFFF input and counter bit low, the next output adds one.
    check_output_toggle_low_to_high: assert property (
        @(posedge clk) disable iff (reset)
        ((in != 16'hFFFF) && (zero_to_one_out == 1'b0)) |=> (S == (A + B + CIN + 1'b1))
    );

    // With a non-FFFF input and counter bit high, the next output drops the extra one.
    check_output_toggle_high_to_low: assert property (
        @(posedge clk) disable iff (reset)
        ((in != 16'hFFFF) && (zero_to_one_out == 1'b1)) |=> (S == (A + B + CIN))
    );

endmodule

module binary_adder_sva (
    input logic [7:0] A,
    input logic [7:0] B,
    input logic       C,
    input logic [7:0] S
);

    // When C is low, S must be the sum of A and B.
    check_add_mode: assert property (
        @($global_clock) !C |-> (S == (A + B))
    );

    // When C is high, S must be the difference of A and B.
    check_sub_mode: assert property (
        @($global_clock) C |-> (S == (A - B))
    );

    // S must always match the operation selected by C.
    check_selected_operation: assert property (
        @($global_clock) S == (C ? (A - B) : (A + B))
    );

    // If the inputs stay the same, the output must stay the same.
    check_stable_inputs_hold_output: assert property (
        @($global_clock) $stable({A, B, C}) |-> $stable(S)
    );

endmodule

rtl:
module sum_2_msb(in_4, out_2);
  input [3:0] in_4;
  output [1:0] out_2;

  wire msb_1 = in_4[3];
  wire msb_2 = in_4[2];

  wire sum = msb_1 | msb_2;

  assign out_2 = {sum, sum};
endmodule

sva:
module sum_2_msb_sva (
    input logic       clk,
    input logic [3:0] in_4,
    input logic [1:0] out_2
);

    // Output bit 1 is the OR of the two input MSBs.
    check_out2_bit1_is_msb_or: assert property (
        @(posedge clk) out_2[1] == (in_4[3] | in_4[2])
    );

    // Output bit 0 is the OR of the two input MSBs.
    check_out2_bit0_is_msb_or: assert property (
        @(posedge clk) out_2[0] == (in_4[3] | in_4[2])
    );

    // Both output bits always match because the OR result is replicated.
    check_out2_bits_match: assert property (
        @(posedge clk) out_2[1] == out_2[0]
    );

    // When both input MSBs are low, the output is 2'b00.
    check_zero_when_both_msbs_low: assert property (
        @(posedge clk) (in_4[3:2] == 2'b00) |-> (out_2 == 2'b00)
    );

    // When either input MSB is high, the output is 2'b11.
    check_ones_when_any_msb_high: assert property (
