    // An invalid counter digit recovers to zero.
    check_invalid_digit_recovers_to_zero: assert property (
        @(posedge clk) disable iff (reset) (q[3:0] == 4'h0) && (q[7:4] > 4'd9) |=> (q == 8'h00)
