    check_function_exact: assert property (
        @($global_clock)
        X == ((~(A2_N & A1_N)) & (B2 | B1))
    );

    // Both A inputs high force the NAND leg low, so X must be low.
    check_a_inputs_both_high_force_low: assert property (
