    check_combined_mux_function: assert property (
        @(posedge clk) out_mux == (sel[1] ? (sel[0] ? d : c) : (sel[0] ? b : a))
    );

    // sel=00 routes input a to the output.
    check_sel_00_routes_a: assert property (
        @(posedge clk) (sel == 2'b00) |-> (out_mux == a)
