    );

    // If all OR inputs are low, X must be low.
    check_all_terms_low_implies_x_low: assert property (
        @(posedge clk) (!C1 && !(A1 & A2) && !(B1 & B2)) |-> !X
    );

    // X low means none of the three OR terms are asserted.
    check_x_low_only_when_all_terms_low: assert property (
        @(posedge clk) !X |-> (!C1 && !(A1 & A2) && !(B1 & B2))
    );

endmodule

rtl:
module dff2(d,clk,clrn,q
    );
	 input [1:0] d;
	 input clk,clrn;
	 output [1:0] q;
    reg [1:0] q;
    always @ (posedge clk or negedge clrn) begin
			if (clrn == 0) q <= 0;
			else				q <= d;
	 end	 
endmodule

sva:
module dff2_sva (
    input logic [1:0] d,
    input logic       clk,
    input logic       clrn,
    input logic [1:0] q
);

    // If reset is low at a clock edge, q must be zero.
    check_reset_low_holds_q_zero: assert property (
        @(posedge clk) disable iff ($initstate)
        !clrn |-> (q == 2'b00)
    );

    // If reset is observed to fall between clocks, q is zero at the next clock.
    check_sampled_reset_fall_clears_q: assert property (
        @(posedge clk) disable iff ($initstate)
        $fell(clrn) |-> (q == 2'b00)
    );

    // On the first clock after reset release, q is still zero before recapturing d.
    check_reset_release_starts_from_zero: assert property (
        @(posedge clk) disable iff ($initstate)
        $rose(clrn) |-> (q == 2'b00)
    );

    // Outside reset, q is either the prior-cycle d or zero from an async clear.
    check_q_is_prev_d_or_zero: assert property (
        @(posedge clk) disable iff (!clrn || $initstate)
        1'b1 |-> ((q == $past(d)) || (q == 2'b00))
    );

    // A nonzero q must match the prior-cycle d.
    check_nonzero_q_matches_prev_d: assert property (
        @(posedge clk) disable iff (!clrn || $initstate)
        (q != 2'b00) |-> (q == $past(d))
    );

    // If the prior-cycle d was zero, q must be zero.
    check_prev_zero_d_leads_to_zero_q: assert property (
        @(posedge clk) disable iff (!clrn || $initstate)
        ($past(d) == 2'b00) |-> (q == 2'b00)
    );

    // A nonzero q cannot immediately follow a sampled reset-low cycle.
    check_nonzero_q_requires_prev_reset_high: assert property (
        @(posedge clk) disable iff (!clrn || $initstate)
        (q != 2'b00) |-> $past(clrn)
    );

    // If q changes to a nonzero value, it must come from the prior-cycle d.
    check_q_change_to_nonzero_matches_prev_d: assert property (
        @(posedge clk) disable iff (!clrn || $initstate)
        ($changed(q) && (q != 2'b00)) |-> (q == $past(d))
    );

endmodule

rtl:
module mux_8to1 (
    input [3:0] in0,
    input [3:0] in1,
    input [3:0] in2,
    input [3:0] in3,
    input [3:0] in4,
    input [3:0] in5,
    input [3:0] in6,
    input [3:0] in7,
    input [2:0] sel,
    output reg [3:0] out
);

    always @(*) begin
        case (sel)
            3'b000: out = in0;
            3'b001: out = in1;
            3'b010: out = in2;
            3'b011: out = in3;
            3'b100: out = in4;
            3'b101: out = in5;
            3'b110: out = in6;
            3'b111: out = in7;
        endcase
    end

endmodule

sva:
module mux_8to1_sva (
    input logic        clk,
    input logic [3:0]  in0,
    input logic [3:0]  in1,
    input logic [3:0]  in2,
    input logic [3:0]  in3,
    input logic [3:0]  in4,
    input logic [3:0]  in5,
    input logic [3:0]  in6,
    input logic [3:0]  in7,
    input logic [2:0]  sel,
    input logic [3:0]  out
);

    // Sampled on clk; RTL has no reset and implements a combinational 8-to-1 mux.

    // sel=000 selects in0 onto out.
    check_sel_000_selects_in0: assert property (
        @(posedge clk) (sel == 3'b000) |-> (out === in0)
    );

    // sel=001 selects in1 onto out.
    check_sel_001_selects_in1: assert property (
        @(posedge clk) (sel == 3'b001) |-> (out === in1)
    );

    // sel=010 selects in2 onto out.
    check_sel_010_selects_in2: assert property (
        @(posedge clk) (sel == 3'b010) |-> (out === in2)
    );

    // sel=011 selects in3 onto out.
    check_sel_011_selects_in3: assert property (
        @(posedge clk) (sel == 3'b011) |-> (out === in3)
    );

    // sel=100 selects in4 onto out.
    check_sel_100_selects_in4: assert property (
        @(posedge clk) (sel == 3'b100) |-> (out === in4)
    );

    // sel=101 selects in5 onto out.
    check_sel_101_selects_in5: assert property (
        @(posedge clk) (sel == 3'b101) |-> (out === in5)
    );

    // sel=110 selects in6 onto out.
    check_sel_110_selects_in6: assert property (
        @(posedge clk) (sel == 3'b110) |-> (out === in6)
    );

    // sel=111 selects in7 onto out.
    check_sel_111_selects_in7: assert property (
        @(posedge clk) (sel == 3'b111) |-> (out === in7)
    );

    // out must always match the input selected by sel.
    check_out_matches_selected_input: assert property (
        @(posedge clk)
            ((sel == 3'b000) && (out === in0)) ||
            ((sel == 3'b001) && (out === in1)) ||
            ((sel == 3'b010) && (out === in2)) ||
            ((sel == 3'b011) && (out === in3)) ||
            ((sel == 3'b100) && (out === in4)) ||
            ((sel == 3'b101) && (out === in5)) ||
            ((sel == 3'b110) && (out === in6)) ||
            ((sel == 3'b111) && (out === in7))
    );

    // If sel and the selected input stay stable, out stays stable.
    check_out_stable_when_selected_path_stable: assert property (
        @(posedge clk)
            (
                (($past(sel) == 3'b000) && (sel == 3'b000) && $stable(in0)) ||
                (($past(sel) == 3'b001) && (sel == 3'b001) && $stable(in1)) ||
                (($past(sel) == 3'b010) && (sel == 3'b010) && $stable(in2)) ||
                (($past(sel) == 3'b011) && (sel == 3'b011) && $stable(in3)) ||
                (($past(sel) == 3'b100) && (sel == 3'b100) && $stable(in4)) ||
                (($past(sel) == 3'b101) && (sel == 3'b101) && $stable(in5)) ||
                (($past(sel) == 3'b110) && (sel == 3'b110) && $stable(in6)) ||
                (($past(sel) == 3'b111) && (sel == 3'b111) && $stable(in7))
            ) |-> $stable(out)
    );

endmodule

rtl:
module gatedcap (
   inout ld,
   input clk,
   input rst,
   output reg vcap
);

   reg [31:0] count;
   reg [31:0] discharge_count;
   reg [31:0] charge_count;
   reg charging;
   reg discharging;

   assign ld = charging | discharging;

   always @(posedge clk) begin
      if (rst) begin
         vcap <= 0;
         count <= 0;
         discharge_count <= 0;
         charge_count <= 0;
         charging <= 0;
         discharging <= 0;
      end else begin
         if (charging) begin
            if (count == 31'd499999) begin
               count <= 0;
               charging <= 0;
               discharging <= 1;
            end else begin
               count <= count + 1;
            end
         end else if (discharging) begin
            if (vcap == 0) begin
               vcap <= 0;
               count <= 0;
               discharge_count <= 0;
               charge_count <= 0;
               charging <= 0;
               discharging <= 0;
            end else if (discharge_count == 31'd49999) begin
               discharge_count <= 0;
               vcap <= vcap - 1;
            end else begin
               discharge_count <= discharge_count + 1;
            end
         end else if (ld) begin
            vcap <= 0;
            count <= 0;
            discharge_count <= 0;
            charge_count <= 0;
            charging <= 1;
            discharging <= 0;
         end
      end
   end

endmodule

module and_gate(
    input A,
    input B,
    output X
);

    wire A1, A2, B1, C1, VPWR, VGND, VPB, VNB;
    assign A1 = A;
    assign B1 = B;
    assign A2 = 1'b1;
    assign C1 = 1'b0;
    assign VPWR = 1'b1;
    assign VGND = 1'b0;
    assign VPB = 1'b1;
    assign VNB = 1'b0;

    and gate_inst (
        X,
        A1,
        B1
    );

endmodule

sva:
module and_gate_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic X
);

    // Output must always equal the AND of the two inputs.
    check_output_matches_and: assert property (
        @(posedge clk) X == (A & B)
    );

    // If both inputs are high, the output must be high.
    check_both_inputs_high_drive_output_high: assert property (
        @(posedge clk) (A && B) |-> X
    );

    // If A is low, the output must be low.
    check_a_low_forces_output_low: assert property (
        @(posedge clk) !A |-> !X
    );

    // If B is low, the output must be low.
    check_b_low_forces_output_low: assert property (
        @(posedge clk) !B |-> !X
    );

    // A high output requires both inputs to be high.
    check_output_high_requires_both_inputs_high: assert property (
        @(posedge clk) X |-> (A && B)
    );

endmodule

rtl:
module dff_sscan (din, clk, q, se, si, so);

parameter SIZE = 1;

input	[SIZE-1:0]	din ;	// data in
input			clk ;	// clk or scan clk

output	[SIZE-1:0]	q ;	// output

input			se ;	// scan-enable
input	[SIZE-1:0]	si ;	// scan-input
output	[SIZE-1:0]	so ;	// scan-output

reg 	[SIZE-1:0]	q ;

`ifdef CONNECT_SHADOW_SCAN

always @ (posedge clk)

	q[SIZE-1:0]  <= (se) ? si[SIZE-1:0]  : din[SIZE-1:0] ;

assign so[SIZE-1:0] = q[SIZE-1:0] ;

`else
always @ (posedge clk)
  q[SIZE-1:0]  <= din[SIZE-1:0] ;

assign so={SIZE{1'b0}};
`endif

endmodule

sva:
module dff_sscan_sva #(
    parameter SIZE = 1
) (
    input  logic [SIZE-1:0] din,
    input  logic            clk,
    input  logic [SIZE-1:0] q,
    input  logic            se,
    input  logic [SIZE-1:0] si,
    input  logic [SIZE-1:0] so
);

`ifdef CONNECT_SHADOW_SCAN
    // q captures si when scan is enabled.
    check_q_captures_scan_input: assert property (
        @(posedge clk) se |=> (q == $past(si))
    );

    // q captures din when scan is disabled.
    check_q_captures_functional_input: assert property (
        @(posedge clk) !se |=> (q == $past(din))
    );

    // so mirrors q when shadow scan is connected.
    check_so_mirrors_q: assert property (
        @(posedge clk) (so == q)
    );
`else
    // q captures din on every rising clock edge.
    check_q_captures_din: assert property (
        @(posedge clk) 1'b1 |=> (q == $past(din))
    );

    // Scan enable does not change the captured source when scan is disconnected.
    check_q_ignores_scan_enable: assert property (
        @(posedge clk) se |=> (q == $past(din))
    );

    // so is tied low when shadow scan is not connected.
    check_so_tied_low: assert property (
        @(posedge clk) (so == {SIZE{1'b0}})
    );
`endif

endmodule

rtl:
module full_adder (
    input A,
    input B,
    input Cin,
    output S,
    output Cout
);

    assign S = A ^ B ^ Cin;
    assign Cout = (A & B) | (Cin & (A ^ B));

endmodule


module four_bit_adder (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] S,
    output Cout
);

    wire [3:0] S_int;
    wire C0, C1, C2;

    full_adder fa0 (
        .A(A[0]),
        .B(B[0]),
        .Cin(Cin),
        .S(S_int[0]),
        .Cout(C0)
    );

    full_adder fa1 (
        .A(A[1]),
        .B(B[1]),
        .Cin(C0),
        .S(S_int[1]),
        .Cout(C1)
    );

    full_adder fa2 (
        .A(A[2]),
        .B(B[2]),
        .Cin(C1),
        .S(S_int[2]),
        .Cout(C2)
    );

    full_adder fa3 (
        .A(A[3]),
        .B(B[3]),
        .Cin(C2),
        .S(S_int[3]),
        .Cout(Cout)
    );

    assign S = S_int;

endmodule

sva:
module four_bit_adder_sva (
    input logic        clk,
    input logic [3:0]  A,
    input logic [3:0]  B,
    input logic        Cin,
    input logic [3:0]  S,
    input logic        Cout
);

    function automatic logic fa_carry (
        input logic a,
        input logic b,
        input logic cin
    );
        fa_carry = (a & b) | (cin & (a ^ b));
    endfunction

    // The 5-bit result must equal A + B + Cin.
    check_total_sum_matches_addition: assert property (
        @(posedge clk) {Cout, S} == ({1'b0, A} + {1'b0, B} + Cin)
    );

    // Bit 0 sum must match the first full-adder XOR equation.
    check_bit0_sum_equation: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0] ^ Cin)
    );

    // Bit 1 sum must use the carry from bit 0.
    check_bit1_sum_equation: assert property (
        @(posedge clk) S[1] == (A[1] ^ B[1] ^ fa_carry(A[0], B[0], Cin))
    );

    // Bit 2 sum must use the carry propagated through bits 0 and 1.
    check_bit2_sum_equation: assert property (
        @(posedge clk) S[2] == (A[2] ^ B[2] ^ fa_carry(A[1], B[1], fa_carry(A[0], B[0], Cin)))
    );

    // Bit 3 sum must use the carry propagated through bits 0 to 2.
    check_bit3_sum_equation: assert property (
        @(posedge clk) S[3] == (A[3] ^ B[3] ^ fa_carry(A[2], B[2], fa_carry(A[1], B[1], fa_carry(A[0], B[0], Cin))))
    );

    // Carry out must match the final full-adder carry equation.
    check_cout_equation: assert property (
        @(posedge clk) Cout == fa_carry(A[3], B[3], fa_carry(A[2], B[2], fa_carry(A[1], B[1], fa_carry(A[0], B[0], Cin))))
    );

endmodule

rtl:
module adder_4bit (
  input [3:0] A,
  input [3:0] B,
  input CIN,
  input CLK,
  input RST,
  output [3:0] SUM,
  output COUT
);

  reg [3:0] SUM_reg;
  reg COUT_reg;

  always @(posedge CLK, negedge RST) begin
    if (~RST) begin
      SUM_reg <= 4'b0;
      COUT_reg <= 1'b0;
    end else begin
      SUM_reg <= A + B + CIN;
      COUT_reg <= (A[3] & B[3]) | (A[3] & CIN) | (B[3] & CIN);
    end
  end

  assign SUM = SUM_reg;
  assign COUT = COUT_reg;

endmodule

sva:
module adder_4bit_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic       CIN,
    input logic       CLK,
    input logic       RST,
    input logic [3:0] SUM,
    input logic       COUT
);

    // During active-low reset, the registered outputs are cleared.
    check_reset_clears_outputs: assert property (
        @(posedge CLK) (!RST) |-> (SUM == 4'b0000 && COUT == 1'b0)
    );

    // On the first clock after reset release, outputs are still the reset values.
    check_first_cycle_after_reset_release_is_zero: assert property (
        @(posedge CLK) disable iff (!RST) $rose(RST) |-> (SUM == 4'b0000 && COUT == 1'b0)
    );

    // SUM reflects the prior cycle's truncated A+B+CIN result.
    check_sum_matches_previous_inputs: assert property (
        @(posedge CLK) disable iff (!RST)
        $past(RST) |-> (SUM == $past(A + B + CIN))
    );

    // COUT reflects the prior cycle's registered MSB majority function.
    check_cout_matches_previous_inputs: assert property (
        @(posedge CLK) disable iff (!RST)
        $past(RST) |-> (COUT == $past((A[3] & B[3]) | (A[3] & CIN) | (B[3] & CIN)))
    );

    // A full-scale add wraps SUM and drives COUT high on the following cycle.
    check_full_scale_add_behavior: assert property (
        @(posedge CLK) disable iff (!RST)
        $past(RST) && ($past(A) == 4'hF) && ($past(B) == 4'hF) && $past(CIN)
        |-> (SUM == 4'hF && COUT == 1'b1)
    );

endmodule

rtl:
module FSM #(
  parameter n = 4, // number of input signals
  parameter m = 2 // number of output signals
)(
  input [n-1:0] in,
  output [m-1:0] out,
  input clk
);

parameter s = 8; // number of states

reg [2:0] state, next_state; // registers to hold current and next states

// define states and their associated output signals
localparam S0 = 3'b000;
localparam S1 = 3'b001;
localparam S2 = 3'b010;
localparam S3 = 3'b011;
localparam S4 = 3'b100;
localparam S5 = 3'b101;
localparam S6 = 3'b110;
localparam S7 = 3'b111;

// define output signals for each state
assign out[0] = (state == S0 || state == S1 || state == S2 || state == S3) ? 1'b1 : 1'b0;
assign out[1] = (state == S4 || state == S5 || state == S6 || state == S7) ? 1'b1 : 1'b0;

// define transitions between states based on input signals
always @(*) begin
  case(state)
    S0: next_state = (in[0] == 1'b1) ? S1 : S0;
    S1: next_state = (in[1] == 1'b1) ? S3 : S2;
    S2: next_state = (in[2] == 1'b1) ? S3 : S1;
    S3: next_state = (in[3] == 1'b1) ? S4 : S0;
    S4: next_state = (in[0] == 1'b1) ? S5 : S4;
    S5: next_state = (in[1] == 1'b1) ? S7 : S6;
    S6: next_state = (in[2] == 1'b1) ? S7 : S5;
    S7: next_state = (in[3] == 1'b1) ? S0 : S4;
  endcase
end

// update current state register with next state
always @(posedge clk) begin
  state <= next_state;
end

endmodule

sva:
module FSM_assertions #(
    parameter n = 4,
    parameter m = 2
)(
    input logic [n-1:0] in,
    input logic [m-1:0] out,
    input logic clk,
    input logic [2:0] state,
    input logic [2:0] next_state
);

    localparam logic [2:0] S0 = 3'b000;
    localparam logic [2:0] S1 = 3'b001;
    localparam logic [2:0] S2 = 3'b010;
    localparam logic [2:0] S3 = 3'b011;
    localparam logic [2:0] S4 = 3'b100;
    localparam logic [2:0] S5 = 3'b101;
    localparam logic [2:0] S6 = 3'b110;
    localparam logic [2:0] S7 = 3'b111;

    // out[0] is high only in states S0 through S3.
    check_out0_logic: assert property (
        @(posedge clk)
        out[0] == ((state == S0) || (state == S1) || (state == S2) || (state == S3))
    );

    // out[1] is high only in states S4 through S7.
    check_out1_logic: assert property (
        @(posedge clk)
        out[1] == ((state == S4) || (state == S5) || (state == S6) || (state == S7))
    );

    // In S0, next_state depends only on in[0].
    check_next_state_s0: assert property (
        @(posedge clk)
        (state == S0) |-> (next_state == (in[0] ? S1 : S0))
    );

    // In S1, next_state depends only on in[1].
    check_next_state_s1: assert property (
        @(posedge clk)
        (state == S1) |-> (next_state == (in[1] ? S3 : S2))
    );

    // In S2, next_state depends only on in[2].
    check_next_state_s2: assert property (
        @(posedge clk)
        (state == S2) |-> (next_state == (in[2] ? S3 : S1))
    );

    // In S3, next_state depends only on in[3].
    check_next_state_s3: assert property (
        @(posedge clk)
        (state == S3) |-> (next_state == (in[3] ? S4 : S0))
    );

    // In S4, next_state depends only on in[0].
    check_next_state_s4: assert property (
        @(posedge clk)
        (state == S4) |-> (next_state == (in[0] ? S5 : S4))
    );

    // In S5, next_state depends only on in[1].
    check_next_state_s5: assert property (
        @(posedge clk)
        (state == S5) |-> (next_state == (in[1] ? S7 : S6))
    );

    // In S6, next_state depends only on in[2].
    check_next_state_s6: assert property (
        @(posedge clk)
        (state == S6) |-> (next_state == (in[2] ? S7 : S5))
    );

    // In S7, next_state depends only on in[3].
    check_next_state_s7: assert property (
        @(posedge clk)
        (state == S7) |-> (next_state == (in[3] ? S0 : S4))
    );

    // The state register loads the previous cycle's next_state.
    check_state_register_update: assert property (
        @(posedge clk)
        1'b1 |=> (state == $past(next_state))
    );

endmodule

rtl:
module data_converter (
    input [3:0] data_in,
    output [1:0] data_out
);

    assign data_out = (data_in <= 4) ? 2'b00 : 
                     (data_in <= 8) ? 2'b01 : 
                     (data_in <= 12) ? 2'b10 : 2'b11;

endmodule

sva:
module data_converter_sva (
    input logic       clk,
    input logic [3:0] data_in,
    input logic [1:0] data_out
);

    // Output must match the RTL threshold expression.
    check_output_equation: assert property (
        @(posedge clk)
        data_out == (
            (data_in <= 4'd4)  ? 2'b00 :
            (data_in <= 4'd8)  ? 2'b01 :
            (data_in <= 4'd12) ? 2'b10 : 2'b11
        )
    );

    // Inputs 0 through 4 must map to 2'b00.
    check_range_0_to_4: assert property (
        @(posedge clk)
        (data_in <= 4'd4) |-> (data_out == 2'b00)
    );

    // Inputs 5 through 8 must map to 2'b01.
    check_range_5_to_8: assert property (
        @(posedge clk)
        ((data_in >= 4'd5) && (data_in <= 4'd8)) |-> (data_out == 2'b01)
    );

    // Inputs 9 through 12 must map to 2'b10.
    check_range_9_to_12: assert property (
        @(posedge clk)
        ((data_in >= 4'd9) && (data_in <= 4'd12)) |-> (data_out == 2'b10)
    );

    // Inputs 13 through 15 must map to 2'b11.
