    pipeline_reg_4,
    pipeline_reg_5,
    pipeline_reg_6,
    pipeline_reg_7,
    pipeline_reg_8,
    pipeline_reg_9,
    reset
);
    parameter WIDTH = 1;
    //Input value registers
    input clk;
    input clk_ena;
    input [WIDTH-1:0] in_stream;
    output [WIDTH-1:0] pipeline_reg_0;
    output [WIDTH-1:0] pipeline_reg_1;
    output [WIDTH-1:0] pipeline_reg_2;
    output [WIDTH-1:0] pipeline_reg_3;
    output [WIDTH-1:0] pipeline_reg_4;
    output [WIDTH-1:0] pipeline_reg_5;
    output [WIDTH-1:0] pipeline_reg_6;
    output [WIDTH-1:0] pipeline_reg_7;
    output [WIDTH-1:0] pipeline_reg_8;
    output [WIDTH-1:0] pipeline_reg_9;
    reg [WIDTH-1:0] pipeline_reg_0;
    reg [WIDTH-1:0] pipeline_reg_1;
    reg [WIDTH-1:0] pipeline_reg_2;
    reg [WIDTH-1:0] pipeline_reg_3;
    reg [WIDTH-1:0] pipeline_reg_4;
    reg [WIDTH-1:0] pipeline_reg_5;
    reg [WIDTH-1:0] pipeline_reg_6;
    reg [WIDTH-1:0] pipeline_reg_7;
    reg [WIDTH-1:0] pipeline_reg_8;
    reg [WIDTH-1:0] pipeline_reg_9;
    input reset;

    always@(posedge clk or posedge reset) begin
        if(reset) begin
            pipeline_reg_0 <= 0;
            pipeline_reg_1 <= 0;
            pipeline_reg_2 <= 0;
            pipeline_reg_3 <= 0;
            pipeline_reg_4 <= 0;
            pipeline_reg_5 <= 0;
            pipeline_reg_6 <= 0;
            pipeline_reg_7 <= 0;
            pipeline_reg_8 <= 0;
            pipeline_reg_9 <= 0;
        end else begin
            if(clk_ena) begin
                pipeline_reg_0 <= in_stream;
                pipeline_reg_1 <= pipeline_reg_0;
                pipeline_reg_2 <= pipeline_reg_1;
                pipeline_reg_3 <= pipeline_reg_2;
                pipeline_reg_4 <= pipeline_reg_3;
                pipeline_reg_5 <= pipeline_reg_4;
                pipeline_reg_6 <= pipeline_reg_5;
                pipeline_reg_7 <= pipeline_reg_6;
                pipeline_reg_8 <= pipeline_reg_7;
                pipeline_reg_9 <= pipeline_reg_8;
            end
        end
    end
endmodule

sva:
module input_pipeline_sva #(
    parameter WIDTH = 1
) (
    input logic clk,
    input logic clk_ena,
    input logic [WIDTH-1:0] in_stream,
    input logic [WIDTH-1:0] pipeline_reg_0,
    input logic [WIDTH-1:0] pipeline_reg_1,
    input logic [WIDTH-1:0] pipeline_reg_2,
    input logic [WIDTH-1:0] pipeline_reg_3,
    input logic [WIDTH-1:0] pipeline_reg_4,
    input logic [WIDTH-1:0] pipeline_reg_5,
    input logic [WIDTH-1:0] pipeline_reg_6,
    input logic [WIDTH-1:0] pipeline_reg_7,
    input logic [WIDTH-1:0] pipeline_reg_8,
    input logic [WIDTH-1:0] pipeline_reg_9,
    input logic reset
);

    // Reset forces all pipeline registers to zero.
    check_reset_clears_pipeline: assert property (
        @(posedge clk)
        reset |-> ((pipeline_reg_0 == '0) &&
                   (pipeline_reg_1 == '0) &&
                   (pipeline_reg_2 == '0) &&
                   (pipeline_reg_3 == '0) &&
                   (pipeline_reg_4 == '0) &&
                   (pipeline_reg_5 == '0) &&
                   (pipeline_reg_6 == '0) &&
                   (pipeline_reg_7 == '0) &&
                   (pipeline_reg_8 == '0) &&
                   (pipeline_reg_9 == '0))
    );

    // Enabled clock loads stage 0 from the input stream.
    check_stage0_captures_input: assert property (
        @(posedge clk) disable iff (reset)
        clk_ena |=> (pipeline_reg_0 == $past(in_stream))
    );

    // Enabled clock shifts stage 0 into stage 1.
    check_stage1_shifts_stage0: assert property (
        @(posedge clk) disable iff (reset)
        clk_ena |=> (pipeline_reg_1 == $past(pipeline_reg_0))
    );

    // Enabled clock shifts stage 1 into stage 2.
    check_stage2_shifts_stage1: assert property (
        @(posedge clk) disable iff (reset)
        clk_ena |=> (pipeline_reg_2 == $past(pipeline_reg_1))
    );

    // Enabled clock shifts stage 2 into stage 3.
    check_stage3_shifts_stage2: assert property (
        @(posedge clk) disable iff (reset)
        clk_ena |=> (pipeline_reg_3 == $past(pipeline_reg_2))
    );

    // Enabled clock shifts stage 3 into stage 4.
    check_stage4_shifts_stage3: assert property (
        @(posedge clk) disable iff (reset)
        clk_ena |=> (pipeline_reg_4 == $past(pipeline_reg_3))
    );

    // Enabled clock shifts stage 4 into stage 5.
    check_stage5_shifts_stage4: assert property (
        @(posedge clk) disable iff (reset)
        clk_ena |=> (pipeline_reg_5 == $past(pipeline_reg_4))
    );

    // Enabled clock shifts stage 5 into stage 6.
    check_stage6_shifts_stage5: assert property (
        @(posedge clk) disable iff (reset)
        clk_ena |=> (pipeline_reg_6 == $past(pipeline_reg_5))
    );

    // Enabled clock shifts stage 6 into stage 7.
    check_stage7_shifts_stage6: assert property (
        @(posedge clk) disable iff (reset)
        clk_ena |=> (pipeline_reg_7 == $past(pipeline_reg_6))
    );

    // Enabled clock shifts stage 7 into stage 8.
    check_stage8_shifts_stage7: assert property (
        @(posedge clk) disable iff (reset)
        clk_ena |=> (pipeline_reg_8 == $past(pipeline_reg_7))
    );

    // Enabled clock shifts stage 8 into stage 9.
    check_stage9_shifts_stage8: assert property (
        @(posedge clk) disable iff (reset)
        clk_ena |=> (pipeline_reg_9 == $past(pipeline_reg_8))
    );

    // Disabled clock enable holds all pipeline registers.
    check_hold_when_clk_ena_low: assert property (
        @(posedge clk) disable iff (reset)
        !clk_ena |=> ((pipeline_reg_0 == $past(pipeline_reg_0)) &&
                      (pipeline_reg_1 == $past(pipeline_reg_1)) &&
                      (pipeline_reg_2 == $past(pipeline_reg_2)) &&
                      (pipeline_reg_3 == $past(pipeline_reg_3)) &&
                      (pipeline_reg_4 == $past(pipeline_reg_4)) &&
                      (pipeline_reg_5 == $past(pipeline_reg_5)) &&
                      (pipeline_reg_6 == $past(pipeline_reg_6)) &&
                      (pipeline_reg_7 == $past(pipeline_reg_7)) &&
                      (pipeline_reg_8 == $past(pipeline_reg_8)) &&
                      (pipeline_reg_9 == $past(pipeline_reg_9)))
    );

endmodule

module d_ff_with_set_clear_sva (
    input logic clk,
    input logic d,
    input logic set,
    input logic clear,
    input logic q
);

    // q must match the prior cycle's clear/set/data priority.
    check_state_update_function: assert property (
        @(posedge clk)
        !$initstate |-> (q == ($past(clear) ? 1'b0 : ($past(set) ? 1'b1 : $past(d))))
    );

    // clear forces q low on the following sampled cycle.
    check_clear_forces_zero: assert property (
        @(posedge clk)
        clear |=> (q == 1'b0)
    );

    // clear overrides set when both are asserted.
    check_clear_priority_over_set: assert property (
        @(posedge clk)
        (clear && set) |=> (q == 1'b0)
    );

    // set drives q high when clear is low.
    check_set_forces_one_when_clear_low: assert property (
        @(posedge clk)
        (!clear && set) |=> (q == 1'b1)
    );

    // d is captured when both control inputs are low.
    check_data_capture_when_controls_low: assert property (
        @(posedge clk)
        (!clear && !set) |=> (q == $past(d))
    );

endmodule

rtl:
module binary_adder (
  input [3:0] A,
  input [3:0] B,
  input Cin,
  input clk,
  input rst_n,
  output [3:0] S,
  output Cout
);

  reg [3:0] S;
  reg Cout;

  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      S <= 4'b0;
      Cout <= 1'b0;
    end else begin
      {Cout, S} <= A + B + Cin;
    end
  end

endmodule

sva:
module binary_adder_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic Cin,
    input logic clk,
    input logic rst_n,
    input logic [3:0] S,
    input logic Cout
);

    // During active-low reset, the registered outputs are cleared.
    check_reset_clears_outputs: assert property (
        @(posedge clk) (!rst_n) |-> ({Cout, S} == 5'b0)
    );

    // A sampled reset cycle leaves the outputs cleared at the next sampled clock.
    check_reset_keeps_outputs_cleared_next_cycle: assert property (
        @(posedge clk) (!rst_n) |=> ({Cout, S} == 5'b0)
    );

    // On active cycles, the next sampled output is either the registered sum or the reset value.
    check_next_output_is_sum_or_reset_value: assert property (
        @(posedge clk) disable iff (!rst_n)
        1'b1 |=> (({Cout, S} == 5'b0) ||
                  ({Cout, S} == $past({1'b0, A} + {1'b0, B} + Cin)))
    );

    // With B and Cin low, the next sampled output is either A or the reset value.
    check_b_zero_cin_zero_passthrough_or_reset: assert property (
        @(posedge clk) disable iff (!rst_n)
        (B == 4'b0 && Cin == 1'b0) |=> (({Cout, S} == 5'b0) ||
                                        ({Cout, S} == {1'b0, $past(A)}))
    );

    // With A and Cin low, the next sampled output is either B or the reset value.
    check_a_zero_cin_zero_passthrough_or_reset: assert property (
        @(posedge clk) disable iff (!rst_n)
        (A == 4'b0 && Cin == 1'b0) |=> (({Cout, S} == 5'b0) ||
                                        ({Cout, S} == {1'b0, $past(B)}))
    );

    // Zero inputs must produce a zero registered output.
    check_zero_inputs_produce_zero_output: assert property (
        @(posedge clk) disable iff (!rst_n)
        (A == 4'b0 && B == 4'b0 && Cin == 1'b0) |=> ({Cout, S} == 5'b0)
    );

    // Any non-overflowing addition must register a low carry.
    check_no_overflow_keeps_carry_low: assert property (
        @(posedge clk) disable iff (!rst_n)
        (({1'b0, A} + {1'b0, B} + Cin) <= 5'd15) |=> (Cout == 1'b0)
    );

endmodule

