module reg_32bits(d, we, clk, rst, q);
  input [31:0] d;
  input clk, rst, we;
  output [31:0] q;
  reg [31:0] q_reg;

  always @(posedge clk, posedge rst) begin
    if (rst) begin
      q_reg <= 32'b0;
    end else if (we) begin
      q_reg <= d;
    end
  end

  assign q = q_reg;
endmodule

sva:
module reg_32bits_sva (
    input logic [31:0] d,
    input logic        we,
    input logic        clk,
    input logic        rst,
    input logic [31:0] q
);

    // A sampled reset must leave q cleared by the next clock.
    check_reset_clears_q_next_cycle: assert property (
        @(posedge clk) rst |=> (q == 32'b0)
    );

    // A previously sampled reset keeps q at zero on the following clock.
    check_reset_value_persists: assert property (
        @(posedge clk) (!$initstate && $past(rst)) |-> (q == 32'b0)
    );

    // Any sampled change to a nonzero q must come from a prior write.
    check_nonzero_change_requires_write: assert property (
        @(posedge clk) disable iff (rst)
        (!$initstate && (q != 32'b0) && (q != $past(q))) |-> ($past(we) && (q == $past(d)))
    );

    // A sampled nonzero q after a prior write must match the written data.
    check_nonzero_write_data_matches_q: assert property (
        @(posedge clk) disable iff (rst)
        (!$initstate && $past(we) && (q != 32'b0)) |-> (q == $past(d))
    );

    // Without a prior write, a sampled nonzero q must hold its value.
    check_nonzero_holds_without_write: assert property (
        @(posedge clk) disable iff (rst)
        (!$initstate && !$past(we) && ($past(q) != 32'b0) && (q != 32'b0)) |-> (q == $past(q))
    );

    // Without a prior write, a sampled zero q cannot become nonzero.
    check_zero_cannot_become_nonzero_without_write: assert property (
        @(posedge clk) disable iff (rst)
        (!$initstate && !$past(we) && ($past(q) == 32'b0)) |-> (q == 32'b0)
    );

endmodule

rtl:
module adder_subtractor (
    input [3:0] A,
    input [3:0] B,
    input M,
    output [3:0] Y
);

    wire [3:0] B_comp;
    wire [3:0] temp_sum;
    wire [3:0] temp_diff;

    // Complement B if M is 1
    assign B_comp = M ? ~B + 1 : B;

    // Calculate the sum and difference
    assign temp_sum = A + B_comp;
    assign temp_diff = A - B_comp;

    // Select output based on M
    assign Y = M ? temp_diff : temp_sum;

endmodule

sva:
module adder_subtractor_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic M,
    input logic [3:0] Y
);

    // RTL is combinational and has no reset; assertions are sampled on clk.

    // When M is 0, Y follows the sum path A + B.
    check_mode_zero_sum_path: assert property (
        @(posedge clk) !M |-> (Y == (A + B))
    );

    // When M is 1, Y follows the implemented temp_diff expression.
    check_mode_one_direct_path: assert property (
        @(posedge clk) M |-> (Y == (A - ((~B) + 4'b0001)))
    );

    // Across both modes, the implemented logic reduces to A + B modulo 16.
    check_output_matches_effective_addition: assert property (
        @(posedge clk) Y == (A + B)
    );

    // If A and B are unchanged, the sampled output must remain unchanged.
    check_stable_inputs_keep_stable_output: assert property (
        @(posedge clk) $past(1'b1) && $stable(A) && $stable(B) |-> $stable(Y)
    );

    // Toggling only M does not change the sampled output.
    check_mode_toggle_has_no_effect: assert property (
        @(posedge clk) $past(1'b1) && $changed(M) && $stable(A) && $stable(B) |-> $stable(Y)
    );

    // With B equal to zero, the output matches A.
    check_zero_b_passthrough: assert property (
        @(posedge clk) (B == 4'h0) |-> (Y == A)
    );

    // With A equal to zero, the output matches B.
    check_zero_a_passthrough: assert property (
        @(posedge clk) (A == 4'h0) |-> (Y == B)
    );

    // The least-significant output bit matches the addition XOR bit.
    check_lsb_matches_sum: assert property (
        @(posedge clk) Y[0] == (A[0] ^ B[0])
    );

endmodule

