module Mux_3x1_W11 (ctrl, D0, D1, D2, S);
  input [1:0] ctrl;
  input [10:0] D0;
  input [10:0] D1;
  input [10:0] D2;
  output reg [10:0] S;

  // Implement the 3x1 multiplexer using Verilog
  always @* begin
    case(ctrl)
      2'b00: S = D0;
      2'b01: S = D1;
      2'b10: S = D2;
      default: S = 11'b0; // Undefined behavior
    endcase
  end

endmodule

sva:
module Mux_3x1_W11_sva (
    input logic [1:0]  ctrl,
    input logic [10:0] D0,
    input logic [10:0] D1,
    input logic [10:0] D2,
    input logic [10:0] S
);

    // No clock or reset exists in the RTL; assertions use the global clock.

    // When ctrl selects D0, the output must match D0.
    check_select_d0: assert property (
        @($global_clock) (ctrl === 2'b00) |-> (S === D0)
    );

    // When ctrl selects D1, the output must match D1.
    check_select_d1: assert property (
        @($global_clock) (ctrl === 2'b01) |-> (S === D1)
    );

    // When ctrl selects D2, the output must match D2.
    check_select_d2: assert property (
        @($global_clock) (ctrl === 2'b10) |-> (S === D2)
    );

    // Any control value outside 00, 01, or 10 must drive zero.
    check_default_zero: assert property (
        @($global_clock) !((ctrl === 2'b00) || (ctrl === 2'b01) || (ctrl === 2'b10)) |-> (S === 11'b0)
    );

    // The output must always implement the full mux function.
    check_mux_function: assert property (
        @($global_clock)
        S === ((ctrl === 2'b00) ? D0 :
               (ctrl === 2'b01) ? D1 :
               (ctrl === 2'b10) ? D2 : 11'b0)
    );

    // If all inputs are stable across samples, the output must remain stable.
    check_output_stable_when_inputs_stable: assert property (
        @($global_clock) ($stable(ctrl) && $stable(D0) && $stable(D1) && $stable(D2)) |-> $stable(S)
    );

endmodule

rtl:
module carry_lookahead_multiplier (
    input [7:0] a,
    input [7:0] b,
    input clk,
    input reset,
    output reg [15:0] result
);

    wire [7:0] p [7:0];
    wire [7:0] g [7:0];
    wire [7:0] c [8:0];

    assign p[0] = a & b[0];
    assign g[0] = a | b[0];

    genvar i;
    generate
        for (i = 1; i < 8; i = i + 1) begin
            assign p[i] = a & b[i];
            assign g[i] = a | b[i];
            assign c[i] = g[i-1] & c[i-1] | p[i-1];
        end
        assign c[8] = g[7] & c[7] | p[7];
    endgenerate

    always @(posedge clk) begin
        if (reset) begin
            result <= 0;
        end else begin
            result <= {8'b0, a} + ({8'b0, b} << 8);
        end
    end

endmodule

sva:
module carry_lookahead_multiplier_sva (
    input logic [7:0] a,
    input logic [7:0] b,
    input logic clk,
    input logic reset,
    input logic [15:0] result
);

    // A reset cycle clears the registered result by the following clock.
    check_reset_clears_result: assert property (
        @(posedge clk) reset |=> (result == 16'h0000)
    );

    // Outside reset, result follows the registered RTL sum expression.
    check_result_implements_rtl_sum: assert property (
        @(posedge clk) disable iff (reset)
        !reset |=> (result == ({8'b0, $past(a)} + ({8'b0, $past(b)} << 8)))
    );

    // Outside reset, the low byte of result captures a.
    check_result_low_byte_captures_a: assert property (
        @(posedge clk) disable iff (reset)
        !reset |=> (result[7:0] == $past(a))
    );

    // Outside reset, the high byte of result captures b.
    check_result_high_byte_captures_b: assert property (
        @(posedge clk) disable iff (reset)
        !reset |=> (result[15:8] == $past(b))
    );

    // Zero inputs produce a zero result on the following non-reset cycle.
    check_zero_inputs_yield_zero_result: assert property (
        @(posedge clk) disable iff (reset)
        ((a == 8'h00) && (b == 8'h00)) |=> (result == 16'h0000)
    );

    // A zero a input clears the low byte on the following non-reset cycle.
    check_zero_a_clears_low_byte: assert property (
        @(posedge clk) disable iff (reset)
        (a == 8'h00) |=> (result[7:0] == 8'h00)
    );

    // A zero b input clears the high byte on the following non-reset cycle.
    check_zero_b_clears_high_byte: assert property (
        @(posedge clk) disable iff (reset)
        (b == 8'h00) |=> (result[15:8] == 8'h00)
    );

endmodule

module calculator_sva(
    input logic clk,
    input logic rst,
    input logic [1:0] op,
    input logic [3:0] num1,
    input logic [3:0] num2,
    input logic [3:0] result,
    input logic overflow
);

    // Addition selects the low 4 bits of num1 + num2.
    check_add_result: assert property (
        @(posedge clk) disable iff (rst)
        (op == 2'b00) |-> (result == ((num1 + num2) & 4'hF))
    );

    // Subtraction selects the low 4 bits of num1 - num2.
    check_sub_result: assert property (
        @(posedge clk) disable iff (rst)
        (op == 2'b01) |-> (result == ((num1 - num2) & 4'hF))
    );

    // Multiplication selects the low 4 bits of num1 * num2.
    check_mul_result: assert property (
        @(posedge clk) disable iff (rst)
        (op == 2'b10) |-> (result == ((num1 * num2) & 4'hF))
    );

    // Division selects the quotient when the divisor is nonzero.
    check_div_result: assert property (
        @(posedge clk) disable iff (rst)
        (op == 2'b11 && num2 != 4'd0) |-> (result == (num1 / num2))
    );

    // Overflow never asserts in this implementation.
    check_overflow_always_low: assert property (
        @(posedge clk) disable iff (rst)
        (overflow == 1'b0)
    );

    // Stable nonzero-divisor inputs keep the outputs stable.
    check_outputs_stable_for_stable_inputs: assert property (
        @(posedge clk) disable iff (rst)
        ($stable({op, num1, num2}) && !(op == 2'b11 && num2 == 4'd0))
        |-> $stable({result, overflow})
    );

endmodule

module binary_counter_sva #(parameter COUNTER_WIDTH = 8) (
    input logic clk,
    input logic rst,
    input logic [COUNTER_WIDTH-1:0] count
);

    // A sampled reset clears the counter by the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |=> (count == '0)
    );

    // The counter stays zero while reset is held across cycles.
    check_reset_holds_zero: assert property (
        @(posedge clk) (rst && $past(rst)) |-> (count == '0)
    );

    // The first cycle after reset deassertion shows a cleared count.
    check_post_reset_count_zero: assert property (
        @(posedge clk) disable iff (rst) $past(rst) |-> (count == '0)
    );

    // In consecutive non-reset cycles, the counter increments by one.
    check_count_increments: assert property (
        @(posedge clk) disable iff (rst) !$past(rst) |-> (count == $past(count) + 1'b1)
    );

    // A maximum count value wraps back to zero on the next non-reset cycle.
    check_count_wraps_to_zero: assert property (
        @(posedge clk) disable iff (rst)
            (!$past(rst) && ($past(count) == {COUNTER_WIDTH{1'b1}})) |-> (count == '0)
    );

endmodule

module decoder_4_to_16_sva (
