    check_max_plus_one_wraps: assert property (
        @(posedge clk) ((A == 16'hFFFF) && (B == 16'h0001)) |-> (Y == 16'h0000)
    );

    // The least-significant sum bit must match A[0] xor B[0].
    check_lsb_sum_bit: assert property (
