);

    // The output always matches the mux select function.
    check_mux_function: assert property (
        @(posedge clk) S == (ctrl ? D1 : D0)
    );

    // When ctrl is low, the output selects D0.
    check_select_d0: assert property (
        @(posedge clk) !ctrl |-> (S == D0)
    );

    // When ctrl is high, the output selects D1.
    check_select_d1: assert property (
        @(posedge clk) ctrl |-> (S == D1)
    );

    // A rising ctrl causes the output to reflect D1.
    check_ctrl_rise_selects_d1: assert property (
        @(posedge clk) $rose(ctrl) |-> (S == D1)
    );

    // A falling ctrl causes the output to reflect D0.
    check_ctrl_fall_selects_d0: assert property (
        @(posedge clk) $fell(ctrl) |-> (S == D0)
    );

    genvar i;
    generate
        for (i = 0; i < WIDTH; i = i + 1) begin : gen_bit_checks
            // Each output bit matches the selected input bit.
            check_bit_mux_function: assert property (
                @(posedge clk) S[i] == (ctrl ? D1[i] : D0[i])
            );
        end
    endgenerate

endmodule

rtl:
module pipelined_circuit(
    input [3:0] in,
    output out_and,
    output out_or,
    output out_xor
);

wire [3:0] stage1_out;
wire [2:0] stage2_out;

// Stage 1
assign stage1_out[0] = in[0] & in[1];
assign stage1_out[1] = in[2] & in[3];
assign stage1_out[2] = stage1_out[0] | stage1_out[1];
assign stage1_out[3] = stage1_out[0] ^ stage1_out[1];

// Stage 2
assign stage2_out[0] = stage1_out[0] & stage1_out[1];
assign stage2_out[1] = stage1_out[2] | stage1_out[3];
assign stage2_out[2] = stage1_out[2] ^ stage1_out[3];

// Output
assign out_and = stage2_out[0];
assign out_or = stage2_out[1];
assign out_xor = stage2_out[2];

endmodule

module top_module( 
    input [3:0] in,
    output out_and,
    output out_or,
    output out_xor
);

pipelined_circuit pc(
    .in(in),
    .out_and(out_and),
    .out_or(out_or),
    .out_xor(out_xor)
);

endmodule

sva:
module pipelined_circuit_sva(
    input logic [3:0] in,
    input logic out_and,
    input logic out_or,
    input logic out_xor
);

    // out_and is the AND of the two pairwise input AND terms.
    check_out_and_function: assert property (
        @($global_clock)
        out_and == ((in[0] & in[1]) & (in[2] & in[3]))
    );

    // out_or matches the second-stage OR expression.
    check_out_or_stage_function: assert property (
        @($global_clock)
        out_or == (((in[0] & in[1]) | (in[2] & in[3])) | ((in[0] & in[1]) ^ (in[2] & in[3])))
    );

    // out_xor matches the second-stage XOR expression.
    check_out_xor_stage_function: assert property (
        @($global_clock)
        out_xor == (((in[0] & in[1]) | (in[2] & in[3])) ^ ((in[0] & in[1]) ^ (in[2] & in[3])))
    );

    // out_or simplifies to the OR of the two pairwise input AND terms.
    check_out_or_simplified_function: assert property (
        @($global_clock)
        out_or == ((in[0] & in[1]) | (in[2] & in[3]))
    );

    // out_xor is always equal to out_and for this logic.
    check_out_xor_matches_out_and: assert property (
        @($global_clock)
        out_xor == out_and
    );

    // If neither input pair ANDs high, all outputs are low.
    check_no_pair_and_gives_zero_outputs: assert property (
        @($global_clock)
        (!(in[0] & in[1]) && !(in[2] & in[3])) |-> ((out_and == 1'b0) && (out_or == 1'b0) && (out_xor == 1'b0))
    );

    // If exactly one input pair ANDs high, only out_or is high.
    check_one_pair_and_gives_only_or: assert property (
        @($global_clock)
        ((in[0] & in[1]) ^ (in[2] & in[3])) |-> ((out_and == 1'b0) && (out_or == 1'b1) && (out_xor == 1'b0))
    );

    // If both input pairs AND high, all outputs are high.
    check_both_pair_ands_give_all_outputs_high: assert property (
        @($global_clock)
        ((in[0] & in[1]) && (in[2] & in[3])) |-> ((out_and == 1'b1) && (out_or == 1'b1) && (out_xor == 1'b1))
    );

endmodule

