module ripple_carry_adder(
  input [3:0] a,
  input [3:0] b,
  output [3:0] sum,
  output carry_out
);

  wire [3:0] carry;
  full_adder fa0(a[0], b[0], 1'b0, carry[0], sum[0]);
  full_adder fa1(a[1], b[1], carry[0], carry[1], sum[1]);
  full_adder fa2(a[2], b[2], carry[1], carry[2], sum[2]);
  full_adder fa3(a[3], b[3], carry[2], carry_out, sum[3]);

endmodule

module full_adder(
  input a, b, cin,
  output cout, sum
);

  assign {cout, sum} = a + b + cin;

endmodule

sva:
module ripple_carry_adder_assertions (
    input logic clk,
    input logic [3:0] a,
    input logic [3:0] b,
    input logic [3:0] sum,
    input logic carry_out
);

    // Full 5-bit result matches unsigned addition.
    check_full_addition: assert property (
        @(posedge clk) {carry_out, sum} == ({1'b0, a} + {1'b0, b})
    );

    // Bit 0 has no carry-in, so it is the XOR of the input bits.
    check_lsb_sum: assert property (
        @(posedge clk) sum[0] == (a[0] ^ b[0])
    );

    // The low two sum bits match 2-bit addition.
    check_low_two_bits: assert property (
        @(posedge clk) sum[1:0] == (a[1:0] + b[1:0])
    );

    // The low three sum bits match 3-bit addition.
    check_low_three_bits: assert property (
        @(posedge clk) sum[2:0] == (a[2:0] + b[2:0])
    );

    // The carry output matches the overflow bit of the extended sum.
    check_carry_out: assert property (
        @(posedge clk) carry_out == ({1'b0, a} + {1'b0, b})[4]
    );

    // Adding zero on a leaves b unchanged and produces no carry.
    check_a_zero_identity: assert property (
        @(posedge clk) (a == 4'h0) |-> (sum == b && carry_out == 1'b0)
    );

    // Adding zero on b leaves a unchanged and produces no carry.
    check_b_zero_identity: assert property (
        @(posedge clk) (b == 4'h0) |-> (sum == a && carry_out == 1'b0)
    );

    // Adding 4'hF and 4'hF produces 4'hE with carry-out set.
    check_max_plus_max: assert property (
        @(posedge clk) ((a == 4'hF) && (b == 4'hF)) |-> (sum == 4'hE && carry_out == 1'b1)
    );

endmodule

module mux4to1_sva (
    input logic clk,
    input logic in0,
    input logic in1,
    input logic in2,
    input logic in3,
    input logic sel0,
    input logic sel1,
    input logic out,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB
);

    // No RTL clock or reset; this combinational mux is sampled on an external clock.

    // sel1=1 and sel0=1 routes in0 to out.
    check_sel11_selects_in0: assert property (
        @(posedge clk) (sel1 && sel0) |-> (out == in0)
    );

    // sel1=1 and sel0=0 routes in1 to out.
    check_sel10_selects_in1: assert property (
        @(posedge clk) (sel1 && !sel0) |-> (out == in1)
    );

    // sel1=0 and sel0=1 routes in2 to out.
    check_sel01_selects_in2: assert property (
        @(posedge clk) (!sel1 && sel0) |-> (out == in2)
    );

    // sel1=0 and sel0=0 routes in3 to out.
    check_sel00_selects_in3: assert property (
        @(posedge clk) (!sel1 && !sel0) |-> (out == in3)
    );

endmodule

