module counter(
  input clk,
  input reset,
  output [3:0] count
);

reg [3:0] count_reg;

always @(posedge clk) begin
  if (reset) begin
    count_reg <= 4'b0000;
  end else begin
    count_reg <= count_reg + 1;
  end
end

assign count = count_reg;

endmodule


module counter_top(
  input clk,
  input reset,
  output reg [4:0] count
);

wire [3:0] count1, count2;

counter c1(
  .clk(clk),
  .reset(reset),
  .count(count1)
);

counter c2(
  .clk(clk),
  .reset(reset),
  .count(count2)
);

always @(posedge clk) begin
  count <= count1 + count2;
end

endmodule

sva:
module counter_top_sva(
    input logic clk,
    input logic reset,
    input logic [4:0] count,
    input logic [3:0] count1,
    input logic [3:0] count2
);

    // Both subcounters clear on the cycle after reset.
    check_subcounters_clear_after_reset: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        $past(reset) |-> ((count1 == 4'd0) && (count2 == 4'd0))
    );

    // count1 increments by one when it is below 15.
    check_count1_increments_below_max: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        (!$past(reset) && ($past(count1) != 4'hF)) |-> (count1 == ($past(count1) + 4'd1))
    );

    // count1 wraps from 15 back to 0.
    check_count1_wraps_at_max: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        (!$past(reset) && ($past(count1) == 4'hF)) |-> (count1 == 4'h0)
    );

    // count2 increments by one when it is below 15.
    check_count2_increments_below_max: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        (!$past(reset) && ($past(count2) != 4'hF)) |-> (count2 == ($past(count2) + 4'd1))
    );

    // count2 wraps from 15 back to 0.
    check_count2_wraps_at_max: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        (!$past(reset) && ($past(count2) == 4'hF)) |-> (count2 == 4'h0)
    );

    // Top count stores the previous cycle's sum of count1 and count2.
    check_top_captures_previous_sum: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        count == ({1'b0, $past(count1)} + {1'b0, $past(count2)})
    );

    // Equal subcounters remain equal on the next cycle.
    check_equal_subcounters_stay_equal: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        ($past(count1) == $past(count2)) |-> (count1 == count2)
    );

    // Equal subcounters produce a doubled value in the top count.
    check_equal_subcounters_double_into_count: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        ($past(count1) == $past(count2)) |-> (count == {$past(count1), 1'b0})
    );

    // Top count becomes zero two cycles after reset is sampled high.
    check_top_count_zero_two_cycles_after_reset: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        $past(reset, 2) |-> (count == 5'd0)
    );

    // Top count never exceeds the sum range of two 4-bit counters.
    check_top_count_within_sum_range: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        count <= 5'd30
    );

endmodule

module four_input_nand_sva (
    input logic A_N,
    input logic B_N,
    input logic C,
    input logic D,
    input logic Y,
    input logic VPWR,
    input logic VGND
);

    // No RTL clock or reset; the design is purely combinational.
    // The cascaded nand4bb instances reduce to Y = A_N & B_N & C & D.

    // The top-level output matches the reduced Boolean function.
    check_function_equivalence: assert property (
        @($global_clock) Y == (A_N & B_N & C & D)
    );

    // All four inputs high drives the output high.
    check_all_inputs_high_drive_output_high: assert property (
        @($global_clock) (A_N && B_N && C && D) |-> Y
    );

    // Any low input forces the output low.
    check_any_input_low_forces_output_low: assert property (
        @($global_clock) (!A_N || !B_N || !C || !D) |-> !Y
    );

    // A high output requires all four inputs to be high.
    check_output_high_requires_all_inputs_high: assert property (
        @($global_clock) Y |-> (A_N && B_N && C && D)
    );

    // A low output means at least one input is low.
    check_output_low_requires_some_input_low: assert property (
        @($global_clock) !Y |-> (!A_N || !B_N || !C || !D)
    );

endmodule

module DLATCHR_sva (
    input logic D,
    input logic nCLK,
    input logic nRST,
    input logic INIT,
    input logic Q
);

    // nCLK is the clock; nRST is a synchronous active-low reset.

    // Q reflects the input selected on the previous clock edge.
    check_selected_input_function: assert property (
        @(posedge nCLK) disable iff ($initstate)
        1'b1 |=> (Q == $past((!nRST) ? INIT : D))
    );

    // After a non-reset clock edge, the stored value is the previous D.
    check_data_capture: assert property (
        @(posedge nCLK) disable iff ($initstate || !nRST)
        $past(nRST) |-> (Q == $past(D))
    );

    // After a reset clock edge, the reset value is visible once reset releases.
    check_reset_load: assert property (
        @(posedge nCLK) disable iff ($initstate || !nRST)
        $past(!nRST) |-> (Q == $past(INIT))
    );

    // When reset was active and D differed from INIT, Q still comes from INIT.
    check_reset_priority_over_d: assert property (
        @(posedge nCLK) disable iff ($initstate || !nRST)
        $past(!nRST && (D != INIT)) |-> ((Q == $past(INIT)) && (Q != $past(D)))
    );

    // When reset was inactive and D differed from INIT, Q comes from D.
    check_data_path_selected: assert property (
        @(posedge nCLK) disable iff ($initstate || !nRST)
        $past(nRST && (D != INIT)) |-> ((Q == $past(D)) && (Q != $past(INIT)))
    );

endmodule

rtl:
module db_controller(
						clk   		,				
                        rst_n 		,
                        start_i		,

                        done_o  	,
						cnt_r		,
						state		
					); 
input 		         	 clk				;
input                	 rst_n       	    ;
input                	 start_i     	    ;

output  reg 	         done_o				; 					
output  reg 	[8:0]    cnt_r				;
output  reg 	[2:0]    state				;
parameter IDLE   = 3'b000, LOAD  = 3'b001, YVER  = 3'b011,YHOR	=3'b010;
parameter CVER   = 3'b110, CHOR  = 3'b111, OUTLT = 3'b101,OUT   =3'b100;

reg     [2:0]   next		;

reg     [8:0]   cycles		;

reg             isluma      ;
reg             isver       ;

always@* begin
	case(state)
		LOAD :cycles	=  'd384   ;
		YVER :cycles    =  'd132   ;
        YHOR :cycles    =  'd140   ;
		CVER :cycles    =  'd68    ;
        CHOR :cycles    =  'd76    ;
       OUTLT :cycles	=  'd67    ;
	   OUT   :cycles	=  'd384   ;
     default :cycles	=  'd0	   ;
	endcase
end


always @(posedge clk or negedge rst_n)	begin
	if(!(rst_n))
		cnt_r	<=	8'd0;
	else if(!state)
		cnt_r	<=	8'd0;	
	else if(cnt_r	==	cycles)
		cnt_r	<=	8'd0;
	else 
        cnt_r	<=	cnt_r	+	1'b1;
end


always @* begin
	case(state)
		IDLE:begin
			if(start_i)
				next	=	LOAD	;
			else 
				next	=	IDLE	;
        end	
	    LOAD:begin
			if(cnt_r	==	cycles)
				next	=	YVER		;
			else
				next	=	LOAD	;
		end
		YVER:begin
			if(cnt_r	==	cycles)
				next	=	YHOR		;
			else
				next	=	YVER		;
		end
		YHOR:begin
			if(cnt_r	==	cycles)
				next	=	CVER		;
			else
				next	=	YHOR	 	;	
		end
		CVER:begin
			if(cnt_r	==	cycles)
				next	=	CHOR		;
			else
				next	=	CVER	 	;	
		end	
		CHOR:begin
			if(cnt_r	==	cycles)
				next	=	OUTLT		;
			else
				next	=	CHOR	 	;	
		end		
	  OUTLT:begin
			if(cnt_r	==	cycles)
				next	=	OUT			;
			else	
				next	=	OUTLT		;
		end	
       OUT:begin
			if(cnt_r	==	cycles)
				next	=	IDLE		;
			else
				next	=	OUT			;
		end				
	endcase
end

always @(posedge clk or negedge rst_n)begin
	if(!rst_n)
		state   <=    	IDLE   		;
	else    			
        state   <=    	next   		;
end 

wire 	done_w	= (state==OUT)?1'b1:1'b0;

always@(posedge clk or negedge rst_n)begin
	if(!rst_n)
		done_o	<=	1'b0			;
	else if(next==IDLE)
		done_o  <=   done_w			;
	else 
		done_o  <=   1'b0			;
end


always @* begin
	case(state)
		YVER,
		YHOR:isluma	=	1'b1;
	 default:isluma =	1'b0;
	endcase
end

always @* begin
	case(state)
		YVER,
		CVER:isver	=	1'b1;
	 default:isver =	1'b0;
	endcase
end




endmodule

sva:
module db_controller_sva (
    input logic       clk,
    input logic       rst_n,
    input logic       start_i,
    input logic       done_o,
    input logic [8:0] cnt_r,
    input logic [2:0] state
);

    localparam [2:0] IDLE  = 3'b000;
    localparam [2:0] LOAD  = 3'b001;
    localparam [2:0] YHOR  = 3'b010;
    localparam [2:0] YVER  = 3'b011;
    localparam [2:0] OUT   = 3'b100;
    localparam [2:0] OUTLT = 3'b101;
    localparam [2:0] CVER  = 3'b110;
    localparam [2:0] CHOR  = 3'b111;

    localparam [8:0] LOAD_CYCLES  = 9'd384;
    localparam [8:0] YVER_CYCLES  = 9'd132;
    localparam [8:0] YHOR_CYCLES  = 9'd140;
    localparam [8:0] CVER_CYCLES  = 9'd68;
    localparam [8:0] CHOR_CYCLES  = 9'd76;
    localparam [8:0] OUTLT_CYCLES = 9'd67;
    localparam [8:0] OUT_CYCLES   = 9'd384;

    // Formal starts with reset asserted.
    init_starts_in_reset: assume property (
        @(posedge clk) $initstate |-> !rst_n
    );

    // A reset cycle drives all registered outputs to their reset values by the next clock.
    check_reset_values: assert property (
        @(posedge clk) !rst_n |=> (state == IDLE && cnt_r == 9'd0 && done_o == 1'b0)
    );

    // State must remain within the defined FSM encodings.
    check_state_encoding: assert property (
        @(posedge clk) disable iff (!rst_n)
        (state == IDLE) || (state == LOAD) || (state == YVER) || (state == YHOR) ||
        (state == CVER) || (state == CHOR) || (state == OUTLT) || (state == OUT)
    );

    // Counter must stay within the state-specific terminal count.
    check_counter_bounds: assert property (
        @(posedge clk) disable iff (!rst_n)
        ((state != IDLE)  || (cnt_r == 9'd0))         &&
        ((state != LOAD)  || (cnt_r <= LOAD_CYCLES))  &&
        ((state != YVER)  || (cnt_r <= YVER_CYCLES))  &&
        ((state != YHOR)  || (cnt_r <= YHOR_CYCLES))  &&
        ((state != CVER)  || (cnt_r <= CVER_CYCLES))  &&
        ((state != CHOR)  || (cnt_r <= CHOR_CYCLES))  &&
        ((state != OUTLT) || (cnt_r <= OUTLT_CYCLES)) &&
        ((state != OUT)   || (cnt_r <= OUT_CYCLES))
    );

    // done_o is never high in active processing states.
    check_done_low_outside_idle: assert property (
        @(posedge clk) disable iff (!rst_n)
        (state != IDLE) |-> !done_o
    );

    // done_o can only follow completion of the OUT state.
    check_done_follows_out_completion: assert property (
        @(posedge clk) disable iff (!rst_n)
        done_o |-> $past((state == OUT) && (cnt_r == OUT_CYCLES))
    );

    // done_o is a single-cycle pulse.
    check_done_single_cycle: assert property (
        @(posedge clk) disable iff (!rst_n)
        done_o |=> !done_o
    );

    // IDLE holds when start_i is not asserted.
    check_idle_holds_without_start: assert property (
        @(posedge clk) disable iff (!rst_n)
        (state == IDLE && !start_i) |=> (state == IDLE && cnt_r == 9'd0)
    );

    // start_i moves the FSM from IDLE to LOAD.
    check_idle_to_load_on_start: assert property (
        @(posedge clk) disable iff (!rst_n)
        (state == IDLE && start_i) |=> (state == LOAD && cnt_r == 9'd0)
    );

    // LOAD increments the counter until its terminal count.
    check_load_counts_until_terminal: assert property (
        @(posedge clk) disable iff (!rst_n)
        (state == LOAD && cnt_r < LOAD_CYCLES) |=> (state == LOAD && cnt_r == ($past(cnt_r) + 9'd1))
    );

    // LOAD advances to YVER at its terminal count.
    check_load_to_yver_at_terminal: assert property (
        @(posedge clk) disable iff (!rst_n)
        (state == LOAD && cnt_r == LOAD_CYCLES) |=> (state == YVER && cnt_r == 9'd0)
    );

    // YVER increments the counter until its terminal count.
    check_yver_counts_until_terminal: assert property (
        @(posedge clk) disable iff (!rst_n)
        (state == YVER && cnt_r < YVER_CYCLES) |=> (state == YVER && cnt_r == ($past(cnt_r) + 9'd1))
    );

    // YVER advances to YHOR at its terminal count.
    check_yver_to_yhor_at_terminal: assert property (
        @(posedge clk) disable iff (!rst_n)
        (state == YVER && cnt_r == YVER_CYCLES) |=> (state == YHOR && cnt_r == 9'd0)
    );

    // YHOR increments the counter until its terminal count.
    check_yhor_counts_until_terminal: assert property (
        @(posedge clk) disable iff (!rst_n)
        (state == YHOR && cnt_r < YHOR_CYCLES) |=> (state == YHOR && cnt_r == ($past(cnt_r) + 9'd1))
    );

    // YHOR advances to CVER at its terminal count.
    check_yhor_to_cver_at_terminal: assert property (
        @(posedge clk) disable iff (!rst_n)
        (state == YHOR && cnt_r == YHOR_CYCLES) |=> (state == CVER && cnt_r == 9'd0)
    );

    // CVER increments the counter until its terminal count.
    check_cver_counts_until_terminal: assert property (
        @(posedge clk) disable iff (!rst_n)
        (state == CVER && cnt_r < CVER_CYCLES) |=> (state == CVER && cnt_r == ($past(cnt_r) + 9'd1))
    );

    // CVER advances to CHOR at its terminal count.
    check_cver_to_chor_at_terminal: assert property (
        @(posedge clk) disable iff (!rst_n)
        (state == CVER && cnt_r == CVER_CYCLES) |=> (state == CHOR && cnt_r == 9'd0)
    );

    // CHOR increments the counter until its terminal count.
    check_chor_counts_until_terminal: assert property (
        @(posedge clk) disable iff (!rst_n)
        (state == CHOR && cnt_r < CHOR_CYCLES) |=> (state == CHOR && cnt_r == ($past(cnt_r) + 9'd1))
    );

    // CHOR advances to OUTLT at its terminal count.
    check_chor_to_outlt_at_terminal: assert property (
        @(posedge clk) disable iff (!rst_n)
        (state == CHOR && cnt_r == CHOR_CYCLES) |=> (state == OUTLT && cnt_r == 9'd0)
    );

    // OUTLT increments the counter until its terminal count.
    check_outlt_counts_until_terminal: assert property (
        @(posedge clk) disable iff (!rst_n)
        (state == OUTLT && cnt_r < OUTLT_CYCLES) |=> (state == OUTLT && cnt_r == ($past(cnt_r) + 9'd1))
    );

    // OUTLT advances to OUT at its terminal count.
    check_outlt_to_out_at_terminal: assert property (
        @(posedge clk) disable iff (!rst_n)
        (state == OUTLT && cnt_r == OUTLT_CYCLES) |=> (state == OUT && cnt_r == 9'd0)
    );

    // OUT increments the counter until its terminal count.
    check_out_counts_until_terminal: assert property (
        @(posedge clk) disable iff (!rst_n)
        (state == OUT && cnt_r < OUT_CYCLES) |=> (state == OUT && cnt_r == ($past(cnt_r) + 9'd1))
    );

    // OUT returns to IDLE and pulses done_o at completion.
    check_out_to_idle_and_done: assert property (
        @(posedge clk) disable iff (!rst_n)
        (state == OUT && cnt_r == OUT_CYCLES) |=> (state == IDLE && cnt_r == 9'd0 && done_o)
    );

endmodule

rtl:
module magnitude_comparison (
  input [3:0] A,
  input [3:0] B,
  output reg eq,
  output reg gt
);

  always @(*) begin
    eq = (A == B);
    gt = (A > B);
  end

endmodule

sva:
module magnitude_comparison_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic eq,
    input logic gt
);

    // eq matches the equality comparison of A and B.
    check_eq_function: assert property (
        @(posedge clk) eq === (A == B)
    );

    // gt matches the greater-than comparison of A and B.
    check_gt_function: assert property (
        @(posedge clk) gt === (A > B)
    );

    // Equal inputs drive eq high and gt low.
    check_equal_case: assert property (
        @(posedge clk) (A == B) |-> (eq && !gt)
    );

    // A greater than B drives gt high and eq low.
    check_greater_case: assert property (
        @(posedge clk) (A > B) |-> (gt && !eq)
    );

    // A less than B drives both outputs low.
    check_less_case: assert property (
        @(posedge clk) (A < B) |-> (!eq && !gt)
    );

    // eq and gt are never asserted at the same time.
    check_outputs_mutex: assert property (
        @(posedge clk) !(eq && gt)
    );

endmodule

