rtl:
module test(
    input a1,
    input s1,
    input s2,
    input s3,
    output i1,
    output i2,
    output i3,
    output i4,
    output i5,
    output i6,
    output i7,
    output i8
);

// Logic to generate the outputs based on the inputs
assign i1 = a1 & s1;
assign i2 = a1 & s2;
assign i3 = a1 & s3;
assign i4 = ~a1 & s1;
assign i5 = ~a1 & s2;
assign i6 = ~a1 & s3;
assign i7 = s1 & s2 & s3;
assign i8 = ~a1 & ~s1 & ~s2 & ~s3;

endmodule

sva:
module test_sva (
    input logic a1,
    input logic s1,
    input logic s2,
    input logic s3,
    input logic i1,
    input logic i2,
    input logic i3,
    input logic i4,
    input logic i5,
    input logic i6,
    input logic i7,
    input logic i8
);

    // i1 is the AND of a1 and s1.
    check_i1_definition: assert property (
        @($global_clock) i1 == (a1 & s1)
    );

    // i2 is the AND of a1 and s2.
    check_i2_definition: assert property (
        @($global_clock) i2 == (a1 & s2)
    );

    // i3 is the AND of a1 and s3.
    check_i3_definition: assert property (
        @($global_clock) i3 == (a1 & s3)
    );

    // i4 is the AND of not-a1 and s1.
    check_i4_definition: assert property (
        @($global_clock) i4 == ((~a1) & s1)
    );

    // i5 is the AND of not-a1 and s2.
    check_i5_definition: assert property (
        @($global_clock) i5 == ((~a1) & s2)
    );

    // i6 is the AND of not-a1 and s3.
    check_i6_definition: assert property (
        @($global_clock) i6 == ((~a1) & s3)
    );

    // i7 is high only when s1, s2, and s3 are all high.
    check_i7_definition: assert property (
        @($global_clock) i7 == (s1 & s2 & s3)
    );

    // i8 is high only when a1, s1, s2, and s3 are all low.
    check_i8_definition: assert property (
        @($global_clock) i8 == ((~a1) & (~s1) & (~s2) & (~s3))
    );

    // s1 is represented by exactly one of i1 or i4 when asserted.
    check_s1_partition: assert property (
        @($global_clock) (((i1 | i4) == s1) && !(i1 & i4))
    );

    // s2 is represented by exactly one of i2 or i5 when asserted.
    check_s2_partition: assert property (
        @($global_clock) (((i2 | i5) == s2) && !(i2 & i5))
    );

    // s3 is represented by exactly one of i3 or i6 when asserted.
    check_s3_partition: assert property (
        @($global_clock) (((i3 | i6) == s3) && !(i3 & i6))
    );

endmodule

module reg32_async_reset_load_sva (
    input logic        clk,
    input logic        reset,
    input logic        load,
    input logic [31:0] data_in,
    input logic [31:0] data_out
);

    // Active-low reset forces data_out to zero.
    check_reset_clears_data_out: assert property (
        @(posedge clk) !reset |-> (data_out == 32'd0)
    );

    // When load is high, data_out captures data_in on the next registered state.
    check_load_captures_data_in: assert property (
        @(posedge clk) disable iff (!reset) load |=> (data_out == $past(data_in))
    );

    // When load is low, data_out holds its previous value.
    check_no_load_holds_data_out: assert property (
        @(posedge clk) disable iff (!reset) !load |=> (data_out == $past(data_out))
    );

endmodule

rtl:
module bitwise_operations (
  input [31:0] a,
  input [31:0] b,
  input [1:0] operation_select,
  input [4:0] shift_amount,
  output reg [31:0] result
);

  // AND operation
  wire [31:0] and_result;
  assign and_result = a & b;

  // OR operation
  wire [31:0] or_result;
  assign or_result = a | b;

  // XOR operation
  wire [31:0] xor_result;
  assign xor_result = a ^ b;

  // Shift-left operation
  wire [31:0] shift_result;
  assign shift_result = a << shift_amount;

  // Select operation based on operation_select input
  always @* begin
    case (operation_select)
      2'b00: result = and_result;
      2'b01: result = or_result;
      2'b10: result = xor_result;
      2'b11: result = shift_result;
    endcase
  end

endmodule

sva:
module bitwise_operations_assertions (
    input logic [31:0] a,
    input logic [31:0] b,
    input logic [1:0]  operation_select,
    input logic [4:0]  shift_amount,
    input logic [31:0] result
);

    // AND selection must drive the bitwise AND result.
    check_and_selected: assert property (
        @($global_clock) (operation_select == 2'b00) |-> (result == (a & b))
    );

    // OR selection must drive the bitwise OR result.
    check_or_selected: assert property (
        @($global_clock) (operation_select == 2'b01) |-> (result == (a | b))
    );

    // XOR selection must drive the bitwise XOR result.
    check_xor_selected: assert property (
        @($global_clock) (operation_select == 2'b10) |-> (result == (a ^ b))
    );

    // Shift selection must drive a left-shifted version of a.
    check_shift_selected: assert property (
        @($global_clock) (operation_select == 2'b11) |-> (result == (a << shift_amount))
    );

    // With all inputs unchanged, result must remain unchanged.
    check_no_state_when_inputs_stable: assert property (
        @($global_clock)
        (!$initstate &&
         (a == $past(a)) &&
         (b == $past(b)) &&
         (operation_select == $past(operation_select)) &&
         (shift_amount == $past(shift_amount)))
        |-> (result == $past(result))
    );

    // shift_amount must not affect result when shift is not selected.
    check_shift_amount_ignored_when_not_shift: assert property (
        @($global_clock)
        (!$initstate &&
         (operation_select == $past(operation_select)) &&
         (operation_select != 2'b11) &&
         (a == $past(a)) &&
         (b == $past(b)) &&
         (shift_amount != $past(shift_amount)))
        |-> (result == $past(result))
    );

    // b must not affect result when the shift operation is selected.
    check_b_ignored_during_shift: assert property (
        @($global_clock)
        (!$initstate &&
         (operation_select == 2'b11) &&
         ($past(operation_select) == 2'b11) &&
         (a == $past(a)) &&
         (shift_amount == $past(shift_amount)) &&
         (b != $past(b)))
        |-> (result == $past(result))
    );

endmodule

rtl:
module clock_gate_module (
  input CLK,
  input EN,
  input TE,
  input reset,
  output ENCLK
);

  reg ENCLK_reg;

  always @(posedge CLK, posedge reset) begin
    if (reset) begin
      ENCLK_reg <= 1'b0;
    end else if (EN && TE) begin
      ENCLK_reg <= ~ENCLK_reg;
    end
  end

  assign ENCLK = ENCLK_reg;

endmodule

sva:
module clock_gate_module_sva (
    input logic CLK,
    input logic EN,
    input logic TE,
    input logic reset,
    input logic ENCLK
);

    // A sampled reset must leave ENCLK low on the following clock.
    check_reset_clears_next_cycle: assert property (
        @(posedge CLK) reset |=> (ENCLK == 1'b0)
    );

    // From a high state, full enable must toggle ENCLK low by the next sample.
    check_toggle_high_to_low_when_enabled: assert property (
        @(posedge CLK) disable iff (reset)
        (EN && TE && ENCLK) |=> (ENCLK == 1'b0)
    );

    // From a low state, missing either enable keeps ENCLK low.
    check_low_holds_without_full_enable: assert property (
        @(posedge CLK) disable iff (reset)
        ((!EN || !TE) && !ENCLK) |=> (ENCLK == 1'b0)
    );

    // Without full enable, ENCLK cannot rise by the next sampled clock.
    check_no_rise_without_full_enable: assert property (
        @(posedge CLK) disable iff (reset)
        (!EN || !TE) |=> !$rose(ENCLK)
    );

    // A sampled rise must come from a prior low state with both enables high.
    check_rise_has_valid_cause: assert property (
        @(posedge CLK) disable iff (reset)
        $rose(ENCLK) |-> (!$past(reset) && $past(EN) && $past(TE) && !$past(ENCLK))
    );

endmodule

rtl:
module alu(Aval, Bval, cin, op, ALUout, cout);
   input [7:0] Aval;
   input [7:0] Bval;
   input cin;
   input [1:0] op;
   output cout;
   output reg [7:0] ALUout;

   reg cout;

   always @(*) begin
      case(op)
         2'b00 : begin
            {cout, ALUout} = Aval + Bval + cin;
         end
         2'b10 : begin
            {cout, ALUout} = {1'b0, Aval & Bval};
         end
         2'b01 : begin
            {cout, ALUout} = 9'h100 ^ (Aval + Bval + 9'h001);
         end
         2'b11 : begin
            {cout, ALUout} = {1'b0, Bval > 7'h07 ? 8'b0 : Aval << Bval};
         end
         default: begin
            {cout, ALUout} = 9'h000;
         end
      endcase
   end

endmodule

sva:
module alu_sva (
    input logic [7:0] Aval,
    input logic [7:0] Bval,
    input logic       cin,
    input logic [1:0] op,
    input logic [7:0] ALUout,
    input logic       cout
);

    // op=00 selects addition with carry-in.
    check_add_mode_result: assert property (
        @($global_clock)
        (op == 2'b00) |-> ({cout, ALUout} == (Aval + Bval + cin))
    );

    // op=10 selects bitwise AND and forces carry low.
    check_and_mode_result: assert property (
        @($global_clock)
        (op == 2'b10) |-> ({cout, ALUout} == {1'b0, (Aval & Bval)})
    );

    // op=01 selects the XOR-modified 9-bit add result.
    check_xor_add_mode_result: assert property (
        @($global_clock)
        (op == 2'b01) |-> ({cout, ALUout} == (9'h100 ^ (Aval + Bval + 9'h001)))
    );

    // op=11 clears the output when the shift amount is greater than 7.
    check_shift_mode_large_amount_zero: assert property (
        @($global_clock)
        ((op == 2'b11) && (Bval > 7'h07)) |-> ({cout, ALUout} == 9'h000)
    );

    // op=11 shifts Aval left by Bval when the shift amount is 7 or less.
    check_shift_mode_small_amount_result: assert property (
        @($global_clock)
        ((op == 2'b11) && (Bval <= 7'h07)) |-> ({cout, ALUout} == {1'b0, (Aval << Bval)})
    );

endmodule

rtl:
module pulse_detection (
  input clk,
  input reset,
  input [31:0] in,
  input [15:0] threshold,
  output reg [15:0] frequency,
  output reg threshold_exceeded
);

  reg [31:0] count;
  reg [3:0] prescaler;
  reg [31:0] prev_in;
  reg [31:0] curr_in;

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      count <= 0;
      prescaler <= 0;
      prev_in <= 0;
      curr_in <= 0;
      frequency <= 0;
      threshold_exceeded <= 0;
    end
    else begin
      if (prescaler == 0) begin
        prev_in <= curr_in;
        curr_in <= in;
        if (prev_in == 1'b0 && curr_in == 1'b1) begin
          count <= count + 1;
        end
        prescaler <= 15;
      end
      else begin
        prescaler <= prescaler - 1;
      end
      if (count >= 100000000) begin
        frequency <= count / 100000;
        count <= 0;
        if (frequency > threshold) begin
          threshold_exceeded <= 1;
        end
        else begin
          threshold_exceeded <= 0;
        end
      end
    end
  end

endmodule

sva:
module pulse_detection_sva (
    input logic        clk,
    input logic        reset,
    input logic [31:0] in,
    input logic [15:0] threshold,
    input logic [15:0] frequency,
    input logic        threshold_exceeded,
    input logic [31:0] count,
    input logic [3:0]  prescaler,
    input logic [31:0] prev_in,
    input logic [31:0] curr_in
);

    // Reset clears all state and outputs.
    reset_clears_state: assert property (
        @(posedge clk)
        reset |-> (count == 32'd0) &&
                  (prescaler == 4'd0) &&
                  (prev_in == 32'd0) &&
                  (curr_in == 32'd0) &&
                  (frequency == 16'd0) &&
                  (threshold_exceeded == 1'b0)
    );

    // A zero prescaler reloads to 15 on the next cycle.
    prescaler_reloads_after_sample: assert property (
        @(posedge clk) disable iff (reset)
        (prescaler == 4'd0) |=> (prescaler == 4'd15)
    );

    // A nonzero prescaler decrements by one each cycle.
    prescaler_decrements_while_busy: assert property (
        @(posedge clk) disable iff (reset)
        (prescaler != 4'd0) |=> (prescaler == ($past(prescaler) - 4'd1))
    );

    // Sampling updates prev_in from curr_in and curr_in from in.
    sample_updates_input_history: assert property (
        @(posedge clk) disable iff (reset)
        (prescaler == 4'd0) |=> (prev_in == $past(curr_in)) &&
                                (curr_in == $past(in))
    );

    // Without sampling, prev_in and curr_in hold their values.
    hold_input_history_while_prescaling: assert property (
        @(posedge clk) disable iff (reset)
        (prescaler != 4'd0) |=> (prev_in == $past(prev_in)) &&
                                (curr_in == $past(curr_in))
    );

    // An exact sampled 0-to-1 value increments count below the window limit.
    count_increments_on_qualified_sample: assert property (
        @(posedge clk) disable iff (reset)
        (prescaler == 4'd0) &&
        (prev_in == 32'd0) &&
        (curr_in == 32'd1) &&
        (count < 32'd100000000)
        |=> (count == ($past(count) + 32'd1))
    );

    // Without a qualified sample, count holds below the window limit.
    count_holds_without_qualified_sample: assert property (
        @(posedge clk) disable iff (reset)
        (count < 32'd100000000) &&
        !((prescaler == 4'd0) && (prev_in == 32'd0) && (curr_in == 32'd1))
        |=> (count == $past(count))
    );

    // Reaching the window limit clears count on the next cycle.
    count_clears_at_window_end: assert property (
        @(posedge clk) disable iff (reset)
        (count >= 32'd100000000) |=> (count == 32'd0)
    );

    // Reaching the window limit updates frequency from count / 100000.
    frequency_updates_at_window_end: assert property (
        @(posedge clk) disable iff (reset)
        (count >= 32'd100000000) |=> (frequency == ($past(count) / 32'd100000))
    );

    // Before the window ends, frequency holds its value.
    frequency_holds_before_window_end: assert property (
        @(posedge clk) disable iff (reset)
        (count < 32'd100000000) |=> (frequency == $past(frequency))
    );

    // Reaching the window limit updates the flag from the prior frequency comparison.
    threshold_flag_updates_at_window_end: assert property (
        @(posedge clk) disable iff (reset)
        (count >= 32'd100000000)
        |=> (threshold_exceeded == ($past(frequency) > $past(threshold)))
    );

    // Before the window ends, the threshold flag holds its value.
    threshold_flag_holds_before_window_end: assert property (
        @(posedge clk) disable iff (reset)
        (count < 32'd100000000) |=> (threshold_exceeded == $past(threshold_exceeded))
    );

endmodule

module adder_sva (
    input logic clk,
    input logic signed [7:0] A,
    input logic signed [7:0] B,
    input logic signed [7:0] sum,
    input logic C
);

    // sum reflects the 8-bit signed addition of A and B.
    check_sum_matches_addition: assert property (
        @(posedge clk) sum == (A + B)
    );

    // C is the sign-extension bit of the 8-bit result.
    check_c_matches_sum_sign: assert property (
        @(posedge clk) C == sum[7]
    );

    // With A equal to zero, the outputs mirror B.
    check_zero_left_identity: assert property (
        @(posedge clk) (A == 8'sd0) |-> ((sum == B) && (C == B[7]))
    );

    // With B equal to zero, the outputs mirror A.
    check_zero_right_identity: assert property (
        @(posedge clk) (B == 8'sd0) |-> ((sum == A) && (C == A[7]))
    );

    // Zero plus zero produces a zero result and clear C.
    check_zero_plus_zero: assert property (
        @(posedge clk) ((A == 8'sd0) && (B == 8'sd0)) |-> ((sum == 8'sd0) && (C == 1'b0))
    );

endmodule

module binary_counter_sva (
    input logic       CLK,
    input logic       RST,
    input logic       COUNT_EN,
    input logic [3:0] Q
);

    // A reset cycle clears Q by the next sampled clock.
    check_reset_clears_q: assert property (
        @(posedge CLK) $past(RST) |-> (Q == 4'b0000)
    );

    // When enabled outside reset, Q increments by one.
    check_count_increment: assert property (
        @(posedge CLK) disable iff (RST)
        (!$past(RST) && $past(COUNT_EN)) |-> (Q == ($past(Q) + 4'd1))
    );

    // When not enabled outside reset, Q holds its value.
    check_hold_when_disabled: assert property (
        @(posedge CLK) disable iff (RST)
        (!$past(RST) && !$past(COUNT_EN)) |-> (Q == $past(Q))
    );

    // An enabled count wraps from 4'hF back to 4'h0.
    check_wrap_from_max: assert property (
        @(posedge CLK) disable iff (RST)
        (!$past(RST) && $past(COUNT_EN) && ($past(Q) == 4'hF)) |-> (Q == 4'h0)
    );

    // Q only changes after a reset cycle or an enabled count cycle.
    check_q_changes_only_after_action: assert property (
        @(posedge CLK) disable iff (RST)
        (Q != $past(Q)) |-> ($past(RST) || $past(COUNT_EN))
    );

endmodule

