sva:
module top_sva (
    input logic       di,
    input logic [3:0] do
);

    // do[0] is the inverted input.
    check_do0_inverts_di: assert property (
        @($global_clock) do[0] == ~di
    );

    // do[1] is the inverted input.
    check_do1_inverts_di: assert property (
        @($global_clock) do[1] == ~di
    );

    // do[2] is the inverted input from c_inst.
    check_do2_inverts_di: assert property (
        @($global_clock) do[2] == ~di
    );

    // do[3] matches the original input.
    check_do3_matches_di: assert property (
        @($global_clock) do[3] == di
    );

    // The two box outputs must match.
    check_do0_do1_match: assert property (
        @($global_clock) do[0] == do[1]
    );

    // c_inst low output must match the box outputs.
    check_do1_do2_match: assert property (
        @($global_clock) do[1] == do[2]
    );

    // c_inst high output must complement the low outputs.
    check_do3_complements_do2: assert property (
        @($global_clock) do[3] == ~do[2]
    );

    // The full output bus matches the implemented combinational function.
    check_output_bus_function: assert property (
        @($global_clock) do == {di, ~di, ~di, ~di}
    );

endmodule

rtl:
module full_adder(
    input A,
    input B,
    input CI,
    output S,
    output CO
);

assign S = A ^ B ^ CI;
assign CO = (A & B) | (CI & (A ^ B));

endmodule

module four_bit_adder(
    input [3:0] A,
    input [3:0] B,
    output [4:0] C,
    output CO
);

wire [3:0] S;
wire [3:0] CO_int;

full_adder FA0(.A(A[0]), .B(B[0]), .CI(1'b0), .S(S[0]), .CO(CO_int[0]));
full_adder FA1(.A(A[1]), .B(B[1]), .CI(CO_int[0]), .S(S[1]), .CO(CO_int[1]));
full_adder FA2(.A(A[2]), .B(B[2]), .CI(CO_int[1]), .S(S[2]), .CO(CO_int[2]));
full_adder FA3(.A(A[3]), .B(B[3]), .CI(CO_int[2]), .S(S[3]), .CO(CO));

assign C = {CO, S};

endmodule

sva:
module four_bit_adder_sva (
    input logic       clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [4:0] C,
    input logic       CO
);

    // The 5-bit output vector must equal the unsigned sum of A and B.
    check_total_sum: assert property (
        @(posedge clk) C == ({1'b0, A} + {1'b0, B})
    );

    // The separate carry output must match the MSB of C.
    check_co_matches_c_msb: assert property (
        @(posedge clk) CO == C[4]
    );

    // Bit 0 sum is the XOR of A[0] and B[0] with no carry-in.
    check_bit0_sum: assert property (
        @(posedge clk) C[0] == (A[0] ^ B[0])
    );

    // Bit 1 sum includes the carry generated by bit 0.
    check_bit1_sum: assert property (
        @(posedge clk) C[1] == (A[1] ^ B[1] ^ (A[0] & B[0]))
    );

    // Bit 2 sum includes the ripple carry from bits 0 and 1.
    check_bit2_sum: assert property (
        @(posedge clk) C[2] == (A[2] ^ B[2] ^
                                ((A[1] & B[1]) |
                                 ((A[0] & B[0]) & (A[1] ^ B[1]))))
    );

    // Bit 3 sum includes the ripple carry from bits 0 through 2.
    check_bit3_sum: assert property (
        @(posedge clk) C[3] == (A[3] ^ B[3] ^
                                ((A[2] & B[2]) |
                                 (((A[1] & B[1]) |
                                   ((A[0] & B[0]) & (A[1] ^ B[1]))) &
                                  (A[2] ^ B[2]))))
    );

    // Carry-out follows the final full-adder carry equation.
    check_final_carry: assert property (
        @(posedge clk) CO == ((A[3] & B[3]) |
                              (((A[2] & B[2]) |
                                (((A[1] & B[1]) |
                                  ((A[0] & B[0]) & (A[1] ^ B[1]))) &
                                 (A[2] ^ B[2]))) &
                               (A[3] ^ B[3])))
    );

endmodule

rtl:
module johnson_counter (
    input clk,
    output reg [3:0] Q
);

reg [3:0] shift_reg;

always @(posedge clk) begin
    shift_reg <= {shift_reg[2:0], shift_reg[3]};
    Q <= shift_reg[0] ^ shift_reg[3];
end

endmodule

sva:
module johnson_counter_sva (
    input logic       clk,
    input logic [3:0] Q,
    input logic [3:0] shift_reg
);

    // shift_reg rotates by one bit on every clock.
    check_shift_reg_rotation: assert property (
        @(posedge clk)
        !$isunknown($past(shift_reg)) |-> shift_reg == {$past(shift_reg[2:0]), $past(shift_reg[3])}
    );

    // Q[0] is the XOR of the prior shift_reg[0] and shift_reg[3].
    check_q_lsb_from_prior_shift: assert property (
        @(posedge clk)
        !$isunknown($past(shift_reg)) |-> Q[0] == ($past(shift_reg[0]) ^ $past(shift_reg[3]))
    );

    // The upper bits of Q are always zero after Q is first updated.
    check_q_upper_bits_zero: assert property (
        @(posedge clk)
        !$isunknown($past(shift_reg)) |-> Q[3:1] == 3'b000
    );

    // The current Q[0] matches the current rotated shift_reg bits.
    check_q_lsb_matches_current_shift: assert property (
        @(posedge clk)
        !$isunknown($past(shift_reg)) |-> Q[0] == (shift_reg[1] ^ shift_reg[0])
    );

    // A 4-bit rotation returns shift_reg to the same value after four clocks.
    check_shift_reg_period_four: assert property (
        @(posedge clk)
        !$isunknown($past(shift_reg, 4)) |-> shift_reg == $past(shift_reg, 4)
    );

    // Q repeats every four clocks once four updated Q values exist.
    check_q_period_four: assert property (
        @(posedge clk)
        !$isunknown($past(shift_reg, 5)) |-> Q == $past(Q, 4)
    );

endmodule

