module my_flip_flop (
    input clk,
    input d,
    input rst,
    output q
);

    reg q_reg;

    always @(posedge clk) begin
        if (rst) begin
            q_reg <= 1'b0;
        end else begin
            q_reg <= d;
        end
    end

    assign q = q_reg;

endmodule

sva:
module my_flip_flop_sva (
    input logic clk,
    input logic d,
    input logic rst,
    input logic q
);

    // q reflects the previous cycle's d when reset was not active.
    check_q_captures_previous_d: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        !$past(rst) |-> (q == $past(d))
    );

    // A reset on the previous cycle forces q low.
    check_reset_clears_q: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        $past(rst) |-> (q == 1'b0)
    );

    // q holds its value when the previous d already matched q.
    check_q_holds_when_d_is_unchanged: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        (!$past(rst) && ($past(d) == $past(q))) |-> (q == $past(q))
    );

    // q updates when the previous d differed from q.
    check_q_updates_when_d_changes: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        (!$past(rst) && ($past(d) != $past(q))) |-> (q == $past(d))
    );

endmodule

rtl:
module CRC_serial_m_lfs_XOR
#(
	parameter	HASH_LENGTH = 64
)
(
	i_message     ,  
	i_cur_parity  ,  
	o_next_parity
);
	input						i_message    ;
	input	[HASH_LENGTH-1:0]	i_cur_parity  ;
	output	[HASH_LENGTH-1:0]	o_next_parity ;

	localparam	[0:64]	HASH_VALUE	=	65'b11001001011011000101011110010101110101111000011100001111010000101;

	wire	w_feedback_term;

	assign	w_feedback_term	=	i_message ^ i_cur_parity[HASH_LENGTH-1];

	assign	o_next_parity[0]	=	w_feedback_term;

	genvar	i;
	generate
		for (i=1; i<HASH_LENGTH; i=i+1)
		begin: linear_function
			if (HASH_VALUE[i] == 1)
				assign	o_next_parity[i] = i_cur_parity[i-1] ^ w_feedback_term;
			else
				assign	o_next_parity[i] = i_cur_parity[i-1];
		end
	endgenerate

endmodule

sva:
module CRC_serial_m_lfs_XOR_sva
#(
    parameter HASH_LENGTH = 64
)
(
    input logic                    i_message,
    input logic [HASH_LENGTH-1:0]  i_cur_parity,
    input logic [HASH_LENGTH-1:0]  o_next_parity
);

    localparam [0:64] HASH_VALUE = 65'b11001001011011000101011110010101110101111000011100001111010000101;

    // Bit 0 is always the feedback term.
    check_feedback_bit0: assert property (
        @($global_clock)
        o_next_parity[0] == (i_message ^ i_cur_parity[HASH_LENGTH-1])
    );

    genvar i;
    generate
        for (i = 1; i < HASH_LENGTH; i = i + 1) begin : gen_next_parity_checks
            if (HASH_VALUE[i] == 1'b1) begin : gen_tapped_check
                // Tapped bits XOR the shifted parity bit with the feedback term.
                check_tapped_bit: assert property (
                    @($global_clock)
                    o_next_parity[i] == (i_cur_parity[i-1] ^ (i_message ^ i_cur_parity[HASH_LENGTH-1]))
                );
            end
            else begin : gen_shift_check
                // Untapped bits are a pure one-bit shift of the current parity.
                check_shift_bit: assert property (
                    @($global_clock)
                    o_next_parity[i] == i_cur_parity[i-1]
                );
            end
        end
    endgenerate

endmodule

rtl:
module priority_encoder(
  input [3:0] in,  // number of input signals
  output [1:0] out
);

// assign out = $clog2(in);

// Synthesizable implementation of a priority encoder
assign out = (in[3] ? 2'b11 :
              (in[2] ? 2'b10 :
               (in[1] ? 2'b01 :
                (in[0] ? 2'b00 : 2'bxx))));

endmodule

sva:
module priority_encoder_sva (
    input logic       clk,
    input logic [3:0] in,
    input logic [1:0] out
);

    // If input bit 3 is set, it has highest priority and out must be 3.
    check_encode_bit3: assert property (
        @(posedge clk) in[3] |-> (out == 2'b11)
    );

    // If bit 3 is clear and bit 2 is set, out must be 2.
    check_encode_bit2: assert property (
        @(posedge clk) (!in[3] && in[2]) |-> (out == 2'b10)
    );

    // If bits 3:2 are clear and bit 1 is set, out must be 1.
    check_encode_bit1: assert property (
        @(posedge clk) (!in[3] && !in[2] && in[1]) |-> (out == 2'b01)
    );

    // If bits 3:1 are clear and bit 0 is set, out must be 0.
    check_encode_bit0: assert property (
        @(posedge clk) (!in[3] && !in[2] && !in[1] && in[0]) |-> (out == 2'b00)
    );

    // For any nonzero input, out must match the implemented priority encoding.
    check_nonzero_input_encoding: assert property (
        @(posedge clk) (|in) |-> (out == (in[3] ? 2'b11 :
                                         (in[2] ? 2'b10 :
                                          (in[1] ? 2'b01 : 2'b00))))
    );

endmodule

