rtl:
module my_module (
    input A1,
    input A2,
    input A3,
    input A4,
    input B1,
    output X
);

    reg X_A, X_B;

    always @(*) begin
        if (A1 == 1) begin
            X_A = A2;
        end else begin
            X_A = A3 ^ A4;
        end
    end

    always @(*) begin
        if (B1 == 1) begin
            X_B = ~X_A;
        end else begin
            X_B = X_A;
        end
    end

    assign X = X_B;

endmodule

sva:
module my_module_sva (
    input logic clk,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic A4,
    input logic B1,
    input logic X
);

    // X must match the complete combinational function.
    check_full_function: assert property (
        @(posedge clk) X == ((A1 ? A2 : (A3 ^ A4)) ^ B1)
    );

    // When A1 selects A2 and B1 is low, X matches A2.
    check_a2_selected_passthrough: assert property (
        @(posedge clk) (A1 && !B1) |-> (X == A2)
    );

    // When A1 selects A2 and B1 is high, X is the inverse of A2.
    check_a2_selected_inverted: assert property (
        @(posedge clk) (A1 && B1) |-> (X == ~A2)
    );

    // When A1 selects the XOR path and B1 is low, X matches A3 ^ A4.
    check_xor_selected_passthrough: assert property (
        @(posedge clk) (!A1 && !B1) |-> (X == (A3 ^ A4))
    );

    // When A1 selects the XOR path and B1 is high, X is the inverse of A3 ^ A4.
    check_xor_selected_inverted: assert property (
        @(posedge clk) (!A1 && B1) |-> (X == ~(A3 ^ A4))
    );

    // With B1 low, X passes the selected value unchanged.
    check_b1_low_passthrough: assert property (
        @(posedge clk) (!B1) |-> (X == (A1 ? A2 : (A3 ^ A4)))
    );

    // With B1 high, X is the inverse of the selected value.
    check_b1_high_inverts_selected_value: assert property (
        @(posedge clk) B1 |-> (X == ~((A1 ? A2 : (A3 ^ A4))))
    );

endmodule

module counter_sva(
    input logic       clk,
    input logic       reset,
    input logic       up_down,
    input logic [3:0] out
);

    // Reset clears the counter on the next sampled clock.
    reset_clears_out: assert property (
        @(posedge clk) reset |=> (out == 4'b0000)
    );

    // With reset low and up_down high, the counter increments by one.
    count_up_step: assert property (
        @(posedge clk) disable iff (reset)
        up_down |=> (out == ($past(out) + 4'd1))
    );

    // With reset low and up_down low, the counter decrements by one.
    count_down_step: assert property (
        @(posedge clk) disable iff (reset)
        !up_down |=> (out == ($past(out) - 4'd1))
    );

    // Counting up from 4'hF wraps around to 4'h0.
    up_wraps_from_f_to_0: assert property (
        @(posedge clk) disable iff (reset)
        up_down && (out == 4'hF) |=> (out == 4'h0)
    );

    // Counting down from 4'h0 wraps around to 4'hF.
    down_wraps_from_0_to_f: assert property (
        @(posedge clk) disable iff (reset)
        !up_down && (out == 4'h0) |=> (out == 4'hF)
    );

endmodule

rtl:
module rippleCarryAdder(A, B, Cin, Sum, Cout);
    input [3:0] A;
    input [3:0] B;
    input Cin;
    output [3:0] Sum;
    output Cout;

    wire [3:0] C;
    wire [3:0] S;

    fullAdder FA0(A[0], B[0], Cin, S[0], C[0]);
    fullAdder FA1(A[1], B[1], C[0], S[1], C[1]);
    fullAdder FA2(A[2], B[2], C[1], S[2], C[2]);
    fullAdder FA3(A[3], B[3], C[2], S[3], Cout);

    assign Sum = S;

endmodule
module fullAdder(A, B, Cin, Sum, Cout);
    input A;
    input B;
    input Cin;
    output Sum;
    output Cout;

    assign Sum = A ^ B ^ Cin;
    assign Cout = (A & B) | (B & Cin) | (Cin & A);

endmodule

sva:
module rippleCarryAdder_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic Cin,
    input logic [3:0] Sum,
    input logic Cout,
    input logic [3:0] C,
    input logic [3:0] S
);

    // Sum must mirror the internal S bus.
    check_sum_alias: assert property (
        @(posedge clk) Sum == S
    );

    // FA0 sum must match the full-adder XOR equation.
    check_fa0_sum_function: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0] ^ Cin)
    );

    // FA0 carry must match the full-adder carry equation.
    check_fa0_carry_function: assert property (
        @(posedge clk) C[0] == ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin))
    );

    // FA1 sum must use C[0] as its carry-in.
    check_fa1_sum_function: assert property (
        @(posedge clk) S[1] == (A[1] ^ B[1] ^ C[0])
    );

    // FA1 carry must match the full-adder carry equation.
    check_fa1_carry_function: assert property (
        @(posedge clk) C[1] == ((A[1] & B[1]) | (A[1] & C[0]) | (B[1] & C[0]))
    );

    // FA2 sum must use C[1] as its carry-in.
    check_fa2_sum_function: assert property (
        @(posedge clk) S[2] == (A[2] ^ B[2] ^ C[1])
    );

    // FA2 carry must match the full-adder carry equation.
    check_fa2_carry_function: assert property (
        @(posedge clk) C[2] == ((A[2] & B[2]) | (A[2] & C[1]) | (B[2] & C[1]))
    );

    // FA3 sum must use C[2] as its carry-in.
    check_fa3_sum_function: assert property (
        @(posedge clk) S[3] == (A[3] ^ B[3] ^ C[2])
    );

    // FA3 carry-out must match the full-adder carry equation.
    check_fa3_carry_function: assert property (
        @(posedge clk) Cout == ((A[3] & B[3]) | (A[3] & C[2]) | (B[3] & C[2]))
    );

    // The full 5-bit result must equal A + B + Cin.
    check_overall_addition_result: assert property (
        @(posedge clk) {Cout, Sum} == ({1'b0, A} + {1'b0, B} + {{4{1'b0}}, Cin})
    );

endmodule

