sva:
module up_counter_sva(
    input logic clk,
    input logic rst,
    input logic [3:0] count
);

    // Reset drives count to zero on the following cycle.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |=> (count == 4'd0)
    );

    // If reset remains asserted, count stays at zero.
    check_reset_holds_zero: assert property (
        @(posedge clk) rst |=> (rst -> (count == 4'd0))
    );

    // After reset deasserts, the first sampled count is zero.
    check_reset_release_starts_from_zero: assert property (
        @(posedge clk) rst |=> (!rst -> (count == 4'd0))
    );

    // Across consecutive non-reset cycles, count increments by one.
    check_count_increments: assert property (
        @(posedge clk) disable iff (rst) !rst |=> (count == ($past(count) + 4'd1))
    );

    // The 4-bit counter wraps from 15 back to 0.
    check_count_rollover: assert property (
        @(posedge clk) disable iff (rst) (!rst && (count == 4'hf)) |=> (count == 4'h0)
    );

endmodule

rtl:
module comparator_8bit (
  input [7:0] A,
  input [7:0] B,
  output reg equal,
  output reg greater_than,
  output reg less_than
);

  always @(*) begin
    if (A == B) begin
      equal = 1;
      greater_than = 0;
      less_than = 0;
    end
    else if (A > B) begin
      equal = 0;
      greater_than = 1;
      less_than = 0;
    end
    else begin
      equal = 0;
      greater_than = 0;
      less_than = 1;
    end
  end

endmodule

sva:
module comparator_8bit_sva (
    input logic clk,
    input logic [7:0] A,
    input logic [7:0] B,
    input logic equal,
    input logic greater_than,
    input logic less_than
);

    // Equal inputs select only equal.
    check_equal_case: assert property (
        @(posedge clk) (A == B) |-> (equal && !greater_than && !less_than)
    );

    // A greater than B selects only greater_than.
    check_greater_case: assert property (
        @(posedge clk) (A > B) |-> (!equal && greater_than && !less_than)
    );

    // A less than B selects only less_than.
    check_less_case: assert property (
        @(posedge clk) (A < B) |-> (!equal && !greater_than && less_than)
    );

    // equal and greater_than cannot be high together.
    check_equal_greater_mutex: assert property (
        @(posedge clk) !(equal && greater_than)
    );

    // equal and less_than cannot be high together.
    check_equal_less_mutex: assert property (
        @(posedge clk) !(equal && less_than)
    );

    // greater_than and less_than cannot be high together.
    check_greater_less_mutex: assert property (
        @(posedge clk) !(greater_than && less_than)
    );

    // One result output must always be asserted.
    check_result_present: assert property (
        @(posedge clk) (equal || greater_than || less_than)
    );

endmodule

rtl:
module abs_difference_sum (
  input [15:0] input_a,
  input [15:0] input_b,
  output [15:0] output_sum
);

  wire [3:0] a_0to3, a_4to7, a_8to11, a_12to15;
  wire [3:0] b_0to3, b_4to7, b_8to11, b_12to15;
  wire [3:0] abs_diff_0to3, abs_diff_4to7, abs_diff_8to11, abs_diff_12to15;
  wire [15:0] abs_diff_sum;

  // Split input vectors into 4-bit vectors
  assign a_0to3 = input_a[3:0];
  assign a_4to7 = input_a[7:4];
  assign a_8to11 = input_a[11:8];
  assign a_12to15 = input_a[15:12];
  assign b_0to3 = input_b[3:0];
  assign b_4to7 = input_b[7:4];
  assign b_8to11 = input_b[11:8];
  assign b_12to15 = input_b[15:12];

  // Calculate absolute difference between each corresponding 4-bit vector
  assign abs_diff_0to3 = (a_0to3 > b_0to3) ? (a_0to3 - b_0to3) : (b_0to3 - a_0to3);
  assign abs_diff_4to7 = (a_4to7 > b_4to7) ? (a_4to7 - b_4to7) : (b_4to7 - a_4to7);
  assign abs_diff_8to11 = (a_8to11 > b_8to11) ? (a_8to11 - b_8to11) : (b_8to11 - a_8to11);
  assign abs_diff_12to15 = (a_12to15 > b_12to15) ? (a_12to15 - b_12to15) : (b_12to15 - a_12to15);

  // Calculate sum of absolute differences
  assign abs_diff_sum = {abs_diff_12to15, abs_diff_8to11, abs_diff_4to7, abs_diff_0to3};
  assign output_sum = abs_diff_sum;

endmodule

sva:
module abs_difference_sum_sva (
    input logic [15:0] input_a,
    input logic [15:0] input_b,
    input logic [15:0] output_sum
);

    function automatic [3:0] abs4(input [3:0] x, input [3:0] y);
        begin
            abs4 = (x > y) ? (x - y) : (y - x);
        end
    endfunction

    // Low output nibble uses a-b when the low nibble of a is larger.
    check_low_nibble_gt_branch: assert property (
        @($global_clock)
        (input_a[3:0] > input_b[3:0]) |-> (output_sum[3:0] == (input_a[3:0] - input_b[3:0]))
    );

    // Low output nibble uses b-a when the low nibble of b is larger or equal.
    check_low_nibble_le_branch: assert property (
        @($global_clock)
        (input_a[3:0] <= input_b[3:0]) |-> (output_sum[3:0] == (input_b[3:0] - input_a[3:0]))
    );

    // Bits [7:4] use a-b when that nibble of a is larger.
    check_midlow_nibble_gt_branch: assert property (
        @($global_clock)
        (input_a[7:4] > input_b[7:4]) |-> (output_sum[7:4] == (input_a[7:4] - input_b[7:4]))
    );

    // Bits [7:4] use b-a when that nibble of b is larger or equal.
    check_midlow_nibble_le_branch: assert property (
        @($global_clock)
        (input_a[7:4] <= input_b[7:4]) |-> (output_sum[7:4] == (input_b[7:4] - input_a[7:4]))
    );

    // Bits [11:8] use a-b when that nibble of a is larger.
    check_midhigh_nibble_gt_branch: assert property (
        @($global_clock)
        (input_a[11:8] > input_b[11:8]) |-> (output_sum[11:8] == (input_a[11:8] - input_b[11:8]))
    );

    // Bits [11:8] use b-a when that nibble of b is larger or equal.
    check_midhigh_nibble_le_branch: assert property (
        @($global_clock)
        (input_a[11:8] <= input_b[11:8]) |-> (output_sum[11:8] == (input_b[11:8] - input_a[11:8]))
    );

    // High output nibble uses a-b when the high nibble of a is larger.
    check_high_nibble_gt_branch: assert property (
        @($global_clock)
        (input_a[15:12] > input_b[15:12]) |-> (output_sum[15:12] == (input_a[15:12] - input_b[15:12]))
    );

    // High output nibble uses b-a when the high nibble of b is larger or equal.
    check_high_nibble_le_branch: assert property (
        @($global_clock)
        (input_a[15:12] <= input_b[15:12]) |-> (output_sum[15:12] == (input_b[15:12] - input_a[15:12]))
    );

    // The 16-bit output is the concatenation of the four nibble absolute differences.
    check_output_concatenation: assert property (
        @($global_clock)
        output_sum == {
            abs4(input_a[15:12], input_b[15:12]),
            abs4(input_a[11:8],  input_b[11:8]),
            abs4(input_a[7:4],   input_b[7:4]),
            abs4(input_a[3:0],   input_b[3:0])
        }
    );

    // Identical input words produce an all-zero output word.
    check_equal_inputs_zero_output: assert property (
        @($global_clock)
        (input_a == input_b) |-> (output_sum == 16'h0000)
    );

endmodule

