module DivFrec(clk,rst,div,clkd,clk_1kHz);
input wire clk,rst;
input wire [10:0]div;
output wire clkd;
output wire clk_1kHz;

reg [10:0]q = 0;
reg cd = 0;
reg [15:0]q_1kHz = 0;
reg cd_1kHz = 0;

always@(posedge clk, posedge rst)
	if (rst)
		begin
		q <= 0;
		cd <=0;
		end
	else 
		if (q==div)
			begin
			q <= 0;
			cd <= ~cd;
			end
		else
			q <= q + 11'b1;

assign clkd = cd;

always@(posedge clk, posedge rst)
	if (rst)
		begin
		q_1kHz <= 0;
		cd_1kHz <=0;
		end
	else 
		if (q_1kHz==16'd49999)
			begin
			q_1kHz <= 0;
			cd_1kHz <= ~cd_1kHz;
			end
		else
			q_1kHz <= q_1kHz + 16'b1;

assign clk_1kHz = cd_1kHz;


endmodule

sva:
module DivFrec_assertions (
    input logic clk,
    input logic rst,
    input logic [10:0] div,
    input logic clkd,
    input logic clk_1kHz,
    input logic [10:0] q,
    input logic cd,
    input logic [15:0] q_1kHz,
    input logic cd_1kHz
);

    // clkd must mirror the internal divider flop.
    check_clkd_reflects_cd: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        clkd == cd
    );

    // clk_1kHz must mirror the internal 1 kHz divider flop.
    check_clk_1khz_reflects_cd_1khz: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        clk_1kHz == cd_1kHz
    );

    // After a sampled reset cycle, the main divider state must be cleared.
    check_main_reset_release_state: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        $past(rst) |-> (q == 11'd0 && cd == 1'b0 && clkd == 1'b0)
    );

    // After a sampled reset cycle, the 1 kHz divider state must be cleared.
    check_fixed_reset_release_state: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        $past(rst) |-> (q_1kHz == 16'd0 && cd_1kHz == 1'b0 && clk_1kHz == 1'b0)
    );

    // The programmable counter increments when it is not at its terminal count.
    check_main_counter_increments: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        (!$past(rst) && ($past(q) != $past(div))) |-> (q == ($past(q) + 11'd1))
    );

    // The programmable divider output holds when the terminal count is not reached.
    check_main_divider_holds_between_terminals: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        (!$past(rst) && ($past(q) != $past(div))) |-> (cd == $past(cd))
    );

    // The programmable counter clears when it reaches div.
    check_main_counter_resets_at_terminal: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        (!$past(rst) && ($past(q) == $past(div))) |-> (q == 11'd0)
    );

    // The programmable divider output toggles when q reaches div.
    check_main_divider_toggles_at_terminal: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        (!$past(rst) && ($past(q) == $past(div))) |-> (cd != $past(cd))
    );

    // The 1 kHz counter increments when it is not at 49999.
    check_fixed_counter_increments: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        (!$past(rst) && ($past(q_1kHz) != 16'd49999)) |-> (q_1kHz == ($past(q_1kHz) + 16'd1))
    );

    // The 1 kHz divider output holds when 49999 is not reached.
    check_fixed_divider_holds_between_terminals: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        (!$past(rst) && ($past(q_1kHz) != 16'd49999)) |-> (cd_1kHz == $past(cd_1kHz))
    );

    // The 1 kHz counter clears when it reaches 49999.
    check_fixed_counter_resets_at_terminal: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        (!$past(rst) && ($past(q_1kHz) == 16'd49999)) |-> (q_1kHz == 16'd0)
    );

    // The 1 kHz divider output toggles when q_1kHz reaches 49999.
    check_fixed_divider_toggles_at_terminal: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        (!$past(rst) && ($past(q_1kHz) == 16'd49999)) |-> (cd_1kHz != $past(cd_1kHz))
    );

    // The fixed divider counter must stay within its implemented count range.
    check_fixed_counter_range: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        q_1kHz <= 16'd49999
    );

endmodule

rtl:
module fsm_3bit_pattern_detection (
  input clk,
  input reset,
  input [5:0] data,
  output reg match
);

  parameter S0 = 2'b00, S1 = 2'b01, S2 = 2'b10, S3 = 2'b11;
  reg [1:0] state, next_state;

  always @(posedge clk, posedge reset) begin
    if (reset) begin
      state <= S0;
      match <= 1'b0;
    end
    else begin
      state <= next_state;
      match <= (state == S3);
    end
  end

  always @(*) begin
    case (state)
      S0: begin
        if (data[2:0] == 3'b001) next_state = S1;
        else next_state = S0;
      end
      S1: begin
        if (data[2:0] == 3'b010) next_state = S2;
        else next_state = S0;
      end
      S2: begin
        if (data[2:0] == 3'b100) next_state = S3;
        else next_state = S0;
      end
      S3: begin
        next_state = S0;
      end
    endcase
  end

endmodule

sva:
module fsm_3bit_pattern_detection_sva (
    input logic clk,
    input logic reset,
    input logic [5:0] data,
    input logic match,
    input logic [1:0] state,
    input logic [1:0] next_state
);

    localparam logic [1:0] S0 = 2'b00;
    localparam logic [1:0] S1 = 2'b01;
    localparam logic [1:0] S2 = 2'b10;
    localparam logic [1:0] S3 = 2'b11;

    // Reset forces the FSM to S0 and clears match.
    check_reset_state_and_match: assert property (
        @(posedge clk)
        reset |-> ((state == S0) && (match == 1'b0))
    );

    // In S0, only 001 on data[2:0] advances to S1.
    check_s0_next_state_decoding: assert property (
        @(posedge clk) disable iff (reset)
        (state == S0) |-> (next_state == ((data[2:0] == 3'b001) ? S1 : S0))
    );

    // In S1, only 010 on data[2:0] advances to S2.
    check_s1_next_state_decoding: assert property (
        @(posedge clk) disable iff (reset)
        (state == S1) |-> (next_state == ((data[2:0] == 3'b010) ? S2 : S0))
    );

    // In S2, only 100 on data[2:0] advances to S3.
    check_s2_next_state_decoding: assert property (
        @(posedge clk) disable iff (reset)
        (state == S2) |-> (next_state == ((data[2:0] == 3'b100) ? S3 : S0))
    );

    // In S3, the FSM always returns to S0.
    check_s3_next_state_decoding: assert property (
        @(posedge clk) disable iff (reset)
        (state == S3) |-> (next_state == S0)
    );

    // The state register loads next_state on each clock.
    check_state_register_update: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> (state == $past(next_state))
    );

    // match reflects whether the previous cycle's state was S3.
    check_match_register_update: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> (match == (($past(state) == S3) ? 1'b1 : 1'b0))
    );

    // A sampled S3 state produces S0 and match high on the next cycle.
    check_s3_returns_to_s0_with_match: assert property (
        @(posedge clk) disable iff (reset)
        (state == S3) |=> ((state == S0) && (match == 1'b1))
    );

    // A mismatch in S1 or S2 returns the FSM to S0 on the next cycle.
    check_mismatch_returns_to_s0: assert property (
        @(posedge clk) disable iff (reset)
        (((state == S1) && (data[2:0] != 3'b010)) ||
         ((state == S2) && (data[2:0] != 3'b100)))
        |=> (state == S0)
    );

    // 001,010,100 from S0 reaches S3 and then pulses match.
    check_full_pattern_detection: assert property (
        @(posedge clk) disable iff (reset)
        (
            ((state == S0) && (data[2:0] == 3'b001))
            ##1 ((state == S1) && (data[2:0] == 3'b010))
            ##1 ((state == S2) && (data[2:0] == 3'b100))
        )
        |=> (
            ((state == S3) && (match == 1'b0))
            ##1 ((state == S0) && (match == 1'b1))
        )
    );

endmodule

