module Ripple_Carry_Adder(
  input [3:0] A,
  input [3:0] B,
  input Cin,
  output [3:0] S,
  output Cout
);

  wire [3:0] sum;  //intermediate sum bits
  wire [3:0] carry;  //intermediate carry bits

  //full adder for least significant bit
  Full_Adder FA0 (
    .A(A[0]),
    .B(B[0]),
    .Cin(Cin),
    .S(sum[0]),
    .Cout(carry[0])
  );

  //full adder for second least significant bit
  Full_Adder FA1 (
    .A(A[1]),
    .B(B[1]),
    .Cin(carry[0]),
    .S(sum[1]),
    .Cout(carry[1])
  );

  //full adder for third least significant bit
  Full_Adder FA2 (
    .A(A[2]),
    .B(B[2]),
    .Cin(carry[1]),
    .S(sum[2]),
    .Cout(carry[2])
  );

  //full adder for most significant bit
  Full_Adder FA3 (
    .A(A[3]),
    .B(B[3]),
    .Cin(carry[2]),
    .S(sum[3]),
    .Cout(Cout)
  );

  assign S = sum;  //output sum bits

endmodule

//full adder module
module Full_Adder(
  input A,
  input B,
  input Cin,
  output S,
  output Cout
);

  assign S = A ^ B ^ Cin;  //XOR of inputs
  assign Cout = (A & B) | (Cin & (A ^ B));  //OR of ANDs

endmodule

sva:
module Ripple_Carry_Adder_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic Cin,
    input logic [3:0] S,
    input logic Cout
);

    // Overall output matches 4-bit addition with carry in.
    check_total_sum: assert property (
        @(posedge clk) {Cout, S} == ({1'b0, A} + {1'b0, B} + Cin)
    );

    // Bit 0 sum is the XOR of A[0], B[0], and Cin.
    check_lsb_sum: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0] ^ Cin)
    );

    // Bit 1 sum uses the carry generated by bit 0.
    check_bit1_sum: assert property (
        @(posedge clk) S[1] == (A[1] ^ B[1] ^ ((A[0] & B[0]) | (Cin & (A[0] ^ B[0]))))
    );

    // Bit 2 sum uses the carry out of the lower two bits.
    check_bit2_sum: assert property (
        @(posedge clk) S[2] == (A[2] ^ B[2] ^ (({1'b0, A[1:0]} + {1'b0, B[1:0]} + Cin) >= 3'd4))
    );

    // Bit 3 sum uses the carry out of the lower three bits.
    check_bit3_sum: assert property (
        @(posedge clk) S[3] == (A[3] ^ B[3] ^ (({1'b0, A[2:0]} + {1'b0, B[2:0]} + Cin) >= 4'd8))
    );

    // Cout is the carry out of the full 4-bit addition.
    check_cout_consistency: assert property (
        @(posedge clk) Cout == (({1'b0, A} + {1'b0, B} + Cin) >= 5'd16)
    );

    // Zero plus zero with no carry in produces zero.
    check_zero_addition: assert property (
        @(posedge clk) ((A == 4'd0) && (B == 4'd0) && (Cin == 1'b0)) |-> ({Cout, S} == 5'd0)
    );

    // Adding zero on B with no carry in passes A through.
    check_add_zero_rhs: assert property (
        @(posedge clk) ((B == 4'd0) && (Cin == 1'b0)) |-> ({Cout, S} == {1'b0, A})
    );

    // Adding zero on A with no carry in passes B through.
    check_add_zero_lhs: assert property (
        @(posedge clk) ((A == 4'd0) && (Cin == 1'b0)) |-> ({Cout, S} == {1'b0, B})
    );

    // With B at zero, Cin increments A by one.
    check_increment_with_cin: assert property (
        @(posedge clk) ((B == 4'd0) && (Cin == 1'b1)) |-> ({Cout, S} == ({1'b0, A} + 5'd1))
    );

endmodule

rtl:
module sky130_fd_sc_hd__and4 (
    X,
    A,
    B,
    C,
    D
);

    output X;
    input  A;
    input  B;
    input  C;
    input  D;

    wire and0_out_X;

    and and0 (and0_out_X, A, B, C, D     );
    buf buf0 (X         , and0_out_X     );

endmodule

sva:
module sky130_fd_sc_hd__and4_assertions (
    input logic clk,
    input logic X,
    input logic A,
    input logic B,
    input logic C,
    input logic D
);

    // X equals the AND of all four inputs.
    check_output_matches_and: assert property (
        @(posedge clk) X == (A & B & C & D)
    );

    // All four high inputs drive X high.
    check_all_high_drives_output_high: assert property (
        @(posedge clk) ((A == 1'b1) && (B == 1'b1) && (C == 1'b1) && (D == 1'b1)) |-> (X == 1'b1)
    );

    // A low forces X low.
    check_a_low_forces_output_low: assert property (
        @(posedge clk) (A == 1'b0) |-> (X == 1'b0)
    );

    // B low forces X low.
    check_b_low_forces_output_low: assert property (
        @(posedge clk) (B == 1'b0) |-> (X == 1'b0)
    );

    // C low forces X low.
    check_c_low_forces_output_low: assert property (
        @(posedge clk) (C == 1'b0) |-> (X == 1'b0)
    );

    // D low forces X low.
    check_d_low_forces_output_low: assert property (
        @(posedge clk) (D == 1'b0) |-> (X == 1'b0)
    );

    // A high X requires all four inputs high.
    check_output_high_requires_all_inputs_high: assert property (
        @(posedge clk) (X == 1'b1) |-> ((A == 1'b1) && (B == 1'b1) && (C == 1'b1) && (D == 1'b1))
    );

endmodule

rtl:
module sky130_fd_sc_lp__nor4bb (
    Y  ,
    A  ,
    B  ,
    C_N,
    D_N
);

    output Y  ;
    input  A  ;
    input  B  ;
    input  C_N;
    input  D_N;

    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    wire nor0_out  ;
    wire and0_out_Y;

    nor nor0 (nor0_out  , A, B              );
    and and0 (and0_out_Y, nor0_out, C_N, D_N);
    buf buf0 (Y         , and0_out_Y        );

endmodule

sva:
module sky130_fd_sc_lp__nor4bb_sva (
    input logic clk,
    input logic Y,
    input logic A,
    input logic B,
    input logic C_N,
    input logic D_N
);

    // Y matches the implemented combinational function.
    check_output_function: assert property (
        @(posedge clk) Y == ((~(A | B)) & C_N & D_N)
    );

    // A high forces the NOR stage low, so Y must be low.
    check_a_high_forces_y_low: assert property (
        @(posedge clk) A |-> !Y
    );

    // B high forces the NOR stage low, so Y must be low.
    check_b_high_forces_y_low: assert property (
        @(posedge clk) B |-> !Y
    );

    // C_N low blocks the AND stage, so Y must be low.
    check_cn_low_forces_y_low: assert property (
        @(posedge clk) !C_N |-> !Y
    );

    // D_N low blocks the AND stage, so Y must be low.
    check_dn_low_forces_y_low: assert property (
        @(posedge clk) !D_N |-> !Y
    );

    // All enabling inputs produce a high output.
    check_enabling_inputs_drive_y_high: assert property (
        @(posedge clk) (!A && !B && C_N && D_N) |-> Y
    );

    // A high output implies the required input combination.
    check_y_high_implies_input_combination: assert property (
        @(posedge clk) Y |-> (!A && !B && C_N && D_N)
    );

endmodule

module sync_counter_sva(
    input logic clk,
    input logic reset_n,
    input logic enable,
    input logic [3:0] count
);

    // Active-low reset clears the counter to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) !reset_n |-> (count == 4'b0000)
    );

    // When enabled, the counter increments by one on the next clock.
    check_count_increments_when_enabled: assert property (
        @(posedge clk) disable iff (!reset_n)
        enable |=> (count == ($past(count) + 4'd1))
    );

    // When not enabled, the counter holds its value.
    check_count_holds_when_disabled: assert property (
        @(posedge clk) disable iff (!reset_n)
        !enable |=> (count == $past(count))
    );

    // When enabled at its maximum value, the counter wraps to zero.
    check_count_wraps_from_max: assert property (
        @(posedge clk) disable iff (!reset_n)
        (enable && (count == 4'hF)) |=> (count == 4'h0)
    );

endmodule

rtl:
module sky130_fd_sc_lp__o21a (
    X ,
    A1,
    A2,
    B1
);

    output X ;
    input  A1;
    input  A2;
    input  B1;

    wire or0_out   ;
    wire and0_out_X;

    or  or0  (or0_out   , A2, A1         );
    and and0 (and0_out_X, or0_out, B1    );
    buf buf0 (X         , and0_out_X     );

endmodule

sva:
module sky130_fd_sc_lp__o21a_sva (
    input logic clk,
    input logic X,
    input logic A1,
    input logic A2,
    input logic B1
);

    // X implements (A1 | A2) & B1.
    check_function_equivalence: assert property (
        @(posedge clk) X === ((A1 | A2) & B1)
    );

    // B1 low forces X low.
    check_b1_low_forces_x_low: assert property (
        @(posedge clk) (B1 == 1'b0) |-> (X == 1'b0)
    );

    // Both OR inputs low force X low.
    check_or_inputs_low_force_x_low: assert property (
        @(posedge clk) ((A1 == 1'b0) && (A2 == 1'b0)) |-> (X == 1'b0)
    );

    // A1 high with B1 high drives X high.
    check_a1_and_b1_drive_x_high: assert property (
        @(posedge clk) ((A1 == 1'b1) && (B1 == 1'b1)) |-> (X == 1'b1)
    );

    // A2 high with B1 high drives X high.
    check_a2_and_b1_drive_x_high: assert property (
        @(posedge clk) ((A2 == 1'b1) && (B1 == 1'b1)) |-> (X == 1'b1)
    );

    // X high requires B1 and at least one OR input high.
    check_x_high_requires_valid_inputs: assert property (
        @(posedge clk) (X == 1'b1) |-> ((B1 == 1'b1) && ((A1 == 1'b1) || (A2 == 1'b1)))
    );

endmodule

