    );

endmodule

rtl:
module mux4to1 (
  input [3:0] in,
  input [1:0] sel,
  output reg out
);

  always @(*) begin
    case(sel)
      2'b00: out = in[0];
      2'b01: out = in[1];
      2'b10: out = in[2];
      2'b11: out = in[3];
      default: out = 1'b0;
    endcase;
  end

endmodule

sva:
module mux4to1_sva (
    input logic       clk,
    input logic [3:0] in,
    input logic [1:0] sel,
    input logic       out
);

    // sel=00 routes in[0] to out.
    check_sel_00_routes_in0: assert property (
        @(posedge clk) (sel === 2'b00) |-> (out === in[0])
    );

    // sel=01 routes in[1] to out.
    check_sel_01_routes_in1: assert property (
        @(posedge clk) (sel === 2'b01) |-> (out === in[1])
    );

    // sel=10 routes in[2] to out.
    check_sel_10_routes_in2: assert property (
        @(posedge clk) (sel === 2'b10) |-> (out === in[2])
    );

    // sel=11 routes in[3] to out.
    check_sel_11_routes_in3: assert property (
        @(posedge clk) (sel === 2'b11) |-> (out === in[3])
    );

    // Any non-matching select value drives the default output of 0.
    check_default_out_zero: assert property (
        @(posedge clk)
        !((sel === 2'b00) || (sel === 2'b01) || (sel === 2'b10) || (sel === 2'b11))
        |-> (out === 1'b0)
    );

    // out always matches the mux case selection.
    check_full_mux_behavior: assert property (
        @(posedge clk)
        out === ((sel === 2'b00) ? in[0] :
                 (sel === 2'b01) ? in[1] :
                 (sel === 2'b10) ? in[2] :
                 (sel === 2'b11) ? in[3] :
                                   1'b0)
    );

endmodule

module internal_bank_address_sva (
    input logic        lio_buscfg_brstlen2_sr,
    input logic        lio_buscfg_brstlen4_sr,
    input logic [7:0]  m_cdq_haddr_sr,
    input logic [3:0]  ibnk_sel_s
);

    // Upper output bits are always zero because the RTL assigns a 2-bit slice to a 4-bit output.
    check_upper_bits_zero: assert property (
        @($global_clock) ibnk_sel_s[3:2] === 2'b00
    );

    // In 2-burst mode, the bank select comes from address bits [1:0].
    check_2burst_decode: assert property (
        @($global_clock)
        ({lio_buscfg_brstlen4_sr, lio_buscfg_brstlen2_sr} === 2'b01)
        |-> (ibnk_sel_s === {2'b00, m_cdq_haddr_sr[1:0]})
    );

    // In 4-burst mode, the bank select comes from address bits [2:1].
    check_4burst_decode: assert property (
        @($global_clock)
        ({lio_buscfg_brstlen4_sr, lio_buscfg_brstlen2_sr} === 2'b10)
        |-> (ibnk_sel_s === {2'b00, m_cdq_haddr_sr[2:1]})
    );

    // When both burst-length flags are low, the default decode uses address bits [2:1].
    check_default_decode_00: assert property (
        @($global_clock)
        ({lio_buscfg_brstlen4_sr, lio_buscfg_brstlen2_sr} === 2'b00)
        |-> (ibnk_sel_s === {2'b00, m_cdq_haddr_sr[2:1]})
    );

    // When both burst-length flags are high, the default decode uses address bits [2:1].
    check_default_decode_11: assert property (
        @($global_clock)
        ({lio_buscfg_brstlen4_sr, lio_buscfg_brstlen2_sr} === 2'b11)
        |-> (ibnk_sel_s === {2'b00, m_cdq_haddr_sr[2:1]})
    );

endmodule

module alu_sva(
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [2:0] Op,
    input logic [3:0] result
);

    // Addition opcode produces A + B.
    check_addition_result: assert property (
        @(posedge clk)
        (Op == 3'b000) |-> (result == (A + B))
    );

    // Subtraction opcode produces A - B.
    check_subtraction_result: assert property (
        @(posedge clk)
        (Op == 3'b001) |-> (result == (A - B))
    );

    // AND opcode produces A & B.
    check_and_result: assert property (
        @(posedge clk)
        (Op == 3'b010) |-> (result == (A & B))
    );

    // OR opcode produces A | B.
    check_or_result: assert property (
        @(posedge clk)
        (Op == 3'b011) |-> (result == (A | B))
    );

    // XOR opcode produces A ^ B.
    check_xor_result: assert property (
        @(posedge clk)
        (Op == 3'b100) |-> (result == (A ^ B))
    );

    // Shift-left opcode produces A shifted left by one.
    check_shift_left_result: assert property (
        @(posedge clk)
        (Op == 3'b101) |-> (result == (A << 1))
    );

    // Shift-right opcode produces A shifted right by one.
    check_shift_right_result: assert property (
        @(posedge clk)
        (Op == 3'b110) |-> (result == (A >> 1))
    );

    // Increment opcode produces A + 1.
    check_increment_result: assert property (
        @(posedge clk)
        (Op == 3'b111) |-> (result == (A + 1))
    );

    // Stable inputs keep the combinational result stable.
    check_result_stable_when_inputs_stable: assert property (
        @(posedge clk)
        $stable({A, B, Op}) |-> $stable(result)
    );

endmodule

rtl:
module OA22X1 (input IN1, IN2, IN3, IN4, output Q, input VDD, VSS);
    wire and_out, or_out;

    assign and_out = IN3 & IN4;
    assign or_out = IN3 | IN4;

    assign Q = (IN1 & ~IN2) ? IN3 :
               (~IN1 & IN2) ? IN4 :
               (IN1 & IN2) ? and_out :
               or_out;
endmodule

sva:
module OA22X1_sva (
    input logic IN1,
    input logic IN2,
    input logic IN3,
    input logic IN4,
    input logic Q,
    input logic VDD,
    input logic VSS
);

    // Q matches the implemented conditional combinational function.
    check_output_function: assert property (
        @($global_clock)
        Q === (
            (IN1 & ~IN2) ? IN3 :
            ((~IN1 & IN2) ? IN4 :
            ((IN1 & IN2) ? (IN3 & IN4) :
                           (IN3 | IN4)))
        )
    );

    // IN1=1 and IN2=0 selects IN3.
    check_select_in3: assert property (
        @($global_clock)
        ((IN1 === 1'b1) && (IN2 === 1'b0)) |-> (Q === IN3)
    );

    // IN1=0 and IN2=1 selects IN4.
    check_select_in4: assert property (
        @($global_clock)
        ((IN1 === 1'b0) && (IN2 === 1'b1)) |-> (Q === IN4)
    );

    // IN1=1 and IN2=1 selects IN3 & IN4.
    check_and_mode: assert property (
        @($global_clock)
        ((IN1 === 1'b1) && (IN2 === 1'b1)) |-> (Q === (IN3 & IN4))
    );

    // IN1=0 and IN2=0 selects IN3 | IN4.
    check_or_mode: assert property (
        @($global_clock)
        ((IN1 === 1'b0) && (IN2 === 1'b0)) |-> (Q === (IN3 | IN4))
    );

    // Both data inputs low force Q low.
    check_both_data_low_force_zero: assert property (
        @($global_clock)
        ((IN3 === 1'b0) && (IN4 === 1'b0)) |-> (Q === 1'b0)
    );

    // Both data inputs high force Q high.
    check_both_data_high_force_one: assert property (
        @($global_clock)
        ((IN3 === 1'b1) && (IN4 === 1'b1)) |-> (Q === 1'b1)
    );

    // Stable functional inputs keep Q stable.
    check_output_stable_when_inputs_stable: assert property (
        @($global_clock)
        ($stable(IN1) && $stable(IN2) && $stable(IN3) && $stable(IN4)) |-> $stable(Q)
    );

    // Supply pin changes do not affect Q when functional inputs are unchanged.
    check_supply_independence: assert property (
        @($global_clock)
        ($stable(IN1) && $stable(IN2) && $stable(IN3) && $stable(IN4) &&
         (!$stable(VDD) || !$stable(VSS))) |-> $stable(Q)
    );

endmodule

rtl:
module comparator_4bit(
    input [3:0] A,
    input [3:0] B,
    output reg [1:0] result
);

    always @(*) begin
        if (A[3] == 1 && B[3] == 0) begin
            result = 2'b01;
        end else if (A[3] == 0 && B[3] == 1) begin
            result = 2'b10;
        end else begin
            if (A[3:0] > B[3:0]) begin
                result = 2'b01;
            end else if (A[3:0] < B[3:0]) begin
                result = 2'b10;
            end else begin
                result = 2'b00;
            end
        end
    end

endmodule

sva:
module comparator_4bit_sva (
    input logic       clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [1:0] result
);

    // Result only uses the three encodings implemented in the RTL.
    check_result_encoding: assert property (
        @(posedge clk)
        (result == 2'b00) || (result == 2'b01) || (result == 2'b10)
    );

    // If A has MSB set and B does not, result indicates A > B.
    check_msb_a_high_b_low: assert property (
        @(posedge clk)
        ((A[3] == 1'b1) && (B[3] == 1'b0)) |-> (result == 2'b01)
    );

    // If B has MSB set and A does not, result indicates A < B.
    check_msb_a_low_b_high: assert property (
        @(posedge clk)
        ((A[3] == 1'b0) && (B[3] == 1'b1)) |-> (result == 2'b10)
    );

    // When A is greater than B, result must indicate greater-than.
    check_a_greater_than_b_maps_to_01: assert property (
        @(posedge clk)
        (A > B) |-> (result == 2'b01)
    );

    // When A is less than B, result must indicate less-than.
    check_a_less_than_b_maps_to_10: assert property (
        @(posedge clk)
        (A < B) |-> (result == 2'b10)
    );

    // When A equals B, result must indicate equality.
    check_a_equal_b_maps_to_00: assert property (
        @(posedge clk)
        (A == B) |-> (result == 2'b00)
    );

    // A greater-than result must correspond to A > B.
    check_result_01_implies_a_greater_than_b: assert property (
        @(posedge clk)
        (result == 2'b01) |-> (A > B)
    );

    // A less-than result must correspond to A < B.
    check_result_10_implies_a_less_than_b: assert property (
        @(posedge clk)
        (result == 2'b10) |-> (A < B)
    );

    // An equality result must correspond to A == B.
    check_result_00_implies_a_equal_b: assert property (
        @(posedge clk)
        (result == 2'b00) |-> (A == B)
    );

endmodule

rtl:
module sky130_fd_sc_lp__fa (
    COUT,
    SUM ,
    A   ,
    B   ,
    CIN
);

    output COUT;
    output SUM ;
    input  A   ;
    input  B   ;
    input  CIN ;

    wire or0_out     ;
    wire and0_out    ;
    wire and1_out    ;
    wire and2_out    ;
    wire nor0_out    ;
    wire nor1_out    ;
    wire or1_out_COUT;
    wire or2_out_SUM ;

    or  or0  (or0_out     , CIN, B            );
    and and0 (and0_out    , or0_out, A        );
    and and1 (and1_out    , B, CIN            );
    or  or1  (or1_out_COUT, and1_out, and0_out);
    buf buf0 (COUT        , or1_out_COUT      );
    and and2 (and2_out    , CIN, A, B         );
    nor nor0 (nor0_out    , A, or0_out        );
    nor nor1 (nor1_out    , nor0_out, COUT    );
    or  or2  (or2_out_SUM , nor1_out, and2_out);
    buf buf1 (SUM         , or2_out_SUM       );

endmodule

sva:
module sky130_fd_sc_lp__fa_sva (
    input logic clk,
    input logic COUT,
    input logic SUM,
    input logic A,
    input logic B,
    input logic CIN
);

    // Combined outputs match 1-bit addition of A, B, and CIN.
    check_full_adder_value: assert property (
        @(posedge clk) ({COUT, SUM} == ({1'b0, A} + {1'b0, B} + {1'b0, CIN}))
    );

    // Carry-out is the majority function of the three inputs.
    check_carry_majority: assert property (
        @(posedge clk) (COUT == ((A & B) | (A & CIN) | (B & CIN)))
    );

    // Sum is the odd-parity function of the three inputs.
    check_sum_odd_parity: assert property (
        @(posedge clk) (SUM == (A ^ B ^ CIN))
    );

    // All-zero inputs produce zero outputs.
    check_zero_inputs: assert property (
        @(posedge clk) ((!A && !B && !CIN) |-> ({COUT, SUM} == 2'b00))
    );

    // Exactly one asserted input produces sum without carry.
    check_single_high_input: assert property (
        @(posedge clk) ((({1'b0, A} + {1'b0, B} + {1'b0, CIN}) == 2'd1) |-> ({COUT, SUM} == 2'b01))
    );

    // Exactly two asserted inputs produce carry without sum.
    check_two_high_inputs: assert property (
        @(posedge clk) ((({1'b0, A} + {1'b0, B} + {1'b0, CIN}) == 2'd2) |-> ({COUT, SUM} == 2'b10))
    );

    // All-one inputs produce both carry and sum.
    check_all_high_inputs: assert property (
        @(posedge clk) ((A & B & CIN) |-> ({COUT, SUM} == 2'b11))
    );

endmodule

rtl:
module compare_4 (
  ram_empty_fb_i_reg,
  v1_reg,
  rd_en,
  out,
  comp1
);

  output ram_empty_fb_i_reg;
  input [4:0] v1_reg;
  input rd_en;
  input out;
  input comp1;

  wire [3:0] carrynet;
  wire comp0;
  wire ram_empty_fb_i_reg;
  wire rd_en;
  wire [4:0] v1_reg;

  // Carry Look-Ahead Adder
  assign carrynet = {1'b0, 1'b0, 1'b0, 1'b0} + v1_reg[3:0];

  // 4-input LUT
  assign ram_empty_fb_i_reg = !(comp0 & rd_en & out & comp1);
  assign comp0 = carrynet[3] | carrynet[2] | carrynet[1] | carrynet[0];

endmodule

sva:
module compare_4_sva (
    input logic        ram_empty_fb_i_reg,
    input logic [4:0]  v1_reg,
    input logic        rd_en,
    input logic        out,
    input logic        comp1
);

    // Output matches the implemented combinational equation.
    check_output_equation: assert property (
        @($global_clock)
        ram_empty_fb_i_reg == !((|v1_reg[3:0]) & rd_en & out & comp1)
    );

    // A zero low nibble forces the output HIGH.
    check_zero_low_nibble_forces_high: assert property (
        @($global_clock)
        (v1_reg[3:0] == 4'b0000) |-> ram_empty_fb_i_reg
    );

    // Any LOW control input forces the output HIGH.
    check_low_control_forces_high: assert property (
        @($global_clock)
        (!rd_en || !out || !comp1) |-> ram_empty_fb_i_reg
    );

    // All controls HIGH with a nonzero low nibble force the output LOW.
    check_all_inputs_active_force_low: assert property (
        @($global_clock)
        (rd_en && out && comp1 && (v1_reg[3:0] != 4'b0000)) |-> !ram_empty_fb_i_reg
    );

    // A LOW output can only occur with all controls HIGH and a nonzero low nibble.
    check_low_output_has_required_conditions: assert property (
        @($global_clock)
        !ram_empty_fb_i_reg |-> (rd_en && out && comp1 && (v1_reg[3:0] != 4'b0000))
    );

    // Changing only v1_reg[4] does not affect the output.
    check_bit4_is_unused: assert property (
        @($global_clock)
        $changed(v1_reg[4]) &&
        $stable(v1_reg[3:0]) &&
        $stable(rd_en) &&
        $stable(out) &&
        $stable(comp1)
        |-> $stable(ram_empty_fb_i_reg)
    );

endmodule

rtl:
module counter (
  // inputs:
  clk,
  reset,

  // outputs:
  count
);

  // inputs
  input clk;
  input reset;

  // outputs
  output reg [3:0] count;

  // counter logic
  always @(posedge clk, negedge reset) begin
    if (!reset) begin
      count <= 4'b0;
    end else begin
      count <= count + 1;
    end
  end

endmodule

sva:
module counter_assertions (
    input logic       clk,
    input logic       reset,
    input logic [3:0] count
);

    // A sampled reset cycle forces count to zero by the next clock.
    check_count_zero_after_sampled_reset: assert property (
        @(posedge clk) disable iff ($initstate)
        $past(!reset) |-> (count == 4'd0)
    );

    // On consecutive active samples, count either increments or is zero after an async reset pulse.
    check_count_progresses_or_resets: assert property (
        @(posedge clk) disable iff (!reset || $initstate)
        $past(reset) |-> ((count == ($past(count) + 4'd1)) || (count == 4'd0))
    );

    // On consecutive active samples, 4'hF wraps back to 4'h0.
    check_wrap_from_max_when_running: assert property (
        @(posedge clk) disable iff (!reset || $initstate)
        ($past(reset) && ($past(count) == 4'hF)) |-> (count == 4'd0)
    );

endmodule

rtl:
module shift_register (
    input serial_in,
    input shift,
    output reg [3:0] parallel_out
);

    always @ (posedge shift) begin
        parallel_out <= {parallel_out[2:0], serial_in};
    end

endmodule

sva:
module shift_register_sva (
    input  logic       serial_in,
    input  logic       shift,
    input  logic [3:0] parallel_out
);

    // The register shifts prior contents and loads the prior serial input into bit 0.
    check_full_shift_update: assert property (
        @(posedge shift)
        1'b1 |=> parallel_out == {$past(parallel_out[2:0]), $past(serial_in)}
    );

    // Bit 3 takes the previous value of bit 2.
    check_bit3_shift: assert property (
        @(posedge shift)
        1'b1 |=> parallel_out[3] == $past(parallel_out[2])
    );

    // Bit 2 takes the previous value of bit 1.
    check_bit2_shift: assert property (
        @(posedge shift)
        1'b1 |=> parallel_out[2] == $past(parallel_out[1])
    );

    // Bit 1 takes the previous value of bit 0.
    check_bit1_shift: assert property (
        @(posedge shift)
        1'b1 |=> parallel_out[1] == $past(parallel_out[0])
    );

    // Bit 0 loads the previous serial input.
    check_bit0_load: assert property (
        @(posedge shift)
        1'b1 |=> parallel_out[0] == $past(serial_in)
    );

    // After four shift edges, the register reflects the last four serial inputs.
    check_last_four_serial_inputs: assert property (
        @(posedge shift)
        1'b1 ##1 1'b1 ##1 1'b1 ##1 1'b1 |=> parallel_out == {
            $past(serial_in,4),
            $past(serial_in,3),
            $past(serial_in,2),
            $past(serial_in,1)
        }
    );

endmodule

rtl:
module counter (
  input clk,
  input rst,
  input [7:0] max_count,
  output reg [7:0] count
);

  always @(posedge clk or posedge rst) begin
    if (rst) begin
      count <= 0;
    end else if (count == max_count) begin
      count <= 0;
    end else begin
      count <= count + 1;
    end
  end

endmodule

sva:
module counter_sva (
    input logic       clk,
    input logic       rst,
    input logic [7:0] max_count,
    input logic [7:0] count
);

    // A sampled reset drives the counter to zero by the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |=> (count == 8'd0)
    );

    // A reset held across clocks keeps the counter at zero.
    check_reset_holds_zero: assert property (
        @(posedge clk) disable iff ($initstate) (rst && $past(rst)) |-> (count == 8'd0)
    );

    // When count matches max_count, the counter wraps to zero.
    check_wrap_on_max: assert property (
        @(posedge clk) disable iff (rst) (count == max_count) |=> (count == 8'd0)
    );

    // When count does not match max_count, the counter increments by one.
    check_increment_when_not_max: assert property (
        @(posedge clk) disable iff (rst) (count != max_count) |=> (count == ($past(count) + 8'd1))
    );

    // From zero with max_count at zero, the counter remains at zero.
    check_zero_max_stays_zero: assert property (
        @(posedge clk) disable iff (rst) (count == 8'd0 && max_count == 8'd0) |=> (count == 8'd0)
    );

    // From zero with a nonzero max_count, the counter advances to one.
    check_zero_count_advances_to_one: assert property (
        @(posedge clk) disable iff (rst) (count == 8'd0 && max_count != 8'd0) |=> (count == 8'd1)
    );

endmodule

rtl:
module RegisterAdd_6
   (add_overflow_flag,
    E,
    O,
    CLK,
    AR);
  output add_overflow_flag;
  input [0:0]E;
  input [0:0]O;
  input CLK;
  input [0:0]AR;

  wire [0:0]AR;
  wire CLK;
  wire [0:0]E;
  wire [0:0]O;
  wire add_overflow_flag;

  reg [0:0] Q_reg;
  always @(posedge CLK or negedge AR)
  begin
    if (!AR)
      Q_reg <= 1'b0;
    else if (E)
      Q_reg <= O;
  end

  assign add_overflow_flag = (E & O & Q_reg);

endmodule

sva:
module RegisterAdd_6_sva (
    input logic add_overflow_flag,
    input logic [0:0] E,
    input logic [0:0] O,
    input logic CLK,
    input logic [0:0] AR
);

    // Overflow can only be high when both current input bits are high.
    check_overflow_requires_high_inputs: assert property (
        @(posedge CLK) disable iff (!AR[0])
        add_overflow_flag |-> ((E[0] == 1'b1) && (O[0] == 1'b1))
    );

    // If either current input bit is low, the overflow output must be low.
    check_low_input_blocks_overflow: assert property (
        @(posedge CLK) disable iff (!AR[0])
        ((E[0] == 1'b0) || (O[0] == 1'b0)) |-> (add_overflow_flag == 1'b0)
    );

    // While reset is asserted, the output must stay low.
    check_reset_forces_output_low: assert property (
        @(posedge CLK)
        (AR[0] == 1'b0) |-> (add_overflow_flag == 1'b0)
    );

    // A sampled reset cycle clears the registered contribution by the next clock.
    check_reset_clears_output_next_cycle: assert property (
        @(posedge CLK)
        (AR[0] == 1'b0) |=> (add_overflow_flag == 1'b0)
    );

    // Loading a zero into the register forces the next sampled output low.
    check_load_zero_clears_output_next_cycle: assert property (
        @(posedge CLK) disable iff (!AR[0])
        ((E[0] == 1'b1) && (O[0] == 1'b0)) |=> (add_overflow_flag == 1'b0)
    );

endmodule

rtl:
module And_Module (
    input [7:0] a,
    input [7:0] b,
    output reg [7:0] out,
    output reg out_valid,
    input clk
);

    always @(posedge clk) begin
        out <= a & b;
        out_valid <= 1'b1;
    end

endmodule

sva:
module And_Module_sva (
    input logic [7:0] a,
    input logic [7:0] b,
    input logic [7:0] out,
    input logic out_valid,
    input logic clk
);

    // out captures the bitwise AND of the prior-cycle inputs.
    check_out_registered_and: assert property (
        @(posedge clk) 1'b1 |=> (out == ($past(a) & $past(b)))
    );

    // out_valid is driven high after each clock edge.
    check_out_valid_asserted: assert property (
        @(posedge clk) 1'b1 |=> (out_valid == 1'b1)
    );

    // Once out_valid is high, it remains high on later clocks.
    check_out_valid_sticky_high: assert property (
        @(posedge clk) out_valid |=> out_valid
    );

    // Stable inputs across cycles keep the registered output stable.
    check_out_stable_when_inputs_stable: assert property (
        @(posedge clk) ($stable(a) && $stable(b)) |=> $stable(out)
    );

    // A zero on either operand produces a zero output on the next cycle.
    check_zero_operand_forces_zero: assert property (
        @(posedge clk) ((a == 8'h00) || (b == 8'h00)) |=> (out == 8'h00)
    );

    // All ones on a passes b through to the next-cycle output.
    check_all_ones_a_passes_b: assert property (
        @(posedge clk) (a == 8'hFF) |=> (out == $past(b))
    );

    // All ones on b passes a through to the next-cycle output.
    check_all_ones_b_passes_a: assert property (
        @(posedge clk) (b == 8'hFF) |=> (out == $past(a))
    );

endmodule

rtl:
module final_module (
    input [1:0] comparator_output,
    input [2:0] up_down_output,
    input [3:0] A,
    input [3:0] B,
    output [4:0] final_output
);

reg [4:0] final_output_internal;

assign final_output = final_output_internal;

always @(*) begin
  case (comparator_output)
    2'b01: final_output_internal = up_down_output + A;
    2'b10: final_output_internal = up_down_output + B;
    default: final_output_internal = up_down_output;
  endcase
end

endmodule

module top_module (
    input clk,
    input reset,
    input [3:0] A,
    input [3:0] B,
    input up_down,
    output [4:0] final_output
);

wire [1:0] comparator_output;
wire [2:0] up_down_output;

comparator comparator_inst (
    .A(A),
    .B(B),
    .OUT(comparator_output)
);

up_down_counter up_down_counter_inst (
    .clk(clk),
    .reset(reset),
    .up_down(up_down),
    .count(up_down_output)
);

final_module final_module_inst (
    .comparator_output(comparator_output),
    .up_down_output(up_down_output),
    .A(A),
    .B(B),
    .final_output(final_output)
);

endmodule

module comparator (
    input [3:0] A,
    input [3:0] B,
    output reg [1:0] OUT
);

always @(*) begin
    if (A > B) OUT = 2'b01;
    else if (A < B) OUT = 2'b10;
    else OUT = 2'b00;
end

endmodule

module up_down_counter (
    input clk,
    input reset,
    input up_down,
    output reg [2:0] count
);

always @(posedge clk, posedge reset) begin
    if (reset) count <= 3'b000;
    else begin
        if (up_down) count <= count + 1;
        else count <= count - 1;
    end
end

endmodule

sva:
module top_module_assertions (
    input logic clk,
    input logic reset,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic up_down,
    input logic [4:0] final_output,
    input logic [1:0] comparator_output,
    input logic [2:0] up_down_output
);

    // A sampled reset must clear the counter by the next clock.
    check_counter_clears_after_reset: assert property (
        @(posedge clk) disable iff ($initstate)
        reset |=> (up_down_output == 3'b000)
    );

    // An up command increments the counter unless async reset forced it to zero.
    check_counter_counts_up: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        up_down |=> ((up_down_output == ($past(up_down_output) + 3'b001)) ||
                     (up_down_output == 3'b000))
    );

    // A down command decrements the counter unless async reset forced it to zero.
    check_counter_counts_down: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        !up_down |=> ((up_down_output == ($past(up_down_output) - 3'b001)) ||
                      (up_down_output == 3'b000))
    );

    // A greater-than comparison produces code 01.
    check_comparator_gt_code: assert property (
        @(posedge clk) disable iff (reset)
        (A > B) |-> (comparator_output == 2'b01)
    );

    // A less-than comparison produces code 10.
    check_comparator_lt_code: assert property (
        @(posedge clk) disable iff (reset)
        (A < B) |-> (comparator_output == 2'b10)
    );

    // Equal inputs produce code 00.
    check_comparator_eq_code: assert property (
        @(posedge clk) disable iff (reset)
        (A == B) |-> (comparator_output == 2'b00)
    );

    // Comparator code 01 selects A for the final sum.
    check_final_selects_a: assert property (
        @(posedge clk) disable iff (reset)
        (comparator_output == 2'b01) |-> (final_output == (up_down_output + A))
    );

    // Comparator code 10 selects B for the final sum.
    check_final_selects_b: assert property (
        @(posedge clk) disable iff (reset)
        (comparator_output == 2'b10) |-> (final_output == (up_down_output + B))
    );

    // All other comparator codes pass the counter value through.
    check_final_default_path: assert property (
        @(posedge clk) disable iff (reset)
        ((comparator_output != 2'b01) && (comparator_output != 2'b10)) |-> (final_output == up_down_output)
    );

    // When A is greater than B, the top-level output adds A.
    check_top_output_when_a_gt_b: assert property (
        @(posedge clk) disable iff (reset)
        (A > B) |-> (final_output == (up_down_output + A))
    );

    // When A is less than B, the top-level output adds B.
    check_top_output_when_a_lt_b: assert property (
        @(posedge clk) disable iff (reset)
        (A < B) |-> (final_output == (up_down_output + B))
    );

    // When A equals B, the top-level output passes the counter through.
    check_top_output_when_a_eq_b: assert property (
        @(posedge clk) disable iff (reset)
        (A == B) |-> (final_output == up_down_output)
    );

endmodule

rtl:
module binary_to_gray (
  input [2:0] in,
  output reg [2:0] out
);

  always @* begin
    case(in)
      3'b000: out = 3'b000;
      3'b001: out = 3'b001;
      3'b010: out = 3'b011;
      3'b011: out = 3'b010;
      3'b100: out = 3'b110;
      3'b101: out = 3'b111;
      3'b110: out = 3'b101;
      3'b111: out = 3'b100;
    endcase
  end

endmodule

sva:
module binary_to_gray_sva (
    input logic clk,
    input logic [2:0] in,
    input logic [2:0] out
);

    // 000 maps to 000.
    check_map_000: assert property (
        @(posedge clk) (in == 3'b000) |-> (out == 3'b000)
    );

    // 001 maps to 001.
    check_map_001: assert property (
        @(posedge clk) (in == 3'b001) |-> (out == 3'b001)
    );

    // 010 maps to 011.
    check_map_010: assert property (
        @(posedge clk) (in == 3'b010) |-> (out == 3'b011)
    );

    // 011 maps to 010.
    check_map_011: assert property (
        @(posedge clk) (in == 3'b011) |-> (out == 3'b010)
    );

    // 100 maps to 110.
    check_map_100: assert property (
        @(posedge clk) (in == 3'b100) |-> (out == 3'b110)
    );

    // 101 maps to 111.
    check_map_101: assert property (
        @(posedge clk) (in == 3'b101) |-> (out == 3'b111)
    );

    // 110 maps to 101.
    check_map_110: assert property (
        @(posedge clk) (in == 3'b110) |-> (out == 3'b101)
    );

    // 111 maps to 100.
    check_map_111: assert property (
        @(posedge clk) (in == 3'b111) |-> (out == 3'b100)
    );

    // Output matches the 3-bit binary-to-Gray formula.
    check_gray_formula: assert property (
        @(posedge clk) out == {in[2], (in[2] ^ in[1]), (in[1] ^ in[0])}
    );

endmodule

rtl:
module bin2gray(input [3:0] B, output reg [3:0] G);

always @ (B) begin
    G[3] = B[3];
    G[2] = B[3] ^ B[2];
    G[1] = B[2] ^ B[1];
    G[0] = B[1] ^ B[0];
end

endmodule

sva:
module bin2gray_sva (
    input logic [3:0] B,
    input logic [3:0] G
);

    // No RTL clock or reset; sample combinational behavior on the formal global clock.

    // G[3] must copy the MSB of B.
    check_g3_msb_copy: assert property (
        @($global_clock) G[3] == B[3]
    );

    // G[2] must be B[3] XOR B[2].
    check_g2_xor_mapping: assert property (
        @($global_clock) G[2] == (B[3] ^ B[2])
    );

    // G[1] must be B[2] XOR B[1].
    check_g1_xor_mapping: assert property (
        @($global_clock) G[1] == (B[2] ^ B[1])
    );

    // G[0] must be B[1] XOR B[0].
    check_g0_xor_mapping: assert property (
        @($global_clock) G[0] == (B[1] ^ B[0])
    );

    // The full Gray code output must match the binary input encoding.
    check_full_gray_encoding: assert property (
        @($global_clock) G == {B[3], (B[3] ^ B[2]), (B[2] ^ B[1]), (B[1] ^ B[0])}
    );

endmodule

module dff_async_reset_sva (
    input logic clk,
    input logic d,
    input logic rst,
    input logic q
);

    // Low rst implies low q at sampled clock edges.
    check_reset_low_implies_q_low: assert property (
        @(posedge clk)
        1'b1 |=> ((rst == 1'b1) || (q == 1'b0))
    );

    // A sampled low rst leaves q low on the next clock.
    check_reset_keeps_q_low_next_clock: assert property (
        @(posedge clk)
        (rst == 1'b0) |=> (q == 1'b0)
    );

    // With reset deasserted, sampled d=0 is captured by the next clock.
    check_capture_zero: assert property (
        @(posedge clk) disable iff (!rst)
        (d == 1'b0) |=> (q == 1'b0)
    );

    // Whenever q is high, the previous sampled d must have been high.
    check_q_high_has_prior_high_d: assert property (
        @(posedge clk) disable iff (!rst)
        1'b1 |=> ((q == 1'b0) || ($past(d) == 1'b1))
    );

endmodule

rtl:
module mux2x4(data0, data1, data2, data3, selectInput, out);

    output reg [1:0] out;
    input [1:0] data0, data1, data2, data3;
    input [1:0] selectInput;

    always @* begin
        case (selectInput)
            2'b00: out = data0;
            2'b01: out = data1;
            2'b10: out = data2;
            2'b11: out = data3;
            default: out = 2'b00;
        endcase
    end

