sva:
module mux2x4_assertions (
    input logic clk,
    input logic [1:0] data0,
    input logic [1:0] data1,
    input logic [1:0] data2,
    input logic [1:0] data3,
    input logic [1:0] selectInput,
    input logic [1:0] out
);

    // When selectInput is 00, out must equal data0.
    check_select_00: assert property (
        @(posedge clk) (selectInput === 2'b00) |-> (out === data0)
    );

    // When selectInput is 01, out must equal data1.
    check_select_01: assert property (
        @(posedge clk) (selectInput === 2'b01) |-> (out === data1)
    );

    // When selectInput is 10, out must equal data2.
    check_select_10: assert property (
        @(posedge clk) (selectInput === 2'b10) |-> (out === data2)
    );

    // When selectInput is 11, out must equal data3.
    check_select_11: assert property (
        @(posedge clk) (selectInput === 2'b11) |-> (out === data3)
    );

    // When selectInput contains X or Z, out must take the default value 00.
    check_default_on_unknown_select: assert property (
        @(posedge clk) $isunknown(selectInput) |-> (out === 2'b00)
    );

endmodule

rtl:
module sky130_fd_sc_lp__o221ai (
    Y ,
    A1,
    A2,
    B1,
    B2,
    C1
);

    output Y ;
    input  A1;
    input  A2;
    input  B1;
    input  B2;
    input  C1;

    wire or0_out    ;
    wire or1_out    ;
    wire nand0_out_Y;

    or   or0   (or0_out    , B2, B1              );
    or   or1   (or1_out    , A2, A1              );
    nand nand0 (nand0_out_Y, or1_out, or0_out, C1);
    buf  buf0  (Y          , nand0_out_Y         );

endmodule

sva:
module sky130_fd_sc_lp__o221ai_sva (
    input logic clk,
    input logic Y,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic B2,
    input logic C1
);

    // Y implements the buffered NAND of (A1|A2), (B1|B2), and C1.
    check_o221ai_equation: assert property (
        @(posedge clk)
        Y == ~(((A1 | A2) & (B1 | B2) & C1))
    );

    // A low C1 input forces the NAND output high.
    check_c1_low_forces_y_high: assert property (
        @(posedge clk)
        (C1 == 1'b0) |-> (Y == 1'b1)
    );

    // Both A inputs low force the first OR term low and Y high.
    check_a_inputs_low_force_y_high: assert property (
        @(posedge clk)
        ((A1 == 1'b0) && (A2 == 1'b0)) |-> (Y == 1'b1)
    );

    // Both B inputs low force the second OR term low and Y high.
    check_b_inputs_low_force_y_high: assert property (
        @(posedge clk)
        ((B1 == 1'b0) && (B2 == 1'b0)) |-> (Y == 1'b1)
    );

    // When both OR terms and C1 are high, the NAND output must be low.
    check_all_terms_high_drive_y_low: assert property (
        @(posedge clk)
        (((A1 | A2) == 1'b1) && ((B1 | B2) == 1'b1) && (C1 == 1'b1)) |-> (Y == 1'b0)
    );

    // A low Y can only occur when both OR terms and C1 are high.
    check_y_low_requires_all_terms_high: assert property (
        @(posedge clk)
        (Y == 1'b0) |-> (((A1 | A2) == 1'b1) && ((B1 | B2) == 1'b1) && (C1 == 1'b1))
    );

endmodule

rtl:
module counter (
    clk,
    rst,
    en,
    count
);

    input clk;
    input rst;
    input en;
    output [3:0] count;

    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    reg [3:0] count_reg;

    always @(posedge clk) begin
        if (rst == 1) begin
            count_reg <= 0;
        end else if (en == 1) begin
            count_reg <= count_reg + 1;
        end
    end

    assign count = count_reg;

endmodule

sva:
module counter_sva (
    input logic       clk,
    input logic       rst,
    input logic       en,
    input logic [3:0] count
);

    // Synchronous reset clears the counter on the next cycle.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |=> (count == 4'd0)
    );

    // Reset has priority over enable and still clears the counter.
    check_reset_overrides_enable: assert property (
        @(posedge clk) (rst && en) |=> (count == 4'd0)
    );

    // When enabled outside reset, the counter increments by one.
    check_enable_increments_count: assert property (
        @(posedge clk) disable iff (rst) en |=> (count == ($past(count) + 4'd1))
    );

    // When not enabled outside reset, the counter holds its value.
    check_disable_holds_count: assert property (
        @(posedge clk) disable iff (rst) !en |=> (count == $past(count))
    );

    // A 4-bit maximum value wraps to zero when incremented.
    check_wraps_after_max: assert property (
        @(posedge clk) disable iff (rst) (en && (count == 4'hf)) |=> (count == 4'h0)
    );

endmodule

rtl:
module logic_circuit (
    input A1,
    input A2,
    input B1,
    input C1,
    input D1,
    output X
);

    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    assign X = (A1 & A2) | (!A1 & B1) | (!C1 & D1);

endmodule

sva:
module logic_circuit_sva (
    input logic A1,
    input logic A2,
    input logic B1,
    input logic C1,
    input logic D1,
    input logic X
);

    // X must match the implemented Boolean equation.
    check_x_matches_expression: assert property (
        @($global_clock)
        X == ((A1 & A2) | ((!A1) & B1) | ((!C1) & D1))
    );

    // The A1/A2 term is sufficient to drive X high.
    check_x_high_on_a1_a2_term: assert property (
        @($global_clock)
        (A1 & A2) |-> X
    );

    // The !A1/B1 term is sufficient to drive X high.
    check_x_high_on_not_a1_b1_term: assert property (
        @($global_clock)
        ((!A1) & B1) |-> X
    );

    // The !C1/D1 term is sufficient to drive X high.
    check_x_high_on_not_c1_d1_term: assert property (
        @($global_clock)
        ((!C1) & D1) |-> X
    );

    // X must be low when all product terms are false.
    check_x_low_when_no_term_true: assert property (
        @($global_clock)
        !((A1 & A2) | ((!A1) & B1) | ((!C1) & D1)) |-> !X
    );

    // With A1 high and the C/D term off, X reduces to A2.
    check_x_reduces_to_a2_when_a1_high: assert property (
        @($global_clock)
        (A1 & !((!C1) & D1)) |-> (X == A2)
    );

    // With A1 low and the C/D term off, X reduces to B1.
    check_x_reduces_to_b1_when_a1_low: assert property (
        @($global_clock)
        ((!A1) & !((!C1) & D1)) |-> (X == B1)
    );

endmodule

rtl:
module adder_subtractor (
  input [3:0] A,
  input [3:0] B,
  input sub,
  input clk,
  input rst,
  output [3:0] out,
  output cout
);

  reg [3:0] A_inv;
  reg [3:0] B_inv;
  reg [3:0] sum;
  reg carry;

  // Invert B if subtracting
  always @* B_inv = sub ? ~B + 1 : B;

  // Invert A if subtracting
  always @* A_inv = sub ? ~A : A;

  // Full adder
  always @(posedge clk) begin
    if (rst) begin
      sum <= 0;
      carry <= 0;
    end else begin
      {carry, sum} <= A_inv + B_inv + carry;
    end
  end

  // Output
  assign out = sum;
  assign cout = carry;

endmodule

sva:
module adder_subtractor_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic sub,
    input logic clk,
    input logic rst,
    input logic [3:0] out,
    input logic cout
);

    // Clock: clk. Reset: rst, active-high synchronous.
    // Mixed logic: combinational operand preprocessing with sequential outputs.

    // Synchronous reset clears the registered output and carry on the next cycle.
    check_reset_clears_outputs: assert property (
        @(posedge clk) (rst == 1'b1) |=> ({cout, out} == 5'h00)
    );

    // In add mode, the next output is A + B + current cout, with the carry bit truncated.
    check_add_mode_update: assert property (
        @(posedge clk) disable iff (rst)
        (sub == 1'b0) |=> ({cout, out} == {1'b0, ($past(A) + $past(B) + $past(cout))})
    );

    // In subtract mode, the next output uses ~A and two's-complement B, with the carry bit truncated.
    check_sub_mode_update: assert property (
        @(posedge clk) disable iff (rst)
        (sub == 1'b1) |=> ({cout, out} == {1'b0, ((~$past(A)) + ((~$past(B)) + 4'h1) + $past(cout))})
    );

    // Every non-reset update drives the registered carry output low.
    check_carry_zero_after_update: assert property (
        @(posedge clk) disable iff (rst)
        1'b1 |=> (cout == 1'b0)
    );

endmodule

rtl:
module arithmetic_op (
    input [7:0] a,
    input [7:0] b,
    input [1:0] ctrl,
    output reg [7:0] result
);

always @(*) begin
    case(ctrl)
        2'b00: result = a + b;
        2'b01: result = a - b;
        2'b10: result = a & b;
        2'b11: result = a | b;
    endcase
end

endmodule

sva:
module arithmetic_op_sva (
    input logic clk,
    input logic [7:0] a,
    input logic [7:0] b,
    input logic [1:0] ctrl,
    input logic [7:0] result
);

    // Addition select drives result to a + b.
    check_add_operation: assert property (
        @(posedge clk) (ctrl == 2'b00) |-> (result == (a + b))
    );

    // Subtraction select drives result to a - b.
    check_sub_operation: assert property (
        @(posedge clk) (ctrl == 2'b01) |-> (result == (a - b))
    );

    // AND select drives result to a & b.
    check_and_operation: assert property (
        @(posedge clk) (ctrl == 2'b10) |-> (result == (a & b))
    );

    // OR select drives result to a | b.
    check_or_operation: assert property (
        @(posedge clk) (ctrl == 2'b11) |-> (result == (a | b))
    );

    // Stable inputs keep the sampled result stable.
    check_stable_inputs_hold_result: assert property (
        @(posedge clk) ($stable(a) && $stable(b) && $stable(ctrl)) |-> $stable(result)
    );

endmodule

rtl:
module signal_mux (
    input  A1,
    input  A2,
    input  A3,
    input  B1,
    output X
);

    assign X = (A1 & A2) | (~A1 & A3 & B1) | (~A1 & ~A3 & (A2 & B1));

endmodule

sva:
module signal_mux_sva (
    input logic clk,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic B1,
    input logic X
);

    // X matches the RTL combinational equation.
    check_x_equation: assert property (
        @(posedge clk)
        X == ((A1 & A2) | (~A1 & A3 & B1) | (~A1 & ~A3 & (A2 & B1)))
    );

    // When A1 is high, X follows A2.
    check_a1_high_selects_a2: assert property (
        @(posedge clk)
        A1 |-> (X == A2)
    );

    // When A1 is low, X reduces to B1 AND (A2 OR A3).
    check_a1_low_reduced_form: assert property (
        @(posedge clk)
        (!A1) |-> (X == (B1 & (A2 | A3)))
    );

    // When A1 is low and B1 is low, X must be low.
    check_a1_low_b1_low_forces_zero: assert property (
        @(posedge clk)
        (!A1 && !B1) |-> (X == 1'b0)
    );

    // When A1 is low, B1 is high, and A3 is high, X must be high.
    check_a1_low_b1_high_a3_high_forces_one: assert property (
        @(posedge clk)
        (!A1 && B1 && A3) |-> (X == 1'b1)
    );

    // When A1 is low, B1 is high, and A3 is low, X follows A2.
    check_a1_low_b1_high_a3_low_selects_a2: assert property (
        @(posedge clk)
        (!A1 && B1 && !A3) |-> (X == A2)
    );

endmodule

rtl:
module adder_4bit(
    input [3:0] A,
    input [3:0] B,
    input Cin,
    input Clk,
    output [3:0] S,
    output Cout
);

reg [4:0] sum; // Changed the size of sum to 5 bits to accommodate the carry-out

always @(posedge Clk) begin
    if (Cin) begin
        sum <= A + B + 1;
    end else begin
        sum <= A + B;
    end
end

assign S = sum[3:0];
assign Cout = sum[4];

endmodule

sva:
module adder_4bit_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic Cin,
    input logic Clk,
    input logic [3:0] S,
    input logic Cout
);

    // Registered outputs equal the previous cycle's 5-bit addition.
    check_registered_sum: assert property (
        @(posedge Clk)
        !$initstate |-> ({Cout, S} == ({1'b0, $past(A)} + {1'b0, $past(B)} + {4'b0, $past(Cin)}))
    );

    // Sum output is the low 4 bits of the previous cycle's addition.
    check_sum_low_bits: assert property (
        @(posedge Clk)
        !$initstate |-> (S == ($past(A) + $past(B) + $past(Cin)))
    );

    // Carry-out reflects overflow of the previous cycle's addition.
    check_carry_out_matches_overflow: assert property (
        @(posedge Clk)
        !$initstate |-> (Cout == (({1'b0, $past(A)} + {1'b0, $past(B)} + {4'b0, $past(Cin)}) >= 5'd16))
    );

    // With previous Cin low, the registered result is A plus B.
    check_cin_low_branch: assert property (
        @(posedge Clk)
        !$initstate && !$past(Cin) |-> ({Cout, S} == ({1'b0, $past(A)} + {1'b0, $past(B)}))
    );

    // With previous Cin high, the registered result is A plus B plus 1.
    check_cin_high_branch: assert property (
        @(posedge Clk)
        !$initstate && $past(Cin) |-> ({Cout, S} == ({1'b0, $past(A)} + {1'b0, $past(B)} + 5'd1))
    );

endmodule

rtl:
module three_input_full_adder (input A, input B, input C, output S, output Cout);
  wire n1, n2, n3;

  xor U1 (n1, A, B);
  xor U2 (S, n1, C);
  and U3 (n2, A, B);
  and U4 (n3, n1, C);
  or U5 (Cout, n2, n3);
endmodule

sva:
module three_input_full_adder_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic C,
    input logic S,
    input logic Cout
);

    // Sum output is the XOR of all three inputs.
    check_sum_function: assert property (
        @(posedge clk) S == (A ^ B ^ C)
    );

    // Carry output matches the implemented carry equation.
    check_carry_function: assert property (
        @(posedge clk) Cout == ((A & B) | ((A ^ B) & C))
    );

    // With C low, the block behaves as a half-adder on A and B.
    check_half_adder_mode: assert property (
        @(posedge clk) !C |-> ((S == (A ^ B)) && (Cout == (A & B)))
    );

    // With C high, sum inverts A^B and carry is the OR of A and B.
    check_c_high_mode: assert property (
        @(posedge clk) C |-> ((S == ~(A ^ B)) && (Cout == (A | B)))
    );

    // When A and B match, sum follows C and carry follows A.
    check_equal_ab_behavior: assert property (
        @(posedge clk) (A == B) |-> ((S == C) && (Cout == A))
    );

    // When A and B differ, sum is inverted C and carry follows C.
    check_different_ab_behavior: assert property (
        @(posedge clk) (A != B) |-> ((S == ~C) && (Cout == C))
    );

endmodule

rtl:
module latch_module (CLK, EN, TE, ENCLK);
  input CLK, EN, TE;
  output reg ENCLK;

  always @(posedge CLK) begin
    if (EN) begin
      ENCLK <= TE;
    end
