module up_counter_sva (
    input logic       clk,
    input logic       reset,
    input logic       enable,
    input logic [2:0] count
);

    // Active-high synchronous reset clears the counter on the next cycle.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 3'b000)
    );

    // When disabled outside reset, the counter holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset)
        (!enable) |=> (count == $past(count))
    );

    // When enabled below 7, the counter increments by one.
    check_increment_when_enabled: assert property (
        @(posedge clk) disable iff (reset)
        (enable && (count != 3'b111)) |=> (count == ($past(count) + 3'b001))
    );

    // When enabled at 7, the counter wraps back to zero.
    check_wrap_when_max: assert property (
        @(posedge clk) disable iff (reset)
        (enable && (count == 3'b111)) |=> (count == 3'b000)
    );

endmodule

module BIN_DEC2_sva (
    input logic        clk,
    input logic [15:0] B2,
    input logic [19:0] bcdout2
);

    // Reconstructed decimal value must equal the binary input.
    check_decimal_value_match: assert property (
        @(posedge clk)
        ((int'(bcdout2[19:16]) * 10000) +
         (int'(bcdout2[15:12]) * 1000)  +
         (int'(bcdout2[11:8])  * 100)   +
         (int'(bcdout2[7:4])   * 10)    +
          int'(bcdout2[3:0])) == int'(B2)
    );

    // Ones nibble must be a valid BCD digit.
    check_ones_digit_range: assert property (
        @(posedge clk) bcdout2[3:0] <= 4'd9
    );

    // Tens nibble must be a valid BCD digit.
    check_tens_digit_range: assert property (
        @(posedge clk) bcdout2[7:4] <= 4'd9
    );

    // Hundreds nibble must be a valid BCD digit.
    check_hundreds_digit_range: assert property (
        @(posedge clk) bcdout2[11:8] <= 4'd9
    );

    // Thousands nibble must be a valid BCD digit.
    check_thousands_digit_range: assert property (
        @(posedge clk) bcdout2[15:12] <= 4'd9
    );

    // Ten-thousands nibble must be a valid BCD digit.
    check_ten_thousands_digit_range: assert property (
        @(posedge clk) bcdout2[19:16] <= 4'd9
    );

    // Zero converts to all-zero BCD.
    check_zero_conversion: assert property (
        @(posedge clk) (B2 == 16'd0) |-> (bcdout2 == 20'h00000)
    );

    // Ten converts to 00010 in BCD.
    check_ten_conversion: assert property (
        @(posedge clk) (B2 == 16'd10) |-> (bcdout2 == 20'h00010)
    );

    // Ten-thousand converts to 10000 in BCD.
    check_ten_thousand_conversion: assert property (
        @(posedge clk) (B2 == 16'd10000) |-> (bcdout2 == 20'h10000)
    );

    // Maximum 16-bit input converts to 65535 in BCD.
    check_max_conversion: assert property (
        @(posedge clk) (B2 == 16'd65535) |-> (bcdout2 == 20'h65535)
    );

    // Single-digit inputs only occupy the ones nibble.
    check_single_digit_conversion: assert property (
        @(posedge clk) (B2 <= 16'd9) |-> (bcdout2[19:4] == 16'h0000 && bcdout2[3:0] == B2[3:0])
    );

endmodule

rtl:
module sky130_fd_sc_ms__clkdlyinv3sd3 (
    input A,
    input VPWR,
    input VGND,
    input VPB,
    input VNB,
    input clk,
    output Y
);

wire inv1_out, inv2_out, inv3_out;

assign inv1_out = ~A;
assign inv2_out = ~inv1_out;
assign inv3_out = ~inv2_out;

assign Y = inv3_out;

endmodule

sva:
module sky130_fd_sc_ms__clkdlyinv3sd3_sva (
    input logic A,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB,
    input logic clk,
    input logic Y
);

    // Y is the result of three inversions of A.
    check_y_matches_triple_inversion: assert property (
        @(posedge clk) Y == ~A
    );

    // A low produces Y high.
    check_output_high_when_input_low: assert property (
        @(posedge clk) !A |-> Y
    );

    // A high produces Y low.
    check_output_low_when_input_high: assert property (
        @(posedge clk) A |-> !Y
    );

    // Y always differs from A.
    check_output_is_logical_opposite: assert property (
        @(posedge clk) Y != A
    );

    // If A is stable across samples, Y is also stable.
    check_output_stable_when_input_stable: assert property (
        @(posedge clk) 1'b1 |=> ($stable(A) |-> $stable(Y))
    );

    // If A changes across samples, Y changes too.
    check_output_changes_with_input: assert property (
        @(posedge clk) 1'b1 |=> ($changed(A) |-> $changed(Y))
    );

    // Y can only change when A changes across samples.
    check_output_only_changes_with_input: assert property (
        @(posedge clk) 1'b1 |=> ($changed(Y) |-> $changed(A))
    );

    // A sampled rise yields a low sampled Y.
    check_output_low_on_input_rise: assert property (
        @(posedge clk) 1'b1 |=> ($rose(A) |-> !Y)
    );

    // A sampled fall yields a high sampled Y.
    check_output_high_on_input_fall: assert property (
        @(posedge clk) 1'b1 |=> ($fell(A) |-> Y)
    );

endmodule

rtl:
module counter48 #(
        parameter DATASIZE  = 16    // width of the counter, must be <=48 bits!
    ) (
        input wire                  clk,
        input wire                  res_n,
        input wire                  increment,
        input wire  [DATASIZE-1:0]  load,
        input wire                  load_enable,
        output wire [DATASIZE-1:0]  value
);

    reg [DATASIZE-1:0]  value_reg;
    reg                 load_enable_reg;

    assign value    = value_reg;

    always @(posedge clk or negedge res_n) begin
        if (!res_n) begin
            value_reg       <= {DATASIZE{1'b0}};
            load_enable_reg <= 1'b0;
        end
        else begin
            load_enable_reg <= load_enable;
            if (load_enable_reg) begin
                value_reg   <= load;
            end else if (increment) begin
                value_reg   <= value_reg + 1'b1;
            end
        end
    end

endmodule

sva:
module counter48_sva #(
    parameter DATASIZE = 16
) (
    input logic                 clk,
    input logic                 res_n,
    input logic                 increment,
    input logic [DATASIZE-1:0]  load,
    input logic                 load_enable,
    input logic [DATASIZE-1:0]  value
);

    // Reset holds the counter output at zero.
    check_reset_clears_value: assert property (
        @(posedge clk)
        (!$initstate && !res_n) |-> (value == {DATASIZE{1'b0}})
    );

    // A queued load updates value with the current load input on the next cycle.
    check_delayed_load_updates_value: assert property (
        @(posedge clk) disable iff (!res_n)
        (!$initstate && $past(res_n) && $past(load_enable)) |=> (value == $past(load))
    );

    // A queued load overrides increment.
    check_load_has_priority_over_increment: assert property (
        @(posedge clk) disable iff (!res_n)
        (!$initstate && $past(res_n) && $past(load_enable) && increment) |=> (value == $past(load))
    );

    // Without a queued load, increment advances the value by one.
    check_increment_advances_value: assert property (
        @(posedge clk) disable iff (!res_n)
        (!$initstate && $past(res_n) && !$past(load_enable) && increment) |=> (value == ($past(value) + 1'b1))
    );

    // Without a queued load or increment, the value holds.
    check_hold_without_activity: assert property (
        @(posedge clk) disable iff (!res_n)
        (!$initstate && $past(res_n) && !$past(load_enable) && !increment) |=> (value == $past(value))
    );

    // A new load_enable does not load immediately.
    check_load_enable_is_delayed: assert property (
        @(posedge clk) disable iff (!res_n)
        (!$initstate && $past(res_n) && !$past(load_enable) && load_enable && !increment) |=> (value == $past(value))
    );

    // A new load_enable does not block a same-cycle increment.
    check_increment_not_blocked_by_new_load_enable: assert property (
        @(posedge clk) disable iff (!res_n)
        (!$initstate && $past(res_n) && !$past(load_enable) && load_enable && increment) |=> (value == ($past(value) + 1'b1))
    );

endmodule

