rtl:
module top_module(
    input a,
    input b,
    input sel_b1,
    input sel_b2,
    output reg out_always
);

wire and_out;
wire mux_out;
wire final_out;

and_gate and_inst(
    .a(a),
    .b(b),
    .out(and_out)
);

mux_2to1 mux_inst(
    .a(a),
    .b(b),
    .sel(sel_b1 & sel_b2),
    .out(mux_out)
);

functional_module functional_inst(
    .and_out(and_out),
    .mux_out(mux_out),
    .final_out(final_out)
);

always @* begin
    out_always = final_out;
end

endmodule
module and_gate(
    input a,
    input b,
    output reg out
);

always @* begin
    out = a & b;
end

endmodule
module mux_2to1(
    input a,
    input b,
    input sel,
    output reg out
);

always @* begin
    out = sel ? b : a;
end

endmodule
module functional_module(
    input and_out,
    input mux_out,
    output reg final_out
);

always @* begin
    final_out = and_out ^ mux_out;
end

endmodule

sva:
module top_module_sva(
    input logic clk,
    input logic a,
    input logic b,
    input logic sel_b1,
    input logic sel_b2,
    input logic out_always
);

wire and_out;
wire mux_out;
wire final_out;

assign and_out  = a & b;
assign mux_out  = (sel_b1 & sel_b2) ? b : a;
assign final_out = and_out ^ mux_out;

// Output must match the combinational result of the submodules.
check_output_matches_final_out: assert property (
    @(posedge clk) out_always == final_out
);

// When both select bits are high, the mux path uses b.
check_output_when_b_selected: assert property (
    @(posedge clk) (sel_b1 & sel_b2) |-> (out_always == ((a & b) ^ b))
);

// When either select bit is low, the mux path uses a.
check_output_when_a_selected: assert property (
    @(posedge clk) !(sel_b1 & sel_b2) |-> (out_always == ((a & b) ^ a))
);

// With b selected, the final function simplifies to ~a & b.
check_selected_b_simplified: assert property (
    @(posedge clk) (sel_b1 & sel_b2) |-> (out_always == (~a & b))
);

// With a selected, the final function simplifies to a & ~b.
check_selected_a_simplified: assert property (
    @(posedge clk) !(sel_b1 & sel_b2) |-> (out_always == (a & ~b))
);

// Equal data inputs always force the XOR result low.
check_equal_inputs_drive_zero: assert property (
    @(posedge clk) (a == b) |-> (out_always == 1'b0)
);

// A high output is only possible when a and b differ.
check_high_output_requires_mismatch: assert property (
    @(posedge clk) out_always |-> (a ^ b)
);

// For a=1 and b=0, the output is high only when a is selected.
check_case_a1_b0: assert property (
    @(posedge clk) (a & ~b) |-> (out_always == !(sel_b1 & sel_b2))
);

// For a=0 and b=1, the output is high only when b is selected.
check_case_a0_b1: assert property (
    @(posedge clk) (~a & b) |-> (out_always == (sel_b1 & sel_b2))
);

endmodule

rtl:
module frequency_divider (
  input clk_in,
  input rst,
  output reg clk_out
);

parameter div = 10;

reg [31:0] count;

always @(posedge clk_in or posedge rst) begin
  if (rst) begin
    count <= 0;
    clk_out <= 0;
  end else begin
    count <= count + 1;
    if (count == div - 1) begin
      count <= 0;
      clk_out <= ~clk_out;
    end
  end
end

endmodule

sva:
module frequency_divider_sva #(
    parameter int unsigned div = 10
) (
    input logic        clk_in,
    input logic        rst,
    input logic        clk_out,
    input logic [31:0] count
);

    localparam logic [31:0] DIV_MINUS_1 = div - 1;

    // Reset clears both count and clk_out.
    check_reset_clears_state: assert property (
        @(posedge clk_in) rst |-> ((count == 32'd0) && (clk_out == 1'b0))
    );

    // Count increments by one before reaching div-1.
    check_count_increments_before_wrap: assert property (
        @(posedge clk_in) disable iff (rst || $initstate)
        ($past(count) != DIV_MINUS_1) |-> (count == ($past(count) + 32'd1))
    );

    // clk_out holds its value before count reaches div-1.
    check_clk_out_holds_before_wrap: assert property (
        @(posedge clk_in) disable iff (rst || $initstate)
        ($past(count) != DIV_MINUS_1) |-> (clk_out == $past(clk_out))
    );

    // Count wraps to zero when the previous count was div-1.
    check_count_wraps_at_terminal: assert property (
        @(posedge clk_in) disable iff (rst || $initstate)
        ($past(count) == DIV_MINUS_1) |-> (count == 32'd0)
    );

    // clk_out toggles when the previous count was div-1.
    check_clk_out_toggles_at_terminal: assert property (
        @(posedge clk_in) disable iff (rst || $initstate)
        ($past(count) == DIV_MINUS_1) |-> (clk_out == ~$past(clk_out))
    );

    // clk_out can only change on a wrap cycle.
    check_clk_out_changes_only_on_wrap: assert property (
        @(posedge clk_in) disable iff (rst || $initstate)
        (clk_out != $past(clk_out)) |-> ($past(count) == DIV_MINUS_1)
    );

    // A zero count outside reset must come from a wrap cycle.
    check_zero_count_only_after_wrap: assert property (
        @(posedge clk_in) disable iff (rst || $initstate)
        (count == 32'd0) |-> ($past(count) == DIV_MINUS_1)
    );

endmodule

rtl:
module detect_0_to_1 (
    input clk,
    input reset,
    input [31:0] in,
    output reg [31:0] out
);

reg [31:0] prev_in;

always @(posedge clk) begin
    if (reset) begin
        out <= 0;
        prev_in <= 0;
    end else begin
        prev_in <= in;
        out <= (in & ~prev_in);
    end
end

endmodule

sva:
module detect_0_to_1_assertions (
    input logic        clk,
    input logic        reset,
    input logic [31:0] in,
    input logic [31:0] out
);

    // A reset cycle forces out low on the following sample.
    check_reset_clears_out: assert property (
        @(posedge clk) reset |=> (out == 32'b0)
    );

    // The first active cycle after reset compares input against zero.
    check_first_active_cycle_after_reset: assert property (
        @(posedge clk) disable iff (reset)
        $past(reset) |=> (out == $past(in))
    );

    // Active cycles detect 0-to-1 transitions from the prior input.
    check_detects_zero_to_one_transitions: assert property (
        @(posedge clk) disable iff (reset)
        !$past(reset) |=> (out == ($past(in) & ~$past(in,2)))
    );

    // Output bits can only come from 1 bits in the generating input.
    check_out_is_subset_of_input: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> ((out & ~$past(in)) == 32'b0)
    );

    // An all-zero input produces an all-zero output.
    check_zero_input_produces_zero_out: assert property (
        @(posedge clk) disable iff (reset)
        (in == 32'b0) |=> (out == 32'b0)
    );

    // Stable input across active cycles produces no detection pulse.
    check_stable_input_produces_zero_out: assert property (
        @(posedge clk) disable iff (reset)
        (!$past(reset) && (in == $past(in))) |=> (out == 32'b0)
    );

    // Bits that were already high in the prior input do not retrigger.
    check_previous_ones_do_not_retrigger: assert property (
        @(posedge clk) disable iff (reset)
        !$past(reset) |=> ((out & $past(in,2)) == 32'b0)
    );

endmodule

