rtl:
module AddressGenerator(input clk, input ce,
                        input [4:0] Operation, 
                        input [1:0] MuxCtrl,
                        input [7:0] DataBus, T, X, Y,
                        output [15:0] AX,
                        output Carry);
  // Actual contents of registers
  reg [7:0] AL, AH;
  // Last operation generated a carry?
  reg SavedCarry;
  assign AX = {AH, AL};

  wire [2:0] ALCtrl = Operation[4:2];
  wire [1:0] AHCtrl = Operation[1:0];

  // Possible new value for AL.
  wire [7:0] NewAL;
  assign {Carry,NewAL} = {1'b0, (MuxCtrl[1] ? T : AL)} + {1'b0, (MuxCtrl[0] ? Y : X)};

  // The other one
  wire TmpVal = (!AHCtrl[1] | SavedCarry);
  wire [7:0] TmpAdd = (AHCtrl[1] ? AH : AL) + {7'b0, TmpVal};

  always @(posedge clk) if (ce) begin
    SavedCarry <= Carry;
    if (ALCtrl[2])
      case(ALCtrl[1:0])
      0: AL <= NewAL;
      1: AL <= DataBus;
      2: AL <= TmpAdd;
      3: AL <= T;
      endcase

    case(AHCtrl[1:0])
    0: AH <= AH;
    1: AH <= 0;
    2: AH <= TmpAdd;
    3: AH <= DataBus;
    endcase
  end
endmodule

sva:
module AddressGenerator_sva (
    input logic        clk,
    input logic        ce,
    input logic [4:0]  Operation,
    input logic [1:0]  MuxCtrl,
    input logic [7:0]  DataBus,
    input logic [7:0]  T,
    input logic [7:0]  X,
    input logic [7:0]  Y,
    input logic [15:0] AX,
    input logic        Carry
);

    property p_carry_matches_selected_sum;
        logic [8:0] expected_sum;
        @(posedge clk)
            (1'b1, expected_sum = {1'b0, (MuxCtrl[1] ? T : AX[7:0])} + {1'b0, (MuxCtrl[0] ? Y : X)})
            |-> (Carry == expected_sum[8]);
    endproperty

    property p_ax_holds_when_ce_low;
        logic [15:0] held_ax;
        @(posedge clk)
            (!ce, held_ax = AX)
            |=> (AX == held_ax);
    endproperty

    property p_al_holds_when_not_enabled;
        logic [7:0] held_al;
        @(posedge clk)
            (ce && !Operation[4], held_al = AX[7:0])
            |=> (AX[7:0] == held_al);
    endproperty

    property p_al_loads_newal;
        logic [7:0] expected_al;
        @(posedge clk)
            (ce && (Operation[4:2] == 3'b100),
             expected_al = (MuxCtrl[1] ? T : AX[7:0]) + (MuxCtrl[0] ? Y : X))
            |=> (AX[7:0] == expected_al);
    endproperty

    property p_al_loads_databus;
        logic [7:0] expected_al;
        @(posedge clk)
            (ce && (Operation[4:2] == 3'b101), expected_al = DataBus)
            |=> (AX[7:0] == expected_al);
    endproperty

    property p_al_loads_incremented_al;
        logic [7:0] expected_al;
        @(posedge clk)
            (ce && (Operation[4:2] == 3'b110) && !Operation[1], expected_al = AX[7:0] + 8'h01)
            |=> (AX[7:0] == expected_al);
    endproperty

    property p_al_loads_t;
        logic [7:0] expected_al;
        @(posedge clk)
            (ce && (Operation[4:2] == 3'b111), expected_al = T)
            |=> (AX[7:0] == expected_al);
    endproperty

    property p_ah_holds;
        logic [7:0] held_ah;
        @(posedge clk)
            (ce && (Operation[1:0] == 2'b00), held_ah = AX[15:8])
            |=> (AX[15:8] == held_ah);
    endproperty

    property p_ah_clears;
        @(posedge clk)
            (ce && (Operation[1:0] == 2'b01))
            |=> (AX[15:8] == 8'h00);
    endproperty

    property p_ah_loads_databus;
        logic [7:0] expected_ah;
        @(posedge clk)
            (ce && (Operation[1:0] == 2'b11), expected_ah = DataBus)
            |=> (AX[15:8] == expected_ah);
    endproperty

    // Carry is the carry-out of the selected 8-bit addition.
    check_carry_matches_selected_sum: assert property (p_carry_matches_selected_sum);

    // AX holds its value when clock enable is low.
    check_ax_holds_when_ce_low: assert property (p_ax_holds_when_ce_low);

    // AL holds when the AL update enable bit is not set.
    check_al_holds_when_not_enabled: assert property (p_al_holds_when_not_enabled);

    // AL loads the selected sum when ALCtrl selects NewAL.
    check_al_loads_newal: assert property (p_al_loads_newal);

    // AL loads DataBus when ALCtrl selects the bus.
    check_al_loads_databus: assert property (p_al_loads_databus);

    // AL increments from its current value when TmpAdd uses AL plus one.
    check_al_loads_incremented_al: assert property (p_al_loads_incremented_al);

    // AL loads T when ALCtrl selects T.
    check_al_loads_t: assert property (p_al_loads_t);

    // AH holds when AHCtrl selects hold.
    check_ah_holds: assert property (p_ah_holds);

    // AH clears to zero when AHCtrl selects zero.
    check_ah_clears: assert property (p_ah_clears);

    // AH loads DataBus when AHCtrl selects the bus.
    check_ah_loads_databus: assert property (p_ah_loads_databus);

endmodule

rtl:
module power_module (
    input VPB,
    input VPWR,
    input VGND,
    input VNB,
    output reg HI,
    output reg LO
);

always @* begin
    if (VPB) begin
        HI = 1;
        LO = 0;
    end else if (VPWR && !VGND) begin
        HI = 1;
        LO = 0;
    end else if (VNB) begin
        HI = 0;
        LO = 1;
    end else if (!VPWR && VGND) begin
        HI = 0;
        LO = 1;
    end else begin
        HI = 0;
        LO = 0;
    end
end

endmodule

sva:
module power_module_sva (
    input logic VPB,
    input logic VPWR,
    input logic VGND,
    input logic VNB,
    input logic HI,
    input logic LO
);

    // VPB forces HI high and LO low.
    check_vpb_branch: assert property (
        @($global_clock) VPB |-> (HI == 1'b1) && (LO == 1'b0)
    );

    // With VPB low, VPWR high and VGND low drive HI high and LO low.
    check_vpwr_branch: assert property (
        @($global_clock) (!VPB && VPWR && !VGND) |-> (HI == 1'b1) && (LO == 1'b0)
    );

    // VNB drives LO high when the HI-driving conditions are absent.
    check_vnb_branch: assert property (
        @($global_clock) (!VPB && !(VPWR && !VGND) && VNB) |-> (HI == 1'b0) && (LO == 1'b1)
    );

    // With no VPWR and asserted VGND, LO is high when higher-priority branches are absent.
    check_no_vpwr_vgnd_branch: assert property (
        @($global_clock) (!VPB && !VNB && !VPWR && VGND) |-> (HI == 1'b0) && (LO == 1'b1)
    );

    // When neither HI nor LO conditions apply, both outputs are low.
    check_default_branch: assert property (
        @($global_clock) (!VPB && !VNB && ((VPWR && VGND) || (!VPWR && !VGND))) |-> (HI == 1'b0) && (LO == 1'b0)
    );

    // HI and LO are never high at the same time.
    check_hi_lo_mutex: assert property (
        @($global_clock) !((HI == 1'b1) && (LO == 1'b1))
    );

endmodule

module fifo_counter_sva (
    input logic clk,
    input logic empty,
    input logic ge2_free,
    input logic ge3_free,
    input logic [1:0] input_tm_cnt,
    input logic [4:0] fifo_cnt_inc
);

    // Output matches the RTL priority function.
    check_full_function: assert property (
        @(posedge clk)
        fifo_cnt_inc == (
            empty ? {3'b000, input_tm_cnt} :
            ((ge3_free && (input_tm_cnt == 2'b11)) ? 5'd2 :
             ((ge2_free && (input_tm_cnt >= 2'd2)) ? 5'd1 :
              ((input_tm_cnt >= 2'd1) ? 5'd0 : 5'b11111)))
        )
    );

    // When empty is high, the output passes through input_tm_cnt.
    check_empty_pass_through: assert property (
        @(posedge clk)
        empty |-> (fifo_cnt_inc == {3'b000, input_tm_cnt})
    );

    // The empty branch has priority over the later branches.
    check_empty_priority: assert property (
        @(posedge clk)
        (empty && ge3_free && ge2_free && (input_tm_cnt == 2'b11)) |-> (fifo_cnt_inc == 5'd3)
    );

    // For non-empty and count 3 with ge3_free, the output is 2.
    check_ge3_free_count3: assert property (
        @(posedge clk)
        (!empty && ge3_free && (input_tm_cnt == 2'b11)) |-> (fifo_cnt_inc == 5'd2)
    );

    // The ge3_free branch overrides ge2_free when both are true.
    check_ge3_priority_over_ge2: assert property (
        @(posedge clk)
        (!empty && ge3_free && ge2_free && (input_tm_cnt == 2'b11)) |-> (fifo_cnt_inc == 5'd2)
    );

    // For non-empty and count 2 with ge2_free, the output is 1.
    check_ge2_free_count2: assert property (
        @(posedge clk)
        (!empty && ge2_free && (input_tm_cnt == 2'b10)) |-> (fifo_cnt_inc == 5'd1)
    );

    // For count 3 without ge3_free but with ge2_free, the output is 1.
    check_count3_ge2_without_ge3: assert property (
        @(posedge clk)
        (!empty && !ge3_free && ge2_free && (input_tm_cnt == 2'b11)) |-> (fifo_cnt_inc == 5'd1)
    );

    // For non-empty and count 1, the output falls through to 0.
    check_count1_maps_zero: assert property (
        @(posedge clk)
        (!empty && (input_tm_cnt == 2'b01)) |-> (fifo_cnt_inc == 5'd0)
    );

    // For non-empty and count 2 without ge2_free, the output is 0.
    check_count2_without_ge2_maps_zero: assert property (
        @(posedge clk)
        (!empty && !ge2_free && (input_tm_cnt == 2'b10)) |-> (fifo_cnt_inc == 5'd0)
    );

    // For non-empty and count 0, the output is all ones.
    check_count0_maps_all_ones: assert property (
        @(posedge clk)
        (!empty && (input_tm_cnt == 2'b00)) |-> (fifo_cnt_inc == 5'b11111)
    );

    // The output only takes values produced by the RTL.
    check_output_legal_values: assert property (
        @(posedge clk)
        (fifo_cnt_inc == 5'd0)  ||
        (fifo_cnt_inc == 5'd1)  ||
        (fifo_cnt_inc == 5'd2)  ||
        (fifo_cnt_inc == 5'd3)  ||
        (fifo_cnt_inc == 5'b11111)
    );

endmodule

