module sky130_fd_sc_hd__fa (
    COUT,
    SUM ,
    A   ,
    B   ,
    CIN
);

    output COUT;
    output SUM ;
    input  A   ;
    input  B   ;
    input  CIN ;

    wire or0_out     ;
    wire and0_out    ;
    wire and1_out    ;
    wire and2_out    ;
    wire nor0_out    ;
    wire nor1_out    ;
    wire or1_out_COUT;
    wire or2_out_SUM ;

    or  or0  (or0_out     , CIN, B            );
    and and0 (and0_out    , or0_out, A        );
    and and1 (and1_out    , B, CIN            );
    or  or1  (or1_out_COUT, and1_out, and0_out);
    buf buf0 (COUT        , or1_out_COUT      );
    and and2 (and2_out    , CIN, A, B         );
    nor nor0 (nor0_out    , A, or0_out        );
    nor nor1 (nor1_out    , nor0_out, COUT    );
    or  or2  (or2_out_SUM , nor1_out, and2_out);
    buf buf1 (SUM         , or2_out_SUM       );

endmodule

sva:
module sky130_fd_sc_hd__fa_sva (
    input  logic clk,   // property clock
    input  logic COUT,
    input  logic SUM,
    input  logic A,
    input  logic B,
    input  logic CIN
);
    // COUT implements majority-of-three: (A&B) | (A&CIN) | (B&CIN).
    check_cout_majority: assert property (
        @(posedge clk) disable iff (1'b0)
        COUT == ((A & B) | (A & CIN) | (B & CIN))
    );

    // SUM is odd parity of inputs: A ^ B ^ CIN.
    check_sum_parity: assert property (
        @(posedge clk) disable iff (1'b0)
        SUM == (A ^ B ^ CIN)
    );

    // When COUT is 1, SUM equals A&B&CIN (only 3 ones case yields SUM=1).
    check_sum_when_cout1: assert property (
        @(posedge clk) disable iff (1'b0)
        (COUT == 1'b1) |-> (SUM == (A & B & CIN))
    );

    // When COUT is 0, SUM equals A|B|CIN (exactly one 1 yields SUM=1).
    check_sum_when_cout0: assert property (
        @(posedge clk) disable iff (1'b0)
        (COUT == 1'b0) |-> (SUM == (A | B | CIN))
    );

    // All inputs 0 -> outputs 0.
    check_zero_inputs: assert property (
        @(posedge clk) disable iff (1'b0)
        ({A,B,CIN} == 3'b000) |-> (COUT == 1'b0 && SUM == 1'b0)
    );

    // Exactly one input 1 -> SUM=1, COUT=0.
    check_one_hot_case: assert property (
        @(posedge clk) disable iff (1'b0)
        ({A,B,CIN} inside {3'b001,3'b010,3'b100}) |-> (COUT == 1'b0 && SUM == 1'b1)
    );

    // Exactly two inputs 1 -> SUM=0, COUT=1.
    check_two_ones_case: assert property (
        @(posedge clk) disable iff (1'b0)
        ({A,B,CIN} inside {3'b011,3'b101,3'b110}) |-> (COUT == 1'b1 && SUM == 1'b0)
    );

    // All inputs 1 -> outputs 1.
    check_all_ones_case: assert property (
        @(posedge clk) disable iff (1'b0)
        ({A,B,CIN} == 3'b111) |-> (COUT == 1'b1 && SUM == 1'b1)
    );

    // If A equals B, COUT equals that value (majority determined by the pair).
    check_cout_when_A_eq_B: assert property (
        @(posedge clk) disable iff (1'b0)
        (A == B) |-> (COUT == A)
    );

    // If A equals B, SUM equals CIN (A^B cancels).
    check_sum_when_A_eq_B: assert property (
        @(posedge clk) disable iff (1'b0)
        (A == B) |-> (SUM == CIN)
    );
endmodule

rtl:
module combinational_circuit (
    X,
    A1,
    A2,
    B1,
    C1
);

    output X;
    input A1;
    input A2;
    input B1;
    input C1;

    assign X = (A1) ? 1'b1 :
               (A2) ? 1'b0 :
               (B1) ? 1'b1 :
               (C1) ? 1'b0 :
                      1'b1 ;

endmodule

sva:
module combinational_circuit_sva (
    input logic X,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic C1
);
    // No explicit clock/reset in RTL; pure combinational; assertions use $global_clock.
    // Behavior: priority-if chain: A1?1 : A2?0 : B1?1 : C1?0 : 1.

    // A1 high forces X high (top priority).
    check_a1_forces_one: assert property (
        @($global_clock) (A1 == 1'b1) |-> (X == 1'b1)
    );

    // With A1 low and A2 high, X is driven low.
    check_a2_sets_zero_when_a1_low: assert property (
        @($global_clock) ((A1 == 1'b0) && (A2 == 1'b1)) |-> (X == 1'b0)
    );

    // With A1,A2 low and B1 high, X is driven high.
    check_b1_sets_one_when_a1_a2_low: assert property (
        @($global_clock) ((A1 == 1'b0) && (A2 == 1'b0) && (B1 == 1'b1)) |-> (X == 1'b1)
    );

    // With A1,A2,B1 low and C1 high, X is driven low.
    check_c1_sets_zero_when_higher_low: assert property (
        @($global_clock) ((A1 == 1'b0) && (A2 == 1'b0) && (B1 == 1'b0) && (C1 == 1'b1)) |-> (X == 1'b0)
    );

    // With all inputs low, default drives X high.
    check_default_sets_one: assert property (
        @($global_clock) ((A1 == 1'b0) && (A2 == 1'b0) && (B1 == 1'b0) && (C1 == 1'b0)) |-> (X == 1'b1)
    );

    // When both B1 and C1 high and higher terms low, B1 overrides -> X high.
    check_b1_overrides_c1: assert property (
        @($global_clock) ((A1 == 1'b0) && (A2 == 1'b0) && (B1 == 1'b1) && (C1 == 1'b1)) |-> (X == 1'b1)
    );

    // When A1 and A2 are high, A1 overrides -> X high.
    check_a1_overrides_a2: assert property (
        @($global_clock) ((A1 == 1'b1) && (A2 == 1'b1)) |-> (X == 1'b1)
    );

    // When A1 and C1 are high, A1 overrides -> X high.
    check_a1_overrides_c1: assert property (
        @($global_clock) ((A1 == 1'b1) && (C1 == 1'b1)) |-> (X == 1'b1)
    );

    // X low occurs only via A2 path or C1 path with higher terms low.
    check_zero_only_in_a2_or_c1_paths: assert property (
        @($global_clock) (X == 1'b0) |-> ((A1 == 1'b0) && ((A2 == 1'b1) || ((A2 == 1'b0) && (B1 == 1'b0) && (C1 == 1'b1))))
    );

    // If X is high and A1 is low, then A2 must be low (else A2-branch would force X low).
    check_x_high_implies_a2_low_when_a1_low: assert property (
        @($global_clock) ((X == 1'b1) && (A1 == 1'b0)) |-> (A2 == 1'b0)
    );

endmodule

