sva:
module sky130_fd_sc_ms__nor4bb_sva (
    input logic Y,
    input logic A,
    input logic B,
    input logic C_N,
    input logic D_N
);
    // Combinational gate with no clock/reset; sample on any input edge.

    // Y must equal (~(A|B)) & C_N & D_N.
    check_y_functional_equivalence: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C_N or negedge C_N or posedge D_N or negedge D_N)
            (Y === ((~(A | B)) & C_N & D_N))
    );

    // If A and B are 0 and C_N and D_N are 1, Y must be 1.
    check_y_one_only_when_ab00_cn1_dn1: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C_N or negedge C_N or posedge D_N or negedge D_N)
            ((!A && !B && (C_N == 1'b1) && (D_N == 1'b1)) -> (Y == 1'b1))
    );

    // A=1 forces Y=0.
    check_a_high_forces_y_low: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C_N or negedge C_N or posedge D_N or negedge D_N)
            ((A == 1'b1) -> (Y == 1'b0))
    );

    // B=1 forces Y=0.
    check_b_high_forces_y_low: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C_N or negedge C_N or posedge D_N or negedge D_N)
            ((B == 1'b1) -> (Y == 1'b0))
    );

    // C_N=0 forces Y=0.
    check_c_n_low_forces_y_low: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C_N or negedge C_N or posedge D_N or negedge D_N)
            ((C_N == 1'b0) -> (Y == 1'b0))
    );

    // D_N=0 forces Y=0.
    check_d_n_low_forces_y_low: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C_N or negedge C_N or posedge D_N or negedge D_N)
            ((D_N == 1'b0) -> (Y == 1'b0))
    );

    // Y=1 implies A=0.
    check_y_high_implies_a_zero: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C_N or negedge C_N or posedge D_N or negedge D_N)
            ((Y == 1'b1) -> (A == 1'b0))
    );

    // Y=1 implies B=0.
    check_y_high_implies_b_zero: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C_N or negedge C_N or posedge D_N or negedge D_N)
            ((Y == 1'b1) -> (B == 1'b0))
    );

    // With A=0 and B=0, Y equals C_N & D_N.
    check_ab00_y_equals_cn_and_dn: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C_N or negedge C_N or posedge D_N or negedge D_N)
            ((!A && !B) -> (Y === (C_N & D_N)))
    );

    // With C_N=1 and D_N=1, Y equals ~(A|B).
    check_cn1_dn1_y_equals_nor_ab: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C_N or negedge C_N or posedge D_N or negedge D_N)
            (((C_N == 1'b1) && (D_N == 1'b1)) -> (Y === ~(A | B)))
    );
endmodule

module addsub_sva (
    input logic CLK,        // External clock for sampling assertions
    input logic [3:0] A,
    input logic [3:0] B,
    input logic ctrl,
    input logic [3:0] Y
);
    // Notes: No reset in RTL; combinational logic; assertions are sampled on CLK.

    // When ctrl=1, Y equals A+B (4-bit modulo arithmetic).
    check_add_result: assert property (
        @(posedge CLK) ctrl |-> (Y == (A + B))
    );

    // When ctrl=0, Y equals A-B (4-bit modulo arithmetic).
    check_sub_result: assert property (
        @(posedge CLK) !ctrl |-> (Y == (A - B))
    );

    // If inputs are stable across cycles, output remains stable.
    check_stable_when_inputs_unchanged: assert property (
        @(posedge CLK) $stable({A,B,ctrl}) |-> $stable(Y)
    );

    // If B is zero, output equals A regardless of ctrl.
    check_b_zero_returns_a: assert property (
        @(posedge CLK) (B == 4'd0) |-> (Y == A)
    );

    // If ctrl=1 and A is zero, output equals B.
    check_add_a_zero_returns_b: assert property (
        @(posedge CLK) (ctrl && (A == 4'd0)) |-> (Y == B)
    );

    // If ctrl=0 and A==B, output is zero.
    check_sub_self_zero: assert property (
        @(posedge CLK) (!ctrl && (A == B)) |-> (Y == 4'd0)
    );

    // Wrap-around example: 0xF + 1 -> 0 when adding.
    check_add_wrap_ff_plus_1: assert property (
        @(posedge CLK) (ctrl && (A == 4'hF) && (B == 4'd1)) |-> (Y == 4'h0)
    );

    // Wrap-around example: 0 - 1 -> 0xF when subtracting.
    check_sub_wrap_0_minus_1: assert property (
        @(posedge CLK) (!ctrl && (A == 4'd0) && (B == 4'd1)) |-> (Y == 4'hF)
    );

    // Adding zeros yields zero.
    check_add_zero_zero: assert property (
        @(posedge CLK) (ctrl && (A == 4'd0) && (B == 4'd0)) |-> (Y == 4'd0)
    );

    // Subtracting zeros yields zero.
    check_sub_zero_zero: assert property (
        @(posedge CLK) (!ctrl && (A == 4'd0) && (B == 4'd0)) |-> (Y == 4'd0)
    );

endmodule

rtl:
module mux_2to1 (
    input A,
    input B,
    input S,
    output reg Y
);

    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    always @* begin
        if (S == 0)
            Y = A;
        else
            Y = B;
    end

endmodule

sva:
module mux_2to1_sva (
    input logic clk,   // sampling clock for combinational DUT
    input logic A,
    input logic B,
    input logic S,
    input logic Y
);
    // When S is 0, output must equal A.
    check_select0_routes_A: assert property (
        @(posedge clk) (S === 1'b0) |-> (Y === A)
    );

    // When S is 1, output must equal B.
    check_select1_routes_B: assert property (
        @(posedge clk) (S === 1'b1) |-> (Y === B)
    );

    // If A equals B, output must equal that common value.
    check_equal_inputs_pass_through: assert property (
        @(posedge clk) (A === B) |-> (Y === A)
    );

    // If S, A, and B are stable across a cycle, Y must be stable.
    check_stable_when_inputs_stable: assert property (
        @(posedge clk) ($stable(S) && $stable(A) && $stable(B)) |-> $stable(Y)
    );

    // If Y changes, it must be due to S changing or the selected input changing.
    check_output_change_requires_cause: assert property (
        @(posedge clk) (!$stable(Y)) |-> ( !$stable(S)
                                        || (S === 1'b0 && !$stable(A))
                                        || (S === 1'b1 && !$stable(B)) )
    );

    // With S held at 0, a change on A must be reflected on Y at the next sample.
    check_s0_a_change_updates_y: assert property (
        @(posedge clk) (S === 1'b0 && $past(S) === 1'b0 && (A !== $past(A))) |-> (Y === A)
    );

    // With S held at 1, a change on B must be reflected on Y at the next sample.
    check_s1_b_change_updates_y: assert property (
        @(posedge clk) (S === 1'b1 && $past(S) === 1'b1 && (B !== $past(B))) |-> (Y === B)
    );

    // On a rising edge of S, output must equal B.
    check_sel_rise_selects_B: assert property (
        @(posedge clk) $rose(S) |-> (Y === B)
    );

    // On a falling edge of S, output must equal A.
    check_sel_fall_selects_A: assert property (
        @(posedge clk) $fell(S) |-> (Y === A)
    );

    // With S held at 0 and A stable, Y must remain stable (B changes cannot affect Y).
    check_irrelevant_input_no_effect_s0: assert property (
        @(posedge clk) (S === 1'b0 && $past(S) === 1'b0 && $stable(A)) |-> $stable(Y)
    );

    // With S held at 1 and B stable, Y must remain stable (A changes cannot affect Y).
    check_irrelevant_input_no_effect_s1: assert property (
        @(posedge clk) (S === 1'b1 && $past(S) === 1'b1 && $stable(B)) |-> $stable(Y)
    );
endmodule

rtl:
module adder16 (
    input [15:0] in1,
    input [15:0] in2,
    output [15:0] out,
    output carry
);

    assign {carry, out} = in1 + in2;

endmodule
module nand16 (
    input [15:0] in1,
    input [15:0] in2,
    output [15:0] out
);

    assign out = ~(in1 & in2);

endmodule
module mux16x2 (
    input [15:0] in1,
    input [15:0] in2,
    input sel,
    output [15:0] out
);

    assign out = (sel == 1'b0) ? in1 : in2;

endmodule
module alu(
    input [15:0] in1, in2,
    input op,
    output [15:0] out,
    output zero, carry
);

    wire [15:0] outAdd, outNand;
    wire carryAdd;

    // Instantiate the adder16 module
    adder16 add1(.in1(in1), .in2(in2), .out(outAdd), .carry(carryAdd));

    // Instantiate the nand16 module
    nand16 nand1(.in1(in1), .in2(in2), .out(outNand));

    // Instantiate the mux16x2 module
    mux16x2 m1(.in1(outAdd), .in2(outNand), .sel(op), .out(out));

    // Perform bitwise NOR on the output
    nor n1(zero, out[15], out[14], out[13], out[12], out[11], out[10], out[9], out[8], out[7], out[6], out[5], out[4], out[3], out[2], out[1], out[0]);

    // Set the carry output based on the operation performed
    assign carry = (op == 0) ? carryAdd : 1'b0;

endmodule

sva:
module alu_sva (
    input logic CLK,
    input logic [15:0] in1,
    input logic [15:0] in2,
    input logic op,
    input logic [15:0] out,
    input logic zero,
    input logic carry
);
    // When op==0, {carry,out} equals the 17-bit sum of in1 and in2.
    check_add_sum_selected: assert property (
        @(posedge CLK) disable iff (1'b0) (op == 1'b0) |-> ({carry, out} == ({1'b0, in1} + {1'b0, in2}))
    );

    // When op==1, out equals bitwise NAND of inputs.
    check_nand_selected_out: assert property (
        @(posedge CLK) disable iff (1'b0) (op == 1'b1) |-> (out == ~(in1 & in2))
    );

    // When op==1, carry is forced LOW.
    check_carry_zero_on_nand: assert property (
        @(posedge CLK) disable iff (1'b0) (op == 1'b1) |-> (carry == 1'b0)
    );

    // zero is the NOR-reduction of out bits.
    check_zero_is_nor_out: assert property (
        @(posedge CLK) disable iff (1'b0) zero == ~(|out)
    );

    // For add op, zero matches NOR of expected sum low 16 bits.
    check_zero_matches_add: assert property (
        @(posedge CLK) disable iff (1'b0) (op == 1'b0) |-> (zero == ~(|(({1'b0, in1} + {1'b0, in2})[15:0])))
    );

    // For NAND op, zero matches NOR of ~(in1 & in2).
    check_zero_matches_nand: assert property (
        @(posedge CLK) disable iff (1'b0) (op == 1'b1) |-> (zero == ~(|(~(in1 & in2))))
    );

    // If carry is HIGH, the operation must be add.
    check_carry_implies_add: assert property (
        @(posedge CLK) disable iff (1'b0) (carry == 1'b1) |-> (op == 1'b0)
    );

    // With stable inputs and op, outputs must remain stable.
    check_pure_comb_stability: assert property (
        @(posedge CLK) disable iff (1'b0) $stable({in1, in2, op}) |-> $stable({out, zero, carry})
    );
endmodule

rtl:
module synchronizer_ff
   (D,
    Q,
    m_aclk,
    AR);
  output [3:0]D;
  input [3:0]Q;
  input m_aclk;
  input AR;

  reg [3:0] Q_sync;
  always @(posedge m_aclk or negedge AR) begin
    if (!AR) begin
      Q_sync <= 4'b0;
    end else begin
      Q_sync <= Q;
    end
  end

  assign D = Q_sync;

endmodule

sva:
module synchronizer_ff_sva (
    input logic [3:0] D,
    input logic [3:0] Q,
    input logic m_aclk,
    input logic AR
);
    ///// Reset behavior /////
    // While reset is asserted (AR=0), D must be 0.
    check_reset_forces_zero: assert property (
        @(posedge m_aclk) (!AR) |-> (D == 4'b0000)
    );
    // On reset assertion, D is 0 at this clock.
    check_reset_assert_cycle_zero: assert property (
        @(posedge m_aclk) $fell(AR) |-> (D == 4'b0000)
    );
    // On reset deassertion, D remains 0 at this clock (pre-NBA sample).
    check_reset_deassert_cycle_zero: assert property (
        @(posedge m_aclk) $rose(AR) |-> (D == 4'b0000)
    );

    ///// Normal operation /////
    // With AR high for two consecutive clocks, D equals Q from the previous clock.
    check_capture_latency: assert property (
        @(posedge m_aclk) disable iff (!AR) $past(AR) |-> (D == $past(Q))
    );
    // After reset deasserts, on the next clock D equals Q sampled at deassertion.
    check_capture_after_reset_release: assert property (
        @(posedge m_aclk) disable iff (!AR) $rose(AR) |-> ##1 (AR && (D == $past(Q)))
    );
    // If Q is stable across clocks while out of reset, D remains stable.
    check_stable_Q_keeps_D_stable: assert property (
        @(posedge m_aclk) disable iff (!AR) ($past(AR) && (Q == $past(Q))) |-> (D == $past(D))
    );
    // If D changes (and AR was high for the last two clocks), then prior-Q changed.
    check_D_change_has_prior_Q_change: assert property (
        @(posedge m_aclk) disable iff (!AR) ($past(AR) && $past($past(AR)) && (D != $past(D))) |-> ($past(Q) != $past($past(Q)))
    );
    // If prior-Q changed (and AR was high for the last two clocks), then D changes.
    check_Q_change_causes_D_change: assert property (
        @(posedge m_aclk) disable iff (!AR) ($past(AR) && $past($past(AR)) && ($past(Q) != $past($past(Q)))) |-> (D != $past(D))
    );
endmodule

rtl:
module sky130_fd_sc_hvl__nand3 (
    Y,
    A,
    B,
    C
);

    output Y;
    input  A;
    input  B;
    input  C;

    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    wire nand0_out_Y;

    nand nand0 (nand0_out_Y, B, A, C        );
    buf  buf0  (Y          , nand0_out_Y    );

endmodule

sva:
module sky130_fd_sc_hvl__nand3_sva (
    input logic clk,
    input logic Y,
    input logic A,
    input logic B,
    input logic C
);
    // When all inputs are 1, Y must be 0 (NAND3 truth).
    check_all_ones_drives_low: assert property (
        @(posedge clk) (A == 1'b1 && B == 1'b1 && C == 1'b1) |-> (Y == 1'b0)
    );

    // If A is 0, Y must be 1 (NAND3 truth).
    check_a_zero_forces_high: assert property (
        @(posedge clk) (A == 1'b0) |-> (Y == 1'b1)
    );

    // If B is 0, Y must be 1 (NAND3 truth).
    check_b_zero_forces_high: assert property (
        @(posedge clk) (B == 1'b0) |-> (Y == 1'b1)
    );

    // If C is 0, Y must be 1 (NAND3 truth).
    check_c_zero_forces_high: assert property (
        @(posedge clk) (C == 1'b0) |-> (Y == 1'b1)
    );

    // Y can be 0 only when A, B, and C are all 1.
    check_only_low_if_all_ones: assert property (
        @(posedge clk) (Y == 1'b0) |-> (A == 1'b1 && B == 1'b1 && C == 1'b1)
    );

    // If Y is 1, not all inputs are 1.
    check_high_implies_not_all_ones: assert property (
        @(posedge clk) (Y == 1'b1) |-> !((A == 1'b1) && (B == 1'b1) && (C == 1'b1))
    );

    // If inputs are stable across a cycle, Y must also be stable.
    check_stable_when_inputs_stable: assert property (
        @(posedge clk) ($stable(A) && $stable(B) && $stable(C)) |-> $stable(Y)
    );

    // A falling edge on Y implies all inputs are 1 now.
    check_y_fall_requires_all_ones: assert property (
        @(posedge clk) $fell(Y) |-> (A == 1'b1 && B == 1'b1 && C == 1'b1)
    );

    // A rising edge on Y implies at least one input is 0 now.
    check_y_rise_requires_any_zero: assert property (
        @(posedge clk) $rose(Y) |-> (A == 1'b0 || B == 1'b0 || C == 1'b0)
    );
endmodule

module dff_async_reset_sva (
    input logic clk,
    input logic reset,
    input logic d,
    input logic q
);
    // Q matches previous D on cycles following a non-reset cycle.
    check_capture_from_d_prev_not_reset: assert property (
        @(posedge clk) disable iff (!reset)
            ($past(reset) == 1'b1) |-> (q == $past(d))
    );

    // Q is 0 on any cycle immediately following a cycle with reset low.
    check_q_zero_after_prev_reset_low: assert property (
        @(posedge clk) disable iff (!reset)
            ($past(reset) == 1'b0) |-> (q == 1'b0)
    );

    // Rising edge on D with reset high drives Q to 1 on the next clock.
    check_d_rise_sets_q_next: assert property (
        @(posedge clk) disable iff (!reset)
            (reset && $rose(d)) |=> (q == 1'b1)
    );

    // Falling edge on D with reset high drives Q to 0 on the next clock.
    check_d_fall_clears_q_next: assert property (
        @(posedge clk) disable iff (!reset)
            (reset && $fell(d)) |=> (q == 1'b0)
    );

    // When reset high and D equals current Q, Q holds its value next cycle.
    check_q_holds_when_d_equals_q: assert property (
        @(posedge clk) disable iff (!reset)
            (reset && (d == q)) |=> (q == $past(q))
    );

    // With no reset over two cycles and stable D, Q remains stable across cycles.
    check_q_stable_when_d_stable: assert property (
        @(posedge clk) disable iff (!reset)
            (($past(reset) == 1'b1) && (reset == 1'b1) && (d == $past(d))) |=> (q == $past(q))
    );
endmodule

rtl:
module multiplier (
    input [3:0] a,
    input [3:0] b,
    output [7:0] product
);

reg [3:0] a_reg, b_reg;
reg [7:0] product_reg;

always @(*) begin
    a_reg = a;
    b_reg = b;
    product_reg = a_reg * b_reg;
end

assign product = product_reg;

endmodule

sva:
module multiplier_sva (
    input logic clk,
    input logic [3:0] a,
    input logic [3:0] b,
    input logic [7:0] product
);
    // Product equals mathematical multiplication of a and b.
    check_product_equals_multiply: assert property (
        @(posedge clk) disable iff (1'b0) product == (a * b)
    );

    // If either input is zero then product is zero.
    check_zero_input_drives_zero_output: assert property (
        @(posedge clk) disable iff (1'b0) ((a == 4'd0) || (b == 4'd0)) |-> (product == 8'd0)
    );

    // If a is 1 then product equals b (zero-extended).
    check_identity_when_a_is_one: assert property (
        @(posedge clk) disable iff (1'b0) (a == 4'd1) |-> (product == {4'b0, b})
    );

    // If b is 1 then product equals a (zero-extended).
    check_identity_when_b_is_one: assert property (
        @(posedge clk) disable iff (1'b0) (b == 4'd1) |-> (product == {4'b0, a})
    );

    // Product never exceeds 15*15 = 225.
    check_product_upper_bound_225: assert property (
        @(posedge clk) disable iff (1'b0) product <= 8'd225
    );

    // LSB of product equals AND of LSBs of inputs.
    check_lsb_equals_and_of_lsbs: assert property (
        @(posedge clk) disable iff (1'b0) product[0] == (a[0] & b[0])
    );

    // If inputs are stable, product must be stable.
    check_output_stable_if_inputs_stable: assert property (
        @(posedge clk) disable iff (1'b0) ($stable(a) && $stable(b)) |-> $stable(product)
    );

    // If product changes, at least one input must have changed.
    check_output_change_requires_input_change: assert property (
        @(posedge clk) disable iff (1'b0) $changed(product) |-> ($changed(a) || $changed(b))
    );

    // Product equals sum of shifted partial products based on b bits.
    check_partial_product_expansion_matches: assert property (
        @(posedge clk) disable iff (1'b0)
            product == (
                (b[0] ? {4'b0, a}           : 8'd0) +
                (b[1] ? {3'b0, a, 1'b0}     : 8'd0) +
                (b[2] ? {2'b0, a, 2'b0}     : 8'd0) +
                (b[3] ? {1'b0, a, 3'b0}     : 8'd0)
            )
    );

    // Specific max case: 15*15 equals 225.
    check_specific_max_case_15x15: assert property (
        @(posedge clk) disable iff (1'b0) ((a == 4'd15) && (b == 4'd15)) |-> (product == 8'd225)
    );
endmodule

rtl:
module crossbar36
  (input clk, input reset, input clear,
   input cross,
   input [35:0] data0_i, input src0_rdy_i, output dst0_rdy_o,
   input [35:0] data1_i, input src1_rdy_i, output dst1_rdy_o,
   output [35:0] data0_o, output src0_rdy_o, input dst0_rdy_i,
   output [35:0] data1_o, output src1_rdy_o, input dst1_rdy_i);

   reg 		 cross_int, active0, active1;
   wire active0_next = (src0_rdy_i & dst0_rdy_o)? ~data0_i[33] : active0;
   wire active1_next = (src1_rdy_i & dst1_rdy_o)? ~data1_i[33] : active1;

   assign data0_o = cross_int ? data1_i : data0_i;
   assign data1_o = cross_int ? data0_i : data1_i;

   assign src0_rdy_o = cross_int ? src1_rdy_i : src0_rdy_i;
   assign src1_rdy_o = cross_int ? src0_rdy_i : src1_rdy_i;

   assign dst0_rdy_o = cross_int ? dst1_rdy_i : dst0_rdy_i;
   assign dst1_rdy_o = cross_int ? dst0_rdy_i : dst1_rdy_i;

   always @(posedge clk)
     if(reset | clear)
       active0 <= 0;
     else
       active0 <= active0_next;

   always @(posedge clk)
     if(reset | clear)
       active1 <= 0;
     else
       active1 <= active1_next;

   always @(posedge clk)
     if(reset | clear)
       cross_int <= 0;
     else if(~active0_next & ~active1_next)
       cross_int <= cross;

endmodule

sva:
module crossbar36_sva (
    input logic clk,
    input logic reset,
    input logic clear,
    input logic cross,
    input logic [35:0] data0_i,
    input logic src0_rdy_i,
    input logic dst0_rdy_o,
    input logic [35:0] data1_i,
    input logic src1_rdy_i,
    input logic dst1_rdy_o,
    input logic [35:0] data0_o,
    input logic src0_rdy_o,
    input logic dst0_rdy_i,
    input logic [35:0] data1_o,
    input logic src1_rdy_o,
    input logic dst1_rdy_i,
    // Internal signals from RTL
    input logic cross_int,
    input logic active0,
    input logic active1,
    input logic active0_next,
    input logic active1_next
);

    ///// Reset behavior /////
    // Reset/clear drives active0 LOW.
    reset_active0_low: assert property (
        @(posedge clk) (reset | clear) |-> (active0 == 1'b0)
    );
    // Reset/clear drives active1 LOW.
    reset_active1_low: assert property (
        @(posedge clk) (reset | clear) |-> (active1 == 1'b0)
    );
    // Reset/clear drives cross_int LOW.
    reset_cross_int_low: assert property (
        @(posedge clk) (reset | clear) |-> (cross_int == 1'b0)
    );

    ///// Crossbar muxing /////
    // When not crossed, all channels are pass-through.
    mux_passthrough_when_no_cross: assert property (
        @(posedge clk) disable iff (reset | clear)
            (cross_int == 1'b0)
            |-> (data0_o == data0_i)
             && (data1_o == data1_i)
             && (src0_rdy_o == src0_rdy_i)
             && (src1_rdy_o == src1_rdy_i)
             && (dst0_rdy_o == dst0_rdy_i)
             && (dst1_rdy_o == dst1_rdy_i)
    );
    // When crossed, channels are swapped.
    mux_swap_when_cross: assert property (
        @(posedge clk) disable iff (reset | clear)
            (cross_int == 1'b1)
            |-> (data0_o == data1_i)
             && (data1_o == data0_i)
             && (src0_rdy_o == src1_rdy_i)
             && (src1_rdy_o == src0_rdy_i)
             && (dst0_rdy_o == dst1_rdy_i)
             && (dst1_rdy_o == dst0_rdy_i)
    );

    ///// Channel activity tracking /////
    // On handshake, active0 loads inverted data0_i[33] on next cycle.
    active0_updates_on_handshake: assert property (
        @(posedge clk) disable iff (reset | clear)
            ($past(! (reset | clear)) && $past(src0_rdy_i & dst0_rdy_o))
            |-> (active0 == ~ $past(data0_i[33]))
    );
    // Without handshake, active0 holds its previous value.
    active0_holds_without_handshake: assert property (
        @(posedge clk) disable iff (reset | clear)
            ($past(! (reset | clear)) && !$past(src0_rdy_i & dst0_rdy_o))
            |-> (active0 == $past(active0))
    );
    // On handshake, active1 loads inverted data1_i[33] on next cycle.
    active1_updates_on_handshake: assert property (
        @(posedge clk) disable iff (reset | clear)
            ($past(! (reset | clear)) && $past(src1_rdy_i & dst1_rdy_o))
            |-> (active1 == ~ $past(data1_i[33]))
    );
    // Without handshake, active1 holds its previous value.
    active1_holds_without_handshake: assert property (
        @(posedge clk) disable iff (reset | clear)
            ($past(! (reset | clear)) && !$past(src1_rdy_i & dst1_rdy_o))
            |-> (active1 == $past(active1))
    );

    ///// Cross selection update rules /////
    // cross_int may change only when both active*_next were 0 in the previous cycle.
    cross_int_changes_only_when_idle: assert property (
        @(posedge clk) disable iff (reset | clear)
            ($past(! (reset | clear)) && $changed(cross_int))
            |-> $past((~active0_next) & (~active1_next))
    );
    // If either channel was active in the previous cycle, cross_int holds.
    cross_int_holds_when_busy: assert property (
        @(posedge clk) disable iff (reset | clear)
            ($past(! (reset | clear)) && !$past((~active0_next) & (~active1_next)))
            |-> (cross_int == $past(cross_int))
    );
    // When both were idle in the previous cycle, cross_int loads cross.
    cross_int_updates_from_cross_when_idle: assert property (
        @(posedge clk) disable iff (reset | clear)
            ($past(! (reset | clear)) && $past((~active0_next) & (~active1_next)))
            |-> (cross_int == $past(cross))
    );

endmodule

rtl:
module mux4(sel1, sel0, in0, in1, in2, in3, out);
  input sel1, sel0, in0, in1, in2, in3;
  output reg out;

  always @ (*)
    case ({sel1, sel0})
      2'b00: out = in0;
      2'b01: out = in1;
      2'b10: out = in2;
      2'b11: out = in3;
    endcase

endmodule

sva:
module mux4_sva (
    input logic sel1,
    input logic sel0,
    input logic in0,
    input logic in1,
    input logic in2,
    input logic in3,
    input logic out
);
    ///// Functional mapping /////
    // When sel=00, out equals in0.
    check_map_00: assert property (
        @(posedge sel1 or negedge sel1 or posedge sel0 or negedge sel0 or
          posedge in0 or negedge in0 or posedge in1 or negedge in1 or
          posedge in2 or negedge in2 or posedge in3 or negedge in3 or
          posedge out or negedge out)
        ((sel1 == 1'b0) && (sel0 == 1'b0)) |-> (out == in0)
    );

    // When sel=01, out equals in1.
    check_map_01: assert property (
        @(posedge sel1 or negedge sel1 or posedge sel0 or negedge sel0 or
          posedge in0 or negedge in0 or posedge in1 or negedge in1 or
          posedge in2 or negedge in2 or posedge in3 or negedge in3 or
          posedge out or negedge out)
        ((sel1 == 1'b0) && (sel0 == 1'b1)) |-> (out == in1)
    );

    // When sel=10, out equals in2.
    check_map_10: assert property (
        @(posedge sel1 or negedge sel1 or posedge sel0 or negedge sel0 or
          posedge in0 or negedge in0 or posedge in1 or negedge in1 or
          posedge in2 or negedge in2 or posedge in3 or negedge in3 or
          posedge out or negedge out)
        ((sel1 == 1'b1) && (sel0 == 1'b0)) |-> (out == in2)
    );

    // When sel=11, out equals in3.
    check_map_11: assert property (
        @(posedge sel1 or negedge sel1 or posedge sel0 or negedge sel0 or
          posedge in0 or negedge in0 or posedge in1 or negedge in1 or
          posedge in2 or negedge in2 or posedge in3 or negedge in3 or
          posedge out or negedge out)
        ((sel1 == 1'b1) && (sel0 == 1'b1)) |-> (out == in3)
    );

    ///// Stability with selects and selected input held /////
    // If sel=00 and sel/in0 stable, out remains stable.
    hold_out_when_00_and_in0_stable: assert property (
        @(posedge sel1 or negedge sel1 or posedge sel0 or negedge sel0 or
          posedge in0 or negedge in0 or posedge in1 or negedge in1 or
          posedge in2 or negedge in2 or posedge in3 or negedge in3 or
          posedge out or negedge out)
        ((sel1 == 1'b0) && (sel0 == 1'b0) && $stable(sel1) && $stable(sel0) && $stable(in0)) |-> $stable(out)
    );

    // If sel=01 and sel/in1 stable, out remains stable.
    hold_out_when_01_and_in1_stable: assert property (
        @(posedge sel1 or negedge sel1 or posedge sel0 or negedge sel0 or
          posedge in0 or negedge in0 or posedge in1 or negedge in1 or
          posedge in2 or negedge in2 or posedge in3 or negedge in3 or
          posedge out or negedge out)
        ((sel1 == 1'b0) && (sel0 == 1'b1) && $stable(sel1) && $stable(sel0) && $stable(in1)) |-> $stable(out)
    );

    // If sel=10 and sel/in2 stable, out remains stable.
    hold_out_when_10_and_in2_stable: assert property (
        @(posedge sel1 or negedge sel1 or posedge sel0 or negedge sel0 or
          posedge in0 or negedge in0 or posedge in1 or negedge in1 or
          posedge in2 or negedge in2 or posedge in3 or negedge in3 or
          posedge out or negedge out)
        ((sel1 == 1'b1) && (sel0 == 1'b0) && $stable(sel1) && $stable(sel0) && $stable(in2)) |-> $stable(out)
    );

    // If sel=11 and sel/in3 stable, out remains stable.
    hold_out_when_11_and_in3_stable: assert property (
        @(posedge sel1 or negedge sel1 or posedge sel0 or negedge sel0 or
          posedge in0 or negedge in0 or posedge in1 or negedge in1 or
          posedge in2 or negedge in2 or posedge in3 or negedge in3 or
          posedge out or negedge out)
        ((sel1 == 1'b1) && (sel0 == 1'b1) && $stable(sel1) && $stable(sel0) && $stable(in3)) |-> $stable(out)
    );

    ///// Out changes only when selected input changes (with selects held) /////
    // If sel=00 held and out changes, in0 must have changed.
    out_change_implies_in0_change_when_00: assert property (
        @(posedge sel1 or negedge sel1 or posedge sel0 or negedge sel0 or
          posedge in0 or negedge in0 or posedge in1 or negedge in1 or
          posedge in2 or negedge in2 or posedge in3 or negedge in3 or
          posedge out or negedge out)
        ((sel1 == 1'b0) && (sel0 == 1'b0) && $stable(sel1) && $stable(sel0) && $changed(out)) |-> $changed(in0)
    );

    // If sel=01 held and out changes, in1 must have changed.
    out_change_implies_in1_change_when_01: assert property (
        @(posedge sel1 or negedge sel1 or posedge sel0 or negedge sel0 or
          posedge in0 or negedge in0 or posedge in1 or negedge in1 or
          posedge in2 or negedge in2 or posedge in3 or negedge in3 or
          posedge out or negedge out)
        ((sel1 == 1'b0) && (sel0 == 1'b1) && $stable(sel1) && $stable(sel0) && $changed(out)) |-> $changed(in1)
    );

    // If sel=10 held and out changes, in2 must have changed.
    out_change_implies_in2_change_when_10: assert property (
        @(posedge sel1 or negedge sel1 or posedge sel0 or negedge sel0 or
          posedge in0 or negedge in0 or posedge in1 or negedge in1 or
          posedge in2 or negedge in2 or posedge in3 or negedge in3 or
          posedge out or negedge out)
        ((sel1 == 1'b1) && (sel0 == 1'b0) && $stable(sel1) && $stable(sel0) && $changed(out)) |-> $changed(in2)
    );

    // If sel=11 held and out changes, in3 must have changed.
    out_change_implies_in3_change_when_11: assert property (
        @(posedge sel1 or negedge sel1 or posedge sel0 or negedge sel0 or
          posedge in0 or negedge in0 or posedge in1 or negedge in1 or
          posedge in2 or negedge in2 or posedge in3 or negedge in3 or
          posedge out or negedge out)
        ((sel1 == 1'b1) && (sel0 == 1'b1) && $stable(sel1) && $stable(sel0) && $changed(out)) |-> $changed(in3)
    );
endmodule

