module comb_circuit_sva (
    input logic clk,
    input logic [3:0] in,
    input logic [2:0] out
);
    // Analysis: No reset; combinational logic only; sample assertions on an external clock.
    // Behavior: out = (in < 4) ? (in + 1)[2:0] : (in - 1)[2:0].

    // For in < 4, out equals in + 1 (3-bit result).
    check_low_range_function: assert property (
        @(posedge clk) (in < 4'd4) |-> (out == (in[2:0] + 3'd1))
    );

    // For in >= 4, out equals in - 1 (3-bit result).
    check_high_range_function: assert property (
        @(posedge clk) (in >= 4'd4) |-> (out == (in[2:0] - 3'd1))
    );

    // Boundary: in == 3 maps to out == 4.
    check_boundary_in3_out4: assert property (
        @(posedge clk) (in == 4'd3) |-> (out == 3'd4)
    );

    // Boundary: in == 4 maps to out == 3.
    check_boundary_in4_out3: assert property (
        @(posedge clk) (in == 4'd4) |-> (out == 3'd3)
    );

    // Corner: in == 0 maps to out == 1.
    check_in0_out1: assert property (
        @(posedge clk) (in == 4'd0) |-> (out == 3'd1)
    );

    // If input is stable across a cycle, output must be stable.
    check_out_stable_if_in_stable: assert property (
        @(posedge clk) $stable(in) |-> $stable(out)
    );

    // In low range, if input increments by 1 and stays <4, output increments by 1.
    check_inc_in_low_range_updates_out: assert property (
        @(posedge clk) (($past(in) < 4'd4) && (in < 4'd4) && (in == $past(in) + 4'd1)) |-> (out == $past(out) + 3'd1)
    );

    // In low range, if input decrements by 1 and stays <4, output decrements by 1.
    check_dec_in_low_range_updates_out: assert property (
        @(posedge clk) (($past(in) < 4'd4) && (in < 4'd4) && ($past(in) == in + 4'd1)) |-> (out == $past(out) - 3'd1)
    );

    // In high range, if input increments by 1 and stays >=4, output increments by 1.
    check_inc_in_high_range_updates_out: assert property (
        @(posedge clk) (($past(in) >= 4'd4) && (in >= 4'd4) && (in == $past(in) + 4'd1)) |-> (out == $past(out) + 3'd1)
    );

    // In high range, if input decrements by 1 and stays >=4, output decrements by 1.
    check_dec_in_high_range_updates_out: assert property (
        @(posedge clk) (($past(in) >= 4'd4) && (in >= 4'd4) && ($past(in) == in + 4'd1)) |-> (out == $past(out) - 3'd1)
    );
endmodule

rtl:
module ripple_carry_adder (
    input [3:0] in0,
    input [3:0] in1,
    input carry_in,
    output [3:0] sum,
    output carry_out
);

wire [3:0] stage1_sum;
wire stage1_carry;

wire [3:0] stage2_sum;
wire stage2_carry;

wire [3:0] stage3_sum;
wire stage3_carry;

// Stage 1
full_adder fa1(in0[0], in1[0], carry_in, stage1_sum[0], stage1_carry);

// Stage 2
full_adder fa2(in0[1], in1[1], stage1_carry, stage2_sum[1], stage2_carry);

// Stage 3
full_adder fa3(in0[2], in1[2], stage2_carry, stage3_sum[2], stage3_carry);

// Stage 4
full_adder fa4(in0[3], in1[3], stage3_carry, sum[3], carry_out);

assign sum[0] = stage1_sum[0];
assign sum[1] = stage2_sum[1];
assign sum[2] = stage3_sum[2];

endmodule

module full_adder (
    input a,
    input b,
    input carry_in,
    output sum,
    output carry_out
);

assign sum = a ^ b ^ carry_in;
assign carry_out = (a & b) | (a & carry_in) | (b & carry_in);

endmodule

sva:
module ripple_carry_adder_sva (
    input  logic        CLK,
    input  logic [3:0]  in0,
    input  logic [3:0]  in1,
    input  logic        carry_in,
    input  logic [3:0]  sum,
    input  logic        carry_out
);

    // Helper expressions for ripple carries and full 5-bit result
    let c0   = (in0[0] & in1[0]) | (in0[0] & carry_in) | (in1[0] & carry_in);
    let c1   = (in0[1] & in1[1]) | (in0[1] & c0)       | (in1[1] & c0);
    let c2   = (in0[2] & in1[2]) | (in0[2] & c1)       | (in1[2] & c1);
    let res5 = ({1'b0,in0} + {1'b0,in1} + carry_in);

    // The 5-bit {carry_out,sum} equals in0 + in1 + carry_in.
    check_add_result_5bit: assert property (
        @(posedge CLK) disable iff (1'b0) {carry_out, sum} == res5
    );

    // sum[0] equals XOR of LSBs and carry_in.
    check_sum0_xor: assert property (
        @(posedge CLK) disable iff (1'b0) sum[0] == (in0[0] ^ in1[0] ^ carry_in)
    );

    // sum[1] equals XOR of bit1s and carry from bit0.
    check_sum1_xor: assert property (
        @(posedge CLK) disable iff (1'b0) sum[1] == (in0[1] ^ in1[1] ^ c0)
    );

    // sum[2] equals XOR of bit2s and carry from bit1.
    check_sum2_xor: assert property (
        @(posedge CLK) disable iff (1'b0) sum[2] == (in0[2] ^ in1[2] ^ c1)
    );

    // sum[3] equals XOR of bit3s and carry from bit2.
    check_sum3_xor: assert property (
        @(posedge CLK) disable iff (1'b0) sum[3] == (in0[3] ^ in1[3] ^ c2)
    );

    // carry_out is the majority of bit3s and carry from bit2.
    check_carry_out_majority: assert property (
        @(posedge CLK) disable iff (1'b0) carry_out == ((in0[3] & in1[3]) | (in0[3] & c2) | (in1[3] & c2))
    );

    // The 4-bit sum equals the low 4 bits of the arithmetic result.
    check_sum_low_bits_match: assert property (
        @(posedge CLK) disable iff (1'b0) sum == res5[3:0]
    );

    // If inputs are stable across a cycle, outputs remain stable.
    check_stability_on_stable_inputs: assert property (
        @(posedge CLK) disable iff (1'b0)
            (in0 == $past(in0) && in1 == $past(in1) && carry_in == $past(carry_in))
            |-> (sum == $past(sum) && carry_out == $past(carry_out))
    );

    // With in0/in1 stable, a rising carry_in increments the 5-bit result by 1.
    check_increment_on_cin_rise: assert property (
        @(posedge CLK) disable iff (1'b0)
            (in0 == $past(in0) && in1 == $past(in1) && $rose(carry_in))
            |-> ({carry_out, sum} == $past({carry_out, sum}) + 5'd1)
    );

    // With in0/in1 stable, a falling carry_in decrements the 5-bit result by 1.
    check_decrement_on_cin_fall: assert property (
        @(posedge CLK) disable iff (1'b0)
            (in0 == $past(in0) && in1 == $past(in1) && $fell(carry_in))
            |-> ({carry_out, sum} == $past({carry_out, sum}) - 5'd1)
    );

endmodule

module synchronous_counter_sva (
  input logic clk,
  input logic rst,
  input logic en,
  input logic [3:0] count
);
  ///// Reset behavior /////
  // Synchronous reset drives count to zero on the clock edge.
  check_reset_clears_count: assert property (
    @(posedge clk) rst |-> (count == 4'd0)
  );

  // While reset is held across cycles, count stays zero and stable.
  check_continuous_reset_holds_zero: assert property (
    @(posedge clk) (rst && $past(rst)) |-> (count == 4'd0 && $stable(count))
  );

  // On reset deassert with en=0, count remains zero in that cycle.
  check_deassert_reset_en0_keeps_zero: assert property (
    @(posedge clk) ($fell(rst) && (en == 1'b0)) |-> (count == 4'd0)
  );

  // On reset deassert with en=1, count becomes one in that cycle.
  check_deassert_reset_en1_sets_one: assert property (
    @(posedge clk) ($fell(rst) && (en == 1'b1)) |-> (count == 4'd1)
  );

  ///// Enable and increment semantics /////
  // With en=1 (and no reset), count increments by one on the next cycle.
  check_increment_when_en_high: assert property (
    @(posedge clk) disable iff (rst) (en == 1'b1) |=> (count == $past(count) + 4'd1)
  );

  // With en=0 (and no reset), count holds its value on the next cycle.
  check_hold_when_en_low: assert property (
    @(posedge clk) disable iff (rst) (en == 1'b0) |=> (count == $past(count))
  );

  // If en=1 at count==15, next count wraps to zero.
  check_wrap_on_max: assert property (
    @(posedge clk) disable iff (rst) (en && (count == 4'hF)) |=> (count == 4'd0)
  );

  // Any change in count (no reset) implies en=1 and step is exactly +1 (mod 16).
  check_change_requires_en_and_plus1: assert property (
    @(posedge clk) disable iff (rst) $changed(count) |-> (en && (count == $past(count) + 4'd1))
  );

  // Two consecutive cycles of en=1 advance count by two.
  check_two_consecutive_en_increments_by2: assert property (
    @(posedge clk) disable iff (rst) (en ##1 en) |=> (count == $past(count,2) + 4'd2)
  );

  // en=1 then en=0 over two cycles advances count by one total.
  check_en_then_hold_advances_by1: assert property (
    @(posedge clk) disable iff (rst) (en ##1 !en) |=> (count == $past(count,2) + 4'd1)
  );

  // Two consecutive cycles of en=0 cause no change over those two cycles.
  check_two_cycles_no_en_no_change: assert property (
    @(posedge clk) disable iff (rst) (!en ##1 !en) |=> (count == $past(count,2))
  );
endmodule

