module clock_module(input wire inclk0,
                    output wire c0,
                    output wire c1,
                    output wire locked,
                    output wire e0);

    assign c0 = inclk0;
    assign c1 = inclk0;
    assign locked = 1;
    assign e0 = ~inclk0;

endmodule

sva:
module clock_module_sva (
    input logic inclk0,
    input logic c0,
    input logic c1,
    input logic locked,
    input logic e0
);
    // c0 must equal inclk0.
    check_c0_eq_inclk0: assert property (
        @(posedge inclk0) c0 == inclk0
    );

    // c1 must equal inclk0.
    check_c1_eq_inclk0: assert property (
        @(posedge inclk0) c1 == inclk0
    );

    // e0 must be the inversion of inclk0.
    check_e0_inverts_inclk0: assert property (
        @(posedge inclk0) e0 == ~inclk0
    );

    // locked must be constantly HIGH.
    check_locked_constant_high: assert property (
        @(posedge inclk0) locked == 1'b1
    );

    // c0 and c1 must always be equal.
    check_c0_c1_equal: assert property (
        @(posedge inclk0) c0 == c1
    );

    // e0 must be the inversion of c0.
    check_e0_inverts_c0: assert property (
        @(posedge inclk0) e0 == ~c0
    );

    // On inclk0 posedge, outputs reflect expected phase: c0=1, c1=1, e0=0.
    check_posedge_phase_values: assert property (
        @(posedge inclk0) (c0 == 1'b1) && (c1 == 1'b1) && (e0 == 1'b0)
    );
endmodule

rtl:
module top_module (
    input [3:0] A,
    input [3:0] B,
    input enable,
    output reg [3:0] q
);

  wire greater_or_equal;
  magnitude_comparator comparator(A, B, greater_or_equal);

  always @ (greater_or_equal, enable) begin
    if (greater_or_equal & enable) begin
      q <= A;
    end else begin
      q <= B;
    end
  end

endmodule

module magnitude_comparator (
    input [3:0] A,
    input [3:0] B,
    output reg greater_or_equal
);

  always @ (A, B) begin
    if (A >= B) begin
      greater_or_equal <= 1;
    end else begin
      greater_or_equal <= 0;
    end
  end

endmodule

sva:
module top_module_sva (
    input logic CLK,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic enable,
    input logic [3:0] q
);
    ///// Combinational selection rules /////
    // When enable is LOW, q equals B.
    check_q_equals_B_when_enable_low: assert property (
        @(posedge CLK) disable iff (1'b0) (!enable) |-> (q == B)
    );

    // When enable is HIGH and A >= B, q equals A.
    check_q_equals_A_when_enable_high_and_A_ge_B: assert property (
        @(posedge CLK) disable iff (1'b0) (enable && (A >= B)) |-> (q == A)
    );

    // When enable is HIGH and A < B, q equals B.
    check_q_equals_B_when_enable_high_and_A_lt_B: assert property (
        @(posedge CLK) disable iff (1'b0) (enable && (A < B)) |-> (q == B)
    );

    // If A < B, q must be B regardless of enable.
    check_q_equals_B_when_A_lt_B: assert property (
        @(posedge CLK) disable iff (1'b0) (A < B) |-> (q == B)
    );

    // q is always either A or B.
    check_q_is_A_or_B: assert property (
        @(posedge CLK) disable iff (1'b0) ((q == A) || (q == B))
    );

    // Functional equivalence: q == (enable && (A >= B) ? A : B).
    check_mux_equivalence: assert property (
        @(posedge CLK) disable iff (1'b0) (q == ((enable && (A >= B)) ? A : B))
    );

    // When A == B and enable is HIGH, q equals A.
    check_equal_inputs_with_enable: assert property (
        @(posedge CLK) disable iff (1'b0) (enable && (A == B)) |-> (q == A)
    );

    // When A == B and enable is LOW, q equals B.
    check_equal_inputs_without_enable: assert property (
        @(posedge CLK) disable iff (1'b0) (!enable && (A == B)) |-> (q == B)
    );
endmodule

rtl:
module counter (
  input clk,
  input reset,
  output reg [7:0] count
);

  always @(posedge clk) begin
    if (reset) begin
      count <= 8'b0;
    end else begin
      count <= count + 1;
    end
  end

endmodule

sva:
module counter_sva (
    input logic clk,
    input logic reset,
    input logic [7:0] count
);

    // Synchronous reset drives count to zero on the next clock.
    check_reset_clears_next: assert property (
        @(posedge clk) reset |=> (count == 8'h00)
    );

    // While reset is held across cycles, count remains zero.
    check_reset_held_forces_zero: assert property (
        @(posedge clk) (reset && $past(reset)) |-> (count == 8'h00)
    );

    // When not in reset and previous count was not 0xFF, count increments by 1.
    check_increment_no_wrap: assert property (
        @(posedge clk) disable iff (reset)
            ($past(count) != 8'hFF) |-> (count == $past(count) + 8'd1)
    );

    // When not in reset and previous count was 0xFF, count wraps to 0x00.
    check_wrap_from_ff: assert property (
        @(posedge clk) disable iff (reset)
            ($past(count) == 8'hFF) |-> (count == 8'h00)
    );

    // On reset deassertion (1->0), the first not-reset cycle produces count == 1.
    check_first_cycle_after_reset_deassert: assert property (
        @(posedge clk) disable iff (reset)
            $fell(reset) |-> (count == 8'h01)
    );

    // When not in reset and no wrap, count strictly increases.
    check_monotonic_increase_no_wrap: assert property (
        @(posedge clk) disable iff (reset)
            ($past(count) != 8'hFF) |-> (count > $past(count))
    );

endmodule

module counter_sva (
    input logic clk,
    input logic rst_n,
    input logic [3:0] counter_out
);
    ///// Reset behavior /////
    // While reset is asserted (active-low), counter_out is 0.
    check_reset_forces_zero: assert property (
        @(posedge clk) (!rst_n) |-> (counter_out == 4'b0000)
    );

    // If reset was asserted in the previous cycle, the previous counter value was 0.
    check_prev_cycle_reset_value_zero: assert property (
        @(posedge clk) $past(!rst_n) |-> ($past(counter_out) == 4'b0000)
    );

    ///// Release from reset /////
    // On the first cycle after reset deasserts, counter_out becomes 1.
    check_first_value_after_reset_is_one: assert property (
        @(posedge clk) $rose(rst_n) |-> (counter_out == 4'd1)
    );

    ///// Counting step that is always safe /////
    // When not in reset and previous value was 0, the next value is 1.
    check_zero_advances_to_one: assert property (
        @(posedge clk) disable iff (!rst_n) ($past(counter_out) == 4'd0) |-> (counter_out == 4'd1)
    );
endmodule

rtl:
module d_ffsr(CLK, D, S, R, Q, QN);
  input CLK, D, S, R;
  output Q, QN;
  reg Q;

  always @(posedge CLK) begin
    if (S == 1'b1) begin
      Q <= 1'b1;
    end else if (R == 1'b1) begin
      Q <= 1'b0;
    end else begin
      Q <= D;
    end
  end

  assign QN = ~Q;

endmodule

sva:
module d_ffsr_sva (
    input logic CLK,
    input logic D,
    input logic S,
    input logic R,
    input logic Q,
    input logic QN
);
    ///// Synchronous set/reset and data load behavior /////
    // S asserted sets Q to 1 on the next clock (S has priority).
    check_sync_set_dominates: assert property (
        @(posedge CLK) disable iff (1'b0) (S == 1'b1) |=> (Q == 1'b1)
    );

    // R asserted with S deasserted clears Q to 0 on the next clock.
    check_sync_reset_when_no_set: assert property (
        @(posedge CLK) disable iff (1'b0) (S == 1'b0 && R == 1'b1) |=> (Q == 1'b0)
    );

    // When both S and R are asserted, S dominates and Q becomes 1 on the next clock.
    check_priority_s_over_r: assert property (
        @(posedge CLK) disable iff (1'b0) (S == 1'b1 && R == 1'b1) |=> (Q == 1'b1)
    );

    // With S=0 and R=0, Q loads D sampled at the same edge.
    check_data_load_when_no_ctrl: assert property (
        @(posedge CLK) disable iff (1'b0) ##1 ($past(S)==1'b0 && $past(R)==1'b0) |-> (Q == $past(D))
    );

    // If no control and D equals prior Q, Q holds its value across the next cycle.
    check_hold_when_d_equals_prev_q: assert property (
        @(posedge CLK) disable iff (1'b0) ##1 ($past(S)==1'b0 && $past(R)==1'b0 && ($past(D) == $past(Q))) |-> (Q == $past(Q))
    );

    // Any change in Q is justified by prior S/R/D values.
    check_q_change_has_cause: assert property (
        @(posedge CLK) disable iff (1'b0)
            ##1 $changed(Q) |-> (
                ($past(S) == 1'b1 && $past(Q) != 1'b1) ||
                ($past(S) == 1'b0 && $past(R) == 1'b1 && $past(Q) != 1'b0) ||
                ($past(S) == 1'b0 && $past(R) == 1'b0 && $past(D) != $past(Q))
            )
    );

    ///// Output relationship /////
    // QN is always the logical complement of Q.
    check_qn_is_complement_of_q: assert property (
        @(posedge CLK) disable iff (1'b0) (QN == ~Q)
    );

    // Q and QN are never equal.
    check_q_qn_never_equal: assert property (
        @(posedge CLK) disable iff (1'b0) (Q != QN)
    );

    // QN changes iff Q changes between consecutive clocks.
    check_qn_changes_iff_q_changes: assert property (
        @(posedge CLK) disable iff (1'b0) ##1 1'b1 |-> ($changed(QN) == $changed(Q))
    );

    ///// Functional summary check /////
    // Next Q equals: S?1 : (R?0 : D) using prior-cycle inputs.
    check_next_q_truth_table: assert property (
        @(posedge CLK) disable iff (1'b0)
            ##1 1'b1 |-> (Q == ($past(S) ? 1'b1 : ($past(R) ? 1'b0 : $past(D))))
    );
endmodule

rtl:
module four_bit_register (input clk, input [3:0] din, output [3:0] dout);
    reg [3:0] reg_data;

    always @(posedge clk) begin
        reg_data <= din;
    end

    assign dout = reg_data;
endmodule

sva:
module four_bit_register_sva (
    input logic clk,
    input logic [3:0] din,
    input logic [3:0] dout
);
    // dout equals din from previous clock (1-cycle latency).
    check_dout_one_cycle_latency: assert property (
        @(posedge clk) !$isunknown($past(din)) |-> (dout == $past(din))
    );

    // A change on din causes a change on dout one cycle later.
    check_change_propagation: assert property (
        @(posedge clk) (!$isunknown($past(din)) && (din != $past(din))) |=> (dout != $past(dout))
    );

    // If din is stable between clocks, dout is stable on the next cycle.
    check_stability_propagation: assert property (
        @(posedge clk) (!$isunknown($past(din)) && (din == $past(din))) |=> (dout == $past(dout))
    );

    // Per-bit 1-cycle latency from din[i] to dout[i].
    genvar i;
    generate
        for (i = 0; i < 4; i++) begin : gen_bit_latency
            // dout[i] equals din[i] from previous clock.
            check_bit_latency: assert property (
                @(posedge clk) !$isunknown($past(din[i])) |-> (dout[i] == $past(din[i]))
            );
        end
    endgenerate
endmodule

rtl:
module four_bit_adder (
    input [3:0] a,
    input [3:0] b,
    input cin,
    output [3:0] sum,
    output cout
);

    wire [3:0] c;
    assign c[0] = cin;
    assign c[1] = 0;
    assign c[2] = 0;
    assign c[3] = 0;
    assign {cout, sum} = a + b + c;

endmodule

sva:
module four_bit_adder_sva (
    input logic [3:0] a,
    input logic [3:0] b,
    input logic       cin,
    input logic [3:0] sum,
    input logic       cout
);
    ///// Functional equivalence checks /////
    // {cout,sum} equals zero-extended 4-bit (a + b + cin).
    check_concat_zero_extended: assert property (
        @(posedge cin) {cout, sum} == {1'b0, (a + b + cin)}
    );
    // cout is always 0 (addition width is 4 bits on RHS).
    check_cout_always_zero: assert property (
        @(posedge cin) cout == 1'b0
    );
    // sum equals 4-bit (a + b + cin) modulo 16.
    check_sum_mod_add: assert property (
        @(posedge cin) sum == (a + b + cin)
    );

    ///// Bit-level full-adder relations derived from a + b + cin /////
    // LSB: sum[0] = a0 ^ b0 ^ cin.
    check_sum_bit0_xor: assert property (
        @(posedge cin) sum[0] == (a[0] ^ b[0] ^ cin)
    );
    // sum[1] with carry from bit 0.
    check_sum_bit1_full_adder: assert property (
        @(posedge cin) sum[1] == (a[1] ^ b[1] ^ ((a[0] & b[0]) | ((a[0] ^ b[0]) & cin)))
    );
    // sum[2] with propagated carry.
    check_sum_bit2_full_adder: assert property (
        @(posedge cin)
            sum[2] == (a[2] ^ b[2] ^
                       (((a[1] & b[1]) | ((a[1] ^ b[1]) & ((a[0] & b[0]) | ((a[0] ^ b[0]) & cin))))))
    );
    // sum[3] with propagated carry.
    check_sum_bit3_full_adder: assert property (
        @(posedge cin)
            sum[3] == (a[3] ^ b[3] ^
                       ( (a[2] & b[2]) |
                         ( (a[2] ^ b[2]) &
                           ( (a[1] & b[1]) |
                             ( (a[1] ^ b[1]) &
                               ( (a[0] & b[0]) | ( (a[0] ^ b[0]) & cin ) )
                             )
                           )
                         )
                       )
            )
    );

    ///// Corner cases by cin value /////
    // When cin rises (cin=1), output equals a + b + 1 with zero-extended carry.
    check_sum_when_cin1: assert property (
        @(posedge cin) {cout, sum} == {1'b0, (a + b + 1'b1)}
    );
    // When cin falls (cin=0), output equals a + b with zero-extended carry.
    check_sum_when_cin0: assert property (
        @(negedge cin) {cout, sum} == {1'b0, (a + b)}
    );
    // cout is 0 also when cin falls.
    check_cout_zero_negedge: assert property (
        @(negedge cin) cout == 1'b0
    );
endmodule

rtl:
module my_module (
    input  A1,
    input  A2,
    input  A3,
    input  B1,
    input  C1,
    output X
);

    wire X_int;
    a311o_2 dut (
        .X(X_int),
        .A1(A1),
        .A2(A2),
        .A3(A3),
        .B1(B1),
        .C1(C1)
    );

    assign X = X_int;

endmodule

module a311o_2(
    output X,
    input A1,
    input A2,
    input A3,
    input B1,
    input C1
);

    // Intermediate wires for internal logic
    wire A_out;
    wire BC_out;

    // Logical OR for A inputs
    assign A_out = A1 | A2 | A3;

    // Logical AND for B and C inputs
    assign BC_out = B1 & C1;

    // Combining the results - Assuming an XOR function for illustration
    assign X = A_out ^ BC_out;

endmodule

sva:
module my_module_sva (
    input logic A1,
    input logic A2,
    input logic A3,
    input logic B1,
    input logic C1,
    input logic X
);
    // No clock/reset in RTL; pure combinational. Use @($global_clock) for sampling.

    // X implements (A1|A2|A3) ^ (B1&C1).
    check_x_functional_equivalence: assert property (
        @($global_clock) X == ((A1 | A2 | A3) ^ (B1 & C1))
    );

    // If B1 or C1 is 0, X equals A1|A2|A3.
    check_bc_zero_path: assert property (
        @($global_clock) ((B1 == 1'b0) || (C1 == 1'b0)) |-> (X == (A1 | A2 | A3))
    );

    // If B1 and C1 are 1, X equals ~(A1|A2|A3).
    check_bc_one_inverts_a: assert property (
        @($global_clock) ((B1 == 1'b1) && (C1 == 1'b1)) |-> (X == ~(A1 | A2 | A3))
    );

    // If A1=A2=A3=0, X equals B1&C1.
    check_all_a_zero_path: assert property (
        @($global_clock) ((A1 == 1'b0) && (A2 == 1'b0) && (A3 == 1'b0)) |-> (X == (B1 & C1))
    );

    // If any A is 1, X equals ~(B1&C1).
    check_a_one_inverts_bc: assert property (
        @($global_clock) ((A1 | A2 | A3) == 1'b1) |-> (X == ~(B1 & C1))
    );

    // If A_out=1 and BC_out=0, X must be 1.
    check_x_one_when_a_one_bc_zero: assert property (
        @($global_clock) (((A1 | A2 | A3) == 1'b1) && ((B1 & C1) == 1'b0)) |-> (X == 1'b1)
    );

    // If A_out=0 and BC_out=1, X must be 1.
    check_x_one_when_a_zero_bc_one: assert property (
        @($global_clock) (((A1 | A2 | A3) == 1'b0) && ((B1 & C1) == 1'b1)) |-> (X == 1'b1)
    );

    // If A_out equals BC_out, X must be 0.
    check_equal_operands_yield_zero: assert property (
        @($global_clock) (((A1 | A2 | A3) == (B1 & C1))) |-> (X == 1'b0)
    );

    // If inputs are stable, X remains stable.
    check_stable_output_when_inputs_stable: assert property (
        @($global_clock) $stable({A1, A2, A3, B1, C1}) |-> $stable(X)
    );

    // X can only change when at least one input changes.
    check_no_spurious_output_toggle: assert property (
        @($global_clock) $changed(X) |-> ($changed(A1) || $changed(A2) || $changed(A3) || $changed(B1) || $changed(C1))
    );
endmodule

rtl:
module bitwise_and(
  input [1:0] A,
  input [1:0] B,
  output [1:0] Y
);

  assign Y = A & B;

endmodule

sva:
module bitwise_and_sva (
    input logic clk,
    input logic [1:0] A,
    input logic [1:0] B,
    input logic [1:0] Y
);
    // Output equals bitwise AND of inputs (vector).
    check_and_vector: assert property (
        @(posedge clk) (Y == (A & B))
    );

    // Bit 0 output equals AND of inputs bit 0.
    check_and_bit0: assert property (
        @(posedge clk) (Y[0] == (A[0] & B[0]))
    );

    // Bit 1 output equals AND of inputs bit 1.
    check_and_bit1: assert property (
        @(posedge clk) (Y[1] == (A[1] & B[1]))
    );

    // Y[0] is 1 only when both A[0] and B[0] are 1 (same cycle).
    check_y0_only_when_both_high: assert property (
        @(posedge clk) Y[0] |=> (A[0] && B[0])
    );

    // Y[1] is 1 only when both A[1] and B[1] are 1 (same cycle).
    check_y1_only_when_both_high: assert property (
        @(posedge clk) Y[1] |=> (A[1] && B[1])
    );

    // If both A[0] and B[0] are 1, then Y[0] is 1 (same cycle).
    check_both_high_implies_y0: assert property (
        @(posedge clk) (A[0] && B[0]) |=> Y[0]
    );

    // If both A[1] and B[1] are 1, then Y[1] is 1 (same cycle).
    check_both_high_implies_y1: assert property (
        @(posedge clk) (A[1] && B[1]) |=> Y[1]
    );
endmodule

