module decoder_3to8 (
    input A,
    input B,
    input C,
    output reg Y0,
    output reg Y1,
    output reg Y2,
    output reg Y3,
    output reg Y4,
    output reg Y5,
    output reg Y6,
    output reg Y7
);

always @ (A or B or C) begin
    Y0 = ~(A | B | C);
    Y1 = ~(A | B | ~C);
    Y2 = ~(A | ~B | C);
    Y3 = ~(A | ~B | ~C);
    Y4 = ~(~A | B | C);
    Y5 = ~(~A | B | ~C);
    Y6 = ~(~A | ~B | C);
    Y7 = ~(~A | ~B | ~C);
end

endmodule

sva:
module decoder_3to8_sva (
    // DUT ports
    input logic A,
    input logic B,
    input logic C,
    input logic Y0,
    input logic Y1,
    input logic Y2,
    input logic Y3,
    input logic Y4,
    input logic Y5,
    input logic Y6,
    input logic Y7,
    // Sampling clock for SVA (RTL has no clock/reset)
    input logic clk
);
    // No clock/reset in RTL; assertions are sampled on clk without reset gating.
    // Purely combinational 3-to-8 decoder: Y[i] is one-hot minterm of A,B,C.

    // Y0 equals ~(A | B | C)
    check_y0_definition: assert property (
        @(posedge clk) Y0 == ~(A | B | C)
    );

    // Y1 equals ~(A | B | ~C)
    check_y1_definition: assert property (
        @(posedge clk) Y1 == ~(A | B | ~C)
    );

    // Y2 equals ~(A | ~B | C)
    check_y2_definition: assert property (
        @(posedge clk) Y2 == ~(A | ~B | C)
    );

    // Y3 equals ~(A | ~B | ~C)
    check_y3_definition: assert property (
        @(posedge clk) Y3 == ~(A | ~B | ~C)
    );

    // Y4 equals ~(~A | B | C)
    check_y4_definition: assert property (
        @(posedge clk) Y4 == ~(~A | B | C)
    );

    // Y5 equals ~(~A | B | ~C)
    check_y5_definition: assert property (
        @(posedge clk) Y5 == ~(~A | B | ~C)
    );

    // Y6 equals ~(~A | ~B | C)
    check_y6_definition: assert property (
        @(posedge clk) Y6 == ~(~A | ~B | C)
    );

    // Y7 equals ~(~A | ~B | ~C)
    check_y7_definition: assert property (
        @(posedge clk) Y7 == ~(~A | ~B | ~C)
    );

    // Exactly one output is HIGH for any A,B,C
    check_onehot_outputs: assert property (
        @(posedge clk) $onehot({Y7,Y6,Y5,Y4,Y3,Y2,Y1,Y0})
    );

    // Outputs cover all cases (OR of all Y is 1)
    check_outputs_cover_all: assert property (
        @(posedge clk) (|{Y7,Y6,Y5,Y4,Y3,Y2,Y1,Y0}) == 1'b1
    );

    // If inputs are stable, outputs remain stable (combinational behavior)
    check_output_stability_when_inputs_stable: assert property (
        @(posedge clk) $stable({A,B,C}) |-> $stable({Y7,Y6,Y5,Y4,Y3,Y2,Y1,Y0})
    );
endmodule

rtl:
module avr109rx (
		 input rst,
		 input clk,
		 output[7:0] rx_data,
		 output rx_avail,
		 input rxd,
		 input rx_enabled
		 );
   parameter CLK_FREQUENCY = 1000000;
   parameter BAUD_RATE = 19200;

   function integer log2;
      input integer value;
      begin
         value = value-1;
         for (log2=0; value>0; log2=log2+1)
           value = value>>1;
      end
   endfunction

   localparam BAUDDIV = (CLK_FREQUENCY / BAUD_RATE);
   localparam LOG2_BAUDDIV = log2(BAUDDIV);

   reg [7:0] rxshift_d, rxshift_q;
   reg 	     rx_active_d, rx_active_q;
   reg 	     rx_done_d, rx_done_q;
   reg [3:0] rxcnt_d,   rxcnt_q;
   reg [LOG2_BAUDDIV-1:0] rxbaud_d, rxbaud_q;

   assign rx_data = rxshift_q;
   assign rx_avail = rx_done_q;

   always @(*) begin
      rx_active_d = rx_active_q;
      rx_done_d = 1'b0;

      if (rx_active_q) begin
	 rxshift_d = rxshift_q;
	 rxcnt_d = rxcnt_q;
	 if (rxbaud_q == BAUDDIV-1) begin
	    if (rxcnt_q == 9) begin
	       if (rxd) begin
		  rx_active_d = 1'b0;
		  rx_done_d = 1'b1;
	       end
	    end else begin
	       rxshift_d = {rxd, rxshift_q[7:1]};
	       rxcnt_d = rxcnt_q + 1;
	    end
	    rxbaud_d = 0;
	 end else begin
	    rxbaud_d = rxbaud_q + 1;
	 end
      end else begin
	 rxshift_d = {8{1'b0}};
	 rxcnt_d = 0;
	 rxbaud_d = BAUDDIV/2;
	 if (~rxd) begin
	    rx_active_d = 1'b1;
	 end
      end

   end

   always @(posedge clk) begin
      if (rst | ~rx_enabled) begin
	 rxshift_q <= {8{1'b0}};
	 rx_active_q <= 1'b0;
	 rx_done_q <= 1'b0;
	 rxcnt_q <= 0;
	 rxbaud_q <= 0;
      end else begin
	 rxshift_q <= rxshift_d;
	 rx_active_q <= rx_active_d;
	 rx_done_q <= rx_done_d;
	 rxcnt_q <= rxcnt_d;
	 rxbaud_q <= rxbaud_d;
      end
   end

endmodule

sva:
module avr109rx_sva #(
    parameter int CLK_FREQUENCY = 1000000,
    parameter int BAUD_RATE     = 19200,
    parameter int BAUDDIV       = (CLK_FREQUENCY / BAUD_RATE),
    parameter int LOG2_BAUDDIV  = (BAUDDIV <= 1) ? 1 : $clog2(BAUDDIV)
)(
    input  logic              rst,
    input  logic              clk,
    input  logic [7:0]        rx_data,
    input  logic              rx_avail,
    input  logic              rxd,
    input  logic              rx_enabled,
    // Internal state from DUT
    input  logic [7:0]        rxshift_q,
    input  logic              rx_active_q,
    input  logic              rx_done_q,
    input  logic [3:0]        rxcnt_q,
    input  logic [LOG2_BAUDDIV-1:0] rxbaud_q
);

    localparam int BAUDDIV_M1   = BAUDDIV - 1;
    localparam int BAUDDIV_HALF = BAUDDIV/2;

    ///// Reset/disable behavior /////
    // When rst asserted or rx_enabled deasserted, outputs are driven LOW/zero.
    reset_outputs_zero: assert property (
        @(posedge clk) (rst | ~rx_enabled) |-> (rx_data == 8'h00) && (rx_avail == 1'b0)
    );
    // When rst asserted or rx_enabled deasserted, internal state clears to zero.
    reset_regs_zero: assert property (
        @(posedge clk) (rst | ~rx_enabled) |-> (rxshift_q == 8'h00) && (rx_active_q == 1'b0) &&
                                           (rx_done_q == 1'b0) && (rxcnt_q == 4'd0) &&
                                           (rxbaud_q == '0)
    );

    ///// Output mapping to internal state /////
    // rx_data mirrors rxshift_q every cycle.
    map_rx_data_to_shift: assert property (
        @(posedge clk) disable iff (rst | ~rx_enabled) (rx_data == rxshift_q)
    );
    // rx_avail mirrors rx_done_q every cycle.
    map_rx_avail_to_done: assert property (
        @(posedge clk) disable iff (rst | ~rx_enabled) (rx_avail == rx_done_q)
    );

    ///// rx_avail pulse semantics /////
    // rx_avail is a single-cycle pulse.
    rx_avail_one_cycle_pulse: assert property (
        @(posedge clk) disable iff (rst | ~rx_enabled) $rose(rx_avail) |=> !rx_avail
    );
    // When rx_avail is high, the receiver is inactive that same cycle.
    rx_avail_implies_inactive: assert property (
        @(posedge clk) disable iff (rst | ~rx_enabled) rx_avail |-> !rx_active_q
    );
    // Rising rx_avail corresponds to a stop-bit sample in the previous cycle.
    rx_avail_prev_stop_condition: assert property (
        @(posedge clk) disable iff (rst | ~rx_enabled)
            $rose(rx_avail) |-> $past(rx_active_q && (rxbaud_q == BAUDDIV_M1) && (rxcnt_q == 4'd9) && rxd)
    );
    // When rx_avail is high, rxcnt_q is 9 (stop-bit sample just occurred).
    rx_avail_implies_rxcnt9: assert property (
        @(posedge clk) disable iff (rst | ~rx_enabled) rx_avail |-> (rxcnt_q == 4'd9)
    );

    ///// Activation/deactivation rules /////
    // rx_active deasserts only following a valid stop-bit sample.
    rx_active_fall_only_on_stop: assert property (
        @(posedge clk) disable iff (rst | ~rx_enabled)
            $fell(rx_active_q) |-> $past((rxbaud_q == BAUDDIV_M1) && (rxcnt_q == 4'd9) && rxd)
    );
    // A detected start (idle with rxd low) activates reception on the next cycle.
    idle_start_on_low_rxd: assert property (
        @(posedge clk) disable iff (rst | ~rx_enabled) (!rx_active_q && !rxd) |=> rx_active_q
    );
    // While idle and rxd high, stay idle on the next cycle.
    idle_hold_on_high_rxd: assert property (
        @(posedge clk) disable iff (rst | ~rx_enabled) (!rx_active_q && rxd) |=> !rx_active_q
    );

    ///// Idle defaults /////
    // While idle, next-state defaults: shift=0, cnt=0, baud=BAUDDIV/2.
    idle_defaults_on_next: assert property (
        @(posedge clk) disable iff (rst | ~rx_enabled)
            !rx_active_q |=> (rxshift_q == 8'h00) && (rxcnt_q == 4'd0) && (rxbaud_q == BAUDDIV_HALF)
    );

    ///// Timing and sampling behavior while active /////
    // Between samples, baud counter increments by 1; others hold; rx_done_q stays 0.
    active_between_samples_baud_increments: assert property (
        @(posedge clk) disable iff (rst | ~rx_enabled)
            (rx_active_q && (rxbaud_q != BAUDDIV_M1))
            |=> (rxbaud_q == $past(rxbaud_q) + 1) &&
                (rxcnt_q == $past(rxcnt_q)) &&
                (rxshift_q == $past(rxshift_q)) &&
                (rx_active_q == 1'b1) &&
                (rx_done_q == 1'b0)
    );
    // On any sample event, baud counter resets to 0 on the next cycle.
    sample_resets_baud: assert property (
        @(posedge clk) disable iff (rst | ~rx_enabled)
            (rx_active_q && (rxbaud_q == BAUDDIV_M1)) |=> (rxbaud_q == '0)
    );
    // Sample with rxcnt<9: shift in rxd at MSB, increment count, stay active, no done.
    active_sample_shift_and_count: assert property (
        @(posedge clk) disable iff (rst | ~rx_enabled)
            (rx_active_q && (rxbaud_q == BAUDDIV_M1) && (rxcnt_q < 4'd9))
            |=> (rx_active_q == 1'b1) &&
                (rxcnt_q == $past(rxcnt_q) + 1) &&
                (rxshift_q == { $past(rxd), $past(rxshift_q[7:1]) }) &&
                (rxbaud_q == '0) &&
                (rx_done_q == 1'b0)
    );
    // Sample stop bit (rxcnt==9) with rxd==1: deactivate and pulse done next cycle.
    active_stop_sample_done: assert property (
        @(posedge clk) disable iff (rst | ~rx_enabled)
            (rx_active_q && (rxbaud_q == BAUDDIV_M1) && (rxcnt_q == 4'd9) && rxd)
            |=> (!rx_active_q && rx_done_q && (rxbaud_q == '0))
    );
    // Sample stop bit (rxcnt==9) with rxd==0: remain active, hold count, no done, reset baud.
    active_stop_zero_waits: assert property (
        @(posedge clk) disable iff (rst | ~rx_enabled)
            (rx_active_q && (rxbaud_q == BAUDDIV_M1) && (rxcnt_q == 4'd9) && !rxd)
            |=> (rx_active_q && (rxcnt_q == 4'd9) && (rxbaud_q == '0) &&
                 (rxshift_q == $past(rxshift_q)) && (rx_done_q == 1'b0))
    );

endmodule

rtl:
module my_module (
    Y   ,
    A1  ,
    A2  ,
    A3  ,
    B1  
);

    output Y   ;
    input  A1  ;
    input  A2  ;
    input  A3  ;
    input  B1  ;

    wire temp;

    assign temp = (A1 & A2 & A3) | (~A1 & ~A2 & ~A3);

    assign Y = temp ? 1'b1 : B1;

endmodule

sva:
module my_module_sva (
    input logic Y,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic B1
);
    // Analysis: no clock/reset; combinational; Y=1 if A1,A2,A3 all equal, else Y=B1.

    // Y must match the RTL ternary expression.
    check_y_matches_rtl_expr: assert property (
        @(posedge $global_clock) Y == ( ((A1 & A2 & A3) | (~A1 & ~A2 & ~A3)) ? 1'b1 : B1 )
    );

    // Y is 1 when A1,A2,A3 are all 1 or all 0.
    check_y_one_when_unanimous: assert property (
        @(posedge $global_clock) ((A1 & A2 & A3) || (~A1 & ~A2 & ~A3)) |-> (Y == 1'b1)
    );

    // When inputs are not unanimous, Y equals B1.
    check_y_equals_b1_when_not_unanimous: assert property (
        @(posedge $global_clock) !((A1 & A2 & A3) | (~A1 & ~A2 & ~A3)) |-> (Y == B1)
    );

    // Y==0 implies B1==0 and inputs are not unanimous.
    check_y_zero_implies_b1_zero_and_not_unanimous: assert property (
        @(posedge $global_clock) (Y == 1'b0) |-> ((B1 == 1'b0) && !((A1 & A2 & A3) | (~A1 & ~A2 & ~A3)))
    );

    // Y==1 implies B1==1 or inputs are unanimous.
    check_y_one_implies_cause: assert property (
        @(posedge $global_clock) (Y == 1'b1) |-> ((B1 == 1'b1) || (A1 & A2 & A3) || (~A1 & ~A2 & ~A3))
    );

    // B1==1 always forces Y==1.
    check_b1_one_forces_y_one: assert property (
        @(posedge $global_clock) (B1 == 1'b1) |-> (Y == 1'b1)
    );

    // When B1==0, Y equals the unanimity function of A1,A2,A3.
    check_b1_zero_implies_y_equals_unanimous: assert property (
        @(posedge $global_clock) (B1 == 1'b0) |-> (Y == ((A1 & A2 & A3) | (~A1 & ~A2 & ~A3)))
    );

    // Y differs from B1 only when inputs are unanimous and B1 is 0.
    check_y_differs_from_b1_only_when_unanimous_b1_zero: assert property (
        @(posedge $global_clock) (Y != B1) |-> (((A1 & A2 & A3) || (~A1 & ~A2 & ~A3)) && (B1 == 1'b0) && (Y == 1'b1))
    );

    // If not unanimous and B1==1, then Y==1.
    check_not_unanimous_b1_one_y_one: assert property (
        @(posedge $global_clock) (!((A1 & A2 & A3) | (~A1 & ~A2 & ~A3)) && (B1 == 1'b1)) |-> (Y == 1'b1)
    );

    // If not unanimous and B1==0, then Y==0.
    check_not_unanimous_b1_zero_y_zero: assert property (
        @(posedge $global_clock) (!((A1 & A2 & A3) | (~A1 & ~A2 & ~A3)) && (B1 == 1'b0)) |-> (Y == 1'b0)
    );
endmodule

rtl:
module sky130_fd_sc_hd__nand3 (
    Y,
    A,
    B,
    C
);

    output Y;
    input  A;
    input  B;
    input  C;

    wire nand0_out_Y;

    nand nand0 (nand0_out_Y, B, A, C        );
    buf  buf0  (Y          , nand0_out_Y    );

endmodule

sva:
module sky130_fd_sc_hd__nand3_sva (
    input logic clk,
    input logic Y,
    input logic A,
    input logic B,
    input logic C
);
    // Y implements a 3-input NAND of A,B,C.
    check_nand_function: assert property (
        @(posedge clk) Y == ~(A & B & C)
    );

    // When all inputs are HIGH, Y must be LOW.
    check_all_high_drives_low: assert property (
        @(posedge clk) (A && B && C) |-> (Y == 1'b0)
    );

    // Y LOW implies all inputs are HIGH.
    check_low_implies_all_high: assert property (
        @(posedge clk) (Y == 1'b0) |-> (A && B && C)
    );

    // If A is LOW, Y must be HIGH (regardless of B and C).
    check_any_low_A_drives_high: assert property (
        @(posedge clk) (!A) |-> (Y == 1'b1)
    );

    // If B is LOW, Y must be HIGH (regardless of A and C).
    check_any_low_B_drives_high: assert property (
        @(posedge clk) (!B) |-> (Y == 1'b1)
    );

    // If C is LOW, Y must be HIGH (regardless of A and B).
    check_any_low_C_drives_high: assert property (
        @(posedge clk) (!C) |-> (Y == 1'b1)
    );

    // If A rises while B and C are HIGH, Y must be LOW.
    check_rise_A_with_BC_high_drives_low: assert property (
        @(posedge clk) ($rose(A) && B && C) |-> (Y == 1'b0)
    );

    // If A falls while B and C are HIGH, Y must be HIGH.
    check_fall_A_with_BC_high_drives_high: assert property (
        @(posedge clk) ($fell(A) && B && C) |-> (Y == 1'b1)
    );

    // If B rises while A and C are HIGH, Y must be LOW.
    check_rise_B_with_AC_high_drives_low: assert property (
        @(posedge clk) ($rose(B) && A && C) |-> (Y == 1'b0)
    );

    // If C rises while A and B are HIGH, Y must be LOW.
    check_rise_C_with_AB_high_drives_low: assert property (
        @(posedge clk) ($rose(C) && A && B) |-> (Y == 1'b0)
    );

    // If inputs are stable, output must be stable (pure combinational).
    check_stable_inputs_imply_stable_output: assert property (
        @(posedge clk) ($stable(A) && $stable(B) && $stable(C)) |-> $stable(Y)
    );
endmodule

rtl:
module sky130_fd_sc_lp__a22oi (
    Y ,
    A1,
    A2,
    B1,
    B2
);

    output Y ;
    input  A1;
    input  A2;
    input  B1;
    input  B2;

    wire nand0_out ;
    wire nand1_out ;
    wire and0_out_Y;

    nand nand0 (nand0_out , A2, A1              );
    nand nand1 (nand1_out , B2, B1              );
    and  and0  (and0_out_Y, nand0_out, nand1_out);
    buf  buf0  (Y         , and0_out_Y          );

endmodule

sva:
module sky130_fd_sc_lp__a22oi_sva (
    input logic Y,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic B2
);
    ///// Functional equivalence /////
    // Y implements ~( (A1 & A2) | (B1 & B2) ) sampled on A1 rising edge.
    check_y_function_equivalence: assert property (
        @(posedge A1) Y == ~((A1 & A2) | (B1 & B2))
    );

    // If A1&A2 are both HIGH, Y must be LOW.
    check_y_low_when_A_pair_high: assert property (
        @(posedge A1) (A1 & A2) |-> (Y == 1'b0)
    );

    // If B1&B2 are both HIGH, Y must be LOW.
    check_y_low_when_B_pair_high: assert property (
        @(posedge A1) (B1 & B2) |-> (Y == 1'b0)
    );

    // If neither A1&A2 nor B1&B2 are HIGH, Y must be HIGH.
    check_y_high_when_neither_pair_high: assert property (
        @(posedge A1) (!(A1 & A2) && !(B1 & B2)) |-> (Y == 1'b1)
    );
endmodule

rtl:
module mux_2_to_1 (
    select,
    data_0,
    data_1,
    out
);

    input select;
    input data_0;
    input data_1;
    output out;

    assign out = select ? data_1 : data_0;

endmodule

sva:
module mux_2_to_1_sva (
    input logic clk,
    input logic select,
    input logic data_0,
    input logic data_1,
    input logic out
);
    // Mux function: out equals selected input.
    check_mux_equivalence: assert property (
        @(posedge clk) out == (select ? data_1 : data_0)
    );

    // When select=0, out equals data_0.
    check_select0_routes_data0: assert property (
        @(posedge clk) (select == 1'b0) |-> (out == data_0)
    );

    // When select=1, out equals data_1.
    check_select1_routes_data1: assert property (
        @(posedge clk) (select == 1'b1) |-> (out == data_1)
    );

    // If inputs are equal, out equals that value.
    check_equal_inputs_pass_through: assert property (
        @(posedge clk) (data_0 == data_1) |-> (out == data_0)
    );

    // Out is stable when select and data inputs are stable.
    check_stable_when_inputs_stable: assert property (
        @(posedge clk) ($stable(select) && $stable(data_0) && $stable(data_1)) |-> $stable(out)
    );

    // Out change implies at least one of select/data_0/data_1 changed.
    check_out_change_requires_input_change: assert property (
        @(posedge clk) $changed(out) |-> ($changed(select) || $changed(data_0) || $changed(data_1))
    );

    // If select=0 and data_0 changes (select stable), out follows and changes.
    check_data0_change_propagates_when_selected: assert property (
        @(posedge clk) (select == 1'b0 && $stable(select) && $changed(data_0)) |-> ($changed(out) && (out == data_0))
    );

    // If select=1 and data_1 changes (select stable), out follows and changes.
    check_data1_change_propagates_when_selected: assert property (
        @(posedge clk) (select == 1'b1 && $stable(select) && $changed(data_1)) |-> ($changed(out) && (out == data_1))
    );

    // If select=1 and data_0 changes (select stable), out stays stable.
    check_unselected_data0_no_effect: assert property (
        @(posedge clk) (select == 1'b1 && $stable(select) && $changed(data_0)) |-> $stable(out)
    );

    // If select=0 and data_1 changes (select stable), out stays stable.
    check_unselected_data1_no_effect: assert property (
        @(posedge clk) (select == 1'b0 && $stable(select) && $changed(data_1)) |-> $stable(out)
    );

    // On select rising edge with stable data, out switches from data_0 to data_1.
    check_out_updates_on_select_rise: assert property (
        @(posedge clk) ($rose(select) && $stable(data_0) && $stable(data_1)) |-> ($past(out) == $past(data_0) && out == data_1)
    );

    // On select falling edge with stable data, out switches from data_1 to data_0.
    check_out_updates_on_select_fall: assert property (
        @(posedge clk) ($fell(select) && $stable(data_0) && $stable(data_1)) |-> ($past(out) == $past(data_1) && out == data_0)
    );
endmodule

rtl:
module d_ff_as (
    input CLK,
    input D,
    input SET,
    input CLR,
    output Q,
    output Q_N
);

    reg Q_int;

    always @(posedge CLK ) begin  // or posedge SET) begin  // or posedge CLR removed
        if (SET) begin
            Q_int <= 1'b1;
        end else if (CLR) begin
            Q_int <= 1'b0;
        end else begin
            Q_int <= D;
        end
    end

    assign Q = Q_int;
    assign Q_N = ~Q_int;

endmodule
module top_module (
    input CLK,
    input D,
    input SET,
    input CLR,
    output Q,
    output Q_N
);

    d_ff_as d_ff (
        .CLK(CLK),
        .D(D),
        .SET(SET),
        .CLR(CLR),
        .Q(Q),
        .Q_N(Q_N)
    );

endmodule

sva:
module top_module_sva (
    input logic CLK,
    input logic D,
    input logic SET,
    input logic CLR,
    input logic Q,
    input logic Q_N
);
    // Clock: CLK (posedge). No reset signal present.
    // Sequential logic: posedge-triggered DFF with synchronous SET (priority) and CLR.
    // Behavior: If SET=1 -> Q=1; else if CLR=1 -> Q=0; else Q<=D. Q_N is always ~Q.

    ///// Output relationship /////
    // Q_N is always the inversion of Q.
    check_qn_is_inversion_of_q: assert property (
        @(posedge CLK) (Q_N == ~Q)
    );

    ///// Priority rules /////
    // When both SET and CLR are 1, SET dominates and Q goes HIGH next cycle.
    check_set_dominates_clr: assert property (
        @(posedge CLK) (SET && CLR) |=> (Q == 1'b1) && (Q_N == 1'b0)
    );

    ///// Set/Clear effects /////
    // SET drives Q HIGH on the next clock, regardless of D.
    check_set_forces_q_high: assert property (
        @(posedge CLK) SET |=> (Q == 1'b1)
    );

    // With CLR asserted and SET deasserted, Q goes LOW on the next clock.
    check_clr_forces_q_low_when_no_set: assert property (
        @(posedge CLK) (CLR && !SET) |=> (Q == 1'b0)
    );

    // With CLR asserted and SET deasserted, Q_N goes HIGH on the next clock.
    check_clr_sets_qn_high_when_no_set: assert property (
        @(posedge CLK) (CLR && !SET) |=> (Q_N == 1'b1)
    );

    ///// Data capture /////
    // When neither SET nor CLR, Q captures D on the next clock.
    check_d_captured_into_q_on_next_clk: assert property (
        @(posedge CLK) (!SET && !CLR) |=> (Q == $past(D))
    );

    // When neither SET nor CLR, Q_N captures inverted D on the next clock.
    check_d_captured_into_qn_on_next_clk: assert property (
        @(posedge CLK) (!SET && !CLR) |=> (Q_N == ~$past(D))
    );

    ///// Functional equivalence /////
    // Full next-state function for Q: priority SET over CLR over D.
    check_full_next_state_q: assert property (
        @(posedge CLK) 1'b1 |=> (Q == $past(SET ? 1'b1 : (CLR ? 1'b0 : D)))
    );

    ///// Hold behavior (derived from data capture) /////
    // If neither SET nor CLR and D equals current Q, Q holds its value next cycle.
    check_hold_when_d_equals_q: assert property (
        @(posedge CLK) (!SET && !CLR && (D == Q)) |=> (Q == $past(Q))
    );

endmodule

rtl:
module sky130_fd_sc_lp__inputiso0p (
    X    ,
    A    ,
    SLEEP
);

    output X    ;
    input  A    ;
    input  SLEEP;

    wire sleepn;

    not not0 (sleepn, SLEEP          );
    and and0 (X     , A, sleepn      );

endmodule

sva:
module sky130_fd_sc_lp__inputiso0p_sva (
    input logic clk,
    input logic X,
    input logic A,
    input logic SLEEP
);
    // X implements A & ~SLEEP
    check_function_equivalence: assert property (
        @(posedge clk) X == (A & ~SLEEP)
    );

    // When SLEEP is high, X must be 0
    check_isolation_when_sleep: assert property (
        @(posedge clk) SLEEP |-> (X == 1'b0)
    );

    // When SLEEP is low, X equals A
    check_transparent_when_awake: assert property (
        @(posedge clk) !SLEEP |-> (X == A)
    );

    // X high only if A is high and SLEEP is low
    check_x_high_conditions: assert property (
        @(posedge clk) (X == 1'b1) |-> (A == 1'b1) && (SLEEP == 1'b0)
    );

    // If A is low, X must be low
    check_a_low_forces_x_low: assert property (
        @(posedge clk) (A == 1'b0) |-> (X == 1'b0)
    );

    // If A is high, X equals ~SLEEP
    check_a_high_sets_x_to_not_sleep: assert property (
        @(posedge clk) (A == 1'b1) |-> (X == ~SLEEP)
    );

    // X can only rise when A is high and SLEEP is low
    check_x_rise_requires_a_and_awake: assert property (
        @(posedge clk) $rose(X) |-> (A == 1'b1) && (SLEEP == 1'b0)
    );

    // X can only fall when A is low or SLEEP is high
    check_x_fall_requires_a0_or_sleep1: assert property (
        @(posedge clk) $fell(X) |-> (A == 1'b0) || (SLEEP == 1'b1)
    );

    // On SLEEP rising edge, X must be 0
    check_x_zero_on_sleep_rise: assert property (
        @(posedge clk) $rose(SLEEP) |-> (X == 1'b0)
    );

    // On SLEEP falling edge with A high, X must be 1
    check_x_one_on_sleep_fall_if_a_high: assert property (
        @(posedge clk) ($fell(SLEEP) && (A == 1'b1)) |-> (X == 1'b1)
    );

    // On A rising edge with SLEEP low, X must be 1
    check_x_one_on_a_rise_if_awake: assert property (
        @(posedge clk) ($rose(A) && (SLEEP == 1'b0)) |-> (X == 1'b1)
    );

    // On A falling edge with SLEEP low, X must be 0
    check_x_zero_on_a_fall_if_awake: assert property (
        @(posedge clk) ($fell(A) && (SLEEP == 1'b0)) |-> (X == 1'b0)
    );
endmodule

rtl:
module mux4 (
    input A0,
    input A1,
    input A2,
    input A3,
    input S0,
    input S1,
    output X,
    input VPB,
    input VPWR,
    input VGND,
    input VNB
);

reg [3:0] inputs;
reg [1:0] select;

always @(posedge S0) begin
    select[0] <= S0;
end

always @(posedge S1) begin
    select[1] <= S1;
end

always @ (select, A0, A1, A2, A3) begin
    case (select)
        2'b00: inputs = {A0, 1'b0, 1'b0, 1'b0};
        2'b01: inputs = {1'b0, A1, 1'b0, 1'b0};
        2'b10: inputs = {1'b0, 1'b0, A2, 1'b0};
        2'b11: inputs = {1'b0, 1'b0, 1'b0, A3};
    endcase
end

assign X = inputs[3] | inputs[2] | inputs[1] | inputs[0];

endmodule

sva:
module mux4_sva (
    input  logic A0,
    input  logic A1,
    input  logic A2,
    input  logic A3,
    input  logic S0,
    input  logic S1,
    input  logic X,
    input  logic VPB,
    input  logic VPWR,
    input  logic VGND,
    input  logic VNB,
    // Internal RTL signals (connect via bind or hierarchical reference)
    input  logic [3:0] inputs,
    input  logic [1:0] select
);
    ///// Output function /////
    // X equals OR-reduction of inputs on S0 clock.
    check_x_is_or_inputs_s0: assert property (
        @(posedge S0) X == (inputs[3] | inputs[2] | inputs[1] | inputs[0])
    );
    // X equals OR-reduction of inputs on S1 clock.
    check_x_is_or_inputs_s1: assert property (
        @(posedge S1) X == (inputs[3] | inputs[2] | inputs[1] | inputs[0])
    );

    ///// Combinational decode of inputs from select /////
    // For select == 2'b00, inputs routes A0 to bit[3].
    check_inputs_map_sel_00: assert property (
        @(posedge S0) (select == 2'b00) |-> (inputs == {A0, 1'b0, 1'b0, 1'b0})
    );
    // For select == 2'b01, inputs routes A1 to bit[2].
    check_inputs_map_sel_01: assert property (
        @(posedge S0) (select == 2'b01) |-> (inputs == {1'b0, A1, 1'b0, 1'b0})
    );
    // For select == 2'b10, inputs routes A2 to bit[1].
    check_inputs_map_sel_10: assert property (
        @(posedge S0) (select == 2'b10) |-> (inputs == {1'b0, 1'b0, A2, 1'b0})
    );
    // For select == 2'b11, inputs routes A3 to bit[0].
    check_inputs_map_sel_11: assert property (
        @(posedge S0) (select == 2'b11) |-> (inputs == {1'b0, 1'b0, 1'b0, A3})
    );
    // inputs is one-hot or zero (by construction of the decoder).
    check_inputs_onehot0: assert property (
        @(posedge S0) $onehot0(inputs)
    );

    ///// X equals the selected A input /////
    // When select == 2'b00, X equals A0.
    check_x_map_sel_00: assert property (
        @(posedge S0) (select == 2'b00) |-> (X == A0)
    );
    // When select == 2'b01, X equals A1.
    check_x_map_sel_01: assert property (
        @(posedge S0) (select == 2'b01) |-> (X == A1)
    );
    // When select == 2'b10, X equals A2.
    check_x_map_sel_10: assert property (
        @(posedge S0) (select == 2'b10) |-> (X == A2)
    );
    // When select == 2'b11, X equals A3.
    check_x_map_sel_11: assert property (
        @(posedge S0) (select == 2'b11) |-> (X == A3)
    );

    ///// Select flops behavior /////
    // Posedge S0 causes select[0] to be 1 by the next S0 edge.
    check_select0_sets_next: assert property (
        @(posedge S0) 1'b1 |=> (select[0] == 1'b1)
    );
    // Posedge S1 causes select[1] to be 1 by the next S1 edge.
    check_select1_sets_next: assert property (
        @(posedge S1) 1'b1 |=> (select[1] == 1'b1)
    );
endmodule

