module pipestage
  #(parameter TAGWIDTH = 1)
   (input clk,
    input reset,
    input stb_in,
    input stb_out,
    output reg valid,
    input [TAGWIDTH-1:0] tag_in,
    output reg [TAGWIDTH-1:0] tag_out);

   always @(posedge clk)
     if(reset)
       begin
	  valid <= 0;
	  tag_out <= 0;
       end
     else if(stb_in)
       begin
	  valid <= 1;
	  tag_out <= tag_in;
       end
     else if(stb_out)
       begin
	  valid <= 0;
	  tag_out <= 0;
       end

endmodule

sva:
module pipestage_sva
  #(parameter TAGWIDTH = 1)
   (input  logic                 clk,
    input  logic                 reset,     // active-HIGH synchronous reset
    input  logic                 stb_in,
    input  logic                 stb_out,
    input  logic                 valid,
    input  logic [TAGWIDTH-1:0]  tag_in,
    input  logic [TAGWIDTH-1:0]  tag_out);

    // Synchronous reset drives valid/tag_out to zero by next cycle.
    check_sync_reset_clears_next: assert property (
        @(posedge clk) reset |=> (valid == 1'b0) && (tag_out == '0)
    );

    // On stb_in, next-cycle valid=1 and tag_out captures tag_in from prior cycle.
    check_load_on_stb_in: assert property (
        @(posedge clk) disable iff (reset) stb_in |=> (valid == 1'b1) && (tag_out == $past(tag_in))
    );

    // On stb_out without stb_in, next-cycle valid=0 and tag_out=0.
    check_clear_on_stb_out: assert property (
        @(posedge clk) disable iff (reset) (stb_out && !stb_in) |=> (valid == 1'b0) && (tag_out == '0)
    );

    // If both stb_in and stb_out, stb_in has priority (load occurs).
    check_priority_in_over_out: assert property (
        @(posedge clk) disable iff (reset) (stb_in && stb_out) |=> (valid == 1'b1) && (tag_out == $past(tag_in))
    );

    // When no strobes, registers hold their previous values.
    check_hold_on_idle: assert property (
        @(posedge clk) disable iff (reset) (!stb_in && !stb_out) |=> (valid == $past(valid)) && (tag_out == $past(tag_out))
    );

    // valid can only rise due to stb_in in the previous cycle.
    check_valid_rise_cause: assert property (
        @(posedge clk) disable iff (reset) $rose(valid) |-> $past(stb_in)
    );

    // valid can only fall due to stb_out (with no stb_in) in the previous cycle.
    check_valid_fall_cause: assert property (
        @(posedge clk) disable iff (reset) $fell(valid) |-> $past(stb_out && !stb_in)
    );

    // After stb_in, if next cycle is idle, loaded tag/value persist.
    check_persist_after_load_when_idle: assert property (
        @(posedge clk) disable iff (reset)
            (stb_in) |=> (!stb_in && !stb_out) |-> (valid == 1'b1) && (tag_out == $past(tag_in,1))
    );

    // After stb_out (without stb_in), if next cycle is idle, cleared state persists.
    check_persist_after_clear_when_idle: assert property (
        @(posedge clk) disable iff (reset)
            (stb_out && !stb_in) |=> (!stb_in && !stb_out) |-> (valid == 1'b0) && (tag_out == '0)
    );

endmodule

module counter_sva (
    input logic clk,
    input logic rst,
    input logic enable,
    input logic load,
    input logic increment,
    input logic [7:0] data_in,
    input logic [7:0] count
);
    // After a cycle with rst=1, count must be 0 on the next cycle.
    check_reset_clears_on_next: assert property (
        @(posedge clk) disable iff (rst) $past(rst) |-> (count == 8'h00)
    );

    // While rst is asserted, the following cycle's count is 0 (synchronous reset).
    check_zero_during_reset: assert property (
        @(posedge clk) rst |=> (count == 8'h00)
    );

    // If load was 1 last cycle (and not in reset), count updates to data_in.
    check_load_updates_count: assert property (
        @(posedge clk) disable iff (rst) $past(load) && !$past(rst) |-> (count == $past(data_in))
    );

    // If enable&&increment last cycle with no load and not in reset, count increments by 1.
    check_increment_updates_count: assert property (
        @(posedge clk) disable iff (rst) !$past(load) && !$past(rst) && $past(enable && increment) |-> (count == $past(count) + 8'd1)
    );

    // If no load and no enable&&increment last cycle (and not in reset), count holds.
    check_stable_when_no_action: assert property (
        @(posedge clk) disable iff (rst) !$past(rst) && !$past(load) && !$past(enable && increment) |-> (count == $past(count))
    );

    // Increment at 8'hFF wraps to 8'h00 (no load, not in reset).
    check_increment_wraparound: assert property (
        @(posedge clk) disable iff (rst) !$past(rst) && !$past(load) && $past(enable && increment) && ($past(count) == 8'hFF) |-> (count == 8'h00)
    );

    // Load has priority over increment when both were asserted last cycle (not in reset).
    check_load_overrides_increment: assert property (
        @(posedge clk) disable iff (rst) !$past(rst) && $past(load) && $past(enable && increment) |-> (count == $past(data_in))
    );

    // Any change in count must be caused by rst, load, or (enable&&increment) last cycle.
    check_change_implies_cause: assert property (
        @(posedge clk) disable iff (rst) (count != $past(count)) |-> ($past(rst) || $past(load) || ($past(enable) && $past(increment)))
    );

    // If enable=1 and increment=0 last cycle with no load (and not in reset), count holds.
    check_enable_without_increment_no_change: assert property (
        @(posedge clk) disable iff (rst) !$past(rst) && !$past(load) && $past(enable) && !$past(increment) |-> (count == $past(count))
    );

    // If enable=0 and increment=1 last cycle with no load (and not in reset), count holds.
    check_increment_without_enable_no_change: assert property (
        @(posedge clk) disable iff (rst) !$past(rst) && !$past(load) && !$past(enable) && $past(increment) |-> (count == $past(count))
    );
endmodule

rtl:
module ddr3_init_sm (rst, clk, init_done, init_start);

input wire rst;
input wire clk;
input wire init_done;
output reg init_start;

reg [7:0] init_dly_cnt;

parameter IDLE = 3'b000,
			START_CNT = 3'b001,
			WAITFOR_CNT = 3'b010,
			INIT_DDR = 3'b011,
			INIT_DONE = 3'b100;

reg [2:0] state, next;

	always @(posedge clk or posedge rst)
		if (rst) state <= IDLE;
		else state <= next;

	always @(state or init_done or init_dly_cnt) begin
		next = 'bx;
		case (state)
			IDLE : next = START_CNT;
			START_CNT : next = WAITFOR_CNT;
			WAITFOR_CNT : if (init_dly_cnt == 8'h3c) next = INIT_DDR;
						else next = WAITFOR_CNT;
			INIT_DDR : if (init_done) next = INIT_DONE;
						else next = INIT_DDR;
			INIT_DONE : next = INIT_DONE;
		endcase
	end

	always @(posedge clk or posedge rst)
		if (rst) begin
			init_start <= 1'b0;
		end
		else begin
			init_start <= 1'b0;
		case (next)
			INIT_DDR: init_start <= 1'b1;
		endcase
	end

	always @(posedge clk or posedge rst)
	begin
		if (rst) begin
			init_dly_cnt <= 8'h00;
		end else begin
			init_dly_cnt <= init_dly_cnt + 1;
		end
	end

endmodule

sva:
module ddr3_init_sm_sva (
    input logic rst,
    input logic clk,
    input logic init_done,
    input logic init_start,
    input logic [2:0] state,
    input logic [2:0] next,
    input logic [7:0] init_dly_cnt
);
    // Clock: clk (posedge). Reset: rst (active-high, async). Mixed: sequential FSM + combinational next-state + free-running counter.

    // Mirror DUT encodings for readability
    localparam IDLE        = 3'b000;
    localparam START_CNT   = 3'b001;
    localparam WAITFOR_CNT = 3'b010;
    localparam INIT_DDR    = 3'b011;
    localparam INIT_DONE   = 3'b100;

    ///// Reset behavior /////
    // On reset, state must be IDLE.
    reset_state_to_idle: assert property (
        @(posedge clk) rst |-> (state == IDLE)
    );
    // On reset, init_start must be 0.
    reset_init_start_low: assert property (
        @(posedge clk) rst |-> (init_start == 1'b0)
    );
    // On reset, init_dly_cnt must be 0.
    reset_counter_zero: assert property (
        @(posedge clk) rst |-> (init_dly_cnt == 8'h00)
    );

    ///// Sequential updates /////
    // State register updates from previous next.
    check_state_updates_from_next: assert property (
        @(posedge clk) disable iff (rst) state == $past(next)
    );
    // Counter increments by 1 every cycle when not in reset.
    counter_increments: assert property (
        @(posedge clk) disable iff (rst) init_dly_cnt == ($past(init_dly_cnt) + 8'h01)
    );

    ///// Next-state logic /////
    // From IDLE, next must be START_CNT.
    next_from_idle_is_start: assert property (
        @(posedge clk) disable iff (rst) (state == IDLE) |-> (next == START_CNT)
    );
    // From START_CNT, next must be WAITFOR_CNT.
    next_from_start_is_wait: assert property (
        @(posedge clk) disable iff (rst) (state == START_CNT) |-> (next == WAITFOR_CNT)
    );
    // From WAITFOR_CNT with count hit, next must be INIT_DDR.
    next_from_wait_cnt_hit_is_initddr: assert property (
        @(posedge clk) disable iff (rst) (state == WAITFOR_CNT && init_dly_cnt == 8'h3c) |-> (next == INIT_DDR)
    );
    // From WAITFOR_CNT without count hit, next must be WAITFOR_CNT.
    next_from_wait_cnt_miss_is_wait: assert property (
        @(posedge clk) disable iff (rst) (state == WAITFOR_CNT && init_dly_cnt != 8'h3c) |-> (next == WAITFOR_CNT)
    );
    // From INIT_DDR with init_done asserted, next must be INIT_DONE.
    next_from_initddr_done_is_done: assert property (
        @(posedge clk) disable iff (rst) (state == INIT_DDR && init_done) |-> (next == INIT_DONE)
    );
    // From INIT_DDR with init_done deasserted, next must be INIT_DDR.
    next_from_initddr_notdone_is_initddr: assert property (
        @(posedge clk) disable iff (rst) (state == INIT_DDR && !init_done) |-> (next == INIT_DDR)
    );
    // From INIT_DONE, next must remain INIT_DONE.
    next_from_done_is_done: assert property (
        @(posedge clk) disable iff (rst) (state == INIT_DONE) |-> (next == INIT_DONE)
    );

    ///// Output behavior /////
    // init_start reflects whether next is INIT_DDR.
    init_start_matches_next: assert property (
        @(posedge clk) disable iff (rst) init_start == (next == INIT_DDR)
    );

    ///// One-cycle state transitions /////
    // IDLE -> START_CNT in one cycle.
    state_transition_idle_to_start: assert property (
        @(posedge clk) disable iff (rst) (state == IDLE) |=> (state == START_CNT)
    );
    // START_CNT -> WAITFOR_CNT in one cycle.
    state_transition_start_to_wait: assert property (
        @(posedge clk) disable iff (rst) (state == START_CNT) |=> (state == WAITFOR_CNT)
    );
    // WAITFOR_CNT with count hit -> INIT_DDR in one cycle.
    state_transition_wait_hit_to_initddr: assert property (
        @(posedge clk) disable iff (rst) (state == WAITFOR_CNT && init_dly_cnt == 8'h3c) |=> (state == INIT_DDR)
    );
    // INIT_DDR with init_done -> INIT_DONE in one cycle.
    state_transition_initddr_done_to_done: assert property (
        @(posedge clk) disable iff (rst) (state == INIT_DDR && init_done) |=> (state == INIT_DONE)
    );
endmodule

