module to_driver_sd_avs(
                        input wire         clk_sys,
                        input wire         rst,
                        input wire         ao486_rst,

                        input wire [31:0]  hdd_avalon_master_address,
                        input wire         hdd_avalon_master_read,
                        output wire [31:0] hdd_avalon_master_readdata,
                        input wire         hdd_avalon_master_write,
                        input wire [31:0]  hdd_avalon_master_writedata,
                        output wire        hdd_avalon_master_waitrequest,
                        output reg         hdd_avalon_master_readdatavalid,

                        input wire [31:0]  bios_loader_address,
                        input wire         bios_loader_read,
                        output wire [31:0] bios_loader_readdata,
                        input wire         bios_loader_write,
                        input wire [31:0]  bios_loader_writedata,
                        output wire        bios_loader_waitrequest,
                        input wire [3:0]   bios_loader_byteenable,

                        output wire [1:0]  driver_sd_avs_address,
                        output wire        driver_sd_avs_read,
                        input wire [31:0]  driver_sd_avs_readdata,
                        output wire        driver_sd_avs_write,
                        output wire [31:0] driver_sd_avs_writedata
                        );

    assign driver_sd_avs_address   = (~ao486_rst) ? hdd_avalon_master_address[3:2] : bios_loader_address[3:2];
    assign driver_sd_avs_read      = (~ao486_rst) ? hdd_avalon_master_read : bios_loader_read && bios_loader_address[31:4] == 28'h0;
    assign driver_sd_avs_write     = (~ao486_rst) ? hdd_avalon_master_write : bios_loader_write && bios_loader_address[31:4] == 28'h0;
    assign driver_sd_avs_writedata = (~ao486_rst) ? hdd_avalon_master_writedata : bios_loader_writedata;

    assign hdd_avalon_master_readdata = (~ao486_rst) ? driver_sd_avs_readdata : 0;
    assign hdd_avalon_master_waitrequest = 0;
    always @(posedge clk_sys) hdd_avalon_master_readdatavalid <= (~ao486_rst) ? driver_sd_avs_read : 0;

    assign bios_loader_readdata = (~ao486_rst) ? 0 : driver_sd_avs_readdata;
    assign bios_loader_waitrequest = 0;

endmodule

sva:
module to_driver_sd_avs_sva (
    input logic         clk_sys,
    input logic         rst,
    input logic         ao486_rst,

    input logic [31:0]  hdd_avalon_master_address,
    input logic         hdd_avalon_master_read,
    input logic [31:0]  hdd_avalon_master_readdata,
    input logic         hdd_avalon_master_write,
    input logic [31:0]  hdd_avalon_master_writedata,
    input logic         hdd_avalon_master_waitrequest,
    input logic         hdd_avalon_master_readdatavalid,

    input logic [31:0]  bios_loader_address,
    input logic         bios_loader_read,
    input logic [31:0]  bios_loader_readdata,
    input logic         bios_loader_write,
    input logic [31:0]  bios_loader_writedata,
    input logic         bios_loader_waitrequest,
    input logic [3:0]   bios_loader_byteenable,

    input logic [1:0]   driver_sd_avs_address,
    input logic         driver_sd_avs_read,
    input logic [31:0]  driver_sd_avs_readdata,
    input logic         driver_sd_avs_write,
    input logic [31:0]  driver_sd_avs_writedata
);

    ///// Path selection to driver_sd_avs /////
    // Address mux selects bits [3:2] from the active source.
    check_driver_address_mux: assert property (
        @(posedge clk_sys) disable iff (rst)
        driver_sd_avs_address == ((~ao486_rst) ? hdd_avalon_master_address[3:2] : bios_loader_address[3:2])
    );

    // Read control is from HDD when ~ao486_rst, else gated BIOS read in 0x0000_0000..0x0000_000F.
    check_driver_read_mux: assert property (
        @(posedge clk_sys) disable iff (rst)
        driver_sd_avs_read == ((~ao486_rst) ? hdd_avalon_master_read
                                            : (bios_loader_read && (bios_loader_address[31:4] == 28'h0)))
    );

    // Write control is from HDD when ~ao486_rst, else gated BIOS write in 0x0000_0000..0x0000_000F.
    check_driver_write_mux: assert property (
        @(posedge clk_sys) disable iff (rst)
        driver_sd_avs_write == ((~ao486_rst) ? hdd_avalon_master_write
                                             : (bios_loader_write && (bios_loader_address[31:4] == 28'h0)))
    );

    // Writedata is from the active source without additional gating.
    check_driver_wdata_mux: assert property (
        @(posedge clk_sys) disable iff (rst)
        driver_sd_avs_writedata == ((~ao486_rst) ? hdd_avalon_master_writedata : bios_loader_writedata)
    );

    ///// Return path to masters /////
    // HDD readdata reflects driver data when ~ao486_rst, else 0.
    check_hdd_readdata_mux: assert property (
        @(posedge clk_sys) disable iff (rst)
        hdd_avalon_master_readdata == ((~ao486_rst) ? driver_sd_avs_readdata : 32'h0)
    );

    // BIOS readdata reflects driver data when ao486_rst, else 0.
    check_bios_readdata_mux: assert property (
        @(posedge clk_sys) disable iff (rst)
        bios_loader_readdata == (ao486_rst ? driver_sd_avs_readdata : 32'h0)
    );

    // HDD waitrequest is hardwired LOW.
    check_hdd_waitreq_zero: assert property (
        @(posedge clk_sys) disable iff (rst)
        hdd_avalon_master_waitrequest == 1'b0
    );

    // BIOS waitrequest is hardwired LOW.
    check_bios_waitreq_zero: assert property (
        @(posedge clk_sys) disable iff (rst)
        bios_loader_waitrequest == 1'b0
    );

    ///// Registered status /////
    // HDD readdatavalid mirrors driver_sd_avs_read when ~ao486_rst, else 0.
    check_hdd_readdatavalid_reg: assert property (
        @(posedge clk_sys) disable iff (rst)
        hdd_avalon_master_readdatavalid == ((~ao486_rst) ? driver_sd_avs_read : 1'b0)
    );

    // HDD readdatavalid cannot be 1 while ao486_rst is asserted.
    check_hdd_readdatavalid_blocked_in_reset: assert property (
        @(posedge clk_sys) disable iff (rst)
        hdd_avalon_master_readdatavalid |-> (~ao486_rst)
    );

    ///// BIOS address gating /////
    // When BIOS address is outside 0x0000_0000..0x0000_000F, no read/write reaches the driver.
    check_bios_addr_blocks_access_outside_window: assert property (
        @(posedge clk_sys) disable iff (rst)
        ao486_rst && (bios_loader_address[31:4] != 28'h0) |-> (!driver_sd_avs_read && !driver_sd_avs_write)
    );

endmodule

rtl:
module alu (a_in, b_in, alu_function, c_alu);

   input  [31:0] a_in        ;
   input  [31:0] b_in        ;
   input  [ 3:0] alu_function;
   output [31:0] c_alu       ;

   wire [32:0] aa      ;
   wire [32:0] bb      ;
   wire [32:0] sum     ;
   wire        do_add  ;
   wire        sign_ext;

   assign do_add   = (alu_function == 4'b0001) ? 1'b1 : 1'b0 ; // alu_add
   assign sign_ext = (alu_function == 4'b0010) ? 1'b0 : 1'b1 ; // alu_less_than
   assign aa       = {(a_in[31] & sign_ext), a_in} ;
   assign bb       = {(b_in[31] & sign_ext), b_in} ;

   reg [31:0] c_alu;
   always @(*) begin
        case(alu_function)
            4'b0001 : c_alu = sum[31:0]         ; // alu_add
            4'b0010 : c_alu = {31'b0, sum[32]}  ; // alu_less_than
            4'b0100 : c_alu = a_in | b_in       ; // alu_or
            4'b0101 : c_alu = a_in & b_in       ; // alu_and
            4'b0110 : c_alu = a_in ^ b_in       ; // alu_xor
            4'b0111 : c_alu = ~(a_in | b_in)    ; // alu_nor
            default : c_alu = 32'b0             ; // alu_nothing
        endcase
    end

   assign sum = (do_add)? aa+bb : aa-bb;

endmodule

sva:
module alu_sva (
    input logic clk,
    input logic [31:0] a_in,
    input logic [31:0] b_in,
    input logic [3:0]  alu_function,
    input logic [31:0] c_alu
);
    // For alu_add (0001), output equals lower 32 bits of sign-extended 33-bit a_in + b_in.
    check_add_lower32_from_signext_add: assert property (
        @(posedge clk) disable iff (1'b0)
            (alu_function == 4'b0001) |-> (c_alu == (({a_in[31], a_in} + {b_in[31], b_in})[31:0]))
    );

    // For alu_add (0001), output equals 32-bit a_in + b_in (ignoring carry-out).
    check_add_32bit_equivalence: assert property (
        @(posedge clk) disable iff (1'b0)
            (alu_function == 4'b0001) |-> (c_alu == (a_in + b_in))
    );

    // For alu_less_than (0010), output is 1 when a_in < b_in (unsigned) and zero otherwise.
    check_less_than_unsigned: assert property (
        @(posedge clk) disable iff (1'b0)
            (alu_function == 4'b0010) |-> ((c_alu[31:1] == 31'b0) && (c_alu[0] == (a_in < b_in)))
    );

    // For alu_less_than (0010), LSB equals borrow of zero-extended subtraction a_in - b_in.
    check_less_than_borrow_equals_lsb: assert property (
        @(posedge clk) disable iff (1'b0)
            (alu_function == 4'b0010) |-> (c_alu[0] == (({1'b0, a_in} - {1'b0, b_in})[32]))
    );

    // For alu_or (0100), output equals a_in | b_in.
    check_or_result: assert property (
        @(posedge clk) disable iff (1'b0)
            (alu_function == 4'b0100) |-> (c_alu == (a_in | b_in))
    );

    // For alu_and (0101), output equals a_in & b_in.
    check_and_result: assert property (
        @(posedge clk) disable iff (1'b0)
            (alu_function == 4'b0101) |-> (c_alu == (a_in & b_in))
    );

    // For alu_xor (0110), output equals a_in ^ b_in.
    check_xor_result: assert property (
        @(posedge clk) disable iff (1'b0)
            (alu_function == 4'b0110) |-> (c_alu == (a_in ^ b_in))
    );

    // For alu_nor (0111), output equals ~(a_in | b_in).
    check_nor_result: assert property (
        @(posedge clk) disable iff (1'b0)
            (alu_function == 4'b0111) |-> (c_alu == ~(a_in | b_in))
    );

    // For all other opcodes, output is zero.
    check_default_zero: assert property (
        @(posedge clk) disable iff (1'b0)
            (!(alu_function inside {4'b0001,4'b0010,4'b0100,4'b0101,4'b0110,4'b0111})) |-> (c_alu == 32'b0)
    );
endmodule

rtl:
module mux (
    input A,
    input B,
    input C,
    input invert,
    output out
);

reg out_reg;

always @ * begin
    if (C == 1'b0) begin
        out_reg <= A;
    end else if (C == 1'b1) begin
        if (invert == 1'b0) begin
            out_reg <= B;
        end else begin
            out_reg <= ~B;
        end
    end
end

assign out = out_reg;

endmodule

sva:
module mux_sva (
    input logic clk,       // verification clock (RTL has no clock/reset)
    input logic A,
    input logic B,
    input logic C,
    input logic invert,
    input logic out
);
    // Functional equivalence: out matches the mux/invert expression
    check_functional_equiv: assert property (
        @(posedge clk) out == (C ? (invert ? ~B : B) : A)
    );

    // When C==0, out equals A
    check_sel_C0: assert property (
        @(posedge clk) (C == 1'b0) |-> (out == A)
    );

    // When C==1 and invert==0, out equals B
    check_sel_C1_inv0: assert property (
        @(posedge clk) ((C == 1'b1) && (invert == 1'b0)) |-> (out == B)
    );

    // When C==1 and invert==1, out equals ~B
    check_sel_C1_inv1: assert property (
        @(posedge clk) ((C == 1'b1) && (invert == 1'b1)) |-> (out == ~B)
    );

    // When C==1, out equals B XOR invert
    check_C1_xor: assert property (
        @(posedge clk) (C == 1'b1) |-> (out == (B ^ invert))
    );

    // On C rising, out follows the B/invert path
    check_rose_C: assert property (
        @(posedge clk) $rose(C) |-> (out == (invert ? ~B : B))
    );

    // On C falling, out follows A
    check_fell_C: assert property (
        @(posedge clk) $fell(C) |-> (out == A)
    );

    // On invert rising while C==1, out becomes ~B
    check_rose_invert_C1: assert property (
        @(posedge clk) (C == 1'b1) && $rose(invert) |-> (out == ~B)
    );

    // On invert falling while C==1, out becomes B
    check_fell_invert_C1: assert property (
        @(posedge clk) (C == 1'b1) && $fell(invert) |-> (out == B)
    );

    // When B changes and C==1, out updates per invert
    check_B_change_C1: assert property (
        @(posedge clk) (C == 1'b1) && $changed(B) |-> (out == (invert ? ~B : B))
    );

    // When A changes and C==0, out updates to A
    check_A_change_C0: assert property (
        @(posedge clk) (C == 1'b0) && $changed(A) |-> (out == A)
    );

    // If all inputs are stable, out remains stable
    check_stable_inputs_imply_stable_out: assert property (
        @(posedge clk) $stable(A) && $stable(B) && $stable(C) && $stable(invert) |-> $stable(out)
    );
endmodule

rtl:
module mux_2to1_power(
  input A1,
  input A2,
  input B1,
  input B2,
  output X,
  input VPB,
  input VPWR,
  input VGND,
  input VNB
);

  wire sel;
  assign sel = A1 | A2;

  assign X = sel ? (A1 ? B1 : B2) : 1'b0;

endmodule

sva:
module mux_2to1_power_sva (
    input logic A1,
    input logic A2,
    input logic B1,
    input logic B2,
    input logic X,
    input logic VPB,
    input logic VPWR,
    input logic VGND,
    input logic VNB
);
    // When neither select is asserted, X must be 0.
    check_no_select_forces_zero: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge B1 or negedge B1 or posedge B2 or negedge B2)
        (!A1 && !A2) |-> (X == 1'b0)
    );

    // When A1 is asserted, X must equal B1.
    check_a1_selects_b1: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge B1 or negedge B1 or posedge B2 or negedge B2)
        A1 |-> (X == B1)
    );

    // When only A2 is asserted, X must equal B2.
    check_a2_selects_b2_when_a1_zero: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge B1 or negedge B1 or posedge B2 or negedge B2)
        (!A1 && A2) |-> (X == B2)
    );

    // Functional equivalence of X to the boolean expression.
    check_functional_equivalence: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge B1 or negedge B1 or posedge B2 or negedge B2)
        X == ((A1 && B1) || ((!A1) && A2 && B2))
    );

    // If X is 1, it must come from either A1&B1 or (!A1)&A2&B2.
    check_x_high_requires_valid_path: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge B1 or negedge B1 or posedge B2 or negedge B2)
        (X == 1'b1) |-> ((A1 && B1) || ((!A1) && A2 && B2))
    );

    // If both data inputs are 0, X must be 0 regardless of selects.
    check_zero_when_both_data_zero: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge B1 or negedge B1 or posedge B2 or negedge B2)
        (!B1 && !B2) |-> (X == 1'b0)
    );

    // A1=1 and B1=1 must drive X=1.
    check_high_when_a1_and_b1_high: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge B1 or negedge B1 or posedge B2 or negedge B2)
        (A1 && B1) |-> (X == 1'b1)
    );

    // With A1=0 and A2=1, B2=1 must drive X=1.
    check_high_when_a2_selected_and_b2_high: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge B1 or negedge B1 or posedge B2 or negedge B2)
        ((!A1) && A2 && B2) |-> (X == 1'b1)
    );
endmodule

rtl:
module up_down_counter (
  input clk,
  input reset,
  input enable,
  input mode,
  output reg [2:0] q
);

  always @(posedge clk or negedge reset) begin
    if (!reset) begin
      q <= 3'b0;
    end else if (enable) begin
      if (mode) begin
        // Down mode
        if (q == 3'b000) begin
          q <= 3'b111;
        end else begin
          q <= q - 1;
        end
      end else begin
        // Up mode
        if (q == 3'b111) begin
          q <= 3'b000;
        end else begin
          q <= q + 1;
        end
      end
    end
  end

endmodule

sva:
module up_down_counter_sva (
  input logic clk,
  input logic reset,       // active-low asynchronous reset in RTL
  input logic enable,
  input logic mode,        // 0: up, 1: down
  input logic [2:0] q
);

  ///// Reset behavior /////
  // While reset is asserted low, q is forced to 0.
  reset_forces_zero: assert property (
    @(posedge clk) (!reset) |-> (q == 3'b000)
  );

  ///// Enable gating /////
  // When enable is LOW, q holds its previous value.
  hold_when_disabled: assert property (
    @(posedge clk) disable iff (!reset) (!enable) |=> (q == $past(q))
  );

  // q only changes when enable was HIGH in the previous cycle (excluding reset effects).
  change_only_when_enabled: assert property (
    @(posedge clk) disable iff (!reset) (q != $past(q)) |-> $past(enable)
  );

  ///// Up mode behavior (mode == 0) /////
  // In up mode with enable, non-wrap increment by 1.
  upmode_inc_nonwrap: assert property (
    @(posedge clk) disable iff (!reset) (enable && !mode && (q != 3'b111)) |=> (q == $past(q) + 3'b001)
  );

  // In up mode with enable, wrap from 7 to 0.
  upmode_wrap_from_max: assert property (
    @(posedge clk) disable iff (!reset) (enable && !mode && (q == 3'b111)) |=> (q == 3'b000)
  );

  // In up mode with enable, wrap occurs iff previous q was 7.
  upmode_wrap_iff_prev_max: assert property (
    @(posedge clk) disable iff (!reset) (enable && !mode) |=> (($past(q) == 3'b111) == (q == 3'b000))
  );

  ///// Down mode behavior (mode == 1) /////
  // In down mode with enable, non-wrap decrement by 1.
  downmode_dec_nonwrap: assert property (
    @(posedge clk) disable iff (!reset) (enable && mode && (q != 3'b000)) |=> (q == $past(q) - 3'b001)
  );

  // In down mode with enable, wrap from 0 to 7.
  downmode_wrap_from_zero: assert property (
    @(posedge clk) disable iff (!reset) (enable && mode && (q == 3'b000)) |=> (q == 3'b111)
  );

  // In down mode with enable, wrap occurs iff previous q was 0.
  downmode_wrap_iff_prev_zero: assert property (
    @(posedge clk) disable iff (!reset) (enable && mode) |=> (($past(q) == 3'b000) == (q == 3'b111))
  );

  ///// General enabled behavior /////
  // When enabled, q must change every cycle (either +/-1 with wrap).
  enabled_always_changes: assert property (
    @(posedge clk) disable iff (!reset) enable |=> (q != $past(q))
  );

endmodule

rtl:
module my_module (
   input in,
   input clk,
   output reg fr_a,
   output reg fr_b,
   output reg fr_chk
   );

   always @(posedge clk) begin
      fr_a <= in;
      fr_b <= in;
      fr_chk <= in + 1;
   end

endmodule

sva:
module my_module_sva (
    input logic in,
    input logic clk,
    input logic fr_a,
    input logic fr_b,
    input logic fr_chk
);
    ///// Sequential sampling /////
    // fr_a samples 'in' on each rising clock (1-cycle latency).
    check_fr_a_samples_in: assert property (
        @(posedge clk) fr_a == $past(in)
    );
    // fr_b samples 'in' on each rising clock (1-cycle latency).
    check_fr_b_samples_in: assert property (
        @(posedge clk) fr_b == $past(in)
    );
    // fr_chk captures LSB of (in + 1), i.e., complement of previous 'in'.
    check_fr_chk_complements_in: assert property (
        @(posedge clk) fr_chk == ~ $past(in)
    );

    ///// Edge propagation /////
    // A rise on 'in' causes a rise on fr_a one cycle later.
    in_rise_to_fr_a_rise: assert property (
        @(posedge clk) $rose(in) |=> $rose(fr_a)
    );
    // A fall on 'in' causes a fall on fr_a one cycle later.
    in_fall_to_fr_a_fall: assert property (
        @(posedge clk) $fell(in) |=> $fell(fr_a)
    );
    // A rise on 'in' causes a rise on fr_b one cycle later.
    in_rise_to_fr_b_rise: assert property (
        @(posedge clk) $rose(in) |=> $rose(fr_b)
    );
    // A fall on 'in' causes a fall on fr_b one cycle later.
    in_fall_to_fr_b_fall: assert property (
        @(posedge clk) $fell(in) |=> $fell(fr_b)
    );
    // A rise on 'in' causes a fall on fr_chk one cycle later.
    in_rise_to_fr_chk_fall: assert property (
        @(posedge clk) $rose(in) |=> $fell(fr_chk)
    );
    // A fall on 'in' causes a rise on fr_chk one cycle later.
    in_fall_to_fr_chk_rise: assert property (
        @(posedge clk) $fell(in) |=> $rose(fr_chk)
    );
endmodule

rtl:
module soc_design_SystemID (
  // inputs:
  address,
  clock,
  reset_n,

  // outputs:
  readdata
);

  output [31:0] readdata;
  input [31:0] address;
  input clock;
  input reset_n;

  reg [31:0] readdata_reg;

  always @(posedge clock or negedge reset_n) begin
    if (!reset_n) begin
      readdata_reg <= 32'h0;
    end else begin
      readdata_reg <= (address == 32'h0) ? 32'hff : 32'h590d8d31;
    end
  end

  assign readdata = readdata_reg;

endmodule

sva:
module soc_design_SystemID_sva (
    input logic clock,
    input logic reset_n,
    input logic [31:0] address,
    input logic [31:0] readdata
);
    // During reset, readdata is 0.
    check_reset_forces_zero: assert property (
        @(posedge clock) (!reset_n) |-> (readdata == 32'h00000000)
    );

    // On falling edge of reset_n, readdata is 0 at this sample.
    check_reset_fall_clears_output: assert property (
        @(posedge clock) $fell(reset_n) |-> (readdata == 32'h00000000)
    );

    // On rising edge of reset_n, readdata remains 0 in this cycle.
    check_reset_rise_zero_this_cycle: assert property (
        @(posedge clock) $rose(reset_n) |-> (readdata == 32'h00000000)
    );

    // Out of reset, readdata equals function of previous-cycle address.
    check_prev_addr_mapping: assert property (
        @(posedge clock) disable iff (!reset_n)
            $past(reset_n) |-> (readdata == (($past(address) == 32'h00000000) ? 32'h000000FF : 32'h590D8D31))
    );

    // When operational, readdata is one of the two allowed constants.
    check_operational_value_domain: assert property (
        @(posedge clock) disable iff (!reset_n)
            $past(reset_n) |-> (readdata inside {32'h000000FF, 32'h590D8D31})
    );

    // When operational, readdata is never zero.
    check_operational_nonzero: assert property (
        @(posedge clock) disable iff (!reset_n)
            $past(reset_n) |-> (readdata != 32'h00000000)
    );

    // If address==0 and remain out of reset, next-cycle readdata is 0xFF.
    check_forward_pipeline_zero: assert property (
        @(posedge clock) disable iff (!reset_n)
            (address == 32'h00000000) |-> ##1 (reset_n && (readdata == 32'h000000FF))
    );

    // If address!=0 and remain out of reset, next-cycle readdata is 0x590D8D31.
    check_forward_pipeline_nonzero: assert property (
        @(posedge clock) disable iff (!reset_n)
            (address != 32'h00000000) |-> ##1 (reset_n && (readdata == 32'h590D8D31))
    );

    // With two-cycle stable address and out of reset, readdata stays stable.
    check_stable_address_two_cycles_keeps_output_stable: assert property (
        @(posedge clock) disable iff (!reset_n)
            ($past(reset_n) && $past(reset_n,2) && ($past(address) == $past(address,2))) |-> (readdata == $past(readdata))
    );

    // With two cycles out of reset, both current and previous outputs match their respective address mappings.
    check_two_cycle_correlation: assert property (
        @(posedge clock) disable iff (!reset_n)
            ($past(reset_n) && $past(reset_n,2)) |-> 
            (($past(readdata) == (($past(address,2) == 32'h00000000) ? 32'h000000FF : 32'h590D8D31)) &&
             (readdata       == (($past(address)    == 32'h00000000) ? 32'h000000FF : 32'h590D8D31)))
    );
endmodule

module compm4_sva (
    input logic clk,
    input logic A0,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic B0,
    input logic B1,
    input logic B2,
    input logic B3,
    input logic GT,
    input logic LT
);
    // GT matches unsigned compare A>B
    check_gt_definition: assert property (
        @(posedge clk) GT == ({A3,A2,A1,A0} > {B3,B2,B1,B0})
    );

    // LT matches unsigned compare A<B
    check_lt_definition: assert property (
        @(posedge clk) LT == ({A3,A2,A1,A0} < {B3,B2,B1,B0})
    );

    // GT and LT are never both 1
    check_mutual_exclusion: assert property (
        @(posedge clk) !(GT && LT)
    );

    // When A==B, both outputs are 0
    check_equal_outputs_zero: assert property (
        @(posedge clk) ({A3,A2,A1,A0} == {B3,B2,B1,B0}) |=> (GT == 1'b0 && LT == 1'b0)
    );

    // When A!=B, exactly one of GT or LT is 1
    check_inequal_outputs_xor: assert property (
        @(posedge clk) ({A3,A2,A1,A0} != {B3,B2,B1,B0}) |=> (GT ^ LT)
    );

    // If GT is 1 then LT is 0
    check_gt_implies_not_lt: assert property (
        @(posedge clk) GT |=> (LT == 1'b0)
    );

    // If LT is 1 then GT is 0
    check_lt_implies_not_gt: assert property (
        @(posedge clk) LT |=> (GT == 1'b0)
    );

    // When A>B, GT=1 and LT=0
    check_outputs_when_A_gt_B: assert property (
        @(posedge clk) ({A3,A2,A1,A0} > {B3,B2,B1,B0}) |=> (GT == 1'b1 && LT == 1'b0)
    );

    // When A<B, LT=1 and GT=0
    check_outputs_when_A_lt_B: assert property (
        @(posedge clk) ({A3,A2,A1,A0} < {B3,B2,B1,B0}) |=> (LT == 1'b1 && GT == 1'b0)
    );
endmodule

module binary_counter_sva (
    input logic clk,
    input logic rst,
    input logic en,
    input logic [3:0] count
);
    ///// Reset behavior /////
    // When rst is HIGH at a clock edge, count must be zero.
    check_reset_forces_zero: assert property (
        @(posedge clk) rst |-> (count == 4'd0)
    );

    // During reset, count is known and zero (no X/Z while rst is HIGH).
    check_known_zero_during_reset: assert property (
        @(posedge clk) rst |-> (!$isunknown(count) && count == 4'd0)
    );

    ///// Enable-driven counting (gated to cycles where rst is LOW at both ends) /////
    // With rst LOW in both cycles and en LOW in the previous cycle, count holds its value.
    check_hold_when_en_low: assert property (
        @(posedge clk) disable iff (rst)
            ($past(!rst,1,1'b0) && !rst && $past(!en,1,1'b0)) |-> (count == $past(count,1,4'h0))
    );

    // With rst LOW in both cycles and en HIGH in the previous cycle, count increments by 1 (mod 16).
    check_increment_when_en_high: assert property (
        @(posedge clk) disable iff (rst)
            ($past(!rst,1,1'b0) && !rst && $past(en,1,1'b0)) |-> (count == (($past(count,1,4'h0) + 4'd1) & 4'hF))
    );

    // With rst LOW in both cycles, if prior count was 4'hF and en was HIGH, next count wraps to 0.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (rst)
            ($past(!rst,1,1'b0) && !rst && $past(en,1,1'b0) && ($past(count,1,4'h0) == 4'hF)) |-> (count == 4'h0)
    );
endmodule

rtl:
module fb_rxcounters (
   input MRxClk, Reset, MRxDV, RxValid,
   input StateIdle, StateFFS, StatePreamble,
   input [1:0] StateData,
   input StateFrmCrc,
   input MRxDEqDataSoC,
   output TotalRecvNibCntEq0,
   output [15:0] TotalRecvNibCnt,
   output [7:0] RxRamAddr,
   output [3:0] FrmCrcNibCnt,
   output FrmCrcStateEnd
);
   reg [15:0] TotalRecvNibCnt;
   reg [7:0] RxRamAddr;
   reg [3:0] FrmCrcNibCnt;
   wire ResetTotalRecvNibCnt, IncrementTotalRecvNibCnt;
   wire ResetRxRamAddr, IncrementRxRamAddr;
   wire IncrementFrmCrcNibCnt, ResetFrmCrcNibCnt;

   assign ResetTotalRecvNibCnt = StateIdle & ~MRxDV;
   assign IncrementTotalRecvNibCnt = MRxDV;
   always @(posedge MRxClk or posedge Reset) begin
      if (Reset) TotalRecvNibCnt <= 16'd0;
      else if (ResetTotalRecvNibCnt) TotalRecvNibCnt <= 16'd0;
      else if (IncrementTotalRecvNibCnt) TotalRecvNibCnt <= TotalRecvNibCnt + 16'd1;
   end

   assign TotalRecvNibCntEq0 = (TotalRecvNibCnt == 16'd0);

   assign ResetRxRamAddr = StateIdle | StateFFS | StatePreamble;
   assign IncrementRxRamAddr = RxValid;
   always @(posedge MRxClk or posedge Reset) begin
      if (Reset) RxRamAddr <= 8'd0;
      else if (ResetRxRamAddr) RxRamAddr <= 8'd0;
      else if (IncrementRxRamAddr) RxRamAddr <= RxRamAddr + 8'd1;
   end

   assign IncrementFrmCrcNibCnt = StateFrmCrc;
   assign ResetFrmCrcNibCnt = StateIdle;
   assign FrmCrcStateEnd = FrmCrcNibCnt[0];
   always @(posedge MRxClk or posedge Reset) begin
      if (Reset) FrmCrcNibCnt <= 4'd0;
      else if (ResetFrmCrcNibCnt) FrmCrcNibCnt <= 4'd0;
      else if (IncrementFrmCrcNibCnt) FrmCrcNibCnt <= FrmCrcNibCnt + 4'd1;
   end
endmodule

sva:
module fb_rxcounters_sva (
   input logic MRxClk,
   input logic Reset,
   input logic MRxDV,
   input logic RxValid,
   input logic StateIdle,
   input logic StateFFS,
   input logic StatePreamble,
   input logic [1:0] StateData,
   input logic StateFrmCrc,
   input logic MRxDEqDataSoC,
   input logic TotalRecvNibCntEq0,
   input logic [15:0] TotalRecvNibCnt,
   input logic [7:0] RxRamAddr,
   input logic [3:0] FrmCrcNibCnt,
   input logic FrmCrcStateEnd
);
   ///// Global reset effects (active-high, async) /////
   // On Reset, TotalRecvNibCnt must be 0.
   totalcnt_zero_on_reset: assert property (
      @(posedge MRxClk) Reset |-> (TotalRecvNibCnt == 16'd0)
   );
   // On Reset, RxRamAddr must be 0.
   rxaddr_zero_on_reset: assert property (
      @(posedge MRxClk) Reset |-> (RxRamAddr == 8'd0)
   );
   // On Reset, FrmCrcNibCnt must be 0.
   frmcrc_zero_on_reset: assert property (
      @(posedge MRxClk) Reset |-> (FrmCrcNibCnt == 4'd0)
   );
   // On Reset, TotalRecvNibCntEq0 must be 1.
   eq0_high_on_reset: assert property (
      @(posedge MRxClk) Reset |-> (TotalRecvNibCntEq0 == 1'b1)
   );

   ///// Combinational outputs reflect registered values /////
   // TotalRecvNibCntEq0 equals (TotalRecvNibCnt == 0).
   eq0_matches_counter: assert property (
      @(posedge MRxClk) disable iff (Reset) (TotalRecvNibCntEq0 == (TotalRecvNibCnt == 16'd0))
   );
   // FrmCrcStateEnd equals LSB of FrmCrcNibCnt.
   frmcrcstateend_matches_lsb: assert property (
      @(posedge MRxClk) disable iff (Reset) (FrmCrcStateEnd == FrmCrcNibCnt[0])
   );

   ///// TotalRecvNibCnt behavior /////
   // When StateIdle && !MRxDV, counter resets to 0 on next cycle.
   totalcnt_reset_on_idle_no_dv: assert property (
      @(posedge MRxClk) disable iff (Reset) (StateIdle && !MRxDV) |-> ##1 (TotalRecvNibCnt == 16'd0)
   );
   // When MRxDV, counter increments by 1 on next cycle.
   totalcnt_increments_on_mrxdv: assert property (
      @(posedge MRxClk) disable iff (Reset) MRxDV |-> ##1 (TotalRecvNibCnt == $past(TotalRecvNibCnt) + 16'd1)
   );
   // When !MRxDV and not idle, counter holds its value.
   totalcnt_holds_without_inc_or_rst: assert property (
      @(posedge MRxClk) disable iff (Reset) (!MRxDV && !StateIdle) |-> ##1 (TotalRecvNibCnt == $past(TotalRecvNibCnt))
   );

   ///// RxRamAddr behavior /////
   // When StateIdle/StateFFS/StatePreamble, address resets to 0 on next cycle.
   rxaddr_reset_on_state_reset: assert property (
      @(posedge MRxClk) disable iff (Reset) (StateIdle || StateFFS || StatePreamble) |-> ##1 (RxRamAddr == 8'd0)
   );
   // When RxValid and not in reset states, address increments by 1 on next cycle.
   rxaddr_increments_on_rxvalid: assert property (
      @(posedge MRxClk) disable iff (Reset) (RxValid && !(StateIdle || StateFFS || StatePreamble)) |-> ##1 (RxRamAddr == $past(RxRamAddr) + 8'd1)
   );
   // When not incrementing and not resetting, address holds its value.
   rxaddr_holds_without_inc_or_rst: assert property (
      @(posedge MRxClk) disable iff (Reset) (!RxValid && !(StateIdle || StateFFS || StatePreamble)) |-> ##1 (RxRamAddr == $past(RxRamAddr))
   );

   ///// FrmCrcNibCnt behavior /////
   // When StateIdle, CRC nibble counter resets to 0 on next cycle.
   frmcrc_reset_on_idle: assert property (
      @(posedge MRxClk) disable iff (Reset) StateIdle |-> ##1 (FrmCrcNibCnt == 4'd0)
   );
   // When StateFrmCrc and not idle, CRC nibble counter increments by 1 on next cycle.
   frmcrc_increments_in_crc_state: assert property (
      @(posedge MRxClk) disable iff (Reset) (StateFrmCrc && !StateIdle) |-> ##1 (FrmCrcNibCnt == $past(FrmCrcNibCnt) + 4'd1)
   );
   // When not in CRC state and not idle, CRC nibble counter holds its value.
   frmcrc_holds_without_inc_or_rst: assert property (
      @(posedge MRxClk) disable iff (Reset) (!StateFrmCrc && !StateIdle) |-> ##1 (FrmCrcNibCnt == $past(FrmCrcNibCnt))
   );
endmodule

