module my_module(
   input                sgmii_refclk_p,
   input                sgmii_refclk_n,
   input [3:0]          sgmii_rxn,
   input [3:0]          sgmii_rxp,
   input                pl_btn,
   output [3:0]         sgmii_txn,
   output [3:0]         sgmii_txp,
   output               mdio_mdc,
   output [1:0]         pl_led,
   output [1:0]         pl_pmod
);


   reg [23:0] cnt_0;
