module adder #(parameter WIDTH=8) (
    input clk, rst, load,
    input [WIDTH-1:0] A, B,
    output [WIDTH-1:0] Q
);

    wire [WIDTH:0] carry;
    wire [WIDTH-1:0] sum;

    // Ripple-carry adder
    genvar i;
    generate 
        for (i = 0; i < WIDTH; i = i + 1) begin : adder_stage
            full_adder FA (
                .a(A[i]), .b(B[i]), .c(carry[i]),
                .sum(sum[i]), .carry(carry[i+1])
            );
        end
    endgenerate

    // Carry-out for the last stage
    assign carry[WIDTH] = (A[WIDTH-1] & B[WIDTH-1]) | (A[WIDTH-1] & carry[WIDTH-1]) | (B[WIDTH-1] & carry[WIDTH-1]);

    // Registering the output
    reg [WIDTH-1:0] Q_reg;
    always @(posedge clk) begin
        if (rst) begin
            Q_reg <= 0;
        end else if (load) begin
            Q_reg <= sum;
        end
    end

    assign Q = Q_reg;

    assign carry[0] = 0; // Connect the first carry-in to 0.

endmodule
module full_adder (
    input a, b, c,
    output sum, carry
);

    assign sum = a ^ b ^ c;
    assign carry = (a & b) | (a & c) | (b & c);

endmodule

sva:
module adder_sva #(parameter WIDTH=8) (
    input logic clk,
    input logic rst,       // Active-high synchronous reset
    input logic load,
    input logic [WIDTH-1:0] A,
    input logic [WIDTH-1:0] B,
    input logic [WIDTH-1:0] Q
);

    ///// Reset behavior /////
    // One cycle after rst is asserted, Q must be zero.
    check_reset_clears_q_next: assert property (
        @(posedge clk) rst |=> (Q == '0)
    );

    // If rst is asserted in consecutive cycles, Q is zero in the later cycle.
    check_in_reset_q_zero_current: assert property (
        @(posedge clk) ($past(rst) && rst) |-> (Q == '0)
    );

    // Reset has priority over load; if both high, Q still clears to zero next cycle.
    check_reset_overrides_load: assert property (
        @(posedge clk) (rst && load) |=> (Q == '0)
    );

    ///// Sequential update semantics /////
    // Without load (and not coming from reset), Q holds its previous value.
    check_hold_without_load: assert property (
        @(posedge clk) disable iff (rst)
            ($past(1'b1) && !$past(load) && !$past(rst)) |-> (Q == $past(Q))
    );

    // Q only changes when the previous cycle had load or reset.
    check_change_requires_load_or_reset: assert property (
        @(posedge clk) disable iff (rst)
            ($past(1'b1) && (Q != $past(Q))) |-> ($past(load) || $past(rst))
    );

    ///// Functional correctness /////
    // After a load (and not from reset), Q equals A+B modulo WIDTH from the load cycle.
    check_sum_update_correct: assert property (
        @(posedge clk) disable iff (rst)
            ($past(1'b1) && $past(load) && !$past(rst)) |-> (Q == (($past(A) + $past(B)) [WIDTH-1:0]))
    );

    // LSB correctness after load: carry-in to bit 0 is 0, so Q[0] = A[0] ^ B[0].
    check_lsb_after_load: assert property (
        @(posedge clk) disable iff (rst)
            ($past(1'b1) && $past(load) && !$past(rst)) |-> (Q[0] == ($past(A[0]) ^ $past(B[0])))
    );

    // If load stays low for two consecutive cycles (no reset), Q remains constant across them.
    check_two_cycle_hold_no_load: assert property (
        @(posedge clk) disable iff (rst)
            ($past(1'b1) && !$past(load) && !load && !$past(rst)) |-> (Q == $past(Q))
    );

endmodule

module up_down_counter_sva (
    input  logic [3:0] LOAD,
    input  logic       UP_DOWN,
    input  logic       CLK,
    input  logic       RESET,
    input  logic [3:0] COUNT
);
    ///// Reset behavior /////
    // While RESET is asserted, COUNT must be 0.
    check_reset_clears_count: assert property (
        @(posedge CLK) RESET |-> (COUNT == 4'd0)
    );

    ///// Load behavior /////
    // On non-zero LOAD, COUNT is updated to LOAD on the next clock.
    check_load_updates_count: assert property (
        @(posedge CLK) disable iff (RESET)
            (LOAD != 4'd0) |=> (RESET || (COUNT == $past(LOAD)))
    );

    ///// Counting behavior /////
    // With LOAD == 0 and UP_DOWN == 1, COUNT increments by 1 on the next clock.
    check_increment_when_up: assert property (
        @(posedge CLK) disable iff (RESET)
            (LOAD == 4'd0 && (UP_DOWN == 1'b1)) |=> (RESET || (COUNT == ($past(COUNT) + 4'd1)))
    );

    // With LOAD == 0 and UP_DOWN == 0, COUNT decrements by 1 on the next clock.
    check_decrement_when_down: assert property (
        @(posedge CLK) disable iff (RESET)
            (LOAD == 4'd0 && (UP_DOWN == 1'b0)) |=> (RESET || (COUNT == ($past(COUNT) - 4'd1)))
    );

    ///// Wrap-around checks /////
    // Incrementing from 4'hF wraps to 4'h0 when LOAD == 0 and UP_DOWN == 1.
    check_wrap_on_increment: assert property (
        @(posedge CLK) disable iff (RESET)
            (LOAD == 4'd0 && (UP_DOWN == 1'b1) && ($past(COUNT) == 4'hF)) |=> (RESET || (COUNT == 4'h0))
    );

    // Decrementing from 4'h0 wraps to 4'hF when LOAD == 0 and UP_DOWN == 0.
    check_wrap_on_decrement: assert property (
        @(posedge CLK) disable iff (RESET)
            (LOAD == 4'd0 && (UP_DOWN == 1'b0) && ($past(COUNT) == 4'h0)) |=> (RESET || (COUNT == 4'hF))
    );
endmodule

rtl:
module mux4to1(
    input [3:0] data_in,
    input [1:0] sel,
    output reg data_out
);
    always @ (sel or data_in) begin
        case (sel)
            2'b00: data_out <= data_in[0];
            2'b01: data_out <= data_in[1];
            2'b10: data_out <= data_in[2];
            2'b11: data_out <= data_in[3];
        endcase
    end
endmodule

sva:
module mux4to1_sva (
    input logic clk,            // sampling clock for assertions
    input logic [3:0] data_in,
    input logic [1:0] sel,
    input logic data_out
);
    ///// Functional mapping /////
    // When sel is 2-state, output equals the selected input bit.
    check_mux_function_general: assert property (
        @(posedge clk) (sel inside {2'b00,2'b01,2'b10,2'b11}) |-> (data_out === data_in[sel])
    );

    // sel==00 routes data_in[0] to data_out.
    check_sel_00_route: assert property (
        @(posedge clk) (sel === 2'b00) |-> (data_out === data_in[0])
    );
    // sel==01 routes data_in[1] to data_out.
    check_sel_01_route: assert property (
        @(posedge clk) (sel === 2'b01) |-> (data_out === data_in[1])
    );
    // sel==10 routes data_in[2] to data_out.
    check_sel_10_route: assert property (
        @(posedge clk) (sel === 2'b10) |-> (data_out === data_in[2])
    );
    // sel==11 routes data_in[3] to data_out.
    check_sel_11_route: assert property (
        @(posedge clk) (sel === 2'b11) |-> (data_out === data_in[3])
    );

    ///// Change-causality /////
    // Output only changes if sel or some data_in bit changed.
    check_out_change_has_cause: assert property (
        @(posedge clk) $changed(data_out) |-> ($changed(sel) || $changed(data_in))
    );

    ///// Ignore unselected inputs /////
    // With sel==00 stable, changes on data_in[3:1] do not change data_out.
    check_ignore_unselected_00: assert property (
        @(posedge clk) (sel === 2'b00) && !$changed(sel) && !$changed(data_in[0]) && $changed(data_in[3:1]) |-> !$changed(data_out)
    );
    // With sel==01 stable, changes on data_in[3:2] or data_in[0] do not change data_out.
    check_ignore_unselected_01: assert property (
        @(posedge clk) (sel === 2'b01) && !$changed(sel) && !$changed(data_in[1]) && $changed({data_in[3:2],data_in[0]}) |-> !$changed(data_out)
    );
    // With sel==10 stable, changes on data_in[3] or data_in[1:0] do not change data_out.
    check_ignore_unselected_10: assert property (
        @(posedge clk) (sel === 2'b10) && !$changed(sel) && !$changed(data_in[2]) && $changed({data_in[3],data_in[1:0]}) |-> !$changed(data_out)
    );
    // With sel==11 stable, changes on data_in[2:0] do not change data_out.
    check_ignore_unselected_11: assert property (
        @(posedge clk) (sel === 2'b11) && !$changed(sel) && !$changed(data_in[3]) && $changed(data_in[2:0]) |-> !$changed(data_out)
    );

    ///// Selected input drives output /////
    // With sel==00 stable, a change on data_in[0] causes data_out to change.
    check_selected_change_affects_out_00: assert property (
        @(posedge clk) (sel === 2'b00) && !$changed(sel) && $changed(data_in[0]) |-> $changed(data_out)
    );
    // With sel==01 stable, a change on data_in[1] causes data_out to change.
    check_selected_change_affects_out_01: assert property (
        @(posedge clk) (sel === 2'b01) && !$changed(sel) && $changed(data_in[1]) |-> $changed(data_out)
    );
    // With sel==10 stable, a change on data_in[2] causes data_out to change.
    check_selected_change_affects_out_10: assert property (
        @(posedge clk) (sel === 2'b10) && !$changed(sel) && $changed(data_in[2]) |-> $changed(data_out)
    );
    // With sel==11 stable, a change on data_in[3] causes data_out to change.
    check_selected_change_affects_out_11: assert property (
        @(posedge clk) (sel === 2'b11) && !$changed(sel) && $changed(data_in[3]) |-> $changed(data_out)
    );
endmodule

rtl:
module two_bit_comparator (
    input [1:0] A,
    input [1:0] B,
    output Y
);

    assign Y = (A > B) ? 1'b1 : 1'b0;

endmodule

sva:
module two_bit_comparator_sva (
    input logic CLK,
    input logic [1:0] A,
    input logic [1:0] B,
    input logic Y
);
    // Y must be 1 when A > B.
    check_y_high_when_a_gt_b: assert property (
        @(posedge CLK) (A > B) |-> (Y == 1'b1)
    );

    // Y must be 0 when A <= B.
    check_y_low_when_a_le_b: assert property (
        @(posedge CLK) (A <= B) |-> (Y == 1'b0)
    );

    // If Y is 1 then A must be greater than B.
    check_y1_implies_a_gt_b: assert property (
        @(posedge CLK) (Y == 1'b1) |-> (A > B)
    );

    // If MSBs differ and A[1]=1,B[1]=0 then Y must be 1.
    check_msb_diff_a1_b0: assert property (
        @(posedge CLK) (A[1] && !B[1]) |-> (Y == 1'b1)
    );

    // If MSBs differ and A[1]=0,B[1]=1 then Y must be 0.
    check_msb_diff_a0_b1: assert property (
        @(posedge CLK) (!A[1] && B[1]) |-> (Y == 1'b0)
    );

    // If MSBs equal, comparison reduces to LSB: Y == (A[0] & ~B[0]).
    check_msb_equal_lsb_decides: assert property (
        @(posedge CLK) (A[1] == B[1]) |-> (Y == (A[0] & ~B[0]))
    );

    // If A equals B then Y must be 0.
    check_equal_inputs_y0: assert property (
        @(posedge CLK) (A == B) |-> (Y == 1'b0)
    );

    // If A is 0 then Y must be 0.
    check_a_zero_y0: assert property (
        @(posedge CLK) (A == 2'b00) |-> (Y == 1'b0)
    );

    // If B is 3 then Y must be 0.
    check_b_three_y0: assert property (
        @(posedge CLK) (B == 2'b11) |-> (Y == 1'b0)
    );

    // If A is 3 and B is not 3 then Y must be 1.
    check_a_three_gt_non_three: assert property (
        @(posedge CLK) (A == 2'b11 && B != 2'b11) |-> (Y == 1'b1)
    );
endmodule

module updown_counter_sva (
    input logic clk,
    input logic reset,      // active-low asynchronous reset
    input logic control,    // 0: up, 1: down
    input logic [2:0] count // 3-bit counter
);
    // Reset low forces count to zero at each clock.
    reset_low_clears_count: assert property (
        @(posedge clk) (reset == 1'b0) |-> (count == 3'd0)
    );

    // Out of reset, next count matches prev control: +1 when 0, -1 when 1.
    count_update_matches_prev_control: assert property (
        @(posedge clk) disable iff (reset == 1'b0)
            $past(reset) |-> (count == ($past(control) ? ($past(count) - 3'd1) : ($past(count) + 3'd1)))
    );

    // Up-count wraps from 7 to 0 when previous control was 0.
    wrap_up_on_7_to_0: assert property (
        @(posedge clk) disable iff (reset == 1'b0)
            ($past(reset) && ($past(control) == 1'b0) && ($past(count) == 3'd7)) |-> (count == 3'd0)
    );

    // Down-count wraps from 0 to 7 when previous control was 1.
    wrap_down_on_0_to_7: assert property (
        @(posedge clk) disable iff (reset == 1'b0)
            ($past(reset) && ($past(control) == 1'b1) && ($past(count) == 3'd0)) |-> (count == 3'd7)
    );

    // Up-count increments by exactly one when not wrapping.
    increment_no_wrap: assert property (
        @(posedge clk) disable iff (reset == 1'b0)
            ($past(reset) && ($past(control) == 1'b0) && ($past(count) != 3'd7)) |-> (count == $past(count) + 3'd1)
    );

    // Down-count decrements by exactly one when not wrapping.
    decrement_no_wrap: assert property (
        @(posedge clk) disable iff (reset == 1'b0)
            ($past(reset) && ($past(control) == 1'b1) && ($past(count) != 3'd0)) |-> (count == $past(count) - 3'd1)
    );

    // While reset remains asserted across cycles, count stays at zero.
    hold_zero_during_reset: assert property (
        @(posedge clk) (!$past(reset) && !reset) |-> (count == 3'd0)
    );
endmodule

rtl:
module nor4 (
    // input and output ports
    output Y,
    input A,
    input B,
    input C,
    input D
);

    // supplies
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB;
    supply0 VNB;

    // local signals
    wire nor1_out_Y;
    wire nor2_out_Y;
    wire nor3_out_Y;
    wire nor4_out_Y;

    // NOR gates
    nor nor1 (nor1_out_Y, A, B);
    nor nor2 (nor2_out_Y, C, D);
    nor nor3 (nor3_out_Y, nor1_out_Y, nor2_out_Y);
    nor nor4 (Y, nor3_out_Y);

endmodule

sva:
module nor4_sva (
    input logic clk,
    input logic Y,
    input logic A,
    input logic B,
    input logic C,
    input logic D
);
    // Y must equal (~A & ~B) | (~C & ~D).
    check_function_equivalence: assert property (
        @(posedge clk) Y == ((~(A | B)) | (~(C | D)))
    );

    // If A and B are both 0, Y must be 1.
    check_y_high_when_ab00: assert property (
        @(posedge clk) (A == 1'b0) && (B == 1'b0) |-> (Y == 1'b1)
    );

    // If C and D are both 0, Y must be 1.
    check_y_high_when_cd00: assert property (
        @(posedge clk) (C == 1'b0) && (D == 1'b0) |-> (Y == 1'b1)
    );

    // If each pair has at least one '1', Y must be 0.
    check_y_low_when_each_pair_has_one: assert property (
        @(posedge clk) ((A | B) && (C | D)) |-> (Y == 1'b0)
    );

    // If A and B are both 1, Y equals (~C & ~D).
    check_y_equals_notC_and_notD_when_ab11: assert property (
        @(posedge clk) (A == 1'b1) && (B == 1'b1) |-> (Y == ((~C) & (~D)))
    );

    // If Y is 1, at least one pair (A,B) or (C, D) is 00.
    check_y1_implies_some_pair_zero: assert property (
        @(posedge clk) (Y == 1'b1) |-> ((~A & ~B) || (~C & ~D))
    );

    // Rising A with others stable cannot cause Y to rise.
    monotone_no_y_rise_on_A_rise: assert property (
        @(posedge clk) $rose(A) && $stable(B) && $stable(C) && $stable(D) |-> !$rose(Y)
    );

    // Rising C with others stable cannot cause Y to rise.
    monotone_no_y_rise_on_C_rise: assert property (
        @(posedge clk) $rose(C) && $stable(A) && $stable(B) && $stable(D) |-> !$rose(Y)
    );

    // Falling A with B=0 and others stable forces Y=1.
    force_y1_on_A_fall_with_B0: assert property (
        @(posedge clk) $fell(A) && (B == 1'b0) && $stable(B) && $stable(C) && $stable(D) |-> (Y == 1'b1)
    );

    // Falling C with D=0 and others stable forces Y=1.
    force_y1_on_C_fall_with_D0: assert property (
        @(posedge clk) $fell(C) && (D == 1'b0) && $stable(A) && $stable(B) && $stable(D) |-> (Y == 1'b1)
    );
endmodule

rtl:
module register (
    input clk,
    input rst,
    input [7:0] data_in,
    input enable,
    output reg [7:0] data_out
);

reg [7:0] stored_data;

always @(posedge clk) begin
    if (rst) begin
        stored_data <= 8'h00;
    end else if (enable) begin
        stored_data <= data_in;
    end
end

always @*
    data_out = stored_data;

endmodule

sva:
module register_sva (
    input logic clk,
    input logic rst,
    input logic [7:0] data_in,
    input logic enable,
    input logic [7:0] data_out
);
    // Clock: clk; Reset: rst (active-high, synchronous)
    // Behavior: sequential register with enable; data_out mirrors stored_data combinationally

    // On reset, output becomes 0 on the next cycle.
    reset_clears_output: assert property (
        @(posedge clk) rst |=> (data_out == 8'h00)
    );

    // With enable HIGH (and not in reset), next cycle output equals previous data_in.
    write_updates_output: assert property (
        @(posedge clk) disable iff (rst) enable |=> (data_out == $past(data_in))
    );

    // With enable LOW (and not in reset), next cycle output holds its value.
    hold_when_enable_low: assert property (
        @(posedge clk) disable iff (rst) !enable |=> (data_out == $past(data_out))
    );

    // Output changes only if there was an enable or reset in the prior cycle.
    change_requires_write_or_reset: assert property (
        @(posedge clk) disable iff (rst) $changed(data_out) |-> ($past(enable) || $past(rst))
    );

    // Two back-to-back enables: at the second-next cycle, output equals data_in from the prior cycle.
    two_writes_in_sequence: assert property (
        @(posedge clk) disable iff (rst) (enable ##1 enable) |=> (data_out == $past(data_in, 1))
    );

    // Two cycles with enable LOW: output equals the value from two cycles earlier.
    hold_two_cycles_no_enable: assert property (
        @(posedge clk) disable iff (rst) (!enable ##1 !enable) |=> (data_out == $past(data_out, 2))
    );

    // If data_in changes while enable is LOW, output still holds on the next cycle.
    hold_despite_input_change: assert property (
        @(posedge clk) disable iff (rst) (!enable && $changed(data_in)) |=> (data_out == $past(data_out))
    );

    // After reset deasserts and no write that cycle, output remains 0 on the next cycle.
    deassert_reset_no_write_keeps_zero: assert property (
        @(posedge clk) ($fell(rst) && !enable) |=> (data_out == 8'h00)
    );

    // After a write, the written value holds until the next write (reset aborts the check).
    hold_after_write_until_next_write: assert property (
        @(posedge clk) disable iff (rst) enable |=> (data_out == $past(data_in)) until_with (enable)
    );

    // Reset dominates enable: if both are HIGH, next cycle output is 0.
    reset_overrides_enable: assert property (
        @(posedge clk) (rst && enable) |=> (data_out == 8'h00)
    );
endmodule

rtl:
module parity_generator (
    input [7:0] in,
    output parity);

    assign parity = ((^in) & 1'b1);

endmodule

sva:
module parity_generator_sva (
    input logic CLK,
    input logic [7:0] in,
    input logic parity
);
    // Parity equals XOR reduction of in masked by 1.
    check_parity_definition: assert property (
        @(posedge CLK) parity == ((^in) & 1'b1)
    );

    // If input is stable, parity must remain stable.
    check_stability_when_input_stable: assert property (
        @(posedge CLK) $stable(in) |-> $stable(parity)
    );

    // Change in parity equals parity of the input delta.
    check_parity_delta_matches_input_delta: assert property (
        @(posedge CLK) (parity ^ $past(parity)) == ((^(in ^ $past(in))) & 1'b1)
    );

    // A single-bit flip in input must toggle parity.
    check_parity_toggles_on_onebit_flip: assert property (
        @(posedge CLK) $onehot(in ^ $past(in)) |-> (parity != $past(parity))
    );
endmodule

rtl:
module sky130_fd_sc_lp__ha (
    COUT,
    SUM ,
    A   ,
    B
);

    output COUT;
    output SUM ;
    input  A   ;
    input  B   ;

    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    wire and0_out_COUT;
    wire xor0_out_SUM ;

    and and0 (and0_out_COUT, A, B           );
    buf buf0 (COUT         , and0_out_COUT  );
    xor xor0 (xor0_out_SUM , B, A           );
    buf buf1 (SUM          , xor0_out_SUM   );

endmodule

sva:
module sky130_fd_sc_lp__ha_sva (
    input logic COUT,
    input logic SUM,
    input logic A,
    input logic B
);
    // COUT equals logical AND of A and B.
    check_cout_definition: assert property (
        @(posedge $global_clock) COUT == (A & B)
    );

    // SUM equals logical XOR of A and B.
    check_sum_definition: assert property (
        @(posedge $global_clock) SUM == (A ^ B)
    );

    // When A=0 and B=0 then SUM=0 and COUT=0.
    check_tt_00: assert property (
        @(posedge $global_clock) (A==1'b0 && B==1'b0) |-> (SUM==1'b0 && COUT==1'b0)
    );

    // When A=0 and B=1 then SUM=1 and COUT=0.
    check_tt_01: assert property (
        @(posedge $global_clock) (A==1'b0 && B==1'b1) |-> (SUM==1'b1 && COUT==1'b0)
    );

    // When A=1 and B=0 then SUM=1 and COUT=0.
    check_tt_10: assert property (
        @(posedge $global_clock) (A==1'b1 && B==1'b0) |-> (SUM==1'b1 && COUT==1'b0)
    );

    // When A=1 and B=1 then SUM=0 and COUT=1.
    check_tt_11: assert property (
        @(posedge $global_clock) (A==1'b1 && B==1'b1) |-> (SUM==1'b0 && COUT==1'b1)
    );

    // SUM and COUT are never both HIGH.
    check_outputs_not_both_high: assert property (
        @(posedge $global_clock) !(SUM && COUT)
    );

    // SUM=1 implies inputs differ.
    check_sum_high_inputs_differ: assert property (
        @(posedge $global_clock) SUM |-> (A != B)
    );

    // COUT=1 implies both inputs are 1.
    check_cout_high_inputs_one: assert property (
        @(posedge $global_clock) COUT |-> (A && B)
    );

    // Inputs equal implies SUM=0.
    check_inputs_equal_sum_low: assert property (
        @(posedge $global_clock) (A == B) |-> (SUM == 1'b0)
    );
endmodule

