module decade_counter (
    input clk,
    input slowena,
    input reset,
    output reg [3:0] q);

    // Define states
    parameter IDLE = 2'b00;
    parameter COUNT = 2'b01;
    parameter PAUSE = 2'b10;

    // Define state register and next state logic
    reg [1:0] state, next_state;
    always @ (posedge clk) begin
        if (reset) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    // Define output logic
    always @ (state) begin
        case (state)
            IDLE: q <= 4'b0000;
            COUNT: q <= q + 1;
            PAUSE: q <= q;
        endcase
    end

    // Define next state logic
    always @ (state, slowena) begin
        case (state)
            IDLE: if (!slowena) begin
                     next_state = COUNT;
                  end else begin
                     next_state = IDLE;
                  end
            COUNT: if (q == 4'b1001) begin
                      next_state = IDLE;
                   end else if (slowena) begin
                      next_state = PAUSE;
                   end else begin
                      next_state = COUNT;
                   end
            PAUSE: if (!slowena) begin
                      next_state = COUNT;
                   end else begin
                      next_state = PAUSE;
                   end
        endcase
    end

endmodule

module top_module (
    input clk,
    input slowena,
    input reset,
    output [3:0] q);

    // Instantiate the decade counter module
    decade_counter dc (
        .clk(clk),
        .slowena(slowena),
        .reset(reset),
        .q(q)
    );

endmodule

sva:
module decade_counter_sva (
    input logic clk,
    input logic slowena,
    input logic reset,
    input logic [3:0] q
);
    // Clock: clk. Reset: reset (active-high, synchronous). Mixed: seq state, comb q updates.

    // After reset is asserted, q must be 0 on the next clock.
    reset_clears_q_next: assert property (
        @(posedge clk) reset |=> (q == 4'd0)
    );

    // While reset stays asserted across cycles, q must be 0.
    hold_zero_while_reset: assert property (
        @(posedge clk) (reset && $past(reset)) |-> (q == 4'd0)
    );

    // Any change of q must either set it to 0 or increment by 1 (mod 16).
    q_change_is_zero_or_plus1: assert property (
        @(posedge clk) disable iff (reset) $changed(q) |-> ((q == 4'd0) || (q == ($past(q) + 4'd1)))
    );

    // If q increments by 1 this cycle, slowena had to be LOW in the prior cycle.
    increment_implies_prev_slowena_low: assert property (
        @(posedge clk) disable iff (reset) (q == ($past(q) + 4'd1)) |-> ($past(slowena) == 1'b0)
    );

    // q cannot increment by 1 in two consecutive cycles.
    no_back_to_back_increments: assert property (
        @(posedge clk) disable iff (reset) (q == ($past(q) + 4'd1)) |-> ##1 !(q == ($past(q) + 4'd1))
    );

    // If slowena is HIGH this cycle, q must not increment on the next cycle.
    no_increment_when_slowena_high: assert property (
        @(posedge clk) disable iff (reset) slowena |-> ##1 !(q == ($past(q) + 4'd1))
    );

    // If slowena is HIGH for two consecutive cycles, q is stable in the next cycle.
    slowena_high_two_cycles_stabilizes_q: assert property (
        @(posedge clk) disable iff (reset) (slowena && $past(slowena)) |-> ##1 (q == $past(q))
    );

    // A transition from 0 to non-zero must be to 1.
    zero_to_nonzero_becomes_one: assert property (
        @(posedge clk) disable iff (reset) ($past(q) == 4'd0 && q != 4'd0) |-> (q == 4'd1)
    );

    // A falling edge on slowena causes q to increment on the next cycle.
    slowena_fall_causes_increment_next: assert property (
        @(posedge clk) disable iff (reset) ($past(slowena) && !slowena) |-> ##1 (q == ($past(q) + 4'd1))
    );

    // After reset deasserts and slowena is HIGH, q holds its value into the next cycle.
    post_reset_deassert_with_slowena_high_holds_q: assert property (
        @(posedge clk) disable iff (reset) ($past(reset) && !reset && slowena) |-> ##1 (q == $past(q))
    );

endmodule

module accumulator_sva (
    input logic clk,
    input logic reset,          // active-high synchronous reset
    input logic [7:0] in,
    input logic [15:0] out
);
    // On a non-reset cycle, next out equals current out plus in (16-bit wraparound).
    check_add_update: assert property (
        @(posedge clk) disable iff (reset) 1'b1 |=> out == $past(out) + $past(in)
    );

    // If in is zero and not in reset, out holds its value next cycle.
    check_hold_when_in_zero: assert property (
        @(posedge clk) disable iff (reset) (in == 8'd0) |=> out == $past(out)
    );

    // If in is 1 and not in reset, out increments by 1 next cycle.
    check_increment_by_one: assert property (
        @(posedge clk) disable iff (reset) (in == 8'd1) |=> out == $past(out) + 16'd1
    );

    // If in is 255 and not in reset, out increments by 255 next cycle.
    check_increment_by_255: assert property (
        @(posedge clk) disable iff (reset) (in == 8'hFF) |=> out == $past(out) + 16'd255
    );

    // After a reset cycle, out is zero on the following cycle.
    check_zero_after_reset_cycle: assert property (
        @(posedge clk) disable iff (reset) $past(reset) |-> (out == 16'd0)
    );

    // If two consecutive cycles are not in reset, out equals out from two cycles ago plus the last two inputs.
    check_two_cycle_accumulation: assert property (
        @(posedge clk) disable iff (reset) (!reset && !$past(reset)) |-> (out == $past(out,2) + $past(in,2) + $past(in,1))
    );

    // When not in reset now and previously, the step difference equals previous input.
    check_step_diff_matches_prev_in: assert property (
        @(posedge clk) disable iff (reset) !$past(reset) |-> (out - $past(out)) == $past(in)
    );

    // On reset deassertion (falling edge), out is zero in that cycle.
    check_out_zero_on_reset_fall: assert property (
        @(posedge clk) disable iff (reset) $fell(reset) |-> (out == 16'd0)
    );
endmodule

module calculator_sva (
    input logic clk,
    input logic [7:0] a_in,
    input logic [7:0] b_in,
    input logic [1:0] op,
    input logic [7:0] c_out
);
    // When op==00, output is 8-bit sum of a_in and b_in.
    check_add_result: assert property (
        @(posedge clk) (op == 2'b00) |-> (c_out == (a_in + b_in))
    );

    // When op==01, output is 8-bit difference a_in - b_in.
    check_sub_result: assert property (
        @(posedge clk) (op == 2'b01) |-> (c_out == (a_in - b_in))
    );

    // When op==10, output is low 8 bits of the product.
    check_mul_result_truncate8: assert property (
        @(posedge clk) (op == 2'b10) |-> (c_out == (a_in * b_in)[7:0])
    );

    // When op==11 and divisor is nonzero, output is a_in / b_in.
    check_div_result_nonzero: assert property (
        @(posedge clk) (op == 2'b11 && (b_in != 8'd0)) |-> (c_out == (a_in / b_in))
    );

    // If op contains any X/Z, default branch forces c_out to zero.
    check_default_on_unknown_op: assert property (
        @(posedge clk) $isunknown(op) |-> (c_out == 8'h00)
    );

    // If inputs are stable, output remains stable (pure combinational behavior).
    check_output_stable_when_inputs_stable: assert property (
        @(posedge clk) ($stable(a_in) && $stable(b_in) && $stable(op)) |-> $stable(c_out)
    );

    // Addition passthrough: when op==00 and b_in==0, c_out equals a_in.
    check_add_zero_b_passthru: assert property (
        @(posedge clk) (op == 2'b00 && (b_in == 8'd0)) |-> (c_out == a_in)
    );

    // Subtraction cancels equal operands: when op==01 and a_in==b_in, c_out==0.
    check_sub_equal_zero: assert property (
        @(posedge clk) (op == 2'b01 && (a_in == b_in)) |-> (c_out == 8'h00)
    );

    // Multiplication by zero yields zero when op==10.
    check_mul_zero_operand: assert property (
        @(posedge clk) (op == 2'b10 && ((a_in == 8'd0) || (b_in == 8'd0))) |-> (c_out == 8'h00)
    );

    // Division by one passes a_in through when op==11.
    check_div_by_one_passthru: assert property (
        @(posedge clk) (op == 2'b11 && (b_in == 8'd1)) |-> (c_out == a_in)
    );
endmodule

