sva:
module bin_to_two_bit_sva (
    input logic CLK,
    input logic [3:0] in,
    input logic [1:0] out
);
    // out[0] equals in[1] OR in[3].
    check_out0_mapping: assert property (
        @(posedge CLK) disable iff (1'b0) out[0] == (in[1] | in[3])
    );

    // out[1] equals in[2] OR in[3].
    check_out1_mapping: assert property (
        @(posedge CLK) disable iff (1'b0) out[1] == (in[2] | in[3])
    );

    // out equals {in[2]|in[3], in[1]|in[3]}.
    check_out_vector_mapping: assert property (
        @(posedge CLK) disable iff (1'b0) out == { (in[2] | in[3]), (in[1] | in[3]) }
    );

    // If in[3] is 1, out must be 2'b11.
    check_in3_forces_all_ones: assert property (
        @(posedge CLK) disable iff (1'b0) in[3] |-> (out == 2'b11)
    );

    // If in[3] is 0, out passes through in[2:1] to {out[1],out[0]}.
    check_in3_zero_pass_through: assert property (
        @(posedge CLK) disable iff (1'b0) !in[3] |-> ((out[0] == in[1]) && (out[1] == in[2]))
    );

    // If in[1]==0 and in[3]==0 then out[0]==0.
    check_out0_zero_conditions: assert property (
        @(posedge CLK) disable iff (1'b0) (!in[1] && !in[3]) |-> (out[0] == 1'b0)
    );

    // If in[2]==0 and in[3]==0 then out[1]==0.
    check_out1_zero_conditions: assert property (
        @(posedge CLK) disable iff (1'b0) (!in[2] && !in[3]) |-> (out[1] == 1'b0)
    );

    // All-zero input produces all-zero output.
    check_zero_input_zero_output: assert property (
        @(posedge CLK) disable iff (1'b0) (in == 4'b0000) |-> (out == 2'b00)
    );

    // With in[3]==0, in[1]==1 sets out[0].
    check_out0_set_by_in1_when_in3_zero: assert property (
        @(posedge CLK) disable iff (1'b0) (in[1] && !in[3]) |-> (out[0] == 1'b1)
    );

    // With in[3]==0, in[2]==1 sets out[1].
    check_out1_set_by_in2_when_in3_zero: assert property (
        @(posedge CLK) disable iff (1'b0) (in[2] && !in[3]) |-> (out[1] == 1'b1)
    );
endmodule

rtl:
module full_adder_4bit #(parameter DW = 4 // data width
                         )
  ( input [DW-1:0]  A, //input A
    input [DW-1:0]  B, //input B
    input [DW-1:0]  C_in, //input C_in
    output [DW-1:0] S, //sum output
    output [DW-1:0] C_out //carry output
  );

  `ifdef CFG_ASIC
    genvar i;
    for (i = 0; i < DW; i = i + 1) begin
      asic_csa32 asic_csa32 (.s(S[i]), .c(C_out[i]), .in2(C_in[i]), .in1(B[i]), .in0(A[i]));
    end
  `else
    assign S[DW-1:0] = A[DW-1:0] ^ B[DW-1:0] ^ C_in[DW-1:0];
    assign C_out[DW-1:0] = (A[DW-1:0] & B[DW-1:0]) | (B[DW-1:0] & C_in[DW-1:0]) | (C_in[DW-1:0] & A[DW-1:0]);
  `endif // !`ifdef CFG_ASIC

endmodule

sva:
module full_adder_4bit_sva #(
    parameter int DW = 4
) (
    input  logic                 CLK,
    input  logic                 RESETn,
    input  logic [DW-1:0]        A,
    input  logic [DW-1:0]        B,
    input  logic [DW-1:0]        C_in,
    input  logic [DW-1:0]        S,
    input  logic [DW-1:0]        C_out
);
    ///// Functional equivalence (vector) /////
    // Sum output equals bitwise XOR of inputs.
    check_sum_is_xor: assert property (
        @(posedge CLK) disable iff (!RESETn) S == (A ^ B ^ C_in)
    );
    // Carry output equals bitwise majority of inputs.
    check_carry_is_majority: assert property (
        @(posedge CLK) disable iff (!RESETn) C_out == ((A & B) | (B & C_in) | (C_in & A))
    );

    ///// Combinational sanity /////
    // If inputs are stable cycle-to-cycle, outputs are stable too.
    combinational_stability: assert property (
        @(posedge CLK) disable iff (!RESETn) ($stable(A) && $stable(B) && $stable(C_in)) |=> ($stable(S) && $stable(C_out))
    );
    // All-zero inputs produce all-zero outputs.
    vector_zero_identity: assert property (
        @(posedge CLK) disable iff (!RESETn) ((A == '0) && (B == '0) && (C_in == '0)) |=> ((S == '0) && (C_out == '0))
    );
    // If all three input vectors are equal, S is zero and C_out equals that vector.
    vector_equal_inputs: assert property (
        @(posedge CLK) disable iff (!RESETn) ((A == B) && (B == C_in)) |=> ((S == '0) && (C_out == A))
    );

    ///// Bit-level properties /////
    genvar i;
    generate
        for (i = 0; i < DW; i++) begin : gen_bit_checks
            // With C_in=1, S is XNOR(A,B) and C_out is OR(A,B).
            cin1_behavior: assert property (
                @(posedge CLK) disable iff (!RESETn) (C_in[i] == 1'b1) |=> ((S[i] == ~(A[i] ^ B[i])) && (C_out[i] == (A[i] | B[i])))
            );
            // With C_in=0, S is XOR(A,B) and C_out is AND(A,B).
            cin0_behavior: assert property (
                @(posedge CLK) disable iff (!RESETn) (C_in[i] == 1'b0) |=> ((S[i] == (A[i] ^ B[i])) && (C_out[i] == (A[i] & B[i])))
            );
            // Per bit, arithmetic balance: A+B+C_in equals S + 2*C_out.
            check_weighted_sum: assert property (
                @(posedge CLK) disable iff (!RESETn) (A[i] + B[i] + C_in[i]) == (S[i] + (C_out[i] << 1))
            );
            // If exactly one input is 1, then S=1 and C_out=0.
            one_of_three: assert property (
                @(posedge CLK) disable iff (!RESETn) ((A[i] + B[i] + C_in[i]) == 2'd1) |=> ((S[i] == 1'b1) && (C_out[i] == 1'b0))
            );
            // If exactly two inputs are 1, then S=0 and C_out=1.
            two_of_three: assert property (
                @(posedge CLK) disable iff (!RESETn) ((A[i] + B[i] + C_in[i]) == 2'd2) |=> ((S[i] == 1'b0) && (C_out[i] == 1'b1))
            );
            // If all three inputs are 1, then S=1 and C_out=1.
            three_of_three: assert property (
                @(posedge CLK) disable iff (!RESETn) ((A[i] & B[i] & C_in[i]) == 1'b1) |=> ((S[i] == 1'b1) && (C_out[i] == 1'b1))
            );
            // If all three inputs are 0, then S=0 and C_out=0.
            zero_of_three: assert property (
                @(posedge CLK) disable iff (!RESETn) ((A[i] | B[i] | C_in[i]) == 1'b0) |=> ((S[i] == 1'b0) && (C_out[i] == 1'b0))
            );
        end
    endgenerate
endmodule

rtl:
module top_module (
    input clk,
    input reset,
    input [7:0] in,
    input [31:0] in2,
    output final_output
);

    // Parity bit generation module
    wire [7:0] in_xor;
    assign in_xor = ^in;
    wire parity_bit;
    assign parity_bit = in_xor[0] ^ in_xor[1] ^ in_xor[2] ^ in_xor[3] ^ in_xor[4] ^ in_xor[5] ^ in_xor[6] ^ in_xor[7];

    // Falling edge detection module
    reg [31:0] counter;
    wire falling_edge;
    assign falling_edge = (counter == 32'h7FFFFFFF);
    always @(posedge clk) begin
        if (reset) begin
            counter <= 0;
        end else begin
            counter <= counter + 1;
        end
    end

    // XOR module
    wire xor_output;
    assign xor_output = parity_bit ^ falling_edge;

    // Final output
    assign final_output = xor_output;

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic reset,
    input logic [7:0] in,
    input logic [31:0] in2,
    input logic final_output
);
    // Mirror of RTL combinational parity path
    logic [7:0] in_xor_m;
    assign in_xor_m = ^in;
    logic parity_bit_m;
    assign parity_bit_m = in_xor_m[0] ^ in_xor_m[1] ^ in_xor_m[2] ^ in_xor_m[3] ^ in_xor_m[4] ^ in_xor_m[5] ^ in_xor_m[6] ^ in_xor_m[7];

    // Mirror of RTL counter and falling_edge logic
    logic [31:0] counter_m;
    always_ff @(posedge clk) begin
        if (reset) begin
            counter_m <= 32'd0;
        end else begin
            counter_m <= counter_m + 32'd1;
        end
    end
    logic falling_edge_m;
    assign falling_edge_m = (counter_m == 32'h7FFFFFFF);

    // Expected final output per RTL wiring
    logic expected_final_m;
    assign expected_final_m = parity_bit_m ^ falling_edge_m;

    ///// Assertions /////
    // final_output equals parity_bit ^ falling_edge (functional equivalence).
    check_final_output_function: assert property (
        @(posedge clk) disable iff (reset) final_output == expected_final_m
    );

    // When counter != 0x7FFFFFFF, final_output equals parity_bit.
    check_output_equals_parity_when_not_match: assert property (
        @(posedge clk) disable iff (reset) (counter_m != 32'h7FFFFFFF) |-> (final_output == parity_bit_m)
    );

    // When counter == 0x7FFFFFFF, final_output equals inverted parity_bit.
    check_output_equals_inverted_parity_at_match: assert property (
        @(posedge clk) disable iff (reset) (counter_m == 32'h7FFFFFFF) |-> (final_output == ~parity_bit_m)
    );

    // Output toggle equals XOR of parity toggle and falling_edge toggle.
    check_output_toggle_relation: assert property (
        @(posedge clk) disable iff (reset) ($changed(final_output)) == (($changed(parity_bit_m)) ^ ($changed(falling_edge_m)))
    );

    // Changing in2 alone (with parity and falling_edge stable) cannot change final_output.
    check_in2_irrelevant_when_others_stable: assert property (
        @(posedge clk) disable iff (reset) ($changed(in2) && $stable(parity_bit_m) && $stable(falling_edge_m)) |-> $stable(final_output)
    );

    // If neither parity nor falling_edge changes, final_output must be stable.
    check_output_stable_when_drivers_stable: assert property (
        @(posedge clk) disable iff (reset) ($stable(parity_bit_m) && $stable(falling_edge_m)) |-> $stable(final_output)
    );

    // falling_edge is high for exactly one cycle per occurrence (must deassert next cycle).
    check_falling_edge_one_cycle_pulse: assert property (
        @(posedge clk) disable iff (reset) falling_edge_m |-> ##1 !falling_edge_m
    );

    // falling_edge is zero whenever counter != 0x7FFFFFFF.
    check_falling_edge_only_when_match: assert property (
        @(posedge clk) disable iff (reset) (counter_m != 32'h7FFFFFFF) |-> (falling_edge_m == 1'b0)
    );

    // Parity monitor reduces to the simple reduction XOR of 'in'.
    check_parity_definition: assert property (
        @(posedge clk) disable iff (reset) parity_bit_m == (^in)
    );

endmodule

