sva:
module or4_module_sva (
    input logic CLK,     // Sampling clock for assertions (DUT has no clock)
    input logic A,
    input logic B,
    input logic C_N,
    input logic D_N,
    input logic X
);
    // Clocks: none in RTL; Resets: none; Logic: pure combinational X = A | B | ~C_N | ~D_N.

    // X equals the defined OR function of inputs.
    check_or_function: assert property (
        @(posedge CLK) disable iff (1'b0) X == (A | B | ~C_N | ~D_N)
    );

    // Rising A drives X HIGH in the same cycle.
    check_rose_A_sets_X_high: assert property (
        @(posedge CLK) disable iff (1'b0) $rose(A) |-> X
    );

    // Rising B drives X HIGH in the same cycle.
    check_rose_B_sets_X_high: assert property (
        @(posedge CLK) disable iff (1'b0) $rose(B) |-> X
    );

    // Falling C_N (active-low) drives X HIGH in the same cycle.
    check_fell_C_N_sets_X_high: assert property (
        @(posedge CLK) disable iff (1'b0) $fell(C_N) |-> X
    );

    // Falling D_N (active-low) drives X HIGH in the same cycle.
    check_fell_D_N_sets_X_high: assert property (
        @(posedge CLK) disable iff (1'b0) $fell(D_N) |-> X
    );

    // When all inputs are inactive (A=0,B=0,C_N=1,D_N=1), X must be LOW.
    check_all_inactive_makes_X_low: assert property (
        @(posedge CLK) disable iff (1'b0) (!A && !B && C_N && D_N) |-> !X
    );

    // If X is LOW, then all inputs must be inactive (A=0,B=0,C_N=1,D_N=1).
    check_X_low_means_all_inactive: assert property (
        @(posedge CLK) disable iff (1'b0) (!X) |-> (!A && !B && C_N && D_N)
    );

    // If X is HIGH, at least one driving condition must be true.
    check_X_high_has_some_cause: assert property (
        @(posedge CLK) disable iff (1'b0) X |-> (A || B || !C_N || !D_N)
    );

    // Output cannot change if all inputs are stable.
    check_output_stable_when_inputs_stable: assert property (
        @(posedge CLK) disable iff (1'b0) ($stable(A) && $stable(B) && $stable(C_N) && $stable(D_N)) |-> $stable(X)
    );

    // If A and B are 0, X equals (~C_N | ~D_N).
    check_AB_zero_refines_X: assert property (
        @(posedge CLK) disable iff (1'b0) (!A && !B) |-> (X == (~C_N | ~D_N))
    );
endmodule

module counter_sva (
    input logic rst,
    input logic en,
    input logic clk,
    input logic [3:0] count
);

    ///// Reset behavior /////
    // When reset is asserted LOW, count is forced to zero.
    check_reset_forces_zero: assert property (
        @(posedge clk) (rst == 1'b0) |-> (count == 4'b0000)
    );

    ///// Enable-controlled counting /////
    // When enable is LOW, hold the previous count (outside reset).
    check_hold_when_en_low: assert property (
        @(posedge clk) disable iff (!rst) (en == 1'b0) |-> (count == $past(count))
    );

    // When enable is HIGH and previous count != 15, increment by 1.
    check_increment_when_en_high_no_wrap: assert property (
        @(posedge clk) disable iff (!rst) (en == 1'b1) && ($past(count) != 4'hF) |-> (count == ($past(count) + 4'd1))
    );

    // When enable is HIGH and previous count == 15, wrap to 0.
    check_increment_when_en_high_wrap: assert property (
        @(posedge clk) disable iff (!rst) (en == 1'b1) && ($past(count) == 4'hF) |-> (count == 4'h0)
    );

    // Any change in count (outside reset) implies enable is HIGH that cycle.
    check_change_implies_en_high: assert property (
        @(posedge clk) disable iff (!rst) (count != $past(count)) |-> (en == 1'b1)
    );

    // When enable is HIGH (outside reset), count must change every cycle.
    check_must_change_when_en_high: assert property (
        @(posedge clk) disable iff (!rst) (en == 1'b1) |-> (count != $past(count))
    );

    // If enable is HIGH and count is 0 (outside reset), previous count was 15 (wrap origin).
    check_wrap_only_from_max: assert property (
        @(posedge clk) disable iff (!rst) (en == 1'b1) && (count == 4'h0) |-> ($past(count) == 4'hF)
    );

endmodule

rtl:
module full_adder (
    input A,
    input B,
    input C_IN,
    output wire S,
    output wire C_OUT
);

assign S = A ^ B ^ C_IN;
assign C_OUT = (A & B) | (B & C_IN) | (A & C_IN);

endmodule

module adder4bit (
    input [3:0] A,
    input [3:0] B,
    input C_IN,
    output [3:0] SUM,
    output wire C_OUT
);

wire [3:0] carry;

full_adder fa1(
    .A(A[0]),
    .B(B[0]),
    .C_IN(C_IN),
    .S(SUM[0]),
    .C_OUT(carry[0])
);

full_adder fa2(
    .A(A[1]),
    .B(B[1]),
    .C_IN(carry[0]),
    .S(SUM[1]),
    .C_OUT(carry[1])
);

full_adder fa3(
    .A(A[2]),
    .B(B[2]),
    .C_IN(carry[1]),
    .S(SUM[2]),
    .C_OUT(carry[2])
);

full_adder fa4(
    .A(A[3]),
    .B(B[3]),
    .C_IN(carry[2]),
    .S(SUM[3]),
    .C_OUT(C_OUT)
);

endmodule

sva:
module adder4bit_sva (
    input logic CLK,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic C_IN,
    input logic [3:0] SUM,
    input logic C_OUT
);
    // Helper carry expectations derived from ripple structure
    logic c0_exp, c1_exp, c2_exp, c3_exp;
    assign c0_exp = (A[0] & B[0]) | (B[0] & C_IN) | (A[0] & C_IN);
    assign c1_exp = (A[1] & B[1]) | (B[1] & c0_exp) | (A[1] & c0_exp);
    assign c2_exp = (A[2] & B[2]) | (B[2] & c1_exp) | (A[2] & c1_exp);
    assign c3_exp = (A[3] & B[3]) | (B[3] & c2_exp) | (A[3] & c2_exp);

    ///// Arithmetic correctness /////
    // 5-bit result must equal A + B + C_IN.
    check_total_sum_correct: assert property (
        @(posedge CLK) {C_OUT, SUM} == ({1'b0, A} + {1'b0, B} + C_IN)
    );

    ///// Bit-slice sum equations /////
    // LSB sum equals XOR of A[0], B[0], and C_IN.
    check_sum_bit0_is_fulladder_xor: assert property (
        @(posedge CLK) SUM[0] == (A[0] ^ B[0] ^ C_IN)
    );
    // SUM[1] equals XOR of A[1], B[1], and carry from bit0.
    check_sum_bit1_is_fulladder_xor: assert property (
        @(posedge CLK) SUM[1] == (A[1] ^ B[1] ^ c0_exp)
    );
    // SUM[2] equals XOR of A[2], B[2], and carry from bit1.
    check_sum_bit2_is_fulladder_xor: assert property (
        @(posedge CLK) SUM[2] == (A[2] ^ B[2] ^ c1_exp)
    );
    // SUM[3] equals XOR of A[3], B[3], and carry from bit2.
    check_sum_bit3_is_fulladder_xor: assert property (
        @(posedge CLK) SUM[3] == (A[3] ^ B[3] ^ c2_exp)
    );

    ///// Carry-out correctness /////
    // Final carry-out equals carry generated into bit3 stage.
    check_carry_out_ripple_correct: assert property (
        @(posedge CLK) C_OUT == c3_exp
    );

    ///// Basic identities and corner cases /////
    // Adding zero with no carry-in yields zero and no carry-out.
    check_zero_plus_zero_no_carry: assert property (
        @(posedge CLK) (A == 4'b0000) && (B == 4'b0000) && (C_IN == 1'b0) |-> (SUM == 4'b0000) && (C_OUT == 1'b0)
    );
    // Adding B with A=0 and no carry-in yields SUM=B and no carry-out.
    check_identity_add_zero_A: assert property (
        @(posedge CLK) (A == 4'b0000) && (C_IN == 1'b0) |-> (SUM == B) && (C_OUT == 1'b0)
    );
    // Adding A with B=0 and no carry-in yields SUM=A and no carry-out.
    check_identity_add_zero_B: assert property (
        @(posedge CLK) (B == 4'b0000) && (C_IN == 1'b0) |-> (SUM == A) && (C_OUT == 1'b0)
    );
    // 0xF + 0x0 + 1 overflows to SUM=0 and C_OUT=1.
    check_overflow_F_plus_0_plus_1: assert property (
        @(posedge CLK) (A == 4'hF) && (B == 4'h0) && (C_IN == 1'b1) |-> (SUM == 4'h0) && (C_OUT == 1'b1)
    );
endmodule

