module or3 (
    input A,
    input B,
    input C,
    output X,
    input VPWR,
    input VGND
);

    assign X = A | B | C;

endmodule

module three_input_module (
    input input_a,
    input input_b,
    input input_c,
    output output_x,
    input vpwr,
    input vgnd
);

    wire or1_output;
    wire or2_output;
    wire or3_output;

    // instantiate 3-input OR gates
    or3 or1 (
        .A(input_a),
        .B(input_b),
        .C(input_c),
        .X(or1_output),
        .VPWR(vpwr),
        .VGND(vgnd)
    );

    or3 or2 (
        .A(input_a),
        .B(input_b),
        .C(or1_output),
        .X(or2_output),
        .VPWR(vpwr),
        .VGND(vgnd)
    );

    or3 or3 (
        .A(or2_output),
        .B(input_c),
        .C(or1_output),
        .X(or3_output),
        .VPWR(vpwr),
        .VGND(vgnd)
    );

    // invert the output of the final OR gate to get the correct output
    assign output_x = ~or3_output;

endmodule

sva:
module three_input_module_sva (
    input logic CLK,
    // DUT ports
    input logic input_a,
    input logic input_b,
    input logic input_c,
    input logic output_x,
    input logic vpwr,
    input logic vgnd,
    // DUT internal nets
    input logic or1_output,
    input logic or2_output,
    input logic or3_output
);

    // or1_output equals A|B|C.
    check_or1_function: assert property (
        @(posedge CLK) (or1_output == (input_a | input_b | input_c))
    );

    // or2_output equals A|B|or1_output.
    check_or2_function: assert property (
        @(posedge CLK) (or2_output == (input_a | input_b | or1_output))
    );

    // or3_output equals or2_output|C|or1_output.
    check_or3_function: assert property (
        @(posedge CLK) (or3_output == (or2_output | input_c | or1_output))
    );

    // output_x is inversion of or3_output.
    check_output_inversion: assert property (
        @(posedge CLK) (output_x == ~or3_output)
    );

    // or2_output collapses to or1_output.
    check_or2_equals_or1: assert property (
        @(posedge CLK) (or2_output == or1_output)
    );

    // or3_output collapses to or1_output.
    check_or3_equals_or1: assert property (
        @(posedge CLK) (or3_output == or1_output)
    );

    // output_x equals NOR of inputs.
    check_output_nor_of_inputs: assert property (
        @(posedge CLK) (output_x == ~(input_a | input_b | input_c))
    );

    // When all inputs are 0, output_x must be 1.
    check_all_zero_inputs_output_high: assert property (
        @(posedge CLK) (!input_a && !input_b && !input_c) |=> (output_x == 1'b1)
    );

    // When any input is 1, output_x must be 0.
    check_any_input_high_output_low: assert property (
        @(posedge CLK) (input_a || input_b || input_c) |=> (output_x == 1'b0)
    );

    // If output_x is 1, then all inputs must be 0.
    check_output_high_implies_all_inputs_zero: assert property (
        @(posedge CLK) (output_x == 1'b1) |=> (!input_a && !input_b && !input_c)
    );

endmodule

module shift_register_sva (
    input logic CLK,
    input logic LOAD,
    input logic SHIFT,
    input logic [3:0] D,
    input logic [3:0] Q
);
    // On LOAD, next Q captures D (LOAD has priority over SHIFT).
    check_load_captures_d: assert property (
        @(posedge CLK) LOAD |=> (Q == $past(D))
    );

    // On SHIFT without LOAD, next Q is left-shifted with zero fill.
    check_shift_left_with_zero_fill: assert property (
        @(posedge CLK) (!LOAD && SHIFT) |=> (Q == { $past(Q)[2:0], 1'b0 })
    );

    // With neither LOAD nor SHIFT, Q holds its value.
    check_hold_when_idle: assert property (
        @(posedge CLK) (!LOAD && !SHIFT) |=> (Q == $past(Q))
    );

    // If both LOAD and SHIFT are asserted, LOAD wins and Q captures D.
    check_load_priority_over_shift: assert property (
        @(posedge CLK) (LOAD && SHIFT) |=> (Q == $past(D))
    );

    // On SHIFT without LOAD, LSB becomes 0 next cycle.
    check_shift_zero_fills_lsb: assert property (
        @(posedge CLK) (!LOAD && SHIFT) |=> (Q[0] == 1'b0)
    );

    // On SHIFT without LOAD, Q[3] comes from previous Q[2].
    check_shift_bit3_from_bit2: assert property (
        @(posedge CLK) (!LOAD && SHIFT) |=> (Q[3] == $past(Q[2]))
    );

    // On SHIFT without LOAD, Q[2] comes from previous Q[1].
    check_shift_bit2_from_bit1: assert property (
        @(posedge CLK) (!LOAD && SHIFT) |=> (Q[2] == $past(Q[1]))
    );

    // On SHIFT without LOAD, Q[1] comes from previous Q[0].
    check_shift_bit1_from_bit0: assert property (
        @(posedge CLK) (!LOAD && SHIFT) |=> (Q[1] == $past(Q[0]))
    );

    // Four consecutive SHIFTs without LOAD zero out the register by the next cycle.
    sequence four_consecutive_shifts_no_load;
        (!LOAD && SHIFT)[*4];
    endsequence
    check_four_shifts_zero_out: assert property (
        @(posedge CLK) four_consecutive_shifts_no_load |=> (Q == 4'b0000)
    );

    // If Q is 0 and a SHIFT occurs without LOAD, Q remains 0 next cycle.
    check_zero_stays_zero_under_shift: assert property (
        @(posedge CLK) (!LOAD && SHIFT && (Q == 4'b0000)) |=> (Q == 4'b0000)
    );
endmodule

rtl:
module shift_sel(
    input [3:0] in,
    input [1:0] sel,
    output reg [3:0] out
);

always @(*) begin
    case(sel)
        2'b00: out = {in[3:2], 2'b00};
        2'b01: out = in & 4'b1100;
        2'b10: out = in | 4'b0011;
        2'b11: out = in ^ 4'b1010;
    endcase
end

endmodule

sva:
module shift_sel_sva (
    input logic clk,
    input logic [3:0] in,
    input logic [1:0] sel,
    input logic [3:0] out
);
    // For sel==00, out is {in[3:2], 2'b00}.
    check_sel00_transform: assert property (
        @(posedge clk) (sel == 2'b00) |-> (out == {in[3:2], 2'b00})
    );

    // For sel==01, out is in & 4'b1100.
    check_sel01_transform: assert property (
        @(posedge clk) (sel == 2'b01) |-> (out == (in & 4'b1100))
    );

    // For sel==10, out is in | 4'b0011.
    check_sel10_transform: assert property (
        @(posedge clk) (sel == 2'b10) |-> (out == (in | 4'b0011))
    );

    // For sel==11, out is in ^ 4'b1010.
    check_sel11_transform: assert property (
        @(posedge clk) (sel == 2'b11) |-> (out == (in ^ 4'b1010))
    );

    // Bit 2 of out always passes through in[2] for all sel values.
    check_out2_passthrough: assert property (
        @(posedge clk) (out[2] == in[2])
    );

    // For sel==00, lower two bits are zero.
    check_sel00_lsb_zero: assert property (
        @(posedge clk) (sel == 2'b00) |-> (out[1:0] == 2'b00)
    );

    // For sel==01, lower two bits are zero.
    check_sel01_lsb_zero: assert property (
        @(posedge clk) (sel == 2'b01) |-> (out[1:0] == 2'b00)
    );

    // For sel==10, lower two bits are ones.
    check_sel10_lsb_one: assert property (
        @(posedge clk) (sel == 2'b10) |-> (out[1:0] == 2'b11)
    );

    // MSB passes through when sel is not 2'b11.
    check_msb_passthrough_unless_xor: assert property (
        @(posedge clk) (sel != 2'b11) |-> (out[3] == in[3])
    );

    // For sel==11, bitwise behavior: invert bits 3 and 1, pass bits 2 and 0.
    check_sel11_bitwise_detail: assert property (
        @(posedge clk) (sel == 2'b11) |-> (out[3] == ~in[3] && out[2] == in[2] && out[1] == ~in[1] && out[0] == in[0])
    );
endmodule

