module ripple_carry_adder (
  input clk,
  input [3:0] A,
  input [3:0] B,
  input Cin,
  output [3:0] S,
  output Cout
);

  reg [3:0] sum;
  reg Cout_reg;

  always @(posedge clk) begin
    sum <= A + B + Cin;
    Cout_reg <= (A[3] & B[3]) | (A[3] & Cin) | (B[3] & Cin);
  end

  assign S = sum;
  assign Cout = Cout_reg;

endmodule

sva:
module ripple_carry_adder_sva (
  input logic clk,
  input logic [3:0] A,
  input logic [3:0] B,
  input logic Cin,
  input logic [3:0] S,
  input logic Cout
);

  ///// Registered behaviors /////
  // S registers the lower 4 bits of A+B+Cin from the previous cycle.
  check_sum_registered: assert property (
    @(posedge clk) S == $past((A + B + Cin)[3:0])
  );

  // Cout registers the MSB carry expression from the previous cycle.
  check_cout_registered: assert property (
    @(posedge clk) Cout == $past((A[3] & B[3]) | (A[3] & Cin) | (B[3] & Cin))
  );

  ///// Stability with repeated inputs /////
  // If A,B,Cin are identical across the last two cycles, outputs repeat.
  check_outputs_repeat_when_inputs_repeat: assert property (
    @(posedge clk) ($past(A,1) == $past(A,2)) && ($past(B,1) == $past(B,2)) && ($past(Cin,1) == $past(Cin,2))
      |-> (S == $past(S)) && (Cout == $past(Cout))
  );

  ///// Sum corner cases /////
  // With B=0 and Cin=0, S follows A (one-cycle latency).
  check_S_eq_A_when_B0_Cin0: assert property (
    @(posedge clk) ($past(B) == 4'b0000) && ($past(Cin) == 1'b0) |-> (S == $past(A))
  );

  // With A=0 and Cin=0, S follows B (one-cycle latency).
  check_S_eq_B_when_A0_Cin0: assert property (
    @(posedge clk) ($past(A) == 4'b0000) && ($past(Cin) == 1'b0) |-> (S == $past(B))
  );

  // With A=0, B=0, Cin=0, S is 0 (one-cycle latency).
  check_S_zero_when_all_zero: assert property (
    @(posedge clk) ($past(A) == 4'b0000) && ($past(B) == 4'b0000) && ($past(Cin) == 1'b0) |-> (S == 4'b0000)
  );

  // With A=0, B=0, Cin=1, S is 1 (one-cycle latency).
  check_S_one_when_only_Cin1: assert property (
    @(posedge clk) ($past(A) == 4'b0000) && ($past(B) == 4'b0000) && ($past(Cin) == 1'b1) |-> (S == 4'b0001)
  );

  // With A=0xF, B=0, Cin=1, S wraps to 0 (one-cycle latency).
  check_S_zero_when_A_F_B0_Cin1: assert property (
    @(posedge clk) ($past(A) == 4'hF) && ($past(B) == 4'h0) && ($past(Cin) == 1'b1) |-> (S == 4'h0)
  );

  ///// Cout corner cases /////
  // If A[3] and B[3] are 1, Cout is 1 (one-cycle latency).
  check_Cout_one_when_A3_and_B3: assert property (
    @(posedge clk) $past(A[3]) && $past(B[3]) |-> (Cout == 1'b1)
  );

  // If Cin=1 and either A[3] or B[3] is 1, Cout is 1 (one-cycle latency).
  check_Cout_one_when_Cin1_and_MSB_one: assert property (
    @(posedge clk) $past(Cin) && ($past(A[3]) || $past(B[3])) |-> (Cout == 1'b1)
  );

  // If Cin=0 and exactly one of A[3],B[3] is 1, Cout is 0 (one-cycle latency).
  check_Cout_zero_when_Cin0_onehot_MSB: assert property (
    @(posedge clk) !$past(Cin) && ($past(A[3]) ^ $past(B[3])) |-> (Cout == 1'b0)
  );

  // If A[3]=0, B[3]=0, and Cin=1, Cout is 0 (one-cycle latency).
  check_Cout_zero_when_no_MSB_and_Cin1: assert property (
    @(posedge clk) !$past(A[3]) && !$past(B[3]) && $past(Cin) |-> (Cout == 1'b0)
  );

endmodule

rtl:
module mux_encoder_decoder_xor (
    input [2:0] sel,
    input [3:0] data0,
    input [3:0] data1,
    input [3:0] data2,
    input [3:0] data3,
    input [3:0] data4,
    input [3:0] data5,
    output [3:0] out
);

    // Priority Encoder
    wire [2:0] encoded_sel;
    priority_encoder pe(sel, encoded_sel);

    // Decoder
    wire [5:0] decoded_sel;
    decoder dec(encoded_sel, decoded_sel);

    // Multiplexer
    wire [3:0] mux_out;
    mux_6to1 mux(
        .sel(encoded_sel[2:0]), // Resized the port to 3 bits
        .data0(data0),
        .data1(data1),
        .data2(data2),
        .data3(data3),
        .data4(data4),
        .data5(data5),
        .out(mux_out)
    );

    // XOR
    wire [3:0] xor_out;
    assign xor_out = mux_out ^ decoded_sel[3:0]; // Resized the port to 3 bits

    // Output
    assign out = xor_out;

endmodule
module priority_encoder (
    input [2:0] in,
    output reg [2:0] out
);

    always @* begin
        case (in)
            3'b000: out = 3'b000;
            3'b001: out = 3'b001;
            3'b010: out = 3'b010;
            3'b011: out = 3'b011;
            3'b100: out = 3'b100;
            3'b101: out = 3'b100;
            3'b110: out = 3'b100;
            3'b111: out = 3'b100;
        endcase
    end

endmodule
module decoder (
    input [2:0] in,
    output reg [5:0] out
);

    always @* begin
        case (in)
            3'b000: out = 6'b000001;
            3'b001: out = 6'b000010;
            3'b010: out = 6'b000100;
            3'b011: out = 6'b001000;
            3'b100: out = 6'b010000;
            3'b101: out = 6'b000000;
            3'b110: out = 6'b000000;
            3'b111: out = 6'b000000;
        endcase
    end

endmodule
module mux_6to1 (
    input [2:0] sel,
    input [3:0] data0,
    input [3:0] data1,
    input [3:0] data2,
    input [3:0] data3,
    input [3:0] data4,
    input [3:0] data5,
    output reg [3:0] out
);

    always @* begin
        case (sel)
            3'b000: out = data0;
            3'b001: out = data1;
            3'b010: out = data2;
            3'b011: out = data3;
            3'b100: out = data4;
            3'b101: out = data5;
            default: out = 4'b0000;
        endcase
    end

endmodule

sva:
module mux_encoder_decoder_xor_sva (
    input logic [2:0] sel,
    input logic [3:0] data0,
    input logic [3:0] data1,
    input logic [3:0] data2,
    input logic [3:0] data3,
    input logic [3:0] data4,
    input logic [3:0] data5,
    input logic [3:0] out
);
    // For sel==000, out equals data0 XOR 1
    check_sel0_xor1_value: assert property (
        @(posedge $global_clock) (sel == 3'b000) |-> (out == (data0 ^ 4'b0001))
    );

    // For sel==001, out equals data1 XOR 2
    check_sel1_xor2_value: assert property (
        @(posedge $global_clock) (sel == 3'b001) |-> (out == (data1 ^ 4'b0010))
    );

    // For sel==010, out equals data2 XOR 4
    check_sel2_xor4_value: assert property (
        @(posedge $global_clock) (sel == 3'b010) |-> (out == (data2 ^ 4'b0100))
    );

    // For sel==011, out equals data3 XOR 8
    check_sel3_xor8_value: assert property (
        @(posedge $global_clock) (sel == 3'b011) |-> (out == (data3 ^ 4'b1000))
    );

    // For any sel with MSB=1 (100..111), out passes data4 unchanged
    check_sel_highbit_uses_data4: assert property (
        @(posedge $global_clock) (sel[2] == 1'b1) |-> (out == data4)
    );

    // If sel stays 000 and data0 is stable, out remains stable
    stability_sel0_data0_stable: assert property (
        @(posedge $global_clock) (sel == 3'b000 && $past(sel) == 3'b000 && $stable(data0)) |-> (out == $past(out))
    );

    // If sel stays 001 and data1 is stable, out remains stable
    stability_sel1_data1_stable: assert property (
        @(posedge $global_clock) (sel == 3'b001 && $past(sel) == 3'b001 && $stable(data1)) |-> (out == $past(out))
    );

    // If sel stays 010 and data2 is stable, out remains stable
    stability_sel2_data2_stable: assert property (
        @(posedge $global_clock) (sel == 3'b010 && $past(sel) == 3'b010 && $stable(data2)) |-> (out == $past(out))
    );

    // If sel stays 011 and data3 is stable, out remains stable
    stability_sel3_data3_stable: assert property (
        @(posedge $global_clock) (sel == 3'b011 && $past(sel) == 3'b011 && $stable(data3)) |-> (out == $past(out))
    );

    // If sel MSB stays 1 and data4 is stable, out remains stable
    stability_sel_highbit_data4_stable: assert property (
        @(posedge $global_clock) (sel[2] && $past(sel[2]) && $stable(data4)) |-> (out == $past(out))
    );

endmodule

module sparc_exu_aluadder64_sva (
    input logic clk,
    input logic [63:0] rs1_data,
    input logic [63:0] rs2_data,
    input logic cin,
    input logic [63:0] adder_out,
    input logic cout32,
    input logic cout64
);
    // Purely combinational adder; no reset in RTL. Assertions are clocked; no disable condition.

    // Lower 32-bit addition with carry-in produces cout32 and adder_out[31:0].
    check_lower_add_split: assert property (
        @(posedge clk) disable iff (1'b0)
        {cout32, adder_out[31:0]} == ({1'b0, rs1_data[31:0]} + {1'b0, rs2_data[31:0]} + cin)
    );

    // Upper 32-bit addition with cout32 carry-in produces cout64 and adder_out[63:32].
    check_upper_add_split: assert property (
        @(posedge clk) disable iff (1'b0)
        {cout64, adder_out[63:32]} == ({1'b0, rs1_data[63:32]} + {1'b0, rs2_data[63:32]} + cout32)
    );

    // Full 65-bit sum matches concatenated {cout64, adder_out}.
    check_full_65bit_sum: assert property (
        @(posedge clk) disable iff (1'b0)
        {cout64, adder_out} == ({1'b0, rs1_data} + {1'b0, rs2_data} + cin)
    );

    // cout32 equals MSB of the 33-bit lower-half sum.
    check_cout32_is_lower_carry: assert property (
        @(posedge clk) disable iff (1'b0)
        cout32 == (({1'b0, rs1_data[31:0]} + {1'b0, rs2_data[31:0]} + cin)[32])
    );

    // adder_out[31:0] equals lower 32 bits of the lower-half sum.
    check_lo_bits_match: assert property (
        @(posedge clk) disable iff (1'b0)
        adder_out[31:0] == (rs1_data[31:0] + rs2_data[31:0] + cin)
    );

    // cout64 equals MSB of the 33-bit upper-half sum with carry-in cout32.
    check_cout64_is_upper_carry: assert property (
        @(posedge clk) disable iff (1'b0)
        cout64 == (({1'b0, rs1_data[63:32]} + {1'b0, rs2_data[63:32]} + cout32)[32])
    );

    // adder_out[63:32] equals lower 32 bits of the upper-half sum with carry-in cout32.
    check_hi_bits_match: assert property (
        @(posedge clk) disable iff (1'b0)
        adder_out[63:32] == (rs1_data[63:32] + rs2_data[63:32] + cout32)
    );

    // cout64 equals bit[64] of the 65-bit total sum.
    check_cout64_matches_total_carry: assert property (
        @(posedge clk) disable iff (1'b0)
        cout64 == (({1'b0, rs1_data} + {1'b0, rs2_data} + cin)[64])
    );

    // adder_out equals the lower 64 bits of the 65-bit total sum.
    check_adder_out_matches_total_low64: assert property (
        @(posedge clk) disable iff (1'b0)
        adder_out == ({1'b0, rs1_data} + {1'b0, rs2_data} + cin)[63:0]
    );

    // Low outputs depend only on rs1[31:0], rs2[31:0], and cin.
    check_lo_outputs_stable_on_lo_inputs_stable: assert property (
        @(posedge clk) disable iff (1'b0)
        $stable(rs1_data[31:0]) && $stable(rs2_data[31:0]) && $stable(cin) |-> $stable({cout32, adder_out[31:0]})
    );

    // High outputs depend only on rs1[63:32], rs2[63:32], and cout32.
    check_hi_outputs_stable_on_hi_inputs_and_cout32_stable: assert property (
        @(posedge clk) disable iff (1'b0)
        $stable(rs1_data[63:32]) && $stable(rs2_data[63:32]) && $stable(cout32) |-> $stable({cout64, adder_out[63:32]})
    );

endmodule

rtl:
module delay3stage (
    Y   ,
    A   ,
    VPWR,
    VGND,
    VPB ,
    VNB
);

    output Y   ;
    input  A   ;
    input  VPWR;
    input  VGND;
    input  VPB ;
    input  VNB ;

    wire inv1, inv2, inv3;

    assign inv1 = ~A;
    assign inv2 = ~inv1;
    assign inv3 = ~inv2;

    assign Y = inv3;

endmodule

sva:
module delay3stage_sva (
    input logic Y,
    input logic A,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB
);
    // Y must be the bitwise complement of A when sampled on A rising edge.
    check_complement_on_A_posedge: assert property (
        @(posedge A) (Y == ~A)
    );

    // Y must be the bitwise complement of A when sampled on Y rising edge.
    check_complement_on_Y_posedge: assert property (
        @(posedge Y) (Y == ~A)
    );

    // When A rises, Y must fall (opposite toggle).
    check_y_falls_on_a_rise: assert property (
        @(posedge A) $fell(Y)
    );

    // When Y rises, A must fall (opposite toggle).
    check_a_falls_on_y_rise: assert property (
        @(posedge Y) $fell(A)
    );

    // A and Y are never equal when sampled on A rising edge.
    check_inequality_on_A_posedge: assert property (
        @(posedge A) (Y != A)
    );

    // Exactly one of A or Y is 1 when sampled on A rising edge.
    check_one_hot_on_A_posedge: assert property (
        @(posedge A) (A ^ Y) == 1'b1
    );

    // Complement relation holds regardless of VPWR events.
    check_complement_on_VPWR_posedge: assert property (
        @(posedge VPWR) (Y == ~A)
    );

    // Complement relation holds regardless of VGND events.
    check_complement_on_VGND_posedge: assert property (
        @(posedge VGND) (Y == ~A)
    );

    // Complement relation holds regardless of VPB events.
    check_complement_on_VPB_posedge: assert property (
        @(posedge VPB) (Y == ~A)
    );

    // Complement relation holds regardless of VNB events.
    check_complement_on_VNB_posedge: assert property (
        @(posedge VNB) (Y == ~A)
    );
endmodule

rtl:
module mux_1bit (
  input ctrl,
  input [0:0] D0,
  input [0:0] D1,
  output reg [0:0] S
);

  always @(*) begin
    case(ctrl)
      1'b0: S = D0;
      1'b1: S = D1;
    endcase
  end

endmodule

sva:
module mux_1bit_sva (
    input logic CLK,
    input logic ctrl,
    input logic [0:0] D0,
    input logic [0:0] D1,
    input logic [0:0] S
);

    // S equals the selected data input (functional equivalence).
    check_mux_functional_equivalence: assert property (
        @(posedge CLK) S == (ctrl ? D1 : D0)
    );

    // When ctrl is 0, S equals D0.
    check_select_D0_when_ctrl_0: assert property (
        @(posedge CLK) (ctrl == 1'b0) |-> (S == D0)
    );

    // When ctrl is 1, S equals D1.
    check_select_D1_when_ctrl_1: assert property (
        @(posedge CLK) (ctrl == 1'b1) |-> (S == D1)
    );

    // On ctrl rising edge, S reflects D1.
    check_output_on_ctrl_rise_selects_D1: assert property (
        @(posedge CLK) $rose(ctrl) |-> (S == D1)
    );

    // On ctrl falling edge, S reflects D0.
    check_output_on_ctrl_fall_selects_D0: assert property (
        @(posedge CLK) $fell(ctrl) |-> (S == D0)
    );

    // With ctrl=0, changes on D1 do not affect S if ctrl and D0 are stable.
    check_unselected_input_no_effect_when_ctrl_0: assert property (
        @(posedge CLK) (ctrl == 1'b0) && $stable(ctrl) && $stable(D0) && $changed(D1) |-> $stable(S)
    );

    // With ctrl=1, changes on D0 do not affect S if ctrl and D1 are stable.
    check_unselected_input_no_effect_when_ctrl_1: assert property (
        @(posedge CLK) (ctrl == 1'b1) && $stable(ctrl) && $stable(D1) && $changed(D0) |-> $stable(S)
    );

    // If ctrl, D0, and D1 are stable, S remains stable (pure combinational).
    check_output_stable_when_all_inputs_stable: assert property (
        @(posedge CLK) $stable(ctrl) && $stable(D0) && $stable(D1) |-> $stable(S)
    );

    // With ctrl=0 and stable, S changes iff D0 changes.
    check_output_tracks_D0_when_ctrl_0_changes: assert property (
        @(posedge CLK) (ctrl == 1'b0) && $stable(ctrl) && $changed(D0) |-> $changed(S)
    );

    // With ctrl=1 and stable, S changes iff D1 changes.
    check_output_tracks_D1_when_ctrl_1_changes: assert property (
        @(posedge CLK) (ctrl == 1'b1) && $stable(ctrl) && $changed(D1) |-> $changed(S)
    );

    // If ctrl toggles and the newly selected input differs from the previously selected input, S changes.
    check_sel_toggle_changes_output_if_new_selected_differs_from_prev_selected: assert property (
        @(posedge CLK)
            $changed(ctrl) && (
                (ctrl && (D1 != $past(D0))) ||
                (!ctrl && (D0 != $past(D1)))
            ) |-> $changed(S)
    );

    // If D0 equals D1, S equals that value regardless of ctrl.
    check_equal_inputs_force_S_equal: assert property (
        @(posedge CLK) (D0 == D1) |-> (S == D0)
    );

endmodule

rtl:
module binary_adder(
    input [3:0] A,
    input [3:0] B,
    input CIN,
    output reg [3:0] S,
    output reg COUT
);

    reg CARRY;

    always @(*) begin
        S[0] = A[0] ^ B[0] ^ CIN;
        CARRY = (A[0] & B[0]) | (A[0] & CIN) | (B[0] & CIN);
        S[1] = A[1] ^ B[1] ^ CARRY;
        CARRY = (A[1] & B[1]) | (A[1] & CARRY) | (B[1] & CARRY);
        S[2] = A[2] ^ B[2] ^ CARRY;
        CARRY = (A[2] & B[2]) | (A[2] & CARRY) | (B[2] & CARRY);
        S[3] = A[3] ^ B[3] ^ CARRY;
        COUT = (A[3] & B[3]) | (A[3] & CARRY) | (B[3] & CARRY);
    end

endmodule

sva:
module binary_adder_sva (
    // External sampling clock/reset for SVA (DUT is purely combinational)
    input logic clk,
    input logic reset_n,
    // DUT ports
    input logic [3:0] A,
    input logic [3:0] B,
    input logic CIN,
    input logic [3:0] S,
    input logic COUT
);
    // DUT has no clock/reset; logic is purely combinational. Assertions sample on clk.

    // Local aliases for carry chain and 5-bit sum
    let c0   = (A[0] & B[0]) | (A[0] & CIN) | (B[0] & CIN);
    let c1   = (A[1] & B[1]) | (A[1] & c0)  | (B[1] & c0);
    let c2   = (A[2] & B[2]) | (A[2] & c1)  | (B[2] & c1);
    let sum5 = {1'b0, A} + {1'b0, B} + CIN;

    ///// Functional equivalence /////
    // 5-bit result equals A + B + CIN.
    check_full_sum_equivalence: assert property (
        @(posedge clk) disable iff (!reset_n) {COUT, S} == sum5
    );

    ///// Bit-level ripple-carry equations /////
    // Bit 0 sum is XOR of A[0], B[0], CIN.
    check_bit0_sum_xor: assert property (
        @(posedge clk) disable iff (!reset_n) S[0] == (A[0] ^ B[0] ^ CIN)
    );
    // Bit 1 sum uses carry from bit 0.
    check_bit1_sum_xor_with_c0: assert property (
        @(posedge clk) disable iff (!reset_n) S[1] == (A[1] ^ B[1] ^ c0)
    );
    // Bit 2 sum uses carry from bit 1.
    check_bit2_sum_xor_with_c1: assert property (
        @(posedge clk) disable iff (!reset_n) S[2] == (A[2] ^ B[2] ^ c1)
    );
    // Bit 3 sum uses carry from bit 2.
    check_bit3_sum_xor_with_c2: assert property (
        @(posedge clk) disable iff (!reset_n) S[3] == (A[3] ^ B[3] ^ c2)
    );
    // Final carry-out from bit 3 matches generate/propagate logic.
    check_cout_from_c2: assert property (
        @(posedge clk) disable iff (!reset_n) COUT == ((A[3] & B[3]) | (A[3] & c2) | (B[3] & c2))
    );

    ///// Sanity behaviors (direct consequences of the adder logic) /////
    // When B==0 and CIN==0, output equals A with no carry.
    check_transparent_when_B_zero_no_cin: assert property (
        @(posedge clk) disable iff (!reset_n) ((B == 4'b0) && (CIN == 1'b0)) |-> (S == A && COUT == 1'b0)
    );
    // When A==0 and CIN==0, output equals B with no carry.
    check_transparent_when_A_zero_no_cin: assert property (
        @(posedge clk) disable iff (!reset_n) ((A == 4'b0) && (CIN == 1'b0)) |-> (S == B && COUT == 1'b0)
    );
    // All zeros in yields all zeros out.
    check_zero_inputs_zero_outputs: assert property (
        @(posedge clk) disable iff (!reset_n) ((A == 4'b0) && (B == 4'b0) && (CIN == 1'b0)) |-> ((S == 4'b0) && (COUT == 1'b0))
    );
    // Only CIN asserted increments by 1 with no carry-out.
    check_only_cin_increments_by_one: assert property (
        @(posedge clk) disable iff (!reset_n) ((A == 4'b0) && (B == 4'b0) && (CIN == 1'b1)) |-> ((S == 4'b0001) && (COUT == 1'b0))
    );
endmodule

module barrel_shifter_4bit_sva (
    input logic clk,
    input logic [3:0] in,
    input logic [1:0] shift,
    input logic [3:0] out
);
    ///// Functional mapping from previous-cycle inputs to registered output /////
    // If previous shift was 00, out equals previous in logically left-shifted by 1.
    map_shift00_full: assert property (
        @(posedge clk) ($past(shift) == 2'b00) |-> (out == ($past(in) << 1))
    );

    // If previous shift was 01, out equals previous in logically right-shifted by 1.
    map_shift01_full: assert property (
        @(posedge clk) ($past(shift) == 2'b01) |-> (out == ($past(in) >> 1))
    );

    // If previous shift was 10, out equals previous in rotated left by 2.
    map_shift10_full: assert property (
        @(posedge clk) ($past(shift) == 2'b10) |-> (out == { $past(in[1:0]), $past(in[3:2]) })
    );

    ///// Bit-level consequences of each transform /////
    // For shift 00, LSB of out is 0 (inserted zero on left shift).
    shift00_lsb_zero: assert property (
        @(posedge clk) ($past(shift) == 2'b00) |-> (out[0] == 1'b0)
    );

    // For shift 00, upper bits of out come from previous lower bits of in.
    shift00_upper_from_lower: assert property (
        @(posedge clk) ($past(shift) == 2'b00) |-> (out[3:1] == $past(in[2:0]))
    );

    // For shift 01, MSB of out is 0 (inserted zero on right shift).
    shift01_msb_zero: assert property (
        @(posedge clk) ($past(shift) == 2'b01) |-> (out[3] == 1'b0)
    );

    // For shift 01, lower bits of out come from previous upper bits of in.
    shift01_lower_from_upper: assert property (
        @(posedge clk) ($past(shift) == 2'b01) |-> (out[2:0] == $past(in[3:1]))
    );

    // For shift 10, out[3:2] equal previous in[1:0].
    shift10_upper_matches_prev_lsb: assert property (
        @(posedge clk) ($past(shift) == 2'b10) |-> (out[3:2] == $past(in[1:0]))
    );

    // For shift 10, out[1:0] equal previous in[3:2].
    shift10_lower_matches_prev_msb: assert property (
        @(posedge clk) ($past(shift) == 2'b10) |-> (out[1:0] == $past(in[3:2]))
    );

    ///// Stability rule /////
    // If in and shift are unchanged over two cycles, out remains unchanged.
    stable_out_if_inputs_stable: assert property (
        @(posedge clk) ($past(in,2) == $past(in)) && ($past(shift,2) == $past(shift)) |-> (out == $past(out))
    );
endmodule

