sva:
module sky130_fd_sc_hd__o32ai_sva (
    input logic clk,   // Assertion clock (DUT has no clock/reset)
    input logic Y,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic B1,
    input logic B2
);
    // Analysis: No clock/reset in DUT; logic is purely combinational.
    // Function: Y = ~((A1|A2|A3) & (B1|B2)) = ((~A1 & ~A2 & ~A3) | (~B1 & ~B2)).

    // Local combinational reductions for readability
    wire a_or = (A1 | A2 | A3);
    wire b_or = (B1 | B2);
    wire y_func_andinv   = ~(a_or & b_or);
    wire y_func_demorgan = ((~A1 & ~A2 & ~A3) | (~B1 & ~B2));

    ///// Functional equivalence checks /////
    // Y must equal ~( (A1|A2|A3) & (B1|B2) ).
    check_function_equivalence_andinv: assert property (
        @(posedge clk) (Y === y_func_andinv)
    );

    // Y must equal ((~A1 & ~A2 & ~A3) | (~B1 & ~B2)).
    check_function_equivalence_demorgan: assert property (
        @(posedge clk) (Y === y_func_demorgan)
    );

    // The two equivalent forms of the function must agree.
    check_internal_forms_agree: assert property (
        @(posedge clk) (y_func_andinv === y_func_demorgan)
    );

    ///// Useful implications of the Boolean function /////
    // If all A-group inputs are 0, Y is 1.
    check_y_high_when_a_group_all_zero: assert property (
        @(posedge clk) (!a_or) |-> (Y === 1'b1)
    );

    // If all B-group inputs are 0, Y is 1.
    check_y_high_when_b_group_all_zero: assert property (
        @(posedge clk) (!b_or) |-> (Y === 1'b1)
    );

    // If both groups have at least one 1, Y is 0.
    check_y_low_when_both_groups_active: assert property (
        @(posedge clk) (a_or && b_or) |-> (Y === 1'b0)
    );

    // If only A-group has a 1 and B-group has none, Y is 1.
    check_y_high_when_only_a_active: assert property (
        @(posedge clk) (a_or && !b_or) |-> (Y === 1'b1)
    );

    // If only B-group has a 1 and A-group has none, Y is 1.
    check_y_high_when_only_b_active: assert property (
        @(posedge clk) (!a_or && b_or) |-> (Y === 1'b1)
    );

    ///// Consistency and stability /////
    // If inputs are stable across a cycle, Y must be stable.
    check_output_stable_when_inputs_stable: assert property (
        @(posedge clk) $stable({A1,A2,A3,B1,B2}) |-> $stable(Y)
    );

    // If Y is 0, both group ORs must be 1.
    check_y_low_implies_both_groups_active: assert property (
        @(posedge clk) (Y === 1'b0) |-> (a_or && b_or)
    );

    // If Y is 1, at least one group OR must be 0.
    check_y_high_implies_some_group_zero: assert property (
        @(posedge clk) (Y === 1'b1) |-> ((!a_or) || (!b_or))
    );

endmodule

rtl:
module comparator (
  input [3:0] in1,
  input [3:0] in2,
  output reg [1:0] out
);

  always @ (in1, in2) begin
    if (in1 == in2) begin
      out <= 2'b00;
    end else if (in1 > in2) begin
      out <= 2'b01;
    end else begin
      out <= 2'b10;
    end
  end

endmodule

sva:
module comparator_sva (
    input logic clk,
    input logic [3:0] in1,
    input logic [3:0] in2,
    input logic [1:0] out
);
    ///// Combinational mapping checks /////
    // When in1 equals in2, out must be 2'b00.
    map_eq: assert property (
        @(posedge clk) (in1 == in2) |-> (out == 2'b00)
    );
    // When in1 is greater than in2, out must be 2'b01.
    map_gt: assert property (
        @(posedge clk) (in1 > in2) |-> (out == 2'b01)
    );
    // When in1 is less than in2, out must be 2'b10.
    map_lt: assert property (
        @(posedge clk) (in1 < in2) |-> (out == 2'b10)
    );

    ///// Reverse mapping (code implies relation) /////
    // If out is 2'b00, inputs must be equal.
    rev_map_eq: assert property (
        @(posedge clk) (out == 2'b00) |-> (in1 == in2)
    );
    // If out is 2'b01, in1 must be greater than in2.
    rev_map_gt: assert property (
        @(posedge clk) (out == 2'b01) |-> (in1 > in2)
    );
    // If out is 2'b10, in1 must be less than in2.
    rev_map_lt: assert property (
        @(posedge clk) (out == 2'b10) |-> (in1 < in2)
    );

    ///// Encoding sanity /////
    // out must never be 2'b11.
    out_never_illegal_11: assert property (
        @(posedge clk) out != 2'b11
    );

    ///// Stability relationships /////
    // If inputs are stable across a cycle, out must be stable.
    output_stable_when_inputs_stable: assert property (
        @(posedge clk) ($stable(in1) && $stable(in2)) |-> $stable(out)
    );
    // If out changes, at least one input must have changed.
    out_change_requires_input_change: assert property (
        @(posedge clk) $changed(out) |-> ($changed(in1) || $changed(in2))
    );
endmodule

module mux_2_to_1_sva (
    input logic in1,
    input logic in2,
    input logic select,
    input logic out
);
    // On a select edge, if previous select was 0, current out equals previous in1.
    check_prev_sel0_captured_in1: assert property (
        @(posedge select or negedge select) ($past(select) == 1'b0) |-> (out == $past(in1))
    );

    // On a select edge, if previous select was 1, current out equals previous in2.
    check_prev_sel1_captured_in2: assert property (
        @(posedge select or negedge select) ($past(select) == 1'b1) |-> (out == $past(in2))
    );

    // On posedge in1 with no select change since last posedge in1, out must be stable.
    check_out_stable_on_in1_posedge_when_select_stable: assert property (
        @(posedge in1) $stable(select) |-> $stable(out)
    );

    // On negedge in1 with no select change since last negedge in1, out must be stable.
    check_out_stable_on_in1_negedge_when_select_stable: assert property (
        @(negedge in1) $stable(select) |-> $stable(out)
    );

    // On posedge in2 with no select change since last posedge in2, out must be stable.
    check_out_stable_on_in2_posedge_when_select_stable: assert property (
        @(posedge in2) $stable(select) |-> $stable(out)
    );

    // On negedge in2 with no select change since last negedge in2, out must be stable.
    check_out_stable_on_in2_negedge_when_select_stable: assert property (
        @(negedge in2) $stable(select) |-> $stable(out)
    );

    // Sanity: at posedge select, select must read as 1.
    check_select_value_on_posedge: assert property (
        @(posedge select) select == 1'b1
    );

    // Sanity: at negedge select, select must read as 0.
    check_select_value_on_negedge: assert property (
        @(negedge select) select == 1'b0
    );
endmodule

