sva:
module or_gate_sva (
    input logic CLK,
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic X
);
    ///// Functional correctness /////
    // X equals bitwise OR of all inputs.
    check_or_equivalence: assert property (
        @(posedge CLK) X === (A | B | C | D)
    );

    // When all inputs are 0, X must be 0.
    check_all_zero_implies_x_zero: assert property (
        @(posedge CLK) ((A == 1'b0) && (B == 1'b0) && (C == 1'b0) && (D == 1'b0)) |-> (X == 1'b0)
    );

    // If any input is 1, X must be 1.
    check_any_one_implies_x_one: assert property (
        @(posedge CLK) (A || B || C || D) |-> (X == 1'b1)
    );

    // If X is 0, all inputs must be 0.
    check_x_zero_implies_all_zero: assert property (
        @(posedge CLK) (X == 1'b0) |-> ((A == 1'b0) && (B == 1'b0) && (C == 1'b0) && (D == 1'b0))
    );

    // If X is 1, at least one input must be 1.
    check_x_one_implies_any_one: assert property (
        @(posedge CLK) (X == 1'b1) |-> (A || B || C || D)
    );

    ///// Stability and dependency /////
    // With stable inputs, X must remain stable.
    check_stable_inputs_implies_stable_x: assert property (
        @(posedge CLK) $stable({A,B,C,D}) |-> $stable(X)
    );

    // If X changes, at least one input must have changed.
    check_x_change_implies_input_change: assert property (
        @(posedge CLK) !$stable(X) |-> !$stable({A,B,C,D})
    );

    ///// Individual input dominance when others are 0 /////
    // With B,C,D=0, X must equal A.
    check_dom_a_when_others_zero: assert property (
        @(posedge CLK) ((B == 1'b0) && (C == 1'b0) && (D == 1'b0)) |-> (X === A)
    );

    // With A,C,D=0, X must equal B.
    check_dom_b_when_others_zero: assert property (
        @(posedge CLK) ((A == 1'b0) && (C == 1'b0) && (D == 1'b0)) |-> (X === B)
    );

    // With A,B,D=0, X must equal C.
    check_dom_c_when_others_zero: assert property (
        @(posedge CLK) ((A == 1'b0) && (B == 1'b0) && (D == 1'b0)) |-> (X === C)
    );

    // With A,B,C=0, X must equal D.
    check_dom_d_when_others_zero: assert property (
        @(posedge CLK) ((A == 1'b0) && (B == 1'b0) && (C == 1'b0)) |-> (X === D)
    );

endmodule

rtl:
module binary_counter(clk, en, clr, count);
    input clk, en, clr;
    output reg [3:0] count;

    always @(posedge clk) begin
        if(clr == 1'b1) begin
            count <= 4'b0;
        end
        else if(en == 1'b1) begin
            count <= count + 4'b1;
        end
    end
endmodule

sva:
module binary_counter_sva (
    input logic clk,
    input logic en,
    input logic clr,
    input logic [3:0] count
);
    // When clr is 1, next cycle count must be 0.
    check_clear_sets_zero: assert property (
        @(posedge clk) clr |=> (count == 4'b0)
    );

    // Clear has priority over enable when both are 1.
    check_clear_overrides_enable: assert property (
        @(posedge clk) (clr && en) |=> (count == 4'b0)
    );

    // When enabled without clear, count increments by 1 modulo 16.
    check_enable_increments: assert property (
        @(posedge clk) (!clr && en) |=> (count == $past(count) + 4'd1)
    );

    // When both clear and enable are 0, count holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) (!clr && !en) |=> (count == $past(count))
    );

    // When count is 0xF and enabled (without clear), it wraps to 0.
    check_wrap_on_max: assert property (
        @(posedge clk) (!clr && en && (count == 4'hF)) |=> (count == 4'h0)
    );

    // Any change must be due to prior clr or prior enable without clr.
    check_no_spurious_change: assert property (
        @(posedge clk) disable iff ($initstate)
            (count != $past(count)) |-> ($past(clr) || ($past(en) && !$past(clr)))
    );

    // If clr was high in the previous cycle, current count is 0.
    check_prev_clear_results_zero: assert property (
        @(posedge clk) disable iff ($initstate)
            $past(clr) |-> (count == 4'h0)
    );

    // If previously enabled without clear, current count equals prev+1.
    check_prev_enable_increments: assert property (
        @(posedge clk) disable iff ($initstate)
            $past(!clr && en) |-> (count == $past(count) + 4'd1)
    );

    // If previously disabled without clear, current count is unchanged.
    check_prev_hold: assert property (
        @(posedge clk) disable iff ($initstate)
            $past(!clr && !en) |-> (count == $past(count))
    );

    // Functional update equation matches RTL for all cases.
    check_functional_update_equation: assert property (
        @(posedge clk) disable iff ($initstate)
            count == ($past(clr) ? 4'd0 : ($past(en) ? $past(count) + 4'd1 : $past(count)))
    );
endmodule

rtl:
module transition_detector_register (
    input clk,
    input reset,
    input signal,
    output reg [31:0] output_reg
);

reg signal_d;
always @(posedge clk) begin
    signal_d <= signal;
    if (reset) begin
        output_reg <= 1;
    end else if (signal_d && !signal) begin
        output_reg <= {32{1'b1}};
    end
end

endmodule

sva:
module transition_detector_register_sva (
    input logic clk,
    input logic reset,          // active-high synchronous reset
    input logic signal,
    input logic [31:0] output_reg
);
    // Reset sets output_reg to 1 on the next cycle.
    reset_sets_output_reg: assert property (
        @(posedge clk) reset |=> (output_reg == 32'd1)
    );

    // A falling edge of signal (when not in reset) sets output_reg to all 1s on the next cycle.
    fall_sets_all_ones: assert property (
        @(posedge clk) disable iff (reset) $fell(signal) |=> (output_reg == 32'hFFFF_FFFF)
    );

    // Reset has priority over falling-edge detection.
    reset_overrides_fall: assert property (
        @(posedge clk) (reset && $fell(signal)) |=> (output_reg == 32'd1)
    );

    // When not in reset and no falling edge occurs, output_reg holds its value.
    hold_without_fall: assert property (
        @(posedge clk) disable iff (reset) !$fell(signal) |=> (output_reg == $past(output_reg))
    );

    // A rising edge of signal does not change output_reg.
    rise_no_update: assert property (
        @(posedge clk) disable iff (reset) $rose(signal) |=> (output_reg == $past(output_reg))
    );
endmodule

rtl:
module barrel_shifter_16bit (
    input [15:0] data,
    input [3:0] shift_amount,
    output reg [15:0] out
);

reg [15:0] stage1_out;
reg [15:0] stage2_out;

always @(*) begin
    stage1_out = (shift_amount[3]) ? data << 8 : data;
end

always @(*) begin
    stage2_out = (shift_amount[2]) ? stage1_out << 4 : stage1_out;
end

always @(*) begin
    out = (shift_amount[1]) ? stage2_out << 2 : stage2_out;
end

endmodule

sva:
module barrel_shifter_16bit_sva (
    input logic clk,
    input logic [15:0] data,
    input logic [3:0] shift_amount,
    input logic [15:0] out
);
    ///// Functional mapping for each shift combination (shift_amount[3:1]) /////
    // No shift when [3:1]==000.
    check_shift_0: assert property (
        @(posedge clk) (shift_amount[3:1] == 3'b000) |-> (out == data)
    );

    // Shift by 2 when [3:1]==001.
    check_shift_2: assert property (
        @(posedge clk) (shift_amount[3:1] == 3'b001) |-> (out == (data << 2))
    );

    // Shift by 4 when [3:1]==010.
    check_shift_4: assert property (
        @(posedge clk) (shift_amount[3:1] == 3'b010) |-> (out == (data << 4))
    );

    // Shift by 6 when [3:1]==011.
    check_shift_6: assert property (
        @(posedge clk) (shift_amount[3:1] == 3'b011) |-> (out == (data << 6))
    );

    // Shift by 8 when [3:1]==100.
    check_shift_8: assert property (
        @(posedge clk) (shift_amount[3:1] == 3'b100) |-> (out == (data << 8))
    );

    // Shift by 10 when [3:1]==101.
    check_shift_10: assert property (
        @(posedge clk) (shift_amount[3:1] == 3'b101) |-> (out == (data << 10))
    );

    // Shift by 12 when [3:1]==110.
    check_shift_12: assert property (
        @(posedge clk) (shift_amount[3:1] == 3'b110) |-> (out == (data << 12))
    );

    // Shift by 14 when [3:1]==111.
    check_shift_14: assert property (
        @(posedge clk) (shift_amount[3:1] == 3'b111) |-> (out == (data << 14))
    );

    ///// Bit-level structural consequences of left shifts /////
    // LSBs [1:0] are zeroed whenever shift by 2 is selected.
    check_lsb_zero_when_b1: assert property (
        @(posedge clk) shift_amount[1] |-> (out[1:0] == 2'b00)
    );

    // LSBs [3:0] are zeroed whenever shift by 4 is selected.
    check_lsb_zero_when_b2: assert property (
        @(posedge clk) shift_amount[2] |-> (out[3:0] == 4'b0000)
    );

    // LSBs [7:0] are zeroed whenever shift by 8 is selected.
    check_lsb_zero_when_b3: assert property (
        @(posedge clk) shift_amount[3] |-> (out[7:0] == 8'b0000_0000)
    );

    ///// Insensitivity to shift_amount[0] /////
    // Changing shift_amount[0] alone does not change out.
    check_ignore_shift_bit0: assert property (
        @(posedge clk) ($changed(shift_amount[0]) && $stable(data) && $stable(shift_amount[3:1])) |-> $stable(out)
    );

    ///// Combinational stability /////
    // If inputs are stable, output stays stable.
    check_stable_inputs_imply_stable_out: assert property (
        @(posedge clk) ($stable(data) && $stable(shift_amount)) |-> $stable(out)
    );
endmodule

