    Y  ,
    A_N,
    B
);

    output Y  ;
    input  A_N;
    input  B  ;

    wire not0_out ;
    wire or0_out_Y;

    not not0 (not0_out , B              );
    or  or0  (or0_out_Y, not0_out, A_N  );
