module TOP(
    input wire in,
    output reg out0,
    output reg out1,
    output reg out2,
    output reg out3,
    output reg out
);

reg [1:0] counter;
reg [3:0] bits;

always @(posedge in)
begin
    counter <= counter + 1;
    bits[counter[1:0]] <= in;
    out0 <= bits[0];
    out1 <= bits[1];
    out2 <= bits[2];
    out3 <= bits[3];
    out <= {out3, out2, out1, out0};
end

endmodule

sva:
module TOP_sva (
    input logic in,
    input logic out0,
    input logic out1,
    input logic out2,
    input logic out3,
    input logic out,
    input logic [1:0] counter,
    input logic [3:0] bits
);
    ///// Counter behavior /////
    // Counter increments by 1 (mod 4) each posedge of 'in'.
    check_counter_increments: assert property (
        @(posedge in) $past(1'b1) |-> (counter == $past(counter) + 2'd1)
    );

    ///// Bits array update /////
    // The bit indexed by previous cycle's counter (pre-increment) is updated to previous 'in' value.
    check_bits_write_value: assert property (
        @(posedge in) $past(1'b1) |-> (bits[($past(counter) - 2'd1)] == $past(in))
    );
    // bits[0] is unchanged if it was not the written index last cycle.
    check_bits0_stable_when_not_written: assert property (
        @(posedge in) ($past(1'b1) && (($past(counter) - 2'd1) != 2'd0)) |-> (bits[0] == $past(bits[0]))
    );
    // bits[1] is unchanged if it was not the written index last cycle.
    check_bits1_stable_when_not_written: assert property (
        @(posedge in) ($past(1'b1) && (($past(counter) - 2'd1) != 2'd1)) |-> (bits[1] == $past(bits[1]))
    );
    // bits[2] is unchanged if it was not the written index last cycle.
    check_bits2_stable_when_not_written: assert property (
        @(posedge in) ($past(1'b1) && (($past(counter) - 2'd1) != 2'd2)) |-> (bits[2] == $past(bits[2]))
    );
    // bits[3] is unchanged if it was not the written index last cycle.
    check_bits3_stable_when_not_written: assert property (
        @(posedge in) ($past(1'b1) && (($past(counter) - 2'd1) != 2'd3)) |-> (bits[3] == $past(bits[3]))
    );

    ///// Output registers /////
    // out0 captures bits[0] from the previous cycle.
    check_out0_follows_bits0: assert property (
        @(posedge in) $past(1'b1) |-> (out0 == $past(bits[0]))
    );
    // out1 captures bits[1] from the previous cycle.
    check_out1_follows_bits1: assert property (
        @(posedge in) $past(1'b1) |-> (out1 == $past(bits[1]))
    );
    // out2 captures bits[2] from the previous cycle.
    check_out2_follows_bits2: assert property (
        @(posedge in) $past(1'b1) |-> (out2 == $past(bits[2]))
    );
    // out3 captures bits[3] from the previous cycle.
    check_out3_follows_bits3: assert property (
        @(posedge in) $past(1'b1) |-> (out3 == $past(bits[3]))
    );
    // out captures the previous value of out0 (LSB of the concatenation).
    check_out_follows_prev_out0: assert property (
        @(posedge in) $past(1'b1) |-> (out == $past(out0))
    );
endmodule

rtl:
module top_module (
    input clk,          // Clock input
    input reset,        // Synchronous active-high reset
    input [7:0] d,      // 8-bit input for the register
    input [1:0] select, // Select input to choose between register and counter
    output [11:0] q     // 12-bit output from the functional module
);

    // Register module with active high synchronous reset
    reg [7:0] reg_out;
    always @(posedge clk) begin
        if (reset) begin
            reg_out <= 8'h34;
        end else begin
            reg_out <= d;
        end
    end

    // Counter module with synchronous reset
    reg [3:0] counter_out;
    always @(posedge clk) begin
        if (reset) begin
            counter_out <= 4'h0;
        end else begin
            counter_out <= counter_out + 1;
        end
    end

    // Control logic module to select between register and counter output
    reg [7:0] selected_input;
    always @* begin
        if (select == 2'b00) begin
            selected_input = reg_out;
        end else if (select == 2'b01) begin
            selected_input = counter_out;
        end else begin
            selected_input = 8'h0;
        end
    end

    // Functional module to add the selected inputs
    wire [11:0] added_output;
    assign added_output = {4'b0, selected_input} + {4'b0, reg_out};

    // Output from the functional module
    assign q = added_output;

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic reset,
    input logic [7:0] d,
    input logic [1:0] select,
    input logic [11:0] q,
    // Internal design signals
    input logic [7:0] reg_out,
    input logic [3:0] counter_out,
    input logic [7:0] selected_input,
    input logic [11:0] added_output
);

    ///// Reset behavior /////
    // During reset, reg_out is 0x34.
    check_reg_out_reset_value: assert property (
        @(posedge clk) reset |-> (reg_out == 8'h34)
    );
    // During reset, counter_out is 0.
    check_counter_reset_value: assert property (
        @(posedge clk) reset |-> (counter_out == 4'h0)
    );

    ///// Register behavior /////
    // When not in reset and previous cycle not in reset, reg_out captures previous d.
    check_reg_out_loads_d: assert property (
        @(posedge clk) disable iff (reset) (!$past(reset)) |-> (reg_out == $past(d))
    );

    ///// Counter behavior /////
    // When not in reset and previous cycle not in reset, counter_out increments by 1 (mod 16).
    check_counter_increments: assert property (
        @(posedge clk) disable iff (reset) (!$past(reset)) |-> (counter_out == ($past(counter_out) + 4'd1))
    );

    ///// Selection logic /////
    // When select == 2'b00, selected_input equals reg_out.
    check_select00_uses_reg_out: assert property (
        @(posedge clk) disable iff (reset) (select == 2'b00) |-> (selected_input == reg_out)
    );
    // When select == 2'b01, selected_input equals zero-extended counter_out.
    check_select01_uses_counter_zero_ext: assert property (
        @(posedge clk) disable iff (reset) (select == 2'b01) |-> ((selected_input[3:0] == counter_out) && (selected_input[7:4] == 4'h0))
    );
    // When select is neither 00 nor 01, selected_input is zero.
    check_select_other_zero: assert property (
        @(posedge clk) disable iff (reset) ((select != 2'b00) && (select != 2'b01)) |-> (selected_input == 8'h00)
    );

    ///// Adder and output /////
    // added_output equals zero-extended sum of selected_input and reg_out.
    check_added_output_sum_definition: assert property (
        @(posedge clk) disable iff (reset) (added_output == ({4'b0, selected_input} + {4'b0, reg_out}))
    );
    // q equals added_output.
    check_q_ties_to_added_output: assert property (
        @(posedge clk) disable iff (reset) (q == added_output)
    );
    // When select == 2'b00, added_output equals reg_out + reg_out (zero-extended).
    check_select00_sum_double_reg_out: assert property (
        @(posedge clk) disable iff (reset) (select == 2'b00) |-> (added_output == ({4'b0, reg_out} + {4'b0, reg_out}))
    );

endmodule

rtl:
`define MAXQ 2
module uut (
	input clk,
	input d, r, e,
	output [`MAXQ:0] q
);
	reg q0;
	always @(posedge clk) begin
		if (r)
			q0 <= 0;
		else if (e)
			q0 <= d;
	end

	reg q1;
	always @(posedge clk, posedge r) begin
		if (r)
			q1 <= 0;
		else if (e)
			q1 <= d;
	end

	reg q2;
	always @(posedge clk, negedge r) begin
		if (!r)
			q2 <= 0;
		else if (!e)
			q2 <= d;
	end

	assign q = {q2, q1, q0};
endmodule

