module xor_gate(
    input a,
    input b,
    output out
);

wire w1, w2, w3;

and_gate and1(.a(a), .b(~b), .out(w1));
and_gate and2(.a(~a), .b(b), .out(w2));
or_gate or1(.a(w1), .b(w2), .out(w3));
not_gate not1(.a(w3), .out(out));

endmodule

module and_gate(
    input a,
    input b,
    output out
);

assign out = a & b;

endmodule

module or_gate(
    input a,
    input b,
    output out
);

assign out = a | b;

endmodule

module not_gate(
    input a,
    output out
);

