endmodule

module top_module(
    input clk,
    input a,
    input b,
    output out_always_ff
);

reg a_ff, b_ff;

always @(posedge clk) begin
    a_ff <= a;
    b_ff <= b;
end

xor_gate xor1(.a(a_ff), .b(b_ff), .out(out_always_ff));

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic a,
    input logic b,
    input logic out_always_ff
);
    ///// Functional correctness (registered XNOR of inputs) /////
    // Next cycle output equals XNOR of current inputs.
    check_out_is_xnor_of_inputs_next: assert property (
        @(posedge clk) 1'b1 |-> ##1 (out_always_ff == (a ~^ b))
    );

    // If inputs are equal now, next cycle output is 1.
    check_equal_inputs_imply_out1_next: assert property (
        @(posedge clk) (a == b) |-> ##1 (out_always_ff == 1'b1)
    );

    // If inputs differ now, next cycle output is 0.
    check_unequal_inputs_imply_out0_next: assert property (
        @(posedge clk) (a != b) |-> ##1 (out_always_ff == 1'b0)
    );

    // Alternative XNOR form: (~a & ~b) | (a & b) holds next cycle.
    check_xnor_alternative_expression_next: assert property (
        @(posedge clk) 1'b1 |-> ##1 (out_always_ff == ((~a & ~b) | (a & b)))
    );

    ///// Temporal consistency between input changes and output changes /////
    // If neither input changes this cycle, output is stable next cycle.
    check_no_input_change_keeps_output_stable_next: assert property (
        @(posedge clk) ($stable(a) && $stable(b)) |-> ##1 $stable(out_always_ff)
    );

    // If exactly one input changes this cycle, output changes next cycle.
    check_one_input_toggle_causes_output_toggle_next: assert property (
        @(posedge clk) ($onehot({$changed(a), $changed(b)})) |-> ##1 $changed(out_always_ff)
    );

    // If both inputs change this cycle, output is stable next cycle.
    check_both_inputs_toggle_keeps_output_stable_next: assert property (
        @(posedge clk) ($changed(a) && $changed(b)) |-> ##1 $stable(out_always_ff)
    );

    // If only a changes (b stable), output changes next cycle.
    check_a_toggle_only_causes_output_toggle_next: assert property (
        @(posedge clk) ($changed(a) && $stable(b)) |-> ##1 $changed(out_always_ff)
    );

    // If only b changes (a stable), output changes next cycle.
    check_b_toggle_only_causes_output_toggle_next: assert property (
        @(posedge clk) ($changed(b) && $stable(a)) |-> ##1 $changed(out_always_ff)
    );
endmodule

rtl:
module inc_module(
    input clk, reset, 
    input [2:0] SW, 
    output reg [3:0] LED
);

reg [2:0] SW_reg;
always @(posedge clk, posedge reset) begin
    if (reset) begin
        SW_reg <= 3'b0;
        LED <= 4'b0;
    end else begin
        SW_reg <= SW;
        LED <= SW_reg + 1;
    end
end

endmodule

sva:
module inc_module_sva (
    input logic clk,
    input logic reset,
    input logic [2:0] SW,
    input logic [3:0] LED
);
    // Clock: clk (posedge). Reset: reset (active-high, async). Sequential: LED <= prev(SW)+1 with 1-cycle latency.

    // While reset is asserted, LED is held at zero.
    check_reset_drives_led_zero: assert property (
        @(posedge clk) reset |-> (LED == 4'b0000)
    );

    // Out of reset, LED equals previous-cycle SW plus 1.
    check_led_from_prev_sw: assert property (
        @(posedge clk) disable iff (reset)
            !$past(reset) |-> (LED == ({1'b0, $past(SW)} + 4'd1))
    );

    // Out of reset, LED[0] toggles vs previous SW[0].
    check_led_lsb_toggle: assert property (
        @(posedge clk) disable iff (reset)
            !$past(reset) |-> (LED[0] == ~$past(SW[0]))
    );

    // Out of reset, LED[1] equals SW[1] XOR SW[0] from previous cycle.
    check_led_bit1_xor_prev: assert property (
        @(posedge clk) disable iff (reset)
            !$past(reset) |-> (LED[1] == ($past(SW[1]) ^ $past(SW[0])))
    );

    // Out of reset, LED[2] equals SW[2] XOR (SW[1] & SW[0]) from previous cycle.
    check_led_bit2_carry_logic: assert property (
        @(posedge clk) disable iff (reset)
            !$past(reset) |-> (LED[2] == ($past(SW[2]) ^ ($past(SW[1]) & $past(SW[0]))))
    );

    // Out of reset, LED[3] is the carry-out: SW[2] & SW[1] & SW[0] from previous cycle.
    check_led_msb_carry_from_prev: assert property (
        @(posedge clk) disable iff (reset)
            !$past(reset) |-> (LED[3] == ($past(SW[2]) & $past(SW[1]) & $past(SW[0])))
    );

    // Out of reset, LED is never zero (since it is prev(SW)+1).
    check_led_nonzero_out_of_reset: assert property (
        @(posedge clk) disable iff (reset)
            !$past(reset) |-> (LED != 4'd0)
    );

    // Out of reset, LED is in the range 1..8.
    check_led_in_range_out_of_reset: assert property (
        @(posedge clk) disable iff (reset)
            !$past(reset) |-> (LED inside {[4'd1:4'd8]})
    );

    // If SW was stable over the last two cycles (and not in reset), LED is stable this cycle.
    check_led_stable_when_sw_stable: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(reset) && !$past(reset,2) && ($past(SW) == $past(SW,2))) |-> (LED == $past(LED))
    );

    // If previous SW was 3'b111, LED[2:0] are zero (i.e., 8).
    check_led_lowbits_zero_on_overflow: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(reset) && (&$past(SW))) |-> (LED[2:0] == 3'b000)
    );
endmodule

rtl:
module Counter (
    input wire Clock,
    input wire Reset,
    input wire Enable,
    input wire [3:0] CountTo,
    output reg [3:0] CountValue,
    output reg CountFinished
);

    reg [3:0] nextCountValue;

    always @(*) begin
        if (CountValue == CountTo) begin
            CountFinished = 1;
            nextCountValue = 0;
        end else begin
            CountFinished = 0;
            nextCountValue = CountValue + 1;
        end
    end

    always @(posedge Clock) begin
        if (Reset) begin
            CountValue <= 0;
        end else if (Enable) begin
            CountValue <= nextCountValue;
        end
    end

endmodule

sva:
module Counter_sva (
    input logic Clock,
    input logic Reset,
    input logic Enable,
    input logic [3:0] CountTo,
    input logic [3:0] CountValue,
    input logic CountFinished
);
    ///// Functional relationship between outputs /////
    // CountFinished is high iff CountValue equals CountTo.
    check_countfinished_definition: assert property (
        @(posedge Clock) disable iff (Reset) (CountFinished == (CountValue == CountTo))
    );

    ///// Reset behavior /////
    // After a cycle with Reset high, CountValue becomes 0.
    check_reset_clears_countvalue: assert property (
        @(posedge Clock) disable iff (Reset) $past(Reset) |-> (CountValue == 4'd0)
    );

    // If both Reset and Enable were high last cycle, Reset takes precedence and CountValue is 0.
    check_reset_precedence_over_enable: assert property (
        @(posedge Clock) disable iff (Reset) ($past(Reset) && $past(Enable)) |-> (CountValue == 4'd0)
    );

    ///// Enable and hold behavior /////
    // When not Reset and not Enable, CountValue holds its previous value.
    check_hold_when_disabled: assert property (
        @(posedge Clock) disable iff (Reset) ($past(!Reset) && !$past(Enable)) |-> (CountValue == $past(CountValue))
    );

    // When enabled and previous CountValue != CountTo, CountValue increments by 1.
    check_increment_when_enabled_ne_equal: assert property (
        @(posedge Clock) disable iff (Reset)
            ($past(!Reset && Enable) && ($past(CountValue) != $past(CountTo))) |-> (CountValue == ($past(CountValue) + 4'd1))
    );

    // When enabled and previous CountValue == CountTo, CountValue wraps to 0.
    check_wrap_when_enabled_equal: assert property (
        @(posedge Clock) disable iff (Reset)
            ($past(!Reset && Enable) && ($past(CountValue) == $past(CountTo))) |-> (CountValue == 4'd0)
    );

    // A change in CountValue only occurs if prior Reset or Enable were asserted.
    check_changes_imply_enable_or_reset: assert property (
        @(posedge Clock) disable iff (Reset) (CountValue != $past(CountValue)) |-> ($past(Reset) || $past(Enable))
    );

    ///// Combinational stability consistency /////
    // If CountValue and CountTo are stable, CountFinished is stable (pure function).
    check_countfinished_stable_when_inputs_stable: assert property (
        @(posedge Clock) disable iff (Reset) ($stable(CountValue) && $stable(CountTo)) |-> $stable(CountFinished)
    );
endmodule

rtl:
module mux_2to1 (
    input [7:0] in1,
    input [7:0] in2,
    input sel,
    output [7:0] out
);

assign out = sel ? in2 : in1;

endmodule

sva:
module mux_2to1_sva (
    input logic clk,
    input logic [7:0] in1,
    input logic [7:0] in2,
    input logic sel,
    input logic [7:0] out
);
    // Out must equal the selected input every cycle.
    mapping_exact: assert property (
        @(posedge clk) out == (sel ? in2 : in1)
    );

    // When sel=0, out equals in1.
    sel0_selects_in1: assert property (
        @(posedge clk) !sel |-> (out == in1)
    );

    // When sel=1, out equals in2.
    sel1_selects_in2: assert property (
        @(posedge clk) sel |-> (out == in2)
    );

    // If in1==in2, out equals that value.
    equal_inputs_imply_out_equal: assert property (
        @(posedge clk) (in1 == in2) |-> (out == in1)
    );

    // When sel=0, changes on in2 do not change out.
    ignore_in2_when_sel0: assert property (
        @(posedge clk) (!sel && $changed(in2)) |-> $stable(out)
    );

    // When sel=1, changes on in1 do not change out.
    ignore_in1_when_sel1: assert property (
        @(posedge clk) (sel && $changed(in1)) |-> $stable(out)
    );

    // If sel and inputs are stable, out is stable.
    stable_inputs_keep_out_stable: assert property (
        @(posedge clk) $stable(sel) && $stable(in1) && $stable(in2) |-> $stable(out)
    );

    // Out changes only if sel or one of the inputs changes.
    out_change_has_cause: assert property (
        @(posedge clk) $changed(out) |-> ($changed(sel) || $changed(in1) || $changed(in2))
    );

    // Out equals one of the two inputs every cycle.
    out_is_one_of_inputs: assert property (
        @(posedge clk) (out == in1) || (out == in2)
    );
endmodule

rtl:
module number_in(
    input [31:0] num_a,
    input [31:0] num_b,
    input [31:0] result,
    input [4:0] code,
    input btnm,
    output reg [32:0] num_out
);

    reg [31:0] new;
    reg [6:0] i;
    reg [1:0] state;
    reg b_state;

    parameter [1:0] numA = 2'b00;
    parameter [1:0] numB = 2'b01;
    parameter [1:0] numC = 2'b10;

    initial state = 2'b00;
    initial b_state = 0;

    always @(*) begin
        if (btnm) begin
            if (~b_state) begin
                b_state = 1;
                case (state)
                    numA: if (code > 9 && code < 15) state = numB;
                    numB: if (code == 15) state = numC;
                    numC: if (code == 16) state = numA;
                    default: state = numA;
                endcase
            end
        end else begin
            b_state = 0;
        end
    end

    always @(state) begin
        case (state)
            numA: new = num_a;
            numB: new = num_b;
            numC: new = result;
            default: new = num_a;
        endcase
        if (new[31]) begin
            for (i = 0; i < 32; i = i + 1) begin
                num_out[i] = ~new[i];
            end
            num_out = num_out + 1'b1;
            num_out[32] = 1'b1;
        end else begin
            num_out = new;
        end
    end

endmodule

sva:
module number_in_sva (
    input  logic [31:0] num_a,
    input  logic [31:0] num_b,
    input  logic [31:0] result,
    input  logic [4:0]  code,
    input  logic        btnm,
    input  logic [32:0] num_out
);
    // No clock/reset in RTL; assertions sample on posedge of btnm.
    // Combinational logic with internal latch-like state; num_out is 33-bit signed-magnitude of selected input.

    function automatic logic [31:0] abs32 (input logic [31:0] x);
        abs32 = x[31] ? ((~x) + 32'd1) : x;
    endfunction

    function automatic logic [32:0] fmt33 (input logic [31:0] x);
        fmt33 = x[31] ? {1'b1, ((~x) + 32'd1)} : {1'b0, x};
    endfunction

    ///// Output selection and formatting /////
    // num_out must equal the formatted value of one of {num_a,num_b,result}.
    check_num_out_matches_one_formatted_input: assert property (
        @(posedge btnm) (num_out == fmt33(num_a)) || (num_out == fmt33(num_b)) || (num_out == fmt33(result))
    );

    // If all inputs are equal, num_out equals the formatted value of that input.
    check_all_equal_drives_formatted_value: assert property (
        @(posedge btnm) (num_a == num_b) && (num_b == result) |-> (num_out == fmt33(num_a))
    );

    // The lower 32 bits of num_out equal the absolute value of one of the inputs.
    check_lower_bits_are_abs_of_some_input: assert property (
        @(posedge btnm) (num_out[31:0] == abs32(num_a)) || (num_out[31:0] == abs32(num_b)) || (num_out[31:0] == abs32(result))
    );

    ///// Sign-bit consistency /////
    // If num_out sign is 1, at least one input must be negative.
    check_sign_implies_some_input_negative: assert property (
        @(posedge btnm) num_out[32] |-> (num_a[31] || num_b[31] || result[31])
    );

    // If all inputs are non-negative, num_out sign must be 0.
    check_all_nonneg_implies_sign_zero: assert property (
        @(posedge btnm) (!num_a[31] && !num_b[31] && !result[31]) |-> (num_out[32] == 1'b0)
    );

    // If all inputs are negative, num_out sign must be 1.
    check_all_neg_implies_sign_one: assert property (
        @(posedge btnm) (num_a[31] && num_b[31] && result[31]) |-> (num_out[32] == 1'b1)
    );

    // If num_out sign is 0, its value must match some non-negative input exactly.
    check_sign_zero_matches_some_nonneg_input: assert property (
        @(posedge btnm) (num_out[32] == 1'b0) |-> 
            ( (!num_a[31] && (num_out[31:0] == num_a)) ||
              (!num_b[31] && (num_out[31:0] == num_b)) ||
              (!result[31] && (num_out[31:0] == result)) )
    );

    // If num_out sign is 1, its magnitude must match the abs() of some negative input.
    check_sign_one_matches_abs_of_some_negative_input: assert property (
        @(posedge btnm) (num_out[32] == 1'b1) |-> 
            ( (num_a[31] && (num_out[31:0] == abs32(num_a))) ||
              (num_b[31] && (num_out[31:0] == abs32(num_b))) ||
              (result[31] && (num_out[31:0] == abs32(result))) )
    );

    ///// Corner cases /////
    // If all inputs are zero, output must be zero-extended zero.
    check_all_zero_inputs_zero_output: assert property (
        @(posedge btnm) (num_a == 32'd0) && (num_b == 32'd0) && (result == 32'd0) |-> (num_out == 33'd0)
    );

    // If all inputs are INT_MIN, output must be sign=1 and magnitude=INT_MIN.
    check_all_minint_outputs_minint_magnitude: assert property (
        @(posedge btnm) (num_a == 32'h8000_0000) && (num_b == 32'h8000_0000) && (result == 32'h8000_0000)
            |-> (num_out == {1'b1, 32'h8000_0000})
    );

    // If all inputs share the same absolute value, num_out magnitude equals that common absolute value.
    check_common_abs_magnitude: assert property (
        @(posedge btnm) (abs32(num_a) == abs32(num_b)) && (abs32(num_b) == abs32(result))
            |-> (num_out[31:0] == abs32(num_a))
    );

endmodule

rtl:
module comparator_3bit (
  input [2:0] A,
  input [2:0] B,
  output reg eq,
  output reg gt
);

  always @(*) begin
    if (A == B) begin
      eq = 1;
      gt = 0;
    end else if (A > B) begin
      eq = 0;
      gt = 1;
    end else begin
      eq = 0;
      gt = 0;
    end
  end

endmodule

sva:
module comparator_3bit_sva (
  input logic clk,          // Sampling clock for assertions (DUT has no clock/reset)
  input logic [2:0] A,
  input logic [2:0] B,
  input logic eq,
  input logic gt
);

  ///// Functional correctness /////
  // When A == B, eq=1 and gt=0.
  check_equal_case: assert property (
    @(posedge clk) (A == B) |-> (eq == 1'b1 && gt == 1'b0)
  );

  // When A > B, gt=1 and eq=0.
  check_greater_case: assert property (
    @(posedge clk) (A > B) |-> (gt == 1'b1 && eq == 1'b0)
  );

  // When A < B, eq=0 and gt=0.
  check_less_case: assert property (
    @(posedge clk) (A < B) |-> (eq == 1'b0 && gt == 1'b0)
  );

  // eq high implies A == B.
  check_eq_implies_equal: assert property (
    @(posedge clk) eq |-> (A == B)
  );

  // gt high implies A > B.
  check_gt_implies_greater: assert property (
    @(posedge clk) gt |-> (A > B)
  );

  // eq and gt are never both 1.
  check_outputs_mutex: assert property (
    @(posedge clk) !(eq && gt)
  );

  ///// Combinational consistency /////
  // If A and B are unchanged, eq and gt remain unchanged.
  check_stable_when_inputs_stable: assert property (
    @(posedge clk) ((A == $past(A)) && (B == $past(B))) |-> ((eq == $past(eq)) && (gt == $past(gt)))
  );

  // If eq or gt changes, then A or B must have changed.
  check_output_change_implies_input_change: assert property (
    @(posedge clk) ($changed(eq) || $changed(gt)) |-> ($changed(A) || $changed(B))
  );

endmodule

module my_register_sva (
    input logic clk,
    input logic ena,
    input logic d,
    input logic clrn, // active-low synchronous clear
    input logic prn,  // active-low synchronous preset
    input logic q
);

    ///// Reset behavior /////
    // When clear is asserted low, q must be 0 on the next clock.
    check_clear_forces_zero: assert property (
        @(posedge clk) (clrn == 1'b0) |=> (q == 1'b0)
    );

    // When preset is asserted low (and clear is high), q must be 1 on the next clock.
    check_preset_sets_one: assert property (
        @(posedge clk) (clrn == 1'b1 && prn == 1'b0) |=> (q == 1'b1)
    );

    // If both clear and preset are low, clear has priority and q must be 0 next clock.
    check_clear_overrides_preset: assert property (
        @(posedge clk) (clrn == 1'b0 && prn == 1'b0) |=> (q == 1'b0)
    );

    ///// Enable/hold behavior when no resets /////
    // With no resets and enable high, q loads d on the next clock.
    check_enable_loads_d_when_no_resets: assert property (
        @(posedge clk) disable iff (!clrn || !prn) (ena == 1'b1) |=> (q == $past(d))
    );

    // With no resets and enable low, q holds its previous value.
    check_hold_when_disabled_when_no_resets: assert property (
        @(posedge clk) disable iff (!clrn || !prn) (ena == 1'b0) |=> (q == $past(q))
    );

    // With no resets, any change in q must be caused by enable being high in the prior cycle.
    check_change_requires_enable_when_no_resets: assert property (
        @(posedge clk) disable iff (!clrn || !prn)
            ($past(clrn == 1'b1 && prn == 1'b1) && (q != $past(q))) |-> ($past(ena) == 1'b1)
    );

    // With no resets, the full next-state function matches: q_next = ena ? d : q.
    check_next_state_matches_spec_when_no_resets: assert property (
        @(posedge clk) disable iff (!clrn || !prn)
            1'b1 |=> (q == ($past(ena) ? $past(d) : $past(q)))
    );

endmodule

rtl:
module adder32(
  input [31:0] a,
  input [31:0] b,
  input cin,
  output [31:0] sum,
  output cout
);
  wire [15:0] a_low, b_low, sum_low;
  wire [15:0] a_high, b_high, sum_high;
  wire c1, c2;

  assign a_low = a[15:0];
  assign b_low = b[15:0];
  assign a_high = a[31:16];
  assign b_high = b[31:16];

  // Low 16-bit adder
  adder16 adder_low(
    .a(a_low),
    .b(b_low),
    .cin(cin),
    .sum(sum_low),
    .cout(c1)
  );

  // High 16-bit adder
  adder16 adder_high(
    .a(a_high),
    .b(b_high),
    .cin(c1),
    .sum(sum_high),
    .cout(c2)
  );

  // Final 32-bit sum
  assign sum = {sum_high, sum_low};
  assign cout = c2;
endmodule
module adder16(
  input [15:0] a,
  input [15:0] b,
  input cin,
  output [15:0] sum,
  output cout
);
  wire [15:0] sum_temp;

  assign {cout, sum_temp} = a + b + cin;
  assign sum = sum_temp;
endmodule
module top_module(
  input [31:0] a,
  input [31:0] b,
  output [31:0] sum
);
  wire cin;
  wire cout;

  // Carry select adder
  adder32 adder(
    .a(a),
    .b(b),
    .cin(cin),
    .sum(sum),
    .cout(cout)
  );

  assign cin = 1'b0;
endmodule

sva:
module adder32_sva (
    input logic CLK,
    input logic [31:0] a,
    input logic [31:0] b,
    input logic cin,
    input logic [31:0] sum,
    input logic cout,
    input logic [15:0] a_low,
    input logic [15:0] b_low,
    input logic [15:0] sum_low,
    input logic [15:0] a_high,
    input logic [15:0] b_high,
    input logic [15:0] sum_high,
    input logic c1,
    input logic c2
);
    // a_low is the low 16 bits of a.
    check_a_low_slice: assert property (
        @(posedge CLK) a_low == a[15:0]
    );
    // b_low is the low 16 bits of b.
    check_b_low_slice: assert property (
        @(posedge CLK) b_low == b[15:0]
    );
    // a_high is the high 16 bits of a.
    check_a_high_slice: assert property (
        @(posedge CLK) a_high == a[31:16]
    );
    // b_high is the high 16 bits of b.
    check_b_high_slice: assert property (
        @(posedge CLK) b_high == b[31:16]
    );
    // Low 16-bit adder computes sum_low and carry c1.
    check_low_adder_function: assert property (
        @(posedge CLK) {c1, sum_low} == ({1'b0, a_low} + {1'b0, b_low} + cin)
    );
    // High 16-bit adder computes sum_high and carry c2 using c1 as carry-in.
    check_high_adder_function: assert property (
        @(posedge CLK) {c2, sum_high} == ({1'b0, a_high} + {1'b0, b_high} + c1)
    );
    // 32-bit sum is the concatenation of high and low sums.
    check_sum_concat: assert property (
        @(posedge CLK) sum == {sum_high, sum_low}
    );
    // cout equals the final carry c2.
    check_cout_equals_c2: assert property (
        @(posedge CLK) cout == c2
    );
    // sum_low matches low 16 bits of sum.
    check_sum_low_slice_match: assert property (
        @(posedge CLK) sum_low == sum[15:0]
    );
    // sum_high matches high 16 bits of sum.
    check_sum_high_slice_match: assert property (
        @(posedge CLK) sum_high == sum[31:16]
    );
    // Full 33-bit result equals a + b + cin.
    check_full_width_sum: assert property (
        @(posedge CLK) {cout, sum} == ({1'b0, a} + {1'b0, b} + cin)
    );
endmodule

rtl:
module First_Phase_M_W32 (clk, rst, load, Data_MX, Data_MY, Op_MX, Op_MY);
  input [31:0] Data_MX;
  input [31:0] Data_MY;
  output [31:0] Op_MX;
  output [31:0] Op_MY;
  input clk, rst, load;
  wire n1;

  RegisterMult_W32 XMRegister (.clk(clk), .rst(rst), .load(n1), .D(Data_MX), .Q(Op_MX));
  RegisterMult_W32 YMRegister (.clk(clk), .rst(rst), .load(n1), .D(Data_MY), .Q(Op_MY));
  CLKBUFX2TS U1 (.A(load), .Y(n1));
endmodule

module RegisterMult_W32 (clk, rst, load, D, Q);
  input clk, rst, load;
  input [31:0] D;
  output reg [31:0] Q;

  always @(posedge clk) begin
    if (rst) begin
      Q <= 32'h0;
    end else if (load) begin
      Q <= D;
    end
  end
endmodule

module CLKBUFX2TS (A, Y);
  input A;
  output Y;

  assign Y = A;
endmodule

sva:
module First_Phase_M_W32_sva (
    input logic clk,
    input logic rst,
    input logic load,
    input logic [31:0] Data_MX,
    input logic [31:0] Data_MY,
    input logic [31:0] Op_MX,
    input logic [31:0] Op_MY
);
    ///// Reset behavior (active-high synchronous) /////
    // If rst is HIGH at a clock edge, outputs are zero on the next cycle.
    reset_clears_outputs_next: assert property (
        @(posedge clk) rst |=> (Op_MX == 32'h0) && (Op_MY == 32'h0)
    );
    // While rst is held HIGH for 2+ cycles, outputs remain zero.
    reset_holds_zero: assert property (
        @(posedge clk) (rst && $past(rst)) |-> (Op_MX == 32'h0) && (Op_MY == 32'h0)
    );

    ///// Load/capture behavior /////
    // With load HIGH and not in reset, Op_MX captures Data_MX on the next cycle.
    capture_mx_on_load: assert property (
        @(posedge clk) disable iff (rst) load |=> (Op_MX == $past(Data_MX))
    );
    // With load HIGH and not in reset, Op_MY captures Data_MY on the next cycle.
    capture_my_on_load: assert property (
        @(posedge clk) disable iff (rst) load |=> (Op_MY == $past(Data_MY))
    );

    ///// Hold behavior when not loading /////
    // With load LOW and not in reset, Op_MX holds its previous value.
    hold_mx_without_load: assert property (
        @(posedge clk) disable iff (rst) !load |=> (Op_MX == $past(Op_MX))
    );
    // With load LOW and not in reset, Op_MY holds its previous value.
    hold_my_without_load: assert property (
        @(posedge clk) disable iff (rst) !load |=> (Op_MY == $past(Op_MY))
    );

    ///// Change qualification /////
    // Any change on Op_MX must be caused by prior load or prior reset.
    mx_change_requires_prior_load_or_reset: assert property (
        @(posedge clk) disable iff (rst) (Op_MX != $past(Op_MX)) |-> ($past(load) || $past(rst))
    );
    // Any change on Op_MY must be caused by prior load or prior reset.
    my_change_requires_prior_load_or_reset: assert property (
        @(posedge clk) disable iff (rst) (Op_MY != $past(Op_MY)) |-> ($past(load) || $past(rst))
    );

    ///// Behavior around reset release /////
    // On the cycle after reset (previous cycle rst=1) with no load, outputs remain zero.
    release_reset_no_load_keeps_zero: assert property (
        @(posedge clk) disable iff (rst) ($past(rst) && !load) |-> (Op_MX == 32'h0) && (Op_MY == 32'h0)
    );
    // On the cycle after reset (previous cycle rst=1) with load HIGH, next outputs capture current data.
    release_reset_with_load_captures_data: assert property (
        @(posedge clk) disable iff (rst) ($past(rst) && load) |=> (Op_MX == $past(Data_MX)) && (Op_MY == $past(Data_MY))
    );
endmodule

rtl:
module counter_3bit_async_reset(
    input clk,
    input rst,
    output reg [2:0] count
);

always @(posedge clk or negedge rst) begin
    if (!rst) begin
        count <= 3'b0;
    end else begin
        count <= count + 1;
    end
end

endmodule

sva:
module counter_3bit_async_reset_sva (
    input logic clk,
    input logic rst,
    input logic [2:0] count
);
    ///// Reset behavior /////
    // When reset is asserted LOW at a clock edge, count is forced to 0.
    check_reset_forces_zero: assert property (
        @(posedge clk) !rst |-> (count == 3'd0)
    );

    // While reset remains LOW across consecutive cycles, count holds at 0 (stable).
    check_reset_held_low_stable: assert property (
        @(posedge clk) ($past(1'b1) && !rst && $past(!rst)) |-> ($stable(count) && (count == 3'd0))
    );

    // On the first clock after reset deasserts (LOW->HIGH across clocks), count becomes 1.
    check_release_to_one: assert property (
        @(posedge clk) disable iff (!rst) ($past(1'b1) && $past(!rst) && rst) |-> (count == 3'd1)
    );

    // If the previous cycle had reset LOW, then the previous count was 0.
    check_prev_cycle_reset_count_zero: assert property (
        @(posedge clk) ($past(1'b1) && $past(!rst)) |-> ($past(count) == 3'd0)
    );

    // From a cycle with reset LOW, the next cycle's count is 0 if reset stays LOW, else 1 if reset goes HIGH.
    check_next_cycle_after_reset: assert property (
        @(posedge clk) !rst |-> ##1 ((rst && (count == 3'd1)) || (!rst && (count == 3'd0)))
    );

    // When not in reset and count is 0 at a clock edge, it must be due to wrap from 7.
    check_wrap_to_zero_requires_prev_seven: assert property (
        @(posedge clk) disable iff (!rst) ($past(1'b1) && rst && (count == 3'd0)) |-> ($past(count) == 3'd7)
    );
endmodule

rtl:
module next_state_logic (
  input x,
  input [2:0] y,
  output Y2
);

reg Y2;

always @(*) begin
  case (y)
    3'b000: Y2 = x;
    3'b001: Y2 = 0;
    3'b010: Y2 = x;
    3'b011: Y2 = 1;
    3'b100: Y2 = 1;
    3'b101: Y2 = x;
    default: Y2 = 0;
  endcase
end

endmodule

sva:
module next_state_logic_sva (
    input logic x,
    input logic [2:0] y,
    input logic Y2
);
    // For y==000, Y2 must equal x.
    check_y000_maps_to_x: assert property (
        @(posedge x) (y == 3'b000) |-> (Y2 == x)
    );

    // For y==001, Y2 must be 0.
    check_y001_maps_to_0: assert property (
        @(posedge x) (y == 3'b001) |-> (Y2 == 1'b0)
    );

    // For y==010, Y2 must equal x.
    check_y010_maps_to_x: assert property (
        @(posedge x) (y == 3'b010) |-> (Y2 == x)
    );

    // For y==011, Y2 must be 1.
    check_y011_maps_to_1: assert property (
        @(posedge x) (y == 3'b011) |-> (Y2 == 1'b1)
    );

    // For y==100, Y2 must be 1.
    check_y100_maps_to_1: assert property (
        @(posedge x) (y == 3'b100) |-> (Y2 == 1'b1)
    );

    // For y==101, Y2 must equal x.
    check_y101_maps_to_x: assert property (
        @(posedge x) (y == 3'b101) |-> (Y2 == x)
    );

    // For y==110, Y2 must be 0 (default case).
    check_y110_maps_to_0: assert property (
        @(posedge x) (y == 3'b110) |-> (Y2 == 1'b0)
    );

    // For y==111, Y2 must be 0 (default case).
    check_y111_maps_to_0: assert property (
        @(posedge x) (y == 3'b111) |-> (Y2 == 1'b0)
    );
endmodule

rtl:
module delay_gate(
    input A,
    input reset,
    output reg X,
    input clk
);

    reg [3:0] delay_reg;

    always @(posedge clk) begin
        if (reset) begin
            delay_reg <= 0;
            X <= 0;
        end else begin
            delay_reg <= {delay_reg[2:0], A};
            X <= delay_reg[3];
        end
    end

endmodule

sva:
module delay_gate_sva (
    input logic A,
    input logic reset,      // synchronous active-high reset
    input logic X,
    input logic clk,
    input logic [3:0] delay_reg
);
    // During reset, X and delay_reg are cleared on the next clock.
    check_reset_clears_next: assert property (
        @(posedge clk) reset |=> (delay_reg == 4'b0000) && (X == 1'b0)
    );

    // On non-reset cycles (looking back one cycle), delay_reg shifts A into LSB.
    check_shift_vector_update: assert property (
        @(posedge clk) disable iff (reset) $past(!reset) |-> (delay_reg == { $past(delay_reg[2:0]), $past(A) })
    );

    // MSB gets previous bit[2] on non-reset cycles.
    check_bit3_shifts_from_bit2: assert property (
        @(posedge clk) disable iff (reset) $past(!reset) |-> (delay_reg[3] == $past(delay_reg[2]))
    );

    // bit[2] gets previous bit[1] on non-reset cycles.
    check_bit2_shifts_from_bit1: assert property (
        @(posedge clk) disable iff (reset) $past(!reset) |-> (delay_reg[2] == $past(delay_reg[1]))
    );

    // bit[1] gets previous bit[0] on non-reset cycles.
    check_bit1_shifts_from_bit0: assert property (
        @(posedge clk) disable iff (reset) $past(!reset) |-> (delay_reg[1] == $past(delay_reg[0]))
    );

    // LSB gets previous A on non-reset cycles.
    check_lsb_captures_A: assert property (
        @(posedge clk) disable iff (reset) $past(!reset) |-> (delay_reg[0] == $past(A))
    );

    // X gets previous delay_reg[3] on non-reset cycles.
    check_x_tracks_prev_msb: assert property (
        @(posedge clk) disable iff (reset) $past(!reset) |-> (X == $past(delay_reg[3]))
    );

    // With 4 consecutive non-reset cycles, X equals A from 4 cycles ago.
    check_x_four_cycle_delay: assert property (
        @(posedge clk) disable iff (reset)
            ($past(!reset,1) && $past(!reset,2) && $past(!reset,3) && $past(!reset,4))
            |-> (X == $past(A,4))
    );

    // After reset deasserts, X remains 0 for four cycles.
    check_x_zero_after_reset_fall: assert property (
        @(posedge clk) disable iff (reset) $fell(reset) |-> (X == 1'b0)[*4]
    );

    // After reset deasserts, delay_reg[3] remains 0 for three cycles.
    check_msb_zero_three_after_reset_fall: assert property (
        @(posedge clk) disable iff (reset) $fell(reset) |-> (delay_reg[3] == 1'b0)[*3]
    );
endmodule

rtl:
module logic_operation (
    output Y,
    input  A,
    input  B,
    input  C,
    input  D
);

    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    // Implement AND gates
    wire AB;
    wire CD;
    and (AB, A, B);
    and (CD, C, D);

    // Implement OR gate
    or (Y, AB, CD);

endmodule

sva:
module logic_operation_sva (
    input  logic clk, // sampling clock for assertions
    input  logic Y,
    input  logic A,
    input  logic B,
    input  logic C,
    input  logic D
);
    // DUT is pure combinational: Y == (A & B) | (C & D); no reset present.

    // Y equals (A&B)|(C&D) every sampled cycle.
    check_functional_equivalence: assert property (
        @(posedge clk) Y == ((A && B) || (C && D))
    );

    // If A and B are both HIGH, Y must be HIGH the same cycle.
    check_y_high_when_ab_true: assert property (
        @(posedge clk) (A && B) |-> (Y == 1'b1)
    );

    // If C and D are both HIGH, Y must be HIGH the same cycle.
    check_y_high_when_cd_true: assert property (
        @(posedge clk) (C && D) |-> (Y == 1'b1)
    );

    // If neither pair (A&B) nor (C&D) is HIGH, Y must be LOW.
    check_y_low_when_no_pair_true: assert property (
        @(posedge clk) (!(A && B) && !(C && D)) |-> (Y == 1'b0)
    );

    // If Y is HIGH, at least one pair (A&B) or (C&D) must be HIGH.
    check_y_high_implies_pair_true: assert property (
        @(posedge clk) (Y == 1'b1) |-> ((A && B) || (C && D))
    );

    // If Y is LOW, neither (A&B) nor (C&D) is HIGH.
    check_y_low_implies_no_pair_true: assert property (
        @(posedge clk) (Y == 1'b0) |-> (!(A && B) && !(C && D))
    );
endmodule

rtl:
module bitwise_and_module(
    input wire A1,
    input wire A2,
    input wire B1,
    output wire X
);

    assign X = A1 & A2 & B1;

endmodule

sva:
module bitwise_and_module_sva (
    input logic A1,
    input logic A2,
    input logic B1,
    input logic X
);
    // X equals A1 & A2 & B1 on any input transition.
    check_and_equation_on_input_edges: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge B1 or negedge B1)
        (X == (A1 & A2 & B1))
    );

    // X equals A1 & A2 & B1 whenever X toggles.
    check_and_equation_on_output_edges: assert property (
        @(posedge X or negedge X)
        (X == (A1 & A2 & B1))
    );

    // X rising implies all inputs are HIGH.
    check_x_rise_requires_all_inputs_high: assert property (
        @(posedge X)
        (A1 && A2 && B1)
    );

    // X falling implies at least one input is LOW.
    check_x_fall_requires_some_input_low: assert property (
        @(negedge X)
        (!A1 || !A2 || !B1)
    );

    // If A1 is LOW, X must be LOW (sampled on A1 edges).
    check_a1_low_forces_x_low: assert property (
        @(posedge A1 or negedge A1)
        (A1 == 1'b0) |-> (X == 1'b0)
    );

    // If A2 is LOW, X must be LOW (sampled on A2 edges).
    check_a2_low_forces_x_low: assert property (
        @(posedge A2 or negedge A2)
        (A2 == 1'b0) |-> (X == 1'b0)
    );

    // If B1 is LOW, X must be LOW (sampled on B1 edges).
    check_b1_low_forces_x_low: assert property (
        @(posedge B1 or negedge B1)
        (B1 == 1'b0) |-> (X == 1'b0)
    );

    // If all inputs are HIGH, X must be HIGH (on any input edge).
    check_all_high_implies_x_high: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge B1 or negedge B1)
        (A1 && A2 && B1) |-> (X == 1'b1)
    );
endmodule

rtl:
module jk_flip_flop(
    input clk, // Clock
    input clr_n, // Active low, asynchronous reset
    input j, // J input
    input k, // K input
    output reg q, // Output
    output q_n // Inverted output
);

// Look at the falling edge of clock for state transitions
always @(negedge clk or negedge clr_n) begin
    if (~clr_n) begin
        // This is the reset condition. Most synthesis tools
        // require an asynchronous reset to be defined this
        // way.
        q <= 1'b0;
    end
    else begin
        case ({j,k})
            2'b00: q <= q; // HOLD
            2'b01: q <= 1'b0; // RESET
            2'b10: q <= 1'b1; // SET
            2'b11: q <= ~q; // TOGGLE
        endcase
    end
end

// Assign statements
assign q_n = ~q;

endmodule

sva:
module jk_flip_flop_sva (
    input logic clk,
    input logic clr_n,
    input logic j,
    input logic k,
    input logic q,
    input logic q_n
);
    ///// Basic reset and inversion rules /////
    // When reset is asserted (active low), q must be 0 and q_n must be 1.
    check_reset_forces_outputs: assert property (
        @(negedge clk) (!clr_n) |-> (q == 1'b0) && (q_n == 1'b1)
    );
    // q_n is always the logical inverse of q when not in reset.
    check_qn_complement_nonreset_negedge: assert property (
        @(negedge clk) disable iff (!clr_n) (q_n == ~q)
    );
    // q_n is always the logical inverse of q on the rising edge as well (not in reset).
    check_qn_complement_nonreset_posedge: assert property (
        @(posedge clk) disable iff (!clr_n) (q_n == ~q)
    );
    // q_n remains the logical inverse of q even during reset.
    check_qn_complement_during_reset: assert property (
        @(negedge clk) (!clr_n) |-> (q_n == ~q)
    );

    ///// Asynchronous reset dominance across edges /////
    // If the previous edge was in reset, q must be 0 at this edge (before state update).
    check_q_zero_after_prev_reset: assert property (
        @(negedge clk) disable iff (!clr_n) $past(!clr_n) |-> (q == 1'b0)
    );

    ///// JK next-state behavior sampled on negedge /////
    // If previous edge had J=0,K=0 (and was not in reset), q holds its value.
    check_jk_hold_on_00: assert property (
        @(negedge clk) disable iff (!clr_n)
            $past(clr_n) && ($past(j) == 1'b0) && ($past(k) == 1'b0) |-> (q == $past(q))
    );
    // If previous edge had J=0,K=1 (and was not in reset), q goes to 0.
    check_jk_reset_on_01: assert property (
        @(negedge clk) disable iff (!clr_n)
            $past(clr_n) && ($past(j) == 1'b0) && ($past(k) == 1'b1) |-> (q == 1'b0)
    );
    // If previous edge had J=1,K=0 (and was not in reset), q goes to 1.
    check_jk_set_on_10: assert property (
        @(negedge clk) disable iff (!clr_n)
            $past(clr_n) && ($past(j) == 1'b1) && ($past(k) == 1'b0) |-> (q == 1'b1)
    );
    // If previous edge had J=1,K=1 (and was not in reset), q toggles.
    check_jk_toggle_on_11: assert property (
        @(negedge clk) disable iff (!clr_n)
            $past(clr_n) && ($past(j) == 1'b1) && ($past(k) == 1'b1) |-> (q == ~$past(q))
    );
    // Two consecutive toggle commands (with no resets on those edges) restore q to its original value.
    check_double_toggle_restores: assert property (
        @(negedge clk) disable iff (!clr_n)
            $past(clr_n,2) && $past(clr_n,1) &&
            ($past(j,2) == 1'b1) && ($past(k,2) == 1'b1) &&
            ($past(j,1) == 1'b1) && ($past(k,1) == 1'b1) |-> (q == $past(q,2))
    );
endmodule

rtl:
module highest_16_bits (
  input [31:0] in,
  input [3:0] control,
  output reg [15:0] out
);

  always @(*) begin
    case (control)
      0: out = 16'b0;
      1: out = in[31:16];
      2: out = in[15:0];
      3: out = in[31:16] >> 16;
      4: out = in[15:0] >> 16;
      5: out = in[31:16] >> 16;
      6: out = in[15:0] >> 16;
      default: out = 16'b0;
    endcase
  end

endmodule

sva:
module highest_16_bits_sva (
  input logic clk,               // Assertion clock (RTL has no clock/reset)
  input logic [31:0] in,
  input logic [3:0] control,
  input logic [15:0] out
);
  // Analysis: combinational case logic; control=1 -> in[31:16], control=2 -> in[15:0], others -> 0.

  // Out matches the exact combinational mapping for all control values.
  check_functional_mapping_exact: assert property (
    @(posedge clk) out == (control == 4'd1 ? in[31+:16] :
                           control == 4'd2 ? in[0+:16]  :
                           16'b0)
  );

  // control==0 drives zero.
  check_control0_zero: assert property (
    @(posedge clk) (control == 4'd0) |-> (out == 16'b0)
  );

  // control==1 selects upper 16 bits.
  check_control1_upper: assert property (
    @(posedge clk) (control == 4'd1) |-> (out == in[31:16])
  );

  // control==2 selects lower 16 bits.
  check_control2_lower: assert property (
    @(posedge clk) (control == 4'd2) |-> (out == in[15:0])
  );

  // control==3 drives zero (shift of 16 by 16 is zero).
  check_control3_zero: assert property (
    @(posedge clk) (control == 4'd3) |-> (out == 16'b0)
  );

  // control==4 drives zero (shift of 16 by 16 is zero).
  check_control4_zero: assert property (
    @(posedge clk) (control == 4'd4) |-> (out == 16'b0)
  );

  // control==5 drives zero (shift of 16 by 16 is zero).
  check_control5_zero: assert property (
    @(posedge clk) (control == 4'd5) |-> (out == 16'b0)
  );

  // control==6 drives zero (shift of 16 by 16 is zero).
  check_control6_zero: assert property (
    @(posedge clk) (control == 4'd6) |-> (out == 16'b0)
  );

  // control in 7..15 hits default and drives zero.
  check_default_zero_range: assert property (
    @(posedge clk) (control inside {[4'd7:4'd15]}) |-> (out == 16'b0)
  );

  // If inputs are stable, output remains stable (combinational behavior).
  check_stability_when_inputs_stable: assert property (
    @(posedge clk) $stable({in, control}) |-> $stable(out)
  );

endmodule

rtl:
module ripple_carry_adder(
  input [3:0] A,
  input [3:0] B,
  input Cin,
  output [3:0] Sum,
  output Cout
);

  wire [3:0] carry;

  // full adder for bit 0
  full_adder fa0(A[0], B[0], Cin, Sum[0], carry[0]);

  // full adders for bits 1-3
  full_adder fa1(A[1], B[1], carry[0], Sum[1], carry[1]);
  full_adder fa2(A[2], B[2], carry[1], Sum[2], carry[2]);
  full_adder fa3(A[3], B[3], carry[2], Sum[3], Cout);

endmodule

module full_adder(
  input A,
  input B,
  input Cin,
  output Sum,
  output Cout
);

  assign Sum = A ^ B ^ Cin;
  assign Cout = (A & B) | (Cin & (A ^ B));

endmodule

sva:
module ripple_carry_adder_sva(
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic Cin,
    input logic [3:0] Sum,
    input logic Cout
);
    // Overall 5-bit result equals A + B + Cin.
    check_total_sum_matches_addition: assert property (
        @(posedge clk) {Cout, Sum} == (A + B + Cin)
    );

    // LSB sum equals A[0] XOR B[0] XOR Cin.
    check_sum_bit0_xor: assert property (
        @(posedge clk) Sum[0] == (A[0] ^ B[0] ^ Cin)
    );

    // Bit1 sum equals XOR with carry from bit0.
    check_sum_bit1_from_carry0: assert property (
        @(posedge clk) Sum[1] == (
            A[1] ^ B[1] ^ ( (A[0] & B[0]) | ( Cin & (A[0] ^ B[0]) ) )
        )
    );

    // Bit2 sum equals XOR with carry from bit1.
    check_sum_bit2_from_carry1: assert property (
        @(posedge clk) Sum[2] == (
            A[2] ^ B[2] ^ (
                (A[1] & B[1]) |
                ( ((A[0] & B[0]) | ( Cin & (A[0] ^ B[0]) )) & (A[1] ^ B[1]) )
            )
        )
    );

    // Bit3 sum equals XOR with carry from bit2.
    check_sum_bit3_from_carry2: assert property (
        @(posedge clk) Sum[3] == (
            A[3] ^ B[3] ^ (
                (A[2] & B[2]) |
                ( ((A[1] & B[1]) | ( ((A[0] & B[0]) | ( Cin & (A[0] ^ B[0]) )) & (A[1] ^ B[1]) )) & (A[2] ^ B[2]) )
            )
        )
    );

    // Final carry-out equals generate/propagate from bit3.
    check_cout_from_carry2: assert property (
        @(posedge clk) Cout == (
            (A[3] & B[3]) |
            ( (
                (A[2] & B[2]) |
                ( ((A[1] & B[1]) | ( ((A[0] & B[0]) | ( Cin & (A[0] ^ B[0]) )) & (A[1] ^ B[1]) )) & (A[2] ^ B[2]) )
            ) & (A[3] ^ B[3]) )
        )
    );

    // Lower 2 sum bits match 2-bit addition of A,B and Cin.
    check_lower2bits_addition: assert property (
        @(posedge clk) Sum[1:0] == (A[1:0] + B[1:0] + Cin)[1:0]
    );

    // Lower 3 sum bits match 3-bit addition of A,B and Cin.
    check_lower3bits_addition: assert property (
        @(posedge clk) Sum[2:0] == (A[2:0] + B[2:0] + Cin)[2:0]
    );

    // Outputs do not change when inputs are stable.
    check_outputs_stable_when_inputs_stable: assert property (
        @(posedge clk) $stable({A,B,Cin}) |-> $stable({Sum,Cout})
    );

    // When B=0 and Cin=0, output equals A and Cout=0.
    check_identity_B_zero_Cin_zero: assert property (
        @(posedge clk) ((B == 4'b0000) && (Cin == 1'b0)) |-> ((Sum == A) && (Cout == 1'b0))
    );
endmodule

