module sky130_fd_sc_ls__a221o (
    X ,
    A1,
    A2,
    B1,
    B2,
    C1
);

    output X ;
    input  A1;
    input  A2;
    input  B1;
    input  B2;
    input  C1;

    assign X = ((A1 & A2 & C1) | (B1 & B2 & C1));

endmodule

sva:
module sky130_fd_sc_ls__a221o_sva (
    input  logic clk,
    input  logic X,
    input  logic A1,
    input  logic A2,
    input  logic B1,
    input  logic B2,
    input  logic C1
);
    ///// Functional correctness /////
    // X must equal (A1 & A2 & C1) | (B1 & B2 & C1).
    check_functional_equivalence: assert property (
        @(posedge clk) X == ((A1 && A2 && C1) || (B1 && B2 && C1))
    );

    // When C1 is LOW, X must be LOW.
    check_c1_low_forces_x0: assert property (
        @(posedge clk) (C1 == 1'b0) |-> (X == 1'b0)
    );

    // A-path alone (A1&A2 with C1) is sufficient to drive X HIGH.
    check_a_path_sufficient: assert property (
        @(posedge clk) (A1 && A2 && C1) |-> (X == 1'b1)
    );

    // B-path alone (B1&B2 with C1) is sufficient to drive X HIGH.
    check_b_path_sufficient: assert property (
        @(posedge clk) (B1 && B2 && C1) |-> (X == 1'b1)
    );

    // If X is HIGH, C1 must be HIGH.
    check_x_high_requires_c1: assert property (
        @(posedge clk) (X == 1'b1) |-> (C1 == 1'b1)
    );

    // If X is HIGH, at least one of (A1&A2) or (B1&B2) must be HIGH.
    check_x_high_requires_some_pair: assert property (
        @(posedge clk) (X == 1'b1) |-> ((A1 && A2) || (B1 && B2))
    );

    // If C1 is HIGH and neither pair is HIGH, then X must be LOW.
    check_x_low_when_c1_high_and_no_pairs: assert property (
        @(posedge clk) (C1 && !(A1 && A2) && !(B1 && B2)) |-> (X == 1'b0)
    );

    // If both pairs and C1 are HIGH, X must be HIGH.
    check_both_pairs_and_c1_high: assert property (
        @(posedge clk) (C1 && (A1 && A2) && (B1 && B2)) |-> (X == 1'b1)
    );
endmodule

module dff_sva (
    input logic DATAIN,
    input logic CLK,
    input logic ACLR,
    input logic ENA,
    input logic SCLR,
    input logic SLOAD,
    input logic SDATA,
    input logic Q
);
    // Asynchronous clear holds Q low while asserted.
    check_async_clear_forces_zero: assert property (
        @(posedge CLK) !ACLR |-> (Q == 1'b0)
    );

    // With ENA high and SCLR high, Q synchronously clears to 0.
    check_sync_clear_when_enabled: assert property (
        @(posedge CLK) disable iff (!ACLR) (ENA && SCLR) |-> (Q == 1'b0)
    );

    // With ENA high, SCLR low, and SLOAD high, Q loads SDATA.
    check_sync_load_when_enabled: assert property (
        @(posedge CLK) disable iff (!ACLR) (ENA && !SCLR && SLOAD) |-> (Q == SDATA)
    );

    // With ENA high and both SCLR and SLOAD low, Q captures DATAIN.
    check_data_capture_when_enabled: assert property (
        @(posedge CLK) disable iff (!ACLR) (ENA && !SCLR && !SLOAD) |-> (Q == DATAIN)
    );

    // When enabled and not synchronously cleared, Q equals SLOAD ? SDATA : DATAIN.
    check_combined_mux_behavior: assert property (
        @(posedge CLK) disable iff (!ACLR) (ENA && !SCLR) |-> (Q == (SLOAD ? SDATA : DATAIN))
    );

    // Synchronous clear has priority over SLOAD when both are high.
    check_sclr_overrides_sload: assert property (
        @(posedge CLK) disable iff (!ACLR) (ENA && SCLR && SLOAD) |-> (Q == 1'b0)
    );

    // When enabled, Q equals (SCLR ? 0 : (SLOAD ? SDATA : DATAIN)).
    check_full_case_when_enabled: assert property (
        @(posedge CLK) disable iff (!ACLR) ENA |-> (Q == (SCLR ? 1'b0 : (SLOAD ? SDATA : DATAIN)))
    );
endmodule

