module my_or3b_4 (
    input A,
    input B,
    input C_N,
    output X
);

    wire AB, AB_C_N, A_C_N, B_C_N;

    assign AB = A | B;
    assign AB_C_N = AB | C_N;
    assign A_C_N = A | C_N;
    assign B_C_N = B | C_N;

    assign X = AB_C_N & A_C_N & B_C_N;

endmodule

sva:
module my_or3b_4_sva (
    input logic CLK,
    input logic A,
    input logic B,
    input logic C_N,
    input logic X
);
    // X equals the structural expression implemented in RTL.
    check_structural_equivalence: assert property (
        @(posedge CLK) X == ((A | B | C_N) & (A | C_N) & (B | C_N))
    );

    // X equals the simplified boolean form C_N | (A & B).
    check_simplified_equivalence: assert property (
        @(posedge CLK) X == (C_N | (A & B))
    );

    // When C_N is 1, X must be 1.
    check_cn_dominates: assert property (
        @(posedge CLK) C_N |-> (X == 1'b1)
    );

    // When C_N is 0, X must equal A & B.
    check_cn0_means_and: assert property (
        @(posedge CLK) (!C_N) |-> (X == (A & B))
    );

    // When C_N is 0 and A is 0, X must be 0.
    check_cn0_a0_forces_x0: assert property (
        @(posedge CLK) (!C_N && !A) |-> (X == 1'b0)
    );

    // When C_N is 0 and B is 0, X must be 0.
    check_cn0_b0_forces_x0: assert property (
        @(posedge CLK) (!C_N && !B) |-> (X == 1'b0)
    );

    // When both A and B are 1, X must be 1.
    check_ab_high_implies_x1: assert property (
        @(posedge CLK) (A && B) |-> (X == 1'b1)
    );

    // If X is 1, then at least one of A, B, or C_N is 1.
    check_x_implies_any_input_or_cn: assert property (
        @(posedge CLK) X |-> (A | B | C_N)
    );

    // If X is 1, then A or C_N must be 1.
    check_x_implies_a_or_cn: assert property (
        @(posedge CLK) X |-> (A | C_N)
    );

    // If X is 1, then B or C_N must be 1.
    check_x_implies_b_or_cn: assert property (
        @(posedge CLK) X |-> (B | C_N)
    );
endmodule

rtl:
module sky130_fd_sc_hdll__xor2b (
    input  A,
    input  B,
    input  C,
    output X
);

    wire  A_xor_B;
    wire  A_or_B;

    assign A_xor_B = A ^ B;
    assign A_or_B  = A | B;

    assign X = (C == 1'b1) ? A_xor_B : A_or_B;

endmodule

sva:
module sky130_fd_sc_hdll__xor2b_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic C,
    input logic X
);
    // X matches the RTL equation: C ? (A^B) : (A|B)
    check_function_equation: assert property (
        @(posedge clk) X == (C ? (A ^ B) : (A | B))
    );

    // When C is 1, X is A xor B
    check_select_high_is_xor: assert property (
        @(posedge clk) (C == 1'b1) |-> (X == (A ^ B))
    );

    // When C is 0, X is A or B
    check_select_low_is_or: assert property (
        @(posedge clk) (C == 1'b0) |-> (X == (A | B))
    );

    // With C=0 and A==B, X equals A
    check_c_low_equal_inputs_pass_through: assert property (
        @(posedge clk) (C == 1'b0) && (A == B) |-> (X == A)
    );

    // If A=0 and B=0, X must be 0
    check_both_zero_results_zero: assert property (
        @(posedge clk) (A == 1'b0) && (B == 1'b0) |-> (X == 1'b0)
    );

    // If A=1, B=1, and C=1, then X must be 0
    check_both_one_c_high_results_zero: assert property (
        @(posedge clk) (A == 1'b1) && (B == 1'b1) && (C == 1'b1) |-> (X == 1'b0)
    );

    // If A=1, B=1, and C=0, then X must be 1
    check_both_one_c_low_results_one: assert property (
        @(posedge clk) (A == 1'b1) && (B == 1'b1) && (C == 1'b0) |-> (X == 1'b1)
    );

    // With C=1, differing inputs imply X=1
    check_c_high_inputs_differ_results_one: assert property (
        @(posedge clk) (C == 1'b1) && (A != B) |-> (X == 1'b1)
    );

    // With C=1, equal inputs imply X=0
    check_c_high_inputs_equal_results_zero: assert property (
        @(posedge clk) (C == 1'b1) && (A == B) |-> (X == 1'b0)
    );

    // With C=0, any input high implies X=1
    check_c_low_any_one_results_one: assert property (
        @(posedge clk) (C == 1'b0) && ((A == 1'b1) || (B == 1'b1)) |-> (X == 1'b1)
    );
endmodule

