module Problem2(
    input A,
    input B,
    input C,
    input D,
    input E,
    input F,
    output X,
    output Y
    );

    assign X = (A & B & C & D) | (A & B & C & E) | (A & B & D & E) | (C & D & A & E) | (C & D & B & E) | (A & B & C & F) | (A & B & D & F) | (C & D & A & F) | (C & D & B & F) | (C & D & E & F) | (A & B & E & F) | (B & D & E & F) | (A & D & E & F) | (B & C & E & F) | (A & C & E & F);
    assign Y = ~((A & B & C & D) | (A & B & C & E) | (A & B & D & E) | (C & D & A & E) | (C & D & B & E) | (A & B & C & F) | (A & B & D & F) | (C & D & A & F) | (C & D & B & F) | (C & D & E & F) | (A & B & E & F) | (B & D & E & F) | (A & D & E & F) | (B & C & E & F) | (A & C & E & F));
endmodule

sva:
module Problem2_sva (
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic E,
    input logic F,
    input logic X,
    input logic Y
);
    // Y must always be the logical complement of X.
    check_y_is_complement_of_x: assert property (
        @($global_clock) Y == ~X
    );

    // X must be 1 when at least four inputs among A..F are 1.
    check_x_high_when_ge4: assert property (
        @($global_clock) ($countones({A,B,C,D,E,F}) >= 4) |-> (X == 1'b1)
    );

    // X must be 0 when fewer than four inputs among A..F are 1.
    check_x_low_when_lt4: assert property (
        @($global_clock) ($countones({A,B,C,D,E,F}) < 4) |-> (X == 1'b0)
    );

    // If no input rises, X cannot rise (monotonic non-decreasing w.r.t. input rises).
    check_no_x_rise_without_input_rise: assert property (
        @($global_clock) !($rose(A) || $rose(B) || $rose(C) || $rose(D) || $rose(E) || $rose(F)) |-> !$rose(X)
    );

    // If no input falls, X cannot fall (monotonic non-increasing w.r.t. input falls).
    check_no_x_fall_without_input_fall: assert property (
        @($global_clock) !($fell(A) || $fell(B) || $fell(C) || $fell(D) || $fell(E) || $fell(F)) |-> !$fell(X)
    );

    // If all inputs are stable, both outputs must be stable (purely combinational function).
    check_stable_inputs_hold_outputs: assert property (
        @($global_clock) $stable({A,B,C,D,E,F}) |-> ($stable(X) && $stable(Y))
    );

    // When X rises, the popcount must cross from <4 to >=4.
    check_x_rise_crosses_threshold: assert property (
        @($global_clock) $rose(X) |-> (($countones({A,B,C,D,E,F}) >= 4) && ($countones($past({A,B,C,D,E,F})) < 4))
    );

    // When X falls, the popcount must cross from >=4 to <4.
    check_x_fall_crosses_threshold: assert property (
        @($global_clock) $fell(X) |-> (($countones({A,B,C,D,E,F}) < 4) && ($countones($past({A,B,C,D,E,F})) >= 4))
    );
endmodule

rtl:
module xor_gate(
    input a,
    input b,
    input clk,
    output reg out_case
);

always @(posedge clk) begin
    case ({a, b})
        2'b00: out_case <= 1'b0;
        2'b01: out_case <= 1'b1;
        2'b10: out_case <= 1'b1;
        2'b11: out_case <= 1'b0;
    endcase
end

endmodule

sva:
module xor_gate_sva (
    input logic a,
    input logic b,
    input logic clk,
    input logic out_case
);

    ///// Functional correctness /////
    // Out should equal XOR of previous-cycle inputs.
    check_out_is_prev_xor: assert property (
        @(posedge clk) $past(1'b1) |-> (out_case == ($past(a) ^ $past(b)))
    );

    // If previous inputs were 00, out must be 0.
    check_truth_00: assert property (
        @(posedge clk) $past(1'b1) && ($past({a,b}) == 2'b00) |-> (out_case == 1'b0)
    );

    // If previous inputs were 01, out must be 1.
    check_truth_01: assert property (
        @(posedge clk) $past(1'b1) && ($past({a,b}) == 2'b01) |-> (out_case == 1'b1)
    );

    // If previous inputs were 10, out must be 1.
    check_truth_10: assert property (
        @(posedge clk) $past(1'b1) && ($past({a,b}) == 2'b10) |-> (out_case == 1'b1)
    );

    // If previous inputs were 11, out must be 0.
    check_truth_11: assert property (
        @(posedge clk) $past(1'b1) && ($past({a,b}) == 2'b11) |-> (out_case == 1'b0)
    );

endmodule

rtl:
module counter (
    input CLK,
    input RST,
    output reg [3:0] Q
);

    always @(posedge CLK) begin
        if (RST) begin
            Q <= 4'b0;
        end else begin
            Q <= Q + 1;
        end
    end

endmodule

sva:
module counter_sva (
    input logic CLK,
    input logic RST,
    input logic [3:0] Q
);

    ///// Reset behavior /////
    // When RST is high, Q must be 0 on the next cycle.
    check_reset_clears_Q_next: assert property (
        @(posedge CLK) RST |=> (Q == 4'h0)
    );

    // If RST is high in two consecutive cycles, Q must be 0 in the second cycle.
    check_Q_zero_while_reset_held: assert property (
        @(posedge CLK) (RST && $past(RST)) |-> (Q == 4'h0)
    );

    // Immediately after a reset cycle (RST was 1 last cycle, now 0), Q must be 0.
    check_Q_zero_immediately_after_reset_release: assert property (
        @(posedge CLK) (!RST && $past(RST)) |-> (Q == 4'h0)
    );

    // On a rising edge of RST, Q must be 0 on the next cycle.
    check_next_after_reset_assert_zero: assert property (
        @(posedge CLK) $rose(RST) |=> (Q == 4'h0)
    );

    // On a falling edge of RST, Q must increment on the next cycle.
    check_next_after_reset_release_increments: assert property (
        @(posedge CLK) $fell(RST) |=> (Q == $past(Q) + 1)
    );

    ///// Counting behavior (when not in reset) /////
    // When not in reset, Q increments by 1 each cycle.
    check_increment_when_not_reset: assert property (
        @(posedge CLK) disable iff (RST) 1'b1 |=> (Q == $past(Q) + 1)
    );

    // When not in reset, Q must change every cycle (no hold).
    check_counter_advances_each_cycle: assert property (
        @(posedge CLK) disable iff (RST) 1'b1 |=> (Q != $past(Q))
    );

    // When not in reset and Q is 0xF, it wraps to 0 on the next cycle.
    check_wrap_from_max_when_not_reset: assert property (
        @(posedge CLK) disable iff (RST) (Q == 4'hF) |=> (Q == 4'h0)
    );

    // When not in reset and Q is 0xE, it becomes 0xF on the next cycle.
    check_increment_from_E_to_F_when_not_reset: assert property (
        @(posedge CLK) disable iff (RST) (Q == 4'hE) |=> (Q == 4'hF)
    );

    ///// Unified next-state rule /////
    // Next Q equals 0 if RST was 1 last cycle, else equals last Q + 1.
    check_unified_next_state_rule: assert property (
        @(posedge CLK) 1'b1 |=> ( $past(RST) ? (Q == 4'h0) : (Q == $past(Q) + 1) )
    );

endmodule

rtl:
module TLATNTSCAX2TS_latch_module (CLK, EN, TE, ENCLK);
  input CLK, EN, TE;
  output ENCLK;

  TLATNTSCAX2TS latch (.E(EN), .SE(TE), .CK(CLK), .ECK(ENCLK));

endmodule

module TLATNTSCAX2TS (
  input E,
  input SE,
  input CK,
  output reg ECK
);
  always @(posedge CK) begin
    if (SE) begin
      ECK <= E;
    end
  end
endmodule

sva:
module TLATNTSCAX2TS_latch_module_sva (
    input logic CLK,
    input logic EN,
    input logic TE,
    input logic ENCLK
);
    ///// Enable-controlled register semantics /////
    // When enabled, ENCLK must equal EN on the same rising CLK edge.
    update_on_enable_matches_input: assert property (
        @(posedge CLK) TE |-> (ENCLK == EN)
    );

    // When disabled, ENCLK must not change on this rising CLK edge.
    hold_when_disabled_stable: assert property (
        @(posedge CLK) !TE |-> !$changed(ENCLK)
    );

    // Any change of ENCLK must occur only when TE is high.
    change_requires_enable: assert property (
        @(posedge CLK) $changed(ENCLK) |-> TE
    );

    // If ENCLK changes, its new value must equal EN (the source when enabled).
    change_sets_output_to_input: assert property (
        @(posedge CLK) $changed(ENCLK) |-> (ENCLK == EN)
    );

    // Full next-state function: ENCLK = (TE ? EN : previous ENCLK).
    next_state_function: assert property (
        @(posedge CLK) ENCLK == (TE ? EN : $past(ENCLK))
    );

    // On a 0->1 enable, if EN differs from previous ENCLK, ENCLK must change.
    rising_enable_diff_data_changes: assert property (
        @(posedge CLK) $rose(TE) && (EN != $past(ENCLK)) |-> $changed(ENCLK)
    );

    // On a 0->1 enable, if EN equals previous ENCLK, ENCLK must not change.
    rising_enable_same_data_no_change: assert property (
        @(posedge CLK) $rose(TE) && (EN == $past(ENCLK)) |-> !$changed(ENCLK)
    );

    // While disabled, changes on EN must not affect ENCLK at the clock edge.
    data_ignored_when_disabled: assert property (
        @(posedge CLK) (!TE && $changed(EN)) |-> !$changed(ENCLK)
    );
endmodule

module d_flip_flop_as_sva (
  input logic clk,
  input logic as,
  input logic [7:0] d,
  input logic [7:0] q
);
  // Clock: clk (posedge). No explicit reset. q updates to d when as==0; holds when as==1.

  // When as is LOW, q captures d on the next clock.
  check_load_on_as_low: assert property (
    @(posedge clk) (~as) |=> (q == $past(d))
  );

  // When as is HIGH, q holds its previous value on the next clock.
  check_hold_when_as_high: assert property (
    @(posedge clk) (as) |=> (q == $past(q))
  );

  // If q changed since the last clock, then as was LOW in the previous cycle.
  check_q_change_requires_prev_enable: assert property (
    @(posedge clk) $changed(q) |-> $past(~as)
  );

  // If q changed since the last clock, the new q equals last cycle's d.
  check_q_change_matches_prev_d: assert property (
    @(posedge clk) $changed(q) |-> (q == $past(d))
  );

  // Exact next-state function for q based on previous cycle's as, d, and q.
  check_next_state_function: assert property (
    @(posedge clk) q == ($past(~as) ? $past(d) : $past(q))
  );

  // If as is LOW and d differs from current q, q must change next cycle.
  check_update_changes_when_data_diff: assert property (
    @(posedge clk) (~as && (d != q)) |=> (q != $past(q))
  );

  // If as is LOW and d equals current q, q must not change next cycle.
  check_update_no_change_when_data_same: assert property (
    @(posedge clk) (~as && (d == q)) |=> (q == $past(q))
  );

  // While holding (as HIGH), changes on d do not affect q.
  check_data_changes_do_not_affect_when_as_high: assert property (
    @(posedge clk) (as && $changed(d)) |=> (q == $past(q))
  );

  // On a falling edge of as, q captures d on the next clock.
  check_fall_as_triggers_update: assert property (
    @(posedge clk) $fell(as) |=> (q == $past(d))
  );

  // On a rising edge of as, q must hold on the next clock.
  check_rise_as_holds_value: assert property (
    @(posedge clk) $rose(as) |=> (q == $past(q))
  );

endmodule

rtl:
module bram_controller(clk, reset, btn, wea, addra);

  input wire clk, reset, btn;
  output reg wea;
  output reg [3:0] addra;

  localparam [1:0]
  idle = 2'b00,
  leer = 2'b01,
  fin  = 2'b10;

  reg [1:0] state_reg;
  reg [3:0] counter;

  always@(posedge clk, posedge reset)
    if(reset)
      begin
        addra<=0;
        counter<=0;	
        state_reg<=idle;
        wea<=0;
      end
  else begin

    case(state_reg)

      idle:
        if(btn==1'b1)begin
          state_reg<=leer;
        end

      leer:
        begin
          wea<=0;
          counter<=counter+1'b1;
          state_reg<=fin;
        end

      fin:begin

        addra<=addra+1'b1;
        if(counter==4'b1111)begin
          counter<=0;
        end
        state_reg<=idle;
      end	

    endcase
  end

endmodule

sva:
module bram_controller_sva (
    input logic clk,
    input logic reset,
    input logic btn,
    input logic wea,
    input logic [3:0] addra,
    input logic [1:0] state_reg,
    input logic [3:0] counter
);
    // State encodings matching RTL
    localparam logic [1:0]
        idle = 2'b00,
        leer = 2'b01,
        fin  = 2'b10;

    ///// Reset behavior /////
    // On reset deassertion, outputs/state/counter return to defaults.
    check_reset_release_defaults: assert property (
        @(posedge clk) disable iff (reset)
            $fell(reset) |-> (addra == 4'd0) && (counter == 4'd0) && (state_reg == idle) && (wea == 1'b0)
    );

    ///// State encoding /////
    // State register only takes the defined encodings.
    check_state_encoding_valid: assert property (
        @(posedge clk) disable iff (reset)
            (state_reg inside {idle, leer, fin})
    );

    ///// State transitions /////
    // In IDLE with btn=0, stay in IDLE.
    check_idle_stay_when_btn0: assert property (
        @(posedge clk) disable iff (reset)
            (state_reg == idle && btn == 1'b0) |-> ##1 (reset || state_reg == idle)
    );
    // In IDLE with btn=1, go to LEER.
    check_idle_to_leer_when_btn1: assert property (
        @(posedge clk) disable iff (reset)
            (state_reg == idle && btn == 1'b1) |-> ##1 (reset || state_reg == leer)
    );
    // From LEER, next state is FIN.
    check_leer_to_fin: assert property (
        @(posedge clk) disable iff (reset)
            (state_reg == leer) |-> ##1 (reset || state_reg == fin)
    );
    // From FIN, next state is IDLE.
    check_fin_to_idle: assert property (
        @(posedge clk) disable iff (reset)
            (state_reg == fin) |-> ##1 (reset || state_reg == idle)
    );

    ///// WEA behavior /////
    // WEA is always 0 after reset.
    check_wea_const_zero: assert property (
        @(posedge clk) disable iff (reset)
            wea == 1'b0
    );

    ///// ADDRA behavior /////
    // ADDRA increments by 1 in FIN.
    check_addra_inc_in_fin: assert property (
        @(posedge clk) disable iff (reset)
            (state_reg == fin) |-> ##1 (reset || addra == $past(addra) + 1'b1)
    );
    // ADDRA holds in IDLE.
    check_addra_hold_in_idle: assert property (
        @(posedge clk) disable iff (reset)
            (state_reg == idle) |-> ##1 (reset || addra == $past(addra))
    );
    // ADDRA holds in LEER.
    check_addra_hold_in_leer: assert property (
        @(posedge clk) disable iff (reset)
            (state_reg == leer) |-> ##1 (reset || addra == $past(addra))
    );

    ///// COUNTER behavior /////
    // COUNTER increments by 1 in LEER.
    check_counter_inc_in_leer: assert property (
        @(posedge clk) disable iff (reset)
            (state_reg == leer) |-> ##1 (reset || counter == $past(counter) + 1'b1)
    );
    // COUNTER holds in IDLE.
    check_counter_hold_in_idle: assert property (
        @(posedge clk) disable iff (reset)
            (state_reg == idle) |-> ##1 (reset || counter == $past(counter))
    );
    // COUNTER resets to 0 in FIN when it equals 15.
    check_counter_reset_in_fin_at_15: assert property (
        @(posedge clk) disable iff (reset)
            (state_reg == fin && counter == 4'b1111) |-> ##1 (reset || counter == 4'd0)
    );
    // COUNTER holds in FIN when not 15.
    check_counter_hold_in_fin_not_15: assert property (
        @(posedge clk) disable iff (reset)
            (state_reg == fin && counter != 4'b1111) |-> ##1 (reset || counter == $past(counter))
    );
endmodule

module Cfu_sva (
  input logic               cmd_valid,
  input logic               cmd_ready,
  input logic [9:0]         cmd_payload_function_id,
  input logic [31:0]        cmd_payload_inputs_0,
  input logic [31:0]        cmd_payload_inputs_1,
  input logic               rsp_valid,
  input logic               rsp_ready,
  input logic [31:0]        rsp_payload_outputs_0,
  input logic               reset,
  input logic               clk
);
    // rsp_valid must mirror cmd_valid each cycle.
    check_rsp_valid_mirror: assert property (
        @(posedge clk) disable iff (reset) (rsp_valid == cmd_valid)
    );

    // cmd_ready must mirror rsp_ready each cycle.
    check_cmd_ready_mirror: assert property (
        @(posedge clk) disable iff (reset) (cmd_ready == rsp_ready)
    );

    // When select=0, output routes inputs_0.
    mux_select0_routes_in0: assert property (
        @(posedge clk) disable iff (reset) (!cmd_payload_function_id[0]) |-> (rsp_payload_outputs_0 == cmd_payload_inputs_0)
    );

    // When select=1, output routes inputs_1.
    mux_select1_routes_in1: assert property (
        @(posedge clk) disable iff (reset) (cmd_payload_function_id[0]) |-> (rsp_payload_outputs_0 == cmd_payload_inputs_1)
    );

    // Output equals the ternary mux of select and inputs.
    mux_function_equivalence: assert property (
        @(posedge clk) disable iff (reset) (rsp_payload_outputs_0 == (cmd_payload_function_id[0] ? cmd_payload_inputs_1 : cmd_payload_inputs_0))
    );

    // If select and both inputs are stable, the output remains stable.
    out_stable_when_inputs_stable: assert property (
        @(posedge clk) disable iff (reset) ($stable(cmd_payload_function_id[0]) && $stable(cmd_payload_inputs_0) && $stable(cmd_payload_inputs_1)) |-> $stable(rsp_payload_outputs_0)
    );

    // Changes to function_id[9:1] alone cannot change the output.
    upper_id_bits_no_effect: assert property (
        @(posedge clk) disable iff (reset)
            ($stable(cmd_payload_function_id[0]) && $stable(cmd_payload_inputs_0) && $stable(cmd_payload_inputs_1) &&
             (cmd_payload_function_id[9:1] != $past(cmd_payload_function_id[9:1])))
            |-> $stable(rsp_payload_outputs_0)
    );

    // Rising edge on cmd_valid produces rising edge on rsp_valid.
    edge_rise_valid_mirror: assert property (
        @(posedge clk) disable iff (reset) $rose(cmd_valid) |-> $rose(rsp_valid)
    );

    // Falling edge on cmd_valid produces falling edge on rsp_valid.
    edge_fall_valid_mirror: assert property (
        @(posedge clk) disable iff (reset) $fell(cmd_valid) |-> $fell(rsp_valid)
    );

    // Rising edge on rsp_ready produces rising edge on cmd_ready.
    edge_rise_ready_mirror: assert property (
        @(posedge clk) disable iff (reset) $rose(rsp_ready) |-> $rose(cmd_ready)
    );

    // Falling edge on rsp_ready produces falling edge on cmd_ready.
    edge_fall_ready_mirror: assert property (
        @(posedge clk) disable iff (reset) $fell(rsp_ready) |-> $fell(cmd_ready)
    );
endmodule

rtl:
module barrel_shifter (
    input [3:0] data,
    input [1:0] shift_amount,
    output reg [3:0] result
);

always @(*) begin
    case(shift_amount)
        2'b00: result = data;
        2'b01: result = {data[2:0], 1'b0};
        2'b10: result = {data[1:0], 2'b00};
        2'b11: result = 4'b0000;
    endcase
end

endmodule

sva:
module barrel_shifter_sva (
    input logic CLK,
    input logic [3:0] data,
    input logic [1:0] shift_amount,
    input logic [3:0] result
);
    // Result matches the full case-defined function for all shift_amount values.
    check_function_complete: assert property (
        @(posedge CLK)
            ((shift_amount == 2'b00) && (result == data)) ||
            ((shift_amount == 2'b01) && (result == {data[2:0], 1'b0})) ||
            ((shift_amount == 2'b10) && (result == {data[1:0], 2'b00})) ||
            ((shift_amount == 2'b11) && (result == 4'b0000))
    );

    // No shift: result equals data when shift_amount == 2'b00.
    check_no_shift_passthrough: assert property (
        @(posedge CLK) (shift_amount == 2'b00) |-> (result == data)
    );

    // Shift by 1: result equals {data[2:0], 1'b0} when shift_amount == 2'b01.
    check_shift1_concat: assert property (
        @(posedge CLK) (shift_amount == 2'b01) |-> (result == {data[2:0], 1'b0})
    );

    // Shift by 2: result equals {data[1:0], 2'b00} when shift_amount == 2'b10.
    check_shift2_concat: assert property (
        @(posedge CLK) (shift_amount == 2'b10) |-> (result == {data[1:0], 2'b00})
    );

    // Shift by 3 (2'b11): result is 4'b0000 regardless of data.
    check_shift3_zero: assert property (
        @(posedge CLK) (shift_amount == 2'b11) |-> (result == 4'b0000)
    );

    // Shift by 1: LSB is forced to 0.
    check_shift1_lsb_zero: assert property (
        @(posedge CLK) (shift_amount == 2'b01) |-> (result[0] == 1'b0)
    );

    // Shift by 2: two LSBs are forced to 0.
    check_shift2_lsbs_zero: assert property (
        @(posedge CLK) (shift_amount == 2'b10) |-> (result[1:0] == 2'b00)
    );

    // Shift by 1: upper bits map to data[2:0].
    check_shift1_upper_map: assert property (
        @(posedge CLK) (shift_amount == 2'b01) |-> (result[3:1] == data[2:0])
    );

    // Shift by 2: upper two bits map to data[1:0].
    check_shift2_upper_map: assert property (
        @(posedge CLK) (shift_amount == 2'b10) |-> (result[3:2] == data[1:0])
    );

    // Purely combinational behavior: if inputs are stable, result is stable.
    check_stability_with_stable_inputs: assert property (
        @(posedge CLK) ($stable(data) && $stable(shift_amount)) |-> $stable(result)
    );
endmodule

module top_module_sva (
    input logic clk,
    input logic rst_n,
    input logic write_en,
    input logic [7:0] write_addr,
    input logic [3:0] write_data,
    input logic read_en,
    input logic [7:0] read_addr,
    input logic [3:0] mux_in_0,
    input logic [3:0] mux_in_1,
    input logic [3:0] mux_in_2,
    input logic [3:0] mux_in_3,
    input logic [1:0] mux_sel,
    input logic [3:0] out
);
    // During reset, out must be cleared to 0.
    check_reset_clears_out: assert property (
        @(posedge clk) !rst_n |-> (out == 4'b0000)
    );

    // When read_en is LOW, out holds its previous value.
    check_out_holds_without_read: assert property (
        @(posedge clk) disable iff (!rst_n) (!read_en) |=> (out == $past(out))
    );

    // With read_en HIGH and mux_sel==01, out captures mux_in_0 on next cycle.
    check_read_sel_01_routes_mux_in_0: assert property (
        @(posedge clk) disable iff (!rst_n) (read_en && (mux_sel == 2'b01)) |=> (out == $past(mux_in_0))
    );

    // With read_en HIGH and mux_sel==10, out captures mux_in_1 on next cycle.
    check_read_sel_10_routes_mux_in_1: assert property (
        @(posedge clk) disable iff (!rst_n) (read_en && (mux_sel == 2'b10)) |=> (out == $past(mux_in_1))
    );

    // With read_en HIGH and mux_sel==11, out captures mux_in_2 on next cycle.
    check_read_sel_11_routes_mux_in_2: assert property (
        @(posedge clk) disable iff (!rst_n) (read_en && (mux_sel == 2'b11)) |=> (out == $past(mux_in_2))
    );
endmodule

rtl:
module pulse_generator (
    input clk,
    input ena,
    output reg pulse,
    output reg cycle
);

reg [1:0] state;

always @(posedge clk) begin
    cycle <= state[0];
    if (ena) begin
        state <= 2'b01;
        pulse <= 1'b1;
    end
    else begin
        state <= 2'b10;
        pulse <= 1'b0;
    end
end

endmodule

sva:
module pulse_generator_sva (
    input logic clk,
    input logic ena,
    input logic pulse,
    input logic cycle,
    input logic [1:0] state
);
    ///// Sequential behavior derived from RTL ///// 

    // pulse captures ena from the previous cycle.
    check_pulse_follows_prev_ena: assert property (
        @(posedge clk) $past(1'b1) |-> (pulse == $past(ena))
    );

    // state encodes previous-cycle ena as 2'b01 when ena=1 and 2'b10 when ena=0.
    check_state_encodes_prev_ena: assert property (
        @(posedge clk) $past(1'b1) |-> (state == ($past(ena) ? 2'b01 : 2'b10))
    );

    // cycle captures state[0] from two cycles earlier (due to read-before-write of state).
    check_cycle_follows_prevprev_state_bit0: assert property (
        @(posedge clk) $past(1'b1, 2) |-> (cycle == $past(state[0], 2))
    );

    // cycle equals ena from two cycles earlier.
    check_cycle_follows_prevprev_ena: assert property (
        @(posedge clk) $past(1'b1, 2) |-> (cycle == $past(ena, 2))
    );

    // pulse equals state[0] in the same sampled cycle.
    check_pulse_equals_state_lsb: assert property (
        @(posedge clk) $past(1'b1) |-> (pulse == state[0])
    );

    // state is always one-hot (01 or 10) after first update.
    check_state_onehot: assert property (
        @(posedge clk) $past(1'b1) |-> ((state == 2'b01) || (state == 2'b10))
    );

    // state bits are complementary after first update.
    check_state_bits_complementary: assert property (
        @(posedge clk) $past(1'b1) |-> (state[1] == ~state[0])
    );

    // When previous ena was 1, pulse must be 1.
    check_pulse_assert_when_prev_ena_high: assert property (
        @(posedge clk) ($past(1'b1) && $past(ena)) |-> (pulse == 1'b1)
    );

    // When previous ena was 0, pulse must be 0.
    check_pulse_deassert_when_prev_ena_low: assert property (
        @(posedge clk) ($past(1'b1) && !$past(ena)) |-> (pulse == 1'b0)
    );

    // After first update, state LSB reflects previous ena directly.
    check_state_lsb_matches_prev_ena: assert property (
        @(posedge clk) $past(1'b1) |-> (state[0] == $past(ena))
    );

endmodule

rtl:
module and_or_gate (
    X,
    A1,
    A2,
    A3,
    B1,
    B2
);

    output X;
    input A1;
    input A2;
    input A3;
    input B1;
    input B2;

    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB;
    supply0 VNB;

    wire or_input;
    wire and_output;

    assign or_input = A3 | B1 | B2;
    assign and_output = A1 & A2;

    assign X = and_output & or_input;

endmodule

sva:
module and_or_gate_sva (
    input logic CLK,
    input logic RESETn,
    input logic X,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic B1,
    input logic B2
);
    // X equals A1&A2&(A3|B1|B2).
    check_functional_equivalence: assert property (
        @(posedge CLK) disable iff (!RESETn) X == ((A1 & A2) & (A3 | B1 | B2))
    );

    // If X is 1 then A1 must be 1.
    check_x_implies_a1: assert property (
        @(posedge CLK) disable iff (!RESETn) X |-> A1
    );

    // If X is 1 then A2 must be 1.
    check_x_implies_a2: assert property (
        @(posedge CLK) disable iff (!RESETn) X |-> A2
    );

    // If X is 1 then at least one of A3/B1/B2 must be 1.
    check_x_implies_or: assert property (
        @(posedge CLK) disable iff (!RESETn) X |-> (A3 | B1 | B2)
    );

    // If A1 is 0 then X must be 0.
    check_zero_when_a1_low: assert property (
        @(posedge CLK) disable iff (!RESETn) (!A1) |-> (X == 1'b0)
    );

    // If A2 is 0 then X must be 0.
    check_zero_when_a2_low: assert property (
        @(posedge CLK) disable iff (!RESETn) (!A2) |-> (X == 1'b0)
    );

    // If A3,B1,B2 are all 0 then X must be 0.
    check_zero_when_or_inputs_low: assert property (
        @(posedge CLK) disable iff (!RESETn) (!A3 & !B1 & !B2) |-> (X == 1'b0)
    );

    // If A1&A2 and any of A3/B1/B2 then X must be 1.
    check_one_when_and_and_any_or: assert property (
        @(posedge CLK) disable iff (!RESETn) (A1 & A2 & (A3 | B1 | B2)) |-> (X == 1'b1)
    );

    // If A1&A2 and none of A3/B1/B2 then X must be 0.
    check_zero_when_and_and_no_or: assert property (
        @(posedge CLK) disable iff (!RESETn) (A1 & A2 & !A3 & !B1 & !B2) |-> (X == 1'b0)
    );

    // When A1&A2 are 1, X equals (A3|B1|B2).
    check_a1a2_high_means_x_matches_or: assert property (
        @(posedge CLK) disable iff (!RESETn) (A1 & A2) |-> (X == (A3 | B1 | B2))
    );

    // When any of A3/B1/B2 is 1, X equals (A1&A2).
    check_or_high_means_x_matches_and: assert property (
        @(posedge CLK) disable iff (!RESETn) (A3 | B1 | B2) |-> (X == (A1 & A2))
    );
endmodule

