sva:
module sky130_fd_sc_hdll__o21ba_sva (
    input  logic CLK,
    input  logic X,
    input  logic A1,
    input  logic A2,
    input  logic B1_N
);
    // Functional equivalence: X == (~B1_N) & (A1 | A2).
    check_function_equation: assert property (
        @(posedge CLK) X == ((~B1_N) & (A1 | A2))
    );

    // When B1_N is HIGH, X must be LOW.
    check_x_low_when_B1_N_high: assert property (
        @(posedge CLK) (B1_N == 1'b1) |-> (X == 1'b0)
    );

    // When both A1 and A2 are LOW, X must be LOW.
    check_x_low_when_A1_A2_low: assert property (
        @(posedge CLK) ((A1 == 1'b0) && (A2 == 1'b0)) |-> (X == 1'b0)
    );

    // When B1_N is LOW, X equals (A1 | A2).
    check_x_equals_or_under_enable: assert property (
        @(posedge CLK) (B1_N == 1'b0) |-> (X == (A1 | A2))
    );

    // If X is HIGH, B1_N must be LOW.
    check_x_high_implies_B1_N_low: assert property (
        @(posedge CLK) (X == 1'b1) |-> (B1_N == 1'b0)
    );

    // If X is HIGH, at least one of A1 or A2 must be HIGH.
    check_x_high_implies_A1_or_A2_high: assert property (
        @(posedge CLK) (X == 1'b1) |-> (A1 || A2)
    );

    // If B1_N is LOW and A1 is HIGH, X must be HIGH.
    check_x_high_when_B1_N_low_and_A1_high: assert property (
        @(posedge CLK) ((B1_N == 1'b0) && (A1 == 1'b1)) |-> (X == 1'b1)
    );

    // If B1_N is LOW and A2 is HIGH, X must be HIGH.
    check_x_high_when_B1_N_low_and_A2_high: assert property (
        @(posedge CLK) ((B1_N == 1'b0) && (A2 == 1'b1)) |-> (X == 1'b1)
    );

    // If B1_N is LOW and both A1 and A2 are LOW, X must be LOW.
    check_x_low_when_enable_and_inputs_low: assert property (
        @(posedge CLK) ((B1_N == 1'b0) && (A1 == 1'b0) && (A2 == 1'b0)) |-> (X == 1'b0)
    );

    // If X is LOW, then either B1_N is HIGH or both A1 and A2 are LOW.
    check_x_low_implies_block_or_both_low: assert property (
        @(posedge CLK) (X == 1'b0) |-> (B1_N || ((A1 == 1'b0) && (A2 == 1'b0)))
    );
endmodule

rtl:
module shift_register (
  input [3:0] data_in,
  input shift_in,
  input load,
  input clk,
  output reg [3:0] data_out
);

  reg [3:0] shift_reg;

  always @(posedge clk) begin
    if (load) begin
      shift_reg <= data_in;
    end else begin
      shift_reg <= {shift_reg[2:0], shift_in};
    end
  end

  always @* begin
    data_out = shift_reg;
  end

endmodule

sva:
module shift_register_sva (
    input  logic        clk,
    input  logic [3:0]  data_in,
    input  logic        shift_in,
    input  logic        load,
    input  logic [3:0]  data_out,
    input  logic [3:0]  shift_reg
);

    ///// Combinational pass-through /////
    // data_out continuously mirrors internal shift_reg.
    check_dataout_mirrors_shiftreg: assert property (
        @(posedge clk) data_out == shift_reg
    );

    ///// Next-state behavior /////
    // Next-cycle data_out equals load ? data_in : {data_out[2:0], shift_in}.
    check_next_state_equation: assert property (
        @(posedge clk) 1'b1 |=> (data_out == ($sampled(load) ? $sampled(data_in) : { $sampled(data_out[2:0]), $sampled(shift_in) }))
    );

    ///// Load behavior /////
    // When load is asserted, next-cycle data_out equals sampled data_in.
    load_captures_data_in_next_cycle: assert property (
        @(posedge clk) load |=> (data_out == $sampled(data_in))
    );

    ///// Shift behavior (bit-wise) /////
    // When shifting, next-cycle MSB comes from prior bit[2].
    shift_moves_msb_from_bit2: assert property (
        @(posedge clk) !load |=> (data_out[3] == $sampled(data_out[2]))
    );
    // When shifting, next-cycle bit[2] comes from prior bit[1].
    shift_moves_bit2_from_bit1: assert property (
        @(posedge clk) !load |=> (data_out[2] == $sampled(data_out[1]))
    );
    // When shifting, next-cycle bit[1] comes from prior bit[0].
    shift_moves_bit1_from_bit0: assert property (
        @(posedge clk) !load |=> (data_out[1] == $sampled(data_out[0]))
    );
    // When shifting, next-cycle LSB comes from sampled shift_in.
    shift_in_captures_into_lsb: assert property (
        @(posedge clk) !load |=> (data_out[0] == $sampled(shift_in))
    );

    ///// Multi-cycle behavior /////
    // Two consecutive shifts produce a two-bit left shift with two sampled shift_in bits.
    two_consecutive_shifts_chain: assert property (
        @(posedge clk) ($past(!load,2) && $past(!load,1)) |-> (data_out == { $past(data_out[1:0],2), $past(shift_in,2), $past(shift_in,1) })
    );
    // Two consecutive loads result in data_out taking the most recent sampled data_in.
    two_consecutive_loads_last_sample_kept: assert property (
        @(posedge clk) ($past(load,2) && $past(load,1)) |-> (data_out == $past(data_in,1))
    );

endmodule

rtl:
module write_back
#(
   parameter DATA_WIDTH = 32,
   parameter REG_ADDR_WIDTH = 5
 )
(
   input [DATA_WIDTH-1:0] mem_data_in,
   input [DATA_WIDTH-1:0] alu_data_in,
   input [DATA_WIDTH-1:0] hi_data_in,
input [REG_ADDR_WIDTH-1:0] reg_a_wr_addr_in,
   input [REG_ADDR_WIDTH-1:0] reg_b_wr_addr_in,
   input reg_a_wr_en_in,
   input reg_b_wr_en_in,
   input write_back_mux_sel,

   output [REG_ADDR_WIDTH-1:0] reg_a_wr_addr_out,
   output [REG_ADDR_WIDTH-1:0] reg_b_wr_addr_out,
   output [DATA_WIDTH-1:0] reg_a_wr_data_out,
   output [DATA_WIDTH-1:0] reg_b_wr_data_out,
   output reg_a_wr_en_out,
   output reg_b_wr_en_out
);

assign reg_a_wr_data_out = write_back_mux_sel?mem_data_in:alu_data_in;
assign reg_b_wr_data_out = hi_data_in;
assign reg_a_wr_en_out = reg_a_wr_en_in;
assign reg_b_wr_en_out = reg_b_wr_en_in;
assign reg_a_wr_addr_out = reg_a_wr_addr_in;
assign reg_b_wr_addr_out = reg_b_wr_addr_in;

endmodule

sva:
module write_back_sva
#(
   parameter DATA_WIDTH = 32,
   parameter REG_ADDR_WIDTH = 5
)
(
   input  logic                       clk,

   input  logic [DATA_WIDTH-1:0]      mem_data_in,
   input  logic [DATA_WIDTH-1:0]      alu_data_in,
   input  logic [DATA_WIDTH-1:0]      hi_data_in,
   input  logic [REG_ADDR_WIDTH-1:0]  reg_a_wr_addr_in,
   input  logic [REG_ADDR_WIDTH-1:0]  reg_b_wr_addr_in,
   input  logic                       reg_a_wr_en_in,
   input  logic                       reg_b_wr_en_in,
   input  logic                       write_back_mux_sel,

   input  logic [REG_ADDR_WIDTH-1:0]  reg_a_wr_addr_out,
   input  logic [REG_ADDR_WIDTH-1:0]  reg_b_wr_addr_out,
   input  logic [DATA_WIDTH-1:0]      reg_a_wr_data_out,
   input  logic [DATA_WIDTH-1:0]      reg_b_wr_data_out,
   input  logic                       reg_a_wr_en_out,
   input  logic                       reg_b_wr_en_out
);

    ///// Combinational passthrough/mux behavior /////
    // reg_a_wr_data_out equals selected input per write_back_mux_sel.
    check_a_data_mux: assert property (
        @(posedge clk) reg_a_wr_data_out == (write_back_mux_sel ? mem_data_in : alu_data_in)
    );

    // When sel=1, reg_a_wr_data_out equals mem_data_in.
    check_a_data_when_sel1: assert property (
        @(posedge clk) (write_back_mux_sel == 1'b1) |-> (reg_a_wr_data_out == mem_data_in)
    );

    // When sel=0, reg_a_wr_data_out equals alu_data_in.
    check_a_data_when_sel0: assert property (
        @(posedge clk) (write_back_mux_sel == 1'b0) |-> (reg_a_wr_data_out == alu_data_in)
    );

    // reg_b_wr_data_out passes through hi_data_in.
    check_b_data_passthrough: assert property (
        @(posedge clk) reg_b_wr_data_out == hi_data_in
    );

    // reg_a_wr_en_out passes through reg_a_wr_en_in.
    check_a_wr_en_passthrough: assert property (
        @(posedge clk) reg_a_wr_en_out == reg_a_wr_en_in
    );

    // reg_b_wr_en_out passes through reg_b_wr_en_in.
    check_b_wr_en_passthrough: assert property (
        @(posedge clk) reg_b_wr_en_out == reg_b_wr_en_in
    );

    // reg_a_wr_addr_out passes through reg_a_wr_addr_in.
    check_a_addr_passthrough: assert property (
        @(posedge clk) reg_a_wr_addr_out == reg_a_wr_addr_in
    );

    // reg_b_wr_addr_out passes through reg_b_wr_addr_in.
    check_b_addr_passthrough: assert property (
        @(posedge clk) reg_b_wr_addr_out == reg_b_wr_addr_in
    );

endmodule

rtl:
module min_finder (
    input [7:0] a, b, c, d,
    output [7:0] min);

    wire [7:0] ab_min, cd_min, global_min;

    // Comparators to find the minimum of a and b, and c and d
    assign ab_min = (a < b) ? a : b;
    assign cd_min = (c < d) ? c : d;

    // Multiplexer to select the minimum of a and b, and c and d
    assign global_min = (ab_min < cd_min) ? ab_min : cd_min;

    // Output the global minimum
    assign min = global_min;

endmodule

module top_module (
    input [7:0] a, b, c, d,
    output [7:0] min);

    min_finder min_finder_inst (
        .a(a),
        .b(b),
        .c(c),
        .d(d),
        .min(min)
    );

endmodule

sva:
module min_finder_sva (
    input logic [7:0] a, b, c, d,
    input logic [7:0] min,
    input logic [7:0] ab_min, cd_min, global_min
);
    // Use a global formal clock for combinational design
    default clocking @(posedge $global_clock); endclocking

    // ab_min equals a when a < b
    check_ab_min_select_a: assert property (
        (a < b) |-> (ab_min == a)
    );

    // ab_min equals b when a >= b (ties choose b)
    check_ab_min_select_b: assert property (
        (a >= b) |-> (ab_min == b)
    );

    // ab_min is less than or equal to both a and b
    check_ab_min_le_inputs: assert property (
        (ab_min <= a) && (ab_min <= b)
    );

    // cd_min equals c when c < d
    check_cd_min_select_c: assert property (
        (c < d) |-> (cd_min == c)
    );

    // cd_min equals d when c >= d (ties choose d)
    check_cd_min_select_d: assert property (
        (c >= d) |-> (cd_min == d)
    );

    // cd_min is less than or equal to both c and d
    check_cd_min_le_inputs: assert property (
        (cd_min <= c) && (cd_min <= d)
    );

    // global_min equals ab_min when ab_min < cd_min
    check_global_min_select_ab: assert property (
        (ab_min < cd_min) |-> (global_min == ab_min)
    );

    // global_min equals cd_min when ab_min >= cd_min (ties choose cd_min)
    check_global_min_select_cd: assert property (
        (ab_min >= cd_min) |-> (global_min == cd_min)
    );

    // global_min is less than or equal to both ab_min and cd_min
    check_global_min_le_pair_mins: assert property (
        (global_min <= ab_min) && (global_min <= cd_min)
    );

    // Output min equals global_min
    check_min_equals_global_min: assert property (
        (min == global_min)
    );

    // Output min is less than or equal to all inputs
    check_min_le_all_inputs: assert property (
        (min <= a) && (min <= b) && (min <= c) && (min <= d)
    );

    // Output min equals one of the inputs
    check_min_is_one_of_inputs: assert property (
        (min == a) || (min == b) || (min == c) || (min == d)
    );
endmodule

rtl:
module d_latch (
    input GATE,
    input CLK,
    input D,
    output Q
);

    reg q;

    always @(posedge CLK) begin
        if (!GATE) begin
            q <= D;
        end
    end

    assign Q = q;

endmodule

sva:
module d_latch_sva (
    input logic CLK,
    input logic GATE,
    input logic D,
    input logic Q
);
    // Next-cycle state equation: if GATE is low at next edge, Q= D; else Q holds previous value.
    check_next_state_equation: assert property (
        @(posedge CLK) 1'b1 |=> (Q == ((!GATE) ? D : $past(Q)))
    );

    // When GATE is high, Q holds its previous sampled value into the next cycle.
    check_hold_when_gate_high: assert property (
        @(posedge CLK) GATE |=> (Q == $past(Q))
    );

    // Any observed change in Q between consecutive samples must be due to GATE being low in the previous cycle.
    check_q_change_requires_prev_gate_low: assert property (
        @(posedge CLK) $changed(Q) |-> $past(!GATE)
    );

    // If GATE is high and D toggles, Q still holds its previous value into the next cycle.
    check_hold_when_gate_high_even_if_d_toggles: assert property (
        @(posedge CLK) (GATE && (D != $past(D))) |=> (Q == $past(Q))
    );

    // On a rising transition of GATE (low->high), Q equals the D value captured in the prior cycle.
    check_q_matches_d_on_gate_rise: assert property (
        @(posedge CLK) $rose(GATE) |-> (Q == $past(D))
    );
endmodule

rtl:
module mux4to1 (
  input [3:0] in,
  input [1:0] sel,
  output reg out
);

always @(*) begin
  case(sel)
    2'b00: out = in[0];
    2'b01: out = in[1];
    2'b10: out = in[2];
    2'b11: out = in[3];
  endcase
end

endmodule

sva:
module mux4to1_sva (
    input logic clk,        // External clock for sampling assertions (RTL has no clock/reset)
    input logic [3:0] in,
    input logic [1:0] sel,
    input logic out
);
    // Out equals the input bit indexed by sel.
    check_out_matches_index: assert property (
        @(posedge clk) out == in[sel]
    );

    // When sel==00, out must equal in[0].
    check_sel_00_mapping: assert property (
        @(posedge clk) (sel == 2'b00) |-> (out == in[0])
    );

    // When sel==01, out must equal in[1].
    check_sel_01_mapping: assert property (
        @(posedge clk) (sel == 2'b01) |-> (out == in[1])
    );

    // When sel==10, out must equal in[2].
    check_sel_10_mapping: assert property (
        @(posedge clk) (sel == 2'b10) |-> (out == in[2])
    );

    // When sel==11, out must equal in[3].
    check_sel_11_mapping: assert property (
        @(posedge clk) (sel == 2'b11) |-> (out == in[3])
    );

    // Out equals SOP decode of sel and inputs (structural equivalence).
    check_sop_equivalence: assert property (
        @(posedge clk) out ==
            ((~sel[1] & ~sel[0] & in[0]) |
             (~sel[1] &  sel[0] & in[1]) |
             ( sel[1] & ~sel[0] & in[2]) |
             ( sel[1] &  sel[0] & in[3]))
    );
endmodule

rtl:
module my_or_gate (
    X   ,
    A   ,
    B   ,
    C   ,
    D_N ,
    VPWR,
    VGND,
    VPB ,
    VNB
);

    output X   ;
    input  A   ;
    input  B   ;
    input  C   ;
    input  D_N ;
    input  VPWR;
    input  VGND;
    input  VPB ;
    input  VNB ;

    assign X = A | B | C | D_N;

endmodule

sva:
module my_or_gate_sva (
    input logic X,
    input logic A,
    input logic B,
    input logic C,
    input logic D_N,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB
);
    ///// Functional equivalence to RTL assign /////
    // X matches A|B|C|D_N when A rises.
    check_or_equiv_on_A_posedge: assert property (
        @(posedge A) X == (A | B | C | D_N)
    );
    // X matches A|B|C|D_N when A falls.
    check_or_equiv_on_A_negedge: assert property (
        @(negedge A) X == (A | B | C | D_N)
    );
    // X matches A|B|C|D_N when B rises.
    check_or_equiv_on_B_posedge: assert property (
        @(posedge B) X == (A | B | C | D_N)
    );
    // X matches A|B|C|D_N when B falls.
    check_or_equiv_on_B_negedge: assert property (
        @(negedge B) X == (A | B | C | D_N)
    );
    // X matches A|B|C|D_N when C rises.
    check_or_equiv_on_C_posedge: assert property (
        @(posedge C) X == (A | B | C | D_N)
    );
    // X matches A|B|C|D_N when C falls.
    check_or_equiv_on_C_negedge: assert property (
        @(negedge C) X == (A | B | C | D_N)
    );
    // X matches A|B|C|D_N when D_N rises.
    check_or_equiv_on_DN_posedge: assert property (
        @(posedge D_N) X == (A | B | C | D_N)
    );
    // X matches A|B|C|D_N when D_N falls.
    check_or_equiv_on_DN_negedge: assert property (
        @(negedge D_N) X == (A | B | C | D_N)
    );

    ///// Independence from unused power/body pins /////
    // VPWR changes do not affect X if A,B,C,D_N are stable.
    check_x_independent_of_vpwr_posedge: assert property (
        @(posedge VPWR) ((A == $past(A)) && (B == $past(B)) && (C == $past(C)) && (D_N == $past(D_N))) |-> (X == $past(X))
    );
    // VPWR changes do not affect X if A,B,C,D_N are stable.
    check_x_independent_of_vpwr_negedge: assert property (
        @(negedge VPWR) ((A == $past(A)) && (B == $past(B)) && (C == $past(C)) && (D_N == $past(D_N))) |-> (X == $past(X))
    );
    // VGND changes do not affect X if A,B,C,D_N are stable.
    check_x_independent_of_vgnd_posedge: assert property (
        @(posedge VGND) ((A == $past(A)) && (B == $past(B)) && (C == $past(C)) && (D_N == $past(D_N))) |-> (X == $past(X))
    );
    // VGND changes do not affect X if A,B,C,D_N are stable.
    check_x_independent_of_vgnd_negedge: assert property (
        @(negedge VGND) ((A == $past(A)) && (B == $past(B)) && (C == $past(C)) && (D_N == $past(D_N))) |-> (X == $past(X))
    );
endmodule

rtl:
module ID_EX(
	clk,rst,BJ,
	id_a, id_b, id_td, id_d2, id_Aluc, id_WREG, id_WMEM, id_LW,id_instr,
	ex_a, ex_b, ex_td, ex_d2, ex_Aluc, ex_WREG, ex_WMEM, ex_LW,ex_instr
    );
	input clk,rst,BJ;
	input wire [31:0] id_a,id_b,id_d2,id_instr;
	input wire [4:0] id_td,id_Aluc;
	input wire id_WREG,id_WMEM,id_LW;
	output reg [31:0] ex_a,ex_b,ex_d2,ex_instr;
	output reg [4:0] ex_td,ex_Aluc;
	output reg ex_WREG,ex_WMEM,ex_LW;

	always @(posedge clk or posedge rst)
	begin
		if(rst)
		begin
			ex_a <= 0;
			ex_b <= 0;
			ex_d2 <= 0;
			ex_td <= 0;
			ex_Aluc <= 0;
			ex_WREG <= 0;
			ex_WMEM <= 0;
			ex_LW <= 0;
			ex_instr<=32'b100000;
		end
		else if(BJ)
		begin
			ex_a <= 0;
			ex_b <= 0;
			ex_d2 <= 0;
			ex_td <= 0;
			ex_Aluc <= 0;
			ex_WREG <= 0;
			ex_WMEM <= 0;
			ex_LW <= 0;
			ex_instr<=32'b100000;
		end
		else
		begin
			ex_a <= id_a;
			ex_b <= id_b;
			ex_d2 <= id_d2;
			ex_td <= id_td;
			ex_Aluc <= id_Aluc;
			ex_WREG <= id_WREG;
			ex_WMEM <= id_WMEM;
			ex_LW <= id_LW;
			ex_instr<=id_instr;
		end
	end

endmodule

sva:
module ID_EX_sva (
    input logic clk,
    input logic rst,
    input logic BJ,
    input logic [31:0] id_a,
    input logic [31:0] id_b,
    input logic [31:0] id_d2,
    input logic [31:0] id_instr,
    input logic [4:0]  id_td,
    input logic [4:0]  id_Aluc,
    input logic        id_WREG,
    input logic        id_WMEM,
    input logic        id_LW,
    input logic [31:0] ex_a,
    input logic [31:0] ex_b,
    input logic [31:0] ex_d2,
    input logic [31:0] ex_instr,
    input logic [4:0]  ex_td,
    input logic [4:0]  ex_Aluc,
    input logic        ex_WREG,
    input logic        ex_WMEM,
    input logic        ex_LW
);
    ///// Reset behavior /////
    // During reset, all EX regs are 0 and ex_instr is 32'b100000.
    check_reset_defaults: assert property (
        @(posedge clk) rst |-> (ex_a==32'b0 && ex_b==32'b0 && ex_d2==32'b0 &&
                                ex_td==5'b0 && ex_Aluc==5'b0 &&
                                ex_WREG==1'b0 && ex_WMEM==1'b0 && ex_LW==1'b0 &&
                                ex_instr==32'b100000)
    );

    ///// Flush behavior (BJ) /////
    // If BJ is asserted, next cycle EX regs clear to 0 and ex_instr to 32'b100000.
    check_flush_clears_outputs: assert property (
        @(posedge clk) disable iff (rst)
            BJ |=> (ex_a==32'b0 && ex_b==32'b0 && ex_d2==32'b0 &&
                    ex_td==5'b0 && ex_Aluc==5'b0 &&
                    ex_WREG==1'b0 && ex_WMEM==1'b0 && ex_LW==1'b0 &&
                    ex_instr==32'b100000)
    );

    ///// Pass-through behavior when not flushing /////
    // When BJ is 0, ex_a captures id_a in the next cycle.
    check_pass_through_ex_a: assert property (
        @(posedge clk) disable iff (rst) (!BJ) |=> (ex_a == $past(id_a))
    );
    // When BJ is 0, ex_b captures id_b in the next cycle.
    check_pass_through_ex_b: assert property (
        @(posedge clk) disable iff (rst) (!BJ) |=> (ex_b == $past(id_b))
    );
    // When BJ is 0, ex_d2 captures id_d2 in the next cycle.
    check_pass_through_ex_d2: assert property (
        @(posedge clk) disable iff (rst) (!BJ) |=> (ex_d2 == $past(id_d2))
    );
    // When BJ is 0, ex_td captures id_td in the next cycle.
    check_pass_through_ex_td: assert property (
        @(posedge clk) disable iff (rst) (!BJ) |=> (ex_td == $past(id_td))
    );
    // When BJ is 0, ex_Aluc captures id_Aluc in the next cycle.
    check_pass_through_ex_Aluc: assert property (
        @(posedge clk) disable iff (rst) (!BJ) |=> (ex_Aluc == $past(id_Aluc))
    );
    // When BJ is 0, ex_WREG captures id_WREG in the next cycle.
    check_pass_through_ex_WREG: assert property (
        @(posedge clk) disable iff (rst) (!BJ) |=> (ex_WREG == $past(id_WREG))
    );
    // When BJ is 0, ex_WMEM captures id_WMEM in the next cycle.
    check_pass_through_ex_WMEM: assert property (
        @(posedge clk) disable iff (rst) (!BJ) |=> (ex_WMEM == $past(id_WMEM))
    );
    // When BJ is 0, ex_LW captures id_LW in the next cycle.
    check_pass_through_ex_LW: assert property (
        @(posedge clk) disable iff (rst) (!BJ) |=> (ex_LW == $past(id_LW))
    );
    // When BJ is 0, ex_instr captures id_instr in the next cycle.
    check_pass_through_ex_instr: assert property (
        @(posedge clk) disable iff (rst) (!BJ) |=> (ex_instr == $past(id_instr))
    );
endmodule

rtl:
module calculator(a, b, op, result);

  input [7:0] a;
  input [7:0] b;
  input [1:0] op;
  output reg [7:0] result;

  always @(*) begin
    case(op)
      2'b00: result = a + b;
      2'b01: result = a - b;
      2'b10: result = a * b;
      2'b11: result = a / b;
    endcase
  end

endmodule

sva:
module calculator_sva (
    input logic [7:0] a,
    input logic [7:0] b,
    input logic [1:0] op,
    input logic [7:0] result
);
    // No explicit clock/reset; combinational DUT; sample assertions on posedge of op[0].

    // When op==00, result equals a + b (8-bit wrap).
    check_add_result: assert property (
        @(posedge op[0]) (op == 2'b00) |-> (result == (a + b))
    );

    // When op==01, result equals a - b (8-bit wrap).
    check_sub_result: assert property (
        @(posedge op[0]) (op == 2'b01) |-> (result == (a - b))
    );

    // When op==10, result equals low 8 bits of a * b.
    check_mul_result: assert property (
        @(posedge op[0]) (op == 2'b10) |-> (result == (a * b)[7:0])
    );

    // When op==11 and b!=0, result equals a / b.
    check_div_result_nonzero: assert property (
        @(posedge op[0]) ((op == 2'b11) && (b != 8'd0)) |-> (result == (a / b))
    );

    // Result is stable if a, b, and op are unchanged.
    check_stable_when_inputs_stable: assert property (
        @(posedge op[0]) (a == $past(a) && b == $past(b) && op == $past(op)) |-> (result == $past(result))
    );
endmodule

rtl:
module mux_16bit(
    input [15:0] a,
    input [15:0] b,
    input sel,
    output [15:0] out
);

    assign out = (sel == 1'b0) ? a : b;

endmodule

sva:
module mux_16bit_sva (
    input logic clk,
    input logic [15:0] a,
    input logic [15:0] b,
    input logic sel,
    input logic [15:0] out
);
    // When sel==0, out must equal a.
    check_sel0_routes_a: assert property (
        @(posedge clk) (sel == 1'b0) |-> (out == a)
    );

    // When sel==1, out must equal b.
    check_sel1_routes_b: assert property (
        @(posedge clk) (sel == 1'b1) |-> (out == b)
    );

    // If a and b are equal, out must equal that value regardless of sel.
    check_equal_inputs_passthrough: assert property (
        @(posedge clk) (a == b) |-> (out == a)
    );

    // With sel==0 held stable and a stable, out remains stable.
    check_out_stable_when_sel0_and_a_stable: assert property (
        @(posedge clk) (sel == 1'b0) && $stable(sel) && $stable(a) |-> $stable(out)
    );

    // With sel==1 held stable and b stable, out remains stable.
    check_out_stable_when_sel1_and_b_stable: assert property (
        @(posedge clk) (sel == 1'b1) && $stable(sel) && $stable(b) |-> $stable(out)
    );

    // With sel==0 held stable, any change on a must change out.
    check_out_follows_a_when_sel0_and_a_changes: assert property (
        @(posedge clk) (sel == 1'b0) && $stable(sel) && $changed(a) |-> $changed(out)
    );

    // With sel==1 held stable, any change on b must change out.
    check_out_follows_b_when_sel1_and_b_changes: assert property (
        @(posedge clk) (sel == 1'b1) && $stable(sel) && $changed(b) |-> $changed(out)
    );

    // If sel toggles while a and b are stable and differ, out must change.
    check_out_changes_on_sel_toggle_when_inputs_differ: assert property (
        @(posedge clk) $changed(sel) && $stable(a) && $stable(b) && (a != b) |-> $changed(out)
    );

    // With sel==0 held stable and a stable, changes on b must not affect out.
    check_unselected_b_change_no_effect_when_sel0: assert property (
        @(posedge clk) (sel == 1'b0) && $stable(sel) && $stable(a) && $changed(b) |-> $stable(out)
    );

    // With sel==1 held stable and b stable, changes on a must not affect out.
    check_unselected_a_change_no_effect_when_sel1: assert property (
        @(posedge clk) (sel == 1'b1) && $stable(sel) && $stable(b) && $changed(a) |-> $stable(out)
    );
endmodule

rtl:
module mux_2_to_1 (
    input a,
    input b,
    input sel,
    output out
);

    wire w1;

    assign w1 = ~sel & a;
    assign out = sel & b | w1;

endmodule

sva:
module mux_2_to_1_sva (
    input logic clk,   // external sampling clock for SVA
    input logic a,
    input logic b,
    input logic sel,
    input logic out,
    input logic w1
);
    // Clocks: none in RTL; Reset: none; Logic: pure combinational.
    // Key behavior: out = (sel ? b : a); w1 = (~sel & a). Assertions sampled on clk.

    // w1 equals ~sel & a.
    check_w1_definition: assert property (
        @(posedge clk) w1 == ((~sel) & a)
    );

    // out equals (sel & b) | w1.
    check_out_sum_of_terms: assert property (
        @(posedge clk) out == ((sel & b) | w1)
    );

    // When sel=1, out must equal b.
    check_sel1_routes_b: assert property (
        @(posedge clk) sel |-> (out == b)
    );

    // When sel=0, out must equal a.
    check_sel0_routes_a: assert property (
        @(posedge clk) (~sel) |-> (out == a)
    );

    // If sel=1 then w1 must be 0.
    check_w1_zero_when_sel1: assert property (
        @(posedge clk) sel |-> (w1 == 1'b0)
    );

    // If a=0 then w1 must be 0.
    check_w1_zero_when_a0: assert property (
        @(posedge clk) (~a) |-> (w1 == 1'b0)
    );

    // If sel=1 and b=1 then out must be 1.
    check_out1_when_sel1_b1: assert property (
        @(posedge clk) (sel & b) |-> (out == 1'b1)
    );

    // If sel=1 and b=0 then out must be 0.
    check_out0_when_sel1_b0: assert property (
        @(posedge clk) (sel & (~b)) |-> (out == 1'b0)
    );

    // If sel=0 and a=1 then out must be 1.
    check_out1_when_sel0_a1: assert property (
        @(posedge clk) ((~sel) & a) |-> (out == 1'b1)
    );

    // If sel=0 and a=0 then out must be 0.
    check_out0_when_sel0_a0: assert property (
        @(posedge clk) ((~sel) & (~a)) |-> (out == 1'b0)
    );
