module myDFF (CK, D, RN, SN, Q, QN);
input  CK ;
input  D ;
input  RN ;
input  SN ;
output Q ;
output QN ;
reg Q;

always @ (posedge CK) begin
    if (RN) begin
        Q <= 1'b0;
    end else if (SN) begin
        Q <= 1'b1;
    end else begin
        Q <= D;
    end
end

assign QN = ~Q;

endmodule

sva:
module myDFF_sva (
    input logic CK,
    input logic D,
    input logic RN,   // Active-HIGH synchronous reset
    input logic SN,   // Active-HIGH synchronous set
    input logic Q,
    input logic QN
);

    ///// Synchronous control behavior /////
    // When RN is asserted at a clock edge, Q must be 0 on the next cycle.
    check_sync_reset_drives_q0: assert property (
        @(posedge CK) RN |=> (Q == 1'b0)
    );

    // When SN is asserted (and RN is not), Q must be 1 on the next cycle.
    check_sync_set_drives_q1: assert property (
        @(posedge CK) disable iff (RN) SN |=> (Q == 1'b1)
    );

    // When neither RN nor SN is asserted, Q captures D on the next cycle.
    check_data_capture_when_no_ctrl: assert property (
        @(posedge CK) disable iff (RN) (!SN) |=> (Q == $past(D))
    );

    // RN has priority over SN when both are asserted; Q must be 0 next cycle.
    check_reset_priority_over_set: assert property (
        @(posedge CK) (RN && SN) |=> (Q == 1'b0)
    );

    ///// Complementary output /////
    // QN is always the bitwise complement of Q.
    check_qn_complements_q: assert property (
        @(posedge CK) (QN == ~Q)
    );

    // When neither RN nor SN is asserted, QN next equals inversion of current D.
    check_qn_reflects_d_on_data_capture: assert property (
        @(posedge CK) disable iff (RN) (!SN) |=> (QN == ~$past(D))
    );

    // When SN is asserted (and RN is not), QN must be 0 on the next cycle.
    check_qn_zero_on_set: assert property (
        @(posedge CK) disable iff (RN) SN |=> (QN == 1'b0)
    );

    // When RN is asserted, QN must be 1 on the next cycle.
    check_qn_one_on_reset: assert property (
        @(posedge CK) RN |=> (QN == 1'b1)
    );

endmodule

rtl:
module tone_generator (
  input clk,
  input rst,
  input [1:0] tone,
  output audio_out
);

parameter f_clk = 50_000_000; // frequency of the clock signal
parameter f_tone = 440; // frequency of the selected tone (default: A4)
parameter t_duration = 1; // duration of the tone in seconds (default: 1 second)

reg [31:0] tone_counter = 0;
reg [31:0] tone_duration = 0;
reg [31:0] sample_counter = 0;
reg [31:0] sample_period = 0;
reg [1:0] tone_type = 2'b00; // default: sine wave

wire tone_signal;

// DTMF tone generation
always @ (posedge clk) begin
  if (rst) begin
    tone_counter <= 0;
    tone_duration <= 0;
    sample_counter <= 0;
    sample_period <= 0;
    tone_type <= 2'b00;
  end else begin
    // Check if tone is selected
    if (tone != 2'b00) begin
      // A new tone is selected
      if (tone != tone_type) begin
        tone_counter <= 0;
        tone_duration <= t_duration * f_clk;
        sample_counter <= 0;
        sample_period <= f_clk / f_tone;
        tone_type <= tone;
      end else begin // Same tone is selected
        // Check if tone duration is reached
        if (tone_counter >= tone_duration) begin
          tone_counter <= 0;
          tone_duration <= 0;
          sample_counter <= 0;
          sample_period <= 0;
          tone_type <= 2'b00;
        end else begin
          tone_counter <= tone_counter + 1;
          sample_counter <= sample_counter + 1;
          // Check if a new sample is needed
          if (sample_counter >= sample_period) begin
            sample_counter <= 0;
          end
        end
      end
    end else begin // No tone is selected
      tone_counter <= 0;
      tone_duration <= 0;
      sample_counter <= 0;
      sample_period <= 0;
      tone_type <= 2'b00;
    end
  end
end

// Sine wave generation
assign tone_signal = (tone_counter >= (f_clk / (2 * f_tone))) ? 1'b1 : 1'b0;

// Audio output
assign audio_out = tone_signal;

endmodule

sva:
module tone_generator_sva #(
    parameter int unsigned f_clk = 50_000_000,
    parameter int unsigned f_tone = 440,
    parameter int unsigned t_duration = 1
) (
    input  logic        clk,
    input  logic        rst,
    input  logic [1:0]  tone,
    input  logic        audio_out,

    // Internal DUT signals
    input  logic [31:0] tone_counter,
    input  logic [31:0] tone_duration,
    input  logic [31:0] sample_counter,
    input  logic [31:0] sample_period,
    input  logic [1:0]  tone_type
);
    localparam int unsigned HALF_PERIOD    = f_clk / (2 * f_tone);
    localparam int unsigned DURATION_TICKS = t_duration * f_clk;

    ///// Reset behavior /////
    // Synchronous active-HIGH reset clears all internal state.
    reset_clears_state: assert property (
        @(posedge clk) rst |-> (tone_counter == 32'd0) && (tone_duration == 32'd0) &&
                           (sample_counter == 32'd0) && (sample_period == 32'd0) &&
                           (tone_type == 2'b00)
    );
    // During reset, audio_out is LOW (tone_counter is 0 and threshold > 0).
    reset_audio_low: assert property (
        @(posedge clk) rst |-> (audio_out == 1'b0)
    );

    ///// Idle behavior (no tone selected) /////
    // When tone==00, all counters/periods clear and no tone is latched.
    idle_clears_state: assert property (
        @(posedge clk) disable iff (rst)
            (tone == 2'b00) |-> (tone_counter == 32'd0) && (tone_duration == 32'd0) &&
                               (sample_counter == 32'd0) && (sample_period == 32'd0) &&
                               (tone_type == 2'b00)
    );
    // When tone==00, audio_out is LOW.
    idle_audio_low: assert property (
        @(posedge clk) disable iff (rst)
            (tone == 2'b00) |-> (audio_out == 1'b0)
    );

    ///// New tone selection /////
    // On new non-zero tone selection, initialize duration/period and clear counters.
    new_tone_initializes_state: assert property (
        @(posedge clk) disable iff (rst)
            (tone != 2'b00) && (tone != $past(tone_type))
            |-> (tone_counter == 32'd0) && (sample_counter == 32'd0) &&
                (tone_duration == DURATION_TICKS) && (sample_period == (f_clk / f_tone)) &&
                (tone_type == tone)
    );

    ///// Active tone behavior /////
    // When current tone duration reached, clear state and deselect tone.
    end_of_tone_clears_state: assert property (
        @(posedge clk) disable iff (rst)
            (tone != 2'b00) && (tone == $past(tone_type)) && ($past(tone_counter) >= $past(tone_duration))
            |-> (tone_counter == 32'd0) && (tone_duration == 32'd0) &&
                (sample_counter == 32'd0) && (sample_period == 32'd0) &&
                (tone_type == 2'b00)
    );
    // While active (same tone) and not finished, tone_counter increments by 1.
    active_increments_tone_counter: assert property (
        @(posedge clk) disable iff (rst)
            (tone != 2'b00) && (tone == $past(tone_type)) && ($past(tone_counter) < $past(tone_duration))
            |-> (tone_counter == $past(tone_counter) + 32'd1)
    );
    // sample_counter increments when below sample_period during active tone.
    active_increments_sample_counter: assert property (
        @(posedge clk) disable iff (rst)
            (tone != 2'b00) && (tone == $past(tone_type)) &&
            ($past(tone_counter) < $past(tone_duration)) &&
            ($past(sample_counter) < $past(sample_period))
            |-> (sample_counter == $past(sample_counter) + 32'd1)
    );
    // sample_counter resets to 0 when it reaches/exceeds sample_period.
    active_resets_sample_counter: assert property (
        @(posedge clk) disable iff (rst)
            (tone != 2'b00) && (tone == $past(tone_type)) &&
            ($past(tone_counter) < $past(tone_duration)) &&
            ($past(sample_counter) >= $past(sample_period))
            |-> (sample_counter == 32'd0)
    );
    // sample_period and tone_duration hold constant while active.
    active_holds_period_and_duration: assert property (
        @(posedge clk) disable iff (rst)
            (tone != 2'b00) && (tone == $past(tone_type)) && ($past(tone_counter) < $past(tone_duration))
            |-> (sample_period == $past(sample_period)) && (tone_duration == $past(tone_duration))
    );
    // tone_type holds and equals input while active.
    active_holds_tone_type: assert property (
        @(posedge clk) disable iff (rst)
            (tone != 2'b00) && (tone == $past(tone_type)) && ($past(tone_counter) < $past(tone_duration))
            |-> (tone_type == $past(tone_type)) && (tone_type == tone)
    );
    // sample_counter never exceeds sample_period while active.
    active_sample_counter_bound: assert property (
        @(posedge clk) disable iff (rst)
            (tone != 2'b00) && (tone == $past(tone_type)) && ($past(tone_counter) < $past(tone_duration))
            |-> (sample_counter <= sample_period)
    );

    ///// Output mapping /////
    // audio_out equals (tone_counter >= f_clk/(2*f_tone)).
    audio_out_matches_comparator: assert property (
        @(posedge clk) disable iff (rst)
            audio_out == (tone_counter >= HALF_PERIOD)
    );

endmodule

module binary_counter_sva (
    input logic CLK,
    input logic RST,
    input logic [3:0] Q
);
    ///// Reset behavior /////
    // When RST is asserted, Q must be 0 on the next clock.
    reset_forces_zero_next: assert property (
        @(posedge CLK) RST |=> (Q == 4'h0)
    );

    ///// Counting behavior (disabled during reset) /////
    // When not at max, Q increments by 1 on the next clock.
    count_increments_when_not_max: assert property (
        @(posedge CLK) disable iff (RST) (Q != 4'hF) |=> (Q == $past(Q) + 1'b1)
    );

    // When at max, Q wraps to 0 on the next clock.
    count_wraps_when_max: assert property (
        @(posedge CLK) disable iff (RST) (Q == 4'hF) |=> (Q == 4'h0)
    );

    // LSB toggles every cycle when not in reset.
    lsb_toggles_without_reset: assert property (
        @(posedge CLK) disable iff (RST) 1'b1 |=> (Q[0] == ~$past(Q[0]))
    );
endmodule

rtl:
module NAND4X0 (input IN1, IN2, IN3, IN4, output QN, input VDD, VSS);
  wire nand1, nand2, nand3;

  assign nand1 = ~(IN1 & IN2);
  assign nand2 = ~(IN3 & IN4);
  assign nand3 = ~(nand1 & nand2);

  assign QN = nand3;
endmodule

sva:
module NAND4X0_sva (
    input logic clk,
    input logic IN1,
    input logic IN2,
    input logic IN3,
    input logic IN4,
    input logic QN,
    input logic VDD,
    input logic VSS
);
    // QN equals (IN1&IN2) OR (IN3&IN4).
    check_qn_function: assert property (
        @(posedge clk) QN == ((IN1 & IN2) | (IN3 & IN4))
    );

    // If IN1 and IN2 are HIGH, QN must be HIGH.
    check_pair12_implies_high: assert property (
        @(posedge clk) (IN1 && IN2) |-> QN
    );

    // If IN3 and IN4 are HIGH, QN must be HIGH.
    check_pair34_implies_high: assert property (
        @(posedge clk) (IN3 && IN4) |-> QN
    );

    // If neither pair is both HIGH, QN must be LOW.
    check_both_pairs_not_high_implies_low: assert property (
        @(posedge clk) (!(IN1 && IN2) && !(IN3 && IN4)) |-> !QN
    );

    // If QN is LOW, neither pair can be both HIGH.
    check_low_implies_no_pair_high: assert property (
        @(posedge clk) !QN |-> (!(IN1 && IN2) && !(IN3 && IN4))
    );

    // If QN is HIGH, at least one pair is both HIGH.
    check_high_implies_some_pair_high: assert property (
        @(posedge clk) QN |-> ((IN1 && IN2) || (IN3 && IN4))
    );

    // If all four inputs are stable, QN must be stable (pure combinational).
    check_stability_with_stable_inputs: assert property (
        @(posedge clk) $stable({IN1,IN2,IN3,IN4}) |-> $stable(QN)
    );

    // QN changes only if at least one of the four inputs changes.
    check_output_change_requires_input_change: assert property (
        @(posedge clk) $changed(QN) |-> !$stable({IN1,IN2,IN3,IN4})
    );

    // Changes on VDD/VSS do not affect QN when data inputs are stable.
    check_power_pins_no_effect: assert property (
        @(posedge clk) ($changed(VDD) || $changed(VSS)) && $stable({IN1,IN2,IN3,IN4}) |-> $stable(QN)
    );

    // If all inputs are LOW, QN must be LOW.
    check_all_zero_implies_low: assert property (
        @(posedge clk) (!IN1 && !IN2 && !IN3 && !IN4) |-> !QN
    );
endmodule

module xor_32_sva (
    input logic CLK,
    input logic [31:0] X,
    input logic [31:0] Y,
    input logic [31:0] Dout
);
    // Clock: CLK (posedge). No reset in RTL; mask first cycle with $initstate.
    // Sequential: Dout is a 1-cycle-registered XOR of X and Y.

    // Dout equals previous cycle's bitwise XOR of X and Y.
    check_dout_pipeline_xor: assert property (
        @(posedge CLK) disable iff ($initstate) (Dout == $past(X ^ Y))
    );

    // If X equals Y in this cycle, Dout is zero next cycle.
    check_zero_when_inputs_equal: assert property (
        @(posedge CLK) disable iff ($initstate) (X == Y) |=> (Dout == 32'b0)
    );

    // If X is bitwise complement of Y in this cycle, Dout is all ones next cycle.
    check_allones_when_inputs_complementary: assert property (
        @(posedge CLK) disable iff ($initstate) (X == ~Y) |=> (Dout == 32'hFFFF_FFFF)
    );

    // If Y is zero in this cycle, Dout equals prior X next cycle.
    check_prevY_zero_passes_prevX: assert property (
        @(posedge CLK) disable iff ($initstate) (Y == 32'b0) |=> (Dout == $past(X))
    );

    // If X is zero in this cycle, Dout equals prior Y next cycle.
    check_prevX_zero_passes_prevY: assert property (
        @(posedge CLK) disable iff ($initstate) (X == 32'b0) |=> (Dout == $past(Y))
    );

    // If Y is all ones in this cycle, Dout equals bitwise NOT of prior X next cycle.
    check_prevY_ones_inverts_prevX: assert property (
        @(posedge CLK) disable iff ($initstate) (Y == 32'hFFFF_FFFF) |=> (Dout == ~ $past(X))
    );

    // If X is all ones in this cycle, Dout equals bitwise NOT of prior Y next cycle.
    check_prevX_ones_inverts_prevY: assert property (
        @(posedge CLK) disable iff ($initstate) (X == 32'hFFFF_FFFF) |=> (Dout == ~ $past(Y))
    );

endmodule

rtl:
module barrel_shifter (
    input [3:0] data,
    input shift_left,
    input shift_right,
    input rotate_right,
    output [3:0] shifted_data
);

reg [3:0] stage1_data;
reg [3:0] stage2_data;

always @(*) begin
    stage1_data = shift_left ? {data[2:0], 1'b0} : {1'b0, data[3:1]};
end

always @(*) begin
    stage2_data = shift_right ? {1'b0, stage1_data[3:1]} : (rotate_right ? {stage1_data[0], stage1_data[3:1]} : stage1_data);
end

assign shifted_data = stage2_data;

endmodule

sva:
module barrel_shifter_sva (
    input logic clk,                // Sampling clock for SVA (RTL has no clock/reset)
    input logic [3:0] data,
    input logic shift_left,
    input logic shift_right,
    input logic rotate_right,
    input logic [3:0] shifted_data
);
    ///// Functional equivalence checks /////
    // When shift_right=1, output is right shift of stage1_data (priority over rotate_right).
    check_shift_right_full: assert property (
        @(posedge clk)
        shift_right |-> (shifted_data == {1'b0,
                                          (shift_left ? data[2] : 1'b0),
                                          (shift_left ? data[1] : data[3]),
                                          (shift_left ? data[0] : data[2])})
    );

    // When !shift_right && rotate_right=1, output is rotate-right of stage1_data.
    check_rotate_right_full: assert property (
        @(posedge clk)
        (!shift_right && rotate_right) |-> (shifted_data == {(shift_left ? 1'b0 : data[1]),
                                                            (shift_left ? data[2] : 1'b0),
                                                            (shift_left ? data[1] : data[3]),
                                                            (shift_left ? data[0] : data[2])})
    );

    // When !shift_right && !rotate_right, output passes stage1_data.
    check_passthrough_full: assert property (
        @(posedge clk)
        (!shift_right && !rotate_right) |-> (shifted_data == (shift_left ? {data[2:0], 1'b0}
                                                                        : {1'b0, data[3:1]}))
    );

    ///// Bit-level invariants /////
    // In shift_right path, MSB is zero-filled.
    check_shift_right_msb_zero: assert property (
        @(posedge clk)
        shift_right |-> (shifted_data[3] == 1'b0)
    );

    // In rotate_right path, MSB comes from stage1_data[0].
    check_rotate_right_msb_mapping: assert property (
        @(posedge clk)
        (!shift_right && rotate_right) |-> (shifted_data[3] == (shift_left ? 1'b0 : data[1]))
    );

    // In passthrough path, LSB equals stage1_data[0].
    check_passthrough_lsb_mapping: assert property (
        @(posedge clk)
        (!shift_right && !rotate_right) |-> (shifted_data[0] == (shift_left ? 1'b0 : data[1]))
    );

    // In rotate_right path, LSB equals stage1_data[1].
    check_rotate_right_lsb_mapping: assert property (
        @(posedge clk)
        (!shift_right && rotate_right) |-> (shifted_data[0] == (shift_left ? data[0] : data[2]))
    );

    // In passthrough path, MSB equals stage1_data[3].
    check_passthrough_msb_mapping: assert property (
        @(posedge clk)
        (!shift_right && !rotate_right) |-> (shifted_data[3] == (shift_left ? data[2] : 1'b0))
    );

    // In shift_right path, bit[1] maps from stage1_data[2].
    check_shift_right_bit1_mapping: assert property (
        @(posedge clk)
        shift_right |-> (shifted_data[1] == (shift_left ? data[1] : data[3]))
    );

    // In rotate_right path, bit[2] maps from stage1_data[2].
    check_rotate_right_bit2_mapping: assert property (
        @(posedge clk)
        (!shift_right && rotate_right) |-> (shifted_data[2] == (shift_left ? data[1] : data[3]))
    );

    ///// Priority/independence /////
    // With shift_right held high and other used inputs stable, output is independent of rotate_right.
    check_shift_right_independent_of_rotate: assert property (
        @(posedge clk)
        (shift_right && $stable({data, shift_left, shift_right})) |-> $stable(shifted_data)
    );
endmodule

rtl:
module mux_2to1 (
    input A,
    input B,
    input SEL,
    output Y
);

    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;

    // Output assignment
    assign Y = SEL ? B : A;

endmodule

sva:
module mux_2to1_sva (
    input logic A,
    input logic B,
    input logic SEL,
    input logic Y
);
    // On A rising edge, Y must equal the mux function.
    check_func_on_A_rise: assert property (
        @(posedge A) Y == (SEL ? B : A)
    );
    // On A falling edge, Y must equal the mux function.
    check_func_on_A_fall: assert property (
        @(negedge A) Y == (SEL ? B : A)
    );
    // On B rising edge, Y must equal the mux function.
    check_func_on_B_rise: assert property (
        @(posedge B) Y == (SEL ? B : A)
    );
    // On B falling edge, Y must equal the mux function.
    check_func_on_B_fall: assert property (
        @(negedge B) Y == (SEL ? B : A)
    );
    // On SEL rising edge, Y must equal the mux function (select B).
    check_func_on_SEL_rise: assert property (
        @(posedge SEL) Y == (SEL ? B : A)
    );
    // On SEL falling edge, Y must equal the mux function (select A).
    check_func_on_SEL_fall: assert property (
        @(negedge SEL) Y == (SEL ? B : A)
    );

    // When SEL=0 and A rises, Y must go HIGH.
    track_Y_with_A_when_SEL0_rise: assert property (
        @(posedge A) (SEL == 1'b0) |-> (Y == 1'b1)
    );
    // When SEL=0 and A falls, Y must go LOW.
    track_Y_with_A_when_SEL0_fall: assert property (
        @(negedge A) (SEL == 1'b0) |-> (Y == 1'b0)
    );
    // When SEL=1 and B rises, Y must go HIGH.
    track_Y_with_B_when_SEL1_rise: assert property (
        @(posedge B) (SEL == 1'b1) |-> (Y == 1'b1)
    );
    // When SEL=1 and B falls, Y must go LOW.
    track_Y_with_B_when_SEL1_fall: assert property (
        @(negedge B) (SEL == 1'b1) |-> (Y == 1'b0)
    );
endmodule

rtl:
module main (val1, val2, result);

input [2:0] val1, val2;
output [2:0] result ;

assign result = (val1 == val2) ? val1 << 1 : 
               (val1 == 3'b000) ? 0 : 
               (val1 == 3'b001) ? 1 : 
               (val1 == 3'b010) ? 2 : 
               (val1 == 3'b011) ? 4 : 4;

endmodule

sva:
module main_sva (
    input logic [2:0] val1,
    input logic [2:0] val2,
    input logic [2:0] result
);
    // Result matches the exact ternary expression in RTL.
    check_function_equivalence: assert property (
        @(posedge val1[0] or posedge val1[1] or posedge val1[2] or posedge val2[0] or posedge val2[1] or posedge val2[2])
            result == ((val1 == val2) ? (val1 << 1) :
                      (val1 == 3'd0) ? 3'd0 :
                      (val1 == 3'd1) ? 3'd1 :
                      (val1 == 3'd2) ? 3'd2 :
                      (val1 == 3'd3) ? 3'd4 : 3'd4)
    );

    // When val1 equals val2, result is val1 shifted left by 1.
    check_equal_shift: assert property (
        @(posedge val1[0] or posedge val1[1] or posedge val1[2] or posedge val2[0] or posedge val2[1] or posedge val2[2])
            (val1 == val2) |-> (result == (val1 << 1))
    );

    // When val1 equals val2, LSB of result is zero (left shift property).
    check_equal_lsb_zero: assert property (
        @(posedge val1[0] or posedge val1[1] or posedge val1[2] or posedge val2[0] or posedge val2[1] or posedge val2[2])
            (val1 == val2) |-> (result[0] == 1'b0)
    );

    // When val1 != val2 and val1 == 0, result is 0.
    check_neq_val1_0: assert property (
        @(posedge val1[0] or posedge val1[1] or posedge val1[2] or posedge val2[0] or posedge val2[1] or posedge val2[2])
            ((val1 != val2) && (val1 == 3'd0)) |-> (result == 3'd0)
    );

    // When val1 != val2 and val1 == 1, result is 1.
    check_neq_val1_1: assert property (
        @(posedge val1[0] or posedge val1[1] or posedge val1[2] or posedge val2[0] or posedge val2[1] or posedge val2[2])
            ((val1 != val2) && (val1 == 3'd1)) |-> (result == 3'd1)
    );

    // When val1 != val2 and val1 == 2, result is 2.
    check_neq_val1_2: assert property (
        @(posedge val1[0] or posedge val1[1] or posedge val1[2] or posedge val2[0] or posedge val2[1] or posedge val2[2])
            ((val1 != val2) && (val1 == 3'd2)) |-> (result == 3'd2)
    );

    // When val1 != val2 and val1 == 3, result is 4.
    check_neq_val1_3: assert property (
        @(posedge val1[0] or posedge val1[1] or posedge val1[2] or posedge val2[0] or posedge val2[1] or posedge val2[2])
            ((val1 != val2) && (val1 == 3'd3)) |-> (result == 3'd4)
    );

    // When val1 != val2 and val1 >= 4, result is 4.
    check_neq_val1_ge4: assert property (
        @(posedge val1[0] or posedge val1[1] or posedge val1[2] or posedge val2[0] or posedge val2[1] or posedge val2[2])
            ((val1 != val2) && (val1 >= 3'd4)) |-> (result == 3'd4)
    );

    // When val1 != val2, result is restricted to {0,1,2,4}.
    check_neq_allowed_values: assert property (
        @(posedge val1[0] or posedge val1[1] or posedge val1[2] or posedge val2[0] or posedge val2[1] or posedge val2[2])
            (val1 != val2) |-> (result inside {3'd0,3'd1,3'd2,3'd4})
    );

    // Example: when equal and val1==3, result is 6 (3<<1 in 3-bit width).
    check_equal_example_val1_3: assert property (
        @(posedge val1[0] or posedge val1[1] or posedge val1[2] or posedge val2[0] or posedge val2[1] or posedge val2[2])
            ((val1 == val2) && (val1 == 3'd3)) |-> (result == 3'd6)
    );
endmodule

