rtl:
module RegisterAdd_4 (
  input clk,
  input rst,
  input load,
  input [3:0] D,
  output [3:0] Q
);

  reg [3:0] reg_out;
  wire [3:0] add_out;

  always @(posedge clk, posedge rst) begin
    if (rst) begin
      reg_out <= 4'b0;
    end else if (load) begin
      reg_out <= D;
    end else begin
      reg_out <= reg_out + D;
    end
  end

  assign Q = reg_out;

endmodule

sva:
module RegisterAdd_4_sva (
  input logic clk,
  input logic rst,
  input logic load,
  input logic [3:0] D,
  input logic [3:0] Q
);

  ///// Environment assumptions /////
  // Assume reset does not glitch between clock edges.
  assume_stable_reset: assume property (
    @(posedge clk) $stable(rst)
  );

  ///// Reset behavior /////
  // While reset is asserted, Q must be 0.
  reset_forces_zero: assert property (
    @(posedge clk) rst |-> (Q == 4'b0000)
  );

  ///// Load and accumulate behaviors /////
  // If load is HIGH, next Q equals current D.
  load_writes_D_to_Q: assert property (
    @(posedge clk) disable iff (rst) load |=> (Q == $past(D))
  );

  // If load is LOW, next Q equals current Q + D modulo 16.
  add_when_not_load: assert property (
    @(posedge clk) disable iff (rst) !load |=> (Q == (($past(Q) + $past(D))[3:0]))
  );

  // If load is LOW and D is 0, Q holds its value.
  hold_when_addend_zero: assert property (
    @(posedge clk) disable iff (rst) (!load && (D == 4'b0000)) |=> (Q == $past(Q))
  );

  // If load is HIGH and D is 0, Q becomes 0.
  load_zero_clears: assert property (
    @(posedge clk) disable iff (rst) (load && (D == 4'b0000)) |=> (Q == 4'b0000)
  );

  // If load is LOW and D is nonzero, Q must change (modulo 16).
  add_nonzero_changes_Q: assert property (
    @(posedge clk) disable iff (rst) (!load && (D != 4'b0000)) |=> (Q != $past(Q))
  );

  ///// Useful arithmetic corner checks (mod-16 wrap) /////
  // When Q=15 and D=1 with load LOW, next Q wraps to 0.
  wrap_15_plus_1_to_0: assert property (
    @(posedge clk) disable iff (rst) ($past(!load) && ($past(Q) == 4'hF) && ($past(D) == 4'h1)) |-> (Q == 4'h0)
  );

  // When Q=8 and D=8 with load LOW, next Q wraps to 0.
  wrap_8_plus_8_to_0: assert property (
    @(posedge clk) disable iff (rst) ($past(!load) && ($past(Q) == 4'h8) && ($past(D) == 4'h8)) |-> (Q == 4'h0)
  );

endmodule

module synchronous_counter_sva (
    input logic clk,
    input logic reset,
    input logic [3:0] count
);
    ///// Reset behavior /////
    // While reset is HIGH at a clock edge, count must be 0.
    check_reset_forces_zero: assert property (
        @(posedge clk) reset |-> (count == 4'd0)
    );

    ///// Normal counting behavior (when not in reset) /////
    // If last cycle was not reset and count <= 8, increment by 1.
    check_increment_when_below_9: assert property (
        @(posedge clk) disable iff (reset)
            (!$initstate && $past(!reset) && ($past(count) <= 4'd8)) |-> (count == $past(count) + 4'd1)
    );

    // If last cycle was not reset and count was 9, wrap to 0.
    check_wrap_from_9_to_0: assert property (
        @(posedge clk) disable iff (reset)
            (!$initstate && $past(!reset) && ($past(count) == 4'd9)) |-> (count == 4'd0)
    );

    // After at least one non-reset cycle, count must be within 0..9.
    check_range_after_nonreset: assert property (
        @(posedge clk) disable iff (reset)
            (!$initstate && $past(!reset)) |-> (count <= 4'd9)
    );

    // If not in reset now and previously not in reset, a zero must come from a wrap from 9.
    check_zero_only_from_wrap_no_reset: assert property (
        @(posedge clk) disable iff (reset)
            (!$initstate && !reset && $past(!reset) && (count == 4'd0)) |-> ($past(count) == 4'd9)
    );

    // If last cycle was not reset and count <= 8, the value must change (no hold).
    check_no_hold_when_below_9: assert property (
        @(posedge clk) disable iff (reset)
            (!$initstate && $past(!reset) && ($past(count) <= 4'd8)) |-> (count != $past(count))
    );

    ///// Reset release behavior /////
    // On reset falling edge, count is 0 this cycle and 1 on the next (if reset stays low).
    check_post_reset_first_increment: assert property (
        @(posedge clk) disable iff (reset)
            $fell(reset) |-> (count == 4'd0) ##1 (count == 4'd1)
    );

    ///// Periodicity /////
    // With no reset for 10 cycles, count repeats every 10 cycles.
    check_period_10_no_reset: assert property (
        @(posedge clk) disable iff (reset)
            1'b1 |-> ##10 (count == $past(count, 10))
    );
endmodule

rtl:
module adder_4bit_carry (
  input [3:0] a,
  input [3:0] b,
  input cin,
  output [3:0] sum,
  output cout
);

  wire [3:0] s; // intermediate sum
  wire c1, c2, c3; // intermediate carry signals

  // generate the intermediate sum and carry signals
  full_adder fa0(a[0], b[0], cin, s[0], c1);
  full_adder fa1(a[1], b[1], c1, s[1], c2);
  full_adder fa2(a[2], b[2], c2, s[2], c3);
  full_adder fa3(a[3], b[3], c3, s[3], cout);

  // assign the outputs
  assign sum = s;

endmodule

// full adder module
module full_adder (
  input a,
  input b,
  input cin,
  output sum,
  output cout
);

  assign sum = a ^ b ^ cin;
  assign cout = (a & b) | (a & cin) | (b & cin);

endmodule

sva:
module adder_4bit_carry_sva (
    input logic clk,
    input logic [3:0] a,
    input logic [3:0] b,
    input logic cin,
    input logic [3:0] sum,
    input logic cout
);
    ///// Functional correctness /////
    // Combined {cout,sum} equals arithmetic a + b + cin (5-bit).
    check_addition_result: assert property (
        @(posedge clk) {cout, sum} == ({1'b0, a} + {1'b0, b} + cin)
    );

    // LSB sum matches XOR of a[0], b[0], and cin.
    check_sum_lsb_xor: assert property (
        @(posedge clk) sum[0] == (a[0] ^ b[0] ^ cin)
    );

    // When inputs are all zero, outputs are zero.
    check_zero_inputs_zero_outputs: assert property (
        @(posedge clk) (a == 4'b0 && b == 4'b0 && cin == 1'b0) |-> (sum == 4'b0 && cout == 1'b0)
    );

    // Adding zero on b with cin=0 returns a and no carry.
    check_identity_b_zero_cin_zero: assert property (
        @(posedge clk) (b == 4'b0 && cin == 1'b0) |-> (sum == a && cout == 1'b0)
    );

    // Adding zero on a with cin=0 returns b and no carry.
    check_identity_a_zero_cin_zero: assert property (
        @(posedge clk) (a == 4'b0 && cin == 1'b0) |-> (sum == b && cout == 1'b0)
    );

    // With b==0, result equals a + cin (proper 5-bit sum).
    check_b_zero_add_cin: assert property (
        @(posedge clk) (b == 4'b0) |-> ({cout, sum} == ({1'b0, a} + cin))
    );

    ///// Stability properties /////
    // If inputs are stable across a cycle, outputs remain stable.
    check_stable_inputs_hold_outputs: assert property (
        @(posedge clk) $stable({a, b, cin}) |-> $stable({sum, cout})
    );

    // Outputs can change only if at least one input changed.
    check_output_change_requires_input_change: assert property (
        @(posedge clk) $changed({sum, cout}) |-> $changed({a, b, cin})
    );

    ///// Corner cases /////
    // Max operands with cin=0 produce sum=14 and carry=1.
    check_max_plus_zero: assert property (
        @(posedge clk) (a == 4'hF && b == 4'hF && cin == 1'b0) |-> (sum == 4'he && cout == 1'b1)
    );

    // Max operands with cin=1 produce sum=15 and carry=1.
    check_max_plus_one: assert property (
        @(posedge clk) (a == 4'hF && b == 4'hF && cin == 1'b1) |-> (sum == 4'hf && cout == 1'b1)
    );

    ///// Symmetry /////
    // Swapping a and b between cycles (with same cin) leaves {cout,sum} unchanged.
    check_commutativity_swap_invariance: assert property (
        @(posedge clk) (a == $past(b) && b == $past(a) && cin == $past(cin)) |-> ({cout, sum} == $past({cout, sum}))
    );

    // When a[0]==b[0], LSB of sum equals cin.
    check_lsb_when_a0_eq_b0: assert property (
        @(posedge clk) (a[0] == b[0]) |-> (sum[0] == cin)
    );
endmodule

rtl:
module decoder_3to8 (
    input wire clk,
    input wire [2:0] abc,
    output reg [7:0] y
);

    always @(posedge clk) begin
        y <= 8'b00000001 << abc;
    end

endmodule

sva:
module decoder_3to8_sva (
    input logic clk,
    input logic [2:0] abc,
    input logic [7:0] y
);
    // y equals the one-hot decode of abc from the previous cycle.
    check_decode_matches_prev_abc: assert property (
        @(posedge clk) $past(1'b1) |-> (y == (8'b00000001 << $past(abc)))
    );

    // y is non-zero and one-hot each cycle (after the first).
    check_y_onehot: assert property (
        @(posedge clk) $past(1'b1) |-> (y != 8'b00000000) && ((y & (y - 8'b00000001)) == 8'b00000000)
    );

    // If abc is unchanged across a cycle, y remains unchanged in the next cycle.
    check_stability_when_abc_stable: assert property (
        @(posedge clk) ($past(1'b1) && (abc == $past(abc))) |-> ##1 (y == $past(y))
    );

    // If abc changes across a cycle, y changes in the next cycle.
    check_change_propagation: assert property (
        @(posedge clk) ($past(1'b1) && (abc != $past(abc))) |-> ##1 (y != $past(y))
    );

    // When previous abc was 0, y is 00000001.
    check_low_boundary_decode: assert property (
        @(posedge clk) ($past(1'b1) && ($past(abc) == 3'd0)) |-> (y == 8'b00000001)
    );

    // When previous abc was 7, y is 10000000.
    check_high_boundary_decode: assert property (
        @(posedge clk) ($past(1'b1) && ($past(abc) == 3'd7)) |-> (y == 8'b10000000)
    );
endmodule

rtl:
module interrupt(
	input clock,

	input IEN_d,
	input IOF_d,
	input RTI_d,
	input branch_d,
	input IRQ,
	input [11:0] PC,

	output reg branch_ISR,
	output reg [11:0] ISR_adr
	);

	reg [11:0] return_adr;

	reg IEN_reg;
	reg IRQ_reg;
	reg I;

	initial begin
		IEN_reg = 0;
		return_adr = 0;
	end


	always @(posedge clock) begin
		if (IEN_d == 1)
			IEN_reg = 1;
		if (IOF_d == 1)
			IEN_reg = 0;

		if (I == 1) begin
			IEN_reg = 0;
			return_adr = PC;
		end

		IRQ_reg = IRQ;
	end

	always @(*) begin
		I <= IEN_reg & IRQ_reg & ~branch_d;
		if (I == 1) begin
			branch_ISR <= 1;
			ISR_adr <= 12'h1;
		end
		else if (RTI_d == 1) begin
			branch_ISR <= 1;
			ISR_adr <= return_adr;
		end
		else begin
			branch_ISR <= 0;
			ISR_adr <= 0;
		end
	end



endmodule

sva:
module interrupt_sva (
    input logic clock,

    input logic IEN_d,
    input logic IOF_d,
    input logic RTI_d,
    input logic branch_d,
    input logic IRQ,
    input logic [11:0] PC,

    input logic branch_ISR,
    input logic [11:0] ISR_adr,

    // Internal DUT signals
    input logic [11:0] return_adr,
    input logic IEN_reg,
    input logic IRQ_reg,
    input logic I
);
    // IRQ_reg must capture IRQ on every rising edge.
    check_irq_reg_captures_IRQ: assert property (
        @(posedge clock) (IRQ_reg == IRQ)
    );

    // IEN_reg is cleared when an interrupt is taken (I=1).
    check_IEN_reg_cleared_on_interrupt: assert property (
        @(posedge clock) (I == 1'b1) |-> (IEN_reg == 1'b0)
    );

    // IEN_reg is cleared when IOF_d is asserted and no interrupt is taken.
    check_IEN_reg_cleared_on_IOF_only: assert property (
        @(posedge clock) (IOF_d == 1'b1 && I == 1'b0) |-> (IEN_reg == 1'b0)
    );

    // IEN_reg is set when IEN_d is asserted and no clear condition applies.
    check_IEN_reg_set_on_IEN_only: assert property (
        @(posedge clock) (IEN_d == 1'b1 && IOF_d == 1'b0 && I == 1'b0) |-> (IEN_reg == 1'b1)
    );

    // return_adr captures PC when an interrupt is taken.
    check_return_adr_captured_on_interrupt: assert property (
        @(posedge clock) (I == 1'b1) |-> (return_adr == PC)
    );

    // branch_ISR is asserted iff I or RTI_d is true.
    check_branch_ISR_definition: assert property (
        @(posedge clock) (branch_ISR == (I || RTI_d))
    );

    // On interrupt, ISR_adr must be vector 12'h1.
    check_ISR_adr_on_interrupt: assert property (
        @(posedge clock) (I == 1'b1) |-> (ISR_adr == 12'h001)
    );

    // On RTI only (no interrupt), ISR_adr must be return_adr.
    check_ISR_adr_on_RTI_only: assert property (
        @(posedge clock) (I == 1'b0 && RTI_d == 1'b1) |-> (ISR_adr == return_adr)
    );

    // With no event (no I, no RTI), outputs are deasserted/zero.
    check_ISR_default_when_no_event: assert property (
        @(posedge clock) (I == 1'b0 && RTI_d == 1'b0) |-> (branch_ISR == 1'b0 && ISR_adr == 12'h000)
    );

    // branch_ISR low implies ISR_adr is zero.
    check_branch_zero_implies_zero_addr: assert property (
        @(posedge clock) (branch_ISR == 1'b0) |-> (ISR_adr == 12'h000)
    );

    // I can be high only if IEN_reg and IRQ_reg are high and branch_d is low.
    check_I_high_requires_inputs: assert property (
        @(posedge clock) (I == 1'b1) |-> (IEN_reg == 1'b1 && IRQ_reg == 1'b1 && branch_d == 1'b0)
    );

    // I must be low when IEN_reg is low.
    check_I_low_when_IEN_reg_zero: assert property (
        @(posedge clock) (IEN_reg == 1'b0) |-> (I == 1'b0)
    );

    // I must be low when IRQ_reg is low.
    check_I_low_when_IRQ_reg_zero: assert property (
        @(posedge clock) (IRQ_reg == 1'b0) |-> (I == 1'b0)
    );

    // I must be low when branch_d is high.
    check_I_low_when_branch_d_one: assert property (
        @(posedge clock) (branch_d == 1'b1) |-> (I == 1'b0)
    );
endmodule

module match_sva (
    input  logic        clk,
    input  logic [15:0] vec_i,
    input  logic        b8_i,
    input  logic        b12_i,
    input  logic        match1_o,
    input  logic        match2_o
);
    // match1_o equals the defined conjunction of selected bits and inputs.
    check_match1_definition: assert property (
        @(posedge clk) match1_o == ((vec_i[15:14] == 2'b00) && (vec_i[11] == 1'b0) && (vec_i[7] == b8_i) && (vec_i[3] == b12_i))
    );
    // match2_o equals the defined conjunction of selected bits and inputs.
    check_match2_definition: assert property (
        @(posedge clk) match2_o == ((vec_i[15:14] == 2'b00) && (vec_i[7] == b8_i) && (vec_i[3] == b12_i) && (vec_i[11] == 1'b0))
    );
    // The two outputs are always identical.
    check_outputs_equivalent: assert property (
        @(posedge clk) (match1_o == match2_o)
    );
    // If match1_o is HIGH, the required conditions hold.
    check_match1_high_requires_conditions: assert property (
        @(posedge clk) match1_o |-> ((vec_i[15:14] == 2'b00) && (vec_i[11] == 1'b0) && (vec_i[7] == b8_i) && (vec_i[3] == b12_i))
    );
    // If match2_o is HIGH, the required conditions hold.
    check_match2_high_requires_conditions: assert property (
        @(posedge clk) match2_o |-> ((vec_i[15:14] == 2'b00) && (vec_i[7] == b8_i) && (vec_i[3] == b12_i) && (vec_i[11] == 1'b0))
    );
    // When all conditions hold, both outputs are HIGH.
    check_conditions_imply_both_high: assert property (
        @(posedge clk) ((vec_i[15:14] == 2'b00) && (vec_i[11] == 1'b0) && (vec_i[7] == b8_i) && (vec_i[3] == b12_i)) |-> (match1_o && match2_o)
    );
    // Outputs remain stable if all inputs are stable.
    check_stable_when_all_inputs_stable: assert property (
        @(posedge clk) $stable({vec_i, b8_i, b12_i}) |-> $stable({match1_o, match2_o})
    );
    // Outputs depend only on vec_i[15:14], vec_i[11], vec_i[7], vec_i[3], b8_i, and b12_i.
    check_stable_when_relevant_subset_stable: assert property (
        @(posedge clk) $stable({vec_i[15:14], vec_i[11], vec_i[7], vec_i[3], b8_i, b12_i}) |-> $stable({match1_o, match2_o})
    );
    // If vec_i[15:14] != 2'b00, both outputs are LOW.
    check_vec15_14_zero_required: assert property (
        @(posedge clk) (vec_i[15:14] != 2'b00) |-> (!match1_o && !match2_o)
    );
    // If vec_i[11] != 0, both outputs are LOW.
    check_vec11_zero_required: assert property (
        @(posedge clk) (vec_i[11] != 1'b0) |-> (!match1_o && !match2_o)
    );
    // If b8_i mismatches vec_i[7], both outputs are LOW.
    check_b8_match_required: assert property (
        @(posedge clk) (vec_i[7] != b8_i) |-> (!match1_o && !match2_o)
    );
    // If b12_i mismatches vec_i[3], both outputs are LOW.
    check_b12_match_required: assert property (
        @(posedge clk) (vec_i[3] != b12_i) |-> (!match1_o && !match2_o)
    );
endmodule

rtl:
module top_module (
    input CLK,
    input RST,
    input CLR,
    input LD,
    input [3:0] DATA,
    output reg [4:0] Q
);

reg [3:0] binary_counter;
reg [3:0] async_counter;

always @(posedge CLK) begin
    if (RST) begin
        binary_counter <= 4'b0000;
    end else begin
        binary_counter <= binary_counter + 1;
    end
end

always @(posedge CLK) begin
    if (CLR) begin
        async_counter <= 4'b0000;
    end else if (LD) begin
        async_counter <= DATA;
    end else begin
        async_counter <= async_counter + 1;
    end
end

always @* begin
    Q = binary_counter + async_counter;
end

endmodule

sva:
module top_module_sva (
    input logic CLK,
    input logic RST,
    input logic CLR,
    input logic LD,
    input logic [3:0] DATA,
    input logic [4:0] Q
);

    ///// Combinational output range /////
    // Q is the 5-bit sum of two 4-bit counters; it can never exceed 30.
    check_q_within_valid_range: assert property (
        @(posedge CLK) disable iff (RST) (Q <= 5'd30)
    );

    ///// Reset and clear interactions (synchronous, active-high) /////
    // If both RST and CLR are HIGH in a cycle, Q must be 0 in the next cycle.
    check_both_resets_force_zero_next: assert property (
        @(posedge CLK) (RST && CLR) |=> (Q == 5'd0)
    );

    // If RST is HIGH and CLR is LOW and LD is HIGH, Q loads DATA next cycle.
    check_rst_and_ld_loads_data_next: assert property (
        @(posedge CLK) (RST && !CLR && LD) |=> (Q == $past(DATA))
    );

    // If RST is HIGH and CLR is LOW (LD don't care), Q is in 0..15 next cycle.
    check_rst_without_clr_bounds_next: assert property (
        @(posedge CLK) (RST && !CLR) |=> (Q <= 5'd15)
    );

    // If CLR is HIGH (regardless of LD), Q is in 0..15 next cycle (RST not asserted).
    check_clr_bounds_next: assert property (
        @(posedge CLK) disable iff (RST) (CLR) |=> (Q <= 5'd15)
    );

    // When RST and CLR and LD are all HIGH together, Q still goes to 0 next cycle (CLR priority over LD and RST forces binary_counter to 0).
    check_ld_ignored_when_both_resets: assert property (
        @(posedge CLK) (RST && CLR && LD) |=> (Q == 5'd0)
    );

    ///// Free-running behavior when no controls are asserted /////
    // With no RST/CLR/LD and Q <= 14, both 4-bit counters increment without wrap so Q increases by 2 next cycle.
    check_increment_by_two_when_small: assert property (
        @(posedge CLK) disable iff (RST)
            (!RST && !CLR && !LD && (Q <= 5'd14)) |=> (Q == ($past(Q) + 5'd2))
    );

    // With two consecutive cycles of no RST/CLR/LD and Q <= 13 at the first, Q increases by 4 after two cycles (no wrap in either counter).
    check_two_cycle_increment_when_small: assert property (
        @(posedge CLK) disable iff (RST)
            ((!RST && !CLR && !LD && (Q <= 5'd13)) ##1 (!RST && !CLR && !LD)) |=> (Q == ($past(Q, 2) + 5'd4))
    );

    ///// Persistence under sustained resets /////
    // If both RST and CLR hold HIGH for two consecutive cycles, Q remains 0 one cycle later as well.
    check_zero_persists_while_both_resets_hold: assert property (
        @(posedge CLK) ((RST && CLR) ##1 (RST && CLR)) |=> (Q == 5'd0)
    );

endmodule

rtl:
module binary_to_gray(
  input wire clk,
  input wire reset,
  input wire [7:0] bin,
  output reg [7:0] gray
);

  always @(posedge clk, posedge reset) begin
    if (reset) begin
      gray <= 8'b0;
    end else begin
      gray[7] <= bin[7];
      gray[6] <= bin[7] ^ bin[6];
      gray[5] <= bin[6] ^ bin[5];
      gray[4] <= bin[5] ^ bin[4];
      gray[3] <= bin[4] ^ bin[3];
      gray[2] <= bin[3] ^ bin[2];
      gray[1] <= bin[2] ^ bin[1];
      gray[0] <= bin[1] ^ bin[0];
    end
  end

endmodule

sva:
module binary_to_gray_sva (
    input logic clk,
    input logic reset,
    input logic [7:0] bin,
    input logic [7:0] gray
);
    ///// Reset behavior /////
    // When reset is asserted at the clock edge, gray must be all zeros.
    reset_forces_gray_zero: assert property (
        @(posedge clk) reset |-> (gray == 8'b0)
    );

    ///// Binary-to-Gray mapping (registered, 1-cycle latency) /////
    // After a non-reset cycle, gray equals the Gray-encoded value of prior bin.
    check_gray_vector_mapping: assert property (
        @(posedge clk) disable iff (reset)
            $past(!reset) |-> (gray == {
                $past(bin[7]),
                ($past(bin[7]) ^ $past(bin[6])),
                ($past(bin[6]) ^ $past(bin[5])),
                ($past(bin[5]) ^ $past(bin[4])),
                ($past(bin[4]) ^ $past(bin[3])),
                ($past(bin[3]) ^ $past(bin[2])),
                ($past(bin[2]) ^ $past(bin[1])),
                ($past(bin[1]) ^ $past(bin[0]))
            })
    );

    // MSB of gray equals prior bin[7].
    check_gray7_maps_bin7: assert property (
        @(posedge clk) disable iff (reset)
            $past(!reset) |-> (gray[7] == $past(bin[7]))
    );

    // gray[6] equals prior bin[7] XOR bin[6].
    check_gray6_maps_bin76: assert property (
        @(posedge clk) disable iff (reset)
            $past(!reset) |-> (gray[6] == ($past(bin[7]) ^ $past(bin[6])))
    );

    // gray[5] equals prior bin[6] XOR bin[5].
    check_gray5_maps_bin65: assert property (
        @(posedge clk) disable iff (reset)
            $past(!reset) |-> (gray[5] == ($past(bin[6]) ^ $past(bin[5])))
    );

    // gray[4] equals prior bin[5] XOR bin[4].
    check_gray4_maps_bin54: assert property (
        @(posedge clk) disable iff (reset)
            $past(!reset) |-> (gray[4] == ($past(bin[5]) ^ $past(bin[4])))
    );

    // gray[3] equals prior bin[4] XOR bin[3].
    check_gray3_maps_bin43: assert property (
        @(posedge clk) disable iff (reset)
            $past(!reset) |-> (gray[3] == ($past(bin[4]) ^ $past(bin[3])))
    );

    // gray[2] equals prior bin[3] XOR bin[2].
    check_gray2_maps_bin32: assert property (
        @(posedge clk) disable iff (reset)
            $past(!reset) |-> (gray[2] == ($past(bin[3]) ^ $past(bin[2])))
    );

    // gray[1] equals prior bin[2] XOR bin[1].
    check_gray1_maps_bin21: assert property (
        @(posedge clk) disable iff (reset)
            $past(!reset) |-> (gray[1] == ($past(bin[2]) ^ $past(bin[1])))
    );

    // gray[0] equals prior bin[1] XOR bin[0].
    check_gray0_maps_bin10: assert property (
        @(posedge clk) disable iff (reset)
            $past(!reset) |-> (gray[0] == ($past(bin[1]) ^ $past(bin[0])))
    );
endmodule

rtl:
module add_subtract (
    input [7:0] a,
    input [7:0] b,
    input sel,
    output [7:0] result
);

    wire [7:0] sum;
    wire [7:0] diff;

    assign sum = a + b;
    assign diff = a - b;

    assign result = sel ? diff : sum;

endmodule

sva:
module add_subtract_sva (
    input  logic        CLK,
    input  logic        RESETn,
    input  logic [7:0]  a,
    input  logic [7:0]  b,
    input  logic        sel,
    input  logic [7:0]  result
);
    // Result matches selected add/sub operation.
    check_result_muxed_operation: assert property (
        @(posedge CLK) disable iff (!RESETn) result == (sel ? (a - b) : (a + b))
    );

    // When sel=0, result equals a+b.
    check_add_result: assert property (
        @(posedge CLK) disable iff (!RESETn) (!sel) |-> (result == (a + b))
    );

    // When sel=1, result equals a-b.
    check_sub_result: assert property (
        @(posedge CLK) disable iff (!RESETn) (sel) |-> (result == (a - b))
    );

    // For sel=0, commutativity holds: result == b+a.
    check_add_commutative: assert property (
        @(posedge CLK) disable iff (!RESETn) (!sel) |-> (result == (b + a))
    );

    // For sel=1, inverse identity: (result + b) == a (mod 256).
    check_sub_inverse_identity: assert property (
        @(posedge CLK) disable iff (!RESETn) (sel) |-> ((result + b) == a)
    );

    // For sel=0, inverse identity: (result - b) == a (mod 256).
    check_add_inverse_identity: assert property (
        @(posedge CLK) disable iff (!RESETn) (!sel) |-> ((result - b) == a)
    );

    // If b==0, result equals a for both operations.
    check_b_zero_identity: assert property (
        @(posedge CLK) disable iff (!RESETn) (b == 8'h00) |-> (result == a)
    );

    // If sel=0 and a==0, result equals b.
    check_a_zero_add_identity: assert property (
        @(posedge CLK) disable iff (!RESETn) (!sel && (a == 8'h00)) |-> (result == b)
    );

    // If sel=1 and a==0, result equals (0 - b) (two's complement).
    check_a_zero_sub_identity: assert property (
        @(posedge CLK) disable iff (!RESETn) (sel && (a == 8'h00)) |-> (result == (8'h00 - b))
    );

    // If inputs are stable across a cycle, result must be stable.
    check_output_stable_when_inputs_stable: assert property (
        @(posedge CLK) disable iff (!RESETn) $stable({a,b,sel}) |-> $stable(result)
    );
endmodule

