module circuit (
    Y   ,
    A1_N,
    A2_N,
    B1  ,
    B2  ,
    VPWR,
    VGND,
    VPB ,
    VNB
);

    output Y   ;
    input  A1_N;
    input  A2_N;
    input  B1  ;
    input  B2  ;
    input  VPWR;
    input  VGND;
    input  VPB ;
    input  VNB ;

    assign Y = (A1_N & A2_N & ~B1 & ~B2) | (A1_N & ~A2_N & B1 & B2);

endmodule

sva:
module circuit_sva (
    input logic clk,   // sampling clock for assertions (DUT has no clock/reset)
    input logic Y,
    input logic A1_N,
    input logic A2_N,
    input logic B1,
    input logic B2,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB
);
    ///// Functional equivalence (same-cycle) /////
    // Y is 1 when either product term is true.
    check_y_high_when_term1_or_term2: assert property (
        @(posedge clk) disable iff (1'b0)
        ((A1_N & A2_N & ~B1 & ~B2) | (A1_N & ~A2_N & B1 & B2)) |=> Y
    );
    // Y is 0 when neither product term is true.
    check_y_low_when_neither_term: assert property (
        @(posedge clk) disable iff (1'b0)
        !((A1_N & A2_N & ~B1 & ~B2) | (A1_N & ~A2_N & B1 & B2)) |=> !Y
    );

    ///// Simple implications derived from the equation /////
    // If A1_N is LOW, Y must be LOW.
    check_a1n_low_forces_y_low: assert property (
        @(posedge clk) disable iff (1'b0)
        !A1_N |=> !Y
    );
    // If B1 and B2 differ, Y must be LOW.
    check_mismatched_b_forces_y_low: assert property (
        @(posedge clk) disable iff (1'b0)
        (B1 ^ B2) |=> !Y
    );
    // If Y is HIGH, A1_N must be HIGH.
    check_y_high_requires_a1n_high: assert property (
        @(posedge clk) disable iff (1'b0)
        Y |=> A1_N
    );
    // If Y is HIGH, B1 and B2 must be equal (00 or 11).
    check_y_high_requires_b_equal: assert property (
        @(posedge clk) disable iff (1'b0)
        Y |=> !(B1 ^ B2)
    );

    ///// Positive cases for Y=1 /////
    // When A1_N&A2_N&~B1&~B2, Y must be 1.
    check_term1_drives_y_high: assert property (
        @(posedge clk) disable iff (1'b0)
        (A1_N & A2_N & ~B1 & ~B2) |=> Y
    );
    // When A1_N&~A2_N&B1&B2, Y must be 1.
    check_term2_drives_y_high: assert property (
        @(posedge clk) disable iff (1'b0)
        (A1_N & ~A2_N & B1 & B2) |=> Y
    );

    ///// Negative cases for Y=0 /////
    // With B1=B2=0, Y is 0 unless A1_N&A2_N.
    check_b00_requires_a1n_a2n_for_y_high: assert property (
        @(posedge clk) disable iff (1'b0)
        ((B1==1'b0) && (B2==1'b0) && !(A1_N && A2_N)) |=> !Y
    );
    // With B1=B2=1, Y is 0 unless A1_N&~A2_N.
    check_b11_requires_a1n_and_not_a2n_for_y_high: assert property (
        @(posedge clk) disable iff (1'b0)
        (B1 && B2 && !(A1_N && !A2_N)) |=> !Y
    );

    ///// Stability properties /////
    // If A1_N,A2_N,B1,B2 are stable, Y must be stable.
    check_y_stable_when_inputs_stable: assert property (
        @(posedge clk) disable iff (1'b0)
        (A1_N == $past(A1_N)) && (A2_N == $past(A2_N)) && (B1 == $past(B1)) && (B2 == $past(B2)) |-> (Y == $past(Y))
    );
    // Changes on power pins alone cannot change Y when logic inputs are stable.
    check_power_pin_independence: assert property (
        @(posedge clk) disable iff (1'b0)
        (A1_N == $past(A1_N)) && (A2_N == $past(A2_N)) && (B1 == $past(B1)) && (B2 == $past(B2)) &&
        ((VPWR != $past(VPWR)) || (VGND != $past(VGND)) || (VPB != $past(VPB)) || (VNB != $past(VNB)))
        |-> (Y == $past(Y))
    );
endmodule

rtl:
module full_adder(A, B, Ci, S, Co);
  input A, B, Ci;
  output S, Co;
  assign S = A ^ B ^ Ci;
  assign Co = (A & B) | (Ci & (A ^ B));
endmodule

module RCA_4(A, B, Ci, S, Co);
  input [3:0] A;
  input [3:0] B;
  input Ci;
  output [3:0] S;
  output Co;

  wire [3:1] CTMP;

  full_adder FAI_1(.A(A[0]), .B(B[0]), .Ci(Ci), .S(S[0]), .Co(CTMP[1]));
  full_adder FAI_2(.A(A[1]), .B(B[1]), .Ci(CTMP[1]), .S(S[1]), .Co(CTMP[2]));
  full_adder FAI_3(.A(A[2]), .B(B[2]), .Ci(CTMP[2]), .S(S[2]), .Co(CTMP[3]));
  full_adder FAI_4(.A(A[3]), .B(B[3]), .Ci(CTMP[3]), .S(S[3]), .Co(Co));
endmodule

sva:
module RCA_4_sva (
    input logic CLK,
    input logic RESETn,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic Ci,
    input logic [3:0] S,
    input logic Co,
    input logic [3:1] CTMP
);
    // LSB sum equals XOR of A[0], B[0], and Ci.
    bit0_sum_is_xor: assert property (
        @(posedge CLK) disable iff (!RESETn) S[0] == (A[0] ^ B[0] ^ Ci)
    );

    // Carry from bit0 equals (A0&B0) | (Ci&(A0^B0)).
    bit0_carry1_is_formula: assert property (
        @(posedge CLK) disable iff (!RESETn) CTMP[1] == ((A[0] & B[0]) | (Ci & (A[0] ^ B[0])))
    );

    // Bit1 sum equals XOR of A[1], B[1], and CTMP[1].
    bit1_sum_is_xor: assert property (
        @(posedge CLK) disable iff (!RESETn) S[1] == (A[1] ^ B[1] ^ CTMP[1])
    );

    // Carry from bit1 equals (A1&B1) | (CTMP1&(A1^B1)).
    bit1_carry2_is_formula: assert property (
        @(posedge CLK) disable iff (!RESETn) CTMP[2] == ((A[1] & B[1]) | (CTMP[1] & (A[1] ^ B[1])))
    );

    // Bit2 sum equals XOR of A[2], B[2], and CTMP[2].
    bit2_sum_is_xor: assert property (
        @(posedge CLK) disable iff (!RESETn) S[2] == (A[2] ^ B[2] ^ CTMP[2])
    );

    // Carry from bit2 equals (A2&B2) | (CTMP2&(A2^B2)).
    bit2_carry3_is_formula: assert property (
        @(posedge CLK) disable iff (!RESETn) CTMP[3] == ((A[2] & B[2]) | (CTMP[2] & (A[2] ^ B[2])))
    );

    // Bit3 sum equals XOR of A[3], B[3], and CTMP[3].
    bit3_sum_is_xor: assert property (
        @(posedge CLK) disable iff (!RESETn) S[3] == (A[3] ^ B[3] ^ CTMP[3])
    );

    // Final carry equals (A3&B3) | (CTMP3&(A3^B3)).
    final_carry_is_formula: assert property (
        @(posedge CLK) disable iff (!RESETn) Co == ((A[3] & B[3]) | (CTMP[3] & (A[3] ^ B[3])))
    );

    // Overall 5-bit result {Co,S} equals A + B + Ci.
    overall_addition_correct: assert property (
        @(posedge CLK) disable iff (!RESETn) {Co, S} == ({1'b0, A} + {1'b0, B} + {4'b0, Ci})
    );

    // If inputs are stable across cycles, outputs are stable as well.
    outputs_stable_when_inputs_stable: assert property (
        @(posedge CLK) disable iff (!RESETn) ($stable(A) && $stable(B) && $stable(Ci)) |-> $stable({S, Co})
    );
endmodule

rtl:
module SNPS_CLOCK_GATE_HIGH_RegisterAdd_W17 ( CLK, EN, ENCLK, TE );
  input CLK, EN, TE;
  output ENCLK;

  TLATNTSCAX2TS latch ( .E(EN), .SE(TE), .CK(CLK), .ECK(ENCLK) );

endmodule

module TLATNTSCAX2TS ( E, SE, CK, ECK );
  input E, SE, CK;
  output reg ECK;

  always @ (posedge CK)
    if (E) ECK <= SE;

endmodule

sva:
module SNPS_CLOCK_GATE_HIGH_RegisterAdd_W17_sva (
    input logic CLK,
    input logic EN,
    input logic ENCLK,
    input logic TE
);
    // Next-cycle ENCLK equals prior TE when prior EN=1, else holds prior ENCLK.
    check_next_value_mux: assert property (
        @(posedge CLK) 1'b1 |=> (ENCLK == ($past(EN) ? $past(TE) : $past(ENCLK)))
    );

    // When EN is high, ENCLK updates next cycle to prior TE.
    check_update_on_en_high: assert property (
        @(posedge CLK) EN |=> (ENCLK == $past(TE))
    );

    // When EN is low, ENCLK holds its previous value next cycle.
    check_hold_when_en_low: assert property (
        @(posedge CLK) !EN |=> (ENCLK == $past(ENCLK))
    );

    // Any change in ENCLK between cycles requires prior EN to be high.
    check_change_requires_prev_en: assert property (
        @(posedge CLK) (ENCLK != $past(ENCLK)) |-> $past(EN)
    );

    // If ENCLK changes, the new value must equal prior TE (and prior EN must be high).
    check_change_matches_prev_te: assert property (
        @(posedge CLK) (ENCLK != $past(ENCLK)) |-> ($past(EN) && (ENCLK == $past(TE)))
    );

    // If ENCLK does not change, then either prior EN was low or prior TE equaled prior ENCLK.
    check_nochange_causes: assert property (
        @(posedge CLK) (ENCLK == $past(ENCLK)) |-> (!$past(EN) || ($past(TE) == $past(ENCLK)))
    );

    // If prior EN was high and prior TE differed from prior ENCLK, ENCLK must change.
    check_change_when_prev_te_diff: assert property (
        @(posedge CLK) ($past(EN) && ($past(TE) != $past(ENCLK))) |-> (ENCLK != $past(ENCLK))
    );
endmodule

rtl:
module counter_3bit_sync_reset (
  input clk,
  input reset,
  input ena,
  output reg [2:0] count,
  output reg flag
);

  always @(posedge clk, posedge reset) begin
    if (reset) begin
      count <= 3'b0;
      flag <= 1'b0;
    end
    else if (ena) begin
      if (count == 3'b111) begin
        count <= 3'b0;
        flag <= 1'b1;
      end
      else begin
        count <= count + 1;
        flag <= 1'b0;
      end
    end
  end

endmodule

sva:
module counter_3bit_sync_reset_sva (
  input logic clk,
  input logic reset,
  input logic ena,
  input logic [2:0] count,
  input logic flag
);

  // While reset is HIGH, outputs must be zero.
  reset_outputs_zero: assert property (
    @(posedge clk) reset |-> (count == 3'b000) && (flag == 1'b0)
  );

  // When disabled, count and flag hold their values.
  hold_when_disabled: assert property (
    @(posedge clk) disable iff (reset) (!ena) |=> (count == $past(count)) && (flag == $past(flag))
  );

  // When enabled and not at max, count increments and flag clears next cycle.
  increment_when_enabled: assert property (
    @(posedge clk) disable iff (reset) (ena && (count != 3'b111)) |=> (count == $past(count) + 3'b001) && (flag == 1'b0)
  );

  // When enabled and at max, wrap to zero and set flag next cycle.
  wrap_and_set_flag: assert property (
    @(posedge clk) disable iff (reset) (ena && (count == 3'b111)) |=> (count == 3'b000) && (flag == 1'b1)
  );

  // Flag high implies count is zero in the same cycle.
  flag_implies_count_zero: assert property (
    @(posedge clk) disable iff (reset) flag |-> (count == 3'b000)
  );

  // Flag can only rise after an enabled wrap from 7.
  flag_rise_on_wrap_only: assert property (
    @(posedge clk) disable iff (reset) $rose(flag) |-> ($past(ena) && ($past(count) == 3'b111))
  );

  // Any change in count must be due to enable in the previous cycle.
  count_change_requires_enable: assert property (
    @(posedge clk) disable iff (reset) ($past(1'b1) && (count != $past(count))) |-> $past(ena)
  );

  // Any change in flag must be due to enable in the previous cycle.
  flag_change_requires_enable: assert property (
    @(posedge clk) disable iff (reset) ($past(1'b1) && (flag != $past(flag))) |-> $past(ena)
  );

  // First enabled cycle after wrap (count=0, flag=1) clears flag and sets count to 1.
  clear_flag_on_enable_from_zero: assert property (
    @(posedge clk) disable iff (reset) (ena && (count == 3'b000) && (flag == 1'b1)) |=> (count == 3'b001) && (flag == 1'b0)
  );

  // When enabled, count must change on the next cycle (increment or wrap).
  enabled_step_changes_count: assert property (
    @(posedge clk) disable iff (reset) ena |=> (count != $past(count))
  );

endmodule

