    // Track past-valid to safely use $past after first cycle.
    logic past_valid;
    always @(posedge clk) begin
        if (reset) past_valid <= 1'b0;
        else past_valid <= 1'b1;
    end

    ///// Top-level wiring/combinational mapping /////
    // rising_edge must equal sum_output (direct assign).
    check_rising_edge_equals_sum_output: assert property (
        @(posedge clk) disable iff (reset) rising_edge == sum_output
    );
    // sum_output equals q + d (adder with q wired from rising_edge_detection output).
    check_sum_output_equals_q_plus_d: assert property (
        @(posedge clk) disable iff (reset) sum_output == (q + d)
    );
    // rising_edge equals q + d (by wiring through sum_output).
    check_rising_edge_equals_q_plus_d: assert property (
        @(posedge clk) disable iff (reset) rising_edge == (q + d)
    );
    // (sum_output - d) recovers q (modulo-256).
    check_sum_minus_d_equals_q: assert property (
        @(posedge clk) disable iff (reset) (sum_output - d) == q
    );
    // (sum_output - q) recovers d (modulo-256).
    check_sum_minus_q_equals_d: assert property (
        @(posedge clk) disable iff (reset) (sum_output - q) == d
    );
    // If q and d are stable, sum_output must be stable.
    check_sum_stable_when_q_and_d_stable: assert property (
        @(posedge clk) disable iff (reset) past_valid && $stable(q) && $stable(d) |-> $stable(sum_output)
    );
    // If q and d are stable, rising_edge must be stable.
    check_rising_stable_when_q_and_d_stable: assert property (
        @(posedge clk) disable iff (reset) past_valid && $stable(q) && $stable(d) |-> $stable(rising_edge)
    );

    ///// Rising-edge detector sequential behavior on q /////
    // Exact next-state equation: q == $past(q) & ~($past(in) ^ $past(q)).
    check_q_exact_update: assert property (
        @(posedge clk) disable iff (reset) past_valid |-> (q == ($past(q) & ~($past(in) ^ $past(q))))
    );
    // q cannot gain new 1-bits relative to previous q.
    check_q_no_new_ones: assert property (
        @(posedge clk) disable iff (reset) past_valid |-> ((q & ~($past(q))) == 8'h00)
    );
    // Bits where $past(in) != $past(q) must clear to 0 in q.
    check_q_zero_on_mismatch_bits: assert property (
        @(posedge clk) disable iff (reset) past_valid |-> ((q & ($past(in) ^ $past(q))) == 8'h00)
    );
    // Bits where $past(in) == $past(q) must hold their previous q value.
    check_q_hold_on_match_bits: assert property (
        @(posedge clk) disable iff (reset) past_valid |-> (((q ^ $past(q)) & ~($past(in) ^ $past(q))) == 8'h00)
    );
endmodule

rtl:
module my_module (
    output Q      ,
    input  CLK_N  ,
    input  D      ,
    input  SCD    ,
    input  SCE    ,
    input  RESET_B,
    input  VPWR   ,
    input  VGND   ,
    input  VPB    ,
    input  VNB
);

    wire Q_temp;
    assign Q = (SCD) ? 1 :
               (SCE) ? 0 :
               (RESET_B == 0) ? 0 :
               Q_temp;
    wire next_state;
    assign next_state = D;
    assign Q_temp = next_state;

endmodule

sva:
module my_module_sva (
    input  logic Q,
    input  logic CLK_N,
    input  logic D,
    input  logic SCD,
    input  logic SCE,
    input  logic RESET_B,
    input  logic VPWR,
    input  logic VGND,
    input  logic VPB,
    input  logic VNB
);
    // Clock: CLK_N (posedge). Reset: RESET_B active-low. Logic: combinational priority mux.

    // SCD high forces Q to 1.
    check_scd_forces_one: assert property (
        @(posedge CLK_N) disable iff (!RESET_B) SCD |-> (Q == 1'b1)
    );

    // SCD has priority over SCE when both are high.
    check_scd_over_sce: assert property (
        @(posedge CLK_N) disable iff (!RESET_B) (SCD && SCE) |-> (Q == 1'b1)
    );

    // With SCD low, SCE high forces Q to 0.
    check_sce_forces_zero_when_scd0: assert property (
        @(posedge CLK_N) disable iff (!RESET_B) (!SCD && SCE) |-> (Q == 1'b0)
    );

    // When SCD=0, SCE=0, and RESET_B=1, Q follows D.
    check_default_path_follows_D: assert property (
        @(posedge CLK_N) disable iff (!RESET_B) (!SCD && !SCE && (RESET_B == 1'b1)) |-> (Q == D)
    );

    // When SCD=0 and SCE=0 during reset, Q is 0.
    check_reset_clears_when_unselected: assert property (
        @(posedge CLK_N) (!RESET_B && !SCD && !SCE) |-> (Q == 1'b0)
    );

    // With SCD=0, SCE=1 during reset, Q remains 0 (SCE priority over reset default path).
    check_sce_priority_over_reset: assert property (
        @(posedge CLK_N) (!RESET_B && !SCD && SCE) |-> (Q == 1'b0)
    );

    // During reset, SCD still forces Q to 1.
    check_scd_overrides_reset: assert property (
        @(posedge CLK_N) (!RESET_B && SCD) |-> (Q == 1'b1)
    );

    // With SCD=1, SCE=1, and reset asserted, Q is 1 (SCD wins).
    check_all_high_scd_wins: assert property (
        @(posedge CLK_N) (!RESET_B && SCD && SCE) |-> (Q == 1'b1)
    );
endmodule

rtl:
module binary_multiplier (
    input [3:0] a,
    input [3:0] b,
    output [7:0] product
);

    integer i; // Declare i as an integer for loop indexing

    reg [7:0] product; // Declare product as a reg

    always @ * begin
        product = 8'b0; // Initialize product to 0
        for (i = 0; i < 4; i = i + 1) begin
            if (b[i] == 1) begin
                product = product + (a << i);
            end
        end
    end

endmodule
module gray_code (
    input [3:0] binary_input,
    output [3:0] gray_output
);

    reg [3:0] gray_output; // Declare gray_output as a reg

    always @ * begin
        gray_output = binary_input ^ (binary_input >> 1);
    end

endmodule
module top_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input [3:0] a,    // First 4-bit binary input
    input [3:0] b,    // Second 4-bit binary input
    output reg [3:0] gray_product // Final product in Gray code
);

    wire [7:0] binary_product;
    reg [7:0] binary_product_reg; // Declare binary_product_reg as a reg
    wire [3:0] binary_a;
    wire [3:0] binary_b;
    wire [3:0] gray_a;
    wire [3:0] gray_b;

    binary_multiplier binary_mult(.a(a), .b(b), .product(binary_product));
    gray_code gray_a_code(.binary_input(a), .gray_output(gray_a));
    gray_code gray_b_code(.binary_input(b), .gray_output(gray_b));

    always @(posedge clk) begin
        if (reset) begin
            binary_product_reg <= 8'b0;
            gray_product <= 4'b0;
        end else begin
            binary_product_reg <= binary_product;
            gray_product <= gray_a ^ gray_b; // Calculate gray product
        end
    end

endmodule

sva:
module top_module_sva (
    input  logic        clk,
    input  logic        reset,                 // synchronous active-high reset
    input  logic [3:0]  a,
    input  logic [3:0]  b,
    input  logic [3:0]  gray_product,
    // Internal signals from top_module
    input  logic [7:0]  binary_product,
    input  logic [7:0]  binary_product_reg,
    input  logic [3:0]  gray_a,
    input  logic [3:0]  gray_b
);
    ///// Reset behavior /////
    // On a reset cycle, next-cycle registered outputs must be zero.
    reset_clears_regs: assert property (
        @(posedge clk) reset |=> (binary_product_reg == 8'b0) && (gray_product == 4'b0)
    );

    // First cycle after leaving reset, registered outputs remain zero.
    post_reset_regs_zero: assert property (
        @(posedge clk) ($past(reset) && !reset) |-> (binary_product_reg == 8'b0) && (gray_product == 4'b0)
    );

    ///// Combinational block correctness /////
    // gray_a is combinational Gray code of a.
    check_gray_a_comb: assert property (
        @(posedge clk) disable iff (reset) gray_a == (a ^ (a >> 1))
    );

    // gray_b is combinational Gray code of b.
    check_gray_b_comb: assert property (
        @(posedge clk) disable iff (reset) gray_b == (b ^ (b >> 1))
    );

    // binary_product is combinational multiplication a*b.
    check_comb_multiplier: assert property (
        @(posedge clk) disable iff (reset) binary_product == (a * b)
    );

    // If either operand is zero, combinational product is zero.
    check_mult_by_zero: assert property (
        @(posedge clk) disable iff (reset) ((a == 4'b0) || (b == 4'b0)) |-> (binary_product == 8'b0)
    );

    ///// Sequential register updates /////
    // binary_product_reg captures binary_product on the next cycle (when not preceded by reset).
    check_bin_reg_tracks_wire: assert property (
        @(posedge clk) disable iff (reset) (!$past(reset)) |-> (binary_product_reg == $past(binary_product))
    );

    // binary_product_reg equals previous-cycle a*b (when not preceded by reset).
    check_bin_reg_eq_past_mult: assert property (
        @(posedge clk) disable iff (reset) (!$past(reset)) |-> (binary_product_reg == $past(a * b))
    );

    // gray_product captures gray_a ^ gray_b from the previous cycle (when not preceded by reset).
    check_gray_product_prev_grayxor: assert property (
        @(posedge clk) disable iff (reset) (!$past(reset)) |-> (gray_product == $past(gray_a ^ gray_b))
    );

    // gray_product equals previous-cycle (gray(a) ^ gray(b)) computed from a,b (when not preceded by reset).
    check_gray_product_prev_func: assert property (
        @(posedge clk) disable iff (reset) (!$past(reset)) |-> (gray_product == $past((a ^ (a >> 1)) ^ (b ^ (b >> 1))))
    );

endmodule

