module and_gate(input a, b, c, d, output out);
    wire temp1, temp2, temp3;

    nand gate1(temp1, a, b);
    nand gate2(temp2, temp1, c);
    nand gate3(temp3, temp2, d);
    nand gate4(out, temp3, temp3);

endmodule

sva:
module and_gate_sva (
    input logic clk,
    input logic a,
    input logic b,
    input logic c,
    input logic d,
    input logic out,
    input logic temp1,
    input logic temp2,
    input logic temp3
);
    ///// Gate-level structure checks /////
    // gate1: temp1 is NAND of a and b.
    check_gate1_is_nand: assert property (
        @(posedge clk) disable iff (1'b0) temp1 == ~(a & b)
    );
    // gate2: temp2 is NAND of temp1 and c.
    check_gate2_is_nand: assert property (
        @(posedge clk) disable iff (1'b0) temp2 == ~(temp1 & c)
    );
    // gate3: temp3 is NAND of temp2 and d.
    check_gate3_is_nand: assert property (
        @(posedge clk) disable iff (1'b0) temp3 == ~(temp2 & d)
    );
    // gate4: out is inversion of temp3 (NAND of a signal with itself).
    check_gate4_is_inv: assert property (
        @(posedge clk) disable iff (1'b0) out == ~temp3
    );

    ///// Functional equivalence /////
    // out equals d & ((a & b) | ~c).
    check_function_equivalence: assert property (
        @(posedge clk) disable iff (1'b0) out == (d & ((a & b) | ~c))
    );

    ///// Useful implications derived from the logic /////
    // If d is LOW then out must be LOW.
    check_d_low_forces_out_low: assert property (
        @(posedge clk) disable iff (1'b0) (d == 1'b0) |-> (out == 1'b0)
    );
    // If c is LOW then out equals d.
    check_c_low_passes_d: assert property (
        @(posedge clk) disable iff (1'b0) (c == 1'b0) |-> (out == d)
    );
    // If a and b are both HIGH then out equals d.
    check_ab_high_passes_d: assert property (
        @(posedge clk) disable iff (1'b0) (a && b) |-> (out == d)
    );
    // If c is HIGH and (a & b) is LOW then out is LOW.
    check_c_high_and_ab_low_out_low: assert property (
        @(posedge clk) disable iff (1'b0) (c && !(a && b)) |-> (out == 1'b0)
    );
    // If c and d are HIGH then out equals a & b.
    check_cd_high_out_equals_ab: assert property (
        @(posedge clk) disable iff (1'b0) (c && d) |-> (out == (a & b))
    );
endmodule

rtl:
module binary_counter (
    input clk,
    input reset,
    output reg [3:0] q
);

    always @(posedge clk, posedge reset) begin
        if (reset) begin
            q <= 4'b0000;
        end else begin
            q <= q + 1;
        end
    end

endmodule

sva:
module binary_counter_sva (
    input logic clk,
    input logic reset,
    input logic [3:0] q
);
    ///// Reset behavior /////
    // When reset is asserted at the clock edge, q is driven to 0.
    check_reset_forces_zero: assert property (
        @(posedge clk) reset |-> (q == 4'b0000)
    );

    // If reset is asserted in consecutive cycles, q stays 0 across both cycles.
    check_hold_zero_during_reset: assert property (
        @(posedge clk) (reset && $past(reset)) |-> (q == 4'b0000 && $past(q) == 4'b0000)
    );

    // If the previous cycle was in reset, q in that previous cycle was 0.
    check_prev_cycle_zero_during_reset: assert property (
        @(posedge clk) $past(reset) |-> ($past(q) == 4'b0000)
    );

    ///// Exit from reset /////
    // On the first cycle out of reset, q becomes 1.
    check_out_of_reset_starts_at_one: assert property (
        @(posedge clk) disable iff (reset) ($past(reset) && !reset) |-> (q == 4'b0001)
    );

    // If reset is high now, next cycle q is 0 if reset stays high, else 1.
    check_next_cycle_after_reset: assert property (
        @(posedge clk) reset |=> (reset ? (q == 4'b0000) : (q == 4'b0001))
    );

    ///// Sanity /////
    // q is never X/Z when not in reset.
    check_q_known_out_of_reset: assert property (
        @(posedge clk) disable iff (reset) !$isunknown(q)
    );

    // With reset low, q==0 can only occur due to wrap-around from 0xF (or if previous cycle was in reset).
    check_zero_only_from_wrap: assert property (
        @(posedge clk) disable iff (reset) (q == 4'b0000) |-> ($past(q) == 4'b1111 || $past(reset))
    );

    // With reset low in consecutive cycles, q cannot remain 0 (no 0->0 stutter).
    check_no_stutter_zero_out_of_reset: assert property (
        @(posedge clk) disable iff (reset) ($past(reset) == 1'b0 && reset == 1'b0 && $past(q) == 4'b0000) |-> (q != 4'b0000)
    );
endmodule

