module three_input_gate (
    Y,
    A1,
    A2,
    B1
);

    output Y;
    input A1;
    input A2;
    input B1;

    wire A1_AND_A2;
    wire B1_OR_A1_AND_A2;

    assign A1_AND_A2 = A1 & A2;
    assign B1_OR_A1_AND_A2 = B1 | A1_AND_A2;

    assign Y = B1_OR_A1_AND_A2;

endmodule

sva:
module three_input_gate_sva (
    input logic Y,
    input logic A1,
    input logic A2,
    input logic B1
);

    ///// Functional equivalence /////
    // Y must equal B1 | (A1 & A2) after any input/output edge.
    check_functional_equivalence: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge B1 or negedge B1 or posedge Y or negedge Y)
            ##0 (Y == (B1 | (A1 & A2)))
    );

    ///// Implications from inputs /////
    // If B1 is HIGH, Y must be HIGH after settle.
    check_b1_high_forces_y1: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge B1 or negedge B1 or posedge Y or negedge Y)
            ##0 (B1 == 1'b1) |-> (Y == 1'b1)
    );
    // If both A1 and A2 are HIGH, Y must be HIGH after settle.
    check_a_pair_high_forces_y1: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge B1 or negedge B1 or posedge Y or negedge Y)
            ##0 ((A1 == 1'b1) && (A2 == 1'b1)) |-> (Y == 1'b1)
    );
    // If B1 is LOW and any of A1/A2 is LOW, Y must be LOW after settle.
    check_b1_low_and_any_a_low_forces_y0: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge B1 or negedge B1 or posedge Y or negedge Y)
            ##0 ((B1 == 1'b0) && ((A1 == 1'b0) || (A2 == 1'b0))) |-> (Y == 1'b0)
    );

    ///// Implications from output /////
    // If Y is LOW, then B1 is LOW and at least one of A1/A2 is LOW.
    check_y0_implies_inputs: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge B1 or negedge B1 or posedge Y or negedge Y)
            ##0 (Y == 1'b0) |-> ((B1 == 1'b0) && ((A1 == 1'b0) || (A2 == 1'b0)))
    );
    // If Y is HIGH, then B1 is HIGH or both A1 and A2 are HIGH.
    check_y1_implies_inputs: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge B1 or negedge B1 or posedge Y or negedge Y)
            ##0 (Y == 1'b1) |-> ((B1 == 1'b1) || ((A1 == 1'b1) && (A2 == 1'b1)))
    );

    ///// Edge-specific settle checks /////
    // On B1 rising edge, Y must be HIGH after delta.
    check_posedge_b1_sets_y1: assert property (
        @(posedge B1) ##0 (Y == 1'b1)
    );
    // On B1 falling edge, Y must equal A1 & A2 after delta.
    check_negedge_b1_sets_y_and: assert property (
        @(negedge B1) ##0 (Y == (A1 & A2))
    );
    // On A1 rising edge, Y must equal B1 | A2 after delta.
    check_posedge_a1_updates_y: assert property (
        @(posedge A1) ##0 (Y == (B1 | A2))
    );
    // On A1 falling edge, Y must equal B1 after delta.
    check_negedge_a1_updates_y: assert property (
        @(negedge A1) ##0 (Y == B1)
    );
    // On A2 rising edge, Y must equal B1 | A1 after delta.
    check_posedge_a2_updates_y: assert property (
        @(posedge A2) ##0 (Y == (B1 | A1))
    );
    // On A2 falling edge, Y must equal B1 after delta.
    check_negedge_a2_updates_y: assert property (
        @(negedge A2) ##0 (Y == B1)
    );

endmodule

rtl:
module sky130_fd_sc_lp__o21a (
    X   ,
    A1  ,
    A2  ,
    B1  ,
    VPWR,
    VGND,
    VPB ,
    VNB
);

    output X   ;
    input  A1  ;
    input  A2  ;
    input  B1  ;
    input  VPWR;
    input  VGND;
    input  VPB ;
    input  VNB ;

    wire a1_high, a1_low_a2_high, a1_a2_low_b1_high;

    assign a1_high = (A1 == 1'b1);
    assign a1_low_a2_high = (A1 == 1'b0) && (A2 == 1'b1);
    assign a1_a2_low_b1_high = (A1 == 1'b0) && (A2 == 1'b0) && (B1 == 1'b1);

    assign X = a1_high || a1_low_a2_high || a1_a2_low_b1_high;

endmodule

sva:
module sky130_fd_sc_lp__o21a_sva (
    input  logic clk,
    input  logic X,
    input  logic A1,
    input  logic A2,
    input  logic B1,
    input  logic VPWR,
    input  logic VGND,
    input  logic VPB,
    input  logic VNB
);
    // X matches the RTL sum-of-terms definition using 4-state comparisons.
    check_function_equivalence: assert property (
        @(posedge clk)
        X === ((A1 == 1'b1) || ((A1 == 1'b0) && (A2 == 1'b1)) || ((A1 == 1'b0) && (A2 == 1'b0) && (B1 == 1'b1)))
    );

    // If A1 is 1, X must be 1.
    check_a1_one_forces_x_one: assert property (
        @(posedge clk)
        (A1 === 1'b1) |-> (X === 1'b1)
    );

    // If A1 is 0 and A2 is 1, X must be 1.
    check_a1_zero_a2_one_forces_x_one: assert property (
        @(posedge clk)
        ((A1 === 1'b0) && (A2 === 1'b1)) |-> (X === 1'b1)
    );

    // If A1 is 0, A2 is 0, and B1 is 1, X must be 1.
    check_a1_zero_a2_zero_b1_one_forces_x_one: assert property (
        @(posedge clk)
        ((A1 === 1'b0) && (A2 === 1'b0) && (B1 === 1'b1)) |-> (X === 1'b1)
    );

    // If A1, A2, and B1 are all 0, X must be 0.
    check_all_zeros_force_x_zero: assert property (
        @(posedge clk)
        ((A1 === 1'b0) && (A2 === 1'b0) && (B1 === 1'b0)) |-> (X === 1'b0)
    );

    // If X is 0, then A1, A2, and B1 must all be 0.
    check_x_zero_implies_all_zero_inputs: assert property (
        @(posedge clk)
        (X === 1'b0) |-> ((A1 === 1'b0) && (A2 === 1'b0) && (B1 === 1'b0))
    );

    // With all inputs known (0/1), X must also be known (not X/Z).
    check_known_inputs_imply_known_x: assert property (
        @(posedge clk)
        (!$isunknown({A1, A2, B1})) |-> (!$isunknown(X))
    );

    // With all inputs known (0/1), X equals bitwise OR of A1, A2, and B1.
    check_known_inputs_or_equivalence: assert property (
        @(posedge clk)
        (!$isunknown({A1, A2, B1})) |-> (X == (A1 | A2 | B1))
    );

    // If X is 1 while A1=0 and A2=0, then B1 must be 1.
    check_x_one_a1_zero_a2_zero_implies_b1_one: assert property (
        @(posedge clk)
        ((X === 1'b1) && (A1 === 1'b0) && (A2 === 1'b0)) |-> (B1 === 1'b1)
    );

    // If X is 1 and A1=0, then either A2=1 or (A2=0 and B1=1).
    check_x_one_a1_zero_requires_a2_one_or_b1_one: assert property (
        @(posedge clk)
        ((X === 1'b1) && (A1 === 1'b0)) |-> ((A2 === 1'b1) || ((A2 === 1'b0) && (B1 === 1'b1)))
    );
endmodule

