sva:
module sky130_fd_sc_ls__a311oi_sva (
    input logic clk,
    input logic Y,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic B1,
    input logic C1
);
    // Y implements ~( (A1 & A2 & A3) | B1 | C1 )
    check_y_function: assert property (
        @(posedge clk) Y == ~((A1 & A2 & A3) | B1 | C1)
    );

    // If B1 is HIGH, Y must be LOW.
    check_y_zero_when_b1_high: assert property (
        @(posedge clk) B1 |-> (Y == 1'b0)
    );

    // If C1 is HIGH, Y must be LOW.
    check_y_zero_when_c1_high: assert property (
        @(posedge clk) C1 |-> (Y == 1'b0)
    );

    // If A1&A2&A3 are all HIGH, Y must be LOW.
    check_y_zero_when_all_a_high: assert property (
        @(posedge clk) (A1 & A2 & A3) |-> (Y == 1'b0)
    );

    // Y can be HIGH only when B1=0, C1=0, and not all of A1,A2,A3 are 1.
    check_y_implication_from_y_high: assert property (
        @(posedge clk) (Y == 1'b1) |-> (!B1 && !C1 && !(A1 & A2 & A3))
    );

    // When B1=0, C1=0, and not all of A1,A2,A3 are 1, Y must be HIGH.
    check_y_one_when_allowed: assert property (
        @(posedge clk) (!B1 && !C1 && !(A1 & A2 & A3)) |-> (Y == 1'b1)
    );

    // With B1=0 and C1=0, Y equals ~(A1 & A2 & A3).
    check_y_when_b1c1_zero: assert property (
        @(posedge clk) (!B1 && !C1) |-> (Y == ~(A1 & A2 & A3))
    );

    // If inputs are stable across a cycle, Y must remain stable.
    check_y_stable_when_inputs_stable: assert property (
        @(posedge clk) $stable({A1, A2, A3, B1, C1}) |-> $stable(Y)
    );
endmodule

rtl:
module four_bit_mux (
    input [3:0] A,
    input [1:0] S,
    output reg [3:0] X
);

    always @(*) begin
        case (S)
            2'b00: X = 4'b0000;
            2'b01: X = 4'b1111;
            2'b10: X = (A == 4'b1111) ? 4'b0000 : A;
            2'b11: X = (A == 4'b0000) ? 4'b1111 : A;
        endcase
    end

endmodule

sva:
module four_bit_mux_sva (
    input logic [3:0] A,
    input logic [1:0] S,
    input logic [3:0] X
);
    // Combinational module with no clock/reset; assertions sample on any input edge.

    // S=00 forces X=0000.
    check_s00_zero: assert property (
        @(posedge A[0] or negedge A[0] or posedge A[1] or negedge A[1] or posedge A[2] or negedge A[2] or posedge A[3] or negedge A[3] or posedge S[0] or negedge S[0] or posedge S[1] or negedge S[1])
        (S == 2'b00) |=> (X == 4'b0000)
    );

    // S=01 forces X=1111.
    check_s01_ones: assert property (
        @(posedge A[0] or negedge A[0] or posedge A[1] or negedge A[1] or posedge A[2] or negedge A[2] or posedge A[3] or negedge A[3] or posedge S[0] or negedge S[0] or posedge S[1] or negedge S[1])
        (S == 2'b01) |=> (X == 4'b1111)
    );

    // S=10 with A==1111 forces X=0000.
    check_s10_allones_to_zero: assert property (
        @(posedge A[0] or negedge A[0] or posedge A[1] or negedge A[1] or posedge A[2] or negedge A[2] or posedge A[3] or negedge A[3] or posedge S[0] or negedge S[0] or posedge S[1] or negedge S[1])
        ((S == 2'b10) && (A == 4'b1111)) |=> (X == 4'b0000)
    );

    // S=10 with A!=1111 passes A through to X.
    check_s10_passthrough_else: assert property (
        @(posedge A[0] or negedge A[0] or posedge A[1] or negedge A[1] or posedge A[2] or negedge A[2] or posedge A[3] or negedge A[3] or posedge S[0] or negedge S[0] or posedge S[1] or negedge S[1])
        ((S == 2'b10) && (A != 4'b1111)) |=> (X == A)
    );

    // S=11 with A==0000 forces X=1111.
    check_s11_allzeros_to_ones: assert property (
        @(posedge A[0] or negedge A[0] or posedge A[1] or negedge A[1] or posedge A[2] or negedge A[2] or posedge A[3] or negedge A[3] or posedge S[0] or negedge S[0] or posedge S[1] or negedge S[1])
        ((S == 2'b11) && (A == 4'b0000)) |=> (X == 4'b1111)
    );

    // S=11 with A!=0000 passes A through to X.
    check_s11_passthrough_else: assert property (
        @(posedge A[0] or negedge A[0] or posedge A[1] or negedge A[1] or posedge A[2] or negedge A[2] or posedge A[3] or negedge A[3] or posedge S[0] or negedge S[0] or posedge S[1] or negedge S[1])
        ((S == 2'b11) && (A != 4'b0000)) |=> (X == A)
    );

    // Under S=10, X differs from A only when A==1111 and then X==0000.
    check_s10_only_diff_on_allones: assert property (
        @(posedge A[0] or negedge A[0] or posedge A[1] or negedge A[1] or posedge A[2] or negedge A[2] or posedge A[3] or negedge A[3] or posedge S[0] or negedge S[0] or posedge S[1] or negedge S[1])
        ((S == 2'b10) && (X != A)) |=> ((A == 4'b1111) && (X == 4'b0000))
    );

    // Under S=11, X differs from A only when A==0000 and then X==1111.
    check_s11_only_diff_on_allzeros: assert property (
        @(posedge A[0] or negedge A[0] or posedge A[1] or negedge A[1] or posedge A[2] or negedge A[2] or posedge A[3] or negedge A[3] or posedge S[0] or negedge S[0] or posedge S[1] or negedge S[1])
        ((S == 2'b11) && (X != A)) |=> ((A == 4'b0000) && (X == 4'b1111))
    );

    // X equals the exact function of A and S as coded in the case statement.
    check_functional_equivalence: assert property (
        @(posedge A[0] or negedge A[0] or posedge A[1] or negedge A[1] or posedge A[2] or negedge A[2] or posedge A[3] or negedge A[3] or posedge S[0] or negedge S[0] or posedge S[1] or negedge S[1])
        X == ((S == 2'b00) ? 4'b0000 :
              (S == 2'b01) ? 4'b1111 :
              (S == 2'b10) ? ((A == 4'b1111) ? 4'b0000 : A) :
                             ((A == 4'b0000) ? 4'b1111 : A))
    );

endmodule

rtl:
module adder_4bit (
    aclr,
    clock,
    A,
    B,
    CIN,
    S,
    COUT
);

    input aclr;
    input clock;
    input [3:0] A;
    input [3:0] B;
    input CIN;
    output [3:0] S;
    output COUT;

    wire [3:0] sum;
    wire [3:0] carry;

    // Instantiate full adders
    full_adder U0_fa0 (
        .A(A[0]),
        .B(B[0]),
        .CIN(CIN),
        .SUM(sum[0]),
        .COUT(carry[0])
    );
    full_adder U1_fa1 (
        .A(A[1]),
        .B(B[1]),
        .CIN(carry[0]),
        .SUM(sum[1]),
        .COUT(carry[1])
    );
    full_adder U2_fa2 (
        .A(A[2]),
        .B(B[2]),
        .CIN(carry[1]),
        .SUM(sum[2]),
        .COUT(carry[2])
    );
    full_adder U3_fa3 (
        .A(A[3]),
        .B(B[3]),
        .CIN(carry[2]),
        .SUM(sum[3]),
        .COUT(COUT)
    );

    // Instantiate registers
    reg [3:0] S_reg;
    always @(posedge clock or negedge aclr) begin
        if (!aclr) begin
            S_reg <= 4'b0;
        end else if (COUT) begin
            S_reg <= sum;
        end
    end

    assign S = S_reg;

endmodule
module full_adder (
    A,
    B,
    CIN,
    SUM,
    COUT
);

    input A;
    input B;
    input CIN;
    output SUM;
    output COUT;

    assign SUM = A ^ B ^ CIN;
    assign COUT = (A & B) | (B & CIN) | (CIN & A);

endmodule

sva:
module adder_4bit_sva (
    input logic aclr,
    input logic clock,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic CIN,
    input logic [3:0] S,
    input logic COUT
);
    // S is driven to zero while asynchronous reset is asserted low.
    check_reset_clears_S: assert property (
        @(posedge clock) (!aclr) |-> (S == 4'b0000)
    );

    // COUT equals the carry-out (MSB) of A + B + CIN.
    check_cout_matches_arithmetic: assert property (
        @(posedge clock) disable iff (!aclr)
            COUT == ({1'b0, A} + {1'b0, B} + CIN)[4]
    );

    // Sequential update rule: if last cycle was not in reset, S loads sum on COUT=1 else holds.
    check_sequential_update: assert property (
        @(posedge clock) disable iff (!aclr)
            $past(aclr) |-> S == ( $past(COUT)
                                   ? ({1'b0, $past(A)} + {1'b0, $past(B)} + $past(CIN))[3:0]
                                   : $past(S) )
    );

    // When COUT was 1 in the previous cycle, S equals the previous cycle's sum.
    check_load_on_cout: assert property (
        @(posedge clock) disable iff (!aclr)
            $past(aclr) && $past(COUT) |-> S == ({1'b0, $past(A)} + {1'b0, $past(B)} + $past(CIN))[3:0]
    );

    // When COUT was 0 in the previous cycle, S holds its previous value.
    check_hold_when_cout_zero: assert property (
        @(posedge clock) disable iff (!aclr)
            $past(aclr) && !$past(COUT) |-> S == $past(S)
    );

    // Any change in S across cycles implies COUT was 1 in the previous cycle.
    check_change_implies_prev_cout: assert property (
        @(posedge clock) disable iff (!aclr)
            $past(aclr) && (S != $past(S)) |-> $past(COUT)
    );

    // After reset deassertion, S remains zero until a cycle where COUT is 1.
    check_zero_until_first_cout: assert property (
        @(posedge clock) disable iff (!aclr)
            $rose(aclr) |-> (S == 4'b0000 until_with COUT)
    );
endmodule

