module counter (
    input clk,
    input rst,
    input [31:0] max_value,
    output reg [31:0] count
);

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            count <= 0;
        end else if (count == max_value - 1) begin
            count <= 0;
        end else begin
            count <= count + 1;
        end
    end

endmodule

sva:
module counter_sva (
    input logic clk,
    input logic rst,                // active-high reset
    input logic [31:0] max_value,
    input logic [31:0] count
);
    // Reset high at a clock edge forces count to 0 on the next cycle.
    check_reset_next_zero: assert property (
        @(posedge clk) rst |=> (count == 32'd0)
    );

    // While reset stays high across cycles, count must be 0.
    check_reset_holds_zero: assert property (
        @(posedge clk) (rst && $past(rst)) |-> (count == 32'd0)
    );

    // If not in reset and count != max_value-1, next count increments by 1.
    check_increment_when_not_wrap: assert property (
        @(posedge clk) disable iff (rst) (count != (max_value - 32'd1)) |-> ##1 (count == $past(count) + 32'd1)
    );

    // If not in reset and count == max_value-1, next count wraps to 0.
    check_wrap_when_threshold: assert property (
        @(posedge clk) disable iff (rst) (count == (max_value - 32'd1)) |-> ##1 (count == 32'd0)
    );

    // On the first cycle after reset deasserts, next update from 0 follows normal rule.
    check_post_reset_first_update: assert property (
        @(posedge clk) ($past(rst) && !rst) |-> ##1 (count == (($past(max_value) == 32'd1) ? 32'd0 : 32'd1))
    );
endmodule

module usb_type_c_orientation_sva (
    input logic CLK,
    input logic cc1,
    input logic cc2,
    input logic orientation
);
    // Orientation must be 1 when cc1=1 and cc2=0.
    check_orient_A_forward: assert property (
        @(posedge CLK) (cc1 === 1'b1) && (cc2 === 1'b0) |-> (orientation === 1'b1)
    );

    // Orientation must be 0 when cc1=0 and cc2=1.
    check_orient_B_forward: assert property (
        @(posedge CLK) (cc1 === 1'b0) && (cc2 === 1'b1) |-> (orientation === 1'b0)
    );

    // Orientation can be 1 only if cc1=1 and cc2=0.
    check_orient_A_reverse: assert property (
        @(posedge CLK) (orientation === 1'b1) |-> ((cc1 === 1'b1) && (cc2 === 1'b0))
    );

    // Orientation can be 0 only if cc1=0 and cc2=1.
    check_orient_B_reverse: assert property (
        @(posedge CLK) (orientation === 1'b0) |-> ((cc1 === 1'b0) && (cc2 === 1'b1))
    );

    // On cc1 rising edge with cc2 low, orientation must be 1 in the same cycle.
    check_orient_on_cc1_rise: assert property (
        @(posedge CLK) ($rose(cc1) && (cc2 === 1'b0)) |-> (orientation === 1'b1)
    );

    // On cc2 rising edge with cc1 low, orientation must be 0 in the same cycle.
    check_orient_on_cc2_rise: assert property (
        @(posedge CLK) ($rose(cc2) && (cc1 === 1'b0)) |-> (orientation === 1'b0)
    );
endmodule

