module and_gate_sva (
    input logic clk,   // External sampling clock (RTL has no clock/reset)
    input logic a,
    input logic b,
    input logic out
);
    // out must equal a & b every cycle.
    check_and_equivalence: assert property (
        @(posedge clk) out == (a & b)
    );

    // out HIGH only when both inputs are HIGH.
    check_out_high_implies_inputs_high: assert property (
        @(posedge clk) out |=> (a && b)
    );

    // If any input is LOW, out must be LOW.
    check_any_input_low_forces_out_low: assert property (
        @(posedge clk) (!a || !b) |=> (!out)
    );

    // If both inputs are HIGH, out must be HIGH.
    check_inputs_high_implies_out_high: assert property (
        @(posedge clk) (a && b) |=> out
    );

    // out can change only if at least one input changed.
    check_out_change_needs_input_change: assert property (
        @(posedge clk) $changed(out) |=> ($changed(a) || $changed(b))
    );

    // If both inputs are stable, out must be stable.
    check_stable_inputs_keep_out_stable: assert property (
        @(posedge clk) (!$changed(a) && !$changed(b)) |=> !$changed(out)
    );
endmodule

rtl:
module top_module (
    input clk,
    input reset,
    input [7:0] a1,
    input [7:0] b1,
    input [7:0] a2,
    input [7:0] b2,
    output EN,
    output [2:0] Y
);

    // Instantiate unsigned multiplier modules
    wire [15:0] product1;
    wire [15:0] product2;
    unsigned_multiplier unsigned_multiplier_1(a1, b1, clk, reset, product1);
    unsigned_multiplier unsigned_multiplier_2(a2, b2, clk, reset, product2);

    // Instantiate priority encoder module
    priority_encoder priority_encoder(product1, product2, EN, Y);

endmodule
module unsigned_multiplier (
    input [7:0] a,
    input [7:0] b,
    input clk,
    input reset,
    output [15:0] product
);

    reg [15:0] product_reg;

    always @(posedge clk) begin
        if (reset) begin
            product_reg <= 0;
        end else begin
            product_reg <= a * b;
        end
    end

    assign product = product_reg;

endmodule
module priority_encoder (
    input [15:0] inputs1,
    input [15:0] inputs2,
    output reg EN,
    output reg [2:0] Y
);

    always @(*) begin
        if (inputs1 == 16'h0000 && inputs2 == 16'h0000) begin
            EN <= 0;
            Y <= 3'b000;
        end else if (inputs1 > inputs2) begin
            EN <= 1;
            Y <= inputs1[12:10];
        end else begin
            EN <= 1;
            Y <= inputs2[12:10];
        end
    end

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic reset,
    input logic [7:0] a1,
    input logic [7:0] b1,
    input logic [7:0] a2,
    input logic [7:0] b2,
    input logic EN,
    input logic [2:0] Y
);

    ///// Helper expressions (expanded inline in properties) /////
    // p1 = ({8'b0,$past(a1)} * {8'b0,$past(b1)})[15:0]
    // p2 = ({8'b0,$past(a2)} * {8'b0,$past(b2)})[15:0]

    ///// Reset behavior /////
    // After a cycle with reset=1, priority encoder must see zeros -> EN=0 and Y=000.
    check_reset_clears_outputs_next: assert property (
        @(posedge clk) disable iff (reset)
            $past(reset) |-> (EN == 1'b0 && Y == 3'b000)
    );

    ///// EN behavior /////
    // EN must be 0 when both products are zero.
    check_en_low_when_both_zero: assert property (
        @(posedge clk) disable iff (reset)
            ((({8'b0,$past(a1)} * {8'b0,$past(b1)})[15:0] == 16'h0000) &&
             (({8'b0,$past(a2)} * {8'b0,$past(b2)})[15:0] == 16'h0000))
            |-> (EN == 1'b0)
    );

    // EN must be 1 when at least one product is nonzero.
    check_en_high_when_any_nonzero: assert property (
        @(posedge clk) disable iff (reset)
            ((({8'b0,$past(a1)} * {8'b0,$past(b1)})[15:0] != 16'h0000) ||
             (({8'b0,$past(a2)} * {8'b0,$past(b2)})[15:0] != 16'h0000))
            |-> (EN == 1'b1)
    );

    ///// Y behavior for zero case /////
    // Y must be 000 when both products are zero.
    check_y_zero_when_both_zero: assert property (
        @(posedge clk) disable iff (reset)
            ((({8'b0,$past(a1)} * {8'b0,$past(b1)})[15:0] == 16'h0000) &&
             (({8'b0,$past(a2)} * {8'b0,$past(b2)})[15:0] == 16'h0000))
            |-> (Y == 3'b000)
    );

    ///// Selection behavior /////
    // When product1 > product2, select product1[12:10] and EN=1.
    check_select_p1_when_greater: assert property (
        @(posedge clk) disable iff (reset)
            (({8'b0,$past(a1)} * {8'b0,$past(b1)})[15:0] >
             ({8'b0,$past(a2)} * {8'b0,$past(b2)})[15:0])
            |-> (EN == 1'b1 && Y == ({8'b0,$past(a1)} * {8'b0,$past(b1)})[12:10])
    );

    // When product2 > product1, select product2[12:10] and EN=1.
    check_select_p2_when_greater: assert property (
        @(posedge clk) disable iff (reset)
            (({8'b0,$past(a2)} * {8'b0,$past(b2)})[15:0] >
             ({8'b0,$past(a1)} * {8'b0,$past(b1)})[15:0])
            |-> (EN == 1'b1 && Y == ({8'b0,$past(a2)} * {8'b0,$past(b2)})[12:10])
    );

    // When products are equal and nonzero, select product2[12:10] and EN=1.
    check_select_p2_when_equal_nonzero: assert property (
        @(posedge clk) disable iff (reset)
            ((({8'b0,$past(a1)} * {8'b0,$past(b1)})[15:0] ==
              ({8'b0,$past(a2)} * {8'b0,$past(b2)})[15:0]) &&
             (({8'b0,$past(a1)} * {8'b0,$past(b1)})[15:0] != 16'h0000))
            |-> (EN == 1'b1 && Y == ({8'b0,$past(a2)} * {8'b0,$past(b2)})[12:10])
    );

    // When only product1 is nonzero, select product1[12:10] and EN=1.
    check_select_p1_when_only_p1_nonzero: assert property (
        @(posedge clk) disable iff (reset)
            ((({8'b0,$past(a1)} * {8'b0,$past(b1)})[15:0] != 16'h0000) &&
             (({8'b0,$past(a2)} * {8'b0,$past(b2)})[15:0] == 16'h0000))
            |-> (EN == 1'b1 && Y == ({8'b0,$past(a1)} * {8'b0,$past(b1)})[12:10])
    );

    // When only product2 is nonzero, select product2[12:10] and EN=1.
    check_select_p2_when_only_p2_nonzero: assert property (
        @(posedge clk) disable iff (reset)
            ((({8'b0,$past(a2)} * {8'b0,$past(b2)})[15:0] != 16'h0000) &&
             (({8'b0,$past(a1)} * {8'b0,$past(b1)})[15:0] == 16'h0000))
            |-> (EN == 1'b1 && Y == ({8'b0,$past(a2)} * {8'b0,$past(b2)})[12:10])
    );

    // When EN==1, Y must reflect the selected product's [12:10] and at least one product nonzero.
    check_en1_implies_consistent_y: assert property (
        @(posedge clk) disable iff (reset)
            EN == 1'b1 |-> 
                ( (({8'b0,$past(a1)} * {8'b0,$past(b1)})[15:0] != 16'h0000) ||
                  (({8'b0,$past(a2)} * {8'b0,$past(b2)})[15:0] != 16'h0000) )
                &&
                ( Y == ( (({8'b0,$past(a1)} * {8'b0,$past(b1)})[15:0] >
                          ({8'b0,$past(a2)} * {8'b0,$past(b2)})[15:0])
                        ? ({8'b0,$past(a1)} * {8'b0,$past(b1)})[12:10]
                        : ({8'b0,$past(a2)} * {8'b0,$past(b2)})[12:10] ) )
    );

endmodule

rtl:
module up_down_counter (
  input clk,
  input areset,
  input up_down,
  input load,
  input [3:0] load_value,
  output reg [3:0] count
);

  always @(posedge clk or negedge areset) begin
    if (areset == 0) begin
      count <= 0;
    end else if (load == 1) begin
      count <= load_value;
    end else if (up_down == 1) begin
      count <= count + 1;
    end else begin
      count <= count - 1;
    end
  end

endmodule

sva:
module up_down_counter_sva (
  input logic clk,
  input logic areset,
  input logic up_down,
  input logic load,
  input logic [3:0] load_value,
  input logic [3:0] count
);

  ///// Reset behavior /////
  // While reset is asserted (active-low), count must be 0.
  reset_holds_zero: assert property (
    @(posedge clk) (areset == 1'b0) |-> (count == 4'd0)
  );

  ///// Load behavior /////
  // When load is 1, next count equals current load_value.
  load_updates_count_next: assert property (
    @(posedge clk) disable iff (areset == 1'b0)
      (load == 1'b1) |=> (count == $past(load_value))
  );

  ///// Up/Down behavior /////
  // When load is 0 and up_down is 1, next count increments by 1 (mod 16).
  increment_update: assert property (
    @(posedge clk) disable iff (areset == 1'b0)
      (load == 1'b0 && up_down == 1'b1) |=> (count == ($past(count) + 4'd1))
  );

  // When load is 0 and up_down is 0, next count decrements by 1 (mod 16).
  decrement_update: assert property (
    @(posedge clk) disable iff (areset == 1'b0)
      (load == 1'b0 && up_down == 1'b0) |=> (count == ($past(count) - 4'd1))
  );

  ///// Wrap-around behavior /////
  // Increment wraps from 15 to 0.
  increment_wrap: assert property (
    @(posedge clk) disable iff (areset == 1'b0)
      (load == 1'b0 && up_down == 1'b1 && $past(count) == 4'hF) |=> (count == 4'h0)
  );

  // Decrement wraps from 0 to 15.
  decrement_wrap: assert property (
    @(posedge clk) disable iff (areset == 1'b0)
      (load == 1'b0 && up_down == 1'b0 && $past(count) == 4'h0) |=> (count == 4'hF)
  );

  ///// Sanity checks /////
  // When not loading, count must change each cycle by +/-1.
  change_when_no_load: assert property (
    @(posedge clk) disable iff (areset == 1'b0)
      (load == 1'b0) |=> (count != $past(count))
  );

  // Full next-state equation matches RTL priority and arithmetic.
  next_state_function: assert property (
    @(posedge clk) disable iff (areset == 1'b0)
      1'b1 |=> ( count == ( $past(load) ? $past(load_value)
                                : ( $past(up_down) ? ($past(count) + 4'd1)
                                                   : ($past(count) - 4'd1) ) ) )
  );

endmodule

rtl:
module shift_register_8bit (
    input clk,
    input load,
    input [7:0] data_in,
    output [7:0] data_out
);

reg [7:0] shift_reg;

always @(posedge clk) begin
    if (load) begin
        shift_reg <= data_in;
    end else begin
        shift_reg <= {shift_reg[6:0], 1'b0};
    end
end

assign data_out = shift_reg;

endmodule

sva:
module shift_register_8bit_sva (
    input logic clk,
    input logic load,
    input logic [7:0] data_in,
    input logic [7:0] data_out
);
    // Next-state equation: load -> data_in, else shift left with 0 LSB.
    check_next_state_equation: assert property (
        @(posedge clk) !$initstate |-> (data_out == ($past(load) ? $past(data_in) : { $past(data_out[6:0]), 1'b0 }))
    );

    // When load was 1, next data_out equals previous data_in.
    check_load_captures_input: assert property (
        @(posedge clk) (!$initstate && $past(load)) |-> (data_out == $past(data_in))
    );

    // When load was 0, next data_out equals left-shifted previous data_out with 0 inserted.
    check_shift_on_no_load: assert property (
        @(posedge clk) (!$initstate && !$past(load)) |-> (data_out == { $past(data_out[6:0]), 1'b0 })
    );

    // When load was 0, next LSB is 0.
    check_lsb_zero_on_shift: assert property (
        @(posedge clk) (!$initstate && !$past(load)) |-> (data_out[0] == 1'b0)
    );

    // When load was 0, upper 7 bits shift from previous lower 7 bits.
    check_upper_bits_shift_on_no_load: assert property (
        @(posedge clk) (!$initstate && !$past(load)) |-> (data_out[7:1] == $past(data_out[6:0]))
    );

    // After 8 consecutive no-load cycles, output becomes zero.
    check_zero_after_8_no_loads: assert property (
        @(posedge clk) (!load)[*8] |=> (data_out == 8'h00)
    );

    // After 2 consecutive no-load cycles, lower 2 bits are zero.
    check_lower2_zero_after_2_no_loads: assert property (
        @(posedge clk) (!load)[*2] |=> (data_out[1:0] == 2'b00)
    );

    // After 3 consecutive no-load cycles, lower 3 bits are zero.
    check_lower3_zero_after_3_no_loads: assert property (
        @(posedge clk) (!load)[*3] |=> (data_out[2:0] == 3'b000)
    );
endmodule

module barrel_shifter_sva (
    input logic CLK,
    input logic [7:0] in,
    input logic [2:0] shift_amount,
    input logic direction,
    input logic [7:0] out
);
    // Left shift selected: out equals in << shift_amount.
    check_left_shift_result: assert property (
        @(posedge CLK) (direction == 1'b0) |-> (out == (in << shift_amount))
    );

    // Right shift selected: out equals in >> shift_amount.
    check_right_shift_result: assert property (
        @(posedge CLK) (direction == 1'b1) |-> (out == (in >> shift_amount))
    );

    // Zero shift amount passes input through regardless of direction.
    check_shift_zero_passthrough: assert property (
        @(posedge CLK) (shift_amount == 3'd0) |-> (out == in)
    );

    // Left shift with nonzero amount zero-fills LSB.
    check_left_shift_lsb_zero_when_nonzero: assert property (
        @(posedge CLK) ((direction == 1'b0) && (shift_amount != 3'd0)) |-> (out[0] == 1'b0)
    );

    // Right shift with nonzero amount zero-fills MSB.
    check_right_shift_msb_zero_when_nonzero: assert property (
        @(posedge CLK) ((direction == 1'b1) && (shift_amount != 3'd0)) |-> (out[7] == 1'b0)
    );

    // Extreme case: left shift by 7 places.
    check_extreme_left_shift7: assert property (
        @(posedge CLK) ((direction == 1'b0) && (shift_amount == 3'd7)) |-> (out == {in[0], 7'b0})
    );

    // Extreme case: right shift by 7 places.
    check_extreme_right_shift7: assert property (
        @(posedge CLK) ((direction == 1'b1) && (shift_amount == 3'd7)) |-> (out == {7'b0, in[7]})
    );

    // Specific case: left shift by 1 place.
    check_left_shift1_pattern: assert property (
        @(posedge CLK) ((direction == 1'b0) && (shift_amount == 3'd1)) |-> (out == {in[6:0], 1'b0})
    );

    // Zero input always yields zero output.
    check_zero_input_yields_zero_output: assert property (
        @(posedge CLK) (in == 8'b0) |-> (out == 8'b0)
    );

    // If inputs are stable, output remains stable.
    check_stability_when_inputs_stable: assert property (
        @(posedge CLK) $stable(in) && $stable(shift_amount) && $stable(direction) |-> $stable(out)
    );
endmodule

