rtl:
module dffc_6 ( clk, reset, d, q );
	input clk;
	input reset;
	input [5:0] d;
	output [5:0] q;
	reg [5:0] q;

	always @(posedge clk or negedge reset) begin
		if (!reset) begin
			q <= 6'b0;
		end
		else begin
			q <= d;
		end
	end
endmodule

sva:
module dffc_6_sva (
    input logic clk,
    input logic reset,
    input logic [5:0] d,
    input logic [5:0] q
);
    // q must be 0 whenever reset is asserted (active-low).
    check_reset_forces_zero: assert property (
        @(posedge clk) (reset == 1'b0) |-> (q == 6'b0)
    );

    // On a falling edge of reset, q is 0 at this clock sample.
    check_zero_on_reset_fall_sample: assert property (
        @(posedge clk) $fell(reset) |-> (q == 6'b0)
    );

    // On a rising edge of reset, q is 0 at this clock sample.
    check_zero_on_reset_rise_sample: assert property (
        @(posedge clk) $rose(reset) |-> (q == 6'b0)
    );

    // With reset high in consecutive cycles, q equals last cycle's d.
    check_capture_d_when_reset_high: assert property (
        @(posedge clk) disable iff (!reset) $past(reset) |-> (q == $past(d))
    );

    // First clock after reset release captures the d value from the release cycle.
    check_first_cycle_after_release_captures_d: assert property (
        @(posedge clk) disable iff (!reset) $rose(reset) |-> ##1 (q == $past(d))
    );

    // If d held constant over the last two cycles (no reset), q does not change.
    check_stability_when_d_unchanged: assert property (
        @(posedge clk) disable iff (!reset)
            ($past(reset,2) && $past(reset) && ($past(d) == $past(d,2))) |-> (q == $past(q))
    );

    // If q changes (no reset), the change was caused by a change in d in the prior cycle.
    check_q_change_requires_d_change: assert property (
        @(posedge clk) disable iff (!reset)
            ($past(reset,2) && $past(reset) && (q != $past(q))) |-> ($past(d) != $past(d,2))
    );

    // When reset is high, next cycle's q equals this cycle's d (if reset stays high).
    check_next_cycle_captures_d_when_reset_high: assert property (
        @(posedge clk) disable iff (!reset) reset |-> ##1 (q == $past(d))
    );
endmodule

rtl:
module sync_merge (
    input wire r1,
    input wire r2,
    input wire a1,
    input wire a2,
    output reg r0,
    output reg a0
);

    always @(*) begin
        if (r1 == 1'b0 && r2 == 1'b0) begin
            r0 = 1'b0;
            a0 = 1'b0;
        end else if (r1 == 1'b1 && r2 == 1'b0) begin
            r0 = 1'b1;
            a0 = a1;
        end else if (r1 == 1'b0 && r2 == 1'b1) begin
            r0 = 1'b1;
            a0 = a2;
        end else if (r1 == 1'b1 && r2 == 1'b1) begin
            r0 = 1'b0;
            a0 = 1'b0;
        end
    end

endmodule

sva:
module sync_merge_sva (
    input logic clk,
    input logic r1,
    input logic r2,
    input logic a1,
    input logic a2,
    input logic r0,
    input logic a0
);
    // r0 is XOR of r1 and r2.
    check_r0_xor: assert property (
        @(posedge clk) r0 == (r1 ^ r2)
    );

    // When both r1 and r2 are LOW, outputs are LOW.
    check_both_low_behavior: assert property (
        @(posedge clk) (r1 == 1'b0 && r2 == 1'b0) |-> (r0 == 1'b0 && a0 == 1'b0)
    );

    // When only r1 is HIGH, r0 is HIGH and a0 passes a1.
    check_r1_only_behavior: assert property (
        @(posedge clk) (r1 == 1'b1 && r2 == 1'b0) |-> (r0 == 1'b1 && a0 == a1)
    );

    // When only r2 is HIGH, r0 is HIGH and a0 passes a2.
    check_r2_only_behavior: assert property (
        @(posedge clk) (r1 == 1'b0 && r2 == 1'b1) |-> (r0 == 1'b1 && a0 == a2)
    );

    // When both r1 and r2 are HIGH, outputs are LOW.
    check_both_high_behavior: assert property (
        @(posedge clk) (r1 == 1'b1 && r2 == 1'b1) |-> (r0 == 1'b0 && a0 == 1'b0)
    );

    // If r0 is LOW, a0 must be LOW.
    check_r0_low_implies_a0_low: assert property (
        @(posedge clk) (r0 == 1'b0) |-> (a0 == 1'b0)
    );

    // a0 can be HIGH only when exactly one request is HIGH.
    check_a0_high_only_if_one_req: assert property (
        @(posedge clk) (a0 == 1'b1) |-> (r1 ^ r2)
    );

    // On r1 rising when r2 is LOW, r0 is HIGH and a0 passes a1.
    check_rise_r1_when_r2_low: assert property (
        @(posedge clk) ($rose(r1) && (r2 == 1'b0)) |-> (r0 == 1'b1 && a0 == a1)
    );

    // On r2 rising when r1 is LOW, r0 is HIGH and a0 passes a2.
    check_rise_r2_when_r1_low: assert property (
        @(posedge clk) ($rose(r2) && (r1 == 1'b0)) |-> (r0 == 1'b1 && a0 == a2)
    );

    // On r1 falling when r2 is HIGH, r0 is HIGH and a0 passes a2.
    check_fall_r1_when_r2_high: assert property (
        @(posedge clk) ($fell(r1) && (r2 == 1'b1)) |-> (r0 == 1'b1 && a0 == a2)
    );
endmodule

rtl:
module shift_register (
    input clk,
    input [3:0] D,
    input SI,
    output reg SO
);

reg [3:0] reg1, reg2, reg3, reg4;

always @(posedge clk) begin
    reg4 <= reg3;
    reg3 <= reg2;
    reg2 <= reg1;
    reg1 <= SI ? D : reg1;
    SO <= reg4[0];
end

endmodule

sva:
module shift_register_sva (
    input logic clk,
    input logic [3:0] D,
    input logic SI,
    input logic SO,
    // Internal DUT signals
    input logic [3:0] reg1,
    input logic [3:0] reg2,
    input logic [3:0] reg3,
    input logic [3:0] reg4
);
    // reg1 loads D when SI is high.
    check_reg1_load_on_SI_high: assert property (
        @(posedge clk) (SI == 1'b1) |=> (reg1 === $past(D))
    );

    // reg1 holds its value when SI is low.
    check_reg1_hold_on_SI_low: assert property (
        @(posedge clk) (SI == 1'b0) |=> (reg1 === $past(reg1))
    );

    // reg2 samples reg1 every cycle.
    check_reg2_samples_reg1: assert property (
        @(posedge clk) 1'b1 |=> (reg2 === $past(reg1))
    );

    // reg3 samples reg2 every cycle.
    check_reg3_samples_reg2: assert property (
        @(posedge clk) 1'b1 |=> (reg3 === $past(reg2))
    );

    // reg4 samples reg3 every cycle.
    check_reg4_samples_reg3: assert property (
        @(posedge clk) 1'b1 |=> (reg4 === $past(reg3))
    );

    // SO outputs the previous reg4[0] each cycle.
    check_SO_samples_reg4_lsb: assert property (
        @(posedge clk) 1'b1 |=> (SO === $past(reg4[0]))
    );

    // If reg1 changes, it must be due to SI high and equals prior D.
    check_reg1_change_implies_SI_and_D: assert property (
        @(posedge clk) $changed(reg1) |-> ($past(SI) && (reg1 === $past(D)))
    );

    // When SI is high, D[0] appears at SO after 4 cycles.
    check_D0_reaches_SO_in_4_cycles: assert property (
        @(posedge clk) (SI == 1'b1) |-> ##4 (SO === $past(D[0], 4))
    );

    // If SO changes, reg4[0] must have changed in the previous cycle.
    check_SO_change_follows_reg4_lsb_change: assert property (
        @(posedge clk) $changed(SO) |-> $past($changed(reg4[0]))
    );
endmodule

module adder_sva (
    // Analysis: no clock/reset in RTL; purely combinational; S = (C ? A - B : A + B) with 4-bit wrap.
    // Key signals: A[3:0], B[3:0], C (mode select), S[3:0] (result).
    // Assertions sample on an external clock 'clk'.
    input  logic        clk,
    input  logic [3:0]  A,
    input  logic [3:0]  B,
    input  logic        C,
    input  logic [3:0]  S
);
    // Add mode: S equals low 4 bits of A+B when C==0.
    check_add_mode_result: assert property (
        @(posedge clk) (C == 1'b0) |-> (S == (A + B)[3:0])
    );

    // Sub mode: S equals low 4 bits of A-B when C==1.
    check_sub_mode_result: assert property (
        @(posedge clk) (C == 1'b1) |-> (S == (A - B)[3:0])
    );

    // Combinational determinism: if {A,B,C} are stable, S is stable.
    stable_when_inputs_stable: assert property (
        @(posedge clk) $stable({A,B,C}) |-> $stable(S)
    );

    // Identity for zero B: adding or subtracting zero yields A.
    identity_when_B_zero: assert property (
        @(posedge clk) (B == 4'h0) |-> (S == A)
    );

    // Add identity: when A is zero in add mode, S equals B.
    add_identity_A_zero: assert property (
        @(posedge clk) (C == 1'b0 && A == 4'h0) |-> (S == B)
    );

    // Sub equality: when A==B in sub mode, S is zero (mod-16).
    sub_zero_when_A_eq_B: assert property (
        @(posedge clk) (C == 1'b1 && A == B) |-> (S == 4'h0)
    );

    // Add invertibility (mod-16): in add mode, (S - A) mod 16 equals B.
    add_mode_invertibility: assert property (
        @(posedge clk) (C == 1'b0) |-> ((S - A)[3:0] == B)
    );

    // Sub invertibility (mod-16): in sub mode, (S + B) mod 16 equals A.
    sub_mode_invertibility: assert property (
        @(posedge clk) (C == 1'b1) |-> ((S + B)[3:0] == A)
    );
endmodule

rtl:
module adder_4bit(
  input [3:0] A,
  input [3:0] B,
  input S,
  output [3:0] C
);

  assign C = S ? A - B : A + B;

endmodule

sva:
module adder_4bit_sva (
    input logic clk,           // External clock for sampling assertions
    input logic [3:0] A,
    input logic [3:0] B,
    input logic S,
    input logic [3:0] C
);
    ///// Functional correctness /////
    // When S==0, C must equal A + B (4-bit wrap).
    check_add_mode_correct: assert property (
        @(posedge clk) (S == 1'b0) |-> (C == (A + B))
    );
    // When S==1, C must equal A - B (4-bit wrap).
    check_sub_mode_correct: assert property (
        @(posedge clk) (S == 1'b1) |-> (C == (A - B))
    );

    ///// Determinism and stability /////
    // If inputs A,B,S are unchanged from last cycle, C must be unchanged.
    check_output_stable_when_inputs_stable: assert property (
        @(posedge clk) ({A,B,S} == $past({A,B,S})) |-> (C == $past(C))
    );

    ///// X-propagation /////
    // If A,B,S are all known (no X/Z), then C must be known.
    check_known_output_with_known_inputs: assert property (
        @(posedge clk) (!$isunknown({A,B,S})) |-> (!$isunknown(C))
    );

    ///// Algebraic identities (direct consequences of + and -) /////
    // In add mode, adding zero B passes A through.
    check_add_zero_B_passthru: assert property (
        @(posedge clk) (S == 1'b0 && B == 4'h0) |-> (C == A)
    );
    // In add mode, adding zero A passes B through.
    check_add_zero_A_passthru: assert property (
        @(posedge clk) (S == 1'b0 && A == 4'h0) |-> (C == B)
    );
    // In sub mode, subtracting zero B passes A through.
    check_sub_zero_B_passthru: assert property (
        @(posedge clk) (S == 1'b1 && B == 4'h0) |-> (C == A)
    );
    // In sub mode, subtracting equal operands yields zero.
    check_sub_equal_inputs_zero: assert property (
        @(posedge clk) (S == 1'b1 && A == B) |-> (C == 4'h0)
    );
endmodule

rtl:
module comparator (
    input [3:0] A,
    input [3:0] B,
    output reg EQ,
    output reg GT,
    output reg LT
);

    always @(*) begin
        if (A == B) begin
            EQ = 1;
            GT = 0;
            LT = 0;
        end else if (A > B) begin
            EQ = 0;
            GT = 1;
            LT = 0;
        end else begin
            EQ = 0;
            GT = 0;
            LT = 1;
        end
    end

endmodule

