);
    // No clock/reset in DUT; combinational. Assertions sample on external clk with no reset gating.
    // Behavior: EQ iff A==B, GT iff A>B, LT iff A<B; exactly one output is HIGH.

    // Outputs EQ and GT are mutually exclusive.
    check_mutex_eq_gt: assert property (
        @(posedge clk) !(EQ && GT)
    );

    // Outputs EQ and LT are mutually exclusive.
    check_mutex_eq_lt: assert property (
        @(posedge clk) !(EQ && LT)
    );

    // Outputs GT and LT are mutually exclusive.
    check_mutex_gt_lt: assert property (
        @(posedge clk) !(GT && LT)
    );

    // At least one of EQ/GT/LT must be HIGH.
    check_not_all_zero: assert property (
        @(posedge clk) (EQ || GT || LT)
    );

    // When A equals B, outputs reflect equality.
    check_map_equal: assert property (
        @(posedge clk) (A == B) |-> (EQ && !GT && !LT)
    );

    // When A is greater than B, outputs reflect greater-than.
    check_map_greater: assert property (
        @(posedge clk) (A > B) |-> (!EQ && GT && !LT)
    );

    // When A is less than B, outputs reflect less-than.
    check_map_less: assert property (
        @(posedge clk) (A < B) |-> (!EQ && !GT && LT)
    );

    // If EQ is HIGH, inputs must be equal.
    check_eq_implies_relation: assert property (
        @(posedge clk) EQ |-> (A == B)
    );

    // If GT is HIGH, A must be greater than B.
    check_gt_implies_relation: assert property (
        @(posedge clk) GT |-> (A > B)
    );

    // If LT is HIGH, A must be less than B.
    check_lt_implies_relation: assert property (
        @(posedge clk) LT |-> (A < B)
    );
endmodule

rtl:
module shift_mux_array
	#(parameter SWR=26, parameter LEVEL=5)
    (
    input wire [SWR-1:0] Data_i,
    input wire select_i,
    input wire bit_shift_i,
    output wire [SWR-1:0] Data_o
    );

genvar j;
localparam integer lvl = 2**(LEVEL);
localparam integer x = (SWR - 1);
generate for (j=0; j<=SWR-1 ; j=j+1) begin : MUX_ODDNORM

	localparam integer sh=(2**LEVEL)+j; case ((lvl+j)>(x))

		1'b1: begin :BSHITMUX
		assign Data_o[j] = (select_i) ? bit_shift_i : Data_i[j];

			end

		1'b0: begin : FSHITMUX

			assign Data_o[j] = (select_i) ? Data_i[lvl+j] : Data_i[j];

			end
		endcase
	end
endgenerate

endmodule

sva:
module shift_mux_array_sva
  #(parameter int SWR = 26, parameter int LEVEL = 5)
  (
    input  logic                   clk,
    input  logic [SWR-1:0]         Data_i,
    input  logic                   select_i,
    input  logic                   bit_shift_i,
    input  logic [SWR-1:0]         Data_o
  );

  // Replicate RTL constants
  localparam int lvl = 2**(LEVEL);
  localparam int x   = SWR - 1;

  // When select_i=0, output passes through input vector.
  check_passthrough_when_select0: assert property (
    @(posedge clk) disable iff (1'b0) (!select_i) |=> (Data_o == Data_i)
  );

  genvar j;
  generate
    for (j = 0; j <= SWR-1; j = j + 1) begin : gen_bit_checks
      if ((lvl + j) > x) begin : fill_region
        // With select_i=1 and index out-of-range, Data_o[j] equals bit_shift_i.
        check_sel1_fill_bit: assert property (
          @(posedge clk) disable iff (1'b0) (select_i) |=> (Data_o[j] == bit_shift_i)
        );
      end else begin : forward_region
        // With select_i=1 and index in-range, Data_o[j] maps to Data_i[lvl+j].
        check_sel1_forward_bit: assert property (
          @(posedge clk) disable iff (1'b0) (select_i) |=> (Data_o[j] == Data_i[lvl + j])
        );
      end
    end
  endgenerate

endmodule

