sva:
module TLATNTSCAX2TS_sva (
    input logic E,
    input logic SE,
    input logic CK,
    input logic ECK
);
    ///// Functional equivalence /////
    // ECK equals E & SE.
    check_eck_and_equation: assert property (
        @(posedge CK) ECK == (E & SE)
    );
    // If E is LOW, ECK must be LOW.
    check_eck_low_when_e_low: assert property (
        @(posedge CK) (E == 1'b0) |-> (ECK == 1'b0)
    );
    // If SE is LOW, ECK must be LOW.
    check_eck_low_when_se_low: assert property (
        @(posedge CK) (SE == 1'b0) |-> (ECK == 1'b0)
    );
    // If ECK is HIGH, both E and SE are HIGH.
    check_eck_high_implies_inputs_high: assert property (
        @(posedge CK) (ECK == 1'b1) |-> (E == 1'b1) && (SE == 1'b1)
    );
    // When E is HIGH, ECK mirrors SE.
    check_eck_equals_se_when_e_high: assert property (
        @(posedge CK) (E == 1'b1) |-> (ECK == SE)
    );
    // When SE is HIGH, ECK mirrors E.
    check_eck_equals_e_when_se_high: assert property (
        @(posedge CK) (SE == 1'b1) |-> (ECK == E)
    );
    // ECK rising edge only when both inputs are HIGH.
    check_no_false_rise_eck: assert property (
        @(posedge CK) $rose(ECK) |-> (E && SE)
    );
    // ECK falling edge only when at least one input is LOW.
    check_no_false_fall_eck: assert property (
        @(posedge CK) $fell(ECK) |-> !(E && SE)
    );
    // If E rises while SE is HIGH, ECK must rise.
    check_eck_rises_on_e_rise_with_se_high: assert property (
        @(posedge CK) ($rose(E) && (SE == 1'b1)) |-> $rose(ECK)
    );
    // If SE rises while E is HIGH, ECK must rise.
    check_eck_rises_on_se_rise_with_e_high: assert property (
        @(posedge CK) ($rose(SE) && (E == 1'b1)) |-> $rose(ECK)
    );
    // If both inputs are stable, ECK is stable.
    check_eck_stable_when_inputs_stable: assert property (
        @(posedge CK) $stable(E) && $stable(SE) |-> $stable(ECK)
    );
endmodule

module clock_gate_sva (
    input logic CLK,
    input logic EN,
    input logic TE,
    input logic ENCLK
);
    ///// Functional equivalence /////
    // ENCLK equals EN & TE.
    check_enclk_and_equation: assert property (
        @(posedge CLK) ENCLK == (EN & TE)
    );
    // If EN is LOW, ENCLK must be LOW.
    check_enclk_low_when_en_low: assert property (
        @(posedge CLK) (EN == 1'b0) |-> (ENCLK == 1'b0)
    );
    // If TE is LOW, ENCLK must be LOW.
    check_enclk_low_when_te_low: assert property (
        @(posedge CLK) (TE == 1'b0) |-> (ENCLK == 1'b0)
    );
    // If ENCLK is HIGH, both EN and TE are HIGH.
    check_enclk_high_implies_inputs_high: assert property (
        @(posedge CLK) (ENCLK == 1'b1) |-> (EN == 1'b1) && (TE == 1'b1)
    );
    // When EN is HIGH, ENCLK mirrors TE.
    check_enclk_equals_te_when_en_high: assert property (
        @(posedge CLK) (EN == 1'b1) |-> (ENCLK == TE)
    );
    // When TE is HIGH, ENCLK mirrors EN.
    check_enclk_equals_en_when_te_high: assert property (
        @(posedge CLK) (TE == 1'b1) |-> (ENCLK == EN)
    );
    // ENCLK rising edge only when both inputs are HIGH.
    check_no_false_rise_enclk: assert property (
        @(posedge CLK) $rose(ENCLK) |-> (EN && TE)
    );
    // ENCLK falling edge only when at least one input is LOW.
    check_no_false_fall_enclk: assert property (
        @(posedge CLK) $fell(ENCLK) |-> !(EN && TE)
    );
    // If EN rises while TE is HIGH, ENCLK must rise.
    check_enclk_rises_on_en_rise_with_te_high: assert property (
        @(posedge CLK) ($rose(EN) && (TE == 1'b1)) |-> $rose(ENCLK)
    );
    // If TE rises while EN is HIGH, ENCLK must rise.
    check_enclk_rises_on_te_rise_with_en_high: assert property (
        @(posedge CLK) ($rose(TE) && (EN == 1'b1)) |-> $rose(ENCLK)
    );
    // If both inputs are stable, ENCLK is stable.
    check_enclk_stable_when_inputs_stable: assert property (
        @(posedge CLK) $stable(EN) && $stable(TE) |-> $stable(ENCLK)
    );
endmodule

module up_down_counter_sva (
    input logic clk,
    input logic up_down,
    input logic reset,
    input logic [3:0] q
);
    // On a clock where reset=1, q must be 0 on the next clock.
    check_reset_to_zero_next: assert property (
        @(posedge clk) reset |=> (q == 4'd0)
    );

    // While reset is held high across clocks, q stays 0.
    check_reset_held_forces_zero: assert property (
        @(posedge clk) (reset && $past(reset)) |-> (q == 4'd0)
    );

    // General 1-cycle update: after any active cycle, q matches the prior cycle's rule.
    check_general_state_update: assert property (
        @(posedge clk) disable iff (reset)
            $past(1'b1) |-> ( q == ( $past(reset) ? 4'd0
                                              : ($past(up_down) ? ($past(q) + 4'd1)
                                                                : ($past(q) - 4'd1)) ) )
    );

    // If last cycle was active and up_down=1, q increments by 1 modulo 16.
    check_increment_step: assert property (
        @(posedge clk) disable iff (reset)
            ($past(!reset) && $past(up_down)) |-> (q == ($past(q) + 4'd1))
    );

    // If last cycle was active and up_down=0, q decrements by 1 modulo 16.
    check_decrement_step: assert property (
        @(posedge clk) disable iff (reset)
            ($past(!reset) && !$past(up_down)) |-> (q == ($past(q) - 4'd1))
    );

    // Increment wrap: from 0xF with up_down=1 goes to 0x0.
    check_wrap_inc_from_max: assert property (
        @(posedge clk) disable iff (reset)
            ($past(!reset) && $past(up_down) && ($past(q) == 4'hF)) |-> (q == 4'h0)
    );

    // Decrement wrap: from 0x0 with up_down=0 goes to 0xF.
    check_wrap_dec_from_min: assert property (
        @(posedge clk) disable iff (reset)
            ($past(!reset) && !$past(up_down) && ($past(q) == 4'h0)) |-> (q == 4'hF)
    );

    // On every active cycle, q must change value (never hold).
    check_value_changes_each_active_cycle: assert property (
        @(posedge clk) disable iff (reset)
            $past(!reset) |-> (q != $past(q))
    );

    // Two consecutive active increments advance q by 2 modulo 16.
    check_two_cycle_inc_progress: assert property (
        @(posedge clk) disable iff (reset)
            ($past(!reset && up_down, 2) && $past(!reset && up_down, 1))
                |-> (q == ($past(q, 2) + 4'd2))
    );

    // Two consecutive active decrements decrease q by 2 modulo 16.
    check_two_cycle_dec_progress: assert property (
        @(posedge clk) disable iff (reset)
            ($past(!reset && !up_down, 2) && $past(!reset && !up_down, 1))
                |-> (q == ($past(q, 2) - 4'd2))
    );

    // On the cycle immediately after reset was 1, q must be 0 (release behavior).
    check_reset_release_yields_zero: assert property (
        @(posedge clk) disable iff (reset)
            ($past(reset) && !reset) |-> (q == 4'd0)
    );
endmodule

module top_module_sva (
    input logic clk,
    input logic reset,
    input logic enable,
    input logic [3:0] A,
    input logic [3:0] final_output
);
    ///// Reset behavior /////
    // While reset is LOW, final_output equals A + 3 (counter held at 0).
    check_reset_low_output_eq_A_plus3: assert property (
        @(posedge clk) (!reset) |-> (final_output == (A + 4'd3))
    );

    // While reset is LOW and A is stable, final_output remains stable.
    check_reset_low_stableA_output_stable: assert property (
        @(posedge clk) (!reset && $stable(A)) |-> $stable(final_output)
    );

    // On reset deassertion edge, final_output equals A + 3.
    check_reset_release_output_eq_A_plus3: assert property (
        @(posedge clk) $rose(reset) |-> (final_output == (A + 4'd3))
    );

    ///// Functional behavior with counter /////
    // With A stable across cycles, final_output advances by $past(enable) (mod 16).
    check_step_with_stableA_prev_enable: assert property (
        @(posedge clk) disable iff (!reset)
            $past(reset) && (A == $past(A))
            |-> final_output == ($past(final_output) + ($past(enable) ? 4'd1 : 4'd0))
    );

    // General delta: if previous enable was 0, delta(final_output) equals delta(A) (mod 16).
    check_delta_with_prev_enable0: assert property (
        @(posedge clk) disable iff (!reset)
            $past(reset) && ($past(enable) == 1'b0)
            |-> final_output == ($past(final_output) + (A + (~$past(A) + 4'd1)))
    );

    // General delta: if previous enable was 1, delta(final_output) equals delta(A)+1 (mod 16).
    check_delta_with_prev_enable1: assert property (
        @(posedge clk) disable iff (!reset)
            $past(reset) && ($past(enable) == 1'b1)
            |-> final_output == ($past(final_output) + (A + (~$past(A) + 4'd1)) + 4'd1)
    );

    // Over two cycles with A stable and enable HIGH in both, final_output increases by 2 (mod 16).
    check_two_cycle_inc_enable_high_stable_A: assert property (
        @(posedge clk) disable iff (!reset)
            $past(reset,2) &&
            (A == $past(A)) && ($past(A) == $past(A,2)) &&
            $past(enable) && $past(enable,2)
            |-> final_output == ($past(final_output,2) + 4'd2)
    );

    // Over two cycles with A stable and enable LOW in both, final_output holds.
    check_two_cycle_hold_enable_low_stable_A: assert property (
        @(posedge clk) disable iff (!reset)
            $past(reset,2) &&
            (A == $past(A)) && ($past(A) == $past(A,2)) &&
            !$past(enable) && !$past(enable,2)
            |-> final_output == $past(final_output,2)
    );
endmodule

