sva:
module my_module_sva (
    input logic CLK,
    input logic RESETn,
    input logic X,
    input logic A1_N,
    input logic A2_N,
    input logic B1,
    input logic B2
);
    ///// Combinational function checks /////
    // X equals (~(A2_N & A1_N)) & (B1 | B2).
    check_x_boolean_definition: assert property (
        @(posedge CLK) disable iff (!RESETn) X == ((~(A2_N & A1_N)) & (B1 | B2))
    );

    // If both A1_N and A2_N are 1, X must be 0.
    check_x_zero_when_A_both_high: assert property (
        @(posedge CLK) disable iff (!RESETn) (A1_N && A2_N) |-> (X == 1'b0)
    );

    // If both B1 and B2 are 0, X must be 0.
    check_x_zero_when_B_both_low: assert property (
        @(posedge CLK) disable iff (!RESETn) (!B1 && !B2) |-> (X == 1'b0)
    );

    // If (B1|B2)=1 and any A*_N is 0, X must be 1.
    check_x_one_when_B_or_and_any_A_low: assert property (
        @(posedge CLK) disable iff (!RESETn) ((B1 || B2) && (!A1_N || !A2_N)) |-> (X == 1'b1)
    );

    // X high implies B1 or B2 is high.
    check_x_high_implies_B_or: assert property (
        @(posedge CLK) disable iff (!RESETn) X |-> (B1 || B2)
    );

    // X high implies not(A1_N & A2_N).
    check_x_high_implies_not_A_and: assert property (
        @(posedge CLK) disable iff (!RESETn) X |-> !(A1_N && A2_N)
    );

    // X high implies both conditions: (B1|B2)=1 and not(A1_N & A2_N).
    check_x_high_implies_required_conditions: assert property (
        @(posedge CLK) disable iff (!RESETn) X |-> ((B1 || B2) && !(A1_N && A2_N))
    );

    // Output can only change when at least one input changes.
    check_x_changes_only_with_input_change: assert property (
        @(posedge CLK) disable iff (!RESETn) $changed(X) |-> $changed({A1_N, A2_N, B1, B2})
    );
endmodule

rtl:
module Comparator #(
  parameter n = 8
) (
  input [n-1:0] a,
  input [n-1:0] b,
  output eq,
  output gt,
  output lt
);


reg [2:0] result;

always @(*) begin
  if (a == b) begin
    result = 3'b001; // a equals b
  end else if (a > b) begin
    result = 3'b010; // a is greater than b
  end else begin
    result = 3'b100; // a is less than b
  end
end

assign eq = (result == 3'b001);
assign gt = (result == 3'b010);
assign lt = (result == 3'b100);

endmodule

sva:
module Comparator_sva #(
  parameter int n = 8
) (
  input  logic [n-1:0] a,
  input  logic [n-1:0] b,
  input  logic         eq,
  input  logic         gt,
  input  logic         lt
);

    ///// Output coding /////
    // Exactly one of eq/gt/lt must be HIGH (one-hot).
    check_outputs_onehot: assert property (
        @(posedge a[0] or negedge a[0] or posedge b[0] or negedge b[0] or
          posedge eq   or negedge eq   or posedge gt   or negedge gt   or
          posedge lt   or negedge lt)
        $onehot({eq, gt, lt})
    );

    // Outputs are never X/Z.
    check_outputs_known: assert property (
        @(posedge a[0] or negedge a[0] or posedge b[0] or negedge b[0] or
          posedge eq   or negedge eq   or posedge gt   or negedge gt   or
          posedge lt   or negedge lt)
        !$isunknown({eq, gt, lt})
    );

    // Outputs are never all zero (completeness).
    check_outputs_nonzero: assert property (
        @(posedge a[0] or negedge a[0] or posedge b[0] or negedge b[0] or
          posedge eq   or negedge eq   or posedge gt   or negedge gt   or
          posedge lt   or negedge lt)
        (eq || gt || lt)
    );

    ///// Functional mapping /////
    // If a == b, then eq=1 and gt=0, lt=0.
    map_equal_to_eq: assert property (
        @(posedge a[0] or negedge a[0] or posedge b[0] or negedge b[0] or
          posedge eq   or negedge eq   or posedge gt   or negedge gt   or
          posedge lt   or negedge lt)
        (a == b) |-> (eq && !gt && !lt)
    );

    // If a > b, then gt=1 and eq=0, lt=0.
    map_greater_to_gt: assert property (
        @(posedge a[0] or negedge a[0] or posedge b[0] or negedge b[0] or
          posedge eq   or negedge eq   or posedge gt   or negedge gt   or
          posedge lt   or negedge lt)
        (a > b) |-> (gt && !eq && !lt)
    );

    // If neither (a == b) nor (a > b), then lt=1 and eq=0, gt=0.
    map_else_to_lt: assert property (
        @(posedge a[0] or negedge a[0] or posedge b[0] or negedge b[0] or
          posedge eq   or negedge eq   or posedge gt   or negedge gt   or
          posedge lt   or negedge lt)
        (!(a == b) && !(a > b)) |-> (lt && !eq && !gt)
    );

    ///// Output-to-input consistency /////
    // eq implies a == b.
    eq_implies_equal: assert property (
        @(posedge a[0] or negedge a[0] or posedge b[0] or negedge b[0] or
          posedge eq   or negedge eq   or posedge gt   or negedge gt   or
          posedge lt   or negedge lt)
        eq |-> (a == b)
    );

    // gt implies a > b.
    gt_implies_greater: assert property (
        @(posedge a[0] or negedge a[0] or posedge b[0] or negedge b[0] or
          posedge eq   or negedge eq   or posedge gt   or negedge gt   or
          posedge lt   or negedge lt)
        gt |-> (a > b)
    );

endmodule

rtl:
module full_adder (
  input A,
  input B,
  input C_in,
  output S,
  output C_out
);

assign S = A ^ B ^ C_in;
assign C_out = (A & B) | (A & C_in) | (B & C_in);

endmodule
module ripple_carry_adder #(
  parameter n = 4 // number of bits in A and B
)(
  input [n-1:0] A,
  input [n-1:0] B,
  output [n:0] C
);

wire [n:0] carry; // carry signals for each bit position

// generate carry signals
genvar i;
generate
  for (i = 0; i < n; i = i + 1) begin : carry_gen
    full_adder fa(
      .A(A[i]),
      .B(B[i]),
      .C_in(carry[i]),
      .S(C[i]),
      .C_out(carry[i+1])
    );
  end
endgenerate

// set carry-in for least significant bit
assign carry[0] = 1'b0;

// assign output
assign C[n] = carry[n];

endmodule

sva:
module ripple_carry_adder_sva #(
    parameter int n = 4
)(
    input  logic                 clk,  // sampling clock for SVA (DUT is combinational)
    input  logic [n-1:0]         A,
    input  logic [n-1:0]         B,
    input  logic [n:0]           C
);
    ///// Functional equivalence /////
    // C equals zero-extended sum of A and B.
    check_full_sum_correct: assert property (
        @(posedge clk) disable iff (1'b0) C == ({1'b0, A} + {1'b0, B})
    );

    // MSB carry equals MSB of the zero-extended addition.
    check_msb_carry_bit: assert property (
        @(posedge clk) disable iff (1'b0) C[n] == (({1'b0, A} + {1'b0, B})[n])
    );

    ///// Bit-level consequences /////
    // LSB sum is XOR since carry-in is 0.
    check_lsb_sum: assert property (
        @(posedge clk) disable iff (1'b0) C[0] == (A[0] ^ B[0])
    );

    // Carry into bit1 equals A[0] & B[0] (only if bit1 exists).
    generate if (n >= 1) begin : have_bit1
        check_carry1_from_lsb: assert property (
            @(posedge clk) disable iff (1'b0) C[1] == (A[0] & B[0])
        );
    end endgenerate

    // For each prefix, low (i+1) sum bits match truncated addition.
    generate
        genvar i;
        for (i = 0; i < n; i = i + 1) begin : gen_lower_partial_sum
            check_lower_partial_sum: assert property (
                @(posedge clk) disable iff (1'b0) C[i:0] == (A[i:0] + B[i:0])
            );
        end
    endgenerate

    // Bit j equals XOR of A[j], B[j], and carry-in from lower bits.
    generate
        genvar j;
        for (j = 1; j < n; j = j + 1) begin : gen_bit_sum_with_carry_in
            check_bit_sum_with_carry_in: assert property (
                @(posedge clk) disable iff (1'b0)
                    C[j] == ((A[j] ^ B[j]) ^ (({1'b0, A[j-1:0]} + {1'b0, B[j-1:0]})[j]))
            );
        end
    endgenerate

    ///// Special operand cases /////
    // If A is zero, C passes through B (zero-extended).
    check_zero_a_passthrough: assert property (
        @(posedge clk) disable iff (1'b0) (A == '0) |-> (C == {1'b0, B})
    );

    // If B is zero, C passes through A (zero-extended).
    check_zero_b_passthrough: assert property (
        @(posedge clk) disable iff (1'b0) (B == '0) |-> (C == {1'b0, A})
    );

    // If A == B, result equals 2*A (zero-extended then left-shifted).
    check_doubling_when_equal: assert property (
        @(posedge clk) disable iff (1'b0) (A == B) |-> (C == ({1'b0, A} << 1))
    );

    // If B is bitwise NOT of A, sum is all ones with no carry-out.
    check_complement_all_ones: assert property (
        @(posedge clk) disable iff (1'b0) (B == ~A) |-> (C == {1'b0, {n{1'b1}}})
    );

    ///// Stability /////
    // With stable inputs across cycles, the output remains stable (combinational determinism).
    check_stable_when_inputs_stable: assert property (
        @(posedge clk) disable iff (1'b0) ($stable(A) && $stable(B)) |-> $stable(C)
    );
endmodule

