sva:
module sky130_fd_sc_hd__maj3_sva (
    input logic X,
    input logic A,
    input logic B,
    input logic C
);

    ///// Majority function /////
    // X equals the majority-of-three of A, B, C.
    check_majority_equivalence: assert property (
        @(posedge $global_clock) disable iff (1'b0) X == ((A & B) | (A & C) | (B & C))
    );

    ///// Dominance when two inputs match /////
    // If A equals B, X must equal A.
    check_equal_ab_dominates: assert property (
        @(posedge $global_clock) disable iff (1'b0) (A == B) |-> (X == A)
    );
    // If A equals C, X must equal A.
    check_equal_ac_dominates: assert property (
        @(posedge $global_clock) disable iff (1'b0) (A == C) |-> (X == A)
    );
    // If B equals C, X must equal B.
    check_equal_bc_dominates: assert property (
        @(posedge $global_clock) disable iff (1'b0) (B == C) |-> (X == B)
    );

    ///// At least two inputs HIGH implies X HIGH /////
    // If A and B are 1, X must be 1 (independent of C).
    check_two_high_ab_implies_x: assert property (
        @(posedge $global_clock) disable iff (1'b0) (A && B) |-> (X == 1'b1)
    );
    // If A and C are 1, X must be 1 (independent of B).
    check_two_high_ac_implies_x: assert property (
        @(posedge $global_clock) disable iff (1'b0) (A && C) |-> (X == 1'b1)
    );
    // If B and C are 1, X must be 1 (independent of A).
    check_two_high_bc_implies_x: assert property (
        @(posedge $global_clock) disable iff (1'b0) (B && C) |-> (X == 1'b1)
    );

    ///// At least two inputs LOW implies X LOW /////
    // If A and B are 0, X must be 0 (independent of C).
    check_two_low_ab_implies_nx: assert property (
        @(posedge $global_clock) disable iff (1'b0) (!A && !B) |-> (X == 1'b0)
    );
    // If A and C are 0, X must be 0 (independent of B).
    check_two_low_ac_implies_nx: assert property (
        @(posedge $global_clock) disable iff (1'b0) (!A && !C) |-> (X == 1'b0)
    );
    // If B and C are 0, X must be 0 (independent of A).
    check_two_low_bc_implies_nx: assert property (
        @(posedge $global_clock) disable iff (1'b0) (!B && !C) |-> (X == 1'b0)
    );

endmodule

rtl:
module adder (
    input [15:0] A,
    input [15:0] B,
    input CIN,
    output [15:0] SUM,
    output COUT
);

    assign {COUT, SUM} = A + B + CIN;

endmodule

sva:
module adder_sva (
    input logic CLK,
    input logic [15:0] A,
    input logic [15:0] B,
    input logic CIN,
    input logic [15:0] SUM,
    input logic COUT
);
    ///// Functional equivalence to RTL /////
    // SUM equals the 16-bit truncated result of A + B + CIN.
    check_sum_matches_add: assert property (
        @(posedge CLK) SUM == (A + B + CIN)
    );

    // COUT is always zero because the RHS sum is 16-bit and the MSB is zero-extended.
    check_cout_always_zero: assert property (
        @(posedge CLK) COUT == 1'b0
    );

    // {COUT,SUM} equals zero-extended 16-bit addition.
    check_concat_zeroext_add: assert property (
        @(posedge CLK) {COUT, SUM} == {1'b0, (A + B + CIN)}
    );

    ///// Basic pass-through scenarios /////
    // With B==0 and CIN==0, SUM passes A and COUT stays zero.
    check_pass_through_a: assert property (
        @(posedge CLK) (B == 16'h0000) && (CIN == 1'b0) |-> (SUM == A) && (COUT == 1'b0)
    );

    // With A==0 and CIN==0, SUM passes B and COUT stays zero.
    check_pass_through_b: assert property (
        @(posedge CLK) (A == 16'h0000) && (CIN == 1'b0) |-> (SUM == B) && (COUT == 1'b0)
    );

    // With A==0 and B==0, SUM equals CIN and COUT stays zero.
    check_only_cin: assert property (
        @(posedge CLK) (A == 16'h0000) && (B == 16'h0000) |-> (SUM == {15'b0, CIN}) && (COUT == 1'b0)
    );

    ///// Arithmetic identities preserved by 16-bit truncation /////
    // For two's-complement wraparound: A + ~A + 1 = 0 (truncated), so SUM==0 and COUT==0.
    check_twos_complement_cancel: assert property (
        @(posedge CLK) (B == ~A) && (CIN == 1'b1) |-> (SUM == 16'h0000) && (COUT == 1'b0)
    );

    ///// Bit-level consequence /////
    // LSB of SUM equals parity of LSBs and CIN for 16-bit addition.
    check_sum_bit0_parity: assert property (
        @(posedge CLK) SUM[0] == (A[0] ^ B[0] ^ CIN)
    );

    ///// Commutativity reflection /////
    // The computed SUM is commutative in A and B.
    check_sum_commutative: assert property (
        @(posedge CLK) (A + B + CIN) == (B + A + CIN)
    );

endmodule

rtl:
module addsub(
    input [3:0] A,
    input [3:0] B,
    input sel,
    output [3:0] sum,
    output cout
    );

    wire [3:0] B_comp;

    assign B_comp = ~B + 1;

    assign sum = (sel == 1) ? A + B_comp : A + B;
    assign cout = (sel == 1) ? (A < B) : (sum < A);

endmodule

sva:
module addsub_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic sel,
    input logic [3:0] sum,
    input logic cout
);
    // When sel=0, sum equals 4-bit A+B.
    check_sum_add_path: assert property (
        @(posedge clk) (sel == 1'b0) |-> (sum == (A + B))
    );

    // When sel=1, sum equals 4-bit A + (~B + 1).
    check_sum_sub_path: assert property (
        @(posedge clk) (sel == 1'b1) |-> (sum == (A + (~B + 4'b0001)))
    );

    // When sel=0, cout indicates carry by sum < A.
    check_cout_add_path: assert property (
        @(posedge clk) (sel == 1'b0) |-> (cout == (sum < A))
    );

    // When sel=1, cout indicates borrow by A < B.
    check_cout_sub_path: assert property (
        @(posedge clk) (sel == 1'b1) |-> (cout == (A < B))
    );

    // When sel=0, cout equals MSB of 5-bit A+B.
    check_add_carry_bit_equivalence: assert property (
        @(posedge clk) (sel == 1'b0) |-> (cout == ({1'b0, A} + {1'b0, B})[4])
    );

    // When sel=0, (sum - A) mod 16 equals B.
    check_add_inverse_relation_sum_minus_A_eq_B: assert property (
        @(posedge clk) (sel == 1'b0) |-> ((sum + (~A + 4'b0001)) == B)
    );

    // When sel=1, (sum + B) mod 16 equals A.
    check_sub_inverse_relation_sum_plus_B_eq_A: assert property (
        @(posedge clk) (sel == 1'b1) |-> ((sum + B) == A)
    );

    // When sel=0 and B==0, sum==A and no carry.
    check_add_B_zero_case: assert property (
        @(posedge clk) ((sel == 1'b0) && (B == 4'b0000)) |-> ((sum == A) && (cout == 1'b0))
    );

    // When sel=1 and B==0, sum==A and no borrow.
    check_sub_B_zero_case: assert property (
        @(posedge clk) ((sel == 1'b1) && (B == 4'b0000)) |-> ((sum == A) && (cout == 1'b0))
    );

    // When sel=1 and A==B, sum==0 and no borrow.
    check_sub_equal_operands_yield_zero: assert property (
        @(posedge clk) ((sel == 1'b1) && (A == B)) |-> ((sum == 4'b0000) && (cout == 1'b0))
    );

    // When sel=1 and borrow occurs, result wraps above A.
    check_sub_borrow_implies_sum_gt_A: assert property (
        @(posedge clk) ((sel == 1'b1) && (cout == 1'b1)) |-> (sum > A)
    );

    // When sel=1 and no borrow, result is <= A.
    check_sub_no_borrow_implies_sum_le_A: assert property (
        @(posedge clk) ((sel == 1'b1) && (cout == 1'b0)) |-> (sum <= A)
    );
endmodule

