module custom_logic (
    output Y,
    input  A1,
    input  A2,
    input  B1_N
);

    // Local signals
    wire not_B1_N;
    wire and0_out;
    wire and1_out;
    wire or0_out;
    wire nand0_out_Y;

    // Gate-level primitives
    not  u_not_B1_N (not_B1_N, B1_N);
    and  u_and0     (and0_out, A1, A2);
    and  u_and1     (and1_out, not_B1_N, and0_out);
    or   u_or0      (or0_out, A1, A2);
    nand u_nand0    (nand0_out_Y, and1_out, or0_out);
    buf  u_buf0     (Y, nand0_out_Y);

endmodule

sva:
module custom_logic_sva (
    input logic CLK,
    input logic A1,
    input logic A2,
    input logic B1_N,
    input logic Y,
    // Internal nets from RTL (optional to bind)
    input logic not_B1_N,
    input logic and0_out,
    input logic and1_out,
    input logic or0_out,
    input logic nand0_out_Y
);
    ///// Gate-level correctness /////
    // not_B1_N is the inversion of B1_N.
    check_not_B1N_inversion: assert property (
        @(posedge CLK) not_B1_N == ~B1_N
    );
    // and0_out is A1 AND A2.
    check_and0_function: assert property (
        @(posedge CLK) and0_out == (A1 & A2)
    );
    // and1_out is not_B1_N AND and0_out.
    check_and1_function: assert property (
        @(posedge CLK) and1_out == (not_B1_N & and0_out)
    );
    // or0_out is A1 OR A2.
    check_or0_function: assert property (
        @(posedge CLK) or0_out == (A1 | A2)
    );
    // nand0_out_Y is NAND of and1_out and or0_out.
    check_nand0_function: assert property (
        @(posedge CLK) nand0_out_Y == ~(and1_out & or0_out)
    );
    // Y is a buffered version of nand0_out_Y.
    check_buf_to_Y: assert property (
        @(posedge CLK) Y == nand0_out_Y
    );

    ///// Functional equivalence and implications on top-level ports /////
    // Y equals (B1_N | ~A1 | ~A2) (simplified function).
    check_simplified_function: assert property (
        @(posedge CLK) Y == (B1_N | ~A1 | ~A2)
    );
    // If B1_N is HIGH, Y must be HIGH.
    check_B1N_high_forces_Y_high: assert property (
        @(posedge CLK) (B1_N == 1'b1) |=> (Y == 1'b1)
    );
    // If A1 is LOW or A2 is LOW, Y must be HIGH.
    check_A1_or_A2_low_forces_Y_high: assert property (
        @(posedge CLK) ((A1 == 1'b0) || (A2 == 1'b0)) |=> (Y == 1'b1)
    );
    // If B1_N is LOW and A1 and A2 are HIGH, Y must be LOW.
    check_all_high_B1N_low_drives_Y_low: assert property (
        @(posedge CLK) ((B1_N == 1'b0) && (A1 == 1'b1) && (A2 == 1'b1)) |=> (Y == 1'b0)
    );
    // Y can be LOW only when B1_N is LOW and A1 and A2 are HIGH.
    check_Y_low_only_when_all_high_and_B1N_low: assert property (
        @(posedge CLK) (Y == 1'b0) |=> ((B1_N == 1'b0) && (A1 == 1'b1) && (A2 == 1'b1))
    );
endmodule

rtl:
module bin2gray (
  input clk,
  input [3:0] bin,
  output reg [3:0] gray
);

reg [3:0] prev_bin;

always @(posedge clk) begin
  if (bin !== prev_bin) begin
    gray[3] = bin[3];
    gray[2] = bin[3] ^ bin[2];
    gray[1] = bin[2] ^ bin[1];
    gray[0] = bin[1] ^ bin[0];
    prev_bin <= bin;
  end
end

endmodule

sva:
module bin2gray_sva (
    input logic        clk,
    input logic [3:0]  bin,
    input logic [3:0]  gray,
    input logic [3:0]  prev_bin
);
    // Clock: clk (posedge). No reset in RTL. Sequential logic gated by bin !== prev_bin.

    // When bin differs from prev_bin, gray must be current-cycle bin encoded to Gray.
    check_gray_update_value: assert property (
        @(posedge clk) (bin !== prev_bin) |-> (gray === {bin[3], (bin[3]^bin[2]), (bin[2]^bin[1]), (bin[1]^bin[0])})
    );

    // Bit mapping MSB on update: gray[3] equals bin[3].
    check_gray_msb_mapping_on_update: assert property (
        @(posedge clk) (bin !== prev_bin) |-> (gray[3] === bin[3])
    );

    // Bit mapping bit2 on update: gray[2] equals bin[3]^bin[2].
    check_gray_bit2_mapping_on_update: assert property (
        @(posedge clk) (bin !== prev_bin) |-> (gray[2] === (bin[3]^bin[2]))
    );

    // Bit mapping bit1 on update: gray[1] equals bin[2]^bin[1].
    check_gray_bit1_mapping_on_update: assert property (
        @(posedge clk) (bin !== prev_bin) |-> (gray[1] === (bin[2]^bin[1]))
    );

    // Bit mapping bit0 on update: gray[0] equals bin[1]^bin[0].
    check_gray_bit0_mapping_on_update: assert property (
        @(posedge clk) (bin !== prev_bin) |-> (gray[0] === (bin[1]^bin[0]))
    );

    // After an update, prev_bin captures the prior-cycle bin.
    check_prev_bin_updates_next_cycle: assert property (
        @(posedge clk) (bin !== prev_bin) |=> (prev_bin === $past(bin))
    );

    // Any change on gray must coincide with update condition in that cycle.
    check_gray_change_requires_update_condition: assert property (
        @(posedge clk) $changed(gray) |-> (bin !== prev_bin)
    );

    // Any change on prev_bin must have been caused by update condition in the prior cycle.
    check_prev_bin_change_requires_prior_update: assert property (
        @(posedge clk) $changed(prev_bin) |-> $past(bin !== $past(prev_bin))
    );

    // If no update condition, hold gray and prev_bin stable into next cycle.
    check_hold_stable_when_equal: assert property (
        @(posedge clk) (bin === prev_bin) |=> (gray === $past(gray)) && (prev_bin === $past(prev_bin))
    );

    // If no update condition, gray equals Gray(bin) in that cycle.
    check_gray_function_when_equal: assert property (
        @(posedge clk) (bin === prev_bin) |-> (gray === {bin[3], (bin[3]^bin[2]), (bin[2]^bin[1]), (bin[1]^bin[0])})
    );

endmodule

