module top_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input [7:0] d1,   // 8-bit input for the first register
    input [7:0] d2,   // 8-bit input for the second register
    output [7:0] q    // 8-bit output from the functional module
);

    reg [7:0] reg1, reg2;
    wire [7:0] diff;

    // Registers with synchronous reset
    always @(posedge clk) begin
        if (reset) begin
            reg1 <= 8'd0;
            reg2 <= 8'd0;
        end else begin
            reg1 <= d1;
            reg2 <= d2;
        end
    end

    // Difference calculator
    assign diff = reg1 - reg2;

    // Output
    assign q = diff;

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic reset,       // Synchronous active-high reset
    input logic [7:0] d1,
    input logic [7:0] d2,
    input logic [7:0] q,
    // Internal signals from DUT (bind hierarchically)
    input logic [7:0] reg1,
    input logic [7:0] reg2,
    input logic [7:0] diff
);
    ///// Reset behavior /////
    // During reset, registers and outputs are driven to zero.
    reset_clears_state_and_output: assert property (
        @(posedge clk) reset |-> (reg1 == 8'd0) && (reg2 == 8'd0) && (diff == 8'd0) && (q == 8'd0)
    );

    ///// Register load behavior /////
    // reg1 captures d1 on each rising edge when not in reset.
    reg1_loads_d1_on_nonreset: assert property (
        @(posedge clk) disable iff (reset) reg1 == d1
    );
    // reg2 captures d2 on each rising edge when not in reset.
    reg2_loads_d2_on_nonreset: assert property (
        @(posedge clk) disable iff (reset) reg2 == d2
    );

    ///// Combinational datapath wiring /////
    // diff equals reg1 - reg2.
    diff_matches_regs_sub: assert property (
        @(posedge clk) disable iff (reset) diff == (reg1 - reg2)
    );
    // q is directly driven by diff.
    q_matches_diff: assert property (
        @(posedge clk) disable iff (reset) q == diff
    );
    // q equals reg1 - reg2.
    q_matches_regs_sub: assert property (
        @(posedge clk) disable iff (reset) q == (reg1 - reg2)
    );

    ///// Arithmetic identities from the subtraction /////
    // (reg1 - reg2) + reg2 == reg1 (modulo 8-bit).
    add_inverse_consistency: assert property (
        @(posedge clk) disable iff (reset) reg1 == (diff + reg2)
    );
    // If reg1 == reg2 then diff and q must be zero.
    equal_regs_imply_zero_output: assert property (
        @(posedge clk) disable iff (reset) (reg1 == reg2) |-> (diff == 8'd0) && (q == 8'd0)
    );

    ///// Temporal arithmetic consistency /////
    // If reg1 increments by 1 and reg2 holds, diff increments by 1.
    inc_reg1_increases_diff: assert property (
        @(posedge clk) disable iff (reset)
            (reg1 == $past(reg1) + 8'd1 && reg2 == $past(reg2)) |-> (diff == $past(diff) + 8'd1)
    );
    // If reg2 increments by 1 and reg1 holds, diff decrements by 1.
    inc_reg2_decreases_diff: assert property (
        @(posedge clk) disable iff (reset)
            (reg1 == $past(reg1) && reg2 == $past(reg2) + 8'd1) |-> (diff == $past(diff) - 8'd1)
    );
endmodule

module next_higher_binary_sva (
    input logic CLK,
    input logic [3:0] in,
    input logic [3:0] out
);
    // When in==0000, out must be 0001.
    check_map_0000_to_0001: assert property (
        @(posedge CLK) (in == 4'b0000) |=> (out == 4'b0001)
    );
    // When in==0001, out must be 0010.
    check_map_0001_to_0010: assert property (
        @(posedge CLK) (in == 4'b0001) |=> (out == 4'b0010)
    );
    // When in==0010, out must be 0011.
    check_map_0010_to_0011: assert property (
        @(posedge CLK) (in == 4'b0010) |=> (out == 4'b0011)
    );
    // When in==0011, out must be 0100.
    check_map_0011_to_0100: assert property (
        @(posedge CLK) (in == 4'b0011) |=> (out == 4'b0100)
    );
    // When in==0100, out must be 0101.
    check_map_0100_to_0101: assert property (
        @(posedge CLK) (in == 4'b0100) |=> (out == 4'b0101)
    );
    // When in==0101, out must be 0110.
    check_map_0101_to_0110: assert property (
        @(posedge CLK) (in == 4'b0101) |=> (out == 4'b0110)
    );
    // When in==0110, out must be 0111.
    check_map_0110_to_0111: assert property (
        @(posedge CLK) (in == 4'b0110) |=> (out == 4'b0111)
    );
    // When in==0111, out must be 1000.
    check_map_0111_to_1000: assert property (
        @(posedge CLK) (in == 4'b0111) |=> (out == 4'b1000)
    );
    // When in==1000, out must be 1001.
    check_map_1000_to_1001: assert property (
        @(posedge CLK) (in == 4'b1000) |=> (out == 4'b1001)
    );
    // When in==1001, out must be 1010.
    check_map_1001_to_1010: assert property (
        @(posedge CLK) (in == 4'b1001) |=> (out == 4'b1010)
    );
    // When in==1010, out must be 1011.
    check_map_1010_to_1011: assert property (
        @(posedge CLK) (in == 4'b1010) |=> (out == 4'b1011)
    );
    // When in==1011, out must be 1100.
    check_map_1011_to_1100: assert property (
        @(posedge CLK) (in == 4'b1011) |=> (out == 4'b1100)
    );
    // When in==1100, out must be 1101.
    check_map_1100_to_1101: assert property (
        @(posedge CLK) (in == 4'b1100) |=> (out == 4'b1101)
    );
    // When in==1101, out must be 1110.
    check_map_1101_to_1110: assert property (
        @(posedge CLK) (in == 4'b1101) |=> (out == 4'b1110)
    );
    // When in==1110, out must be 1111.
    check_map_1110_to_1111: assert property (
        @(posedge CLK) (in == 4'b1110) |=> (out == 4'b1111)
    );
    // When in==1111, out must wrap to 0000.
    check_map_1111_to_0000: assert property (
        @(posedge CLK) (in == 4'b1111) |=> (out == 4'b0000)
    );
