sva:
module sky130_fd_sc_ls__clkdlyinv5sd2_sva (
    input logic CLK,   // sampling clock for assertions
    input logic Y,     // DUT output
    input logic A      // DUT input
);
    // Y is always the logical inversion of A at sample time.
    check_inversion_function: assert property (
        @(posedge CLK) (Y === ~A)
    );

    // A rising edge implies a falling edge on Y.
    check_roseA_fellY: assert property (
        @(posedge CLK) $rose(A) |-> $fell(Y)
    );

    // A falling edge implies a rising edge on Y.
    check_fellA_roseY: assert property (
        @(posedge CLK) $fell(A) |-> $rose(Y)
    );

    // Y rising edge implies a falling edge on A.
    check_roseY_fellA: assert property (
        @(posedge CLK) $rose(Y) |-> $fell(A)
    );

    // Y falling edge implies a rising edge on A.
    check_fellY_roseA: assert property (
        @(posedge CLK) $fell(Y) |-> $rose(A)
    );

    // If A is stable across samples, Y is stable across samples.
    check_stable_A_implies_stable_Y: assert property (
        @(posedge CLK) $stable(A) |-> $stable(Y)
    );

    // When A is known at consecutive samples, A and Y change iff each other changes.
    check_change_equivalence_when_known: assert property (
        @(posedge CLK)
            (((A === 1'b0) || (A === 1'b1)) && (($past(A) === 1'b0) || ($past(A) === 1'b1)))
            |-> ($changed(Y) == $changed(A))
    );

    // Y is never high-impedance (no tri-state drivers in DUT).
    check_Y_not_highz: assert property (
        @(posedge CLK) (Y !== 1'bz)
    );

    // When A is 0, Y must be 1.
    check_A0_implies_Y1: assert property (
        @(posedge CLK) (A === 1'b0) |-> (Y === 1'b1)
    );

    // When A is 1, Y must be 0.
    check_A1_implies_Y0: assert property (
        @(posedge CLK) (A === 1'b1) |-> (Y === 1'b0)
    );
endmodule

rtl:
module simple_arithmetic (
    input [7:0] A,
    input [7:0] B,
    input [1:0] op,
    output [7:0] out
);

    wire [7:0] add_out = A + B;
    wire [7:0] sub_out = A - B;
    wire [7:0] and_out = A & B;
    wire [7:0] or_out = A | B;

    assign out = (op == 2'b00) ? add_out :
                 (op == 2'b01) ? sub_out :
                 (op == 2'b10) ? and_out :
                                 or_out;

endmodule

sva:
module simple_arithmetic_sva (
    input logic clk,
    input logic [7:0] A,
    input logic [7:0] B,
    input logic [1:0] op,
    input logic [7:0] out
);
    ///// Functional mapping /////
    // Out matches the RTL ternary selection of operations.
    check_functional_equivalence: assert property (
        @(posedge clk) out == ((op == 2'b00) ? (A + B) :
                               (op == 2'b01) ? (A - B) :
                               (op == 2'b10) ? (A & B) :
                                               (A | B))
    );

    ///// Operation selections /////
    // When op==00, out equals A+B (8-bit wraparound).
    check_add_selection: assert property (
        @(posedge clk) (op === 2'b00) |-> (out == (A + B))
    );

    // When op==01, out equals A-B (8-bit wraparound).
    check_sub_selection: assert property (
        @(posedge clk) (op === 2'b01) |-> (out == (A - B))
    );

    // When op==10, out equals A&B.
    check_and_selection: assert property (
        @(posedge clk) (op === 2'b10) |-> (out == (A & B))
    );

    // When op==11, out equals A|B.
    check_or_selection: assert property (
        @(posedge clk) (op === 2'b11) |-> (out == (A | B))
    );

    // For any op not 00/01/10 (including X/Z), out falls through to OR.
    check_default_fallthrough_to_or: assert property (
        @(posedge clk) ((op !== 2'b00) && (op !== 2'b01) && (op !== 2'b10)) |-> (out == (A | B))
    );

    ///// Stability /////
    // With stable inputs and op across a cycle, out remains stable.
    check_stable_when_inputs_stable: assert property (
        @(posedge clk) $stable(A) && $stable(B) && $stable(op) |-> $stable(out)
    );
endmodule

