module pipeline_register #(
    parameter width = 8 // width of the data signal
)(
  input wire clk,
  input wire reset,
  input [width-1:0] data_in,
  output reg [width-1:0] data_out
);


always @(posedge clk) begin
    if (reset) begin
        data_out <= 0;
    end else begin
        data_out <= data_in;
    end
end

endmodule

sva:
module pipeline_register_sva #(
    parameter width = 8
)(
    input logic clk,
    input logic reset,
    input logic [width-1:0] data_in,
    input logic [width-1:0] data_out
);

    // Synchronous reset drives data_out to zero on the next clock.
    check_reset_clears_next: assert property (
        @(posedge clk) reset |=> (data_out == '0)
    );

    // While reset remains asserted, data_out is held at zero.
    check_hold_zero_during_continuous_reset: assert property (
        @(posedge clk) (reset && $past(reset)) |-> (data_out == '0)
    );

    // On the cycle reset deasserts, data_out is still zero (from prior reset cycle).
    check_zero_on_reset_fall_cycle: assert property (
        @(posedge clk) $fell(reset) |-> (data_out == '0)
    );

    // When previous cycle was not in reset, output equals previous input.
    check_capture_when_prev_not_reset: assert property (
        @(posedge clk) disable iff (reset) !$past(reset) |-> (data_out == $past(data_in))
    );

    // One cycle after reset deasserts, output captures input from the deassert cycle.
    check_capture_after_reset_deassert: assert property (
        @(posedge clk) $fell(reset) |=> (data_out == $past(data_in))
    );

    // On reset assertion edge, current output shows the previous cycle's input.
    check_prev_input_visible_on_reset_rise: assert property (
        @(posedge clk) $rose(reset) |-> (data_out == $past(data_in))
    );

    // If input was stable over two non-reset cycles, output does not change.
    check_out_stable_when_in_stable_no_reset: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(reset) && !$past(reset,2) && ($past(data_in) == $past(data_in,2))) |-> (data_out == $past(data_out))
    );

endmodule

rtl:
module calculator (
  input [7:0] a,
  input [7:0] b,
  input [1:0] op,
  output [7:0] result
);

  reg [7:0] result_reg;

  always @(*) begin
    case (op)
      2'b00: result_reg = a + b;
      2'b01: result_reg = a - b;
      2'b10: result_reg = a * b;
      2'b11: result_reg = a / b;
    endcase
  end

  assign result = result_reg;

endmodule

sva:
module calculator_sva (
    input logic CLK,
    input logic [7:0] a,
    input logic [7:0] b,
    input logic [1:0] op,
    input logic [7:0] result
);

    ///// Functional correctness per opcode /////
    // op=00: result equals 8-bit sum of a and b.
    check_add_result: assert property (
        @(posedge CLK) (op == 2'b00) |-> (result == ((a + b) & 8'hFF))
    );

    // op=01: result equals 8-bit difference a - b.
    check_sub_result: assert property (
        @(posedge CLK) (op == 2'b01) |-> (result == ((a - b) & 8'hFF))
    );

    // op=10: result equals low 8 bits of a * b.
    check_mul_result: assert property (
        @(posedge CLK) (op == 2'b10) |-> (result == ((a * b) & 8'hFF))
    );

    // op=11 with b!=0: result equals a / b.
    check_div_result_valid: assert property (
        @(posedge CLK) (op == 2'b11 && b != 8'd0) |-> (result == (a / b))
    );

    ///// Algebraic identities for corner cases /////
    // op=00 and b==0: result equals a.
    check_add_zero_b: assert property (
        @(posedge CLK) (op == 2'b00 && (b == 8'd0)) |-> (result == a)
    );

    // op=01 and b==0: result equals a.
    check_sub_zero_b: assert property (
        @(posedge CLK) (op == 2'b01 && (b == 8'd0)) |-> (result == a)
    );

    // op=01 and a==b: result is zero.
    check_sub_a_eq_b_zero: assert property (
        @(posedge CLK) (op == 2'b01 && (a == b)) |-> (result == 8'd0)
    );

    // op=10 and a==0 or b==0: result is zero.
    check_mul_zero_operand: assert property (
        @(posedge CLK) (op == 2'b10 && ((a == 8'd0) || (b == 8'd0))) |-> (result == 8'd0)
    );

    // op=10 and a==1: result equals b.
    check_mul_a_one: assert property (
        @(posedge CLK) (op == 2'b10 && (a == 8'd1)) |-> (result == b)
    );

    // op=10 and b==1: result equals a.
    check_mul_b_one: assert property (
        @(posedge CLK) (op == 2'b10 && (b == 8'd1)) |-> (result == a)
    );

    // op=11 and b==1: result equals a.
    check_div_b_one: assert property (
        @(posedge CLK) (op == 2'b11 && (b == 8'd1)) |-> (result == a)
    );

    // op=11 with b!=0 and a==0: result is zero.
    check_div_a_zero: assert property (
        @(posedge CLK) (op == 2'b11 && b != 8'd0 && a == 8'd0) |-> (result == 8'd0)
    );

    // op=11 with b!=0 and a==b: result is one.
    check_div_a_eq_b_one: assert property (
        @(posedge CLK) (op == 2'b11 && b != 8'd0 && a == b) |-> (result == 8'd1)
    );

endmodule

rtl:
module full_adder (
    input A,
    input B,
    input CI,
    output SUM,
    output COUT_N
);

    wire xor0_out_SUM;
    wire a_b;
    wire a_ci;
    wire b_ci;
    wire or0_out_coutn;

    xor xor0 (xor0_out_SUM, A, B, CI);
    assign SUM = xor0_out_SUM;
    nor nor0 (a_b, A, B);
    nor nor1 (a_ci, A, CI);
    nor nor2 (b_ci, B, CI);
    or or0 (or0_out_coutn, a_b, a_ci, b_ci);
    assign COUT_N = or0_out_coutn;

endmodule

sva:
module full_adder_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic CI,
    input logic SUM,
    input logic COUT_N
);
    // SUM must equal A ^ B ^ CI.
    check_sum_is_xor: assert property (
        @(posedge clk) disable iff (1'b0) SUM == (A ^ B ^ CI)
    );

    // COUT_N must equal complement of majority (two-or-more ones).
    check_coutn_is_comp_majority: assert property (
        @(posedge clk) disable iff (1'b0) COUT_N == ~((A & B) | (A & CI) | (B & CI))
    );

    // If all inputs are stable over a cycle, outputs must be stable too.
    check_outputs_stable_when_inputs_stable: assert property (
        @(posedge clk) disable iff (1'b0) ($stable(A) && $stable(B) && $stable(CI)) |-> ($stable(SUM) && $stable(COUT_N))
    );

    // With B and CI stable, toggling A must toggle SUM.
    check_sum_toggles_on_A_toggle: assert property (
        @(posedge clk) disable iff (1'b0) ($changed(A) && $stable(B) && $stable(CI)) |-> $changed(SUM)
    );

    // With A and CI stable, toggling B must toggle SUM.
    check_sum_toggles_on_B_toggle: assert property (
        @(posedge clk) disable iff (1'b0) ($stable(A) && $changed(B) && $stable(CI)) |-> $changed(SUM)
    );

    // With A and B stable, toggling CI must toggle SUM.
    check_sum_toggles_on_CI_toggle: assert property (
        @(posedge clk) disable iff (1'b0) ($stable(A) && $stable(B) && $changed(CI)) |-> $changed(SUM)
    );

    // Truth table: 000 -> SUM=0, COUT_N=1.
    truth_000: assert property (
        @(posedge clk) disable iff (1'b0) (A==1'b0 && B==1'b0 && CI==1'b0) |-> (SUM==1'b0 && COUT_N==1'b1)
    );

    // Truth table: 001 -> SUM=1, COUT_N=1.
    truth_001: assert property (
        @(posedge clk) disable iff (1'b0) (A==1'b0 && B==1'b0 && CI==1'b1) |-> (SUM==1'b1 && COUT_N==1'b1)
    );

    // Truth table: 011 -> SUM=0, COUT_N=0.
    truth_011: assert property (
        @(posedge clk) disable iff (1'b0) (A==1'b0 && B==1'b1 && CI==1'b1) |-> (SUM==1'b0 && COUT_N==1'b0)
    );

    // Truth table: 111 -> SUM=1, COUT_N=0.
    truth_111: assert property (
        @(posedge clk) disable iff (1'b0) (A==1'b1 && B==1'b1 && CI==1'b1) |-> (SUM==1'b1 && COUT_N==1'b0)
    );
endmodule

rtl:
module fifo (
   // Outputs
   out0, out1,
   // Inputs
   clk, wr0a, wr0b, wr1a, wr1b, inData
);

   input         clk;
   input         wr0a;
   input         wr0b;
   input         wr1a;
   input         wr1b;
   input [15:0]  inData;

   output [15:0] out0;
   output [15:0] out1;

   reg [15:0]    mem [1:0];


   assign        out0 = mem[0];
   assign        out1 = mem[1];

   always @(posedge clk) begin
      // These mem assignments must be done in order after processing
      if (wr0a) begin
         mem[0] <=  inData;
      end
      if (wr0b) begin
         mem[0] <= ~inData;
      end
      if (wr1a) begin
         mem[1] <=  inData;
      end
      if (wr1b) begin
         mem[1] <= ~inData;
      end
   end

endmodule

sva:
module fifo_sva (
    input  logic        clk,
    input  logic        wr0a,
    input  logic        wr0b,
    input  logic        wr1a,
    input  logic        wr1b,
    input  logic [15:0] inData,
    input  logic [15:0] out0,
    input  logic [15:0] out1
);

    // wr0b causes out0 to take ~inData on the next cycle (B overrides A).
    property p_update_out0_on_wr0b;
        logic [15:0] din;
        @(posedge clk) (wr0b, din = inData) |=> (out0 == ~din);
    endproperty
    update_out0_on_wr0b: assert property (p_update_out0_on_wr0b);

    // wr0a without wr0b causes out0 to take inData on the next cycle.
    property p_update_out0_on_wr0a_only;
        logic [15:0] din;
        @(posedge clk) ((wr0a && !wr0b), din = inData) |=> (out0 == din);
    endproperty
    update_out0_on_wr0a_only: assert property (p_update_out0_on_wr0a_only);

    // If no write to mem[0], out0 holds its value on the next cycle.
    property p_hold_out0_when_no_write;
        logic [15:0] o;
        @(posedge clk) ((!wr0a && !wr0b), o = out0) |=> (out0 == o);
    endproperty
    hold_out0_when_no_write: assert property (p_hold_out0_when_no_write);

    // wr1b causes out1 to take ~inData on the next cycle (B overrides A).
    property p_update_out1_on_wr1b;
        logic [15:0] din;
        @(posedge clk) (wr1b, din = inData) |=> (out1 == ~din);
    endproperty
    update_out1_on_wr1b: assert property (p_update_out1_on_wr1b);

    // wr1a without wr1b causes out1 to take inData on the next cycle.
    property p_update_out1_on_wr1a_only;
        logic [15:0] din;
        @(posedge clk) ((wr1a && !wr1b), din = inData) |=> (out1 == din);
    endproperty
    update_out1_on_wr1a_only: assert property (p_update_out1_on_wr1a_only);

    // If no write to mem[1], out1 holds its value on the next cycle.
    property p_hold_out1_when_no_write;
        logic [15:0] o;
        @(posedge clk) ((!wr1a && !wr1b), o = out1) |=> (out1 == o);
    endproperty
    hold_out1_when_no_write: assert property (p_hold_out1_when_no_write);

    // When both wr0a and wr0b are asserted, out0 takes ~inData (B priority).
    property p_out0_priority_b_over_a;
        logic [15:0] din;
        @(posedge clk) ((wr0a && wr0b), din = inData) |=> (out0 == ~din);
    endproperty
    out0_priority_b_over_a: assert property (p_out0_priority_b_over_a);

    // When both wr1a and wr1b are asserted, out1 takes ~inData (B priority).
    property p_out1_priority_b_over_a;
        logic [15:0] din;
        @(posedge clk) ((wr1a && wr1b), din = inData) |=> (out1 == ~din);
    endproperty
    out1_priority_b_over_a: assert property (p_out1_priority_b_over_a);

    // Simultaneous wr0a-only and wr1a-only cause both out0/out1 to take inData.
    property p_both_a_only_updates_both_to_inData;
        logic [15:0] din;
        @(posedge clk) ((wr0a && !wr0b && wr1a && !wr1b), din = inData) |=> ((out0 == din) && (out1 == din));
    endproperty
    both_a_only_updates_both_to_inData: assert property (p_both_a_only_updates_both_to_inData);

    // Simultaneous wr0b and wr1b cause both out0/out1 to take ~inData.
    property p_both_b_updates_both_to_not_inData;
        logic [15:0] din;
        @(posedge clk) ((wr0b && wr1b), din = inData) |=> ((out0 == ~din) && (out1 == ~din));
    endproperty
    both_b_updates_both_to_not_inData: assert property (p_both_b_updates_both_to_not_inData);

    // Mixed: wr0b with wr1a-only updates out0 to ~inData and out1 to inData.
    property p_mixed_wr0b_wr1a_only;
        logic [15:0] din;
        @(posedge clk) ((wr0b && wr1a && !wr1b), din = inData) |=> ((out0 == ~din) && (out1 == din));
    endproperty
    mixed_wr0b_wr1a_only: assert property (p_mixed_wr0b_wr1a_only);

    // Mixed: wr0a-only with wr1b updates out0 to inData and out1 to ~inData.
    property p_mixed_wr0a_only_wr1b;
        logic [15:0] din;
        @(posedge clk) ((wr0a && !wr0b && wr1b), din = inData) |=> ((out0 == din) && (out1 == ~din));
    endproperty
    mixed_wr0a_only_wr1b: assert property (p_mixed_wr0a_only_wr1b);

endmodule

rtl:
module binary_to_bcd_converter (
    input [2:0] binary_in,
    output reg [3:0] bcd_out
);

always @(*) begin
    case (binary_in)
        3'b000: bcd_out = 4'b0000;
        3'b001: bcd_out = 4'b0001;
        3'b010: bcd_out = 4'b0010;
        3'b011: bcd_out = 4'b0011;
        3'b100: bcd_out = 4'b0100;
        3'b101: bcd_out = 4'b0101;
        3'b110: bcd_out = 4'b0110;
        3'b111: bcd_out = 4'b0111;
    endcase;
end

endmodule

module priority_multiplexer (
    input [3:0] in0,
    input [7:0] in1,
    input P,
    output reg [7:0] out
);

always @(*) begin
    if (P) begin
        out = in1;
    end else begin
        out = in0;
    end
end

endmodule

module bcd_adder (
    input [3:0] bcd_in,
    input [7:0] c_in,
    input clk,
    input reset,       // Synchronous active-high reset
    output reg [7:0] q
);

always @(posedge clk or negedge reset) begin
    if (!reset) begin
        q <= 8'b00000000;
    end else begin
        q <= bcd_in + c_in;
    end
end

endmodule

module top_module (
    input clk,
    input reset,       // Synchronous active-high reset
    input [2:0] D,     // 3-bit binary input for the binary-to-BCD converter
    input S,           // Select input for choosing between BCD digits and C
    input P,           // Priority input for choosing C over BCD digits
    input [7:0] C,     // Input for the priority multiplexer
    output [7:0] q     // 8-bit output from the functional module
);

wire [3:0] bcd_out;
wire [7:0] c_out;
binary_to_bcd_converter bcd_converter(.binary_in(D), .bcd_out(bcd_out));
priority_multiplexer priority_mux(.in0(bcd_out), .in1(C), .P(P), .out(c_out));
bcd_adder adder(.bcd_in(bcd_out), .c_in(c_out), .clk(clk), .reset(reset), .q(q));

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic reset,        // Active-low asynchronous in RTL (negedge sensitive), asserted low
    input logic [2:0] D,
    input logic S,            // Unused in RTL
    input logic P,
    input logic [7:0] C,
    input logic [7:0] q,
    input logic [3:0] bcd_out,
    input logic [7:0] c_out
);
    ///// Binary-to-BCD converter checks /////
    // bcd_out must be zero-extended D.
    check_bcd_zero_extend: assert property (
        @(posedge clk) disable iff (!reset) bcd_out == {1'b0, D}
    );
    // bcd_out MSB is always 0 (range 0..7).
    check_bcd_msb_zero: assert property (
        @(posedge clk) disable iff (!reset) bcd_out[3] == 1'b0
    );

    ///// Priority multiplexer checks /////
    // When P is 1, c_out equals C.
    check_mux_priority_high_routes_C: assert property (
        @(posedge clk) disable iff (!reset) P |-> (c_out == C)
    );
    // When P is 0, c_out equals zero-extended bcd_out.
    check_mux_priority_low_routes_bcd: assert property (
        @(posedge clk) disable iff (!reset) !P |-> (c_out == {4'b0000, bcd_out})
    );
    // When P is 0, upper nibble of c_out is 0.
    check_mux_priority_low_upper_zero: assert property (
        @(posedge clk) disable iff (!reset) !P |-> (c_out[7:4] == 4'b0000)
    );
    // When P is 0, lower nibble of c_out equals bcd_out.
    check_mux_priority_low_lower_matches_bcd: assert property (
        @(posedge clk) disable iff (!reset) !P |-> (c_out[3:0] == bcd_out)
    );

    ///// BCD adder (sequential) checks /////
    // While reset is asserted low at clock edge, q is 0.
    check_reset_clears_q: assert property (
        @(posedge clk) (!reset) |-> (q == 8'h00)
    );
    // With reset high in consecutive cycles, q updates to previous-cycle sum.
    check_q_updates_with_sum: assert property (
        @(posedge clk) disable iff (!reset) $past(reset) |-> (q == $past(bcd_out + c_out))
    );
    // If previous cycle had P=1 (and reset high), q equals previous C + bcd_out.
    check_q_update_when_prev_priority_high: assert property (
        @(posedge clk) disable iff (!reset) ($past(reset) && $past(P)) |-> (q == $past(C + bcd_out))
    );
    // If previous cycle had P=0 (and reset high), q equals previous zero-extended bcd_out + bcd_out.
    check_q_update_when_prev_priority_low: assert property (
        @(posedge clk) disable iff (!reset) ($past(reset) && !$past(P)) |-> (q == $past({4'b0000, bcd_out} + bcd_out))
    );
endmodule

rtl:
module mig_7series_v2_3_poc_edge_store #
  (parameter TCQ                        = 100,
   parameter TAPCNTRWIDTH               = 7,
   parameter TAPSPERKCLK                = 112)
  (
  fall_lead, fall_trail, rise_lead, rise_trail,
  clk, run_polarity, run_end, select0, select1, tap, run
  );

  input clk;

  input run_polarity;
  input run_end;
  input select0;
  input select1;
  input [TAPCNTRWIDTH-1:0] tap;
  input [TAPCNTRWIDTH-1:0] run;

  wire [TAPCNTRWIDTH:0] trailing_edge = run > tap ? tap + TAPSPERKCLK[TAPCNTRWIDTH-1:0] - run
                                                  : tap - run;

  wire run_end_this = run_end && select0 && select1;

  reg [TAPCNTRWIDTH-1:0] fall_lead_r, fall_trail_r, rise_lead_r, rise_trail_r;
  output [TAPCNTRWIDTH-1:0] fall_lead, fall_trail, rise_lead, rise_trail;
  assign fall_lead = fall_lead_r;
  assign fall_trail = fall_trail_r;
  assign rise_lead = rise_lead_r;
  assign rise_trail = rise_trail_r;

  wire [TAPCNTRWIDTH-1:0] fall_lead_ns = run_end_this & run_polarity ? tap : fall_lead_r;
  wire [TAPCNTRWIDTH-1:0] rise_trail_ns = run_end_this & run_polarity ? trailing_edge[TAPCNTRWIDTH-1:0]
                                                                      : rise_trail_r;
  wire [TAPCNTRWIDTH-1:0] rise_lead_ns = run_end_this & ~run_polarity ? tap : rise_lead_r;
  wire [TAPCNTRWIDTH-1:0] fall_trail_ns = run_end_this & ~run_polarity ? trailing_edge[TAPCNTRWIDTH-1:0]
                                                                       : fall_trail_r;

  always @(posedge clk) fall_lead_r <= #TCQ fall_lead_ns;
  always @(posedge clk) fall_trail_r <= #TCQ fall_trail_ns;
  always @(posedge clk) rise_lead_r <= #TCQ rise_lead_ns;
  always @(posedge clk) rise_trail_r <= #TCQ rise_trail_ns;

endmodule

sva:
module mig_7series_v2_3_poc_edge_store_sva #(
    parameter int TCQ = 100,
    parameter int TAPCNTRWIDTH = 7,
    parameter int TAPSPERKCLK = 112
) (
    input  logic                         clk,
    input  logic                         run_polarity,
    input  logic                         run_end,
    input  logic                         select0,
    input  logic                         select1,
    input  logic [TAPCNTRWIDTH-1:0]      tap,
    input  logic [TAPCNTRWIDTH-1:0]      run,
    input  logic [TAPCNTRWIDTH-1:0]      fall_lead,
    input  logic [TAPCNTRWIDTH-1:0]      fall_trail,
    input  logic [TAPCNTRWIDTH-1:0]      rise_lead,
    input  logic [TAPCNTRWIDTH-1:0]      rise_trail
);

    // Low TAPSPERKCLK bits used by RTL in trailing_edge calc
    localparam logic [TAPCNTRWIDTH-1:0] TAPSPERKCLK_LSBS = TAPSPERKCLK[TAPCNTRWIDTH-1:0];

    // Helper to match RTL trailing_edge[TAPCNTRWIDTH-1:0]
    function automatic logic [TAPCNTRWIDTH-1:0] calc_te(
        input logic [TAPCNTRWIDTH-1:0] tap_i,
        input logic [TAPCNTRWIDTH-1:0] run_i
    );
        calc_te = (run_i > tap_i) ? (tap_i + TAPSPERKCLK_LSBS - run_i)
                                  : (tap_i - run_i);
    endfunction

    ///// Update on run_end with run_polarity == 1 /////
    // When run_end_this and run_polarity=1, fall_lead loads tap on next cycle.
    update_fall_lead_pospol: assert property (
        @(posedge clk) (run_end && select0 && select1 && run_polarity) |=> (fall_lead == $past(tap))
    );

    // When run_end_this and run_polarity=1, rise_trail loads trailing_edge LSBs on next cycle.
    update_rise_trail_pospol: assert property (
        @(posedge clk) (run_end && select0 && select1 && run_polarity) |=> (rise_trail == calc_te($past(tap), $past(run)))
    );

    // When run_end_this and run_polarity=1, rise_lead and fall_trail hold their previous values.
    hold_unaffected_pospol: assert property (
        @(posedge clk) (run_end && select0 && select1 && run_polarity) |=> (rise_lead == $past(rise_lead)) && (fall_trail == $past(fall_trail))
    );

    ///// Update on run_end with run_polarity == 0 /////
    // When run_end_this and run_polarity=0, rise_lead loads tap on next cycle.
    update_rise_lead_negpol: assert property (
        @(posedge clk) (run_end && select0 && select1 && ~run_polarity) |=> (rise_lead == $past(tap))
    );

    // When run_end_this and run_polarity=0, fall_trail loads trailing_edge LSBs on next cycle.
    update_fall_trail_negpol: assert property (
        @(posedge clk) (run_end && select0 && select1 && ~run_polarity) |=> (fall_trail == calc_te($past(tap), $past(run)))
    );

    // When run_end_this and run_polarity=0, fall_lead and rise_trail hold their previous values.
    hold_unaffected_negpol: assert property (
        @(posedge clk) (run_end && select0 && select1 && ~run_polarity) |=> (fall_lead == $past(fall_lead)) && (rise_trail == $past(rise_trail))
    );

    ///// Gating when run_end_this is false /////
    // If run_end_this is false, all outputs hold their values on next cycle.
    hold_when_no_update: assert property (
        @(posedge clk) !(run_end && select0 && select1) |=> (fall_lead == $past(fall_lead)) && (fall_trail == $past(fall_trail)) &&
                                                           (rise_lead == $past(rise_lead)) && (rise_trail == $past(rise_trail))
    );

endmodule

module counter_sva (
    input logic Clk,
    input logic Reset,     // Active-high synchronous reset
    input logic Enable,
    input logic [3:0] Q
);
    ///// Counter behavior (sequential, posedge Clk) /////
    // On reset, Q is driven to 0 in the same cycle.
    reset_forces_zero: assert property (
        @(posedge Clk) Reset |-> (Q == 4'h0)
    );

    // Reset has priority over Enable.
    reset_priority_over_enable: assert property (
        @(posedge Clk) Reset && Enable |-> (Q == 4'h0)
    );

    // When not in reset and Enable is LOW, Q holds its value.
    hold_when_disabled: assert property (
        @(posedge Clk) disable iff (Reset) (!Enable) |-> (Q == $past(Q))
    );

    // When not in reset and Enable is HIGH, Q increments by 1 (mod 16).
    increment_when_enabled: assert property (
        @(posedge Clk) disable iff (Reset) (Enable) |-> (Q == ($past(Q) + 4'd1))
    );

    // When not in reset, if previous Q was 0xF and Enable is HIGH, Q wraps to 0.
    wrap_on_max: assert property (
        @(posedge Clk) disable iff (Reset) (Enable && ($past(Q) == 4'hF)) |-> (Q == 4'h0)
    );

    // With Enable HIGH for two consecutive cycles (and previous cycle not in reset), Q advances by 2.
    two_cycle_increment: assert property (
        @(posedge Clk) disable iff (Reset) (Enable && $past(Enable) && !$past(Reset)) |-> (Q == ($past(Q,2) + 4'd2))
    );

    // With Enable LOW for two consecutive cycles (and previous cycle not in reset), Q holds over two cycles.
    two_cycle_hold: assert property (
        @(posedge Clk) disable iff (Reset) (!Enable && !$past(Enable) && !$past(Reset)) |-> (Q == $past(Q,2))
    );

    // While reset is held across cycles, Q remains 0.
    reset_held_keeps_zero: assert property (
        @(posedge Clk) (Reset && $past(Reset)) |-> (Q == 4'h0 && $past(Q) == 4'h0)
    );
endmodule

rtl:
module gray_code_converter(
    input [15:0] binary_input,
    output [15:0] gray_code_output
);

