rtl:
module dut(
  input wire clk,
  input wire reset,
  input wire [15:0] input_signal,
  output reg [3:0] output_signal
);

reg [3:0] count;

always @(posedge clk) begin
  if (reset) begin
    count <= 0;
  end else begin
    if (input_signal == 16'b1111_1111_1111_1111 || input_signal == 16'b0000_0000_0000_0000) begin
      count <= 0;
    end else if (input_signal[15] == 1) begin
      count <= 1;
    end else begin
      count <= count + 1;
    end
  end
end

always @(posedge clk) begin
  if (reset) begin
    output_signal <= 0;
  end else if (input_signal == 16'b1111_1111_1111_1111 || input_signal == 16'b0000_0000_0000_0000) begin
    output_signal <= 0;
  end else if (input_signal[15] == 1) begin
    output_signal <= count;
  end
end

endmodule

sva:
module dut_sva (
    input logic clk,
    input logic reset,
    input logic [15:0] input_signal,
    input logic [3:0] output_signal,
    input logic [3:0] count
);
    // Synchronous reset drives count and output_signal to 0 in the next cycle.
    check_reset_clears_both: assert property (
        @(posedge clk) reset |=> (count == 4'd0) && (output_signal == 4'd0)
    );

    // All-zeros or all-ones input drives both count and output to 0 next cycle.
    check_sentinel_clears_both: assert property (
        @(posedge clk) disable iff (reset)
            ((input_signal == 16'hFFFF) || (input_signal == 16'h0000)) |=> (count == 4'd0) && (output_signal == 4'd0)
    );

    // With MSB=1 (and not sentinel), count becomes 1 next cycle.
    check_msb1_sets_count_one: assert property (
        @(posedge clk) disable iff (reset)
            (!((input_signal == 16'hFFFF) || (input_signal == 16'h0000)) && (input_signal[15] == 1'b1)) |=> (count == 4'd1)
    );

    // With MSB=1 (and not sentinel), output becomes previous count next cycle.
    check_msb1_updates_output_prev_count: assert property (
        @(posedge clk) disable iff (reset)
            (!((input_signal == 16'hFFFF) || (input_signal == 16'h0000)) && (input_signal[15] == 1'b1) && $past(!reset)) |=> (output_signal == $past(count))
    );

    // With MSB=0 (and not sentinel), count increments by 1 modulo 16 next cycle.
    check_msb0_increments_count: assert property (
        @(posedge clk) disable iff (reset)
            (!((input_signal == 16'hFFFF) || (input_signal == 16'h0000)) && (input_signal[15] == 1'b0) && $past(!reset)) |=> (count == (($past(count) == 4'hF) ? 4'h0 : ($past(count) + 4'd1)))
    );

    // With MSB=0 (and not sentinel), output holds its previous value next cycle.
    check_msb0_holds_output: assert property (
        @(posedge clk) disable iff (reset)
            (!((input_signal == 16'hFFFF) || (input_signal == 16'h0000)) && (input_signal[15] == 1'b0) && $past(!reset)) |=> (output_signal == $past(output_signal))
    );

    // Output can change only if prior cycle was reset, sentinel, or MSB=1.
    check_output_changes_only_when_driven: assert property (
        @(posedge clk) disable iff (reset)
            $changed(output_signal) |-> ($past(reset) || $past((input_signal == 16'hFFFF) || (input_signal == 16'h0000) || (input_signal[15] == 1'b1)))
    );

    // Count wraps from 15 to 0 when incrementing under MSB=0.
    check_increment_wraps_at_15: assert property (
        @(posedge clk) disable iff (reset)
            (!((input_signal == 16'hFFFF) || (input_signal == 16'h0000)) && (input_signal[15] == 1'b0) && $past(!reset) && ($past(count) == 4'hF)) |=> (count == 4'h0)
    );
endmodule

module decoder_3to8_case_sva (
    input logic A,
    input logic B,
    input logic C,
    input logic [7:0] Y
);
    ///// Functional decoding checks /////
    // Y must equal 1 << {A,B,C} for any change on A/B/C.
    check_decode_shift_equivalence: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C or negedge C)
        disable iff (1'b0)
        Y == (8'b00000001 << {A,B,C})
    );

    // Output must be one-hot for any change on A/B/C.
    check_onehot_output: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C or negedge C)
        disable iff (1'b0)
        $onehot(Y)
    );

    // When ABC=000, Y must be 00000001.
    check_decode_000: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C or negedge C)
        disable iff (1'b0)
        ({A,B,C} == 3'b000) |-> (Y == 8'b00000001)
    );

    // When ABC=001, Y must be 00000010.
    check_decode_001: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C or negedge C)
        disable iff (1'b0)
        ({A,B,C} == 3'b001) |-> (Y == 8'b00000010)
    );

    // When ABC=010, Y must be 00000100.
    check_decode_010: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C or negedge C)
        disable iff (1'b0)
        ({A,B,C} == 3'b010) |-> (Y == 8'b00000100)
    );

    // When ABC=011, Y must be 00001000.
    check_decode_011: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C or negedge C)
        disable iff (1'b0)
        ({A,B,C} == 3'b011) |-> (Y == 8'b00001000)
    );

    // When ABC=100, Y must be 00010000.
    check_decode_100: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C or negedge C)
        disable iff (1'b0)
        ({A,B,C} == 3'b100) |-> (Y == 8'b00010000)
    );

    // When ABC=101, Y must be 00100000.
    check_decode_101: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C or negedge C)
        disable iff (1'b0)
        ({A,B,C} == 3'b101) |-> (Y == 8'b00100000)
    );

    // When ABC=110, Y must be 01000000.
    check_decode_110: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C or negedge C)
        disable iff (1'b0)
        ({A,B,C} == 3'b110) |-> (Y == 8'b01000000)
    );

    // When ABC=111, Y must be 10000000.
    check_decode_111: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C or negedge C)
        disable iff (1'b0)
        ({A,B,C} == 3'b111) |-> (Y == 8'b10000000)
    );
endmodule

