module counter #(
  parameter WIDTH = 16
)(
  input clk,
  input reset,
  input enable,
  output reg [WIDTH-1:0] count
);


always @(posedge clk) begin
  if (reset) begin
    count <= 0;
  end else if (enable) begin
    count <= count + 1;
  end
end

endmodule

sva:
module counter_sva #(
  parameter WIDTH = 16
) (
  input  logic                 clk,
  input  logic                 reset,   // active-high synchronous reset
  input  logic                 enable,
