sva:
module sky130_fd_sc_ms__or2b_sva (
    input logic clk,
    input logic X,
    input logic A,
    input logic B_N
);
    // X equals A OR NOT B_N.
    check_function_equivalence: assert property (
        @(posedge clk) X == (A | ~B_N)
    );

    // If A is 1, X must be 1.
    check_a_high_forces_x_high: assert property (
        @(posedge clk) A |-> X
    );

    // If B_N is 0, X must be 1.
    check_bn_low_forces_x_high: assert property (
        @(posedge clk) (~B_N) |-> X
    );

    // If A is 0 and B_N is 1, X must be 0.
    check_a0_bn1_forces_x0: assert property (
        @(posedge clk) (!A && B_N) |-> (!X)
    );

    // X is 0 only when A is 0 and B_N is 1.
    check_x0_only_when_a0_bn1: assert property (
        @(posedge clk) (!X) |-> (!A && B_N)
    );

    // Truth-table corner: A=0, B_N=0 => X=1.
    check_tt_a0_bn0_x1: assert property (
        @(posedge clk) (!A && !B_N) |-> X
    );

    // Truth-table corner: A=1, B_N=0 => X=1.
    check_tt_a1_bn0_x1: assert property (
        @(posedge clk) (A && !B_N) |-> X
    );

    // Truth-table corner: A=1, B_N=1 => X=1.
    check_tt_a1_bn1_x1: assert property (
        @(posedge clk) (A && B_N) |-> X
    );

    // Truth-table corner: A=0, B_N=1 => X=0.
    check_tt_a0_bn1_x0: assert property (
        @(posedge clk) (!A && B_N) |-> (!X)
    );
endmodule

rtl:
module four_bit_adder(
  input [3:0] A,
  input [3:0] B,
  output [3:0] S,
  output C
);

  wire [3:0] sum;
  wire C1, C2, C3; // Intermediate carry signals

  // Full adder for least significant bit
  full_adder fa0(
    .a(A[0]),
    .b(B[0]),
    .c_in(1'b0),
    .sum(sum[0]),
    .c_out(C1)
  );

  // Full adder for second least significant bit
  full_adder fa1(
    .a(A[1]),
    .b(B[1]),
    .c_in(C1),
    .sum(sum[1]),
    .c_out(C2)
  );

  // Full adder for third least significant bit
  full_adder fa2(
    .a(A[2]),
    .b(B[2]),
    .c_in(C2),
    .sum(sum[2]),
    .c_out(C3)
  );

  // Full adder for most significant bit
  full_adder fa3(
    .a(A[3]),
    .b(B[3]),
    .c_in(C3),
    .sum(sum[3]),
    .c_out(C)
  );

  assign S = sum;

endmodule
module full_adder(
  input a,
  input b,
  input c_in,
  output sum,
  output c_out
);

  assign sum = a ^ b ^ c_in;
  assign c_out = (a & b) | (a & c_in) | (b & c_in);

endmodule

sva:
module four_bit_adder_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] S,
    input logic C
);
    // Local recompute of ripple-carry chain from A and B
    logic c1, c2, c3;
    logic [4:0] exp_sum5;

    assign c1 = A[0] & B[0];
    assign c2 = (A[1] & B[1]) | (A[1] & c1) | (B[1] & c1);
    assign c3 = (A[2] & B[2]) | (A[2] & c2) | (B[2] & c2);
    assign exp_sum5 = {1'b0, A} + {1'b0, B};

    // The 5-bit result {C,S} equals A+B with zero carry-in.
    check_vector_sum_matches_add: assert property (
        @(posedge clk) disable iff (1'b0) ({C, S} == exp_sum5)
    );

    // LSB sum is XOR of A[0] and B[0] (c_in=0).
    check_sum_bit0_xor: assert property (
        @(posedge clk) disable iff (1'b0) (S[0] == (A[0] ^ B[0]))
    );

    // Bit1 sum equals XOR of A[1], B[1], and c1.
    check_sum_bit1_xor_with_c1: assert property (
        @(posedge clk) disable iff (1'b0) (S[1] == (A[1] ^ B[1] ^ c1))
    );

    // Bit2 sum equals XOR of A[2], B[2], and c2.
    check_sum_bit2_xor_with_c2: assert property (
        @(posedge clk) disable iff (1'b0) (S[2] == (A[2] ^ B[2] ^ c2))
    );

    // Bit3 sum equals XOR of A[3], B[3], and c3.
    check_sum_bit3_xor_with_c3: assert property (
        @(posedge clk) disable iff (1'b0) (S[3] == (A[3] ^ B[3] ^ c3))
    );

    // Final carry-out equals majority of A[3], B[3], and c3.
    check_carryout_majority: assert property (
        @(posedge clk) disable iff (1'b0) (C == ((A[3] & B[3]) | (A[3] & c3) | (B[3] & c3)))
    );

    // Carry-out equals MSB of the 5-bit sum.
    check_carryout_equals_sum_msb: assert property (
        @(posedge clk) disable iff (1'b0) (C == exp_sum5[4])
    );

    // Sum lower 4 bits equal lower 4 bits of A+B.
    check_sum_lower4_equals_add: assert property (
        @(posedge clk) disable iff (1'b0) (S == exp_sum5[3:0])
    );

    // Adding zero on A yields S=B and C=0.
    check_add_zero_on_A: assert property (
        @(posedge clk) disable iff (1'b0) ((A == 4'b0000) |-> (S == B) && (C == 1'b0))
    );

    // Adding zero on B yields S=A and C=0.
    check_add_zero_on_B: assert property (
        @(posedge clk) disable iff (1'b0) ((B == 4'b0000) |-> (S == A) && (C == 1'b0))
    );

    // If no bit position has both A and B set, result is XOR and no carry.
    check_no_overlap_bits_implies_xor: assert property (
        @(posedge clk) disable iff (1'b0) (((A & B) == 4'b0000) |-> (S == (A ^ B)) && (C == 1'b0))
    );

endmodule

rtl:
module strobe_gen 
  ( input clock,
    input reset,
    input enable,
    input [7:0] rate, input strobe_in,
    output wire strobe );

reg [7:0] counter;
   assign strobe = ~|counter && enable && strobe_in;

   always @(posedge clock)
     if(reset | ~enable)
       counter <= #1 8'd0;
     else if(strobe_in)
       if(counter == 0)
	 counter <= #1 rate;
       else 
	 counter <= #1 counter - 8'd1;

endmodule

sva:
module strobe_gen_sva (
    input logic clock,
    input logic reset,
    input logic enable,
    input logic [7:0] rate,
    input logic strobe_in,
    input logic strobe,
    input logic [7:0] counter
);
    ///// Combinational strobe definition /////
    // strobe equals (counter==0) && enable && strobe_in.
    check_strobe_definition: assert property (
        @(posedge clock) (strobe == ((counter == 8'd0) && enable && strobe_in))
    );

    // strobe HIGH requires enable and strobe_in HIGH.
    strobe_requires_inputs: assert property (
        @(posedge clock) strobe |-> (enable && strobe_in)
    );

    // enable LOW forces strobe LOW.
    enable_low_forces_strobe_low: assert property (
        @(posedge clock) (!enable) |-> (strobe == 1'b0)
    );

    // strobe_in LOW forces strobe LOW.
    strobe_in_low_forces_strobe_low: assert property (
        @(posedge clock) (!strobe_in) |-> (strobe == 1'b0)
    );

    // strobe HIGH implies counter is zero.
    strobe_implies_counter_zero: assert property (
        @(posedge clock) strobe |-> (counter == 8'd0)
    );

    // When counter is zero and inputs are HIGH, strobe is HIGH.
    zero_counter_inputs_high_implies_strobe: assert property (
        @(posedge clock) (enable && strobe_in && (counter == 8'd0)) |-> strobe
    );

    ///// Counter update behavior /////
    // On reset, counter clears to zero on next cycle.
    counter_clears_on_reset: assert property (
        @(posedge clock) reset |=> (counter == 8'd0)
    );

    // When enable is LOW, counter clears to zero on next cycle.
    counter_clears_when_disabled: assert property (
        @(posedge clock) (!reset && !enable) |=> (counter == 8'd0)
    );

    // With enable HIGH and strobe_in LOW, counter holds its value.
    counter_holds_when_strobe_in_low: assert property (
        @(posedge clock) disable iff (reset) (enable && !strobe_in) |=> (counter == $past(counter))
    );

    // With enable and strobe_in HIGH and counter non-zero, counter decrements by one.
    counter_decrements_when_nonzero: assert property (
        @(posedge clock) disable iff (reset) (enable && strobe_in && (counter != 8'd0)) |=> (counter == $past(counter) - 8'd1)
    );

    // With enable and strobe_in HIGH and counter zero, counter loads rate.
    counter_loads_rate_when_zero: assert property (
        @(posedge clock) disable iff (reset) (enable && strobe_in && (counter == 8'd0)) |=> (counter == rate)
    );

    // When strobe is HIGH, counter loads rate on next cycle.
    strobe_implies_load_rate_next: assert property (
        @(posedge clock) disable iff (reset) strobe |=> (counter == rate)
    );
endmodule

rtl:
module magnitude_comparator (
    input valid,
    input [3:0] A,
    input [3:0] B,
    input [1:0] sel,
    output [1:0] out_mode0,
    output less_than,
    output equal_to,
    output greater_than
);

    reg [1:0] magnitude;
    reg less_than_reg, equal_to_reg, greater_than_reg;

    always @(*) begin
        if (A == B) begin
            magnitude = 2'b00;
            less_than_reg = 1'b0;
            equal_to_reg = 1'b1;
            greater_than_reg = 1'b0;
        end else if (A > B) begin
            magnitude = 2'b01;
            less_than_reg = 1'b0;
            equal_to_reg = 1'b0;
            greater_than_reg = 1'b1;
        end else begin
            magnitude = 2'b10;
            less_than_reg = 1'b1;
            equal_to_reg = 1'b0;
            greater_than_reg = 1'b0;
        end
    end

    assign out_mode0 = (sel == 2'b00) ? magnitude : 2'b00;
    assign less_than = (sel == 2'b01) ? less_than_reg : 1'b0;
    assign equal_to = (sel == 2'b01) ? equal_to_reg : 1'b0;
    assign greater_than = (sel == 2'b01) ? greater_than_reg : 1'b0;

endmodule

sva:
module magnitude_comparator_sva (
    input logic        valid,
    input logic [3:0]  A,
    input logic [3:0]  B,
    input logic [1:0]  sel,
    input logic [1:0]  out_mode0,
    input logic        less_than,
    input logic        equal_to,
    input logic        greater_than
);
    ///// Mode-0 (magnitude code) behavior /////
    // When sel==00, out_mode0 encodes compare result: 00 if A==B, 01 if A>B, 10 if A<B.
    check_sel00_magnitude_encoding: assert property (
        @(posedge valid) (sel == 2'b00) |-> (out_mode0 == ((A == B) ? 2'b00 : ((A > B) ? 2'b01 : 2'b10)))
    );
    // When sel!=00, out_mode0 must be 00.
    check_sel_not00_out_zero: assert property (
        @(posedge valid) (sel != 2'b00) |-> (out_mode0 == 2'b00)
    );
    // For sel==00, out_mode0[1] reflects (A<B).
    check_sel00_out_msb_is_less: assert property (
        @(posedge valid) (sel == 2'b00) |-> (out_mode0[1] == (A < B))
    );
    // For sel==00, out_mode0[0] reflects (A>B).
    check_sel00_out_lsb_is_greater: assert property (
        @(posedge valid) (sel == 2'b00) |-> (out_mode0[0] == (A > B))
    );

    ///// Mode-1 (flag outputs) behavior /////
    // When sel==01, less_than reflects (A<B).
    check_sel01_less_than_matches: assert property (
        @(posedge valid) (sel == 2'b01) |-> (less_than == (A < B))
    );
    // When sel==01, equal_to reflects (A==B).
    check_sel01_equal_to_matches: assert property (
        @(posedge valid) (sel == 2'b01) |-> (equal_to == (A == B))
    );
    // When sel==01, greater_than reflects (A>B).
    check_sel01_greater_than_matches: assert property (
        @(posedge valid) (sel == 2'b01) |-> (greater_than == (A > B))
    );
    // When sel==01, exactly one of the three flags is HIGH.
    check_sel01_onehot_result: assert property (
        @(posedge valid) (sel == 2'b01) |-> $onehot({less_than, equal_to, greater_than})
    );

    ///// Output gating when not in mode-1 /////
    // When sel!=01, less_than must be 0.
    check_sel_not01_less_zero: assert property (
        @(posedge valid) (sel != 2'b01) |-> (less_than == 1'b0)
    );
    // When sel!=01, equal_to must be 0.
    check_sel_not01_equal_zero: assert property (
        @(posedge valid) (sel != 2'b01) |-> (equal_to == 1'b0)
    );
    // When sel!=01, greater_than must be 0.
    check_sel_not01_greater_zero: assert property (
        @(posedge valid) (sel != 2'b01) |-> (greater_than == 1'b0)
    );
endmodule

module and4_module_sva (
    input logic X,
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB
);
    ///// Combinational AND truth /////
    // X equals the AND of all inputs and rails.
    check_and_function_equality: assert property (
        @(posedge A) X == (A & B & C & D & VPWR & VGND & VPB & VNB)
    );

    ///// Dominance of 0 /////
    // If any input/rail is 0, X must be 0.
    check_zero_when_any_input_zero: assert property (
        @(posedge A) ((A==1'b0) || (B==1'b0) || (C==1'b0) || (D==1'b0) ||
                      (VPWR==1'b0) || (VGND==1'b0) || (VPB==1'b0) || (VNB==1'b0))
                      |-> (X==1'b0)
    );

    ///// All-ones drives X high /////
    // If all inputs/rails are 1, X must be 1.
    check_one_when_all_inputs_one: assert property (
        @(posedge A) (A && B && C && D && VPWR && VGND && VPB && VNB) |-> (X==1'b1)
    );

    ///// High output implies all inputs high /////
    // If X is 1, then all inputs/rails are 1.
    check_one_implies_all_inputs_one: assert property (
        @(posedge A) (X==1'b1) |-> (A && B && C && D && VPWR && VGND && VPB && VNB)
    );
endmodule

rtl:
module system_axi_quad_spi_shield_0_wr_status_flags_as
   (\gic0.gc1.count_reg[0] ,
    E,
    \gic0.gc1.count_d2_reg[0] ,
    s_axi_aclk,
    out,
    p_6_in,
    ip2Bus_WrAck_core_reg_1,
    Bus_RNW_reg);
  output \gic0.gc1.count_reg[0] ;
  output [0:0]E;
  input \gic0.gc1.count_d2_reg[0] ;
  input s_axi_aclk;
  input out;
  input p_6_in;
  input ip2Bus_WrAck_core_reg_1;
  input Bus_RNW_reg;

  wire Bus_RNW_reg;
  wire [0:0]E;
  wire \gic0.gc1.count_d2_reg[0] ;
  wire ip2Bus_WrAck_core_reg_1;
  wire out;
  wire p_6_in;
  reg ram_full_fb_i;
  reg ram_full_i;
  reg ram_full_i_reg0;
  reg ram_full_i_reg1;
  reg ram_full_i_reg2;
  wire s_axi_aclk;

  assign \gic0.gc1.count_reg[0]  = ram_full_i_reg2;
  assign E = 1'b0;

   reg [255:0] ram [0:0] ; 

  always @(posedge s_axi_aclk) begin
    if (p_6_in) begin
        ram[0][ip2Bus_WrAck_core_reg_1] <= 1'b1;
    end
  end

  // Flip-flops
  always @(posedge s_axi_aclk) begin
    if (Bus_RNW_reg) begin
      ram_full_i <= out;
      ram_full_fb_i <= 1'b0;
    end
    else begin
      ram_full_fb_i <= ram_full_i;
    end
  end

  always @(posedge s_axi_aclk) begin
    ram_full_i_reg0 <= ram_full_fb_i;
    ram_full_i_reg1 <= ram_full_i_reg0;
    ram_full_i_reg2 <= ram_full_i_reg1;
  end

endmodule

sva:
module system_axi_quad_spi_shield_0_wr_status_flags_as_sva (
    input logic \gic0.gc1.count_reg[0] ,
    input logic [0:0] E,
    input logic \gic0.gc1.count_d2_reg[0] ,
    input logic s_axi_aclk,
    input logic out,
    input logic p_6_in,
    input logic ip2Bus_WrAck_core_reg_1,
    input logic Bus_RNW_reg
);
    // E is tied LOW continuously.
    check_E_constant_low: assert property (
        @(posedge s_axi_aclk) disable iff (1'b0) (E[0] == 1'b0)
    );

    // When Bus_RNW_reg is HIGH, count_reg[0] is forced to 0 four cycles later.
    check_count_zero_4_after_Bus_RNW_high: assert property (
        @(posedge s_axi_aclk) disable iff (1'b0) (Bus_RNW_reg == 1'b1) |-> ##4 (\gic0.gc1.count_reg[0]  == 1'b0)
    );

    // A rising edge on Bus_RNW_reg also clears count_reg[0] after four cycles.
    check_count_zero_4_after_Bus_RNW_rose: assert property (
        @(posedge s_axi_aclk) disable iff (1'b0) $rose(Bus_RNW_reg) |-> ##4 (\gic0.gc1.count_reg[0]  == 1'b0)
    );

    // If Bus_RNW_reg was HIGH 4 cycles ago, count_reg[0] is 0 now.
    check_count_zero_now_if_Bus_RNW_high_4ago: assert property (
        @(posedge s_axi_aclk) disable iff (1'b0) ($past(Bus_RNW_reg,4) == 1'b1) |-> (\gic0.gc1.count_reg[0]  == 1'b0)
    );

    // Two-cycle HIGH on Bus_RNW_reg maps to two-cycle 0 on count four cycles later.
    check_sustained_high_2_maps_to_two_zeros: assert property (
        @(posedge s_axi_aclk) disable iff (1'b0) (Bus_RNW_reg [*2]) |-> ##4 ((\gic0.gc1.count_reg[0]  == 1'b0) [*2])
    );

    // Four-cycle HIGH on Bus_RNW_reg maps to four-cycle 0 on count four cycles later.
    check_sustained_high_4_maps_to_four_zeros: assert property (
        @(posedge s_axi_aclk) disable iff (1'b0) (Bus_RNW_reg [*4]) |-> ##4 ((\gic0.gc1.count_reg[0]  == 1'b0) [*4])
    );
endmodule

rtl:
module ripple_adder(A, B, CIN, S, COUT);
  input [3:0] A;
  input [3:0] B;
  input CIN;
  output [3:0] S;
  output COUT;

  wire [3:0] sum;
  wire [3:0] carry;

  // first full adder
  fulladder FA0(A[0], B[0], CIN, sum[0], carry[0]);

  // second full adder
  fulladder FA1(A[1], B[1], carry[0], sum[1], carry[1]);

  // third full adder
  fulladder FA2(A[2], B[2], carry[1], sum[2], carry[2]);

  // fourth full adder
  fulladder FA3(A[3], B[3], carry[2], sum[3], COUT);

  assign S = sum;

endmodule

module fulladder (a, b, ci, s, co);
  input a, b, ci;
  output co, s;

  wire d;

  assign d = a ^ b;
  assign s = d ^ ci;
  assign co = (b & ~d) | (d & ci);
endmodule

sva:
module ripple_adder_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic CIN,
    input logic [3:0] S,
    input logic COUT
);
    // Local expected results based on the RTL's combinational logic
    logic p0, p1, p2, p3;
    logic c0, c1, c2, c3;
    logic [4:0] exp_sum5;

    assign p0 = A[0] ^ B[0];
    assign p1 = A[1] ^ B[1];
    assign p2 = A[2] ^ B[2];
    assign p3 = A[3] ^ B[3];

    assign c0 = (A[0] & B[0]) | (p0 & CIN);
    assign c1 = (A[1] & B[1]) | (p1 & c0);
    assign c2 = (A[2] & B[2]) | (p2 & c1);
    assign c3 = (A[3] & B[3]) | (p3 & c2);

    assign exp_sum5 = {1'b0, A} + {1'b0, B} + CIN;

    // Overall 5-bit sum equals A + B + CIN.
    overall_addition_correct: assert property (
        @(posedge clk) {COUT, S} == exp_sum5
    );

    // LSB sum is XOR of A[0], B[0], and CIN.
    sum_bit0_parity: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0] ^ CIN)
    );

    // Bit1 sum is XOR of A[1], B[1], and carry0.
    sum_bit1_parity_with_carry0: assert property (
        @(posedge clk) S[1] == (p1 ^ c0)
    );

    // Bit2 sum is XOR of A[2], B[2], and carry1.
    sum_bit2_parity_with_carry1: assert property (
        @(posedge clk) S[2] == (p2 ^ c1)
    );

    // Bit3 sum is XOR of A[3], B[3], and carry2.
    sum_bit3_parity_with_carry2: assert property (
        @(posedge clk) S[3] == (p3 ^ c2)
    );

    // Final carry-out equals carry3 from the ripple chain.
    cout_matches_carry3: assert property (
        @(posedge clk) COUT == c3
    );

    // With CIN=0, the result equals A + B.
    cin_zero_behavior: assert property (
        @(posedge clk) (CIN == 1'b0) |-> ({COUT, S} == ({1'b0, A} + {1'b0, B}))
    );

    // With A=0 and B=0, sum is CIN in bit0 and no carry out.
    zero_inputs_behavior: assert property (
        @(posedge clk) (A == 4'b0000 && B == 4'b0000) |-> ({COUT, S} == {1'b0, 3'b000, CIN})
    );

    // With B=0 and CIN=0, sum passes A and no carry out.
    passthrough_A_when_B_zero_no_cin: assert property (
        @(posedge clk) (B == 4'b0000 && CIN == 1'b0) |-> ({COUT, S} == {1'b0, A})
    );

    // With A=0 and CIN=0, sum passes B and no carry out.
    passthrough_B_when_A_zero_no_cin: assert property (
        @(posedge clk) (A == 4'b0000 && CIN == 1'b0) |-> ({COUT, S} == {1'b0, B})
    );

    // If inputs are stable between cycles, outputs remain stable.
    stable_inputs_imply_stable_outputs: assert property (
        @(posedge clk) ($stable(A) && $stable(B) && $stable(CIN)) |-> ($stable(S) && $stable(COUT))
    );
endmodule

rtl:
module flip_flops (
  input D, J, K, T, S, R, CLK,
  output Q_D, Q_JK, Q_T, Q_SR
);

// D flip-flop (positive edge-triggered)
reg Q_D;
always @(posedge CLK) begin
  Q_D <= D;
end

// JK flip-flop (negative edge-triggered)
reg Q_JK;
always @(negedge CLK) begin
  case({J, K})
    2'b00: Q_JK <= Q_JK;
    2'b01: Q_JK <= 0;
    2'b10: Q_JK <= 1;
    2'b11: Q_JK <= ~Q_JK;
  endcase
end

// T flip-flop (positive edge-triggered)
reg Q_T;
always @(posedge CLK) begin
  if (T) begin
    Q_T <= ~Q_T;
  end
end

// SR flip-flop (negative edge-triggered)
reg Q_SR;
always @(negedge CLK) begin
  case({S, R})
    2'b00: Q_SR <= Q_SR;
    2'b01: Q_SR <= 0;
    2'b10: Q_SR <= 1;
    2'b11: Q_SR <= 'bx; // undefined state
  endcase
end

endmodule

sva:
module flip_flops_sva (
  input logic D,
  input logic J,
  input logic K,
  input logic T,
  input logic S,
  input logic R,
  input logic CLK,
  input logic Q_D,
  input logic Q_JK,
  input logic Q_T,
  input logic Q_SR
);
  // DFF: Q_D captures D on rising edge (checked at next rising edge).
  check_dff_capture: assert property (
    @(posedge CLK) 1'b1 |=> (Q_D === $past(D))
  );

  // JKFF: J=0,K=0 -> hold previous value (checked at next falling edge).
  check_jkff_hold_00: assert property (
    @(negedge CLK) ({J,K} == 2'b00) |=> (Q_JK === $past(Q_JK))
  );
  // JKFF: J=0,K=1 -> reset to 0 (checked at next falling edge).
  check_jkff_reset_01: assert property (
    @(negedge CLK) ({J,K} == 2'b01) |=> (Q_JK == 1'b0)
  );
  // JKFF: J=1,K=0 -> set to 1 (checked at next falling edge).
  check_jkff_set_10: assert property (
    @(negedge CLK) ({J,K} == 2'b10) |=> (Q_JK == 1'b1)
  );
  // JKFF: J=1,K=1 -> toggle (checked at next falling edge).
  check_jkff_toggle_11: assert property (
    @(negedge CLK) ({J,K} == 2'b11) |=> (Q_JK === ~$past(Q_JK))
  );

  // TFF: when T=1, toggle on rising edge (checked at next rising edge).
  check_tff_toggle_when_T1: assert property (
    @(posedge CLK) (T == 1'b1) |=> (Q_T === ~$past(Q_T))
  );
  // TFF: when T=0, hold on rising edge (checked at next rising edge).
  check_tff_hold_when_T0: assert property (
    @(posedge CLK) (T == 1'b0) |=> (Q_T === $past(Q_T))
  );

  // SRFF: S=0,R=0 -> hold previous value (checked at next falling edge).
  check_srff_hold_00: assert property (
    @(negedge CLK) ({S,R} == 2'b00) |=> (Q_SR === $past(Q_SR))
  );
  // SRFF: S=0,R=1 -> reset to 0 (checked at next falling edge).
  check_srff_reset_01: assert property (
    @(negedge CLK) ({S,R} == 2'b01) |=> (Q_SR == 1'b0)
  );
  // SRFF: S=1,R=0 -> set to 1 (checked at next falling edge).
  check_srff_set_10: assert property (
    @(negedge CLK) ({S,R} == 2'b10) |=> (Q_SR == 1'b1)
  );
endmodule

module my_module_sva (
    input  logic in1,
    input  logic in2,
    input  logic in3,
    input  logic in4,
    input  logic in5,
    input  logic in6,
    input  logic in7,
    input  logic in8,
    input  logic c1,
    input  logic b1,
    input  logic a2,
    input  logic a1,
    input  logic out1
);
    ///// Combinational AND definition /////
    // out1 must equal a1 & a2 & b1 & c1 whenever any of these inputs toggle HIGH.
    check_out1_is_and: assert property (
        @(posedge a1 or posedge a2 or posedge b1 or posedge c1)
            out1 == (a1 & a2 & b1 & c1)
    );

    ///// Basic implications of AND /////
    // If all inputs are 1, out1 must be 1.
    check_all_ones_impl_out1_one: assert property (
        @(posedge a1 or posedge a2 or posedge b1 or posedge c1)
            (a1 & a2 & b1 & c1) |-> (out1 == 1'b1)
    );
    // If any input is 0, out1 must be 0.
    check_any_zero_impl_out1_zero: assert property (
        @(posedge a1 or posedge a2 or posedge b1 or posedge c1)
            ((!a1) || (!a2) || (!b1) || (!c1)) |-> (out1 == 1'b0)
    );
    // If out1 is 1, all inputs must be 1.
    check_out1_one_impl_all_ones: assert property (
        @(posedge a1 or posedge a2 or posedge b1 or posedge c1)
            (out1 == 1'b1) |-> (a1 & a2 & b1 & c1)
    );

    ///// Output transition consistency /////
    // A rising edge on out1 can only occur when all inputs are 1.
    check_out1_rise_requires_all_ones: assert property (
        @(posedge a1 or posedge a2 or posedge b1 or posedge c1)
            $rose(out1) |-> (a1 & a2 & b1 & c1)
    );
    // A falling edge on out1 implies at least one input is 0.
    check_out1_fall_requires_some_zero: assert property (
        @(posedge a1 or posedge a2 or posedge b1 or posedge c1)
            $fell(out1) |-> !(a1 & a2 & b1 & c1)
    );
    // out1 can only change if at least one of a1/a2/b1/c1 changes.
    check_out1_changes_only_with_controls: assert property (
        @(posedge a1 or posedge a2 or posedge b1 or posedge c1 or
          posedge in1 or posedge in2 or posedge in3 or posedge in4 or
          posedge in5 or posedge in6 or posedge in7 or posedge in8)
            $changed(out1) |-> !($stable(a1) && $stable(a2) && $stable(b1) && $stable(c1))
    );

    ///// Independence from unused inputs /////
    // Changes on in1..in8 alone must not affect out1 (controls stable).
    check_unused_inputs_do_not_affect_out: assert property (
        @(posedge in1 or posedge in2 or posedge in3 or posedge in4 or
          posedge in5 or posedge in6 or posedge in7 or posedge in8)
            ($stable(a1) && $stable(a2) && $stable(b1) && $stable(c1)) |-> $stable(out1)
    );
endmodule

rtl:
module carry_save_adder (
    input [3:0] a,
    input [3:0] b,
    input [3:0] c,
    output reg [3:0] s,
    output reg [3:0] c_out
);

wire [3:0] x, y, z, carry1, carry2;

assign x = a ^ b;
assign y = a & b;
assign z = x & c;
assign carry1 = y | z;
assign carry2 = (a & b) | (c & x);

always @* begin
    s = x ^ c;
    c_out = carry1 | carry2;
end

endmodule

sva:
module carry_save_adder_sva (
    input logic CLK,
    input logic [3:0] a,
    input logic [3:0] b,
    input logic [3:0] c,
    input logic [3:0] s,
    input logic [3:0] c_out
);
    // Sum is bitwise XOR of a, b, and c.
    check_sum_is_xor3: assert property (
        @(posedge CLK) disable iff (1'b0) s == (a ^ b) ^ c
    );

    // Carry-out equals (a & b) | (c & (a ^ b)).
    check_carry_function: assert property (
        @(posedge CLK) disable iff (1'b0) c_out == ((a & b) | (c & (a ^ b)))
    );

    // Carry-out equals majority function (a&b)|(a&c)|(b&c).
    check_carry_majority_equiv: assert property (
        @(posedge CLK) disable iff (1'b0) c_out == ((a & b) | (a & c) | (b & c))
    );

    // s OR c_out equals bitwise OR of inputs.
    check_sum_or_carry_matches_input_or: assert property (
        @(posedge CLK) disable iff (1'b0) (s | c_out) == (a | b | c)
    );

    // s AND c_out equals bitwise AND of all three inputs.
    check_sum_and_carry_triplet_and: assert property (
        @(posedge CLK) disable iff (1'b0) (s & c_out) == (a & b & c)
    );

    // When c is zero, sum reduces to a ^ b.
    check_sum_when_c_zero: assert property (
        @(posedge CLK) disable iff (1'b0) (c == 4'b0000) |-> (s == (a ^ b))
    );

    // When c is zero, carry reduces to a & b.
    check_carry_when_c_zero: assert property (
        @(posedge CLK) disable iff (1'b0) (c == 4'b0000) |-> (c_out == (a & b))
    );

    // When c is all ones, sum is bitwise NOT of (a ^ b).
    check_sum_when_c_ones: assert property (
        @(posedge CLK) disable iff (1'b0) (c == 4'b1111) |-> (s == ~(a ^ b))
    );

    // When c is all ones, carry is a | b.
    check_carry_when_c_ones: assert property (
        @(posedge CLK) disable iff (1'b0) (c == 4'b1111) |-> (c_out == (a | b))
    );

    // When a equals b, sum equals c.
    check_sum_when_a_eq_b: assert property (
        @(posedge CLK) disable iff (1'b0) (a == b) |-> (s == c)
    );

    // When c equals a ^ b, sum is zero.
    check_sum_when_c_eq_xor: assert property (
        @(posedge CLK) disable iff (1'b0) (c == (a ^ b)) |-> (s == 4'b0000)
    );

    // When c equals a ^ b, carry is a | b.
    check_carry_when_c_eq_xor: assert property (
        @(posedge CLK) disable iff (1'b0) (c == (a ^ b)) |-> (c_out == (a | b))
    );
endmodule

rtl:
module and_gate (
    output Y ,
    input  A1,
    input  A2,
    input  A3,
    input  A4,
    input  B1
);

    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;

    // Implementing the 4-input AND gate with an additional input signal B1
    assign Y = (A1 & A2 & A3 & A4 & B1);

endmodule

sva:
module and_gate_sva (
    input logic Y,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic A4,
    input logic B1
);
    ///// AND gate functional correctness /////
    // Y equals the AND of all inputs whenever any input or Y rises.
    check_and_function_on_edges: assert property (
        @(posedge A1 or posedge A2 or posedge A3 or posedge A4 or posedge B1 or posedge Y)
        Y == (A1 & A2 & A3 & A4 & B1)
    );

    // Y can only rise when all inputs are HIGH.
    check_y_rise_requires_all_high: assert property (
        @(posedge Y)
        (A1 && A2 && A3 && A4 && B1)
    );

    // When all inputs are HIGH, Y must be HIGH.
    check_all_high_implies_y_high: assert property (
        @(posedge A1 or posedge A2 or posedge A3 or posedge A4 or posedge B1)
        (A1 && A2 && A3 && A4 && B1) |-> (Y == 1'b1)
    );

    // If any input is LOW, Y must be LOW.
    check_any_low_implies_y_low: assert property (
        @(posedge A1 or posedge A2 or posedge A3 or posedge A4 or posedge B1 or posedge Y)
        (!(A1 && A2 && A3 && A4 && B1)) |-> (Y == 1'b0)
    );

    // If B1 is LOW, Y must be LOW (gating by B1).
    check_b1_low_forces_y_low: assert property (
        @(posedge A1 or posedge A2 or posedge A3 or posedge A4 or posedge B1 or posedge Y)
        (!B1) |-> (Y == 1'b0)
    );

    // If A1 is LOW, Y must be LOW.
    check_a1_low_forces_y_low: assert property (
        @(posedge A1 or posedge A2 or posedge A3 or posedge A4 or posedge B1 or posedge Y)
        (!A1) |-> (Y == 1'b0)
    );

    // If A2 is LOW, Y must be LOW.
    check_a2_low_forces_y_low: assert property (
        @(posedge A1 or posedge A2 or posedge A3 or posedge A4 or posedge B1 or posedge Y)
        (!A2) |-> (Y == 1'b0)
    );

    // If A3 is LOW, Y must be LOW.
    check_a3_low_forces_y_low: assert property (
        @(posedge A1 or posedge A2 or posedge A3 or posedge A4 or posedge B1 or posedge Y)
        (!A3) |-> (Y == 1'b0)
    );

    // If A4 is LOW, Y must be LOW.
    check_a4_low_forces_y_low: assert property (
        @(posedge A1 or posedge A2 or posedge A3 or posedge A4 or posedge B1 or posedge Y)
        (!A4) |-> (Y == 1'b0)
    );
endmodule

