module mux_4to1 (
  input sel1,
  input sel2,
  input d0,
  input d1,
  input d2,
  input d3,
  output reg out
);

  always @(*) begin
    case ({sel1, sel2})
      2'b00: out = d0;
      2'b01: out = d1;
      2'b10: out = d2;
      2'b11: out = d3;
    endcase
  end

endmodule

sva:
module mux_4to1_sva (
    input logic clk,
    input logic sel1,
    input logic sel2,
    input logic d0,
    input logic d1,
    input logic d2,
    input logic d3,
    input logic out
);

    ///// Functional mapping /////
    // When sel==00, out equals d0.
    check_map_sel00_to_d0: assert property (
        @(posedge clk) ({sel1, sel2} == 2'b00) |-> (out == d0)
    );
    // When sel==01, out equals d1.
    check_map_sel01_to_d1: assert property (
        @(posedge clk) ({sel1, sel2} == 2'b01) |-> (out == d1)
    );
    // When sel==10, out equals d2.
    check_map_sel10_to_d2: assert property (
        @(posedge clk) ({sel1, sel2} == 2'b10) |-> (out == d2)
    );
    // When sel==11, out equals d3.
    check_map_sel11_to_d3: assert property (
        @(posedge clk) ({sel1, sel2} == 2'b11) |-> (out == d3)
    );

    ///// Independence from unselected inputs /////
    // With sel==00 held constant and d0 stable, out is stable.
    check_stable_out_when_sel00_and_d0_stable: assert property (
        @(posedge clk) ({sel1, sel2} == 2'b00 && $stable(sel1) && $stable(sel2) && $stable(d0)) |-> $stable(out)
    );
    // With sel==01 held constant and d1 stable, out is stable.
    check_stable_out_when_sel01_and_d1_stable: assert property (
        @(posedge clk) ({sel1, sel2} == 2'b01 && $stable(sel1) && $stable(sel2) && $stable(d1)) |-> $stable(out)
    );
    // With sel==10 held constant and d2 stable, out is stable.
    check_stable_out_when_sel10_and_d2_stable: assert property (
        @(posedge clk) ({sel1, sel2} == 2'b10 && $stable(sel1) && $stable(sel2) && $stable(d2)) |-> $stable(out)
    );
    // With sel==11 held constant and d3 stable, out is stable.
    check_stable_out_when_sel11_and_d3_stable: assert property (
        @(posedge clk) ({sel1, sel2} == 2'b11 && $stable(sel1) && $stable(sel2) && $stable(d3)) |-> $stable(out)
    );

endmodule

module ring_counter_sva #(
  parameter int n = 4
) (
  input  logic             clk,
  input  logic [n-1:0]     out,
  input  logic [n-1:0]     state
);
  // Clock: clk; Reset: none. Sequential counter with special wrap/reset; combinational out from state.
  localparam logic [n-1:0] ALL_ZEROS = {n{1'b0}};
  localparam logic [n-1:0] ALL_ONES  = {n{1'b1}};

  // When state equals n, next state must be 0.
  check_state_reset_on_n: assert property (
    @(posedge clk) disable iff ($initstate)
    (state == n) |=> (state == ALL_ZEROS)
  );

  // When state equals all ones, next state wraps to 0.
  check_state_wrap_from_all_ones: assert property (
    @(posedge clk) disable iff ($initstate)
    (state == ALL_ONES) |=> (state == ALL_ZEROS)
  );

  // When state is not n, next state increments by 1 (mod 2^n).
  check_state_increments_when_not_n: assert property (
    @(posedge clk) disable iff ($initstate)
    (state != n) |=> (state == ($past(state) + 1))
  );

  // A next-state of 0 arises only from prior state n or all ones.
  check_zero_next_only_from_prev_n_or_all_ones: assert property (
    @(posedge clk) disable iff ($initstate)
    (state == ALL_ZEROS) |-> (($past(state) == n) || ($past(state) == ALL_ONES))
  );

  // When state is all ones, out must be all ones.
  check_out_all_ones_when_state_all_ones: assert property (
    @(posedge clk)
    (state == ALL_ONES) |-> (out == ALL_ONES)
  );

  // If state < n, out is exactly one-hot at position state.
  check_out_onehot_when_state_lt_n: assert property (
    @(posedge clk)
    (state < n) |-> ($onehot(out) && (out == (1 << state)))
  );

  // If state >= n and not all ones, out must be zero.
  check_out_zero_when_state_ge_n_not_all_ones: assert property (
    @(posedge clk)
    ((state >= n) && (state != ALL_ONES)) |-> (out == ALL_ZEROS)
  );

  // out can be all ones only when state is all ones.
  check_out_allones_implies_state_allones: assert property (
    @(posedge clk)
    (out == ALL_ONES) |-> (state == ALL_ONES)
  );

  // State value n cannot persist for two consecutive cycles.
  check_state_n_not_sticky: assert property (
    @(posedge clk) disable iff ($initstate)
    (state == n) |=> (state != n)
  );

  // For n>1, when state equals n, out must be zero (truncation of 1<<n).
  generate if (n > 1) begin : gen_n_gt1
    check_out_zero_when_state_eq_n_n_gt1: assert property (
      @(posedge clk)
      (state == n) |-> (out == ALL_ZEROS)
    );
  end endgenerate

  // For n>1, when state == n-1, next state must be n.
  generate if (n > 1) begin : gen_n_minus1_to_n
    check_state_n_minus1_goto_n: assert property (
      @(posedge clk) disable iff ($initstate)
      (state == (n-1)) |=> (state == n)
    );
  end endgenerate

endmodule

rtl:
module multiplier(
    input [3:0] a,
    input [3:0] b,
    input enable,
    output reg signed [7:0] result
);

// Initialize the result to 0
initial begin
    result = 0;
end

// Multiplication process
always @(*) begin
    if (enable == 1) begin
        result = $signed(a) * $signed(b);
    end else begin
        result = 0;
    end
end

endmodule

sva:
module multiplier_sva (
    input logic [3:0] a,
    input logic [3:0] b,
    input logic enable,
    input logic signed [7:0] result
);
    // No explicit clock/reset in RTL; sample assertions on $global_clock. Purely combinational behavior.

    // When enabled, result equals the signed product of a and b.
    check_enabled_product: assert property (
        @(posedge $global_clock) enable |-> (result == ($signed(a) * $signed(b)))
    );

    // When disabled, result is 0.
    check_disabled_zero: assert property (
        @(posedge $global_clock) !enable |-> (result == 8'sd0)
    );

    // If either operand is zero while enabled, result is zero.
    check_zero_operand_zero_result: assert property (
        @(posedge $global_clock) (enable && ((a == 4'sd0) || (b == 4'sd0))) |-> (result == 8'sd0)
    );

    // If both operands are non-zero while enabled, result is non-zero.
    check_nonzero_operands_nonzero_result: assert property (
        @(posedge $global_clock) (enable && (a != 4'sd0) && (b != 4'sd0)) |-> (result != 8'sd0)
    );

    // With mixed operand signs (and non-zero), the product sign is negative.
    check_negative_sign_for_mixed_signs: assert property (
        @(posedge $global_clock) (enable && (a != 4'sd0) && (b != 4'sd0) && (a[3] ^ b[3])) |-> (result[7] == 1'b1)
    );

    // With same operand signs (and non-zero), the product sign is non-negative.
    check_positive_sign_for_same_signs: assert property (
        @(posedge $global_clock) (enable && (a != 4'sd0) && (b != 4'sd0) && ~(a[3] ^ b[3])) |-> (result[7] == 1'b0)
    );

    // Output remains stable when inputs and enable are stable.
    check_output_stable_if_inputs_stable: assert property (
        @(posedge $global_clock) ($stable(a) && $stable(b) && $stable(enable)) |-> $stable(result)
    );

    // Known inputs yield a known output (no X/Z propagation beyond inputs).
    check_known_output_when_inputs_known: assert property (
        @(posedge $global_clock) (!$isunknown({enable, a, b})) |-> (!$isunknown(result))
    );
endmodule

rtl:
module axi_protocol_converter(
    input wire aclk,
    input wire m_axi_arvalid,
    output reg m_axi_arready,
    input wire [31:0] m_axi_araddr,
    input wire [31:0] m_payload_i_reg,
    output wire [31:0] m_payload_o_reg,
    input wire si_rs_arvalid
);

    // Define states for the state machine
    localparam IDLE = 2'b00;
    localparam READ = 2'b01;
    localparam WRITE = 2'b10;

    // Define state registers
    reg [1:0] state_reg;
    reg [31:0] address_reg;
    reg [31:0] data_reg;

    // Define output registers
    reg [31:0] m_payload_o_reg_reg;

    // Default values
    assign m_payload_o_reg = m_payload_o_reg_reg;

    // State machine
    always @(posedge aclk) begin
        case (state_reg)
            IDLE: begin
                if (m_axi_arvalid) begin
                    address_reg <= m_axi_araddr;
                    state_reg <= READ;
                end
                else if (si_rs_arvalid) begin
                    address_reg <= m_axi_araddr;
                    data_reg <= m_payload_i_reg;
                    state_reg <= WRITE;
                end
            end
            READ: begin
                if (m_axi_arready) begin
                    m_axi_arready <= 0;
                    state_reg <= IDLE;
                end
                else begin
                    m_axi_arready <= 1;
                    state_reg <= READ;
                end
            end
            WRITE: begin
                if (m_axi_arready) begin
                    m_axi_arready <= 0;
                    state_reg <= IDLE;
                end
                else begin
                    m_payload_o_reg_reg <= data_reg;
                    m_axi_arready <= 1;
                    state_reg <= WRITE;
                end
            end
            default: state_reg <= IDLE;
        endcase
    end
endmodule

sva:
module axi_protocol_converter_sva (
    input logic aclk,
    input logic m_axi_arvalid,
    input logic m_axi_arready,
    input logic [31:0] m_axi_araddr,
    input logic [31:0] m_payload_i_reg,
    input logic [31:0] m_payload_o_reg,
    input logic si_rs_arvalid
);
    // m_axi_arready high pulses must be single-cycle.
    ready_pulse_single_cycle: assert property (
        @(posedge aclk) $rose(m_axi_arready) |-> ##1 !m_axi_arready
    );

    // m_payload_o_reg can change only in cycles when m_axi_arready is HIGH.
    payload_update_only_when_ready: assert property (
        @(posedge aclk) $changed(m_payload_o_reg) |-> (m_axi_arready == 1'b1)
    );

    // When m_axi_arready is LOW in a cycle, m_payload_o_reg must not change that cycle.
    payload_no_update_when_ready_low: assert property (
        @(posedge aclk) (m_axi_arready == 1'b0) |-> !$changed(m_payload_o_reg)
    );

    // m_payload_o_reg must not update in two consecutive cycles.
    payload_no_back_to_back_updates: assert property (
        @(posedge aclk) $changed(m_payload_o_reg) |-> ##1 !$changed(m_payload_o_reg)
    );

    // After a payload update, m_axi_arready must be LOW in the next cycle.
    payload_update_implies_ready_low_next: assert property (
        @(posedge aclk) $changed(m_payload_o_reg) |-> ##1 (m_axi_arready == 1'b0)
    );

    // If m_axi_arready is HIGH, m_payload_o_reg holds its value into the next cycle.
    ready_high_payload_stable_next: assert property (
        @(posedge aclk) (m_axi_arready == 1'b1) |-> ##1 $stable(m_payload_o_reg)
    );
endmodule

rtl:
module mux4to1 (
    input [3:0] in0,
    input [3:0] in1,
    input [3:0] in2,
    input [3:0] in3,
    input [1:0] sel,
    output reg [3:0] out
);

always @*
begin
    case(sel)
        2'b00: out = in0;
        2'b01: out = in1;
        2'b10: out = in2;
        2'b11: out = in3;
    endcase
end

endmodule

sva:
module mux4to1_sva (
    input logic CLK,
    input logic [3:0] in0,
    input logic [3:0] in1,
    input logic [3:0] in2,
    input logic [3:0] in3,
    input logic [1:0] sel,
    input logic [3:0] out
);
    ///// Functional mapping /////
    // When sel==00, out equals in0.
    select_00_routes_in0: assert property (
        @(posedge CLK) (sel == 2'b00) |-> (out == in0)
    );
    // When sel==01, out equals in1.
    select_01_routes_in1: assert property (
        @(posedge CLK) (sel == 2'b01) |-> (out == in1)
    );
    // When sel==10, out equals in2.
    select_10_routes_in2: assert property (
        @(posedge CLK) (sel == 2'b10) |-> (out == in2)
    );
    // When sel==11, out equals in3.
    select_11_routes_in3: assert property (
        @(posedge CLK) (sel == 2'b11) |-> (out == in3)
    );

    ///// Stability and dependency /////
    // If sel and all inputs are stable, out is stable.
    all_stable_implies_out_stable: assert property (
        @(posedge CLK) $stable(sel) && $stable(in0) && $stable(in1) && $stable(in2) && $stable(in3) |-> $stable(out)
    );
    // If sel==00 holds and in0 is stable, out is stable.
    stable_when_sel0_and_in0_stable: assert property (
        @(posedge CLK) (sel == 2'b00) && $stable(sel) && $stable(in0) |-> $stable(out)
    );
    // If sel==01 holds and in1 is stable, out is stable.
    stable_when_sel1_and_in1_stable: assert property (
        @(posedge CLK) (sel == 2'b01) && $stable(sel) && $stable(in1) |-> $stable(out)
    );
    // If sel==10 holds and in2 is stable, out is stable.
    stable_when_sel2_and_in2_stable: assert property (
        @(posedge CLK) (sel == 2'b10) && $stable(sel) && $stable(in2) |-> $stable(out)
    );
    // If sel==11 holds and in3 is stable, out is stable.
    stable_when_sel3_and_in3_stable: assert property (
        @(posedge CLK) (sel == 2'b11) && $stable(sel) && $stable(in3) |-> $stable(out)
    );

    ///// Change propagation /////
    // If sel==00 holds and in0 changes, out changes.
    change_propagation_sel0: assert property (
        @(posedge CLK) (sel == 2'b00) && $stable(sel) && $changed(in0) |-> $changed(out)
    );
    // If sel==01 holds and in1 changes, out changes.
    change_propagation_sel1: assert property (
        @(posedge CLK) (sel == 2'b01) && $stable(sel) && $changed(in1) |-> $changed(out)
    );
    // If sel==10 holds and in2 changes, out changes.
    change_propagation_sel2: assert property (
        @(posedge CLK) (sel == 2'b10) && $stable(sel) && $changed(in2) |-> $changed(out)
    );
    // If sel==11 holds and in3 changes, out changes.
    change_propagation_sel3: assert property (
        @(posedge CLK) (sel == 2'b11) && $stable(sel) && $changed(in3) |-> $changed(out)
    );
endmodule

rtl:
module comparator(A, B, Z);
  input [1:0] A;
  input [1:0] B;
  output Z;
  wire eq, gt;

  assign eq = (A == B);
  assign gt = (A > B);

  assign Z = (gt | eq);

endmodule

sva:
module comparator_sva (
    input logic CLK,
    input logic [1:0] A,
    input logic [1:0] B,
    input logic Z
);
    ///// Functional correctness /////
    // When A equals B, Z must be HIGH.
    check_z_high_when_equal: assert property (
        @(posedge CLK) disable iff (1'b0) (A == B) |-> (Z == 1'b1)
    );
    // When A is greater than B, Z must be HIGH.
    check_z_high_when_greater: assert property (
        @(posedge CLK) disable iff (1'b0) (A > B) |-> (Z == 1'b1)
    );
    // When A is less than B, Z must be LOW.
    check_z_low_when_less: assert property (
        @(posedge CLK) disable iff (1'b0) (A < B) |-> (Z == 1'b0)
    );

    ///// Combinational consistency /////
    // If A and B are stable, Z must remain stable.
    check_stability_when_inputs_stable: assert property (
        @(posedge CLK) disable iff (1'b0) ($stable(A) && $stable(B)) |-> $stable(Z)
    );
    // Any change on Z must be caused by a change on A or B.
    check_output_change_requires_input_change: assert property (
        @(posedge CLK) disable iff (1'b0) $changed(Z) |-> ($changed(A) || $changed(B))
    );
endmodule

rtl:
module flip_flop (
    Q      ,
    Q_N    ,
    D      ,
    SCD    ,
    SCE    ,
    CLK_N  ,
    SET_B  ,
    RESET_B
);

    output Q      ;
    output Q_N    ;
    input  D      ;
    input  SCD    ;
    input  SCE    ;
    input  CLK_N  ;
    input  SET_B  ;
    input  RESET_B;

    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;

    reg Q;
    reg Q_N;

    always @(negedge CLK_N) begin
        if (SCD == 1'b1) begin
            Q <= 1'b0;
            Q_N <= 1'b1;
        end
        else if (SCE == 1'b1) begin
            Q <= 1'b1;
            Q_N <= 1'b0;
        end
        else if (SET_B == 1'b0) begin
            Q <= 1'b1;
            Q_N <= 1'b0;
        end
        else if (RESET_B == 1'b0) begin
            Q <= 1'b0;
            Q_N <= 1'b1;
        end
        else begin
            Q <= D;
            Q_N <= ~D;
        end
    end

endmodule

sva:
module flip_flop_sva (
    input logic Q,
    input logic Q_N,
    input logic D,
    input logic SCD,
    input logic SCE,
    input logic CLK_N,
    input logic SET_B,
    input logic RESET_B
);

    // SCD=1 at a negedge forces next Q=0 and Q_N=1 (highest priority).
    check_scd_forces_q0: assert property (
        @(negedge CLK_N) (SCD == 1'b1) |=> (Q == 1'b0) && (Q_N == 1'b1)
    );

    // With SCD=0 and SCE=1 at a negedge, next Q=1 and Q_N=0.
    check_sce_forces_q1: assert property (
        @(negedge CLK_N) (SCD == 1'b0) && (SCE == 1'b1) |=> (Q == 1'b1) && (Q_N == 1'b0)
    );

    // With SCD=0, SCE=0, and SET_B=0 at a negedge, next Q=1 and Q_N=0.
    check_setb_low_forces_q1: assert property (
        @(negedge CLK_N) (SCD == 1'b0) && (SCE == 1'b0) && (SET_B == 1'b0) |=> (Q == 1'b1) && (Q_N == 1'b0)
    );

    // With SCD=0, SCE=0, SET_B=1, and RESET_B=0 at a negedge, next Q=0 and Q_N=1.
    check_resetb_low_forces_q0: assert property (
        @(negedge CLK_N) (SCD == 1'b0) && (SCE == 1'b0) && (SET_B == 1'b1) && (RESET_B == 1'b0) |=> (Q == 1'b0) && (Q_N == 1'b1)
    );

    // With no control active at a negedge, next Q follows prior D and Q_N is its inverse.
    check_default_loads_d: assert property (
        @(negedge CLK_N) (SCD == 1'b0) && (SCE == 1'b0) && (SET_B == 1'b1) && (RESET_B == 1'b1) |=> (Q == $past(D)) && (Q_N == ~$past(D))
    );

    // After any negedge update, Q_N is the bitwise complement of Q.
    check_outputs_complement_each_cycle: assert property (
        @(negedge CLK_N) 1'b1 |=> (Q_N == ~Q)
    );

    // If the default path occurs in back-to-back cycles and D is unchanged, Q and Q_N remain unchanged.
    check_hold_when_default_and_D_stable: assert property (
        @(negedge CLK_N)
            $past((SCD == 1'b0) && (SCE == 1'b0) && (SET_B == 1'b1) && (RESET_B == 1'b1)) &&
            (SCD == 1'b0) && (SCE == 1'b0) && (SET_B == 1'b1) && (RESET_B == 1'b1) &&
            (D == $past(D))
        |-> (Q == $past(Q)) && (Q_N == $past(Q_N))
    );

endmodule

