module custom_module (
    Y   ,
    A1  ,
    A2  ,
    A3  ,
    B1  ,
    B2  ,
    VPWR,
    VGND,
    VPB ,
    VNB
);

    output Y   ;
    input  A1  ;
    input  A2  ;
    input  A3  ;
    input  B1  ;
    input  B2  ;
    input  VPWR;
    input  VGND;
    input  VPB ;
    input  VNB ;

    assign Y = (A1 && !A2 && A3 && B1 && !B2) ? 1'b1 : 1'b0;

endmodule

sva:
module custom_module_sva (
    input logic Y,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic B1,
    input logic B2,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB
);

    ///// Functional equivalence /////
    // Y equals the boolean function A1 && !A2 && A3 && B1 && !B2 (4-state exact).
    check_y_function_equivalence: assert property (
        @(posedge A1 or posedge A2 or posedge A3 or posedge B1 or posedge B2 or posedge Y)
            (Y === (A1 && !A2 && A3 && B1 && !B2))
    );

    ///// Truth table implications /////
    // When the exact enable condition holds, Y must be 1.
    check_y_when_condition_true: assert property (
        @(posedge A1 or posedge A2 or posedge A3 or posedge B1 or posedge B2 or posedge Y)
            (A1 && !A2 && A3 && B1 && !B2) |-> (Y === 1'b1)
    );

    // A1 LOW forces Y LOW.
    check_y_zero_when_A1_low: assert property (
        @(posedge A1 or posedge A2 or posedge A3 or posedge B1 or posedge B2 or posedge Y)
            (!A1) |-> (Y === 1'b0)
    );

    // A2 HIGH forces Y LOW.
    check_y_zero_when_A2_high: assert property (
        @(posedge A1 or posedge A2 or posedge A3 or posedge B1 or posedge B2 or posedge Y)
            (A2) |-> (Y === 1'b0)
    );

    // A3 LOW forces Y LOW.
    check_y_zero_when_A3_low: assert property (
        @(posedge A1 or posedge A2 or posedge A3 or posedge B1 or posedge B2 or posedge Y)
            (!A3) |-> (Y === 1'b0)
    );

    // B1 LOW forces Y LOW.
    check_y_zero_when_B1_low: assert property (
        @(posedge A1 or posedge A2 or posedge A3 or posedge B1 or posedge B2 or posedge Y)
            (!B1) |-> (Y === 1'b0)
    );

    // B2 HIGH forces Y LOW.
    check_y_zero_when_B2_high: assert property (
        @(posedge A1 or posedge A2 or posedge A3 or posedge B1 or posedge B2 or posedge Y)
            (B2) |-> (Y === 1'b0)
    );

    ///// Output-to-input implications /////
    // If Y is HIGH, A1 must be HIGH.
    check_inputs_when_y_high_A1: assert property (
        @(posedge A1 or posedge A2 or posedge A3 or posedge B1 or posedge B2 or posedge Y)
            (Y === 1'b1) |-> (A1 === 1'b1)
    );

    // If Y is HIGH, A2 must be LOW.
    check_inputs_when_y_high_A2: assert property (
        @(posedge A1 or posedge A2 or posedge A3 or posedge B1 or posedge B2 or posedge Y)
            (Y === 1'b1) |-> (A2 === 1'b0)
    );

    // If Y is HIGH, A3 must be HIGH.
    check_inputs_when_y_high_A3: assert property (
        @(posedge A1 or posedge A2 or posedge A3 or posedge B1 or posedge B2 or posedge Y)
            (Y === 1'b1) |-> (A3 === 1'b1)
    );

    // If Y is HIGH, B1 must be HIGH.
    check_inputs_when_y_high_B1: assert property (
        @(posedge A1 or posedge A2 or posedge A3 or posedge B1 or posedge B2 or posedge Y)
            (Y === 1'b1) |-> (B1 === 1'b1)
    );

    // If Y is HIGH, B2 must be LOW.
    check_inputs_when_y_high_B2: assert property (
        @(posedge A1 or posedge A2 or posedge A3 or posedge B1 or posedge B2 or posedge Y)
            (Y === 1'b1) |-> (B2 === 1'b0)
    );

endmodule

rtl:
module add_sub_pipeline
(
    input wire [31:0] a,
    input wire [31:0] b,
    input wire        sub,
    output wire [31:0] sum
);

    wire [15:0] a_lsb  ;
    wire [15:0] b_lsb  ;
    wire [15:0] a_msb  ;
    wire [15:0] b_msb  ;
    wire [15:0] sum_lsb;
    wire [15:0] sum_msb;
    wire        cin_msb;
    wire        cin_lsb;

    assign a_lsb  = a[15:0];
    assign b_lsb  = b[15:0];
    assign a_msb  = a[31:16];
    assign b_msb  = b[31:16];

    assign cin_lsb = sub;
    assign cin_msb = sub;

    adder16 adder_lsb(.a(a_lsb), .b(b_lsb), .cin(cin_lsb), .sum(sum_lsb));
    adder16 adder_msb(.a(a_msb), .b(b_msb), .cin(cin_msb), .sum(sum_msb));

    assign sum = {sum_msb, sum_lsb};

endmodule
module adder16
(
    input wire [15:0] a,
    input wire [15:0] b,
    input wire        cin,
    output wire [15:0] sum
);

    wire [15:0] carry;

    assign sum = a + b + cin;
    assign carry = (a[15] & b[15]) | (a[15] & cin) | (b[15] & cin);

endmodule
module twos_complement
(
    input wire  in,
    output wire out
);

    assign out = ~in + 1;

endmodule

sva:
module add_sub_pipeline_sva (
    input logic        CLK,
    input logic [31:0] a,
    input logic [31:0] b,
    input logic        sub,
    input logic [31:0] sum
);
    ///// Functional correctness /////
    // LSB 16-bit sum equals a[15:0] + b[15:0] + sub (low 16 bits).
    check_sum_lsb_correct: assert property (
        @(posedge CLK) sum[15:0] == (a[15:0] + b[15:0] + sub)[15:0]
    );
    // MSB 16-bit sum equals a[31:16] + b[31:16] + sub (low 16 bits).
    check_sum_msb_correct: assert property (
        @(posedge CLK) sum[31:16] == (a[31:16] + b[31:16] + sub)[15:0]
    );
    // Full 32-bit sum is the concatenation of the two independent 16-bit sums.
    check_sum_concat_correct: assert property (
        @(posedge CLK) sum == { (a[31:16] + b[31:16] + sub)[15:0], (a[15:0] + b[15:0] + sub)[15:0] }
    );

    ///// Stability and independence /////
    // If inputs are unchanged, output is unchanged (purely combinational behavior).
    check_sum_stable_if_inputs_stable: assert property (
        @(posedge CLK) (a == $past(a) && b == $past(b) && sub == $past(sub)) |-> (sum == $past(sum))
    );
    // MSB sum is unaffected by changes to LSB inputs when MSB inputs and sub are unchanged.
    check_msb_independent_of_lsb: assert property (
        @(posedge CLK) (a[31:16] == $past(a[31:16]) && b[31:16] == $past(b[31:16]) && sub == $past(sub)) |-> (sum[31:16] == $past(sum[31:16]))
    );
    // LSB sum is unaffected by changes to MSB inputs when LSB inputs and sub are unchanged.
    check_lsb_independent_of_msb: assert property (
        @(posedge CLK) (a[15:0] == $past(a[15:0]) && b[15:0] == $past(b[15:0]) && sub == $past(sub)) |-> (sum[15:0] == $past(sum[15:0]))
    );

    ///// Basic identities /////
    // When b==0 and sub==0, sum equals a.
    check_identity_b_zero_no_cin: assert property (
        @(posedge CLK) (b == 32'h0 && sub == 1'b0) |-> (sum == a)
    );
    // When a==0 and sub==0, sum equals b.
    check_identity_a_zero_no_cin: assert property (
        @(posedge CLK) (a == 32'h0 && sub == 1'b0) |-> (sum == b)
    );
    // When a==0, b==0, and sub==1, sum is 0x0001_0001.
    check_zero_inputs_sub_one: assert property (
        @(posedge CLK) ((a == 32'h0) && (b == 32'h0) && (sub == 1'b1)) |-> (sum == 32'h0001_0001)
    );

    ///// Algebraic properties /////
    // Swapping a and b across cycles (with sub unchanged) leaves sum unchanged (commutativity).
    check_commutativity_swap: assert property (
        @(posedge CLK) (a == $past(b) && b == $past(a) && sub == $past(sub)) |-> (sum == $past(sum))
    );
    // If a and b are stable and sub toggles, sum[0] toggles (±1 on LSB half).
    check_lsb_bit0_toggles_on_sub_toggle: assert property (
        @(posedge CLK) (a == $past(a) && b == $past(b) && (sub != $past(sub))) |-> (sum[0] != $past(sum[0]))
    );
    // If a and b are stable and sub toggles, sum[16] toggles (±1 on MSB half).
    check_msb_bit0_toggles_on_sub_toggle: assert property (
        @(posedge CLK) (a == $past(a) && b == $past(b) && (sub != $past(sub))) |-> (sum[16] != $past(sum[16]))
    );
endmodule

module karnaugh_map_sva (
    input logic clk,        // sampling clock for SVA only (RTL has no clock/reset)
    input logic A, B, C, D, E,
    input logic F
);
    // F=0 for 00000
    check_map_00000_is_0: assert property (
        @(posedge clk) ({A,B,C,D,E} == 5'b00000) |-> (F == 1'b0)
    );
    // F=1 for 00001
    check_map_00001_is_1: assert property (
        @(posedge clk) ({A,B,C,D,E} == 5'b00001) |-> (F == 1'b1)
    );
    // F=1 for 00011
    check_map_00011_is_1: assert property (
        @(posedge clk) ({A,B,C,D,E} == 5'b00011) |-> (F == 1'b1)
    );
    // F=0 for 00010
    check_map_00010_is_0: assert property (
        @(posedge clk) ({A,B,C,D,E} == 5'b00010) |-> (F == 1'b0)
    );
