rtl:
module zet_next_or_not (
    input [1:0] prefix,
    input [7:1] opcode,
    input cx_zero,
    input zf,
    input ext_int,
    output next_in_opco,
    output next_in_exec
  );

  wire exit_z, cmp_sca, exit_rep, valid_ops;

  assign cmp_sca = opcode[2] & opcode[1];
  assign exit_z = prefix[0] ?  (cmp_sca ? ~zf : 1'b0 )
                            :  (cmp_sca ? zf : 1'b0 );
  assign exit_rep = cx_zero | exit_z;
  assign valid_ops = (opcode[7:1]==7'b1010_010   || opcode[7:1]==7'b1010_011   || opcode[7:1]==7'b1010_101   || opcode[7:1]==7'b1010_110   || opcode[7:1]==7'b1010_111); assign next_in_exec = prefix[1] && valid_ops && !exit_rep && !ext_int;
  assign next_in_opco = prefix[1] && valid_ops && cx_zero;
endmodule

sva:
module zet_next_or_not_sva (
    input  logic CLK,
    input  logic RESETn,
    input  logic [1:0] prefix,
    input  logic [7:1] opcode,
    input  logic cx_zero,
    input  logic zf,
    input  logic ext_int,
    input  logic next_in_opco,
    input  logic next_in_exec
);

    function automatic bit valid_ops_f (input logic [7:1] op);
        valid_ops_f = (op == 7'b1010_010) ||
                      (op == 7'b1010_011) ||
                      (op == 7'b1010_101) ||
                      (op == 7'b1010_110) ||
                      (op == 7'b1010_111);
    endfunction

    function automatic bit exit_z_f (input logic [1:0] pref, input logic [7:1] op, input logic zf_i);
        bit cmp_sca;
        cmp_sca = op[2] & op[1];
        exit_z_f = pref[0] ? (cmp_sca ? ~zf_i : 1'b0)
                           : (cmp_sca ?  zf_i : 1'b0);
    endfunction

    // next_in_opco equals prefix[1] && valid_ops && cx_zero.
    check_next_in_opco_definition: assert property (
        @(posedge CLK) disable iff (!RESETn)
        next_in_opco == (prefix[1] && valid_ops_f(opcode) && cx_zero)
    );

    // next_in_exec equals prefix[1] && valid_ops && !exit_rep && !ext_int.
    check_next_in_exec_definition: assert property (
        @(posedge CLK) disable iff (!RESETn)
        next_in_exec == (prefix[1] && valid_ops_f(opcode) && !(cx_zero | exit_z_f(prefix, opcode, zf)) && !ext_int)
    );

    // next_in_opco requires prefix[1].
    check_opco_requires_prefix1: assert property (
        @(posedge CLK) disable iff (!RESETn)
        next_in_opco |-> (prefix[1] == 1'b1)
    );

    // next_in_opco requires opcode to be valid.
    check_opco_requires_valid_ops: assert property (
        @(posedge CLK) disable iff (!RESETn)
        next_in_opco |-> valid_ops_f(opcode)
    );

    // next_in_opco requires cx_zero.
    check_opco_requires_cx_zero: assert property (
        @(posedge CLK) disable iff (!RESETn)
        next_in_opco |-> (cx_zero == 1'b1)
    );

    // next_in_exec requires prefix[1].
    check_exec_requires_prefix1: assert property (
        @(posedge CLK) disable iff (!RESETn)
        next_in_exec |-> (prefix[1] == 1'b1)
    );

    // next_in_exec requires opcode to be valid.
    check_exec_requires_valid_ops: assert property (
        @(posedge CLK) disable iff (!RESETn)
        next_in_exec |-> valid_ops_f(opcode)
    );

    // next_in_exec requires cx_zero LOW.
    check_exec_requires_not_cx_zero: assert property (
        @(posedge CLK) disable iff (!RESETn)
        next_in_exec |-> (cx_zero == 1'b0)
    );

    // next_in_exec requires ext_int LOW.
    check_exec_requires_not_ext_int: assert property (
        @(posedge CLK) disable iff (!RESETn)
        next_in_exec |-> (ext_int == 1'b0)
    );

    // next_in_exec requires exit_z LOW.
    check_exec_requires_not_exit_z: assert property (
        @(posedge CLK) disable iff (!RESETn)
        next_in_exec |-> (exit_z_f(prefix, opcode, zf) == 1'b0)
    );

    // If cmp_sca is 1, next_in_exec implies zf matches prefix[0] rule.
    check_exec_zf_when_cmp_sca: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (next_in_exec && (opcode[2] & opcode[1])) |-> (prefix[0] ? (zf == 1'b1) : (zf == 1'b0))
    );

    // Outputs cannot both be HIGH simultaneously.
    check_outputs_mutex: assert property (
        @(posedge CLK) disable iff (!RESETn)
        !(next_in_opco && next_in_exec)
    );

    // Invalid opcode forces both outputs LOW.
    check_invalid_ops_block_outputs: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (!valid_ops_f(opcode)) |-> (!next_in_opco && !next_in_exec)
    );

    // With prefix[1] && valid_ops && cx_zero, opco asserts and exec deasserts.
    check_cx_zero_selects_opco: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (prefix[1] && valid_ops_f(opcode) && cx_zero) |-> (next_in_opco && !next_in_exec)
    );

    // With all exec conditions met, exec asserts and opco deasserts.
    check_exec_true_when_conditions_met: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (prefix[1] && valid_ops_f(opcode) && !ext_int && !cx_zero &&
         ( !(opcode[2] & opcode[1]) || (prefix[0] ? (zf==1'b1) : (zf==1'b0)) )
        ) |-> (next_in_exec && !next_in_opco)
    );

    // ext_int HIGH blocks next_in_exec.
    check_ext_int_blocks_exec: assert property (
        @(posedge CLK) disable iff (!RESETn)
        ext_int |-> (next_in_exec == 1'b0)
    );

endmodule

rtl:
module top_module (
    input clk,
    input reset,  // Synchronous active-high reset
    input [7:0] d,  // 8-bit input for the register
    input select,  // Select input to choose between register and counter
    output [7:0] q  // 8-bit output from the addition operation
);

    // Declare internal wires
    wire [7:0] reg_out;
    wire [3:0] counter_out;

    // Instantiate the register module
    reg_module reg_inst (
        .clk(clk),
        .reset(reset),
        .d(d),
        .q(reg_out)
    );

    // Instantiate the counter module
    counter_module counter_inst (
        .clk(clk),
        .reset(reset),
        .q(counter_out)
    );

    // Instantiate the adder module
    adder_module adder_inst (
        .a(select ? reg_out : counter_out),
        .b(select ? counter_out : reg_out),
        .sum(q)
    );

endmodule

// 8-bit register with active high synchronous reset
module reg_module (
    input clk,
    input reset,  // Synchronous active-high reset
    input [7:0] d,  // 8-bit input
    output reg [7:0] q  // 8-bit output
);

    always @(posedge clk) begin
        if (reset) begin
            q <= 8'h34;
        end else begin
            q <= d;
        end
    end

endmodule

// 4-bit binary counter that counts from 0 through 15, with synchronous reset to 0
module counter_module (
    input clk,
    input reset,  // Synchronous active-high reset
    output reg [3:0] q  // 4-bit output
);

    always @(posedge clk) begin
        if (reset) begin
            q <= 4'b0;
        end else begin
            q <= q + 1;
        end
    end

endmodule

// Functional module that adds two 8-bit inputs
module adder_module (
    input [7:0] a,  // 8-bit input a
    input [7:0] b,  // 8-bit input b
    output reg [7:0] sum  // 8-bit output sum
);

    always @(*) begin
        sum = a + b;
    end

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic reset,
    input logic [7:0] d,
    input logic select,
    input logic [7:0] q,
    input logic [7:0] reg_out,
    input logic [3:0] counter_out
);
    ///// Register behavior /////
    // On the cycle after reset is asserted, reg_out must be 0x34.
    reg_reset_to_34_next: assert property (
        @(posedge clk) reset |=> (reg_out == 8'h34)
    );
    // While reset remains asserted across cycles, reg_out holds 0x34.
    reg_holds_34_during_reset: assert property (
        @(posedge clk) (reset && $past(reset)) |-> (reg_out == 8'h34)
    );
    // On the cycle reset deasserts, reg_out still reflects the reset value before update.
    reg_deassert_cycle_shows_34: assert property (
        @(posedge clk) ($past(reset) && !reset) |-> (reg_out == 8'h34)
    );
    // When not in reset and previous cycle not in reset, reg_out equals prior d.
    reg_loads_d_from_prev_cycle: assert property (
        @(posedge clk) disable iff (reset) (!$past(reset)) |-> (reg_out == $past(d))
    );

    ///// Counter behavior /////
    // On the cycle after reset is asserted, counter_out must be 0.
    counter_reset_to_0_next: assert property (
        @(posedge clk) reset |=> (counter_out == 4'b0)
    );
    // While reset remains asserted across cycles, counter_out holds 0.
    counter_holds_0_during_reset: assert property (
        @(posedge clk) (reset && $past(reset)) |-> (counter_out == 4'b0)
    );
    // On the cycle reset deasserts, counter_out is 0 before update.
    counter_deassert_cycle_shows_0: assert property (
        @(posedge clk) ($past(reset) && !reset) |-> (counter_out == 4'b0)
    );
    // When not in reset, counter_out increments by 1 modulo 16 each cycle.
    counter_increments_by_1: assert property (
        @(posedge clk) disable iff (reset) counter_out == ($past(counter_out) + 4'd1)
    );
    // When previous value was 15, next value wraps to 0.
    counter_wraps_from_15_to_0: assert property (
        @(posedge clk) disable iff (reset) ($past(counter_out) == 4'hF) |-> (counter_out == 4'h0)
    );

    ///// Adder/output behavior /////
    // q equals reg_out plus zero-extended counter_out (independent of select).
    adder_sum_matches_inputs: assert property (
        @(posedge clk) disable iff (reset) q == (reg_out + {4'b0, counter_out})[7:0]
    );
    // On the cycle after reset is asserted, q must be 0x34 (34 + 0).
    q_after_reset_is_34_next: assert property (
        @(posedge clk) reset |=> (q == 8'h34)
    );
endmodule

