module jaxa_errorStatus (
                          // inputs:
                           address,
                           clk,
                           in_port,
                           reset_n,

                          // outputs:
                           readdata
                        )
;

  output  [ 31: 0] readdata;
  input   [  1: 0] address;
  input            clk;
  input   [  7: 0] in_port;
  input            reset_n;


wire             clk_en;
wire    [  7: 0] data_in;
wire    [  7: 0] read_mux_out;
reg     [ 31: 0] readdata;
  assign clk_en = 1;
  //s1, which is an e_avalon_slave
  assign read_mux_out = {8 {(address == 2'b00)}} & data_in;
  always @(posedge clk or negedge reset_n)
    begin
      if (reset_n == 0)
          readdata <= 0;
      else if (clk_en)
          readdata <= {32'b0 | read_mux_out};
    end


  assign data_in = in_port;

endmodule

sva:
module jaxa_errorStatus_sva (
    input logic        clk,
    input logic        reset_n,
    input logic [1:0]  address,
    input logic [7:0]  in_port,
    input logic [31:0] readdata
);

    ///// Reset behavior /////
    // During reset, readdata must be zero.
    check_reset_clears_readdata: assert property (
        @(posedge clk) (!reset_n) |-> (readdata == 32'h0)
    );

    ///// Structural invariants /////
    // Upper 24 bits are always zero when not in reset.
    check_upper_bytes_zero: assert property (
        @(posedge clk) disable iff (!reset_n) readdata[31:8] == 24'h0
    );

    ///// Registered update semantics /////
    // On each cycle out of reset, readdata equals zero-extended muxed data from the prior cycle.
    check_registered_output_matches_prev_cycle: assert property (
        @(posedge clk) disable iff (!reset_n)
            $past(reset_n) |-> (readdata == {24'h0, ($past(address) == 2'b00) ? $past(in_port) : 8'h00})
    );

    // If previous address was 00, the low byte equals previous in_port.
    check_low_byte_tracks_in_port_when_addr0: assert property (
        @(posedge clk) disable iff (!reset_n)
            $past(reset_n) && ($past(address) == 2'b00) |-> (readdata[7:0] == $past(in_port))
    );

    // If previous address was not 00, the low byte is zero.
    check_low_byte_zero_when_addr_not0: assert property (
        @(posedge clk) disable iff (!reset_n)
            $past(reset_n) && ($past(address) != 2'b00) |-> (readdata[7:0] == 8'h00)
    );

endmodule

rtl:
module four_bit_adder(
    input [3:0] a,
    input [3:0] b,
    input cin,
    output [3:0] sum,
    output cout
);

    wire [3:0] xor_out;
    wire [3:0] and_out;
    wire [3:0] or_out;

    // XOR gates for sum calculation
    xor x1 (xor_out[0], a[0], b[0]);
    xor x2 (xor_out[1], a[1], b[1]);
    xor x3 (xor_out[2], a[2], b[2]);
    xor x4 (xor_out[3], a[3], b[3]);

    // AND gates for carry calculation
    and a1 (and_out[0], a[0], b[0]);
    and a2 (and_out[1], a[1], b[1]);
    and a3 (and_out[2], a[2], b[2]);
    and a4 (and_out[3], a[3], b[3]);

    // OR gates for carry calculation
    or o1 (or_out[0], and_out[0], and_out[1]);
    or o2 (or_out[1], and_out[2], and_out[3]);
    or o3 (or_out[2], xor_out[0], xor_out[1]);
    or o4 (or_out[3], xor_out[2], xor_out[3]);

    // Carry-out calculation
    assign cout = or_out[3];

    // Sum calculation
    assign sum[0] = xor_out[0] ^ cin;
    assign sum[1] = xor_out[1] ^ and_out[0];
    assign sum[2] = xor_out[2] ^ and_out[1];
    assign sum[3] = xor_out[3] ^ and_out[2];

endmodule

sva:
module four_bit_adder_sva (
    input  logic        clk,   // sampling clock for assertions (RTL has no clock)
    input  logic [3:0]  a,
    input  logic [3:0]  b,
    input  logic        cin,
    input  logic [3:0]  sum,
    input  logic        cout
);
    // RTL is purely combinational with no reset; wrapper adds clk for property sampling.

    // sum[0] implements (a0 ^ b0) ^ cin.
    check_sum0_def: assert property (
        @(posedge clk) sum[0] == ((a[0] ^ b[0]) ^ cin)
    );

    // sum[1] implements (a1 ^ b1) ^ (a0 & b0).
    check_sum1_def: assert property (
        @(posedge clk) sum[1] == ((a[1] ^ b[1]) ^ (a[0] & b[0]))
    );

    // sum[2] implements (a2 ^ b2) ^ (a1 & b1).
    check_sum2_def: assert property (
        @(posedge clk) sum[2] == ((a[2] ^ b[2]) ^ (a[1] & b[1]))
    );

    // sum[3] implements (a3 ^ b3) ^ (a2 & b2).
    check_sum3_def: assert property (
        @(posedge clk) sum[3] == ((a[3] ^ b[3]) ^ (a[2] & b[2]))
    );

    // cout implements (a2 ^ b2) | (a3 ^ b3).
    check_cout_def: assert property (
        @(posedge clk) cout == ((a[2] ^ b[2]) | (a[3] ^ b[3]))
    );

    // When a0 equals b0, sum[0] equals cin.
    sum0_when_equal_inputs0: assert property (
        @(posedge clk) (a[0] == b[0]) |-> (sum[0] == cin)
    );

    // When a0 differs from b0, sum[0] equals ~cin.
    sum0_when_diff_inputs0: assert property (
        @(posedge clk) (a[0] != b[0]) |-> (sum[0] == ~cin)
    );

    // When a1 equals b1, sum[1] equals (a0 & b0).
    sum1_when_equal_inputs1: assert property (
        @(posedge clk) (a[1] == b[1]) |-> (sum[1] == (a[0] & b[0]))
    );

    // When a1 differs from b1, sum[1] equals ~(a0 & b0).
    sum1_when_diff_inputs1: assert property (
        @(posedge clk) (a[1] != b[1]) |-> (sum[1] == ~(a[0] & b[0]))
    );

    // If upper-bit pairs are equal, cout must be 0.
    cout_zero_when_top_pairs_equal: assert property (
        @(posedge clk) ((a[2] == b[2]) && (a[3] == b[3])) |-> (cout == 1'b0)
    );

    // If any upper-bit pair differs, cout must be 1.
    cout_one_when_any_top_pair_diff: assert property (
        @(posedge clk) ((a[2] != b[2]) || (a[3] != b[3])) |-> (cout == 1'b1)
    );

    // sum[0] changes only with a0, b0, or cin.
    sum0_dep_stability: assert property (
        @(posedge clk) $stable({a[0], b[0], cin}) |-> $stable(sum[0])
    );

    // sum[1] changes only with a1, b1, a0, or b0.
    sum1_dep_stability: assert property (
        @(posedge clk) $stable({a[1], b[1], a[0], b[0]}) |-> $stable(sum[1])
    );

    // sum[2] changes only with a2, b2, a1, or b1.
    sum2_dep_stability: assert property (
        @(posedge clk) $stable({a[2], b[2], a[1], b[1]}) |-> $stable(sum[2])
    );

    // sum[3] changes only with a3, b3, a2, or b2.
    sum3_dep_stability: assert property (
        @(posedge clk) $stable({a[3], b[3], a[2], b[2]}) |-> $stable(sum[3])
    );

    // cout changes only with a2, b2, a3, or b3.
    cout_dep_stability: assert property (
        @(posedge clk) $stable({a[2], b[2], a[3], b[3]}) |-> $stable(cout)
    );

endmodule

rtl:
module parity #(
  parameter n = 8 // number of input bits
)(
  input [n-1:0] in,
  output parity_out,
  output error_flag
);


wire [n:0] sum;
assign sum = {in, 1'b0} ^ {n+1{1'b0}}; // XOR with a vector of n+1 zeros

assign parity_out = ~sum[n]; // invert the most significant bit of the sum to get the parity bit

assign error_flag = sum[n]; // the error flag is the parity bit

endmodule

sva:
module parity_sva #(
    parameter n = 8
)(
    input logic [n-1:0] in,
    input logic parity_out,
    input logic error_flag
);

    ///// Functional relations /////
    // On parity_out rising, outputs reflect parity_out=~in[n-1] and error_flag=in[n-1].
    check_parity_rise_function: assert property (
        @(posedge parity_out) (parity_out == ~in[n-1]) && (error_flag == in[n-1])
    );

    // On error_flag rising, outputs reflect parity_out=~in[n-1] and error_flag=in[n-1].
    check_error_rise_function: assert property (
        @(posedge error_flag) (parity_out == ~in[n-1]) && (error_flag == in[n-1])
    );

    // On MSB rising, outputs reflect parity_out=~in[n-1] and error_flag=in[n-1].
    check_msb_rise_function: assert property (
        @(posedge in[n-1]) (parity_out == ~in[n-1]) && (error_flag == in[n-1])
    );

    // On parity_out rising, error_flag must be LOW (outputs are complements).
    check_complement_on_parity_rise: assert property (
        @(posedge parity_out) (error_flag == 1'b0)
    );

    // On error_flag rising, parity_out must be LOW (outputs are complements).
    check_complement_on_error_rise: assert property (
        @(posedge error_flag) (parity_out == 1'b0)
    );

    // On parity_out rising, MSB must be LOW (since parity_out = ~in[n-1]).
    check_parity_rise_implies_msb_low: assert property (
        @(posedge parity_out) (in[n-1] == 1'b0)
    );

    // On error_flag rising, MSB must be HIGH (since error_flag = in[n-1]).
    check_error_rise_implies_msb_high: assert property (
        @(posedge error_flag) (in[n-1] == 1'b1)
    );

    ///// Independence from lower bits /////
    // Any low-order bit rising alone must not change outputs (MSB stable).
    if (n > 1) begin : gen_lower_independence
        genvar i;
        for (i = 0; i < n-1; i++) begin : g_no_influence
            lower_bit_rise_no_output_change: assert property (
                @(posedge in[i]) $stable(in[n-1]) |-> $stable(parity_out) && $stable(error_flag)
            );
        end
    end

endmodule

rtl:
module PicoBlaze_OutReg
	#(parameter LOCAL_PORT_ID = 8'h00)
	(
	clk,
	reset,
	port_id,
	write_strobe,
	out_port,
	new_out_port);
input  wire        clk;
input  wire        reset;
input  wire    	 [7:0] port_id;
input  wire        write_strobe;
input  wire        [7:0] out_port;
output reg  		 [7:0] new_out_port;
reg RegEnable=1;





always @ (*)
	begin
		if (write_strobe == 1)
			begin
				case (port_id)
					LOCAL_PORT_ID: RegEnable = 1;
					default: RegEnable = 0;
				endcase
			end
		else
			RegEnable=0;
	end



	always @ (posedge clk, posedge reset)
	begin
		if(reset == 1)
			new_out_port <= 8'h00;
		else
			begin
				if(RegEnable == 1)
					new_out_port <= out_port;
				else
					new_out_port <= new_out_port;
			end
	end

endmodule

sva:
module PicoBlaze_OutReg_sva #(
    parameter LOCAL_PORT_ID = 8'h00
) (
    input  logic        clk,
    input  logic        reset,
    input  logic [7:0]  port_id,
    input  logic        write_strobe,
    input  logic [7:0]  out_port,
    input  logic [7:0]  new_out_port,
    input  logic        RegEnable
);

    ///// Reset behavior /////
    // While reset is HIGH, new_out_port must be 0.
    reset_forces_zero: assert property (
        @(posedge clk) reset |-> (new_out_port == 8'h00)
    );

    // On the cycle reset deasserts (HIGH->LOW), new_out_port remains 0.
    reset_fall_keeps_zero: assert property (
        @(posedge clk) $fell(reset) |-> (new_out_port == 8'h00)
    );

    ///// RegEnable decode /////
    // RegEnable equals write_strobe && (port_id == LOCAL_PORT_ID).
    regenable_definition: assert property (
        @(posedge clk) disable iff (reset)
            RegEnable == (write_strobe && (port_id == LOCAL_PORT_ID))
    );

    // If RegEnable is HIGH, write_strobe must be HIGH.
    regenable_requires_strobe: assert property (
        @(posedge clk) disable iff (reset)
            RegEnable |-> (write_strobe == 1'b1)
    );

    // If RegEnable is HIGH, port_id must match LOCAL_PORT_ID.
    regenable_requires_port_match: assert property (
        @(posedge clk) disable iff (reset)
            RegEnable |-> (port_id == LOCAL_PORT_ID)
    );

    ///// Register update semantics /////
    // A valid write updates new_out_port with out_port on the next clock.
    update_on_write_hit: assert property (
        @(posedge clk) disable iff (reset)
            (write_strobe && (port_id == LOCAL_PORT_ID)) |=> (new_out_port == $past(out_port))
    );

    // If there is no valid write in two consecutive cycles, new_out_port holds its value.
    hold_when_no_write_two_cycles: assert property (
        @(posedge clk) disable iff (reset)
            ( !(write_strobe && (port_id == LOCAL_PORT_ID))
              ##1 !(write_strobe && (port_id == LOCAL_PORT_ID)) )
            |-> (new_out_port == $past(new_out_port))
    );

endmodule

rtl:
module top_module (
    input [3:0] A,
    input [3:0] B,
    input SUBTRACT,
    output reg [3:0] SUM,
    output reg OVERFLOW,
    output reg EQUAL,
    output reg GREATER_THAN,
    output reg LESS_THAN
);

    wire [3:0] add_sub_out;
    wire [1:0] comp_out;
    reg overflow_int;

    reg carry_in;

    adder_subtractor add_sub (
        .A(A),
        .B(B),
        .SUBTRACT(SUBTRACT),
        .OUT(add_sub_out),
        .OVERFLOW(overflow_int)
    );

    comparator_2bit comp (
        .A(A),
        .B(B),
        .OUT(comp_out)
    );

    always @* begin
        SUM <= add_sub_out;
        OVERFLOW <= overflow_int;
        EQUAL <= (comp_out == 2'b01);
        GREATER_THAN <= (comp_out == 2'b10);
        LESS_THAN <= (comp_out == 2'b00);
    end
endmodule
module adder_subtractor (
    input [3:0] A,
    input [3:0] B,
    input SUBTRACT,
    output reg [3:0] OUT,
    output reg OVERFLOW
);

    wire [3:0] twos_comp_B = (~B) + 1;

    always @* begin
        OUT <= A;
        OVERFLOW <= 0;
        if (SUBTRACT) begin
            OUT <= A + twos_comp_B;
        end else begin
            OUT <= A + B;
        end
        if (A >= OUT && SUBTRACT) begin
            OVERFLOW <= 1;
        end else if (A <= OUT && !SUBTRACT) begin
            OVERFLOW <= 1;
        end
    end
endmodule
module comparator_2bit (
    input [3:0] A,
    input [3:0] B,
    output reg [1:0] OUT
);

    always @(*) begin
        if (A > B) begin
            OUT <= 2'b10;
        end else if (A < B) begin
            OUT <= 2'b00;
        end else begin
            OUT <= 2'b01;
        end
    end
endmodule

sva:
module top_module_sva (
    input logic CLK,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic SUBTRACT,
    input logic [3:0] SUM,
    input logic OVERFLOW,
    input logic EQUAL,
    input logic GREATER_THAN,
    input logic LESS_THAN
);
    ///// SUM behavior /////
    // When not subtracting, SUM equals A + B (4-bit wrap).
    check_sum_add: assert property (
        @(posedge CLK) (!SUBTRACT) |-> (SUM == (A + B))
    );
    // When subtracting, SUM equals A + (~B) + 1 (two's complement, 4-bit wrap).
    check_sum_sub: assert property (
        @(posedge CLK) (SUBTRACT) |-> (SUM == (A + (~B) + 4'b0001))
    );
    // When subtracting and A == B, SUM is zero.
    check_sum_sub_equal_zero: assert property (
        @(posedge CLK) (SUBTRACT && (A == B)) |-> (SUM == 4'b0000)
    );

    ///// Comparator flags (EQUAL/GREATER_THAN/LESS_THAN) /////
    // Comparator flags are one-hot.
    check_compare_onehot: assert property (
        @(posedge CLK) $onehot({EQUAL, GREATER_THAN, LESS_THAN})
    );
    // If A == B, only EQUAL is asserted.
    check_equal_when_AeqB: assert property (
        @(posedge CLK) (A == B) |-> (EQUAL && !GREATER_THAN && !LESS_THAN)
    );
    // If EQUAL is asserted, then A == B.
    check_AeqB_when_equal: assert property (
        @(posedge CLK) (EQUAL) |-> (A == B)
    );
    // If A > B, only GREATER_THAN is asserted.
    check_gt_when_AgtB: assert property (
        @(posedge CLK) (A > B) |-> (GREATER_THAN && !EQUAL && !LESS_THAN)
    );
    // If GREATER_THAN is asserted, then A > B.
    check_AgtB_when_gt: assert property (
        @(posedge CLK) (GREATER_THAN) |-> (A > B)
    );
    // If A < B, only LESS_THAN is asserted.
    check_lt_when_AltB: assert property (
        @(posedge CLK) (A < B) |-> (LESS_THAN && !EQUAL && !GREATER_THAN)
    );
    // If LESS_THAN is asserted, then A < B.
    check_AltB_when_lt: assert property (
        @(posedge CLK) (LESS_THAN) |-> (A < B)
    );
endmodule

rtl:
module majority_gate (
    input A, B, C, D,
    output Y
);

wire AB, AC, AD, BC, BD, CD;

assign AB = A & B;
assign AC = A & C;
assign AD = A & D;
assign BC = B & C;
assign BD = B & D;
assign CD = C & D;

assign Y = (AB | AC | AD | BC | BD | CD);

endmodule

sva:
module majority_gate_sva (
    input logic CLK,
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic Y
);
    // Y equals the OR of all pairwise ANDs of A,B,C,D.
    check_y_equation: assert property (
        @(posedge CLK) Y == ((A & B) | (A & C) | (A & D) | (B & C) | (B & D) | (C & D))
    );

    // If A and B are HIGH together, Y must be HIGH.
    pair_AB_implies_Y: assert property (
        @(posedge CLK) (A & B) |-> Y
    );

    // If A and C are HIGH together, Y must be HIGH.
    pair_AC_implies_Y: assert property (
        @(posedge CLK) (A & C) |-> Y
    );

    // If A and D are HIGH together, Y must be HIGH.
    pair_AD_implies_Y: assert property (
        @(posedge CLK) (A & D) |-> Y
    );

    // If B and C are HIGH together, Y must be HIGH.
    pair_BC_implies_Y: assert property (
        @(posedge CLK) (B & C) |-> Y
    );

    // If B and D are HIGH together, Y must be HIGH.
    pair_BD_implies_Y: assert property (
        @(posedge CLK) (B & D) |-> Y
    );

    // If C and D are HIGH together, Y must be HIGH.
    pair_CD_implies_Y: assert property (
        @(posedge CLK) (C & D) |-> Y
    );

    // When all inputs are LOW, Y must be LOW.
    all_zero_implies_zero: assert property (
        @(posedge CLK) !(A | B | C | D) |-> !Y
    );

    // When exactly one input is HIGH, Y must be LOW.
    onehot_implies_zero: assert property (
        @(posedge CLK) $onehot({A,B,C,D}) |-> !Y
    );

    // When all inputs are HIGH, Y must be HIGH.
    all_one_implies_one: assert property (
        @(posedge CLK) (A & B & C & D) |-> Y
    );
endmodule

rtl:
module ones_complement(
    input [3:0] in,
    output [3:0] out
);

assign out = ~in;


endmodule

sva:
module ones_complement_sva (
    input logic clk,          // sampling clock (DUT has no clock/reset)
    input logic [3:0] in,
    input logic [3:0] out
);

    // out equals bitwise NOT of in.
    check_out_equals_bitwise_not_in: assert property (
        @(posedge clk) out == ~in
    );

    // out XOR in is all ones.
    check_xor_all_ones: assert property (
        @(posedge clk) (out ^ in) == 4'hF
    );

    // out OR in is all ones.
    check_or_all_ones: assert property (
        @(posedge clk) (out | in) == 4'hF
    );

    // out AND in is all zeros.
    check_and_all_zeros: assert property (
        @(posedge clk) (out & in) == 4'h0
    );

    // Bit 0 is complemented.
    check_bit0_complement: assert property (
        @(posedge clk) out[0] == ~in[0]
    );

    // Bit 1 is complemented.
    check_bit1_complement: assert property (
        @(posedge clk) out[1] == ~in[1]
    );

    // Bit 2 is complemented.
    check_bit2_complement: assert property (
        @(posedge clk) out[2] == ~in[2]
    );

    // Bit 3 is complemented.
    check_bit3_complement: assert property (
        @(posedge clk) out[3] == ~in[3]
    );

    // out is never equal to in.
    check_never_equal: assert property (
        @(posedge clk) out != in
    );

endmodule

rtl:
module priority_encoder_and_ripple_carry_adder (
    input [3:0] I,
    input [3:0] A,
    input [3:0] B,
    input Cin,
    input select,
    output reg [1:0] Y,
    output reg [3:0] Sum
);

wire [1:0] priority_enc_out;
wire [3:0] ripple_carry_out;

priority_encoder priority_enc_inst (
    .I(I),
    .Y(priority_enc_out)
);

ripple_carry_adder ripple_carry_inst (
    .A(A),
    .B(B),
    .Cin(Cin),
    .Sum(ripple_carry_out)
);

always @(*) begin
    if (select == 0) begin
        Y <= priority_enc_out;
        Sum <= 4'b0;
    end else begin
        Y <= 2'b0;
        Sum <= ripple_carry_out;
    end
end

endmodule

module priority_encoder (
    input [3:0] I,
    output reg [1:0] Y
);

always @* begin
    case (I)
        4'b0001: Y = 2'b00;
        4'b0010: Y = 2'b01;
        4'b0100: Y = 2'b10;
        4'b1000: Y = 2'b11;
        default: Y = 2'b00;
    endcase
end

endmodule

module ripple_carry_adder (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output reg [3:0] Sum
);

reg [3:0] temp;

always @* begin
    temp = A + B + Cin;
    Sum = temp[3:0];
end

endmodule

sva:
module priority_encoder_and_ripple_carry_adder_sva (
    input logic clk,
    input logic [3:0] I,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic Cin,
    input logic select,
    input logic [1:0] Y,
    input logic [3:0] Sum
);

    // When select=0, Sum is forced to zero.
    check_select0_sum_zero: assert property (
        @(posedge clk) (select == 1'b0) |-> (Sum == 4'b0000)
    );

    // When select=1, Y is forced to zero.
    check_select1_y_zero: assert property (
        @(posedge clk) (select == 1'b1) |-> (Y == 2'b00)
    );

    // When select=1, Sum equals A+B+Cin (low 4 bits).
    check_select1_sum_matches_adder: assert property (
        @(posedge clk) (select == 1'b1) |-> (Sum == (A + B + Cin))
    );

    // For select=0 and I==0001, Y==00.
    check_pe_sel0_i0001: assert property (
        @(posedge clk) (select == 1'b0 && I == 4'b0001) |-> (Y == 2'b00)
    );

    // For select=0 and I==0010, Y==01.
    check_pe_sel0_i0010: assert property (
        @(posedge clk) (select == 1'b0 && I == 4'b0010) |-> (Y == 2'b01)
    );

    // For select=0 and I==0100, Y==10.
    check_pe_sel0_i0100: assert property (
        @(posedge clk) (select == 1'b0 && I == 4'b0100) |-> (Y == 2'b10)
    );

    // For select=0 and I==1000, Y==11.
    check_pe_sel0_i1000: assert property (
        @(posedge clk) (select == 1'b0 && I == 4'b1000) |-> (Y == 2'b11)
    );

    // For select=0 and non-onehot I, Y==00 (default case).
    check_pe_sel0_default: assert property (
        @(posedge clk) (select == 1'b0 && !$onehot(I)) |-> (Y == 2'b00)
    );

    // Y==01 occurs only when select=0 and I==0010.
    check_y01_implies_i0010_sel0: assert property (
        @(posedge clk) (Y == 2'b01) |-> (select == 1'b0 && I == 4'b0010)
    );

    // Y==10 occurs only when select=0 and I==0100.
    check_y10_implies_i0100_sel0: assert property (
        @(posedge clk) (Y == 2'b10) |-> (select == 1'b0 && I == 4'b0100)
    );

    // Y==11 occurs only when select=0 and I==1000.
    check_y11_implies_i1000_sel0: assert property (
        @(posedge clk) (Y == 2'b11) |-> (select == 1'b0 && I == 4'b1000)
    );

    // Y and Sum are never both non-zero simultaneously.
    check_outputs_not_both_nonzero: assert property (
        @(posedge clk) !((|Y) && (|Sum))
    );

endmodule

