module barrel_shifter (
    input [3:0] in,
    input [1:0] shift_amt,
    input dir,
    output reg [3:0] out
);

    always @(*) begin
        case (dir)
            0: out = in << shift_amt;
            1: out = in >> shift_amt;
        endcase
    end

endmodule

sva:
module barrel_shifter_sva (
    input logic CLK,              // sampling clock for assertions (DUT has no clock/reset)
    input logic [3:0] in,
    input logic [1:0] shift_amt,
    input logic dir,
    input logic [3:0] out
);
    // DUT is pure combinational: dir==0 => out=in<<shift_amt; dir==1 => out=in>>shift_amt.

    // Out equals the selected shift function of inputs each cycle.
    check_out_comb_function: assert property (
        @(posedge CLK) out == (dir ? (in >> shift_amt) : (in << shift_amt))
    );

    // Shift-by-zero is a passthrough regardless of direction.
    check_shift0_passthrough: assert property (
        @(posedge CLK) (shift_amt == 2'd0) |-> (out == in)
    );

    // When inputs are stable, output remains stable (pure function property).
    check_stable_output_when_inputs_stable: assert property (
        @(posedge CLK) ($stable(in) && $stable(shift_amt) && $stable(dir)) |-> $stable(out)
    );

    // Left shift by 1: LSB becomes 0; upper bits shift up by one.
    check_left_shift_by1: assert property (
        @(posedge CLK) (dir == 1'b0 && shift_amt == 2'd1) |-> (out[0] == 1'b0 && out[3:1] == in[2:0])
    );

    // Left shift by 2: two LSBs become 0; upper two bits shift up by two.
    check_left_shift_by2: assert property (
        @(posedge CLK) (dir == 1'b0 && shift_amt == 2'd2) |-> (out[1:0] == 2'b00 && out[3:2] == in[1:0])
    );

    // Left shift by 3: lower three bits become 0; MSB takes in[0].
    check_left_shift_by3: assert property (
        @(posedge CLK) (dir == 1'b0 && shift_amt == 2'd3) |-> (out[2:0] == 3'b000 && out[3] == in[0])
    );

    // Right shift by 1: MSB becomes 0; lower bits shift down by one.
    check_right_shift_by1: assert property (
        @(posedge CLK) (dir == 1'b1 && shift_amt == 2'd1) |-> (out[3] == 1'b0 && out[2:0] == in[3:1])
    );

    // Right shift by 2: two MSBs become 0; lower two bits shift down by two.
    check_right_shift_by2: assert property (
        @(posedge CLK) (dir == 1'b1 && shift_amt == 2'd2) |-> (out[3:2] == 2'b00 && out[1:0] == in[3:2])
    );

    // Right shift by 3: upper three bits become 0; LSB takes in[3].
    check_right_shift_by3: assert property (
        @(posedge CLK) (dir == 1'b1 && shift_amt == 2'd3) |-> (out[3:1] == 3'b000 && out[0] == in[3])
    );

endmodule

rtl:
module final_output (
    input clk,
    input reset,
    input d,
    input rise,
    input down,
    output q_out
);

reg q = 0;
always @(posedge clk) begin
    if (reset) begin
        q <= 0;
    end else begin
        if (rise) begin
            q <= 1;
        end else if (down) begin
            q <= 0;
        end
    end
end

assign q_out = q;

endmodule

sva:
module final_output_sva (
    input logic clk,
    input logic reset,
    input logic d,
    input logic rise,
    input logic down,
    input logic q_out
);
    // Clock: clk; Reset: reset (active-high synchronous).
    // Sequential flop: rise sets 1, else if down sets 0, else hold; q_out mirrors flop.

    // During reset, output is forced low.
    reset_forces_zero: assert property (
        @(posedge clk) reset |-> (q_out == 1'b0)
    );

    // Full next-state function when not in reset.
    functional_next_state: assert property (
        @(posedge clk) disable iff (reset)
            q_out == ( rise ? 1'b1 : ( down ? 1'b0 : $past(q_out) ) )
    );

    // If rise is asserted, output becomes 1 (independent of down).
    check_rise_sets_one: assert property (
        @(posedge clk) disable iff (reset) rise |-> (q_out == 1'b1)
    );

    // If down is asserted without rise, output becomes 0.
    check_down_clears_when_no_rise: assert property (
        @(posedge clk) disable iff (reset) (down && !rise) |-> (q_out == 1'b0)
    );

    // If neither control is asserted, output holds its value.
    check_hold_when_no_ctrl: assert property (
        @(posedge clk) disable iff (reset) (!rise && !down) |-> $stable(q_out)
    );

    // When both controls are asserted, rise has priority and output is 1.
    check_priority_rise_over_down: assert property (
        @(posedge clk) disable iff (reset) (rise && down) |-> (q_out == 1'b1)
    );

    // A 0->1 transition on output can only occur due to rise when not in reset.
    check_output_rise_requires_rise: assert property (
        @(posedge clk) disable iff (reset) $rose(q_out) |-> rise
    );

    // A 1->0 transition on output (outside reset) can only occur due to down without rise.
    check_output_fall_requires_down_no_rise: assert property (
        @(posedge clk) disable iff (reset) $fell(q_out) |-> (down && !rise)
    );
endmodule

