sva:
module autoinst_multitemplate_sva (
    input  logic clk,
    input  logic rst_n,
    input  logic Boo1,
    input  logic Boo2,
    input  logic Boo3,
    input  logic b,
    input  logic c,
    input  logic [3:0] f4_dotnamed
);
    // f4 equals Boo1 + Boo2 + b + (Boo3 & c), zero-extended to 4 bits.
    check_f4_sum: assert property (
        @(posedge clk) disable iff (!rst_n)
            f4_dotnamed == ({3'b000,Boo1} + {3'b000,Boo2} + {3'b000,b} + {3'b000,(Boo3 & c)})
    );

    // f4 is in the numeric range 0..4.
    check_f4_range: assert property (
        @(posedge clk) disable iff (!rst_n)
            (f4_dotnamed <= 4'd4)
    );

    // MSB of f4 is always 0.
    check_f4_msb_zero: assert property (
        @(posedge clk) disable iff (!rst_n)
            (f4_dotnamed[3] == 1'b0)
    );

    // LSB equals XOR parity of contributors.
    check_f4_lsb_parity: assert property (
        @(posedge clk) disable iff (!rst_n)
            f4_dotnamed[0] == (Boo1 ^ Boo2 ^ b ^ (Boo3 & c))
    );

    // When all contributors are 0, f4 is 0.
    check_f4_all_zero: assert property (
        @(posedge clk) disable iff (!rst_n)
            (!Boo1 && !Boo2 && !b && !(Boo3 & c)) |-> (f4_dotnamed == 4'd0)
    );

    // When only Boo2 and b are 1, f4 is 2.
    check_f4_two_ones_boo2_b: assert property (
        @(posedge clk) disable iff (!rst_n)
            (Boo2 && b && !Boo1 && !(Boo3 & c)) |-> (f4_dotnamed == 4'd2)
    );

    // When c is 0, Boo3 contributes 0 to the sum.
    check_gate_by_c_zero: assert property (
        @(posedge clk) disable iff (!rst_n)
            (c == 1'b0) |-> (f4_dotnamed == ({3'b000,Boo1} + {3'b000,Boo2} + {3'b000,b}))
    );

    // When Boo3 is 0, its contribution is 0.
    check_gate_by_boo3_zero: assert property (
        @(posedge clk) disable iff (!rst_n)
            (Boo3 == 1'b0) |-> (f4_dotnamed == ({3'b000,Boo1} + {3'b000,Boo2} + {3'b000,b}))
    );

    // When Boo1,Boo2,b,Boo3,c are all 1, f4 is 4.
    check_all_four_ones: assert property (
        @(posedge clk) disable iff (!rst_n)
            (Boo1 && Boo2 && b && Boo3 && c) |-> (f4_dotnamed == 4'd4)
    );

    // f4[2] is 1 only when all four contributors are 1.
    check_bit2_only_when_all_four: assert property (
        @(posedge clk) disable iff (!rst_n)
            f4_dotnamed[2] |-> (Boo1 && Boo2 && b && Boo3 && c)
    );

    // When only Boo3&c is 1, f4 is 1.
    check_only_boo3c_one: assert property (
        @(posedge clk) disable iff (!rst_n)
            (!Boo1 && !Boo2 && !b && Boo3 && c) |-> (f4_dotnamed == 4'd1)
    );
endmodule

rtl:
module control(op, alu_op, regDst, aluSrc, memToReg, regWrite, memRead, memWrite, branch);

  input [5:0] op;

  output [1:0] alu_op;

  output regDst;

  output aluSrc;

  output memToReg;

  output regWrite;

  output memRead;

  output memWrite;

  output branch;

  wire int0;

  wire op0_bar;

  wire op1_bar;

  wire op2_bar;

  wire op3_bar;

  wire op4_bar;

  wire op5_bar;

  wire _00_;

  wire _01_;

  wire _02_;

  wire _03_;

  wire _04_;

  wire _05_;

  wire _06_;

  wire _07_;

  wire _08_;

  wire _09_;

  wire _10_;

  wire _11_;

  wire _12_;

  wire _13_;

  wire _14_;
  assign op0_bar = ~op[0];
  assign op1_bar = ~op[1];
  assign op2_bar = ~op[2];
  assign op3_bar = ~op[3];
  assign op4_bar = ~op[4];
  assign op5_bar = ~op[5];
  assign _00_ = op5_bar & op4_bar;
  assign _01_ = _00_ & op3_bar;
  assign _02_ = _01_ & op[2];
  assign _03_ = _02_ & op1_bar;
  assign alu_op[0] = _03_ & op0_bar;
  assign _04_ = _01_ & op2_bar;
  assign _05_ = _04_ & op1_bar;
  assign alu_op[1] = _05_ & op0_bar;
  assign _06_ = op[5] & op4_bar;
  assign _07_ = _06_ & op3_bar;
  assign _08_ = _07_ & op2_bar;
  assign _09_ = _08_ & op[1];
  assign int0 = _09_ & op[0];
  assign _10_ = _06_ & op[3];
  assign _11_ = _10_ & op2_bar;
  assign _12_ = _11_ & op[1];
  assign memWrite = _12_ & op[0];
  assign _13_ = _06_ & op2_bar;
  assign _14_ = _13_ & op[1];
  assign aluSrc = _14_ & op[0];
  assign regWrite = int0 | alu_op[1];
  assign regDst = alu_op[1];
  assign memToReg = int0;
  assign memRead = int0;
  assign branch = alu_op[0];
endmodule

sva:
module control_sva (
    input logic CLK,
    input logic RESETn,
    input logic [5:0] op,
    input logic [1:0] alu_op,
    input logic regDst,
    input logic aluSrc,
    input logic memToReg,
    input logic regWrite,
    input logic memRead,
    input logic memWrite,
    input logic branch
);
    // regDst mirrors alu_op[1].
    check_regDst_equals_aluop1: assert property (
        @(posedge CLK) disable iff (!RESETn) (regDst == alu_op[1])
    );

    // branch mirrors alu_op[0].
    check_branch_equals_aluop0: assert property (
        @(posedge CLK) disable iff (!RESETn) (branch == alu_op[0])
    );

    // memToReg equals memRead.
    check_memToReg_equals_memRead: assert property (
        @(posedge CLK) disable iff (!RESETn) (memToReg == memRead)
    );

    // aluSrc equals (memRead OR memWrite).
    check_aluSrc_equals_memRead_or_memWrite: assert property (
        @(posedge CLK) disable iff (!RESETn) (aluSrc == (memRead || memWrite))
    );

    // regWrite equals (memToReg OR regDst).
    check_regWrite_equals_memToReg_or_regDst: assert property (
        @(posedge CLK) disable iff (!RESETn) (regWrite == (memToReg || regDst))
    );

    // alu_op bits are mutually exclusive.
    check_aluop_mutex: assert property (
        @(posedge CLK) disable iff (!RESETn) !(alu_op[1] && alu_op[0])
    );

    // memRead and memWrite are mutually exclusive.
    check_mem_mutex: assert property (
        @(posedge CLK) disable iff (!RESETn) !(memRead && memWrite)
    );

    // memToReg implies regWrite.
    check_memToReg_implies_regWrite: assert property (
        @(posedge CLK) disable iff (!RESETn) memToReg |-> regWrite
    );

    // regDst implies regWrite.
    check_regDst_implies_regWrite: assert property (
        @(posedge CLK) disable iff (!RESETn) regDst |-> regWrite
    );

    // memWrite implies not regWrite.
    check_memWrite_implies_no_regWrite: assert property (
        @(posedge CLK) disable iff (!RESETn) memWrite |-> !regWrite
    );

    // When op == 6'b000000, decode R-type controls.
    check_decode_op_000000: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (op == 6'b000000) |-> (alu_op == 2'b10) && (regDst == 1'b1) && (regWrite == 1'b1) &&
                                 (memRead == 1'b0) && (memWrite == 1'b0) && (memToReg == 1'b0) &&
                                 (branch == 1'b0) && (aluSrc == 1'b0)
    );

    // When op == 6'b000100, decode branch controls.
    check_decode_op_000100: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (op == 6'b000100) |-> (alu_op == 2'b01) && (branch == 1'b1) &&
                                 (memRead == 1'b0) && (memWrite == 1'b0) && (memToReg == 1'b0) &&
                                 (regDst == 1'b0) && (regWrite == 1'b0) && (aluSrc == 1'b0)
    );

    // When op == 6'b100011, decode load controls.
    check_decode_op_100011: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (op == 6'b100011) |-> (memRead == 1'b1) && (memToReg == 1'b1) && (regWrite == 1'b1) &&
                                 (aluSrc == 1'b1) && (memWrite == 1'b0) && (branch == 1'b0) &&
                                 (regDst == 1'b0) && (alu_op == 2'b00)
    );

    // When op == 6'b101011, decode store controls.
    check_decode_op_101011: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (op == 6'b101011) |-> (memWrite == 1'b1) && (aluSrc == 1'b1) &&
                                 (regWrite == 1'b0) && (memRead == 1'b0) && (memToReg == 1'b0) &&
                                 (branch == 1'b0) && (regDst == 1'b0) && (alu_op == 2'b00)
    );
endmodule

module var14_multi_sva (
    input logic clk,
    input logic A, B, C, D, E, F, G, H, I, J, K, L, M, N,
    input logic valid
);
    // Recompute DUT combinational logic locally for checking
    wire [7:0] min_value  = 8'd120;
    wire [7:0] max_weight = 8'd60;
    wire [7:0] max_volume = 8'd60;

    wire [7:0] total_value =
          A * 8'd4
        + B * 8'd8
        + C * 8'd0
        + D * 8'd20
        + E * 8'd10
        + F * 8'd12
        + G * 8'd18
        + H * 8'd14
        + I * 8'd6
        + J * 8'd15
        + K * 8'd30
        + L * 8'd8
        + M * 8'd16
        + N * 8'd18;

    wire [7:0] total_weight =
          A * 8'd28
        + B * 8'd8
        + C * 8'd27
        + D * 8'd18
        + E * 8'd27
        + F * 8'd28
        + G * 8'd6
        + H * 8'd1
        + I * 8'd20
        + J * 8'd0
        + K * 8'd5
        + L * 8'd13
        + M * 8'd8
        + N * 8'd14;

    wire [7:0] total_volume =
          A * 8'd27
        + B * 8'd27
        + C * 8'd4
        + D * 8'd4
        + E * 8'd0
        + F * 8'd24
        + G * 8'd4
        + H * 8'd20
        + I * 8'd12
        + J * 8'd15
        + K * 8'd5
        + L * 8'd2
        + M * 8'd9
        + N * 8'd28;

    // valid matches the defined threshold comparison of totals
    check_valid_definition: assert property (
        @(posedge clk) valid == ((total_value >= min_value) && (total_weight <= max_weight) && (total_volume <= max_volume))
    );

    // Total value never exceeds sum of its coefficients (179)
    check_total_value_bound: assert property (
        @(posedge clk) total_value <= 8'd179
    );

    // Total weight never exceeds sum of its coefficients (203)
    check_total_weight_bound: assert property (
        @(posedge clk) total_weight <= 8'd203
    );

    // Total volume never exceeds sum of its coefficients (181)
    check_total_volume_bound: assert property (
        @(posedge clk) total_volume <= 8'd181
    );

    // All-zero inputs imply invalid (value too low)
    check_all_zero_implies_not_valid: assert property (
        @(posedge clk) (A==1'b0 && B==1'b0 && C==1'b0 && D==1'b0 && E==1'b0 && F==1'b0 && G==1'b0 &&
                        H==1'b0 && I==1'b0 && J==1'b0 && K==1'b0 && L==1'b0 && M==1'b0 && N==1'b0)
                        |-> (valid == 1'b0)
    );

    // Changing only C does not affect total_value (C's value coefficient is 0)
    check_c_change_no_value_effect: assert property (
        @(posedge clk) ($changed(C) && $stable({A,B,D,E,F,G,H,I,J,K,L,M,N}))
        |-> (total_value == $past(total_value))
    );

    // Changing only J does not affect total_weight (J's weight coefficient is 0)
    check_j_change_no_weight_effect: assert property (
        @(posedge clk) ($changed(J) && $stable({A,B,C,D,E,F,G,H,I,K,L,M,N}))
        |-> (total_weight == $past(total_weight))
    );

    // Changing only E does not affect total_volume (E's volume coefficient is 0)
    check_e_change_no_volume_effect: assert property (
        @(posedge clk) ($changed(E) && $stable({A,B,C,D,F,G,H,I,J,K,L,M,N}))
        |-> (total_volume == $past(total_volume))
    );

    // Rising A increases totals by its coefficients
    check_a_rise_increments_totals: assert property (
        @(posedge clk) ($rose(A) && $stable({B,C,D,E,F,G,H,I,J,K,L,M,N}))
        |-> ( (total_value  == $past(total_value)  + 8'd4)
           && (total_weight == $past(total_weight) + 8'd28)
           && (total_volume == $past(total_volume) + 8'd27) )
    );

    // Falling A decreases totals by its coefficients
    check_a_fall_decrements_totals: assert property (
        @(posedge clk) ($fell(A) && $stable({B,C,D,E,F,G,H,I,J,K,L,M,N}))
        |-> ( (total_value  == $past(total_value)  - 8'd4)
           && (total_weight == $past(total_weight) - 8'd28)
           && (total_volume == $past(total_volume) - 8'd27) )
    );

    // Rising K increases totals by its coefficients
    check_k_rise_increments_totals: assert property (
        @(posedge clk) ($rose(K) && $stable({A,B,C,D,E,F,G,H,I,J,L,M,N}))
        |-> ( (total_value  == $past(total_value)  + 8'd30)
           && (total_weight == $past(total_weight) + 8'd5)
           && (total_volume == $past(total_volume) + 8'd5) )
    );

    // Falling K decreases totals by its coefficients
    check_k_fall_decrements_totals: assert property (
        @(posedge clk) ($fell(K) && $stable({A,B,C,D,E,F,G,H,I,J,L,M,N}))
        |-> ( (total_value  == $past(total_value)  - 8'd30)
           && (total_weight == $past(total_weight) - 8'd5)
           && (total_volume == $past(total_volume) - 8'd5) )
    );

    // Rising J increases value and volume by 15 and keeps weight unchanged
    check_j_rise_effects: assert property (
        @(posedge clk) ($rose(J) && $stable({A,B,C,D,E,F,G,H,I,K,L,M,N}))
        |-> ( (total_value  == $past(total_value)  + 8'd15)
           && (total_weight == $past(total_weight) + 8'd0)
           && (total_volume == $past(total_volume) + 8'd15) )
    );

    // Falling J decreases value and volume by 15 and keeps weight unchanged
    check_j_fall_effects: assert property (
        @(posedge clk) ($fell(J) && $stable({A,B,C,D,E,F,G,H,I,K,L,M,N}))
        |-> ( (total_value  == $past(total_value)  - 8'd15)
           && (total_weight == $past(total_weight) - 8'd0)
           && (total_volume == $past(total_volume) - 8'd15) )
    );
endmodule

rtl:
module mux_4to1(
  input [31:0] A,
  input [31:0] B,
  input [31:0] C,
  input [31:0] D,
  input [1:0] S,
  output reg [31:0] Y
);

  always @(*) begin
    case(S)
      2'b00: Y = A;
      2'b01: Y = B;
      2'b10: Y = C;
      2'b11: Y = D;
    endcase
  end

endmodule

sva:
module mux_4to1_sva (
    input logic clk,           // external verification clock
    input logic [31:0] A,
    input logic [31:0] B,
    input logic [31:0] C,
    input logic [31:0] D,
    input logic [1:0]  S,
    input logic [31:0] Y
);
    // Analysis: No clock/reset in DUT; pure combinational 4:1 mux. This wrapper samples on clk.

    default clocking cb @(posedge clk); endclocking

    // When S==00, Y must equal A.
    check_s00_selects_A: assert property ( (S == 2'b00) |-> (Y == A) );

    // When S==01, Y must equal B.
    check_s01_selects_B: assert property ( (S == 2'b01) |-> (Y == B) );

    // When S==10, Y must equal C.
    check_s10_selects_C: assert property ( (S == 2'b10) |-> (Y == C) );

    // When S==11, Y must equal D.
    check_s11_selects_D: assert property ( (S == 2'b11) |-> (Y == D) );

    // With S==00 and both S and A stable, Y must be stable.
    stable_y_when_s00_and_A_stable: assert property ( (S == 2'b00) && $stable(S) && $stable(A) |-> $stable(Y) );

    // With S==01 and both S and B stable, Y must be stable.
    stable_y_when_s01_and_B_stable: assert property ( (S == 2'b01) && $stable(S) && $stable(B) |-> $stable(Y) );

    // With S==10 and both S and C stable, Y must be stable.
    stable_y_when_s10_and_C_stable: assert property ( (S == 2'b10) && $stable(S) && $stable(C) |-> $stable(Y) );

    // With S==11 and both S and D stable, Y must be stable.
    stable_y_when_s11_and_D_stable: assert property ( (S == 2'b11) && $stable(S) && $stable(D) |-> $stable(Y) );

endmodule

rtl:
module fix_shifter(
    output [31:0] dout,
    input [31:0] B,
    input [1:0] ctrl,
    input [1:0] A
);

wire [31:0] shifted;

assign shifted = (ctrl == 2'b00) ? (B << A) :
                 (ctrl == 2'b01) ? (B << (A + 1)) :
                 (ctrl == 2'b10) ? (B << (A + 2)) :
                                   (B << (A + 3));
assign dout = shifted;

endmodule

sva:
module fix_shifter_sva (
    input logic clk,
    input logic [31:0] dout,
    input logic [31:0] B,
    input logic [1:0]  ctrl,
    input logic [1:0]  A
);
    // dout matches the RTL ternary shift selection for all ctrl values.
    check_dout_matches_muxed_shift: assert property (
        @(posedge clk) dout == ((ctrl == 2'b00) ? (B << A) :
                                (ctrl == 2'b01) ? (B << (A + 1)) :
                                (ctrl == 2'b10) ? (B << (A + 2)) :
                                                  (B << (A + 3)))
    );

    // When ctrl==00, dout equals B shifted left by A.
    check_ctrl00_shift: assert property (
        @(posedge clk) (ctrl == 2'b00) |-> (dout == (B << A))
    );

    // When ctrl==01, dout equals B shifted left by A+1.
    check_ctrl01_shift: assert property (
        @(posedge clk) (ctrl == 2'b01) |-> (dout == (B << (A + 1)))
    );

    // When ctrl==10, dout equals B shifted left by A+2.
    check_ctrl10_shift: assert property (
        @(posedge clk) (ctrl == 2'b10) |-> (dout == (B << (A + 2)))
    );

    // When ctrl==11, dout equals B shifted left by A+3.
    check_ctrl11_shift: assert property (
        @(posedge clk) (ctrl == 2'b11) |-> (dout == (B << (A + 3)))
    );

    // If inputs A,B,ctrl are stable, dout must remain stable.
    check_stable_on_stable_inputs: assert property (
        @(posedge clk) $stable({A, B, ctrl}) |-> $stable(dout)
    );

    // No-shift case: when A==0 and ctrl==0, dout equals B.
    check_no_shift_when_ctrl00_A00: assert property (
        @(posedge clk) ((A == 2'b00) && (ctrl == 2'b00)) |-> (dout == B)
    );

    // Compact equivalence: dout equals B shifted by (A + ctrl).
    check_equiv_compact_shift_amount: assert property (
        @(posedge clk) dout == (B << (A + ctrl))
    );

    // Zero input propagates: if B is zero, dout must be zero.
    check_zero_input_zero_output: assert property (
        @(posedge clk) (B == 32'b0) |-> (dout == 32'b0)
    );

    // Max shift example: when A==3 and ctrl==3, dout equals B << 6.
    check_max_shift_case: assert property (
        @(posedge clk) ((A == 2'b11) && (ctrl == 2'b11)) |-> (dout == (B << 6))
    );
endmodule

rtl:
module my_4input_nand (
    Y   ,
    A   ,
    B   ,
    C   ,
    D   
);

    output Y   ;
    input  A   ;
    input  B   ;
    input  C   ;
    input  D   ;

    wire nand1_out;
    wire nand2_out;
    wire nand3_out;

    nand (
        nand1_out,
        A,
        B,
        C,
        D
    );

    nand (
        nand2_out,
        nand1_out,
        nand1_out
    );

    not (
        nand3_out,
        nand2_out
    );

    assign Y = nand3_out;

endmodule

sva:
module my_4input_nand_sva (
    input logic Y,
    input logic A,
    input logic B,
    input logic C,
    input logic D
);
    // Y equals NAND of A,B,C,D.
    check_y_is_nand4: assert property (
        @(posedge A or posedge B or posedge C or posedge D) Y == ~(A & B & C & D)
    );

    // If any input is 0, Y must be 1.
    check_any_zero_implies_y1: assert property (
        @(posedge A or posedge B or posedge C or posedge D) ((A == 1'b0) || (B == 1'b0) || (C == 1'b0) || (D == 1'b0)) |-> (Y == 1'b1)
    );

    // If all inputs are 1, Y must be 0.
    check_all_ones_implies_y0: assert property (
        @(posedge A or posedge B or posedge C or posedge D) (A && B && C && D) |-> (Y == 1'b0)
    );

    // If Y is 0, then all inputs must be 1.
    check_y0_implies_all_ones: assert property (
        @(posedge A or posedge B or posedge C or posedge D) (Y == 1'b0) |-> (A && B && C && D)
    );

    // If Y is 1, then at least one input must be 0.
    check_y1_implies_any_zero: assert property (
        @(posedge A or posedge B or posedge C or posedge D) (Y == 1'b1) |-> ((A == 1'b0) || (B == 1'b0) || (C == 1'b0) || (D == 1'b0))
    );

    // De Morgan equivalence: Y equals (!A || !B || !C || !D).
    check_demorgan_form: assert property (
        @(posedge A or posedge B or posedge C or posedge D) Y == (!A || !B || !C || !D)
    );

    // On A rising when others are 1, Y must be 0.
    check_posedge_a_all_ones_y0: assert property (
        @(posedge A) (B && C && D) |-> (Y == 1'b0)
    );

    // On B rising when others are 1, Y must be 0.
    check_posedge_b_all_ones_y0: assert property (
        @(posedge B) (A && C && D) |-> (Y == 1'b0)
    );

    // On C rising when others are 1, Y must be 0.
    check_posedge_c_all_ones_y0: assert property (
        @(posedge C) (A && B && D) |-> (Y == 1'b0)
    );

    // On D rising when others are 1, Y must be 0.
    check_posedge_d_all_ones_y0: assert property (
        @(posedge D) (A && B && C) |-> (Y == 1'b0)
    );
endmodule

rtl:
module gray_code_converter (
    input [3:0] binary_in,
    input select,
    output reg [3:0] gray_out
);

    always @ (select or binary_in) begin
        if (select == 1'b1) begin
            gray_out[0] <= binary_in[0];
            gray_out[1] <= binary_in[0] ^ binary_in[1];
            gray_out[2] <= binary_in[1] ^ binary_in[2];
            gray_out[3] <= binary_in[2] ^ binary_in[3];
        end else begin
            gray_out <= binary_in;
        end
    end

endmodule

sva:
module gray_code_converter_sva (
    input  logic clk,              // sampling clock for assertions
    input  logic [3:0] binary_in,
    input  logic select,
    input  logic [3:0] gray_out
);
    // LSB always matches binary_in[0].
    check_lsb_matches: assert property (
        @(posedge clk) (gray_out[0] == binary_in[0])
    );

    // When select=0, output passes through binary_in.
    check_passthrough_when_select0: assert property (
        @(posedge clk) (!select) |-> (gray_out == binary_in)
    );

    // When select=1, gray_out[1] is binary_in[0] XOR binary_in[1].
    check_gray_bit1_when_select1: assert property (
        @(posedge clk) (select) |-> (gray_out[1] == (binary_in[0] ^ binary_in[1]))
    );

    // When select=1, gray_out[2] is binary_in[1] XOR binary_in[2].
    check_gray_bit2_when_select1: assert property (
        @(posedge clk) (select) |-> (gray_out[2] == (binary_in[1] ^ binary_in[2]))
    );

    // When select=1, gray_out[3] is binary_in[2] XOR binary_in[3].
    check_gray_bit3_when_select1: assert property (
        @(posedge clk) (select) |-> (gray_out[3] == (binary_in[2] ^ binary_in[3]))
    );

    // When select=1, full vector matches Gray-code mapping.
    check_full_gray_mapping_when_select1: assert property (
        @(posedge clk) (select) |-> (gray_out == { (binary_in[2] ^ binary_in[3]),
                                                   (binary_in[1] ^ binary_in[2]),
                                                   (binary_in[0] ^ binary_in[1]),
                                                   (binary_in[0]) })
    );

    // If inputs are stable across cycles, output remains stable.
    check_stability_with_stable_inputs: assert property (
        @(posedge clk) ($stable(binary_in) && $stable(select)) |-> $stable(gray_out)
    );
endmodule

rtl:
module counter (
    input clk,
    input reset,
    input [31:0] max_count,
    output reg [31:0] count
);

always @(posedge clk) begin
    if (reset) begin
        count <= 0;
    end else if (count == max_count) begin
        count <= 0;
    end else begin
        count <= count + 1;
    end
end

endmodule

sva:
module counter_sva (
    input logic clk,
    input logic reset,
    input logic [31:0] max_count,
    input logic [31:0] count
);

    // Synchronous reset drives count to 0 on the next cycle.
    reset_sets_zero_next: assert property (
        @(posedge clk) reset |=> (count == 32'd0)
    );

    // If reset is held across consecutive cycles, count is 0 on the later cycle.
    reset_held_keeps_zero: assert property (
        @(posedge clk) (reset && $past(reset)) |-> (count == 32'd0)
    );

    // On reset deassertion (prior cycle asserted, now deasserted), count is 0.
    reset_release_zero: assert property (
        @(posedge clk) ($past(reset) && !reset) |-> (count == 32'd0)
    );

    // When not in reset: if prior count == prior max_count, next count is 0 (wrap).
    wrap_on_match_prev: assert property (
        @(posedge clk) disable iff (reset)
            ($past(count) == $past(max_count)) |-> (count == 32'd0)
    );

    // When not in reset: if prior count != prior max_count, next count increments by 1.
    increment_on_neq_prev: assert property (
        @(posedge clk) disable iff (reset)
            ($past(count) != $past(max_count)) |-> (count == ($past(count) + 32'd1))
    );

    // When not in reset: next count matches the RTL branching (wrap or increment).
    next_value_follows_rtl: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(reset)) |-> (count == (($past(count) == $past(max_count)) ? 32'd0 : ($past(count) + 32'd1)))
    );

endmodule

rtl:
module barrel_shifter (
    input [3:0] A,
    input [1:0] B,
    output reg [3:0] Y
);

    always @(*) begin
        case (B)
            2'b00: Y = A;
            2'b01: Y = {A[2:0], 1'b0};
            2'b10: Y = {1'b0, A[3:1]};
            2'b11: Y = {2'b00, A[3:2]};
        endcase
    end

endmodule

sva:
module barrel_shifter_sva (
    input logic CLK,
    input logic [3:0] A,
    input logic [1:0] B,
    input logic [3:0] Y
);
    // B==00: pass-through
    check_b00_passthrough: assert property (
        @(posedge CLK) (B == 2'b00) |-> (Y == A)
    );

    // B==01: left shift by 1 with zero-fill on LSB
    check_b01_left_shift1: assert property (
        @(posedge CLK) (B == 2'b01) |-> (Y == {A[2:0], 1'b0})
    );

    // B==10: right shift by 1 with zero-fill on MSB
    check_b10_right_shift1: assert property (
        @(posedge CLK) (B == 2'b10) |-> (Y == {1'b0, A[3:1]})
    );

    // B==11: right shift by 2 with zero-fill on top two bits
    check_b11_right_shift2: assert property (
        @(posedge CLK) (B == 2'b11) |-> (Y == {2'b00, A[3:2]})
    );

    // For B==01, LSB must be zero
    check_b01_lsb_zero: assert property (
        @(posedge CLK) (B == 2'b01) |-> (Y[0] == 1'b0)
    );

    // For B==10, MSB must be zero
    check_b10_msb_zero: assert property (
        @(posedge CLK) (B == 2'b10) |-> (Y[3] == 1'b0)
    );

    // For B==11, top two bits must be zero
    check_b11_two_msb_zero: assert property (
        @(posedge CLK) (B == 2'b11) |-> (Y[3:2] == 2'b00)
    );

    // If A and B don't change, Y must not change
    check_output_stable_when_inputs_stable: assert property (
        @(posedge CLK) $stable({A, B}) |-> $stable(Y)
    );
endmodule

rtl:
module clock_gating (
    input CLK,
    input GATE,
    input VPB,
    input VPWR,
    input VGND,
    input VNB,
    output GCLK
);

    wire gated_clk;

    assign gated_clk = (GATE == 1'b1) ? CLK : 1'b0;
    assign GCLK = gated_clk;

endmodule

sva:
module clock_gating_sva (
    input logic CLK,
    input logic GATE,
    input logic VPB,
    input logic VPWR,
    input logic VGND,
    input logic VNB,
    input logic GCLK
);
    ///// Clock gating behavior /////
    // When CLK is high (posedge), GCLK equals GATE.
    check_gclk_eq_gate_on_clk_high: assert property (
        @(posedge CLK) (GCLK == GATE)
    );

    // When CLK is low (negedge), GCLK is forced low.
    check_gclk_low_on_clk_low: assert property (
        @(negedge CLK) (GCLK == 1'b0)
    );

    // A rising GATE across posedges produces a rising GCLK across posedges.
    check_gclk_rises_with_gate_rise: assert property (
        @(posedge CLK) $rose(GATE) |-> $rose(GCLK)
    );

    // A falling GATE across posedges produces a falling GCLK across posedges.
    check_gclk_falls_with_gate_fall: assert property (
        @(posedge CLK) $fell(GATE) |-> $fell(GCLK)
    );
endmodule

rtl:
module adder_subtractor(
    input [31:0] a,
    input [31:0] b,
    input sub,
    output [31:0] result
);

    assign result = sub ? a - b : a + b;

endmodule

module control_module(
    input select,
    output sub
);

    assign sub = select;

endmodule

module top_module(
    input [31:0] a,
    input [31:0] b,
    input sub,
    input select,
    output [31:0] final_output
);

    wire [31:0] adder_output;
    wire [31:0] subtractor_output;
    wire [31:0] inverted_subtractor_output;

    adder_subtractor adder(.a(a), .b(b), .sub(0), .result(adder_output));
    adder_subtractor subtractor(.a(a), .b(b), .sub(1), .result(subtractor_output));
    control_module control(.select(select), .sub(sub));
    assign inverted_subtractor_output = ~subtractor_output;

    assign final_output = select ? inverted_subtractor_output : adder_output;

endmodule

sva:
module top_module_sva (
    input logic CLK,                // External clock for assertions (RTL has no clock/reset)
    input logic [31:0] a,
    input logic [31:0] b,
    input logic sub,
    input logic select,
    input logic [31:0] final_output
);
    // final_output must be a+b when select is 0.
    check_select0_sum: assert property (
        @(posedge CLK) (select == 1'b0) |-> (final_output == (a + b))
    );

    // final_output must be ~(a-b) when select is 1.
    check_select1_inverted_sub: assert property (
        @(posedge CLK) (select == 1'b1) |-> (final_output == ~(a - b))
    );

    // Combined functional relation for all cases.
    check_function_combined: assert property (
        @(posedge CLK) final_output == (select ? ~(a - b) : (a + b))
    );

    // Internal control ties sub to select.
    check_sub_equals_select: assert property (
        @(posedge CLK) sub == select
    );

    // If a,b,select are stable, final_output must be stable.
    check_output_stable_when_inputs_stable: assert property (
        @(posedge CLK) $stable(a) && $stable(b) && $stable(select) |-> $stable(final_output)
    );

    // With select=0 stable and b stable, a increment by 1 causes final_output to increment by 1.
    inc_a_select0_increases_sum: assert property (
        @(posedge CLK) (select == 1'b0) && ($past(select) == 1'b0) && $stable(b) && (a == $past(a) + 32'd1)
        |-> (final_output == $past(final_output) + 32'd1)
    );

    // With select=0 stable and a stable, b increment by 1 causes final_output to increment by 1.
    inc_b_select0_increases_sum: assert property (
        @(posedge CLK) (select == 1'b0) && ($past(select) == 1'b0) && $stable(a) && (b == $past(b) + 32'd1)
        |-> (final_output == $past(final_output) + 32'd1)
    );

    // With select=1 stable and b stable, a increment by 1 causes final_output to decrement by 1.
    inc_a_select1_decreases_inverted_sub: assert property (
        @(posedge CLK) (select == 1'b1) && ($past(select) == 1'b1) && $stable(b) && (a == $past(a) + 32'd1)
        |-> (final_output == $past(final_output) - 32'd1)
    );

    // With select=1 stable and a stable, b increment by 1 causes final_output to increment by 1.
    inc_b_select1_increases_inverted_sub: assert property (
        @(posedge CLK) (select == 1'b1) && ($past(select) == 1'b1) && $stable(a) && (b == $past(b) + 32'd1)
        |-> (final_output == $past(final_output) + 32'd1)
    );

    // For select=1 and a==b, final_output must be all 1s.
    select1_equal_inputs_all_ones: assert property (
        @(posedge CLK) (select == 1'b1) && (a == b) |-> (final_output == 32'hFFFF_FFFF)
    );

    // For select=0 and b==0, final_output must pass through a.
    select0_b_zero_passthrough_a: assert property (
        @(posedge CLK) (select == 1'b0) && (b == 32'd0) |-> (final_output == a)
    );

    // For select=0 and a==0, final_output must pass through b.
    select0_a_zero_passthrough_b: assert property (
        @(posedge CLK) (select == 1'b0) && (a == 32'd0) |-> (final_output == b)
    );
endmodule

rtl:
module xor2 (
   // Outputs
   output reg z,
   // Inputs
   input a, b
   );

   parameter DELAY = 1;

   always @ (a or b) begin
      #DELAY z = a ^ b;
   end

endmodule

sva:
module xor2_sva (
    input logic a,
    input logic b,
    input logic z
);
    // Analysis: no clock or reset in RTL; purely combinational with #DELAY on assignment.
    // Functional behavior: z updates to a ^ b after DELAY time units when a or b changes.
    // With no clock/reset exposed by the RTL and timing-based behavior, no sound clocked SVA can be written without inventing signals.
endmodule

rtl:
module velocityControlHdl_MinMax
          (
           in0,
           in1,
           in2,
           out0
          );


  input   signed [17:0] in0;  input   signed [17:0] in1;  input   signed [17:0] in2;  output  signed [17:0] out0;  wire signed [17:0] MinMax_muxout [0:2];  wire signed [17:0] MinMax_stage1_val [0:1];  wire signed [17:0] MinMax_stage2_val;  assign MinMax_muxout[0] = in0;
  assign MinMax_muxout[1] = in1;
  assign MinMax_muxout[2] = in2;

  assign MinMax_stage1_val[0] = (MinMax_muxout[0] <= MinMax_muxout[1] ? MinMax_muxout[0] :
              MinMax_muxout[1]);
  assign MinMax_stage1_val[1] = MinMax_muxout[2];



  assign MinMax_stage2_val = (MinMax_stage1_val[0] <= MinMax_stage1_val[1] ? MinMax_stage1_val[0] :
              MinMax_stage1_val[1]);



  assign out0 = MinMax_stage2_val;

endmodule

sva:
module velocityControlHdl_MinMax_sva (
    input logic clk,
    input  signed [17:0] in0,
    input  signed [17:0] in1,
    input  signed [17:0] in2,
    input  signed [17:0] out0
);
    // Out must equal one of the inputs (min is selected from inputs).
    check_out_is_from_inputs: assert property (
        @(posedge clk) disable iff (1'b0) (out0 == in0) || (out0 == in1) || (out0 == in2)
    );

    // Out is less than or equal to in0.
    check_out_le_in0: assert property (
        @(posedge clk) disable iff (1'b0) out0 <= in0
    );

    // Out is less than or equal to in1.
    check_out_le_in1: assert property (
        @(posedge clk) disable iff (1'b0) out0 <= in1
    );

    // Out is less than or equal to in2.
    check_out_le_in2: assert property (
        @(posedge clk) disable iff (1'b0) out0 <= in2
    );

    // If in0 is less than or equal to both in1 and in2, out equals in0.
    select_in0_when_min: assert property (
        @(posedge clk) disable iff (1'b0) ((in0 <= in1) && (in0 <= in2)) |-> (out0 == in0)
    );

    // If in1 is strictly less than in0 and less than or equal to in2, out equals in1.
    select_in1_when_strict_min: assert property (
        @(posedge clk) disable iff (1'b0) ((in1 < in0) && (in1 <= in2)) |-> (out0 == in1)
    );

    // If in2 is strictly less than both in0 and in1, out equals in2.
    select_in2_when_strict_min: assert property (
        @(posedge clk) disable iff (1'b0) ((in2 < in0) && (in2 < in1)) |-> (out0 == in2)
    );

    // If out equals in0, then in0 is less than or equal to both in1 and in2.
    out_eq_in0_implies_in0_min: assert property (
        @(posedge clk) disable iff (1'b0) (out0 == in0) |-> ((in0 <= in1) && (in0 <= in2))
    );

    // If out equals in1, then in1 is strictly less than in0 and less than or equal to in2.
    out_eq_in1_implies_in1_min: assert property (
        @(posedge clk) disable iff (1'b0) (out0 == in1) |-> ((in1 < in0) && (in1 <= in2))
    );

    // If out equals in2, then in2 is strictly less than both in0 and in1.
    out_eq_in2_implies_in2_min: assert property (
        @(posedge clk) disable iff (1'b0) (out0 == in2) |-> ((in2 < in0) && (in2 < in1))
    );

    // Tie between in0 and in1 (and <= in2) selects in0 due to <= tie-break.
    tie_in0_in1_prefers_in0: assert property (
        @(posedge clk) disable iff (1'b0) ((in0 == in1) && (in0 <= in2)) |-> (out0 == in0)
    );

    // Tie between in0 and in2 (and <= in1) selects in0 due to <= tie-break.
    tie_in0_in2_prefers_in0: assert property (
        @(posedge clk) disable iff (1'b0) ((in0 == in2) && (in0 <= in1)) |-> (out0 == in0)
    );

    // Tie between in1 and in2, both less than in0, selects in1 due to <= tie-break.
    tie_in1_in2_prefers_in1: assert property (
        @(posedge clk) disable iff (1'b0) ((in1 == in2) && (in1 < in0)) |-> (out0 == in1)
    );

    // All inputs equal selects in0 due to tie-break ordering.
    all_equal_prefers_in0: assert property (
        @(posedge clk) disable iff (1'b0) ((in0 == in1) && (in1 == in2)) |-> (out0 == in0)
    );
endmodule

rtl:
module ip_packet_filter (
    input wire clk,
    input wire rst,
    input wire input_ip_hdr_valid,
    output wire input_ip_hdr_ready,
    input wire [31:0] input_ip_dest_ip,
    output wire output_ip_hdr_valid,
    input wire output_ip_hdr_ready,
    output wire [31:0] output_ip_dest_ip,
    output wire [47:0] output_ip_eth_dest_mac,
    output wire [15:0] output_ip_length,
    output wire drop
);

parameter FILTER_IP = 32'hc0a80101; // Predefined IP address to filter

reg [31:0] input_ip_dest_ip_reg;
reg [47:0] output_ip_eth_dest_mac_reg;
reg [15:0] output_ip_length_reg;
reg drop_reg;

assign input_ip_hdr_ready = 1;
assign output_ip_hdr_valid = input_ip_hdr_valid;
assign output_ip_dest_ip = input_ip_dest_ip_reg;
assign output_ip_eth_dest_mac = output_ip_eth_dest_mac_reg;
assign output_ip_length = output_ip_length_reg;
assign drop = drop_reg;

always @(posedge clk) begin
    if (rst) begin
        input_ip_dest_ip_reg <= 0;
        output_ip_eth_dest_mac_reg <= 0;
        output_ip_length_reg <= 0;
        drop_reg <= 0;
    end else begin
        if (input_ip_hdr_valid & output_ip_hdr_ready) begin
            input_ip_dest_ip_reg <= input_ip_dest_ip;
            output_ip_eth_dest_mac_reg <= output_ip_eth_dest_mac;
            output_ip_length_reg <= output_ip_length;
            drop_reg <= (input_ip_dest_ip == FILTER_IP);
        end
    end
end

endmodule

sva:
module ip_packet_filter_sva (
    input logic clk,
    input logic rst,
    input logic input_ip_hdr_valid,
    input logic input_ip_hdr_ready,
    input logic [31:0] input_ip_dest_ip,
    input logic output_ip_hdr_valid,
    input logic output_ip_hdr_ready,
    input logic [31:0] output_ip_dest_ip,
    input logic [47:0] output_ip_eth_dest_mac,
    input logic [15:0] output_ip_length,
    input logic drop
);
    // Clock: clk; Reset: rst (sync, active-high).
    // Logic: mixed (combinational assigns + sequential regs).
    // Key behavior: ready=1, valid mirrors input; on (input_ip_hdr_valid & output_ip_hdr_ready) capture dest_ip and set drop=(input_ip_dest_ip==FILTER_IP); eth_mac/length remain constant after reset.

    localparam logic [31:0] FILTER_IP = 32'hc0a80101;

    // input_ip_hdr_ready is hard-wired HIGH.
    check_input_ready_const_high: assert property (
        @(posedge clk) disable iff (rst) input_ip_hdr_ready == 1'b1
    );

    // output_ip_hdr_valid mirrors input_ip_hdr_valid.
    check_valid_passthrough: assert property (
        @(posedge clk) disable iff (rst) output_ip_hdr_valid == input_ip_hdr_valid
    );

    // Synchronous reset drives outputs to zero on the next cycle.
    check_reset_clears_outputs: assert property (
        @(posedge clk) rst |=> (output_ip_dest_ip == 32'h0) && (output_ip_eth_dest_mac == 48'h0) && (output_ip_length == 16'h0) && (drop == 1'b0)
    );

    // On handshake, capture input_ip_dest_ip into output_ip_dest_ip on next cycle.
    check_capture_dest_ip_on_handshake: assert property (
        @(posedge clk) disable iff (rst)
            (input_ip_hdr_valid && output_ip_hdr_ready) |=> (output_ip_dest_ip == $past(input_ip_dest_ip, 1, rst))
    );

    // Without handshake, output_ip_dest_ip holds its value.
    check_dest_ip_stable_without_handshake: assert property (
        @(posedge clk) disable iff (rst)
            !(input_ip_hdr_valid && output_ip_hdr_ready) |=> (output_ip_dest_ip == $past(output_ip_dest_ip, 1, rst))
    );

    // On handshake, drop updates to (input_ip_dest_ip == FILTER_IP) on next cycle.
    check_drop_update_on_handshake: assert property (
        @(posedge clk) disable iff (rst)
            (input_ip_hdr_valid && output_ip_hdr_ready) |=> (drop == ($past(input_ip_dest_ip, 1, rst) == FILTER_IP))
    );

    // Without handshake, drop holds its value.
    check_drop_stable_without_handshake: assert property (
        @(posedge clk) disable iff (rst)
            !(input_ip_hdr_valid && output_ip_hdr_ready) |=> (drop == $past(drop, 1, rst))
    );

    // Any change in drop must be due to a handshake in the prior cycle and must match the compare result.
    check_drop_change_requires_prev_handshake: assert property (
        @(posedge clk) disable iff (rst)
            (drop != $past(drop, 1, rst)) |-> $past(input_ip_hdr_valid && output_ip_hdr_ready, 1, rst)
                                         && (drop == ($past(input_ip_dest_ip, 1, rst) == FILTER_IP))
    );

    // Any change in output_ip_dest_ip must be due to a handshake in the prior cycle and must match the input sampled then.
    check_dest_ip_change_requires_prev_handshake: assert property (
        @(posedge clk) disable iff (rst)
            (output_ip_dest_ip != $past(output_ip_dest_ip, 1, rst)) |-> $past(input_ip_hdr_valid && output_ip_hdr_ready, 1, rst)
                                                                   && (output_ip_dest_ip == $past(input_ip_dest_ip, 1, rst))
    );

    // output_ip_eth_dest_mac remains constant after reset (self-assignment in RTL).
    check_eth_mac_stable_post_reset: assert property (
        @(posedge clk) disable iff (rst) $stable(output_ip_eth_dest_mac)
    );

    // output_ip_length remains constant after reset (self-assignment in RTL).
    check_length_stable_post_reset: assert property (
        @(posedge clk) disable iff (rst) $stable(output_ip_length)
    );

endmodule

rtl:
module mux_6to1 (
    input [2:0] sel,
    input [23:0] data_in,
    output reg [3:0] out
);

always @(*) begin
    case (sel)
        3'b000: out = data_in[3:0];
        3'b001: out = data_in[7:4];
        3'b010: out = data_in[11:8];
        3'b011: out = data_in[15:12];
        3'b100: out = data_in[19:16];
        3'b101: out = data_in[23:20];
        default: out = 4'b0000;
    endcase
end

endmodule

sva:
module mux_6to1_sva (
    input logic [2:0] sel,
    input logic [23:0] data_in,
    input logic [3:0] out
);
    ///// Functional mapping checks /////
    // sel=000 selects data_in[3:0].
    sel_000_selects_low_nibble: assert property (
        @(posedge $global_clock) (sel == 3'b000) |-> (out == data_in[3:0])
    );
    // sel=001 selects data_in[7:4].
    sel_001_selects_nibble1: assert property (
        @(posedge $global_clock) (sel == 3'b001) |-> (out == data_in[7:4])
    );
    // sel=010 selects data_in[11:8].
    sel_010_selects_nibble2: assert property (
        @(posedge $global_clock) (sel == 3'b010) |-> (out == data_in[11:8])
    );
    // sel=011 selects data_in[15:12].
    sel_011_selects_nibble3: assert property (
        @(posedge $global_clock) (sel == 3'b011) |-> (out == data_in[15:12])
    );
    // sel=100 selects data_in[19:16].
    sel_100_selects_nibble4: assert property (
        @(posedge $global_clock) (sel == 3'b100) |-> (out == data_in[19:16])
    );
    // sel=101 selects data_in[23:20].
    sel_101_selects_nibble5: assert property (
        @(posedge $global_clock) (sel == 3'b101) |-> (out == data_in[23:20])
    );
    // sel=110/111 drives out to 0 (default case).
    default_sel_outputs_zero: assert property (
        @(posedge $global_clock) (sel[2:1] == 2'b11) |-> (out == 4'b0000)
    );

    ///// General combinational properties /////
    // Out equals one of the six nibbles or zero.
    out_matches_allowed_values: assert property (
        @(posedge $global_clock)
            (out == data_in[3:0])  ||
            (out == data_in[7:4])  ||
            (out == data_in[11:8]) ||
            (out == data_in[15:12])||
            (out == data_in[19:16])||
            (out == data_in[23:20])||
            (out == 4'b0000)
    );
    // Out only changes when sel or data_in changes.
    out_changes_only_with_inputs: assert property (
        @(posedge $global_clock) $changed(out) |-> $changed({sel, data_in})
    );
    // If sel and data_in are stable, out is stable.
    out_stable_when_inputs_stable: assert property (
        @(posedge $global_clock) $stable({sel, data_in}) |-> $stable(out)
    );
endmodule

rtl:
module sync_counter (
    input clk,
    input reset,
    input count_en,
    input load,
    input [3:0] data_in,
    output reg [3:0] count_val,
    output reg overflow,
    output reg underflow
);

always @(posedge clk) begin
    if (reset) begin
        count_val <= 4'b0000;
        overflow <= 1'b0;
        underflow <= 1'b0;
    end else if (load) begin
        count_val <= data_in;
        overflow <= 1'b0;
        underflow <= 1'b0;
    end else if (count_en) begin
        if (count_val == 4'b1111) begin
            count_val <= 4'b0000;
            overflow <= 1'b1;
            underflow <= 1'b0;
        end else begin
            count_val <= count_val + 1;
            overflow <= 1'b0;
            underflow <= 1'b0;
        end
    end else begin
        if (count_val == 4'b0000) begin
            count_val <= 4'b1111;
            overflow <= 1'b0;
            underflow <= 1'b1;
        end else begin
            count_val <= count_val - 1;
            overflow <= 1'b0;
            underflow <= 1'b0;
        end
    end
end

endmodule

sva:
module sync_counter_sva (
    input logic clk,
    input logic reset,
    input logic count_en,
    input logic load,
    input logic [3:0] data_in,
    input logic [3:0] count_val,
    input logic overflow,
    input logic underflow
);
    // Clock: clk; Reset: reset (active-high, synchronous). All logic is sequential on posedge clk.

    // On reset, next cycle outputs are cleared.
    check_reset_clears_next: assert property (
        @(posedge clk) reset |=> (count_val == 4'b0000) && (overflow == 1'b0) && (underflow == 1'b0)
    );

    // Load has priority and updates count_val; flags clear next cycle.
    check_load_updates_and_clears_flags: assert property (
        @(posedge clk) disable iff (reset) load |=> (count_val == $past(data_in)) && (overflow == 1'b0) && (underflow == 1'b0)
    );

    // When counting up at max (0xF), wrap to 0 and set overflow; underflow clears.
    check_countup_wrap_sets_overflow: assert property (
        @(posedge clk) disable iff (reset) (!load && count_en && (count_val == 4'hF)) |=> (count_val == 4'h0) && (overflow == 1'b1) && (underflow == 1'b0)
    );

    // When counting up below max, increment by 1; both flags clear.
    check_countup_increment_clears_flags: assert property (
        @(posedge clk) disable iff (reset) (!load && count_en && (count_val != 4'hF)) |=> (count_val == ($past(count_val) + 4'd1)) && (overflow == 1'b0) && (underflow == 1'b0)
    );

    // When counting down at 0, wrap to 0xF and set underflow; overflow clears.
    check_countdown_wrap_sets_underflow: assert property (
        @(posedge clk) disable iff (reset) (!load && !count_en && (count_val == 4'h0)) |=> (count_val == 4'hF) && (underflow == 1'b1) && (overflow == 1'b0)
    );

    // When counting down above 0, decrement by 1; both flags clear.
    check_countdown_decrement_clears_flags: assert property (
        @(posedge clk) disable iff (reset) (!load && !count_en && (count_val != 4'h0)) |=> (count_val == ($past(count_val) - 4'd1)) && (overflow == 1'b0) && (underflow == 1'b0)
    );

    // Overflow and underflow are never asserted simultaneously.
    check_flags_mutex: assert property (
        @(posedge clk) disable iff (reset) !(overflow && underflow)
    );

    // On any countdown step (load=0, count_en=0), overflow is 0 next cycle.
    check_no_overflow_on_countdown: assert property (
        @(posedge clk) disable iff (reset) (!load && !count_en) |=> (overflow == 1'b0)
    );

    // On any count-up step (load=0, count_en=1), underflow is 0 next cycle.
    check_no_underflow_on_countup: assert property (
        @(posedge clk) disable iff (reset) (!load && count_en) |=> (underflow == 1'b0)
    );

    // Without load, the counter value always changes next cycle.
    check_no_hold_without_load: assert property (
        @(posedge clk) disable iff (reset) (!load) |=> (count_val != $past(count_val))
    );

    // Overflow cannot occur in two consecutive cycles.
    check_no_back_to_back_overflow: assert property (
        @(posedge clk) disable iff (reset) overflow |=> (overflow == 1'b0)
    );

    // Underflow cannot occur in two consecutive cycles.
    check_no_back_to_back_underflow: assert property (
        @(posedge clk) disable iff (reset) underflow |=> (underflow == 1'b0)
    );

endmodule

