sva:
module sky130_fd_sc_ms__a311oi_sva (
    input logic Y,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic B1,
    input logic C1
);
    // No clock/reset in DUT; pure combinational: Y = ~((A1 & A2 & A3) | B1 | C1). Sample on posedge A1.

    // Y equals the NOR of (A1&A2&A3), B1, and C1.
    check_function_equation: assert property (
        @(posedge A1) Y == ~((A1 & A2 & A3) | B1 | C1)
    );

    // B1 high forces Y low.
    check_B1_high_forces_Y0: assert property (
        @(posedge A1) B1 |-> (Y == 1'b0)
    );

    // C1 high forces Y low.
    check_C1_high_forces_Y0: assert property (
        @(posedge A1) C1 |-> (Y == 1'b0)
    );

    // All A inputs high forces Y low (when B1 and C1 are irrelevant).
    check_allA_high_forces_Y0: assert property (
        @(posedge A1) (A1 & A2 & A3) |-> (Y == 1'b0)
    );

    // If the OR of (A1&A2&A3), B1, or C1 is high, Y must be low.
    check_or_inputs_high_implies_Y0: assert property (
        @(posedge A1) ((A1 & A2 & A3) | B1 | C1) |-> (Y == 1'b0)
    );

    // Y high requires B1 and C1 low and not all A inputs high.
    check_Y1_requires_conditions: assert property (
        @(posedge A1) (Y == 1'b1) |-> ((~B1) & (~C1) & ~(A1 & A2 & A3))
    );

    // Y low implies at least one of (A1&A2&A3), B1, or C1 is high.
    check_Y0_implies_some_input_high: assert property (
        @(posedge A1) (Y == 1'b0) |-> ((A1 & A2 & A3) | B1 | C1)
    );

    // With B1=C1=0, Y equals NAND of A1,A2,A3.
    check_BC_zero_reduces_to_NAND3: assert property (
        @(posedge A1) ((~B1) & (~C1)) |-> (Y == ~(A1 & A2 & A3))
    );

    // With B1=C1=0 and Y low, all A inputs must be high.
    check_BC_zero_Y0_implies_allA_high: assert property (
        @(posedge A1) ((~B1) & (~C1) & (Y == 1'b0)) |-> (A1 & A2 & A3)
    );

    // With B1=C1=0 and Y high, not all A inputs are high.
    check_BC_zero_Y1_implies_not_allA_high: assert property (
        @(posedge A1) ((~B1) & (~C1) & (Y == 1'b1)) |-> ~(A1 & A2 & A3)
    );

endmodule

rtl:
module d_flip_flop (
    input clk,
    input d,
    output reg q
);

  always @(posedge clk) begin
    q <= d;
  end

endmodule

sva:
module d_flip_flop_sva (
    input logic clk,
    input logic d,
    input logic q
);

    // Q equals the value of D from the previous clock edge (one-cycle latency).
    check_q_equals_past_d: assert property (
        @(posedge clk) $past(1'b1) |-> (q == $past(d))
    );

    // If D was stable across the last two cycles, Q holds its value this cycle.
    check_q_stable_when_d_held: assert property (
        @(posedge clk) ($past(1'b1,2) && ($past(d) == $past(d,2))) |-> (q == $past(q))
    );

    // If D changed between the last two cycles, Q changes accordingly this cycle.
    check_q_changes_when_d_changes: assert property (
        @(posedge clk) ($past(1'b1,2) && ($past(d) != $past(d,2))) |-> (q != $past(q))
    );

    // The current D value is observed on Q at the next clock edge.
    check_next_cycle_transfer: assert property (
        @(posedge clk) 1'b1 |=> (q == $past(d))
    );

    // Whenever Q changes, its new value equals the previously sampled D.
    check_q_change_matches_prev_d: assert property (
        @(posedge clk) ($past(1'b1,2) && (q != $past(q))) |-> (q == $past(d))
    );

endmodule

rtl:
module BCD_to_Binary (
  input [3:0] bcd,
  output [7:0] bin
);

  // Lookup table for BCD to binary conversion
  // Each entry represents the binary equivalent of the BCD code
  // For example, 0000 (BCD for decimal 0) maps to 0000 (binary for decimal 0)
  // and 0100 (BCD for decimal 4) maps to 0100 (binary for decimal 4)
  // The table is defined as a parameter to make it easier to modify
  parameter [15:0] BCD_to_Bin_LUT = 16'b0000000000000101;

  // Convert each decimal digit in the BCD code to its binary equivalent
  // by using the lookup table
  wire [3:0] digit0_bin = BCD_to_Bin_LUT[bcd[3:0]];
  wire [3:0] digit1_bin = BCD_to_Bin_LUT[bcd[1:0]];

  // Combine the binary codes for each decimal digit to create the
  // eight-bit binary code output
  assign bin = {digit1_bin, digit0_bin};

endmodule

sva:
module BCD_to_Binary_sva (
    input logic CLK,
    input logic [3:0] bcd,
    input logic [7:0] bin
);
    // DUT has no clock or reset; combinational logic only. Assertions are sampled on external CLK.
    // Structure: bin = {zero-extended LUT[bcd[1:0]], zero-extended LUT[bcd]} ⇒ only bin[4] and bin[0] can be 1.

    // Past-valid guard for $past/$stable/$changed usage.
    logic past_valid;
    always_ff @(posedge CLK) past_valid <= 1'b1;

    // High nibble must have only its LSB possibly set.
    check_high_nibble_shape: assert property (
        @(posedge CLK) bin[7:4] == {3'b000, bin[4]}
    );

    // Low nibble must have only its LSB possibly set.
    check_low_nibble_shape: assert property (
        @(posedge CLK) bin[3:0] == {3'b000, bin[0]}
    );

    // No ones outside bit positions 4 and 0.
    check_reserved_bits_zero: assert property (
        @(posedge CLK) (bin & 8'hEE) == 8'h00
    );

    // If BCD input is stable, BIN output must be stable (purely combinational behavior).
    check_deterministic_function: assert property (
        @(posedge CLK) past_valid && $stable(bcd) |-> $stable(bin)
    );

    // If low two bits of BCD are stable, bin[4] must be stable (bin[4] depends only on bcd[1:0]).
    check_bin4_stable_with_low2_stable: assert property (
        @(posedge CLK) past_valid && $stable(bcd[1:0]) |-> $stable(bin[4])
    );

    // A change on bin[4] implies a change on bcd[1:0].
    check_bin4_change_implies_low2_change: assert property (
        @(posedge CLK) past_valid && $changed(bin[4]) |-> !$stable(bcd[1:0])
    );

    // A change on bin[0] implies some bit of bcd changed.
    check_bin0_change_implies_bcd_change: assert property (
        @(posedge CLK) past_valid && $changed(bin[0]) |-> !$stable(bcd)
    );

    // If only upper two bits of BCD change, the high nibble must remain stable.
    check_high_nibble_independent_of_upper_bcd: assert property (
        @(posedge CLK) past_valid && $stable(bcd[1:0]) |-> $stable(bin[7:4])
    );

endmodule

rtl:
module mux_4to1 (
    input [7:0] data_in_0,
    input [7:0] data_in_1,
    input [7:0] data_in_2,
    input [7:0] data_in_3,
    input sel1,
    input sel2,
    output reg [7:0] out
);

    always @(*) begin
        case ({sel2, sel1})
            2'b00: out <= data_in_0;
            2'b01: out <= data_in_1;
            2'b10: out <= data_in_2;
            2'b11: out <= data_in_3;
        endcase
    end

endmodule

module shift_left (
    input [7:0] data_in,
    input [3:0] shift,
    output reg [7:0] out
);

    always @(*) begin
        out <= data_in << shift;
    end

endmodule

module adder (
    input [7:0] data_in_1,
    input [7:0] data_in_2,
    output reg [7:0] out
);

    always @(*) begin
        out <= data_in_1 + data_in_2;
    end

endmodule

module shift_mux_adder (
    input [7:0] data_in_0,
    input [7:0] data_in_1,
    input [7:0] data_in_2,
    input [7:0] data_in_3,
    input [3:0] B,
    input sel1,
    input sel2,
    output reg [7:0] out
);

    wire [7:0] mux_out;
    wire [7:0] shift_out;

    mux_4to1 mux_inst (
        .data_in_0(data_in_0),
        .data_in_1(data_in_1),
        .data_in_2(data_in_2),
        .data_in_3(data_in_3),
        .sel1(sel1),
        .sel2(sel2),
        .out(mux_out)
    );

    shift_left shift_inst (
        .data_in(mux_out),
        .shift(B),
        .out(shift_out)
    );

    always @(*) begin
        if (B > 3) begin
            out <= 8'b0;
        end else begin
            out <= shift_out;
        end
    end

endmodule

sva:
module shift_mux_adder_sva (
    input logic clk,
    input logic [7:0] data_in_0,
    input logic [7:0] data_in_1,
    input logic [7:0] data_in_2,
    input logic [7:0] data_in_3,
    input logic [3:0] B,
    input logic sel1,
    input logic sel2,
    input logic [7:0] out
);
    // When B>3, out is forced to zero.
    check_B_gt3_zero: assert property (
        @(posedge clk) (B > 4'd3) |-> (out == 8'b0)
    );

    // For B<=3, out equals selected input left-shifted by B.
    check_B_le3_selected_shift: assert property (
        @(posedge clk) (B <= 4'd3) |-> (out == (((sel2 == 1'b0) ? ((sel1 == 1'b0) ? data_in_0 : data_in_1)
                                                                 : ((sel1 == 1'b0) ? data_in_2 : data_in_3)) << B))
    );

    // For B<=3 and sel=00, out equals data_in_0 << B.
    check_sel00_shift: assert property (
        @(posedge clk) ((B <= 4'd3) && (sel2 == 1'b0) && (sel1 == 1'b0)) |-> (out == (data_in_0 << B))
    );

    // For B<=3 and sel=01, out equals data_in_1 << B.
    check_sel01_shift: assert property (
        @(posedge clk) ((B <= 4'd3) && (sel2 == 1'b0) && (sel1 == 1'b1)) |-> (out == (data_in_1 << B))
    );

    // For B<=3 and sel=10, out equals data_in_2 << B.
    check_sel10_shift: assert property (
        @(posedge clk) ((B <= 4'd3) && (sel2 == 1'b1) && (sel1 == 1'b0)) |-> (out == (data_in_2 << B))
    );

    // For B<=3 and sel=11, out equals data_in_3 << B.
    check_sel11_shift: assert property (
        @(posedge clk) ((B <= 4'd3) && (sel2 == 1'b1) && (sel1 == 1'b1)) |-> (out == (data_in_3 << B))
    );

    // For B==0, out passes through the selected input.
    check_B0_passthrough: assert property (
        @(posedge clk) (B == 4'd0) |-> (out == ((sel2 == 1'b0) ? ((sel1 == 1'b0) ? data_in_0 : data_in_1)
                                                              : ((sel1 == 1'b0) ? data_in_2 : data_in_3)))
    );

    // For B==1, LSB of out is zero due to left shift.
    check_B1_zero_fill: assert property (
        @(posedge clk) (B == 4'd1) |-> (out[0] == 1'b0)
    );

    // For B==2, two LSBs of out are zero due to left shift.
    check_B2_zero_fill: assert property (
        @(posedge clk) (B == 4'd2) |-> (out[1:0] == 2'b00)
    );

    // For B==3, three LSBs of out are zero due to left shift.
    check_B3_zero_fill: assert property (
        @(posedge clk) (B == 4'd3) |-> (out[2:0] == 3'b000)
    );
endmodule

module up_down_counter_4bit_sva (
    input logic clk,
    input logic up_down,
    input logic load,
    input logic en,
    input logic [3:0] data_in,
    input logic [3:0] out
);

    // If en was 0 last cycle, out holds its value.
    hold_when_en_low: assert property (
        @(posedge clk) ($past(en) == 1'b0) |-> (out == $past(out))
    );

    // If en and load were 1 last cycle, out captures data_in.
    load_captures_data: assert property (
        @(posedge clk) ($past(en) && $past(load)) |-> (out == $past(data_in))
    );

    // If en=1, load=0, up_down=1 last cycle, out increments by 1 (mod 16).
    count_up_next_value: assert property (
        @(posedge clk) ($past(en) && !$past(load) && $past(up_down)) |-> (out == ($past(out) + 4'd1))
    );

    // If en=1, load=0, up_down=0 last cycle, out decrements by 1 (mod 16).
    count_down_next_value: assert property (
        @(posedge clk) ($past(en) && !$past(load) && !$past(up_down)) |-> (out == ($past(out) - 4'd1))
    );

    // When enabled last cycle, next out equals load data or +/-1 as selected.
    functional_update_when_enabled: assert property (
        @(posedge clk) $past(en) |-> (
            out == ( $past(load)
                     ? $past(data_in)
                     : ( $past(up_down) ? ($past(out) + 4'd1) : ($past(out) - 4'd1) )
                   )
        )
    );

    // Any change in out implies en was 1 in the prior cycle.
    change_implies_enabled: assert property (
        @(posedge clk) (out != $past(out)) |-> $past(en)
    );

    // When counting (enabled, no load), out always changes from prior value.
    counting_changes_value: assert property (
        @(posedge clk) ($past(en) && !$past(load)) |-> (out != $past(out))
    );

    // If out did not change, reason is en=0 or a load of the same value.
    stable_out_has_reason: assert property (
        @(posedge clk) (out == $past(out)) |-> (
            ($past(en) == 1'b0) ||
            ($past(en) && $past(load) && ($past(data_in) == $past(out)))
        )
    );

    // Count up from 4'hF wraps to 4'h0.
    wrap_on_increment_from_max: assert property (
        @(posedge clk) ($past(en) && !$past(load) && $past(up_down) && ($past(out) == 4'hF)) |-> (out == 4'h0)
    );

    // Count down from 4'h0 wraps to 4'hF.
    wrap_on_decrement_from_min: assert property (
        @(posedge clk) ($past(en) && !$past(load) && !$past(up_down) && ($past(out) == 4'h0)) |-> (out == 4'hF)
    );

endmodule

module synchronous_counter_sva (
    input logic clk,
    input logic reset,
    input logic enable,
    input logic control,
    input logic [3:0] count
);
    // Synchronous reset clears count to zero on the next cycle.
    reset_clears_next: assert property (
        @(posedge clk) reset |-> ##1 (count == 4'b0)
    );

    // While reset is held across cycles, count is zero.
    reset_holds_zero: assert property (
        @(posedge clk) (reset && $past(reset)) |-> (count == 4'b0)
    );

    // When enable is LOW, count holds its value on the next cycle.
    hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset) (!enable) |-> ##1 (count == $past(count))
    );

    // When enable and control are HIGH, count increments by 1 on the next cycle.
    inc_on_enable_control: assert property (
        @(posedge clk) disable iff (reset) (enable && control) |-> ##1 (count == $past(count) + 4'd1)
    );

    // When enable is HIGH and control is LOW, count decrements by 1 on the next cycle.
    dec_on_enable_ncontrol: assert property (
        @(posedge clk) disable iff (reset) (enable && !control) |-> ##1 (count == $past(count) - 4'd1)
    );

    // With enable HIGH, count must change on the next cycle.
    change_when_enable: assert property (
        @(posedge clk) disable iff (reset) enable |-> ##1 (count != $past(count))
    );

    // Any change (excluding prior reset) implies previous enable was HIGH.
    change_implies_prev_enable: assert property (
        @(posedge clk) disable iff (reset) (!$past(reset) && (count != $past(count))) |-> $past(enable)
    );

    // If count increased by 1 (excluding prior reset), previous enable && control were HIGH.
    inc_cause_requires_en_ctrl: assert property (
        @(posedge clk) disable iff (reset) (!$past(reset) && (count == $past(count) + 4'd1)) |-> ($past(enable) && $past(control))
    );

    // If count decreased by 1 (excluding prior reset), previous enable was HIGH and control LOW.
    dec_cause_requires_en_nctrl: assert property (
        @(posedge clk) disable iff (reset) (!$past(reset) && (count == $past(count) - 4'd1)) |-> ($past(enable) && !$past(control))
    );

    // Wrap-around on increment: 0xF + 1 -> 0x0 when enabled and control HIGH.
    wrap_inc_from_max: assert property (
        @(posedge clk) disable iff (reset) (enable && control && (count == 4'hF)) |-> ##1 (count == 4'h0)
    );

    // Wrap-around on decrement: 0x0 - 1 -> 0xF when enabled and control LOW.
    wrap_dec_from_zero: assert property (
        @(posedge clk) disable iff (reset) (enable && !control && (count == 4'h0)) |-> ##1 (count == 4'hF)
    );

    // LSB toggles whenever an update occurs (enable HIGH).
    lsb_toggles_when_enable: assert property (
        @(posedge clk) disable iff (reset) enable |-> ##1 (count[0] != $past(count[0]))
    );
endmodule

rtl:
module mux32to16(out , in1 , in2 ,control);

output [31:0] out;
input [31:0] in1,in2;
input control;

wire control_not;
wire [31:0] anded_out_1,anded_out_2;

not (control_not,control);


