sva:
module mux32to16_sva (
    input logic [31:0] out,
    input logic [31:0] in1,
    input logic [31:0] in2,
    input logic        control
);
    // When control goes HIGH, out must equal in2.
    select_in2_on_control_high: assert property (
        @(posedge control) out == in2
    );

    // When control goes LOW, out must equal in1.
    select_in1_on_control_low: assert property (
        @(negedge control) out == in1
    );

    // SOP equivalence at control HIGH: out = (~control & in1) | (control & in2).
    sop_equivalence_on_control_high: assert property (
        @(posedge control) out == (({32{~control}} & in1) | ({32{control}} & in2))
    );

    // SOP equivalence at control LOW: out = (~control & in1) | (control & in2).
    sop_equivalence_on_control_low: assert property (
        @(negedge control) out == (({32{~control}} & in1) | ({32{control}} & in2))
    );
endmodule

module dff_3input_sva (
    input logic clk,
    input logic reset,
    input logic set,
    input logic [2:0] data,
    input logic q
);

    // During active-low reset, q must be 0.
    check_reset_forces_zero: assert property (
        @(posedge clk) !reset |-> (q == 1'b0)
    );

    // If reset was low on the previous cycle, q must be 0 now.
    check_prev_reset_low_q_zero: assert property (
        @(posedge clk) $past(!reset) |-> (q == 1'b0)
    );

    // With reset high, set=1 drives q to 1 on the next cycle.
    check_set_forces_one_next: assert property (
        @(posedge clk) disable iff (!reset) set |=> (q == 1'b1)
    );

    // With reset high and set=0, q updates to data[2]&data[1]&data[0] on the next cycle.
    check_data_and_updates_next: assert property (
        @(posedge clk) disable iff (!reset) !set |=> (q == (data[2] & data[1] & data[0]))
    );

    // When the prior cycle was out of reset, q equals (set ? 1 : &data) from the prior cycle.
    check_next_state_equation: assert property (
        @(posedge clk) disable iff (!reset) $past(reset) |-> ( q == ( $past(set) ? 1'b1 : (& $past(data)) ) )
    );

    // If q is 1 now, last cycle must have been out of reset and (set==1 or data==3'b111).
    check_q_one_has_valid_cause: assert property (
        @(posedge clk) disable iff (!reset) (q == 1'b1) |-> ( $past(reset) && ( $past(set) || (& $past(data)) ) )
    );

    // If last cycle had reset high, set=0, and data did not all assert, q must be 0 now.
    check_q_zero_when_prev_inputs_zero: assert property (
        @(posedge clk) disable iff (!reset) ( $past(reset) && !$past(set) && !(& $past(data)) ) |-> (q == 1'b0)
    );

    // While reset is held low across cycles, q stays at 0 and is stable.
    check_q_stable_during_held_reset: assert property (
        @(posedge clk) (!reset && $past(!reset)) |-> (q == 1'b0 && $stable(q))
    );

endmodule

rtl:
module register_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input [7:0] d,    // 8-bit input for the register
    output reg [7:0] q // 8-bit output from the register
);

    always @(posedge clk) begin
        if (reset) begin
            q <= 8'h34; // Reset to 0x34
        end else begin
            q <= d;
        end
    end

endmodule

module counter_module (
    input clk,
    input reset,      // Synchronous active-high reset
    output reg [3:0] q // 4-bit output from the counter
);

    always @(posedge clk) begin
        if (reset) begin
            q <= 4'b0; // Reset to 0
        end else begin
            q <= q + 1;
        end
    end

endmodule

module adder_module (
    input [7:0] a,    // 8-bit input for the adder
    input [3:0] b,    // 4-bit input for the adder
    output [7:0] c    // 8-bit output from the adder
);

    assign c = a + b;

endmodule

module control_module (
    input select,     // Select input to choose between register and counter
    input [7:0] reg_output, // Output from the register module
    input [3:0] counter_output, // Output from the counter module
    output [7:0] active_output // Output from the active module
);

    wire [7:0] adder_input;
    wire [3:0] zero = 4'b0;

    adder_module adder_inst (
        .a(reg_output),
        .b(counter_output),
        .c(adder_input)
    );

    assign active_output = select ? adder_input : {zero, reg_output};

endmodule

module top_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input [7:0] d,    // 8-bit input for the register
    input select,     // Select input to choose between register and counter
    output [7:0] q    // 8-bit output from the active module
);

    wire [7:0] reg_output;
    wire [3:0] counter_output;
    wire [7:0] active_output;

    register_module register_inst (
        .clk(clk),
        .reset(reset),
        .d(d),
        .q(reg_output)
    );

    counter_module counter_inst (
        .clk(clk),
        .reset(reset),
        .q(counter_output)
    );

    control_module control_inst (
        .select(select),
        .reg_output(reg_output),
        .counter_output(counter_output),
        .active_output(active_output)
    );

    assign q = active_output;

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic reset,          // Synchronous active-high reset
    input logic [7:0] d,
    input logic select,
    input logic [7:0] q,
    // Internal observation points from the RTL hierarchy
    input logic [7:0] reg_output,
    input logic [3:0] counter_output,
    input logic [7:0] active_output,
    input logic [7:0] adder_input
);
    ///// register_module checks /////
    // After a cycle with reset asserted, register outputs 0x34.
    check_register_reset_value: assert property (
        @(posedge clk) $past(reset) |-> (reg_output == 8'h34)
    );
    // When not in reset on consecutive cycles, register captures previous d.
    check_register_captures_d: assert property (
        @(posedge clk) disable iff (reset) $past(!reset) |-> (reg_output == $past(d))
    );

    ///// counter_module checks /////
    // After a cycle with reset asserted, counter outputs 0.
    check_counter_reset_value: assert property (
        @(posedge clk) $past(reset) |-> (counter_output == 4'd0)
    );
    // When not in reset on consecutive cycles, counter increments by 1 (mod-16).
    check_counter_increments: assert property (
        @(posedge clk) disable iff (reset) $past(!reset) |-> (counter_output == $past(counter_output) + 4'd1)
    );

    ///// adder_module checks /////
    // Adder output equals reg_output plus zero-extended counter_output.
    check_adder_sum: assert property (
        @(posedge clk) disable iff (reset) adder_input == (reg_output + {4'b0, counter_output})
    );

    ///// control_module mux checks /////
    // When select=1, active_output comes from adder_input.
    check_mux_select1: assert property (
        @(posedge clk) disable iff (reset) (select) |-> (active_output == adder_input)
    );
    // When select=0, active_output passes reg_output (LSBs of {zero, reg_output}).
    check_mux_select0: assert property (
        @(posedge clk) disable iff (reset) (!select) |-> (active_output == reg_output)
    );

    ///// top_module connectivity checks /////
    // Top-level q follows active_output.
    check_q_follows_active_output: assert property (
        @(posedge clk) disable iff (reset) (q == active_output)
    );
    // When select=1, q equals reg_output plus zero-extended counter_output.
    check_q_select1_sum: assert property (
        @(posedge clk) disable iff (reset) (select) |-> (q == (reg_output + {4'b0, counter_output}))
    );
    // When select=0, q equals reg_output.
    check_q_select0_passthrough: assert property (
        @(posedge clk) disable iff (reset) (!select) |-> (q == reg_output)
    );
    // When select=0 and previous cycle not reset, q equals previous d.
    check_q_select0_matches_past_d: assert property (
        @(posedge clk) disable iff (reset) $past(!reset) && (!select) |-> (q == $past(d))
    );
endmodule

rtl:
module multifunction_module(
  input input_signal_1,
  input input_signal_2,
  input input_signal_3,
  input input_signal_4,
  input input_signal_5,
  output output_signal
);

  assign output_signal = ((input_signal_1 & ~input_signal_2) | (~input_signal_3 & input_signal_4) | (input_signal_5 ^ (input_signal_1 & input_signal_2 & input_signal_3 & input_signal_4)));

endmodule

sva:
module multifunction_module_sva (
  input  logic clk,
  input  logic input_signal_1,
  input  logic input_signal_2,
  input  logic input_signal_3,
  input  logic input_signal_4,
  input  logic input_signal_5,
  input  logic output_signal
);
  // Local aliases for readability
  logic t_abcd;
  logic t1, t2, t3;

  assign t_abcd = input_signal_1 & input_signal_2 & input_signal_3 & input_signal_4;
  assign t1     = input_signal_1 & ~input_signal_2;
  assign t2     = ~input_signal_3 & input_signal_4;
  assign t3     = input_signal_5 ^ t_abcd;

  // Output equals the defined Boolean function.
  check_output_function: assert property (
    @(posedge clk) output_signal == (t1 | t2 | t3)
  );

  // If (input_signal_1 & ~input_signal_2) is true, output must be HIGH.
  check_term1_implies_output_high: assert property (
    @(posedge clk) t1 |-> output_signal
  );

  // If (~input_signal_3 & input_signal_4) is true, output must be HIGH.
  check_term2_implies_output_high: assert property (
    @(posedge clk) t2 |-> output_signal
  );

  // If (input_signal_5 ^ (input_signal_1&2&3&4)) is true, output must be HIGH.
  check_xor_term_implies_output_high: assert property (
    @(posedge clk) t3 |-> output_signal
  );

  // If all three terms are LOW, output must be LOW.
  check_all_terms_low_implies_output_low: assert property (
    @(posedge clk) (!t1 && !t2 && !t3) |-> (output_signal == 1'b0)
  );

  // Output HIGH implies at least one term is HIGH.
  check_output_high_implies_some_term_high: assert property (
    @(posedge clk) output_signal |-> (t1 || t2 || t3)
  );

  // Output LOW implies all terms are LOW.
  check_output_low_implies_no_term_high: assert property (
    @(posedge clk) !output_signal |-> (!t1 && !t2 && !t3)
  );

  // When input_signal_1&2&3&4 is HIGH, output equals ~input_signal_5.
  check_abcd_high_implies_output_not_e: assert property (
    @(posedge clk) t_abcd |-> (output_signal == ~input_signal_5)
  );

  // When input_signal_1&2&3&4 is LOW and other terms are LOW, output equals input_signal_5.
  check_abcd_low_and_no_other_terms_implies_output_e: assert property (
    @(posedge clk) (!t_abcd && !t1 && !t2) |-> (output_signal == input_signal_5)
  );

  // When the first two terms are LOW, output equals (input_signal_5 ^ (input_signal_1&2&3&4)).
  check_only_xor_drives_when_other_terms_low: assert property (
    @(posedge clk) (!t1 && !t2) |-> (output_signal == (input_signal_5 ^ t_abcd))
  );

endmodule

rtl:
module priority_encoder (
  input [3:0] in,
  output reg [1:0] pos
);

  always @*
  begin
    case(in)
      4'b0001: pos = 0;
      4'b0010: pos = 1;
      4'b0100: pos = 2;
      4'b1000: pos = 3;
      default: pos = 0;
    endcase
  end

endmodule

sva:
module priority_encoder_sva (
    input logic clk,
    input logic [3:0] in,
    input logic [1:0] pos
);
    // 0001 maps to position 0.
    encode_in_0001_to_pos0: assert property (
        @(posedge clk) (in == 4'b0001) |-> (pos == 2'd0)
    );

    // 0010 maps to position 1.
    encode_in_0010_to_pos1: assert property (
        @(posedge clk) (in == 4'b0010) |-> (pos == 2'd1)
    );

    // 0100 maps to position 2.
    encode_in_0100_to_pos2: assert property (
        @(posedge clk) (in == 4'b0100) |-> (pos == 2'd2)
    );

    // 1000 maps to position 3.
    encode_in_1000_to_pos3: assert property (
        @(posedge clk) (in == 4'b1000) |-> (pos == 2'd3)
    );

    // Any non-listed input maps to 0 (default case).
    encode_default_to_pos0: assert property (
        @(posedge clk) (in != 4'b0001 && in != 4'b0010 && in != 4'b0100 && in != 4'b1000) |-> (pos == 2'd0)
    );

    // If pos is 1 then input must be 0010.
    reverse_pos1_implies_0010: assert property (
        @(posedge clk) (pos == 2'd1) |-> (in == 4'b0010)
    );

    // If pos is 2 then input must be 0100.
    reverse_pos2_implies_0100: assert property (
        @(posedge clk) (pos == 2'd2) |-> (in == 4'b0100)
    );

    // If pos is 3 then input must be 1000.
    reverse_pos3_implies_1000: assert property (
        @(posedge clk) (pos == 2'd3) |-> (in == 4'b1000)
    );

    // If pos is 0 then input cannot be 0010/0100/1000.
    reverse_pos0_excludes_1_2_3: assert property (
        @(posedge clk) (pos == 2'd0) |-> (in != 4'b0010 && in != 4'b0100 && in != 4'b1000)
    );
endmodule

rtl:
module rippleCounter(clk, rst_n, out);
    input clk, rst_n;
    output [3:0] out;

    reg [3:0] count;

    always @(posedge clk, negedge rst_n) begin
        if(!rst_n) begin
            count <= 4'b0;
        end else begin
            if(count == 4'b1111) begin
                count <= 4'b0;
            end else begin
                count <= count + 1;
            end
        end
    end

    assign out = count;

endmodule

sva:
module rippleCounter_sva (
    input logic clk,
    input logic rst_n,
    input logic [3:0] out
);

    ///// Reset behavior /////
    // While reset is asserted, out is 0 at each clock.
    check_reset_zero: assert property (
        @(posedge clk) (!rst_n |-> (out == 4'd0))
    );

    ///// Counting behavior /////
    // When running and previous out != 15, out increments by 1.
    check_increment_no_wrap: assert property (
        @(posedge clk) disable iff (!rst_n)
            ($past(rst_n) && ($past(out) != 4'd15)) |-> (out == $past(out) + 4'd1)
    );

    // When running and previous out == 15, out wraps to 0.
    check_wrap_15_to_0: assert property (
        @(posedge clk) disable iff (!rst_n)
            ($past(rst_n) && ($past(out) == 4'd15)) |-> (out == 4'd0)
    );

    // When running, out changes every cycle (no hold).
    check_out_changes_each_cycle: assert property (
        @(posedge clk) disable iff (!rst_n)
            $past(rst_n) |-> (out != $past(out))
    );

    // When out of reset for 16 consecutive cycles, state repeats every 16.
    check_periodicity_16: assert property (
        @(posedge clk) disable iff (!rst_n)
            ( rst_n && $past(rst_n,1) && $past(rst_n,2) && $past(rst_n,3) && $past(rst_n,4)
              && $past(rst_n,5) && $past(rst_n,6) && $past(rst_n,7) && $past(rst_n,8)
              && $past(rst_n,9) && $past(rst_n,10) && $past(rst_n,11) && $past(rst_n,12)
              && $past(rst_n,13) && $past(rst_n,14) && $past(rst_n,15) ) |-> (out == $past(out,16))
    );

    ///// Reset edge effects /////
    // One cycle after a reset assertion, out is 0.
    check_zero_next_after_reset_assert: assert property (
        @(posedge clk) $fell(rst_n) |=> (out == 4'd0)
    );

    // On the clock where reset deasserts, out is still 0.
    check_zero_at_reset_release_edge: assert property (
        @(posedge clk) disable iff (!rst_n)
            $rose(rst_n) |-> (out == 4'd0)
    );

    // One cycle after reset deasserts, out becomes 1.
    check_one_after_reset_release: assert property (
        @(posedge clk) disable iff (!rst_n)
            $rose(rst_n) |=> (out == 4'd1)
    );

    ///// Additional invariants /////
    // When running, out == 0 only if previous out was 15.
    check_zero_only_after_wrap: assert property (
        @(posedge clk) disable iff (!rst_n)
            ($past(rst_n) && (out == 4'd0)) |-> ($past(out) == 4'd15)
    );

    // When running, LSB toggles every cycle.
    check_lsb_toggles: assert property (
        @(posedge clk) disable iff (!rst_n)
            $past(rst_n) |-> (out[0] == ~$past(out[0]))
    );

endmodule

rtl:
module top_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input [7:0] d,
    output [7:0] q,
    output [7:0] anyedge_or_d
);

    // Define internal wires and signals
    wire [7:0] q_ff;
    wire [7:0] q_t;
    wire [7:0] anyedge;
    wire [7:0] or_result;

    // Instantiate the D flip-flop module
    dff_module dff_inst (
        .clk(clk),
        .reset(reset),
        .d(d),
        .q(q_ff)
    );

    // Instantiate the any edge detection module
    anyedge_module anyedge_inst (
        .clk(clk),
        .reset(reset),
        .d(q_ff),
        .q(anyedge)
    );

    // Implement the T flip-flops for the D flip-flop module
    assign q_t[0] = q_ff[0] ^ d[0];
    assign q_t[1] = q_ff[1] ^ d[1];
    assign q_t[2] = q_ff[2] ^ d[2];
    assign q_t[3] = q_ff[3] ^ d[3];
    assign q_t[4] = q_ff[4] ^ d[4];
    assign q_t[5] = q_ff[5] ^ d[5];
    assign q_t[6] = q_ff[6] ^ d[6];
    assign q_t[7] = q_ff[7] ^ d[7];

    // Instantiate the OR gate module
    or_gate_module or_gate_inst (
        .a(q_t),
        .b(anyedge),
        .c(or_result)
    );

    // Assign the output signals
    assign q = q_ff;
    assign anyedge_or_d = or_result;

endmodule

// Define the D flip-flop module
module dff_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input [7:0] d,
    output reg [7:0] q
);

    always @(negedge clk) begin
        if (reset) begin
            q <= 8'b0;
        end else begin
            q <= d;
        end
    end

endmodule

// Define the any edge detection module
module anyedge_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input [7:0] d,
    output reg [7:0] q
);

    reg [7:0] d_ff;

    always @(posedge clk) begin
        if (reset) begin
            d_ff <= 8'b0;
            q <= 8'b0;
        end else begin
            d_ff <= d;
            q <= d ^ d_ff;
        end
    end

endmodule

// Define the OR gate module
module or_gate_module (
    input [7:0] a,
    input [7:0] b,
    output reg [7:0] c
);

    always @(a or b) begin
        c <= a | b;
    end

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic reset,      // Synchronous active-high reset
    input logic [7:0] d,
    input logic [7:0] q,
    input logic [7:0] anyedge_or_d
);

    ///// dff_module (negedge clock) /////
    // When not in reset now and previously, q equals prior-cycle d at each negedge.
    dff_loads_d_on_negedge: assert property (
        @(negedge clk) disable iff (reset) (!$past(reset)) |-> (q == $past(d))
    );

    // If reset was asserted on the previous negedge, q must now be 0.
    dff_prev_reset_drives_zero: assert property (
        @(negedge clk) $past(reset) |-> (q == 8'h00)
    );

    // If reset is asserted on this negedge, q will be 0 by the next negedge.
    dff_reset_now_zero_next: assert property (
        @(negedge clk) reset |=> (q == 8'h00)
    );

    ///// anyedge_module + or_gate_module observed at posedge /////
    // OR output equals (q ^ d) OR (q toggled between the last two posedges).
    or_exact_decomposition: assert property (
        @(posedge clk) disable iff (reset) anyedge_or_d == ((q ^ d) | ($past(q) ^ $past(q,2)))
    );

    // OR output must include all 1s from (q ^ d).
    or_includes_q_xor_d: assert property (
        @(posedge clk) disable iff (reset) (((q ^ d) & ~anyedge_or_d) == 8'h00)
    );

    // OR output must include bits that toggled in q between the last two posedges.
    or_includes_prev_q_toggle: assert property (
        @(posedge clk) disable iff (reset) ((($past(q) ^ $past(q,2)) & ~anyedge_or_d) == 8'h00)
    );

    // If (q ^ d) is zero, OR output equals the previous-cycle anyedge term.
    or_reduces_to_prev_anyedge_when_qeqd: assert property (
        @(posedge clk) disable iff (reset) ((q ^ d) == 8'h00) |-> (anyedge_or_d == ($past(q) ^ $past(q,2)))
    );

    // If neither source contributes (q==d and no prior q toggle), OR output is zero.
    or_zero_when_no_sources: assert property (
        @(posedge clk) disable iff (reset) ((q == d) && ($past(q) == $past(q,2))) |-> (anyedge_or_d == 8'h00)
    );

    // After a posedge with reset asserted, next posedge OR output equals (q ^ d) (anyedge term cleared).
    or_after_reset_reduces_to_q_xor_d: assert property (
        @(posedge clk) reset |=> (anyedge_or_d == (q ^ d))
    );

endmodule

