module feedforward_mux_4to1_sel2_32_1 #(
parameter
    ID                = 0,
    NUM_STAGE         = 1,
    din1_WIDTH       = 32,
    din2_WIDTH       = 32,
    din3_WIDTH       = 32,
    din4_WIDTH       = 32,
    din5_WIDTH         = 32,
    dout_WIDTH            = 32
)(
    input  [31 : 0]     din1,
    input  [31 : 0]     din2,
    input  [31 : 0]     din3,
    input  [31 : 0]     din4,
    input  [1 : 0]    din5,
    output [31 : 0]   dout);

wire [1 : 0]     sel;
wire [31 : 0]         mux_1_0;
wire [31 : 0]         mux_1_1;
wire [31 : 0]         mux_2_0;

assign sel = din5;

assign mux_1_0 = (sel[0] == 0)? din1 : din2;
assign mux_1_1 = (sel[0] == 0)? din3 : din4;

assign mux_2_0 = (sel[1] == 0)? mux_1_0 : mux_1_1;

assign dout = mux_2_0;

endmodule

sva:
module feedforward_mux_4to1_sel2_32_1_sva (
    input logic [31:0] din1,
    input logic [31:0] din2,
    input logic [31:0] din3,
    input logic [31:0] din4,
    input logic [1:0]  din5,
    input logic [31:0] dout
);

    ///// Functional mapping /////
    // Direct functional equivalence to the ternary expression.
    check_mux_function: assert property (
        @($global_clock) dout == (din5[1] ? (din5[0] ? din4 : din3) : (din5[0] ? din2 : din1))
    );

    // When din5 == 2'b00, dout equals din1.
    check_sel00_maps_din1: assert property (
        @($global_clock) (din5 == 2'b00) |-> (dout == din1)
    );

    // When din5 == 2'b01, dout equals din2.
    check_sel01_maps_din2: assert property (
        @($global_clock) (din5 == 2'b01) |-> (dout == din2)
    );

    // When din5 == 2'b10, dout equals din3.
    check_sel10_maps_din3: assert property (
        @($global_clock) (din5 == 2'b10) |-> (dout == din3)
    );

    // When din5 == 2'b11, dout equals din4.
    check_sel11_maps_din4: assert property (
        @($global_clock) (din5 == 2'b11) |-> (dout == din4)
    );

    ///// Independence/stability /////
    // If sel[1]==0 and sel,din1,din2 are stable, dout is stable (din3/din4 do not affect).
    check_unselected_pair_no_effect_sel1_is0: assert property (
        @($global_clock) (din5[1] == 1'b0 && $stable(din5) && $stable(din1) && $stable(din2)) |-> $stable(dout)
    );

    // If sel[1]==1 and sel,din3,din4 are stable, dout is stable (din1/din2 do not affect).
    check_unselected_pair_no_effect_sel1_is1: assert property (
        @($global_clock) (din5[1] == 1'b1 && $stable(din5) && $stable(din3) && $stable(din4)) |-> $stable(dout)
    );

    // If sel[0]==0 and sel,din1,din3 are stable, dout is stable (din2/din4 do not affect).
    check_unselected_with_sel0_is0: assert property (
        @($global_clock) (din5[0] == 1'b0 && $stable(din5) && $stable(din1) && $stable(din3)) |-> $stable(dout)
    );

    // If sel[0]==1 and sel,din2,din4 are stable, dout is stable (din1/din3 do not affect).
    check_unselected_with_sel0_is1: assert property (
        @($global_clock) (din5[0] == 1'b1 && $stable(din5) && $stable(din2) && $stable(din4)) |-> $stable(dout)
    );

    // If all inputs are stable, dout remains stable (purely combinational behavior).
    check_quiescent_stability: assert property (
        @($global_clock) $stable({din1,din2,din3,din4,din5}) |-> $stable(dout)
    );

endmodule

module shift_register_sva (
    input logic [3:0] DATA_IN,
    input logic       LOAD,
    input logic       CLK,
    input logic [3:0] DATA_OUT
);

    // Next-state equals load (prev) or rotate-left-1 (prev) of DATA_OUT.
    check_next_state_rule: assert property (
        @(posedge CLK)
            DATA_OUT == ( $past(LOAD)
                          ? $past(DATA_IN)
                          : { $past(DATA_OUT[2:0]), $past(DATA_OUT[3]) } )
    );

    // If LOAD was 1 in the previous cycle, DATA_OUT captures previous DATA_IN.
    check_load_captures_data: assert property (
        @(posedge CLK)
            $past(LOAD) |-> (DATA_OUT == $past(DATA_IN))
    );

    // If LOAD was 0 in the previous cycle, DATA_OUT rotates left by 1.
    check_rotate_when_no_load: assert property (
        @(posedge CLK)
            $past(!LOAD) |-> (DATA_OUT == { $past(DATA_OUT[2:0]), $past(DATA_OUT[3]) })
    );

    // Rotate mapping for bit3 when not loading: new[3] = old[2].
    check_rotate_bit3: assert property (
        @(posedge CLK)
            $past(!LOAD) |-> (DATA_OUT[3] == $past(DATA_OUT[2]))
    );

    // Rotate mapping for bit2 when not loading: new[2] = old[1].
    check_rotate_bit2: assert property (
        @(posedge CLK)
            $past(!LOAD) |-> (DATA_OUT[2] == $past(DATA_OUT[1]))
    );

    // Rotate mapping for bit1 when not loading: new[1] = old[0].
    check_rotate_bit1: assert property (
        @(posedge CLK)
            $past(!LOAD) |-> (DATA_OUT[1] == $past(DATA_OUT[0]))
    );

    // Rotate mapping for bit0 when not loading: new[0] = old[3].
    check_rotate_bit0: assert property (
        @(posedge CLK)
            $past(!LOAD) |-> (DATA_OUT[0] == $past(DATA_OUT[3]))
    );

    // Four consecutive rotates (no LOAD for 4 cycles) return to the original value.
    check_four_rotate_identity: assert property (
        @(posedge CLK)
            $past(!LOAD,1) && $past(!LOAD,2) && $past(!LOAD,3) && $past(!LOAD,4)
            |-> (DATA_OUT == $past(DATA_OUT,4))
    );

endmodule

rtl:
module alu (
    input [31:0] a,
    input [31:0] b,
    input [3:0] ctrl,
    output [31:0] result,
    output carry_out,
    output zero
);

reg [31:0] temp_result;
reg carry_out_reg;
reg zero_reg;

always @(*) begin
    case(ctrl)
        4'b0000: temp_result = a + b; // addition
        4'b0001: temp_result = a - b; // subtraction
        4'b0010: temp_result = a & b; // bitwise AND
        4'b0011: temp_result = a | b; // bitwise OR
        4'b0100: temp_result = a ^ b; // bitwise XOR
        4'b0101: temp_result = a << b[4:0]; // shift left
        4'b0110: temp_result = a >> b[4:0]; // shift right
        default: temp_result = 0; // default to 0
    endcase

    if(ctrl == 4'b0000 || ctrl == 4'b0001) begin
        carry_out_reg = (temp_result[31] == 1);
    end else begin
        carry_out_reg = 0;
    end

    if(temp_result == 0) begin
        zero_reg = 1;
    end else begin
        zero_reg = 0;
    end
end

assign result = temp_result;
assign carry_out = carry_out_reg;
assign zero = zero_reg;

endmodule

sva:
module alu_sva (
    input logic [31:0] a,
    input logic [31:0] b,
    input logic [3:0]  ctrl,
    input logic [31:0] result,
    input logic        carry_out,
    input logic        zero
);
    // Combinational ALU with no clock/reset; assertions are clocked on $global_clock.

    // Addition result when ctrl==0000.
    check_add_result: assert property (
        @(posedge $global_clock) (ctrl == 4'b0000) |-> (result == (a + b))
    );

    // Subtraction result when ctrl==0001.
    check_sub_result: assert property (
        @(posedge $global_clock) (ctrl == 4'b0001) |-> (result == (a - b))
    );

    // Bitwise AND result when ctrl==0010.
    check_and_result: assert property (
        @(posedge $global_clock) (ctrl == 4'b0010) |-> (result == (a & b))
    );

    // Bitwise OR result when ctrl==0011.
    check_or_result: assert property (
        @(posedge $global_clock) (ctrl == 4'b0011) |-> (result == (a | b))
    );

    // Bitwise XOR result when ctrl==0100.
    check_xor_result: assert property (
        @(posedge $global_clock) (ctrl == 4'b0100) |-> (result == (a ^ b))
    );

    // Logical shift left by b[4:0] when ctrl==0101.
    check_sll_result: assert property (
        @(posedge $global_clock) (ctrl == 4'b0101) |-> (result == (a << b[4:0]))
    );

    // Logical shift right by b[4:0] when ctrl==0110.
    check_srl_result: assert property (
        @(posedge $global_clock) (ctrl == 4'b0110) |-> (result == (a >> b[4:0]))
    );

    // Default case drives result to zero for all other ctrl values.
    check_default_zero_result: assert property (
        @(posedge $global_clock) (!(ctrl inside {4'b0000,4'b0001,4'b0010,4'b0011,4'b0100,4'b0101,4'b0110})) |-> (result == 32'd0)
    );

    // carry_out equals MSB of result for add/sub.
    check_carry_for_add_sub: assert property (
        @(posedge $global_clock) ((ctrl == 4'b0000) || (ctrl == 4'b0001)) |-> (carry_out == (result[31] == 1'b1))
    );

    // carry_out is zero for non add/sub operations.
    check_carry_zero_for_others: assert property (
        @(posedge $global_clock) (!(ctrl inside {4'b0000,4'b0001})) |-> (carry_out == 1'b0)
    );

    // zero flag is 1 iff result is zero.
    check_zero_flag_true_when_result_zero: assert property (
        @(posedge $global_clock) (result == 32'd0) |-> (zero == 1'b1)
    );

    // zero flag is 0 iff result is nonzero.
    check_zero_flag_false_when_result_nonzero: assert property (
        @(posedge $global_clock) (result != 32'd0) |-> (zero == 1'b0)
    );

endmodule

