    check_invert_on_te_rise: assert property (
        @(posedge TE) (TE == 1'b1) |-> (Z === ~A)
    );

    // When TE is HIGH, Z equals ~A on A rising edges.
    check_invert_on_a_rise_when_enabled: assert property (
