module and4 (
  input A,
  input B,
  input C,
  input D,
  output Y
);

  wire w1, w2;

  and (w1, A, B, C);
  and (w2, w1, D);
  assign Y = w2;

endmodule

sva:
module and4_sva (
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic Y
);
    // Pure combinational AND of A,B,C,D to Y; sample on $global_clock.

    // When all signals are known, Y equals A&B&C&D.
    check_y_functional_when_known: assert property (
        @(posedge $global_clock) (!$isunknown({A,B,C,D,Y})) |-> (Y == (A & B & C & D))
    );

    // If Y is HIGH, then all inputs are HIGH.
    check_y_high_implies_inputs_high: assert property (
        @(posedge $global_clock) (Y == 1'b1) |-> (A && B && C && D)
    );

    // If all inputs are HIGH, Y is HIGH.
    check_inputs_high_implies_y_high: assert property (
        @(posedge $global_clock) (A && B && C && D) |-> (Y == 1'b1)
    );

    // A LOW forces Y LOW.
    check_zero_dominance_A: assert property (
        @(posedge $global_clock) (A == 1'b0) |-> (Y == 1'b0)
    );

    // B LOW forces Y LOW.
    check_zero_dominance_B: assert property (
        @(posedge $global_clock) (B == 1'b0) |-> (Y == 1'b0)
    );

    // C LOW forces Y LOW.
    check_zero_dominance_C: assert property (
        @(posedge $global_clock) (C == 1'b0) |-> (Y == 1'b0)
    );

    // D LOW forces Y LOW.
    check_zero_dominance_D: assert property (
        @(posedge $global_clock) (D == 1'b0) |-> (Y == 1'b0)
    );

    // Y only changes when at least one input changes.
    check_y_changes_only_on_input_change: assert property (
        @(posedge $global_clock) $changed(Y) |-> ($changed(A) || $changed(B) || $changed(C) || $changed(D))
    );

    // Y rising edge implies all inputs are HIGH.
    check_y_rise_requires_all_ones: assert property (
        @(posedge $global_clock) $rose(Y) |-> (A && B && C && D)
    );

    // Y falling edge implies at least one input is LOW.
    check_y_fall_requires_any_zero: assert property (
        @(posedge $global_clock) $fell(Y) |-> (!A || !B || !C || !D)
    );
endmodule

module sky130_fd_sc_hs__counter_sva (
    input logic clk,
    input logic rst,
    input logic enable,
    input logic load,
    input logic [31:0] count_max,
    input logic [31:0] count
);
    // On load, next count equals previous count_max.
    check_load_sets_count_to_max: assert property (
        @(posedge clk) disable iff (rst)
            load |=> (count == $past(count_max))
    );

    // Load has priority over enable when both are high.
    check_load_overrides_enable: assert property (
        @(posedge clk) disable iff (rst)
            (load && enable) |=> (count == $past(count_max))
    );

    // When enabled without load, next count either wraps to 0 at max or increments by 1.
    check_enable_behavior: assert property (
        @(posedge clk) disable iff (rst)
            (!load && enable) |=> (
                (($past(count) == $past(count_max)) && (count == '0)) ||
                (($past(count) != $past(count_max)) && (count == $past(count) + 1))
            )
    );

    // When idle (no load and not enabled), count holds its value.
    check_hold_when_idle: assert property (
        @(posedge clk) disable iff (rst)
            (!load && !enable) |=> (count == $past(count))
    );

    // When enabled and not at max (and no load), count increments by 1.
    check_enable_increments_nonmax: assert property (
        @(posedge clk) disable iff (rst)
            (!load && enable && (count != count_max)) |=> (count == $past(count) + 1)
    );

    // When enabled and at max (and no load), count wraps to 0.
    check_enable_wraps_at_max: assert property (
        @(posedge clk) disable iff (rst)
            (!load && enable && (count == count_max)) |=> (count == '0)
    );
endmodule

