module simple_arithmetic_unit_sva (
    input logic [3:0] a,
    input logic [3:0] b,
    input logic [1:0] op_select,
    input logic [3:0] result,
    input logic       carry_borrow
);
    // When op_select=00, outputs equal 5-bit addition of a and b.
    check_add_operation: assert property (
        @($global_clock) (op_select == 2'b00) |-> ({carry_borrow, result} == (a + b))
    );

    // When op_select=01, outputs equal 5-bit subtraction of a and b.
    check_sub_operation: assert property (
        @($global_clock) (op_select == 2'b01) |-> ({carry_borrow, result} == (a - b))
    );

    // For subtraction, borrow flag is 1 iff a < b.
    check_sub_borrow_flag: assert property (
        @($global_clock) (op_select == 2'b01) |-> (carry_borrow == (a < b))
    );

    // When op_select=10, result is a & b and carry_borrow is 0.
    check_and_operation: assert property (
        @($global_clock) (op_select == 2'b10) |-> (result == (a & b)) && (carry_borrow == 1'b0)
    );

    // When op_select=11 (default), outputs are zero.
    check_default_outputs: assert property (
        @($global_clock) (op_select == 2'b11) |-> (result == 4'b0000) && (carry_borrow == 1'b0)
    );

    // Outputs remain unchanged if inputs a, b, and op_select are unchanged.
    check_outputs_stable_when_inputs_stable: assert property (
        @($global_clock) ($stable(a) && $stable(b) && $stable(op_select)) |-> $stable({carry_borrow, result})
    );

    // For subtraction, equal operands yield zero result and no borrow.
    check_sub_equal_operands_zero_result: assert property (
        @($global_clock) (op_select == 2'b01 && a == b) |-> (result == 4'b0000) && (carry_borrow == 1'b0)
    );

    // For AND, if either operand is zero, result is zero.
    check_and_zero_operand_zero_result: assert property (
        @($global_clock) (op_select == 2'b10 && ((a == 4'b0000) || (b == 4'b0000))) |-> (result == 4'b0000)
    );

    // For AND, result has no bits set outside those set in a and b.
    check_and_result_subset_inputs: assert property (
        @($global_clock) (op_select == 2'b10) |-> (((result & ~a) == 4'b0000) && ((result & ~b) == 4'b0000))
    );
endmodule

rtl:
module nor_gate (
    input a, b,
    output out
);
    assign out = ~(a | b);
endmodule

module mux_2to1 (
    input a, b, sel,
    output out
);
    wire nor_a, nor_b, nor_sel;

    nor_gate nor1 (.a(a), .b(sel), .out(nor_a));
    nor_gate nor2 (.a(b), .b(~sel), .out(nor_b));
    nor_gate nor3 (.a(nor_a), .b(nor_b), .out(out));
endmodule

module subtractor (
    input [1:0] in,
    output [1:0] diff
);
    wire [1:0] sub_const = 2'b01;

    assign diff = in - sub_const;
endmodule

module top_module (
    input a, b,
    input sel,
    output [1:0] diff
);
    wire mux_out;

    mux_2to1 mux (.a(a), .b(b), .sel(sel), .out(mux_out));
    subtractor sub (.in({1'b0, mux_out}), .diff(diff));
endmodule

sva:
module top_module_sva (
    input logic CLK,
    input logic a,
    input logic b,
    input logic sel,
    input logic [1:0] diff
);
    // diff bits must be equal.
    check_diff_bits_equal: assert property (
        @(posedge CLK) (diff[1] == diff[0])
    );

    // diff can only be 2'b00 or 2'b11.
    check_diff_limited_values: assert property (
        @(posedge CLK) (diff inside {2'b00, 2'b11})
    );

    // Functional equivalence: diff == {2{~(sel ? b : a)}}.
    check_diff_functional_equiv: assert property (
        @(posedge CLK) (diff == {2{~(sel ? b : a)}})
    );

    // When sel=0, diff depends only on a.
    check_when_sel0: assert property (
        @(posedge CLK) (sel == 1'b0) |-> (diff == {2{~a}})
    );

    // When sel=1, diff depends only on b.
    check_when_sel1: assert property (
        @(posedge CLK) (sel == 1'b1) |-> (diff == {2{~b}})
    );

    // If inputs a,b,sel are stable, diff is stable.
    check_stable_when_inputs_stable: assert property (
        @(posedge CLK) $stable({a,b,sel}) |-> $stable(diff)
    );

    // With sel=0, if only a changes, diff changes.
    check_selected_a_change_affects_diff: assert property (
        @(posedge CLK) (sel==1'b0 && $stable(sel) && $stable(b) && $changed(a)) |-> $changed(diff)
    );

    // With sel=1, if only b changes, diff changes.
    check_selected_b_change_affects_diff: assert property (
        @(posedge CLK) (sel==1'b1 && $stable(sel) && $stable(a) && $changed(b)) |-> $changed(diff)
    );

    // With sel=0, if only b changes, diff is stable.
    check_unselected_b_change_no_effect: assert property (
        @(posedge CLK) (sel==1'b0 && $stable(sel) && $stable(a) && $changed(b)) |-> $stable(diff)
    );

    // With sel=1, if only a changes, diff is stable.
    check_unselected_a_change_no_effect: assert property (
        @(posedge CLK) (sel==1'b1 && $stable(sel) && $stable(b) && $changed(a)) |-> $stable(diff)
    );
endmodule

rtl:
module FrequencyCounter(
    input clk,
    input freqin,
    output [23:0] frequency
    );

parameter        SecondCount    =    8001800;          reg    [23:0]    counter        =    0;                reg    [23:0]    freq           =    0;                reg    [23:0]    secondcounter  =    0;                reg              stopin         =    0;                reg              inreseted      =    0;                always @(posedge clk)    
begin
        if(secondcounter == SecondCount)
        begin
            secondcounter     <= 0;
            stopin             <= 1;
            freq                 <=    counter*2;
        end
        else 
            if(~stopin)
                secondcounter <= secondcounter + 1;

        if(inreseted)
            stopin <= 0;
end

always @(negedge freqin)
begin
        if(~stopin)
        begin
            counter    <=    counter + 1;
            inreseted <= 0;
        end
        else
        begin
            counter <= 0;
            inreseted <= 1;
        end
end

assign frequency = freq;

endmodule

sva:
module FrequencyCounter_sva (
    input logic clk,
    input logic freqin,
    input logic [23:0] frequency,

    // Internal DUT signals (bind these from the instance)
    input logic [23:0] counter,
    input logic [23:0] freq,
    input logic [23:0] secondcounter,
    input logic stopin,
    input logic inreseted
);
    // Mirror of DUT parameter
    localparam logic [23:0] SECONDCOUNT = 24'd8001800;

    ///// Output mapping /////
    // Output port mirrors internal freq register.
    check_frequency_tied_to_internal: assert property (
        @(posedge clk) frequency == freq
    );

    ///// Window hit behavior /////
    // When secondcounter hits SECONDCOUNT, it resets to 0 on that update.
    check_secondcounter_resets_on_hit: assert property (
        @(posedge clk) (secondcounter == SECONDCOUNT) |=> (secondcounter == 24'd0)
    );
    // On hit, freq captures 2*counter from that cycle.
    check_freq_updates_on_hit: assert property (
        @(posedge clk) (secondcounter == SECONDCOUNT) |=> (freq == ($past(counter) << 1))
    );
    // On hit with inreseted LOW, stopin becomes 1.
    check_stopin_set_on_hit_no_inreseted: assert property (
        @(posedge clk) (secondcounter == SECONDCOUNT && !inreseted) |=> (stopin == 1'b1)
    );

    ///// Stop control /////
    // inreseted HIGH forces stopin LOW on next cycle.
    check_stopin_clears_when_inreseted: assert property (
        @(posedge clk) inreseted |=> (stopin == 1'b0)
    );
    // stopin can only deassert when prior inreseted was HIGH.
    check_stopin_only_deasserts_when_inreseted: assert property (
        @(posedge clk) $fell(stopin) |-> $past(inreseted)
    );
    // stopin can only assert when prior hit occurred and inreseted was LOW.
    check_stopin_only_asserts_on_hit_without_inreseted: assert property (
        @(posedge clk) $rose(stopin) |-> ($past(secondcounter) == SECONDCOUNT && !$past(inreseted))
    );

    ///// secondcounter progression /////
    // While not hit and stopin LOW, secondcounter increments by 1.
    check_secondcounter_increments_when_active: assert property (
        @(posedge clk) (secondcounter != SECONDCOUNT && !stopin) |=> (secondcounter == $past(secondcounter) + 24'd1)
    );
    // While not hit and stopin HIGH, secondcounter holds.
    check_secondcounter_holds_when_stopped: assert property (
        @(posedge clk) (secondcounter != SECONDCOUNT && stopin) |=> (secondcounter == $past(secondcounter))
    );

    ///// freq update qualification /////
    // freq changes only on cycles following a hit.
    check_freq_changes_only_on_hit: assert property (
        @(posedge clk) $changed(freq) |-> ($past(secondcounter) == SECONDCOUNT)
    );

    ///// freqin edge effects (sampled on clk) /////
    // Without a freqin falling edge in the interval, counter holds.
    check_counter_stable_without_fall: assert property (
        @(posedge clk) !$fell(freqin) |-> (counter == $past(counter))
    );
    // A freqin fall while counting increments counter by at least 1 by this sample.
    check_counter_increments_on_fall_while_counting: assert property (
        @(posedge clk) ($fell(freqin) && ($past(stopin) == 1'b0)) |-> (counter >= $past(counter) + 24'd1)
    );
    // A freqin fall while stopped resets counter to 0 and sets inreseted.
    check_counter_reset_and_inreseted_set_on_fall_while_stopped: assert property (
        @(posedge clk) ($fell(freqin) && ($past(stopin) == 1'b1)) |-> (counter == 24'd0 && inreseted == 1'b1)
    );
    // A freqin fall while counting clears inreseted to 0.
    check_inreseted_cleared_on_fall_while_counting: assert property (
        @(posedge clk) ($fell(freqin) && ($past(stopin) == 1'b0)) |-> (inreseted == 1'b0)
    );

endmodule

