    // For A,B,Cin=011 => Sum=0, Cout=1.
    check_tt_011: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge Cin or negedge Cin)
            ((A===1'b0) && (B===1'b1) && (Cin===1'b1)) |-> ((Sum===1'b0) && (Cout===1'b1))
