module sky130_fd_sc_hvl__o22a (
    X ,
    A1,
    A2,
    B1,
    B2
);

    output X ;
    input  A1;
    input  A2;
    input  B1;
    input  B2;

    wire or0_out   ;
    wire or1_out   ;
    wire and0_out_X;

    or  or0  (or0_out   , A2, A1          );
    or  or1  (or1_out   , B2, B1          );
    and and0 (and0_out_X, or0_out, or1_out);
    buf buf0 (X         , and0_out_X      );

endmodule

sva:
module sky130_fd_sc_hvl__o22a_sva (
    input logic clk,
    input logic X,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic B2,
    input logic or0_out,
    input logic or1_out,
    input logic and0_out_X
);
    // or0_out implements A1 OR A2.
    check_or0_definition: assert property (
        @(posedge clk) or0_out == (A1 | A2)
    );

    // or1_out implements B1 OR B2.
    check_or1_definition: assert property (
        @(posedge clk) or1_out == (B1 | B2)
    );

    // and0_out_X implements or0_out AND or1_out.
    check_and0_definition: assert property (
        @(posedge clk) and0_out_X == (or0_out & or1_out)
    );

    // X buffers and0_out_X.
    check_buf_definition: assert property (
        @(posedge clk) X == and0_out_X
    );

    // X equals (A1 OR A2) AND (B1 OR B2).
    check_function_equivalence: assert property (
        @(posedge clk) X == ((A1 | A2) & (B1 | B2))
    );

    // If both A1 and A2 are LOW, X must be LOW.
    check_A_group_zero_forces_X_zero: assert property (
        @(posedge clk) (~A1 & ~A2) |-> (X == 1'b0)
    );

    // If both B1 and B2 are LOW, X must be LOW.
    check_B_group_zero_forces_X_zero: assert property (
        @(posedge clk) (~B1 & ~B2) |-> (X == 1'b0)
    );

    // If X is HIGH, at least one of A1/A2 is HIGH.
    check_X_high_implies_A_group_high: assert property (
        @(posedge clk) (X == 1'b1) |-> (A1 | A2)
    );

    // If X is HIGH, at least one of B1/B2 is HIGH.
    check_X_high_implies_B_group_high: assert property (
        @(posedge clk) (X == 1'b1) |-> (B1 | B2)
    );

    // If A1 and B1 are HIGH, X must be HIGH.
    check_A1_and_B1_suffices_for_X_high: assert property (
        @(posedge clk) (A1 & B1) |-> (X == 1'b1)
    );
endmodule

rtl:
module bool_func (
  input x,
  input y,
  input z,
  output f
);

  wire x_or_y = x | y;
  wire x_xor_z = x ^ z;

  assign f = x_or_y & x_xor_z;

endmodule

sva:
module bool_func_sva (
    // DUT ports
    input logic x,
    input logic y,
    input logic z,
    input logic f,
    // Sampling clock for assertions (DUT has no clock/reset)
    input logic clk
);
    // Analysis: DUT is purely combinational; no clock/reset; f = (x|y) & (x^z).
    // Local mirrors of DUT's internal wires for readability
    wire x_or_y  = x | y;
    wire x_xor_z = x ^ z;

    // f must equal (x|y) & (x^z)
    check_functional_equation: assert property (
        @(posedge clk) f == (x_or_y & x_xor_z)
    );

    // If x == z, then f must be 0 (since x^z == 0)
    check_zero_when_x_eq_z: assert property (
        @(posedge clk) (x == z) |-> (f == 1'b0)
    );

    // If x|y == 0, then f must be 0
    check_zero_when_or_zero: assert property (
        @(posedge clk) (x_or_y == 1'b0) |-> (f == 1'b0)
    );

    // If x^z == 0, then f must be 0
    check_zero_when_xor_zero: assert property (
        @(posedge clk) (x_xor_z == 1'b0) |-> (f == 1'b0)
    );

    // If both terms are 1, f must be 1
    check_one_when_terms_one: assert property (
        @(posedge clk) (x_xor_z && x_or_y) |-> (f == 1'b1)
    );

    // When x=0 and z=1, f equals y
    check_passthrough_y_when_x0z1: assert property (
        @(posedge clk) ((x == 1'b0) && (z == 1'b1)) |-> (f == y)
    );

    // When x=1 and z=0, f is 1 regardless of y
    check_one_when_x1z0: assert property (
        @(posedge clk) ((x == 1'b1) && (z == 1'b0)) |-> (f == 1'b1)
    );

    // When x=0 and z=0, f is 0
    check_zero_when_x0z0: assert property (
        @(posedge clk) ((x == 1'b0) && (z == 1'b0)) |-> (f == 1'b0)
    );

    // When x=1 and z=1, f is 0
    check_zero_when_x1z1: assert property (
        @(posedge clk) ((x == 1'b1) && (z == 1'b1)) |-> (f == 1'b0)
    );

    // When x=0 and y=0, f is 0
    check_zero_when_x0y0: assert property (
        @(posedge clk) ((x == 1'b0) && (y == 1'b0)) |-> (f == 1'b0)
    );
endmodule

rtl:
module key_gen(
    clk,
    reset,
    p2k_valid,
    p2k_ingress,
    p2k_rloc_src,
    p2k_eid_dst,
    p2k_metadata,
    mode,
    k2m_metadata_valid,
    k2m_metadata
);

input clk;
input reset;
input p2k_valid;
input [7:0] p2k_ingress;
input [127:0] p2k_rloc_src;
input [127:0] p2k_eid_dst;
input [7:0] p2k_metadata;
input mode;
output k2m_metadata_valid;
output [107:0] k2m_metadata;

reg k2m_metadata_valid;
reg [107:0] k2m_metadata;

always @ (posedge clk or negedge reset) begin
    if (!reset) begin
        k2m_metadata_valid <= 1'b0;
        k2m_metadata <= 108'b0;
    end
    else begin
        if (p2k_valid == 1'b1) begin
            if (mode == 1'b1) begin
                if (p2k_ingress == 8'b0) begin
                    k2m_metadata <= {mode, p2k_ingress, p2k_rloc_src[17:0], 81'b0};
                end
                else begin
                    k2m_metadata <= {mode, p2k_ingress, 18'b0, 81'b0};
                end
                k2m_metadata_valid <= 1'b1;
            end
            else begin
                k2m_metadata_valid <= 1'b1;
                k2m_metadata <= {mode, p2k_ingress, p2k_eid_dst[127:56], 56'b0};
            end
        end
        else begin
            k2m_metadata_valid <= 1'b0;
        end
    end
end

endmodule

sva:
module key_gen_sva (
    input logic clk,
    input logic reset,
    input logic p2k_valid,
    input logic [7:0] p2k_ingress,
    input logic [127:0] p2k_rloc_src,
    input logic [127:0] p2k_eid_dst,
    input logic [7:0] p2k_metadata,
    input logic mode,
    input logic k2m_metadata_valid,
    input logic [107:0] k2m_metadata
);
    // During active-low reset, outputs are driven to zero.
    reset_outputs_zero: assert property (
        @(posedge clk) !reset |-> (k2m_metadata_valid == 1'b0) && (k2m_metadata == 108'b0)
    );

    // When p2k_valid is HIGH, k2m_metadata_valid is HIGH next cycle.
    valid_next_high_when_p2k_valid: assert property (
        @(posedge clk) disable iff (!reset) (p2k_valid == 1'b1) |=> (k2m_metadata_valid == 1'b1)
    );

    // When p2k_valid is LOW, k2m_metadata_valid is LOW next cycle.
    valid_next_low_when_no_p2k_valid: assert property (
        @(posedge clk) disable iff (!reset) (p2k_valid == 1'b0) |=> (k2m_metadata_valid == 1'b0)
    );

    // On p2k_valid & mode & ingress==0, metadata captures mode, ingress, rloc[17:0], zeros.
    metadata_mode1_ingress0_content: assert property (
        @(posedge clk) disable iff (!reset)
            (p2k_valid && (mode == 1'b1) && (p2k_ingress == 8'b0)) |=> 
            (k2m_metadata_valid == 1'b1) &&
            (k2m_metadata == {mode, p2k_ingress, p2k_rloc_src[17:0], 81'b0})
    );

    // On p2k_valid & mode & ingress!=0, metadata captures mode, ingress, zeros, zeros.
    metadata_mode1_ingressnz_content: assert property (
        @(posedge clk) disable iff (!reset)
            (p2k_valid && (mode == 1'b1) && (p2k_ingress != 8'b0)) |=> 
            (k2m_metadata_valid == 1'b1) &&
            (k2m_metadata == {mode, p2k_ingress, 18'b0, 81'b0})
    );

    // On p2k_valid & !mode, metadata equals truncated {mode,ingress,eid[127:56],56'b0}.
    metadata_mode0_truncated_eid: assert property (
        @(posedge clk) disable iff (!reset)
            (p2k_valid && (mode == 1'b0)) |=> 
            (k2m_metadata_valid == 1'b1) &&
            (k2m_metadata == {p2k_eid_dst[107:56], 56'b0})
    );

    // When p2k_valid is LOW, metadata holds its previous value.
    metadata_holds_when_no_valid: assert property (
        @(posedge clk) disable iff (!reset)
            (p2k_valid == 1'b0) |=> (k2m_metadata == $past(k2m_metadata))
    );

    // For mode==1 updates, low 81 bits of metadata are zero next cycle.
    mode1_low81_zero: assert property (
        @(posedge clk) disable iff (!reset)
            (p2k_valid && (mode == 1'b1)) |=> (k2m_metadata[80:0] == 81'b0)
    );

    // For mode==1 updates, ingress is reflected in bits [106:99] next cycle.
    mode1_carries_ingress_bits: assert property (
        @(posedge clk) disable iff (!reset)
            (p2k_valid && (mode == 1'b1)) |=> (k2m_metadata[106:99] == p2k_ingress)
    );

    // For mode==0 updates, low 56 bits of metadata are zero next cycle.
    mode0_low56_zero: assert property (
        @(posedge clk) disable iff (!reset)
            (p2k_valid && (mode == 1'b0)) |=> (k2m_metadata[55:0] == 56'b0)
    );
endmodule

