module and_or_gate (
    input A,
    input B,
    input C,
    input D,
    output F1,
    output F2
);

wire and1, and2, or1;

assign and1 = A & B;
assign and2 = C & D;
assign or1 = A | B;

assign F1 = and1 & and2;
assign F2 = or1 | and2;

endmodule

sva:
module and_or_gate_sva (
    input logic CLK,
    input logic RESETn,
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic F1,
    input logic F2,
    input logic and1,
    input logic and2,
    input logic or1
);
    // and1 must equal A & B.
    check_and1_definition: assert property (
        @(posedge CLK) disable iff (!RESETn) and1 == (A & B)
    );

    // and2 must equal C & D.
    check_and2_definition: assert property (
        @(posedge CLK) disable iff (!RESETn) and2 == (C & D)
    );

    // or1 must equal A | B.
    check_or1_definition: assert property (
        @(posedge CLK) disable iff (!RESETn) or1 == (A | B)
    );

    // F1 must equal and1 & and2.
    check_F1_from_internals: assert property (
        @(posedge CLK) disable iff (!RESETn) F1 == (and1 & and2)
    );

    // F2 must equal or1 | and2.
    check_F2_from_internals: assert property (
        @(posedge CLK) disable iff (!RESETn) F2 == (or1 | and2)
    );

    // F1 must equal A & B & C & D.
    check_F1_from_inputs: assert property (
        @(posedge CLK) disable iff (!RESETn) F1 == (A & B & C & D)
    );

    // F2 must equal (A | B) | (C & D).
    check_F2_from_inputs: assert property (
        @(posedge CLK) disable iff (!RESETn) F2 == ((A | B) | (C & D))
    );

    // If F1 is HIGH then and1 must be HIGH.
    check_F1_implies_and1: assert property (
        @(posedge CLK) disable iff (!RESETn) F1 |-> (and1 == 1'b1)
    );

    // If F1 is HIGH then and2 must be HIGH.
    check_F1_implies_and2: assert property (
        @(posedge CLK) disable iff (!RESETn) F1 |-> (and2 == 1'b1)
    );

    // If and2 is HIGH then F2 must be HIGH.
    check_and2_implies_F2: assert property (
        @(posedge CLK) disable iff (!RESETn) and2 |-> (F2 == 1'b1)
    );
endmodule

rtl:
module binary_counter(
  input clk,
  input reset,
  output reg [3:0] count
);

  always @(posedge clk) begin
    if (reset) begin
      count <= 4'h0;
    end else begin
      count <= count + 1;
    end
  end

endmodule

sva:
module binary_counter_sva (
  input logic clk,
  input logic reset,
  input logic [3:0] count
);
  // Clock: clk (posedge). Reset: reset (synchronous, active-high). Sequential 4-bit up-counter with wrap.

  // Reset high causes count to be 0 on the next clock.
  reset_clears_next: assert property (
    @(posedge clk) reset |=> (count == 4'h0)
  );

  // If reset is held high across consecutive clocks, count is 0.
  reset_held_outputs_zero: assert property (
    @(posedge clk) ($past(reset) && reset) |-> (count == 4'h0)
  );

  // When not in reset for two consecutive clocks, count increments by 1.
  count_increments_when_running: assert property (
    @(posedge clk) disable iff (reset) $past(!reset) |-> (count == $past(count) + 4'd1)
  );

  // When running (no reset in consecutive clocks), count must change.
  count_changes_when_running: assert property (
    @(posedge clk) disable iff (reset) $past(!reset) |-> (count != $past(count))
  );

  // Wrap from 4'hF to 4'h0 on next clock when running.
  wrap_from_f_to_0: assert property (
    @(posedge clk) disable iff (reset) ($past(!reset) && ($past(count) == 4'hF)) |-> (count == 4'h0)
  );

  // On reset deassertion edge, count is 0 in that same cycle.
  deassertion_outputs_zero: assert property (
    @(posedge clk) $fell(reset) |-> (count == 4'h0)
  );

endmodule

rtl:
module sky130_fd_sc_lp__a41oi (
    Y ,
    A1,
    A2,
    A3,
    A4,
    B1
);

    output Y ;
    input  A1;
    input  A2;
    input  A3;
    input  A4;
    input  B1;

    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    wire and0_out  ;
    wire nor0_out_Y;

    and and0 (and0_out  , A1, A2, A3, A4 );
    nor nor0 (nor0_out_Y, B1, and0_out   );
    buf buf0 (Y         , nor0_out_Y     );

endmodule

sva:
module sky130_fd_sc_lp__a41oi_sva (
    input logic Y,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic A4,
    input logic B1
);
    // Combinational cell: Y = ~(B1 | (A1&A2&A3&A4)); no clock/reset present.

    // Y matches NOR of B1 and the 4-input AND.
    check_function_equivalence: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge A3 or negedge A3 or posedge A4 or negedge A4 or posedge B1 or negedge B1)
        Y == ~(B1 | (A1 & A2 & A3 & A4))
    );

    // If B1 is HIGH, Y must be LOW (same cycle).
    check_B1_high_forces_Y_low: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge A3 or negedge A3 or posedge A4 or negedge A4 or posedge B1 or negedge B1)
        (B1 == 1'b1) |=> (Y == 1'b0)
    );

    // If all A inputs are HIGH, Y must be LOW (same cycle).
    check_allA_high_forces_Y_low: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge A3 or negedge A3 or posedge A4 or negedge A4 or posedge B1 or negedge B1)
        ((A1 & A2 & A3 & A4) == 1'b1) |=> (Y == 1'b0)
    );

    // If B1 is LOW and not all A are HIGH, Y must be HIGH (same cycle).
    check_B1_low_and_notAllA_drives_Y_high: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge A3 or negedge A3 or posedge A4 or negedge A4 or posedge B1 or negedge B1)
        ((B1 == 1'b0) && !(A1 & A2 & A3 & A4)) |=> (Y == 1'b1)
    );

    // Y HIGH implies B1 is LOW and not all A are HIGH (same cycle).
    check_Y_high_implies_inputs: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge A3 or negedge A3 or posedge A4 or negedge A4 or posedge B1 or negedge B1)
        (Y == 1'b1) |=> ((B1 == 1'b0) && !(A1 & A2 & A3 & A4))
    );

    // Y LOW implies B1 is HIGH or all A are HIGH (same cycle).
    check_Y_low_implies_inputs: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge A3 or negedge A3 or posedge A4 or negedge A4 or posedge B1 or negedge B1)
        (Y == 1'b0) |=> ((B1 == 1'b1) || (A1 & A2 & A3 & A4))
    );

    // If inputs are stable between samples, Y must also be stable.
    check_stability: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge A3 or negedge A3 or posedge A4 or negedge A4 or posedge B1 or negedge B1)
        $stable({A1, A2, A3, A4, B1}) |=> $stable(Y)
    );

    // On B1 rising edge, Y must be LOW (same cycle).
    check_Y_on_B1_rise: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge A3 or negedge A3 or posedge A4 or negedge A4 or posedge B1 or negedge B1)
        $rose(B1) |=> (Y == 1'b0)
    );

    // On B1 falling edge, Y must equal ~(A1&A2&A3&A4) (same cycle).
    check_Y_on_B1_fall: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge A3 or negedge A3 or posedge A4 or negedge A4 or posedge B1 or negedge B1)
        $fell(B1) |=> (Y == ~(A1 & A2 & A3 & A4))
    );

    // When all A rise to 1, Y must be LOW (same cycle).
    check_Y_on_allA_rise: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge A3 or negedge A3 or posedge A4 or negedge A4 or posedge B1 or negedge B1)
        $rose(A1 & A2 & A3 & A4) |=> (Y == 1'b0)
    );
endmodule

rtl:
module uparc_fwdu(
    rs,
    rs_data,
    rt,
    rt_data,
    rd_p2,
    rd_data_p2,
    pend_mem_load_p2,
    rd_p3,
    rd_data_p3,
    rs_data_p1,
    rt_data_p1
);

input wire [4:0] rs;
input wire [31:0] rs_data;
input wire [4:0] rt;
input wire [31:0] rt_data;

input wire [4:0] rd_p2;
input wire [31:0] rd_data_p2;

input wire pend_mem_load_p2;

input wire [4:0] rd_p3;
input wire [31:0] rd_data_p3;

output reg [31:0] rs_data_p1;
output reg [31:0] rt_data_p1;

always @(*) begin
    if (rs == rd_p2) begin
        rs_data_p1 = rd_data_p2;
    end else if (rs == rd_p3) begin
        rs_data_p1 = rd_data_p3;
    end else begin
        rs_data_p1 = rs_data;
    end
end

always @(*) begin
    if (rt == rd_p2 && !pend_mem_load_p2) begin
        rt_data_p1 = rd_data_p2;
    end else if (rt == rd_p3) begin
        rt_data_p1 = rd_data_p3;
    end else begin
        rt_data_p1 = rt_data;
    end
end

endmodule

sva:
module uparc_fwdu_sva (
    input logic [4:0] rs,
    input logic [31:0] rs_data,
    input logic [4:0] rt,
    input logic [31:0] rt_data,
    input logic [4:0] rd_p2,
    input logic [31:0] rd_data_p2,
    input logic pend_mem_load_p2,
    input logic [4:0] rd_p3,
    input logic [31:0] rd_data_p3,
    input logic [31:0] rs_data_p1,
    input logic [31:0] rt_data_p1
);
    // rs forwards from P2 when rs matches rd_p2.
    check_rs_from_p2: assert property (
        @(posedge $global_clock) (rs == rd_p2) |-> (rs_data_p1 == rd_data_p2)
    );

    // rs forwards from P3 when no P2 match and rs matches rd_p3.
    check_rs_from_p3: assert property (
        @(posedge $global_clock) (rs != rd_p2) && (rs == rd_p3) |-> (rs_data_p1 == rd_data_p3)
    );

    // rs takes register file data when no match with P2 or P3.
    check_rs_from_regfile: assert property (
        @(posedge $global_clock) (rs != rd_p2) && (rs != rd_p3) |-> (rs_data_p1 == rs_data)
    );

    // rt forwards from P2 when rt matches rd_p2 and no pending load.
    check_rt_from_p2_when_no_load: assert property (
        @(posedge $global_clock) (rt == rd_p2) && (!pend_mem_load_p2) |-> (rt_data_p1 == rd_data_p2)
    );

    // rt forwards from P3 when P2 path not taken and rt matches rd_p3.
    check_rt_from_p3_when_p2_blocked: assert property (
        @(posedge $global_clock) (rt == rd_p3) && (pend_mem_load_p2 || (rt != rd_p2)) |-> (rt_data_p1 == rd_data_p3)
    );

    // rt takes register file data when P2 path not taken and no P3 match.
    check_rt_from_regfile: assert property (
        @(posedge $global_clock) ((rt != rd_p2) || pend_mem_load_p2) && (rt != rd_p3) |-> (rt_data_p1 == rt_data)
    );

    // When both rt matches and load is pending, P3 has priority.
    check_rt_both_match_load_selects_p3: assert property (
        @(posedge $global_clock) (rt == rd_p2) && (rt == rd_p3) && pend_mem_load_p2 |-> (rt_data_p1 == rd_data_p3)
    );

    // When both rt matches and no load is pending, P2 has priority.
    check_rt_both_match_no_load_selects_p2: assert property (
        @(posedge $global_clock) (rt == rd_p2) && (rt == rd_p3) && !pend_mem_load_p2 |-> (rt_data_p1 == rd_data_p2)
    );
endmodule

