module sky130_fd_sc_lp__o311a (
    X ,
    A1,
    A2,
    A3,
    B1,
    C1
);

    output X ;
    input  A1;
    input  A2;
    input  A3;
    input  B1;
    input  C1;

    wire or0_out   ;
    wire and0_out_X;

    or  or0  (or0_out   , A2, A1, A3     );
    and and0 (and0_out_X, or0_out, B1, C1);
    buf buf0 (X         , and0_out_X     );

endmodule

sva:
module sky130_fd_sc_lp__o311a_sva (
    input logic clk,
    input logic X,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic B1,
    input logic C1
);
    // DUT has no clock/reset; combinational. Sample on clk; no reset gating (disable iff 1'b0). X = (A1|A2|A3)&B1&C1.

    // X implements the exact Boolean equation.
    check_function_equivalence: assert property (
        @(posedge clk) disable iff (1'b0) X == ((A1 | A2 | A3) & B1 & C1)
    );

    // B1 low forces X low.
    check_b1_low_forces_x0: assert property (
        @(posedge clk) disable iff (1'b0) (!B1) |-> (!X)
    );

    // C1 low forces X low.
    check_c1_low_forces_x0: assert property (
        @(posedge clk) disable iff (1'b0) (!C1) |-> (!X)
    );

    // All A inputs low force X low.
    check_all_a_low_forces_x0: assert property (
        @(posedge clk) disable iff (1'b0) (!A1 && !A2 && !A3) |-> (!X)
    );

    // B1 and C1 high with any A high drives X high.
    check_gate_true_drives_x1: assert property (
        @(posedge clk) disable iff (1'b0) (B1 && C1 && (A1 || A2 || A3)) |-> X
    );

    // X high implies B1 and C1 high and at least one A high.
    check_x_high_implies_inputs: assert property (
        @(posedge clk) disable iff (1'b0) X |-> (B1 && C1 && (A1 || A2 || A3))
    );

    // Rising X requires B1 and C1 high and at least one A high.
    check_x_rise_requires_conditions: assert property (
        @(posedge clk) disable iff (1'b0) $rose(X) |-> (B1 && C1 && (A1 || A2 || A3))
    );

    // Falling X implies some required input condition is false.
    check_x_fall_implies_blocking_input: assert property (
        @(posedge clk) disable iff (1'b0) $fell(X) |-> ((!B1) || (!C1) || (!A1 && !A2 && !A3))
    );

    // If all inputs are stable across a cycle, X must be stable.
    check_stable_inputs_hold_output: assert property (
        @(posedge clk) disable iff (1'b0) ($stable(A1) && $stable(A2) && $stable(A3) && $stable(B1) && $stable(C1)) |-> $stable(X)
    );
endmodule

module mux3to1_sva (
    input logic clk,
    input logic [1:0] sel,
    input logic in0,
    input logic in1,
    input logic in2,
    input logic out
);

    // sel==0 routes in0 to out.
    check_sel0_routes_in0: assert property (
        @(posedge clk) disable iff (1'b0) (sel == 2'd0) |-> (out == in0)
    );

    // sel==1 routes in1 to out.
    check_sel1_routes_in1: assert property (
        @(posedge clk) disable iff (1'b0) (sel == 2'd1) |-> (out == in1)
    );

    // sel==2 routes in2 to out.
    check_sel2_routes_in2: assert property (
        @(posedge clk) disable iff (1'b0) (sel == 2'd2) |-> (out == in2)
    );

    // sel==3 drives out low (default branch).
    check_sel3_routes_zero: assert property (
        @(posedge clk) disable iff (1'b0) (sel == 2'd3) |-> (out == 1'b0)
    );

    // If sel and selected source are stable, out remains stable.
    check_stable_out_when_sel_and_source_stable: assert property (
        @(posedge clk) disable iff (1'b0)
        ($stable(sel) && ((sel==2'd0 && $stable(in0)) ||
                          (sel==2'd1 && $stable(in1)) ||
                          (sel==2'd2 && $stable(in2)) ||
                          (sel==2'd3)))
        |-> $stable(out)
    );

    // If out is LOW, then either the selected input is LOW or sel==3.
    check_out_zero_implies_selected_zero_or_default: assert property (
        @(posedge clk) disable iff (1'b0)
        (out == 1'b0) |-> ((sel==2'd0 && in0==1'b0) ||
                           (sel==2'd1 && in1==1'b0) ||
                           (sel==2'd2 && in2==1'b0) ||
                           (sel==2'd3))
    );

    // If out is HIGH, then the selected input is HIGH (sel cannot be 3).
    check_out_one_implies_selected_one: assert property (
        @(posedge clk) disable iff (1'b0)
        (out == 1'b1) |-> ((sel==2'd0 && in0==1'b1) ||
                           (sel==2'd1 && in1==1'b1) ||
                           (sel==2'd2 && in2==1'b1))
    );

endmodule

rtl:
`define DIV_WITDH 9

module clock_divider(
iCLK,
iRST_n,
oCLK_OUT,
);

input iCLK;
input iRST_n;
output oCLK_OUT;

reg [`DIV_WITDH-1:0] clk_cnt;


always@(posedge iCLK or negedge iRST_n)	
	begin	
		if (!iRST_n)
			clk_cnt <= 0;
		else	
			clk_cnt <= clk_cnt + 1;
	end

assign oCLK_OUT = clk_cnt[`DIV_WITDH-1];


endmodule

sva:
module clock_divider_sva (
    input logic iCLK,
    input logic iRST_n,
    input logic oCLK_OUT
);

    ///// Reset behavior /////
    // While reset is asserted, oCLK_OUT must be 0.
    reset_holds_output_low: assert property (
        @(posedge iCLK) (!iRST_n) |-> (oCLK_OUT == 1'b0)
    );

    // On the cycle reset is asserted (falling edge), oCLK_OUT must be 0.
    reset_fall_clears_output: assert property (
        @(posedge iCLK) $fell(iRST_n) |-> (oCLK_OUT == 1'b0)
    );

    // On the first active clock after reset deasserts, oCLK_OUT remains 0.
    post_reset_first_cycle_low: assert property (
        @(posedge iCLK) disable iff (!iRST_n) $rose(iRST_n) |-> (oCLK_OUT == 1'b0)
    );

    ///// Output well-formedness /////
    // Out of reset, oCLK_OUT must never be X/Z.
    check_output_known_when_active: assert property (
        @(posedge iCLK) disable iff (!iRST_n) !$isunknown(oCLK_OUT)
    );

    // Any change of oCLK_OUT can only occur when not in reset now and in the previous cycle.
    change_only_out_of_reset: assert property (
        @(posedge iCLK) $changed(oCLK_OUT) |-> (iRST_n && $past(iRST_n))
    );

    ///// Toggle pacing /////
    // oCLK_OUT cannot toggle on two consecutive cycles.
    no_back_to_back_toggles: assert property (
        @(posedge iCLK) disable iff (!iRST_n) $changed(oCLK_OUT) |-> ##1 !$changed(oCLK_OUT)
    );

    // After a rising edge, oCLK_OUT stays HIGH for at least one full cycle.
    min_high_pulse_width_1cycle: assert property (
        @(posedge iCLK) disable iff (!iRST_n) $rose(oCLK_OUT) |-> ##1 (oCLK_OUT == 1'b1)
    );

    // After a falling edge, oCLK_OUT stays LOW for at least one full cycle.
    min_low_pulse_width_1cycle: assert property (
        @(posedge iCLK) disable iff (!iRST_n) $fell(oCLK_OUT) |-> ##1 (oCLK_OUT == 1'b0)
    );

endmodule

rtl:
module shift_register(input clk, reset, data, output reg [2:0] q);

    always @(posedge clk) begin
        if (reset) begin
            q <= 3'b0;
        end else begin
            q <= {q[1:0], data};
        end
    end

endmodule

sva:
module shift_register_sva (
    input logic clk,
    input logic reset,   // active-high synchronous reset
    input logic data,
    input logic [2:0] q
);

    // Reset drives q to zero on the active clock edge.
    reset_clears_q: assert property (
        @(posedge clk) reset |-> (q == 3'b000)
    );

    // When not in reset, q updates to {previous q[1:0], previous data}.
    shift_vector_update: assert property (
        @(posedge clk) disable iff (reset) q == { $past(q[1:0]), $past(data) }
    );

    // When not in reset, q[0] captures previous data.
    shift_bit0_captures_data: assert property (
        @(posedge clk) disable iff (reset) q[0] == $past(data)
    );

    // When not in reset, q[1] shifts in from previous q[0].
    shift_bit1_from_q0: assert property (
        @(posedge clk) disable iff (reset) q[1] == $past(q[0])
    );

    // When not in reset, q[2] shifts in from previous q[1].
    shift_bit2_from_q1: assert property (
        @(posedge clk) disable iff (reset) q[2] == $past(q[1])
    );

    // On reset deassertion edge, q follows the shift rule from the prior state.
    first_cycle_after_reset: assert property (
        @(posedge clk) $fell(reset) |-> (q == { $past(q[1:0]), $past(data) })
    );

endmodule

