module simple_counter_sva (
  input logic clk,
  input logic rst_n,
  input logic en,
  input logic [3:0] count
);
  // Clock: clk; Reset: rst_n active-low, synchronous
  // Sequential counter: increments on clk when en=1; holds when en=0; wraps 15->0

  // During reset, count is 0.
  reset_value: assert property (
    @(posedge clk) !rst_n |-> (count == 4'b0000)
  );

  // When en=0 (no reset), count holds its value.
  hold_when_en_low: assert property (
    @(posedge clk) disable iff (!rst_n) (!en) |-> $stable(count)
  );

  // When en=1 (no reset), count updates by +1 with wrap at 15->0.
  update_on_en_high: assert property (
    @(posedge clk) disable iff (!rst_n)
      en |-> (count == (($past(count) == 4'hf) ? 4'h0 : ($past(count) + 1'b1)))
  );

  // Any change to count (no reset) requires en=1.
  change_requires_en: assert property (
    @(posedge clk) disable iff (!rst_n) (!$stable(count)) |-> en
  );

  // When en=1 (no reset), the value must change.
  update_changes_value: assert property (
    @(posedge clk) disable iff (!rst_n) en |-> (count != $past(count))
  );

  // If en=1 and the new value is 0 (no reset), the previous value was 15.
  wrap_from_15_only: assert property (
    @(posedge clk) disable iff (!rst_n) (en && (count == 4'h0)) |-> ($past(count) == 4'hf)
  );

  // On the cycle reset is asserted, count is driven to 0.
  sync_reset_effect: assert property (
    @(posedge clk) $fell(rst_n) |-> (count == 4'h0)
  );
endmodule

module nova_io_pio_dummy_sva (
    input logic        pclk,
    input logic        bs_rst,     // Active-low async reset
    input logic        bs_stb,
    input logic        bs_we,
    input logic [7:0]  bs_adr,
    input logic [15:0] bs_din,
    input logic [15:0] bs_dout,
    input logic        r_DONE,
    input logic        r_BUSY
);
    parameter logic [5:0] device_addr = 6'b000000;

    // During reset, flags and bs_dout drive known values.
    reset_known_values: assert property (
        @(posedge pclk) !bs_rst |-> (r_DONE == 1'b1) && (r_BUSY == 1'b0) && (bs_dout == {1'b0, 1'b1, 14'h0000})
    );

    // bs_dout must reflect r_BUSY and r_DONE with lower 14 bits zero.
    dout_reflects_flags: assert property (
        @(posedge pclk) disable iff (!bs_rst) (bs_dout == {r_BUSY, r_DONE, 14'h0000})
    );

    // Write to group 00 with cmd 01 drives DONE=0, BUSY=1 on next cycle.
    write_cmd01_sets_busy: assert property (
        @(posedge pclk) disable iff (!bs_rst)
            (bs_stb && (bs_adr[5:0] == device_addr) && bs_we && (bs_adr[7:6] == 2'b00) && (bs_din[15:14] == 2'b01))
            |=> (r_DONE == 1'b0) && (r_BUSY == 1'b1)
    );

    // Write to group 00 with cmd 10 drives DONE=0, BUSY=0 on next cycle.
    write_cmd10_clears_busy_and_done: assert property (
        @(posedge pclk) disable iff (!bs_rst)
            (bs_stb && (bs_adr[5:0] == device_addr) && bs_we && (bs_adr[7:6] == 2'b00) && (bs_din[15:14] == 2'b10))
            |=> (r_DONE == 1'b0) && (r_BUSY == 1'b0)
    );

    // Write to group 00 with cmd 11 does not change flags.
    write_cmd11_no_change: assert property (
        @(posedge pclk) disable iff (!bs_rst)
            (bs_stb && (bs_adr[5:0] == device_addr) && bs_we && (bs_adr[7:6] == 2'b00) && (bs_din[15:14] == 2'b11))
            |=> (r_DONE == $past(r_DONE)) && (r_BUSY == $past(r_BUSY))
    );

    // Write to group 00 with cmd 00 does not change flags.
    write_cmd00_no_change: assert property (
        @(posedge pclk) disable iff (!bs_rst)
            (bs_stb && (bs_adr[5:0] == device_addr) && bs_we && (bs_adr[7:6] == 2'b00) && (bs_din[15:14] == 2'b00))
            |=> (r_DONE == $past(r_DONE)) && (r_BUSY == $past(r_BUSY))
    );

    // Writes to groups 01/10/11 do not change flags.
    write_group_non00_no_change: assert property (
        @(posedge pclk) disable iff (!bs_rst)
            (bs_stb && (bs_adr[5:0] == device_addr) && bs_we && (bs_adr[7:6] != 2'b00))
            |=> (r_DONE == $past(r_DONE)) && (r_BUSY == $past(r_BUSY))
    );

    // Reads (any group) do not change flags.
    read_access_no_change: assert property (
        @(posedge pclk) disable iff (!bs_rst)
            (bs_stb && (bs_adr[5:0] == device_addr) && !bs_we)
            |=> (r_DONE == $past(r_DONE)) && (r_BUSY == $past(r_BUSY))
    );

    // Non-targeted accesses do not change flags.
    non_target_access_no_change: assert property (
        @(posedge pclk) disable iff (!bs_rst)
            (bs_stb && (bs_adr[5:0] != device_addr))
            |=> (r_DONE == $past(r_DONE)) && (r_BUSY == $past(r_BUSY))
    );

    // BUSY implies DONE is low.
    busy_implies_done_low: assert property (
        @(posedge pclk) disable iff (!bs_rst) r_BUSY |-> (r_DONE == 1'b0)
    );

endmodule

module counter_sva (
  input logic clk,
  input logic rst,
  input logic dir,
  input logic [7:0] count
);

  // While reset is asserted, count must be 0.
  check_reset_forces_zero: assert property (
    @(posedge clk) rst |-> (count == 8'd0)
  );

  // When dir=1 and count is not 255, next count increments by 1.
  check_up_increments_when_not_max: assert property (
    @(posedge clk) disable iff (rst) (dir && (count != 8'd255)) |=> (count == $past(count) + 8'd1)
  );

  // When dir=1 and count is 255, next count wraps to 0.
  check_up_wraps_at_255: assert property (
    @(posedge clk) disable iff (rst) (dir && (count == 8'd255)) |=> (count == 8'd0)
  );

  // When dir=0 and count is not 0, next count decrements by 1.
  check_down_decrements_when_not_min: assert property (
    @(posedge clk) disable iff (rst) (!dir && (count != 8'd0)) |=> (count == $past(count) - 8'd1)
  );

  // When dir=0 and count is 0, next count wraps to 255.
  check_down_wraps_at_0: assert property (
    @(posedge clk) disable iff (rst) (!dir && (count == 8'd0)) |=> (count == 8'd255)
  );

  // Out of reset, count changes every cycle.
  check_count_changes_each_cycle: assert property (
    @(posedge clk) disable iff (rst) 1'b1 |=> (count != $past(count))
  );

  // Out of reset, LSB toggles every cycle (±1 update).
  check_lsb_toggles_each_cycle: assert property (
    @(posedge clk) disable iff (rst) 1'b1 |=> (count[0] != $past(count[0]))
  );

  // Full next-state equation for dir=1 (increment with wrap at 255).
  check_up_next_state_equation: assert property (
    @(posedge clk) disable iff (rst) dir |-> (count == (($past(count) == 8'd255) ? 8'd0 : ($past(count) + 8'd1)))
  );

  // Full next-state equation for dir=0 (decrement with wrap at 0).
  check_down_next_state_equation: assert property (
    @(posedge clk) disable iff (rst) !dir |-> (count == (($past(count) == 8'd0) ? 8'd255 : ($past(count) - 8'd1)))
  );

  // Step size is always ±1 modulo 256 out of reset.
  check_step_is_plus_or_minus_one: assert property (
    @(posedge clk) disable iff (rst) 1'b1 |=> ((count == $past(count) + 8'd1) || (count == $past(count) - 8'd1))
  );

endmodule

rtl:
module full_adder (
    input A,
    input B,
    input CIN,
    output SUM,
    output COUT
);

    wire C1, S1, C2;
    fa fa1 (
        .A(A),
        .B(B),
        .CI(CIN),
        .S(S1),
        .CO(C1)
    );
    fa fa2 (
        .A(S1),
        .B(C1),
        .CI(1'b0),
        .S(SUM),
        .CO(C2)
    );
    assign COUT = C1 | C2;

endmodule 

module fa (
    input A,
    input B,
    input CI,
    output S,
    output CO
);

    assign {CO, S} = A + B + CI;

endmodule

sva:
module full_adder_sva (
    input logic CLK,   // External sampling clock (DUT is combinational, no reset)
    input logic A,
    input logic B,
    input logic CIN,
    input logic SUM,
    input logic COUT
);

    // COUT equals majority of A,B,CIN.
    check_cout_is_majority: assert property (
        @(posedge CLK) COUT == ((A & B) | (A & CIN) | (B & CIN))
    );

    // SUM equals (A^B^CIN) xor majority(A,B,CIN).
    check_sum_equals_xor_with_carry: assert property (
        @(posedge CLK) SUM == ((A ^ B ^ CIN) ^ ((A & B) | (A & CIN) | (B & CIN)))
    );

    // When no carry, SUM equals parity of inputs.
    check_sum_when_cout0: assert property (
        @(posedge CLK) (COUT == 1'b0) |-> (SUM == (A ^ B ^ CIN))
    );

    // When carry, SUM is inverse of parity.
    check_sum_when_cout1: assert property (
        @(posedge CLK) (COUT == 1'b1) |-> (SUM == ~(A ^ B ^ CIN))
    );

    // Exactly one input high -> SUM=1, COUT=0.
    check_onehot_inputs: assert property (
        @(posedge CLK) $onehot({A,B,CIN}) |-> (SUM == 1'b1) && (COUT == 1'b0)
    );

    // All inputs low -> outputs low.
    check_all_zero_case: assert property (
        @(posedge CLK) (~A & ~B & ~CIN) |-> (SUM == 1'b0) && (COUT == 1'b0)
    );

    // All inputs high -> SUM=0, COUT=1.
    check_all_one_case: assert property (
        @(posedge CLK) (A & B & CIN) |-> (SUM == 1'b0) && (COUT == 1'b1)
    );

    // Two ones: A&B=1 and CIN=0 -> SUM=1, COUT=1.
    check_two_ones_AB: assert property (
        @(posedge CLK) (A & B & ~CIN) |-> (SUM == 1'b1) && (COUT == 1'b1)
    );

    // Two ones: A&CIN=1 and B=0 -> SUM=1, COUT=1.
    check_two_ones_AC: assert property (
        @(posedge CLK) (A & CIN & ~B) |-> (SUM == 1'b1) && (COUT == 1'b1)
    );

    // Two ones: B&CIN=1 and A=0 -> SUM=1, COUT=1.
    check_two_ones_BC: assert property (
        @(posedge CLK) (B & CIN & ~A) |-> (SUM == 1'b1) && (COUT == 1'b1)
    );

endmodule

rtl:
module digitalclock (
  input clk,
  input reset,
  output reg [3:0] hour,
  output reg [5:0] minute,
  output reg ampm, // 1 for PM, 0 for AM
  output reg valid // 1 if time is valid (12:00 PM)
);

  reg [3:0] hour_count;
  reg [5:0] minute_count;

  always @(posedge clk) begin
    if (reset) begin
      hour_count <= 4'b0001;
      minute_count <= 6'b000000;
    end else begin
      // increment minute count
      if (minute_count == 6'd59) begin
        minute_count <= 6'b000000;
        // increment hour count
        if (hour_count == 4'd12) begin
          hour_count <= 4'd01;
        end else begin
          hour_count <= hour_count + 1;
        end
      end else begin
        minute_count <= minute_count + 1;
      end

      // set valid flag if time is valid
      if (hour_count == 4'd12 && minute_count == 6'd00) begin
        valid <= 1'b1;
      end else begin
        valid <= 1'b0;
      end
    end
  end

  // output hour and minute counts
  always @(*) begin
    hour = hour_count;
    minute = minute_count;
  end

  // toggle AM/PM indicator every 12 hours
  always @(posedge clk) begin
    if (reset) begin
      ampm <= 1'b0;
    end else if (hour_count == 4'd12) begin
      ampm <= ~ampm;
    end
  end

endmodule

sva:
module digitalclock_sva (
  input logic clk,
  input logic reset,
  input logic [3:0] hour,
  input logic [5:0] minute,
  input logic ampm,
  input logic valid,
  // Internal DUT signals used by assertions (must be connected via bind)
  input logic [3:0] hour_count,
  input logic [5:0] minute_count
);

  ///// Output mirroring of internal counters /////
  // hour output must mirror hour_count.
  outputs_match_hour: assert property (
    @(posedge clk) disable iff (reset) hour == hour_count
  );
  // minute output must mirror minute_count.
  outputs_match_minute: assert property (
    @(posedge clk) disable iff (reset) minute == minute_count
  );

  ///// Synchronous reset effects (next cycle) /////
  // On reset, next-cycle hour_count=1 and minute_count=0.
  reset_sets_counts: assert property (
    @(posedge clk) reset |-> ##1 (hour_count == 4'd1 && minute_count == 6'd0)
  );
  // On reset, next-cycle ampm=0.
  reset_clears_ampm: assert property (
    @(posedge clk) reset |-> ##1 (ampm == 1'b0)
  );

  ///// Minute counter behavior /////
  // If minute_count != 59, it increments by 1 next cycle.
  minute_increments: assert property (
    @(posedge clk) disable iff (reset)
      (minute_count != 6'd59) |-> ##1 (minute_count == $past(minute_count) + 6'd1)
  );
  // If minute_count == 59, it wraps to 0 next cycle.
  minute_wraps_at_59: assert property (
    @(posedge clk) disable iff (reset)
      (minute_count == 6'd59) |-> ##1 (minute_count == 6'd0)
  );

  ///// Hour counter behavior /////
  // If minute_count != 59, hour_count holds its value next cycle.
  hour_holds_when_minute_not_59: assert property (
    @(posedge clk) disable iff (reset)
      (minute_count != 6'd59) |-> ##1 (hour_count == $past(hour_count))
  );
  // If minute_count == 59 and hour_count != 12, hour_count increments next cycle.
  hour_increments_on_minute_wrap: assert property (
    @(posedge clk) disable iff (reset)
      (minute_count == 6'd59 && hour_count != 4'd12) |-> ##1 (hour_count == $past(hour_count) + 4'd1)
  );
  // If minute_count == 59 and hour_count == 12, hour_count wraps to 1 next cycle.
  hour_wraps_from_12_on_minute_wrap: assert property (
    @(posedge clk) disable iff (reset)
      (minute_count == 6'd59 && hour_count == 4'd12) |-> ##1 (hour_count == 4'd1)
  );

  ///// AM/PM behavior /////
  // When hour_count == 12, ampm toggles next cycle.
  ampm_toggles_at_hour_12: assert property (
    @(posedge clk) disable iff (reset)
      (hour_count == 4'd12) |-> ##1 (ampm == ~$past(ampm))
  );
  // When hour_count != 12, ampm holds its value next cycle.
  ampm_holds_when_not_12: assert property (
    @(posedge clk) disable iff (reset)
      (hour_count != 4'd12) |-> ##1 (ampm == $past(ampm))
  );

  ///// valid flag behavior /////
  // If time is 12:00 this cycle, valid is 1 next cycle.
  valid_high_next_if_12_00: assert property (
    @(posedge clk) disable iff (reset)
      (hour_count == 4'd12 && minute_count == 6'd0) |-> ##1 (valid == 1'b1)
  );
  // If time is not 12:00 this cycle, valid is 0 next cycle.
  valid_low_next_if_not_12_00: assert property (
    @(posedge clk) disable iff (reset)
      !(hour_count == 4'd12 && minute_count == 6'd0) |-> ##1 (valid == 1'b0)
  );

endmodule

