module and_gate (
  input A,
  input B,
  output Y
);

  wire A1, A2, B1, B2;

  assign A1 = A;
  assign A2 = 1'b1;
  assign B1 = B;
  assign B2 = 1'b1;

  assign Y = A & B;

endmodule

sva:
module and_gate_sva (
    // DUT ports
    input logic A,
    input logic B,
    input logic Y
);
    // Analysis:
    // - No clock or reset in DUT; purely combinational logic.
    // - Key behavior: Y is the logical AND of A and B (Y = A & B).
    // - Assertions are sampled on any edge of A or B.

    ///// Combinational correctness /////
    // Y must always equal A & B.
    check_y_equals_and: assert property (
        @(posedge A or negedge A or posedge B or negedge B) (Y == (A & B))
    );

    // If A is LOW, Y must be LOW.
    check_y_low_when_a_low: assert property (
        @(posedge A or negedge A or posedge B or negedge B) (!A) |-> (Y == 1'b0)
    );

    // If B is LOW, Y must be LOW.
    check_y_low_when_b_low: assert property (
        @(posedge A or negedge A or posedge B or negedge B) (!B) |-> (Y == 1'b0)
    );

    // Y can be HIGH only when both A and B are HIGH.
    check_y_high_implies_both_high: assert property (
        @(posedge A or negedge A or posedge B or negedge B) (Y == 1'b1) |-> ((A == 1'b1) && (B == 1'b1))
    );

    // If not both inputs are HIGH, Y must be LOW.
    check_not_both_high_implies_y_low: assert property (
        @(posedge A or negedge A or posedge B or negedge B) (!(A && B)) |-> (Y == 1'b0)
    );

endmodule

module binary_counter_sva (
    input logic clk,
    input logic reset,
    input logic enable,
    input logic [3:0] Q
);
    // While reset is HIGH, Q must be 0 at each sampled clock edge.
    reset_forces_zero: assert property (
        @(posedge clk) reset |-> (Q == 4'b0000)
    );

    // When not in reset and enable is HIGH, Q increments by 1 (mod 16).
    increment_when_enabled: assert property (
        @(posedge clk) disable iff (reset) enable |-> (Q == $past(Q) + 4'd1)
    );

    // When not in reset and enable is LOW, Q holds its value.
    hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset) !enable |-> (Q == $past(Q))
    );

    // Any change in Q (without reset) implies enable is HIGH that cycle.
    change_requires_enable: assert property (
        @(posedge clk) disable iff (reset) (Q != $past(Q)) |-> enable
    );

    // Wrap-around: if previous Q was 15 and enable is HIGH, Q becomes 0.
    wrap_from_15_to_0_on_enable: assert property (
        @(posedge clk) disable iff (reset) (enable && ($past(Q) == 4'hF)) |-> (Q == 4'h0)
    );

    // After 16 consecutive enabled cycles (no reset), Q returns to its original value.
    full_cycle_after_16_enables: assert property (
        @(posedge clk) disable iff (reset) enable[*16] |-> (Q == $past(Q,16))
    );

    // On reset deassertion with enable LOW, Q remains 0 on that cycle.
    reset_release_no_enable_keeps_zero: assert property (
        @(posedge clk) ($fell(reset) && !enable) |-> (Q == 4'h0)
    );

    // On reset deassertion with enable HIGH, Q becomes 1 on that cycle.
    reset_release_with_enable_sets_one: assert property (
        @(posedge clk) ($fell(reset) && enable) |-> (Q == 4'h1)
    );
endmodule

rtl:
module barrel_shifter (
    input [3:0] D,
    input [1:0] A,
    output [3:0] S
);

reg [3:0] stage1_out;
reg [3:0] stage2_out;
reg [3:0] stage3_out;

always @(*) begin
    case(A)
        2'b00: stage1_out = D;
        2'b01: stage1_out = {D[2:0], 1'b0};
        2'b10: stage1_out = {D[1:0], 2'b00};
        2'b11: stage1_out = {D[0], 3'b000};
    endcase
end

always @(*) begin
    case(A)
        2'b00: stage2_out = stage1_out;
        2'b01: stage2_out = {stage1_out[1:0], 2'b00};
        2'b10: stage2_out = {stage1_out[0], 3'b000};
        2'b11: stage2_out = 4'b0000;
    endcase
end

always @(*) begin
    case(A)
        2'b00: stage3_out = stage2_out;
        2'b01: stage3_out = {stage2_out[2:0], 1'b0};
        2'b10: stage3_out = {stage2_out[1:0], 2'b00};
        2'b11: stage3_out = {stage2_out[0], 3'b000};
    endcase
end

assign S = stage3_out;

endmodule

sva:
module barrel_shifter_sva (
    input logic clk,
    input logic [3:0] D,
    input logic [1:0] A,
    input logic [3:0] S
);
    // For A==2'b00, output passes input D.
    check_A00_passthrough: assert property (
        @(posedge clk) (A == 2'b00) |-> (S == D)
    );

    // For A==2'b01, output is {D[0],3'b000}.
    check_A01_shift3_from_D0: assert property (
        @(posedge clk) (A == 2'b01) |-> (S == {D[0], 3'b000})
    );

    // For A==2'b10 or 2'b11, output is all zeros.
    check_Amsb1_forces_zero: assert property (
        @(posedge clk) (A[1] == 1'b1) |-> (S == 4'b0000)
    );

    // When A!=2'b00, lower three bits of S are zero.
    check_lower_bits_zero_when_not_A00: assert property (
        @(posedge clk) (A != 2'b00) |-> (S[2:0] == 3'b000)
    );

    // MSB mapping: A==00 -> D[3], A==01 -> D[0], otherwise 0.
    check_msb_mapping: assert property (
        @(posedge clk) S[3] == ((A == 2'b00) ? D[3] :
                                (A == 2'b01) ? D[0] :
                                1'b0)
    );

    // All-zero input must produce all-zero output.
    check_zero_propagation: assert property (
        @(posedge clk) (D == 4'b0000) |-> (S == 4'b0000)
    );
endmodule

