module sum_first_last_16_bits (
    input [31:0] in_signal,
    output [15:0] out_signal
);

    wire [15:0] first_16_bits;
    wire [15:0] last_16_bits;

    assign first_16_bits = in_signal[31:16];
    assign last_16_bits = in_signal[15:0];

    assign out_signal = first_16_bits + last_16_bits;

endmodule

sva:
module sum_first_last_16_bits_sva (
    input logic [31:0] in_signal,
    input logic [15:0] out_signal
);
    // Output equals sum of upper and lower 16 bits (mod 2^16).
    check_sum_definition: assert property (
        @(posedge in_signal[0]) out_signal == (in_signal[31:16] + in_signal[15:0])
    );

    // If upper 16 bits are zero, output equals lower 16 bits.
    check_zero_upper_passthrough: assert property (
        @(posedge in_signal[0]) (in_signal[31:16] == 16'h0000) |=> (out_signal == in_signal[15:0])
    );

    // If lower 16 bits are zero, output equals upper 16 bits.
    check_zero_lower_passthrough: assert property (
        @(posedge in_signal[0]) (in_signal[15:0] == 16'h0000) |=> (out_signal == in_signal[31:16])
    );

    // If upper half is all ones, output equals lower minus one (mod 2^16).
    check_all_ones_upper_minus_one: assert property (
        @(posedge in_signal[0]) (in_signal[31:16] == 16'hFFFF) |=> (out_signal == (in_signal[15:0] - 16'd1))
    );

    // If lower half is all ones, output equals upper minus one (mod 2^16).
    check_all_ones_lower_minus_one: assert property (
        @(posedge in_signal[0]) (in_signal[15:0] == 16'hFFFF) |=> (out_signal == (in_signal[31:16] - 16'd1))
    );

    // If both halves are all ones, output equals 16'hFFFE.
    check_all_ones_both_fffe: assert property (
        @(posedge in_signal[0]) (in_signal == 32'hFFFF_FFFF) |=> (out_signal == 16'hFFFE)
    );

    // Output LSB equals XOR of LSBs of the two halves.
    check_lsb_xor_of_halves: assert property (
        @(posedge in_signal[0]) out_signal[0] == (in_signal[16] ^ in_signal[0])
    );

    // If halves are equal, output equals value left-shifted by 1 (mod 2^16).
    check_equal_halves_left_shift: assert property (
        @(posedge in_signal[0]) (in_signal[31:16] == in_signal[15:0]) |=> (out_signal == (in_signal[15:0] << 1))
    );
endmodule

rtl:
module decoder(
    input [6:0] address,
    output reg  bar_led_ce_n,
                board_led_ce_n,
                switch_ce_n,
                mem1_ce_n,
                mem2_ce_n);

    always @(address) begin
        switch_ce_n    = 1'b1;
        bar_led_ce_n   = 1'b1;
        mem2_ce_n      = 1'b1;
        board_led_ce_n = 1'b1;
        mem1_ce_n      = 1'b1;

        casex (address)
            7'h74: switch_ce_n    = 1'b0;
            7'h6C: bar_led_ce_n   = 1'b0;
            7'h5?: mem2_ce_n      = 1'b0;
            7'h2F: board_led_ce_n = 1'b0;
            7'h0?: mem1_ce_n      = 1'b0;
        endcase
    end
endmodule

sva:
module decoder_sva (
    input logic [6:0] address,
    input logic bar_led_ce_n,
    input logic board_led_ce_n,
    input logic switch_ce_n,
    input logic mem1_ce_n,
    input logic mem2_ce_n
);
    // No explicit clock/reset in RTL; sample assertions on a data edge.
    ///// Decode equivalences /////
    // switch_ce_n low iff address == 7'h74.
    eq_switch_decode: assert property (
        @(posedge address[0]) (switch_ce_n == (address != 7'h74))
    );
    // bar_led_ce_n low iff address == 7'h6C.
    eq_bar_led_decode: assert property (
        @(posedge address[0]) (bar_led_ce_n == (address != 7'h6C))
    );
    // board_led_ce_n low iff address == 7'h2F.
    eq_board_led_decode: assert property (
        @(posedge address[0]) (board_led_ce_n == (address != 7'h2F))
    );
    // mem1_ce_n low iff address[6:4] == 3'b000 (0x00-0x0F).
    eq_mem1_decode: assert property (
        @(posedge address[0]) (mem1_ce_n == (address[6:4] != 3'b000))
    );
    // mem2_ce_n low iff address[6:4] == 3'b101 (0x50-0x5F).
    eq_mem2_decode: assert property (
        @(posedge address[0]) (mem2_ce_n == (address[6:4] != 3'b101))
    );
    ///// Mutual exclusion /////
    // At most one active-low CE is asserted at a time.
    at_most_one_active: assert property (
        @(posedge address[0]) $onehot0({~bar_led_ce_n, ~board_led_ce_n, ~switch_ce_n, ~mem1_ce_n, ~mem2_ce_n})
    );
    ///// Default behavior /////
    // If no decode matches, all CEs remain deasserted (HIGH).
    default_no_match_all_high: assert property (
        @(posedge address[0])
        ((address != 7'h74) && (address != 7'h6C) && (address != 7'h2F) &&
         (address[6:4] != 3'b000) && (address[6:4] != 3'b101))
        |-> (switch_ce_n && bar_led_ce_n && board_led_ce_n && mem1_ce_n && mem2_ce_n)
    );
    ///// Specific address exclusivity /////
    // At address 7'h74 only switch_ce_n is asserted (LOW).
    only_switch_on_0x74: assert property (
        @(posedge address[0]) (address == 7'h74)
        |-> (!switch_ce_n && bar_led_ce_n && board_led_ce_n && mem1_ce_n && mem2_ce_n)
    );
    // At address 7'h6C only bar_led_ce_n is asserted (LOW).
    only_bar_led_on_0x6C: assert property (
