    // If Q is 0 while running, the previous value must have been 0xF.
    zero_only_from_wrap_no_reset: assert property (
        @(posedge clk) disable iff (reset) ($past(!reset) && (Q == 4'h0)) |-> ($past(Q) == 4'hF)
    );
