    // When sel==01, out equals (in1 > in0) ? in1 : in0.
    check_top_sel01_out: assert property (
        @(posedge clk) disable iff (1'b0) (sel == 2'b01) |-> (out === ((in1 > in0) ? in1 : in0))
    );
    // When sel==10, out equals (in2 > in0) ? in2 : in0.
    check_top_sel10_out: assert property (
        @(posedge clk) disable iff (1'b0) (sel == 2'b10) |-> (out === ((in2 > in0) ? in2 : in0))
    );
    // When sel==11, out equals (in3 > in0) ? in3 : in0.
    check_top_sel11_out: assert property (
        @(posedge clk) disable iff (1'b0) (sel == 2'b11) |-> (out === ((in3 > in0) ? in3 : in0))
    );
endmodule

rtl:
module six_input_module (
    input A1, A2, B1, B2, C1, VPB, VPWR, VGND, VNB, 
    output Y
);

    assign Y = ((A1 & A2 & ~B1 & ~B2) | (~A1 & ~A2 & B1 & B2) | C1) ? 1'b1 : 1'b0;

endmodule

sva:
module six_input_module_sva (
    input logic A1,
    input logic A2,
    input logic B1,
    input logic B2,
    input logic C1,
    input logic VPB,
    input logic VPWR,
    input logic VGND,
    input logic VNB,
    input logic Y
);
    // Y equals the RTL boolean function when A1 toggles.
    check_func_eq_on_A1: assert property (
        @(posedge A1) Y == ((A1 & A2 & ~B1 & ~B2) | (~A1 & ~A2 & B1 & B2) | C1)
    );

    // Y equals the RTL boolean function when A2 toggles.
    check_func_eq_on_A2: assert property (
        @(posedge A2) Y == ((A1 & A2 & ~B1 & ~B2) | (~A1 & ~A2 & B1 & B2) | C1)
    );

    // Y equals the RTL boolean function when B1 toggles.
    check_func_eq_on_B1: assert property (
        @(posedge B1) Y == ((A1 & A2 & ~B1 & ~B2) | (~A1 & ~A2 & B1 & B2) | C1)
    );

    // Y equals the RTL boolean function when B2 toggles.
    check_func_eq_on_B2: assert property (
        @(posedge B2) Y == ((A1 & A2 & ~B1 & ~B2) | (~A1 & ~A2 & B1 & B2) | C1)
    );

    // Y equals the RTL boolean function when C1 toggles.
    check_func_eq_on_C1: assert property (
        @(posedge C1) Y == ((A1 & A2 & ~B1 & ~B2) | (~A1 & ~A2 & B1 & B2) | C1)
    );

    // C1 high forces Y high.
    check_c1_dominates_y: assert property (
        @(posedge C1) C1 |-> (Y == 1'b1)
    );

    // A1&A2&~B1&~B2 implies Y high.
    check_aa11_bb00_implies_y1: assert property (
        @(posedge A1) (A1 & A2 & ~B1 & ~B2) |-> (Y == 1'b1)
    );

    // ~A1&~A2&B1&B2 implies Y high.
    check_aa00_bb11_implies_y1: assert property (
        @(posedge B1) (~A1 & ~A2 & B1 & B2) |-> (Y == 1'b1)
    );

    // If no term true and C1 low, Y must be low.
    check_else_case_y0: assert property (
        @(posedge A2) (!C1 && !((A1 & A2 & ~B1 & ~B2) | (~A1 & ~A2 & B1 & B2))) |-> (Y == 1'b0)
    );

    // Any rising edge of Y must be due to the function being true.
    check_y_rise_consistent_with_function: assert property (
        @(posedge Y) ((A1 & A2 & ~B1 & ~B2) | (~A1 & ~A2 & B1 & B2) | C1)
    );
endmodule

rtl:
module freq_synthesizer (
  input clk_ref,
  input [31:0] ctrl_word,
  output reg out_clk
);

parameter N = 10;
parameter M = 5;

reg [31:0] counter;
reg [31:0] divider = 0;

always @(posedge clk_ref) begin
  counter <= counter + 1;
  if (counter == N-1) begin
    counter <= 0;
    if (divider == M-1) begin
      divider <= 0;
      out_clk <= ~out_clk;
    end
    else begin
      divider <= divider + 1;
    end
  end
end

endmodule

sva:
module freq_synthesizer_sva #(
    parameter int unsigned N = 10,
    parameter int unsigned M = 5
) (
    input  logic         clk_ref,
    input  logic [31:0]  ctrl_word,
    input  logic         out_clk,
    input  logic [31:0]  counter,
    input  logic [31:0]  divider
);
    // Local copies of thresholds for comparisons
    localparam logic [31:0] N_MINUS_1 = N - 1;
    localparam logic [31:0] M_MINUS_1 = M - 1;

    // Gate assertions for the first cycle
    logic past_valid;
    initial past_valid = 1'b0;
    always @(posedge clk_ref) past_valid <= 1'b1;

    // Counter increments by 1 when not at N-1.
    check_counter_increment_when_not_wrap: assert property (
        @(posedge clk_ref) disable iff (!past_valid)
            ($past(counter) != N_MINUS_1) |-> (counter == $past(counter) + 32'd1)
    );

    // Counter wraps to 0 when at N-1.
    check_counter_wrap_to_zero: assert property (
        @(posedge clk_ref) disable iff (!past_valid)
            ($past(counter) == N_MINUS_1) |-> (counter == 32'd0)
    );

    // Divider holds when counter does not wrap.
    check_divider_stable_when_counter_not_wrap: assert property (
        @(posedge clk_ref) disable iff (!past_valid)
            ($past(counter) != N_MINUS_1) |-> (divider == $past(divider))
    );

    // out_clk holds when counter does not wrap.
    check_outclk_stable_when_counter_not_wrap: assert property (
        @(posedge clk_ref) disable iff (!past_valid)
            ($past(counter) != N_MINUS_1) |-> (out_clk == $past(out_clk))
    );

    // On counter wrap without divider wrap, divider increments and out_clk holds.
    check_divider_inc_on_counter_wrap_not_div_wrap: assert property (
        @(posedge clk_ref) disable iff (!past_valid)
            ($past(counter) == N_MINUS_1 && $past(divider) != M_MINUS_1)
            |-> (divider == $past(divider) + 32'd1) && (out_clk == $past(out_clk))
    );

    // On both counter and divider wrap, divider resets and out_clk toggles.
    check_both_wrap_resets_divider_and_toggles_outclk: assert property (
        @(posedge clk_ref) disable iff (!past_valid)
            ($past(counter) == N_MINUS_1 && $past(divider) == M_MINUS_1)
            |-> (divider == 32'd0) && (out_clk == ~$past(out_clk))
    );

    // On any counter wrap, only valid divider/out_clk updates occur (increment+hold or reset+toggle).
    check_counter_wrap_results_in_valid_update: assert property (
        @(posedge clk_ref) disable iff (!past_valid)
            ($past(counter) == N_MINUS_1)
            |-> (
                    ((divider == $past(divider) + 32'd1) && (out_clk == $past(out_clk))) ||
                    ((divider == 32'd0) && (out_clk == ~$past(out_clk)))
                )
    );

    // out_clk can only change when both counter and divider were at their terminal values.
    check_outclk_toggle_only_on_both_wraps: assert property (
        @(posedge clk_ref) disable iff (!past_valid)
            $changed(out_clk) |-> ($past(counter) == N_MINUS_1) && ($past(divider) == M_MINUS_1)
    );

    // Any change of divider implies counter wrapped the previous cycle.
    check_divider_change_implies_counter_wrap: assert property (
        @(posedge clk_ref) disable iff (!past_valid)
            (divider != $past(divider)) |-> ($past(counter) == N_MINUS_1)
    );

    // out_clk cannot toggle in back-to-back cycles.
    check_no_back_to_back_outclk_toggle: assert property (
        @(posedge clk_ref) disable iff (!past_valid)
            $changed(out_clk) |-> ##1 !$changed(out_clk)
    );

    // Any change of out_clk must be a logical inversion.
    check_outclk_change_is_invert: assert property (
        @(posedge clk_ref) disable iff (!past_valid)
            $changed(out_clk) |-> (out_clk == ~$past(out_clk))
    );

endmodule

rtl:
module nor_gate(
    input A,
    input B,
    output Z
);

    assign Z = ~(A | B);

endmodule

sva:
module nor_gate_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic Z
);
    // Z implements NOR of A and B.
    check_nor_function: assert property (
        @(posedge clk) Z === ~(A | B)
    );

    // Z equals (~A & ~B) (De Morgan consistency).
    check_demorgan_equivalence: assert property (
        @(posedge clk) Z === ((~A) & (~B))
    );

    // Z can be HIGH only when both inputs are LOW.
    check_Z_high_only_if_inputs_low: assert property (
        @(posedge clk) (Z === 1'b1) |-> ((A === 1'b0) && (B === 1'b0))
    );

    // When both inputs are LOW, Z must be HIGH.
    check_inputs_low_imply_Z_high: assert property (
        @(posedge clk) ((A === 1'b0) && (B === 1'b0)) |-> (Z === 1'b1)
    );

    // If A is HIGH, Z must be LOW.
    check_A_high_implies_Z_low: assert property (
        @(posedge clk) (A === 1'b1) |-> (Z === 1'b0)
    );

    // If B is HIGH, Z must be LOW.
    check_B_high_implies_Z_low: assert property (
        @(posedge clk) (B === 1'b1) |-> (Z === 1'b0)
    );

    // If both inputs are HIGH, Z must be LOW.
    check_both_inputs_high_implies_Z_low: assert property (
        @(posedge clk) ((A === 1'b1) && (B === 1'b1)) |-> (Z === 1'b0)
    );

    // If Z is LOW, at least one input must be HIGH.
    check_Z_low_implies_any_input_high: assert property (
        @(posedge clk) (Z === 1'b0) |-> ((A === 1'b1) || (B === 1'b1))
    );

    // If inputs are stable across cycles, Z must be stable.
    check_output_stable_if_inputs_stable: assert property (
        @(posedge clk) $stable({A,B}) |-> $stable(Z)
    );

    // If Z changes, at least one input must have changed.
    check_output_change_implies_input_change: assert property (
        @(posedge clk) $changed(Z) |-> $changed({A,B})
    );
endmodule

rtl:
module sky130_fd_sc_lp__nand4 (
    Y,
    A,
    B,
    C,
    D
);

    output Y;
    input  A;
    input  B;
    input  C;
    input  D;

    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    wire nand0_out_Y;

    nand nand0 (nand0_out_Y, D, C, B, A     );
    buf  buf0  (Y          , nand0_out_Y    );

endmodule

sva:
module sky130_fd_sc_lp__nand4_sva (
    input logic CLK,   // Sampling clock (DUT has no clock/reset; purely combinational)
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic Y
);
    ///// Functional equivalence /////
    // Y equals the 4-input NAND of A,B,C,D.
    check_y_is_nand4: assert property (
        @(posedge CLK) Y == ~(A & B & C & D)
    );

    ///// Truth table implications /////
    // If all inputs are 1, Y must be 0.
    check_all_ones_implies_y0: assert property (
        @(posedge CLK) (A && B && C && D) |-> (Y == 1'b0)
    );
    // If A is 0, Y must be 1.
    check_a0_implies_y1: assert property (
        @(posedge CLK) (A == 1'b0) |-> (Y == 1'b1)
    );
    // If B is 0, Y must be 1.
    check_b0_implies_y1: assert property (
        @(posedge CLK) (B == 1'b0) |-> (Y == 1'b1)
    );
    // If C is 0, Y must be 1.
    check_c0_implies_y1: assert property (
        @(posedge CLK) (C == 1'b0) |-> (Y == 1'b1)
    );
    // If D is 0, Y must be 1.
    check_d0_implies_y1: assert property (
        @(posedge CLK) (D == 1'b0) |-> (Y == 1'b1)
    );
    // Y can be 0 only when all inputs are 1.
    check_y0_implies_all_ones: assert property (
        @(posedge CLK) (Y == 1'b0) |-> (A && B && C && D)
    );

    ///// Edge-driven behavior when last input goes HIGH /////
    // When A rises and B,C,D are stably 1, Y must be 0.
    check_y_fall_when_A_rises_last: assert property (
        @(posedge CLK) $rose(A) && B && C && D && $past(B) && $past(C) && $past(D) |-> (Y == 1'b0)
    );
    // When B rises and A,C,D are stably 1, Y must be 0.
    check_y_fall_when_B_rises_last: assert property (
        @(posedge CLK) $rose(B) && A && C && D && $past(A) && $past(C) && $past(D) |-> (Y == 1'b0)
    );
    // When C rises and A,B,D are stably 1, Y must be 0.
    check_y_fall_when_C_rises_last: assert property (
        @(posedge CLK) $rose(C) && A && B && D && $past(A) && $past(B) && $past(D) |-> (Y == 1'b0)
    );
    // When D rises and A,B,C are stably 1, Y must be 0.
    check_y_fall_when_D_rises_last: assert property (
        @(posedge CLK) $rose(D) && A && B && C && $past(A) && $past(B) && $past(C) |-> (Y == 1'b0)
    );
endmodule

rtl:
module four_to_one (
    input A1_N,
    input A2_N,
    input B1,
    input B2,
    output Y
);

    assign Y = ~(A1_N & A2_N & B1 & ~B2) & ~(A1_N & ~A2_N & ~B1 & B2) & ~(~A1_N & A2_N & ~B1 & B2) & ~(~A1_N & ~A2_N & B1 & B2);

endmodule

sva:
module four_to_one_sva (
    input logic CLK,
    input logic A1_N,
    input logic A2_N,
    input logic B1,
    input logic B2,
    input logic Y
);
    // Y implements the exact combinational equation from RTL.
    func_equivalence: assert property (
        @(posedge CLK)
        Y == ( !(A1_N && A2_N && B1 && !B2)
             && !(A1_N && !A2_N && !B1 && B2)
             && !(!A1_N && A2_N && !B1 && B2)
             && !(!A1_N && !A2_N && B1 && B2) )
    );

    // Minterm A1_N&A2_N&B1&~B2 forces Y LOW.
    minterm1_forces_low: assert property (
        @(posedge CLK) (A1_N && A2_N && B1 && !B2) |-> (Y == 1'b0)
    );

    // Minterm A1_N&~A2_N&~B1&B2 forces Y LOW.
    minterm2_forces_low: assert property (
        @(posedge CLK) (A1_N && !A2_N && !B1 && B2) |-> (Y == 1'b0)
    );

    // Minterm ~A1_N&A2_N&~B1&B2 forces Y LOW.
    minterm3_forces_low: assert property (
        @(posedge CLK) (!A1_N && A2_N && !B1 && B2) |-> (Y == 1'b0)
    );

    // Minterm ~A1_N&~A2_N&B1&B2 forces Y LOW.
    minterm4_forces_low: assert property (
        @(posedge CLK) (!A1_N && !A2_N && B1 && B2) |-> (Y == 1'b0)
    );

    // If none of the minterms hold, Y must be HIGH.
    none_minterm_forces_high: assert property (
        @(posedge CLK)
        !( (A1_N && A2_N && B1 && !B2)
         || (A1_N && !A2_N && !B1 && B2)
         || (!A1_N && A2_N && !B1 && B2)
         || (!A1_N && !A2_N && B1 && B2) ) |-> (Y == 1'b1)
    );

    // Y LOW implies at least one minterm is true.
    y_low_implies_some_minterm: assert property (
        @(posedge CLK)
        (Y == 1'b0) |-> ( (A1_N && A2_N && B1 && !B2)
                       || (A1_N && !A2_N && !B1 && B2)
                       || (!A1_N && A2_N && !B1 && B2)
                       || (!A1_N && !A2_N && B1 && B2) )
    );

    // With stable inputs, Y must remain stable (purely combinational).
    stable_output_when_inputs_stable: assert property (
        @(posedge CLK)
        ($stable(A1_N) && $stable(A2_N) && $stable(B1) && $stable(B2)) |-> $stable(Y)
    );

    // When B1=0 and B2=0, Y must be HIGH.
    b00_forces_high: assert property (
        @(posedge CLK) (!B1 && !B2) |-> (Y == 1'b1)
    );

    // When B1=1 and B2=0 and not(A1_N&A2_N), Y must be HIGH.
    b10_nonbothA_high_forces_high: assert property (
        @(posedge CLK) (B1 && !B2 && !(A1_N && A2_N)) |-> (Y == 1'b1)
    );

    // When B1=0 and B2=1 and A1_N^A2_N, Y must be LOW.
    b01_xor_forces_low: assert property (
        @(posedge CLK) (!B1 && B2 && (A1_N ^ A2_N)) |-> (Y == 1'b0)
    );

    // When B1=0 and B2=1 and A1_N==A2_N, Y must be HIGH.
    b01_xnor_forces_high: assert property (
        @(posedge CLK) (!B1 && B2 && !(A1_N ^ A2_N)) |-> (Y == 1'b1)
    );

    // When B1=1 and B2=1 and any A is HIGH, Y must be HIGH.
    b11_anyA_high_forces_high: assert property (
        @(posedge CLK) (B1 && B2 && (A1_N || A2_N)) |-> (Y == 1'b1)
    );
endmodule

rtl:
module ripple_carry_adder (
	input [3:0] A,
	input [3:0] B,
	input C_in,
	input clk,
	output [3:0] S,
	output C_out
);

	reg [3:0] S_reg;
	reg C_out_reg;

	always @(posedge clk) begin
		// calculate the sum of A, B, and C_in
		S_reg = A + B + C_in;

		// calculate the carry-out bit
		C_out_reg = ((A[3] & B[3]) | (A[3] & C_in) | (B[3] & C_in));
	end

	// assign outputs
	assign S = S_reg;
	assign C_out = C_out_reg;

endmodule

sva:
module ripple_carry_adder_sva (
    input logic        clk,
    input logic [3:0]  A,
    input logic [3:0]  B,
    input logic        C_in,
    input logic [3:0]  S,
    input logic        C_out
);
    // 3-input majority function
    function automatic logic maj3 (input logic x, input logic y, input logic z);
        maj3 = (x & y) | (x & z) | (y & z);
    endfunction

    ///// Functional correctness of registered outputs /////
    // S equals previous-cycle A+B+C_in (low 4 bits).
    check_sum_matches_prev_inputs: assert property (
        @(posedge clk) S == (($past(A) + $past(B) + $past(C_in)) & 4'hF)
    );

    // C_out equals previous-cycle majority of A[3], B[3], and C_in.
    check_cout_matches_prev_inputs: assert property (
        @(posedge clk) C_out == maj3($past(A[3]), $past(B[3]), $past(C_in))
    );

    ///// Bit-level sum correctness /////
    // Bit 0 is XOR of previous-cycle A[0], B[0], and C_in.
    check_s0_xor: assert property (
        @(posedge clk) S[0] == ($past(A[0]) ^ $past(B[0]) ^ $past(C_in))
    );

    // Bit 1 is XOR of A[1], B[1], and carry from bit 0 (all from previous cycle).
    check_s1_xor_with_c1: assert property (
        @(posedge clk) S[1] == ($past(A[1]) ^ $past(B[1]) ^ maj3($past(A[0]), $past(B[0]), $past(C_in)))
    );

    // Bit 2 is XOR of A[2], B[2], and carry from bit 1 (prev cycle).
    check_s2_xor_with_c2: assert property (
        @(posedge clk) S[2] == ($past(A[2]) ^ $past(B[2]) ^ maj3($past(A[1]), $past(B[1]), maj3($past(A[0]), $past(B[0]), $past(C_in))))
    );

    // Bit 3 is XOR of A[3], B[3], and carry from bit 2 (prev cycle).
    check_s3_xor_with_c3: assert property (
        @(posedge clk) S[3] == ($past(A[3]) ^ $past(B[3]) ^ maj3($past(A[2]), $past(B[2]), maj3($past(A[1]), $past(B[1]), maj3($past(A[0]), $past(B[0]), $past(C_in)))))
    );

    ///// Carry-out corner cases derived from implemented logic /////
    // If previous-cycle A[3]=0 and B[3]=0, C_out must be 0.
    check_cout_zero_when_msbs_zero: assert property (
        @(posedge clk) ($past(A[3]) == 1'b0 && $past(B[3]) == 1'b0) |-> (C_out == 1'b0)
    );

    // If previous-cycle A[3]=1 and B[3]=1, C_out must be 1.
    check_cout_one_when_msbs_one: assert property (
        @(posedge clk) ($past(A[3]) == 1'b1 && $past(B[3]) == 1'b1) |-> (C_out == 1'b1)
    );

    // If previous-cycle A[3] != B[3], C_out equals previous-cycle C_in.
    check_cout_equals_cin_when_msbs_differ: assert property (
        @(posedge clk) ($past(A[3]) ^ $past(B[3])) |-> (C_out == $past(C_in))
    );

    ///// Simple identity cases for the sum /////
    // When previous-cycle B==0 and C_in==0, S equals previous-cycle A.
    check_sum_identity_B_zero: assert property (
        @(posedge clk) ($past(B) == 4'b0000 && $past(C_in) == 1'b0) |-> (S == $past(A))
    );

    // When previous-cycle A==0 and C_in==0, S equals previous-cycle B.
    check_sum_identity_A_zero: assert property (
        @(posedge clk) ($past(A) == 4'b0000 && $past(C_in) == 1'b0) |-> (S == $past(B))
    );

    // When previous-cycle B==0 and C_in==1, S equals previous-cycle A+1 (mod 16).
    check_sum_increment_B_zero_Cin1: assert property (
        @(posedge clk) ($past(B) == 4'b0000 && $past(C_in) == 1'b1) |-> (S == (($past(A) + 4'd1) & 4'hF))
    );

endmodule

rtl:
module udp_dff(input D, CLK, CLR, SET, output Q, QN);
  reg Q;

  always @(posedge CLK) begin
    if (CLR)
      Q <= 1'b0;
    else if (SET)
      Q <= 1'b1;
    else
      Q <= D;
  end

  assign QN = ~Q;
endmodule

sva:
module udp_dff_sva (
    input logic D,
    input logic CLK,
    input logic CLR,
    input logic SET,
    input logic Q,
    input logic QN
);
    // QN is always the complement of Q.
    check_qn_complement: assert property (
        @(posedge CLK) disable iff ($initstate) (QN == ~Q)
    );

    // CLR high at a clock drives Q low next cycle.
    check_clr_forces_zero: assert property (
        @(posedge CLK) disable iff ($initstate) CLR |=> (Q == 1'b0)
    );

    // SET high with CLR low drives Q high next cycle.
    check_set_forces_one_without_clear: assert property (
        @(posedge CLK) disable iff ($initstate) (!CLR && SET) |=> (Q == 1'b1)
    );

    // CLR has priority over SET when both are high.
    check_both_clr_set_prioritize_clear: assert property (
        @(posedge CLK) disable iff ($initstate) (CLR && SET) |=> (Q == 1'b0)
    );

    // With no control, Q follows D on the next cycle.
    check_no_ctrl_q_follows_d: assert property (
        @(posedge CLK) disable iff ($initstate) (!CLR && !SET) |=> (Q == $past(D))
    );

    // With no control, QN follows ~D on the next cycle.
    check_no_ctrl_qn_follows_not_d: assert property (
        @(posedge CLK) disable iff ($initstate) (!CLR && !SET) |=> (QN == ~$past(D))
    );

    // If no control and D equals current Q, Q holds value next cycle.
    check_hold_when_no_ctrl_and_D_eq_Q: assert property (
        @(posedge CLK) disable iff ($initstate) (!CLR && !SET && (D == Q)) |=> (Q == $past(Q))
    );

    // CLR high at a clock drives QN high next cycle.
    check_clr_sets_qn_high: assert property (
        @(posedge CLK) disable iff ($initstate) CLR |=> (QN == 1'b1)
    );

    // SET high with CLR low drives QN low next cycle.
    check_set_sets_qn_low_without_clear: assert property (
        @(posedge CLK) disable iff ($initstate) (!CLR && SET) |=> (QN == 1'b0)
    );

    // D rising with no control drives Q high next cycle.
    check_d_rise_drives_q_one: assert property (
        @(posedge CLK) disable iff ($initstate) (!CLR && !SET && $rose(D)) |=> (Q == 1'b1)
    );

    // D falling with no control drives Q low next cycle.
    check_d_fall_drives_q_zero: assert property (
        @(posedge CLK) disable iff ($initstate) (!CLR && !SET && $fell(D)) |=> (Q == 1'b0)
    );
endmodule

