rtl:
module Datapath_Unit(
    output reg signed [15:0] CR,
    output reg AR_gt_0, AR_lt_0,
    input [15:0] Data_AR, Data_BR,
    input Ld_AR_BR, Div_AR_x2_CR, Mul_BR_x2_CR, Clr_CR,
    input clk
);

    reg signed [15:0] AR;
    reg signed [15:0] BR;

    always @(AR) begin
        AR_lt_0 = (AR < 0);
        AR_gt_0 = (AR > 0);
    end

    always @(negedge clk) begin
        if (Ld_AR_BR) begin
            AR <= Data_AR;
            BR <= Data_BR;
        end else if (Div_AR_x2_CR) begin
            CR <= AR / 2;
        end else if (Mul_BR_x2_CR) begin
            CR <= BR * 2;
        end else if (Clr_CR) begin
            CR <= 0;
        end
    end

endmodule

sva:
module Datapath_Unit_sva (
    input  logic signed [15:0] CR,
    input  logic AR_gt_0,
    input  logic AR_lt_0,
    input  logic [15:0] Data_AR,
    input  logic [15:0] Data_BR,
    input  logic Ld_AR_BR,
    input  logic Div_AR_x2_CR,
    input  logic Mul_BR_x2_CR,
    input  logic Clr_CR,
    input  logic clk
);
    // AR_gt_0 and AR_lt_0 are never both HIGH simultaneously.
    check_ar_flags_mutex: assert property (
        @(negedge clk) disable iff ($initstate) !(AR_gt_0 && AR_lt_0)
    );

    // AR flags remain stable across cycles if no load in previous and current cycles.
    check_ar_flags_stable_without_load: assert property (
        @(negedge clk) disable iff ($initstate)
            (!$past(Ld_AR_BR) && !Ld_AR_BR) |-> (AR_gt_0 == $past(AR_gt_0) && AR_lt_0 == $past(AR_lt_0))
    );

    // After load with positive Data_AR, AR_gt_0=1 and AR_lt_0=0 at next cycle.
    check_ar_flags_after_load_pos: assert property (
        @(negedge clk) disable iff ($initstate)
            (Ld_AR_BR && ($signed(Data_AR) > 0)) |=> (AR_gt_0 == 1'b1 && AR_lt_0 == 1'b0)
    );

    // After load with negative Data_AR, AR_lt_0=1 and AR_gt_0=0 at next cycle.
    check_ar_flags_after_load_neg: assert property (
        @(negedge clk) disable iff ($initstate)
            (Ld_AR_BR && ($signed(Data_AR) < 0)) |=> (AR_gt_0 == 1'b0 && AR_lt_0 == 1'b1)
    );

    // After load with zero Data_AR, both AR flags are 0 at next cycle.
    check_ar_flags_after_load_zero: assert property (
        @(negedge clk) disable iff ($initstate)
            (Ld_AR_BR && ($signed(Data_AR) == 0)) |=> (AR_gt_0 == 1'b0 && AR_lt_0 == 1'b0)
    );

    // After load with non-zero Data_AR, exactly one AR flag is HIGH at next cycle.
    check_ar_flags_after_load_nonzero_onehot: assert property (
        @(negedge clk) disable iff ($initstate)
            (Ld_AR_BR && ($signed(Data_AR) != 0)) |=> (AR_gt_0 ^ AR_lt_0)
    );

    // Loading AR/BR does not modify CR; CR holds its previous value.
    check_cr_hold_on_load: assert property (
        @(negedge clk) disable iff ($initstate)
            Ld_AR_BR |=> (CR == $past(CR))
    );

    // With no operations asserted, CR holds its previous value.
    check_cr_hold_when_no_ops: assert property (
        @(negedge clk) disable iff ($initstate)
            (!Ld_AR_BR && !Div_AR_x2_CR && !Mul_BR_x2_CR && !Clr_CR) |=> (CR == $past(CR))
    );

    // When only Clr_CR is selected (and Ld/Div/Mul are 0), CR is cleared to 0.
    check_cr_clear_when_only_clr: assert property (
        @(negedge clk) disable iff ($initstate)
            (!Ld_AR_BR && !Div_AR_x2_CR && !Mul_BR_x2_CR && Clr_CR) |=> (CR == 16'sd0)
    );

    // If only Clr_CR is selected in consecutive cycles, CR remains 0.
    check_cr_zero_persistent_on_only_clr: assert property (
        @(negedge clk) disable iff ($initstate)
            ($past(!Ld_AR_BR && !Div_AR_x2_CR && !Mul_BR_x2_CR && Clr_CR) &&
             (!Ld_AR_BR && !Div_AR_x2_CR && !Mul_BR_x2_CR && Clr_CR)) |-> (CR == 16'sd0)
    );

endmodule

module four_bit_selector_sva (
    input logic clk,
    input logic [3:0] a,
    input logic [1:0] o
);
    // Output matches the RTL's ternary mapping.
    check_functional_mapping: assert property (
        @(posedge clk) disable iff (1'b0)
            o == ((a < 5) ? a[1:0] : ((a >> 2)[3:2]))
    );

    // For a < 5, output equals the 2 LSBs of a.
    check_low_range_path: assert property (
        @(posedge clk) disable iff (1'b0)
            (a < 5) |-> (o == a[1:0])
    );

    // For a >= 5, output is zero because (a >> 2)[3:2] == 2'b00.
    check_high_range_zero: assert property (
        @(posedge clk) disable iff (1'b0)
            (a >= 5) |-> (o == 2'b00)
    );

    // Boundary: a == 4 drives o == 2'b00 (a[1:0]).
    check_boundary_a_eq_4: assert property (
        @(posedge clk) disable iff (1'b0)
            (a == 4) |-> (o == 2'b00)
    );

    // Boundary: a == 5 drives o == 2'b00 ((a >> 2)[3:2]).
    check_boundary_a_eq_5: assert property (
        @(posedge clk) disable iff (1'b0)
            (a == 5) |-> (o == 2'b00)
    );

    // If input is stable across cycles, output remains stable (pure combinational).
    check_output_stable_when_a_stable: assert property (
        @(posedge clk) disable iff (1'b0)
            $stable(a) |-> $stable(o)
    );

    // Transition from a < 5 to a >= 5 yields o == 2'b00 on the latter cycle.
    check_transition_low_to_high: assert property (
        @(posedge clk) disable iff (1'b0)
            (a < 5) ##1 (a >= 5) |-> (o == 2'b00)
    );

    // Transition from a >= 5 to a < 5 yields o == a[1:0] on the latter cycle.
    check_transition_high_to_low: assert property (
        @(posedge clk) disable iff (1'b0)
            (a >= 5) ##1 (a < 5) |-> (o == a[1:0])
    );

    // Any non-zero output implies a < 5 and equals a[1:0].
    check_nonzero_output_implies_low_range: assert property (
        @(posedge clk) disable iff (1'b0)
            (o != 2'b00) |-> ((a < 5) && (o == a[1:0]))
    );

    // Uniqueness: o == 2'b01 only occurs when a == 4'd1.
    check_unique_output_01: assert property (
        @(posedge clk) disable iff (1'b0)
            (o == 2'b01) |-> (a == 4'd1)
    );

    // Uniqueness: o == 2'b10 only occurs when a == 4'd2.
    check_unique_output_10: assert property (
        @(posedge clk) disable iff (1'b0)
            (o == 2'b10) |-> (a == 4'd2)
    );

    // Uniqueness: o == 2'b11 only occurs when a == 4'd3.
    check_unique_output_11: assert property (
        @(posedge clk) disable iff (1'b0)
            (o == 2'b11) |-> (a == 4'd3)
    );
endmodule

rtl:
module comb_circuit (
  input [2:0] A,
  input [2:0] B,
  input [2:0] C,
  output [2:0] Y1,
  output [2:0] Y2,
  output [2:0] Y3
);

  wire [2:0] _Y1;
  wire [2:0] _Y2;
  wire [2:0] _Y3;

  assign _Y1 = A & B;
  assign _Y2 = A | C;
  assign _Y3 = B ^ C;

  assign Y1 = _Y1;
  assign Y2 = _Y2;
  assign Y3 = _Y3;

endmodule

sva:
module comb_circuit_sva (
    input logic [2:0] A,
    input logic [2:0] B,
    input logic [2:0] C,
    input logic [2:0] Y1,
    input logic [2:0] Y2,
    input logic [2:0] Y3
);

    ///// Functional correctness /////
    // Y1 equals bitwise AND of A and B.
    check_y1_and: assert property (
        @($global_clock) Y1 == (A & B)
    );

    // Y2 equals bitwise OR of A and C.
    check_y2_or: assert property (
        @($global_clock) Y2 == (A | C)
    );

    // Y3 equals bitwise XOR of B and C.
    check_y3_xor: assert property (
        @($global_clock) Y3 == (B ^ C)
    );

    ///// Derived invariants from definitions /////
    // Y1 is a subset of A.
    check_y1_subset_a: assert property (
        @($global_clock) (Y1 & ~A) == 3'b000
    );

    // Y1 is a subset of B.
    check_y1_subset_b: assert property (
        @($global_clock) (Y1 & ~B) == 3'b000
    );

    // Y2 is a superset of A.
    check_y2_superset_a: assert property (
        @($global_clock) (A & ~Y2) == 3'b000
    );

    // Y2 is a superset of C.
    check_y2_superset_c: assert property (
        @($global_clock) (C & ~Y2) == 3'b000
    );

    // Inversion: B is Y3 XOR C.
    check_y3_invert_b: assert property (
        @($global_clock) (Y3 ^ C) == B
    );

    // Inversion: C is Y3 XOR B.
    check_y3_invert_c: assert property (
        @($global_clock) (Y3 ^ B) == C
    );

    // Y1 OR Y2 collapses to Y2.
    check_y1_or_y2_eq_y2: assert property (
        @($global_clock) (Y1 | Y2) == Y2
    );

    // Y1 AND Y2 collapses to Y1.
    check_y1_and_y2_eq_y1: assert property (
        @($global_clock) (Y1 & Y2) == Y1
    );

endmodule

rtl:
module top_module(
    input t,
    input clk,
    output reg [1:0] out
);

reg [1:0] flip_flop;
wire d1, d2;

// T flip-flop 1
assign d1 = flip_flop[0] ^ t;
always @(posedge clk) begin
    flip_flop[0] <= d1;
end

// T flip-flop 2
assign d2 = flip_flop[1] ^ flip_flop[0];
always @(posedge clk) begin
    flip_flop[1] <= d2;
end

// Functional module
always @(*) begin
    case (flip_flop)
        2'b00: out = 2'b00;
        2'b01: out = 2'b01;
        2'b10: out = 2'b10;
        2'b11: out = 2'b11;
    endcase
end

endmodule

sva:
module top_module_sva (
    input logic t,
    input logic clk,
    input logic [1:0] out
);
    // Clock: clk (posedge). Reset: none. Logic: sequential TFFs + combinational mapping (out mirrors flip_flop).
    // Key next-state: out[0]' = $past(out[0]) ^ t; out[1]' = $past(out[1]) ^ $past(out[0]).

    // LSB updates with XOR of prior LSB and current t.
    check_lsb_updates_with_t: assert property (
        @(posedge clk) out[0] == ($past(out[0]) ^ t)
    );

    // MSB toggles iff prior LSB was 1.
    check_msb_updates_with_prev_lsb: assert property (
        @(posedge clk) out[1] == ($past(out[1]) ^ $past(out[0]))
    );

    // Out0 does not toggle when t is 0.
    check_out0_stable_when_t0: assert property (
        @(posedge clk) (!t) |-> (out[0] == $past(out[0]))
    );

    // Out0 toggles when t is 1.
    check_out0_toggle_when_t1: assert property (
        @(posedge clk) (t) |-> (out[0] != $past(out[0]))
    );

    // Out1 does not toggle when prior out0 was 0.
    check_out1_stable_when_prev_lsb0: assert property (
        @(posedge clk) ($past(out[0]) == 1'b0) |-> (out[1] == $past(out[1]))
    );

    // Out1 toggles when prior out0 was 1.
    check_out1_toggle_when_prev_lsb1: assert property (
        @(posedge clk) ($past(out[0]) == 1'b1) |-> (out[1] != $past(out[1]))
    );

    // With t==0 and prior state 00, stay at 00.
    check_t0_transition_00: assert property (
        @(posedge clk) (!t && ($past(out) == 2'b00)) |-> (out == 2'b00)
    );

    // With t==0 and prior state 01, go to 11.
    check_t0_transition_01: assert property (
        @(posedge clk) (!t && ($past(out) == 2'b01)) |-> (out == 2'b11)
    );

    // With t==0 and prior state 10, stay at 10.
    check_t0_transition_10: assert property (
        @(posedge clk) (!t && ($past(out) == 2'b10)) |-> (out == 2'b10)
    );

    // With t==0 and prior state 11, go to 01.
    check_t0_transition_11: assert property (
        @(posedge clk) (!t && ($past(out) == 2'b11)) |-> (out == 2'b01)
    );

    // With t==1 and prior state 00, go to 01.
    check_t1_transition_00: assert property (
        @(posedge clk) (t && ($past(out) == 2'b00)) |-> (out == 2'b01)
    );

    // With t==1 and prior state 01, go to 10.
    check_t1_transition_01: assert property (
        @(posedge clk) (t && ($past(out) == 2'b01)) |-> (out == 2'b10)
    );

    // With t==1 and prior state 10, go to 11.
    check_t1_transition_10: assert property (
        @(posedge clk) (t && ($past(out) == 2'b10)) |-> (out == 2'b11)
    );

    // With t==1 and prior state 11, go to 00.
    check_t1_transition_11: assert property (
        @(posedge clk) (t && ($past(out) == 2'b11)) |-> (out == 2'b00)
    );

endmodule

rtl:
module Mux_3x1_bv2 #(parameter W=32)
(
//Input Signals
input wire [1:0] select,
input wire [W-1:0] ch_0,
input wire [W-1:0] ch_1,
input wire [W-1:0] ch_2,
//Output Signals
output reg [W-1:0] data_out
);
    always @*
        begin
            case(select)
                2'b00: data_out <= {W{1'b0}};
                2'b01: data_out <= ch_0;
                2'b10: data_out <= ch_1;
                2'b11: data_out <= ch_2;
                default : data_out <= ch_0;
            endcase
        end
endmodule

sva:
module Mux_3x1_bv2_sva #(parameter W=32) (
    input logic [1:0] select,
    input logic [W-1:0] ch_0,
    input logic [W-1:0] ch_1,
    input logic [W-1:0] ch_2,
    input logic [W-1:0] data_out
);
    // When select==2'b00, data_out must be all zeros.
    check_sel00_outputs_zero: assert property (
        @(posedge select[0] or posedge select[1] or negedge select[0] or negedge select[1])
            (select == 2'b00) |-> (data_out == {W{1'b0}})
    );

    // When select==2'b01, data_out must equal ch_0.
    check_sel01_routes_ch0: assert property (
        @(posedge select[0] or posedge select[1] or negedge select[0] or negedge select[1])
            (select == 2'b01) |-> (data_out == ch_0)
    );

    // When select==2'b10, data_out must equal ch_1.
    check_sel10_routes_ch1: assert property (
        @(posedge select[0] or posedge select[1] or negedge select[0] or negedge select[1])
            (select == 2'b10) |-> (data_out == ch_1)
    );

    // When select==2'b11, data_out must equal ch_2.
    check_sel11_routes_ch2: assert property (
        @(posedge select[0] or posedge select[1] or negedge select[0] or negedge select[1])
            (select == 2'b11) |-> (data_out == ch_2)
    );
endmodule

