rtl:
module calculator(
    input clk,
    input [7:0] A,
    input [7:0] B,
    input [1:0] operation,
    output reg [15:0] result
);

    reg [15:0] temp;

    always @(posedge clk) begin
        case(operation)
            2'b00: // addition
                temp = {8'b0, A} + {8'b0, B};
            2'b01: // subtraction
                temp = {8'b0, A} - {8'b0, B};
            2'b10: // multiplication
                temp = {16'b0, A} * {16'b0, B};
            2'b11: // division
                temp = {16'b0, A} / {16'b0, B};
        endcase

        result <= temp;
    end
endmodule

sva:
module calculator_sva (
    input logic clk,
    input logic [7:0] A,
    input logic [7:0] B,
    input logic [1:0] operation,
    input logic [15:0] result
);
    ///// Functional correctness per operation (1-cycle latency) /////
    // On add, result equals previous cycle's 16-bit zero-extended A+B.
    check_addition_result: assert property (
        @(posedge clk) ($past(operation) == 2'b00) |-> (result == $past({8'b0, A} + {8'b0, B}))
    );
    // On subtract, result equals previous cycle's 16-bit zero-extended A-B.
    check_subtraction_result: assert property (
        @(posedge clk) ($past(operation) == 2'b01) |-> (result == $past({8'b0, A} - {8'b0, B}))
    );
    // On multiply, result equals previous cycle's lower 16 bits of 24x24 product.
    check_multiplication_result: assert property (
        @(posedge clk) ($past(operation) == 2'b10) |-> (result == $past(({16'b0, A} * {16'b0, B})[15:0]))
    );
    // On divide with nonzero divisor, result equals previous cycle's lower 16 bits of 24/24 quotient.
    check_division_result_nonzero: assert property (
        @(posedge clk) ($past(operation) == 2'b11 && $past(B) != 8'd0) |-> (result == $past(({16'b0, A} / {16'b0, B})[15:0]))
    );

    ///// Identities and corner cases derived from the RTL arithmetic /////
    // Add: if A was zero, result equals previous zero-extended B.
    add_identity_A_zero: assert property (
        @(posedge clk) ($past(operation) == 2'b00 && $past(A) == 8'd0) |-> (result == $past({8'b0, B}))
    );
    // Add: if B was zero, result equals previous zero-extended A.
    add_identity_B_zero: assert property (
        @(posedge clk) ($past(operation) == 2'b00 && $past(B) == 8'd0) |-> (result == $past({8'b0, A}))
    );
    // Sub: if B was zero, result equals previous zero-extended A.
    sub_identity_B_zero: assert property (
        @(posedge clk) ($past(operation) == 2'b01 && $past(B) == 8'd0) |-> (result == $past({8'b0, A}))
    );
    // Sub: if A and B were equal, result is zero.
    sub_equal_operands_zero: assert property (
        @(posedge clk) ($past(operation) == 2'b01 && ($past(A) == $past(B))) |-> (result == 16'd0)
    );
    // Mul: if either operand was zero, result is zero.
    mul_zero_produces_zero: assert property (
        @(posedge clk) ($past(operation) == 2'b10 && ($past(A) == 8'd0 || $past(B) == 8'd0)) |-> (result == 16'd0)
    );
    // Mul: if A was 1, result equals previous zero-extended B.
    mul_by_one_A_identity: assert property (
        @(posedge clk) ($past(operation) == 2'b10 && $past(A) == 8'd1) |-> (result == $past({8'b0, B}))
    );
    // Mul: if B was 1, result equals previous zero-extended A.
    mul_by_one_B_identity: assert property (
        @(posedge clk) ($past(operation) == 2'b10 && $past(B) == 8'd1) |-> (result == $past({8'b0, A}))
    );
    // Div: if divisor was 1, result equals previous zero-extended A.
    div_by_one_identity: assert property (
        @(posedge clk) ($past(operation) == 2'b11 && $past(B) == 8'd1) |-> (result == $past({8'b0, A}))
    );
endmodule

rtl:
module mux_4to1_case (
  input [3:0] a,
  input [3:0] b,
  input [3:0] c,
  input [3:0] d,
  input [1:0] sel,
  output reg [3:0] out
);

always @(*) begin
  case(sel)
    2'b00: out = a;
    2'b01: out = b;
    2'b10: out = c;
    2'b11: out = d;
    default: out = 4'b0000;
  endcase
end

endmodule

sva:
module mux_4to1_case_sva (
  input logic clk,              // external verification clock
  input logic [3:0] a,
  input logic [3:0] b,
  input logic [3:0] c,
  input logic [3:0] d,
  input logic [1:0] sel,
  input logic [3:0] out
);

  // When sel==00, out routes a.
  check_sel_00_routes_a: assert property (
    @(posedge clk) disable iff (1'b0) (sel === 2'b00) |-> (out == a)
  );

  // When sel==01, out routes b.
  check_sel_01_routes_b: assert property (
    @(posedge clk) disable iff (1'b0) (sel === 2'b01) |-> (out == b)
  );

  // When sel==10, out routes c.
  check_sel_10_routes_c: assert property (
    @(posedge clk) disable iff (1'b0) (sel === 2'b10) |-> (out == c)
  );

  // When sel==11, out routes d.
  check_sel_11_routes_d: assert property (
    @(posedge clk) disable iff (1'b0) (sel === 2'b11) |-> (out == d)
  );

  // If sel has X/Z, default branch drives zero.
  check_unknown_sel_routes_zero: assert property (
    @(posedge clk) disable iff (1'b0) $isunknown(sel) |-> (out == 4'b0000)
  );

  // For known sel, out equals the selected input.
  check_mapping_for_known_sel: assert property (
    @(posedge clk) disable iff (1'b0)
      (!$isunknown(sel)) |-> (
        ((sel === 2'b00) && (out == a)) ||
        ((sel === 2'b01) && (out == b)) ||
        ((sel === 2'b10) && (out == c)) ||
        ((sel === 2'b11) && (out == d))
      )
  );

  // If sel and selected input are stable, out is stable.
  check_out_stable_if_sel_and_selected_stable: assert property (
    @(posedge clk) disable iff (1'b0)
      ($stable(sel) &&
       (((sel === 2'b00) && $stable(a)) ||
        ((sel === 2'b01) && $stable(b)) ||
        ((sel === 2'b10) && $stable(c)) ||
        ((sel === 2'b11) && $stable(d))))) |-> $stable(out)
  );

  // Changes on unselected inputs do not affect out when sel==00 and a is stable.
  check_unselected_changes_ignore_out_sel00: assert property (
    @(posedge clk) disable iff (1'b0)
      ($stable(sel) && (sel === 2'b00) && $stable(a) && $changed({b,c,d})) |-> $stable(out)
  );

  // Changes on unselected inputs do not affect out when sel==01 and b is stable.
  check_unselected_changes_ignore_out_sel01: assert property (
    @(posedge clk) disable iff (1'b0)
      ($stable(sel) && (sel === 2'b01) && $stable(b) && $changed({a,c,d})) |-> $stable(out)
  );

  // Changes on unselected inputs do not affect out when sel==10 and c is stable.
  check_unselected_changes_ignore_out_sel10: assert property (
    @(posedge clk) disable iff (1'b0)
      ($stable(sel) && (sel === 2'b10) && $stable(c) && $changed({a,b,d})) |-> $stable(out)
  );

  // Changes on unselected inputs do not affect out when sel==11 and d is stable.
  check_unselected_changes_ignore_out_sel11: assert property (
    @(posedge clk) disable iff (1'b0)
      ($stable(sel) && (sel === 2'b11) && $stable(d) && $changed({a,b,c})) |-> $stable(out)
  );

endmodule

rtl:
module Adder4 (input [3:0] A, B, input Cin, clk, output [3:0] S, output Cout);

    reg [3:0] S_reg;
    reg Cout_reg;

    always @(posedge clk) begin
        S_reg <= A + B + Cin;
        Cout_reg <= (A[3] & B[3]) | (A[3] & Cin) | (B[3] & Cin);
    end

    assign S = S_reg;
    assign Cout = Cout_reg;

endmodule

sva:
module Adder4_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic       Cin,
    input logic       clk,
    input logic [3:0] S,
    input logic       Cout
);

    // S registers the 4-bit sum A+B+Cin one cycle later.
    check_sum_registered: assert property (
        @(posedge clk) 1'b1 |-> ##1 (S == $past(A + B + Cin))
    );

    // Cout registers the MSB carry expression one cycle later.
    check_cout_registered: assert property (
        @(posedge clk) 1'b1 |-> ##1 (Cout == $past((A[3] & B[3]) | (A[3] & Cin) | (B[3] & Cin)))
    );

    // LSB of the sum equals A[0]^B[0]^Cin one cycle later.
    check_sum_lsb_bit0: assert property (
        @(posedge clk) 1'b1 |-> ##1 (S[0] == $past(A[0] ^ B[0] ^ Cin))
    );

    // MSB of the sum equals bit[3] of (A+B+Cin) one cycle later.
    check_sum_msb_bit3: assert property (
        @(posedge clk) 1'b1 |-> ##1 (S[3] == $past((A + B + Cin)[3]))
    );

    // Cout is independent of lower bits; if {A[3],B[3],Cin} is unchanged across two cycles, Cout holds.
    check_cout_independent_of_lower_bits: assert property (
        @(posedge clk) ($past({A[3], B[3], Cin}) == $past({A[3], B[3], Cin}, 2)) |-> ##1 (Cout == $past(Cout))
    );

endmodule

rtl:
module my_module (
    X   ,
    A1  ,
    A2  ,
    A3  ,
    B1  ,
    B2  ,
    VPWR,
    VGND,
    VPB ,
    VNB
);

    output X   ;
    input  A1  ;
    input  A2  ;
    input  A3  ;
    input  B1  ;
    input  B2  ;
    input  VPWR;
    input  VGND;
    input  VPB ;
    input  VNB ;

    wire a2_and_a3;
    wire b2_or_vpwr;
    wire vpb_xor_vnb;

    assign a2_and_a3 = A2 & A3;
    assign b2_or_vpwr = B2 | VPWR;
    assign vpb_xor_vnb = VPB ^ VNB;

    assign X = (A1 & a2_and_a3) | (~A1 & B1 & b2_or_vpwr) | (~A1 & ~B1 & vpb_xor_vnb);

endmodule

sva:
module my_module_sva (
    input logic X,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic B1,
    input logic B2,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB
);
    // X equals the implemented boolean expression.
    check_function_equation: assert property (
        @(posedge B2) X == ((A1 & (A2 & A3)) | ((~A1) & B1 & (B2 | VPWR)) | ((~A1) & (~B1) & (VPB ^ VNB)))
    );

    // When A1 is HIGH, X equals A2 & A3.
    check_A1_high_path: assert property (
        @(posedge B2) A1 |-> (X == (A2 & A3))
    );

    // When A1 is LOW and B1 is HIGH, X equals B2 | VPWR.
    check_A1_low_B1_high_path: assert property (
        @(posedge B2) (~A1 & B1) |-> (X == (B2 | VPWR))
    );

    // When A1 is LOW and B1 is LOW, X equals VPB ^ VNB.
    check_A1_low_B1_low_path: assert property (
        @(posedge B2) (~A1 & ~B1) |-> (X == (VPB ^ VNB))
    );

    // If A1=1 and A2=1 and A3=1, then X must be 1.
    check_A1_high_all_ones_implies_X1: assert property (
        @(posedge B2) (A1 & A2 & A3) |-> (X == 1'b1)
    );

    // If A1=1 and A2=0, then X must be 0.
    check_A1_high_A2_zero_implies_X0: assert property (
        @(posedge B2) (A1 & ~A2) |-> (X == 1'b0)
    );

    // If A1=1 and A3=0, then X must be 0.
    check_A1_high_A3_zero_implies_X0: assert property (
        @(posedge B2) (A1 & ~A3) |-> (X == 1'b0)
    );

    // If A1=0, B1=1, and B2=1, then X must be 1.
    check_else_path_B2_one_implies_X1: assert property (
        @(posedge B2) (~A1 & B1 & B2) |-> (X == 1'b1)
    );

    // If A1=0, B1=1, and VPWR=1, then X must be 1.
    check_else_path_VPWR_one_implies_X1: assert property (
        @(posedge B2) (~A1 & B1 & VPWR) |-> (X == 1'b1)
    );

    // If A1=0, B1=1, B2=0, and VPWR=0, then X must be 0.
    check_else_path_zero_inputs_implies_X0: assert property (
        @(posedge B2) (~A1 & B1 & ~B2 & ~VPWR) |-> (X == 1'b0)
    );

    // If A1=0, B1=0, and VPB==VNB, then X must be 0.
    check_xor_path_equal_inputs_implies_X0: assert property (
        @(posedge B2) (~A1 & ~B1 & (VPB ~^ VNB)) |-> (X == 1'b0)
    );

    // If A1=0, B1=0, and VPB!=VNB, then X must be 1.
    check_xor_path_unequal_inputs_implies_X1: assert property (
        @(posedge B2) (~A1 & ~B1 & (VPB ^ VNB)) |-> (X == 1'b1)
    );
endmodule

rtl:
module t_order_a (
   m_from_clk_lev1_r, n_from_clk_lev2, o_from_com_levs11, o_from_comandclk_levs12,
   clk, a_to_clk_levm3, b_to_clk_levm1, c_com_levs10, d_to_clk_levm2, one
   );

   input clk;
   input [7:0] a_to_clk_levm3;
   input [7:0] b_to_clk_levm1;
   input [7:0] c_com_levs10;
   input [7:0] d_to_clk_levm2;
   input [7:0] one;
   output [7:0] m_from_clk_lev1_r;
   output [7:0] n_from_clk_lev2;
   output [7:0] o_from_com_levs11;
   output [7:0] o_from_comandclk_levs12;


   reg [7:0]		m_from_clk_lev1_r;
   wire [7:0] a_to_clk_levm1;
   wire [7:0] a_to_clk_levm2;
   wire [7:0] c_com_levs11;
   reg [7:0]  o_from_comandclk_levs12;
   wire [7:0]  n_from_clk_lev2;
   wire [7:0]  n_from_clk_lev3;

   assign     a_to_clk_levm1 = a_to_clk_levm2 + d_to_clk_levm2;
   assign     a_to_clk_levm2 = a_to_clk_levm3 + 0;

   always @ (posedge clk) begin
      m_from_clk_lev1_r <= a_to_clk_levm1 + b_to_clk_levm1;
   end

   assign c_com_levs11 = c_com_levs10 + one;
   always @ (c_com_levs11 or n_from_clk_lev3) o_from_comandclk_levs12 = c_com_levs11 + n_from_clk_lev3;
   assign n_from_clk_lev2 = m_from_clk_lev1_r;
   assign n_from_clk_lev3 = n_from_clk_lev2;
   wire [7:0] o_from_com_levs11 = c_com_levs10 + 1;

endmodule

sva:
module t_order_a_sva (
    input logic clk,
    input logic [7:0] a_to_clk_levm3,
    input logic [7:0] b_to_clk_levm1,
    input logic [7:0] c_com_levs10,
    input logic [7:0] d_to_clk_levm2,
    input logic [7:0] one,
    input logic [7:0] m_from_clk_lev1_r,
    input logic [7:0] n_from_clk_lev2,
    input logic [7:0] o_from_com_levs11,
    input logic [7:0] o_from_comandclk_levs12
);
    // m_from_clk_lev1_r captures (a_to_clk_levm3 + d_to_clk_levm2) + b_to_clk_levm1 on the previous cycle.
    check_m_update_from_inputs: assert property (
        @(posedge clk) m_from_clk_lev1_r == $past((a_to_clk_levm3 + d_to_clk_levm2) + b_to_clk_levm1)
    );

    // n_from_clk_lev2 is a combinational mirror of m_from_clk_lev1_r.
    check_n_mirrors_m: assert property (
        @(posedge clk) n_from_clk_lev2 == m_from_clk_lev1_r
    );

    // o_from_com_levs11 is c_com_levs10 + 1 (8-bit wrap).
    check_o_com_plus1: assert property (
        @(posedge clk) o_from_com_levs11 == (c_com_levs10 + 8'd1)
    );

    // o_from_comandclk_levs12 equals (c_com_levs10 + one) + n_from_clk_lev2 (combinational).
    check_o_andclk_sum_with_n: assert property (
        @(posedge clk) o_from_comandclk_levs12 == ((c_com_levs10 + one) + n_from_clk_lev2)
    );

    // By transitivity (n == m), o_from_comandclk_levs12 also equals (c_com_levs10 + one) + m_from_clk_lev1_r.
    check_o_andclk_sum_with_m: assert property (
        @(posedge clk) o_from_comandclk_levs12 == ((c_com_levs10 + one) + m_from_clk_lev1_r)
    );

    // n_from_clk_lev2 also reflects the registered sum from the previous cycle.
    check_n_update_from_inputs: assert property (
        @(posedge clk) n_from_clk_lev2 == $past((a_to_clk_levm3 + d_to_clk_levm2) + b_to_clk_levm1)
    );

    // If the adder inputs are stable over a cycle, m_from_clk_lev1_r holds its value.
    check_m_holds_when_inputs_stable: assert property (
        @(posedge clk) ($stable(a_to_clk_levm3) && $stable(b_to_clk_levm1) && $stable(d_to_clk_levm2)) |-> (m_from_clk_lev1_r == $past(m_from_clk_lev1_r))
    );

    // If operands to o_from_comandclk_levs12 are stable over a cycle, it holds its value.
    check_o_andclk_holds_when_operands_stable: assert property (
        @(posedge clk) ($stable(c_com_levs10) && $stable(one) && $stable(n_from_clk_lev2)) |-> (o_from_comandclk_levs12 == $past(o_from_comandclk_levs12))
    );

    // Any change on m_from_clk_lev1_r must be reflected on n_from_clk_lev2 at the same clock.
    check_n_changes_with_m: assert property (
        @(posedge clk) $changed(m_from_clk_lev1_r) |-> $changed(n_from_clk_lev2)
    );

    // If m_from_clk_lev1_r does not change across a cycle, n_from_clk_lev2 does not change either.
    check_n_not_change_when_m_not_change: assert property (
        @(posedge clk) !$changed(m_from_clk_lev1_r) |-> !$changed(n_from_clk_lev2)
    );
endmodule

rtl:
module complement_concat (
    input [15:0] data_in,
    output reg [31:0] comp_concat_out
);

    always @(*) begin
        comp_concat_out = {data_in, ~data_in};
    end

endmodule

sva:
module complement_concat_sva (
    input logic CLK,
    input logic RESETn,
    input logic [15:0] data_in,
    input logic [31:0] comp_concat_out
);
    // Output equals input concatenated with its bitwise complement.
    check_concat_exact: assert property (
        @(posedge CLK) disable iff (!RESETn)
            comp_concat_out == {data_in, ~data_in}
    );

    // Upper 16 bits mirror data_in.
    check_upper_matches_input: assert property (
        @(posedge CLK) disable iff (!RESETn)
            comp_concat_out[31:16] == data_in
    );

    // Lower 16 bits are bitwise complement of data_in.
    check_lower_is_complement: assert property (
        @(posedge CLK) disable iff (!RESETn)
            comp_concat_out[15:0] == ~data_in
    );

    // Upper half is bitwise complement of lower half.
    check_upper_complements_lower: assert property (
        @(posedge CLK) disable iff (!RESETn)
            comp_concat_out[31:16] == ~comp_concat_out[15:0]
    );

    // Lower half XOR input is all ones.
    check_lower_xor_all_ones: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (comp_concat_out[15:0] ^ data_in) == 16'hFFFF
    );

    // Pairwise OR across halves is all ones.
    check_pairwise_or_ones: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (comp_concat_out[31:16] | comp_concat_out[15:0]) == 16'hFFFF
    );

    // Pairwise AND across halves is all zeros.
    check_pairwise_and_zeros: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (comp_concat_out[31:16] & comp_concat_out[15:0]) == 16'h0000
    );

    // No X/Z on output when input has no X/Z.
    check_no_unknown_when_input_known: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (!$isunknown(data_in)) |-> (!$isunknown(comp_concat_out))
    );

    // If input is stable across cycles, output is stable across cycles.
    check_stability_with_input: assert property (
        @(posedge CLK) disable iff (!RESETn)
            ($past(RESETn) && (data_in == $past(data_in))) |-> (comp_concat_out == $past(comp_concat_out))
    );

    // Upper half toggle mask matches input toggle mask.
    check_upper_toggle_mask: assert property (
        @(posedge CLK) disable iff (!RESETn)
            $past(RESETn) |-> ((comp_concat_out[31:16] ^ $past(comp_concat_out[31:16])) == (data_in ^ $past(data_in)))
    );

    // Lower half toggle mask matches input toggle mask.
    check_lower_toggle_mask: assert property (
        @(posedge CLK) disable iff (!RESETn)
            $past(RESETn) |-> ((comp_concat_out[15:0] ^ $past(comp_concat_out[15:0])) == (data_in ^ $past(data_in)))
    );
endmodule

rtl:
module full_adder (
    input A,
    input B,
    input Cin,
    output S,
    output Cout
);
    // Implementing full adder using structural verilog
    wire w1, w2, w3;
    xor x1(w1, A, B);
    xor x2(S, w1, Cin);
    and a1(w2, A, B);
    and a2(w3, w1, Cin);
    or o1(Cout, w2, w3);
endmodule

module four_bit_adder (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] S,
    output Cout
);
    wire c0, c1, c2;
    full_adder fa0(A[0], B[0], Cin, S[0], c0);
    full_adder fa1(A[1], B[1], c0, S[1], c1);
    full_adder fa2(A[2], B[2], c1, S[2], c2);
    full_adder fa3(A[3], B[3], c2, S[3], Cout);
endmodule

sva:
module four_bit_adder_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic Cin,
    input logic [3:0] S,
    input logic Cout
);
    // Carry function for a single bit full adder stage.
    function automatic logic carr(input logic a, input logic b, input logic c_in);
        carr = (a & b) | (c_in & (a ^ b));
    endfunction

    // Sum bit 0 equals XOR of A[0], B[0], and Cin.
    check_sum0_xor: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0] ^ Cin)
    );

    // Sum bit 1 equals XOR of A[1], B[1], and carry from bit 0.
    check_sum1_xor_with_carry: assert property (
        @(posedge clk) S[1] == (A[1] ^ B[1] ^ carr(A[0], B[0], Cin))
    );

    // Sum bit 2 equals XOR of A[2], B[2], and carry from bit 1.
    check_sum2_xor_with_carry: assert property (
        @(posedge clk) S[2] == (A[2] ^ B[2] ^ carr(A[1], B[1], carr(A[0], B[0], Cin)))
    );

    // Sum bit 3 equals XOR of A[3], B[3], and carry from bit 2.
    check_sum3_xor_with_carry: assert property (
        @(posedge clk) S[3] == (A[3] ^ B[3] ^ carr(A[2], B[2], carr(A[1], B[1], carr(A[0], B[0], Cin))))
    );

    // Cout equals carry from the MSB stage.
    check_cout_ripple: assert property (
        @(posedge clk) Cout == carr(A[3], B[3], carr(A[2], B[2], carr(A[1], B[1], carr(A[0], B[0], Cin))))
    );

    // The 5-bit result {Cout,S} equals A + B + Cin.
    check_5bit_sum_matches: assert property (
        @(posedge clk) {Cout, S} == (A + B + Cin)
    );
endmodule

rtl:
module hazard_unit
    (
        input   wire[4:0]   rs_ex_mem_hz_i,
        input   wire[4:0]   rt_ex_mem_hz_i,
        input   wire[4:0]   rd_mem_wb_hz_i,
        input   wire[4:0]   rd_wb_ret_hz_i,
        input   wire        mem_to_reg_ex_mem_hz_i,
        input   wire        reg_wr_mem_wb_hz_i,
        input   wire        reg_wr_wb_ret_hz_i,
        input   wire        branch_taken_ex_mem_hz_i,
        input   wire        jump_iss_ex_hz_i,
        input   wire        brn_pred_ex_mem_hz_i,
        output  wire        stall_fetch_hz_o,
        output  wire        stall_iss_hz_o,
        output  wire        flush_ex_hz_o,
        output  wire        flush_iss_hz_o,
        output  wire[1:0]   fwd_p1_ex_mem_hz_o,
        output  wire[1:0]   fwd_p2_ex_mem_hz_o
    );

    wire        stall_fetch_hz;
    wire        stall_iss_hz;
    wire        flush_ex_hz;
    wire        flush_iss_hz;
    wire[1:0]   fwd_p1_ex_mem_hz;
    wire[1:0]   fwd_p2_ex_mem_hz;

    assign  stall_fetch_hz_o    = stall_fetch_hz;
    assign  stall_iss_hz_o      = stall_iss_hz;
    assign  flush_ex_hz_o       = flush_ex_hz;
    assign  flush_iss_hz_o      = flush_iss_hz;
    assign  fwd_p1_ex_mem_hz_o  = fwd_p1_ex_mem_hz; 
    assign  fwd_p2_ex_mem_hz_o  = fwd_p2_ex_mem_hz; 

    assign  fwd_p1_ex_mem_hz = (reg_wr_mem_wb_hz_i & |rd_mem_wb_hz_i &
                               (rd_mem_wb_hz_i == rs_ex_mem_hz_i)) ? 2'b10 
                               : (reg_wr_wb_ret_hz_i &  |rd_wb_ret_hz_i &                       
                                 (rd_wb_ret_hz_i == rs_ex_mem_hz_i)) ? 2'b01 
                                 : 2'b00;
    assign  fwd_p2_ex_mem_hz = (reg_wr_mem_wb_hz_i & |rd_mem_wb_hz_i &
                               (rd_mem_wb_hz_i == rt_ex_mem_hz_i)) ? 2'b10 
                               : (reg_wr_wb_ret_hz_i & |rd_wb_ret_hz_i &
                                 (rd_wb_ret_hz_i == rt_ex_mem_hz_i)) ? 2'b01 
                                 : 2'b00;
    assign stall_fetch_hz = 1'b0;
    assign stall_iss_hz = 1'b0;
    assign flush_ex_hz = branch_taken_ex_mem_hz_i & ~brn_pred_ex_mem_hz_i;
    assign flush_iss_hz = (branch_taken_ex_mem_hz_i & ~brn_pred_ex_mem_hz_i) | jump_iss_ex_hz_i;

endmodule

sva:
module hazard_unit_sva (
    input logic CLK,
    input logic RESETn,
    input logic [4:0] rs_ex_mem_hz_i,
    input logic [4:0] rt_ex_mem_hz_i,
    input logic [4:0] rd_mem_wb_hz_i,
    input logic [4:0] rd_wb_ret_hz_i,
    input logic       mem_to_reg_ex_mem_hz_i,
    input logic       reg_wr_mem_wb_hz_i,
    input logic       reg_wr_wb_ret_hz_i,
    input logic       branch_taken_ex_mem_hz_i,
    input logic       jump_iss_ex_hz_i,
    input logic       brn_pred_ex_mem_hz_i,
    input logic       stall_fetch_hz_o,
    input logic       stall_iss_hz_o,
    input logic       flush_ex_hz_o,
    input logic       flush_iss_hz_o,
    input logic [1:0] fwd_p1_ex_mem_hz_o,
    input logic [1:0] fwd_p2_ex_mem_hz_o
);
    ///// Stall outputs /////
    // stall_fetch_hz_o is always 0.
    check_stall_fetch_const_zero: assert property (
        @(posedge CLK) disable iff (!RESETn) (stall_fetch_hz_o == 1'b0)
    );
    // stall_iss_hz_o is always 0.
    check_stall_iss_const_zero: assert property (
        @(posedge CLK) disable iff (!RESETn) (stall_iss_hz_o == 1'b0)
    );

    ///// Flush logic /////
    // flush_ex_hz_o equals branch_taken_ex_mem_hz_i & ~brn_pred_ex_mem_hz_i.
    check_flush_ex_definition: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (flush_ex_hz_o == (branch_taken_ex_mem_hz_i & ~brn_pred_ex_mem_hz_i))
    );
    // flush_iss_hz_o equals (branch_taken_ex_mem_hz_i & ~brn_pred_ex_mem_hz_i) | jump_iss_ex_hz_i.
    check_flush_iss_definition: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (flush_iss_hz_o == ((branch_taken_ex_mem_hz_i & ~brn_pred_ex_mem_hz_i) | jump_iss_ex_hz_i))
    );
    // flush_ex implies taken and mispredicted.
    check_flush_ex_implies_taken_mispred: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (flush_ex_hz_o |-> (branch_taken_ex_mem_hz_i && !brn_pred_ex_mem_hz_i))
    );
    // flush_ex implies flush_iss (since flush_iss = flush_ex | jump).
    check_flush_ex_implies_flush_iss: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (flush_ex_hz_o |-> flush_iss_hz_o)
    );
    // jump sets flush_iss.
    check_jump_sets_flush_iss: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (jump_iss_ex_hz_i |-> flush_iss_hz_o)
    );

    ///// Forwarding for operand 1 (rs_ex_mem_hz_i) /////
    // If MEM/WB writes matching nonzero rd, select 2'b10.
    check_fwd_p1_memwb_select: assert property (
        @(posedge CLK) disable iff (!RESETn)
            ((reg_wr_mem_wb_hz_i && (|rd_mem_wb_hz_i) && (rd_mem_wb_hz_i == rs_ex_mem_hz_i))
             |-> (fwd_p1_ex_mem_hz_o == 2'b10))
    );
    // If MEM/WB is not selected and WB/RET writes matching nonzero rd, select 2'b01.
    check_fwd_p1_wbret_select: assert property (
        @(posedge CLK) disable iff (!RESETn)
            ((!(reg_wr_mem_wb_hz_i && (|rd_mem_wb_hz_i) && (rd_mem_wb_hz_i == rs_ex_mem_hz_i)) &&
               (reg_wr_wb_ret_hz_i && (|rd_wb_ret_hz_i) && (rd_wb_ret_hz_i == rs_ex_mem_hz_i)))
             |-> (fwd_p1_ex_mem_hz_o == 2'b01))
    );
    // If neither source matches, select 2'b00.
    check_fwd_p1_default_zero: assert property (
        @(posedge CLK) disable iff (!RESETn)
            ((!(reg_wr_mem_wb_hz_i && (|rd_mem_wb_hz_i) && (rd_mem_wb_hz_i == rs_ex_mem_hz_i)) &&
               !(reg_wr_wb_ret_hz_i && (|rd_wb_ret_hz_i) && (rd_wb_ret_hz_i == rs_ex_mem_hz_i)))
             |-> (fwd_p1_ex_mem_hz_o == 2'b00))
    );
    // If 2'b10 is selected, MEM/WB match condition holds.
    check_fwd_p1_when_10_implies_memwb: assert property (
        @(posedge CLK) disable iff (!RESETn)
            ((fwd_p1_ex_mem_hz_o == 2'b10)
             |-> (reg_wr_mem_wb_hz_i && (|rd_mem_wb_hz_i) && (rd_mem_wb_hz_i == rs_ex_mem_hz_i)))
    );
    // If 2'b01 is selected, MEM/WB not selected and WB/RET match holds.
    check_fwd_p1_when_01_implies_wbret: assert property (
        @(posedge CLK) disable iff (!RESETn)
            ((fwd_p1_ex_mem_hz_o == 2'b01)
             |-> (!(reg_wr_mem_wb_hz_i && (|rd_mem_wb_hz_i) && (rd_mem_wb_hz_i == rs_ex_mem_hz_i)) &&
                  (reg_wr_wb_ret_hz_i && (|rd_wb_ret_hz_i) && (rd_wb_ret_hz_i == rs_ex_mem_hz_i))))
    );
    // If 2'b00 is selected, neither match holds.
    check_fwd_p1_when_00_implies_none: assert property (
        @(posedge CLK) disable iff (!RESETn)
            ((fwd_p1_ex_mem_hz_o == 2'b00)
             |-> (!(reg_wr_mem_wb_hz_i && (|rd_mem_wb_hz_i) && (rd_mem_wb_hz_i == rs_ex_mem_hz_i)) &&
                  !(reg_wr_wb_ret_hz_i && (|rd_wb_ret_hz_i) && (rd_wb_ret_hz_i == rs_ex_mem_hz_i))))
    );
    // fwd_p1 encoding never 2'b11.
    check_fwd_p1_never_11: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (fwd_p1_ex_mem_hz_o inside {2'b00,2'b01,2'b10})
    );

    ///// Forwarding for operand 2 (rt_ex_mem_hz_i) /////
    // If MEM/WB writes matching nonzero rd, select 2'b10.
    check_fwd_p2_memwb_select: assert property (
        @(posedge CLK) disable iff (!RESETn)
            ((reg_wr_mem_wb_hz_i && (|rd_mem_wb_hz_i) && (rd_mem_wb_hz_i == rt_ex_mem_hz_i))
             |-> (fwd_p2_ex_mem_hz_o == 2'b10))
    );
    // If MEM/WB is not selected and WB/RET writes matching nonzero rd, select 2'b01.
    check_fwd_p2_wbret_select: assert property (
        @(posedge CLK) disable iff (!RESETn)
            ((!(reg_wr_mem_wb_hz_i && (|rd_mem_wb_hz_i) && (rd_mem_wb_hz_i == rt_ex_mem_hz_i)) &&
               (reg_wr_wb_ret_hz_i && (|rd_wb_ret_hz_i) && (rd_wb_ret_hz_i == rt_ex_mem_hz_i)))
             |-> (fwd_p2_ex_mem_hz_o == 2'b01))
    );
    // If neither source matches, select 2'b00.
    check_fwd_p2_default_zero: assert property (
        @(posedge CLK) disable iff (!RESETn)
            ((!(reg_wr_mem_wb_hz_i && (|rd_mem_wb_hz_i) && (rd_mem_wb_hz_i == rt_ex_mem_hz_i)) &&
               !(reg_wr_wb_ret_hz_i && (|rd_wb_ret_hz_i) && (rd_wb_ret_hz_i == rt_ex_mem_hz_i)))
             |-> (fwd_p2_ex_mem_hz_o == 2'b00))
    );
    // If 2'b10 is selected, MEM/WB match condition holds.
    check_fwd_p2_when_10_implies_memwb: assert property (
        @(posedge CLK) disable iff (!RESETn)
            ((fwd_p2_ex_mem_hz_o == 2'b10)
             |-> (reg_wr_mem_wb_hz_i && (|rd_mem_wb_hz_i) && (rd_mem_wb_hz_i == rt_ex_mem_hz_i)))
    );
    // If 2'b01 is selected, MEM/WB not selected and WB/RET match holds.
    check_fwd_p2_when_01_implies_wbret: assert property (
        @(posedge CLK) disable iff (!RESETn)
            ((fwd_p2_ex_mem_hz_o == 2'b01)
             |-> (!(reg_wr_mem_wb_hz_i && (|rd_mem_wb_hz_i) && (rd_mem_wb_hz_i == rt_ex_mem_hz_i)) &&
                  (reg_wr_wb_ret_hz_i && (|rd_wb_ret_hz_i) && (rd_wb_ret_hz_i == rt_ex_mem_hz_i))))
    );
    // If 2'b00 is selected, neither match holds.
    check_fwd_p2_when_00_implies_none: assert property (
        @(posedge CLK) disable iff (!RESETn)
            ((fwd_p2_ex_mem_hz_o == 2'b00)
             |-> (!(reg_wr_mem_wb_hz_i && (|rd_mem_wb_hz_i) && (rd_mem_wb_hz_i == rt_ex_mem_hz_i)) &&
                  !(reg_wr_wb_ret_hz_i && (|rd_wb_ret_hz_i) && (rd_wb_ret_hz_i == rt_ex_mem_hz_i))))
    );
    // fwd_p2 encoding never 2'b11.
    check_fwd_p2_never_11: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (fwd_p2_ex_mem_hz_o inside {2'b00,2'b01,2'b10})
    );
endmodule

rtl:
module bitwise_op (x, y, z, o);

	input [31:0] x, y, z;
	output [31:0] o;

	wire [31:0] temp;

	assign temp = y ^ z;
	assign o = z ^ (x & temp);

endmodule

sva:
module bitwise_op_sva (
    // Environment clock for sampling; DUT has no clock/reset (pure combinational)
    input logic clk,
    // DUT ports
    input logic [31:0] x,
    input logic [31:0] y,
    input logic [31:0] z,
    input logic [31:0] o
);
    // o matches the RTL expression exactly.
    check_output_matches_rtl_expr: assert property (
        @(posedge clk) o == (z ^ (x & (y ^ z)))
    );

    // o is equivalent to a bitwise mux: x ? y : z.
    check_mux_equivalence: assert property (
        @(posedge clk) o == ((x & y) | (~x & z))
    );

    // The XOR of o and z equals x masked with (y^z).
    check_xor_mask_relation: assert property (
        @(posedge clk) (o ^ z) == (x & (y ^ z))
    );

    // When x is all zeros, o must pass through z.
    check_pass_through_when_x_zero: assert property (
        @(posedge clk) (x == 32'b0) |-> (o == z)
    );

    // When x is all ones, o must equal y.
    check_select_y_when_x_all_ones: assert property (
        @(posedge clk) (x == 32'hFFFF_FFFF) |-> (o == y)
    );

    // When y equals z, o must equal z.
    check_when_y_equals_z: assert property (
        @(posedge clk) (y == z) |-> (o == z)
    );

    // When z is all zeros, o reduces to x & y.
    check_when_z_zero: assert property (
        @(posedge clk) (z == 32'b0) |-> (o == (x & y))
    );

    // When y is all zeros, o reduces to (~x) & z.
    check_when_y_zero: assert property (
        @(posedge clk) (y == 32'b0) |-> (o == ((~x) & z))
    );

    // Bits selected by x must match y (masked equality).
    check_y_path_mask: assert property (
        @(posedge clk) (o & x) == (y & x)
    );

    // Bits not selected by x must match z (masked equality).
    check_z_path_mask: assert property (
        @(posedge clk) (o & ~x) == (z & ~x)
    );
endmodule

rtl:
module sky130_fd_sc_ms__or4b_1 (
    input A,
    input B,
    input C,
    input D,
    output X
);

    assign X = A | B | C | D;

endmodule

module or4 (
    input A,
    input B,
    input C,
    input D,
    output X
);

    wire [3:0] or_inputs;
    assign or_inputs = {A, B, C, ~D};

    sky130_fd_sc_ms__or4b_1 or_gate (
        .X(X),
        .A(or_inputs[0]),
        .B(or_inputs[1]),
        .C(or_inputs[2]),
        .D(or_inputs[3])
    );

endmodule

sva:
module or4_sva (
    input logic CLK,
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic X
);
    // X equals A | B | C | ~D.
    check_functional_equivalence: assert property (
        @(posedge CLK) disable iff (1'b0) X == (A | B | C | ~D)
    );
    // D low forces X high in the same cycle.
    check_d_low_forces_x_high: assert property (
        @(posedge CLK) disable iff (1'b0) (D == 1'b0) |=> (X == 1'b1)
    );
    // A high forces X high in the same cycle.
    check_a_high_forces_x_high: assert property (
        @(posedge CLK) disable iff (1'b0) (A == 1'b1) |=> (X == 1'b1)
    );
    // B high forces X high in the same cycle.
    check_b_high_forces_x_high: assert property (
        @(posedge CLK) disable iff (1'b0) (B == 1'b1) |=> (X == 1'b1)
    );
    // C high forces X high in the same cycle.
    check_c_high_forces_x_high: assert property (
        @(posedge CLK) disable iff (1'b0) (C == 1'b1) |=> (X == 1'b1)
    );
    // When A,B,C are low and D is high, X must be low.
    check_all_abclow_dhigh_forces_x_low: assert property (
        @(posedge CLK) disable iff (1'b0) (!A && !B && !C && (D == 1'b1)) |=> (X == 1'b0)
    );
    // When A,B,C are low, X equals ~D.
    check_abclow_x_eq_notd: assert property (
        @(posedge CLK) disable iff (1'b0) (!A && !B && !C) |=> (X == ~D)
    );
    // When D is high, X equals A|B|C.
    check_dhigh_x_eq_abc: assert property (
        @(posedge CLK) disable iff (1'b0) (D == 1'b1) |=> (X == (A | B | C))
    );
    // If X is low, then A,B,C are low and D is high.
    check_x_low_implies_inputs_inactive: assert property (
        @(posedge CLK) disable iff (1'b0) (X == 1'b0) |=> (!A && !B && !C && (D == 1'b1))
    );
    // If X is high, then at least one of A,B,C is high or D is low.
    check_x_high_implies_cause: assert property (
        @(posedge CLK) disable iff (1'b0) (X == 1'b1) |=> (A || B || C || !D)
    );
endmodule

rtl:
module my_module (
    X ,
    A1,
    A2,
    B1,
    B2,
    C1
);

    // Module ports
    output X ;
    input  A1;
    input  A2;
    input  B1;
    input  B2;
    input  C1;

    // Local signals
    wire or0_out   ;
    wire or1_out   ;
    wire and0_out_X;

    //  Name  Output      Other arguments
    or  or0  (or0_out   , B2, B1              );
    or  or1  (or1_out   , A2, A1              );
    and and0 (and0_out_X, or0_out, or1_out, C1);
    buf buf0 (X         , and0_out_X          );

endmodule

sva:
module my_module_sva (
    input  logic CLK,
    input  logic X,
    input  logic A1,
    input  logic A2,
    input  logic B1,
    input  logic B2,
    input  logic C1
);
    // X equals (A1|A2)&(B1|B2)&C1.
    check_function_equivalence: assert property (
        @(posedge CLK) X === ((A1 || A2) && (B1 || B2) && C1)
    );

    // X high requires C1 high.
    check_x_high_requires_c1: assert property (
        @(posedge CLK) (X == 1'b1) |-> (C1 == 1'b1)
    );

    // X high requires at least one A high.
    check_x_high_requires_a: assert property (
        @(posedge CLK) (X == 1'b1) |-> (A1 || A2)
    );

    // X high requires at least one B high.
    check_x_high_requires_b: assert property (
        @(posedge CLK) (X == 1'b1) |-> (B1 || B2)
    );

    // C1 low forces X low.
    check_c1_low_forces_x_low: assert property (
        @(posedge CLK) (C1 == 1'b0) |-> (X == 1'b0)
    );

    // Both A low forces X low.
    check_a_both_low_forces_x_low: assert property (
        @(posedge CLK) ((A1 == 1'b0) && (A2 == 1'b0)) |-> (X == 1'b0)
    );

    // Both B low forces X low.
    check_b_both_low_forces_x_low: assert property (
        @(posedge CLK) ((B1 == 1'b0) && (B2 == 1'b0)) |-> (X == 1'b0)
    );

    // X can only change if some input changed.
    check_x_change_requires_input_change: assert property (
        @(posedge CLK) $changed(X) |-> ($changed(A1) || $changed(A2) || $changed(B1) || $changed(B2) || $changed(C1))
    );

    // If all inputs are stable, X must be stable.
    check_inputs_stable_hold_x_stable: assert property (
        @(posedge CLK) (!$changed(A1) && !$changed(A2) && !$changed(B1) && !$changed(B2) && !$changed(C1)) |-> !$changed(X)
    );

    // X rising implies all enabling conditions now true.
    check_x_rise_requires_conditions: assert property (
        @(posedge CLK) $rose(X) |-> ((A1 || A2) && (B1 || B2) && (C1 == 1'b1))
    );

    // C1 falling forces X low in the same cycle.
    check_c1_fall_forces_x_low: assert property (
        @(posedge CLK) $fell(C1) |-> (X == 1'b0)
    );

    // With both OR terms true, rising C1 drives X high.
    check_c1_rise_sets_x_high_when_ors_true: assert property (
        @(posedge CLK) ($rose(C1) && (A1 || A2) && (B1 || B2)) |-> (X == 1'b1)
    );
endmodule

rtl:
module shift_register(input clk, input rst, input data, output reg [2:0] q);
    reg [2:0] q_temp;

    always @(posedge clk or negedge rst) begin
        if (rst == 0) begin
            q_temp <= 3'b0;
        end
        else begin
            q_temp <= {q_temp[1:0], data};
        end
    end

    always @(q_temp) begin
        q <= q_temp;
    end
endmodule

sva:
module shift_register_sva (
    input logic clk,
    input logic rst,          // active-low reset in RTL (asserted when 0)
    input logic data,
    input logic [2:0] q,
    input logic [2:0] q_temp
);
    // During reset, q must be 0.
    check_reset_clears_q: assert property (
        @(posedge clk) (rst == 1'b0) |-> (q == 3'b000)
    );

    // During reset, q_temp must be 0.
    check_reset_clears_qtemp: assert property (
        @(posedge clk) (rst == 1'b0) |-> (q_temp == 3'b000)
    );

    // q must mirror q_temp at all sampled times.
    check_q_mirrors_qtemp: assert property (
        @(posedge clk) (q == q_temp)
    );

    // On each enabled clock, q shifts left by one and captures data in LSB.
    check_shift_update_word: assert property (
        @(posedge clk) disable iff (!rst) $past(rst) |-> (q == { $past(q)[1:0], $past(data) })
    );

    // MSB shift: q[2] takes previous q[1] when enabled.
    check_shift_update_msb: assert property (
        @(posedge clk) disable iff (!rst) $past(rst) |-> (q[2] == $past(q[1]))
    );

    // Middle bit shift: q[1] takes previous q[0] when enabled.
    check_shift_update_mid: assert property (
        @(posedge clk) disable iff (!rst) $past(rst) |-> (q[1] == $past(q[0]))
    );

    // LSB capture: q[0] takes previous data when enabled.
    check_shift_update_lsb: assert property (
        @(posedge clk) disable iff (!rst) $past(rst) |-> (q[0] == $past(data))
    );

    // After three enabled cycles, q equals the last three data samples.
    check_three_cycle_capture: assert property (
        @(posedge clk) disable iff (!rst)
            ($past(rst,1) && $past(rst,2) && $past(rst,3))
            |-> (q == { $past(data,3), $past(data,2), $past(data,1) })
    );

    // While reset is held, q remains zero and stable.
    check_hold_reset_keeps_q_zero: assert property (
        @(posedge clk) (rst == 1'b0 && $past(rst) == 1'b0) |-> (q == 3'b000) && (q == $past(q))
    );

    // While reset is held, q_temp remains zero and stable.
    check_hold_reset_keeps_qtemp_zero: assert property (
        @(posedge clk) (rst == 1'b0 && $past(rst) == 1'b0) |-> (q_temp == 3'b000) && (q_temp == $past(q_temp))
    );
endmodule

