module SyncCounter(
    input clk,
    input rst,
    output reg [3:0] count,
    output [3:0] leds
);

always @(posedge clk) begin
    if (rst) begin
        count <= 4'b0;
    end else begin
        count <= count + 1;
    end
end

assign leds = count;

endmodule

sva:
module SyncCounter_sva (
    input logic clk,
    input logic rst,
    input logic [3:0] count,
    input logic [3:0] leds
);
    // leds must always mirror count.
    check_leds_mirror_count: assert property (
        @(posedge clk) disable iff (rst) (leds == count)
    );

    // Synchronous reset drives count to 0 on the next cycle.
    check_reset_clears_count_next: assert property (
        @(posedge clk) rst |=> (count == 4'd0)
    );

    // If reset is held across consecutive cycles, count remains 0.
    check_reset_held_keeps_zero: assert property (
        @(posedge clk) ($past(rst) && rst) |-> (count == 4'd0)
    );

    // Synchronous reset drives leds to 0 on the next cycle.
    check_reset_clears_leds_next: assert property (
        @(posedge clk) rst |=> (leds == 4'd0)
    );

    // When not in reset, count increments by 1 each cycle (modulo 16).
    check_increment_each_cycle_no_reset: assert property (
        @(posedge clk) disable iff (rst) (count == $past(count) + 4'd1)
    );

    // When not in reset for two cycles, the two-cycle stride is +2 (modulo 16).
    check_two_cycle_stride_no_reset: assert property (
        @(posedge clk) disable iff (rst) (!$past(rst) && !rst) |-> (count == $past(count,2) + 4'd2)
    );

    // When the previous value was 0xF and no reset, wrap to 0x0.
    check_wrap_from_F_to_0: assert property (
        @(posedge clk) disable iff (rst) ($past(!rst) && ($past(count) == 4'hF)) |-> (count == 4'h0)
    );

    // When not in reset, count must change every cycle (no stall).
    check_no_stall_when_no_reset: assert property (
        @(posedge clk) disable iff (rst) (count != $past(count))
    );

    // Immediately after reset deasserts, count becomes 1.
    check_first_value_after_reset_is_1: assert property (
        @(posedge clk) disable iff (rst) ($past(rst) && !rst) |-> (count == 4'd1)
    );

    // When not in reset, leds increments by 1 each cycle (follows count).
    check_leds_increment_no_reset: assert property (
        @(posedge clk) disable iff (rst) (leds == $past(leds) + 4'd1)
    );
endmodule

rtl:
module top_module (
    input [2:0] a,         // 3-bit input vector a
    input [2:0] b,         // 3-bit input vector b
    input sel_logic_or,   // Select input for logical OR or bitwise OR
    input sel_inverse,    // Select input for regular or inverse input vectors
    output [2:0] out_or,   // Output from logical OR module
    output [2:0] out_bitwise,  // Output from bitwise OR module
    output [5:0] out_not   // Output for inverses of input vectors
);

    wire [2:0] a_int, b_int;
    wire [2:0] out_or_int, out_bitwise_int;

    assign a_int = sel_inverse ? ~a : a;
    assign b_int = sel_inverse ? ~b : b;

    // Instantiate the logical OR module
    or_logic_module u_or_logic (
        .a(a_int),
        .b(b_int),
        .out(out_or_int)
    );

    // Instantiate the bitwise OR module
    or_bitwise_module u_or_bitwise (
        .a(a_int),
        .b(b_int),
        .out(out_bitwise_int)
    );

    // Combinational logic for inverses
    assign out_not[5:3] = ~b;
    assign out_not[2:0] = ~a;

    // Select between logical OR and bitwise OR
    assign out_or = sel_logic_or ? out_or_int : 3'b0;
    assign out_bitwise = ~sel_logic_or ? out_bitwise_int : 3'b0;

endmodule
module or_logic_module (
    input [2:0] a,
    input [2:0] b,
    output [2:0] out
);
    assign out = a | b;
endmodule
module or_bitwise_module (
    input [2:0] a,
    input [2:0] b,
    output [2:0] out
);
    assign out = a | b;
endmodule

sva:
module top_module_sva (
    input logic CLK,
    input logic [2:0] a,
    input logic [2:0] b,
    input logic sel_logic_or,
    input logic sel_inverse,
    input logic [2:0] out_or,
    input logic [2:0] out_bitwise,
    input logic [5:0] out_not
);
    // Expected OR of (possibly inverted) inputs used by both output selections
    wire [2:0] expected_or = sel_inverse ? (~a | ~b) : (a | b);

    // out_not lower bits are bitwise NOT of a
    check_out_not_lower: assert property (
        @(posedge CLK) out_not[2:0] == ~a
    );

    // out_not upper bits are bitwise NOT of b
    check_out_not_upper: assert property (
        @(posedge CLK) out_not[5:3] == ~b
    );

    // When sel_logic_or=0, out_or is forced to zero
    check_out_or_zero_when_sel0: assert property (
        @(posedge CLK) (sel_logic_or == 1'b0) |-> (out_or == 3'b000)
    );

    // When sel_logic_or=1, out_bitwise is forced to zero
    check_out_bitwise_zero_when_sel1: assert property (
        @(posedge CLK) (sel_logic_or == 1'b1) |-> (out_bitwise == 3'b000)
    );

    // When sel_logic_or=1, out_or equals OR of selected (possibly inverted) inputs
    check_out_or_value_when_sel1: assert property (
        @(posedge CLK) (sel_logic_or == 1'b1) |-> (out_or == expected_or)
    );

    // When sel_logic_or=0, out_bitwise equals OR of selected (possibly inverted) inputs
    check_out_bitwise_value_when_sel0: assert property (
        @(posedge CLK) (sel_logic_or == 1'b0) |-> (out_bitwise == expected_or)
    );

    // The OR of the two outputs equals the expected OR result
    check_outputs_or_combined_equals_expected: assert property (
        @(posedge CLK) (out_or | out_bitwise) == expected_or
    );

    // The two outputs are bitwise disjoint
    check_outputs_bitwise_disjoint: assert property (
        @(posedge CLK) (out_or & out_bitwise) == 3'b000
    );

    // If out_or is zero then either it is deselected or the expected result is zero
    check_out_or_zero_implication: assert property (
        @(posedge CLK) (out_or == 3'b000) |-> ((sel_logic_or == 1'b0) || (expected_or == 3'b000))
    );

    // If out_bitwise is zero then either it is deselected or the expected result is zero
    check_out_bitwise_zero_implication: assert property (
        @(posedge CLK) (out_bitwise == 3'b000) |-> ((sel_logic_or == 1'b1) || (expected_or == 3'b000))
    );
endmodule

module binary_counter_sva (
    input logic clk,
    input logic reset,
    input logic count_up,
    input logic [3:0] count
);
    // Reset drives count to zero at each clock.
    reset_forces_zero: assert property (
        @(posedge clk) reset |-> (count == 4'h0)
    );

    // While reset is held across cycles, count stays at 0 and stable.
    hold_zero_while_reset: assert property (
        @(posedge clk) (reset && $past(reset)) |-> (count == 4'h0) && (count == $past(count))
    );

    // When counting up, next count is prev + 1 (mod 16).
    check_up_increments: assert property (
        @(posedge clk) disable iff (reset) $past(!reset) && $past(count_up) |-> (count == $past(count) + 4'd1)
    );

    // When counting down, next count is prev - 1 (mod 16).
    check_down_decrements: assert property (
        @(posedge clk) disable iff (reset) $past(!reset) && !$past(count_up) |-> (count == $past(count) - 4'd1)
    );

    // Up-wrap: from 0xF to 0 when count_up is 1.
    check_wrap_up: assert property (
        @(posedge clk) disable iff (reset) $past(!reset) && $past(count_up) && ($past(count) == 4'hF) |-> (count == 4'h0)
    );

    // Down-wrap: from 0 to 0xF when count_up is 0.
    check_wrap_down: assert property (
        @(posedge clk) disable iff (reset) $past(!reset) && !$past(count_up) && ($past(count) == 4'h0) |-> (count == 4'hF)
    );

    // If result is 0, prior state/direction must be F with up or 1 with down.
    check_zero_predecessors: assert property (
        @(posedge clk) disable iff (reset) $past(!reset) && (count == 4'h0) |->
            ( ($past(count_up) && ($past(count) == 4'hF)) || (!$past(count_up) && ($past(count) == 4'h1)) )
    );

    // If result is F, prior state/direction must be E with up or 0 with down.
    check_f_predecessors: assert property (
        @(posedge clk) disable iff (reset) $past(!reset) && (count == 4'hF) |->
            ( ($past(count_up) && ($past(count) == 4'hE)) || (!$past(count_up) && ($past(count) == 4'h0)) )
    );

    // Two-cycle up: +2 (mod 16) when count_up = 1 for two cycles.
    check_two_step_up: assert property (
        @(posedge clk) disable iff (reset)
            $past(!reset,2) && $past(!reset,1) && $past(count_up,2) && $past(count_up,1)
            |-> (count == $past(count,2) + 4'd2)
    );

    // Two-cycle down: -2 (mod 16) when count_up = 0 for two cycles.
    check_two_step_down: assert property (
        @(posedge clk) disable iff (reset)
            $past(!reset,2) && $past(!reset,1) && !$past(count_up,2) && !$past(count_up,1)
            |-> (count == $past(count,2) - 4'd2)
    );

    // LSB toggles on every active step (increment or decrement).
    check_lsb_toggles: assert property (
        @(posedge clk) disable iff (reset) $past(!reset) |-> (count[0] == ~$past(count[0]))
    );
endmodule

rtl:
`define ADDER_WIDTH 010
`define DUMMY_WIDTH 128

`define 2_LEVEL_ADDER

module adder_tree_top (
	clk,
	isum0_0_0_0, isum0_0_0_1, isum0_0_1_0, isum0_0_1_1, isum0_1_0_0, isum0_1_0_1, isum0_1_1_0, isum0_1_1_1,
	sum,
);
	input clk;
	input [`ADDER_WIDTH+0-1:0] isum0_0_0_0, isum0_0_0_1, isum0_0_1_0, isum0_0_1_1, isum0_1_0_0, isum0_1_0_1, isum0_1_1_0, isum0_1_1_1;
	output [`ADDER_WIDTH  :0] sum;
	reg    [`ADDER_WIDTH  :0] sum;

	wire [`ADDER_WIDTH+3-1:0] sum0;
	wire [`ADDER_WIDTH+2-1:0] sum0_0, sum0_1;
	wire [`ADDER_WIDTH+1-1:0] sum0_0_0, sum0_0_1, sum0_1_0, sum0_1_1;
	reg  [`ADDER_WIDTH+0-1:0] sum0_0_0_0, sum0_0_0_1, sum0_0_1_0, sum0_0_1_1, sum0_1_0_0, sum0_1_0_1, sum0_1_1_0, sum0_1_1_1;

	adder_tree_branch L1_0(sum0_0,     sum0_1,     sum0    );
	defparam L1_0.EXTRA_BITS = 2;

	adder_tree_branch L2_0(sum0_0_0,   sum0_0_1,   sum0_0  );
	adder_tree_branch L2_1(sum0_1_0,   sum0_1_1,   sum0_1  );
	defparam L2_0.EXTRA_BITS = 1;
	defparam L2_1.EXTRA_BITS = 1;

	adder_tree_branch L3_0(sum0_0_0_0, sum0_0_0_1, sum0_0_0);
	adder_tree_branch L3_1(sum0_0_1_0, sum0_0_1_1, sum0_0_1);
	adder_tree_branch L3_2(sum0_1_0_0, sum0_1_0_1, sum0_1_0);
	adder_tree_branch L3_3(sum0_1_1_0, sum0_1_1_1, sum0_1_1);
	defparam L3_0.EXTRA_BITS = 0;
	defparam L3_1.EXTRA_BITS = 0;
	defparam L3_2.EXTRA_BITS = 0;
	defparam L3_3.EXTRA_BITS = 0;

	always @(posedge clk) begin
		sum0_0_0_0 <= isum0_0_0_0;
		sum0_0_0_1 <= isum0_0_0_1;
		sum0_0_1_0 <= isum0_0_1_0;
		sum0_0_1_1 <= isum0_0_1_1;
		sum0_1_0_0 <= isum0_1_0_0;
		sum0_1_0_1 <= isum0_1_0_1;
		sum0_1_1_0 <= isum0_1_1_0;
		sum0_1_1_1 <= isum0_1_1_1;

		`ifdef 3_LEVEL_ADDER
			sum <= sum0;
		`endif
		`ifdef 2_LEVEL_ADDER
			sum <= sum0_0;
		`endif
	end

endmodule

module adder_tree_branch(a,b,sum);
	parameter EXTRA_BITS = 0;

	input [`ADDER_WIDTH+EXTRA_BITS-1:0] a;
	input [`ADDER_WIDTH+EXTRA_BITS-1:0] b;
	output [`ADDER_WIDTH+EXTRA_BITS:0] sum;

	assign sum = a + b;
endmodule

sva:
module adder_tree_top_sva (
    input logic clk,
    input logic [`ADDER_WIDTH+0-1:0] isum0_0_0_0,
    input logic [`ADDER_WIDTH+0-1:0] isum0_0_0_1,
    input logic [`ADDER_WIDTH+0-1:0] isum0_0_1_0,
    input logic [`ADDER_WIDTH+0-1:0] isum0_0_1_1,
    input logic [`ADDER_WIDTH+0-1:0] isum0_1_0_0,
    input logic [`ADDER_WIDTH+0-1:0] isum0_1_0_1,
    input logic [`ADDER_WIDTH+0-1:0] isum0_1_1_0,
    input logic [`ADDER_WIDTH+0-1:0] isum0_1_1_1,
    input logic [`ADDER_WIDTH:0]     sum
);
    // Clock: clk posedge. No reset in RTL. Sequential pipeline with 1-cycle latency to sum (2_LEVEL_ADDER active).

    // Localparams for safe sizing without relying on macros outside this file.
    localparam int SW = $bits(sum);                  // sum width
    localparam int IW = $bits(isum0_0_0_0);          // input element width

    ///// Functional correctness (2-level tree selected) /////
    // Next-cycle sum equals truncated ((isum0_0_0_0+isum0_0_0_1) + (isum0_0_1_0+isum0_0_1_1)) from this cycle.
    check_sum_matches_two_level_tree: assert property (
        @(posedge clk)
        1'b1 |=> sum == (
            ( {1'b0, ({1'b0, isum0_0_0_0} + {1'b0, isum0_0_0_1})}
            + {1'b0, ({1'b0, isum0_0_1_0} + {1'b0, isum0_0_1_1})} )[SW-1:0]
        )
    );

    // Next-cycle sum equals truncated direct sum of the first four inputs from this cycle.
    check_sum_matches_flat_sum4: assert property (
        @(posedge clk)
        1'b1 |=> sum == (
            ( {2'b00, isum0_0_0_0} + {2'b00, isum0_0_0_1}
            + {2'b00, isum0_0_1_0} + {2'b00, isum0_0_1_1} )[SW-1:0]
        )
    );

    ///// Stability and dependence /////
    // If the first four inputs are stable this cycle, sum is stable next cycle.
    check_sum_stable_when_first4_stable: assert property (
        @(posedge clk)
        $stable({isum0_0_0_0, isum0_0_0_1, isum0_0_1_0, isum0_0_1_1}) |=> (sum == $past(sum))
    );

    // If sum changes from last cycle to this cycle, at least one of the first four inputs changed in the prior cycle step.
    check_sum_change_implies_first4_change: assert property (
        @(posedge clk)
        (sum != $past(sum)) |-> ($past({isum0_0_0_0, isum0_0_0_1, isum0_0_1_0, isum0_0_1_1}) != $past({isum0_0_0_0, isum0_0_0_1, isum0_0_1_0, isum0_0_1_1}, 2))
    );

    // Changes to the unused four inputs alone (with first four stable) do not affect next-cycle sum.
    check_unused_half_no_effect: assert property (
        @(posedge clk)
        $stable({isum0_0_0_0, isum0_0_0_1, isum0_0_1_0, isum0_0_1_1}) && $changed({isum0_1_0_0, isum0_1_0_1, isum0_1_1_0, isum0_1_1_1})
        |=> (sum == $past(sum))
    );

endmodule

rtl:
module flip_flop(
    input CLK,
    input D,
    input SCD,
    input SCE,
    input SET_B,
    input VPWR,
    input VGND,
    input VPB,
    input VNB,
    output Q,
    output Q_N
);

    reg [1:0] state;
    // Declare next_state as a reg type to make it a valid l-value
    reg [1:0] next_state;

    // Define the state transitions
    always @(*) begin
        case(state)
            2'b00: begin
                next_state = {SCD, SCE};
            end
            2'b01: begin
                next_state = {SCD, ~SET_B};
            end
            2'b10: begin
                next_state = {~SCE, SET_B};
            end
            2'b11: begin
                next_state = {~SCE, ~SET_B};
            end
        endcase
    end

    // Define the output functions
    assign Q = (state == 2'b10 || state == 2'b11) ? 1'b1 : 1'b0;
    assign Q_N = ~Q;

    // Define the state machine
    always @(posedge CLK) begin
        state <= next_state;
    end

endmodule

sva:
module flip_flop_sva (
    input logic CLK,
    input logic D,
    input logic SCD,
    input logic SCE,
    input logic SET_B,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB,
    input logic Q,
    input logic Q_N
);

    ///// Output relationship /////
    // Q_N is always the logical inverse of Q.
    check_qn_is_inverse_of_q: assert property (
        @(posedge CLK) Q_N == ~Q
    );

    ///// Next-state behavior of Q /////
    // If Q=1 and SCE=0, Q stays 1 next cycle.
    check_hold_one_when_sce_low: assert property (
        @(posedge CLK) (Q && (SCE == 1'b0)) |=> (Q == 1'b1)
    );
    // If Q=1 and SCE=1, Q becomes 0 next cycle.
    check_clear_when_sce_high: assert property (
        @(posedge CLK) (Q && (SCE == 1'b1)) |=> (Q == 1'b0)
    );
    // If Q=0 and SCD=1, Q becomes 1 next cycle.
    check_set_when_scd_high: assert property (
        @(posedge CLK) ((!Q) && (SCD == 1'b1)) |=> (Q == 1'b1)
    );
    // If Q=0 and SCD=0, Q stays 0 next cycle.
    check_hold_zero_when_scd_low: assert property (
        @(posedge CLK) ((!Q) && (SCD == 1'b0)) |=> (Q == 1'b0)
    );

    ///// Edge-cause checks /////
    // A falling edge on Q requires SCE was 1 in the prior cycle.
    check_q_fall_requires_sce_high: assert property (
        @(posedge CLK) $fell(Q) |-> $past(SCE)
    );
    // A rising edge on Q requires SCD was 1 in the prior cycle.
    check_q_rise_requires_scd_high: assert property (
        @(posedge CLK) $rose(Q) |-> $past(SCD)
    );

    ///// Complement edge correlation /////
    // When Q rises, Q_N falls the same cycle.
    check_qn_falls_when_q_rises: assert property (
        @(posedge CLK) $rose(Q) |-> $fell(Q_N)
    );
    // When Q falls, Q_N rises the same cycle.
    check_qn_rises_when_q_falls: assert property (
        @(posedge CLK) $fell(Q) |-> $rose(Q_N)
    );

endmodule

rtl:
module full_adder(
    input A,
    input B,
    input Cin,
    output S,
    output Cout
);

    assign S = A ^ B ^ Cin;
    assign Cout = (A & B) | (Cin & (A ^ B));

endmodule

module four_bit_adder(
    input [3:0] A,
    input [3:0] B,
    output [3:0] S,
    output Cout
);

    wire [3:0] c;
    wire [3:0] s;

    full_adder fa0(
        .A(A[0]),
        .B(B[0]),
        .Cin(1'b0),
        .S(s[0]),
        .Cout(c[0])
    );
    full_adder fa1(
        .A(A[1]),
        .B(B[1]),
        .Cin(c[0]),
        .S(s[1]),
        .Cout(c[1])
    );
    full_adder fa2(
        .A(A[2]),
        .B(B[2]),
        .Cin(c[1]),
        .S(s[2]),
        .Cout(c[2])
    );
    full_adder fa3(
        .A(A[3]),
        .B(B[3]),
        .Cin(c[2]),
        .S(s[3]),
        .Cout(Cout)
    );

    assign S = s;

endmodule

sva:
module four_bit_adder_sva (
    input logic CLK,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] S,
    input logic Cout
);
    // Final 5-bit sum must equal zero-extended A+B.
    check_sum_matches_addition: assert property (
        @(posedge CLK) {Cout, S} == ({1'b0, A} + {1'b0, B})
    );

    // LSB sum is XOR with Cin=0.
    check_s0_is_xor: assert property (
        @(posedge CLK) S[0] == (A[0] ^ B[0])
    );

    // Carry into bit1 equals A0&B0 (derived via S1 parity).
    check_carry_into_bit1: assert property (
        @(posedge CLK) (S[1] ^ A[1] ^ B[1]) == (A[0] & B[0])
    );

    // Bit1 sum equals XOR with carry from bit0.
    check_s1_is_xor_with_carry: assert property (
        @(posedge CLK) S[1] == (A[1] ^ B[1] ^ (A[0] & B[0]))
    );

    // Carry into bit2 equals (A1&B1) | ((A0&B0)&(A1^B1)).
    check_carry_into_bit2: assert property (
        @(posedge CLK) (S[2] ^ A[2] ^ B[2]) == ((A[1] & B[1]) | ((A[0] & B[0]) & (A[1] ^ B[1])))
    );

    // Bit2 sum equals XOR with computed carry into bit2.
    check_s2_is_xor_with_carry: assert property (
        @(posedge CLK) S[2] == (A[2] ^ B[2] ^ ((A[1] & B[1]) | ((A[0] & B[0]) & (A[1] ^ B[1]))))
    );

    // Carry into bit3 equals (A2&B2) | (c1&(A2^B2)) with c1 expanded.
    check_carry_into_bit3: assert property (
        @(posedge CLK) (S[3] ^ A[3] ^ B[3]) ==
            ((A[2] & B[2]) | (((A[1] & B[1]) | ((A[0] & B[0]) & (A[1] ^ B[1]))) & (A[2] ^ B[2])))
    );

    // Bit3 sum equals XOR with computed carry into bit3.
    check_s3_is_xor_with_carry: assert property (
        @(posedge CLK) S[3] == (A[3] ^ B[3] ^
            ((A[2] & B[2]) | (((A[1] & B[1]) | ((A[0] & B[0]) & (A[1] ^ B[1]))) & (A[2] ^ B[2]))))
    );

    // Cout equals (A3&B3) | (c2&(A3^B3)) with c2 expanded.
    check_cout_from_final_carry: assert property (
        @(posedge CLK) Cout ==
            ((A[3] & B[3]) | (
                ((A[2] & B[2]) | (((A[1] & B[1]) | ((A[0] & B[0]) & (A[1] ^ B[1]))) & (A[2] ^ B[2])))
                & (A[3] ^ B[3])
            ))
    );
endmodule

