module counter(input clk, input reset, input in, output p);
	reg [5-1:0] r;
	always @(posedge clk or posedge reset) begin
		if(reset)
			r <= 0;
		else begin
			if(r)
				r <= r + 5'b1;
			if(in)
				r <= 1;
		end
	end
	assign p = r == 20;
endmodule

sva:
module counter_sva (
    input logic clk,
    input logic reset,
    input logic in,
    input logic p,
    input logic [4:0] r
);
    // Reset drives r to 0 on the following clock.
    reset_clears_r: assert property (
        @(posedge clk) reset |-> (r == 5'd0)
    );

    // During reset, p must be 0.
    reset_drives_p_low: assert property (
        @(posedge clk) reset |-> (p == 1'b0)
    );

    // p is the combinational comparison (r == 20).
    p_matches_r_eq_20: assert property (
        @(posedge clk) disable iff (reset) p == (r == 5'd20)
    );

    // Exact next-state function for r; allow escape if reset rises between cycles.
    exact_next_state: assert property (
        @(posedge clk) disable iff (reset)
            1 |=> ($rose(reset) || (r == (in ? 5'd1 : ($past(r) != 5'd0 ? $past(r) + 5'd1 : $past(r)))))
    );

    // If previous r was nonzero and in is 0 now, r increments by 1 (mod 32).
    nonzero_increments_when_no_in: assert property (
        @(posedge clk) disable iff (reset)
            1 |=> ($rose(reset) || in || ($past(r) == 5'd0) || (r == $past(r) + 5'd1))
    );

    // If previous r was zero and in is 0 now, r stays at 0.
    zero_holds_when_no_in: assert property (
        @(posedge clk) disable iff (reset)
            1 |=> ($rose(reset) || in || ($past(r) != 5'd0) || (r == 5'd0))
    );

    // If in is 1 now, r is 1 now (assignment priority to 'in').
    in_forces_r_one: assert property (
        @(posedge clk) disable iff (reset)
            1 |=> ($rose(reset) || !in || (r == 5'd1))
    );

    // When previous r was 31 and in is 0 now, r wraps to 0.
    wrap_31_to_0: assert property (
        @(posedge clk) disable iff (reset)
            1 |=> ($rose(reset) || in || ($past(r) != 5'd31) || (r == 5'd0))
    );
endmodule

rtl:
module hd_data_reader (
    input           clk,
    input           rst,

    input           enable,
    output  reg     error,

    input           hd_read_from_host,
    input   [31:0]  hd_data_from_host
);

//Registers/Wires
reg                 prev_enable;
wire                posedge_enable;
reg         [31:0]  test_data;

//Submodules

//Asynchronous Logic
assign              posedge_enable = (!prev_enable && enable);

//Synchronous Logic
always @ (posedge clk) begin
    if (rst) begin
        prev_enable         <=  0;
        error               <=  0;
        test_data           <=  0;
    end
    else begin
        prev_enable         <=  enable;
        if (posedge_enable) begin
            error           <=  0;
            test_data       <=  0;
        end
        else begin
            if (hd_read_from_host) begin
                if (hd_data_from_host != test_data) begin
                    error   <=  1;
                end
                test_data   <=  test_data + 1;
            end
        end
    end
end


endmodule

sva:
module hd_data_reader_sva (
    input logic        clk,
    input logic        rst,                 // active-high synchronous reset
    input logic        enable,
    input logic        error,
    input logic        hd_read_from_host,
    input logic [31:0] hd_data_from_host
);
    ///// Reset behavior /////
    // Synchronous reset drives error low by the next cycle.
    reset_clears_error_next: assert property (
        @(posedge clk) rst |=> (error == 1'b0)
    );

    ///// Error clearing on enable rising edge /////
    // Rising edge of enable clears error by the next cycle.
    enable_rise_clears_error: assert property (
        @(posedge clk) disable iff (rst) $rose(enable) |=> (error == 1'b0)
    );

    ///// Error transition rules /////
    // error can only fall due to reset or a rising enable in the previous cycle.
    error_fall_requires_clear_event_prev: assert property (
        @(posedge clk) disable iff (rst)
            $fell(error) |-> ($past(rst,1,1'b0) || ($past(enable,1,1'b0) && !$past(enable,2,1'b0)))
    );

    // error rising requires a host read in the previous cycle.
    error_rise_requires_read_prev: assert property (
        @(posedge clk) disable iff (rst)
            $rose(error) |-> $past(hd_read_from_host,1,1'b0)
    );

    // error rising cannot occur if previous cycle had reset or rising enable.
    error_rise_not_after_prev_reset_or_enrise: assert property (
        @(posedge clk) disable iff (rst)
            $rose(error) |-> (!$past(rst,1,1'b0) && !($past(enable,1,1'b0) && !$past(enable,2,1'b0)))
    );

    // If previous cycle had no read and no rising enable, error must not rise.
    no_error_rise_without_prev_read_or_enrise: assert property (
        @(posedge clk) disable iff (rst)
            (!$past(hd_read_from_host,1,1'b0) && !($past(enable,1,1'b0) && !$past(enable,2,1'b0)))
            |-> !$rose(error)
    );

    // If error was high and previous cycle had no clear event, it remains high.
    error_sticky_without_prev_clear: assert property (
        @(posedge clk) disable iff (rst)
            ($past(error,1,1'b0) && !($past(enable,1,1'b0) && !$past(enable,2,1'b0)))
            |-> (error == 1'b1)
    );

    // With no read and no rising enable in the previous cycle, error is stable.
    error_stable_without_prev_activity: assert property (
        @(posedge clk) disable iff (rst)
            (!$past(hd_read_from_host,1,1'b0) && !($past(enable,1,1'b0) && !$past(enable,2,1'b0)))
            |-> $stable(error)
    );

endmodule

rtl:
module add_sub (
    input [31:0] a,
    input [31:0] b,
    input sub,
    output [31:0] result
);

    wire [31:0] sum;
    wire [31:0] diff;
    wire [31:0] select;

    assign select = sub ? ~b : b;

    assign sum = a + select;
    assign diff = sub ? ~select : select;

    assign result = sub ? diff : sum;

endmodule

module transition_detector (
    input clk,
    input reset,
    input [31:0] in,
    output reg out
);

    reg [31:0] prev;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            prev <= 0;
            out <= 0;
        end
        else begin
            if (in[0] && !prev[0]) begin
                out <= 1;
            end
            else if (!in[0] && prev[0]) begin
                out <= 0;
            end
            prev <= in;
        end
    end

endmodule

module top_module (
    input clk,
    input reset,
    input [31:0] a,
    input [31:0] b,
    input sub,
    input [31:0] in,
    output [31:0] out
);

    wire [31:0] add_sub_result;
    wire transition_detector_result;

    add_sub add_sub_inst (
        .a(a),
        .b(b),
        .sub(sub),
        .result(add_sub_result)
    );

    transition_detector transition_detector_inst (
        .clk(clk),
        .reset(reset),
        .in(in),
        .out(transition_detector_result)
    );

    assign out = transition_detector_result ? add_sub_result - in : add_sub_result + in;

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic reset,
    input logic [31:0] a,
    input logic [31:0] b,
    input logic sub,
    input logic [31:0] in,
    input logic [31:0] out
);
    // Clock: clk; Reset: reset (active-high). Mixed: add_sub combinational; transition_detector sequential; top combines both.

    ///// Reset behavior /////
    // During reset, transition_detector output is 0 => out = base + in.
    check_out_plus_during_reset: assert property (
        @(posedge clk) reset |-> (out == ((sub ? b : (a + b)) + in))
    );

    ///// Edge-driven selection of add/sub on in[0] rising /////
    // On in[0] rising edge with sub==0, out = (a+b) - in that cycle.
    check_rise_sub0_minus: assert property (
        @(posedge clk) disable iff (reset) ($rose(in[0]) && (sub == 1'b0)) |-> (out == ((a + b) - in))
    );
    // On in[0] rising edge with sub==1, out = b - in that cycle.
    check_rise_sub1_minus: assert property (
        @(posedge clk) disable iff (reset) ($rose(in[0]) && (sub == 1'b1)) |-> (out == (b - in))
    );

    ///// Edge-driven selection of add/sub on in[0] falling /////
    // On in[0] falling edge with sub==0, out = (a+b) + in that cycle.
    check_fall_sub0_plus: assert property (
        @(posedge clk) disable iff (reset) ($fell(in[0]) && (sub == 1'b0)) |-> (out == ((a + b) + in))
    );
    // On in[0] falling edge with sub==1, out = b + in that cycle.
    check_fall_sub1_plus: assert property (
        @(posedge clk) disable iff (reset) ($fell(in[0]) && (sub == 1'b1)) |-> (out == (b + in))
    );

    ///// One-cycle hold after edge when in[0] remains level /////
    // After a rise, if in[0] stays high next cycle, out remains base - in.
    check_hold_after_rise_one_cycle: assert property (
        @(posedge clk) disable iff (reset) $rose(in[0]) ##1 (in[0] == 1'b1) |-> (out == ((sub ? b : (a + b)) - in))
    );
    // After a fall, if in[0] stays low next cycle, out remains base + in.
    check_hold_after_fall_one_cycle: assert property (
        @(posedge clk) disable iff (reset) $fell(in[0]) ##1 (in[0] == 1'b0) |-> (out == ((sub ? b : (a + b)) + in))
    );

    ///// Post-reset first active clock behavior /////
    // Immediately after reset deasserts, if in[0]==1, out = base - in.
    check_post_reset_deassert_high_lsb: assert property (
        @(posedge clk) $fell(reset) && (in[0] == 1'b1) |-> (out == ((sub ? b : (a + b)) - in))
    );
    // Immediately after reset deasserts, if in[0]==0, out = base + in.
    check_post_reset_deassert_low_lsb: assert property (
        @(posedge clk) $fell(reset) && (in[0] == 1'b0) |-> (out == ((sub ? b : (a + b)) + in))
    );

    ///// Arithmetic consistency at transition edges /////
    // On in[0] rising edge, out + in equals base.
    check_rise_arith_consistency: assert property (
        @(posedge clk) disable iff (reset) $rose(in[0]) |-> ((out + in) == (sub ? b : (a + b)))
    );
    // On in[0] falling edge, out - in equals base.
    check_fall_arith_consistency: assert property (
        @(posedge clk) disable iff (reset) $fell(in[0]) |-> ((out - in) == (sub ? b : (a + b)))
    );

endmodule

