module parity_check (
    input A,
    input B,
    input C,
    input D,
    output parity
);

    wire ab, cd, abcd;

    xor(ab, A, B);
    xor(cd, C, D);
    xor(abcd, ab, cd);
    assign parity = abcd;

endmodule

sva:
module parity_check_sva (
    input logic CLK,
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic parity
);

    // parity equals XOR of all inputs
    check_parity_function: assert property (
        @(posedge CLK) parity == (A ^ B ^ C ^ D)
    );

    // If inputs are stable, parity must be stable
    check_parity_stable_on_inputs_stable: assert property (
        @(posedge CLK) $stable({A,B,C,D}) |-> $stable(parity)
    );

    // If only A changes, parity must change
    check_single_change_A_toggles_parity: assert property (
        @(posedge CLK) $changed(A) && $stable(B) && $stable(C) && $stable(D) |-> $changed(parity)
    );

    // If only B changes, parity must change
    check_single_change_B_toggles_parity: assert property (
        @(posedge CLK) $changed(B) && $stable(A) && $stable(C) && $stable(D) |-> $changed(parity)
    );

    // If only C changes, parity must change
    check_single_change_C_toggles_parity: assert property (
        @(posedge CLK) $changed(C) && $stable(A) && $stable(B) && $stable(D) |-> $changed(parity)
    );

    // If only D changes, parity must change
    check_single_change_D_toggles_parity: assert property (
        @(posedge CLK) $changed(D) && $stable(A) && $stable(B) && $stable(C) |-> $changed(parity)
    );

    // If A and B both change and C,D stable, parity must be unchanged
    check_two_changes_AB_hold_parity: assert property (
        @(posedge CLK) $changed(A) && $changed(B) && $stable(C) && $stable(D) |-> $stable(parity)
    );

    // If A and C both change and B,D stable, parity must be unchanged
    check_two_changes_AC_hold_parity: assert property (
        @(posedge CLK) $changed(A) && $changed(C) && $stable(B) && $stable(D) |-> $stable(parity)
    );

    // If A and D both change and B,C stable, parity must be unchanged
    check_two_changes_AD_hold_parity: assert property (
        @(posedge CLK) $changed(A) && $changed(D) && $stable(B) && $stable(C) |-> $stable(parity)
    );

    // If B and C both change and A,D stable, parity must be unchanged
    check_two_changes_BC_hold_parity: assert property (
        @(posedge CLK) $changed(B) && $changed(C) && $stable(A) && $stable(D) |-> $stable(parity)
    );

    // If B and D both change and A,C stable, parity must be unchanged
    check_two_changes_BD_hold_parity: assert property (
        @(posedge CLK) $changed(B) && $changed(D) && $stable(A) && $stable(C) |-> $stable(parity)
    );

    // If C and D both change and A,B stable, parity must be unchanged
    check_two_changes_CD_hold_parity: assert property (
        @(posedge CLK) $changed(C) && $changed(D) && $stable(A) && $stable(B) |-> $stable(parity)
    );

endmodule

rtl:
module priority_encoder (
    input [3:0] in,
    output reg [1:0] pos
);
    always @(*) begin
        case (in)
            4'b1000: pos = 2'b11;
            4'b0100: pos = 2'b10;
            4'b0010: pos = 2'b01;
            4'b0001: pos = 2'b00;
            default: pos = 2'b00;
        endcase
    end
endmodule

module counter (
    input clk,
    input reset,
    input enable,
    output reg [7:0] count
);
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            count <= 8'b0;
        end else if (enable) begin
            count <= count + 1;
        end
    end
endmodule

module top_module (
    input clk,
    input reset,
    input [3:0] in,
    output reg [1:0] pos,
    output reg [7:0] out
);
    wire enable;
    reg [7:0] count;

    priority_encoder pe (
        .in(in),
        .pos(pos)
    );

    assign enable = (pos == 2'b11) ? 1 : 0;

    counter cnt (
        .clk(clk),
        .reset(reset),
        .enable(enable),
        .count(count)
    );

    always @(*) begin
        out = count[7:0] * in;
    end
endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic reset,        // Active-high reset
    input logic [3:0] in,
    input logic [1:0] pos,
    input logic [7:0] out
);
    ///// Priority encoder mapping /////
    // If in=1000 then pos must be 11.
    pe_map_in_1000_to_pos_11: assert property (
        @(posedge clk) disable iff (reset) (in == 4'b1000) |-> (pos == 2'b11)
    );
    // If in=0100 then pos must be 10.
    pe_map_in_0100_to_pos_10: assert property (
        @(posedge clk) disable iff (reset) (in == 4'b0100) |-> (pos == 2'b10)
    );
    // If in=0010 then pos must be 01.
    pe_map_in_0010_to_pos_01: assert property (
        @(posedge clk) disable iff (reset) (in == 4'b0010) |-> (pos == 2'b01)
    );
    // If in=0001 then pos must be 00.
    pe_map_in_0001_to_pos_00: assert property (
        @(posedge clk) disable iff (reset) (in == 4'b0001) |-> (pos == 2'b00)
    );
    // For all other in values, pos must be 00 (default case).
    pe_default_others_to_pos_00: assert property (
        @(posedge clk) disable iff (reset) (in != 4'b1000 && in != 4'b0100 && in != 4'b0010 && in != 4'b0001) |-> (pos == 2'b00)
    );
    // pos=11 can only occur when in=1000.
    pe_pos_11_implies_1000: assert property (
        @(posedge clk) disable iff (reset) (pos == 2'b11) |-> (in == 4'b1000)
    );
    // pos=10 can only occur when in=0100.
    pe_pos_10_implies_0100: assert property (
        @(posedge clk) disable iff (reset) (pos == 2'b10) |-> (in == 4'b0100)
    );
    // pos=01 can only occur when in=0010.
    pe_pos_01_implies_0010: assert property (
        @(posedge clk) disable iff (reset) (pos == 2'b01) |-> (in == 4'b0010)
    );
    // pos must be stable across cycles when in is stable (pure combinational mapping).
    pe_pos_stable_when_in_stable: assert property (
        @(posedge clk) disable iff (reset) $stable(in) |-> $stable(pos)
    );

    ///// Counter/out behavior (observed via product) /////
    // While reset is asserted, out must be 0 (count is held at 0).
    out_zero_during_reset: assert property (
        @(posedge clk) reset |-> (out == 8'b0)
    );
    // If in=0000, out must be 0 (multiplication by zero).
    out_zero_when_in_zero: assert property (
        @(posedge clk) disable iff (reset) (in == 4'b0000) |-> (out == 8'b0)
    );
    // If in=0010 (x2), LSB must be 0.
    out_lsb0_zero_when_in_0010: assert property (
        @(posedge clk) disable iff (reset) (in == 4'b0010) |-> (out[0] == 1'b0)
    );
    // If in=0100 (x4), two LSBs must be 0.
    out_lsb01_zero_when_in_0100: assert property (
        @(posedge clk) disable iff (reset) (in == 4'b0100) |-> (out[1:0] == 2'b00)
    );
    // If in=1000 (x8), three LSBs must be 0.
    out_lsb012_zero_when_in_1000: assert property (
        @(posedge clk) disable iff (reset) (in == 4'b1000) |-> (out[2:0] == 3'b000)
    );
    // With in=1000 held stable across cycles, out must increment by 8 (mod 256) each cycle.
    out_increments_by_8_when_in_1000_stable: assert property (
        @(posedge clk) disable iff (reset) ($past(reset) == 1'b0 && $past(in) == 4'b1000 && in == 4'b1000) |-> (out == $past(out) + 8'd8)
    );
    // If in is stable and pos!=11 across cycles (no enable), out must be stable.
    out_stable_when_no_increment: assert property (
        @(posedge clk) disable iff (reset) ($past(reset) == 1'b0 && $past(in) == in && $past(pos) != 2'b11 && pos != 2'b11) |-> $stable(out)
    );
endmodule

rtl:
module mux_2to1(
    input A0,
    input A1,
    input S,
    output X
);

assign X = (S == 1'b0) ? A0 : A1;

endmodule

sva:
module mux_2to1_sva (
    input logic clk,
    input logic A0,
    input logic A1,
    input logic S,
    input logic X
);
    // When S is 0, output must equal A0.
    check_select0_passes_A0: assert property (
        @(posedge clk) (S === 1'b0) |-> (X === A0)
    );

    // When S is 1, output must equal A1.
    check_select1_passes_A1: assert property (
        @(posedge clk) (S === 1'b1) |-> (X === A1)
    );

    // Functional equivalence with the RTL conditional expression.
    check_functional_equation: assert property (
        @(posedge clk) X === ((S == 1'b0) ? A0 : A1)
    );

    // If A0 and A1 are equal (4-state), X must equal that value regardless of S.
    check_equal_inputs_override: assert property (
        @(posedge clk) (A0 === A1) |-> (X === A0)
    );

    // If inputs and select are stable, output must be stable.
    check_stable_inputs_hold_output: assert property (
        @(posedge clk) $stable({S, A0, A1}) |-> $stable(X)
    );

    // With S=0, any change on A0 must be reflected on X.
    check_A0_change_reflected_when_S0: assert property (
        @(posedge clk) (S === 1'b0 && $changed(A0)) |-> (X === A0)
    );

    // With S=1, any change on A1 must be reflected on X.
    check_A1_change_reflected_when_S1: assert property (
        @(posedge clk) (S === 1'b1 && $changed(A1)) |-> (X === A1)
    );

    // If S is unknown and A0!=A1, X must be unknown (x-merge behavior).
    check_unknown_select_diff_inputs_yield_unknown: assert property (
        @(posedge clk) ($isunknown(S) && (A0 !== A1)) |-> $isunknown(X)
    );

    // With S=0 and A0 known, X must be known (and equal to A0).
    check_known_output_when_S0_and_A0_known: assert property (
        @(posedge clk) (S === 1'b0 && !$isunknown(A0)) |-> (!$isunknown(X) && X === A0)
    );

    // With S=1 and A1 known, X must be known (and equal to A1).
    check_known_output_when_S1_and_A1_known: assert property (
        @(posedge clk) (S === 1'b1 && !$isunknown(A1)) |-> (!$isunknown(X) && X === A1)
    );
endmodule

module pcie_7x_0_core_top_gtp_cpllpd_ovrd_sva (
    input  logic         i_ibufds_gte2,
    input  logic         o_cpllpd_ovrd,
    input  logic         o_cpllreset_ovrd,
    input  logic [95:0]  cpllpd_wait,
    input  logic [127:0] cpllreset_wait
);
    // Clock: i_ibufds_gte2 (posedge). No reset port in RTL.

    // cpllpd_wait shifts left by 1 and inserts 0 at LSB each clk.
    check_cpllpd_wait_shift: assert property (
        @(posedge i_ibufds_gte2) !$initstate |-> (cpllpd_wait == { $past(cpllpd_wait[94:0]), 1'b0 })
    );

    // cpllreset_wait shifts left by 1 and inserts 0 at LSB each clk.
    check_cpllreset_wait_shift: assert property (
        @(posedge i_ibufds_gte2) !$initstate |-> (cpllreset_wait == { $past(cpllreset_wait[126:0]), 1'b0 })
    );

    // cpllpd_wait MSB equals previous bit[94].
    check_cpllpd_msb_follows_bit94: assert property (
        @(posedge i_ibufds_gte2) !$initstate |-> (cpllpd_wait[95] == $past(cpllpd_wait[94]))
    );

    // cpllreset_wait MSB equals previous bit[126].
    check_cpllreset_msb_follows_bit126: assert property (
        @(posedge i_ibufds_gte2) !$initstate |-> (cpllreset_wait[127] == $past(cpllreset_wait[126]))
    );

    // After the first update, cpllpd_wait LSB is always 0.
    check_cpllpd_lsb_zero: assert property (
        @(posedge i_ibufds_gte2) !$initstate |-> (cpllpd_wait[0] == 1'b0)
    );

    // After the first update, cpllreset_wait LSB is always 0.
    check_cpllreset_lsb_zero: assert property (
        @(posedge i_ibufds_gte2) !$initstate |-> (cpllreset_wait[0] == 1'b0)
    );

    // o_cpllpd_ovrd equals cpllpd_wait MSB.
    map_o_cpllpd_to_msb: assert property (
        @(posedge i_ibufds_gte2) (o_cpllpd_ovrd == cpllpd_wait[95])
    );

    // o_cpllreset_ovrd equals cpllreset_wait MSB.
    map_o_cpllreset_to_msb: assert property (
        @(posedge i_ibufds_gte2) (o_cpllreset_ovrd == cpllreset_wait[127])
    );

    // With zero-fill shifting, cpllpd_wait becomes all-zero 96 cycles later from any time.
    eventually_zero_cpllpd_wait: assert property (
        @(posedge i_ibufds_gte2) 1'b1 |-> ##96 (cpllpd_wait == 96'b0)
    );

    // With zero-fill shifting, cpllreset_wait becomes all-zero 128 cycles later from any time.
    eventually_zero_cpllreset_wait: assert property (
        @(posedge i_ibufds_gte2) 1'b1 |-> ##128 (cpllreset_wait == 128'b0)
    );

    // Consequently, o_cpllpd_ovrd is 0 96 cycles later from any time.
    eventually_zero_o_cpllpd: assert property (
        @(posedge i_ibufds_gte2) 1'b1 |-> ##96 (o_cpllpd_ovrd == 1'b0)
    );

    // Consequently, o_cpllreset_ovrd is 0 128 cycles later from any time.
    eventually_zero_o_cpllreset: assert property (
        @(posedge i_ibufds_gte2) 1'b1 |-> ##128 (o_cpllreset_ovrd == 1'b0)
    );

    // Initial contents per RTL: cpllpd_wait all 1s; cpllreset_wait has 8 LSB 1s.
    init_shift_regs_correct: assert property (
        @(posedge i_ibufds_gte2) $initstate |-> (cpllpd_wait == 96'hFFFFFFFFFFFFFFFFFFFFFFFF) && (cpllreset_wait == 128'h000000000000000000000000000000FF)
    );

    // Initial output levels per RTL mapping (MSBs of initial registers).
    init_outputs_levels: assert property (
        @(posedge i_ibufds_gte2) $initstate |-> (o_cpllpd_ovrd == 1'b1) && (o_cpllreset_ovrd == 1'b0)
    );

    // From init, o_cpllpd_ovrd stays HIGH for the first 96 cycles.
    init_o_cpllpd_high_96: assert property (
        @(posedge i_ibufds_gte2) $initstate |-> (o_cpllpd_ovrd [*96])
    );

    // From init, o_cpllreset_ovrd stays LOW for the first 120 cycles.
    init_o_cpllreset_low_120: assert property (
        @(posedge i_ibufds_gte2) $initstate |-> (!o_cpllreset_ovrd [*120])
    );

    // From init, o_cpllreset_ovrd is HIGH for 8 cycles starting at cycle 120.
    init_o_cpllreset_high_window: assert property (
        @(posedge i_ibufds_gte2) $initstate |-> ##120 (o_cpllreset_ovrd [*8])
    );
endmodule

rtl:
module t_order_a (
   m_from_clk_lev1_r, n_from_clk_lev2, o_from_com_levs11,
   o_from_comandclk_levs12,
   clk, a_to_clk_levm3, b_to_clk_levm1, c_com_levs10, d_to_clk_levm2, one
   );

   input clk;
   input [7:0] a_to_clk_levm3;
   input [7:0] b_to_clk_levm1;
   input [7:0] c_com_levs10;
   input [7:0] d_to_clk_levm2;
   input [7:0] one;
   output [7:0] m_from_clk_lev1_r;
   output [7:0] n_from_clk_lev2;
   output [7:0] o_from_com_levs11;
   output [7:0] o_from_comandclk_levs12;


   reg [7:0]            m_from_clk_lev1_r;
   wire [7:0] a_to_clk_levm1;
   wire [7:0] a_to_clk_levm2;
   wire [7:0] c_com_levs11;
   reg [7:0]  o_from_comandclk_levs12;
   wire [7:0]  n_from_clk_lev2;
   wire [7:0]  n_from_clk_lev3;

   assign     a_to_clk_levm1 = a_to_clk_levm2 + d_to_clk_levm2;
   assign     a_to_clk_levm2 = a_to_clk_levm3 + 0;

   always @ (posedge clk) begin
      m_from_clk_lev1_r <= a_to_clk_levm1 + b_to_clk_levm1;
   end

   assign c_com_levs11 = c_com_levs10 + one;
   always @ (c_com_levs11 or n_from_clk_lev3) o_from_comandclk_levs12 = c_com_levs11 + n_from_clk_lev3;
   assign n_from_clk_lev2 = m_from_clk_lev1_r;
   assign n_from_clk_lev3 = n_from_clk_lev2;
   wire [7:0] o_from_com_levs11 = c_com_levs10 + 1;

endmodule

sva:
module t_order_a_sva (
    input logic clk,
    input logic [7:0] a_to_clk_levm3,
    input logic [7:0] b_to_clk_levm1,
    input logic [7:0] c_com_levs10,
    input logic [7:0] d_to_clk_levm2,
    input logic [7:0] one,
    input logic [7:0] m_from_clk_lev1_r,
    input logic [7:0] n_from_clk_lev2,
    input logic [7:0] o_from_com_levs11,
    input logic [7:0] o_from_comandclk_levs12
);
    // Clock: clk; no reset present
    // Mixed logic: m_from_clk_lev1_r is sequential; others are combinational
    // Key relations: m = reg((a+d)+b); n = m; o_com = c+1; o_cmdclk = (c+one)+n

    // m_from_clk_lev1_r updates each clk to (a_to_clk_levm3 + d_to_clk_levm2 + b_to_clk_levm1) truncated to 8b.
    check_m_from_clk_lev1_r_update_seq: assert property (
        @(posedge clk) !$initstate |-> ( m_from_clk_lev1_r == $past( ((a_to_clk_levm3 + d_to_clk_levm2) + b_to_clk_levm1)[7:0] ) )
    );

    // n_from_clk_lev2 continuously mirrors m_from_clk_lev1_r.
    check_n_from_clk_lev2_mirror_m: assert property (
        @(posedge clk) n_from_clk_lev2 == m_from_clk_lev1_r
    );

    // n_from_clk_lev2 equals the registered sum from prior cycle as well.
    check_n_from_clk_lev2_seq_sum: assert property (
        @(posedge clk) !$initstate |-> ( n_from_clk_lev2 == $past( ((a_to_clk_levm3 + d_to_clk_levm2) + b_to_clk_levm1)[7:0] ) )
    );

    // o_from_com_levs11 equals c_com_levs10 + 1 (8-bit wrap).
    check_o_from_com_levs11_inc1: assert property (
        @(posedge clk) o_from_com_levs11 == ( (c_com_levs10 + 8'd1) [7:0] )
    );

    // o_from_comandclk_levs12 equals (c_com_levs10 + one + n_from_clk_lev2) truncated to 8b.
    check_o_from_comandclk_levs12_expr_n: assert property (
        @(posedge clk) o_from_comandclk_levs12 == ( ((c_com_levs10 + one) + n_from_clk_lev2) [7:0] )
    );

    // o_from_comandclk_levs12 also equals (c_com_levs10 + one + m_from_clk_lev1_r) truncated to 8b.
    check_o_from_comandclk_levs12_expr_m: assert property (
        @(posedge clk) o_from_comandclk_levs12 == ( ((c_com_levs10 + one) + m_from_clk_lev1_r) [7:0] )
    );

    // If n_from_clk_lev2 changes between cycles, m_from_clk_lev1_r must also change.
    check_n_change_implies_m_change: assert property (
        @(posedge clk) (!$initstate && $changed(n_from_clk_lev2)) |-> $changed(m_from_clk_lev1_r)
    );

    // If m_from_clk_lev1_r changes between cycles, n_from_clk_lev2 must also change.
    check_m_change_implies_n_change: assert property (
        @(posedge clk) (!$initstate && $changed(m_from_clk_lev1_r)) |-> $changed(n_from_clk_lev2)
    );

    // If (c_com_levs10, one, n_from_clk_lev2) are stable across a cycle, o_from_comandclk_levs12 must be stable.
    check_o_cmdclk_stable_when_inputs_stable: assert property (
        @(posedge clk) (!$initstate && $stable(c_com_levs10) && $stable(one) && $stable(n_from_clk_lev2)) |-> $stable(o_from_comandclk_levs12)
    );

    // If o_from_comandclk_levs12 changes, at least one of (c_com_levs10, one, n_from_clk_lev2) changed.
    check_o_cmdclk_change_implies_input_change: assert property (
        @(posedge clk) (!$initstate && $changed(o_from_comandclk_levs12)) |-> ($changed(c_com_levs10) || $changed(one) || $changed(n_from_clk_lev2))
    );

    // If c_com_levs10 is stable across a cycle, o_from_com_levs11 must be stable.
    check_o_com_stable_when_c_stable: assert property (
        @(posedge clk) (!$initstate && $stable(c_com_levs10)) |-> $stable(o_from_com_levs11)
    );

    // If o_from_com_levs11 changes, c_com_levs10 must have changed.
    check_o_com_change_implies_c_change: assert property (
        @(posedge clk) (!$initstate && $changed(o_from_com_levs11)) |-> $changed(c_com_levs10)
    );

endmodule

rtl:
module up_down_counter (
    input clk,
    input reset,
    input up_down,
    input load,
    input [3:0] data_in,
    output reg [3:0] count
);

    always @ (posedge clk or posedge reset) begin
        if (reset) begin
            count <= 4'b0000;
        end else if (load) begin
            count <= data_in;
        end else if (up_down) begin
            count <= count + 1;
        end else begin
            count <= count - 1;
        end
    end
endmodule

module top_module (
    input clk,
    input reset,
    input up_down,
    input load,
    input [3:0] data_in,
    output wire [3:0] count,
    output wire [3:0] sum
);
    wire [3:0] up_count, down_count;

    up_down_counter up_counter (
        .clk(clk),
        .reset(reset),
        .up_down(1'b1),
        .load(load),
        .data_in(data_in),
        .count(up_count)
    );

    up_down_counter down_counter (
        .clk(clk),
        .reset(reset),
        .up_down(1'b0),
        .load(load),
        .data_in(data_in),
        .count(down_count)
    );

    assign count = up_down ? up_count : down_count;
    assign sum = up_count + down_count;
endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic reset,
    input logic up_down,
    input logic load,
    input logic [3:0] data_in,
    input logic [3:0] count,
    input logic [3:0] sum
);
    // Reset drives outputs to zero.
    check_reset_outputs_zero: assert property (
        @(posedge clk) reset |-> (count == 4'h0) && (sum == 4'h0)
    );

    // On load, next cycle count equals data_in.
    check_count_load_next: assert property (
        @(posedge clk) disable iff (reset) load |=> (count == $past(data_in))
    );

    // On load, next cycle sum equals data_in + data_in (mod 16).
    check_sum_load_next: assert property (
        @(posedge clk) disable iff (reset) load |=> (sum == (($past(data_in) + $past(data_in)) & 4'hF))
    );

    // With no load in consecutive cycles, sum holds its previous value.
    check_sum_stable_no_load: assert property (
        @(posedge clk) disable iff (reset) ($past(!reset) && !load && !$past(load)) |-> (sum == $past(sum))
    );

    // If sum changes, a load must have occurred in the previous cycle.
    check_sum_change_implies_prev_load: assert property (
        @(posedge clk) disable iff (reset) ($past(!reset) && (sum != $past(sum))) |-> $past(load)
    );

    // With up_down=1 and no load in consecutive cycles, count increments by 1 (mod 16).
    check_count_inc_when_up: assert property (
        @(posedge clk) disable iff (reset)
            ( $past(!reset) && up_down && $past(up_down) && !load && !$past(load) )
            |-> (count == (($past(count) + 4'd1) & 4'hF))
    );

    // With up_down=0 and no load in consecutive cycles, count decrements by 1 (mod 16).
    check_count_dec_when_down: assert property (
        @(posedge clk) disable iff (reset)
            ( $past(!reset) && !up_down && !$past(up_down) && !load && !$past(load) )
            |-> (count == (($past(count) - 4'd1) & 4'hF))
    );

    // First cycle after reset deasserts, sum is zero.
    check_sum_zero_after_reset_release: assert property (
        @(posedge clk) ($past(reset) && !reset) |-> (sum == 4'h0)
    );

    // On back-to-back load cycles, count tracks the previous cycle's data_in each time.
    check_count_back_to_back_loads: assert property (
        @(posedge clk) disable iff (reset) ($past(!reset) && load && $past(load)) |-> (count == $past(data_in))
    );
endmodule

rtl:
module fletcher_checksum (
  input [7:0] data,
  input rst,
  input clk,
  output reg [15:0] sum
);

  reg [7:0] byte_count;
  reg [15:0] sum_temp;
  reg [15:0] sum_prev;
  reg [15:0] sum_final;
  reg [1:0] state;

  always @(posedge clk) begin
    if (rst) begin
      state <= 2'b00;
      byte_count <= 8'd0;
      sum_temp <= 16'd0;
      sum_prev <= 16'd0;
      sum_final <= 16'd0;
      sum <= 16'd0;
    end
    else begin
      case (state)
        2'b00: begin // State 0: Add byte to sum_temp
          sum_temp <= sum_temp + data;
          byte_count <= byte_count + 8'd1;
          state <= 2'b01;
        end
        2'b01: begin // State 1: Add sum_temp to sum_prev
          sum_prev <= sum_prev + sum_temp;
          sum_temp <= 16'd0;
          if (byte_count == 8'd255) begin
            state <= 2'b10;
          end
          else begin
            state <= 2'b00;
          end
        end
        2'b10: begin // State 2: Truncate final sum and output
          sum_final <= sum_prev % 16'd255;
          sum <= sum_final;
          state <= 2'b11;
        end
        2'b11: begin // State 3: Check checksum
          if (sum_final == data) begin
            state <= 2'b00;
          end
          else begin
            state <= 2'b11;
          end
        end
      endcase
    end
  end

endmodule

sva:
module fletcher_checksum_sva (
  input logic clk,
  input logic rst,
  input logic [7:0] data,
  input logic [15:0] sum,
  input logic [7:0] byte_count,
  input logic [15:0] sum_temp,
  input logic [15:0] sum_prev,
  input logic [15:0] sum_final,
  input logic [1:0] state
);

  ///// Reset behavior /////
  // Synchronous reset drives all registers to zero and state to 2'b00.
  reset_values: assert property (
    @(posedge clk) rst |-> (state == 2'b00) && (byte_count == 8'd0) && (sum_temp == 16'd0) &&
                    (sum_prev == 16'd0) && (sum_final == 16'd0) && (sum == 16'd0)
  );

  ///// State 2'b00 behavior /////
  // In state 2'b00, next state is 2'b01.
  state00_next_is_01: assert property (
    @(posedge clk) disable iff (rst) (state == 2'b00) |=> (state == 2'b01)
  );
  // In state 2'b00, sum_temp adds data and byte_count increments by 1.
  state00_updates: assert property (
    @(posedge clk) disable iff (rst) (state == 2'b00) |=> 
      (sum_temp == $past(sum_temp) + data) && (byte_count == $past(byte_count) + 8'd1)
  );

  ///// State 2'b01 behavior /////
  // In state 2'b01, sum_prev accumulates sum_temp and sum_temp clears to 0.
  state01_updates: assert property (
    @(posedge clk) disable iff (rst) (state == 2'b01) |=> 
      (sum_prev == $past(sum_prev) + $past(sum_temp)) && (sum_temp == 16'd0)
  );
  // In state 2'b01 with byte_count == 255, next state is 2'b10.
  state01_next_when_255: assert property (
    @(posedge clk) disable iff (rst) (state == 2'b01 && byte_count == 8'd255) |=> (state == 2'b10)
  );
  // In state 2'b01 with byte_count != 255, next state is 2'b00.
  state01_next_when_not_255: assert property (
    @(posedge clk) disable iff (rst) (state == 2'b01 && byte_count != 8'd255) |=> (state == 2'b00)
  );

  ///// State 2'b10 behavior /////
  // In state 2'b10, sum_final updates to sum_prev % 255.
  state10_compute_final: assert property (
    @(posedge clk) disable iff (rst) (state == 2'b10) |=> (sum_final == ($past(sum_prev) % 16'd255))
  );
  // In state 2'b10, sum updates from the previous sum_final value.
  state10_output_prev_final: assert property (
    @(posedge clk) disable iff (rst) (state == 2'b10) |=> (sum == $past(sum_final))
  );
  // In state 2'b10, next state is 2'b11.
  state10_next_is_11: assert property (
    @(posedge clk) disable iff (rst) (state == 2'b10) |=> (state == 2'b11)
  );

  ///// State 2'b11 behavior /////
  // In state 2'b11 with sum_final == data, next state is 2'b00.
  state11_next_when_match: assert property (
    @(posedge clk) disable iff (rst) (state == 2'b11 && (sum_final == data)) |=> (state == 2'b00)
  );
  // In state 2'b11 with sum_final != data, state holds at 2'b11.
  state11_hold_when_mismatch: assert property (
    @(posedge clk) disable iff (rst) (state == 2'b11 && (sum_final != data)) |=> (state == 2'b11)
  );

  ///// Stability outside write states /////
  // byte_count only changes in state 2'b00.
  byte_count_stable_outside_state00: assert property (
    @(posedge clk) disable iff (rst) (state != 2'b00) |=> (byte_count == $past(byte_count))
  );
  // sum_prev only changes in state 2'b01.
  sum_prev_stable_outside_state01: assert property (
    @(posedge clk) disable iff (rst) (state != 2'b01) |=> (sum_prev == $past(sum_prev))
  );
  // sum_temp is stable in states 2'b10 and 2'b11.
  sum_temp_stable_in_10_11: assert property (
    @(posedge clk) disable iff (rst) (state inside {2'b10, 2'b11}) |=> (sum_temp == $past(sum_temp))
  );
  // sum_final only changes in state 2'b10.
  sum_final_stable_outside_state10: assert property (
    @(posedge clk) disable iff (rst) (state != 2'b10) |=> (sum_final == $past(sum_final))
  );
  // sum only changes in state 2'b10.
  sum_stable_outside_state10: assert property (
    @(posedge clk) disable iff (rst) (state != 2'b10) |=> (sum == $past(sum))
  );

endmodule

