module ripple_carry_adder(clock, a_in, b_in, out);

parameter BITS = 8;

input clock;
input [BITS-1:0] a_in;
input [BITS-1:0] b_in;
output [BITS-1:0] out;

wire [BITS:0] carry;
assign carry[0] = 1'b0;

genvar i;
generate
  for (i = 0; i < BITS; i = i + 1) begin : full_adder_loop
    full_adder fa(clock, a_in[i], b_in[i], carry[i], out[i], carry[i+1]);
  end
endgenerate

endmodule

module full_adder(clock, a, b, cin, sum, cout);

input clock;
input a, b, cin;
output sum, cout;

wire s1, c1, c2;

assign s1 = a ^ b;
assign sum = s1 ^ cin;
assign c1 = a & b;
assign c2 = s1 & cin;
assign cout = c1 | c2;

endmodule

sva:
module ripple_carry_adder_sva #(
    parameter BITS = 8
) (
    input logic                  clock,
    input logic [BITS-1:0]       a_in,
    input logic [BITS-1:0]       b_in,
    input logic [BITS-1:0]       out
);
    // No reset in RTL; assertions are clocked on 'clock'.

    // Sum equals truncated addition of inputs.
    check_sum_correct: assert property (
        @(posedge clock) out == (a_in + b_in)
    );

    // If b_in is zero, out equals a_in.
    check_add_zero_b: assert property (
        @(posedge clock) (b_in == '0) |-> (out == a_in)
    );

    // If a_in is zero, out equals b_in.
    check_add_zero_a: assert property (
        @(posedge clock) (a_in == '0) |-> (out == b_in)
    );

    // LSB sum equals XOR of LSB inputs (carry-in is 0).
    check_lsb_xor: assert property (
        @(posedge clock) out[0] == (a_in[0] ^ b_in[0])
    );

    // If both LSB inputs are 1, LSB sum is 0.
    check_lsb_carry_effect: assert property (
        @(posedge clock) (a_in[0] & b_in[0]) |-> (out[0] == 1'b0)
    );

    // Adding bitwise complement yields all ones.
    check_complement_all_ones: assert property (
        @(posedge clock) (b_in == ~a_in) |-> (out == {BITS{1'b1}})
    );

    // All ones plus 1 wraps to zero (a_in = all 1s, b_in = 1).
    check_ones_plus_one_wrap_a: assert property (
        @(posedge clock)
            (a_in == {BITS{1'b1}}) && (b_in == {{(BITS-1){1'b0}},1'b1}) |-> (out == {BITS{1'b0}})
    );

    // All ones plus 1 wraps to zero (b_in = all 1s, a_in = 1).
    check_ones_plus_one_wrap_b: assert property (
        @(posedge clock)
            (b_in == {BITS{1'b1}}) && (a_in == {{(BITS-1){1'b0}},1'b1}) |-> (out == {BITS{1'b0}})
    );

    // When inputs are equal, result is left shift by 1 (modulo width).
    check_double_when_equal: assert property (
        @(posedge clock) (a_in == b_in) |-> (out == (a_in << 1))
    );

    // Lower 2-bit slice adds correctly (independent of higher bits).
    if (BITS >= 2) begin : gen_low2
        check_low2_slice_sum: assert property (
            @(posedge clock) out[1:0] == (a_in[1:0] + b_in[1:0])
        );
        // Bit1 sum equals XOR of bit1s and carry from bit0 (a0 & b0).
        check_bit1_sum: assert property (
            @(posedge clock) out[1] == (a_in[1] ^ b_in[1]) ^ (a_in[0] & b_in[0])
        );
    end

    // Lower 3-bit slice adds correctly (independent of higher bits).
    if (BITS >= 3) begin : gen_low3
        check_low3_slice_sum: assert property (
            @(posedge clock) out[2:0] == (a_in[2:0] + b_in[2:0])
        );
    end
endmodule

rtl:
module shift_register (
    input clk,
    input reset,
    input load,
    input [3:0] data_in,
    output [3:0] data_out
);

reg [3:0] shift_reg;

always @(posedge clk) begin
    if (reset) begin
        shift_reg <= 4'b0;
    end else if (load) begin
        shift_reg <= data_in;
    end else begin
        shift_reg <= {shift_reg[2:0], data_in[3]};
    end
end

assign data_out = shift_reg;

endmodule

sva:
module shift_register_sva (
    input logic clk,
    input logic reset,      // synchronous, active-high
    input logic load,
    input logic [3:0] data_in,
    input logic [3:0] data_out
);
    // Reset sets output to 0 on the next cycle.
    reset_clears_next: assert property (
        @(posedge clk) reset |=> (data_out == 4'b0000)
    );

    // While reset remains asserted, output stays 0.
    reset_holds_zero: assert property (
        @(posedge clk) $past(reset) && reset |-> (data_out == 4'b0000)
    );

    // When load is asserted, next output equals current data_in.
    load_updates_output: assert property (
        @(posedge clk) disable iff (reset) load |=> (data_out == $past(data_in))
    );

    // When not loading, next output is left-shift of current output with serial-in from data_in[3].
    shift_updates_output: assert property (
        @(posedge clk) disable iff (reset) !load |=> (data_out == { $past(data_out[2:0]), $past(data_in[3]) })
    );

    // When not loading, MSB shifts from previous bit[2].
    shift_msb_from_bit2: assert property (
        @(posedge clk) disable iff (reset) !load |=> (data_out[3] == $past(data_out[2]))
    );

    // When not loading, LSB takes data_in[3] of the same cycle.
    shift_lsb_from_datain_msb: assert property (
        @(posedge clk) disable iff (reset) !load |=> (data_out[0] == $past(data_in[3]))
    );
endmodule

rtl:
module and_gate (
    input A,
    input B,
    output X
);

    wire not_A, not_B, and_AB;

    // Invert A and B
    inv_1 inv_A (
        .A(A),
        .X(not_A)
    );

    inv_1 inv_B (
        .A(B),
        .X(not_B)
    );

    // AND the inverted signals
    and2 and_inv (
        .A(not_A),
        .B(not_B),
        .X(and_AB)
    );

    // Invert the AND output
    inv_1 inv_AB (
        .A(and_AB),
        .X(X)
    );

endmodule

module inv_1 (
    input A,
    output X
);

    assign X = ~A;

endmodule

module and2 (
    input A,
    input B,
    output X
);

    assign X = A & B;

endmodule

sva:
module and_gate_sva (
    input logic clk,   // sampling clock for assertions (DUT has no clock/reset)
    input logic A,
    input logic B,
    input logic X
);
    // X equals A OR B.
    check_x_equals_or: assert property (
        @(posedge clk) X == (A | B)
    );

    // If both inputs are LOW, output is LOW.
    check_x_zero_when_both_zero: assert property (
        @(posedge clk) ((A == 1'b0) && (B == 1'b0)) |-> (X == 1'b0)
    );

    // If A is HIGH, output is HIGH.
    check_x_one_when_a_one: assert property (
        @(posedge clk) (A == 1'b1) |-> (X == 1'b1)
    );

    // If B is HIGH, output is HIGH.
    check_x_one_when_b_one: assert property (
        @(posedge clk) (B == 1'b1) |-> (X == 1'b1)
    );

    // If output is LOW, both inputs are LOW.
    check_inputs_low_when_x_low: assert property (
        @(posedge clk) (X == 1'b0) |-> ((A == 1'b0) && (B == 1'b0))
    );

    // If output is HIGH, at least one input is HIGH.
    check_some_input_high_when_x_high: assert property (
        @(posedge clk) (X == 1'b1) |-> ((A | B) == 1'b1)
    );

    // If inputs are equal, output equals that value (idempotence).
    check_idempotent: assert property (
        @(posedge clk) (A == B) |-> (X == A)
    );
endmodule

module arithmetic_module_sva (
    input logic CLK,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic C1,
    input logic [1:0] Y
);
    // Y = A1 - A2 when B1==1 and C1==0.
    check_subtract_branch: assert property (
        @(posedge CLK) (B1 && !C1) |-> (Y == (A1 - A2))
    );

    // Y = A1 * A2 when B1==1 and C1==1.
    check_multiply_branch: assert property (
        @(posedge CLK) (B1 && C1) |-> (Y == (A1 * A2))
    );

    // Y = A1 + A2 when B1==0.
    check_add_branch: assert property (
        @(posedge CLK) (!B1) |-> (Y == (A1 + A2))
    );

    // In add branch, LSB equals XOR of A1 and A2.
    check_add_bit0: assert property (
        @(posedge CLK) (!B1) |-> (Y[0] == (A1 ^ A2))
    );

    // In add branch, MSB equals carry (A1 & A2).
    check_add_bit1: assert property (
        @(posedge CLK) (!B1) |-> (Y[1] == (A1 & A2))
    );

    // In multiply branch, LSB equals A1 AND A2.
    check_mul_bit0: assert property (
        @(posedge CLK) (B1 && C1) |-> (Y[0] == (A1 & A2))
    );

    // In multiply branch, MSB is always 0 for 1-bit operands.
    check_mul_bit1_zero: assert property (
        @(posedge CLK) (B1 && C1) |-> (Y[1] == 1'b0)
    );

    // If inputs are stable across cycles, Y remains stable (combinational).
    check_y_stable_when_inputs_stable: assert property (
        @(posedge CLK) $stable({A1,A2,B1,C1}) |-> $stable(Y)
    );

    // Y always matches the operation selected by B1/C1.
    check_functional_selection: assert property (
        @(posedge CLK) (B1 && !C1) ? (Y == (A1 - A2)) :
                        (B1 &&  C1) ? (Y == (A1 * A2)) :
                                      (Y == (A1 + A2))
    );
endmodule

rtl:
module xnor4 (
    input [3:0] A,
    input [3:0] B,
    input [3:0] C,
    input [3:0] D,
    input VPWR,
    input VGND,
    input VPB,
    input VNB,
    output reg Y
);

    wire [3:0] AB, CD, ABCD;
    assign AB = A ^ B;
    assign CD = C ^ D;
    assign ABCD = AB ^ CD;
    always @* begin
        Y = ~(ABCD[0] | ABCD[1] | ABCD[2] | ABCD[3]);
    end

endmodule

sva:
module xnor4_sva (
    input logic clk,
    input logic reset_n,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] C,
    input logic [3:0] D,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB,
    input logic Y
);
    // Y equals NOR-reduction of bitwise XOR across A,B,C,D.
    check_y_function: assert property (
        @(posedge clk) disable iff (!reset_n) Y == ~(|(((A ^ B) ^ (C ^ D))))
    );

    // If (A^B) equals (C^D), Y must be 1.
    check_y_true_when_xor_vectors_equal: assert property (
        @(posedge clk) disable iff (!reset_n) (((A ^ B) == (C ^ D))) |-> (Y == 1'b1)
    );

    // If (A^B) differs from (C^D), Y must be 0.
    check_y_false_when_xor_vectors_different: assert property (
        @(posedge clk) disable iff (!reset_n) (((A ^ B) != (C ^ D))) |-> (Y == 1'b0)
    );

    // Y is unaffected when only VPWR changes and data inputs are stable.
    check_y_stable_on_vpwr_change: assert property (
        @(posedge clk) disable iff (!reset_n)
        ($stable(A) && $stable(B) && $stable(C) && $stable(D) && $changed(VPWR)) |-> $stable(Y)
    );

    // Y is unaffected when only VGND changes and data inputs are stable.
    check_y_stable_on_vgnd_change: assert property (
        @(posedge clk) disable iff (!reset_n)
        ($stable(A) && $stable(B) && $stable(C) && $stable(D) && $changed(VGND)) |-> $stable(Y)
    );

    // Y is unaffected when only VPB changes and data inputs are stable.
    check_y_stable_on_vpb_change: assert property (
        @(posedge clk) disable iff (!reset_n)
        ($stable(A) && $stable(B) && $stable(C) && $stable(D) && $changed(VPB)) |-> $stable(Y)
    );

    // Y is unaffected when only VNB changes and data inputs are stable.
    check_y_stable_on_vnb_change: assert property (
        @(posedge clk) disable iff (!reset_n)
        ($stable(A) && $stable(B) && $stable(C) && $stable(D) && $changed(VNB)) |-> $stable(Y)
    );

    // Swapping A and B leaves Y unchanged (with C,D held).
    check_y_invariant_under_swap_ab: assert property (
        @(posedge clk) disable iff (!reset_n)
        (A == $past(B) && B == $past(A) && C == $past(C) && D == $past(D)) |-> (Y == $past(Y))
    );

    // Swapping C and D leaves Y unchanged (with A,B held).
    check_y_invariant_under_swap_cd: assert property (
        @(posedge clk) disable iff (!reset_n)
        (A == $past(A) && B == $past(B) && C == $past(D) && D == $past(C)) |-> (Y == $past(Y))
    );

    // If ((A^B)^(C^D)) is stable, Y must be stable.
    check_y_stable_when_xor_input_stable: assert property (
        @(posedge clk) disable iff (!reset_n)
        $stable(((A ^ B) ^ (C ^ D))) |-> $stable(Y)
    );

    // Y changes only if ((A^B)^(C^D)) changes.
    check_y_change_requires_xor_input_change: assert property (
        @(posedge clk) disable iff (!reset_n)
        $changed(Y) |-> $changed(((A ^ B) ^ (C ^ D)))
    );

    // If A==B and C==D, then Y must be 1.
    check_y_one_when_pairs_equal: assert property (
        @(posedge clk) disable iff (!reset_n) ((A == B) && (C == D)) |-> (Y == 1'b1)
    );

    // If A==B and C!=D, then Y must be 0.
    check_y_zero_when_cd_diff_only: assert property (
        @(posedge clk) disable iff (!reset_n) ((A == B) && (C != D)) |-> (Y == 1'b0)
    );

    // If A!=B and C==D, then Y must be 0.
    check_y_zero_when_ab_diff_only: assert property (
        @(posedge clk) disable iff (!reset_n) ((A != B) && (C == D)) |-> (Y == 1'b0)
    );
endmodule

rtl:
module subtract5(
   input [3:0] input_num,
   output [3:0] output_num
);

wire [4:0] five_minus_input;
assign five_minus_input = 5'd5 - {1'b0, input_num};

assign output_num = (five_minus_input[4] == 1) ? 4'b0 : five_minus_input[3:0];

endmodule

sva:
module subtract5_sva (
    input  logic [3:0] input_num,
    input  logic [3:0] output_num
);

    // For this combinational DUT with no clock/reset, sample on posedge of input_num[0].

    // If input <= 5, output equals 5 - input.
    check_subtract_when_le5: assert property (
        @(posedge input_num[0]) (input_num <= 4'd5) |-> (output_num == (4'd5 - input_num))
    );

    // If input > 5, output is zero (saturates at 0).
    check_saturate_when_gt5: assert property (
        @(posedge input_num[0]) (input_num > 4'd5) |-> (output_num == 4'd0)
    );

    // Output is always in range 0..5.
    check_output_range_to_five: assert property (
        @(posedge input_num[0]) (output_num <= 4'd5)
    );

    // Output zero implies input is >= 5.
    check_zero_output_implies_ge5: assert property (
        @(posedge input_num[0]) (output_num == 4'd0) |-> (input_num >= 4'd5)
    );

    // For input <= 5, output + input == 5.
    check_sum_is_five_when_input_le5: assert property (
        @(posedge input_num[0]) (input_num <= 4'd5) |-> ((output_num + input_num) == 4'd5)
    );

    // Bit[3] of output is always zero (output never exceeds 5).
    check_output_bit3_is_zero: assert property (
        @(posedge input_num[0]) (output_num[3] == 1'b0)
    );

    // Input 0 maps to output 5.
    check_case_input0_output5: assert property (
        @(posedge input_num[0]) (input_num == 4'd0) |-> (output_num == 4'd5)
    );

    // Input 5 maps to output 0.
    check_case_input5_output0: assert property (
        @(posedge input_num[0]) (input_num == 4'd5) |-> (output_num == 4'd0)
    );

    // If input is stable across samples, output is stable (pure combinational mapping).
    check_output_stable_when_input_stable: assert property (
        @(posedge input_num[0]) ($past(1'b1) && (input_num == $past(input_num))) |-> (output_num == $past(output_num))
    );

    // If input increments by 1 within 0..5, output decrements by 1 (until saturation).
    check_output_decrements_on_input_increment: assert property (
        @(posedge input_num[0])
            ($past(1'b1) && ($past(input_num) <= 4'd4) && (input_num == ($past(input_num) + 1)))
            |-> (output_num == ($past(output_num) - 1))
    );

endmodule

rtl:
module twos_complement (
    input [3:0] binary_in,
    output reg [3:0] twos_comp_out
);

always @(*) begin
    twos_comp_out = ~binary_in + 1;
end

endmodule

sva:
module twos_complement_sva (
    input logic clk,
    input logic [3:0] binary_in,
    input logic [3:0] twos_comp_out
);
    // Output equals bitwise NOT of input plus 1 (two's complement).
    check_twos_comp_equation: assert property (
        @(posedge clk) twos_comp_out == ((~binary_in) + 4'd1)
    );

    // Input plus output wraps to zero (mod 16).
    check_sum_zero_mod16: assert property (
        @(posedge clk) (binary_in + twos_comp_out) == 4'd0
    );

    // Input zero maps to output zero.
    check_zero_in_to_zero_out: assert property (
        @(posedge clk) (binary_in == 4'd0) |-> (twos_comp_out == 4'd0)
    );

    // Output zero implies input zero.
    check_zero_out_implies_zero_in: assert property (
        @(posedge clk) (twos_comp_out == 4'd0) |-> (binary_in == 4'd0)
    );

    // -8 (1000) is a fixed point of two's complement.
    check_neg_eight_fixed_point: assert property (
        @(posedge clk) (binary_in == 4'd8) |-> (twos_comp_out == 4'd8)
    );

    // LSB is preserved by two's complement.
    check_lsb_preserved: assert property (
        @(posedge clk) (twos_comp_out[0] == binary_in[0])
    );

    // Two's complement is involutive: applying it again returns input.
    check_involution: assert property (
        @(posedge clk) ((~twos_comp_out) + 4'd1) == binary_in
    );

    // If input is stable, output is stable next cycle.
    check_output_stable_when_input_stable: assert property (
        @(posedge clk) $stable(binary_in) |=> $stable(twos_comp_out)
    );

    // If input changes between cycles, output changes in the same step.
    check_output_changes_when_input_changes: assert property (
        @(posedge clk) (!$stable(binary_in)) |-> (!$stable(twos_comp_out))
    );

    // Output equals input only for 0 or 8.
    check_equality_only_for_fixed_points: assert property (
        @(posedge clk) (twos_comp_out == binary_in) |-> ((binary_in == 4'd0) || (binary_in == 4'd8))
    );
endmodule

rtl:
module pairwise_xor (
  input a,
  input b,
  input c,
  input d,
  input e,
  output [24:0] out
);

  assign out = {a^a, a^b, a^c, a^d, a^e, b^a, b^b, b^c, b^d, b^e, c^a, c^b, c^c, c^d, c^e, d^a, d^b, d^c, d^d, d^e, e^a, e^b, e^c, e^d, e^e};

endmodule

sva:
module pairwise_xor_sva (
  // RTL has no clock/reset; this wrapper uses 'clk' only for SVA sampling.
  input logic clk,
  // DUT ports (observed as inputs here)
  input logic a,
  input logic b,
  input logic c,
  input logic d,
  input logic e,
  input logic [24:0] out
);

  // out equals the concatenation of all pairwise XORs as in the RTL.
  check_full_concat_mapping: assert property (
    @(posedge clk) out == {a^a, a^b, a^c, a^d, a^e, b^a, b^b, b^c, b^d, b^e, c^a, c^b, c^c, c^d, c^e, d^a, d^b, d^c, d^d, d^e, e^a, e^b, e^c, e^d, e^e}
  );

  ///// Diagonal bits (x^x) are zero /////
  // a^a bit is always 0.
  check_diagonal_aa_zero: assert property (
    @(posedge clk) out[24] == 1'b0
  );
  // b^b bit is always 0.
  check_diagonal_bb_zero: assert property (
    @(posedge clk) out[18] == 1'b0
  );
  // c^c bit is always 0.
  check_diagonal_cc_zero: assert property (
    @(posedge clk) out[12] == 1'b0
  );
  // d^d bit is always 0.
  check_diagonal_dd_zero: assert property (
    @(posedge clk) out[6] == 1'b0
  );
  // e^e bit is always 0.
  check_diagonal_ee_zero: assert property (
    @(posedge clk) out[0] == 1'b0
  );

  ///// Symmetry of XOR: x^y == y^x /////
  // a^b equals b^a.
  check_symmetry_ab_ba_equal: assert property (
    @(posedge clk) out[23] == out[19]
  );
  // a^c equals c^a.
  check_symmetry_ac_ca_equal: assert property (
    @(posedge clk) out[22] == out[14]
  );
  // a^d equals d^a.
  check_symmetry_ad_da_equal: assert property (
    @(posedge clk) out[21] == out[9]
  );
  // a^e equals e^a.
  check_symmetry_ae_ea_equal: assert property (
    @(posedge clk) out[20] == out[4]
  );
  // b^c equals c^b.
  check_symmetry_bc_cb_equal: assert property (
    @(posedge clk) out[17] == out[13]
  );
  // b^d equals d^b.
  check_symmetry_bd_db_equal: assert property (
    @(posedge clk) out[16] == out[8]
  );
  // b^e equals e^b.
  check_symmetry_be_eb_equal: assert property (
    @(posedge clk) out[15] == out[3]
  );
  // c^d equals d^c.
  check_symmetry_cd_dc_equal: assert property (
    @(posedge clk) out[11] == out[7]
  );
  // c^e equals e^c.
  check_symmetry_ce_ec_equal: assert property (
    @(posedge clk) out[10] == out[2]
  );
  // d^e equals e^d.
  check_symmetry_de_ed_equal: assert property (
    @(posedge clk) out[5] == out[1]
  );

endmodule

module multiplier_module_sva (
    input logic clk,
    input logic reset,      // Active-high synchronous reset
    input logic [15:0] a,
    input logic [15:0] b,
    input logic [15:0] p
);
    // After any cycle with reset=1, p is 0 in the next cycle.
    check_reset_clears_p_next: assert property (
        @(posedge clk) disable iff (reset)
            $past(reset) |-> (p == 16'h0000)
    );

    // When prior cycle not in reset, p equals low 16 bits of a*b from prior cycle.
    check_registered_multiply_low16: assert property (
        @(posedge clk) disable iff (reset)
            !$past(reset) |-> (p == (($past(a) * $past(b)) [15:0]))
    );

    // If previous a was zero (and not in reset), p is zero now.
    check_zero_a_implies_zero_p: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(reset) && ($past(a) == 16'h0000)) |-> (p == 16'h0000)
    );

    // If previous b was zero (and not in reset), p is zero now.
    check_zero_b_implies_zero_p: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(reset) && ($past(b) == 16'h0000)) |-> (p == 16'h0000)
    );

    // If previous a was one (and not in reset), p equals previous b.
    check_one_a_passthrough_b: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(reset) && ($past(a) == 16'h0001)) |-> (p == $past(b))
    );

    // If previous b was one (and not in reset), p equals previous a.
    check_one_b_passthrough_a: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(reset) && ($past(b) == 16'h0001)) |-> (p == $past(a))
    );

    // If inputs are stable across the last and current cycle (and not in reset), p is stable into the next cycle.
    check_stable_inputs_imply_stable_p: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(reset) && !reset && ($past(a) == a) && ($past(b) == b)) |=> (p == $past(p))
    );
endmodule

rtl:
module axi_to_custom_protocol_converter
  (output reg next_pending_r_reg,
   output reg [11:0] m_axi_awaddr,
   output reg [47:0] m_payload_i_reg,
   output reg incr_next_pending,
   output reg wrap_next_pending,
   output reg sel_first_reg_0,
   input aclk,
   input [11:0] m_axi_awaddr_in,
   input [47:0] m_payload_i_reg_in,
   input next,
   input incr_next_pending_in,
   input wrap_next_pending_in,
   input sel_first_i);

  always @(posedge aclk) begin
    if (sel_first_i) begin
      m_axi_awaddr <= m_axi_awaddr_in;
      m_payload_i_reg <= m_payload_i_reg_in;
      sel_first_reg_0 <= 1'b1;
      next_pending_r_reg <= 1'b0;
    end else begin
      if (incr_next_pending_in) begin
        m_axi_awaddr <= m_axi_awaddr + 1;
        next_pending_r_reg <= 1'b0;
        incr_next_pending <= 1'b1;
        wrap_next_pending <= 1'b0;
      end else if (wrap_next_pending_in) begin
        m_axi_awaddr <= m_axi_awaddr_in;
        incr_next_pending <= 1'b0;
        wrap_next_pending <= 1'b1;
        next_pending_r_reg <= 1'b0;
      end else if (next) begin
        next_pending_r_reg <= 1'b0;
        incr_next_pending <= 1'b0;
        wrap_next_pending <= 1'b0;
      end
      sel_first_reg_0 <= 1'b0;
    end
  end
endmodule

sva:
module axi_to_custom_protocol_converter_sva
(
    input logic next_pending_r_reg,
    input logic [11:0] m_axi_awaddr,
    input logic [47:0] m_payload_i_reg,
    input logic incr_next_pending,
    input logic wrap_next_pending,
    input logic sel_first_reg_0,
    input logic aclk,
    input logic [11:0] m_axi_awaddr_in,
    input logic [47:0] m_payload_i_reg_in,
    input logic next,
    input logic incr_next_pending_in,
    input logic wrap_next_pending_in,
    input logic sel_first_i
);
    // On sel_first_i, load AWADDR/PAYLOAD from inputs, raise sel_first_reg_0, and clear next_pending_r_reg.
    check_sel_first_loads: assert property (
        @(posedge aclk) sel_first_i |-> (m_axi_awaddr == m_axi_awaddr_in)
                                   && (m_payload_i_reg == m_payload_i_reg_in)
                                   && (sel_first_reg_0 == 1'b1)
                                   && (next_pending_r_reg == 1'b0)
    );

    // sel_first_reg_0 mirrors sel_first_i every cycle.
    check_sel_first_flag_mirror: assert property (
        @(posedge aclk) sel_first_reg_0 == sel_first_i
    );

    // In incr branch, set incr_next_pending=1, wrap_next_pending=0, and clear next_pending_r_reg.
    check_incr_branch_flags: assert property (
        @(posedge aclk) (!sel_first_i && incr_next_pending_in) |-> (incr_next_pending == 1'b1)
                                                                  && (wrap_next_pending == 1'b0)
                                                                  && (next_pending_r_reg == 1'b0)
    );

    // In wrap branch, load AWADDR from input, set wrap_next_pending=1, incr_next_pending=0, and clear next_pending_r_reg.
    check_wrap_branch_effects: assert property (
        @(posedge aclk) (!sel_first_i && !incr_next_pending_in && wrap_next_pending_in) |-> (m_axi_awaddr == m_axi_awaddr_in)
                                                                                           && (wrap_next_pending == 1'b1)
                                                                                           && (incr_next_pending == 1'b0)
                                                                                           && (next_pending_r_reg == 1'b0)
    );

    // In next branch, clear incr_next_pending, wrap_next_pending, and next_pending_r_reg.
    check_next_branch_effects: assert property (
        @(posedge aclk) (!sel_first_i && !incr_next_pending_in && !wrap_next_pending_in && next) |-> (incr_next_pending == 1'b0)
                                                                                                  && (wrap_next_pending == 1'b0)
                                                                                                  && (next_pending_r_reg == 1'b0)
    );

    // Payload holds its value whenever sel_first_i stays LOW across consecutive cycles.
    check_payload_holds_when_sel_first_low: assert property (
        @(posedge aclk) ($past(!sel_first_i) && !sel_first_i) |-> (m_payload_i_reg == $past(m_payload_i_reg))
    );

    // AWADDR holds when there is no incr or wrap in two consecutive cycles with sel_first_i LOW.
    check_addr_holds_when_no_update: assert property (
        @(posedge aclk) ($past(!sel_first_i && !incr_next_pending_in && !wrap_next_pending_in)
                         && !sel_first_i && !incr_next_pending_in && !wrap_next_pending_in)
                         |-> (m_axi_awaddr == $past(m_axi_awaddr))
    );

    // Flags and next_pending_r_reg hold when idle (no incr/wrap/next) across two consecutive cycles with sel_first_i LOW.
    check_flags_hold_when_idle: assert property (
        @(posedge aclk) ($past(!sel_first_i && !incr_next_pending_in && !wrap_next_pending_in && !next)
                         && !sel_first_i && !incr_next_pending_in && !wrap_next_pending_in && !next)
                         |-> (incr_next_pending == $past(incr_next_pending))
                          && (wrap_next_pending == $past(wrap_next_pending))
                          && (next_pending_r_reg == $past(next_pending_r_reg))
    );
endmodule

