endmodule

sva:
module and_module_sva (
    input logic CLK,   // sampling clock for assertions
    input logic a,
    input logic b,
    input logic out
);
    // Output equals logical AND of inputs.
    check_out_equals_and: assert property (
        @(posedge CLK) out == (a & b)
    );

    // If any input is LOW, output must be LOW.
    check_any_input_low_forces_out_low: assert property (
        @(posedge CLK) (!a || !b) |-> (out == 1'b0)
    );

    // Output change must be caused by a change on at least one input.
    check_out_change_requires_input_change: assert property (
        @(posedge CLK) $changed(out) |-> ($changed(a) || $changed(b))
    );

    // Rising output implies at least one input rose and both are HIGH now.
    check_out_rise_cause: assert property (
        @(posedge CLK) $rose(out) |-> (($rose(a) && b) || ($rose(b) && a))
    );

    // Falling output implies at least one input fell.
    check_out_fall_cause: assert property (
        @(posedge CLK) $fell(out) |-> ($fell(a) || $fell(b))
    );
endmodule

rtl:
module GrayCodeConverter #(
  parameter n = 4 // number of bits
)(
  input [n-1:0] bin,
  input [n-1:0] gray,
  output [n-1:0] gray_out,
  output [n-1:0] bin_out
);


assign gray_out = bin ^ (bin >> 1);
assign bin_out = gray ^ (gray >> 1);

endmodule

sva:
module GrayCodeConverter_sva #(
  parameter int n = 4
)(
  // External clock for checking combinational logic
  input logic CLK,

  // DUT ports
  input logic [n-1:0] bin,
  input logic [n-1:0] gray,
  input logic [n-1:0] gray_out,
  input logic [n-1:0] bin_out
);
  // No reset in RTL; pure combinational; assertions are clocked on CLK.

  // gray_out must equal bin XOR (bin >> 1).
  check_gray_out_def: assert property (
    @(posedge CLK) gray_out == (bin ^ (bin >> 1))
  );

  // bin_out must equal gray XOR (gray >> 1).
  check_bin_out_def: assert property (
    @(posedge CLK) bin_out == (gray ^ (gray >> 1))
  );

  // MSB of gray_out equals MSB of bin.
  check_gray_msb: assert property (
    @(posedge CLK) gray_out[n-1] == bin[n-1]
  );

  // MSB of bin_out equals MSB of gray.
  check_bin_msb: assert property (
    @(posedge CLK) bin_out[n-1] == gray[n-1]
  );

  // Each gray_out[i] equals bin[i] XOR bin[i+1] for i in [0..n-2].
  genvar gi;
  generate
    for (gi = 0; gi < (n-1); gi++) begin : gen_gray_bits
      check_gray_bit: assert property (
        @(posedge CLK) gray_out[gi] == (bin[gi] ^ bin[gi+1])
      );
    end
  endgenerate

  // Each bin_out[i] equals gray[i] XOR gray[i+1] for i in [0..n-2].
  genvar bi;
  generate
    for (bi = 0; bi < (n-1); bi++) begin : gen_bin_bits
      check_bin_bit: assert property (
        @(posedge CLK) bin_out[bi] == (gray[bi] ^ gray[bi+1])
      );
    end
  endgenerate

  // When bin is all-zeros, gray_out must be all-zeros.
  check_zero_bin_to_zero_gray: assert property (
    @(posedge CLK) (bin == '0) |-> (gray_out == '0)
  );

  // When gray is all-zeros, bin_out must be all-zeros.
  check_zero_gray_to_zero_bin: assert property (
    @(posedge CLK) (gray == '0) |-> (bin_out == '0)
  );

  // gray_out XOR bin equals bin right-shifted by 1.
  check_gray_xor_bin_is_shift: assert property (
    @(posedge CLK) (gray_out ^ bin) == (bin >> 1)
  );

  // bin_out XOR gray equals gray right-shifted by 1.
  check_bin_xor_gray_is_shift: assert property (
    @(posedge CLK) (bin_out ^ gray) == (gray >> 1)
  );

endmodule

module sky130_fd_sc_lp__and3b_sva (
    input logic A_N,
    input logic B,
    input logic C,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB,
    input logic X
);
    // X equals AND of (A_N,B,C) where X is 1 only when all are exactly 1.
    check_truth_table_exact: assert property (
        @(posedge A_N or negedge A_N or posedge B or negedge B or posedge C or negedge C)
        disable iff (1'b0)
        (X === ((A_N === 1'b1) && (B === 1'b1) && (C === 1'b1)))
    );

    // If A_N is 0, X must be 0.
    check_x_low_when_a_zero: assert property (
        @(posedge A_N or negedge A_N or posedge B or negedge B or posedge C or negedge C)
        disable iff (1'b0)
        (A_N === 1'b0) |-> (X === 1'b0)
    );

    // If B is 0, X must be 0.
    check_x_low_when_b_zero: assert property (
        @(posedge A_N or negedge A_N or posedge B or negedge B or posedge C or negedge C)
        disable iff (1'b0)
        (B === 1'b0) |-> (X === 1'b0)
    );

    // If C is 0, X must be 0.
    check_x_low_when_c_zero: assert property (
        @(posedge A_N or negedge A_N or posedge B or negedge B or posedge C or negedge C)
        disable iff (1'b0)
        (C === 1'b0) |-> (X === 1'b0)
    );

    // If X is 1 then all inputs are exactly 1.
    check_x_one_implies_inputs_one: assert property (
        @(posedge A_N or negedge A_N or posedge B or negedge B or posedge C or negedge C)
        disable iff (1'b0)
        (X === 1'b1) |-> ((A_N === 1'b1) && (B === 1'b1) && (C === 1'b1))
    );

    // If any input is not exactly 1 (including X/Z), X must be 0.
    check_x_zero_if_any_input_not_one: assert property (
        @(posedge A_N or negedge A_N or posedge B or negedge B or posedge C or negedge C)
        disable iff (1'b0)
        ((A_N !== 1'b1) || (B !== 1'b1) || (C !== 1'b1)) |-> (X === 1'b0)
    );

    // X must never be X/Z because it is always assigned 0 or 1.
    check_x_never_unknown: assert property (
        @(posedge A_N or negedge A_N or posedge B or negedge B or posedge C or negedge C)
        disable iff (1'b0)
        !$isunknown(X)
    );

    // On A_N rising when B and C are 1, X must be 1.
    check_x_high_on_a_rise_when_bc_high: assert property (
        @(posedge A_N)
        disable iff (1'b0)
        ((B === 1'b1) && (C === 1'b1)) |-> (X === 1'b1)
    );

    // On B rising when A_N and C are 1, X must be 1.
    check_x_high_on_b_rise_when_ac_high: assert property (
        @(posedge B)
        disable iff (1'b0)
        ((A_N === 1'b1) && (C === 1'b1)) |-> (X === 1'b1)
    );

    // On C rising when A_N and B are 1, X must be 1.
    check_x_high_on_c_rise_when_ab_high: assert property (
        @(posedge C)
        disable iff (1'b0)
        ((A_N === 1'b1) && (B === 1'b1)) |-> (X === 1'b1)
    );
endmodule

