    input  B  ;
    input  C  ;
    input  D_N;

    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    wire not0_out ;
    wire or0_out_X;

    not not0 (not0_out , D_N              );
    or  or0  (or0_out_X, not0_out, C, B, A);
