module adder_subtractor(
    input [3:0] A, B,
    input C,
    output [3:0] S,
    output Cout
);

wire [3:0] B_neg;
assign B_neg = (~B) + 1;

assign S = (C) ? (A + B_neg) : (A + B);
assign Cout = (C) ? (A >= B) : (A + B >= 16);

endmodule

sva:
module adder_subtractor_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic C,
    input logic [3:0] S,
    input logic Cout
);
    // Addition mode: S equals A + B (4-bit result).
    check_sum_add_mode: assert property (
        @(posedge clk) (!C) |-> (S == (A + B))
    );

    // Subtraction mode: S equals A + (~B + 1) (two's complement, 4-bit).
    check_sum_sub_mode: assert property (
        @(posedge clk) C |-> (S == (A + ((~B) + 4'd1)))
    );

    // Addition mode: Cout equals (A + B >= 16) as coded (with 4-bit sum semantics).
    check_cout_add_mode_expr: assert property (
        @(posedge clk) (!C) |-> (Cout == ((A + B) >= 32'd16))
    );

    // Subtraction mode: Cout indicates no borrow (A >= B).
    check_cout_sub_mode_expr: assert property (
        @(posedge clk) C |-> (Cout == (A >= B))
    );

    // Subtraction mode: when A == B, result is zero and no borrow.
    check_sub_equal_inputs_zero: assert property (
        @(posedge clk) (C && (A == B)) |-> (S == 4'd0 && Cout == 1'b1)
    );

    // Addition mode: when B == 0, pass-through A to S.
    check_add_b_zero_passthrough: assert property (
        @(posedge clk) (!C && (B == 4'd0)) |-> (S == A)
    );

    // Addition mode: when B == 0, Cout is zero per coded compare.
    check_add_b_zero_no_carry: assert property (
        @(posedge clk) (!C && (B == 4'd0)) |-> (Cout == 1'b0)
    );

    // Addition mode: when A == 0, pass-through B to S.
    check_add_a_zero_passthrough: assert property (
        @(posedge clk) (!C && (A == 4'd0)) |-> (S == B)
    );

    // Subtraction mode: when B == 0, pass-through A to S.
    check_sub_b_zero_passthrough: assert property (
        @(posedge clk) (C && (B == 4'd0)) |-> (S == A)
    );

    // Subtraction mode: when B == 0, Cout is one (A >= 0).
    check_sub_b_zero_no_borrow: assert property (
        @(posedge clk) (C && (B == 4'd0)) |-> (Cout == 1'b1)
    );
endmodule

rtl:
module controlunit(input [5:0] imemout,output brnch,output memorywrite,output memoryread,output alusrc,output regw,output regdst,output aluop,output memtoreg);
reg brnch,memorywrite,memoryread,aluop;
reg memtoreg,alusrc,regw,regdst;

always @ ( imemout )
begin
	if(imemout[5:0] == 6'b000000)
	begin
		brnch = 1'b0;
		memorywrite = 1'b0;
		memoryread = 1'b0;
		alusrc = 1'b0;
		regw = 1'b1;
		regdst = 1'b1;
		aluop = 1'b1;
		memtoreg = 1'b1;
	end
	else
	if(imemout[5:0] == 6'b100011)
	begin
		brnch = 1'b0;
		memorywrite = 1'b0;
		memoryread = 1'b1;
		alusrc = 1'b1;
		regw = 1'b1;
		regdst = 1'b0;
		aluop = 1'b0;
		memtoreg = 1'b0;
	end
	else
	if(imemout[5:0] == 6'b101011)
	begin
		brnch = 1'b0;
		memorywrite = 1'b1;
		memoryread = 1'b0;
		alusrc = 1'b1;
		regw = 1'b0;
		regdst = 1'b0;
		aluop = 1'b0;
		memtoreg = 1'b0;
	end
	else
	if(imemout[5:0] == 6'b000100)
	begin
		brnch = 1'b1;
		memorywrite = 1'b0;
		memoryread = 1'b0;
		alusrc = 1'b0;
		regw = 1'b0;
		regdst = 1'b0;
		aluop = 1'b0;
		memtoreg = 1'b0;
	end
	else
	begin
		brnch = 1'b0;
		memorywrite = 1'b0;
		memoryread = 1'b0;
		alusrc = 1'b0;
		regw = 1'b0;
		regdst = 1'b0;
		aluop = 1'b0;
		memtoreg = 1'b0;
	end
end

endmodule

sva:
module controlunit_sva (
    input  logic        clk,
    input  logic        reset_n,
    input  logic [5:0]  imemout,
    input  logic        brnch,
    input  logic        memorywrite,
    input  logic        memoryread,
    input  logic        alusrc,
    input  logic        regw,
    input  logic        regdst,
    input  logic        aluop,
    input  logic        memtoreg
);
    localparam logic [5:0] OPC_RTYPE = 6'b000000;
    localparam logic [5:0] OPC_LW    = 6'b100011;
    localparam logic [5:0] OPC_SW    = 6'b101011;
    localparam logic [5:0] OPC_BEQ   = 6'b000100;

    // R-type decode drives exact outputs.
    check_decode_rtype: assert property (
        @(posedge clk) disable iff (!reset_n)
        (imemout == OPC_RTYPE) |-> (brnch==1'b0 && memorywrite==1'b0 && memoryread==1'b0 && alusrc==1'b0 && regw==1'b1 && regdst==1'b1 && aluop==1'b1 && memtoreg==1'b1)
    );

    // LW decode drives exact outputs.
    check_decode_lw: assert property (
        @(posedge clk) disable iff (!reset_n)
        (imemout == OPC_LW) |-> (brnch==1'b0 && memorywrite==1'b0 && memoryread==1'b1 && alusrc==1'b1 && regw==1'b1 && regdst==1'b0 && aluop==1'b0 && memtoreg==1'b0)
    );

    // SW decode drives exact outputs.
    check_decode_sw: assert property (
        @(posedge clk) disable iff (!reset_n)
        (imemout == OPC_SW) |-> (brnch==1'b0 && memorywrite==1'b1 && memoryread==1'b0 && alusrc==1'b1 && regw==1'b0 && regdst==1'b0 && aluop==1'b0 && memtoreg==1'b0)
    );

    // BEQ decode drives exact outputs.
    check_decode_beq: assert property (
        @(posedge clk) disable iff (!reset_n)
        (imemout == OPC_BEQ) |-> (brnch==1'b1 && memorywrite==1'b0 && memoryread==1'b0 && alusrc==1'b0 && regw==1'b0 && regdst==1'b0 && aluop==1'b0 && memtoreg==1'b0)
    );

    // Default decode (all other opcodes) drives all zeros.
    check_decode_default: assert property (
        @(posedge clk) disable iff (!reset_n)
        ((imemout != OPC_RTYPE) && (imemout != OPC_LW) && (imemout != OPC_SW) && (imemout != OPC_BEQ))
        |-> (brnch==1'b0 && memorywrite==1'b0 && memoryread==1'b0 && alusrc==1'b0 && regw==1'b0 && regdst==1'b0 && aluop==1'b0 && memtoreg==1'b0)
    );

    // Read and write to memory are never both asserted.
    check_rd_wr_mutex: assert property (
        @(posedge clk) disable iff (!reset_n)
        !(memoryread && memorywrite)
    );

    // ALUOP high occurs only for R-type.
    check_aluop_only_rtype: assert property (
        @(posedge clk) disable iff (!reset_n)
        aluop |-> (imemout == OPC_RTYPE)
    );

    // REGDST high occurs only for R-type.
    check_regdst_only_rtype: assert property (
        @(posedge clk) disable iff (!reset_n)
        regdst |-> (imemout == OPC_RTYPE)
    );

    // MEMTOREG high occurs only for R-type.
    check_memtoreg_only_rtype: assert property (
        @(posedge clk) disable iff (!reset_n)
        memtoreg |-> (imemout == OPC_RTYPE)
    );

    // ALUSRC high occurs only for LW or SW.
    check_alusrc_lw_or_sw: assert property (
        @(posedge clk) disable iff (!reset_n)
        alusrc |-> ((imemout == OPC_LW) || (imemout == OPC_SW))
    );

    // REGW high occurs only for R-type or LW.
    check_regw_rtype_or_lw: assert property (
        @(posedge clk) disable iff (!reset_n)
        regw |-> ((imemout == OPC_RTYPE) || (imemout == OPC_LW))
    );

    // MEMORYREAD implies LW opcode.
    check_memoryread_implies_lw: assert property (
        @(posedge clk) disable iff (!reset_n)
        memoryread |-> (imemout == OPC_LW)
    );

    // MEMORYWRITE implies SW opcode.
    check_memorywrite_implies_sw: assert property (
        @(posedge clk) disable iff (!reset_n)
        memorywrite |-> (imemout == OPC_SW)
    );

    // BRNCH implies BEQ opcode and no memory access.
    check_branch_implies_beq_no_mem: assert property (
        @(posedge clk) disable iff (!reset_n)
        brnch |-> ((imemout == OPC_BEQ) && !memoryread && !memorywrite)
    );

    // MEMTOREG high implies REGW high and no MEMORYREAD.
    check_memtoreg_implies_regw: assert property (
        @(posedge clk) disable iff (!reset_n)
        memtoreg |-> (regw && !memoryread)
    );

    // If IMEMOUT is stable across cycles, outputs remain stable.
    check_stability_when_input_stable: assert property (
        @(posedge clk) disable iff (!reset_n)
        (imemout == $past(imemout)) |-> (brnch==$past(brnch) && memorywrite==$past(memorywrite) && memoryread==$past(memoryread) && alusrc==$past(alusrc) && regw==$past(regw) && regdst==$past(regdst) && aluop==$past(aluop) && memtoreg==$past(memtoreg))
    );
endmodule

rtl:
module comparator (
    input [3:0] A,
    input [3:0] B,
    output reg EQ,
    output reg GT,
    output reg LT
);

    always @(*) begin
        if (A == B) begin
            EQ = 1;
            GT = 0;
            LT = 0;
        end else if (A > B) begin
            EQ = 0;
            GT = 1;
            LT = 0;
        end else begin
            EQ = 0;
            GT = 0;
            LT = 1;
        end
    end

endmodule

sva:
module comparator_sva (
    input  logic        CLK,   // Sampling clock for assertions (DUT is combinational)
    input  logic [3:0]  A,
    input  logic [3:0]  B,
    input  logic        EQ,
    input  logic        GT,
    input  logic        LT
);
    ///// Comparator behavior /////
    // Exactly one of EQ/GT/LT must be HIGH.
    check_outputs_onehot: assert property (
        @(posedge CLK) $onehot({EQ, GT, LT})
    );

    // When A == B, outputs must be EQ=1, GT=0, LT=0.
    check_equal_maps_to_EQ: assert property (
        @(posedge CLK) (A == B) |-> (EQ && !GT && !LT)
    );

    // When A > B, outputs must be EQ=0, GT=1, LT=0.
    check_greater_maps_to_GT: assert property (
        @(posedge CLK) (A > B) |-> (!EQ && GT && !LT)
    );

    // When A < B, outputs must be EQ=0, GT=0, LT=1.
    check_less_maps_to_LT: assert property (
        @(posedge CLK) (A < B) |-> (!EQ && !GT && LT)
    );

    // If EQ is 1, then A must equal B.
    check_EQ_implies_equal: assert property (
        @(posedge CLK) EQ |-> (A == B)
    );

    // If GT is 1, then A must be greater than B.
    check_GT_implies_greater: assert property (
        @(posedge CLK) GT |-> (A > B)
    );

    // If LT is 1, then A must be less than B.
    check_LT_implies_less: assert property (
        @(posedge CLK) LT |-> (A < B)
    );

    // Outputs are never all zero.
    check_not_all_zero: assert property (
        @(posedge CLK) (EQ || GT || LT)
    );
endmodule

rtl:
module four_bit_adder(
  input [3:0] A,
  input [3:0] B,
  input Cin,
  output Cout,
  output [3:0] S
);

  wire [3:0] temp_sum;
  wire C0, C1, C2;

  // Full adder for the least significant bit
  full_adder FA0(A[0], B[0], Cin, temp_sum[0], C0);

  // Full adder for the second least significant bit
  full_adder FA1(A[1], B[1], C0, temp_sum[1], C1);

  // Full adder for the third least significant bit
  full_adder FA2(A[2], B[2], C1, temp_sum[2], C2);

  // Full adder for the most significant bit
  full_adder FA3(A[3], B[3], C2, temp_sum[3], Cout);

  assign S = temp_sum;

endmodule
module full_adder(
  input A,
  input B,
  input Cin,
  output S,
  output Cout
);

  assign S = A ^ B ^ Cin;
  assign Cout = (A & B) | (Cin & (A ^ B));

endmodule

sva:
module four_bit_adder_sva (
    input  logic        CLK,   // External assertion clock (RTL has no clock/reset)
    input  logic [3:0]  A,
    input  logic [3:0]  B,
    input  logic        Cin,
    input  logic        Cout,
    input  logic [3:0]  S
);
    // Helper carry expressions derived from inputs (reflect RTL ripple structure)
    logic c0_e, c1_e, c2_e;
    assign c0_e = (A[0] & B[0]) | (Cin & (A[0] ^ B[0]));
    assign c1_e = (A[1] & B[1]) | (c0_e & (A[1] ^ B[1]));
    assign c2_e = (A[2] & B[2]) | (c1_e & (A[2] ^ B[2]));

    ///// Functional correctness of the adder /////
    // Concatenated {Cout,S} equals 5-bit arithmetic sum A + B + Cin.
    check_sum_matches_arithmetic: assert property (
        @(posedge CLK) disable iff (1'b0) {Cout, S} == (A + B + Cin)
    );
    // Bit 0 sum is XOR of A[0], B[0], and Cin.
    check_bit0_sum_xor: assert property (
        @(posedge CLK) disable iff (1'b0) S[0] == (A[0] ^ B[0] ^ Cin)
    );
    // Bit 1 sum is XOR of A[1], B[1], and carry from bit 0.
    check_bit1_sum_xor: assert property (
        @(posedge CLK) disable iff (1'b0) S[1] == (A[1] ^ B[1] ^ c0_e)
    );
    // Bit 2 sum is XOR of A[2], B[2], and carry from bit 1.
    check_bit2_sum_xor: assert property (
        @(posedge CLK) disable iff (1'b0) S[2] == (A[2] ^ B[2] ^ c1_e)
    );
    // Bit 3 sum is XOR of A[3], B[3], and carry from bit 2.
    check_bit3_sum_xor: assert property (
        @(posedge CLK) disable iff (1'b0) S[3] == (A[3] ^ B[3] ^ c2_e)
    );
    // Final carry-out equals carry function of bit 3 and carry from bit 2.
    check_cout_formula: assert property (
        @(posedge CLK) disable iff (1'b0) Cout == ((A[3] & B[3]) | (c2_e & (A[3] ^ B[3])))
    );

    ///// Basic identities and boundary cases /////
    // Adding zero B with Cin=0 passes A through and no carry.
    check_zero_identity_B: assert property (
        @(posedge CLK) disable iff (1'b0) ((B == 4'b0000) && (Cin == 1'b0)) |-> ((S == A) && (Cout == 1'b0))
    );
    // Adding zero A with Cin=0 passes B through and no carry.
    check_zero_identity_A: assert property (
        @(posedge CLK) disable iff (1'b0) ((A == 4'b0000) && (Cin == 1'b0)) |-> ((S == B) && (Cout == 1'b0))
    );
    // Only Cin=1 with A=0 and B=0 yields S=1 and Cout=0.
    check_cin_only: assert property (
        @(posedge CLK) disable iff (1'b0) ((A == 4'b0000) && (B == 4'b0000) && (Cin == 1'b1)) |-> ((S == 4'b0001) && (Cout == 1'b0))
    );
    // 0xF + 0x1 with Cin=0 wraps to 0x0 with Cout=1.
    check_overflow_F_plus_1: assert property (
        @(posedge CLK) disable iff (1'b0) ((A == 4'hF) && (B == 4'h1) && (Cin == 1'b0)) |-> ((S == 4'h0) && (Cout == 1'b1))
    );
    // 0xF + 0xF + Cin=1 yields 0xF with Cout=1.
    check_overflow_FF_plus_1: assert property (
        @(posedge CLK) disable iff (1'b0) ((A == 4'hF) && (B == 4'hF) && (Cin == 1'b1)) |-> ((S == 4'hF) && (Cout == 1'b1))
    );

    ///// Combinational stability /////
    // If inputs are stable across a cycle, outputs remain stable.
    check_output_stability_when_inputs_stable: assert property (
        @(posedge CLK) disable iff (1'b0) $stable({A,B,Cin}) |-> $stable({S,Cout})
    );
endmodule

rtl:
module adder_4bit(
  input [3:0] A,
  input [3:0] B,
  output [3:0] S,
  output C_out
);

  wire [3:0] sum;
  wire [3:0] carry;

  // Full Adders
  full_adder fa0(
    .a(A[0]),
    .b(B[0]),
    .c_in(1'b0),
    .sum(sum[0]),
    .c_out(carry[0])
  );

  full_adder fa1(
    .a(A[1]),
    .b(B[1]),
    .c_in(carry[0]),
    .sum(sum[1]),
    .c_out(carry[1])
  );

  full_adder fa2(
    .a(A[2]),
    .b(B[2]),
    .c_in(carry[1]),
    .sum(sum[2]),
    .c_out(carry[2])
  );

  full_adder fa3(
    .a(A[3]),
    .b(B[3]),
    .c_in(carry[2]),
    .sum(sum[3]),
    .c_out(C_out)
  );

  assign S = sum;

endmodule

module full_adder(
  input a,
  input b,
  input c_in,
  output sum,
  output c_out
);

  assign sum = a ^ b ^ c_in;
  assign c_out = (a & b) | (a & c_in) | (b & c_in);

endmodule

sva:
module adder_4bit_sva (
    input logic CLK,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] S,
    input logic C_out
);
    // 5-bit sum must equal unsigned addition of A and B.
    check_sum_5bit: assert property (
        @(posedge CLK) disable iff (1'b0) {C_out, S} == ({1'b0, A} + {1'b0, B})
    );

    // LSB sum equals A[0] XOR B[0] (carry-in is 0).
    check_s0_xor: assert property (
        @(posedge CLK) disable iff (1'b0) S[0] == (A[0] ^ B[0])
    );

    // Bit1 sum equals A[1] XOR B[1] XOR carry0.
    check_s1_ripple: assert property (
        @(posedge CLK) disable iff (1'b0) S[1] == (A[1] ^ B[1] ^ (A[0] & B[0]))
    );

    // Bit2 sum equals A[2] XOR B[2] XOR carry1.
    check_s2_ripple: assert property (
        @(posedge CLK) disable iff (1'b0) S[2] == (A[2] ^ B[2] ^ ((A[1] & B[1]) | ((A[1] ^ B[1]) & (A[0] & B[0]))))
    );

    // Bit3 sum equals A[3] XOR B[3] XOR carry2.
    check_s3_ripple: assert property (
        @(posedge CLK) disable iff (1'b0) S[3] == (A[3] ^ B[3] ^ ((A[2] & B[2]) | ((A[2] ^ B[2]) & ((A[1] & B[1]) | ((A[1] ^ B[1]) & (A[0] & B[0]))))))
    );

    // Final carry-out equals majority of A[3], B[3], and carry2.
    check_cout_ripple: assert property (
        @(posedge CLK) disable iff (1'b0)
            C_out == (
                (A[3] & B[3]) |
                (A[3] & ((A[2] & B[2]) | ((A[2] ^ B[2]) & ((A[1] & B[1]) | ((A[1] ^ B[1]) & (A[0] & B[0])))))) |
                (B[3] & ((A[2] & B[2]) | ((A[2] ^ B[2]) & ((A[1] & B[1]) | ((A[1] ^ B[1]) & (A[0] & B[0]))))))
            )
    );

    // Output S equals lower 4 bits of the 5-bit sum.
    check_s_lowbits_of_sum: assert property (
        @(posedge CLK) disable iff (1'b0) S == (({1'b0, A} + {1'b0, B})[3:0])
    );

    // Carry-out equals MSB of the 5-bit sum.
    check_cout_msb_of_sum: assert property (
        @(posedge CLK) disable iff (1'b0) C_out == (({1'b0, A} + {1'b0, B})[4])
    );

    // Adding zero on A yields S==B and no carry.
    check_add_zero_A: assert property (
        @(posedge CLK) disable iff (1'b0) (A == 4'b0000) |-> (S == B) && (C_out == 1'b0)
    );

    // Adding zero on B yields S==A and no carry.
    check_add_zero_B: assert property (
        @(posedge CLK) disable iff (1'b0) (B == 4'b0000) |-> (S == A) && (C_out == 1'b0)
    );

    // When both inputs are 4'hF, sum is 4'he with carry-out 1.
    check_max_plus_max: assert property (
        @(posedge CLK) disable iff (1'b0) (A == 4'hF && B == 4'hF) |-> (S == 4'hE) && (C_out == 1'b1)
    );

    // Carry-out iff the 4-bit sum wraps below either operand.
    check_cout_wrap_condition: assert property (
        @(posedge CLK) disable iff (1'b0) C_out == ((S < A) || (S < B))
    );
endmodule

rtl:
module snps_clock_gate_high_d_ff_en_w32_0_8 (
    input CLK,
    input EN,
    input TE,
    output ENCLK
);

    TLATNTSCAX2TS latch (
        .E(EN),
        .SE(TE),
        .CK(CLK),
        .ECK(ENCLK)
    );

endmodule

module TLATNTSCAX2TS (
    input E,
    input SE,
    input CK,
    output reg ECK
);
always @ (posedge CK)
    begin
        if (SE)
            ECK <= E;
    end
endmodule

sva:
module snps_clock_gate_high_d_ff_en_w32_0_8_sva (
    input logic CLK,
    input logic EN,
    input logic TE,
    input logic ENCLK
);
    // When TE is 1, EN is captured to ENCLK on the next clock.
    cg_update_when_te_high: assert property (
        @(posedge CLK) TE |=> (ENCLK == $past(EN))
    );

    // When TE is 0, ENCLK holds its previous value on the next clock.
    cg_hold_when_te_low: assert property (
        @(posedge CLK) !TE |=> (ENCLK == $past(ENCLK))
    );

    // Any change in ENCLK must come from prior TE==1 and equals prior EN.
    cg_change_implies_prior_te_and_val: assert property (
        @(posedge CLK) (ENCLK != $past(ENCLK)) |-> ($past(TE) && (ENCLK == $past(EN)))
    );

    // If TE is 1 and EN equals the previous ENCLK, no change occurs next cycle.
    cg_idempotent_update_no_change: assert property (
        @(posedge CLK) (TE && (EN == $past(ENCLK))) |=> (ENCLK == $past(ENCLK,1))
    );

    // If TE is 1 and EN differs from the previous ENCLK, a change occurs next cycle.
    cg_update_causes_change_if_diff: assert property (
        @(posedge CLK) (TE && (EN != $past(ENCLK))) |=> (ENCLK != $past(ENCLK,1))
    );

    // If TE is 0 for two cycles, ENCLK two cycles later equals its value two cycles ago.
    cg_two_cycle_hold_when_te_low: assert property (
        @(posedge CLK) (!TE) ##1 (!TE) |=> (ENCLK == $past(ENCLK,2))
    );

    // If TE is 1 for two cycles, ENCLK two cycles later equals EN from one cycle ago.
    cg_two_cycle_update_when_te_high: assert property (
        @(posedge CLK) (TE) ##1 (TE) |=> (ENCLK == $past(EN,1))
    );

    // If TE is 0 for three cycles, ENCLK three cycles later equals its value three cycles ago.
    cg_three_cycle_hold_when_te_low: assert property (
        @(posedge CLK) (!TE) ##1 (!TE) ##1 (!TE) |=> (ENCLK == $past(ENCLK,3))
    );

    // If TE is 1 for three cycles, ENCLK three cycles later equals EN from one cycle ago.
    cg_three_cycle_update_when_te_high: assert property (
        @(posedge CLK) (TE) ##1 (TE) ##1 (TE) |=> (ENCLK == $past(EN,1))
    );

    // If no change occurred but prior TE was 1, then EN must have equaled the prior ENCLK.
    cg_no_change_despite_te_means_equal: assert property (
        @(posedge CLK) ((ENCLK == $past(ENCLK)) && $past(TE)) |-> ($past(EN) == $past(ENCLK))
    );
endmodule

rtl:
module register_counter_xor (
    input clk, 
    input reset,
    input [3:0] reg_data_in,
    input reg_load,
    input counter_enable,
    output [7:0] output_data
); 

reg [3:0] register_data;
reg [3:0] counter_data;
wire [7:0] xor_output;

// Register module
always @(posedge clk, negedge reset) begin
    if (!reset) begin
        register_data <= 4'b0;
    end else begin
        if (reg_load) begin
            register_data <= reg_data_in;
        end
    end
end

// Counter module
always @(posedge clk, negedge reset) begin
    if (!reset) begin
        counter_data <= 4'b0;
    end else begin
        if (counter_enable) begin
            counter_data <= counter_data + 1;
        end
    end
end

// XOR module
assign xor_output = {register_data, counter_data} ^ 8'b11111111;

// Output
assign output_data = xor_output;

endmodule

