module bitwise_logic (
  input A,
  input B,
  input [1:0] SEL,
  output C
);

  // Define logical operators based on SEL input signal
  wire AND = A & B;
  wire OR = A | B;
  wire XOR = A ^ B;
  wire NOT = ~A;

  // Compute output signal C based on input signals A and B and SEL control signal
  assign C = (SEL == 0) ? AND :
            (SEL == 1) ? OR :
            (SEL == 2) ? XOR :
            (SEL == 3) ? NOT :
            1'bx; // default value for invalid SEL input

endmodule

sva:
module bitwise_logic_sva (
    input logic A,
    input logic B,
    input logic [1:0] SEL,
    input logic C
);
    // When SEL==00, C equals A & B.
    check_sel00_and: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge SEL[0] or negedge SEL[0] or posedge SEL[1] or negedge SEL[1])
        (SEL == 2'b00) |-> (C == (A & B))
    );

    // When SEL==01, C equals A | B.
    check_sel01_or: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge SEL[0] or negedge SEL[0] or posedge SEL[1] or negedge SEL[1])
        (SEL == 2'b01) |-> (C == (A | B))
    );

    // When SEL==10, C equals A ^ B.
    check_sel10_xor: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge SEL[0] or negedge SEL[0] or posedge SEL[1] or negedge SEL[1])
        (SEL == 2'b10) |-> (C == (A ^ B))
    );

    // When SEL==11, C equals ~A.
    check_sel11_not: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge SEL[0] or negedge SEL[0] or posedge SEL[1] or negedge SEL[1])
        (SEL == 2'b11) |-> (C == (~A))
    );

    // AND: if A is 0 then C is 0.
    check_and_zero_when_A0: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge SEL[0] or negedge SEL[0] or posedge SEL[1] or negedge SEL[1])
        ((SEL == 2'b00) && (A == 1'b0)) |-> (C == 1'b0)
    );

    // AND: if B is 0 then C is 0.
    check_and_zero_when_B0: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge SEL[0] or negedge SEL[0] or posedge SEL[1] or negedge SEL[1])
        ((SEL == 2'b00) && (B == 1'b0)) |-> (C == 1'b0)
    );

    // OR: if A is 1 then C is 1.
    check_or_one_when_A1: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge SEL[0] or negedge SEL[0] or posedge SEL[1] or negedge SEL[1])
        ((SEL == 2'b01) && (A == 1'b1)) |-> (C == 1'b1)
    );

    // OR: if B is 1 then C is 1.
    check_or_one_when_B1: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge SEL[0] or negedge SEL[0] or posedge SEL[1] or negedge SEL[1])
        ((SEL == 2'b01) && (B == 1'b1)) |-> (C == 1'b1)
    );

    // XOR: if A equals B then C is 0.
    check_xor_zero_when_equal: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge SEL[0] or negedge SEL[0] or posedge SEL[1] or negedge SEL[1])
        ((SEL == 2'b10) && (A == B)) |-> (C == 1'b0)
    );

    // XOR: if A differs from B then C is 1.
    check_xor_one_when_diff: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge SEL[0] or negedge SEL[0] or posedge SEL[1] or negedge SEL[1])
        ((SEL == 2'b10) && (A != B)) |-> (C == 1'b1)
    );
endmodule

module counter_sva #(
    parameter WIDTH = 8,
    parameter MODULUS = 256
)(
    input  logic                 ce,
    input  logic                 clr,
    input  logic                 clk,
    input  logic [WIDTH-1:0]     out
);
    // Local constants sized to WIDTH
    localparam logic [WIDTH-1:0] MODM1 = MODULUS - 1;
    localparam logic [WIDTH-1:0] ZERO  = {WIDTH{1'b0}};

    ///// Synchronous clear behavior /////
    // On clr, out is 0 on the next cycle (clr overrides ce).
    check_sync_clear_sets_zero: assert property (
        @(posedge clk) clr |=> (out == ZERO)
    );

    ///// Normal operation (disable during clr) /////
    // With ce low and no clr, out holds its value.
    check_hold_when_ce_low: assert property (
        @(posedge clk) disable iff (clr) (!ce) |=> (out == $past(out))
    );

    // With ce high and not at MOD-1, out increments by 1.
    check_increment_when_enabled_nonmax: assert property (
        @(posedge clk) disable iff (clr) (ce && (out != MODM1)) |=> (out == $past(out) + 1)
    );

    // With ce high at MOD-1, out wraps to 0.
    check_wrap_when_enabled_at_max: assert property (
        @(posedge clk) disable iff (clr) (ce && (out == MODM1)) |=> (out == ZERO)
    );

    // Any change in out must be due to prior ce or clr.
    check_change_requires_enable_or_clear: assert property (
        @(posedge clk) (out != $past(out)) |-> ($past(ce) || $past(clr))
    );

    // Transition to 0 from nonzero without clr implies wrap due to ce at MOD-1.
    check_zero_transition_cause: assert property (
        @(posedge clk)
            (!$past(clr) && ($past(out) != ZERO) && (out == ZERO)) |-> ($past(ce) && ($past(out) == MODM1))
    );

    // With ce high and no clr, next out is either prev+1 or wraps to 0.
    check_enable_defines_next_state: assert property (
        @(posedge clk) disable iff (clr)
            ce |=> ((($past(out) != MODM1) && (out == $past(out) + 1)) ||
                    (($past(out) == MODM1) && (out == ZERO)))
    );
endmodule

rtl:
module binary_counter (
  input clk,
  input reset,
  output reg [2:0] out
);

  always @(posedge clk) begin
    case(out)
      3'b000: out <= 3'b001;
      3'b001: out <= 3'b010;
      3'b010: out <= 3'b011;
      3'b011: out <= 3'b100;
      3'b100: out <= 3'b101;
      3'b101: out <= 3'b110;
      3'b110: out <= 3'b000;
      default: out <= 3'b000;
    endcase
    if(reset) begin
      out <= 3'b000;
    end
  end

endmodule

sva:
module binary_counter_sva (
  input logic clk,
  input logic reset,
  input logic [2:0] out
);

  // Reset drives next out to 000 on the following clock.
  check_reset_clears_next: assert property (
    @(posedge clk) reset |=> (out == 3'b000)
  );

  // 000 -> 001 when not in reset.
  check_count_000_to_001: assert property (
    @(posedge clk) disable iff (reset) (out == 3'b000) |=> (out == 3'b001)
  );

  // 001 -> 010 when not in reset.
  check_count_001_to_010: assert property (
    @(posedge clk) disable iff (reset) (out == 3'b001) |=> (out == 3'b010)
  );

  // 010 -> 011 when not in reset.
  check_count_010_to_011: assert property (
    @(posedge clk) disable iff (reset) (out == 3'b010) |=> (out == 3'b011)
  );

  // 011 -> 100 when not in reset.
  check_count_011_to_100: assert property (
    @(posedge clk) disable iff (reset) (out == 3'b011) |=> (out == 3'b100)
  );

  // 100 -> 101 when not in reset.
  check_count_100_to_101: assert property (
    @(posedge clk) disable iff (reset) (out == 3'b100) |=> (out == 3'b101)
  );

  // 101 -> 110 when not in reset.
  check_count_101_to_110: assert property (
    @(posedge clk) disable iff (reset) (out == 3'b101) |=> (out == 3'b110)
  );

  // 110 -> 000 when not in reset.
  check_count_110_to_000: assert property (
    @(posedge clk) disable iff (reset) (out == 3'b110) |=> (out == 3'b000)
  );

  // Default case: 111 -> 000 when not in reset.
  check_default_111_to_000: assert property (
    @(posedge clk) disable iff (reset) (out == 3'b111) |=> (out == 3'b000)
  );

endmodule

module calc_sva (
    input logic CLK,           // sampling clock for assertions
    input logic [3:0] num1,
    input logic [3:0] num2,
    input logic       op,
    input logic [3:0] result
);
    // Result matches selected operation (4-bit modular arithmetic).
    check_core_functionality: assert property (
        @(posedge CLK) result == (op ? (num1 - num2) : (num1 + num2))
    );

    // If inputs are stable across a cycle, result remains stable.
    check_stable_when_inputs_stable: assert property (
        @(posedge CLK) $stable(op) && $stable(num1) && $stable(num2) |-> $stable(result)
    );

    // In subtraction mode, equal operands yield zero.
    check_sub_equal_operands_zero: assert property (
        @(posedge CLK) op && (num1 == num2) |-> (result == 4'd0)
    );

    // In addition mode, adding zero on RHS yields num1.
    check_add_zero_rhs_identity: assert property (
        @(posedge CLK) (!op) && (num2 == 4'd0) |-> (result == num1)
    );

    // In addition mode, adding zero on LHS yields num2.
    check_add_zero_lhs_identity: assert property (
        @(posedge CLK) (!op) && (num1 == 4'd0) |-> (result == num2)
    );

    // In subtraction mode, subtracting zero yields num1.
    check_sub_zero_rhs_identity: assert property (
        @(posedge CLK) op && (num2 == 4'd0) |-> (result == num1)
    );

    // In subtraction mode, (result + num2) recovers num1 (mod 16).
    check_sub_invertibility_mod16: assert property (
        @(posedge CLK) op |-> ((result + num2) == num1)
    );

    // In addition mode, (result - num2) recovers num1 (mod 16).
    check_add_invertibility_mod16: assert property (
        @(posedge CLK) (!op) |-> ((result - num2) == num1)
    );
endmodule

module parity_checker_sva (
    input logic CLK,          // External sampling clock (DUT has no clock/reset)
    input logic [3:0] data,
    input logic parity
);
    // Parity equals XOR reduction of data (4-state exact equality).
    check_parity_matches_reduction: assert property (
        @(posedge CLK) disable iff (1'b0) parity === (^data)
    );

    // Parity not X/Z when all data bits are known.
    check_parity_known_when_data_known: assert property (
        @(posedge CLK) disable iff (1'b0) (!$isunknown(data)) |-> (!$isunknown(parity))
    );

    // If inputs do not change, parity does not change (no storage; pure function).
    check_parity_stable_when_inputs_stable: assert property (
        @(posedge CLK) disable iff (1'b0) (data === $past(data)) |-> (parity === $past(parity))
    );

    // A single-bit flip in data causes parity to toggle.
    check_parity_toggles_on_single_bit_flip: assert property (
        @(posedge CLK) disable iff (1'b0)
            (!$isunknown(data) && !$isunknown($past(data)) && ($countones(data ^ $past(data)) == 1))
            |-> (parity !== $past(parity))
    );

    // Two-bit flips in data leave parity unchanged (even parity preservation).
    check_parity_stable_on_two_bit_flip: assert property (
        @(posedge CLK) disable iff (1'b0)
            (!$isunknown(data) && !$isunknown($past(data)) && ($countones(data ^ $past(data)) == 2))
            |-> (parity === $past(parity))
    );
endmodule

