sva:
module multiplexer32to16_sva (
    input logic CLK,
    input logic [31:0] out,
    input logic [31:0] in1,
    input logic [31:0] in2,
    input logic control
);
    // Vector mux behavior: out equals control ? in2 : in1.
    check_mux_vector_function: assert property (
        @(posedge CLK) out == (control ? in2 : in1)
    );

    // When control is 0, out equals in1.
    check_out_eq_in1_when_c0: assert property (
        @(posedge CLK) (control == 1'b0) |-> (out == in1)
    );

    // When control is 1, out equals in2.
    check_out_eq_in2_when_c1: assert property (
        @(posedge CLK) (control == 1'b1) |-> (out == in2)
    );

    // Equal inputs produce that value regardless of control.
    check_equal_inputs_dont_care_select: assert property (
        @(posedge CLK) (in1 == in2) |-> (out == in1)
    );

    // Mask-form equivalence: out == (~sel & in1) | (sel & in2).
    check_mask_equivalence: assert property (
        @(posedge CLK) out == ((~({32{control}}) & in1) | (({32{control}}) & in2))
    );

    // On 0->1 control transition, out equals in2 at that sample.
    check_out_after_rose_control: assert property (
        @(posedge CLK) $rose(control) |-> (out == in2)
    );

    // On 1->0 control transition, out equals in1 at that sample.
    check_out_after_fell_control: assert property (
        @(posedge CLK) $fell(control) |-> (out == in1)
    );

    // With control=0 and both control and in1 stable, out is stable.
    check_stability_c0: assert property (
        @(posedge CLK) (control == 1'b0 && $stable(control) && $stable(in1)) |-> $stable(out)
    );

    // With control=1 and both control and in2 stable, out is stable.
    check_stability_c1: assert property (
        @(posedge CLK) (control == 1'b1 && $stable(control) && $stable(in2)) |-> $stable(out)
    );
endmodule

module verilog_module_sva (
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB,
    input logic out
);
    // Sample on any signal edge since RTL is purely combinational.
    default clocking cb @(
        posedge VPWR or negedge VPWR or
        posedge VGND or negedge VGND or
        posedge VPB  or negedge VPB  or
        posedge VNB  or negedge VNB  or
        posedge out  or negedge out
    ); endclocking

    // out equals logical AND of all inputs.
    check_out_matches_and: assert property (
        out == (VPWR & VGND & VPB & VNB)
    );

    // If out is HIGH, all inputs must be HIGH.
    check_out_high_implies_inputs_high: assert property (
        out |-> (VPWR && VGND && VPB && VNB)
    );

    // If all inputs are HIGH, out must be HIGH.
    check_all_high_implies_out_high: assert property (
        (VPWR && VGND && VPB && VNB) |-> out
    );

    // If any input is LOW, out must be LOW.
    check_any_low_implies_out_low: assert property (
        (!VPWR || !VGND || !VPB || !VNB) |-> !out
    );

    // On out rising edge, all inputs must be HIGH.
    check_out_rise_requires_all_ones: assert property (
        @(posedge out) (VPWR && VGND && VPB && VNB)
    );

    // On out falling edge, at least one input must be LOW.
    check_out_fall_requires_some_zero: assert property (
        @(negedge out) (!VPWR || !VGND || !VPB || !VNB)
    );

    // A falling VPWR forces out LOW.
    check_vpwr_fall_forces_out_low: assert property (
        @(negedge VPWR) !out
    );

    // A falling VGND forces out LOW.
    check_vgnd_fall_forces_out_low: assert property (
        @(negedge VGND) !out
    );

    // A falling VPB forces out LOW.
    check_vpb_fall_forces_out_low: assert property (
        @(negedge VPB) !out
    );

    // A falling VNB forces out LOW.
    check_vnb_fall_forces_out_low: assert property (
        @(negedge VNB) !out
    );
endmodule

rtl:
module logic_function (
    input clk,
    input rst,
    input [3:0] din,
    output dout
);

// XOR the bits of the input together to count the number of 1's
wire [1:0] xor1 = din[0] ^ din[1];
wire [1:0] xor2 = din[2] ^ din[3];
wire [1:0] xor3 = xor1 ^ xor2;
wire [0:0] xor4 = xor3[0] ^ xor3[1];

// Invert the output to get the desired output
assign dout = ~xor4;

endmodule

sva:
module logic_function_sva (
    input logic clk,
    input logic rst,
    input logic [3:0] din,
    input logic dout
);
    // Clock: clk (posedge). Reset: rst active-high.
    // Logic: combinational; dout = ~(^din).

    // dout equals the inversion of the XOR-reduction of din.
    check_inverted_parity_function: assert property (
        @(posedge clk) disable iff (rst) (dout === ~(^din))
    );

    // When din has even parity, dout must be 1.
    check_even_parity_high: assert property (
        @(posedge clk) disable iff (rst) ((^din) === 1'b0) |-> (dout === 1'b1)
    );

    // When din has odd parity, dout must be 0.
    check_odd_parity_low: assert property (
        @(posedge clk) disable iff (rst) ((^din) === 1'b1) |-> (dout === 1'b0)
    );

    // Specific case: all zeros input yields dout=1 (even parity).
    check_all_zeros_high: assert property (
        @(posedge clk) disable iff (rst) (din == 4'b0000) |-> (dout === 1'b1)
    );

    // Specific case: all ones input yields dout=1 (even parity).
    check_all_ones_high: assert property (
        @(posedge clk) disable iff (rst) (din == 4'b1111) |-> (dout === 1'b1)
    );
endmodule

rtl:
module four_bit_adder(
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] Sum,
    output Cout
);

    wire c1, c2, c3;
    one_bit_adder fa1(.a(A[0]), .b(B[0]), .cin(Cin), .sum(Sum[0]), .cout(c1));
    one_bit_adder fa2(.a(A[1]), .b(B[1]), .cin(c1), .sum(Sum[1]), .cout(c2));
    one_bit_adder fa3(.a(A[2]), .b(B[2]), .cin(c2), .sum(Sum[2]), .cout(c3));
    one_bit_adder fa4(.a(A[3]), .b(B[3]), .cin(c3), .sum(Sum[3]), .cout(Cout));

endmodule
module one_bit_adder(
    input a,
    input b,
    input cin,
    output sum,
    output cout
);

    assign sum = a ^ b ^ cin;
    assign cout = (a & b) | (b & cin) | (a & cin);

endmodule

sva:
module four_bit_adder_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic       Cin,
    input logic [3:0] Sum,
    input logic       Cout
);
    // No clock/reset in DUT; combinational logic; use $global_clock for sampling.

    // Local let expressions for ripple carries derived from DUT equations
    let c1 = (A[0] & B[0]) | (B[0] & Cin) | (A[0] & Cin);
    let c2 = (A[1] & B[1]) | (B[1] & c1)  | (A[1] & c1);
    let c3 = (A[2] & B[2]) | (B[2] & c2)  | (A[2] & c2);

    ///// Functional correctness /////
    // 5-bit sum equals A + B + Cin.
    check_full_sum: assert property (
        @(posedge $global_clock) {Cout, Sum} == ({1'b0, A} + {1'b0, B} + Cin)
    );
    // Sum low 4 bits match truncated addition.
    check_sum_low4: assert property (
        @(posedge $global_clock) Sum == (({1'b0, A} + {1'b0, B} + Cin)[3:0])
    );
    // Cout equals MSB of 5-bit addition result.
    check_cout_msb: assert property (
        @(posedge $global_clock) Cout == (({1'b0, A} + {1'b0, B} + Cin)[4])
    );

    ///// Bit-slice correctness /////
    // LSB sum implements XOR of A[0], B[0], Cin.
    check_sum0_xor: assert property (
        @(posedge $global_clock) Sum[0] == (A[0] ^ B[0] ^ Cin)
    );
    // Bit1 sum uses carry c1 from bit0.
    check_sum1_xor: assert property (
        @(posedge $global_clock) Sum[1] == (A[1] ^ B[1] ^ c1)
    );
    // Bit2 sum uses carry c2 from bit1.
    check_sum2_xor: assert property (
        @(posedge $global_clock) Sum[2] == (A[2] ^ B[2] ^ c2)
    );
    // Bit3 sum uses carry c3 from bit2.
    check_sum3_xor: assert property (
        @(posedge $global_clock) Sum[3] == (A[3] ^ B[3] ^ c3)
    );
    // Cout is majority of A[3], B[3], and c3.
    check_cout_majority: assert property (
        @(posedge $global_clock) Cout == ((A[3] & B[3]) | (B[3] & c3) | (A[3] & c3))
    );

    ///// Basic identities /////
    // Adding zero B and zero Cin returns A with no carry.
    check_add_zero_B: assert property (
        @(posedge $global_clock) ((B == 4'b0000) && (Cin == 1'b0)) |=> ((Sum == A) && (Cout == 1'b0))
    );
    // Adding zero A and zero Cin returns B with no carry.
    check_add_zero_A: assert property (
        @(posedge $global_clock) ((A == 4'b0000) && (Cin == 1'b0)) |=> ((Sum == B) && (Cout == 1'b0))
    );
endmodule

rtl:
module alu(
		input		[3:0]	ctl,
		input		[31:0]	a, b,
		output reg	[31:0]	out,
		output				zero,
		output				oflow);

	wire [31:0] sub_ab;
	wire [31:0] add_ab;
	wire 		oflow_add;
	wire 		oflow_sub;
	wire 		slt;

	assign zero = (0 == out);

	assign sub_ab = a - b;
	assign add_ab = a + b;

	assign oflow_add = (a[31] == b[31] && add_ab[31] != a[31]) ? 1 : 0;
	assign oflow_sub = (a[31] == b[31] && sub_ab[31] != a[31]) ? 1 : 0;

	assign oflow = (ctl == 4'b0010) ? oflow_add : oflow_sub;

	assign slt = oflow_sub ? ~(a[31]) : a[31];

	always @(*) begin
		case (ctl)
			4'd2:  out <= add_ab;				
			4'd0:  out <= a & b;				
			4'd12: out <= ~(a | b);				
			4'd1:  out <= a | b;				
			4'd7:  out <= {{31{1'b0}}, slt};	
			4'd6:  out <= sub_ab;				
			4'd13: out <= a ^ b;				
			default: out <= 0;
		endcase
	end

endmodule

