    input logic A,
    input logic B,
    input logic SUM,
    input logic COUT
);
    // Analysis: no reset in RTL; pure combinational; SUM=A^B, COUT=A&B.

    // SUM equals A XOR B.
    check_sum_def: assert property (
        @(posedge CLK) SUM == (A ^ B)
    );

    // COUT equals A AND B.
    check_cout_def: assert property (
        @(posedge CLK) COUT == (A & B)
    );

