module example004_sva (
    input logic clk,
    input logic rst,
    input logic y,
    input logic [3:0] counter
);
    // y reflects (counter == 12)
    check_y_matches_counter_eq12: assert property (
        @(posedge clk) disable iff (rst) (y == (counter == 4'd12))
    );

    // On reset assertion, next counter is 0
    check_reset_drives_counter_zero_next: assert property (
        @(posedge clk) rst |-> ##1 (counter == 4'd0)
    );

    // While reset is held HIGH across consecutive cycles, counter stays 0
    check_hold_zero_while_reset: assert property (
        @(posedge clk) rst && $past(rst) |-> (counter == 4'd0)
    );

    // When not in reset and counter != 9, next is either reset asserted or counter increments by 1
    check_increment_or_reset: assert property (
        @(posedge clk) disable iff (rst) (counter != 4'd9) |-> ##1 (rst || (counter == $past(counter) + 4'd1))
    );

    // When not in reset and counter is 9, next counter is 0
    check_wrap_on_nine: assert property (
        @(posedge clk) disable iff (rst) (counter == 4'd9) |-> ##1 (counter == 4'd0)
    );

    // y cannot be HIGH in two consecutive cycles (counter advances)
    check_y_not_sticky: assert property (
        @(posedge clk) disable iff (rst) y |-> ##1 !y
    );

    // When not in reset and counter is 15, next counter wraps to 0 (4-bit increment)
    check_wrap_on_fifteen: assert property (
        @(posedge clk) disable iff (rst) (counter == 4'd15) |-> ##1 (counter == 4'd0)
    );

    // On reset assertion, next y is 0 (since counter becomes 0)
    check_reset_drives_y_zero_next: assert property (
        @(posedge clk) rst |-> ##1 (y == 1'b0)
    );
endmodule

module alu_4bit_sva (
    input logic CLK,
    input logic [3:0] Z,
    input logic [1:0] op,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] C
);
    // For op=00, Z equals 4-bit A+B.
    check_add_correct: assert property (
        @(posedge CLK) (op == 2'b00) |-> (Z == (A + B))
    );

    // For op=00, Z-B equals A modulo 16.
    check_add_inverse: assert property (
        @(posedge CLK) (op == 2'b00) |-> ((Z - B) == A)
    );

    // For op=01, Z equals 4-bit A-B.
    check_sub_correct: assert property (
        @(posedge CLK) (op == 2'b01) |-> (Z == (A - B))
    );

    // For op=01, Z+B equals A modulo 16.
    check_sub_inverse: assert property (
        @(posedge CLK) (op == 2'b01) |-> ((Z + B) == A)
    );

    // For op=10, Z equals A & B.
    check_and_correct: assert property (
        @(posedge CLK) (op == 2'b10) |-> (Z == (A & B))
    );

    // For op=10, Z can only have bits set that are set in A.
    check_and_subset_A: assert property (
        @(posedge CLK) (op == 2'b10) |-> ((Z & ~A) == 4'b0000)
    );

    // For op=10, Z can only have bits set that are set in B.
    check_and_subset_B: assert property (
        @(posedge CLK) (op == 2'b10) |-> ((Z & ~B) == 4'b0000)
    );

    // For op=11, Z equals A | B.
    check_or_correct: assert property (
        @(posedge CLK) (op == 2'b11) |-> (Z == (A | B))
    );

    // For op=11, all bits set in A must be set in Z.
    check_or_superset_A: assert property (
        @(posedge CLK) (op == 2'b11) |-> ((~Z & A) == 4'b0000)
    );

    // For op=11, all bits set in B must be set in Z.
    check_or_superset_B: assert property (
        @(posedge CLK) (op == 2'b11) |-> ((~Z & B) == 4'b0000)
    );

    // If op, A, and B are stable, Z must remain stable.
    check_stable_when_inputs_stable: assert property (
        @(posedge CLK) $stable({op,A,B}) |-> $stable(Z)
    );

    // Z must be independent of C; C changes alone cannot change Z.
    check_independent_of_C: assert property (
        @(posedge CLK) $stable({op,A,B}) && $changed(C) |-> $stable(Z)
    );
endmodule

