module input_output_module(
    input wire CLK,
    output reg [6:0] Q
);

reg [6:0] inputs_reg;
wire [6:0] inputs_delayed;

always @(posedge CLK) begin
    inputs_reg <= Q;
end

assign inputs_delayed[0] = inputs_reg[6];
assign inputs_delayed[1] = inputs_reg[5];
assign inputs_delayed[2] = inputs_reg[4];
assign inputs_delayed[3] = inputs_reg[3];
assign inputs_delayed[4] = inputs_reg[2];
assign inputs_delayed[5] = inputs_reg[1];
assign inputs_delayed[6] = inputs_reg[0];

reg [6:0] delay_counter;
reg [2:0] input_counter;
reg [1:0] state_counter;

always @(posedge CLK) begin
    delay_counter <= delay_counter + 1;
    if (delay_counter == 20) begin
        delay_counter <= 0;
        input_counter <= input_counter + 1;
        if (input_counter == 7) begin
            input_counter <= 0;
            state_counter <= state_counter + 1;
            if (state_counter == 3) begin
                state_counter <= 0;
            end
        end
    end
end

reg [6:0] inputs_pattern_0 = 7'b1000000;
reg [6:0] inputs_pattern_1 = 7'b0111111;
reg [6:0] inputs_pattern_2 = 7'bxxxxxxx;

always @(posedge CLK) begin
    case (state_counter)
        0: Q <= inputs_pattern_0;
        1: Q <= inputs_pattern_1;
        2: Q <= inputs_pattern_2;
    endcase
end

wire Q_delayed;
reg Q_delayed_reg;
assign Q_delayed = Q;

always @(posedge CLK) begin
    Q_delayed_reg <= Q;
end

endmodule

sva:
module input_output_module_sva (
    input logic        CLK,
    input logic [6:0]  Q,

    // Internal DUT signals (for bind-by-name)
    input logic [6:0]  inputs_reg,
    input logic [6:0]  inputs_delayed,
    input logic [6:0]  delay_counter,
    input logic [2:0]  input_counter,
    input logic [1:0]  state_counter,
    input logic [6:0]  inputs_pattern_0,
    input logic [6:0]  inputs_pattern_1,
    input logic [6:0]  inputs_pattern_2,
    input logic        Q_delayed,
    input logic        Q_delayed_reg
);
    // Q_delayed is a direct alias of Q.
    check_q_delayed_alias: assert property (
        @(posedge CLK) Q_delayed == Q
    );

    // Q_delayed_reg captures Q with one-cycle latency.
    check_q_delayed_reg_captures_q: assert property (
        @(posedge CLK) Q_delayed_reg == $past(Q)
    );

    // inputs_reg captures Q each cycle.
    check_inputs_reg_captures_q: assert property (
        @(posedge CLK) inputs_reg == $past(Q)
    );

    // inputs_delayed is the bit-reversed view of inputs_reg.
    check_inputs_delayed_is_reverse: assert property (
        @(posedge CLK) inputs_delayed == {inputs_reg[0],inputs_reg[1],inputs_reg[2],inputs_reg[3],inputs_reg[4],inputs_reg[5],inputs_reg[6]}
    );

    // delay_counter increments by 1 when previous value was not 20.
    check_delay_counter_incr: assert property (
        @(posedge CLK) ($past(delay_counter) != 7'd20) |-> (delay_counter == $past(delay_counter) + 7'd1)
    );

    // delay_counter resets to 0 when previous value was 20.
    check_delay_counter_rollover: assert property (
        @(posedge CLK) ($past(delay_counter) == 7'd20) |-> (delay_counter == 7'd0)
    );

    // input_counter holds unless delay_counter hit 20.
    check_input_counter_holds_without_tick: assert property (
        @(posedge CLK) ($past(delay_counter) != 7'd20) |-> (input_counter == $past(input_counter))
    );

    // input_counter increments when delay_counter hit 20 and not at 7.
    check_input_counter_increments_on_tick: assert property (
        @(posedge CLK) ($past(delay_counter) == 7'd20 && $past(input_counter) != 3'd7) |-> (input_counter == $past(input_counter) + 3'd1)
    );

    // input_counter resets to 0 when it was 7 and delay_counter hit 20.
    check_input_counter_rollover: assert property (
        @(posedge CLK) ($past(delay_counter) == 7'd20 && $past(input_counter) == 3'd7) |-> (input_counter == 3'd0)
    );

    // state_counter holds unless input_counter was 7 and delay_counter hit 20.
    check_state_counter_holds_without_roll: assert property (
        @(posedge CLK) !($past(delay_counter) == 7'd20 && $past(input_counter) == 3'd7) |-> (state_counter == $past(state_counter))
    );

    // state_counter increments when roll event occurs and previous value was not 3.
    check_state_counter_increments: assert property (
        @(posedge CLK) ($past(delay_counter) == 7'd20 && $past(input_counter) == 3'd7 && $past(state_counter) != 2'd3) |-> (state_counter == $past(state_counter) + 2'd1)
    );

    // state_counter resets to 0 when roll event occurs and previous value was 3.
    check_state_counter_resets_to_zero: assert property (
        @(posedge CLK) ($past(delay_counter) == 7'd20 && $past(input_counter) == 3'd7 && $past(state_counter) == 2'd3) |-> (state_counter == 2'd0)
    );

    // When previous state was 0, Q is driven by inputs_pattern_0.
    check_q_when_state0: assert property (
        @(posedge CLK) ($past(state_counter) == 2'd0) |-> (Q == inputs_pattern_0)
    );

    // When previous state was 1, Q is driven by inputs_pattern_1.
    check_q_when_state1: assert property (
        @(posedge CLK) ($past(state_counter) == 2'd1) |-> (Q == inputs_pattern_1)
    );

    // When previous state was 3, Q holds its previous value (no assignment in case).
    check_q_holds_when_state3: assert property (
        @(posedge CLK) ($past(state_counter) == 2'd3) |-> (Q == $past(Q))
    );
endmodule

rtl:
module SerialRX(clk, RxD, RxD_data_ready, RxD_data, RxD_endofpacket, RxD_idle);
input clk, RxD;
output RxD_data_ready;  output [7:0] RxD_data;

parameter ClkFrequency = 16000000; parameter Baud = 115200;

output RxD_endofpacket;  output RxD_idle;  parameter Baud8 = Baud*8;
parameter Baud8GeneratorAccWidth = 16;
wire [Baud8GeneratorAccWidth:0] Baud8GeneratorInc = ((Baud8<<(Baud8GeneratorAccWidth-7))+(ClkFrequency>>8))/(ClkFrequency>>7);
reg [Baud8GeneratorAccWidth:0] Baud8GeneratorAcc;
always @(posedge clk) Baud8GeneratorAcc <= Baud8GeneratorAcc[Baud8GeneratorAccWidth-1:0] + Baud8GeneratorInc;
wire Baud8Tick = Baud8GeneratorAcc[Baud8GeneratorAccWidth];

reg [1:0] RxD_sync_inv;
always @(posedge clk) if(Baud8Tick) RxD_sync_inv <= {RxD_sync_inv[0], ~RxD};
reg [1:0] RxD_cnt_inv;
reg RxD_bit_inv;

always @(posedge clk)
if(Baud8Tick)
begin
	if( RxD_sync_inv[1] && RxD_cnt_inv!=2'b11) RxD_cnt_inv <= RxD_cnt_inv + 2'h1;
	else 
	if(~RxD_sync_inv[1] && RxD_cnt_inv!=2'b00) RxD_cnt_inv <= RxD_cnt_inv - 2'h1;

	if(RxD_cnt_inv==2'b00) RxD_bit_inv <= 1'b0;
	else
	if(RxD_cnt_inv==2'b11) RxD_bit_inv <= 1'b1;
end

reg [3:0] state;
reg [3:0] bit_spacing;

wire next_bit = (bit_spacing==4'd10);

always @(posedge clk)
if(state==0)
	bit_spacing <= 4'b0000;
else
if(Baud8Tick)
	bit_spacing <= {bit_spacing[2:0] + 4'b0001} | {bit_spacing[3], 3'b000};

always @(posedge clk)
if(Baud8Tick)
case(state)
	4'b0000: if(RxD_bit_inv) state <= 4'b1000;  4'b1000: if(next_bit) state <= 4'b1001;  4'b1001: if(next_bit) state <= 4'b1010;  4'b1010: if(next_bit) state <= 4'b1011;  4'b1011: if(next_bit) state <= 4'b1100;  4'b1100: if(next_bit) state <= 4'b1101;  4'b1101: if(next_bit) state <= 4'b1110;  4'b1110: if(next_bit) state <= 4'b1111;  4'b1111: if(next_bit) state <= 4'b0001;  4'b0001: if(next_bit) state <= 4'b0000;  default: state <= 4'b0000;
endcase

reg [7:0] RxD_data;
always @(posedge clk)
if(Baud8Tick && next_bit && state[3]) RxD_data <= {~RxD_bit_inv, RxD_data[7:1]};

reg RxD_data_ready;
always @(posedge clk)
begin
	RxD_data_ready <= (Baud8Tick && next_bit && state==4'b0001 && ~RxD_bit_inv);  end

reg [4:0] gap_count;
always @(posedge clk) if (state!=0) gap_count<=5'h00; else if(Baud8Tick & ~gap_count[4]) gap_count <= gap_count + 5'h01;
assign RxD_idle = gap_count[4];
reg RxD_endofpacket; always @(posedge clk) RxD_endofpacket <= Baud8Tick & (gap_count==5'h0F);

endmodule

sva:
module SerialRX_sva (
    input logic clk,
    input logic RxD,
    input logic RxD_data_ready,
    input logic [7:0] RxD_data,
    input logic RxD_endofpacket,
    input logic RxD_idle
);
    // Clock: clk (posedge). No reset in RTL. Mixed logic (sequential regs; RxD_idle is combinational from a counter).

    // End-of-packet implies entering idle now and was not idle in the previous cycle.
    check_eop_implies_idle_and_prev_not_idle: assert property (
        @(posedge clk) RxD_endofpacket |-> (RxD_idle && !$past(RxD_idle,1,1'b0))
    );

    // Idle rising edge only occurs together with end-of-packet.
    check_idle_rise_implies_eop: assert property (
        @(posedge clk) (!$past(RxD_idle,1,1'b0) && RxD_idle) |-> RxD_endofpacket
    );

    // End-of-packet is a single-cycle pulse (no back-to-back 1s).
    check_eop_one_cycle_pulse: assert property (
        @(posedge clk) $past(RxD_endofpacket,1,1'b0) |-> !RxD_endofpacket
    );

    // Data-ready is a single-cycle pulse (no back-to-back 1s).
    check_data_ready_one_cycle_pulse: assert property (
        @(posedge clk) $past(RxD_data_ready,1,1'b0) |-> !RxD_data_ready
    );

    // When idle, data-ready must be low.
    check_idle_excludes_data_ready: assert property (
        @(posedge clk) RxD_idle |-> !RxD_data_ready
    );

    // When data-ready is high, idle must be low.
    check_data_ready_excludes_idle: assert property (
        @(posedge clk) RxD_data_ready |-> !RxD_idle
    );

    // When data-ready is high, end-of-packet must be low.
    check_data_ready_excludes_eop: assert property (
        @(posedge clk) RxD_data_ready |-> !RxD_endofpacket
    );

    // While staying idle (not the first idle cycle), end-of-packet cannot assert.
    check_idle_steady_no_eop: assert property (
        @(posedge clk) (RxD_idle && $past(RxD_idle,1,1'b0)) |-> !RxD_endofpacket
    );

    // Idle falling edge cannot coincide with end-of-packet or data-ready.
    check_idle_fall_excludes_eop_and_data_ready: assert property (
        @(posedge clk) ($past(RxD_idle,1,1'b0) && !RxD_idle) |-> (!RxD_endofpacket && !RxD_data_ready)
    );

    // Data bus is stable on the cycle data-ready is asserted.
    check_data_stable_on_ready: assert property (
        @(posedge clk) RxD_data_ready |-> (RxD_data == $past(RxD_data,1,RxD_data))
    );

    // Data bus remains stable during idle cycles.
    check_data_stable_while_idle: assert property (
        @(posedge clk) RxD_idle |-> (RxD_data == $past(RxD_data,1,RxD_data))
    );
endmodule

module multi_input_output_sva (
    input logic [7:0] A,
    input logic [7:0] B,
    input logic [7:0] C,
    input logic [7:0] D,
    input logic [7:0] E,
    input logic [7:0] F,
    input logic [7:0] G,
    input logic [7:0] H,
    input logic [7:0] Y
);

    ///// Functional correctness /////
    // Y equals (A+B)-(C+D)+(E+F)-(G+H) with 8-bit wrap.
    check_y_definition: assert property (
        @(posedge A[0]) Y == (A + B) - (C + D) + (E + F) - (G + H)
    );

    // All inputs zero yields Y=0.
    check_y_all_zero_input: assert property (
        @(posedge A[0]) ((A==8'h00)&&(B==8'h00)&&(C==8'h00)&&(D==8'h00)&&(E==8'h00)&&(F==8'h00)&&(G==8'h00)&&(H==8'h00))
        |-> (Y==8'h00)
    );

    // If B..H are zero, Y passes A.
    check_y_passthrough_A_when_others_zero: assert property (
        @(posedge A[0]) ((B==8'h00)&&(C==8'h00)&&(D==8'h00)&&(E==8'h00)&&(F==8'h00)&&(G==8'h00)&&(H==8'h00))
        |-> (Y==A)
    );

    // If pairwise inputs match (A=C,B=D,E=G,F=H), Y is zero.
    check_y_zero_when_pairs_equal: assert property (
        @(posedge A[0]) ((A==C)&&(B==D)&&(E==G)&&(F==H))
        |-> (Y==8'h00)
    );

    // If E=F=G=H=0, Y=(A+B)-(C+D).
    check_y_when_EFGH_zero: assert property (
        @(posedge A[0]) ((E==8'h00)&&(F==8'h00)&&(G==8'h00)&&(H==8'h00))
        |-> (Y == (A + B) - (C + D))
    );

    // If G=H=0, Y=(A+B)-(C+D)+(E+F).
    check_y_when_GH_zero: assert property (
        @(posedge A[0]) ((G==8'h00)&&(H==8'h00))
        |-> (Y == (A + B) - (C + D) + (E + F))
    );

    // If A=B=C=D=0, Y=(E+F)-(G+H).
    check_y_when_ABCD_zero: assert property (
        @(posedge A[0]) ((A==8'h00)&&(B==8'h00)&&(C==8'h00)&&(D==8'h00))
        |-> (Y == (E + F) - (G + H))
    );

    ///// Algebraic cancellation checks (mod-256 arithmetic) /////
    // Adding back (G+H) cancels the final subtraction.
    check_cancel_gh_addback: assert property (
        @(posedge A[0]) (Y + (G + H)) == ( (A + B) - (C + D) + (E + F) )
    );

    // Adding back (G+H) then subtracting (E+F) cancels the last two pairs.
    check_cancel_gh_then_ef: assert property (
        @(posedge A[0]) ((Y + (G + H)) - (E + F)) == ( (A + B) - (C + D) )
    );

    // After canceling GH and EF and adding (C+D), recover (A+B).
    check_recover_ab: assert property (
        @(posedge A[0]) (((Y + (G + H)) - (E + F)) + (C + D)) == (A + B)
    );

endmodule

