// 2-to-1 MUX module
module mux2to1 (
    input [3:0] in0,
    input [3:0] in1,
    input sel,
    output reg [3:0] out
);

always @(*) begin
    if(sel == 1'b0) begin
        out = in0;
    end
    else begin
        out = in1;
    end
