sva:
module mux4to1_using_2to1_sva (
    input logic clk,             // Sampling clock for SVA (DUT is combinational)
    input logic [3:0] in0,
    input logic [3:0] in1,
    input logic [3:0] in2,
    input logic [3:0] in3,
    input logic [1:0] sel,
    input logic [3:0] out
);
    // DUT analysis: no clock/reset in RTL; purely combinational 4:1 mux built from 2:1 stages.

    ///// Functional routing rules /////
    // When sel == 2'b00, out must equal in0.
    check_sel00_routes_in0: assert property (
        @(posedge clk) (sel === 2'b00) |-> ##0 (out == in0)
    );
    // When sel == 2'b01, out must equal in1.
    check_sel01_routes_in1: assert property (
        @(posedge clk) (sel === 2'b01) |-> ##0 (out == in1)
    );
    // When sel == 2'b10, out must equal in2.
    check_sel10_routes_in2: assert property (
        @(posedge clk) (sel === 2'b10) |-> ##0 (out == in2)
    );
    // When sel == 2'b11, out must equal in3.
    check_sel11_routes_in3: assert property (
        @(posedge clk) (sel === 2'b11) |-> ##0 (out == in3)
    );

    ///// Combinational stability and causality /////
    // If all inputs and sel are stable, out must be stable.
    check_out_stable_if_all_inputs_stable: assert property (
        @(posedge clk) ($stable(in0) && $stable(in1) && $stable(in2) && $stable(in3) && $stable(sel)) |-> ##0 $stable(out)
    );
    // If out changed, at least one input or sel must have changed.
    check_out_change_has_cause: assert property (
        @(posedge clk) $changed(out) |-> ##0 (!$stable({in0,in1,in2,in3,sel}))
    );

    ///// Non-selected inputs do not affect out /////
    // With sel==00 and sel/in0 stable, out must remain stable.
    check_no_effect_others_when_00: assert property (
        @(posedge clk) (sel === 2'b00 && $stable(sel) && $stable(in0)) |-> ##0 $stable(out)
    );
    // With sel==01 and sel/in1 stable, out must remain stable.
    check_no_effect_others_when_01: assert property (
        @(posedge clk) (sel === 2'b01 && $stable(sel) && $stable(in1)) |-> ##0 $stable(out)
    );
    // With sel==10 and sel/in2 stable, out must remain stable.
    check_no_effect_others_when_10: assert property (
        @(posedge clk) (sel === 2'b10 && $stable(sel) && $stable(in2)) |-> ##0 $stable(out)
    );
    // With sel==11 and sel/in3 stable, out must remain stable.
    check_no_effect_others_when_11: assert property (
        @(posedge clk) (sel === 2'b11 && $stable(sel) && $stable(in3)) |-> ##0 $stable(out)
    );

endmodule

rtl:
module async_counter (
    input clk,
    input reset,      // Asynchronous active-high reset
    input up_down,    // Control input to select count direction
    output reg [2:0] q
);

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            q <= 3'b000;
        end else if (up_down) begin
            q <= q + 1;
        end else begin
            q <= q - 1;
        end
    end

endmodule

sva:
module async_counter_sva (
    input logic clk,
    input logic reset,       // Asynchronous active-high reset
    input logic up_down,     // Count direction: 1=up, 0=down
    input logic [2:0] q
);
    // While reset is asserted, q must be 0 on each clock.
    reset_holds_zero: assert property (
        @(posedge clk) reset |-> (q == 3'b000)
    );

    // When counting up, q increments by 1 modulo 8.
    count_up_increments: assert property (
        @(posedge clk) disable iff (reset) (up_down && $past(1'b1)) |-> (q == ($past(q) + 3'd1))
    );

    // When counting down, q decrements by 1 modulo 8.
    count_down_decrements: assert property (
        @(posedge clk) disable iff (reset) (!up_down && $past(1'b1)) |-> (q == ($past(q) - 3'd1))
    );

    // Increment from 7 wraps to 0.
    wrap_up_from_7_to_0: assert property (
        @(posedge clk) disable iff (reset) (up_down && $past(1'b1) && ($past(q) == 3'd7)) |-> (q == 3'd0)
    );

    // Decrement from 0 wraps to 7.
    wrap_down_from_0_to_7: assert property (
        @(posedge clk) disable iff (reset) (!up_down && $past(1'b1) && ($past(q) == 3'd0)) |-> (q == 3'd7)
    );

    // On every non-reset cycle, q must change (never holds its value).
    non_reset_always_changes: assert property (
        @(posedge clk) disable iff (reset) $past(1'b1) |-> (q != $past(q))
    );

    // If up_down stays high for two cycles, q advances by +2 modulo 8.
    two_cycle_up_add2: assert property (
        @(posedge clk) disable iff (reset) (up_down && $past(up_down) && $past(1'b1,2)) |-> (q == ($past(q,2) + 3'd2))
    );

    // If up_down stays low for two cycles, q retreats by -2 modulo 8.
    two_cycle_down_sub2: assert property (
        @(posedge clk) disable iff (reset) (!up_down && !$past(up_down) && $past(1'b1,2)) |-> (q == ($past(q,2) - 3'd2))
    );

    // On reset deassert with up count, q becomes 1 (0 + 1).
    release_to_up_starts_at1: assert property (
        @(posedge clk) disable iff (reset) ($fell(reset) && up_down) |-> (q == 3'd1)
    );

    // On reset deassert with down count, q becomes 7 (0 - 1).
    release_to_down_starts_at7: assert property (
        @(posedge clk) disable iff (reset) ($fell(reset) && !up_down) |-> (q == 3'd7)
    );
endmodule

rtl:
module Modulo (
  input [n-1:0] numerator,
  input [n-1:0] denominator,
  output reg [n-1:0] remainder
);

parameter n = 8; // number of bits for numerator and denominator.

reg [n-1:0] quotient;
reg [n-1:0] dividend;

always @(*) begin
  if (denominator == 0) begin
    remainder <= 0;
  end
  else if (numerator < denominator) begin
    remainder <= numerator;
  end
  else begin
    quotient = numerator / denominator;
    dividend = quotient * denominator;
    remainder <= numerator - dividend;
  end
end

endmodule

sva:
module Modulo_sva #(
    parameter int n = 8
) (
    input logic CLK,
    input logic RESETn,
    input logic [n-1:0] numerator,
    input logic [n-1:0] denominator,
    input logic [n-1:0] remainder
);

    // When denominator is zero, remainder must be zero.
    check_zero_denominator_drives_zero_remainder: assert property (
        @(posedge CLK) disable iff (!RESETn) (denominator == {n{1'b0}}) |-> (remainder == {n{1'b0}})
    );

    // When denominator is nonzero and numerator < denominator, remainder equals numerator.
    check_lt_path_returns_numerator: assert property (
        @(posedge CLK) disable iff (!RESETn) (denominator != {n{1'b0}} && (numerator < denominator)) |-> (remainder == numerator)
    );

    // When denominator is nonzero and numerator == denominator, remainder is zero.
    check_equal_values_return_zero: assert property (
        @(posedge CLK) disable iff (!RESETn) (denominator != {n{1'b0}} && (numerator == denominator)) |-> (remainder == {n{1'b0}})
    );

    // For nonzero denominator, remainder is strictly less than denominator.
    check_remainder_less_than_denominator_when_div_valid: assert property (
        @(posedge CLK) disable iff (!RESETn) (denominator != {n{1'b0}}) |-> (remainder < denominator)
    );

    // Remainder is never greater than numerator.
    check_remainder_not_greater_than_numerator: assert property (
        @(posedge CLK) disable iff (!RESETn) (remainder <= numerator)
    );

    // For nonzero denominator, remainder equals numerator % denominator.
    check_mod_equivalence_when_div_valid: assert property (
        @(posedge CLK) disable iff (!RESETn) (denominator != {n{1'b0}}) |-> (remainder == (numerator % denominator))
    );

    // For nonzero denominator, remainder equals numerator - (floor(numerator/denominator) * denominator).
    check_division_identity_when_div_valid: assert property (
        @(posedge CLK) disable iff (!RESETn) (denominator != {n{1'b0}}) |-> 
            (remainder == (numerator - (((numerator / denominator) * denominator)[n-1:0])))
    );

    // When denominator is one, remainder must be zero.
    check_denominator_one_gives_zero_remainder: assert property (
        @(posedge CLK) disable iff (!RESETn) (denominator == {{(n-1){1'b0}},1'b1}) |-> (remainder == {n{1'b0}})
    );

    // When numerator is zero, remainder must be zero.
    check_zero_numerator_gives_zero_remainder: assert property (
        @(posedge CLK) disable iff (!RESETn) (numerator == {n{1'b0}}) |-> (remainder == {n{1'b0}})
    );

    // If inputs are stable cycle-to-cycle, remainder is stable (purely combinational behavior).
    check_stable_io_yields_stable_remainder: assert property (
        @(posedge CLK) disable iff (!RESETn) ($stable(numerator) && $stable(denominator)) |-> $stable(remainder)
    );

endmodule

rtl:
module priority_encoder(input [3:0] in, output reg [1:0] out);

always @(*) begin
    case(in)
        4'b0001: out = 2'b01;
        4'b0010: out = 2'b10;
        4'b0100: out = 2'b11;
        4'b1000: out = 2'b00;
        4'b0011, 4'b0111, 4'b1111: out = 2'b10;
        4'b0101, 4'b1011, 4'b1101: out = 2'b11;
        4'b0110, 4'b1010, 4'b1100: out = 2'b10;
        default: out = 2'b00;
    endcase
end

endmodule

