module sky130_fd_sc_ls__nor3 (input A, B, C, VPWR, VGND, VPB, VNB, output Y);
    assign Y = ~(A | B | C);
endmodule

sva:
module sky130_fd_sc_ls__nor3_sva (
    input logic CLK,
    input logic RESETn,
    input logic A,
    input logic B,
    input logic C,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB,
    input logic Y
);
    // Y equals NOR of A,B,C each cycle.
    check_nor_function: assert property (
        @(posedge CLK) disable iff (!RESETn) Y == ~(A | B | C)
    );

    // When all inputs are 0, Y must be 1.
    check_y_one_when_all_zero: assert property (
        @(posedge CLK) disable iff (!RESETn) (!A && !B && !C) |-> (Y == 1'b1)
    );

    // When any input is 1, Y must be 0.
    check_y_zero_when_any_one: assert property (
        @(posedge CLK) disable iff (!RESETn) (A | B | C) |-> (Y == 1'b0)
    );

    // If Y is 1, then all inputs must be 0.
    check_y1_implies_all_zero: assert property (
        @(posedge CLK) disable iff (!RESETn) (Y == 1'b1) |-> (!A && !B && !C)
    );

    // If Y is 0, then at least one input must be 1.
    check_y0_implies_any_one: assert property (
        @(posedge CLK) disable iff (!RESETn) (Y == 1'b0) |-> (A | B | C)
    );

    // If A,B,C are stable, Y must also be stable.
    check_y_stable_when_inputs_stable: assert property (
        @(posedge CLK) disable iff (!RESETn) $stable({A,B,C}) |-> $stable(Y)
    );
endmodule

rtl:
module my_module (
    Q,
    CLK,
    D,
    SCD,
    SCE,
    RESET_B,
    VPWR,
    VGND,
    VPB,
    VNB
);

    // Module ports
    output Q;
    input CLK;
    input D;
    input SCD;
    input SCE;
    input RESET_B;
    input VPWR;
    input VGND;
    input VPB;
    input VNB;

    // Local signals
    wire buf_Q;
    wire RESET;
    wire mux_out;
    reg notifier;
    wire D_delayed;
    wire SCD_delayed;
    wire SCE_delayed;
    wire RESET_B_delayed;
    wire CLK_delayed;
    wire awake;
    wire cond0;
    wire cond1;
    wire cond2;
    wire cond3;
    wire cond4;

    // Inverters
    not (RESET, RESET_B_delayed);

    // Multiplexer
    mux2_1 mux0 (mux_out, D_delayed, SCD_delayed, SCE_delayed);

    // D Flip-Flop
    dff dff0 (buf_Q, mux_out, CLK_delayed, RESET, notifier);

    // Power & Ground
    assign awake = (VPWR === 1'b1);

    // Combinational Logic
    assign cond0 = ((RESET_B_delayed === 1'b1) && awake);
    assign cond1 = ((SCE_delayed === 1'b0) && cond0);
    assign cond2 = ((SCE_delayed === 1'b1) && cond0);
    assign cond3 = ((D_delayed !== SCD_delayed) && cond0);
    assign cond4 = ((RESET_B === 1'b1) && awake);

    // Output buffer
    buf buf0 (Q, buf_Q);

    // Delayed signals
    buf dlclkbuf0 (D_delayed, D, CLK, RESET_B);
    buf dlclkbuf1 (SCD_delayed, SCD, CLK, RESET_B);
    buf dlclkbuf2 (SCE_delayed, SCE, CLK, RESET_B);
    buf dlclkbuf3 (RESET_B_delayed, RESET_B, CLK, RESET_B);
    buf dlclkbuf4 (CLK_delayed, CLK, CLK, RESET_B);

    // Notifier
    always @(posedge CLK) begin
        if (cond1 || cond2 || cond3 || cond4) begin
            notifier <= 1'b1;
        end else begin
            notifier <= 1'b0;
        end
    end

endmodule

module mux2_1 (out, in0, in1, sel);
    parameter WIDTH=1;

    input [WIDTH-1:0] in0, in1;
    input sel;

    output [WIDTH-1:0] out;

    assign out = (sel) ? in1 : in0;
endmodule

module dff (Q, D, CLK, RST, notifier);

    parameter WIDTH=1;

    input [WIDTH-1:0] D;
    input CLK, RST;
    input notifier;

    output [WIDTH-1:0] Q;

    reg [WIDTH-1:0] Q_reg;
    wire RSTB;

    not RST_inv(RSTB, RST);

    always @(posedge CLK or negedge RSTB) begin
        if (~RSTB)
            Q_reg <= {WIDTH{1'b0}};
        else if (notifier)
            Q_reg <= D;
    end

    assign Q = Q_reg;

endmodule

sva:
module my_module_sva (
    input logic Q,
    input logic CLK,
    input logic D,
    input logic SCD,
    input logic SCE,
    input logic RESET_B,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB
);
    ///// Environment assumptions (rails) /////
    // Constrain VPWR to be 0/1 (no X/Z) for formal convergence.
    env_vpwr_binary: assume property (
        @(posedge CLK) (VPWR === 1'b0) || (VPWR === 1'b1)
    );

    ///// Reset behavior /////
    // When RESET_B is LOW, Q must be 0 on the next clock.
    reset_low_forces_q0_next: assert property (
        @(posedge CLK) (RESET_B == 1'b0) |=> (Q == 1'b0)
    );
    // While RESET_B stays LOW across consecutive cycles, Q stays 0 and stable.
    reset_hold_q0_stable: assert property (
        @(posedge CLK) (RESET_B == 1'b0) && $past(RESET_B == 1'b0) |-> (Q == 1'b0) && $stable(Q)
    );
    // On a sampled falling edge of RESET_B, Q is 0 on the next clock.
    q_clears_on_reset_fall: assert property (
        @(posedge CLK) $fell(RESET_B) |=> (Q == 1'b0)
    );

    ///// Functional update rules (clocked, power good, reset deasserted) /////
    // After a cycle with power ON and reset deasserted, Q updates from either D or SCD.
    update_from_inputs_when_powered: assert property (
        @(posedge CLK) disable iff (RESET_B == 1'b0)
            $past((VPWR == 1'b1) && (RESET_B == 1'b1)) |-> ((Q == $past(D)) || (Q == $past(SCD)))
    );
    // When SCE was 0 last cycle under power ON and reset deasserted, Q follows D.
    follow_d_when_sce0: assert property (
        @(posedge CLK) disable iff (RESET_B == 1'b0)
            $past((VPWR == 1'b1) && (RESET_B == 1'b1) && (SCE == 1'b0)) |-> (Q == $past(D))
    );
    // When SCE was 1 last cycle under power ON and reset deasserted, Q follows SCD.
    follow_scd_when_sce1: assert property (
        @(posedge CLK) disable iff (RESET_B == 1'b0)
            $past((VPWR == 1'b1) && (RESET_B == 1'b1) && (SCE == 1'b1)) |-> (Q == $past(SCD))
    );
    // If D and SCD were equal last cycle in functional mode, Q equals that common value.
    follow_common_when_inputs_equal: assert property (
        @(posedge CLK) disable iff (RESET_B == 1'b0)
            $past((VPWR == 1'b1) && (RESET_B == 1'b1) && (D == SCD)) |-> (Q == $past(D))
    );
    // If inputs and select are stable over two functional cycles, Q is stable.
    stable_when_inputs_and_sel_stable: assert property (
        @(posedge CLK) disable iff (RESET_B == 1'b0)
            $past((VPWR == 1'b1) && (RESET_B == 1'b1)) &&
            (VPWR == 1'b1) && (RESET_B == 1'b1) &&
            $stable(D) && $stable(SCD) && $stable(SCE) |-> $stable(Q)
    );
endmodule

rtl:
module fsm (input in, output out, input clk);

    parameter s0 = 3'b000, s1 = 3'b001, s2 = 3'b010, s3 = 3'b011, s4 = 3'b100, s5 = 3'b101;
    reg [2:0] currentState, nextState;

    always @ (posedge clk) begin
        currentState <= nextState;
    end

    always @ (currentState, in) begin
        case (currentState)
            s0: if (in == 1'b0) nextState = s1; else nextState = s5;
            s1: if (in == 1'b0) nextState = s2; else nextState = s5;
            s2: if (in == 1'b0) nextState = s3; else nextState = s5;
            s3: if (in == 1'b0) nextState = s4; else nextState = s5;
            s4: if (in == 1'b0) nextState = s5; else nextState = s5;
            s5: nextState = s5;
        endcase
    end

    assign out = (currentState == s5);

endmodule

sva:
module fsm_sva (
    input logic clk,
    input logic in,
    input logic out,
    input logic [2:0] currentState,
    input logic [2:0] nextState
);
    // State encodings (match RTL)
    localparam logic [2:0] s0 = 3'b000;
    localparam logic [2:0] s1 = 3'b001;
    localparam logic [2:0] s2 = 3'b010;
    localparam logic [2:0] s3 = 3'b011;
    localparam logic [2:0] s4 = 3'b100;
    localparam logic [2:0] s5 = 3'b101;

    // currentState captures previous-cycle nextState on each rising clock edge.
    check_state_register_updates_from_next: assert property (
        @(posedge clk) !$isunknown($past(nextState)) |-> (currentState == $past(nextState))
    );

    // From s0 with in==0, nextState is s1.
    check_s0_in0_go_s1: assert property (
        @(posedge clk) (currentState == s0 && in == 1'b0) |-> (nextState == s1)
    );

    // From s1 with in==0, nextState is s2.
    check_s1_in0_go_s2: assert property (
        @(posedge clk) (currentState == s1 && in == 1'b0) |-> (nextState == s2)
    );

    // From s2 with in==0, nextState is s3.
    check_s2_in0_go_s3: assert property (
        @(posedge clk) (currentState == s2 && in == 1'b0) |-> (nextState == s3)
    );

    // From s3 with in==0, nextState is s4.
    check_s3_in0_go_s4: assert property (
        @(posedge clk) (currentState == s3 && in == 1'b0) |-> (nextState == s4)
    );

    // From s4 with in==0, nextState is s5.
    check_s4_in0_go_s5: assert property (
        @(posedge clk) (currentState == s4 && in == 1'b0) |-> (nextState == s5)
    );

    // With in==1 and a defined state, nextState is s5.
    check_in1_forces_s5_from_any: assert property (
        @(posedge clk) (in == 1'b1 && (currentState inside {s0,s1,s2,s3,s4,s5})) |-> (nextState == s5)
    );

    // State s5 is absorbing regardless of input.
    check_s5_absorbing: assert property (
        @(posedge clk) (currentState == s5) |-> (nextState == s5)
    );

    // out reflects whether currentState is s5.
    check_out_matches_state: assert property (
        @(posedge clk) out == (currentState == s5)
    );

    // Once out is HIGH, it remains HIGH (since s5 is absorbing).
    check_out_sticky_when_high: assert property (
        @(posedge clk) out |-> ##1 out
    );

endmodule

rtl:
module speaker (
    // Clocks
    input clk,
    input rst,

    // Wishbone slave interface
    input      [7:0] wb_dat_i,
    output reg [7:0] wb_dat_o,
    input            wb_we_i,
    input            wb_stb_i,
    input            wb_cyc_i,
    output           wb_ack_o,

    // Timer clock
    input timer2,

    // Speaker pad signal
    output speaker_
  );

  // Net declarations
  wire        write;
  wire        spk;

  // Combinatorial logic
  // System speaker
  assign speaker_ = timer2 & wb_dat_o[1];

  // Wishbone signals
  assign wb_ack_o = wb_stb_i && wb_cyc_i;
  assign write    = wb_stb_i && wb_cyc_i && wb_we_i;

  // Sequential logic
  always @(posedge clk)
    wb_dat_o <= rst ? 8'h0 : (write ? wb_dat_i : wb_dat_o);

endmodule

sva:
module speaker_sva (
    input logic clk,
    input logic rst,
    input logic [7:0] wb_dat_i,
    input logic [7:0] wb_dat_o,
    input logic wb_we_i,
    input logic wb_stb_i,
    input logic wb_cyc_i,
    input logic wb_ack_o,
    input logic timer2,
    input logic speaker_
);
    // wb_ack_o equals wb_stb_i AND wb_cyc_i each cycle.
    check_wb_ack_definition: assert property (
        @(posedge clk) disable iff (rst) wb_ack_o == (wb_stb_i && wb_cyc_i)
    );

    // If wb_stb_i and wb_cyc_i are stable, wb_ack_o is stable.
    check_wb_ack_stability_if_inputs_stable: assert property (
        @(posedge clk) disable iff (rst) ($stable(wb_stb_i) && $stable(wb_cyc_i)) |-> $stable(wb_ack_o)
    );

    // A write request implies wb_ack_o is HIGH in the same cycle.
    check_write_implies_ack: assert property (
        @(posedge clk) disable iff (rst) (wb_stb_i && wb_cyc_i && wb_we_i) |-> (wb_ack_o == 1'b1)
    );

    // speaker_ equals timer2 AND wb_dat_o[1] each cycle.
    check_speaker_definition: assert property (
        @(posedge clk) disable iff (rst) speaker_ == (timer2 & wb_dat_o[1])
    );

    // If timer2 and wb_dat_o[1] are stable, speaker_ is stable.
    check_speaker_stability_if_inputs_stable: assert property (
        @(posedge clk) disable iff (rst) ($stable(timer2) && $stable(wb_dat_o[1])) |-> $stable(speaker_)
    );

    // Reset drives wb_dat_o to 0x00 on the next cycle (synchronous reset).
    check_reset_clears_data_next: assert property (
        @(posedge clk) rst |=> (wb_dat_o == 8'h00)
    );

    // When not in reset, a write updates wb_dat_o with wb_dat_i on the next cycle.
    check_write_updates_data_next: assert property (
        @(posedge clk) disable iff (rst) (wb_stb_i && wb_cyc_i && wb_we_i) |=> (wb_dat_o == $past(wb_dat_i))
    );

    // When not in reset and no write, wb_dat_o holds its value on the next cycle.
    check_hold_without_write: assert property (
        @(posedge clk) disable iff (rst) !(wb_stb_i && wb_cyc_i && wb_we_i) |=> (wb_dat_o == $past(wb_dat_o))
    );

    // wb_dat_o can change only due to reset or a write in the previous cycle.
    check_data_changes_only_on_write_or_reset: assert property (
        @(posedge clk) disable iff (rst) $changed(wb_dat_o) |-> ($past(rst) || $past(wb_stb_i && wb_cyc_i && wb_we_i))
    );

    // While reset is held across cycles, wb_dat_o remains 0x00.
    check_data_zero_when_reset_held: assert property (
        @(posedge clk) (rst && $past(rst)) |-> (wb_dat_o == 8'h00)
    );
endmodule

rtl:
module add_sub_shift (
    input [15:0] in0,
    input [15:0] in1,
    input ctrl,
    input signed [3:0] SHIFT,
    input RESET,
    input clk, // Added missing clock input
    output reg [15:0] q
);

    wire [15:0] add_sub_out;
    wire [15:0] shift_out;

    add_sub_16bit add_sub_inst (
        .in0(in0),
        .in1(in1),
        .ctrl(ctrl),
        .out(add_sub_out)
    );

    barrel_shifter_4bit shift_inst (
        .in(add_sub_out),
        .shift(SHIFT),
        .out(shift_out)
    );

    always @(posedge clk or posedge RESET) begin // Changed sensitivity list to include clk and RESET
        if (RESET) begin
            q <= 0;
        end else begin
            q <= shift_out;
        end
    end

endmodule

module add_sub_16bit (
    input [15:0] in0,
    input [15:0] in1,
    input ctrl,
    output reg [15:0] out
);

    always @(*) begin
        if (ctrl) begin
            out = in0 + in1;
        end else begin
            out = in0 - in1;
        end
    end

endmodule

module barrel_shifter_4bit (
    input [15:0] in,
    input signed [3:0] shift,
    output reg [15:0] out
);

    always @(*) begin
        out = in << shift;
    end

endmodule

sva:
module add_sub_shift_sva (
    input logic [15:0] in0,
    input logic [15:0] in1,
    input logic ctrl,
    input logic signed [3:0] SHIFT,
    input logic RESET,
    input logic clk,
    input logic [15:0] q
);
    ///// Reset behavior /////
    // While RESET is high, q must be 0 on each clock.
    check_reset_forces_zero: assert property (
        @(posedge clk) RESET |-> (q == 16'h0000)
    );
    // On a rising edge of RESET, q must be 0 at that clock.
    check_reset_rise_clears_q: assert property (
        @(posedge clk) $rose(RESET) |-> (q == 16'h0000)
    );

    ///// Core functionality /////
    // When not in reset and ctrl=1, q equals (in0+in1) left-shifted by SHIFT at the same clock.
    check_add_path_q_correct: assert property (
        @(posedge clk) disable iff (RESET) (ctrl) |-> (q == ((in0 + in1) << SHIFT))
    );
    // When not in reset and ctrl=0, q equals (in0-in1) left-shifted by SHIFT at the same clock.
    check_sub_path_q_correct: assert property (
        @(posedge clk) disable iff (RESET) (!ctrl) |-> (q == ((in0 - in1) << SHIFT))
    );

    ///// Useful corollaries from the RTL math /////
    // If SHIFT==0, q equals add/sub result without shift.
    check_no_shift_when_SHIFT_zero: assert property (
        @(posedge clk) disable iff (RESET) (SHIFT == '0) |-> (q == (ctrl ? (in0 + in1) : (in0 - in1)))
    );
    // If ctrl=1 and in1==0, q equals in0 left-shifted by SHIFT.
    check_add_with_zero_rhs_equals_in0_shifted: assert property (
        @(posedge clk) disable iff (RESET) (ctrl && (in1 == 16'h0000)) |-> (q == (in0 << SHIFT))
    );
    // If ctrl=0 and in1==0, q equals in0 left-shifted by SHIFT.
    check_sub_with_zero_rhs_equals_in0_shifted: assert property (
        @(posedge clk) disable iff (RESET) (!ctrl && (in1 == 16'h0000)) |-> (q == (in0 << SHIFT))
    );
    // If ctrl=0 and in0==in1, q must be 0 (0 shifted remains 0).
    check_sub_equal_operands_zero: assert property (
        @(posedge clk) disable iff (RESET) (!ctrl && (in0 == in1)) |-> (q == 16'h0000)
    );

    ///// Stability /////
    // If inputs (in0,in1,ctrl,SHIFT) are stable across cycles and not in reset, q remains stable.
    check_stability_when_inputs_stable: assert property (
        @(posedge clk) disable iff (RESET)
            ($past(1'b1) && !$past(RESET) && $stable(in0) && $stable(in1) && $stable(ctrl) && $stable(SHIFT))
            |-> (q == $past(q))
    );
endmodule

module mux_2to1_priority_sva (
    // External sampling clock (RTL has no clock/reset)
    input logic clk,
    // DUT ports
    input logic [3:0] A,
    input logic [3:0] B,
    input logic       P,
    input logic [3:0] Y
);
    // Y must equal the selected input each cycle.
    check_mux_function: assert property (
        @(posedge clk) Y == (P ? A : B)
    );

    // When P is 1, Y must equal A.
    check_select_A_when_P_high: assert property (
        @(posedge clk) P |-> (Y == A)
    );

    // When P is 0, Y must equal B.
    check_select_B_when_P_low: assert property (
        @(posedge clk) !P |-> (Y == B)
    );

    // If A, B, and P are all stable, Y must be stable.
    check_stable_when_all_inputs_stable: assert property (
        @(posedge clk) ($stable(A) && $stable(B) && $stable(P)) |-> $stable(Y)
    );

    // With P held high and A stable, changes on B must not affect Y.
    check_unselected_B_ignored_when_P_high: assert property (
        @(posedge clk) (P && $stable(P) && $stable(A) && !$stable(B)) |-> $stable(Y)
    );

    // With P held low and B stable, changes on A must not affect Y.
    check_unselected_A_ignored_when_P_low: assert property (
        @(posedge clk) (!P && $stable(P) && $stable(B) && !$stable(A)) |-> $stable(Y)
    );

    // With P held high, a change on A must cause a change on Y.
    check_y_follows_A_when_P_high: assert property (
        @(posedge clk) (P && $stable(P) && !$stable(A)) |-> !$stable(Y)
    );

    // With P held low, a change on B must cause a change on Y.
    check_y_follows_B_when_P_low: assert property (
        @(posedge clk) (!P && $stable(P) && !$stable(B)) |-> !$stable(Y)
    );

    // On rising P, Y must now equal A and previously have equaled B.
    check_behavior_on_P_rise: assert property (
        @(posedge clk) $rose(P) |-> (Y == A) && ($past(Y) == $past(B))
    );

    // On falling P, Y must now equal B and previously have equaled A.
    check_behavior_on_P_fall: assert property (
        @(posedge clk) $fell(P) |-> (Y == B) && ($past(Y) == $past(A))
    );
endmodule

