module num_2_sva (
    input logic CLK,
    input logic [2:0] in_row,
    input logic [4:0] out_code
);
    // Row 000 maps to 01110.
    map_row_000: assert property (
        @(posedge CLK) disable iff (1'b0) (in_row == 3'b000) |-> (out_code == 5'b01110)
    );

    // Row 001 maps to 10001.
    map_row_001: assert property (
        @(posedge CLK) disable iff (1'b0) (in_row == 3'b001) |-> (out_code == 5'b10001)
    );

    // Row 010 maps to 01000.
    map_row_010: assert property (
        @(posedge CLK) disable iff (1'b0) (in_row == 3'b010) |-> (out_code == 5'b01000)
    );

    // Row 011 maps to 00100.
    map_row_011: assert property (
        @(posedge CLK) disable iff (1'b0) (in_row == 3'b011) |-> (out_code == 5'b00100)
    );

    // Row 100 maps to 00010.
    map_row_100: assert property (
        @(posedge CLK) disable iff (1'b0) (in_row == 3'b100) |-> (out_code == 5'b00010)
    );

    // Row 101 maps to 11111.
    map_row_101: assert property (
        @(posedge CLK) disable iff (1'b0) (in_row == 3'b101) |-> (out_code == 5'b11111)
    );

    // Row 110 maps to 00000 (default).
    map_default_row_110: assert property (
        @(posedge CLK) disable iff (1'b0) (in_row == 3'b110) |-> (out_code == 5'b00000)
    );

    // Row 111 maps to 00000 (default).
    map_default_row_111: assert property (
        @(posedge CLK) disable iff (1'b0) (in_row == 3'b111) |-> (out_code == 5'b00000)
    );

    // out_code is always one of the defined patterns.
    out_code_value_legal_set: assert property (
        @(posedge CLK) disable iff (1'b0) out_code inside {5'b01110,5'b10001,5'b01000,5'b00100,5'b00010,5'b11111,5'b00000}
    );

    // For mapped rows 000..101, out_code is never 00000.
    nonzero_when_row_mapped: assert property (
        @(posedge CLK) disable iff (1'b0) (in_row inside {3'b000,3'b001,3'b010,3'b011,3'b100,3'b101}) |-> (out_code != 5'b00000)
    );
endmodule

rtl:
module Comparator (
  input [n-1:0] a,
  input [n-1:0] b,
  input [1:0] ctrl,
  output reg out
);

parameter n = 8; // number of bits in input numbers

reg signed [n-1:0] a_signed, b_signed;

// Sign extension for signed numbers
always @(*) begin
  if (ctrl == 2'b01) begin // a > b
    if (a[n-1] == 1) // a is negative
      a_signed = {{n-1{1'b1}}, a};
    else
      a_signed = {n-1'b0, a};

    if (b[n-1] == 1) // b is negative
      b_signed = {{n-1{1'b1}}, b};
    else
      b_signed = {n-1'b0, b};
  end
  else if (ctrl == 2'b10) begin // a < b
    if (a[n-1] == 1) // a is negative
      a_signed = {{n-1{1'b1}}, a};
    else
      a_signed = {n-1'b0, a};

    if (b[n-1] == 1) // b is negative
      b_signed = {{n-1{1'b1}}, b};
    else
      b_signed = {n-1'b0, b};
  end
end

// Comparison logic
always @(*) begin
  case (ctrl)
    2'b00: out = (a == b);
    2'b01: out = (a_signed > b_signed);
    2'b10: out = (a_signed < b_signed);
    default: out = 1'b0;
  endcase
end

endmodule

sva:
module Comparator_sva #(
    parameter int n = 8
) (
    input  logic                  CLK,
    input  logic [n-1:0]          a,
    input  logic [n-1:0]          b,
    input  logic [1:0]            ctrl,
    input  logic                  out,
    input  logic signed [n-1:0]   a_signed,
    input  logic signed [n-1:0]   b_signed
);
    // Equality mode: out reflects (a == b).
    check_eq_mode_out: assert property (
        @(posedge CLK) (ctrl == 2'b00) |-> (out == (a == b))
    );

    // Greater-than mode: out reflects (a_signed > b_signed).
    check_gt_mode_out: assert property (
        @(posedge CLK) (ctrl == 2'b01) |-> (out == (a_signed > b_signed))
    );

    // Less-than mode: out reflects (a_signed < b_signed).
    check_lt_mode_out: assert property (
        @(posedge CLK) (ctrl == 2'b10) |-> (out == (a_signed < b_signed))
    );

    // Default/other mode (2'b11): out is 0.
    check_default_zero: assert property (
        @(posedge CLK) (ctrl == 2'b11) |-> (out == 1'b0)
    );

    // When comparing (01/10), a_signed equals a due to truncation of concatenation.
    check_compare_mode_a_assigned: assert property (
        @(posedge CLK) (ctrl inside {2'b01,2'b10}) |-> (a_signed == a)
    );

    // When comparing (01/10), b_signed equals b due to truncation of concatenation.
    check_compare_mode_b_assigned: assert property (
        @(posedge CLK) (ctrl inside {2'b01,2'b10}) |-> (b_signed == b)
    );

    // When not comparing (00/11) and ctrl stable, a_signed holds its value (latch behavior).
    check_hold_a_when_not_compare: assert property (
        @(posedge CLK) (ctrl inside {2'b00,2'b11} && $stable(ctrl)) |-> $stable(a_signed)
    );

    // When not comparing (00/11) and ctrl stable, b_signed holds its value (latch behavior).
    check_hold_b_when_not_compare: assert property (
        @(posedge CLK) (ctrl inside {2'b00,2'b11} && $stable(ctrl)) |-> $stable(b_signed)
    );

    // When comparing and inputs/ctrl stable, a_signed remains stable.
    check_compare_stable_a: assert property (
        @(posedge CLK) (ctrl inside {2'b01,2'b10} && $stable(ctrl) && $stable(a)) |-> $stable(a_signed)
    );

    // When comparing and inputs/ctrl stable, b_signed remains stable.
    check_compare_stable_b: assert property (
        @(posedge CLK) (ctrl inside {2'b01,2'b10} && $stable(ctrl) && $stable(b)) |-> $stable(b_signed)
    );
endmodule

rtl:
module top_module (
    input clk,
    input reset,       // Asynchronous reset
    input slowena,     // Enable input for decade counter
    input [2:0] select,// Select input to choose between 3-to-4 wire connection and decade counter
    input [3:0] a,b,c,       // Inputs for 3-to-4 wire connection
    output [3:0] q     // Final 4-bit output from functional module
);

    // 3-to-4 wire connection module
    wire [3:0] w;
    assign w = (select == 3'b000) ? a : (select == 3'b001) ? b : (select == 3'b010) ? c : 4'b0000;

    // Decade counter module
    reg [3:0] counter;
    always @(posedge clk or negedge reset) begin
        if (!reset) begin
            counter <= 0;
        end else if (slowena) begin
            counter <= counter + 1;
        end
    end

    // Functional module
    assign q = (select == 3'b011) ? counter : w;

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic reset,
    input logic slowena,
    input logic [2:0] select,
    input logic [3:0] a,
    input logic [3:0] b,
    input logic [3:0] c,
    input logic [3:0] q,
    // Internal signals from RTL
    input logic [3:0] counter,
    input logic [3:0] w
);

    ///// Counter behavior /////
    // While reset is asserted (active-low), counter is 0.
    reset_forces_counter_zero: assert property (
        @(posedge clk) !reset |-> (counter == 4'd0)
    );

    // When enabled, counter increments by 1 on the next cycle.
    counter_increments_when_enabled: assert property (
        @(posedge clk) disable iff (!reset) slowena |=> (counter == $past(counter) + 4'd1)
    );

    // When not enabled, counter holds its value.
    counter_holds_when_disabled: assert property (
        @(posedge clk) disable iff (!reset) !slowena |=> (counter == $past(counter))
    );

    ///// Output selection /////
    // When select is 3'b011, q equals counter.
    q_selects_counter_on_011: assert property (
        @(posedge clk) disable iff (!reset) (select == 3'b011) |-> (q == counter)
    );

    // When select is not 3'b011, q equals w.
    q_equals_w_when_not_011: assert property (
        @(posedge clk) disable iff (!reset) (select != 3'b011) |-> (q == w)
    );

    ///// w mux behavior /////
    // When select is 3'b000, w equals a.
    w_selects_a_on_000: assert property (
        @(posedge clk) disable iff (!reset) (select == 3'b000) |-> (w == a)
    );

    // When select is 3'b001, w equals b.
    w_selects_b_on_001: assert property (
        @(posedge clk) disable iff (!reset) (select == 3'b001) |-> (w == b)
    );

    // When select is 3'b010, w equals c.
    w_selects_c_on_010: assert property (
        @(posedge clk) disable iff (!reset) (select == 3'b010) |-> (w == c)
    );

    // For all other select values, w is 0.
    w_zero_on_other_selects: assert property (
        @(posedge clk) disable iff (!reset) ((select != 3'b000) && (select != 3'b001) && (select != 3'b010)) |-> (w == 4'd0)
    );

endmodule

