module mux_2to1_enable (
  input A,
  input B,
  input E,
  output Y
);

  assign Y = E ? A : B;

endmodule

sva:
module mux_2to1_enable_sva (
    input logic CLK,
    input logic A,
    input logic B,
    input logic E,
    input logic Y
);

    // Y implements a 2:1 mux: Y == (E ? A : B).
    check_mux_function: assert property (
        @(posedge CLK) Y == (E ? A : B)
    );

    // When E=1, Y must equal A.
    check_select_a_when_e1: assert property (
        @(posedge CLK) (E == 1'b1) |-> (Y == A)
    );

    // When E=0, Y must equal B.
    check_select_b_when_e0: assert property (
        @(posedge CLK) (E == 1'b0) |-> (Y == B)
    );

    // With E=0 and only A changing, Y must remain stable.
    check_a_ignored_when_e0: assert property (
        @(posedge CLK) (E == 1'b0 && $stable(E) && $stable(B) && $changed(A)) |-> $stable(Y)
    );

    // With E=1 and only B changing, Y must remain stable.
    check_b_ignored_when_e1: assert property (
        @(posedge CLK) (E == 1'b1 && $stable(E) && $stable(A) && $changed(B)) |-> $stable(Y)
    );

    // If A and B are equal, Y must equal that value regardless of E.
    check_equal_inputs_passthrough: assert property (
        @(posedge CLK) (A == B) |-> (Y == A)
    );

    // If A and B are stable and equal while E toggles, Y must remain stable.
    check_e_toggle_no_effect_when_a_eq_b: assert property (
        @(posedge CLK) ($stable(A) && $stable(B) && (A == B) && $changed(E)) |-> $stable(Y)
    );

endmodule

rtl:
module multifsm(clk, rst, proddone, start, done, ld, shift);

  input clk;
  input rst; 
  input start;
  input proddone;
  output  done;
  output   ld;
  output shift;

  parameter [1:0] IDLE=2'b00, MUL=2'b01 , DONE= 2'b10;
  reg [1:0] state , newstate;

  always @* begin
    newstate = IDLE;
    case (state)
        IDLE: if (start) newstate= MUL; else newstate= IDLE;
        MUL: if (start & proddone) newstate = DONE; else if (start) newstate = MUL; else newstate = IDLE;
        DONE: if(start) newstate= DONE ; else newstate= IDLE;
    endcase

    end

  always @( posedge clk or posedge rst)
         if (rst)
              state <= IDLE;
         else state <= newstate;

  assign done  = (state == DONE);
  assign ld    = (state == IDLE);
  assign shift = (state== MUL) && !proddone;


endmodule

sva:
module multifsm_sva (
    input logic clk,
    input logic rst,
    input logic proddone,
    input logic start,
    input logic done,
    input logic ld,
    input logic shift,
    input logic [1:0] state,
    input logic [1:0] newstate
);
    // State encodings mirrored from RTL
    localparam logic [1:0] IDLE = 2'b00;
    localparam logic [1:0] MUL  = 2'b01;
    localparam logic [1:0] DONE = 2'b10;

    ///// Reset behavior /////
    // When reset is asserted, state must be IDLE.
    reset_state_idle: assert property (
        @(posedge clk) rst |-> (state == IDLE)
    );
    // When reset is asserted, outputs reflect IDLE (ld=1, done=0, shift=0).
    reset_outputs_idle: assert property (
        @(posedge clk) rst |-> (ld == 1'b1) && (done == 1'b0) && (shift == 1'b0)
    );

    ///// Sequential update /////
    // When not in reset, state updates from previous cycle's newstate.
    check_state_uses_newstate: assert property (
        @(posedge clk) disable iff (rst) state == $past(newstate)
    );

    ///// Next-state combinational logic /////
    // newstate calculation when in IDLE.
    nextstate_calc_idle: assert property (
        @(posedge clk) disable iff (rst) (state == IDLE) |-> (newstate == (start ? MUL : IDLE))
    );
    // newstate calculation when in MUL.
    nextstate_calc_mul: assert property (
        @(posedge clk) disable iff (rst) (state == MUL) |-> (newstate == ((start && proddone) ? DONE : (start ? MUL : IDLE)))
    );
    // newstate calculation when in DONE.
    nextstate_calc_done: assert property (
        @(posedge clk) disable iff (rst) (state == DONE) |-> (newstate == (start ? DONE : IDLE))
    );

    ///// Output decode /////
    // done is high iff state == DONE.
    check_done_decode: assert property (
        @(posedge clk) disable iff (rst) (done == (state == DONE))
    );
    // ld is high iff state == IDLE.
    check_ld_decode: assert property (
        @(posedge clk) disable iff (rst) (ld == (state == IDLE))
    );
    // shift is high iff state == MUL and proddone == 0.
    check_shift_decode: assert property (
        @(posedge clk) disable iff (rst) (shift == ((state == MUL) && !proddone))
    );
    // Shift equals (!done && !ld && !proddone).
    check_shift_vs_outputs: assert property (
        @(posedge clk) disable iff (rst) (shift == (!done && !ld && !proddone))
    );
    // ld and done are mutually exclusive.
    check_ld_done_mutex: assert property (
        @(posedge clk) disable iff (rst) !(ld && done)
    );

    ///// Temporal behavior from outputs /////
    // In DONE, next-cycle done equals current start.
    done_next_depends_on_start: assert property (
        @(posedge clk) disable iff (rst) done |-> ##1 (done == start)
    );
    // If ld and start==0, remain in IDLE next cycle (ld stays high).
    ld_holds_when_start_low: assert property (
        @(posedge clk) disable iff (rst) (ld && !start) |-> ##1 ld
    );
    // If ld and start==1, leave IDLE next cycle (ld goes low).
    ld_clears_when_start_high: assert property (
        @(posedge clk) disable iff (rst) (ld && start) |-> ##1 !ld
    );
    // From MUL with start && proddone, go to DONE next cycle.
    mul_to_done_on_start_and_proddone: assert property (
        @(posedge clk) disable iff (rst) (!ld && !done && start && proddone) |-> ##1 done
    );
    // From MUL with start && !proddone, stay in MUL next cycle.
    mul_stay_when_start_and_not_proddone: assert property (
        @(posedge clk) disable iff (rst) (!ld && !done && start && !proddone) |-> ##1 (!ld && !done)
    );
    // From MUL with !start, go to IDLE next cycle.
    mul_to_idle_when_start_low: assert property (
        @(posedge clk) disable iff (rst) (!ld && !done && !start) |-> ##1 ld
    );
    // A rising edge of done occurs only from MUL with start && proddone in the previous cycle.
    done_rise_from_mul_start_proddone: assert property (
        @(posedge clk) disable iff (rst) $rose(done) |-> ($past(!ld && !done) && $past(start) && $past(proddone))
    );
    // A falling edge of ld occurs only if start was high in the previous cycle.
    ld_fall_requires_start_high: assert property (
        @(posedge clk) disable iff (rst) $fell(ld) |-> $past(start)
    );
    // A rising edge of ld occurs only if start was low in the previous cycle.
    ld_rise_requires_start_low: assert property (
        @(posedge clk) disable iff (rst) $rose(ld) |-> !$past(start)
    );
    // A falling edge of done occurs only if start was low in the previous cycle.
    done_fall_requires_start_low: assert property (
        @(posedge clk) disable iff (rst) $fell(done) |-> !$past(start)
    );
endmodule

rtl:
module four_bit_adder (
	input [3:0] A,
	input [3:0] B,
	input Cin,
	output [3:0] S,
	output Cout
);

	wire [3:0] X;
	wire [3:0] Y;
	wire C1, C2, C3;

	// Define NAND gate using primitive gates
	assign X[0] = ~(A[0] & B[0]);
	assign Y[0] = ~(X[0] & Cin);
	assign C1 = ~(B[0] & Cin);

	assign X[1] = ~(A[1] & B[1]);
	assign Y[1] = ~(X[1] & C1);
	assign C2 = ~(B[1] & C1);

	assign X[2] = ~(A[2] & B[2]);
	assign Y[2] = ~(X[2] & C2);
	assign C3 = ~(B[2] & C2);

	assign X[3] = ~(A[3] & B[3]);
	assign S[3] = ~(X[3] & C3);
	assign Cout = ~(B[3] & C3);

	assign S[2] = Y[2];
	assign S[1] = Y[1];
	assign S[0] = Y[0];
endmodule

sva:
module four_bit_adder_sva (
    input logic CLK,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic Cin,
    input logic [3:0] S,
    input logic Cout
);
    // No clock/reset in DUT; purely combinational NAND network. Assertions sample at posedge CLK; no reset gating.

    ///// Functional equivalence to RTL equations /////
    // S[0] equals ~(~(A0 & B0) & Cin).
    check_s0_matches_logic: assert property (
        @(posedge CLK) disable iff (1'b0)
        S[0] === ~( (~(A[0] & B[0])) & Cin )
    );

    // S[1] equals ~(~(A1 & B1) & ~(B0 & Cin)).
    check_s1_matches_logic: assert property (
        @(posedge CLK) disable iff (1'b0)
        S[1] === ~( (~(A[1] & B[1])) & ~(B[0] & Cin) )
    );

    // S[2] equals ~(~(A2 & B2) & ~(B1 & ~(B0 & Cin))).
    check_s2_matches_logic: assert property (
        @(posedge CLK) disable iff (1'b0)
        S[2] === ~( (~(A[2] & B[2])) & ~(B[1] & ~(B[0] & Cin)) )
    );

    // S[3] equals ~(~(A3 & B3) & ~(B2 & ~(B1 & ~(B0 & Cin)))).
    check_s3_matches_logic: assert property (
        @(posedge CLK) disable iff (1'b0)
        S[3] === ~( (~(A[3] & B[3])) & ~(B[2] & ~(B[1] & ~(B[0] & Cin))) )
    );

    // Cout equals ~(B3 & ~(B2 & ~(B1 & ~(B0 & Cin)))).
    check_cout_matches_logic: assert property (
        @(posedge CLK) disable iff (1'b0)
        Cout === ~( B[3] & ~(B[2] & ~(B[1] & ~(B[0] & Cin))) )
    );

    ///// Combinational stability /////
    // If inputs are stable, outputs must be stable.
    check_outputs_stable_when_inputs_stable: assert property (
        @(posedge CLK) disable iff (1'b0)
        ($stable(A) && $stable(B) && $stable(Cin)) |-> ($stable(S) && $stable(Cout))
    );

    // Outputs can change only if at least one input changed.
    check_outputs_change_requires_input_change: assert property (
        @(posedge CLK) disable iff (1'b0)
        ($changed(S) || $changed(Cout)) |-> ($changed(A) || $changed(B) || $changed(Cin))
    );

    ///// Independence from irrelevant inputs /////
    // S[0] is independent of A[3:1] and B[3:1] when A[0],B[0],Cin are stable.
    check_s0_independent_of_upper_inputs: assert property (
        @(posedge CLK) disable iff (1'b0)
        ($stable(A[0]) && $stable(B[0]) && $stable(Cin) && $changed({A[3:1],B[3:1]})) |-> $stable(S[0])
    );

    // S[1] is independent of A[3:2],A[0],B[3:2] when A[1],B[1],B[0],Cin are stable.
    check_s1_independent_of_irrelevant_inputs: assert property (
        @(posedge CLK) disable iff (1'b0)
        ($stable(A[1]) && $stable(B[1]) && $stable(B[0]) && $stable(Cin) && $changed({A[3:2],A[0],B[3:2]})) |-> $stable(S[1])
    );

    // S[2] is independent of A[3],A[1:0],B[3] when A[2],B[2],B[1],B[0],Cin are stable.
    check_s2_independent_of_irrelevant_inputs: assert property (
        @(posedge CLK) disable iff (1'b0)
        ($stable(A[2]) && $stable(B[2]) && $stable(B[1]) && $stable(B[0]) && $stable(Cin) && $changed({A[3],A[1:0],B[3]})) |-> $stable(S[2])
    );

    // S[3] is independent of A[2:0] when A[3],B[3:0],Cin are stable.
    check_s3_independent_of_lower_A_bits: assert property (
        @(posedge CLK) disable iff (1'b0)
        ($stable(A[3]) && $stable(B) && $stable(Cin) && $changed(A[2:0])) |-> $stable(S[3])
    );

    // Cout is independent of A when B and Cin are stable.
    check_cout_independent_of_A: assert property (
        @(posedge CLK) disable iff (1'b0)
        ($stable(B) && $stable(Cin) && $changed(A)) |-> $stable(Cout)
    );

    ///// Simple corner case implied by the NAND structure /////
    // When B==0, S[3:1]==0, S[0]==~Cin, Cout==1.
    check_behavior_when_B_is_zero: assert property (
        @(posedge CLK) disable iff (1'b0)
        (B === 4'b0000) |-> ((S[3:1] === 3'b000) && (S[0] === ~Cin) && (Cout === 1'b1))
    );

endmodule

module binary_counter_sva (
    input logic clk,
    input logic reset,
    input logic enable,
    input logic [3:0] count
);

    // Reset high drives count to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |-> (count == 4'h0)
    );

    // With enable low, count holds its previous value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset) (!enable) |-> (count == $past(count))
    );

    // With enable high and below max, count increments by 1.
    check_increment_when_enabled_not_max: assert property (
        @(posedge clk) disable iff (reset) (enable && ($past(count) != 4'hF)) |-> (count == $past(count) + 1)
    );

    // With enable high at max, count wraps to zero.
    check_wrap_to_zero_when_enabled_at_max: assert property (
        @(posedge clk) disable iff (reset) (enable && ($past(count) == 4'hF)) |-> (count == 4'h0)
    );

    // Any change in count requires enable high.
    check_change_requires_enable: assert property (
        @(posedge clk) disable iff (reset) (count != $past(count)) |-> enable
    );

    // If count increments by 1, enable must be high.
    check_increment_implies_enable: assert property (
        @(posedge clk) disable iff (reset) (count == ($past(count) + 1)) |-> enable
    );

    // A decrease across cycles can only be wrap 15->0.
    check_decrease_only_on_wrap: assert property (
        @(posedge clk) disable iff (reset) (count < $past(count)) |-> (($past(count) == 4'hF) && (count == 4'h0))
    );

    // A 15->0 wrap requires enable high.
    check_wrap_transition_requires_enable: assert property (
        @(posedge clk) disable iff (reset) (($past(count) == 4'hF) && (count == 4'h0)) |-> enable
    );

    // With enable high and count is zero, previous must be 15 (not due to reset).
    check_zero_with_enable_prev_max: assert property (
        @(posedge clk) disable iff (reset) (enable && (count == 4'h0) && $past(1'b1)) |-> ($past(count) == 4'hF)
    );

    // With enable low and previous 15, count stays 15.
    check_max_holds_when_disabled: assert property (
        @(posedge clk) disable iff (reset) (($past(count) == 4'hF) && !enable) |-> (count == 4'hF)
    );

endmodule

rtl:
module four_bit_adder (
  input [3:0] A,
  input [3:0] B,
  input Cin,
  output [3:0] Sum,
  output Cout
);

  wire [3:0] sum_wire;
  wire carry_wire;

  assign {carry_wire, sum_wire} = A + B + Cin;
  assign Cout = carry_wire;
  assign Sum = sum_wire;

endmodule

sva:
module four_bit_adder_sva (
    input logic CLK,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic Cin,
    input logic [3:0] Sum,
    input logic Cout
);
    // DUT is combinational with no reset; assertions are sampled on CLK.

    // Sum/Cout equal the 5-bit addition of A, B, and Cin.
    check_sum_cout_matches_add: assert property (
        @(posedge CLK) {Cout, Sum} == ({1'b0, A} + {1'b0, B} + Cin)
    );

    // Sum is the low 4 bits of the full 5-bit addition.
    check_sum_low_nibble: assert property (
        @(posedge CLK) Sum == (({1'b0, A} + {1'b0, B} + Cin)[3:0])
    );

    // Cout is the MSB (bit 4) of the full 5-bit addition.
    check_cout_is_msb: assert property (
        @(posedge CLK) Cout == (({1'b0, A} + {1'b0, B} + Cin)[4])
    );

    // LSB of Sum equals XOR of operand LSBs and Cin.
    check_lsb_parity: assert property (
        @(posedge CLK) Sum[0] == (A[0] ^ B[0] ^ Cin)
    );

    // With Cin=0, result equals A+B with no increment.
    check_no_cin_behavior: assert property (
        @(posedge CLK) (Cin == 1'b0) |-> ({Cout, Sum} == ({1'b0, A} + {1'b0, B}))
    );

    // With Cin=1, result equals A+B plus one.
    check_with_cin_increment: assert property (
        @(posedge CLK) (Cin == 1'b1) |-> ({Cout, Sum} == ({1'b0, A} + {1'b0, B} + 5'd1))
    );

    // If A==0 and Cin==0, Sum mirrors B and Cout is 0.
    check_zero_A_no_cin: assert property (
        @(posedge CLK) ((A == 4'b0000) && (Cin == 1'b0)) |-> ((Sum == B) && (Cout == 1'b0))
    );

    // If B==0 and Cin==0, Sum mirrors A and Cout is 0.
    check_zero_B_no_cin: assert property (
        @(posedge CLK) ((B == 4'b0000) && (Cin == 1'b0)) |-> ((Sum == A) && (Cout == 1'b0))
    );

    // If A==0 and B==0, Sum equals Cin in bit0 and Cout is 0.
    check_only_cin_effect: assert property (
        @(posedge CLK) ((A == 4'b0000) && (B == 4'b0000)) |-> ((Sum == {3'b000, Cin}) && (Cout == 1'b0))
    );

    // Cout is 1 iff the full 5-bit sum exceeds 0xF.
    check_cout_overflow_flag: assert property (
        @(posedge CLK) Cout == (({1'b0, A} + {1'b0, B} + Cin) > 5'd15)
    );

endmodule

rtl:
module logic_module (
    Y,
    A1,
    A2,
    B1
);

    // Module ports
    output Y;
    input A1;
    input A2;
    input B1;

    // Local signals
    wire and0_out;
    wire nor0_out_Y;

    // Implement AND operation
    and and0 (and0_out, A1, A2);

    // Implement NOR operation
    nor nor0 (nor0_out_Y, B1, and0_out);

    // Implement buffer
    buf buf0 (Y, nor0_out_Y);

endmodule

sva:
module logic_module_sva (
    input logic clk,
    input logic Y,
    input logic A1,
    input logic A2,
    input logic B1
);

    // Y equals NOR of B1 and (A1 & A2).
    check_func_equation: assert property (
        @(posedge clk) Y == ~(B1 | (A1 & A2))
    );

    // If B1 is HIGH then Y must be LOW.
    check_y_low_when_b1_high: assert property (
        @(posedge clk) (B1 == 1'b1) |-> (Y == 1'b0)
    );

    // If A1 and A2 are both HIGH then Y must be LOW.
    check_y_low_when_a1a2_high: assert property (
        @(posedge clk) ((A1 == 1'b1) && (A2 == 1'b1)) |-> (Y == 1'b0)
    );

    // If B1 is LOW and A1 is LOW then Y must be HIGH (independent of A2).
    check_y_high_when_b1_low_a1_low: assert property (
        @(posedge clk) ((B1 == 1'b0) && (A1 == 1'b0)) |-> (Y == 1'b1)
    );

    // If B1 is LOW and A2 is LOW then Y must be HIGH (independent of A1).
    check_y_high_when_b1_low_a2_low: assert property (
        @(posedge clk) ((B1 == 1'b0) && (A2 == 1'b0)) |-> (Y == 1'b1)
    );

    // If A1 and A2 are both LOW then Y equals ~B1.
    check_y_equals_not_b1_when_a1a2_zero: assert property (
        @(posedge clk) ((A1 == 1'b0) && (A2 == 1'b0)) |-> (Y == ~B1)
    );

    // If Y is HIGH then B1 is LOW and not both A1 and A2 are HIGH.
    check_y_one_implies_conditions: assert property (
        @(posedge clk) (Y == 1'b1) |-> ((B1 == 1'b0) && !((A1 == 1'b1) && (A2 == 1'b1)))
    );

    // If B1 is LOW and Y is LOW then A1 and A2 must both be HIGH.
    check_y_zero_with_b1_zero_implies_a1a2: assert property (
        @(posedge clk) ((B1 == 1'b0) && (Y == 1'b0)) |-> ((A1 == 1'b1) && (A2 == 1'b1))
    );

    // Output is stable when inputs are stable across a cycle.
    check_output_stable_when_inputs_stable: assert property (
        @(posedge clk) $stable({A1, A2, B1}) |-> $stable(Y)
    );

    // De Morgan equivalent form of the function.
    check_demorgan_form: assert property (
        @(posedge clk) Y == ((~B1) & ((~A1) | (~A2)))
    );

endmodule

module binary_counter_sva (
    input logic clk,
    input logic reset,
    input logic enable,
    input logic [3:0] count
);
    ///// Counter behavior /////
    // Synchronous reset drives count to 0.
    check_reset_clears_to_zero: assert property (
        @(posedge clk) reset |-> (count == 4'd0)
    );

    // When enable was LOW, hold the previous count.
    check_hold_when_enable_low: assert property (
        @(posedge clk) disable iff (reset) !$past(enable) |-> (count == $past(count))
    );

    // With enable HIGH and previous count not 15, increment by 1.
    check_increment_on_enable: assert property (
        @(posedge clk) disable iff (reset) $past(enable) && !$past(reset) && ($past(count) != 4'd15) |-> (count == $past(count) + 4'd1)
    );

    // With enable HIGH and previous count 15, wrap to 0.
    check_wrap_on_max: assert property (
        @(posedge clk) disable iff (reset) $past(enable) && !$past(reset) && ($past(count) == 4'd15) |-> (count == 4'd0)
    );

    // If count changed without current reset, prior enable must have been HIGH or prior reset was HIGH.
    check_change_requires_enable_or_prev_reset: assert property (
        @(posedge clk) disable iff (reset) (count != $past(count)) |-> ($past(enable) || $past(reset))
    );

    // Without prior reset, next count equals the RTL next-state function.
    check_next_state_function: assert property (
        @(posedge clk) disable iff (reset)
            !$past(reset) |-> (count == ($past(enable) ? (($past(count) == 4'd15) ? 4'd0 : ($past(count) + 4'd1)) : $past(count)))
    );

    // Without prior reset, reaching 0 with enable implies previous value was 15.
    check_zero_only_from_wrap_when_enabled: assert property (
        @(posedge clk) disable iff (reset) (!$past(reset) && (count == 4'd0) && $past(enable)) |-> ($past(count) == 4'd15)
    );
endmodule

rtl:
module unsigned_comparator (
    input [3:0] A,
    input [3:0] B,
    output EQ,
    output GT,
    output LT
);

    assign EQ = (A == B);
    assign GT = (A > B);
    assign LT = (A < B);

endmodule

sva:
module unsigned_comparator_sva (
    input logic CLK,
    input logic RESETn,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic EQ,
    input logic GT,
    input logic LT
);
    // DUT is pure combinational; assertions are clocked on CLK and gated by active-low RESETn.

    // EQ must reflect A == B.
    check_eq_definition: assert property (
        @(posedge CLK) disable iff (!RESETn) (EQ == (A == B))
    );

    // GT must reflect A > B.
    check_gt_definition: assert property (
        @(posedge CLK) disable iff (!RESETn) (GT == (A > B))
    );

    // LT must reflect A < B.
    check_lt_definition: assert property (
        @(posedge CLK) disable iff (!RESETn) (LT == (A < B))
    );

    // Exactly one of {EQ, GT, LT} must be HIGH.
    check_outputs_onehot: assert property (
        @(posedge CLK) disable iff (!RESETn) $onehot({EQ, GT, LT})
    );

    // If EQ is HIGH, GT and LT must be LOW.
    check_eq_excludes_others: assert property (
        @(posedge CLK) disable iff (!RESETn) EQ |-> (!GT && !LT)
    );

    // If GT is HIGH, EQ and LT must be LOW.
    check_gt_excludes_others: assert property (
        @(posedge CLK) disable iff (!RESETn) GT |-> (!EQ && !LT)
    );

    // If LT is HIGH, EQ and GT must be LOW.
    check_lt_excludes_others: assert property (
        @(posedge CLK) disable iff (!RESETn) LT |-> (!EQ && !GT)
    );

    // EQ must equal the negation of (GT or LT).
    check_eq_is_complement_of_gt_or_lt: assert property (
        @(posedge CLK) disable iff (!RESETn) (EQ == !(GT || LT))
    );

endmodule

rtl:
module full_adder (
    input a,
    input b,
    input cin,
    output sum,
    output cout
);

    assign sum = a ^ b ^ cin;
    assign cout = (a & b) | (cin & (a ^ b));

endmodule

module ripple_adder (
    input [3:0] a,
    input [3:0] b,
    output c
);

    wire [3:0] sum;
    wire [3:1] carry;

    full_adder fa0 (
        .a(a[0]),
        .b(b[0]),
        .cin(1'b0),
        .sum(sum[0]),
        .cout(carry[1])
    );

    full_adder fa1 (
        .a(a[1]),
        .b(b[1]),
        .cin(carry[1]),
        .sum(sum[1]),
        .cout(carry[2])
    );

    full_adder fa2 (
        .a(a[2]),
        .b(b[2]),
        .cin(carry[2]),
        .sum(sum[2]),
        .cout(carry[3])
    );

    full_adder fa3 (
        .a(a[3]),
        .b(b[3]),
        .cin(carry[3]),
        .sum(sum[3]),
        .cout(c)
    );

endmodule

sva:
module ripple_adder_sva (
    input logic CLK,
    input logic [3:0] a,
    input logic [3:0] b,
    input logic c
);

    // Compute ripple carry-out (cin=0) from a,b bits.
    function automatic logic carry4 (input logic [3:0] x, input logic [3:0] y);
        logic c1, c2, c3, c4;
        c1 = x[0] & y[0];
        c2 = (x[1] & y[1]) | ((x[1] ^ y[1]) & c1);
        c3 = (x[2] & y[2]) | ((x[2] ^ y[2]) & c2);
        c4 = (x[3] & y[3]) | ((x[3] ^ y[3]) & c3);
        return c4;
    endfunction

    // Compute carry-out of lower 3 bits (cin=0).
    function automatic logic carry3 (input logic [2:0] x, input logic [2:0] y);
        logic c1, c2, c3;
        c1 = x[0] & y[0];
        c2 = (x[1] & y[1]) | ((x[1] ^ y[1]) & c1);
        c3 = (x[2] & y[2]) | ((x[2] ^ y[2]) & c2);
        return c3;
    endfunction

    // Carry-out equals overflow bit of 5-bit sum {0,a}+{0,b}.
    check_c_matches_add_overflow: assert property (
        @(posedge CLK) c == ({1'b0, a} + {1'b0, b})[4]
    );

    // Carry-out matches explicit ripple-carry computation (cin=0).
    check_c_matches_ripple_chain: assert property (
        @(posedge CLK) c == carry4(a, b)
    );

    // No carry when either operand is zero.
    check_no_carry_when_operand_zero: assert property (
        @(posedge CLK) ((a == 4'b0000) || (b == 4'b0000)) |-> (c == 1'b0)
    );

    // No carry when both MSBs are 0.
    check_no_carry_when_msb00: assert property (
        @(posedge CLK) (!a[3] && !b[3]) |-> (c == 1'b0)
    );

    // Carry is 1 when both MSBs are 1.
    check_carry_when_msb11: assert property (
        @(posedge CLK) (a[3] && b[3]) |-> (c == 1'b1)
    );

    // If exactly one MSB is 1 and low 3-bit add carries, carry-out is 1.
    check_carry_one_msb_and_lower_carry: assert property (
        @(posedge CLK) ((a[3] ^ b[3]) && (carry3(a[2:0], b[2:0]) == 1'b1)) |-> (c == 1'b1)
    );

    // If exactly one MSB is 1 and low 3-bit add does not carry, carry-out is 0.
    check_no_carry_one_msb_no_lower_carry: assert property (
        @(posedge CLK) ((a[3] ^ b[3]) && (carry3(a[2:0], b[2:0]) == 1'b0)) |-> (c == 1'b0)
    );

endmodule

rtl:
module top_module (
    input [3:0] multiplier,
    input [3:0] multiplicand,
    input [15:0] in0,
    input [15:0] in1,
    input ctrl,
    output reg [15:0] out
);

    wire [7:0] unsigned_mult_out;
    wire [3:0] add_sub_out;
    wire [15:0] final_out;

    unsigned_multiplier unsigned_mult(.a(multiplier), .b(multiplicand), .p(unsigned_mult_out));
    add_sub add_sub(.a(multiplier), .b(multiplicand), .ctrl(ctrl), .s(add_sub_out));
    functional_module functional(.in0(unsigned_mult_out), .in1(add_sub_out), .out(final_out));

    always @(*) begin
        if (ctrl == 0) begin
            out = final_out;
        end else begin
            out = final_out + in0 + in1;
        end
    end

endmodule

module unsigned_multiplier (
    input [3:0] a,
    input [3:0] b,
    output reg [7:0] p
);

    always @(*) begin
        p = a * b;
    end

endmodule

module add_sub (
    input [3:0] a,
    input [3:0] b,
    input ctrl,
    output reg [3:0] s
);

    always @(*) begin
        if (ctrl == 0) begin
            s = a + b;
        end else begin
            s = a - b;
        end
    end

endmodule

module functional_module (
    input [7:0] in0,
    input [3:0] in1,
    output reg [15:0] out
);

    always @(*) begin
        out = {8'b0, in0} + {12'b0, in1};
    end

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic [3:0] multiplier,
    input logic [3:0] multiplicand,
    input logic [15:0] in0,
    input logic [15:0] in1,
    input logic ctrl,
    input logic [15:0] out
);
    // Note: DUT is purely combinational with no reset; assertions are sampled on clk with no disable.

    // Helper expressions matching DUT math
    let prod8_l  = (multiplier * multiplicand);                  // 8-bit product
    let sum4_l   = (multiplier + multiplicand);                  // 4-bit add (wrap)
    let diff4_l  = (multiplier - multiplicand);                  // 4-bit sub (wrap)
    let final0_l = {8'b0, prod8_l} + {12'b0, sum4_l};            // functional_module(out) when ctrl==0
    let final1_l = {8'b0, prod8_l} + {12'b0, diff4_l};           // functional_module(out) when ctrl==1

    // When ctrl==0, out equals functional_module result (product + add) zero-extended.
    check_ctrl0_out_equation: assert property (
        @(posedge clk) disable iff (1'b0)
            (ctrl == 1'b0) |-> (out == final0_l)
    );

    // When ctrl==1, out equals functional result (product + sub) plus in0 and in1 (16-bit wrap).
    check_ctrl1_out_equation: assert property (
        @(posedge clk) disable iff (1'b0)
            (ctrl == 1'b1) |-> (out == (final1_l + in0 + in1))
    );

    // Under ctrl==0, upper 8 bits of out are zero (result fits in 8 bits after nibble add).
    check_ctrl0_upper_zero: assert property (
        @(posedge clk) disable iff (1'b0)
            (ctrl == 1'b0) |-> (out[15:8] == 8'h00)
    );

    // If all inputs are stable, out remains stable (purely combinational function).
    check_stable_when_inputs_stable: assert property (
        @(posedge clk) disable iff (1'b0)
            $stable({multiplier, multiplicand, ctrl, in0, in1}) |-> $stable(out)
    );

    // Under ctrl==0, with ctrl/multiplier/multiplicand stable, out is stable (ignores in0/in1).
    check_ctrl0_independent_of_in0_in1: assert property (
        @(posedge clk) disable iff (1'b0)
            (ctrl == 1'b0 && $stable(ctrl) && $stable(multiplier) && $stable(multiplicand)) |-> $stable(out)
    );

    // Under ctrl==0, low nibble equals (prod[3:0] + (a+b))[3:0].
    check_ctrl0_low_nibble: assert property (
        @(posedge clk) disable iff (1'b0)
            (ctrl == 1'b0) |-> (out[3:0] == ((prod8_l[3:0] + sum4_l)[3:0]))
    );

    // Under ctrl==0, out is within the computed bound (<= 240).
    check_ctrl0_range_bound: assert property (
        @(posedge clk) disable iff (1'b0)
            (ctrl == 1'b0) |-> (out <= 16'd240)
    );

    // Under ctrl==1 and in0==0 and in1==0, out reduces to functional result (product + sub).
    check_ctrl1_zero_ext_inputs: assert property (
        @(posedge clk) disable iff (1'b0)
            (ctrl == 1'b1 && in0 == 16'h0000 && in1 == 16'h0000) |-> (out == final1_l)
    );

    // On ctrl falling edge, output selects the ctrl==0 path immediately.
    check_ctrl_fall_selects_ctrl0_path: assert property (
        @(posedge clk) disable iff (1'b0)
            $fell(ctrl) |-> (out == final0_l)
    );

    // On ctrl rising edge, output selects the ctrl==1 path immediately.
    check_ctrl_rise_selects_ctrl1_path: assert property (
        @(posedge clk) disable iff (1'b0)
            $rose(ctrl) |-> (out == (final1_l + in0 + in1))
    );

endmodule

rtl:
module counter(
  input clk,
  input reset,
  output reg [3:0] out
);

  // Combinational always block
  always @ (posedge clk or posedge reset) begin
    if (reset) begin
      out <= 4'b0000;
    end else begin
      out <= out + 1;
    end
  end

endmodule

sva:
module counter_sva (
    input logic clk,
    input logic reset,
    input logic [3:0] out
);
    // On any clock where reset is high, out must be 0 on the next clock.
    reset_clears_out_next: assert property (
        @(posedge clk) reset |=> (out == 4'd0)
    );

    // If reset was high on the previous clock, out must be 0 now.
    reset_prev_cycle_forces_zero_now: assert property (
        @(posedge clk) $past(reset) |-> (out == 4'd0)
    );

    // If reset is high on two consecutive clocks, out must be 0 now.
    reset_held_keeps_out_zero_now: assert property (
        @(posedge clk) (reset && $past(reset)) |-> (out == 4'd0)
    );

    // Sanity: out is always within 4-bit range (0..15).
    out_width_range: assert property (
        @(posedge clk) (out inside {[4'd0:4'd15]})
    );
endmodule

rtl:
module and_or_not (
    input A,
    input B,
    input C,
    output Y
);

wire and_result, not_result;

assign and_result = A & B;
assign not_result = !C;
assign Y = and_result | not_result;

endmodule

sva:
module and_or_not_sva (
    input logic CLK,
    input logic A,
    input logic B,
    input logic C,
    input logic Y
);
    // Y equals (A & B) OR (!C).
    check_functional_equivalence: assert property (
        @(posedge CLK) Y == ((A & B) | (!C))
    );

    // When C is LOW, Y must be HIGH.
    check_c_low_dominates: assert property (
        @(posedge CLK) (C == 1'b0) |-> (Y == 1'b1)
    );

    // When C is HIGH, Y equals A & B.
    check_c_high_matches_and: assert property (
        @(posedge CLK) (C == 1'b1) |-> (Y == (A & B))
    );

    // If Y is LOW, then C is HIGH and at least one of A or B is LOW.
    check_y_zero_implies_c_high_and_not_ab: assert property (
        @(posedge CLK) (Y == 1'b0) |-> (C == 1'b1) && ((A == 1'b0) || (B == 1'b0))
    );

    // If Y and C are HIGH, then both A and B are HIGH.
    check_y_and_c_high_implies_both_inputs_high: assert property (
        @(posedge CLK) (Y == 1'b1) && (C == 1'b1) |-> (A == 1'b1) && (B == 1'b1)
    );

    // If Y is HIGH while A is LOW, then C must be LOW.
    check_y_high_and_a_low_implies_c_low: assert property (
        @(posedge CLK) (Y == 1'b1) && (A == 1'b0) |-> (C == 1'b0)
    );

    // If Y is HIGH while B is LOW, then C must be LOW.
    check_y_high_and_b_low_implies_c_low: assert property (
        @(posedge CLK) (Y == 1'b1) && (B == 1'b0) |-> (C == 1'b0)
    );

    // If A, B, and C are stable, Y remains stable.
    check_stable_inputs_keep_y_stable: assert property (
        @(posedge CLK) $stable(A) && $stable(B) && $stable(C) |-> $stable(Y)
    );

    // A falling edge on C forces Y HIGH (due to !C term).
    check_c_fall_forces_y_high: assert property (
        @(posedge CLK) $fell(C) |-> (Y == 1'b1)
    );

    // With C HIGH, a rising A when B is HIGH sets Y HIGH.
    check_c_high_a_rise_with_b1_sets_y: assert property (
        @(posedge CLK) (C == 1'b1) && $rose(A) && (B == 1'b1) |-> (Y == 1'b1)
    );

    // With C HIGH, a rising B when A is HIGH sets Y HIGH.
    check_c_high_b_rise_with_a1_sets_y: assert property (
        @(posedge CLK) (C == 1'b1) && $rose(B) && (A == 1'b1) |-> (Y == 1'b1)
    );

    // With C HIGH, a falling A clears Y LOW.
    check_c_high_a_fall_clears_y: assert property (
        @(posedge CLK) (C == 1'b1) && $fell(A) |-> (Y == 1'b0)
    );

    // With C HIGH, a falling B clears Y LOW.
    check_c_high_b_fall_clears_y: assert property (
        @(posedge CLK) (C == 1'b1) && $fell(B) |-> (Y == 1'b0)
    );
endmodule

module counter_sva #(
    parameter WIDTH = 8,
    parameter MODULUS = 256
)(
    input logic clk,
    input logic ce,
    input logic clr,
    input logic [WIDTH-1:0] out
);
    ///// Clock: clk; Reset: clr (synchronous, active-high) /////

    // After any cycle with clr HIGH, out must be 0 on the next cycle.
    check_sync_clear_next_zero: assert property (
        @(posedge clk) disable iff (clr) $past(clr) |-> (out == '0)
    );

    // With no clr and ce LOW in the previous cycle, out holds its value.
    check_hold_without_ce: assert property (
        @(posedge clk) disable iff (clr) (!$past(clr) && !$past(ce)) |-> (out == $past(out))
    );

    // With no clr and ce HIGH below MODULUS-1 in the previous cycle, out increments by 1.
    check_increment_when_ce_high_below_max: assert property (
        @(posedge clk) disable iff (clr)
        (!$past(clr) && $past(ce) && ($past(out) != MODULUS-1)) |-> (out == $past(out) + 1)
    );

    // With no clr and ce HIGH at MODULUS-1 in the previous cycle, out wraps to 0.
    check_wrap_when_ce_high_at_max: assert property (
        @(posedge clk) disable iff (clr)
        (!$past(clr) && $past(ce) && ($past(out) == MODULUS-1)) |-> (out == '0)
    );

    // Any change in out must be caused by prior clr or ce.
    check_change_requires_ce_or_clr_prev: assert property (
        @(posedge clk) disable iff (clr) (out != $past(out)) |-> ($past(clr) || $past(ce))
    );

    // A transition to 0 (from non-zero) without prior clr must be a wrap from MODULUS-1 with ce.
    check_zero_transition_only_on_wrap_or_reset: assert property (
        @(posedge clk) disable iff (clr)
        (!$past(clr) && (out == '0) && ($past(out) != '0)) |-> ($past(ce) && ($past(out) == MODULUS-1))
    );

    // With prior ce and no prior clr, the next state is either increment or wrap (no other values).
    check_ce_step_is_inc_or_wrap: assert property (
        @(posedge clk) disable iff (clr)
        (!$past(clr) && $past(ce)) |-> (
            (($past(out) == MODULUS-1) && (out == '0)) ||
            (($past(out) != MODULUS-1) && (out == $past(out) + 1))
        )
    );

    // Without prior clr, out can only hold, increment by 1, or wrap to 0 from MODULUS-1.
    check_no_leap_changes: assert property (
        @(posedge clk) disable iff (clr)
        (!$past(clr)) |-> (
            (out == $past(out)) ||
            (($past(out) == MODULUS-1) && (out == '0)) ||
            (out == $past(out) + 1)
        )
    );

endmodule

rtl:
module comparator (
  input [(8 - 1):0] a,
  input [(8 - 1):0] b,
  output [(1 - 1):0] op,
  input clk,
  input ce,
  input clr
);

  reg [(1 - 1):0] op_reg;
  wire [(8 - 1):0] a_reg;
  wire [(8 - 1):0] b_reg;

  assign a_reg = a;
  assign b_reg = b;

  always @(posedge clk) begin
    if (clr) begin
      op_reg <= 1'b0;
    end else if (ce) begin
      op_reg <= (a_reg == b_reg) ? 1'b1 : 1'b0;
    end
  end

  assign op = op_reg;

endmodule

sva:
module comparator_sva (
    input logic [7:0] a,
    input logic [7:0] b,
    input logic       op,
    input logic       clk,
    input logic       ce,
    input logic       clr
);

    ///// Reset behavior /////
    // On clr assertion, op is cleared on the next clock.
    reset_clears_op_next: assert property (
        @(posedge clk) clr |=> (op == 1'b0)
    );

    // clr has priority over ce when both are asserted.
    reset_overrides_ce: assert property (
        @(posedge clk) (clr && ce) |=> (op == 1'b0)
    );

    ///// Capture behavior /////
    // With ce high, op updates next cycle to (a == b).
    update_on_ce: assert property (
        @(posedge clk) disable iff (clr) ce |=> (op == (a == b))
    );

    // With ce high and a == b, next op is 1.
    update_one_on_eq: assert property (
        @(posedge clk) disable iff (clr) (ce && (a == b)) |=> (op == 1'b1)
    );

    // With ce high and a != b, next op is 0.
    update_zero_on_neq: assert property (
        @(posedge clk) disable iff (clr) (ce && (a != b)) |=> (op == 1'b0)
    );

    ///// Hold behavior /////
    // With ce low, op holds its value unless reset occurs next cycle.
    hold_when_ce_low: assert property (
        @(posedge clk) disable iff (clr) (!ce) |=> (clr || $stable(op))
    );

    ///// Change qualification /////
    // A rising edge of op implies prior ce with a == b.
    op_rise_implies_prev_ce_eq: assert property (
        @(posedge clk) disable iff (clr) $rose(op) |-> $past(ce && (a == b))
    );

    // A falling edge of op implies prior ce with a != b or a prior reset.
    op_fall_implies_prev_ce_neq_or_reset: assert property (
        @(posedge clk) disable iff (clr) $fell(op) |-> ($past(ce && (a != b)) || $past(clr))
    );

endmodule

rtl:
module shift_register (
  input clk,
  input shift_enable,
  input parallel_load_enable,
  input [15:0] data_in,
  output [15:0] data_out
);

  reg [15:0] register;

  always @(posedge clk) begin
    if (parallel_load_enable) begin
      register <= data_in;
    end else if (shift_enable) begin
      register <= {register[14:0], 1'b0};
    end
  end

  assign data_out = register;

endmodule

sva:
module shift_register_sva (
  input logic clk,
  input logic shift_enable,
  input logic parallel_load_enable,
  input logic [15:0] data_in,
  input logic [15:0] data_out
);
  // Clock: clk (posedge). No reset. Sequential register: parallel load > else shift-left with 0 fill > else hold.

  // Parallel load updates data_out on the next cycle to current data_in.
  load_updates_next: assert property (
    @(posedge clk) parallel_load_enable |=> (data_out == $past(data_in,1,data_in))
  );

  // Shift-left by one with zero fill when shifting without load.
  shift_vector_update: assert property (
    @(posedge clk) (!parallel_load_enable && shift_enable) |=> (data_out == { $past(data_out,1,data_out)[14:0], 1'b0 })
  );

  // LSB becomes 0 on shift (no load).
  shift_lsb_zero: assert property (
    @(posedge clk) (!parallel_load_enable && shift_enable) |=> (data_out[0] == 1'b0)
  );

  // MSB becomes prior bit14 on shift (no load).
  shift_msb_from_bit14: assert property (
    @(posedge clk) (!parallel_load_enable && shift_enable) |=> (data_out[15] == $past(data_out,1,data_out)[14])
  );

  // Hold value when neither load nor shift is enabled.
  hold_when_idle: assert property (
    @(posedge clk) (!parallel_load_enable && !shift_enable) |=> (data_out == $past(data_out,1,data_out))
  );

  // Load has priority over shift when both are asserted.
  load_over_shift_priority: assert property (
    @(posedge clk) (parallel_load_enable && shift_enable) |=> (data_out == $past(data_in,1,data_in))
  );

  // Any change in data_out must be caused by a load or shift in the previous cycle.
  change_requires_enable: assert property (
    @(posedge clk) (data_out != $past(data_out,1,data_out)) |-> $past(parallel_load_enable || shift_enable,1,1'b0)
  );

  // Sixteen consecutive shifts with no load clear the register to zero.
  sixteen_shifts_clear_to_zero: assert property (
    @(posedge clk) (!parallel_load_enable && shift_enable)[*16] |=> (data_out == 16'h0000)
  );

endmodule

rtl:
module top_module (
    input A,
    input B,
    input C_in,
    output [8:0] out
);

    wire [1:0] fa1_out;
    wire [1:0] fa2_out;
    wire parity_bit;

    // Full Adder 1
    full_adder fa1 (
        .A(A),
        .B(B),
        .C_in(C_in),
        .sum(fa1_out[0]),
        .C_out(fa1_out[1])
    );

    // Full Adder 2
    full_adder fa2 (
        .A(fa1_out[0]),
        .B(fa1_out[1]),
        .C_in(1'b0),
        .sum(fa2_out[0]),
        .C_out(fa2_out[1])
    );

    // Parity Bit Calculation
    assign parity_bit = (A ^ B ^ fa2_out[0]) & (A | B | fa2_out[0]);

    // Output
    assign out = {parity_bit, fa2_out};

endmodule

// Full Adder
module full_adder (
    input A,
    input B,
    input C_in,
    output sum,
    output C_out
);

    assign sum = A ^ B ^ C_in;
    assign C_out = (A & B) | (C_in & (A ^ B));

endmodule

sva:
module top_module_sva (
    input logic CLK,
    input logic A,
    input logic B,
    input logic C_in,
    input logic [8:0] out,
    input logic [1:0] fa1_out,
    input logic [1:0] fa2_out,
    input logic parity_bit
);
    // fa1 sum equals A ^ B ^ C_in.
    check_fa1_sum: assert property (
        @(posedge CLK) (fa1_out[0] == (A ^ B ^ C_in))
    );

    // fa1 carry equals (A & B) | (C_in & (A ^ B)).
    check_fa1_carry: assert property (
        @(posedge CLK) (fa1_out[1] == ((A & B) | (C_in & (A ^ B))))
    );

    // fa2 sum equals fa1_sum ^ fa1_carry ^ 1'b0.
    check_fa2_sum: assert property (
        @(posedge CLK) (fa2_out[0] == (fa1_out[0] ^ fa1_out[1] ^ 1'b0))
    );

    // fa2 carry equals (fa1_sum & fa1_carry) | (1'b0 & (fa1_sum ^ fa1_carry)).
    check_fa2_carry: assert property (
        @(posedge CLK) (fa2_out[1] == ((fa1_out[0] & fa1_out[1]) | (1'b0 & (fa1_out[0] ^ fa1_out[1]))))
    );

    // Parity bit equals (A ^ B ^ fa2_sum) & (A | B | fa2_sum).
    check_parity_definition: assert property (
        @(posedge CLK) (parity_bit == ((A ^ B ^ fa2_out[0]) & (A | B | fa2_out[0])))
    );

    // out[1:0] maps directly to fa2_out[1:0].
    check_out_lower_mapping: assert property (
        @(posedge CLK) (out[1:0] == fa2_out[1:0])
    );

    // out[2] maps directly to parity_bit.
    check_out_parity_mapping: assert property (
        @(posedge CLK) (out[2] == parity_bit)
    );

    // out[8:3] are zero due to width extension in assignment.
    check_out_upper_zero: assert property (
        @(posedge CLK) (out[8:3] == 6'b0)
    );

    // out[0] equals (A ^ B ^ C_in) ^ ((A & B) | (C_in & (A ^ B))).
    check_out0_from_inputs: assert property (
        @(posedge CLK) (out[0] == ((A ^ B ^ C_in) ^ ((A & B) | (C_in & (A ^ B)))))
    );

    // out[1] equals ((A ^ B ^ C_in) & ((A & B) | (C_in & (A ^ B)))).
    check_out1_from_inputs: assert property (
        @(posedge CLK) (out[1] == ((A ^ B ^ C_in) & ((A & B) | (C_in & (A ^ B)))))
    );
endmodule

