module counter4(clk, enable, reset, out);

	output reg [3:0] out;
	input clk, enable, reset;

	always@(posedge clk or posedge reset) begin
		if(reset == 1'b1) begin
			out <= 4'b0;
		end
		else if(enable == 1'b1) begin
			out <= out + 1;
		end
	end

endmodule

sva:
module counter4_sva (
    input  logic        clk,
    input  logic        enable,
    input  logic        reset,
    input  logic [3:0]  out
);
    // During reset, out is forced to 0 on each clock.
    check_reset_forces_zero: assert property (
        @(posedge clk) reset |-> (out == 4'd0)
    );

    // If previous cycle was not in reset and enable was 0, out holds its value.
    check_hold_when_prev_disabled: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(reset) && !$past(enable)) |-> (out == $past(out))
    );

    // If previous cycle was not in reset and enable was 1, out increments by 1 modulo 16.
    check_increment_when_prev_enabled: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(reset) && $past(enable)) |-> (out == (($past(out) + 4'd1) & 4'hF))
    );

    // When previous value was 15 and enable was 1 (no reset), counter wraps to 0.
    check_wrap_from_max_with_enable: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(reset) && $past(enable) && ($past(out) == 4'hF)) |-> (out == 4'h0)
    );
endmodule

rtl:
module ripple_adder (
  input [3:0] A,
  input [3:0] B,
  input Cin,
  output [3:0] S,
  output Cout
);
  wire [4:0] sum;

  assign sum = A + B + Cin;
  assign S = sum[3:0];
  assign Cout = sum[4];

endmodule

sva:
module ripple_adder_sva (
    input logic CLK,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic Cin,
    input logic [3:0] S,
    input logic Cout
);
    ///// Arithmetic correctness /////
    // Combined output equals zero-extended sum of A, B, and Cin.
    check_combined_sum: assert property (
        @(posedge CLK) {Cout, S} == ({1'b0, A} + {1'b0, B} + Cin)
    );

    // Lower 4 bits of the sum drive S.
    check_s_low_bits: assert property (
        @(posedge CLK) S == (({1'b0, A} + {1'b0, B} + Cin)[3:0])
    );

    // MSB of the sum drives Cout.
    check_carry_out_bit: assert property (
        @(posedge CLK) Cout == (({1'b0, A} + {1'b0, B} + Cin)[4])
    );

    ///// Input-conditional behaviors /////
    // With Cin=0, outputs equal A+B.
    check_no_carry_in_case: assert property (
        @(posedge CLK) (!Cin) |-> ({Cout, S} == ({1'b0, A} + {1'b0, B}))
    );

    // With Cin=1, outputs equal A+B+1.
    check_with_carry_in_case: assert property (
        @(posedge CLK) (Cin) |-> ({Cout, S} == ({1'b0, A} + {1'b0, B} + 5'd1))
    );

    // All zeros in => all zeros out.
    check_zero_case: assert property (
        @(posedge CLK) (A == 4'd0 && B == 4'd0 && Cin == 1'b0) |-> (S == 4'd0 && Cout == 1'b0)
    );

    // Max inputs with Cin=1 => S=0xF and Cout=1.
    check_max_case: assert property (
        @(posedge CLK) (A == 4'hF && B == 4'hF && Cin == 1'b1) |-> (S == 4'hF && Cout == 1'b1)
    );

    ///// Temporal consistency for pure combinational logic /////
    // Stable inputs imply stable outputs.
    check_stable_inputs_hold_outputs: assert property (
        @(posedge CLK) ($stable(A) && $stable(B) && $stable(Cin)) |-> ($stable(S) && $stable(Cout))
    );

    // If A and B are stable and Cin rises, the 5-bit sum increments by 1.
    check_cin_rise_increments_sum: assert property (
        @(posedge CLK) ($stable(A) && $stable(B) && $rose(Cin)) |-> ({Cout, S} == ($past({Cout, S}) + 5'd1))
    );

    // If A and B are stable and Cin falls, the 5-bit sum decrements by 1.
    check_cin_fall_decrements_sum: assert property (
        @(posedge CLK) ($stable(A) && $stable(B) && $fell(Cin)) |-> ({Cout, S} == ($past({Cout, S}) - 5'd1))
    );

    // Swapping A and B across cycles with Cin unchanged preserves outputs.
    check_commutativity_over_time: assert property (
        @(posedge CLK) ((A == $past(B)) && (B == $past(A)) && (Cin == $past(Cin))) |-> ({Cout, S} == $past({Cout, S}))
    );
endmodule

rtl:
module sky130_fd_sc_lp__and2 (
    X,
    A,
    B
);

    output X;
    input  A;
    input  B;

    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    wire and0_out_X;

    and and0 (and0_out_X, A, B           );
    buf buf0 (X         , and0_out_X     );

endmodule

sva:
module sky130_fd_sc_lp__and2_sva (
    input logic CLK,   // external clock for sampling assertions
    input logic X,     // DUT output
    input logic A,     // DUT input
    input logic B      // DUT input
);
    // DUT has no clock/reset; pure combinational AND: X = A & B; assertions sampled on CLK.

    // X equals A & B every sampled cycle.
    check_functional_and: assert property (
        @(posedge CLK) X == (A & B)
    );

    // If X is 1, both inputs must be 1.
    check_x_one_implies_inputs_one: assert property (
        @(posedge CLK) X |-> (A && B)
    );

    // If both inputs are 1, X must be 1.
    check_inputs_one_implies_x_one: assert property (
        @(posedge CLK) (A && B) |-> X
    );

    // If A is 0, X must be 0.
    check_a_zero_forces_x_zero: assert property (
        @(posedge CLK) (A == 1'b0) |-> (X == 1'b0)
    );

    // If B is 0, X must be 0.
    check_b_zero_forces_x_zero: assert property (
        @(posedge CLK) (B == 1'b0) |-> (X == 1'b0)
    );

    // X can only rise when both inputs are 1.
    check_x_rise_requires_both_one: assert property (
        @(posedge CLK) $rose(X) |-> (A && B)
    );

    // X can only fall when at least one input is 0.
    check_x_fall_requires_any_zero: assert property (
        @(posedge CLK) $fell(X) |-> (!A || !B)
    );

    // If both inputs are stable, X must be stable.
    check_inputs_stable_implies_x_stable: assert property (
        @(posedge CLK) $stable(A) && $stable(B) |-> $stable(X)
    );

    // When A rises with B=1, X must be 1 that cycle.
    check_a_rise_with_b1_implies_x1: assert property (
        @(posedge CLK) $rose(A) && (B == 1'b1) |-> (X == 1'b1)
    );

    // When A falls with B=1, X must be 0 that cycle.
    check_a_fall_with_b1_implies_x0: assert property (
        @(posedge CLK) $fell(A) && (B == 1'b1) |-> (X == 1'b0)
    );

endmodule

rtl:
module priority_encoder (
    input [1:0] in,
    output reg [1:0] out
);

    always @* begin
        case(in)
            2'b00: out = 2'b00;
            2'b01: out = 2'b01;
            2'b10: out = 2'b10;
            2'b11: out = 2'b11;
            default: out = 2'b00;
        endcase
    end

endmodule

sva:
module priority_encoder_sva (
    input logic clk,
    input logic [1:0] in,
    input logic [1:0] out
);
    // Combinational DUT with no reset; use clk only for sampling.

    // Output equals input every sampled cycle.
    check_out_equals_in: assert property (
        @(posedge clk) out == in
    );

    // For in==00, out must be 00.
    check_case_00: assert property (
        @(posedge clk) (in == 2'b00) |-> (out == 2'b00)
    );

    // For in==01, out must be 01.
    check_case_01: assert property (
        @(posedge clk) (in == 2'b01) |-> (out == 2'b01)
    );

    // For in==10, out must be 10.
    check_case_10: assert property (
        @(posedge clk) (in == 2'b10) |-> (out == 2'b10)
    );

    // For in==11, out must be 11.
    check_case_11: assert property (
        @(posedge clk) (in == 2'b11) |-> (out == 2'b11)
    );

    // If input is stable across cycles, output is stable.
    check_stability_when_input_stable: assert property (
        @(posedge clk) (in == $past(in)) |-> (out == $past(out))
    );

    // Output change across cycles implies input changed.
    check_output_change_requires_input_change: assert property (
        @(posedge clk) $changed(out) |-> $changed(in)
    );

    // Input change across cycles implies output changed.
    check_input_change_implies_output_change: assert property (
        @(posedge clk) $changed(in) |-> $changed(out)
    );
endmodule

rtl:
module comparator #(
  parameter n = 8 // number of bits in input signals
)(
  input [n-1:0] in1,
  input [n-1:0] in2,
  output eq,
  output gt,
  output lt
);


wire [n-1:0] xor_out;
wire [n-1:0] and_out1;
wire [n-1:0] and_out2;

assign xor_out = in1 ^ in2;
assign and_out1 = in1 & xor_out;
assign and_out2 = in2 & xor_out;

assign eq = ~|xor_out;
assign gt = |and_out1;
assign lt = |and_out2;

endmodule

sva:
module comparator_sva #(
  parameter int n = 8
)(
  input logic CLK,
  input logic [n-1:0] in1,
  input logic [n-1:0] in2,
  input logic eq,
  input logic gt,
  input logic lt
);

  // eq is 1 iff all bits of in1 and in2 are equal.
  check_eq_function: assert property (
    @(posedge CLK) eq == (in1 == in2)
  );

  // gt is 1 iff there exists a bit where in1=1 and in2=0.
  check_gt_function: assert property (
    @(posedge CLK) gt == (|(in1 & ~in2))
  );

  // lt is 1 iff there exists a bit where in2=1 and in1=0.
  check_lt_function: assert property (
    @(posedge CLK) lt == (|(in2 & ~in1))
  );

  // eq implies neither gt nor lt is asserted.
  check_eq_blocks_gt_lt: assert property (
    @(posedge CLK) eq |-> (!gt && !lt)
  );

  // If inputs differ, at least one of gt or lt must be asserted.
  check_ineq_implies_flag: assert property (
    @(posedge CLK) (in1 != in2) |-> (gt || lt)
  );

  // If either gt or lt is asserted, inputs must differ.
  check_flag_implies_ineq: assert property (
    @(posedge CLK) (gt || lt) |-> (in1 != in2)
  );

  // eq is the logical complement of (gt || lt).
  check_eq_complements_flags: assert property (
    @(posedge CLK) eq == !(gt || lt)
  );

endmodule

rtl:
module baud_rate_generator(
    input clk, rst_n, bps_start,
    output wire clk_baud
);

parameter BAUD_RATE = 9600;
parameter freq = 16000000; // 16 MHz clock frequency

reg [31:0] counter;
reg toggle;

always @(posedge clk or negedge rst_n) begin
    if(!rst_n) begin
        counter <= 0;
        toggle <= 0;
    end
    else if(bps_start) begin
        counter <= counter + 1;
        if(counter == (freq / (BAUD_RATE * 2))) begin
            toggle <= ~toggle;
            counter <= 0;
        end
    end
end

assign clk_baud = toggle;

endmodule

sva:
module baud_rate_generator_sva (
    input logic clk,
    input logic rst_n,
    input logic bps_start,
    input logic clk_baud,
    // Internal DUT signals (from RTL)
    input logic [31:0] counter,
    input logic toggle
);
    // Mirror DUT parameters to compute threshold used in RTL
    parameter int BAUD_RATE = 9600;
    parameter int freq = 16000000;
    localparam int THRESH = freq / (BAUD_RATE * 2);

    ///// Reset behavior /////
    // While reset is asserted, counter and toggle are 0 and clk_baud is LOW.
    reset_drive_low: assert property (
        @(posedge clk) !rst_n |-> (counter == 32'd0) && (toggle == 1'b0) && (clk_baud == 1'b0)
    );

    // On the cycle reset deasserts, state remains cleared (toggle=0, counter=0, clk_baud=0).
    reset_release_clear: assert property (
        @(posedge clk) $rose(rst_n) |-> (counter == 32'd0) && (toggle == 1'b0) && (clk_baud == 1'b0)
    );

    ///// Output connectivity /////
    // clk_baud must always mirror toggle (continuous assign).
    check_clk_baud_mirrors_toggle: assert property (
        @(posedge clk) disable iff (!rst_n) (clk_baud === toggle)
    );

    ///// Functional behavior /////
    // When bps_start is HIGH and counter equals THRESH, next cycle toggle flips and counter resets to 0.
    toggle_on_threshold: assert property (
        @(posedge clk) disable iff (!rst_n)
            (bps_start && (counter == THRESH)) |=> (toggle == ~$past(toggle)) && (counter == 32'd0)
    );

    // When bps_start is HIGH and counter is not THRESH, next cycle counter increments and toggle holds.
    count_when_running: assert property (
        @(posedge clk) disable iff (!rst_n)
            (bps_start && (counter != THRESH)) |=> (counter == $past(counter) + 32'd1) && (toggle == $past(toggle))
    );

    // When bps_start is LOW, next cycle counter and toggle hold their values (no counting).
    hold_when_stopped: assert property (
        @(posedge clk) disable iff (!rst_n)
            (!bps_start) |=> (counter == $past(counter)) && (toggle == $past(toggle)) && (clk_baud == $past(clk_baud))
    );

endmodule

rtl:
module decoder_2to4 (
    input [1:0] in,
    input clk,
    output reg [3:0] out
);

reg [3:0] out_reg;

always @(*) begin
    case(in)
        2'b00: out_reg = 4'b0001;
        2'b01: out_reg = 4'b0010;
        2'b10: out_reg = 4'b0100;
        2'b11: out_reg = 4'b1000;
    endcase;
end

always @(posedge clk) begin
    out <= out_reg;
end

endmodule

sva:
module decoder_2to4_sva (
    input logic clk,
    input logic [1:0] in,
    input logic [3:0] out
);
    // Output equals one-hot decode of prior input.
    check_registered_decode: assert property (
        @(posedge clk) disable iff ($initstate) out == (4'b0001 << $past(in))
    );

    // Output is always one-hot after initialization.
    check_out_onehot: assert property (
        @(posedge clk) disable iff ($initstate) $onehot(out)
    );

    // Output is always one of the four valid one-hot values.
    check_out_valid_set: assert property (
        @(posedge clk) disable iff ($initstate) (out inside {4'b0001,4'b0010,4'b0100,4'b1000})
    );

    // If input is unchanged for two consecutive cycles, output holds its value.
    check_hold_when_input_stable: assert property (
        @(posedge clk) disable iff ($initstate) ($past(in) == $past(in,2)) |-> (out == $past(out))
    );

    // If input changes between the last two cycles, output changes accordingly.
    check_change_when_input_changes: assert property (
        @(posedge clk) disable iff ($initstate) ($past(in) != $past(in,2)) |-> (out != $past(out))
    );
endmodule

