sva:
module five_input_module_sva (
    input  logic CLK,
    input  logic RESETn,
    input  logic A1,
    input  logic A2,
    input  logic A3,
    input  logic B1,
    input  logic B2,
    input  logic Y
);
    // Y equals its defining boolean function.
    check_y_function: assert property (
        @(posedge CLK) disable iff (!RESETn) Y == ((A1 & A2) | (A1 & A3) | (B1 & B2))
    );

    // If A1 is 0, Y reduces to B1 & B2.
    check_y_when_A1_zero: assert property (
        @(posedge CLK) disable iff (!RESETn) (A1 == 1'b0) |-> (Y == (B1 & B2))
    );

    // If either B1 or B2 is 0, Y reduces to A1 & (A2 | A3).
    check_y_when_Bpair_zero: assert property (
        @(posedge CLK) disable iff (!RESETn) ((B1 == 1'b0) || (B2 == 1'b0)) |-> (Y == (A1 & (A2 | A3)))
    );

    // If A1 and (A2 or A3) are 1, Y must be 1.
    check_y_forced_high_by_A_path: assert property (
        @(posedge CLK) disable iff (!RESETn) (A1 & (A2 | A3)) |-> (Y == 1'b1)
    );

    // If B1 and B2 are 1, Y must be 1.
    check_y_forced_high_by_B_path: assert property (
        @(posedge CLK) disable iff (!RESETn) (B1 & B2) |-> (Y == 1'b1)
    );

    // If A2 and A3 are 0, Y reduces to B1 & B2.
    check_y_when_A2A3_zero: assert property (
        @(posedge CLK) disable iff (!RESETn) ((A2 == 1'b0) && (A3 == 1'b0)) |-> (Y == (B1 & B2))
    );

    // If A2 and A3 are 1, Y equals A1 | (B1 & B2).
    check_y_when_A2A3_one: assert property (
        @(posedge CLK) disable iff (!RESETn) ((A2 == 1'b1) && (A3 == 1'b1)) |-> (Y == (A1 | (B1 & B2)))
    );

    // If A2 is 0 and B2 is 0, Y reduces to A1 & A3.
    check_y_when_A2_zero_B2_zero: assert property (
        @(posedge CLK) disable iff (!RESETn) ((A2 == 1'b0) && (B2 == 1'b0)) |-> (Y == (A1 & A3))
    );

    // With all inputs stable across a cycle, Y must remain stable.
    check_y_stable_if_inputs_stable: assert property (
        @(posedge CLK) disable iff (!RESETn) ($stable(A1) && $stable(A2) && $stable(A3) && $stable(B1) && $stable(B2)) |-> $stable(Y)
    );

    // Any change on Y must be caused by a change on at least one input.
    check_y_changes_require_input_change: assert property (
        @(posedge CLK) disable iff (!RESETn) $changed(Y) |-> ($changed(A1) || $changed(A2) || $changed(A3) || $changed(B1) || $changed(B2))
    );
endmodule

module mux_2to1_sva (
    input logic a,
    input logic b,
    input logic sel_b1,
    input logic sel_b2,
    input logic out_always
);
    // Output matches the 2:1 mux equation.
    check_mux_equation: assert property (
        @(posedge a or posedge b or posedge sel_b1 or posedge sel_b2)
        out_always == ((sel_b2 & ~sel_b1) ? b : a)
    );

    // When sel_b2=1 and sel_b1=0, output equals b.
    check_b_selected: assert property (
        @(posedge a or posedge b or posedge sel_b1 or posedge sel_b2)
        (sel_b2 && !sel_b1) |-> (out_always == b)
    );

    // When sel_b2=0, output equals a.
    check_a_when_sel_b2_low: assert property (
        @(posedge a or posedge b or posedge sel_b1 or posedge sel_b2)
        (!sel_b2) |-> (out_always == a)
    );

    // When sel_b1=1, output equals a.
    check_a_when_sel_b1_high: assert property (
        @(posedge a or posedge b or posedge sel_b1 or posedge sel_b2)
        (sel_b1) |-> (out_always == a)
    );

    // If a and b are equal, output equals that value.
    check_equal_inputs_pass_through: assert property (
        @(posedge a or posedge b or posedge sel_b1 or posedge sel_b2)
        (a == b) |-> (out_always == a)
    );
endmodule

module four_bit_decoder_sva (
    input  logic        CLK,   // Sampling clock for assertions
    input  logic [3:0]  A,
    input  logic [3:0]  B
);
    // B must equal binary-to-Gray conversion: A ^ (A >> 1).
    check_gray_formula: assert property (
        @(posedge CLK) disable iff (1'b0) B == (A ^ (A >> 1))
    );

    // When A==0000, B must be 0000.
    check_map_A_0000: assert property (
        @(posedge CLK) disable iff (1'b0) (A == 4'b0000) |-> (B == 4'b0000)
    );
    // When A==0001, B must be 0001.
    check_map_A_0001: assert property (
        @(posedge CLK) disable iff (1'b0) (A == 4'b0001) |-> (B == 4'b0001)
    );
    // When A==0010, B must be 0011.
    check_map_A_0010: assert property (
        @(posedge CLK) disable iff (1'b0) (A == 4'b0010) |-> (B == 4'b0011)
    );
    // When A==0011, B must be 0010.
    check_map_A_0011: assert property (
        @(posedge CLK) disable iff (1'b0) (A == 4'b0011) |-> (B == 4'b0010)
    );
    // When A==0100, B must be 0110.
    check_map_A_0100: assert property (
        @(posedge CLK) disable iff (1'b0) (A == 4'b0100) |-> (B == 4'b0110)
    );
    // When A==0101, B must be 0111.
    check_map_A_0101: assert property (
        @(posedge CLK) disable iff (1'b0) (A == 4'b0101) |-> (B == 4'b0111)
    );
    // When A==0110, B must be 0101.
    check_map_A_0110: assert property (
        @(posedge CLK) disable iff (1'b0) (A == 4'b0110) |-> (B == 4'b0101)
    );
    // When A==0111, B must be 0100.
    check_map_A_0111: assert property (
        @(posedge CLK) disable iff (1'b0) (A == 4'b0111) |-> (B == 4'b0100)
    );
    // When A==1000, B must be 1100.
    check_map_A_1000: assert property (
        @(posedge CLK) disable iff (1'b0) (A == 4'b1000) |-> (B == 4'b1100)
    );
    // When A==1001, B must be 1101.
    check_map_A_1001: assert property (
        @(posedge CLK) disable iff (1'b0) (A == 4'b1001) |-> (B == 4'b1101)
    );
    // When A==1010, B must be 1111.
    check_map_A_1010: assert property (
        @(posedge CLK) disable iff (1'b0) (A == 4'b1010) |-> (B == 4'b1111)
    );
    // When A==1011, B must be 1110.
    check_map_A_1011: assert property (
        @(posedge CLK) disable iff (1'b0) (A == 4'b1011) |-> (B == 4'b1110)
    );
    // When A==1100, B must be 1010.
    check_map_A_1100: assert property (
        @(posedge CLK) disable iff (1'b0) (A == 4'b1100) |-> (B == 4'b1010)
    );
    // When A==1101, B must be 1011.
    check_map_A_1101: assert property (
        @(posedge CLK) disable iff (1'b0) (A == 4'b1101) |-> (B == 4'b1011)
    );
    // When A==1110, B must be 1001.
    check_map_A_1110: assert property (
        @(posedge CLK) disable iff (1'b0) (A == 4'b1110) |-> (B == 4'b1001)
    );
    // When A==1111, B must be 1000.
    check_map_A_1111: assert property (
