sva:
module sky130_fd_sc_ls__nand3_sva (
    input logic Y,
    input logic A,
    input logic B,
    input logic C
);
    // Combinational NAND3 cell; no clock/reset. Sample assertions on input posedges.

    // Y equals ~(A & B & C) when sampled on A rising edge.
    check_nand_truth_on_A: assert property (
        @(posedge A) Y == ~(A & B & C)
    );

    // Y equals ~(A & B & C) when sampled on B rising edge.
    check_nand_truth_on_B: assert property (
        @(posedge B) Y == ~(A & B & C)
    );

    // Y equals ~(A & B & C) when sampled on C rising edge.
    check_nand_truth_on_C: assert property (
        @(posedge C) Y == ~(A & B & C)
    );

    // If all inputs are HIGH then Y must be LOW (sampled on A).
    check_all_high_implies_low_on_A: assert property (
        @(posedge A) (A && B && C) |-> (Y == 1'b0)
    );

    // If all inputs are HIGH then Y must be LOW (sampled on B).
    check_all_high_implies_low_on_B: assert property (
        @(posedge B) (A && B && C) |-> (Y == 1'b0)
    );

    // If all inputs are HIGH then Y must be LOW (sampled on C).
    check_all_high_implies_low_on_C: assert property (
        @(posedge C) (A && B && C) |-> (Y == 1'b0)
    );

    // If any input is LOW then Y must be HIGH (sampled on A).
    check_any_low_implies_high_on_A: assert property (
        @(posedge A) ((!A) || (!B) || (!C)) |-> (Y == 1'b1)
    );

    // If any input is LOW then Y must be HIGH (sampled on B).
    check_any_low_implies_high_on_B: assert property (
        @(posedge B) ((!A) || (!B) || (!C)) |-> (Y == 1'b1)
    );

    // If any input is LOW then Y must be HIGH (sampled on C).
    check_any_low_implies_high_on_C: assert property (
        @(posedge C) ((!A) || (!B) || (!C)) |-> (Y == 1'b1)
    );
endmodule

rtl:
module timer(
    input CLK_I,
    input RST_I,

    input [31:2] ADR_I,
    input CYC_I,
    input STB_I,
    input WE_I,

    output reg RTY_O,
    output reg interrupt_o
);

    reg [27:0] counter;

    always @(posedge CLK_I) begin
        if(RST_I == 1'b1) begin
            RTY_O <= 1'b0;
            interrupt_o <= 1'b0;
            counter <= 28'd0;
        end
        else if(counter == 28'h00FFFFF) begin
            if(ADR_I == { 27'b1111_1111_1111_1111_1111_1111_111, 3'b001 } && CYC_I == 1'b1 && STB_I == 1'b1 && WE_I == 1'b0 && interrupt_o == 1'b1) begin
                RTY_O <= 1'b1;
                interrupt_o <= 1'b0;
                counter <= 28'd0;
            end
            else begin
                interrupt_o <= 1'b1;
            end
        end
        else begin
            RTY_O <= 1'b0;
            counter <= counter + 28'd1;
        end
    end

endmodule

sva:
module timer_sva (
    input logic CLK_I,
    input logic RST_I,

    input logic [31:2] ADR_I,
    input logic CYC_I,
    input logic STB_I,
    input logic WE_I,

    input logic RTY_O,
    input logic interrupt_o,

    // Internal signal from DUT
    input logic [27:0] counter
);

    // Reset sets RTY_O, interrupt_o, and counter to 0 on the next cycle.
    reset_clears_outputs_and_counter: assert property (
        @(posedge CLK_I) RST_I |=> (RTY_O == 1'b0) && (interrupt_o == 1'b0) && (counter == 28'd0)
    );

    // Counter never exceeds terminal value 28'h00FFFFF.
    check_counter_bounded: assert property (
        @(posedge CLK_I) disable iff (RST_I) counter <= 28'h00FFFFF
    );

    // When not at terminal count, counter increments by 1 next cycle.
    inc_when_not_at_limit: assert property (
        @(posedge CLK_I) disable iff (RST_I)
            (counter != 28'h00FFFFF) |=> (counter == $past(counter) + 28'd1)
    );

    // When not at terminal count, RTY_O is driven LOW next cycle.
    rty_low_when_not_at_limit: assert property (
        @(posedge CLK_I) disable iff (RST_I)
            (counter != 28'h00FFFFF) |=> (RTY_O == 1'b0)
    );

    // When not at terminal count, interrupt_o is unchanged next cycle.
    interrupt_unchanged_when_not_at_limit: assert property (
        @(posedge CLK_I) disable iff (RST_I)
            (counter != 28'h00FFFFF) |=> (interrupt_o == $past(interrupt_o))
    );

    // When at terminal count and matching read access with interrupt_o==1, clear: RTY_O=1, interrupt_o=0, counter=0 next cycle.
    clear_when_limit_and_bus_read: assert property (
        @(posedge CLK_I) disable iff (RST_I)
            (counter == 28'h00FFFFF) &&
            (ADR_I == {27'b1111_1111_1111_1111_1111_1111_111, 3'b001}) &&
            (CYC_I == 1'b1) && (STB_I == 1'b1) && (WE_I == 1'b0) && (interrupt_o == 1'b1)
            |=> (RTY_O == 1'b1) && (interrupt_o == 1'b0) && (counter == 28'd0)
    );

    // When at terminal count without the matching read access, interrupt_o is set HIGH next cycle.
    set_interrupt_when_limit_without_clear: assert property (
        @(posedge CLK_I) disable iff (RST_I)
            (counter == 28'h00FFFFF) &&
            !((ADR_I == {27'b1111_1111_1111_1111_1111_1111_111, 3'b001}) &&
              (CYC_I == 1'b1) && (STB_I == 1'b1) && (WE_I == 1'b0) && (interrupt_o == 1'b1))
            |=> (interrupt_o == 1'b1)
    );

    // When at terminal count without the matching read access, counter holds its value next cycle.
    hold_counter_when_limit_without_clear: assert property (
        @(posedge CLK_I) disable iff (RST_I)
            (counter == 28'h00FFFFF) &&
            !((ADR_I == {27'b1111_1111_1111_1111_1111_1111_111, 3'b001}) &&
              (CYC_I == 1'b1) && (STB_I == 1'b1) && (WE_I == 1'b0) && (interrupt_o == 1'b1))
            |=> (counter == $past(counter))
    );

    // When at terminal count without the matching read access, RTY_O holds its value next cycle.
    hold_rty_when_limit_without_clear: assert property (
        @(posedge CLK_I) disable iff (RST_I)
            (counter == 28'h00FFFFF) &&
            !((ADR_I == {27'b1111_1111_1111_1111_1111_1111_111, 3'b001}) &&
              (CYC_I == 1'b1) && (STB_I == 1'b1) && (WE_I == 1'b0) && (interrupt_o == 1'b1))
            |=> (RTY_O == $past(RTY_O))
    );

    // A rising edge on RTY_O implies previous cycle was the matching read at terminal count.
    rty_rose_only_from_clear: assert property (
        @(posedge CLK_I) disable iff (RST_I)
            $rose(RTY_O) |-> ($past(counter) == 28'h00FFFFF) &&
                           ($past(ADR_I) == {27'b1111_1111_1111_1111_1111_1111_111, 3'b001}) &&
                           ($past(CYC_I) == 1'b1) && ($past(STB_I) == 1'b1) &&
                           ($past(WE_I) == 1'b0) && ($past(interrupt_o) == 1'b1)
    );

    // A rising edge on interrupt_o implies previous cycle was terminal count without the matching read.
    interrupt_rose_only_from_limit_no_clear: assert property (
        @(posedge CLK_I) disable iff (RST_I)
            $rose(interrupt_o) |-> ($past(counter) == 28'h00FFFFF) &&
                                 !(( $past(ADR_I) == {27'b1111_1111_1111_1111_1111_1111_111, 3'b001}) &&
                                    ($past(CYC_I) == 1'b1) && ($past(STB_I) == 1'b1) &&
                                    ($past(WE_I) == 1'b0) && ($past(interrupt_o) == 1'b1))
    );

    // RTY_O pulses for a single cycle.
    rty_is_single_cycle_pulse: assert property (
        @(posedge CLK_I) disable iff (RST_I)
            RTY_O |=> !RTY_O
    );

endmodule

rtl:
module accumulator
  #(parameter IWIDTH=16, OWIDTH=30)
    (input clk,
     input clear,
     input acc,
     input signed [IWIDTH-1:0] in,
     output reg signed [OWIDTH-1:0] out);

   wire signed [OWIDTH-1:0] in_signext;
   wire signed [OWIDTH-1:0] in_signext_extended;

   assign in_signext_extended = {{OWIDTH-IWIDTH{in[IWIDTH-1]}}, in};

   // CLEAR & ~ACC --> clears the accumulator
   // CLEAR & ACC --> loads the accumulator
   // ~CLEAR & ACC --> accumulates
   // ~CLEAR & ~ACC --> hold

   wire signed [OWIDTH-1:0] addend1 = clear ? 0 : out;
   wire signed [OWIDTH-1:0] addend2 = ~acc ? 0 : in_signext_extended;
   wire signed [OWIDTH-1:0] sum_int = addend1 + addend2;

   always @(posedge clk)
     out <= sum_int;

endmodule

sva:
module accumulator_sva
  #(parameter IWIDTH=16, OWIDTH=30)
  (
    input logic clk,
    input logic clear,
    input logic acc,
    input logic signed [IWIDTH-1:0] in,
    input logic signed [OWIDTH-1:0] out
  );

  // Clock: clk (posedge). No reset in RTL.
  // Logic: sequential reg out with combinational precompute.
  // Behavior: out_next = (clear ? 0 : out) + (acc ? signext(in) : 0).

  // Out updates exactly per the RTL next-state equation.
  check_update_equation: assert property (
    @(posedge clk)
      $past(1'b1,1,1'b0) |-> ( out == ( ($past(clear) ? '0 : $past(out)) + ($past(acc) ? $signed($past(in)) : '0) ) )
  );

  // When ~clear & ~acc, out holds its previous value.
  check_hold_when_idle: assert property (
    @(posedge clk)
      $past(1'b1,1,1'b0) && $past(!clear && !acc) |-> ( out == $past(out) )
  );

  // When clear & ~acc, out becomes zero.
  check_clear_without_acc_zeros: assert property (
    @(posedge clk)
      $past(1'b1,1,1'b0) && $past(clear && !acc) |-> ( out == '0 )
  );

  // When clear & acc, out loads sign-extended input.
  check_load_on_clear_and_acc: assert property (
    @(posedge clk)
      $past(1'b1,1,1'b0) && $past(clear && acc) |-> ( out == $signed($past(in)) )
  );

  // When ~clear & acc, out accumulates previous out plus sign-extended input.
  check_accumulate_adds_input: assert property (
    @(posedge clk)
      $past(1'b1,1,1'b0) && $past(!clear && acc) |-> ( out == $past(out) + $signed($past(in)) )
  );

  // If acc is 0, out ignores input and either holds or clears to zero.
  check_no_acc_behavior: assert property (
    @(posedge clk)
      $past(1'b1,1,1'b0) && $past(!acc) |-> ( out == ($past(clear) ? '0 : $past(out)) )
  );

  // If clear is 1, out ignores previous out and is either 0 or loads input.
  check_clear_behavior: assert property (
    @(posedge clk)
      $past(1'b1,1,1'b0) && $past(clear) |-> ( out == ($past(acc) ? $signed($past(in)) : '0) )
  );

  // Delta on accumulate equals the sign-extended input.
  check_delta_on_accumulate: assert property (
    @(posedge clk)
      $past(1'b1,1,1'b0) && $past(!clear && acc) |-> ( out - $past(out) == $signed($past(in)) )
  );

endmodule

rtl:
module sky130_fd_sc_ms__o21bai (
    Y   ,
    A1  ,
    A2  ,
    B1_N
);

    output Y   ;
    input  A1  ;
    input  A2  ;
    input  B1_N;

    wire b          ;
    wire or0_out    ;
    wire nand0_out_Y;

    not  not0  (b          , B1_N           );
    or   or0   (or0_out    , A2, A1         );
    nand nand0 (nand0_out_Y, b, or0_out     );
    buf  buf0  (Y          , nand0_out_Y    );

endmodule

sva:
module sky130_fd_sc_ms__o21bai_sva (
    input  logic CLK,
    input  logic Y,
    input  logic A1,
    input  logic A2,
    input  logic B1_N
);
    // Y equals B1_N | (~A1 & ~A2).
    check_functional_equivalence: assert property (
        @(posedge CLK) disable iff (1'b0) Y == (B1_N | ((!A1) & (!A2)))
    );

    // Y equals ~( (~B1_N) & (A1 | A2) ).
    check_demorgan_equivalence: assert property (
        @(posedge CLK) disable iff (1'b0) Y == ~( (~B1_N) & (A1 | A2) )
    );

    // B1_N high forces Y high.
    check_b1n_high_forces_y_high: assert property (
        @(posedge CLK) disable iff (1'b0) (B1_N == 1'b1) |-> (Y == 1'b1)
    );

    // When B1_N is low, Y equals NOR(A1, A2).
    check_b1n_low_gives_nor: assert property (
        @(posedge CLK) disable iff (1'b0) (B1_N == 1'b0) |-> (Y == !(A1 || A2))
    );

    // If B1_N is low and (A1 or A2) is high, Y must be low.
    check_enable_low_and_any_input_high_makes_y_low: assert property (
        @(posedge CLK) disable iff (1'b0) ((B1_N == 1'b0) && ((A1 == 1'b1) || (A2 == 1'b1))) |-> (Y == 1'b0)
    );

    // If both A1 and A2 are low, Y must be high.
    check_both_inputs_low_makes_y_high: assert property (
        @(posedge CLK) disable iff (1'b0) ((!A1) && (!A2)) |-> (Y == 1'b1)
    );

    // Y low implies B1_N is low and at least one of A1/A2 is high.
    check_y_low_characterization: assert property (
        @(posedge CLK) disable iff (1'b0) (Y == 1'b0) |-> ((B1_N == 1'b0) && ((A1 == 1'b1) || (A2 == 1'b1)))
    );

    // Y high implies B1_N is high or both A1 and A2 are low.
    check_y_high_characterization: assert property (
        @(posedge CLK) disable iff (1'b0) (Y == 1'b1) |-> ((B1_N == 1'b1) || ((!A1) && (!A2)))
    );

    // With B1_N low and both A1 and A2 high, Y must be low.
    check_b1n_low_and_both_high_makes_y_low: assert property (
        @(posedge CLK) disable iff (1'b0) ((B1_N == 1'b0) && (A1 == 1'b1) && (A2 == 1'b1)) |-> (Y == 1'b0)
    );

    // Rising A1 under B1_N low forces Y low that cycle.
    check_a1_rise_under_b1n_low_forces_y_low: assert property (
        @(posedge CLK) disable iff (1'b0) ($rose(A1) && (B1_N == 1'b0)) |-> (Y == 1'b0)
    );

    // Rising A2 under B1_N low forces Y low that cycle.
    check_a2_rise_under_b1n_low_forces_y_low: assert property (
        @(posedge CLK) disable iff (1'b0) ($rose(A2) && (B1_N == 1'b0)) |-> (Y == 1'b0)
    );
endmodule

rtl:
module TwosComplement (
   input clk,
   input [3:0] in,
   output reg [3:0] out
   );

   always @(posedge clk) begin
      out <= ~in + 1;
   end

endmodule

sva:
module TwosComplement_sva (
    input logic clk,
    input logic [3:0] in,
    input logic [3:0] out
);
    // Out equals two's complement of previous input (one-cycle latency).
    check_out_twos_complement_prev_in: assert property (
        @(posedge clk) out == ((~$past(in)) + 4'd1)
    );

    // LSB of out matches previous LSB of in.
    check_lsb_matches_prev_in: assert property (
        @(posedge clk) out[0] == $past(in[0])
    );

    // Previous input 0 maps to output 0.
    check_prev_zero_maps_zero: assert property (
        @(posedge clk) ($past(in) == 4'h0) |-> (out == 4'h0)
    );

    // Previous input 8 maps to output 8.
    check_prev_eight_maps_eight: assert property (
        @(posedge clk) ($past(in) == 4'h8) |-> (out == 4'h8)
    );

    // Previous input 1 maps to output 15.
    check_prev_one_maps_fifteen: assert property (
        @(posedge clk) ($past(in) == 4'h1) |-> (out == 4'hF)
    );

    // Previous input 15 maps to output 1.
    check_prev_fifteen_maps_one: assert property (
        @(posedge clk) ($past(in) == 4'hF) |-> (out == 4'h1)
    );

    // Output equals previous input only for 0 or 8.
    check_prev_nonfixed_implies_notequal: assert property (
        @(posedge clk) (($past(in) != 4'h0) && ($past(in) != 4'h8)) |-> (out != $past(in))
    );

    // If input was stable last cycle, output remains stable this cycle.
    check_stable_in_prev_implies_stable_out: assert property (
        @(posedge clk) ($past(in) == $past(in,2)) |-> (out == $past(out))
    );

    // If input incremented by 1 (prev-to-prev), output decrements by 1 (prev-to-now).
    check_incr_by1_decr_out_by1: assert property (
        @(posedge clk) ($past(in) == ($past(in,2) + 4'd1)) |-> (out == ($past(out) - 4'd1))
    );

    // If input decremented by 1 (prev-to-prev), output increments by 1 (prev-to-now).
    check_decr_by1_incr_out_by1: assert property (
        @(posedge clk) ($past(in) == ($past(in,2) - 4'd1)) |-> (out == ($past(out) + 4'd1))
    );
endmodule

rtl:
module pass_through(in, out, vdd18);
  input vdd18;
  input [7:0] in;
  output [7:0] out;

  assign out = vdd18 ? in : 8'b0;
endmodule

sva:
module pass_through_sva (
    input logic clk,
    input logic vdd18,
    input logic [7:0] in,
    input logic [7:0] out
);

    // Out equals in when vdd18=1, else zero.
    check_functional_mapping: assert property (
        @(posedge clk) out == (vdd18 ? in : 8'h00)
    );

    // On vdd18 rising edge, out equals in.
    check_on_power_rise: assert property (
        @(posedge clk) $rose(vdd18) |-> (out == in)
    );

    // On vdd18 falling edge, out is zero.
    check_on_power_fall: assert property (
        @(posedge clk) $fell(vdd18) |-> (out == 8'h00)
    );

    // If in and vdd18 do not change, out does not change.
    check_output_stable_when_inputs_stable: assert property (
        @(posedge clk) (!$changed(in) && !$changed(vdd18)) |-> !$changed(out)
    );

    // Out changes only if in or vdd18 changes.
    check_output_change_has_cause: assert property (
        @(posedge clk) $changed(out) |-> ($changed(in) || $changed(vdd18))
    );

    // When vdd18=0 and in changes, out remains zero.
    check_ignore_input_when_power_low: assert property (
        @(posedge clk) (!vdd18 && $changed(in)) |-> (out == 8'h00)
    );

    // When vdd18=1 and in changes, out equals in.
    check_follow_input_when_power_high: assert property (
        @(posedge clk) (vdd18 && $changed(in)) |-> (out == in)
    );

    // Non-zero out implies vdd18 is high.
    check_nonzero_out_implies_power_high: assert property (
        @(posedge clk) (out != 8'h00) |-> vdd18
    );

endmodule

module arithmetic_8bit_sva (
    input logic CLK,
    input logic signed [7:0] A,
    input logic signed [7:0] B,
    input logic sel,
    input logic signed [7:0] Y
);
    typedef logic signed [7:0] s8_t;

    // When sel==0, Y is A + B (8-bit signed wrap).
    check_sum_branch: assert property (
        @(posedge CLK) (sel == 1'b0) |-> (Y == s8_t'(A + B))
    );

    // When sel==1, Y is A - B (8-bit signed wrap).
    check_diff_branch: assert property (
        @(posedge CLK) (sel == 1'b1) |-> (Y == s8_t'(A - B))
    );

    // For addition branch, if B==0 then Y==A.
    check_sum_identity_B_zero: assert property (
        @(posedge CLK) (sel == 1'b0 && (B == 8'sd0)) |-> (Y == A)
    );

    // For addition branch, if A==0 then Y==B.
    check_sum_identity_A_zero: assert property (
        @(posedge CLK) (sel == 1'b0 && (A == 8'sd0)) |-> (Y == B)
    );

    // For subtraction branch, if B==0 then Y==A.
    check_diff_identity_B_zero: assert property (
        @(posedge CLK) (sel == 1'b1 && (B == 8'sd0)) |-> (Y == A)
    );

    // For subtraction branch, if A==B then Y==0.
    check_diff_self_sub_zero: assert property (
        @(posedge CLK) (sel == 1'b1 && (A == B)) |-> (Y == 8'sd0)
    );

    // For addition branch, if B == -A (8-bit) then Y==0.
    check_sum_negation_zero: assert property (
        @(posedge CLK) (sel == 1'b0 && (B == s8_t'(-A))) |-> (Y == 8'sd0)
    );

    // For addition branch, reversing: (Y - B) == A (8-bit).
    check_sum_reverse_relation: assert property (
        @(posedge CLK) (sel == 1'b0) |-> (s8_t'(Y - B) == A)
    );

    // For subtraction branch, reversing: (Y + B) == A (8-bit).
    check_diff_reverse_relation: assert property (
        @(posedge CLK) (sel == 1'b1) |-> (s8_t'(Y + B) == A)
    );

    // If A,B,sel are stable, Y must be stable (combinational determinism).
    check_stability_when_inputs_stable: assert property (
        @(posedge CLK) disable iff ($initstate) $stable({A,B,sel}) |-> $stable(Y)
    );

endmodule

rtl:
module up_counter (
    input clk,
    input reset,
    output reg [3:0] count
);

    always @(posedge clk) begin
        if (reset) begin
            count <= 4'b0;
        end else begin
            count <= count + 1;
        end
    end

endmodule

sva:
module up_counter_sva (
    input logic clk,
    input logic reset,
    input logic [3:0] count
);
    // On any cycle with reset asserted, count is driven to 0.
    reset_drives_zero: assert property (
        @(posedge clk) reset |-> (count == 4'd0)
    );

    // When not in reset for consecutive cycles, count increments by 1 (mod 16).
    count_increments_no_reset: assert property (
        @(posedge clk) disable iff (reset)
        $past(!reset) |-> (count == $past(count) + 4'd1)
    );

    // If previous count was 15 and still not in reset, count wraps to 0.
    count_wraps_from_max: assert property (
        @(posedge clk) disable iff (reset)
        ($past(!reset) && ($past(count) == 4'hF)) |-> (count == 4'd0)
    );

    // On the cycle after reset deasserts, count becomes 1.
    count_one_after_reset_deassert: assert property (
        @(posedge clk) disable iff (reset)
        ($past(reset) && !reset) |-> (count == 4'd1)
    );

    // If count is 0 on a non-reset cycle following a non-reset cycle, it wrapped from 15.
    zero_implies_prev_max: assert property (
        @(posedge clk) disable iff (reset)
        ($past(!reset) && !reset && (count == 4'd0)) |-> ($past(count) == 4'hF)
    );

    // LSB toggles on each non-reset cycle (increment by 1).
    lsb_toggles_each_step: assert property (
        @(posedge clk) disable iff (reset)
        $past(!reset) |-> (count[0] == ~$past(count[0]))
    );
endmodule

rtl:
module verilog_module (
    //# {{data|Data Signals}}
    input  A1  ,
    input  A2  ,
    input  B1  ,
    input  C1  ,
    output X   ,

    //# {{power|Power}}
    input  VPB ,
    input  VPWR,
    input  VGND,
    input  VNB
);

    wire A1_A2;
    wire B1_C1;

    assign A1_A2 = A1 & A2;
    assign B1_C1 = B1 & C1;

    assign X = A1_A2 | B1_C1;

endmodule

sva:
module verilog_module_sva (
    input logic A1,
    input logic A2,
    input logic B1,
    input logic C1,
    input logic X,
    input logic VPB,
    input logic VPWR,
    input logic VGND,
    input logic VNB
);

    // X must equal (A1 & A2) | (B1 & C1).
    check_x_or_of_ands: assert property (
        @(posedge A1 or posedge A2 or posedge B1 or posedge C1 or posedge X or posedge VPB or posedge VPWR or posedge VGND or posedge VNB)
            X == ((A1 & A2) | (B1 & C1))
    );

    // If A1&A2 is 1 then X must be 1.
    check_a_term_implies_x: assert property (
        @(posedge A1 or posedge A2 or posedge B1 or posedge C1 or posedge X or posedge VPB or posedge VPWR or posedge VGND or posedge VNB)
            (A1 && A2) |-> (X == 1'b1)
    );

    // If B1&C1 is 1 then X must be 1.
    check_b_term_implies_x: assert property (
        @(posedge A1 or posedge A2 or posedge B1 or posedge C1 or posedge X or posedge VPB or posedge VPWR or posedge VGND or posedge VNB)
            (B1 && C1) |-> (X == 1'b1)
    );

    // If X is 1 then at least one product term is 1.
    check_x_one_implies_some_term: assert property (
        @(posedge A1 or posedge A2 or posedge B1 or posedge C1 or posedge X or posedge VPB or posedge VPWR or posedge VGND or posedge VNB)
            (X == 1'b1) |-> ((A1 && A2) || (B1 && C1))
    );

    // If X is 0 then both product terms are 0.
    check_x_zero_implies_no_terms: assert property (
        @(posedge A1 or posedge A2 or posedge B1 or posedge C1 or posedge X or posedge VPB or posedge VPWR or posedge VGND or posedge VNB)
            (X == 1'b0) |-> ((! (A1 && A2)) && (! (B1 && C1)))
    );

    // If both product terms are 0 then X is 0.
    check_x_zero_when_no_terms_true: assert property (
        @(posedge A1 or posedge A2 or posedge B1 or posedge C1 or posedge X or posedge VPB or posedge VPWR or posedge VGND or posedge VNB)
            ((! (A1 && A2)) && (! (B1 && C1))) |-> (X == 1'b0)
    );

    // If all four inputs are 0 then X is 0.
    check_x_zero_when_all_zero: assert property (
        @(posedge A1 or posedge A2 or posedge B1 or posedge C1 or posedge X or posedge VPB or posedge VPWR or posedge VGND or posedge VNB)
            ((A1 == 1'b0) && (A2 == 1'b0) && (B1 == 1'b0) && (C1 == 1'b0)) |-> (X == 1'b0)
    );

    // If A1 and B1 are 0 then X is 0.
    check_x_zero_when_a1_b1_zero: assert property (
        @(posedge A1 or posedge A2 or posedge B1 or posedge C1 or posedge X or posedge VPB or posedge VPWR or posedge VGND or posedge VNB)
            ((A1 == 1'b0) && (B1 == 1'b0)) |-> (X == 1'b0)
    );

    // If A2 and C1 are 0 then X is 0.
    check_x_zero_when_a2_c1_zero: assert property (
        @(posedge A1 or posedge A2 or posedge B1 or posedge C1 or posedge X or posedge VPB or posedge VPWR or posedge VGND or posedge VNB)
            ((A2 == 1'b0) && (C1 == 1'b0)) |-> (X == 1'b0)
    );

    // If both product terms are 1 then X is 1.
    check_x_one_when_both_terms_true: assert property (
        @(posedge A1 or posedge A2 or posedge B1 or posedge C1 or posedge X or posedge VPB or posedge VPWR or posedge VGND or posedge VNB)
            ((A1 && A2) && (B1 && C1)) |-> (X == 1'b1)
    );

    // When B-path is off, X equals A1&A2.
    check_x_equals_a_term_when_b_off: assert property (
        @(posedge A1 or posedge A2 or posedge B1 or posedge C1 or posedge X or posedge VPB or posedge VPWR or posedge VGND or posedge VNB)
            ((B1 == 1'b0) || (C1 == 1'b0)) |-> (X == (A1 & A2))
    );

    // When A-path is off, X equals B1&C1.
    check_x_equals_b_term_when_a_off: assert property (
        @(posedge A1 or posedge A2 or posedge B1 or posedge C1 or posedge X or posedge VPB or posedge VPWR or posedge VGND or posedge VNB)
            ((A1 == 1'b0) || (A2 == 1'b0)) |-> (X == (B1 & C1))
    );

    // X does not change if A1,A2,B1,C1 are stable.
    check_x_stable_when_inputs_stable: assert property (
        @(posedge A1 or posedge A2 or posedge B1 or posedge C1 or posedge X or negedge X or posedge VPB or posedge VPWR or posedge VGND or posedge VNB)
            $stable({A1, A2, B1, C1}) |-> $stable(X)
    );

endmodule

rtl:
module add_sub (
    input [3:0] A,
    input [3:0] B,
    input SUB,
    output [3:0] Q
);

    wire [3:0] sum;
    wire [3:0] diff;

    assign sum = A + B;
    assign diff = A - B;

    assign Q = SUB ? diff : sum;

endmodule

sva:
module add_sub_sva (
    input logic clk,          // External clock for SVA (RTL has no clock/reset)
    input logic [3:0] A,
    input logic [3:0] B,
    input logic SUB,
    input logic [3:0] Q
);
    // Q equals (A + B) when SUB is 0 (modulo-16)
    check_sum_path: assert property (
        @(posedge clk) (SUB == 1'b0) |-> (Q == (A + B)[3:0])
    );

    // Q equals (A - B) when SUB is 1 (modulo-16)
    check_diff_path: assert property (
        @(posedge clk) (SUB == 1'b1) |-> (Q == (A - B)[3:0])
    );

    // On SUB falling edge, Q reflects sum path
    check_q_on_sub_fall: assert property (
        @(posedge clk) $fell(SUB) |-> (Q == (A + B)[3:0])
    );

    // On SUB rising edge, Q reflects diff path
    check_q_on_sub_rise: assert property (
        @(posedge clk) $rose(SUB) |-> (Q == (A - B)[3:0])
    );

    // Add inverse: when SUB=0, (Q - B) mod 16 equals A
    check_add_inverse: assert property (
        @(posedge clk) (SUB == 1'b0) |-> ((Q - B)[3:0] == A)
    );

    // Sub inverse: when SUB=1, (Q + B) mod 16 equals A
    check_sub_inverse: assert property (
        @(posedge clk) (SUB == 1'b1) |-> ((Q + B)[3:0] == A)
    );

    // If B is zero, Q equals A regardless of SUB
    check_b_zero_transparency: assert property (
        @(posedge clk) (B == 4'd0) |-> (Q == A)
    );

    // If SUB=0 and A is zero, Q equals B
    check_a_zero_add_identity: assert property (
        @(posedge clk) (SUB == 1'b0 && A == 4'd0) |-> (Q == B)
    );

    // If SUB=1 and A equals B, Q is zero
    check_equal_operands_sub_zero: assert property (
        @(posedge clk) (SUB == 1'b1 && A == B) |-> (Q == 4'd0)
    );

    // If inputs are stable, output remains stable
    check_stability_when_inputs_stable: assert property (
        @(posedge clk) $stable(A) && $stable(B) && $stable(SUB) |-> $stable(Q)
    );
endmodule

rtl:
module five_to_one (
    input A1,
    input A2,
    input A3,
    input [1:0] B,
    output X
);

    assign X = (A1 == 1) && (A2 == 0) && (A3 == 1) && (B == 2'b10 || B == 2'b11);

endmodule

sva:
module five_to_one_sva (
    input logic A1,
    input logic A2,
    input logic A3,
    input logic [1:0] B,
    input logic X
);
    // X matches the RTL boolean equation exactly.
    check_x_definition: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge A3 or negedge A3 or posedge B[0] or negedge B[0] or posedge B[1] or negedge B[1] or posedge X or negedge X)
        X == ((A1 == 1'b1) && (A2 == 1'b0) && (A3 == 1'b1) && ((B == 2'b10) || (B == 2'b11)))
    );

    // If X is 1, inputs must satisfy the enable condition.
    check_x_high_implies_inputs: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge A3 or negedge A3 or posedge B[0] or negedge B[0] or posedge B[1] or negedge B[1] or posedge X or negedge X)
        (X == 1'b1) |-> ((A1 == 1'b1) && (A2 == 1'b0) && (A3 == 1'b1) && ((B == 2'b10) || (B == 2'b11)))
    );

    // A1 low forces X low.
    check_a1_low_blocks_x: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge A3 or negedge A3 or posedge B[0] or negedge B[0] or posedge B[1] or negedge B[1] or posedge X or negedge X)
        (A1 == 1'b0) |-> (X == 1'b0)
    );

    // A2 high forces X low.
    check_a2_high_blocks_x: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge A3 or negedge A3 or posedge B[0] or negedge B[0] or posedge B[1] or negedge B[1] or posedge X or negedge X)
        (A2 == 1'b1) |-> (X == 1'b0)
    );

    // A3 low forces X low.
    check_a3_low_blocks_x: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge A3 or negedge A3 or posedge B[0] or negedge B[0] or posedge B[1] or negedge B[1] or posedge X or negedge X)
        (A3 == 1'b0) |-> (X == 1'b0)
    );

    // B[1] low forces X low (B must be 2'b10 or 2'b11).
    check_b_msb_low_blocks_x: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge A3 or negedge A3 or posedge B[0] or negedge B[0] or posedge B[1] or negedge B[1] or posedge X or negedge X)
        (B[1] == 1'b0) |-> (X == 1'b0)
    );

    // Exact enable case with B==2'b10 drives X high.
    check_enable_case_b10_sets_x: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge A3 or negedge A3 or posedge B[0] or negedge B[0] or posedge B[1] or negedge B[1] or posedge X or negedge X)
        ((A1 == 1'b1) && (A2 == 1'b0) && (A3 == 1'b1) && (B == 2'b10)) |-> (X == 1'b1)
    );

    // Exact enable case with B==2'b11 drives X high.
    check_enable_case_b11_sets_x: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge A3 or negedge A3 or posedge B[0] or negedge B[0] or posedge B[1] or negedge B[1] or posedge X or negedge X)
        ((A1 == 1'b1) && (A2 == 1'b0) && (A3 == 1'b1) && (B == 2'b11)) |-> (X == 1'b1)
    );

    // If B is not 2'b10 or 2'b11, X must be low.
    check_invalid_b_values_block_x: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge A3 or negedge A3 or posedge B[0] or negedge B[0] or posedge B[1] or negedge B[1] or posedge X or negedge X)
        !((B == 2'b10) || (B == 2'b11)) |-> (X == 1'b0)
    );
endmodule

module contador_AD_MM_2dig_sva (
    input logic clk,
    input logic reset,
    input logic [3:0] en_count,
    input logic enUP,
    input logic enDOWN,
    input logic [7:0] data_MM
);

    // Helper: decode 2-digit BCD to integer
    function automatic int unsigned bcd8_to_int (input logic [7:0] bcd);
        return int'(bcd[7:4]) * 10 + int'(bcd[3:0]);
    endfunction

    // Helper: increment modulo 60
    function automatic int unsigned inc_mod60 (input int unsigned v);
        return (v >= 59) ? 0 : (v + 1);
    endfunction

    // Helper: decrement modulo 60
    function automatic int unsigned dec_mod60 (input int unsigned v);
        return (v == 0) ? 59 : (v - 1);
    endfunction

    // Helper: data_MM is valid BCD in range 00..59
    function automatic bit is_valid_bcd_00_59 (input logic [7:0] b);
        return (b[7:4] <= 4'd5) && (b[3:0] <= 4'd9);
    endfunction

    ///// Reset behavior /////
    // While reset is asserted HIGH, the displayed value is 00.
    reset_drives_zero: assert property (
        @(posedge clk) reset |-> (data_MM == 8'h00)
    );

    ///// Output encoding rules /////
    // data_MM is always a valid 2-digit BCD value in the range 00..59.
    bcd_range_valid: assert property (
        @(posedge clk) disable iff (reset) is_valid_bcd_00_59(data_MM)
    );

    ///// Hold behavior /////
    // When en_count != 2, the value holds (no change next cycle).
    hold_when_count_disabled: assert property (
        @(posedge clk) disable iff (reset)
            (en_count != 4'd2) |=> (data_MM == $past(data_MM))
    );

    // When enabled (en_count==2) but no direction requested, the value holds.
    hold_when_no_dir_enabled: assert property (
        @(posedge clk) disable iff (reset)
            (en_count == 4'd2) && !enUP && !enDOWN |=> (data_MM == $past(data_MM))
    );

    ///// Up-count behavior /////
    // When enabled and enUP is HIGH (regardless of enDOWN), increment modulo 60.
    inc_on_up_enabled: assert property (
        @(posedge clk) disable iff (reset)
            (en_count == 4'd2) && enUP
            |=> (bcd8_to_int(data_MM) == inc_mod60(bcd8_to_int($past(data_MM))))
    );

    // When both enUP and enDOWN are HIGH while enabled, UP has priority (increments).
    up_precedence_over_down: assert property (
        @(posedge clk) disable iff (reset)
            (en_count == 4'd2) && enUP && enDOWN
            |=> (bcd8_to_int(data_MM) == inc_mod60(bcd8_to_int($past(data_MM))))
    );

    // Wrap on UP from 59 to 00 when enabled.
    wrap_up_59_to_00: assert property (
        @(posedge clk) disable iff (reset)
            (en_count == 4'd2) && enUP && (bcd8_to_int(data_MM) == 59)
            |=> (bcd8_to_int(data_MM) == 0)
    );

    ///// Down-count behavior /////
    // When enabled with enDOWN and enUP LOW, decrement modulo 60.
    dec_on_down_enabled_no_up: assert property (
        @(posedge clk) disable iff (reset)
            (en_count == 4'd2) && !enUP && enDOWN
            |=> (bcd8_to_int(data_MM) == dec_mod60(bcd8_to_int($past(data_MM))))
    );

    // Wrap on DOWN from 00 to 59 when enabled and UP is LOW.
    wrap_down_00_to_59: assert property (
        @(posedge clk) disable iff (reset)
            (en_count == 4'd2) && !enUP && enDOWN && (bcd8_to_int(data_MM) == 0)
            |=> (bcd8_to_int(data_MM) == 59)
    );

endmodule

rtl:
module four_bit_adder(
    input [3:0] a,
    input [3:0] b,
    input cin,
    output [3:0] s,
    output cout
);

    wire [3:0] sum;
    wire cout0, cout1, cout2;

    // full adder for least significant bit
    full_adder fa0(
        .a(a[0]),
        .b(b[0]),
        .cin(cin),
        .s(sum[0]),
        .cout(cout0)
    );

    // full adder for second least significant bit
    full_adder fa1(
        .a(a[1]),
        .b(b[1]),
        .cin(cout0),
        .s(sum[1]),
        .cout(cout1)
    );

    // full adder for third least significant bit
    full_adder fa2(
        .a(a[2]),
        .b(b[2]),
        .cin(cout1),
        .s(sum[2]),
        .cout(cout2)
    );

    // full adder for most significant bit
    full_adder fa3(
        .a(a[3]),
        .b(b[3]),
        .cin(cout2),
        .s(sum[3]),
        .cout(cout)
    );

    assign s = sum;

endmodule
module full_adder(
    input a,
    input b,
    input cin,
    output s,
    output cout
);

    wire sum1, sum2, sum3;

    // XOR gates to calculate sum
    assign sum1 = a ^ b;
    assign s = sum1 ^ cin;

    // AND gates to calculate carry out
    assign sum2 = a & b;
    assign sum3 = cin & sum1;
    assign cout = sum2 | sum3;

endmodule

sva:
module four_bit_adder_sva (
    input  logic CLK,
    input  logic RESETn,
    input  logic [3:0] a,
    input  logic [3:0] b,
    input  logic       cin,
    input  logic [3:0] s,
    input  logic       cout
);

    ///// Functional correctness /////
    // Combined {cout,s} equals the 5 LSBs of a+b+cin (pure combinational adder correctness).
    check_arith_sum_5lsb: assert property (
        @(posedge CLK) disable iff (!RESETn)
            {cout, s} == (a + b + cin)[4:0]
    );

    // LSB sum bit is XOR of a[0], b[0], and cin.
    check_sum_bit0_xor: assert property (
        @(posedge CLK) disable iff (!RESETn)
            s[0] == (a[0] ^ b[0] ^ cin)
    );

    // s[1] is XOR of a[1], b[1], and carry from bit0.
    check_sum_bit1_with_c0: assert property (
        @(posedge CLK) disable iff (!RESETn)
            s[1] == (a[1] ^ b[1] ^ ( (a[0] & b[0]) | (cin & (a[0] ^ b[0])) ))
    );

    // s[2] is XOR of a[2], b[2], and carry from bit1.
    check_sum_bit2_with_c1: assert property (
        @(posedge CLK) disable iff (!RESETn)
            s[2] == (a[2] ^ b[2] ^ (
                        (a[1] & b[1]) |
                        ( ((a[0] & b[0]) | (cin & (a[0] ^ b[0]))) & (a[1] ^ b[1]) )
                    ))
    );

    // s[3] is XOR of a[3], b[3], and carry from bit2.
    check_sum_bit3_with_c2: assert property (
        @(posedge CLK) disable iff (!RESETn)
            s[3] == (a[3] ^ b[3] ^ (
                        (a[2] & b[2]) |
                        ( ( (a[1] & b[1]) |
                            ( ((a[0] & b[0]) | (cin & (a[0] ^ b[0]))) & (a[1] ^ b[1]) )
                          ) & (a[2] ^ b[2]) )
                    ))
    );

    // cout equals carry from bit3 (ripple of generated/propagated carries).
    check_cout_from_c3: assert property (
        @(posedge CLK) disable iff (!RESETn)
            cout == (
                (a[3] & b[3]) |
                ( (
                    (a[2] & b[2]) |
                    ( ( (a[1] & b[1]) |
                        ( ((a[0] & b[0]) | (cin & (a[0] ^ b[0]))) & (a[1] ^ b[1]) )
                      ) & (a[2] ^ b[2]) )
                  ) & (a[3] ^ b[3]) )
            )
    );

    // cout is high iff a+b+cin exceeds 4'hF (overflow of 4-bit sum).
    check_cout_overflow_flag: assert property (
        @(posedge CLK) disable iff (!RESETn)
            cout == ((a + b + cin) > 4'hF)
    );

    ///// Simple corner cases /////
    // With a=0 and b=0, s equals cin in bit0 and zeros elsewhere; cout is 0.
    check_zero_inputs_passthrough_cin: assert property (
        @(posedge CLK) disable iff (!RESETn)
            ((a == 4'b0000) && (b == 4'b0000)) |->
                (s == {3'b000, cin}) && (cout == 1'b0)
    );

    // With a=0 and cin=0, s equals b and cout is 0.
    check_add_b_when_a_zero_cin_zero: assert property (
        @(posedge CLK) disable iff (!RESETn)
            ((a == 4'b0000) && (cin == 1'b0)) |->
                (s == b) && (cout == 1'b0)
    );

endmodule

rtl:
module gray_converter (
    input [3:0] binary_in,
    input gray_ctrl,
    input rst_n,
    output reg [3:0] gray_out
);

reg [3:0] binary_reg1, binary_reg2;
reg [3:0] gray_reg1, gray_reg2;

always @(posedge rst_n) begin
    if(~rst_n) begin
        binary_reg1 <= 4'b0000;
        binary_reg2 <= 4'b0000;
        gray_reg1 <= 4'b0000;
        gray_reg2 <= 4'b0000;
    end else begin
        binary_reg1 <= binary_in;
        binary_reg2 <= binary_reg1;
        gray_reg1 <= gray_out;
        gray_reg2 <= gray_reg1;
    end
end

always @(posedge gray_ctrl) begin
    if(gray_ctrl == 1'b0) begin
        gray_out <= binary_reg1 ^ binary_reg2;
    end else begin
        gray_out <= gray_reg1 ^ {gray_reg2[2:0], 1'b0}; // right shift
    end
end

endmodule

sva:
module gray_converter_sva (
    input logic [3:0] binary_in,
    input logic       gray_ctrl,
    input logic       rst_n,
    input logic [3:0] gray_out
);
    // Clocks: posedge rst_n and posedge gray_ctrl. Reset is active-low (disable iff !rst_n). Logic is sequential.

    ///// rst_n-posedge pipeline updates /////
    // Next rst_n posedge: binary_reg1 captures previous binary_in.
    check_binary_reg1_captures_binary_in_on_rstn: assert property (
        @(posedge rst_n) disable iff (!rst_n)
            1'b1 |=> (binary_reg1 == $past(binary_in))
    );

    // Next rst_n posedge: binary_reg2 captures previous binary_reg1.
    check_binary_reg2_captures_binary_reg1_on_rstn: assert property (
        @(posedge rst_n) disable iff (!rst_n)
            1'b1 |=> (binary_reg2 == $past(binary_reg1))
    );

    // Next rst_n posedge: gray_reg1 captures previous gray_out.
    check_gray_reg1_captures_gray_out_on_rstn: assert property (
        @(posedge rst_n) disable iff (!rst_n)
            1'b1 |=> (gray_reg1 == $past(gray_out))
    );

    // Next rst_n posedge: gray_reg2 captures previous gray_reg1.
    check_gray_reg2_captures_gray_reg1_on_rstn: assert property (
        @(posedge rst_n) disable iff (!rst_n)
            1'b1 |=> (gray_reg2 == $past(gray_reg1))
    );

    ///// gray_ctrl-posedge gray_out update /////
    // Next gray_ctrl posedge: gray_out = prev(gray_reg1) XOR (prev(gray_reg2) << 1).
    check_gray_out_update_on_gray_ctrl: assert property (
        @(posedge gray_ctrl) disable iff (!rst_n)
            1'b1 |=> (gray_out == ($past(gray_reg1) ^ { $past(gray_reg2)[2:0], 1'b0 }))
    );

    // Next gray_ctrl posedge: gray_out[0] equals prev(gray_reg1[0]).
    check_gray_out_bit0_on_gray_ctrl: assert property (
        @(posedge gray_ctrl) disable iff (!rst_n)
            1'b1 |=> (gray_out[0] == $past(gray_reg1[0]))
    );

    // Next gray_ctrl posedge: gray_out[1] equals prev(gray_reg1[1]) XOR prev(gray_reg2[0]).
    check_gray_out_bit1_on_gray_ctrl: assert property (
        @(posedge gray_ctrl) disable iff (!rst_n)
            1'b1 |=> (gray_out[1] == ($past(gray_reg1[1]) ^ $past(gray_reg2[0])))
    );

    // Next gray_ctrl posedge: gray_out[2] equals prev(gray_reg1[2]) XOR prev(gray_reg2[1]).
    check_gray_out_bit2_on_gray_ctrl: assert property (
        @(posedge gray_ctrl) disable iff (!rst_n)
            1'b1 |=> (gray_out[2] == ($past(gray_reg1[2]) ^ $past(gray_reg2[1])))
    );

    // Next gray_ctrl posedge: gray_out[3] equals prev(gray_reg1[3]) XOR prev(gray_reg2[2]).
    check_gray_out_bit3_on_gray_ctrl: assert property (
        @(posedge gray_ctrl) disable iff (!rst_n)
            1'b1 |=> (gray_out[3] == ($past(gray_reg1[3]) ^ $past(gray_reg2[2])))
    );

endmodule

rtl:
module niosII_system_nios2_qsys_0_nios2_oci_dbrk (
    // inputs:
    E_st_data,
    av_ld_data_aligned_filtered,
    clk,
    d_address,
    d_read,
    d_waitrequest,
    d_write,
    debugack,
    reset_n,

    // outputs:
    cpu_d_address,
    cpu_d_read,
    cpu_d_readdata,
    cpu_d_wait,
    cpu_d_write,
    cpu_d_writedata,
    dbrk_break,
    dbrk_goto0,
    dbrk_goto1,
    dbrk_traceme,
    dbrk_traceoff,
    dbrk_traceon,
    dbrk_trigout
);

    input [31:0] E_st_data;
    input [31:0] av_ld_data_aligned_filtered;
    input clk;
    input [24:0] d_address;
    input d_read;
    input d_waitrequest;
    input d_write;
    input debugack;
    input reset_n;
    output [24:0] cpu_d_address;
    output cpu_d_read;
    output [31:0] cpu_d_readdata;
    output cpu_d_wait;
    output cpu_d_write;
    output [31:0] cpu_d_writedata;
    output dbrk_break;
    output dbrk_goto0;
    output dbrk_goto1;
    output dbrk_traceme;
    output dbrk_traceoff;
    output dbrk_traceon;
    output dbrk_trigout;

    reg [31:0] cpu_d_writedata_reg;
    reg [24:0] cpu_d_address_reg;
    reg cpu_d_read_reg;
    reg [31:0] cpu_d_readdata_reg;
    reg cpu_d_wait_reg;
    reg cpu_d_write_reg;
    reg dbrk_break_reg;
    reg dbrk_goto0_reg;
    reg dbrk_goto1_reg;
    reg dbrk_traceme_reg;
    reg dbrk_traceoff_reg;
    reg dbrk_traceon_reg;
    reg dbrk_trigout_reg;

    wire [31:0] dbrk_data;
    assign dbrk_data = cpu_d_write_reg ? cpu_d_writedata_reg : cpu_d_readdata_reg;

    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            cpu_d_writedata_reg <= 0;
            cpu_d_address_reg <= 0;
            cpu_d_read_reg <= 0;
            cpu_d_readdata_reg <= 0;
            cpu_d_wait_reg <= 0;
            cpu_d_write_reg <= 0;
            dbrk_break_reg <= 0;
            dbrk_goto0_reg <= 0;
            dbrk_goto1_reg <= 0;
            dbrk_traceme_reg <= 0;
            dbrk_traceoff_reg <= 0;
            dbrk_traceon_reg <= 0;
            dbrk_trigout_reg <= 0;
        end else begin
            cpu_d_writedata_reg <= d_write ? E_st_data : av_ld_data_aligned_filtered;
            cpu_d_address_reg <= d_write ? d_address : 0;
            cpu_d_read_reg <= d_write ? 0 : d_read;
            cpu_d_readdata_reg <= d_read ? av_ld_data_aligned_filtered : 0;
            cpu_d_wait_reg <= d_waitrequest;
            cpu_d_write_reg <= d_write;
            dbrk_break_reg <= !debugack ? ~dbrk_break_reg : dbrk_break_reg;
            dbrk_goto0_reg <= 0;
            dbrk_goto1_reg <= 0;
            dbrk_traceme_reg <= 0;
            dbrk_traceoff_reg <= 0;
            dbrk_traceon_reg <= 0;
            dbrk_trigout_reg <= 0;
        end
    end

    assign cpu_d_writedata = cpu_d_writedata_reg;
    assign cpu_d_address = cpu_d_address_reg;
    assign cpu_d_read = cpu_d_read_reg;
