module mult16_16
   (CLK,
    A,
    B,
    CE,
    SCLR,
    ZERO_DETECT,
    P,
    PCASC);
  input CLK;
  input [15:0]A;
  input [15:0]B;
  input CE;
  input SCLR;
  output [1:0]ZERO_DETECT;
  output [7:0]P;
  output [47:0]PCASC;

  wire [31:0]mult_result;
  wire [55:0]mult_result_extended;
  wire [63:0]mult_result_extended_zero_detect;

  assign mult_result = A * B;
  assign mult_result_extended = {8'b0, mult_result};
  assign mult_result_extended_zero_detect = {2'b0, mult_result_extended};

  assign P = mult_result[7:0];
  assign PCASC = mult_result_extended[47:0];
  assign ZERO_DETECT = (mult_result_extended_zero_detect == 0) ? 2'b11 : ((mult_result_extended_zero_detect[55:8] == 0) ? 2'b10 : 2'b01);

endmodule

sva:
module mult16_16_sva (
    input logic CLK,
    input logic [15:0] A,
    input logic [15:0] B,
    input logic CE,
    input logic SCLR,
    input logic [1:0] ZERO_DETECT,
    input logic [7:0] P,
    input logic [47:0] PCASC
);
    // P equals the low 8 bits of A*B.
    check_p_low8_of_product: assert property (
        @(posedge CLK) P == (A * B)[7:0]
    );

    // PCASC equals {16'h0, A*B}.
    check_pcasc_matches_product: assert property (
        @(posedge CLK) PCASC == {16'h0000, (A * B)}
    );

    // Upper 16 bits of PCASC are zero.
    check_pcasc_upper16_zero: assert property (
        @(posedge CLK) PCASC[47:32] == 16'h0000
    );

    // P equals the low byte of PCASC.
    check_p_equals_pcasc_low8: assert property (
        @(posedge CLK) P == PCASC[7:0]
    );

    // ZERO_DETECT is 2'b11 when product is zero.
    check_zero_detect_zero_case: assert property (
        @(posedge CLK) ((A * B) == 32'd0) |-> (ZERO_DETECT == 2'b11)
    );

    // ZERO_DETECT is 2'b10 when product is nonzero and fits in 8 bits.
    check_zero_detect_low8_case: assert property (
        @(posedge CLK) (((A * B) != 32'd0) && (((A * B)[31:8]) == 24'd0)) |-> (ZERO_DETECT == 2'b10)
    );

    // ZERO_DETECT is 2'b01 when product exceeds 8 bits.
    check_zero_detect_high_case: assert property (
        @(posedge CLK) (((A * B)[31:8]) != 24'd0) |-> (ZERO_DETECT == 2'b01)
    );

    // ZERO_DETECT never takes value 2'b00.
    check_zero_detect_no_00: assert property (
        @(posedge CLK) ZERO_DETECT != 2'b00
    );

    // ZERO_DETECT[1] indicates product fits in 8 bits.
    check_zero_detect_bit1: assert property (
        @(posedge CLK) ZERO_DETECT[1] == (((A * B)[31:8]) == 24'd0)
    );

    // ZERO_DETECT[0] is 1 if product is zero or exceeds 8 bits.
    check_zero_detect_bit0: assert property (
        @(posedge CLK) ZERO_DETECT[0] == ( ((A * B) == 32'd0) || (((A * B)[31:8]) != 24'd0) )
    );

    // Outputs remain stable when A and B are stable.
    check_outputs_stable_when_inputs_stable: assert property (
        @(posedge CLK) ($stable(A) && $stable(B)) |-> $stable({P, PCASC, ZERO_DETECT})
    );

    // Zero operand drives zero outputs and ZERO_DETECT==2'b11.
    check_zero_operand_zero_outputs: assert property (
        @(posedge CLK) ((A == 16'd0) || (B == 16'd0)) |-> ((P == 8'd0) && (PCASC == 48'd0) && (ZERO_DETECT == 2'b11))
    );
endmodule

rtl:
module wb_mux(
    // Clock and reset
    clk, rst,

    // Internal i/f
    wb_freeze, rfwb_op,
    muxin_a, muxin_b, muxin_c, muxin_d,
    muxout, muxreg, muxreg_valid
);

parameter width = 32;


input               clk;
input               rst;

input               wb_freeze;
input   [2:0]       rfwb_op;
input   [width-1:0] muxin_a;
input   [width-1:0] muxin_b;
input   [width-1:0] muxin_c;
input   [width-1:0] muxin_d;
output  [width-1:0] muxout;
output  [width-1:0] muxreg;
output              muxreg_valid;

reg [width-1:0] muxout;
reg [width-1:0] muxreg;
reg muxreg_valid;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        muxreg <= 32'd0;
        muxreg_valid <= 1'b0;
    end
    else if (!wb_freeze) begin
        muxreg <= muxout;
        muxreg_valid <= rfwb_op[0];
    end
end

always @(*) begin
    case(rfwb_op[2:1])
        2'b00: muxout = muxin_a;
        2'b01: muxout = muxin_b;
        2'b10: muxout = muxin_c;
        2'b11: muxout = muxin_d + 32'h8;
    endcase
end

endmodule

sva:
module wb_mux_sva #(
    parameter int width = 32
)(
    input  logic               clk,
    input  logic               rst,
    input  logic               wb_freeze,
    input  logic [2:0]         rfwb_op,
    input  logic [width-1:0]   muxin_a,
    input  logic [width-1:0]   muxin_b,
    input  logic [width-1:0]   muxin_c,
    input  logic [width-1:0]   muxin_d,
    input  logic [width-1:0]   muxout,
    input  logic [width-1:0]   muxreg,
    input  logic               muxreg_valid
);

    ///// Reset behavior /////
    // During reset, muxreg and muxreg_valid are driven to zero.
    reset_drives_regs_zero: assert property (
        @(posedge clk) rst |-> (muxreg == '0) && (muxreg_valid == 1'b0)
    );

    ///// Freeze behavior /////
    // When wb_freeze is HIGH, muxreg holds its previous value.
    freeze_holds_muxreg: assert property (
        @(posedge clk) disable iff (rst) (wb_freeze && $past(!rst)) |=> (muxreg == $past(muxreg))
    );
    // When wb_freeze is HIGH, muxreg_valid holds its previous value.
    freeze_holds_muxreg_valid: assert property (
        @(posedge clk) disable iff (rst) (wb_freeze && $past(!rst)) |=> (muxreg_valid == $past(muxreg_valid))
    );

    ///// Sequential capture when not frozen /////
    // When not frozen, muxreg captures muxout on the next clock.
    capture_muxout_when_not_frozen: assert property (
        @(posedge clk) disable iff (rst) (!wb_freeze && $past(!rst)) |=> (muxreg == $past(muxout))
    );
    // When not frozen, muxreg_valid captures rfwb_op[0] on the next clock.
    capture_valid_when_not_frozen: assert property (
        @(posedge clk) disable iff (rst) (!wb_freeze && $past(!rst)) |=> (muxreg_valid == $past(rfwb_op[0]))
    );

    ///// Combinational muxout selection /////
    // rfwb_op[2:1]==00 selects muxin_a.
    muxout_select_a: assert property (
        @(posedge clk) disable iff (rst) (rfwb_op[2:1] == 2'b00) |-> (muxout == muxin_a)
    );
    // rfwb_op[2:1]==01 selects muxin_b.
    muxout_select_b: assert property (
        @(posedge clk) disable iff (rst) (rfwb_op[2:1] == 2'b01) |-> (muxout == muxin_b)
    );
    // rfwb_op[2:1]==10 selects muxin_c.
    muxout_select_c: assert property (
        @(posedge clk) disable iff (rst) (rfwb_op[2:1] == 2'b10) |-> (muxout == muxin_c)
    );
    // rfwb_op[2:1]==11 selects muxin_d + 8.
    muxout_select_d_plus8: assert property (
        @(posedge clk) disable iff (rst) (rfwb_op[2:1] == 2'b11) |-> (muxout == (muxin_d + 32'h8))
    );

    ///// End-to-end capture for d+8 path /////
    // When not frozen and selecting d+8, muxreg captures muxin_d+8 on the next clock.
    capture_d_plus8_on_unfreeze: assert property (
        @(posedge clk) disable iff (rst) (!wb_freeze && (rfwb_op[2:1] == 2'b11) && $past(!rst)) |=> (muxreg == $past(muxin_d + 32'h8))
    );

endmodule

rtl:
module IBUFCTRL (
  input I,
  input IBUFDISABLE,
  input T,
  output O
);

  assign O = IBUFDISABLE ? (T ? 1'b0 : 1'b1) : I;

endmodule

sva:
module IBUFCTRL_sva (
  input logic I,
  input logic IBUFDISABLE,
  input logic T,
  input logic O
);
  // No clock/reset in RTL; sample on any input edge.

  // O must equal the RTL combinational equation.
  check_mux_equation: assert property (
    @(posedge I or negedge I or posedge IBUFDISABLE or negedge IBUFDISABLE or posedge T or negedge T)
      O == (IBUFDISABLE ? (T ? 1'b0 : 1'b1) : I)
  );

  // When enabled (IBUFDISABLE==0), O follows I.
  check_enabled_path: assert property (
    @(posedge I or negedge I or posedge IBUFDISABLE or negedge IBUFDISABLE or posedge T or negedge T)
      (IBUFDISABLE == 1'b0) |-> (O == I)
  );

  // When disabled (IBUFDISABLE==1), O equals ~T.
  check_disabled_inverts_T: assert property (
    @(posedge I or negedge I or posedge IBUFDISABLE or negedge IBUFDISABLE or posedge T or negedge T)
      (IBUFDISABLE == 1'b1) |-> (O == ~T)
  );

  // Disabled and T=1 forces O=0.
  check_disabled_T1_drives_0: assert property (
    @(posedge I or negedge I or posedge IBUFDISABLE or negedge IBUFDISABLE or posedge T or negedge T)
      (IBUFDISABLE && T) |-> (O == 1'b0)
  );

  // Disabled and T=0 forces O=1.
  check_disabled_T0_drives_1: assert property (
    @(posedge I or negedge I or posedge IBUFDISABLE or negedge IBUFDISABLE or posedge T or negedge T)
      (IBUFDISABLE && !T) |-> (O == 1'b1)
  );
endmodule

rtl:
module binary_counter (
  input clk,
  input reset,
  output reg [2:0] count,
  output reg enable
);

  always @(posedge clk) begin
    if (reset) begin
      count <= 3'b000;
      enable <= 1'b0;
    end
    else begin
      if (count == 3'b101) begin
        count <= 3'b000;
        enable <= 1'b1;
      end
      else begin
        count <= count + 1;
        enable <= 1'b0;
      end
    end
  end

endmodule

sva:
module binary_counter_sva (
  input logic clk,
  input logic reset,
  input logic [2:0] count,
  input logic enable
);

  // On reset, next cycle drives count=0 and enable=0.
  reset_next_outputs_zero: assert property (
    @(posedge clk) reset |=> (count == 3'b000) && (enable == 1'b0)
  );

  // From count=0, next is 1 and enable=0.
  next_from_0: assert property (
    @(posedge clk) disable iff (reset) (count == 3'b000) |=> (count == 3'b001) && (enable == 1'b0)
  );

  // From count=1, next is 2 and enable=0.
  next_from_1: assert property (
    @(posedge clk) disable iff (reset) (count == 3'b001) |=> (count == 3'b010) && (enable == 1'b0)
  );

  // From count=2, next is 3 and enable=0.
  next_from_2: assert property (
    @(posedge clk) disable iff (reset) (count == 3'b010) |=> (count == 3'b011) && (enable == 1'b0)
  );

  // From count=3, next is 4 and enable=0.
  next_from_3: assert property (
    @(posedge clk) disable iff (reset) (count == 3'b011) |=> (count == 3'b100) && (enable == 1'b0)
  );

  // From count=4, next is 5 and enable=0.
  next_from_4: assert property (
    @(posedge clk) disable iff (reset) (count == 3'b100) |=> (count == 3'b101) && (enable == 1'b0)
  );

  // From count=5, next is 0 and enable=1.
  next_from_5: assert property (
    @(posedge clk) disable iff (reset) (count == 3'b101) |=> (count == 3'b000) && (enable == 1'b1)
  );

  // From count=6, next is 7 and enable=0.
  next_from_6: assert property (
    @(posedge clk) disable iff (reset) (count == 3'b110) |=> (count == 3'b111) && (enable == 1'b0)
  );

  // From count=7, next is 0 and enable=0.
  next_from_7: assert property (
    @(posedge clk) disable iff (reset) (count == 3'b111) |=> (count == 3'b000) && (enable == 1'b0)
  );

  // Enable is a single-cycle pulse.
  enable_one_cycle_pulse: assert property (
    @(posedge clk) disable iff (reset) (enable == 1'b1) |=> (enable == 1'b0)
  );

  // When enable is 1, the count in that cycle is 0.
  enable_implies_count_zero: assert property (
    @(posedge clk) disable iff (reset) (enable == 1'b1) |-> (count == 3'b000)
  );

  // While count is 5, enable is 0 in that same cycle.
  count5_implies_enable_zero: assert property (
    @(posedge clk) disable iff (reset) (count == 3'b101) |-> (enable == 1'b0)
  );

endmodule

module data_comp_decomp_sva (
    input logic CLK,          // sampling clock for SVA (DUT is combinational)
    input logic [7:0] data_in,
    input logic [3:0] data_out,
    input logic       valid
);
    // Analysis: no clock/reset in DUT; purely combinational; maps 4 encodings, else invalid.

    // data_in == 8'h01 maps to data_out == 4'h1 with valid == 1
    check_map_sym1: assert property (
        @(posedge CLK) (data_in == 8'h01) |-> ((data_out == 4'h1) && (valid == 1'b1))
    );

    // data_in == 8'h02 maps to data_out == 4'h2 with valid == 1
    check_map_sym2: assert property (
        @(posedge CLK) (data_in == 8'h02) |-> ((data_out == 4'h2) && (valid == 1'b1))
    );

    // data_in == 8'h04 maps to data_out == 4'h3 with valid == 1
    check_map_sym3: assert property (
        @(posedge CLK) (data_in == 8'h04) |-> ((data_out == 4'h3) && (valid == 1'b1))
    );

    // data_in == 8'h08 maps to data_out == 4'h4 with valid == 1
    check_map_sym4: assert property (
        @(posedge CLK) (data_in == 8'h08) |-> ((data_out == 4'h4) && (valid == 1'b1))
    );

    // For all other data_in values, data_out == 0 and valid == 0
    check_default_map: assert property (
        @(posedge CLK) !(data_in inside {8'h01,8'h02,8'h04,8'h08}) |-> ((data_out == 4'h0) && (valid == 1'b0))
    );

    // valid == 1 occurs only for recognized inputs
    check_valid_high_implies_recognized: assert property (
        @(posedge CLK) (valid == 1'b1) |-> (data_in inside {8'h01,8'h02,8'h04,8'h08})
    );

    // Recognized inputs always produce valid == 1
    check_recognized_implies_valid_high: assert property (
        @(posedge CLK) (data_in inside {8'h01,8'h02,8'h04,8'h08}) |-> (valid == 1'b1)
    );

    // valid == 0 implies data_out == 0
    check_valid_low_implies_zero: assert property (
        @(posedge CLK) (valid == 1'b0) |-> (data_out == 4'h0)
    );

    // data_out == 0 implies valid == 0
    check_zero_implies_valid_low: assert property (
        @(posedge CLK) (data_out == 4'h0) |-> (valid == 1'b0)
    );

    // Non-zero data_out implies recognized input and valid == 1
    check_nonzero_out_implies_recognized_and_valid: assert property (
        @(posedge CLK) (data_out != 4'h0) |-> ((data_in inside {8'h01,8'h02,8'h04,8'h08}) && (valid == 1'b1))
    );

    // valid == 1 implies data_out is one of 4'h1..4'h4
    check_valid_high_implies_known_code: assert property (
        @(posedge CLK) (valid == 1'b1) |-> (data_out inside {4'h1,4'h2,4'h3,4'h4})
    );
endmodule

rtl:
module comparator_4bit(
    input [3:0] A,
    input [3:0] B,
    output EQ,
    output GT
    );

    assign EQ = (A == B);
    assign GT = (A > B);

endmodule

sva:
module comparator_4bit_sva (
    input logic CLK,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic EQ,
    input logic GT
);
    // EQ must reflect (A == B).
    check_eq_definition: assert property (
        @(posedge CLK) (EQ === (A == B))
    );

    // GT must reflect (A > B).
    check_gt_definition: assert property (
        @(posedge CLK) (GT === (A > B))
    );

    // EQ and GT cannot be high at the same time.
    check_outputs_mutex: assert property (
        @(posedge CLK) !((EQ === 1'b1) && (GT === 1'b1))
    );

    // When A == B, outputs must be EQ=1 and GT=0.
    check_equal_case_outputs: assert property (
        @(posedge CLK) (A == B) |-> ((EQ === 1'b1) && (GT === 1'b0))
    );

    // When A > B, outputs must be GT=1 and EQ=0.
    check_greater_case_outputs: assert property (
        @(posedge CLK) (A > B) |-> ((GT === 1'b1) && (EQ === 1'b0))
    );

    // When A < B, outputs must be EQ=0 and GT=0.
    check_less_case_outputs: assert property (
        @(posedge CLK) (A < B) |-> ((EQ === 1'b0) && (GT === 1'b0))
    );

    // If EQ is asserted, inputs must be equal.
    check_eq_high_implies_inputs_equal: assert property (
        @(posedge CLK) (EQ === 1'b1) |-> (A == B)
    );

    // If GT is asserted, A must be greater than B.
    check_gt_high_implies_a_greater: assert property (
        @(posedge CLK) (GT === 1'b1) |-> (A > B)
    );
endmodule

rtl:
module counter(
  input clk,
  input reset,
  input [31:0] max_value,
  output reg [31:0] count
);

  always @(posedge clk) begin
    if (reset) begin
      count <= 0;
    end else if (count == max_value) begin
      count <= 0;
    end else begin
      count <= count + 1;
    end
  end

endmodule

sva:
module counter_sva (
    input logic clk,
    input logic reset,           // active-high synchronous reset
    input logic [31:0] max_value,
    input logic [31:0] count
);
    // On any cycle with reset asserted, count must be 0 on the next cycle.
    reset_clears_count_next: assert property (
        @(posedge clk) reset |=> (count == 32'd0)
    );

    // If reset was 1 in the previous cycle, count must be 0 now.
    prev_reset_forces_zero_now: assert property (
        @(posedge clk) $past(reset) |-> (count == 32'd0)
    );

    // When not in reset, reaching max_value causes wrap to 0 on the next cycle.
    wrap_on_reaching_max: assert property (
        @(posedge clk) disable iff (reset) (count == max_value) |=> (count == 32'd0)
    );

    // When not in reset and below max_value, next cycle increments unless reset arrives.
    increment_when_below_max: assert property (
        @(posedge clk) disable iff (reset) (count != max_value) |=> (reset || (count == $past(count) + 32'd1))
    );

    // When not in reset and max_value==0 at 0, the counter holds at 0.
    hold_zero_when_max_zero: assert property (
        @(posedge clk) disable iff (reset) (count == 32'd0 && max_value == 32'd0) |=> (count == 32'd0)
    );

    // With reset low in consecutive cycles, next-state follows exact update rule (wrap or increment).
    precise_update_no_reset: assert property (
        @(posedge clk) (!$past(reset) && !reset) |-> (
            (count == 32'd0 && $past(count) == $past(max_value)) ||
            (count == $past(count) + 32'd1 && $past(count) != $past(max_value))
        )
    );

    // One-below-max steps to max on the next cycle when not reset (or is 0 if reset).
    step_to_max_from_one_below: assert property (
        @(posedge clk) disable iff (reset) ((count + 32'd1) == max_value && (count != max_value)) |=> (reset || (count == max_value))
    );
endmodule

rtl:
module Comparador(clock, reset, write_value, read_value, 
	read_value_reg_en, led_success, led_fail);

	input clock, reset, read_value_reg_en;
	input [3:0] write_value, read_value;
	output led_success, led_fail;

	reg [3:0] read_value_reg;

	assign led_success = (write_value == read_value_reg);
	assign led_fail = ~led_success;

	always @( posedge clock or posedge reset)
		begin
			if(reset)
				begin
					read_value_reg <= 4'b0;
				end
			else if (read_value_reg_en)
				begin
					read_value_reg <= read_value;
				end
		end

endmodule

sva:
module Comparador_sva (
    input logic clock,
    input logic reset,
    input logic [3:0] write_value,
    input logic [3:0] read_value,
    input logic read_value_reg_en,
    input logic led_success,
    input logic led_fail,
    // Internal signal from RTL (bind or connect hierarchically)
    input logic [3:0] read_value_reg
);
    // Clock: clock (posedge). Reset: reset (active-high, async). Mixed logic: reg + combinational compares.

    ///// Register behavior /////
    // While reset is asserted, read_value_reg is held at 0.
    reset_clears_reg: assert property (
        @(posedge clock) reset |-> (read_value_reg == 4'b0000)
    );
    // When enabled, next cycle read_value_reg updates from read_value.
    load_on_enable: assert property (
        @(posedge clock) disable iff (reset) read_value_reg_en |=> (read_value_reg == $past(read_value))
    );
    // If enable stays LOW across two cycles, the register holds its value.
    hold_when_enable_stays_low: assert property (
        @(posedge clock) disable iff (reset) (!read_value_reg_en ##1 !read_value_reg_en) |-> (read_value_reg == $past(read_value_reg,1))
    );

    ///// LED definitions /////
    // led_fail is always the logical inverse of led_success.
    led_fail_is_invert_success: assert property (
        @(posedge clock) disable iff (reset) (led_fail == ~led_success)
    );
    // led_success reflects write_value == read_value_reg.
    led_success_matches_compare: assert property (
        @(posedge clock) disable iff (reset) (led_success == (write_value == read_value_reg))
    );
    // During reset (read_value_reg forced to 0), LEDs reflect compare against zero.
    leds_match_zero_during_reset: assert property (
        @(posedge clock) reset |-> (led_success == (write_value == 4'b0000)) && (led_fail == ~(write_value == 4'b0000))
    );
    // Exactly one of the LEDs is HIGH (mutual exclusion and completeness).
    leds_one_hot: assert property (
        @(posedge clock) disable iff (reset) (led_success ^ led_fail)
    );

    ///// LED response to register update /////
    // After an enabled load, next-cycle led_success matches write_value vs prior-cycle read_value.
    led_success_updates_after_enable: assert property (
        @(posedge clock) disable iff (reset) read_value_reg_en |=> (led_success == (write_value == $past(read_value)))
    );
    // If enable stays LOW and write_value is stable across two cycles, LEDs remain stable.
    leds_stable_when_inputs_stable: assert property (
        @(posedge clock) disable iff (reset)
            ((!read_value_reg_en && $stable(write_value)) ##1 (!read_value_reg_en && $stable(write_value)))
            |-> (led_success == $past(led_success,1)) && (led_fail == $past(led_fail,1))
    );

endmodule

rtl:
module sky130_fd_sc_ls__and3 (
    X,
    A,
    B,
    C
);

    output X;
    input  A;
    input  B;
    input  C;

    wire and0_out_X;

    and and0 (and0_out_X, C, A, B        );
    buf buf0 (X         , and0_out_X     );

endmodule

sva:
module sky130_fd_sc_ls__and3_sva (
    input logic CLK,
    input logic X,
    input logic A,
    input logic B,
    input logic C
);
    // Output equals logical AND of inputs.
    check_functional_and: assert property (
        @(posedge CLK) disable iff (1'b0) X == (A & B & C)
    );

    // X HIGH implies all inputs HIGH.
    check_x_high_implies_inputs_high: assert property (
        @(posedge CLK) disable iff (1'b0) X |-> (A && B && C)
    );

    // All inputs HIGH implies X HIGH.
    check_all_inputs_high_implies_x_high: assert property (
        @(posedge CLK) disable iff (1'b0) (A && B && C) |-> X
    );

    // !A forces X LOW.
    check_low_a_forces_x_low: assert property (
        @(posedge CLK) disable iff (1'b0) (!A) |-> (!X)
    );

    // !B forces X LOW.
    check_low_b_forces_x_low: assert property (
        @(posedge CLK) disable iff (1'b0) (!B) |-> (!X)
    );

    // !C forces X LOW.
    check_low_c_forces_x_low: assert property (
        @(posedge CLK) disable iff (1'b0) (!C) |-> (!X)
    );

    // With B&C HIGH, X equals A.
    check_bc_high_gates_a_to_x: assert property (
        @(posedge CLK) disable iff (1'b0) (B && C) |-> (X == A)
    );

    // With A&C HIGH, X equals B.
    check_ac_high_gates_b_to_x: assert property (
        @(posedge CLK) disable iff (1'b0) (A && C) |-> (X == B)
    );

    // With A&B HIGH, X equals C.
    check_ab_high_gates_c_to_x: assert property (
        @(posedge CLK) disable iff (1'b0) (A && B) |-> (X == C)
    );

    // X can only rise if at least one input rises.
    check_x_rise_requires_input_rise: assert property (
        @(posedge CLK) disable iff (1'b0) $rose(X) |-> ($rose(A) || $rose(B) || $rose(C))
    );

    // X can only fall if at least one input falls.
    check_x_fall_requires_input_fall: assert property (
        @(posedge CLK) disable iff (1'b0) $fell(X) |-> ($fell(A) || $fell(B) || $fell(C))
    );

    // If all inputs are stable, X is stable.
    check_stable_inputs_imply_stable_x: assert property (
        @(posedge CLK) disable iff (1'b0) ($stable(A) && $stable(B) && $stable(C)) |-> $stable(X)
    );
endmodule

module counter_sva (
    input logic clk,
    input logic rst,
    input logic [3:0] count
);
    // Clock: clk (posedge). Reset: rst (synchronous, active-high). Behavior: 4-bit up-counter with wrap at 15 to 0.

    // Reset drives count to 0 on the next cycle.
    check_reset_clears_next: assert property (
        @(posedge clk) rst |=> (count == 4'h0)
    );

    // While reset is held across cycles, count is 0.
    check_hold_zero_while_reset: assert property (
        @(posedge clk) (rst && $past(rst)) |-> (count == 4'h0)
    );

    // On reset deassertion (1->0), current cycle's count is 0.
    check_count_zero_on_reset_fall: assert property (
        @(posedge clk) $fell(rst) |-> (count == 4'h0)
    );

    // One cycle after reset deasserts, count becomes 1.
    check_count_one_after_reset_release: assert property (
        @(posedge clk) $fell(rst) |=> (count == 4'd1)
    );

    // If previous cycle was not in reset and count was not max, it increments by 1.
    check_increment_when_prev_not_max: assert property (
        @(posedge clk) disable iff (rst) (!$past(rst) && ($past(count) != 4'hF)) |-> (count == ($past(count) + 4'd1))
    );

    // If previous cycle was not in reset and count was max, it wraps to 0.
    check_wrap_when_prev_max: assert property (
        @(posedge clk) disable iff (rst) (!$past(rst) && ($past(count) == 4'hF)) |-> (count == 4'h0)
    );

    // If previous cycle was not in reset and not max, next value is not 0.
    check_no_spurious_zero_when_prev_not_max: assert property (
        @(posedge clk) disable iff (rst) (!$past(rst) && ($past(count) != 4'hF)) |-> (count != 4'h0)
    );

endmodule

rtl:
module and_xnor_inv (
  input a,
  input b,
  output g_out,
  output p_out
);

  wire n3;

  // Inverter
  not (n3, a);

  // AND gate
  and (g_out, a, b);

  // XNOR gate
  xnor (p_out, n3, b);

endmodule

sva:
module and_xnor_inv_sva (
    input logic a,
    input logic b,
    input logic g_out,
    input logic p_out
);
    // No clock or reset in RTL; pure combinational; sample on posedge of a or b.

    // g_out implements a AND b.
    check_and_definition: assert property (
        @(posedge a or posedge b) g_out == (a & b)
    );

    // p_out implements a XOR b (since XNOR(~a,b) == a^b).
    check_xor_definition: assert property (
        @(posedge a or posedge b) p_out == (a ^ b)
    );

    // g_out and p_out are never both HIGH.
    check_outputs_mutex: assert property (
        @(posedge a or posedge b) !(g_out & p_out)
    );

    // OR of outputs equals OR of inputs.
    check_or_identity: assert property (
        @(posedge a or posedge b) (g_out | p_out) == (a | b)
    );

    // XOR of outputs equals OR of inputs (disjoint sum).
    check_xor_or_identity: assert property (
        @(posedge a or posedge b) (g_out ^ p_out) == (a | b)
    );

    // Truth table: a=0, b=0 -> g_out=0, p_out=0.
    check_case_00: assert property (
        @(posedge a or posedge b) (!a && !b) |-> (!g_out && !p_out)
    );

    // Truth table: a=0, b=1 -> g_out=0, p_out=1.
    check_case_01: assert property (
        @(posedge a or posedge b) (!a && b) |-> (!g_out && p_out)
    );

    // Truth table: a=1, b=0 -> g_out=0, p_out=1.
    check_case_10: assert property (
        @(posedge a or posedge b) (a && !b) |-> (!g_out && p_out)
    );

    // Truth table: a=1, b=1 -> g_out=1, p_out=0.
    check_case_11: assert property (
        @(posedge a or posedge b) (a && b) |-> (g_out && !p_out)
    );
endmodule

