module dff_en_ce (
  input clk,
  input en,
  input enclk,
  input d,
  output q
);

  reg q_reg;

  always @(posedge clk) begin
    if (enclk) begin
      if (en)
        q_reg <= d;
    end
    else
      q_reg <= q_reg;
  end

  assign q = q_reg;

endmodule

sva:
module dff_en_ce_sva (
    input logic clk,
    input logic en,
    input logic enclk,
    input logic d,
    input logic q
);
    // When both enables are HIGH, q updates to d on the next cycle.
    check_load_on_both_enables: assert property (
        @(posedge clk) (enclk && en) |=> (q == $past(d))
    );

    // When enclk is LOW, q holds its previous value.
    check_hold_when_enclk_low: assert property (
        @(posedge clk) (!enclk) |=> (q == $past(q))
    );

    // When enclk is HIGH but en is LOW, q holds its previous value.
    check_hold_when_en_low_but_enclk_high: assert property (
        @(posedge clk) (enclk && !en) |=> (q == $past(q))
    );

    // Any change on q must be caused by both enables being HIGH in the prior cycle.
    check_change_requires_prior_enable: assert property (
        @(posedge clk) $changed(q) |-> $past(enclk && en)
    );

    // If q changes, the new q equals the previous-cycle d.
    check_change_matches_prev_d: assert property (
        @(posedge clk) $changed(q) |-> (q == $past(d))
    );

    // Even if en is HIGH, if enclk is LOW, q must hold.
    check_hold_when_en_high_enclk_low: assert property (
        @(posedge clk) (en && !enclk) |=> (q == $past(q))
    );

    // If enabled and d equals current q, q must not change next cycle.
    check_no_toggle_when_enabled_and_equal_data: assert property (
        @(posedge clk) (enclk && en && (d == q)) |=> (q == $past(q))
    );

    // If enabled and d differs from current q, q must change next cycle.
    check_toggle_when_enabled_and_data_differs: assert property (
        @(posedge clk) (enclk && en && (d != q)) |=> $changed(q)
    );
endmodule

rtl:
module button_counter (
  input clk,
  input button,
  output reg [2:0] count
);

  always @(posedge clk) begin
    if (button && count < 5) begin
      count <= count + 1;
    end else if (count == 5) begin
      count <= 0;
    end
  end

endmodule

sva:
module button_counter_sva (
  input logic clk,
  input logic button,
  input logic [2:0] count
);

  // When button is high and count<5, next count increments by 1.
  check_increment_on_button_lt5: assert property (
    @(posedge clk) (button && (count < 3'd5)) |-> ##1 (count == $past(count) + 3'd1)
  );

  // When count is 5, next count becomes 0.
  check_wrap_to_zero_on_five: assert property (
    @(posedge clk) (count == 3'd5) |-> ##1 (count == 3'd0)
  );

  // Otherwise (not increment condition and not 5), count holds.
  check_hold_when_no_increment_conditions: assert property (
    @(posedge clk) ((! (button && (count < 3'd5))) && (count != 3'd5)) |-> ##1 (count == $past(count))
  );

  // If count is 4 and button is high, then 5 next and 0 the cycle after.
  check_two_cycle_4_button_to_0: assert property (
    @(posedge clk) (button && (count == 3'd4)) |-> ##1 (count == 3'd5) ##1 (count == 3'd0)
  );

  // If count > 5, it must hold its value.
  check_stable_when_gt5: assert property (
    @(posedge clk) (count > 3'd5) |-> ##1 (count == $past(count))
  );

  // If count changes to 0 from non-zero, previous count must have been 5.
  check_zero_must_follow_prev_five: assert property (
    @(posedge clk) 1'b1 |-> ##1 ( !((count == 3'd0) && ($past(count) != 3'd0)) || ($past(count) == 3'd5) )
  );

  // If count increases by 1, previous cycle had button high and count<5.
  check_increment_requires_button_and_lt5: assert property (
    @(posedge clk) 1'b1 |-> ##1 ( !(count == $past(count) + 3'd1) || ($past(button) && ($past(count) < 3'd5)) )
  );

  // Any decrement must be exactly 5 -> 0.
  check_only_decrement_is_5_to_0: assert property (
    @(posedge clk) 1'b1 |-> ##1 ( !(count < $past(count)) || ( ($past(count) == 3'd5) && (count == 3'd0) ) )
  );

  // Count cannot be 5 in two consecutive cycles.
  check_no_two_consecutive_five: assert property (
    @(posedge clk) (count == 3'd5) |-> ##1 (count != 3'd5)
  );

  // From prev <=5, next count cannot jump by more than +1.
  check_no_upskip_when_prev_le5: assert property (
    @(posedge clk) 1'b1 |-> ##1 ( !($past(count) <= 3'd5) || (count <= ($past(count) + 3'd1)) )
  );

endmodule

module MoleDecoder_sva (
    input logic CLK,                 // sampling clock for assertions
    input logic [4:0] mole_position,
    input logic [15:0] mole16bit
);
    // Output has at most one bit set or is all zero.
    check_onehot0_output: assert property (
        @(posedge CLK) $onehot0(mole16bit)
    );

    // For positions 0..15, output equals 1 shifted left by mole_position.
    check_decode_when_valid_position: assert property (
        @(posedge CLK) (mole_position <= 5'd15) |-> (mole16bit == (16'h0001 << mole_position))
    );

    // For positions 16..31, output is zero.
    check_zero_on_invalid_position: assert property (
        @(posedge CLK) (mole_position > 5'd15) |-> (mole16bit == 16'h0000)
    );

    // Zero output implies position is outside 0..15.
    check_zero_means_invalid_position: assert property (
        @(posedge CLK) (mole16bit == 16'h0000) |-> (mole_position > 5'd15)
    );

    // Non-zero output implies position is within 0..15.
    check_nonzero_means_valid_position: assert property (
        @(posedge CLK) (mole16bit != 16'h0000) |-> (mole_position <= 5'd15)
    );

    // Non-zero output must match the 1<<mole_position encoding.
    check_nonzero_matches_shift: assert property (
        @(posedge CLK) (mole16bit != 16'h0000) |-> (mole16bit == (16'h0001 << mole_position))
    );

    // Boundary: position 0 decodes to LSB set.
    check_pos0_maps_to_lsb: assert property (
        @(posedge CLK) (mole_position == 5'd0) |-> (mole16bit == 16'h0001)
    );

    // Boundary: position 15 decodes to MSB set.
    check_pos15_maps_to_msb: assert property (
        @(posedge CLK) (mole_position == 5'd15) |-> (mole16bit == 16'h8000)
    );
endmodule

module simple_counter_sva (
    input logic clk,
    input logic reset,
    input logic [7:0] count
);
    // Clock: clk (posedge)
    // Reset: reset (active-high, synchronous)
    // Logic: sequential counter with wrap at 8'hFF

    // Reset drives count to 0 on the next cycle.
    reset_clears_count_next: assert property (
        @(posedge clk) reset |=> (count == 8'h00)
    );

    // If reset is held high across cycles, count is 0 in the held cycle.
    reset_held_keeps_zero: assert property (
        @(posedge clk) (reset && $past(reset)) |-> (count == 8'h00)
    );

    // When not reset and not at max, next count increments by 1.
    count_increments_when_not_max: assert property (
        @(posedge clk) disable iff (reset) (count != 8'hFF) |=> (count == $past(count) + 8'h01)
    );

    // When not reset and at max, next count wraps to 0.
    count_wraps_after_max: assert property (
        @(posedge clk) disable iff (reset) (count == 8'hFF) |=> (count == 8'h00)
    );

    // Next-state is fully determined by current count when not in reset.
    next_state_deterministic: assert property (
        @(posedge clk) disable iff (reset) 1'b1 |=> (count == (($past(count) == 8'hFF) ? 8'h00 : ($past(count) + 8'h01)))
    );

    // Without reset over two adjacent cycles, count must change every cycle.
    count_changes_every_cycle_no_reset: assert property (
        @(posedge clk) disable iff (reset) (!reset && !$past(reset)) |-> (count != $past(count))
    );

    // If count is 0 without reset, previous cycle was either reset or 0xFF.
    zero_only_from_reset_or_wrap: assert property (
        @(posedge clk) disable iff (reset) (count == 8'h00) |-> ($past(reset) || ($past(count) == 8'hFF))
    );

    // If previous cycle (without reset) was 0xFF, current count is 0.
    prev_max_implies_zero_now: assert property (
        @(posedge clk) disable iff (reset) ($past(!reset) && ($past(count) == 8'hFF)) |-> (count == 8'h00)
    );

endmodule

module Multiplexer_sva #(parameter WIDTH = 1) (
    input logic ctrl,
    input logic [WIDTH-1:0] D0,
    input logic [WIDTH-1:0] D1,
    input logic [WIDTH-1:0] S
);
    // When ctrl==0, S equals D0.
    select_d0_when_ctrl0: assert property (
        @($global_clock) (ctrl == 1'b0) |-> (S == D0)
    );

    // When ctrl==1, S equals D1.
    select_d1_when_ctrl1: assert property (
        @($global_clock) (ctrl == 1'b1) |-> (S == D1)
    );

    // S implements the mux function S = ctrl ? D1 : D0.
    mux_function_definition: assert property (
        @($global_clock) (S == ((ctrl == 1'b0) ? D0 : D1))
    );

    // If inputs are equal, S must equal that value.
    equal_inputs_tieoff: assert property (
        @($global_clock) (D0 == D1) |-> (S == D0)
    );

    // If ctrl, D0, and D1 are stable, S must be stable.
    output_stable_when_all_static: assert property (
        @($global_clock) ($stable(ctrl) && $stable(D0) && $stable(D1)) |-> $stable(S)
    );

    // On ctrl rising edge, S equals D1.
    output_matches_d1_on_ctrl_rise: assert property (
        @($global_clock) $rose(ctrl) |-> (S == D1)
    );

    // On ctrl falling edge, S equals D0.
    output_matches_d0_on_ctrl_fall: assert property (
        @($global_clock) $fell(ctrl) |-> (S == D0)
    );

    // With ctrl held at 0 and D0 stable, S must be stable.
    stable_out_when_select0_and_d0_stable: assert property (
        @($global_clock) (ctrl == 1'b0 && $stable(ctrl) && $stable(D0)) |-> $stable(S)
    );

    // With ctrl held at 1 and D1 stable, S must be stable.
    stable_out_when_select1_and_d1_stable: assert property (
        @($global_clock) (ctrl == 1'b1 && $stable(ctrl) && $stable(D1)) |-> $stable(S)
    );

    // With ctrl held at 0, S changes iff D0 changes.
    change_correlation_ctrl0: assert property (
        @($global_clock) ($stable(ctrl) && (ctrl == 1'b0)) |-> ($changed(S) == $changed(D0))
    );

    // With ctrl held at 1, S changes iff D1 changes.
    change_correlation_ctrl1: assert property (
        @($global_clock) ($stable(ctrl) && (ctrl == 1'b1)) |-> ($changed(S) == $changed(D1))
    );

    // If ctrl toggles while D0==D1, S must not change.
    ctrl_toggle_no_effect_when_inputs_equal: assert property (
        @($global_clock) ($changed(ctrl) && (D0 == D1)) |-> $stable(S)
    );
endmodule

