module fsm_pattern_detection (
  input clk,
  input reset,
  input data,
  output detected
);

  // Define states
  localparam IDLE = 2'b00;
  localparam STATE1 = 2'b01;
  localparam STATE2 = 2'b10;

  // Define pattern to detect
  localparam PATTERN = 3'b101;

  // Define current state
  reg [1:0] state;

  // Define shift register
  reg [2:0] shift_reg;

  // Define output register
  reg output_reg;

  // Define clocked process
  always @(posedge clk) begin
    if (reset) begin
      // Reset state and shift register
      state <= IDLE;
      shift_reg <= 3'b0;
      output_reg <= 1'b0;
    end else begin
      // Shift in new data
      shift_reg <= {shift_reg[1:0], data};

      // State machine
      case(state)
        IDLE: begin
          if (shift_reg == PATTERN) begin
            state <= STATE1;
            output_reg <= 1'b1;
          end else begin
            state <= IDLE;
            output_reg <= 1'b0;
          end
        end
        STATE1: begin
          state <= STATE2;
          output_reg <= 1'b1;
        end
        STATE2: begin
          state <= IDLE;
          output_reg <= 1'b0;
        end
      endcase
    end
  end

  // Assign output
  assign detected = output_reg;

endmodule

sva:
module fsm_pattern_detection_sva (
  input logic clk,
  input logic reset,
  input logic data,
  input logic detected,
  // Internal signals from DUT (bind hierarchically)
  input logic [1:0] state,
  input logic [2:0] shift_reg,
  input logic output_reg
);
  // Mirror DUT localparams
  localparam IDLE   = 2'b00;
  localparam STATE1 = 2'b01;
  localparam STATE2 = 2'b10;
  localparam PATTERN = 3'b101;

  ///// Basic wiring /////
  // detected must equal output_reg due to continuous assign.
  check_detected_matches_output_reg: assert property (
    @(posedge clk) disable iff (reset) detected == output_reg
  );

  ///// Reset behavior /////
  // On the first cycle out of reset, all regs return to defaults.
  check_reset_release_defaults: assert property (
    @(posedge clk) disable iff (reset) $past(reset) |-> (state == IDLE) && (shift_reg == 3'b000) && (output_reg == 1'b0) && (detected == 1'b0)
  );

  ///// Shift register behavior /////
  // Shift register updates with previous value and previous data.
  check_shift_reg_update: assert property (
    @(posedge clk) disable iff (reset) shift_reg == {$past(shift_reg)[1:0], $past(data)}
  );

  ///// FSM next-state rules /////
  // From IDLE with pattern match, next state is STATE1.
  check_idle_match_next_state: assert property (
    @(posedge clk) disable iff (reset) ($past(state) == IDLE) && ($past(shift_reg) == PATTERN) |-> (state == STATE1)
  );
  // From IDLE without pattern match, stay in IDLE.
  check_idle_nomatch_next_state: assert property (
    @(posedge clk) disable iff (reset) ($past(state) == IDLE) && ($past(shift_reg) != PATTERN) |-> (state == IDLE)
  );
  // From STATE1, next state is STATE2.
  check_state1_next_state: assert property (
    @(posedge clk) disable iff (reset) ($past(state) == STATE1) |-> (state == STATE2)
  );
  // From STATE2, next state is IDLE.
  check_state2_next_state: assert property (
    @(posedge clk) disable iff (reset) ($past(state) == STATE2) |-> (state == IDLE)
  );

  ///// Output behavior /////
  // From IDLE with pattern match, detected asserted next cycle.
  check_idle_match_detected: assert property (
    @(posedge clk) disable iff (reset) ($past(state) == IDLE) && ($past(shift_reg) == PATTERN) |-> (detected == 1'b1)
  );
  // From IDLE without pattern match, detected deasserted next cycle.
  check_idle_nomatch_detected: assert property (
    @(posedge clk) disable iff (reset) ($past(state) == IDLE) && ($past(shift_reg) != PATTERN) |-> (detected == 1'b0)
  );
  // In STATE1, detected is asserted.
  check_state1_detected: assert property (
    @(posedge clk) disable iff (reset) ($past(state) == STATE1) |-> (detected == 1'b1)
  );
  // In STATE2, detected is deasserted.
  check_state2_detected: assert property (
    @(posedge clk) disable iff (reset) ($past(state) == STATE2) |-> (detected == 1'b0)
  );

  ///// Detected pulse shape /////
  // A rising edge of detected is followed by one more HIGH then a LOW.
  check_detected_two_cycle_pulse: assert property (
    @(posedge clk) disable iff (reset) $rose(detected) |-> (##1 detected ##1 !detected)
  );
  // Any rising edge of detected implies prior cycle was IDLE with pattern.
  check_detected_rise_corresponds_to_match: assert property (
    @(posedge clk) disable iff (reset) $rose(detected) |-> ($past(state) == IDLE) && ($past(shift_reg) == PATTERN)
  );

endmodule

module priority_arbiter_sva (
    input logic clk,

    input logic src0_arb_atom_q,
    input logic src0_arb_req_q,
    input logic src1_arb_atom_q,
    input logic src1_arb_req_q,
    input logic src2_arb_atom_q,
    input logic src2_arb_req_q,
    input logic src3_arb_atom_q,
    input logic src3_arb_req_q,
    input logic src4_arb_atom_q,
    input logic src4_arb_req_q,
    input logic src5_arb_atom_q,
    input logic src5_arb_req_q,
    input logic src6_arb_atom_q,
    input logic src6_arb_req_q,
    input logic src7_arb_atom_q,
    input logic src7_arb_req_q,

    input logic arb_src0_grant_a,
    input logic arb_src1_grant_a,
    input logic arb_src2_grant_a,
    input logic arb_src3_grant_a,
    input logic arb_src4_grant_a,
    input logic arb_src5_grant_a,
    input logic arb_src6_grant_a,
    input logic arb_src7_grant_a
);
    // DUT is purely combinational (no reset); assertions sampled on external clk.

    // Grant0 equals req0 & atom0.
    check_grant0_logic: assert property (
        @(posedge clk) arb_src0_grant_a == (src0_arb_req_q && src0_arb_atom_q)
    );

    // Grant1 equals req1 & atom1 & !atom0.
    check_grant1_logic: assert property (
        @(posedge clk) arb_src1_grant_a == (src1_arb_req_q && src1_arb_atom_q && !src0_arb_atom_q)
    );

    // Grant2 equals req2 & atom2 & !atom1 & !atom0.
    check_grant2_logic: assert property (
        @(posedge clk) arb_src2_grant_a == (src2_arb_req_q && src2_arb_atom_q && !src1_arb_atom_q && !src0_arb_atom_q)
    );

    // Grant3 equals req3 & atom3 & !atom2 & !atom1 & !atom0.
    check_grant3_logic: assert property (
        @(posedge clk) arb_src3_grant_a == (src3_arb_req_q && src3_arb_atom_q && !src2_arb_atom_q && !src1_arb_atom_q && !src0_arb_atom_q)
    );

    // Grant4 equals req4 & atom4 & !atom3..0.
    check_grant4_logic: assert property (
        @(posedge clk) arb_src4_grant_a == (src4_arb_req_q && src4_arb_atom_q && !src3_arb_atom_q && !src2_arb_atom_q && !src1_arb_atom_q && !src0_arb_atom_q)
    );

    // Grant5 equals req5 & atom5 & !atom4..0.
    check_grant5_logic: assert property (
        @(posedge clk) arb_src5_grant_a == (src5_arb_req_q && src5_arb_atom_q && !src4_arb_atom_q && !src3_arb_atom_q && !src2_arb_atom_q && !src1_arb_atom_q && !src0_arb_atom_q)
    );

    // Grant6 equals req6 & atom6 & !atom5..0.
    check_grant6_logic: assert property (
        @(posedge clk) arb_src6_grant_a == (src6_arb_req_q && src6_arb_atom_q && !src5_arb_atom_q && !src4_arb_atom_q && !src3_arb_atom_q && !src2_arb_atom_q && !src1_arb_atom_q && !src0_arb_atom_q)
    );

    // Grant7 equals req7 & atom7 & !atom6..0.
    check_grant7_logic: assert property (
        @(posedge clk) arb_src7_grant_a == (src7_arb_req_q && src7_arb_atom_q && !src6_arb_atom_q && !src5_arb_atom_q && !src4_arb_atom_q && !src3_arb_atom_q && !src2_arb_atom_q && !src1_arb_atom_q && !src0_arb_atom_q)
    );

    // Grants are mutually exclusive (0 or 1 set).
    check_grant_mutex: assert property (
        @(posedge clk) $onehot0({arb_src7_grant_a,arb_src6_grant_a,arb_src5_grant_a,arb_src4_grant_a,arb_src3_grant_a,arb_src2_grant_a,arb_src1_grant_a,arb_src0_grant_a})
    );

    // If no atoms are set, no grants are set.
    check_no_atom_no_grant: assert property (
        @(posedge clk)
            !(src0_arb_atom_q || src1_arb_atom_q || src2_arb_atom_q || src3_arb_atom_q ||
              src4_arb_atom_q || src5_arb_atom_q || src6_arb_atom_q || src7_arb_atom_q)
            |-> !(arb_src0_grant_a || arb_src1_grant_a || arb_src2_grant_a || arb_src3_grant_a ||
                  arb_src4_grant_a || arb_src5_grant_a || arb_src6_grant_a || arb_src7_grant_a)
    );

endmodule

