module Adder(
    input [7:0] A,
    input [7:0] B,
    output [15:0] C
);

assign C = {8'b0, A} + {8'b0, B};

endmodule

sva:
module Adder_sva (
    input logic [7:0]  A,
    input logic [7:0]  B,
    input logic [15:0] C
);
    // No clock/reset in RTL; sample assertions on posedge of A[0].
    // Output equals zero-extended sum of A and B.
    check_sum_function: assert property (
        @(posedge A[0]) C == ({8'b0, A} + {8'b0, B})
    );

    // Upper seven bits are always zero.
    check_upper_seven_zero: assert property (
        @(posedge A[0]) C[15:9] == 7'b0
    );

    // Carry-out bit matches bit[8] of zero-extended sum.
    check_carry_bit: assert property (
        @(posedge A[0]) C[8] == (({8'b0, A} + {8'b0, B})[8])
    );

    // Low 8 bits equal the low 8 bits of the zero-extended sum.
    check_low_byte: assert property (
        @(posedge A[0]) C[7:0] == (({8'b0, A} + {8'b0, B})[7:0])
    );

    // Commutativity holds for the implemented expression.
    check_commutative: assert property (
        @(posedge A[0]) C == ({8'b0, B} + {8'b0, A})
    );

    // Sum is at least A.
    check_ge_A: assert property (
        @(posedge A[0]) C >= {8'b0, A}
    );

    // Sum is at least B.
    check_ge_B: assert property (
        @(posedge A[0]) C >= {8'b0, B}
    );

    // Sum never exceeds 510 (max 255+255).
    check_upper_bound: assert property (
        @(posedge A[0]) C <= 16'd510
    );

    // If B is zero, C equals A zero-extended.
    check_B_zero_identity: assert property (
        @(posedge A[0]) (B == 8'b0) |-> (C == {8'b0, A})
    );

    // If A is zero, C equals B zero-extended.
    check_A_zero_identity: assert property (
        @(posedge A[0]) (A == 8'b0) |-> (C == {8'b0, B})
    );
endmodule

rtl:
module magnitude_comparator(
  input [2:0] A,
  input [2:0] B,
  output a_greater,
  output b_greater,
  output equal
);

  assign a_greater = (A > B) ? 1'b1 : 1'b0;
  assign b_greater = (B > A) ? 1'b1 : 1'b0;
  assign equal = (A == B) ? 1'b1 : 1'b0;

endmodule

sva:
module magnitude_comparator_sva (
    input logic clk,
    input logic [2:0] A,
    input logic [2:0] B,
    input logic a_greater,
    input logic b_greater,
    input logic equal
);
    // a_greater reflects (A > B).
    check_a_greater_definition: assert property (
        @(posedge clk) a_greater == (A > B)
    );

    // b_greater reflects (B > A).
    check_b_greater_definition: assert property (
        @(posedge clk) b_greater == (B > A)
    );

    // equal reflects (A == B).
    check_equal_definition: assert property (
        @(posedge clk) equal == (A == B)
    );

    // Exactly one of a_greater, b_greater, equal is HIGH.
    check_outputs_onehot: assert property (
        @(posedge clk) $onehot({a_greater, b_greater, equal})
    );

    // equal excludes both greater outputs.
    check_equal_excludes_greater: assert property (
        @(posedge clk) equal |-> (!a_greater && !b_greater)
    );

    // a_greater excludes b_greater and equal.
    check_a_greater_excludes_others: assert property (
        @(posedge clk) a_greater |-> (!b_greater && !equal)
    );

    // b_greater excludes a_greater and equal.
    check_b_greater_excludes_others: assert property (
        @(posedge clk) b_greater |-> (!a_greater && !equal)
    );

    // (a_greater || b_greater) matches (A != B).
    check_neq_matches_any_greater: assert property (
        @(posedge clk) (a_greater || b_greater) == (A != B)
    );

    // equal matches NOT (a_greater || b_greater).
    check_eq_matches_not_any_greater: assert property (
        @(posedge clk) equal == !(a_greater || b_greater)
    );
endmodule

