sva:
module sky130_fd_sc_hd__o221ai_sva (
    input logic Y,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic B2,
    input logic C1
);
    // Y equals ~((A1|A2)&(B1|B2)&C1) sampled on A1 rising.
    function_eq_on_A1: assert property (
        @(posedge A1) disable iff (1'b0) Y == ~(((A1 | A2) & (B1 | B2) & C1))
    );
    // Y equals ~((A1|A2)&(B1|B2)&C1) sampled on A2 rising.
    function_eq_on_A2: assert property (
        @(posedge A2) disable iff (1'b0) Y == ~(((A1 | A2) & (B1 | B2) & C1))
    );
    // Y equals ~((A1|A2)&(B1|B2)&C1) sampled on B1 rising.
    function_eq_on_B1: assert property (
        @(posedge B1) disable iff (1'b0) Y == ~(((A1 | A2) & (B1 | B2) & C1))
    );
    // Y equals ~((A1|A2)&(B1|B2)&C1) sampled on B2 rising.
    function_eq_on_B2: assert property (
        @(posedge B2) disable iff (1'b0) Y == ~(((A1 | A2) & (B1 | B2) & C1))
    );
    // Y equals ~((A1|A2)&(B1|B2)&C1) sampled on C1 rising.
    function_eq_on_C1: assert property (
        @(posedge C1) disable iff (1'b0) Y == ~(((A1 | A2) & (B1 | B2) & C1))
    );

    // C1 LOW forces Y HIGH.
    c1_low_forces_y_high: assert property (
        @(posedge A1) disable iff (1'b0) (C1 == 1'b0) |-> (Y == 1'b1)
    );
    // Both A inputs LOW force Y HIGH.
    both_a_low_force_y_high: assert property (
        @(posedge B1) disable iff (1'b0) ((A1 == 1'b0) && (A2 == 1'b0)) |-> (Y == 1'b1)
    );
    // Both B inputs LOW force Y HIGH.
    both_b_low_force_y_high: assert property (
        @(posedge A2) disable iff (1'b0) ((B1 == 1'b0) && (B2 == 1'b0)) |-> (Y == 1'b1)
    );
    // All terms HIGH force Y LOW.
    all_terms_high_force_y_low: assert property (
        @(posedge B2) disable iff (1'b0) (((A1 | A2) == 1'b1) && ((B1 | B2) == 1'b1) && (C1 == 1'b1)) |-> (Y == 1'b0)
    );
    // Y LOW implies C1 and both OR terms are HIGH.
    y_low_requires_all_terms_high: assert property (
        @(posedge C1) disable iff (1'b0) (Y == 1'b0) |-> (((A1 | A2) == 1'b1) && ((B1 | B2) == 1'b1) && (C1 == 1'b1))
    );
endmodule

rtl:
module shift_reg (
    input [3:0] D,
    input SHL,
    input SHR,
    input LOAD,
    output [3:0] Q
);

reg [3:0] Q_reg;
reg [3:0] Q_next;

always @(*) begin
    Q_next = Q_reg;
    if (LOAD) begin
        Q_next = D;
    end else if (SHL) begin
        Q_next[3:1] = Q_reg[2:0];
        Q_next[0] = 0;
    end else if (SHR) begin
        Q_next[2:0] = Q_reg[3:1];
        Q_next[3] = 0;
    end
end

always @(posedge LOAD) begin
    Q_reg <= Q_next;
end

assign Q = Q_reg;

endmodule

sva:
module shift_reg_sva (
    input logic [3:0] D,
    input logic SHL,
    input logic SHR,
    input logic LOAD,
    input logic [3:0] Q
);

    // On next LOAD edge, Q equals D sampled at this LOAD edge.
    load_captures_d_next: assert property (
        @(posedge LOAD) 1'b1 |=> (Q == $past(D))
    );

    // At each LOAD edge after the first, Q equals D from the previous LOAD edge.
    q_matches_prev_d_at_load: assert property (
        @(posedge LOAD) $past($rose(LOAD)) |-> (Q == $past(D))
    );

    // SHL has no effect when LOAD rises; next Q reflects D.
    shl_ignored_on_load: assert property (
        @(posedge LOAD) SHL |=> (Q == $past(D))
    );

    // SHR has no effect when LOAD rises; next Q reflects D.
    shr_ignored_on_load: assert property (
        @(posedge LOAD) SHR |=> (Q == $past(D))
    );

    // SHL and SHR both high are ignored on LOAD; next Q reflects D.
    both_shifts_ignored_on_load: assert property (
        @(posedge LOAD) (SHL && SHR) |=> (Q == $past(D))
    );

    // If D is unchanged across two LOAD pulses, Q is unchanged across them.
    q_stable_when_d_stable_across_loads: assert property (
        @(posedge LOAD) (D == $past(D)) |=> (Q == $past(Q))
    );

    // If D changes between consecutive LOAD pulses, Q changes accordingly.
    q_changes_when_d_changes_across_loads: assert property (
        @(posedge LOAD) (D != $past(D)) |=> (Q != $past(Q))
    );

    // With no shifting requested (SHL=0, SHR=0), next Q still equals D on LOAD.
    no_shift_still_loads_d: assert property (
        @(posedge LOAD) (!SHL && !SHR) |=> (Q == $past(D))
    );

endmodule

