module top_module (
    input wire [15:0] in,
    output reg [10:0] out
);

    // Combinational circuit to split input into two 8-bit outputs
    wire [7:0] upper_byte = ~in[15:8];
    wire [7:0] lower_byte = ~in[7:0];

    // Priority encoder to encode 8-bit binary number
    wire [2:0] priority_encoder_output;
    priority_encoder priority_encoder_inst (
        .in(upper_byte),
        .out(priority_encoder_output)
    );

    // Combine outputs from both modules
    always @(*) begin
        out[2:0] = priority_encoder_output;
        out[10:3] = {7'b0, upper_byte} + {3'b0, lower_byte};
    end

endmodule

// Priority encoder module
module priority_encoder (
    input wire [7:0] in,
    output reg [2:0] out
);
    always @(*) begin
        casez(in)
            8'b00000001: out = 0;
            8'b00000010: out = 1;
            8'b00000100: out = 2;
            8'b00001000: out = 3;
            8'b00010000: out = 4;
            8'b00100000: out = 5;
            8'b01000000: out = 6;
            8'b10000000: out = 7;
            default: out = 3'b111; // If no bits are set, output 111
        endcase
    end
endmodule

sva:
module top_module_sva (
    // External clock for sampling assertions (RTL has no clock/reset)
    input logic clk,
    // DUT ports
    input wire [15:0] in,
    input wire [10:0] out
);
    // Analysis:
    // - No clock/reset in RTL; logic is purely combinational.
    // - out[2:0] = priority_encoder(~in[15:8]); default 3'b111.
    // - out[10:3] = ((~in[15:8]) + (~in[7:0]))[7:0] (8-bit truncated sum).

    ///// Encoder correctness /////
    // out[2:0] matches the case mapping implemented in priority_encoder.
    check_encoder_functional_map: assert property (
        @(posedge clk) disable iff (1'b0)
            out[2:0] == (
                ((~in[15:8]) == 8'b00000001) ? 3'd0 :
                ((~in[15:8]) == 8'b00000010) ? 3'd1 :
                ((~in[15:8]) == 8'b00000100) ? 3'd2 :
                ((~in[15:8]) == 8'b00001000) ? 3'd3 :
                ((~in[15:8]) == 8'b00010000) ? 3'd4 :
                ((~in[15:8]) == 8'b00100000) ? 3'd5 :
                ((~in[15:8]) == 8'b01000000) ? 3'd6 :
                3'd7 // 8'b10000000 or any other pattern -> 3'b111
            )
    );

    // If only bit 0 of ~in[15:8] is set, encoder outputs 0.
    check_encoder_onehot_b0: assert property (
        @(posedge clk) disable iff (1'b0)
            ((~in[15:8]) == 8'b00000001) |-> (out[2:0] == 3'd0)
    );

    // If only bit 1 of ~in[15:8] is set, encoder outputs 1.
    check_encoder_onehot_b1: assert property (
        @(posedge clk) disable iff (1'b0)
            ((~in[15:8]) == 8'b00000010) |-> (out[2:0] == 3'd1)
    );

    // If only bit 2 of ~in[15:8] is set, encoder outputs 2.
    check_encoder_onehot_b2: assert property (
        @(posedge clk) disable iff (1'b0)
            ((~in[15:8]) == 8'b00000100) |-> (out[2:0] == 3'd2)
    );

    // If only bit 3 of ~in[15:8] is set, encoder outputs 3.
    check_encoder_onehot_b3: assert property (
        @(posedge clk) disable iff (1'b0)
            ((~in[15:8]) == 8'b00001000) |-> (out[2:0] == 3'd3)
    );

    // If only bit 4 of ~in[15:8] is set, encoder outputs 4.
    check_encoder_onehot_b4: assert property (
        @(posedge clk) disable iff (1'b0)
            ((~in[15:8]) == 8'b00010000) |-> (out[2:0] == 3'd4)
    );

    // If only bit 5 of ~in[15:8] is set, encoder outputs 5.
    check_encoder_onehot_b5: assert property (
        @(posedge clk) disable iff (1'b0)
            ((~in[15:8]) == 8'b00100000) |-> (out[2:0] == 3'd5)
    );

    // If only bit 6 of ~in[15:8] is set, encoder outputs 6.
    check_encoder_onehot_b6: assert property (
        @(posedge clk) disable iff (1'b0)
            ((~in[15:8]) == 8'b01000000) |-> (out[2:0] == 3'd6)
    );

    // If no bits are set in ~in[15:8], encoder outputs 3'b111.
    check_encoder_default_zero: assert property (
        @(posedge clk) disable iff (1'b0)
            ((~in[15:8]) == 8'b00000000) |-> (out[2:0] == 3'd7)
    );

    // If multiple bits are set in ~in[15:8], encoder outputs 3'b111.
    check_encoder_default_multibit: assert property (
        @(posedge clk) disable iff (1'b0)
            (((~in[15:8]) != 8'h00) && (((~in[15:8]) & ((~in[15:8]) - 8'h01)) != 8'h00))) |-> (out[2:0] == 3'd7)
    );

    ///// Sum path correctness /////
    // out[10:3] is the low 8 bits of (~in[15:8] + ~in[7:0]).
    check_sum_truncated: assert property (
        @(posedge clk) disable iff (1'b0)
            out[10:3] == ((~in[15:8]) + (~in[7:0]))[7:0]
    );

    // If ~in[7:0] is zero, sum equals ~in[15:8].
    check_sum_when_lower_zero: assert property (
        @(posedge clk) disable iff (1'b0)
            ((~in[7:0]) == 8'h00) |-> (out[10:3] == (~in[15:8]))
    );

    // If ~in[15:8] is zero, sum equals ~in[7:0].
    check_sum_when_upper_zero: assert property (
        @(posedge clk) disable iff (1'b0)
            ((~in[15:8]) == 8'h00) |-> (out[10:3] == (~in[7:0]))
    );

    // If in == 16'hFFFF, both inverted bytes are zero and the sum is zero.
    check_sum_min: assert property (
        @(posedge clk) disable iff (1'b0)
            (in == 16'hFFFF) |-> (out[10:3] == 8'h00)
    );

    // If in == 16'h0000, both inverted bytes are 8'hFF and sum[7:0] == 8'hFE.
    check_sum_max_trunc: assert property (
        @(posedge clk) disable iff (1'b0)
            (in == 16'h0000) |-> (out[10:3] == 8'hFE)
    );

endmodule

module add_sub_sva (
    input logic CLK,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic SUB,
    input logic [3:0] RESULT
);
    // RESULT equals add or subtract modulo 16 based on SUB.
    check_result_function: assert property (
        @(posedge CLK) RESULT == (SUB ? ((A - B) & 5'h0F) : ((A + B) & 5'h0F))
    );

    // When SUB=0, RESULT is A+B modulo 16.
    check_add_when_sub0: assert property (
        @(posedge CLK) (SUB == 1'b0) |-> (RESULT == ((A + B) & 5'h0F))
    );

    // When SUB=1, RESULT is A-B modulo 16.
    check_sub_when_sub1: assert property (
        @(posedge CLK) (SUB == 1'b1) |-> (RESULT == ((A - B) & 5'h0F))
    );

    // With SUB=0 and B=0, RESULT equals A.
    check_add_identity_B_zero: assert property (
        @(posedge CLK) (SUB == 1'b0 && B == 4'h0) |-> (RESULT == A)
    );

    // With SUB=0 and A=0, RESULT equals B.
    check_add_identity_A_zero: assert property (
        @(posedge CLK) (SUB == 1'b0 && A == 4'h0) |-> (RESULT == B)
    );

    // With SUB=1 and B=0, RESULT equals A.
    check_sub_identity_B_zero: assert property (
        @(posedge CLK) (SUB == 1'b1 && B == 4'h0) |-> (RESULT == A)
    );

    // With SUB=1 and A=B, RESULT is zero.
    check_sub_self_subtract_zero: assert property (
        @(posedge CLK) (SUB == 1'b1 && A == B) |-> (RESULT == 4'h0)
    );

    // With SUB=1 and A=0, RESULT equals (16 - B) modulo 16.
    check_sub_A_zero_twos_comp: assert property (
        @(posedge CLK) (SUB == 1'b1 && A == 4'h0) |-> (RESULT == ((5'd16 - B) & 5'h0F))
    );

    // With SUB=0 and B=1, RESULT is A+1 modulo 16.
    check_add_increment_by_one: assert property (
        @(posedge CLK) (SUB == 1'b0 && B == 4'h1) |-> (RESULT == ((A + 4'h1) & 5'h0F))
    );

    // With SUB=1 and B=1, RESULT is A-1 modulo 16.
    check_sub_decrement_by_one: assert property (
        @(posedge CLK) (SUB == 1'b1 && B == 4'h1) |-> (RESULT == ((A - 4'h1) & 5'h0F))
    );
endmodule

module dff_set_sva (
    input logic Q,
    input logic CLK,
    input logic D,
    input logic SET_B
);
    // Analysis:
    // - Clock: CLK (posedge)
    // - Async set: SET_B active-low; drives Q=1 when low
    // - Logic: sequential (DFF with asynchronous set)
    // - Behavior: if SET_B==0 -> Q=1 asynchronously; else on posedge CLK -> Q captures D

    ///// Asynchronous set behavior /////
    // When SET_B is LOW, Q must be driven HIGH.
    check_async_set_dominates: assert property (
        @(posedge CLK) (SET_B == 1'b0) |-> (Q == 1'b1)
    );

    // If SET_B is LOW across consecutive cycles, Q is HIGH in both.
    check_async_set_held_two_cycles: assert property (
        @(posedge CLK) (SET_B == 1'b0) && ($past(SET_B) == 1'b0) |-> (Q == 1'b1) && ($past(Q) == 1'b1)
    );

    ///// Synchronous capture when not set /////
    // With SET_B HIGH in both this and previous cycle, Q equals prior D.
    check_sync_capture_when_not_set: assert property (
        @(posedge CLK) disable iff (!SET_B) ($past(SET_B) == 1'b1) |-> (Q == $past(D))
    );

    // In normal mode, if D was stable over the last cycle, Q stays stable.
    check_stable_D_implies_stable_Q: assert property (
        @(posedge CLK) disable iff (!SET_B) ($past(SET_B) == 1'b1) && (D == $past(D)) |-> (Q == $past(Q))
    );

    // In normal mode, if Q changed this cycle, it must equal the prior D.
    check_Q_change_matches_prior_D: assert property (
        @(posedge CLK) disable iff (!SET_B) ($past(SET_B) == 1'b1) && (Q != $past(Q)) |-> (Q == $past(D))
    );

    // On the first clock after SET_B rises (release), Q captures D from the release edge.
    check_capture_after_set_release: assert property (
        @(posedge CLK) disable iff (!SET_B) $rose(SET_B) |-> ##1 (Q == $past(D,1))
    );

    ///// Sanity constraints derived from RTL /////
    // Q cannot be 0 while SET_B is LOW.
    check_Q_zero_implies_set_deasserted: assert property (
        @(posedge CLK) (Q == 1'b0) |-> (SET_B == 1'b1)
    );

    // A falling edge on Q implies prior D was 0 and SET_B was not asserted.
    check_Q_fall_origin: assert property (
        @(posedge CLK) $fell(Q) |-> ($past(SET_B) == 1'b1) && (SET_B == 1'b1) && ($past(D) == 1'b0)
    );

endmodule

