    );

    ///// Test enable gating /////
    // TE low forces ENCLK low.
    te_low_forces_zero: assert property (
        @(posedge CLK) disable iff (reset) (TE == 1'b0) |-> (ENCLK == 1'b0)
    );
    // ENCLK high implies TE is high (gated path).
    enclk_high_requires_te: assert property (
