module full_adder (
    input A,
    input B,
    input C_in,
    output S,
    output C_out
);

    assign S = A ^ B ^ C_in;
    assign C_out = (A & B) | (C_in & (A ^ B));

endmodule

module four_bit_adder (
    input [3:0] A,
    input [3:0] B,
    input C_in,
    output [3:0] S,
    output C_out
);

    wire c1, c2, c3;

    full_adder fa0(.A(A[0]), .B(B[0]), .C_in(C_in), .S(S[0]), .C_out(c1));
    full_adder fa1(.A(A[1]), .B(B[1]), .C_in(c1), .S(S[1]), .C_out(c2));
    full_adder fa2(.A(A[2]), .B(B[2]), .C_in(c2), .S(S[2]), .C_out(c3));
    full_adder fa3(.A(A[3]), .B(B[3]), .C_in(c3), .S(S[3]), .C_out(C_out));

endmodule

sva:
module four_bit_adder_sva (
    input logic CLK,
    input logic RESETn,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic C_in,
    input logic [3:0] S,
    input logic C_out
);
    // Sum and carry must equal 5-bit addition of inputs.
    check_total_sum: assert property (
        @(posedge CLK) disable iff (!RESETn) {C_out, S} == ({1'b0, A} + {1'b0, B} + C_in)
    );

    // LSB sum equals XOR of A[0], B[0], and C_in.
    check_lsb_sum: assert property (
        @(posedge CLK) disable iff (!RESETn) S[0] == (A[0] ^ B[0] ^ C_in)
    );

    // Low 2-bit sum matches truncated 2-bit addition.
    check_low2_trunc: assert property (
        @(posedge CLK) disable iff (!RESETn) S[1:0] == (({1'b0, A[1:0]} + {1'b0, B[1:0]} + C_in)[1:0])
    );

    // Low 3-bit sum matches truncated 3-bit addition.
    check_low3_trunc: assert property (
        @(posedge CLK) disable iff (!RESETn) S[2:0] == (({1'b0, A[2:0]} + {1'b0, B[2:0]} + C_in)[2:0])
    );

    // Carry-out equals MSB of the 5-bit total sum.
    check_cout_msb_equal: assert property (
        @(posedge CLK) disable iff (!RESETn) C_out == (({1'b0, A} + {1'b0, B} + C_in)[4])
    );

    // Bit1 sum uses carry from bit0 result.
    check_s1_with_carry0: assert property (
        @(posedge CLK) disable iff (!RESETn) S[1] == (A[1] ^ B[1] ^ (({1'b0, A[0]} + {1'b0, B[0]} + C_in)[1]))
    );

    // Bit2 sum uses carry from bit1 result.
    check_s2_with_carry1: assert property (
        @(posedge CLK) disable iff (!RESETn) S[2] == (A[2] ^ B[2] ^ (({1'b0, A[1:0]} + {1'b0, B[1:0]} + C_in)[2]))
    );

    // Bit3 sum uses carry from bit2 result.
    check_s3_with_carry2: assert property (
        @(posedge CLK) disable iff (!RESETn) S[3] == (A[3] ^ B[3] ^ (({1'b0, A[2:0]} + {1'b0, B[2:0]} + C_in)[3]))
    );

    // MSB carry-out equals full-adder formula using carry into MSB.
    check_cout_full_adder_msb: assert property (
        @(posedge CLK) disable iff (!RESETn) C_out == ( (A[3] & B[3]) | ((A[3] ^ B[3]) & (({1'b0, A[2:0]} + {1'b0, B[2:0]} + C_in)[3])) )
    );

    // High 2-bit block plus propagated carry equals outputs' high block and C_out.
    check_high_group_with_carry2: assert property (
        @(posedge CLK) disable iff (!RESETn) {C_out, S[3:2]} == ( {1'b0, A[3:2]} + {1'b0, B[3:2]} + (({1'b0, A[2:0]} + {1'b0, B[2:0]} + C_in)[3]) )
    );

    // Adding zero B and zero C_in returns A, with no carry.
    identity_B0_C0: assert property (
        @(posedge CLK) disable iff (!RESETn) ((B == 4'b0000) && (C_in == 1'b0)) |-> ((S == A) && (C_out == 1'b0))
    );

    // Adding zero A and zero C_in returns B, with no carry.
    identity_A0_C0: assert property (
        @(posedge CLK) disable iff (!RESETn) ((A == 4'b0000) && (C_in == 1'b0)) |-> ((S == B) && (C_out == 1'b0))
    );

    // Adding only C_in to zero A and zero B places C_in in bit0, no carry-out.
    identity_A0_B0: assert property (
        @(posedge CLK) disable iff (!RESETn) ((A == 4'b0000) && (B == 4'b0000)) |-> ((S == {3'b000, C_in}) && (C_out == 1'b0))
    );

    // Max plus one case: 0xF + 0xF + 1 = carry 1 and 0xF.
    max_plus_one_case: assert property (
        @(posedge CLK) disable iff (!RESETn) ((A == 4'hF) && (B == 4'hF) && (C_in == 1'b1)) |-> ((S == 4'hF) && (C_out == 1'b1))
    );
endmodule

rtl:
module axis_pulse_generator
(
  input  wire        aclk,
  input  wire        aresetn,

  // Slave side
  output wire        s_axis_tready,
  input  wire [63:0] s_axis_tdata,
  input  wire        s_axis_tvalid,

  // Master side
  input  wire        m_axis_tready,
  output wire [15:0] m_axis_tdata,
  output wire        m_axis_tvalid
);

  reg [31:0] int_cntr_reg, int_cntr_next;
  reg pulse_generated;
  reg [31:0] pulse_duration;
  reg [31:0] pulse_counter;

  wire int_enbl_wire, int_tready_wire, int_tvalid_wire;

  assign int_enbl_wire = |int_cntr_reg;
  assign int_tready_wire = ~int_enbl_wire;
  assign int_tvalid_wire = int_tready_wire & s_axis_tvalid;

  always @(posedge aclk)
  begin
    if(~aresetn)
    begin
      int_cntr_reg <= 32'd0;
      pulse_generated <= 1'b0;
      pulse_duration <= 32'd0;
      pulse_counter <= 32'd0;
    end
    else
    begin
      int_cntr_reg <= int_cntr_next;
    end
  end

  always @*
  begin
    int_cntr_next = int_cntr_reg;

    if(s_axis_tvalid && !pulse_generated)
    begin
      pulse_duration <= s_axis_tdata[63:32];
      pulse_generated <= 1'b1;
      pulse_counter <= pulse_duration;
    end

    if(pulse_generated)
    begin
      if(pulse_counter == 0)
      begin
        pulse_generated <= 1'b0;
      end
      else
      begin
        pulse_counter <= pulse_counter - 1'b1;
      end
    end

    if(int_enbl_wire)
    begin
      int_cntr_next = int_cntr_reg - 1'b1;
    end
  end

  assign s_axis_tready = int_tready_wire;
  assign m_axis_tdata = s_axis_tdata[15:0];
  assign m_axis_tvalid = int_tvalid_wire;

endmodule

sva:
module axis_pulse_generator_sva (
    input logic        aclk,
    input logic        aresetn,
    // Slave side
    input logic        s_axis_tready,
    input logic [63:0] s_axis_tdata,
    input logic        s_axis_tvalid,
    // Master side
    input logic        m_axis_tready,
    input logic [15:0] m_axis_tdata,
    input logic        m_axis_tvalid
);
    ///// Reset behavior /////
    // While reset is asserted low, s_axis_tready must be HIGH.
    reset_ready_high: assert property (
        @(posedge aclk) !aresetn |-> (s_axis_tready == 1'b1)
    );

    ///// Combinational relationships /////
    // m_axis_tvalid is exactly s_axis_tready AND s_axis_tvalid (same cycle).
    check_tvalid_definition: assert property (
        @(posedge aclk) disable iff (!aresetn) m_axis_tvalid == (s_axis_tready & s_axis_tvalid)
    );

    // When s_axis_tvalid is LOW, m_axis_tvalid must be LOW.
    check_tvalid_low_when_s_valid_low: assert property (
        @(posedge aclk) disable iff (!aresetn) (!s_axis_tvalid) |-> (!m_axis_tvalid)
    );

    // When s_axis_tready is LOW, m_axis_tvalid must be LOW.
    check_tvalid_low_when_not_ready: assert property (
        @(posedge aclk) disable iff (!aresetn) (!s_axis_tready) |-> (!m_axis_tvalid)
    );

    // When s_axis_tready is HIGH, m_axis_tvalid mirrors s_axis_tvalid.
    check_valid_eq_when_ready: assert property (
        @(posedge aclk) disable iff (!aresetn) s_axis_tready |-> (m_axis_tvalid == s_axis_tvalid)
    );

    // When s_axis_tvalid is HIGH, m_axis_tvalid mirrors s_axis_tready.
    check_valid_eq_when_s_valid: assert property (
        @(posedge aclk) disable iff (!aresetn) s_axis_tvalid |-> (m_axis_tvalid == s_axis_tready)
    );

    // m_axis_tdata always passes through s_axis_tdata[15:0] (no latency).
    check_data_passthrough: assert property (
        @(posedge aclk) disable iff (!aresetn) m_axis_tdata == s_axis_tdata[15:0]
    );

    // When m_axis_tvalid is HIGH, data must equal s_axis_tdata[15:0] in the same cycle.
    check_data_when_valid: assert property (
        @(posedge aclk) disable iff (!aresetn) m_axis_tvalid |-> (m_axis_tdata == s_axis_tdata[15:0])
    );

    // If m_axis_tvalid is HIGH, both s_axis_tvalid and s_axis_tready must be HIGH.
    check_m_valid_implies_s_valid_and_ready: assert property (
        @(posedge aclk) disable iff (!aresetn) m_axis_tvalid |-> (s_axis_tvalid && s_axis_tready)
    );
endmodule

module decoder_3to8_sva (
    input logic A,
    input logic B,
    input logic C,
    input logic Y0,
    input logic Y1,
    input logic Y2,
    input logic Y3,
    input logic Y4,
    input logic Y5,
    input logic Y6,
    input logic Y7
);
    // Aggregate outputs for compact checks.
    wire [7:0] Y = {Y7, Y6, Y5, Y4, Y3, Y2, Y1, Y0};

    ///// Decoder output invariants /////
    // Outputs are always one-hot (exactly one HIGH).
    check_outputs_onehot: assert property (
        @(posedge A) $onehot(Y)
    );

    // If Y0 is HIGH, all other outputs must be LOW.
    check_y0_mutex: assert property (
        @(posedge A) Y0 |-> !(Y1 || Y2 || Y3 || Y4 || Y5 || Y6 || Y7)
    );
    // If Y1 is HIGH, all other outputs must be LOW.
    check_y1_mutex: assert property (
        @(posedge A) Y1 |-> !(Y0 || Y2 || Y3 || Y4 || Y5 || Y6 || Y7)
    );
    // If Y2 is HIGH, all other outputs must be LOW.
    check_y2_mutex: assert property (
        @(posedge A) Y2 |-> !(Y0 || Y1 || Y3 || Y4 || Y5 || Y6 || Y7)
    );
    // If Y3 is HIGH, all other outputs must be LOW.
    check_y3_mutex: assert property (
        @(posedge A) Y3 |-> !(Y0 || Y1 || Y2 || Y4 || Y5 || Y6 || Y7)
    );
    // If Y4 is HIGH, all other outputs must be LOW.
    check_y4_mutex: assert property (
        @(posedge A) Y4 |-> !(Y0 || Y1 || Y2 || Y3 || Y5 || Y6 || Y7)
    );
    // If Y5 is HIGH, all other outputs must be LOW.
    check_y5_mutex: assert property (
        @(posedge A) Y5 |-> !(Y0 || Y1 || Y2 || Y3 || Y4 || Y6 || Y7)
    );
    // If Y6 is HIGH, all other outputs must be LOW.
    check_y6_mutex: assert property (
        @(posedge A) Y6 |-> !(Y0 || Y1 || Y2 || Y3 || Y4 || Y5 || Y7)
    );
    // If Y7 is HIGH, all other outputs must be LOW.
    check_y7_mutex: assert property (
        @(posedge A) Y7 |-> !(Y0 || Y1 || Y2 || Y3 || Y4 || Y5 || Y6)
    );

    // On any change, the one-hot output can only switch one bit off and one bit on.
    check_transition_two_bits: assert property (
        @(posedge A)
            ($onehot(Y) && $onehot($past(Y))) |-> (($past(Y) == Y) || ($countones(Y ^ $past(Y)) == 2))
    );
endmodule

rtl:
module mux_2to1 (
    input sel,
    input in0,
    input in1,
    output out
);

    assign out = sel ? in1 : in0;

endmodule

sva:
module mux_2to1_sva (
    input logic sel,
    input logic in0,
    input logic in1,
    input logic out
);
    // When sel is 0, out equals in0.
    check_out_when_sel0: assert property (
        @(posedge sel or negedge sel or posedge in0 or negedge in0 or posedge in1 or negedge in1)
        (sel == 1'b0) |-> (out == in0)
    );

    // When sel is 1, out equals in1.
    check_out_when_sel1: assert property (
        @(posedge sel or negedge sel or posedge in0 or negedge in0 or posedge in1 or negedge in1)
        (sel == 1'b1) |-> (out == in1)
    );

    // Out implements the mux equation at each input edge.
    check_mux_equation: assert property (
        @(posedge sel or negedge sel or posedge in0 or negedge in0 or posedge in1 or negedge in1)
        (out == (sel ? in1 : in0))
    );

    // If data inputs are equal, out equals that value.
    check_equal_inputs_reflect: assert property (
        @(posedge sel or negedge sel or posedge in0 or negedge in0 or posedge in1 or negedge in1)
        (in0 == in1) |-> (out == in0)
    );

    // Out only changes when at least one of sel/in0/in1 changes.
    check_out_only_changes_with_inputs: assert property (
        @(posedge sel or negedge sel or posedge in0 or negedge in0 or posedge in1 or negedge in1)
        $changed(out) |-> ($changed(sel) || $changed(in0) || $changed(in1))
    );

    // With sel stable at 1, out follows in1 changes.
    check_out_follows_in1_when_sel1_stable: assert property (
        @(posedge sel or negedge sel or posedge in0 or negedge in0 or posedge in1 or negedge in1)
        (sel && $stable(sel) && $changed(in1)) |-> $changed(out)
    );

    // With sel stable at 0, out follows in0 changes.
    check_out_follows_in0_when_sel0_stable: assert property (
        @(posedge sel or negedge sel or posedge in0 or negedge in0 or posedge in1 or negedge in1)
        (!sel && $stable(sel) && $changed(in0)) |-> $changed(out)
    );

    // With sel stable at 1, changes on in0 alone do not change out.
    check_ignore_in0_when_sel1_only_in0_changes: assert property (
        @(posedge sel or negedge sel or posedge in0 or negedge in0 or posedge in1 or negedge in1)
        (sel && $stable(sel) && $changed(in0) && !$changed(in1)) |-> !$changed(out)
    );

    // With sel stable at 0, changes on in1 alone do not change out.
    check_ignore_in1_when_sel0_only_in1_changes: assert property (
        @(posedge sel or negedge sel or posedge in0 or negedge in0 or posedge in1 or negedge in1)
        (!sel && $stable(sel) && $changed(in1) && !$changed(in0)) |-> !$changed(out)
    );

    // When sel toggles and inputs differ and are stable, out toggles.
    check_out_changes_on_sel_toggle_when_inputs_differ: assert property (
        @(posedge sel or negedge sel or posedge in0 or negedge in0 or posedge in1 or negedge in1)
        ($changed(sel) && $stable(in0) && $stable(in1) && (in0 != in1)) |-> $changed(out)
    );

    // When sel toggles and inputs are equal and stable, out stays the same.
    check_out_stable_on_sel_toggle_when_inputs_equal: assert property (
        @(posedge sel or negedge sel or posedge in0 or negedge in0 or posedge in1 or negedge in1)
        ($changed(sel) && $stable(in0) && $stable(in1) && (in0 == in1)) |-> !$changed(out)
    );

    // If sel is stable, any out change is explained by the selected data input.
    check_out_change_explained_by_selected_input: assert property (
        @(posedge sel or negedge sel or posedge in0 or negedge in0 or posedge in1 or negedge in1)
        ($changed(out) && $stable(sel)) |-> ((sel && $changed(in1)) || (!sel && $changed(in0)))
    );
endmodule

rtl:
module counter (
    input Clk,
    input Reset,
    input Enable,
    output [3:0] Q
);

reg [3:0] Q_reg;
reg [3:0] Q_next;

always @(posedge Clk) begin
    if (Reset) begin
        Q_reg <= 4'b0000;
    end else if (Enable) begin
        Q_reg <= Q_next;
    end
end

always @(*) begin
    if (Enable)
        Q_next = Q_reg + 1;
    else
        Q_next = Q_reg;
end

assign Q = Q_reg;

endmodule

sva:
module counter_sva (
    input logic Clk,
    input logic Reset,     // Active-HIGH synchronous reset
    input logic Enable,
    input logic [3:0] Q
);

    ///// Reset behavior /////
    // On any cycle with Reset HIGH, Q is 0 on the next cycle.
    reset_forces_zero_next: assert property (
        @(posedge Clk) Reset |=> (Q == 4'd0)
    );

    // If Reset is held HIGH for consecutive cycles, Q must read 0.
    reset_hold_zero: assert property (
        @(posedge Clk) (Reset && $past(Reset)) |-> (Q == 4'd0)
    );

    ///// Enable/hold/increment rules /////
    // When disabled (and not in reset), Q holds its value into the next cycle.
    hold_when_disabled: assert property (
        @(posedge Clk) disable iff (Reset) (!Enable) |=> (Q == $past(Q))
    );

    // When enabled and Q != 15, Q increments by 1 next cycle.
    increment_when_enabled_no_overflow: assert property (
        @(posedge Clk) disable iff (Reset) (Enable && (Q != 4'hF)) |=> (Q == $past(Q) + 4'd1)
    );

    // When enabled and Q == 15, Q wraps to 0 next cycle.
    rollover_when_enabled_at_max: assert property (
        @(posedge Clk) disable iff (Reset) (Enable && (Q == 4'hF)) |=> (Q == 4'd0)
    );

    // Any change to Q (without a reset in the previous cycle) requires previous Enable.
    change_requires_prev_enable: assert property (
        @(posedge Clk) disable iff (Reset) ($changed(Q) && !$past(Reset)) |-> $past(Enable)
    );

    // With 16 consecutive enabled cycles (no reset), Q returns to its value 16 cycles earlier.
    wrap_after_16_enables: assert property (
        @(posedge Clk) disable iff (Reset) (Enable[*16]) |=> (Q == $past(Q, 16))
    );

    // With two consecutive disabled cycles (no reset), Q matches its value two cycles earlier.
    hold_across_two_disabled_cycles: assert property (
        @(posedge Clk) disable iff (Reset) (!Enable[*2]) |=> (Q == $past(Q, 2))
    );

endmodule

module calculator_sva (
    input logic [3:0] a,
    input logic [3:0] b,
    input logic [1:0] op,
    input logic [3:0] result
);
    // For op==00, result is low 4 bits of a+b.
    check_addition_result: assert property (
        @(posedge a[0] or posedge b[0] or posedge op[0] or posedge op[1]) (op == 2'b00) |-> (result == (a + b)[3:0])
    );

    // For op==01, result is low 4 bits of a-b.
    check_subtraction_result: assert property (
        @(posedge a[0] or posedge b[0] or posedge op[0] or posedge op[1]) (op == 2'b01) |-> (result == (a - b)[3:0])
    );

    // For op values not 00/01 (i.e., 10 or 11), result is 0.
    check_default_zero_for_other_ops: assert property (
        @(posedge a[0] or posedge b[0] or posedge op[0] or posedge op[1]) (op[1] == 1'b1) |-> (result == 4'b0000)
    );

    // Addition identity: when op==00 and b==0, result equals a.
    check_addition_with_b_zero: assert property (
        @(posedge a[0] or posedge b[0] or posedge op[0] or posedge op[1]) ((op == 2'b00) && (b == 4'b0000)) |-> (result == a)
    );

    // Addition identity: when op==00 and a==0, result equals b.
    check_addition_with_a_zero: assert property (
        @(posedge a[0] or posedge b[0] or posedge op[0] or posedge op[1]) ((op == 2'b00) && (a == 4'b0000)) |-> (result == b)
    );

    // Subtraction identity: when op==01 and b==0, result equals a.
    check_subtraction_with_b_zero: assert property (
        @(posedge a[0] or posedge b[0] or posedge op[0] or posedge op[1]) ((op == 2'b01) && (b == 4'b0000)) |-> (result == a)
    );

    // Subtraction equality: when op==01 and a==b, result is 0.
    check_subtraction_equal_operands_zero: assert property (
        @(posedge a[0] or posedge b[0] or posedge op[0] or posedge op[1]) ((op == 2'b01) && (a == b)) |-> (result == 4'b0000)
    );

    // Functional mapping completeness: result matches the selected operation.
    check_functional_mapping_complete: assert property (
        @(posedge a[0] or posedge b[0] or posedge op[0] or posedge op[1])
            1'b1 |-> (
                ((op == 2'b00) && (result == (a + b)[3:0])) ||
                ((op == 2'b01) && (result == (a - b)[3:0])) ||
                ((op[1] == 1'b1) && (result == 4'b0000))
            )
    );
endmodule

rtl:
module sky130_fd_sc_hd__a21oi (
    Y ,
    A1,
    A2,
    B1
);

    output Y ;
    input  A1;
    input  A2;
    input  B1;

    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    wire and0_out  ;
    wire nor0_out_Y;

    and and0 (and0_out  , A1, A2         );
    nor nor0 (nor0_out_Y, B1, and0_out   );
    buf buf0 (Y         , nor0_out_Y     );

endmodule

sva:
module sky130_fd_sc_hd__a21oi_sva (
    input logic Y,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic and0_out,
    input logic nor0_out_Y
);
    // No clock/reset in DUT; purely combinational; Y = ~(B1 | (A1 & A2)); sample on $global_clock.

    // Y must equal the a21oi boolean function.
    check_func_equiv: assert property (
        @(posedge $global_clock) Y == ~(B1 | (A1 & A2))
    );

    // Internal AND gate output equals A1 & A2.
    check_and0_out_equiv: assert property (
        @(posedge $global_clock) and0_out == (A1 & A2)
    );

    // Internal NOR gate output equals ~(B1 | and0_out).
    check_nor0_out_equiv: assert property (
        @(posedge $global_clock) nor0_out_Y == ~(B1 | and0_out)
    );

    // Output buffer drives Y equal to nor0_out_Y.
    check_buf0_equiv: assert property (
        @(posedge $global_clock) Y == nor0_out_Y
    );

    // B1 high forces Y low.
    check_b1_high_forces_y_low: assert property (
        @(posedge $global_clock) (B1 == 1'b1) |-> (Y == 1'b0)
    );

    // A1&A2 high forces Y low.
    check_a1a2_high_forces_y_low: assert property (
        @(posedge $global_clock) ((A1 & A2) == 1'b1) |-> (Y == 1'b0)
    );

    // Y high implies B1 low and at least one of A1/A2 low.
    check_y_high_implies_inputs: assert property (
        @(posedge $global_clock) (Y == 1'b1) |-> (B1 == 1'b0) && ((A1 == 1'b0) || (A2 == 1'b0))
    );

    // Y low implies B1 high or A1&A2 high.
    check_y_low_implies_inputs: assert property (
        @(posedge $global_clock) (Y == 1'b0) |-> ((B1 == 1'b1) || ((A1 & A2) == 1'b1))
    );

    // With B1 low and exactly one of A1/A2 high, Y must be high.
    check_onehot_a_inputs_when_b1_low_y_high: assert property (
        @(posedge $global_clock) (B1 == 1'b0 && (A1 ^ A2)) |-> (Y == 1'b1)
    );

    // With B1 low and A1 low, Y must be high (independent of A2).
    check_b1_low_a1_low_y_high: assert property (
        @(posedge $global_clock) (B1 == 1'b0 && A1 == 1'b0) |-> (Y == 1'b1)
    );

    // With B1 low and A2 low, Y must be high (independent of A1).
    check_b1_low_a2_low_y_high: assert property (
        @(posedge $global_clock) (B1 == 1'b0 && A2 == 1'b0) |-> (Y == 1'b1)
    );

endmodule

