sva:
module sky130_fd_sc_ls__o21a_sva (
    input logic X,
    input logic A1,
    input logic A2,
    input logic B1
);
    // No clock/reset in DUT; pure combinational; sample on posedge of A1/A2/B1/X.

    // X implements (A1 | A2) & B1.
    func_equivalence: assert property (
        @(posedge A1 or posedge A2 or posedge B1 or posedge X) X == ((A1 | A2) & B1)
    );

    // If B1 is LOW, X must be LOW.
    gate_low_when_B1_low: assert property (
        @(posedge A1 or posedge A2 or posedge B1 or posedge X) (B1 == 1'b0) |-> (X == 1'b0)
    );

    // If either A1 or A2 is HIGH and B1 is HIGH, X must be HIGH.
    drives_high_when_enabled_and_any_A: assert property (
        @(posedge A1 or posedge A2 or posedge B1 or posedge X) (B1 && (A1 || A2)) |-> (X == 1'b1)
    );

    // X cannot be HIGH unless B1 is HIGH.
    x_implies_b1: assert property (
        @(posedge A1 or posedge A2 or posedge B1 or posedge X) (X == 1'b1) |-> (B1 == 1'b1)
    );

    // X cannot be HIGH unless at least one of A1/A2 is HIGH.
    x_implies_any_a: assert property (
        @(posedge A1 or posedge A2 or posedge B1 or posedge X) (X == 1'b1) |-> (A1 || A2)
    );

    // If both A1 and A2 are LOW, X must be LOW.
    both_a_low_forces_x_low: assert property (
        @(posedge A1 or posedge A2 or posedge B1 or posedge X) ((A1 == 1'b0) && (A2 == 1'b0)) |-> (X == 1'b0)
    );

    // If A1 and B1 are HIGH, X must be HIGH.
    a1_and_b1_implies_x_high: assert property (
        @(posedge A1 or posedge A2 or posedge B1 or posedge X) (A1 && B1) |-> (X == 1'b1)
    );

    // If A2 and B1 are HIGH, X must be HIGH.
    a2_and_b1_implies_x_high: assert property (
        @(posedge A1 or posedge A2 or posedge B1 or posedge X) (A2 && B1) |-> (X == 1'b1)
    );
endmodule

rtl:
module counter (
    input clk,
    input rst,
    output reg [3:0] count
);

    always @(posedge clk) begin
        if (rst) begin
            count <= 4'b0;
        end else if (count == 4'b1111) begin
            count <= 4'b0;
        end else begin
            count <= count + 1;
        end
    end

endmodule

sva:
module counter_sva (
    input logic clk,
    input logic rst,
    input logic [3:0] count
);

    // Synchronous reset drives count to 0.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |-> (count == 4'b0000)
    );

    // Next-state function when previous cycle not in reset (increment or wrap).
    check_next_state_function: assert property (
        @(posedge clk) disable iff (rst)
            (!$past(rst)) |-> (count == (($past(count) == 4'hF) ? 4'h0 : ($past(count) + 1)))
    );

    // When not in reset, reaching 0xF wraps to 0.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (rst)
            (!$past(rst) && ($past(count) == 4'hF)) |-> (count == 4'h0)
    );

    // When not in reset, a zero value must have come from 0xF.
    check_zero_only_from_wrap: assert property (
        @(posedge clk) disable iff (rst)
            (count == 4'h0) |-> ($past(count) == 4'hF)
    );

    // Without reset, the counter value changes every cycle (never holds).
    check_free_running_no_hold: assert property (
        @(posedge clk) disable iff (rst)
            (!$past(rst)) |-> (count != $past(count))
    );

    // On reset deassertion, the counter becomes 1.
    check_deassert_to_one: assert property (
        @(posedge clk) $fell(rst) |-> (count == 4'h1)
    );

endmodule

rtl:
module connection_module(
    input a, b, c,
    input select,
    output w, x, y, z
);

    assign w = a;
    assign z = c;

    // 2:1 MUX to select between b and c
    assign x = (select == 1'b0) ? b : c;
    assign y = (select == 1'b1) ? b : c;

endmodule

sva:
module connection_module_sva (
    input logic a,
    input logic b,
    input logic c,
    input logic select,
    input logic w,
    input logic x,
    input logic y,
    input logic z
);
    // Note: No clock/reset in RTL; combinational connections sampled on any input/output edge.
    // Define a sampling event on any edge of DUT ports.
    localparam bit UNUSED = 1'b0; // prevent empty module warnings
    // Event expression used by all assertions
    `define ANY_EDGE_EVENT (posedge a or negedge a or \
                            posedge b or negedge b or \
                            posedge c or negedge c or \
                            posedge select or negedge select or \
                            posedge w or negedge w or \
                            posedge x or negedge x or \
                            posedge y or negedge y or \
                            posedge z or negedge z)

    // w must always equal a.
    check_w_equals_a: assert property (
        @(`ANY_EDGE_EVENT) (w == a)
    );

    // z must always equal c.
    check_z_equals_c: assert property (
        @(`ANY_EDGE_EVENT) (z == c)
    );

    // When select is 0, x must equal b.
    check_x_when_sel0: assert property (
        @(`ANY_EDGE_EVENT) (select == 1'b0) |-> (x == b)
    );

    // When select is 1, x must equal c.
    check_x_when_sel1: assert property (
        @(`ANY_EDGE_EVENT) (select == 1'b1) |-> (x == c)
    );

    // When select is 0, y must equal c.
    check_y_when_sel0: assert property (
        @(`ANY_EDGE_EVENT) (select == 1'b0) |-> (y == c)
    );

    // When select is 1, y must equal b.
    check_y_when_sel1: assert property (
        @(`ANY_EDGE_EVENT) (select == 1'b1) |-> (y == b)
    );

    // The pair {x,y} must be exactly {b,c}.
    check_xy_match_bc_set: assert property (
        @(`ANY_EDGE_EVENT) ((x == b) && (y == c)) || ((x == c) && (y == b))
    );

    // x equals y iff b equals c.
    check_xy_equality_reflects_bc: assert property (
        @(`ANY_EDGE_EVENT) ((x == y) == (b == c))
    );

    // When select is 1, x must equal z (both select c).
    check_x_equals_z_when_sel1: assert property (
        @(`ANY_EDGE_EVENT) (select == 1'b1) |-> (x == z)
    );

    // When select is 0, y must equal z (both select c).
    check_y_equals_z_when_sel0: assert property (
        @(`ANY_EDGE_EVENT) (select == 1'b0) |-> (y == z)
    );

endmodule

rtl:
module full_adder(
    input a, b, cin,
    output sum, cout
);

    assign sum = a ^ b ^ cin;
    assign cout = (a & b) | (cin & (a ^ b));

endmodule

module top_module(
    input [3:0] a, b, // 4-bit inputs
    input cin, // Carry-in
    output [3:0] sum, // 4-bit sum output
    output cout // Carry-out
);

    wire [3:0] carry; // Internal carry signals

    full_adder fa0(.a(a[0]), .b(b[0]), .cin(cin), .sum(sum[0]), .cout(carry[0]));
    full_adder fa1(.a(a[1]), .b(b[1]), .cin(carry[0]), .sum(sum[1]), .cout(carry[1]));
    full_adder fa2(.a(a[2]), .b(b[2]), .cin(carry[1]), .sum(sum[2]), .cout(carry[2]));
    full_adder fa3(.a(a[3]), .b(b[3]), .cin(carry[2]), .sum(sum[3]), .cout(cout));

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic [3:0] a,
    input logic [3:0] b,
    input logic cin,
    input logic [3:0] sum,
    input logic cout
);
    // No clock or reset in RTL; pure combinational ripple-carry adder.
    // Checker uses external clk for sampling; no disable iff.
    // Ports: a[3:0], b[3:0], cin -> sum[3:0], cout.

    // Sum and carry-out equal zero-extended addition of inputs.
    check_full_sum: assert property (
        @(posedge clk) {cout, sum} == ({1'b0, a} + {1'b0, b} + cin)
    );

    // Bit 0 sum equals a0 ^ b0 ^ cin.
    check_sum0_xor: assert property (
        @(posedge clk) sum[0] == (a[0] ^ b[0] ^ cin)
    );

    // Bit 1 sum equals a1 ^ b1 ^ carry0.
    check_sum1_xor_with_carry0: assert property (
        @(posedge clk) sum[1] == (a[1] ^ b[1] ^ ((a[0] & b[0]) | (cin & (a[0] ^ b[0]))))
    );

    // Bit 2 sum equals a2 ^ b2 ^ carry1.
    check_sum2_xor_with_carry1: assert property (
        @(posedge clk) sum[2] == (
            a[2] ^ b[2] ^
            ((a[1] & b[1]) | (((a[0] & b[0]) | (cin & (a[0] ^ b[0]))) & (a[1] ^ b[1])))
        )
    );

    // Bit 3 sum equals a3 ^ b3 ^ carry2.
    check_sum3_xor_with_carry2: assert property (
        @(posedge clk) sum[3] == (
            a[3] ^ b[3] ^
            (
                (a[2] & b[2]) |
                (
                    ((a[1] & b[1]) | (((a[0] & b[0]) | (cin & (a[0] ^ b[0]))) & (a[1] ^ b[1])))
                    & (a[2] ^ b[2])
                )
            )
        )
    );

    // Carry-out equals carry3 from the final full adder stage.
    check_cout_carry3: assert property (
        @(posedge clk) cout == (
            (a[3] & b[3]) |
            (
                (
                    (a[2] & b[2]) |
                    (
                        ((a[1] & b[1]) | (((a[0] & b[0]) | (cin & (a[0] ^ b[0]))) & (a[1] ^ b[1])))
                        & (a[2] ^ b[2])
                    )
                )
                & (a[3] ^ b[3])
            )
        )
    );

    // When a=0 and b=0, sum mirrors cin on bit0 and cout is 0.
    check_zero_inputs_behavior: assert property (
        @(posedge clk) ((a == 4'b0000) && (b == 4'b0000)) |-> (sum == {3'b000, cin}) && (cout == 1'b0)
    );

    // When a=15, b=15, cin=1, result is 31 (5'b11111).
    check_all_ones_plus_one: assert property (
        @(posedge clk) ((a == 4'hF) && (b == 4'hF) && (cin == 1'b1)) |-> ({cout, sum} == 5'b11111)
    );

    // With a=0 and cin=0, output equals b and cout is 0.
    check_add_b_when_a_zero_cin0: assert property (
        @(posedge clk) ((a == 4'b0000) && (cin == 1'b0)) |-> (sum == b) && (cout == 1'b0)
    );

    // With b=0 and cin=0, output equals a and cout is 0.
    check_add_a_when_b_zero_cin0: assert property (
        @(posedge clk) ((b == 4'b0000) && (cin == 1'b0)) |-> (sum == a) && (cout == 1'b0)
    );

endmodule

module pg_to_PG_assert (
    input logic clk,
    input logic [15:0] p,
    input logic [15:0] g,
    input logic [3:0] bp,
    input logic [3:0] bg
);
    // No clock/reset in RTL; purely combinational; assertions are clocked on clk.

    ///// Functional equivalence to RTL equations /////
    // bg[0] equals block-generate for bits [3:0].
    check_bg0_definition: assert property (
        @(posedge clk) bg[0] == ( g[3] | (p[3] & g[2]) | (p[3] & p[2] & g[1]) | (p[3] & p[2] & p[1] & g[0]) )
    );
    // bg[1] equals block-generate for bits [7:4].
    check_bg1_definition: assert property (
        @(posedge clk) bg[1] == ( g[7] | (p[7] & g[6]) | (p[7] & p[6] & g[5]) | (p[7] & p[6] & p[5] & g[4]) )
    );
    // bg[2] equals block-generate for bits [11:8].
    check_bg2_definition: assert property (
        @(posedge clk) bg[2] == ( g[11] | (p[11] & g[10]) | (p[11] & p[10] & g[9]) | (p[11] & p[10] & p[9] & g[8]) )
    );
    // bg[3] equals block-generate for bits [15:12].
    check_bg3_definition: assert property (
        @(posedge clk) bg[3] == ( g[15] | (p[15] & g[14]) | (p[15] & p[14] & g[13]) | (p[15] & p[14] & p[13] & g[12]) )
    );

    // bp[0] equals AND of p[3:0].
    check_bp0_definition: assert property (
        @(posedge clk) bp[0] == (p[3] & p[2] & p[1] & p[0])
    );
    // bp[1] equals AND of p[7:4].
    check_bp1_definition: assert property (
        @(posedge clk) bp[1] == (p[7] & p[6] & p[5] & p[4])
    );
    // bp[2] equals AND of p[11:8].
    check_bp2_definition: assert property (
        @(posedge clk) bp[2] == (p[11] & p[10] & p[9] & p[8])
    );
    // bp[3] equals AND of p[15:12].
    check_bp3_definition: assert property (
        @(posedge clk) bp[3] == (p[15] & p[14] & p[13] & p[12])
    );

    ///// Stability with respect to relevant inputs /////
    // bg[0] stable when p[3],p[2],p[1] and g[3:0] are stable.
    stable_bg0_on_group_inputs: assert property (
        @(posedge clk) $stable({p[3],p[2],p[1],g[3:0]}) |-> $stable(bg[0])
    );
    // bg[1] stable when p[7],p[6],p[5] and g[7:4] are stable.
    stable_bg1_on_group_inputs: assert property (
        @(posedge clk) $stable({p[7],p[6],p[5],g[7:4]}) |-> $stable(bg[1])
    );
    // bg[2] stable when p[11],p[10],p[9] and g[11:8] are stable.
    stable_bg2_on_group_inputs: assert property (
        @(posedge clk) $stable({p[11],p[10],p[9],g[11:8]}) |-> $stable(bg[2])
    );
    // bg[3] stable when p[15],p[14],p[13] and g[15:12] are stable.
    stable_bg3_on_group_inputs: assert property (
        @(posedge clk) $stable({p[15],p[14],p[13],g[15:12]}) |-> $stable(bg[3])
    );

    // bp[0] stable when p[3:0] are stable.
    stable_bp0_on_group_inputs: assert property (
        @(posedge clk) $stable(p[3:0]) |-> $stable(bp[0])
    );
    // bp[1] stable when p[7:4] are stable.
    stable_bp1_on_group_inputs: assert property (
        @(posedge clk) $stable(p[7:4]) |-> $stable(bp[1])
    );
    // bp[2] stable when p[11:8] are stable.
    stable_bp2_on_group_inputs: assert property (
        @(posedge clk) $stable(p[11:8]) |-> $stable(bp[2])
    );
    // bp[3] stable when p[15:12] are stable.
    stable_bp3_on_group_inputs: assert property (
        @(posedge clk) $stable(p[15:12]) |-> $stable(bp[3])
    );
endmodule

