sva:
module and_gate_sva (
    input logic clk,
    input logic Y,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic C1
);
    // Y must be 1 when all inputs are 1.
    check_all_inputs_high_implies_Y_high: assert property (
        @(posedge clk) disable iff (1'b0) (A1 && A2 && B1 && C1) |-> (Y == 1'b1)
    );
    // Y can be 1 only if all inputs are 1.
    check_Y_high_implies_all_inputs_high: assert property (
        @(posedge clk) disable iff (1'b0) (Y == 1'b1) |-> (A1 && A2 && B1 && C1)
    );
    // If any input is 0, Y must be 0.
    check_any_input_low_forces_Y_low: assert property (
        @(posedge clk) disable iff (1'b0) (!A1 || !A2 || !B1 || !C1) |-> (Y == 1'b0)
    );
    // If Y rises, all inputs must be 1 now.
    check_Y_rose_requires_all_inputs_high: assert property (
        @(posedge clk) disable iff (1'b0) $rose(Y) |-> (A1 && A2 && B1 && C1)
    );
    // If Y falls, at least one input must be 0 now.
    check_Y_fell_requires_some_input_low: assert property (
        @(posedge clk) disable iff (1'b0) $fell(Y) |-> (!A1 || !A2 || !B1 || !C1)
    );
    // If A1 falls to 0, Y must be 0 now.
    check_A1_fall_forces_Y_low: assert property (
        @(posedge clk) disable iff (1'b0) $fell(A1) |-> (Y == 1'b0)
    );
    // If A2 falls to 0, Y must be 0 now.
    check_A2_fall_forces_Y_low: assert property (
        @(posedge clk) disable iff (1'b0) $fell(A2) |-> (Y == 1'b0)
    );
    // If B1 falls to 0, Y must be 0 now.
    check_B1_fall_forces_Y_low: assert property (
        @(posedge clk) disable iff (1'b0) $fell(B1) |-> (Y == 1'b0)
    );
    // If C1 falls to 0, Y must be 0 now.
    check_C1_fall_forces_Y_low: assert property (
        @(posedge clk) disable iff (1'b0) $fell(C1) |-> (Y == 1'b0)
    );
    // When A1 is the last input to rise, Y must rise.
    check_last_bit_rise_A1_causes_Y_rise: assert property (
        @(posedge clk) disable iff (1'b0) ($rose(A1) && A2 && B1 && C1) |-> $rose(Y)
    );
endmodule

module up_down_counter_sva (
  input logic clk,
  input logic reset,
  input logic enable,
  input logic control,
  input logic [2:0] count
);

  ///// Reset behavior /////
  // While reset is HIGH at a clock edge, count is 0.
  check_reset_forces_zero: assert property (
    @(posedge clk) reset |-> (count == 3'd0)
  );

  ///// Hold/update rules /////
  // When disabled, count holds its previous value.
  check_hold_when_disabled: assert property (
    @(posedge clk) disable iff (reset) (!enable) |=> (count == $past(count))
  );

  // When enabled and control=1, count increments by 1 (mod 8).
  check_increment_when_enabled: assert property (
    @(posedge clk) disable iff (reset) (enable && control) |=> (count == ($past(count) + 3'd1))
  );

  // When enabled and control=0, count decrements by 1 (mod 8).
  check_decrement_when_enabled: assert property (
    @(posedge clk) disable iff (reset) (enable && !control) |=> (count == ($past(count) - 3'd1))
  );

  // When enabled, count must change value next cycle.
  check_change_on_enable: assert property (
    @(posedge clk) disable iff (reset) (enable) |=> (count != $past(count))
  );

  ///// Wrap-around corner cases /////
  // Increment wrap-around: 7 -> 0 when enabled and control=1.
  check_increment_wrap: assert property (
    @(posedge clk) disable iff (reset) (enable && control && ($past(count) == 3'd7)) |=> (count == 3'd0)
  );

  // Decrement wrap-around: 0 -> 7 when enabled and control=0.
  check_decrement_wrap: assert property (
    @(posedge clk) disable iff (reset) (enable && !control && ($past(count) == 3'd0)) |=> (count == 3'd7)
  );

  ///// Sanity /////
  // Count is always within 3-bit range.
  check_count_range: assert property (
    @(posedge clk) (count <= 3'd7)
  );

endmodule

rtl:
module check_1fs (
  input [31:0] timeunit,
  input [31:0] timeprecision,
  output reg is_1fs
);

  always @(*) begin
    if (timeunit == 1 && timeprecision == 1) begin
      is_1fs <= 1'b1;
    end else begin
      is_1fs <= 1'b0;
    end
  end

endmodule

sva:
module check_1fs_sva (
    input logic CLK,
    input logic [31:0] timeunit,
    input logic [31:0] timeprecision,
    input logic is_1fs
);
    // Output high when both inputs are exactly 1.
    check_is_1fs_high_when_both_one: assert property (
        @(posedge CLK) ((timeunit === 32'd1) && (timeprecision === 32'd1)) |-> (is_1fs == 1'b1)
    );

    // Output low when either input is not exactly 1.
    check_is_1fs_low_when_any_not_one: assert property (
        @(posedge CLK) ((timeunit !== 32'd1) || (timeprecision !== 32'd1)) |-> (is_1fs == 1'b0)
    );

    // If output is high, both inputs must be exactly 1.
    check_output_high_implies_inputs_one: assert property (
        @(posedge CLK) (is_1fs == 1'b1) |-> ((timeunit === 32'd1) && (timeprecision === 32'd1))
    );

    // Rising edge on output only when both inputs are exactly 1.
    check_rise_requires_both_one: assert property (
        @(posedge CLK) $rose(is_1fs) |-> ((timeunit === 32'd1) && (timeprecision === 32'd1))
    );

    // Falling edge on output only when at least one input is not exactly 1.
    check_fall_requires_any_not_one: assert property (
        @(posedge CLK) $fell(is_1fs) |-> ((timeunit !== 32'd1) || (timeprecision !== 32'd1))
    );

    // Output is never X or Z.
    check_output_known: assert property (
        @(posedge CLK) !$isunknown(is_1fs)
    );
endmodule

rtl:
module sky130_fd_sc_hdll__xnor2 (
    Y,
    A,
    B
);

    output Y;
    input  A;
    input  B;

    wire xnor0_out_Y;

    xnor xnor0 (xnor0_out_Y, A, B           );
    buf  buf0  (Y          , xnor0_out_Y    );

endmodule

sva:
module sky130_fd_sc_hdll__xnor2_sva (
    input logic Y,
    input logic A,
    input logic B
);
    // No clock/reset in RTL; pure combinational XNOR; sample on any edge of A or B.

    // Y implements XNOR of A and B.
    check_xnor_function: assert property (
        @(posedge A or negedge A or posedge B or negedge B) (Y === (A ~^ B))
    );

    // If B==1, Y follows A.
    check_b_one_transparent: assert property (
        @(posedge A or negedge A or posedge B or negedge B) (B == 1'b1) |-> (Y === A)
    );

    // If B==0, Y equals ~A.
    check_b_zero_inverts: assert property (
        @(posedge A or negedge A or posedge B or negedge B) (B == 1'b0) |-> (Y === ~A)
    );

    // If A==1, Y follows B.
    check_a_one_transparent: assert property (
        @(posedge A or negedge A or posedge B or negedge B) (A == 1'b1) |-> (Y === B)
    );

    // If A==0, Y equals ~B.
    check_a_zero_inverts: assert property (
        @(posedge A or negedge A or posedge B or negedge B) (A == 1'b0) |-> (Y === ~B)
    );

    // When A and B are known equal, Y is 1.
    check_equal_inputs_imply_one: assert property (
        @(posedge A or negedge A or posedge B or negedge B) (A == B) |-> (Y === 1'b1)
    );

    // When A and B are known different, Y is 0.
    check_diff_inputs_imply_zero: assert property (
        @(posedge A or negedge A or posedge B or negedge B) (A != B) |-> (Y === 1'b0)
    );

    // Y is never high-impedance.
    check_y_never_z: assert property (
        @(posedge A or negedge A or posedge B or negedge B) (Y !== 1'bz)
    );

    // If only A toggles and B is stable (both known), Y toggles.
    check_toggle_on_A_only: assert property (
        @(posedge A or negedge A or posedge B or negedge B)
        ((A == ~$past(A)) && (B == $past(B))) |-> (Y == ~$past(Y))
    );

    // If only B toggles and A is stable (both known), Y toggles.
    check_toggle_on_B_only: assert property (
        @(posedge A or negedge A or posedge B or negedge B)
        ((B == ~$past(B)) && (A == $past(A))) |-> (Y == ~$past(Y))
    );

    // If both A and B toggle (both known), Y holds its value.
    check_both_toggle_hold: assert property (
        @(posedge A or negedge A or posedge B or negedge B)
        ((A == ~$past(A)) && (B == ~$past(B))) |-> (Y == $past(Y))
    );

endmodule

rtl:
module binary_counter (
    input clk,
    input rst,
    input en,
    output [3:0] count
);

    reg [3:0] count_reg;

    always @(posedge clk) begin
        if (rst) begin
            count_reg <= 4'b0;
        end else if (en) begin
            count_reg <= count_reg + 1;
        end
    end

    assign count = count_reg;

endmodule

sva:
module binary_counter_sva (
    input logic clk,
    input logic rst,
    input logic en,
    input logic [3:0] count
);
    // Reset drives count to zero on the same clock edge.
    reset_forces_zero: assert property (
        @(posedge clk) rst |-> (count == 4'd0)
    );

    // When not in reset and enable is LOW, count holds its value.
    hold_on_en_low: assert property (
        @(posedge clk) disable iff (rst) $past(!rst) && !en |-> (count == $past(count))
    );

    // When not in reset and enable is HIGH, count increments by 1 (mod 16).
    increment_on_en_high: assert property (
        @(posedge clk) disable iff (rst) $past(!rst) && en |-> (count == ($past(count) + 4'd1))
    );

    // Any change to count (out of reset) requires enable to be HIGH.
    change_requires_en: assert property (
        @(posedge clk) disable iff (rst) $past(!rst) && (count != $past(count)) |-> en
    );

    // With enable HIGH and previous count at 0xF, count wraps to 0x0.
    wrap_from_f_to_0: assert property (
        @(posedge clk) disable iff (rst) $past(!rst) && en && ($past(count) == 4'hF) |-> (count == 4'h0)
    );

    // First cycle after reset deasserts and enable is LOW: count remains 0.
    post_reset_en0_holds_zero: assert property (
        @(posedge clk) disable iff (rst) $past(rst) && !rst && !en |-> (count == 4'd0)
    );

    // First cycle after reset deasserts and enable is HIGH: count becomes 1.
    post_reset_en1_increments_to_one: assert property (
        @(posedge clk) disable iff (rst) $past(rst) && !rst && en |-> (count == 4'd1)
    );

    // Out of reset, each step is either hold or +1 (no other deltas).
    step_or_hold_only: assert property (
        @(posedge clk) disable iff (rst) $past(!rst) |-> ((count == $past(count)) || (count == ($past(count) + 4'd1)))
    );

    // With enable HIGH for two consecutive cycles (no reset), net increment is +2.
    two_cycle_increment_when_en_stays_high: assert property (
        @(posedge clk) disable iff (rst) $past(!rst) && $past(!rst,2) && en && $past(en) |-> (count == ($past(count,2) + 4'd2))
    );

    // While reset is held across consecutive cycles, count remains 0.
    count_zero_stable_when_reset_held: assert property (
        @(posedge clk) $past(rst) && rst |-> (count == 4'd0)
    );
endmodule

rtl:
module binary_to_gray
  (G, B, clk, rst);

  output [3:0] G;
  input [3:0] B;
  input clk, rst;

  reg [3:0] G_reg;
  reg [3:0] B_reg;

  always @(posedge clk, negedge rst) begin
    if (~rst) begin
      G_reg <= 4'b0;
      B_reg <= 4'b0;
    end else begin
      B_reg <= B;
      G_reg <= {B_reg[3], B_reg[3]^B_reg[2], B_reg[2]^B_reg[1], B_reg[1]^B_reg[0]};
    end
  end

  assign G = G_reg;

endmodule

sva:
module binary_to_gray_sva (
    input logic clk,
    input logic rst,
    input logic [3:0] B,
    input logic [3:0] G,
    input logic [3:0] B_reg,
    input logic [3:0] G_reg
);
    // During reset (active-low), internal registers are cleared to 0.
    reset_regs_zero: assert property (
        @(posedge clk) (!rst) |-> (B_reg == 4'b0000) && (G_reg == 4'b0000)
    );

    // During reset (active-low), output G is 0.
    reset_output_zero: assert property (
        @(posedge clk) (!rst) |-> (G == 4'b0000)
    );

    // G is a direct reflection of G_reg.
    check_output_driven_by_greg: assert property (
        @(posedge clk) disable iff (!rst) (G == G_reg)
    );

    // B is sampled into B_reg each cycle (1-cycle latency).
    check_breg_captures_b: assert property (
        @(posedge clk) disable iff (!rst) $past(rst) |-> (B_reg == $past(B))
    );

    // G_reg computes Gray code from previous B_reg.
    check_greg_from_prev_breg: assert property (
        @(posedge clk) disable iff (!rst) $past(rst) |-> (
            G_reg == { $past(B_reg[3]),
                       $past(B_reg[3]) ^ $past(B_reg[2]),
                       $past(B_reg[2]) ^ $past(B_reg[1]),
                       $past(B_reg[1]) ^ $past(B_reg[0]) }
        )
    );

    // G equals Gray code of previous B (end-to-end 1-cycle latency).
    check_g_from_prev_b: assert property (
        @(posedge clk) disable iff (!rst) $past(rst) |-> (
            G == { $past(B[3]),
                   $past(B[3]) ^ $past(B[2]),
                   $past(B[2]) ^ $past(B[1]),
                   $past(B[1]) ^ $past(B[0]) }
        )
    );

    // On reset deassertion edge, outputs reflect zeros from previously reset state.
    check_zero_on_reset_release: assert property (
        @(posedge clk) disable iff (!rst) $rose(rst) |-> (B_reg == 4'b0000) && (G_reg == 4'b0000) && (G == 4'b0000)
    );

    // If B is unchanged for two consecutive cycles, G is unchanged next cycle.
    check_g_stable_when_b_stable: assert property (
        @(posedge clk) disable iff (!rst) $past(rst,2) && ($past(B,1) == $past(B,2)) |-> (G == $past(G))
    );

    // MSB of G equals previous cycle's MSB of B.
    check_g_msb_from_prev_b_msb: assert property (
        @(posedge clk) disable iff (!rst) $past(rst) |-> (G[3] == $past(B[3]))
    );

    // MSB of G_reg equals previous cycle's MSB of B_reg.
    check_greg_msb_from_prev_breg_msb: assert property (
        @(posedge clk) disable iff (!rst) $past(rst) |-> (G_reg[3] == $past(B_reg[3]))
    );
endmodule

rtl:
module errman_nfl (
  output nfl_num,
  output inc_dec_b,
  input cfg_err_cpl_timeout_n,
  input decr_nfl,
  input rst,
  input clk
);

  parameter FFD = 1; // clock to out delay model

  reg to_incr;
  reg add_sub_b;

  always @ (cfg_err_cpl_timeout_n or decr_nfl) begin
    case ({cfg_err_cpl_timeout_n, decr_nfl})
      2'b10: begin
        to_incr = 1'b0;
        add_sub_b = 1'b1;
      end
      2'b11: begin
        to_incr = 1'b1;
        add_sub_b = 1'b0;
      end
      2'b00: begin
        to_incr = 1'b1;
        add_sub_b = 1'b1;
      end
      2'b01: begin
        to_incr = 1'b0;
        add_sub_b = 1'b1;
      end
      default: begin
        to_incr = 1'b0;
        add_sub_b = 1'b1;
      end
    endcase
  end

  reg reg_nfl_num;
  reg reg_inc_dec_b;

  always @ (posedge clk or posedge rst) begin
    if (rst) begin
      reg_nfl_num <= #FFD 1'b0;
      reg_inc_dec_b <= #FFD 1'b0;
    end else begin
      reg_nfl_num <= #FFD to_incr ? reg_nfl_num + 1 : reg_nfl_num - 1;
      reg_inc_dec_b <= #FFD add_sub_b;
    end
  end

  assign nfl_num = reg_nfl_num;
  assign inc_dec_b = reg_inc_dec_b;

endmodule

sva:
module errman_nfl_sva (
  input logic clk,
  input logic rst, // active-high async reset
  input logic cfg_err_cpl_timeout_n,
  input logic decr_nfl,
  input logic nfl_num,
  input logic inc_dec_b
);

  ///// Reset behavior /////
  // While reset is asserted, outputs are held LOW.
  reset_outputs_low: assert property (
    @(posedge clk) rst |-> (nfl_num == 1'b0) && (inc_dec_b == 1'b0)
  );

  ///// Sequential behavior of nfl_num /////
  // nfl_num toggles every active clock (one-cycle complement).
  check_nfl_num_toggle_each_cycle: assert property (
    @(posedge clk) disable iff (rst) $past(1'b1) |-> (nfl_num == ~$past(nfl_num))
  );
  // nfl_num must change on every active clock edge.
  check_nfl_num_always_changes: assert property (
    @(posedge clk) disable iff (rst) $past(1'b1) |-> $changed(nfl_num)
  );

  ///// Registered capture of inc_dec_b /////
  // inc_dec_b equals NAND of inputs from the previous cycle (when previous cycle not in reset).
  check_inc_dec_b_captures_prev_nand: assert property (
    @(posedge clk) disable iff (rst) $past(!rst) |-> inc_dec_b == ~( $past(cfg_err_cpl_timeout_n) & $past(decr_nfl) )
  );
  // Any change on inc_dec_b reflects a change in previous-cycle NAND of inputs.
  check_inc_dec_b_change_matches_prev_input_change: assert property (
    @(posedge clk) disable iff (rst)
      $past(!rst,1) && $past(!rst,2) && $changed(inc_dec_b)
      |-> ($past(~(cfg_err_cpl_timeout_n & decr_nfl),1) != $past(~(cfg_err_cpl_timeout_n & decr_nfl),2))
  );
  // If previous-cycle NAND of inputs is unchanged, inc_dec_b does not change.
  check_inc_dec_b_no_change_if_prev_input_nand_unchanged: assert property (
    @(posedge clk) disable iff (rst)
      $past(!rst,1) && $past(!rst,2) && ($past(~(cfg_err_cpl_timeout_n & decr_nfl),1) == $past(~(cfg_err_cpl_timeout_n & decr_nfl),2))
      |-> !$changed(inc_dec_b)
  );

  ///// Consistency checks for inc_dec_b values /////
  // inc_dec_b can be 0 only if both inputs were 1 in the previous cycle.
  check_inc_dec_b_zero_only_on_prev_both_high: assert property (
    @(posedge clk) disable iff (rst) ($past(!rst) && (inc_dec_b == 1'b0)) |-> ($past(cfg_err_cpl_timeout_n) && $past(decr_nfl))
  );
  // inc_dec_b is 1 if at least one previous input was 0.
  check_inc_dec_b_one_on_prev_not_both_high: assert property (
    @(posedge clk) disable iff (rst) ($past(!rst) && (inc_dec_b == 1'b1)) |-> !($past(cfg_err_cpl_timeout_n) && $past(decr_nfl))
  );

endmodule

rtl:
module button_counter (
   input  wire        BTN,
   output reg  [3:0]  COUNT
);

   always @(posedge BTN) begin
      if (COUNT == 15)
         COUNT <= 0;
      else
         COUNT <= COUNT + 1;
   end

endmodule

sva:
module button_counter_sva (
    input logic        BTN,
    input logic [3:0]  COUNT
);
    // When previous COUNT was not 15, next BTN edge increments by 1.
    check_inc_when_prev_not_15: assert property (
        @(posedge BTN) 1'b1 |=> ( ($past(COUNT) != 4'd15) |-> (COUNT == $past(COUNT) + 4'd1) )
    );

    // When previous COUNT was 15, next BTN edge wraps to 0.
    check_wrap_when_prev_15: assert property (
        @(posedge BTN) 1'b1 |=> ( ($past(COUNT) == 4'd15) |-> (COUNT == 4'd0) )
    );

    // COUNT must change on every BTN rising edge.
    check_count_changes_each_pulse: assert property (
        @(posedge BTN) 1'b1 |=> ( ($past(COUNT) == $past(COUNT)) |-> (COUNT != $past(COUNT)) )
    );

    // After 16 BTN edges, COUNT repeats its value (mod-16 behavior).
    check_period_16: assert property (
        @(posedge BTN) 1'b1 |-> ##16 (COUNT == $past(COUNT,16))
    );
endmodule

rtl:
module combinational_logic(
    input wire A,
    input wire B,
    input wire C,
    input wire D,
    output reg X,
    output reg Y
);

always @(*) begin
    if (A) begin
        X = 1'b1;
        Y = 1'b0;
    end else begin
        if (B || (C && !D)) begin
            X = 1'b1;
        end else begin
            X = 1'b0;
        end
        if (!B || (C && D)) begin
            Y = 1'b1;
        end else begin
            Y = 1'b0;
        end
    end
end

endmodule

sva:
module combinational_logic_sva (
    input logic CLK,
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic X,
    input logic Y
);
    // X equals A || B || (C && !D)
    check_X_function: assert property (
        @(posedge CLK) disable iff (1'b0) X == (A || B || (C && !D))
    );

    // Y equals !A && (!B || (C && D))
    check_Y_function: assert property (
        @(posedge CLK) disable iff (1'b0) Y == ((!A) && ((!B) || (C && D)))
    );

    // When A is 1, X=1 and Y=0
    check_A_forces_outputs: assert property (
        @(posedge CLK) disable iff (1'b0) A |-> (X == 1'b1) && (Y == 1'b0)
    );

    // When A is 0, X equals B || (C && !D)
    check_notA_X_definition: assert property (
        @(posedge CLK) disable iff (1'b0) (!A) |-> (X == (B || (C && !D)))
    );

    // When A is 0, Y equals !B || (C && D)
    check_notA_Y_definition: assert property (
        @(posedge CLK) disable iff (1'b0) (!A) |-> (Y == ((!B) || (C && D)))
    );

    // When A=0 and B=1, X=1 and Y=(C && D)
    check_notA_B1: assert property (
        @(posedge CLK) disable iff (1'b0) (!A && B) |-> (X == 1'b1) && (Y == (C && D))
    );

    // When A=0 and B=0, X=(C && !D) and Y=1
    check_notA_B0: assert property (
        @(posedge CLK) disable iff (1'b0) (!A && !B) |-> (X == (C && !D)) && (Y == 1'b1)
    );

    // When A=0 and C=0, X=B and Y=!B
    check_notA_C0: assert property (
        @(posedge CLK) disable iff (1'b0) (!A && !C) |-> (X == B) && (Y == !B)
    );

    // When A=0, C=1, D=0, X=1 and Y=!B
    check_notA_C1_D0: assert property (
        @(posedge CLK) disable iff (1'b0) (!A && C && !D) |-> (X == 1'b1) && (Y == !B)
    );

    // When A=0, C=1, D=1, X=B and Y=1
    check_notA_C1_D1: assert property (
        @(posedge CLK) disable iff (1'b0) (!A && C && D) |-> (X == B) && (Y == 1'b1)
    );
endmodule

rtl:
module mux_4to1_enable (
  input [3:0] in,
  input [1:0] sel,
  input enable,
  output reg out
);

always @ (sel or in or enable) begin
  if (enable == 1'b1) begin
    case (sel)
      2'b00: out = in[0];
      2'b01: out = in[1];
      2'b10: out = in[2];
      2'b11: out = in[3];
      default: out = 1'b0;
    endcase
  end else begin
    out = 1'b0;
  end
end

endmodule

sva:
module mux_4to1_enable_sva (
  input logic [3:0] in,
  input logic [1:0] sel,
  input logic enable,
  input logic out
);

  // When disabled, out must be 0.
  check_out_zero_when_disabled: assert property (
    @(posedge enable or negedge enable
      or posedge sel[0] or negedge sel[0] or posedge sel[1] or negedge sel[1]
      or posedge in[0] or negedge in[0] or posedge in[1] or negedge in[1]
      or posedge in[2] or negedge in[2] or posedge in[3] or negedge in[3])
    (enable == 1'b0) |-> (out == 1'b0)
  );

  // When enabled and sel==00, out equals in[0].
  check_sel_00_mapping: assert property (
    @(posedge enable or negedge enable
      or posedge sel[0] or negedge sel[0] or posedge sel[1] or negedge sel[1]
      or posedge in[0] or negedge in[0] or posedge in[1] or negedge in[1]
      or posedge in[2] or negedge in[2] or posedge in[3] or negedge in[3])
    (enable && (sel == 2'b00)) |-> (out == in[0])
  );

  // When enabled and sel==01, out equals in[1].
  check_sel_01_mapping: assert property (
    @(posedge enable or negedge enable
      or posedge sel[0] or negedge sel[0] or posedge sel[1] or negedge sel[1]
      or posedge in[0] or negedge in[0] or posedge in[1] or negedge in[1]
      or posedge in[2] or negedge in[2] or posedge in[3] or negedge in[3])
    (enable && (sel == 2'b01)) |-> (out == in[1])
  );

  // When enabled and sel==10, out equals in[2].
  check_sel_10_mapping: assert property (
    @(posedge enable or negedge enable
      or posedge sel[0] or negedge sel[0] or posedge sel[1] or negedge sel[1]
      or posedge in[0] or negedge in[0] or posedge in[1] or negedge in[1]
      or posedge in[2] or negedge in[2] or posedge in[3] or negedge in[3])
    (enable && (sel == 2'b10)) |-> (out == in[2])
  );

  // When enabled and sel==11, out equals in[3].
  check_sel_11_mapping: assert property (
    @(posedge enable or negedge enable
      or posedge sel[0] or negedge sel[0] or posedge sel[1] or negedge sel[1]
      or posedge in[0] or negedge in[0] or posedge in[1] or negedge in[1]
      or posedge in[2] or negedge in[2] or posedge in[3] or negedge in[3])
    (enable && (sel == 2'b11)) |-> (out == in[3])
  );

  // When enabled and sel is not 00/01/10/11 (X/Z), out is 0.
  check_unknown_sel_defaults_zero: assert property (
    @(posedge enable or negedge enable
      or posedge sel[0] or negedge sel[0] or posedge sel[1] or negedge sel[1]
      or posedge in[0] or negedge in[0] or posedge in[1] or negedge in[1]
      or posedge in[2] or negedge in[2] or posedge in[3] or negedge in[3])
    (enable && (sel !== 2'b00) && (sel !== 2'b01) && (sel !== 2'b10) && (sel !== 2'b11)) |-> (out == 1'b0)
  );

  // On rising edge of enable, out reflects selected input (or 0 if sel is X/Z).
  check_out_on_enable_rise: assert property (
    @(posedge enable)
      1'b1 |-> (
        (sel == 2'b00 && out == in[0]) ||
        (sel == 2'b01 && out == in[1]) ||
        (sel == 2'b10 && out == in[2]) ||
        (sel == 2'b11 && out == in[3]) ||
        ((sel !== 2'b00) && (sel !== 2'b01) && (sel !== 2'b10) && (sel !== 2'b11) && (out == 1'b0))
      )
  );

  // On falling edge of enable, out must be 0.
  check_out_on_enable_fall_zero: assert property (
    @(negedge enable) 1'b1 |-> (out == 1'b0)
  );

  // Changing in[0] while enabled with sel not 00 does not change out.
  check_unselected_in0_no_effect: assert property (
    @(posedge in[0] or negedge in[0])
    (enable && ((sel == 2'b01) || (sel == 2'b10) || (sel == 2'b11))) |-> $stable(out)
  );

  // Changing in[1] while enabled with sel not 01 does not change out.
  check_unselected_in1_no_effect: assert property (
    @(posedge in[1] or negedge in[1])
    (enable && ((sel == 2'b00) || (sel == 2'b10) || (sel == 2'b11))) |-> $stable(out)
  );

  // Changing in[2] while enabled with sel not 10 does not change out.
  check_unselected_in2_no_effect: assert property (
    @(posedge in[2] or negedge in[2])
    (enable && ((sel == 2'b00) || (sel == 2'b01) || (sel == 2'b11))) |-> $stable(out)
  );

  // Changing in[3] while enabled with sel not 11 does not change out.
  check_unselected_in3_no_effect: assert property (
    @(posedge in[3] or negedge in[3])
    (enable && ((sel == 2'b00) || (sel == 2'b01) || (sel == 2'b10))) |-> $stable(out)
  );

endmodule

rtl:
module U2 (
    input [7:0] A,
    input [7:0] B,
    output [7:0] OUT
);

    reg [7:0] out_reg;

    always @(*) begin
        out_reg = (A >= B) ? (A - B) : (B - A);
    end

    assign OUT = out_reg;

endmodule

sva:
module U2_sva (
    input logic CLK,
    input logic [7:0] A,
    input logic [7:0] B,
    input logic [7:0] OUT
);

    // OUT equals absolute difference of A and B.
    check_abs_difference_function: assert property (
        @(posedge CLK) OUT == ((A >= B) ? (A - B) : (B - A))
    );

    // When A >= B, OUT equals A - B.
    check_case_A_ge_B: assert property (
        @(posedge CLK) (A >= B) |-> (OUT == (A - B))
    );

    // When A < B, OUT equals B - A.
    check_case_B_gt_A: assert property (
        @(posedge CLK) (A < B) |-> (OUT == (B - A))
    );

    // Equal inputs produce zero output.
    check_equal_inputs_zero_out: assert property (
        @(posedge CLK) (A == B) |-> (OUT == 8'd0)
    );

    // Zero output implies inputs are equal.
    check_zero_out_implies_equal: assert property (
        @(posedge CLK) (OUT == 8'd0) |-> (A == B)
    );

    // If B is zero, OUT equals A.
    check_B_zero_out_eq_A: assert property (
        @(posedge CLK) (B == 8'd0) |-> (OUT == A)
    );

    // If A is zero, OUT equals B.
    check_A_zero_out_eq_B: assert property (
        @(posedge CLK) (A == 8'd0) |-> (OUT == B)
    );

    // Result never exceeds A when A >= B.
    check_out_le_max_when_A_ge_B: assert property (
        @(posedge CLK) (A >= B) |-> (OUT <= A)
    );

    // Result never exceeds B when A < B.
    check_out_le_max_when_B_gt_A: assert property (
        @(posedge CLK) (A < B) |-> (OUT <= B)
    );

    // Min plus OUT equals max.
    check_min_plus_out_equals_max: assert property (
        @(posedge CLK) ((A >= B) ? ((OUT + B) == A) : ((OUT + A) == B))
    );

    // OUT equals one of the two directed differences.
    check_out_is_one_of_two_diffs: assert property (
        @(posedge CLK) (OUT == (A - B)) || (OUT == (B - A))
    );

endmodule

rtl:
module up_counter (clk, rst, count_out);
   input clk, rst;
   output reg [3:0] count_out;

   always @(posedge clk) begin
      if (rst) begin
         count_out <= 4'b0000;
      end else begin
         count_out <= count_out + 1;
      end
   end

endmodule

sva:
module up_counter_sva (
    input logic clk,
    input logic rst,
    input logic [3:0] count_out
);

    // On the first cycle after reset deasserts, count_out is 0.
    check_reset_release_zero: assert property (
        @(posedge clk) disable iff (rst)
        $past(rst) && !rst |-> (count_out == 4'd0)
    );

    // When not in reset for two consecutive cycles, count_out increments by 1.
    check_increment_no_reset: assert property (
        @(posedge clk) disable iff (rst)
        !$past(rst) && !rst |-> (count_out == $past(count_out) + 4'd1)
    );

    // Without reset, wrap from 0xF to 0x0 on the next cycle.
    check_wrap_from_f_to_0: assert property (
        @(posedge clk) disable iff (rst)
        !$past(rst) && !rst && ($past(count_out) == 4'hF) |-> (count_out == 4'h0)
    );

    // LSB toggles every non-reset cycle.
    check_lsb_toggles: assert property (
        @(posedge clk) disable iff (rst)
        !$past(rst) && !rst |-> (count_out[0] == ~$past(count_out[0]))
    );

    // Bit1 toggles when there is a carry from bit0.
    check_bit1_toggle_on_carry: assert property (
        @(posedge clk) disable iff (rst)
        !$past(rst) && !rst && $past(count_out[0]) |-> (count_out[1] == ~$past(count_out[1]))
    );

    // Bit1 holds when there is no carry from bit0.
    check_bit1_stable_no_carry: assert property (
        @(posedge clk) disable iff (rst)
        !$past(rst) && !rst && !$past(count_out[0]) |-> (count_out[1] == $past(count_out[1]))
    );

    // Bit2 toggles when there is a carry from bits[1:0].
    check_bit2_toggle_on_carry: assert property (
        @(posedge clk) disable iff (rst)
        !$past(rst) && !rst && ($past(count_out[1:0]) == 2'b11) |-> (count_out[2] == ~$past(count_out[2]))
    );

    // Bit2 holds when there is no carry from bits[1:0].
    check_bit2_stable_no_carry: assert property (
        @(posedge clk) disable iff (rst)
        !$past(rst) && !rst && ($past(count_out[1:0]) != 2'b11) |-> (count_out[2] == $past(count_out[2]))
    );

    // Bit3 toggles when there is a carry from bits[2:0].
    check_bit3_toggle_on_carry: assert property (
        @(posedge clk) disable iff (rst)
        !$past(rst) && !rst && ($past(count_out[2:0]) == 3'b111) |-> (count_out[3] == ~$past(count_out[3]))
    );

    // Bit3 holds when there is no carry from bits[2:0].
    check_bit3_stable_no_carry: assert property (
        @(posedge clk) disable iff (rst)
        !$past(rst) && !rst && ($past(count_out[2:0]) != 3'b111) |-> (count_out[3] == $past(count_out[3]))
    );

endmodule

rtl:
module top_module (
    input clk,
    input signed [31:0] a,
    input signed [31:0] b,
    input [7:0] input1,
    input [7:0] input2,
    input control,
    output [1:0] result,
    output signed [31:0] sum
);

    wire signed [15:0] mul8_out;
    wire and_gate_out;
    wire or_gate_out;

    mul8 mul8_inst (
        .a(input1),
        .b(input2),
        .product(mul8_out)
    );

    and_gate and_gate_inst (
        .a(input1[0] & input2[0]),
        .b(input1[1] & input2[1]),
        .out(and_gate_out)
    );

    reg [1:0] result_reg;
    reg [31:0] sum_reg;
    reg or_gate_out_reg;

    always @ (posedge clk) begin
        case (control)
            0: result_reg <= {and_gate_out, 1'b0};
            1: result_reg <= {or_gate_out, 1'b0};
        endcase
        sum_reg <= a + b + {16'd0, mul8_out};
        or_gate_out_reg <= input1 | input2;
    end

    assign result = result_reg;
    assign sum = sum_reg;
    assign or_gate_out = or_gate_out_reg;

endmodule

module mul8 (
    input signed [7:0] a,
    input signed [7:0] b,
    output signed [15:0] product
);

    assign product = a * b;

endmodule

module and_gate (
    input a,
    input b,
    output out
);

    assign out = a & b;

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic signed [31:0] a,
    input logic signed [31:0] b,
    input logic [7:0] input1,
    input logic [7:0] input2,
    input logic control,
    input logic [1:0] result,
    input logic signed [31:0] sum
);
    // Helper expressions for readability
    let and_two_bits = ( (input1[0] & input2[0]) & (input1[1] & input2[1]) );
    let or_lsb       = ( input1[0] | input2[0] );
    let prod16       = ( $signed(input1) * $signed(input2) );              // 16-bit signed
    let zext_prod32  = {16'd0, prod16[15:0]};                              // zero-extend to 32

    ///// result_reg behavior /////
    // result[0] is always driven LOW by the sequential logic.
    check_result_lsb_zero: assert property (
        @(posedge clk) result[0] == 1'b0
    );

    // When previous control was 0, result[1] equals previous AND of selected input bits.
    check_result_sel0_msb: assert property (
        @(posedge clk) ($past(control) == 1'b0) |-> (result[1] == $past(and_two_bits))
    );

    // When previous control was 0, full result vector matches {AND,0}.
    check_result_sel0_full: assert property (
        @(posedge clk) ($past(control) == 1'b0) |-> (result == {$past(and_two_bits), 1'b0})
    );

    // When previous control was 1, result[1] equals the OR(LSB) from two cycles ago (due to extra register).
    check_result_sel1_msb: assert property (
        @(posedge clk) ($past(control) == 1'b1) |-> (result[1] == $past($past(or_lsb)))
    );

    // When previous control was 1, full result vector matches {OR(LSB from two cycles ago),0}.
    check_result_sel1_full: assert property (
        @(posedge clk) ($past(control) == 1'b1) |-> (result == {$past($past(or_lsb)), 1'b0})
    );

    ///// sum_reg behavior /////
    // sum equals a + b + zero-extended 16-bit signed product of input1*input2 from previous cycle.
    check_sum_update: assert property (
        @(posedge clk) sum == $past(a + b + zext_prod32)
    );

    // The contribution (sum - a - b) equals the zero-extended product from previous cycle.
    check_sum_contribution_exact: assert property (
        @(posedge clk) (sum - $past(a) - $past(b)) == $past(zext_prod32)
    );

    // The upper 16 bits of (sum - a - b) are always zero (due to zero-extension).
    check_sum_contribution_upper_zero: assert property (
        @(posedge clk) (sum - $past(a) - $past(b))[31:16] == 16'h0000
    );

    // The lower 16 bits of (sum - a - b) equal the product's lower 16 bits from previous cycle.
    check_sum_contribution_lower_match: assert property (
        @(posedge clk) (sum - $past(a) - $past(b))[15:0] == $past(prod16[15:0])
    );

endmodule

rtl:
module generate_output_signals(input VPWR, input VGND, output VDD, output VSS, output VDD_VSS);

    assign VDD = (VPWR == 1'b1 && VGND == 1'b0) ? 1'b1 : 1'b0;
    assign VSS = (VGND == 1'b1 && VPWR == 1'b0) ? 1'b1 : 1'b0;
    assign VDD_VSS = (VDD == 1'b1 && VSS == 1'b1) ? 1'b1 : 1'b0;

endmodule

sva:
module generate_output_signals_sva (
    input logic VPWR,
    input logic VGND,
    input logic VDD,
    input logic VSS,
    input logic VDD_VSS
);
    // VDD matches RTL function (sampled on VPWR rising edge).
    check_vdd_def_vpwr: assert property (
        @(posedge VPWR) VDD === (((VPWR == 1'b1) && (VGND == 1'b0)) ? 1'b1 : 1'b0)
    );

    // VDD matches RTL function (sampled on VGND rising edge).
    check_vdd_def_vgnd: assert property (
        @(posedge VGND) VDD === (((VPWR == 1'b1) && (VGND == 1'b0)) ? 1'b1 : 1'b0)
    );

    // VSS matches RTL function (sampled on VPWR rising edge).
    check_vss_def_vpwr: assert property (
        @(posedge VPWR) VSS === (((VGND == 1'b1) && (VPWR == 1'b0)) ? 1'b1 : 1'b0)
    );

    // VSS matches RTL function (sampled on VGND rising edge).
    check_vss_def_vgnd: assert property (
        @(posedge VGND) VSS === (((VGND == 1'b1) && (VPWR == 1'b0)) ? 1'b1 : 1'b0)
    );

    // VDD_VSS matches RTL function (sampled on VPWR rising edge).
    check_vdd_vss_def_vpwr: assert property (
        @(posedge VPWR) VDD_VSS === (((VDD == 1'b1) && (VSS == 1'b1)) ? 1'b1 : 1'b0)
    );

    // VDD_VSS matches RTL function (sampled on VGND rising edge).
    check_vdd_vss_def_vgnd: assert property (
        @(posedge VGND) VDD_VSS === (((VDD == 1'b1) && (VSS == 1'b1)) ? 1'b1 : 1'b0)
    );

    // If VDD is HIGH then VSS must be LOW (sampled on VPWR rising edge).
    vdd_high_implies_vss_low_vpwr: assert property (
        @(posedge VPWR) (VDD === 1'b1) |-> (VSS === 1'b0)
    );

    // If VDD is HIGH then VSS must be LOW (sampled on VGND rising edge).
    vdd_high_implies_vss_low_vgnd: assert property (
        @(posedge VGND) (VDD === 1'b1) |-> (VSS === 1'b0)
    );

    // If VSS is HIGH then VDD must be LOW (sampled on VPWR rising edge).
    vss_high_implies_vdd_low_vpwr: assert property (
        @(posedge VPWR) (VSS === 1'b1) |-> (VDD === 1'b0)
    );

    // If VSS is HIGH then VDD must be LOW (sampled on VGND rising edge).
    vss_high_implies_vdd_low_vgnd: assert property (
        @(posedge VGND) (VSS === 1'b1) |-> (VDD === 1'b0)
    );
endmodule

rtl:
module mux_2to1(
    input A,
    input B,
    input S,
    output Y
);

assign Y = (S == 1) ? B : A;

endmodule

sva:
module mux_2to1_sva (
    input logic clk,    // sampling clock for assertions
    input logic A,
    input logic B,
    input logic S,
    input logic Y
);

    // Y must equal selected input per S.
    check_mux_function: assert property (
        @(posedge clk) Y == (S ? B : A)
    );

    // When S==0, Y equals A.
    check_select_zero_path: assert property (
        @(posedge clk) (S == 1'b0) |-> (Y == A)
    );

    // When S==1, Y equals B.
    check_select_one_path: assert property (
        @(posedge clk) (S == 1'b1) |-> (Y == B)
    );

    // If A,B,S are unchanged from last cycle, Y must be unchanged.
    check_stable_when_inputs_stable: assert property (
        @(posedge clk)
            (!$isunknown($past(A)) && !$isunknown($past(B)) && !$isunknown($past(S)) && !$isunknown($past(Y)) &&
             (A == $past(A)) && (B == $past(B)) && (S == $past(S))) |-> (Y == $past(Y))
    );

    // With S held at 0 across cycles, a change on A is reflected on Y.
    check_follow_A_when_S0: assert property (
        @(posedge clk)
            (!$isunknown($past(S)) &&
             ($past(S) == 1'b0) && (S == 1'b0) &&
             !$isunknown($past(A)) && (A != $past(A))) |-> (Y == A)
    );

    // With S held at 1 across cycles, a change on B is reflected on Y.
    check_follow_B_when_S1: assert property (
        @(posedge clk)
            (!$isunknown($past(S)) &&
             ($past(S) == 1'b1) && (S == 1'b1) &&
             !$isunknown($past(B)) && (B != $past(B))) |-> (Y == B)
    );

    // With S held at 0 and A stable, changes on B do not affect Y.
    check_ignore_B_when_S0: assert property (
        @(posedge clk)
            (!$isunknown($past(S)) && !$isunknown($past(A)) && !$isunknown($past(B)) && !$isunknown($past(Y)) &&
             ($past(S) == 1'b0) && (S == 1'b0) &&
             (A == $past(A)) && (B != $past(B))) |-> (Y == $past(Y))
    );

    // With S held at 1 and B stable, changes on A do not affect Y.
    check_ignore_A_when_S1: assert property (
        @(posedge clk)
            (!$isunknown($past(S)) && !$isunknown($past(A)) && !$isunknown($past(B)) && !$isunknown($past(Y)) &&
             ($past(S) == 1'b1) && (S == 1'b1) &&
             (B == $past(B)) && (A != $past(A))) |-> (Y == $past(Y))
    );

endmodule

rtl:
module mux4_1(
    input [3:0] in,
    input [1:0] sel,
    output reg out
);

    always @(*) begin
        case(sel)
            2'b00: out = in[0];
            2'b01: out = in[1];
            2'b10: out = in[2];
            2'b11: out = in[3];
        endcase
    end

endmodule

sva:
module mux4_1_sva (
    input logic CLK,
    input logic [3:0] in,
    input logic [1:0] sel,
    input logic out
);
    ///// Functional mapping /////
    // When sel==00, out equals in[0].
    check_sel_00_routes_in0: assert property (
        @(posedge CLK) disable iff (1'b0) (sel == 2'b00) |-> (out == in[0])
    );
    // When sel==01, out equals in[1].
    check_sel_01_routes_in1: assert property (
        @(posedge CLK) disable iff (1'b0) (sel == 2'b01) |-> (out == in[1])
    );
    // When sel==10, out equals in[2].
    check_sel_10_routes_in2: assert property (
        @(posedge CLK) disable iff (1'b0) (sel == 2'b10) |-> (out == in[2])
    );
    // When sel==11, out equals in[3].
    check_sel_11_routes_in3: assert property (
        @(posedge CLK) disable iff (1'b0) (sel == 2'b11) |-> (out == in[3])
    );
    // Out equals the bit of 'in' indexed by 'sel' at all times.
    check_out_matches_dynamic_index: assert property (
        @(posedge CLK) disable iff (1'b0) (out == in[sel])
    );

    ///// Stability and change behavior /////
    // If inputs 'in' and 'sel' are stable, 'out' remains stable.
    check_stability_when_inputs_stable: assert property (
        @(posedge CLK) disable iff (1'b0) ($stable(in) && $stable(sel)) |-> $stable(out)
    );
    // If 'sel' and the selected input bit are stable, 'out' is stable.
    check_no_spurious_change_with_sel_and_selected_input_stable: assert property (
        @(posedge CLK) disable iff (1'b0) ($stable(sel) && $stable(in[sel])) |-> $stable(out)
    );
    // If 'sel' is stable and the selected input bit changes, 'out' changes.
    check_out_changes_when_selected_input_changes: assert property (
        @(posedge CLK) disable iff (1'b0) ($stable(sel) && !$stable(in[sel])) |-> !$stable(out)
    );
    // If 'sel' is stable and 'out' changes, the selected input bit changed.
    check_selected_input_change_needed_for_out_change: assert property (
        @(posedge CLK) disable iff (1'b0) ($stable(sel) && !$stable(out)) |-> !$stable(in[sel])
    );
endmodule

rtl:
module up_counter_with_reset_and_load (
    input clk,
    input reset,
    input load,
    output reg [7:0] count
);

    always @(posedge clk) begin
        if (reset) begin
            count <= 0;
        end
        else if (load) begin
            count <= 8'd0;
        end
        else begin
            count <= count + 1;
        end
    end

endmodule
module up_down_counter_with_load (
    input clk,
    input load,
    input up_down,
    output reg [7:0] count
);

    always @(posedge clk) begin
        if (load) begin
            count <= 8'd0;
        end
        else if (up_down) begin
            count <= count + 1;
        end
        else begin
            count <= count - 1;
        end
    end

endmodule
module summing_module (
    input [7:0] count1,
    input [7:0] count2,
    output reg [7:0] sum
);

    always @(count1 or count2) begin
        sum <= count1 + count2;
    end

endmodule
module top_module (
    input clk,
    input reset,
    input load,
    input up_down,
    input [3:0] data_in,
    output [7:0] data_out
);

    reg [7:0] count1;
    reg [7:0] count2;
    wire [7:0] sum;

    up_counter_with_reset_and_load up_counter (
        .clk(clk),
        .reset(reset),
        .load(load),
        .count(count1)
    );

    up_down_counter_with_load up_down_counter (
        .clk(clk),
        .load(load),
        .up_down(up_down),
        .count(count2)
    );

    summing_module summing (
        .count1(count1),
        .count2(count2),
        .sum(sum)
    );

    assign data_out = sum;

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic reset,
    input logic load,
    input logic up_down,
    input logic [3:0] data_in,
    input logic [7:0] data_out,
    input logic [7:0] count1,   // top_module internal
    input logic [7:0] count2,   // top_module internal
    input logic [7:0] sum       // top_module internal
);

    ///// up_counter_with_reset_and_load /////
    // Synchronous reset drives count1 to 0.
    check_count1_resets_to_zero: assert property (
        @(posedge clk) reset |-> (count1 == 8'd0)
    );
    // load drives count1 to 0 when not in reset.
    check_count1_load_clears: assert property (
        @(posedge clk) disable iff (reset) load |-> (count1 == 8'd0)
    );
    // When neither reset nor load, count1 increments by 1 each cycle.
    check_count1_inc_when_no_reset_load: assert property (
        @(posedge clk) disable iff (reset) (!load) |-> (count1 == $past(count1) + 8'd1)
    );

    ///// up_down_counter_with_load /////
    // load drives count2 to 0.
    check_count2_load_clears: assert property (
        @(posedge clk) disable iff (reset) load |-> (count2 == 8'd0)
    );
    // When !load and up_down=1, count2 increments by 1.
    check_count2_inc_when_up_no_load: assert property (
        @(posedge clk) disable iff (reset) (!load && up_down) |-> (count2 == $past(count2) + 8'd1)
    );
    // When !load and up_down=0, count2 decrements by 1.
    check_count2_dec_when_down_no_load: assert property (
        @(posedge clk) disable iff (reset) (!load && !up_down) |-> (count2 == $past(count2) - 8'd1)
    );

    ///// summing_module and top-level wiring /////
    // sum equals truncated 8-bit addition of count1 and count2.
    check_sum_matches_truncated_add: assert property (
        @(posedge clk) disable iff (reset) sum == ((count1 + count2) & 9'h0FF)
    );
    // data_out is driven by sum.
    check_data_out_eq_sum: assert property (
        @(posedge clk) disable iff (reset) data_out == sum
    );
    // When !reset, !load, and up_down=1, sum advances by +2 modulo 256.
    check_sum_advances_by_two_on_up: assert property (
        @(posedge clk) disable iff (reset) (!load && up_down) |-> (sum == (($past(sum) + 8'd2) & 9'h0FF))
    );
    // When !reset, !load, and up_down=0, sum is unchanged.
    check_sum_stable_on_down: assert property (
        @(posedge clk) disable iff (reset) (!load && !up_down) |-> (sum == $past(sum))
    );

endmodule

rtl:
module AND3 (A, B, C, Z);
input  A ;
input  B ;
input  C ;
output Z ;

   wire  I0_out;
   wire  I1_out;

   and  (I0_out, A, B);
   and  (I1_out, I0_out, C);
   assign Z = I1_out;

endmodule

sva:
module AND3_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic C,
    input logic Z
);
    // Z must equal A & B & C every cycle.
    check_z_is_and_equivalence: assert property (
        @(posedge clk) disable iff (1'b0) Z == (A & B & C)
    );

    // When all inputs are HIGH, Z must be HIGH.
    check_all_high_implies_z_high: assert property (
        @(posedge clk) disable iff (1'b0) (A & B & C) |-> Z
    );

    // If Z is HIGH, all inputs must be HIGH.
    check_z_high_implies_all_high: assert property (
        @(posedge clk) disable iff (1'b0) Z |-> (A & B & C)
    );

    // A rising with B and C HIGH causes Z to rise.
    check_rose_a_causes_rose_z: assert property (
        @(posedge clk) disable iff (1'b0) ($rose(A) && B && C) |-> $rose(Z)
    );

    // B rising with A and C HIGH causes Z to rise.
    check_rose_b_causes_rose_z: assert property (
        @(posedge clk) disable iff (1'b0) ($rose(B) && A && C) |-> $rose(Z)
    );

    // C rising with A and B HIGH causes Z to rise.
    check_rose_c_causes_rose_z: assert property (
        @(posedge clk) disable iff (1'b0) ($rose(C) && A && B) |-> $rose(Z)
    );

    // A rise, B rise, or C rise must occur when Z rises.
    check_rose_z_implies_some_input_rose: assert property (
        @(posedge clk) disable iff (1'b0) $rose(Z) |-> ($rose(A) || $rose(B) || $rose(C))
    );

    // A fall, B fall, or C fall must occur when Z falls.
    check_fell_z_implies_some_input_fell: assert property (
        @(posedge clk) disable iff (1'b0) $fell(Z) |-> ($fell(A) || $fell(B) || $fell(C))
    );

    // If inputs are stable across a cycle, Z must be stable.
    check_stable_inputs_imply_stable_z: assert property (
        @(posedge clk) disable iff (1'b0) $stable({A,B,C}) |=> $stable(Z)
    );
endmodule

