module INV_X1 (A, ZN);
  input A;
  output ZN;

  assign ZN = ~A;
endmodule
module NAND2_X1 (A1, A2, ZN);
  input A1, A2;
  output ZN;

  assign ZN = ~(A1 & A2);
endmodule
module g_3 (g, p, g_prec, g_out);
  input g, p, g_prec;
  output g_out;
  wire n5, n6;

  INV_X1 U1 (.A(g), .ZN(n6));
  NAND2_X1 U2 (.A1(n5), .A2(n6), .ZN(g_out));
  NAND2_X1 U3 (.A1(g_prec), .A2(p), .ZN(n5));

endmodule

sva:
module g_3_sva (
    input logic CLK,
    input logic RESETn,
    input logic g,
    input logic p,
    input logic g_prec,
    input logic g_out
);
    ///// Functional equivalence /////
    // g_out implements g | (g_prec & p).
    check_functional_equivalence: assert property (
        @(posedge CLK) disable iff (!RESETn) (g_out == (g | (g_prec & p)))
    );

    ///// Basic implications /////
    // If g is 1, g_out must be 1.
    check_g_high_forces_one: assert property (
        @(posedge CLK) disable iff (!RESETn) (g == 1'b1) |-> (g_out == 1'b1)
    );
    // If g_prec and p are both 1, g_out must be 1.
    check_gprec_and_p_high_implies_one: assert property (
        @(posedge CLK) disable iff (!RESETn) ((g_prec == 1'b1) && (p == 1'b1)) |-> (g_out == 1'b1)
    );

    ///// Pass-through conditions /////
    // When p is 0, g_out equals g.
    check_p_zero_pass_g: assert property (
        @(posedge CLK) disable iff (!RESETn) (p == 1'b0) |-> (g_out == g)
    );
    // When g_prec is 0, g_out equals g.
    check_gprec_zero_pass_g: assert property (
        @(posedge CLK) disable iff (!RESETn) (g_prec == 1'b0) |-> (g_out == g)
    );
    // When p is 1, g_out equals g | g_prec.
    check_p_one_or_logic: assert property (
        @(posedge CLK) disable iff (!RESETn) (p == 1'b1) |-> (g_out == (g | g_prec))
    );

    ///// Zero-output conditions /////
    // If g and p are 0, g_out must be 0.
    check_g_zero_p_zero_out_zero: assert property (
        @(posedge CLK) disable iff (!RESETn) ((g == 1'b0) && (p == 1'b0)) |-> (g_out == 1'b0)
    );
    // If g and g_prec are 0, g_out must be 0.
    check_g_zero_gprec_zero_out_zero: assert property (
        @(posedge CLK) disable iff (!RESETn) ((g == 1'b0) && (g_prec == 1'b0)) |-> (g_out == 1'b0)
    );

    ///// Conditional passthroughs /////
    // If g is 0 and g_prec is 1, g_out equals p.
    check_g_zero_gprec_one_pass_p: assert property (
        @(posedge CLK) disable iff (!RESETn) ((g == 1'b0) && (g_prec == 1'b1)) |-> (g_out == p)
    );
    // If g is 0 and p is 1, g_out equals g_prec.
    check_g_zero_p_one_pass_gprec: assert property (
        @(posedge CLK) disable iff (!RESETn) ((g == 1'b0) && (p == 1'b1)) |-> (g_out == g_prec)
    );
endmodule

rtl:
module adder_4bit (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] S,
    output Cout
);

    wire [3:0] sum;
    wire C1, C2, C3;

    assign sum[0] = A[0] ^ B[0] ^ Cin;
    assign C1 = (A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin);
    assign sum[1] = A[1] ^ B[1] ^ C1;
    assign C2 = (A[1] & B[1]) | (A[1] & C1) | (B[1] & C1);
    assign sum[2] = A[2] ^ B[2] ^ C2;
    assign C3 = (A[2] & B[2]) | (A[2] & C2) | (B[2] & C2);
    assign sum[3] = A[3] ^ B[3] ^ C3;
    assign Cout = (A[3] & B[3]) | (A[3] & C3) | (B[3] & C3);

    assign S = sum;

endmodule

sva:
module adder_4bit_sva (
    input logic CLK,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic Cin,
    input logic [3:0] S,
    input logic Cout
);
    // DUT has no clock/reset; pure combinational adder. Assertions sample on external CLK.

    // S equals the low 4 bits of A + B + Cin.
    check_sum_lowbits: assert property (
        @(posedge CLK) S == (A + B + Cin)[3:0]
    );

    // Cout equals the carry-out bit of A + B + Cin.
    check_cout_bit: assert property (
        @(posedge CLK) Cout == (A + B + Cin)[4]
    );

    // LSB sum equals XOR of A[0], B[0], and Cin.
    check_lsb_xor: assert property (
        @(posedge CLK) S[0] == (A[0] ^ B[0] ^ Cin)
    );

    // Adding zero (B=0 and Cin=0) passes A through with no carry.
    check_identity_when_B_zero: assert property (
        @(posedge CLK) ((B == 4'b0000) && (Cin == 1'b0)) |-> (S == A) && (Cout == 1'b0)
    );

    // Adding zero (A=0 and Cin=0) passes B through with no carry.
    check_identity_when_A_zero: assert property (
        @(posedge CLK) ((A == 4'b0000) && (Cin == 1'b0)) |-> (S == B) && (Cout == 1'b0)
    );

    // With A=0 and B=0, sum is Cin in bit0 and no carry.
    check_only_cin: assert property (
        @(posedge CLK) ((A == 4'b0000) && (B == 4'b0000)) |-> (S == {3'b000, Cin}) && (Cout == 1'b0)
    );

    // With A=0xF, B=0xF, Cin=0: sum=0xE and carry=1.
    check_max_operands_no_cin: assert property (
        @(posedge CLK) ((A == 4'hF) && (B == 4'hF) && (Cin == 1'b0)) |-> (S == 4'hE) && (Cout == 1'b1)
    );

    // With A=0xF, B=0xF, Cin=1: sum=0xF and carry=1.
    check_max_operands_with_cin: assert property (
        @(posedge CLK) ((A == 4'hF) && (B == 4'hF) && (Cin == 1'b1)) |-> (S == 4'hF) && (Cout == 1'b1)
    );

    // If inputs are stable across cycles, outputs remain stable.
    check_stable_outputs_when_inputs_stable: assert property (
        @(posedge CLK) $stable({A,B,Cin}) |-> $stable({S,Cout})
    );

    // Carry-out equals overflow comparison of A + B + Cin.
    check_cout_overflow_match: assert property (
        @(posedge CLK) Cout == ((A + B + Cin) >= 5'd16)
    );

endmodule

rtl:
module priority_encoder (
    input [2:0] in,
    output reg [7:0] out
);

always @*
begin
    case(in)
        3'b000: out = 8'b00000001;
        3'b001: out = 8'b00000010;
        3'b010: out = 8'b00000100;
        3'b011: out = 8'b00001000;
        3'b100: out = 8'b00010000;
        3'b101: out = 8'b00100000;
        3'b110: out = 8'b01000000;
        3'b111: out = 8'b10000000;
        default: out = 8'b00000000;
    endcase
end

endmodule

sva:
module priority_encoder_sva (
    input logic clk,
    input logic [2:0] in,
    input logic [7:0] out
);
    // Combinational 3->8 decoder; no reset in RTL; assertions sample on clk.

    // Output equals one-hot shift of input index.
    check_shift_equivalence: assert property (
        @(posedge clk) out == (8'b00000001 << in)
    );

    // Output is exactly one-hot.
    check_onehot_out: assert property (
        @(posedge clk) $onehot(out)
    );

    // When in==000, out==00000001.
    check_decode_000: assert property (
        @(posedge clk) (in == 3'b000) |-> (out == 8'b00000001)
    );

    // When in==001, out==00000010.
    check_decode_001: assert property (
        @(posedge clk) (in == 3'b001) |-> (out == 8'b00000010)
    );

    // When in==010, out==00000100.
    check_decode_010: assert property (
        @(posedge clk) (in == 3'b010) |-> (out == 8'b00000100)
    );

    // When in==011, out==00001000.
    check_decode_011: assert property (
        @(posedge clk) (in == 3'b011) |-> (out == 8'b00001000)
    );

    // When in==100, out==00010000.
    check_decode_100: assert property (
        @(posedge clk) (in == 3'b100) |-> (out == 8'b00010000)
    );

    // When in==101, out==00100000.
    check_decode_101: assert property (
        @(posedge clk) (in == 3'b101) |-> (out == 8'b00100000)
    );

    // When in==110, out==01000000.
    check_decode_110: assert property (
        @(posedge clk) (in == 3'b110) |-> (out == 8'b01000000)
    );

    // When in==111, out==10000000.
    check_decode_111: assert property (
        @(posedge clk) (in == 3'b111) |-> (out == 8'b10000000)
    );
endmodule

rtl:
module dff_preset_clear (
  output reg Q,
  input D,
  input C,
  input R,
  input P
);

  always @(posedge C) begin
    if (R)
      Q <= 1'b0;
    else if (P)
      Q <= 1'b1;
    else
      Q <= D;
  end

endmodule

sva:
module dff_preset_clear_sva (
    input logic Q,
    input logic D,
    input logic C,
    input logic R,
    input logic P
);
    // On posedge C, R=1 clears Q on the next clock.
    check_sync_clear: assert property (
        @(posedge C) disable iff (1'b0) R |=> (Q == 1'b0)
    );

    // On posedge C, with R=0 and P=1, Q is set to 1 on the next clock.
    check_sync_preset: assert property (
        @(posedge C) disable iff (1'b0) (!R && P) |=> (Q == 1'b1)
    );

    // On posedge C, with R=0 and P=0, Q captures D on the next clock.
    check_data_capture: assert property (
        @(posedge C) disable iff (1'b0) (!R && !P) |=> (Q == $past(D))
    );

    // If both R and P are 1, clear has priority and Q becomes 0 on the next clock.
    check_clear_priority_over_preset: assert property (
        @(posedge C) disable iff (1'b0) (R && P) |=> (Q == 1'b0)
    );

    // Next-state equation: Q equals previous cycle's muxed result of R/P/D.
    check_next_state_function: assert property (
        @(posedge C) disable iff (1'b0)
            $past(1'b1) |-> ( Q == ( $past(R) ? 1'b0 : ( $past(P) ? 1'b1 : $past(D) ) ) )
    );

    // With R=0,P=0 and D=1 at a clock, Q becomes 1 on the next clock.
    check_data1_capture: assert property (
        @(posedge C) disable iff (1'b0) (!R && !P && D) |=> (Q == 1'b1)
    );

    // With R=0,P=0 and D=0 at a clock, Q becomes 0 on the next clock.
    check_data0_capture: assert property (
        @(posedge C) disable iff (1'b0) (!R && !P && !D) |=> (Q == 1'b0)
    );

    // If previously R=0,P=0 and D==Qprev, Q holds its value now.
    check_hold_when_data_matches_prev: assert property (
        @(posedge C) disable iff (1'b0)
            ($past(1'b1) && !$past(R) && !$past(P) && ($past(D) == $past(Q))) |-> (Q == $past(Q))
    );

    // If previously R=0,P=0 and D!=Qprev, Q toggles relative to Qprev now.
    check_toggle_when_data_differs_prev: assert property (
        @(posedge C) disable iff (1'b0)
            ($past(1'b1) && !$past(R) && !$past(P) && ($past(D) != $past(Q))) |-> (Q != $past(Q))
    );

    // If previously P=1 and R=0, Q is 1 now.
    check_prev_preset_sets_q: assert property (
        @(posedge C) disable iff (1'b0)
            ($past(1'b1) && !$past(R) && $past(P)) |-> (Q == 1'b1)
    );
endmodule

rtl:
module mux2to1 (o, a, b, sel);
    output o;
    input a, b, sel;
    assign o = sel ? b : a;
endmodule

sva:
module mux2to1_sva (
    input logic CLK,
    input logic o,
    input logic a,
    input logic b,
    input logic sel
);
    // o equals selected input each cycle.
    check_mux_function: assert property (
        @(posedge CLK) o == (sel ? b : a)
    );

    // When sel=0, output equals a.
    check_sel0_path: assert property (
        @(posedge CLK) (sel == 1'b0) |-> (o == a)
    );

    // When sel=1, output equals b.
    check_sel1_path: assert property (
        @(posedge CLK) (sel == 1'b1) |-> (o == b)
    );

    // On sel rising edge, output selects b.
    check_output_on_sel_rise: assert property (
        @(posedge CLK) $rose(sel) |-> (o == b)
    );

    // On sel falling edge, output selects a.
    check_output_on_sel_fall: assert property (
        @(posedge CLK) $fell(sel) |-> (o == a)
    );

    // If a changes while sel=0, output equals a.
    check_follow_a_when_sel0: assert property (
        @(posedge CLK) $changed(a) && (sel == 1'b0) |-> (o == a)
    );

    // If b changes while sel=1, output equals b.
    check_follow_b_when_sel1: assert property (
        @(posedge CLK) $changed(b) && (sel == 1'b1) |-> (o == b)
    );

    // If inputs unchanged from last cycle, output unchanged.
    check_output_stable_with_inputs: assert property (
        @(posedge CLK) ((a == $past(a)) && (b == $past(b)) && (sel == $past(sel))) |-> (o == $past(o))
    );

    // If a==b, output equals that common value.
    check_equal_inputs_passthrough: assert property (
        @(posedge CLK) (a == b) |-> (o == a)
    );
endmodule

rtl:
module mux4(input [3:0] in, input [1:0] sel, output reg out);

always @(*) begin
    case(sel)
        2'b00: out = in[0];
        2'b01: out = in[1];
        2'b10: out = in[2];
        2'b11: out = in[3];
    endcase
end

endmodule

sva:
module mux4_sva (
    input logic clk,          // sampling clock for SVA
    input logic [3:0] in,
    input logic [1:0] sel,
    input logic out
);
    ///// Mux functional correctness /////
    // Out equals the selected input bit.
    check_mux_function: assert property (
        @(posedge clk) out == in[sel]
    );

    // When sel==00, out equals in[0].
    check_sel00_routes_in0: assert property (
        @(posedge clk) (sel == 2'b00) |-> (out == in[0])
    );

    // When sel==01, out equals in[1].
    check_sel01_routes_in1: assert property (
        @(posedge clk) (sel == 2'b01) |-> (out == in[1])
    );

    // When sel==10, out equals in[2].
    check_sel10_routes_in2: assert property (
        @(posedge clk) (sel == 2'b10) |-> (out == in[2])
    );

    // When sel==11, out equals in[3].
    check_sel11_routes_in3: assert property (
        @(posedge clk) (sel == 2'b11) |-> (out == in[3])
    );

    ///// Stability and independence /////
    // If sel and the selected input are stable, out must be stable.
    check_out_stable_when_sel_and_selected_stable: assert property (
        @(posedge clk) $stable(sel) && $stable(in[sel]) |-> $stable(out)
    );

    // If sel is stable and the selected input changes, out updates to the new selected input.
    check_out_follows_selected_input: assert property (
        @(posedge clk) $stable(sel) && (in[sel] != $past(in[sel])) |-> (out == in[sel])
    );

    // Changes on unselected inputs do not affect out when sel and selected input are stable.
    check_unselected_inputs_do_not_affect_out: assert property (
        @(posedge clk)
            $stable(sel) && $stable(in[sel]) &&
            (((in ^ $past(in)) & ~(4'b0001 << sel)) != 4'b0000)
            |-> $stable(out)
    );
endmodule

rtl:
module sky130_fd_sc_ls__xnor2 (
    input A,
    input B,
    output Y
);

assign Y = ~(A ^ B);

endmodule

sva:
module sky130_fd_sc_ls__xnor2_sva (
    input logic CLK,
    input logic A,
    input logic B,
    input logic Y
);
    // Output equals bitwise XNOR of inputs at all times.
    check_function_equivalence: assert property (
        @(posedge CLK) (Y === ~(A ^ B))
    );

    // When inputs are known and equal, output must be 1.
    check_equal_known_implies_one: assert property (
        @(posedge CLK) (! $isunknown({A,B}) && (A == B)) |-> (Y == 1'b1)
    );

    // When inputs are known and not equal, output must be 0.
    check_unequal_known_implies_zero: assert property (
        @(posedge CLK) (! $isunknown({A,B}) && (A != B)) |-> (Y == 1'b0)
    );

    // When both inputs are known, output must be known (no X/Z).
    check_known_inputs_imply_known_output: assert property (
        @(posedge CLK) (! $isunknown({A,B})) |-> (! $isunknown(Y))
    );

    // If exactly one input changed since last cycle, output must change.
    check_single_input_toggle_flips_output: assert property (
        @(posedge CLK) (($changed(A) ^ $changed(B))) |-> $changed(Y)
    );

    // If both inputs changed since last cycle, output must not change.
    check_both_inputs_toggle_keep_output: assert property (
        @(posedge CLK) ($changed(A) && $changed(B)) |-> (!$changed(Y))
    );

    // If neither input changed since last cycle, output must not change.
    check_no_input_change_keeps_output: assert property (
        @(posedge CLK) ((!$changed(A)) && (!$changed(B))) |-> (!$changed(Y))
    );
endmodule

rtl:
module floating_point_arithmetic (
  input [31:0] a,
  input [31:0] b,
  input [1:0] ctrl,
  output reg [31:0] result
);

parameter EXPONENT_WIDTH = 8;
parameter MANTISSA_WIDTH = 23;

// Define input and output formats as per IEEE 754 standard
wire [EXPONENT_WIDTH-1:0] a_exp, b_exp;
wire [MANTISSA_WIDTH-1:0] a_mant, b_mant;
wire a_sign, b_sign;
assign a_sign = a[31];
assign a_exp = a[30:23];
assign a_mant = a[22:0];
assign b_sign = b[31];
assign b_exp = b[30:23];
assign b_mant = b[22:0];

// Implement addition, subtraction, multiplication, and division using Verilog code
wire [31:0] add_result, sub_result, mul_result, div_result;
adder add(.a(a), .b(b), .result(add_result));
subtractor sub(.a(a), .b(b), .result(sub_result));
multiplier mul(.a(a), .b(b), .result(mul_result));
divider div(.a(a), .b(b), .result(div_result));

// Select the operation based on the control signal
always @(*) begin
  case (ctrl)
    2'b00: result <= add_result;
    2'b01: result <= sub_result;
    2'b10: result <= mul_result;
    2'b11: result <= div_result;
    default: result <= 32'b0;
  endcase
end

endmodule

module adder (
  input [31:0] a,
  input [31:0] b,
  output reg [31:0] result
);
always @* begin
  result = a + b;
end
endmodule

module subtractor (
  input [31:0] a,
  input [31:0] b,
  output reg [31:0] result
);
always @* begin
  result = a - b;
end
endmodule

module multiplier (
  input [31:0] a,
  input [31:0] b,
  output reg [31:0] result
);
always @* begin
  result = a * b;
end
endmodule

module divider (
  input [31:0] a,
  input [31:0] b,
  output reg [31:0] result
);
always @* begin
  result = a / b;
end
endmodule

sva:
module floating_point_arithmetic_sva (
  input logic [31:0] a,
  input logic [31:0] b,
  input logic [1:0]  ctrl,
  input logic [31:0] result
);
  // No clock/reset in RTL; use $global_clock for synchronous SVA.

  // Local reference computations matching RTL arithmetic/truncation
  logic [31:0] add_ref, sub_ref, mul_ref, div_ref;
  always_comb begin
    add_ref = a + b;
    sub_ref = a - b;
    mul_ref = a * b;
    div_ref = a / b;
  end

  ///// Operation select /////
  // ctrl==00 selects addition
  check_select_add: assert property (
    @(posedge $global_clock) (ctrl == 2'b00) |-> (result == add_ref)
  );
  // ctrl==01 selects subtraction
  check_select_sub: assert property (
    @(posedge $global_clock) (ctrl == 2'b01) |-> (result == sub_ref)
  );
  // ctrl==10 selects multiplication (truncated to 32b)
  check_select_mul: assert property (
    @(posedge $global_clock) (ctrl == 2'b10) |-> (result == mul_ref)
  );
  // ctrl==11 selects division when divisor is nonzero
  check_select_div_no_div0: assert property (
    @(posedge $global_clock) (ctrl == 2'b11 && b != 32'd0) |-> (result == div_ref)
  );

  ///// Identities and corner cases consistent with the RTL arithmetic /////
  // Adding zero on A returns B
  check_add_identity_a_zero: assert property (
    @(posedge $global_clock) (ctrl == 2'b00 && a == 32'd0) |-> (result == b)
  );
  // Adding zero on B returns A
  check_add_identity_b_zero: assert property (
    @(posedge $global_clock) (ctrl == 2'b00 && b == 32'd0) |-> (result == a)
  );
  // Subtracting zero returns A
  check_sub_identity_b_zero: assert property (
    @(posedge $global_clock) (ctrl == 2'b01 && b == 32'd0) |-> (result == a)
  );
  // Subtracting a from itself yields zero
  check_sub_self_zero: assert property (
    @(posedge $global_clock) (ctrl == 2'b01 && a == b) |-> (result == 32'd0)
  );
  // Multiplication by zero yields zero
  check_mul_zero_absorb: assert property (
    @(posedge $global_clock) (ctrl == 2'b10 && (a == 32'd0 || b == 32'd0)) |-> (result == 32'd0)
  );
  // Multiplication identity with one on A
  check_mul_identity_a_one: assert property (
    @(posedge $global_clock) (ctrl == 2'b10 && a == 32'd1) |-> (result == b)
  );
  // Multiplication identity with one on B
  check_mul_identity_b_one: assert property (
    @(posedge $global_clock) (ctrl == 2'b10 && b == 32'd1) |-> (result == a)
  );
  // Division identity by one
  check_div_identity_b_one: assert property (
    @(posedge $global_clock) (ctrl == 2'b11 && b == 32'd1) |-> (result == a)
  );
  // Zero dividend yields zero when divisor nonzero
  check_div_zero_numerator: assert property (
    @(posedge $global_clock) (ctrl == 2'b11 && a == 32'd0 && b != 32'd0) |-> (result == 32'd0)
  );

  ///// Combinational stability /////
  // If inputs and ctrl are stable, result remains stable
  check_result_stable_when_inputs_stable: assert property (
    @(posedge $global_clock) ($stable(a) && $stable(b) && $stable(ctrl)) |-> $stable(result)
  );
endmodule

module odd_parity_sva (
    input logic a,
    input logic b,
    input logic c,
    input logic out
);

    ///// Functional equivalence /////
    // out must equal a ^ b ^ c (odd parity of the three inputs).
    check_parity_xor: assert property (
        @(posedge a or negedge a or posedge b or negedge b or posedge c or negedge c)
            out == (a ^ b ^ c)
    );

    ///// Truth table checks /////
    // 0 ones: out must be 0.
    check_zero_ones: assert property (
        @(posedge a or negedge a or posedge b or negedge b or posedge c or negedge c)
            (!a && !b && !c) |-> (out == 1'b0)
    );
    // 1 one (a=1): out must be 1.
    check_one_hot_a: assert property (
        @(posedge a or negedge a or posedge b or negedge b or posedge c or negedge c)
            (a && !b && !c) |-> (out == 1'b1)
    );
    // 1 one (b=1): out must be 1.
    check_one_hot_b: assert property (
        @(posedge a or negedge a or posedge b or negedge b or posedge c or negedge c)
            (!a && b && !c) |-> (out == 1'b1)
    );
    // 1 one (c=1): out must be 1.
    check_one_hot_c: assert property (
        @(posedge a or negedge a or posedge b or negedge b or posedge c or negedge c)
            (!a && !b && c) |-> (out == 1'b1)
    );
    // 2 ones (a&b): out must be 0.
    check_two_ones_ab: assert property (
        @(posedge a or negedge a or posedge b or negedge b or posedge c or negedge c)
            (a && b && !c) |-> (out == 1'b0)
    );
    // 2 ones (a&c): out must be 0.
    check_two_ones_ac: assert property (
        @(posedge a or negedge a or posedge b or negedge b or posedge c or negedge c)
            (a && !b && c) |-> (out == 1'b0)
    );
    // 2 ones (b&c): out must be 0.
    check_two_ones_bc: assert property (
        @(posedge a or negedge a or posedge b or negedge b or posedge c or negedge c)
            (!a && b && c) |-> (out == 1'b0)
    );
    // 3 ones: out must be 1.
    check_three_ones: assert property (
        @(posedge a or negedge a or posedge b or negedge b or posedge c or negedge c)
            (a && b && c) |-> (out == 1'b1)
    );

endmodule

module add_sub_mux_sva (
    input logic clk,
    input logic [3:0] a,
    input logic [3:0] b,
    input logic mode,
    input logic [3:0] B,
    input logic [3:0] C,
    input logic [3:0] D,
    input logic [3:0] E,
    input logic [1:0] SEL,
    input logic EN,
    input logic [3:0] q
);
    ///// Mux behavior /////
    // EN low forces q to E regardless of SEL.
    check_en_low_selects_E: assert property (
        @(posedge clk) disable iff (1'b0) (!EN) |-> (q == E)
    );

    // With EN high and SEL==01, q == B.
    check_en_high_sel_01_B: assert property (
        @(posedge clk) disable iff (1'b0) (EN && (SEL == 2'b01)) |-> (q == B)
    );

    // With EN high and SEL==10, q == C.
    check_en_high_sel_10_C: assert property (
        @(posedge clk) disable iff (1'b0) (EN && (SEL == 2'b10)) |-> (q == C)
    );

    // With EN high and SEL==11, q == D.
    check_en_high_sel_11_D: assert property (
        @(posedge clk) disable iff (1'b0) (EN && (SEL == 2'b11)) |-> (q == D)
    );

    ///// add_sub path when selected /////
    // With EN high, SEL==00, and mode==1, q == a + b.
    check_add_path_when_selected: assert property (
        @(posedge clk) disable iff (1'b0) (EN && (SEL == 2'b00) && mode) |-> (q == (a + b))
    );

    // With EN high, SEL==00, and mode==0, q == a - b.
    check_sub_path_when_selected: assert property (
        @(posedge clk) disable iff (1'b0) (EN && (SEL == 2'b00) && !mode) |-> (q == (a - b))
    );

    ///// Full combinational function equivalence /////
    // q equals the mux-of-sources with EN override and add/sub on SEL==00.
    check_full_function: assert property (
        @(posedge clk) disable iff (1'b0)
            1'b1 |-> (
                q == ( EN
                       ? ( (SEL == 2'b00) ? (mode ? (a + b) : (a - b)) :
                           (SEL == 2'b01) ? B :
                           (SEL == 2'b10) ? C : D )
                       : E )
            )
    );
endmodule

