    input  D    ;
    input  SET_B;
    input  RESET_B;

    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    reg Q;

    always @(posedge CLK) begin
        if (RESET_B) begin
