module fifo19_rxrealign
  (input clk, input reset, input clear,
   input [18:0] datain, input src_rdy_i, output dst_rdy_o,
   output [18:0] dataout, output src_rdy_o, input dst_rdy_i);

   reg 	rxre_state;
   localparam RXRE_DUMMY  = 0;
   localparam RXRE_PKT 	  = 1;

   assign dataout[18] 	  = datain[18];
   assign dataout[17] 	  = datain[17];
   assign dataout[16] 	  = (rxre_state==RXRE_DUMMY) | (datain[17] & datain[16]);  assign dataout[15:0] = datain[15:0];

   always @(posedge clk)
     if(reset | clear)
       rxre_state <= RXRE_DUMMY;
     else if(src_rdy_i & dst_rdy_i)
       case(rxre_state)
	 RXRE_DUMMY :
	   rxre_state <= RXRE_PKT;
	 RXRE_PKT :
	   if(datain[17])   rxre_state <= RXRE_DUMMY;
       endcase assign src_rdy_o 	 = src_rdy_i & dst_rdy_i;   assign dst_rdy_o = src_rdy_i & dst_rdy_i & (rxre_state == RXRE_PKT);  endmodule

sva:
module fifo19_rxrealign_sva (
    input  logic        clk,
    input  logic        reset,
    input  logic        clear,
    input  logic [18:0] datain,
    input  logic        src_rdy_i,
    input  logic        dst_rdy_o,
    input  logic [18:0] dataout,
    input  logic        src_rdy_o,
    input  logic        dst_rdy_i
);

    ///// Data mapping checks /////
    // dataout[18] must pass through datain[18].
    check_dataout18_passthrough: assert property (
        @(posedge clk) disable iff (reset || clear) dataout[18] == datain[18]
    );
    // dataout[17] must pass through datain[17].
    check_dataout17_passthrough: assert property (
        @(posedge clk) disable iff (reset || clear) dataout[17] == datain[17]
    );
    // dataout[15:0] must pass through datain[15:0].
    check_dataout_lo16_passthrough: assert property (
        @(posedge clk) disable iff (reset || clear) dataout[15:0] == datain[15:0]
    );
    // If datain[17] & datain[16] are 1, dataout[16] must be 1.
    check_dataout16_when_17and16_set: assert property (
        @(posedge clk) disable iff (reset || clear) (datain[17] && datain[16]) |-> (dataout[16] == 1'b1)
    );

    ///// Ready signal relationships /////
    // src_rdy_o must equal src_rdy_i & dst_rdy_i.
    check_src_rdy_o_definition: assert property (
        @(posedge clk) disable iff (reset || clear) src_rdy_o == (src_rdy_i & dst_rdy_i)
    );
    // If src_rdy_i is 0, src_rdy_o must be 0.
    check_src_rdy_o_zero_when_src_not_ready: assert property (
        @(posedge clk) disable iff (reset || clear) (!src_rdy_i) |-> (!src_rdy_o)
    );
    // If dst_rdy_i is 0, src_rdy_o must be 0.
    check_src_rdy_o_zero_when_dst_not_ready: assert property (
        @(posedge clk) disable iff (reset || clear) (!dst_rdy_i) |-> (!src_rdy_o)
    );
    // dst_rdy_o can only be 1 when src_rdy_i & dst_rdy_i are 1.
    check_dst_rdy_o_implies_handshake: assert property (
        @(posedge clk) disable iff (reset || clear) dst_rdy_o |-> (src_rdy_i & dst_rdy_i)
    );
    // dst_rdy_o implies src_rdy_o (since src_rdy_o = src_rdy_i & dst_rdy_i).
    check_dst_rdy_o_subset_src_rdy_o: assert property (
        @(posedge clk) disable iff (reset || clear) dst_rdy_o |-> src_rdy_o
    );
    // If src_rdy_i is 0, dst_rdy_o must be 0.
    check_dst_rdy_o_zero_when_src_not_ready: assert property (
        @(posedge clk) disable iff (reset || clear) (!src_rdy_i) |-> (!dst_rdy_o)
    );
    // If dst_rdy_i is 0, dst_rdy_o must be 0.
    check_dst_rdy_o_zero_when_dst_not_ready: assert property (
        @(posedge clk) disable iff (reset || clear) (!dst_rdy_i) |-> (!dst_rdy_o)
    );

endmodule

module binary_counter_sva (
    input logic clk,
    input logic reset,
    input logic enable,
    input logic [3:0] count
);
    // On a clock when reset is 1, count becomes 0 on the next clock.
    check_reset_clears_next: assert property (
        @(posedge clk) reset |=> (count == 4'b0000)
    );

    // Reset has priority over enable if both are asserted.
    check_reset_dominates_enable: assert property (
        @(posedge clk) (reset && enable) |=> (count == 4'b0000)
    );

    // While reset stays asserted across cycles, count remains 0.
    check_reset_holds_zero: assert property (
        @(posedge clk) ($past(reset) && reset) |-> (count == 4'b0000)
    );

    // With enable deasserted (and not in reset), count holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset) (!enable) |=> (count == $past(count))
    );

    // With enable asserted (and not in reset), count increments modulo 16.
    check_increment_when_enabled: assert property (
        @(posedge clk) disable iff (reset) (enable) |=> (count == ( $past(count) + 4'd1 )[3:0])
    );

    // Any change in count (excluding reset) implies prior cycle had enable high.
    check_change_implies_prev_enable: assert property (
        @(posedge clk) disable iff (reset) ($past(!reset) && (count != $past(count))) |-> $past(enable)
    );

    // Without reset, next value must be either hold or +1 modulo 16.
    check_only_hold_or_increment: assert property (
        @(posedge clk) disable iff (reset) $past(!reset) |-> ((count == $past(count)) || (count == ( $past(count) + 4'd1 )[3:0]))
    );

    // When previous value was 4'hF and enable was 1 (no reset), wrap to 0.
    check_wrap_at_max: assert property (
        @(posedge clk) disable iff (reset) ($past(!reset) && $past(enable) && ($past(count) == 4'hF)) |-> (count == 4'h0)
    );

    // Two consecutive enables (no reset) produce +2 modulo 16 after two cycles.
    check_two_consecutive_enables_plus2: assert property (
        @(posedge clk) disable iff (reset)
            ($past(!reset,1) && $past(!reset,2) && $past(enable,1) && $past(enable,2))
            |-> (count == ( $past(count,2) + 4'd2 )[3:0])
    );

    // Two consecutive disables (no reset) keep count equal to the value two cycles ago.
    check_two_consecutive_disables_hold: assert property (
        @(posedge clk) disable iff (reset)
            ($past(!reset,1) && $past(!reset,2) && !$past(enable,1) && !$past(enable,2))
            |-> (count == $past(count,2))
    );
endmodule

