module calculator(
  input         rst,
  input         clk,
  input  [7:0]  a,
  input  [7:0]  b,
  input  [1:0]  op,
  output [7:0]  result,
  output        valid
);

  reg [7:0] result_reg;
  reg valid_reg;

  always @(posedge clk or negedge rst) begin
    if (rst == 0) begin
      result_reg <= 0;
      valid_reg <= 0;
    end
    else begin
      case(op)
        2'b00: result_reg <= a + b; // addition
        2'b01: result_reg <= a - b; // subtraction
        2'b10: result_reg <= a * b; // multiplication
        2'b11: result_reg <= a / b; // division
      endcase
      valid_reg <= 1;
    end
  end

  assign result = result_reg;
  assign valid = valid_reg;

endmodule

sva:
module calculator_sva (
    input logic        rst,
    input logic        clk,
    input logic [7:0]  a,
    input logic [7:0]  b,
    input logic [1:0]  op,
    input logic [7:0]  result,
    input logic        valid
);
    // While reset (active LOW), outputs are cleared.
    reset_outputs_cleared: assert property (
        @(posedge clk) (!rst) |-> (result == 8'h00) && (valid == 1'b0)
    );

    // valid cannot be HIGH when reset is asserted.
    valid_only_when_not_in_reset: assert property (
        @(posedge clk) valid |-> rst
    );

    // With valid HIGH, result matches previous-cycle addition (op==00).
    check_add_result: assert property (
        @(posedge clk) disable iff (!rst)
            (valid && ($past(op) == 2'b00)) |-> (result == ($past(a) + $past(b)))
    );

    // With valid HIGH, result matches previous-cycle subtraction (op==01).
    check_sub_result: assert property (
        @(posedge clk) disable iff (!rst)
            (valid && ($past(op) == 2'b01)) |-> (result == ($past(a) - $past(b)))
    );

    // With valid HIGH, result matches lower 8b of previous-cycle multiplication (op==10).
    check_mul_result: assert property (
        @(posedge clk) disable iff (!rst)
            (valid && ($past(op) == 2'b10)) |-> (result == (($past(a) * $past(b)) [7:0]))
    );

    // With valid HIGH, result matches previous-cycle division (op==11) when divisor != 0.
    check_div_result_nonzero: assert property (
        @(posedge clk) disable iff (!rst)
            (valid && ($past(op) == 2'b11) && ($past(b) != 8'h00)) |-> (result == ($past(a) / $past(b)))
    );

    // With valid HIGH and stable inputs/op (and no div-by-zero), result holds its previous value.
    stable_result_when_inputs_stable: assert property (
        @(posedge clk) disable iff (!rst)
            (valid && $stable(op) && $stable(a) && $stable(b) && ((op != 2'b11) || (b != 8'h00)))
            |-> (result == $past(result))
    );

    // With valid HIGH, multiply-by-zero yields zero.
    mul_by_zero_yields_zero: assert property (
        @(posedge clk) disable iff (!rst)
            (valid && ($past(op) == 2'b10) && (($past(a) == 8'h00) || ($past(b) == 8'h00)))
            |-> (result == 8'h00)
    );

    // With valid HIGH, add with b==0 returns a.
    add_with_b_zero_identity: assert property (
        @(posedge clk) disable iff (!rst)
            (valid && ($past(op) == 2'b00) && ($past(b) == 8'h00))
            |-> (result == $past(a))
    );

    // With valid HIGH, subtract with b==0 returns a.
    sub_with_b_zero_identity: assert property (
        @(posedge clk) disable iff (!rst)
            (valid && ($past(op) == 2'b01) && ($past(b) == 8'h00))
            |-> (result == $past(a))
    );

    // With valid HIGH, divide by one returns a.
    div_by_one_identity: assert property (
        @(posedge clk) disable iff (!rst)
            (valid && ($past(op) == 2'b11) && ($past(b) == 8'h01))
            |-> (result == $past(a))
    );

endmodule

module ExtToIntSync_sva (
    input logic clk,
    input logic rst,
    input logic ext_signal,
    input logic int_signal
);
    // When reset is HIGH at the clock edge, int_signal is driven to 0 in the same cycle.
    check_reset_sets_zero_now: assert property (
        @(posedge clk) rst |-> ##0 (int_signal == 1'b0)
    );

    // If reset is HIGH in two consecutive samples, int_signal must read as 0 now.
    check_reset_held_zero: assert property (
        @(posedge clk) ($past(rst) && rst) |-> (int_signal == 1'b0)
    );

    // Immediately after reset deasserts, sampled int_signal remains 0 from the prior cycle.
    check_post_reset_sample_zero: assert property (
        @(posedge clk) $fell(rst) |-> (int_signal == 1'b0)
    );

    // With reset LOW, int_signal captures ext_signal on the same clock edge (after NBA).
    check_capture_when_not_reset: assert property (
        @(posedge clk) disable iff (rst) 1'b1 |-> ##0 (int_signal == ext_signal)
    );

    // If reset is HIGH now, int_signal is 0 on the next sampled cycle.
    check_reset_implies_next_zero: assert property (
        @(posedge clk) rst |=> (int_signal == 1'b0)
    );

    // On a sampled rising edge of reset, int_signal is driven to 0 in the same cycle.
    check_reset_rise_sets_zero_now: assert property (
        @(posedge clk) $rose(rst) |-> ##0 (int_signal == 1'b0)
    );
endmodule

rtl:
module my_module (
    VPWR,
    VGND,
    X   ,
    A1  ,
    A2  ,
    A3  ,
    B1  ,
    B2
);

    // Module ports
    input  VPWR;
    input  VGND;
    output X   ;
    input  A1  ;
    input  A2  ;
    input  A3  ;
    input  B1  ;
    input  B2  ;

    // Local signals
    wire	and0_out          ;
    wire	and1_out          ;
    wire    or0_out_X         ;
    wire    buf0_out          ;

    // Perform AND operation between A1, A2, and A3
    and and0 (and0_out, A3, A1, A2);

    // Perform AND operation between B1 and B2
    and and1 (and1_out, B1, B2);

    // Perform OR operation between and0_out and and1_out
    or or0 (or0_out_X, and1_out, and0_out);

    // Connect the output of the OR operation to an instance of the buf module
    buf buf0 (buf0_out, or0_out_X);

    // Connect the output of the buf instance to the output of the module
    assign X = buf0_out;

endmodule

sva:
module my_module_sva (
    // DUT ports as inputs
    input logic VPWR,
    input logic VGND,
    input logic X,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic B1,
    input logic B2,
    // Internal signals from DUT
    input logic and0_out,
    input logic and1_out,
    input logic or0_out_X,
    input logic buf0_out
);
    // No clock/reset in RTL; purely combinational: X = (A3 & A1 & A2) | (B1 & B2)

    // AND gate and0 implements A3 & A1 & A2.
    check_and0_gate_function: assert property (
        @(posedge A1 or posedge A2 or posedge A3 or posedge B1 or posedge B2 or posedge X or posedge and0_out or posedge and1_out or posedge or0_out_X or posedge buf0_out)
            and0_out === (A3 & A1 & A2)
    );

    // AND gate and1 implements B1 & B2.
    check_and1_gate_function: assert property (
        @(posedge A1 or posedge A2 or posedge A3 or posedge B1 or posedge B2 or posedge X or posedge and0_out or posedge and1_out or posedge or0_out_X or posedge buf0_out)
            and1_out === (B1 & B2)
    );

    // OR gate or0 implements and1_out | and0_out.
    check_or0_gate_function: assert property (
        @(posedge A1 or posedge A2 or posedge A3 or posedge B1 or posedge B2 or posedge X or posedge and0_out or posedge and1_out or posedge or0_out_X or posedge buf0_out)
            or0_out_X === (and1_out | and0_out)
    );

    // BUF gate buf0 passes or0_out_X to buf0_out.
    check_buf0_identity: assert property (
        @(posedge A1 or posedge A2 or posedge A3 or posedge B1 or posedge B2 or posedge X or posedge and0_out or posedge and1_out or posedge or0_out_X or posedge buf0_out)
            buf0_out === or0_out_X
    );

    // Final assign connects buf0_out to X.
    check_output_assign_identity: assert property (
        @(posedge A1 or posedge A2 or posedge A3 or posedge B1 or posedge B2 or posedge X or posedge and0_out or posedge and1_out or posedge or0_out_X or posedge buf0_out)
            X === buf0_out
    );

    // End-to-end function: X == (A3 & A1 & A2) | (B1 & B2).
    check_end_to_end_equation: assert property (
        @(posedge A1 or posedge A2 or posedge A3 or posedge B1 or posedge B2 or posedge X or posedge and0_out or posedge and1_out or posedge or0_out_X or posedge buf0_out)
            X === ((A3 & A1 & A2) | (B1 & B2))
    );

    // If either AND path is 1, X must be 1 (same cycle).
    check_output_one_if_any_path_one: assert property (
        @(posedge A1 or posedge A2 or posedge A3 or posedge B1 or posedge B2 or posedge X or posedge and0_out or posedge and1_out or posedge or0_out_X or posedge buf0_out)
            ((and0_out === 1'b1) || (and1_out === 1'b1)) |-> (X === 1'b1)
    );

    // If both AND paths are 0, X must be 0 (same cycle).
    check_output_zero_if_both_paths_zero: assert property (
        @(posedge A1 or posedge A2 or posedge A3 or posedge B1 or posedge B2 or posedge X or posedge and0_out or posedge and1_out or posedge or0_out_X or posedge buf0_out)
            ((and0_out === 1'b0) && (and1_out === 1'b0)) |-> (X === 1'b0)
    );

    // X=1 implies at least one AND path is 1.
    check_output_high_implies_any_path_high: assert property (
        @(posedge A1 or posedge A2 or posedge A3 or posedge B1 or posedge B2 or posedge X or posedge and0_out or posedge and1_out or posedge or0_out_X or posedge buf0_out)
            (X === 1'b1) |-> ((and0_out === 1'b1) || (and1_out === 1'b1))
    );

    // X=0 implies both AND paths are 0.
    check_output_low_implies_both_paths_low: assert property (
        @(posedge A1 or posedge A2 or posedge A3 or posedge B1 or posedge B2 or posedge X or posedge and0_out or posedge and1_out or posedge or0_out_X or posedge buf0_out)
            (X === 1'b0) |-> ((and0_out === 1'b0) && (and1_out === 1'b0))
    );

endmodule

rtl:
module dual_edge_ff (
    input clk,
    input d,
    output q
);

reg q1, q2;

always @(posedge clk) begin
    q1 <= d;
end

always @(negedge clk) begin
    q2 <= q1;
end

assign q = q2;

endmodule

sva:
module dual_edge_ff_sva (
    input logic clk,
    input logic d,
    input logic q
);
    // Clock: clk (both posedge and negedge used). Reset: none.
    // Logic: sequential across both edges; q updates on negedge to prior posedge d.

    // On each negedge, q equals d captured at the most recent posedge.
    check_q_eq_prev_posedge_d_at_negedge: assert property (
        @(negedge clk) q == $past(d, 1, posedge clk)
    );

    // On each posedge, q still equals d from the previous posedge.
    check_q_eq_prev_posedge_d_at_posedge: assert property (
        @(posedge clk) q == $past(d)
    );

    // If q changes at a negedge, then d must have changed at the preceding posedge vs. the one before it.
    check_q_change_at_negedge_implies_d_change: assert property (
        @(negedge clk) $changed(q) |-> ($past(d, 1, posedge clk) != $past(d, 2, posedge clk))
    );

    // If d changed at the current posedge vs. the prior posedge, q must change at this negedge.
    check_d_change_at_posedge_implies_q_change: assert property (
        @(negedge clk) ($past(d, 1, posedge clk) != $past(d, 2, posedge clk)) |-> (q != $past(q))
    );

    // If d did not change across the last two posedges, q must be stable across the last two negedges.
    check_q_stable_when_d_stable_across_posedges: assert property (
        @(negedge clk) ($past(d, 1, posedge clk) == $past(d, 2, posedge clk)) |-> (q == $past(q))
    );

    // At each posedge, q equals its value from the most recent negedge (no update occurs at posedge).
    check_q_const_through_posedge: assert property (
        @(posedge clk) q == $past(q, 1, negedge clk)
    );
endmodule

rtl:
module binary_counter (
  input clk,
  input reset,
  output reg [1:0] count
);

  reg [1:0] next_count;

  always @(posedge clk) begin
    if (reset) begin
      count <= 2'b00;
    end else begin
      count <= next_count;
    end
  end

  always @(*) begin
    case (count)
      2'b00: next_count = 2'b01;
      2'b01: next_count = 2'b10;
      2'b10: next_count = 2'b11;
      2'b11: next_count = 2'b00;
    endcase
  end

endmodule

sva:
module binary_counter_sva (
  input logic clk,
  input logic reset,
  input logic [1:0] count
);
  // Clock: clk (posedge). Reset: reset active-high synchronous.
  // Logic: mixed (sequential count, combinational next_count).
  // Behavior: modulo-4 up-counter 00->01->10->11->00.

  // On reset, count becomes 00 on the next cycle.
  reset_clears_count_next: assert property (
    @(posedge clk) reset |=> (count == 2'b00)
  );

  // If reset held for consecutive cycles, count is 00 in the current cycle.
  reset_held_keeps_zero: assert property (
    @(posedge clk) (reset && $past(reset)) |-> (count == 2'b00)
  );

  // On reset deassertion cycle, count is still 00 before increment.
  deassert_reset_current_zero: assert property (
    @(posedge clk) $fell(reset) |-> (count == 2'b00)
  );

  // One cycle after reset deasserts, count becomes 01.
  deassert_reset_next_one: assert property (
    @(posedge clk) $fell(reset) |=> (count == 2'b01)
  );

  // From 00, next count is 01 when not in reset.
  step_from_00_to_01: assert property (
    @(posedge clk) disable iff (reset) (count == 2'b00) |=> (count == 2'b01)
  );

  // From 01, next count is 10 when not in reset.
  step_from_01_to_10: assert property (
    @(posedge clk) disable iff (reset) (count == 2'b01) |=> (count == 2'b10)
  );

  // From 10, next count is 11 when not in reset.
  step_from_10_to_11: assert property (
    @(posedge clk) disable iff (reset) (count == 2'b10) |=> (count == 2'b11)
  );

  // From 11, next count is 00 when not in reset.
  step_from_11_to_00: assert property (
    @(posedge clk) disable iff (reset) (count == 2'b11) |=> (count == 2'b00)
  );

  // Count changes every cycle when not in reset.
  count_changes_without_reset: assert property (
    @(posedge clk) disable iff (reset) 1'b1 |=> (count != $past(count))
  );

  // After 4 cycles without reset, count returns to the same value.
  period_four_cycle: assert property (
    @(posedge clk) disable iff (reset) 1'b1 |=> ##4 (count == $past(count,4))
  );
endmodule

rtl:
module binary_full_adder_74283 (
  input [3:0] num1,
  input [3:0] num2,
  input carry_in,
  output [3:0] sum,
  output carry_out
);

  assign {carry_out, sum} = num1 + num2 + carry_in;

endmodule

sva:
module binary_full_adder_74283_sva (
    input logic clk,
    input logic [3:0] num1,
    input logic [3:0] num2,
    input logic carry_in,
    input logic [3:0] sum,
    input logic carry_out
);
    function automatic logic maj3 (input logic a, input logic b, input logic c);
        maj3 = (a & b) | (a & c) | (b & c);
    endfunction

    // Sum and carry concatenation equals 5-bit addition of operands.
    check_full_sum_concat: assert property (
        @(posedge clk) {carry_out, sum} == (num1 + num2 + carry_in)
    );

    // LSB sum bit is XOR of inputs and carry_in.
    check_sum_bit0_xor: assert property (
        @(posedge clk) sum[0] == (num1[0] ^ num2[0] ^ carry_in)
    );

    // Bit1 sum is XOR of inputs and carry from bit0.
    check_sum_bit1_xor: assert property (
        @(posedge clk) sum[1] == (num1[1] ^ num2[1] ^ maj3(num1[0], num2[0], carry_in))
    );

    // Bit2 sum is XOR of inputs and carry from bit1.
    check_sum_bit2_xor: assert property (
        @(posedge clk) sum[2] == (num1[2] ^ num2[2] ^ maj3(num1[1], num2[1], maj3(num1[0], num2[0], carry_in)))
    );

    // Bit3 sum is XOR of inputs and carry from bit2.
    check_sum_bit3_xor: assert property (
        @(posedge clk) sum[3] == (num1[3] ^ num2[3] ^ maj3(num1[2], num2[2], maj3(num1[1], num2[1], maj3(num1[0], num2[0], carry_in))))
    );

    // Final carry_out equals carry from bit3.
    check_carry_out_majority: assert property (
        @(posedge clk) carry_out == maj3(num1[3], num2[3], maj3(num1[2], num2[2], maj3(num1[1], num2[1], maj3(num1[0], num2[0], carry_in))))
    );

    // When no overflow occurs, carry_out must be 0.
    check_no_overflow_implies_carry0: assert property (
        @(posedge clk) ((num1 + num2 + carry_in) <= 5'd15) |-> (carry_out == 1'b0)
    );

    // When overflow occurs, carry_out must be 1.
    check_overflow_implies_carry1: assert property (
        @(posedge clk) ((num1 + num2 + carry_in) > 5'd15) |-> (carry_out == 1'b1)
    );

    // If num1==0 and carry_in==0, output equals num2 with no carry.
    check_passthrough_num2_when_num1_zero_cin0: assert property (
        @(posedge clk) ((num1 == 4'd0) && (carry_in == 1'b0)) |-> ((sum == num2) && (carry_out == 1'b0))
    );

    // If num2==0 and carry_in==0, output equals num1 with no carry.
    check_passthrough_num1_when_num2_zero_cin0: assert property (
        @(posedge clk) ((num2 == 4'd0) && (carry_in == 1'b0)) |-> ((sum == num1) && (carry_out == 1'b0))
    );

    // If num2==0 and carry_in==1, output equals num1+1 with carry on overflow.
    check_increment_when_cin1_num2_zero: assert property (
        @(posedge clk) ((num2 == 4'd0) && (carry_in == 1'b1)) |-> ((sum == (num1 + 5'd1)[3:0]) && (carry_out == (num1 == 4'hF)))
    );

    // Outputs remain stable when inputs do not change.
    check_outputs_stable_when_inputs_stable: assert property (
        @(posedge clk) ($stable(num1) && $stable(num2) && $stable(carry_in)) |-> ($stable(sum) && $stable(carry_out))
    );
endmodule

rtl:
module sum_4bit(input [3:0] input_a, output reg [4:0] output_sum);

always @(*) begin
    output_sum = {1'b0, input_a} + 4'b0001;
end

endmodule

sva:
module sum_4bit_sva (
    input logic clk,
    input logic [3:0] input_a,
    input logic [4:0] output_sum
);
    // Output is zero-extended input_a plus 1.
    check_sum_functional: assert property (
        @(posedge clk) output_sum == ({1'b0, input_a} + 5'd1)
    );

    // Lower 4 bits equal input_a + 1 modulo 16.
    check_lower_nibble_increment: assert property (
        @(posedge clk) output_sum[3:0] == (input_a + 4'd1)
    );

    // Carry-out equals reduction AND of input_a (overflow on 0xF).
    check_carry_out_condition: assert property (
        @(posedge clk) output_sum[4] == (&input_a)
    );

    // LSB toggles on +1 increment.
    check_bit0_toggle: assert property (
        @(posedge clk) output_sum[0] == ~input_a[0]
    );

    // Bit1 equals a1 XOR a0 for +1 increment.
    check_bit1_logic: assert property (
        @(posedge clk) output_sum[1] == (input_a[1] ^ input_a[0])
    );

    // Bit2 equals a2 XOR (a1 & a0) for +1 increment.
    check_bit2_logic: assert property (
        @(posedge clk) output_sum[2] == (input_a[2] ^ (input_a[1] & input_a[0]))
    );

    // Bit3 equals a3 XOR (a2 & a1 & a0) for +1 increment.
    check_bit3_logic: assert property (
        @(posedge clk) output_sum[3] == (input_a[3] ^ (input_a[2] & input_a[1] & input_a[0]))
    );

    // When input is 0xF, sum is 0x10.
    check_overflow_case: assert property (
        @(posedge clk) (input_a == 4'hF) |-> (output_sum == 5'h10)
    );

    // When input is 0x0, sum is 0x01.
    check_zero_input_case: assert property (
        @(posedge clk) (input_a == 4'h0) |-> (output_sum == 5'h01)
    );

    // If input_a is unchanged across cycles, output_sum is unchanged.
    check_functional_stability: assert property (
        @(posedge clk) (input_a == $past(input_a)) |-> (output_sum == $past(output_sum))
    );
endmodule

rtl:
module mux2to1(
   input         in0, in1, sel,
   output        out);

   assign out = sel ? in1 : in0;

endmodule

sva:
module mux2to1_sva (
    input logic CLK,
    input logic in0,
    input logic in1,
    input logic sel,
    input logic out
);
    // Out equals selected input per mux function.
    check_mux_function: assert property (
        @(posedge CLK) out == (sel ? in1 : in0)
    );

    // When sel=0, out mirrors in0.
    check_sel0_path: assert property (
        @(posedge CLK) (sel == 1'b0) |-> (out == in0)
    );

    // When sel=1, out mirrors in1.
    check_sel1_path: assert property (
        @(posedge CLK) (sel == 1'b1) |-> (out == in1)
    );

    // If in0,in1,sel are unchanged across cycles, out is unchanged.
    check_out_stable_if_inputs_stable: assert property (
        @(posedge CLK) (!$changed(in0) && !$changed(in1) && !$changed(sel)) |-> !$changed(out)
    );

    // With sel stable 0, out changes only if in0 changes.
    check_out_change_requires_in0_when_sel0: assert property (
        @(posedge CLK) (sel == 1'b0 && $past(sel) == 1'b0 && $changed(out)) |-> $changed(in0)
    );

    // With sel stable 1, out changes only if in1 changes.
    check_out_change_requires_in1_when_sel1: assert property (
        @(posedge CLK) (sel == 1'b1 && $past(sel) == 1'b1 && $changed(out)) |-> $changed(in1)
    );

    // With sel stable 0 and in0 unchanged, out is unchanged.
    check_out_stable_sel0_if_in0_stable: assert property (
        @(posedge CLK) (sel == 1'b0 && $past(sel) == 1'b0 && !$changed(in0)) |-> !$changed(out)
    );

    // With sel stable 1 and in1 unchanged, out is unchanged.
    check_out_stable_sel1_if_in1_stable: assert property (
        @(posedge CLK) (sel == 1'b1 && $past(sel) == 1'b1 && !$changed(in1)) |-> !$changed(out)
    );
endmodule

module decoder_4to16_sva (
    input logic [1:0] sel,
    input logic [15:0] out
);
    // Output equals 1'h1 shifted by sel (core decode relation).
    check_decode_equivalence: assert property (
        @(posedge sel[0] or negedge sel[0] or posedge sel[1] or negedge sel[1])
        out == (16'b0000000000000001 << sel)
    );

    // Output is always one of the four valid patterns.
    check_out_valid_set: assert property (
        @(posedge sel[0] or negedge sel[0] or posedge sel[1] or negedge sel[1])
        out inside {16'h0001,16'h0002,16'h0004,16'h0008}
    );

    // Upper bits [15:4] are always zero.
    check_upper_bits_zero: assert property (
        @(posedge sel[0] or negedge sel[0] or posedge sel[1] or negedge sel[1])
        out[15:4] == 12'b0
    );

    // Exactly one output bit is HIGH at a time.
    check_onehot_out: assert property (
        @(posedge sel[0] or negedge sel[0] or posedge sel[1] or negedge sel[1])
        $onehot(out)
    );

    // sel==2'b00 maps to out==16'h0001.
    check_map_00_forward: assert property (
        @(posedge sel[0] or negedge sel[0] or posedge sel[1] or negedge sel[1])
        (sel == 2'b00) |=> (out == 16'h0001)
    );

    // sel==2'b01 maps to out==16'h0002.
    check_map_01_forward: assert property (
        @(posedge sel[0] or negedge sel[0] or posedge sel[1] or negedge sel[1])
        (sel == 2'b01) |=> (out == 16'h0002)
    );

    // sel==2'b10 maps to out==16'h0004.
    check_map_10_forward: assert property (
        @(posedge sel[0] or negedge sel[0] or posedge sel[1] or negedge sel[1])
        (sel == 2'b10) |=> (out == 16'h0004)
    );

    // sel==2'b11 maps to out==16'h0008.
    check_map_11_forward: assert property (
        @(posedge sel[0] or negedge sel[0] or posedge sel[1] or negedge sel[1])
        (sel == 2'b11) |=> (out == 16'h0008)
    );

    // Reverse: out==16'h0001 implies sel==2'b00.
    check_map_0001_reverse: assert property (
        @(posedge sel[0] or negedge sel[0] or posedge sel[1] or negedge sel[1])
        (out == 16'h0001) |=> (sel == 2'b00)
    );

    // Reverse: out==16'h0002 implies sel==2'b01.
    check_map_0002_reverse: assert property (
        @(posedge sel[0] or negedge sel[0] or posedge sel[1] or negedge sel[1])
        (out == 16'h0002) |=> (sel == 2'b01)
    );

    // Reverse: out==16'h0004 implies sel==2'b10.
    check_map_0004_reverse: assert property (
        @(posedge sel[0] or negedge sel[0] or posedge sel[1] or negedge sel[1])
        (out == 16'h0004) |=> (sel == 2'b10)
    );

    // Reverse: out==16'h0008 implies sel==2'b11.
    check_map_0008_reverse: assert property (
        @(posedge sel[0] or negedge sel[0] or posedge sel[1] or negedge sel[1])
        (out == 16'h0008) |=> (sel == 2'b11)
    );

    // Out is never all zeros (default branch unreachable for 2-bit sel).
    check_out_nonzero: assert property (
        @(posedge sel[0] or negedge sel[0] or posedge sel[1] or negedge sel[1])
        out != 16'h0000
    );
endmodule

rtl:
module mi_nios_cpu_nios2_oci_td_mode (
  // inputs:
  ctrl,

  // outputs:
  td_mode
);

  output [3:0] td_mode;
  input [8:0] ctrl;

  wire [2:0] ctrl_bits_for_mux;
  reg [3:0] td_mode;
  assign ctrl_bits_for_mux = ctrl[7:5];

  always @(*) begin
    case (ctrl_bits_for_mux)
      3'b000: td_mode = 4'b0000;
      3'b001: td_mode = 4'b1000;
      3'b010: td_mode = 4'b0100;
      3'b011: td_mode = 4'b1100;
      3'b100: td_mode = 4'b0010;
      3'b101: td_mode = 4'b1010;
      3'b110: td_mode = 4'b0101;
      3'b111: td_mode = 4'b1111;
      default: td_mode = 4'b0000;
    endcase
  end

endmodule

sva:
module mi_nios_cpu_nios2_oci_td_mode_sva (
    input logic clk,
    input logic [8:0] ctrl,
    input logic [3:0] td_mode
);
    // Local alias of mux select bits
    wire [2:0] ctrl_bits_for_mux = ctrl[7:5];

    // td_mode mapping when ctrl_bits_for_mux == 3'b000
    map_sel_000: assert property (
        @(posedge clk) (ctrl_bits_for_mux == 3'b000) |-> (td_mode == 4'b0000)
    );

    // td_mode mapping when ctrl_bits_for_mux == 3'b001
    map_sel_001: assert property (
        @(posedge clk) (ctrl_bits_for_mux == 3'b001) |-> (td_mode == 4'b1000)
    );

    // td_mode mapping when ctrl_bits_for_mux == 3'b010
    map_sel_010: assert property (
        @(posedge clk) (ctrl_bits_for_mux == 3'b010) |-> (td_mode == 4'b0100)
    );

    // td_mode mapping when ctrl_bits_for_mux == 3'b011
    map_sel_011: assert property (
        @(posedge clk) (ctrl_bits_for_mux == 3'b011) |-> (td_mode == 4'b1100)
    );

    // td_mode mapping when ctrl_bits_for_mux == 3'b100
    map_sel_100: assert property (
        @(posedge clk) (ctrl_bits_for_mux == 3'b100) |-> (td_mode == 4'b0010)
    );

    // td_mode mapping when ctrl_bits_for_mux == 3'b101
    map_sel_101: assert property (
        @(posedge clk) (ctrl_bits_for_mux == 3'b101) |-> (td_mode == 4'b1010)
    );

    // td_mode mapping when ctrl_bits_for_mux == 3'b110
    map_sel_110: assert property (
        @(posedge clk) (ctrl_bits_for_mux == 3'b110) |-> (td_mode == 4'b0101)
    );

    // td_mode mapping when ctrl_bits_for_mux == 3'b111
    map_sel_111: assert property (
        @(posedge clk) (ctrl_bits_for_mux == 3'b111) |-> (td_mode == 4'b1111)
    );

    // td_mode always matches the combinational decode of ctrl[7:5]
    decode_consistency: assert property (
        @(posedge clk)
            td_mode ==
            ((ctrl_bits_for_mux == 3'b000) ? 4'b0000 :
             (ctrl_bits_for_mux == 3'b001) ? 4'b1000 :
             (ctrl_bits_for_mux == 3'b010) ? 4'b0100 :
             (ctrl_bits_for_mux == 3'b011) ? 4'b1100 :
             (ctrl_bits_for_mux == 3'b100) ? 4'b0010 :
             (ctrl_bits_for_mux == 3'b101) ? 4'b1010 :
             (ctrl_bits_for_mux == 3'b110) ? 4'b0101 :
                                             4'b1111)
    );

    // td_mode can only be one of the enumerated decode values
    td_mode_range_check: assert property (
        @(posedge clk) td_mode inside {
            4'b0000, 4'b1000, 4'b0100, 4'b1100,
            4'b0010, 4'b1010, 4'b0101, 4'b1111
        }
    );
endmodule

