    A_N,
    B_N,
    C  ,
    D
);

    output Y  ;
    input  A_N;
    input  B_N;
    input  C  ;
    input  D  ;

    wire nand0_out;
    wire or0_out_Y;

    nand nand0 (nand0_out, D, C               );
    or   or0   (or0_out_Y, B_N, A_N, nand0_out);
    buf  buf0  (Y        , or0_out_Y          );

endmodule

sva:
module sky130_fd_sc_ms__nand4bb_sva (
    input logic Y,
    input logic A_N,
    input logic B_N,
    input logic C,
    input logic D,
    input logic nand0_out,
    input logic or0_out_Y
);
    // No explicit clock/reset in RTL; combinational cell sampled on any input/output edge.

    // Y equals A_N | B_N | ~(C & D).
    check_function_y: assert property (
        @(posedge A_N or negedge A_N or posedge B_N or negedge B_N or posedge C or negedge C or posedge D or negedge D or posedge Y or negedge Y)
        Y === (A_N | B_N | ~(C & D))
    );

    // nand0_out equals ~(D & C).
    check_nand0_equation: assert property (
        @(posedge C or negedge C or posedge D or negedge D or posedge nand0_out or negedge nand0_out)
        nand0_out === ~(D & C)
    );

    // or0_out_Y equals B_N | A_N | nand0_out.
    check_or0_equation: assert property (
        @(posedge A_N or negedge A_N or posedge B_N or negedge B_N or posedge nand0_out or negedge nand0_out or posedge or0_out_Y or negedge or0_out_Y)
        or0_out_Y === (B_N | A_N | nand0_out)
    );

    // Buffer drives Y equal to or0_out_Y.
    check_buf_equation: assert property (
        @(posedge Y or negedge Y or posedge or0_out_Y or negedge or0_out_Y)
        Y === or0_out_Y
    );

    // A_N high forces Y high.
    check_A_N_dominates: assert property (
        @(posedge A_N or negedge A_N or posedge B_N or negedge B_N or posedge C or negedge C or posedge D or negedge D or posedge Y or negedge Y)
        (A_N == 1'b1) |-> (Y == 1'b1)
    );

    // B_N high forces Y high.
    check_B_N_dominates: assert property (
        @(posedge A_N or negedge A_N or posedge B_N or negedge B_N or posedge C or negedge C or posedge D or negedge D or posedge Y or negedge Y)
        (B_N == 1'b1) |-> (Y == 1'b1)
    );

    // C low forces Y high.
    check_C_zero_dominates: assert property (
        @(posedge A_N or negedge A_N or posedge B_N or negedge B_N or posedge C or negedge C or posedge D or negedge D or posedge Y or negedge Y)
        (C == 1'b0) |-> (Y == 1'b1)
    );

    // D low forces Y high.
    check_D_zero_dominates: assert property (
        @(posedge A_N or negedge A_N or posedge B_N or negedge B_N or posedge C or negedge C or posedge D or negedge D or posedge Y or negedge Y)
        (D == 1'b0) |-> (Y == 1'b1)
    );

    // When A_N=0, B_N=0, C=1, D=1, Y must be 0.
    check_zero_condition: assert property (
        @(posedge A_N or negedge A_N or posedge B_N or negedge B_N or posedge C or negedge C or posedge D or negedge D or posedge Y or negedge Y)
        ((A_N == 1'b0) && (B_N == 1'b0) && (C == 1'b1) && (D == 1'b1)) |-> (Y == 1'b0)
    );

    // Y can be 0 only if A_N=0, B_N=0, C=1, D=1.
    check_y_zero_implies_inputs: assert property (
        @(posedge A_N or negedge A_N or posedge B_N or negedge B_N or posedge C or negedge C or posedge D or negedge D or posedge Y or negedge Y)
        (Y == 1'b0) |-> ((A_N == 1'b0) && (B_N == 1'b0) && (C == 1'b1) && (D == 1'b1))
    );

    // With A_N=0 and B_N=0, or0_out_Y equals nand0_out.
    check_or_passthrough_when_AB_low: assert property (
        @(posedge A_N or negedge A_N or posedge B_N or negedge B_N or posedge nand0_out or negedge nand0_out or posedge or0_out_Y or negedge or0_out_Y)
        ((A_N == 1'b0) && (B_N == 1'b0)) |-> (or0_out_Y === nand0_out)
    );

    // If both C and D are 1, nand0_out is 0.
    check_nand_low_when_CD_high: assert property (
        @(posedge C or negedge C or posedge D or negedge D or posedge nand0_out or negedge nand0_out)
        ((C == 1'b1) && (D == 1'b1)) |-> (nand0_out == 1'b0)
    );

    // If either C or D is 0, nand0_out is 1.
    check_nand_high_when_any_CD_low: assert property (
        @(posedge C or negedge C or posedge D or negedge D or posedge nand0_out or negedge nand0_out)
        ((C == 1'b0) || (D == 1'b0)) |-> (nand0_out == 1'b1)
    );
endmodule

rtl:
module counter(
    input clk,
    input reset,
    input [7:0] max_count,
    output reg [7:0] count
);

always @(posedge clk) begin
    if (reset) begin
        count <= 0;
    end else if (count == max_count) begin
        count <= 0;
    end else begin
        count <= count + 1;
    end
end

endmodule

sva:
module counter_sva (
    input logic clk,
    input logic reset,          // active-high synchronous reset
    input logic [7:0] max_count,
    input logic [7:0] count
);

    // Reset drives count to 0 on the next clock.
    reset_clears_next: assert property (
        @(posedge clk) reset |=> (count == 8'd0)
    );

    // When count equals max_count, next count wraps to 0.
    wrap_to_zero_at_max: assert property (
        @(posedge clk) disable iff (reset) (count == max_count) |=> (count == 8'd0)
    );

    // When count is not max_count, next count increments by 1 (mod 256).
    increment_when_not_max: assert property (
        @(posedge clk) disable iff (reset) (count != max_count) |=> (count == $past(count) + 8'd1)
    );

    // Next-state equals 0 at max_count else equals previous+1.
    next_state_equation: assert property (
        @(posedge clk) disable iff (reset) 1'b1 |=> (count == (($past(count) == $past(max_count)) ? 8'd0 : ($past(count) + 8'd1)))
    );

    // Count only holds across cycles when previous count==0 and previous max_count==0.
    hold_only_when_max_zero: assert property (
        @(posedge clk) disable iff (reset) (count == $past(count)) |-> (($past(count) == 8'd0) && ($past(max_count) == 8'd0))
    );

    // If count is 0 (and previous cycle not in reset), cause was max hit or 8'hFF overflow.
    zero_has_expected_causes: assert property (
        @(posedge clk) disable iff (reset) ($past(!reset) && (count == 8'd0)) |-> (($past(count) == $past(max_count)) || ($past(count) == 8'hFF))
    );

    // From 0 when max_count != 0, next count becomes 1.
    zero_then_one_when_max_nonzero: assert property (
        @(posedge clk) disable iff (reset) (count == 8'd0 && max_count != 8'd0) |=> (count == 8'd1)
    );

    // Overflow case: from 8'hFF when not at max_count, next count becomes 0.
    overflow_ff_to_zero: assert property (
        @(posedge clk) disable iff (reset) ($past(count) == 8'hFF && ($past(count) != $past(max_count))) |-> (count == 8'd0)
    );

    // Normal increment cannot produce 0 unless previous was 8'hFF.
    normal_increment_never_zero: assert property (
        @(posedge clk) disable iff (reset) ($past(count) != $past(max_count) && $past(count) != 8'hFF) |-> (count != 8'd0)
    );

    // Special case of hold: if previous count==0 and previous max_count==0, current count is 0.
    hold_when_max_zero_prev: assert property (
        @(posedge clk) disable iff (reset) ($past(count) == 8'd0 && $past(max_count) == 8'd0) |-> (count == 8'd0)
    );

endmodule

