sva:
module sky130_fd_sc_ms__nand4bb_sva (
    input logic CLK,
    input logic Y,
    input logic A_N,
    input logic B_N,
    input logic C,
    input logic D
);
    // Y equals the combinational function A_N | B_N | ~(C & D).
    check_functional_equivalence: assert property (
        @(posedge CLK) Y == (A_N | B_N | ~(C & D))
    );

    // If Y is LOW, then A_N=0, B_N=0, and C&D=1 must hold.
    check_y_low_conditions: assert property (
        @(posedge CLK) (Y == 1'b0) |-> ((A_N == 1'b0) && (B_N == 1'b0) && (C == 1'b1) && (D == 1'b1))
    );

    // A_N HIGH forces Y HIGH.
    check_a_n_dominates: assert property (
        @(posedge CLK) (A_N == 1'b1) |-> (Y == 1'b1)
    );

    // B_N HIGH forces Y HIGH.
    check_b_n_dominates: assert property (
        @(posedge CLK) (B_N == 1'b1) |-> (Y == 1'b1)
    );

    // C LOW forces Y HIGH (since ~(C&D)=1).
    check_c_low_forces_y_high: assert property (
        @(posedge CLK) (C == 1'b0) |-> (Y == 1'b1)
    );

    // D LOW forces Y HIGH (since ~(C&D)=1).
    check_d_low_forces_y_high: assert property (
        @(posedge CLK) (D == 1'b0) |-> (Y == 1'b1)
    );

    // With A_N=0 and B_N=0, Y reduces to ~(C & D).
    check_reduce_when_an_bn_low: assert property (
        @(posedge CLK) ((A_N == 1'b0) && (B_N == 1'b0)) |-> (Y == ~(C & D))
    );

    // With C=1 and D=1, Y reduces to A_N | B_N.
    check_reduce_when_c_d_high: assert property (
        @(posedge CLK) ((C == 1'b1) && (D == 1'b1)) |-> (Y == (A_N | B_N))
    );
endmodule

rtl:
module counter(clk, rst, count);
  input clk, rst;
  output reg [3:0] count;

  always @(posedge clk, posedge rst) begin
    if (rst) begin
      count <= 4'b0;
    end else if (count == 4'b1001) begin
      count <= 4'b0;
    end else begin
      count <= count + 1;
    end
  end

endmodule

sva:
module counter_sva (
    input logic clk,
    input logic rst,
    input logic [3:0] count
);

    // While reset is asserted at a clock edge, count must be 0 on the next clock.
    reset_clears_next: assert property (
        @(posedge clk) rst |=> (count == 4'd0)
    );

    // If reset is held high across consecutive clocks, count is 0 at the current clock.
    reset_hold_zero_now: assert property (
        @(posedge clk) ($past(rst) && rst) |-> (count == 4'd0)
    );

    // If reset is held high across consecutive clocks, count was 0 at the previous clock.
    reset_hold_zero_prev: assert property (
        @(posedge clk) ($past(rst) && rst) |-> ($past(count) == 4'd0)
    );

    // Out of reset, count value is always within 0..9.
    count_in_range: assert property (
        @(posedge clk) disable iff (rst) (count <= 4'd9)
    );

    // Whenever count is 9 at a clock edge (out of reset), the next value is 0.
    wrap_from_9_to_0: assert property (
        @(posedge clk) disable iff (rst) (count == 4'd9) |=> (count == 4'd0)
    );

    // If previous clock was in reset, the current count is 0.
    prev_reset_implies_zero_now: assert property (
        @(posedge clk) $past(rst) |-> (count == 4'd0)
    );

endmodule

rtl:
module generate_Z (
    input A1,
    input A2,
    input B1,
    input B2,
    input C1,
    output reg [1:0] Z
);

    wire Y;
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    assign Y = (A1 & B2 & C1) | (A2 & B1 & C1) | (A1 & B1 & ~C1) | (A2 & B2 & ~C1);
    always @ (Y) begin
        case (Y)
            2'b00: Z = 2'b00;
            2'b01: Z = 2'b01;
            2'b10: Z = 2'b10;
            2'b11: Z = 2'b11;
        endcase
    end

endmodule

sva:
module generate_Z_sva (
    input logic CLK,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic B2,
    input logic C1,
    input logic [1:0] Z
);
    // Local recomputation of Y (matches RTL equation)
    logic y;
    assign y = (A1 & B2 & C1) | (A2 & B1 & C1) | (A1 & B1 & ~C1) | (A2 & B2 & ~C1);

    ///// Functional mapping /////
    // Z must equal {1'b0, y}.
    check_z_function_mapping: assert property (
        @(posedge CLK) disable iff ($initstate) Z == {1'b0, y}
    );

    ///// Event-driven behavior /////
    // When y rises, Z must be 2'b01 in the same cycle.
    check_update_on_y_rise: assert property (
        @(posedge CLK) disable iff ($initstate) $rose(y) |-> (Z == 2'b01)
    );
    // When y falls, Z must be 2'b00 in the same cycle.
    check_update_on_y_fall: assert property (
        @(posedge CLK) disable iff ($initstate) $fell(y) |-> (Z == 2'b00)
    );
    // Z can only change when y changes.
    check_z_changes_only_if_y_changes: assert property (
        @(posedge CLK) disable iff ($initstate) $changed(Z) |-> $changed(y)
    );
    // If all inputs are stable, Z must be stable.
    check_stable_inputs_imply_stable_Z: assert property (
        @(posedge CLK) disable iff ($initstate) $stable({A1,A2,B1,B2,C1}) |-> $stable(Z)
    );

    ///// Partitioned by C1 /////
    // When C1 is 1, Z[0] equals (A1&B2)|(A2&B1) and MSB is 0.
    check_path_when_C1_is_1: assert property (
        @(posedge CLK) disable iff ($initstate) C1 |-> (Z == {1'b0, ((A1 & B2) | (A2 & B1))})
    );
    // When C1 is 0, Z[0] equals (A1&B1)|(A2&B2) and MSB is 0.
    check_path_when_C1_is_0: assert property (
        @(posedge CLK) disable iff ($initstate) !C1 |-> (Z == {1'b0, ((A1 & B1) | (A2 & B2))})
    );

    ///// Useful corollaries from the logic /////
    // If both A inputs are 0, Z must be 2'b00.
    check_zero_when_A_pair_zero: assert property (
        @(posedge CLK) disable iff ($initstate) (A1 == 1'b0 && A2 == 1'b0) |-> (Z == 2'b00)
    );
    // If both B inputs are 0, Z must be 2'b00.
    check_zero_when_B_pair_zero: assert property (
        @(posedge CLK) disable iff ($initstate) (B1 == 1'b0 && B2 == 1'b0) |-> (Z == 2'b00)
    );
    // If all A and B inputs are 1, Z must be 2'b01 (independent of C1).
    check_one_when_all_ones: assert property (
        @(posedge CLK) disable iff ($initstate) (A1 && A2 && B1 && B2) |-> (Z == 2'b01)
    );
endmodule

module sky130_fd_sc_lp__inputiso1n_sva (
    input logic A,
    input logic SLEEP_B,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB,
    input logic X
);
    // No clock or reset in DUT; purely combinational; sample on edges of inputs/outputs.

    // X must equal !A & !SLEEP_B & !VPWR & !VGND & !VPB & !VNB on any input/output edge.
    check_function_on_any_edge: assert property (
        @(posedge A or negedge A or
          posedge SLEEP_B or negedge SLEEP_B or
          posedge VPWR or negedge VPWR or
          posedge VGND or negedge VGND or
          posedge VPB or negedge VPB or
          posedge VNB or negedge VNB or
          posedge X or negedge X)
        X == (!A && !SLEEP_B && !VPWR && !VGND && !VPB && !VNB)
    );

    // If X rises, all inputs must be 0.
    check_x_rise_requires_all_low: assert property (
        @(posedge X) (A == 1'b0) && (SLEEP_B == 1'b0) && (VPWR == 1'b0) && (VGND == 1'b0) && (VPB == 1'b0) && (VNB == 1'b0)
    );

    // If any input falls such that all become 0, X must be 1.
    check_x_high_when_all_low_on_any_fall: assert property (
        @(negedge A or negedge SLEEP_B or negedge VPWR or negedge VGND or negedge VPB or negedge VNB)
        ((A == 1'b0) && (SLEEP_B == 1'b0) && (VPWR == 1'b0) && (VGND == 1'b0) && (VPB == 1'b0) && (VNB == 1'b0)) |-> (X == 1'b1)
    );

    // A high forces X low.
    check_x_low_when_A_high: assert property (
        @(posedge A) X == 1'b0
    );

    // SLEEP_B high forces X low.
    check_x_low_when_SLEEP_B_high: assert property (
        @(posedge SLEEP_B) X == 1'b0
    );

    // VPWR high forces X low.
    check_x_low_when_VPWR_high: assert property (
        @(posedge VPWR) X == 1'b0
    );

    // VGND high forces X low.
    check_x_low_when_VGND_high: assert property (
        @(posedge VGND) X == 1'b0
    );

    // VPB high forces X low.
    check_x_low_when_VPB_high: assert property (
        @(posedge VPB) X == 1'b0
    );

    // VNB high forces X low.
    check_x_low_when_VNB_high: assert property (
        @(posedge VNB) X == 1'b0
    );

endmodule

