module add8(in_a, in_b, out_sum, out_carry);

input [7:0] in_a, in_b;
output [7:0] out_sum;
output out_carry;

wire [8:0] temp_sum;

assign temp_sum = in_a + in_b;
assign out_sum = temp_sum[7:0];
assign out_carry = temp_sum[8];

endmodule

sva:
module add8_sva (
    input logic CLK,
    input logic [7:0] in_a,
    input logic [7:0] in_b,
    input logic [7:0] out_sum,
    input logic out_carry
);
    // Sum and carry match implemented 8-bit add with zero-extended carry.
    check_concat_sum_matches_8b_add: assert property (
        @(posedge CLK) {out_carry, out_sum} == {1'b0, (in_a + in_b)}
    );

    // out_sum equals 8-bit addition of inputs.
    check_sum_matches_8b_add: assert property (
        @(posedge CLK) out_sum == (in_a + in_b)
    );

    // out_carry is always zero due to zero-extension of 8-bit result.
    check_carry_const_zero: assert property (
        @(posedge CLK) out_carry == 1'b0
    );

    // Adding zero on B leaves A unchanged and carry zero.
    check_zero_b_identity: assert property (
        @(posedge CLK) (in_b == 8'h00) |-> (out_sum == in_a) && (out_carry == 1'b0)
    );

    // Adding zero on A leaves B unchanged and carry zero.
    check_zero_a_identity: assert property (
        @(posedge CLK) (in_a == 8'h00) |-> (out_sum == in_b) && (out_carry == 1'b0)
    );

    // Adding 0xFF on B decrements A modulo 256; carry remains zero.
    check_ff_b_decrement: assert property (
        @(posedge CLK) (in_b == 8'hFF) |-> (out_sum == (in_a - 8'h01)) && (out_carry == 1'b0)
    );

    // Adding 0xFF on A decrements B modulo 256; carry remains zero.
    check_ff_a_decrement: assert property (
        @(posedge CLK) (in_a == 8'hFF) |-> (out_sum == (in_b - 8'h01)) && (out_carry == 1'b0)
    );

    // Both inputs zero produce zero sum and zero carry.
    check_both_zero_result_zero: assert property (
        @(posedge CLK) (in_a == 8'h00 && in_b == 8'h00) |-> (out_sum == 8'h00) && (out_carry == 1'b0)
    );

    // Both inputs 0xFF produce 0xFE sum and zero carry (8-bit addition).
    check_both_ff_result_fe: assert property (
        @(posedge CLK) (in_a == 8'hFF && in_b == 8'hFF) |-> (out_sum == 8'hFE) && (out_carry == 1'b0)
    );
endmodule

module d_flip_flop_async_reset_sva (
    input logic CLK,
    input logic RESET_B, // active-low async reset
    input logic D,
    input logic Q
);

    ///// Reset behavior /////
    // While reset is asserted low, Q must be 0.
    check_reset_low_forces_zero: assert property (
        @(posedge CLK) (!RESET_B) |-> (Q == 1'b0)
    );

    // When reset falls (1->0), Q is 0 at this sample.
    check_reset_fall_clears_q: assert property (
        @(posedge CLK) $fell(RESET_B) |-> (Q == 1'b0)
    );

    // If reset is low in consecutive cycles, Q remains 0 across them.
    check_reset_hold_zero: assert property (
        @(posedge CLK) (!$past(RESET_B) && !RESET_B) |-> ($past(Q) == 1'b0 && Q == 1'b0)
    );

    ///// Normal capture behavior /////
    // With reset high now and previously, Q equals previous D.
    check_capture_prev_d_when_reset_high: assert property (
        @(posedge CLK) disable iff (!RESET_B) $past(RESET_B) |-> (Q == $past(D))
    );

    // After reset deasserts (prev low, now high), next cycle Q equals D from deassert cycle.
    check_capture_after_reset_release: assert property (
        @(posedge CLK) disable iff (!RESET_B) (!$past(RESET_B) && RESET_B) |=> (Q == $past(D))
    );

    // If reset high for last two cycles and D did not change, Q does not change.
    check_q_stable_if_prev_two_d_equal: assert property (
        @(posedge CLK) disable iff (!RESET_B)
            ($past(RESET_B) && $past(RESET_B,2) && ($past(D) == $past(D,2))) |-> (Q == $past(Q))
    );

    // If reset high for last two cycles and D changed, Q must change.
    check_q_changes_if_prev_two_d_differ: assert property (
        @(posedge CLK) disable iff (!RESET_B)
            ($past(RESET_B) && $past(RESET_B,2) && ($past(D) != $past(D,2))) |-> (Q != $past(Q))
    );

    // If reset high for last two cycles and Q changed, D must have changed in prior cycle.
    check_q_change_implies_prev_d_change: assert property (
        @(posedge CLK) disable iff (!RESET_B)
            ($past(RESET_B) && $past(RESET_B,2) && (Q != $past(Q))) |-> ($past(D) != $past(D,2))
    );

endmodule

