module four_input_and_gate (
  A,
  B,
  C,
  D,
  EN,
  Y
);

  input [1:0] A;
  input [1:0] B;
  input [1:0] C;
  input [1:0] D;
  input EN;
  output Y;

  assign Y = (EN == 1'b1) && (A == 2'b11) && (B == 2'b10) && (C == 2'b01) && (D == 2'b00);

endmodule

sva:
module four_input_and_gate_sva (
    input logic [1:0] A,
    input logic [1:0] B,
    input logic [1:0] C,
    input logic [1:0] D,
    input logic EN,
    input logic Y
);
    // Use a formal global clock since RTL is purely combinational and has no clock/reset.
    default clocking cb @(posedge $global_clock); endclocking

    ///// Functional equivalence /////
    // Y matches the exact combinational expression from the RTL.
    check_y_definition: assert property (
        Y === ((EN == 1'b1) && (A == 2'b11) && (B == 2'b10) && (C == 2'b01) && (D == 2'b00))
    );

    ///// Simple implications derived from the RTL /////
    // EN low forces Y low.
    check_en_low_forces_y0: assert property (
        (EN == 1'b0) |-> (Y == 1'b0)
    );
    // If A is not 2'b11, Y must be low.
    check_a_mismatch_forces_y0: assert property (
        (A != 2'b11) |-> (Y == 1'b0)
    );
    // If B is not 2'b10, Y must be low.
    check_b_mismatch_forces_y0: assert property (
        (B != 2'b10) |-> (Y == 1'b0)
    );
    // If C is not 2'b01, Y must be low.
    check_c_mismatch_forces_y0: assert property (
        (C != 2'b01) |-> (Y == 1'b0)
    );
    // If D is not 2'b00, Y must be low.
    check_d_mismatch_forces_y0: assert property (
        (D != 2'b00) |-> (Y == 1'b0)
    );

    ///// Biconditional checks /////
    // Y high implies all inputs match and EN is high.
    check_y_high_implies_conditions: assert property (
        (Y == 1'b1) |-> ((EN == 1'b1) && (A == 2'b11) && (B == 2'b10) && (C == 2'b01) && (D == 2'b00))
    );
    // When EN and all inputs match, Y must be high.
    check_conditions_imply_y_high: assert property (
        ((EN == 1'b1) && (A == 2'b11) && (B == 2'b10) && (C == 2'b01) && (D == 2'b00)) |-> (Y == 1'b1)
    );

    ///// Edge-based sanity checks /////
    // A rising edge on Y can only occur when EN and all inputs match.
    check_y_rise_implies_conditions: assert property (
        $rose(Y) |-> ((EN == 1'b1) && (A == 2'b11) && (B == 2'b10) && (C == 2'b01) && (D == 2'b00))
    );
    // A falling edge on Y implies at least one condition is now false.
    check_y_fall_implies_any_condition_false: assert property (
        $fell(Y) |-> ((EN != 1'b1) || (A != 2'b11) || (B != 2'b10) || (C != 2'b01) || (D != 2'b00))
    );

endmodule

rtl:
module binary_to_gray(
    input [3:0] bin_in,
    output [3:0] gray_out
);

    assign gray_out[3] = bin_in[3];
    assign gray_out[2] = bin_in[3] ^ bin_in[2];
    assign gray_out[1] = bin_in[2] ^ bin_in[1];
    assign gray_out[0] = bin_in[1] ^ bin_in[0];

endmodule

sva:
module binary_to_gray_sva (
    input logic clk,
    input logic [3:0] bin_in,
    input logic [3:0] gray_out
);
    // Gray MSB equals binary MSB.
    check_gray_msb_passthrough: assert property (
        @(posedge clk) gray_out[3] == bin_in[3]
    );

    // Gray[2] equals bin_in[3] XOR bin_in[2].
    check_gray_bit2_is_b3_xor_b2: assert property (
        @(posedge clk) gray_out[2] == (bin_in[3] ^ bin_in[2])
    );

    // Gray[1] equals bin_in[2] XOR bin_in[1].
    check_gray_bit1_is_b2_xor_b1: assert property (
        @(posedge clk) gray_out[1] == (bin_in[2] ^ bin_in[1])
    );

    // Gray[0] equals bin_in[1] XOR bin_in[0].
    check_gray_bit0_is_b1_xor_b0: assert property (
        @(posedge clk) gray_out[0] == (bin_in[1] ^ bin_in[0])
    );

    // Vector mapping equals {b3, b3^b2, b2^b1, b1^b0}.
    check_gray_vector_mapping: assert property (
        @(posedge clk) gray_out == {bin_in[3], (bin_in[3] ^ bin_in[2]), (bin_in[2] ^ bin_in[1]), (bin_in[1] ^ bin_in[0])}
    );

    // Binary[3] recovered from Gray equals gray_out[3].
    check_bin3_from_gray: assert property (
        @(posedge clk) bin_in[3] == gray_out[3]
    );

    // Binary[2] recovered as gray_out[3] XOR gray_out[2].
    check_bin2_from_gray: assert property (
        @(posedge clk) bin_in[2] == (gray_out[3] ^ gray_out[2])
    );

    // Binary[1] recovered as gray_out[3] XOR gray_out[2] XOR gray_out[1].
    check_bin1_from_gray: assert property (
        @(posedge clk) bin_in[1] == (gray_out[3] ^ gray_out[2] ^ gray_out[1])
    );

    // Binary[0] recovered as gray_out[3] XOR gray_out[2] XOR gray_out[1] XOR gray_out[0].
    check_bin0_from_gray: assert property (
        @(posedge clk) bin_in[0] == (gray_out[3] ^ gray_out[2] ^ gray_out[1] ^ gray_out[0])
    );
endmodule

