module full_adder(input a, input b, input cin, output sum, output cout);
    assign sum = a ^ b ^ cin;
    assign cout = (a & b) | (a & cin) | (b & cin);
endmodule
module adder8(input [7:0] a, input [7:0] b, input cin, output [7:0] sum, output cout);
    wire [7:0] s;
    wire [7:0] c;
    full_adder fa1(a[0], b[0], cin, s[0], c[0]);
    full_adder fa2(a[1], b[1], c[0], s[1], c[1]);
    full_adder fa3(a[2], b[2], c[1], s[2], c[2]);
    full_adder fa4(a[3], b[3], c[2], s[3], c[3]);
    full_adder fa5(a[4], b[4], c[3], s[4], c[4]);
    full_adder fa6(a[5], b[5], c[4], s[5], c[5]);
    full_adder fa7(a[6], b[6], c[5], s[6], c[6]);
    full_adder fa8(a[7], b[7], c[6], s[7], cout);
    assign sum = {s[7], s[6], s[5], s[4], s[3], s[2], s[1], s[0]};
endmodule

sva:
module adder8_sva (
    input  logic        CLK,
    input  logic [7:0]  a,
    input  logic [7:0]  b,
    input  logic        cin,
    input  logic [7:0]  sum,
    input  logic        cout
);
    ///// Functional arithmetic equivalence /////
    // Sum+carry equals 9-bit addition of inputs.
    check_add_result: assert property (
        @(posedge CLK) disable iff ($initstate)
        {cout, sum} == ({1'b0, a} + {1'b0, b} + cin)
    );

    // Carry-out equals MSB of 9-bit addition.
    check_cout_is_msb: assert property (
        @(posedge CLK) disable iff ($initstate)
        cout == ({1'b0, a} + {1'b0, b} + cin)[8]
    );

    // LSB sum equals a[0] XOR b[0] XOR cin.
    check_sum0_xor: assert property (
        @(posedge CLK) disable iff ($initstate)
        sum[0] == (a[0] ^ b[0] ^ cin)
    );

    ///// Special-case identities /////
    // Adding zero B and zero carry returns A with no carry.
    check_add_zero_b: assert property (
        @(posedge CLK) disable iff ($initstate)
        ((b == 8'h00) && (cin == 1'b0)) |-> ((sum == a) && (cout == 1'b0))
    );

    // Adding zero A and zero carry returns B with no carry.
    check_add_zero_a: assert property (
        @(posedge CLK) disable iff ($initstate)
        ((a == 8'h00) && (cin == 1'b0)) |-> ((sum == b) && (cout == 1'b0))
    );

    // A + ~A + 1 -> 0 with carry-out 1.
    check_complement_plus_one: assert property (
        @(posedge CLK) disable iff ($initstate)
        ((b == ~a) && (cin == 1'b1)) |-> ((sum == 8'h00) && (cout == 1'b1))
    );

    // A + ~A + 0 -> 0xFF with no carry-out.
    check_complement_no_carry: assert property (
        @(posedge CLK) disable iff ($initstate)
        ((b == ~a) && (cin == 1'b0)) |-> ((sum == 8'hFF) && (cout == 1'b0))
    );

    // 0xFF + 0 + 1 -> 0 with carry-out 1.
    check_ff_plus_one: assert property (
        @(posedge CLK) disable iff ($initstate)
        ((a == 8'hFF) && (b == 8'h00) && (cin == 1'b1)) |-> ((sum == 8'h00) && (cout == 1'b1))
    );

    ///// Temporal consistency (purely combinational determinism) /////
    // If inputs are stable, outputs remain stable.
    check_stable_outputs_when_inputs_stable: assert property (
        @(posedge CLK) disable iff ($initstate)
        ($stable(a) && $stable(b) && $stable(cin)) |-> ($stable(sum) && $stable(cout))
    );

    // With B and CIN stable, incrementing A by 1 increments the 9-bit result by 1.
    check_result_increments_when_a_increments: assert property (
        @(posedge CLK) disable iff ($initstate)
        ((a == $past(a) + 8'd1) && (b == $past(b)) && (cin == $past(cin)))
        |-> ({cout, sum} == ($past({cout, sum}) + 9'd1))
    );

    // With A and CIN stable, incrementing B by 1 increments the 9-bit result by 1.
    check_result_increments_when_b_increments: assert property (
        @(posedge CLK) disable iff ($initstate)
        ((b == $past(b) + 8'd1) && (a == $past(a)) && (cin == $past(cin)))
        |-> ({cout, sum} == ($past({cout, sum}) + 9'd1))
    );

    // When all inputs are zero, outputs are zero.
    check_all_zero: assert property (
        @(posedge CLK) disable iff ($initstate)
        ((a == 8'h00) && (b == 8'h00) && (cin == 1'b0)) |-> ((sum == 8'h00) && (cout == 1'b0))
    );
endmodule

module ones_counter_sva (
    input logic [3:0] in,
    input logic clk,
    input logic rst,
    input logic [2:0] out
);
    ///// Reset behavior /////
    // If reset was asserted in the previous cycle, out must be 0 now.
    check_reset_clears_out_next: assert property (
        @(posedge clk) $past(rst) |-> (out == 3'd0)
    );

    ///// Functional update /////
    // When not in reset in the previous cycle, out equals the previous cycle's sum of input bits.
    check_out_eq_prev_sum_when_prev_not_rst: assert property (
        @(posedge clk) disable iff (rst) $past(!rst) |-> (out == $past(in[0] + in[1] + in[2] + in[3]))
    );

    ///// Output range /////
    // out is always within 0..4.
    check_out_range: assert property (
        @(posedge clk) (out <= 3'd4)
    );

    ///// Specific input patterns /////
    // If previous input was 4'b0000 and not in reset, out is 0.
    check_prev_in_zero_results_zero: assert property (
        @(posedge clk) disable iff (rst) $past(!rst) && ($past(in) == 4'b0000) |-> (out == 3'd0)
    );

    // If previous input was one-hot and not in reset, out is 1.
    check_prev_in_onehot_results_one: assert property (
        @(posedge clk) disable iff (rst) $past(!rst) && $onehot($past(in)) |-> (out == 3'd1)
    );

    ///// Bit-level consequences /////
    // The LSB of out equals the parity (XOR) of previous inputs when not in reset.
    check_lsb_matches_parity: assert property (
        @(posedge clk) disable iff (rst) $past(!rst) |-> (out[0] == ^$past(in))
    );

    ///// Temporal consistency /////
    // If inputs were stable over the last two cycles (and not in reset), out does not change this cycle.
    check_out_stable_if_input_stable: assert property (
        @(posedge clk) disable iff (rst)
            $past(!rst) && $past(!rst,2) && ($past(in) == $past(in,2)) |-> (out == $past(out))
    );

    // If exactly one input bit toggled between the last two cycles (and not in reset), out changes by 1.
    check_one_bit_toggle_changes_by_one: assert property (
        @(posedge clk) disable iff (rst)
            $past(!rst) && $past(!rst,2) && $onehot($past(in) ^ $past(in,2))
            |-> ((out == $past(out) + 3'd1) || ($past(out) == out + 3'd1))
    );
endmodule

rtl:
module top_module (
    input clk,
    input reset,
    input [7:0] a,
    input [7:0] b,
    output reg [7:0] q
);

    wire greater_than;
    wire equal;
    wire enable;
    wire [3:0] count;
    wire [7:0] sum;

    // Instantiate the 8-bit comparator module
    comparator_module comparator_inst(
        .a(a),
        .b(b),
        .greater_than(greater_than)
    );

    // Instantiate the 4-bit binary counter module
    counter_module counter_inst(
        .clk(clk),
        .reset(reset),
        .enable(enable),
        .count(count)
    );

    // Instantiate the control logic module
    control_logic_module control_inst(
        .a(a),
        .b(b),
        .greater_than(greater_than),
        .equal(equal),
        .enable(enable)
    );

    // Instantiate the additional functional module
    functional_module functional_inst(
        .a(a[0]),
        .b(count),
        .sum(sum)
    );

    // Output the appropriate value based on the control logic
    always @(posedge clk) begin
        if (reset) begin
            q <= 0;
        end else if (greater_than) begin
            q <= count;
        end else if (equal) begin
            q <= sum;
        end else begin
            q <= a;
        end
    end

endmodule
module comparator_module (
    input [7:0] a,
    input [7:0] b,
    output reg greater_than
);

    always @(*) begin
        if (a > b) begin
            greater_than = 1;
        end else begin
            greater_than = 0;
        end
    end

endmodule
module counter_module (
    input clk,
    input reset,
    input enable,
    output reg [3:0] count
);

    always @(posedge clk) begin
        if (reset) begin
            count <= 0;
        end else if (enable) begin
            count <= count + 1;
        end
    end

endmodule
module control_logic_module (
    input [7:0] a,
    input [7:0] b,
    input greater_than,
    output reg equal,
    output reg enable
);

    always @(*) begin
        if (a > b) begin
            equal = 0;
            enable = 1;
        end else if (a < b) begin
            equal = 0;
            enable = 0;
        end else begin
            equal = 1;
            enable = 1;
        end
    end

endmodule
module functional_module (
    input a,
    input [3:0] b,
    output reg [7:0] sum
);

    always @(*) begin
        sum = {7'b0, a} + b;
    end

endmodule

sva:
module top_module_sva (
    input  logic        clk,
    input  logic        reset,   // active-high synchronous
    input  logic [7:0]  a,
    input  logic [7:0]  b,
    input  logic [7:0]  q
);

    ///// Reset behavior /////
    // When reset is asserted, q must be 0.
    reset_q_zero: assert property (
        @(posedge clk) reset |-> (q == 8'h00)
    );

    ///// Output selection rules /////
    // If a<b, q must equal a.
    q_matches_a_when_a_lt_b: assert property (
        @(posedge clk) disable iff (reset) (a < b) |-> (q == a)
    );

    // If a<b, q is strictly less than b.
    q_lt_b_when_a_lt_b: assert property (
        @(posedge clk) disable iff (reset) (a < b) |-> (q < b)
    );

    // If a>b, q comes from 4-bit counter, so upper nibble is zero.
    q_upper_nibble_zero_when_a_gt_b: assert property (
        @(posedge clk) disable iff (reset) (a > b) |-> (q[7:4] == 4'b0000)
    );

    // If a>=b, q is from counter or sum, so q <= 16.
    q_bounded_when_a_ge_b: assert property (
        @(posedge clk) disable iff (reset) (a >= b) |-> (q <= 8'h10)
    );

    // If a==b, q equals count + a[0], so q >= a[0].
    q_min_bound_when_equal: assert property (
        @(posedge clk) disable iff (reset) (a == b) |-> (q >= {7'b0, a[0]})
    );

    // If a==b and a[0]==0, q equals count (0..15).
    q_max_15_when_equal_a0_zero: assert property (
        @(posedge clk) disable iff (reset) (a == b) && (a[0] == 1'b0) |-> (q <= 8'h0F)
    );

    ///// Cross-cycle behaviors /////
    // If a>b in two consecutive cycles, q's low nibble increments by 1 (mod 16) and upper nibble stays zero.
    gt_consecutive_incr_low_nibble: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(reset) && ($past(a) > $past(b)) && (a > b))
            |-> ($past(q[7:4]) == 4'b0000) && (q[7:4] == 4'b0000) && (q[3:0] == $past(q[3:0]) + 4'd1)
    );

    // If a==b in two consecutive cycles and a[0] is stable, q's low nibble increments by 1 (mod 16).
    eq_consecutive_incr_low_nibble_a0_stable: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(reset) && ($past(a) == $past(b)) && (a == b) && ($past(a[0]) == a[0]))
            |-> (q[3:0] == $past(q[3:0]) + 4'd1)
    );

    ///// Range disambiguation /////
    // If a>=b and q>15, it must be the equal-path producing exactly 16.
    high_value_only_on_equal_16: assert property (
        @(posedge clk) disable iff (reset)
            ((a >= b) && (q > 8'h0F)) |-> ((a == b) && (q == 8'h10))
    );

endmodule

rtl:
module counter (
    input clk,
    input reset,
    output reg [3:0] count
);

always @(posedge clk) begin
    if (reset) begin
        count <= 4'b0;
    end else begin
        count <= count + 1;
    end
end

endmodule

sva:
module counter_sva (
    input logic clk,
    input logic reset,
    input logic [3:0] count
);
    // Next state equals 0 after a prior reset, else prior value + 1 (mod 16).
    check_next_state_function: assert property (
        @(posedge clk) !$initstate |-> (count == ($past(reset) ? 4'd0 : (($past(count) + 4'd1) & 4'hF)))
    );

    // Without prior reset, count increments by exactly 1 (mod 16).
    check_increment_no_reset: assert property (
        @(posedge clk) disable iff (reset) (!$past(reset)) |-> (count == (($past(count) + 4'd1) & 4'hF))
    );

    // After a reset cycle, count is 0 on the following cycle.
    check_zero_after_reset_cycle: assert property (
        @(posedge clk) $past(reset) |-> (count == 4'd0)
    );

    // If reset is asserted in two consecutive cycles, count is 0 on the second.
    check_zero_while_reset: assert property (
        @(posedge clk) (reset && $past(reset)) |-> (count == 4'd0)
    );

    // If last cycle was not reset and count was 15, it wraps to 0.
    check_wraparound_from_F_to_0: assert property (
        @(posedge clk) disable iff (reset) (!$past(reset) && ($past(count) == 4'hF)) |-> (count == 4'd0)
    );

    // While reset is held across clock edges, count remains stable.
    check_stable_during_continuous_reset: assert property (
        @(posedge clk) (reset && $past(reset)) |-> $stable(count)
    );
endmodule

rtl:
module signal_combiner (
    input [7:0] input_signals,
    output output_signal
);

    wire [7:0] input_signals_inverted;
    assign input_signals_inverted = ~input_signals;

    wire [7:0] num_ones;
    assign num_ones = {
        input_signals_inverted[0] & input_signals[1],
        input_signals_inverted[1] & input_signals[2],
        input_signals_inverted[2] & input_signals[3],
        input_signals_inverted[3] & input_signals[4],
        input_signals_inverted[4] & input_signals[5],
        input_signals_inverted[5] & input_signals[6],
        input_signals_inverted[6] & input_signals[7],
        input_signals_inverted[7]
    };

    wire at_least_four_ones;
    assign at_least_four_ones = (num_ones[0] + num_ones[1] + num_ones[2] + num_ones[3] + num_ones[4] + num_ones[5] + num_ones[6] + num_ones[7]) >= 4;

    assign output_signal = at_least_four_ones;

endmodule

sva:
module signal_combiner_sva (
    input logic [7:0] input_signals,
    input logic       output_signal
);
    // No clock or reset in DUT; pure combinational logic.
    // Assertions sample on any input bit edge to check combinational relationships.

    // Default clock: any edge on any input bit.
    default clocking comb_cb @(
        posedge input_signals[0] or negedge input_signals[0] or
        posedge input_signals[1] or negedge input_signals[1] or
        posedge input_signals[2] or negedge input_signals[2] or
        posedge input_signals[3] or negedge input_signals[3] or
        posedge input_signals[4] or negedge input_signals[4] or
        posedge input_signals[5] or negedge input_signals[5] or
        posedge input_signals[6] or negedge input_signals[6] or
        posedge input_signals[7] or negedge input_signals[7]
    ); endclocking

    // Local re-computation of DUT combinational logic from ports.
    wire [7:0] inv = ~input_signals;
    wire [7:0] num_ones_local;
    assign num_ones_local = {
        inv[0] & input_signals[1],
        inv[1] & input_signals[2],
        inv[2] & input_signals[3],
        inv[3] & input_signals[4],
        inv[4] & input_signals[5],
        inv[5] & input_signals[6],
        inv[6] & input_signals[7],
        inv[7]
    };
    wire [3:0] sum_all    = num_ones_local[0] + num_ones_local[1] + num_ones_local[2] + num_ones_local[3]
                           + num_ones_local[4] + num_ones_local[5] + num_ones_local[6] + num_ones_local[7];
    wire [3:0] sum_others =                  /* exclude num_ones_local[0] = ~input_signals[7] */
                              num_ones_local[1] + num_ones_local[2] + num_ones_local[3]
                            + num_ones_local[4] + num_ones_local[5] + num_ones_local[6] + num_ones_local[7];
    wire       computed_output = (sum_all >= 4);

    // Output equals the DUT's defined threshold function (sum_all >= 4).
    check_output_definition: assert property (output_signal == computed_output);

    // If fewer than 4 contributing terms, output must be 0.
    check_output_low_when_count_lt4: assert property ((sum_all < 4) |-> (output_signal == 1'b0));

    // If at least 4 contributing terms, output must be 1.
    check_output_high_when_count_ge4: assert property ((sum_all >= 4) |-> (output_signal == 1'b1));

    // All inputs 0 -> only ~input_signals[7] contributes; count=1 -> output 0.
    check_pattern_all_zeros: assert property ((input_signals == 8'h00) |-> (output_signal == 1'b0));

    // All inputs 1 -> no terms contribute; count=0 -> output 0.
    check_pattern_all_ones: assert property ((input_signals == 8'hFF) |-> (output_signal == 1'b0));

    // Alternating 0101_0101 yields exactly 4 contributing terms -> output 1.
    check_pattern_55: assert property ((input_signals == 8'h55) |-> (output_signal == 1'b1));

    // Alternating 1010_1010 yields exactly 4 contributing terms -> output 1.
    check_pattern_AA: assert property ((input_signals == 8'hAA) |-> (output_signal == 1'b1));

    // If MSB is 0 (so ~input_signals[7] contributes 1) and 3 other terms are 1 -> output 1.
    check_msb_zero_plus_three_pairs: assert property (((input_signals[7] == 1'b0) && (sum_others >= 3)) |-> (output_signal == 1'b1));

    // If MSB is 1 (so ~input_signals[7] contributes 0), require 4 other terms to assert -> output 1.
    check_msb_one_requires_four_pairs: assert property (((input_signals[7] == 1'b1) && (sum_others >= 4)) |-> (output_signal == 1'b1));

endmodule

rtl:
module p_aoi22 (q, qbar, i0, i1, i2, i3);
  output q, qbar;
  input i0, i1, i2, i3;
  wire [1:0] int_0n;

  nor I0 (int_0n[0], i0, i1);
  and I1 (int_0n[1], i2, i3);
  nand I2 (q, int_0n[0], int_0n[1]);
  nor I3 (qbar, int_0n[0], q);
endmodule

sva:
module p_aoi22_sva (
    input logic clk,
    input logic q,
    input logic qbar,
    input logic i0,
    input logic i1,
    input logic i2,
    input logic i3
);
    // q equals (i0|i1|~i2|~i3).
    check_q_functional: assert property (
        @(posedge clk) q == ((i0 | i1) | ((~i2) | (~i3)))
    );

    // qbar equals (i0|i1) & ~q.
    check_qbar_functional: assert property (
        @(posedge clk) qbar == ((i0 | i1) & (~q))
    );

    // qbar is always 0 due to logic structure.
    check_qbar_always_zero: assert property (
        @(posedge clk) qbar == 1'b0
    );

    // If i0 is 1 then q must be 1.
    check_q_high_when_i0_high: assert property (
        @(posedge clk) i0 |-> (q == 1'b1)
    );

    // If i1 is 1 then q must be 1.
    check_q_high_when_i1_high: assert property (
        @(posedge clk) i1 |-> (q == 1'b1)
    );

    // If i2 is 0 then q must be 1.
    check_q_high_when_i2_low: assert property (
        @(posedge clk) (~i2) |-> (q == 1'b1)
    );

    // If i3 is 0 then q must be 1.
    check_q_high_when_i3_low: assert property (
        @(posedge clk) (~i3) |-> (q == 1'b1)
    );

    // If i0=0,i1=0,i2=1,i3=1 then q must be 0.
    check_q_low_under_specific_inputs: assert property (
        @(posedge clk) ((~i0) && (~i1) && i2 && i3) |-> (q == 1'b0)
    );

    // q is 0 only when i0=0,i1=0,i2=1,i3=1.
    check_q_low_only_if_specific_inputs: assert property (
        @(posedge clk) (q == 1'b0) |-> ((~i0) && (~i1) && i2 && i3)
    );

    // When i0=0 and i1=0, qbar must be 0.
    check_qbar_zero_when_no_i0_i1: assert property (
        @(posedge clk) ((~i0) && (~i1)) |-> (qbar == 1'b0)
    );

    // If q is 1 then qbar must be 0.
    check_qbar_zero_when_q_one: assert property (
        @(posedge clk) (q == 1'b1) |-> (qbar == 1'b0)
    );

    // q and qbar are never both 1.
    check_q_qbar_never_both_one: assert property (
        @(posedge clk) !(q && qbar)
    );
endmodule

rtl:
module and_gate (
    input A, B,
    output Y
);

    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;

    and (Y, A, B); // gate output

endmodule

sva:
module and_gate_sva (
    input logic CLK,
    input logic A,
    input logic B,
    input logic Y
);
    // Output equals logical AND of inputs.
    check_and_function: assert property (
        @(posedge CLK) Y == (A & B)
    );

    // If both inputs are HIGH, output is HIGH.
    check_inputs_high_implies_y_high: assert property (
        @(posedge CLK) (A && B) |-> (Y == 1'b1)
    );

    // If A is LOW, output is LOW.
    check_a_low_forces_y_low: assert property (
        @(posedge CLK) (!A) |-> (Y == 1'b0)
    );

    // If B is LOW, output is LOW.
    check_b_low_forces_y_low: assert property (
        @(posedge CLK) (!B) |-> (Y == 1'b0)
    );

    // Output HIGH implies both inputs are HIGH.
    check_y_high_implies_inputs_high: assert property (
        @(posedge CLK) (Y == 1'b1) |-> (A && B)
    );

    // Rising edge on output requires both inputs HIGH.
    check_y_rise_requires_inputs_high: assert property (
        @(posedge CLK) $rose(Y) |-> (A && B)
    );

    // Falling edge on output implies at least one input LOW.
    check_y_fall_implies_input_low: assert property (
        @(posedge CLK) $fell(Y) |-> ((!A) || (!B))
    );

    // If inputs are stable, output is stable.
    check_stable_inputs_imply_stable_y: assert property (
        @(posedge CLK) ($stable(A) && $stable(B)) |-> $stable(Y)
    );
endmodule

rtl:
module top_module( 
    input [99:0] a, b,
    input cin,
    output cout,
    output [99:0] sum );

    reg [99:0] sum_reg;
    reg cout_reg;
    integer i;

    always @(*) begin
        sum_reg[0] = a[0] ^ b[0] ^ cin;
        cout_reg = (a[0] & b[0]) | (a[0] & cin) | (b[0] & cin);
        for (i = 1; i < 100; i = i + 1) begin
            sum_reg[i] = a[i] ^ b[i] ^ sum_reg[i-1];
            cout_reg = (a[i] & b[i]) | (a[i] & sum_reg[i-1]) | (b[i] & sum_reg[i-1]);
        end
    end

    assign sum = sum_reg;
    assign cout = cout_reg;

endmodule

sva:
module top_module_sva (
    input logic [99:0] a,
    input logic [99:0] b,
    input logic cin,
    input logic cout,
    input logic [99:0] sum
);
    // All properties are sampled on the posedge of cin (no clock/reset in RTL).

    // sum[0] equals a[0] XOR b[0] XOR cin.
    check_sum_bit0: assert property (
        @(posedge cin) sum[0] == (a[0] ^ b[0] ^ cin)
    );

    // sum[i] equals a[i] XOR b[i] XOR sum[i-1] for i=1..99.
    genvar gi;
    generate
        for (gi = 1; gi < 100; gi++) begin : g_sum_chain
            check_sum_chain: assert property (
                @(posedge cin) sum[gi] == (a[gi] ^ b[gi] ^ sum[gi-1])
            );
        end
    endgenerate

    // cout equals majority of a[99], b[99], and sum[98].
    check_cout_from_msb: assert property (
        @(posedge cin) cout == ((a[99] & b[99]) | (a[99] & sum[98]) | (b[99] & sum[98]))
    );
endmodule

rtl:
module InputCell( InputPin, FromPreviousBSCell, CaptureDR, ShiftDR, TCK, ToNextBSCell);
input  InputPin;
input  FromPreviousBSCell;
input  CaptureDR;
input  ShiftDR; 
input  TCK;     

reg Latch;      

output ToNextBSCell;
reg    ToNextBSCell;

wire SelectedInput = CaptureDR? InputPin : FromPreviousBSCell;

always @ (posedge TCK)
begin
	if(CaptureDR | ShiftDR)
		Latch<=SelectedInput;
end

always @ (negedge TCK)
begin
	ToNextBSCell<=Latch;
end


endmodule	// InputCell

sva:
module InputCell_sva (
    input logic InputPin,
    input logic FromPreviousBSCell,
    input logic CaptureDR,
    input logic ShiftDR,
    input logic TCK,
    input logic ToNextBSCell
);
    // Clock: TCK (posedge loads Latch, negedge updates ToNextBSCell). Reset: none. Logic: mixed (comb + seq).
    // Behavior: On posedge TCK with (CaptureDR|ShiftDR), selected input is latched; on next negedge, ToNextBSCell gets that latched value.

    // On negedge, when CaptureDR was 1 at prior posedge, drive sampled InputPin.
    check_capture_dr_updates_output: assert property (
        @(negedge TCK) $past(CaptureDR, 1, posedge TCK) |-> (ToNextBSCell == $past(InputPin, 1, posedge TCK))
    );

    // On negedge, when only ShiftDR was 1 at prior posedge, drive sampled FromPreviousBSCell.
    check_shift_dr_updates_output: assert property (
        @(negedge TCK) (!$past(CaptureDR, 1, posedge TCK) && $past(ShiftDR, 1, posedge TCK)) |-> (ToNextBSCell == $past(FromPreviousBSCell, 1, posedge TCK))
    );

    // On negedge, when both were 1 at prior posedge, CaptureDR has priority (use InputPin).
    check_priority_capture_over_shift: assert property (
        @(negedge TCK) ($past(CaptureDR, 1, posedge TCK) && $past(ShiftDR, 1, posedge TCK)) |-> (ToNextBSCell == $past(InputPin, 1, posedge TCK))
    );

    // On negedge, when neither enable was 1 at prior posedge, hold previous negedge value.
    check_hold_without_enable: assert property (
        @(negedge TCK) (!$past(CaptureDR, 1, posedge TCK) && !$past(ShiftDR, 1, posedge TCK)) |-> (ToNextBSCell == $past(ToNextBSCell, 1, negedge TCK))
    );

    // On negedge, any change in output must be preceded by CaptureDR or ShiftDR high at prior posedge.
    check_output_change_requires_enable: assert property (
        @(negedge TCK) (ToNextBSCell != $past(ToNextBSCell, 1, negedge TCK)) |-> $past(CaptureDR || ShiftDR, 1, posedge TCK)
    );

    // On negedge, when any enable was 1 at prior posedge, output equals selected input from that posedge.
    check_selected_input_function: assert property (
        @(negedge TCK) $past(CaptureDR || ShiftDR, 1, posedge TCK) |-> 
            (ToNextBSCell == ($past(CaptureDR, 1, posedge TCK) ? $past(InputPin, 1, posedge TCK) : $past(FromPreviousBSCell, 1, posedge TCK)))
    );

    // On negedge, if idle for two consecutive prior posedges, hold across two negedges.
    check_hold_across_two_idle_cycles: assert property (
        @(negedge TCK) (!$past(CaptureDR || ShiftDR, 1, posedge TCK) && !$past(CaptureDR || ShiftDR, 2, posedge TCK)) |-> 
            (ToNextBSCell == $past(ToNextBSCell, 2, negedge TCK))
    );
endmodule

rtl:
module comparator_4bit (
    input [3:0] A,
    input [3:0] B,
    output reg [1:0] OUT
);

    always @(*) begin
        if (A > B) begin
            OUT = 2'b01;
        end else if (A < B) begin
            OUT = 2'b10;
        end else begin
            OUT = 2'b11;
        end
    end

endmodule

sva:
module comparator_4bit_sva (
    input logic CLK,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [1:0] OUT
);
    // When A > B, OUT must be 01.
    check_gt_sets_code: assert property (
        @(posedge CLK) (A > B) |-> (OUT == 2'b01)
    );

    // When A < B, OUT must be 10.
    check_lt_sets_code: assert property (
        @(posedge CLK) (A < B) |-> (OUT == 2'b10)
    );

    // When A == B, OUT must be 11.
    check_eq_sets_code: assert property (
        @(posedge CLK) (A == B) |-> (OUT == 2'b11)
    );

    // OUT must never be 00.
    check_out_never_00: assert property (
        @(posedge CLK) (OUT != 2'b00)
    );

    // If OUT is 01, then A > B.
    check_code_implies_gt: assert property (
        @(posedge CLK) (OUT == 2'b01) |-> (A > B)
    );

    // If OUT is 10, then A < B.
    check_code_implies_lt: assert property (
        @(posedge CLK) (OUT == 2'b10) |-> (A < B)
    );

    // If OUT is 11, then A == B.
    check_code_implies_eq: assert property (
        @(posedge CLK) (OUT == 2'b11) |-> (A == B)
    );
endmodule

rtl:
module barrel_shifter(
  input [3:0] in,
  input [1:0] shift,
  input dir,
  output [3:0] out
);

  wire [3:0] shifted_right;
  wire [3:0] shifted_left;

  assign shifted_right = {in[1:0], 2'b00};
  assign shifted_left = {2'b00, in[3:2]};

  assign out = (dir == 0) ? shifted_right >> shift : shifted_left << shift;

endmodule

sva:
module barrel_shifter_sva (
    input logic clk,
    input logic [3:0] in,
    input logic [1:0] shift,
    input logic dir,
    input logic [3:0] out
);
    // Combinational RTL with no reset/clock; assertions sample on 'clk'.

    // When dir==0, out equals right-path expression.
    check_dir0_function: assert property (
        @(posedge clk) (dir == 1'b0) |-> (out == ({in[1:0], 2'b00} >> shift))
    );

    // When dir==1, out equals left-path expression.
    check_dir1_function: assert property (
        @(posedge clk) (dir == 1'b1) |-> (out == ({2'b00, in[3:2]} << shift))
    );

    // dir==0, shift==0 maps low 2 bits to out[3:2], zeros in out[1:0].
    map_dir0_s0: assert property (
        @(posedge clk) (dir == 1'b0 && shift == 2'd0) |-> (out[3:2] == in[1:0] && out[1:0] == 2'b00)
    );

    // dir==0, shift==1 maps low 2 bits to out[2:1], zeros at out[3] and out[0].
    map_dir0_s1: assert property (
        @(posedge clk) (dir == 1'b0 && shift == 2'd1) |-> (out[3] == 1'b0 && out[2:1] == in[1:0] && out[0] == 1'b0)
    );

    // dir==0, shift==2 maps low 2 bits to out[1:0], zeros in out[3:2].
    map_dir0_s2: assert property (
        @(posedge clk) (dir == 1'b0 && shift == 2'd2) |-> (out[3:2] == 2'b00 && out[1:0] == in[1:0])
    );

    // dir==0, shift==3 maps in[1] to out[0], zeros in out[3:1].
    map_dir0_s3: assert property (
        @(posedge clk) (dir == 1'b0 && shift == 2'd3) |-> (out[3:1] == 3'b000 && out[0] == in[1])
    );

    // dir==1, shift==0 maps high 2 bits to out[1:0], zeros in out[3:2].
    map_dir1_s0: assert property (
        @(posedge clk) (dir == 1'b1 && shift == 2'd0) |-> (out[3:2] == 2'b00 && out[1:0] == in[3:2])
    );

    // dir==1, shift==1 maps high 2 bits to out[2:1], zeros at out[3] and out[0].
    map_dir1_s1: assert property (
        @(posedge clk) (dir == 1'b1 && shift == 2'd1) |-> (out[3] == 1'b0 && out[2:1] == in[3:2] && out[0] == 1'b0)
    );

    // dir==1, shift==2 maps high 2 bits to out[3:2], zeros in out[1:0].
    map_dir1_s2: assert property (
        @(posedge clk) (dir == 1'b1 && shift == 2'd2) |-> (out[3:2] == in[3:2] && out[1:0] == 2'b00)
    );

    // dir==1, shift==3 maps in[2] to out[3], zeros in out[2:0].
    map_dir1_s3: assert property (
        @(posedge clk) (dir == 1'b1 && shift == 2'd3) |-> (out[3] == in[2] && out[2:0] == 3'b000)
    );

endmodule

rtl:
module full_adder (
  input A,
  input B,
  input Cin,
  output S,
  output Cout
);

  assign S = A ^ B ^ Cin;
  assign Cout = (A & B) | (A & Cin) | (B & Cin);

endmodule

module ripple_carry_adder #(
  parameter n = 4 // number of bits in the input and output
)(
  input [n-1:0] A,
  input [n-1:0] B,
  output [n-1:0] S
);


wire [n:0] carry;
genvar i;

generate
  for (i = 0; i < n; i = i + 1) begin : adder
    full_adder fa (
      .A(A[i]),
      .B(B[i]),
      .Cin(carry[i]),
      .S(S[i]),
      .Cout(carry[i+1])
    );
  end
endgenerate

assign carry[0] = 1'b0;

endmodule

sva:
module ripple_carry_adder_sva #(
    parameter int n = 4
)(
    input logic clk,
    input logic [n-1:0] A,
    input logic [n-1:0] B,
    input logic [n-1:0] S
);
    ///// Functional correctness /////
    // S equals the n-bit sum of A and B (truncated modulo 2^n).
    check_sum_mod_n: assert property (
        @(posedge clk) S == (A + B)
    );

    // LSB sum has no carry-in: S[0] == A[0] ^ B[0].
    check_lsb_xor: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0])
    );

    // If A is zero, S must equal B.
    check_identity_A_zero: assert property (
        @(posedge clk) (A == '0) |-> (S == B)
    );

    // If B is zero, S must equal A.
    check_identity_B_zero: assert property (
        @(posedge clk) (B == '0) |-> (S == A)
    );

    // With no overlapping 1s, addition reduces to bitwise OR.
    check_disjoint_inputs_or: assert property (
        @(posedge clk) ((A & B) == '0) |-> (S == (A | B))
    );

    // Equal operands sum to a left shift by 1 (modulo 2^n).
    check_equal_operands_shift: assert property (
        @(posedge clk) (A == B) |-> (S == (A << 1))
    );

    // Complementary operands sum to all ones (modulo 2^n).
    check_complementary_operands_all_ones: assert property (
        @(posedge clk) (B == ~A) |-> (S == {n{1'b1}})
    );

    ///// Local carry-in determinism from LSB /////
    // If A[0]=0 and B[0]=0, carry into bit1 is 0 so S[1]==A[1]^B[1].
    if (n > 1) begin : g_bit1_props
        check_bit1_xor_when_lsb_00: assert property (
            @(posedge clk) (A[0] == 1'b0 && B[0] == 1'b0) |-> (S[1] == (A[1] ^ B[1]))
        );
        // If A[0]=1 and B[0]=1, carry into bit1 is 1 so S[1]==~(A[1]^B[1]).
        check_bit1_xnor_when_lsb_11: assert property (
            @(posedge clk) (A[0] == 1'b1 && B[0] == 1'b1) |-> (S[1] == ~(A[1] ^ B[1]))
        );
    end

    ///// Higher-bit XOR when all lower bits are zero /////
    // For any i>0, if all lower bits of A and B are zero, carry-in to i is 0 so S[i]==A[i]^B[i].
    genvar i;
    generate
        for (i = 1; i < n; i++) begin : lower_zeros_imp_xor
            check_xor_when_lower_zeros: assert property (
                @(posedge clk) ((A[i-1:0] == '0) && (B[i-1:0] == '0)) |-> (S[i] == (A[i] ^ B[i]))
            );
        end
    endgenerate
endmodule

