module halves_sum(
    input [31:0] in,
    output reg [15:0] out
);

    always @(*) begin
        out = (in[31:16] + in[15:0]);
    end

endmodule

sva:
module halves_sum_sva (
    input logic [31:0] in,
    input logic [15:0] out
);
    // No clock or reset in RTL; pure combinational: out = (in[31:16] + in[15:0]) truncated to 16 bits.

    always_comb begin
        // out equals the 16-bit sum of upper and lower halves (truncated).
        check_out_eq_halves_sum: assert (out == (in[31:16] + in[15:0]));
        // If upper half is zero, out equals lower half.
        check_upper_zero_passthrough: assert ((in[31:16] != 16'h0000) || (out == in[15:0]));
        // If lower half is zero, out equals upper half.
        check_lower_zero_passthrough: assert ((in[15:0] != 16'h0000) || (out == in[31:16]));
        // When both halves are 0xFFFF, sum truncates to 0xFFFE.
        check_overflow_fffe: assert (!((in[31:16] == 16'hFFFF) && (in[15:0] == 16'hFFFF)) || (out == 16'hFFFE));
        // When upper is 0x0001 and lower is 0xFFFF, sum wraps to 0x0000.
        check_wrap_zero_example: assert (!((in[31:16] == 16'h0001) && (in[15:0] == 16'hFFFF)) || (out == 16'h0000));
    end
endmodule

module memory_sva #(
  parameter bits = 32,
  parameter words = 1024
)(
  input logic clk,
  input logic [9:0] addr,
  input logic [bits-1:0] data_in,
  input logic [bits-1:0] mem
);
    // Clock: clk (posedge). No reset in RTL.
    // Sequential: mem captures data_in when (addr < words), else holds.

    // If in-range last cycle, mem now equals last cycle's data_in.
    update_on_prev_in_range: assert property (
        @(posedge clk) disable iff ($initstate) $past(addr < words) |-> (mem == $past(data_in))
    );

    // If out-of-range last cycle, mem holds its previous value.
    hold_on_prev_out_of_range: assert property (
        @(posedge clk) disable iff ($initstate) !$past(addr < words) |-> (mem == $past(mem))
    );

    // Any change in mem requires in-range condition last cycle.
    change_requires_prev_in_range: assert property (
        @(posedge clk) disable iff ($initstate) (mem != $past(mem)) |-> $past(addr < words)
    );

    // When mem changes, the new value must equal last cycle's data_in.
    change_value_matches_prev_data_in: assert property (
        @(posedge clk) disable iff ($initstate) (mem != $past(mem)) |-> (mem == $past(data_in))
    );

    // Exact next-state function for mem based on previous cycle.
    next_state_function: assert property (
        @(posedge clk) disable iff ($initstate) mem == ($past(addr < words) ? $past(data_in) : $past(mem))
    );

    // If in-range last cycle and data_in differed from prior mem, mem must change.
    must_change_when_prev_in_range_and_data_differs: assert property (
        @(posedge clk) disable iff ($initstate) ($past(addr < words) && ($past(data_in) != $past(mem))) |-> (mem != $past(mem))
    );

    // If in-range last cycle and data_in equaled prior mem, mem must not change.
    no_change_when_prev_in_range_and_data_same: assert property (
        @(posedge clk) disable iff ($initstate) ($past(addr < words) && ($past(data_in) == $past(mem))) |-> (mem == $past(mem))
    );

    // If mem did not change, either last cycle was out-of-range or same data was captured.
    no_change_reason: assert property (
        @(posedge clk) disable iff ($initstate) (mem == $past(mem)) |-> (!$past(addr < words) || ($past(data_in) == $past(mem)))
    );

endmodule

rtl:
module xor_gate(
    input a,
    input b,
    output reg out
);

always @(*) begin
    out = a ^ b;
end

endmodule

sva:
module xor_gate_sva (
    input logic clk,
    input logic a,
    input logic b,
    input logic out
);
    // Output equals XOR of inputs each cycle.
    check_xor_function: assert property (
        @(posedge clk) out == (a ^ b)
    );

    // When inputs are equal, output is 0.
    check_out_zero_when_inputs_equal: assert property (
        @(posedge clk) (a == b) |-> (out == 1'b0)
    );

    // When inputs differ, output is 1.
    check_out_one_when_inputs_differ: assert property (
        @(posedge clk) (a != b) |-> (out == 1'b1)
    );

    // Output change equals parity of input changes (exactly one input change causes output change).
    check_change_parity_relation: assert property (
        @(posedge clk) ($changed(out) == ($changed(a) ^ $changed(b)))
    );

    // If only 'a' changes, output changes.
    check_out_changes_on_a_only: assert property (
        @(posedge clk) ($changed(a) && !$changed(b)) |-> $changed(out)
    );

    // If only 'b' changes, output changes.
    check_out_changes_on_b_only: assert property (
        @(posedge clk) (!$changed(a) && $changed(b)) |-> $changed(out)
    );

    // If both inputs change, output does not change.
    check_out_stable_on_both_change: assert property (
        @(posedge clk) ($changed(a) && $changed(b)) |-> !$changed(out)
    );

    // If both inputs are stable, output is stable.
    check_out_stable_when_inputs_stable: assert property (
        @(posedge clk) ($stable(a) && $stable(b)) |-> $stable(out)
    );

    // Truth table: a=0,b=0 => out=0.
    check_tt_00: assert property (
        @(posedge clk) (!a && !b) |-> (out == 1'b0)
    );

    // Truth table: a=1,b=0 => out=1.
    check_tt_10: assert property (
        @(posedge clk) (a && !b) |-> (out == 1'b1)
    );

    // Truth table: a=0,b=1 => out=1.
    check_tt_01: assert property (
        @(posedge clk) (!a && b) |-> (out == 1'b1)
    );

    // Truth table: a=1,b=1 => out=0.
    check_tt_11: assert property (
        @(posedge clk) (a && b) |-> (out == 1'b0)
    );
endmodule

module xor_8bit_sva (
    input logic clk,
    input logic [7:0] A,
    input logic [7:0] B,
    input logic [7:0] C
);
    // C must equal bitwise XOR of A and B every cycle.
    check_vector_xor: assert property (
        @(posedge clk) C == (A ^ B)
    );

    // Change in C equals XOR of changes in A and B (delta identity).
    check_delta_identity: assert property (
        @(posedge clk) 1'b1 |=> ((C ^ $past(C)) == ((A ^ $past(A)) ^ (B ^ $past(B))))
    );

    // If both inputs are stable, output must be stable too.
    check_stable_if_inputs_stable: assert property (
        @(posedge clk) 1'b1 |=> (($stable(A) && $stable(B)) |-> $stable(C))
    );

    // Each output bit equals XOR of corresponding input bits.
    genvar i;
    generate
        for (i = 0; i < 8; i++) begin : gen_bit
            // C[i] must equal A[i] ^ B[i] each cycle.
            check_bit_xor: assert property (
                @(posedge clk) C[i] == (A[i] ^ B[i])
            );
        end
    endgenerate
endmodule

rtl:
module counter (
    input clk,
    input reset,
    output reg [3:0] count
);

always @(posedge clk) begin
    if (reset) begin
        count <= 4'b0000;
    end else begin
        count <= count + 1;
    end
end

endmodule

sva:
module counter_sva (
    input logic clk,
    input logic reset,      // Active-high synchronous reset
    input logic [3:0] count // 4-bit up-counter output
);

    // If reset was asserted in the previous cycle, count is 0 now.
    check_reset_clears_count: assert property (
        @(posedge clk) disable iff (reset)
            $past(reset) |-> (count == 4'd0)
    );

    // If last cycle was not reset and not at max, increment by 1.
    check_increment_nonwrap: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(reset) && ($past(count) != 4'hF)) |-> (count == $past(count) + 4'd1)
    );

    // If last cycle was not reset and at max, wrap to 0.
    check_wrap_on_max: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(reset) && ($past(count) == 4'hF)) |-> (count == 4'd0)
    );

    // Without reset last cycle, count must change every cycle.
    check_change_each_cycle_without_reset: assert property (
        @(posedge clk) disable iff (reset)
            !$past(reset) |-> (count != $past(count))
    );

    // Over two cycles without reset and starting <=13, net increment is +2.
    check_two_cycle_increment_small_range: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(reset,2) && !$past(reset,1) && ($past(count,2) <= 4'd13)) |-> (count == $past(count,2) + 4'd2)
    );

    // Over two cycles without reset, starting at 14 wraps to 0.
    check_two_cycle_wrap_from_14: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(reset,2) && !$past(reset,1) && ($past(count,2) == 4'd14)) |-> (count == 4'd0)
    );

    // Over two cycles without reset, starting at 15 ends at 1.
    check_two_cycle_wrap_from_15: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(reset,2) && !$past(reset,1) && ($past(count,2) == 4'd15)) |-> (count == 4'd1)
    );

    // With no resets for 16 cycles, the count value repeats.
    check_16_cycle_periodicity_no_reset: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(reset,1)  && !$past(reset,2)  && !$past(reset,3)  && !$past(reset,4)  &&
             !$past(reset,5)  && !$past(reset,6)  && !$past(reset,7)  && !$past(reset,8)  &&
             !$past(reset,9)  && !$past(reset,10) && !$past(reset,11) && !$past(reset,12) &&
             !$past(reset,13) && !$past(reset,14) && !$past(reset,15) && !$past(reset,16))
            |-> (count == $past(count,16))
    );

    // If last cycle was not reset and count is 0 now, previous count was 15.
    check_zero_implies_prev_15_when_no_prev_reset: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(reset) && (count == 4'd0)) |-> ($past(count) == 4'hF)
    );

    // Over three cycles without reset and starting <=12, net increment is +3.
    check_three_cycle_increment_small_range: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(reset,3) && !$past(reset,2) && !$past(reset,1) && ($past(count,3) <= 4'd12)) |-> (count == $past(count,3) + 4'd3)
    );

endmodule

rtl:
module adder_mod (
    input [3:0] A,
    input [3:0] B,
    output [3:0] sum
);

    wire [3:0] carry;
    wire [3:0] full_sum;

    // Add each bit of A and B, storing the result in full_sum
    // and the carry out in carry
    full_adder fa0 (.a(A[0]), .b(B[0]), .cin(1'b0), .sum(full_sum[0]), .cout(carry[0]));
    full_adder fa1 (.a(A[1]), .b(B[1]), .cin(carry[0]), .sum(full_sum[1]), .cout(carry[1]));
    full_adder fa2 (.a(A[2]), .b(B[2]), .cin(carry[1]), .sum(full_sum[2]), .cout(carry[2]));
    full_adder fa3 (.a(A[3]), .b(B[3]), .cin(carry[2]), .sum(full_sum[3]), .cout(carry[3]));

    // The final sum is the 4 least significant bits of full_sum
    assign sum = full_sum[3:0];

endmodule

module full_adder (
    input a,
    input b,
    input cin,
    output sum,
    output cout
);

    assign {cout,sum} = a + b + cin;

endmodule

sva:
module adder_mod_sva (
    input  logic        CLK,        // sampling clock for SVA
    input  logic [3:0]  A,
    input  logic [3:0]  B,
    input  logic [3:0]  sum,
    // Internal nets from adder_mod (bind to these for deeper checks)
    input  logic [3:0]  carry,
    input  logic [3:0]  full_sum
);
    // sum must equal internal full_sum bus.
    check_sum_matches_full_sum: assert property (
        @(posedge CLK) sum == full_sum
    );

    // fa0 implements A[0] + B[0] with cin=0.
    check_fa0_arith: assert property (
        @(posedge CLK) {carry[0], full_sum[0]} == (A[0] + B[0] + 1'b0)
    );

    // fa1 implements A[1] + B[1] with cin=carry[0].
    check_fa1_arith: assert property (
        @(posedge CLK) {carry[1], full_sum[1]} == (A[1] + B[1] + carry[0])
    );

    // fa2 implements A[2] + B[2] with cin=carry[1].
    check_fa2_arith: assert property (
        @(posedge CLK) {carry[2], full_sum[2]} == (A[2] + B[2] + carry[1])
    );

    // fa3 implements A[3] + B[3] with cin=carry[2].
    check_fa3_arith: assert property (
        @(posedge CLK) {carry[3], full_sum[3]} == (A[3] + B[3] + carry[2])
    );

    // Overall 5-bit result equals A + B (carry-out plus 4-bit sum).
    check_total_addition: assert property (
        @(posedge CLK) {carry[3], sum} == ({1'b0, A} + {1'b0, B})
    );

    // sum equals the truncated (LSB 4) of A + B.
    check_sum_truncation: assert property (
        @(posedge CLK) sum == (A + B)[3:0]
    );

    // Carry[0] is generate term for LSB adder (cin=0).
    check_carry0_generate: assert property (
        @(posedge CLK) carry[0] == (A[0] & B[0])
    );

    // Carry[1] is majority of A[1], B[1], carry[0].
    check_carry1_majority: assert property (
        @(posedge CLK) carry[1] == ((A[1] & B[1]) | (A[1] & carry[0]) | (B[1] & carry[0]))
    );

    // Carry[2] is majority of A[2], B[2], carry[1].
    check_carry2_majority: assert property (
        @(posedge CLK) carry[2] == ((A[2] & B[2]) | (A[2] & carry[1]) | (B[2] & carry[1]))
    );

    // Carry[3] is majority of A[3], B[3], carry[2].
    check_carry3_majority: assert property (
        @(posedge CLK) carry[3] == ((A[3] & B[3]) | (A[3] & carry[2]) | (B[3] & carry[2]))
    );

    // LSB sum bit is XOR of inputs (cin=0).
    check_sum0_xor: assert property (
        @(posedge CLK) full_sum[0] == (A[0] ^ B[0])
    );

    // Upper sum bits are XOR of inputs and incoming carry.
    check_sum_high_xor: assert property (
        @(posedge CLK) full_sum[3:1] == (A[3:1] ^ B[3:1] ^ carry[2:0])
    );
endmodule

rtl:
module bitwise_xor(
  input [31:0] a,
  input [31:0] b,
  output [31:0] out
);

  reg [31:0] temp;

  always @(*) begin
    temp = a ^ b;
  end

  assign out = temp;

endmodule

sva:
module bitwise_xor_sva (
    input logic [31:0] a,
    input logic [31:0] b,
    input logic [31:0] out
);
    // Combinational DUT with no clock/reset; sample on $global_clock and mask $initstate.

    // out equals bitwise XOR of a and b.
    check_out_is_xor: assert property (
        @($global_clock) disable iff ($initstate) (out == (a ^ b))
    );

    // If inputs are equal, out must be zero.
    check_zero_when_inputs_equal: assert property (
        @($global_clock) disable iff ($initstate) (a == b) |-> (out == 32'h0000_0000)
    );

    // If b is zero, out equals a.
    check_out_equals_a_when_b_zero: assert property (
        @($global_clock) disable iff ($initstate) (b == 32'h0000_0000) |-> (out == a)
    );

    // If a is zero, out equals b.
    check_out_equals_b_when_a_zero: assert property (
        @($global_clock) disable iff ($initstate) (a == 32'h0000_0000) |-> (out == b)
    );

    // If b is all ones, out equals bitwise NOT of a.
    check_out_is_invert_a_when_b_ones: assert property (
        @($global_clock) disable iff ($initstate) (b == 32'hFFFF_FFFF) |-> (out == ~a)
    );

    // If a is all ones, out equals bitwise NOT of b.
    check_out_is_invert_b_when_a_ones: assert property (
        @($global_clock) disable iff ($initstate) (a == 32'hFFFF_FFFF) |-> (out == ~b)
    );

    // XOR inverse: out ^ a equals b.
    check_inverse_property_with_a: assert property (
        @($global_clock) disable iff ($initstate) ((out ^ a) == b)
    );

    // XOR inverse: out ^ b equals a.
    check_inverse_property_with_b: assert property (
        @($global_clock) disable iff ($initstate) ((out ^ b) == a)
    );

    // If inputs are stable across a cycle, output must be stable.
    check_stability_when_inputs_stable: assert property (
        @($global_clock) disable iff ($initstate) ($stable(a) && $stable(b)) |-> $stable(out)
    );

    // If output changes, at least one input must have changed.
    check_output_change_requires_input_change: assert property (
        @($global_clock) disable iff ($initstate) (!$stable(out)) |-> (!$stable(a) || !$stable(b))
    );

endmodule

rtl:
module counter (
    input clk,
    input reset,
    input [3:0] N,
    output reg [3:0] count_out
);

    always @(posedge clk, posedge reset) begin
        if (reset) begin
            count_out <= 4'b0000;
        end else if (count_out == N) begin
            count_out <= 4'b0000;
        end else begin
            count_out <= count_out + 1;
        end
    end

endmodule
module adder_subtractor (
    input [3:0] A,
    input [3:0] B,
    input mode,
    output reg [3:0] out
);

    always @(*) begin
        if (mode) begin
            out = A + B;
        end else begin
            out = A - B;
        end
    end

endmodule
module top_module (
    input clk,
    input reset,
    input [3:0] N,
    input [3:0] B,
    input mode,
    input select,
    output reg [3:0] q
);

    wire [3:0] count_out;
    wire [3:0] out;

    counter counter_inst (
        .clk(clk),
        .reset(reset),
        .N(N),
        .count_out(count_out)
    );

    adder_subtractor adder_subtractor_inst (
        .A(count_out),
        .B(B),
        .mode(mode),
        .out(out)
    );

    always @(posedge clk) begin
        if (select) begin
            q <= count_out;
        end else begin
            q <= out;
        end
    end

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic reset,
    input logic [3:0] N,
    input logic [3:0] B,
    input logic mode,
    input logic select,
    input logic [3:0] q
);
    ///// counter: reset and step rules /////
    // After a cycle with reset HIGH, counter must be 0 on the next clock.
    check_counter_reset_next_zero: assert property (
        @(posedge clk) disable iff (reset)
            $past(reset) |-> (counter_inst.count_out == 4'd0)
    );

    // If previous cycle was not in reset and count_out != N, it increments by 1.
    check_counter_increment: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(reset) && ($past(counter_inst.count_out) != $past(N))) |-> 
                (counter_inst.count_out == ($past(counter_inst.count_out) + 4'd1))
    );

    // If previous cycle was not in reset and count_out == N, it wraps to 0.
    check_counter_wrap_to_zero_on_match: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(reset) && ($past(counter_inst.count_out) == $past(N))) |-> 
                (counter_inst.count_out == 4'd0)
    );

    ///// adder_subtractor: combinational function /////
    // In add mode, out equals A + B (A is counter_inst.count_out).
    check_adder_add_mode: assert property (
        @(posedge clk) disable iff (reset)
            mode |-> (adder_subtractor_inst.out == (counter_inst.count_out + B))
    );

    // In sub mode, out equals A - B (A is counter_inst.count_out).
    check_adder_sub_mode: assert property (
        @(posedge clk) disable iff (reset)
            !mode |-> (adder_subtractor_inst.out == (counter_inst.count_out - B))
    );

    ///// q register: loads selected source on each clock /////
    // If previous cycle selected counter path, q equals previous count_out.
    check_q_load_prev_count_on_select1: assert property (
        @(posedge clk) disable iff (reset)
            $past(select) |-> (q == $past(counter_inst.count_out))
    );

    // If previous cycle selected adder/subtractor path, q equals previous out.
    check_q_load_prev_out_on_select0: assert property (
        @(posedge clk) disable iff (reset)
            !$past(select) |-> (q == $past(adder_subtractor_inst.out))
    );

    ///// End-to-end: when select stays HIGH, q behaves like the counter /////
    // With select HIGH in consecutive cycles, q steps by +1 unless it hits N, then wraps to 0.
    check_q_steps_like_counter_when_select_held: assert property (
        @(posedge clk) disable iff (reset)
            ($past(select) && select && !$past(reset)) |-> 
                (q == (($past(q) == $past(N)) ? 4'd0 : ($past(q) + 4'd1)))
    );

    // With select HIGH in consecutive cycles and q hit N previously, q must be 0 now.
    check_q_wrap_when_select_held: assert property (
        @(posedge clk) disable iff (reset)
            ($past(select) && select && !$past(reset) && ($past(q) == $past(N))) |-> 
                (q == 4'd0)
    );

    // With select HIGH in consecutive cycles and q != N previously, q increments by 1.
    check_q_inc_when_select_held_not_at_N: assert property (
        @(posedge clk) disable iff (reset)
            ($past(select) && select && !$past(reset) && ($past(q) != $past(N))) |-> 
                (q == ($past(q) + 4'd1))
    );
endmodule

rtl:
module adder4bit(
  input [3:0] A,
  input [3:0] B,
  input C_in,
  output [3:0] S,
  output C_out
);

  wire [4:0] temp;

  assign temp = A + B + C_in;
  assign S = temp[3:0];
  assign C_out = temp[4];

endmodule

sva:
module adder4bit_sva (
    input logic CLK,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic C_in,
    input logic [3:0] S,
    input logic C_out
);
    // Sum+carry concatenation equals zero-extended 4-bit addition result.
    check_concat_sum: assert property (
        @(posedge CLK) {C_out, S} == {1'b0, (A + B + C_in)}
    );

    // Sum equals 4-bit truncated A+B+C_in.
    check_sum_lower4: assert property (
        @(posedge CLK) S == (A + B + C_in)
    );

    // Carry-out is always zero due to 4-bit addition width.
    check_cout_zero: assert property (
        @(posedge CLK) C_out == 1'b0
    );

    // Bit0 of sum is XOR of A0, B0, and C_in.
    check_bit0_xor: assert property (
        @(posedge CLK) S[0] == (A[0] ^ B[0] ^ C_in)
    );

    // Bit1 of sum uses carry from bit0.
    check_bit1_xor_with_c0: assert property (
        @(posedge CLK) S[1] == (A[1] ^ B[1] ^ ((A[0]&B[0]) | (A[0]&C_in) | (B[0]&C_in)))
    );

    // Bit2 of sum uses carry from bit1 (which depends on bit0).
    check_bit2_xor_with_c1: assert property (
        @(posedge CLK) S[2] == (
            A[2] ^ B[2] ^
            ( (A[1]&B[1]) |
              (A[1]&((A[0]&B[0]) | (A[0]&C_in) | (B[0]&C_in))) |
              (B[1]&((A[0]&B[0]) | (A[0]&C_in) | (B[0]&C_in))) )
        )
    );

    // Bit3 of sum uses carry from bit2 (which depends on bits1..0).
    check_bit3_xor_with_c2: assert property (
        @(posedge CLK) S[3] == (
            A[3] ^ B[3] ^
            ( (A[2]&B[2]) |
              (A[2] &
                 ( (A[1]&B[1]) |
                   (A[1]&((A[0]&B[0]) | (A[0]&C_in) | (B[0]&C_in))) |
                   (B[1]&((A[0]&B[0]) | (A[0]&C_in) | (B[0]&C_in))) )
              ) |
              (B[2] &
                 ( (A[1]&B[1]) |
                   (A[1]&((A[0]&B[0]) | (A[0]&C_in) | (B[0]&C_in))) |
                   (B[1]&((A[0]&B[0]) | (A[0]&C_in) | (B[0]&C_in))) )
              )
            )
        )
    );

    // Adding zero operand and zero carry returns the other operand (B zero).
    check_add_zero_identity_Bzero: assert property (
        @(posedge CLK) (B == 4'b0000 && C_in == 1'b0) |-> (S == A && C_out == 1'b0)
    );

    // Adding zero operand and zero carry returns the other operand (A zero).
    check_add_zero_identity_Azero: assert property (
        @(posedge CLK) (A == 4'b0000 && C_in == 1'b0) |-> (S == B && C_out == 1'b0)
    );

    // All zeros in yields all zeros out.
    check_all_zero_pass_through: assert property (
        @(posedge CLK) (A == 4'b0000 && B == 4'b0000 && C_in == 1'b0) |-> (S == 4'b0000 && C_out == 1'b0)
    );
endmodule

rtl:
module adder_4bit (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    input enable,
    output [3:0] Sum,
    output Cout
);

    wire [3:0] sum;
    wire [4:0] adder_out;

    assign sum = A + B + Cin;
    assign adder_out = {Cin, sum};

    assign Cout = (adder_out > 4'b1111);
    assign Sum = (enable) ? sum : A;

endmodule

sva:
module adder_4bit_sva (
    input logic CLK,          // External clock for assertions (RTL is purely combinational, no reset)
    input logic [3:0] A,
    input logic [3:0] B,
    input logic Cin,
    input logic enable,
    input logic [3:0] Sum,
    input logic Cout
);

    // Sum muxes between A and (A+B+Cin)[3:0] based on enable.
    check_sum_mux: assert property (
        @(posedge CLK) Sum == (enable ? (A + B + Cin)[3:0] : A)
    );

    // When disabled, Sum equals A.
    check_sum_bypass: assert property (
        @(posedge CLK) !enable |-> (Sum == A)
    );

    // When enabled, Sum equals the low 4 bits of A + B + Cin.
    check_sum_add_low4: assert property (
        @(posedge CLK) enable |-> (Sum == (A + B + Cin)[3:0])
    );

    // Cout equals Cin given comparator implementation.
    check_cout_equals_cin: assert property (
        @(posedge CLK) (Cout == Cin)
    );

    // Cin HIGH implies Cout HIGH.
    check_cout_when_cin_high: assert property (
        @(posedge CLK) Cin |-> (Cout == 1'b1)
    );

    // Cin LOW implies Cout LOW.
    check_cout_when_cin_low: assert property (
        @(posedge CLK) !Cin |-> (Cout == 1'b0)
    );

    // If B==0 and Cin==0, Sum equals A regardless of enable.
    check_sum_identity_when_B0_C0: assert property (
        @(posedge CLK) (B == 4'b0000 && Cin == 1'b0) |-> (Sum == A)
    );

endmodule

rtl:
module flip_flop (
    output Q   ,
    output Q_N ,
    input  CLK ,
    input  D   ,
    input  SCD ,
    input  SCE ,
    input  VPWR,
    input  VGND,
    input  VPB ,
    input  VNB 
);

    reg Q;
    wire Q_N;

    assign Q_N = ~Q;

    always @(posedge CLK) begin
        if (SCD && ~SCE) begin
            Q <= 1'b1;
        end else if (~SCD && SCE) begin
            Q <= 1'b0;
        end else if (~SCD && ~SCE) begin
            Q <= D;
        end else if (SCD && SCE) begin
            Q <= 1'b0;
        end
    end

endmodule

sva:
module flip_flop_sva (
    input logic Q,
    input logic Q_N,
    input logic CLK,
    input logic D,
    input logic SCD,
    input logic SCE,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB
);
    ///// Combinational relation /////
    // Q_N is always the bitwise complement of Q.
    check_qn_complement: assert property (
        @(posedge CLK) Q_N == ~Q
    );

    ///// Sequential update rules (sampled one cycle later using $past) /////
    // Full next-state function encoded from the RTL if/else chain.
    check_next_state_function: assert property (
        @(posedge CLK) Q == ($past(SCE) ? 1'b0 : ($past(SCD) ? 1'b1 : $past(D)))
    );

    // When SCE was HIGH, Q is forced LOW.
    check_clear_on_sce: assert property (
        @(posedge CLK) $past(SCE) |-> (Q == 1'b0)
    );

    // When SCE was LOW and SCD was HIGH, Q is set HIGH.
    check_set_on_scd_when_sce_low: assert property (
        @(posedge CLK) (!$past(SCE) && $past(SCD)) |-> (Q == 1'b1)
    );

    // When both SCE and SCD were LOW, Q loads D.
    check_load_d_when_both_low: assert property (
        @(posedge CLK) (!$past(SCE) && !$past(SCD)) |-> (Q == $past(D))
    );

    // When both SCE and SCD were HIGH, Q is forced LOW.
    check_clear_when_both_high: assert property (
        @(posedge CLK) ($past(SCE) && $past(SCD)) |-> (Q == 1'b0)
    );

    // Loading D causes Q to change if D differed from prior Q.
    check_load_d_changes_q: assert property (
        @(posedge CLK) (!$past(SCE) && !$past(SCD) && ($past(D) != $past(Q))) |-> (Q != $past(Q))
    );

    // Loading D holds Q if D equaled prior Q.
    check_load_d_holds_q: assert property (
        @(posedge CLK) (!$past(SCE) && !$past(SCD) && ($past(D) == $past(Q))) |-> (Q == $past(Q))
    );
endmodule

module d_ff_set_clear_sva (
    input logic D,
    input logic CLK,
    input logic SET_B,
    input logic SCD,
    input logic Q
);
    // Q next-cycle equals priority mux of inputs sampled this cycle.
    check_next_q_matches_priority_mux: assert property (
        @(posedge CLK) 1'b1 |=> (Q == ((SET_B == 1'b0) ? 1'b1 : ((SCD == 1'b0) ? 1'b0 : D)))
    );

    // Active-low SET_B forces Q to 1 on the next cycle.
    check_set_forces_one: assert property (
        @(posedge CLK) (SET_B == 1'b0) |=> (Q == 1'b1)
    );

    // Active-low SCD forces Q to 0 on the next cycle when SET_B is not active.
    check_clear_forces_zero: assert property (
        @(posedge CLK) (SET_B != 1'b0 && SCD == 1'b0) |=> (Q == 1'b0)
    );

    // With no set/clear active, Q captures D on the next cycle.
    check_data_captured: assert property (
        @(posedge CLK) (SET_B != 1'b0 && SCD != 1'b0) |=> (Q == D)
    );

    // When both SET_B and SCD are low, set has priority and Q becomes 1.
    check_set_overrides_clear: assert property (
        @(posedge CLK) (SET_B == 1'b0 && SCD == 1'b0) |=> (Q == 1'b1)
    );
endmodule

module calculator_sva (
    input logic CLK,
    input logic [7:0] A,
    input logic [7:0] B,
    input logic [1:0] op,
    input logic [7:0] result
);
    // When op=00, result must equal A+B (8-bit wrap)
    check_addition: assert property (
        @(posedge CLK) (op == 2'b00) |-> (result == (A + B))
    );

    // When op=01, result must equal A-B (8-bit wrap)
    check_subtraction: assert property (
        @(posedge CLK) (op == 2'b01) |-> (result == (A - B))
    );

    // When op=10, result must equal low 8 bits of A*B
    check_multiplication_low8: assert property (
        @(posedge CLK) (op == 2'b10) |-> (result == (A * B)[7:0])
    );

    // When op=11 and B!=0, result must equal A/B
    check_division_nonzero: assert property (
        @(posedge CLK) (op == 2'b11 && B != 8'd0) |-> (result == (A / B))
    );

    // If inputs are stable, result must remain stable
    check_stable_result_when_inputs_stable: assert property (
        @(posedge CLK) ($stable(A) && $stable(B) && $stable(op)) |-> $stable(result)
    );

    // If result changes, at least one of A, B, or op must have changed
    check_result_change_implies_input_change: assert property (
        @(posedge CLK) $changed(result) |-> ($changed(A) || $changed(B) || $changed(op))
    );
endmodule

