module dff (
    input CLK,
    input D,
    input SCD,
    input SCE,
    input SET_B,
    output reg Q
);

    always @(posedge CLK) begin
        if (SCD) begin
            if (SCE) begin
                Q <= D;
            end
            else begin
                Q <= 1'b0;
            end
        end
        else begin
            if (SET_B) begin
                Q <= 1'b1;
            end
            else begin
                Q <= Q;
            end
        end
    end

endmodule

