    assign SCD = R;
    assign SCE = 1;
    assign SET_B = S;

    dff base (
        .Q(Q),
        .CLK(CLK),
        .D(D),
        .SCD(SCD),
        .SCE(SCE),
        .SET_B(SET_B)
    );

endmodule

