    );

    // If only C1 toggles and B1 == A2, Y must remain stable.
    check_y_c1_toggle_nochange_when_b1_eq_a2: assert property (
        @(posedge clk) ($changed(C1) && $stable(A1) && $stable(A2) && $stable(B1) && $stable(B2) && (B1 == A2)) |-> $stable(Y)
