`ifndef _alu
`define _alu

module alu(
		input		[3:0]	ctl,
		input		[31:0]	a, b,
		output reg	[31:0]	out,
		output				zero);

	wire [31:0] sub_ab;
	wire [31:0] add_ab;
	wire 		oflow_add;
	wire 		oflow_sub;
	wire 		oflow;
	wire 		slt;

	assign zero = (0 == out);

	assign sub_ab = a - b;
	assign add_ab = a + b;

	assign oflow_add = (a[31] == b[31] && add_ab[31] != a[31]) ? 1 : 0;
	assign oflow_sub = (a[31] == b[31] && sub_ab[31] != a[31]) ? 1 : 0;

	assign oflow = (ctl == 4'b0010) ? oflow_add : oflow_sub;

	assign slt = oflow_sub ? ~(a[31]) : a[31];

	always @(*) begin
		case (ctl)
			4'b0010: out <= add_ab;				4'b0000: out <= a & b;				4'b1100: out <= ~(a | b);			4'b0001: out <= a | b;				4'b0111: out <= {{31{1'b0}}, slt};	4'b0110: out <= sub_ab;				4'b1101: out <= a ^ b;				default: out <= 0;
		endcase
	end

endmodule

`endif

sva:
module alu_sva (
    input logic CLK,
    input logic [3:0] ctl,
    input logic [31:0] a,
    input logic [31:0] b,
    input logic [31:0] out,
    input logic zero
);
    // Local re-computation of internal RTL wires for checking
    logic [31:0] add_ab, sub_ab;
    logic oflow_sub;
    logic slt;

    assign add_ab   = a + b;
    assign sub_ab   = a - b;
    assign oflow_sub = (a[31] == b[31]) && (sub_ab[31] != a[31]);
    assign slt      = oflow_sub ? ~a[31] : a[31];

    // zero output equals (out == 0)
    check_zero_definition: assert property (
        @(posedge CLK) zero == (out == 32'd0)
    );

    // ADD opcode: out equals a + b
    check_add_result: assert property (
        @(posedge CLK) (ctl == 4'b0010) |-> (out == add_ab)
    );

    // SUB opcode: out equals a - b
    check_sub_result: assert property (
        @(posedge CLK) (ctl == 4'b0110) |-> (out == sub_ab)
    );

    // AND opcode: out equals a & b
    check_and_result: assert property (
        @(posedge CLK) (ctl == 4'b0000) |-> (out == (a & b))
    );

    // OR opcode: out equals a | b
    check_or_result: assert property (
        @(posedge CLK) (ctl == 4'b0001) |-> (out == (a | b))
    );

    // NOR opcode: out equals ~(a | b)
    check_nor_result: assert property (
        @(posedge CLK) (ctl == 4'b1100) |-> (out == ~(a | b))
    );

    // XOR opcode: out equals a ^ b
    check_xor_result: assert property (
        @(posedge CLK) (ctl == 4'b1101) |-> (out == (a ^ b))
    );

    // SLT opcode: LSB equals slt
    check_slt_lsb: assert property (
        @(posedge CLK) (ctl == 4'b0111) |-> (out[0] == slt)
    );

    // SLT opcode: upper 31 bits are zero
    check_slt_upper_zero: assert property (
        @(posedge CLK) (ctl == 4'b0111) |-> (out[31:1] == 31'd0)
    );

    // Default opcode: out equals zero for unlisted ctl values
    check_default_zero: assert property (
        @(posedge CLK) !(ctl inside {4'b0010,4'b0000,4'b1100,4'b0001,4'b0111,4'b0110,4'b1101}) |-> (out == 32'd0)
    );
endmodule

rtl:
module barrel_shifter (
    input [3:0] data,
    input [1:0] shift_amount,
    output reg [3:0] shifted_data
);

always @(*) begin
    case (shift_amount)
        2'b00: shifted_data = data;
        2'b01: shifted_data = {data[2:0], data[3]};
        2'b10: shifted_data = {data[1:0], data[3:2]};
        2'b11: shifted_data = {data[0], data[3:1]};
    endcase
end

endmodule

module up_down_counter (
    input clk,
    input up_down,
    input load,
    input reset,
    output reg [3:0] Q
);

always @(posedge clk) begin
    if (reset) begin
        Q <= 4'b0000;
    end else if (load) begin
        Q <= Q;
    end else if (up_down) begin
        Q <= Q + 1;
    end else begin
        Q <= Q - 1;
    end
end

endmodule

module functional_module (
    input [3:0] shifted_data,
    input [3:0] counter_data,
    output [3:0] sum
);

assign sum = shifted_data + counter_data;

endmodule

module top_module (
    input clk,
    input up_down,
    input load,
    input reset,
    input [3:0] data,
    input [1:0] shift_amount,
    output [3:0] Q
);

wire [3:0] shifted_data;
wire [3:0] counter_data;

barrel_shifter barrel_shifter_inst (
    .data(data),
    .shift_amount(shift_amount),
    .shifted_data(shifted_data)
);

up_down_counter up_down_counter_inst (
    .clk(clk),
    .up_down(up_down),
    .load(load),
    .reset(reset),
    .Q(counter_data)
);

functional_module functional_module_inst (
    .shifted_data(shifted_data),
    .counter_data(counter_data),
    .sum(Q)
);

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic up_down,
    input logic load,
    input logic reset,
    input logic [3:0] data,
    input logic [1:0] shift_amount,
    input logic [3:0] Q
);

    // Compute expected barrel shift from inputs
    logic [3:0] shifted_expected;
    always_comb begin
        unique case (shift_amount)
            2'b00: shifted_expected = data;
            2'b01: shifted_expected = {data[2:0], data[3]};
            2'b10: shifted_expected = {data[1:0], data[3:2]};
            2'b11: shifted_expected = {data[0], data[3:1]};
        endcase
    end

    ///// Reset behavior ties sum to shifted data (counter resets to 0) /////
    // On reset with shift 00, Q equals data.
    reset_shift_00: assert property (
        @(posedge clk) reset && (shift_amount == 2'b00) |-> (Q == data)
    );
    // On reset with shift 01, Q equals {data[2:0], data[3]}.
    reset_shift_01: assert property (
        @(posedge clk) reset && (shift_amount == 2'b01) |-> (Q == {data[2:0], data[3]})
    );
    // On reset with shift 10, Q equals {data[1:0], data[3:2]}.
    reset_shift_10: assert property (
        @(posedge clk) reset && (shift_amount == 2'b10) |-> (Q == {data[1:0], data[3:2]})
    );
    // On reset with shift 11, Q equals {data[0], data[3:1]}.
    reset_shift_11: assert property (
        @(posedge clk) reset && (shift_amount == 2'b11) |-> (Q == {data[0], data[3:1]})
    );

    ///// Counter-driven sum behavior when inputs to barrel shifter are stable /////
    // With load high and stable shift inputs, Q holds its previous value.
    hold_when_load_and_inputs_stable: assert property (
        @(posedge clk) disable iff (reset)
            load && $stable({data, shift_amount}) |-> (Q == $past(Q))
    );
    // With count up, no load, and stable shift inputs, Q increments by 1 (mod 16).
    inc_when_up_inputs_stable: assert property (
        @(posedge clk) disable iff (reset)
            (!load && up_down && $stable({data, shift_amount})) |-> (Q == ($past(Q) + 4'd1))
    );
    // With count down, no load, and stable shift inputs, Q decrements by 1 (mod 16).
    dec_when_down_inputs_stable: assert property (
        @(posedge clk) disable iff (reset)
            (!load && !up_down && $stable({data, shift_amount})) |-> (Q == ($past(Q) - 4'd1))
    );

    ///// General step bound when barrel inputs are stable /////
    // With stable shift inputs, Q changes by at most 1 per cycle (or holds).
    bounded_step_with_inputs_stable: assert property (
        @(posedge clk) disable iff (reset)
            $stable({data, shift_amount}) |-> ((Q == $past(Q)) || (Q == ($past(Q) + 4'd1)) || (Q == ($past(Q) - 4'd1)))
    );

    ///// Explicit wrap-around checks /////
    // On increment from 0xF with no load and stable inputs, Q wraps to 0.
    wrap_increment_from_max: assert property (
        @(posedge clk) disable iff (reset)
            (!load && up_down && $stable({data, shift_amount}) && ($past(Q) == 4'hF)) |-> (Q == 4'h0)
    );
    // On decrement from 0x0 with no load and stable inputs, Q wraps to 0xF.
    wrap_decrement_from_min: assert property (
        @(posedge clk) disable iff (reset)
            (!load && !up_down && $stable({data, shift_amount}) && ($past(Q) == 4'h0)) |-> (Q == 4'hF)
    );

endmodule

rtl:
module twos_complement(A, B, Y);
input [3:0] A;
input B;
output reg [3:0] Y;

always @ (A, B)
begin
    if(B == 1'b1)
        Y <= 4'b0000;
    else
        Y <= ~A + 4'b0001;
end

endmodule

sva:
module twos_complement_sva (
    input logic CLK,
    input logic [3:0] A,
    input logic B,
    input logic [3:0] Y
);
    // When B is 1, Y is forced to zero.
    check_y_zero_when_b_high: assert property (
        @(posedge CLK) (B == 1'b1) |-> (Y == 4'b0000)
    );

    // When B is 0, Y equals two's complement of A.
    check_y_twos_complement_when_b_low: assert property (
        @(posedge CLK) (B == 1'b0) |-> (Y == (~A + 4'b0001))
    );

    // When B is 0, Y + A (mod 16) is zero.
    check_sum_zero_mod16_when_b_low: assert property (
        @(posedge CLK) (B == 1'b0) |-> ((Y + A)[3:0] == 4'h0)
    );

    // If A and B are stable across cycles, Y remains stable.
    check_y_stable_when_inputs_stable: assert property (
        @(posedge CLK) (($past(A) === A) && ($past(B) === B)) |-> (Y === $past(Y))
    );

    // Special case: when B is 0 and A is 0, Y is 0.
    check_y_zero_when_b_low_and_a_zero: assert property (
        @(posedge CLK) ((B == 1'b0) && (A == 4'h0)) |-> (Y == 4'h0)
    );

    // Special case: when B is 0 and A is 8, Y is 8 (self two's-complement point).
    check_y_equals_a_when_b_low_and_a_is_8: assert property (
        @(posedge CLK) ((B == 1'b0) && (A == 4'h8)) |-> (Y == 4'h8)
    );

    // Special case: when B is 0 and A is 15, Y is 1.
    check_y_is_1_when_b_low_and_a_is_15: assert property (
        @(posedge CLK) ((B == 1'b0) && (A == 4'hF)) |-> (Y == 4'h1)
    );

    // When B is 0 and Y is 0, A must be 0 (uniqueness of two's complement zero).
    check_a_zero_if_b_low_and_y_zero: assert property (
        @(posedge CLK) ((B == 1'b0) && (Y == 4'h0)) |-> (A == 4'h0)
    );
endmodule

rtl:
module full_adder(A, B, Cin, S, Cout);
    input A, B, Cin;
    output S, Cout;

    assign S = A ^ B ^ Cin;
    assign Cout = (A & B) | (Cin & (A ^ B));
endmodule

module adder4(A, B, S, Cout);
    input [3:0] A, B;
    output [3:0] S;
    output Cout;

    wire C1, C2, C3;
    full_adder FA1(A[0], B[0], 1'b0, S[0], C1);
    full_adder FA2(A[1], B[1], C1, S[1], C2);
    full_adder FA3(A[2], B[2], C2, S[2], C3);
    full_adder FA4(A[3], B[3], C3, S[3], Cout);
endmodule

sva:
module adder4_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] S,
    input logic Cout
);
    // Outputs represent the 5-bit sum of A and B (no carry-in).
    check_sum_matches_add: assert property (
        @(posedge clk) {Cout, S} == (A + B)
    );

    // LSB sum is XOR of inputs (Cin=0).
    check_s0_is_xor: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0])
    );

    // Bit1 sum equals XOR with carry from bit0 (A0&B0).
    check_s1_is_xor_with_carry: assert property (
        @(posedge clk) S[1] == ((A[1] ^ B[1]) ^ (A[0] & B[0]))
    );

    // Bit2 sum equals XOR with propagated carry C2.
    check_s2_is_xor_with_carry: assert property (
        @(posedge clk) S[2] == ((A[2] ^ B[2]) ^ ( (A[1] & B[1]) | ((A[1] ^ B[1]) & (A[0] & B[0])) ))
    );

    // Bit3 sum equals XOR with propagated carry C3.
    check_s3_is_xor_with_carry: assert property (
        @(posedge clk) S[3] == ((A[3] ^ B[3]) ^ ( (A[2] & B[2]) | ((A[2] ^ B[2]) & ( (A[1] & B[1]) | ((A[1] ^ B[1]) & (A[0] & B[0])) )) ))
    );

    // Cout equals the final carry-out from bit3.
    check_cout_is_final_carry: assert property (
        @(posedge clk) Cout == ( (A[3] & B[3]) | ((A[3] ^ B[3]) & ( (A[2] & B[2]) | ((A[2] ^ B[2]) & ( (A[1] & B[1]) | ((A[1] ^ B[1]) & (A[0] & B[0])) )) )) )
    );

    // Adding zero to zero yields zero sum and no carry.
    check_zero_plus_zero: assert property (
        @(posedge clk) ((A == 4'd0) && (B == 4'd0)) |-> ((S == 4'd0) && (Cout == 1'b0))
    );

    // Adding zero (B) passes A to S with no carry.
    check_add_zero_b: assert property (
        @(posedge clk) (B == 4'd0) |-> ((S == A) && (Cout == 1'b0))
    );

    // Adding zero (A) passes B to S with no carry.
    check_add_zero_a: assert property (
        @(posedge clk) (A == 4'd0) |-> ((S == B) && (Cout == 1'b0))
    );

    // A plus bitwise-not A yields 0xF with no carry.
    check_a_plus_not_a: assert property (
        @(posedge clk) (B == ~A) |-> ((S == 4'hF) && (Cout == 1'b0))
    );
endmodule

rtl:
module LOA #(parameter LPL=10, parameter W=16)(
    input wire [W - 1:0] in1,
    input wire [W - 1:0] in2,
    output wire [W:0] res
    );

wire [LPL-1:0] in1LowerPart;
wire [LPL-1:0] in2LowerPart;
wire [W-LPL-1:0] in1UpperPart;
wire [W-LPL-1:0] in2UpperPart;
wire [W-LPL:0] midRes;
wire [LPL-1:0] ORLowerPart;
wire ANDN;

assign ORLowerPart = ((in1[LPL-1:0]) |( in2[LPL-1:0]));
and and_1(ANDN,in1[LPL-1],in2[LPL-1]);
assign  midRes= in1[W-1:LPL] + in2[W-1:LPL] + ANDN;
assign res = {midRes, ORLowerPart};

endmodule

sva:
module LOA_sva #(parameter int LPL=10, parameter int W=16) (
    input logic CLK,
    input logic [W - 1:0] in1,
    input logic [W - 1:0] in2,
    input logic [W:0] res
);
    // RTL has no clock/reset; assertions are sampled on CLK only.
    default clocking cb @(posedge CLK); endclocking

    // Parameters must yield legal slice widths (matches RTL structure).
    check_param_legal: assert property (
        (LPL >= 1) && (W > LPL)
    );

    // Lower LPL result bits are bitwise OR of inputs.
    check_lower_or: assert property (
        res[LPL-1:0] == (in1[LPL-1:0] | in2[LPL-1:0])
    );

    // Upper part equals upper addends plus carry-in from bit LPL-1 AND.
    check_upper_sum_with_cin: assert property (
        res[W:LPL] == ({1'b0, in1[W-1:LPL]} + {1'b0, in2[W-1:LPL]} + (in1[LPL-1] & in2[LPL-1]))
    );

    // Full output matches the RTL concatenation of upper sum and lower OR.
    check_full_concat: assert property (
        res == {({1'b0, in1[W-1:LPL]} + {1'b0, in2[W-1:LPL]} + (in1[LPL-1] & in2[LPL-1])), (in1[LPL-1:0] | in2[LPL-1:0])}
    );

    // If lower OR is zero, both lower input parts must be zero.
    check_lower_zero_implies_inputs_zero: assert property (
        (res[LPL-1:0] == '0) |-> ((in1[LPL-1:0] == '0) && (in2[LPL-1:0] == '0))
    );

    // When not both LPL-1 bits are 1, carry-in to upper add is zero.
    check_no_cin_when_not_both_one: assert property (
        !(in1[LPL-1] & in2[LPL-1]) |-> (res[W:LPL] == ({1'b0, in1[W-1:LPL]} + {1'b0, in2[W-1:LPL]}))
    );

    // When both LPL-1 bits are 1, carry-in to upper add is one.
    check_cin_when_both_one: assert property (
        (in1[LPL-1] & in2[LPL-1]) |-> (res[W:LPL] == ({1'b0, in1[W-1:LPL]} + {1'b0, in2[W-1:LPL]} + 1'b1))
    );

    // MSB of res equals carry-out of the upper addition with carry-in.
    check_top_carry_matches_add: assert property (
        res[W] == (({1'b0, in1[W-1:LPL]} + {1'b0, in2[W-1:LPL]} + (in1[LPL-1] & in2[LPL-1]))[W-LPL])
    );

    // If both inputs are zero, result must be zero.
    check_zero_inputs_zero_output: assert property (
        ((in1 == '0) && (in2 == '0)) |-> (res == '0)
    );

    // Bit LPL-1 of result equals OR of input bits at LPL-1.
    check_boundary_bit_or: assert property (
        res[LPL-1] == (in1[LPL-1] | in2[LPL-1])
    );
endmodule

module inverted_5input_OR_gate_sva (
    input  logic CLK,
    input  logic p1,
    input  logic p2,
    input  logic p3,
    input  logic p4,
    input  logic p5,
    input  logic y
);
    // Output is 0 when any input is 1.
    check_any_high_forces_y0: assert property (
        @(posedge CLK) disable iff (1'b0)
        ((p1 === 1'b1) || (p2 === 1'b1) || (p3 === 1'b1) || (p4 === 1'b1) || (p5 === 1'b1)) |-> (y === 1'b0)
    );

    // Output is 1 when all inputs are 0.
    check_all_low_forces_y1: assert property (
        @(posedge CLK) disable iff (1'b0)
        ((p1 === 1'b0) && (p2 === 1'b0) && (p3 === 1'b0) && (p4 === 1'b0) && (p5 === 1'b0)) |-> (y === 1'b1)
    );

    // If y is 0, at least one input must be 1.
    check_y0_implies_some_high: assert property (
        @(posedge CLK) disable iff (1'b0)
        (y === 1'b0) |-> ((p1 === 1'b1) || (p2 === 1'b1) || (p3 === 1'b1) || (p4 === 1'b1) || (p5 === 1'b1))
    );

    // If y is 1, no input is 1.
    check_y1_implies_no_high: assert property (
        @(posedge CLK) disable iff (1'b0)
        (y === 1'b1) |-> ((p1 !== 1'b1) && (p2 !== 1'b1) && (p3 !== 1'b1) && (p4 !== 1'b1) && (p5 !== 1'b1))
    );

    // If no input is 1 (including X/Z), output is 1.
    check_no_known_highs_forces_y1: assert property (
        @(posedge CLK) disable iff (1'b0)
        ((p1 !== 1'b1) && (p2 !== 1'b1) && (p3 !== 1'b1) && (p4 !== 1'b1) && (p5 !== 1'b1)) |-> (y === 1'b1)
    );

    // y is always a known 0 or 1.
    check_y_is_binary: assert property (
        @(posedge CLK) disable iff (1'b0)
        (y === 1'b0) || (y === 1'b1)
    );

    // With stable inputs, y must be stable.
    check_stable_inputs_hold_y: assert property (
        @(posedge CLK) disable iff (1'b0)
        $stable({p1,p2,p3,p4,p5}) |-> $stable(y)
    );

    // A falling y requires at least one input to be 1.
    check_y_fall_requires_high: assert property (
        @(posedge CLK) disable iff (1'b0)
        $fell(y) |-> ((p1 === 1'b1) || (p2 === 1'b1) || (p3 === 1'b1) || (p4 === 1'b1) || (p5 === 1'b1))
    );

    // A rising y requires no input to be 1.
    check_y_rise_requires_no_high: assert property (
        @(posedge CLK) disable iff (1'b0)
        $rose(y) |-> ((p1 !== 1'b1) && (p2 !== 1'b1) && (p3 !== 1'b1) && (p4 !== 1'b1) && (p5 !== 1'b1))
    );

    // With all inputs known 0/1, y equals logical NOR of inputs.
    check_boolean_equivalence_when_inputs_known: assert property (
        @(posedge CLK) disable iff (1'b0)
        ((p1 === 1'b0 || p1 === 1'b1) &&
         (p2 === 1'b0 || p2 === 1'b1) &&
         (p3 === 1'b0 || p3 === 1'b1) &&
         (p4 === 1'b0 || p4 === 1'b1) &&
         (p5 === 1'b0 || p5 === 1'b1)) |-> (y === !(p1 || p2 || p3 || p4 || p5))
    );
endmodule

rtl:
module shiftReg #(
    parameter WIDTH = 8,
    parameter ADDR_WIDTH = 2
) (
    input clk,
    input [WIDTH-1:0] data,
    input ce,
    input [ADDR_WIDTH-1:0] a,
    output reg [WIDTH-1:0] q
);


parameter DEPTH = 4;

reg [WIDTH-1:0] SRL_SIG [0:DEPTH-1];
integer i;

always @ (posedge clk)
begin
    if (ce)
    begin
        for (i=0; i<DEPTH-1; i=i+1)
            SRL_SIG[i+1] <= SRL_SIG[i];
        SRL_SIG[0] <= data;
    end
end

always @*
begin
    q = SRL_SIG[a];
end

endmodule

sva:
module shiftReg_sva #(
    parameter int WIDTH = 8,
    parameter int ADDR_WIDTH = 2,
    parameter int DEPTH = 4
) (
    input logic clk,
    input logic [WIDTH-1:0] data,
    input logic ce,
    input logic [ADDR_WIDTH-1:0] a,
    input logic [WIDTH-1:0] q
);

    // Constrain address to valid range of the SRL depth.
    assume_valid_addr_range: assume property (
        @(posedge clk) a < DEPTH
    );

    // If CE was LOW last cycle and address is unchanged, q must hold its value.
    check_q_hold_when_prev_ce_low_and_a_stable: assert property (
        @(posedge clk) (!$past(ce) && (a == $past(a))) |-> (q == $past(q))
    );

    // When selecting stage 0, after a CE pulse last cycle q equals last cycle's data.
    check_stage0_data_latency: assert property (
        @(posedge clk) ($past(ce) && (a == '0)) |-> (q == $past(data))
    );

    // When selecting stage 1, after two consecutive CE pulses q equals data from 2 cycles ago.
    check_stage1_data_latency: assert property (
        @(posedge clk) ($past(ce,2) && $past(ce,1) && (a == 'd1)) |-> (q == $past(data,2))
    );

    // When selecting stage 2, after three consecutive CE pulses q equals data from 3 cycles ago.
    check_stage2_data_latency: assert property (
        @(posedge clk) ($past(ce,3) && $past(ce,2) && $past(ce,1) && (a == 'd2)) |-> (q == $past(data,3))
    );

    // When selecting stage 3, after four consecutive CE pulses q equals data from 4 cycles ago.
    check_stage3_data_latency: assert property (
        @(posedge clk) ($past(ce,4) && $past(ce,3) && $past(ce,2) && $past(ce,1) && (a == 'd3)) |-> (q == $past(data,4))
    );

    // If address increments by 1 and CE was HIGH last cycle, q must equal its previous value.
    check_q_preserved_on_addr_inc_with_prev_ce_high: assert property (
        @(posedge clk) ($past(ce) && ($past(a) < (DEPTH-1)) && (a == ($past(a) + 1))) |-> (q == $past(q))
    );

    // If address changes from 1 to 0 and CE was HIGH last cycle, q equals last cycle's data.
    check_addr_dec_to_zero_returns_prev_data: assert property (
        @(posedge clk) ($past(ce) && ($past(a) == 'd1) && (a == 'd0)) |-> (q == $past(data))
    );

endmodule

module mux_2to1_sva (
    input logic clk,     // sampling clock for SVA (DUT has no clock/reset)
    input logic in0,
    input logic in1,
    input logic sel,
    input logic out
);
    // When sel=1, out equals in1.
    check_sel1_routes_in1: assert property (
        @(posedge clk) sel |-> (out == in1)
    );

    // When sel=0, out equals in0.
    check_sel0_routes_in0: assert property (
        @(posedge clk) !sel |-> (out == in0)
    );

    // If inputs are equal, out equals that value regardless of sel.
    check_equal_inputs_bypass: assert property (
        @(posedge clk) (in0 == in1) |-> (out == in0)
    );

    // If inputs differ and out equals in0, sel must be 0.
    check_out_eq_in0_implies_sel0: assert property (
        @(posedge clk) (in0 != in1) && (out == in0) |-> (!sel)
    );

    // If inputs differ and out equals in1, sel must be 1.
    check_out_eq_in1_implies_sel1: assert property (
        @(posedge clk) (in0 != in1) && (out == in1) |-> (sel)
    );

    // With sel and both inputs stable, out remains stable.
    check_stable_out_when_all_stable: assert property (
        @(posedge clk) $stable(sel) && $stable(in0) && $stable(in1) |-> $stable(out)
