module wait_generator(
    input clk, nreset, WAIT,
    output reg wait_random
);

    reg [8:0] wait_counter;

    always @(posedge clk or negedge nreset) begin
        if (!nreset) begin
            wait_counter <= 9'b0;
        end else begin
            wait_counter <= wait_counter + 1'b1;
        end
    end

    always @* begin
        if (WAIT) begin
            if (wait_counter[5:0] != 6'b0) begin
                wait_random = 1'b1;
            end else begin
                wait_random = 1'b0;
            end
        end else begin
            wait_random = 1'b0;
        end
    end

endmodule

sva:
module wait_generator_sva (
    input logic clk,
    input logic nreset,
    input logic WAIT,
    input logic wait_random,
    input logic [8:0] wait_counter
);
    // Clock: clk; Reset: nreset active-low
    // Mixed: sequential 9-bit counter + combinational wait_random
    // Behavior: wait_random = WAIT && (wait_counter[5:0] != 0)

    // Counter goes to 0 when reset falls.
    reset_fall_clears_counter: assert property (
        @(posedge clk) $fell(nreset) |-> (wait_counter == 9'b0)
    );

    // Counter becomes 1 on first clock after reset deassertion.
    counter_one_after_reset_release: assert property (
        @(posedge clk) $rose(nreset) |-> (wait_counter == 9'd1)
    );

    // Counter increments by 1 each cycle when out of reset.
    counter_increments_when_active: assert property (
        @(posedge clk) disable iff (!nreset) $past(nreset) |-> (wait_counter == $past(wait_counter) + 9'd1)
    );

    // Counter wraps from 9'h1FF to 0 when active.
    counter_wraps_after_max: assert property (
        @(posedge clk) disable iff (!nreset) $past(nreset) && ($past(wait_counter) == 9'h1FF) |-> (wait_counter == 9'h000)
    );

    // wait_random equals WAIT && (wait_counter[5:0] != 0) when active.
    wait_random_comb_function: assert property (
        @(posedge clk) disable iff (!nreset) wait_random == (WAIT && (wait_counter[5:0] != 6'b0))
    );

    // If WAIT is 0, wait_random must be 0 when active.
    wait_random_low_when_WAIT_low: assert property (
        @(posedge clk) disable iff (!nreset) (WAIT == 1'b0) |-> (wait_random == 1'b0)
    );

    // wait_random can only rise when WAIT is 1 and counter[5:0] is nonzero.
    wait_random_rise_condition: assert property (
        @(posedge clk) disable iff (!nreset) $rose(wait_random) |-> (WAIT == 1'b1) && (wait_counter[5:0] != 6'b0)
    );

    // wait_random can only fall when WAIT is 0 or counter[5:0] is zero.
    wait_random_fall_condition: assert property (
        @(posedge clk) disable iff (!nreset) $fell(wait_random) |-> ((WAIT == 1'b0) || (wait_counter[5:0] == 6'b0))
    );

endmodule

module three_to_one_sva (
    input logic A1,
    input logic A2,
    input logic B1_N,
    input logic Y,
    input logic VPWR,
    input logic VGND
);
    // Y matches the boolean function encoded in the RTL.
    check_function_equivalence: assert property (
        @(posedge VPWR) Y == ((A1 && A2) || ((!A1) && (!A2) && (!B1_N)))
    );

    // When both A1 and A2 are HIGH, Y is HIGH.
    check_both_high_sets_y: assert property (
        @(posedge VPWR) (A1 && A2) |-> (Y == 1'b1)
    );

    // When exactly one of A1/A2 is HIGH, Y is LOW.
    check_one_hot_clears_y: assert property (
        @(posedge VPWR) (A1 ^ A2) |-> (Y == 1'b0)
    );

    // When both A1 and A2 are LOW and B1_N is LOW, Y is HIGH.
    check_both_low_b1n_low_sets_y: assert property (
        @(posedge VPWR) (!A1 && !A2 && !B1_N) |-> (Y == 1'b1)
    );

    // When both A1 and A2 are LOW and B1_N is HIGH, Y is LOW.
    check_both_low_b1n_high_clears_y: assert property (
        @(posedge VPWR) (!A1 && !A2 && B1_N) |-> (Y == 1'b0)
    );

    // With B1_N HIGH, Y equals A1 AND A2.
    check_b1n_high_reduces_to_and: assert property (
        @(posedge VPWR) (B1_N == 1'b1) |-> (Y == (A1 && A2))
    );

    // With B1_N LOW, Y equals XNOR of A1 and A2.
    check_b1n_low_reduces_to_xnor: assert property (
        @(posedge VPWR) (B1_N == 1'b0) |-> (Y == ~(A1 ^ A2))
    );

    // If A1, A2, and B1_N are stable, Y remains stable.
    check_output_stable_when_inputs_stable: assert property (
        @(posedge VPWR) ($stable(A1) && $stable(A2) && $stable(B1_N)) |-> $stable(Y)
    );

    // Y can be HIGH only for the allowed input combinations.
    check_y_high_implies_valid_inputs: assert property (
        @(posedge VPWR) (Y == 1'b1) |-> ((A1 && A2) || (!A1 && !A2 && !B1_N))
    );
endmodule

rtl:
module binary_counter(
    input clk,
    input rst,
    output reg [1:0] count,
    output reg overflow
);

    always @(posedge clk or negedge rst) begin
        if(rst == 0) begin
            count <= 2'b00;
            overflow <= 0;
        end
        else begin
            if(count == 2'b11) begin
                count <= 2'b00;
                overflow <= 1;
            end
            else begin
                count <= count + 1;
                overflow <= 0;
            end
        end
    end

endmodule

sva:
module binary_counter_sva (
    input logic clk,
    input logic rst,
    input logic [1:0] count,
    input logic overflow
);
    ///// Reset behavior /////
    // While reset is asserted low, count and overflow are held at 0.
    reset_outputs_zero: assert property (
        @(posedge clk) (rst == 1'b0) |-> (count == 2'b00) && (overflow == 1'b0)
    );

    ///// State transitions /////
    // From 00, next is 01 with no overflow.
    trans_00_to_01: assert property (
        @(posedge clk) disable iff (!rst) (count == 2'b00) |=> ((count == 2'b01) && (overflow == 1'b0))
    );
    // From 01, next is 10 with no overflow.
    trans_01_to_10: assert property (
        @(posedge clk) disable iff (!rst) (count == 2'b01) |=> ((count == 2'b10) && (overflow == 1'b0))
    );
    // From 10, next is 11 with no overflow.
    trans_10_to_11: assert property (
        @(posedge clk) disable iff (!rst) (count == 2'b10) |=> ((count == 2'b11) && (overflow == 1'b0))
    );
    // From 11, next is 00 and overflow asserted.
    trans_11_to_00_overflow: assert property (
        @(posedge clk) disable iff (!rst) (count == 2'b11) |=> ((count == 2'b00) && (overflow == 1'b1))
    );

    ///// Overflow semantics /////
    // Overflow high implies current count is 00.
    overflow_implies_zero: assert property (
        @(posedge clk) disable iff (!rst) overflow |-> (count == 2'b00)
    );
    // When count is nonzero, overflow must be 0.
    no_overflow_when_count_nonzero: assert property (
        @(posedge clk) disable iff (!rst) (count != 2'b00) |-> (overflow == 1'b0)
    );
    // Overflow is a single-cycle pulse.
    overflow_single_cycle: assert property (
        @(posedge clk) disable iff (!rst) overflow |=> !overflow
    );

    ///// Reset release /////
    // On reset deassertion, hold 00/0 then increment to 01/0.
    post_reset_first_step: assert property (
        @(posedge clk) $rose(rst) |-> ((count == 2'b00) && (overflow == 1'b0)) ##1 ((count == 2'b01) && (overflow == 1'b0))
    );

    ///// Multi-step progression /////
    // After wrap (11->00/overflow), next step is 01 with overflow low.
    wrap_two_step_progress: assert property (
        @(posedge clk) disable iff (!rst) (count == 2'b11) |=> ((count == 2'b00) && (overflow == 1'b1)) ##1 ((count == 2'b01) && (overflow == 1'b0))
    );
endmodule

