module top_module(
    input wire [15:0] in,
    output wire [7:0] out_hi,
    output wire [7:0] out_lo,
    input wire clk
); // Added clk as an input to the module

wire [7:0] stage1_out_hi;
wire [7:0] stage1_out_lo;

