assign out_lo = out_lo_reg;

endmodule

sva:
module top_module_sva (
    input logic [15:0] in,
    input logic [7:0]  out_hi,
    input logic [7:0]  out_lo,
    input logic        clk
);
    // DUT: top_module | Clock: clk (posedge) | Reset: none | Logic: mixed (comb split + seq regs)

    // Outputs are the 1-cycle delayed split of input (full 16-bit check).
    check_pipeline_concat: assert property (
        @(posedge clk) 1'b1 |=> {out_hi, out_lo} == $past(in)
    );

    // High byte output equals previous cycle's in[15:8].
    check_pipeline_hi: assert property (
        @(posedge clk) 1'b1 |=> out_hi == $past(in[15:8])
    );

    // Low byte output equals previous cycle's in[7:0].
    check_pipeline_lo: assert property (
        @(posedge clk) 1'b1 |=> out_lo == $past(in[7:0])
    );

endmodule

rtl:
module bitwise_xor (
    input [31:0] A,
    input [31:0] B,
    input TE,
    output [31:0] Z
);

    assign Z = TE ? (A ^ B) : 0;

endmodule

sva:
module bitwise_xor_sva (
    input logic [31:0] A,
    input logic [31:0] B,
    input logic TE,
    input logic [31:0] Z
);
    // Z implements TE ? (A ^ B) : 0.
    check_functional: assert property (
        @(posedge TE or posedge A[0] or posedge B[0]) Z == (TE ? (A ^ B) : 32'h0)
    );

    // When TE is 0, Z is all zeros.
    check_zero_when_te0: assert property (
        @(posedge TE or posedge A[0] or posedge B[0]) (TE == 1'b0) |-> (Z == 32'h0)
    );

    // When TE is 1, Z equals A ^ B.
    check_xor_when_te1: assert property (
        @(posedge TE or posedge A[0] or posedge B[0]) (TE == 1'b1) |-> (Z == (A ^ B))
    );

    // If Z is non-zero, TE must be 1.
    check_nonzero_implies_te1: assert property (
        @(posedge TE or posedge A[0] or posedge B[0]) (Z != 32'h0) |-> (TE == 1'b1)
    );

    // With TE=1 and A==0, Z passes through B.
    check_passthrough_b_when_te1_a_zero: assert property (
        @(posedge TE or posedge A[0] or posedge B[0]) (TE == 1'b1 && (A == 32'h0)) |-> (Z == B)
    );

    // With TE=1 and B==0, Z passes through A.
    check_passthrough_a_when_te1_b_zero: assert property (
        @(posedge TE or posedge A[0] or posedge B[0]) (TE == 1'b1 && (B == 32'h0)) |-> (Z == A)
    );

    // With TE=1 and A==B, Z is zero.
    check_zero_when_te1_a_eq_b: assert property (
        @(posedge TE or posedge A[0] or posedge B[0]) (TE == 1'b1 && (A == B)) |-> (Z == 32'h0)
    );

    // With TE=1 and B==~A, Z is all ones.
    check_allones_when_te1_b_eq_not_a: assert property (
        @(posedge TE or posedge A[0] or posedge B[0]) (TE == 1'b1 && (B == ~A)) |-> (Z == 32'hFFFF_FFFF)
    );
endmodule

rtl:
module top_module (
    X   ,
    A1  ,
    A2  ,
    A3  ,
    B1  ,
    C1 
);

    output X   ;
    input  A1  ;
    input  A2  ;
    input  A3  ;
    input  B1  ;
    input  C1  ;


    assign X = (A1 | A2 |A3) & B1 & C1;



endmodule

sva:
module top_module_sva (
    input logic X,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic B1,
    input logic C1
);
    // X equals (A1|A2|A3)&B1&C1 at any input edge.
    check_functional_equivalence: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge A3 or negedge A3 or posedge B1 or negedge B1 or posedge C1 or negedge C1)
        X == ((A1 | A2 | A3) & B1 & C1)
    );

    // If B1 is LOW, X must be LOW.
    check_zero_when_B1_low: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge A3 or negedge A3 or posedge B1 or negedge B1 or posedge C1 or negedge C1)
        (B1 == 1'b0) |-> (X == 1'b0)
    );

    // If C1 is LOW, X must be LOW.
    check_zero_when_C1_low: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge A3 or negedge A3 or posedge B1 or negedge B1 or posedge C1 or negedge C1)
        (C1 == 1'b0) |-> (X == 1'b0)
    );

    // If all A inputs are LOW, X must be LOW.
    check_zero_when_all_A_low: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge A3 or negedge A3 or posedge B1 or negedge B1 or posedge C1 or negedge C1)
        ((A1 == 1'b0) && (A2 == 1'b0) && (A3 == 1'b0)) |-> (X == 1'b0)
    );

    // With B1&C1 HIGH and A1 HIGH, X must be HIGH.
    check_one_when_A1_and_gates_high: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge A3 or negedge A3 or posedge B1 or negedge B1 or posedge C1 or negedge C1)
        ((B1 == 1'b1) && (C1 == 1'b1) && (A1 == 1'b1)) |-> (X == 1'b1)
    );

    // With B1&C1 HIGH and A2 HIGH, X must be HIGH.
    check_one_when_A2_and_gates_high: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge A3 or negedge A3 or posedge B1 or negedge B1 or posedge C1 or negedge C1)
        ((B1 == 1'b1) && (C1 == 1'b1) && (A2 == 1'b1)) |-> (X == 1'b1)
    );

    // With B1&C1 HIGH and A3 HIGH, X must be HIGH.
    check_one_when_A3_and_gates_high: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge A3 or negedge A3 or posedge B1 or negedge B1 or posedge C1 or negedge C1)
        ((B1 == 1'b1) && (C1 == 1'b1) && (A3 == 1'b1)) |-> (X == 1'b1)
    );

    // When B1&C1 are HIGH, X equals A1|A2|A3.
    check_when_gates_high_output_matches_or: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge A3 or negedge A3 or posedge B1 or negedge B1 or posedge C1 or negedge C1)
        ((B1 == 1'b1) && (C1 == 1'b1)) |-> (X == (A1 | A2 | A3))
    );

    // X HIGH implies B1&C1 HIGH and at least one A HIGH.
    check_x_high_implies_inputs: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge A3 or negedge A3 or posedge B1 or negedge B1 or posedge C1 or negedge C1)
        (X == 1'b1) |-> ((B1 == 1'b1) && (C1 == 1'b1) && ((A1 | A2 | A3) == 1'b1))
    );

    // With B1&C1 HIGH and all A LOW, X must be LOW.
    check_zero_when_gates_high_and_as_low: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge A3 or negedge A3 or posedge B1 or negedge B1 or posedge C1 or negedge C1)
        ((B1 == 1'b1) && (C1 == 1'b1) && ((A1 | A2 | A3) == 1'b0)) |-> (X == 1'b0)
    );
endmodule

rtl:
module shift_register ( input clk, input d, output q );

reg [2:0] reg_array;
assign q = reg_array[0];

always @(posedge clk) begin
    reg_array <= {reg_array[1:0], d};
end

endmodule

sva:
module shift_register_sva (
    input logic clk,
    input logic d,
    input logic q,
    input logic [2:0] reg_array
);

    // q directly mirrors reg_array[0] via continuous assignment.
    check_q_mirrors_reg0: assert property (
        @(posedge clk) q == reg_array[0]
    );

    // On each clock, reg_array shifts left and captures d on bit[2].
    check_shift_update_vector: assert property (
        @(posedge clk) reg_array == { $past(reg_array[1:0]), $past(d) }
    );

    // Bit[0] updates from previous bit[1].
    check_bit0_from_bit1: assert property (
        @(posedge clk) reg_array[0] == $past(reg_array[1])
    );

    // Bit[1] updates from previous bit[2].
    check_bit1_from_bit2: assert property (
        @(posedge clk) reg_array[1] == $past(reg_array[2])
    );

    // Bit[2] captures previous d.
    check_bit2_from_d: assert property (
        @(posedge clk) reg_array[2] == $past(d)
    );

    // q equals d delayed by two cycles (guarded against insufficient history).
    check_q_two_cycle_delay_of_d: assert property (
        @(posedge clk) !$isunknown($past(d,2)) |-> (q == $past(d,2))
    );

endmodule

rtl:
module max_value(
    input [7:0] A,
    input [7:0] B,
    output reg [7:0] MAX
);

    always @(*) begin
        MAX = (A >= B) ? A : B;
    end

endmodule

sva:
module max_value_sva (
    input logic [7:0] A,
    input logic [7:0] B,
    input logic [7:0] MAX
);
    // MAX implements the ternary compare result exactly.
    check_function_equivalence: assert property (
        @($global_clock) (MAX == ((A >= B) ? A : B))
    );

    // When A >= B, MAX equals A.
    check_choose_A_when_A_ge_B: assert property (
        @($global_clock) (A >= B) |-> (MAX == A)
    );

    // When A < B, MAX equals B.
    check_choose_B_when_A_lt_B: assert property (
        @($global_clock) (A < B) |-> (MAX == B)
    );

    // If MAX equals A, then A >= B.
    check_if_max_is_A_then_A_ge_B: assert property (
        @($global_clock) (MAX == A) |-> (A >= B)
    );

    // If MAX equals B, then A < B.
    check_if_max_is_B_then_A_lt_B: assert property (
        @($global_clock) (MAX == B) |-> (A < B)
    );

    // MAX is always either A or B.
    check_max_is_either_input: assert property (
        @($global_clock) (MAX == A) || (MAX == B)
    );

    // MAX is greater than or equal to both inputs (unsigned).
    check_max_ge_inputs: assert property (
        @($global_clock) (MAX >= A) && (MAX >= B)
    );

    // Equal inputs drive MAX to that value; tie breaks to A.
    check_tie_breaks_to_A: assert property (
        @($global_clock) (A == B) |-> (MAX == A)
    );

    // If A and B are stable, MAX remains stable.
    check_stable_when_inputs_stable: assert property (
        @($global_clock) ($stable(A) && $stable(B)) |-> $stable(MAX)
    );
endmodule

rtl:
module g_18 ( g, p, g_prec, g_out );
  input g, p;
  input [1:0] g_prec;
  output g_out;
  wire n2;

  // AOI21 gate
  assign n2 = ~(p & g_prec[1] & ~g);

  // Inverter gate
  assign g_out = ~n2;
endmodule

sva:
module g_18_sva (
    input logic CLK,
    input logic g,
    input logic p,
    input logic [1:0] g_prec,
    input logic g_out
);
    // g_out equals p & g_prec[1] & ~g.
    check_functional_equivalence: assert property (
        @(posedge CLK) g_out == (p & g_prec[1] & ~g)
    );

    // If g_out is 1 then p must be 1.
    check_g_out_implies_p: assert property (
        @(posedge CLK) g_out |-> p
    );

    // If g_out is 1 then g_prec[1] must be 1.
    check_g_out_implies_gprec1: assert property (
        @(posedge CLK) g_out |-> g_prec[1]
    );

    // If g_out is 1 then g must be 0.
    check_g_out_implies_not_g: assert property (
        @(posedge CLK) g_out |-> !g
    );

    // When p=1, g_prec[1]=1, and g=0, g_out must be 1.
    check_one_if_all_true: assert property (
        @(posedge CLK) (p && g_prec[1] && !g) |-> (g_out == 1'b1)
    );

    // g_out is independent of g_prec[0] when other inputs are stable.
    check_independence_gprec0: assert property (
        @(posedge CLK) ($changed(g_prec[0]) && $stable({p, g_prec[1], g})) |-> $stable(g_out)
    );

    // If p, g_prec[1], and g are stable, g_out is stable.
    check_stable_when_inputs_stable: assert property (
        @(posedge CLK) $stable({p, g_prec[1], g}) |-> $stable(g_out)
    );

    // On p rising with g_prec[1]=1 and g=0, g_out is 1.
    check_g_out_on_p_rise: assert property (
        @(posedge CLK) ($rose(p) && g_prec[1] && !g) |-> (g_out == 1'b1)
    );

    // On g_prec[1] rising with p=1 and g=0, g_out is 1.
    check_g_out_on_gprec1_rise: assert property (
        @(posedge CLK) ($rose(g_prec[1]) && p && !g) |-> (g_out == 1'b1)
    );

    // On g rising with p=1 and g_prec[1]=1, g_out is 0.
    check_g_out_on_g_rise: assert property (
        @(posedge CLK) ($rose(g) && p && g_prec[1]) |-> (g_out == 1'b0)
    );

    // On g falling with p=1 and g_prec[1]=1, g_out is 1.
    check_g_out_on_g_fall: assert property (
        @(posedge CLK) ($fell(g) && p && g_prec[1]) |-> (g_out == 1'b1)
    );

    // On g_prec[1] falling, g_out is 0.
    check_g_out_on_gprec1_fall: assert property (
        @(posedge CLK) $fell(g_prec[1]) |-> (g_out == 1'b0)
    );
endmodule

rtl:
module pg_45 ( g, p, g_prec, p_prec, p_out, g_out_BAR );
  input g, p, g_prec, p_prec;
  output p_out, g_out_BAR;

  // AOI21 gate
  wire g_out_BAR_wire;
  assign g_out_BAR_wire = ~(g_prec & p | g);
  assign g_out_BAR = g_out_BAR_wire;

  // AND2 gate
  wire p_out_wire;
  assign p_out_wire = p_prec & p;
  assign p_out = p_out_wire;

endmodule

sva:
module pg_45_sva (
    input  logic CLK,
    input  logic g,
    input  logic p,
    input  logic g_prec,
    input  logic p_prec,
    input  logic p_out,
    input  logic g_out_BAR
);
    ///// Combinational equivalence /////
    // p_out equals p_prec AND p.
    check_p_out_equation: assert property (
        @(posedge CLK) p_out == (p_prec & p)
    );
    // g_out_BAR equals NOT((g_prec AND p) OR g).
    check_g_out_BAR_equation: assert property (
        @(posedge CLK) g_out_BAR == ~((g_prec & p) | g)
    );

    ///// Derived implications from logic /////
    // If p is LOW then p_out must be LOW.
    check_p_out_low_if_p_low: assert property (
        @(posedge CLK) (!p) |-> (p_out == 1'b0)
    );
    // If p_prec is LOW then p_out must be LOW.
    check_p_out_low_if_p_prec_low: assert property (
        @(posedge CLK) (!p_prec) |-> (p_out == 1'b0)
    );
    // If both p and p_prec are HIGH then p_out must be HIGH.
    check_p_out_high_if_both_high: assert property (
        @(posedge CLK) (p && p_prec) |-> (p_out == 1'b1)
    );
    // If p_out is HIGH then both p and p_prec are HIGH.
    check_p_out_implies_inputs_high: assert property (
        @(posedge CLK) p_out |-> (p && p_prec)
    );

    // If g is HIGH then g_out_BAR must be LOW.
    check_g_out_bar_low_if_g_high: assert property (
        @(posedge CLK) g |-> (g_out_BAR == 1'b0)
    );
    // If g_prec AND p are HIGH then g_out_BAR must be LOW.
    check_g_out_bar_low_if_gprec_and_p: assert property (
        @(posedge CLK) (g_prec && p) |-> (g_out_BAR == 1'b0)
    );
    // If g is LOW and (g_prec AND p) is LOW then g_out_BAR must be HIGH.
    check_g_out_bar_high_if_both_low: assert property (
        @(posedge CLK) (!g && !(g_prec && p)) |-> (g_out_BAR == 1'b1)
    );
    // If g_out_BAR is HIGH then g is LOW and (g_prec AND p) is LOW.
    check_g_out_bar_high_implies_inputs_low: assert property (
        @(posedge CLK) g_out_BAR |-> (!g && !(g_prec && p))
    );
endmodule

rtl:
module binary_counter (
  input clk,
  input rst,
  output reg [3:0] count,
  output reg max_reached
);

  always @(posedge clk or posedge rst) begin
    if (rst) begin
      count <= 4'b0;
      max_reached <= 1'b0;
    end
    else if (count == 4'b1111) begin
      count <= 4'b0;
      max_reached <= 1'b1;
    end
    else begin
      count <= count + 1;
      max_reached <= 1'b0;
    end
  end

endmodule

sva:
module binary_counter_sva (
  input logic clk,
  input logic rst,
  input logic [3:0] count,
  input logic max_reached
);

  // While reset is asserted, outputs are driven to zero.
  reset_drives_zero: assert property (
    @(posedge clk) rst |-> (count == 4'h0) && (max_reached == 1'b0)
  );

  // If previous cycle was active and count != 15, next count increments by 1 and flag is 0.
  increment_when_not_max: assert property (
    @(posedge clk) disable iff (rst)
      ($past(!rst) && ($past(count) != 4'hF)) |-> (count == ($past(count) + 4'd1)) && (max_reached == 1'b0)
  );

  // If previous cycle was active and count == 15, next count wraps to 0 and flag is 1.
  wrap_when_prev_max: assert property (
    @(posedge clk) disable iff (rst)
      ($past(!rst) && ($past(count) == 4'hF)) |-> (count == 4'h0) && (max_reached == 1'b1)
  );

  // Flag can only rise when previous count was 15.
  flag_rise_only_on_wrap: assert property (
    @(posedge clk) disable iff (rst)
      $rose(max_reached) |-> ($past(count) == 4'hF)
  );

  // When flag is 1, count is 0 in the same cycle.
  flag_implies_zero_count: assert property (
    @(posedge clk) disable iff (rst)
      max_reached |-> (count == 4'h0)
  );

  // Flag is a single-cycle pulse.
  flag_one_cycle_pulse: assert property (
    @(posedge clk) disable iff (rst)
      max_reached |-> !max_reached
  );

  // If count is non-zero, flag must be 0.
  nonzero_count_implies_flag_zero: assert property (
    @(posedge clk) disable iff (rst)
      (count != 4'h0) |-> (max_reached == 1'b0)
  );

  // If previous cycle was active and current count is 0, previous count was 15.
  zero_now_means_prev_max: assert property (
    @(posedge clk) disable iff (rst)
      ($past(!rst) && (count == 4'h0)) |-> ($past(count) == 4'hF)
  );

  // In active operation, count changes every cycle (increments or wraps).
  count_changes_every_cycle_active: assert property (
    @(posedge clk) disable iff (rst)
      $past(!rst) |-> (count != $past(count))
  );

  // If current count is 15, next cycle wraps to 0 and flag is 1.
  present_max_wraps_next: assert property (
    @(posedge clk) disable iff (rst)
      (count == 4'hF) |-> ##1 (count == 4'h0) && (max_reached == 1'b1)
  );

endmodule

module sync_counter_sva (
    input logic clk,
    input logic reset,       // active-high synchronous reset
    input logic enable,
    input logic direction,
    input logic [3:0] count
);

    // Reset drives count to zero on the next clock.
    reset_clears_next: assert property (
        @(posedge clk) reset |=> (count == 4'b0000)
    );

    // If reset is held across consecutive cycles, count is zero in the later cycle.
    reset_held_forces_zero: assert property (
        @(posedge clk) ($past(reset) && reset) |-> (count == 4'b0000)
    );

    // With enable LOW (and no reset), count holds its value to the next cycle.
    hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset) (!enable) |=> (count == $past(count))
    );

    // With enable HIGH and direction LOW, count increments by 1 with wrap at 4'hF->4'h0.
    increment_with_wrap: assert property (
        @(posedge clk) disable iff (reset)
        (enable && !direction) |=> (
            ($past(count) == 4'hF) ? (count == 4'h0) : (count == $past(count) + 4'd1)
        )
    );

    // With enable HIGH and direction HIGH, count decrements by 1 with wrap at 4'h0->4'hF.
    decrement_with_wrap: assert property (
        @(posedge clk) disable iff (reset)
        (enable && direction) |=> (
            ($past(count) == 4'h0) ? (count == 4'hF) : (count == $past(count) - 4'd1)
        )
    );

    // When enable is HIGH (and no reset), count must change on the next cycle.
    enabled_changes_count: assert property (
        @(posedge clk) disable iff (reset) enable |=> (count != $past(count))
    );

    // Any change in count must be due to reset or enable being HIGH in the prior cycle.
    change_requires_enable_or_reset: assert property (
        @(posedge clk) (count != $past(count)) |-> ($past(reset) || $past(enable))
    );

    // Increment wrap: at max (4'hF) with increment command, next count is 4'h0.
    increment_wrap_from_max: assert property (
        @(posedge clk) disable iff (reset)
        (enable && !direction && ($past(count) == 4'hF)) |=> (count == 4'h0)
    );

    // Decrement wrap: at min (4'h0) with decrement command, next count is 4'hF.
    decrement_wrap_from_min: assert property (
        @(posedge clk) disable iff (reset)
        (enable && direction && ($past(count) == 4'h0)) |=> (count == 4'hF)
    );

    // If neither reset nor enable were asserted in the prior cycle, count must not change.
    no_change_without_enable_or_reset_prev: assert property (
        @(posedge clk) (!$past(reset) && !$past(enable)) |-> (count == $past(count))
    );

endmodule

rtl:
module my_inverter (
    output reg Y,
    input  wire in
);

    always @(*) begin
        Y = ~in;
    end

endmodule

sva:
module my_inverter_sva (
    input  logic clk,
    input  logic Y,
    input  logic in
);
    // Y is always the bitwise inversion of in.
    check_inversion_value: assert property (
        @(posedge clk) (Y === ~in)
    );

    // When in rises, Y falls in the same cycle.
    check_in_rise_y_fall: assert property (
        @(posedge clk) $rose(in) |-> $fell(Y)
    );

    // When in falls, Y rises in the same cycle.
    check_in_fall_y_rise: assert property (
        @(posedge clk) $fell(in) |-> $rose(Y)
    );

    // If in is stable across cycles, Y is stable.
    check_stability_when_input_stable: assert property (
        @(posedge clk) (in === $past(in)) |-> (Y === $past(Y))
    );

    // Any change on Y implies in changed (no internal storage).
    check_y_change_implies_in_change: assert property (
        @(posedge clk) $changed(Y) |-> $changed(in)
    );

    // When in is 0, Y must be 1.
    check_in_low_y_high: assert property (
        @(posedge clk) (in == 1'b0) |-> (Y == 1'b1)
    );

    // When in is 1, Y must be 0.
    check_in_high_y_low: assert property (
        @(posedge clk) (in == 1'b1) |-> (Y == 1'b0)
    );
endmodule

rtl:
module MUX2X1 (A, B, S, Y);
input  A ;
input  B ;
input  S ;
output Y ;

   wire  notS;
   assign notS = ~S;

   wire  I0_out, I1_out;
   and   (I0_out, A, notS);
   and   (I1_out, B, S);

   or    (Y, I0_out, I1_out);

endmodule

module MUX4X1 (A, B, C, D, S0, S1, Y);
input  A ;
input  B ;
input  C ;
input  D ;
input  S0 ;
input  S1 ;
output Y ;

   wire  MUX2X1_1_out, MUX2X1_2_out;

   MUX2X1 MUX2X1_1 (A, B, S0, MUX2X1_1_out);
   MUX2X1 MUX2X1_2 (C, D, S0, MUX2X1_2_out);
   MUX2X1 MUX2X1_3 (MUX2X1_1_out, MUX2X1_2_out, S1, Y);

endmodule

sva:
module MUX2X1_sva (
    input logic CLK,    // External sampling clock; RTL has no clock/reset (purely combinational)
    input logic A,
    input logic B,
    input logic S,
    input logic Y
);
    // MUX2 truth table: when S=0, Y=A.
    check_mux2_sel0_A: assert property (
        @(posedge CLK) (S == 1'b0) |=> (Y == A)
    );
    // MUX2 truth table: when S=1, Y=B.
    check_mux2_sel1_B: assert property (
        @(posedge CLK) (S == 1'b1) |=> (Y == B)
    );
    // Functional equation: Y = (~S & A) | (S & B).
    check_mux2_functional_eq: assert property (
        @(posedge CLK) Y == ((~S & A) | (S & B))
    );
    // If A and B are equal, Y must equal that value regardless of S.
    check_mux2_equal_inputs_hold: assert property (
        @(posedge CLK) (A == B) |=> (Y == A)
    );
endmodule

module MUX4X1_sva (
    input logic CLK,    // External sampling clock; RTL has no clock/reset (purely combinational)
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic S0,
    input logic S1,
    input logic Y
);
    // Functional equation: Y = S1 ? (S0 ? D : C) : (S0 ? B : A).
    check_mux4_functional_eq: assert property (
        @(posedge CLK) Y == (S1 ? (S0 ? D : C) : (S0 ? B : A))
    );
    // Truth table: S1=0,S0=0 selects A.
    check_mux4_sel00_A: assert property (
        @(posedge CLK) ((S1 == 1'b0) && (S0 == 1'b0)) |=> (Y == A)
    );
    // Truth table: S1=0,S0=1 selects B.
    check_mux4_sel01_B: assert property (
        @(posedge CLK) ((S1 == 1'b0) && (S0 == 1'b1)) |=> (Y == B)
    );
    // Truth table: S1=1,S0=0 selects C.
    check_mux4_sel10_C: assert property (
        @(posedge CLK) ((S1 == 1'b1) && (S0 == 1'b0)) |=> (Y == C)
    );
    // Truth table: S1=1,S0=1 selects D.
    check_mux4_sel11_D: assert property (
        @(posedge CLK) ((S1 == 1'b1) && (S0 == 1'b1)) |=> (Y == D)
    );
    // Grouping by first stage: when S0=0, Y = (S1 ? C : A).
    check_mux4_grouping_S0_0: assert property (
        @(posedge CLK) (S0 == 1'b0) |=> (Y == (S1 ? C : A))
    );
    // Grouping by first stage: when S0=1, Y = (S1 ? D : B).
    check_mux4_grouping_S0_1: assert property (
        @(posedge CLK) (S0 == 1'b1) |=> (Y == (S1 ? D : B))
    );
    // If all data inputs are equal, Y must equal that value regardless of selects.
    check_mux4_all_equal_passthrough: assert property (
        @(posedge CLK) ((A == B) && (B == C) && (C == D)) |=> (Y == A)
    );
    // If S1=0 and A==B, Y must equal A regardless of S0.
    check_mux4_equal_pair_lowbank: assert property (
        @(posedge CLK) ((S1 == 1'b0) && (A == B)) |=> (Y == A)
    );
    // If S1=1 and C==D, Y must equal C regardless of S0.
    check_mux4_equal_pair_highbank: assert property (
        @(posedge CLK) ((S1 == 1'b1) && (C == D)) |=> (Y == C)
    );
endmodule

rtl:
module parity (
  input [n-1:0] in,
  output p,
  output [n-1:0] out
);

parameter n = 8; // number of input signals

// Compute the parity bit as a Boolean function of the input signals
wire parity_bit = ^in;

// Output the parity bit and the input signals
assign p = parity_bit;
assign out = in;

endmodule

sva:
module parity_sva #(
    parameter int unsigned n = 8
) (
    input  logic               clk,
    input  logic [n-1:0]       in,
    input  logic               p,
    input  logic [n-1:0]       out
);
    // out must mirror in exactly (bitwise).
    check_out_equals_in: assert property (
        @(posedge clk) out === in
    );

    // p must equal the reduction XOR of in.
    check_p_equals_xor_in: assert property (
        @(posedge clk) p === (^in)
    );

    // p must also equal the reduction XOR of out (since out == in).
    check_p_equals_xor_out: assert property (
        @(posedge clk) p === (^out)
    );

    // When in is all zeros, p must be 0 and out must be all zeros.
    check_zero_input_behavior: assert property (
        @(posedge clk) (in === '0) |-> (p === 1'b0) && (out === '0)
    );

    // When in is all ones, p must equal n%2 and out must be all ones.
    localparam bit P_ONES = (n % 2) ? 1'b1 : 1'b0;
    check_all_ones_input_behavior: assert property (
        @(posedge clk) (in === {n{1'b1}}) |-> (p === P_ONES) && (out === {n{1'b1}})
    );

    // When exactly one input bit is 1, p must be 1 and out must equal in.
    check_onehot_sets_parity: assert property (
        @(posedge clk) $onehot(in) |-> (p === 1'b1) && (out === in)
    );

    // If inputs are stable this cycle, outputs must be stable.
    check_stable_out_when_in_stable: assert property (
        @(posedge clk) $stable(in) |-> $stable(out)
    );

    // If inputs are stable this cycle, parity output must be stable.
    check_stable_p_when_in_stable: assert property (
        @(posedge clk) $stable(in) |-> $stable(p)
    );

    // If inputs change, outputs must change (since out mirrors in).
    check_changed_in_implies_changed_out: assert property (
        @(posedge clk) $changed(in) |-> $changed(out)
    );

    // If outputs change, inputs must have changed (no internal storage/logic).
    check_changed_out_implies_changed_in: assert property (
        @(posedge clk) $changed(out) |-> $changed(in)
    );
endmodule

rtl:
module modulo_operator (
  input [31:0] dividend,
  input [31:0] divisor,
  output reg [31:0] remainder
);

always @(*) begin
  if (divisor == 0) begin
    remainder = 0;
  end else begin
    remainder = dividend % divisor;
  end
end

endmodule

sva:
module modulo_operator_sva (
  input logic clk,
  input logic reset_n,
  input logic [31:0] dividend,
  input logic [31:0] divisor,
  input logic [31:0] remainder
);
  // If divisor is 0, remainder must be 0.
  check_div_by_zero_zero: assert property (
    @(posedge clk) disable iff (!reset_n) (divisor == 32'd0) |-> (remainder == 32'd0)
  );

  // For known nonzero divisor, remainder equals dividend % divisor.
  check_exact_modulo_result: assert property (
    @(posedge clk) disable iff (!reset_n) (!$isunknown(dividend) && !$isunknown(divisor) && (divisor != 32'd0)) |-> (remainder == (dividend % divisor))
  );

  // For known nonzero divisor, remainder is less than divisor.
  check_remainder_range: assert property (
    @(posedge clk) disable iff (!reset_n) (!$isunknown({dividend, divisor}) && (divisor != 32'd0)) |-> (remainder < divisor)
  );

  // If dividend < divisor and divisor != 0, remainder equals dividend.
  check_remainder_eq_dividend_when_smaller: assert property (
    @(posedge clk) disable iff (!reset_n) (!$isunknown({dividend, divisor}) && (divisor != 32'd0) && (dividend < divisor)) |-> (remainder == dividend)
  );

  // If dividend == divisor != 0, remainder is 0.
  check_remainder_zero_when_equal: assert property (
    @(posedge clk) disable iff (!reset_n) (!$isunknown({dividend, divisor}) && (divisor != 32'd0) && (dividend == divisor)) |-> (remainder == 32'd0)
  );

  // If divisor == 1, remainder is 0.
  check_remainder_zero_divisor_one: assert property (
    @(posedge clk) disable iff (!reset_n) (divisor == 32'd1) |-> (remainder == 32'd0)
  );

  // If divisor == 2, remainder equals LSB of dividend.
  check_remainder_parity_divisor_two: assert property (
    @(posedge clk) disable iff (!reset_n) (!$isunknown({dividend, divisor}) && (divisor == 32'd2)) |-> ((remainder[0] == dividend[0]) && (remainder[31:1] == 31'd0))
  );

  // Output must be stable if inputs are stable (purely combinational).
  check_stable_when_inputs_stable: assert property (
    @(posedge clk) disable iff (!reset_n) ($stable(dividend) && $stable(divisor)) |-> $stable(remainder)
  );

  // If dividend is 0, remainder is 0.
  check_remainder_zero_when_dividend_zero: assert property (
    @(posedge clk) disable iff (!reset_n) (!$isunknown(divisor) && (dividend == 32'd0)) |-> (remainder == 32'd0)
  );

  // For known nonzero divisor, (dividend - remainder) is divisible by divisor.
  check_difference_divisible: assert property (
    @(posedge clk) disable iff (!reset_n) (!$isunknown({dividend, divisor, remainder}) && (divisor != 32'd0)) |-> (((dividend - remainder) % divisor) == 32'd0)
  );

  // For known nonzero divisor, remainder is not greater than dividend.
  check_remainder_le_dividend: assert property (
    @(posedge clk) disable iff (!reset_n) (!$isunknown({dividend, divisor}) && (divisor != 32'd0)) |-> (remainder <= dividend)
  );
endmodule

rtl:
module mul16(
    input [15:0] a,
    input [15:0] b,
    output reg [31:0] result
);

always @(*) begin
    result = a * b;
end

endmodule

module pipelined_multiplier(
    input [31:0] a,
    input [31:0] b,
    input enable,
    output reg [31:0] result
);

wire [15:0] a_lsb = a[15:0];
wire [15:0] a_msb = a[31:16];
wire [15:0] b_lsb = b[15:0];
wire [15:0] b_msb = b[31:16];

wire [31:0] mul16_1_result;
wire [31:0] mul16_2_result;

mul16 mul16_1(.a(a_lsb), .b(b_lsb), .result(mul16_1_result));
mul16 mul16_2(.a(a_msb), .b(b_msb), .result(mul16_2_result));

always @(posedge enable) begin
    result <= mul16_1_result + (mul16_2_result << 16);
end

endmodule

sva:
module pipelined_multiplier_sva (
    input logic [31:0] a,
    input logic [31:0] b,
    input logic        enable,
    input logic [31:0] result
);
    ///// Functional transform on enable posedge /////
    // On each enable edge, next-sampled result equals (a[15:0]*b[15:0]) + ((a[31:16]*b[31:16]) << 16) from that edge.
    check_result_next_equals_split_sum: assert property (
        @(posedge enable) 1'b1 |=> result == $past( ( (a[15:0] * b[15:0]) + ((a[31:16] * b[31:16]) << 16) ) )
    );

    // On each enable edge, next-sampled result[15:0] equals low 16 bits of (a[15:0]*b[15:0]) from that edge.
    check_lower16_matches_ll_product: assert property (
        @(posedge enable) 1'b1 |=> result[15:0] == $past( (a[15:0] * b[15:0]) [15:0] )
    );

    // On each enable edge, next-sampled result[31:16] equals ((a[15:0]*b[15:0])>>16 + (a[31:16]*b[31:16])[15:0]) low 16 bits from that edge.
    check_upper16_matches_composed_sum: assert property (
        @(posedge enable) 1'b1 |=> result[31:16] == $past( ( ( ( (a[15:0] * b[15:0]) >> 16 ) [15:0] ) + ( (a[31:16] * b[31:16]) [15:0] ) ) [15:0] )
    );

    ///// Stability properties /////
    // If a and b are unchanged across consecutive enable edges, result is unchanged at the next edge.
    check_result_stable_if_inputs_stable: assert property (
        @(posedge enable) (a == $past(a) && b == $past(b)) |=> (result == $past(result))
    );

    // If only low halves of a and b are unchanged across edges, result[15:0] is unchanged at the next edge.
    check_low16_stable_if_low_inputs_stable: assert property (
        @(posedge enable) ((a[15:0] == $past(a[15:0])) && (b[15:0] == $past(b[15:0]))) |=> (result[15:0] == $past(result[15:0]))
    );

    ///// Special-case input patterns /////
    // If either operand is zero at an enable edge, result becomes zero at the next edge.
    check_result_zero_when_operand_zero: assert property (
        @(posedge enable) ((a == 32'd0) || (b == 32'd0)) |=> (result == 32'd0)
    );

    // If both high halves are zero at an enable edge, next-sampled result equals (a[15:0]*b[15:0]).
    check_result_equals_ll_when_high_zero: assert property (
        @(posedge enable) ((a[31:16] == 16'd0) && (b[31:16] == 16'd0)) |=> (result == $past(a[15:0] * b[15:0]))
    );

    // If any low half is zero at an enable edge, next-sampled result[15:0] is zero.
    check_low16_zero_when_any_low_zero: assert property (
        @(posedge enable) ((a[15:0] == 16'd0) || (b[15:0] == 16'd0)) |=> (result[15:0] == 16'd0)
    );

    // If any low half is zero at an enable edge, next-sampled result[31:16] equals (a[31:16]*b[31:16])[15:0].
    check_upper16_eq_msbprod_low16_when_low_zero: assert property (
        @(posedge enable) ((a[15:0] == 16'd0) || (b[15:0] == 16'd0)) |=> (result[31:16] == $past( (a[31:16] * b[31:16]) [15:0] ))
    );
endmodule

rtl:
module mux_4to1_case (
    input A, B, C, D,
    input [1:0] sel,
    input clk,  // Added clock input
    output reg Y
);

reg [1:0] stage1_sel;
reg [1:0] stage2_sel;

always @(*) begin
    stage1_sel = sel;
    stage2_sel = stage1_sel;
end

always @(posedge clk) begin  // Corrected the event to use the clock input
    case (stage2_sel)
        2'b00: Y <= A;
        2'b01: Y <= B;
        2'b10: Y <= C;
        2'b11: Y <= D;
    endcase
end

endmodule

sva:
module mux_4to1_case_sva (
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic [1:0] sel,
    input logic clk,
    input logic Y
);
    // Clock: clk (posedge). No reset in RTL.
    // Mixed logic: combinational sel propagation; sequential update of Y on clk.

    // When sel==00, next-cycle Y equals current A.
    y_updates_on_sel_00: assert property (
        @(posedge clk) (sel == 2'b00) |=> (Y == $past(A))
    );

    // When sel==01, next-cycle Y equals current B.
    y_updates_on_sel_01: assert property (
        @(posedge clk) (sel == 2'b01) |=> (Y == $past(B))
    );

    // When sel==10, next-cycle Y equals current C.
    y_updates_on_sel_10: assert property (
        @(posedge clk) (sel == 2'b10) |=> (Y == $past(C))
    );

    // When sel==11, next-cycle Y equals current D.
    y_updates_on_sel_11: assert property (
        @(posedge clk) (sel == 2'b11) |=> (Y == $past(D))
    );

    // If sel stays 00 and A is stable across cycles, Y remains stable.
    y_stable_when_sel00_and_A_stable: assert property (
        @(posedge clk) (sel == 2'b00 && $stable(sel) && $stable(A)) |=> $stable(Y)
    );

    // If sel stays 01 and B is stable across cycles, Y remains stable.
    y_stable_when_sel01_and_B_stable: assert property (
        @(posedge clk) (sel == 2'b01 && $stable(sel) && $stable(B)) |=> $stable(Y)
    );

    // If sel stays 10 and C is stable across cycles, Y remains stable.
    y_stable_when_sel10_and_C_stable: assert property (
        @(posedge clk) (sel == 2'b10 && $stable(sel) && $stable(C)) |=> $stable(Y)
    );

    // If sel stays 11 and D is stable across cycles, Y remains stable.
    y_stable_when_sel11_and_D_stable: assert property (
        @(posedge clk) (sel == 2'b11 && $stable(sel) && $stable(D)) |=> $stable(Y)
    );

endmodule

rtl:
module bitwise_and(
  input [15:0] A,
  input [15:0] B,
  output [15:0] C
);

  assign C = A & B;

endmodule

sva:
module bitwise_and_sva (
    input logic CLK,
    input logic [15:0] A,
    input logic [15:0] B,
    input logic [15:0] C
);
    // C equals bitwise AND of A and B.
    check_and_functional: assert property (
        @(posedge CLK) disable iff (1'b0) (C == (A & B))
    );

    // No C bit can be 1 unless both A and B bits are 1.
    check_no_spurious_ones: assert property (
        @(posedge CLK) disable iff (1'b0) ((C & (~A | ~B)) == 16'h0000)
    );

    // All (A & B) 1-bits must appear in C (no missing ones).
    check_no_missing_ones: assert property (
        @(posedge CLK) disable iff (1'b0) (((A & B) & ~C) == 16'h0000)
    );

    // If A is all zeros, C is all zeros.
    check_zero_when_A_zero: assert property (
        @(posedge CLK) disable iff (1'b0) (A == 16'h0000) |-> (C == 16'h0000)
    );

    // If B is all zeros, C is all zeros.
    check_zero_when_B_zero: assert property (
        @(posedge CLK) disable iff (1'b0) (B == 16'h0000) |-> (C == 16'h0000)
    );

    // If A is all ones, C passes B unchanged.
    check_pass_through_when_A_all_ones: assert property (
        @(posedge CLK) disable iff (1'b0) (A == 16'hFFFF) |-> (C == B)
    );

    // If B is all ones, C passes A unchanged.
    check_pass_through_when_B_all_ones: assert property (
        @(posedge CLK) disable iff (1'b0) (B == 16'hFFFF) |-> (C == A)
    );
endmodule

