module up_down_counter (
    input clk,
    input up_down,
    input [3:0] load,
    output [7:0] count
);

reg [7:0] count;

always @(posedge clk) begin
    if (load != 0) begin
        count <= load;
    end else if (up_down == 1) begin
        count <= count + 1;
    end else begin
        count <= count - 1;
    end
end

endmodule

sva:
module up_down_counter_sva (
    input logic clk,
    input logic up_down,
    input logic [3:0] load,
    input logic [7:0] count
);

    // When load is non-zero, next count equals zero-extended load value.
    check_load_priority_value: assert property (
        @(posedge clk) (load != 4'd0) |=> (count == {4'b0000, $past(load)})
    );

    // When no load and up_down==1, next count increments by 1.
    check_increment_on_up: assert property (
        @(posedge clk) (load == 4'd0 && up_down == 1'b1) |=> (count == $past(count) + 8'd1)
    );

    // When no load and up_down==0, next count decrements by 1.
    check_decrement_on_down: assert property (
        @(posedge clk) (load == 4'd0 && up_down == 1'b0) |=> (count == $past(count) - 8'd1)
    );

    // On load, upper nibble of next count is zero.
    check_load_upper_nibble_zero: assert property (
        @(posedge clk) (load != 4'd0) |=> (count[7:4] == 4'b0000)
    );

    // On load, lower nibble of next count matches load.
    check_load_lower_nibble_matches: assert property (
        @(posedge clk) (load != 4'd0) |=> (count[3:0] == $past(load))
    );

    // With no load, next value changes by exactly +/-1 based on up_down.
    check_step_by_one_when_no_load: assert property (
        @(posedge clk) (load == 4'd0) |=> (count == $past(count) + ($past(up_down) ? 8'd1 : 8'hFF))
    );

    // Increment wrap-around: 0xFF -> 0x00 when no load and counting up.
    check_wrap_increment: assert property (
        @(posedge clk) (load == 4'd0 && up_down == 1'b1 && $past(count) == 8'hFF) |=> (count == 8'h00)
    );

    // Decrement wrap-around: 0x00 -> 0xFF when no load and counting down.
    check_wrap_decrement: assert property (
        @(posedge clk) (load == 4'd0 && up_down == 1'b0 && $past(count) == 8'h00) |=> (count == 8'hFF)
    );

    // Two consecutive no-load increments result in net +2 after two cycles.
    check_two_cycle_increment: assert property (
        @(posedge clk) (load == 4'd0 && up_down == 1'b1) ##1 (load == 4'd0 && up_down == 1'b1) |-> (count == $past(count,2) + 8'd2)
    );

    // Two consecutive no-load decrements result in net -2 after two cycles.
    check_two_cycle_decrement: assert property (
        @(posedge clk) (load == 4'd0 && up_down == 1'b0) ##1 (load == 4'd0 && up_down == 1'b0) |-> (count == $past(count,2) - 8'd2)
    );

endmodule

rtl:
module top_module(
    input [2:0] in_vec1,
    input [2:0] in_vec2,
    input sel_b1,
    input sel_b2,
    output [2:0] out_vec,
    output even_parity
);

    wire [2:0] mux_out;
    wire [2:0] rev_in_vec;
    wire even_parity1, even_parity2;

    // 2-to-1 mux implementation
    assign mux_out = sel_b2 ? {in_vec2[2], in_vec2[1], in_vec2[0]} : {in_vec1[2], in_vec1[1], in_vec1[0]};

    // Reverse parity module implementation
    reg [2:0] shift_reg;
    wire xor_out1, xor_out2, xor_out3;

    assign even_parity1 = xor_out1 ^ xor_out2 ^ xor_out3;
    assign even_parity2 = xor_out1 ^ xor_out2 ^ xor_out3 ^ 1'b1;

    always @(posedge sel_b1) begin
        shift_reg <= sel_b2 ? {in_vec2[2], in_vec2[1], in_vec2[0]} : {in_vec1[2], in_vec1[1], in_vec1[0]};
    end

    assign rev_in_vec = shift_reg;

    assign xor_out1 = rev_in_vec[0] ^ rev_in_vec[1];
    assign xor_out2 = rev_in_vec[1] ^ rev_in_vec[2];
    assign xor_out3 = rev_in_vec[2] ^ rev_in_vec[0];

    assign out_vec = even_parity1 ? {rev_in_vec, 1'b1} : {mux_out, 1'b1};
    assign even_parity = even_parity2;

endmodule

sva:
module top_module_sva (
    input logic [2:0] in_vec1,
    input logic [2:0] in_vec2,
    input logic sel_b1,   // clock
    input logic sel_b2,
    input logic [2:0] out_vec,
    input logic even_parity
);
    // Clock: sel_b1 (posedge). No reset.
    // Logic: mixed (sequential shift_reg on sel_b1; outputs are combinational).
    // Behavior: out_vec = { (sel_b2 ? in_vec2[1:0] : in_vec1[1:0]), 1'b1 }; even_parity = 1.

    // even_parity output is constant HIGH.
    check_even_parity_const_high: assert property (
        @(posedge sel_b1) even_parity == 1'b1
    );

    // out_vec LSB is always 1.
    check_out_lsb_is_one: assert property (
        @(posedge sel_b1) out_vec[0] == 1'b1
    );

    // Upper two bits of out_vec follow the selected input's [1:0].
    check_out_upper_bits_mux_function: assert property (
        @(posedge sel_b1) out_vec[2:1] == (sel_b2 ? in_vec2[1:0] : in_vec1[1:0])
    );

    // When sel_b2 is HIGH, out_vec[2:1] equals in_vec2[1:0].
    check_sel_high_path_upper_bits: assert property (
        @(posedge sel_b1) sel_b2 |-> (out_vec[2:1] == in_vec2[1:0])
    );

    // When sel_b2 is LOW, out_vec[2:1] equals in_vec1[1:0].
    check_sel_low_path_upper_bits: assert property (
        @(posedge sel_b1) !sel_b2 |-> (out_vec[2:1] == in_vec1[1:0])
    );

    // Full out_vec equals concat of selected [1:0] with trailing 1.
    check_out_vec_full_concat: assert property (
        @(posedge sel_b1) out_vec == { (sel_b2 ? in_vec2[1:0] : in_vec1[1:0]), 1'b1 }
    );

endmodule

