module sparc_ifu_cmp35(
   hit, 
   a, b, valid
   );

   input [34:0] a, b;
   input 	valid;

   output 	hit;

   reg 		hit;
   wire 	valid;
   wire [34:0] 	a, b;

   always @ (a or b or valid)
     begin
	if ((a==b) & valid)
	  hit = 1'b1;
	else
	  hit = 1'b0;
     end endmodule

sva:
module sparc_ifu_cmp35_sva (
    input logic [34:0] a,
    input logic [34:0] b,
    input logic        valid,
    input logic        hit
);
    // Combinational compare; no clock/reset in RTL; sample using $global_clock.

    // hit equals (a==b) & valid.
    check_hit_function: assert property (
        @($global_clock) hit == ((a == b) & valid)
    );

    // When valid is low, hit must be 0.
    check_no_hit_when_valid_low: assert property (
        @($global_clock) !valid |-> (hit == 1'b0)
    );

    // When valid is high and a equals b, hit must be 1.
    check_hit_when_valid_and_equal: assert property (
        @($global_clock) (valid && (a == b)) |-> (hit == 1'b1)
    );

    // When valid is high and a not equal b, hit must be 0.
    check_no_hit_when_valid_and_not_equal: assert property (
        @($global_clock) (valid && (a != b)) |-> (hit == 1'b0)
    );

    // If hit is 1 then valid is 1 and a equals b.
    check_hit_implies_valid_and_equal: assert property (
        @($global_clock) hit |-> (valid && (a == b))
    );

    // If a, b, and valid are stable, hit remains stable.
    check_stability: assert property (
        @($global_clock) ($stable(a) && $stable(b) && $stable(valid)) |-> $stable(hit)
    );

    // Any change on hit must be caused by a, b, or valid changing.
    check_hit_change_needs_input_change: assert property (
        @($global_clock) $changed(hit) |-> ($changed(a) || $changed(b) || $changed(valid))
    );
endmodule

rtl:
module xor4 (
    X,
    A,
    B,
    C,
    D
);

    // Port declaration
    output X;
    input  A;
    input  B;
    input  C;
    input  D;

    // Internal signals
    wire AB, CD, ABCD;

    // Instantiate XOR gates
    xor (AB, A, B);
    xor (CD, C, D);
    xor (ABCD, AB, CD);

    // Output assignment
    assign X = ABCD;

endmodule

sva:
module xor4_sva (
    input logic CLK,
    input logic RESETn,
    input logic X,
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic AB,
    input logic CD,
    input logic ABCD
);

    ///// Structural equivalence to instantiated gates /////
    // AB equals A XOR B.
    check_ab_xor: assert property (
        @(posedge CLK) disable iff (!RESETn) AB == (A ^ B)
    );

    // CD equals C XOR D.
    check_cd_xor: assert property (
        @(posedge CLK) disable iff (!RESETn) CD == (C ^ D)
    );

    // ABCD equals AB XOR CD.
    check_abcd_xor: assert property (
        @(posedge CLK) disable iff (!RESETn) ABCD == (AB ^ CD)
    );

    // X is assigned directly from ABCD.
    check_output_assign: assert property (
        @(posedge CLK) disable iff (!RESETn) X == ABCD
    );

    ///// Functional parity property /////
    // X equals the XOR of A, B, C, and D.
    check_x_equals_xor4: assert property (
        @(posedge CLK) disable iff (!RESETn) X == ((A ^ B) ^ (C ^ D))
    );

    ///// Temporal consistency from combinational behavior /////
    // With reset previously deasserted, X's change equals parity of input changes.
    check_parity_change_equivalence: assert property (
        @(posedge CLK) disable iff (!RESETn)
            $past(RESETn) |-> ((X ^ $past(X)) == ((A ^ $past(A)) ^ (B ^ $past(B)) ^ (C ^ $past(C)) ^ (D ^ $past(D))))
    );

    // If inputs are stable, X remains stable.
    check_stable_inputs_hold_output: assert property (
        @(posedge CLK) disable iff (!RESETn)
            ($past(RESETn) && $stable(A) && $stable(B) && $stable(C) && $stable(D)) |-> $stable(X)
    );

    // If exactly one input toggles, X toggles.
    check_one_input_toggle_changes_output: assert property (
        @(posedge CLK) disable iff (!RESETn)
            ($past(RESETn) && ($countones({A ^ $past(A), B ^ $past(B), C ^ $past(C), D ^ $past(D)}) == 1)) |-> (X ^ $past(X))
    );

    // If exactly two inputs toggle, X does not change.
    check_two_input_toggle_keeps_output: assert property (
        @(posedge CLK) disable iff (!RESETn)
            ($past(RESETn) && ($countones({A ^ $past(A), B ^ $past(B), C ^ $past(C), D ^ $past(D)}) == 2)) |-> (X == $past(X))
    );

    // If all four inputs toggle, X does not change.
    check_four_input_toggle_keeps_output: assert property (
        @(posedge CLK) disable iff (!RESETn)
            ($past(RESETn) && ($countones({A ^ $past(A), B ^ $past(B), C ^ $past(C), D ^ $past(D)}) == 4)) |-> (X == $past(X))
    );

endmodule

rtl:
module adder_2bit(input [1:0] A, B, S, output [1:0] O);

  wire [1:0] sum;
  wire [1:0] diff;

  wire s_not;
  not (s_not, S);

  // Calculate sum and difference
  assign sum = A + B;
  assign diff = {A[1] ^ B[1], A[0] ^ B[0]} + {~B[1], ~B[0], 1'b0};

  // Use mux2to1 to select output based on S
  assign O = s_not ? sum : diff;

endmodule

sva:
module adder_2bit_sva (
    input logic CLK,
    input logic [1:0] A,
    input logic [1:0] B,
    input logic [1:0] S,
    input logic [1:0] O,
    input logic [1:0] sum,
    input logic [1:0] diff,
    input logic       s_not
);
    // sum must equal A+B (2-bit modulo arithmetic).
    check_sum_def: assert property (
        @(posedge CLK) sum == (A + B)
    );

    // sum[0] equals A[0] XOR B[0].
    check_sum_bit0_xor: assert property (
        @(posedge CLK) sum[0] == (A[0] ^ B[0])
    );

    // sum[1] equals A[1] XOR B[1] XOR carry from bit0.
    check_sum_bit1: assert property (
        @(posedge CLK) sum[1] == (A[1] ^ B[1] ^ (A[0] & B[0]))
    );

    // diff equals truncated 2 LSBs of the 3-bit addition per RTL.
    check_diff_def: assert property (
        @(posedge CLK) diff == ( {A[1]^B[1], A[0]^B[0]} + {~B[1], ~B[0], 1'b0} )[1:0]
    );

    // diff[0] equals A[0] XOR B[0].
    check_diff_bit0_xor: assert property (
        @(posedge CLK) diff[0] == (A[0] ^ B[0])
    );

    // diff[1] equals (A[1] XOR B[1]) XOR (~B[0]).
    check_diff_bit1_expr: assert property (
        @(posedge CLK) diff[1] == ((A[1] ^ B[1]) ^ ~B[0])
    );

    // Output O must select sum when s_not is 1, else diff.
    check_o_mux: assert property (
        @(posedge CLK) O == (s_not ? sum : diff)
    );

    // When s_not is 1, O equals sum.
    check_o_when_snot_1: assert property (
        @(posedge CLK) s_not |-> (O == sum)
    );

    // When s_not is 0, O equals diff.
    check_o_when_snot_0: assert property (
        @(posedge CLK) !s_not |-> (O == diff)
    );
endmodule

module adder_subtractor_sva (
    // DUT ports
    input logic [3:0] A,
    input logic [3:0] B,
    input logic       C,
    input logic [3:0] out,
    // Sampling clock for SVA (DUT is combinational; no reset present)
    input logic       clk
);
    // When C==0, output equals A+B (4-bit wraparound).
    compute_add_correct: assert property (
        @(posedge clk) (C == 1'b0) |-> (out == (A + B))
    );

    // When C==1, output equals A-B (4-bit wraparound).
    compute_sub_correct: assert property (
        @(posedge clk) (C == 1'b1) |-> (out == (A - B))
    );

    // If both inputs are zero, output is zero (both modes).
    zero_when_both_zero: assert property (
        @(posedge clk) ((A == 4'd0) && (B == 4'd0)) |-> (out == 4'd0)
    );

    // In subtraction mode and A==B, output is zero.
    sub_equal_zero: assert property (
        @(posedge clk) (C == 1'b1 && (A == B)) |-> (out == 4'd0)
    );

    // In addition mode with B==0, output passes A.
    add_passthrough_b_zero: assert property (
        @(posedge clk) (C == 1'b0 && (B == 4'd0)) |-> (out == A)
    );

    // In subtraction mode with B==0, output passes A.
    sub_passthrough_b_zero: assert property (
        @(posedge clk) (C == 1'b1 && (B == 4'd0)) |-> (out == A)
    );

    // In addition mode with A==0, output passes B.
    add_passthrough_a_zero: assert property (
        @(posedge clk) (C == 1'b0 && (A == 4'd0)) |-> (out == B)
    );
endmodule

