    // If B is HIGH, X must be HIGH.
    check_b_implies_x_high: assert property (
        @($global_clock) B |-> X
    );
    // If C is HIGH, X must be HIGH.
    check_c_implies_x_high: assert property (
        @($global_clock) C |-> X
    );
    // If D_N is HIGH, X must be HIGH.
    check_d_implies_x_high: assert property (
        @($global_clock) D_N |-> X
