    input b,
    input cin,
    output sum,
    output cout
);

    wire s1;
    wire c1;
    wire c2;

    xor(s1, a, b);
    xor(sum, s1, cin);
    and(c1, a, b);
    and(c2, s1, cin);
    or(cout, c1, c2);

endmodule

