module sram (
    input wire [7:0] address,
    input wire [7:0] data_in,
    input wire clk,
    input wire write_enable,
    output reg [7:0] data_out
);

    always @(posedge clk) begin
        if (write_enable) begin
            data_out <= data_in;
        end
    end

endmodule

module ff_d #(parameter WIDTH = 8) (
    input wire [WIDTH-1:0] D,
    input wire en,
    input wire clk,
    input wire res,
    output reg [WIDTH-1:0] Q
);

    always @(posedge clk or posedge res) begin
        if (res) begin
            Q <= 8'b0;
        end else if (en) begin
            Q <= D;
        end
    end

endmodule

module memory_decoder(
    input wire [7:0] address,
    input wire [7:0] data_in,
    input wire [7:0] switch_in,
    input wire clk,
    input wire res,
    input wire write_enable,
    output wire [7:0] LED_status,
    output wire [7:0] data_out
);

    wire [7:0] memory_data_out;
    wire [7:0] switch_data_out;
    wire mem_write_enable, LED_write_enable;

    // mask write to address 0xff for LED usage
    assign mem_write_enable = write_enable & (~&address);

    // sram block
    sram sram0 (
        .address(address),
        .data_in(data_in),
        .clk(clk),
        .write_enable(mem_write_enable),
        .data_out(memory_data_out)
    );

    // decode LED address
    assign LED_write_enable = write_enable & (&address);

    // LED output driver flip flop
    ff_d #(.WIDTH(8)) led_driver0 (
        .D(data_in),
        .en(LED_write_enable),
        .clk(clk),
        .res(res),
        .Q(LED_status)
    );

    // switch input driver flip flop
    ff_d #(.WIDTH(8)) switch_driver0 (
        .D(switch_in),
        .en(1'b1),
        .clk(clk),
        .res(res),
        .Q(switch_data_out)
    );

    // decode read address
    assign data_out = (~&address) ? memory_data_out : switch_data_out;

endmodule

sva:
module memory_decoder_sva (
    input logic [7:0] address,
    input logic [7:0] data_in,
    input logic [7:0] switch_in,
    input logic clk,
    input logic res,
    input logic write_enable,
    input logic [7:0] LED_status,
    input logic [7:0] data_out
);
    // LED_status must be 0 while reset is asserted.
    reset_led_status_zero: assert property (
        @(posedge clk) res |-> (LED_status == 8'h00)
    );

    // While reset is asserted and address==0xFF, data_out (switch path) must be 0.
    reset_switch_path_zero: assert property (
        @(posedge clk) res && (&address) |-> (data_out == 8'h00)
    );

    // Writing to address 0xFF updates LED_status with data_in on the next cycle.
    led_updates_on_we_ffff: assert property (
        @(posedge clk) disable iff (res) (write_enable && (&address)) |=> (LED_status == $past(data_in))
    );

    // LED_status holds when not writing to address 0xFF.
    led_holds_without_enable: assert property (
        @(posedge clk) disable iff (res) (!(write_enable && (&address))) |=> (LED_status == $past(LED_status))
    );

    // Any LED_status change requires a 0xFF write in the prior cycle (outside reset).
    led_change_requires_prev_enable: assert property (
        @(posedge clk) disable iff (res) (LED_status != $past(LED_status)) |-> $past(write_enable && (&address) && !res)
    );

    // When address==0xFF, data_out is the prior-cycle switch_in sample.
    dataout_switch_samples_prev: assert property (
        @(posedge clk) disable iff (res) (&address) |-> (data_out == $past(switch_in))
    );

    // When address!=0xFF and write_enable, data_out reflects data_in in the same cycle.
    dataout_mem_write_same_cycle: assert property (
        @(posedge clk) disable iff (res) ((~&address) && write_enable) |-> (data_out == data_in)
    );

    // If address!=0xFF for two cycles and no writes in either cycle edge, data_out holds.
    dataout_mem_hold_no_write: assert property (
        @(posedge clk) disable iff (res) ((~&address) && (~&$past(address)) && !write_enable && !$past(write_enable)) |-> (data_out == $past(data_out))
    );

    // After a reset cycle, LED_status stays 0 until a 0xFF write occurs.
    led_zero_after_reset_until_write: assert property (
        @(posedge clk) disable iff (res) $past(res) && !(write_enable && (&address)) |-> (LED_status == 8'h00)
    );
endmodule

rtl:
module GeAr_N8_R1_P6 (
    input [7:0] in1,
    input [7:0] in2,
    output [8:0] res
);

assign res = in1 + in2;

endmodule

sva:
module GeAr_N8_R1_P6_sva (
    input logic clk,         // sampling clock (RTL has no clock)
    input logic [7:0] in1,
    input logic [7:0] in2,
    input logic [8:0] res
);
    // Output equals 8-bit sum (zero-extended to 9 bits).
    check_sum_definition: assert property (
        @(posedge clk) disable iff (1'b0) res == (in1 + in2)
    );

    // MSB of result is always zero.
    check_msb_zero: assert property (
        @(posedge clk) disable iff (1'b0) res[8] == 1'b0
    );

    // Lower byte matches truncated 8-bit sum.
    check_lower_byte_match: assert property (
        @(posedge clk) disable iff (1'b0) res[7:0] == (in1 + in2)
    );

    // Commutativity preserved: swapping operands yields same result.
    check_commutative_sum: assert property (
        @(posedge clk) disable iff (1'b0) res == (in2 + in1)
    );

    // Adding zero on in2 returns in1 in the lower byte and zero MSB.
    check_add_zero_in2: assert property (
        @(posedge clk) disable iff (1'b0) (in2 == 8'd0) |-> (res[7:0] == in1 && res[8] == 1'b0)
    );

    // Adding zero on in1 returns in2 in the lower byte and zero MSB.
    check_add_zero_in1: assert property (
        @(posedge clk) disable iff (1'b0) (in1 == 8'd0) |-> (res[7:0] == in2 && res[8] == 1'b0)
    );

    // If inputs are stable across a cycle, output is stable (pure combinational).
    check_stability_when_inputs_stable: assert property (
        @(posedge clk) disable iff (1'b0) ($stable(in1) && $stable(in2)) |-> $stable(res)
    );

    // Output numeric range is 0..255.
    check_output_range: assert property (
        @(posedge clk) disable iff (1'b0) res <= 9'd255
    );

    // LSB equals XOR of input LSBs (no carry-in).
    check_lsb_xor: assert property (
        @(posedge clk) disable iff (1'b0) res[0] == (in1[0] ^ in2[0])
    );
endmodule

