module FULL_ADDER(A, B, Cin, Sum, Cout);
input A, B, Cin;
output Sum, Cout;

wire w1, w2, w3;

xor(w1, A, B);
xor(Sum, Cin, w1);
and(w2, A, B);
and(w3, w1, Cin);
or(Cout, w2, w3);

endmodule

module ADD4(A, B, Cin, Sum, Cout);
input [3:0] A, B;
input Cin;
output [3:0] Sum;
output Cout;

wire c1, c2, c3;
FULL_ADDER fa1(A[0], B[0], Cin, Sum[0], c1);
FULL_ADDER fa2(A[1], B[1], c1, Sum[1], c2);
FULL_ADDER fa3(A[2], B[2], c2, Sum[2], c3);
FULL_ADDER fa4(A[3], B[3], c3, Sum[3], Cout);

endmodule

sva:
module ADD4_sva (
    input logic CLK,               // Sampling clock for SVA (DUT is purely combinational; no reset)
    input logic [3:0] A,
    input logic [3:0] B,
    input logic Cin,
    input logic [3:0] Sum,
    input logic Cout
);
    // Local expected carry chain computed from inputs
    logic c1_exp, c2_exp, c3_exp;
    assign c1_exp = (A[0] & B[0]) | ((A[0] ^ B[0]) & Cin);
    assign c2_exp = (A[1] & B[1]) | ((A[1] ^ B[1]) & c1_exp);
    assign c3_exp = (A[2] & B[2]) | ((A[2] ^ B[2]) & c2_exp);

    // Local expected sums and carry-out
    logic [3:0] sum_exp;
    logic       cout_exp;
    assign sum_exp[0] = A[0] ^ B[0] ^ Cin;
    assign sum_exp[1] = A[1] ^ B[1] ^ c1_exp;
    assign sum_exp[2] = A[2] ^ B[2] ^ c2_exp;
    assign sum_exp[3] = A[3] ^ B[3] ^ c3_exp;
    assign cout_exp   = (A[3] & B[3]) | ((A[3] ^ B[3]) & c3_exp);

    // Arithmetic reference (5-bit)
    logic [4:0] add_exp;
    assign add_exp = A + B + Cin;

    // Sum[0] matches XOR of A0,B0,Cin.
    check_sum0_xor: assert property (
        @(posedge CLK) Sum[0] == (A[0] ^ B[0] ^ Cin)
    );

    // Sum[1] matches XOR of A1,B1 and carry c1.
    check_sum1_from_c1: assert property (
        @(posedge CLK) Sum[1] == (A[1] ^ B[1] ^ c1_exp)
    );

    // Sum[2] matches XOR of A2,B2 and carry c2.
    check_sum2_from_c2: assert property (
        @(posedge CLK) Sum[2] == (A[2] ^ B[2] ^ c2_exp)
    );

    // Sum[3] matches XOR of A3,B3 and carry c3.
    check_sum3_from_c3: assert property (
        @(posedge CLK) Sum[3] == (A[3] ^ B[3] ^ c3_exp)
    );

    // Cout matches carry out from MSB stage.
    check_cout_from_c3: assert property (
        @(posedge CLK) Cout == cout_exp
    );

    // Full 5-bit result matches arithmetic addition.
    check_vector_sum_matches_add: assert property (
        @(posedge CLK) {Cout, Sum} == add_exp
    );

    // If A3=0 and B3=0 then Cout must be 0.
    check_cout_msb_00: assert property (
        @(posedge CLK) (A[3] == 1'b0 && B[3] == 1'b0) |-> (Cout == 1'b0)
    );

    // If A3=1 and B3=1 then Cout must be 1.
    check_cout_msb_11: assert property (
        @(posedge CLK) (A[3] == 1'b1 && B[3] == 1'b1) |-> (Cout == 1'b1)
    );

    // If A3!=B3 then Cout equals c3 (carry into MSB).
    check_cout_msb_mismatch_equals_c3: assert property (
        @(posedge CLK) (A[3] ^ B[3]) |-> (Cout == c3_exp)
    );

    // If A3==B3 then Sum[3] equals c3.
    check_sum3_when_msb_equal: assert property (
        @(posedge CLK) (A[3] == B[3]) |-> (Sum[3] == c3_exp)
    );

    // If A3!=B3 then Sum[3] is inverse of c3.
    check_sum3_when_msb_mismatch: assert property (
        @(posedge CLK) (A[3] ^ B[3]) |-> (Sum[3] == ~c3_exp)
    );

    // If inputs are stable across a cycle, outputs remain stable.
    check_outputs_stable_if_inputs_stable: assert property (
        @(posedge CLK) $stable({A, B, Cin}) |-> $stable({Sum, Cout})
    );
endmodule

rtl:
module my_module (
  input in0, in1, in2, in3, d0, d1, d2, d3, clk, reset,
  output reg out0, out1, out2, out3
);

  wire n1, n2, n3, n4;

  assign n1 = ~(reset | n1);
  assign n2 = (in0 & d0) | (in1 & ~d0);
  assign n3 = ~(reset | n3);
  assign n4 = (in2 & d3) | (in3 & ~d3);

  always @(posedge clk) begin
    out0 <= d0;
    out1 <= d1;
    out2 <= d2;
    out3 <= d3;
  end

endmodule

sva:
module my_module_sva (
  input logic in0, in1, in2, in3,
  input logic d0, d1, d2, d3,
  input logic clk, reset,
  input logic out0, out1, out2, out3
);

  ///// Registering behavior /////
  // out0 equals d0 from the previous cycle.
  check_out0_registers_d0: assert property (
    @(posedge clk) disable iff (reset) out0 == $past(d0)
  );
  // out1 equals d1 from the previous cycle.
  check_out1_registers_d1: assert property (
    @(posedge clk) disable iff (reset) out1 == $past(d1)
  );
  // out2 equals d2 from the previous cycle.
  check_out2_registers_d2: assert property (
    @(posedge clk) disable iff (reset) out2 == $past(d2)
  );
  // out3 equals d3 from the previous cycle.
  check_out3_registers_d3: assert property (
    @(posedge clk) disable iff (reset) out3 == $past(d3)
  );

  ///// Change propagation /////
  // A change on d0 causes out0 to change next cycle.
  change_out0_follows_d0_change: assert property (
    @(posedge clk) disable iff (reset) $changed(d0) |=> $changed(out0)
  );
  // A change on d1 causes out1 to change next cycle.
  change_out1_follows_d1_change: assert property (
    @(posedge clk) disable iff (reset) $changed(d1) |=> $changed(out1)
  );
  // A change on d2 causes out2 to change next cycle.
  change_out2_follows_d2_change: assert property (
    @(posedge clk) disable iff (reset) $changed(d2) |=> $changed(out2)
  );
  // A change on d3 causes out3 to change next cycle.
  change_out3_follows_d3_change: assert property (
    @(posedge clk) disable iff (reset) $changed(d3) |=> $changed(out3)
  );

  ///// Stability propagation /////
  // If d0 is stable, out0 stays stable next cycle.
  stable_out0_when_d0_stable: assert property (
    @(posedge clk) disable iff (reset) !$changed(d0) |=> !$changed(out0)
  );
  // If d1 is stable, out1 stays stable next cycle.
  stable_out1_when_d1_stable: assert property (
    @(posedge clk) disable iff (reset) !$changed(d1) |=> !$changed(out1)
  );
  // If d2 is stable, out2 stays stable next cycle.
  stable_out2_when_d2_stable: assert property (
    @(posedge clk) disable iff (reset) !$changed(d2) |=> !$changed(out2)
  );
  // If d3 is stable, out3 stays stable next cycle.
  stable_out3_when_d3_stable: assert property (
    @(posedge clk) disable iff (reset) !$changed(d3) |=> !$changed(out3)
  );

endmodule

rtl:
module regfile(
  input [2:0] addr1,
  input [2:0] addr2,
  input [7:0] data_in,
  output reg [7:0] data_out1,
  output reg [7:0] data_out2,
  input wire write_en
);

  reg [7:0] regs [0:7];

  always @(*) begin
    // Read operations
    data_out1 = regs[addr1];
    data_out2 = regs[addr2];

    // Write operation
    if (write_en) begin
      regs[addr1] = data_in;
    end
  end

endmodule

sva:
module regfile_sva (
    input logic [2:0] addr1,
    input logic [2:0] addr2,
    input logic [7:0] data_in,
    input logic [7:0] data_out1,
    input logic [7:0] data_out2,
    input logic write_en
);
    // When both read addresses are equal, both outputs must match (sampled on write_en rising edge).
    check_equal_outputs_on_we_rise: assert property (
        @(posedge write_en) (addr1 == addr2) |-> (data_out1 == data_out2)
    );

    // When both read addresses are equal, both outputs must match (sampled on write_en falling edge).
    check_equal_outputs_on_we_fall: assert property (
        @(negedge write_en) (addr1 == addr2) |-> (data_out1 == data_out2)
    );
endmodule

rtl:
module clock_gate (input CLK, EN, TE, output ENCLK);
  wire EN_gate, TE_gate, CLK_gate, ENCLK;

  TLATNTSCAX2TS latch (.E(EN_gate), .SE(TE_gate), .CK(CLK_gate), .ECK(ENCLK));
  assign CLK_gate = CLK;
  assign EN_gate = EN;
  assign TE_gate = TE;
endmodule
module TLATNTSCAX2TS (
  input E, SE, CK,
  output reg ECK
);

  always @(posedge CK) begin
    if (E)
      ECK <= SE;
  end

endmodule

sva:
module clock_gate_sva (
    input logic CLK,
    input logic EN,
    input logic TE,
    input logic ENCLK
);
    // If EN was 1 on the previous edge, ENCLK now equals previous TE (1-cycle capture).
    check_capture_on_prev_enable: assert property (
        @(posedge CLK) $past(EN) |-> (ENCLK == $past(TE))
    );

    // If EN was 0 on the previous edge, ENCLK holds its value.
    check_hold_on_prev_disable: assert property (
        @(posedge CLK) $past(!EN) |-> (ENCLK == $past(ENCLK))
    );

    // Any change in ENCLK implies EN was 1 in the prior cycle.
    check_change_requires_enable: assert property (
        @(posedge CLK) (ENCLK != $past(ENCLK)) |-> $past(EN)
    );

    // When ENCLK changes, the new value must equal TE from the prior cycle.
    check_changed_value_matches_prev_te: assert property (
        @(posedge CLK) (ENCLK != $past(ENCLK)) |-> (ENCLK == $past(TE))
    );

    // TE changes have no effect when EN was 0 in the prior cycle.
    check_te_change_ignored_when_prev_disabled: assert property (
        @(posedge CLK) ($past(!EN) && (TE != $past(TE))) |-> (ENCLK == $past(ENCLK))
    );

    // If EN was 1 and TE did not change since last edge, ENCLK equals TE now.
    check_match_when_prev_enabled_and_te_stable: assert property (
        @(posedge CLK) ($past(EN) && (TE == $past(TE))) |-> (ENCLK == TE)
    );

    // If EN was 0 and is still 0, ENCLK must not change at this edge.
    check_no_change_across_two_cycle_disable: assert property (
        @(posedge CLK) ($past(!EN) && !EN) |-> (ENCLK == $past(ENCLK))
    );

    // If EN was 1 and TE changed at the current edge, ENCLK still reflects the prior TE (1-cycle latency).
    check_latency_when_prev_enabled_te_changed_now: assert property (
        @(posedge CLK) ($past(EN) && (TE != $past(TE))) |-> (ENCLK == $past(TE))
    );
endmodule

rtl:
module greater_than_module (
   input [3:0] a,
   input [3:0] b,
   output reg [3:0] x
);

always @(*) begin
    if (a > b) begin
        x = a;
    end else begin
        x = b;
    end
end

endmodule

sva:
module greater_than_module_sva (
    input logic clk,
    input logic [3:0] a,
    input logic [3:0] b,
    input logic [3:0] x
);

    // x equals the max of a and b per RTL conditional
    check_output_is_max_expr: assert property (
        @(posedge clk) x == ((a > b) ? a : b)
    );

    // When a > b, x must be a
    check_select_a_when_a_gt_b: assert property (
        @(posedge clk) (a > b) |-> (x == a)
    );

    // When a <= b, x must be b
    check_select_b_when_a_le_b: assert property (
        @(posedge clk) (a <= b) |-> (x == b)
    );

    // On tie (a == b), x selects b
    check_select_b_on_tie: assert property (
        @(posedge clk) (a == b) |-> (x == b)
    );

    // x must always equal either a or b
    check_x_equals_a_or_b_only: assert property (
        @(posedge clk) (x == a) || (x == b)
    );

    // If x equals a, then a must be greater than b
    check_if_x_is_a_then_a_gt_b: assert property (
        @(posedge clk) (x == a) |-> (a > b)
    );

    // If x equals b, then a must be less than or equal to b
    check_if_x_is_b_then_a_le_b: assert property (
        @(posedge clk) (x == b) |-> (a <= b)
    );

    // x is at least as large as a
    check_x_ge_a: assert property (
        @(posedge clk) (x >= a)
    );

    // x is at least as large as b
    check_x_ge_b: assert property (
        @(posedge clk) (x >= b)
    );

    // If either input is 4'hF, x must be 4'hF
    check_x_is_F_if_any_F: assert property (
        @(posedge clk) ((a == 4'hF) || (b == 4'hF)) |-> (x == 4'hF)
    );

    // If both inputs are zero, x must be zero
    check_x_is_zero_if_both_zero: assert property (
        @(posedge clk) ((a == 4'h0) && (b == 4'h0)) |-> (x == 4'h0)
    );

endmodule

module add_sub_sva (
    input logic CLK,
    input logic RESETn,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic sub,
    input logic [3:0] result
);
    // When sub=0, result is the low 4 bits of A+B.
    check_add_when_sub0: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (!sub) |-> (result == (A + B)[3:0])
    );

    // When sub=1, result is the low 4 bits of A-B.
    check_sub_when_sub1: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (sub) |-> (result == (A - B)[3:0])
    );

    // If B==0, result equals A (both add and sub cases).
    check_result_identity_B_zero: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (B == 4'd0) |-> (result == A)
    );

    // If A==0 and add mode, result equals B.
    check_result_identity_A_zero_add: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (!sub && (A == 4'd0)) |-> (result == B)
    );

    // If A==B and sub mode, result is zero.
    check_subtraction_zero_when_equal: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (sub && (A == B)) |-> (result == 4'd0)
    );

    // If A==0 and sub mode, result equals two's complement of B (0 - B mod 16).
    check_negate_B_when_A_zero_sub: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (sub && (A == 4'd0)) |-> (result == (4'd0 - B)[3:0])
    );

    // If inputs are unchanged across cycles, result is unchanged.
    check_output_stable_on_input_stable: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (A == $past(A) && B == $past(B) && sub == $past(sub)) |-> (result == $past(result))
    );

    // If only A increments by 1 and others hold, result increments by 1 (mod 16).
    check_result_follows_A_plus1: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (A == ($past(A) + 4'd1)[3:0] && B == $past(B) && sub == $past(sub)) |-> (result == ($past(result) + 4'd1)[3:0])
    );

    // In add mode, if only B increments by 1, result increments by 1 (mod 16).
    check_result_follows_B_plus1_add: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (!sub && sub == $past(sub) && A == $past(A) && B == ($past(B) + 4'd1)[3:0]) |-> (result == ($past(result) + 4'd1)[3:0])
    );

    // In sub mode, if only B increments by 1, result decrements by 1 (mod 16).
    check_result_follows_B_plus1_sub: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (sub && sub == $past(sub) && A == $past(A) && B == ($past(B) + 4'd1)[3:0]) |-> (result == ($past(result) - 4'd1)[3:0])
    );
endmodule

module register_sva (
    input logic d,
    input logic clk,
    input logic ena,
    input logic clr,
    input logic pr,
    input logic q
);

    // clr high forces q to 0 on the next cycle.
    check_clr_forces_zero: assert property (
        @(posedge clk) disable iff (1'b0) clr |=> (q == 1'b0)
    );

    // When clr and pr are both high, clear wins and q goes to 0 next cycle.
    check_priority_clr_over_pr: assert property (
        @(posedge clk) disable iff (1'b0) (clr && pr) |=> (q == 1'b0)
    );

    // pr high (with clr low) forces q to 1 on the next cycle.
    check_pr_sets_one_when_no_clr: assert property (
        @(posedge clk) disable iff (1'b0) (!clr && pr) |=> (q == 1'b1)
    );

    // With ena and no clr/pr, q loads d on the next cycle.
    check_ena_loads_d_when_no_clr_pr: assert property (
        @(posedge clk) disable iff (1'b0) (!clr && !pr && ena) |=> (q == $past(d))
    );

    // With no clr/pr/ena, q holds its previous value.
    check_hold_when_no_ctrl: assert property (
        @(posedge clk) disable iff (1'b0) (!clr && !pr && !ena) |=> (q == $past(q))
    );

    // With pr and ena asserted (and clr low), pr has priority and q goes to 1.
    check_priority_pr_over_ena: assert property (
        @(posedge clk) disable iff (1'b0) (!clr && pr && ena) |=> (q == 1'b1)
    );

    // A rising edge on q must be caused by prior pr or a load of 1.
    check_rise_q_caused_by_pr_or_load1: assert property (
        @(posedge clk) disable iff (1'b0)
            $rose(q) |-> (($past(pr) && !$past(clr)) ||
                          (!$past(clr) && !$past(pr) && $past(ena) && ($past(d) == 1'b1)))
    );

    // A falling edge on q must be caused by prior clr or a load of 0.
    check_fall_q_caused_by_clr_or_load0: assert property (
        @(posedge clk) disable iff (1'b0)
            $fell(q) |-> ($past(clr) ||
                          (!$past(clr) && !$past(pr) && $past(ena) && ($past(d) == 1'b0)))
    );

    // When loading a 1 (ena=1, no clr/pr, d=1), q becomes 1 next cycle.
    check_load_one: assert property (
        @(posedge clk) disable iff (1'b0) (!clr && !pr && ena && d) |=> (q == 1'b1)
    );

    // When loading a 0 (ena=1, no clr/pr, d=0), q becomes 0 next cycle.
    check_load_zero: assert property (
        @(posedge clk) disable iff (1'b0) (!clr && !pr && ena && !d) |=> (q == 1'b0)
    );

endmodule

rtl:
module PushButton_Debouncer(
    input clk,
    input PB,  // "PB" is the glitchy, asynchronous to clk, active low push-button signal

    // from which we make three outputs, all synchronous to the clock
    output reg PB_state,  // 1 as long as the push-button is active (down)
    output PB_down,  // 1 for one clock cycle when the push-button goes down (i.e. just pushed)
    output PB_up   // 1 for one clock cycle when the push-button goes up (i.e. just released)
);

// First use two flip-flops to synchronize the PB signal the "clk" clock domain
reg PB_sync_0;  always @(posedge clk) PB_sync_0 <= ~PB;  // invert PB to make PB_sync_0 active high
reg PB_sync_1;  always @(posedge clk) PB_sync_1 <= PB_sync_0;

// Next declare a 16-bits counter
reg [15:0] PB_cnt;


wire PB_idle = (PB_state==PB_sync_1);
wire PB_cnt_max = &PB_cnt;	// true when all bits of PB_cnt are 1's

always @(posedge clk)
if(PB_idle)
    PB_cnt <= 0;  // nothing's going on
else
begin
    PB_cnt <= PB_cnt + 16'd1;  // something's going on, increment the counter
    if(PB_cnt_max) PB_state <= ~PB_state;  // if the counter is maxed out, PB changed!
end

assign PB_down = ~PB_idle & PB_cnt_max & ~PB_state;
assign PB_up   = ~PB_idle & PB_cnt_max &  PB_state;
endmodule

sva:
module PushButton_Debouncer_sva (
    input logic clk,
    input logic PB,
    input logic PB_state,
    input logic PB_down,
    input logic PB_up,
    // Internal signals from RTL (bind hierarchically)
    input logic PB_sync_0,
    input logic PB_sync_1,
    input logic [15:0] PB_cnt,
    input logic PB_idle,
    input logic PB_cnt_max
);
    // PB_sync_0 samples inverted PB (1-cycle delayed in assertion sampling)
    check_sync0_tracks_PB: assert property (
        @(posedge clk) disable iff ($initstate) PB_sync_0 == $past(~PB)
    );

    // PB_sync_1 follows PB_sync_0 by 1 cycle
    check_sync1_tracks_sync0: assert property (
        @(posedge clk) disable iff ($initstate) PB_sync_1 == $past(PB_sync_0)
    );

    // PB_idle is exactly (PB_state == PB_sync_1)
    check_idle_definition: assert property (
        @(posedge clk) disable iff ($initstate) PB_idle == (PB_state == PB_sync_1)
    );

    // PB_cnt_max is the AND-reduction of PB_cnt
    check_cntmax_definition: assert property (
        @(posedge clk) disable iff ($initstate) PB_cnt_max == (&PB_cnt)
    );

    // If idle last cycle, counter is 0 now
    check_cnt_resets_when_idle_prev: assert property (
        @(posedge clk) disable iff ($initstate) $past(PB_idle) |-> (PB_cnt == 16'd0)
    );

    // If active last cycle, counter increments by 1 now (with wrap)
    check_cnt_increments_when_active_prev: assert property (
        @(posedge clk) disable iff ($initstate) $past(!PB_idle) |-> (PB_cnt == $past(PB_cnt) + 16'd1)
    );

    // PB_state only changes when active and counter was max last cycle
    check_state_changes_only_on_max: assert property (
        @(posedge clk) disable iff ($initstate) $changed(PB_state) |-> $past(!PB_idle & PB_cnt_max)
    );

    // When active and counter was max last cycle, PB_state toggles
    check_state_changes_when_required: assert property (
        @(posedge clk) disable iff ($initstate) $past(!PB_idle & PB_cnt_max) |-> (PB_state == ~$past(PB_state))
    );

    // PB_down is exactly asserted when not idle, cnt max, and state low
    check_pb_down_definition: assert property (
        @(posedge clk) disable iff ($initstate) PB_down == (~PB_idle & PB_cnt_max & ~PB_state)
    );

    // PB_up is exactly asserted when not idle, cnt max, and state high
    check_pb_up_definition: assert property (
        @(posedge clk) disable iff ($initstate) PB_up == (~PB_idle & PB_cnt_max & PB_state)
    );

    // PB_down implies PB_up is LOW in the same cycle
    check_down_implies_not_up: assert property (
        @(posedge clk) disable iff ($initstate) PB_down |-> !PB_up
    );

    // PB_up implies PB_down is LOW in the same cycle
    check_up_implies_not_down: assert property (
        @(posedge clk) disable iff ($initstate) PB_up |-> !PB_down
    );

    // PB_down is a single-cycle pulse
    check_pb_down_single_cycle: assert property (
        @(posedge clk) disable iff ($initstate) PB_down |-> ##1 !PB_down
    );

    // PB_up is a single-cycle pulse
    check_pb_up_single_cycle: assert property (
        @(posedge clk) disable iff ($initstate) PB_up |-> ##1 !PB_up
    );
endmodule

rtl:
module clock_inverter(
    input wire clk,
    output reg Y
);

    // Inputs are registered
    reg Y_internal = ~clk;

    always @(posedge clk) begin
        Y <= Y_internal;
    end

endmodule

sva:
module clock_inverter_sva (
    input logic clk,
    input logic Y,
    input logic Y_internal
);
    // On each rising edge after the first sample, Y equals the previous value of Y_internal.
    check_y_tracks_prev_y_internal: assert property (
        @(posedge clk) $past(1'b1) |-> (Y == $past(Y_internal))
    );

    // Y_internal never changes after its initial assignment.
    check_y_internal_stable: assert property (
        @(posedge clk) $past(1'b1) |-> $stable(Y_internal)
    );

    // If Y changed since the last sample, its new value equals the previous Y_internal.
    check_y_change_implies_prev_y_internal: assert property (
        @(posedge clk) $changed(Y) |-> (Y == $past(Y_internal))
    );

    // If Y_internal is stable over a cycle, then Y is stable on the next cycle.
    check_y_stable_when_y_internal_stable: assert property (
        @(posedge clk) ($past(1'b1) && $stable(Y_internal)) |-> ##1 (Y == $past(Y))
    );
endmodule

rtl:
module clock_gate_64bit_reg (
  input CLK,
  input EN,
  input TE,
  output reg ENCLK
);

  localparam TLATNTSCAX2TS = 0;

  always @(posedge CLK) begin
    if (EN & ~TE) begin
      ENCLK <= 1;
    end else begin
      ENCLK <= 0;
    end
  end

endmodule

sva:
module clock_gate_64bit_reg_sva (
    input logic CLK,
    input logic EN,
    input logic TE,
    input logic ENCLK
);
    // Clock: CLK (posedge). No reset in RTL.
    // Behavior: At each posedge, ENCLK <= (EN & ~TE).

    // EN && !TE drives ENCLK HIGH on the next clock.
    check_next_high_when_en_and_not_te: assert property (
        @(posedge CLK) disable iff ($initstate) (EN && !TE) |=> (ENCLK == 1'b1)
    );

    // TE HIGH forces ENCLK LOW on the next clock.
    check_next_low_when_te_high: assert property (
        @(posedge CLK) disable iff ($initstate) (TE) |=> (ENCLK == 1'b0)
    );

    // EN LOW forces ENCLK LOW on the next clock.
    check_next_low_when_en_low: assert property (
        @(posedge CLK) disable iff ($initstate) (!EN) |=> (ENCLK == 1'b0)
    );

    // ENCLK equals prior cycle's (EN & ~TE).
    check_matches_past_inputs: assert property (
        @(posedge CLK) disable iff ($initstate) ENCLK == ($past(EN) & ~ $past(TE))
    );

    // Rising EN with TE LOW sets ENCLK HIGH on the next clock.
    check_en_rise_effect_when_te_low: assert property (
        @(posedge CLK) disable iff ($initstate) ($rose(EN) && !TE) |=> (ENCLK == 1'b1)
    );

    // Falling EN with TE LOW sets ENCLK LOW on the next clock.
    check_en_fall_effect_when_te_low: assert property (
        @(posedge CLK) disable iff ($initstate) ($fell(EN) && !TE) |=> (ENCLK == 1'b0)
    );
endmodule

module karnaugh_map_sva (
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic F
);
    ///// Functional equivalence /////
    // F equals B^C^D when sampled on A rising edge.
    check_func_on_A_edge: assert property (
        @(posedge A) F == (B ^ C ^ D)
    );
    // F equals B^C^D when sampled on B rising edge.
    check_func_on_B_edge: assert property (
        @(posedge B) F == (B ^ C ^ D)
    );
    // F equals B^C^D when sampled on C rising edge.
    check_func_on_C_edge: assert property (
        @(posedge C) F == (B ^ C ^ D)
    );
    // F equals B^C^D when sampled on D rising edge.
    check_func_on_D_edge: assert property (
        @(posedge D) F == (B ^ C ^ D)
    );

    ///// Truth table by B,C, D (independent of A) /////
    // For BCD=000, F must be 0.
    truth_table_bcd_000: assert property (
        @(posedge A) ({B,C,D} == 3'b000) |-> (F == 1'b0)
    );
    // For BCD=001, F must be 1.
    truth_table_bcd_001: assert property (
        @(posedge A) ({B,C,D} == 3'b001) |-> (F == 1'b1)
    );
    // For BCD=010, F must be 1.
    truth_table_bcd_010: assert property (
        @(posedge A) ({B,C,D} == 3'b010) |-> (F == 1'b1)
    );
    // For BCD=011, F must be 0.
    truth_table_bcd_011: assert property (
        @(posedge A) ({B,C,D} == 3'b011) |-> (F == 1'b0)
    );
    // For BCD=100, F must be 1.
    truth_table_bcd_100: assert property (
        @(posedge A) ({B,C,D} == 3'b100) |-> (F == 1'b1)
    );
    // For BCD=101, F must be 0.
    truth_table_bcd_101: assert property (
        @(posedge A) ({B,C,D} == 3'b101) |-> (F == 1'b0)
    );
    // For BCD=110, F must be 0.
    truth_table_bcd_110: assert property (
        @(posedge A) ({B,C,D} == 3'b110) |-> (F == 1'b0)
    );
    // For BCD=111, F must be 1.
    truth_table_bcd_111: assert property (
        @(posedge A) ({B,C,D} == 3'b111) |-> (F == 1'b1)
    );
endmodule

