endmodule

sva:
module sky130_fd_sc_ms__einvp_sva (
    input logic clk, // external verification clock
    input logic Z,   // DUT output
    input logic A,   // DUT input
    input logic TE   // DUT input (enable, active-high)
);
    // No reset in DUT; assertions are always active (disable iff (1'b0)).
    // DUT is combinational tri-state inverter: TE=1 => Z=~A; TE=0 => Z='z.

    // When enabled, Z equals bitwise inversion of A.
    check_inversion_when_enabled: assert property (
        @(posedge clk) disable iff (1'b0) (TE === 1'b1) |-> (Z === ~A)
    );

    // When disabled, Z is high-impedance.
    check_highz_when_disabled: assert property (
        @(posedge clk) disable iff (1'b0) (TE === 1'b0) |-> (Z === 1'bz)
    );

    // When enabled, Z is never high-impedance.
    check_not_z_when_enabled: assert property (
        @(posedge clk) disable iff (1'b0) (TE === 1'b1) |-> (Z !== 1'bz)
    );

    // When enabled and A=0, Z must be 1.
    check_drive_one_when_A0: assert property (
        @(posedge clk) disable iff (1'b0) (TE === 1'b1 && A === 1'b0) |-> (Z === 1'b1)
    );

    // When enabled and A=1, Z must be 0.
    check_drive_zero_when_A1: assert property (
        @(posedge clk) disable iff (1'b0) (TE === 1'b1 && A === 1'b1) |-> (Z === 1'b0)
    );

    // If enabled across cycles and A is stable, Z remains stable.
    check_stability_when_enabled_and_A_stable: assert property (
        @(posedge clk) disable iff (1'b0) (TE === 1'b1 && $past(TE) === 1'b1 && (A === $past(A))) |-> (Z === $past(Z))
    );
endmodule

rtl:
module and_gate_16bit(
    input [15:0] a,
    input [15:0] b,
    output [15:0] out
);

    assign out = a & b;

endmodule



module top_module(
    input [31:0] a,
    input [31:0] b,
    input op,
    output [31:0] result
);

    wire [15:0] and_out1, and_out2;

    and_gate_16bit and1(
        .a(a[15:0]),
        .b(b[15:0]),
        .out(and_out1)
    );

    and_gate_16bit and2(
        .a(a[31:16]),
        .b(b[31:16]),
        .out(and_out2)
    );

    wire [31:0] and_combined = {and_out2, and_out1};

    assign result = (op == 0) ? (a & b) : and_combined;

endmodule

sva:
module top_module_sva (
    input logic CLK,
    input logic RESETn,
    input logic [31:0] a,
    input logic [31:0] b,
    input logic op,
    input logic [31:0] result
);
    // DUT has no clock/reset; pure combinational. Sample on CLK, gate with active-low RESETn.
    // op==0 path: result equals a & b.
    check_op0_behavior: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (op == 1'b0) |-> (result == (a & b))
    );
    // op==1 path: result equals concatenation of 16-bit ANDs.
    check_op1_behavior: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (op == 1'b1) |-> (result == { (a[31:16] & b[31:16]), (a[15:0] & b[15:0]) })
    );
    // Result always equals full 32-bit AND of a and b.
    check_result_matches_full_and: assert property (
        @(posedge CLK) disable iff (!RESETn)
        result == (a & b)
    );
    // Lower 16 bits of result match a[15:0] & b[15:0].
    check_lower_half: assert property (
        @(posedge CLK) disable iff (!RESETn)
        result[15:0] == (a[15:0] & b[15:0])
    );
    // Upper 16 bits of result match a[31:16] & b[31:16].
    check_upper_half: assert property (
        @(posedge CLK) disable iff (!RESETn)
        result[31:16] == (a[31:16] & b[31:16])
    );
    // No result bit may be 1 where a has 0.
    check_mask_a_zero_forces_result_zero: assert property (
        @(posedge CLK) disable iff (!RESETn)
        ((result & ~a) == 32'h0)
    );
    // No result bit may be 1 where b has 0.
    check_mask_b_zero_forces_result_zero: assert property (
        @(posedge CLK) disable iff (!RESETn)
        ((result & ~b) == 32'h0)
    );
    // If both a and b bits are 1, result bit must be 1.
    check_both_one_implies_result_one: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (((a & b) & ~result) == 32'h0)
    );
    // If a, b, and op are stable, result must be stable.
    check_stability_when_inputs_stable: assert property (
        @(posedge CLK) disable iff (!RESETn)
        $stable(a) && $stable(b) && $stable(op) |-> $stable(result)
    );
    // Changing op alone does not change result (both paths are equivalent).
    check_op_change_no_effect: assert property (
        @(posedge CLK) disable iff (!RESETn)
        $changed(op) && $stable(a) && $stable(b) |-> $stable(result)
    );
endmodule

rtl:
module d_ff_en_parameterized #(parameter WIDTH = 32) (
    input [WIDTH-1:0] D,
    input CLK,
    input FSM_sequential_state_reg_reg_1,
    input FSM_sequential_state_reg_reg_2,
    output [WIDTH-1:0] Q
);

reg [WIDTH-1:0] Q_reg;

always @(posedge CLK) begin
    if (FSM_sequential_state_reg_reg_1) begin
        Q_reg <= 0;
    end else if (FSM_sequential_state_reg_reg_2) begin
        Q_reg <= D;
    end
end

assign Q = Q_reg;

endmodule

sva:
module d_ff_en_parameterized_sva #(parameter WIDTH = 32) (
    input  logic [WIDTH-1:0] D,
    input  logic             CLK,
    input  logic             FSM_sequential_state_reg_reg_1,
    input  logic             FSM_sequential_state_reg_reg_2,
    input  logic [WIDTH-1:0] Q
);

    // When clear is asserted, Q becomes zero on the next clock.
    check_sync_clear_next: assert property (
        @(posedge CLK) FSM_sequential_state_reg_reg_1 |=> (Q == {WIDTH{1'b0}})
    );

    // When both clear and enable are high, clear dominates and Q becomes zero next cycle.
    check_clear_over_enable_priority: assert property (
        @(posedge CLK) (FSM_sequential_state_reg_reg_1 && FSM_sequential_state_reg_reg_2) |=> (Q == {WIDTH{1'b0}})
    );

    // When enable is high and clear is low, Q loads D sampled in the same cycle (observed next cycle).
    property load_on_enable_no_clear;
        logic [WIDTH-1:0] d_samp;
        @(posedge CLK) (!FSM_sequential_state_reg_reg_1 && FSM_sequential_state_reg_reg_2, d_samp = D) |=> (Q == d_samp);
    endproperty
    check_load_on_enable_no_clear: assert property (load_on_enable_no_clear);

    // When both clear and enable are low, Q holds its value across the next cycle.
    check_hold_when_idle: assert property (
        @(posedge CLK) (!FSM_sequential_state_reg_reg_1 && !FSM_sequential_state_reg_reg_2) |-> $stable(Q)
    );

    // Q only changes value across cycles if either clear or enable was asserted in the prior cycle.
    check_update_only_with_control: assert property (
        @(posedge CLK) (Q != $past(Q)) |-> ($past(FSM_sequential_state_reg_reg_1) || ($past(FSM_sequential_state_reg_reg_2) && !$past(FSM_sequential_state_reg_reg_1)))
    );

    // After a load (enable without clear), if controls go idle next cycle, Q equals the loaded D.
    property hold_loaded_value_when_idle_next;
        logic [WIDTH-1:0] d_samp2;
        @(posedge CLK) (!FSM_sequential_state_reg_reg_1 && FSM_sequential_state_reg_reg_2, d_samp2 = D) ##1
                       (!FSM_sequential_state_reg_reg_1 && !FSM_sequential_state_reg_reg_2) |-> (Q == d_samp2);
    endproperty
    check_hold_loaded_value_when_idle_next: assert property (hold_loaded_value_when_idle_next);

endmodule

