module combinational_circuit (
    input [1:0] A1A2,
    input [1:0] B1B2,
    input [1:0] C1C2,
    output Y
);

    assign Y = (A1A2 & B1B2) | (~C1C2);

endmodule

sva:
module combinational_circuit_sva (
    input logic CLK,
    input logic RESETn,
    input logic [1:0] A1A2,
    input logic [1:0] B1B2,
    input logic [1:0] C1C2,
    input logic Y
);
    // Y equals (A0 & B0) | ~C0 (LSB function as coded).
    check_y_function: assert property (
        @(posedge CLK) disable iff (!RESETn) Y == ((A1A2[0] & B1B2[0]) | (~(C1C2[0])))
    );

    // C0=0 forces Y=1 regardless of A0,B0.
    check_c0_low_forces_y1: assert property (
        @(posedge CLK) disable iff (!RESETn) (C1C2[0] == 1'b0) |-> (Y == 1'b1)
    );

    // With C0=1, Y reduces to A0 & B0.
    check_c0_high_reduces_to_and: assert property (
        @(posedge CLK) disable iff (!RESETn) (C1C2[0] == 1'b1) |-> (Y == (A1A2[0] & B1B2[0]))
    );

    // A0 & B0 = 1 guarantees Y=1.
    check_and1_implies_y1: assert property (
        @(posedge CLK) disable iff (!RESETn) ((A1A2[0] & B1B2[0]) == 1'b1) |-> (Y == 1'b1)
    );

    // If C0=1 and A0 & B0 = 0, then Y=0.
    check_c1_and_and0_implies_y0: assert property (
        @(posedge CLK) disable iff (!RESETn) ((C1C2[0] == 1'b1) && ((A1A2[0] & B1B2[0]) == 1'b0)) |-> (Y == 1'b0)
    );

    // Y=0 only when C0=1 and A0 & B0 = 0.
    check_y0_only_under_conditions: assert property (
        @(posedge CLK) disable iff (!RESETn) (Y == 1'b0) |-> ((C1C2[0] == 1'b1) && ((A1A2[0] & B1B2[0]) == 1'b0))
    );

    // Y=1 implies either A0 & B0 = 1 or C0=0.
    check_y1_implies_conditions: assert property (
        @(posedge CLK) disable iff (!RESETn) (Y == 1'b1) |-> (((A1A2[0] & B1B2[0]) == 1'b1) || (C1C2[0] == 1'b0))
    );

    // If LSBs are stable across a cycle, Y must be stable.
    check_lsb_stable_implies_y_stable: assert property (
        @(posedge CLK) disable iff (!RESETn) ($stable(A1A2[0]) && $stable(B1B2[0]) && $stable(C1C2[0])) |-> $stable(Y)
    );

    // If Y changes, at least one LSB input bit changed.
    check_y_change_implies_lsb_change: assert property (
        @(posedge CLK) disable iff (!RESETn) $changed(Y) |-> ($changed(A1A2[0]) || $changed(B1B2[0]) || $changed(C1C2[0]))
    );

    // When A0 & B0 = 0, Y reduces to ~C0.
    check_and0_reduces_to_not_c0: assert property (
        @(posedge CLK) disable iff (!RESETn) ((A1A2[0] & B1B2[0]) == 1'b0) |-> (Y == (~(C1C2[0])))
    );
endmodule

rtl:
module comparator (
    input [1:0] A,
    input [1:0] B,
    output reg [1:0] out
);
    always @(*) begin
        if (A > B) begin
            out <= 2'b01;
        end else if (A < B) begin
            out <= 2'b10;
        end else begin
            out <= 2'b00;
        end
    end
endmodule

module subtractor (
    input [1:0] A,
    input [1:0] B,
    output reg [2:0] out
);
    wire [1:0] A_comp;
    assign A_comp = ~A + 2'b1;

    always @(*) begin
        out[2] = 0;
        if (A < B) begin
            out[2] = 1;
            out[1:0] = A_comp + B;
        end else begin
            out[1:0] = A - B;
        end
    end
endmodule

module top_module (
    input [1:0] A,
    input [1:0] B,
    output reg [2:0] out
);
    wire [1:0] comp_out;
    wire [2:0] sub_out;

    comparator comp(
        .A(A), 
        .B(B), 
        .out(comp_out)
    );

    subtractor sub(
        .A(A), 
        .B(B), 
        .out(sub_out)
    );

    always @(*) begin
        if (sub_out[2] == 1) begin
            out = ~sub_out[1:0] + 3'b001;
        end else begin
            out = sub_out;
        end
    end
endmodule

sva:
module top_module_sva (
    input logic CLK,
    input logic [1:0] A,
    input logic [1:0] B,
    input logic [2:0] out
);
    // out MSB is always 0 (result range is 0..3).
    check_out_msb_zero: assert property (
        @(posedge CLK) out[2] == 1'b0
    );

    // Lower two bits equal (A - B) modulo 4.
    check_out_lowerbits_moddiff: assert property (
        @(posedge CLK) out[1:0] == (A - B)
    );

    // When A == B, output is zero.
    check_equal_inputs_zero_out: assert property (
        @(posedge CLK) (A == B) |-> (out == 3'b000)
    );

    // When A > B, output is the non-wrapped difference.
    check_greater_no_wrap: assert property (
        @(posedge CLK) (A > B) |-> (out == {1'b0, (A - B)})
    );

    // When A < B, wrapped result is non-zero.
    check_less_wrap_nonzero: assert property (
        @(posedge CLK) (A < B) |-> (out[1:0] != 2'b00)
    );

    // When B == 0, output passes through A.
    check_B_zero_passthrough_A: assert property (
        @(posedge CLK) (B == 2'b00) |-> (out == {1'b0, A})
    );

    // When A == 0, output equals (0 - B) modulo 4.
    check_A_zero_wrap_from_B: assert property (
        @(posedge CLK) (A == 2'b00) |-> (out == {1'b0, (2'b00 - B)})
    );

    // When A == 3, output equals (3 - B) modulo 4.
    check_A_max_minus_B: assert property (
        @(posedge CLK) (A == 2'b11) |-> (out == {1'b0, (2'b11 - B)})
    );

    // If inputs are stable cycle-to-cycle, output is stable.
    check_stable_inputs_imply_stable_out: assert property (
        @(posedge CLK) $stable(A) && $stable(B) |-> $stable(out)
    );
endmodule

rtl:
module top_module (
    input [7:0] binary,
    output [7:0] excess128,
    output result
);

    binary_to_excess128 binary_to_excess128_inst (
        .binary(binary),
        .excess128(excess128)
    );

    compare_binary_excess128 compare_binary_excess128_inst (
        .binary(binary),
        .excess128(excess128),
        .result(result)
    );

endmodule

module binary_to_excess128 (
    input [7:0] binary,
    output [7:0] excess128
);

    assign excess128 = binary + 128;

endmodule

module compare_binary_excess128 (
    input [7:0] binary,
    input [7:0] excess128,
    output result
);

    assign result = (binary == excess128);

endmodule

sva:
module top_module_sva (
    input logic [7:0] binary,
    input logic [7:0] excess128,
    input logic       result
);
    // No clock/reset in RTL; pure combinational; assertions use $global_clock.

    ///// binary_to_excess128 mapping /////
    // excess128 equals binary + 8'd128 (mod 256).
    check_excess128_addition: assert property (
        @($global_clock) (excess128 == (binary + 8'd128))
    );

    // Lower 7 bits are unchanged by +128.
    check_excess128_lower_bits_unchanged: assert property (
        @($global_clock) (excess128[6:0] == binary[6:0])
    );

    // MSB is toggled by +128.
    check_excess128_msb_toggled: assert property (
        @($global_clock) (excess128[7] == ~binary[7])
    );

    // Only MSB differs between binary and excess128.
    check_excess128_xor_mask: assert property (
        @($global_clock) ((excess128 ^ binary) == 8'h80)
    );

    // Modular difference is 128.
    check_excess128_minus_binary_128: assert property (
        @($global_clock) ((excess128 - binary) == 8'd128)
    );

    // Adding 128 to excess128 returns binary.
    check_inverse_addition: assert property (
        @($global_clock) (binary == (excess128 + 8'd128))
    );

    ///// compare_binary_excess128 behavior /////
    // result reflects equality of binary and excess128.
    check_compare_function: assert property (
        @($global_clock) (result == (binary == excess128))
    );

    ///// Top-level composition /////
    // Given the mapping, binary and excess128 are never equal.
    check_never_equal: assert property (
        @($global_clock) (binary != excess128)
    );

    // Therefore result is always 0.
    check_result_always_zero: assert property (
        @($global_clock) (result == 1'b0)
    );
endmodule

rtl:
module adder4 #(parameter WIDTH = 4)(
    input [WIDTH-1:0] A,
    input [WIDTH-1:0] B,
    input Cin,
    output [WIDTH-1:0] S,
    output Cout
);

    wire [WIDTH:0] C;

    assign C[0] = Cin;

    genvar i;
    generate
        for (i = 0; i < WIDTH; i = i + 1) begin : adder
            full_adder FA(
                .A(A[i]),
                .B(B[i]),
                .Cin(C[i]),
                .S(S[i]),
                .Cout(C[i+1])
            );
        end
    endgenerate

    assign Cout = C[WIDTH];

endmodule
module full_adder(
    input A,
    input B,
    input Cin,
    output S,
    output Cout
);

    wire w1, w2, w3;

    assign w1 = A ^ B;
    assign w2 = A & B;
    assign w3 = w1 & Cin;
    assign S = w1 ^ Cin;
    assign Cout = w2 | w3;

endmodule

sva:
module adder4_sva #(parameter WIDTH = 4) (
    input logic clk,                 // Sampling clock for assertions (RTL is combinational)
    input logic [WIDTH-1:0] A,
    input logic [WIDTH-1:0] B,
    input logic Cin,
    input logic [WIDTH-1:0] S,
    input logic Cout
);
    ///// Functional equivalence to addition /////
    // {Cout,S} must equal A + B + Cin (properly sized).
    check_sum_matches_addition: assert property (
        @(posedge clk) {Cout, S} == ({1'b0, A} + {1'b0, B} + Cin)
    );

    // S must match the lower WIDTH bits of A + B + Cin.
    check_s_lower_bits_of_sum: assert property (
        @(posedge clk) S == (({1'b0, A} + {1'b0, B} + Cin)[WIDTH-1:0])
    );

    // Cout must equal the carry-out bit of A + B + Cin.
    check_cout_is_carry_out_of_sum: assert property (
        @(posedge clk) Cout == (({1'b0, A} + {1'b0, B} + Cin)[WIDTH])
    );

    ///// Bit-0 behavior /////
    // LSB sum is XOR of A[0], B[0], and Cin.
    check_lsb_sum_logic: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0] ^ Cin)
    );

    ///// Simple corner cases /////
    // If A=0 and B=0, then S equals Cin in bit0 and zeros elsewhere; Cout=0.
    check_zero_plus_zero_case: assert property (
        @(posedge clk) ((A == {WIDTH{1'b0}}) && (B == {WIDTH{1'b0}})) |-> 
                       ((S == {{(WIDTH-1){1'b0}}, Cin}) && (Cout == 1'b0))
    );

    // Adding zero B with Cin=0 passes A through and Cout=0.
    check_add_zero_B_no_cin: assert property (
        @(posedge clk) ((B == {WIDTH{1'b0}}) && (Cin == 1'b0)) |-> 
                       ((S == A) && (Cout == 1'b0))
    );

    // Adding zero A with Cin=0 passes B through and Cout=0.
    check_add_zero_A_no_cin: assert property (
        @(posedge clk) ((A == {WIDTH{1'b0}}) && (Cin == 1'b0)) |-> 
                       ((S == B) && (Cout == 1'b0))
    );

    // Complementary operands with Cin=0 produce all-ones sum and no carry.
    check_complements_no_carry: assert property (
        @(posedge clk) ((B == ~A) && (Cin == 1'b0)) |-> 
                       ((S == {WIDTH{1'b1}}) && (Cout == 1'b0))
    );

    // Complementary operands with Cin=1 produce zero sum and carry=1.
    check_complements_with_carry: assert property (
        @(posedge clk) ((B == ~A) && (Cin == 1'b1)) |-> 
                       ((S == {WIDTH{1'b0}}) && (Cout == 1'b1))
    );

    // All-ones plus all-ones with Cin=1 yields S=all-ones and Cout=1.
    check_all_ones_plus_all_ones_cin1: assert property (
        @(posedge clk) ((A == {WIDTH{1'b1}}) && (B == {WIDTH{1'b1}}) && (Cin == 1'b1)) |-> 
                       ((S == {WIDTH{1'b1}}) && (Cout == 1'b1))
    );

    ///// Stability (combinational behavior) /////
    // If inputs are stable across a cycle, outputs must be stable.
    check_outputs_stable_when_inputs_stable: assert property (
        @(posedge clk) ($stable(A) && $stable(B) && $stable(Cin)) |-> ($stable(S) && $stable(Cout))
    );

    // If LSB inputs are stable across a cycle, S[0] must be stable.
    check_lsb_stable_when_lsb_inputs_stable: assert property (
        @(posedge clk) ($stable(A[0]) && $stable(B[0]) && $stable(Cin)) |-> $stable(S[0])
    );
endmodule

rtl:
module mux_4to1 (
    input [3:0] in,
    input [1:0] sel,
    output reg out
);
    always @ (sel, in) begin
        case (sel)
            2'b00: out <= in[0];
            2'b01: out <= in[1];
            2'b10: out <= in[2];
            2'b11: out <= in[3];
        endcase
    end
endmodule
module dff_8 (
    input clk,
    input reset,
    output reg [7:0] q
);
    always @(posedge clk) begin
        if (reset) begin
            q <= 8'b0;
        end else begin
            q <= 8'b0;
        end
    end
endmodule
module functional_module (
    input [7:0] dff_out,
    input [0:0] mux_out,
    output reg [7:0] q
);
    always @* begin
        q = mux_out + dff_out;
    end
endmodule
module top_module (
    input clk,
    input reset,
    input [3:0] in,
    input [1:0] sel,
    output [7:0] q
);
    wire [0:0] mux_out;

    mux_4to1 mux_inst (
        .in(in),
        .sel(sel),
        .out(mux_out)
    );

    wire [7:0] dff_out;

    dff_8 dff_inst (
        .clk(clk),
        .reset(reset),
        .q(dff_out)
    );

    functional_module func_inst (
        .mux_out(mux_out),
        .dff_out(dff_out),
        .q(q)
    );
endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic reset,
    input logic [3:0] in,
    input logic [1:0] sel,
    input logic [7:0] q
);
    // q equals zero-extended selected input bit.
    check_q_zeroext_selected: assert property (
        @(posedge clk) disable iff (reset) q == {7'b0, in[sel]}
    );

    // Upper bits of q are always zero.
    check_q_upper_bits_zero: assert property (
        @(posedge clk) disable iff (reset) q[7:1] == 7'b0
    );

    // When sel==00, q reflects in[0] in LSB and zeros elsewhere.
    check_sel00_behavior: assert property (
        @(posedge clk) disable iff (reset) (sel == 2'b00) |-> (q == {7'b0, in[0]})
    );

    // When sel==01, q reflects in[1] in LSB and zeros elsewhere.
    check_sel01_behavior: assert property (
        @(posedge clk) disable iff (reset) (sel == 2'b01) |-> (q == {7'b0, in[1]})
    );

    // When sel==10, q reflects in[2] in LSB and zeros elsewhere.
    check_sel10_behavior: assert property (
        @(posedge clk) disable iff (reset) (sel == 2'b10) |-> (q == {7'b0, in[2]})
    );

    // When sel==11, q reflects in[3] in LSB and zeros elsewhere.
    check_sel11_behavior: assert property (
        @(posedge clk) disable iff (reset) (sel == 2'b11) |-> (q == {7'b0, in[3]})
    );

    // If all inputs are zero, q must be zero regardless of sel.
    check_all_inputs_zero: assert property (
        @(posedge clk) disable iff (reset) (in == 4'b0000) |-> (q == 8'h00)
    );

    // If all inputs are one, q must be one regardless of sel.
    check_all_inputs_one: assert property (
        @(posedge clk) disable iff (reset) (in == 4'b1111) |-> (q == 8'h01)
    );

    // q is always either 0 or 1.
    check_q_value_range: assert property (
        @(posedge clk) disable iff (reset) (q inside {8'h00, 8'h01})
    );
endmodule

rtl:
module crc_module (
   // Inputs
   clk,
   // Outputs
   Output
   );

   input clk;
   output reg [8:0] Output;

   integer cyc; initial cyc = 0;
   reg [63:0] crc;
   reg [31:0] sum;

   wire [8:0] Input = crc[8:0];

   always @ (posedge clk) begin
      cyc <= cyc + 1;
      crc <= {crc[62:0], crc[63] ^ crc[2] ^ crc[0]};
      if (cyc==0) begin
         // Setup
         crc <= 64'h5aef0c8d_d70a4497;
         sum <= 32'h0;
      end
      else if (cyc>10 && cyc<90) begin
         sum <= {sum[30:0],sum[31]} ^ {23'h0, crc[8:0]};
      end
      else if (cyc==99) begin
         if (sum == 32'he8bbd130) begin
            Output <= 9'h4a;
         end
         else begin
            Output <= 9'h55;
         end
      end
   end

endmodule

sva:
module crc_module_sva (
    input  logic        clk,
    input  logic [8:0]  Output,
    input  integer      cyc,
    input  logic [63:0] crc,
    input  logic [31:0] sum
);
    // Clock: clk (posedge). No explicit reset; assertions use disable iff (1'b0).
    // Sequential LFSR (crc), accumulator (sum), and conditional Output at cyc==99.

    // cyc increments by 1 every cycle.
    check_cyc_increments: assert property (
        @(posedge clk) disable iff (1'b0) (!$isunknown($past(cyc))) |-> (cyc == $past(cyc) + 1)
    );

    // On cycle after cyc==0, crc is initialized to constant.
    check_crc_init_on_cyc0: assert property (
        @(posedge clk) disable iff (1'b0) (!$isunknown($past(cyc)) && ($past(cyc) == 0)) |-> (crc == 64'h5aef0c8d_d70a4497)
    );

    // On cycle after cyc==0, sum is initialized to 0.
    check_sum_init_on_cyc0: assert property (
        @(posedge clk) disable iff (1'b0) (!$isunknown($past(cyc)) && ($past(cyc) == 0)) |-> (sum == 32'h0)
    );

    // For all cycles except after cyc==0, crc updates via LFSR shift/xor.
    check_crc_lfsr_shift: assert property (
        @(posedge clk) disable iff (1'b0)
            (!$isunknown($past(cyc)) && ($past(cyc) != 0)) |-> (
                crc == { ($past(crc))[62:0], (($past(crc))[63] ^ ($past(crc))[2] ^ ($past(crc))[0]) }
            )
    );

    // When 10 < cyc < 90 (evaluated on previous cycle), sum updates by rotate-left-1 XOR zero-extended crc[8:0].
    check_sum_update_window: assert property (
        @(posedge clk) disable iff (1'b0)
            (!$isunknown($past(cyc)) && ($past(cyc) > 10) && ($past(cyc) < 90)) |-> (
                sum == { ($past(sum))[30:0], ($past(sum))[31] } ^ {23'h0, ($past(crc))[8:0]}
            )
    );

    // Outside the update window (and not after cyc==0), sum holds its previous value.
    check_sum_hold_outside_window: assert property (
        @(posedge clk) disable iff (1'b0)
            (!$isunknown($past(cyc)) && ($past(cyc) != 0) && !(($past(cyc) > 10) && ($past(cyc) < 90))) |-> (
                sum == $past(sum)
            )
    );

    // At cyc==99 (previous cycle), sum is not written and holds.
    check_sum_hold_at_cyc99: assert property (
        @(posedge clk) disable iff (1'b0)
            (!$isunknown($past(cyc)) && ($past(cyc) == 99)) |-> (sum == $past(sum))
    );

    // At cyc==99 with sum == magic, Output is 9'h4a.
    check_output_on_99_matches_sum_true: assert property (
        @(posedge clk) disable iff (1'b0)
            (!$isunknown($past(cyc)) && ($past(cyc) == 99) && ($past(sum) == 32'he8bbd130)) |-> (Output == 9'h4a)
    );

    // At cyc==99 with sum != magic, Output is 9'h55.
    check_output_on_99_matches_sum_false: assert property (
        @(posedge clk) disable iff (1'b0)
            (!$isunknown($past(cyc)) && ($past(cyc) == 99) && ($past(sum) != 32'he8bbd130)) |-> (Output == 9'h55)
    );

    // On all cycles where previous cyc != 99, Output does not change.
    check_output_stable_when_not_99: assert property (
        @(posedge clk) disable iff (1'b0)
            (!$isunknown($past(cyc)) && ($past(cyc) != 99)) |-> (Output === $past(Output))
    );

    // On the cycle after cyc==99, Output is one of the two defined values.
    check_output_values_on_99: assert property (
        @(posedge clk) disable iff (1'b0)
            (!$isunknown($past(cyc)) && ($past(cyc) == 99)) |-> (Output inside {9'h4a, 9'h55})
    );

endmodule

rtl:
module binary_counter (
    input clock,
    output reg [3:0] q
);

    always @(posedge clock) begin
        if (q == 4'b1111) begin
            q <= 4'b0000;
        end else begin
            q <= q + 1;
        end
    end

endmodule

sva:
module binary_counter_sva (
    input logic clock,
    input logic [3:0] q
);
    // Clock: clock (posedge). No reset. Sequential 4-bit up-counter with wrap to 0 at 15.

    // When q is 15, next value must be 0.
    check_wrap_on_max: assert property (
        @(posedge clock) (q == 4'hF) |=> (q == 4'h0)
    );

    // When q is not 15, next value increments by 1.
    check_increment_when_not_max: assert property (
        @(posedge clock) (q != 4'hF) |=> (q == $past(q) + 4'd1)
    );

    // q must change every cycle (no stutter).
    check_no_stutter: assert property (
        @(posedge clock) 1'b1 |=> (q != $past(q))
    );

    // LSB toggles every cycle.
    check_lsb_toggles: assert property (
        @(posedge clock) 1'b1 |=> (q[0] != $past(q[0]))
    );

    // Bit1 updates with carry from bit0: next q[1] = past q[1] XOR past q[0].
    check_bit1_updates_with_carry: assert property (
        @(posedge clock) 1'b1 |=> (q[1] == ($past(q[1]) ^ $past(q[0])))
    );

    // Bit2 updates with carry from bits[1:0]: next q[2] = past q[2] XOR (past q[1] & past q[0]).
    check_bit2_updates_with_carry: assert property (
        @(posedge clock) 1'b1 |=> (q[2] == ($past(q[2]) ^ ($past(q[1]) & $past(q[0]))))
    );

    // Bit3 updates with carry from bits[2:0]: next q[3] = past q[3] XOR (past q[2] & past q[1] & past q[0]).
    check_bit3_updates_with_carry: assert property (
        @(posedge clock) 1'b1 |=> (q[3] == ($past(q[3]) ^ ($past(q[2]) & $past(q[1]) & $past(q[0]))))
    );

    // After 16 cycles, q returns to its prior value (period 16).
    check_periodicity_16: assert property (
        @(posedge clock) 1'b1 |-> ##16 (q == $past(q,16))
    );

    // If q is 0 now, it must have been 15 in the previous cycle.
    check_zero_preceded_by_max: assert property (
        @(posedge clock) 1'b1 |=> ((q == 4'h0) |-> ($past(q) == 4'hF))
    );

    // After 2 cycles, q advances by +2 modulo 16.
    check_two_cycle_step: assert property (
        @(posedge clock) 1'b1 |-> ##2 (q == (($past(q,2) + 4'd2) & 4'hF))
    );
endmodule

rtl:
module sky130_fd_sc_ms__clkdlyinv3sd2 (
    Y,
    A
);

    output Y;
    input  A;

    wire not0_out_Y;

    not not0 (not0_out_Y, A              );
    buf buf0 (Y         , not0_out_Y     );

endmodule

sva:
module sky130_fd_sc_ms__clkdlyinv3sd2_sva (
    input logic CLK, // Sampling clock for assertions (DUT has no clock/reset)
    input logic A,   // DUT input
    input logic Y    // DUT output
);
    // Y must be the bitwise inversion of A at every sample.
    check_y_is_invert_of_a: assert property (
        @(posedge CLK) (Y === ~A)
    );

    // A rising edge implies Y falls at the same sample.
    check_rise_a_fall_y: assert property (
        @(posedge CLK) $rose(A) |-> $fell(Y)
    );

    // A falling edge implies Y rises at the same sample.
    check_fall_a_rise_y: assert property (
        @(posedge CLK) $fell(A) |-> $rose(Y)
    );

    // If A is stable across a cycle, Y must also be stable.
    check_stability_when_a_stable: assert property (
        @(posedge CLK) $stable(A) |-> $stable(Y)
    );

    // Y cannot change unless A changed in that cycle.
    check_no_spurious_y_changes: assert property (
        @(posedge CLK) $changed(Y) |-> $changed(A)
    );

    // Any change in A must cause a change in Y in that cycle.
    check_a_change_causes_y_change: assert property (
        @(posedge CLK) $changed(A) |-> $changed(Y)
    );
endmodule

module dff_clear_reset_sva (
    input logic clock,
    input logic clr,       // active-low synchronous clear
    input logic clr_val,   // load enable when high and clr is high
    input logic d,
    input logic q
);
    // Clear low drives q to 0 on the next clock.
    check_clear_forces_zero_next: assert property (
        @(posedge clock) (!clr) |=> (q == 1'b0)
    );

    // Clear has priority over load when both are asserted.
    check_clear_priority_over_load: assert property (
        @(posedge clock) (!clr && clr_val) |=> (q == 1'b0)
    );

    // With clr high and clr_val high, q loads d on the next clock.
    check_load_updates_q: assert property (
        @(posedge clock) disable iff ($initstate || !clr) (clr && clr_val) |=> (q == $past(d))
    );

    // With clr high and clr_val low, q holds its value.
    check_hold_when_no_load: assert property (
        @(posedge clock) disable iff ($initstate || !clr) (clr && !clr_val) |=> (q == $past(q))
    );

    // Any change on q must be caused by prior clear or prior load.
    check_q_changes_only_on_clear_or_load: assert property (
        @(posedge clock) disable iff ($initstate) $changed(q) |-> $past((!clr) || (clr && clr_val))
    );

    // After a cycle with clr low, q must be 0 on this cycle.
    check_zero_after_prior_clear: assert property (
        @(posedge clock) disable iff ($initstate) $past(!clr) |-> (q == 1'b0)
    );

    // D changes are ignored when not loading (clr high, clr_val low).
    check_ignore_d_when_no_load: assert property (
        @(posedge clock) disable iff ($initstate || !clr) (!clr_val && $changed(d)) |=> (q == $past(q))
    );

    // Loading the same value leaves q unchanged across the boundary.
    check_load_same_value_no_change: assert property (
        @(posedge clock) disable iff ($initstate || !clr) (clr && clr_val && (d == q)) |=> (q == $past(q))
    );
endmodule

