module my_logic (
    input A1,
    input A2,
    input B1,
    input C1,
    output Y
);

    // Local signals
    wire or0_out;
    wire nand0_out_Y;

    // Components
    or or0 (or0_out, A2, A1);
    nand nand0 (nand0_out_Y, C1, or0_out, B1);
    buf buf0 (Y, nand0_out_Y);

endmodule

sva:
module my_logic_sva (
    input logic clk,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic C1,
    input logic Y
);
    // Y matches NAND of C1, B1, and (A1|A2).
    check_functional_equivalence: assert property (
        @(posedge clk) Y == ~(C1 & B1 & (A1 | A2))
    );

    // If C1 is LOW, Y must be HIGH.
    check_Y_one_if_C1_low: assert property (
        @(posedge clk) (!C1) |-> (Y == 1'b1)
    );

    // If B1 is LOW, Y must be HIGH.
    check_Y_one_if_B1_low: assert property (
        @(posedge clk) (!B1) |-> (Y == 1'b1)
    );

    // If both A1 and A2 are LOW, Y must be HIGH.
    check_Y_one_if_both_A_low: assert property (
        @(posedge clk) (!A1 && !A2) |-> (Y == 1'b1)
    );

    // If C1, B1, and (A1|A2) are HIGH, Y must be LOW.
    check_Y_zero_if_all_high: assert property (
        @(posedge clk) (C1 && B1 && (A1 || A2)) |-> (Y == 1'b0)
    );

    // If Y is LOW, then C1 and B1 are HIGH and (A1|A2) is HIGH.
    check_Y_zero_implies_all_high: assert property (
        @(posedge clk) (Y == 1'b0) |-> (C1 && B1 && (A1 || A2))
    );

    // If Y is HIGH, at least one input to the NAND is effectively LOW.
    check_Y_one_implies_not_all_high: assert property (
        @(posedge clk) (Y == 1'b1) |-> (!C1 || !B1 || (!A1 && !A2))
    );

    // When C1 and B1 are HIGH, Y equals NOT(A1|A2).
    check_Y_when_C1_B1_high: assert property (
        @(posedge clk) (C1 && B1) |-> (Y == ~(A1 | A2))
    );

    // When C1 and (A1|A2) are HIGH, Y equals NOT(B1).
    check_Y_when_C1_and_orA_high: assert property (
        @(posedge clk) (C1 && (A1 || A2)) |-> (Y == ~B1)
    );

    // When B1 and (A1|A2) are HIGH, Y equals NOT(C1).
    check_Y_when_B1_and_orA_high: assert property (
        @(posedge clk) (B1 && (A1 || A2)) |-> (Y == ~C1)
    );
endmodule

rtl:
module counter(clk, rst, up_down, enable, count);

    input clk;
    input rst;
    input up_down;
    input enable;
    output reg [3:0] count;

    always @(posedge clk) begin
        if (rst) begin
            count <= 4'b0;
        end
        else if (enable) begin
            if (up_down) begin
                count <= count + 1;
            end
            else begin
                count <= count - 1;
            end
        end
    end

endmodule

sva:
module counter_sva (
    input logic clk,
    input logic rst,
    input logic up_down,
    input logic enable,
    input logic [3:0] count
);
    // Clock: clk (posedge). Reset: rst (synchronous, active-high). Logic: sequential up/down counter.

    // Reset drives count to zero on the following clock.
    reset_clears_next: assert property (
        @(posedge clk) rst |=> (count == 4'd0)
    );

    // While reset stays asserted across cycles, count remains zero.
    hold_zero_while_reset: assert property (
        @(posedge clk) rst && $past(rst,1,1'b0) |-> (count == 4'd0)
    );

    // With enable=0 (not in reset), count holds its value to the next cycle.
    hold_when_disabled: assert property (
        @(posedge clk) disable iff (rst) (!enable) |=> $stable(count)
    );

    // With enable=1 and up_down=1, count increments by 1 modulo 16 on next cycle.
    increment_when_up: assert property (
        @(posedge clk) disable iff (rst) (enable && up_down) |=> (count == (($past(count,1,4'd0) + 4'd1) & 4'hF))
    );

    // With enable=1 and up_down=0, count decrements by 1 modulo 16 on next cycle.
    decrement_when_down: assert property (
        @(posedge clk) disable iff (rst) (enable && !up_down) |=> (count == (($past(count,1,4'd0) - 4'd1) & 4'hF))
    );

    // With enable=1 (not in reset), count must change on the next cycle.
    change_when_enabled: assert property (
        @(posedge clk) disable iff (rst) (enable) |=> !$stable(count)
    );

    // If count changes (not in reset), enable must have been 1 in the previous cycle.
    change_implies_enable_prev: assert property (
        @(posedge clk) disable iff (rst) (count != $past(count,1,4'd0)) |-> $past(enable,1,1'b0)
    );

    // With enable=1, next value is either +1 or -1 modulo 16.
    next_is_pm1_when_enabled: assert property (
        @(posedge clk) disable iff (rst) (enable) |=> (
            (count == (($past(count,1,4'd0) + 4'd1) & 4'hF)) ||
            (count == (($past(count,1,4'd0) - 4'd1) & 4'hF))
        )
    );

endmodule

rtl:
module calculator(
  input clk,
  input reset,
  input [7:0] A,
  input [7:0] B,
  input [2:0] op,
  output reg [15:0] out
);

  always @(posedge clk) begin
    if(reset) begin
      out <= 16'h0000;
    end
    else begin
      case(op)
        3'b000: out <= A + B;
        3'b001: out <= A - B;
        3'b010: out <= A * B;
        3'b011: out <= A / B;
        default: out <= 16'h0000;
      endcase
    end
  end
endmodule

sva:
module calculator_sva (
    input logic clk,
    input logic reset,
    input logic [7:0] A,
    input logic [7:0] B,
    input logic [2:0] op,
    input logic [15:0] out
);
    ///// Reset behavior /////
    // On reset, out must be cleared to 0.
    check_reset_clears_out: assert property (
        @(posedge clk) reset |-> (out == 16'h0000)
    );

    ///// Operation decoding /////
    // When op==000 (ADD) and not in reset, out equals A + B.
    check_add_output: assert property (
        @(posedge clk) disable iff (reset) (op == 3'b000) |-> (out == (A + B))
    );
    // When op==001 (SUB) and not in reset, out equals A - B.
    check_sub_output: assert property (
        @(posedge clk) disable iff (reset) (op == 3'b001) |-> (out == (A - B))
    );
    // When op==010 (MUL) and not in reset, out equals A * B.
    check_mul_output: assert property (
        @(posedge clk) disable iff (reset) (op == 3'b010) |-> (out == (A * B))
    );
    // When op==011 (DIV) with B!=0 and not in reset, out equals A / B.
    check_div_output_when_B_nonzero: assert property (
        @(posedge clk) disable iff (reset) (op == 3'b011 && B != 8'h00) |-> (out == (A / B))
    );
    // For any undefined op (100,101,110,111) and not in reset, out must be 0.
    check_default_zero: assert property (
        @(posedge clk) disable iff (reset) (op inside {3'b100,3'b101,3'b110,3'b111}) |-> (out == 16'h0000)
    );

    ///// Functional consistency /////
    // If inputs (A,B,op) are stable and not dividing by zero, out remains stable.
    check_stable_when_inputs_stable: assert property (
        @(posedge clk) disable iff (reset)
            $stable({A,B,op}) && !(op == 3'b011 && B == 8'h00) |-> $stable(out)
    );
endmodule

rtl:
module four_bit_adder(
  input [3:0] A,
  input [3:0] B,
  input Cin,
  output [3:0] S,
  output Cout
);

  reg [3:0] S;
  reg Cout;

  always @(*) begin
    {Cout, S} = A + B + Cin;
  end

endmodule

sva:
module four_bit_adder_sva (
    input logic CLK,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic Cin,
    input logic [3:0] S,
    input logic Cout
);
    // Outputs equal full 5-bit sum of inputs.
    check_sum_full: assert property (
        @(posedge CLK) {Cout, S} == (A + B + Cin)
    );

    // Lower 4 bits of sum match S.
    check_sum_lower_bits: assert property (
        @(posedge CLK) S == (A + B + Cin)[3:0]
    );

    // Carry-out is the overflow of 4-bit addition.
    check_cout_overflow_flag: assert property (
        @(posedge CLK) Cout == ((A + B + Cin) > 4'hF)
    );

    // LSB sum bit is XOR of inputs.
    check_s0_xor: assert property (
        @(posedge CLK) S[0] == (A[0] ^ B[0] ^ Cin)
    );

    // S[1] uses carry from bit0.
    check_s1_with_c1: assert property (
        @(posedge CLK) S[1] == (A[1] ^ B[1] ^ ((A[0] & B[0]) | ((A[0] ^ B[0]) & Cin)))
    );

    // S[2] uses carry from bit1 which depends on bit0.
    check_s2_with_c2: assert property (
        @(posedge CLK) S[2] == (A[2] ^ B[2] ^ (
            (A[1] & B[1]) | ((A[1] ^ B[1]) & ((A[0] & B[0]) | ((A[0] ^ B[0]) & Cin)))
        ))
    );

    // S[3] uses carry from bit2 which depends on lower bits.
    check_s3_with_c3: assert property (
        @(posedge CLK) S[3] == (A[3] ^ B[3] ^ (
            (A[2] & B[2]) | ((A[2] ^ B[2]) & (
                (A[1] & B[1]) | ((A[1] ^ B[1]) & ((A[0] & B[0]) | ((A[0] ^ B[0]) & Cin)))
            ))
        ))
    );

    // Cout equals carry out of bit3 from full carry chain.
    check_cout_from_c4: assert property (
        @(posedge CLK) Cout == (
            (A[3] & B[3]) | ((A[3] ^ B[3]) & (
                (A[2] & B[2]) | ((A[2] ^ B[2]) & (
                    (A[1] & B[1]) | ((A[1] ^ B[1]) & (
                        (A[0] & B[0]) | ((A[0] ^ B[0]) & Cin)
                    ))
                ))
            ))
        )
    );

    // If inputs do not change between cycles, outputs do not change.
    check_stability_when_inputs_stable: assert property (
        @(posedge CLK) ((A == $past(A)) && (B == $past(B)) && (Cin == $past(Cin)))
        |-> ((S == $past(S)) && (Cout == $past(Cout)))
    );

    // Zero inputs produce zero sum and no carry.
    check_zero_case: assert property (
        @(posedge CLK) ((A == 4'b0000) && (B == 4'b0000) && (Cin == 1'b0))
        |-> ((S == 4'b0000) && (Cout == 1'b0))
    );

    // Max inputs with Cin=1 saturate S and set Cout.
    check_max_case: assert property (
        @(posedge CLK) ((A == 4'hF) && (B == 4'hF) && (Cin == 1'b1))
        |-> ((S == 4'hF) && (Cout == 1'b1))
    );

    // With Cin=0, outputs equal A+B.
    check_cin_zero_sum: assert property (
        @(posedge CLK) (Cin == 1'b0) |-> ({Cout, S} == (A + B))
    );

    // With Cin=1, outputs equal A+B+1.
    check_cin_one_sum: assert property (
        @(posedge CLK) (Cin == 1'b1) |-> ({Cout, S} == (A + B + 1'b1))
    );
endmodule

rtl:
module behavioral(out, a, b, e, w);

input a, b, e, w;
output out;

reg out;

always @ (*)
begin
    if (~a & ~b & ~e & ~w)
        out = 1'b1;

    else if (~a & ~b & ~e & w)
        out = 1'b1;

    else if (~a & ~b & e & ~w)
        out = 1'b1;

    else if (~a & ~b & e & w)
        out = 1'b1;

    else if (~a & b & ~e & ~w)
        out = 1'b0;

    else if (~a & b & ~e & w)
        out = 1'b0;

    else if (~a & b & e & ~w)
        out = 1'b0;

    else if (~a & b & e & w)
        out = 1'b0;

    else if (a & ~b & ~e & ~w)
        out = 1'b0;

    else if (a & ~b & ~e & w)
        out = 1'b0;

    else if (a & ~b & e & ~w)
        out = 1'b0;

    else if (a & ~b & e & w)
        out = 1'b0;

    else if (a & b & ~e & ~w)
        out = 1'b0;

    else if (a & b & ~e & w)
        out = 1'b0;

    else if (a & b & e & ~w)
        out = 1'b0;

    else if (a & b & e & w)
        out = 1'b0;

    else
        out = 1'bx;
end

endmodule

sva:
module behavioral_sva (
    input logic clk,     // sampling clock for SVA (RTL has no clock/reset)
    input logic out,
    input logic a,
    input logic b,
    input logic e,
    input logic w
);
    // RTL is purely combinational; out implements (~a & ~b), e/w are don't-cares.

    // out must equal (~a & ~b) every cycle.
    check_function_equivalence: assert property (
        @(posedge clk) out == ((~a) & (~b))
    );

    // When a=0 and b=0, out must be 1.
    check_out_high_when_a0_b0: assert property (
        @(posedge clk) (!a && !b) |-> (out == 1'b1)
    );

    // When a=1 and b=0, out must be 0.
    check_out_low_when_a1_b0: assert property (
        @(posedge clk) (a && !b) |-> (out == 1'b0)
    );

    // When a=0 and b=1, out must be 0.
    check_out_low_when_a0_b1: assert property (
        @(posedge clk) (!a && b) |-> (out == 1'b0)
    );

    // When a=1 and b=1, out must be 0.
    check_out_low_when_a1_b1: assert property (
        @(posedge clk) (a && b) |-> (out == 1'b0)
    );

    // Enumerated case: ~a & ~b & ~e & ~w -> out=1.
    check_case_a0_b0_e0_w0: assert property (
        @(posedge clk) (!a && !b && !e && !w) |-> (out == 1'b1)
    );

    // Enumerated case: ~a & ~b & e & w -> out=1.
    check_case_a0_b0_e1_w1: assert property (
        @(posedge clk) (!a && !b && e && w) |-> (out == 1'b1)
    );

    // Enumerated case: ~a & b & e & w -> out=0.
    check_case_a0_b1_e1_w1: assert property (
        @(posedge clk) (!a && b && e && w) |-> (out == 1'b0)
    );

    // Enumerated case: a & ~b & e & w -> out=0.
    check_case_a1_b0_e1_w1: assert property (
        @(posedge clk) (a && !b && e && w) |-> (out == 1'b0)
    );

    // Enumerated case: a & b & e & w -> out=0.
    check_case_a1_b1_e1_w1: assert property (
        @(posedge clk) (a && b && e && w) |-> (out == 1'b0)
    );
endmodule

