sva:
module sky130_fd_sc_hdll__xor3_sva (
    input logic X,
    input logic A,
    input logic B,
    input logic C
);
    // X equals A^B^C when sampled on A's rising edge.
    check_x_eq_parity_on_A: assert property (
        @(posedge A) X == (A ^ B ^ C)
    );

    // X equals A^B^C when sampled on B's rising edge.
    check_x_eq_parity_on_B: assert property (
        @(posedge B) X == (A ^ B ^ C)
    );

    // X equals A^B^C when sampled on C's rising edge.
    check_x_eq_parity_on_C: assert property (
        @(posedge C) X == (A ^ B ^ C)
    );

    // If only A toggles (B,C stable), X must toggle.
    check_single_toggle_A_changes_X: assert property (
        @(posedge A) ($stable(B) && $stable(C)) |-> $changed(X)
    );

    // If only B toggles (A,C stable), X must toggle.
    check_single_toggle_B_changes_X: assert property (
        @(posedge B) ($stable(A) && $stable(C)) |-> $changed(X)
    );

    // If only C toggles (A,B stable), X must toggle.
    check_single_toggle_C_changes_X: assert property (
        @(posedge C) ($stable(A) && $stable(B)) |-> $changed(X)
    );

    // If A and B toggle together (C stable), X must not change.
    check_double_toggle_AB_keeps_X: assert property (
        @(posedge A) ($changed(B) && $stable(C)) |-> !$changed(X)
    );

    // If A and C toggle together (B stable), X must not change.
    check_double_toggle_AC_keeps_X: assert property (
        @(posedge A) ($changed(C) && $stable(B)) |-> !$changed(X)
    );

    // If B and C toggle together (A stable), X must not change.
    check_double_toggle_BC_keeps_X: assert property (
        @(posedge B) ($changed(C) && $stable(A)) |-> !$changed(X)
    );

    // Any change on X must be caused by a change on at least one input.
    check_x_change_requires_input_change: assert property (
        @(posedge A or posedge B or posedge C or posedge X) $changed(X) |-> ($changed(A) || $changed(B) || $changed(C))
    );
endmodule

rtl:
module shift_register (
  input clk,
  input load,
  input [3:0] p,
  output reg [3:0] q,
  output reg [3:0] q_bar
);

  always @(posedge clk) begin
    if (load) begin
      q <= p;
      q_bar <= ~p;
    end else begin
      q <= {q[2:0], 1'b0};
      q_bar <= ~{q[2:0], 1'b0};
    end
  end

endmodule

sva:
module shift_register_sva (
  input logic clk,
  input logic load,
  input logic [3:0] p,
  input logic [3:0] q,
  input logic [3:0] q_bar
);

  // q_bar is always the bitwise inverse of q in the next cycle.
  check_qbar_inverts_q_next: assert property (
    @(posedge clk) 1'b1 |=> (q_bar == ~q)
  );

  // When load is HIGH, next q equals current p.
  check_load_sets_q: assert property (
    @(posedge clk) ($past(1'b1) && load) |=> (q == $past(p))
  );

  // When load is HIGH, next q_bar equals bitwise NOT of current p.
  check_load_sets_qbar: assert property (
    @(posedge clk) ($past(1'b1) && load) |=> (q_bar == ~$past(p))
  );

  // When load is LOW, next q shifts left with zero inserted at LSB.
  check_shift_sets_q: assert property (
    @(posedge clk) ($past(1'b1) && !load) |=> (q == {$past(q)[2:0], 1'b0})
  );

  // When load is LOW, next q_bar equals bitwise NOT of the shifted value.
  check_shift_sets_qbar: assert property (
    @(posedge clk) ($past(1'b1) && !load) |=> (q_bar == ~{$past(q)[2:0], 1'b0})
  );

  // When load is LOW, next q[0] is 0 (zero inserted at LSB).
  check_shift_lsb_zero: assert property (
    @(posedge clk) ($past(1'b1) && !load) |=> (q[0] == 1'b0)
  );

  // When load is LOW, next q[3] equals previous q[2] (left shift).
  check_shift_msb_from_q2: assert property (
    @(posedge clk) ($past(1'b1) && !load) |=> (q[3] == $past(q[2]))
  );

  // When load is LOW, next q[2:1] equals previous q[1:0] (left shift).
  check_shift_middle_bits_from_q10: assert property (
    @(posedge clk) ($past(1'b1) && !load) |=> (q[2:1] == $past(q[1:0]))
  );

endmodule

rtl:
module counter(clk, rst, en, count_out);

input clk, rst, en;
output reg [3:0] count_out;

always @(posedge clk) begin
  if (rst) begin
    count_out <= 4'b0000;
  end
  else if (en) begin
    count_out <= count_out + 1;
  end
end

endmodule

sva:
module counter_sva (
    input logic clk,
    input logic rst,       // active-high synchronous reset
    input logic en,
    input logic [3:0] count_out
);
    // Synchronous reset drives count_out to 0 on the next cycle.
    check_reset_clears_next: assert property (
        @(posedge clk) rst |=> (count_out == 4'd0)
    );

    // When previously enabled (and not in reset), counter increments by 1 modulo 16.
    check_increment_when_en_prev: assert property (
        @(posedge clk) disable iff (rst)
            $past(!rst) && $past(en) |-> (count_out == (($past(count_out) + 4'd1)[3:0]))
    );

    // When previously disabled (and not in reset), counter holds its value.
    check_hold_when_en0_prev: assert property (
        @(posedge clk) disable iff (rst)
            $past(!rst) && !$past(en) |-> (count_out == $past(count_out))
    );

    // A change from last cycle (without reset) implies previous enable was HIGH.
    check_change_implies_prev_en: assert property (
        @(posedge clk) disable iff (rst)
            $past(!rst) && (count_out != $past(count_out)) |-> $past(en)
    );

    // No change from last cycle (without reset) implies previous enable was LOW.
    check_no_change_implies_prev_not_en: assert property (
        @(posedge clk) disable iff (rst)
            $past(!rst) && (count_out == $past(count_out)) |-> !$past(en)
    );

    // When previously at 4'hF with enable, wraps to 0 on the next cycle.
    check_wrap_on_max: assert property (
        @(posedge clk) disable iff (rst)
            $past(!rst) && $past(en) && ($past(count_out) == 4'hF) |-> (count_out == 4'h0)
    );

    // Next-state equals prev_state plus prev_en modulo 16 (consolidated rule).
    check_one_step_function: assert property (
        @(posedge clk) disable iff (rst)
            $past(!rst) |-> (count_out == (( $past(count_out) + ($past(en) ? 4'd1 : 4'd0) )[3:0]))
    );

    // If reset stays asserted across consecutive cycles, next cycle remains 0.
    check_reset_hold_zero_next: assert property (
        @(posedge clk) rst && $past(rst) |=> (count_out == 4'd0)
    );
endmodule

rtl:
module bin_to_gray (
  input [2:0] bin,
  output reg [2:0] gray
);

  always @* begin
    case (bin)
      3'b000: gray = 3'b000;
      3'b001: gray = 3'b001;
      3'b010: gray = 3'b011;
      3'b011: gray = 3'b010;
      3'b100: gray = 3'b110;
      3'b101: gray = 3'b111;
      3'b110: gray = 3'b101;
      3'b111: gray = 3'b100;
      default: gray = 3'b000;
    endcase
  end

endmodule

sva:
module bin_to_gray_sva (
    input logic clk,
    input logic [2:0] bin,
    input logic [2:0] gray
);
    // Mapping for bin=000 -> gray=000
    map_000: assert property (
        @(posedge clk) (!$isunknown(bin) && (bin == 3'b000)) |-> (gray == 3'b000)
    );
    // Mapping for bin=001 -> gray=001
    map_001: assert property (
        @(posedge clk) (!$isunknown(bin) && (bin == 3'b001)) |-> (gray == 3'b001)
    );
    // Mapping for bin=010 -> gray=011
    map_010: assert property (
        @(posedge clk) (!$isunknown(bin) && (bin == 3'b010)) |-> (gray == 3'b011)
    );
    // Mapping for bin=011 -> gray=010
    map_011: assert property (
        @(posedge clk) (!$isunknown(bin) && (bin == 3'b011)) |-> (gray == 3'b010)
    );
    // Mapping for bin=100 -> gray=110
    map_100: assert property (
        @(posedge clk) (!$isunknown(bin) && (bin == 3'b100)) |-> (gray == 3'b110)
    );
    // Mapping for bin=101 -> gray=111
    map_101: assert property (
        @(posedge clk) (!$isunknown(bin) && (bin == 3'b101)) |-> (gray == 3'b111)
    );
    // Mapping for bin=110 -> gray=101
    map_110: assert property (
        @(posedge clk) (!$isunknown(bin) && (bin == 3'b110)) |-> (gray == 3'b101)
    );
    // Mapping for bin=111 -> gray=100
    map_111: assert property (
        @(posedge clk) (!$isunknown(bin) && (bin == 3'b111)) |-> (gray == 3'b100)
    );
    // Unknown bin selects default mapping gray=000
    unknown_bin_drives_default_gray: assert property (
        @(posedge clk) $isunknown(bin) |-> (gray == 3'b000)
    );
    // Gray output is stable when bin input is stable
    gray_stable_when_bin_stable: assert property (
        @(posedge clk) $stable(bin) |-> $stable(gray)
    );
endmodule

rtl:
module react(
    input pipelineReady,
    input scheduleTask,
    input [2:0] workCounter,
    input scryptResultAvailableIn,
    input doWork,
    output reg [7:0] preparing,
    output reg decreasePrepare,
    output reg scryptResultAvailable
);

always @(*) begin
    // increment preparing counter
    if (pipelineReady && scheduleTask && workCounter == 3 && !decreasePrepare && !doWork) begin
        preparing = preparing + 1;
    end

    // decrement preparing counter
    if (!pipelineReady && !scheduleTask && decreasePrepare && !doWork) begin
        preparing = preparing - 1;
    end

    // set decreasePrepare signal
    if (!scryptResultAvailableIn) begin
        decreasePrepare = 1;
    end else begin
        decreasePrepare = 0;
    end

    // set scryptResultAvailable signal
    scryptResultAvailable = preparing > 0;
end

endmodule

sva:
module react_sva (
    input logic pipelineReady,
    input logic scheduleTask,
    input logic [2:0] workCounter,
    input logic scryptResultAvailableIn,
    input logic doWork,
    input logic [7:0] preparing,
    input logic decreasePrepare,
    input logic scryptResultAvailable
);
    // decreasePrepare must be 0 when scryptResultAvailableIn is 1.
    decprep_low_when_scryptin_high: assert property (
        @(posedge scryptResultAvailableIn) (decreasePrepare == 1'b0)
    );

    // decreasePrepare must be 1 when scryptResultAvailableIn is 0.
    decprep_high_when_scryptin_low: assert property (
        @(negedge scryptResultAvailableIn) (decreasePrepare == 1'b1)
    );

    // scryptResultAvailableIn must be 0 when decreasePrepare rises.
    scryptin_low_on_decprep_rise: assert property (
        @(posedge decreasePrepare) (scryptResultAvailableIn == 1'b0)
    );

    // scryptResultAvailableIn must be 1 when decreasePrepare falls.
    scryptin_high_on_decprep_fall: assert property (
        @(negedge decreasePrepare) (scryptResultAvailableIn == 1'b1)
    );

    // scryptResultAvailable equals (preparing > 0) when sampled on scryptResultAvailableIn rising edge.
    result_flag_matches_prep_on_scryptin_rise: assert property (
        @(posedge scryptResultAvailableIn) (scryptResultAvailable == (preparing > 8'd0))
    );

    // scryptResultAvailable equals (preparing > 0) when sampled on scryptResultAvailableIn falling edge.
    result_flag_matches_prep_on_scryptin_fall: assert property (
        @(negedge scryptResultAvailableIn) (scryptResultAvailable == (preparing > 8'd0))
    );

    // If scryptResultAvailable rises, preparing must be > 0 at that time.
    result_flag_rise_requires_positive_prep: assert property (
        @(posedge scryptResultAvailable) (preparing > 8'd0)
    );

    // If scryptResultAvailable falls, preparing must be 0 at that time.
    result_flag_fall_requires_zero_prep: assert property (
        @(negedge scryptResultAvailable) (preparing == 8'd0)
    );

    // Increment and decrement conditions for preparing cannot be true simultaneously.
    inc_dec_conditions_mutex: assert property (
        @(posedge scryptResultAvailableIn)
            !(
                (pipelineReady && scheduleTask && (workCounter == 3'd3) && !decreasePrepare && !doWork) &&
                (!pipelineReady && !scheduleTask && decreasePrepare && !doWork)
            )
    );

    // No preparing update condition is true when doWork is HIGH.
    no_update_when_doWork_high: assert property (
        @(posedge scryptResultAvailableIn)
            doWork |-> !(
                (pipelineReady && scheduleTask && (workCounter == 3'd3) && !decreasePrepare && !doWork) ||
                (!pipelineReady && !scheduleTask && decreasePrepare && !doWork)
            )
    );
endmodule

rtl:
module top_module (
    input clk,
    input [7:0] in,
    output [7:0] anyedge
);

reg [7:0] pipe1, pipe2, pipe3;

always @(posedge clk) begin
    pipe1 <= in;
end

always @(posedge clk) begin
    pipe2 <= pipe1;
end

always @(posedge clk) begin
    pipe3 <= pipe2;
end

assign anyedge = (pipe1 ^ pipe2) & pipe2 & (pipe2 ^ pipe3);

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic [7:0] in,
    input logic [7:0] anyedge
);

    // Internal history-valid flags (no reset in RTL)
    logic init1, init2;
    always_ff @(posedge clk) begin
        init1 <= 1'b1;
        init2 <= init1;
    end

    ///// Functional equivalence to 3-sample pulse detector /////
    // After 2 cycles of history, anyedge == (~in & $past(in) & ~$past(in,2)).
    eq_anyedge_function: assert property (
        @(posedge clk) init2 |-> (anyedge == ((~in) & $past(in) & (~$past(in,2))))
    );

    ///// Basic masking rules /////
    // anyedge never asserts on bits where current in is 1.
    anyedge_masked_by_in_zero: assert property (
        @(posedge clk) (anyedge & in) == 8'h00
    );

    ///// Stability implications /////
    // If in didn't change from previous cycle, no pulse can occur.
    no_pulse_when_no_change_prev: assert property (
        @(posedge clk) init1 && ($past(in) == in) |-> (anyedge == 8'h00)
    );
    // If in[t-2] == in[t-1], no pulse can occur at t.
    no_pulse_when_no_change_prev2: assert property (
        @(posedge clk) init2 && ($past(in,2) == $past(in)) |-> (anyedge == 8'h00)
    );

    ///// Necessary conditions for anyedge /////
    // When anyedge is high, the previous in must be high (per bit).
    anyedge_requires_prev_in_high: assert property (
        @(posedge clk) init1 |-> ((anyedge & ~($past(in))) == 8'h00)
    );
    // When anyedge is high, in from two cycles ago must be low (per bit).
    anyedge_requires_prev2_in_low: assert property (
        @(posedge clk) init2 |-> ((anyedge & $past(in,2)) == 8'h00)
    );

    ///// Pulse shape /////
    // No bit of anyedge can be high in two consecutive cycles.
    no_back_to_back_anyedge: assert property (
        @(posedge clk) init1 |-> ((anyedge & $past(anyedge)) == 8'h00)
    );

    ///// Per-bit detection of single-cycle high on input /////
    genvar i;
    for (i = 0; i < 8; i++) begin : gen_bit
        // A 0->1->0 pattern on in[i] produces a pulse on anyedge[i] at the last cycle.
        detect_single_cycle_pulse: assert property (
            @(posedge clk) (!in[i]) ##1 (in[i]) ##1 (!in[i]) |-> anyedge[i]
        );
    end

endmodule

rtl:
module synchronous_counter (
    input clk, rst,
    output reg [3:0] count
);

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            count <= 4'b0000;
        end else if (count == 4'b1111) begin
            count <= 4'b0000;
        end else begin
            count <= count + 1;
        end
    end

endmodule

sva:
module synchronous_counter_sva (
    input logic clk,
    input logic rst,
    input logic [3:0] count
);

    ///// Reset behavior /////
    // If rst is HIGH at a clock edge, count is 0 on the next cycle.
    reset_clears_next: assert property (
        @(posedge clk) rst |-> (count == 4'h0)
    );

    // While rst remains HIGH across cycles, count stays 0.
    hold_zero_during_reset: assert property (
        @(posedge clk) $past(rst) && rst |-> (count == 4'h0)
    );

    ///// Counting behavior (out of reset) /////
    // From 15 with rst LOW at both cycles, wrap to 0.
    wrap_from_15_noreset: assert property (
        @(posedge clk) disable iff (rst)
            (!$past(rst) && !rst && ($past(count) == 4'hF)) |-> (count == 4'h0)
    );

    // From non-15 with rst LOW at both cycles, next count increments or is 0 (async reset may have occurred between edges).
    step_or_zero_noreset: assert property (
        @(posedge clk) disable iff (rst)
            (!$past(rst) && !rst && ($past(count) != 4'hF)) |-> ((count == ($past(count) + 4'h1)) || (count == 4'h0))
    );

    // If not wrapping and next value is non-zero, it must be an exact +1 increment.
    strict_step_when_nonzero: assert property (
        @(posedge clk) disable iff (rst)
            (!$past(rst) && !rst && ($past(count) != 4'hF) && (count != 4'h0)) |-> (count == ($past(count) + 4'h1))
    );

    // If current is non-zero out of reset, it must have increased vs. previous sample (no hold/decrement).
    monotonic_increase_noreset: assert property (
        @(posedge clk) disable iff (rst)
            (!$past(rst) && !rst && (count != 4'h0)) |-> (count > $past(count))
    );

    // If current is non-zero out of reset, previous sample was not 15 (no non-zero after wrap).
    no_nonzero_after_prev_15: assert property (
        @(posedge clk) disable iff (rst)
            (!$past(rst) && !rst && (count != 4'h0)) |-> ($past(count) != 4'hF)
    );

endmodule

