module up_down_counter (
    input clk,
    input up_down,
    input load,
    output reg [2:0] count
);

    always @(posedge clk) begin
        if (load)
            count <= 3'b000;
        else if (up_down)
            count <= count + 1;
        else
            count <= count - 1;
    end

endmodule

module unsigned_multiplier (
    input [3:0] A,
    input [3:0] B,
    output reg [7:0] P
);

    always @(*) begin
        P = A * B;
    end

endmodule

