module jk_flip_flop (
    input  clk,
    input  j,
    input  k,
    output q
);

    reg  q_reg;
    assign q = q_reg;

    always @(posedge clk) begin
        if (j && ~k) begin
            q_reg <= 1'b1;
        end else if (~j && k) begin
            q_reg <= 1'b0;
        end else if (j && k) begin
            q_reg <= ~q_reg;
        end
    end

