module decoder_4to16 (
    input [1:0] A, B,
    input EN,
    input clk,
    output reg [15:0] Y
);

reg [1:0] A_reg, B_reg;
reg EN_reg;

always @(posedge clk) begin
    A_reg <= A;
    B_reg <= B;
    EN_reg <= EN;
end

always @(posedge clk) begin
    if (EN_reg) begin
        case ({A_reg, B_reg})
            2'b00: Y <= 16'b1111111111111110;
            2'b01: Y <= 16'b1111111111111101;
            2'b10: Y <= 16'b1111111111111011;
            2'b11: Y <= 16'b1111111111110111;
            default: Y <= 16'b1111111111111111;
        endcase
    end else begin
        Y <= 16'b1111111111111111;
    end
end

endmodule

sva:
module decoder_4to16_sva (
    input logic clk,
    input logic [1:0] A,
    input logic [1:0] B,
    input logic EN,
    input logic [15:0] Y
);
    // Y must be all 1s next cycle when EN is low.
    check_y_all_ones_when_disabled: assert property (
        @(posedge clk) (!EN) |=> (Y == 16'hFFFF)
    );

    // When EN is high and {A,B}==0, Y must be 0xFFFE next cycle.
    check_decode_code0: assert property (
        @(posedge clk) (EN && ({A,B} == 4'b0000)) |=> (Y == 16'hFFFE)
    );

    // When EN is high and {A,B}==1, Y must be 0xFFFD next cycle.
    check_decode_code1: assert property (
        @(posedge clk) (EN && ({A,B} == 4'b0001)) |=> (Y == 16'hFFFD)
    );

    // When EN is high and {A,B}==2, Y must be 0xFFFB next cycle.
    check_decode_code2: assert property (
        @(posedge clk) (EN && ({A,B} == 4'b0010)) |=> (Y == 16'hFFFB)
    );

    // When EN is high and {A,B}==3, Y must be 0xFFF7 next cycle.
    check_decode_code3: assert property (
        @(posedge clk) (EN && ({A,B} == 4'b0011)) |=> (Y == 16'hFFF7)
    );

    // When EN is high and {A,B} not in 0..3, Y must be all 1s next cycle.
    check_default_all_ones_for_other_codes: assert property (
        @(posedge clk) (EN && !({A,B} inside {4'b0000,4'b0001,4'b0010,4'b0011})) |=> (Y == 16'hFFFF)
    );

    // On valid decode (0..3) with EN high, upper bits [15:4] must be all 1s next cycle.
    check_high_bits_ones_on_valid_decode: assert property (
        @(posedge clk) (EN && ({A,B} inside {4'b0000,4'b0001,4'b0010,4'b0011})) |=> (Y[15:4] == 12'hFFF)
    );

    // On valid decode (0..3) with EN high, Y is not 0xFFFF next cycle.
    check_not_all_ones_on_valid_decode: assert property (
        @(posedge clk) (EN && ({A,B} inside {4'b0000,4'b0001,4'b0010,4'b0011})) |=> (Y != 16'hFFFF)
    );
endmodule

rtl:
module barrel_shifter_priority_encoder_or (
    input clk,
    input load,
    input [1:0] ena,
    input [7:0] in,
    input [99:0] data,
    output reg [7:0] out
);

reg [99:0] shifted_data;
reg [7:0] priority_encoded;
reg [2:0] highest_bit_pos;

always @(posedge clk) begin
    if (load) begin
        shifted_data <= data;
    end else begin
        if (ena[0] && ena[1]) begin
            shifted_data <= {data[99], data[98:0]};
        end else if (ena[0]) begin
            shifted_data <= {data[98:0], data[99]};
        end else if (ena[1]) begin
            shifted_data <= {data[0], data[99:1]};
        end
    end
end

always @* begin
    priority_encoded = 8'b00000000;
    if (shifted_data[99]) begin
        priority_encoded = 8'b10000000;
        highest_bit_pos = 3'b111;
    end else if (shifted_data[98]) begin
        priority_encoded = 8'b01000000;
        highest_bit_pos = 3'b110;
    end else if (shifted_data[97]) begin
        priority_encoded = 8'b00100000;
        highest_bit_pos = 3'b101;
    end else if (shifted_data[96]) begin
        priority_encoded = 8'b00010000;
        highest_bit_pos = 3'b100;
    end else if (shifted_data[95]) begin
        priority_encoded = 8'b00001000;
        highest_bit_pos = 3'b011;
    end else if (shifted_data[94]) begin
        priority_encoded = 8'b00000100;
        highest_bit_pos = 3'b010;
    end else if (shifted_data[93]) begin
        priority_encoded = 8'b00000010;
        highest_bit_pos = 3'b001;
    end else if (shifted_data[92]) begin
        priority_encoded = 8'b00000001;
        highest_bit_pos = 3'b000;
    end
end

always @* begin
    out = priority_encoded | in;
end

endmodule

sva:
module barrel_shifter_priority_encoder_or_sva (
    input logic clk,
    input logic load,
    input logic [1:0] ena,
    input logic [7:0] in,
    input logic [99:0] data,
    input logic [7:0] out,
    // Internal signals from DUT (bind via hierarchy)
    input logic [99:0] shifted_data,
    input logic [7:0] priority_encoded
);
    ///// Sequential barrel shifter behavior /////
    // On load, shifted_data captures data on next cycle.
    shift_on_load_updates_data: assert property (
        @(posedge clk) load |=> (shifted_data === $past(data))
    );
    // With both ena bits set and not loading, shifted_data equals data on next cycle.
    shift_both_ena_no_rotate: assert property (
        @(posedge clk) (!load && (ena[0] && ena[1])) |=> (shifted_data === $past(data))
    );
    // With ena[0] only and not loading, shifted_data rotates left by 1 from data on next cycle.
    shift_left_rotate: assert property (
        @(posedge clk) (!load && (ena[0] && !ena[1])) |=> (shifted_data === { $past(data[98:0]), $past(data[99]) })
    );
    // With ena[1] only and not loading, shifted_data rotates right by 1 from data on next cycle.
    shift_right_rotate: assert property (
        @(posedge clk) (!load && (!ena[0] && ena[1])) |=> (shifted_data === { $past(data[0]), $past(data[99:1]) })
    );

    ///// Priority encoder to output OR mapping /////
    // If shifted_data[99] is 1, out[7] is forced high and lower bits pass through.
    out_follows_priority_99: assert property (
        @(posedge clk) shifted_data[99] |-> (out[7] == 1'b1) && (out[6:0] === in[6:0])
    );
    // If highest set bit is 98, out[6] is forced high and others pass through.
    out_follows_priority_98: assert property (
        @(posedge clk) (!shifted_data[99] && shifted_data[98]) |-> (out[6] == 1'b1) && (out[7] == in[7]) && (out[5:0] === in[5:0])
    );
    // If highest set bit is 97, out[5] is forced high and others pass through.
    out_follows_priority_97: assert property (
        @(posedge clk) (!shifted_data[99] && !shifted_data[98] && shifted_data[97]) |-> (out[5] == 1'b1) && (out[7:6] === in[7:6]) && (out[4:0] === in[4:0])
    );
    // If highest set bit is 96, out[4] is forced high and others pass through.
    out_follows_priority_96: assert property (
        @(posedge clk) (!shifted_data[99] && !shifted_data[98] && !shifted_data[97] && shifted_data[96]) |-> (out[4] == 1'b1) && (out[7:5] === in[7:5]) && (out[3:0] === in[3:0])
    );
    // If highest set bit is 95, out[3] is forced high and others pass through.
    out_follows_priority_95: assert property (
        @(posedge clk) (!shifted_data[99] && !shifted_data[98] && !shifted_data[97] && !shifted_data[96] && shifted_data[95]) |-> (out[3] == 1'b1) && (out[7:4] === in[7:4]) && (out[2:0] === in[2:0])
    );
    // If highest set bit is 94, out[2] is forced high and others pass through.
    out_follows_priority_94: assert property (
        @(posedge clk) (!shifted_data[99] && !shifted_data[98] && !shifted_data[97] && !shifted_data[96] && !shifted_data[95] && shifted_data[94]) |-> (out[2] == 1'b1) && (out[7:3] === in[7:3]) && (out[1:0] === in[1:0])
    );
    // If highest set bit is 93, out[1] is forced high and others pass through.
    out_follows_priority_93: assert property (
        @(posedge clk) (!shifted_data[99] && !shifted_data[98] && !shifted_data[97] && !shifted_data[96] && !shifted_data[95] && !shifted_data[94] && shifted_data[93]) |-> (out[1] == 1'b1) && (out[7:2] === in[7:2]) && (out[0] === in[0])
    );
    // If highest set bit is 92, out[0] is forced high and others pass through.
    out_follows_priority_92: assert property (
        @(posedge clk) (!shifted_data[99] && !shifted_data[98] && !shifted_data[97] && !shifted_data[96] && !shifted_data[95] && !shifted_data[94] && !shifted_data[93] && shifted_data[92]) |-> (out[0] == 1'b1) && (out[7:1] === in[7:1])
    );
    // If none of bits 99:92 are set, out equals in.
    out_when_no_priority_bits: assert property (
        @(posedge clk) (|(shifted_data[99:92]) == 1'b0) |-> (out === in)
    );
    // out is always the bitwise OR of priority_encoded and in.
    out_equals_in_or_priority: assert property (
        @(posedge clk) (out === (in | priority_encoded))
    );
    // priority_encoded is one-hot or zero.
    priority_is_onehot_or_zero: assert property (
        @(posedge clk) $onehot0(priority_encoded)
    );
endmodule

rtl:
module top_module(
    input wire clk,
    input wire [7:0] in,
    output reg [7:0] out
);

    wire [2:0] pos;
    wire [7:0] out_hi, out_lo;
    reg select; // Declare 'select' as a reg

    priority_encoder pe(
        .in(in),
        .pos(pos)
    );

    word_splitter ws(
        .in({8'b0, in}),  // Pad 8 zeros to input to match port width
        .out_hi(out_hi),
        .out_lo(out_lo)
    );

    always @(*) begin  // Use a combinational always block for select
        select = (pos == 0) ? 1'b0 : 1'b1;
    end

    always @(posedge clk) begin
        if (select) begin
            out <= out_hi; // Use blocking assignment '=<' for registers
        end else begin
            out <= out_lo; // Use blocking assignment '=<' for registers
        end
    end

endmodule

module priority_encoder (
    input [7:0] in,
    output reg [2:0] pos
);

    always @(*) begin
        case(in)
            8'b00000001: pos = 3'b000;
            8'b00000010: pos = 3'b001;
            8'b00000100: pos = 3'b010;
            8'b00001000: pos = 3'b011;
            8'b00010000: pos = 3'b100;
            8'b00100000: pos = 3'b101;
            8'b01000000: pos = 3'b110;
            8'b10000000: pos = 3'b111;
            default: pos = 3'b000;
        endcase
    end

endmodule

module word_splitter (
    input wire [15:0] in,
    output reg [7:0] out_hi,
    output reg [7:0] out_lo
);

    always @(*) begin
        out_hi = in >> 8;
        out_lo = in & 8'hFF;
    end

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic [7:0] in,
    input logic [7:0] out,
    input logic [2:0] pos,
    input logic [7:0] out_hi,
    input logic [7:0] out_lo,
    input logic select
);
    ///// Combinational submodule behavior /////
    // word_splitter high byte is always zero (input upper 8 bits are zero).
    check_out_hi_zero: assert property (
        @(posedge clk) out_hi == 8'h00
    );
    // word_splitter low byte equals input.
    check_out_lo_eq_in: assert property (
        @(posedge clk) out_lo == in
    );

    ///// priority_encoder mapping /////
    // pos mapping for one-hot bit0.
    pe_map_b0: assert property (
        @(posedge clk) (in == 8'b00000001) |-> (pos == 3'b000)
    );
    // pos mapping for one-hot bit1.
    pe_map_b1: assert property (
        @(posedge clk) (in == 8'b00000010) |-> (pos == 3'b001)
    );
    // pos mapping for one-hot bit2.
    pe_map_b2: assert property (
        @(posedge clk) (in == 8'b00000100) |-> (pos == 3'b010)
    );
    // pos mapping for one-hot bit3.
    pe_map_b3: assert property (
        @(posedge clk) (in == 8'b00001000) |-> (pos == 3'b011)
    );
    // pos mapping for one-hot bit4.
    pe_map_b4: assert property (
        @(posedge clk) (in == 8'b00010000) |-> (pos == 3'b100)
    );
    // pos mapping for one-hot bit5.
    pe_map_b5: assert property (
        @(posedge clk) (in == 8'b00100000) |-> (pos == 3'b101)
    );
    // pos mapping for one-hot bit6.
    pe_map_b6: assert property (
        @(posedge clk) (in == 8'b01000000) |-> (pos == 3'b110)
    );
    // pos mapping for one-hot bit7.
    pe_map_b7: assert property (
        @(posedge clk) (in == 8'b10000000) |-> (pos == 3'b111)
    );
    // Default: for non-one-hot (including zero), pos is 000.
    pe_default_zero: assert property (
        @(posedge clk) (!(in inside {8'b00000001,8'b00000010,8'b00000100,8'b00001000,8'b00010000,8'b00100000,8'b01000000,8'b10000000})) |-> (pos == 3'b000)
    );

    ///// select derivation from pos /////
    // select is high iff pos != 000.
    select_when_pos_nonzero: assert property (
        @(posedge clk) (pos != 3'b000) |-> (select == 1'b1)
    );
    // select is low iff pos == 000.
    deselect_when_pos_zero: assert property (
        @(posedge clk) (pos == 3'b000) |-> (select == 1'b0)
    );

    ///// Registered mux behavior /////
    // When select is 1, next-cycle out equals previous out_hi.
    mux_select_one: assert property (
        @(posedge clk) select |=> (out == $past(out_hi))
    );
    // When select is 0, next-cycle out equals previous out_lo.
    mux_select_zero: assert property (
        @(posedge clk) !select |=> (out == $past(out_lo))
    );

    ///// End-to-end mapping /////
    // For upper one-hot inputs (bits 1..7), next-cycle out is zero.
    out_zero_for_upper_onehots: assert property (
        @(posedge clk) (in inside {8'b00000010,8'b00000100,8'b00001000,8'b00010000,8'b00100000,8'b01000000,8'b10000000}) |=> (out == 8'h00)
    );
    // For all other inputs, next-cycle out equals previous input.
    out_eq_in_otherwise: assert property (
        @(posedge clk) (!(in inside {8'b00000010,8'b00000100,8'b00001000,8'b00010000,8'b00100000,8'b01000000,8'b10000000})) |=> (out == $past(in))
    );
endmodule

rtl:
module signed_mag_comp (
    input signed [3:0] A,
    input signed [3:0] B,
    output reg EQ,
    output reg GT
);

    always @(*) begin
        if (A == B) begin
            EQ = 1;
            GT = 0;
        end else if (A > B) begin
            EQ = 0;
            GT = 1;
        end else begin
            EQ = 0;
            GT = 0;
        end
    end

endmodule

sva:
module signed_mag_comp_sva (
    input logic CLK,
    input logic signed [3:0] A,
    input logic signed [3:0] B,
    input logic EQ,
    input logic GT
);
    // EQ equals signed equality of A and B.
    eq_reflects_signed_equality: assert property (
        @(posedge CLK) (EQ == (A == B))
    );

    // GT equals signed greater-than of A over B.
    gt_reflects_signed_gt: assert property (
        @(posedge CLK) (GT == (A > B))
    );

    // EQ and GT are never both 1.
    check_outputs_mutex: assert property (
        @(posedge CLK) !(EQ && GT)
    );

    // When A < B, outputs are both 0.
    less_case_outputs_zero_zero: assert property (
        @(posedge CLK) (A < B) |-> (!EQ && !GT)
    );

    // Outputs both 0 only when A < B.
    zero_zero_implies_less: assert property (
        @(posedge CLK) (!EQ && !GT) |-> (A < B)
    );

    // When A != B, EQ is 0.
    neq_implies_eq_zero: assert property (
        @(posedge CLK) (A != B) |-> (EQ == 1'b0)
    );
endmodule

rtl:
module add_sub (
    input [3:0] A, B,
    input MODE,
    output [3:0] S
);

    reg [3:0] temp;

    always @(*) begin
        if (MODE == 0) begin
            temp = A + B;
        end else begin
            temp = A - B;
        end
    end

    assign S = temp;

endmodule

sva:
module add_sub_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic       MODE,
    input logic [3:0] S
);
    // No clock/reset in DUT; pure combinational. Sample on any edge of inputs.
    default clocking cb @(
        posedge MODE or negedge MODE or
        posedge A[0] or negedge A[0] or
        posedge A[1] or negedge A[1] or
        posedge A[2] or negedge A[2] or
        posedge A[3] or negedge A[3] or
        posedge B[0] or negedge B[0] or
        posedge B[1] or negedge B[1] or
        posedge B[2] or negedge B[2] or
        posedge B[3] or negedge B[3]
    ); endclocking

    ///// Functional correctness /////
    // In add mode (MODE==0), S equals A + B (4-bit wraparound).
    check_add_mode: assert property (
        MODE == 1'b0 |-> (S == (A + B))
    );

    // In subtract mode (MODE==1), S equals A - B (4-bit wraparound).
    check_sub_mode: assert property (
        MODE == 1'b1 |-> (S == (A - B))
    );

    // Output equals the selected operation for all input combinations.
    check_function_selection: assert property (
        S == (MODE ? (A - B) : (A + B))
    );

    // If S changed between samples, at least one input changed as well.
    check_output_change_implies_input_change: assert property (
        $changed(S) |-> $changed({MODE, A, B})
    );
endmodule

rtl:
module priority_encoder (
    input [3:0] in,
    output reg [1:0] pos,
    output reg       is_zero
);

    always @(*) begin
        if (|in == 1'b0) begin
            pos = 2'b00;
            is_zero = 1'b1;
        end else begin
            pos = {2{in[3]}};
            is_zero = 1'b0;
        end
    end

endmodule
module and_gate (
    input [3:0] in,
    input        is_zero,
    output       all_high
);

    assign all_high = (is_zero) ? 1'b0 : (in == 4'b1111);

endmodule
module top_module (
    input [3:0] in,
    output reg [1:0] pos,
    output       all_high
);

    wire [1:0] pos_wire;
    wire       is_zero;
    priority_encoder pe(.in(in), .pos(pos_wire), .is_zero(is_zero));
    and_gate ag(.in(in), .is_zero(is_zero), .all_high(all_high));

    always @(*) begin
        pos = pos_wire;
    end

endmodule

sva:
module top_module_sva (
    input logic CLK,
    input logic RESETn,
    // DUT ports
    input logic [3:0] in,
    input logic [1:0] pos,
    input logic       all_high,
    // Internal signals from DUT
    input logic [1:0] pos_wire,
    input logic       is_zero
);
    ///// priority_encoder behavior /////
    // Zero input -> pos_wire=00 and is_zero=1.
    pe_zero_input_outputs: assert property (
        @(posedge CLK) disable iff (!RESETn) (in == 4'b0000) |-> (pos_wire == 2'b00) && (is_zero == 1'b1)
    );
    // Nonzero input -> is_zero=0 and pos_wire duplicates MSB.
    pe_nonzero_input_outputs: assert property (
        @(posedge CLK) disable iff (!RESETn) (in != 4'b0000) |-> (is_zero == 1'b0) && (pos_wire == {2{in[3]}})
    );
    // MSB high -> pos_wire=11 and is_zero=0.
    pe_msb_high_pos_11: assert property (
        @(posedge CLK) disable iff (!RESETn) (in[3] == 1'b1) |-> (pos_wire == 2'b11) && (is_zero == 1'b0)
    );
    // Nonzero with MSB low -> pos_wire=00 and is_zero=0.
    pe_nonzero_msb_low_pos_00: assert property (
        @(posedge CLK) disable iff (!RESETn) ((in != 4'b0000) && (in[3] == 1'b0)) |-> (pos_wire == 2'b00) && (is_zero == 1'b0)
    );
    // is_zero is exactly (in == 0).
    pe_is_zero_equivalence: assert property (
        @(posedge CLK) disable iff (!RESETn) (is_zero == (in == 4'b0000))
    );
    // When is_zero=1, pos_wire must be 00.
    pe_is_zero_implies_pos00: assert property (
        @(posedge CLK) disable iff (!RESETn) is_zero |-> (pos_wire == 2'b00)
    );
    // pos bits are always equal (00 or 11).
    pe_pos_bits_equal: assert property (
        @(posedge CLK) disable iff (!RESETn) (pos_wire[1] == pos_wire[0])
    );

    ///// top_module wiring /////
    // Top-level pos mirrors internal pos_wire.
    top_pos_matches_internal: assert property (
        @(posedge CLK) disable iff (!RESETn) (pos == pos_wire)
    );
    // Top-level pos bits are equal (propagated from pos_wire).
    top_pos_bits_equal: assert property (
        @(posedge CLK) disable iff (!RESETn) (pos[1] == pos[0])
    );

    ///// and_gate behavior /////
    // all_high equals (is_zero ? 0 : (in == 4'hF)).
    ag_all_high_definition: assert property (
        @(posedge CLK) disable iff (!RESETn) ( all_high == (is_zero ? 1'b0 : (in == 4'b1111)) )
    );
    // all_high implies in==1111 and not is_zero.
    ag_all_high_implies_inputs: assert property (
        @(posedge CLK) disable iff (!RESETn) all_high |-> (!is_zero) && (in == 4'b1111)
    );
    // is_zero forces all_high to 0.
    ag_is_zero_clears_all_high: assert property (
        @(posedge CLK) disable iff (!RESETn) is_zero |-> (all_high == 1'b0)
    );
    // For in==1111, outputs are consistent: is_zero=0, pos_wire=11, all_high=1.
    ag_full_one_vector_consistency: assert property (
        @(posedge CLK) disable iff (!RESETn) (in == 4'b1111) |-> (is_zero == 1'b0) && (pos_wire == 2'b11) && (all_high == 1'b1)
    );
endmodule

rtl:
module adder_8bit (
    input         clk,
    input  [7:0] input_a,
    input  [7:0] input_b,
    output reg [7:0] output_c
);

    always @(posedge clk) begin
        output_c <= input_a + input_b;
    end

endmodule

sva:
module adder_8bit_sva (
    input  logic        clk,
    input  logic [7:0]  input_a,
    input  logic [7:0]  input_b,
    input  logic [7:0]  output_c
);
    // Output equals sum of inputs from the previous cycle (1-cycle latency).
    check_sum_pipeline: assert property (
        @(posedge clk) output_c == $past(input_a + input_b)
    );

    // If previous A was zero, output equals previous B.
    check_sum_with_zero_a: assert property (
        @(posedge clk) ($past(input_a) == 8'h00) |-> (output_c == $past(input_b))
    );

    // If previous B was zero, output equals previous A.
    check_sum_with_zero_b: assert property (
        @(posedge clk) ($past(input_b) == 8'h00) |-> (output_c == $past(input_a))
    );

    // LSB of output equals XOR of previous-cycle LSBs (no carry-in).
    check_lsb_xor: assert property (
        @(posedge clk) output_c[0] == $past(input_a[0] ^ input_b[0])
    );

    // If inputs were unchanged across two prior cycles, output holds its value.
    check_output_stable_when_inputs_unchanged: assert property (
        @(posedge clk) (($past(input_a,1) == $past(input_a,2)) && ($past(input_b,1) == $past(input_b,2))) |-> (output_c == $past(output_c))
    );

    // Wraparound example: 0xFF + 0x01 (prev cycle) produces 0x00.
    check_wrap_ff_plus_01: assert property (
        @(posedge clk) (($past(input_a) == 8'hFF) && ($past(input_b) == 8'h01)) |-> (output_c == 8'h00)
    );

    // Wraparound example: 0xFF + 0xFF (prev cycle) produces 0xFE.
    check_wrap_ff_plus_ff: assert property (
        @(posedge clk) (($past(input_a) == 8'hFF) && ($past(input_b) == 8'hFF)) |-> (output_c == 8'hFE)
    );

    // If previous inputs were equal, output equals previous A doubled (mod 256).
    check_doubling_when_equal_inputs: assert property (
        @(posedge clk) ($past(input_a) == $past(input_b)) |-> (output_c == ($past(input_a) << 1))
    );

    // Swapping inputs across two consecutive cycles keeps the output the same.
    check_commutativity_swap_preserves_output: assert property (
        @(posedge clk) (($past(input_a,1) == $past(input_b,2)) && ($past(input_b,1) == $past(input_a,2))) |-> (output_c == $past(output_c))
    );
endmodule

