rtl:
module UART_Rx(
    input CLK,
    output reg [7:0] D = 8'b00000000,
	 input RD,
    input RST,
    input RX,
    output reg RXNE = 1'b0
    );

parameter CLOCK = 1_000_000;
parameter BAUD_RATE = 9_600;

localparam SAMPLES = 4;
localparam CLK_DIV = CLOCK/(BAUD_RATE*SAMPLES*2);
reg [$clog2(CLK_DIV)-1:0]baud_counter = 0;

reg prev_CLK_B;
reg CLK_B = 1'b0; 

always @ (posedge CLK) begin 
	prev_CLK_B <= CLK_B;
	baud_counter <= baud_counter+1'b1;
	if ( baud_counter == CLK_DIV-1) begin
		baud_counter <=0; 
		CLK_B <= ~CLK_B;
	end
end

reg [SAMPLES-1:0]symbol = {SAMPLES{1'b1}};
reg [$clog2(SAMPLES)-1:0]symbol_cnt = 0;

reg busy = 1'b0;
reg [9:0]data = 10'b1111111111;
reg [3:0]data_cnt = 0;
wire data_correct = (!data[0]) & data[9]; always @(posedge CLK) begin
	if (RST == 1'b1) begin
		symbol_cnt <= 0; 
		data_cnt <= 0;
		RXNE <= 1'b0;
		busy <= 1'b0;
		D <= 8'b00000000;
	end
	else if(CLK_B == 1'b1 && prev_CLK_B == 1'b0) begin if((RX==1'b0) && (symbol[SAMPLES-1]==1'b0) && !data_cnt && !busy) begin
			symbol_cnt <= 2; data_cnt <= 9;
			busy <= 1'b1;
		end

		if(busy) begin
			if(symbol_cnt) begin
				symbol_cnt <= symbol_cnt - 1'b1;
			end else begin
				case (symbol[SAMPLES-2:0])
					3'b111, 3'b110, 3'b101, 3'b011:
						data = {1'b1, data[9:1]}; default:
						data = {1'b0, data[9:1]};
				endcase

				if (data_cnt) begin
					data_cnt <= data_cnt - 1'b1;
					symbol_cnt <= 3;
				end
				else begin D <= data[8:1];
					RXNE <= 1'b1;
					busy <= 1'b0;
				end
			end
		end

		symbol <= {RX, symbol[SAMPLES-1:1]};
	end

	if (RD == 1'b1) begin
		RXNE <= 1'b0;
	end else begin
	end
end

endmodule

sva:
module UART_Rx_sva (
    input logic CLK,
    input logic [7:0] D,
    input logic RD,
    input logic RST,
    input logic RX,
    input logic RXNE,
    input logic prev_CLK_B,
    input logic CLK_B,
    input logic [3:0] symbol,
    input logic [1:0] symbol_cnt,
    input logic busy,
    input logic [9:0] data,
    input logic [3:0] data_cnt
);
    // prev_CLK_B tracks the previous value of CLK_B.
    track_prev_clk_b: assert property (
        @(posedge CLK) disable iff (RST) prev_CLK_B == $past(CLK_B)
    );

    // Synchronous reset clears key registers on the next cycle.
    reset_clears_regs_next: assert property (
        @(posedge CLK) RST |=> (symbol_cnt == 2'd0) && (data_cnt == 4'd0) && (RXNE == 1'b0) && (busy == 1'b0) && (D == 8'h00)
    );

    // RD high clears RXNE on the next clock.
    rd_clears_rxne_next: assert property (
        @(posedge CLK) disable iff (RST) $past(RD) |-> (RXNE == 1'b0)
    );

    // RXNE can only fall due to RD.
    rxne_fall_only_on_rd: assert property (
        @(posedge CLK) disable iff (RST) $fell(RXNE) |-> $past(RD)
    );

    // Valid start condition (on CLK_B rise) sets busy and loads data_cnt=9, symbol_cnt=2.
    start_sets_busy_and_counters: assert property (
        @(posedge CLK) disable iff (RST)
            $past((CLK_B == 1'b1) && (prev_CLK_B == 1'b0) && (RX == 1'b0) && (symbol[3] == 1'b0) && (data_cnt == 4'd0) && (busy == 1'b0))
        |-> (busy == 1'b1) && (data_cnt == 4'd9) && (symbol_cnt == 2'd2)
    );

    // While busy and on CLK_B rise, nonzero symbol_cnt decrements by 1.
    symbol_cnt_counts_down: assert property (
        @(posedge CLK) disable iff (RST)
            $past((CLK_B == 1'b1) && (prev_CLK_B == 1'b0) && (busy == 1'b1) && (symbol_cnt != 2'd0))
        |-> (symbol_cnt == $past(symbol_cnt) - 2'd1)
    );

    // While busy and sampling (symbol_cnt==0), load symbol_cnt=3 and decrement data_cnt.
    load_symbol_cnt3_and_dec_data_cnt: assert property (
        @(posedge CLK) disable iff (RST)
            $past((CLK_B == 1'b1) && (prev_CLK_B == 1'b0) && (busy == 1'b1) && (symbol_cnt == 2'd0) && (data_cnt != 4'd0))
        |-> (symbol_cnt == 2'd3) && (data_cnt == $past(data_cnt) - 4'd1)
    );

    // End of frame (symbol_cnt==0 and data_cnt==0 on CLK_B rise) asserts RXNE and clears busy.
    end_of_frame_sets_rxne_and_clears_busy: assert property (
        @(posedge CLK) disable iff (RST)
            $past((CLK_B == 1'b1) && (prev_CLK_B == 1'b0) && (busy == 1'b1) && (symbol_cnt == 2'd0) && (data_cnt == 4'd0))
        |-> (RXNE == 1'b1) && (busy == 1'b0)
    );

    // On each CLK_B rise, shift in RX into the symbol register.
    symbol_shifts_on_clk_b_rise: assert property (
        @(posedge CLK) disable iff (RST)
            $past((CLK_B == 1'b1) && (prev_CLK_B == 1'b0))
        |-> (symbol == {$past(RX), $past(symbol[3:1])})
    );

    // On each sample (CLK_B rise with busy and symbol_cnt==0), data shifts right by 1.
    data_shifts_right_on_sample: assert property (
        @(posedge CLK) disable iff (RST)
            $past((CLK_B == 1'b1) && (prev_CLK_B == 1'b0) && (busy == 1'b1) && (symbol_cnt == 2'd0))
        |-> (data[8:0] == $past(data[9:1]))
    );

    // At end of frame, D is loaded from shifted data (old data[9:2]).
    D_loads_from_shifted_data: assert property (
        @(posedge CLK) disable iff (RST)
            $past((CLK_B == 1'b1) && (prev_CLK_B == 1'b0) && (busy == 1'b1) && (symbol_cnt == 2'd0) && (data_cnt == 4'd0))
        |-> (D == $past(data[9:2]))
    );

    // busy only rises on a valid start condition at a CLK_B rise.
    busy_rise_requires_start: assert property (
        @(posedge CLK) disable iff (RST)
            $rose(busy)
        |-> $past((CLK_B == 1'b1) && (prev_CLK_B == 1'b0) && (RX == 1'b0) && (symbol[3] == 1'b0) && (data_cnt == 4'd0) && (busy == 1'b0))
    );

    // busy only falls at end of frame on a CLK_B rise.
    busy_fall_requires_eof: assert property (
        @(posedge CLK) disable iff (RST)
            $fell(busy)
        |-> $past((CLK_B == 1'b1) && (prev_CLK_B == 1'b0) && (busy == 1'b1) && (symbol_cnt == 2'd0) && (data_cnt == 4'd0))
    );

    // While symbol_cnt!=0 on a CLK_B rise, data remains stable (no shift yet).
    data_stable_while_symbol_window: assert property (
        @(posedge CLK) disable iff (RST)
            $past((CLK_B == 1'b1) && (prev_CLK_B == 1'b0) && (busy == 1'b1) && (symbol_cnt != 2'd0))
        |-> (data == $past(data))
    );
endmodule

rtl:
module byte_generator_even_parity (
  input clk,
  input reset,
  input [7:0] data_in,
  output reg [8:0] byte_out
);

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      byte_out <= 9'b0;
    end else begin
      byte_out[8] <= ^data_in;
      byte_out[7:0] <= data_in;
    end
  end

endmodule

sva:
module byte_generator_even_parity_sva (
  input logic clk,
  input logic reset,
  input logic [7:0] data_in,
  input logic [8:0] byte_out
);

  ///// Reset behavior /////
  // When reset is asserted, byte_out must be all zeros.
  reset_clears_output: assert property (
    @(posedge clk) reset |-> (byte_out == 9'b0)
  );

  ///// Functional mapping /////
  // Next cycle, byte_out[7:0] equals data_in from the previous cycle.
  map_lower_byte_next: assert property (
    @(posedge clk) disable iff (reset) 1'b1 |=> (byte_out[7:0] == $past(data_in))
  );

  // Next cycle, byte_out[8] equals XOR-reduction of previous cycle's data_in.
  map_parity_next: assert property (
    @(posedge clk) disable iff (reset) 1'b1 |=> (byte_out[8] == ^$past(data_in))
  );

  ///// Parity consistency /////
  // Parity bit matches XOR of the stored data bits.
  parity_matches_lower_bits: assert property (
    @(posedge clk) disable iff (reset) (byte_out[8] == ^byte_out[7:0])
  );

  // The 9-bit byte_out always has even parity.
  even_parity_invariant: assert property (
    @(posedge clk) disable iff (reset) (^byte_out == 1'b0)
  );

  ///// Stability relation /////
  // If data_in is the same across two cycles, byte_out remains unchanged next cycle.
  output_stable_when_input_stable: assert property (
    @(posedge clk) disable iff (reset) (data_in == $past(data_in)) |=> (byte_out == $past(byte_out))
  );

endmodule

rtl:
module binary_comparator (
    input [7:0] A,
    input [7:0] B,
    output reg EQ,
    output reg LT,
    output reg GT
);

    always @(*) begin
        if (A == B) begin
            EQ = 1;
            LT = 0;
            GT = 0;
        end else if (A < B) begin
            EQ = 0;
            LT = 1;
            GT = 0;
        end else begin
            EQ = 0;
            LT = 0;
            GT = 1;
        end
    end

endmodule

sva:
module binary_comparator_sva (
    input logic clk,          // verification clock for sampling assertions
    input logic [7:0] A,
    input logic [7:0] B,
    input logic EQ,
    input logic LT,
    input logic GT
);
    // DUT has no reset; purely combinational logic sampled on clk.
    // Behavior: EQ=1 when A==B; LT=1 when A<B; GT=1 when A>B; exactly one high.

    // Exactly one of EQ/LT/GT is HIGH at any time.
    check_onehot_outputs: assert property (
        @(posedge clk) $onehot({EQ, LT, GT})
    );

    // When A equals B, EQ must be 1 and LT/GT must be 0.
    check_eq_when_equal: assert property (
        @(posedge clk) (A == B) |-> (EQ && !LT && !GT)
    );

    // If EQ is 1, then A must equal B.
    check_equal_implied_by_EQ: assert property (
        @(posedge clk) EQ |-> (A == B)
    );

    // When A is less than B, LT must be 1 and EQ/GT must be 0.
    check_lt_when_less: assert property (
        @(posedge clk) (A < B) |-> (!EQ && LT && !GT)
    );

    // If LT is 1, then A must be less than B.
    check_less_implied_by_LT: assert property (
        @(posedge clk) LT |-> (A < B)
    );

    // When A is greater than B, GT must be 1 and EQ/LT must be 0.
    check_gt_when_greater: assert property (
        @(posedge clk) (A > B) |-> (!EQ && !LT && GT)
    );

    // If GT is 1, then A must be greater than B.
    check_greater_implied_by_GT: assert property (
        @(posedge clk) GT |-> (A > B)
    );

endmodule

rtl:
module prng (
    input clk,
    input reset,
    input [7:0] seed,
    output reg [7:0] q
);

reg [99:0] shift_reg;
reg mux_sel;

always @(posedge clk) begin
    if (reset) begin
        shift_reg <= {100{1'b0}};
        mux_sel <= 1'b0;
    end else begin
        shift_reg <= {shift_reg[98:0], mux_sel};
        mux_sel <= shift_reg[93] ^ shift_reg[91] ^ shift_reg[87] ^ shift_reg[84];
    end
end

always @(posedge clk) begin
    if (reset) begin
        q <= seed;
    end else begin
        q <= {shift_reg[99], shift_reg[95], shift_reg[91], shift_reg[87], shift_reg[83], shift_reg[79], shift_reg[75], shift_reg[71]};
    end
end

endmodule

sva:
module prng_sva (
    input logic clk,
    input logic reset,
    input logic [7:0] seed,
    input logic [7:0] q,
    input logic [99:0] shift_reg,
    input logic mux_sel
);

    // In reset, internal state is cleared.
    check_reset_state_regs: assert property (
        @(posedge clk) reset |-> (shift_reg == 100'b0) && (mux_sel == 1'b0)
    );

    // In reset, q equals seed.
    check_reset_q_eq_seed: assert property (
        @(posedge clk) reset |-> (q == seed)
    );

    // On reset deassertion, state remains zero due to prior reset values.
    check_reset_fall_regs_zero: assert property (
        @(posedge clk) $fell(reset) |-> (shift_reg == 100'b0) && (mux_sel == 1'b0)
    );

    // On reset deassertion, q is zero from zeroed taps.
    check_reset_fall_q_zero: assert property (
        @(posedge clk) $fell(reset) |-> (q == 8'h00)
    );

    // When running, shift_reg shifts and inserts previous mux_sel at bit 0.
    check_shift_reg_update: assert property (
        @(posedge clk) disable iff (reset)
            ($past(reset) === 1'b0) |-> (shift_reg == { $past(shift_reg)[98:0], $past(mux_sel) })
    );

    // When running, mux_sel is XOR of previous shift_reg taps [93,91,87,84].
    check_mux_sel_update: assert property (
        @(posedge clk) disable iff (reset)
            ($past(reset) === 1'b0) |-> (mux_sel == ($past(shift_reg)[93] ^ $past(shift_reg)[91] ^ $past(shift_reg)[87] ^ $past(shift_reg)[84]))
    );

    // When running, q is formed from previous shift_reg taps.
    check_q_update_from_taps: assert property (
        @(posedge clk) disable iff (reset)
            ($past(reset) === 1'b0) |-> (q == { $past(shift_reg)[99], $past(shift_reg)[95], $past(shift_reg)[91], $past(shift_reg)[87], $past(shift_reg)[83], $past(shift_reg)[79], $past(shift_reg)[75], $past(shift_reg)[71] })
    );

    // Zero state is absorbing in run mode (remains zero and outputs zero).
    check_zero_state_absorbing: assert property (
        @(posedge clk) disable iff (reset)
            (($past(reset) === 1'b0) && ($past(shift_reg) == 100'b0) && ($past(mux_sel) == 1'b0))
            |-> (shift_reg == 100'b0) && (mux_sel == 1'b0) && (q == 8'h00)
    );

    // While reset is held, state remains stably zero.
    check_reset_state_stable: assert property (
        @(posedge clk) (reset && ($past(reset) === 1'b1)) |-> $stable(shift_reg) && $stable(mux_sel)
    );

endmodule

rtl:
module nor4 (
    Y  ,
    A  ,
    B  ,
    C_N,
    D_N
);

    output Y  ;
    input  A  ;
    input  B  ;
    input  C_N;
    input  D_N;

    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    wire A_N;
    wire B_N;
    wire C_N_N;
    wire D_N_N;
    wire Y;

    not n1(A_N, A);
    not n2(B_N, B);
    not n3(C_N_N, C_N);
    not n4(D_N_N, D_N);

    nand (Y, A_N, B_N, C_N_N, D_N_N);

endmodule

sva:
module nor4_sva (
    input logic clk,
    input logic Y,
    input logic A,
    input logic B,
    input logic C_N,
    input logic D_N
);
    ///// Combinational function checks /////
    // Y must equal OR of inputs per gate structure.
    check_y_is_or: assert property (
        @(posedge clk) Y == (A || B || C_N || D_N)
    );

    // Y cannot be HIGH unless some input is HIGH.
    check_no_false_high: assert property (
        @(posedge clk) (Y == 1'b1) |-> (A || B || C_N || D_N)
    );

    // When all inputs are LOW, Y must be LOW.
    check_all_low_implies_y_low: assert property (
        @(posedge clk) (A == 1'b0 && B == 1'b0 && C_N == 1'b0 && D_N == 1'b0) |-> (Y == 1'b0)
    );

    // Y is LOW only if all inputs are LOW (no other way to get 0 on OR).
    check_y_low_only_if_all_low: assert property (
        @(posedge clk) (Y == 1'b0) |-> (A == 1'b0 && B == 1'b0 && C_N == 1'b0 && D_N == 1'b0)
    );

    // A being HIGH forces Y HIGH.
    check_A_dominates: assert property (
        @(posedge clk) (A == 1'b1) |-> (Y == 1'b1)
    );

    // B being HIGH forces Y HIGH.
    check_B_dominates: assert property (
        @(posedge clk) (B == 1'b1) |-> (Y == 1'b1)
    );

    // C_N being HIGH forces Y HIGH.
    check_C_N_dominates: assert property (
        @(posedge clk) (C_N == 1'b1) |-> (Y == 1'b1)
    );

    // D_N being HIGH forces Y HIGH.
    check_D_N_dominates: assert property (
        @(posedge clk) (D_N == 1'b1) |-> (Y == 1'b1)
    );

    ///// Edge-sensitive sanity checks /////
    // A rising edge on Y implies some input is HIGH in that cycle.
    check_y_rise_requires_input_high: assert property (
        @(posedge clk) $rose(Y) |-> (A || B || C_N || D_N)
    );

    // A falling edge on Y implies all inputs are LOW in that cycle.
    check_y_fall_requires_all_low: assert property (
        @(posedge clk) $fell(Y) |-> (A == 1'b0 && B == 1'b0 && C_N == 1'b0 && D_N == 1'b0)
    );
endmodule

