sva:
module nor_using_nand_sva (
    input logic clk,
    input logic a,
    input logic b,
    input logic out
);
    // Output implements NAND: out == ~(a & b).
    check_nand_function: assert property (
        @(posedge clk) out == (~(a & b))
    );

    // When both inputs are 1, out is 0.
    check_tt_11_zero: assert property (
        @(posedge clk) (a && b) |-> (out == 1'b0)
    );

    // When any input is 0, out is 1.
    check_any_zero_high: assert property (
        @(posedge clk) ((!a) || (!b)) |-> (out == 1'b1)
    );

    // Out low only if both inputs are 1.
    check_low_only_when_both_one: assert property (
        @(posedge clk) (out == 1'b0) |-> (a && b)
    );

    // DeMorgan equivalence form: out == (~a) || (~b).
    check_demorgan_form: assert property (
        @(posedge clk) out == ((~a) || (~b))
    );

    // If inputs are stable between cycles, output is stable.
    check_stable_inputs_stable_output: assert property (
        @(posedge clk) $stable({a, b}) |-> $stable(out)
    );

    // Output changes only if at least one input changes.
    check_output_change_needs_input_change: assert property (
        @(posedge clk) $changed(out) |-> ($changed(a) || $changed(b))
    );
endmodule

rtl:
module up_down_counter(
    input clk, n_rst, up, dn,
    output [3:0] cnt,
    output out1, out2
);

    reg [3:0] cnt_reg;
    reg [3:0] cnt_next;

    assign out1 = ~cnt_reg[0];
    assign out2 = cnt_reg[0];

    always @ (posedge clk or negedge n_rst) begin
        if (~n_rst) begin
            cnt_reg <= 4'b0;
        end else begin
            cnt_reg <= cnt_next;
        end
    end

    always @ (*) begin
        if (up && !dn && cnt_reg < 4'hf) begin
            cnt_next = cnt_reg + 1;
        end else if (dn && !up && cnt_reg > 4'b0) begin
            cnt_next = cnt_reg - 1;
        end else begin
            cnt_next = cnt_reg;
        end
    end

    assign cnt = cnt_reg;

endmodule

sva:
module up_down_counter_sva (
    input logic clk,
    input logic n_rst,
    input logic up,
    input logic dn,
    input logic [3:0] cnt,
    input logic out1,
    input logic out2
);
    // Clock: clk; Reset: n_rst (active-low, asynchronous)
    // Logic: mixed (seq cnt register with async reset; comb next-state and outputs)
    // Behavior: 4-bit saturating up/down counter; hold when both or none; out2=cnt[0], out1=~cnt[0]

    // During active reset, counter is 0 and outputs reflect LSB
    check_reset_state: assert property (
        @(posedge clk) !n_rst |-> (cnt == 4'd0) && (out2 == 1'b0) && (out1 == 1'b1)
    );

    // out2 always equals cnt LSB
    check_out2_matches_cnt_lsb: assert property (
        @(posedge clk) disable iff (!n_rst) out2 == cnt[0]
    );

    // out1 always equals complement of cnt LSB
    check_out1_complements_cnt_lsb: assert property (
        @(posedge clk) disable iff (!n_rst) out1 == ~cnt[0]
    );

    // Increment by 1 when up=1, dn=0, and not at max (based on previous cycle)
    check_increment_when_up_only: assert property (
        @(posedge clk) disable iff (!n_rst)
            $past(n_rst && up && !dn && (cnt < 4'hf)) |-> (cnt == $past(cnt) + 4'd1)
    );

    // Hold at max when up=1, dn=0, and at 0xF (saturate high)
    check_saturate_at_max_on_up: assert property (
        @(posedge clk) disable iff (!n_rst)
            $past(n_rst && up && !dn && (cnt == 4'hf)) |-> (cnt == 4'hf)
    );

    // Decrement by 1 when dn=1, up=0, and not at zero (based on previous cycle)
    check_decrement_when_dn_only: assert property (
        @(posedge clk) disable iff (!n_rst)
            $past(n_rst && dn && !up && (cnt > 4'd0)) |-> (cnt == $past(cnt) - 4'd1)
    );

    // Hold at zero when dn=1, up=0, and at 0 (saturate low)
    check_saturate_at_zero_on_dn: assert property (
        @(posedge clk) disable iff (!n_rst)
            $past(n_rst && dn && !up && (cnt == 4'd0)) |-> (cnt == 4'd0)
    );

    // Hold when both controls are deasserted
    check_hold_when_both_low: assert property (
        @(posedge clk) disable iff (!n_rst)
            $past(n_rst && !up && !dn) |-> (cnt == $past(cnt))
    );

    // Hold when both controls are asserted
    check_hold_when_both_high: assert property (
        @(posedge clk) disable iff (!n_rst)
            $past(n_rst && up && dn) |-> (cnt == $past(cnt))
    );

    // From mid-range (1..14), next value changes by at most 1 or holds
    check_unit_step_in_midrange: assert property (
        @(posedge clk) disable iff (!n_rst)
            $past(n_rst && (cnt > 4'd0) && (cnt < 4'hf)) |->
                ( (cnt == $past(cnt)) ||
                  (cnt == $past(cnt) + 4'd1) ||
                  (cnt == $past(cnt) - 4'd1) )
    );

endmodule

rtl:
module add_sub (A, B, C, Y);
    input [2:0] A, B;
    input C;
    output [2:0] Y;

    wire [2:0] B_neg;
    assign B_neg = ~B + 1;

    assign Y = C ? A + B_neg : A + B;

endmodule

sva:
module add_sub_sva (
    input  logic        CLK,
    input  logic [2:0]  A,
    input  logic [2:0]  B,
    input  logic        C,
    input  logic [2:0]  Y
);
    // Reference computations (3-bit sized to match RTL behavior)
    logic [2:0] b_neg_ref;
    logic [2:0] add_ref;
    logic [2:0] sub_ref;
    logic [2:0] y_ref;

    assign b_neg_ref = ~B + 3'd1;
    assign add_ref   = A + B;
    assign sub_ref   = A + b_neg_ref;
    assign y_ref     = C ? sub_ref : add_ref;

    // Y always equals the muxed add/sub result.
    check_y_matches_spec: assert property (
        @(posedge CLK) (Y == y_ref)
    );

    // When C==0, Y equals A + B.
    check_y_add_when_c0: assert property (
        @(posedge CLK) (!C) |-> (Y == add_ref)
    );

    // When C==1, Y equals A + (~B + 1).
    check_y_sub_when_c1: assert property (
        @(posedge CLK) (C) |-> (Y == sub_ref)
    );

    // For subtraction mode, Y equals A - B (3-bit wraparound).
    check_y_sub_equiv_minus: assert property (
        @(posedge CLK) (C) |-> (Y == (A - B))
    );

    // If Y changes, at least one of A/B/C changed.
    check_y_change_implies_input_change: assert property (
        @(posedge CLK) $changed(Y) |-> ($changed(A) || $changed(B) || $changed(C))
    );

    // If B is zero, Y equals A regardless of C.
    check_b_zero_y_eq_a: assert property (
        @(posedge CLK) (B == 3'd0) |-> (Y == A)
    );

    // In subtraction mode, equal inputs yield zero.
    check_c1_equal_inputs_y_zero: assert property (
        @(posedge CLK) (C && (A == B)) |-> (Y == 3'd0)
    );

    // In subtraction mode, B==7 increments A by 1 (3-bit wrap).
    check_c1_b_max_incr: assert property (
        @(posedge CLK) (C && (B == 3'd7)) |-> (Y == (A + 3'd1))
    );

    // In addition mode, reversing with -B returns A: (Y + (~B + 1)) == A.
    check_c0_reverse_identity: assert property (
        @(posedge CLK) (!C) |-> ((Y + (~B + 3'd1)) == A)
    );

    // In subtraction mode, reversing with +B returns A: (Y + B) == A.
    check_c1_reverse_identity: assert property (
        @(posedge CLK) (C) |-> ((Y + B) == A)
    );
endmodule

rtl:
module priority_encoder (
    input [3:0] in,
    output reg [1:0] out
);

always @(*) begin
    case(in)
        4'b0001: out = 2'b00;
        4'b0010: out = 2'b01;
        4'b0100: out = 2'b10;
        4'b1000: out = 2'b11;
        default: out = 2'b00;
    endcase
end

endmodule

sva:
module priority_encoder_sva (
    input logic CLK,
    input logic [3:0] in,
    input logic [1:0] out
);
    // Golden model of the combinational encoding.
    function automatic logic [1:0] expected_out (input logic [3:0] vin);
        case (vin)
            4'b0001: expected_out = 2'b00;
            4'b0010: expected_out = 2'b01;
            4'b0100: expected_out = 2'b10;
            4'b1000: expected_out = 2'b11;
            default: expected_out = 2'b00;
        endcase
    endfunction

    // Output matches the case-encoded mapping for all inputs.
    check_functional_mapping: assert property (
        @(posedge CLK) out == expected_out(in)
    );

    // When in is 0001, out is 00.
    check_map_0001: assert property (
        @(posedge CLK) (in == 4'b0001) |=> (out == 2'b00)
    );

    // When in is 0010, out is 01.
    check_map_0010: assert property (
        @(posedge CLK) (in == 4'b0010) |=> (out == 2'b01)
    );

    // When in is 0100, out is 10.
    check_map_0100: assert property (
        @(posedge CLK) (in == 4'b0100) |=> (out == 2'b10)
    );

    // When in is 1000, out is 11.
    check_map_1000: assert property (
        @(posedge CLK) (in == 4'b1000) |=> (out == 2'b11)
    );

    // When in is 0000, out is 00 due to default.
    check_map_0000_default: assert property (
        @(posedge CLK) (in == 4'b0000) |=> (out == 2'b00)
    );

    // For any non-onehot input, out defaults to 00.
    check_non_onehot_defaults_zero: assert property (
        @(posedge CLK) (!(in == 4'b0001 || in == 4'b0010 || in == 4'b0100 || in == 4'b1000)) |=> (out == 2'b00)
    );
endmodule

rtl:
module button_counter (
  input clk,
  input button,
  output reg [2:0] count
);

reg [1:0] state;

always @(posedge clk) begin
  if (button) begin
    count <= count + 1;
    case (state)
      0: state <= 1;
      1: state <= 2;
      2: state <= 3;
      3: state <= 0;
    endcase
  end else begin
    state <= state;
  end
end

endmodule

sva:
module button_counter_sva (
    input logic clk,
    input logic button,
    input logic [2:0] count,
    input logic [1:0] state
);
    // When button is LOW, count holds its value into the next cycle.
    check_count_hold_when_button_low: assert property (
        @(posedge clk) !button |=> (count == $past(count))
    );

    // When button is LOW, state holds its value into the next cycle.
    check_state_hold_when_button_low: assert property (
        @(posedge clk) !button |=> (state == $past(state))
    );

    // When button is HIGH, count increments by 1 (modulo 8) into the next cycle.
    check_count_increment_when_button_high: assert property (
        @(posedge clk) button |=> (count == ($past(count) + 3'd1))
    );

    // When button is HIGH and state==0, next state is 1.
    check_state_advance_0_to_1: assert property (
        @(posedge clk) (button && (state == 2'd0)) |=> (state == 2'd1)
    );

    // When button is HIGH and state==1, next state is 2.
    check_state_advance_1_to_2: assert property (
        @(posedge clk) (button && (state == 2'd1)) |=> (state == 2'd2)
    );

    // When button is HIGH and state==2, next state is 3.
    check_state_advance_2_to_3: assert property (
        @(posedge clk) (button && (state == 2'd2)) |=> (state == 2'd3)
    );

    // When button is HIGH and state==3, next state is 0.
    check_state_advance_3_to_0: assert property (
        @(posedge clk) (button && (state == 2'd3)) |=> (state == 2'd0)
    );

    // When button is HIGH and count==7, next count wraps to 0.
    check_count_wrap_7_to_0: assert property (
        @(posedge clk) (button && (count == 3'd7)) |=> (count == 3'd0)
    );

    // Two consecutive cycles of button HIGH increment count by 2 (modulo 8).
    check_two_cycle_count_increment: assert property (
        @(posedge clk) button[*2] |=> (count == ($past(count,2) + 3'd2))
    );

    // Four consecutive cycles of button HIGH return state to its original value.
    check_state_period_4_when_held_high: assert property (
        @(posedge clk) button[*4] |=> (state == $past(state,4))
    );

    // Eight consecutive cycles of button HIGH return count to its original value.
    check_count_period_8_when_held_high: assert property (
        @(posedge clk) button[*8] |=> (count == $past(count,8))
    );

    // Two consecutive cycles of button LOW keep both count and state unchanged over 2 cycles.
    check_hold_over_two_low_cycles: assert property (
        @(posedge clk) (!button)[*2] |=> (count == $past(count,2)) && (state == $past(state,2))
    );
endmodule

rtl:
module sky130_fd_sc_hd__and2b (
    X  ,
    A_N,
    B
);

    output X  ;
    input  A_N;
    input  B  ;

    wire not0_out  ;
    wire and0_out_X;

    not not0 (not0_out  , A_N            );
    and and0 (and0_out_X, not0_out, B    );
    buf buf0 (X         , and0_out_X     );

endmodule

sva:
module sky130_fd_sc_hd__and2b_sva (
    input logic clk,
    input logic X,
    input logic A_N,
    input logic B
);
    // X equals (~A_N) & B
    check_function_equation: assert property (
        @(posedge clk) X == ((~A_N) & B)
    );

    // When B is 0, X must be 0
    check_x_zero_when_b_zero: assert property (
        @(posedge clk) (B == 1'b0) |-> (X == 1'b0)
    );

    // When A_N is 1, X must be 0
    check_x_zero_when_a_n_one: assert property (
        @(posedge clk) (A_N == 1'b1) |-> (X == 1'b0)
    );

    // When A_N is 0 and B is 1, X must be 1
    check_x_one_when_a0_b1: assert property (
        @(posedge clk) ((A_N == 1'b0) && (B == 1'b1)) |-> (X == 1'b1)
    );

    // On B rising edge with A_N==0, X must be 1
    check_x_one_on_b_rise_when_a0: assert property (
        @(posedge clk) ($rose(B) && (A_N == 1'b0)) |-> (X == 1'b1)
    );

    // On B falling edge, X must be 0
    check_x_zero_on_b_fall: assert property (
        @(posedge clk) $fell(B) |-> (X == 1'b0)
    );

    // On A_N falling edge with B==1, X must be 1
    check_x_one_on_an_fall_when_b1: assert property (
        @(posedge clk) ($fell(A_N) && (B == 1'b1)) |-> (X == 1'b1)
    );

    // On A_N rising edge with B==1, X must be 0
    check_x_zero_on_an_rise_when_b1: assert property (
        @(posedge clk) ($rose(A_N) && (B == 1'b1)) |-> (X == 1'b0)
    );

    // X can only rise when B==1 and A_N==0
    check_x_rise_requires_b1_a0: assert property (
        @(posedge clk) $rose(X) |-> ((B == 1'b1) && (A_N == 1'b0))
    );

    // X can only fall when B==0 or A_N==1
    check_x_fall_requires_b0_or_a1: assert property (
        @(posedge clk) $fell(X) |-> ((B == 1'b0) || (A_N == 1'b1))
    );
endmodule

rtl:
module clock_gate(clk, en, enclk, te);

  input clk;
  input en;
  input te;
  output enclk;

  reg gated_clk;

  always @(posedge clk) begin
    if (en) begin
      if (te) begin
        gated_clk <= 1'b1;
      end else begin
        gated_clk <= 1'b0;
      end
    end else begin
      gated_clk <= 1'b0;
    end
  end

  assign enclk = gated_clk & clk;

endmodule

sva:
module clock_gate_sva (
    input logic clk,
    input logic en,
    input logic te,
    input logic enclk
);
    // enclk must be LOW at each clk posedge (clk is LOW just before the edge).
    check_enclk_low_at_posedge: assert property (
        @(posedge clk) enclk == 1'b0
    );

    // During high phase, enclk equals en & te sampled at prior posedge.
    check_enclk_matches_latched_enable: assert property (
        @(negedge clk)
            ($past(1'b1, 1, posedge clk) == 1'b1)
            |-> (enclk == $past(en && te, 1, posedge clk))
    );

    // If en was LOW at posedge, enclk must be LOW this high phase.
    check_en_low_clears_enclk: assert property (
        @(negedge clk)
            ($past(1'b1, 1, posedge clk) == 1'b1) && ($past(en, 1, posedge clk) == 1'b0)
            |-> (enclk == 1'b0)
    );

    // If te was LOW at posedge, enclk must be LOW this high phase.
    check_te_low_clears_enclk: assert property (
        @(negedge clk)
            ($past(1'b1, 1, posedge clk) == 1'b1) && ($past(te, 1, posedge clk) == 1'b0)
            |-> (enclk == 1'b0)
    );

    // If both en and te were HIGH at posedge, enclk must be HIGH this high phase.
    check_both_high_sets_enclk: assert property (
        @(negedge clk)
            ($past(1'b1, 1, posedge clk) == 1'b1) && ($past(en && te, 1, posedge clk))
            |-> (enclk == 1'b1)
    );

    // A rising enclk at negedge implies en&te latched to 1 now and 0 previously.
    check_enclk_rise_cause: assert property (
        @(negedge clk)
            ($past(1'b1, 1, posedge clk) == 1'b1) && $rose(enclk)
            |-> ($past(en && te, 1, posedge clk) && !$past(en && te, 2, posedge clk))
    );

    // A falling enclk at negedge implies en&te latched to 0 now and 1 previously.
    check_enclk_fall_cause: assert property (
        @(negedge clk)
            ($past(1'b1, 1, posedge clk) == 1'b1) && $fell(enclk)
            |-> (!$past(en && te, 1, posedge clk) && $past(en && te, 2, posedge clk))
    );

    // If en&te were 1 for two consecutive posedges, enclk stays HIGH across two negedges.
    check_enclk_stays_high_when_enable_stays_high: assert property (
        @(negedge clk)
            ($past(1'b1, 1, posedge clk) == 1'b1) &&
            $past(en && te, 1, posedge clk) && $past(en && te, 2, posedge clk)
            |-> (enclk && $past(enclk))
    );

    // If en&te were 0 for two consecutive posedges, enclk stays LOW across two negedges.
    check_enclk_stays_low_when_enable_stays_low: assert property (
        @(negedge clk)
            ($past(1'b1, 1, posedge clk) == 1'b1) &&
            !$past(en && te, 1, posedge clk) && !$past(en && te, 2, posedge clk)
            |-> (!enclk && !$past(enclk))
    );
endmodule

rtl:
module sky130_fd_sc_hvl__or3 (
    X,
    A,
    B,
    C
);

    output X;
    input  A;
    input  B;
    input  C;

    wire or0_out_X;

    or  or0  (or0_out_X, B, A, C        );
    buf buf0 (X        , or0_out_X      );

endmodule

sva:
module sky130_fd_sc_hvl__or3_sva (
    input logic CLK,   // external verification clock (DUT has no clock/reset)
    input logic X,
    input logic A,
    input logic B,
    input logic C
);
    ///// OR3 functional correctness /////
    // X equals logical OR of A,B,C each cycle.
    check_or_function_equivalence: assert property (
        @(posedge CLK) (X == (A | B | C))
    );

    // If A is 1, X must be 1 the same cycle.
    check_a_high_forces_x_high: assert property (
        @(posedge CLK) (A == 1'b1) |-> (X == 1'b1)
    );

    // If B is 1, X must be 1 the same cycle.
    check_b_high_forces_x_high: assert property (
        @(posedge CLK) (B == 1'b1) |-> (X == 1'b1)
    );

    // If C is 1, X must be 1 the same cycle.
    check_c_high_forces_x_high: assert property (
        @(posedge CLK) (C == 1'b1) |-> (X == 1'b1)
    );

    // If all inputs are 0, X must be 0 the same cycle.
    check_all_zero_forces_x_zero: assert property (
        @(posedge CLK) ((A == 1'b0) && (B == 1'b0) && (C == 1'b0)) |-> (X == 1'b0)
    );

    // If X is 0, then all inputs must be 0.
    check_x_zero_implies_all_zero: assert property (
        @(posedge CLK) (X == 1'b0) |-> ((A == 1'b0) && (B == 1'b0) && (C == 1'b0))
    );

    ///// Combinational dependency /////
    // X can only change if at least one input changes.
    check_output_change_requires_input_change: assert property (
        @(posedge CLK) $changed(X) |-> ($changed(A) || $changed(B) || $changed(C))
    );
endmodule

rtl:
module priority_encoder (
    input [7:0] a, b, c, d,
    output [1:0] largest_index);

    wire [7:0] max1, max2, max3;

    assign max1 = (a > b) ? a : b;
    assign max2 = (c > d) ? c : d;
    assign max3 = (max1 > max2) ? max1 : max2;

    assign largest_index = (max3 == a) ? 2'b00 :
                           (max3 == b) ? 2'b01 :
                           (max3 == c) ? 2'b10 :
                                         2'b11;

endmodule

module final_module (
    input [7:0] largest_value, sum,
    output [7:0] final_output);

    assign final_output = sum - largest_value;

endmodule

module top_module (
    input [7:0] a, b, c, d,
    output [7:0] final_output);

    wire [1:0] largest_index;
    wire [7:0] largest_value, sum;

    priority_encoder pe(a, b, c, d, largest_index);
    assign largest_value = (largest_index == 2'b00) ? a :
                           (largest_index == 2'b01) ? b :
                           (largest_index == 2'b10) ? c :
                                                     d;

    assign sum = a + b + c + d;

    final_module fm(largest_value, sum, final_output);

endmodule

sva:
module top_module_sva (
    input  logic        clk,
    input  logic [7:0]  a,
    input  logic [7:0]  b,
    input  logic [7:0]  c,
    input  logic [7:0]  d,
    input  logic [7:0]  final_output
);
    // Local reference model of DUT behavior
    logic [10:0] sum_full;
    logic [7:0]  sum8;
    logic [7:0]  max1, max2, max3;
    logic [7:0]  model_final;
    logic [7:0]  sum_minus_a, sum_minus_b, sum_minus_c, sum_minus_d;
    logic [7:0]  final_plus_max;
    logic [9:0]  three_a_full;
    logic [7:0]  three_a;

    assign sum_full = a + b + c + d;
    assign sum8     = sum_full[7:0];

    assign max1 = (a > b) ? a : b;
    assign max2 = (c > d) ? c : d;
    assign max3 = (max1 > max2) ? max1 : max2;

    assign model_final  = sum8 - max3;
    assign sum_minus_a  = sum8 - a;
    assign sum_minus_b  = sum8 - b;
    assign sum_minus_c  = sum8 - c;
    assign sum_minus_d  = sum8 - d;
    assign final_plus_max = final_output + max3;

    assign three_a_full = a + a + a;
    assign three_a      = three_a_full[7:0];

    // final_output equals (a+b+c+d) - max(a,b,c,d) modulo 256
    check_final_output_sum_minus_max: assert property (
        @(posedge clk) final_output == model_final
    );

    // final_output + max(a,b,c,d) equals (a+b+c+d) modulo 256
    check_final_plus_max_equals_sum: assert property (
        @(posedge clk) final_plus_max == sum8
    );

    // If a is a maximum (ties allowed), final_output == sum - a (mod 256)
    check_subtract_a_when_a_is_max: assert property (
        @(posedge clk) ((a >= b) && (a >= c) && (a >= d)) |-> (final_output == sum_minus_a)
    );

    // If b is a maximum (ties allowed), final_output == sum - b (mod 256)
    check_subtract_b_when_b_is_max: assert property (
        @(posedge clk) ((b >= a) && (b >= c) && (b >= d)) |-> (final_output == sum_minus_b)
    );

    // If c is a maximum (ties allowed), final_output == sum - c (mod 256)
    check_subtract_c_when_c_is_max: assert property (
        @(posedge clk) ((c >= a) && (c >= b) && (c >= d)) |-> (final_output == sum_minus_c)
    );

    // If d is a maximum (ties allowed), final_output == sum - d (mod 256)
    check_subtract_d_when_d_is_max: assert property (
        @(posedge clk) ((d >= a) && (d >= b) && (d >= c)) |-> (final_output == sum_minus_d)
    );

    // If all inputs are equal, final_output equals 3*a modulo 256
    check_all_equal_inputs: assert property (
        @(posedge clk) ((a == b) && (b == c) && (c == d)) |-> (final_output == three_a)
    );

    // If all inputs are zero, final_output must be zero
    check_all_zero_inputs: assert property (
        @(posedge clk) ((a == 8'h00) && (b == 8'h00) && (c == 8'h00) && (d == 8'h00)) |-> (final_output == 8'h00)
    );

    // final_output equals sum minus one of the maximal inputs (ties allowed)
    check_subtract_one_of_maxima: assert property (
        @(posedge clk)
            ( ((a >= b) && (a >= c) && (a >= d) && (final_output == sum_minus_a)) ||
              ((b >= a) && (b >= c) && (b >= d) && (final_output == sum_minus_b)) ||
              ((c >= a) && (c >= b) && (c >= d) && (final_output == sum_minus_c)) ||
              ((d >= a) && (d >= b) && (d >= c) && (final_output == sum_minus_d)) )
    );

    // If the maximum value is zero, final_output equals sum (no subtraction effect)
    check_max_zero_no_effect: assert property (
        @(posedge clk) (max3 == 8'h00) |-> (final_output == sum8)
    );

endmodule

rtl:
module uart_baud_clk
#(
  parameter SYS_CLK_FREQ             = 50000000,
  parameter BAUD                     = 19200,
  parameter BAUD_CLK_OVERSAMPLE_RATE = 16
)
(
  input  wire clk,
  input  wire reset,
  output wire baud_clk_tick
);

localparam [15:0] CLKS_PER_OVERSAMPLE_TICK = (SYS_CLK_FREQ / BAUD) / BAUD_CLK_OVERSAMPLE_RATE;

// Registers
reg  [15:0] q_cnt;
wire [15:0] d_cnt;

always @(posedge clk, posedge reset)
  begin
    if (reset)
      q_cnt <= 0;
    else
      q_cnt <= d_cnt;
  end

assign d_cnt         = (q_cnt == (CLKS_PER_OVERSAMPLE_TICK - 1)) ? 16'h0000 : (q_cnt + 16'h0001);
assign baud_clk_tick = (q_cnt == (CLKS_PER_OVERSAMPLE_TICK - 1)) ? 1'b1     : 1'b0;

endmodule

sva:
module uart_baud_clk_sva (
    input logic clk,
    input logic reset,
    input logic baud_clk_tick,
    input logic [15:0] q_cnt,
    input logic [15:0] d_cnt
);
    // On reset, counter must be 0.
    check_reset_clears_counter: assert property (
        @(posedge clk) reset |-> (q_cnt == 16'h0000)
    );

    // While reset is held, counter stays 0 into the next cycle.
    check_reset_holds_zero: assert property (
        @(posedge clk) reset |=> (q_cnt == 16'h0000)
    );

    // q_cnt updates from previous cycle's d_cnt (when not in reset).
    check_q_cnt_follows_d_cnt: assert property (
        @(posedge clk) disable iff (reset) 1'b1 |=> (q_cnt == $past(d_cnt))
    );

    // If previous cycle had a tick, q_cnt wraps to 0 this cycle.
    check_next_on_prev_tick: assert property (
        @(posedge clk) disable iff (reset) ($past(baud_clk_tick) && !$past(reset)) |-> (q_cnt == 16'h0000)
    );

    // If previous cycle had no tick, q_cnt increments by 1 this cycle.
    check_next_on_prev_no_tick: assert property (
        @(posedge clk) disable iff (reset) (!$past(baud_clk_tick) && !$past(reset)) |-> (q_cnt == ($past(q_cnt) + 16'h0001))
    );

    // After any non-reset cycle, q_cnt is either 0 or previous+1.
    check_monotonic_or_wrap: assert property (
        @(posedge clk) disable iff (reset) (!$past(reset)) |-> ((q_cnt == 16'h0000) || (q_cnt == ($past(q_cnt) + 16'h0001)))
    );

    // d_cnt equals 0 when tick is 1, else it equals q_cnt+1 (combinational definition).
    check_d_cnt_matches_tick_logic: assert property (
        @(posedge clk) disable iff (reset) d_cnt == (baud_clk_tick ? 16'h0000 : (q_cnt + 16'h0001))
    );

    // Tick pulses are single-cycle: next cycle must be LOW.
    check_tick_single_cycle_next_low: assert property (
        @(posedge clk) disable iff (reset) baud_clk_tick |=> !baud_clk_tick
    );

    // No back-to-back tick HIGHs: previous cycle must be LOW.
    check_tick_not_back_to_back_prev_low: assert property (
        @(posedge clk) disable iff (reset) baud_clk_tick |-> !$past(baud_clk_tick)
    );

    // A tick this cycle forces next q_cnt to 0.
    check_tick_implies_next_cnt_zero: assert property (
        @(posedge clk) disable iff (reset) baud_clk_tick |=> (q_cnt == 16'h0000)
    );
endmodule

rtl:
module sky130_fd_sc_ls__a21oi (
    Y ,
    A1,
    A2,
    B1
);

    output Y ;
    input  A1;
    input  A2;
    input  B1;

    wire n1, n2, n3, n4, n5, n6, n7;

    not (n1, A1);
    not (n2, A2);
    not (n3, B1);

    and (n4, n1, n2);
    and (n5, n1, B1);
    and (n6, A2, n3);
    and (n7, n6, n3);

    or (Y, n4, n5, n7);

endmodule

sva:
module sky130_fd_sc_ls__a21oi_sva (
    input logic CLK,
    input logic Y,
    input logic A1,
    input logic A2,
    input logic B1
);
    // Functional equivalence: Y = ~A1 | (A2 & ~B1).
    check_func_equiv: assert property (
        @(posedge CLK) Y == ((~A1) | (A2 & ~B1))
    );

    // If A1 is 0 then Y must be 1.
    check_y_high_when_a1_low: assert property (
        @(posedge CLK) (~A1) |-> (Y == 1'b1)
    );

    // If A1=1 and A2=0 then Y=0.
    check_y_low_when_a1_1_a2_0: assert property (
        @(posedge CLK) (A1 & ~A2) |-> (Y == 1'b0)
    );

    // If A1=1 and B1=1 then Y=0.
    check_y_low_when_a1_1_b1_1: assert property (
        @(posedge CLK) (A1 & B1) |-> (Y == 1'b0)
    );

    // If A2=1 and B1=0 then Y=1.
    check_y_high_when_a2_1_b1_0: assert property (
        @(posedge CLK) (A2 & ~B1) |-> (Y == 1'b1)
    );

    // When A1=1 and B1=0, Y equals A2.
    check_y_eq_a2_when_a1_1_b1_0: assert property (
        @(posedge CLK) (A1 & ~B1) |-> (Y == A2)
    );

    // When B1=1, Y equals ~A1.
    check_y_eq_not_a1_when_b1_1: assert property (
        @(posedge CLK) (B1) |-> (Y == ~A1)
    );

    // If Y is 0 then A1=1 and (A2=0 or B1=1).
    check_inputs_when_y0: assert property (
        @(posedge CLK) (Y == 1'b0) |-> (A1 & (~A2 | B1))
    );

    // If Y is 1 then (~A1) or (A2=1 and B1=0).
    check_inputs_when_y1: assert property (
        @(posedge CLK) (Y == 1'b1) |-> ((~A1) | (A2 & ~B1))
    );

    // With B1=0, Y equals (~A1 | A2).
    check_simplify_when_b1_0: assert property (
        @(posedge CLK) (~B1) |-> (Y == ((~A1) | A2))
    );
endmodule

rtl:
module ripple_carry_adder(
    input [3:0] A,
    input [3:0] B,
    input CI,
    output [3:0] S,
    output CO
);

    wire [4:0] C;
    full_adder fa0(.CO(C[0]), .S(S[0]), .A(A[0]), .B(B[0]), .CI(CI));
    full_adder fa1(.CO(C[1]), .S(S[1]), .A(A[1]), .B(B[1]), .CI(C[0]));
    full_adder fa2(.CO(C[2]), .S(S[2]), .A(A[2]), .B(B[2]), .CI(C[1]));
    full_adder fa3(.CO(CO), .S(S[3]), .A(A[3]), .B(B[3]), .CI(C[2]));

endmodule

module full_adder (
    input A,
    input B,
    input CI,
    output S,
    output CO
);

    assign {CO, S} = A + B + CI;

endmodule

sva:
module ripple_carry_adder_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic CI,
    input logic [3:0] S,
    input logic CO
);
    // Functional correctness: 5-bit sum equals A+B+CI.
    check_sum_matches_addition: assert property (
        @(posedge $global_clock) {CO, S} == ({1'b0, A} + {1'b0, B} + CI)
    );

    // Carry-out equals MSB of the 5-bit sum.
    check_carry_msb_of_sum: assert property (
        @(posedge $global_clock) CO == (({1'b0, A} + {1'b0, B} + CI)[4])
    );

    // LSB sum bit equals XOR of A[0], B[0], and CI.
    check_lsb_xor: assert property (
        @(posedge $global_clock) S[0] == (A[0] ^ B[0] ^ CI)
    );

    // When B==0 and CI==0, output is A (no carry).
    check_passthrough_a_when_b_zero_ci_zero: assert property (
        @(posedge $global_clock) (B == 4'd0 && CI == 1'b0) |-> ({CO, S} == {1'b0, A})
    );

    // When B==0 and CI==1, output is A+1 (with possible carry).
    check_increment_a_when_b_zero_ci_one: assert property (
        @(posedge $global_clock) (B == 4'd0 && CI == 1'b1) |-> ({CO, S} == ({1'b0, A} + 5'd1))
    );

    // When A==0 and CI==0, output is B (no carry).
    check_passthrough_b_when_a_zero_ci_zero: assert property (
        @(posedge $global_clock) (A == 4'd0 && CI == 1'b0) |-> ({CO, S} == {1'b0, B})
    );

    // When A==0 and CI==1, output is B+1 (with possible carry).
    check_increment_b_when_a_zero_ci_one: assert property (
        @(posedge $global_clock) (A == 4'd0 && CI == 1'b1) |-> ({CO, S} == ({1'b0, B} + 5'd1))
    );

    // Max case: A=15, B=15, CI=1 -> result is 31 (all ones).
    check_all_ones_with_cin_one_full_scale: assert property (
        @(posedge $global_clock) (A == 4'hF && B == 4'hF && CI == 1'b1) |-> ({CO, S} == 5'b1_1111)
    );

    // All zeros with CI=0 -> result is zero.
    check_zero_zero_zero: assert property (
        @(posedge $global_clock) (A == 4'd0 && B == 4'd0 && CI == 1'b0) |-> ({CO, S} == 5'd0)
    );

    // Commutativity: swapping A and B does not change the result.
    check_commutativity: assert property (
        @(posedge $global_clock) {CO, S} == ({1'b0, B} + {1'b0, A} + CI)
    );
endmodule

rtl:
module mux2 (
    X,
    A0,
    A1,
    S
);

    output X;
    input A0;
    input A1;
    input S;

    assign X = (S == 0) ? A0 : A1;

endmodule

sva:
module mux2_sva (
    input logic CLK,
    input logic X,
    input logic A0,
    input logic A1,
    input logic S
);
    // When S is 0, X equals A0.
    check_sel0_output_matches_A0: assert property (
        @(posedge CLK) disable iff ($initstate) (S === 1'b0) |-> (X === A0)
    );

    // When S is 1, X equals A1.
    check_sel1_output_matches_A1: assert property (
        @(posedge CLK) disable iff ($initstate) (S === 1'b1) |-> (X === A1)
    );

    // If A0 equals A1, X equals that value regardless of S.
    check_equal_inputs_drive_X: assert property (
        @(posedge CLK) disable iff ($initstate) (A0 === A1) |-> (X === A0)
    );

    // If inputs differ and X equals A0, S must be 0.
    check_consistency_X_eq_A0_implies_S0_when_inputs_differ: assert property (
        @(posedge CLK) disable iff ($initstate) ((A0 !== A1) && (X === A0)) |-> (S === 1'b0)
    );

    // If inputs differ and X equals A1, S must be 1.
    check_consistency_X_eq_A1_implies_S1_when_inputs_differ: assert property (
        @(posedge CLK) disable iff ($initstate) ((A0 !== A1) && (X === A1)) |-> (S === 1'b1)
    );

    // If S, A0, and A1 are stable, X is stable.
    check_stability_when_all_stable: assert property (
        @(posedge CLK) disable iff ($initstate) ($stable(S) && $stable(A0) && $stable(A1)) |-> $stable(X)
    );

    // On S rising edge with stable inputs, X now equals A1 and previously equaled A0.
    check_switch_to_A1_on_sel_rise_when_inputs_stable: assert property (
        @(posedge CLK) disable iff ($initstate) ($rose(S) && $stable(A0) && $stable(A1)) |-> ((X === A1) && ($past(X) === $past(A0)))
    );

    // On S falling edge with stable inputs, X now equals A0 and previously equaled A1.
    check_switch_to_A0_on_sel_fall_when_inputs_stable: assert property (
        @(posedge CLK) disable iff ($initstate) ($fell(S) && $stable(A0) && $stable(A1)) |-> ((X === A0) && ($past(X) === $past(A1)))
    );
endmodule

rtl:
module TLATNTSCAX2TS(E, SE, CK, ECK);

  input E, SE, CK;
  output ECK;

  assign ECK = SE ? CK : E ? 1'b1 : 1'b0;

endmodule

module register_clock_gate(CLK, EN, TE, ENCLK);

  input CLK;
  input EN;
  input TE;
  output ENCLK;

  TLATNTSCAX2TS latch (.E(EN), .SE(TE), .CK(CLK), .ECK(ENCLK));

endmodule

sva:
module register_clock_gate_sva (
    input logic CLK,
    input logic EN,
    input logic TE,
    input logic ENCLK
);
    // Analysis: clock=CLK; no reset in RTL; logic is purely combinational; behavior: ENCLK = (TE ? CLK : EN).

    // ENCLK implements the exact mux function defined by RTL.
    check_functional_mux: assert property (
        @(posedge CLK) ENCLK == (TE ? CLK : EN)
    );

    // When TE=1, ENCLK must mirror CLK.
    check_te_selects_clk: assert property (
        @(posedge CLK) TE |-> (ENCLK == CLK)
    );

    // When TE=0, ENCLK must equal EN.
    check_te0_selects_en: assert property (
        @(posedge CLK) !TE |-> (ENCLK == EN)
    );

    // If ENCLK is LOW at CLK posedge, then TE=0 and EN=0.
    check_out_low_conditions: assert property (
        @(posedge CLK) (ENCLK == 1'b0) |-> (!TE && (EN == 1'b0))
    );

    // If ENCLK is HIGH at CLK posedge, then TE=1 or EN=1.
    check_out_high_conditions: assert property (
        @(posedge CLK) (ENCLK == 1'b1) |-> (TE || (EN == 1'b1))
    );
endmodule

