sva:
module sky130_fd_sc_lp__einvp_sva (
    input logic Z,
    input logic A,
    input logic TE
);
    // When enabled (TE=1), Z must be the bitwise NOT of A.
    check_enable_inverts: assert property (TE === 1'b1 |-> (Z === ~A));

    // When disabled (TE=0), Z must be high-impedance.
    check_disable_tristate: assert property (TE === 1'b0 |-> (Z === 1'bz));

    // Z can be high-impedance only when disabled (TE=0).
    check_z_only_when_disabled: assert property ((Z === 1'bz) |-> (TE === 1'b0));
endmodule

rtl:
module shift_adder(
    input clk,
    input load,
    input [31:0] a,
    input [31:0] b,
    input sub,
    output [31:0] sum
);

    reg [7:0] shift_reg;
    wire [31:0] adder_input;
    wire [31:0] adder_output;

    // Shift register with parallel load
    always @(posedge clk) begin
        if (load) begin
            shift_reg <= a[7:0];
        end else begin
            shift_reg <= {shift_reg[6:0], shift_reg[7]};
        end
    end

    // Adder module
    assign adder_input = {shift_reg, b};
    assign adder_output = sub ? {32{1'b0}} - adder_input : adder_input;

    // Output sum
    assign sum = adder_output;

endmodule

sva:
module shift_adder_sva (
    input logic clk,
    input logic load,
    input logic [31:0] a,
    input logic [31:0] b,
    input logic sub,
    input logic [31:0] sum
);

    // Sum equals b when adding, or (0 - b) when subtracting.
    check_sum_function: assert property (
        @(posedge clk) sum == (sub ? (32'h0000_0000 - b) : b)
    );

    // When not subtracting, sum mirrors b.
    check_sum_when_add: assert property (
        @(posedge clk) (!sub) |-> (sum == b)
    );

    // When subtracting, sum + b == 0 (two's complement negation).
    check_sum_when_sub: assert property (
        @(posedge clk) sub |-> ((sum + b) == 32'h0000_0000)
    );

    // If b and sub are stable, sum must remain stable.
    check_sum_stable_if_b_sub_stable: assert property (
        @(posedge clk) $stable(b) && $stable(sub) |-> $stable(sum)
    );

    // If sum changes, either b or sub must have changed.
    check_sum_change_implies_b_or_sub_change: assert property (
        @(posedge clk) $changed(sum) |-> ($changed(b) || $changed(sub))
    );

    // If b is zero, sum must be zero regardless of sub.
    check_sum_zero_when_b_zero: assert property (
        @(posedge clk) (b == 32'h0000_0000) |-> (sum == 32'h0000_0000)
    );

    // Subtracting the most-negative value returns itself (overflow wraps).
    check_sum_minint_case_when_sub: assert property (
        @(posedge clk) (sub && (b == 32'h8000_0000)) |-> (sum == 32'h8000_0000)
    );

    // Changes on a alone (with b and sub stable) cannot change sum.
    check_sum_ignores_a: assert property (
        @(posedge clk) $changed(a) && $stable(b) && $stable(sub) |-> $stable(sum)
    );

    // Changes on load alone (with b and sub stable) cannot change sum.
    check_sum_ignores_load: assert property (
        @(posedge clk) $changed(load) && $stable(b) && $stable(sub) |-> $stable(sum)
    );

    // On sub rising edge with b stable, sum equals (0 - b) in that cycle.
    check_sum_on_sub_rise: assert property (
        @(posedge clk) $rose(sub) && $stable(b) |-> (sum == (32'h0000_0000 - b))
    );

    // On sub falling edge with b stable, sum equals b in that cycle.
    check_sum_on_sub_fall: assert property (
        @(posedge clk) $fell(sub) && $stable(b) |-> (sum == b)
    );

endmodule

rtl:
module xnor4to1 (
    input  A,
    input  B,
    input C,
    input D,
    output Y
);

assign Y = ~(A ^ B ^ C ^ D);

endmodule

sva:
module xnor4to1_sva (
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic Y
);
    // Y must equal the 4-input XNOR of A,B,C,D.
    check_y_matches_xnor: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C or negedge C or posedge D or negedge D)
        Y == ~(A ^ B ^ C ^ D)
    );

    // If A==B and C==D, Y must be 1.
    check_pairs_equal_y1: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C or negedge C or posedge D or negedge D)
        ((A == B) && (C == D)) |-> (Y == 1'b1)
    );

    // If exactly one of (A==B) or (C==D) holds, Y must be 0.
    check_one_pair_equal_y0: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C or negedge C or posedge D or negedge D)
        (((A == B) ^ (C == D)) == 1'b1) |-> (Y == 1'b0)
    );

    // If A!=B and C!=D, Y must be 1.
    check_no_pairs_equal_y1: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C or negedge C or posedge D or negedge D)
        ((A != B) && (C != D)) |-> (Y == 1'b1)
    );

endmodule

module comparator_2bit_sva (
    input logic [1:0] A,
    input logic [1:0] B,
    input logic       EQ
);
    // No explicit clock/reset in RTL; sample on any input/output edge.
    localparam dummy = 1'b0;

    // EQ must be 1 when A equals B (4-state equality).
    check_eq_when_equal: assert property (
        @(posedge A[0] or negedge A[0] or posedge A[1] or negedge A[1]
        or posedge B[0] or negedge B[0] or posedge B[1] or negedge B[1]
        or posedge EQ or negedge EQ)
        (A == B) |-> (EQ == 1'b1)
    );

    // EQ must be 0 when A does not equal B (4-state inequality is true).
    check_eq_low_when_unequal: assert property (
        @(posedge A[0] or negedge A[0] or posedge A[1] or negedge A[1]
        or posedge B[0] or negedge B[0] or posedge B[1] or negedge B[1]
        or posedge EQ or negedge EQ)
        (A != B) |-> (EQ == 1'b0)
    );

    // If EQ is 1, inputs must be equal.
    check_eq_one_implies_equal: assert property (
        @(posedge A[0] or negedge A[0] or posedge A[1] or negedge A[1]
        or posedge B[0] or negedge B[0] or posedge B[1] or negedge B[1]
        or posedge EQ or negedge EQ)
        (EQ == 1'b1) |-> (A == B)
    );

    // Output is binary 0/1 (never X/Z at sampling times).
    check_output_is_binary: assert property (
        @(posedge A[0] or negedge A[0] or posedge A[1] or negedge A[1]
        or posedge B[0] or negedge B[0] or posedge B[1] or negedge B[1]
        or posedge EQ or negedge EQ)
        (EQ inside {1'b0, 1'b1})
    );

    // If inputs are stable, output must be stable (pure combinational behavior).
    check_stable_inputs_keep_output_stable: assert property (
        @(posedge A[0] or negedge A[0] or posedge A[1] or negedge A[1]
        or posedge B[0] or negedge B[0] or posedge B[1] or negedge B[1]
        or posedge EQ or negedge EQ)
        ($stable(A) && $stable(B)) |-> $stable(EQ)
    );

    // Output changes only if at least one input changed.
    check_output_change_requires_input_change: assert property (
        @(posedge A[0] or negedge A[0] or posedge A[1] or negedge A[1]
        or posedge B[0] or negedge B[0] or posedge B[1] or negedge B[1]
        or posedge EQ or negedge EQ)
        $changed(EQ) |-> (!$stable(A) || !$stable(B))
    );
endmodule

rtl:
module binary_adder_4bit(
    input [3:0] A, 
    input [3:0] B, 
    input CI, 
    input CLK, 
    output reg [3:0] SUM, 
    output CO
);

reg [4:0] C;

always @(posedge CLK) begin
    SUM <= A + B + C[3:0];
    C <= (A + B + C) > 4'b1111 ? 1 : 0;
end

assign CO = C[4];

endmodule

sva:
module binary_adder_4bit_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic CI,
    input logic CLK,
    input logic [3:0] SUM,
    input logic CO
);
    // CO never has a rising edge (MSB of C is never driven to 1 by the RTL).
    check_co_never_rises: assert property (
        @(posedge CLK) !$rose(CO)
    );

    // If CO is HIGH now, it must be LOW on the next cycle.
    check_co_clears_next_if_high: assert property (
        @(posedge CLK) (CO == 1'b1) |=> (CO == 1'b0)
    );

    // Once CO is LOW, it remains LOW on the next cycle.
    check_co_low_sticky: assert property (
        @(posedge CLK) (CO == 1'b0) |=> (CO == 1'b0)
    );

    // From any time, CO becomes LOW within two cycles and thus cannot persist HIGH.
    check_co_eventually_low_within_two: assert property (
        @(posedge CLK) 1'b1 |-> ##[0:2] (CO == 1'b0)
    );

    // After any falling edge of CO, it stays LOW forever.
    check_co_stays_low_after_fall: assert property (
        @(posedge CLK) $fell(CO) |-> (CO == 1'b0)[*1:$]
    );

    // If A and B are zero for three consecutive cycles and CO is LOW at the first, SUM is zero on the third.
    check_sum_zero_after_three_zero_inputs_when_co_zero: assert property (
        @(posedge CLK)
            ((CO == 1'b0) && (A == 4'b0000) && (B == 4'b0000)) ##1
            ((A == 4'b0000) && (B == 4'b0000)) ##1
            ((A == 4'b0000) && (B == 4'b0000) && (SUM == 4'b0000))
    );
endmodule

rtl:
module mux(
    input in0,
    input in1,
    input sel,
    output out
);

assign out = sel ? in1 : in0;

endmodule

sva:
module mux_sva (
    // Note: RTL has no clock/reset; use CLK only for sampling assertions.
    input logic CLK,
    input logic in0,
    input logic in1,
    input logic sel,
    input logic out
);
    // out equals selected input per mux function.
    check_mux_equivalence: assert property (
        @(posedge CLK) out == (sel ? in1 : in0)
    );

    // When sel is 0, out mirrors in0.
    check_sel0_path: assert property (
        @(posedge CLK) (sel == 1'b0) |-> (out == in0)
    );

    // When sel is 1, out mirrors in1.
    check_sel1_path: assert property (
        @(posedge CLK) (sel == 1'b1) |-> (out == in1)
    );

    // On a rising edge of sel, out equals in1 in the same cycle.
    check_sel_rise_selects_in1: assert property (
        @(posedge CLK) $rose(sel) |-> (out == in1)
    );

    // On a falling edge of sel, out equals in0 in the same cycle.
    check_sel_fall_selects_in0: assert property (
        @(posedge CLK) $fell(sel) |-> (out == in0)
    );

    // If inputs are equal, out equals that common value regardless of sel.
    check_inputs_equal_forces_out: assert property (
        @(posedge CLK) (in0 == in1) |-> (out == in0)
    );

    // If sel and both inputs are stable, out must be stable.
    check_no_spurious_change: assert property (
        @(posedge CLK) $stable(sel) && $stable(in0) && $stable(in1) |-> $stable(out)
    );

    // Out can change only if at least one of sel/in0/in1 changes.
    check_out_change_has_cause: assert property (
        @(posedge CLK) $changed(out) |-> ($changed(sel) || $changed(in0) || $changed(in1))
    );
endmodule

