             m_iob_fm_datai, m_iob_fm_status, m_rdi_pulse}
    );
    // IOS bus passes through to s0.
    check_s0_ios_passthrough: assert property (
        @(posedge clk) disable iff (reset) s0_ios == m_ios
    );
    // IOB write bus passes through to s0.
    check_s0_write_passthrough: assert property (
        @(posedge clk) disable iff (reset) s0_iob_write == m_iob_write
    );

    ///// Pass-through from master to slave 1 /////
    // All 1-bit control/status signals pass through to s1.
    check_s1_ctrl_passthrough: assert property (
        @(posedge clk) disable iff (reset)
            {s1_iob_poweron, s1_iob_reset, s1_datao_clear, s1_datao_set, s1_cono_clear, s1_cono_set,
             s1_iob_fm_datai, s1_iob_fm_status, s1_rdi_pulse}
          =={m_iob_poweron, m_iob_reset, m_datao_clear, m_datao_set, m_cono_clear, m_cono_set,
             m_iob_fm_datai, m_iob_fm_status, m_rdi_pulse}
    );
    // IOS bus passes through to s1.
    check_s1_ios_passthrough: assert property (
        @(posedge clk) disable iff (reset) s1_ios == m_ios
    );
    // IOB write bus passes through to s1.
    check_s1_write_passthrough: assert property (
        @(posedge clk) disable iff (reset) s1_iob_write == m_iob_write
    );

    ///// Pass-through from master to slave 2 /////
    // All 1-bit control/status signals pass through to s2.
    check_s2_ctrl_passthrough: assert property (
        @(posedge clk) disable iff (reset)
            {s2_iob_poweron, s2_iob_reset, s2_datao_clear, s2_datao_set, s2_cono_clear, s2_cono_set,
             s2_iob_fm_datai, s2_iob_fm_status, s2_rdi_pulse}
          =={m_iob_poweron, m_iob_reset, m_datao_clear, m_datao_set, m_cono_clear, m_cono_set,
             m_iob_fm_datai, m_iob_fm_status, m_rdi_pulse}
    );
    // IOS bus passes through to s2.
    check_s2_ios_passthrough: assert property (
        @(posedge clk) disable iff (reset) s2_ios == m_ios
    );
    // IOB write bus passes through to s2.
    check_s2_write_passthrough: assert property (
        @(posedge clk) disable iff (reset) s2_iob_write == m_iob_write
    );
endmodule

rtl:
module binary_counter (
  input clk,
  input reset,
  input enable,
  output reg [3:0] count
);

  // Define states
  localparam IDLE = 2'b00;
  localparam COUNT = 2'b01;

  // Define state register and next state logic
  reg [1:0] state, next_state;
  always @ (posedge clk, negedge reset) begin
    if (reset == 1'b0) begin
      state <= IDLE;
    end else begin
      state <= next_state;
    end
  end

  // Define counter
  reg [3:0] counter;

  // Define output logic
  always @ (*) begin
    count = counter;
  end

  // Define state machine
  always @ (state, enable) begin
    case (state)
      IDLE: begin
        if (enable) begin
          next_state = COUNT;
        end else begin
          next_state = IDLE;
        end
      end
      COUNT: begin
        if (counter == 4'b1111) begin
          next_state = IDLE;
          counter <= 4'b0000;
        end else begin
          next_state = COUNT;
          counter <= counter + 1;
        end
      end
      default: next_state = IDLE;
    endcase
  end

endmodule

sva:
module binary_counter_sva (
    input logic clk,
    input logic reset,
    input logic enable,
    input logic [3:0] count,
    input logic [1:0] state,
    input logic [1:0] next_state,
    input logic [3:0] counter
);
    // State encodings from RTL
    localparam logic [1:0] IDLE  = 2'b00;
    localparam logic [1:0] COUNT = 2'b01;

    // Output mirrors internal counter.
    check_count_mirrors_counter: assert property (
        @(posedge clk) count == counter
    );

    // While reset is asserted low, state must be IDLE.
    check_state_idle_during_reset: assert property (
        @(posedge clk) (reset == 1'b0) |-> (state == IDLE)
    );

    // When not in reset, state updates from previous next_state.
    check_state_follows_next_state: assert property (
        @(posedge clk) disable iff (reset == 1'b0) state == $past(next_state)
    );

    // next_state only takes defined encodings.
    check_next_state_enum: assert property (
        @(posedge clk) disable iff (reset == 1'b0) next_state inside {IDLE, COUNT}
    );

    // state only takes defined encodings when not in reset.
    check_state_enum: assert property (
        @(posedge clk) disable iff (reset == 1'b0) state inside {IDLE, COUNT}
    );

    // In IDLE with enable=1, next_state is COUNT.
    check_idle_enable_to_count: assert property (
        @(posedge clk) disable iff (reset == 1'b0) (state == IDLE && enable) |-> (next_state == COUNT)
    );

    // In IDLE with enable=0, next_state is IDLE.
    check_idle_no_enable_stays_idle: assert property (
        @(posedge clk) disable iff (reset == 1'b0) (state == IDLE && !enable) |-> (next_state == IDLE)
    );

    // In COUNT with counter==15, next_state is IDLE.
    check_count_max_to_idle: assert property (
        @(posedge clk) disable iff (reset == 1'b0) (state == COUNT && counter == 4'hF) |-> (next_state == IDLE)
    );

    // In COUNT with counter!=15, next_state is COUNT.
    check_count_not_max_stays_count: assert property (
        @(posedge clk) disable iff (reset == 1'b0) (state == COUNT && counter != 4'hF) |-> (next_state == COUNT)
    );

    // One-cycle: IDLE with enable=0 leads to state IDLE.
    check_idle_enable0_next_state_idle: assert property (
        @(posedge clk) disable iff (reset == 1'b0) (state == IDLE && !enable) |=> (state == IDLE)
    );

    // One-cycle: IDLE with enable=1 leads to state COUNT.
    check_idle_enable1_next_state_count: assert property (
        @(posedge clk) disable iff (reset == 1'b0) (state == IDLE && enable) |=> (state == COUNT)
    );

    // One-cycle: COUNT with counter==15 leads to state IDLE.
    check_count_max_next_state_idle: assert property (
        @(posedge clk) disable iff (reset == 1'b0) (state == COUNT && counter == 4'hF) |=> (state == IDLE)
    );

    // One-cycle: COUNT with counter!=15 leads to state COUNT.
    check_count_notmax_next_state_count: assert property (
        @(posedge clk) disable iff (reset == 1'b0) (state == COUNT && counter != 4'hF) |=> (state == COUNT)
    );

    // If state is an unknown encoding, default drives next_state to IDLE.
    check_default_next_state_idle: assert property (
        @(posedge clk) disable iff (reset == 1'b0) (!(state inside {IDLE, COUNT})) |-> (next_state == IDLE)
    );
endmodule

rtl:
module four_bit_adder (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    input CLK,
    output reg [3:0] S,
    output reg Cout
);

reg [4:0] sum;

always @(posedge CLK) begin
    sum = A + B + Cin;
    S = sum[3:0];
    Cout = sum[4];
end

endmodule

sva:
module four_bit_adder_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic Cin,
    input logic CLK,
    input logic [3:0] S,
    input logic Cout
);
    // Clock: CLK; no reset in RTL
    // Sequential: registered 4-bit adder updated on posedge CLK
    // Behavior: {Cout,S} is the 5-bit sum of A+B+Cin (observed one cycle later)

    ///// Functional correctness /////
    // Outputs equal prior-cycle 5-bit sum of inputs.
    check_sum_pipelined: assert property (
        @(posedge CLK) {Cout, S} == ($past(A) + $past(B) + $past(Cin))
    );

    // S equals the lower 4 bits of the prior-cycle sum.
    check_sum_low_bits: assert property (
        @(posedge CLK) S == (($past(A) + $past(B) + $past(Cin))[3:0])
    );

    // Cout equals the MSB of the prior-cycle 5-bit sum.
    check_carry_msb: assert property (
        @(posedge CLK) Cout == (($past(A) + $past(B) + $past(Cin))[4])
    );

    // Cout asserted iff the prior-cycle sum exceeds 15.
    check_carry_threshold: assert property (
        @(posedge CLK) Cout == (($past(A) + $past(B) + $past(Cin)) >= 5'd16)
    );

    ///// Temporal consistency /////
    // If A,B,Cin are stable over a cycle, the next output sample is unchanged.
    check_hold_when_inputs_stable: assert property (
        @(posedge CLK) ($stable(A) && $stable(B) && $stable(Cin)) |-> ##1 ({Cout, S} == $past({Cout, S}))
    );

    // With A,B stable, a rising Cin increments the next output by 1.
    check_increment_on_cin_rise: assert property (
        @(posedge CLK) ($stable(A) && $stable(B) && ($past(Cin) == 1'b0) && (Cin == 1'b1)) |-> ##1 ({Cout, S} == $past({Cout, S}) + 5'd1)
    );

    // With A,B stable, a falling Cin decrements the next output by 1.
    check_decrement_on_cin_fall: assert property (
        @(posedge CLK) ($stable(A) && $stable(B) && ($past(Cin) == 1'b1) && (Cin == 1'b0)) |-> ##1 ({Cout, S} == $past({Cout, S}) - 5'd1)
    );

    ///// Corner cases /////
    // Prior-cycle inputs all zero produce zero output.
    check_zero_case: assert property (
        @(posedge CLK) ($past(A) == 4'd0 && $past(B) == 4'd0 && $past(Cin) == 1'b0) |-> ({Cout, S} == 5'd0)
    );

    // Prior-cycle A=15, B=15, Cin=1 produce 31 (all ones) at output.
    check_max_case: assert property (
        @(posedge CLK) ($past(A) == 4'd15 && $past(B) == 4'd15 && $past(Cin) == 1'b1) |-> ({Cout, S} == 5'd31)
    );

    ///// Algebraic consistency /////
    // Swapping A and B across cycles with Cin stable leaves next output unchanged.
    check_commutativity_swap: assert property (
        @(posedge CLK) ((A == $past(B)) && (B == $past(A)) && (Cin == $past(Cin))) |-> ##1 ({Cout, S} == $past({Cout, S}))
    );

endmodule

module freq_divider_sva (
    input logic clk,
    input logic reset,
    input logic out_clk
);
    ///// Reset behavior /////
    // While reset is asserted low, out_clk must be 0.
    reset_low_out_zero: assert property (
        @(posedge clk) (!reset) |-> (out_clk == 1'b0)
    );

    // On the cycle where reset falls (asynchronous assert), out_clk must be 0.
    async_reset_fall_clears_out: assert property (
        @(posedge clk) $fell(reset) |-> (out_clk == 1'b0)
    );

    // On the first clock after reset deasserts high, out_clk remains 0.
    out_zero_on_first_cycle_after_deassert: assert property (
        @(posedge clk) disable iff (!reset) $rose(reset) |-> (out_clk == 1'b0)
    );

    // On the second clock after reset deasserts high, out_clk becomes 1.
    out_one_on_second_cycle_after_deassert: assert property (
        @(posedge clk) disable iff (!reset) $rose(reset) |-> ##1 (out_clk == 1'b1)
    );

    ///// Divide-by-2 behavior /////
    // After at least one active cycle, out_clk toggles every clock.
    toggle_every_cycle_after_warmup: assert property (
        @(posedge clk) disable iff (!reset) $past(reset) |-> (out_clk != $past(out_clk))
    );

    // After at least two active cycles, out_clk repeats its value every two clocks.
    periodicity_two_cycles: assert property (
        @(posedge clk) disable iff (!reset) $past(reset,2) |-> (out_clk == $past(out_clk,2))
    );

    // Any rising edge of out_clk is followed by a falling edge next cycle.
    rise_followed_by_fall: assert property (
        @(posedge clk) disable iff (!reset) $rose(out_clk) |-> ##1 $fell(out_clk)
    );

    // Any falling edge of out_clk is followed by a rising edge next cycle.
    fall_followed_by_rise: assert property (
        @(posedge clk) disable iff (!reset) $fell(out_clk) |-> ##1 $rose(out_clk)
    );
endmodule

rtl:
module shift_register #(
    parameter N = 4 // Default value for N is 4
) (
    input clk,
    input reset, // Synchronous active-high reset
    input [N-1:0] D, // Input data for the shift register
    input L, // Load input for the shift register
    output reg [N-1:0] Q // Output data from the shift register
);


always @(posedge clk) begin
    if (reset) begin
        Q <= 0;
    end else if (L) begin
        Q <= D;
    end else begin
        Q <= {Q[N-2:0], Q[N-1]};
    end
end

endmodule

module top_module (
    input clk,
    input reset, // Synchronous active-high reset
    input [3:0] D0, // Input data for the 4-bit shift register
    input [15:0] D1, // Input data for the 16-bit shift register
    input select, // Select input to choose between shift registers
    input L, // Load input for the selected shift register
    output [19:0] out // Output of the bitwise OR operation
);

wire [3:0] Q0;
wire [15:0] Q1;

shift_register #(.N(4)) sr0 (
    .clk(clk),
    .reset(reset),
    .D(D0),
    .L(L & ~select),
    .Q(Q0)
);

shift_register #(.N(16)) sr1 (
    .clk(clk),
    .reset(reset),
    .D(D1),
    .L(L & select),
    .Q(Q1)
);

assign out = Q1 | Q0 | 20'h0; // Fix the issue by using the bitwise OR operator instead of the concatenation operator

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic reset, // synchronous active-high
    input logic [3:0] D0,
    input logic [15:0] D1,
    input logic select,
    input logic L,
    input logic [19:0] out
);
    // Clk/reset: clk posedge, reset sync active-high. Sequential logic (two rotating/loadable shift regs). out = (Q1 | Q0) zero-extended to 20b; out[19:16] are always 0.

    // Synchronous reset drives out to 0 on the next cycle.
    reset_clears_out_next: assert property (
        @(posedge clk) reset |=> (out == 20'h00000)
    );

    // The upper 4 bits of out are always zero due to zero-extension to 20 bits.
    invariant_top_bits_zero: assert property (
        @(posedge clk) disable iff (reset) (out[19:16] == 4'b0000)
    );

    // Loading sr1 (L & select) sets out[15:4] to D1[15:4] on the next cycle.
    sr1_load_sets_upper: assert property (
        @(posedge clk) disable iff (reset)
            (L && select) |=> (reset || (out[15:4] == $past(D1[15:4])))
    );

    // When sr1 is not loaded, out[15:5] rotates left by 1 (reflecting sr1 rotation).
    sr1_rotate_upper_when_not_loaded: assert property (
        @(posedge clk) disable iff (reset)
            (!(L && select)) |=> (reset || (out[15:5] == $past(out[14:4])))
    );

    // Loading sr1 guarantees next-cycle out[3:0] includes D1[3:0] (OR dominance).
    sr1_load_includes_lower_nibble: assert property (
        @(posedge clk) disable iff (reset)
            (L && select) |=> (reset || ((out[3:0] & $past(D1[3:0])) == $past(D1[3:0])))
    );

    // Loading sr0 guarantees next-cycle out[3:0] includes D0[3:0] (OR dominance).
    sr0_load_includes_lower_nibble: assert property (
        @(posedge clk) disable iff (reset)
            (L && !select) |=> (reset || ((out[3:0] & $past(D0[3:0])) == $past(D0[3:0])))
    );

    // If sr1 loads zeros in upper 12 bits, out[15:4] becomes zero next cycle.
    sr1_load_upper_zeros: assert property (
        @(posedge clk) disable iff (reset)
            (L && select && (D1[15:4] == 12'h000)) |=> (reset || (out[15:4] == 12'h000))
    );

    // If sr1 loads all ones in upper 12 bits, out[15:4] becomes all ones next cycle.
    sr1_load_upper_ones: assert property (
        @(posedge clk) disable iff (reset)
            (L && select && (D1[15:4] == 12'hFFF)) |=> (reset || (out[15:4] == 12'hFFF))
    );

    // If sr0 loads 4'hF, out[3:0] becomes 4'hF next cycle (OR with anything yields all ones).
    sr0_load_lower_all_ones: assert property (
        @(posedge clk) disable iff (reset)
            (L && !select && (D0 == 4'hF)) |=> (reset || (out[3:0] == 4'hF))
    );

    // If sr1 loads 4'hF in low nibble, out[3:0] becomes 4'hF next cycle.
    sr1_load_lower_all_ones: assert property (
        @(posedge clk) disable iff (reset)
            (L && select && (D1[3:0] == 4'hF)) |=> (reset || (out[3:0] == 4'hF))
    );
endmodule

