module sky130_fd_sc_ms__and4 (
    X,
    A,
    B,
    C,
    D
);

    output X;
    input  A;
    input  B;
    input  C;
    input  D;

    wire and0_out_X;

    and and0 (and0_out_X, A, B, C, D     );
    buf buf0 (X         , and0_out_X     );

endmodule

sva:
module sky130_fd_sc_ms__and4_sva (
    input logic CLK,  // sampling clock for assertions
    input logic X,
    input logic A,
    input logic B,
    input logic C,
    input logic D
);
    // Analysis: no clock/reset in RTL; pure combinational AND4 with buffer; X = A & B & C & D.

    // X equals the AND of inputs A,B,C,D.
    check_functional_equivalence: assert property (
        @(posedge CLK) X == (A & B & C & D)
    );

    // If all inputs are HIGH, X must be HIGH.
    check_all_inputs_high_implies_X_high: assert property (
        @(posedge CLK) (A & B & C & D) |-> (X == 1'b1)
    );

    // If any input is LOW, X must be LOW.
    check_any_input_low_implies_X_low: assert property (
        @(posedge CLK) (!A || !B || !C || !D) |-> (X == 1'b0)
    );

    // A rising edge on X implies all inputs are HIGH.
    check_X_rise_requires_all_inputs_high: assert property (
        @(posedge CLK) $rose(X) |-> (A & B & C & D)
    );

    // A falling edge on X implies at least one input is LOW.
    check_X_fall_requires_any_input_low: assert property (
        @(posedge CLK) $fell(X) |-> (!A || !B || !C || !D)
    );

    // If all inputs are stable, X is stable.
    check_output_stable_when_inputs_stable: assert property (
        @(posedge CLK) $stable({A,B,C,D}) |-> $stable(X)
    );

    // When the AND of inputs rises, X rises.
    check_all_high_rise_causes_X_rise: assert property (
        @(posedge CLK) $rose(A & B & C & D) |-> $rose(X)
    );

    // When the AND of inputs falls, X falls.
    check_all_high_fall_causes_X_fall: assert property (
        @(posedge CLK) $fell(A & B & C & D) |-> $fell(X)
    );
endmodule

module clock_counter_sva (
    input  logic        clk_i,
    input  logic        reset_n,
    input  logic        clk_o,
    input  logic [15:0] count
);
    // Clock: clk_i (posedge). Reset: reset_n (active-low async). Sequential counter toggles clk_o when count >= 17333.

    // Under reset, clk_o and count are driven LOW/zero.
    check_reset_forces_low: assert property (
        @(posedge clk_i) !reset_n |-> (clk_o == 1'b0) && (count == 16'd0)
    );

    // On reset deassertion, first active cycle keeps clk_o low and sets count to 1.
    check_reset_release_first_cycle: assert property (
        @(posedge clk_i) $rose(reset_n) |-> (clk_o == 1'b0) && (count == 16'd1)
    );

    // When previously below threshold, count increments by 1 and clk_o holds.
    check_increment_below_threshold: assert property (
        @(posedge clk_i) disable iff (!reset_n)
            $past(reset_n) && ($past(count) < 16'd17333)
            |-> (count == $past(count) + 16'd1) && (clk_o == $past(clk_o))
    );

    // When previously at/above threshold, clk_o toggles and count clears to 0.
    check_toggle_and_clear_at_threshold: assert property (
        @(posedge clk_i) disable iff (!reset_n)
            $past(reset_n) && ($past(count) >= 16'd17333)
            |-> (clk_o == ~$past(clk_o)) && (count == 16'd0)
    );

    // clk_o must not toggle when previously below threshold.
    check_no_toggle_below_threshold: assert property (
        @(posedge clk_i) disable iff (!reset_n)
            $past(reset_n) && ($past(count) < 16'd17333)
            |-> $stable(clk_o)
    );

    // Any clk_o toggle in run state must be caused by previously reaching threshold.
    check_toggle_only_when_threshold: assert property (
        @(posedge clk_i) disable iff (!reset_n)
            $changed(clk_o) |-> ($past(reset_n) && ($past(count) >= 16'd17333))
    );

    // No back-to-back clk_o toggles on consecutive active cycles.
    check_no_back_to_back_toggles: assert property (
        @(posedge clk_i) disable iff (!reset_n)
            $changed(clk_o) |-> ##1 (reset_n && $stable(clk_o))
    );

    // In run state, count == 0 can only occur after previously reaching threshold.
    check_zero_count_only_from_threshold: assert property (
        @(posedge clk_i) disable iff (!reset_n)
            (count == 16'd0 && $past(reset_n)) |-> ($past(count) >= 16'd17333)
    );

    // In run state, count is always bounded by the threshold.
    check_count_bounded_running: assert property (
        @(posedge clk_i) disable iff (!reset_n)
            $past(reset_n) |-> (count <= 16'd17333)
    );

    // After a toggle/clear cycle, next active cycle sets count to 1 and holds clk_o.
    check_post_toggle_next_cycle: assert property (
        @(posedge clk_i) disable iff (!reset_n)
            $past(reset_n) && ($past(count) >= 16'd17333)
            |-> ##1 (reset_n && (count == 16'd1) && $stable(clk_o))
    );

endmodule

rtl:
module address_decoder (
  input wire address,
  input wire clock,
  input wire reset_n,
  output reg [31:0] readdata
);

always @(posedge clock or negedge reset_n) begin
  if (!reset_n) begin
    readdata <= 0;
  end else begin
    case (address)
      1'b0: readdata <= 32'h560F6F0F;
      1'b1: readdata <= 32'hADC3C2C2;
      default: readdata <= 32'h0;
    endcase
  end
end

endmodule

sva:
module address_decoder_sva (
  input logic address,
  input logic clock,
  input logic reset_n,
  input logic [31:0] readdata
);
  // Clock: clock (posedge). Reset: reset_n active-low async. Sequential registered output.

  // During reset, readdata must be zero.
  reset_clears_readdata: assert property (
    @(posedge clock) (!reset_n) |-> (readdata == 32'h0000_0000)
  );

  // On the cycle reset_n rises, readdata is still 0 before the update.
  reset_release_holds_zero_one_cycle: assert property (
    @(posedge clock) $rose(reset_n) |-> (readdata == 32'h0000_0000)
  );

  // If previous cycle was out of reset and address was 0, readdata now equals 0x560F6F0F.
  map_prev_addr0_to_const0: assert property (
    @(posedge clock) disable iff (!reset_n)
      ($past(reset_n) && ($past(address) == 1'b0)) |-> (readdata == 32'h560F_6F0F)
  );

  // If previous cycle was out of reset and address was 1, readdata now equals 0xADC3C2C2.
  map_prev_addr1_to_const1: assert property (
    @(posedge clock) disable iff (!reset_n)
      ($past(reset_n) && ($past(address) == 1'b1)) |-> (readdata == 32'hADC3_C2C2)
  );

  // If address is 0 this cycle, next cycle readdata is 0x560F6F0F (barring reset).
  next_cycle_update_addr0: assert property (
    @(posedge clock) disable iff (!reset_n)
      (address == 1'b0) |=> (readdata == 32'h560F_6F0F)
  );

  // If address is 1 this cycle, next cycle readdata is 0xADC3C2C2 (barring reset).
  next_cycle_update_addr1: assert property (
    @(posedge clock) disable iff (!reset_n)
      (address == 1'b1) |=> (readdata == 32'hADC3_C2C2)
  );

  // If out of reset for two cycles and address unchanged, readdata is unchanged.
  stable_when_address_unchanged: assert property (
    @(posedge clock) disable iff (!reset_n)
      ($past(reset_n) && (address == $past(address))) |-> (readdata == $past(readdata))
  );

  // If address changed in the prior cycle (vs two cycles ago) and no reset, readdata changes now.
  readdata_changes_when_addr_changed_prev: assert property (
    @(posedge clock) disable iff (!reset_n)
      ($past(reset_n,1) && $past(reset_n,2) && ($past(address,1) != $past(address,2))) |-> (readdata != $past(readdata))
  );

  // If previous address was 0 or 1 while out of reset, readdata is nonzero this cycle.
  readdata_nonzero_for_legal_prev_addr: assert property (
    @(posedge clock) disable iff (!reset_n)
      ($past(reset_n) && (($past(address) == 1'b0) || ($past(address) == 1'b1))) |-> (readdata != 32'h0000_0000)
  );

endmodule

