sva:
module sky130_fd_sc_ls__a2111oi_sva (
    input logic Y,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic C1,
    input logic D1
);
    // No clock/reset in DUT; pure combinational; assertions use $global_clock.
    // Y is NOR of {B1, C1, D1, (A1 & A2)}.

    // Functional equivalence: Y == ~(B1 | C1 | D1 | (A1 & A2)).
    check_function_equivalence: assert property (
        @($global_clock) Y == ~(B1 | C1 | D1 | (A1 & A2))
    );

    // If any contributor is 1, Y must be 0.
    check_any_high_forces_low: assert property (
        @($global_clock) (B1 || C1 || D1 || (A1 && A2)) |-> (Y == 1'b0)
    );

    // If all contributors are 0, Y must be 1.
    check_all_low_forces_high: assert property (
        @($global_clock) (!B1 && !C1 && !D1 && !(A1 && A2)) |-> (Y == 1'b1)
    );

    // Y high implies all contributors are 0.
    check_y_high_implies_all_low: assert property (
        @($global_clock) (Y == 1'b1) |-> (!B1 && !C1 && !D1 && !(A1 && A2))
    );

    // Y low implies at least one contributor is 1.
    check_y_low_implies_any_high: assert property (
        @($global_clock) (Y == 1'b0) |-> (B1 || C1 || D1 || (A1 && A2))
    );

    // B1=1 forces Y=0.
    check_b1_forces_low: assert property (
        @($global_clock) B1 |-> (Y == 1'b0)
    );

    // C1=1 forces Y=0.
    check_c1_forces_low: assert property (
        @($global_clock) C1 |-> (Y == 1'b0)
    );

    // D1=1 forces Y=0.
    check_d1_forces_low: assert property (
        @($global_clock) D1 |-> (Y == 1'b0)
    );

    // A1&A2=1 forces Y=0.
    check_a_pair_forces_low: assert property (
        @($global_clock) (A1 && A2) |-> (Y == 1'b0)
    );

    // If inputs are stable, Y must be stable (pure combinational).
    check_stable_inputs_imply_stable_output: assert property (
        @($global_clock) $stable({A1, A2, B1, C1, D1}) |-> $stable(Y)
    );

    // Y can only rise when all contributors are 0.
    check_y_rise_when_all_low: assert property (
        @($global_clock) $rose(Y) |-> (!B1 && !C1 && !D1 && !(A1 && A2))
    );

    // Y can only fall when at least one contributor is 1.
    check_y_fall_when_any_high: assert property (
        @($global_clock) $fell(Y) |-> (B1 || C1 || D1 || (A1 && A2))
    );
endmodule

rtl:
module hi_read_tx(
    pck0, ck_1356meg, ck_1356megb,
    pwr_lo, pwr_hi, pwr_oe1, pwr_oe2, pwr_oe3, pwr_oe4,
    adc_d, adc_clk,
    ssp_frame, ssp_din, ssp_dout, ssp_clk,
    cross_hi, cross_lo,
    dbg,
    shallow_modulation
);
    input pck0, ck_1356meg, ck_1356megb;
    output pwr_lo, pwr_hi, pwr_oe1, pwr_oe2, pwr_oe3, pwr_oe4;
    input [7:0] adc_d;
    output adc_clk;
    input ssp_dout;
    output ssp_frame, ssp_din, ssp_clk;
    input cross_hi, cross_lo;
    output dbg;
    input shallow_modulation;

reg pwr_hi;
reg pwr_oe1;
reg pwr_oe2;
reg pwr_oe3;
reg pwr_oe4;
always @(ck_1356megb or ssp_dout or shallow_modulation)
begin
    if(shallow_modulation)
    begin
        pwr_hi <= ck_1356megb;
        pwr_oe1 <= ~ssp_dout;
        pwr_oe2 <= ~ssp_dout;
        pwr_oe3 <= ~ssp_dout;
        pwr_oe4 <= 1'b0;
    end
    else
    begin
        pwr_hi <= ck_1356megb & ssp_dout;
        pwr_oe1 <= 1'b0;
        pwr_oe2 <= 1'b0;
        pwr_oe3 <= 1'b0;
        pwr_oe4 <= 1'b0;
    end
end

reg [6:0] hi_div_by_128;

always @(posedge ck_1356meg)
    hi_div_by_128 <= hi_div_by_128 + 1;

assign ssp_clk = hi_div_by_128[6];

reg [2:0] hi_byte_div;

always @(negedge ssp_clk)
    hi_byte_div <= hi_byte_div + 1;

assign ssp_frame = (hi_byte_div == 3'b000);

assign adc_clk = ck_1356meg;

reg after_hysteresis;
always @(negedge adc_clk)
begin
    if(& adc_d[7:0]) after_hysteresis <= 1'b1;
    else if(~(| adc_d[7:0])) after_hysteresis <= 1'b0;
end


assign ssp_din = after_hysteresis;

assign pwr_lo = 1'b0;
assign dbg = ssp_din;

endmodule

sva:
module hi_read_tx_sva (
    input logic pck0,
    input logic ck_1356meg,
    input logic ck_1356megb,
    input logic pwr_lo,
    input logic pwr_hi,
    input logic pwr_oe1,
    input logic pwr_oe2,
    input logic pwr_oe3,
    input logic pwr_oe4,
    input logic [7:0] adc_d,
    input logic adc_clk,
    input logic ssp_frame,
    input logic ssp_din,
    input logic ssp_dout,
    input logic ssp_clk,
    input logic cross_hi,
    input logic cross_lo,
    input logic dbg,
    input logic shallow_modulation
);

    // adc_clk must mirror ck_1356meg.
    check_adc_clk_equals_ck: assert property (
        @(posedge ck_1356meg) (adc_clk == ck_1356meg)
    );

    // dbg must mirror ssp_din.
    check_dbg_mirrors_ssp_din: assert property (
        @(posedge ck_1356meg) (dbg == ssp_din)
    );

    // pwr_lo is tied low.
    check_pwr_lo_const_zero: assert property (
        @(posedge ck_1356meg) (pwr_lo == 1'b0)
    );

    // pwr_oe4 is tied low.
    check_pwr_oe4_const_zero: assert property (
        @(posedge ck_1356meg) (pwr_oe4 == 1'b0)
    );

    // In shallow_modulation, pwr_hi follows ck_1356megb.
    check_pwr_hi_shallow_mode: assert property (
        @(posedge ck_1356meg) shallow_modulation |-> (pwr_hi == ck_1356megb)
    );

    // In deep modulation (not shallow) with ssp_dout==0, pwr_hi must be 0.
    check_pwr_hi_deep_mode_dout0_zero: assert property (
        @(posedge ck_1356meg) (!shallow_modulation && (ssp_dout == 1'b0)) |-> (pwr_hi == 1'b0)
    );

    // In deep modulation (not shallow) with ssp_dout==1, pwr_hi follows ck_1356megb.
    check_pwr_hi_deep_mode_dout1_ck: assert property (
        @(posedge ck_1356meg) (!shallow_modulation && (ssp_dout == 1'b1)) |-> (pwr_hi == ck_1356megb)
    );

    // In shallow_modulation, pwr_oe[1:3] are the inverse of ssp_dout.
    check_pwr_oe_shallow_mode_invert_dout: assert property (
        @(posedge ck_1356meg) shallow_modulation |-> ((pwr_oe1 == ~ssp_dout) && (pwr_oe2 == ~ssp_dout) && (pwr_oe3 == ~ssp_dout))
    );

    // In deep modulation (not shallow), pwr_oe[1:3] are all zero.
    check_pwr_oe_deep_mode_zero: assert property (
        @(posedge ck_1356meg) (!shallow_modulation) |-> ((pwr_oe1 == 1'b0) && (pwr_oe2 == 1'b0) && (pwr_oe3 == 1'b0))
    );

    // pwr_oe1, pwr_oe2, and pwr_oe3 are always equal.
    check_pwr_oe_triple_equal: assert property (
        @(posedge ck_1356meg) (pwr_oe1 == pwr_oe2) && (pwr_oe2 == pwr_oe3)
    );

    // ssp_frame is stable across the posedge of ssp_clk (it only updates on ssp_clk negedge).
    check_ssp_frame_stable_on_posedge_ssp_clk: assert property (
        @(posedge ssp_clk) (ssp_frame == $past(ssp_frame))
    );

    // ssp_din is stable across the posedge of adc_clk (it only updates on adc_clk negedge).
    check_ssp_din_stable_on_posedge_adc_clk: assert property (
        @(posedge adc_clk) (ssp_din == $past(ssp_din))
    );

    // ssp_frame changes only when ssp_clk falls (hi_byte_div updates on ssp_clk negedge).
    check_ssp_frame_changes_only_on_fall_ssp_clk: assert property (
        @(posedge ck_1356meg) $changed(ssp_frame) |-> $fell(ssp_clk)
    );

    // ssp_clk does not change on consecutive posedges of ck_1356meg (it is a divided clock).
    check_ssp_clk_not_change_consecutive_cycles: assert property (
        @(posedge ck_1356meg) $changed(ssp_clk) |=> !$changed(ssp_clk)
    );

endmodule

rtl:
module dual_edge_triggered_flip_flop (
    input clk,
    input d,
    output q
);

reg q1, q2;

always @(posedge clk) // Only positive edge of clock
begin
    q1 <= d;
    q2 <= q1;
end

assign q = q2;

endmodule

sva:
module dual_edge_triggered_flip_flop_sva (
    input logic clk,
    input logic d,
    input logic q
);
    // Clock: clk (posedge). No reset present. q is d delayed by 2 cycles.

    // Q equals D delayed by exactly 2 clock cycles.
    check_q_two_cycle_delay: assert property (
        @(posedge clk) 1'b1 |-> ##2 (q == $past(d, 2))
    );

    // A rising edge on D causes a rising edge on Q two cycles later.
    check_d_rise_to_q_rise_two: assert property (
        @(posedge clk) $rose(d) |-> ##2 $rose(q)
    );

    // A falling edge on D causes a falling edge on Q two cycles later.
    check_d_fall_to_q_fall_two: assert property (
        @(posedge clk) $fell(d) |-> ##2 $fell(q)
    );

    // Any change on D propagates to Q two cycles later.
    check_d_change_to_q_change_two: assert property (
        @(posedge clk) $changed(d) |-> ##2 $changed(q)
    );

    // If D is stable over a cycle, Q is stable two cycles later.
    check_d_stable_implies_q_stable_two: assert property (
        @(posedge clk) $stable(d) |-> ##2 $stable(q)
    );

    // Q changes only if D changed two cycles earlier.
    check_q_change_implies_prior_d_change: assert property (
        @(posedge clk) $changed(q) |-> ($past(d, 2) != $past(d, 3))
    );

    // Q stable only if D was stable two and three cycles earlier.
    check_q_stable_implies_prior_d_stable: assert property (
        @(posedge clk) $stable(q) |-> ($past(d, 2) == $past(d, 3))
    );

    // A rising edge on Q corresponds to D=1 two cycles earlier and D=0 three cycles earlier.
    check_q_rise_matches_prior_d: assert property (
        @(posedge clk) $rose(q) |-> ($past(d, 2) == 1'b1 && $past(d, 3) == 1'b0)
    );

    // A falling edge on Q corresponds to D=0 two cycles earlier and D=1 three cycles earlier.
    check_q_fall_matches_prior_d: assert property (
        @(posedge clk) $fell(q) |-> ($past(d, 2) == 1'b0 && $past(d, 3) == 1'b1)
    );

    // Equivalence: Q changes iff D differed two and three cycles earlier.
    check_q_change_equivalence: assert property (
        @(posedge clk) ($changed(q) == ($past(d, 2) != $past(d, 3)))
    );
endmodule

