module my_module (
    VPWR,
    VGND,
    X   ,
    A1  ,
    A2  ,
    B1  ,
    C1  ,
    D1
);

    // Module ports
    input  VPWR;
    input  VGND;
    output X   ;
    input  A1  ;
    input  A2  ;
    input  B1  ;
    input  C1  ;
    input  D1  ;

    // Local signals
    wire    nand0_out_A1_A2    ;
    wire    nand1_out_B1_C1    ;
    wire    nand2_out_D1_or0   ;
    wire    nand3_out_nand0_nand1;
    wire    buf0_out_nand3     ;

    //                           Name          Output              Other arguments
    nand                         nand0        (nand0_out_A1_A2    , A1, A2              );
    nand                         nand1        (nand1_out_B1_C1    , B1, C1              );
    or                           or0          (nand2_out_D1_or0   , A2, A1              );
    nand                         nand2        (nand3_out_nand0_nand1, nand0_out_A1_A2, nand1_out_B1_C1, nand2_out_D1_or0);
    buf                          buf0         (X                 , buf0_out_nand3     );
    nand                         nand3        (buf0_out_nand3     , nand3_out_nand0_nand1);

endmodule

sva:
module my_module_sva (
    input logic VPWR,
    input logic VGND,
    input logic X,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic C1,
    input logic D1
);
    // Expected combinational function of X
    logic expected_X;
    assign expected_X = (A1 ^ A2) & ~(B1 & C1);

    // X matches its Boolean implementation.
    check_x_function: assert property (
        @(posedge A1) X == expected_X
    );

    // When B1 and C1 are both HIGH, X must be LOW.
    check_x_zero_when_B1C1_high: assert property (
        @(posedge B1) (B1 && C1) |-> (X == 1'b0)
    );

    // When A1 equals A2, X must be LOW.
    check_x_zero_when_A_equal: assert property (
        @(posedge A1) (A1 == A2) |-> (X == 1'b0)
    );

    // When (A1^A2) and not (B1 & C1), X must be HIGH.
    check_x_one_when_cond: assert property (
        @(posedge A1) ((A1 ^ A2) && !(B1 && C1)) |-> (X == 1'b1)
    );

    // If X is HIGH then A1^A2 must be HIGH.
    check_x_implies_xor: assert property (
        @(posedge A1) X |-> (A1 ^ A2)
    );

    // If X is HIGH then not(B1 & C1) must hold.
    check_x_implies_not_B1C1: assert property (
        @(posedge B1) X |-> !(B1 && C1)
    );

    // If B1 is LOW then X equals A1^A2.
    check_B1_zero_pass_through: assert property (
        @(posedge B1) (B1 == 1'b0) |-> (X == (A1 ^ A2))
    );

    // If C1 is LOW then X equals A1^A2.
    check_C1_zero_pass_through: assert property (
        @(posedge C1) (C1 == 1'b0) |-> (X == (A1 ^ A2))
    );

    // If B1 is HIGH and X is HIGH, then C1 must be LOW.
    check_x_and_B1_implies_not_C1: assert property (
        @(posedge B1) (X && (B1 == 1'b1)) |-> (C1 == 1'b0)
    );

    // If C1 is HIGH and X is HIGH, then B1 must be LOW.
    check_x_and_C1_implies_not_B1: assert property (
        @(posedge C1) (X && (C1 == 1'b1)) |-> (B1 == 1'b0)
    );

    // D1 does not affect X when A1,A2,B1,C1 are stable.
    check_D1_independence: assert property (
        @(posedge D1) $stable({A1,A2,B1,C1}) |-> $stable(X)
    );

    // VPWR does not affect X when A1,A2,B1,C1 are stable.
    check_VPWR_independence: assert property (
        @(posedge VPWR) $stable({A1,A2,B1,C1}) |-> $stable(X)
    );

    // VGND does not affect X when A1,A2,B1,C1 are stable.
    check_VGND_independence: assert property (
        @(posedge VGND) $stable({A1,A2,B1,C1}) |-> $stable(X)
    );
endmodule

rtl:
module counter (
    input clk,
    input rst,
    input [31:0] max_val,
    output reg [31:0] count
);

always @(posedge clk) begin
    if (rst) begin
        count <= 0;
    end else if (count == max_val) begin
        count <= 0;
    end else begin
        count <= count + 1;
    end
end

endmodule

sva:
module counter_sva (
    input logic clk,
    input logic rst,
    input logic [31:0] max_val,
    input logic [31:0] count
);
    // Reset drives count to 0 on the next rising edge.
    reset_clears_count_next: assert property (
        @(posedge clk) rst |=> (count == 32'd0)
    );

    // When count equals max_val (no reset), next value is 0.
    wrap_to_zero_on_max: assert property (
        @(posedge clk) disable iff (rst) (count == max_val) |=> (count == 32'd0)
    );

    // When count is not max_val (no reset), next value increments by 1.
    increment_when_not_max: assert property (
        @(posedge clk) disable iff (rst) (count != max_val) |=> (count == $past(count) + 32'd1)
    );

    // Next value function is exactly: (count==max_val) ? 0 : count+1 (no reset).
    deterministic_update: assert property (
        @(posedge clk) disable iff (rst) 1 |=> (count == (($past(count) == $past(max_val)) ? 32'd0 : $past(count) + 32'd1))
    );

    // If not due to reset, a 0 value must come from prior equality to max or overflow.
    zero_implies_prev_eq_max_or_overflow: assert property (
        @(posedge clk) disable iff (rst) 1 |=> ((count == 32'd0 && !$past(rst)) -> ($past(count) == $past(max_val) || $past(count) == 32'hFFFF_FFFF))
    );

    // If previous count was neither max_val nor 32'hFFFF_FFFF (no reset), next count is not 0.
    no_zero_without_eq_or_overflow: assert property (
        @(posedge clk) disable iff (rst) 1 |=> (($past(count) != $past(max_val) && $past(count) != 32'hFFFF_FFFF) -> (count != 32'd0))
    );
endmodule

rtl:
module mux_parity (
  input [2:0] sel,
  input [3:0] data0,
  input [3:0] data1,
  input [3:0] data2,
  input [3:0] data3,
  input [3:0] data4,
  input [3:0] data5,
  output [3:0] out,
  output parity
);

  wire [3:0] mux_out [0:5];
  wire [2:0] sel_dec [0:7];

  // Generate intermediate signals for each input data
  assign mux_out[0] = (sel_dec[0]) ? data0 : 4'b0;
  assign mux_out[1] = (sel_dec[1]) ? data1 : 4'b0;
  assign mux_out[2] = (sel_dec[2]) ? data2 : 4'b0;
  assign mux_out[3] = (sel_dec[3]) ? data3 : 4'b0;
  assign mux_out[4] = (sel_dec[4]) ? data4 : 4'b0;
  assign mux_out[5] = (sel_dec[5]) ? data5 : 4'b0;

  // Generate select signals using a 3-to-8 decoder
  assign sel_dec[0] = (sel == 3'b000);
  assign sel_dec[1] = (sel == 3'b001);
  assign sel_dec[2] = (sel == 3'b010);
  assign sel_dec[3] = (sel == 3'b011);
  assign sel_dec[4] = (sel == 3'b100);
  assign sel_dec[5] = (sel == 3'b101);
  assign sel_dec[6] = 1'b0;
  assign sel_dec[7] = 1'b0;

  // Select the active input data using an 8-input OR gate
  assign out = mux_out[0] | mux_out[1] | mux_out[2] | mux_out[3] | mux_out[4] | mux_out[5];

  // Generate the parity bit using an XOR gate
  assign parity = out[0] ^ out[1] ^ out[2] ^ out[3];

endmodule

sva:
module mux_parity_sva (
  input logic clk,
  input logic [2:0] sel,
  input logic [3:0] data0,
  input logic [3:0] data1,
  input logic [3:0] data2,
  input logic [3:0] data3,
  input logic [3:0] data4,
  input logic [3:0] data5,
  input logic [3:0] out,
  input logic parity
);

  // Mux output equals sum-of-products of data inputs gated by sel
  check_mux_sum_of_products: assert property (
    @(posedge clk)
      out == (
        ((sel == 3'b000) ? data0 : 4'b0) |
        ((sel == 3'b001) ? data1 : 4'b0) |
        ((sel == 3'b010) ? data2 : 4'b0) |
        ((sel == 3'b011) ? data3 : 4'b0) |
        ((sel == 3'b100) ? data4 : 4'b0) |
        ((sel == 3'b101) ? data5 : 4'b0)
      )
  );

  // When sel=000, out equals data0
  check_sel0_route: assert property (
    @(posedge clk) (sel == 3'b000) |-> (out == data0)
  );

  // When sel=001, out equals data1
  check_sel1_route: assert property (
    @(posedge clk) (sel == 3'b001) |-> (out == data1)
  );

  // When sel=010, out equals data2
  check_sel2_route: assert property (
    @(posedge clk) (sel == 3'b010) |-> (out == data2)
  );

  // When sel=011, out equals data3
  check_sel3_route: assert property (
    @(posedge clk) (sel == 3'b011) |-> (out == data3)
  );

  // When sel=100, out equals data4
  check_sel4_route: assert property (
    @(posedge clk) (sel == 3'b100) |-> (out == data4)
  );

  // When sel=101, out equals data5
  check_sel5_route: assert property (
    @(posedge clk) (sel == 3'b101) |-> (out == data5)
  );

  // For invalid sel (110 or 111), out is zero
  check_invalid_sel_out_zero: assert property (
    @(posedge clk) (sel inside {3'b110,3'b111}) |-> (out == 4'b0000)
  );

  // Parity equals XOR of out bits
  check_parity_from_out: assert property (
    @(posedge clk) parity == (out[0] ^ out[1] ^ out[2] ^ out[3])
  );

  // For invalid sel, parity is zero (since out is zero)
  check_invalid_sel_parity_zero: assert property (
    @(posedge clk) (sel inside {3'b110,3'b111}) |-> (parity == 1'b0)
  );

endmodule

rtl:
module barrel_shifter (
    input [3:0] data,
    input [1:0] shift_amount,
    output reg [3:0] result
);

    always @(*) begin
        case(shift_amount)
            2'b00: result = data;
            2'b01: result = {data[3], data[0], data[1], data[2]};
            2'b10: result = {data[2], data[3], data[0], data[1]};
            2'b11: result = {data[1], data[2], data[3], data[0]};
        endcase
    end

endmodule

sva:
module barrel_shifter_sva (
    // Added clock for SVA sampling
    input logic clk,

    // DUT ports
    input logic [3:0] data,
    input logic [1:0] shift_amount,
    input logic [3:0] result
);
    // Analysis: no reset; pure combinational always @(*); behavior is case-based bit permutation.

    // Result must equal data when shift_amount == 2'b00.
    check_shift00_identity: assert property (
        @(posedge clk) (shift_amount == 2'b00) |-> (result == data)
    );

    // Result must equal {data[3], data[0], data[1], data[2]} when shift_amount == 2'b01.
    check_shift01_permutation: assert property (
        @(posedge clk) (shift_amount == 2'b01) |-> (result == {data[3], data[0], data[1], data[2]})
    );

    // Result must equal {data[2], data[3], data[0], data[1]} when shift_amount == 2'b10.
    check_shift10_permutation: assert property (
        @(posedge clk) (shift_amount == 2'b10) |-> (result == {data[2], data[3], data[0], data[1]})
    );

    // Result must equal {data[1], data[2], data[3], data[0]} when shift_amount == 2'b11.
    check_shift11_permutation: assert property (
        @(posedge clk) (shift_amount == 2'b11) |-> (result == {data[1], data[2], data[3], data[0]})
    );

    // Result must always equal the case-derived permutation for the current shift_amount.
    check_functional_equivalence: assert property (
        @(posedge clk)
            result == (
                (shift_amount == 2'b00) ? data :
                (shift_amount == 2'b01) ? {data[3], data[0], data[1], data[2]} :
                (shift_amount == 2'b10) ? {data[2], data[3], data[0], data[1]} :
                                          {data[1], data[2], data[3], data[0]}
            )
    );

endmodule

rtl:
module DFFSR (output Q, input C, S, R, D);

    reg Q;

    always @(posedge C) begin
        if (R) begin
            Q <= 0;
        end else if (S) begin
            Q <= 1;
        end else begin
            Q <= D;
        end
    end

endmodule

sva:
module DFFSR_sva (
    input logic Q,
    input logic C,
    input logic S,
    input logic R,
    input logic D
);
    // Clock: C (posedge). Reset: R is synchronous active-high driving Q to 0; S is synchronous active-high set to 1 (lower priority than R).
    // Logic: Sequential (edge-triggered DFF with synchronous set/reset).
    // Behavior: On posedge C: if R then Q<=0; else if S then Q<=1; else Q<=D.

    // R forces next Q to 0 on the following sample (synchronous reset).
    check_reset_forces_zero: assert property (
        @(posedge C) R |-> (Q == 1'b0)
    );

    // With R deasserted, S forces next Q to 1 (set).
    check_set_forces_one_no_reset: assert property (
        @(posedge C) disable iff (R) S |-> (Q == 1'b1)
    );

    // When both R and S are 1, next Q is 0 (reset has priority over set).
    check_reset_priority_over_set: assert property (
        @(posedge C) (R && S) |-> (Q == 1'b0)
    );

    // With both R and S deasserted, next Q equals D sampled at this clock.
    check_data_captured_when_no_set_reset: assert property (
        @(posedge C) (!R && !S) |-> (Q == $past(D))
    );

    // A 0->1 rise on Q must be caused by either S or by D=1 when no set/reset in the prior cycle.
    check_q_rise_cause: assert property (
        @(posedge C) $rose(Q) |-> (!$past(R) && ($past(S) || (!$past(S) && ($past(D) == 1'b1))))
    );

    // A 1->0 fall on Q must be caused by either R or by D=0 when no set in the prior cycle.
    check_q_fall_cause: assert property (
        @(posedge C) $fell(Q) |-> ($past(R) || (!$past(R) && !$past(S) && ($past(D) == 1'b0)))
    );

endmodule

