module control_logic (
  input select,
  input [31:0] in1,
  input a, b, cin,
  output reg [31:0] out
);
  wire [31:0] in2;
  assign in2 = select ? {a, b, cin} : in1;

  byte_reverser byte_reverser_inst (
    .in(in2),
    .out(out)
  );
