module simple_calculator(
    input signed [31:0] a,
    input signed [31:0] b,
    input [1:0] mode,
    output reg signed [31:0] sum,
    output reg signed [31:0] difference,
    output reg signed [31:0] product,
    output reg signed [31:0] quotient
);

always @(*) begin
    case (mode)
        2'b00: begin
            sum = a + b;
            difference = 0;
            product = 0;
            quotient = 0;
        end
        2'b01: begin
            sum = 0;
            difference = a - b;
            product = 0;
            quotient = 0;
        end
        2'b10: begin
            sum = 0;
            difference = 0;
            product = a * b;
            quotient = 0;
        end
        2'b11: begin
            sum = 0;
            difference = 0;
            product = 0;
            quotient = a / b;
        end
    endcase
end

endmodule

sva:
module simple_calculator_sva (
    input logic clk,
    input logic signed [31:0] a,
    input logic signed [31:0] b,
    input logic [1:0] mode,
    input logic signed [31:0] sum,
    input logic signed [31:0] difference,
    input logic signed [31:0] product,
    input logic signed [31:0] quotient
);
    // In mode 00, sum is 32-bit truncated a+b; others are 0.
    check_mode00_sum_and_zeros: assert property (
        @(posedge clk)
        (mode == 2'b00) |-> (
            sum == $signed((($signed(a) + $signed(b))[31:0])) &&
            difference == 32'sd0 &&
            product == 32'sd0 &&
            quotient == 32'sd0
        )
    );

    // In mode 01, difference is 32-bit truncated a-b; others are 0.
    check_mode01_diff_and_zeros: assert property (
        @(posedge clk)
        (mode == 2'b01) |-> (
            sum == 32'sd0 &&
            difference == $signed((($signed(a) - $signed(b))[31:0])) &&
            product == 32'sd0 &&
            quotient == 32'sd0
        )
    );

    // In mode 10, product is 32-bit truncated a*b; others are 0.
    check_mode10_prod_and_zeros: assert property (
        @(posedge clk)
        (mode == 2'b10) |-> (
            sum == 32'sd0 &&
            difference == 32'sd0 &&
            product == $signed((($signed(a) * $signed(b))[31:0])) &&
            quotient == 32'sd0
        )
    );

    // In mode 11, non-selected outputs are 0.
    check_mode11_zeros: assert property (
        @(posedge clk)
        (mode == 2'b11) |-> (
            sum == 32'sd0 &&
            difference == 32'sd0 &&
            product == 32'sd0
        )
    );

    // In mode 11 with b!=0, quotient equals signed a/b.
    check_mode11_quotient_value: assert property (
        @(posedge clk)
        (mode == 2'b11 && b != 32'sd0) |-> (quotient == ($signed(a) / $signed(b)))
    );

    // When mode is not 00, sum must be 0.
    check_sum_zero_when_not_mode00: assert property (
        @(posedge clk)
        (mode != 2'b00) |-> (sum == 32'sd0)
    );

    // When mode is not 01, difference must be 0.
    check_difference_zero_when_not_mode01: assert property (
        @(posedge clk)
        (mode != 2'b01) |-> (difference == 32'sd0)
    );

    // When mode is not 10, product must be 0.
    check_product_zero_when_not_mode10: assert property (
        @(posedge clk)
        (mode != 2'b10) |-> (product == 32'sd0)
    );

    // When mode is not 11, quotient must be 0.
    check_quotient_zero_when_not_mode11: assert property (
        @(posedge clk)
        (mode != 2'b11) |-> (quotient == 32'sd0)
    );

    // At most one output is non-zero at any time.
    check_outputs_at_most_one_nonzero: assert property (
        @(posedge clk)
        !(
            (sum != 32'sd0 && difference != 32'sd0) ||
            (sum != 32'sd0 && product != 32'sd0) ||
            (sum != 32'sd0 && quotient != 32'sd0) ||
            (difference != 32'sd0 && product != 32'sd0) ||
            (difference != 32'sd0 && quotient != 32'sd0) ||
            (product != 32'sd0 && quotient != 32'sd0)
        )
    );
endmodule

rtl:
module top_module (
    input clk,
    input reset, // Synchronous active-high reset
    input [7:0] in_data, // Input data to the system
    output reg out_signal // Output signal of the system
);

reg [7:0] shift_reg; // Byte-wide shift register
reg parity; // Parity generator output
reg d_ff; // D flip-flop module output
reg xor_output; // XOR module output

// Byte-wide shift register
always @(posedge clk) begin
    if (reset) begin
        shift_reg <= 8'b0;
    end else begin
        shift_reg <= {shift_reg[6:0], parity};
    end
end

// Parity generator
always @(*) begin
    parity = ^in_data;
end

// D flip-flop module
always @(posedge clk) begin
    if (reset) begin
        d_ff <= 1'b0;
    end else begin
        d_ff <= in_data[0];
    end
end

// XOR module
always @(*) begin
    xor_output = parity ^ d_ff;
end

// Output signal
always @(posedge clk) begin
    if (reset) begin
        out_signal <= 1'b0;
    end else begin
        out_signal <= shift_reg[7];
    end
end

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic reset, // Synchronous active-high reset
    input logic [7:0] in_data,
    input logic out_signal,

    // Internal signals from DUT (bind to these by name)
    input logic [7:0] shift_reg,
    input logic parity,
    input logic d_ff,
    input logic xor_output
);

    ///// Reset behavior /////
    // On reset, shift_reg is cleared to 0 by the next clock.
    check_reset_clears_shift_reg: assert property (
        @(posedge clk) reset |=> (shift_reg == 8'h00)
    );

    // On reset, d_ff is cleared to 0 by the next clock.
    check_reset_clears_dff: assert property (
        @(posedge clk) reset |=> (d_ff == 1'b0)
    );

    // On reset, out_signal is cleared to 0 by the next clock.
    check_reset_clears_out: assert property (
        @(posedge clk) reset |=> (out_signal == 1'b0)
    );

    ///// Combinational definitions /////
    // Parity equals reduction XOR of in_data when not in reset.
    check_parity_definition: assert property (
        @(posedge clk) disable iff (reset) (parity == ^in_data)
    );

    // xor_output equals parity XOR d_ff when not in reset.
    check_xor_output_definition: assert property (
        @(posedge clk) disable iff (reset) (xor_output == (parity ^ d_ff))
    );

    ///// Sequential updates /////
    // d_ff captures in_data[0] from the previous cycle (when previous cycle not in reset).
    check_dff_captures_in_lsb: assert property (
        @(posedge clk) disable iff (reset) (!$past(reset)) |-> (d_ff == $past(in_data[0]))
    );

    // shift_reg shifts left and appends parity from the previous cycle (when previous cycle not in reset).
    check_shift_reg_shifts_with_parity: assert property (
        @(posedge clk) disable iff (reset) (!$past(reset)) |-> (shift_reg == { $past(shift_reg[6:0]), $past(parity) })
    );

    // shift_reg[7] moves from previous shift_reg[6] (when previous cycle not in reset).
    check_shift_reg_msb_moves_from_bit6: assert property (
        @(posedge clk) disable iff (reset) (!$past(reset)) |-> (shift_reg[7] == $past(shift_reg[6]))
    );

    // out_signal equals previous cycle's shift_reg[7] (when previous cycle not in reset).
    check_out_signal_follows_shift_msb: assert property (
        @(posedge clk) disable iff (reset) (!$past(reset)) |-> (out_signal == $past(shift_reg[7]))
    );

endmodule

