`resetall




module debounce_switch  #(
    parameter WIDTH=1, parameter N=3, parameter RATE=125000 )(
    input wire clk,
    input wire rst,
    input wire [WIDTH-1:0] in,
    output wire [WIDTH-1:0] out
);

reg [23:0] cnt_reg = 24'd0;

reg [N-1:0] debounce_reg[WIDTH-1:0];

reg [WIDTH-1:0] state;


assign out = state;

integer k;

always @(posedge clk) begin
    if (rst) begin
        cnt_reg <= 0;
        state <= 0;

        for (k = 0; k < WIDTH; k = k + 1) begin
            debounce_reg[k] <= 0;
        end
    end else begin
        if (cnt_reg < RATE) begin
            cnt_reg <= cnt_reg + 24'd1;
        end else begin
            cnt_reg <= 24'd0;
        end

        if (cnt_reg == 24'd0) begin
            for (k = 0; k < WIDTH; k = k + 1) begin
                debounce_reg[k] <= {debounce_reg[k][N-2:0], in[k]};
            end
        end

        for (k = 0; k < WIDTH; k = k + 1) begin
            if (|debounce_reg[k] == 0) begin
                state[k] <= 0;
            end else if (&debounce_reg[k] == 1) begin
                state[k] <= 1;
            end else begin
                state[k] <= state[k];
            end
        end
    end
end

endmodule

`resetall

sva:
module debounce_switch_sva #(
    parameter WIDTH = 1,
    parameter N     = 3,
    parameter RATE  = 125000
)(
    input  logic                  clk,
    input  logic                  rst,
    input  logic [WIDTH-1:0]      in,
    input  logic [WIDTH-1:0]      out,
    // Internal signals from DUT (connect via bind)
    input  logic [23:0]           cnt_reg,
    input  logic [N-1:0]          debounce_reg [WIDTH-1:0],
    input  logic [WIDTH-1:0]      state
);

    ///// Reset behavior /////
    // After a reset cycle, counter and state are 0 on the next cycle.
    reset_clears_counter_state: assert property (
        @(posedge clk) disable iff (rst)
            $past(rst) |-> (cnt_reg == 24'd0) && (state == '0)
    );

    genvar gi_rst;
    generate
        for (gi_rst = 0; gi_rst < WIDTH; gi_rst++) begin : GEN_RESET_DB
            // After a reset cycle, each debounce shift register is 0 on the next cycle.
            reset_clears_debounce_regs: assert property (
                @(posedge clk) disable iff (rst)
                    $past(rst) |-> (debounce_reg[gi_rst] == '0)
            );
        end
    endgenerate

    ///// Counter behavior /////
    // Counter value is always within 0..RATE when not in reset.
    counter_within_range: assert property (
        @(posedge clk) disable iff (rst)
            (cnt_reg <= RATE)
    );

    // If previous cnt_reg < RATE, it increments by 1.
    counter_increments_below_RATE: assert property (
        @(posedge clk) disable iff (rst)
            ($past(!rst) && $past(cnt_reg < RATE)) |-> (cnt_reg == $past(cnt_reg) + 24'd1)
    );

    // If previous cnt_reg >= RATE, it wraps to 0.
    counter_wraps_at_RATE: assert property (
        @(posedge clk) disable iff (rst)
            ($past(!rst) && $past(cnt_reg >= RATE)) |-> (cnt_reg == 24'd0)
    );

    ///// Output wiring /////
    // out mirrors internal state.
    out_mirrors_state: assert property (
        @(posedge clk) disable iff (rst)
            (out == state)
    );

    ///// Debounce sampling and state update /////
    genvar i;
    generate
        for (i = 0; i < WIDTH; i++) begin : GEN_DEBOUNCE
            // On a sampling cycle (prev cnt_reg==0), debounce_reg shifts in in[i].
            debounce_shifts_on_sample: assert property (
                @(posedge clk) disable iff (rst)
                    ($past(!rst) && $past(cnt_reg == 24'd0))
                    |-> (debounce_reg[i] == {$past(debounce_reg[i][N-2:0]), $past(in[i])})
            );

            // When not sampling (prev cnt_reg!=0), debounce_reg holds its value.
            debounce_holds_when_not_sampling: assert property (
                @(posedge clk) disable iff (rst)
                    ($past(!rst) && $past(cnt_reg != 24'd0))
                    |-> (debounce_reg[i] == $past(debounce_reg[i]))
            );

            // If previous debounce_reg was all 0s, state[i] becomes 0.
            state_sets_low_when_all_zero: assert property (
                @(posedge clk) disable iff (rst)
                    ($past(!rst) && ($past(|debounce_reg[i]) == 1'b0))
                    |-> (state[i] == 1'b0)
            );

            // If previous debounce_reg was all 1s, state[i] becomes 1.
            state_sets_high_when_all_one: assert property (
                @(posedge clk) disable iff (rst)
                    ($past(!rst) && ($past(&debounce_reg[i]) == 1'b1))
                    |-> (state[i] == 1'b1)
            );

            // If previous debounce_reg was mixed (not all 0s or 1s), state[i] holds.
            state_holds_when_reg_mixed: assert property (
                @(posedge clk) disable iff (rst)
                    ($past(!rst) && ($past(|debounce_reg[i]) == 1'b1) && ($past(&debounce_reg[i]) == 1'b0))
                    |-> (state[i] == $past(state[i]))
            );
        end
    endgenerate

endmodule

rtl:
module full_adder(
    input a, b, cin,
    output cout, sum );

    wire w1, w2, w3;

    // First half adder
    half_adder HA1(.a(a), .b(b), .sum(w1), .cout(w2));

    // Second half adder
    half_adder HA2(.a(w1), .b(cin), .sum(sum), .cout(w3));

    // Multiplexer to select carry-out
    assign cout = w2 | w3;

endmodule
module half_adder(
    input a, b,
    output sum, cout );

    assign sum = a ^ b;
    assign cout = a & b;

endmodule

sva:
module full_adder_sva (
    input  logic CLK,
    input  logic RESETn,
    input  logic a,
    input  logic b,
    input  logic cin,
    input  logic cout,
    input  logic sum
);
    // Sum equals a ^ b ^ cin.
    check_sum_xor3: assert property (
        @(posedge CLK) disable iff (!RESETn)
        sum == (a ^ b ^ cin)
    );

    // Carry-out equals (a & b) | ((a ^ b) & cin).
    check_cout_logic: assert property (
        @(posedge CLK) disable iff (!RESETn)
        cout == ((a & b) | ((a ^ b) & cin))
    );

    // With cin=0, sum equals a ^ b.
    check_sum_when_cin0: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (cin == 1'b0) |-> (sum == (a ^ b))
    );

    // With cin=0, carry equals a & b.
    check_cout_when_cin0: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (cin == 1'b0) |-> (cout == (a & b))
    );

    // With cin=1, sum equals ~(a ^ b).
    check_sum_when_cin1: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (cin == 1'b1) |-> (sum == ~(a ^ b))
    );

    // With cin=1, carry equals (a & b) | (a ^ b).
    check_cout_when_cin1: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (cin == 1'b1) |-> (cout == ((a & b) | (a ^ b)))
    );

    // If a & b is 1, carry must be 1.
    check_carry_when_ab: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (a & b) |-> (cout == 1'b1)
    );

    // If cin=1 and a ^ b = 1, carry must be 1.
    check_carry_when_cin_and_axorb: assert property (
        @(posedge CLK) disable iff (!RESETn)
        ((cin == 1'b1) && (a ^ b)) |-> (cout == 1'b1)
    );

    // When neither a&b nor (a^b)&cin is 1, carry must be 0.
    check_no_carry_sources: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (!((a & b) | ((a ^ b) & cin))) |-> (cout == 1'b0)
    );

    // All-low inputs produce sum=0 and cout=0.
    check_all_zero_case: assert property (
        @(posedge CLK) disable iff (!RESETn)
        ((!a) && (!b) && (!cin)) |-> ((sum == 1'b0) && (cout == 1'b0))
    );

    // All-high inputs produce sum=1 and cout=1.
    check_all_one_case: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (a && b && cin) |-> ((sum == 1'b1) && (cout == 1'b1))
    );
endmodule

rtl:
module xor_gate_lut(
    input a,
    input b,
    output reg out_lut
);

    always @(*)
    begin
        case ({a,b})
            2'b00: out_lut = 1'b0;
            2'b01: out_lut = 1'b1;
            2'b10: out_lut = 1'b1;
            2'b11: out_lut = 1'b0;
        endcase
    end

endmodule

sva:
module xor_gate_lut_sva (
    input logic CLK,
    input logic a,
    input logic b,
    input logic out_lut
);
    // Output equals XOR of inputs each cycle.
    check_out_eq_xor: assert property (
        @(posedge CLK) (out_lut == (a ^ b))
    );

    // Truth table: 00 -> 0.
    check_case_00: assert property (
        @(posedge CLK) ({a,b} == 2'b00) |-> (out_lut == 1'b0)
    );
    // Truth table: 01 -> 1.
    check_case_01: assert property (
        @(posedge CLK) ({a,b} == 2'b01) |-> (out_lut == 1'b1)
    );
    // Truth table: 10 -> 1.
    check_case_10: assert property (
        @(posedge CLK) ({a,b} == 2'b10) |-> (out_lut == 1'b1)
    );
    // Truth table: 11 -> 0.
    check_case_11: assert property (
        @(posedge CLK) ({a,b} == 2'b11) |-> (out_lut == 1'b0)
    );

    // When b is 0, output passes a.
    check_b0_passthrough: assert property (
        @(posedge CLK) (b == 1'b0) |-> (out_lut == a)
    );
    // When b is 1, output is inverted a.
    check_b1_invert: assert property (
        @(posedge CLK) (b == 1'b1) |-> (out_lut == ~a)
    );

    // When a is 0, output passes b.
    check_a0_passthrough: assert property (
        @(posedge CLK) (a == 1'b0) |-> (out_lut == b)
    );
    // When a is 1, output is inverted b.
    check_a1_invert: assert property (
        @(posedge CLK) (a == 1'b1) |-> (out_lut == ~b)
    );

    // If inputs are stable between samples, output is stable.
    check_stability: assert property (
        @(posedge CLK) ($stable(a) && $stable(b)) |-> $stable(out_lut)
    );

    // Output change parity equals XOR of input changes between samples.
    check_change_parity: assert property (
        @(posedge CLK) ($changed(out_lut) == ($changed(a) ^ $changed(b)))
    );
endmodule

module combinational_logic_sva (
    input A1,
    input A2,
    input A3,
    input B1,
    input VPB,
    input X,
    input VPWR,
    input VGND,
    input VNB
);
    ///// Combinational function checks (clocked on A1 for sampling) /////
    // X matches the defined boolean function of inputs.
    check_x_function_equivalence: assert property (
        @(posedge A1) X == ((A1 && A2 && A3) || (B1 && VPB))
    );

    // When all A inputs are HIGH, X must be HIGH.
    check_a_term_drives_x: assert property (
        @(posedge A1) (A1 && A2 && A3) |-> (X == 1'b1)
    );

    // When B1 and VPB are HIGH, X must be HIGH.
    check_b_term_drives_x: assert property (
        @(posedge A1) (B1 && VPB) |-> (X == 1'b1)
    );

    // When both product terms are LOW, X must be LOW.
    check_x_zero_when_no_term: assert property (
        @(posedge A1) (!((A1 && A2 && A3) || (B1 && VPB))) |-> (X == 1'b0)
    );

    // If X is HIGH, at least one product term must be HIGH.
    check_x_high_implies_term_true: assert property (
        @(posedge A1) X |-> ((A1 && A2 && A3) || (B1 && VPB))
    );

    // If X is LOW, both product terms must be LOW.
    check_x_low_implies_both_terms_low: assert property (
        @(posedge A1) (!X) |-> (!((A1 && A2 && A3)) && !(B1 && VPB))
    );
endmodule

rtl:
module absolute_value (
    input [3:0] binary,
    output reg [3:0] abs_val
);

    always @(*) begin
        if (binary[3] == 1) begin
            abs_val = ~binary + 1;
        end else begin
            abs_val = binary;
        end
    end

endmodule

sva:
module absolute_value_sva (
    input logic clk,
    input logic [3:0] binary,
    input logic [3:0] abs_val
);
    // Analysis: No clock/reset in RTL; purely combinational absolute value function on 4-bit input.
    // Behavior: if binary[3]==1 then abs_val=(~binary+1)[3:0], else abs_val=binary.

    // Output equals mux of pass-through or two's complement based on sign bit.
    check_functional_select: assert property (
        @(posedge clk) abs_val == (binary[3] ? ((~binary + 4'b0001)[3:0]) : binary)
    );

    // When input is negative, output is the 2's complement of input (truncated to 4 bits).
    check_negative_path_twos_complement: assert property (
        @(posedge clk) binary[3] |-> (abs_val == ((~binary + 4'b0001)[3:0]))
    );

    // When input is non-negative, output equals input.
    check_positive_path_passthrough: assert property (
        @(posedge clk) !binary[3] |-> (abs_val == binary)
    );

    // Zero maps to zero.
    check_zero_maps_to_zero: assert property (
        @(posedge clk) (binary == 4'd0) |-> (abs_val == 4'd0)
    );

    // Minimum negative (-8, 4'b1000) maps to 8 (4'b1000).
    check_minneg_maps_to_8: assert property (
        @(posedge clk) (binary == 4'b1000) |-> (abs_val == 4'b1000)
    );

    // For negative inputs except -8, the result has MSB 0.
    check_neg_nonmin_msb_zero: assert property (
        @(posedge clk) (binary[3] && (binary != 4'b1000)) |-> (abs_val[3] == 1'b0)
    );

    // For negative inputs except -8, the result is non-zero.
    check_neg_nonmin_nonzero: assert property (
        @(posedge clk) (binary[3] && (binary != 4'b1000)) |-> (abs_val != 4'd0)
    );

    // Output magnitude is always <= 8.
    check_output_range_le_8: assert property (
        @(posedge clk) abs_val <= 4'd8
    );

    // For non-negative inputs, the MSB of the output is 0.
    check_nonneg_msb_zero: assert property (
        @(posedge clk) !binary[3] |-> (abs_val[3] == 1'b0)
    );

    // Equivalent formulation: abs = (binary XOR sign-mask) + sign (truncated to 4 bits).
    check_xor_plus_sign_equivalence: assert property (
        @(posedge clk) abs_val == (((binary ^ {4{binary[3]}}) + {3'b000, binary[3]})[3:0])
    );

endmodule

rtl:
module four_bit_comparator (
  input [3:0] a,
  input [3:0] b,
  output reg eq,
  output reg gt,
  output reg lt
);

  // Check for equality
  always @* begin
    eq = (a == b);
  end

  // Check for greater than
  always @* begin
    if (a > b)
      gt = 1;
    else
      gt = 0;
  end

  // Check for less than
  always @* begin
    if (a < b)
      lt = 1;
    else
      lt = 0;
  end

endmodule

sva:
module four_bit_comparator_sva (
    input logic clk,
    input logic [3:0] a,
    input logic [3:0] b,
    input logic eq,
    input logic gt,
    input logic lt
);
    // eq must equal (a == b)
    check_eq_definition: assert property (
        @(posedge clk) (eq == (a == b))
    );

    // gt must equal (a > b)
    check_gt_definition: assert property (
        @(posedge clk) (gt == (a > b))
    );

    // lt must equal (a < b)
    check_lt_definition: assert property (
        @(posedge clk) (lt == (a < b))
    );

    // Exactly one of {eq, gt, lt} is HIGH
    check_onehot_relation: assert property (
        @(posedge clk) ((eq + gt + lt) == 1)
    );

    // If eq is HIGH, gt and lt must be LOW
    check_eq_exclusive: assert property (
        @(posedge clk) eq |-> (!gt && !lt)
    );

    // If gt is HIGH, eq and lt must be LOW
    check_gt_exclusive: assert property (
        @(posedge clk) gt |-> (!eq && !lt)
    );

    // If lt is HIGH, eq and gt must be LOW
    check_lt_exclusive: assert property (
        @(posedge clk) lt |-> (!eq && !gt)
    );

    // If a equals b, outputs must be eq=1, gt=0, lt=0
    check_outputs_when_equal: assert property (
        @(posedge clk) (a == b) |-> (eq && !gt && !lt)
    );

    // If a is greater than b, outputs must be gt=1, eq=0, lt=0
    check_outputs_when_greater: assert property (
        @(posedge clk) (a > b) |-> (gt && !eq && !lt)
    );

    // If a is less than b, outputs must be lt=1, eq=0, gt=0
    check_outputs_when_less: assert property (
        @(posedge clk) (a < b) |-> (lt && !eq && !gt)
    );
endmodule

