module nand4 (
    Y   ,
    A   ,
    B   ,
    C   ,
    D   ,
    VPWR,
    VGND,
    VPB ,
    VNB
);

    output Y   ;
    input  A   ;
    input  B   ;
    input  C   ;
    input  D   ;
    input  VPWR;
    input  VGND;
    input  VPB ;
    input  VNB ;

    wire AB, CD, ABCD;
    assign AB = ~(A & B);
    assign CD = ~(C & D);
    assign ABCD = ~(AB & CD);
    assign Y = ABCD;

endmodule

sva:
module nand4_sva (
    input logic Y,
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB
);
    // Analysis: no clock/reset; pure combinational; Y = (A & B) | (C & D); power pins unused by logic.

    // Y equals (A & B) | (C & D).
    check_function_posA: assert property (
        @(posedge A) Y === ((A & B) | (C & D))
    );

    // Y must be 1 when A and B are both 1.
    check_y_high_when_ab11: assert property (
        @(posedge B) (A==1'b1 && B==1'b1) |-> (Y==1'b1)
    );

    // Y must be 1 when C and D are both 1.
    check_y_high_when_cd11: assert property (
        @(posedge D) (C==1'b1 && D==1'b1) |-> (Y==1'b1)
    );

    // Y must be 0 when B=0 and D=0.
    check_y_zero_when_b0_d0: assert property (
        @(posedge B) (B==1'b0 && D==1'b0) |-> (Y==1'b0)
    );

    // When B=1 and C=0 and D=0, Y equals A.
    check_y_equals_a_when_b1_cd00: assert property (
        @(posedge A) (B==1'b1 && C==1'b0 && D==1'b0) |-> (Y===A)
    );

    // When D=1 and A=0 and B=0, Y equals C.
    check_y_equals_c_when_d1_ab00: assert property (
        @(posedge C) (D==1'b1 && A==1'b0 && B==1'b0) |-> (Y===C)
    );

    // Y must be 0 when all inputs are 0.
    check_y_zero_all_zero: assert property (
        @(posedge A) (A==1'b0 && B==1'b0 && C==1'b0 && D==1'b0) |-> (Y==1'b0)
    );

    // Y must be 1 when all inputs are 1.
    check_y_one_all_one: assert property (
        @(posedge A) (A==1'b1 && B==1'b1 && C==1'b1 && D==1'b1) |-> (Y==1'b1)
    );

    // If A=0 and B=0, Y reduces to C & D.
    check_y_depends_on_cd_when_ab00: assert property (
        @(posedge A) (A==1'b0 && B==1'b0) |-> (Y === (C & D))
    );

    // If C=0 and D=0, Y reduces to A & B.
    check_y_depends_on_ab_when_cd00: assert property (
        @(posedge C) (C==1'b0 && D==1'b0) |-> (Y === (A & B))
    );
endmodule

rtl:
module consecutive_ones(
    input [15:0] input_signal,
    input clk,
    output [3:0] output_signal
);

reg [3:0] count;

always @(posedge clk) begin
    if (input_signal == 16'h0000) begin
        count <= 4'h0;
    end else if (input_signal == 16'hFFFF) begin
        count <= 4'h4;
    end else begin
        if (input_signal[0] == 1'b1 && input_signal[1] == 1'b1 && input_signal[2] == 1'b1 && input_signal[3] == 1'b1) begin
            count <= 4'h4;
        end else if (input_signal[1] == 1'b1 && input_signal[2] == 1'b1 && input_signal[3] == 1'b1) begin
            count <= 4'h3;
        end else if (input_signal[2] == 1'b1 && input_signal[3] == 1'b1) begin
            count <= 4'h2;
        end else if (input_signal[3] == 1'b1) begin
            count <= 4'h1;
        end else begin
            count <= 4'h0;
        end
    end
end

assign output_signal = count;

endmodule

sva:
module consecutive_ones_sva (
    input logic clk,
    input logic [15:0] input_signal,
    input logic [3:0] output_signal
);
    // Clock: clk (posedge). No reset in RTL.
    // Sequential logic: count registered each clk; output_signal = count.
    // Behavior: output is 0..4 based on input; special cases 16'h0000 -> 0, 16'hFFFF -> 4; else based on input[3:0] consecutive 1s ending at bit 3.

    // Output value is always within 0..4 on the next cycle.
    check_output_range_0_to_4: assert property (
        @(posedge clk) 1'b1 |=> (output_signal inside {4'h0,4'h1,4'h2,4'h3,4'h4})
    );

    // All-zero input drives 0 next cycle.
    check_all_zero_maps_to_zero: assert property (
        @(posedge clk) (input_signal == 16'h0000) |=> (output_signal == 4'h0)
    );

    // All-one 16-bit input drives 4 next cycle.
    check_all_ones16_maps_to_four: assert property (
        @(posedge clk) (input_signal == 16'hFFFF) |=> (output_signal == 4'h4)
    );

    // Lower nibble 1111 drives 4 next cycle.
    check_lower_nibble_1111_maps_to_four: assert property (
        @(posedge clk) (input_signal[3:0] == 4'hF) |=> (output_signal == 4'h4)
    );

    // Lower nibble 1110 drives 3 next cycle.
    check_lower_nibble_1110_maps_to_three: assert property (
        @(posedge clk) ((input_signal[3:1] == 3'b111) && (input_signal[0] == 1'b0)) |=> (output_signal == 4'h3)
    );

    // Lower nibble 11x? with b1==0 (i.e., b3=1,b2=1,b1=0) drives 2 next cycle.
    check_lower_nibble_110x_b1_0_maps_to_two: assert property (
        @(posedge clk) ((input_signal[3:2] == 2'b11) && (input_signal[1] == 1'b0)) |=> (output_signal == 4'h2)
    );

    // Lower nibble 10xx (b3=1,b2=0) drives 1 next cycle.
    check_lower_nibble_10xx_maps_to_one: assert property (
        @(posedge clk) ((input_signal[3] == 1'b1) && (input_signal[2] == 1'b0)) |=> (output_signal == 4'h1)
    );

    // If b3 is 0, output is 0 next cycle.
    check_b3_zero_maps_to_zero: assert property (
        @(posedge clk) (input_signal[3] == 1'b0) |=> (output_signal == 4'h0)
    );

    // If input is unchanged across cycles, output is unchanged on the next cycle.
    check_stateless_mapping_stability: assert property (
        @(posedge clk) (input_signal == $past(input_signal)) |=> (output_signal == $past(output_signal))
    );

endmodule

rtl:
module full_adder (
        input A,    // Input A to the adder
        input B,    // Input B to the adder
        input Cin,  // Carry-in to the adder
        output Sum, // Output of the adder
        output Cout // Carry-out of the adder
    );

    assign Sum = A ^ B ^ Cin;
    assign Cout = (A & B) | (B & Cin) | (Cin & A);

endmodule

module ripple_carry_adder (
        input [3:0] A,    // Input A to the adder
        input [3:0] B,    // Input B to the adder
        input Cin,        // Carry-in to the adder
        output [3:0] Sum, // Output of the adder
        output Cout      // Carry-out of the adder
    );

    // Define internal wires
    wire [2:0] carry;

    // Instantiate full adder cells
    full_adder adder_0(.A(A[0]), .B(B[0]), .Cin(Cin), .Sum(Sum[0]), .Cout(carry[0]));
    full_adder adder_1(.A(A[1]), .B(B[1]), .Cin(carry[0]), .Sum(Sum[1]), .Cout(carry[1]));
    full_adder adder_2(.A(A[2]), .B(B[2]), .Cin(carry[1]), .Sum(Sum[2]), .Cout(carry[2]));
    full_adder adder_3(.A(A[3]), .B(B[3]), .Cin(carry[2]), .Sum(Sum[3]), .Cout(Cout));

endmodule

module up_down_counter (
        input clk,     // Clock input
        input reset,   // Synchronous active-high reset
        input Up,      // Up input to the counter
        input Down,    // Down input to the counter
        output [3:0] Q // Output of the counter
    );

    // Define internal registers
    reg [3:0] count;

    // Counter logic
    always @(posedge clk) begin
        if (reset) begin
            count <= 4'b0000; // Reset to zero
        end else begin
            if (Up && !Down) begin
                count <= count + 1'b1; // Increment on Up
            end else if (!Up && Down) begin
                count <= count - 1'b1; // Decrement on Down
            end
        end
    end

    // Output assignment
    assign Q = count;

endmodule

sva:
module up_down_counter_sva (
    input logic clk,
    input logic reset,    // synchronous active-high reset
    input logic Up,
    input logic Down,
    input logic [3:0] Q
);
    // Reset sets Q to zero on the next cycle.
    check_reset_clears_q_next: assert property (
        @(posedge clk) reset |=> (Q == 4'b0000)
    );

    // While reset stays asserted, Q remains zero.
    check_hold_zero_while_reset: assert property (
        @(posedge clk) ($past(reset) && reset) |-> (Q == 4'b0000)
    );

    // Increment by 1 when Up=1 and Down=0.
    check_inc_on_up_only: assert property (
        @(posedge clk) disable iff (reset) (Up && !Down) |=> (Q == $past(Q) + 1'b1)
    );

    // Decrement by 1 when Up=0 and Down=1.
    check_dec_on_down_only: assert property (
        @(posedge clk) disable iff (reset) (!Up && Down) |=> (Q == $past(Q) - 1'b1)
    );

    // Hold value when Up=0 and Down=0.
    check_hold_on_both_low: assert property (
        @(posedge clk) disable iff (reset) (!Up && !Down) |=> (Q == $past(Q))
    );

    // Hold value when Up=1 and Down=1.
    check_hold_on_both_high: assert property (
        @(posedge clk) disable iff (reset) (Up && Down) |=> (Q == $past(Q))
    );

    // Step size each cycle is 0, +1, or -1 (modulo 16) when not in reset.
    check_step_bounded_no_reset: assert property (
        @(posedge clk) disable iff (reset) 1'b1 |=> ((Q == $past(Q)) || (Q == $past(Q) + 1'b1) || (Q == $past(Q) - 1'b1))
    );

    // A change in Q implies exactly one of Up/Down was asserted in the prior cycle.
    check_change_requires_one_hot_cmd: assert property (
        @(posedge clk) disable iff (reset) (Q != $past(Q)) |-> ($past(Up) ^ $past(Down))
    );

    // If Q increments by 1, the prior command must have been Up=1, Down=0.
    check_inc_implies_up_only: assert property (
        @(posedge clk) disable iff (reset) (Q == $past(Q) + 1'b1) |-> ($past(Up) && !$past(Down))
    );

    // If Q decrements by 1, the prior command must have been Up=0, Down=1.
    check_dec_implies_down_only: assert property (
        @(posedge clk) disable iff (reset) (Q == $past(Q) - 1'b1) |-> (!$past(Up) && $past(Down))
    );
endmodule

rtl:
module mux4to1 (
  input A,
  input B,
  input C,
  input D,
  input [1:0] S,
  output Y
);

  wire notS0, notS1;

  assign notS0 = ~S[0];
  assign notS1 = ~S[1];

  assign Y = (A & notS1 & notS0) | (B & notS1 & S[0]) | (C & S[1] & notS0) | (D & S[1] & S[0]);

endmodule

sva:
module mux4to1_sva (
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic [1:0] S,
    input logic Y
);
    // Analysis: no clock/reset in RTL; pure combinational mux; sample assertions on input edges.

    // Y must equal the RTL sum-of-products implementation.
    check_sop_equivalence: assert property (
        @(posedge A or posedge B or posedge C or posedge D or posedge S[0] or posedge S[1])
        Y == ((A & (~S[1]) & (~S[0])) |
              (B & (~S[1]) &  S[0])  |
              (C &  S[1]  & (~S[0])) |
              (D &  S[1]  &  S[0]))
    );

    // When S==2'b00, Y must equal A.
    check_select_00_A: assert property (
        @(posedge A or posedge B or posedge C or posedge D or posedge S[0] or posedge S[1])
        (S == 2'b00) |-> (Y == A)
    );

    // When S==2'b01, Y must equal B.
    check_select_01_B: assert property (
        @(posedge A or posedge B or posedge C or posedge D or posedge S[0] or posedge S[1])
        (S == 2'b01) |-> (Y == B)
    );

    // When S==2'b10, Y must equal C.
    check_select_10_C: assert property (
        @(posedge A or posedge B or posedge C or posedge D or posedge S[0] or posedge S[1])
        (S == 2'b10) |-> (Y == C)
    );

    // When S==2'b11, Y must equal D.
    check_select_11_D: assert property (
        @(posedge A or posedge B or posedge C or posedge D or posedge S[0] or posedge S[1])
        (S == 2'b11) |-> (Y == D)
    );

    // If all data inputs are 0, Y must be 0 for any S.
    check_all_zero_inputs: assert property (
        @(posedge A or posedge B or posedge C or posedge D or posedge S[0] or posedge S[1])
        ((A==1'b0) && (B==1'b0) && (C==1'b0) && (D==1'b0)) |-> (Y==1'b0)
    );

    // If all data inputs are 1, Y must be 1 for any S.
    check_all_one_inputs: assert property (
        @(posedge A or posedge B or posedge C or posedge D or posedge S[0] or posedge S[1])
        ((A==1'b1) && (B==1'b1) && (C==1'b1) && (D==1'b1)) |-> (Y==1'b1)
    );
endmodule

