rtl:
module d_ff_clear_preset (
    input clk,
    input d,
    input clr,
    input preset,
    output reg q,
    output reg q_n
);

    always @(posedge clk) begin
        if (clr) begin
            q <= 0;
            q_n <= 1;
        end else if (preset) begin
            q <= 1;
            q_n <= 0;
        end else begin
            q <= d;
            q_n <= ~d;
        end
    end

endmodule

sva:
module d_ff_clear_preset_sva (
    input logic clk,
    input logic d,
    input logic clr,
    input logic preset,
    input logic q,
    input logic q_n
);
    // q_n is always the complement of q.
    outputs_are_complements: assert property (
        @(posedge clk) disable iff (1'b0) (q_n == ~q)
    );

    // q next-state follows priority: clr > preset > d.
    q_next_matches_priority: assert property (
        @(posedge clk) disable iff (1'b0)
            q == ( $past(clr,1,1'b0) ? 1'b0
                 : ($past(preset,1,1'b0) ? 1'b1
                 :  $past(d,1,1'b0) ) )
    );

    // q_n next-state follows priority: clr > preset > ~d.
    qn_next_matches_priority: assert property (
        @(posedge clk) disable iff (1'b0)
            q_n == ( $past(clr,1,1'b0) ? 1'b1
                   : ($past(preset,1,1'b0) ? 1'b0
                   :  ~ $past(d,1,1'b0) ) )
    );

    // If clr was 1 last cycle, outputs are q=0, q_n=1 now.
    clr_forces_clear: assert property (
        @(posedge clk) disable iff (1'b0)
            $past(clr,1,1'b0) |=> (q == 1'b0 && q_n == 1'b1)
    );

    // If preset was 1 and clr was 0 last cycle, outputs are q=1, q_n=0 now.
    preset_sets_when_no_clr: assert property (
        @(posedge clk) disable iff (1'b0)
            (!$past(clr,1,1'b0) && $past(preset,1,1'b0)) |=> (q == 1'b1 && q_n == 1'b0)
    );

    // If neither clr nor preset were 1 last cycle, capture d and ~d now.
    capture_d_when_no_ctrl: assert property (
        @(posedge clk) disable iff (1'b0)
            (!$past(clr,1,1'b0) && !$past(preset,1,1'b0)) |=> (q == $past(d,1,1'b0) && q_n == ~ $past(d,1,1'b0))
    );

    // If both clr and preset were 1 last cycle, clr wins (q=0, q_n=1).
    clr_overrides_preset: assert property (
        @(posedge clk) disable iff (1'b0)
            ($past(clr,1,1'b0) && $past(preset,1,1'b0)) |=> (q == 1'b0 && q_n == 1'b1)
    );
endmodule

rtl:
module dff_with_set_clear_preset (
    input CLK,
    input D,
    input SET,
    input CLR,
    input PRE,
    output reg Q,
    output Q_N
);

always @(posedge CLK) begin
    if (SET) begin
        Q <= 1'b1;
    end else if (CLR) begin
        Q <= 1'b0;
    end else if (PRE) begin
        Q <= 1'b1;
    end else begin
        Q <= D;
    end
end

assign Q_N = ~Q;

endmodule

sva:
module dff_with_set_clear_preset_sva (
    input logic CLK,
    input logic D,
    input logic SET,
    input logic CLR,
    input logic PRE,
    input logic Q,
    input logic Q_N
);
    // Q_N is always the complement of Q.
    check_qn_complement: assert property (
        @(posedge CLK) Q_N == ~Q
    );

    // If SET was 1 in the previous cycle, Q must be 1 now (highest priority).
    check_set_priority: assert property (
        @(posedge CLK) $past(SET) |-> (Q == 1'b1)
    );

    // If CLR was 1 and SET was 0 in the previous cycle, Q must be 0.
    check_clr_priority: assert property (
        @(posedge CLK) (!$past(SET) && $past(CLR)) |-> (Q == 1'b0)
    );

    // If PRE was 1 and SET/CLR were 0 in the previous cycle, Q must be 1.
    check_pre_priority: assert property (
        @(posedge CLK) (!$past(SET) && !$past(CLR) && $past(PRE)) |-> (Q == 1'b1)
    );

    // If no controls were 1 in the previous cycle, Q captures D from the previous cycle.
    check_data_capture_no_controls: assert property (
        @(posedge CLK) (!$past(SET) && !$past(CLR) && !$past(PRE)) |-> (Q == $past(D))
    );

    // SET overrides CLR when both were 1 in the previous cycle.
    check_set_overrides_clr: assert property (
        @(posedge CLK) ($past(SET) && $past(CLR)) |-> (Q == 1'b1)
    );

    // SET overrides PRE when both were 1 in the previous cycle.
    check_set_overrides_pre: assert property (
        @(posedge CLK) ($past(SET) && $past(PRE)) |-> (Q == 1'b1)
    );

    // CLR overrides PRE when SET was 0 and both CLR and PRE were 1 in the previous cycle.
    check_clr_overrides_pre: assert property (
        @(posedge CLK) (!$past(SET) && $past(CLR) && $past(PRE)) |-> (Q == 1'b0)
    );

    // If CLR was 1 and SET was 0 in the previous cycle, Q_N must be 1 now.
    check_qn_on_clr: assert property (
        @(posedge CLK) (!$past(SET) && $past(CLR)) |-> (Q_N == 1'b1)
    );

    // If SET was 1 in the previous cycle, Q_N must be 0 now.
    check_qn_on_set: assert property (
        @(posedge CLK) $past(SET) |-> (Q_N == 1'b0)
    );
endmodule

module Johnson_counter_sva (
    input logic        clk,
    input logic        rst_n,       // active-low reset
    input logic [7:0]  Q,
    input logic [7:0]  shift_reg
);

    ///// Reset behavior /////
    // During reset, shift_reg and Q clear to 0.
    check_reset_clears_regs: assert property (
        @(posedge clk) (!rst_n) |-> (shift_reg == 8'h00) && (Q == 8'h00)
    );

    // On reset deassertion, first-cycle shift_reg and Q are 0.
    check_post_reset_values: assert property (
        @(posedge clk) $rose(rst_n) |-> (shift_reg == 8'h00) && (Q == 8'h00)
    );

    ///// State update /////
    // When running, shift_reg rotates left by one bit each cycle.
    check_shift_rotate_left: assert property (
        @(posedge clk) disable iff (!rst_n)
            $past(rst_n) |-> (shift_reg == { $past(shift_reg)[6:0], $past(shift_reg)[7] })
    );

    ///// Q decode from previous shift_reg /////
    // Q=0x00 when previous shift_reg is 0x00 or 0xFF.
    map_q_from_sr_0000: assert property (
        @(posedge clk) disable iff (!rst_n)
            $past(rst_n) && (($past(shift_reg) == 8'h00) || ($past(shift_reg) == 8'hFF))
            |-> (Q == 8'h00)
    );

    // Q=0x01 when previous shift_reg is 0x80 or 0x7F.
    map_q_from_sr_0001: assert property (
        @(posedge clk) disable iff (!rst_n)
            $past(rst_n) && (($past(shift_reg) == 8'h80) || ($past(shift_reg) == 8'h7F))
            |-> (Q == 8'h01)
    );

    // Q=0x03 when previous shift_reg is 0xC0 or 0x3F.
    map_q_from_sr_0011: assert property (
        @(posedge clk) disable iff (!rst_n)
            $past(rst_n) && (($past(shift_reg) == 8'hC0) || ($past(shift_reg) == 8'h3F))
            |-> (Q == 8'h03)
    );

    // Q=0x07 when previous shift_reg is 0xE0 or 0x1F.
    map_q_from_sr_0111: assert property (
        @(posedge clk) disable iff (!rst_n)
            $past(rst_n) && (($past(shift_reg) == 8'hE0) || ($past(shift_reg) == 8'h1F))
            |-> (Q == 8'h07)
    );

    // Q=0x0F when previous shift_reg is 0xF0 or 0x0F.
    map_q_from_sr_1111: assert property (
        @(posedge clk) disable iff (!rst_n)
            $past(rst_n) && (($past(shift_reg) == 8'hF0) || ($past(shift_reg) == 8'h0F))
            |-> (Q == 8'h0F)
    );

    // Q=0x0E when previous shift_reg is 0xF8 or 0x07.
    map_q_from_sr_1110: assert property (
        @(posedge clk) disable iff (!rst_n)
            $past(rst_n) && (($past(shift_reg) == 8'hF8) || ($past(shift_reg) == 8'h07))
            |-> (Q == 8'h0E)
    );

    // Q=0x0C when previous shift_reg is 0xFC or 0x03.
    map_q_from_sr_1100: assert property (
        @(posedge clk) disable iff (!rst_n)
            $past(rst_n) && (($past(shift_reg) == 8'hFC) || ($past(shift_reg) == 8'h03))
            |-> (Q == 8'h0C)
    );

    // Q=0x08 when previous shift_reg is 0xFE or 0x01.
    map_q_from_sr_1000: assert property (
        @(posedge clk) disable iff (!rst_n)
            $past(rst_n) && (($past(shift_reg) == 8'hFE) || ($past(shift_reg) == 8'h01))
            |-> (Q == 8'h08)
    );

    // If previous shift_reg not in decode table, Q holds its value.
    check_q_holds_on_no_match: assert property (
        @(posedge clk) disable iff (!rst_n)
            $past(rst_n) &&
            !($past(shift_reg) inside {8'h00,8'h80,8'hC0,8'hE0,8'hF0,8'hF8,8'hFC,8'hFE,
                                       8'hFF,8'h7F,8'h3F,8'h1F,8'h0F,8'h07,8'h03,8'h01})
            |-> (Q == $past(Q))
    );

    ///// Q value invariants /////
    // Upper nibble of Q is always zero (due to 4-bit assignments).
    check_q_upper_nibble_zero: assert property (
        @(posedge clk) (Q[7:4] == 4'b0000)
    );

    // Q[3:0] is always one of the defined decode values.
    check_q_lsb_allowed_set: assert property (
        @(posedge clk) disable iff (!rst_n)
            (Q[3:0] inside {4'h0,4'h1,4'h3,4'h7,4'hF,4'hE,4'hC,4'h8})
    );

endmodule

rtl:
module data_adapter (
    input              clk,
    input              reset_n,
    output reg         in_ready,
    input              in_valid,
    input      [ 7: 0] in_data,
    input      [ 7: 0] in_channel,
    input              in_startofpacket,
    input              in_endofpacket,
    input              out_ready,
    output reg         out_valid,
    output reg [ 7: 0] out_data,
    output reg         out_startofpacket,
    output reg         out_endofpacket
);

   reg          out_channel;
   parameter    MAX_CHANNEL = 15;

   // ---------------------------------------------------------------------
   //| Payload Mapping
   // ---------------------------------------------------------------------
   always @* begin
      in_ready = out_ready;
      out_valid = 0;
      out_data = in_data;
      out_startofpacket = in_startofpacket;
      out_endofpacket = in_endofpacket;

      out_channel = in_channel;
      // Suppress channels that are higher than the destination's max_channel.
      if (in_channel > MAX_CHANNEL) begin
         out_valid = 0;
      end else begin
         out_valid = in_valid;
      end
   end

endmodule

sva:
module data_adapter_sva (
    input logic              clk,
    input logic              reset_n,
    input logic              in_ready,
    input logic              in_valid,
    input logic      [ 7: 0] in_data,
    input logic      [ 7: 0] in_channel,
    input logic              in_startofpacket,
    input logic              in_endofpacket,
    input logic              out_ready,
    input logic              out_valid,
    input logic      [ 7: 0] out_data,
    input logic              out_startofpacket,
    input logic              out_endofpacket
);
    // Clock: clk; Reset: reset_n (active-low). Logic: combinational.
    // Behavior: in_ready=out_ready; data/SOP/EOP pass-through; out_valid=in_valid && (in_channel<=15).

    localparam logic [7:0] MAX_CHANNEL = 8'd15;

    // Backpressure passthrough: in_ready mirrors out_ready.
    check_in_ready_passthrough: assert property (
        @(posedge clk) disable iff (!reset_n) in_ready == out_ready
    );

    // Data payload passes through unchanged.
    check_data_passthrough: assert property (
        @(posedge clk) disable iff (!reset_n) out_data == in_data
    );

    // Start-of-packet passes through unchanged.
    check_sop_passthrough: assert property (
        @(posedge clk) disable iff (!reset_n) out_startofpacket == in_startofpacket
    );

    // End-of-packet passes through unchanged.
    check_eop_passthrough: assert property (
        @(posedge clk) disable iff (!reset_n) out_endofpacket == in_endofpacket
    );

    // out_valid equals in_valid when channel <= MAX; otherwise 0.
    check_out_valid_definition: assert property (
        @(posedge clk) disable iff (!reset_n) out_valid == (in_valid && (in_channel <= MAX_CHANNEL))
    );

    // Outputs remain stable if all inputs remain stable (purely combinational mapping).
    check_outputs_stable_when_inputs_stable: assert property (
        @(posedge clk) disable iff (!reset_n)
            $stable({in_valid, in_data, in_channel, in_startofpacket, in_endofpacket, out_ready})
            |-> $stable({in_ready, out_valid, out_data, out_startofpacket, out_endofpacket})
    );

    // out_valid is independent of out_ready (since not used in its computation).
    check_out_valid_independent_of_out_ready: assert property (
        @(posedge clk) disable iff (!reset_n)
            $stable({in_valid, in_channel}) && $changed(out_ready)
            |-> $stable(out_valid)
    );

    // out_valid is independent of payload/SOP/EOP (since not used in its computation).
    check_out_valid_independent_of_payload_ctrl: assert property (
        @(posedge clk) disable iff (!reset_n)
            $stable({in_valid, in_channel}) && $changed({in_data, in_startofpacket, in_endofpacket})
            |-> $stable(out_valid)
    );

    // When channel is in range for two cycles, a rising in_valid causes a rising out_valid.
    check_out_valid_rise_tracks_in_valid: assert property (
        @(posedge clk) disable iff (!reset_n)
            $rose(in_valid) && (in_channel <= MAX_CHANNEL) && $past(in_channel <= MAX_CHANNEL)
            |-> $rose(out_valid)
    );

    // When channel is in range for two cycles, a falling in_valid causes a falling out_valid.
    check_out_valid_fall_tracks_in_valid: assert property (
        @(posedge clk) disable iff (!reset_n)
            $fell(in_valid) && (in_channel <= MAX_CHANNEL) && $past(in_channel <= MAX_CHANNEL)
            |-> $fell(out_valid)
    );

endmodule

rtl:
module dffrl_async (din, clk, rst_l, q, se, si, so);

parameter SIZE = 1;

input   [SIZE-1:0]      din ;   // data in
input                   clk ;   // clk or scan clk
input                   rst_l ;   // reset

output  [SIZE-1:0]      q ;     // output

input                   se ;    // scan-enable
input   [SIZE-1:0]      si ;    // scan-input
output  [SIZE-1:0]      so ;    // scan-output

reg     [SIZE-1:0]      q ;

always @ (posedge clk or negedge rst_l) begin
	if (!rst_l)
		q[SIZE-1:0]  <= {SIZE{1'b0}};
	else begin
		if (se)
			q[SIZE-1:0]  <= si[SIZE-1:0];
		else
			q[SIZE-1:0]  <= din[SIZE-1:0];
	end
end

assign so[SIZE-1:0] = q[SIZE-1:0] ;

endmodule

sva:
module dffrl_async_sva #(
    parameter SIZE = 1
) (
    input  logic [SIZE-1:0] din,
    input  logic            clk,
    input  logic            rst_l,   // active-low async reset
    input  logic [SIZE-1:0] q,
    input  logic            se,
    input  logic [SIZE-1:0] si,
    input  logic [SIZE-1:0] so
);
    // Clock: clk; Reset: rst_l (active-low, asynchronous)
    // Logic: sequential DFF with async reset and scan mux; so mirrors q

    // so must always mirror q (continuous assign)
    so_mirrors_q: assert property (
        @(posedge clk) so == q
    );

    // While reset is asserted low, q must be all zeros
    reset_low_forces_q_zero: assert property (
        @(posedge clk) !rst_l |-> (q == {SIZE{1'b0}})
    );

    // While reset is asserted low, so must be all zeros (since so==q)
    reset_low_forces_so_zero: assert property (
        @(posedge clk) !rst_l |-> (so == {SIZE{1'b0}})
    );

    // One cycle after reset was low, q must still be all zeros
    q_zero_one_cycle_after_reset_low: assert property (
        @(posedge clk) $past(!rst_l) |-> (q == {SIZE{1'b0}})
    );

    // One cycle after reset was low, so must still be all zeros
    so_zero_one_cycle_after_reset_low: assert property (
        @(posedge clk) $past(!rst_l) |-> (so == {SIZE{1'b0}})
    );

    // With se=1 (scan), q loads si on the next cycle
    capture_si_when_se: assert property (
        @(posedge clk) disable iff (!rst_l) se |=> (q == $past(si))
    );

    // With se=0 (functional), q loads din on the next cycle
    capture_din_when_not_se: assert property (
        @(posedge clk) disable iff (!rst_l) !se |=> (q == $past(din))
    );

    // General mux behavior: q next equals prior selected input when not in reset
    selected_mux_update: assert property (
        @(posedge clk) disable iff (!rst_l) 1 |=> (q == $past(se ? si : din))
    );

endmodule

rtl:
module binary_counter(
    input clk, rst,
    output reg [3:0] count,
    output reg max
    );

    always @(posedge clk) begin
        if (rst) begin
            count <= 0;
            max <= 0;
        end
        else begin
            if (count == 4'b1011) begin
                count <= 0;
                max <= 1;
            end
            else begin
                count <= count + 1;
                max <= 0;
            end
        end
    end
endmodule

sva:
module binary_counter_sva (
    input logic clk,
    input logic rst,
    input logic [3:0] count,
    input logic max
);
    // On synchronous reset, drive count=0 and max=0.
    reset_outputs_zero: assert property (
        @(posedge clk) rst |-> (count == 4'd0) && (max == 1'b0)
    );

    // If prev cycle not in reset and prev count!=11, increment and keep max=0.
    incr_when_prev_not_11: assert property (
        @(posedge clk) disable iff (rst || $initstate)
            ($past(!rst) && ($past(count) != 4'd11)) |-> (count == ($past(count) + 4'd1)) && (max == 1'b0)
    );

    // If prev cycle not in reset and prev count==11, wrap to 0 and set max=1.
    wrap_when_prev_is_11: assert property (
        @(posedge clk) disable iff (rst || $initstate)
            ($past(!rst) && ($past(count) == 4'd11)) |-> (count == 4'd0) && (max == 1'b1)
    );

    // max can be 1 only when previous count was 11 (and prev not in reset).
    max_only_when_prev_11: assert property (
        @(posedge clk) disable iff (rst || $initstate)
            max |-> ($past(!rst) && ($past(count) == 4'd11))
    );

    // Whenever max=1, the current count must be 0.
    max_implies_zero_count: assert property (
        @(posedge clk) disable iff (rst)
            max |-> (count == 4'd0)
    );

    // When current count is 0, max reflects whether previous count was 11.
    zero_count_encodes_prev: assert property (
        @(posedge clk) disable iff (rst || $initstate)
            (count == 4'd0) |-> (max == ($past(count) == 4'd11))
    );

    // Count transition is only prev+1 or wrap from 11 to 0 (when prev not in reset).
    count_transition_valid: assert property (
        @(posedge clk) disable iff (rst || $initstate)
            $past(!rst) |-> ((($past(count) == 4'd11) && (count == 4'd0)) ||
                             (($past(count) != 4'd11) && (count == ($past(count) + 4'd1))))
    );

    // max is a single-cycle pulse (cannot be high in consecutive cycles).
    max_one_cycle_pulse: assert property (
        @(posedge clk) disable iff (rst || $initstate)
            max |=> !max
    );

    // When current count is 11, max must be 0.
    max_low_when_count_11: assert property (
        @(posedge clk) disable iff (rst || $initstate)
            (count == 4'd11) |-> (max == 1'b0)
    );

    // After a wrap cycle (count=0,max=1), next cycle increments to 1 and clears max (or reset intervenes).
    next_after_wrap_increments: assert property (
        @(posedge clk) disable iff (rst || $initstate)
            (count == 4'd0 && max == 1'b1) |=> (rst || (count == 4'd1 && max == 1'b0))
    );
endmodule

rtl:
module top_module(
    input a,
    input b,
    input sel_xor,
    input sel_mux,
    output wire out_always
);

wire xor_out;
wire mux_out;

xor_gate xor_inst(
    .a(a),
    .b(b),
    .out(xor_out)
);

mux_2to1 mux_inst(
    .a(a),
    .b(b),
    .sel(sel_mux),
    .out(mux_out)
);

assign out_always = (sel_xor & ~sel_mux) ? xor_out :
                    (sel_mux & ~sel_xor) ? mux_out :
                    (sel_mux & sel_xor) ? 1'b1 : 1'b0;

endmodule
module xor_gate(
    input a,
    input b,
    output wire out
);

assign out = a ^ b;

endmodule
module mux_2to1(
    input a,
    input b,
    input sel,
    output wire out
);

assign out = sel ? b : a;

endmodule

sva:
module top_module_sva (
    input logic clk,         // sampling clock for SVA (DUT has no clock)
    input logic a,
    input logic b,
    input logic sel_xor,
    input logic sel_mux,
    input logic out_always
);
    // Functional equivalence to the RTL ternary chain.
    check_function_equivalence: assert property (
        @(posedge clk)
        out_always == ((sel_xor & ~sel_mux) ? (a ^ b) :
                       (sel_mux & ~sel_xor) ? b :
                       (sel_mux & sel_xor)  ? 1'b1 : 1'b0)
    );

    // When sel_xor=1 and sel_mux=0, output is XOR of a and b.
    check_case_sel10_xor: assert property (
        @(posedge clk) (sel_xor && !sel_mux) |-> (out_always == (a ^ b))
    );

    // When sel_xor=0 and sel_mux=1, output is b (2:1 mux selects b).
    check_case_sel01_b: assert property (
        @(posedge clk) (sel_mux && !sel_xor) |-> (out_always == b)
    );

    // When sel_xor=1 and sel_mux=1, output is constant 1.
    check_case_sel11_one: assert property (
        @(posedge clk) (sel_mux && sel_xor) |-> (out_always == 1'b1)
    );

    // When sel_xor=0 and sel_mux=0, output is constant 0.
    check_case_sel00_zero: assert property (
        @(posedge clk) (!sel_mux && !sel_xor) |-> (out_always == 1'b0)
    );

    // In mux-only case (01), if sel and b are stable, output must be stable (independent of a).
    check_stability_mux_case: assert property (
        @(posedge clk)
        (sel_mux && !sel_xor && $stable(sel_mux) && $stable(sel_xor) && $stable(b)) |-> $stable(out_always)
    );

    // In both-high case (11), if sel remain 11, output stays 1 and stable.
    check_stability_both_high: assert property (
        @(posedge clk)
        (sel_mux && sel_xor && $stable(sel_mux) && $stable(sel_xor)) |-> ($stable(out_always) && (out_always == 1'b1))
    );

    // In both-low case (00), if sel remain 00, output stays 0 and stable.
    check_stability_both_low: assert property (
        @(posedge clk)
        (!sel_mux && !sel_xor && $stable(sel_mux) && $stable(sel_xor)) |-> ($stable(out_always) && (out_always == 1'b0))
    );

    // If all inputs are stable, the output must be stable (purely combinational behavior).
    check_output_stable_when_inputs_stable: assert property (
        @(posedge clk)
        ($stable(a) && $stable(b) && $stable(sel_xor) && $stable(sel_mux)) |-> $stable(out_always)
    );
endmodule

rtl:
module serial_rx #(
		parameter CLK_PER_BIT = 50,
		parameter CTR_SIZE = 6
	)(
		input clk,
		input rst,
		input rx,
		output [7:0] data,
		output new_data
	);

	localparam STATE_SIZE = 2;
	localparam IDLE = 2'd0,
			WAIT_HALF = 2'd1,
			WAIT_FULL = 2'd2,
			WAIT_HIGH = 2'd3;

	reg [CTR_SIZE-1:0] ctr_d, ctr_q;
	reg [2:0] bit_ctr_d, bit_ctr_q;
	reg [7:0] data_d, data_q;
	reg new_data_d, new_data_q;
	reg [STATE_SIZE-1:0] state_d, state_q = IDLE;
	reg rx_d, rx_q;

	assign new_data = new_data_q;
	assign data = data_q;

	always @(*) begin
		rx_d = rx;
		state_d = state_q;
		ctr_d = ctr_q;
		bit_ctr_d = bit_ctr_q;
		data_d = data_q;
		new_data_d = 1'b0;

		case (state_q)
			IDLE: begin
				bit_ctr_d = 3'b0;
				ctr_d = 1'b0;
				if (rx_q == 1'b0) begin
					state_d = WAIT_HALF;
				end
			end
			WAIT_HALF: begin
				ctr_d = ctr_q + 1'b1;
				if (ctr_q == (CLK_PER_BIT >> 1)) begin
					ctr_d = 1'b0;
					state_d = WAIT_FULL;
				end
			end
			WAIT_FULL: begin
				ctr_d = ctr_q + 1'b1;
				if (ctr_q == CLK_PER_BIT - 1) begin
					data_d = {rx_q, data_q[7:1]};
					bit_ctr_d = bit_ctr_q + 1'b1;
					ctr_d = 1'b0;
					if (bit_ctr_q == 3'd7) begin
						state_d = WAIT_HIGH;
						new_data_d = 1'b1;
					end
				end
			end
			WAIT_HIGH: begin
				if (rx_q == 1'b1) begin
					state_d = IDLE;
				end
			end
			default: begin
				state_d = IDLE;
			end
		endcase

	end

	always @(posedge clk) begin
		if (rst) begin
			ctr_q <= 1'b0;
			bit_ctr_q <= 3'b0;
			new_data_q <= 1'b0;
			state_q <= IDLE;
		end else begin
			ctr_q <= ctr_d;
			bit_ctr_q <= bit_ctr_d;
			new_data_q <= new_data_d;
			state_q <= state_d;
		end

		rx_q <= rx_d;
		data_q <= data_d;
	end

endmodule

sva:
module serial_rx_sva (
    input logic clk,
    input logic rst,       // Active-high synchronous reset
    input logic rx,
    input logic [7:0] data,
    input logic new_data
);
    // Clock: posedge clk. Logic: mixed (combinational next-state + sequential regs).

    ///// Reset behavior /////
    // new_data must be LOW during reset.
    check_reset_new_data_low: assert property (
        @(posedge clk) rst |-> (new_data == 1'b0)
    );
    // data holds its value during reset.
    check_reset_data_stable: assert property (
        @(posedge clk) rst |-> $stable(data)
    );

    ///// new_data pulse characteristics /////
    // new_data is a single-cycle pulse.
    check_new_data_single_cycle: assert property (
        @(posedge clk) disable iff (rst) new_data |=> !new_data
    );
    // No consecutive HIGH cycles on new_data.
    check_new_data_no_back_to_back_highs: assert property (
        @(posedge clk) disable iff (rst) !(new_data && $past(new_data))
    );

    ///// Data update behavior relative to new_data /////
    // When new_data rises, data updates in the same cycle.
    check_data_changes_at_new_data: assert property (
        @(posedge clk) disable iff (rst) $rose(new_data) |-> $changed(data)
    );
    // After new_data, data holds at least one cycle.
    check_data_stable_after_new_data: assert property (
        @(posedge clk) disable iff (rst) $rose(new_data) |=> $stable(data)
    );

    ///// Data shifting behavior (port-observable) /////
    // Any data change is a right shift with MSB loaded from previous rx.
    check_data_shift_on_change: assert property (
        @(posedge clk) disable iff (rst) $changed(data) |-> (data === { $past(rx), $past(data[7:1]) })
    );
    // MSB of data on change equals previous rx sample.
    check_msb_matches_rx_on_change: assert property (
        @(posedge clk) disable iff (rst) $changed(data) |-> (data[7] === $past(rx))
    );
    // On the new_data pulse, data reflects the same shift relation.
    check_data_shift_on_new_data: assert property (
        @(posedge clk) disable iff (rst) $rose(new_data) |-> (data === { $past(rx), $past(data[7:1]) })
    );

    ///// Idle/turnaround behavior /////
    // After new_data, data remains stable until the next falling edge of rx (start of next frame).
    check_data_stable_until_next_start: assert property (
        @(posedge clk) disable iff (rst) $rose(new_data) |-> $stable(data) until $fell(rx)
    );
    // new_data cannot assert in the same cycle as a falling edge on rx.
    check_no_immediate_new_data_after_rx_fall: assert property (
        @(posedge clk) disable iff (rst) $fell(rx) |-> !new_data
    );

endmodule

rtl:
module sum_4_bits (input [15:0] in, output reg [3:0] out);

  always @(*) begin
    out = in[15:12] + in[3:0];
  end

endmodule

sva:
module sum_4_bits_sva (
    input logic clk,            // formal clock for assertions
    input logic [15:0] in,
    input logic [3:0]  out
);
    ///// Functional mapping /////
    // out equals sum of high and low nibbles of in (4-bit wrap).
    check_functional_sum: assert property (
        @(posedge clk) out == (in[15:12] + in[3:0])
    );

    ///// Dependency on inputs /////
    // Changing only in[11:4] does not change out.
    check_mid_bits_do_not_affect_output: assert property (
        @(posedge clk)
            ( (in[15:12] == $past(in[15:12], 1, in[15:12])) &&
              (in[3:0]   == $past(in[3:0],   1, in[3:0]))   &&
              (in[11:4]  != $past(in[11:4],  1, in[11:4])) ) |-> 
            ( out == $past(out, 1, out) )
    );

    // out changes only if in[15:12] or in[3:0] changes.
    check_out_changes_only_if_relevant_input_changes: assert property (
        @(posedge clk)
            (out != $past(out, 1, out)) |-> 
            ( (in[15:12] != $past(in[15:12], 1, in[15:12])) || 
              (in[3:0]   != $past(in[3:0],   1, in[3:0])) )
    );

    ///// Stability /////
    // If in is stable, out is stable.
    check_stable_in_implies_stable_out: assert property (
        @(posedge clk) $stable(in) |-> $stable(out)
    );
endmodule

rtl:
module mux (
    input [3:0] D,
    input EN,
    input [1:0] SEL,
    output reg Y
);

always @ (SEL or D or EN) begin
    if (EN) begin
        case (SEL)
            2'b00: Y = D[0];
            2'b01: Y = D[1];
            2'b10: Y = D[2];
            2'b11: Y = D[3];
        endcase
    end else begin
        Y = 0;
    end
end

endmodule

sva:
module mux_sva (
    input logic CLK,
    input logic [3:0] D,
    input logic EN,
    input logic [1:0] SEL,
    input logic Y
);
    // When disabled, output must be 0.
    check_disabled_drives_zero: assert property (
        @(posedge CLK) (!EN) |-> (Y == 1'b0)
    );

    // When enabled and SEL==00, output selects D[0].
    check_enabled_sel00_maps: assert property (
        @(posedge CLK) (EN && (SEL == 2'b00)) |-> (Y == D[0])
    );

    // When enabled and SEL==01, output selects D[1].
    check_enabled_sel01_maps: assert property (
        @(posedge CLK) (EN && (SEL == 2'b01)) |-> (Y == D[1])
    );

    // When enabled and SEL==10, output selects D[2].
    check_enabled_sel10_maps: assert property (
        @(posedge CLK) (EN && (SEL == 2'b10)) |-> (Y == D[2])
    );

    // When enabled and SEL==11, output selects D[3].
    check_enabled_sel11_maps: assert property (
        @(posedge CLK) (EN && (SEL == 2'b11)) |-> (Y == D[3])
    );

    // On falling edge of EN, output must be 0 in the same cycle.
    check_en_fall_forces_zero: assert property (
        @(posedge CLK) $fell(EN) |-> (Y == 1'b0)
    );

    // While disabled and EN stable low, output stays 0 and stable.
    check_stable_zero_when_disabled: assert property (
        @(posedge CLK) (!EN && $stable(EN)) |-> ($stable(Y) && (Y == 1'b0))
    );

    // With EN high, SEL==00, and inputs stable, output is stable.
    check_stable_output_sel00: assert property (
        @(posedge CLK) (EN && $stable(EN) && (SEL == 2'b00) && $stable(SEL) && $stable(D[0])) |-> $stable(Y)
    );

    // With EN high, SEL==01, and inputs stable, output is stable.
    check_stable_output_sel01: assert property (
        @(posedge CLK) (EN && $stable(EN) && (SEL == 2'b01) && $stable(SEL) && $stable(D[1])) |-> $stable(Y)
    );

    // With EN high, SEL==10, and inputs stable, output is stable.
    check_stable_output_sel10: assert property (
        @(posedge CLK) (EN && $stable(EN) && (SEL == 2'b10) && $stable(SEL) && $stable(D[2])) |-> $stable(Y)
    );

    // With EN high, SEL==11, and inputs stable, output is stable.
    check_stable_output_sel11: assert property (
        @(posedge CLK) (EN && $stable(EN) && (SEL == 2'b11) && $stable(SEL) && $stable(D[3])) |-> $stable(Y)
    );
endmodule

rtl:
module bw_clk_cclk_inv_64x (
    clkout,
    clkin );

    output clkout;
    input  clkin;

    assign clkout = ~( clkin );

endmodule

sva:
module bw_clk_cclk_inv_64x_sva (
    input logic clkin,
    input logic clkout
);
    // Output equals bitwise inversion of input on clkin rising edge.
    check_inversion_pos: assert property (
        @(posedge clkin) clkout === ~clkin
    );
    // Output equals bitwise inversion of input on clkin falling edge.
    check_inversion_neg: assert property (
        @(negedge clkin) clkout === ~clkin
    );
    // A 0->1 transition on clkin causes a 1->0 transition on clkout.
    rise_in_fall_out: assert property (
        @(posedge clkin) $rose(clkin) |-> $fell(clkout)
    );
    // A 1->0 transition on clkin causes a 0->1 transition on clkout.
    fall_in_rise_out: assert property (
        @(negedge clkin) $fell(clkin) |-> $rose(clkout)
    );
    // At clkin rising edge, clkout must differ from clkin.
    not_equal_posedge: assert property (
        @(posedge clkin) clkout !== clkin
    );
    // At clkin falling edge, clkout must differ from clkin.
    not_equal_negedge: assert property (
        @(negedge clkin) clkout !== clkin
    );
endmodule

rtl:
module four_bit_adder(a, b, sum);
input [3:0] a;
input [3:0] b;
output [3:0] sum;

assign sum = a + b;

endmodule

sva:
module four_bit_adder_sva (
    input logic [3:0] a,
    input logic [3:0] b,
    input logic [3:0] sum,
    input logic CLK
);
    // DUT has no clock/reset; pure combinational sum = (a + b)[3:0]; assertions sample on CLK.

    // Sum equals 4-bit truncated addition of a and b.
    check_sum_truncated_add: assert property (
        @(posedge CLK) sum == (a + b)[3:0]
    );

    // LSB equals XOR of a[0] and b[0].
    check_lsb_xor: assert property (
        @(posedge CLK) sum[0] == (a[0] ^ b[0])
    );

    // Bit1 follows ripple-carry equation.
    check_bit1_equation: assert property (
        @(posedge CLK) sum[1] == (a[1] ^ b[1] ^ (a[0] & b[0]))
    );

    // Bit2 follows ripple-carry equation.
    check_bit2_equation: assert property (
        @(posedge CLK) sum[2] == (a[2] ^ b[2] ^ ( (a[1] & b[1]) | ((a[1] ^ b[1]) & (a[0] & b[0])) ))
    );

    // Bit3 follows ripple-carry equation.
    check_bit3_equation: assert property (
        @(posedge CLK) sum[3] == (a[3] ^ b[3] ^ ( (a[2] & b[2]) | ((a[2] ^ b[2]) & ( (a[1] & b[1]) | ((a[1] ^ b[1]) & (a[0] & b[0])) ) ) ))
    );

    // Adding zero passes a through.
    check_b_zero_passthrough: assert property (
        @(posedge CLK) (b == 4'd0) |-> (sum == a)
    );

    // Adding zero passes b through.
    check_a_zero_passthrough: assert property (
        @(posedge CLK) (a == 4'd0) |-> (sum == b)
    );

    // Commutativity consistency with built-in addition.
    check_commutativity: assert property (
        @(posedge CLK) sum == (b + a)[3:0]
    );

endmodule

rtl:
module SwapUnit(rs,rt,rd,EXMEMregWrite,EXMEMregisterRd,MEMWBregisterRd,MEMWBregWrite,forwardA,forwardB,rst);
	input[4:0] rs,rt,rd,EXMEMregisterRd,MEMWBregisterRd;
	input EXMEMregWrite,MEMWBregWrite;
	output[1:0] forwardB,forwardA;
	reg[1:0] forwardA,forwardB;
	input rst;

	always @(rs or rt or rd or EXMEMregWrite or EXMEMregisterRd or MEMWBregisterRd or MEMWBregWrite or forwardA or forwardB or rst) begin
		if (rst) begin
			forwardA<=0;
			forwardB<=0;
		end
		else begin
			if(MEMWBregWrite && (MEMWBregisterRd!=0) && !((EXMEMregWrite && (EXMEMregisterRd!=0)) && (EXMEMregisterRd==rs)) && (MEMWBregisterRd==rs))forwardA<=2'b01;
			else if(EXMEMregWrite && (EXMEMregisterRd!=0) && (EXMEMregisterRd==rs)) forwardA<=2'b10;
			else forwardA<=0;
			if(MEMWBregWrite && (MEMWBregisterRd!=0) && !((EXMEMregWrite && (EXMEMregisterRd!=0)) && (EXMEMregisterRd==rt)) && (MEMWBregisterRd==rt))forwardB<=2'b01;
			else if(EXMEMregWrite && (EXMEMregisterRd!=0) && (EXMEMregisterRd==rt)) forwardB<=2'b10;
			else forwardB<=0;

		end
	end


endmodule

sva:
module SwapUnit_sva (
    input logic [4:0] rs,
    input logic [4:0] rt,
    input logic [4:0] rd,
    input logic EXMEMregWrite,
    input logic [4:0] EXMEMregisterRd,
    input logic [4:0] MEMWBregisterRd,
    input logic MEMWBregWrite,
    input logic [1:0] forwardB,
    input logic [1:0] forwardA,
    input logic rst
);
    ///// Reset behavior /////
    // On rst assertion, both forwardA and forwardB drive 0.
    reset_outputs_zero: assert property (
        @(posedge rst) (forwardA == 2'b00) && (forwardB == 2'b00)
    );

    ///// forwardA selection logic /////
    // If EXMEM matches rs and is valid, forwardA selects 2'b10.
    check_forwardA_from_EXMEM: assert property (
        @(posedge EXMEMregWrite or posedge MEMWBregWrite or posedge rst)
        disable iff (rst)
        (EXMEMregWrite && (EXMEMregisterRd != 5'd0) && (EXMEMregisterRd == rs)) |-> (forwardA == 2'b10)
    );
    // If MEMWB matches rs and EXMEM does not, forwardA selects 2'b01.
    check_forwardA_from_MEMWB_no_EXMEM: assert property (
        @(posedge EXMEMregWrite or posedge MEMWBregWrite or posedge rst)
        disable iff (rst)
        (MEMWBregWrite && (MEMWBregisterRd != 5'd0) && (MEMWBregisterRd == rs) &&
         !(EXMEMregWrite && (EXMEMregisterRd != 5'd0) && (EXMEMregisterRd == rs))) |-> (forwardA == 2'b01)
    );
    // If neither EXMEM nor MEMWB matches rs, forwardA is 2'b00.
    check_forwardA_default_zero: assert property (
        @(posedge EXMEMregWrite or posedge MEMWBregWrite or posedge rst)
        disable iff (rst)
        !(EXMEMregWrite && (EXMEMregisterRd != 5'd0) && (EXMEMregisterRd == rs)) &&
        !(MEMWBregWrite && (MEMWBregisterRd != 5'd0) && (MEMWBregisterRd == rs)) |-> (forwardA == 2'b00)
    );
    // When both EXMEM and MEMWB match rs, EXMEM has priority (2'b10).
    check_forwardA_EXMEM_priority: assert property (
        @(posedge EXMEMregWrite or posedge MEMWBregWrite or posedge rst)
        disable iff (rst)
        (EXMEMregWrite && (EXMEMregisterRd != 5'd0) && (EXMEMregisterRd == rs) &&
         MEMWBregWrite && (MEMWBregisterRd != 5'd0) && (MEMWBregisterRd == rs)) |-> (forwardA == 2'b10)
    );
    // forwardA only takes 00, 01, or 10 when not in reset.
    check_forwardA_code_space: assert property (
        @(posedge EXMEMregWrite or posedge MEMWBregWrite or posedge rst)
        disable iff (rst)
        1'b1 |-> (forwardA inside {2'b00, 2'b01, 2'b10})
    );

    ///// forwardB selection logic /////
    // If EXMEM matches rt and is valid, forwardB selects 2'b10.
    check_forwardB_from_EXMEM: assert property (
        @(posedge EXMEMregWrite or posedge MEMWBregWrite or posedge rst)
        disable iff (rst)
        (EXMEMregWrite && (EXMEMregisterRd != 5'd0) && (EXMEMregisterRd == rt)) |-> (forwardB == 2'b10)
    );
    // If MEMWB matches rt and EXMEM does not, forwardB selects 2'b01.
    check_forwardB_from_MEMWB_no_EXMEM: assert property (
        @(posedge EXMEMregWrite or posedge MEMWBregWrite or posedge rst)
        disable iff (rst)
        (MEMWBregWrite && (MEMWBregisterRd != 5'd0) && (MEMWBregisterRd == rt) &&
         !(EXMEMregWrite && (EXMEMregisterRd != 5'd0) && (EXMEMregisterRd == rt))) |-> (forwardB == 2'b01)
    );
    // If neither EXMEM nor MEMWB matches rt, forwardB is 2'b00.
    check_forwardB_default_zero: assert property (
        @(posedge EXMEMregWrite or posedge MEMWBregWrite or posedge rst)
        disable iff (rst)
        !(EXMEMregWrite && (EXMEMregisterRd != 5'd0) && (EXMEMregisterRd == rt)) &&
        !(MEMWBregWrite && (MEMWBregisterRd != 5'd0) && (MEMWBregisterRd == rt)) |-> (forwardB == 2'b00)
    );
    // When both EXMEM and MEMWB match rt, EXMEM has priority (2'b10).
    check_forwardB_EXMEM_priority: assert property (
        @(posedge EXMEMregWrite or posedge MEMWBregWrite or posedge rst)
        disable iff (rst)
        (EXMEMregWrite && (EXMEMregisterRd != 5'd0) && (EXMEMregisterRd == rt) &&
         MEMWBregWrite && (MEMWBregisterRd != 5'd0) && (MEMWBregisterRd == rt)) |-> (forwardB == 2'b10)
    );
    // forwardB only takes 00, 01, or 10 when not in reset.
    check_forwardB_code_space: assert property (
        @(posedge EXMEMregWrite or posedge MEMWBregWrite or posedge rst)
        disable iff (rst)
        1'b1 |-> (forwardB inside {2'b00, 2'b01, 2'b10})
    );

endmodule

module barrel_shifter_sva (
    // DUT ports
    input logic [15:0] data_in,
    input logic [3:0]  shift_amount,
    input logic        shift_direction,
    input logic [15:0] data_out,
    // Sampling clock for SVA (DUT has no clock/reset)
    input logic        CLK
);
    // Clocks: none in RTL (assertions sample on CLK). Reset: none. Logic: purely combinational.

    // data_out equals left or right shift of data_in per shift_direction
    check_functional_equation: assert property (
        @(posedge CLK) data_out == (shift_direction ? (data_in >> shift_amount) : (data_in << shift_amount))
    );

    // Zero shift is a passthrough
    check_zero_shift_passthrough: assert property (
        @(posedge CLK) (shift_amount == 4'd0) |-> (data_out == data_in)
    );

    // Left shift by 1 produces {data_in[14:0], 1'b0}
    check_left_shift_by_1: assert property (
        @(posedge CLK) (shift_direction == 1'b0 && shift_amount == 4'd1) |-> (data_out == {data_in[14:0], 1'b0})
    );

    // Right shift by 1 produces {1'b0, data_in[15:1]}
    check_right_shift_by_1: assert property (
        @(posedge CLK) (shift_direction == 1'b1 && shift_amount == 4'd1) |-> (data_out == {1'b0, data_in[15:1]})
    );

    // Left shift by 15 moves bit 0 to MSB and zeros others
    check_left_shift_by_15: assert property (
        @(posedge CLK) (shift_direction == 1'b0 && shift_amount == 4'd15) |-> (data_out == {data_in[0], 15'b0})
    );

    // Right shift by 15 moves MSB to LSB and zeros others
    check_right_shift_by_15: assert property (
        @(posedge CLK) (shift_direction == 1'b1 && shift_amount == 4'd15) |-> (data_out == {15'b0, data_in[15]})
    );

    // Shifting zero always yields zero
    check_zero_input_results_zero: assert property (
        @(posedge CLK) (data_in == 16'b0) |-> (data_out == 16'b0)
    );

endmodule

rtl:
module processor_system_reset(
  input slowest_sync_clk,
  input ext_reset_in,
  input aux_reset_in,
  input mb_debug_sys_rst,
  input dcm_locked,
  output reg mb_reset,
  output reg [0:0]bus_struct_reset,
  output reg [0:0]peripheral_reset,
  output reg [0:0]interconnect_aresetn,
  output reg [0:0]peripheral_aresetn
);

  always @(posedge slowest_sync_clk) begin
    if(ext_reset_in || aux_reset_in || mb_debug_sys_rst || !dcm_locked) begin
      mb_reset <= 1'b1;
      bus_struct_reset <= 1'b1;
      peripheral_reset <= 1'b1;
      interconnect_aresetn <= 1'b1;
      peripheral_aresetn <= 1'b1;
    end else begin
      mb_reset <= 1'b0;
      bus_struct_reset <= 1'b0;
      peripheral_reset <= 1'b0;
      interconnect_aresetn <= 1'b0;
      peripheral_aresetn <= 1'b0;
    end
  end
endmodule

sva:
module processor_system_reset_sva (
  input logic slowest_sync_clk,
  input logic ext_reset_in,
  input logic aux_reset_in,
  input logic mb_debug_sys_rst,
  input logic dcm_locked,
  input logic mb_reset,
  input logic [0:0] bus_struct_reset,
  input logic [0:0] peripheral_reset,
  input logic [0:0] interconnect_aresetn,
  input logic [0:0] peripheral_aresetn
);

  ///// Functional mapping to reset request (sampled one cycle earlier) /////
  // All reset outputs equal the OR of {ext_reset_in, aux_reset_in, mb_debug_sys_rst, !dcm_locked} from the previous cycle.
  check_outputs_follow_reset_req: assert property (
    @(posedge slowest_sync_clk) disable iff ($initstate)
      {mb_reset, bus_struct_reset[0], peripheral_reset[0], interconnect_aresetn[0], peripheral_aresetn[0]}
        == {5{ $past( ext_reset_in || aux_reset_in || mb_debug_sys_rst || !dcm_locked ) }}
  );

  ///// Explicit 1/0 drive under reset/non-reset conditions /////
  // If any reset cause was asserted or dcm_locked was LOW in the previous cycle, all outputs must be 1.
  check_outputs_one_when_reset_req: assert property (
    @(posedge slowest_sync_clk) disable iff ($initstate)
      $past( ext_reset_in || aux_reset_in || mb_debug_sys_rst || !dcm_locked )
        |-> (mb_reset && bus_struct_reset[0] && peripheral_reset[0] && interconnect_aresetn[0] && peripheral_aresetn[0])
  );

  // If no reset cause was asserted and dcm_locked was HIGH in the previous cycle, all outputs must be 0.
  check_outputs_zero_when_no_reset_req: assert property (
    @(posedge slowest_sync_clk) disable iff ($initstate)
      !$past( ext_reset_in || aux_reset_in || mb_debug_sys_rst || !dcm_locked )
        |-> (!mb_reset && !bus_struct_reset[0] && !peripheral_reset[0] && !interconnect_aresetn[0] && !peripheral_aresetn[0])
  );

  ///// Consistency across reset outputs /////
  // All reset outputs are identical each cycle.
  check_all_outputs_equal: assert property (
    @(posedge slowest_sync_clk) disable iff ($initstate)
      (mb_reset == bus_struct_reset[0]) &&
      (mb_reset == peripheral_reset[0]) &&
      (mb_reset == interconnect_aresetn[0]) &&
      (mb_reset == peripheral_aresetn[0])
  );

  ///// Edge relationships among outputs /////
  // All reset outputs rise in the same cycle.
  check_outputs_rise_together: assert property (
    @(posedge slowest_sync_clk) disable iff ($initstate)
      $rose(mb_reset) |-> $rose(bus_struct_reset[0]) && $rose(peripheral_reset[0]) && $rose(interconnect_aresetn[0]) && $rose(peripheral_aresetn[0])
  );

  // All reset outputs fall in the same cycle.
  check_outputs_fall_together: assert property (
    @(posedge slowest_sync_clk) disable iff ($initstate)
      $fell(mb_reset) |-> $fell(bus_struct_reset[0]) && $fell(peripheral_reset[0]) && $fell(interconnect_aresetn[0]) && $fell(peripheral_aresetn[0])
  );

  ///// Output edges follow reset request edges with one-cycle latency /////
  // A rising reset request causes all reset outputs to rise on the next cycle.
  check_reset_req_rise_causes_output_rise: assert property (
    @(posedge slowest_sync_clk) disable iff ($initstate)
      $rose( ext_reset_in || aux_reset_in || mb_debug_sys_rst || !dcm_locked )
        |=> $rose(mb_reset) && $rose(bus_struct_reset[0]) && $rose(peripheral_reset[0]) && $rose(interconnect_aresetn[0]) && $rose(peripheral_aresetn[0])
  );

  // A falling reset request causes all reset outputs to fall on the next cycle.
  check_reset_req_fall_causes_output_fall: assert property (
    @(posedge slowest_sync_clk) disable iff ($initstate)
      $fell( ext_reset_in || aux_reset_in || mb_debug_sys_rst || !dcm_locked )
        |=> $fell(mb_reset) && $fell(bus_struct_reset[0]) && $fell(peripheral_reset[0]) && $fell(interconnect_aresetn[0]) && $fell(peripheral_aresetn[0])
  );

  ///// Temporal stability /////
  // If all inputs are stable over a cycle, all outputs remain stable in the following cycle.
  check_stable_inputs_imply_stable_outputs: assert property (
    @(posedge slowest_sync_clk) disable iff ($initstate)
      $stable(ext_reset_in) && $stable(aux_reset_in) && $stable(mb_debug_sys_rst) && $stable(dcm_locked)
        |=> $stable({mb_reset, bus_struct_reset[0], peripheral_reset[0], interconnect_aresetn[0], peripheral_aresetn[0]})
  );

endmodule

rtl:
module arithmetic_op(output reg [3:0] Y, input [3:0] A, input [3:0] B, input S);

    always @(*) begin
        Y = (S == 0) ? (A + B) : (A - B);
    end

endmodule

sva:
module arithmetic_op_sva (
    input logic clk,          // Clock for sampling assertions
    input logic [3:0] Y,      // DUT output
    input logic [3:0] A,      // DUT input
    input logic [3:0] B,      // DUT input
    input logic S             // DUT select
);

    // When S==0, Y equals A + B (4-bit wraparound).
    check_add_result_when_S0: assert property (
        @(posedge clk) (S == 1'b0) |-> (Y == (A + B))
    );

    // When S==1, Y equals A - B (4-bit wraparound).
    check_sub_result_when_S1: assert property (
        @(posedge clk) (S == 1'b1) |-> (Y == (A - B))
    );

    // If inputs A, B, S are stable, Y must remain stable.
    check_output_stable_when_inputs_stable: assert property (
        @(posedge clk) ($stable(A) && $stable(B) && $stable(S)) |-> $stable(Y)
    );

    // If B is zero, Y must equal A regardless of S.
    check_passthrough_when_B_zero: assert property (
        @(posedge clk) (B == 4'h0) |-> (Y == A)
    );

    // For subtraction with equal operands, result is zero.
    check_zero_when_A_eq_B_and_sub: assert property (
        @(posedge clk) (S == 1'b1 && A == B) |-> (Y == 4'h0)
    );

    // Inverse identity for addition: (A+B)-B == A.
    check_add_inverse_identity: assert property (
        @(posedge clk) (S == 1'b0) |-> ((Y - B) == A)
    );

    // Inverse identity for subtraction: (A-B)+B == A.
    check_sub_inverse_identity: assert property (
        @(posedge clk) (S == 1'b1) |-> ((Y + B) == A)
    );

    // On S rising edge with stable A,B, Y reflects subtraction.
    check_y_on_rose_S_with_inputs_stable: assert property (
        @(posedge clk) ($rose(S) && $stable(A) && $stable(B)) |-> (Y == (A - B))
    );

    // On S falling edge with stable A,B, Y reflects addition.
    check_y_on_fell_S_with_inputs_stable: assert property (
        @(posedge clk) ($fell(S) && $stable(A) && $stable(B)) |-> (Y == (A + B))
    );

    // When adding equal operands, result LSB must be 0 (2*A mod 16 is even).
    check_even_result_when_S0_and_A_eq_B: assert property (
        @(posedge clk) (S == 1'b0 && A == B) |-> (Y[0] == 1'b0)
    );

endmodule

rtl:
module BitLpf #(
    parameter FILT_BITS = 8
)
(
    input  clk,    input  rst,    input  en,     input  dataIn, output dataOut );

reg signed [FILT_BITS-1:0] filter;

assign dataOut = filter[FILT_BITS-1];

always @(posedge clk) begin
    if (rst) begin
        filter <= 'd0;
    end
    else if (en) begin
        filter <= filter + dataIn - dataOut;
    end
end

endmodule

sva:
module BitLpf_sva #(
    parameter int FILT_BITS = 8
) (
    input  logic clk,
    input  logic rst,      // active-high synchronous reset
    input  logic en,
    input  logic dataIn,
    input  logic dataOut,
    input  logic signed [FILT_BITS-1:0] filter  // internal reg from DUT
);

    // dataOut is always the MSB of filter
    check_dataout_is_msb: assert property (
        @(posedge clk) disable iff (rst) dataOut == filter[FILT_BITS-1]
    );

    // On the first cycle after reset was asserted, filter is zero
    check_filter_zero_after_reset: assert property (
        @(posedge clk) disable iff (rst) $past(rst) |-> (filter == {FILT_BITS{1'b0}})
    );

    // On the first cycle after reset was asserted, dataOut is zero
    check_out_zero_after_reset: assert property (
        @(posedge clk) disable iff (rst) $past(rst) |-> (dataOut == 1'b0)
    );

    // When en was LOW and not in reset, filter holds its value
    check_filter_hold_when_en_low: assert property (
        @(posedge clk) disable iff (rst) $past(!rst && !en) |-> (filter == $past(filter))
    );

    // When en was HIGH but dataIn==dataOut, filter holds (delta=0)
    check_filter_hold_when_no_delta: assert property (
        @(posedge clk) disable iff (rst) $past(!rst && en && ($past(dataIn) == $past(dataOut))) |-> (filter == $past(filter))
    );

    // When en was HIGH and not in reset, filter updates by (dataIn - dataOut)
    check_filter_update_when_en_high: assert property (
        @(posedge clk) disable iff (rst)
            $past(!rst && en) |-> (
                filter == ($signed($past(filter))
                           + $signed({{(FILT_BITS-1){1'b0}}, $past(dataIn)})
                           - $signed({{(FILT_BITS-1){1'b0}}, $past(dataOut)}))
            )
    );

    // When en was LOW and not in reset, dataOut holds (filter holds)
    check_out_hold_when_en_low: assert property (
        @(posedge clk) disable iff (rst) $past(!rst && !en) |-> (dataOut == $past(dataOut))
    );

    // When en was HIGH but dataIn==dataOut, dataOut holds
    check_out_hold_when_no_delta: assert property (
        @(posedge clk) disable iff (rst) $past(!rst && en && ($past(dataIn) == $past(dataOut))) |-> (dataOut == $past(dataOut))
    );

    // A change on dataOut requires prior en HIGH and dataIn!=dataOut
    check_out_change_requires_update: assert property (
        @(posedge clk) disable iff (rst) (dataOut != $past(dataOut)) |-> ($past(!rst && en) && ($past(dataIn) != $past(dataOut)))
    );

    // A change on filter requires prior en HIGH (outside reset)
    check_filter_change_requires_en: assert property (
        @(posedge clk) disable iff (rst) (filter != $past(filter)) |-> $past(en)
    );

endmodule

rtl:
module seven_to_one (
    A1  ,
    A2  ,
    B1  ,
    B2  ,
    C1  ,
    C2  ,
    C3  ,
    X
);

    input  A1  ;
    input  A2  ;
    input  B1  ;
    input  B2  ;
    input  C1  ;
    input  C2  ;
    input  C3  ;
    output X   ;

    assign X = (A1 & A2 & B1 & B2) | ~(C1 | C2 | C3);

endmodule

sva:
module seven_to_one_sva (
    input  logic CLK,
    input  logic RESETn,
    input  logic A1,
    input  logic A2,
    input  logic B1,
    input  logic B2,
    input  logic C1,
    input  logic C2,
    input  logic C3,
    input  logic X
);
    // X equals (A1&A2&B1&B2) OR NOT(C1|C2|C3).
    check_function_equivalence: assert property (
        @(posedge CLK) disable iff (!RESETn)
            X == ( (A1 & A2 & B1 & B2) | ~(C1 | C2 | C3) )
    );

    // If all A/B inputs are 1, X must be 1.
    check_X_one_when_all_A_B_high: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (A1 & A2 & B1 & B2) |-> (X == 1'b1)
    );

    // If all C inputs are 0, X must be 1.
    check_X_one_when_all_C_low: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (~(C1 | C2 | C3) == 1'b1) |-> (X == 1'b1)
    );

    // If any C is 1 and not all A/B are 1, X must be 0.
    check_X_zero_when_any_C_high_and_not_all_A_B: assert property (
        @(posedge CLK) disable iff (!RESETn)
            ((C1 | C2 | C3) && ~((A1 & A2 & B1 & B2))) |-> (X == 1'b0)
    );

    // If X is 0, then at least one C is 1 and not all A/B are 1.
    check_X_zero_implies_inputs: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (X == 1'b0) |-> (((C1 | C2 | C3) == 1'b1) && ((A1 & A2 & B1 & B2) == 1'b0))
    );

    // If X is 1, then either all A/B are 1 or all C are 0.
    check_X_one_implies_inputs: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (X == 1'b1) |-> (((A1 & A2 & B1 & B2) == 1'b1) || (~(C1 | C2 | C3) == 1'b1))
    );

    // If (A1&A2&B1&B2) rises and C inputs are stable, X must be 1.
    check_X_one_on_A_group_rise_with_C_stable: assert property (
        @(posedge CLK) disable iff (!RESETn)
            ($rose(A1 & A2 & B1 & B2) && $stable(C1) && $stable(C2) && $stable(C3)) |-> (X == 1'b1)
    );

    // If ~(C1|C2|C3) rises (all C become 0), X must be 1.
    check_X_one_on_all_C_low_rise: assert property (
        @(posedge CLK) disable iff (!RESETn)
            $rose(~(C1 | C2 | C3)) |-> (X == 1'b1)
    );

    // If (C1|C2|C3) rises while all A/B remain not all 1, X must be 0.
    check_X_zero_on_any_C_rise_with_A_group_stable_zero: assert property (
        @(posedge CLK) disable iff (!RESETn)
            ($rose(C1 | C2 | C3) && $stable(A1) && $stable(A2) && $stable(B1) && $stable(B2) && ((A1 & A2 & B1 & B2) == 1'b0)) |-> (X == 1'b0)
    );

    // If all inputs are stable, X must be stable.
    check_output_stable_when_inputs_stable: assert property (
        @(posedge CLK) disable iff (!RESETn)
            ($stable(A1) && $stable(A2) && $stable(B1) && $stable(B2) && $stable(C1) && $stable(C2) && $stable(C3)) |-> $stable(X)
    );
endmodule

rtl:
module ripple_carry_adder (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] S,
    output Cout
);

    wire [3:0] C; // Internal carry signals
    wire [3:0] X; // Internal sum signals

    // Full adder module instance
    full_adder FA0(.A(A[0]), .B(B[0]), .Cin(Cin), .S(X[0]), .C(C[0]));
    full_adder FA1(.A(A[1]), .B(B[1]), .Cin(C[0]), .S(X[1]), .C(C[1]));
    full_adder FA2(.A(A[2]), .B(B[2]), .Cin(C[1]), .S(X[2]), .C(C[2]));
    full_adder FA3(.A(A[3]), .B(B[3]), .Cin(C[2]), .S(X[3]), .C(C[3]));

    // Output signals
    assign S = X;
    assign Cout = C[3];

endmodule

module full_adder (
    input A,
    input B,
    input Cin,
    output S,
    output C
);

    assign S = A ^ B ^ Cin;
    assign C = (A & B) | (A & Cin) | (B & Cin);

endmodule

sva:
module ripple_carry_adder_sva (
    input logic CLK,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic Cin,
    input logic [3:0] S,
    input logic Cout
);
    // Local carry expressions derived from the ripple chain
    let c0 = (A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin);
    let c1 = (A[1] & B[1]) | (A[1] & c0)  | (B[1] & c0);
    let c2 = (A[2] & B[2]) | (A[2] & c1)  | (B[2] & c1);
    let c3 = (A[3] & B[3]) | (A[3] & c2)  | (B[3] & c2);
    let carry_in_vec = {c2, c1, c0, Cin};

    // Overall 5-bit sum equals A + B + Cin.
    adder_sum_correct: assert property (
        @(posedge CLK) {Cout, S} == ({1'b0, A} + {1'b0, B} + Cin)
    );

    // LSB sum is XOR of A[0], B[0], and Cin.
    sum_bit0_xor: assert property (
        @(posedge CLK) S[0] == (A[0] ^ B[0] ^ Cin)
    );

    // Bit1 sum uses c0 as carry in.
    sum_bit1_xor_with_c0: assert property (
        @(posedge CLK) S[1] == (A[1] ^ B[1] ^ c0)
    );

    // Bit2 sum uses c1 as carry in.
    sum_bit2_xor_with_c1: assert property (
        @(posedge CLK) S[2] == (A[2] ^ B[2] ^ c1)
    );

    // Bit3 sum uses c2 as carry in.
    sum_bit3_xor_with_c2: assert property (
        @(posedge CLK) S[3] == (A[3] ^ B[3] ^ c2)
    );

    // Cout equals the final carry c3.
    cout_equals_c3: assert property (
        @(posedge CLK) Cout == c3
    );

    // Vector sum equals A ^ B ^ carry_in for each bit.
    sum_vector_xor_correct: assert property (
        @(posedge CLK) S == (A ^ B ^ carry_in_vec)
    );

    // If B==0 and Cin==0, output equals A and no carry.
    identity_when_B_zero_and_Cin_zero: assert property (
        @(posedge CLK) (B == 4'b0000 && Cin == 1'b0) |-> (S == A && Cout == 1'b0)
    );

    // If A==0 and Cin==0, output equals B and no carry.
    identity_when_A_zero_and_Cin_zero: assert property (
        @(posedge CLK) (A == 4'b0000 && Cin == 1'b0) |-> (S == B && Cout == 1'b0)
    );

    // If A==0 and B==0, S reflects Cin in LSB and Cout==0.
    both_operands_zero_behavior: assert property (
        @(posedge CLK) (A == 4'b0000 && B == 4'b0000) |-> (S == {3'b000, Cin} && Cout == 1'b0)
    );
endmodule

rtl:
module adder_4bit(
  input [3:0] A,
  input [3:0] B,
  input CIN,
  output [3:0] S,
  output COUT
);

  assign {COUT, S} = A + B + CIN;

endmodule

sva:
module adder_4bit_sva (
    input logic CLK,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic CIN,
    input logic [3:0] S,
    input logic COUT
);
    // Sum output must equal the RTL expression A + B + CIN (concatenated with COUT).
    check_sum_matches_rtl: assert property (
        @(posedge CLK) {COUT, S} == (A + B + CIN)
    );

    // S must equal the low 4 bits of A + B + CIN per RTL.
    check_s_lower_bits: assert property (
        @(posedge CLK) S == (A + B + CIN)
    );

    // If inputs are stable between samples, outputs must also be stable.
    check_stable_inputs_imply_stable_outputs: assert property (
        @(posedge CLK) ($stable(A) && $stable(B) && $stable(CIN)) |-> $stable({COUT, S})
    );

    // Swapping A and B between cycles with CIN unchanged leaves outputs unchanged (commutativity).
    check_commutativity_across_cycles: assert property (
        @(posedge CLK) (A == $past(B)) && (B == $past(A)) && (CIN == $past(CIN)) |-> ({COUT, S} == $past({COUT, S}))
    );

    // If B and CIN are zero, output equals A with no carry (per RTL expression).
    check_identity_with_B_zero_CIN_zero: assert property (
        @(posedge CLK) (B == 4'b0000) && (CIN == 1'b0) |-> ({COUT, S} == {1'b0, A})
    );

    // If A and CIN are zero, output equals B with no carry (per RTL expression).
    check_identity_with_A_zero_CIN_zero: assert property (
        @(posedge CLK) (A == 4'b0000) && (CIN == 1'b0) |-> ({COUT, S} == {1'b0, B})
    );

    // If A and B are zero, S equals CIN in bit[0] and COUT is zero (per RTL expression).
    check_zero_plus_zero: assert property (
        @(posedge CLK) (A == 4'b0000) && (B == 4'b0000) |-> (S == {3'b000, CIN}) && (COUT == 1'b0)
    );
endmodule

rtl:
module mux4to1 (
    input A, B, C, D,
    input S0, S1,
    output Y
);

    wire notS0, notS1, and1, and2, and3, and4;

    not (notS0, S0);
    not (notS1, S1);
    and (and1, A, notS1, notS0);
    and (and2, B, notS1, S0);
    and (and3, C, S1, notS0);
    and (and4, D, S1, S0);
    or (Y, and1, and2, and3, and4);

endmodule

sva:
module mux4to1_sva (
    input logic CLK,
    input logic RESETn,
    input logic A, B, C, D,
    input logic S0, S1,
    input logic Y
);
    // Y implements the 4:1 mux boolean function of selects and data.
    check_mux_function: assert property (
        @(posedge CLK) disable iff (!RESETn)
        Y == ((~S1 & ~S0 & A) | (~S1 & S0 & B) | (S1 & ~S0 & C) | (S1 & S0 & D))
    );

    // When S1S0=00, Y equals A.
    check_sel00_routes_A: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (S1==1'b0 && S0==1'b0) |-> (Y == A)
    );

    // When S1S0=01, Y equals B.
    check_sel01_routes_B: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (S1==1'b0 && S0==1'b1) |-> (Y == B)
    );

    // When S1S0=10, Y equals C.
    check_sel10_routes_C: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (S1==1'b1 && S0==1'b0) |-> (Y == C)
    );

    // When S1S0=11, Y equals D.
    check_sel11_routes_D: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (S1==1'b1 && S0==1'b1) |-> (Y == D)
    );

    // With S1S0 held at 00 and other inputs stable, Y changes iff A changes.
    track_A_when_sel00: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (S1==1'b0 && S0==1'b0 && $stable(S1) && $stable(S0) && $stable(B) && $stable(C) && $stable(D))
        |-> ($changed(Y) == $changed(A))
    );

    // With S1S0 held at 01 and other inputs stable, Y changes iff B changes.
    track_B_when_sel01: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (S1==1'b0 && S0==1'b1 && $stable(S1) && $stable(S0) && $stable(A) && $stable(C) && $stable(D))
        |-> ($changed(Y) == $changed(B))
    );

    // With S1S0 held at 10 and other inputs stable, Y changes iff C changes.
    track_C_when_sel10: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (S1==1'b1 && S0==1'b0 && $stable(S1) && $stable(S0) && $stable(A) && $stable(B) && $stable(D))
        |-> ($changed(Y) == $changed(C))
    );

    // With S1S0 held at 11 and other inputs stable, Y changes iff D changes.
    track_D_when_sel11: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (S1==1'b1 && S0==1'b1 && $stable(S1) && $stable(S0) && $stable(A) && $stable(B) && $stable(C))
        |-> ($changed(Y) == $changed(D))
    );

    // If all inputs and selects are stable, Y must remain stable.
    stable_inputs_hold_Y: assert property (
        @(posedge CLK) disable iff (!RESETn)
        $stable({A,B,C,D,S0,S1}) |-> $stable(Y)
    );
endmodule

module priority_encoder_sva (
    input logic [7:0] D,
    input logic [2:0] EN
);
    // EN[2] mirrors D[7] (highest priority)
    check_en2_mirrors_d7: assert property (
        @(posedge D[0]) disable iff (1'b0) (EN[2] == D[7])
    );
    // EN[1] is set iff D[6] is 1 and D[7] is 0
    check_en1_priority: assert property (
        @(posedge D[0]) disable iff (1'b0) (EN[1] == (!D[7] && D[6]))
    );
    // EN[0] is set iff D[5] is 1 and D[7:6] are 0
    check_en0_priority: assert property (
        @(posedge D[0]) disable iff (1'b0) (EN[0] == (!D[7] && !D[6] && D[5]))
    );
    // EN is one-hot or zero
    check_en_onehot0: assert property (
        @(posedge D[0]) disable iff (1'b0) $onehot0(EN)
    );
    // If D7 is 1, EN must be 3'b100
    check_d7_implies_en100: assert property (
        @(posedge D[0]) disable iff (1'b0) D[7] |-> (EN == 3'b100)
    );
    // If D6 is 1 and D7 is 0, EN must be 3'b010
    check_d6_implies_en010: assert property (
        @(posedge D[0]) disable iff (1'b0) (!D[7] && D[6]) |-> (EN == 3'b010)
    );
    // If only D5 among top bits is 1, EN must be 3'b001
    check_d5_implies_en001: assert property (
        @(posedge D[0]) disable iff (1'b0) (!D[7] && !D[6] && D[5]) |-> (EN == 3'b001)
    );
    // If D[7:5]==3'b000, EN must be 3'b000
    check_none_implies_en000: assert property (
        @(posedge D[0]) disable iff (1'b0) (!D[7] && !D[6] && !D[5]) |-> (EN == 3'b000)
    );
    // EN depends only on D[7:5] (stable upper bits imply stable EN)
    check_en_independent_of_low5: assert property (
        @(posedge D[0]) disable iff (1'b0) $stable(D[7:5]) |-> $stable(EN)
    );
endmodule

rtl:
module two_bit_sat_counter 
    (
        input   wire[1:0] count_i,
        input   wire      op,
        output  reg[1:0]  count
    );

    always @ (*)
    begin
        case (count_i)
            2'b00:  count = (op) ? count_i          : count_i + 2'b1;
            2'b01:  count = (op) ? count_i - 2'b1   : count_i + 2'b1;
            2'b10:  count = (op) ? count_i + 2'b1   : count_i - 2'b1;
            2'b11:  count = (op) ? count_i          : count_i - 2'b1;
            default count = 2'b0;
        endcase
    end

endmodule

sva:
module two_bit_sat_counter_sva (
    input logic CLK,
    input logic [1:0] count_i,
    input logic       op,
    input logic [1:0] count
);

    // 00 with op=0 increments to 01.
    check_00_when_op0_increments: assert property (
        @(posedge CLK) (count_i == 2'b00) && (op == 1'b0) |-> (count == 2'b01)
    );

    // 00 with op=1 saturates (holds at 00).
    check_00_when_op1_saturates: assert property (
        @(posedge CLK) (count_i == 2'b00) && (op == 1'b1) |-> (count == 2'b00)
    );

    // 01 with op=0 increments to 10.
    check_01_when_op0_increments: assert property (
        @(posedge CLK) (count_i == 2'b01) && (op == 1'b0) |-> (count == 2'b10)
    );

    // 01 with op=1 decrements to 00.
    check_01_when_op1_decrements: assert property (
        @(posedge CLK) (count_i == 2'b01) && (op == 1'b1) |-> (count == 2'b00)
    );

    // 10 with op=0 decrements to 01.
    check_10_when_op0_decrements: assert property (
        @(posedge CLK) (count_i == 2'b10) && (op == 1'b0) |-> (count == 2'b01)
    );

    // 10 with op=1 increments to 11.
    check_10_when_op1_increments: assert property (
        @(posedge CLK) (count_i == 2'b10) && (op == 1'b1) |-> (count == 2'b11)
    );

    // 11 with op=0 decrements to 10.
    check_11_when_op0_decrements: assert property (
        @(posedge CLK) (count_i == 2'b11) && (op == 1'b0) |-> (count == 2'b10)
    );

    // 11 with op=1 saturates (holds at 11).
    check_11_when_op1_saturates: assert property (
        @(posedge CLK) (count_i == 2'b11) && (op == 1'b1) |-> (count == 2'b11)
    );

    // For mid values (01,10) output always differs from input.
    check_mid_values_always_change: assert property (
        @(posedge CLK) (count_i inside {2'b01,2'b10}) |-> (count != count_i)
    );

    // Output is either equal or +/-1 from input (no multi-step or wrap beyond 1).
    check_output_step_or_hold_valid: assert property (
        @(posedge CLK) 1'b1 |-> ( (count == count_i) || (count == (count_i + 2'b01)) || (count == (count_i - 2'b01)) )
    );

    // Holding output equals input only at bounds (00 or 11) with op=1.
    check_hold_only_at_bounds_with_op1: assert property (
        @(posedge CLK) (count == count_i) |-> ((count_i inside {2'b00,2'b11}) && (op == 1'b1))
    );

endmodule

rtl:
module frequency_divider (
  input clk,
  input reset,
  input data,
  output reg pulse
);

  parameter PRESET_VALUE = 100; // Change this value to adjust the output frequency

  reg [PRESET_VALUE-1:0] shift_reg;
  reg [7:0] counter = 8'd0;

  always @(posedge clk) begin
    if (reset) begin
      shift_reg <= 0;
      counter <= 0;
      pulse <= 0;
    end else begin
      shift_reg <= {data, shift_reg[PRESET_VALUE-2:0]};
      counter <= counter + 1;
      if (counter == PRESET_VALUE-1) begin
        counter <= 0;
        pulse <= ~pulse;
      end
    end
  end

endmodule

sva:
module frequency_divider_sva #(
    parameter int PRESET_VALUE = 100
) (
    input  logic clk,
    input  logic reset,
    input  logic data,
    input  logic pulse,
    input  logic [PRESET_VALUE-1:0] shift_reg,
    input  logic [7:0] counter
);
    ///// Reset behavior /////
    // On synchronous reset, all state clears to 0.
    reset_clears_state: assert property (
        @(posedge clk) reset |-> (shift_reg == '0) && (counter == 8'd0) && (pulse == 1'b0)
    );

    ///// Shift register behavior /////
    // shift_reg shifts in 'data' at MSB each cycle when not in reset.
    shift_reg_shifts_in_data: assert property (
        @(posedge clk) disable iff (reset) shift_reg == {data, $past(shift_reg)[PRESET_VALUE-2:0]}
    );

    ///// Counter behavior /////
    // Counter increments by 1 when previous value is not PRESET_VALUE-1.
    counter_increments_when_not_terminal: assert property (
        @(posedge clk) disable iff (reset) ($past(counter) != PRESET_VALUE-1) |-> (counter == $past(counter) + 8'd1)
    );

    // Counter resets to 0 when previous value is PRESET_VALUE-1.
    counter_resets_at_terminal: assert property (
        @(posedge clk) disable iff (reset) ($past(counter) == PRESET_VALUE-1) |-> (counter == 8'd0)
    );

    // Counter never exceeds PRESET_VALUE-1 (for PRESET_VALUE <= 256 this is exact).
    counter_bounded_by_preset: assert property (
        @(posedge clk) disable iff (reset) counter <= PRESET_VALUE-1
    );

    ///// Pulse generation behavior /////
    // Pulse toggles exactly when previous counter equals PRESET_VALUE-1.
    pulse_toggles_at_terminal_count: assert property (
        @(posedge clk) disable iff (reset) ($past(counter) == PRESET_VALUE-1) |-> (pulse == ~$past(pulse))
    );

    // Pulse holds value when previous counter is not PRESET_VALUE-1.
    pulse_holds_when_not_terminal: assert property (
        @(posedge clk) disable iff (reset) ($past(counter) != PRESET_VALUE-1) |-> (pulse == $past(pulse))
    );

    // Any pulse change implies counter is 0 on this cycle.
    pulse_change_implies_counter_zero: assert property (
        @(posedge clk) disable iff (reset) (pulse != $past(pulse)) |-> (counter == 8'd0)
    );

    // Successive pulse toggles are PRESET_VALUE cycles apart (absent reset).
    pulse_period_is_PRESET_VALUE: assert property (
        @(posedge clk) disable iff (reset) (pulse != $past(pulse)) |-> ##PRESET_VALUE (pulse != $past(pulse))
    );

    // After reset deassertion, the next pulse toggle occurs in exactly PRESET_VALUE cycles.
    first_toggle_after_reset: assert property (
        @(posedge clk) disable iff (reset) $fell(reset) |-> ##PRESET_VALUE (pulse != $past(pulse))
    );
endmodule

rtl:
module mux_2to1_pipeline(
    input a,
    input b,
    input sel_b1,
    output reg out_always,
    input clk
);

// Pipeline register
reg pipeline_reg;

// Register pipeline stage
always @(posedge clk) begin
    pipeline_reg <= sel_b1;
end

// Output logic
always @(*) begin
    if (pipeline_reg) begin
        out_always = b;
    end else begin
        out_always = a;
    end
end

endmodule

sva:
module mux_2to1_pipeline_sva (
    input logic a,
    input logic b,
    input logic sel_b1,
    input logic out_always,
    input logic clk,
    input logic pipeline_reg
);
    // pipeline_reg captures sel_b1 with one-cycle latency.
    pipe_tracks_sel_b1: assert property (
        @(posedge clk) disable iff ($initstate) pipeline_reg == $past(sel_b1)
    );

    // A rising pipeline_reg means sel_b1 was 1 in the previous cycle.
    pipe_rise_matches_prev_sel1: assert property (
        @(posedge clk) disable iff ($initstate) $rose(pipeline_reg) |-> $past(sel_b1)
    );

    // A falling pipeline_reg means sel_b1 was 0 in the previous cycle.
    pipe_fall_matches_prev_sel0: assert property (
        @(posedge clk) disable iff ($initstate) $fell(pipeline_reg) |-> !$past(sel_b1)
    );

    // out_always equals the mux of a/b selected by pipeline_reg.
    out_matches_selected_input: assert property (
        @(posedge clk) disable iff ($initstate) out_always == (pipeline_reg ? b : a)
    );

    // When selecting a and both a and select are stable, out_always is stable.
    out_stable_when_a_selected_and_stable: assert property (
        @(posedge clk) disable iff ($initstate)
            (pipeline_reg == 1'b0 && $stable(a) && $stable(pipeline_reg)) |-> $stable(out_always)
    );

    // When selecting b and both b and select are stable, out_always is stable.
    out_stable_when_b_selected_and_stable: assert property (
        @(posedge clk) disable iff ($initstate)
            (pipeline_reg == 1'b1 && $stable(b) && $stable(pipeline_reg)) |-> $stable(out_always)
    );

    // An out_always change must be caused by a change in the select or the selected input.
    out_change_has_cause: assert property (
        @(posedge clk) disable iff ($initstate)
            $changed(out_always) |-> ($changed(pipeline_reg) || (pipeline_reg ? $changed(b) : $changed(a)))
    );
endmodule

rtl:
module gated_d_ff_en_W32_0_0 ( CLK, EN, TE, D, Q );
  input CLK, EN, TE;
  input [31:0] D;
  output [31:0] Q;

  wire gated_clk;

  TLATCH latch ( .E(EN), .SE(TE), .CK(CLK), .ECK(gated_clk) );

  reg [31:0] Q_reg;

  always @(posedge gated_clk) begin
    if (EN) begin
      Q_reg <= D;
    end
  end

  assign Q = Q_reg;


endmodule

module TLATCH ( E, SE, CK, ECK );
  parameter INIT = 1'b0;

  input  E, SE;
  input  CK;
  output ECK;

  reg ECK_int;

  assign ECK = ECK_int;

  initial ECK_int = INIT;

  always @( posedge CK ) begin
    if ( SE == 1'b1 ) ECK_int <=INIT;
    else if ( E == 1'b1 ) ECK_int <= 1'b1;
  end

endmodule

sva:
module gated_d_ff_en_W32_0_0_sva (
    input logic CLK,
    input logic EN,
    input logic TE,
    input logic [31:0] D,
    input logic [31:0] Q,
    input logic gated_clk
);
    // TE=1 prevents Q updates at CLK edges.
    te_freezes_output: assert property (
        @(posedge CLK) TE |-> $stable(Q)
    );

    // EN=0 prevents Q updates at CLK edges.
    en_low_holds_output: assert property (
        @(posedge CLK) (EN == 1'b0) |-> $stable(Q)
    );

    // Rising gated_clk implies prior cycle EN=1 and TE=0.
    gated_rise_requires_en_and_not_te: assert property (
        @(posedge CLK) $rose(gated_clk) |-> ($past(EN) && !$past(TE))
    );

    // Falling gated_clk implies prior cycle TE=1.
    gated_fall_requires_te: assert property (
        @(posedge CLK) $fell(gated_clk) |-> $past(TE)
    );

    // EN=1 and TE=0 drives gated_clk HIGH in the next cycle.
    en_sets_gated_high_next: assert property (
        @(posedge CLK) (EN && !TE) |-> ##1 (gated_clk == 1'b1)
    );

    // TE=1 drives gated_clk LOW in the next cycle.
    te_sets_gated_low_next: assert property (
        @(posedge CLK) TE |-> ##1 (gated_clk == 1'b0)
    );

    // With EN=0 and TE=0, gated_clk holds its previous value.
    gated_holds_without_control: assert property (
        @(posedge CLK) (!EN && !TE) |-> (gated_clk == $past(gated_clk))
    );

    // A posedge of gated_clk can only occur when EN=1.
    gated_edge_requires_en: assert property (
        @(posedge gated_clk) EN
    );

    // A posedge of gated_clk can only occur when TE=0.
    gated_edge_requires_te_low: assert property (
        @(posedge gated_clk) !TE
    );

    // On a detected gated_clk rise, Q equals D from the prior CLK.
    q_follows_D_on_gated_rise: assert property (
        @(posedge CLK) $rose(gated_clk) |-> (Q == $past(D))
    );

endmodule

rtl:
module sourceMod
  (
   output reg validData,
   input ctrl_clk,
   input ctrl_data
   );

   always @(posedge ctrl_clk) begin
      validData <= ~validData;
   end

endmodule

sva:
module sourceMod_sva (
    input logic ctrl_clk,
    input logic ctrl_data,
    input logic validData
);
    // If validData is 1, it becomes 0 on the next clock.
    check_toggle_1_to_0: assert property (
        @(posedge ctrl_clk) disable iff ($initstate)
            (validData === 1'b1) |-> ##1 (validData === 1'b0)
    );

    // If validData is 0, it becomes 1 on the next clock.
    check_toggle_0_to_1: assert property (
        @(posedge ctrl_clk) disable iff ($initstate)
            (validData === 1'b0) |-> ##1 (validData === 1'b1)
    );

    // A rise on validData is followed by a fall on the next clock.
    check_rise_followed_by_fall: assert property (
        @(posedge ctrl_clk) disable iff ($initstate)
            $rose(validData) |-> ##1 $fell(validData)
    );

    // A fall on validData is followed by a rise on the next clock.
    check_fall_followed_by_rise: assert property (
        @(posedge ctrl_clk) disable iff ($initstate)
            $fell(validData) |-> ##1 $rose(validData)
    );

    // When known, validData repeats every two clocks.
    check_two_cycle_periodicity: assert property (
        @(posedge ctrl_clk) disable iff ($initstate)
            (((validData===1'b0)||(validData===1'b1)) &&
             (($past(validData,2)===1'b0)||($past(validData,2)===1'b1)))
            |-> (validData == $past(validData,2))
    );

    // When known in consecutive cycles, validData toggles each clock.
    check_toggle_each_cycle_when_known: assert property (
        @(posedge ctrl_clk) disable iff ($initstate)
            (((validData===1'b0)||(validData===1'b1)) &&
             (($past(validData)===1'b0)||($past(validData)===1'b1)))
            |-> (validData != $past(validData))
    );
endmodule

rtl:
module d_ff_reset_preset(clk, reset, preset, d, q);
input clk, reset, preset, d;
output reg q;

always @(posedge clk)
begin
    if (!reset)
        q <= 1'b0;
    else if (!preset)
        q <= 1'b1;
    else
        q <= d;
end

endmodule

sva:
module d_ff_reset_preset_sva (
    input logic clk,
    input logic reset,   // active-low synchronous reset
    input logic preset,  // active-low synchronous preset
    input logic d,
    input logic q
);

    // q follows reset/preset/d priority on each clock edge.
    full_functional_update: assert property (
        @(posedge clk) q == (reset ? (preset ? d : 1'b1) : 1'b0)
    );

    // Active-low reset drives q to 0 on the same cycle.
    check_reset_low_forces_zero: assert property (
        @(posedge clk) !reset |-> (q == 1'b0)
    );

    // With reset high and preset low, q is set to 1.
    check_preset_low_sets_one: assert property (
        @(posedge clk) disable iff (!reset) (!preset) |-> (q == 1'b1)
    );

    // With both reset and preset high, q captures d.
    check_data_captured_when_enabled: assert property (
        @(posedge clk) disable iff (!reset) (preset) |-> (q == d)
    );

    // Reset has priority over preset when both are low.
    check_reset_priority_over_preset: assert property (
        @(posedge clk) (!reset && !preset) |-> (q == 1'b0)
    );

    // On reset falling (becoming active), q is driven to 0.
    check_fall_reset_forces_zero: assert property (
        @(posedge clk) $fell(reset) |-> (q == 1'b0)
    );

    // On preset falling (becoming active) with reset high, q is set to 1.
    check_fall_preset_sets_one: assert property (
        @(posedge clk) disable iff (!reset) $fell(preset) |-> (q == 1'b1)
    );

    // On preset rising with reset high, q is transparent to d.
    check_rise_preset_transparent: assert property (
        @(posedge clk) disable iff (!reset) $rose(preset) |-> (q == d)
    );

    // If both reset and preset are high across two cycles and d is stable, q remains stable.
    check_stable_d_implies_stable_q_when_enabled: assert property (
        @(posedge clk) disable iff (!reset)
            (preset && $past(preset) && $past(reset) && $stable(d)) |-> $stable(q)
    );

    // If both reset and preset are high across two cycles and d changes, q changes.
    check_data_change_propagates_when_enabled: assert property (
        @(posedge clk) disable iff (!reset)
            (preset && $past(preset) && $past(reset) && $changed(d)) |-> $changed(q)
    );

endmodule

rtl:
module dffr (din, clk, rst, q, se, si, so);

parameter SIZE = 1;

input	[SIZE-1:0]	din ;	// data in
input			clk ;	// clk or scan clk
input			rst ;	// reset

output	[SIZE-1:0]	q ;	// output

input			se ;	// scan-enable
input	[SIZE-1:0]	si ;	// scan-input
output	[SIZE-1:0]	so ;	// scan-output

reg 	[SIZE-1:0]	q ;

always @ (posedge clk)
	if (se) begin
		q[SIZE-1:0] <= si[SIZE-1:0];
	end else begin
		if (rst) begin
			q[SIZE-1:0] <= {SIZE{1'b0}};
		end else begin
			q[SIZE-1:0] <= din[SIZE-1:0];
		end
	end

assign so[SIZE-1:0] = q[SIZE-1:0] ;

endmodule

sva:
module dffr_sva #(
    parameter SIZE = 1
) (
    input logic                   clk,   // clock
    input logic                   rst,   // active-high synchronous reset
    input logic                   se,    // scan-enable
    input logic [SIZE-1:0]        din,   // data in
    input logic [SIZE-1:0]        si,    // scan in
    input logic [SIZE-1:0]        q,     // flop output
    input logic [SIZE-1:0]        so     // scan out (combinational mirror of q)
);
    // Clock: clk; Reset: rst (active-high synchronous).
    // Logic: Mixed — sequential flop for q; combinational so = q.
    // Behavior: se has priority; else if rst, q<=0; else q<=din.

    // so always mirrors q.
    check_so_mirrors_q: assert property (
        @(posedge clk) disable iff (rst) (so == q)
    );

    // On scan enable, q loads si on the next cycle (se has highest priority).
    check_scan_loads_si: assert property (
        @(posedge clk) disable iff (rst) $past(se) |-> (q == $past(si))
    );

    // With se deasserted, rst loads zero on the next cycle.
    check_sync_reset_loads_zero: assert property (
        @(posedge clk) disable iff (rst) $past((!se) && rst) |-> (q == {SIZE{1'b0}})
    );

    // With se deasserted and rst low, q loads din on the next cycle.
    check_functional_loads_din: assert property (
        @(posedge clk) disable iff (rst) $past((!se) && (!rst)) |-> (q == $past(din))
    );

    // In scan mode, so reflects previous si on the next cycle.
    check_so_follows_si_in_scan: assert property (
        @(posedge clk) disable iff (rst) $past(se) |-> (so == $past(si))
    );

    // After a reset cycle with se low, so is zero on the next cycle.
    check_so_zero_after_reset_cycle: assert property (
        @(posedge clk) disable iff (rst) $past((!se) && rst) |-> (so == {SIZE{1'b0}})
    );

    // If functional path selected and din equals prior q, q holds its value.
    check_hold_when_din_equals_q: assert property (
        @(posedge clk) disable iff (rst) $past((!se) && (!rst) && (din == q)) |-> (q == $past(q))
    );

    // If scan path selected and si equals prior q, q holds its value.
    check_hold_in_scan_when_si_equals_q: assert property (
        @(posedge clk) disable iff (rst) $past(se && (si == q)) |-> (q == $past(q))
    );

endmodule

rtl:
module adder_4_2 (
    input [3:0] A,
    output [1:0] Y
);

    wire [2:0] sum;
    wire [1:0] constant = 2'b10;

    assign sum = A + constant;
    assign Y = (sum > 3) ? 2'b11 : sum[1:0];

endmodule

sva:
module adder_4_2_sva (
    input logic [3:0] A,
    input logic [1:0] Y
);
    // No clock/reset in RTL; combinational; assertions sample on $global_clock.
    // Behavior: sum3=(A+2)[2:0]; Y = (sum3 > 3) ? 2'b11 : sum3[1:0].

    // Helper recomputation of RTL behavior
    logic [3:0] add4;
    logic [2:0] sum3;
    logic [1:0] expectedY;
    assign add4     = A + 4'd2;          // 4-bit add, as in RTL
    assign sum3     = add4[2:0];         // truncate to 3 bits, as in RTL
    assign expectedY= (sum3 > 3'd3) ? 2'b11 : sum3[1:0];

    // Y matches the recomputed RTL function
    check_y_functional_equivalence: assert property (
        @(posedge $global_clock) Y == expectedY
    );

    // When sum3 <= 3, Y passes through sum3[1:0]
    check_pass_through_when_sum_le3: assert property (
        @(posedge $global_clock) (sum3 <= 3'd3) |-> (Y == sum3[1:0])
    );

    // When sum3 > 3, Y saturates to 2'b11
    check_saturate_when_sum_gt3: assert property (
        @(posedge $global_clock) (sum3 > 3'd3) |-> (Y == 2'b11)
    );

    // If add4[2]==0 (sum3 in 0..3), Y equals add4[1:0]
    check_bit2_zero_pass_through: assert property (
        @(posedge $global_clock) (add4[2] == 1'b0) |-> (Y == add4[1:0])
    );

    // If add4[2]==1 (sum3 in 4..7), Y saturates to 2'b11
    check_bit2_one_saturate: assert property (
        @(posedge $global_clock) (add4[2] == 1'b1) |-> (Y == 2'b11)
    );

    // If input A is stable, output Y is stable (purely combinational)
    check_stable_input_implies_stable_output: assert property (
        @(posedge $global_clock) $stable(A) |-> $stable(Y)
    );

    // Function is periodic in A with period 8: f(A) == f(A+8)
    check_periodicity_plus8: assert property (
        @(posedge $global_clock) (A == ($past(A) + 4'd8)) |-> (Y == $past(Y))
    );

    // If Y == 0, the only possible sum3 is 0
    map_y_zero_implies_sum_zero: assert property (
        @(posedge $global_clock) (Y == 2'b00) |-> (sum3 == 3'd0)
    );

    // If Y == 1, the only possible sum3 is 1
    map_y_one_implies_sum_one: assert property (
        @(posedge $global_clock) (Y == 2'b01) |-> (sum3 == 3'd1)
    );

    // If Y == 2, the only possible sum3 is 2
    map_y_two_implies_sum_two: assert property (
        @(posedge $global_clock) (Y == 2'b10) |-> (sum3 == 3'd2)
    );

    // If Y == 3, sum3 must be >= 3
    map_y_three_implies_sum_ge3: assert property (
        @(posedge $global_clock) (Y == 2'b11) |-> (sum3 >= 3'd3)
    );

endmodule

rtl:
module Arithmetic_Logic_Unit (
    input [4:0] ctrl,
    input [15:0] data_in_A,
    input [15:0] data_in_B,
    output reg [15:0] data_out
    );

    always @* begin
        case(ctrl)
            1: data_out = data_in_A + data_in_B;
            2: data_out = data_in_A - data_in_B;
            3: data_out = data_in_A & data_in_B;
            4: data_out = data_in_A | data_in_B;
            5: data_out = data_in_A ^ data_in_B;
            6: data_out = ~data_in_A;
            7: data_out = ~data_in_B;
            8: data_out = data_in_A << 1;
            9: data_out = data_in_A >> 1;
            10: data_out = data_in_B << 1;
            11: data_out = data_in_B >> 1;
            12: data_out = (data_in_A == data_in_B) ? 1 : 0;
            13: data_out = (data_in_A < data_in_B) ? 1 : 0;
            14: data_out = (data_in_A > data_in_B) ? 1 : 0;
            15: data_out = (data_in_A <= data_in_B) ? 1 : 0;
            16: data_out = (data_in_A >= data_in_B) ? 1 : 0;
            default: data_out = 0;
        endcase
    end

endmodule

sva:
module Arithmetic_Logic_Unit_sva (
    input logic [4:0]  ctrl,
    input logic [15:0] data_in_A,
    input logic [15:0] data_in_B,
    input logic [15:0] data_out
);
    // ctrl=1: output is A + B
    check_add: assert property (
        @(posedge ctrl[0]) disable iff (1'b0) (ctrl == 5'd1) |-> (data_out == (data_in_A + data_in_B))
    );
    // ctrl=2: output is A - B
    check_sub: assert property (
        @(posedge ctrl[0]) disable iff (1'b0) (ctrl == 5'd2) |-> (data_out == (data_in_A - data_in_B))
    );
    // ctrl=3: output is A & B
    check_and: assert property (
        @(posedge ctrl[0]) disable iff (1'b0) (ctrl == 5'd3) |-> (data_out == (data_in_A & data_in_B))
    );
    // ctrl=4: output is A | B
    check_or: assert property (
        @(posedge ctrl[0]) disable iff (1'b0) (ctrl == 5'd4) |-> (data_out == (data_in_A | data_in_B))
    );
    // ctrl=5: output is A ^ B
    check_xor: assert property (
        @(posedge ctrl[0]) disable iff (1'b0) (ctrl == 5'd5) |-> (data_out == (data_in_A ^ data_in_B))
    );
    // ctrl=6: output is ~A
    check_not_a: assert property (
        @(posedge ctrl[0]) disable iff (1'b0) (ctrl == 5'd6) |-> (data_out == (~data_in_A))
    );
    // ctrl=7: output is ~B
    check_not_b: assert property (
        @(posedge ctrl[0]) disable iff (1'b0) (ctrl == 5'd7) |-> (data_out == (~data_in_B))
    );
    // ctrl=8: output is A << 1
    check_shl_a1: assert property (
        @(posedge ctrl[0]) disable iff (1'b0) (ctrl == 5'd8) |-> (data_out == (data_in_A << 1))
    );
    // ctrl=9: output is A >> 1
    check_shr_a1: assert property (
        @(posedge ctrl[0]) disable iff (1'b0) (ctrl == 5'd9) |-> (data_out == (data_in_A >> 1))
    );
    // ctrl=10: output is B << 1
    check_shl_b1: assert property (
        @(posedge ctrl[0]) disable iff (1'b0) (ctrl == 5'd10) |-> (data_out == (data_in_B << 1))
    );
    // ctrl=11: output is B >> 1
    check_shr_b1: assert property (
        @(posedge ctrl[0]) disable iff (1'b0) (ctrl == 5'd11) |-> (data_out == (data_in_B >> 1))
    );
    // ctrl=12: output is (A==B) ? 1 : 0
    check_eq: assert property (
        @(posedge ctrl[0]) disable iff (1'b0) (ctrl == 5'd12) |-> (data_out == ((data_in_A == data_in_B) ? 16'h0001 : 16'h0000))
    );
    // ctrl=13: output is (A<B) ? 1 : 0
    check_lt: assert property (
        @(posedge ctrl[0]) disable iff (1'b0) (ctrl == 5'd13) |-> (data_out == ((data_in_A < data_in_B) ? 16'h0001 : 16'h0000))
    );
    // ctrl=14: output is (A>B) ? 1 : 0
    check_gt: assert property (
        @(posedge ctrl[0]) disable iff (1'b0) (ctrl == 5'd14) |-> (data_out == ((data_in_A > data_in_B) ? 16'h0001 : 16'h0000))
    );
    // ctrl=15: output is (A<=B) ? 1 : 0
    check_le: assert property (
        @(posedge ctrl[0]) disable iff (1'b0) (ctrl == 5'd15) |-> (data_out == ((data_in_A <= data_in_B) ? 16'h0001 : 16'h0000))
    );
    // ctrl=16: output is (A>=B) ? 1 : 0
    check_ge: assert property (
        @(posedge ctrl[0]) disable iff (1'b0) (ctrl == 5'd16) |-> (data_out == ((data_in_A >= data_in_B) ? 16'h0001 : 16'h0000))
    );
    // ctrl not in 1..16: output is 0
    check_default_zero: assert property (
        @(posedge ctrl[0]) disable iff (1'b0) ((ctrl == 5'd0) || (ctrl > 5'd16)) |-> (data_out == 16'h0000)
    );
endmodule

