wire pwrgood_pp0_out_A;
wire pwrgood_pp1_out_sleepb;

// Instantiate power good checkers
pwrgood_pp PG0 (
    .PG(pwrgood_pp0_out_A),
    .A(A),
    .VPWR(VPWR),
    .KAGND(KAGND)
