sva:
module power_good_checker_sva (
    input logic CLK,
    input logic A,
    input logic SLEEP_B,
    input logic VPWR,
    input logic KAGND,
    input logic VPB,
    input logic VNB,
    input logic X
);
    ///// Functional definition /////
    // X equals A && SLEEP_B && VPWR && KAGND.
    check_x_definition: assert property (
        @(posedge CLK) X == (A && SLEEP_B && VPWR && KAGND)
    );

    ///// Necessary conditions for X HIGH /////
    // If X is HIGH then A, SLEEP_B, VPWR, and KAGND must be HIGH.
    check_x_implies_all_high: assert property (
        @(posedge CLK) (X == 1'b1) |-> (A && SLEEP_B && VPWR && KAGND)
    );

    ///// Sufficient conditions for X HIGH /////
    // If A, SLEEP_B, VPWR, and KAGND are all HIGH then X must be HIGH.
    check_all_high_implies_x_high: assert property (
        @(posedge CLK) (A && SLEEP_B && VPWR && KAGND) |-> (X == 1'b1)
    );

    ///// Low input forces X LOW /////
    // If VPWR is LOW then X must be LOW.
    check_x_low_when_vpwr_low: assert property (
        @(posedge CLK) (VPWR == 1'b0) |-> (X == 1'b0)
    );
    // If KAGND is LOW then X must be LOW.
    check_x_low_when_kagnd_low: assert property (
        @(posedge CLK) (KAGND == 1'b0) |-> (X == 1'b0)
    );
    // If A is LOW then X must be LOW.
    check_x_low_when_a_low: assert property (
        @(posedge CLK) (A == 1'b0) |-> (X == 1'b0)
    );
    // If SLEEP_B is LOW then X must be LOW.
    check_x_low_when_sleepb_low: assert property (
        @(posedge CLK) (SLEEP_B == 1'b0) |-> (X == 1'b0)
    );

    ///// Stability and independence /////
    // If A, SLEEP_B, VPWR, and KAGND are stable, X must be stable.
    check_x_stable_when_used_inputs_stable: assert property (
        @(posedge CLK) ($stable(A) && $stable(SLEEP_B) && $stable(VPWR) && $stable(KAGND)) |-> $stable(X)
    );
    // X is unaffected by VPB changes when used inputs are stable.
    check_x_unchanged_on_vpb_toggle: assert property (
        @(posedge CLK) ($changed(VPB) && $stable(A) && $stable(SLEEP_B) && $stable(VPWR) && $stable(KAGND)) |-> $stable(X)
    );
    // X is unaffected by VNB changes when used inputs are stable.
    check_x_unchanged_on_vnb_toggle: assert property (
        @(posedge CLK) ($changed(VNB) && $stable(A) && $stable(SLEEP_B) && $stable(VPWR) && $stable(KAGND)) |-> $stable(X)
    );
endmodule

rtl:
module concat_module (
  input [(16 - 1):0] in0,
  input [(16 - 1):0] in1,
  output [(32 - 1):0] y,
  input clk,
  input ce,
  input clr
);

  reg [(32 - 1):0] y_reg;

  always @(posedge clk) begin
    if (clr) begin
      y_reg <= 0;
    end else if (ce) begin
      y_reg <= {in0, in1};
    end
  end

  assign y = y_reg;

endmodule

sva:
module concat_module_sva (
  input  logic [15:0] in0,
  input  logic [15:0] in1,
  input  logic [31:0] y,
  input  logic        clk,
  input  logic        ce,
  input  logic        clr
);
  // Clock: clk; Reset: clr (synchronous, active-high). Sequential registered output with CE gating.

  // When clr is asserted, y must be 0 on the next cycle.
  reset_clears_next: assert property (
    @(posedge clk) clr |=> (y == '0)
  );

  // While reset is held (from a previous cycle), y stays 0.
  reset_holds_zero: assert property (
    @(posedge clk) $past(clr) |-> (y == '0)
  );

  // With ce HIGH (and not in reset), y loads {in0,in1} on the next cycle.
  load_on_ce: assert property (
    @(posedge clk) disable iff (clr) ce |=> (y == {$past(in0), $past(in1)})
  );

  // With ce LOW (and not in reset), y holds its value on the next cycle.
  hold_when_ce_low: assert property (
    @(posedge clk) disable iff (clr) !ce |=> (y == $past(y))
  );

  // Core next-state relation when not in or just after reset.
  update_main_relation: assert property (
    @(posedge clk) disable iff (clr || $past(clr))
      1'b1 |-> (y == ($past(ce) ? {$past(in0), $past(in1)} : $past(y)))
  );

  // Upper half of y matches in0 on a load.
  upper_half_on_load: assert property (
    @(posedge clk) disable iff (clr) ce |=> (y[31:16] == $past(in0))
  );

  // Lower half of y matches in1 on a load.
  lower_half_on_load: assert property (
    @(posedge clk) disable iff (clr) ce |=> (y[15:0] == $past(in1))
  );

  // Any y change (not around reset) must be caused by ce in the previous cycle.
  y_change_implies_past_ce: assert property (
    @(posedge clk) disable iff (clr || $past(clr)) $changed(y) |-> $past(ce)
  );

endmodule

rtl:
module add4bit(
    input [3:0] A,
    input [3:0] B,
    output [3:0] sum,
    output carry_out
);

    wire [3:0] xor_out;
    wire [3:0] and_out;

    // XOR each bit of A and B to get the sum
    assign xor_out = A ^ B;

    // AND each bit of A and B to get the carry-out
    assign and_out = A & B;

    // Shift the carry-out to the left by 1 bit
    assign carry_out = {and_out, 1'b0};

    // Add the carry-out to the sum
    assign sum = xor_out + carry_out;

endmodule

sva:
module add4bit_sva (
    input logic CLK,
    input logic RESETn,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] sum,
    input logic carry_out
);
    // carry_out is hardwired to 0 (LSB of {and_out,1'b0}).
    check_carry_out_const_zero: assert property (
        @(posedge CLK) disable iff (!RESETn) (carry_out == 1'b0)
    );

    // sum equals (A ^ B) + carry_out (lower 4 bits).
    check_sum_eq_xor_plus_carry: assert property (
        @(posedge CLK) disable iff (!RESETn) (sum == ((A ^ B) + carry_out)[3:0])
    );

    // With carry_out == 0, sum equals bitwise XOR of A and B.
    check_sum_eq_xor: assert property (
        @(posedge CLK) disable iff (!RESETn) (sum == (A ^ B))
    );

    // When A equals B, sum must be zero (XOR property).
    check_sum_zero_when_A_eq_B: assert property (
        @(posedge CLK) disable iff (!RESETn) (A == B) |-> (sum == 4'b0000)
    );

    // When A is zero, sum must equal B (XOR with zero).
    check_sum_eq_B_when_A_zero: assert property (
        @(posedge CLK) disable iff (!RESETn) (A == 4'b0000) |-> (sum == B)
    );

    // When B is zero, sum must equal A (XOR with zero).
    check_sum_eq_A_when_B_zero: assert property (
        @(posedge CLK) disable iff (!RESETn) (B == 4'b0000) |-> (sum == A)
    );

    // When A is bitwise NOT of B, sum must be all ones.
    check_sum_all_ones_when_A_is_bitwise_not_B: assert property (
        @(posedge CLK) disable iff (!RESETn) (A == ~B) |-> (sum == 4'hF)
    );

    // Outputs remain stable if inputs are stable (purely combinational).
    check_outputs_stable_when_inputs_stable: assert property (
        @(posedge CLK) disable iff (!RESETn) ($stable(A) && $stable(B)) |-> ($stable(sum) && $stable(carry_out))
    );
endmodule

