    // Output matches A & B when B falls.
    check_z_on_B_negedge: assert property (
        @(negedge B) Z == (A & B)
    );

    // If Z rises, both inputs must be HIGH.
    check_inputs_on_Z_posedge: assert property (
        @(posedge Z) (A & B)
    );

