module shift_register (
  input clk,
  input reset,
  input shift_in,
  input shift,
  output reg shift_out
);

  reg [15:0] data;

  always @(posedge clk) begin
    if (reset) begin
      data <= 0;
      shift_out <= 0;
    end
    else if (shift) begin
      shift_out <= data[15];
      data <= {data[14:0], shift_in};
    end
  end

endmodule

sva:
module shift_register_sva (
  input  logic        clk,
  input  logic        reset,      // active-high synchronous reset
  input  logic        shift_in,
  input  logic        shift,
  input  logic        shift_out,
  input  logic [15:0] data
);
  // On the cycle after reset was high, data and shift_out are cleared to 0.
  check_reset_clears_state: assert property (
    @(posedge clk) disable iff (reset)
      $past(reset) |-> (data == 16'h0) && (shift_out == 1'b0)
  );

  // When shifting (and not in reset in the previous cycle), data shifts left with new LSB from shift_in.
  check_shift_updates_data: assert property (
    @(posedge clk) disable iff (reset)
      $past(!reset && shift) |-> (data == { $past(data[14:0]), $past(shift_in) })
  );

  // When shifting (and not in reset in the previous cycle), shift_out equals previous MSB of data.
  check_shift_updates_shift_out: assert property (
    @(posedge clk) disable iff (reset)
      $past(!reset && shift) |-> (shift_out == $past(data[15]))
  );

  // Without shift (and not in reset in the previous cycle), data holds its value.
  check_hold_data_without_shift: assert property (
    @(posedge clk) disable iff (reset)
      $past(!reset && !shift) |-> (data == $past(data))
  );

  // Without shift (and not in reset in the previous cycle), shift_out holds its value.
  check_hold_shiftout_without_shift: assert property (
    @(posedge clk) disable iff (reset)
      $past(!reset && !shift) |-> (shift_out == $past(shift_out))
  );

  // On shift, new MSB of data comes from previous bit14.
  check_data_msb_from_prev_bit14: assert property (
    @(posedge clk) disable iff (reset)
      $past(!reset && shift) |-> (data[15] == $past(data[14]))
  );

  // On shift, new LSB of data comes from previous shift_in.
  check_data_lsb_from_shiftin: assert property (
    @(posedge clk) disable iff (reset)
      $past(!reset && shift) |-> (data[0] == $past(shift_in))
  );

  // Reset takes precedence over shift when both were high in the previous cycle.
  check_reset_overrides_shift: assert property (
    @(posedge clk) disable iff (reset)
      $past(reset && shift) |-> (data == 16'h0) && (shift_out == 1'b0)
  );
endmodule

rtl:
module data_whiting(
    output [7:0] dout,
    output next_indicator,
    input [7:0] din,
    input indicator,
    input clk,
    input reset_n
);

localparam RANDOM_INIT = 9'b1_1111_1111;

localparam WAITING = 0,
           PADDING = 1,
           ENCODING = 2;

reg [1:0] state, next_state;
reg [6:0] count, next_count;

reg [8:0] random_regs, next_random_regs;
reg [7:0] working_random, next_working_random;
wire [8:0] next_random = {random_regs[5] ^ random_regs[0], random_regs[8:1]};

always @(*) begin
    case (state)
        WAITING: begin
            if (indicator)
                next_state = PADDING;
            else
                next_state = WAITING;
            next_count = 0;
            next_random_regs = RANDOM_INIT;
            next_working_random = RANDOM_INIT;
        end

        PADDING: begin
            if (count < 79) begin
                next_state = PADDING;
                next_count = count + 1;
                next_random_regs = RANDOM_INIT;
            end else begin
                next_state = ENCODING;
                next_count = 0;
                next_random_regs = next_random;
            end
            next_working_random = RANDOM_INIT;
        end

        ENCODING: begin
            if (indicator) begin
                next_state = WAITING;
                next_count = 0;
            end else begin
                next_state = ENCODING;
                next_count = count + 1;
            end
            next_random_regs = next_random;
            next_working_random = (count[2:0] == 7 ?
                                   random_regs :
                                   working_random);
        end

        default: begin
            next_state = WAITING;
            next_count = 0;
            next_random_regs = RANDOM_INIT;
            next_working_random = RANDOM_INIT;
        end
    endcase
end

always @(posedge clk or negedge reset_n) begin
    if (~reset_n) begin
        state <= WAITING;
        count <= 0;
        random_regs <= RANDOM_INIT;
        working_random <= RANDOM_INIT;
    end else begin
        state <= next_state;
        count <= next_count;
        random_regs <= next_random_regs;
        working_random <= next_working_random;
    end
end

assign next_indicator = indicator;

assign dout = (state == ENCODING ? din ^ working_random : din);

endmodule

sva:
module data_whiting_sva (
    input  logic        clk,
    input  logic        reset_n,
    input  logic [7:0]  din,
    input  logic        indicator,
    input  logic [7:0]  dout,
    input  logic        next_indicator
);
    ///// Indicator pass-through /////
    // next_indicator equals indicator in normal operation.
    check_next_indicator_passthrough: assert property (
        @(posedge clk) disable iff (!reset_n) (next_indicator === indicator)
    );
    // next_indicator equals indicator during reset.
    check_next_indicator_passthrough_during_reset: assert property (
        @(posedge clk) (!reset_n) |-> (next_indicator === indicator)
    );
    // Rising edge on indicator must reflect on next_indicator.
    check_next_indicator_rise_match: assert property (
        @(posedge clk) disable iff (!reset_n) $rose(indicator) |-> $rose(next_indicator)
    );
    // Falling edge on indicator must reflect on next_indicator.
    check_next_indicator_fall_match: assert property (
        @(posedge clk) disable iff (!reset_n) $fell(indicator) |-> $fell(next_indicator)
    );
    // No spurious rising edge on next_indicator without indicator rising.
    check_no_spurious_rise_on_next_indicator: assert property (
        @(posedge clk) disable iff (!reset_n) $rose(next_indicator) |-> $rose(indicator)
    );
    // No spurious falling edge on next_indicator without indicator falling.
    check_no_spurious_fall_on_next_indicator: assert property (
        @(posedge clk) disable iff (!reset_n) $fell(next_indicator) |-> $fell(indicator)
    );
    // If indicator is stable, next_indicator must be stable.
    check_stable_indicator_implies_stable_next: assert property (
        @(posedge clk) disable iff (!reset_n) $stable(indicator) |-> $stable(next_indicator)
    );
    // If next_indicator is stable, indicator must be stable (pure pass-through).
    check_stable_next_implies_stable_indicator: assert property (
        @(posedge clk) disable iff (!reset_n) $stable(next_indicator) |-> $stable(indicator)
    );

    ///// Reset behavior /////
    // While reset is asserted, dout equals din (state forced to WAITING).
    check_dout_equals_din_during_reset: assert property (
        @(posedge clk) (!reset_n) |-> (dout === din)
    );
endmodule

