module multiplier
    # (parameter W = 32) (input wire clk,
    input wire [W-1:0] Data_A_i,
    input wire [W-1:0] Data_B_i,
    output wire [2*W-1:0] Data_S_o
    );

    reg [2*W-1:0] pdt_int;
    assign Data_S_o=pdt_int;always@(posedge clk)
    begin
        pdt_int<= Data_A_i*Data_B_i;
        end

endmodule

sva:
module multiplier_sva
    #(parameter int W = 32)
(
    input logic clk,
    input logic [W-1:0] Data_A_i,
    input logic [W-1:0] Data_B_i,
    input logic [2*W-1:0] Data_S_o
);

    // Output equals product of prior-cycle inputs (1-cycle latency).
    check_product_latency: assert property (
        @(posedge clk) $past(1'b1) |-> (Data_S_o == ($past(Data_A_i) * $past(Data_B_i)))
    );

    // If prior A is zero, output must be zero.
    check_zero_if_a_zero: assert property (
        @(posedge clk) $past(1'b1) && ($past(Data_A_i) == {W{1'b0}}) |-> (Data_S_o == {2*W{1'b0}})
    );

    // If prior B is zero, output must be zero.
    check_zero_if_b_zero: assert property (
        @(posedge clk) $past(1'b1) && ($past(Data_B_i) == {W{1'b0}}) |-> (Data_S_o == {2*W{1'b0}})
    );

    // If prior A is 1, output equals zero-extended prior B.
    check_identity_if_a_one: assert property (
        @(posedge clk) $past(1'b1) && ($past(Data_A_i) == {{(W-1){1'b0}},1'b1}) |-> (Data_S_o == {{W{1'b0}}, $past(Data_B_i)})
    );

    // If prior B is 1, output equals zero-extended prior A.
    check_identity_if_b_one: assert property (
        @(posedge clk) $past(1'b1) && ($past(Data_B_i) == {{(W-1){1'b0}},1'b1}) |-> (Data_S_o == {{W{1'b0}}, $past(Data_A_i)})
    );

    // LSB of output equals AND of prior-cycle input LSBs.
    check_lsb_and: assert property (
        @(posedge clk) $past(1'b1) |-> (Data_S_o[0] == ($past(Data_A_i[0]) & $past(Data_B_i[0])))
    );

    // If both prior inputs are odd, output LSB is 1.
    check_lsb_one_if_both_odd: assert property (
        @(posedge clk) $past(1'b1) && $past(Data_A_i[0]) && $past(Data_B_i[0]) |-> (Data_S_o[0] == 1'b1)
    );

    // If either prior input is even, output LSB is 0.
    check_lsb_zero_if_either_even: assert property (
        @(posedge clk) $past(1'b1) && ((!$past(Data_A_i[0])) || (!$past(Data_B_i[0]))) |-> (Data_S_o[0] == 1'b0)
    );

    // If inputs are unchanged across two cycles, output is unchanged across one cycle.
    check_stable_inputs_hold_output: assert property (
        @(posedge clk) $past(1'b1,2) && ($past(Data_A_i,1) == $past(Data_A_i,2)) && ($past(Data_B_i,1) == $past(Data_B_i,2)) |-> (Data_S_o == $past(Data_S_o,1))
    );

    // If prior A == 2, output equals zero-extended prior B shifted left by 1.
    generate if (W >= 2) begin : gen_shift_by1
        check_a_eq2_shift_b: assert property (
            @(posedge clk) $past(1'b1) && ($past(Data_A_i) == {{(W-2){1'b0}}, 2'b10}) |-> (Data_S_o == ({{W{1'b0}}, $past(Data_B_i)} << 1))
        );
        // If prior B == 2, output equals zero-extended prior A shifted left by 1.
        check_b_eq2_shift_a: assert property (
            @(posedge clk) $past(1'b1) && ($past(Data_B_i) == {{(W-2){1'b0}}, 2'b10}) |-> (Data_S_o == ({{W{1'b0}}, $past(Data_A_i)} << 1))
        );
    end endgenerate

endmodule

rtl:
module binary_adder(
    input [3:0] A,
    input [3:0] B,
    input C,
    output [3:0] Z
);

    wire [3:0] A_comp, B_comp;
    wire [4:0] sum;
    wire carry;

    assign A_comp = (~A) + 1;
    assign B_comp = (~B) + 1;

    assign sum = A_comp + B_comp + C;

    assign carry = sum[4];

    assign Z = (C) ? (~sum[3:0] + 1) : sum[3:0];

endmodule

sva:
module binary_adder_sva (
    input  logic        CLK,
    input  logic [3:0]  A,
    input  logic [3:0]  B,
    input  logic        C,
    input  logic [3:0]  Z
);
    // Local model mirroring RTL computations
    logic [3:0] A_comp, B_comp;
    logic [4:0] sum5;
    logic [3:0] sum_low;
    logic [3:0] z_expected_c0;
    logic [3:0] z_expected_c1;

    assign A_comp       = (~A) + 4'd1;
    assign B_comp       = (~B) + 4'd1;
    assign sum5         = {1'b0, A_comp} + {1'b0, B_comp} + {4'd0, C};
    assign sum_low      = sum5[3:0];
    assign z_expected_c0 = sum_low;
    assign z_expected_c1 = (~sum_low) + 4'd1;

    // When C=0, Z equals sum_low.
    check_z_when_c0: assert property (
        @(posedge CLK) (C == 1'b0) |-> (Z == z_expected_c0)
    );

    // When C=1, Z equals two's complement of sum_low.
    check_z_when_c1: assert property (
        @(posedge CLK) (C == 1'b1) |-> (Z == z_expected_c1)
    );

    // If A,B stable and C rises, Z becomes bitwise complement of previous Z.
    check_z_complement_on_c_rise: assert property (
        @(posedge CLK) ($stable(A) && $stable(B) && ($past(C,1,C) == 1'b0) && (C == 1'b1)) |-> (Z == ~ $past(Z,1,Z))
    );

    // If A,B stable and C falls, Z becomes bitwise complement of previous Z.
    check_z_complement_on_c_fall: assert property (
        @(posedge CLK) ($stable(A) && $stable(B) && ($past(C,1,C) == 1'b1) && (C == 1'b0)) |-> (Z == ~ $past(Z,1,Z))
    );

    // If A,B,C are all stable, Z must be stable (purely combinational behavior).
    check_output_stable_when_inputs_stable: assert property (
        @(posedge CLK) ($stable(A) && $stable(B) && $stable(C)) |-> $stable(Z)
    );

    // With C=1 and B stable, if A increments by 1 (mod 16), Z increments by 1 (mod 16).
    check_deltaA_inc_when_c1: assert property (
        @(posedge CLK) ($stable(B) && (C == 1'b1) && ($past(C,1,C) == 1'b1) && (A == ($past(A,1,A) + 4'd1))) |-> (Z == ($past(Z,1,Z) + 4'd1))
    );

    // With C=0 and B stable, if A increments by 1 (mod 16), Z decrements by 1 (mod 16).
    check_deltaA_inc_when_c0: assert property (
        @(posedge CLK) ($stable(B) && (C == 1'b0) && ($past(C,1,C) == 1'b0) && (A == ($past(A,1,A) + 4'd1))) |-> (Z == ($past(Z,1,Z) - 4'd1))
    );

    // With C=1 and A stable, if B increments by 1 (mod 16), Z increments by 1 (mod 16).
    check_deltaB_inc_when_c1: assert property (
        @(posedge CLK) ($stable(A) && (C == 1'b1) && ($past(C,1,C) == 1'b1) && (B == ($past(B,1,B) + 4'd1))) |-> (Z == ($past(Z,1,Z) + 4'd1))
    );

    // With C=0 and A stable, if B increments by 1 (mod 16), Z decrements by 1 (mod 16).
    check_deltaB_inc_when_c0: assert property (
        @(posedge CLK) ($stable(A) && (C == 1'b0) && ($past(C,1,C) == 1'b0) && (B == ($past(B,1,B) + 4'd1))) |-> (Z == ($past(Z,1,Z) - 4'd1))
    );

    // Alternative form for C=0: Z equals two's complement of (A+B) modulo 16.
    check_alt_formula_c0: assert property (
        @(posedge CLK) (C == 1'b0) |-> (Z == ((~(({1'b0, A} + {1'b0, B})[3:0])) + 4'd1))
    );

    // Alternative form for C=1: Z equals (A + B - 1) modulo 16.
    check_alt_formula_c1: assert property (
        @(posedge CLK) (C == 1'b1) |-> (Z == (({1'b0, A} + {1'b0, B} + 5'd15)[3:0]))
    );

endmodule

rtl:
module sky130_fd_sc_lp__nor3 (
    Y,
    A,
    B,
    C
);

    output Y;
    input  A;
    input  B;
    input  C;

    wire nor0_out_Y;

    nor nor0 (nor0_out_Y, C, A, B        );
    buf buf0 (Y         , nor0_out_Y     );

endmodule

sva:
module sky130_fd_sc_lp__nor3_sva (
    input logic CLK,
    input logic A,
    input logic B,
    input logic C,
    input logic Y
);
    // Y equals NOR of A, B, C.
    check_func_nor3_output: assert property (
        @(posedge CLK) Y == ~(A | B | C)
    );

    // Y HIGH implies all inputs LOW.
    check_y_high_implies_all_low: assert property (
        @(posedge CLK) (Y == 1'b1) |-> (!A && !B && !C)
    );

    // All inputs LOW implies Y HIGH.
    check_all_low_implies_y_high: assert property (
        @(posedge CLK) (!A && !B && !C) |-> (Y == 1'b1)
    );

    // Any input HIGH implies Y LOW.
    check_any_high_implies_y_low: assert property (
        @(posedge CLK) (A || B || C) |-> (Y == 1'b0)
    );

    // Rising A forces Y LOW in same cycle.
    check_roseA_causes_y_low: assert property (
        @(posedge CLK) $rose(A) |-> (Y == 1'b0)
    );

    // Rising B forces Y LOW in same cycle.
    check_roseB_causes_y_low: assert property (
        @(posedge CLK) $rose(B) |-> (Y == 1'b0)
    );

    // Rising C forces Y LOW in same cycle.
    check_roseC_causes_y_low: assert property (
        @(posedge CLK) $rose(C) |-> (Y == 1'b0)
    );

    // A falling to 0 with B,C already 0 makes Y HIGH.
    check_fellA_others_zero_causes_y_high: assert property (
        @(posedge CLK) ($fell(A) && !B && !C) |-> (Y == 1'b1)
    );

    // B falling to 0 with A,C already 0 makes Y HIGH.
    check_fellB_others_zero_causes_y_high: assert property (
        @(posedge CLK) ($fell(B) && !A && !C) |-> (Y == 1'b1)
    );

    // C falling to 0 with A,B already 0 makes Y HIGH.
    check_fellC_others_zero_causes_y_high: assert property (
        @(posedge CLK) ($fell(C) && !A && !B) |-> (Y == 1'b1)
    );
endmodule

rtl:
module twos_complement (
  input [3:0] in,
  output reg [3:0] out
);

  always @* begin
    out = ~in + 1;
  end

endmodule

sva:
module twos_complement_sva (
  input logic clk,
  input logic [3:0] in,
  input logic [3:0] out
);

  // Output equals two's complement of input (mod 16).
  check_twos_complement_mapping: assert property (
    @(posedge clk) out == (~in + 4'b0001)
  );

  // Two's complement is involutive: applying it to out yields in.
  check_involution: assert property (
    @(posedge clk) ((~out + 4'b0001) == in)
  );

  // Zero input maps to zero output.
  check_zero_in_to_zero_out: assert property (
    @(posedge clk) (in == 4'b0000) |-> (out == 4'b0000)
  );

  // Zero output implies zero input.
  check_zero_out_implies_zero_in: assert property (
    @(posedge clk) (out == 4'b0000) |-> (in == 4'b0000)
  );

  // -8 (1000) is a fixed point under two's complement.
  check_neg8_fixed_point: assert property (
    @(posedge clk) (in == 4'b1000) |-> (out == 4'b1000)
  );

  // Input and output sum to zero modulo 16.
  check_sum_zero_mod16: assert property (
    @(posedge clk) ((out + in) == 4'b0000)
  );

endmodule

rtl:
module BinaryCounter(clk, rst, count);
  input clk, rst;
  output reg [3:0] count;

  always @(posedge clk, posedge rst) begin
    if (rst) begin
      count <= 4'b0;
    end else begin
      if (count == 4'b1111) begin
        count <= 4'b0;
      end else begin
        count <= count + 1;
      end
    end
  end
endmodule

sva:
module BinaryCounter_sva (
    input logic clk,
    input logic rst,
    input logic [3:0] count
);
    ///// Reset behavior /////
    // When reset is HIGH at a clock edge, count must be 0.
    reset_forces_zero: assert property (
        @(posedge clk) rst |-> (count == 4'd0)
    );
    // On a sampled rising edge of reset, count is cleared to 0.
    reset_rise_clears_count: assert property (
        @(posedge clk) $rose(rst) |-> (count == 4'd0)
    );
    // While reset stays HIGH across cycles, count remains 0.
    hold_zero_while_reset: assert property (
        @(posedge clk) (rst && $past(rst)) |-> (count == 4'd0)
    );

    ///// Counting behavior (out of reset) /////
    // If not at max in prior cycle, next value increments by 1.
    increment_when_not_max: assert property (
        @(posedge clk) disable iff (rst) (!$past(rst) && ($past(count) != 4'hF)) |-> (count == ($past(count) + 1))
    );
    // If at max (15) in prior cycle, next value wraps to 0.
    wrap_on_max: assert property (
        @(posedge clk) disable iff (rst) (!$past(rst) && ($past(count) == 4'hF)) |-> (count == 4'd0)
    );
    // Out of reset, count changes every cycle.
    change_every_cycle_out_of_reset: assert property (
        @(posedge clk) disable iff (rst) (!$past(rst)) |-> (count != $past(count))
    );
    // Out of reset, a 0 value must come only from a prior 15.
    zero_only_from_wrap_out_of_reset: assert property (
        @(posedge clk) disable iff (rst) (!$past(rst) && (count == 4'd0)) |-> ($past(count) == 4'hF)
    );
    // After 16 cycles with no reset, count returns to its prior value (mod-16).
    period_16_no_reset: assert property (
        @(posedge clk) disable iff (rst) (!rst)[*16] |=> (count == $past(count,16))
    );
endmodule

module register_sva (
  input logic clk,
  input logic reset,
  input logic enable,
  input logic [31:0] data_in,
  input logic [31:0] data_out
);
  // On reset, next cycle data_out is zero.
  reset_clears_output_next: assert property (
    @(posedge clk) reset |=> (data_out == 32'd0)
  );

  // While reset stays asserted, data_out remains zero.
  hold_zero_during_reset: assert property (
    @(posedge clk) (reset && $past(reset)) |-> (data_out == 32'd0)
  );

  // When enabled (and not in reset), next data_out equals prior data_in.
  enable_loads_input_next: assert property (
    @(posedge clk) disable iff (reset) enable |=> (data_out == $past(data_in))
  );

  // When disabled (and not in reset), next data_out holds prior value.
  hold_value_when_disabled: assert property (
    @(posedge clk) disable iff (reset) !enable |=> (data_out == $past(data_out))
  );

  // Reset has priority over enable when both were high previously.
  reset_overrides_enable: assert property (
    @(posedge clk) $past(reset && enable) |-> (data_out == 32'd0)
  );

  // Any change in data_out must be due to prior reset or prior enable.
  change_requires_enable_or_reset: assert property (
    @(posedge clk) (data_out != $past(data_out)) |-> ($past(enable) || $past(reset))
  );

  // If prior cycle was not in reset, next data_out follows enable mux of prior values.
  update_rule_when_no_prior_reset: assert property (
    @(posedge clk) disable iff (reset) (!$past(reset)) |-> (data_out == ($past(enable) ? $past(data_in) : $past(data_out)))
  );

  // After reset deasserts, if enable is low, output remains zero.
  after_reset_zero_if_disabled: assert property (
    @(posedge clk) ($past(reset) && !reset && !enable) |-> (data_out == 32'd0)
  );

  // Two-cycle hold when disabled continuously (and not in reset).
  two_cycle_hold_when_disabled: assert property (
    @(posedge clk) disable iff (reset) (!enable ##1 !enable) |-> (data_out == $past(data_out, 2))
  );

  // With enable asserted in back-to-back cycles (no reset), output follows the second cycle's input.
  two_consecutive_enables_pipeline: assert property (
    @(posedge clk) disable iff (reset) (enable ##1 enable) |-> (data_out == $past(data_in, 1))
  );
endmodule

rtl:
module ripple_carry_adder (
    input [3:0] A,
    input [3:0] B,
    output reg [3:0] sum,
    output reg carry_out
);

    reg [3:0] carry;

    always @(*) begin
        {carry_out, sum} = A + B + carry;
    end

    always @(posedge carry_out) begin
        carry <= carry_out;
    end

endmodule

sva:
module ripple_carry_adder_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] sum,
    input logic       carry_out
);
    // Use the only edge in the RTL (posedge carry_out) as the property clock.
    default clocking @(posedge carry_out); endclocking

    // Rising edge cannot occur when both inputs are zero.
    check_no_rise_when_inputs_zero: assert property (
        (A != 4'd0) || (B != 4'd0)
    );

    // If A+B < 16, on a rise of carry_out the 4-bit sum must be strictly less than A+B.
    check_sum_lt_ab_when_ab_lt16: assert property (
        (({1'b0, A} + {1'b0, B}) < 5'd16) |-> ({1'b0, sum} < ({1'b0, A} + {1'b0, B}))
    );

    // If A+B >= 16, on a rise of carry_out the 4-bit sum must be at least (A+B - 16).
    check_sum_ge_ab_minus16_when_ab_ge16: assert property (
        (({1'b0, A} + {1'b0, B}) >= 5'd16) |-> ({1'b0, sum} >= (({1'b0, A} + {1'b0, B}) - 5'd16))
    );

    // When A+B == 31, on a rise of carry_out the sum must be 15.
    check_sum_eq_15_when_ab_eq31: assert property (
        (({1'b0, A} + {1'b0, B}) == 5'd31) |-> (sum == 4'd15)
    );

    // On a rise of carry_out, the 4-bit sum can never exceed A+B.
    check_sum_never_exceeds_ab_on_rise: assert property (
        ({1'b0, sum} <= ({1'b0, A} + {1'b0, B}))
    );

    // When A+B == 1, on a rise of carry_out the sum must be 0.
    check_sum_zero_when_ab_eq1_on_rise: assert property (
        (({1'b0, A} + {1'b0, B}) == 5'd1) |-> (sum == 4'd0)
    );

    // When A==15 and B==15, on a rise of carry_out the sum must be at least 14.
    check_lower_bound_for_max_inputs_on_rise: assert property (
        (A == 4'd15 && B == 4'd15) |-> (sum >= 4'd14)
    );

    // When A+B == 15, on a rise of carry_out the sum must be <= 14.
    check_sum_le_14_when_ab_eq15_on_rise: assert property (
        (({1'b0, A} + {1'b0, B}) == 5'd15) |-> (sum <= 4'd14)
    );

endmodule

rtl:
module karnaugh_map(
  input wire A, B, C,
  output wire F
);

  // Minimized Boolean expression: F = A'B' + AB' + BC
  assign F = (~A & ~B) | (A & ~B) | (B & C);

endmodule

sva:
module karnaugh_map_assert (
    input logic A,
    input logic B,
    input logic C,
    input logic F
);
    // F equals the RTL expression when sampled on A.
    check_function_equivalence_on_A: assert property (
        @(posedge A) F == ((~A & ~B) | (A & ~B) | (B & C))
    );
    // F equals the RTL expression when sampled on B.
    check_function_equivalence_on_B: assert property (
        @(posedge B) F == ((~A & ~B) | (A & ~B) | (B & C))
    );
    // F equals the RTL expression when sampled on C.
    check_function_equivalence_on_C: assert property (
        @(posedge C) F == ((~A & ~B) | (A & ~B) | (B & C))
    );
    // F equals the simplified form ~B | (B & C) on A edges.
    check_simplified_equivalence_on_A: assert property (
        @(posedge A) F == ((~B) | (B & C))
    );
    // If B is 0 then F must be 1 (A,C don't matter).
    check_B0_implies_F1_on_A: assert property (
        @(posedge A) (B != 1'b0) || (F == 1'b1)
    );
    // If B is 1 then F equals C.
    check_B1_implies_F_eq_C_on_A: assert property (
        @(posedge A) (B != 1'b1) || (F == C)
    );
    // If F is 0 then B must be 1 and C must be 0.
    check_F0_implies_B1C0_on_A: assert property (
        @(posedge A) (F != 1'b0) || ((B == 1'b1) && (C == 1'b0))
    );
    // If B and C are 1 then F must be 1.
    check_B1C1_implies_F1_on_A: assert property (
        @(posedge A) (!((B == 1'b1) && (C == 1'b1))) || (F == 1'b1)
    );
    // If B is 1 and C is 0 then F must be 0.
    check_B1C0_implies_F0_on_A: assert property (
        @(posedge A) (!((B == 1'b1) && (C == 1'b0))) || (F == 1'b0)
    );
    // If F is 1 then (~B) or (B & C) must hold.
    check_F1_implies_minterms_on_A: assert property (
        @(posedge A) (F != 1'b1) || ((~B) || (B && C))
    );
endmodule

rtl:
`define STATE_IDLE		        2'b00
`define STATE_LEADVERIFY		2'b01
`define STATE_DATARCV			2'b10

module ir_rcv (
    input clk50,
    input reset_n,
    input ir_rx,
	output reg [31:0] ir_code,
	output reg ir_code_ack
);

parameter LEADCODE_LO_THOLD     = 230000;  parameter LEADCODE_HI_THOLD     = 210000;  parameter LEADCODE_HI_RPT_THOLD = 105000;  parameter RPT_RELEASE_THOLD     = 6000000; parameter BIT_ONE_THOLD         = 41500;   parameter BIT_DETECT_THOLD      = 20000;   parameter IDLE_THOLD            = 262143;  reg [1:0] state;        reg [31:0] databuf;     reg [5:0] bits_detected;    reg [17:0] act_cnt;     reg [17:0] leadvrf_cnt; reg [17:0] datarcv_cnt; reg [22:0] rpt_cnt;     always @(posedge clk50 or negedge reset_n)
begin
    if (!reset_n)
        act_cnt <= 0;
	else
    begin
        if ((state == `STATE_IDLE) & (~ir_rx))
            act_cnt <= act_cnt + 1'b1;
        else
            act_cnt <= 0;
    end
end

always @(posedge clk50 or negedge reset_n)
begin
    if (!reset_n)
        leadvrf_cnt <= 0;
	else
    begin
        if ((state == `STATE_LEADVERIFY) & ir_rx)
            leadvrf_cnt <= leadvrf_cnt + 1'b1;
        else
            leadvrf_cnt <= 0;
    end
end


always @(posedge clk50 or negedge reset_n)
begin
    if (!reset_n)
    begin
        datarcv_cnt <= 0;
        bits_detected <= 0;
        databuf <= 0;
    end
	else
    begin
        if (state == `STATE_DATARCV)
        begin
            if (ir_rx)
                datarcv_cnt <= datarcv_cnt + 1'b1;
            else
                datarcv_cnt <= 0;

            if (datarcv_cnt == BIT_DETECT_THOLD)
                bits_detected <= bits_detected + 1'b1;

            if (datarcv_cnt == BIT_ONE_THOLD)
                databuf[32-bits_detected] <= 1'b1;
        end
        else
        begin
            datarcv_cnt <= 0;
            bits_detected <= 0;
            databuf <= 0;
        end
    end
end

always @(posedge clk50 or negedge reset_n)
begin
    if (!reset_n)
    begin
        ir_code_ack <= 1'b0;
        ir_code <= 32'h00000000;
    end
	else
    begin
        if ((bits_detected == 32) & (databuf[15:8] == ~databuf[7:0]))
        begin
            ir_code <= databuf;
            ir_code_ack <= 1'b1;
        end
        else if (rpt_cnt >= RPT_RELEASE_THOLD)
        begin
            ir_code <= 32'h00000000;
            ir_code_ack <= 1'b0;
        end
        else
            ir_code_ack <= 1'b0;
    end
end

always @(posedge clk50 or negedge reset_n)
begin
    if (!reset_n)
    begin
        state <= `STATE_IDLE;
        rpt_cnt <= 0;
    end
    else
    begin
        rpt_cnt <= rpt_cnt + 1'b1;

        case (state)
            `STATE_IDLE:
                if (act_cnt >= LEADCODE_LO_THOLD)
                    state <= `STATE_LEADVERIFY;
            `STATE_LEADVERIFY:
            begin
                if (leadvrf_cnt == LEADCODE_HI_RPT_THOLD)
                    rpt_cnt <= 0;
                if (leadvrf_cnt >= LEADCODE_HI_THOLD)
                    state <= `STATE_DATARCV;
            end    
            `STATE_DATARCV:
                if ((datarcv_cnt >= IDLE_THOLD) | (bits_detected >= 33))
                    state <= `STATE_IDLE;
            default:
                state <= `STATE_IDLE;
        endcase
    end
end

endmodule

sva:
module ir_rcv_sva (
    input logic        clk50,
    input logic        reset_n,
    input logic        ir_rx,
    input logic [31:0] ir_code,
    input logic        ir_code_ack,
    input logic [1:0]  state,
    input logic [31:0] databuf,
    input logic [5:0]  bits_detected,
    input logic [17:0] act_cnt,
    input logic [17:0] leadvrf_cnt,
    input logic [17:0] datarcv_cnt,
    input logic [22:0] rpt_cnt
);
    // Clk/Reset: clk50 posedge; reset_n active-low async
    // Logic style: sequential (all regs in posedge FFs)
    // Key behaviors: counters conditioned by state/ir_rx, 3-state FSM, ir_code/ack update on decode, release timeout reset

    // State encodings
    localparam logic [1:0] STATE_IDLE       = 2'b00;
    localparam logic [1:0] STATE_LEADVERIFY = 2'b01;
    localparam logic [1:0] STATE_DATARCV    = 2'b10;

    // Thresholds (match RTL)
    parameter int unsigned LEADCODE_LO_THOLD      = 230000;
    parameter int unsigned LEADCODE_HI_THOLD      = 210000;
    parameter int unsigned LEADCODE_HI_RPT_THOLD  = 105000;
    parameter int unsigned RPT_RELEASE_THOLD      = 6000000;
    parameter int unsigned BIT_ONE_THOLD          = 41500;
    parameter int unsigned BIT_DETECT_THOLD       = 20000;
    parameter int unsigned IDLE_THOLD             = 262143;

    ///// Reset behavior /////
    // On reset assertion, all regs/counters/outputs are cleared and state is IDLE.
    check_reset_values: assert property (
        @(posedge clk50) !reset_n |-> (state == STATE_IDLE)
                                   && (act_cnt == 18'd0)
                                   && (leadvrf_cnt == 18'd0)
                                   && (datarcv_cnt == 18'd0)
                                   && (bits_detected == 6'd0)
                                   && (databuf == 32'h0000_0000)
                                   && (rpt_cnt == 23'd0)
                                   && (ir_code == 32'h0000_0000)
                                   && (ir_code_ack == 1'b0)
    );

    ///// act_cnt rules /////
    // When in IDLE and ir_rx LOW, act_cnt increments by 1.
    check_act_cnt_incr: assert property (
        @(posedge clk50) disable iff (!reset_n)
            ($past(state) == STATE_IDLE && $past(ir_rx) == 1'b0)
            |-> (act_cnt == $past(act_cnt) + 1)
    );
    // Otherwise, act_cnt clears to 0.
    check_act_cnt_clear: assert property (
        @(posedge clk50) disable iff (!reset_n)
            !($past(state) == STATE_IDLE && $past(ir_rx) == 1'b0)
            |-> (act_cnt == 18'd0)
    );

    ///// leadvrf_cnt rules /////
    // When in LEADVERIFY and ir_rx HIGH, leadvrf_cnt increments by 1.
    check_leadvrf_incr: assert property (
        @(posedge clk50) disable iff (!reset_n)
            ($past(state) == STATE_LEADVERIFY && $past(ir_rx) == 1'b1)
            |-> (leadvrf_cnt == $past(leadvrf_cnt) + 1)
    );
    // Otherwise, leadvrf_cnt clears to 0.
    check_leadvrf_clear: assert property (
        @(posedge clk50) disable iff (!reset_n)
            !($past(state) == STATE_LEADVERIFY && $past(ir_rx) == 1'b1)
            |-> (leadvrf_cnt == 18'd0)
    );

    ///// datarcv_cnt rules /////
    // When in DATARCV and ir_rx HIGH, datarcv_cnt increments by 1.
    check_datarcv_incr: assert property (
        @(posedge clk50) disable iff (!reset_n)
            ($past(state) == STATE_DATARCV && $past(ir_rx) == 1'b1)
            |-> (datarcv_cnt == $past(datarcv_cnt) + 1)
    );
    // Otherwise, datarcv_cnt clears to 0.
    check_datarcv_clear: assert property (
        @(posedge clk50) disable iff (!reset_n)
            !($past(state) == STATE_DATARCV && $past(ir_rx) == 1'b1)
            |-> (datarcv_cnt == 18'd0)
    );

    ///// bits_detected rules /////
    // Outside DATARCV, bits_detected clears to 0.
    check_bits_clear_outside_datarcv: assert property (
        @(posedge clk50) disable iff (!reset_n)
            ($past(state) != STATE_DATARCV) |-> (bits_detected == 6'd0)
    );
    // In DATARCV, on BIT_DETECT_THOLD, bits_detected increments by 1.
    check_bits_incr_on_detect: assert property (
        @(posedge clk50) disable iff (!reset_n)
            ($past(state) == STATE_DATARCV && $past(datarcv_cnt) == BIT_DETECT_THOLD)
            |-> (bits_detected == $past(bits_detected) + 1)
    );
    // In DATARCV without detect, bits_detected holds its value.
    check_bits_hold_no_detect: assert property (
        @(posedge clk50) disable iff (!reset_n)
            ($past(state) == STATE_DATARCV && $past(datarcv_cnt) != BIT_DETECT_THOLD)
            |-> (bits_detected == $past(bits_detected))
    );

    ///// databuf rules /////
    // Outside DATARCV, databuf clears to 0.
    check_databuf_clear_outside_datarcv: assert property (
        @(posedge clk50) disable iff (!reset_n)
            ($past(state) != STATE_DATARCV) |-> (databuf == 32'h0000_0000)
    );
    // In DATARCV without BIT_ONE_THOLD, databuf holds its value.
    check_databuf_hold_no_one_thold: assert property (
        @(posedge clk50) disable iff (!reset_n)
            ($past(state) == STATE_DATARCV && $past(datarcv_cnt) != BIT_ONE_THOLD)
            |-> (databuf == $past(databuf))
    );
    // On BIT_ONE_THOLD in DATARCV, the indexed bit is set to 1.
    check_databuf_set_on_one_thold: assert property (
        @(posedge clk50) disable iff (!reset_n)
            ($past(state) == STATE_DATARCV && $past(datarcv_cnt) == BIT_ONE_THOLD && $past(bits_detected) <= 6'd32)
            |-> (databuf[32 - $past(bits_detected)] == 1'b1)
    );

    ///// ir_code_ack and ir_code rules /////
    // ir_code_ack equals the decode condition (bits==32 and byte complement).
    check_ack_equals_decode: assert property (
        @(posedge clk50) disable iff (!reset_n)
            (ir_code_ack == ( ($past(bits_detected) == 6'd32) && ($past(databuf[15:8]) == ~ $past(databuf[7:0])) ))
    );
    // When ack is asserted, ir_code updates to prior databuf.
    check_code_updates_on_ack: assert property (
        @(posedge clk50) disable iff (!reset_n)
            (ir_code_ack) |-> (ir_code == $past(databuf))
    );
    // On release timeout (when decode is not true), code and ack clear.
    check_release_clears_code_ack: assert property (
        @(posedge clk50) disable iff (!reset_n)
            ($past(rpt_cnt) >= RPT_RELEASE_THOLD
             && !(($past(bits_detected) == 6'd32) && ($past(databuf[15:8]) == ~ $past(databuf[7:0]))))
            |-> (ir_code == 32'h0000_0000 && ir_code_ack == 1'b0)
    );
    // When neither decode nor release occurs, ir_code holds its value.
    check_code_holds_no_event: assert property (
        @(posedge clk50) disable iff (!reset_n)
            (! (($past(bits_detected) == 6'd32) && ($past(databuf[15:8]) == ~ $past(databuf[7:0])))
             && !($past(rpt_cnt) >= RPT_RELEASE_THOLD))
            |-> (ir_code == $past(ir_code))
    );

    ///// rpt_cnt rules /////
    // rpt_cnt resets to 0 on LEADVERIFY HI repeat threshold.
    check_rpt_cnt_reset_on_lead_rpt: assert property (
        @(posedge clk50) disable iff (!reset_n)
            ($past(state) == STATE_LEADVERIFY && $past(leadvrf_cnt) == LEADCODE_HI_RPT_THOLD)
            |-> (rpt_cnt == 23'd0)
    );
    // Otherwise, rpt_cnt increments by 1.
    check_rpt_cnt_incr_otherwise: assert property (
        @(posedge clk50) disable iff (!reset_n)
            !($past(state) == STATE_LEADVERIFY && $past(leadvrf_cnt) == LEADCODE_HI_RPT_THOLD)
            |-> (rpt_cnt == $past(rpt_cnt) + 1)
    );

    ///// FSM transition rules /////
    // IDLE -> LEADVERIFY when act_cnt crosses low threshold.
    check_idle_to_leadverify: assert property (
        @(posedge clk50) disable iff (!reset_n)
            ($past(state) == STATE_IDLE && $past(act_cnt) >= LEADCODE_LO_THOLD)
            |-> (state == STATE_LEADVERIFY)
    );
    // LEADVERIFY -> DATARCV when leadvrf_cnt crosses high threshold.
    check_leadverify_to_datarcv: assert property (
        @(posedge clk50) disable iff (!reset_n)
            ($past(state) == STATE_LEADVERIFY && $past(leadvrf_cnt) >= LEADCODE_HI_THOLD)
            |-> (state == STATE_DATARCV)
    );
    // DATARCV -> IDLE on long idle or too many bits.
    check_datarcv_to_idle: assert property (
        @(posedge clk50) disable iff (!reset_n)
            ($past(state) == STATE_DATARCV && ($past(datarcv_cnt) >= IDLE_THOLD || $past(bits_detected) >= 6'd33))
            |-> (state == STATE_IDLE)
    );

endmodule

rtl:
module comparator_generic (
    input [3:0] Ain,
    input [3:0] Bin,
    output reg [3:0] CompOut
);

    // Comparator logic
    always @ (Ain, Bin) begin
        // Initialize output
        CompOut = 4'b0000;

        // Check if Ain is equal to Bin
        if (Ain == Bin) begin
            CompOut[0] = 1'b1; // Ain equals Bin
        end
        else if (Ain > Bin) begin
            CompOut[1] = 1'b1; // Ain is greater than Bin
        end
        else begin
            CompOut[2] = 1'b1; // Ain is less than Bin
        end

        // CompOut[3] can be assigned another condition or left as 0
    end

endmodule

sva:
module comparator_generic_sva (
    input logic clk,
    input logic [3:0] Ain,
    input logic [3:0] Bin,
    input logic [3:0] CompOut
);
    // Bit3 is always 0.
    check_compout3_zero: assert property (
        @(posedge clk) (CompOut[3] == 1'b0)
    );

    // Exactly one of CompOut[2:0] is 1.
    check_compout_onehot_2_0: assert property (
        @(posedge clk) $onehot(CompOut[2:0])
    );

    // If Ain == Bin, CompOut encodes equals (0001).
    check_equal_drives_eq_code: assert property (
        @(posedge clk) (Ain == Bin) |-> (CompOut == 4'b0001)
    );

    // If Ain > Bin, CompOut encodes greater (0010).
    check_greater_drives_gt_code: assert property (
        @(posedge clk) (Ain > Bin) |-> (CompOut == 4'b0010)
    );

    // If Ain < Bin, CompOut encodes less (0100).
    check_less_drives_lt_code: assert property (
        @(posedge clk) (Ain < Bin) |-> (CompOut == 4'b0100)
    );

    // If CompOut[0] is 1, inputs must be equal.
    check_eq_code_means_equal: assert property (
        @(posedge clk) (CompOut[0] == 1'b1) |-> (Ain == Bin)
    );

    // If CompOut[1] is 1, Ain must be greater than Bin.
    check_gt_code_means_greater: assert property (
        @(posedge clk) (CompOut[1] == 1'b1) |-> (Ain > Bin)
    );

    // If CompOut[2] is 1, Ain must be less than Bin.
    check_lt_code_means_less: assert property (
        @(posedge clk) (CompOut[2] == 1'b1) |-> (Ain < Bin)
    );

    // Output remains stable when inputs are stable.
    check_output_stable_when_inputs_stable: assert property (
        @(posedge clk) $stable({Ain, Bin}) |-> $stable(CompOut)
    );
endmodule

