sva:
module my_module_sva (
    input logic Y,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic B1,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB
);
    ///// Combinational function checks (clocked on $global_clock) /////
    // Y implements ~(B1 & (A1 | A2 | A3)).
    check_func_equiv: assert property (
        @(posedge $global_clock) Y == ~(B1 & (A1 | A2 | A3))
    );

    // B1 low forces Y high.
    check_b1_low_forces_high: assert property (
        @(posedge $global_clock) (B1 == 1'b0) |-> (Y == 1'b1)
    );

    // All A inputs low force Y high.
    check_all_a_low_forces_high: assert property (
        @(posedge $global_clock) ((A1 == 1'b0) && (A2 == 1'b0) && (A3 == 1'b0)) |-> (Y == 1'b1)
    );

    // B1 high and any A high force Y low.
    check_b1_high_and_any_a_high_forces_low: assert property (
        @(posedge $global_clock) ((B1 == 1'b1) && (A1 || A2 || A3)) |-> (Y == 1'b0)
    );

    // Y low implies B1 high and some A high.
    check_y_low_implies_conditions: assert property (
        @(posedge $global_clock) (Y == 1'b0) |-> ((B1 == 1'b1) && (A1 || A2 || A3))
    );

    // Only A1 high (A2,A3 low) makes Y == ~B1.
    check_only_a1_high_behaviour: assert property (
        @(posedge $global_clock) ((A1 == 1'b1) && (A2 == 1'b0) && (A3 == 1'b0)) |-> (Y == ~B1)
    );

    // Only A2 high (A1,A3 low) makes Y == ~B1.
    check_only_a2_high_behaviour: assert property (
        @(posedge $global_clock) ((A1 == 1'b0) && (A2 == 1'b1) && (A3 == 1'b0)) |-> (Y == ~B1)
    );

    // Only A3 high (A1,A2 low) makes Y == ~B1.
    check_only_a3_high_behaviour: assert property (
        @(posedge $global_clock) ((A1 == 1'b0) && (A2 == 1'b0) && (A3 == 1'b1)) |-> (Y == ~B1)
    );

    // All A high and B1 low drive Y high.
    check_all_a_high_b1_low_drives_y_high: assert property (
        @(posedge $global_clock) ((A1 == 1'b1) && (A2 == 1'b1) && (A3 == 1'b1) && (B1 == 1'b0)) |-> (Y == 1'b1)
    );
endmodule

rtl:
module adder(A, B, sum);
  input [3:0] A, B;
  output reg [4:0] sum;

  always @* begin
    sum = A + B;
    if (sum > 15) begin
      sum = sum[3:0];
    end
  end
endmodule

sva:
module adder_sva (
    input logic CLK,          // External clock for SVA sampling (DUT has no clock/reset)
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [4:0] sum
);
    // Sum equals A+B modulo 16 with zero MSB.
    check_sum_mod16: assert property (
        @(posedge CLK) sum == {1'b0, (A + B)[3:0]}
    );

    // MSB of sum is always zero.
    check_sum_msb_zero: assert property (
        @(posedge CLK) sum[4] == 1'b0
    );

    // Low nibble of sum equals low nibble of A+B.
    check_low_nibble_matches: assert property (
        @(posedge CLK) sum[3:0] == (A + B)[3:0]
    );

    // When no overflow, sum equals A+B exactly.
    check_no_overflow_result: assert property (
        @(posedge CLK) ((A + B) <= 5'd15) |-> (sum == (A + B))
    );

    // When overflow, sum wraps by subtracting 16.
    check_overflow_result: assert property (
        @(posedge CLK) ((A + B) >= 5'd16) |-> (sum == ((A + B) - 5'd16))
    );

    // Adding zero on A side passes B through (zero-extended).
    check_zero_A: assert property (
        @(posedge CLK) (A == 4'd0) |-> (sum == {1'b0, B})
    );

    // Adding zero on B side passes A through (zero-extended).
    check_zero_B: assert property (
        @(posedge CLK) (B == 4'd0) |-> (sum == {1'b0, A})
    );

    // Max plus max wraps to 14.
    check_max_plus_max: assert property (
        @(posedge CLK) ((A == 4'd15) && (B == 4'd15)) |-> (sum == 5'd14)
    );

    // 15 + 1 wraps to 0.
    check_wrap_15_plus_1: assert property (
        @(posedge CLK) ((A == 4'd15) && (B == 4'd1)) |-> (sum == 5'd0)
    );

    // 0 + 0 yields 0.
    check_zero_plus_zero: assert property (
        @(posedge CLK) ((A == 4'd0) && (B == 4'd0)) |-> (sum == 5'd0)
    );
endmodule

rtl:
module subfxp(a, b, q, clk);

   parameter width = 16, cycles=1;

   input signed [width-1:0]  a, b;
   input                     clk;   
   output signed [width-1:0] q;
   reg signed [width-1:0]    res[cycles-1:0];

   assign                    q = res[cycles-1];

   integer                   i;   

   always @(posedge clk) begin
     res[0] <= a-b;
      for (i=1; i < cycles; i = i+1)
        res[i] <= res[i-1] >> 1;

   end

endmodule

sva:
module subfxp_sva #(
    parameter int width = 16,
    parameter int cycles = 1
) (
    input  logic                         clk,
    input  logic signed [width-1:0]      a,
    input  logic signed [width-1:0]      b,
    input  logic signed [width-1:0]      q
);
    // Clock: clk. No reset in RTL.
    // Sequential pipeline: res[0] <= a-b; res[i] <= res[i-1] >> 1; q = res[cycles-1].
    // End-to-end behavior: q equals (a-b) delayed 'cycles' clocks and logically right-shifted by (cycles-1).

    localparam int SHIFT = (cycles > 0) ? (cycles - 1) : 0;

    // q matches the pipelined subtract and shift: q == $past(a-b, cycles) >> (cycles-1).
    check_end_to_end: assert property (
        @(posedge clk) $past(1'b1, cycles) |-> ( q == ($past(a - b, cycles) >> SHIFT) )
    );

    // If the past difference was zero, q must be zero after the pipeline latency.
    check_zero_diff_propagates_zero: assert property (
        @(posedge clk) ($past(1'b1, cycles) && ($past(a - b, cycles) == '0)) |-> (q == '0)
    );

    // If past b was zero, q equals past a logically right-shifted by (cycles-1).
    check_b_zero_passthrough: assert property (
        @(posedge clk) ($past(1'b1, cycles) && ($past(b, cycles) == '0)) |-> ( q == ($past(a, cycles) >> SHIFT) )
    );

    // If past a was zero, q equals negative past b logically right-shifted by (cycles-1).
    check_a_zero_negate: assert property (
        @(posedge clk) ($past(1'b1, cycles) && ($past(a, cycles) == '0)) |-> ( q == ((- $past(b, cycles)) >> SHIFT) )
    );

    // For cycles==1, stable inputs imply a stable output one cycle later (direct-register behavior).
    genvar _g;
    generate
        if (cycles == 1) begin : gen_c1_stability
            // With cycles==1, if a and b are stable, q is stable as well.
            check_stable_inputs_imply_stable_q_c1: assert property (
                @(posedge clk) ($stable(a) && $stable(b)) |-> $stable(q)
            );
        end
    endgenerate

    // For cycles>1 and SHIFT <= width, MSBs introduced by logical shift must be zero after latency.
    generate
        if (cycles > 1) begin : gen_shift_props
            if (SHIFT <= width) begin : gen_msb_zero
                // After latency, upper SHIFT bits of q are zero due to logical right shift.
                check_msb_zero_after_shift: assert property (
                    @(posedge clk) $past(1'b1, cycles) |-> ( q[width-1 -: SHIFT] == '0 )
                );
            end
            else begin : gen_shift_ge_width
                // If SHIFT >= width, the logical shift yields zero.
                check_full_shift_yields_zero: assert property (
                    @(posedge clk) $past(1'b1, cycles) |-> ( q == '0 )
                );
            end
        end
    endgenerate

endmodule

module binary_to_excess3_sva (
    input  logic       CLK,  // Sampling clock for assertions (DUT has no clock/reset)
    input  logic [3:0] B,
    input  logic [3:0] E
);
    ///// Functional mapping /////
    // E must equal B + 3 modulo 16.
    check_ex3_mapping: assert property (
        @(posedge CLK) E == (B + 4'd3)[3:0]
    );

    ///// Key specific mappings (including wrap-around cases) /////
    // B=0 maps to E=3.
    check_map_b0: assert property (
        @(posedge CLK) (B == 4'b0000) |-> (E == 4'b0011)
    );
    // B=9 maps to E=12.
    check_map_b9: assert property (
        @(posedge CLK) (B == 4'b1001) |-> (E == 4'b1100)
    );
    // B=12 maps to E=15.
    check_map_b12: assert property (
        @(posedge CLK) (B == 4'b1100) |-> (E == 4'b1111)
    );
    // B=13 wraps to E=0.
    check_map_wrap_b13: assert property (
        @(posedge CLK) (B == 4'b1101) |-> (E == 4'b0000)
    );
    // B=14 wraps to E=1.
    check_map_wrap_b14: assert property (
        @(posedge CLK) (B == 4'b1110) |-> (E == 4'b0001)
    );
    // B=15 wraps to E=2.
    check_map_wrap_b15: assert property (
        @(posedge CLK) (B == 4'b1111) |-> (E == 4'b0010)
    );

    ///// Temporal consistency (pure combinational behavior) /////
    // If B is stable across a cycle, E must be stable.
    check_stable_when_B_stable: assert property (
        @(posedge CLK) $stable(B) |-> $stable(E)
    );
    // If B changes across a cycle, E must change (bijection).
    check_E_changes_when_B_changes: assert property (
        @(posedge CLK) !$stable(B) |-> !$stable(E)
    );
    // If B increments by 1 modulo 16, E increments by 1 modulo 16.
    check_increment_consistency: assert property (
        @(posedge CLK) (B == ($past(B) + 4'd1)[3:0]) |-> (E == ($past(E) + 4'd1)[3:0])
    );
endmodule

rtl:
module counter (
   input clk,
   input reset,
   input [3:0] i_value,
   output reg [3:0] value
);

   always @(posedge clk or posedge reset) begin
      if (reset) begin
         value <= 0;
      end else if (value == 4'hF) begin
         value <= 4'h0;
      end else begin
         value <= value + 4'h1;
      end
   end

endmodule

sva:
module counter_sva (
    input logic clk,
    input logic reset,
    input logic [3:0] i_value,
    input logic [3:0] value
);
    // On any clock after reset is high, value must be 0.
    reset_clears_next: assert property (
        @(posedge clk) reset |=> (value == 4'h0)
    );

    // If reset stays asserted across consecutive clocks, value stays 0.
    reset_holds_zero: assert property (
        @(posedge clk) ($past(reset) && reset) |-> (value == 4'h0)
    );

    // When not in reset previously and value was not 0xF, increment by 1.
    inc_when_not_max: assert property (
        @(posedge clk) disable iff (reset) $past(!reset) && ($past(value) != 4'hF) |-> (value == ($past(value) + 4'h1))
    );

    // When not in reset previously and value was 0xF, wrap to 0.
    wrap_when_max: assert property (
        @(posedge clk) disable iff (reset) $past(!reset) && ($past(value) == 4'hF) |-> (value == 4'h0)
    );

    // Out of reset, value must change every cycle (increment or wrap).
    change_each_cycle_out_of_reset: assert property (
        @(posedge clk) disable iff (reset) $past(!reset) |-> (value != $past(value))
    );

    // Sanity: value is always within 4-bit range.
    value_within_range: assert property (
        @(posedge clk) 1'b1 |-> (value inside {[4'h0:4'hF]})
    );
endmodule

rtl:
module my_module (
    input A,
    input TE,
    input VPWR,
    input VGND,
    output reg Z
);

    always @(*) begin
        if (A == 1 && TE == 0) begin
            Z = VPWR;
        end else if (A == 0 && TE == 1) begin
            Z = VGND;
        end else if (A == 1 && TE == 1) begin
            Z = 1;
        end else if (A == 0 && TE == 0) begin
            Z = 0;
        end
    end

endmodule

sva:
module my_module_sva (
    input logic A,
    input logic TE,
    input logic VPWR,
    input logic VGND,
    input logic Z
);
    // No clock/reset in RTL; pure combinational logic sampled on input edges.

    // When A=1 and TE=0, Z must equal VPWR.
    check_a1_te0: assert property (
        @(posedge A or negedge A or posedge TE or negedge TE or posedge VPWR or negedge VPWR or posedge VGND or negedge VGND)
        (A && !TE) |=> (Z == VPWR)
    );

    // When A=0 and TE=1, Z must equal VGND.
    check_a0_te1: assert property (
        @(posedge A or negedge A or posedge TE or negedge TE or posedge VPWR or negedge VPWR or posedge VGND or negedge VGND)
        (!A && TE) |=> (Z == VGND)
    );

    // When A=1 and TE=1, Z must be 1.
    check_a1_te1: assert property (
        @(posedge A or negedge A or posedge TE or negedge TE or posedge VPWR or negedge VPWR or posedge VGND or negedge VGND)
        (A && TE) |=> (Z == 1'b1)
    );

    // When A=0 and TE=0, Z must be 0.
    check_a0_te0: assert property (
        @(posedge A or negedge A or posedge TE or negedge TE or posedge VPWR or negedge VPWR or posedge VGND or negedge VGND)
        (!A && !TE) |=> (Z == 1'b0)
    );

    // Summary for TE=0: Z equals (A ? VPWR : 0).
    check_te0_summary: assert property (
        @(posedge A or negedge A or posedge TE or negedge TE or posedge VPWR or negedge VPWR or posedge VGND or negedge VGND)
        (!TE) |=> (Z == (A ? VPWR : 1'b0))
    );

    // Summary for TE=1: Z equals (A ? 1 : VGND).
    check_te1_summary: assert property (
        @(posedge A or negedge A or posedge TE or negedge TE or posedge VPWR or negedge VPWR or posedge VGND or negedge VGND)
        (TE) |=> (Z == (A ? 1'b1 : VGND))
    );

    // When A and TE are equal, Z must equal TE (covers both 00->0 and 11->1).
    check_equal_inputs: assert property (
        @(posedge A or negedge A or posedge TE or negedge TE or posedge VPWR or negedge VPWR or posedge VGND or negedge VGND)
        (A == TE) |=> (Z == TE)
    );

    // Exact functional mapping: Z matches the coded truth table.
    check_truth_table_function: assert property (
        @(posedge A or negedge A or posedge TE or negedge TE or posedge VPWR or negedge VPWR or posedge VGND or negedge VGND)
        1'b1 |=> (Z == ((A && !TE) ? VPWR :
                        ((!A) && TE) ? VGND :
                        (A && TE)   ? 1'b1  :
                                      1'b0))
    );

endmodule

rtl:
module larger_number(
    input [3:0] num1,
    input [3:0] num2,
    output reg [3:0] larger
);

reg [3:0] stage1_num1;
reg [3:0] stage1_num2;
reg [1:0] stage2_result;

always @(num1) begin
    stage1_num1 <= num1;
end

always @(num2) begin
    stage1_num2 <= num2;
end

always @(stage1_num1, stage1_num2) begin
    if (stage1_num1 > stage1_num2) begin
        stage2_result <= 2'b01;
    end else if (stage1_num1 < stage1_num2) begin
        stage2_result <= 2'b10;
    end else begin
        stage2_result <= 2'b00;
    end
end

always @(stage2_result, stage1_num1, stage1_num2) begin
    if (stage2_result == 2'b01) begin
        larger <= stage1_num1;
    end else if (stage2_result == 2'b10) begin
        larger <= stage1_num2;
    end else begin
        larger <= stage1_num1;
    end
end

endmodule

sva:
module larger_number_sva (
    // Analysis: No clock/reset in DUT; pure combinational selection of max(num1,num2); equal selects num1.
    // Sampling clock/reset provided here for SVA only (active-low RESETn).
    input  logic        CLK,
    input  logic        RESETn,
    input  logic [3:0]  num1,
    input  logic [3:0]  num2,
    input  logic [3:0]  larger
);
    // If num1 > num2, output must equal num1.
    check_larger_is_num1_when_gt: assert property (
        @(posedge CLK) disable iff (!RESETn) (num1 > num2) |-> (larger == num1)
    );

    // If num2 > num1, output must equal num2.
    check_larger_is_num2_when_gt: assert property (
        @(posedge CLK) disable iff (!RESETn) (num2 > num1) |-> (larger == num2)
    );

    // If num1 == num2, output must equal num1 (tie breaks to num1).
    check_larger_is_num1_when_eq: assert property (
        @(posedge CLK) disable iff (!RESETn) (num1 == num2) |-> (larger == num1)
    );

    // Output must always equal one of the two inputs.
    check_output_is_one_of_inputs: assert property (
        @(posedge CLK) disable iff (!RESETn) (larger == num1) || (larger == num2)
    );

    // If output selects num1 and inputs differ, then num1 must be greater.
    check_num1_selected_implies_gt: assert property (
        @(posedge CLK) disable iff (!RESETn) ((larger == num1) && (num1 != num2)) |-> (num1 > num2)
    );

    // If output selects num2 and inputs differ, then num2 must be greater.
    check_num2_selected_implies_gt: assert property (
        @(posedge CLK) disable iff (!RESETn) ((larger == num2) && (num1 != num2)) |-> (num2 > num1)
    );

    // When both inputs are stable across a cycle, the output must be stable.
    check_stability_when_inputs_stable: assert property (
        @(posedge CLK) disable iff (!RESETn) $stable(num1) && $stable(num2) |-> $stable(larger)
    );

    // Output value must be at least as large as each input (i.e., equals the max).
    check_output_is_at_least_each_input: assert property (
        @(posedge CLK) disable iff (!RESETn) (larger >= num1) && (larger >= num2)
    );

    // Output can change only if at least one input changed.
    check_output_change_requires_input_change: assert property (
        @(posedge CLK) disable iff (!RESETn) $changed(larger) |-> ($changed(num1) || $changed(num2))
    );
endmodule

