module adder_module (
    input clk,
    input rst,
    input en,
    input [3:0] input_val,
    output reg [3:0] output_val
);

localparam CONSTANT_VAL = 4'b1011;

always @(posedge clk, posedge rst)
    if (rst) begin
        output_val <= 4'b0;
    end else if (en) begin
        output_val <= input_val + CONSTANT_VAL;
    end

endmodule

sva:
module adder_module_sva (
    input logic clk,
    input logic rst,
    input logic en,
    input logic [3:0] input_val,
    input logic [3:0] output_val
);
    // Reset drives output_val to zero whenever rst is HIGH.
    reset_forces_zero: assert property (
        @(posedge clk) rst |-> (output_val == 4'b0000)
    );

    // On enable with reset low, next-cycle output equals (previous input_val + 0xB) modulo 16.
    update_on_enable: assert property (
        @(posedge clk) disable iff (rst)
            (en && !rst) |=> (!rst && (output_val == (($past(input_val) + 4'b1011)[3:0])))
    );

    // With enable low and reset low, output holds its previous value next cycle.
    hold_when_disabled: assert property (
        @(posedge clk) disable iff (rst)
            (!en && !rst) |=> (!rst && (output_val == $past(output_val)))
    );

    // Any change in output across cycles (with reset low both cycles) requires prior enable high.
    change_requires_enable: assert property (
        @(posedge clk) disable iff (rst)
            (!rst && !$past(rst) && (output_val != $past(output_val))) |-> $past(en)
    );

    // If reset rises between cycles, at this clock edge output is zero.
    reset_rise_clears_output: assert property (
        @(posedge clk) $rose(rst) |-> (output_val == 4'b0000)
    );

    // If reset is low in consecutive cycles and enable was low, output remains unchanged.
    stable_without_enable_two_cycles: assert property (
        @(posedge clk) disable iff (rst)
            (!rst && !$past(rst) && !$past(en)) |-> (output_val == $past(output_val))
    );
endmodule

module MULTIPLEXER_4_TO_1_sva #(
    parameter BUS_WIDTH = 32
) (
    // External sampling clock for assertions (DUT has no clock/reset)
    input  logic                      CLK,
    // DUT ports
    input  logic [BUS_WIDTH-1:0]      IN1,
    input  logic [BUS_WIDTH-1:0]      IN2,
    input  logic [BUS_WIDTH-1:0]      IN3,
    input  logic [BUS_WIDTH-1:0]      IN4,
    input  logic [1:0]                SELECT,
    input  logic [BUS_WIDTH-1:0]      OUT
);
    // SELECT==00 routes IN1 to OUT in the same cycle.
    check_sel00_routes_IN1: assert property (
        @(posedge CLK) (SELECT == 2'b00) |-> (OUT == IN1)
    );

    // SELECT==01 routes IN2 to OUT in the same cycle.
    check_sel01_routes_IN2: assert property (
        @(posedge CLK) (SELECT == 2'b01) |-> (OUT == IN2)
    );

    // SELECT==10 routes IN3 to OUT in the same cycle.
    check_sel10_routes_IN3: assert property (
        @(posedge CLK) (SELECT == 2'b10) |-> (OUT == IN3)
    );

    // SELECT==11 routes IN4 to OUT in the same cycle.
    check_sel11_routes_IN4: assert property (
        @(posedge CLK) (SELECT == 2'b11) |-> (OUT == IN4)
    );

    // When SELECT==00 and IN1 changes, OUT matches IN1 that same cycle.
    check_propagation_sel00: assert property (
        @(posedge CLK) (SELECT == 2'b00 && $changed(IN1)) |-> (OUT == IN1)
    );

    // When SELECT==01 and IN2 changes, OUT matches IN2 that same cycle.
    check_propagation_sel01: assert property (
        @(posedge CLK) (SELECT == 2'b01 && $changed(IN2)) |-> (OUT == IN2)
    );

    // When SELECT==10 and IN3 changes, OUT matches IN3 that same cycle.
    check_propagation_sel10: assert property (
        @(posedge CLK) (SELECT == 2'b10 && $changed(IN3)) |-> (OUT == IN3)
    );

    // When SELECT==11 and IN4 changes, OUT matches IN4 that same cycle.
    check_propagation_sel11: assert property (
        @(posedge CLK) (SELECT == 2'b11 && $changed(IN4)) |-> (OUT == IN4)
    );

    // With SELECT==00 and IN1/SELECT stable, changes on other inputs do not affect OUT.
    check_isolation_sel00: assert property (
        @(posedge CLK) (SELECT == 2'b00 && $stable(SELECT) && $stable(IN1) && ($changed(IN2) || $changed(IN3) || $changed(IN4))) |-> $stable(OUT)
    );

    // With SELECT==01 and IN2/SELECT stable, changes on other inputs do not affect OUT.
    check_isolation_sel01: assert property (
        @(posedge CLK) (SELECT == 2'b01 && $stable(SELECT) && $stable(IN2) && ($changed(IN1) || $changed(IN3) || $changed(IN4))) |-> $stable(OUT)
    );

    // With SELECT==10 and IN3/SELECT stable, changes on other inputs do not affect OUT.
    check_isolation_sel10: assert property (
        @(posedge CLK) (SELECT == 2'b10 && $stable(SELECT) && $stable(IN3) && ($changed(IN1) || $changed(IN2) || $changed(IN4))) |-> $stable(OUT)
    );

    // With SELECT==11 and IN4/SELECT stable, changes on other inputs do not affect OUT.
    check_isolation_sel11: assert property (
        @(posedge CLK) (SELECT == 2'b11 && $stable(SELECT) && $stable(IN4) && ($changed(IN1) || $changed(IN2) || $changed(IN3))) |-> $stable(OUT)
    );
endmodule

rtl:
module pipeemreg(i_wreg,i_m2reg,i_wmem,i_alu,i_b,i_rn,clk,rst,o_wreg,o_m2reg,o_wmem,o_alu,o_b,o_rn);
  input wire clk, rst,i_wreg,i_m2reg,i_wmem;
  input wire [31:0] i_b,i_alu;
  input wire [4:0] i_rn;
  output reg o_wreg,o_m2reg,o_wmem;
  output reg [31:0] o_b,o_alu;
  output reg [4:0] o_rn;
  always @(posedge clk) begin
    if (rst) begin 
      o_wreg<=0;
      o_m2reg<=0;
      o_wmem<=0;
      o_alu<=0;
      o_b<=0;
      o_rn<=0;
    end
    else begin 
      o_wreg<=i_wreg;
      o_m2reg<=i_m2reg;
      o_wmem<=i_wmem;
      o_alu<=i_alu;
      o_b<=i_b;
      o_rn<=i_rn;
    end
  end
endmodule

sva:
module pipeemreg_sva (
  input logic i_wreg,
  input logic i_m2reg,
  input logic i_wmem,
  input logic [31:0] i_alu,
  input logic [31:0] i_b,
  input logic [4:0] i_rn,
  input logic clk,
  input logic rst,
  input logic o_wreg,
  input logic o_m2reg,
  input logic o_wmem,
  input logic [31:0] o_alu,
  input logic [31:0] o_b,
  input logic [4:0] o_rn
);
  // Clock: clk (posedge). Reset: rst (active-high, synchronous). Sequential pipeline reg: pass-through when !rst, zeros when rst.

  ///// Reset behavior (previous cycle rst -> outputs zero this cycle) /////
  // If rst was HIGH last cycle, o_wreg is 0 this cycle.
  reset_prev_clears_o_wreg: assert property (
    @(posedge clk) $past(rst) |-> (o_wreg == 1'b0)
  );
  // If rst was HIGH last cycle, o_m2reg is 0 this cycle.
  reset_prev_clears_o_m2reg: assert property (
    @(posedge clk) $past(rst) |-> (o_m2reg == 1'b0)
  );
  // If rst was HIGH last cycle, o_wmem is 0 this cycle.
  reset_prev_clears_o_wmem: assert property (
    @(posedge clk) $past(rst) |-> (o_wmem == 1'b0)
  );
  // If rst was HIGH last cycle, o_alu is 0 this cycle.
  reset_prev_clears_o_alu: assert property (
    @(posedge clk) $past(rst) |-> (o_alu == 32'd0)
  );
  // If rst was HIGH last cycle, o_b is 0 this cycle.
  reset_prev_clears_o_b: assert property (
    @(posedge clk) $past(rst) |-> (o_b == 32'd0)
  );
  // If rst was HIGH last cycle, o_rn is 0 this cycle.
  reset_prev_clears_o_rn: assert property (
    @(posedge clk) $past(rst) |-> (o_rn == 5'd0)
  );

  ///// Transfer behavior (previous cycle !rst -> outputs follow previous inputs) /////
  // When not in reset previously, o_wreg equals previous i_wreg.
  transfer_o_wreg_follows_i: assert property (
    @(posedge clk) disable iff (rst) ($past(rst) == 1'b0) |-> (o_wreg == $past(i_wreg))
  );
  // When not in reset previously, o_m2reg equals previous i_m2reg.
  transfer_o_m2reg_follows_i: assert property (
    @(posedge clk) disable iff (rst) ($past(rst) == 1'b0) |-> (o_m2reg == $past(i_m2reg))
  );
  // When not in reset previously, o_wmem equals previous i_wmem.
  transfer_o_wmem_follows_i: assert property (
    @(posedge clk) disable iff (rst) ($past(rst) == 1'b0) |-> (o_wmem == $past(i_wmem))
  );
  // When not in reset previously, o_alu equals previous i_alu.
  transfer_o_alu_follows_i: assert property (
    @(posedge clk) disable iff (rst) ($past(rst) == 1'b0) |-> (o_alu == $past(i_alu))
  );
  // When not in reset previously, o_b equals previous i_b.
  transfer_o_b_follows_i: assert property (
    @(posedge clk) disable iff (rst) ($past(rst) == 1'b0) |-> (o_b == $past(i_b))
  );
  // When not in reset previously, o_rn equals previous i_rn.
  transfer_o_rn_follows_i: assert property (
    @(posedge clk) disable iff (rst) ($past(rst) == 1'b0) |-> (o_rn == $past(i_rn))
  );

endmodule

rtl:
module magnitude_comparator_4bit (
    input [3:0] A,
    input [3:0] B,
    output EQ,
    output GT,
    output LT
);

    reg [2:0] result;

    always @* begin
        case (A > B)
            1'b0: result = (A == B) ? 3'b100 : 3'b001;
            1'b1: result = 3'b010;
        endcase
    end

    assign EQ = (result == 3'b100);
    assign GT = (result == 3'b010);
    assign LT = (result == 3'b001);

endmodule

sva:
module magnitude_comparator_4bit_sva (
    input logic CLK,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic EQ,
    input logic GT,
    input logic LT
);
    // EQ reflects A == B.
    check_eq_definition: assert property (
        @(posedge CLK) (EQ == (A == B))
    );
    // GT reflects A > B.
    check_gt_definition: assert property (
        @(posedge CLK) (GT == (A > B))
    );
    // LT reflects A < B.
    check_lt_definition: assert property (
        @(posedge CLK) (LT == (A < B))
    );
    // When A == B, only EQ is high.
    check_eq_mapping: assert property (
        @(posedge CLK) (A == B) |-> (EQ && !GT && !LT)
    );
    // When A > B, only GT is high.
    check_gt_mapping: assert property (
        @(posedge CLK) (A > B) |-> (GT && !EQ && !LT)
    );
    // When A < B, only LT is high.
    check_lt_mapping: assert property (
        @(posedge CLK) (A < B) |-> (LT && !EQ && !GT)
    );
    // Outputs are one-hot across EQ/GT/LT.
    check_outputs_onehot: assert property (
        @(posedge CLK) $onehot({EQ, GT, LT})
    );
    // If inputs are stable, outputs remain stable (purely combinational behavior).
    check_stability_with_stable_inputs: assert property (
        @(posedge CLK) ($stable(A) && $stable(B)) |-> $stable({EQ, GT, LT})
    );
endmodule

rtl:
module gray_code_converter (
  input [3:0] in,
  output [3:0] gray_out
);

  wire [3:0] gray_out;  // Declare gray_out as a wire type

  assign gray_out[0] = in[0];
  assign gray_out[1] = in[0] ^ in[1];
  assign gray_out[2] = in[1] ^ in[2];
  assign gray_out[3] = in[2] ^ in[3];

endmodule

sva:
module gray_code_converter_sva (
    input logic clk,
    input logic [3:0] in,
    input logic [3:0] gray_out
);
    // gray_out[0] equals in[0].
    check_gray0_is_in0: assert property (
        @(posedge clk) gray_out[0] == in[0]
    );

    // gray_out[1] equals in[0] XOR in[1].
    check_gray1_is_in0_xor_in1: assert property (
        @(posedge clk) gray_out[1] == (in[0] ^ in[1])
    );

    // gray_out[2] equals in[1] XOR in[2].
    check_gray2_is_in1_xor_in2: assert property (
        @(posedge clk) gray_out[2] == (in[1] ^ in[2])
    );

    // gray_out[3] equals in[2] XOR in[3].
    check_gray3_is_in2_xor_in3: assert property (
        @(posedge clk) gray_out[3] == (in[2] ^ in[3])
    );

    // Vector mapping: gray_out == {in[2]^in[3], in[1]^in[2], in[0]^in[1], in[0]}.
    check_vector_mapping: assert property (
        @(posedge clk) gray_out == { (in[2] ^ in[3]), (in[1] ^ in[2]), (in[0] ^ in[1]), in[0] }
    );

    // Outputs remain stable if inputs are stable between cycles.
    check_stability_when_inputs_stable: assert property (
        @(posedge clk) $stable(in) |-> $stable(gray_out)
    );
endmodule

rtl:
module mux_4to1(
    input [3:0] I,
    input [1:0] S,
    output reg O
    );

    always @(*)
    begin
        case({S[1], S[0]})
            2'b00: O = I[0];
            2'b01: O = I[1];
            2'b10: O = I[2];
            2'b11: O = I[3];
        endcase
    end
endmodule

sva:
module mux_4to1_sva (
    input logic clk,         // sampling clock for assertions (RTL is combinational; no reset)
    input logic [3:0] I,
    input logic [1:0] S,
    input logic O
);
    // O equals the selected input bit every cycle.
    check_mux_function: assert property (
        @(posedge clk) O == I[S]
    );

    // When S==2'b00, O must equal I[0].
    check_sel00_map: assert property (
        @(posedge clk) (S == 2'b00) |-> (O == I[0])
    );

    // When S==2'b01, O must equal I[1].
    check_sel01_map: assert property (
        @(posedge clk) (S == 2'b01) |-> (O == I[1])
    );

    // When S==2'b10, O must equal I[2].
    check_sel10_map: assert property (
        @(posedge clk) (S == 2'b10) |-> (O == I[2])
    );

    // When S==2'b11, O must equal I[3].
    check_sel11_map: assert property (
        @(posedge clk) (S == 2'b11) |-> (O == I[3])
    );

    // If S and all I bits are stable, O must be stable.
    check_stable_when_inputs_stable: assert property (
        @(posedge clk) ($stable(S) && $stable(I)) |-> $stable(O)
    );

    // If S is stable and O changes, then the selected input bit must have changed.
    check_output_change_requires_selected_change: assert property (
        @(posedge clk) ($stable(S) && $changed(O)) |-> 
            ((S == 2'b00 && $changed(I[0])) ||
             (S == 2'b01 && $changed(I[1])) ||
             (S == 2'b10 && $changed(I[2])) ||
             (S == 2'b11 && $changed(I[3])))
    );

    // With S==2'b00 stable and I[0] stable, O must be stable (unselected inputs don't affect O).
    check_sel00_stability: assert property (
        @(posedge clk) ($stable(S) && (S == 2'b00) && $stable(I[0])) |-> $stable(O)
    );

    // With S==2'b01 stable and I[1] stable, O must be stable (unselected inputs don't affect O).
    check_sel01_stability: assert property (
        @(posedge clk) ($stable(S) && (S == 2'b01) && $stable(I[1])) |-> $stable(O)
    );

    // With S==2'b10 stable and I[2] stable, O must be stable (unselected inputs don't affect O).
    check_sel10_stability: assert property (
        @(posedge clk) ($stable(S) && (S == 2'b10) && $stable(I[2])) |-> $stable(O)
    );

    // With S==2'b11 stable and I[3] stable, O must be stable (unselected inputs don't affect O).
    check_sel11_stability: assert property (
        @(posedge clk) ($stable(S) && (S == 2'b11) && $stable(I[3])) |-> $stable(O)
    );
endmodule

