rtl:
module mi_nios_cpu_nios2_oci_fifo_wrptr_inc (
  input ge2_free,
  input ge3_free,
  input [1:0] input_tm_cnt,
  output reg [3:0] fifo_wrptr_inc
);

  always @* begin
    if (ge3_free && (input_tm_cnt == 2'b11))
      fifo_wrptr_inc = 4'b0011;
    else if (ge2_free && (input_tm_cnt >= 2))
      fifo_wrptr_inc = 4'b0010;
    else if (input_tm_cnt >= 1)
      fifo_wrptr_inc = 4'b0001;
    else
      fifo_wrptr_inc = 4'b0000;
  end

endmodule

sva:
module mi_nios_cpu_nios2_oci_fifo_wrptr_inc_sva (
    input logic CLK,                      // sampling clock for assertions
    input logic ge2_free,
    input logic ge3_free,
    input logic [1:0] input_tm_cnt,
    input logic [3:0] fifo_wrptr_inc
);
    // input_tm_cnt==0 maps to 0
    check_cnt0_maps_zero: assert property (
        @(posedge CLK) disable iff (1'b0) (input_tm_cnt == 2'd0) |-> (fifo_wrptr_inc == 4'b0000)
    );

    // input_tm_cnt==1 maps to 1
    check_cnt1_maps_one: assert property (
        @(posedge CLK) disable iff (1'b0) (input_tm_cnt == 2'd1) |-> (fifo_wrptr_inc == 4'b0001)
    );

    // input_tm_cnt==2 with ge2_free maps to 2
    check_cnt2_ge2_maps_two: assert property (
        @(posedge CLK) disable iff (1'b0) ((input_tm_cnt == 2'd2) && ge2_free) |-> (fifo_wrptr_inc == 4'b0010)
    );

    // input_tm_cnt==2 without ge2_free maps to 1
    check_cnt2_no_ge2_maps_one: assert property (
        @(posedge CLK) disable iff (1'b0) ((input_tm_cnt == 2'd2) && !ge2_free) |-> (fifo_wrptr_inc == 4'b0001)
    );

    // input_tm_cnt==3 with ge3_free maps to 3
    check_cnt3_ge3_maps_three: assert property (
        @(posedge CLK) disable iff (1'b0) ((input_tm_cnt == 2'd3) && ge3_free) |-> (fifo_wrptr_inc == 4'b0011)
    );

    // input_tm_cnt==3 without ge3_free but with ge2_free maps to 2
    check_cnt3_no_ge3_ge2_maps_two: assert property (
        @(posedge CLK) disable iff (1'b0) ((input_tm_cnt == 2'd3) && !ge3_free && ge2_free) |-> (fifo_wrptr_inc == 4'b0010)
    );

    // input_tm_cnt==3 without ge3_free and without ge2_free maps to 1
    check_cnt3_no_ge3_no_ge2_maps_one: assert property (
        @(posedge CLK) disable iff (1'b0) ((input_tm_cnt == 2'd3) && !ge3_free && !ge2_free) |-> (fifo_wrptr_inc == 4'b0001)
    );

    // Output encoding limited to 0..3
    check_out_value_domain: assert property (
        @(posedge CLK) disable iff (1'b0) fifo_wrptr_inc inside {4'b0000,4'b0001,4'b0010,4'b0011}
    );

    // If output is 3 then ge3_free and cnt==3 held
    check_out3_implies_ge3_cnt3: assert property (
        @(posedge CLK) disable iff (1'b0) (fifo_wrptr_inc == 4'b0011) |-> (ge3_free && (input_tm_cnt == 2'd3))
    );

    // If output is 2 then ge2_free and cnt>=2 and not (ge3_free && cnt==3)
    check_out2_implies_ge2_and_not_ge3cnt3: assert property (
        @(posedge CLK) disable iff (1'b0) (fifo_wrptr_inc == 4'b0010) |-> (ge2_free && (input_tm_cnt >= 2'd2) && !(ge3_free && (input_tm_cnt == 2'd3)))
    );

    // If output is 1 then cnt>=1 and neither higher-priority condition held
    check_out1_implies_no_higher_conditions: assert property (
        @(posedge CLK) disable iff (1'b0) (fifo_wrptr_inc == 4'b0001) |-> ((input_tm_cnt >= 2'd1) && !(ge3_free && (input_tm_cnt == 2'd3)) && !(ge2_free && (input_tm_cnt >= 2'd2)))
    );

    // If output is 0 then cnt==0
    check_out0_implies_cnt0: assert property (
        @(posedge CLK) disable iff (1'b0) (fifo_wrptr_inc == 4'b0000) |-> (input_tm_cnt == 2'd0)
    );
endmodule

rtl:
module bitwise_logical_mux(
    input [2:0] a,
    input [2:0] b,
    input sel_b1,
    input sel_b2,
    output [2:0] out_or_bitwise,
    output out_or_logical,
    output [5:0] out_not
);

    // Bitwise OR circuit
    wire [2:0] bitwise_or;
    assign bitwise_or = a | b;

    // Logical OR circuit
    wire logical_or;
    assign logical_or = (a[0] || a[1] || a[2]) || (b[0] || b[1] || b[2]);

    // Multiplexer
    wire [2:0] mux_out;
    assign mux_out = sel_b1 ? (sel_b2 ? bitwise_or | logical_or : logical_or) : bitwise_or;

    // Inverse outputs
    assign out_not = {~b, ~a};

    // Outputs
    assign out_or_bitwise = bitwise_or;
    assign out_or_logical = logical_or;

endmodule

sva:
module bitwise_logical_mux_sva (
    input logic [2:0] a,
    input logic [2:0] b,
    input logic sel_b1,
    input logic sel_b2,
    input logic [2:0] out_or_bitwise,
    input logic out_or_logical,
    input logic [5:0] out_not
);
    // Bitwise OR output must equal a | b.
    check_out_or_bitwise_matches_a_or_b: assert property (
        @(posedge a[0] or posedge a[1] or posedge a[2] or
          posedge b[0] or posedge b[1] or posedge b[2] or
          posedge sel_b1 or posedge sel_b2)
        (out_or_bitwise == (a | b))
    );

    // Logical OR output must equal (|a) || (|b).
    check_out_or_logical_matches_reduce_or_of_inputs: assert property (
        @(posedge a[0] or posedge a[1] or posedge a[2] or
          posedge b[0] or posedge b[1] or posedge b[2] or
          posedge sel_b1 or posedge sel_b2)
        (out_or_logical == ((a[0] || a[1] || a[2]) || (b[0] || b[1] || b[2])))
    );

    // Inverted output must equal {~b, ~a}.
    check_out_not_matches_inverse_concat: assert property (
        @(posedge a[0] or posedge a[1] or posedge a[2] or
          posedge b[0] or posedge b[1] or posedge b[2] or
          posedge sel_b1 or posedge sel_b2)
        (out_not == {~b, ~a})
    );

    // Logical OR must equal reduction-OR of the bitwise OR output.
    check_out_or_logical_is_reduction_of_out_or_bitwise: assert property (
        @(posedge a[0] or posedge a[1] or posedge a[2] or
          posedge b[0] or posedge b[1] or posedge b[2] or
          posedge sel_b1 or posedge sel_b2)
        (out_or_logical == (|out_or_bitwise))
    );

    // Outputs must not change if inputs a and b are stable.
    check_outputs_stable_when_inputs_stable: assert property (
        @(posedge a[0] or posedge a[1] or posedge a[2] or
          posedge b[0] or posedge b[1] or posedge b[2] or
          posedge sel_b1 or posedge sel_b2)
        ($stable(a) && $stable(b)) |-> ($stable(out_or_bitwise) && $stable(out_or_logical) && $stable(out_not))
    );

    // Changing sel_b1 alone must not affect outputs.
    check_outputs_unchanged_on_sel_b1_rise_when_inputs_stable: assert property (
        @(posedge sel_b1)
        ($stable(a) && $stable(b)) |-> (out_or_bitwise == $past(out_or_bitwise) &&
                                        out_or_logical == $past(out_or_logical) &&
                                        out_not == $past(out_not))
    );

    // Changing sel_b2 alone must not affect outputs.
    check_outputs_unchanged_on_sel_b2_rise_when_inputs_stable: assert property (
        @(posedge sel_b2)
        ($stable(a) && $stable(b)) |-> (out_or_bitwise == $past(out_or_bitwise) &&
                                        out_or_logical == $past(out_or_logical) &&
                                        out_not == $past(out_not))
    );

    // When both inputs are zero, outputs are zero/zero and inverted all-ones.
    check_zero_inputs_outputs_consistency: assert property (
        @(posedge a[0] or posedge a[1] or posedge a[2] or
          posedge b[0] or posedge b[1] or posedge b[2] or
          posedge sel_b1 or posedge sel_b2)
        ((a == 3'b000) && (b == 3'b000)) |-> (out_or_bitwise == 3'b000 && out_or_logical == 1'b0 && out_not == 6'b111111)
    );

    // If any bit of a or b is 1, logical OR must be 1.
    check_nonzero_inputs_set_logical_or: assert property (
        @(posedge a[0] or posedge a[1] or posedge a[2] or
          posedge b[0] or posedge b[1] or posedge b[2] or
          posedge sel_b1 or posedge sel_b2)
        (((a != 3'b000) || (b != 3'b000)) |-> (out_or_logical == 1'b1))
    );

    // Lower out_not bits must match ~a and upper bits must match ~b.
    check_out_not_bit_mapping: assert property (
        @(posedge a[0] or posedge a[1] or posedge a[2] or
          posedge b[0] or posedge b[1] or posedge b[2] or
          posedge sel_b1 or posedge sel_b2)
        ((out_not[2:0] == ~a) && (out_not[5:3] == ~b))
    );
endmodule

