module top_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input [7:0] d,    // 8-bit input for the register
    output [3:0] counter_out, // 4-bit output from the counter
    output [7:0] register_out, // 8-bit output from the register
    output [7:0] final_out // Sum of the counter and register outputs
);

    wire [3:0] counter_out_wire;
    wire [7:0] register_out_wire;
    wire [7:0] final_out_wire;

    counter_module counter_inst (
        .clk(clk),
        .reset(reset),
        .q(counter_out_wire)
    );

    register_module register_inst (
        .clk(clk),
        .reset(reset),
        .d(d),
        .q(register_out_wire)
    );

    functional_module functional_inst (
        .counter_in(counter_out_wire),
        .register_in(register_out_wire),
        .final_out(final_out_wire)
    );

    assign counter_out = counter_out_wire;
    assign register_out = register_out_wire;
    assign final_out = final_out_wire;

endmodule

module counter_module (
    input clk,
    input reset,
    output reg [3:0] q // 4-bit output
);

    always @(posedge clk) begin
        if (reset) begin
            q <= 4'b0000;
        end else begin
            q <= q + 1;
        end
    end

endmodule

module register_module (
    input clk,
    input reset,
    input [7:0] d,
    output reg [7:0] q // 8-bit output
);

    always @(posedge clk) begin
        if (reset) begin
            q <= 8'h34;
        end else begin
            q <= d;
        end
    end

endmodule

module functional_module (
    input [3:0] counter_in,
    input [7:0] register_in,
    output reg [7:0] final_out // Sum of the counter and register inputs
);

    always @(*) begin
        final_out = counter_in + register_in;
    end

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic reset,            // Synchronous active-high reset
    input logic [7:0] d,
    input logic [3:0] counter_out,
    input logic [7:0] register_out,
    input logic [7:0] final_out
);
    // During reset, outputs reflect reset values and their sum.
    check_reset_values: assert property (
        @(posedge clk) reset |-> (counter_out == 4'd0) && (register_out == 8'h34) && (final_out == 8'h34)
    );

    // final_out equals the sum of register_out and counter_out each cycle.
    check_final_sum_comb: assert property (
        @(posedge clk) final_out == (register_out + counter_out)
    );

    // Counter increments by 1 each cycle when not in or coming out of reset.
    check_counter_increments: assert property (
        @(posedge clk) disable iff (reset) (!$past(reset)) |-> (counter_out == ($past(counter_out) + 4'd1))
    );

    // Counter wraps from 15 to 0 on the next non-reset cycle.
    check_counter_wrap: assert property (
        @(posedge clk) disable iff (reset) (!$past(reset) && ($past(counter_out) == 4'hF)) |-> (counter_out == 4'h0)
    );

    // On the first non-reset cycle after reset, counter advances from its reset value.
    check_counter_after_reset_release: assert property (
        @(posedge clk) disable iff (reset) ($past(reset) && !reset) |-> (counter_out == ($past(counter_out) + 4'd1))
    );

    // Register captures input d on the next cycle when not in or coming out of reset.
    check_register_tracks_d: assert property (
        @(posedge clk) disable iff (reset) (!$past(reset)) |-> (register_out == $past(d))
    );

    // Given sequential updates, final_out equals past d plus incremented past counter_out.
    check_final_from_past: assert property (
        @(posedge clk) disable iff (reset) (!$past(reset)) |-> (final_out == ($past(d) + ($past(counter_out) + 4'd1)))
    );
endmodule

rtl:
module ripple_carry_adder (
    input [2:0] A,
    input [2:0] B,
    input Cin,
    input clk,
    output reg [2:0] S,
    output reg Cout
);

reg [2:0] sum;
reg [2:0] carry;

always @(posedge clk) begin
    sum[0] = A[0] ^ B[0] ^ Cin;
    carry[0] = (A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin);

    sum[1] = A[1] ^ B[1] ^ carry[0];
    carry[1] = (A[1] & B[1]) | (A[1] & carry[0]) | (B[1] & carry[0]);

    sum[2] = A[2] ^ B[2] ^ carry[1];
    Cout = (A[2] & B[2]) | (A[2] & carry[1]) | (B[2] & carry[1]);

    S <= sum;
end

endmodule

sva:
module ripple_carry_adder_sva (
    input logic [2:0] A,
    input logic [2:0] B,
    input logic       Cin,
    input logic       clk,
    input logic [2:0] S,
    input logic       Cout
);
    // Clock: clk (posedge). No reset present in RTL. Sequential datapath: registered 3-bit ripple-carry add.

    // Full 4-bit sum correctness: {Cout,S} equals A + B + Cin.
    check_full_sum: assert property (
        @(posedge clk) {Cout, S} == ({1'b0, A} + {1'b0, B} + Cin)
    );

    // Bit0 sum is XOR of A0, B0, and Cin.
    check_bit0_sum_xor: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0] ^ Cin)
    );

    // Bit1 sum uses carry0 = (A0&B0)|(A0&Cin)|(B0&Cin).
    check_bit1_sum_xor_with_c0: assert property (
        @(posedge clk) S[1] == (A[1] ^ B[1] ^ ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin)))
    );

    // Bit2 sum uses carry1 = (A1&B1)|(A1&carry0)|(B1&carry0).
    check_bit2_sum_xor_with_c1: assert property (
        @(posedge clk) S[2] == (A[2] ^ B[2] ^
            (
                (A[1] & B[1]) |
                (A[1] & ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin))) |
                (B[1] & ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin)))
            )
        )
    );

    // Cout equals (A2&B2)|(A2&carry1)|(B2&carry1).
    check_cout_from_c1: assert property (
        @(posedge clk) Cout ==
            (
                (A[2] & B[2]) |
                (A[2] &
                    (
                        (A[1] & B[1]) |
                        (A[1] & ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin))) |
                        (B[1] & ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin)))
                    )
                ) |
                (B[2] &
                    (
                        (A[1] & B[1]) |
                        (A[1] & ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin))) |
                        (B[1] & ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin)))
                    )
                )
            )
    );

    // If inputs are stable over a cycle, outputs remain stable.
    check_outputs_stable_if_inputs_stable: assert property (
        @(posedge clk) $stable({A, B, Cin}) |-> $stable({S, Cout})
    );

    // If outputs changed over a cycle, at least one input changed.
    check_output_change_requires_input_change: assert property (
        @(posedge clk) $changed({S, Cout}) |-> !$stable({A, B, Cin})
    );

endmodule

