module adder4bit (
  input [3:0] A,
  input [3:0] B,
  input Cin,
  output [3:0] Sum,
  output Cout
);

  wire c1, c2, c3;

  full_adder fa0(.a(A[0]), .b(B[0]), .c(Cin), .s(Sum[0]), .co(c1));
  full_adder fa1(.a(A[1]), .b(B[1]), .c(c1), .s(Sum[1]), .co(c2));
  full_adder fa2(.a(A[2]), .b(B[2]), .c(c2), .s(Sum[2]), .co(c3));
  full_adder fa3(.a(A[3]), .b(B[3]), .c(c3), .s(Sum[3]), .co(Cout));

endmodule

module full_adder (
  input a,
  input b,
  input c,
  output s,
  output co
);

  assign s = a ^ b ^ c;
  assign co = (a & b) | (c & (a ^ b));

endmodule

sva:
module adder4bit_sva (
    input  logic        clk,
    input  logic [3:0]  A,
    input  logic [3:0]  B,
    input  logic        Cin,
    input  logic [3:0]  Sum,
    input  logic        Cout
);
    // Sum/Cout equal the 5-bit unsigned result of A + B + Cin.
    check_total_sum: assert property (
        @(posedge clk) {Cout, Sum} == ({1'b0, A} + {1'b0, B} + Cin)
    );

    // Bit0 sum is XOR of A[0], B[0], and Cin.
    check_sum_bit0: assert property (
        @(posedge clk) Sum[0] == (A[0] ^ B[0] ^ Cin)
    );

    // Bit1 sum equals XOR with carry from bit0.
    check_sum_bit1: assert property (
        @(posedge clk) Sum[1] == (A[1] ^ B[1] ^ ((A[0] & B[0]) | (Cin & (A[0] ^ B[0]))))
    );

    // Bit2 sum equals XOR with carry from bit1.
    check_sum_bit2: assert property (
        @(posedge clk) Sum[2] == (A[2] ^ B[2] ^ (
            (A[1] & B[1]) | ((A[1] ^ B[1]) & ((A[0] & B[0]) | (Cin & (A[0] ^ B[0]))))
        ))
    );

    // Bit3 sum equals XOR with carry from bit2.
    check_sum_bit3: assert property (
        @(posedge clk) Sum[3] == (A[3] ^ B[3] ^ (
            (A[2] & B[2]) | ((A[2] ^ B[2]) &
                ((A[1] & B[1]) | ((A[1] ^ B[1]) & ((A[0] & B[0]) | (Cin & (A[0] ^ B[0])))))
            )
        ))
    );

    // Cout equals carry from bit3.
    check_cout: assert property (
        @(posedge clk) Cout == (
            (A[3] & B[3]) | ((A[3] ^ B[3]) &
                ((A[2] & B[2]) | ((A[2] ^ B[2]) &
                    ((A[1] & B[1]) | ((A[1] ^ B[1]) &
                        ((A[0] & B[0]) | (Cin & (A[0] ^ B[0])))
                    ))
                ))
            )
        )
    );
endmodule

module xor_module_sva (
  input logic clk,
  input logic rst,
  input logic A,
  input logic B,
  input logic Y
);

  ///// Reset behavior /////
  // After any cycle with rst=1, Y must be 0 on the next clock.
  reset_clears_Y_next: assert property (
    @(posedge clk) rst |=> (Y == 1'b0)
  );

  // If the previous cycle was in reset, Y must be 0 now.
  y_zero_if_prev_reset: assert property (
    @(posedge clk) $past(rst) |-> (Y == 1'b0)
  );

  ///// Functional behavior /////
  // When the previous cycle was not in reset, Y equals A^B from the previous cycle.
  y_matches_prev_xor_no_reset: assert property (
    @(posedge clk) disable iff (rst) (!$past(rst)) |-> (Y == ($past(A) ^ $past(B)))
  );

  // If previous inputs differed (and prev cycle not in reset), Y is 1 now.
  y_is_one_when_prev_inputs_differ: assert property (
    @(posedge clk) disable iff (rst) (!$past(rst) && ($past(A) ^ $past(B))) |-> (Y == 1'b1)
  );

  // If previous inputs were equal (and prev cycle not in reset), Y is 0 now.
  y_is_zero_when_prev_inputs_equal: assert property (
    @(posedge clk) disable iff (rst) (!$past(rst) && ($past(A) == $past(B))) |-> (Y == 1'b0)
  );

  // If XOR did not change across two non-reset cycles, Y holds its value next cycle.
  y_holds_if_xor_unchanged: assert property (
    @(posedge clk) disable iff (rst) (!$past(rst) && !rst && (($past(A) ^ $past(B)) == (A ^ B))) |=> (Y == $past(Y))
  );

  // If XOR toggled between two non-reset cycles, Y toggles on the next cycle.
  y_toggles_if_xor_toggled: assert property (
    @(posedge clk) disable iff (rst) (!$past(rst) && !rst && (($past(A) ^ $past(B)) != (A ^ B))) |=> (Y != $past(Y))
  );

  // On the first non-reset cycle after reset deasserts, Y remains 0.
  y_zero_on_reset_release: assert property (
    @(posedge clk) ($past(rst) && !rst) |-> (Y == 1'b0)
  );

endmodule

module counter_3bit_sva (
    input logic clk,
    input logic rst,    // active-high synchronous reset
    input logic en,
    input logic [2:0] count
);
    // Reset high causes count to be zero on the next cycle.
    reset_clears_next: assert property (
        @(posedge clk) rst |=> (count == 3'b000)
    );

    // If reset is held high across cycles, count is zero.
    reset_holds_zero: assert property (
        @(posedge clk) ($past(rst) && rst) |-> (count == 3'b000)
    );

    // With en=1 (and prior cycle out of reset), count increments by 1 next cycle.
    increment_on_en: assert property (
        @(posedge clk) disable iff (rst) (en && $past(!rst)) |=> (count == $past(count) + 3'b001)
    );

    // With en=0 (and prior cycle out of reset), count holds its value next cycle.
    hold_on_disable: assert property (
        @(posedge clk) disable iff (rst) (!en && $past(!rst)) |=> (count == $past(count))
    );

    // Any change in count (without reset) implies en was 1 in the previous cycle.
    change_implies_prev_en: assert property (
        @(posedge clk) disable iff (rst) ($past(!rst) && (count != $past(count))) |-> $past(en)
    );

    // When en=1 and previous count was 7, next count wraps to 0.
    wrap_on_max: assert property (
        @(posedge clk) disable iff (rst) (en && $past(!rst) && ($past(count) == 3'b111)) |=> (count == 3'b000)
    );

    // With en=1, LSB toggles each cycle.
    lsb_toggles_on_en: assert property (
        @(posedge clk) disable iff (rst) (en && $past(!rst)) |=> (count[0] != $past(count[0]))
    );

    // With en=1, bit1 equals prev(bit1) XOR prev(bit0).
    bit1_xor_carry_on_en: assert property (
        @(posedge clk) disable iff (rst) (en && $past(!rst)) |=> (count[1] == ($past(count[1]) ^ $past(count[0])))
    );

    // With en=1, bit2 equals prev(bit2) XOR (prev(bit1)&prev(bit0)).
    bit2_xor_carry_on_en: assert property (
        @(posedge clk) disable iff (rst) (en && $past(!rst)) |=> (count[2] == ($past(count[2]) ^ ($past(count[1]) & $past(count[0]))))
    );

    // Without reset, next count is either unchanged or incremented by 1.
    only_hold_or_inc: assert property (
        @(posedge clk) disable iff (rst) $past(!rst) |-> ((count == $past(count)) || (count == $past(count) + 3'b001))
    );
endmodule

