endmodule

sva:
module logic_gate_sva (
  input logic clk,
  input logic A,
  input logic B,
  input logic C,
  input logic D,
  input logic Y
);
  // Y must equal (A & ~B & C) | D.
  check_functional_equivalence: assert property (
    @(posedge clk) Y == ((A & (~B) & C) | D)
  );

  // D high forces Y high.
  check_D_high_forces_Y_high: assert property (
    @(posedge clk) D |-> (Y == 1'b1)
  );

  // When D is low and A=1,B=0,C=1, Y must be high.
  check_and_true_sets_Y_when_D_low: assert property (
    @(posedge clk) (!D && A && !B && C) |-> (Y == 1'b1)
  );

  // When D is low and B is high, Y must be low.
  check_B_high_blocks_when_D_low: assert property (
    @(posedge clk) (!D && B) |-> (Y == 1'b0)
  );

  // When D is low and A is low, Y must be low.
  check_A_low_blocks_when_D_low: assert property (
    @(posedge clk) (!D && !A) |-> (Y == 1'b0)
  );

  // When D is low and C is low, Y must be low.
  check_C_low_blocks_when_D_low: assert property (
    @(posedge clk) (!D && !C) |-> (Y == 1'b0)
  );

  // If Y is high while D is low, A=1,B=0,C=1 must hold.
  check_Y_high_requires_inputs_when_D_low: assert property (
    @(posedge clk) (Y && !D) |-> (A && !B && C)
  );

  // If Y is low while D is low, at least one of A=0, B=1, or C=0 holds.
  check_Y_low_implies_one_input_blocks_when_D_low: assert property (
    @(posedge clk) (!Y && !D) |-> ((!A) || B || (!C))
  );
endmodule

rtl:
module bitwise_operations(
    input [0:7] in,
    output B1,
    B2,
    B3,
    B4,
    B5,
    B6,
    B7,
    B8,
    B9,
    B10
);

  assign B1  = in[0] & in[1];
  assign B2  = in[0] | in[1];
  assign B3  = ~(in[0] & in[1]);
  assign B4  = ~(in[0] | in[1]);
  assign B5  = in[0] ^ in[1];
  assign B6  = ~(in[0] ^ in[1]);
  assign B7  = ~in[0];
  assign B8  = in[0];
  assign B9  = (in[0] & in[1]) && (in[2] & in[3]);
  assign B10 = (in[0] & in[1]) || (in[2] & in[3]);

endmodule

sva:
module bitwise_operations_sva (
    input logic [0:7] in,
    input logic B1,
    input logic B2,
    input logic B3,
    input logic B4,
    input logic B5,
    input logic B6,
    input logic B7,
    input logic B8,
    input logic B9,
    input logic B10
);
    // No clock/reset in RTL; pure combinational; sample on global formal clock.

    // B1 equals in[0] & in[1].
    check_B1_and: assert property (
        @(posedge $global_clock) B1 === (in[0] & in[1])
    );

    // B2 equals in[0] | in[1].
    check_B2_or: assert property (
        @(posedge $global_clock) B2 === (in[0] | in[1])
    );

    // B3 equals ~(in[0] & in[1]) (NAND).
    check_B3_nand: assert property (
        @(posedge $global_clock) B3 === ~(in[0] & in[1])
    );

    // B4 equals ~(in[0] | in[1]) (NOR).
    check_B4_nor: assert property (
        @(posedge $global_clock) B4 === ~(in[0] | in[1])
    );

    // B5 equals in[0] ^ in[1] (XOR).
    check_B5_xor: assert property (
        @(posedge $global_clock) B5 === (in[0] ^ in[1])
    );

    // B6 equals ~(in[0] ^ in[1]) (XNOR).
    check_B6_xnor: assert property (
        @(posedge $global_clock) B6 === ~(in[0] ^ in[1])
    );

    // B7 equals ~in[0].
    check_B7_not_in0: assert property (
        @(posedge $global_clock) B7 === ~in[0]
    );

    // B8 equals in[0].
    check_B8_buf_in0: assert property (
        @(posedge $global_clock) B8 === in[0]
    );

    // B9 equals (in[0]&in[1]) && (in[2]&in[3]).
    check_B9_logical_and_pairs: assert property (
        @(posedge $global_clock) B9 === ((in[0] & in[1]) && (in[2] & in[3]))
    );

    // B10 equals (in[0]&in[1]) || (in[2]&in[3]).
    check_B10_logical_or_pairs: assert property (
        @(posedge $global_clock) B10 === ((in[0] & in[1]) || (in[2] & in[3]))
    );

endmodule

rtl:
module four_bit_decoder(
    input [3:0] in,
    output reg [1:0] out
);

always @*
begin
    case(in)
        4'b0000 : out = 2'b00;
        4'b0001 : out = 2'b00;
        4'b0010 : out = 2'b00;
        4'b0011 : out = 2'b00;
        4'b0100 : out = 2'b00;
        4'b0101 : out = 2'b01;
        4'b0110 : out = 2'b01;
        4'b0111 : out = 2'b01;
        4'b1000 : out = 2'b01;
        4'b1001 : out = 2'b10;
        4'b1010 : out = 2'b10;
        4'b1011 : out = 2'b10;
        default : out = 2'b11;
    endcase
end

endmodule

sva:
module four_bit_decoder_sva (
    input logic clk,
    input logic [3:0] in,
    input logic [1:0] out
);

    // Out is always a known 2-bit value.
    check_out_known: assert property (
        @(posedge clk) disable iff (1'b0) !$isunknown(out)
    );

    // Inputs 0..4 map to 00.
    check_map_00_forward: assert property (
        @(posedge clk) disable iff (1'b0) (in inside {[4'd0:4'd4]}) |-> (out == 2'b00)
    );

    // Inputs 5..8 map to 01.
    check_map_01_forward: assert property (
        @(posedge clk) disable iff (1'b0) (in inside {[4'd5:4'd8]}) |-> (out == 2'b01)
    );

    // Inputs 9..11 map to 10.
    check_map_10_forward: assert property (
        @(posedge clk) disable iff (1'b0) (in inside {[4'd9:4'd11]}) |-> (out == 2'b10)
    );

    // Inputs 12..15 map to 11.
    check_map_11_forward: assert property (
        @(posedge clk) disable iff (1'b0) (in inside {[4'd12:4'd15]}) |-> (out == 2'b11)
    );

    // Out 00 only occurs for inputs 0..4.
    check_map_00_reverse: assert property (
        @(posedge clk) disable iff (1'b0) (out == 2'b00) |-> (in inside {[4'd0:4'd4]})
    );

    // Out 01 only occurs for inputs 5..8.
    check_map_01_reverse: assert property (
        @(posedge clk) disable iff (1'b0) (out == 2'b01) |-> (in inside {[4'd5:4'd8]})
    );

    // Out 10 only occurs for inputs 9..11.
    check_map_10_reverse: assert property (
        @(posedge clk) disable iff (1'b0) (out == 2'b10) |-> (in inside {[4'd9:4'd11]})
    );

    // Out 11 only occurs for inputs 12..15.
    check_map_11_reverse: assert property (
        @(posedge clk) disable iff (1'b0) (out == 2'b11) |-> (in inside {[4'd12:4'd15]})
    );

    // If input is stable, output is stable (purely combinational function).
    check_stability_with_stable_input: assert property (
        @(posedge clk) disable iff (1'b0) $stable(in) |-> $stable(out)
    );

endmodule

rtl:
module twos_complement(
    input [3:0] in,
    output reg [3:0] out
);

always @(*) begin
    out = ~in + 1;
end

endmodule

sva:
module twos_complement_sva (
    input logic [3:0] in,
    input logic [3:0] out
);
    ///// Functional equivalence /////
    // out equals bitwise-not of in plus 1 (two's complement).
    check_twos_complement_equivalence: assert property (
        @(posedge in[0] or negedge in[0] or posedge in[1] or negedge in[1] or posedge in[2] or negedge in[2] or posedge in[3] or negedge in[3])
        out == (~in + 4'd1)
    );

    // The 4-bit sum of in and out wraps to zero (modulo-16).
    check_sum_wraps_to_zero: assert property (
        @(posedge in[0] or negedge in[0] or posedge in[1] or negedge in[1] or posedge in[2] or negedge in[2] or posedge in[3] or negedge in[3])
        (in + out) == 4'd0
    );

    // Two's complement is involutive: complement of out == in.
    check_involution: assert property (
        @(posedge in[0] or negedge in[0] or posedge in[1] or negedge in[1] or posedge in[2] or negedge in[2] or posedge in[3] or negedge in[3])
        ((~out) + 4'd1) == in
    );

    ///// Corner cases /////
    // Zero maps to zero.
    check_zero_maps_to_zero: assert property (
        @(posedge in[0] or negedge in[0] or posedge in[1] or negedge in[1] or posedge in[2] or negedge in[2] or posedge in[3] or negedge in[3])
        (in == 4'd0) |-> (out == 4'd0)
    );

    // If out is zero, input must have been zero.
    check_only_zero_maps_to_zero: assert property (
        @(posedge in[0] or negedge in[0] or posedge in[1] or negedge in[1] or posedge in[2] or negedge in[2] or posedge in[3] or negedge in[3])
        (out == 4'd0) |-> (in == 4'd0)
    );

    // Minimum 4-bit two's-complement value (8) maps to itself.
    check_min_neg_self_inverse: assert property (
        @(posedge in[0] or negedge in[0] or posedge in[1] or negedge in[1] or posedge in[2] or negedge in[2] or posedge in[3] or negedge in[3])
        (in == 4'h8) |-> (out == 4'h8)
    );

    // out equals in only for fixed points 0 or 8.
    check_only_fixed_points_equal: assert property (
        @(posedge in[0] or negedge in[0] or posedge in[1] or negedge in[1] or posedge in[2] or negedge in[2] or posedge in[3] or negedge in[3])
        (out == in) |-> ((in == 4'h0) || (in == 4'h8))
    );
endmodule

rtl:
module bit_converter(
    input [3:0] in,
    output [1:0] out
);

    assign out = (in < 5) ? 2'b00 : (in < 9) ? 2'b01 : (in < 11) ? 2'b10 : 2'b11;

endmodule

sva:
module bit_converter_sva (
    input logic CLK,
    input logic [3:0] in,
    input logic [1:0] out
);
    // Out must equal the RTL ternary expression for all inputs.
    check_function_equivalence: assert property (
        @(posedge CLK) out == ((in < 4'd5) ? 2'b00 :
                               (in < 4'd9) ? 2'b01 :
                               (in < 4'd11) ? 2'b10 : 2'b11)
    );

    // For in=0..4, out must be 00.
    check_out_for_in_lt_5: assert property (
        @(posedge CLK) (in < 4'd5) |-> (out == 2'b00)
    );

    // For in=5..8, out must be 01.
    check_out_for_5_to_8: assert property (
        @(posedge CLK) (in >= 4'd5 && in < 4'd9) |-> (out == 2'b01)
    );

    // For in=9..10, out must be 10.
    check_out_for_9_to_10: assert property (
        @(posedge CLK) (in >= 4'd9 && in < 4'd11) |-> (out == 2'b10)
    );

    // For in=11..15, out must be 11.
    check_out_for_11_to_15: assert property (
        @(posedge CLK) (in >= 4'd11) |-> (out == 2'b11)
    );

    // If out is 00, in must be 0..4.
    check_in_range_when_out_00: assert property (
        @(posedge CLK) (out == 2'b00) |-> (in < 4'd5)
    );

    // If out is 01, in must be 5..8.
    check_in_range_when_out_01: assert property (
        @(posedge CLK) (out == 2'b01) |-> (in >= 4'd5 && in < 4'd9)
    );

    // If out is 10, in must be 9..10.
    check_in_range_when_out_10: assert property (
        @(posedge CLK) (out == 2'b10) |-> (in >= 4'd9 && in < 4'd11)
    );

    // If out is 11, in must be 11..15.
    check_in_range_when_out_11: assert property (
        @(posedge CLK) (out == 2'b11) |-> (in >= 4'd11)
    );

    // If input is stable across cycles, output must be stable.
    check_stability: assert property (
        @(posedge CLK) $stable(in) |-> $stable(out)
    );
endmodule

rtl:
module prcfg_dac(

  clk,

  control,
  status,

  src_dac_enable,
  src_dac_data,
  src_dac_valid,

  dst_dac_enable,
  dst_dac_data,
  dst_dac_valid
);

  localparam  RP_ID       = 8'hA0;
  parameter   CHANNEL_ID  = 0;

  input             clk;

  input   [31:0]    control;
  output  [31:0]    status;

  output            src_dac_enable;
  input   [15:0]    src_dac_data;
  output            src_dac_valid;

  input             dst_dac_enable;
  output  [15:0]    dst_dac_data;
  input             dst_dac_valid;

  reg               src_dac_enable;
  reg               src_dac_valid;
  reg     [15:0]    dst_dac_data;

  assign status = {24'h0, RP_ID};

  always @(posedge clk) begin
    src_dac_enable  <= dst_dac_enable;
    dst_dac_data    <= src_dac_data;
    src_dac_valid   <= dst_dac_valid;
  end
endmodule

sva:
module prcfg_dac_sva(

  input logic             clk,

  input logic [31:0]      control,
  input logic [31:0]      status,

  input logic             src_dac_enable,
  input logic [15:0]      src_dac_data,
  input logic             src_dac_valid,

  input logic             dst_dac_enable,
  input logic [15:0]      dst_dac_data,
  input logic             dst_dac_valid
);

    ///// Constant status /////
    // status is hardwired to 32'h000000A0.
    check_status_constant_value: assert property (
        @(posedge clk) status == 32'h000000A0
    );

    // status remains stable over time.
    check_status_stable_over_time: assert property (
        @(posedge clk) disable iff ($initstate) status == $past(status)
    );

    ///// Registered pass-throughs /////
    // src_dac_enable is the registered copy of dst_dac_enable.
    check_src_enable_registered_from_dst_enable: assert property (
        @(posedge clk) disable iff ($initstate) src_dac_enable == $past(dst_dac_enable)
    );

    // src_dac_valid is the registered copy of dst_dac_valid.
    check_src_valid_registered_from_dst_valid: assert property (
        @(posedge clk) disable iff ($initstate) src_dac_valid == $past(dst_dac_valid)
    );

    // dst_dac_data is the registered copy of src_dac_data.
    check_dst_data_registered_from_src_data: assert property (
        @(posedge clk) disable iff ($initstate) dst_dac_data == $past(src_dac_data)
    );

    ///// Stability propagation /////
    // If dst_dac_enable was stable over the last two cycles, src_dac_enable is stable this cycle.
    check_src_enable_stable_when_dst_enable_stable: assert property (
        @(posedge clk) disable iff ($initstate) ($past(dst_dac_enable) == $past(dst_dac_enable,2)) |-> (src_dac_enable == $past(src_dac_enable))
    );

    // If dst_dac_valid was stable over the last two cycles, src_dac_valid is stable this cycle.
    check_src_valid_stable_when_dst_valid_stable: assert property (
        @(posedge clk) disable iff ($initstate) ($past(dst_dac_valid) == $past(dst_dac_valid,2)) |-> (src_dac_valid == $past(src_dac_valid))
    );

    // If src_dac_data was stable over the last two cycles, dst_dac_data is stable this cycle.
    check_dst_data_stable_when_src_data_stable: assert property (
        @(posedge clk) disable iff ($initstate) ($past(src_dac_data) == $past(src_dac_data,2)) |-> (dst_dac_data == $past(dst_dac_data))
    );

endmodule

rtl:
module top_module( 
    input [255:0] in,
    input [7:0] sel,
    output out );

    wire [7:0] decoder_out;
    wire [1:0] mux2_out;

    // Decoder
    decoder dec1(
        .in(sel),
        .out(decoder_out)
    );

    // 2-to-1 Mux
    mux2 mux2_1(
        .in0(in[decoder_out]),
        .in1(in[decoder_out + 1]),
        .sel(sel[0]),
        .out(mux2_out)
    );

    // Final Mux
    assign out = mux2_out[sel[0]];

endmodule

// Decoder
module decoder(
    input [7:0] in,
    output reg [7:0] out
);
    always @ (in) begin
        case (in)
            8'b00000001: out = 8'b00000001;
            8'b00000010: out = 8'b00000010;
            8'b00000100: out = 8'b00000100;
            8'b00001000: out = 8'b00001000;
            8'b00010000: out = 8'b00010000;
            8'b00100000: out = 8'b00100000;
            8'b01000000: out = 8'b01000000;
            8'b10000000: out = 8'b10000000;
            default: out = 8'b00000000;
        endcase
    end
endmodule

// 2-to-1 Mux
module mux2(
    input in0,
    input in1,
    input sel,
    output reg [1:0] out
);
    always @ (in0, in1, sel) begin
        case (sel)
            1'b0: out = {in1, in1};
            1'b1: out = {in0, in0};
            default: out = {in0, in0};
        endcase
    end
endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic [255:0] in,
    input logic [7:0] sel,
    input logic out,

    // Internal signals from DUT (bind hierarchically)
    input logic [7:0] decoder_out,
    input logic [1:0] mux2_out
);

    ///// Decoder checks /////
    // Decoder outputs sel when sel is one-hot.
    decoder_matches_onehot_sel: assert property (
        @(posedge clk) $onehot(sel) |-> (decoder_out == sel)
    );

    // Decoder outputs 0 when sel is not one-hot.
    decoder_zero_when_not_onehot: assert property (
        @(posedge clk) !$onehot(sel) |-> (decoder_out == 8'b0)
    );

    // Decoder output is always one-hot or zero.
    decoder_out_onehot0: assert property (
        @(posedge clk) $onehot0(decoder_out)
    );

    ///// mux2 checks /////
    // When sel[0]==0, mux2_out replicates in[decoder_out + 1].
    mux2_sel0_replication: assert property (
        @(posedge clk) (sel[0] == 1'b0) |-> (mux2_out == {in[decoder_out + 1], in[decoder_out + 1]})
    );

    // When sel[0]==1, mux2_out replicates in[decoder_out].
    mux2_sel1_replication: assert property (
        @(posedge clk) (sel[0] == 1'b1) |-> (mux2_out == {in[decoder_out], in[decoder_out]})
    );

    // mux2_out bits are always identical.
    mux2_bits_identical: assert property (
        @(posedge clk) (mux2_out[1] == mux2_out[0])
    );

    ///// Final mux checks /////
    // Final mux selects mux2_out bit indexed by sel[0].
    final_mux_select: assert property (
        @(posedge clk) (out == mux2_out[sel[0]])
    );

    // End-to-end: out equals selected input bit.
    end_to_end_out_value: assert property (
        @(posedge clk) out == (sel[0] ? in[decoder_out] : in[decoder_out + 1])
    );

    // When sel[0]==0, out equals in[decoder_out + 1].
    end_to_end_sel0: assert property (
        @(posedge clk) (sel[0] == 1'b0) |-> (out == in[decoder_out + 1])
    );

    // When sel[0]==1, out equals in[decoder_out].
    end_to_end_sel1: assert property (
        @(posedge clk) (sel[0] == 1'b1) |-> (out == in[decoder_out])
    );

endmodule

rtl:
module mux6to1_pipeline (
    input [2:0] sel,
    input [3:0] data0,
    input [3:0] data1,
    input [3:0] data2,
    input [3:0] data3,
    input [3:0] data4,
    input [3:0] data5,
    output [3:0] out
);

reg [3:0] stage1_out;
reg [3:0] stage2_out;
reg [3:0] stage3_out;

always @(*) begin
    case(sel)
        3'b000: stage1_out = data0;
        3'b001: stage1_out = data1;
        3'b010: stage1_out = data2;
        3'b011: stage1_out = data3;
        3'b100: stage1_out = data4;
        3'b101: stage1_out = data5;
        default: stage1_out = {data5[3], data5[3], data5[3], data5[3]};
    endcase
end

always @(*) begin
    case(sel)
        3'b000: stage2_out = stage1_out;
        3'b001: stage2_out = stage1_out;
        3'b010: stage2_out = stage1_out;
        3'b011: stage2_out = stage1_out;
        3'b100: stage2_out = stage1_out;
        3'b101: stage2_out = stage1_out;
        default: stage2_out = {stage1_out[3], stage1_out[3], stage1_out[3], stage1_out[3]};
    endcase
end

always @(*) begin
    case(sel)
        3'b000: stage3_out = stage2_out;
        3'b001: stage3_out = stage2_out;
        3'b010: stage3_out = stage2_out;
        3'b011: stage3_out = stage2_out;
        3'b100: stage3_out = stage2_out;
        3'b101: stage3_out = stage2_out;
        default: stage3_out = {stage2_out[3], stage2_out[3], stage2_out[3], stage2_out[3]};
    endcase
end

assign out = stage3_out;

endmodule

sva:
module mux6to1_pipeline_sva (
    input logic CLK,
    input logic [2:0] sel,
    input logic [3:0] data0,
    input logic [3:0] data1,
    input logic [3:0] data2,
    input logic [3:0] data3,
    input logic [3:0] data4,
    input logic [3:0] data5,
    input logic [3:0] out
);
    // When sel==000, out equals data0.
    check_sel_000_maps_to_data0: assert property (
        @(posedge CLK) (sel == 3'b000) |-> (out == data0)
    );

    // When sel==001, out equals data1.
    check_sel_001_maps_to_data1: assert property (
        @(posedge CLK) (sel == 3'b001) |-> (out == data1)
    );

    // When sel==010, out equals data2.
    check_sel_010_maps_to_data2: assert property (
        @(posedge CLK) (sel == 3'b010) |-> (out == data2)
    );

    // When sel==011, out equals data3.
    check_sel_011_maps_to_data3: assert property (
        @(posedge CLK) (sel == 3'b011) |-> (out == data3)
    );

    // When sel==100, out equals data4.
    check_sel_100_maps_to_data4: assert property (
        @(posedge CLK) (sel == 3'b100) |-> (out == data4)
    );

    // When sel==101, out equals data5.
    check_sel_101_maps_to_data5: assert property (
        @(posedge CLK) (sel == 3'b101) |-> (out == data5)
    );

    // When sel==110, out replicates data5[3] on all bits.
    check_sel_110_default_replication: assert property (
        @(posedge CLK) (sel == 3'b110) |-> (out == {4{data5[3]}})
    );

    // When sel==111, out replicates data5[3] on all bits.
    check_sel_111_default_replication: assert property (
        @(posedge CLK) (sel == 3'b111) |-> (out == {4{data5[3]}})
    );

    // Out implements the mux function including default replication.
    check_mux_function_full: assert property (
        @(posedge CLK)
        out == ((sel == 3'b000) ? data0 :
                (sel == 3'b001) ? data1 :
                (sel == 3'b010) ? data2 :
                (sel == 3'b011) ? data3 :
                (sel == 3'b100) ? data4 :
                (sel == 3'b101) ? data5 :
                                  {4{data5[3]}})
    );

    // If sel and inputs are stable, out is stable across cycles.
    check_stability_when_inputs_stable: assert property (
        @(posedge CLK) $stable({sel, data0, data1, data2, data3, data4, data5}) |-> $stable(out)
    );
endmodule

module simple_calculator_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic       op,
    input logic [3:0] Z
);

    // Z implements add/sub based on op (sampled on posedge of A[0]).
    check_func_on_posedge_a0: assert property (
        @(posedge A[0]) Z == ((op ? (A - B) : (A + B)) & 4'hF)
    );

    // Z implements add/sub based on op (sampled on posedge of A[1]).
    check_func_on_posedge_a1: assert property (
        @(posedge A[1]) Z == ((op ? (A - B) : (A + B)) & 4'hF)
    );

    // Z implements add/sub based on op (sampled on posedge of A[2]).
    check_func_on_posedge_a2: assert property (
        @(posedge A[2]) Z == ((op ? (A - B) : (A + B)) & 4'hF)
    );

    // Z implements add/sub based on op (sampled on posedge of B[0]).
    check_func_on_posedge_b0: assert property (
        @(posedge B[0]) Z == ((op ? (A - B) : (A + B)) & 4'hF)
    );

    // Z implements add/sub based on op (sampled on posedge of B[1]).
    check_func_on_posedge_b1: assert property (
        @(posedge B[1]) Z == ((op ? (A - B) : (A + B)) & 4'hF)
    );

    // Z implements add/sub based on op (sampled on posedge of op).
    check_func_on_posedge_op: assert property (
        @(posedge op) Z == ((op ? (A - B) : (A + B)) & 4'hF)
    );

    // When op==0 and B==0, Z equals A (sampled on posedge of A[0]).
    add_identity_b_zero: assert property (
        @(posedge A[0]) (op == 1'b0) && (B == 4'h0) |-> (Z == A)
    );

    // When op==1 and B==0, Z equals A (sampled on posedge of A[0]).
    sub_identity_b_zero: assert property (
        @(posedge A[0]) (op == 1'b1) && (B == 4'h0) |-> (Z == A)
    );

    // When op==0 and A==0, Z equals B (sampled on posedge of B[0]).
    add_identity_a_zero: assert property (
        @(posedge B[0]) (op == 1'b0) && (A == 4'h0) |-> (Z == B)
    );

    // When op==1 and A==B, Z is zero (sampled on posedge of A[0]).
    sub_equal_operands_zero: assert property (
        @(posedge A[0]) (op == 1'b1) && (A == B) |-> (Z == 4'h0)
    );

    // Addition is commutative when op==0 (sampled on posedge of A[3]).
    add_commutes: assert property (
        @(posedge A[3]) (op == 1'b0) |-> (Z == ((B + A) & 4'hF))
    );

endmodule

rtl:
module full_adder(
    input a,
    input b,
    input c_in,
    output sum,
    output c_out
);

    assign {c_out, sum} = a + b + c_in;

endmodule

module combinational_circuit(
    input [3:0] in,
    output out_and,
    output out_or,
    output out_xor
);

    assign out_and = in[0] & in[1] & in[2] & in[3];
    assign out_or = in[0] | in[1] | in[2] | in[3];
    assign out_xor = in[0] ^ in[1] ^ in[2] ^ in[3];

endmodule

module functional_module(
    input a, b, c_in,
    input [3:0] in,
    output c_out,
    output sum,
    output out_and,
    output out_or,
    output out_xor
);

    wire full_adder_sum;
    wire full_adder_c_out;

    combinational_circuit cc(
        .in(in),
        .out_and(out_and),
        .out_or(out_or),
        .out_xor(out_xor)
    );

    full_adder fa(
        .a(a),
        .b(b),
        .c_in(c_in),
        .sum(full_adder_sum),
        .c_out(full_adder_c_out)
    );

    assign sum = full_adder_sum;

    assign c_out = (full_adder_sum & out_xor) ? 1'b0 : full_adder_c_out;

endmodule

sva:
module functional_module_sva (
    input logic clk,            // External sampling clock (RTL is purely combinational)
    input logic a, b, c_in,
    input logic [3:0] in,
    input logic c_out,
    input logic sum,
    input logic out_and,
    input logic out_or,
    input logic out_xor
);
    // sum must be XOR of a, b, c_in per full_adder.
    check_sum_is_xor: assert property (
        @(posedge clk) disable iff (1'b0) sum == (a ^ b ^ c_in)
    );

    // out_and is the AND of all in bits.
    check_out_and_def: assert property (
        @(posedge clk) disable iff (1'b0) out_and == (&in)
    );

    // out_or is the OR of all in bits.
    check_out_or_def: assert property (
        @(posedge clk) disable iff (1'b0) out_or == (|in)
    );

    // out_xor is the XOR of all in bits.
    check_out_xor_def: assert property (
        @(posedge clk) disable iff (1'b0) out_xor == (^in)
    );

    // c_out equals muxed carry: 0 when (sum & out_xor), else full_adder carry.
    check_cout_muxing: assert property (
        @(posedge clk) disable iff (1'b0)
            c_out == ( (sum & out_xor) ? 1'b0 : ((a & b) | (a & c_in) | (b & c_in)) )
    );

    // When (sum & out_xor) is true, c_out must be 0.
    check_cout_forced_low: assert property (
        @(posedge clk) disable iff (1'b0)
            (sum & out_xor) |-> (c_out == 1'b0)
    );

    // When (sum & out_xor) is false, c_out equals the full_adder carry.
    check_cout_equals_carry_when_not_forced: assert property (
        @(posedge clk) disable iff (1'b0)
            !(sum & out_xor) |-> (c_out == ((a & b) | (a & c_in) | (b & c_in)))
    );

    // If out_and is 1 (all inputs are 1), out_or must be 1.
    check_and_implies_or: assert property (
        @(posedge clk) disable iff (1'b0) out_and |-> out_or
    );

    // If out_or is 0, all inputs must be 0.
    check_or_zero_means_all_zero: assert property (
        @(posedge clk) disable iff (1'b0) (out_or == 1'b0) |-> (in == 4'b0000)
    );

    // If out_and is 1, all inputs must be 1.
    check_and_one_means_all_one: assert property (
        @(posedge clk) disable iff (1'b0) (out_and == 1'b1) |-> (in == 4'b1111)
    );

    // If all inputs are 1, parity over four ones is 0, so out_xor must be 0.
    check_and_implies_xor_zero: assert property (
        @(posedge clk) disable iff (1'b0) out_and |-> (out_xor == 1'b0)
    );
endmodule

