sva:
module nor4_sva (
    input logic CLK,
    input logic a,
    input logic b,
    input logic c,
    input logic d,
    input logic y,
    input logic ab, // internal net in nor4
    input logic cd  // internal net in nor4
);
    // ab must be NOR of a and b
    check_ab_is_nor2: assert property (
        @(posedge CLK) ab == ~(a | b)
    );

    // cd must be NOR of c and d
    check_cd_is_nor2: assert property (
        @(posedge CLK) cd == ~(c | d)
    );

    // y must be NOR of ab and cd
    check_y_is_nor2_of_ab_cd: assert property (
        @(posedge CLK) y == ~(ab | cd)
    );

    // y must equal (a|b)&(c|d)
    check_y_equals_and_of_ors: assert property (
        @(posedge CLK) y == ((a | b) & (c | d))
    );

    // If a and b are both 0, y must be 0
    check_y_zero_if_a_b_both_zero: assert property (
        @(posedge CLK) (!a && !b) |-> (y == 1'b0)
    );

    // If c and d are both 0, y must be 0
    check_y_zero_if_c_d_both_zero: assert property (
        @(posedge CLK) (!c && !d) |-> (y == 1'b0)
    );

    // If at least one of a/b and one of c/d are 1, y must be 1
    check_y_one_if_each_pair_has_one: assert property (
        @(posedge CLK) (((a | b) & (c | d)) == 1'b1) |-> (y == 1'b1)
    );

    // If y is 1 then ab and cd must both be 0
    check_y_high_implies_ab_cd_low: assert property (
        @(posedge CLK) (y == 1'b1) |-> ((ab == 1'b0) && (cd == 1'b0))
    );

    // If y is 0 then either ab or cd must be 1
    check_y_low_implies_ab_or_cd_high: assert property (
        @(posedge CLK) (y == 1'b0) |-> ((ab == 1'b1) || (cd == 1'b1))
    );

    // y can change only if at least one input changes
    check_y_changes_only_with_inputs: assert property (
        @(posedge CLK) $changed(y) |-> $changed({a,b,c,d})
    );
endmodule

rtl:
module shift_and_or(input wire clk, input wire [31:0] in, output wire out);

   // Double-width register to store the concatenation of 'd' and 'in'
   reg [63:0] d_reg;

   // Always-FF block to update the register on the rising edge of the clock
   always @(posedge clk) begin
      d_reg <= {d_reg[31:0], in[0] ? in : 32'b0};
   end

   // Wire to store the result of the OR operation on the lower 39 bits of 'd_reg'
   wire tmp0 = |d_reg[38:0];

   // Final assignment of the output based on the OR operation results
   assign out = d_reg[39] | tmp0;

endmodule

sva:
module shift_and_or_sva (
    input logic clk,
    input logic [31:0] in,
    input logic out,
    input logic [63:0] d_reg
);
    // Clock: clk (posedge). No reset present.
    // Mixed logic: sequential d_reg update; combinational out from d_reg.
    // Behavior: d_reg <= {d_reg[31:0], in[0] ? in : 32'b0}; out == |d_reg[39:0] == in[0] | $past(in[0]).

    ///// Output behavior /////
    // out equals OR of current and previous in[0].
    check_out_depends_on_in0_two_cycles: assert property (
        @(posedge clk) $past(1'b1) |-> (out == (in[0] | $past(in[0])))
    );

    // If current in[0] is HIGH, out must be HIGH in the same cycle.
    check_out_high_when_curr_in0_high: assert property (
        @(posedge clk) in[0] |-> (out == 1'b1)
    );

    // If previous in[0] was HIGH, out must be HIGH this cycle.
    check_out_high_when_prev_in0_high: assert property (
        @(posedge clk) ($past(1'b1) && $past(in[0])) |-> (out == 1'b1)
    );

    // If current and previous in[0] are both LOW, out must be LOW.
    check_out_low_when_two_consec_in0_low: assert property (
        @(posedge clk) ($past(1'b1) && !in[0] && !$past(in[0])) |-> (out == 1'b0)
    );

    // If out is LOW, then both current and previous in[0] are LOW.
    check_out_low_implies_two_consec_in0_low: assert property (
        @(posedge clk) ($past(1'b1) && (out == 1'b0)) |-> (!in[0] && !$past(in[0]))
    );

    // If previous out was LOW, out now equals current in[0].
    check_out_equals_in0_when_prev_out_low: assert property (
        @(posedge clk) ($past(1'b1) && ($past(out) == 1'b0)) |-> (out == in[0])
    );

    ///// Register update behavior /////
    // d_reg next state matches {past lower 32, (in[0]? in : 0)}.
    check_dreg_next_state_update: assert property (
        @(posedge clk) $past(1'b1) |-> (d_reg == { $past(d_reg[31:0]), (in[0] ? in : 32'b0) })
    );

    // Upper 32 bits shift from the previous lower 32 bits.
    check_dreg_upper32_shift: assert property (
        @(posedge clk) $past(1'b1) |-> (d_reg[63:32] == $past(d_reg[31:0]))
    );

    // When in[0] is HIGH, lower 32 bits load 'in'.
    check_dreg_lower32_load_on_in0_high: assert property (
        @(posedge clk) in[0] |-> (d_reg[31:0] == in)
    );

    // When in[0] is LOW, lower 32 bits clear to zero.
    check_dreg_lower32_clear_on_in0_low: assert property (
        @(posedge clk) !in[0] |-> (d_reg[31:0] == 32'b0)
    );

    ///// Combinational mapping /////
    // out equals OR-reduction of d_reg[39:0].
    check_out_equals_or_of_dreg_lower40: assert property (
        @(posedge clk) (out == (|d_reg[39:0]))
    );

endmodule

rtl:
module arithmetic_right_shift (
    input clk,
    input reset,
    input [3:0] A,
    input [1:0] shift_amount,
    output reg [3:0] Q
);

always @(posedge clk, negedge reset) begin
    if (!reset) begin
        Q <= 4'b0000;
    end else begin
        case (shift_amount)
            2'b00: Q <= A;
            2'b01: Q <= {A[2:0], A[3]};
            2'b10: Q <= {A[3], A[3:1]};
            2'b11: Q <= {A[2:0], A[3]};
        endcase
    end
end

endmodule

module barrel_shifter (
    input clk,
    input reset,
    input [3:0] A,
    input [1:0] shift,
    input [3:0] shift_data,
    output reg [3:0] Q
);

always @(posedge clk, negedge reset) begin
    if (!reset) begin
        Q <= 4'b0000;
    end else begin
        case (shift)
            2'b00: Q <= A;
            2'b01: Q <= {A[2:0], shift_data[3]};
            2'b10: Q <= {shift_data[0], A[3:1]};
            2'b11: Q <= {A[2:0], A[3]};
        endcase
    end
end

endmodule

module functional_module (
    input [3:0] shift_output,
    input [3:0] barrel_output,
    output wire [3:0] result
);

assign result = shift_output + barrel_output;

endmodule

module top_module (
    input clk,
    input reset,
    input [3:0] A,
    input [1:0] shift,
    input [1:0] shift_amount,
    input select,
    output [3:0] Q
);

wire [3:0] shift_output;
wire [3:0] barrel_output;
wire [3:0] result;

arithmetic_right_shift ars (
    .clk(clk),
    .reset(reset),
    .A(A),
    .shift_amount(shift_amount),
    .Q(shift_output)
);

barrel_shifter bs (
    .clk(clk),
    .reset(reset),
    .A(A),
    .shift(shift),
    .shift_data(shift_output),
    .Q(barrel_output)
);

functional_module fm (
    .shift_output(shift_output),
    .barrel_output(barrel_output),
    .result(result)
);

assign Q = select ? barrel_output : shift_output;

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic reset,
    input logic [3:0] A,
    input logic [1:0] shift,
    input logic [1:0] shift_amount,
    input logic select,
    input logic [3:0] Q
);
    // Clock: clk, Reset: reset (active-low async). Top Q is a comb mux of registered submodule outputs.

    // Q must be zero during active-low reset.
    check_reset_clears_Q: assert property (
        @(posedge clk) !reset |-> (Q == 4'b0000)
    );

    // When select=0 and shift_amount=00, Q passes A.
    check_sel0_sa00_passthru: assert property (
        @(posedge clk) disable iff (!reset) (!select && (shift_amount == 2'b00)) |-> (Q == A)
    );

    // When select=0 and shift_amount=01, Q = {A[2:0], A[3]}.
    check_sel0_sa01_rotl1: assert property (
        @(posedge clk) disable iff (!reset) (!select && (shift_amount == 2'b01)) |-> (Q == {A[2:0], A[3]})
    );

    // When select=0 and shift_amount=10, Q = {A[3], A[3:1]} (arith right 1).
    check_sel0_sa10_sra1: assert property (
        @(posedge clk) disable iff (!reset) (!select && (shift_amount == 2'b10)) |-> (Q == {A[3], A[3:1]})
    );

    // When select=0 and shift_amount=11, Q = {A[2:0], A[3]}.
    check_sel0_sa11_rotl1: assert property (
        @(posedge clk) disable iff (!reset) (!select && (shift_amount == 2'b11)) |-> (Q == {A[2:0], A[3]})
    );

    // When select=1 and shift=00, Q passes A.
    check_sel1_s00_passthru: assert property (
        @(posedge clk) disable iff (!reset) (select && (shift == 2'b00)) |-> (Q == A)
    );

    // When select=1 and shift=11, Q = {A[2:0], A[3]}.
    check_sel1_s11_rotl1: assert property (
        @(posedge clk) disable iff (!reset) (select && (shift == 2'b11)) |-> (Q == {A[2:0], A[3]})
    );

    // When select=1 and shift=01, upper bits of Q come from A[2:0].
    check_sel1_s01_upper_from_A: assert property (
        @(posedge clk) disable iff (!reset) (select && (shift == 2'b01)) |-> (Q[3:1] == A[2:0])
    );

    // When select=1 and shift=01, Q[0] comes from prev shift_output[3].
    check_sel1_s01_lsb_from_prev_shift3: assert property (
        @(posedge clk) disable iff (!reset)
            (select && (shift == 2'b01) && $past(reset))
        |-> (Q[0] ==
             ( (($past(shift_amount) == 2'b01) || ($past(shift_amount) == 2'b11))
               ? $past(A[2]) : $past(A[3]) ))
    );

    // When select=1 and shift=10, lower bits of Q come from A[3:1].
    check_sel1_s10_lower_from_A: assert property (
        @(posedge clk) disable iff (!reset) (select && (shift == 2'b10)) |-> (Q[2:0] == A[3:1])
    );

    // When select=1 and shift=10, Q[3] comes from prev shift_output[0].
    check_sel1_s10_msb_from_prev_shift0: assert property (
        @(posedge clk) disable iff (!reset)
            (select && (shift == 2'b10) && $past(reset))
        |-> (Q[3] ==
             ( ($past(shift_amount) == 2'b00) ? $past(A[0]) :
               (($past(shift_amount) == 2'b10) ? $past(A[1]) : $past(A[3])) ))
    );

endmodule

rtl:
module MUXn_4_1(
  input [MuxLen:0] mux_in0,
  input [MuxLen:0] mux_in1,
  input [MuxLen:0] mux_in2,
  input [MuxLen:0] mux_in3,
  input [1:0] mux_sel,
  output [MuxLen:0] mux_out
);

  parameter MuxLen = 63;

  wire [MuxLen:0] mux_tmp0;
  wire [MuxLen:0] mux_tmp1;

  MUX2x1 #(MuxLen) mux0(mux_in0, mux_in1, mux_sel[0], mux_tmp0);
  MUX2x1 #(MuxLen) mux1(mux_in2, mux_in3, mux_sel[0], mux_tmp1);
  MUX2x1 #(MuxLen) msel(mux_tmp0, mux_tmp1, mux_sel[1], mux_out);

endmodule
module MUX2x1 #(
  parameter MuxLen = 0
)(
  input [MuxLen:0] in0,
  input [MuxLen:0] in1,
  input sel,
  output [MuxLen:0] out
);
  assign out = sel ? in1 : in0;
endmodule

sva:
module MUXn_4_1_sva #(
    parameter MuxLen = 63
)(
    input logic clk,
    input logic rst_n,

    // DUT ports
    input logic [MuxLen:0] mux_in0,
    input logic [MuxLen:0] mux_in1,
    input logic [MuxLen:0] mux_in2,
    input logic [MuxLen:0] mux_in3,
    input logic [1:0]      mux_sel,
    input logic [MuxLen:0] mux_out
);

    ///// 4:1 mux select mapping /////
    // When mux_sel==00, output equals mux_in0.
    check_sel_00_maps_to_in0: assert property (
        @(posedge clk) disable iff (!rst_n) (mux_sel == 2'b00) |-> (mux_out == mux_in0)
    );

    // When mux_sel==01, output equals mux_in1.
    check_sel_01_maps_to_in1: assert property (
        @(posedge clk) disable iff (!rst_n) (mux_sel == 2'b01) |-> (mux_out == mux_in1)
    );

    // When mux_sel==10, output equals mux_in2.
    check_sel_10_maps_to_in2: assert property (
        @(posedge clk) disable iff (!rst_n) (mux_sel == 2'b10) |-> (mux_out == mux_in2)
    );

    // When mux_sel==11, output equals mux_in3.
    check_sel_11_maps_to_in3: assert property (
        @(posedge clk) disable iff (!rst_n) (mux_sel == 2'b11) |-> (mux_out == mux_in3)
    );

    ///// Functional equivalence to ternary expression /////
    // Output equals nested ternary of mux_sel bits.
    check_function_equivalence: assert property (
        @(posedge clk) disable iff (!rst_n)
        mux_out == (mux_sel[1] ? (mux_sel[0] ? mux_in3 : mux_in2)
                               : (mux_sel[0] ? mux_in1 : mux_in0))
    );

    ///// Stability given stable selection path /////
    // If sel==00 and both sel and mux_in0 are stable, output is stable.
    check_stable_out_when_00_path_stable: assert property (
        @(posedge clk) disable iff (!rst_n)
        (mux_sel == 2'b00 && $stable(mux_sel) && $stable(mux_in0)) |-> $stable(mux_out)
    );

    // If sel==01 and both sel and mux_in1 are stable, output is stable.
    check_stable_out_when_01_path_stable: assert property (
        @(posedge clk) disable iff (!rst_n)
        (mux_sel == 2'b01 && $stable(mux_sel) && $stable(mux_in1)) |-> $stable(mux_out)
    );

    // If sel==10 and both sel and mux_in2 are stable, output is stable.
    check_stable_out_when_10_path_stable: assert property (
        @(posedge clk) disable iff (!rst_n)
        (mux_sel == 2'b10 && $stable(mux_sel) && $stable(mux_in2)) |-> $stable(mux_out)
    );

    // If sel==11 and both sel and mux_in3 are stable, output is stable.
    check_stable_out_when_11_path_stable: assert property (
        @(posedge clk) disable iff (!rst_n)
        (mux_sel == 2'b11 && $stable(mux_sel) && $stable(mux_in3)) |-> $stable(mux_out)
    );

    ///// Simplifications when input pairs are equal /////
    // If upper select=0 and mux_in0==mux_in1, output equals that value.
    check_low_tree_pair_equal: assert property (
        @(posedge clk) disable iff (!rst_n)
        (mux_sel[1] == 1'b0 && (mux_in0 == mux_in1)) |-> (mux_out == mux_in0)
    );

    // If upper select=1 and mux_in2==mux_in3, output equals that value.
    check_high_tree_pair_equal: assert property (
        @(posedge clk) disable iff (!rst_n)
        (mux_sel[1] == 1'b1 && (mux_in2 == mux_in3)) |-> (mux_out == mux_in2)
    );

endmodule

module barrel_shifter_sva (
    input logic CLK,          // External verification clock for sampling
    input logic [3:0] D,      // DUT input
    input logic [1:0] S,      // DUT input
    input logic [3:0] Q       // DUT output
);
    // No reset in RTL; purely combinational behavior sampled on CLK.

    // When S==00, Q passes D unchanged.
    check_no_shift: assert property (
        @(posedge CLK) (S == 2'b00) |-> (Q == D)
    );

    // When S==01, Q is left shift by 1 with zero fill.
    check_left_shift: assert property (
        @(posedge CLK) (S == 2'b01) |-> (Q == {D[2:0], 1'b0})
    );

    // For left shift, LSB is zero (zero-fill).
    check_left_shift_lsb_zero: assert property (
        @(posedge CLK) (S == 2'b01) |-> (Q[0] == 1'b0)
    );

    // When S==10, Q is right shift by 1 with zero fill.
    check_right_shift: assert property (
        @(posedge CLK) (S == 2'b10) |-> (Q == {1'b0, D[3:1]})
    );

    // For right shift, MSB is zero (zero-fill).
    check_right_shift_msb_zero: assert property (
        @(posedge CLK) (S == 2'b10) |-> (Q[3] == 1'b0)
    );

    // When S==11, Q is a circular rotate-left by 2 bits.
    check_circular_shift: assert property (
        @(posedge CLK) (S == 2'b11) |-> (Q == {D[1:0], D[3:2]})
    );
endmodule

