module and3_en (
    a,
    b,
    c,
    en,
    out
);

    input a;
    input b;
    input c;
    input en;
    output out;

    reg out_reg;

    always @(posedge en)
        if (en)
            out_reg <= a & b & c;
        else
            out_reg <= 1'b0;

    assign out = out_reg;

endmodule

sva:
module and3_en_sva (
    input logic a,
    input logic b,
    input logic c,
    input logic en,
    input logic out
);
    // Analysis: Clock = posedge en; no reset; sequential FF; out updates on en to a&b&c and holds otherwise.

    // en is HIGH at its own posedge.
    check_en_high_on_posedge: assert property (
        @(posedge en) en == 1'b1
    );

    // On each posedge en (after first), out equals AND of a,b,c from previous posedge.
    check_out_matches_prev_and: assert property (
        @(posedge en) !$isunknown($past({a,b,c})) |-> (out == ($past(a) & $past(b) & $past(c)))
    );

    // If out rises at this posedge, previous a,b,c must all have been 1.
    check_out_rise_requires_prev_and1: assert property (
        @(posedge en) $rose(out) && !$isunknown($past({a,b,c})) |-> ($past(a) && $past(b) && $past(c))
    );

    // If out falls at this posedge, previous a,b,c were not all 1.
    check_out_fall_requires_prev_and0: assert property (
        @(posedge en) $fell(out) && !$isunknown($past({a,b,c})) |-> !($past(a) && $past(b) && $past(c))
    );

    // If previous a,b,c were all 1, out must be 1 at this posedge.
    check_prev_and1_implies_out1: assert property (
        @(posedge en) (!$isunknown($past({a,b,c})) && $past(a) && $past(b) && $past(c)) |-> (out == 1'b1)
    );

    // If previous a,b,c were not all 1, out must be 0 at this posedge.
    check_prev_and0_implies_out0: assert property (
        @(posedge en) (!$isunknown($past({a,b,c})) && !($past(a) && $past(b) && $past(c))) |-> (out == 1'b0)
    );
endmodule

rtl:
module r_TX_BUF_OBJ4_BYTE_1(output reg [7:0] reg_0x61, input wire reset, input wire wenb, input wire [7:0] in_data, input wire clk);
	always@(posedge clk)
	begin
		if(reset==0) begin
			if(wenb==0)
				reg_0x61<=in_data;
			else
				reg_0x61<=reg_0x61;
		end
		else
			reg_0x61<=8'h00;
	end
endmodule

sva:
module r_TX_BUF_OBJ4_BYTE_1_sva (
    input logic clk,
    input logic reset,
    input logic wenb,
    input logic [7:0] in_data,
    input logic [7:0] reg_0x61
);

    ///// Reset behavior /////
    // While reset is asserted (active-high, synchronous), reg_0x61 is 0x00.
    check_reset_drives_zero: assert property (
        @(posedge clk) reset |-> (reg_0x61 == 8'h00)
    );

    ///// Functional update rules (active when not in reset) /////
    // On a write (wenb low) in the previous cycle, capture previous in_data.
    check_write_on_wenb_low: assert property (
        @(posedge clk) disable iff (reset)
            ($past(!reset) && ($past(wenb) == 1'b0)) |-> (reg_0x61 == $past(in_data))
    );

    // On a hold (wenb high) in the previous cycle, retain the previous value.
    check_hold_on_wenb_high: assert property (
        @(posedge clk) disable iff (reset)
            ($past(!reset) && ($past(wenb) == 1'b1)) |-> (reg_0x61 == $past(reg_0x61))
    );

    // Deterministic next-state function based on previous wenb.
    check_next_state_function: assert property (
        @(posedge clk) disable iff (reset)
            $past(!reset) |-> (reg_0x61 == ($past(wenb) ? $past(reg_0x61) : $past(in_data)))
    );

    // If the value changed (and previous cycle was not in reset), the previous cycle must have been a write.
    check_change_implies_prev_write: assert property (
        @(posedge clk) disable iff (reset)
            ($past(!reset) && (reg_0x61 != $past(reg_0x61))) |-> ($past(wenb) == 1'b0)
    );

    // A write followed by a hold preserves the written value two cycles later.
    check_write_then_hold_preserves_value: assert property (
        @(posedge clk) disable iff (reset)
            ($past(!reset,2) && $past(!reset) && ($past(wenb,2) == 1'b0) && ($past(wenb) == 1'b1))
            |-> (reg_0x61 == $past(in_data,2))
    );

    // Back-to-back writes take the last cycle's in_data.
    check_back_to_back_writes_take_last: assert property (
        @(posedge clk) disable iff (reset)
            ($past(!reset,2) && $past(!reset) && ($past(wenb,2) == 1'b0) && ($past(wenb) == 1'b0))
            |-> (reg_0x61 == $past(in_data))
    );

    // First cycle after reset, if holding (wenb high), the register remains at 0x00.
    check_post_reset_hold_is_zero: assert property (
        @(posedge clk) disable iff (reset)
            ($past(reset) && (wenb == 1'b1)) |-> (reg_0x61 == 8'h00)
    );

    // Two consecutive holds (no reset in the past two cycles) keep the value from two cycles ago.
    check_two_consecutive_holds_stable: assert property (
        @(posedge clk) disable iff (reset)
            ($past(!reset,2) && $past(!reset) && ($past(wenb,2) == 1'b1) && ($past(wenb) == 1'b1))
            |-> (reg_0x61 == $past(reg_0x61,2))
    );

endmodule

rtl:
module edge_detector (
    input clk,
    input [7:0] in,
    output reg [7:0] anyedge
);

reg [7:0] prev_in;

always @(posedge clk) begin
    if (in != prev_in) begin
        anyedge <= 8'b00000001;
    end else begin
        anyedge <= 8'b00000000;
    end
    prev_in <= in;
end

endmodule

module top_module (
    input clk,
    input [7:0] in,
    output [7:0] anyedge
);

edge_detector detector (
    .clk(clk),
    .in(in),
    .anyedge(anyedge)
);

endmodule

sva:
module edge_detector_sva (
    input logic clk,
    input logic [7:0] in,
    input logic [7:0] anyedge
);
    // Clock: clk (posedge). Reset: none in RTL.
    // Sequential logic: samples in; anyedge=8'h01 on change, else 8'h00. Bits [7:1] always 0.

    // anyedge must be either 8'h00 or 8'h01 each cycle.
    check_anyedge_valid_values: assert property (
        @(posedge clk) (anyedge == 8'h00) || (anyedge == 8'h01)
    );

    // Upper bits of anyedge are always zero.
    check_anyedge_upper_bits_zero: assert property (
        @(posedge clk) anyedge[7:1] == 7'b0
    );

    // LSB of anyedge equals the change flag between current and previous in.
    check_lsb_matches_change: assert property (
        @(posedge clk) disable iff ($initstate) anyedge[0] == (in != $past(in))
    );

    // When input changes from previous cycle, anyedge must be 8'h01.
    check_anyedge_when_input_changes: assert property (
        @(posedge clk) disable iff ($initstate) (in != $past(in)) |-> (anyedge == 8'h01)
    );

    // When input is unchanged from previous cycle, anyedge must be 8'h00.
    check_anyedge_when_input_unchanged: assert property (
        @(posedge clk) disable iff ($initstate) (in == $past(in)) |-> (anyedge == 8'h00)
    );

endmodule

rtl:
module binary_adder(
    input [3:0] A,
    input [3:0] B,
    input C_in,
    output [3:0] S,
    output C_out
);

wire [3:0] sum;
wire [3:0] carry_out;

full_adder fa0(A[0], B[0], C_in, sum[0], carry_out[0]);
full_adder fa1(A[1], B[1], carry_out[0], sum[1], carry_out[1]);
full_adder fa2(A[2], B[2], carry_out[1], sum[2], carry_out[2]);
full_adder fa3(A[3], B[3], carry_out[2], sum[3], C_out);

assign S = sum;

endmodule

module full_adder(
    input A,
    input B,
    input C_in,
    output S,
    output C_out
);

assign S = A ^ B ^ C_in;
assign C_out = (A & B) | (C_in & (A ^ B));

endmodule

sva:
module binary_adder_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic C_in,
    input logic [3:0] S,
    input logic C_out
);
    // Local carry chain expressions derived from the RTL full adders
    let c1 = (A[0] & B[0]) | (C_in & (A[0] ^ B[0]));
    let c2 = (A[1] & B[1]) | (c1 & (A[1] ^ B[1]));
    let c3 = (A[2] & B[2]) | (c2 & (A[2] ^ B[2]));

    // Sum and carry match 5-bit arithmetic addition of inputs
    check_overall_sum: assert property (
        @(posedge clk) {C_out, S} == (A + B + C_in)
    );

    // LSB sum bit equals XOR of inputs
    check_s0_xor: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0] ^ C_in)
    );

    // Bit1 sum uses ripple carry from bit0
    check_s1_xor: assert property (
        @(posedge clk) S[1] == (A[1] ^ B[1] ^ c1)
    );

    // Bit2 sum uses ripple carry from bit1
    check_s2_xor: assert property (
        @(posedge clk) S[2] == (A[2] ^ B[2] ^ c2)
    );

    // Bit3 sum uses ripple carry from bit2
    check_s3_xor: assert property (
        @(posedge clk) S[3] == (A[3] ^ B[3] ^ c3)
    );

    // Final carry-out equation at MSB
    check_cout_equation: assert property (
        @(posedge clk) C_out == ((A[3] & B[3]) | (c3 & (A[3] ^ B[3])))
    );

    // If both MSB inputs are 1, carry-out must be 1
    check_cout_msb_both_one: assert property (
        @(posedge clk) (~(A[3] & B[3])) || (C_out == 1'b1)
    );

    // If both MSB inputs are 0, carry-out must be 0
    check_cout_msb_both_zero: assert property (
        @(posedge clk) (~(~A[3] & ~B[3])) || (C_out == 1'b0)
    );

    // If MSB inputs differ, carry-out equals c3
    check_cout_msb_diff_equals_c3: assert property (
        @(posedge clk) (~(A[3] ^ B[3])) || (C_out == c3)
    );

    // If MSB inputs are equal, S[3] equals c3
    check_s3_when_msb_equal: assert property (
        @(posedge clk) (A[3] ^ B[3]) || (S[3] == c3)
    );

    // If MSB inputs differ, S[3] is the inverse of c3
    check_s3_when_msb_diff: assert property (
        @(posedge clk) (~(A[3] ^ B[3])) || (S[3] == ~c3)
    );

    // With A=0 and B=0, S mirrors C_in on bit0 and C_out is 0
    check_zero_inputs_behavior: assert property (
        @(posedge clk) (~((A == 4'd0) && (B == 4'd0))) || ((S == {3'b000, C_in}) && (C_out == 1'b0))
    );

    // With A=15, B=15, C_in=0, result is 30 -> C_out=1, S=14
    check_all_ones_no_cin: assert property (
        @(posedge clk) (~((A == 4'hF) && (B == 4'hF) && (C_in == 1'b0))) || ((S == 4'he) && (C_out == 1'b1))
    );

    // With A=15, B=15, C_in=1, result is 31 -> C_out=1, S=15
    check_all_ones_with_cin: assert property (
        @(posedge clk) (~((A == 4'hF) && (B == 4'hF) && (C_in == 1'b1))) || ((S == 4'hf) && (C_out == 1'b1))
    );

    // If bit0 generates a carry (A0&B0), bit1 sum must invert A1^B1
    check_s1_when_carry_generated_at_bit0: assert property (
        @(posedge clk) (~(A[0] & B[0])) || (S[1] == (A[1] ^ B[1] ^ 1'b1))
    );

endmodule

rtl:
module nor2_pg (
    output Y,
    input A,
    input B,
    input VPWR,
    input VGND,
    input VPB,
    input VNB
);

    // Local signals
    wire nor_out_Y;

    // NOR gate implementation
    assign nor_out_Y = A & B;

    // Power good functionality
    power_good #(
        .PWRGOOD_WIDTH(1)
    ) \pwrgood_pp0 (
        .Y(Y),
        .VPWR(VPWR),
        .VGND(VGND),
        .VPB(VPB),
        .VNB(VNB)
    );

endmodule
module power_good #(
    parameter PWRGOOD_WIDTH = 1
)(
    output [PWRGOOD_WIDTH - 1:0] Y,
    input VPWR,
    input VGND,
    input VPB,
    input VNB
);

    assign Y = (VPWR > VGND) ? VPB : VNB;

endmodule

sva:
module nor2_pg_sva (
    input logic CLK,   // External sampling clock (RTL has no clock/reset; purely combinational)
    input logic Y,
    input logic A,
    input logic B,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB
);

    ///// Power-good mux behavior /////
    // When VPWR > VGND, Y must equal VPB.
    check_y_selects_vpb_when_pwrgood: assert property (
        @(posedge CLK) (VPWR > VGND) |-> (Y == VPB)
    );

    // When VPWR <= VGND, Y must equal VNB.
    check_y_selects_vnb_when_not_pwrgood: assert property (
        @(posedge CLK) !(VPWR > VGND) |-> (Y == VNB)
    );

    ///// Stability and dependency /////
    // If all power-related pins are stable, Y must remain stable.
    check_y_stable_when_power_pins_stable: assert property (
        @(posedge CLK) $stable(VPWR) && $stable(VGND) && $stable(VPB) && $stable(VNB) |-> $stable(Y)
    );

    // If Y changes, at least one power-related pin must have changed.
    check_y_change_implies_power_pin_change: assert property (
        @(posedge CLK) $changed(Y) |-> (!$stable(VPWR) || !$stable(VGND) || !$stable(VPB) || !$stable(VNB))
    );

    ///// Data following under fixed select /////
    // With select true and other power pins stable, Y follows VPB on VPB change.
    check_y_follows_vpb_when_pwrgood_and_vpb_changes: assert property (
        @(posedge CLK) (VPWR > VGND) && $stable(VPWR) && $stable(VGND) && $stable(VNB) && $changed(VPB)
        |-> (Y == VPB) && $changed(Y)
    );

    // With select false and other power pins stable, Y follows VNB on VNB change.
    check_y_follows_vnb_when_not_pwrgood_and_vnb_changes: assert property (
        @(posedge CLK) !(VPWR > VGND) && $stable(VPWR) && $stable(VGND) && $stable(VPB) && $changed(VNB)
        |-> (Y == VNB) && $changed(Y)
    );

endmodule

