module my_module_sva (
    input logic X,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic B1,
    input logic B2
);
    // X equals (A1 & A2 & A3) OR (B1 & B2).
    check_functional_equivalence: assert property (
        @(posedge $global_clock) disable iff (1'b0)
        X == ((A1 && A2 && A3) || (B1 && B2))
    );

    // If A1&A2&A3 are all HIGH, X must be HIGH.
    check_termA_implies_X: assert property (
        @(posedge $global_clock) disable iff (1'b0)
        (A1 && A2 && A3) |-> (X == 1'b1)
    );

    // If B1&B2 are both HIGH, X must be HIGH.
    check_termB_implies_X: assert property (
        @(posedge $global_clock) disable iff (1'b0)
        (B1 && B2) |-> (X == 1'b1)
    );

    // If X is HIGH, at least one product term is HIGH.
    check_X_implies_termA_or_termB: assert property (
        @(posedge $global_clock) disable iff (1'b0)
        X |-> ((A1 && A2 && A3) || (B1 && B2))
    );

    // If both product terms are LOW, X must be LOW.
    check_neither_term_implies_X0: assert property (
        @(posedge $global_clock) disable iff (1'b0)
        (!(A1 && A2 && A3) && !(B1 && B2)) |-> (X == 1'b0)
    );

    // X can only change when at least one input changes.
    check_x_change_requires_input_change: assert property (
        @(posedge $global_clock) disable iff (1'b0)
        $changed(X) |-> ($changed(A1) || $changed(A2) || $changed(A3) || $changed(B1) || $changed(B2))
    );

    // If all inputs are stable, X must remain stable.
    check_inputs_stable_implies_x_stable: assert property (
        @(posedge $global_clock) disable iff (1'b0)
        !($changed(A1) || $changed(A2) || $changed(A3) || $changed(B1) || $changed(B2)) |-> !$changed(X)
    );

    // If only A1 toggles, X toggles iff A2&A3 are HIGH and B1&B2 are LOW.
    check_only_A1_toggle_effect: assert property (
        @(posedge $global_clock) disable iff (1'b0)
        ($changed(A1) && !$changed(A2) && !$changed(A3) && !$changed(B1) && !$changed(B2))
            |-> ($changed(X) == (A2 && A3 && !(B1 && B2)))
    );

    // If only A2 toggles, X toggles iff A1&A3 are HIGH and B1&B2 are LOW.
    check_only_A2_toggle_effect: assert property (
        @(posedge $global_clock) disable iff (1'b0)
        (!$changed(A1) && $changed(A2) && !$changed(A3) && !$changed(B1) && !$changed(B2))
            |-> ($changed(X) == (A1 && A3 && !(B1 && B2)))
    );

    // If only B1 toggles, X toggles iff B2 is HIGH and A1&A2&A3 are LOW as a group.
    check_only_B1_toggle_effect: assert property (
        @(posedge $global_clock) disable iff (1'b0)
        (!$changed(A1) && !$changed(A2) && !$changed(A3) && $changed(B1) && !$changed(B2))
            |-> ($changed(X) == (B2 && !(A1 && A2 && A3)))
    );

endmodule

rtl:
module d_ff_sync_rst(clk, rst, d, q);
input clk;
input rst;
input d;
output q;

reg q;

always @(posedge clk) begin
    if (rst) begin
        q <= 1'b0;
    end else begin
        q <= d;
    end
end

endmodule

sva:
module d_ff_sync_rst_sva (
    input logic clk,
    input logic rst,
    input logic d,
    input logic q
);
    // Clock: clk; Reset: rst (active-high, synchronous). Sequential D-FF with sync reset.

    // Q matches previous cycle's (rst ? 0 : d).
    check_next_state_from_prev_inputs: assert property (
        @(posedge clk) $past(1'b1) |-> (q == ($past(rst) ? 1'b0 : $past(d)))
    );

    // If reset was 1 in the previous cycle, Q is 0 now.
    check_q_zero_after_prev_reset: assert property (
        @(posedge clk) $past(rst) |-> (q == 1'b0)
    );

    // If reset was 0 in the previous cycle, Q equals previous D.
    check_q_follows_prev_d_when_no_reset: assert property (
        @(posedge clk) !$past(rst) |-> (q == $past(d))
    );

    // When not in reset previously and D matched prior Q, Q holds its value.
    check_hold_when_input_matches: assert property (
        @(posedge clk) disable iff (rst) ($past(1'b1) && !$past(rst) && ($past(d) == $past(q))) |-> (q == $past(q))
    );

    // When not in reset previously and D differed from prior Q, Q updates to prior D and changes.
    check_update_when_input_differs: assert property (
        @(posedge clk) disable iff (rst) ($past(1'b1) && !$past(rst) && ($past(d) != $past(q))) |-> ((q == $past(d)) && (q != $past(q)))
    );

    // While reset is held across consecutive cycles, Q is 0.
    check_q_zero_while_reset_held: assert property (
        @(posedge clk) ($past(rst) && rst) |-> (q == 1'b0)
    );

    // On the cycle reset deasserts (was 1, now 0), Q remains 0 from the prior reset assignment.
    check_q_zero_on_reset_release: assert property (
        @(posedge clk) ($past(rst) && !rst) |-> (q == 1'b0)
    );

endmodule

module odd_module_sva (
    input logic A1,
    input logic A2,
    input logic B1,
    input logic C1,
    input logic D1,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB,
    input logic Y
);

    ///// Functional equivalence /////
    // Y equals the RTL combinational expression.
    check_y_functional_equivalence: assert property (
        @(posedge A1 or posedge A2 or posedge B1 or posedge C1 or posedge D1 or posedge VPWR or posedge VGND or posedge VPB or posedge VNB or posedge Y)
        Y == (
            (A1 % 2 == 1) ||
            ((A1 % 2 == 0) && (A2 % 2 == 1)) ||
            ((A1 % 2 == 0) && (A2 % 2 == 0) && (B1 % 2 == 1) && (C1 % 2 == 1) && (D1 % 2 == 1)) ||
            (VPWR > VGND) ||
            (VPB == VNB)
        )
    );

    ///// OR-term implications /////
    // If A1 is odd, Y must be HIGH.
    check_y_when_A1_odd: assert property (
        @(posedge A1 or posedge A2 or posedge B1 or posedge C1 or posedge D1 or posedge VPWR or posedge VGND or posedge VPB or posedge VNB or posedge Y)
        (A1 % 2 == 1) |-> (Y == 1'b1)
    );

    // If A1 is even and A2 is odd, Y must be HIGH.
    check_y_when_A2_odd_A1_even: assert property (
        @(posedge A1 or posedge A2 or posedge B1 or posedge C1 or posedge D1 or posedge VPWR or posedge VGND or posedge VPB or posedge VNB or posedge Y)
        ((A1 % 2 == 0) && (A2 % 2 == 1)) |-> (Y == 1'b1)
    );

    // If A1 and A2 are even and B1,C1,D1 are odd, Y must be HIGH.
    check_y_when_chain_odd: assert property (
        @(posedge A1 or posedge A2 or posedge B1 or posedge C1 or posedge D1 or posedge VPWR or posedge VGND or posedge VPB or posedge VNB or posedge Y)
        ((A1 % 2 == 0) && (A2 % 2 == 0) && (B1 % 2 == 1) && (C1 % 2 == 1) && (D1 % 2 == 1)) |-> (Y == 1'b1)
    );

    // If VPWR is greater than VGND, Y must be HIGH.
    check_y_when_power_gt_ground: assert property (
        @(posedge A1 or posedge A2 or posedge B1 or posedge C1 or posedge D1 or posedge VPWR or posedge VGND or posedge VPB or posedge VNB or posedge Y)
        (VPWR > VGND) |-> (Y == 1'b1)
    );

    // If VPB equals VNB, Y must be HIGH.
    check_y_when_bulk_equal: assert property (
        @(posedge A1 or posedge A2 or posedge B1 or posedge C1 or posedge D1 or posedge VPWR or posedge VGND or posedge VPB or posedge VNB or posedge Y)
        (VPB == VNB) |-> (Y == 1'b1)
    );

    ///// Completeness checks /////
    // If Y is HIGH, at least one OR condition must hold.
    check_y_one_implies_some_condition: assert property (
        @(posedge A1 or posedge A2 or posedge B1 or posedge C1 or posedge D1 or posedge VPWR or posedge VGND or posedge VPB or posedge VNB or posedge Y)
        (Y == 1'b1) |-> (
            (A1 % 2 == 1) ||
            ((A1 % 2 == 0) && (A2 % 2 == 1)) ||
            ((A1 % 2 == 0) && (A2 % 2 == 0) && (B1 % 2 == 1) && (C1 % 2 == 1) && (D1 % 2 == 1)) ||
            (VPWR > VGND) ||
            (VPB == VNB)
        )
    );

    // If Y is LOW, none of the OR conditions may hold.
    check_y_zero_implies_no_condition: assert property (
        @(posedge A1 or posedge A2 or posedge B1 or posedge C1 or posedge D1 or posedge VPWR or posedge VGND or posedge VPB or posedge VNB or posedge Y)
        (Y == 1'b0) |-> !(
            (A1 % 2 == 1) ||
            ((A1 % 2 == 0) && (A2 % 2 == 1)) ||
            ((A1 % 2 == 0) && (A2 % 2 == 0) && (B1 % 2 == 1) && (C1 % 2 == 1) && (D1 % 2 == 1)) ||
            (VPWR > VGND) ||
            (VPB == VNB)
        )
    );

    // If no term is true (including power/bulk terms), Y must be LOW.
    check_when_all_conditions_false_then_y_low: assert property (
        @(posedge A1 or posedge A2 or posedge B1 or posedge C1 or posedge D1 or posedge VPWR or posedge VGND or posedge VPB or posedge VNB or posedge Y)
        !(
            (A1 % 2 == 1) ||
            ((A1 % 2 == 0) && (A2 % 2 == 1)) ||
            ((A1 % 2 == 0) && (A2 % 2 == 0) && (B1 % 2 == 1) && (C1 % 2 == 1) && (D1 % 2 == 1)) ||
            (VPWR > VGND) ||
            (VPB == VNB)
        ) |-> (Y == 1'b0)
    );

endmodule

rtl:
module mux_pipeline(
    input [255:0] in,
    input [7:0] sel,
    output reg out,
    input clk
);

reg [7:0] sel_reg;
reg [7:0] sel_next;

reg [255:0] in_reg;
reg [255:0] in_next;

always @(*) begin
    sel_reg = sel;
end

always @(posedge clk) begin
    sel_next <= sel_reg;
    in_next <= in_reg;
end

always @(posedge clk) begin
    out <= in_next[sel_next];
    in_reg <= in_next;
end

endmodule

sva:
module mux_pipeline_sva (
    input logic [255:0] in,
    input logic [7:0] sel,
    input logic out,
    input logic clk
);
    ///// Basic port-level checks /////
    // sel is within 0..255 (width-accurate index range).
    check_sel_index_range: assert property (
        @(posedge clk) (sel < 8'd256)
    );
endmodule

module mux_pipeline_int_sva;
    ///// Internal behavior checks /////
    // sel_reg tracks sel combinationally at every clock edge.
    check_sel_reg_matches_sel: assert property (
        @(posedge clk) sel_reg == sel
    );
    // in_next captures previous in_reg each clock.
    check_in_next_from_in_reg: assert property (
        @(posedge clk) in_next == $past(in_reg)
    );
    // in_reg captures previous in_next each clock.
    check_in_reg_from_in_next: assert property (
        @(posedge clk) in_reg == $past(in_next)
    );
    // in_next returns to its value two cycles earlier (swap behavior).
    check_in_next_two_cycle: assert property (
        @(posedge clk) in_next == $past(in_next, 2)
    );
    // in_reg returns to its value two cycles earlier (swap behavior).
    check_in_reg_two_cycle: assert property (
        @(posedge clk) in_reg == $past(in_reg, 2)
    );
    // Concatenated swap: {in_reg,in_next} == $past({in_next,in_reg}).
    check_pair_swap_concat: assert property (
        @(posedge clk) {in_reg, in_next} == $past({in_next, in_reg})
    );
    // out equals the previous cycle's in_next bit selected by previous sel_next.
    check_out_from_prev_in_next_sel_next: assert property (
        @(posedge clk) out == $past(in_next)[ $past(sel_next) ]
    );
    // If selected input and index did not change in the prior step, out must not change.
    check_out_stable_when_inputs_unchanged: assert property (
        @(posedge clk) (($past(in_next) == $past(in_next,2)) && ($past(sel_next) == $past(sel_next,2))) |-> (out == $past(out))
    );
    // If out changed, either in_next or sel_next changed in the prior step.
    check_out_change_implies_input_or_sel_change: assert property (
        @(posedge clk) $changed(out) |-> (($past(in_next) != $past(in_next,2)) || ($past(sel_next) != $past(sel_next,2)))
    );
endmodule

bind mux_pipeline mux_pipeline_int_sva u_mux_pipeline_int_sva ();

module counter_sva (
    input logic CLK,
    input logic RST,
    input logic EN,
    input logic [3:0] COUNT
);
    // Clock: CLK (posedge). Reset: RST active-high asynchronous.
    // Sequential 4-bit up-counter with enable; reset clears to 0; EN increments, else holds.

    // On any clock where reset is asserted, COUNT must be 0.
    check_reset_clears_count: assert property (
        @(posedge CLK) RST |-> (COUNT == 4'b0000)
    );

    // Immediately after reset deasserts, if EN is 0 then COUNT remains 0.
    check_hold_after_reset_release_without_en: assert property (
        @(posedge CLK) disable iff (RST) $fell(RST) && !EN |-> (COUNT == 4'b0000)
    );

    // Immediately after reset deasserts, if EN is 1 then COUNT becomes 1.
    check_inc_after_reset_release_with_en: assert property (
        @(posedge CLK) disable iff (RST) $fell(RST) && EN |-> (COUNT == 4'b0001)
    );

    // With no reset in the previous cycle, EN=1 increments COUNT by 1 (mod 16).
    check_increment_on_enable: assert property (
        @(posedge CLK) disable iff (RST) (EN && !$past(RST)) |-> (COUNT == $past(COUNT) + 4'd1)
    );

    // With no reset in the previous cycle, EN=0 holds COUNT constant.
    check_hold_when_disabled: assert property (
        @(posedge CLK) disable iff (RST) (!EN && !$past(RST)) |-> (COUNT == $past(COUNT))
    );

    // With no reset in the previous cycle, wrap from 15 to 0 when EN=1.
    check_wrap_on_max: assert property (
        @(posedge CLK) disable iff (RST) (EN && !$past(RST) && ($past(COUNT) == 4'hF)) |-> (COUNT == 4'h0)
    );

    // With no reset in the last 2 cycles, EN=1 for 2 consecutive cycles increments by 2.
    check_two_cycle_increment_on_enable: assert property (
        @(posedge CLK) disable iff (RST) (EN && $past(EN) && !$past(RST) && !$past(RST,2)) |-> (COUNT == $past(COUNT,2) + 4'd2)
    );

    // With no reset in the last 2 cycles, EN=0 for 2 consecutive cycles holds value over 2 cycles.
    check_two_cycle_hold_when_disabled: assert property (
        @(posedge CLK) disable iff (RST) (!EN && !$past(EN) && !$past(RST) && !$past(RST,2)) |-> (COUNT == $past(COUNT,2))
    );

endmodule

rtl:
module gray_code (
    input [3:0] D,
    output reg [3:0] G
);

always @ (D) begin
    G[3] = D[3];
    G[2] = D[3] ^ D[2];
    G[1] = D[2] ^ D[1];
    G[0] = D[1] ^ D[0];
end

endmodule

sva:
module gray_code_sva (
    input logic CLK,
    input logic [3:0] D,
    input logic [3:0] G
);
    // G must equal the Gray encoding of D
    check_gray_encode_vector: assert property (
        @(posedge CLK) G == {D[3], (D[3]^D[2]), (D[2]^D[1]), (D[1]^D[0])}
    );

    // If only D[0] toggles between cycles, only G[0] toggles.
    check_toggle_from_d0: assert property (
        @(posedge CLK) ((D ^ $past(D)) == 4'b0001) |-> ((G ^ $past(G)) == 4'b0001)
    );

    // If only D[1] toggles between cycles, only G[1] and G[0] toggle.
    check_toggle_from_d1: assert property (
        @(posedge CLK) ((D ^ $past(D)) == 4'b0010) |-> ((G ^ $past(G)) == 4'b0011)
    );

    // If only D[2] toggles between cycles, only G[2] and G[1] toggle.
    check_toggle_from_d2: assert property (
        @(posedge CLK) ((D ^ $past(D)) == 4'b0100) |-> ((G ^ $past(G)) == 4'b0110)
    );

    // If only D[3] toggles between cycles, only G[3] and G[2] toggle.
    check_toggle_from_d3: assert property (
        @(posedge CLK) ((D ^ $past(D)) == 4'b1000) |-> ((G ^ $past(G)) == 4'b1100)
    );

    // If D is stable across cycles, G must be stable.
    check_stability_when_D_stable: assert property (
        @(posedge CLK) $stable(D) |-> $stable(G)
    );

    // G[3] can change only if D[3] changes.
    check_g3_changes_only_with_d3: assert property (
        @(posedge CLK) $changed(G[3]) |-> $changed(D[3])
    );

    // G[2] can change only if D[3] or D[2] changes.
    check_g2_changes_only_with_d3_or_d2: assert property (
        @(posedge CLK) $changed(G[2]) |-> ($changed(D[3]) || $changed(D[2]))
    );

    // G[1] can change only if D[2] or D[1] changes.
    check_g1_changes_only_with_d2_or_d1: assert property (
        @(posedge CLK) $changed(G[1]) |-> ($changed(D[2]) || $changed(D[1]))
    );

    // G[0] can change only if D[1] or D[0] changes.
    check_g0_changes_only_with_d1_or_d0: assert property (
        @(posedge CLK) $changed(G[0]) |-> ($changed(D[1]) || $changed(D[0]))
    );
endmodule

rtl:
module mux_2to1 (
    input A,
    input B,
    input sel,
    output out
);

    assign out = (sel == 1'b0) ? A : B;

endmodule

sva:
module mux_2to1_sva (
    input logic CLK,
    input logic A,
    input logic B,
    input logic sel,
    input logic out
);
    // Out equals selected input per mux function.
    check_mux_function: assert property (
        @(posedge CLK) out == ((sel == 1'b0) ? A : B)
    );

    // When sel is 0, out equals A.
    check_sel0_routes_A: assert property (
        @(posedge CLK) (sel == 1'b0) |-> (out == A)
    );

    // When sel is 1, out equals B.
    check_sel1_routes_B: assert property (
        @(posedge CLK) (sel == 1'b1) |-> (out == B)
    );

    // With sel=0 and stable sel/A, a change on B does not change out.
    check_out_independent_of_B_when_sel0: assert property (
        @(posedge CLK) (sel == 1'b0) && $stable(sel) && $stable(A) && $changed(B) |-> $stable(out)
    );

    // With sel=1 and stable sel/B, a change on A does not change out.
    check_out_independent_of_A_when_sel1: assert property (
        @(posedge CLK) (sel == 1'b1) && $stable(sel) && $stable(B) && $changed(A) |-> $stable(out)
    );

    // With stable sel=0, any out change must be due to A changing.
    check_out_change_caused_by_A_when_sel0: assert property (
        @(posedge CLK) (sel == 1'b0) && $stable(sel) && $changed(out) |-> $changed(A)
    );

    // With stable sel=1, any out change must be due to B changing.
    check_out_change_caused_by_B_when_sel1: assert property (
        @(posedge CLK) (sel == 1'b1) && $stable(sel) && $changed(out) |-> $changed(B)
    );

    // If sel, A, and B are all stable, out must be stable.
    check_out_stable_when_inputs_and_sel_stable: assert property (
        @(posedge CLK) $stable(sel) && $stable(A) && $stable(B) |-> $stable(out)
    );

    // If sel toggles while A==B and both stable, out must not change.
    check_sel_toggle_no_effect_when_AeqB: assert property (
        @(posedge CLK) $changed(sel) && $stable(A) && $stable(B) && (A == B) |-> $stable(out)
    );
endmodule

rtl:
module binary_to_gray (
    input [3:0] B,
    output [3:0] G
);

assign G[0] = B[0];
assign G[1] = B[0] ^ B[1];
assign G[2] = B[1] ^ B[2];
assign G[3] = B[2] ^ B[3];

endmodule

sva:
module binary_to_gray_sva (
    input  logic        CLK,
    input  logic [3:0]  B,
    input  logic [3:0]  G
);
    // G[0] equals B[0].
    check_g0_map: assert property (
        @(posedge CLK) disable iff (1'b0) (G[0] == B[0])
    );

    // G[1] equals B[0] XOR B[1].
    check_g1_xor: assert property (
        @(posedge CLK) disable iff (1'b0) (G[1] == (B[0] ^ B[1]))
    );

    // G[2] equals B[1] XOR B[2].
    check_g2_xor: assert property (
        @(posedge CLK) disable iff (1'b0) (G[2] == (B[1] ^ B[2]))
    );

    // G[3] equals B[2] XOR B[3].
    check_g3_xor: assert property (
        @(posedge CLK) disable iff (1'b0) (G[3] == (B[2] ^ B[3]))
    );

    // Vector form: G equals B XOR (B << 1).
    check_vector_equivalence: assert property (
        @(posedge CLK) disable iff (1'b0) (G == (B ^ (B << 1)))
    );
endmodule

rtl:
module up_down_counter (
    input clk,
    input up_down,
    input load,
    input [3:0] binary,
    output reg [3:0] count
);

always @(posedge clk) begin
    if (load) begin
        count <= binary;
    end else if (up_down) begin
        count <= count + 1;
    end else begin
        count <= count - 1;
    end
end

endmodule

module binary_to_bcd_converter (
    input [3:0] binary,
    output [3:0] BCD_HIGH,
    output [3:0] BCD_LOW
);

assign BCD_HIGH = binary / 10;
assign BCD_LOW = binary % 10;

endmodule

module top_module (
    input clk,
    input up_down,
    input load,
    input [3:0] binary,
    output [3:0] BCD_HIGH,
    output [3:0] BCD_LOW
);

wire [3:0] count;
up_down_counter counter(.clk(clk), .up_down(up_down), .load(load), .binary(binary), .count(count));
binary_to_bcd_converter converter(.binary(count), .BCD_HIGH(BCD_HIGH), .BCD_LOW(BCD_LOW));

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic up_down,
    input logic load,
    input logic [3:0] binary,
    input logic [3:0] BCD_HIGH,
    input logic [3:0] BCD_LOW
);
    // BCD_LOW is always 0..9.
    check_bcd_low_range: assert property (
        @(posedge clk) (BCD_LOW <= 4'd9)
    );

    // BCD_HIGH is always 0 or 1.
    check_bcd_high_range: assert property (
        @(posedge clk) (BCD_HIGH <= 4'd1)
    );

    // If BCD_HIGH is 1, BCD_LOW must be 0..5 (since value <= 15).
    check_bcd_high1_low_max5: assert property (
        @(posedge clk) (BCD_HIGH == 4'd1) |-> (BCD_LOW <= 4'd5)
    );

    // On load, next cycle BCD outputs equal binary's BCD.
    check_load_sets_bcd_next: assert property (
        @(posedge clk) load |=> ( (BCD_HIGH == ($past(binary) / 10)) && (BCD_LOW == ($past(binary) % 10)) )
    );

    // When counting up (no load), next BCD equals (previous value + 1) mod 16.
    check_increment_updates_bcd_next: assert property (
        @(posedge clk) (!load && up_down) |=> (
            (BCD_HIGH == ((($past(BCD_HIGH)*10 + $past(BCD_LOW) + 1) % 16) / 10)) &&
            (BCD_LOW  == ((($past(BCD_HIGH)*10 + $past(BCD_LOW) + 1) % 16) % 10))
        )
    );

    // When counting down (no load), next BCD equals (previous value - 1) mod 16.
    check_decrement_updates_bcd_next: assert property (
        @(posedge clk) (!load && !up_down) |=> (
            (BCD_HIGH == (((($past(BCD_HIGH)*10 + $past(BCD_LOW) + 15) % 16) / 10))) &&
            (BCD_LOW  == (((($past(BCD_HIGH)*10 + $past(BCD_LOW) + 15) % 16) % 10)))
        )
    );

    // Increment wrap-around: from 15 -> 0 when counting up (no load).
    check_inc_wrap_15_to_0: assert property (
        @(posedge clk) (!load && up_down && ($past(BCD_HIGH) == 4'd1) && ($past(BCD_LOW) == 4'd5)) |=> 
            (BCD_HIGH == 4'd0) && (BCD_LOW == 4'd0)
    );

    // Decrement wrap-around: from 0 -> 15 when counting down (no load).
    check_dec_wrap_0_to_15: assert property (
        @(posedge clk) (!load && !up_down && ($past(BCD_HIGH) == 4'd0) && ($past(BCD_LOW) == 4'd0)) |=> 
            (BCD_HIGH == 4'd1) && (BCD_LOW == 4'd5)
    );

    // Increment carry: from 9 -> 10 when counting up (no load).
    check_inc_carry_9_to_10: assert property (
        @(posedge clk) (!load && up_down && ($past(BCD_HIGH) == 4'd0) && ($past(BCD_LOW) == 4'd9)) |=> 
            (BCD_HIGH == 4'd1) && (BCD_LOW == 4'd0)
    );

    // Decrement borrow: from 10 -> 9 when counting down (no load).
    check_dec_borrow_10_to_9: assert property (
        @(posedge clk) (!load && !up_down && ($past(BCD_HIGH) == 4'd1) && ($past(BCD_LOW) == 4'd0)) |=> 
            (BCD_HIGH == 4'd0) && (BCD_LOW == 4'd9)
    );
endmodule

