    );

    full_adder fa(
        .a(a),
        .b(b),
        .cin(cin),
        .sum(sum),
        .cout(cout)
    );

    functional_module func_mod(
        .pos0(pos0),
        .pos1(pos1),
        .pos2(pos2),
        .sum(sum),
        .outv(outv)
    );

    control_logic ctrl(
        .select(select),
        .pos0_en(pos0_en),
        .pos1_en(pos1_en),
        .pos2_en(pos2_en),
        .sum_en(sum_en)
    );


endmodule

