module my_module_sva (
    input logic X,
    input logic A1,
    input logic A2
);
    // X equals logical AND of A1 and A2.
    check_and_function: assert property (
        @(posedge $global_clock) X == (A1 & A2)
    );

    // X can be 1 only when both A1 and A2 are 1.
    check_X_high_only_when_both_high: assert property (
        @(posedge $global_clock) X |-> (A1 && A2)
    );

    // If A1 is 0 then X must be 0.
    check_A1_zero_forces_X_zero: assert property (
        @(posedge $global_clock) (A1 == 1'b0) |-> (X == 1'b0)
    );

    // If A2 is 0 then X must be 0.
    check_A2_zero_forces_X_zero: assert property (
        @(posedge $global_clock) (A2 == 1'b0) |-> (X == 1'b0)
    );

    // If both inputs are 1 then X must be 1.
    check_both_ones_implies_X_one: assert property (
        @(posedge $global_clock) (A1 && A2) |-> (X == 1'b1)
    );

    // Output changes only when at least one input changes.
    check_output_change_implies_input_change: assert property (
        @(posedge $global_clock) $changed(X) |-> ($changed(A1) || $changed(A2))
    );

    // If inputs are stable then output is stable.
    check_stability_with_stable_inputs: assert property (
        @(posedge $global_clock) $stable({A1,A2}) |-> $stable(X)
    );
endmodule

module four_bit_register_sva (
  input logic CLK,
  input logic RST,
  input logic [3:0] D,
  input logic [3:0] Q
);

  ///// Reset behavior /////
  // While reset is held low across cycles, Q is 0.
  check_reset_holds_zero: assert property (
    @(posedge CLK) (!RST && $past(!RST)) |-> (Q == 4'b0)
  );

  // If reset is low this cycle, Q is 0 next cycle.
  check_reset_next_cycle_zero: assert property (
    @(posedge CLK) (!RST) |=> (Q == 4'b0)
  );

  // On reset deassertion edge, Q remains 0 in the current cycle.
  check_zero_on_reset_release_cycle: assert property (
    @(posedge CLK) $rose(RST) |-> (Q == 4'b0)
  );

  ///// Functional behavior /////
  // With reset deasserted, Q updates to D with one-cycle latency.
  check_q_follows_d_one_cycle: assert property (
    @(posedge CLK) disable iff (!RST) 1'b1 |=> (Q == $past(D))
  );

  // When not in reset, any change in Q matches the previous D.
  check_q_change_matches_prev_d: assert property (
    @(posedge CLK) disable iff (!RST) $changed(Q) |-> (Q == $past(D))
  );

  // When not in reset for two cycles and D changes, Q changes next cycle.
  check_d_change_propagates: assert property (
    @(posedge CLK) (RST && $past(RST) && (D != $past(D))) |=> (Q != $past(Q))
  );

  // When not in reset for two cycles and D is stable, Q is stable next cycle.
  check_d_stable_keeps_q_stable: assert property (
    @(posedge CLK) (RST && $past(RST) && $stable(D)) |=> (Q == $past(Q))
  );

endmodule

module clock_gate_sva (
  input logic CLK,
  input logic EN,
  input logic TE,
  input logic ENCLK
);

  // ENCLK equals EN && TE after the clock edge update.
  check_enclk_equals_en_and_te_post: assert property (
    @(posedge CLK) ##0 (ENCLK == (EN && TE))
  );

  // If both EN and TE are high at the edge, ENCLK is set high that cycle.
  check_set_when_both_high: assert property (
    @(posedge CLK) (EN && TE) |-> ##0 (ENCLK == 1'b1)
  );

  // If either EN or TE is low at the edge, ENCLK is set low that cycle.
  check_clear_when_not_both_high: assert property (
    @(posedge CLK) !(EN && TE) |-> ##0 (ENCLK == 1'b0)
  );

  // ENCLK high implies both EN and TE were high at that edge.
  check_high_implies_inputs_high: assert property (
    @(posedge CLK) ##0 (ENCLK == 1'b1) |-> (EN && TE)
  );

  // ENCLK low implies not both EN and TE were high at that edge.
  check_low_implies_not_both_high: assert property (
    @(posedge CLK) ##0 (ENCLK == 1'b0) |-> !(EN && TE)
  );

  // If EN&&TE is unchanged across edges, ENCLK holds its value across edges.
  check_hold_when_inputs_unchanged: assert property (
    @(posedge CLK) ((EN && TE) == $past(EN && TE)) |-> ##0 (ENCLK == $past(ENCLK))
  );

  // TE low at the edge forces ENCLK low that cycle.
  check_te_low_forces_low: assert property (
    @(posedge CLK) (TE == 1'b0) |-> ##0 (ENCLK == 1'b0)
  );

  // EN low at the edge forces ENCLK low that cycle.
  check_en_low_forces_low: assert property (
    @(posedge CLK) (EN == 1'b0) |-> ##0 (ENCLK == 1'b0)
  );

endmodule

