module controlunit(input [5:0] imemout, output reg brnch, output reg memorywrite, output reg memoryread, output reg alusrc, output reg regw, output reg regdst, output reg aluop, output reg memtoreg);

always @ ( imemout )
begin
	if(imemout == 6'b000000)
	begin
		brnch = 1'b0;
		memorywrite = 1'b0;
		memoryread = 1'b0;
		alusrc = 1'b0;
		regw = 1'b1;
		regdst = 1'b1;
		aluop = 1'b1;
		memtoreg = 1'b1;
	end
	else if(imemout == 6'b100011)
	begin
		brnch = 1'b0;
		memorywrite = 1'b0;
		memoryread = 1'b1;
		alusrc = 1'b1;
		regw = 1'b1;
		regdst = 1'b0;
		aluop = 1'b0;
		memtoreg = 1'b0;
	end
	else if(imemout == 6'b101011)
	begin
		brnch = 1'b0;
		memorywrite = 1'b1;
		memoryread = 1'b0;
		alusrc = 1'b1;
		regw = 1'b0;
		regdst = 1'b0;
		aluop = 1'b0;
		memtoreg = 1'b0;
	end
	else if(imemout == 6'b000100)
	begin
		brnch = 1'b1;
		memorywrite = 1'b0;
		memoryread = 1'b0;
		alusrc = 1'b0;
		regw = 1'b0;
		regdst = 1'b0;
		aluop = 1'b0;
		memtoreg = 1'b0;
	end
	else
	begin
		brnch = 1'b0;
		memorywrite = 1'b0;
		memoryread = 1'b0;
		alusrc = 1'b0;
		regw = 1'b0;
		regdst = 1'b0;
		aluop = 1'b0;
		memtoreg = 1'b0;
	end
end

endmodule

sva:
module controlunit_sva (
    // Sampling clock/reset (RTL has no clock/reset; combinational decode; used only for property sampling/masking)
    input logic clk,
    input logic reset_n,

    // DUT ports as inputs
    input logic [5:0] imemout,
    input logic brnch,
    input logic memorywrite,
    input logic memoryread,
    input logic alusrc,
    input logic regw,
    input logic regdst,
    input logic aluop,
    input logic memtoreg
);

    // Opcode aliases
    localparam logic [5:0] OP_RTYPE = 6'b000000;
    localparam logic [5:0] OP_LW    = 6'b100011;
    localparam logic [5:0] OP_SW    = 6'b101011;
    localparam logic [5:0] OP_BEQ   = 6'b000100;

    ///// Exact decode mapping /////
    // Outputs for R-type opcode (000000).
    decode_rtype_match: assert property (
        @(posedge clk) disable iff (!reset_n)
        (imemout == OP_RTYPE) |-> (brnch == 1'b0) && (memorywrite == 1'b0) && (memoryread == 1'b0) &&
                                 (alusrc == 1'b0) && (regw == 1'b1) && (regdst == 1'b1) &&
                                 (aluop == 1'b1) && (memtoreg == 1'b1)
    );

    // Outputs for LW opcode (100011).
    decode_lw_match: assert property (
        @(posedge clk) disable iff (!reset_n)
        (imemout == OP_LW) |-> (brnch == 1'b0) && (memorywrite == 1'b0) && (memoryread == 1'b1) &&
                              (alusrc == 1'b1) && (regw == 1'b1) && (regdst == 1'b0) &&
                              (aluop == 1'b0) && (memtoreg == 1'b0)
    );

    // Outputs for SW opcode (101011).
    decode_sw_match: assert property (
        @(posedge clk) disable iff (!reset_n)
        (imemout == OP_SW) |-> (brnch == 1'b0) && (memorywrite == 1'b1) && (memoryread == 1'b0) &&
                              (alusrc == 1'b1) && (regw == 1'b0) && (regdst == 1'b0) &&
                              (aluop == 1'b0) && (memtoreg == 1'b0)
    );

    // Outputs for BEQ opcode (000100).
    decode_beq_match: assert property (
        @(posedge clk) disable iff (!reset_n)
        (imemout == OP_BEQ) |-> (brnch == 1'b1) && (memorywrite == 1'b0) && (memoryread == 1'b0) &&
                              (alusrc == 1'b0) && (regw == 1'b0) && (regdst == 1'b0) &&
                              (aluop == 1'b0) && (memtoreg == 1'b0)
    );

    // Outputs for all other opcodes: all control signals LOW.
    decode_default_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (imemout != OP_RTYPE && imemout != OP_LW && imemout != OP_SW && imemout != OP_BEQ)
        |-> (brnch == 1'b0) && (memorywrite == 1'b0) && (memoryread == 1'b0) &&
            (alusrc == 1'b0) && (regw == 1'b0) && (regdst == 1'b0) &&
            (aluop == 1'b0) && (memtoreg == 1'b0)
    );

    ///// Invariants implied by the decode /////
    // Read and write to memory are never asserted together.
    check_memread_write_mutex: assert property (
        @(posedge clk) disable iff (!reset_n)
        !(memoryread && memorywrite)
    );

    // BRNCH can be HIGH only for BEQ.
    unique_brnch_on_beq: assert property (
        @(posedge clk) disable iff (!reset_n)
        brnch |-> (imemout == OP_BEQ)
    );

    // MEMORYREAD can be HIGH only for LW.
    unique_memoryread_on_lw: assert property (
        @(posedge clk) disable iff (!reset_n)
        memoryread |-> (imemout == OP_LW)
    );

    // MEMORYWRITE can be HIGH only for SW.
    unique_memorywrite_on_sw: assert property (
        @(posedge clk) disable iff (!reset_n)
        memorywrite |-> (imemout == OP_SW)
    );

    // MEMTOREG can be HIGH only for R-type.
    unique_memtoreg_on_rtype: assert property (
        @(posedge clk) disable iff (!reset_n)
        memtoreg |-> (imemout == OP_RTYPE)
    );

    // REGDST can be HIGH only for R-type.
    unique_regdst_on_rtype: assert property (
        @(posedge clk) disable iff (!reset_n)
        regdst |-> (imemout == OP_RTYPE)
    );

    // ALUOP can be HIGH only for R-type.
    unique_aluop_on_rtype: assert property (
        @(posedge clk) disable iff (!reset_n)
        aluop |-> (imemout == OP_RTYPE)
    );

    // REGW can be HIGH only for R-type or LW.
    unique_regw_on_rtype_or_lw: assert property (
        @(posedge clk) disable iff (!reset_n)
        regw |-> ((imemout == OP_RTYPE) || (imemout == OP_LW))
    );

    // ALUSRC can be HIGH only for LW or SW.
    unique_alusrc_on_lw_or_sw: assert property (
        @(posedge clk) disable iff (!reset_n)
        alusrc |-> ((imemout == OP_LW) || (imemout == OP_SW))
    );

endmodule

rtl:
module UART_Receiver #(
	parameter N    = 5,
	parameter Full = 5'd29 )(
	input Clk,
	input Reset,

	output reg [7:0]Data,
	output reg      Ready,	input           Ack,
	input 			 Rx
);
reg        tRx;
reg        tAck;
reg [  7:0]Temp;
reg [N-1:0]Count;
reg [  2:0]BitCount;
reg        NewData;
reg   [1:0]State;
localparam Idle      = 2'b00;
localparam StartBit  = 2'b01;
localparam Receiving = 2'b11;
localparam Done      = 2'b10;
reg tReset;
always @(posedge Clk) begin
	tRx    <= Rx;
	tAck   <= Ack;
	tReset <= Reset;
	if(tReset | tAck) begin
		Data    <= 0;
		Ready   <= 0;
		NewData <= 0;
		Count   <= 0;
		State   <= Idle;
		end else begin
		if(Ready & tAck) Ready <= 1'b0;	case(State)
			Idle: begin
				if(~tRx) begin
					Count <= {1'b0, Full[N-1:1]};
					State <= StartBit;	end
				if(NewData & ~tAck && ~Ready) begin 
					Data    <= Temp;
					Ready   <= 1'b1;	NewData <= 1'b0;
					Count   <= 1'b0;
				end
			end
Done: begin
				if(tRx) State <= Idle;
			end
			default:;
		endcase
if(~|Count) begin
			case(State)
				StartBit: begin
					if(Rx) begin
						State <= Idle;
					end else begin
						BitCount <= 0;
						Count    <= Full;
						State    <= Receiving;
					end
				end
Receiving: begin
					Temp  <= {tRx, Temp[7:1]};
					Count <= Full;

					if(&BitCount) begin
						NewData <= 1'b1;
						State   <= Done;
					end

					BitCount <= BitCount + 1'b1;
				end
default:;
			endcase
		end else begin
			Count <= Count - 1'b1;
		end
	end
end
endmodule

sva:
module UART_Receiver_sva (
    input logic       Clk,
    input logic       Reset,     // active-high synchronous reset in RTL (applied via tReset)
    input logic [7:0] Data,
    input logic       Ready,
    input logic       Ack,
    input logic       Rx
);
    // After previous-cycle Reset, Ready and Data must be cleared.
    check_reset_flush_outputs: assert property (
        @(posedge Clk) disable iff (Reset) $past(Reset) |-> (Ready == 1'b0) && (Data == 8'h00)
    );

    // After previous-cycle Ack, Ready and Data must be cleared.
    check_ack_flush_outputs: assert property (
        @(posedge Clk) disable iff (Reset) $past(Ack) |-> (Ready == 1'b0) && (Data == 8'h00)
    );

    // Ready cannot be high if Reset or Ack was high in the previous cycle.
    check_ready_blocked_by_prev_flush: assert property (
        @(posedge Clk) disable iff (Reset) Ready |-> (!$past(Reset) && !$past(Ack))
    );

    // If Ready and Ack are both high now, next cycle Ready/Data must clear.
    check_ready_ack_clears_next: assert property (
        @(posedge Clk) disable iff (Reset) (Ready && Ack) |=> (Ready == 1'b0) && (Data == 8'h00)
    );

    // A falling edge on Ready must be caused by previous-cycle Ack or Reset.
    check_ready_fall_requires_prev_flush: assert property (
        @(posedge Clk) disable iff (Reset) $fell(Ready) |-> ($past(Ack) || $past(Reset))
    );

    // Data may change only when Ready is asserted or when previous-cycle Ack/Reset flushed it.
    check_data_change_conditions: assert property (
        @(posedge Clk) disable iff (Reset) (Data != $past(Data)) |-> (Ready || $past(Ack) || $past(Reset))
    );

    // Once Ready is high, it stays high until a previous-cycle Ack/Reset occurs.
    check_ready_sticky_without_prev_flush: assert property (
        @(posedge Clk) disable iff (Reset) ($past(Ready) && !$past(Ack) && !$past(Reset)) |-> Ready
    );

    // While Ready remains high (and no previous-cycle Ack/Reset), Data must remain stable.
    check_data_stable_while_ready: assert property (
        @(posedge Clk) disable iff (Reset) ($past(Ready) && !$past(Ack) && !$past(Reset)) |-> (Data == $past(Data))
    );

    // Ready must not rise in the cycle after Ack was high.
    check_no_ready_rise_after_prev_ack: assert property (
        @(posedge Clk) disable iff (Reset) $past(Ack) |-> !$rose(Ready)
    );

    // Ready must not rise in the cycle after Reset was high.
    check_no_ready_rise_after_prev_reset: assert property (
        @(posedge Clk) disable iff (Reset) $past(Reset) |-> !$rose(Ready)
    );
endmodule

