module mux_2_1(input [1:0] in, input sel, output out);
  assign out = (sel == 1'b0) ? in[0] : in[1];
endmodule

sva:
module mux_2_1_sva (
    input logic [1:0] in,
    input logic sel,
    input logic out
);
    // out equals selected input (2:1 mux function) on any input or select edge.
    check_mux_function: assert property (
        @(posedge sel or negedge sel or posedge in[0] or negedge in[0] or posedge in[1] or negedge in[1])
            out == ((sel == 1'b0) ? in[0] : in[1])
    );

    // On rising sel, out reflects in[1].
    check_out_on_sel_rise: assert property (
        @(posedge sel) out == in[1]
    );

    // On falling sel, out reflects in[0].
    check_out_on_sel_fall: assert property (
        @(negedge sel) out == in[0]
    );

    // If sel is 0 and in[0] toggles, out follows in[0].
    check_out_follows_in0_when_sel0: assert property (
        @(posedge in[0] or negedge in[0]) (sel == 1'b0) |-> (out == in[0])
    );

    // If sel is 1 and in[1] toggles, out follows in[1].
    check_out_follows_in1_when_sel1: assert property (
        @(posedge in[1] or negedge in[1]) (sel == 1'b1) |-> (out == in[1])
    );

    // When both inputs are equal, out equals that common value.
    check_out_when_inputs_equal: assert property (
        @(posedge sel or negedge sel or posedge in[0] or negedge in[0] or posedge in[1] or negedge in[1])
            (in[0] == in[1]) |-> (out == in[0])
    );
endmodule

module simple_calculator_sva (
    input logic [15:0] operand_a,
    input logic [15:0] operand_b,
    input logic [1:0]  operation,
    input logic [15:0] result
);
    // No clock/reset in RTL; pure combinational. Use $global_clock for assertions.

    // Addition result matches lower 16 bits of sum when operation == 00.
    check_addition_result: assert property (
        @(posedge $global_clock) (operation == 2'b00) |-> (result == (operand_a + operand_b)[15:0])
    );

    // Subtraction result matches lower 16 bits of difference when operation == 01.
    check_subtraction_result: assert property (
        @(posedge $global_clock) (operation == 2'b01) |-> (result == (operand_a - operand_b)[15:0])
    );

    // Multiplication result matches lower 16 bits of product when operation == 10.
    check_multiplication_result: assert property (
        @(posedge $global_clock) (operation == 2'b10) |-> (result == (operand_a * operand_b)[15:0])
    );

    // Division result matches quotient when operation == 11 and divisor != 0.
    check_division_result_nonzero: assert property (
        @(posedge $global_clock) (operation == 2'b11 && (operand_b != 16'h0000)) |-> (result == (operand_a / operand_b)[15:0])
    );

    // Addition by zero returns operand_a.
    check_add_zero_identity: assert property (
        @(posedge $global_clock) (operation == 2'b00 && operand_b == 16'h0000) |-> (result == operand_a)
    );

    // Subtraction by zero returns operand_a.
    check_sub_zero_identity: assert property (
        @(posedge $global_clock) (operation == 2'b01 && operand_b == 16'h0000) |-> (result == operand_a)
    );

    // Subtraction of equal operands yields zero.
    check_sub_self_zero: assert property (
        @(posedge $global_clock) (operation == 2'b01 && operand_a == operand_b) |-> (result == 16'h0000)
    );

    // Multiplication by zero yields zero.
    check_mul_zero_annihilator: assert property (
        @(posedge $global_clock) (operation == 2'b10 && (operand_a == 16'h0000 || operand_b == 16'h0000)) |-> (result == 16'h0000)
    );

    // Multiplication by one returns operand_a.
    check_mul_one_identity: assert property (
        @(posedge $global_clock) (operation == 2'b10 && operand_b == 16'h0001) |-> (result == operand_a)
    );

    // Division by one returns operand_a.
    check_div_one_identity: assert property (
        @(posedge $global_clock) (operation == 2'b11 && operand_b == 16'h0001) |-> (result == operand_a)
    );
endmodule

module up_counter_sva (
    input logic CLK,
    input logic RST,
    input logic EN,
    input logic [3:0] Q
);

    // On reset, Q becomes zero on the next cycle.
    reset_drives_zero_next: assert property (
        @(posedge CLK) RST |=> (Q == 4'd0)
    );

    // Reset overrides EN when both are asserted.
    reset_overrides_enable: assert property (
        @(posedge CLK) (RST && EN) |=> (Q == 4'd0)
    );

    // When EN=0 and not in reset, Q holds its value.
    hold_when_en_low: assert property (
        @(posedge CLK) disable iff (RST) (!EN) |=> $stable(Q)
    );

    // When EN=1 and not in reset, Q increments by 1 modulo 16.
    increment_when_en_high: assert property (
        @(posedge CLK) disable iff (RST) EN |=> (Q == $past(Q) + 4'd1)
    );

    // If previous Q was 0xF with EN=1, next Q wraps to 0.
    wrap_from_max_on_enable: assert property (
        @(posedge CLK) disable iff (RST) (EN && ($past(Q) == 4'hF)) |=> (Q == 4'd0)
    );

    // Q changes only if EN or RST was asserted in the prior cycle.
    change_only_on_en_or_rst_prev: assert property (
        @(posedge CLK) disable iff (RST) $changed(Q) |-> $past(RST || EN)
    );

    // Without reset in prior cycle, Q either holds or increments by 1.
    at_most_one_step_no_reset: assert property (
        @(posedge CLK) disable iff (RST) $past(!RST) |-> ((Q == $past(Q)) || (Q == $past(Q) + 4'd1))
    );

endmodule

rtl:
module twos_complement (
    input [3:0] in,
    output reg [3:0] out,
    input CLK
);

    wire [3:0] not_in;

    assign not_in = ~in;          
    always @(posedge CLK) begin
        out = not_in + 4'b0001; 
    end

endmodule

sva:
module twos_complement_sva (
    input logic CLK,
    input logic [3:0] in,
    input logic [3:0] out
);
    // Clock: CLK (posedge). No reset present. Sequential reg out with 1-cycle latency; out <= (~in)+1.

    // Next cycle out equals two's complement of current in.
    property p_out_is_twos_complement;
        logic [3:0] vin;
        @(posedge CLK) (vin = in, 1'b1) ##1 (out == (~vin) + 4'd1);
    endproperty
    check_out_is_twos_complement: assert property (p_out_is_twos_complement);

    // Next cycle out plus prior in wraps to zero (mod 16).
    property p_out_plus_in_is_zero;
        logic [3:0] vin;
        @(posedge CLK) (vin = in, 1'b1) ##1 ((out + vin) == 4'd0);
    endproperty
    check_out_plus_in_zero: assert property (p_out_plus_in_is_zero);

    // If in is 0, next cycle out is 0.
    check_zero_maps_to_zero: assert property (
        @(posedge CLK) (in == 4'd0) |=> (out == 4'd0)
    );

    // If in is 8 (1000), next cycle out is also 8 (self-negating).
    check_eight_maps_to_eight: assert property (
        @(posedge CLK) (in == 4'd8) |=> (out == 4'd8)
    );

    // If in is 1, next cycle out is 15.
    check_one_maps_to_fifteen: assert property (
        @(posedge CLK) (in == 4'd1) |=> (out == 4'd15)
    );

    // If in is 15, next cycle out is 1.
    check_fifteen_maps_to_one: assert property (
        @(posedge CLK) (in == 4'd15) |=> (out == 4'd1)
    );

    // Non-zero in implies next cycle out is non-zero.
    check_nonzero_in_implies_nonzero_out: assert property (
        @(posedge CLK) (in != 4'd0) |=> (out != 4'd0)
    );

    // LSB is preserved through two's complement: if in[0]==1, next out[0]==1.
    check_lsb_preserved_one: assert property (
        @(posedge CLK) (in[0] == 1'b1) |=> (out[0] == 1'b1)
    );

    // LSB is preserved through two's complement: if in[0]==0, next out[0]==0.
    check_lsb_preserved_zero: assert property (
        @(posedge CLK) (in[0] == 1'b0) |=> (out[0] == 1'b0)
    );

endmodule

rtl:
module sky130_fd_sc_hd__o2bb2a (
    input  A1_N,
    input  A2_N,
    input  B1  ,
    input  B2  ,
    output X
);

    // Implement the logic for the module
    assign X = (A1_N == 1) && (A2_N == 0) && (B1 == 1) && (B2 == 0);

endmodule

sva:
module sky130_fd_sc_hd__o2bb2a_sva (
    input  logic CLK,   // external sample clock for assertions
    input  logic A1_N,
    input  logic A2_N,
    input  logic B1,
    input  logic B2,
    input  logic X
);
    // X implements A1_N & ~A2_N & B1 & ~B2.
    check_functional_equivalence: assert property (
        @(posedge CLK) X == (A1_N && !A2_N && B1 && !B2)
    );

    // X can be 1 only when the input pattern holds.
    check_x_high_requires_pattern: assert property (
        @(posedge CLK) X |-> (A1_N && !A2_N && B1 && !B2)
    );

    // When the input pattern holds, X must be 1.
    check_pattern_implies_x_high: assert property (
        @(posedge CLK) (A1_N && !A2_N && B1 && !B2) |-> X
    );

    // A1_N low forces X low.
    check_a1n_zero_forces_x_zero: assert property (
        @(posedge CLK) !A1_N |-> !X
    );

    // A2_N high forces X low.
    check_a2n_one_forces_x_zero: assert property (
        @(posedge CLK) A2_N |-> !X
    );

    // B1 low forces X low.
    check_b1_zero_forces_x_zero: assert property (
        @(posedge CLK) !B1 |-> !X
    );

    // B2 high forces X low.
    check_b2_one_forces_x_zero: assert property (
        @(posedge CLK) B2 |-> !X
    );

    // If inputs are stable, X is stable.
    check_x_stable_when_inputs_stable: assert property (
        @(posedge CLK) ($stable(A1_N) && $stable(A2_N) && $stable(B1) && $stable(B2)) |-> $stable(X)
    );

    // Leaving the pattern via A1_N going low makes X low next cycle.
    check_leave_pattern_via_a1n_drop: assert property (
        @(posedge CLK) (A1_N && !A2_N && B1 && !B2) ##1 (!A1_N) |-> !X
    );

    // Leaving the pattern via A2_N going high makes X low next cycle.
    check_leave_pattern_via_a2n_rise: assert property (
        @(posedge CLK) (A1_N && !A2_N && B1 && !B2) ##1 (A2_N) |-> !X
    );

    // Leaving the pattern via B1 going low makes X low next cycle.
    check_leave_pattern_via_b1_drop: assert property (
        @(posedge CLK) (A1_N && !A2_N && B1 && !B2) ##1 (!B1) |-> !X
    );

    // Leaving the pattern via B2 going high makes X low next cycle.
    check_leave_pattern_via_b2_rise: assert property (
        @(posedge CLK) (A1_N && !A2_N && B1 && !B2) ##1 (B2) |-> !X
    );
endmodule

rtl:
module sparc_exu_aluspr(
   spr_out, 
   rs1_data, rs2_data, cin
   );

input [63:0] rs1_data;
input [63:0] rs2_data;
   input     cin;
output [63:0] spr_out;

wire [63:0] rs1_data_xor_rs2_data;
wire [62:0] rs1_data_or_rs2_data;
wire [63:0] shift_or;

assign rs1_data_xor_rs2_data[63:0] = rs1_data[63:0] ^ rs2_data[63:0];
assign rs1_data_or_rs2_data[62:0] = rs1_data[62:0] | rs2_data[62:0];
assign shift_or[63:0] = {rs1_data_or_rs2_data[62:0],cin};

assign spr_out[63:0] = rs1_data_xor_rs2_data[63:0] ^ shift_or[63:0];

endmodule

sva:
module sparc_exu_aluspr_sva (
    input logic [63:0] rs1_data,
    input logic [63:0] rs2_data,
    input logic        cin,
    input logic [63:0] spr_out
);
    // spr_out equals (rs1_data ^ rs2_data) ^ { (rs1_data[62:0] | rs2_data[62:0]), cin }.
    check_result_definition: assert property (
        @($global_clock) spr_out == ((rs1_data ^ rs2_data) ^ { (rs1_data[62:0] | rs2_data[62:0]), cin })
    );

    // High bits do not depend on cin explicitly.
    check_high_bits_independence: assert property (
        @($global_clock) spr_out[63:1] == ((rs1_data[63:1] ^ rs2_data[63:1]) ^ (rs1_data[62:0] | rs2_data[62:0]))
    );

    // Bit 0 equals (rs1_data[0] ^ rs2_data[0]) ^ cin.
    check_bit0_definition: assert property (
        @($global_clock) spr_out[0] == ((rs1_data[0] ^ rs2_data[0]) ^ cin)
    );

    // Bit 1 equals (rs1_data[1] ^ rs2_data[1]) ^ (rs1_data[0] | rs2_data[0]).
    check_bit1_definition: assert property (
        @($global_clock) spr_out[1] == ((rs1_data[1] ^ rs2_data[1]) ^ (rs1_data[0] | rs2_data[0]))
    );

    // Bit 63 equals (rs1_data[63] ^ rs2_data[63]) ^ (rs1_data[62] | rs2_data[62]).
    check_bit63_definition: assert property (
        @($global_clock) spr_out[63] == ((rs1_data[63] ^ rs2_data[63]) ^ (rs1_data[62] | rs2_data[62]))
    );

    // spr_out ^ (rs1_data ^ rs2_data) equals the shifted OR vector.
    check_xor_vs_shiftor: assert property (
        @($global_clock) (spr_out ^ (rs1_data ^ rs2_data)) == { (rs1_data[62:0] | rs2_data[62:0]), cin }
    );

    // Changing cin alone only affects spr_out[0] (upper bits stay stable).
    check_cin_only_affects_bit0_upper_stable: assert property (
        @($global_clock) $changed(cin) && $stable(rs1_data) && $stable(rs2_data) |-> $stable(spr_out[63:1])
    );

    // Changing cin alone causes spr_out[0] to change.
    check_cin_changes_bit0: assert property (
        @($global_clock) $changed(cin) && $stable(rs1_data) && $stable(rs2_data) |-> $changed(spr_out[0])
    );

    // If all inputs are stable, spr_out remains stable.
    check_output_stable_when_inputs_stable: assert property (
        @($global_clock) $stable(rs1_data) && $stable(rs2_data) && $stable(cin) |-> $stable(spr_out)
    );

    // When rs1_data == rs2_data, spr_out equals the shifted OR vector directly.
    check_equal_inputs_reduce_to_shiftor: assert property (
        @($global_clock) (rs1_data == rs2_data) |-> (spr_out == { (rs1_data[62:0] | rs2_data[62:0]), cin })
    );
endmodule

