sva:
module sky130_fd_sc_hd__o21ai_sva (
    input  logic CLK,  // verification clock (RTL has no clock/reset)
    input  logic Y,
    input  logic A1,
    input  logic A2,
    input  logic B1
);
    // Function: Y = ~(B1 & (A1 | A2))

    // Y must equal the combinational function.
    check_function_equivalence: assert property (
        @(posedge CLK) Y == ~(B1 & (A1 | A2))
    );

    // B1 low forces Y high.
    check_B1_low_forces_Y_high: assert property (
        @(posedge CLK) (B1 == 1'b0) |-> (Y == 1'b1)
    );

    // Both A1 and A2 low force Y high.
    check_A_both_low_forces_Y_high: assert property (
        @(posedge CLK) ((A1 == 1'b0) && (A2 == 1'b0)) |-> (Y == 1'b1)
    );

    // B1 high and any A high force Y low.
    check_B1_high_and_any_A_high_forces_Y_low: assert property (
        @(posedge CLK) (B1 == 1'b1) && ((A1 == 1'b1) || (A2 == 1'b1)) |-> (Y == 1'b0)
    );

    // B1 high with both A low forces Y high.
    check_B1_high_and_A_both_low_forces_Y_high: assert property (
        @(posedge CLK) (B1 == 1'b1) && (A1 == 1'b0) && (A2 == 1'b0) |-> (Y == 1'b1)
    );

    // If inputs are stable, Y must be stable (pure combinational).
    check_stable_when_inputs_stable: assert property (
        @(posedge CLK) $stable(A1) && $stable(A2) && $stable(B1) |-> $stable(Y)
    );

    // Y low implies B1 is high and at least one A is high.
    check_Y_low_implies_inputs_conditions: assert property (
        @(posedge CLK) (Y == 1'b0) |-> (B1 == 1'b1) && ((A1 == 1'b1) || (A2 == 1'b1))
    );

    // Y high implies B1 is low or both A are low.
    check_Y_high_implies_inputs_conditions: assert property (
        @(posedge CLK) (Y == 1'b1) |-> ((B1 == 1'b0) || ((A1 == 1'b0) && (A2 == 1'b0)))
    );

    // Rising B1 with any A high drives Y low.
    check_rise_B1_with_any_A_high: assert property (
        @(posedge CLK) $rose(B1) && ((A1 == 1'b1) || (A2 == 1'b1)) |-> (Y == 1'b0)
    );

    // Rising B1 with both A low drives Y high.
    check_rise_B1_with_A_both_low: assert property (
        @(posedge CLK) $rose(B1) && (A1 == 1'b0) && (A2 == 1'b0) |-> (Y == 1'b1)
    );
endmodule

rtl:
module sky130_fd_sc_hs__fa (input A, input B, input CIN, input VPWR, input VGND, output COUT, output SUM);

    reg temp_COUT; // temporary variable to store the value of COUT
    reg temp_SUM; // temporary variable to store the value of SUM

    always @(*) begin
        if((A == 1'b0 || A == 1'b1) && (B == 1'b0 || B == 1'b1) && (CIN == 1'b0 || CIN == 1'b1)) begin
            temp_SUM = A ^ B ^ CIN;
            temp_COUT = (A & B) | (B & CIN) | (CIN & A);
        end
        else begin
            temp_SUM = 1'bx;
            temp_COUT = 1'bx;
        end
    end

    assign SUM = temp_SUM;
    assign COUT = temp_COUT;

endmodule

sva:
module sky130_fd_sc_hs__fa_sva (
    input logic CLK,
    input logic A,
    input logic B,
    input logic CIN,
    input logic VPWR,
    input logic VGND,
    input logic COUT,
    input logic SUM
);
    ///// Functional correctness for known inputs /////
    // With known inputs, SUM equals A ^ B ^ CIN.
    check_sum_matches_xor_when_known: assert property (
        @(posedge CLK) (!$isunknown({A,B,CIN})) |-> (SUM == (A ^ B ^ CIN))
    );
    // With known inputs, COUT equals (A&B) | (B&CIN) | (CIN&A).
    check_cout_matches_majority_when_known: assert property (
        @(posedge CLK) (!$isunknown({A,B,CIN})) |-> (COUT == ((A & B) | (B & CIN) | (CIN & A)))
    );

    ///// X-propagation /////
    // Any unknown on A/B/CIN drives SUM and COUT unknown.
    check_unknown_input_forces_unknown_outputs: assert property (
        @(posedge CLK) ($isunknown(A) || $isunknown(B) || $isunknown(CIN)) |-> ($isunknown(SUM) && $isunknown(COUT))
    );
    // Known A/B/CIN imply SUM and COUT are not unknown.
    check_outputs_known_if_inputs_known: assert property (
        @(posedge CLK) (!$isunknown({A,B,CIN})) |-> (!$isunknown({SUM,COUT}))
    );

    ///// Combinational stability /////
    // If A/B/CIN are stable, SUM/COUT remain stable.
    check_outputs_stable_when_inputs_stable: assert property (
        @(posedge CLK) $stable({A,B,CIN}) |-> $stable({SUM,COUT})
    );
    // Any change on SUM/COUT must be due to a change on A/B/CIN.
    check_output_change_requires_input_change: assert property (
        @(posedge CLK) $changed({SUM,COUT}) |-> !$stable({A,B,CIN})
    );

    ///// Truth table spots (for known inputs) /////
    // 000 -> SUM=0, COUT=0.
    truth_all_zeros: assert property (
        @(posedge CLK) (A==1'b0 && B==1'b0 && CIN==1'b0) |-> (SUM==1'b0 && COUT==1'b0)
    );
    // Exactly one high -> SUM=1, COUT=0.
    truth_exactly_one_high: assert property (
        @(posedge CLK)
        (
            (A==1'b1 && B==1'b0 && CIN==1'b0) ||
            (A==1'b0 && B==1'b1 && CIN==1'b0) ||
            (A==1'b0 && B==1'b0 && CIN==1'b1)
        ) |-> (SUM==1'b1 && COUT==1'b0)
    );
    // Exactly two high -> SUM=0, COUT=1.
    truth_exactly_two_high: assert property (
        @(posedge CLK)
        (
            (A==1'b1 && B==1'b1 && CIN==1'b0) ||
            (A==1'b1 && B==1'b0 && CIN==1'b1) ||
            (A==1'b0 && B==1'b1 && CIN==1'b1)
        ) |-> (SUM==1'b0 && COUT==1'b1)
    );
    // 111 -> SUM=1, COUT=1.
    truth_all_ones: assert property (
        @(posedge CLK) (A==1'b1 && B==1'b1 && CIN==1'b1) |-> (SUM==1'b1 && COUT==1'b1)
    );
endmodule

rtl:
module adder_4bit (
    input [3:0] A,
    input [3:0] B,
    input CIN,
    output [3:0] SUM,
    output COUT
);

    wire [3:0] sum;
    wire [4:0] carry;

    full_adder fa0(A[0], B[0], CIN, sum[0], carry[0]);
    full_adder fa1(A[1], B[1], carry[0], sum[1], carry[1]);
    full_adder fa2(A[2], B[2], carry[1], sum[2], carry[2]);
    full_adder fa3(A[3], B[3], carry[2], sum[3], carry[3]);

    assign SUM = sum;
    assign COUT = carry[3]; // Change here: was carry[4]

endmodule
module full_adder (
    input A,
    input B,
    input CIN,
    output SUM,
    output COUT
);

    assign SUM = A ^ B ^ CIN;
    assign COUT = (A & B) | (B & CIN) | (CIN & A);

endmodule

sva:
module adder_4bit_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic CIN,
    input logic [3:0] SUM,
    input logic COUT
);
    // No clock/reset in DUT; purely combinational. Sample on posedges of any input.

    // Helper carry chain expressions (combinational).
    let c1 = (A[0] & B[0]) | (A[0] & CIN) | (B[0] & CIN);
    let c2 = (A[1] & B[1]) | (A[1] & c1) | (B[1] & c1);
    let c3 = (A[2] & B[2]) | (A[2] & c2) | (B[2] & c2);
    let c4 = (A[3] & B[3]) | (A[3] & c3) | (B[3] & c3);

    ///// Functional correctness /////
    // Full 5-bit sum equals A + B + CIN.
    check_fullsum_vector: assert property (
        @(posedge A[0] or posedge A[1] or posedge A[2] or posedge A[3] or
          posedge B[0] or posedge B[1] or posedge B[2] or posedge B[3] or
          posedge CIN)
        {COUT, SUM} == ({1'b0, A} + {1'b0, B} + CIN)
    );

    // LSB SUM bit is XOR of A[0], B[0], and CIN.
    check_sum0_xor: assert property (
        @(posedge A[0] or posedge A[1] or posedge A[2] or posedge A[3] or
          posedge B[0] or posedge B[1] or posedge B[2] or posedge B[3] or
          posedge CIN)
        SUM[0] == (A[0] ^ B[0] ^ CIN)
    );

    // SUM[1] uses ripple carry c1.
    check_sum1_ripple: assert property (
        @(posedge A[0] or posedge A[1] or posedge A[2] or posedge A[3] or
          posedge B[0] or posedge B[1] or posedge B[2] or posedge B[3] or
          posedge CIN)
        SUM[1] == (A[1] ^ B[1] ^ c1)
    );

    // SUM[2] uses ripple carry c2.
    check_sum2_ripple: assert property (
        @(posedge A[0] or posedge A[1] or posedge A[2] or posedge A[3] or
          posedge B[0] or posedge B[1] or posedge B[2] or posedge B[3] or
          posedge CIN)
        SUM[2] == (A[2] ^ B[2] ^ c2)
    );

    // SUM[3] uses ripple carry c3.
    check_sum3_ripple: assert property (
        @(posedge A[0] or posedge A[1] or posedge A[2] or posedge A[3] or
          posedge B[0] or posedge B[1] or posedge B[2] or posedge B[3] or
          posedge CIN)
        SUM[3] == (A[3] ^ B[3] ^ c3)
    );

    // Final carry-out equals ripple carry c4.
    check_cout_ripple: assert property (
        @(posedge A[0] or posedge A[1] or posedge A[2] or posedge A[3] or
          posedge B[0] or posedge B[1] or posedge B[2] or posedge B[3] or
          posedge CIN)
        COUT == c4
    );

    ///// Useful corner cases /////
    // With CIN == 0, sum equals A + B.
    check_no_cin_sum: assert property (
        @(posedge A[0] or posedge A[1] or posedge A[2] or posedge A[3] or
          posedge B[0] or posedge B[1] or posedge B[2] or posedge B[3] or
          posedge CIN)
        (CIN == 1'b0) |-> ({COUT, SUM} == ({1'b0, A} + {1'b0, B}))
    );

    // When B == 0 and CIN == 0, SUM passes A and COUT is 0.
    check_pass_A_when_B0_CIN0: assert property (
        @(posedge A[0] or posedge A[1] or posedge A[2] or posedge A[3] or
          posedge B[0] or posedge B[1] or posedge B[2] or posedge B[3] or
          posedge CIN)
        ((B == 4'b0000) && (CIN == 1'b0)) |-> ((SUM == A) && (COUT == 1'b0))
    );

    // When A == 0 and CIN == 0, SUM passes B and COUT is 0.
    check_pass_B_when_A0_CIN0: assert property (
        @(posedge A[0] or posedge A[1] or posedge A[2] or posedge A[3] or
          posedge B[0] or posedge B[1] or posedge B[2] or posedge B[3] or
          posedge CIN)
        ((A == 4'b0000) && (CIN == 1'b0)) |-> ((SUM == B) && (COUT == 1'b0))
    );

    // When A == 0 and B == 0, SUM equals CIN in bit0 and COUT is 0.
    check_zero_plus_zero: assert property (
        @(posedge A[0] or posedge A[1] or posedge A[2] or posedge A[3] or
          posedge B[0] or posedge B[1] or posedge B[2] or posedge B[3] or
          posedge CIN)
        ((A == 4'b0000) && (B == 4'b0000)) |-> ((SUM == {3'b000, CIN}) && (COUT == 1'b0))
    );

    // COUT is 1 iff the 5-bit sum overflows 4 bits (>= 16).
    check_cout_on_overflow: assert property (
        @(posedge A[0] or posedge A[1] or posedge A[2] or posedge A[3] or
          posedge B[0] or posedge B[1] or posedge B[2] or posedge B[3] or
          posedge CIN)
        (({1'b0, A} + {1'b0, B} + CIN) >= 5'd16) |-> (COUT == 1'b1)
    );

    // No overflow implies COUT is 0.
    check_cout_no_overflow: assert property (
        @(posedge A[0] or posedge A[1] or posedge A[2] or posedge A[3] or
          posedge B[0] or posedge B[1] or posedge B[2] or posedge B[3] or
          posedge CIN)
        (({1'b0, A} + {1'b0, B} + CIN) <= 5'd15) |-> (COUT == 1'b0)
    );
endmodule

rtl:
module four_bit_adder(
  input [3:0] A,
  input [3:0] B,
  input Cin,
  output [3:0] S,
  output Cout
);

  wire [3:0] sum;
  wire [3:0] carry;

  // First bit of sum and carry
  full_adder fa0(A[0], B[0], Cin, sum[0], carry[0]);

  // Subsequent bits of sum and carry
  full_adder fa1(A[1], B[1], carry[0], sum[1], carry[1]);
  full_adder fa2(A[2], B[2], carry[1], sum[2], carry[2]);
  full_adder fa3(A[3], B[3], carry[2], sum[3], Cout);

  assign S = sum;

endmodule

module full_adder(
  input A,
  input B,
  input Cin,
  output S,
  output Cout
);

  wire s1, s2, c1, c2;

  // First stage
  xor(s1, A, B);
  xor(S, s1, Cin);

  // Second stage
  and(c1, A, B);
  and(c2, s1, Cin);
  or(Cout, c1, c2);

endmodule

sva:
module four_bit_adder_sva (
    input  logic        clk,
    input  logic        reset_n,
    input  logic [3:0]  A,
    input  logic [3:0]  B,
    input  logic        Cin,
    input  logic [3:0]  S,
    input  logic        Cout
);
    // Helper: expected 5-bit sum of A+B+Cin
    logic [4:0] expected_sum;
    assign expected_sum = A + B + Cin;

    // Helper: ripple carry chain derived from inputs
    logic c1, c2, c3;
    assign c1 = (A[0] & B[0]) | ((A[0] ^ B[0]) & Cin);
    assign c2 = (A[1] & B[1]) | ((A[1] ^ B[1]) & c1);
    assign c3 = (A[2] & B[2]) | ((A[2] ^ B[2]) & c2);

    // Sum and carry match arithmetic addition.
    check_full_sum_matches_addition: assert property (
        @(posedge clk) disable iff (!reset_n)
        {Cout, S} == expected_sum
    );

    // LSB sum is XOR of A[0], B[0], and Cin.
    check_bit0_sum_xor: assert property (
        @(posedge clk) disable iff (!reset_n)
        S[0] == (A[0] ^ B[0] ^ Cin)
    );

    // Bit1 sum equals XOR of A[1], B[1], and carry from bit0.
    check_bit1_sum_with_c1: assert property (
        @(posedge clk) disable iff (!reset_n)
        S[1] == (A[1] ^ B[1] ^ c1)
    );

    // Bit2 sum equals XOR of A[2], B[2], and carry from bit1.
    check_bit2_sum_with_c2: assert property (
        @(posedge clk) disable iff (!reset_n)
        S[2] == (A[2] ^ B[2] ^ c2)
    );

    // Bit3 sum equals XOR of A[3], B[3], and carry from bit2.
    check_bit3_sum_with_c3: assert property (
        @(posedge clk) disable iff (!reset_n)
        S[3] == (A[3] ^ B[3] ^ c3)
    );

    // Final carry-out equals ripple-carry from bit3.
    check_cout_ripple_formula: assert property (
        @(posedge clk) disable iff (!reset_n)
        Cout == ((A[3] & B[3]) | ((A[3] ^ B[3]) & c3))
    );

    // Outputs remain stable when inputs remain stable.
    check_outputs_stable_when_inputs_stable: assert property (
        @(posedge clk) disable iff (!reset_n)
        $stable({A, B, Cin}) |-> $stable({S, Cout})
    );

    // Output change implies at least one input changed.
    check_output_change_implies_input_change: assert property (
        @(posedge clk) disable iff (!reset_n)
        !$stable({S, Cout}) |-> !$stable({A, B, Cin})
    );

    // Adding zero to zero yields Cout=0, S[3:1]=0, and S[0]=Cin.
    check_zero_plus_zero_behavior: assert property (
        @(posedge clk) disable iff (!reset_n)
        (A == 4'b0000 && B == 4'b0000) |-> (Cout == 1'b0) && (S[3:1] == 3'b000) && (S[0] == Cin)
    );

    // When both operands are max (0xF), carry-out must be 1 regardless of Cin.
    check_cout_high_when_both_max: assert property (
        @(posedge clk) disable iff (!reset_n)
        (A == 4'hF && B == 4'hF) |-> (Cout == 1'b1)
    );
endmodule

rtl:
module shifter(
    output [31:0] dout,
    input [31:0] A,
    input [31:0] B,
    input [1:0] ctrl
);

wire [31:0] dout_16, dout_8, dout_4, dout_2;

fix_shifter #(16) shifter_16(dout_16, B, ctrl, A[4]);
fix_shifter #(8) shifter_8(dout_8, dout_16, ctrl, A[3]);
fix_shifter #(4) shifter_4(dout_4, dout_8, ctrl, A[2]);
fix_shifter #(2) shifter_2(dout_2, dout_4, ctrl, A[1]);
fix_shifter #(1) shifter_1(dout, dout_2, ctrl, A[0]);

endmodule


module fix_shifter(
    output reg [31:0] dout,
    input [31:0] B,
    input [1:0] ctrl,
    input enable
);

parameter SHIFT_AMOUNT = 1;

wire signed [31:0] signedB = B;

always @(*) begin
    if (enable)
        case (ctrl)
            2'b00:  dout = B << SHIFT_AMOUNT;
            2'b01:  dout = B >> SHIFT_AMOUNT;
            2'b11:  dout = signedB >>> SHIFT_AMOUNT;
            default:
                dout = B;
        endcase
    else
        dout = B;
end

endmodule

sva:
module shifter_sva (
    input logic CLK,
    input logic [31:0] dout,
    input logic [31:0] A,
    input logic [31:0] B,
    input logic [1:0] ctrl
);
    // ctrl=00: dout equals B left-shifted by A[4:0].
    check_left_shift_correctness: assert property (
        @(posedge CLK) (ctrl == 2'b00) |-> (dout == (B << A[4:0]))
    );

    // ctrl=01: dout equals B logical-right-shifted by A[4:0].
    check_right_logical_shift_correctness: assert property (
        @(posedge CLK) (ctrl == 2'b01) |-> (dout == (B >> A[4:0]))
    );

    // ctrl=11: dout equals B arithmetic-right-shifted by A[4:0].
    check_right_arith_shift_correctness: assert property (
        @(posedge CLK) (ctrl == 2'b11) |-> (dout == ($signed(B) >>> A[4:0]))
    );

    // ctrl=10 (default): dout passes B unchanged.
    check_noop_ctrl_10_outputs_input: assert property (
        @(posedge CLK) (ctrl == 2'b10) |-> (dout == B)
    );

    // Zero shift amount yields passthrough regardless of ctrl.
    check_zero_shift_amount_no_change: assert property (
        @(posedge CLK) (A[4:0] == 5'd0) |-> (dout == B)
    );

    // Left shift with nonzero amount forces LSB to 0.
    check_left_shift_lsb_zero: assert property (
        @(posedge CLK) (ctrl == 2'b00 && (A[4:0] != 5'd0)) |-> (dout[0] == 1'b0)
    );

    // Logical right shift with nonzero amount forces MSB to 0.
    check_logical_right_msb_zero: assert property (
        @(posedge CLK) (ctrl == 2'b01 && (A[4:0] != 5'd0)) |-> (dout[31] == 1'b0)
    );

    // Arithmetic right shift with nonzero amount preserves sign bit.
    check_arith_right_sign_preserved: assert property (
        @(posedge CLK) (ctrl == 2'b11 && (A[4:0] != 5'd0)) |-> (dout[31] == B[31])
    );

    // Zero data input always yields zero output.
    check_zero_data_maps_to_zero: assert property (
        @(posedge CLK) (B == 32'h0) |-> (dout == 32'h0)
    );

    // Full functional spec matches ctrl selection and A[4:0] shift amount.
    check_full_functional_spec: assert property (
        @(posedge CLK)
            dout == ((ctrl == 2'b00) ? (B << A[4:0]) :
                     (ctrl == 2'b01) ? (B >> A[4:0]) :
                     (ctrl == 2'b11) ? ($signed(B) >>> A[4:0]) :
                                       B)
    );
endmodule

rtl:
module calculator(input [7:0] num1, num2, input control, output reg [7:0] result, output reg carry);
    reg [8:0] temp;

    always @(*) begin
        if (control == 1'b0) begin  // addition operation
            temp = num1 + num2;
            carry = temp[8];
            result = temp[7:0];
        end
        else begin  // subtraction operation
            temp = num1 - num2;
            carry = temp[8];
            result = temp[7:0];
        end
    end
endmodule

sva:
module calculator_sva (
    input logic CLK,
    input logic [7:0] num1,
    input logic [7:0] num2,
    input logic control,
    input logic [7:0] result,
    input logic carry
);

    ///// Core functionality /////
    // When control==0, outputs equal 9-bit unsigned addition.
    check_add_operation: assert property (
        @(posedge CLK) (control == 1'b0) |-> ({carry, result} == ({1'b0, num1} + {1'b0, num2}))
    );

    // When control==1, outputs equal 9-bit unsigned subtraction.
    check_sub_operation: assert property (
        @(posedge CLK) (control == 1'b1) |-> ({carry, result} == ({1'b0, num1} - {1'b0, num2}))
    );

    ///// Carry/borrow semantics /////
    // In addition mode, carry equals MSB of 9-bit sum.
    check_add_carry_bit: assert property (
        @(posedge CLK) (control == 1'b0) |-> (carry == (({1'b0, num1} + {1'b0, num2})[8]))
    );

    // In subtraction mode, carry indicates borrow (num1 < num2).
    check_sub_borrow_flag: assert property (
        @(posedge CLK) (control == 1'b1) |-> (carry == (num1 < num2))
    );

    ///// Simple algebraic corollaries /////
    // Addition by zero passes through num2 with no carry.
    check_add_zero_num1: assert property (
        @(posedge CLK) (control == 1'b0 && (num1 == 8'h00)) |-> (result == num2 && carry == 1'b0)
    );

    // Addition by zero passes through num1 with no carry.
    check_add_zero_num2: assert property (
        @(posedge CLK) (control == 1'b0 && (num2 == 8'h00)) |-> (result == num1 && carry == 1'b0)
    );

    // Subtraction by zero passes through num1 with no borrow.
    check_sub_zero_num2: assert property (
        @(posedge CLK) (control == 1'b1 && (num2 == 8'h00)) |-> (result == num1 && carry == 1'b0)
    );

    // Subtraction of equal operands yields zero with no borrow.
    check_sub_equal_operands: assert property (
        @(posedge CLK) (control == 1'b1 && (num1 == num2)) |-> (result == 8'h00 && carry == 1'b0)
    );

    ///// Edge-case spot checks /////
    // 0xFF + 0x01 => 0x00 with carry 1 in addition mode.
    check_add_overflow_case: assert property (
        @(posedge CLK) (control == 1'b0 && num1 == 8'hFF && num2 == 8'h01) |-> (result == 8'h00 && carry == 1'b1)
    );

    // 0x00 - 0x01 => 0xFF with borrow (carry=1) in subtraction mode.
    check_sub_borrow_case: assert property (
        @(posedge CLK) (control == 1'b1 && num1 == 8'h00 && num2 == 8'h01) |-> (result == 8'hFF && carry == 1'b1)
    );

endmodule

rtl:
module four_bit_adder (
    input [3:0] A,
    input [3:0] B,
    input CLK,
    input RST,
    output reg [3:0] C
);

    wire [3:0] sum;
    wire [3:0] carry;

endmodule

module full_adder (
    input A,
    input B,
    input CIN,
    output COUT,
    output SUM
);
    assign SUM = A ^ B ^ CIN; // XOR gate for sum
    assign COUT = (A & B) | (B & CIN) | (A & CIN); // OR gate for carry
endmodule

sva:
module full_adder_sva (
    input  logic CLK,
    input  logic RST,   // active-high reset used only to gate assertions
    input  logic A,
    input  logic B,
    input  logic CIN,
    input  logic COUT,
    input  logic SUM
);
    // SUM equals XOR of inputs.
    check_sum_xor: assert property (
        @(posedge CLK) disable iff (RST) SUM == (A ^ B ^ CIN)
    );

    // COUT equals majority function of inputs.
    check_carry_majority: assert property (
        @(posedge CLK) disable iff (RST) COUT == ((A & B) | (B & CIN) | (A & CIN))
    );

    // {COUT,SUM} equals the 2-bit arithmetic sum of A+B+CIN.
    check_add_equivalence: assert property (
        @(posedge CLK) disable iff (RST) {COUT, SUM} == ({1'b0,A} + {1'b0,B} + {1'b0,CIN})
    );

    // When A equals B, SUM mirrors CIN.
    check_sum_when_inputs_equal: assert property (
        @(posedge CLK) disable iff (RST) (A == B) |-> (SUM == CIN)
    );

    // All inputs zero produce outputs 00.
    check_zero_input_case: assert property (
        @(posedge CLK) disable iff (RST) (!A && !B && !CIN) |-> ({COUT, SUM} == 2'b00)
    );

    // Exactly one input high produces outputs 01.
    check_onehot_case: assert property (
        @(posedge CLK) disable iff (RST) $onehot({A,B,CIN}) |-> ({COUT, SUM} == 2'b01)
    );

    // Exactly two inputs high produce outputs 10.
    check_twohot_case: assert property (
        @(posedge CLK) disable iff (RST) ($countones({A,B,CIN}) == 2) |-> ({COUT, SUM} == 2'b10)
    );

    // All three inputs high produce outputs 11.
    check_all_ones_case: assert property (
        @(posedge CLK) disable iff (RST) (A && B && CIN) |-> ({COUT, SUM} == 2'b11)
    );

    // Carry must be 1 when at least two inputs are 1.
    check_carry_ge_two_ones: assert property (
        @(posedge CLK) disable iff (RST) ($countones({A,B,CIN}) >= 2) |-> (COUT == 1'b1)
    );

    // Carry must be 0 when zero or one input is 1.
    check_carry_le_one_one: assert property (
        @(posedge CLK) disable iff (RST) ($countones({A,B,CIN}) <= 1) |-> (COUT == 1'b0)
    );
endmodule

