sva:
module mux2to1_sva (
    input logic clk,
    input logic [31:0] a,
    input logic [31:0] b,
    input logic sel,
    input logic [31:0] c
);
    // Mux output must equal selected input.
    check_mux_function: assert property (
        @(posedge clk) c == (sel ? b : a)
    );

    // When sel==0, output equals a.
    check_sel0_path: assert property (
        @(posedge clk) (sel == 1'b0) |-> (c == a)
    );

    // When sel==1, output equals b.
    check_sel1_path: assert property (
        @(posedge clk) (sel == 1'b1) |-> (c == b)
    );

    // If inputs are equal, output equals that value regardless of sel.
    check_equal_inputs_force_equal_output: assert property (
        @(posedge clk) (a == b) |-> (c == a)
    );

    // If output differs from a, selection must be b and b must differ from a.
    check_output_diff_from_a_implies_select_b: assert property (
        @(posedge clk) (c != a) |-> (sel && (b != a))
    );

    // If output differs from b, selection must be a and a must differ from b.
    check_output_diff_from_b_implies_select_a: assert property (
        @(posedge clk) (c != b) |-> (!sel && (a != b))
    );
endmodule

rtl:
module pwm_fade (clk, trigger, drive);
   input trigger;
   input clk;
   output drive;

   `define FADE_BITS 27
   parameter LEVEL_BITS = 8;

   parameter LOCAL_MINERS = 1;
   reg [LEVEL_BITS-1:0] pwm_counter = 0;
   always @(posedge clk) pwm_counter = pwm_counter + 1;

   reg [`FADE_BITS-1:0] fade_counter = 0;
   always @(posedge clk)
     if (trigger) fade_counter = 0 - 1;
     else if (|fade_counter) fade_counter = fade_counter - 1;

   wire [LEVEL_BITS-1:0] level;
   assign level = fade_counter[`FADE_BITS-1:`FADE_BITS-LEVEL_BITS];

   assign drive = (pwm_counter < level);

endmodule

sva:
module pwm_fade_sva #(
    parameter int LEVEL_BITS = 8,
    parameter int FADE_BITS  = 27
) (
    // DUT ports
    input  logic                       clk,
    input  logic                       trigger,
    input  logic                       drive,
    // Internal DUT signals (bind these from the instance)
    input  logic [LEVEL_BITS-1:0]      pwm_counter,
    input  logic [FADE_BITS-1:0]       fade_counter,
    input  logic [LEVEL_BITS-1:0]      level
);
    // Clock: clk; no reset present in RTL.
    // Logic: mixed (sequential counters, combinational compare/slice).
    // Behavior: pwm_counter++ each clk; trigger reloads fade_counter to all 1s, else it counts down to 0; level = MSBs of fade_counter; drive = (pwm_counter < level).

    localparam logic [FADE_BITS-1:0]  FADE_ALL_ONES = {FADE_BITS{1'b1}};
    localparam logic [LEVEL_BITS-1:0] LEVEL_MAX     = {LEVEL_BITS{1'b1}};

    ///// pwm_counter rules /////
    // pwm_counter increments by 1 every clock.
    check_pwm_counter_step: assert property (
        @(posedge clk) $past(1'b1) |-> (pwm_counter == $past(pwm_counter) + 1)
    );

    // pwm_counter wraps to 0 after reaching max.
    check_pwm_counter_wrap: assert property (
        @(posedge clk) $past(1'b1) && ($past(pwm_counter) == LEVEL_MAX) |-> (pwm_counter == '0)
    );

    ///// fade_counter rules /////
    // When trigger is HIGH, fade_counter loads all 1s.
    check_fade_load_on_trigger_now: assert property (
        @(posedge clk) trigger |-> (fade_counter == FADE_ALL_ONES)
    );

    // When trigger is LOW and fade_counter was nonzero, it decrements by 1.
    check_fade_dec_when_nonzero: assert property (
        @(posedge clk) $past(1'b1) && !$past(trigger) && ($past(fade_counter) != '0) |-> (fade_counter == ($past(fade_counter) - 1))
    );

    // When trigger is LOW and fade_counter was zero, it stays zero.
    check_fade_hold_when_zero: assert property (
        @(posedge clk) $past(1'b1) && !$past(trigger) && ($past(fade_counter) == '0) |-> (fade_counter == '0)
    );

    // With trigger LOW in consecutive cycles, fade_counter is nonincreasing.
    check_fade_monotonic_no_trigger: assert property (
        @(posedge clk) $past(1'b1) && !$past(trigger) && !trigger |-> (fade_counter <= $past(fade_counter))
    );

    ///// level rules /////
    // level equals the top LEVEL_BITS of fade_counter.
    check_level_is_slice: assert property (
        @(posedge clk) level == fade_counter[FADE_BITS-1 -: LEVEL_BITS]
    );

    // With trigger LOW in consecutive cycles, level is nonincreasing.
    check_level_monotonic_no_trigger: assert property (
        @(posedge clk) $past(1'b1) && !$past(trigger) && !trigger |-> (level <= $past(level))
    );

    ///// drive rules /////
    // drive equals (pwm_counter < level).
    check_drive_is_compare: assert property (
        @(posedge clk) drive == (pwm_counter < level)
    );

    // When level is 0, drive must be 0.
    check_drive_zero_when_level_zero: assert property (
        @(posedge clk) (level == '0) |-> (drive == 1'b0)
    );

    // When level is max and pwm_counter != max, drive is 1.
    check_drive_one_when_level_max_and_pwm_not_max: assert property (
        @(posedge clk) (level == LEVEL_MAX) && (pwm_counter != LEVEL_MAX) |-> (drive == 1'b1)
    );

    // When level is max and pwm_counter is max, drive is 0.
    check_drive_zero_when_level_max_and_pwm_max: assert property (
        @(posedge clk) (level == LEVEL_MAX) && (pwm_counter == LEVEL_MAX) |-> (drive == 1'b0)
    );

    // While trigger is HIGH for 2 cycles, drive cannot be 0 in both cycles.
    check_no_two_consecutive_drive_zero_while_trigger_high: assert property (
        @(posedge clk) $past(1'b1) && trigger && $past(trigger) |-> !($past(drive) == 1'b0 && drive == 1'b0)
    );

endmodule

rtl:
module sky130_fd_sc_ms__fahcon (
    COUT_N,
    SUM   ,
    A     ,
    B     ,
    CI
);

    output COUT_N;
    output SUM   ;
    input  A     ;
    input  B     ;
    input  CI    ;

    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    wire xor0_out_SUM ;
    wire a_b          ;
    wire a_ci         ;
    wire b_ci         ;
    wire or0_out_coutn;

    xor xor0 (xor0_out_SUM , A, B, CI       );
    buf buf0 (SUM          , xor0_out_SUM   );
    nor nor0 (a_b          , A, B           );
    nor nor1 (a_ci         , A, CI          );
    nor nor2 (b_ci         , B, CI          );
    or  or0  (or0_out_coutn, a_b, a_ci, b_ci);
    buf buf1 (COUT_N       , or0_out_coutn  );

endmodule

sva:
module sky130_fd_sc_ms__fahcon_sva (
    input logic clk,
    input logic COUT_N,
    input logic SUM,
    input logic A,
    input logic B,
    input logic CI
);

    // SUM implements three-input XOR of A, B, CI.
    check_sum_xor3: assert property (
        @(posedge clk) SUM == (A ^ B ^ CI)
    );

    // COUT_N is the inverse of the majority function of A, B, CI.
    check_coutn_inverse_majority: assert property (
        @(posedge clk) COUT_N == ~((A & B) | (A & CI) | (B & CI))
    );

    // When A equals B, SUM equals CI.
    check_sum_when_ab_equal: assert property (
        @(posedge clk) (A == B) |-> (SUM == CI)
    );

    // When A differs from B, SUM equals inverted CI.
    check_sum_when_ab_differs: assert property (
        @(posedge clk) (A != B) |-> (SUM == ~CI)
    );

    // If both A and B are 1, COUT_N must be 0 regardless of CI.
    check_coutn_low_when_ab_11: assert property (
        @(posedge clk) (A & B) |-> (COUT_N == 1'b0)
    );

    // If both A and B are 0, COUT_N must be 1 regardless of CI.
    check_coutn_high_when_ab_00: assert property (
        @(posedge clk) (~A & ~B) |-> (COUT_N == 1'b1)
    );

    // For input vector 000, SUM=0 and COUT_N=1.
    check_vector_000: assert property (
        @(posedge clk) (A == 1'b0 && B == 1'b0 && CI == 1'b0) |-> (SUM == 1'b0 && COUT_N == 1'b1)
    );

    // For input vector 111, SUM=1 and COUT_N=0.
    check_vector_111: assert property (
        @(posedge clk) (A == 1'b1 && B == 1'b1 && CI == 1'b1) |-> (SUM == 1'b1 && COUT_N == 1'b0)
    );

    // SUM toggles iff an odd number of inputs (A,B,CI) change between cycles.
    check_sum_toggles_on_odd_change: assert property (
        @(posedge clk) ($changed(A) ^ $changed(B) ^ $changed(CI)) |-> $changed(SUM)
    );

    // SUM stays stable if an even number of inputs (including zero) change between cycles.
    check_sum_stable_on_even_change: assert property (
        @(posedge clk) ~($changed(A) ^ $changed(B) ^ $changed(CI)) |-> !$changed(SUM)
    );

endmodule

rtl:
module alu_4bit (
    input [3:0] A,
    input [3:0] B,
    input [2:0] control,
    output reg [3:0] result
);

    always @(*) begin
        case (control)
            3'b000: result = A + B;
            3'b001: result = A - B;
            3'b010: result = A & B;
            3'b011: result = A | B;
            default: result = 4'b0000;
        endcase
    end

endmodule

sva:
module alu_4bit_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [2:0] control,
    input logic [3:0] result
);
    // Analysis: No clock or reset; pure combinational always @(*); result depends only on A,B,control.
    // Function: control=000 add, 001 sub, 010 and, 011 or, default 0000.

    // When control==000, result equals 4-bit A + B.
    check_add_function: assert property (
        @($global_clock) (control == 3'b000) |-> (result == (A + B))
    );

    // When control==001, result equals 4-bit A - B.
    check_sub_function: assert property (
        @($global_clock) (control == 3'b001) |-> (result == (A - B))
    );

    // When control==010, result equals A & B.
    check_and_function: assert property (
        @($global_clock) (control == 3'b010) |-> (result == (A & B))
    );

    // When control==011, result equals A | B.
    check_or_function: assert property (
        @($global_clock) (control == 3'b011) |-> (result == (A | B))
    );

    // For all other control values, result is 0000.
    check_default_zero: assert property (
        @($global_clock) (!(control inside {3'b000,3'b001,3'b010,3'b011})) |-> (result == 4'b0000)
    );

    // If A,B,control are stable, result remains stable (combinational determinism).
    check_stable_when_inputs_stable: assert property (
        @($global_clock) $stable({A,B,control}) |-> $stable(result)
    );

    // Add identity: with B==0, result equals A.
    check_add_zero_identity: assert property (
        @($global_clock) (control == 3'b000 && (B == 4'b0000)) |-> (result == A)
    );

    // Sub identity: with B==0, result equals A.
    check_sub_zero_identity: assert property (
        @($global_clock) (control == 3'b001 && (B == 4'b0000)) |-> (result == A)
    );

    // AND with zero yields zero.
    check_and_zero: assert property (
        @($global_clock) (control == 3'b010 && (B == 4'b0000)) |-> (result == 4'b0000)
    );

    // OR with zero yields A.
    check_or_zero: assert property (
        @($global_clock) (control == 3'b011 && (B == 4'b0000)) |-> (result == A)
    );

    // Subtract/add inverse modulo 16: (A - B) + B == A.
    check_sub_add_inverse_mod16: assert property (
        @($global_clock) (control == 3'b001) |-> ((result + B) == A)
    );

    // AND with ones yields A.
    check_and_ones: assert property (
        @($global_clock) (control == 3'b010 && (B == 4'b1111)) |-> (result == A)
    );

    // OR with ones yields ones.
    check_or_ones: assert property (
        @($global_clock) (control == 3'b011 && (B == 4'b1111)) |-> (result == 4'b1111)
    );

endmodule

