  XOR2_X1 x1 ( .A(A), .B(B), .ZN(n1) );
  XOR2_X1 x2 ( .A(n1), .B(Ci), .ZN(S) );
  AND2_X1 a1 ( .A(A), .B(B), .ZN(n2) );
  AND2_X1 a2 ( .A(n1), .B(Ci), .ZN(n3) );
