    // X implements (A1 & A2) | A3.
    check_function_exact: assert property (
        @(posedge clk) X == ((A1 & A2) | A3)
    );

    // If A3 is HIGH, X must be HIGH.
    check_A3_forces_X_high: assert property (
        @(posedge clk) A3 |-> (X == 1'b1)
    );

