rtl:
module capture_transition (
  input clk,
  input reset,
  input [31:0] input_vector,
  output [31:0] output_vector
);

reg [31:0] prev_vector;
reg [31:0] transition_vector;

always @(posedge clk) begin
  if (reset) begin
    prev_vector <= 32'h0;
    transition_vector <= 32'h0;
  end
  else begin
    prev_vector <= input_vector;
    transition_vector <= ((~input_vector) & prev_vector);
  end
end

assign output_vector = transition_vector;

endmodule

sva:
module capture_transition_sva (
  input logic clk,
  input logic reset,            // active-high synchronous reset
  input logic [31:0] input_vector,
  input logic [31:0] output_vector
);

  ///// Reset behavior /////
  // Output is zero whenever reset is asserted.
  reset_outputs_zero: assert property (
    @(posedge clk) reset |-> (output_vector == 32'h0)
  );

  ///// Functional checks /////
  // Output never overlaps current input (output bits imply current input bits are 0).
  output_masked_by_current_input: assert property (
    @(posedge clk) disable iff (reset) ((output_vector & input_vector) == 32'h0)
  );

  // First cycle after leaving reset, output is zero.
  post_reset_first_cycle_output_zero: assert property (
    @(posedge clk) disable iff (reset) ($past(1'b1) && $past(reset) && !reset) |-> (output_vector == 32'h0)
  );

  // When not in reset previously, output equals (~current_input) & previous_input.
  output_matches_fall_mask: assert property (
    @(posedge clk) disable iff (reset) ($past(1'b1) && !$past(reset)) |-> (output_vector == ((~input_vector) & $past(input_vector)))
  );

  // When not in reset previously, any output bit implies that bit of previous input was 1.
  output_requires_prev_input_one: assert property (
    @(posedge clk) disable iff (reset) ($past(1'b1) && !$past(reset)) |-> ((output_vector & ~($past(input_vector))) == 32'h0)
  );

  // Output pulses are at most one cycle wide per bit.
  no_persistent_output_pulses: assert property (
    @(posedge clk) disable iff (reset) ($past(1'b1)) |-> ((output_vector & $past(output_vector)) == 32'h0)
  );

  // If input is unchanged from previous cycle (and not in reset previously), output is zero.
  no_output_when_input_unchanged: assert property (
    @(posedge clk) disable iff (reset) ($past(1'b1) && !$past(reset) && (input_vector == $past(input_vector))) |-> (output_vector == 32'h0)
  );

  // If there are no 1->0 transitions this cycle (and not in reset previously), output is zero.
  no_fall_no_output: assert property (
    @(posedge clk) disable iff (reset) ($past(1'b1) && !$past(reset) && (((~input_vector) & $past(input_vector)) == 32'h0)) |-> (output_vector == 32'h0)
  );

endmodule

rtl:
module binary_adder (
    // inputs
    input [3:0] A,
    input [3:0] B,
    // outputs
    output [3:0] S,
    output Cout
);

wire [3:0] sum;
wire [3:0] carry;

full_adder fa0(
    .A(A[0]),
    .B(B[0]),
    .Cin(1'b0),
    .S(sum[0]),
    .Cout(carry[0])
);

full_adder fa1(
    .A(A[1]),
    .B(B[1]),
    .Cin(carry[0]),
    .S(sum[1]),
    .Cout(carry[1])
);

full_adder fa2(
    .A(A[2]),
    .B(B[2]),
    .Cin(carry[1]),
    .S(sum[2]),
    .Cout(carry[2])
);

full_adder fa3(
    .A(A[3]),
    .B(B[3]),
    .Cin(carry[2]),
    .S(sum[3]),
    .Cout(Cout)
);

assign S = sum;

endmodule

module full_adder (
    // inputs
    input A,
    input B,
    input Cin,
    // outputs
    output S,
    output Cout
);

wire xor1;
wire and1;
wire and2;

assign xor1 = A ^ B;
assign and1 = A & B;
assign and2 = xor1 & Cin;

assign S = xor1 ^ Cin;
assign Cout = and1 | and2;

endmodule

sva:
module binary_adder_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] S,
    input logic Cout
);

    ///// Functional correctness /////
    // {Cout,S} equals the 5-bit sum of A and B.
    check_result_matches_addition: assert property (
        @(posedge clk) {Cout, S} == (A + B)
    );

    // S is the low 4 bits of A+B.
    check_S_is_low4_of_sum: assert property (
        @(posedge clk) S == (A + B)[3:0]
    );

    // Cout is the MSB (carry-out) of A+B.
    check_Cout_is_carry_of_sum: assert property (
        @(posedge clk) Cout == (A + B)[4]
    );

    ///// Ripple-carry structure equivalence /////
    // Bit 0 sum: no carry-in.
    check_s0_xor: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0])
    );

    // Bit 1 sum uses carry from bit 0.
    check_s1_rca: assert property (
        @(posedge clk) S[1] == ((A[1] ^ B[1]) ^ (A[0] & B[0]))
    );

    // Bit 2 sum uses carry from bit 1.
    check_s2_rca: assert property (
        @(posedge clk) S[2] == ((A[2] ^ B[2]) ^ (((A[1] & B[1]) | ((A[1] ^ B[1]) & (A[0] & B[0])))))
    );

    // Bit 3 sum uses carry from bit 2.
    check_s3_rca: assert property (
        @(posedge clk) S[3] == ((A[3] ^ B[3]) ^ (((A[2] & B[2]) | ((A[2] ^ B[2]) & ((A[1] & B[1]) | ((A[1] ^ B[1]) & (A[0] & B[0])))))))
    );

    // Final carry-out from bit 3.
    check_cout_rca: assert property (
        @(posedge clk) Cout == ((A[3] & B[3]) | ((A[3] ^ B[3]) & ((A[2] & B[2]) | ((A[2] ^ B[2]) & ((A[1] & B[1]) | ((A[1] ^ B[1]) & (A[0] & B[0])))))))
    );

    ///// Overflow/carry equivalence /////
    // If sum exceeds 4 bits, Cout must be 1.
    check_overflow_sets_cout: assert property (
        @(posedge clk) (({1'b0, A} + {1'b0, B}) > 5'd15) |-> (Cout == 1'b1)
    );

    // Cout high implies sum exceeds 4 bits.
    check_cout_implies_overflow: assert property (
        @(posedge clk) Cout |-> (({1'b0, A} + {1'b0, B}) > 5'd15)
    );

    ///// Determinism /////
    // If inputs are stable cycle-to-cycle, outputs remain stable.
    check_outputs_stable_when_inputs_stable: assert property (
        @(posedge clk) $stable({A, B}) |-> $stable({S, Cout})
    );

endmodule

module bitwise_full_adder_sva (
    input logic A,
    input logic B,
    input logic CIN,
    input logic VPB,
    input logic VPWR,
    input logic VGND,
    input logic VNB,
    input logic COUT,
    input logic SUM
);

    ///// Combinational full-adder function /////
    // SUM equals XOR of inputs.
    check_sum_definition: assert property (
        @(posedge A or posedge B or posedge CIN) disable iff (1'b0)
            SUM == (A ^ B) ^ CIN
    );

    // COUT equals carry function (A&B) | (CIN & (A^B)).
    check_cout_definition_impl: assert property (
        @(posedge A or posedge B or posedge CIN) disable iff (1'b0)
            COUT == ((A & B) | (CIN & (A ^ B)))
    );

    // COUT equals majority of inputs.
    check_cout_majority_equiv: assert property (
        @(posedge A or posedge B or posedge CIN) disable iff (1'b0)
            COUT == ((A & B) | (A & CIN) | (B & CIN))
    );

    ///// Truth-table spot checks /////
    // 0+0+0 -> SUM=0, COUT=0.
    check_case_000: assert property (
        @(posedge A or posedge B or posedge CIN) disable iff (1'b0)
            (!A && !B && !CIN) |-> (SUM == 1'b0 && COUT == 1'b0)
    );

    // Exactly one '1' -> SUM=1, COUT=0.
    check_case_popcount1: assert property (
        @(posedge A or posedge B or posedge CIN) disable iff (1'b0)
            ((A + B + CIN) == 1) |-> (SUM == 1'b1 && COUT == 1'b0)
    );

    // Exactly two '1's -> SUM=0, COUT=1.
    check_case_popcount2: assert property (
        @(posedge A or posedge B or posedge CIN) disable iff (1'b0)
            ((A + B + CIN) == 2) |-> (SUM == 1'b0 && COUT == 1'b1)
    );

    // 1+1+1 -> SUM=1, COUT=1.
    check_case_111: assert property (
        @(posedge A or posedge B or posedge CIN) disable iff (1'b0)
            (A && B && CIN) |-> (SUM == 1'b1 && COUT == 1'b1)
    );

    ///// Simple carry implications /////
    // If A&B then COUT must be 1.
    check_carry_when_ab: assert property (
        @(posedge A or posedge B or posedge CIN) disable iff (1'b0)
            (A && B) |-> (COUT == 1'b1)
    );

    // If A&CIN then COUT must be 1.
    check_carry_when_acin: assert property (
        @(posedge A or posedge B or posedge CIN) disable iff (1'b0)
            (A && CIN) |-> (COUT == 1'b1)
    );

    // If B&CIN then COUT must be 1.
    check_carry_when_bcin: assert property (
        @(posedge A or posedge B or posedge CIN) disable iff (1'b0)
            (B && CIN) |-> (COUT == 1'b1)
    );

    ///// XOR identities for SUM /////
    // If B==CIN then SUM==A.
    check_sum_when_b_eq_cin: assert property (
        @(posedge A or posedge B or posedge CIN) disable iff (1'b0)
            (B == CIN) |-> (SUM == A)
    );

    // If A==B then SUM==CIN.
    check_sum_when_a_eq_b: assert property (
        @(posedge A or posedge B or posedge CIN) disable iff (1'b0)
            (A == B) |-> (SUM == CIN)
    );

    // If A==CIN then SUM==B.
    check_sum_when_a_eq_cin: assert property (
        @(posedge A or posedge B or posedge CIN) disable iff (1'b0)
            (A == CIN) |-> (SUM == B)
    );

endmodule

rtl:
module combinational_logic (
    Y,
    A1,
    A2,
    B1,
    B2,
    C1
);

    output Y;
    input A1, A2, B1, B2, C1;

    assign Y = (~A1 & B1 & C1) | (~A1 & ~B2 & ~C1) | (A1 & ~B1 & ~C1) | (A2 & ~B1 & ~C1) | (A2 & B2 & C1);

endmodule

sva:
module combinational_logic_sva (
    input logic CLK,
    input logic Y,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic B2,
    input logic C1
);

    // Y must equal the RTL combinational equation.
    check_y_equation: assert property (
        @(posedge CLK)
        Y == ((~A1 & B1 & C1) | (~A1 & ~B2 & ~C1) | (A1 & ~B1 & ~C1) | (A2 & ~B1 & ~C1) | (A2 & B2 & C1))
    );

    // If (~A1 & B1 & C1) holds, Y must be 1.
    check_term1_sets_y: assert property (
        @(posedge CLK)
        (~A1 & B1 & C1) |-> (Y == 1'b1)
    );

    // If (~A1 & ~B2 & ~C1) holds, Y must be 1.
    check_term2_sets_y: assert property (
        @(posedge CLK)
        (~A1 & ~B2 & ~C1) |-> (Y == 1'b1)
    );

    // If (A1 & ~B1 & ~C1) holds, Y must be 1.
    check_term3_sets_y: assert property (
        @(posedge CLK)
        (A1 & ~B1 & ~C1) |-> (Y == 1'b1)
    );

    // If (A2 & ~B1 & ~C1) holds, Y must be 1.
    check_term4_sets_y: assert property (
        @(posedge CLK)
        (A2 & ~B1 & ~C1) |-> (Y == 1'b1)
    );

    // If (A2 & B2 & C1) holds, Y must be 1.
    check_term5_sets_y: assert property (
        @(posedge CLK)
        (A2 & B2 & C1) |-> (Y == 1'b1)
    );

    // With C1=1 and B1=0, if A2=0 or B2=0 then no term can assert Y.
    check_y_zero_c1_high_b1_low_blocked: assert property (
        @(posedge CLK)
        (C1 & ~B1 & (~A2 | ~B2)) |-> (Y == 1'b0)
    );

    // With C1=0 and B1=1, if A1=1 or B2=1 then no term can assert Y.
    check_y_zero_c1_low_b1_high_blocked: assert property (
        @(posedge CLK)
        (~C1 & B1 & (A1 | B2)) |-> (Y == 1'b0)
    );

    // With C1=0, B1=0, A1=0, A2=0, B2=1, no term can assert Y.
    check_y_zero_specific_combo1: assert property (
        @(posedge CLK)
        (~C1 & ~B1 & ~A1 & ~A2 & B2) |-> (Y == 1'b0)
    );

    // With C1=1, B1=1, A1=1, and (A2=0 or B2=0), no term can assert Y.
    check_y_zero_specific_combo2: assert property (
        @(posedge CLK)
        (C1 & B1 & A1 & (~A2 | ~B2)) |-> (Y == 1'b0)
    );

endmodule

rtl:
module shift_register (
    input in,
    output reg [2:0] out,
    input clk // Added the clk input port
);

reg [2:0] reg_out;

always @(posedge clk) begin
    reg_out <= {reg_out[1:0], in};
end

// Corrected the output assignment to use a register assignment
always @(*) begin
    out <= reg_out & 3'b111;
end

endmodule

sva:
module shift_register_sva (
    input logic clk,
    input logic in,
    input logic [2:0] out,
    input logic [2:0] reg_out
);
    ///// Combinational mapping /////
    // out mirrors reg_out masked by 3'b111.
    out_follows_reg_out_masked: assert property (
        @(posedge clk) out == (reg_out & 3'b111)
    );

    ///// Sequential shift behavior /////
    // reg_out updates to {previous reg_out[1:0], previous in}.
    reg_out_shift_concat: assert property (
        @(posedge clk) $past(1'b1) |-> reg_out == {$past(reg_out[1:0]), $past(in)}
    );
    // Bit 0 of reg_out captures in on the next clock.
    shift_bit0_captures_in: assert property (
        @(posedge clk) $past(1'b1) |-> reg_out[0] == $past(in)
    );
    // Bit 1 of reg_out shifts from previous bit 0.
    shift_bit1_from_bit0: assert property (
        @(posedge clk) $past(1'b1) |-> reg_out[1] == $past(reg_out[0])
    );
    // Bit 2 of reg_out shifts from previous bit 1.
    shift_bit2_from_bit1: assert property (
        @(posedge clk) $past(1'b1) |-> reg_out[2] == $past(reg_out[1])
    );

    ///// Stability relation /////
    // If reg_out is unchanged cycle-to-cycle, out is unchanged.
    out_stable_when_reg_out_stable: assert property (
        @(posedge clk) $past(1'b1) && (reg_out == $past(reg_out)) |-> (out == $past(out))
    );

    ///// 3-cycle input history determines state /////
    // After 3 cycles, reg_out equals the last 3 inputs (oldest->newest).
    reg_out_equals_3past_inputs: assert property (
        @(posedge clk) $past(1'b1,3) |-> reg_out == { $past(in,3), $past(in,2), $past(in,1) }
    );
    // After 3 cycles, out equals masked last 3 inputs.
    out_equals_masked_3past_inputs: assert property (
        @(posedge clk) $past(1'b1,3) |-> out == ({ $past(in,3), $past(in,2), $past(in,1) } & 3'b111)
    );

    ///// Special cases of the 3-cycle history /////
    // Three consecutive zeros on in drive reg_out to 3'b000.
    zeros_flush_reg_out_in3: assert property (
        @(posedge clk) $past(1'b1,3) && ($past(in,3)==1'b0) && ($past(in,2)==1'b0) && ($past(in,1)==1'b0) |-> (reg_out == 3'b000)
    );
    // Three consecutive ones on in drive reg_out to 3'b111.
    ones_fill_reg_out_in3: assert property (
        @(posedge clk) $past(1'b1,3) && ($past(in,3)==1'b1) && ($past(in,2)==1'b1) && ($past(in,1)==1'b1) |-> (reg_out == 3'b111)
    );

endmodule

module d_flip_flop_with_reset_sva (
    input logic clk,
    input logic reset,
    input logic d,
    input logic q
);
    // Synchronous reset drives q to 0 on the next clock.
    reset_clears_q_next: assert property (
        @(posedge clk) reset |=> (q == 1'b0)
    );

    // When previous cycle was not in reset, q equals previous d (1-cycle latency).
    q_eq_prev_d_when_prev_not_reset: assert property (
        @(posedge clk) disable iff (reset) (!$past(reset)) |-> (q == $past(d))
    );

    // If q changes, the cause must be prior reset or prior d differing from prior q.
    q_change_requires_prev_reset_or_prev_d_neq_prev_q: assert property (
        @(posedge clk) disable iff (reset) (q != $past(q)) |-> ($past(reset) || ($past(d) != $past(q)))
    );

    // If prior cycle not in reset and prior d matched prior q, q holds its value.
    q_holds_when_prev_d_eq_prev_q: assert property (
        @(posedge clk) disable iff (reset) (!$past(reset) && ($past(d) == $past(q))) |-> (q == $past(q))
    );

    // If prior cycle not in reset and prior d differed from prior q, q changes accordingly.
    q_toggles_when_prev_d_neq_prev_q: assert property (
        @(posedge clk) disable iff (reset) (!$past(reset) && ($past(d) != $past(q))) |-> (q != $past(q))
    );

    // On reset deassertion edge, q is 0 (due to prior reset).
    q_zero_on_reset_fall: assert property (
        @(posedge clk) $fell(reset) |-> (q == 1'b0)
    );
endmodule

rtl:
module gray_code_converter (
    input [3:0] binary,
    output [3:0] gray
);

assign gray[0] = binary[0];
assign gray[1] = binary[0] ^ binary[1];
assign gray[2] = binary[1] ^ binary[2];
assign gray[3] = binary[2] ^ binary[3];

endmodule

sva:
module gray_code_converter_sva (
    input logic clk,
    input logic [3:0] binary,
    input logic [3:0] gray
);
    // gray[0] equals binary[0].
    check_map_g0_from_b0: assert property (
        @(posedge clk) gray[0] == binary[0]
    );

    // gray[1] equals binary[0] XOR binary[1].
    check_map_g1_from_b01: assert property (
        @(posedge clk) gray[1] == (binary[0] ^ binary[1])
    );

    // gray[2] equals binary[1] XOR binary[2].
    check_map_g2_from_b12: assert property (
        @(posedge clk) gray[2] == (binary[1] ^ binary[2])
    );

    // gray[3] equals binary[2] XOR binary[3].
    check_map_g3_from_b23: assert property (
        @(posedge clk) gray[3] == (binary[2] ^ binary[3])
    );

    // gray vector matches bitwise mapping from binary.
    check_map_vector: assert property (
        @(posedge clk) gray == { (binary[2] ^ binary[3]), (binary[1] ^ binary[2]), (binary[0] ^ binary[1]), binary[0] }
    );

    // If binary is stable, gray remains stable.
    check_stable_binary_implies_stable_gray: assert property (
        @(posedge clk) $stable(binary) |-> $stable(gray)
    );

    // gray[0] changes iff binary[0] changes.
    check_change_g0_iff_b0: assert property (
        @(posedge clk) $changed(gray[0]) == $changed(binary[0])
    );

    // gray[1] change equals parity of changes on binary[0] and binary[1].
    check_change_g1_parity: assert property (
        @(posedge clk) $changed(gray[1]) == ($changed(binary[0]) ^ $changed(binary[1]))
    );

    // gray[2] change equals parity of changes on binary[1] and binary[2].
    check_change_g2_parity: assert property (
        @(posedge clk) $changed(gray[2]) == ($changed(binary[1]) ^ $changed(binary[2]))
    );

    // gray[3] change equals parity of changes on binary[2] and binary[3].
    check_change_g3_parity: assert property (
        @(posedge clk) $changed(gray[3]) == ($changed(binary[2]) ^ $changed(binary[3]))
    );
endmodule

rtl:
module xor_counter(
    input clk,
    input a,
    output reg out_comb_ff,
    output reg [1:0] out_counter
);

reg [1:0] counter;
reg out_ff;

always @(posedge clk) begin
    counter <= counter + 2'b01;
    out_counter <= counter;
end

always @* begin
    out_comb_ff <= a ^ out_ff;
end

always @(posedge clk) begin
    out_ff <= out_comb_ff;
end

endmodule

sva:
module xor_counter_sva (
    input logic clk,
    input logic a,
    input logic out_comb_ff,
    input logic [1:0] out_counter,
    input logic [1:0] counter,
    input logic out_ff
);
    // Counter increments by 1 modulo-4 each clock.
    check_counter_increments: assert property (
        @(posedge clk) disable iff ($initstate) counter == $past(counter) + 2'b01
    );

    // out_counter captures the previous value of counter.
    check_out_counter_is_prev_counter: assert property (
        @(posedge clk) disable iff ($initstate) out_counter == $past(counter)
    );

    // In the same cycle, counter equals out_counter + 1.
    check_counter_equals_out_counter_plus1: assert property (
        @(posedge clk) counter == (out_counter + 2'b01)
    );

    // out_counter increments by 1 each clock (pipelined copy of counter).
    check_out_counter_increments: assert property (
        @(posedge clk) disable iff ($initstate) out_counter == $past(out_counter) + 2'b01
    );

    // out_ff captures the previous out_comb_ff.
    check_out_ff_captures_prev_out_comb_ff: assert property (
        @(posedge clk) disable iff ($initstate) out_ff == $past(out_comb_ff)
    );

    // out_comb_ff is always a XOR out_ff.
    check_out_comb_is_xor: assert property (
        @(posedge clk) out_comb_ff == (a ^ out_ff)
    );

    // out_ff equals previous (a XOR out_ff).
    check_out_ff_next_equals_prev_a_xor_out_ff: assert property (
        @(posedge clk) disable iff ($initstate) out_ff == $past(a ^ out_ff)
    );

    // If previous a was 1, out_ff toggles.
    check_out_ff_toggles_when_prev_a_1: assert property (
        @(posedge clk) disable iff ($initstate) $past(a) |-> (out_ff == ~$past(out_ff))
    );

    // If previous a was 0, out_ff holds.
    check_out_ff_holds_when_prev_a_0: assert property (
        @(posedge clk) disable iff ($initstate) !$past(a) |-> (out_ff == $past(out_ff))
    );

    // out_comb_ff equals a XOR previous out_comb_ff (via out_ff pipeline).
    check_out_comb_relates_to_prev_out_comb: assert property (
        @(posedge clk) disable iff ($initstate) out_comb_ff == (a ^ $past(out_comb_ff))
    );
endmodule

rtl:
module mult_16bit_signed (
    input signed [15:0] M,
    input signed [15:0] N,
    output reg signed [31:0] P
);

    always @(*) begin
        P = M * N;
    end

endmodule

sva:
module mult_16bit_signed_sva (
    input logic CLK,
    input signed [15:0] M,
    input signed [15:0] N,
    input signed [31:0] P
);
    // P equals the signed product of M and N.
    check_product_correct: assert property (
        @(posedge CLK) disable iff ($initstate) P == M * N
    );

    // If M is zero then P is zero.
    check_zero_multiplicand_M: assert property (
        @(posedge CLK) disable iff ($initstate) (M == 16'sd0) |-> (P == 32'sd0)
    );

    // If N is zero then P is zero.
    check_zero_multiplicand_N: assert property (
        @(posedge CLK) disable iff ($initstate) (N == 16'sd0) |-> (P == 32'sd0)
    );

    // If M is one then P equals N.
    check_one_multiplicand_M: assert property (
        @(posedge CLK) disable iff ($initstate) (M == 16'sd1) |-> (P == N)
    );

    // If N is one then P equals M.
    check_one_multiplicand_N: assert property (
        @(posedge CLK) disable iff ($initstate) (N == 16'sd1) |-> (P == M)
    );

    // If M is minus one then P equals -N.
    check_neg_one_multiplicand_M: assert property (
        @(posedge CLK) disable iff ($initstate) (M == -16'sd1) |-> (P == -N)
    );

    // If N is minus one then P equals -M.
    check_neg_one_multiplicand_N: assert property (
        @(posedge CLK) disable iff ($initstate) (N == -16'sd1) |-> (P == -M)
    );

    // For non-zero operands, product sign equals XOR of operand signs.
    check_product_sign: assert property (
        @(posedge CLK) disable iff ($initstate) ((M != 16'sd0) && (N != 16'sd0)) |-> (P[31] == (M[15] ^ N[15]))
    );

    // Zero product implies at least one operand is zero.
    check_zero_product_implication: assert property (
        @(posedge CLK) disable iff ($initstate) (P == 32'sd0) |-> ((M == 16'sd0) || (N == 16'sd0))
    );

    // If inputs are stable cycle-to-cycle, output remains stable.
    check_stability_when_inputs_stable: assert property (
        @(posedge CLK) disable iff ($initstate) (M == $past(M) && N == $past(N)) |-> (P == $past(P))
    );
endmodule

