module adder16(
    input [15:0] A,
    input [15:0] B,
    input CIN,
    output [15:0] SUM,
    output COUT
);

reg [15:0] sum_temp;
reg cout_temp;

always @(*) begin
    {cout_temp,sum_temp} = A + B + CIN;
end

assign SUM = sum_temp;
assign COUT = cout_temp;

endmodule

sva:
module adder16_sva (
    input logic CLK,
    input logic [15:0] A,
    input logic [15:0] B,
    input logic CIN,
    input logic [15:0] SUM,
    input logic COUT
);
    // SUM and COUT equal the 17-bit sum of A, B, and CIN.
    check_full_sum: assert property (
        @(posedge CLK) {COUT, SUM} == (A + B + CIN)
    );

    // SUM equals the lower 16 bits of A + B + CIN.
    check_sum_low16: assert property (
        @(posedge CLK) SUM == (A + B + CIN)[15:0]
    );

    // COUT equals the carry-out bit of A + B + CIN.
    check_cout_bit16: assert property (
        @(posedge CLK) COUT == (A + B + CIN)[16]
    );

    // Adding zero B with CIN=0 yields SUM=A and no carry.
    check_add_zero_B: assert property (
        @(posedge CLK) (B == 16'h0000 && CIN == 1'b0) |-> (SUM == A && COUT == 1'b0)
    );

    // Adding zero A with CIN=0 yields SUM=B and no carry.
    check_add_zero_A: assert property (
        @(posedge CLK) (A == 16'h0000 && CIN == 1'b0) |-> (SUM == B && COUT == 1'b0)
    );

    // Zero A and B yield SUM=CIN and no carry.
    check_zero_plus_zero: assert property (
        @(posedge CLK) (A == 16'h0000 && B == 16'h0000) |-> (SUM == {15'b0, CIN} && COUT == 1'b0)
    );

    // 0xFFFF + 0x0000 + 1 -> SUM=0x0000, COUT=1.
    check_max_plus_one: assert property (
        @(posedge CLK) (A == 16'hFFFF && B == 16'h0000 && CIN == 1'b1) |-> (SUM == 16'h0000 && COUT == 1'b1)
    );

    // 0xFFFF + 0xFFFF + 0 -> SUM=0xFFFE, COUT=1.
    check_max_plus_max_nocin: assert property (
        @(posedge CLK) (A == 16'hFFFF && B == 16'hFFFF && CIN == 1'b0) |-> (SUM == 16'hFFFE && COUT == 1'b1)
    );

    // 0xFFFF + 0xFFFF + 1 -> SUM=0xFFFF, COUT=1.
    check_max_plus_max_cin: assert property (
        @(posedge CLK) (A == 16'hFFFF && B == 16'hFFFF && CIN == 1'b1) |-> (SUM == 16'hFFFF && COUT == 1'b1)
    );

    // A + ~A with CIN=0 -> SUM=0xFFFF, COUT=0.
    check_complement_nocin: assert property (
        @(posedge CLK) (B == ~A && CIN == 1'b0) |-> (SUM == 16'hFFFF && COUT == 1'b0)
    );

    // A + ~A with CIN=1 -> SUM=0x0000, COUT=1.
    check_complement_cin: assert property (
        @(posedge CLK) (B == ~A && CIN == 1'b1) |-> (SUM == 16'h0000 && COUT == 1'b1)
    );
endmodule

rtl:
module sky130_fd_sc_ms__bufinv (
    Y,
    A
);

    output Y;
    input  A;

    wire not0_out_Y;

    not not0 (not0_out_Y, A              );
    buf buf0 (Y         , not0_out_Y     );

endmodule

sva:
module sky130_fd_sc_ms__bufinv_sva (
    input logic Y,
    input logic A
);
    // Y is the logical inversion of A whenever either signal changes.
    check_inversion_on_change: assert property (
        @(posedge A or negedge A or posedge Y or negedge Y) (Y === ~A)
    );

    // When A is 0, Y must be 1.
    check_y_high_if_a_low: assert property (
        @(posedge A or negedge A or posedge Y or negedge Y) (A === 1'b0) |-> (Y === 1'b1)
    );

    // When A is 1, Y must be 0.
    check_y_low_if_a_high: assert property (
        @(posedge A or negedge A or posedge Y or negedge Y) (A === 1'b1) |-> (Y === 1'b0)
    );

    // When Y is 0, A must be 1.
    check_a_high_if_y_low: assert property (
        @(posedge A or negedge A or posedge Y or negedge Y) (Y === 1'b0) |-> (A === 1'b1)
    );

    // When Y is 1, A must be 0.
    check_a_low_if_y_high: assert property (
        @(posedge A or negedge A or posedge Y or negedge Y) (Y === 1'b1) |-> (A === 1'b0)
    );
endmodule

rtl:
module counter_adder_module (
    input wire clk,
    input wire reset,
    input wire select,
    output wire [3:0] out
);

wire [3:0] counter;
wire [3:0] adder_out;

// Instantiate the counter module
counter_module counter_inst (
    .clk(clk),
    .reset(reset),
    .out(counter)
);

// Instantiate the adder module
adder_module adder_inst (
    .a(counter),
    .b(4'b0001),
    .out(adder_out)
);

// Control module to choose between counter and adder

reg [3:0] tmp_counter;  // Declare a temporary register to store the counter value
wire [3:0] selected_output;

always @(posedge clk) begin
    if (reset) begin
        tmp_counter <= 4'b0000;
    end else begin
        case (select)  
            1'b0: tmp_counter  <= counter;
            1'b1: tmp_counter  <= adder_out;
        endcase
    end
end

assign out = tmp_counter;  // Assign the output to the temporary register

endmodule
module counter_module (
    input wire clk,
    input wire reset,
    output wire [3:0] out
);

reg [3:0] counter_reg; // Declare counter as a reg

always @(posedge clk) begin
    if (reset) begin
        counter_reg <= 4'b0000;
    end else begin
        counter_reg <= counter_reg + 1;
    end
end

assign out = counter_reg; // Assign the output to the register value

endmodule
module adder_module (
    input wire [3:0] a,
    input wire [3:0] b,
    output wire [3:0] out
);

assign out = a + b; // Direct assignment for the adder output

endmodule

sva:
module counter_adder_module_sva (
    input logic clk,
    input logic reset,      // active-high synchronous reset
    input logic select,
    input logic [3:0] out
);
    ///// Reset behavior /////
    // If reset is asserted, out becomes 0 on the next clock.
    reset_next_cycle_zero: assert property (
        @(posedge clk) reset |=> (out == 4'd0)
    );

    // While reset stays asserted across consecutive cycles, out is 0.
    reset_hold_zero: assert property (
        @(posedge clk) (reset && $past(reset)) |-> (out == 4'd0)
    );

    // Immediately after reset deasserts, out is 0 (loaded by prior reset cycle).
    reset_deassert_out_zero: assert property (
        @(posedge clk) $past(reset) && !reset |-> (out == 4'd0)
    );

    ///// Output step behavior vs. select history (two-cycle lookahead) /////
    // If select stays 0 for two consecutive cycles, out increments by 1 in the next cycle.
    step_when_select00_next: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(reset) && ($past(select) == 1'b0) && (select == 1'b0))
        |-> ##1 (out == $past(out) + 4'd1)
    );

    // If select stays 1 for two consecutive cycles, out increments by 1 in the next cycle.
    step_when_select11_next: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(reset) && ($past(select) == 1'b1) && (select == 1'b1))
        |-> ##1 (out == $past(out) + 4'd1)
    );

    // If select toggles 0->1, out increments by 2 in the next cycle.
    step_when_select01_next: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(reset) && ($past(select) == 1'b0) && (select == 1'b1))
        |-> ##1 (out == $past(out) + 4'd2)
    );

    // If select toggles 1->0, out holds its value in the next cycle.
    hold_when_select10_next: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(reset) && ($past(select) == 1'b1) && (select == 1'b0))
        |-> ##1 (out == $past(out))
    );

    // If select is X/Z in a cycle, no case item matches and out holds next cycle.
    hold_when_select_unknown_next: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(reset) && (select !== 1'b0) && (select !== 1'b1))
        |-> ##1 (out == $past(out))
    );

    ///// Immediate (one-cycle) output step vs. prior select pair /////
    // If prior two selects were equal, out increments by 1 this cycle.
    step_now_when_prev_equal: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(reset,1) && !$past(reset,2) && ($past(select,1) == $past(select,2)))
        |-> (out == $past(out) + 4'd1)
    );

    // If prior selects were 0 then 1, out increments by 2 this cycle.
    step_now_when_prev01: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(reset,1) && !$past(reset,2) && ($past(select,1) == 1'b1) && ($past(select,2) == 1'b0))
        |-> (out == $past(out) + 4'd2)
    );

    // If prior selects were 1 then 0, out holds this cycle.
    hold_now_when_prev10: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(reset,1) && !$past(reset,2) && ($past(select,1) == 1'b0) && ($past(select,2) == 1'b1))
        |-> (out == $past(out))
    );
endmodule

