module Mux8(sel, i0, i1, i2, i3, i4, i5, i6, i7, o);

	parameter data_width = 8;

	input[2 : 0] sel;
	input[data_width - 1 : 0] i0;
	input[data_width - 1 : 0] i1;
	input[data_width - 1 : 0] i2;
	input[data_width - 1 : 0] i3;
	input[data_width - 1 : 0] i4;
	input[data_width - 1 : 0] i5;
	input[data_width - 1 : 0] i6;
	input[data_width - 1 : 0] i7;
	output[data_width - 1 : 0] o;

	reg[data_width - 1 : 0] reg_o;

	always @(*) begin
		case (sel)
			0 : reg_o <= i0;
			1 : reg_o <= i1;
			2 : reg_o <= i2;
			3 : reg_o <= i3;
			4 : reg_o <= i4;
			5 : reg_o <= i5;
			6 : reg_o <= i6;
			7 : reg_o <= i7;
			default : ;
		endcase
	end

	assign o = reg_o;

endmodule

sva:
module Mux8_sva #(
    parameter data_width = 8
) (
    // Sampling clock (RTL has no clock/reset; pure combinational; use CLK only for assertion sampling)
    input  logic                         CLK,

    // DUT ports
    input  logic [2:0]                   sel,
    input  logic [data_width-1:0]        i0,
    input  logic [data_width-1:0]        i1,
    input  logic [data_width-1:0]        i2,
    input  logic [data_width-1:0]        i3,
    input  logic [data_width-1:0]        i4,
    input  logic [data_width-1:0]        i5,
    input  logic [data_width-1:0]        i6,
    input  logic [data_width-1:0]        i7,
    input  logic [data_width-1:0]        o
);

    ///// Functional mapping /////
    // Output equals the data selected by sel (pure combinational mux behavior).
    check_mux_function: assert property (
        @(posedge CLK) o == (
            (sel == 3'd0) ? i0 :
            (sel == 3'd1) ? i1 :
            (sel == 3'd2) ? i2 :
            (sel == 3'd3) ? i3 :
            (sel == 3'd4) ? i4 :
            (sel == 3'd5) ? i5 :
            (sel == 3'd6) ? i6 : i7
        )
    );

    ///// Stability guarantees /////
    // With sel=0 held and i0 stable, o remains stable.
    stable_sel0_i0: assert property (
        @(posedge CLK) (sel == 3'd0 && $stable(sel) && $stable(i0)) |-> $stable(o)
    );
    // With sel=1 held and i1 stable, o remains stable.
    stable_sel1_i1: assert property (
        @(posedge CLK) (sel == 3'd1 && $stable(sel) && $stable(i1)) |-> $stable(o)
    );
    // With sel=2 held and i2 stable, o remains stable.
    stable_sel2_i2: assert property (
        @(posedge CLK) (sel == 3'd2 && $stable(sel) && $stable(i2)) |-> $stable(o)
    );
    // With sel=3 held and i3 stable, o remains stable.
    stable_sel3_i3: assert property (
        @(posedge CLK) (sel == 3'd3 && $stable(sel) && $stable(i3)) |-> $stable(o)
    );
    // With sel=4 held and i4 stable, o remains stable.
    stable_sel4_i4: assert property (
        @(posedge CLK) (sel == 3'd4 && $stable(sel) && $stable(i4)) |-> $stable(o)
    );
    // With sel=5 held and i5 stable, o remains stable.
    stable_sel5_i5: assert property (
        @(posedge CLK) (sel == 3'd5 && $stable(sel) && $stable(i5)) |-> $stable(o)
    );
    // With sel=6 held and i6 stable, o remains stable.
    stable_sel6_i6: assert property (
        @(posedge CLK) (sel == 3'd6 && $stable(sel) && $stable(i6)) |-> $stable(o)
    );
    // With sel=7 held and i7 stable, o remains stable.
    stable_sel7_i7: assert property (
        @(posedge CLK) (sel == 3'd7 && $stable(sel) && $stable(i7)) |-> $stable(o)
    );

    ///// Change sensitivity /////
    // o changes only if sel changes or the currently selected input changes.
    check_o_change_causes: assert property (
        @(posedge CLK) $changed(o) |-> (
            $changed(sel) ||
            ((sel == 3'd0) && $changed(i0)) ||
            ((sel == 3'd1) && $changed(i1)) ||
            ((sel == 3'd2) && $changed(i2)) ||
            ((sel == 3'd3) && $changed(i3)) ||
            ((sel == 3'd4) && $changed(i4)) ||
            ((sel == 3'd5) && $changed(i5)) ||
            ((sel == 3'd6) && $changed(i6)) ||
            ((sel == 3'd7) && $changed(i7))
        )
    );

endmodule

rtl:
module LFSR25000(
input Clock,
input Reset,
output reg Out
);

reg [14:0] LFSR;

always @(posedge Clock, negedge Reset) begin
	if(Reset==0) begin
		Out <= 0;
		LFSR <= 15'b111111111111111;
	end
	else begin
		LFSR[0] <= LFSR[13] ^ LFSR[14];
		LFSR[14:1] <= LFSR[13:0];
		if(LFSR==15'b001000010001100) Out <= 1;
	end
end

endmodule

sva:
module LFSR25000_sva (
    input logic Clock,
    input logic Reset,      // active-low reset
    input logic Out,
    input logic [14:0] LFSR // internal reg from RTL
);
    localparam logic [14:0] RESET_VAL       = 15'b111111111111111;
    localparam logic [14:0] MATCH_VAL       = 15'b001000010001100;
    localparam logic [14:0] POST_RESET_VAL  = 15'b111111111111110;

    ///// Reset behavior /////
    // While Reset is LOW, Out must be 0.
    check_reset_out_zero: assert property (
        @(posedge Clock) (!Reset) |-> (Out == 1'b0)
    );

    // While Reset is LOW, LFSR must be all ones.
    check_reset_lfsr_ones: assert property (
        @(posedge Clock) (!Reset) |-> (LFSR == RESET_VAL)
    );

    // On Reset rising edge, next LFSR becomes shifted RESET pattern (111...110).
    check_lfsr_on_reset_release: assert property (
        @(posedge Clock) $rose(Reset) |-> (LFSR == POST_RESET_VAL)
    );

    // On Reset rising edge, Out remains 0.
    check_out_on_reset_release: assert property (
        @(posedge Clock) $rose(Reset) |-> (Out == 1'b0)
    );

    ///// Running behavior (Reset HIGH) /////
    // LFSR upper bits shift down by one when running.
    check_lfsr_upper_shift: assert property (
        @(posedge Clock) disable iff (!Reset) $past(Reset) |-> (LFSR[14:1] == $past(LFSR[13:0]))
    );

    // LFSR[0] is feedback XOR of previous LFSR[13] and LFSR[14].
    check_lfsr_feedback_bit: assert property (
        @(posedge Clock) disable iff (!Reset) $past(Reset) |-> (LFSR[0] == ($past(LFSR[13]) ^ $past(LFSR[14])))
    );

    // Out never falls while running (only reset can clear it).
    check_out_never_falls_running: assert property (
        @(posedge Clock) disable iff (!Reset) !$fell(Out)
    );

    // Out can only rise when previous LFSR matched the compare value.
    check_out_rise_only_on_match: assert property (
        @(posedge Clock) disable iff (!Reset) $rose(Out) |-> ($past(LFSR) == MATCH_VAL)
    );

    // If previous LFSR matched, Out must be 1 this cycle.
    check_match_implies_out1: assert property (
        @(posedge Clock) disable iff (!Reset) ($past(LFSR) == MATCH_VAL) |-> (Out == 1'b1)
    );

    // If previous LFSR did not match, Out holds its value.
    check_out_holds_without_match: assert property (
        @(posedge Clock) disable iff (!Reset) ($past(LFSR) != MATCH_VAL) |-> (Out == $past(Out))
    );
endmodule

