module top_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input [255:0] in, // 256-bit input for the multiplexer
    input [7:0] sel,  // 8-bit selection input for the multiplexer
    input direction,   // Direction input for the counter
    output [2:0] count, // 3-bit output from the counter
    output reg out     // 1-bit output from the functional module
);

    // 256-to-1 multiplexer module
    wire [7:0] mux_sel;
    wire mux_out;
    mux_256to1 mux (
        .in(in),
        .sel(mux_sel),
        .out(mux_out)
    );

    // Bidirectional 3-bit counter module
    wire [2:0] counter_out;
    bidir_counter counter (
        .clk(clk),
        .reset(reset),
        .direction(direction),
        .out(counter_out)
    );

    // Functional module that outputs the bitwise AND of the multiplexer and counter outputs
    always @(*) begin
        out = mux_out & counter_out[0];
    end

    // Connect the selection input of the multiplexer to the counter output
    assign mux_sel = counter_out[1:0] + sel;

    // Output the counter output
    assign count = counter_out;

endmodule

// 256-to-1 multiplexer module
module mux_256to1 (
    input [255:0] in, // 256-bit input
    input [7:0] sel,  // 8-bit selection input
    output reg out     // 1-bit output
);

    always @(*) begin
        out = in[sel];
    end

endmodule

// Bidirectional 3-bit counter module
module bidir_counter (
    input clk,
    input reset,      // Synchronous active-high reset
    input direction,   // Direction input
    output reg [2:0] out // 3-bit output
);

    always @(posedge clk) begin
        if (reset) begin
            out <= 3'b0;
        end else if (direction) begin
            out <= out + 1;
        end else begin
            out <= out - 1;
        end
    end

endmodule

sva:
module top_module_sva (
    input  logic        clk,
    input  logic        reset,       // synchronous active-high reset
    input  logic [255:0] in,
    input  logic [7:0]  sel,
    input  logic        direction,
    input  logic [2:0]  count,
    input  logic        out
);

    ///// Reset behavior /////
    // On a cycle where reset is 1, count becomes 0 on the next clock.
    reset_clears_count_next: assert property (
        @(posedge clk) reset |=> (count == 3'd0)
    );

    // While reset is held high across consecutive cycles, count is 0.
    reset_held_forces_zero: assert property (
        @(posedge clk) (reset && $past(reset)) |-> (count == 3'd0)
    );

    ///// Counter step rules /////
    // When direction is 1 (and no reset), next count = prior count + 1 (mod 8).
    count_increments_on_dir1: assert property (
        @(posedge clk) disable iff (reset)
            (!$isunknown(count) && direction) |=> (reset || (count == ({1'b0,$past(count)} + 4'd1)[2:0]))
    );

    // When direction is 0 (and no reset), next count = prior count - 1 (mod 8).
    count_decrements_on_dir0: assert property (
        @(posedge clk) disable iff (reset)
            (!$isunknown(count) && !direction) |=> (reset || (count == ({1'b0,$past(count)} + 4'd7)[2:0]))
    );

    // On every non-reset cycle, next count changes by exactly +/-1 (mod 8).
    count_changes_by_one_each_cycle: assert property (
        @(posedge clk) disable iff (reset)
            (!$isunknown(count)) |=> (
                reset ||
                ({1'b0,count} == ({1'b0,$past(count)} + 4'd1)) ||
                ({1'b0,count} == ({1'b0,$past(count)} + 4'd7))
            )
    );

    ///// Combinational output function /////
    // out equals in[sel + count[1:0]] AND count[0].
    out_function_equivalence: assert property (
        @(posedge clk) disable iff (reset)
            (!$isunknown({count, sel, in})) |-> (out == (in[(sel + {6'd0, count[1:0]})] & count[0]))
    );

    // If count[0] is 0, out must be 0.
    out_zero_when_count_lsb_zero: assert property (
        @(posedge clk) disable iff (reset)
            (count[0] == 1'b0) |-> (out == 1'b0)
    );

    // If count[0] is 1, out equals the selected input bit.
    out_equals_selected_bit_when_count_lsb_one: assert property (
        @(posedge clk) disable iff (reset)
            (count[0] == 1'b1 && !$isunknown({sel, in})) |-> (out == in[(sel + {6'd0, count[1:0]})])
    );

    // If the selected input bit is 0, out must be 0.
    out_zero_when_selected_input_zero: assert property (
        @(posedge clk) disable iff (reset)
            (!$isunknown({sel, in})) && (in[(sel + {6'd0, count[1:0]})] == 1'b0) |-> (out == 1'b0)
    );

    // If the selected input bit and count[0] are 1, out must be 1.
    out_one_when_both_inputs_one: assert property (
        @(posedge clk) disable iff (reset)
            (!$isunknown({sel, in})) && (count[0] == 1'b1) && (in[(sel + {6'd0, count[1:0]})] == 1'b1) |-> (out == 1'b1)
    );

endmodule

rtl:
module top_module (
    input [3:0] in,
    output reg [7:0] out
);

reg [3:0] twos_comp_out;
reg [3:0] bcd_out;

twos_complement twos_comp_inst (
    .in(in),
    .out(twos_comp_out)
);

bcd_converter bcd_inst (
    .binary_input(in),
    .bcd_output(bcd_out)
);

output_combiner combiner_inst (
    .twos_comp_input(twos_comp_out),
    .bcd_input(bcd_out),
    .combined_output(out)
);

endmodule
module twos_complement (
    input [3:0] in,
    output reg [3:0] out
);

always @ (*) begin
    out = (~in) + 1;
end

endmodule
module bcd_converter (
    input [3:0] binary_input,
    output reg [3:0] bcd_output
);

always @ (*) begin
    case (binary_input)
        4'b0000: bcd_output = 4'b0000;
        4'b0001: bcd_output = 4'b0001;
        4'b0010: bcd_output = 4'b0010;
        4'b0011: bcd_output = 4'b0011;
        4'b0100: bcd_output = 4'b0100;
        4'b0101: bcd_output = 4'b0101;
        4'b0110: bcd_output = 4'b0110;
        4'b0111: bcd_output = 4'b0111;
        4'b1000: bcd_output = 4'b1000;
        4'b1001: bcd_output = 4'b1001;
        4'b1010: bcd_output = 4'b0001;
        4'b1011: bcd_output = 4'b0010;
        4'b1100: bcd_output = 4'b0011;
        4'b1101: bcd_output = 4'b0100;
        4'b1110: bcd_output = 4'b0101;
        4'b1111: bcd_output = 4'b0110;
    endcase
end

endmodule
module output_combiner (
    input [3:0] twos_comp_input,
    input [3:0] bcd_input,
    output reg [7:0] combined_output
);

always @ (*) begin
    combined_output = {twos_comp_input, bcd_input};
end

endmodule

sva:
module top_module_sva (
    input logic CLK,
    input logic [3:0] in,
    input logic [7:0] out
);

    // Helper: 4-bit two's complement of x
    function automatic logic [3:0] f_twos (input logic [3:0] x);
        f_twos = (~x) + 4'd1;
    endfunction

    // Helper: 4-bit BCD mapping as implemented in RTL
    function automatic logic [3:0] f_bcd (input logic [3:0] x);
        unique case (x)
            4'b0000: f_bcd = 4'b0000;
            4'b0001: f_bcd = 4'b0001;
            4'b0010: f_bcd = 4'b0010;
            4'b0011: f_bcd = 4'b0011;
            4'b0100: f_bcd = 4'b0100;
            4'b0101: f_bcd = 4'b0101;
            4'b0110: f_bcd = 4'b0110;
            4'b0111: f_bcd = 4'b0111;
            4'b1000: f_bcd = 4'b1000;
            4'b1001: f_bcd = 4'b1001;
            4'b1010: f_bcd = 4'b0001;
            4'b1011: f_bcd = 4'b0010;
            4'b1100: f_bcd = 4'b0011;
            4'b1101: f_bcd = 4'b0100;
            4'b1110: f_bcd = 4'b0101;
            4'b1111: f_bcd = 4'b0110;
            default: f_bcd = 4'b0000;
        endcase
    endfunction

    // Combined output matches concatenation of two's complement and BCD of in.
    check_combined_output: assert property (
        @(posedge CLK) out == { f_twos(in), f_bcd(in) }
    );

    // Upper nibble equals two's complement of in.
    check_twos_high_nibble: assert property (
        @(posedge CLK) out[7:4] == f_twos(in)
    );

    // Lower nibble equals BCD mapping of in.
    check_bcd_low_nibble: assert property (
        @(posedge CLK) out[3:0] == f_bcd(in)
    );

    // For in 0..9, BCD nibble equals in.
    check_bcd_small_digits: assert property (
        @(posedge CLK) (in <= 4'd9) |-> (out[3:0] == in)
    );

    // For in 10..15, BCD nibble equals in - 9.
    check_bcd_large_digits: assert property (
        @(posedge CLK) (in >= 4'd10) |-> (out[3:0] == (in - 4'd9))
    );

    // BCD nibble is always in range 0..9.
    check_bcd_digit_range: assert property (
        @(posedge CLK) out[3:0] <= 4'd9
    );

    // Input 0 produces 0x00 on out.
    check_zero_input_output_zero: assert property (
        @(posedge CLK) (in == 4'd0) |-> (out == 8'h00)
    );

    // Upper nibble zero only when in is zero.
    check_upper_zero_implies_input_zero: assert property (
        @(posedge CLK) (out[7:4] == 4'd0) |-> (in == 4'd0)
    );

    // If input is stable, output remains stable.
    check_output_stable_when_input_stable: assert property (
        @(posedge CLK) $stable(in) |-> $stable(out)
    );

    // Applying two's complement to upper nibble returns original in.
    check_twos_involution_via_out: assert property (
        @(posedge CLK) f_twos(out[7:4]) == in
    );

endmodule

rtl:
module acciones_to_bcd(
	 input clk,
	 input rst,
	 input [1:0] piso, input [1:0] accion, input puertas, output reg [3:0] BCD1,
	 output reg [3:0] BCD2,
	 output reg [3:0] BCD3,
	 output reg [3:0] BCD4
    );

initial begin
	BCD4 = 1;
	BCD3 = 9;
	BCD2 = 6;
	BCD1 = 0;
end

always @ (posedge clk)
	begin
		if (rst == 1)
			begin
				BCD4 = 4'b1110;
				#10 BCD4 = 4'b0001;
				BCD3 = 4'b0110;
				#10 BCD3 = 4'b1001;
			end
		else
			begin
				if (piso == 2'b00)
					BCD4 = 4'b0001;
				else if (piso == 2'b01)
					BCD4 = 4'b0010;
				else if (piso == 2'b10)
					BCD4 = 4'b0011;
				else
					BCD4 = 4'b0100;
			end
	end

always @ (posedge clk)
	begin
		if (rst == 1)
			begin
				BCD1 = 4'b1111;
				#10 BCD1 = 4'b0000;
			end
		else
			begin
				if (accion == 2'b00)
					BCD1 = 4'b0000;
				else if (accion == 2'b01)
					BCD1 = 4'b0101;
				else if (accion == 2'b10)
					BCD1 = 4'b1000;
				else
					BCD1 = 0;
			end
	end

always @ (posedge clk)
	begin
		if (rst == 1)
			begin
				BCD2 = 4'b1001;
				#10 BCD2 = 4'b0110;
			end
		else
			begin
				if (puertas == 1'b0)
					BCD2 = 4'b0111;
				else
					BCD2 = 4'b0110;
			end
	end

endmodule

sva:
module acciones_to_bcd_sva (
    input logic clk,
    input logic rst,
    input logic [1:0] piso,
    input logic [1:0] accion,
    input logic puertas,
    input logic [3:0] BCD1,
    input logic [3:0] BCD2,
    input logic [3:0] BCD3,
    input logic [3:0] BCD4
);

    ///// BCD4 decodes piso when not in reset /////
    // piso==00 maps to BCD4=0001.
    check_bcd4_maps_piso_00: assert property (
        @(posedge clk) disable iff (rst) (piso == 2'b00) |-> (BCD4 == 4'b0001)
    );
    // piso==01 maps to BCD4=0010.
    check_bcd4_maps_piso_01: assert property (
        @(posedge clk) disable iff (rst) (piso == 2'b01) |-> (BCD4 == 4'b0010)
    );
    // piso==10 maps to BCD4=0011.
    check_bcd4_maps_piso_10: assert property (
        @(posedge clk) disable iff (rst) (piso == 2'b10) |-> (BCD4 == 4'b0011)
    );
    // piso==11 maps to BCD4=0100.
    check_bcd4_maps_piso_11: assert property (
        @(posedge clk) disable iff (rst) (piso == 2'b11) |-> (BCD4 == 4'b0100)
    );

    ///// BCD1 decodes accion when not in reset /////
    // accion==00 maps to BCD1=0000.
    check_bcd1_maps_accion_00: assert property (
        @(posedge clk) disable iff (rst) (accion == 2'b00) |-> (BCD1 == 4'b0000)
    );
    // accion==01 maps to BCD1=0101.
    check_bcd1_maps_accion_01: assert property (
        @(posedge clk) disable iff (rst) (accion == 2'b01) |-> (BCD1 == 4'b0101)
    );
    // accion==10 maps to BCD1=1000.
    check_bcd1_maps_accion_10: assert property (
        @(posedge clk) disable iff (rst) (accion == 2'b10) |-> (BCD1 == 4'b1000)
    );
    // accion==11 maps to BCD1=0000.
    check_bcd1_maps_accion_11: assert property (
        @(posedge clk) disable iff (rst) (accion == 2'b11) |-> (BCD1 == 4'b0000)
    );

    ///// BCD2 decodes puertas when not in reset /////
    // puertas==0 maps to BCD2=0111.
    check_bcd2_maps_puertas_0: assert property (
        @(posedge clk) disable iff (rst) (puertas == 1'b0) |-> (BCD2 == 4'b0111)
    );
    // puertas==1 maps to BCD2=0110.
    check_bcd2_maps_puertas_1: assert property (
        @(posedge clk) disable iff (rst) (puertas == 1'b1) |-> (BCD2 == 4'b0110)
    );

    ///// BCD3 behavior /////
    // When not in reset, BCD3 holds its value (no assignment in RTL).
    check_bcd3_stable_outside_reset: assert property (
        @(posedge clk) disable iff (rst) $stable(BCD3)
    );

endmodule

