module comparator (
    input [2:0] a,
    input [2:0] b,
    output reg gt,
    output reg eq,
    output reg lt
);

    always @(*) begin
        if(a > b) begin
            gt = 1;
            eq = 0;
            lt = 0;
        end
        else if(a == b) begin
            gt = 0;
            eq = 1;
            lt = 0;
        end
        else begin
            gt = 0;
            eq = 0;
            lt = 1;
        end
    end

endmodule

sva:
module comparator_sva (
    input logic clk,          // sampling clock for SVA (DUT has no clock/reset)
    input logic [2:0] a,
    input logic [2:0] b,
    input logic gt,
    input logic eq,
    input logic lt
);

    // Exactly one of gt/eq/lt is HIGH.
    check_outputs_onehot: assert property (
        @(posedge clk) $onehot({gt, eq, lt})
    );

    // If a > b then gt=1, eq=0, lt=0.
    check_outputs_when_a_gt_b: assert property (
        @(posedge clk) (a > b) |-> (gt && !eq && !lt)
    );

    // If a == b then eq=1, gt=0, lt=0.
    check_outputs_when_a_eq_b: assert property (
        @(posedge clk) (a == b) |-> (!gt && eq && !lt)
    );

    // If a < b then lt=1, gt=0, eq=0.
    check_outputs_when_a_lt_b: assert property (
        @(posedge clk) (a < b) |-> (!gt && !eq && lt)
    );

    // gt implies a > b.
    check_gt_implies_relation: assert property (
        @(posedge clk) gt |-> (a > b)
    );

    // eq implies a == b.
    check_eq_implies_relation: assert property (
        @(posedge clk) eq |-> (a == b)
    );

    // lt implies a < b.
    check_lt_implies_relation: assert property (
        @(posedge clk) lt |-> (a < b)
    );

endmodule

rtl:
module chatgpt_generate_JC_counter(
  input                clk,
  input                rst_n,
  output reg  [63:0]   Q
);

  reg [63:0] lfsr;

  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      lfsr <= 64'h0000000000000000;
      Q <= 64'h0000000000000000;
    end else begin
      lfsr <= {lfsr[62:0], lfsr[63] ^ lfsr[0] ^ lfsr[1] ^ lfsr[3]};
      Q <= lfsr;
    end
  end

endmodule

sva:
module chatgpt_generate_JC_counter_sva (
    input logic              clk,
    input logic              rst_n,
    input logic [63:0]       Q,
    input logic [63:0]       lfsr
);

    ///// Reset behavior /////
    // While reset is asserted, Q and lfsr must be zero.
    check_reset_drives_zero: assert property (
        @(posedge clk) (!rst_n) |-> (Q == 64'h0) && (lfsr == 64'h0)
    );

    // While reset is asserted, Q and lfsr remain stable.
    check_reset_stability: assert property (
        @(posedge clk) (!rst_n) |-> $stable(Q) && $stable(lfsr)
    );

    // On reset deassertion, Q and lfsr are zero on that clock.
    check_deassertion_zero: assert property (
        @(posedge clk) $rose(rst_n) |-> (Q == 64'h0) && (lfsr == 64'h0)
    );

    // After reset release, Q and lfsr remain zero until reset reasserts.
    hold_zero_after_release: assert property (
        @(posedge clk) $rose(rst_n) |-> ((Q == 64'h0) && (lfsr == 64'h0)) until_with (!rst_n)
    );

    ///// Sequential update relations (out of reset) /////
    // When out of reset in consecutive cycles, Q equals previous lfsr.
    check_q_tracks_prev_lfsr: assert property (
        @(posedge clk) disable iff (!rst_n)
            $past(rst_n) |-> (Q == $past(lfsr))
    );

    // When out of reset in consecutive cycles, lfsr updates per shift/XOR polynomial.
    check_lfsr_update_vector: assert property (
        @(posedge clk) disable iff (!rst_n)
            $past(rst_n) |-> (lfsr == { $past(lfsr[62:0]), ($past(lfsr[63]) ^ $past(lfsr[0]) ^ $past(lfsr[1]) ^ $past(lfsr[3])) })
    );

    // Upper bits of lfsr shift left by one when out of reset.
    check_lfsr_shift_upper: assert property (
        @(posedge clk) disable iff (!rst_n)
            $past(rst_n) |-> (lfsr[63:1] == $past(lfsr[62:0]))
    );

    // LSB of lfsr equals XOR of taps 63,0,1,3 from previous cycle when out of reset.
    check_lfsr_lsb_from_taps: assert property (
        @(posedge clk) disable iff (!rst_n)
            $past(rst_n) |-> (lfsr[0] == ($past(lfsr[63]) ^ $past(lfsr[0]) ^ $past(lfsr[1]) ^ $past(lfsr[3])))
    );

    // Zero state is absorbing for lfsr when out of reset.
    check_lfsr_zero_absorbing: assert property (
        @(posedge clk) disable iff (!rst_n)
            ($past(rst_n) && $past(lfsr == 64'h0)) |-> (lfsr == 64'h0)
    );

    // If previous lfsr was zero out of reset, Q must be zero now.
    check_q_zero_when_prev_lfsr_zero: assert property (
        @(posedge clk) disable iff (!rst_n)
            ($past(rst_n) && $past(lfsr == 64'h0)) |-> (Q == 64'h0)
    );

endmodule

module ArithmeticUnit_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [2:0] C,
    input logic [3:0] R
);
    // For C==000, R equals 4-bit sum of A and B (wraps on overflow).
    check_addition_result: assert property (
        @(posedge clk) (C == 3'b000) |-> (R === (A + B))
    );

    // For C==001, R equals 4-bit difference A - B (wraps on underflow).
    check_subtraction_result: assert property (
        @(posedge clk) (C == 3'b001) |-> (R === (A - B))
    );

    // For all other C values, R is driven to zero.
    check_default_zero: assert property (
        @(posedge clk) ((C != 3'b000) && (C != 3'b001)) |-> (R === 4'b0000)
    );

    // Addition identity: adding zero on B passes A through.
    check_add_zero_b: assert property (
        @(posedge clk) ((C == 3'b000) && (B == 4'b0000)) |-> (R === A)
    );

    // Addition identity: adding zero on A passes B through.
    check_add_zero_a: assert property (
        @(posedge clk) ((C == 3'b000) && (A == 4'b0000)) |-> (R === B)
    );

    // Subtraction identity: subtracting zero passes A through.
    check_sub_zero_b: assert property (
        @(posedge clk) ((C == 3'b001) && (B == 4'b0000)) |-> (R === A)
    );

    // Subtraction of equal operands yields zero.
    check_sub_equal_operands_zero: assert property (
        @(posedge clk) ((C == 3'b001) && (A == B)) |-> (R === 4'b0000)
    );

    // When adding equal operands, result equals A<<1 (4-bit wrap).
    check_add_double_when_equal: assert property (
        @(posedge clk) ((C == 3'b000) && (A == B)) |-> (R === (A << 1))
    );

    // Example wrap on addition: 0xF + 1 => 0x0.
    check_add_wrap_example: assert property (
        @(posedge clk) ((C == 3'b000) && (A == 4'hF) && (B == 4'h1)) |-> (R === 4'h0)
    );

    // Example borrow on subtraction: 0x0 - 1 => 0xF.
    check_sub_borrow_example: assert property (
        @(posedge clk) ((C == 3'b001) && (A == 4'h0) && (B == 4'h1)) |-> (R === 4'hF)
    );
endmodule

