sva:
module sky130_fd_sc_ls__xor2_sva (
    input logic CLK,          // sampling clock for assertions
    input logic X,            // DUT output
    input logic A,            // DUT input
    input logic B,            // DUT input
    input logic xor0_out_X    // DUT internal net
);
    // DUT has no clock/reset; pure combinational XOR with output buffer.
    // Key behavior: X = A ^ B, with X buffered from xor0_out_X.

    // X must equal A XOR B.
    check_xor_equals_expr: assert property (
        @(posedge CLK) X == (A ^ B)
    );

    // Internal XOR output must equal A XOR B.
    check_internal_xor_equals_expr: assert property (
        @(posedge CLK) xor0_out_X == (A ^ B)
    );

    // Buffer must pass internal XOR output to X.
    check_buf_pass_through: assert property (
        @(posedge CLK) X == xor0_out_X
    );

    // Truth table: 00 -> 0.
    check_truth_00: assert property (
        @(posedge CLK) (A == 1'b0 && B == 1'b0) |-> (X == 1'b0)
    );

    // Truth table: 01 -> 1.
    check_truth_01: assert property (
        @(posedge CLK) (A == 1'b0 && B == 1'b1) |-> (X == 1'b1)
    );

    // Truth table: 10 -> 1.
    check_truth_10: assert property (
        @(posedge CLK) (A == 1'b1 && B == 1'b0) |-> (X == 1'b1)
    );

    // Truth table: 11 -> 0.
    check_truth_11: assert property (
        @(posedge CLK) (A == 1'b1 && B == 1'b1) |-> (X == 1'b0)
    );

    // When B is 0, X must equal A.
    check_b_zero_transparent: assert property (
        @(posedge CLK) (B == 1'b0) |-> (X == A)
    );

    // When B is 1, X must equal inverted A.
    check_b_one_inverts_a: assert property (
        @(posedge CLK) (B == 1'b1) |-> (X == ~A)
    );

    // When A is 0, X must equal B.
    check_a_zero_transparent: assert property (
        @(posedge CLK) (A == 1'b0) |-> (X == B)
    );

    // When A is 1, X must equal inverted B.
    check_a_one_inverts_b: assert property (
        @(posedge CLK) (A == 1'b1) |-> (X == ~B)
    );

endmodule

rtl:
module adder(
    input signed [31:0] a,
    input signed [31:0] b,
    input clk,
    output reg signed [31:0] sum
);

reg signed [31:0] temp_sum;
reg overflow;

always @(posedge clk) begin
    temp_sum = a + b;
    overflow = (a[31] == b[31]) && (temp_sum[31] != a[31]);
    if (overflow) begin
        if (a[31] == 1) begin
            sum <= -2147483648; // minimum value for 32-bit signed two's complement
        end else begin
            sum <= 2147483647; // maximum value for 32-bit signed two's complement
        end
    end else begin
        sum <= temp_sum;
    end
end

endmodule

sva:
module adder_sva (
    input logic clk,
    input logic signed [31:0] a,
    input logic signed [31:0] b,
    input logic signed [31:0] sum
);
    // Clock: clk. No reset in RTL. Sequential saturating signed adder.

    // Helper: 32-bit signed saturating add of x+y per RTL
    let sat_add(x, y) = (((x[31] == y[31]) && (((x + y)[31]) != x[31])) ? (x[31] ? 32'sh8000_0000 : 32'sh7fff_ffff) : (x + y));

    ///// Saturation behavior /////
    // Next-cycle sum equals saturating add of current a and b.
    check_saturating_sum: assert property (
        @(posedge clk) 1 |=> (sum == sat_add($past(a), $past(b)))
    );

    ///// No-overflow cases /////
    // If signs differ, next-cycle sum equals raw a+b (no overflow possible).
    check_no_overflow_opposite_signs: assert property (
        @(posedge clk) ($past(a)[31] != $past(b)[31]) |=> (sum == ($past(a) + $past(b)))
    );

    // If signs same and raw sum sign matches input sign, next-cycle sum equals raw a+b.
    check_no_overflow_same_sign_no_wrap: assert property (
        @(posedge clk) (($past(a)[31] == $past(b)[31]) && ((($past(a) + $past(b))[31]) == $past(a)[31])) |=> (sum == ($past(a) + $past(b)))
    );

    ///// Overflow saturation /////
    // Positive overflow (two positives producing negative) saturates to +MAX.
    check_positive_overflow_saturates_max: assert property (
        @(posedge clk) (($past(a)[31] == 1'b0) && ($past(b)[31] == 1'b0) && ((($past(a) + $past(b))[31]) == 1'b1)) |=> (sum == 32'sh7fff_ffff)
    );

    // Negative overflow (two negatives producing positive) saturates to -MIN.
    check_negative_overflow_saturates_min: assert property (
        @(posedge clk) (($past(a)[31] == 1'b1) && ($past(b)[31] == 1'b1) && ((($past(a) + $past(b))[31]) == 1'b0)) |=> (sum == 32'sh8000_0000)
    );

    ///// Basic arithmetic identities honored /////
    // 0 + 0 yields 0 on next cycle.
    check_zero_plus_zero: assert property (
        @(posedge clk) (($past(a) == 32'sd0) && ($past(b) == 32'sd0)) |=> (sum == 32'sd0)
    );

    // Adding zero on b passes a through on next cycle.
    check_add_zero_b_transparent: assert property (
        @(posedge clk) ($past(b) == 32'sd0) |=> (sum == $past(a))
    );

    // Adding zero on a passes b through on next cycle.
    check_add_zero_a_transparent: assert property (
        @(posedge clk) ($past(a) == 32'sd0) |=> (sum == $past(b))
    );

    // When no overflow, next-cycle sum sign matches raw sum sign.
    check_sign_matches_when_no_overflow: assert property (
        @(posedge clk)
            !((($past(a)[31] == $past(b)[31]) && ((($past(a) + $past(b))[31]) != $past(a)[31])))
            |=> (sum[31] == ($past(a) + $past(b))[31])
    );

endmodule

rtl:
module comparator (
    input [3:0] A,
    input [3:0] B,
    output EQ,
    output GT,
    output LT
);

    assign EQ = (A == B);
    assign GT = (A > B);
    assign LT = (A < B);

endmodule

sva:
module comparator_sva (
    input logic CLK,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic EQ,
    input logic GT,
    input logic LT
);
    // EQ equals (A == B).
    check_eq_definition: assert property (
        @(posedge CLK) (EQ === (A == B))
    );

    // GT equals (A > B).
    check_gt_definition: assert property (
        @(posedge CLK) (GT === (A > B))
    );

    // LT equals (A < B).
    check_lt_definition: assert property (
        @(posedge CLK) (LT === (A < B))
    );

    // If EQ is 1 then GT is 0.
    check_eq_excludes_gt: assert property (
        @(posedge CLK) EQ |-> (GT == 1'b0)
    );

    // If EQ is 1 then LT is 0.
    check_eq_excludes_lt: assert property (
        @(posedge CLK) EQ |-> (LT == 1'b0)
    );

    // If GT is 1 then EQ is 0.
    check_gt_excludes_eq: assert property (
        @(posedge CLK) GT |-> (EQ == 1'b0)
    );

    // If GT is 1 then LT is 0.
    check_gt_excludes_lt: assert property (
        @(posedge CLK) GT |-> (LT == 1'b0)
    );

    // If LT is 1 then EQ is 0.
    check_lt_excludes_eq: assert property (
        @(posedge CLK) LT |-> (EQ == 1'b0)
    );

    // If LT is 1 then GT is 0.
    check_lt_excludes_gt: assert property (
        @(posedge CLK) LT |-> (GT == 1'b0)
    );

    // With known inputs, exactly one of {EQ,GT,LT} is 1.
    check_onehot_when_inputs_known: assert property (
        @(posedge CLK) (!$isunknown({A,B})) |-> $onehot({EQ,GT,LT})
    );
endmodule

rtl:
module UART_Rx #(
 parameter N    = 5,
 parameter Full = 5'd29 // Clk / BAUD - 1
)(
 input Reset,
 input Clk,

 output reg [7:0]Data,
 output reg      Ready,
 input           Ack,

 input 			 Rx
);
//------------------------------------------------------------------------------

reg        tRx;
reg        tAck;
reg [  7:0]Temp;
reg [N-1:0]Count;
reg [  2:0]BitCount;
reg        NewData;
//------------------------------------------------------------------------------

reg   [1:0]State;
localparam Idle      = 2'b00;
localparam StartBit  = 2'b01;
localparam Receiving = 2'b11;
localparam Done      = 2'b10;
//------------------------------------------------------------------------------

reg tReset;

always @(posedge Clk) begin
 tRx    <= Rx;
 tAck   <= Ack;
 tReset <= Reset;

 if(tReset) begin
  Data    <= 0;
  Ready   <= 0;
  NewData <= 0;

  Count <= 0;

  State <= Idle;
//------------------------------------------------------------------------------

 end else begin
  if(Ready & tAck) Ready <= 1'b0;

  case(State)
   Idle: begin
    if(~tRx) begin
     Count <= {1'b0, Full[N-1:1]};
     State <= StartBit;
    end

    if(NewData & ~tAck && ~Ready) begin 
     Data    <= Temp;
     Ready   <= 1'b1;
     NewData <= 1'b0;
    end
   end
//------------------------------------------------------------------------------

   Done: begin
    if(tRx) State <= Idle;
   end
   default:;
  endcase
//------------------------------------------------------------------------------

  if(~|Count) begin
   case(State)
    StartBit: begin
     if(Rx) begin
      State <= Idle;
     end else begin
      BitCount <= 0;
      Count    <= Full;
      State    <= Receiving;
     end 
    end
//------------------------------------------------------------------------------ 

    Receiving: begin
     Temp  <= {tRx, Temp[7:1]};
     Count <= Full;

     if(&BitCount) begin
      NewData <= 1'b1;
      State   <= Done;
     end

     BitCount <= BitCount + 1'b1;
    end
//------------------------------------------------------------------------------ 

    default:;
   endcase
  end else begin
   Count <= Count - 1'b1;
  end
 end
end
//------------------------------------------------------------------------------

endmodule

sva:
module UART_Rx_sva #(
    parameter int N = 5,
    parameter logic [N-1:0] Full = 5'd29
)(
    input logic Reset,
    input logic Clk,

    input logic [7:0] Data,
    input logic       Ready,
    input logic       Ack,
    input logic       Rx,

    // Internal signals from DUT
    input logic       tRx,
    input logic       tAck,
    input logic [7:0] Temp,
    input logic [N-1:0] Count,
    input logic [2:0] BitCount,
    input logic       NewData,
    input logic [1:0] State,
    input logic       tReset
);
    // Local copies of state encodings for readability
    localparam logic [1:0] Idle      = 2'b00;
    localparam logic [1:0] StartBit  = 2'b01;
    localparam logic [1:0] Receiving = 2'b11;
    localparam logic [1:0] Done      = 2'b10;

    ///// Reset behavior /////
    // On synchronous reset, clear state and outputs next cycle.
    reset_seq_clear: assert property (
        @(posedge Clk) tReset |=> (Data == 8'h00) && (Ready == 1'b0) && (NewData == 1'b0) && (Count == {N{1'b0}}) && (State == Idle)
    );

    ///// Sampling flops /////
    // tRx is Rx delayed by one cycle.
    check_tRx_is_delayed_Rx: assert property (
        @(posedge Clk) disable iff (tReset) tRx == $past(Rx)
    );
    // tAck is Ack delayed by one cycle.
    check_tAck_is_delayed_Ack: assert property (
        @(posedge Clk) disable iff (tReset) tAck == $past(Ack)
    );

    ///// State encoding /////
    // State must be one of the defined encodings.
    check_state_encoding: assert property (
        @(posedge Clk) disable iff (tReset) (State inside {Idle, StartBit, Receiving, Done})
    );

    ///// Ready/Ack handshake /////
    // Ready clears one cycle after tAck is HIGH while Ready is HIGH.
    check_ready_clears_on_tAck: assert property (
        @(posedge Clk) disable iff (tReset) (Ready && tAck) |=> !Ready
    );
    // Ready holds HIGH if tAck is LOW.
    check_ready_holds_without_tAck: assert property (
        @(posedge Clk) disable iff (tReset) (Ready && !tAck) |=> Ready
    );
    // A falling Ready must be caused by tAck in the previous cycle.
    check_ready_fall_caused_by_tAck: assert property (
        @(posedge Clk) disable iff (tReset) $fell(Ready) |-> $past(Ready && tAck)
    );

    ///// Start bit detection /////
    // StartBit can only be entered from Idle when tRx is LOW.
    check_startbit_entry_from_idle_only: assert property (
        @(posedge Clk) disable iff (tReset) (State == StartBit && $past(State) != StartBit) |-> $past(State == Idle && !tRx)
    );
    // From Idle with start detected and Count==0, preset Count to half and go to StartBit.
    check_idle_to_startbit_half_count: assert property (
        @(posedge Clk) disable iff (tReset) $past(State == Idle && !tRx && (Count == {N{1'b0}})) |=> (State == StartBit) && (Count == {1'b0, Full[N-1:1]})
    );
    // In StartBit with Count==0 and Rx HIGH, return to Idle next cycle.
    check_startbit_abort_on_high_Rx: assert property (
        @(posedge Clk) disable iff (tReset) $past(State == StartBit && (Count == {N{1'b0}}) && (Rx == 1'b1)) |=> (State == Idle)
    );
    // In StartBit with Count==0 and Rx LOW, enter Receiving, reload Count, and clear BitCount.
    check_startbit_to_receiving_on_low_Rx: assert property (
        @(posedge Clk) disable iff (tReset) $past(State == StartBit && (Count == {N{1'b0}}) && (Rx == 1'b0)) |=> (State == Receiving) && (Count == Full) && (BitCount == 3'd0)
    );

    ///// Receiving bits /////
    // In Receiving at Count==0, reload Count to Full.
    check_receiving_reload_count: assert property (
        @(posedge Clk) disable iff (tReset) $past(State == Receiving && (Count == {N{1'b0}})) |=> (Count == Full)
    );
    // In Receiving at Count==0, shift in tRx into Temp.
    check_receiving_shift: assert property (
        @(posedge Clk) disable iff (tReset) $past(State == Receiving && (Count == {N{1'b0}})) |=> (Temp == {$past(tRx), $past(Temp[7:1])})
    );
    // When the last bit is sampled, assert NewData and go to Done.
    check_receiving_done_on_last_bit: assert property (
        @(posedge Clk) disable iff (tReset) $past(State == Receiving && (Count == {N{1'b0}}) && (&BitCount)) |=> (NewData == 1'b1) && (State == Done)
    );

    ///// Done/Idle transition /////
    // In Done, when tRx is HIGH, return to Idle next cycle.
    check_done_to_idle_on_high_tRx: assert property (
        @(posedge Clk) disable iff (tReset) $past(State == Done && tRx) |=> (State == Idle)
    );

    ///// Data/Ready generation in Idle /////
    // In Idle with NewData and no tAck and Ready LOW, latch Temp to Data, raise Ready, and clear NewData.
    check_data_latch_in_idle_when_newdata_no_ack: assert property (
        @(posedge Clk) disable iff (tReset) $past(State == Idle && NewData && !tAck && !Ready) |=> (Data == $past(Temp)) && (Ready == 1'b1) && (NewData == 1'b0)
    );
    // When Ready rises, Data must equal previous Temp and NewData must be cleared.
    check_ready_rise_latches_data_and_clears_newdata: assert property (
        @(posedge Clk) disable iff (tReset) $rose(Ready) |-> (Data == $past(Temp)) && (NewData == 1'b0)
    );

    ///// Counter behavior /////
    // When Count is non-zero, it decrements by 1 next cycle.
    check_count_decrements_when_nonzero: assert property (
        @(posedge Clk) disable iff (tReset) $past(Count != {N{1'b0}}) |=> (Count == ($past(Count) - {{(N-1){1'b0}},1'b1}))
    );

    ///// Temp write points /////
    // Temp only updates when sampling a bit in Receiving at Count==0.
    check_temp_changes_only_on_sample: assert property (
        @(posedge Clk) disable iff (tReset) $changed(Temp) |-> $past(State == Receiving && (Count == {N{1'b0}}))
    );
endmodule

module counter_3bit_sva (
    input logic clk,
    input logic reset,
    input logic enable,
    input logic [2:0] count
);
    // Reset low forces count to zero at the sampling edge.
    reset_forces_zero: assert property (
        @(posedge clk) (!reset) |-> (count == 3'd0)
    );

    // On the first clock after reset deasserts, count is still zero.
    zero_on_reset_release: assert property (
        @(posedge clk) ($past(!reset) && reset) |-> (count == 3'd0)
    );

    // With enable LOW, count holds its previous value (when out of reset).
    hold_when_enable_low: assert property (
        @(posedge clk) disable iff (!reset) ($past(reset) && !enable) |-> (count == $past(count))
    );

    // With enable HIGH, count increments by 1 modulo 8 (when out of reset).
    increment_when_enable_high: assert property (
        @(posedge clk) disable iff (!reset) ($past(reset) && enable) |-> (count == (($past(count) == 3'd7) ? 3'd0 : ($past(count) + 3'd1)))
    );

    // When previous count was 7 and enable HIGH, wrap to 0.
    wrap_on_max_value: assert property (
        @(posedge clk) disable iff (!reset) ($past(reset) && ($past(count) == 3'd7) && enable) |-> (count == 3'd0)
    );

    // Any change in count (while out of reset) requires enable was HIGH in the prior cycle.
    change_requires_prev_enable: assert property (
        @(posedge clk) disable iff (!reset) ($past(reset) && (count != $past(count))) |-> $past(enable)
    );

    // With enable HIGH (while out of reset), count must change from the prior cycle.
    enable_implies_change: assert property (
        @(posedge clk) disable iff (!reset) ($past(reset) && enable) |-> (count != $past(count))
    );

    // If enable is HIGH for two consecutive cycles, count advances by 2 modulo 8.
    two_cycle_enable_increments_by_two: assert property (
        @(posedge clk) disable iff (!reset) ($past(reset,2) && $past(enable) && enable) |-> (count == (($past(count,2) + 3'd2)[2:0]))
    );
endmodule

module Bitwise_Or_sva (
  input logic CLK,
  input logic [31:0] in0,
  input logic [31:0] in1,
  input logic enable,
  input logic [31:0] out
);

  // When enable is HIGH, out equals bitwise OR of in0 and in1.
  check_or_when_enabled: assert property (
    @(posedge CLK) enable |-> (out == (in0 | in1))
  );

  // When enable is LOW, out is all zeros.
  check_zero_when_disabled: assert property (
    @(posedge CLK) !enable |-> (out == 32'h0)
  );

  // Output never has 1s where both inputs have 0s.
  check_no_spurious_ones: assert property (
    @(posedge CLK) (out & ~(in0 | in1)) == 32'h0
  );

  // When enabled, output includes all 1-bits present in either input.
  check_out_superset_inputs_when_enabled: assert property (
    @(posedge CLK) enable |-> (((in0 | in1) & ~out) == 32'h0)
  );

  // When enabled and in1 is zero, out equals in0.
  check_in1_zero_passthrough: assert property (
    @(posedge CLK) (enable && (in1 == 32'h0)) |-> (out == in0)
  );

  // When enabled and in0 is zero, out equals in1.
  check_in0_zero_passthrough: assert property (
    @(posedge CLK) (enable && (in0 == 32'h0)) |-> (out == in1)
  );

  // When enabled and inputs are equal, out equals that common value.
  check_equal_inputs_passthrough: assert property (
    @(posedge CLK) (enable && (in0 == in1)) |-> (out == in0)
  );

  // When enabled, out is a superset of each input bitwise.
  check_bitwise_inclusion_when_enabled: assert property (
    @(posedge CLK) enable |-> ((out | in0) == out && (out | in1) == out)
  );

endmodule

module decoder_sva (
    input logic CLK,
    input logic [2:0] ABC,
    input logic [7:0] Y
);
    ///// Functional decode checks /////
    // Y must always be exactly one-hot.
    check_y_onehot: assert property (
        @(posedge CLK) $onehot(Y)
    );

    // Y must equal 1 shifted left by ABC.
    check_decode_shift: assert property (
        @(posedge CLK) Y == (8'b00000001 << ABC)
    );

    ///// Inverse mapping: Y bit implies ABC value /////
    // If Y[0] is HIGH, ABC must be 000.
    check_y0_implies_abc0: assert property (
        @(posedge CLK) Y[0] |-> (ABC == 3'b000)
    );

    // If Y[1] is HIGH, ABC must be 001.
    check_y1_implies_abc1: assert property (
        @(posedge CLK) Y[1] |-> (ABC == 3'b001)
    );

    // If Y[2] is HIGH, ABC must be 010.
    check_y2_implies_abc2: assert property (
        @(posedge CLK) Y[2] |-> (ABC == 3'b010)
    );

    // If Y[3] is HIGH, ABC must be 011.
    check_y3_implies_abc3: assert property (
        @(posedge CLK) Y[3] |-> (ABC == 3'b011)
    );

    // If Y[4] is HIGH, ABC must be 100.
    check_y4_implies_abc4: assert property (
        @(posedge CLK) Y[4] |-> (ABC == 3'b100)
    );

    // If Y[5] is HIGH, ABC must be 101.
    check_y5_implies_abc5: assert property (
        @(posedge CLK) Y[5] |-> (ABC == 3'b101)
    );

    // If Y[6] is HIGH, ABC must be 110.
    check_y6_implies_abc6: assert property (
        @(posedge CLK) Y[6] |-> (ABC == 3'b110)
    );

    // If Y[7] is HIGH, ABC must be 111.
    check_y7_implies_abc7: assert property (
        @(posedge CLK) Y[7] |-> (ABC == 3'b111)
    );
endmodule

