    input  A1  ;
    input  A2  ;
    input  B1_N;

    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    wire b         ;
    wire and0_out  ;
    wire nor0_out_Y;

    not not0 (b         , B1_N           );
