module sky130_fd_sc_lp__clkinvlp_sva (
    input logic CLK,
    input logic RESETn,
    input logic Y,
    input logic A
);
    // Y is always the logical inversion of A.
    check_inversion: assert property (
        @(posedge CLK) disable iff (!RESETn) (Y == ~A)
    );

    // A rising edge implies Y falls in the same cycle.
    check_a_rise_y_fall: assert property (
        @(posedge CLK) disable iff (!RESETn) $rose(A) |-> $fell(Y)
    );

    // A falling edge implies Y rises in the same cycle.
    check_a_fall_y_rise: assert property (
        @(posedge CLK) disable iff (!RESETn) $fell(A) |-> $rose(Y)
    );

    // Y rising edge implies A fell in the same cycle.
    check_y_rise_a_fall: assert property (
        @(posedge CLK) disable iff (!RESETn) $rose(Y) |-> $fell(A)
    );

    // Y falling edge implies A rose in the same cycle.
    check_y_fall_a_rise: assert property (
        @(posedge CLK) disable iff (!RESETn) $fell(Y) |-> $rose(A)
    );

    // Y only changes when A changes.
    check_y_change_requires_a_change: assert property (
        @(posedge CLK) disable iff (!RESETn) $changed(Y) |-> $changed(A)
    );

    // If A is stable, Y remains stable.
    check_a_stable_implies_y_stable: assert property (
        @(posedge CLK) disable iff (!RESETn) $stable(A) |-> $stable(Y)
    );

    // A and Y are never both HIGH simultaneously.
    check_never_both_high: assert property (
        @(posedge CLK) disable iff (!RESETn) !(A && Y)
    );
endmodule

rtl:
module my_module(
    input A,
    input B,
    input C,
    input D,
    input E,
    output reg X
);

    reg [31:0] T, T2;

    always @(*) begin
        if (A == 0) begin
            X = 0;
        end else begin
            T = B + C;
            if (T >= D) begin
                X = 1;
            end else begin
                T2 = E + T;
                if (T2 >= D) begin
                    X = 1;
                end else begin
                    X = 0;
                end
            end
        end
    end

endmodule

sva:
module my_module_sva (
    input logic CLK,   // Sampling clock for assertions (RTL is purely combinational)
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic E,
    input logic X
);
    // A low forces X low.
    check_a_low_forces_x0: assert property (
        @(posedge CLK) (A == 1'b0) |=> (X == 1'b0)
    );

    // If A is high and (B+C) >= D then X must be 1.
    check_t_ge_d_sets_x1: assert property (
        @(posedge CLK) ((A == 1'b1) && ((B + C) >= D)) |=> (X == 1'b1)
    );

    // If A is high and (B+C) < D then X equals ((E + (B + C)) >= D).
    check_else_path_exact: assert property (
        @(posedge CLK) ((A == 1'b1) && ((B + C) < D)) |=> (X == ((E + (B + C)) >= D))
    );

    // X can be 1 only when A is 1 and one of the comparisons is true.
    check_x1_only_when_conditions: assert property (
        @(posedge CLK) (X == 1'b1) |=> ((A == 1'b1) && ( ((B + C) >= D) || ((E + (B + C)) >= D) ))
    );

    // Full functional equivalence of X to the RTL logic.
    check_functional_equiv: assert property (
        @(posedge CLK) X == (A && ( ((B + C) >= D) || ((E + (B + C)) >= D) ))
    );

    // When D is 0 and A is 1, X must be 1.
    check_d_zero_implies_x1_when_a1: assert property (
        @(posedge CLK) ((A == 1'b1) && (D == 1'b0)) |=> (X == 1'b1)
    );
endmodule

module Adder_sva (
    input logic [2:0] A,
    input logic [2:0] B,
    input logic CLK,
    input logic RST,
    input logic [2:0] Q
);
    // Q is 0 whenever RST is asserted at the clock edge.
    check_q_zero_when_rst_high: assert property (
        @(posedge CLK) RST |-> (Q == 3'b000)
    );

    // When not in reset, Q equals A+B computed at that edge.
    check_q_equals_sum_when_not_reset: assert property (
        @(posedge CLK) disable iff (RST) (Q == (A + B))
    );

    // On a rising edge of RST, Q is forced to 0 in that cycle.
    check_reset_rise_forces_zero: assert property (
        @(posedge CLK) $rose(RST) |-> (Q == 3'b000)
    );

    // On a falling edge of RST, Q loads A+B in that cycle.
    check_reset_fall_loads_sum: assert property (
        @(posedge CLK) disable iff (RST) $fell(RST) |-> (Q == (A + B))
    );

    // If reset is high in two consecutive cycles, Q is 0 in both.
    check_hold_zero_during_reset: assert property (
        @(posedge CLK) RST && $past(RST) |-> (Q == 3'b000) && ($past(Q) == 3'b000)
    );

    // With reset low in consecutive cycles and A,B stable, Q remains stable.
    check_q_stable_when_inputs_stable: assert property (
        @(posedge CLK) disable iff (RST) $past(!RST) && $stable(A) && $stable(B) |-> (Q == $past(Q))
    );
endmodule

rtl:
module signal_combiner (
    A,
    B,
    C,
    D,
    X
);

    input A;
    input B;
    input C;
    input D;
    output X;

    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    assign X = (A & B & C & D) ? 0 : ((A | B | C | D) >= 2) ? 1 : (A | B | C | D);

endmodule

sva:
module signal_combiner_sva (
    input logic CLK,
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic X
);
    // X equals (A|B|C|D) masked off when all inputs are 1
    check_functional_equivalence: assert property (
        @(posedge CLK) X == ((A | B | C | D) & ~(A & B & C & D))
    );

    // All inputs 1 forces X to 0
    check_all_ones_forces_zero: assert property (
        @(posedge CLK) (A & B & C & D) |-> (X == 1'b0)
    );

    // All inputs 0 forces X to 0
    check_all_zeros_forces_zero: assert property (
        @(posedge CLK) !(A | B | C | D) |-> (X == 1'b0)
    );

    // When not all ones, X equals the OR of inputs
    check_not_all_ones_equals_or: assert property (
        @(posedge CLK) !(A & B & C & D) |-> (X == (A | B | C | D))
    );

    // If some but not all inputs are 1, X is 1
    check_partial_ones_give_one: assert property (
        @(posedge CLK) ((A | B | C | D) && !(A & B & C & D)) |-> (X == 1'b1)
    );

    // X high implies at least one input high and not all inputs high
    check_x_high_condition: assert property (
        @(posedge CLK) (X == 1'b1) |-> ((A | B | C | D) && !(A & B & C & D))
    );

    // X low occurs only when all zeros or all ones
    check_x_low_only_allzeros_or_allones: assert property (
        @(posedge CLK) (X == 1'b0) |-> ((!(A | B | C | D)) || (A & B & C & D))
    );

    // Exactly one-hot on A drives X high
    check_singleton_A: assert property (
        @(posedge CLK) (A && !B && !C && !D) |-> (X == 1'b1)
    );

    // Exactly one-hot on B drives X high
    check_singleton_B: assert property (
        @(posedge CLK) (!A && B && !C && !D) |-> (X == 1'b1)
    );

    // Exactly one-hot on C drives X high
    check_singleton_C: assert property (
        @(posedge CLK) (!A && !B && C && !D) |-> (X == 1'b1)
    );

    // Exactly one-hot on D drives X high
    check_singleton_D: assert property (
        @(posedge CLK) (!A && !B && !C && D) |-> (X == 1'b1)
    );
endmodule

module add_sub_4bit_sva (
    input  logic        CLK,     // external assertion clock (DUT has no clock/reset)
    input  logic [3:0]  num1,
    input  logic [3:0]  num2,
    input  logic        sub,
    input  logic [3:0]  result
);
    // Result matches selected operation each cycle.
    check_function_select: assert property (
        @(posedge CLK) result == (sub ? (num1 - num2) : (num1 + num2))
    );

    // When sub==0, result equals num1 + num2.
    check_add_path: assert property (
        @(posedge CLK) (sub == 1'b0) |-> (result == (num1 + num2))
    );

    // When sub==1, result equals num1 - num2.
    check_sub_path: assert property (
        @(posedge CLK) (sub == 1'b1) |-> (result == (num1 - num2))
    );

    // If inputs are stable, result is stable (pure combinational behavior).
    check_stability_when_inputs_stable: assert property (
        @(posedge CLK) ($stable(num1) && $stable(num2) && $stable(sub)) |-> $stable(result)
    );

    // Addition identity: adding zero returns num1.
    check_add_zero_identity: assert property (
        @(posedge CLK) (sub == 1'b0 && (num2 == 4'b0000)) |-> (result == num1)
    );

    // Subtraction identity: subtracting zero returns num1.
    check_sub_zero_identity: assert property (
        @(posedge CLK) (sub == 1'b1 && (num2 == 4'b0000)) |-> (result == num1)
    );

    // Subtracting equal operands yields zero.
    check_sub_equal_operands_zero: assert property (
        @(posedge CLK) (sub == 1'b1 && (num1 == num2)) |-> (result == 4'b0000)
    );

    // Rising sub selects subtraction, with previous cycle showing addition if inputs unchanged.
    check_sub_rise_selects_diff: assert property (
        @(posedge CLK) ($rose(sub) && $stable(num1) && $stable(num2))
            |-> (result == (num1 - num2)) && ($past(result) == ($past(num1) + $past(num2)))
    );

    // Falling sub selects addition, with previous cycle showing subtraction if inputs unchanged.
    check_sub_fall_selects_sum: assert property (
        @(posedge CLK) ($fell(sub) && $stable(num1) && $stable(num2))
            |-> (result == (num1 + num2)) && ($past(result) == ($past(num1) - $past(num2)))
    );
endmodule

rtl:
module four_bit_adder (
  input [3:0] A,
  input [3:0] B,
  input C,
  output [3:0] S
);

  // Declare internal wires
  wire [3:0] sum;
  wire [3:0] carry;

  // Generate sum and carry using basic gates
  assign sum = A ^ B;
  assign carry = A & B;

  // Output sum or carry based on control input C
  assign S = (C == 1'b0) ? sum : carry;

endmodule

sva:
module four_bit_adder_sva (
  input logic [3:0] A,
  input logic [3:0] B,
  input logic       C,
  input logic [3:0] S
);
  // Combinational DUT with no clock/reset; sample properties on C edges.

  // S must equal (C ? (A & B) : (A ^ B)) on any C edge.
  check_select_function: assert property (
    @(posedge C or negedge C) S == (C ? (A & B) : (A ^ B))
  );

  // On rising C, S equals bitwise AND of A and B.
  check_and_on_C_high: assert property (
    @(posedge C) S == (A & B)
  );

  // On falling C, S equals bitwise XOR of A and B.
  check_xor_on_C_low: assert property (
    @(negedge C) S == (A ^ B)
  );

  // When inputs are equal and C is low, XOR result (S) is zero.
  check_xor_zero_when_equal: assert property (
    @(negedge C) (A == B) |-> (S == 4'b0000)
  );

  // When either input is zero and C is high, AND result (S) is zero.
  check_and_zero_when_any_zero: assert property (
    @(posedge C) ((A == 4'b0000) || (B == 4'b0000)) |-> (S == 4'b0000)
  );

  // When both inputs are all ones and C is high, AND result (S) is all ones.
  check_and_all_ones: assert property (
    @(posedge C) (A == 4'b1111 && B == 4'b1111) |-> (S == 4'b1111)
  );
endmodule

rtl:
module bitwise_and (
    input [3:0] DATA_IN,
    input [3:0] MASK,
    output reg [3:0] DATA_OUT
);

    always @(*) begin
        DATA_OUT = DATA_IN & MASK;
    end

endmodule

sva:
module bitwise_and_sva (
    input logic CLK,
    input logic [3:0] DATA_IN,
    input logic [3:0] MASK,
    input logic [3:0] DATA_OUT
);
    // Output equals bitwise AND of DATA_IN and MASK.
    check_output_is_bitwise_and: assert property (
        @(posedge CLK) DATA_OUT == (DATA_IN & MASK)
    );

    // When MASK is all zeros, output must be zero.
    check_zero_mask_clears_output: assert property (
        @(posedge CLK) (MASK == 4'b0000) |-> (DATA_OUT == 4'b0000)
    );

    // When MASK is all ones, output equals input.
    check_allones_mask_passthrough: assert property (
        @(posedge CLK) (MASK == 4'b1111) |-> (DATA_OUT == DATA_IN)
    );

    // Bits not selected by MASK must be zero.
    check_unmasked_bits_are_zero: assert property (
        @(posedge CLK) (DATA_OUT & ~MASK) == 4'b0000
    );

    // On masked bits, output matches input.
    check_masked_bits_match_input: assert property (
        @(posedge CLK) ((DATA_OUT ^ DATA_IN) & MASK) == 4'b0000
    );

    // Output cannot introduce new 1s where input has 0s.
    check_no_new_ones_compared_to_input: assert property (
        @(posedge CLK) (DATA_OUT & ~DATA_IN) == 4'b0000
    );
endmodule

rtl:
module calculator (
    input [7:0] a,
    input [7:0] b,
    input add,
    input sub,
    output [7:0] result
);

    wire [7:0] add_result;
    wire [7:0] sub_result;

    assign add_result = a + b;
    assign sub_result = a - b;

    assign result = add ? add_result : sub ? sub_result : 8'b0;

endmodule

sva:
module calculator_sva (
    input logic CLK,
    input logic [7:0] a,
    input logic [7:0] b,
    input logic add,
    input logic sub,
    input logic [7:0] result
);
    // Result matches the combinational ternary equation.
    check_result_matches_equation: assert property (
        @(posedge CLK) result == (add ? (a + b) : (sub ? (a - b) : 8'h00))
    );

    // When add is asserted, result equals a + b (priority over sub).
    check_add_priority: assert property (
        @(posedge CLK) add |-> (result == (a + b))
    );

    // When only sub is asserted, result equals a - b.
    check_sub_when_no_add: assert property (
        @(posedge CLK) (!add && sub) |-> (result == (a - b))
    );

    // When neither add nor sub is asserted, result is zero.
    check_zero_when_no_ops: assert property (
        @(posedge CLK) (!add && !sub) |-> (result == 8'h00)
    );

    // When both add and sub are asserted, add takes precedence (result is a + b).
    check_both_ops_add_wins: assert property (
        @(posedge CLK) (add && sub) |-> (result == (a + b))
    );
endmodule

rtl:
module slower(
  input CLK,
  input SLOWCLK,
  input RESET,
  output reg EN_OUT
);

  reg [1:0] cur;
  reg [1:0] slowclk_last;

  always @(posedge CLK) begin
    if (RESET) begin
      EN_OUT <= 1'b0;
      cur <= 2'b0;
      slowclk_last <= 2'b0;
    end else begin
      if (SLOWCLK == slowclk_last) begin
        cur <= ~cur;
        EN_OUT <= 1'b1;
      end else begin
        EN_OUT <= 1'b0;
      end
      slowclk_last <= SLOWCLK;
    end
  end

endmodule

sva:
module slower_sva (
    input logic CLK,
    input logic SLOWCLK,
    input logic RESET,
    input logic EN_OUT
);
    // Clock: CLK posedge; Reset: RESET synchronous active-high.
    // Behavior: EN_OUT=1 iff SLOWCLK is unchanged from previous CLK; else EN_OUT=0.

    // During RESET, EN_OUT must be driven LOW.
    reset_drives_en_low: assert property (
        @(posedge CLK) RESET |-> (EN_OUT == 1'b0)
    );

    // If SLOWCLK is stable since last CLK, EN_OUT must be 1.
    en_high_on_slowclk_stable: assert property (
        @(posedge CLK) disable iff (RESET)
            ($stable(SLOWCLK) && !$past(RESET)) |-> (EN_OUT == 1'b1)
    );

    // If SLOWCLK changed since last CLK, EN_OUT must be 0.
    en_low_on_slowclk_change: assert property (
        @(posedge CLK) disable iff (RESET)
            ($changed(SLOWCLK) && !$past(RESET)) |-> (EN_OUT == 1'b0)
    );

    // EN_OUT high implies SLOWCLK was stable since last CLK.
    en_high_implies_slowclk_stable: assert property (
        @(posedge CLK) disable iff (RESET)
            (EN_OUT && !$past(RESET)) |-> $stable(SLOWCLK)
    );

    // EN_OUT low implies SLOWCLK changed since last CLK.
    en_low_implies_slowclk_changed: assert property (
        @(posedge CLK) disable iff (RESET)
            ((!EN_OUT) && !$past(RESET)) |-> $changed(SLOWCLK)
    );

    // After a SLOWCLK change, if next cycle SLOWCLK is stable then EN_OUT must be 1.
    en_recovers_high_after_change_and_stable: assert property (
        @(posedge CLK) disable iff (RESET)
            ($changed(SLOWCLK) && !$past(RESET)) ##1 ($stable(SLOWCLK) && !RESET) |-> (EN_OUT == 1'b1)
    );

    // On RESET deassertion, if SLOWCLK is 0 then EN_OUT must be 1 in that cycle.
    release_en_out_when_slowclk_zero: assert property (
        @(posedge CLK) $fell(RESET) && (SLOWCLK == 1'b0) |-> (EN_OUT == 1'b1)
    );

    // On RESET deassertion, if SLOWCLK is 1 then EN_OUT must be 0 in that cycle.
    release_en_out_when_slowclk_one: assert property (
        @(posedge CLK) $fell(RESET) && (SLOWCLK == 1'b1) |-> (EN_OUT == 1'b0)
    );

    // A falling edge on EN_OUT (1->0) occurs only when SLOWCLK changed.
    en_out_fall_only_on_slowclk_change: assert property (
        @(posedge CLK) disable iff (RESET)
            ($fell(EN_OUT) && !$past(RESET)) |-> $changed(SLOWCLK)
    );

    // A rising edge on EN_OUT (0->1) requires last cycle change and current stability of SLOWCLK.
    en_out_rise_requires_prev_change_and_now_stable: assert property (
        @(posedge CLK) disable iff (RESET)
            ($rose(EN_OUT) && !$past(RESET)) |-> (!$changed(SLOWCLK) && $past($changed(SLOWCLK)))
    );

endmodule

rtl:
module d_ff_reset (
    input D,
    input RESET_B,
    input VPWR,
    input VGND,
    input VPB,
    input VNB,
    input CLK_N,
    output reg Q
);

    wire D_valid;
    wire RESET_B_valid;
    wire VPWR_valid;
    wire VGND_valid;
    wire VPB_valid;
    wire VNB_valid;

    assign D_valid = (VPWR == 1'b1) && (VGND == 1'b0);
    assign RESET_B_valid = (VPWR == 1'b1) && (VGND == 1'b0);
    assign VPWR_valid = (VPWR == 1'b1) && (VGND == 1'b0);
    assign VGND_valid = (VPWR == 1'b1) && (VGND == 1'b0);
    assign VPB_valid = (VPB == 1'b1) && (VNB == 32'b11111111111111111111111111111111);
    assign VNB_valid = (VPB == 1'b1) && (VNB == 32'b11111111111111111111111111111111);

    always @(posedge CLK_N) begin
        if (RESET_B_valid && !RESET_B) begin
            Q <= 1'b0;
        end else if (D_valid) begin
            Q <= D;
        end
    end

endmodule

sva:
module d_ff_reset_sva (
    input logic D,
    input logic RESET_B,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB,
    input logic CLK_N,
    input logic Q
);
    ///// Reset behavior /////
    // Active-low reset with valid power drives Q to 0 on the next clock.
    reset_low_forces_q0: assert property (
        @(posedge CLK_N) ((VPWR == 1'b1) && (VGND == 1'b0) && (!RESET_B)) |=> (Q == 1'b0)
    );

    // Reset low without valid power has no effect on Q (no assignment occurs).
    reset_low_without_power_no_effect: assert property (
        @(posedge CLK_N) ((!((VPWR == 1'b1) && (VGND == 1'b0))) && (!RESET_B)) |=> (Q == $past(Q))
    );

    ///// Data capture behavior /////
    // With valid power and reset deasserted, Q captures D on the next clock.
    capture_d_when_powered: assert property (
        @(posedge CLK_N) disable iff (!RESET_B) ((VPWR == 1'b1) && (VGND == 1'b0) && (RESET_B == 1'b1)) |=> (Q == D)
    );

    // If D equals previous Q when capturing, Q remains unchanged.
    no_change_when_d_equals_prev_q: assert property (
        @(posedge CLK_N) disable iff (!RESET_B) ((VPWR == 1'b1) && (VGND == 1'b0) && (RESET_B == 1'b1) && (D == $past(Q))) |=> (Q == $past(Q))
    );

    // If D differs from previous Q when capturing, Q must change.
    q_changes_when_d_differs_from_prev_q: assert property (
        @(posedge CLK_N) disable iff (!RESET_B) ((VPWR == 1'b1) && (VGND == 1'b0) && (RESET_B == 1'b1) && (D != $past(Q))) |=> (Q != $past(Q))
    );

    ///// Hold behavior /////
    // With invalid power rails, Q holds its value across the clock.
    hold_when_power_invalid: assert property (
        @(posedge CLK_N) disable iff (!RESET_B) (!((VPWR == 1'b1) && (VGND == 1'b0))) |=> (Q == $past(Q))
    );

    ///// Change qualification /////
    // Any change on Q must be preceded by valid power rails.
    q_change_requires_valid_power: assert property (
        @(posedge CLK_N) disable iff (!RESET_B) $changed(Q) |-> $past((VPWR == 1'b1) && (VGND == 1'b0))
    );
endmodule

rtl:
module dffrl_s (din, clk, rst_l, q, se, si, so);

parameter SIZE = 1;

input	[SIZE-1:0]	din ;	// data in
input			clk ;	// clk or scan clk
input			rst_l ;	// reset

output	[SIZE-1:0]	q ;	// output

input			se ;	// scan-enable
input	[SIZE-1:0]	si ;	// scan-input
output	[SIZE-1:0]	so ;	// scan-output

reg 	[SIZE-1:0]	q ;

`ifdef NO_SCAN
always @ (posedge clk)
	q[SIZE-1:0]  <= rst_l ? din[SIZE-1:0] : {SIZE{1'b0}};
`else

// Reset dominates
always @ (posedge clk)

	q[SIZE-1:0]  <= rst_l ? ((se) ? si[SIZE-1:0]  : din[SIZE-1:0] ) : {SIZE{1'b0}};

assign so[SIZE-1:0] = q[SIZE-1:0] ;
`endif

endmodule

sva:
module dffrl_s_sva #(
    parameter SIZE = 1
) (
    input  logic                  clk,
    input  logic                  rst_l,
    input  logic                  se,
    input  logic [SIZE-1:0]       din,
    input  logic [SIZE-1:0]       si,
    input  logic [SIZE-1:0]       q,
    input  logic [SIZE-1:0]       so
);
    ///// Reset behavior /////
    // When reset is asserted (active-low), q is driven to 0 on the clock edge.
    check_reset_clears_q: assert property (
        @(posedge clk) !rst_l |-> (q == {SIZE{1'b0}})
    );

    ///// Functional capture behavior (common to both builds) /////
    // When not in reset and se was 0 last cycle, q captures din.
    check_capture_din_when_se0: assert property (
        @(posedge clk) disable iff (!rst_l) ($past(rst_l) && ($past(se) == 1'b0)) |-> (q == $past(din))
    );

    // When not in reset, se was 0, and din equaled q last cycle, q holds its value.
    check_hold_when_se0_and_din_matches_q: assert property (
        @(posedge clk) disable iff (!rst_l) ($past(rst_l) && ($past(se) == 1'b0) && ($past(din) == $past(q))) |-> (q == $past(q))
    );

`ifdef NO_SCAN
    ///// NO_SCAN build /////
    // When not in reset, q always captures din.
    check_noscan_captures_din: assert property (
        @(posedge clk) disable iff (!rst_l) $past(rst_l) |-> (q == $past(din))
    );
`else
    ///// Scan-enabled build /////
    // Combined next-state function: q captures si when se=1, else din, when not in reset.
    check_scan_combined_nextstate: assert property (
        @(posedge clk) disable iff (!rst_l) $past(rst_l) |-> (q == ($past(se) ? $past(si) : $past(din)))
    );

    // When not in reset and se was 1 last cycle, q captures si.
    check_capture_si_when_se1: assert property (
        @(posedge clk) disable iff (!rst_l) ($past(rst_l) && ($past(se) == 1'b1)) |-> (q == $past(si))
    );

    // so directly reflects q at all times (when property enabled).
    check_so_equals_q: assert property (
        @(posedge clk) disable iff (!rst_l) (so == q)
    );

    // When reset is asserted (active-low), so is driven to 0 via so=q.
    check_reset_clears_so: assert property (
        @(posedge clk) !rst_l |-> (so == {SIZE{1'b0}})
    );

    // When not in reset and se was 0, so reflects previous din (via so=q).
    check_so_follows_prev_din_when_se0: assert property (
        @(posedge clk) disable iff (!rst_l) ($past(rst_l) && ($past(se) == 1'b0)) |-> (so == $past(din))
    );

    // When not in reset and se was 1, so reflects previous si (via so=q).
    check_so_follows_prev_si_when_se1: assert property (
        @(posedge clk) disable iff (!rst_l) ($past(rst_l) && ($past(se) == 1'b1)) |-> (so == $past(si))
    );
`endif

endmodule

module up_down_counter_sva (
    input logic CLK,
    input logic UP_DOWN,
    input logic RESET,
    input logic [3:0] Q
);

    ///// Reset behavior /////
    // RESET drives Q to zero on the next clock.
    reset_clears_next: assert property (
        @(posedge CLK) RESET |=> (Q == 4'b0000)
    );

    // While RESET is held across cycles, Q remains zero.
    reset_holds_zero: assert property (
        @(posedge CLK) $past(RESET) && RESET |-> (Q == 4'b0000)
    );

    // On RESET deassertion edge, Q is zero in that cycle.
    q_zero_on_reset_fall: assert property (
        @(posedge CLK) $fell(RESET) |-> (Q == 4'b0000)
    );

    ///// Counting behavior /////
    // When UP_DOWN=1 and not in reset, Q increments by 1 on the next clock.
    count_up_step: assert property (
        @(posedge CLK) disable iff (RESET) UP_DOWN |=> (Q == $past(Q) + 4'd1)
    );

    // When UP_DOWN=0 and not in reset, Q decrements by 1 on the next clock.
    count_down_step: assert property (
        @(posedge CLK) disable iff (RESET) !UP_DOWN |=> (Q == $past(Q) - 4'd1)
    );

    // Without reset, Q changes every cycle (always +/-1).
    q_changes_each_cycle: assert property (
        @(posedge CLK) disable iff (RESET) 1'b1 |=> (Q != $past(Q))
    );

    // When counting up from 0xF, Q wraps to 0 on the next clock.
    count_up_wrap_to_zero: assert property (
        @(posedge CLK) disable iff (RESET) (UP_DOWN && (Q == 4'hF)) |=> (Q == 4'h0)
    );

    // When counting down from 0, Q wraps to 0xF on the next clock.
    count_down_wrap_to_f: assert property (
        @(posedge CLK) disable iff (RESET) (!UP_DOWN && (Q == 4'h0)) |=> (Q == 4'hF)
    );

    // Two consecutive UP cycles (no reset) advance Q by +2 modulo 16.
    two_cycles_up: assert property (
        @(posedge CLK) disable iff (RESET) (UP_DOWN ##1 UP_DOWN) |=> (Q == $past(Q,2) + 4'd2)
    );

    // Two consecutive DOWN cycles (no reset) decrement Q by -2 modulo 16.
    two_cycles_down: assert property (
        @(posedge CLK) disable iff (RESET) ((!UP_DOWN) ##1 (!UP_DOWN)) |=> (Q == $past(Q,2) - 4'd2)
    );

endmodule

module counter_sva (
    input logic clk,
    input logic rst,          // active-high synchronous reset
    input logic [7:0] count
);
    parameter int unsigned MAX_COUNT = 255;

    ///// Reset behavior /////
    // After reset deassertion, count is 0 on that cycle.
    reset_deassert_zero: assert property (
        @(posedge clk) disable iff (rst) ($past(rst,1) == 1'b1) |-> (count == 8'd0)
    );

    ///// Next-state function /////
    // When not at MAX_COUNT, count increments by 1 next cycle.
    increment_when_below_max: assert property (
        @(posedge clk) disable iff (rst) (count != MAX_COUNT) |=> (count == $past(count) + 8'd1)
    );
    // When at MAX_COUNT, count wraps to 0 next cycle.
    wrap_on_max: assert property (
        @(posedge clk) disable iff (rst) (count == MAX_COUNT) |=> (count == 8'd0)
    );

    ///// Invariants /////
    // While not in reset, count never exceeds MAX_COUNT.
    count_bounded_by_max: assert property (
        @(posedge clk) disable iff (rst) (count <= MAX_COUNT)
    );

    ///// Transition consistency /////
    // If current count != 0 and previous cycle wasn't in reset, previous count was current-1.
    prev_is_one_less_when_curr_nonzero: assert property (
        @(posedge clk) disable iff (rst) (!$past(rst) && (count != 8'd0)) |-> ($past(count) == (count - 8'd1))
    );
    // If current count is 0 and previous cycle wasn't in reset, previous count was MAX_COUNT.
    zero_only_from_wrap: assert property (
        @(posedge clk) disable iff (rst) (!$past(rst) && (count == 8'd0)) |-> ($past(count) == MAX_COUNT)
    );
    // MAX_COUNT cannot persist for two consecutive cycles when not in reset.
    no_two_cycles_at_max: assert property (
        @(posedge clk) disable iff (rst) (count == MAX_COUNT) |=> (count != MAX_COUNT)
    );
    // If previous cycle wasn't reset and wasn't MAX_COUNT, current count cannot be 0.
    no_spurious_zero_without_prev_max: assert property (
        @(posedge clk) disable iff (rst) (!$past(rst) && ($past(count) != MAX_COUNT)) |-> (count != 8'd0)
    );

    ///// Useful strengthened corner checks (parameter-dependent) /////
    // From MAX_COUNT-1, go to MAX_COUNT next cycle (if MAX_COUNT > 0).
    generate
        if (MAX_COUNT > 0) begin : gen_penultimate_to_max
            penultimate_to_max: assert property (
                @(posedge clk) disable iff (rst) (count == (MAX_COUNT - 1)) |=> (count == MAX_COUNT)
            );
        end
    endgenerate
    // From 0 (not immediately after reset), go to 1 next cycle when running (if MAX_COUNT > 0).
    generate
        if (MAX_COUNT > 0) begin : gen_zero_to_one
            zero_to_one_next: assert property (
                @(posedge clk) disable iff (rst) ((count == 8'd0) && !$past(rst)) |=> (count == 8'd1)
            );
        end
    endgenerate
endmodule

