sva:
module mux_2_1_sva (
    input logic A,
    input logic B,
    input logic S,
    input logic Y
);
    // Combinational 2:1 mux; no clock/reset in RTL; sample on any input edge.

    // Functional equation: Y must equal (S ? B : A) at all times.
    check_mux_function: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge S or negedge S)
            Y == (S ? B : A)
    );

    // When S is 0, Y equals A.
    check_select0_path: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge S or negedge S)
            (S == 1'b0) |-> (Y == A)
    );

    // When S is 1, Y equals B.
    check_select1_path: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge S or negedge S)
            (S == 1'b1) |-> (Y == B)
    );
endmodule

rtl:
module configurable_counter (
  input clk,
  input reset,
  input [7:0] max_count,
  output reg [7:0] count
);

  always @(posedge clk, posedge reset) begin
    if (reset) begin
      count <= 8'b0;
    end else if (count == max_count) begin
      count <= 8'b0;
    end else begin
      count <= count + 1;
    end
  end

endmodule

sva:
module configurable_counter_sva (
    input logic clk,
    input logic reset,           // active-high async reset
    input logic [7:0] max_count,
    input logic [7:0] count
);

    // Reset forces count to zero whenever sampled high on clk.
    check_reset_forces_zero: assert property (
        @(posedge clk) reset |-> (count == 8'd0)
    );

    // Next-state function: on the next cycle, either reset is asserted or count updates per RTL (uses current max_count and previous count).
    check_next_state_matches_rtl: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |-> ##1 (reset || (count == (($past(count) == max_count) ? 8'd0 : ($past(count) + 8'd1))))
    );

    // If previous count equals current max_count, next count is zero.
    check_wrap_when_prev_eq_current_max: assert property (
        @(posedge clk) disable iff (reset)
        ($past(count) == max_count) |-> (count == 8'd0)
    );

    // If previous count does not equal current max_count, next count increments by one (mod 256).
    check_increment_when_prev_not_equal: assert property (
        @(posedge clk) disable iff (reset)
        ($past(count) != max_count) |-> (count == ($past(count) + 8'd1))
    );

    // On every non-reset cycle, next count is either zero or previous+1.
    check_zero_or_plus1_transition: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |-> ##1 (reset || (count == 8'd0) || (count == ($past(count) + 8'd1)))
    );

    // If not in reset and next count is zero, then previous count was max_count or 8'hFF (wrap via +1).
    check_zero_implies_prev_eq_max_or_prev_ff: assert property (
        @(posedge clk) disable iff (reset)
        (count == 8'd0) |-> (($past(count) == max_count) || ($past(count) == 8'hFF))
    );

    // On reset deassertion, count becomes 0 (if max_count==0) or 1 (otherwise) at that clk edge.
    check_reset_deassertion_result: assert property (
        @(posedge clk) $fell(reset) |-> (count == 8'd0 || count == 8'd1)
    );

endmodule

rtl:
module binary_counter (
    input clk,
    input [7:0] max_count,
    output reg [7:0] count
);

    always @(posedge clk) begin
        if (count == max_count) begin
            count <= 0;
        end else begin
            count <= count + 1;
        end
    end

endmodule

sva:
module binary_counter_sva (
    input logic clk,
    input logic [7:0] max_count,
    input logic [7:0] count
);
    // Clock: clk (posedge). No reset in RTL; sequential: if (count==max_count) -> 0 else +1 (mod 256).

    // If previous count equaled previous max_count, next count is 0.
    update_to_zero_on_match: assert property (
        @(posedge clk) ($past(count) == $past(max_count)) |-> (count == 8'h00)
    );

    // If previous count did not equal previous max_count, next count increments by 1 (mod 256).
    update_increment_on_no_match: assert property (
        @(posedge clk) ($past(count) != $past(max_count)) |-> (count == ($past(count) + 8'd1)[7:0])
    );

    // If current count is 0, it must be due to a previous match or an overflow from 0xFF.
    zero_implies_from_match_or_overflow: assert property (
        @(posedge clk) (count == 8'h00) |-> (($past(count) == $past(max_count)) || ($past(count) == 8'hFF))
    );

    // If previous was 0xFF and did not match max_count, overflow to 0 occurs.
    overflow_to_zero_when_prev_ff_no_match: assert property (
        @(posedge clk) (($past(count) == 8'hFF) && ($past(count) != $past(max_count))) |-> (count == 8'h00)
    );

    // If previous was not 0xFF and did not match max_count, next value cannot be 0.
    no_spurious_zero_without_ff_no_match: assert property (
        @(posedge clk) (($past(count) != $past(max_count)) && ($past(count) != 8'hFF)) |-> (count != 8'h00)
    );

    // Over two consecutive non-match cycles, count increases by 2 (mod 256).
    two_cycle_increment_without_match: assert property (
        @(posedge clk) (($past(count,2) != $past(max_count,2)) && ($past(count,1) != $past(max_count,1)))
        |-> (count == ($past(count,2) + 8'd2)[7:0])
    );

    // If previous matched max_count and current max_count is 0, count remains 0 (idempotent reset to 0).
    zero_sticky_when_max_zero: assert property (
        @(posedge clk) (($past(count) == $past(max_count)) && (max_count == 8'h00)) |-> (count == 8'h00)
    );

    // If previous count was 0 and previous max_count was nonzero, next count becomes 1.
    from_zero_when_max_nonzero: assert property (
        @(posedge clk) (($past(count) == 8'h00) && ($past(max_count) != 8'h00)) |-> (count == 8'h01)
    );

endmodule

rtl:
module decoder_barrelshifter (
    input A,
    input B,
    input C,
    input [3:0] data_in,
    input dir,
    output [3:0] data_out
);

    // 3-to-8 decoder
    wire [7:0] decoder_out;
    assign decoder_out = ~(A&B&C) << 3 | ~(A&B&~C) << 2 | ~(A&~B&C) << 1 | ~(A&~B&~C) << 0 | ~(~A&B&C) << 4 | ~(~A&B&~C) << 5 | ~(~A&~B&C) << 6 | ~(~A&~B&~C) << 7;

    // Barrel shifter
    wire [3:0] shifted_data;
    assign shifted_data = dir ? data_in >> 1 : data_in << 1;
    assign data_out = (decoder_out & 8'hFF) == 0 ? data_in : shifted_data;

endmodule

sva:
module decoder_barrelshifter_sva (
    input  logic       A,
    input  logic       B,
    input  logic       C,
    input  logic [3:0] data_in,
    input  logic       dir,
    input  logic [3:0] data_out
);

    // Local recomputation of DUT combinational function
    logic        passthrough;         // A & ~B & ~C selects pass-through
    logic [3:0]  left_shifted;        // data_in << 1
    logic [3:0]  right_shifted;       // data_in >> 1
    logic [3:0]  expected_shifted;    // dir ? right : left

    assign passthrough      = (A & ~B & ~C);
    assign left_shifted     = data_in << 1;
    assign right_shifted    = data_in >> 1;
    assign expected_shifted = dir ? right_shifted : left_shifted;

    // data_out matches exact RTL expression (pass-through vs shifted)
    check_function_equivalence: assert property (
        @(posedge A) data_out == (passthrough ? data_in : expected_shifted)
    );

    // Pass-through case: when A&~B&~C, output equals input
    check_passthrough: assert property (
        @(posedge A) passthrough |-> (data_out == data_in)
    );

    // Shift-left case: when not pass-through and dir==0, output equals data_in<<1
    check_shift_left_vector: assert property (
        @(posedge A) (!passthrough && (dir == 1'b0)) |-> (data_out == left_shifted)
    );

    // Shift-right case: when not pass-through and dir==1, output equals data_in>>1
    check_shift_right_vector: assert property (
        @(posedge A) (!passthrough && (dir == 1'b1)) |-> (data_out == right_shifted)
    );

    // Left shift zeros the LSB
    check_shift_left_lsb_zero: assert property (
        @(posedge A) (!passthrough && (dir == 1'b0)) |-> (data_out[0] == 1'b0)
    );

    // Left shift bit mapping: out[1] <= in[0]
    check_shift_left_bit1_map: assert property (
        @(posedge A) (!passthrough && (dir == 1'b0)) |-> (data_out[1] == data_in[0])
    );

    // Left shift bit mapping: out[2] <= in[1]
    check_shift_left_bit2_map: assert property (
        @(posedge A) (!passthrough && (dir == 1'b0)) |-> (data_out[2] == data_in[1])
    );

    // Left shift bit mapping: out[3] <= in[2]
    check_shift_left_bit3_map: assert property (
        @(posedge A) (!passthrough && (dir == 1'b0)) |-> (data_out[3] == data_in[2])
    );

    // Right shift zeros the MSB
    check_shift_right_msb_zero: assert property (
        @(posedge A) (!passthrough && (dir == 1'b1)) |-> (data_out[3] == 1'b0)
    );

    // Right shift bit mapping: out[2] <= in[3]
    check_shift_right_bit2_map: assert property (
        @(posedge A) (!passthrough && (dir == 1'b1)) |-> (data_out[2] == data_in[3])
    );

    // Right shift bit mapping: out[1] <= in[2]
    check_shift_right_bit1_map: assert property (
        @(posedge A) (!passthrough && (dir == 1'b1)) |-> (data_out[1] == data_in[2])
    );

    // Right shift bit mapping: out[0] <= in[1]
    check_shift_right_bit0_map: assert property (
        @(posedge A) (!passthrough && (dir == 1'b1)) |-> (data_out[0] == data_in[1])
    );

endmodule

module bitwise_op_sva (
    input logic CLK,
    input logic [7:0] a,
    input logic [7:0] b,
    input logic [2:0] op,
    input logic [7:0] out
);
    // For op=000, out must be a & b.
    check_map_and: assert property (
        @(posedge CLK) (op == 3'b000) |-> (out == (a & b))
    );

    // For op=001, out must be a | b.
    check_map_or: assert property (
        @(posedge CLK) (op == 3'b001) |-> (out == (a | b))
    );

    // For op=010, out must be a ^ b.
    check_map_xor: assert property (
        @(posedge CLK) (op == 3'b010) |-> (out == (a ^ b))
    );

    // For op=011, out must be two's complement of a (~a + 1).
    check_map_neg_a: assert property (
        @(posedge CLK) (op == 3'b011) |-> (out == (~a + 8'd1))
    );

    // For op=100, out must be two's complement of b (~b + 1).
    check_map_neg_b: assert property (
        @(posedge CLK) (op == 3'b100) |-> (out == (~b + 8'd1))
    );

    // For op=101, out must be ~(a & b) (bitwise NAND).
    check_map_nand: assert property (
        @(posedge CLK) (op == 3'b101) |-> (out == ~(a & b))
    );

    // For op=110, out must be ~(a | b) (bitwise NOR).
    check_map_nor: assert property (
        @(posedge CLK) (op == 3'b110) |-> (out == ~(a | b))
    );

    // For op=111, out must be ~(a ^ b) (bitwise XNOR).
    check_map_xnor: assert property (
        @(posedge CLK) (op == 3'b111) |-> (out == ~(a ^ b))
    );

    // If a, b, and op are stable, out must be stable (combinational behavior).
    check_stable_out_when_inputs_stable: assert property (
        @(posedge CLK) ($stable(a) && $stable(b) && $stable(op)) |-> $stable(out)
    );

    // For op=011, a + out wraps to 0 (two's complement identity).
    check_neg_a_sum_zero: assert property (
        @(posedge CLK) (op == 3'b011) |-> ((a + out) == 8'h00)
    );

    // For op=100, b + out wraps to 0 (two's complement identity).
    check_neg_b_sum_zero: assert property (
        @(posedge CLK) (op == 3'b100) |-> ((b + out) == 8'h00)
    );
endmodule

