module arithmetic_operations(
    input [15:0] A_in,
    input [15:0] B_in,
    output reg [15:0] sum_out,
    output reg [15:0] diff_out,
    output reg [15:0] abs_diff_out,
    output reg [15:0] and_out,
    output reg [15:0] or_out,
    output reg [15:0] xor_out
);

    always @(*) begin
        // Sum
        sum_out = A_in + B_in;

        // Difference
        diff_out = A_in - B_in;

        // Absolute difference
        if (A_in > B_in) begin
            abs_diff_out = A_in - B_in;
        end else begin
            abs_diff_out = B_in - A_in;
        end

        // Bitwise AND
        and_out = A_in & B_in;

        // Bitwise OR
        or_out = A_in | B_in;

        // Bitwise XOR
        xor_out = A_in ^ B_in;
    end

endmodule

sva:
module arithmetic_operations_sva (
    // DUT ports as inputs
    input logic [15:0] A_in,
    input logic [15:0] B_in,
    input logic [15:0] sum_out,
    input logic [15:0] diff_out,
    input logic [15:0] abs_diff_out,
    input logic [15:0] and_out,
    input logic [15:0] or_out,
    input logic [15:0] xor_out,
    // External sampling clock for SVA (RTL is combinational; no reset present)
    input logic CLK
);
    // Combinational RTL (no clock/reset). Assertions sample on CLK.
    // Behaviors: sum=A+B (16-bit wrap), diff=A-B (16-bit wrap), abs_diff per unsigned compare, bitwise AND/OR/XOR.

    // Sum equals lower 16 bits of A_in + B_in.
    check_sum_functional: assert property (
        @(posedge CLK) sum_out == (A_in + B_in)[15:0]
    );

    // Difference equals lower 16 bits of A_in - B_in.
    check_diff_functional: assert property (
        @(posedge CLK) diff_out == (A_in - B_in)[15:0]
    );

    // Absolute difference when A_in > B_in equals A_in - B_in.
    check_absdiff_when_gt: assert property (
        @(posedge CLK) (A_in > B_in) |-> (abs_diff_out == (A_in - B_in)[15:0])
    );

    // Absolute difference when A_in <= B_in equals B_in - A_in.
    check_absdiff_when_le: assert property (
        @(posedge CLK) (A_in <= B_in) |-> (abs_diff_out == (B_in - A_in)[15:0])
    );

    // Bitwise AND correctness.
    check_and_functional: assert property (
        @(posedge CLK) and_out == (A_in & B_in)
    );

    // Bitwise OR correctness.
    check_or_functional: assert property (
        @(posedge CLK) or_out == (A_in | B_in)
    );

    // Bitwise XOR correctness.
    check_xor_functional: assert property (
        @(posedge CLK) xor_out == (A_in ^ B_in)
    );

    // XOR equals (OR & ~AND).
    check_xor_or_and_identity: assert property (
        @(posedge CLK) xor_out == (or_out & ~and_out)
    );

    // OR equals XOR | AND.
    check_or_decomposition: assert property (
        @(posedge CLK) or_out == (xor_out | and_out)
    );

    // AND is a subset of OR (no bit can be 1 in AND while 0 in OR).
    check_and_subset_or: assert property (
        @(posedge CLK) (and_out & ~or_out) == 16'h0000
    );

    // When inputs are equal, diff/xor/abs_diff are zero.
    check_equal_inputs_zeroes: assert property (
        @(posedge CLK) (A_in == B_in) |-> (diff_out == 16'h0000) && (abs_diff_out == 16'h0000) && (xor_out == 16'h0000)
    );

endmodule

rtl:
module five_to_one (
    input A,
    input B,
    input C,
    input D,
    input E,
    output reg Y
);

always @(*) begin
    if (A) begin
        Y = 1;
    end else if (B) begin
        Y = 1;
    end else if (C) begin
        Y = 1;
    end else if (D && !E) begin
        Y = 1;
    end else if (!D && E) begin
        Y = 1;
    end else begin
        Y = 0;
    end
end

endmodule

sva:
module five_to_one_sva (
    input logic CLK,
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic E,
    input logic Y
);
    // Analysis: no clock/reset in RTL; purely combinational; Y=1 if A|B|C or (D^E when A=B=C=0).

    // Y equals the combinational function encoded by the if/else chain.
    check_y_function_equivalence: assert property (
        @(posedge CLK) Y == (A || B || C || ((!A && !B && !C) && (D ^ E)))
    );

    // If any of A,B,C is 1, Y must be 1.
    check_y_high_when_any_abc: assert property (
        @(posedge CLK) (A || B || C) |-> (Y == 1'b1)
    );

    // If A,B,C are 0 and D^E is 1, Y must be 1.
    check_y_high_when_dxorE_no_abc: assert property (
        @(posedge CLK) (!A && !B && !C && (D ^ E)) |-> (Y == 1'b1)
    );

    // If A,B,C are 0 and D^E is 0, Y must be 0.
    check_y_low_when_no_conditions: assert property (
        @(posedge CLK) (!A && !B && !C && !(D ^ E)) |-> (Y == 1'b0)
    );

    // Y=1 only when one of the specified conditions holds.
    check_y_high_only_when_condition_true: assert property (
        @(posedge CLK) (Y == 1'b1) |-> (A || B || C || ((!A && !B && !C) && (D ^ E)))
    );

    // Y=0 only when no condition in the chain is met.
    check_y_low_only_when_no_condition_true: assert property (
        @(posedge CLK) (Y == 1'b0) |-> (!A && !B && !C && !(D ^ E))
    );

    // If inputs are stable across a cycle, Y must remain stable (combinational behavior).
    check_y_stable_when_inputs_stable: assert property (
        @(posedge CLK) $stable({A,B,C,D,E}) |-> $stable(Y)
    );
endmodule

rtl:
module multiplier (
    input [7:0] a,
    input [7:0] b,
    output reg [15:0] out
);
    always @* begin
        out = a * b;
    end
endmodule

module parity (
    input [7:0] in,
    output reg parity_out
);
    always @* begin
        parity_out = ^in;
    end
endmodule

module additional (
    input [15:0] mult_out,
    input parity_out,
    output reg [15:0] out
);
    always @* begin
        if (parity_out == 1'b0) begin
            out = mult_out + {8'b0, 1'b1};
        end else begin
            out = mult_out;
        end
    end
endmodule

module top_module (
    input [7:0] a,
    input [7:0] b,
    input [7:0] in,
    input select,
    output [15:0] out
);
    wire [15:0] mult_out;
    wire parity_out;
    wire [15:0] add_out;

    multiplier mult_inst (
        .a(a),
        .b(b),
        .out(mult_out)
    );

    parity parity_inst (
        .in(in),
        .parity_out(parity_out)
    );

    additional add_inst (
        .mult_out(mult_out),
        .parity_out(parity_out),
        .out(add_out)
    );

    assign out = select ? add_out : mult_out;
endmodule

sva:
module top_module_sva (
    input logic CLK,
    input logic [7:0] a,
    input logic [7:0] b,
    input logic [7:0] in,
    input logic select,
    input logic [15:0] out
);
    // When select=0, out equals the multiplier result.
    check_select0_path: assert property (
        @(posedge CLK) disable iff (1'b0) (select == 1'b0) |-> (out == (a * b))
    );

    // When select=1 and parity is 1, out equals the multiplier result.
    check_select1_parity1_path: assert property (
        @(posedge CLK) disable iff (1'b0) (select && (^in == 1'b1)) |-> (out == (a * b))
    );

    // When select=1 and parity is 0, out equals multiplier result plus {8'b0,1'b1}.
    check_select1_parity0_path: assert property (
        @(posedge CLK) disable iff (1'b0) (select && (^in == 1'b0)) |-> (out == ((a * b) + {8'b0, 1'b1}))
    );

    // For select=1, out - product equals 0 if parity=1 else 1 if parity=0.
    check_select1_diff_matches_parity: assert property (
        @(posedge CLK) disable iff (1'b0) select |-> ((out - (a * b)) == ( (^in) ? 16'd0 : 16'd1 ))
    );

    // If all inputs are stable, output must be stable (purely combinational behavior).
    check_stability_when_inputs_stable: assert property (
        @(posedge CLK) disable iff (1'b0) $stable(a) && $stable(b) && $stable(in) && $stable(select) |-> $stable(out)
    );

    // With select=0 and any zero multiplicand, out is zero.
    check_zero_mult_select0: assert property (
        @(posedge CLK) disable iff (1'b0) (select == 1'b0) && ((a == 8'd0) || (b == 8'd0)) |-> (out == 16'd0)
    );

    // With select=1, parity=1, and any zero multiplicand, out is zero.
    check_zero_mult_select1_parity1: assert property (
        @(posedge CLK) disable iff (1'b0) (select && (^in == 1'b1) && ((a == 8'd0) || (b == 8'd0))) |-> (out == 16'd0)
    );

    // With select=1, parity=0, and any zero multiplicand, out is {8'b0,1'b1}.
    check_zero_mult_select1_parity0: assert property (
        @(posedge CLK) disable iff (1'b0) (select && (^in == 1'b0) && ((a == 8'd0) || (b == 8'd0))) |-> (out == {7'd0, 9'h001}[15:0])
    );

    // With select=1 and parity=0, LSB toggles relative to product.
    check_lsb_toggle_parity0: assert property (
        @(posedge CLK) disable iff (1'b0) (select && (^in == 1'b0)) |-> (out[0] == ~((a * b)[0]))
    );

    // With select=1 and parity=1, LSB matches product LSB.
    check_lsb_equal_parity1: assert property (
        @(posedge CLK) disable iff (1'b0) (select && (^in == 1'b1)) |-> (out[0] == ((a * b)[0]))
    );
endmodule

rtl:
module logical_gate (
    Y ,
    A1,
    A2,
    B1,
    B2
);

    output Y ;
    input  A1;
    input  A2;
    input  B1;
    input  B2;

    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    assign Y = (A1 & A2) | (B1 & B2);

endmodule

sva:
module logical_gate_sva (
    input logic Y,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic B2
);
    // No clock/reset in RTL; pure combinational. Sample on any input/output edge.

    // Y equals the intended OR-of-ANDs function.
    check_function_equivalence: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge B1 or negedge B1 or posedge B2 or negedge B2 or posedge Y or negedge Y)
            (Y == ((A1 & A2) | (B1 & B2)))
    );

    // If Y is HIGH then at least one AND term is HIGH.
    check_y_high_implies_term_true: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge B1 or negedge B1 or posedge B2 or negedge B2 or posedge Y or negedge Y)
            (Y) |-> ((A1 & A2) | (B1 & B2))
    );

    // If Y is LOW then neither AND term is HIGH.
    check_y_low_implies_terms_false: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge B1 or negedge B1 or posedge B2 or negedge B2 or posedge Y or negedge Y)
            (!Y) |-> !((A1 & A2) | (B1 & B2))
    );

    // A-term HIGH forces Y HIGH.
    check_a_term_forces_y_high: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge B1 or negedge B1 or posedge B2 or negedge B2 or posedge Y or negedge Y)
            ((A1 & A2)) |-> (Y)
    );

    // B-term HIGH forces Y HIGH.
    check_b_term_forces_y_high: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge B1 or negedge B1 or posedge B2 or negedge B2 or posedge Y or negedge Y)
            ((B1 & B2)) |-> (Y)
    );

    // If both first inputs are LOW, Y must be LOW.
    check_first_inputs_both_low_force_y_low: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge B1 or negedge B1 or posedge B2 or negedge B2 or posedge Y or negedge Y)
            ((!A1) && (!B1)) |-> (!Y)
    );

    // If both second inputs are LOW, Y must be LOW.
    check_second_inputs_both_low_force_y_low: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge B1 or negedge B1 or posedge B2 or negedge B2 or posedge Y or negedge Y)
            ((!A2) && (!B2)) |-> (!Y)
    );

    // On a rising edge of Y, at least one AND term is HIGH.
    check_y_rise_requires_term_true: assert property (
        @(posedge Y) ((A1 & A2) | (B1 & B2))
    );

    // On a falling edge of Y, both AND terms are not HIGH.
    check_y_fall_requires_terms_false: assert property (
        @(negedge Y) !((A1 & A2) | (B1 & B2))
    );

endmodule

rtl:
module nor_gate(
    input a,
    input b,
    output out
    );

    assign out = ~(a | b);

endmodule

module mux_with_nor_gate(
    input a,
    input b,
    input c,
    input control,
    output w,
    output x,
    output y,
    output z
    );

    wire nor_out;
    nor_gate nor_inst(a, b, nor_out);

    assign w = (control == 1'b0) ? a : ((control == 1'b1) ? b : c);
    assign x = w;
    assign y = w;
    assign z = w;

endmodule

sva:
module mux_with_nor_gate_sva (
    input logic a,
    input logic b,
    input logic c,
    input logic control,
    input logic w,
    input logic x,
    input logic y,
    input logic z
);
    // No clock/reset in RTL; pure combinational. Sample assertions on posedge of 'a'.

    // Replicated outputs must equal w.
    check_outputs_equal_w: assert property (
        @(posedge a) (x == w) && (y == w) && (z == w)
    );

    // When control is exactly 0, w must equal a.
    check_w_select_a_when_control_0: assert property (
        @(posedge a) (control === 1'b0) |-> (w == a)
    );

    // When control is exactly 1, w must equal b.
    check_w_select_b_when_control_1: assert property (
        @(posedge a) (control === 1'b1) |-> (w == b)
    );

    // When control is neither 0 nor 1, w must equal c.
    check_w_select_c_when_control_unknown: assert property (
        @(posedge a) ((control !== 1'b0) && (control !== 1'b1)) |-> (w == c)
    );

    // When control is exactly 0, all outputs must equal a.
    check_all_select_a_when_control_0: assert property (
        @(posedge a) (control === 1'b0) |-> ((x == a) && (y == a) && (z == a))
    );

    // When control is exactly 1, all outputs must equal b.
    check_all_select_b_when_control_1: assert property (
        @(posedge a) (control === 1'b1) |-> ((x == b) && (y == b) && (z == b))
    );

    // When control is neither 0 nor 1, all outputs must equal c.
    check_all_select_c_when_control_unknown: assert property (
        @(posedge a) ((control !== 1'b0) && (control !== 1'b1)) |-> ((x == c) && (y == c) && (z == c))
    );

endmodule

rtl:
module and_gate (
    input a,
    input b,
    output out
);

    wire na, nb, nand_out;

    not (na, a);
    not (nb, b);
    nand (nand_out, na, nb);
    not (out, nand_out);

endmodule

sva:
module and_gate_sva (
    input logic CLK,
    input logic a,
    input logic b,
    input logic out
);
    // Functional NOR relation: out equals ~(a | b).
    check_out_is_nor_ab: assert property (
        @(posedge CLK) out == ~(a | b)
    );

    // Out HIGH only when both inputs are LOW.
    check_out_high_only_when_both_low: assert property (
        @(posedge CLK) out |-> (!a && !b)
    );

    // If any input is HIGH, out must be LOW.
    check_any_input_high_forces_out_low: assert property (
        @(posedge CLK) (a || b) |-> (!out)
    );

    // If both inputs are LOW, out must be HIGH.
    check_both_low_implies_out_high: assert property (
        @(posedge CLK) (!a && !b) |-> out
    );
endmodule

rtl:
module arith(a, b, sum, diff, prod);
   input [7:0] a, b;
   output [7:0] sum, diff, prod;

   assign sum = a + b;
   assign diff = a - b;
   assign prod = a * b;

endmodule

sva:
module arith_sva (
    input logic clk,
    input logic [7:0] a,
    input logic [7:0] b,
    input logic [7:0] sum,
    input logic [7:0] diff,
    input logic [7:0] prod
);
    // sum matches 8-bit addition of a and b
    check_sum_equals_addition: assert property (
        @(posedge clk) sum == (a + b)
    );

    // diff matches 8-bit subtraction a - b
    check_diff_equals_subtraction: assert property (
        @(posedge clk) diff == (a - b)
    );

    // prod matches low 8 bits of a * b
    check_prod_equals_mult_low8: assert property (
        @(posedge clk) prod == (a * b)[7:0]
    );

    // sum - b recovers a (mod 256)
    check_sum_minus_b_recovers_a: assert property (
        @(posedge clk) (sum - b) == a
    );

    // diff + b recovers a (mod 256)
    check_diff_plus_b_recovers_a: assert property (
        @(posedge clk) (diff + b) == a
    );

    // If a is zero, product is zero
    check_prod_zero_when_a_zero: assert property (
        @(posedge clk) (a == 8'h00) |-> (prod == 8'h00)
    );

    // If b is zero, product is zero
    check_prod_zero_when_b_zero: assert property (
        @(posedge clk) (b == 8'h00) |-> (prod == 8'h00)
    );

    // (sum - diff) equals 2*b (mod 256)
    check_sum_minus_diff_is_2b: assert property (
        @(posedge clk) (sum - diff) == (b << 1)
    );

    // (sum + diff) equals 2*a (mod 256)
    check_sum_plus_diff_is_2a: assert property (
        @(posedge clk) (sum + diff) == (a << 1)
    );

    // Equal inputs imply sum is 2*a and diff is 0
    check_equal_inputs_implications: assert property (
        @(posedge clk) (a == b) |-> ((sum == (a << 1)) && (diff == 8'h00))
    );
endmodule

module ShiftRegister_sva (
    input  logic D,
    input  logic LOAD,
    input  logic CLK,
    input  logic [5:0] Q
);

    // If LOAD was 1 last cycle, Q loads all bits from D.
    check_load_writes_all_bits: assert property (
        @(posedge CLK) $past(1'b1,1,1'b0) && $past(LOAD,1,1'b0) |-> (Q == {6{$past(D,1,1'b0)}})
    );

    // If LOAD was 0 last cycle, Q shifts left with D entering bit 0.
    check_shift_nextstate_vector: assert property (
        @(posedge CLK) $past(1'b1,1,1'b0) && !$past(LOAD,1,1'b0) |-> (Q == {$past(Q,1,6'b0)[4:0], $past(D,1,1'b0)})
    );

    // On shift (LOAD was 0), MSB gets previous bit 4.
    check_shift_msb_propagate: assert property (
        @(posedge CLK) $past(1'b1,1,1'b0) && !$past(LOAD,1,1'b0) |-> (Q[5] == $past(Q,1,6'b0)[4])
    );

    // On shift (LOAD was 0), LSB gets previous D.
    check_shift_lsb_from_D: assert property (
        @(posedge CLK) $past(1'b1,1,1'b0) && !$past(LOAD,1,1'b0) |-> (Q[0] == $past(D,1,1'b0))
    );

    // If LOAD was 1 last cycle, both MSB and LSB equal D.
    check_load_sets_end_bits: assert property (
        @(posedge CLK) $past(1'b1,1,1'b0) && $past(LOAD,1,1'b0) |-> (Q[5] == $past(D,1,1'b0)) && (Q[0] == $past(D,1,1'b0))
    );

endmodule

rtl:
module binary_counter (
    input clk,
    input reset,
    input enable,
    output [3:0] Q
);

reg [3:0] Q_reg;
reg [3:0] Q_next;

always @(posedge clk) begin
    if (reset) begin
        Q_reg <= 4'b0;
    end
    else if (enable) begin
        Q_reg <= Q_next;
    end
end

always @* begin
    if (Q_reg == 4'b1111) begin
        Q_next = 4'b0000;
    end
    else begin
        Q_next = Q_reg + 1;
    end
end

assign Q = Q_reg;

endmodule

sva:
module binary_counter_sva (
    input logic clk,
    input logic reset,      // active-high synchronous reset
    input logic enable,
    input logic [3:0] Q
);

    // Q must be 0 on any clock where reset is asserted.
    reset_clears_Q: assert property (
        @(posedge clk) reset |-> (Q == 4'b0000)
    );

    // When enable is LOW, Q holds its previous value.
    hold_when_enable_low: assert property (
        @(posedge clk) disable iff (reset) (!enable) |-> (Q == $past(Q))
    );

    // When enable is HIGH and previous Q != 15, Q increments by 1.
    increment_when_enable_high_no_wrap: assert property (
        @(posedge clk) disable iff (reset) (enable && ($past(Q) != 4'hF)) |-> (Q == $past(Q) + 4'd1)
    );

    // When enable is HIGH and previous Q == 15, Q wraps to 0.
    wrap_when_enable_high_from_fifteen: assert property (
        @(posedge clk) disable iff (reset) (enable && ($past(Q) == 4'hF)) |-> (Q == 4'h0)
    );

    // Q only changes on a clock when enable is HIGH (reset cycles disabled).
    change_requires_enable: assert property (
        @(posedge clk) disable iff (reset) $changed(Q) |-> enable
    );

    // If Q is 0 on a cycle with enable HIGH (and previous cycle not in reset), previous Q was 15.
    zero_with_enable_implies_prev_fifteen: assert property (
        @(posedge clk) disable iff (reset) (enable && (Q == 4'h0) && $past(!reset)) |-> ($past(Q) == 4'hF)
    );

    // Immediately after reset deasserts, if enable is HIGH, Q becomes 1.
    next_is_one_after_reset_then_enable: assert property (
        @(posedge clk) disable iff (reset) (!reset && $past(reset) && enable) |-> (Q == 4'd1)
    );

    // Immediately after reset deasserts, if enable is LOW, Q stays at 0.
    next_is_zero_after_reset_then_disable: assert property (
        @(posedge clk) disable iff (reset) (!reset && $past(reset) && !enable) |-> (Q == 4'd0)
    );

    // From previous Q == 15, next Q is either 0 if enable HIGH, or holds at 15 if enable LOW.
    next_from_fifteen_cases: assert property (
        @(posedge clk) disable iff (reset) ($past(Q) == 4'hF) |-> ((enable && (Q == 4'h0)) || (!enable && (Q == 4'hF)))
    );

    // When enabled and previous Q was 0, Q increments to 1.
    increment_from_zero_when_enabled: assert property (
        @(posedge clk) disable iff (reset) (enable && ($past(Q) == 4'h0)) |-> (Q == 4'h1)
    );

endmodule

rtl:
module mux2to1 (Y, A, B, S);
    output Y;
    input A, B, S;
    assign Y = (S == 1'b0) ? A : B;
endmodule

module mux4to1 (Y, D0, D1, D2, D3, S0, S1);
    output Y;
    input D0, D1, D2, D3, S0, S1;
    wire w1, w2, w3;
    mux2to1 mux1 (.Y(w1), .A(D0), .B(D1), .S(S1));
    mux2to1 mux2 (.Y(w2), .A(D2), .B(D3), .S(S1));
    mux2to1 mux3 (.Y(w3), .A(w1), .B(w2), .S(S0));
    assign Y = w3;
endmodule

sva:
module mux4to1_sva (
    input logic CLK,
    input logic Y,
    input logic D0,
    input logic D1,
    input logic D2,
    input logic D3,
    input logic S0,
    input logic S1
);
    // Y equals D0 when S0=0 and S1=0.
    select_00_maps_to_D0: assert property (
        @(posedge CLK) ((S0 == 1'b0) && (S1 == 1'b0)) |-> (Y == D0)
    );

    // Y equals D1 when S0=0 and S1=1.
    select_01_maps_to_D1: assert property (
        @(posedge CLK) ((S0 == 1'b0) && (S1 == 1'b1)) |-> (Y == D1)
    );

    // Y equals D2 when S0=1 and S1=0.
    select_10_maps_to_D2: assert property (
        @(posedge CLK) ((S0 == 1'b1) && (S1 == 1'b0)) |-> (Y == D2)
    );

    // Y equals D3 when S0=1 and S1=1.
    select_11_maps_to_D3: assert property (
        @(posedge CLK) ((S0 == 1'b1) && (S1 == 1'b1)) |-> (Y == D3)
    );

    // Y matches the nested 2:1 mux composition.
    function_equivalence_nested_mux: assert property (
        @(posedge CLK) Y == (S0 ? (S1 ? D3 : D2) : (S1 ? D1 : D0))
    );

    // If all data and selects are stable, Y remains stable (purely combinational).
    stability_when_inputs_stable: assert property (
        @(posedge CLK) $stable({D0,D1,D2,D3,S0,S1}) |-> $stable(Y)
    );

    // With S0=0,S1=0 held stable, a change on D0 causes a corresponding change on Y.
    change_propagation_00: assert property (
        @(posedge CLK) ($stable(S0) && $stable(S1) && (S0 == 1'b0) && (S1 == 1'b0) && $changed(D0)) |-> ($changed(Y) && (Y == D0))
    );

    // With S0=0,S1=1 held stable, a change on D1 causes a corresponding change on Y.
    change_propagation_01: assert property (
        @(posedge CLK) ($stable(S0) && $stable(S1) && (S0 == 1'b0) && (S1 == 1'b1) && $changed(D1)) |-> ($changed(Y) && (Y == D1))
    );

    // With S0=1,S1=0 held stable, a change on D2 causes a corresponding change on Y.
    change_propagation_10: assert property (
        @(posedge CLK) ($stable(S0) && $stable(S1) && (S0 == 1'b1) && (S1 == 1'b0) && $changed(D2)) |-> ($changed(Y) && (Y == D2))
    );

    // With S0=1,S1=1 held stable, a change on D3 causes a corresponding change on Y.
    change_propagation_11: assert property (
        @(posedge CLK) ($stable(S0) && $stable(S1) && (S0 == 1'b1) && (S1 == 1'b1) && $changed(D3)) |-> ($changed(Y) && (Y == D3))
    );
endmodule

module mux_4to1_sva (
    input logic clk,
    input logic reset_n,
    input logic [7:0] D0,
    input logic [7:0] D1,
    input logic [7:0] D2,
    input logic [7:0] D3,
    input logic [1:0] SEL,
    input logic [7:0] Y
);
    // When SEL==00, Y equals D0 in the same cycle.
    check_sel00_maps_d0: assert property (
        @(posedge clk) disable iff (!reset_n) (SEL == 2'b00) |-> (Y == D0)
    );

    // When SEL==01, Y equals D1 in the same cycle.
    check_sel01_maps_d1: assert property (
        @(posedge clk) disable iff (!reset_n) (SEL == 2'b01) |-> (Y == D1)
    );

    // When SEL==10, Y equals D2 in the same cycle.
    check_sel10_maps_d2: assert property (
        @(posedge clk) disable iff (!reset_n) (SEL == 2'b10) |-> (Y == D2)
    );

    // When SEL==11, Y equals D3 in the same cycle.
    check_sel11_maps_d3: assert property (
        @(posedge clk) disable iff (!reset_n) (SEL == 2'b11) |-> (Y == D3)
    );

    // Functional equivalence to a 4:1 mux tree driven by SEL bits.
    check_mux_function: assert property (
        @(posedge clk) disable iff (!reset_n) Y == (SEL[1] ? (SEL[0] ? D3 : D2) : (SEL[0] ? D1 : D0))
    );

    // With SEL==00 held and D0 stable across a cycle, Y must be stable.
    check_stability_sel00: assert property (
        @(posedge clk) disable iff (!reset_n) (SEL == 2'b00 && $stable(SEL) && $stable(D0)) |-> $stable(Y)
    );

    // With SEL==01 held and D1 stable across a cycle, Y must be stable.
    check_stability_sel01: assert property (
        @(posedge clk) disable iff (!reset_n) (SEL == 2'b01 && $stable(SEL) && $stable(D1)) |-> $stable(Y)
    );

    // With SEL==10 held and D2 stable across a cycle, Y must be stable.
    check_stability_sel10: assert property (
        @(posedge clk) disable iff (!reset_n) (SEL == 2'b10 && $stable(SEL) && $stable(D2)) |-> $stable(Y)
    );

    // With SEL==11 held and D3 stable across a cycle, Y must be stable.
    check_stability_sel11: assert property (
        @(posedge clk) disable iff (!reset_n) (SEL == 2'b11 && $stable(SEL) && $stable(D3)) |-> $stable(Y)
    );
endmodule

