rtl:
module mux2to1(A, B, S, Y);
input A, B, S;
output Y;

assign Y = (!S && A) | (S && B);

endmodule

sva:
module mux2to1_sva (
    input logic A,
    input logic B,
    input logic S,
    input logic Y
);
    // On S rising, output selects B.
    select_B_on_S_rise: assert property (
        @(posedge S) Y == B
    );

    // On S falling, output selects A.
    select_A_on_S_fall: assert property (
        @(negedge S) Y == A
    );

    // On A rising, Y matches the mux equation.
    equation_hold_on_A_rise: assert property (
        @(posedge A) Y == ((!S && A) | (S && B))
    );

    // On A falling, Y matches the mux equation.
    equation_hold_on_A_fall: assert property (
        @(negedge A) Y == ((!S && A) | (S && B))
    );

    // On B rising, Y matches the mux equation.
    equation_hold_on_B_rise: assert property (
        @(posedge B) Y == ((!S && A) | (S && B))
    );

    // On B falling, Y matches the mux equation.
    equation_hold_on_B_fall: assert property (
        @(negedge B) Y == ((!S && A) | (S && B))
    );

    // When S=0 and A rises, Y follows A.
    y_follows_A_when_S0_rise: assert property (
        @(posedge A) (!S) |-> (Y == A)
    );

    // When S=0 and A falls, Y follows A.
    y_follows_A_when_S0_fall: assert property (
        @(negedge A) (!S) |-> (Y == A)
    );

    // When S=1 and B rises, Y follows B.
    y_follows_B_when_S1_rise: assert property (
        @(posedge B) (S) |-> (Y == B)
    );

    // When S=1 and B falls, Y follows B.
    y_follows_B_when_S1_fall: assert property (
        @(negedge B) (S) |-> (Y == B)
    );
endmodule

rtl:
module binary_counter (
    input clk,
    input rst,
    output reg [3:0] count
);

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            count <= 4'b0;
        end else begin
            count <= count + 1;
        end
    end

endmodule

sva:
module binary_counter_sva (
    input logic clk,
    input logic rst,
    input logic [3:0] count
);
    // While reset is asserted (active-high), count must be 0 at each clk edge.
    reset_forces_zero: assert property (
        @(posedge clk) rst |-> (count == 4'd0)
    );

    // If reset stays asserted across cycles, count remains 0 and stable.
    reset_holds_zero_stable: assert property (
        @(posedge clk) disable iff ($initstate) (rst && $past(rst)) |-> (count == 4'd0) && $stable(count)
    );

    // When reset deasserts (1->0), count becomes 1 on that clk edge.
    count_is_one_on_reset_release: assert property (
        @(posedge clk) disable iff ($initstate) $fell(rst) |-> (count == 4'd1)
    );

    // When not in reset, count must change every clk (increments or wraps).
    count_changes_every_cycle_without_reset: assert property (
        @(posedge clk) disable iff (rst || $initstate) !$stable(count)
    );

    // Without reset, if count is 0 now, it must have been 15 in the previous cycle (wrap).
    zero_now_means_prev_fifteen: assert property (
        @(posedge clk) disable iff (rst || $initstate) (count == 4'd0) |-> ($past(count) == 4'd15)
    );

    // When reset asserts (0->1), count must be 0 at that clk edge.
    reset_rise_results_zero: assert property (
        @(posedge clk) disable iff ($initstate) $rose(rst) |-> (count == 4'd0)
    );
endmodule

rtl:
module EtherCAT_master #(
    parameter n = 8, 
    parameter m = 4  
)(
    input [n-1:0] in_send,
    input [m-1:0] in_receive,
    input clk,
    input rst,
    output reg [n-1:0] out_receive,
    output reg [m-1:0] out_send
);

always @(posedge clk or posedge rst) begin
    if (rst) begin
        out_receive <= 0;
        out_send <= 0;
    end else begin
        out_receive <= in_send;
        out_send <= in_receive;
    end
end

endmodule

sva:
module EtherCAT_master_sva #(
    parameter int n = 8, 
    parameter int m = 4
)(
    input  logic [n-1:0] in_send,
    input  logic [m-1:0] in_receive,
    input  logic         clk,
    input  logic         rst,
    input  logic [n-1:0] out_receive,
    input  logic [m-1:0] out_send
);

    ///// Reset behavior /////
    // After any cycle with rst HIGH, outputs are zero in the next cycle.
    reset_clears_next: assert property (
        @(posedge clk) rst |=> (out_receive == '0) && (out_send == '0)
    );

    // While rst is held HIGH across consecutive cycles, outputs are zero.
    reset_held_forces_zero: assert property (
        @(posedge clk) ($past(rst) && rst) |-> (out_receive == '0) && (out_send == '0)
    );

    // While rst is held HIGH across consecutive cycles, outputs do not change.
    reset_held_outputs_stable: assert property (
        @(posedge clk) ($past(rst) && rst) |-> $stable(out_receive) && $stable(out_send)
    );

    // On the first cycle after rst was HIGH (deassertion at this clock), outputs are still zero this cycle.
    deassertion_cycle_outputs_zero: assert property (
        @(posedge clk) ($past(rst) && !rst) |-> (out_receive == '0) && (out_send == '0)
    );

    // A rising edge of rst leads to zeroed outputs by the next cycle.
    rise_reset_zero_next: assert property (
        @(posedge clk) $rose(rst) |=> (out_receive == '0) && (out_send == '0)
    );

    ///// Coverage (non-constraining) /////
    // Observe pass-through of in_send to out_receive in one cycle when not in reset.
    cover_receive_pass: cover property (
        @(posedge clk) disable iff (rst) out_receive == $past(in_send)
    );

    // Observe pass-through of in_receive to out_send in one cycle when not in reset.
    cover_send_pass: cover property (
        @(posedge clk) disable iff (rst) out_send == $past(in_receive)
    );

endmodule

rtl:
module ripple_carry_adder (
  input [3:0] A,
  input [3:0] B,
  input cin,
  output [3:0] sum,
  output cout
);

  wire [4:0] carry;

  assign carry[0] = cin;

  genvar i;
  generate
    for (i = 0; i < 4; i = i + 1) begin : adder
      full_adder fa (
        .a(A[i]),
        .b(B[i]),
        .cin(carry[i]),
        .sum(sum[i]),
        .cout(carry[i+1])
      );
    end
  endgenerate

  assign cout = carry[4];

endmodule

module full_adder (
  input a,
  input b,
  input cin,
  output sum,
  output cout
);

  assign sum = a ^ b ^ cin;
  assign cout = (a & b) | (a & cin) | (b & cin);

endmodule

sva:
module ripple_carry_adder_sva (
    input logic CLK,
    input logic RESETn, // external reset for property gating (DUT has no reset)
    input logic [3:0] A,
    input logic [3:0] B,
    input logic cin,
    input logic [3:0] sum,
    input logic cout
);
    ///// Arithmetic correctness /////
    // Sum+carry equals 5-bit addition of A, B, and cin.
    check_sum_cout_matches_addition: assert property (
        @(posedge CLK) disable iff (!RESETn)
        ({cout, sum} == ({1'b0, A} + {1'b0, B} + {4'b0000, cin}))
    );

    ///// Bit-level ripple relationships /////
    // LSB sum is XOR of A[0], B[0], cin.
    check_sum0_xor: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (sum[0] == (A[0] ^ B[0] ^ cin))
    );
    // sum[1] equals XOR of A[1]^B[1] with carry from bit0.
    check_sum1_xor_with_c1: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (sum[1] == ((A[1] ^ B[1]) ^ ((A[0] & B[0]) | ((A[0] ^ B[0]) & cin))))
    );
    // sum[2] equals XOR of A[2]^B[2] with carry from bit1.
    check_sum2_xor_with_c2: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (sum[2] == ((A[2] ^ B[2]) ^ (
            (A[1] & B[1]) | ((A[1] ^ B[1]) & ((A[0] & B[0]) | ((A[0] ^ B[0]) & cin)))
        )))
    );
    // sum[3] equals XOR of A[3]^B[3] with carry from bit2.
    check_sum3_xor_with_c3: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (sum[3] == ((A[3] ^ B[3]) ^ (
            (A[2] & B[2]) | ((A[2] ^ B[2]) & (
                (A[1] & B[1]) | ((A[1] ^ B[1]) & ((A[0] & B[0]) | ((A[0] ^ B[0]) & cin)))
            ))
        )))
    );
    // cout equals carry out from bit3.
    check_cout_carry4: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (cout == (
            (A[3] & B[3]) | ((A[3] ^ B[3]) & (
                (A[2] & B[2]) | ((A[2] ^ B[2]) & (
                    (A[1] & B[1]) | ((A[1] ^ B[1]) & ((A[0] & B[0]) | ((A[0] ^ B[0]) & cin)))
                ))
            ))
        ))
    );

    ///// Sanity scenarios /////
    // All zeros in => all zeros out.
    check_zero_input_result: assert property (
        @(posedge CLK) disable iff (!RESETn)
        ((A == 4'b0000) && (B == 4'b0000) && (cin == 1'b0)) |-> ((sum == 4'b0000) && (cout == 1'b0))
    );
    // With B==0 and cin==0, output equals A and no carry.
    check_pass_through_when_B_zero_and_cin_zero: assert property (
        @(posedge CLK) disable iff (!RESETn)
        ((B == 4'b0000) && (cin == 1'b0)) |-> ((sum == A) && (cout == 1'b0))
    );
    // Adding bitwise complement with cin==0 yields 0xF and no carry.
    check_complement_no_cin: assert property (
        @(posedge CLK) disable iff (!RESETn)
        ((B == ~A) && (cin == 1'b0)) |-> ((sum == 4'hF) && (cout == 1'b0))
    );
    // Adding bitwise complement with cin==1 yields 0x0 and carry.
    check_complement_with_cin: assert property (
        @(posedge CLK) disable iff (!RESETn)
        ((B == ~A) && (cin == 1'b1)) |-> ((sum == 4'h0) && (cout == 1'b1))
    );
endmodule

