module latch (
  input E,
  input SE,
  input CK,
  output ECK
);

  reg gated_clk;

  always @(posedge CK) begin
    if (E && !SE) begin
      gated_clk <= 1'b1;
    end else begin
      gated_clk <= 1'b0;
    end
  end

  assign ECK = gated_clk;

endmodule

module clock_gate (
  input CLK,
  input EN,
  input TE,
  output ENCLK
);

  reg gated_clk;

  always @(posedge CLK) begin
    if (EN && !TE) begin
      gated_clk <= 1'b1;
    end else begin
      gated_clk <= 1'b0;
    end
  end

  latch latch (
    .E(EN),
    .SE(TE),
    .CK(CLK),
    .ECK(ENCLK)
  );

endmodule

sva:
module latch_sva (
    input logic E,
    input logic SE,
    input logic CK,
    input logic ECK
);
    // ECK equals prior cycle's (E && !SE).
    check_eck_matches_past_enable: assert property (
        @(posedge CK) disable iff ($initstate) ECK == $past(E && !SE)
    );

    // If SE was 1 last cycle, ECK must be 0 now.
    check_eck_zero_on_se: assert property (
        @(posedge CK) disable iff ($initstate) $past(SE) |-> (ECK == 1'b0)
    );

    // If E was 1 and SE was 0 last cycle, ECK must be 1 now.
    check_eck_one_on_enable: assert property (
        @(posedge CK) disable iff ($initstate) $past(E && !SE) |-> (ECK == 1'b1)
    );

    // If E was 0 and SE was 0 last cycle, ECK must be 0 now.
    check_eck_zero_when_disabled: assert property (
        @(posedge CK) disable iff ($initstate) $past(!E && !SE) |-> (ECK == 1'b0)
    );
endmodule

module clock_gate_sva (
    input logic CLK,
    input logic EN,
    input logic TE,
    input logic ENCLK
);
    // ENCLK equals prior cycle's (EN && !TE).
    check_enclk_matches_past_enable: assert property (
        @(posedge CLK) disable iff ($initstate) ENCLK == $past(EN && !TE)
    );

    // If TE was 1 last cycle, ENCLK must be 0 now.
    check_enclk_zero_on_te: assert property (
        @(posedge CLK) disable iff ($initstate) $past(TE) |-> (ENCLK == 1'b0)
    );

    // If EN was 1 and TE was 0 last cycle, ENCLK must be 1 now.
    check_enclk_one_on_enable: assert property (
        @(posedge CLK) disable iff ($initstate) $past(EN && !TE) |-> (ENCLK == 1'b1)
    );

    // If EN was 0 and TE was 0 last cycle, ENCLK must be 0 now.
    check_enclk_zero_when_disabled: assert property (
        @(posedge CLK) disable iff ($initstate) $past(!EN && !TE) |-> (ENCLK == 1'b0)
    );
endmodule

rtl:
module complement (
    output [3:0] X,
    input  [3:0] A
);


    not inv1 (
       X[0],
       A[0]
    );

    not inv2 (
       X[1],
       A[1]
    );

    not inv3 (
       X[2],
       A[2]
    );

    not inv4 (
       X[3],
       A[3]
    );

endmodule

sva:
module complement_sva (
    input logic [3:0] X,
    input logic [3:0] A
);

    // On any A edge, X must equal bitwise complement of A.
    check_vector_complement: assert property (
        @(posedge A[0] or negedge A[0] or
          posedge A[1] or negedge A[1] or
          posedge A[2] or negedge A[2] or
          posedge A[3] or negedge A[3])
        (X == ~A)
    );

    // Bit 0: X[0] is the inverse of A[0] on any A[0] edge.
    check_x0_is_not_a0: assert property (
        @(posedge A[0] or negedge A[0]) (X[0] == ~A[0])
    );

    // Bit 1: X[1] is the inverse of A[1] on any A[1] edge.
    check_x1_is_not_a1: assert property (
        @(posedge A[1] or negedge A[1]) (X[1] == ~A[1])
    );

    // Bit 2: X[2] is the inverse of A[2] on any A[2] edge.
    check_x2_is_not_a2: assert property (
        @(posedge A[2] or negedge A[2]) (X[2] == ~A[2])
    );

    // Bit 3: X[3] is the inverse of A[3] on any A[3] edge.
    check_x3_is_not_a3: assert property (
        @(posedge A[3] or negedge A[3]) (X[3] == ~A[3])
    );

    // Any change in A must cause a change in X.
    change_in_a_changes_x: assert property (
        @(posedge A[0] or negedge A[0] or
          posedge A[1] or negedge A[1] or
          posedge A[2] or negedge A[2] or
          posedge A[3] or negedge A[3])
        $changed(X)
    );

    // A[0] only changes -> only X[0] changes.
    singlebit0_maps: assert property (
        @(posedge A[0] or negedge A[0])
        ($stable(A[1]) && $stable(A[2]) && $stable(A[3]))
        |-> ($changed(X[0]) && $stable(X[1]) && $stable(X[2]) && $stable(X[3]))
    );

    // A[1] only changes -> only X[1] changes.
    singlebit1_maps: assert property (
        @(posedge A[1] or negedge A[1])
        ($stable(A[0]) && $stable(A[2]) && $stable(A[3]))
        |-> ($changed(X[1]) && $stable(X[0]) && $stable(X[2]) && $stable(X[3]))
    );

    // A[2] only changes -> only X[2] changes.
    singlebit2_maps: assert property (
        @(posedge A[2] or negedge A[2])
        ($stable(A[0]) && $stable(A[1]) && $stable(A[3]))
        |-> ($changed(X[2]) && $stable(X[0]) && $stable(X[1]) && $stable(X[3]))
    );

    // A[3] only changes -> only X[3] changes.
    singlebit3_maps: assert property (
        @(posedge A[3] or negedge A[3])
        ($stable(A[0]) && $stable(A[1]) && $stable(A[2]))
        |-> ($changed(X[3]) && $stable(X[0]) && $stable(X[1]) && $stable(X[2]))
    );

    // Any change in X must correspond to a change in A.
    x_change_implies_a_change: assert property (
        @(posedge X[0] or negedge X[0] or
          posedge X[1] or negedge X[1] or
          posedge X[2] or negedge X[2] or
          posedge X[3] or negedge X[3])
        $changed(A)
    );

endmodule

