module amiq_mux2_1(input clk, input sel, input in0, input in1, output reg out);
	initial out=0;

	always@(posedge clk) begin
		out<=sel?in1:in0;	
	end
endmodule

sva:
module amiq_mux2_1_sva (
    input logic clk,
    input logic sel,
    input logic in0,
    input logic in1,
    input logic out
);
    // Out equals previous cycle's selected input (registered mux behavior).
    check_out_matches_prev_selected_input: assert property (
        @(posedge clk) disable iff ($initstate) out == $past(sel ? in1 : in0)
    );

    // When previous sel was 0, out equals previous in0.
    check_out_prev_in0_when_prev_sel0: assert property (
        @(posedge clk) disable iff ($initstate) ($past(sel) == 1'b0) |-> (out == $past(in0))
    );

    // When previous sel was 1, out equals previous in1.
    check_out_prev_in1_when_prev_sel1: assert property (
        @(posedge clk) disable iff ($initstate) ($past(sel) == 1'b1) |-> (out == $past(in1))
    );

    // If both inputs were equal in the previous cycle, out equals that value.
    check_out_when_prev_inputs_equal: assert property (
        @(posedge clk) disable iff ($initstate) ($past(in0) == $past(in1)) |-> (out == $past(in0))
    );

    // If sel is 0 this cycle, next cycle out equals this cycle's in0.
    check_next_out_matches_in0_when_sel0: assert property (
        @(posedge clk) disable iff ($initstate) (sel == 1'b0) |=> (out == $past(in0))
    );

    // If sel is 1 this cycle, next cycle out equals this cycle's in1.
    check_next_out_matches_in1_when_sel1: assert property (
        @(posedge clk) disable iff ($initstate) (sel == 1'b1) |=> (out == $past(in1))
    );
endmodule

rtl:
module mux4to1 (
    sel,
    in0,
    in1,
    in2,
    in3,
    out
);

    // Module ports
    input [1:0] sel;
    input in0, in1, in2, in3;
    output out;

    // Local signals
    reg mux_out;

    // Implement the multiplexer using an always block
    always @ (sel, in0, in1, in2, in3) begin
        case (sel)
            2'b00: mux_out = in0;
            2'b01: mux_out = in1;
            2'b10: mux_out = in2;
            2'b11: mux_out = in3;
        endcase
    end

    // Assign the output signal to the selected input signal
    assign out = mux_out;

endmodule

sva:
module mux4to1_sva (
    input logic [1:0] sel,
    input logic in0,
    input logic in1,
    input logic in2,
    input logic in3,
    input logic out
);

    // Helper: compute the expected mux output from sel and inputs.
    function automatic logic selected_input_value (
        input logic [1:0] s,
        input logic i0, i1, i2, i3
    );
        case (s)
            2'b00: selected_input_value = i0;
            2'b01: selected_input_value = i1;
            2'b10: selected_input_value = i2;
            default: selected_input_value = i3;
        endcase
    endfunction

    ///// Functional correctness checks /////

    // Output equals selected input when sel[0] rises.
    check_out_matches_sel_on_sel0_posedge: assert property (
        @(posedge sel[0]) out == selected_input_value(sel, in0, in1, in2, in3)
    );

    // Output equals selected input when sel[1] rises.
    check_out_matches_sel_on_sel1_posedge: assert property (
        @(posedge sel[1]) out == selected_input_value(sel, in0, in1, in2, in3)
    );

    // Output equals selected input when in0 rises.
    check_out_matches_sel_on_in0_posedge: assert property (
        @(posedge in0) out == selected_input_value(sel, in0, in1, in2, in3)
    );

    // Output equals selected input when in1 rises.
    check_out_matches_sel_on_in1_posedge: assert property (
        @(posedge in1) out == selected_input_value(sel, in0, in1, in2, in3)
    );

    // Output equals selected input when in2 rises.
    check_out_matches_sel_on_in2_posedge: assert property (
        @(posedge in2) out == selected_input_value(sel, in0, in1, in2, in3)
    );

    // Output equals selected input when in3 rises.
    check_out_matches_sel_on_in3_posedge: assert property (
        @(posedge in3) out == selected_input_value(sel, in0, in1, in2, in3)
    );

    // When sel==00, out mirrors in0 on in0 rising edges.
    check_route_in0_when_sel00: assert property (
        @(posedge in0) (sel == 2'b00) |-> (out == in0)
    );

    // When sel==01, out mirrors in1 on in1 rising edges.
    check_route_in1_when_sel01: assert property (
        @(posedge in1) (sel == 2'b01) |-> (out == in1)
    );

    // When sel==10, out mirrors in2 on in2 rising edges.
    check_route_in2_when_sel10: assert property (
        @(posedge in2) (sel == 2'b10) |-> (out == in2)
    );

    // When sel==11, out mirrors in3 on in3 rising edges.
    check_route_in3_when_sel11: assert property (
        @(posedge in3) (sel == 2'b11) |-> (out == in3)
    );

    // When out rises, it equals the value of the currently selected input.
    check_out_posedge_matches_selected: assert property (
        @(posedge out) out == selected_input_value(sel, in0, in1, in2, in3)
    );

endmodule

rtl:
module four_bit_adder (
    input [3:0] A,
    input [3:0] B,
    input CI,
    output [3:0] SUM,
    output CO
);

    wire C1, C2, C3;

    // Instantiate 4-bit full adder cells
    full_adder FA0(A[0], B[0], CI, SUM[0], C1);
    full_adder FA1(A[1], B[1], C1, SUM[1], C2);
    full_adder FA2(A[2], B[2], C2, SUM[2], C3);
    full_adder FA3(A[3], B[3], C3, SUM[3], CO);

endmodule

module full_adder (
    input A,
    input B,
    input CI,
    output SUM,
    output CO
);

    // Assign Sum and Carry Out using XOR and AND gates
    assign SUM = A ^ B ^ CI;
    assign CO = (A & B) | (B & CI) | (A & CI);

endmodule

sva:
module four_bit_adder_sva (
    input logic CLK,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic CI,
    input logic [3:0] SUM,
    input logic CO
);
    // Combinational 4-bit adder; no reset in RTL; use CLK only for sampling.

    // SUM and CO together equal the 5-bit arithmetic sum of A+B+CI.
    check_sum_and_carry_are_arithmetic: assert property (
        @(posedge CLK) {CO, SUM} == ({1'b0, A} + {1'b0, B} + CI)
    );

    // CO equals the MSB of the 5-bit sum.
    check_carry_equals_sum_msb: assert property (
        @(posedge CLK) CO == ({1'b0, A} + {1'b0, B} + CI)[4]
    );

    // No carry-out when both MSBs are 0.
    check_no_carry_when_both_msb_zero: assert property (
        @(posedge CLK) (A[3] == 1'b0 && B[3] == 1'b0) |-> (CO == 1'b0)
    );

    // Carry-out must be 1 when both MSBs are 1.
    check_carry_when_both_msb_one: assert property (
        @(posedge CLK) (A[3] == 1'b1 && B[3] == 1'b1) |-> (CO == 1'b1)
    );

    // LSB sum bit is XOR of A[0], B[0], and CI.
    check_lsb_sum_xor: assert property (
        @(posedge CLK) SUM[0] == (A[0] ^ B[0] ^ CI)
    );

    // Adding B=0 with CI=0 yields SUM=A and CO=0.
    check_identity_b_zero_no_ci: assert property (
        @(posedge CLK) ((B == 4'b0000) && (CI == 1'b0)) |-> ((SUM == A) && (CO == 1'b0))
    );

    // Adding A=0 with CI=0 yields SUM=B and CO=0.
    check_identity_a_zero_no_ci: assert property (
        @(posedge CLK) ((A == 4'b0000) && (CI == 1'b0)) |-> ((SUM == B) && (CO == 1'b0))
    );

    // With A=0 and B=0, output equals CI (no carry-out).
    check_zero_plus_zero_ci_only: assert property (
        @(posedge CLK) ((A == 4'b0000) && (B == 4'b0000)) |-> ((CO == 1'b0) && (SUM == {3'b000, CI}))
    );

    // A + (~A) + 1 produces SUM=0 and CO=1.
    check_ones_complement_plus_one: assert property (
        @(posedge CLK) ((B == ~A) && (CI == 1'b1)) |-> ((SUM == 4'b0000) && (CO == 1'b1))
    );

    // When A==B and CI==0, result is A shifted left by 1 with carry=MSB of A.
    check_double_when_equal_no_ci: assert property (
        @(posedge CLK) ((A == B) && (CI == 1'b0)) |-> ({CO, SUM} == {A[3], {A[2:0], 1'b0}})
    );

    // Adding 0xF with CI=1 yields {1, A}.
    check_add_f_with_ci_one: assert property (
        @(posedge CLK) ((B == 4'hF) && (CI == 1'b1)) |-> ({CO, SUM} == {1'b1, A})
    );

    // A + (~A) with CI=0 produces SUM=0xF and CO=0.
    check_ones_complement_no_ci: assert property (
        @(posedge CLK) ((B == ~A) && (CI == 1'b0)) |-> ((SUM == 4'hF) && (CO == 1'b0))
    );
endmodule

rtl:
module rsdec_syn_m3 (y, x);
	input [8:0] x;
	output [8:0] y;
	reg [8:0] y;
	always @ (x)
	begin
		y[0] = x[5];
		y[1] = x[6];
		y[2] = x[7];
		y[3] = x[8];
		y[4] = x[0] ^ x[5];
		y[5] = x[1] ^ x[6];
		y[6] = x[2] ^ x[7];
		y[7] = x[3] ^ x[8];
		y[8] = x[4];
	end
endmodule

sva:
module rsdec_syn_m3_sva (
    input logic CLK,
    input logic RESETn,
    input logic [8:0] x,
    input logic [8:0] y
);
    ///// Combinational mapping checks /////
    // y[0] equals x[5].
    map_y0_from_x5: assert property (
        @(posedge CLK) disable iff (!RESETn) (y[0] == x[5])
    );
    // y[1] equals x[6].
    map_y1_from_x6: assert property (
        @(posedge CLK) disable iff (!RESETn) (y[1] == x[6])
    );
    // y[2] equals x[7].
    map_y2_from_x7: assert property (
        @(posedge CLK) disable iff (!RESETn) (y[2] == x[7])
    );
    // y[3] equals x[8].
    map_y3_from_x8: assert property (
        @(posedge CLK) disable iff (!RESETn) (y[3] == x[8])
    );
    // y[4] equals x[0] XOR x[5].
    map_y4_from_x0_x5: assert property (
        @(posedge CLK) disable iff (!RESETn) (y[4] == (x[0] ^ x[5]))
    );
    // y[5] equals x[1] XOR x[6].
    map_y5_from_x1_x6: assert property (
        @(posedge CLK) disable iff (!RESETn) (y[5] == (x[1] ^ x[6]))
    );
    // y[6] equals x[2] XOR x[7].
    map_y6_from_x2_x7: assert property (
        @(posedge CLK) disable iff (!RESETn) (y[6] == (x[2] ^ x[7]))
    );
    // y[7] equals x[3] XOR x[8].
    map_y7_from_x3_x8: assert property (
        @(posedge CLK) disable iff (!RESETn) (y[7] == (x[3] ^ x[8]))
    );
    // y[8] equals x[4].
    map_y8_from_x4: assert property (
        @(posedge CLK) disable iff (!RESETn) (y[8] == x[4])
    );
    // Full vector mapping equals the RTL function.
    map_y_vector: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (y == { x[4], (x[3] ^ x[8]), (x[2] ^ x[7]), (x[1] ^ x[6]), (x[0] ^ x[5]), x[8], x[7], x[6], x[5] })
    );

    ///// Derived consistency checks /////
    // x[0] can be recovered as y[4] XOR y[0].
    recover_x0_via_y4_xor_y0: assert property (
        @(posedge CLK) disable iff (!RESETn) ((y[4] ^ y[0]) == x[0])
    );
    // x[1] can be recovered as y[5] XOR y[1].
    recover_x1_via_y5_xor_y1: assert property (
        @(posedge CLK) disable iff (!RESETn) ((y[5] ^ y[1]) == x[1])
    );
    // x[2] can be recovered as y[6] XOR y[2].
    recover_x2_via_y6_xor_y2: assert property (
        @(posedge CLK) disable iff (!RESETn) ((y[6] ^ y[2]) == x[2])
    );
    // x[3] can be recovered as y[7] XOR y[3].
    recover_x3_via_y7_xor_y3: assert property (
        @(posedge CLK) disable iff (!RESETn) ((y[7] ^ y[3]) == x[3])
    );
endmodule

rtl:
module adder(
  input [7:0] A,
  input [7:0] B,
  output [7:0] S,
  output C
);

  wire [8:0] sum;

  assign sum = A + B;

  assign S = sum[7:0];
  assign C = sum[8];

endmodule

sva:
module adder_sva (
    // DUT ports as inputs to the SVA module
    input logic [7:0] A,
    input logic [7:0] B,
    input logic [7:0] S,
    input logic       C,
    // SVA sampling clock (DUT has no clock/reset; purely combinational)
    input logic       CLK
);
    // Combinational adder: sum = A + B; S = sum[7:0]; C = sum[8].

    // Outputs equal zero-extended sum of inputs.
    check_sum_concat: assert property (
        @(posedge CLK) {C, S} == ({1'b0, A} + {1'b0, B})
    );

    // S equals the lower 8 bits of the sum.
    check_sum_low_bits: assert property (
        @(posedge CLK) S == ({1'b0, A} + {1'b0, B})[7:0]
    );

    // C equals the carry-out bit of the sum.
    check_carry_bit: assert property (
        @(posedge CLK) C == ({1'b0, A} + {1'b0, B})[8]
    );

    // Additive identity when B is zero.
    check_identity_B_zero: assert property (
        @(posedge CLK) (B == 8'h00) |-> ({C, S} == {1'b0, A})
    );

    // Additive identity when A is zero.
    check_identity_A_zero: assert property (
        @(posedge CLK) (A == 8'h00) |-> ({C, S} == {1'b0, B})
    );

    // Increment by one when B is 1.
    check_increment_B_one: assert property (
        @(posedge CLK) (B == 8'h01) |-> ({C, S} == ({1'b0, A} + 9'd1))
    );

    // Increment by one when A is 1.
    check_increment_A_one: assert property (
        @(posedge CLK) (A == 8'h01) |-> ({C, S} == ({1'b0, B} + 9'd1))
    );

    // Max inputs produce 0x1FE (S=0xFE, C=1).
    check_max_plus_max: assert property (
        @(posedge CLK) (A == 8'hFF && B == 8'hFF) |-> (S == 8'hFE && C == 1'b1)
    );

    // If inputs are stable, outputs must be stable (pure combinational).
    check_stability_no_state: assert property (
        @(posedge CLK) $stable({A, B}) |-> $stable({C, S})
    );
endmodule

rtl:
module ripple_carry_adder(
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] Sum,
    output Cout
);

wire [3:0] C;

// calculate sum bits
assign Sum[0] = A[0] ^ B[0] ^ Cin;
assign Sum[1] = A[1] ^ B[1] ^ C[0];
assign Sum[2] = A[2] ^ B[2] ^ C[1];
assign Sum[3] = A[3] ^ B[3] ^ C[2];

// calculate carry-out bit
assign Cout = (A[3] & B[3]) | (A[3] & C[2]) | (B[3] & C[2]);

// calculate carry bits
assign C[0] = (A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin);
assign C[1] = (A[1] & B[1]) | (A[1] & C[0]) | (B[1] & C[0]);
assign C[2] = (A[2] & B[2]) | (A[2] & C[1]) | (B[2] & C[1]);

endmodule

sva:
module ripple_carry_adder_sva (
    input  logic        CLK,   // External clock for SVA only; DUT has no clock/reset
    input  logic [3:0]  A,
    input  logic [3:0]  B,
    input  logic        Cin,
    input  logic [3:0]  Sum,
    input  logic        Cout
);
    // Combinational ripple-carry adder: Sum[i]=Ai^Bi^carry_in, Cout from final carry

    let c0_exp = (A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin);
    let c1_exp = (A[1] & B[1]) | (A[1] & c0_exp) | (B[1] & c0_exp);
    let c2_exp = (A[2] & B[2]) | (A[2] & c1_exp) | (B[2] & c1_exp);

    // Sum[0] matches RTL expression A0 ^ B0 ^ Cin.
    check_sum0_matches_rtl: assert property (
        @(posedge CLK) Sum[0] == (A[0] ^ B[0] ^ Cin)
    );

    // Sum[1] matches RTL expression A1 ^ B1 ^ C0.
    check_sum1_matches_rtl: assert property (
        @(posedge CLK) Sum[1] == (A[1] ^ B[1] ^ c0_exp)
    );

    // Sum[2] matches RTL expression A2 ^ B2 ^ C1.
    check_sum2_matches_rtl: assert property (
        @(posedge CLK) Sum[2] == (A[2] ^ B[2] ^ c1_exp)
    );

    // Sum[3] matches RTL expression A3 ^ B3 ^ C2.
    check_sum3_matches_rtl: assert property (
        @(posedge CLK) Sum[3] == (A[3] ^ B[3] ^ c2_exp)
    );

    // Cout matches RTL expression using A3, B3, and C2.
    check_cout_matches_rtl: assert property (
        @(posedge CLK) Cout == ((A[3] & B[3]) | (A[3] & c2_exp) | (B[3] & c2_exp))
    );

    // Full 5-bit result equals A + B + Cin.
    check_full_result_adds: assert property (
        @(posedge CLK) {Cout, Sum} == ({1'b0, A} + {1'b0, B} + Cin)
    );

    // Outputs are known when inputs are known.
    check_known_propagation: assert property (
        @(posedge CLK) (!$isunknown({A, B, Cin})) |-> (!$isunknown({Sum, Cout}))
    );

    // If B==0 and Cin==0 then Sum==A and Cout==0.
    check_identity_B_zero: assert property (
        @(posedge CLK) ((B == 4'b0000) && (Cin == 1'b0)) |-> ((Sum == A) && (Cout == 1'b0))
    );

    // If A==0 and Cin==0 then Sum==B and Cout==0.
    check_identity_A_zero: assert property (
        @(posedge CLK) ((A == 4'b0000) && (Cin == 1'b0)) |-> ((Sum == B) && (Cout == 1'b0))
    );

    // If B==4'hF and Cin==1 then {Cout,Sum} == {1,A}.
    check_full_carry_propagation: assert property (
        @(posedge CLK) ((B == 4'hF) && (Cin == 1'b1)) |-> ({Cout, Sum} == {1'b1, A})
    );

endmodule

rtl:
module bin_to_gray(
    input [3:0] bin,
    output [3:0] gray
);

assign gray[3] = bin[3];
assign gray[2] = bin[3] ^ bin[2];
assign gray[1] = bin[2] ^ bin[1];
assign gray[0] = bin[1] ^ bin[0];

endmodule

sva:
module bin_to_gray_sva (
    input logic CLK,
    input logic [3:0] bin,
    input logic [3:0] gray
);
    // Gray MSB equals binary MSB.
    check_gray_msb_copies_bin_msb: assert property (
        @(posedge CLK) gray[3] == bin[3]
    );

    // Gray[2] equals bin[3] XOR bin[2].
    check_gray_bit2_xor: assert property (
        @(posedge CLK) gray[2] == (bin[3] ^ bin[2])
    );

    // Gray[1] equals bin[2] XOR bin[1].
    check_gray_bit1_xor: assert property (
        @(posedge CLK) gray[1] == (bin[2] ^ bin[1])
    );

    // Gray[0] equals bin[1] XOR bin[0].
    check_gray_bit0_xor: assert property (
        @(posedge CLK) gray[0] == (bin[1] ^ bin[0])
    );

    // Toggling only bin[3] toggles gray[3] and gray[2]; lower bits hold.
    check_toggle_only_bin3_affects_gray3_and2: assert property (
        @(posedge CLK) ($changed(bin[3]) && $stable(bin[2:0]))
        |-> ($changed(gray[3]) && $changed(gray[2]) && $stable(gray[1:0]))
    );

    // Toggling only bin[2] toggles gray[2] and gray[1]; others hold.
    check_toggle_only_bin2_affects_gray2_and1: assert property (
        @(posedge CLK) ($changed(bin[2]) && $stable({bin[3], bin[1:0]}))
        |-> ($changed(gray[2]) && $changed(gray[1]) && $stable({gray[3], gray[0]}))
    );

    // Toggling only bin[1] toggles gray[1] and gray[0]; upper bits hold.
    check_toggle_only_bin1_affects_gray1_and0: assert property (
        @(posedge CLK) ($changed(bin[1]) && $stable({bin[3:2], bin[0]}))
        |-> ($changed(gray[1]) && $changed(gray[0]) && $stable(gray[3:2]))
    );

    // Toggling only bin[0] toggles only gray[0]; upper bits hold.
    check_toggle_only_bin0_affects_gray0_only: assert property (
        @(posedge CLK) ($changed(bin[0]) && $stable(bin[3:1]))
        |-> ($changed(gray[0]) && $stable(gray[3:1]))
    );

    // Binary bit2 reconstructs as gray[3] XOR gray[2].
    check_inverse_bin2_from_gray: assert property (
        @(posedge CLK) bin[2] == (gray[3] ^ gray[2])
    );

    // Binary bit0 reconstructs as gray[3]^gray[2]^gray[1]^gray[0].
    check_inverse_bin0_from_gray: assert property (
        @(posedge CLK) bin[0] == (gray[3] ^ gray[2] ^ gray[1] ^ gray[0])
    );
endmodule

rtl:
module d_ff_en_0
   (d_ff3_sign_out,
    FSM_sequential_state_reg,
    Q,
    CLK,
    EN);

  input [1:0] FSM_sequential_state_reg;
  input [0:0] Q;
  input CLK;
  input EN;
  output reg d_ff3_sign_out;

  wire [0:0] D;

  assign D = Q;

  always @ (posedge CLK or negedge EN) begin
    if (!EN) begin
      d_ff3_sign_out <= 1'b0;
    end
    else begin
      d_ff3_sign_out <= D;
    end
  end

endmodule

sva:
module d_ff_en_0_sva (
    input  logic [0:0] d_ff3_sign_out,
    input  logic [1:0] FSM_sequential_state_reg,
    input  logic [0:0] Q,
    input  logic       CLK,
    input  logic       EN
);
    // Clock: CLK (posedge). Reset: EN active-low, asynchronous.

    ///// Asynchronous reset behavior /////
    // When EN is LOW at a clock edge, output must be 0.
    reset_level_forces_zero: assert property (
        @(posedge CLK) (EN == 1'b0) |-> (d_ff3_sign_out == 1'b0)
    );

    // On a falling edge of EN between clocks, output must be 0 at the next clock.
    reset_fall_clears_output: assert property (
        @(posedge CLK) $fell(EN) |-> (d_ff3_sign_out == 1'b0)
    );

    // While EN stays LOW across cycles, output remains 0 and stable.
    reset_hold_zero_and_stable: assert property (
        @(posedge CLK) (!EN && !$past(EN)) |-> (d_ff3_sign_out == 1'b0 && $stable(d_ff3_sign_out))
    );

    ///// Enabled capture behavior /////
    // With EN HIGH for two consecutive cycles, output equals previous cycle's Q.
    capture_when_enabled_two_cycles: assert property (
        @(posedge CLK) disable iff (!EN) ($past(EN) && EN) |-> (d_ff3_sign_out == $past(Q))
    );

    // With EN HIGH for two consecutive cycles and Q unchanged, output remains unchanged.
    hold_when_input_stable_and_enabled: assert property (
        @(posedge CLK) disable iff (!EN) ($past(EN) && EN && (Q == $past(Q))) |-> (d_ff3_sign_out == $past(d_ff3_sign_out))
    );

    // With EN HIGH for two consecutive cycles and Q changed last cycle, output changes accordingly.
    reflect_input_change_when_enabled: assert property (
        @(posedge CLK) disable iff (!EN) ($past(EN) && EN && (Q != $past(Q))) |-> (d_ff3_sign_out != $past(d_ff3_sign_out))
    );
endmodule

