module my_module(
    input in1,
    input in2,
    input in3,
    input in4,
    input in5,
    output out1
);

    wire and_out;
    wire or_out;

    assign and_out = in1 & in2 & in3 & in4;
    assign or_out = and_out | in5;
    assign out1 = or_out;

endmodule

sva:
module my_module_sva (
    input logic clk,
    input logic in1,
    input logic in2,
    input logic in3,
    input logic in4,
    input logic in5,
    input logic out1
);
    // Combinational RTL; no reset/clock in DUT; assertions are sampled on clk.

    // out1 equals (in1 & in2 & in3 & in4) | in5.
    check_out1_equation: assert property (
        @(posedge clk) out1 == ((in1 & in2 & in3 & in4) | in5)
    );

    // in5 high forces out1 high.
    check_in5_forces_out1: assert property (
        @(posedge clk) in5 |-> out1
    );

    // When in5 is low, out1 equals in1&in2&in3&in4.
    check_out1_when_in5_low: assert property (
        @(posedge clk) !in5 |-> (out1 == (in1 & in2 & in3 & in4))
    );

    // All of in1..in4 high implies out1 high.
    check_all_in_high_implies_out1_high: assert property (
        @(posedge clk) (in1 & in2 & in3 & in4) |-> out1
    );

    // With in5 low and any of in1..in4 low, out1 must be low.
    check_any_in_low_with_in5_low_implies_out1_low: assert property (
        @(posedge clk) (!in5 && !(in1 & in2 & in3 & in4)) |-> !out1
    );

    // If inputs are stable, out1 must be stable.
    check_output_stable_when_inputs_stable: assert property (
        @(posedge clk) $stable({in1,in2,in3,in4,in5}) |-> $stable(out1)
    );

    // out1 low implies in5 is low and not(all of in1..in4 are high).
    check_out1_low_implies_inputs: assert property (
        @(posedge clk) !out1 |-> (!in5 && !(in1 & in2 & in3 & in4))
    );

    // If out1 is high while in5 is low, then all of in1..in4 must be high.
    check_out1_high_with_in5_low_implies_all_in_high: assert property (
        @(posedge clk) (out1 && !in5) |-> (in1 && in2 && in3 && in4)
    );
endmodule

module up_counter_sva (
    input logic clk,
    input logic rst,      // active-high, synchronous reset
    input logic en,
    input logic [3:0] count
);
    // Clock: clk (posedge). Reset: rst (active-high, synchronous). Logic: sequential counter with enable.

    // Reset sets count to 0 on the next clock.
    check_reset_sets_zero_next: assert property (
        @(posedge clk) rst |=> (count == 4'd0)
    );

    // While reset is held for 2+ cycles, count reads as 0 each cycle.
    check_reset_keeps_zero_while_held: assert property (
        @(posedge clk) (rst && $past(rst)) |-> (count == 4'd0)
    );

    // When en is low and not in reset, count holds its value.
    check_hold_when_en_low: assert property (
        @(posedge clk) disable iff (rst) (!en) |=> (count == $past(count))
    );

    // When en is high and not in reset, count increments modulo 16.
    check_increment_mod16_when_en_high: assert property (
        @(posedge clk) disable iff (rst) en |=> (count == (($past(count) + 4'd1) & 4'hF))
    );

    // Any count change must be caused by prior en or reset.
    check_change_requires_prev_en_or_rst: assert property (
        @(posedge clk) disable iff (rst) (count != $past(count)) |-> ($past(en) || $past(rst))
    );

    // If prior en was high and not in reset, count changes next cycle.
    check_progress_on_prev_enable: assert property (
        @(posedge clk) disable iff (rst) ($past(en) && !$past(rst)) |-> (count != $past(count))
    );

    // If both rst and en were high last cycle, reset takes priority (count becomes 0).
    check_reset_overrides_enable: assert property (
        @(posedge clk) ($past(rst) && $past(en)) |-> (count == 4'd0)
    );

    // If prior en was high and prior count was 4'hF, next count wraps to 0.
    check_wrap_from_max_on_enable: assert property (
        @(posedge clk) disable iff (rst) ($past(en) && ($past(count) == 4'hF)) |-> (count == 4'd0)
    );
endmodule

