module barrel_shifter (
    input [3:0] A,
    input [1:0] B,
    output reg [3:0] Q
);

always @(*) begin
    case(B)
        2'b00: Q = A;
        2'b01: Q = {A[0], A[3:1]};
        2'b10: Q = {A[1:0], A[3:2]};
        2'b11: Q = {A[2:0], A[3]};
    endcase
end

