module up_counter (
    input clk,
    input reset,
    output reg [3:0] Q
);

always @(posedge clk) begin
    if (reset) begin
        Q <= 4'b0000;
    end else begin
        Q <= Q + 1;
        if (Q == 4'b1111) begin
            Q <= 4'b0000;
        end
    end
end

