module servo
#(
    parameter WIDTH = 16, parameter NUM = 1     ) (
    input clk50Mhz,                   input rst,                        input [(WIDTH*NUM)-1:0] posArray, output reg [NUM-1:0] pwm          );

wire [WIDTH-1:0] posArrayInternal[NUM-1:0];

reg [19:0] counter;

integer i;
genvar j;

generate
begin
    for (j=0; j<NUM; j=j+1) begin
        assign posArrayInternal[j] = posArray[(WIDTH*(j+1)-1):(WIDTH*j)];
    end
end
endgenerate

always @(posedge clk50Mhz) begin
    if (rst) begin
        counter <= 'd0;
        pwm <= 'b0;
    end else begin
        counter <= counter + 1;
        for (i=0; i<NUM; i=i+1) begin
            if (((posArrayInternal[i] << (16-WIDTH)) + 42232) > counter)
                pwm[i] <= 1'b1;
            else
                pwm[i] <= 1'b0;
        end
    end
end

endmodule

sva:
module servo_sva #(
    parameter WIDTH = 16,
    parameter NUM   = 1
) (
    input  logic                     clk50Mhz,
    input  logic                     rst,
    input  logic [(WIDTH*NUM)-1:0]   posArray,
    input  logic [NUM-1:0]           pwm,
    input  logic [19:0]              counter
);

    // Counter must be 0 when synchronous reset is asserted.
    check_reset_counter_zero: assert property (
        @(posedge clk50Mhz) disable iff (1'b0) rst |-> (counter == 20'd0)
    );

    // PWM outputs must be 0 when synchronous reset is asserted.
    check_reset_pwm_zero: assert property (
        @(posedge clk50Mhz) disable iff (1'b0) rst |-> (pwm == {NUM{1'b0}})
    );

    // On the first cycle after reset deasserts, counter increments from 0 to 1.
    check_counter_after_reset: assert property (
        @(posedge clk50Mhz) disable iff (rst) $fell(rst) |-> (counter == 20'd1)
    );

    // Counter increments by 1 every cycle when not in reset (mod 2^20).
    check_counter_increments: assert property (
        @(posedge clk50Mhz) disable iff (rst) counter == ($past(counter) + 20'd1)
    );

    // When previous counter was max, it wraps to 0 on the next cycle.
    check_counter_wrap: assert property (
        @(posedge clk50Mhz) disable iff (rst) ($past(counter) == 20'hFFFFF) |-> (counter == 20'd0)
    );

    genvar i;
    generate
        for (i = 0; i < NUM; i = i + 1) begin : per_channel_checks
            // PWM[i] equals comparator result computed with previous counter value.
            check_pwm_functional_i: assert property (
                @(posedge clk50Mhz) disable iff (rst)
                    pwm[i] ==
                    ( ( (posArray[(WIDTH*(i+1)-1):(WIDTH*i)] << (16-WIDTH)) + 16'd42232 ) > $past(counter) )
            );

            // If comparator is true with previous counter, PWM[i] must be 1 this cycle.
            check_pwm_high_condition_i: assert property (
                @(posedge clk50Mhz) disable iff (rst)
                    ( ( (posArray[(WIDTH*(i+1)-1):(WIDTH*i)] << (16-WIDTH)) + 16'd42232 ) > $past(counter) )
                    |-> pwm[i] == 1'b1
            );

            // If comparator is false with previous counter, PWM[i] must be 0 this cycle.
            check_pwm_low_condition_i: assert property (
                @(posedge clk50Mhz) disable iff (rst)
                    ! ( ( (posArray[(WIDTH*(i+1)-1):(WIDTH*i)] << (16-WIDTH)) + 16'd42232 ) > $past(counter) )
                    |-> pwm[i] == 1'b0
            );

            // On the first non-reset cycle, PWM[i] must be 1 (threshold > 0 always holds).
            check_pwm_after_reset_deassert_i: assert property (
                @(posedge clk50Mhz) disable iff (rst) $fell(rst) |-> (pwm[i] == 1'b1)
            );
        end
    endgenerate

endmodule

rtl:
module top_module (
clk,
up_down,
load,
reset,
A,
B,
EQ,
GT,
LT
);

// Declare the input/output ports
input clk;
input up_down;
input load;
input reset;
input [3:0] A;
input [3:0] B;
output wire EQ;
output wire GT;
output wire LT;

// Declare the internal register and wires
reg [3:0] counter;
wire [3:0] D;
wire [3:0] Q;

// Instantiate the up-down counter module
up_down_counter counter_module (
.clk(clk),
.up_down(up_down),
.load(load),
.reset(reset),
.D(D),
.Q(Q)
);

// Assign the value to D based on load signal
assign D = (load) ? A : Q; // if load is asserted, D takes the value of A, otherwise it takes the value of Q

// Instantiate the magnitude comparator module
magnitude_comparator comparator_module (
.A(Q), // Use the output of the counter as input to the comparator
.B(B),
.EQ(EQ),
.GT(GT),
.LT(LT)
);

endmodule

module up_down_counter (
clk,
up_down,
load,
reset,
D,
Q
);

// Declare the input/output ports
input clk;
input up_down;
input load;
input reset;
input [3:0] D;
output reg [3:0] Q;

// Implement the counter using always block
always @(posedge clk) begin
if (reset) begin
    Q <= 4'b0; // Reset the counter to 0
end else if (load) begin
    Q <= D; // Load the counter with the value of D
end else begin
    if (up_down) begin
        Q <= Q + 1; // Increment the counter if up_down is asserted
    end else begin
        Q <= Q - 1; // Decrement the counter if up_down is deasserted
    end
end
end

endmodule

module magnitude_comparator (
A,
B,
EQ,
GT,
LT
);

// Declare the input/output ports
input [3:0] A;
input [3:0] B;
output wire EQ;
output wire GT;
output wire LT;

// Implement the comparator using continuous assignment
assign EQ = (A == B);
assign GT = (A > B);
assign LT = (A < B);

endmodule

sva:
module top_module_sva (
    input  logic        clk,
    input  logic        up_down,
    input  logic        load,
    input  logic        reset,    // active-HIGH, synchronous
    input  logic [3:0]  A,
    input  logic [3:0]  B,
    input  logic        EQ,
    input  logic        GT,
    input  logic        LT,
    // Internal top-level nets
    input  logic [3:0]  D,
    input  logic [3:0]  Q
);

    ///// Top-level D mux /////
    // D selects A when load=1 else Q.
    check_d_mux_select: assert property (
        @(posedge clk) disable iff (reset) D == (load ? A : Q)
    );

    ///// Up/down counter sequencing /////
    // On reset assertion, Q clears to 0 on next cycle.
    check_q_reset_next: assert property (
        @(posedge clk) reset |=> (Q == 4'b0000)
    );

    // With load asserted (no reset), next Q captures A.
    check_q_load_captures_a: assert property (
        @(posedge clk) disable iff (reset) load |=> (Q == $past(A))
    );

    // With up_down=1 and load=0, next Q increments by 1 (mod 16).
    check_q_increments: assert property (
        @(posedge clk) disable iff (reset) (!load && up_down) |=> (Q == $past(Q) + 4'd1)
    );

    // With up_down=0 and load=0, next Q decrements by 1 (mod 16).
    check_q_decrements: assert property (
        @(posedge clk) disable iff (reset) (!load && !up_down) |=> (Q == $past(Q) - 4'd1)
    );

    // Increment wraps from 15 to 0.
    check_q_inc_wrap: assert property (
        @(posedge clk) disable iff (reset) (!load && up_down && ($past(Q) == 4'hF)) |=> (Q == 4'h0)
    );

    // Decrement wraps from 0 to 15.
    check_q_dec_wrap: assert property (
        @(posedge clk) disable iff (reset) (!load && !up_down && ($past(Q) == 4'h0)) |=> (Q == 4'hF)
    );

    ///// Comparator correctness /////
    // EQ reflects (Q == B).
    check_cmp_eq: assert property (
        @(posedge clk) disable iff (reset) (EQ == (Q == B))
    );

    // GT reflects (Q > B).
    check_cmp_gt: assert property (
        @(posedge clk) disable iff (reset) (GT == (Q > B))
    );

    // LT reflects (Q < B).
    check_cmp_lt: assert property (
        @(posedge clk) disable iff (reset) (LT == (Q < B))
    );

    // Exactly one of EQ/GT/LT is HIGH.
    check_cmp_onehot: assert property (
        @(posedge clk) disable iff (reset) $onehot({EQ, GT, LT})
    );

    // After reset, comparator reflects comparison of zero vs B on next cycle.
    check_cmp_after_reset_zero: assert property (
        @(posedge clk) reset |=> (EQ == (4'd0 == B)) && (GT == 1'b0) && (LT == (4'd0 < B))
    );

endmodule

