    input logic d,
    input logic en,
    input logic q
);
    // Clock: clk (posedge), Reset: rst active-low asynchronous, Sequential DFF with enable.

    // While reset is held LOW across consecutive cycles, q must be 0.
    check_q_zero_while_reset_low: assert property (
        @(posedge clk) (!rst && $past(!rst)) |-> (q == 1'b0)
    );

    // While reset remains LOW across consecutive cycles, q is stable.
    check_q_stable_while_reset_low: assert property (
        @(posedge clk) (!rst && $past(!rst)) |-> (q == $past(q))
    );

    // On reset deassertion (0->1), q is 0 at that clock edge.
    check_q_zero_on_reset_deassert: assert property (
        @(posedge clk) $rose(rst) |-> (q == 1'b0)
    );

    // With enable LOW in the previous cycle and not in reset now, q holds or is 0 if an async reset occurred mid-cycle.
    check_hold_when_en_low_or_reset_midcycle: assert property (
        @(posedge clk) disable iff (!rst) !$past(en) |-> (q == $past(q) || q == 1'b0)
    );

    // With enable HIGH in the previous cycle and not in reset now, q captures previous d or is 0 if an async reset occurred mid-cycle.
    check_capture_when_en_high_or_reset_midcycle: assert property (
        @(posedge clk) disable iff (!rst) $past(en) |-> (q == $past(d) || q == 1'b0)
    );

    // Immediately after reset deassertion with enable HIGH, next cycle q equals this cycle's d if still out of reset.
    check_capture_after_reset_deassert_with_en: assert property (
        @(posedge clk) ($rose(rst) && en) |=> ( rst ? (q == $past(d)) : 1'b1 )
    );
endmodule

module shift_register_sva (
    input logic clk,
    input logic [3:0] IN,
    input logic PL,
    input logic SL,
    input logic SR,
    input logic [3:0] q
);
    // On PL, next q equals IN (highest priority).
    check_parallel_load: assert property (
        @(posedge clk) disable iff ($initstate)
            $past(PL) |-> (q == $past(IN))
    );

    // On SL without PL, next q is rotate-left by 1.
    check_shift_left_rotate: assert property (
        @(posedge clk) disable iff ($initstate)
            (!$past(PL) && $past(SL)) |-> (q == { $past(q[2:0]), $past(q[3]) })
    );

    // On SR without PL or SL, next q is rotate-right by 1.
    check_shift_right_rotate: assert property (
        @(posedge clk) disable iff ($initstate)
            (!$past(PL) && !$past(SL) && $past(SR)) |-> (q == { $past(q[0]), $past(q[3:1]) })
    );

    // With no control asserted, q holds its previous value.
    check_hold_when_idle: assert property (
        @(posedge clk) disable iff ($initstate)
            (!$past(PL) && !$past(SL) && !$past(SR)) |-> (q == $past(q))
    );

    // q changes only if at least one control was asserted.
    check_q_change_requires_enable: assert property (
        @(posedge clk) disable iff ($initstate)
            $changed(q) |-> $past(PL || SL || SR)
    );
endmodule

rtl:
module control_unit(
    input [1:0] ctrl,
    input [3:0] data_in,
    input load,
    input clk,
    output reg [3:0] data_out,
    output reg valid
);

reg [3:0] reg_data;

always @(posedge clk) begin
    if (load) begin
        reg_data <= data_in;
    end else begin
        case(ctrl)
            2'b00: begin
                data_out <= reg_data;
                valid <= 1'b1;
            end
            2'b01: begin
                data_out <= ~reg_data;
                valid <= 1'b1;
            end
            2'b10: begin
                data_out <= data_in;
                valid <= 1'b1;
            end
            2'b11: begin
                data_out <= ~data_in;
                valid <= 1'b1;
            end
            default: begin
                data_out <= 4'b0;
                valid <= 1'b0;
            end
        endcase
    end
end

initial begin
    reg_data = 4'b0;
end

endmodule

sva:
module control_unit_sva (
    input logic [1:0] ctrl,
    input logic [3:0] data_in,
    input logic load,
    input logic clk,
    input logic [3:0] data_out,
    input logic valid,
    input logic [3:0] reg_data
);
    // During load, outputs hold their previous values.
    hold_outputs_during_load: assert property (
        @(posedge clk) ($past(1'b1) && load) |=> (data_out == $past(data_out)) && (valid == $past(valid))
    );

    // When load is asserted, reg_data captures data_in on the next cycle.
    load_updates_reg_data: assert property (
        @(posedge clk) load |=> (reg_data == $past(data_in))
    );

    // When load is deasserted, reg_data holds its value.
    hold_reg_data_when_not_load: assert property (
        @(posedge clk) !load |=> (reg_data == $past(reg_data))
    );

    // When !load and ctrl==00, next data_out equals reg_data and valid is 1.
    compute_passthrough_reg_data: assert property (
        @(posedge clk) (!load && (ctrl == 2'b00)) |=> ((data_out == $past(reg_data)) && (valid == 1'b1))
    );

    // When !load and ctrl==01, next data_out equals bitwise ~reg_data and valid is 1.
    compute_invert_reg_data: assert property (
        @(posedge clk) (!load && (ctrl == 2'b01)) |=> ((data_out == ~$past(reg_data)) && (valid == 1'b1))
    );

    // When !load and ctrl==10, next data_out equals data_in and valid is 1.
    compute_passthrough_data_in: assert property (
        @(posedge clk) (!load && (ctrl == 2'b10)) |=> ((data_out == $past(data_in)) && (valid == 1'b1))
    );

    // When !load and ctrl==11, next data_out equals bitwise ~data_in and valid is 1.
    compute_invert_data_in: assert property (
        @(posedge clk) (!load && (ctrl == 2'b11)) |=> ((data_out == ~$past(data_in)) && (valid == 1'b1))
    );

    // Any cycle with !load drives valid high on the next cycle.
    valid_high_on_operation: assert property (
        @(posedge clk) !load |=> (valid == 1'b1)
    );

    // load followed by ctrl==00 yields data_out equal to the loaded reg value.
    load_then_ctrl00_uses_loaded_data: assert property (
        @(posedge clk) (load ##1 (!load && (ctrl == 2'b00))) |=> (data_out == $past(data_in, 2)) && (valid == 1'b1)
    );

    // load followed by ctrl==01 yields data_out equal to ~loaded reg value.
    load_then_ctrl01_uses_inverted_loaded_data: assert property (
        @(posedge clk) (load ##1 (!load && (ctrl == 2'b01))) |=> (data_out == ~$past(data_in, 2)) && (valid == 1'b1)
    );

    // load followed by ctrl==10 yields data_out equal to next-cycle data_in.
    load_then_ctrl10_uses_next_data_in: assert property (
        @(posedge clk) (load ##1 (!load && (ctrl == 2'b10))) |=> (data_out == $past(data_in, 1)) && (valid == 1'b1)
    );

    // load followed by ctrl==11 yields data_out equal to ~next-cycle data_in.
    load_then_ctrl11_uses_inverted_next_data_in: assert property (
        @(posedge clk) (load ##1 (!load && (ctrl == 2'b11))) |=> (data_out == ~$past(data_in, 1)) && (valid == 1'b1)
    );
endmodule

rtl:
module top_module(
    input [3:0] in,
    input [2:0] sel,
    output [1:0] out
);

wire [1:0] level1 [0:3];
wire level2 [0:1];
wire level3;
wire level4;
wire level5;

assign level1[0] = {1'b0, in[1]};
assign level1[1] = {1'b0, in[3]};
assign level1[2] = {in[2], in[1]}; // Corrected the bounds of the range
assign level1[3] = {in[3], in[2]}; // Corrected the bounds of the range

priority_encoder pe1(
    .in(level1[0]), 
    .out(level2[0])
);

priority_encoder pe2(
    .in(level1[1]), 
    .out(level2[1])
);

priority_encoder pe3(
    .in(level1[2]), 
    .out(level3)
);

priority_encoder pe4(
    .in(level1[3]), 
    .out(level4)
);

assign level5 = (level2[1] == 1'b1) ? 1'b1 :
             (level2[0] == 1'b1) ? 1'b0 : // Corrected the precedence of operators
             1'b0;

assign out = (sel == 3'b000) ? level1[0] :
             (sel == 3'b001) ? level2[0] :
             (sel == 3'b010) ? level3 :
             (sel == 3'b011) ? level4 :
             (sel == 3'b100) ? level5 : 2'bxx;

endmodule
module priority_encoder(
    input [1:0] in,
    output out
);

assign out = (in[1] == 1'b1) ? 1'b1 :
             (in[0] == 1'b1) ? 1'b0 :
             1'b0;

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic [3:0] in,
    input logic [2:0] sel,
    input logic [1:0] out
);
    ///// Functional mapping checks /////
    // When sel=000, out == {0, in[1]}.
    check_sel000_mapping: assert property (
        @(posedge clk) disable iff (1'b0) (sel == 3'b000) |-> (out == {1'b0, in[1]})
    );
    // When sel=001, out == 2'b00.
    check_sel001_zero: assert property (
        @(posedge clk) disable iff (1'b0) (sel == 3'b001) |-> (out == 2'b00)
    );
    // When sel=010, out == {0, in[2]}.
    check_sel010_mapping: assert property (
        @(posedge clk) disable iff (1'b0) (sel == 3'b010) |-> (out == {1'b0, in[2]})
    );
    // When sel=011, out == {0, in[3]}.
    check_sel011_mapping: assert property (
        @(posedge clk) disable iff (1'b0) (sel == 3'b011) |-> (out == {1'b0, in[3]})
    );
    // When sel=100, out == 2'b00.
    check_sel100_zero: assert property (
        @(posedge clk) disable iff (1'b0) (sel == 3'b100) |-> (out == 2'b00)
    );
    // For valid selects (000..100), MSB of out is always 0.
    check_valid_sel_msb_zero: assert property (
        @(posedge clk) disable iff (1'b0)
        ((sel == 3'b000) || (sel == 3'b001) || (sel == 3'b010) || (sel == 3'b011) || (sel == 3'b100))
        |-> (out[1] == 1'b0)
    );

    ///// Stability with constant select /////
    // With sel=000 held and in[1] stable, out is stable.
    check_stable_sel000_on_in1: assert property (
        @(posedge clk) disable iff (1'b0)
        ($past(sel) == 3'b000 && sel == 3'b000 && $stable(in[1])) |-> $stable(out)
    );
    // With sel=010 held and in[2] stable, out is stable.
    check_stable_sel010_on_in2: assert property (
        @(posedge clk) disable iff (1'b0)
        ($past(sel) == 3'b010 && sel == 3'b010 && $stable(in[2])) |-> $stable(out)
    );
    // With sel=011 held and in[3] stable, out is stable.
    check_stable_sel011_on_in3: assert property (
        @(posedge clk) disable iff (1'b0)
        ($past(sel) == 3'b011 && sel == 3'b011 && $stable(in[3])) |-> $stable(out)
    );
    // With sel=001 held, out remains 2'b00.
    check_stable_sel001_zero: assert property (
        @(posedge clk) disable iff (1'b0)
        ($past(sel) == 3'b001 && sel == 3'b001) |-> (out == 2'b00)
    );
endmodule

