module decoder_2to4 (
    input A,
    input B,
    output reg Y0,
    output reg Y1,
    output reg Y2,
    output reg Y3
);

    always @ (A, B) begin
        Y0 = ~(A | B);
        Y1 = ~(A & B);
        Y2 = ~((~A) & B);
        Y3 = ~(~A | ~B);
    end

endmodule

sva:
module decoder_2to4_sva (
    input logic A,
    input logic B,
    input logic Y0,
    input logic Y1,
    input logic Y2,
    input logic Y3
);
    // Y0 equals ~(A | B)
    check_y0_is_nor_ab: assert property (
        @(posedge A or negedge A or posedge B or negedge B) Y0 == ~(A | B)
    );

    // Y1 equals ~(A & B)
    check_y1_is_nand_ab: assert property (
        @(posedge A or negedge A or posedge B or negedge B) Y1 == ~(A & B)
    );

    // Y2 equals ~((~A) & B)
    check_y2_is_nor_notA_B: assert property (
        @(posedge A or negedge A or posedge B or negedge B) Y2 == ~((~A) & B)
    );

    // Y3 equals ~(~A | ~B)
    check_y3_is_nand_notA_notB: assert property (
        @(posedge A or negedge A or posedge B or negedge B) Y3 == ~(~A | ~B)
    );

    // Y1 is the logical complement of Y3
    check_y1_complements_y3: assert property (
        @(posedge A or negedge A or posedge B or negedge B) Y1 == ~Y3
    );

    // Truth table: A=0, B=0 -> Y0=1, Y1=1, Y2=1, Y3=0
    check_tt_00: assert property (
        @(posedge A or negedge A or posedge B or negedge B) (!A && !B) |=> (Y0 && Y1 && Y2 && !Y3)
    );

    // Truth table: A=0, B=1 -> Y0=0, Y1=1, Y2=0, Y3=0
    check_tt_01: assert property (
        @(posedge A or negedge A or posedge B or negedge B) (!A && B) |=> (!Y0 && Y1 && !Y2 && !Y3)
    );

    // Truth table: A=1, B=0 -> Y0=0, Y1=1, Y2=1, Y3=0
    check_tt_10: assert property (
        @(posedge A or negedge A or posedge B or negedge B) (A && !B) |=> (!Y0 && Y1 && Y2 && !Y3)
    );

    // Truth table: A=1, B=1 -> Y0=0, Y1=0, Y2=1, Y3=1
    check_tt_11: assert property (
        @(posedge A or negedge A or posedge B or negedge B) (A && B) |=> (!Y0 && !Y1 && Y2 && Y3)
    );

    // If Y0 is 1, then Y1 must be 1
    check_y0_implies_y1: assert property (
        @(posedge A or negedge A or posedge B or negedge B) Y0 |=> Y1
    );
endmodule

rtl:
module calculator(
    input clk,
    input [1:0] op,
    input [7:0] a,
    input [7:0] b,
    input reset,
    output reg [7:0] result,
    output reg valid
);

always @(posedge clk) begin
    if (reset) begin
        result <= 8'b0;
        valid <= 1'b0;
    end else begin
        case(op)
            2'b00: begin
                result <= a + b;
                valid <= 1'b1;
            end
            2'b01: begin
                result <= a - b;
                valid <= 1'b1;
            end
            2'b10: begin
                result <= a * b;
                valid <= 1'b1;
            end
            2'b11: begin
                result <= a / b;
                valid <= 1'b1;
            end
            default: begin
                valid <= 1'b0;
            end
        endcase
    end
end

endmodule

sva:
module calculator_sva (
    input logic clk,
    input logic [1:0] op,
    input logic [7:0] a,
    input logic [7:0] b,
    input logic reset,
    input logic [7:0] result,
    input logic valid
);
    // On reset, next-cycle result and valid are cleared.
    reset_clears_result_and_valid: assert property (
        @(posedge clk) reset |=> (result == 8'b0) && (valid == 1'b0)
    );

    // When not in reset, valid is HIGH on the next cycle.
    valid_next_cycle_when_not_reset: assert property (
        @(posedge clk) disable iff (reset) 1'b1 |=> (valid == 1'b1)
    );

    // After two consecutive non-reset cycles, valid must be HIGH.
    valid_stays_high_out_of_reset: assert property (
        @(posedge clk) disable iff (reset) (!reset && $past(!reset)) |-> (valid == 1'b1)
    );

    // ADD: Next-cycle result equals previous a+b (LSB 8) and valid HIGH.
    add_result_correct: assert property (
        @(posedge clk) disable iff (reset)
            (op == 2'b00) |=> ((result == (($past(a) + $past(b)) [7:0])) && (valid == 1'b1))
    );

    // SUB: Next-cycle result equals previous a-b (LSB 8) and valid HIGH.
    sub_result_correct: assert property (
        @(posedge clk) disable iff (reset)
            (op == 2'b01) |=> ((result == (($past(a) - $past(b)) [7:0])) && (valid == 1'b1))
    );

    // MUL: Next-cycle result equals previous a*b (LSB 8) and valid HIGH.
    mul_result_correct: assert property (
        @(posedge clk) disable iff (reset)
            (op == 2'b10) |=> ((result == (($past(a) * $past(b)) [7:0])) && (valid == 1'b1))
    );

    // DIV (b!=0): Next-cycle result equals previous a/b and valid HIGH.
    div_result_correct_when_b_nonzero: assert property (
        @(posedge clk) disable iff (reset)
            ((op == 2'b11) && (b != 8'd0)) |=> ((result == ($past(a) / $past(b))) && (valid == 1'b1))
    );

    // After ADD opcode, valid is HIGH on the next cycle.
    valid_after_add: assert property (
        @(posedge clk) disable iff (reset) (op == 2'b00) |=> (valid == 1'b1)
    );

    // After SUB opcode, valid is HIGH on the next cycle.
    valid_after_sub: assert property (
        @(posedge clk) disable iff (reset) (op == 2'b01) |=> (valid == 1'b1)
    );

    // After MUL opcode, valid is HIGH on the next cycle.
    valid_after_mul: assert property (
        @(posedge clk) disable iff (reset) (op == 2'b10) |=> (valid == 1'b1)
    );
endmodule

module d_ff_en_ce_sva (
    input logic clk,
    input logic en,
    input logic enclk,
    input logic d,
    input logic q
);
    // Q updates with D on the next cycle when both enables are HIGH.
    update_on_enable: assert property (
        @(posedge clk) (en && enclk) |=> (q == $past(d))
    );

    // Q holds its value on the next cycle when at least one enable is LOW.
    hold_when_not_both: assert property (
        @(posedge clk) !(en && enclk) |=> (q == $past(q))
    );

    // Any change on Q must be due to both enables being HIGH in the previous cycle.
    change_requires_prev_enable: assert property (
        @(posedge clk) $changed(q) |-> $past(en && enclk)
    );

    // When Q changes, its new value equals the previous-cycle D.
    change_matches_prev_d: assert property (
        @(posedge clk) $changed(q) |-> (q == $past(d))
    );

    // If EN is LOW, Q must hold its previous value on the next cycle.
    hold_when_en_low: assert property (
        @(posedge clk) !en |=> (q == $past(q))
    );

    // If ENCLK is LOW, Q must hold its previous value on the next cycle.
    hold_when_enclk_low: assert property (
        @(posedge clk) !enclk |=> (q == $past(q))
    );

    // With both enables HIGH and D different from current Q, Q must change next cycle.
    enabled_and_data_diff_causes_change: assert property (
        @(posedge clk) (en && enclk && (d != q)) |=> (q != $past(q))
    );

    // With both enables HIGH and D equal to current Q, Q must not change next cycle.
    enabled_and_data_equal_causes_no_change: assert property (
        @(posedge clk) (en && enclk && (d == q)) |=> (q == $past(q))
    );

    // If both enables were HIGH but Q did not change, then D equaled Q in that cycle.
    no_change_under_enable_means_data_equal: assert property (
        @(posedge clk) ($past(en && enclk) && !$changed(q)) |-> ($past(d) == $past(q))
    );

    // Each cycle, Q equals either its previous value or the previous-cycle D.
    next_state_is_prev_q_or_prev_d: assert property (
        @(posedge clk) (q == $past(q)) || (q == $past(d))
    );
endmodule

rtl:
module top_module(
    input signed [31:0] a,
    input signed [31:0] b,
    output signed [63:0] product
);

    wire signed [15:0] stage1_out;
    wire signed [15:0] stage2_out;
    wire signed [15:0] stage3_out;
    wire signed [15:0] stage4_out;

    // instantiate four 8-bit multiplication modules
    mult8bit mult1(.a(a[7:0]), .b(b[7:0]), .product(stage1_out[15:0]));
    mult8bit mult2(.a(a[15:8]), .b(b[15:8]), .product(stage2_out[15:0]));
    mult8bit mult3(.a(a[23:16]), .b(b[23:16]), .product(stage3_out[15:0]));
    mult8bit mult4(.a(a[31:24]), .b(b[31:24]), .product(stage4_out[15:0]));

    // pipeline structure
    reg signed [15:0] stage1_reg;
    reg signed [15:0] stage2_reg;
    reg signed [15:0] stage3_reg;
    reg signed [15:0] stage4_reg;

    always @(*) begin
        stage1_reg = stage1_out;
    end

    always @(*) begin
        stage2_reg = stage2_out;
    end

    always @(*) begin
        stage3_reg = stage3_out;
    end

    always @(*) begin
        stage4_reg = stage4_out;
    end

    assign product = {stage4_reg, stage3_reg, stage2_reg, stage1_reg};

endmodule
module mult8bit(
    input signed [7:0] a,
    input signed [7:0] b,
    output signed [15:0] product
);

    assign product = a * b;

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic signed [31:0] a,
    input logic signed [31:0] b,
    input logic signed [63:0] product
);
    // Notes: No clock/reset in RTL; purely combinational. clk here is a sampling clock for SVA.

    // Full product equals concatenation of four signed 8x8 products.
    check_full_concat: assert property (
        @(posedge clk) product == {
            ($signed(a[31:24]) * $signed(b[31:24])),
            ($signed(a[23:16]) * $signed(b[23:16])),
            ($signed(a[15:8])  * $signed(b[15:8])),
            ($signed(a[7:0])   * $signed(b[7:0]))
        }
    );

    // Low 16 bits equal signed multiply of low bytes.
    check_seg0_mapping: assert property (
        @(posedge clk) product[15:0] == ($signed(a[7:0]) * $signed(b[7:0]))
    );

    // Bits [31:16] equal signed multiply of second byte.
    check_seg1_mapping: assert property (
        @(posedge clk) product[31:16] == ($signed(a[15:8]) * $signed(b[15:8]))
    );

    // Bits [47:32] equal signed multiply of third byte.
    check_seg2_mapping: assert property (
        @(posedge clk) product[47:32] == ($signed(a[23:16]) * $signed(b[23:16]))
    );

    // High 16 bits equal signed multiply of high bytes.
    check_seg3_mapping: assert property (
        @(posedge clk) product[63:48] == ($signed(a[31:24]) * $signed(b[31:24]))
    );

    // If low bytes of a and b are stable, low 16 bits of product are stable.
    check_seg0_stable_when_inputs_stable: assert property (
        @(posedge clk) $stable(a[7:0]) && $stable(b[7:0]) |-> $stable(product[15:0])
    );

    // If second bytes of a and b are stable, bits [31:16] of product are stable.
    check_seg1_stable_when_inputs_stable: assert property (
        @(posedge clk) $stable(a[15:8]) && $stable(b[15:8]) |-> $stable(product[31:16])
    );

    // If third bytes of a and b are stable, bits [47:32] of product are stable.
    check_seg2_stable_when_inputs_stable: assert property (
        @(posedge clk) $stable(a[23:16]) && $stable(b[23:16]) |-> $stable(product[47:32])
    );

    // If high bytes of a and b are stable, high 16 bits of product are stable.
    check_seg3_stable_when_inputs_stable: assert property (
        @(posedge clk) $stable(a[31:24]) && $stable(b[31:24]) |-> $stable(product[63:48])
    );

    // If either operand is zero, the entire product bus is zero.
    check_zero_operand_zero_product: assert property (
        @(posedge clk) ((a == 32'sd0) || (b == 32'sd0)) |-> (product == 64'sd0)
    );

endmodule

rtl:
module DFFE (
    output reg Q,
    input C, E, D
);

    // Initialize flip-flop
    always @ (posedge C) begin
        if (E) begin
            Q <= D;
        end
    end

    // Timing specifications for ICE40_HX
    `ifdef ICE40_HX
    specify
        $setup(D, posedge C &&& E, 470 - 449);
        $setup(E, posedge C, 0);
        if (E) (posedge C => (Q : D)) = 540;
    endspecify
    `endif

    // Timing specifications for ICE40_LP
    `ifdef ICE40_LP
    specify
        $setup(D, posedge C &&& E, 693 - 662);
        $setup(E, posedge C, 0);
        if (E) (posedge C => (Q : D)) = 796;
    endspecify
    `endif

    // Timing specifications for ICE40_U
    `ifdef ICE40_U
    specify
        $setup(D, posedge C &&& E, 0); // Negative times not currently supported
        $setup(E, posedge C, 0);
        if (E) (posedge C => (Q : D)) = 1391;
    endspecify
    `endif

endmodule

sva:
module DFFE_sva (
    input logic Q,
    input logic C,
    input logic E,
    input logic D
);
    // When enabled, next Q equals prior D.
    check_q_updates_on_enable: assert property (
        @(posedge C) E |=> (Q == $past(D))
    );

    // When disabled, next Q holds its previous value.
    check_q_holds_when_disabled: assert property (
        @(posedge C) !E |=> (Q == $past(Q))
    );

    // Any change in Q must be due to prior enable and equal prior D.
    check_q_change_requires_enable_and_matches_d: assert property (
        @(posedge C) $changed(Q) |-> ($past(E) && (Q == $past(D)))
    );

    // If enabled and D equals current Q, no change next cycle.
    check_no_change_when_enable_same_data: assert property (
        @(posedge C) (E && (D == Q)) |=> (Q == $past(Q))
    );

    // If enabled and D differs from current Q, Q must change next cycle.
    check_change_when_enable_diff_data: assert property (
        @(posedge C) (E && (D != Q)) |=> $changed(Q)
    );

    // Next Q equals mux of prior D and prior Q based on prior E.
    check_next_q_mux_of_e: assert property (
        @(posedge C) 1'b1 |=> (Q == ($past(E) ? $past(D) : $past(Q)))
    );
endmodule

