    input  logic [N-1:0]      count
);

    // When reset is asserted low at a clock edge, count is 0.
    reset_forces_zero_now: assert property (
        @(posedge clk) (rst == 1'b0) |-> (count == {N{1'b0}})
    );

    // On reset falling edge, count is 0 at that cycle.
    reset_fall_clears_counter: assert property (
        @(posedge clk) $fell(rst) |-> (count == {N{1'b0}})
    );

    // On reset rising edge, counter starts at 1.
    reset_rise_starts_at_one: assert property (
        @(posedge clk) disable iff (!rst) $rose(rst) |-> (count == {{(N-1){1'b0}},1'b1})
    );

    // When rst is HIGH in consecutive samples, counter either increments by 1 or equals 1 if reset pulsed low between edges.
    increment_or_one_when_running: assert property (
        @(posedge clk) disable iff (!rst) $past(rst) |-> ((count == $past(count) + 1'b1) || (count == {{(N-1){1'b0}},1'b1}))
    );

    // While held in reset across consecutive samples, count stays at 0.
    count_stable_in_reset: assert property (
        @(posedge clk) ($past(rst) == 1'b0 && rst == 1'b0) |-> (count == {N{1'b0}} && $past(count) == {N{1'b0}})
    );

    // If running and counter reads 0, previous sample was all 1's (wrap-around).
    wraparound_implies_prev_all_ones: assert property (
        @(posedge clk) disable iff (!rst) ($past(rst) && (count == {N{1'b0}})) |-> ($past(count) == {N{1'b1}})
    );

    // On reset rising edge, the previous sampled count was 0.
    reset_rise_prev_count_zero: assert property (
        @(posedge clk) disable iff (!rst) $rose(rst) |-> ($past(count) == {N{1'b0}})
    );

endmodule

rtl:
module bit_summing_circuit ( input [15:0] in, output reg [3:0] out );

    always @* begin
        out = {in[14], in[12], in[10], in[8]} + {in[7], in[5], in[3], in[1]};
    end

endmodule

module ring_counter ( input clk, input reset, output reg [2:0] out );

    always @(posedge clk) begin
        if (reset) begin
            out <= 3'b000;
        end else begin
            out <= {out[1:0], out[2]};
        end
    end

endmodule

module final_output ( input [3:0] bit_sum, input [2:0] ring_count, output reg [3:0] out );

    always @* begin
        out = bit_sum + ring_count;
    end

endmodule

module top_module ( input clk, input [15:0] in, output reg [3:0] q );

    wire [3:0] bit_sum;
    wire [2:0] ring_count;
    wire [3:0] final_out;

    bit_summing_circuit bit_sum_circuit ( .in(in), .out(bit_sum) );
    ring_counter ring_counter_inst ( .clk(clk), .reset(q[0]), .out(ring_count) );
    final_output final_out_inst ( .bit_sum(bit_sum), .ring_count(ring_count), .out(final_out) );

    always @* begin
        q <= final_out;
    end

endmodule

sva:
module ring_counter_sva (
    input logic clk,
    input logic reset,
    input logic [2:0] out
);
    // On previous-cycle reset, out must be zero now.
    check_reset_clears_next: assert property (
        @(posedge clk) disable iff (reset) $past(reset) |-> (out == 3'b000)
    );

    // When not in reset, current out equals left-rotate of prior out.
    check_rotate_update: assert property (
        @(posedge clk) disable iff (reset) !reset |-> (out == {$past(out[1:0]), $past(out[2])})
    );

    // When not in reset on consecutive cycles, bit0 equals prior bit2.
    check_rotate_bit0: assert property (
        @(posedge clk) disable iff (reset) $past(!reset) && !reset |-> (out[0] == $past(out[2]))
    );

    // When not in reset on consecutive cycles, bit1 equals prior bit0.
    check_rotate_bit1: assert property (
        @(posedge clk) disable iff (reset) $past(!reset) && !reset |-> (out[1] == $past(out[0]))
    );

    // When not in reset on consecutive cycles, bit2 equals prior bit1.
    check_rotate_bit2: assert property (
        @(posedge clk) disable iff (reset) $past(!reset) && !reset |-> (out[2] == $past(out[1]))
    );

    // Zero value persists when not in reset (rotate(0) == 0).
    check_zero_sticks_no_reset: assert property (
        @(posedge clk) disable iff (reset) $past(!reset) && !reset && ($past(out) == 3'b000) |-> (out == 3'b000)
    );

    // After three cycles without reset, out returns to its value three cycles ago.
    check_three_cycle_period: assert property (
        @(posedge clk) disable iff (reset) !reset && $past(!reset) && $past(!reset,2) |-> (out == $past(out,3))
    );

    // After two cycles without reset, out equals out from two cycles ago rotated left by 2.
    check_two_step_rotate: assert property (
        @(posedge clk) disable iff (reset) !reset && $past(!reset) |-> (out == { $past(out[0],2), $past(out[2],2), $past(out[1],2) })
    );

    // 111 is invariant under rotation when not in reset.
    check_rotate_111_stable: assert property (
        @(posedge clk) disable iff (reset) $past(!reset) && !reset && ($past(out) == 3'b111) |-> (out == 3'b111)
    );

    // Specific rotation example: 101 rotates to 011 when not in reset.
    check_rotate_101_to_011: assert property (
        @(posedge clk) disable iff (reset) $past(!reset) && !reset && ($past(out) == 3'b101) |-> (out == 3'b011)
    );
endmodule

rtl:
module xnor_xor (
  input [2:0] in1,
  input [2:0] in2,
  input [1:0] in3,
  output out1,
  output out2
);

  wire [2:0] xnor_out;
  assign xnor_out = ~(in1 ^ in2);

  assign out1 = xnor_out[2] & xnor_out[1] & xnor_out[0];
  assign out2 = out1 ^ in3[1];

endmodule

sva:
module xnor_xor_sva (
    input logic CLK,            // External clock for property sampling (DUT has no clock/reset)
    input logic [2:0] in1,
    input logic [2:0] in2,
    input logic [1:0] in3,
    input logic out1,
    input logic out2
);
    // out1 equals AND of XNORs of in1 and in2
    check_out1_definition: assert property (
        @(posedge CLK) out1 == (&(~(in1 ^ in2)))
    );

    // out2 equals out1 XOR in3[1]
    check_out2_definition: assert property (
        @(posedge CLK) out2 == (out1 ^ in3[1])
    );

    // If LSBs differ, out1 must be 0
    check_out1_zero_if_bit0_diff: assert property (
        @(posedge CLK) (in1[0] ^ in2[0]) |-> (out1 == 1'b0)
    );

    // If mid bits differ, out1 must be 0
    check_out1_zero_if_bit1_diff: assert property (
        @(posedge CLK) (in1[1] ^ in2[1]) |-> (out1 == 1'b0)
    );

    // If MSBs differ, out1 must be 0
    check_out1_zero_if_bit2_diff: assert property (
        @(posedge CLK) (in1[2] ^ in2[2]) |-> (out1 == 1'b0)
    );

    // If all bits match, out1 must be 1
    check_out1_one_if_all_equal: assert property (
        @(posedge CLK) (~(in1[0] ^ in2[0]) && ~(in1[1] ^ in2[1]) && ~(in1[2] ^ in2[2])) |-> (out1 == 1'b1)
    );

    // When out1 is 0, out2 equals in3[1]
    check_out2_when_out1_zero: assert property (
        @(posedge CLK) (!out1) |-> (out2 == in3[1])
    );

    // When out1 is 1, out2 equals NOT in3[1]
    check_out2_when_out1_one: assert property (
        @(posedge CLK) (out1) |-> (out2 == ~in3[1])
    );

    // Changes on in3[0] do not affect out1 if in1/in2 are stable
    check_out1_independent_of_in3_0: assert property (
        @(posedge CLK) ($changed(in3[0]) && $stable(in1) && $stable(in2)) |-> $stable(out1)
    );

    // Changes on in3[0] do not affect out2 if in1/in2/in3[1] are stable
    check_out2_independent_of_in3_0: assert property (
        @(posedge CLK) ($changed(in3[0]) && $stable(in1) && $stable(in2) && $stable(in3[1])) |-> $stable(out2)
    );

    // Toggling in3[1] toggles out2 when in1/in2 are stable
    check_out2_toggles_with_in3_1: assert property (
        @(posedge CLK) ($changed(in3[1]) && $stable(in1) && $stable(in2)) |-> $changed(out2)
    );
endmodule

rtl:
module Add_Subt ( clk, rst, load_i, Add_Sub_op_i, Data_A_i, PreData_B_i, 
        Data_Result_o, FSM_C_o);
  input [25:0] Data_A_i;
  input [25:0] PreData_B_i;
  output [25:0] Data_Result_o;
  input clk, rst, load_i, Add_Sub_op_i;
  output FSM_C_o;

  wire   [26:0] S_to_D;

  // Perform addition or subtraction based on Add_Sub_op_i
  assign S_to_D = (Add_Sub_op_i) ? (Data_A_i - PreData_B_i) : (Data_A_i + PreData_B_i);

  // Store the result of the addition or subtraction in Data_Result_o
  RegisterAdd_W26 Add_Subt_Result ( .clk(clk), .rst(rst), .load(load_i), .D(
        S_to_D[25:0]), .Q(Data_Result_o) );

  // Detect overflow and set FSM_C_o high if overflow occurs
  RegisterAdd_W1 Add_overflow_Result ( .clk(clk), .rst(rst), .load(load_i), 
        .D(S_to_D[26]), .Q(FSM_C_o) );

endmodule
module RegisterAdd_W26 ( clk, rst, load, D, Q );
  input                   clk, rst, load;
  input  [25:0]           D;
  output [25:0]           Q;
  reg    [25:0]           Q;
  always@(posedge clk)
    if (rst)
      Q <= 0;
    else if (load)
      Q <= D;
endmodule
module RegisterAdd_W1 ( clk, rst, load, D, Q );
  input                   clk, rst, load;
  input                    D;
  output reg               Q;
  always@(posedge clk)
    if (rst)
      Q <= 0;
    else if (load)
      Q <= D;
endmodule

sva:
module Add_Subt_sva (
    input logic        clk,
    input logic        rst,          // active-high synchronous reset
    input logic        load_i,
    input logic        Add_Sub_op_i, // 1: subtract, 0: add
    input logic [25:0] Data_A_i,
    input logic [25:0] PreData_B_i,
    input logic [25:0] Data_Result_o,
    input logic        FSM_C_o
);
    // One cycle after reset was asserted, outputs must be zero.
    reset_clears_outputs_next: assert property (
        @(posedge clk) disable iff (rst) $past(rst) |-> (Data_Result_o == 26'd0) && (FSM_C_o == 1'b0)
    );

    // If both reset and load were high, reset has priority and outputs go to zero next cycle.
    reset_has_priority_over_load: assert property (
        @(posedge clk) disable iff (rst) $past(rst && load_i) |-> (Data_Result_o == 26'd0) && (FSM_C_o == 1'b0)
    );

    // With load and Add_Sub_op_i==0, next-cycle outputs equal 27-bit sum of inputs.
    load_updates_sum_next: assert property (
        @(posedge clk) disable iff (rst)
            (load_i && !Add_Sub_op_i)
            |=> ({FSM_C_o, Data_Result_o} == ({1'b0, $past(Data_A_i)} + {1'b0, $past(PreData_B_i)}))
    );

    // With load and Add_Sub_op_i==1, next-cycle outputs equal 27-bit difference of inputs.
    load_updates_sub_next: assert property (
        @(posedge clk) disable iff (rst)
            (load_i && Add_Sub_op_i)
            |=> ({FSM_C_o, Data_Result_o} == ({1'b0, $past(Data_A_i)} - {1'b0, $past(PreData_B_i)}))
    );

    // When load is low, outputs hold their previous values.
    hold_without_load: assert property (
        @(posedge clk) disable iff (rst)
            (!load_i) |=> ({FSM_C_o, Data_Result_o} == $past({FSM_C_o, Data_Result_o}))
    );

    // Outputs may change only on cycles following a load (ignoring reset cycles).
    change_only_after_load: assert property (
        @(posedge clk) disable iff (rst)
            $changed({FSM_C_o, Data_Result_o}) |-> $past(load_i)
    );

    // On load with addition, overflow flag equals MSB of the 27-bit sum next cycle.
    fsm_c_matches_carry_on_sum: assert property (
        @(posedge clk) disable iff (rst)
            (load_i && !Add_Sub_op_i)
            |=> (FSM_C_o == (({1'b0, $past(Data_A_i)} + {1'b0, $past(PreData_B_i)})[26]))
    );

    // On load with subtraction, overflow flag equals MSB of the 27-bit difference next cycle.
    fsm_c_matches_borrow_on_sub: assert property (
        @(posedge clk) disable iff (rst)
            (load_i && Add_Sub_op_i)
            |=> (FSM_C_o == (({1'b0, $past(Data_A_i)} - {1'b0, $past(PreData_B_i)})[26]))
    );
endmodule

rtl:
module mux32_2 ( IN0, IN1, CTRL, OUT1 );
  input [31:0] IN0;
  input [31:0] IN1;
  output [31:0] OUT1;
  input CTRL;

  wire [0:0] mux_outs[31:0];

  // Instantiate 32 individual 2:1 multiplexers
  genvar i;
  generate
    for (i = 0; i < 32; i = i + 1) begin : mux_loop
      MUX2 U ( .A(IN0[i]), .B(IN1[i]), .S(CTRL), .Z(mux_outs[i]) );
    end
  endgenerate

  // Combine the outputs of the individual multiplexers to form the final output
  assign OUT1 = {mux_outs[31], mux_outs[30], mux_outs[29], mux_outs[28], mux_outs[27], mux_outs[26], mux_outs[25], mux_outs[24], mux_outs[23], mux_outs[22], mux_outs[21], mux_outs[20], mux_outs[19], mux_outs[18], mux_outs[17], mux_outs[16], mux_outs[15], mux_outs[14], mux_outs[13], mux_outs[12], mux_outs[11], mux_outs[10], mux_outs[9], mux_outs[8], mux_outs[7], mux_outs[6], mux_outs[5], mux_outs[4], mux_outs[3], mux_outs[2], mux_outs[1], mux_outs[0] };

endmodule
module MUX2 (A, B, S, Z);
  input A, B, S;
  output Z;

  assign Z = (S) ? B : A;

endmodule

sva:
module mux32_2_sva (
    input logic CLK,
    input logic [31:0] IN0,
    input logic [31:0] IN1,
    input logic CTRL,
    input logic [31:0] OUT1
);
    // When CTRL is 0, OUT1 mirrors IN0.
    check_select_ctrl0_vector: assert property (
        @(posedge CLK) (CTRL == 1'b0) |-> (OUT1 == IN0)
    );

    // When CTRL is 1, OUT1 mirrors IN1.
    check_select_ctrl1_vector: assert property (
        @(posedge CLK) (CTRL == 1'b1) |-> (OUT1 == IN1)
    );

    // Rising CTRL selects IN1 immediately.
    check_ctrl_rise_selects_IN1: assert property (
        @(posedge CLK) $rose(CTRL) |-> (OUT1 == IN1)
    );

    // Falling CTRL selects IN0 immediately.
    check_ctrl_fall_selects_IN0: assert property (
        @(posedge CLK) $fell(CTRL) |-> (OUT1 == IN0)
    );

    // OUT1 always equals either IN0 or IN1.
    check_output_is_one_of_inputs: assert property (
        @(posedge CLK) (OUT1 == IN0) || (OUT1 == IN1)
    );

    // Boolean mux identity: OUT1 == (CTRL ? IN1 : IN0).
    check_mux_boolean_equivalence: assert property (
        @(posedge CLK) OUT1 == (({32{CTRL}} & IN1) | ({32{~CTRL}} & IN0))
    );

    // If inputs are equal, OUT1 matches them.
    check_input_equality_passthrough: assert property (
        @(posedge CLK) (IN0 == IN1) |-> (OUT1 == IN0)
    );

    // With CTRL stable low and IN0 stable, OUT1 is stable.
    check_stability_when_ctrl0_in0_stable: assert property (
        @(posedge CLK) (CTRL == 1'b0) && $stable(CTRL) && $stable(IN0) |-> $stable(OUT1)
    );

    // With CTRL stable high and IN1 stable, OUT1 is stable.
    check_stability_when_ctrl1_in1_stable: assert property (
        @(posedge CLK) (CTRL == 1'b1) && $stable(CTRL) && $stable(IN1) |-> $stable(OUT1)
    );

    // If CTRL low and IN0 changes, OUT1 changes.
    check_out_changes_if_in0_changes_when_ctrl0: assert property (
        @(posedge CLK) (CTRL == 1'b0) && $stable(CTRL) && $changed(IN0) |-> $changed(OUT1)
    );

    // If CTRL high and IN1 changes, OUT1 changes.
    check_out_changes_if_in1_changes_when_ctrl1: assert property (
        @(posedge CLK) (CTRL == 1'b1) && $stable(CTRL) && $changed(IN1) |-> $changed(OUT1)
    );

    // With both inputs stable, any OUT1 change implies CTRL changed.
    check_ctrl_is_only_cause_of_change_when_inputs_stable: assert property (
        @(posedge CLK) $stable(IN0) && $stable(IN1) && $changed(OUT1) |-> $changed(CTRL)
    );
endmodule

module IFID_Stage_sva (
    input logic clock,
    input logic reset,
    input logic IF_Flush,
    input logic IF_Stall,
    input logic ID_Stall,
    input logic [31:0] IF_Instruction,
    input logic [31:0] IF_PCAdd4,
    input logic [31:0] IF_PC,
    input logic IF_IsBDS,
    input logic [31:0] ID_Instruction,
    input logic [31:0] ID_PCAdd4,
    input logic [31:0] ID_RestartPC,
    input logic ID_IsBDS,
    input logic ID_IsFlushed,
    input logic [31:0] vote_ID_Instruction,
    input logic [31:0] vote_ID_PCAdd4,
    input logic [31:0] vote_ID_RestartPC,
    input logic vote_ID_IsBDS,
    input logic vote_ID_IsFlushed
);
    ///// Clocks/Resets /////
    // On reset, next cycle all vote_* outputs are cleared to 0.
    reset_clears_all: assert property (
        @(posedge clock) reset |-> ##1 (vote_ID_Instruction == 32'b0) && (vote_ID_PCAdd4 == 32'b0) && (vote_ID_RestartPC == 32'b0) && (vote_ID_IsBDS == 1'b0) && (vote_ID_IsFlushed == 1'b0)
    );

    ///// ID_Stall forwarding rules /////
    // With ID_Stall, next cycle vote_ID_Instruction comes from ID_Instruction.
    stall_forwards_instruction_from_ID: assert property (
        @(posedge clock) disable iff (reset) ID_Stall |-> ##1 (vote_ID_Instruction == $past(ID_Instruction))
    );
    // With ID_Stall, next cycle vote_ID_PCAdd4 comes from ID_PCAdd4.
    stall_forwards_pcadd4_from_ID: assert property (
        @(posedge clock) disable iff (reset) ID_Stall |-> ##1 (vote_ID_PCAdd4 == $past(ID_PCAdd4))
    );
    // With ID_Stall, next cycle vote_ID_IsBDS comes from ID_IsBDS.
    stall_forwards_isbds_from_ID: assert property (
        @(posedge clock) disable iff (reset) ID_Stall |-> ##1 (vote_ID_IsBDS == $past(ID_IsBDS))
    );
    // With ID_Stall, next cycle vote_ID_IsFlushed comes from ID_IsFlushed.
    stall_forwards_isflushed_from_ID: assert property (
        @(posedge clock) disable iff (reset) ID_Stall |-> ##1 (vote_ID_IsFlushed == $past(ID_IsFlushed))
    );
    // With ID_Stall, next cycle vote_ID_RestartPC comes from ID_RestartPC.
    stall_forwards_restartpc_from_ID: assert property (
        @(posedge clock) disable iff (reset) ID_Stall |-> ##1 (vote_ID_RestartPC == $past(ID_RestartPC))
    );

    ///// Non-stall datapath rules /////
    // Without ID_Stall and without IF_Stall/IF_Flush, next cycle instruction comes from IF_Instruction.
    nonstall_instruction_from_IF: assert property (
        @(posedge clock) disable iff (reset) (!ID_Stall && !(IF_Stall || IF_Flush)) |-> ##1 (vote_ID_Instruction == $past(IF_Instruction))
    );
    // Without ID_Stall and with IF_Stall or IF_Flush, next cycle instruction is zeroed.
    nonstall_instruction_zero_on_ifhold_or_flush: assert property (
        @(posedge clock) disable iff (reset) (!ID_Stall && (IF_Stall || IF_Flush)) |-> ##1 (vote_ID_Instruction == 32'b0)
    );
    // Without ID_Stall, next cycle PCAdd4 comes directly from IF_PCAdd4.
    nonstall_pcadd4_from_IF: assert property (
        @(posedge clock) disable iff (reset) (!ID_Stall) |-> ##1 (vote_ID_PCAdd4 == $past(IF_PCAdd4))
    );
    // Without ID_Stall, next cycle IsBDS comes directly from IF_IsBDS.
    nonstall_isbds_from_IF: assert property (
        @(posedge clock) disable iff (reset) (!ID_Stall) |-> ##1 (vote_ID_IsBDS == $past(IF_IsBDS))
    );
    // Without ID_Stall, next cycle IsFlushed comes directly from IF_Flush.
    nonstall_isflushed_from_IF: assert property (
        @(posedge clock) disable iff (reset) (!ID_Stall) |-> ##1 (vote_ID_IsFlushed == $past(IF_Flush))
    );

    ///// Restart PC selection /////
    // If IF_IsBDS, next cycle RestartPC comes from ID_RestartPC (regardless of stall).
    restartpc_from_ID_when_isbds: assert property (
        @(posedge clock) disable iff (reset) IF_IsBDS |-> ##1 (vote_ID_RestartPC == $past(ID_RestartPC))
    );
    // If not ID_Stall and not IF_IsBDS, next cycle RestartPC comes from IF_PC.
    restartpc_from_IF_pc_when_normal: assert property (
        @(posedge clock) disable iff (reset) (!ID_Stall && !IF_IsBDS) |-> ##1 (vote_ID_RestartPC == $past(IF_PC))
    );
endmodule

module mux4_ctrl_sva (
    input  logic        CLK,   // external verification clock (RTL has no clock/reset)
    input  logic [7:0]  A,
    input  logic [7:0]  B,
    input  logic [7:0]  C,
    input  logic [7:0]  D,
    input  logic        ctrl,
    input  logic [7:0]  out
);
    // RTL is purely combinational: ctrl=0 selects A, ctrl=1 selects D, otherwise out=0.

    // When ctrl==0, out equals A.
    check_ctrl0_selects_A: assert property (
        @(posedge CLK) (ctrl == 1'b0) |-> (out == A)
    );

    // When ctrl==1, out equals D.
    check_ctrl1_selects_D: assert property (
        @(posedge CLK) (ctrl == 1'b1) |-> (out == D)
    );

    // If ctrl is X/Z, out must be 0.
    check_default_zero_on_unknown_ctrl: assert property (
        @(posedge CLK) (ctrl !== 1'b0 && ctrl !== 1'b1) |-> (out == 8'h00)
    );

    // With ctrl held 0 and A stable, out stays stable.
    check_stable_out_when_ctrl0_A_stable: assert property (
        @(posedge CLK) (ctrl == 1'b0) && $stable(ctrl) && $stable(A) |-> $stable(out)
    );

    // With ctrl held 1 and D stable, out stays stable.
    check_stable_out_when_ctrl1_D_stable: assert property (
        @(posedge CLK) (ctrl == 1'b1) && $stable(ctrl) && $stable(D) |-> $stable(out)
    );

    // With ctrl held 0, a change on A causes a change on out.
    check_A_change_propagates_when_ctrl0: assert property (
        @(posedge CLK) (ctrl == 1'b0) && $stable(ctrl) && $changed(A) |-> $changed(out)
    );

    // With ctrl held 1, a change on D causes a change on out.
    check_D_change_propagates_when_ctrl1: assert property (
        @(posedge CLK) (ctrl == 1'b1) && $stable(ctrl) && $changed(D) |-> $changed(out)
    );

    // On ctrl rising edge, out reflects D.
    check_out_on_ctrl_rise: assert property (
        @(posedge CLK) $rose(ctrl) |-> (out == D)
    );

    // On ctrl falling edge, out reflects A.
    check_out_on_ctrl_fall: assert property (
        @(posedge CLK) $fell(ctrl) |-> (out == A)
    );
endmodule

