module and_gate (
    output reg [7:0] out,
    input [7:0] in1,
    input [7:0] in2
);

always @* begin
    out = in1 & in2;
end

endmodule

module or_gate (
    output reg [7:0] out,
    input [7:0] in1,
    input [7:0] in2
);

always @* begin
    out = in1 | in2;
end

endmodule

module three_to_one (
    input [7:0] A,
    input [7:0] B,
    input [7:0] C,
    output reg [7:0] X
);

wire [7:0] and_result;
wire [7:0] or_result;

and_gate and_gate_inst (
    .out(and_result),
    .in1(A),
    .in2(B)
);

or_gate or_gate_inst (
    .out(or_result),
    .in1(B),
    .in2(C)
);

always @* begin
    X = and_result ^ or_result;
end

endmodule

sva:
module three_to_one_sva (
    input logic CLK,
    input logic [7:0] A,
    input logic [7:0] B,
    input logic [7:0] C,
    input logic [7:0] X
);
    ///// Functional equivalence /////
    // X must equal (A & B) ^ (B | C).
    check_function_equivalence_main: assert property (
        @(posedge CLK) X == ((A & B) ^ (B | C))
    );
    // X must also equal ((~A) & B) | (C & ~B).
    check_equivalence_mux_form: assert property (
        @(posedge CLK) X == (((~A) & B) | (C & ~B))
    );

    ///// Bit-level masking behaviors /////
    // Bits where B is 0: X must match C on those bits.
    check_bits_where_B_zero_match_C: assert property (
        @(posedge CLK) (((X ^ C) & ~B) == 8'h00)
    );
    // Bits where B is 1: X must match ~A on those bits.
    check_bits_where_B_one_match_notA: assert property (
        @(posedge CLK) (((X ^ (~A)) & B) == 8'h00)
    );

    ///// Special cases /////
    // If all bits of B are 0, X equals C.
    check_all_B_zero_implies_X_eq_C: assert property (
        @(posedge CLK) (B == 8'h00) |-> (X == C)
    );
    // If all bits of B are 1, X equals ~A.
    check_all_B_ones_implies_X_eq_notA: assert property (
        @(posedge CLK) (B == 8'hFF) |-> (X == (~A))
    );
    // If A equals C, X reduces to A ^ B.
    check_when_A_equals_C_then_X_eq_A_xor_B: assert property (
        @(posedge CLK) (A == C) |-> (X == (A ^ B))
    );
    // If C equals ~A, X equals ~A regardless of B.
    check_when_C_equals_notA_then_X_eq_notA: assert property (
        @(posedge CLK) (C == (~A)) |-> (X == (~A))
    );
    // If B equals C, X equals B & ~A.
    check_when_B_equals_C_then_X_eq_B_and_notA: assert property (
        @(posedge CLK) (B == C) |-> (X == (B & (~A)))
    );
    // If B equals ~C, X equals ~(A & B).
    check_when_B_equals_notC_then_X_eq_not_AandB: assert property (
        @(posedge CLK) (B == (~C)) |-> (X == (~(A & B)))
    );
endmodule

rtl:
module binary_to_gray(
    input [3:0] binary,
    output [3:0] gray
);

    assign gray[3] = binary[3];
    assign gray[2] = binary[3] ^ binary[2];
    assign gray[1] = binary[2] ^ binary[1];
    assign gray[0] = binary[1] ^ binary[0];

endmodule

sva:
module binary_to_gray_sva (
    input logic clk,
    input logic [3:0] binary,
    input logic [3:0] gray
);
    ///// Bitwise mapping /////
    // MSB maps directly: gray[3] == binary[3].
    check_map_bit3: assert property (
        @(posedge clk) disable iff (1'b0) gray[3] == binary[3]
    );
    // gray[2] == binary[3] ^ binary[2].
    check_map_bit2: assert property (
        @(posedge clk) disable iff (1'b0) gray[2] == (binary[3] ^ binary[2])
    );
    // gray[1] == binary[2] ^ binary[1].
    check_map_bit1: assert property (
        @(posedge clk) disable iff (1'b0) gray[1] == (binary[2] ^ binary[1])
    );
    // gray[0] == binary[1] ^ binary[0].
    check_map_bit0: assert property (
        @(posedge clk) disable iff (1'b0) gray[0] == (binary[1] ^ binary[0])
    );

    ///// Vector mapping equivalence /////
    // gray == binary XOR (binary >> 1).
    check_map_vector: assert property (
        @(posedge clk) disable iff (1'b0) gray == (binary ^ {1'b0, binary[3:1]})
    );

    ///// Inverse relations derived from mapping /////
    // Recover binary[2] from gray: binary[2] == gray[2] ^ gray[3].
    check_inverse_b2: assert property (
        @(posedge clk) disable iff (1'b0) binary[2] == (gray[2] ^ gray[3])
    );
    // Recover binary[1] from gray: binary[1] == gray[1] ^ gray[2] ^ gray[3].
    check_inverse_b1: assert property (
        @(posedge clk) disable iff (1'b0) binary[1] == (gray[1] ^ gray[2] ^ gray[3])
    );
    // Recover binary[0] from gray: binary[0] == gray[0] ^ gray[1] ^ gray[2] ^ gray[3].
    check_inverse_b0: assert property (
        @(posedge clk) disable iff (1'b0) binary[0] == (gray[0] ^ gray[1] ^ gray[2] ^ gray[3])
    );

    ///// Additional consistency checks /////
    // Parity of gray equals LSB of binary.
    check_parity_relation: assert property (
        @(posedge clk) disable iff (1'b0) (^gray) == binary[0]
    );
    // Upper pair mapping consistency: {gray[3],gray[2]}.
    check_upper_pair_map: assert property (
        @(posedge clk) disable iff (1'b0) {gray[3], gray[2]} == {binary[3], (binary[3] ^ binary[2])}
    );
endmodule

rtl:
module four_bit_adder(
    input [3:0] A,
    input [3:0] B,
    input CI,
    output CO,
    output [3:0] S
);

wire [3:0] C; // intermediate carry values
wire [3:0] X; // intermediate sum values

// full adder for bit 0
full_adder FA0(A[0], B[0], CI, C[0], X[0]);

// full adder for bit 1
full_adder FA1(A[1], B[1], C[0], C[1], X[1]);

// full adder for bit 2
full_adder FA2(A[2], B[2], C[1], C[2], X[2]);

// full adder for bit 3
full_adder FA3(A[3], B[3], C[2], CO, X[3]);

assign S = X;

endmodule

module full_adder(
    input A,
    input B,
    input CI,
    output CO,
    output S
);

assign {CO, S} = A + B + CI;

endmodule

sva:
module four_bit_adder_sva (
    input logic CLK,          // sampling clock for SVA
    input logic [3:0] A,
    input logic [3:0] B,
    input logic CI,
    input logic CO,
    input logic [3:0] S
);
    // Sum and carry-out equal the 5-bit addition of inputs.
    sum_matches_addition: assert property (
        @(posedge CLK) {CO, S} == ({1'b0, A} + {1'b0, B} + CI)
    );

    // S equals lower 4 bits of the 5-bit sum.
    s_is_lower_nibble_of_sum: assert property (
        @(posedge CLK) S == (({1'b0, A} + {1'b0, B} + CI)[3:0])
    );

    // CO equals MSB of the 5-bit sum.
    co_is_msb_of_sum: assert property (
        @(posedge CLK) CO == (({1'b0, A} + {1'b0, B} + CI)[4])
    );

    // LSB sum equals XOR of inputs.
    lsb_xor_rule: assert property (
        @(posedge CLK) S[0] == (A[0] ^ B[0] ^ CI)
    );

    // Identity: when B==0 and CI==0, output equals A with no carry.
    identity_b_zero_ci_zero: assert property (
        @(posedge CLK) (B == 4'b0000) && (CI == 1'b0) |-> (S == A) && (CO == 1'b0)
    );

    // Identity: when A==0 and CI==0, output equals B with no carry.
    identity_a_zero_ci_zero: assert property (
        @(posedge CLK) (A == 4'b0000) && (CI == 1'b0) |-> (S == B) && (CO == 1'b0)
    );

    // Corner case: when A==0 and B==0, S echoes CI and CO is 0.
    zero_inputs_corner: assert property (
        @(posedge CLK) (A == 4'b0000) && (B == 4'b0000) |-> (S == {3'b000, CI}) && (CO == 1'b0)
    );

    // No carry-out when 5-bit sum is less than 16.
    no_carry_without_overflow: assert property (
        @(posedge CLK) (({1'b0, A} + {1'b0, B} + CI) < 5'd16) |-> (CO == 1'b0)
    );

    // Carry-out asserted when 5-bit sum is 16 or more.
    carry_with_overflow: assert property (
        @(posedge CLK) (({1'b0, A} + {1'b0, B} + CI) >= 5'd16) |-> (CO == 1'b1)
    );

    // Outputs remain stable when inputs are stable between samples.
    outputs_stable_when_inputs_stable: assert property (
        @(posedge CLK) $stable(A) && $stable(B) && $stable(CI) |-> $stable(S) && $stable(CO)
    );
endmodule

rtl:
module mux2to1 (out, in0, in1, sel);
	output out;
	input in0, in1;
	input sel;
	assign out = sel ? in1 : in0;
endmodule

module or2 (out, in0, in1);
	output out;
	input in0, in1;
	assign out = in0 | in1;
endmodule

module mux4to1 (out, in0, in1, in2, in3, sel);
	output out;
	input in0, in1, in2, in3;
	input [1:0] sel;
	wire m0, m1, o;
	mux2to1 m2 (m0, in0, in1, sel[0]);
	mux2to1 m3 (m1, in2, in3, sel[0]);
	or2 o1 (o, m0, m1);
	mux2to1 m4 (out, m0, m1, sel[1]);
endmodule

sva:
module mux4to1_sva (
    input logic CLK,
    input logic out,
    input logic in0,
    input logic in1,
    input logic in2,
    input logic in3,
    input logic [1:0] sel
);
    // out equals the canonical 4:1 mux function of sel and inputs.
    check_mux_function: assert property (
        @(posedge CLK) out == (sel[1] ? (sel[0] ? in3 : in2) : (sel[0] ? in1 : in0))
    );

    // When sel==00, out must equal in0.
    check_sel00_maps_in0: assert property (
        @(posedge CLK) (sel == 2'b00) |-> (out == in0)
    );

    // When sel==01, out must equal in1.
    check_sel01_maps_in1: assert property (
        @(posedge CLK) (sel == 2'b01) |-> (out == in1)
    );

    // When sel==10, out must equal in2.
    check_sel10_maps_in2: assert property (
        @(posedge CLK) (sel == 2'b10) |-> (out == in2)
    );

    // When sel==11, out must equal in3.
    check_sel11_maps_in3: assert property (
        @(posedge CLK) (sel == 2'b11) |-> (out == in3)
    );

    // MSB of sel selects between lower pair (in0/in1) when 0.
    check_group_select_low: assert property (
        @(posedge CLK) (sel[1] == 1'b0) |-> (out == (sel[0] ? in1 : in0))
    );

    // MSB of sel selects between upper pair (in2/in3) when 1.
    check_group_select_high: assert property (
        @(posedge CLK) (sel[1] == 1'b1) |-> (out == (sel[0] ? in3 : in2))
    );

    // Purely combinational: if all inputs and sel are unchanged, out is unchanged.
    check_memoryless: assert property (
        @(posedge CLK) ({in3,in2,in1,in0,sel} == $past({in3,in2,in1,in0,sel})) |-> (out == $past(out))
    );

    // Isolation: with sel==00 stable, changes on in1/in2/in3 do not affect out.
    check_isolation_sel00: assert property (
        @(posedge CLK)
            ($past(sel) == 2'b00 && sel == 2'b00 && in0 == $past(in0) &&
             ((in1 != $past(in1)) || (in2 != $past(in2)) || (in3 != $past(in3))))
        |-> (out == $past(out))
    );

    // Isolation: with sel==01 stable, changes on in0/in2/in3 do not affect out.
    check_isolation_sel01: assert property (
        @(posedge CLK)
            ($past(sel) == 2'b01 && sel == 2'b01 && in1 == $past(in1) &&
             ((in0 != $past(in0)) || (in2 != $past(in2)) || (in3 != $past(in3))))
        |-> (out == $past(out))
    );

    // Isolation: with sel==10 stable, changes on in0/in1/in3 do not affect out.
    check_isolation_sel10: assert property (
        @(posedge CLK)
            ($past(sel) == 2'b10 && sel == 2'b10 && in2 == $past(in2) &&
             ((in0 != $past(in0)) || (in1 != $past(in1)) || (in3 != $past(in3))))
        |-> (out == $past(out))
    );

    // Isolation: with sel==11 stable, changes on in0/in1/in2 do not affect out.
    check_isolation_sel11: assert property (
        @(posedge CLK)
            ($past(sel) == 2'b11 && sel == 2'b11 && in3 == $past(in3) &&
             ((in0 != $past(in0)) || (in1 != $past(in1)) || (in2 != $past(in2))))
        |-> (out == $past(out))
    );
endmodule

rtl:
module mux_4to1 (
  input [3:0] data_in,
  input [1:0] sel,
  output reg out
);

always @(*)
begin
  case(sel)
    2'b00: out = sel[0] ? data_in[1] : data_in[0];
    2'b01: out = sel[0] ? data_in[3] : data_in[2];
    default: out = 1'b0;
  endcase
end

endmodule

sva:
module mux_4to1_sva (
    input logic [3:0] data_in,
    input logic [1:0] sel,
    input logic       out
);
    // Out matches truth table at sel[0] rising edges.
    check_truth_table_on_sel0: assert property (
        @(posedge sel[0]) out == ((sel == 2'b00) ? data_in[0] :
                                   (sel == 2'b01) ? data_in[3] :
                                   1'b0)
    );

    // Out matches truth table at sel[1] rising edges.
    check_truth_table_on_sel1: assert property (
        @(posedge sel[1]) out == ((sel == 2'b00) ? data_in[0] :
                                   (sel == 2'b01) ? data_in[3] :
                                   1'b0)
    );

    // When sel==00, out equals data_in[0] at data_in[0] edges.
    check_sel00_data0_drives_out: assert property (
        @(posedge data_in[0]) (sel == 2'b00) |-> (out == data_in[0])
    );

    // When sel==01, out equals data_in[3] at data_in[3] edges.
    check_sel01_data3_drives_out: assert property (
        @(posedge data_in[3]) (sel == 2'b01) |-> (out == data_in[3])
    );

    // sel[1]==1 implies out is 0 at sel[1] rising edge (default case).
    check_default_zero_on_sel1_rise: assert property (
        @(posedge sel[1]) out == 1'b0
    );

    // Out cannot rise when sel[1]==1.
    check_no_out_rise_when_sel1_high: assert property (
        @(posedge out) sel[1] == 1'b0
    );
endmodule

rtl:
module r_COMMAND(output reg [7:0] reg_0x23, input wire reset, input wire wenb, input wire [7:0] in_data, input wire clk);
	always@(posedge clk)
	begin
		if(reset==0) begin
			if(wenb==0)
				reg_0x23<=in_data;
			else
				reg_0x23<=reg_0x23;
		end
		else
			reg_0x23<=8'h00;
	end
endmodule

sva:
module r_COMMAND_sva (
    input logic clk,
    input logic reset,       // active-high synchronous reset
    input logic wenb,        // active-low write enable
    input logic [7:0] in_data,
    input logic [7:0] reg_0x23
);
    // Reset drives reg_0x23 to 8'h00 on the next clock.
    check_reset_clears_reg_next: assert property (
        @(posedge clk) reset |-> (reg_0x23 == 8'h00)
    );

    // With wenb HIGH (no write), hold previous value to next cycle.
    check_hold_when_wenb_high: assert property (
        @(posedge clk) disable iff (reset) (wenb == 1'b1) |-> (reg_0x23 == $past(reg_0x23))
    );

    // With wenb LOW, load in_data on the next cycle.
    check_update_on_wenb_low: assert property (
        @(posedge clk) disable iff (reset) (wenb == 1'b0) |-> (reg_0x23 == $past(in_data))
    );

    // If the register changes and last cycle was not reset, last cycle must have had a write enable (wenb LOW).
    check_change_requires_prev_write_when_no_reset: assert property (
        @(posedge clk) disable iff (reset) ($changed(reg_0x23) && !$past(reset)) |-> ($past(wenb) == 1'b0)
    );

    // If last cycle was a write and in_data equaled the old value, the register must not change.
    check_write_same_value_no_change: assert property (
        @(posedge clk) disable iff (reset) ($past(wenb) == 1'b0 && ($past(in_data) == $past(reg_0x23))) |-> (reg_0x23 == $past(reg_0x23))
    );

    // If last cycle was a write and in_data differed from the old value, the register must change.
    check_write_diff_value_changes: assert property (
        @(posedge clk) disable iff (reset) ($past(wenb) == 1'b0 && ($past(in_data) != $past(reg_0x23))) |-> (reg_0x23 != $past(reg_0x23))
    );

    // Next-state relation when neither current nor previous cycle is in reset.
    check_next_state_definition: assert property (
        @(posedge clk) (!reset && !$past(reset)) |-> (reg_0x23 == (($past(wenb) == 1'b0) ? $past(in_data) : $past(reg_0x23)))
    );

    // Reset dominates write: if reset is asserted, next value is 0 regardless of wenb.
    check_reset_dominates_write: assert property (
        @(posedge clk) (reset && (wenb == 1'b0)) |-> (reg_0x23 == 8'h00)
    );
endmodule

rtl:
module four_bit_adder(
  input [3:0] A,
  input [3:0] B,
  input CIN,
  output [3:0] SUM,
  output COUT,
  input VPWR,
  input VGND
);

  wire [3:0] C;
  wire [3:0] S;

  assign S[0] = A[0] ^ B[0] ^ CIN;
  assign C[0] = (A[0] & B[0]) | (A[0] & CIN) | (B[0] & CIN);

  assign S[1] = A[1] ^ B[1] ^ C[0];
  assign C[1] = (A[1] & B[1]) | (A[1] & C[0]) | (B[1] & C[0]);

  assign S[2] = A[2] ^ B[2] ^ C[1];
  assign C[2] = (A[2] & B[2]) | (A[2] & C[1]) | (B[2] & C[1]);

  assign S[3] = A[3] ^ B[3] ^ C[2];
  assign COUT = (A[3] & B[3]) | (A[3] & C[2]) | (B[3] & C[2]);

  assign SUM = {S[3], S[2], S[1], S[0]};

endmodule

sva:
module four_bit_adder_sva (
  input logic [3:0] A,
  input logic [3:0] B,
  input logic CIN,
  input logic [3:0] SUM,
  input logic COUT,
  input logic VPWR,
  input logic VGND
);
  // No clock or reset in RTL; combinational logic; assertions use posedge $global_clock with no reset disable.
  // Key behavior: 4-bit ripple-carry addition: {COUT,SUM} == A + B + CIN; VPWR/VGND are unused.

  // SUM and COUT must equal the 5-bit addition of A, B, and CIN.
  check_addition_packed: assert property (
    @(posedge $global_clock) {COUT, SUM} == ({1'b0, A} + {1'b0, B} + CIN)
  );

  // SUM must match the low 4 bits of A + B + CIN.
  check_sum_lowbits: assert property (
    @(posedge $global_clock) SUM == (({1'b0, A} + {1'b0, B} + CIN)[3:0])
  );

  // COUT must match the carry-out bit (bit 4) of A + B + CIN.
  check_cout_bit: assert property (
    @(posedge $global_clock) COUT == (({1'b0, A} + {1'b0, B} + CIN)[4])
  );

  // LSB sum bit equals XOR of A[0], B[0], and CIN.
  check_sum_bit0_xor: assert property (
    @(posedge $global_clock) SUM[0] == (A[0] ^ B[0] ^ CIN)
  );

  // SUM[1] equals XOR of A[1], B[1], and carry from bit 0.
  check_sum_bit1_xor_with_c0: assert property (
    @(posedge $global_clock)
      SUM[1] == (A[1] ^ B[1] ^ ((A[0] & B[0]) | (A[0] & CIN) | (B[0] & CIN)))
  );

  // Outputs remain stable if A, B, and CIN are stable (no hidden state or VPWR/VGND dependence).
  check_outputs_stable_on_stable_inputs: assert property (
    @(posedge $global_clock) ($stable(A) && $stable(B) && $stable(CIN)) |-> ($stable(SUM) && $stable(COUT))
  );

  // Adding zeros yields zero result and no carry.
  check_zero_case: assert property (
    @(posedge $global_clock) (A == 4'd0 && B == 4'd0 && CIN == 1'b0) |-> (SUM == 4'd0 && COUT == 1'b0)
  );

  // 0xF + 0xF + 1 yields SUM=0xF and COUT=1.
  check_max_plus_one: assert property (
    @(posedge $global_clock) (A == 4'hF && B == 4'hF && CIN == 1'b1) |-> (SUM == 4'hF && COUT == 1'b1)
  );

endmodule

rtl:
module register_bank (
  input clk,
  input [31:0] data_in,
  input write_en,
  input [4:0] read_address_1,
  input [4:0] read_address_2,
  output reg [31:0] read_data_1,
  output reg [31:0] read_data_2
);

  wire [31:0] ram_data;
  reg [31:0] ram_q_1;
  reg [31:0] ram_q_2;
  assign ram_data = data_in;

  always @(posedge clk) begin
    read_data_1 <= ram_q_1;
    read_data_2 <= ram_q_2;
  end

  always @(posedge clk) begin
    if (write_en) begin
      ram_q_1 <= ram_data;
      ram_q_2 <= ram_data;
    end
  end

endmodule

sva:
module register_bank_sva (
  input logic clk,
  input logic [31:0] data_in,
  input logic write_en,
  input logic [4:0] read_address_1,
  input logic [4:0] read_address_2,
  input logic [31:0] read_data_1,
  input logic [31:0] read_data_2
);
  // A write captures data_in into read_data_1 on the next clock.
  check_write_capture_rd1: assert property (
    @(posedge clk) write_en |=> (read_data_1 == $past(data_in))
  );

  // A write captures data_in into read_data_2 on the next clock.
  check_write_capture_rd2: assert property (
    @(posedge clk) write_en |=> (read_data_2 == $past(data_in))
  );

  // Without a write, read_data_1 holds its value to the next clock.
  check_hold_no_write_rd1: assert property (
    @(posedge clk) !write_en |=> (read_data_1 == $past(read_data_1))
  );

  // Without a write, read_data_2 holds its value to the next clock.
  check_hold_no_write_rd2: assert property (
    @(posedge clk) !write_en |=> (read_data_2 == $past(read_data_2))
  );

  // read_data_1 only changes following a write in the previous cycle.
  check_change_requires_prev_write_rd1: assert property (
    @(posedge clk) $changed(read_data_1) |-> $past(write_en)
  );

  // read_data_2 only changes following a write in the previous cycle.
  check_change_requires_prev_write_rd2: assert property (
    @(posedge clk) $changed(read_data_2) |-> $past(write_en)
  );

  // After a write, both outputs next cycle equal that cycle's data_in.
  check_prev_write_outputs_equal_written: assert property (
    @(posedge clk) $past(write_en) |-> (read_data_1 == $past(data_in)) && (read_data_2 == $past(data_in))
  );

  // Any output change implies last cycle was a write and both outputs now equal the written data.
  check_any_change_implies_written_value: assert property (
    @(posedge clk) ($changed(read_data_1) || $changed(read_data_2)) |-> $past(write_en) && (read_data_1 == $past(data_in)) && (read_data_2 == $past(data_in))
  );

  // If outputs differ now, there was no write in the previous cycle.
  check_diff_implies_no_prev_write: assert property (
    @(posedge clk) (read_data_1 != read_data_2) |-> !$past(write_en)
  );

  // If no write this cycle and outputs are equal now, they remain equal next cycle.
  check_equal_hold_without_write: assert property (
    @(posedge clk) (!write_en && (read_data_1 == read_data_2)) |=> (read_data_1 == read_data_2)
  );
endmodule

rtl:
module altera_tse_false_path_marker 
#(
   parameter MARKER_WIDTH = 1
)
(
   input    reset,
   input    clk,
   input    [MARKER_WIDTH - 1 : 0] data_in,
   output   [MARKER_WIDTH - 1 : 0] data_out
);

 reg [MARKER_WIDTH - 1 : 0] data_out_reg;


assign data_out = data_out_reg;

always @(posedge clk or posedge reset) 
begin
   if (reset)
   begin
      data_out_reg <= {MARKER_WIDTH{1'b0}};
   end
   else
   begin
      data_out_reg <= data_in;
   end
end

endmodule

sva:
module altera_tse_false_path_marker_sva 
#(
    parameter int MARKER_WIDTH = 1
)
(
    input  logic                      reset,
    input  logic                      clk,
    input  logic [MARKER_WIDTH-1:0]   data_in,
    input  logic [MARKER_WIDTH-1:0]   data_out
);

    // If reset is HIGH, output must be zero on the next cycle.
    check_output_zero_next_after_reset: assert property (
        @(posedge clk) reset |=> (data_out == {MARKER_WIDTH{1'b0}})
    );

    // If the previous cycle had reset HIGH, output must be zero now.
    check_output_zero_if_prev_cycle_reset: assert property (
        @(posedge clk) $past(reset) |-> (data_out == {MARKER_WIDTH{1'b0}})
    );

    // On a sampled falling edge of reset, output is zero on that cycle.
    check_output_zero_on_reset_fall_now: assert property (
        @(posedge clk) $fell(reset) |-> (data_out == {MARKER_WIDTH{1'b0}})
    );

    // With reset LOW on consecutive samples, output is either previous input or zero.
    check_prev_in_or_zero_when_no_reset_sampled: assert property (
        @(posedge clk) disable iff (reset)
            (!reset && !$past(reset)) |-> ((data_out == $past(data_in)) || (data_out == {MARKER_WIDTH{1'b0}}))
    );

    // With reset LOW on consecutive samples, a non-zero output must equal previous input.
    check_nonzero_output_matches_prev_input_when_no_reset_sampled: assert property (
        @(posedge clk) disable iff (reset)
            (!reset && !$past(reset) && (data_out != {MARKER_WIDTH{1'b0}})) |-> (data_out == $past(data_in))
    );

    // Output is never X/Z while reset is HIGH.
    check_output_not_unknown_during_reset: assert property (
        @(posedge clk) reset |-> !$isunknown(data_out)
    );

endmodule

