module binary_addition(
    input [7:0] a,
    input [7:0] b,
    output [7:0] sum
);

    wire [8:0] temp_sum;

    assign temp_sum = a + b;
    assign sum = temp_sum[7:0];

endmodule

sva:
module binary_addition_sva (
    input  logic CLK,          // External sampling clock for SVA
    input  logic [7:0] a,
    input  logic [7:0] b,
    input  logic [7:0] sum
);
    // Sum equals 8-bit addition of a and b (modulo 256).
    check_sum_is_add: assert property (
        @(posedge CLK) sum == (a + b)
    );

    // If a is zero, sum equals b.
    check_zero_a_identity: assert property (
        @(posedge CLK) (a == 8'h00) |-> (sum == b)
    );

    // If b is zero, sum equals a.
    check_zero_b_identity: assert property (
        @(posedge CLK) (b == 8'h00) |-> (sum == a)
    );

    // Subtracting b from sum recovers a (modulo 256).
    check_subtract_recovers_a: assert property (
        @(posedge CLK) (sum - b) == a
    );

    // Subtracting a from sum recovers b (modulo 256).
    check_subtract_recovers_b: assert property (
        @(posedge CLK) (sum - a) == b
    );

    // If inputs are stable across a cycle, sum is stable.
    check_stability_when_inputs_stable: assert property (
        @(posedge CLK) ($stable(a) && $stable(b)) |-> $stable(sum)
    );

    // Specific wrap-around example: 0xFF + 0x01 -> 0x00.
    check_wrap_example_ff_plus_01: assert property (
        @(posedge CLK) ((a == 8'hFF) && (b == 8'h01)) |-> (sum == 8'h00)
    );
endmodule

rtl:
module my_module (
    X,
    A,
    SLEEP
);

    output X;
    input A;
    input SLEEP;

    wire signal1, signal2, signal3, signal4;

    assign signal1 = A & SLEEP;
    assign signal2 = ~SLEEP;
    assign signal3 = A;
    assign signal4 = SLEEP;

    assign X = (SLEEP) ? (signal1 & signal2) | (signal3 & signal4) : A;

endmodule

sva:
module my_module_sva (
    input logic CLK,      // Sampling clock for assertions (DUT has no clock/reset)
    input logic X,        // DUT output
    input logic A,        // DUT input
    input logic SLEEP     // DUT input
);
    // X matches the RTL combinational expression.
    check_x_matches_rtl_expr: assert property (
        @(posedge CLK) X == (SLEEP ? (((A & SLEEP) & (~SLEEP)) | (A & SLEEP)) : A)
    );

    // X equals A for all cycles.
    check_x_equals_a: assert property (
        @(posedge CLK) X == A
    );

    // When SLEEP is 0, X equals A.
    check_sleep0_passthrough: assert property (
        @(posedge CLK) (SLEEP == 1'b0) |-> (X == A)
    );

    // When SLEEP is 1, X equals A.
    check_sleep1_passthrough: assert property (
        @(posedge CLK) (SLEEP == 1'b1) |-> (X == A)
    );

    // Rising SLEEP does not change X if A is stable.
    check_sleep_rise_no_effect_when_a_stable: assert property (
        @(posedge CLK) $rose(SLEEP) && $stable(A) |-> $stable(X)
    );

    // Falling SLEEP does not change X if A is stable.
    check_sleep_fall_no_effect_when_a_stable: assert property (
        @(posedge CLK) $fell(SLEEP) && $stable(A) |-> $stable(X)
    );

    // X rises when A rises.
    check_x_rises_with_a: assert property (
        @(posedge CLK) $rose(A) |-> $rose(X)
    );

    // X falls when A falls.
    check_x_falls_with_a: assert property (
        @(posedge CLK) $fell(A) |-> $fell(X)
    );

    // Any change on X implies a change on A.
    check_x_change_implies_a_change: assert property (
        @(posedge CLK) $changed(X) |-> $changed(A)
    );

    // The term (A & SLEEP) & (~SLEEP) is zero when SLEEP is 1.
    check_and_term_zero_on_sleep1: assert property (
        @(posedge CLK) (SLEEP == 1'b1) |-> (((A & SLEEP) & (~SLEEP)) == 1'b0)
    );
endmodule

rtl:
module Interleaver(
    input clk,
    input trigger,
    input Interleave_b,
	 input FF_en,
	 `ifdef XILINX_ISIM
		output reg output_en = 1'b1
	 `else
		output reg output_en = 1'b0
	 `endif
    );

 reg Interleave = 1'b0, Interleave_a = 1'b0;
 reg FF_en_a = 1'b0, FF_en_b = 1'b0;

always @(posedge clk) begin
	Interleave <= Interleave_a;
	Interleave_a <= Interleave_b;
	FF_en_a <= FF_en;
	FF_en_b <= FF_en_a;

	if (trigger && FF_en_b) output_en <= (Interleave) ? ~output_en : 1'b1;
	else if (trigger) output_en <= 1'b0;
	else output_en <= output_en;
	end

endmodule

sva:
module Interleaver_sva (
    input logic clk,
    input logic trigger,
    input logic Interleave_b,
    input logic FF_en,
    input logic output_en
);

    // When trigger is LOW, output_en holds its value to next cycle.
    hold_when_no_trigger: assert property (
        @(posedge clk) !trigger |=> output_en == $past(output_en)
    );

    // On trigger with FF_en delayed 2 cycles LOW, next output_en is 0.
    set0_on_trigger_no_ff_delayed: assert property (
        @(posedge clk) (trigger && !$past(FF_en,2)) |=> (output_en == 1'b0)
    );

    // On trigger with FF_en delayed 2 cycles HIGH and Interleave delayed 2 cycles LOW, next output_en is 1.
    set1_on_trigger_ff_delayed_interleave0: assert property (
        @(posedge clk) (trigger && $past(FF_en,2) && !$past(Interleave_b,2)) |=> (output_en == 1'b1)
    );

    // On trigger with FF_en and Interleave both delayed 2 cycles HIGH, next output_en toggles.
    toggle_on_trigger_ff_delayed_interleave1: assert property (
        @(posedge clk) (trigger && $past(FF_en,2) && $past(Interleave_b,2)) |=> (output_en == !$past(output_en))
    );

    // Directional toggle: with trigger, ff delayed=1, interleave delayed=1, if prev output_en=1 then next is 0.
    toggle_dir_high_to_low: assert property (
        @(posedge clk) (trigger && $past(FF_en,2) && $past(Interleave_b,2) && $past(output_en)) |=> (output_en == 1'b0)
    );

    // Directional toggle: with trigger, ff delayed=1, interleave delayed=1, if prev output_en=0 then next is 1.
    toggle_dir_low_to_high: assert property (
        @(posedge clk) (trigger && $past(FF_en,2) && $past(Interleave_b,2) && !$past(output_en)) |=> (output_en == 1'b1)
    );

    // Any change of output_en implies trigger was HIGH in the previous cycle.
    change_only_on_trigger: assert property (
        @(posedge clk) $changed(output_en) |-> $past(trigger)
    );

    // A rising edge on output_en implies prior trigger and FF_en delayed 2 cycles HIGH.
    rise_implies_trigger_and_ff_delayed: assert property (
        @(posedge clk) $rose(output_en) |-> ($past(trigger) && $past(FF_en,2))
    );

    // A falling edge on output_en implies prior trigger was HIGH.
    fall_implies_trigger: assert property (
        @(posedge clk) $fell(output_en) |-> $past(trigger)
    );

    // Full-case next-state function for output_en on trigger (encodes the RTL ternary behavior).
    next_state_on_trigger_matches_rtl: assert property (
        @(posedge clk)
            trigger |=> (
                $past(FF_en,2)
                    ? ( $past(Interleave_b,2) ? (output_en == !$past(output_en)) : (output_en == 1'b1) )
                    : (output_en == 1'b0)
            )
    );

endmodule

rtl:
module mem_encryption (
  input clk,
  input reset,
  input [31:0] data_in,
  input [31:0] key,
  output reg [31:0] data_out
);

  reg [31:0] internal_state;

  always @(posedge clk) begin
    if (reset) begin
      internal_state <= 0;
      data_out <= 0;
    end else begin
      if (key == 0) begin
        data_out <= data_in;
      end else begin
        internal_state <= data_in ^ key;
        data_out <= internal_state ^ key;
      end
    end
  end

endmodule

sva:
module mem_encryption_sva (
    input logic         clk,
    input logic         reset,
    input logic [31:0]  data_in,
    input logic [31:0]  key,
    input logic [31:0]  data_out,
    input logic [31:0]  internal_state
);
    // Clock: clk (posedge). Reset: reset (active-high synchronous).
    // Sequential: registers internal_state and data_out update on posedge clk.
    // Function: reset clears regs; key==0 -> data_out=data_in, hold internal_state; else -> internal_state=data_in^key, data_out=$past(internal_state)^key.

    // On reset, both internal_state and data_out are driven to 0.
    reset_clears_regs: assert property (
        @(posedge clk) reset |-> (internal_state == 32'h0) && (data_out == 32'h0)
    );

    // When key is zero, data_out passes through data_in.
    key_zero_passthrough: assert property (
        @(posedge clk) disable iff (reset) (key == 32'h0) |-> (data_out == data_in)
    );

    // When key is zero, internal_state holds its previous value.
    hold_internal_state_when_key_zero: assert property (
        @(posedge clk) disable iff (reset) (!$past(reset) && (key == 32'h0)) |-> (internal_state == $past(internal_state))
    );

    // When key is nonzero, internal_state updates to data_in ^ key in the same cycle.
    update_internal_state_when_key_nonzero: assert property (
        @(posedge clk) disable iff (reset) (key != 32'h0) |-> (internal_state == (data_in ^ key))
    );

    // When key is nonzero, data_out uses previous internal_state XOR current key.
    data_out_uses_prev_internal_state_when_key_nonzero: assert property (
        @(posedge clk) disable iff (reset) (!$past(reset) && (key != 32'h0)) |-> (data_out == ($past(internal_state) ^ key))
    );

    // First cycle after reset with nonzero key: data_out equals key (prev internal_state was 0).
    first_nonzero_key_after_reset_outputs_key: assert property (
        @(posedge clk) disable iff (reset) ($past(reset) && (key != 32'h0)) |-> (data_out == key)
    );

    // If previous cycle had nonzero key and current key is zero, internal_state equals previous data_in ^ previous key.
    internal_state_matches_prev_calc_on_key_drop_to_zero: assert property (
        @(posedge clk) disable iff (reset) (!$past(reset) && (key == 32'h0) && ($past(key) != 32'h0)) |-> (internal_state == ($past(data_in) ^ $past(key)))
    );

    // With nonzero keys in two consecutive cycles, data_out equals (prev data_in ^ prev key) ^ current key.
    data_out_two_cycle_relation_when_key_nonzero_consecutive: assert property (
        @(posedge clk) disable iff (reset) (!$past(reset) && !$past(reset,2) && (key != 32'h0) && ($past(key) != 32'h0)) |-> (data_out == (($past(data_in) ^ $past(key)) ^ key))
    );

endmodule

rtl:
module calculator(
    input [7:0] a, b,
    input [1:0] op,
    output reg [7:0] result
);

always @(*) begin
    case(op)
        2'b00: result = a + b;
        2'b01: result = a - b;
        2'b10: result = a * b;
        2'b11: result = a / b;
    endcase
end

endmodule

sva:
module calculator_sva (
    // DUT ports
    input logic [7:0] a,
    input logic [7:0] b,
    input logic [1:0] op,
    input logic [7:0] result,
    // Checker clock (DUT is combinational; assertions are sampled on this clock)
    input logic clk
);
    // Analysis: No clock/reset in DUT; purely combinational; result selects a+b, a-b, a*b, a/b by op.

    // For op==00, result equals a+b truncated to 8 bits.
    check_add_operation: assert property (
        @(posedge clk) (op == 2'b00) |-> (result == (a + b)[7:0])
    );

    // For op==01, result equals a-b truncated to 8 bits.
    check_sub_operation: assert property (
        @(posedge clk) (op == 2'b01) |-> (result == (a - b)[7:0])
    );

    // For op==10, result equals low 8 bits of a*b.
    check_mul_operation: assert property (
        @(posedge clk) (op == 2'b10) |-> (result == (a * b)[7:0])
    );

    // For op==11 with nonzero divisor, result equals a/b.
    check_div_operation_nonzero: assert property (
        @(posedge clk) (op == 2'b11 && b != 8'd0) |-> (result == (a / b)[7:0])
    );

    // If inputs a,b,op do not change, result must not change.
    check_pure_function_stability: assert property (
        @(posedge clk) ($stable(a) && $stable(b) && $stable(op)) |-> $stable(result)
    );

    // For add: adding zero from a side yields the other operand.
    check_add_zero_a: assert property (
        @(posedge clk) (op == 2'b00 && a == 8'd0) |-> (result == b)
    );

    // For add: adding zero from b side yields the other operand.
    check_add_zero_b: assert property (
        @(posedge clk) (op == 2'b00 && b == 8'd0) |-> (result == a)
    );

    // For sub: subtracting zero yields the minuend.
    check_sub_zero: assert property (
        @(posedge clk) (op == 2'b01 && b == 8'd0) |-> (result == a)
    );

    // For sub: subtracting equal operands yields zero.
    check_sub_equal_zero: assert property (
        @(posedge clk) (op == 2'b01 && a == b) |-> (result == 8'd0)
    );

    // For mul: multiplying by zero on a side yields zero.
    check_mul_zero_a: assert property (
        @(posedge clk) (op == 2'b10 && a == 8'd0) |-> (result == 8'd0)
    );

    // For mul: multiplying by zero on b side yields zero.
    check_mul_zero_b: assert property (
        @(posedge clk) (op == 2'b10 && b == 8'd0) |-> (result == 8'd0)
    );

    // For mul: multiplying by one on a side yields the other operand.
    check_mul_one_a: assert property (
        @(posedge clk) (op == 2'b10 && a == 8'd1) |-> (result == b)
    );

    // For mul: multiplying by one on b side yields the other operand.
    check_mul_one_b: assert property (
        @(posedge clk) (op == 2'b10 && b == 8'd1) |-> (result == a)
    );

    // For div: dividing by one yields the dividend.
    check_div_one: assert property (
        @(posedge clk) (op == 2'b11 && b == 8'd1) |-> (result == a)
    );
endmodule

module d_flip_flop_sva (
    input logic clk,
    input logic d,
    input logic q
);
    // q equals previous cycle's d
    dff_q_eq_past_d: assert property (
        @(posedge clk) q == $past(d)
    );

    // If d changed since last cycle, q reflects previous d and not current d
    dff_d_change_implication: assert property (
        @(posedge clk) $changed(d) |-> (q == $past(d)) && (q != d)
    );

    // If d did not change since last cycle, q equals current d
    dff_d_nochange_eq_current: assert property (
        @(posedge clk) !$changed(d) |-> (q == d)
    );

    // If q changed since last cycle, then d changed in the prior cycle
    dff_q_change_implies_prior_d_change: assert property (
        @(posedge clk) $changed(q) |-> ($past(d) != $past(d,2))
    );

    // If d changed in the prior cycle, q changes this cycle
    dff_prior_d_change_implies_q_change: assert property (
        @(posedge clk) ($past(d) != $past(d,2)) |-> $changed(q)
    );
endmodule

rtl:
module top_module (
    input [1:0] in,
    output reg [15:0] out,
    output reg select
);

    wire [15:0] decoder_out;
    reg [3:0] select_bit;

    decoder_4to16 decoder(
        .in(in),
        .out(decoder_out)
    );

    always @(*) begin
        case (in)
            2'b00: select_bit = 4'b0001;
            2'b01: select_bit = 4'b0010;
            2'b10: select_bit = 4'b0100;
            2'b11: select_bit = 4'b1000;
        endcase
    end

    always @(*) begin
        out = 16'b0;
        out[select_bit] = 1'b1;
        select = select_bit != 4'b0000;
    end

endmodule

module decoder_4to16 (
    input [1:0] in,
    output reg [15:0] out
);

    always @(*) begin
        case (in)
            2'b00: out = 16'b0000000000000001;
            2'b01: out = 16'b0000000000000010;
            2'b10: out = 16'b0000000000000100;
            2'b11: out = 16'b0000000000001000;
        endcase
    end

endmodule

sva:
module top_module_sva (
    input  logic [1:0]  in,
    input  logic [15:0] out,
    input  logic        select,
    input  logic [3:0]  select_bit,
    input  logic [15:0] decoder_out
);
    // select_bit must encode 1<<in
    check_select_bit_shift: assert property (
        @(posedge in[0] or negedge in[0] or posedge in[1] or negedge in[1])
        select_bit == (4'b0001 << in)
    );

    // select_bit is never zero
    check_select_bit_nonzero: assert property (
        @(posedge in[0] or negedge in[0] or posedge in[1] or negedge in[1])
        select_bit != 4'b0000
    );

    // out equals 1 shifted by select_bit
    check_out_from_select_bit_shift: assert property (
        @(posedge in[0] or negedge in[0] or posedge in[1] or negedge in[1])
        out == (16'h0001 << select_bit)
    );

    // The selected bit of out is 1
    check_out_selected_bit_one: assert property (
        @(posedge in[0] or negedge in[0] or posedge in[1] or negedge in[1])
        out[select_bit] == 1'b1
    );

    // out is exactly one-hot
    check_out_onehot: assert property (
        @(posedge in[0] or negedge in[0] or posedge in[1] or negedge in[1])
        $onehot(out)
    );

    // Only bits {1,2,4,8} can ever be set in out
    check_out_legal_bits_only: assert property (
        @(posedge in[0] or negedge in[0] or posedge in[1] or negedge in[1])
        (out & ~(16'h0002 | 16'h0004 | 16'h0010 | 16'h0100)) == 16'h0000
    );

    // select reflects whether select_bit is non-zero
    check_select_matches_select_bit_nonzero: assert property (
        @(posedge in[0] or negedge in[0] or posedge in[1] or negedge in[1])
        select == (select_bit != 4'b0000)
    );

    // Mapping: in==00 -> out==0x0002
    check_out_map_in_00: assert property (
        @(posedge in[0] or negedge in[0] or posedge in[1] or negedge in[1])
        (in == 2'b00) |-> (out == 16'h0002)
    );

    // Mapping: in==01 -> out==0x0004
    check_out_map_in_01: assert property (
        @(posedge in[0] or negedge in[0] or posedge in[1] or negedge in[1])
        (in == 2'b01) |-> (out == 16'h0004)
    );

    // Mapping: in==10 -> out==0x0010
    check_out_map_in_10: assert property (
        @(posedge in[0] or negedge in[0] or posedge in[1] or negedge in[1])
        (in == 2'b10) |-> (out == 16'h0010)
    );

    // Mapping: in==11 -> out==0x0100
    check_out_map_in_11: assert property (
        @(posedge in[0] or negedge in[0] or posedge in[1] or negedge in[1])
        (in == 2'b11) |-> (out == 16'h0100)
    );

    // decoder_out is exactly one-hot
    check_decoder_out_onehot: assert property (
        @(posedge in[0] or negedge in[0] or posedge in[1] or negedge in[1])
        $onehot(decoder_out)
    );

    // decoder_out equals 1<<in (bits [0..3])
    check_decoder_out_shift: assert property (
        @(posedge in[0] or negedge in[0] or posedge in[1] or negedge in[1])
        decoder_out == (16'h0001 << in)
    );

    // decoder_out upper bits [15:4] are always zero
    check_decoder_out_high_bits_zero: assert property (
        @(posedge in[0] or negedge in[0] or posedge in[1] or negedge in[1])
        decoder_out[15:4] == 12'h000
    );
endmodule

module multi_input_output_sva (
    input logic [3:0] input1,
    input logic [1:0] input2,
    input logic input3,
    input logic input4,
    input logic input5,
    input logic input6,
    input logic input7,
    input logic input8,
    input logic output1
);
    // No clock/reset in RTL; combinational logic. Sample assertions on posedge of input3.

    // Output must equal the RTL's priority function.
    check_output1_function_equivalence: assert property (
        @(posedge input3)
            output1 == (
                ((input1 >= 4'b0110) && (input2 == 2'b10)) ||
                ( !((input1 >= 4'b0110) && (input2 == 2'b10)) &&
                  !(input3 && !input4) &&
                  (input5 && input6 && input7 && input8) )
            )
    );

    // If first condition holds, output1 must be 1.
    check_first_condition_sets_one: assert property (
        @(posedge input3)
            ((input1 >= 4'b0110) && (input2 == 2'b10)) |-> (output1 == 1'b1)
    );

    // If first is false and second holds, output1 must be 0.
    check_second_condition_sets_zero_when_first_false: assert property (
        @(posedge input3)
            (!((input1 >= 4'b0110) && (input2 == 2'b10)) &&
             (input3 == 1'b1) && (input4 == 1'b0)) |-> (output1 == 1'b0)
    );

    // If first and second are false and third holds, output1 must be 1.
    check_third_condition_sets_one_when_higher_false: assert property (
        @(posedge input3)
            (!((input1 >= 4'b0110) && (input2 == 2'b10)) &&
             !((input3 == 1'b1) && (input4 == 1'b0)) &&
             (input5 && input6 && input7 && input8)) |-> (output1 == 1'b1)
    );

    // If none of the conditions hold, output1 must be 0.
    check_default_sets_zero: assert property (
        @(posedge input3)
            (!((input1 >= 4'b0110) && (input2 == 2'b10)) &&
             !((input3 == 1'b1) && (input4 == 1'b0)) &&
             !(input5 && input6 && input7 && input8)) |-> (output1 == 1'b0)
    );

    // If output1 is 1, it must be due to the first or third condition per priority.
    check_no_spurious_one: assert property (
        @(posedge input3)
            (output1 == 1'b1) |-> (
                ((input1 >= 4'b0110) && (input2 == 2'b10)) ||
                (!((input1 >= 4'b0110) && (input2 == 2'b10)) &&
                 !((input3 == 1'b1) && (input4 == 1'b0)) &&
                 (input5 && input6 && input7 && input8))
            )
    );

    // If output1 is 0, it must be due to the second condition or default case.
    check_no_spurious_zero: assert property (
        @(posedge input3)
            (output1 == 1'b0) |-> (
                (!((input1 >= 4'b0110) && (input2 == 2'b10)) &&
                 (input3 == 1'b1) && (input4 == 1'b0)) ||
                (!((input1 >= 4'b0110) && (input2 == 2'b10)) &&
                 !((input3 == 1'b1) && (input4 == 1'b0)) &&
                 !(input5 && input6 && input7 && input8))
            )
    );

endmodule

rtl:
module RCB_FRL_count_to_16x(clk, rst, count, counter_value);

input clk, rst, count;
output [3:0] counter_value;

reg [3:0] counter_value_preserver;

assign counter_value = counter_value_preserver;

always@(posedge clk or posedge rst) begin
 if(rst == 1'b1) begin
   counter_value_preserver = 4'h0;
 end
 else if ( count == 1'b1 ) begin
   counter_value_preserver = counter_value_preserver + 1;
 end
 else begin
   counter_value_preserver = counter_value;
 end
end

endmodule

sva:
module RCB_FRL_count_to_16x_sva (
    input logic clk,
    input logic rst,          // active-high asynchronous reset
    input logic count,        // count enable
    input logic [3:0] counter_value
);
    // Reset high at a clock edge forces counter_value to 0.
    check_reset_level_forces_zero: assert property (
        @(posedge clk) rst |-> (counter_value == 4'h0)
    );

    // If reset is held high across consecutive clock edges, value stays 0.
    check_reset_held_keeps_zero: assert property (
        @(posedge clk) (rst && $past(rst)) |-> (counter_value == 4'h0)
    );

    // With no reset across the boundary and count=0, hold last value.
    check_hold_when_count_low: assert property (
        @(posedge clk) disable iff (rst)
            ($past(!rst) && ($past(count) == 1'b0)) |-> (counter_value == $past(counter_value))
    );

    // With no reset across the boundary and count=1, increment by 1 modulo 16.
    check_increment_when_count_high: assert property (
        @(posedge clk) disable iff (rst)
            ($past(!rst) && ($past(count) == 1'b1)) |-> (counter_value == (($past(counter_value) + 4'd1)[3:0]))
    );

    // Explicit wrap-around: from 4'hF with count=1 (no reset across), next is 4'h0.
    check_wrap_on_f_when_enabled: assert property (
        @(posedge clk) disable iff (rst)
            ($past(!rst) && ($past(count) == 1'b1) && ($past(counter_value) == 4'hF)) |-> (counter_value == 4'h0)
    );

    // Combined next-state function (no reset across): next = prev + (count?1:0) modulo 16.
    check_next_state_function: assert property (
        @(posedge clk) disable iff (rst)
            $past(!rst) |-> (counter_value == (($past(counter_value) + ($past(count) ? 4'd1 : 4'd0))[3:0]))
    );
