module four_bit_adder(
    input [3:0] A,
    input [3:0] B,
    output reg [3:0] S,
    output C
);

    wire [3:0] sum;
    wire carry;

    assign sum = A + B;
    assign C = (A[3] & B[3]) | ((A[3] | B[3]) & ~sum[3]);

    always @* begin
        if (C) begin
            S = sum + 4'b1;
        end else begin
            S = sum;
        end
    end

endmodule

sva:
module four_bit_adder_sva (
    input logic CLK,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] S,
    input logic C
);
    // C matches the RTL equation using A, B, and MSB of (A+B).
    check_c_equation: assert property (
        @(posedge CLK) C == ((A[3] & B[3]) | ((A[3] | B[3]) & ~((A + B)[3])))
    );

    // When no carry, S equals A+B (4-bit).
    check_s_no_carry: assert property (
        @(posedge CLK) (C == 1'b0) |-> (S == (A + B))
    );

    // When carry, S equals (A+B)+1 (4-bit end-around).
    check_s_with_carry: assert property (
        @(posedge CLK) (C == 1'b1) |-> (S == ((A + B) + 1'b1))
    );

    // S equals (A+B)+C (4-bit end-around sum).
    check_s_end_around: assert property (
        @(posedge CLK) S == ((A + B) + C)
    );

    // C equals the carry-out of 5-bit addition {0,A}+{0,B}.
    check_c_as_carryout: assert property (
        @(posedge CLK) C == (({1'b0, A} + {1'b0, B})[4])
    );

    // If both MSBs are 0, carry must be 0.
    check_c_zero_when_msb_zero: assert property (
        @(posedge CLK) ((A[3] == 1'b0) && (B[3] == 1'b0)) |-> (C == 1'b0)
    );

    // If both MSBs are 1, carry must be 1.
    check_c_one_when_msb_one: assert property (
        @(posedge CLK) ((A[3] == 1'b1) && (B[3] == 1'b1)) |-> (C == 1'b1)
    );

    // Carry high implies at least one MSB input is high.
    check_c_implies_any_msb_one: assert property (
        @(posedge CLK) (C == 1'b1) |-> (A[3] | B[3])
    );

    // With differing MSBs and sum[3]==0, carry must be 1.
    check_c_when_msb_diff_and_sum3_zero: assert property (
        @(posedge CLK) ((A[3] ^ B[3]) && (((A + B)[3]) == 1'b0)) |-> (C == 1'b1)
    );

    // With differing MSBs and sum[3]==1, carry must be 0.
    check_c_when_msb_diff_and_sum3_one: assert property (
        @(posedge CLK) ((A[3] ^ B[3]) && (((A + B)[3]) == 1'b1)) |-> (C == 1'b0)
    );
endmodule

module up_down_counter_sva (
    input logic clk,
    input logic UP,
    input logic DOWN,
    input logic LOAD,
    input logic [3:0] DIN,
    input logic [3:0] Q
);
    // Clock: clk (posedge). Reset: none.
    // Synchronous sequential counter with priority: LOAD > UP > DOWN.

    // When LOAD is high, Q loads DIN on the next cycle.
    check_load_updates_q: assert property (
        @(posedge clk) LOAD |=> (Q == $past(DIN))
    );

    // When LOAD=0 and UP=1, Q increments with wrap at 15.
    check_up_increments: assert property (
        @(posedge clk) (!LOAD && UP) |=> (Q == (($past(Q) == 4'hF) ? 4'h0 : ($past(Q) + 4'd1)))
    );

    // When LOAD=0, UP=0, and DOWN=1, Q decrements with wrap at 0.
    check_down_decrements: assert property (
        @(posedge clk) (!LOAD && !UP && DOWN) |=> (Q == (($past(Q) == 4'h0) ? 4'hF : ($past(Q) - 4'd1)))
    );

    // When LOAD=0 and UP=0 and DOWN=0, Q holds its value.
    check_hold_when_idle: assert property (
        @(posedge clk) (!LOAD && !UP && !DOWN) |=> (Q == $past(Q))
    );

    // When LOAD=0 and both UP and DOWN are 1, UP takes priority (count up).
    check_up_priority_over_down: assert property (
        @(posedge clk) (!LOAD && UP && DOWN) |=> (Q == (($past(Q) == 4'hF) ? 4'h0 : ($past(Q) + 4'd1)))
    );

    // Exact next-state function when LOAD=0 (encodes priority and wrap behavior).
    check_no_load_next_state_function: assert property (
        @(posedge clk) (!LOAD) |=> (
            Q == (
                $past(UP) ? (($past(Q) == 4'hF) ? 4'h0 : ($past(Q) + 4'd1)) :
                ($past(DOWN) ? (($past(Q) == 4'h0) ? 4'hF : ($past(Q) - 4'd1)) :
                $past(Q))
            )
        )
    );

endmodule

