sva:
module custom_and2_sva (
    input logic o,
    input logic i0,
    input logic i1
);
    // Output equals i0 & i1 when i0 rises.
    check_and_on_i0_posedge: assert property (
        @(posedge i0) disable iff (1'b0) o === (i0 & i1)
    );
    // Output equals i0 & i1 when i1 rises.
    check_and_on_i1_posedge: assert property (
        @(posedge i1) disable iff (1'b0) o === (i0 & i1)
    );
    // Output equals i0 & i1 when o rises.
    check_and_on_o_posedge: assert property (
        @(posedge o) disable iff (1'b0) o === (i0 & i1)
    );
    // o can only rise when both inputs are 1.
    check_o_rise_requires_inputs_high: assert property (
        @(posedge o) disable iff (1'b0) (i0 === 1'b1) && (i1 === 1'b1)
    );
endmodule

rtl:
module sky130_fd_sc_ms__sdfbbn (
    D      , // moved to the beginning of the list
    SCD    ,
    SCE    ,
    CLK    ,
    SET_B  ,
    RESET_B,
    Q      ,
    Q_N    ,
    VPWR   ,
    VGND   ,
    VPB    ,
    VNB
);

    input  D      ;
    input  SCD    ;
    input  SCE    ;
    input  CLK    ;
    input  SET_B  ;
    input  RESET_B;
    output Q      ;
    output Q_N    ;
    input  VPWR   ;
    input  VGND   ;
    input  VPB    ;
    input  VNB    ;

    reg Q_N;  // Removed assignment to Q_N from reg type to wire type

    // Inverted the Q output to match the Q_N output
    assign Q = ~Q_N;

    reg [1:0] state;

    always @ (posedge CLK) begin
        if (SET_B == 1'b0) begin
            Q_N <= 1'b1;
        end
        if (RESET_B == 1'b0) begin
            Q_N <= 1'b0;
        end
        if (SCE) begin
            Q_N <= D;
        end
        if (SCD) begin
            Q_N <= 1'b0;
        end
    end

endmodule

sva:
module sky130_fd_sc_ms__sdfbbn_sva (
    input logic D,
    input logic SCD,
    input logic SCE,
    input logic CLK,
    input logic SET_B,
    input logic RESET_B,
    input logic Q,
    input logic Q_N,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB
);
    // Clock: CLK. Resets: SET_B, RESET_B (active-low, synchronous).
    // Sequential FF with priority: SCD > SCE > !RESET_B > !SET_B. Q = ~Q_N.

    // Q is always inverse of Q_N.
    check_q_inverts_qn: assert property (
        @(posedge CLK) disable iff (!SET_B || !RESET_B) (Q == ~Q_N)
    );

    // SCD high forces Q_N to 0 on the next cycle.
    check_scd_forces_zero: assert property (
        @(posedge CLK) disable iff (!SET_B || !RESET_B) SCD |=> (Q_N == 1'b0)
    );

    // With SCE high and SCD low, Q_N loads D on the next cycle.
    check_sce_loads_d_no_scd: assert property (
        @(posedge CLK) disable iff (!SET_B || !RESET_B) (SCE && !SCD) |=> (Q_N == $past(D))
    );

    // With RESET_B low and no later overrides, Q_N goes to 0 on the next cycle.
    check_reset_forces_zero_when_unoverridden: assert property (
        @(posedge CLK) (RESET_B == 1'b0) && (SCE == 1'b0) && (SCD == 1'b0) |=> (Q_N == 1'b0)
    );

    // With SET_B low and no later overrides, Q_N goes to 1 on the next cycle.
    check_set_forces_one_when_unoverridden: assert property (
        @(posedge CLK) (SET_B == 1'b0) && (RESET_B == 1'b1) && (SCE == 1'b0) && (SCD == 1'b0) |=> (Q_N == 1'b1)
    );

    // If SET_B and RESET_B both low (no SCE/SCD), RESET_B wins driving 0.
    check_reset_overrides_set: assert property (
        @(posedge CLK) (SET_B == 1'b0) && (RESET_B == 1'b0) && (SCE == 1'b0) && (SCD == 1'b0) |=> (Q_N == 1'b0)
    );

    // If RESET_B low and SCE high (no SCD), SCE overrides and Q_N loads D.
    check_sce_overrides_reset: assert property (
        @(posedge CLK) (RESET_B == 1'b0) && (SCE == 1'b1) && (SCD == 1'b0) |=> (Q_N == $past(D))
    );

    // When SET_B, RESET_B deasserted and SCE/SCD low, Q_N holds its value.
    check_hold_when_no_ctrls: assert property (
        @(posedge CLK) disable iff (!SET_B || !RESET_B) (SET_B == 1'b1) && (RESET_B == 1'b1) && (SCE == 1'b0) && (SCD == 1'b0) |=> (Q_N == $past(Q_N))
    );

    // After SCE load (no SCD), Q reflects ~D on next cycle.
    check_q_updates_after_sce: assert property (
        @(posedge CLK) disable iff (!SET_B || !RESET_B) (SCE && !SCD) |=> (Q == ~$past(D))
    );

    // After SCD high, Q goes to 1 on the next cycle.
    check_q_one_after_scd: assert property (
        @(posedge CLK) disable iff (!SET_B || !RESET_B) SCD |=> (Q == 1'b1)
    );
endmodule

rtl:
module decoder_2to4 (
  input wire [1:0] in_data,
  output reg [3:0] out_data
);

always @(in_data) begin
  case (in_data)
    2'b00: out_data <= 4'b0001;
    2'b01: out_data <= 4'b0010;
    2'b10: out_data <= 4'b0100;
    2'b11: out_data <= 4'b1000;
    default: out_data <= 4'b0000;
  endcase
end

endmodule

sva:
module decoder_2to4_sva (
  input logic clk,              // sampling clock for assertions (RTL has no clock)
  input logic [1:0] in_data,    // DUT input
  input logic [3:0] out_data    // DUT output
);
  // RTL: no reset, purely combinational 2->4 one-hot decoder with default to 0000 on unknown input

  // Input 00 decodes to 0001.
  decode_map_00: assert property (
    @(posedge clk) disable iff ($initstate) (in_data == 2'b00) |-> (out_data == 4'b0001)
  );

  // Input 01 decodes to 0010.
  decode_map_01: assert property (
    @(posedge clk) disable iff ($initstate) (in_data == 2'b01) |-> (out_data == 4'b0010)
  );

  // Input 10 decodes to 0100.
  decode_map_10: assert property (
    @(posedge clk) disable iff ($initstate) (in_data == 2'b10) |-> (out_data == 4'b0100)
  );

  // Input 11 decodes to 1000.
  decode_map_11: assert property (
    @(posedge clk) disable iff ($initstate) (in_data == 2'b11) |-> (out_data == 4'b1000)
  );

  // Output 0001 implies known input 00.
  reverse_map_0001: assert property (
    @(posedge clk) disable iff ($initstate) (!$isunknown(in_data) && (out_data == 4'b0001)) |-> (in_data == 2'b00)
  );

  // Output 0010 implies known input 01.
  reverse_map_0010: assert property (
    @(posedge clk) disable iff ($initstate) (!$isunknown(in_data) && (out_data == 4'b0010)) |-> (in_data == 2'b01)
  );

  // Output 0100 implies known input 10.
  reverse_map_0100: assert property (
    @(posedge clk) disable iff ($initstate) (!$isunknown(in_data) && (out_data == 4'b0100)) |-> (in_data == 2'b10)
  );

  // Output 1000 implies known input 11.
  reverse_map_1000: assert property (
    @(posedge clk) disable iff ($initstate) (!$isunknown(in_data) && (out_data == 4'b1000)) |-> (in_data == 2'b11)
  );

  // Known input must produce a one-hot output.
  known_in_onehot_out: assert property (
    @(posedge clk) disable iff ($initstate) (!$isunknown(in_data)) |-> $onehot(out_data)
  );

  // Unknown input forces output to 0000 (default case).
  unknown_in_zero_out: assert property (
    @(posedge clk) disable iff ($initstate) $isunknown(in_data) |-> (out_data == 4'b0000)
  );

endmodule

module mux_2to1_behavioral_sva (
  input logic [3:0] a,
  input logic [3:0] b,
  input logic       s,
  input logic [3:0] mux_out
);

  // On any input edge, mux_out equals selected input based on s.
  check_function_on_input_edges: assert property (
    @(posedge s or negedge s
      or posedge a[0] or negedge a[0]
      or posedge a[1] or negedge a[1]
      or posedge a[2] or negedge a[2]
      or posedge a[3] or negedge a[3]
      or posedge b[0] or negedge b[0]
      or posedge b[1] or negedge b[1]
      or posedge b[2] or negedge b[2]
      or posedge b[3] or negedge b[3])
    ((s == 1'b0) && (mux_out == a)) || ((s == 1'b1) && (mux_out == b))
  );

  // On select rising edge, mux_out must equal b.
  check_out_follows_b_on_s_rise: assert property (
    @(posedge s) mux_out == b
  );

  // On select falling edge, mux_out must equal a.
  check_out_follows_a_on_s_fall: assert property (
    @(negedge s) mux_out == a
  );

  // With s=0, any change on a must be reflected on mux_out.
  check_a_change_reflected_when_s0: assert property (
    @(posedge a[0] or negedge a[0]
      or posedge a[1] or negedge a[1]
      or posedge a[2] or negedge a[2]
      or posedge a[3] or negedge a[3])
    (s == 1'b0) |-> (mux_out == a)
  );

  // With s=1, any change on b must be reflected on mux_out.
  check_b_change_reflected_when_s1: assert property (
    @(posedge b[0] or negedge b[0]
      or posedge b[1] or negedge b[1]
      or posedge b[2] or negedge b[2]
      or posedge b[3] or negedge b[3])
    (s == 1'b1) |-> (mux_out == b)
  );

  // On any change of mux_out, it must equal the currently selected input.
  check_out_is_consistent_on_out_change: assert property (
    @(posedge mux_out[0] or negedge mux_out[0]
      or posedge mux_out[1] or negedge mux_out[1]
      or posedge mux_out[2] or negedge mux_out[2]
      or posedge mux_out[3] or negedge mux_out[3])
    ((s == 1'b0) && (mux_out == a)) || ((s == 1'b1) && (mux_out == b))
  );

endmodule

rtl:
module mux4to1 (
  input [3:0] in,
  input [1:0] sel,
  output reg out
);

  always @ (sel or in) begin
    case (sel)
      2'b00: out <= in[0];
      2'b01: out <= in[1];
      2'b10: out <= in[2];
      2'b11: out <= in[3];
    endcase
  end

endmodule

sva:
module mux4to1_sva (
  input logic CLK,
  input logic [3:0] in,
  input logic [1:0] sel,
  input logic out
);
  // No clock/reset in RTL; sampled on external CLK. Combinational mux behavior.

  // Out equals the bit selected by sel.
  check_mux_function: assert property (
    @(posedge CLK) (out === in[sel])
  );

  // When sel==00, out mirrors in[0].
  check_sel_00: assert property (
    @(posedge CLK) (sel == 2'b00) |-> (out === in[0])
  );

  // When sel==01, out mirrors in[1].
  check_sel_01: assert property (
    @(posedge CLK) (sel == 2'b01) |-> (out === in[1])
  );

  // When sel==10, out mirrors in[2].
  check_sel_10: assert property (
    @(posedge CLK) (sel == 2'b10) |-> (out === in[2])
  );

  // When sel==11, out mirrors in[3].
  check_sel_11: assert property (
    @(posedge CLK) (sel == 2'b11) |-> (out === in[3])
  );

  // If in and sel are stable, out must be stable.
  check_out_stable_when_inputs_stable: assert property (
    @(posedge CLK) ($stable(in) && $stable(sel)) |-> $stable(out)
  );

  // With sel stable, changing non-selected inputs does not change out.
  check_nonselected_inputs_do_not_affect_out: assert property (
    @(posedge CLK) ($stable(sel) && $changed(in) && !$changed(in[sel])) |-> $stable(out)
  );

  // With sel stable, changing the selected input changes out.
  check_out_follows_selected_input_change: assert property (
    @(posedge CLK) ($stable(sel) && $changed(in[sel])) |-> $changed(out)
  );

endmodule

rtl:
module mux64 #(parameter MUX_SIZE = 64)
  (input [MUX_SIZE-1:0] datai,
   input [6-1:0] A,
   input [6-1:0] B,
   input [6-1:0] C,
   output reg datao
   );

   always @(*)
   begin
      case({C,B,A})
         {6{1'b0}}: datao = datai[0];
         {6{1'b0}}, 31: datao = datai[1];
         {6{1'b0}}, 32: datao = datai[0];
         default: datao = datai[1];
      endcase
   end

endmodule

sva:
module mux64_sva #(
    parameter MUX_SIZE = 64
) (
    input  logic                 clk,
    input  logic [MUX_SIZE-1:0]  datai,
    input  logic [5:0]           A,
    input  logic [5:0]           B,
    input  logic [5:0]           C,
    input  logic                 datao
);

    // When concatenation equals 0, datao must be datai[0].
    sel_0_routes_bit0: assert property (
        @(posedge clk) disable iff (1'b0) ({C,B,A} == 18'd0) |-> (datao == datai[0])
    );

    // When concatenation equals 32, datao must be datai[0].
    sel_32_routes_bit0: assert property (
        @(posedge clk) disable iff (1'b0) ({C,B,A} == 18'd32) |-> (datao == datai[0])
    );

    // When concatenation is neither 0 nor 32, datao must be datai[1].
    other_sel_routes_bit1: assert property (
        @(posedge clk) disable iff (1'b0) !(({C,B,A} == 18'd0) || ({C,B,A} == 18'd32)) |-> (datao == datai[1])
    );

    // Explicit check for 31 case label: datao must be datai[1].
    sel_31_routes_bit1: assert property (
        @(posedge clk) disable iff (1'b0) ({C,B,A} == 18'd31) |-> (datao == datai[1])
    );

    // Output must always equal either datai[0] or datai[1].
    output_from_bit0_or_bit1_only: assert property (
        @(posedge clk) disable iff (1'b0) 1'b1 |-> ((datao == datai[0]) || (datao == datai[1]))
    );

    // If datai[0] equals datai[1], datao equals that value regardless of select.
    equal_inputs_pass_through: assert property (
        @(posedge clk) disable iff (1'b0) (datai[0] === datai[1]) |-> (datao == datai[0])
    );

    // If selection stays in {0,32} across cycles and datai[0] is stable, datao is stable.
    stable_when_in_bit0_region: assert property (
        @(posedge clk) disable iff (1'b0)
            $past((({C,B,A} == 18'd0) || ({C,B,A} == 18'd32))) &&
            (({C,B,A} == 18'd0) || ({C,B,A} == 18'd32)) &&
            ($past(datai[0]) == datai[0]) |-> (datao == $past(datao))
    );

    // If selection stays outside {0,32} across cycles and datai[1] is stable, datao is stable.
    stable_when_in_bit1_region: assert property (
        @(posedge clk) disable iff (1'b0)
            !$past((({C,B,A} == 18'd0) || ({C,B,A} == 18'd32))) &&
            !((({C,B,A} == 18'd0) || ({C,B,A} == 18'd32))) &&
            ($past(datai[1]) == datai[1]) |-> (datao == $past(datao))
    );

    // If inputs differ and datao equals datai[0], select must be 0 or 32.
    di0_implies_bit0_region_when_inputs_differ: assert property (
        @(posedge clk) disable iff (1'b0)
            ((datai[0] != datai[1]) && (datao == datai[0])) |-> (({C,B,A} == 18'd0) || ({C,B,A} == 18'd32))
    );

    // If inputs differ and select is not {0,32}, datao must be datai[1].
    non_bit0_region_implies_di1_when_inputs_differ: assert property (
        @(posedge clk) disable iff (1'b0)
            ((datai[0] != datai[1]) && !((({C,B,A} == 18'd0) || ({C,B,A} == 18'd32)))) |-> (datao == datai[1])
    );

endmodule

rtl:
module and4b (
    input  A_N ,
    input  B   ,
    input  C   ,
    input  D   ,
    output X   ,
    input  VPB ,
    input  VPWR,
    input  VGND,
    input  VNB
);
    wire AB, CD, ABCD;

    // AND gates for AB and CD
    and gate_AB(AB, A_N, B);
    and gate_CD(CD, C, D);

    // AND gate for ABCD
    and gate_ABCD(ABCD, AB, CD);

    // Inverter for X
    not inv_X(X, ABCD);

endmodule

sva:
module and4b_sva (
    input logic CLK,   // external checker clock; DUT has no clock/reset
    input logic A_N,
    input logic B,
    input logic C,
    input logic D,
    input logic X,
    input logic VPB,
    input logic VPWR,
    input logic VGND,
    input logic VNB
);

    // X equals NAND of A_N, B, C, D.
    check_function_nand_equivalence: assert property (
        @(posedge CLK) X == ~(A_N & B & C & D)
    );

    // When all inputs are HIGH, X must be LOW.
    check_all_high_implies_X_low: assert property (
        @(posedge CLK) (A_N && B && C && D) |-> (X == 1'b0)
    );

    // When any input is LOW, X must be HIGH.
    check_any_low_implies_X_high: assert property (
        @(posedge CLK) ((!A_N) || (!B) || (!C) || (!D)) |-> (X == 1'b1)
    );

    // If X is LOW, then all inputs must be HIGH.
    check_X_low_implies_all_high: assert property (
        @(posedge CLK) (X == 1'b0) |-> (A_N && B && C && D)
    );

    // If X is HIGH, then at least one input is LOW.
    check_X_high_implies_any_low: assert property (
        @(posedge CLK) (X == 1'b1) |-> ((!A_N) || (!B) || (!C) || (!D))
    );

    // With B,C,D HIGH, X equals NOT A_N.
    check_dep_A: assert property (
        @(posedge CLK) (B && C && D) |-> (X == ~A_N)
    );

    // With A_N,C,D HIGH, X equals NOT B.
    check_dep_B: assert property (
        @(posedge CLK) (A_N && C && D) |-> (X == ~B)
    );

    // With A_N,B,D HIGH, X equals NOT C.
    check_dep_C: assert property (
        @(posedge CLK) (A_N && B && D) |-> (X == ~C)
    );

    // With A_N,B,C HIGH, X equals NOT D.
    check_dep_D: assert property (
        @(posedge CLK) (A_N && B && C) |-> (X == ~D)
    );

endmodule

rtl:
module bitwise_operators (
  input [7:0] in1,
  input [7:0] in2,
  output [7:0] out_and,
  output [7:0] out_or,
  output [7:0] out_xor,
  output [7:0] out_not
);

  assign out_and = in1 & in2;
  assign out_or = in1 | in2;
  assign out_xor = in1 ^ in2;
  assign out_not = ~in1;

endmodule

sva:
module bitwise_operators_sva (
  input logic CLK,
  input logic [7:0] in1,
  input logic [7:0] in2,
  input logic [7:0] out_and,
  input logic [7:0] out_or,
  input logic [7:0] out_xor,
  input logic [7:0] out_not
);

  // out_and equals bitwise AND of inputs.
  check_out_and_function: assert property (
    @(posedge CLK) out_and == (in1 & in2)
  );

  // out_or equals bitwise OR of inputs.
  check_out_or_function: assert property (
    @(posedge CLK) out_or == (in1 | in2)
  );

  // out_xor equals bitwise XOR of inputs.
  check_out_xor_function: assert property (
    @(posedge CLK) out_xor == (in1 ^ in2)
  );

  // out_not equals bitwise NOT of in1.
  check_out_not_function: assert property (
    @(posedge CLK) out_not == ~in1
  );

  // De Morgan for OR: a|b == ~(~a & ~b).
  check_or_demorgan: assert property (
    @(posedge CLK) out_or == ~(~in1 & ~in2)
  );

  // De Morgan for AND: a&b == ~(~a | ~b).
  check_and_demorgan: assert property (
    @(posedge CLK) out_and == ~(~in1 | ~in2)
  );

  // OR equals (AND | XOR) for same operands.
  check_or_is_and_or_xor: assert property (
    @(posedge CLK) out_or == (out_and | out_xor)
  );

  // XOR equals OR AND NOT(AND) for same operands.
  check_xor_is_or_andnot_and: assert property (
    @(posedge CLK) out_xor == (out_or & ~out_and)
  );

  // AND and XOR are bitwise disjoint.
  check_and_xor_mutex: assert property (
    @(posedge CLK) (out_and & out_xor) == '0
  );

  // in1 and its complement are bitwise disjoint.
  check_in1_out_not_mutex: assert property (
    @(posedge CLK) (in1 & out_not) == '0
  );

  // in1 XOR ~in1 yields all ones.
  check_in1_xor_out_not_allones: assert property (
    @(posedge CLK) (in1 ^ out_not) == 8'hFF
  );

  // If out_and changes, at least one input changed.
  check_out_and_change_has_input_change: assert property (
    @(posedge CLK) $changed(out_and) |-> ($changed(in1) || $changed(in2))
  );

  // If out_or changes, at least one input changed.
  check_out_or_change_has_input_change: assert property (
    @(posedge CLK) $changed(out_or) |-> ($changed(in1) || $changed(in2))
  );

  // If out_xor changes, at least one input changed.
  check_out_xor_change_has_input_change: assert property (
    @(posedge CLK) $changed(out_xor) |-> ($changed(in1) || $changed(in2))
  );

  // If out_not changes, in1 changed.
  check_out_not_change_has_in1_change: assert property (
    @(posedge CLK) $changed(out_not) |-> $changed(in1)
  );

endmodule

module priority_encoder_sva (
    input logic clk,
    input logic [7:0] in,
    input logic [2:0] pos
);
    // If in[7] is 1, pos must be 7 (highest priority).
    check_priority_bit7: assert property (
        @(posedge clk) in[7] |-> (pos == 3'd7)
    );

    // If in[6] is 1 and in[7] is 0, pos must be 6.
    check_priority_bit6: assert property (
        @(posedge clk) (!in[7] && in[6]) |-> (pos == 3'd6)
    );

    // If in[5] is 1 and in[7:6] are 0, pos must be 5.
    check_priority_bit5: assert property (
        @(posedge clk) ((in[7:6] == 2'b00) && in[5]) |-> (pos == 3'd5)
    );

    // If in[4] is 1 and in[7:5] are 0, pos must be 4.
    check_priority_bit4: assert property (
        @(posedge clk) ((in[7:5] == 3'b000) && in[4]) |-> (pos == 3'd4)
    );

    // If in[3] is 1 and in[7:4] are 0, pos must be 3.
    check_priority_bit3: assert property (
        @(posedge clk) ((in[7:4] == 4'b0000) && in[3]) |-> (pos == 3'd3)
    );

    // If in[2] is 1 and in[7:3] are 0, pos must be 2.
    check_priority_bit2: assert property (
        @(posedge clk) ((in[7:3] == 5'b00000) && in[2]) |-> (pos == 3'd2)
    );

    // If in[1] is 1 and in[7:2] are 0, pos must be 1.
    check_priority_bit1: assert property (
        @(posedge clk) ((in[7:2] == 6'b000000) && in[1]) |-> (pos == 3'd1)
    );

    // If only in[0] is 1 (no higher bits), pos must be 0.
    check_priority_bit0: assert property (
        @(posedge clk) ((in[7:1] == 7'b0000000) && in[0]) |-> (pos == 3'd0)
    );

    // If all inputs are 0, pos must be 0.
    check_zero_input: assert property (
        @(posedge clk) (in == 8'b0000_0000) |-> (pos == 3'd0)
    );

    // If pos is 7, then in[7] must be 1.
    check_inverse_pos7_requires_in7: assert property (
        @(posedge clk) (pos == 3'd7) |-> in[7]
    );

    // If pos is 6, then in[7] must be 0 and in[6] must be 1.
    check_inverse_pos6_requires_in6_and_no7: assert property (
        @(posedge clk) (pos == 3'd6) |-> (!in[7] && in[6])
    );

    // If pos is 0, no higher bits [7:1] may be set.
    check_inverse_pos0_blocks_higher: assert property (
        @(posedge clk) (pos == 3'd0) |-> (in[7:1] == 7'b0000000)
    );
endmodule

rtl:
module counter_4bit(clk, rst, q);

input clk, rst;
output reg [3:0] q;

always @(posedge clk) begin
	if (rst == 1'b1) // Synchronous reset
		q <= 4'b0;
	else if (q == 4'b1111) // Counter rolls over to 0
		q <= 4'b0;
	else
		q <= q + 1; // Counter increments
end

endmodule

sva:
module counter_4bit_sva (
    input logic clk,
    input logic rst,
    input logic [3:0] q
);
    // Synchronous reset drives q to 0 on the reset cycle.
    check_reset_sets_zero: assert property (
        @(posedge clk) rst |-> (q == 4'b0000)
    );

    // When not in reset in consecutive cycles and prev q != 15, q increments by 1.
    check_increment_when_not_max: assert property (
        @(posedge clk) disable iff (rst)
            ($past(!rst) && ($past(q) != 4'hF)) |-> (q == ($past(q) + 4'h1))
    );

    // When not in reset in consecutive cycles and prev q == 15, q rolls over to 0.
    check_rollover_when_max: assert property (
        @(posedge clk) disable iff (rst)
            ($past(!rst) && ($past(q) == 4'hF)) |-> (q == 4'h0)
    );

    // First non-reset cycle after reset deasserts produces q == 1.
    check_first_cycle_after_reset: assert property (
        @(posedge clk) disable iff (rst)
            ($past(rst) && !rst) |-> (q == 4'h1)
    );

    // Without reset now and previously, q==0 can only follow a previous 15.
    check_zero_only_after_max_without_reset: assert property (
        @(posedge clk) disable iff (rst)
            ($past(!rst) && !rst && (q == 4'h0)) |-> ($past(q) == 4'hF)
    );
endmodule

