rtl:
module baud_generator(
    input clk,
    output reg pulse
);

parameter BAUD_RATE = 4800;
parameter CLOCK_FREQ = 50000000;

reg [15:0] counter = 0;
reg [15:0] compare_value = CLOCK_FREQ / BAUD_RATE;

always @(posedge clk) begin
    counter <= counter + 1;
    if (counter == compare_value) begin
        pulse <= 1;
        counter <= 0;
    end else begin
        pulse <= 0;
    end
end

endmodule

sva:
module baud_generator_sva (
    input logic clk,
    input logic pulse,
    input logic [15:0] counter,
    input logic [15:0] compare_value
);
    ///// Parameter register behavior /////
    // compare_value must remain constant after the first cycle.
    hold_compare_value_constant: assert property (
        @(posedge clk) $past(1'b1) |-> (compare_value == $past(compare_value))
    );

    ///// Counter update rules /////
    // Counter update is either reset to 0 or increments by 1 each cycle.
    counter_update_is_reset_or_inc: assert property (
        @(posedge clk) $past(1'b1) |-> (counter == 16'd0 || counter == ($past(counter) + 16'd1))
    );

    // When last-cycle counter equaled compare_value, counter resets to 0.
    counter_resets_on_match: assert property (
        @(posedge clk) ($past(1'b1) && ($past(counter) == compare_value)) |-> (counter == 16'd0)
    );

    // When last-cycle counter did not equal compare_value, counter increments by 1.
    counter_increments_on_no_match: assert property (
        @(posedge clk) ($past(1'b1) && ($past(counter) != compare_value)) |-> (counter == ($past(counter) + 16'd1))
    );

    ///// Pulse generation rules /////
    // Pulse reflects whether last-cycle counter matched compare_value.
    pulse_reflects_prev_compare: assert property (
        @(posedge clk) $past(1'b1) |-> (pulse == ($past(counter) == compare_value))
    );

    // If pulse is high, counter must be 0 in the same cycle.
    pulse_implies_counter_zero: assert property (
        @(posedge clk) pulse |-> (counter == 16'd0)
    );

    ///// Corner cases due to 16-bit arithmetic /////
    // If counter becomes 0 without a compare match, the previous value must have been 16'hFFFF (overflow wrap).
    overflow_to_zero_requires_ffff: assert property (
        @(posedge clk) ($past(1'b1) && ($past(counter) != compare_value) && (counter == 16'd0)) |-> ($past(counter) == 16'hFFFF)
    );

    // If counter is 0 this cycle, it must be due to either a compare match or overflow from 16'hFFFF.
    counter_zero_causes: assert property (
        @(posedge clk) ($past(1'b1) && (counter == 16'd0)) |-> (($past(counter) == compare_value) || ($past(counter) == 16'hFFFF))
    );
endmodule

bind baud_generator baud_generator_sva u_baud_generator_sva (
    .clk(clk),
    .pulse(pulse),
    .counter(counter),
    .compare_value(compare_value)
);

rtl:
module alu_32bit (
    input [31:0] A,
    input [31:0] B,
    input [2:0] OPCODE,
    input CIN,
    output reg COUT,
    output reg [31:0] Y
);

    always @(*) begin
        case(OPCODE)
            3'b000: Y = A + B + CIN;
            3'b001: Y = A - B - ~CIN;
            3'b010: Y = A & B;
            3'b011: Y = A | B;
            3'b100: Y = A ^ B;
            3'b101: Y = A << B;
            3'b110: Y = A >> B;
            default: Y = 0;
        endcase
        if(OPCODE[1:0] == 2'b00) begin
            COUT = (Y[31] ^ CIN) & (OPCODE[2] ^ Y[30]);
        end else if(OPCODE[1:0] == 2'b01) begin
            COUT = (A[31] ^ B[31] ^ Y[31]) & (A[31] ^ CIN);
        end else begin
            COUT = 0;
        end
    end

endmodule

sva:
module alu_32bit_sva (
    input logic CLK,
    input logic RESETn,        // Active-low reset for sampling; DUT has no reset
    input logic [31:0] A,
    input logic [31:0] B,
    input logic [2:0]  OPCODE,
    input logic        CIN,
    input logic        COUT,
    input logic [31:0] Y
);
    // DUT is purely combinational (no clock/reset); assertions are sampled on CLK.

    // Y matches add with carry-in when OPCODE==000.
    check_y_add: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (OPCODE == 3'b000) |-> (Y == (A + B + CIN))
    );

    // Y matches subtract with inverted borrow when OPCODE==001.
    check_y_sub: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (OPCODE == 3'b001) |-> (Y == (A - B - ~CIN))
    );

    // Y matches bitwise AND when OPCODE==010.
    check_y_and: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (OPCODE == 3'b010) |-> (Y == (A & B))
    );

    // Y matches bitwise OR when OPCODE==011.
    check_y_or: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (OPCODE == 3'b011) |-> (Y == (A | B))
    );

    // Y matches bitwise XOR when OPCODE==100.
    check_y_xor: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (OPCODE == 3'b100) |-> (Y == (A ^ B))
    );

    // Y matches logical shift-left by B when OPCODE==101.
    check_y_sll: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (OPCODE == 3'b101) |-> (Y == (A << B))
    );

    // Y matches logical shift-right by B when OPCODE==110.
    check_y_srl: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (OPCODE == 3'b110) |-> (Y == (A >> B))
    );

    // Y is zero in default case when OPCODE==111.
    check_y_default_zero: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (OPCODE == 3'b111) |-> (Y == 32'd0)
    );

    // COUT equation when OPCODE[1:0]==00.
    check_cout_for_op00: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (OPCODE[1:0] == 2'b00) |-> (COUT == ((Y[31] ^ CIN) & (OPCODE[2] ^ Y[30])))
    );

    // COUT equation when OPCODE[1:0]==01.
    check_cout_for_op01: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (OPCODE[1:0] == 2'b01) |-> (COUT == ((A[31] ^ B[31] ^ Y[31]) & (A[31] ^ CIN)))
    );

    // COUT is zero when OPCODE[1:0] is 10 or 11.
    check_cout_zero_for_op10_11: assert property (
        @(posedge CLK) disable iff (!RESETn)
        ((OPCODE[1:0] == 2'b10) || (OPCODE[1:0] == 2'b11)) |-> (COUT == 1'b0)
    );

endmodule

rtl:
module priority_encoder (in0, in1, out);
input in0;
input in1;
output reg [1:0] out;

always @ (in0, in1) begin
    if (in0 && !in1) // in0 is high and in1 is low
        out <= 2'b01;
    else if (!in0 && in1) // in0 is low and in1 is high
        out <= 2'b10;
    else if (in0 && in1) // both inputs are high
        out <= 2'b10;
    else // both inputs are low
        out <= 2'b00;
end

endmodule

sva:
module priority_encoder_sva (
    input logic in0,
    input logic in1,
    input logic [1:0] out
);
    // Combinational DUT with no clock/reset; sample assertions on any input edge.

    // Out must equal the encoded function of inputs.
    check_out_encoding: assert property (
        @(posedge in0 or negedge in0 or posedge in1 or negedge in1) out == {in1, (in0 && !in1)}
    );

    // If in1 is high, output must be 2'b10 (in1 has priority).
    check_in1_priority_to_10: assert property (
        @(posedge in0 or negedge in0 or posedge in1 or negedge in1) in1 |-> (out == 2'b10)
    );

    // If only in0 is high, output must be 2'b01.
    check_in0_only_to_01: assert property (
        @(posedge in0 or negedge in0 or posedge in1 or negedge in1) (in0 && !in1) |-> (out == 2'b01)
    );

    // If both inputs are low, output must be 2'b00.
    check_both_low_to_00: assert property (
        @(posedge in0 or negedge in0 or posedge in1 or negedge in1) (!in0 && !in1) |-> (out == 2'b00)
    );

    // Output must never be 2'b11.
    check_out_not_11: assert property (
        @(posedge in0 or negedge in0 or posedge in1 or negedge in1) out != 2'b11
    );

    // MSB equals in1.
    check_msb_matches_in1: assert property (
        @(posedge in0 or negedge in0 or posedge in1 or negedge in1) out[1] == in1
    );

    // LSB equals in0 & ~in1.
    check_lsb_logic: assert property (
        @(posedge in0 or negedge in0 or posedge in1 or negedge in1) out[0] == (in0 && !in1)
    );

    // If LSB is 1, then in0=1 and in1=0.
    check_lsb_one_implies_inputs: assert property (
        @(posedge in0 or negedge in0 or posedge in1 or negedge in1) out[0] |-> (in0 && !in1)
    );

    // If MSB is 1, then in1=1.
    check_msb_one_implies_in1: assert property (
        @(posedge in0 or negedge in0 or posedge in1 or negedge in1) out[1] |-> in1
    );

    // When in1 is high, LSB must be 0.
    check_lsb_zero_when_in1_high: assert property (
        @(posedge in0 or negedge in0 or posedge in1 or negedge in1) in1 |-> (out[0] == 1'b0)
    );
endmodule

rtl:
module sky130_fd_sc_lp__fahcon (
    COUT_N,
    SUM   ,
    A     ,
    B     ,
    CI
);

    output COUT_N;
    output SUM   ;
    input  A     ;
    input  B     ;
    input  CI    ;

    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    wire xor0_out_SUM ;
    wire a_b          ;
    wire a_ci         ;
    wire b_ci         ;
    wire or0_out_coutn;

    xor xor0 (xor0_out_SUM , A, B, CI       );
    buf buf0 (SUM          , xor0_out_SUM   );
    nor nor0 (a_b          , A, B           );
    nor nor1 (a_ci         , A, CI          );
    nor nor2 (b_ci         , B, CI          );
    or  or0  (or0_out_coutn, a_b, a_ci, b_ci);
    buf buf1 (COUT_N       , or0_out_coutn  );

endmodule

sva:
module sky130_fd_sc_lp__fahcon_sva (
    input logic COUT_N,
    input logic SUM,
    input logic A,
    input logic B,
    input logic CI
);
    // Combinational cell with no clock/reset; sample on input edges.

    // SUM equals three-input XOR (sampled on A edge).
    sum_eq_xor_on_A: assert property (
        @(posedge A) SUM == (A ^ B ^ CI)
    );

    // SUM equals three-input XOR (sampled on B edge).
    sum_eq_xor_on_B: assert property (
        @(posedge B) SUM == (A ^ B ^ CI)
    );

    // SUM equals three-input XOR (sampled on CI edge).
    sum_eq_xor_on_CI: assert property (
        @(posedge CI) SUM == (A ^ B ^ CI)
    );

    // COUT_N equals OR of NOR terms per RTL (sampled on A edge).
    coutn_eq_or_nor_on_A: assert property (
        @(posedge A) COUT_N == ((~(A|B)) | (~(A|CI)) | (~(B|CI)))
    );

    // COUT_N equals OR of NOR terms per RTL (sampled on B edge).
    coutn_eq_or_nor_on_B: assert property (
        @(posedge B) COUT_N == ((~(A|B)) | (~(A|CI)) | (~(B|CI)))
    );

    // COUT_N equals OR of NOR terms per RTL (sampled on CI edge).
    coutn_eq_or_nor_on_CI: assert property (
        @(posedge CI) COUT_N == ((~(A|B)) | (~(A|CI)) | (~(B|CI)))
    );

    // If A and B are 1, COUT_N must be 0 regardless of CI.
    coutn_zero_when_A_and_B_one: assert property (
        @(posedge A) (A && B) |-> (COUT_N == 1'b0)
    );

    // If A and CI are 1, COUT_N must be 0 regardless of B.
    coutn_zero_when_A_and_CI_one: assert property (
        @(posedge CI) (A && CI) |-> (COUT_N == 1'b0)
    );

    // If B and CI are 1, COUT_N must be 0 regardless of A.
    coutn_zero_when_B_and_CI_one: assert property (
        @(posedge B) (B && CI) |-> (COUT_N == 1'b0)
    );

    // When A and B are equal, SUM equals CI.
    sum_equals_CI_when_A_eq_B: assert property (
        @(posedge CI) (A == B) |-> (SUM == CI)
    );
endmodule

module clock_gate_high_register_add_sva (
    input logic CLK,
    input logic EN,
    input logic TE,
    input logic ENCLK
);
    // When enabled, ENCLK updates to TE on the next clock.
    update_on_enable: assert property (
        @(posedge CLK) EN |=> (ENCLK == $past(TE))
    );

    // When disabled, ENCLK holds its previous value on the next clock.
    hold_when_disabled: assert property (
        @(posedge CLK) !EN |=> (ENCLK == $past(ENCLK))
    );

    // Any change in ENCLK from one cycle to the next requires EN to have been HIGH in the prior cycle.
    change_requires_prev_enable: assert property (
        @(posedge CLK) 1'b1 |=> ((ENCLK != $past(ENCLK)) |-> $past(EN))
    );

    // If ENCLK changes, the new value must equal TE from the prior cycle.
    change_matches_prev_te: assert property (
        @(posedge CLK) 1'b1 |=> ((ENCLK != $past(ENCLK)) |-> (ENCLK == $past(TE)))
    );

    // If enabled and TE differs from current ENCLK, ENCLK must toggle on the next clock.
    enabled_differs_causes_toggle: assert property (
        @(posedge CLK) (EN && (TE != ENCLK)) |=> (ENCLK != $past(ENCLK))
    );

    // If enabled and TE equals current ENCLK, ENCLK remains unchanged on the next clock.
    enabled_same_keeps_stable: assert property (
        @(posedge CLK) (EN && (TE == ENCLK)) |=> (ENCLK == $past(ENCLK))
    );
endmodule

rtl:
module counter(
	input wire clk,
	output reg [15:0] count
);

always @(posedge clk) begin
	if(count == 16'hFFFF) begin
		count <= 16'h0000;
	end
	else begin
		count <= count + 1'b1;
	end
end

endmodule

sva:
module counter_sva (
    input logic clk,
    input logic [15:0] count
);
    // Next state equals prev+1, or wraps to 0 from 0xFFFF.
    check_update_rule: assert property (
        @(posedge clk) $past(1'b1) |-> (count == (($past(count) == 16'hFFFF) ? 16'h0000 : ($past(count) + 16'h0001)))
    );

    // Only 0xFFFF can be followed by 0x0000.
    check_zero_only_after_max: assert property (
        @(posedge clk) ($past(1'b1) && (count == 16'h0000)) |-> ($past(count) == 16'hFFFF)
    );

    // For nonzero count, previous value must be current - 1.
    check_prev_is_curr_minus1_when_nonzero: assert property (
