    check_X_zero_implies_all_zero: assert property (
        @(posedge A or posedge B or posedge C or negedge A or negedge B or negedge C)
            disable iff (1'b0)
            (X === 1'b0) |-> ((A === 1'b0) && (B === 1'b0) && (C === 1'b0))
