module SNPS_CLOCK_GATE_HIGH_RegisterAdd_W31_0_3 ( CLK, EN, ENCLK, TE );
  input CLK, EN, TE;
  output ENCLK;

  // Replace TBUF with a D-flip-flop
  reg EN_latch;
  always @(posedge CLK) begin
    if (TE) begin
      EN_latch <= EN;
    end
  end

  // Replace BUFX with a buffer
  assign ENCLK = EN_latch;
endmodule

sva:
module SNPS_CLOCK_GATE_HIGH_RegisterAdd_W31_0_3_sva (
    input logic CLK,
    input logic EN,
    input logic ENCLK,
    input logic TE
);
    // Analysis: Clock=CLK (posedge), no reset. Sequential D-FF gated by TE; ENCLK is registered EN when TE=1, else holds.

    // On TE=1, ENCLK updates to EN on the next cycle.
    update_on_TE_high: assert property (
        @(posedge CLK) TE |=> (ENCLK == $past(EN))
    );

    // On TE=0, ENCLK holds its previous value on the next cycle.
    hold_when_TE_low: assert property (
        @(posedge CLK) !TE |=> (ENCLK == $past(ENCLK))
    );

    // Any change in ENCLK from last cycle implies TE was 1 in the previous cycle.
    enclk_change_requires_prev_TE: assert property (
        @(posedge CLK) (ENCLK != $past(ENCLK)) |-> $past(TE)
    );

    // If TE was 1 in the previous cycle, ENCLK equals the previous EN now.
    prev_te_high_updates_output: assert property (
        @(posedge CLK) $past(TE) |-> (ENCLK == $past(EN))
    );

    // If TE was 0 in the previous cycle, ENCLK holds its previous value now.
    prev_te_low_holds_output: assert property (
        @(posedge CLK) !$past(TE) |-> (ENCLK == $past(ENCLK))
    );

    // With TE=1, if previous EN differed from previous ENCLK, ENCLK must change next cycle.
    update_causes_change_when_input_differs: assert property (
        @(posedge CLK) TE && ($past(EN) != $past(ENCLK)) |=> (ENCLK != $past(ENCLK))
    );

    // With TE=1, if previous EN equaled previous ENCLK, ENCLK must not change next cycle.
    update_no_change_when_input_same: assert property (
        @(posedge CLK) TE && ($past(EN) == $past(ENCLK)) |=> (ENCLK == $past(ENCLK))
    );

    // One-cycle state equation: ENCLK now equals (prev TE ? prev EN : prev ENCLK).
    one_cycle_state_equation: assert property (
        @(posedge CLK) ENCLK == ($past(TE) ? $past(EN) : $past(ENCLK))
    );
endmodule

rtl:
module top_module( 
    input [99:0] in,
    input a,
    input b,
    output out_nor,
    output out_or,
    output out_xor 
);

    // First NAND gate
    wire [99:0] nand1_out;
    assign nand1_out = ~(&in);

    // Second NAND gate
    wire [99:0] nand2_out;
    assign nand2_out = ~(&in);

    // NOR gate output
    wire nor_out;
    assign nor_out = ~(nand1_out | nand2_out);

    // OR gate output
    wire or_out;
    assign or_out = |in;

    // XOR gate output
    wire xor_out;
    assign xor_out = ^in;

    // Assign outputs to module ports
    assign out_nor = nor_out;
    assign out_or = or_out;
    assign out_xor = xor_out;

endmodule

sva:
module top_module_sva (
    input logic [99:0] in,
    input logic a,
    input logic b,
    input logic out_nor,
    input logic out_or,
    input logic out_xor
);
    ///// Combinational correctness (sampled on posedge of 'a') /////
    // out_or equals reduction OR of in.
    check_out_or_reduction: assert property (
        @(posedge a) out_or == (|in)
    );
    // out_xor equals reduction XOR of in.
    check_out_xor_reduction: assert property (
        @(posedge a) out_xor == (^in)
    );
    // out_nor equals reduction AND of in (by RTL composition).
    check_out_nor_is_and: assert property (
        @(posedge a) out_nor == (&in)
    );

    ///// Logical relationships implied by reductions /////
    // If out_nor is 1 (all bits are 1), out_or must be 1.
    check_nor_implies_or: assert property (
        @(posedge a) out_nor |-> out_or
    );
    // If out_or is 0 (all bits are 0), out_xor must be 0.
    check_or_zero_implies_xor_zero: assert property (
        @(posedge a) !out_or |-> (out_xor == 1'b0)
    );
    // If out_or is 0 (all bits are 0), out_nor must be 0.
    check_or_zero_implies_nor_zero: assert property (
        @(posedge a) !out_or |-> (out_nor == 1'b0)
    );
    // If out_xor is 1 (odd parity), out_or must be 1.
    check_xor_one_implies_or_one: assert property (
        @(posedge a) out_xor |-> out_or
    );
    // If out_nor is 1 (all ones, even count of ones), out_xor must be 0.
    check_nor_one_implies_xor_zero: assert property (
        @(posedge a) out_nor |-> (out_xor == 1'b0)
    );

    ///// Corner-case input patterns /////
    // When in is all zeros, all outputs are zero.
    check_all_zero_input: assert property (
        @(posedge a) (in == 100'b0) |-> (out_or == 1'b0 && out_xor == 1'b0 && out_nor == 1'b0)
    );
    // When in is all ones, out_or=1, out_xor=0 (even parity), out_nor=1.
    check_all_ones_input: assert property (
        @(posedge a) (in == {100{1'b1}}) |-> (out_or == 1'b1 && out_xor == 1'b0 && out_nor == 1'b1)
    );
endmodule

