sva:
module sky130_fd_sc_ls__or4bb_sva (
    input logic X,
    input logic A,
    input logic B,
    input logic C_N,
    input logic D_N
);
    // X implements A | B | ~C_N | ~D_N sampled on A rising edge.
    check_truth_on_A_posedge: assert property (
        @(posedge A) X == (A | B | ~C_N | ~D_N)
    );

    // X implements A | B | ~C_N | ~D_N sampled on B rising edge.
    check_truth_on_B_posedge: assert property (
        @(posedge B) X == (A | B | ~C_N | ~D_N)
    );

    // X implements A | B | ~C_N | ~D_N sampled on C_N rising edge.
    check_truth_on_Cn_posedge: assert property (
        @(posedge C_N) X == (A | B | ~C_N | ~D_N)
    );

    // X implements A | B | ~C_N | ~D_N sampled on D_N rising edge.
    check_truth_on_Dn_posedge: assert property (
        @(posedge D_N) X == (A | B | ~C_N | ~D_N)
    );

    // X implements A | B | ~C_N | ~D_N sampled on X rising edge.
    check_truth_on_X_posedge: assert property (
        @(posedge X) X == (A | B | ~C_N | ~D_N)
    );

    // Asserting C_N low forces X high.
    check_Cn_low_forces_X_high: assert property (
        @(negedge C_N) X == 1'b1
    );

    // Asserting D_N low forces X high.
    check_Dn_low_forces_X_high: assert property (
        @(negedge D_N) X == 1'b1
    );

    // With C_N just risen and D_N already high, X reduces to A | B.
    check_reduce_to_AorB_on_Cn_rise: assert property (
        @(posedge C_N) (D_N == 1'b1) |-> (X == (A | B))
    );

    // With D_N just risen and C_N already high, X reduces to A | B.
    check_reduce_to_AorB_on_Dn_rise: assert property (
        @(posedge D_N) (C_N == 1'b1) |-> (X == (A | B))
    );

    // When X falls low, all inputs must make all OR terms false.
    check_X_low_implies_all_inactive: assert property (
        @(negedge X) (A == 1'b0) && (B == 1'b0) && (C_N == 1'b1) && (D_N == 1'b1)
    );
endmodule

rtl:
module calculator(
    input [7:0] A,
    input [7:0] B,
    input [1:0] opcode,
    output reg [15:0] result
);

always @* begin
    case(opcode)
        2'b00: result = A + B;
        2'b01: result = A - B;
        2'b10: result = A * B;
        2'b11: result = A / B;
    endcase
end

endmodule

sva:
module calculator_sva (
    input logic CLK,
    input logic [7:0] A,
    input logic [7:0] B,
    input logic [1:0] opcode,
    input logic [15:0] result
);
    // For opcode 00, result is zero-extended 8-bit sum of A and B.
    check_add_value: assert property (
        @(posedge CLK) (opcode == 2'b00) |-> (result == {8'h00, (A + B)})
    );

    // For opcode 01, result is zero-extended 8-bit difference A - B.
    check_sub_value: assert property (
        @(posedge CLK) (opcode == 2'b01) |-> (result == {8'h00, (A - B)})
    );

    // For opcode 10, result equals 16-bit product A * B.
    check_mul_value: assert property (
        @(posedge CLK) (opcode == 2'b10) |-> (result == (A * B))
    );

    // For opcode 11 with B!=0, result is zero-extended 8-bit quotient A / B.
    check_div_value: assert property (
        @(posedge CLK) (opcode == 2'b11) && (B != 8'h00) |-> (result == {8'h00, (A / B)})
    );

    // Multiply by zero on A yields 0.
    check_mul_zero_A: assert property (
        @(posedge CLK) (opcode == 2'b10) && (A == 8'h00) |-> (result == 16'h0000)
    );

    // Multiply by zero on B yields 0.
    check_mul_zero_B: assert property (
        @(posedge CLK) (opcode == 2'b10) && (B == 8'h00) |-> (result == 16'h0000)
    );

    // Addition with A == 0 returns zero-extended B.
    check_add_zero_A: assert property (
        @(posedge CLK) (opcode == 2'b00) && (A == 8'h00) |-> (result == {8'h00, B})
    );

    // Addition with B == 0 returns zero-extended A.
    check_add_zero_B: assert property (
        @(posedge CLK) (opcode == 2'b00) && (B == 8'h00) |-> (result == {8'h00, A})
    );

    // Subtraction with A == B yields zero.
    check_sub_equal_zero: assert property (
        @(posedge CLK) (opcode == 2'b01) && (A == B) |-> (result == 16'h0000)
    );

    // Division by one returns zero-extended A.
    check_div_by_one: assert property (
        @(posedge CLK) (opcode == 2'b11) && (B == 8'h01) |-> (result == {8'h00, A})
    );
endmodule

module mux4to1_sva (
    input logic clk,                  // sampling clock for SVA (RTL is combinational, no reset)
    input logic [1:0] sel,
    input logic [3:0] in0,
    input logic [3:0] in1,
    input logic [3:0] in2,
    input logic [3:0] in3,
    input logic [3:0] out
);

    // First-one-hot within a 4-bit vector (LSB priority)
    function automatic logic [3:0] first_one_hot4 (input logic [3:0] v);
        if (v[0])       return 4'b0001;
        else if (v[1])  return 4'b0010;
        else if (v[2])  return 4'b0100;
        else if (v[3])  return 4'b1000;
        else            return 4'b0000;
    endfunction

    // Expected outputs per sel, reflecting global 16-bit priority order
    logic [3:0] expected_sel00, expected_sel01, expected_sel10, expected_sel11;
    always_comb begin
        expected_sel00 = first_one_hot4(in0);
        expected_sel01 = (|in0) ? 4'b0000 : first_one_hot4(in1);
        expected_sel10 = ((|in0) || (|in1)) ? 4'b0000 : first_one_hot4(in2);
        expected_sel11 = ((|in0) || (|in1) || (|in2)) ? 4'b0000 : first_one_hot4(in3);
    end

    // Selected input nibble based on sel
    logic [3:0] selected_in;
    always_comb begin
        unique case (sel)
            2'b00: selected_in = in0;
            2'b01: selected_in = in1;
            2'b10: selected_in = in2;
            default: selected_in = in3;
        endcase
    end

    ///// Functional equivalence to RTL /////
    // For sel==00, out equals first-one-hot of in0.
    check_sel00_functional: assert property (
        @(posedge clk) (sel == 2'b00) |-> (out == expected_sel00)
    );
    // For sel==01, out equals first-one-hot of in1 gated by no ones in in0.
    check_sel01_functional: assert property (
        @(posedge clk) (sel == 2'b01) |-> (out == expected_sel01)
    );
    // For sel==10, out equals first-one-hot of in2 gated by no ones in in0|in1.
    check_sel10_functional: assert property (
        @(posedge clk) (sel == 2'b10) |-> (out == expected_sel10)
    );
    // For sel==11, out equals first-one-hot of in3 gated by no ones in in0|in1|in2.
    check_sel11_functional: assert property (
        @(posedge clk) (sel == 2'b11) |-> (out == expected_sel11)
    );

    ///// Basic safety/consistency rules /////
    // Out is always a subset of the selected input nibble.
    check_out_subset_of_selected: assert property (
        @(posedge clk) ((out & ~selected_in) == 4'b0000)
    );
    // Out has at most one bit set (one-hot or zero).
    check_out_onehot0: assert property (
        @(posedge clk) $onehot0(out)
    );

    ///// Priority blocking by earlier nibbles /////
    // If sel==01 and any bit in in0 is 1, out must be zero.
    check_block_by_in0_for_sel01: assert property (
        @(posedge clk) (sel == 2'b01 && (|in0)) |-> (out == 4'b0000)
    );
    // If sel==10 and any bit in in0|in1 is 1, out must be zero.
    check_block_by_in0_in1_for_sel10: assert property (
        @(posedge clk) (sel == 2'b10 && ((|in0) || (|in1))) |-> (out == 4'b0000)
    );
    // If sel==11 and any bit in in0|in1|in2 is 1, out must be zero.
    check_block_by_prev_for_sel11: assert property (
        @(posedge clk) (sel == 2'b11 && ((|in0) || (|in1) || (|in2))) |-> (out == 4'b0000)
    );

    ///// All-zeros input behavior /////
    // If all inputs are zero, out must be zero for any sel.
    check_all_zero_inputs: assert property (
        @(posedge clk) (~(|in0) && ~(|in1) && ~(|in2) && ~(|in3))) |-> (out == 4'b0000)
    );

endmodule

rtl:
module magnitude_comparator (
    input [3:0] A,
    input [3:0] B,
    output reg GT,
    output reg EQ
);

always @(*) begin
    if (A > B) begin
        GT = 1;
        EQ = 0;
    end
    else if (A == B) begin
        GT = 0;
        EQ = 1;
    end
    else begin
        GT = 0;
        EQ = 0;
    end
end

endmodule

sva:
module magnitude_comparator_sva (
    input  logic        CLK,
    input  logic        RESETn,
    input  logic [3:0]  A,
    input  logic [3:0]  B,
    input  logic        GT,
    input  logic        EQ
);
    // When A > B, outputs must be GT=1 and EQ=0.
    outputs_for_a_greater: assert property (
        @(posedge CLK) disable iff (!RESETn) (A > B) |-> (GT == 1'b1 && EQ == 1'b0)
    );

    // When A == B, outputs must be GT=0 and EQ=1.
    outputs_for_equal: assert property (
        @(posedge CLK) disable iff (!RESETn) (A == B) |-> (GT == 1'b0 && EQ == 1'b1)
    );

    // When A < B, outputs must be GT=0 and EQ=0.
    outputs_for_a_less: assert property (
        @(posedge CLK) disable iff (!RESETn) (A < B) |-> (GT == 1'b0 && EQ == 1'b0)
    );

    // GT can be 1 only when A > B (and then EQ must be 0).
    gt_only_when_a_greater: assert property (
        @(posedge CLK) disable iff (!RESETn) (GT == 1'b1) |-> ((A > B) && (EQ == 1'b0))
    );

    // EQ can be 1 only when A == B (and then GT must be 0).
    eq_only_when_equal: assert property (
        @(posedge CLK) disable iff (!RESETn) (EQ == 1'b1) |-> ((A == B) && (GT == 1'b0))
    );

    // Combination GT=0 and EQ=0 occurs only when A < B.
    zero_zero_only_when_a_less: assert property (
        @(posedge CLK) disable iff (!RESETn) ((GT == 1'b0) && (EQ == 1'b0)) |-> (A < B)
    );

    // GT and EQ are never both 1 simultaneously.
    gt_eq_mutex: assert property (
        @(posedge CLK) disable iff (!RESETn) !(GT && EQ)
    );

    // GT exactly matches the boolean result of (A > B).
    gt_matches_compare: assert property (
        @(posedge CLK) disable iff (!RESETn) GT == (A > B)
    );

    // EQ exactly matches the boolean result of (A == B).
    eq_matches_equal: assert property (
        @(posedge CLK) disable iff (!RESETn) EQ == (A == B)
    );

    // When A is not greater than B, GT must be 0.
    no_gt_when_not_greater: assert property (
        @(posedge CLK) disable iff (!RESETn) !(A > B) |-> (GT == 1'b0)
    );
endmodule

rtl:
module multiplexer #(parameter N = 8, M = 2) (
    input [N-1:0] A,
    input [N-1:0] B,
    input [N-1:0] C,
    input [M-1:0] S,
    output [N-1:0] Y
);

// Declare a register to hold the selected input
reg [N-1:0] selected_input;

always @(*) begin
    case (S)
        2'b00: selected_input = A;
        2'b01: selected_input = B;
        2'b10: selected_input = C;
        default: selected_input = 0; // Optional default case
    endcase
end

// Assign the selected input to the output
assign Y = selected_input;

endmodule

sva:
module multiplexer_sva #(
    parameter int N = 8,
    parameter int M = 2
)(
    input logic clk,                 // Checker sampling clock (DUT has no clock/reset)
    input logic [N-1:0] A,
    input logic [N-1:0] B,
    input logic [N-1:0] C,
    input logic [M-1:0] S,
    input logic [N-1:0] Y
);
    // Analysis: DUT has no clock/reset; purely combinational mux; Y selects A/B/C by S, else 0.

    // Y implements the mux function exactly (A for 00, B for 01, C for 10, else 0).
    check_mux_function: assert property (
        @(posedge clk)
            Y == ((S == 2'b00) ? A :
                  (S == 2'b01) ? B :
                  (S == 2'b10) ? C : '0)
    );

    // When S==00 (zero-extended), Y equals A.
    check_select_A_when_S_00: assert property (
        @(posedge clk) (S == 2'b00) |-> (Y == A)
    );

    // When S==01 (zero-extended), Y equals B.
    check_select_B_when_S_01: assert property (
        @(posedge clk) (S == 2'b01) |-> (Y == B)
    );

    // When S==10 (zero-extended), Y equals C.
    check_select_C_when_S_10: assert property (
        @(posedge clk) (S == 2'b10) |-> (Y == C)
    );

    // When S is not 00/01/10, Y drives all zeros (default case).
    check_default_zero_when_other_S: assert property (
        @(posedge clk) (!( (S == 2'b00) || (S == 2'b01) || (S == 2'b10) )) |-> (Y == '0)
    );

    // If A,B,C,S are stable cycle-to-cycle, Y must remain stable (purely combinational).
    check_output_stable_when_inputs_stable: assert property (
        @(posedge clk) $stable({A,B,C,S}) |-> $stable(Y)
    );

    // For M>2, any nonzero upper bits in S force the default case (Y==0).
    generate
        if (M > 2) begin : gen_hi_default_zero
            check_upper_bits_force_default_zero: assert property (
                @(posedge clk) (S[M-1:2] != '0) |-> (Y == '0)
            );
        end
    endgenerate
endmodule

rtl:
module full_adder (
  input a,
  input b,
  input c_in,
  output sum,
  output c_out
);

  assign sum = a ^ b ^ c_in;
  assign c_out = (a & b) | (c_in & (a ^ b));

endmodule

sva:
module full_adder_sva (
    input logic a,
    input logic b,
    input logic c_in,
    input logic sum,
    input logic c_out
);
    // sum equals a ^ b ^ c_in
    check_sum_def: assert property (
        @(posedge a or negedge a or posedge b or negedge b or posedge c_in or negedge c_in)
        sum == (a ^ b ^ c_in)
    );

    // c_out equals (a & b) | (c_in & (a ^ b))
    check_c_out_def: assert property (
        @(posedge a or negedge a or posedge b or negedge b or posedge c_in or negedge c_in)
        c_out == ((a & b) | (c_in & (a ^ b)))
    );

    // c_out equals majority form (a&b)|(a&c_in)|(b&c_in)
    check_c_out_majority_equiv: assert property (
        @(posedge a or negedge a or posedge b or negedge b or posedge c_in or negedge c_in)
        c_out == ((a & b) | (a & c_in) | (b & c_in))
    );

    // When c_in is 0, sum is a ^ b
    check_sum_when_cin0: assert property (
        @(posedge a or negedge a or posedge b or negedge b or posedge c_in or negedge c_in)
        (c_in == 1'b0) |-> (sum == (a ^ b))
    );

    // When c_in is 1, sum is ~(a ^ b)
    check_sum_when_cin1: assert property (
        @(posedge a or negedge a or posedge b or negedge b or posedge c_in or negedge c_in)
        (c_in == 1'b1) |-> (sum == ~(a ^ b))
    );

    // When c_in is 0, c_out is a & b
    check_c_out_when_cin0: assert property (
        @(posedge a or negedge a or posedge b or negedge b or posedge c_in or negedge c_in)
        (c_in == 1'b0) |-> (c_out == (a & b))
    );

    // When c_in is 1, c_out is a | b
    check_c_out_when_cin1: assert property (
        @(posedge a or negedge a or posedge b or negedge b or posedge c_in or negedge c_in)
        (c_in == 1'b1) |-> (c_out == (a | b))
    );

    // If a equals b, sum equals c_in
    check_sum_when_a_eq_b: assert property (
        @(posedge a or negedge a or posedge b or negedge b or posedge c_in or negedge c_in)
        (a == b) |-> (sum == c_in)
    );

    // Exactly one input high -> sum=1, c_out=0
    check_onehot_behavior: assert property (
        @(posedge a or negedge a or posedge b or negedge b or posedge c_in or negedge c_in)
        (( a & ~b & ~c_in) | (~a &  b & ~c_in) | (~a & ~b &  c_in)) |-> (sum == 1'b1 && c_out == 1'b0)
    );

    // Exactly two inputs high -> sum=0, c_out=1
    check_twohot_behavior: assert property (
        @(posedge a or negedge a or posedge b or negedge b or posedge c_in or negedge c_in)
        ((a & b & ~c_in) | (a & ~b & c_in) | (~a & b & c_in)) |-> (sum == 1'b0 && c_out == 1'b1)
    );

    // All inputs low -> sum=0, c_out=0
    check_all_zero_behavior: assert property (
        @(posedge a or negedge a or posedge b or negedge b or posedge c_in or negedge c_in)
        (~a & ~b & ~c_in) |-> (sum == 1'b0 && c_out == 1'b0)
    );
endmodule

