module crc(
  input [0:0] data_in,
  input crc_en,
  output [15:0] crc_out,
  input rst,
  input clk);

  reg [15:0] lfsr_q,lfsr_c;

  assign crc_out = lfsr_q;

  always @(*) begin
    lfsr_c[0] = lfsr_q[15] ^ data_in[0];
    lfsr_c[1] = lfsr_q[0];
    lfsr_c[2] = lfsr_q[1] ^ lfsr_q[15] ^ data_in[0];
    lfsr_c[3] = lfsr_q[2];
    lfsr_c[4] = lfsr_q[3];
    lfsr_c[5] = lfsr_q[4];
    lfsr_c[6] = lfsr_q[5];
    lfsr_c[7] = lfsr_q[6];
    lfsr_c[8] = lfsr_q[7];
    lfsr_c[9] = lfsr_q[8];
    lfsr_c[10] = lfsr_q[9];
    lfsr_c[11] = lfsr_q[10];
    lfsr_c[12] = lfsr_q[11];
    lfsr_c[13] = lfsr_q[12];
    lfsr_c[14] = lfsr_q[13];
    lfsr_c[15] = lfsr_q[14] ^ lfsr_q[15] ^ data_in[0];

  end always @(posedge clk, posedge rst) begin
    if(rst) begin
      lfsr_q <= {16{1'b0}};
    end
    else begin
      lfsr_q <= crc_en ? lfsr_c : lfsr_q;
    end
  end endmodule // crc

sva:
module crc_sva (
    input logic [0:0] data_in,
    input logic crc_en,
    input logic [15:0] crc_out,
    input logic rst,
    input logic clk,
    // Internal signals from DUT for binding
    input logic [15:0] lfsr_q,
    input logic [15:0] lfsr_c
);
    ///// Reset behavior /////
    // When reset is asserted, internal state clears to zero.
    check_reset_clears_state: assert property (
        @(posedge clk) rst |-> (lfsr_q == 16'h0000)
    );
    // When reset is asserted, output reflects cleared state.
    check_reset_drives_output_zero: assert property (
        @(posedge clk) rst |-> (crc_out == 16'h0000)
    );

    ///// Output mapping /////
    // Output always reflects internal state.
    check_output_equals_state: assert property (
        @(posedge clk) disable iff (rst) (crc_out == lfsr_q)
    );

    ///// Enable-controlled state update /////
    // When enable is LOW, state holds its previous value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (rst) (!crc_en) |=> (lfsr_q == $past(lfsr_q))
    );
    // When enable is HIGH, state updates to previous cycle's combinational next value.
    check_update_when_enabled: assert property (
        @(posedge clk) disable iff (rst) (crc_en) |=> (lfsr_q == $past(lfsr_c))
    );

    ///// Combinational next-state equations (lfsr_c) /////
    // Next-state bit 0 equals lfsr_q[15] XOR data_in[0].
    check_lfsr_c_bit0_def: assert property (
        @(posedge clk) disable iff (rst) (lfsr_c[0] == (lfsr_q[15] ^ data_in[0]))
    );
    // Next-state bit 1 equals lfsr_q[0].
    check_lfsr_c_bit1_def: assert property (
        @(posedge clk) disable iff (rst) (lfsr_c[1] == lfsr_q[0])
    );
    // Next-state bit 2 equals lfsr_q[1] XOR lfsr_q[15] XOR data_in[0].
    check_lfsr_c_bit2_def: assert property (
        @(posedge clk) disable iff (rst) (lfsr_c[2] == (lfsr_q[1] ^ lfsr_q[15] ^ data_in[0]))
    );
    // Next-state bit 3 equals lfsr_q[2].
    check_lfsr_c_bit3_def: assert property (
        @(posedge clk) disable iff (rst) (lfsr_c[3] == lfsr_q[2])
    );
    // Next-state bit 4 equals lfsr_q[3].
    check_lfsr_c_bit4_def: assert property (
        @(posedge clk) disable iff (rst) (lfsr_c[4] == lfsr_q[3])
    );
    // Next-state bit 5 equals lfsr_q[4].
    check_lfsr_c_bit5_def: assert property (
        @(posedge clk) disable iff (rst) (lfsr_c[5] == lfsr_q[4])
    );
    // Next-state bit 6 equals lfsr_q[5].
    check_lfsr_c_bit6_def: assert property (
        @(posedge clk) disable iff (rst) (lfsr_c[6] == lfsr_q[5])
    );
    // Next-state bit 7 equals lfsr_q[6].
    check_lfsr_c_bit7_def: assert property (
        @(posedge clk) disable iff (rst) (lfsr_c[7] == lfsr_q[6])
    );
    // Next-state bit 8 equals lfsr_q[7].
    check_lfsr_c_bit8_def: assert property (
        @(posedge clk) disable iff (rst) (lfsr_c[8] == lfsr_q[7])
    );
    // Next-state bit 9 equals lfsr_q[8].
    check_lfsr_c_bit9_def: assert property (
        @(posedge clk) disable iff (rst) (lfsr_c[9] == lfsr_q[8])
    );
    // Next-state bit 10 equals lfsr_q[9].
    check_lfsr_c_bit10_def: assert property (
        @(posedge clk) disable iff (rst) (lfsr_c[10] == lfsr_q[9])
    );
    // Next-state bit 11 equals lfsr_q[10].
    check_lfsr_c_bit11_def: assert property (
        @(posedge clk) disable iff (rst) (lfsr_c[11] == lfsr_q[10])
    );
    // Next-state bit 12 equals lfsr_q[11].
    check_lfsr_c_bit12_def: assert property (
        @(posedge clk) disable iff (rst) (lfsr_c[12] == lfsr_q[11])
    );
    // Next-state bit 13 equals lfsr_q[12].
    check_lfsr_c_bit13_def: assert property (
        @(posedge clk) disable iff (rst) (lfsr_c[13] == lfsr_q[12])
    );
    // Next-state bit 14 equals lfsr_q[13].
    check_lfsr_c_bit14_def: assert property (
        @(posedge clk) disable iff (rst) (lfsr_c[14] == lfsr_q[13])
    );
    // Next-state bit 15 equals lfsr_q[14] XOR lfsr_q[15] XOR data_in[0].
    check_lfsr_c_bit15_def: assert property (
        @(posedge clk) disable iff (rst) (lfsr_c[15] == (lfsr_q[14] ^ lfsr_q[15] ^ data_in[0]))
    );

endmodule

rtl:
module nor3 (
    input  A,
    input  B,
    input  C,
    output Y
);

    // NOR gate implementation
    assign Y = ~(A | B | C);

endmodule

sva:
module nor3_sva (
    input logic clk,  // sampling clock for SVA (DUT has no clock/reset)
    input logic A,
    input logic B,
    input logic C,
    input logic Y
);
    // Y implements a 3-input NOR of A,B,C.
    check_function_equivalence: assert property (
        @(posedge clk) Y === ~(A | B | C)
    );

    // Any input HIGH forces Y LOW.
    check_any_input_one_forces_y_zero: assert property (
        @(posedge clk) ((A===1'b1) || (B===1'b1) || (C===1'b1)) |-> (Y===1'b0)
    );

    // All inputs LOW force Y HIGH.
    check_all_inputs_zero_forces_y_one: assert property (
        @(posedge clk) ((A===1'b0) && (B===1'b0) && (C===1'b0)) |-> (Y===1'b1)
    );

    // If Y is HIGH, all inputs must be LOW.
    check_y_high_implies_all_inputs_low: assert property (
        @(posedge clk) (Y===1'b1) |-> ((A===1'b0) && (B===1'b0) && (C===1'b0))
    );

    // If Y is LOW, at least one input must be HIGH.
    check_y_low_implies_any_input_high: assert property (
        @(posedge clk) (Y===1'b0) |-> ((A===1'b1) || (B===1'b1) || (C===1'b1))
    );

    // On Y rising, all inputs must be LOW.
    check_output_rise_requires_all_inputs_zero: assert property (
        @(posedge clk) $rose(Y) |-> ((A===1'b0) && (B===1'b0) && (C===1'b0))
    );

    // On Y falling, at least one input must be HIGH.
    check_output_fall_requires_any_input_one: assert property (
        @(posedge clk) $fell(Y) |-> ((A===1'b1) || (B===1'b1) || (C===1'b1))
    );

    // If inputs are stable between cycles, Y is stable too.
    check_stability_when_inputs_stable: assert property (
        @(posedge clk) ((A === $past(A)) && (B === $past(B)) && (C === $past(C))) |-> (Y === $past(Y))
    );

    // If A rises and B,C are 0 both before and after, Y must fall.
    check_y_fall_when_A_rises_and_others_zero: assert property (
        @(posedge clk) ($rose(A) && (B===1'b0) && (C===1'b0) && $past(B===1'b0) && $past(C===1'b0)) |-> $fell(Y)
    );

    // If B rises and A,C are 0 both before and after, Y must fall.
    check_y_fall_when_B_rises_and_others_zero: assert property (
        @(posedge clk) ($rose(B) && (A===1'b0) && (C===1'b0) && $past(A===1'b0) && $past(C===1'b0)) |-> $fell(Y)
    );

    // If C rises and A,B are 0 both before and after, Y must fall.
    check_y_fall_when_C_rises_and_others_zero: assert property (
        @(posedge clk) ($rose(C) && (A===1'b0) && (B===1'b0) && $past(A===1'b0) && $past(B===1'b0)) |-> $fell(Y)
    );

    // If A falls and B,C are 0 both before and after, Y must rise.
    check_y_rise_when_A_falls_and_others_zero: assert property (
        @(posedge clk) ($fell(A) && (B===1'b0) && (C===1'b0) && $past(B===1'b0) && $past(C===1'b0)) |-> $rose(Y)
    );

    // If B falls and A,C are 0 both before and after, Y must rise.
    check_y_rise_when_B_falls_and_others_zero: assert property (
        @(posedge clk) ($fell(B) && (A===1'b0) && (C===1'b0) && $past(A===1'b0) && $past(C===1'b0)) |-> $rose(Y)
    );

    // If C falls and A,B are 0 both before and after, Y must rise.
    check_y_rise_when_C_falls_and_others_zero: assert property (
        @(posedge clk) ($fell(C) && (A===1'b0) && (B===1'b0) && $past(A===1'b0) && $past(B===1'b0)) |-> $rose(Y)
    );
endmodule

rtl:
module shift_register (
  input clk,
  input load,
  input [3:0] data_in,
  input reset,
  output [3:0] data_out
);

  reg [3:0] shift_reg;

  always @(posedge clk) begin
    if (reset) begin
      shift_reg <= 4'b0000;
    end else if (load) begin
      shift_reg <= data_in;
    end else begin
      shift_reg <= {shift_reg[2:0], 1'b0};
    end
  end

  assign data_out = shift_reg;

endmodule

sva:
module shift_register_sva (
  input logic clk,
  input logic load,
  input logic [3:0] data_in,
  input logic reset,
  input logic [3:0] data_out
);
  // Clock: clk (posedge). Reset: reset (active-high, synchronous). Logic: sequential with load/shift; data_out mirrors shift_reg.

  // Reset sets register to 0 on the next cycle.
  reset_clears: assert property (
    @(posedge clk) reset |=> (data_out == 4'b0000)
  );

  // Reset overrides load when both are asserted.
  reset_overrides_load: assert property (
    @(posedge clk) (reset && load) |=> (data_out == 4'b0000)
  );

  // Load captures data_in on the next cycle (when not in reset).
  load_writes_next: assert property (
    @(posedge clk) disable iff (reset) load |=> (data_out == $past(data_in))
  );

  // Shift operation: next value is {prev[2:0], 1'b0} when not loading.
  shift_next_value: assert property (
    @(posedge clk) disable iff (reset) !load |=> (data_out == { $past(data_out[2:0]), 1'b0 })
  );

  // Shift LSB becomes 0.
  shift_lsb_zero: assert property (
    @(posedge clk) disable iff (reset) !load |=> (data_out[0] == 1'b0)
  );

  // Shift moves bit0 to bit1.
  shift_bit1_from_bit0: assert property (
    @(posedge clk) disable iff (reset) !load |=> (data_out[1] == $past(data_out[0]))
  );

  // Shift moves bit1 to bit2.
  shift_bit2_from_bit1: assert property (
    @(posedge clk) disable iff (reset) !load |=> (data_out[2] == $past(data_out[1]))
  );

  // Shift moves bit2 to bit3.
  shift_bit3_from_bit2: assert property (
    @(posedge clk) disable iff (reset) !load |=> (data_out[3] == $past(data_out[2]))
  );

  // After 4 consecutive shifts (no load), the register becomes 0.
  four_shifts_zero: assert property (
    @(posedge clk) disable iff (reset) (!load)[*4] |=> (data_out == 4'b0000)
  );

  // A load followed by a shift brings loaded bit2 to MSB two cycles later.
  load_then_shift_moves_loaded_bit2_to_msb: assert property (
    @(posedge clk) disable iff (reset) (load ##1 !load) |=> (data_out[3] == $past(data_in[2], 2))
  );

endmodule

rtl:
module mux4to1 (
    input [3:0] data_in,
    input [1:0] sel,
    output reg out
);

    always @(*) begin
        case(sel)
            2'b00: out = data_in[0];
            2'b01: out = data_in[1];
            2'b10: out = data_in[2];
            2'b11: out = data_in[3];
        endcase
    end

endmodule

sva:
module mux4to1_sva (
    input logic CLK,
    input logic [3:0] data_in,
    input logic [1:0] sel,
    input logic out
);
    // Output equals the selected input bit for all sel values.
    check_mux_function: assert property (
        @(posedge CLK) out == ((sel == 2'b00) ? data_in[0] :
                               (sel == 2'b01) ? data_in[1] :
                               (sel == 2'b10) ? data_in[2] : data_in[3])
    );

    // When sel==2'b00, out equals data_in[0].
    check_sel_00: assert property (
        @(posedge CLK) (sel == 2'b00) |-> (out == data_in[0])
    );

    // When sel==2'b01, out equals data_in[1].
    check_sel_01: assert property (
        @(posedge CLK) (sel == 2'b01) |-> (out == data_in[1])
    );

    // When sel==2'b10, out equals data_in[2].
    check_sel_10: assert property (
        @(posedge CLK) (sel == 2'b10) |-> (out == data_in[2])
    );

    // When sel==2'b11, out equals data_in[3].
    check_sel_11: assert property (
        @(posedge CLK) (sel == 2'b11) |-> (out == data_in[3])
    );

    // If sel is stable and the selected input changes, out follows that new value.
    check_out_follows_selected_change: assert property (
        @(posedge CLK) $stable(sel) && (data_in[sel] != $past(data_in[sel])) |-> (out == data_in[sel])
    );

    // If sel is stable and out changes, the selected input must have changed.
    check_out_change_requires_selected_change: assert property (
        @(posedge CLK) $stable(sel) && (out != $past(out)) |-> (data_in[sel] != $past(data_in[sel]))
    );

    // If sel and the selected input are both stable, out remains stable.
    check_stability_when_inputs_stable: assert property (
        @(posedge CLK) $stable(sel) && $stable(data_in[sel]) |-> $stable(out)
    );
endmodule

module data_register_sva (
    input logic reset,
    input logic wenb,
    input logic [7:0] in_data,
    input logic clk,
    input logic [7:0] out_data
);
    // Clock: clk. Reset: reset active-low (asynchronous). Sequential 8-bit register with write enable; hold otherwise.

    // While reset is asserted LOW, out_data must be 0x00.
    check_in_reset_forces_zero: assert property (
        @(posedge clk) (!reset) |-> (out_data == 8'h00)
    );

    // On the cycle after reset was LOW, out_data is still 0x00.
    check_post_reset_zero: assert property (
        @(posedge clk) $past(!reset) |-> (out_data == 8'h00)
    );

    // First cycle after deasserting reset with no write, out_data remains 0x00.
    check_deassert_no_write_keeps_zero: assert property (
        @(posedge clk) disable iff (!reset) ($past(!reset) && reset && !wenb) |-> (out_data == 8'h00)
    );

    // First cycle after deasserting reset with a write, next cycle out_data equals in_data of the deassert cycle.
    check_deassert_write_updates_next: assert property (
        @(posedge clk) disable iff (!reset) ($past(!reset) && reset && wenb) |-> ##1 (out_data == $past(in_data))
    );

    // With reset HIGH in consecutive cycles, a write in the previous cycle updates out_data with previous in_data.
    check_write_updates_from_prev_cycle: assert property (
        @(posedge clk) disable iff (!reset) ($past(reset) && $past(wenb)) |-> (out_data == $past(in_data))
    );

    // With reset HIGH in consecutive cycles, no write in the previous cycle holds out_data stable.
    check_hold_when_no_write: assert property (
        @(posedge clk) disable iff (!reset) ($past(reset) && !$past(wenb)) |-> (out_data == $past(out_data))
    );

endmodule

rtl:
module Register(input [31:0] IN, input Clk, Reset, Load, output reg [31:0] OUT);

    always @(posedge Clk) begin
        if (Reset) begin
            OUT <= 0;
        end else if (Load) begin
            OUT <= IN;
        end
    end

endmodule

sva:
module Register_sva (
    input logic [31:0] IN,
    input logic Clk,
    input logic Reset,
    input logic Load,
    input logic [31:0] OUT
);
    // On reset, OUT is cleared on the next cycle.
    check_reset_clears_out_next: assert property (
        @(posedge Clk) Reset |=> (OUT == 32'h0000_0000)
    );

    // Reset overrides Load when both asserted.
    check_reset_overrides_load: assert property (
        @(posedge Clk) (Reset && Load) |=> (OUT == 32'h0000_0000)
    );

    // While reset is held across cycles, OUT remains zero.
    check_out_zero_while_reset_held: assert property (
        @(posedge Clk) (Reset && $past(Reset)) |-> (OUT == 32'h0000_0000)
    );

    // With Load and not Reset, OUT captures IN on the next cycle.
    check_load_updates_out: assert property (
        @(posedge Clk) disable iff (Reset) Load |=> (OUT == $past(IN))
    );

    // When idle (no reset, no load), OUT holds its value.
    check_hold_when_idle: assert property (
        @(posedge Clk) disable iff (Reset) (!Load) |=> (OUT == $past(OUT))
    );

    // Any change to OUT must be caused by prior Reset or Load.
    check_out_change_has_cause: assert property (
        @(posedge Clk) disable iff (Reset) (OUT != $past(OUT)) |-> ($past(Reset) || ($past(Load) && !$past(Reset)))
    );

    // Two consecutive loads update OUT with the second cycle's IN.
    sequence two_consecutive_loads;
        (!Reset && Load) ##1 (!Reset && Load);
    endsequence
    check_two_consecutive_loads: assert property (
        @(posedge Clk) disable iff (Reset) two_consecutive_loads |=> (OUT == $past(IN))
    );

    // Two idle cycles (no reset, no load) keep OUT unchanged across both.
    check_two_idle_cycles_hold: assert property (
        @(posedge Clk) disable iff (Reset) (!Load && !Reset) ##1 (!Load && !Reset) |=> (OUT == $past(OUT,2))
    );
endmodule

rtl:
module counter_4bit(
    input clk,
    input reset,
    output reg [3:0] count,
    output reg max_count
);

always @(posedge clk or negedge reset) begin
    if (reset == 0) begin
        count <= 0;
        max_count <= 0;
    end else begin
        if (count == 4'hF) begin
            count <= 0;
            max_count <= 1;
        end else begin
            count <= count + 1;
            max_count <= 0;
        end
    end
end

endmodule

sva:
module counter_4bit_sva (
    input logic clk,
    input logic reset,          // active-low reset
    input logic [3:0] count,
    input logic max_count
);

    // While reset is asserted low, outputs are forced to 0.
    reset_forces_zero: assert property (
        @(posedge clk) (reset == 1'b0) |-> (count == 4'h0) && (max_count == 1'b0)
    );

    // When count is 0xF, next cycle wraps to 0 and pulses max_count.
    wrap_on_max: assert property (
        @(posedge clk) disable iff (reset == 1'b0) (count == 4'hF) |=> (count == 4'h0) && (max_count == 1'b1)
    );

    // When count is not 0xF, next cycle increments and clears max_count.
    increment_when_not_max: assert property (
        @(posedge clk) disable iff (reset == 1'b0) (count != 4'hF) |=> (count == $past(count) + 4'h1) && (max_count == 1'b0)
    );

    // max_count high implies count is zero in the same cycle.
    max_count_only_with_zero_count: assert property (
        @(posedge clk) disable iff (reset == 1'b0) max_count |-> (count == 4'h0)
    );

    // max_count can only be asserted following a 0xF state (out of reset).
    max_count_only_after_wrap: assert property (
        @(posedge clk) disable iff (reset == 1'b0) (max_count && $past(reset)) |-> ($past(count) == 4'hF)
    );

    // max_count is a single-cycle pulse.
    max_count_one_cycle_pulse: assert property (
        @(posedge clk) disable iff (reset == 1'b0) max_count |=> !max_count
    );

    // When count is 0xF, max_count must be 0 in the same cycle.
    max_low_when_count_is_F: assert property (
        @(posedge clk) disable iff (reset == 1'b0) (count == 4'hF) |-> (max_count == 1'b0)
    );

    // Out of reset, seeing count==0 implies the previous count was 0xF.
    zero_count_means_wrapped: assert property (
        @(posedge clk) disable iff (reset == 1'b0) (reset && $past(reset) && (count == 4'h0)) |-> ($past(count) == 4'hF)
    );

    // After a max_count pulse, next cycle count is 1 and max_count clears.
    next_after_maxcount_is_one: assert property (
        @(posedge clk) disable iff (reset == 1'b0) max_count |=> (count == 4'h1) && (max_count == 1'b0)
    );

    // Out of reset, each step follows either wrap-to-zero or increment-by-one rule.
    update_follows_spec: assert property (
        @(posedge clk) disable iff (reset == 1'b0)
            (reset && $past(reset)) |-> (
                ($past(count) == 4'hF) ? ((count == 4'h0) && (max_count == 1'b1))
                                       : ((count == $past(count) + 4'h1) && (max_count == 1'b0))
            )
    );

endmodule

rtl:
module up_counter (
    input clk,
    input rst,
    output reg [3:0] count
);

    always @(posedge clk) begin
        if (rst) begin
            count <= 4'b0;
        end else begin
            count <= count + 1;
        end
    end

endmodule

sva:
module up_counter_sva (
    input logic clk,
    input logic rst,
    input logic [3:0] count
);
    // On any clock where reset is asserted, count is driven to 0.
    check_reset_forces_zero: assert property (
        @(posedge clk) rst |-> (count == 4'b0000)
    );

    // When not in reset now and previously, count increments by 1.
    check_increment_when_no_reset: assert property (
        @(posedge clk) disable iff (rst) !$past(rst) |-> (count == $past(count) + 4'd1)
    );

    // First cycle after reset deasserts, count becomes 1.
    check_first_count_after_reset_release: assert property (
        @(posedge clk) $fell(rst) |-> (count == 4'd1)
    );

    // From 0xF, next value is 0 when not in reset.
    check_wrap_from_f_to_0_without_reset: assert property (
        @(posedge clk) disable iff (rst) ($past(count) == 4'hF) |-> (count == 4'h0)
    );

    // Over 2 consecutive cycles without reset, count increases by 2.
    check_two_cycle_increment_without_reset: assert property (
        @(posedge clk) disable iff (rst) (!$past(rst) && !$past(rst,2)) |-> (count == $past(count,2) + 4'd2)
    );

    // Over 16 consecutive cycles without reset, count returns to the prior value.
    check_periodicity_16_without_reset: assert property (
        @(posedge clk) disable iff (rst) !rst[*16] |-> (count == $past(count,16))
    );
endmodule

rtl:
module BOR (
  input Vin,
  input Vth,
  input clk,
  input reset,
  output rst_out
);

  reg bor_ff;

  always @ (posedge clk or negedge reset) begin
    if (!reset) begin
      bor_ff <= 0;
    end else begin
      if (Vin < Vth) begin
        bor_ff <= 1;
      end else begin
        bor_ff <= 0;
      end
    end
  end

  assign rst_out = bor_ff;

endmodule

sva:
module BOR_sva (
  input logic Vin,
  input logic Vth,
  input logic clk,
  input logic reset,
  input logic rst_out,
  input logic bor_ff
);

  // rst_out is 0 during active-low reset.
  check_reset_forces_rst_out_low: assert property (
    @(posedge clk) !reset |-> (rst_out == 1'b0)
  );

  // bor_ff is 0 during active-low reset.
  check_reset_clears_bor_ff: assert property (
    @(posedge clk) !reset |-> (bor_ff == 1'b0)
  );

  // rst_out mirrors internal bor_ff.
  check_rst_out_mirrors_bor_ff: assert property (
    @(posedge clk) disable iff (!reset) (rst_out == bor_ff)
  );

  // With reset high in consecutive cycles, rst_out equals prior-cycle (Vin < Vth).
  check_registered_comparator_mapping: assert property (
    @(posedge clk) disable iff (!reset) $past(reset) |-> (rst_out == $past(Vin < Vth))
  );

  // If prior-cycle (Vin < Vth) was true, rst_out is 1 now.
  check_prev_comp_true_sets_out: assert property (
    @(posedge clk) disable iff (!reset) ($past(reset) && $past(Vin < Vth)) |-> (rst_out == 1'b1)
  );

  // If prior-cycle (Vin < Vth) was false, rst_out is 0 now.
  check_prev_comp_false_clears_out: assert property (
    @(posedge clk) disable iff (!reset) ($past(reset) && !$past(Vin < Vth)) |-> (rst_out == 1'b0)
  );

  // A rising edge on rst_out matches a 0->1 transition of (Vin < Vth) in the prior cycle.
  check_out_rise_matches_comp_rise: assert property (
    @(posedge clk) disable iff (!reset) $rose(rst_out) |-> ($past(reset,2) &&  $past(Vin < Vth,1) && !$past(Vin < Vth,2))
  );

  // A falling edge on rst_out matches a 1->0 transition of (Vin < Vth) in the prior cycle.
  check_out_fall_matches_comp_fall: assert property (
    @(posedge clk) disable iff (!reset) $fell(rst_out) |-> ($past(reset,2) && !$past(Vin < Vth,1) &&  $past(Vin < Vth,2))
  );

  // If (Vin < Vth) is unchanged over the last two cycles, rst_out is stable now.
  check_out_stable_when_comp_unchanged: assert property (
    @(posedge clk) disable iff (!reset) ($past(reset,2) && ($past(Vin < Vth,1) == $past(Vin < Vth,2))) |-> $stable(rst_out)
  );

  // On reset deassertion cycle, rst_out remains 0 (update occurs after sampling).
  check_out_zero_on_reset_rise_cycle: assert property (
    @(posedge clk) disable iff (!reset) $rose(reset) |-> (rst_out == 1'b0)
  );

endmodule

rtl:
module and_8bit (
    input [7:0] A,
    input [7:0] B,
    input clk,
    output reg [7:0] Y
);

always @(posedge clk) begin
    Y = A & B;
end

endmodule

sva:
module and_8bit_sva (
    input logic [7:0] A,
    input logic [7:0] B,
    input logic clk,
    input logic [7:0] Y
);
    ///// Functional behavior /////
    // Next-cycle Y equals bitwise AND of current A and B.
    check_y_next_is_and_of_inputs: assert property (
        @(posedge clk) 1'b1 |=> (Y == $past(A & B))
    );

    // If B is all ones, next-cycle Y equals previous A.
    check_y_next_eq_prevA_when_B_all1: assert property (
        @(posedge clk) (B == 8'hFF) |=> (Y == $past(A))
    );

    // If A is all ones, next-cycle Y equals previous B.
    check_y_next_eq_prevB_when_A_all1: assert property (
        @(posedge clk) (A == 8'hFF) |=> (Y == $past(B))
    );

    // If A is all zeros, next-cycle Y is zero.
    check_y_next_zero_when_A_zero: assert property (
        @(posedge clk) (A == 8'h00) |=> (Y == 8'h00)
    );

    // If B is all zeros, next-cycle Y is zero.
    check_y_next_zero_when_B_zero: assert property (
        @(posedge clk) (B == 8'h00) |=> (Y == 8'h00)
    );

    // If A and B are stable over the last cycle, Y is stable over the next cycle.
    check_y_stable_when_inputs_stable: assert property (
        @(posedge clk) ($stable(A) && $stable(B)) |=> $stable(Y)
    );
endmodule

rtl:
module up_counter(
    input clk,
    input rst,
    output reg [3:0] count
);

always @(posedge clk or negedge rst) begin
    if (!rst) begin
        count <= 4'b0000;
    end else begin
        count <= count + 1;
    end
end

endmodule

sva:
module up_counter_sva (
    input logic clk,
    input logic rst,
    input logic [3:0] count
);

    // While reset is asserted LOW at a clock edge, count must be 0.
    check_reset_forces_zero: assert property (
        @(posedge clk) !rst |-> (count == 4'd0)
    );

    // If reset is LOW on two consecutive clock edges, count remains 0.
    check_zero_while_reset_low_consecutive: assert property (
        @(posedge clk) (!rst && $past(!rst)) |-> (count == 4'd0)
    );

    // On a sampled falling edge of reset, count is 0 at that clock edge.
    check_zero_on_reset_fall: assert property (
        @(posedge clk) $fell(rst) |-> (count == 4'd0)
    );

    // On the first clock edge after reset deasserts (LOW->HIGH), count is 1.
    check_first_count_after_reset_release: assert property (
        @(posedge clk) $rose(rst) |-> (count == 4'd1)
    );

    // When not in reset, count must be a known value (no X/Z).
    check_count_known_when_active: assert property (
        @(posedge clk) disable iff (!rst) !$isunknown(count)
    );

endmodule

rtl:
module setting_reg
  #(parameter my_addr = 0, 
    parameter width = 32,
    parameter at_reset=32'd0)
    (input clk, input rst, input strobe, input wire [7:0] addr,
     input wire [31:0] in, output reg [width-1:0] out, output reg changed);

   always @(posedge clk)
     if(rst)
       begin
	  out <= at_reset;
	  changed <= 1'b0;
       end
     else
       if(strobe & (my_addr==addr))
	 begin
	    out <= in;
	    changed <= 1'b1;
	 end
       else
	 changed <= 1'b0;

endmodule

sva:
module setting_reg_sva
  #(parameter my_addr = 0,
    parameter width = 32,
    parameter at_reset = 32'd0)
(
    input logic clk,
    input logic rst,
    input logic strobe,
    input logic [7:0] addr,
    input logic [31:0] in,
    input logic [width-1:0] out,
    input logic changed
);

    // After a cycle with rst asserted, outputs must hold reset values.
    check_reset_state_after_rst: assert property (
        @(posedge clk) disable iff (rst)
            $past(rst) |-> (out == at_reset) && (changed == 1'b0)
    );

    // A write hit last cycle updates out to the previous in[width-1:0].
    check_write_updates_out: assert property (
        @(posedge clk) disable iff (rst)
            $past(!rst && strobe && (my_addr == addr)) |-> (out == $past(in[width-1:0]))
    );

    // A write hit last cycle sets changed HIGH now.
    check_write_sets_changed: assert property (
        @(posedge clk) disable iff (rst)
            $past(!rst && strobe && (my_addr == addr)) |-> (changed == 1'b1)
    );

    // With no write last cycle (and not in reset), out holds its previous value.
    check_hold_out_no_write: assert property (
        @(posedge clk) disable iff (rst)
            $past(!rst && !(strobe && (my_addr == addr))) |-> (out == $past(out))
    );

    // With no write last cycle (and not in reset), changed is LOW now.
    check_clears_changed_no_write: assert property (
        @(posedge clk) disable iff (rst)
            $past(!rst && !(strobe && (my_addr == addr))) |-> (changed == 1'b0)
    );

    // A strobe with address mismatch last cycle does not update out.
    check_mismatch_strobe_holds_out: assert property (
        @(posedge clk) disable iff (rst)
            $past(!rst && strobe && (my_addr != addr)) |-> (out == $past(out))
    );

    // A strobe with address mismatch last cycle keeps changed LOW.
    check_mismatch_strobe_clears_changed: assert property (
        @(posedge clk) disable iff (rst)
            $past(!rst && strobe && (my_addr != addr)) |-> (changed == 1'b0)
    );

    // If changed is HIGH now, the previous cycle must have been a write hit.
    check_changed_implies_prev_write: assert property (
        @(posedge clk) disable iff (rst)
            changed |-> $past(!rst && strobe && (my_addr == addr))
    );

    // out can only change due to a reset last cycle or a write hit last cycle.
    check_out_changes_only_on_write_or_reset: assert property (
        @(posedge clk) disable iff (rst)
            $changed(out) |-> ($past(rst) || $past(!rst && strobe && (my_addr == addr)))
    );

    // If there was a write last cycle and no write this cycle, changed must be LOW now (single-cycle pulse).
    check_changed_pulse_no_back_to_back: assert property (
        @(posedge clk) disable iff (rst)
            ($past(!rst && strobe && (my_addr == addr)) && !(strobe && (my_addr == addr))) |-> (changed == 1'b0)
    );

endmodule

rtl:
module flip_flop(input D, SCD, SCE, RESET_B, VPWR, VGND, VPB, VNB, output Q, input CLK);

    // Instantiate the DFF module
    DFF dff(D, SCD, SCE, RESET_B, Q, CLK);

endmodule

module DFF(input D, SCD, SCE, RESET_B, output Q, input CLK);

    reg q;

    always @(posedge CLK or negedge RESET_B)
    begin
        if (!RESET_B)
            q <= 1'b0;
        else if (SCE)
            q <= D;
    end

    assign Q = q;

endmodule

sva:
module flip_flop_sva (
    input  logic D,
    input  logic SCD,
    input  logic SCE,
    input  logic RESET_B,  // Active-low async reset
    input  logic VPWR,
    input  logic VGND,
    input  logic VPB,
    input  logic VNB,
    input  logic Q,
    input  logic CLK
);
    // Reset low forces Q to 0 at every clock.
    reset_low_forces_zero: assert property (
        @(posedge CLK) (!RESET_B) |-> (Q == 1'b0)
    );

    // A falling edge on RESET_B clears Q to 0 by the next clock sample.
    reset_fall_clears_Q: assert property (
        @(posedge CLK) $fell(RESET_B) |-> (Q == 1'b0)
    );

    // With SCE HIGH, Q captures D on the next clock.
    capture_on_sce_high: assert property (
        @(posedge CLK) disable iff (!RESET_B) SCE |=> (Q == $past(D))
    );

    // With SCE LOW, Q holds its previous value.
    hold_on_sce_low: assert property (
        @(posedge CLK) disable iff (!RESET_B) !SCE |=> (Q == $past(Q))
    );

    // If SCE HIGH and D equals previous Q, Q does not change next cycle.
    sce_high_same_data_no_change: assert property (
        @(posedge CLK) disable iff (!RESET_B) (SCE && (D == $past(Q))) |=> (Q == $past(Q))
    );

    // If SCE HIGH and D differs from previous Q, Q must change next cycle.
    sce_high_diff_data_changes_q: assert property (
        @(posedge CLK) disable iff (!RESET_B) (SCE && (D != $past(Q))) |=> $changed(Q)
    );

    // Any Q change without a RESET_B fall implies prior SCE was HIGH.
    q_change_requires_sce_no_reset_edge: assert property (
        @(posedge CLK) disable iff (!RESET_B) ($changed(Q) && !$fell(RESET_B)) |-> $past(SCE)
    );

    // When SCE is LOW, SCD activity does not affect Q on the next clock.
    scd_change_no_effect_when_sce_low: assert property (
        @(posedge CLK) disable iff (!RESET_B) (!SCE && $changed(SCD)) |=> (Q == $past(Q))
    );

    // Next-state equation when no reset fall occurred in the interval.
    next_state_equation_without_reset_edge: assert property (
        @(posedge CLK) disable iff (!RESET_B) (!$fell(RESET_B)) |-> (Q == ($past(SCE) ? $past(D) : $past(Q)))
    );

    // After reset deasserts and with SCE LOW, Q remains 0 on the next clock.
    post_reset_release_no_load_holds_zero: assert property (
        @(posedge CLK) ($rose(RESET_B) && !SCE) |=> (Q == 1'b0)
    );
endmodule

module mux_3to1_enable_sva (
    input logic [3:0] a,
    input logic [3:0] b,
    input logic [3:0] c,
    input logic       en,
    input logic [1:0] sel,
    input logic [3:0] out
);

    // Out matches the RTL's effective function (r folded into selection).
    check_function_equivalence: assert property (
        @(posedge en or posedge sel[0] or posedge sel[1] or
          posedge a[0] or posedge a[1] or posedge a[2] or posedge a[3] or
          posedge b[0] or posedge b[1] or posedge b[2] or posedge b[3] or
          posedge c[0] or posedge c[1] or posedge c[2] or posedge c[3] or
          posedge out[0] or posedge out[1] or posedge out[2] or posedge out[3])
        out == (en ? (sel[1] ? a : (sel[0] ? b : 4'b0)) : 4'b0)
    );

    // When disabled, output must be 0.
    check_out_zero_when_disabled: assert property (
        @(posedge en or posedge sel[0] or posedge sel[1] or
          posedge a[0] or posedge a[1] or posedge a[2] or posedge a[3] or
          posedge b[0] or posedge b[1] or posedge b[2] or posedge b[3] or
          posedge c[0] or posedge c[1] or posedge c[2] or posedge c[3] or
          posedge out[0] or posedge out[1] or posedge out[2] or posedge out[3])
        (!en) |-> (out == 4'b0)
    );

    // When enabled and sel[1]=1, output selects a.
    check_select_a_when_sel1: assert property (
        @(posedge en or posedge sel[0] or posedge sel[1] or
          posedge a[0] or posedge a[1] or posedge a[2] or posedge a[3] or
          posedge b[0] or posedge b[1] or posedge b[2] or posedge b[3] or
          posedge c[0] or posedge c[1] or posedge c[2] or posedge c[3] or
          posedge out[0] or posedge out[1] or posedge out[2] or posedge out[3])
        (en && sel[1]) |-> (out == a)
    );

    // When enabled and sel[1]=0, sel[0]=1, output selects b.
    check_select_b_when_sel0_only: assert property (
        @(posedge en or posedge sel[0] or posedge sel[1] or
          posedge a[0] or posedge a[1] or posedge a[2] or posedge a[3] or
          posedge b[0] or posedge b[1] or posedge b[2] or posedge b[3] or
          posedge c[0] or posedge c[1] or posedge c[2] or posedge c[3] or
          posedge out[0] or posedge out[1] or posedge out[2] or posedge out[3])
        (en && !sel[1] && sel[0]) |-> (out == b)
    );

    // When enabled and sel==2'b00, output is 0.
    check_zero_when_enabled_sel00: assert property (
        @(posedge en or posedge sel[0] or posedge sel[1] or
          posedge a[0] or posedge a[1] or posedge a[2] or posedge a[3] or
          posedge b[0] or posedge b[1] or posedge b[2] or posedge b[3] or
          posedge c[0] or posedge c[1] or posedge c[2] or posedge c[3] or
          posedge out[0] or posedge out[1] or posedge out[2] or posedge out[3])
        (en && !sel[1] && !sel[0]) |-> (out == 4'b0)
    );

    // When enabled and both sel bits are 1, a has priority over b.
    check_a_priority_when_both_sel_high: assert property (
        @(posedge en or posedge sel[0] or posedge sel[1] or
          posedge a[0] or posedge a[1] or posedge a[2] or posedge a[3] or
          posedge b[0] or posedge b[1] or posedge b[2] or posedge b[3] or
          posedge c[0] or posedge c[1] or posedge c[2] or posedge c[3] or
          posedge out[0] or posedge out[1] or posedge out[2] or posedge out[3])
        (en && sel[1] && sel[0]) |-> (out == a)
    );

endmodule

rtl:
module karnaugh_map(
  input wire A, B, C,
  output reg F
);

  always @*
  begin
    case ({A,B,C})
      3'b000: F = 0;
      3'b001: F = 1;
      3'b010: F = 0;
      3'b011: F = 1;
      3'b100: F = 0;
      3'b101: F = 1;
      3'b110: F = 1;
      3'b111: F = 0;
    endcase
  end

endmodule

sva:
module karnaugh_map_sva (
    input logic CLK,
    input logic A,
    input logic B,
    input logic C,
    input logic F
);
    // F must be 0 when A,B,C = 000.
    check_map_000: assert property (
        @(posedge CLK) ({A,B,C} === 3'b000) |-> (F == 1'b0)
    );

    // F must be 1 when A,B,C = 001.
    check_map_001: assert property (
        @(posedge CLK) ({A,B,C} === 3'b001) |-> (F == 1'b1)
    );

    // F must be 0 when A,B,C = 010.
    check_map_010: assert property (
        @(posedge CLK) ({A,B,C} === 3'b010) |-> (F == 1'b0)
    );

    // F must be 1 when A,B,C = 011.
    check_map_011: assert property (
        @(posedge CLK) ({A,B,C} === 3'b011) |-> (F == 1'b1)
    );

    // F must be 0 when A,B,C = 100.
    check_map_100: assert property (
        @(posedge CLK) ({A,B,C} === 3'b100) |-> (F == 1'b0)
    );

    // F must be 1 when A,B,C = 101.
    check_map_101: assert property (
        @(posedge CLK) ({A,B,C} === 3'b101) |-> (F == 1'b1)
    );

    // F must be 1 when A,B,C = 110.
    check_map_110: assert property (
        @(posedge CLK) ({A,B,C} === 3'b110) |-> (F == 1'b1)
    );

    // F must be 0 when A,B,C = 111.
    check_map_111: assert property (
        @(posedge CLK) ({A,B,C} === 3'b111) |-> (F == 1'b0)
    );

    // F equals C XOR (A AND B) for all known inputs.
    check_function_equivalence: assert property (
        @(posedge CLK) !($isunknown({A,B,C})) |-> (F == (C ^ (A & B)))
    );
endmodule

rtl:
module de_PLL (
    areset,
    inclk0,
    c0
);

    input areset;
    input inclk0;
    output c0;

    // Phase detector
    wire phase_error;
    reg phase_error_d1;
    always @(posedge inclk0 or negedge areset) begin
        if (~areset) begin
            phase_error_d1 <= 0;
        end else begin
            phase_error_d1 <= phase_error;
        end
    end

    assign phase_error = (c0 & ~inclk0) | (~c0 & inclk0);

    // Charge pump
    reg [7:0] charge_pump_out;
    always @(posedge inclk0 or negedge areset) begin
        if (~areset) begin
            charge_pump_out <= 0;
        end else begin
            charge_pump_out <= (phase_error & (charge_pump_out < 8'h7f)) ? charge_pump_out + 1 : 
                               (~phase_error & (charge_pump_out > 8'h80)) ? charge_pump_out - 1 : charge_pump_out;
        end
    end

    // Loop filter
    reg [15:0] loop_filter_out;
    always @(posedge inclk0 or negedge areset) begin
        if (~areset) begin
            loop_filter_out <= 16'h0000;
        end else begin
            loop_filter_out <= loop_filter_out + charge_pump_out;
        end
    end

    // Voltage-controlled oscillator (VCO)
    reg [31:0] vco_out;
    always @(posedge inclk0 or negedge areset) begin
        if (~areset) begin
            vco_out <= 32'h00000000;
        end else begin
            vco_out <= vco_out + loop_filter_out;
        end
    end

    // Divide-by-2
    reg [31:0] div_by_2_out;
    always @(posedge vco_out[31] or negedge areset) begin
        if (~areset) begin
            div_by_2_out <= 32'h00000000;
        end else begin
            div_by_2_out <= {vco_out[30:0], ~vco_out[31]};
        end
    end

    // Output clock signal
    assign c0 = div_by_2_out[31];

endmodule

sva:
module de_PLL_sva (
    input logic areset,
    input logic inclk0,
    input logic c0,

    // Internal signals from RTL (bind/connect hierarchically)
    input logic        phase_error,
    input logic        phase_error_d1,
    input logic [7:0]  charge_pump_out,
    input logic [15:0] loop_filter_out,
    input logic [31:0] vco_out,
    input logic [31:0] div_by_2_out
);

    ///// Reset behavior /////
    // During reset, c0 must be LOW.
    reset_c0_low: assert property (
        @(posedge inclk0) (!areset) |-> (c0 == 1'b0)
    );
    // During reset, phase_error_d1 must be 0.
    reset_phase_error_d1_zero: assert property (
        @(posedge inclk0) (!areset) |-> (phase_error_d1 == 1'b0)
    );
    // During reset, charge_pump_out must be 0.
    reset_charge_pump_zero: assert property (
        @(posedge inclk0) (!areset) |-> (charge_pump_out == 8'h00)
    );
    // During reset, loop_filter_out must be 0.
    reset_loop_filter_zero: assert property (
        @(posedge inclk0) (!areset) |-> (loop_filter_out == 16'h0000)
    );
    // During reset, vco_out must be 0.
    reset_vco_zero: assert property (
        @(posedge inclk0) (!areset) |-> (vco_out == 32'h00000000)
    );
    // During reset, div_by_2_out must be 0.
    reset_div2_zero: assert property (
        @(posedge inclk0) (!areset) |-> (div_by_2_out == 32'h00000000)
    );

    ///// Phase detector /////
    // phase_error is combinational: (c0 & ~inclk0) | (~c0 & inclk0).
    comb_phase_error_def: assert property (
        @(posedge inclk0) disable iff (!areset) phase_error == ((c0 & ~inclk0) | (~c0 & inclk0))
    );
    // phase_error_d1 is one-cycle delayed sample of phase_error.
    pipe_phase_error_d1: assert property (
        @(posedge inclk0) disable iff (!areset) $past(areset) |-> (phase_error_d1 == $past(phase_error))
    );

    ///// Charge pump /////
    // charge_pump_out next-state matches saturating up/down rules.
    cp_nextstate_match: assert property (
        @(posedge inclk0) disable iff (!areset)
            $past(areset) |-> charge_pump_out ==
                ((phase_error && ($past(charge_pump_out) < 8'h7F)) ? ($past(charge_pump_out) + 8'd1) :
                 ((!phase_error && ($past(charge_pump_out) > 8'h80)) ? ($past(charge_pump_out) - 8'd1) :
                  $past(charge_pump_out)))
    );
    // charge_pump_out step size is at most +/-1 per cycle.
    cp_step_bound: assert property (
        @(posedge inclk0) disable iff (!areset)
            $past(areset) |-> (
                (charge_pump_out == $past(charge_pump_out)) ||
                (charge_pump_out == ($past(charge_pump_out) + 8'd1)) ||
                (charge_pump_out == ($past(charge_pump_out) - 8'd1))
            )
    );

    ///// Loop filter /////
    // loop_filter_out accumulates previous charge_pump_out.
    lf_accumulate: assert property (
        @(posedge inclk0) disable iff (!areset)
            $past(areset) |-> (loop_filter_out == ($past(loop_filter_out) + $past(charge_pump_out)))
    );

    ///// VCO /////
    // vco_out accumulates previous loop_filter_out.
    vco_accumulate: assert property (
        @(posedge inclk0) disable iff (!areset)
            $past(areset) |-> (vco_out == ($past(vco_out) + $past(loop_filter_out)))
    );

    ///// Divide-by-2 and output /////
    // c0 is the MSB of div_by_2_out.
    c0_matches_div2_msb: assert property (
        @(posedge inclk0) disable iff (!areset) (c0 == div_by_2_out[31])
    );

endmodule

