module full_adder (
    input A,
    input B,
    input CI,
    output SUM,
    output COUT_N
);

    // Local signals
    wire xor0_out_SUM ;
    wire a_b          ;
    wire a_ci         ;
    wire b_ci         ;
    wire or0_out_coutn;

    //  Name  Output         Other arguments
    xor xor0 (xor0_out_SUM , A, B, CI       );
    buf buf0 (SUM          , xor0_out_SUM   );
    nor nor0 (a_b          , A, B           );
    nor nor1 (a_ci         , A, CI          );
    nor nor2 (b_ci         , B, CI          );
    or  or0  (or0_out_coutn, a_b, a_ci, b_ci);
    buf buf1 (COUT_N       , or0_out_coutn  );

endmodule

sva:
module full_adder_sva (
    input logic A,
    input logic B,
    input logic CI,
    input logic SUM,
    input logic COUT_N
);
    // No clock/reset in DUT; combinational logic; sample on any input edge.

    // SUM equals three-input XOR of A, B, and CI.
    check_sum_is_three_input_xor: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge CI or negedge CI)
            SUM == (A ^ B ^ CI)
    );

    // COUT_N is the inverse of majority(A,B,CI) = ~(A&B | A&CI | B&CI).
    check_coutn_is_not_majority: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge CI or negedge CI)
            COUT_N == ~((A & B) | (A & CI) | (B & CI))
    );

    // When any two inputs are 1, COUT_N must be 0.
    check_carry_low_when_two_ones: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge CI or negedge CI)
            ((A & B) | (A & CI) | (B & CI)) |-> (COUT_N == 1'b0)
    );

    // When at most one input is 1, COUT_N must be 1.
    check_carry_high_when_zero_or_one_one: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge CI or negedge CI)
            ((~A & ~B) | (~A & ~CI) | (~B & ~CI)) |-> (COUT_N == 1'b1)
    );

    // If A equals B, SUM equals CI.
    check_sum_eq_ci_when_a_eq_b: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge CI or negedge CI)
            (A == B) |-> (SUM == CI)
    );

    // If A differs from B, SUM equals ~CI.
    check_sum_eq_not_ci_when_a_ne_b: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge CI or negedge CI)
            (A != B) |-> (SUM == ~CI)
    );

    // When all inputs are 0, SUM=0 and COUT_N=1.
    check_case_all_zero: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge CI or negedge CI)
            (~A & ~B & ~CI) |-> ((SUM == 1'b0) && (COUT_N == 1'b1))
    );

    // When exactly one input is 1, SUM=1 and COUT_N=1.
    check_case_exactly_one_one: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge CI or negedge CI)
            ((A & ~B & ~CI) | (~A & B & ~CI) | (~A & ~B & CI)) |-> ((SUM == 1'b1) && (COUT_N == 1'b1))
    );

    // When exactly two inputs are 1, SUM=0 and COUT_N=0.
    check_case_exactly_two_ones: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge CI or negedge CI)
            ((A & B & ~CI) | (A & CI & ~B) | (B & CI & ~A)) |-> ((SUM == 1'b0) && (COUT_N == 1'b0))
    );

    // When all inputs are 1, SUM=1 and COUT_N=0.
    check_case_all_one: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge CI or negedge CI)
            (A & B & CI) |-> ((SUM == 1'b1) && (COUT_N == 1'b0))
    );
endmodule

module comparator_2bit_sva (
    input logic clk,
    input logic [1:0] A,
    input logic [1:0] B,
    input logic [1:0] C
);

    ///// C[1] behavior /////
    // C[1] equals (A[1] & ~B[1]) per (A[1] > B[1]).
    check_c1_definition: assert property (
        @(posedge clk) C[1] == (A[1] & ~B[1])
    );

    // When MSBs are equal, C[1] must be 0.
    check_c1_zero_when_msbs_equal: assert property (
        @(posedge clk) (A[1] == B[1]) |-> (C[1] == 1'b0)
    );

    // When MSBs differ, C[1] equals A[1].
    check_c1_matches_a1_on_mismatch: assert property (
        @(posedge clk) (A[1] != B[1]) |-> (C[1] == A[1])
    );

    ///// C[0] behavior /////
    // When MSBs are equal, C[0] equals (A[0] >= B[0]).
    check_c0_when_msbs_equal: assert property (
        @(posedge clk) (A[1] == B[1]) |-> (C[0] == (A[0] >= B[0]))
    );

    // When MSBs differ, C[0] equals ~C[1].
    check_c0_complement_when_msbs_differ: assert property (
        @(posedge clk) (A[1] != B[1]) |-> (C[0] == ~C[1])
    );

    ///// Output coding /////
    // Output is never 2'b11.
    check_c_never_11: assert property (
        @(posedge clk) (C != 2'b11)
    );

    // If A[1]=1 and B[1]=0, output must be 2'b10.
    check_case_msbs_10: assert property (
        @(posedge clk) (A[1] && !B[1]) |-> (C == 2'b10)
    );

    // If A[1]=0 and B[1]=1, output must be 2'b01.
    check_case_msbs_01: assert property (
        @(posedge clk) (!A[1] && B[1]) |-> (C == 2'b01)
    );

    // If A[1]=0 and B[1]=0, C = {1'b0, (A[0] >= B[0])}.
    check_case_msbs_00: assert property (
        @(posedge clk) (!A[1] && !B[1]) |-> (C == {1'b0, (A[0] >= B[0])})
    );

    // If A[1]=1 and B[1]=1, C = {1'b0, (A[0] >= B[0])}.
    check_case_msbs_11: assert property (
        @(posedge clk) (A[1] && B[1]) |-> (C == {1'b0, (A[0] >= B[0])})
    );

    ///// Temporal sanity /////
    // Any rise of C[1] implies A[1]=1 and B[1]=0 at that time.
    check_c1_rise_condition: assert property (
        @(posedge clk) $rose(C[1]) |-> (A[1] && !B[1])
    );

endmodule

