module compare_and_concatenate(a, b, c);
    input [7:0] a, b;
    output [15:0] c;

    wire [7:0] diff;

    assign diff = (a >= b) ? (a-b) : (b-a);

    assign c = {diff, (a >= b) ? b : a};

endmodule

sva:
module compare_and_concatenate_sva (
    input logic CLK,
    input logic [7:0] a,
    input logic [7:0] b,
    input logic [15:0] c
);
    // c matches exact concatenation: {abs(a-b), min(a,b)}
    check_exact_concat: assert property (
        @(posedge CLK) c == { ((a >= b) ? (a - b) : (b - a)), ((a >= b) ? b : a) }
    );

    // When a >= b, upper byte equals a - b
    check_upper_when_ge: assert property (
        @(posedge CLK) (a >= b) |-> (c[15:8] == (a - b))
    );

    // When a >= b, lower byte equals b
    check_lower_when_ge: assert property (
        @(posedge CLK) (a >= b) |-> (c[7:0] == b)
    );

    // When a < b, upper byte equals b - a
    check_upper_when_lt: assert property (
        @(posedge CLK) (a < b) |-> (c[15:8] == (b - a))
    );

    // When a < b, lower byte equals a
    check_lower_when_lt: assert property (
        @(posedge CLK) (a < b) |-> (c[7:0] == a)
    );

    // If a == b, upper byte is 0 and lower byte equals a
    check_zero_when_equal: assert property (
        @(posedge CLK) (a == b) |-> (c == {8'h00, a})
    );

    // Lower byte equals one of the inputs (min(a,b))
    check_lower_is_input: assert property (
        @(posedge CLK) (c[7:0] == a) || (c[7:0] == b)
    );

    // Lower byte is less than or equal to both inputs
    check_lower_is_min_inequality: assert property (
        @(posedge CLK) (c[7:0] <= a) && (c[7:0] <= b)
    );

    // Upper byte equals absolute difference |a - b|
    check_upper_is_absdiff: assert property (
        @(posedge CLK) c[15:8] == ((a >= b) ? (a - b) : (b - a))
    );

    // Sum of upper and lower bytes equals max(a,b)
    check_sum_equals_max: assert property (
        @(posedge CLK) (c[15:8] + c[7:0]) == ((a >= b) ? a : b)
    );
endmodule

module d_ff_sc_ena_set_sva (
    input logic Q,
    input logic CLK,
    input logic D,
    input logic SCD,
    input logic SCE,
    input logic SET_B
);
    // Active-low SET_B forces Q to 0 whenever asserted.
    reset_forces_q0: assert property (
        @(posedge CLK) !SET_B |-> (Q == 1'b0)
    );

    // While SET_B stays low across cycles, Q remains 0.
    reset_holds_q0: assert property (
        @(posedge CLK) (!SET_B && $past(!SET_B)) |-> (Q == 1'b0)
    );

    // With SET_B high, when SCE is 1 load SCD on this clock.
    load_scan_path: assert property (
        @(posedge CLK) disable iff (!SET_B) SCE |=> (Q == $past(SCD))
    );

    // With SET_B high, when SCE is 0 load D on this clock.
    load_func_path: assert property (
        @(posedge CLK) disable iff (!SET_B) !SCE |=> (Q == $past(D))
    );

    // If SCE, SCD, and D are all stable, Q must be stable.
    stable_inputs_hold_q: assert property (
        @(posedge CLK) disable iff (!SET_B) $stable(SCE) && $stable(SCD) && $stable(D) |=> $stable(Q)
    );

    // If SCE is stably 1 and SCD is stable, Q stays stable.
    stable_scan_holds_q: assert property (
        @(posedge CLK) disable iff (!SET_B) SCE && $stable(SCE) && $stable(SCD) |=> $stable(Q)
    );

    // If SCE is stably 0 and D is stable, Q stays stable.
    stable_func_holds_q: assert property (
        @(posedge CLK) disable iff (!SET_B) !SCE && $stable(SCE) && $stable(D) |=> $stable(Q)
    );

    // If D and SCD are equal and both stable, Q takes that common value regardless of SCE.
    equal_inputs_propagate: assert property (
        @(posedge CLK) disable iff (!SET_B) (D == SCD) && $stable(D) && $stable(SCD) |=> (Q == $past(D))
    );
endmodule

