    // If X is 0 then B1=0, C1=0, and (A1 & A2)=0.
    check_x_low_implies_inputs_low: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge B1 or negedge B1 or posedge C1 or negedge C1)
        (X === 1'b0) |-> ((B1 === 1'b0) && (C1 === 1'b0) && ((A1 & A2) === 1'b0))
    );

    // If B1 is 1 then X must be 1.
    check_b1_high_implies_x_high: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge B1 or negedge B1 or posedge C1 or negedge C1)
        (B1 === 1'b1) |-> (X === 1'b1)
    );

    // If C1 is 1 then X must be 1.
    check_c1_high_implies_x_high: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge B1 or negedge B1 or posedge C1 or negedge C1)
        (C1 === 1'b1) |-> (X === 1'b1)
    );

    // If (A1 & A2) is 1 then X must be 1.
    check_and_term_implies_x_high: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge B1 or negedge B1 or posedge C1 or negedge C1)
        ((A1 & A2) === 1'b1) |-> (X === 1'b1)
    );

    // When B1=0 and C1=0, X equals (A1 & A2).
    check_reduce_to_and_when_b1c1_zero: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge B1 or negedge B1 or posedge C1 or negedge C1)
        ((B1 === 1'b0) && (C1 === 1'b0)) |-> (X === (A1 & A2))
    );

    // When A1=0, X reduces to (B1 | C1).
    check_a1_zero_reduces_to_b1_or_c1: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge B1 or negedge B1 or posedge C1 or negedge C1)
        (A1 === 1'b0) |-> (X === (B1 | C1))
    );

    // When A2=0, X reduces to (B1 | C1).
    check_a2_zero_reduces_to_b1_or_c1: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge B1 or negedge B1 or posedge C1 or negedge C1)
        (A2 === 1'b0) |-> (X === (B1 | C1))
    );

    // If A1=0, B1=0, C1=0 then X must be 0.
    check_all_low_implies_x_low: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge B1 or negedge B1 or posedge C1 or negedge C1)
        ((A1 === 1'b0) && (B1 === 1'b0) && (C1 === 1'b0)) |-> (X === 1'b0)
    );

    // If either B1 or C1 is 1 then X must be 1.
    check_side_inputs_or_implies_x_high: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge B1 or negedge B1 or posedge C1 or negedge C1)
        ((B1 | C1) === 1'b1) |-> (X === 1'b1)
    );
endmodule

rtl:
module adder_4bit (
  input [3:0] A, B,
  input CIN,
  output [3:0] S,
  output COUT
);

  wire [3:0] sum, carry;

  // Full Adder
  assign {carry[0], sum[0]} = A[0] + B[0] + CIN;
  assign {carry[1], sum[1]} = A[1] + B[1] + carry[0];
  assign {carry[2], sum[2]} = A[2] + B[2] + carry[1];
  assign {carry[3], sum[3]} = A[3] + B[3] + carry[2];
  assign COUT = carry[3];
  assign S = sum;

endmodule

sva:
module adder_4bit_sva (
    input logic CLK,
    input logic RESETn,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic CIN,
    input logic [3:0] S,
    input logic COUT
);
    // Outputs equal the 5-bit arithmetic sum of inputs.
    check_combined_sum_correct: assert property (
        @(posedge CLK) disable iff (!RESETn)
        {COUT, S} == ({1'b0, A} + {1'b0, B} + CIN)
    );

    // COUT is the MSB of the 5-bit sum.
    check_cout_is_msb_of_sum: assert property (
        @(posedge CLK) disable iff (!RESETn)
        COUT == (({1'b0, A} + {1'b0, B} + CIN)[4])
    );

    // LSB sum bit is XOR of input bits for a full-adder.
    check_s0_xor: assert property (
        @(posedge CLK) disable iff (!RESETn)
        S[0] == (A[0] ^ B[0] ^ CIN)
    );

    // No carry-out when total sum <= 15.
    check_no_carry_when_sum_le_15: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (({1'b0, A} + {1'b0, B} + CIN) <= 5'd15) |-> (COUT == 1'b0)
    );

    // Carry-out asserted when total sum >= 16.
    check_carry_when_sum_ge_16: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (({1'b0, A} + {1'b0, B} + CIN) >= 5'd16) |-> (COUT == 1'b1)
    );

    // Adding zero B with CIN=0 returns A, carry zero.
    check_add_zero_identity_b: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (B == 4'd0 && CIN == 1'b0) |-> ({COUT, S} == {1'b0, A})
    );

    // Adding zero A with CIN=0 returns B, carry zero.
    check_add_zero_identity_a: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (A == 4'd0 && CIN == 1'b0) |-> ({COUT, S} == {1'b0, B})
    );

    // With A=0 and B=0, sum equals CIN and carry is zero.
    check_zero_zero_cin_passthrough: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (A == 4'd0 && B == 4'd0) |-> (COUT == 1'b0 && S == {3'b000, CIN})
    );

    // With B bitwise complement of A and CIN=0, sum is 0xF and carry is zero.
    check_complement_no_carry_when_cin0: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (B == ~A && CIN == 1'b0) |-> (S == 4'hF && COUT == 1'b0)
    );

    // Corner case: 0xF + 0xF + 1 = 0xF with carry 1.
    check_max_plus_max_plus_one: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (A == 4'hF && B == 4'hF && CIN == 1'b1) |-> (S == 4'hF && COUT == 1'b1)
    );

    // If inputs are stable across a cycle, outputs remain stable.
    check_output_stable_when_inputs_stable: assert property (
        @(posedge CLK) disable iff (!RESETn)
        ($stable(A) && $stable(B) && $stable(CIN)) |-> $stable({COUT, S})
    );
endmodule

