module adder4(
    // Inputs
    input cin,
    input [3:0] a,
    input [3:0] b,

    // Outputs
    output [3:0] sum,
    output cout
);

wire [4:0] temp;

assign temp = a + b + cin;

assign sum = temp[3:0];
assign cout = temp[4];

endmodule

sva:
module adder4_sva (
    input logic cin,
    input logic [3:0] a,
    input logic [3:0] b,
    input logic [3:0] sum,
    input logic cout
);
    // Outputs equal the 5-bit sum of inputs.
    check_full_sum_match: assert property (
        @(posedge $global_clock) {cout, sum} == ({1'b0, a} + {1'b0, b} + cin)
    );

    // sum is the lower 4 bits of the 5-bit sum.
    check_sum_lower_bits: assert property (
        @(posedge $global_clock) sum == (({1'b0, a} + {1'b0, b} + cin)[3:0])
    );

    // cout is the MSB of the 5-bit sum.
    check_cout_is_msb: assert property (
        @(posedge $global_clock) cout == (({1'b0, a} + {1'b0, b} + cin)[4])
    );

    // If the 5-bit sum is less than 16, cout must be 0.
    check_no_carry_when_no_overflow: assert property (
        @(posedge $global_clock) (({1'b0, a} + {1'b0, b} + cin) < 5'd16) |-> (cout == 1'b0)
    );

    // If the 5-bit sum is at least 16, cout must be 1.
    check_carry_when_overflow: assert property (
        @(posedge $global_clock) (({1'b0, a} + {1'b0, b} + cin) >= 5'd16) |-> (cout == 1'b1)
    );

    // With zero inputs, sum equals cin in bit0 and cout is 0.
    check_zero_inputs_behavior: assert property (
        @(posedge $global_clock) (a == 4'b0000 && b == 4'b0000) |-> (sum == {3'b000, cin} && cout == 1'b0)
    );

    // When cin is 0, result equals a+b (5-bit).
    check_cin_zero_case: assert property (
        @(posedge $global_clock) (cin == 1'b0) |-> ({cout, sum} == ({1'b0, a} + {1'b0, b}))
    );

    // When cin is 1, result equals a+b+1 (5-bit).
    check_cin_one_case: assert property (
        @(posedge $global_clock) (cin == 1'b1) |-> ({cout, sum} == ({1'b0, a} + {1'b0, b} + 5'd1))
    );

    // If inputs are stable cycle-to-cycle, outputs must be stable.
    check_stable_outputs_when_inputs_stable: assert property (
        @(posedge $global_clock) $stable({a, b, cin}) |-> $stable({sum, cout})
    );

    // Max inputs with cin=0 produce 30 => sum=14, cout=1.
    check_max_inputs_cin0: assert property (
        @(posedge $global_clock) (a == 4'hF && b == 4'hF && cin == 1'b0) |-> (sum == 4'hE && cout == 1'b1)
    );

    // Max inputs with cin=1 produce 31 => sum=15, cout=1.
    check_max_inputs_cin1: assert property (
        @(posedge $global_clock) (a == 4'hF && b == 4'hF && cin == 1'b1) |-> (sum == 4'hF && cout == 1'b1)
    );
endmodule

rtl:
module sky130_fd_sc_hd__and4b (
    X   ,
    A_N ,
    B   ,
    C   ,
    D   ,
    VPWR,
    VGND,
    VPB ,
    VNB
);

    // Module ports
    output X   ;
    input  A_N ;
    input  B   ;
    input  C   ;
    input  D   ;
    input  VPWR;
    input  VGND;
    input  VPB ;
    input  VNB ;

    // Local signals
    wire not0_out         ;
    wire and0_out_X       ;

    // Inverter
    not not0 (not0_out, A_N);

    // 3-input AND gate
    and and0 (and0_out_X, not0_out, B, C, D);

    // Buffer
    buf buf0 (X, and0_out_X);

endmodule

sva:
module sky130_fd_sc_hd__and4b_sva (
    input logic X,
    input logic A_N,
    input logic B,
    input logic C,
    input logic D,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB
);
    // Combinational equivalence: X == (~A_N & B & C & D).
    check_function_equivalence: assert property (
        @(posedge A_N or negedge A_N or posedge B or negedge B or posedge C or negedge C or posedge D or negedge D)
            (X === ((~A_N) & B & C & D))
    );

    // A_N high forces X low.
    check_A_N_high_forces_X_low: assert property (
        @(posedge A_N or negedge A_N or posedge B or negedge B or posedge C or negedge C or posedge D or negedge D)
            (A_N === 1'b1) |-> (X === 1'b0)
    );

    // B low forces X low.
    check_B_zero_forces_X_low: assert property (
        @(posedge A_N or negedge A_N or posedge B or negedge B or posedge C or negedge C or posedge D or negedge D)
            (B === 1'b0) |-> (X === 1'b0)
    );

    // C low forces X low.
    check_C_zero_forces_X_low: assert property (
        @(posedge A_N or negedge A_N or posedge B or negedge B or posedge C or negedge C or posedge D or negedge D)
            (C === 1'b0) |-> (X === 1'b0)
    );

    // D low forces X low.
    check_D_zero_forces_X_low: assert property (
        @(posedge A_N or negedge A_N or posedge B or negedge B or posedge C or negedge C or posedge D or negedge D)
            (D === 1'b0) |-> (X === 1'b0)
    );

    // All inputs true (with A_N low) forces X high.
    check_all_inputs_true_forces_X_high: assert property (
        @(posedge A_N or negedge A_N or posedge B or negedge B or posedge C or negedge C or posedge D or negedge D)
            ((A_N === 1'b0) && (B === 1'b1) && (C === 1'b1) && (D === 1'b1)) |-> (X === 1'b1)
    );

    // X high implies A_N low and B,C,D high.
    check_X_high_implies_inputs_true: assert property (
        @(posedge A_N or negedge A_N or posedge B or negedge B or posedge C or negedge C or posedge D or negedge D)
            (X === 1'b1) |-> ((A_N === 1'b0) && (B === 1'b1) && (C === 1'b1) && (D === 1'b1))
    );

    // With inputs stable, X is stable.
    check_stable_inputs_imply_stable_X: assert property (
        @(posedge A_N or negedge A_N or posedge B or negedge B or posedge C or negedge C or posedge D or negedge D)
            ($stable(A_N) && $stable(B) && $stable(C) && $stable(D)) |-> $stable(X)
    );

    // Falling B drives X low immediately.
    check_B_fall_forces_X_low: assert property (
        @(posedge A_N or negedge A_N or posedge B or negedge B or posedge C or negedge C or posedge D or negedge D)
            $fell(B) |-> (X === 1'b0)
    );

    // Falling C drives X low immediately.
    check_C_fall_forces_X_low: assert property (
        @(posedge A_N or negedge A_N or posedge B or negedge B or posedge C or negedge C or posedge D or negedge D)
            $fell(C) |-> (X === 1'b0)
    );

    // Falling D drives X low immediately.
    check_D_fall_forces_X_low: assert property (
        @(posedge A_N or negedge A_N or posedge B or negedge B or posedge C or negedge C or posedge D or negedge D)
            $fell(D) |-> (X === 1'b0)
    );

    // Rising A_N drives X low immediately.
    check_A_N_rise_forces_X_low: assert property (
        @(posedge A_N or negedge A_N or posedge B or negedge B or posedge C or negedge C or posedge D or negedge D)
            $rose(A_N) |-> (X === 1'b0)
    );

    // Falling A_N with others high drives X high immediately.
    check_A_N_fall_others_high_sets_X_high: assert property (
        @(posedge A_N or negedge A_N or posedge B or negedge B or posedge C or negedge C or posedge D or negedge D)
            ($fell(A_N) && (B === 1'b1) && (C === 1'b1) && (D === 1'b1)) |-> (X === 1'b1)
    );

    // Rising B with A_N low and C,D high drives X high immediately.
    check_B_rise_others_true_sets_X_high: assert property (
        @(posedge A_N or negedge A_N or posedge B or negedge B or posedge C or negedge C or posedge D or negedge D)
            ($rose(B) && (A_N === 1'b0) && (C === 1'b1) && (D === 1'b1)) |-> (X === 1'b1)
    );

    // Rising C with A_N low and B,D high drives X high immediately.
    check_C_rise_others_true_sets_X_high: assert property (
        @(posedge A_N or negedge A_N or posedge B or negedge B or posedge C or negedge C or posedge D or negedge D)
            ($rose(C) && (A_N === 1'b0) && (B === 1'b1) && (D === 1'b1)) |-> (X === 1'b1)
    );

    // Rising D with A_N low and B,C high drives X high immediately.
    check_D_rise_others_true_sets_X_high: assert property (
        @(posedge A_N or negedge A_N or posedge B or negedge B or posedge C or negedge C or posedge D or negedge D)
            ($rose(D) && (A_N === 1'b0) && (B === 1'b1) && (C === 1'b1)) |-> (X === 1'b1)
    );
endmodule

rtl:
module full_adder(a,b,cin,sum,cout);
    input a,b,cin;
    output sum,cout;

    wire w1,w2,w3;

    xor(w1,a,b);
    xor(sum,w1,cin);
    and(w2,w1,cin);
    and(w3,a,b);
    or(cout,w2,w3);
endmodule

module four_bit_adder(a,b,cin,sum,cout);
    input [3:0] a,b;
    input cin;
    output [3:0] sum;
    output cout;

    wire c1,c2,c3;
    full_adder fa0(a[0],b[0],cin,sum[0],c1);
    full_adder fa1(a[1],b[1],c1,sum[1],c2);
    full_adder fa2(a[2],b[2],c2,sum[2],c3);
    full_adder fa3(a[3],b[3],c3,sum[3],cout);
endmodule

sva:
module four_bit_adder_sva (
    input logic clk,
    input logic [3:0] a,
    input logic [3:0] b,
    input logic cin,
    input logic [3:0] sum,
    input logic cout
);
    // Local expression helpers for ripple-carry chain
    let c1 = (a[0] & b[0]) | (a[0] & cin) | (b[0] & cin);
    let c2 = (a[1] & b[1]) | (a[1] & c1 ) | (b[1] & c1 );
    let c3 = (a[2] & b[2]) | (a[2] & c2 ) | (b[2] & c2 );
    let c4 = (a[3] & b[3]) | (a[3] & c3 ) | (b[3] & c3 );

    ///// Functional correctness /////
    // 5-bit result equals a + b + cin (unsigned addition).
    check_addition_result: assert property (
        @(posedge clk) {cout, sum} == ({1'b0, a} + {1'b0, b} + cin)
    );

    ///// Bit-slice correctness /////
    // LSB sum is XOR of a[0], b[0], and cin.
    check_sum0_xor: assert property (
        @(posedge clk) sum[0] == (a[0] ^ b[0] ^ cin)
    );
    // Bit1 sum is XOR of a[1], b[1], and carry from bit0.
    check_sum1_xor_with_c1: assert property (
        @(posedge clk) sum[1] == (a[1] ^ b[1] ^ c1)
    );
    // Bit2 sum is XOR of a[2], b[2], and carry from bit1.
    check_sum2_xor_with_c2: assert property (
        @(posedge clk) sum[2] == (a[2] ^ b[2] ^ c2)
    );
    // Bit3 sum is XOR of a[3], b[3], and carry from bit2.
    check_sum3_xor_with_c3: assert property (
        @(posedge clk) sum[3] == (a[3] ^ b[3] ^ c3)
    );
    // Carry-out equals carry generated at bit3.
    check_cout_matches_c4: assert property (
        @(posedge clk) cout == c4
    );

    ///// Simple corner cases /////
    // Adding zero and zero yields sum = cin on bit0 and cout = 0.
    check_zero_plus_zero: assert property (
        @(posedge clk) ((a == 4'b0000) && (b == 4'b0000)) |-> ((sum == {3'b000, cin}) && (cout == 1'b0))
    );
    // Adding zero with cin=0 passes through the other operand (a path).
    check_add_zero_b: assert property (
        @(posedge clk) ((b == 4'b0000) && (cin == 1'b0)) |-> ((sum == a) && (cout == 1'b0))
    );
    // Adding zero with cin=0 passes through the other operand (b path).
    check_add_zero_a: assert property (
        @(posedge clk) ((a == 4'b0000) && (cin == 1'b0)) |-> ((sum == b) && (cout == 1'b0))
    );
endmodule

rtl:
module jmp_cond (
    input [4:0]  logic_flags,
    input [3:0]  cond,
    input        is_cx,
    input [15:0] cx,
    output reg   jmp
  );

  wire of, sf, zf, pf, cf;
  wire cx_zero;

  assign of = logic_flags[4];
  assign sf = logic_flags[3];
  assign zf = logic_flags[2];
  assign pf = logic_flags[1];
  assign cf = logic_flags[0];
  assign cx_zero = ~(|cx);

  always @(cond or is_cx or cx_zero or zf or of or cf or sf or pf)
    if (is_cx) case (cond)
        4'b0000: jmp <= cx_zero;         
        4'b0001: jmp <= ~cx_zero;        
        4'b0010: jmp <= zf & ~cx_zero;   
        default: jmp <= ~zf & ~cx_zero; 
      endcase
    else case (cond)
      4'b0000: jmp <= of;
      4'b0001: jmp <= ~of;
      4'b0010: jmp <= cf;
      4'b0011: jmp <= ~cf;
      4'b0100: jmp <= zf;
      4'b0101: jmp <= ~zf;
      4'b0110: jmp <= cf | zf;
      4'b0111: jmp <= ~cf & ~zf;

      4'b1000: jmp <= sf;
      4'b1001: jmp <= ~sf;
      4'b1010: jmp <= pf;
      4'b1011: jmp <= ~pf;
      4'b1100: jmp <= (sf ^ of);
      4'b1101: jmp <= (sf ^~ of);
      4'b1110: jmp <= zf | (sf ^ of);
      4'b1111: jmp <= ~zf & (sf ^~ of);
    endcase
endmodule

sva:
module jmp_cond_sva (
    input logic [4:0] logic_flags,
    input logic [3:0] cond,
    input logic       is_cx,
    input logic [15:0] cx,
    input logic       jmp
);
    // Derived flag bits
    wire of = logic_flags[4];
    wire sf = logic_flags[3];
    wire zf = logic_flags[2];
    wire pf = logic_flags[1];
    wire cf = logic_flags[0];
    wire cx_zero = ~(|cx);

    ///// is_cx path /////
    // When is_cx and cond==0000, jmp equals cx_zero.
    check_is_cx_cond_0000: assert property (
        @(posedge $global_clock) (is_cx && (cond == 4'b0000)) |=> (jmp == cx_zero)
    );
    // When is_cx and cond==0001, jmp equals ~cx_zero.
    check_is_cx_cond_0001: assert property (
        @(posedge $global_clock) (is_cx && (cond == 4'b0001)) |=> (jmp == ~cx_zero)
    );
    // When is_cx and cond==0010, jmp equals zf & ~cx_zero.
    check_is_cx_cond_0010: assert property (
        @(posedge $global_clock) (is_cx && (cond == 4'b0010)) |=> (jmp == (zf & ~cx_zero))
    );
    // When is_cx and cond in {0011,0100..1111}, jmp equals ~zf & ~cx_zero.
    check_is_cx_cond_default: assert property (
        @(posedge $global_clock)
            (is_cx &&
             ((cond == 4'b0011) || (cond == 4'b0100) || (cond == 4'b0101) || (cond == 4'b0110) ||
              (cond == 4'b0111) || (cond == 4'b1000) || (cond == 4'b1001) || (cond == 4'b1010) ||
              (cond == 4'b1011) || (cond == 4'b1100) || (cond == 4'b1101) || (cond == 4'b1110) ||
              (cond == 4'b1111)))
        |=> (jmp == (~zf & ~cx_zero))
    );

    ///// !is_cx path /////
    // When !is_cx and cond==0000, jmp equals of.
    check_no_cx_cond_0000: assert property (
        @(posedge $global_clock) (!is_cx && (cond == 4'b0000)) |=> (jmp == of)
    );
    // When !is_cx and cond==0001, jmp equals ~of.
    check_no_cx_cond_0001: assert property (
        @(posedge $global_clock) (!is_cx && (cond == 4'b0001)) |=> (jmp == ~of)
    );
    // When !is_cx and cond==0010, jmp equals cf.
    check_no_cx_cond_0010: assert property (
        @(posedge $global_clock) (!is_cx && (cond == 4'b0010)) |=> (jmp == cf)
    );
    // When !is_cx and cond==0011, jmp equals ~cf.
    check_no_cx_cond_0011: assert property (
        @(posedge $global_clock) (!is_cx && (cond == 4'b0011)) |=> (jmp == ~cf)
    );
    // When !is_cx and cond==0100, jmp equals zf.
    check_no_cx_cond_0100: assert property (
        @(posedge $global_clock) (!is_cx && (cond == 4'b0100)) |=> (jmp == zf)
    );
    // When !is_cx and cond==0101, jmp equals ~zf.
    check_no_cx_cond_0101: assert property (
        @(posedge $global_clock) (!is_cx && (cond == 4'b0101)) |=> (jmp == ~zf)
    );
    // When !is_cx and cond==0110, jmp equals cf | zf.
    check_no_cx_cond_0110: assert property (
        @(posedge $global_clock) (!is_cx && (cond == 4'b0110)) |=> (jmp == (cf | zf))
    );
    // When !is_cx and cond==0111, jmp equals ~cf & ~zf.
    check_no_cx_cond_0111: assert property (
        @(posedge $global_clock) (!is_cx && (cond == 4'b0111)) |=> (jmp == (~cf & ~zf))
    );
    // When !is_cx and cond==1000, jmp equals sf.
    check_no_cx_cond_1000: assert property (
        @(posedge $global_clock) (!is_cx && (cond == 4'b1000)) |=> (jmp == sf)
    );
    // When !is_cx and cond==1001, jmp equals ~sf.
    check_no_cx_cond_1001: assert property (
        @(posedge $global_clock) (!is_cx && (cond == 4'b1001)) |=> (jmp == ~sf)
    );
    // When !is_cx and cond==1010, jmp equals pf.
    check_no_cx_cond_1010: assert property (
        @(posedge $global_clock) (!is_cx && (cond == 4'b1010)) |=> (jmp == pf)
    );
    // When !is_cx and cond==1011, jmp equals ~pf.
    check_no_cx_cond_1011: assert property (
        @(posedge $global_clock) (!is_cx && (cond == 4'b1011)) |=> (jmp == ~pf)
    );
    // When !is_cx and cond==1100, jmp equals sf ^ of.
    check_no_cx_cond_1100: assert property (
        @(posedge $global_clock) (!is_cx && (cond == 4'b1100)) |=> (jmp == (sf ^ of))
    );
    // When !is_cx and cond==1101, jmp equals sf XNOR of.
    check_no_cx_cond_1101: assert property (
        @(posedge $global_clock) (!is_cx && (cond == 4'b1101)) |=> (jmp == (sf ^~ of))
    );
    // When !is_cx and cond==1110, jmp equals zf | (sf ^ of).
    check_no_cx_cond_1110: assert property (
        @(posedge $global_clock) (!is_cx && (cond == 4'b1110)) |=> (jmp == (zf | (sf ^ of)))
    );
    // When !is_cx and cond==1111, jmp equals ~zf & (sf XNOR of).
    check_no_cx_cond_1111: assert property (
        @(posedge $global_clock) (!is_cx && (cond == 4'b1111)) |=> (jmp == (~zf & (sf ^~ of)))
    );
