d_ff dff4 (.clk(clk), .d(d[4]), .q(q[4]));
d_ff dff5 (.clk(clk), .d(d[5]), .q(q[5]));
d_ff dff6 (.clk(clk), .d(d[6]), .q(q[6]));
d_ff dff7 (.clk(clk), .d(d[7]), .q(q[7]));

// Logic function module instantiation
