module logic_function (
    input [7:0] in,
    input select,
    output out
);
wire [7:0] and_out;
wire [7:0] or_out;
wire [7:0] xor_out;

assign and_out = &in;
assign or_out = |in;
assign xor_out = ^in;

// Select the output of the desired logic function
assign out = select ? (select == 2'b01 ? or_out : xor_out) : and_out; // Fixed the case statement

endmodule

