    input [3:0] b,
    input cin,
    output [3:0] sum,
    output cout
   );

   wire [3:0] s;
   wire [3:0] c;

   compressor2 #(.width(1)) c1(a[0], b[0], s[0], c[0]);
   compressor2 #(.width(1)) c2(s[0], b[1], s[1], c[1]);
   compressor2 #(.width(1)) c3(s[1], b[2], s[2], c[2]);
