module up_counter_4bit_async_reset_sva (
    input logic clk,
    input logic rst,          // active-low async reset
    input logic [3:0] q
);

    // When reset is asserted (low) at a clock edge, q must be zero.
    reset_forces_zero: assert property (
        @(posedge clk) (!rst) |-> (q == 4'd0)
    );

    // On reset deassertion ($rose of rst), q becomes 1 (increment from 0).
    deassertion_sets_one: assert property (
        @(posedge clk) $rose(rst) |-> (q == 4'd1)
    );

    // In non-reset, if q is 0 now, it must have wrapped from 15 last cycle.
    nonreset_zero_implies_wrap: assert property (
        @(posedge clk) disable iff (!rst) ($past(1'b1) && (q == 4'd0)) |-> ($past(rst) && ($past(q) == 4'd15))
    );

    // In non-reset, if q is 2..15 now, last q must be q-1.
    nonreset_mid_values_step: assert property (
        @(posedge clk) disable iff (!rst) ($past(1'b1) && (q inside {[4'd2:4'd15]})) |-> ($past(rst) && ($past(q) == (q - 4'd1)))
    );

    // In non-reset, if last q was 0, current q must be 1.
    nonreset_prev_zero_to_one: assert property (
        @(posedge clk) disable iff (!rst) ($past(1'b1) && $past(rst) && ($past(q) == 4'd0)) |-> (q == 4'd1)
    );

    // In non-reset, if last q was 15, current q is either 0 (wrap) or 1 (if async reset glitched between edges).
    nonreset_prev_fifteen_results_0_or_1: assert property (
        @(posedge clk) disable iff (!rst) ($past(1'b1) && $past(rst) && ($past(q) == 4'd15)) |-> (q inside {4'd0, 4'd1})
    );

endmodule

rtl:
module shift_register (
    input clk,
    input reset,
    input [7:0] data_in,
    input [1:0] shift_direction,
    input load,
    output reg [7:0] q
);

always @(posedge clk or negedge reset) begin
    if (!reset) begin
        q <= 8'd0;
    end else if (load) begin
        q <= data_in;
    end else begin
        if (shift_direction == 2'b00) begin
            q <= {q[6:0], q[7]};
        end else if (shift_direction == 2'b01) begin
            q <= {q[0], q[7:1]};
        end
    end
end

endmodule

module min_finder (
    input [7:0] a, b, c, d,
    output reg [7:0] min
);

always @(*) begin
    min = a;
    if (b < min) min = b;
    if (c < min) min = c;
    if (d < min) min = d;
end

endmodule

module top_module (
    input clk,
    input reset,
    input [7:0] data_in,
    input [1:0] shift_direction,
    input load,
    input [7:0] a, b, c, d,
    output [7:0] q,
    output [7:0] min,
    output [7:0] final_output
);

shift_register sr (
    .clk(clk),
    .reset(reset),
    .data_in(data_in),
    .shift_direction(shift_direction),
    .load(load),
    .q(q)
);

min_finder mf (
    .a(a),
    .b(b),
    .c(c),
    .d(d),
    .min(min)
);

assign final_output = min & q;

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic reset,
    input logic [7:0] data_in,
    input logic [1:0] shift_direction,
    input logic load,
    input logic [7:0] a, b, c, d,
    input logic [7:0] q,
    input logic [7:0] min,
    input logic [7:0] final_output
);

    ///// Reset behavior (active-low) /////
    // While reset is asserted low, q must be 0.
    reset_q_zero: assert property (
        @(posedge clk) !reset |-> (q == 8'h00)
    );

    // While reset is asserted low, final_output must be 0 (since q is 0).
    reset_final_output_zero: assert property (
        @(posedge clk) !reset |-> (final_output == 8'h00)
    );

    ///// Shift register behavior /////
    // On load, q captures data_in on the next cycle.
    load_captures_data: assert property (
        @(posedge clk) disable iff (!reset) load |=> (q == $past(data_in))
    );

    // When not loading and shift_direction==00, q rotates left by 1 on next cycle.
    rotate_left_when_dir00: assert property (
        @(posedge clk) disable iff (!reset)
            (!load && (shift_direction == 2'b00)) |=> (q == { $past(q)[6:0], $past(q)[7] })
    );

    // When not loading and shift_direction==01, q rotates right by 1 on next cycle.
    rotate_right_when_dir01: assert property (
        @(posedge clk) disable iff (!reset)
            (!load && (shift_direction == 2'b01)) |=> (q == { $past(q)[0], $past(q)[7:1] })
    );

    // When not loading and shift_direction is 10 or 11, q holds its value.
    hold_when_dir_others: assert property (
        @(posedge clk) disable iff (!reset)
            (!load && (shift_direction inside {2'b10, 2'b11})) |=> (q == $past(q))
    );

    ///// min_finder (combinational) /////
    // min must be less than or equal to each input.
    min_is_bounded_by_inputs: assert property (
        @(posedge clk) disable iff (!reset) (min <= a) && (min <= b) && (min <= c) && (min <= d)
    );

    // min must equal one of the inputs.
    min_is_one_of_inputs: assert property (
        @(posedge clk) disable iff (!reset) (min == a) || (min == b) || (min == c) || (min == d)
    );

    // If a is less-or-equal to all, min must be a.
    min_selects_a_when_least: assert property (
        @(posedge clk) disable iff (!reset) (a <= b) && (a <= c) && (a <= d) |-> (min == a)
    );

    // If b is strictly less than a and <= c,d, min must be b (reflecting tie-break order).
    min_selects_b_when_least: assert property (
        @(posedge clk) disable iff (!reset) (b < a) && (b <= c) && (b <= d) |-> (min == b)
    );

    ///// Final output /////
    // final_output is the bitwise AND of min and q.
    final_output_is_and: assert property (
        @(posedge clk) disable iff (!reset) final_output == (min & q)
    );

endmodule

module mux_2to1_sva (
    input logic a,
    input logic b,
    input logic sel_b1,
    input logic sel_b2,
    input logic out_always
);
    // Output implements (sel_b1 && sel_b2) ? b : a.
    check_mux_function: assert property (
        @(posedge a or negedge a or posedge b or negedge b or posedge sel_b1 or negedge sel_b1 or posedge sel_b2 or negedge sel_b2 or posedge out_always or negedge out_always)
            out_always == ((sel_b1 && sel_b2) ? b : a)
    );

    // When both selects are HIGH, output equals b.
    check_b_selected: assert property (
        @(posedge a or negedge a or posedge b or negedge b or posedge sel_b1 or negedge sel_b1 or posedge sel_b2 or negedge sel_b2 or posedge out_always or negedge out_always)
            (sel_b1 && sel_b2) |-> (out_always == b)
    );

    // When selects are not both HIGH, output equals a.
    check_a_selected: assert property (
        @(posedge a or negedge a or posedge b or negedge b or posedge sel_b1 or negedge sel_b1 or posedge sel_b2 or negedge sel_b2 or posedge out_always or negedge out_always)
            (!(sel_b1 && sel_b2)) |-> (out_always == a)
    );

    // If output differs from a, both selects must be HIGH.
    check_not_a_implies_select_b: assert property (
        @(posedge a or negedge a or posedge b or negedge b or posedge sel_b1 or negedge sel_b1 or posedge sel_b2 or negedge sel_b2 or posedge out_always or negedge out_always)
            (out_always != a) |-> (sel_b1 && sel_b2)
    );

    // Changes on b are gated when not both selects HIGH (a stable).
    check_b_gated_when_not_selected: assert property (
        @(posedge a or negedge a or posedge b or negedge b or posedge sel_b1 or negedge sel_b1 or posedge sel_b2 or negedge sel_b2 or posedge out_always or negedge out_always)
            ((!sel_b1 || !sel_b2) && $stable(a) && $changed(b)) |-> $stable(out_always)
    );

    // With both selects HIGH, a-changes do not affect output (b stable).
    check_a_ignored_when_b_selected: assert property (
        @(posedge a or negedge a or posedge b or negedge b or posedge sel_b1 or negedge sel_b1 or posedge sel_b2 or negedge sel_b2 or posedge out_always or negedge out_always)
            ((sel_b1 && sel_b2) && $stable(b) && $changed(a)) |-> $stable(out_always)
    );

    // With both selects HIGH, output follows b on b changes (a stable).
    check_out_follows_b_when_selected: assert property (
        @(posedge a or negedge a or posedge b or negedge b or posedge sel_b1 or negedge sel_b1 or posedge sel_b2 or negedge sel_b2 or posedge out_always or negedge out_always)
            ((sel_b1 && sel_b2) && $stable(a) && $changed(b)) |-> $changed(out_always)
    );

    // With selects not both HIGH, output follows a on a changes (b stable).
    check_out_follows_a_when_not_selected: assert property (
        @(posedge a or negedge a or posedge b or negedge b or posedge sel_b1 or negedge sel_b1 or posedge sel_b2 or negedge sel_b2 or posedge out_always or negedge out_always)
            ((!sel_b1 || !sel_b2) && $stable(b) && $changed(a)) |-> $changed(out_always)
    );

    // Output equals either a or b at all times.
    check_output_is_a_or_b: assert property (
        @(posedge a or negedge a or posedge b or negedge b or posedge sel_b1 or negedge sel_b1 or posedge sel_b2 or negedge sel_b2 or posedge out_always or negedge out_always)
            (out_always == a) || (out_always == b)
    );

    // Any output change must be caused by a, b, or select changes.
    check_output_change_has_cause: assert property (
        @(posedge a or negedge a or posedge b or negedge b or posedge sel_b1 or negedge sel_b1 or posedge sel_b2 or negedge sel_b2 or posedge out_always or negedge out_always)
            $changed(out_always) |-> ($changed(a) || $changed(b) || $changed(sel_b1) || $changed(sel_b2))
    );
endmodule

