module subtract_8bit(
    input [7:0] A,
    input [7:0] B,
    output reg [7:0] difference
);

integer inside_sub_a = 1;

always @(*) begin
    difference = A - B;
end

endmodule

sva:
module subtract_8bit_sva (
    input logic clk,
    input logic [7:0] A,
    input logic [7:0] B,
    input logic [7:0] difference
);
    // difference implements 8-bit subtraction A - B
    check_difference_function: assert property (
        @(posedge clk) difference == (A - B)
    );

    // If inputs are stable, output remains stable
    check_stability: assert property (
        @(posedge clk) ($stable(A) && $stable(B)) |-> $stable(difference)
    );

    // When A equals B, the difference is zero
    check_zero_when_equal: assert property (
        @(posedge clk) (A == B) |-> (difference == 8'h00)
    );

    // When B is zero, the difference equals A
    check_b_zero_passthrough: assert property (
        @(posedge clk) (B == 8'h00) |-> (difference == A)
    );

    // When A is zero, the difference equals two's complement of B
    check_a_zero_twos_complement: assert property (
        @(posedge clk) (A == 8'h00) |-> (difference == (~B + 8'h01))
    );

    // Subtracting 8'hFF equals adding 1 (mod 256)
    check_sub_ff_is_inc: assert property (
        @(posedge clk) (B == 8'hFF) |-> (difference == (A + 8'h01))
    );

    // (A - B) + B recovers A (mod 256)
    check_add_back_b_recovers_a: assert property (
        @(posedge clk) (difference + B) == A
    );

    // A - (A - B) recovers B (mod 256)
    check_reverse_sub_recovers_b: assert property (
        @(posedge clk) (A - difference) == B
    );

    // If A increments by 1 and B is stable, difference increments by 1
    check_a_inc_updates_diff: assert property (
        @(posedge clk) ($stable(B) && (A == $past(A) + 8'h01)) |-> (difference == $past(difference) + 8'h01)
    );

    // If B increments by 1 and A is stable, difference decrements by 1
    check_b_inc_updates_diff: assert property (
        @(posedge clk) ($stable(A) && (B == $past(B) + 8'h01)) |-> (difference == $past(difference) - 8'h01)
    );
endmodule

rtl:
module write_axi(
		 input clock_recovery,
		 input clock_50,
		 input reset_n,
		 input [13:0] data_rec,
		 output reg [13:0] data_stand	
		);

	reg [13:0] prev_data_stand;

	always@(posedge clock_50 or negedge reset_n ) begin
		if(!reset_n) begin
			data_stand <= 14'd0;
			prev_data_stand <= 14'd0;
		end
		else begin
			if(clock_recovery) begin
				data_stand <= data_rec;
				prev_data_stand <= data_rec;
			end
			else begin
				data_stand <= prev_data_stand;
			end
		end
	end

endmodule

sva:
module write_axi_sva (
    input logic clock_recovery,
    input logic clock_50,
    input logic reset_n,
    input logic [13:0] data_rec,
    input logic [13:0] data_stand
);
    // During active-low reset, data_stand is driven to zero.
    check_reset_drives_zero: assert property (
        @(posedge clock_50) !reset_n |-> (data_stand == 14'd0)
    );

    // When clock_recovery is HIGH, data_stand loads data_rec in the same cycle.
    check_update_when_cr_high: assert property (
        @(posedge clock_50) disable iff (!reset_n) clock_recovery |-> (data_stand == data_rec)
    );

    // When clock_recovery is LOW, data_stand holds its previous value.
    check_hold_when_cr_low: assert property (
        @(posedge clock_50) disable iff (!reset_n) !clock_recovery |-> (data_stand == $past(data_stand))
    );

    // Any change on data_stand must coincide with clock_recovery HIGH.
    check_change_requires_cr: assert property (
        @(posedge clock_50) disable iff (!reset_n) $changed(data_stand) |-> clock_recovery
    );

    // If a HIGH clock_recovery is followed by LOW, data_stand holds the sampled data_rec from the HIGH cycle.
    check_after_cr_high_then_low_holds_prev_sample: assert property (
        @(posedge clock_50) disable iff (!reset_n) $past(clock_recovery) && !clock_recovery |-> (data_stand == $past(data_rec))
    );

    // After reset release, data_stand stays zero until the first cycle with clock_recovery HIGH.
    check_zero_until_first_cr_after_reset_release: assert property (
        @(posedge clock_50) disable iff (!reset_n) $rose(reset_n) |-> (data_stand == 14'd0) until (clock_recovery)
    );

    // On clock_recovery HIGH, if data_rec differs from previous data_stand, data_stand must change.
    check_update_changes_when_new_diff_from_old: assert property (
        @(posedge clock_50) disable iff (!reset_n) clock_recovery && (data_rec != $past(data_stand)) |-> $changed(data_stand)
    );

    // On clock_recovery HIGH, if data_rec equals previous data_stand, data_stand must not change.
    check_update_no_change_when_new_equals_old: assert property (
        @(posedge clock_50) disable iff (!reset_n) clock_recovery && (data_rec == $past(data_stand)) |-> !$changed(data_stand)
    );
endmodule

rtl:
module pwm_controller(
    input clk,
    input [12:0] slow_rate,
    output speaker_out
);

reg [12:0] counter;
reg speaker;
reg [12:0] slow_rate_old;

initial begin
    counter = 0;
    slow_rate_old = 0;
    speaker = 1'b0;
end

always @(posedge clk) begin
    if(slow_rate_old != slow_rate) begin
        counter <= 0;
        speaker <= 1'b0;
        slow_rate_old <= slow_rate;
    end
    else if (slow_rate != 0) begin
        if(counter == slow_rate) begin
            speaker <= ~speaker;
            counter <= 0;
        end
        else begin
            counter <= counter + 1;
        end
    end
    else begin
        speaker <= 1'b0;
        counter <= 0;
    end
end

assign speaker_out = speaker;

endmodule

sva:
module pwm_controller_sva (
    input logic clk,
    input logic [12:0] slow_rate,
    input logic speaker_out,

    // Internal signals from RTL (allowed since they exist in the RTL)
    input logic [12:0] counter,
    input logic speaker,
    input logic [12:0] slow_rate_old
);

    ///// Structural wiring /////
    // speaker_out must always equal internal speaker register.
    check_speaker_out_matches_speaker: assert property (
        @(posedge clk) speaker_out == speaker
    );

    ///// Rate change behavior /////
    // On slow_rate change, next cycle counter=0, speaker=0, and slow_rate_old captures prior slow_rate.
    check_rate_change_resets_and_captures: assert property (
        @(posedge clk) (slow_rate_old != slow_rate) |=> (counter == 13'd0) && (speaker == 1'b0) && (slow_rate_old == $past(slow_rate))
    );

    ///// Zero-rate behavior /////
    // If slow_rate==0, next cycle counter=0 and speaker=0.
    check_zero_rate_forces_idle: assert property (
        @(posedge clk) (slow_rate == 13'd0) |=> (counter == 13'd0) && (speaker == 1'b0)
    );

    ///// Counting behavior when active and rate stable /////
    // When slow_rate is stable, nonzero, and counter<slow_rate, next cycle counter increments by 1 and speaker holds.
    check_increment_and_hold_speaker_while_counting: assert property (
        @(posedge clk) (slow_rate_old == slow_rate) && (slow_rate != 13'd0) && (counter != slow_rate) |=> 
            (counter == $past(counter) + 13'd1) && (speaker == $past(speaker))
    );

    // When slow_rate is stable, nonzero, and counter==slow_rate, next cycle counter resets to 0 and speaker toggles.
    check_toggle_and_reset_on_match: assert property (
        @(posedge clk) (slow_rate_old == slow_rate) && (slow_rate != 13'd0) && (counter == slow_rate) |=> 
            (counter == 13'd0) && (speaker == ~$past(speaker))
    );

    ///// Bookkeeping for slow_rate_old /////
    // If slow_rate is unchanged, slow_rate_old must remain unchanged next cycle.
    check_slow_rate_old_stable_without_change: assert property (
        @(posedge clk) (slow_rate_old == slow_rate) |=> (slow_rate_old == $past(slow_rate_old))
    );

    ///// Safety bounds /////
    // When slow_rate is stable, counter must be within [0, slow_rate].
    check_counter_bounded_when_rate_stable: assert property (
        @(posedge clk) (slow_rate_old == slow_rate) |-> (counter <= slow_rate)
    );

    ///// Idle invariants /////
    // If slow_rate remains 0 (stable), counter and speaker stay at 0 (same-cycle invariant after settling).
    check_idle_invariant_while_zero_and_stable: assert property (
        @(posedge clk) (slow_rate_old == slow_rate) && (slow_rate == 13'd0) |-> (counter == 13'd0) && (speaker == 1'b0)
    );

endmodule

rtl:
module twos_complement (
    input [3:0] in,
    output [3:0] out
);

assign out = ~in + 1'b1;

endmodule

sva:
module twos_complement_sva (
    input logic clk,
    input logic [3:0] in,
    input logic [3:0] out
);
    // No clock or reset in RTL; purely combinational; function: out = ~in + 1'b1 (4-bit two's complement).

    // out equals bitwise-not(in) plus 1 each cycle.
    check_twos_function: assert property (
        @(posedge clk) out == (~in + 1'b1)
    );

    // Two's complement is an involution: ~out + 1 equals in.
    check_involution: assert property (
        @(posedge clk) (~out + 1'b1) == in
    );

    // Sum of in and out is zero modulo 16.
    check_sum_zero_mod16: assert property (
        @(posedge clk) (in + out) == 4'h0
    );

    // Zero maps to zero.
    check_zero_maps_to_zero: assert property (
        @(posedge clk) (in == 4'h0) |-> (out == 4'h0)
    );

    // Zero output implies zero input (bijectivity at zero).
    check_zero_out_implies_zero_in: assert property (
        @(posedge clk) (out == 4'h0) |-> (in == 4'h0)
    );

    // 8 is a fixed point in 4-bit two's complement.
    check_eight_fixed_point: assert property (
        @(posedge clk) (in == 4'h8) |-> (out == 4'h8)
    );

    // LSB is preserved by two's complement.
    check_lsb_preserved: assert property (
        @(posedge clk) out[0] == in[0]
    );

    // If in equals out, it must be 0 or 8.
    check_fixed_points_only_0_or_8: assert property (
        @(posedge clk) (in == out) |-> ((in == 4'h0) || (in == 4'h8))
    );

    // Corner case: -1 (0xF) maps to +1 (0x1).
    check_F_to_1: assert property (
        @(posedge clk) (in == 4'hF) |-> (out == 4'h1)
    );

    // Corner case: +1 (0x1) maps to -1 (0xF).
    check_1_to_F: assert property (
        @(posedge clk) (in == 4'h1) |-> (out == 4'hF)
    );
endmodule

module sky130_fd_sc_hs__nor4b_sva (
    input logic A,
    input logic B,
    input logic C,
    input logic D_N,
    input logic Y,
    input logic VPWR,
    input logic VGND
);

    // Y implements ~(A|B|C|D_N) whenever any input or Y changes.
    check_function_equivalence_on_change: assert property (
        @(posedge A or negedge A or
          posedge B or negedge B or
          posedge C or negedge C or
          posedge D_N or negedge D_N or
          posedge Y or negedge Y)
        (Y == ~(A | B | C | D_N))
    );

    // A rising forces Y LOW.
    check_A_rise_forces_Y_low: assert property (
        @(posedge A) (Y == 1'b0)
    );

    // B rising forces Y LOW.
    check_B_rise_forces_Y_low: assert property (
        @(posedge B) (Y == 1'b0)
    );

    // C rising forces Y LOW.
    check_C_rise_forces_Y_low: assert property (
        @(posedge C) (Y == 1'b0)
    );

    // D_N rising forces Y LOW.
    check_DN_rise_forces_Y_low: assert property (
        @(posedge D_N) (Y == 1'b0)
    );

    // Y can only rise when all inputs are LOW.
    check_Y_rise_requires_all_inputs_low: assert property (
        @(posedge Y) (A == 1'b0) && (B == 1'b0) && (C == 1'b0) && (D_N == 1'b0)
    );

    // Y can only fall when any input is HIGH.
    check_Y_fall_requires_some_input_high: assert property (
        @(negedge Y) (A == 1'b1) || (B == 1'b1) || (C == 1'b1) || (D_N == 1'b1)
    );

    // If A is the last input going LOW (others LOW), Y must be HIGH.
    check_last_low_A_sets_Y_high: assert property (
        @(negedge A) ((B == 1'b0) && (C == 1'b0) && (D_N == 1'b0)) |-> (Y == 1'b1)
    );

    // If B is the last input going LOW (others LOW), Y must be HIGH.
    check_last_low_B_sets_Y_high: assert property (
        @(negedge B) ((A == 1'b0) && (C == 1'b0) && (D_N == 1'b0)) |-> (Y == 1'b1)
    );

    // If C is the last input going LOW (others LOW), Y must be HIGH.
    check_last_low_C_sets_Y_high: assert property (
        @(negedge C) ((A == 1'b0) && (B == 1'b0) && (D_N == 1'b0)) |-> (Y == 1'b1)
    );

    // If D_N is the last input going LOW (others LOW), Y must be HIGH.
    check_last_low_DN_sets_Y_high: assert property (
        @(negedge D_N) ((A == 1'b0) && (B == 1'b0) && (C == 1'b0)) |-> (Y == 1'b1)
    );

endmodule

rtl:
module my_module (
    CLK,
    D,
    SCD,
    SCE,
    SET_B,
    EN,
    Q
);

    input CLK;
    input D;
    input SCD;
    input SCE;
    input SET_B;
    input EN;
    output Q;

    reg Q_reg;
    always @(posedge CLK) begin
        if (EN == 1'b0) begin
            Q_reg <= 1'b0;
        end else if (SCD == 1'b1) begin
            Q_reg <= 1'b0;
        end else if (SET_B == 1'b1) begin
            Q_reg <= 1'b1;
        end else if (SCE == 1'b1) begin
            Q_reg <= D;
        end
    end

    assign Q = Q_reg;

endmodule

sva:
module my_module_sva (
    input logic CLK,
    input logic D,
    input logic SCD,
    input logic SCE,
    input logic SET_B,
    input logic EN,
    input logic Q
);
    // Exact next-state mapping for Q from previous-cycle controls and D.
    check_next_state_map: assert property (
        @(posedge CLK) $past(1'b1) |-> 
            Q == (
                ($past(EN)  == 1'b0) ? 1'b0 :
                ($past(SCD) == 1'b1) ? 1'b0 :
                ($past(SET_B)== 1'b1) ? 1'b1 :
                ($past(SCE) == 1'b1) ? $past(D) :
                $past(Q)
            )
    );

    // EN low synchronously clears Q to 0.
    check_clear_on_en_low: assert property (
        @(posedge CLK) $past(1'b1) && ($past(EN) == 1'b0) |-> (Q == 1'b0)
    );

    // With EN high, SCD high synchronously clears Q to 0.
    check_clear_on_scd: assert property (
        @(posedge CLK) $past(1'b1) && ($past(EN) == 1'b1) && ($past(SCD) == 1'b1) |-> (Q == 1'b0)
    );

    // With EN high and SCD low, SET_B high synchronously sets Q to 1.
    check_set_on_set_b: assert property (
        @(posedge CLK) $past(1'b1) && ($past(EN) == 1'b1) && ($past(SCD) == 1'b0) && ($past(SET_B) == 1'b1) |-> (Q == 1'b1)
    );

    // With higher-priority controls inactive, SCE high loads D into Q.
    check_load_on_sce: assert property (
        @(posedge CLK) $past(1'b1) && ($past(EN) == 1'b1) && ($past(SCD) == 1'b0) && ($past(SET_B) == 1'b0) && ($past(SCE) == 1'b1) |-> (Q == $past(D))
    );

    // When no control is active, Q holds its previous value.
    check_hold_when_no_ctrl: assert property (
        @(posedge CLK) $past(1'b1) && ($past(EN) == 1'b1) && ($past(SCD) == 1'b0) && ($past(SET_B) == 1'b0) && ($past(SCE) == 1'b0) |-> (Q == $past(Q))
    );

    // Q changes only if at least one control was active in the previous cycle.
    check_q_changes_only_with_ctrl: assert property (
        @(posedge CLK) $past(1'b1) && (Q != $past(Q)) |-> (($past(EN) == 1'b0) || ($past(SCD) == 1'b1) || ($past(SET_B) == 1'b1) || ($past(SCE) == 1'b1))
    );

    // A rising edge on Q comes only from SET_B or load of D==1 (with higher-priority clears inactive).
    check_q_rise_causes: assert property (
        @(posedge CLK) $past(1'b1) && $rose(Q) |-> 
            ( ($past(EN) == 1'b1) && ($past(SCD) == 1'b0) &&
              ( ($past(SET_B) == 1'b1) ||
                (($past(SET_B) == 1'b0) && ($past(SCE) == 1'b1) && ($past(D) == 1'b1)) ) )
    );

    // A falling edge on Q comes only from clears or load of D==0 (respecting priority).
    check_q_fall_causes: assert property (
        @(posedge CLK) $past(1'b1) && $fell(Q) |-> 
            ( ($past(EN) == 1'b0) ||
              (($past(EN) == 1'b1) && ($past(SCD) == 1'b1)) ||
              (($past(EN) == 1'b1) && ($past(SCD) == 1'b0) && ($past(SET_B) == 1'b0) && ($past(SCE) == 1'b1) && ($past(D) == 1'b0)) )
    );

    // SET_B has priority over SCE when both are high (with clears inactive).
    check_set_b_overrides_sce: assert property (
        @(posedge CLK) $past(1'b1) && ($past(EN) == 1'b1) && ($past(SCD) == 1'b0) && ($past(SET_B) == 1'b1) && ($past(SCE) == 1'b1) |-> (Q == 1'b1)
    );
endmodule

module mux_2to1_enable_sva (
    input logic data_in_0,
    input logic data_in_1,
    input logic enable,
    input logic data_out
);
    // Output equals data_in_0 when enable is 0.
    check_select0_function: assert property (
        @(posedge enable or posedge data_in_0 or posedge data_in_1 or posedge data_out)
        (enable == 1'b0) |-> (data_out == data_in_0)
    );

    // Output equals data_in_1 when enable is 1.
    check_select1_function: assert property (
        @(posedge enable or posedge data_in_0 or posedge data_in_1 or posedge data_out)
        (enable == 1'b1) |-> (data_out == data_in_1)
    );

    // On enable rising edge, output selects data_in_1.
    check_out_on_enable_rise: assert property (
        @(posedge enable) data_out == data_in_1
    );

    // When enable=0, changes on data_in_1 alone do not change output.
    check_unselected_in1_no_effect: assert property (
        @(posedge data_in_1)
        (enable == 1'b0 && !$changed(enable) && $stable(data_in_0)) |-> $stable(data_out)
    );

    // When enable=1, changes on data_in_0 alone do not change output.
    check_unselected_in0_no_effect: assert property (
        @(posedge data_in_0)
        (enable == 1'b1 && !$changed(enable) && $stable(data_in_1)) |-> $stable(data_out)
    );

    // If both inputs are equal, output must match that value.
    check_equal_inputs_pass_through: assert property (
        @(posedge enable or posedge data_in_0 or posedge data_in_1 or posedge data_out)
        (data_in_0 == data_in_1) |-> (data_out == data_in_0)
    );
endmodule

