module and_gate (
    input a,
    input b,
    output out
);

assign out = a & b;

endmodule

sva:
module and_gate_sva (
    input logic a,
    input logic b,
    input logic out
);
    // Combinational AND gate; no clock/reset present; sample on $global_clock.

    // out must equal a & b every cycle.
    check_out_is_and: assert property (
        @(posedge $global_clock) out == (a & b)
    );

    // If out is HIGH, both inputs must be HIGH.
    check_out_high_requires_inputs_high: assert property (
        @(posedge $global_clock) out |-> (a && b)
    );

    // If a is LOW, out must be LOW.
    check_a_low_forces_out_low: assert property (
        @(posedge $global_clock) !a |-> !out
    );

    // If b is LOW, out must be LOW.
    check_b_low_forces_out_low: assert property (
        @(posedge $global_clock) !b |-> !out
    );

    // If both inputs are HIGH, out must be HIGH.
    check_inputs_high_force_out_high: assert property (
        @(posedge $global_clock) (a && b) |-> out
    );
endmodule

rtl:
module binary_to_gray(
  input [3:0] A,
  output [3:0] G
);

  assign G[0] = A[0];
  assign G[1] = A[0] ^ A[1];
  assign G[2] = A[1] ^ A[2];
  assign G[3] = A[2] ^ A[3];

endmodule

sva:
module binary_to_gray_sva (
    input  logic        clk,
    input  logic [3:0]  A,
    input  logic [3:0]  G
);
    ///// Bitwise mapping checks /////
    // G[0] must equal A[0].
    check_g0_map: assert property (
        @(posedge clk) G[0] == A[0]
    );
    // G[1] must equal A[0] ^ A[1].
    check_g1_map: assert property (
        @(posedge clk) G[1] == (A[0] ^ A[1])
    );
    // G[2] must equal A[1] ^ A[2].
    check_g2_map: assert property (
        @(posedge clk) G[2] == (A[1] ^ A[2])
    );
    // G[3] must equal A[2] ^ A[3].
    check_g3_map: assert property (
        @(posedge clk) G[3] == (A[2] ^ A[3])
    );
    // G must equal {A2^A3, A1^A2, A0^A1, A0}.
    check_vector_map: assert property (
        @(posedge clk) G == { (A[2]^A[3]), (A[1]^A[2]), (A[0]^A[1]), A[0] }
    );

    ///// Temporal consistency checks /////
    // If A is stable across a cycle, G must be stable.
    check_stability: assert property (
        @(posedge clk) $stable(A) |-> $stable(G)
    );

    ///// Input toggle effect checks /////
    // If only A[0] toggles, G[0] and G[1] toggle; G[2:3] stay stable.
    check_toggle_from_a0: assert property (
        @(posedge clk) ($changed(A[0]) && $stable(A[3:1]))
        |-> ($changed(G[0]) && $changed(G[1]) && $stable(G[3:2]))
    );
    // If only A[1] toggles, G[1] and G[2] toggle; G[0] and G[3] stay stable.
    check_toggle_from_a1: assert property (
        @(posedge clk) ($changed(A[1]) && $stable({A[3:2],A[0]}))
        |-> ($changed(G[1]) && $changed(G[2]) && $stable({G[3],G[0]}))
    );
    // If only A[2] toggles, G[2] and G[3] toggle; G[0] and G[1] stay stable.
    check_toggle_from_a2: assert property (
        @(posedge clk) ($changed(A[2]) && $stable({A[3],A[1:0]}))
        |-> ($changed(G[2]) && $changed(G[3]) && $stable(G[1:0]))
    );
    // If only A[3] toggles, only G[3] toggles; G[0:2] stay stable.
    check_toggle_from_a3: assert property (
        @(posedge clk) ($changed(A[3]) && $stable(A[2:0]))
        |-> ($changed(G[3]) && $stable(G[2:0]))
    );
endmodule

rtl:
module Span12Mux_v0(I, S, O);
  input [11:0] I;
  input [3:0] S;
  output reg [11:0] O;

  always @ (S or I) begin
    case (S)
      4'b0000: O <= I;
      4'b0001: O <= I;
      4'b0010: O <= I;
      4'b0011: O <= I;
      4'b0100: O <= I;
      4'b0101: O <= I;
      4'b0110: O <= I;
      4'b0111: O <= I;
      4'b1000: O <= I;
      4'b1001: O <= I;
      4'b1010: O <= I;
      4'b1011: O <= I;
      default: O <= 0;
    endcase
  end
endmodule

sva:
module Span12Mux_v0_sva (
    input logic [11:0] I,
    input logic [3:0]  S,
    input logic [11:0] O
);
    ///// Functional mapping /////
    // For S in 0..11 (S[3:2] != 2'b11), output must pass through input.
    check_passthrough_when_sel_not_11: assert property (
        @(posedge S[0] or posedge S[1] or posedge S[2] or posedge S[3] or
          posedge I[0] or posedge I[1] or posedge I[2] or posedge I[3] or
          posedge I[4] or posedge I[5] or posedge I[6] or posedge I[7] or
          posedge I[8] or posedge I[9] or posedge I[10] or posedge I[11])
        disable iff (1'b0)
        (S[3:2] != 2'b11) |-> (O == I)
    );

    // For S in 12..15 (S[3:2] == 2'b11), output must be all zeros.
    check_zero_when_sel_11xx: assert property (
        @(posedge S[0] or posedge S[1] or posedge S[2] or posedge S[3] or
          posedge I[0] or posedge I[1] or posedge I[2] or posedge I[3] or
          posedge I[4] or posedge I[5] or posedge I[6] or posedge I[7] or
          posedge I[8] or posedge I[9] or posedge I[10] or posedge I[11])
        disable iff (1'b0)
        (S[3:2] == 2'b11) |-> (O == 12'b0)
    );

    ///// Stability expectations for combinational logic /////
    // If S and I are stable, O must remain stable.
    check_stable_on_stable_inputs: assert property (
        @(posedge S[0] or posedge S[1] or posedge S[2] or posedge S[3] or
          posedge I[0] or posedge I[1] or posedge I[2] or posedge I[3] or
          posedge I[4] or posedge I[5] or posedge I[6] or posedge I[7] or
          posedge I[8] or posedge I[9] or posedge I[10] or posedge I[11])
        disable iff (1'b0)
        ($stable(S) && $stable(I)) |-> $stable(O)
    );

    // With selection in 0..11 and S stable, any change on I must be reflected on O.
    check_output_tracks_input_when_selected: assert property (
        @(posedge S[0] or posedge S[1] or posedge S[2] or posedge S[3] or
          posedge I[0] or posedge I[1] or posedge I[2] or posedge I[3] or
          posedge I[4] or posedge I[5] or posedge I[6] or posedge I[7] or
          posedge I[8] or posedge I[9] or posedge I[10] or posedge I[11])
        disable iff (1'b0)
        ((S[3:2] != 2'b11) && $stable(S) && !$stable(I)) |-> (O == I)
    );

    // With selection in 12..15 and S stable, O must remain zero regardless of I changes.
    check_output_ignores_input_when_11xx: assert property (
        @(posedge S[0] or posedge S[1] or posedge S[2] or posedge S[3] or
          posedge I[0] or posedge I[1] or posedge I[2] or posedge I[3] or
          posedge I[4] or posedge I[5] or posedge I[6] or posedge I[7] or
          posedge I[8] or posedge I[9] or posedge I[10] or posedge I[11])
        disable iff (1'b0)
        ((S[3:2] == 2'b11) && $stable(S)) |-> (O == 12'b0)
    );
endmodule

module and_gate_sva (
  input logic A,
  input logic B,
  input logic CLK,
  input logic RST,
  input logic Y
);
  // While reset is asserted (active-low), Y must be 0 at each clock edge.
  reset_drives_Y_low: assert property (
    @(posedge CLK) !RST |-> (Y == 1'b0)
  );

  // Out of reset, Y equals the previous cycle's A & B.
  y_equals_past_and: assert property (
    @(posedge CLK) disable iff (!RST) $past(RST) |-> (Y == $past(A & B))
  );

  // If previous cycle had A=1 and B=1, then Y must be 1 this cycle.
  y1_when_prev_inputs_11: assert property (
    @(posedge CLK) disable iff (!RST) $past(RST) && $past(A) && $past(B) |-> (Y == 1'b1)
  );

  // If previous cycle had A=0 (regardless of B), then Y must be 0 this cycle.
  y0_when_prev_A0: assert property (
    @(posedge CLK) disable iff (!RST) $past(RST) && ($past(A) == 1'b0) |-> (Y == 1'b0)
  );

  // If previous cycle had B=0 (regardless of A), then Y must be 0 this cycle.
  y0_when_prev_B0: assert property (
    @(posedge CLK) disable iff (!RST) $past(RST) && ($past(B) == 1'b0) |-> (Y == 1'b0)
  );

  // A rising Y implies previous cycle's (A & B) was 1.
  y_rise_implies_prev_and1: assert property (
    @(posedge CLK) disable iff (!RST) $past(RST) && $rose(Y) |-> ($past(A & B) == 1'b1)
  );

  // A falling Y implies previous cycle's (A & B) was 0.
  y_fall_implies_prev_and0: assert property (
    @(posedge CLK) disable iff (!RST) $past(RST) && $fell(Y) |-> ($past(A & B) == 1'b0)
  );

  // If (A & B) was stable over the last two cycles, Y must equal its previous value.
  y_stable_when_inputs_stable: assert property (
    @(posedge CLK) disable iff (!RST) $past(RST,2) && ($past(A & B,2) == $past(A & B,1)) |-> (Y == $past(Y))
  );
endmodule

rtl:
module sync_reset_DFF (
	input D, GSR, CLK,
	output reg Q
);

	always @(posedge CLK) begin
		if (GSR) begin
			Q <= 1'b0;
		end else begin
			Q <= D;
		end
	end

endmodule

sva:
module sync_reset_DFF_sva (
    input logic D,
    input logic GSR,   // synchronous active-high reset
    input logic CLK,
    input logic Q
);
    // If reset was asserted on the previous cycle, Q is 0 now.
    check_sync_reset_clears_q: assert property (
        @(posedge CLK) $past(GSR) |-> (Q == 1'b0)
    );

    // When not in reset on the previous cycle, Q reflects D from the previous cycle.
    check_data_captured_when_no_reset: assert property (
        @(posedge CLK) disable iff (GSR) $past(!GSR) |-> (Q == $past(D))
    );

    // On a cycle where reset just deasserted, Q remains 0 (held from prior reset capture).
    check_q_zero_on_reset_deassert_cycle: assert property (
        @(posedge CLK) $fell(GSR) |-> (Q == 1'b0)
    );

    // While reset is held across consecutive cycles, Q stays 0.
    check_q_held_low_while_reset_high: assert property (
        @(posedge CLK) ($past(GSR) && GSR) |-> (Q == 1'b0)
    );

    // If not in reset for two consecutive cycles, Q's transition matches D's prior transition.
    check_q_transition_matches_d_transition_no_reset: assert property (
        @(posedge CLK) disable iff (GSR) (!$past(GSR) && !$past($past(GSR))) |-> ((Q ^ $past(Q)) == ($past(D) ^ $past($past(D))))
    );

    // If not in reset for two consecutive cycles and D was stable, Q is stable.
    check_q_holds_when_d_stable_no_reset: assert property (
        @(posedge CLK) disable iff (GSR) (!$past(GSR) && !$past($past(GSR)) && ($past(D) == $past($past(D)))) |-> (Q == $past(Q))
    );
endmodule

rtl:
module shifter (
    input [3:0] data_in,
    input rotate,
    output [3:0] data_out
);
    wire [3:0] shifted_data;

    assign shifted_data[0] = rotate ? data_in[3] : data_in[0];
    assign shifted_data[1] = rotate ? data_in[0] : data_in[1];
    assign shifted_data[2] = rotate ? data_in[1] : data_in[2];
    assign shifted_data[3] = rotate ? data_in[2] : data_in[3];

    assign data_out = shifted_data;
endmodule
module mux_4to1 (
    input [3:0] data0,
    input [3:0] data1,
    input [3:0] data2,
    input [3:0] data3,
    input [1:0] select,
    output [3:0] out
);
    reg [3:0] mux_out;

    always @* begin
        case (select)
            2'b00: mux_out = data0;
            2'b01: mux_out = data1;
            2'b10: mux_out = data2;
            2'b11: mux_out = data3;
        endcase
    end

    assign out = mux_out;
endmodule
module top_module (
    input [3:0] data1,
    input rotate,
    input [3:0] data2,
    input [1:0] select,
    output [3:0] out
);
    wire [3:0] shifted_data;
    wire [3:0] mux_data;

    shifter shifter_inst (
        .data_in(data1),
        .rotate(rotate),
        .data_out(shifted_data)
    );

    mux_4to1 mux_inst (
        .data0(shifted_data),
        .data1(data2),
        .data2(4'b0),
        .data3(4'b1),
        .select(select),
        .out(mux_data)
    );

    assign out = mux_data;
endmodule

sva:
module top_module_sva (
    input logic [3:0] data1,
    input logic rotate,
    input logic [3:0] data2,
    input logic [1:0] select,
    input logic [3:0] out
);
    // When select==01, mux forwards data2 to out.
    check_mux_sel01_forwards_data2: assert property (
        @(posedge select[0]) (select == 2'b01) |-> (out == data2)
    );

    // When select==10, mux drives all zeros.
    check_mux_sel10_drives_zero: assert property (
        @(posedge select[0]) (select == 2'b10) |-> (out == 4'b0000)
    );

    // When select==11, mux drives 0001.
    check_mux_sel11_drives_one: assert property (
        @(posedge select[0]) (select == 2'b11) |-> (out == 4'b0001)
    );

    // When select==00 and no rotate, pass data1 through.
    check_sel00_no_rotate_passthrough: assert property (
        @(posedge select[0]) (select == 2'b00 && !rotate) |-> (out == data1)
    );

    // When select==00 and rotate, bit0 comes from data1[3].
    check_sel00_rotate_bit0: assert property (
        @(posedge select[0]) (select == 2'b00 && rotate) |-> (out[0] == data1[3])
    );

    // When select==00 and rotate, bit1 comes from data1[0].
    check_sel00_rotate_bit1: assert property (
        @(posedge select[0]) (select == 2'b00 && rotate) |-> (out[1] == data1[0])
    );

    // When select==00 and rotate, bit2 comes from data1[1].
    check_sel00_rotate_bit2: assert property (
        @(posedge select[0]) (select == 2'b00 && rotate) |-> (out[2] == data1[1])
    );

    // When select==00 and rotate, bit3 comes from data1[2].
    check_sel00_rotate_bit3: assert property (
        @(posedge select[0]) (select == 2'b00 && rotate) |-> (out[3] == data1[2])
    );
endmodule

rtl:
module logic_gate (
    input A1,
    input A2,
    input B1,
    input B2,
    input C1,
    output reg X
);

    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;

    always @(*) begin
        X = (A1 & A2 & (B1 | B2) & ~C1);
    end

endmodule

sva:
module logic_gate_sva (
    input logic CLK,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic B2,
    input logic C1,
    input logic X
);
    ///// Combinational function checks /////
    // X must be 1 iff A1 & A2 & (B1 | B2) & ~C1 is 1.
    check_function_implies_x: assert property (
        @(posedge CLK) (A1 & A2 & (B1 | B2) & ~C1) |-> (X == 1'b1)
    );
    // If X is 1, all enabling conditions must be true.
    check_x_implies_function: assert property (
        @(posedge CLK) (X == 1'b1) |-> (A1 & A2 & (B1 | B2) & ~C1)
    );

    ///// Blocking conditions /////
    // If C1 is HIGH, X must be 0.
    check_c1_blocks_x: assert property (
        @(posedge CLK) C1 |-> (X == 1'b0)
    );
    // If A1 is LOW, X must be 0.
    check_a1_low_blocks_x: assert property (
        @(posedge CLK) !A1 |-> (X == 1'b0)
    );
    // If A2 is LOW, X must be 0.
    check_a2_low_blocks_x: assert property (
        @(posedge CLK) !A2 |-> (X == 1'b0)
    );
    // If both B1 and B2 are LOW, X must be 0.
    check_b_both_low_blocks_x: assert property (
        @(posedge CLK) (!B1 & !B2) |-> (X == 1'b0)
    );

    ///// Necessary conditions when X is HIGH /////
    // If X is HIGH, at least one of B1 or B2 must be HIGH.
    check_x_requires_b: assert property (
        @(posedge CLK) X |-> (B1 | B2)
    );
    // If X is HIGH, A1 and A2 must be HIGH and C1 must be LOW.
    check_x_requires_a1_a2_c1: assert property (
        @(posedge CLK) X |-> (A1 & A2 & ~C1)
    );
endmodule

rtl:
module my_module (
    X ,
    A1,
    A2,
    A3,
    B1
);

    output X ;
    input  A1;
    input  A2;
    input  A3;
    input  B1;

    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    wire and1;
    wire and2;
    wire or1;

    assign and1 = A1 & A2;
    assign and2 = A2 & A3;
    assign or1 = and1 | and2;

    assign X = (B1) ? 1'b0 : or1;

endmodule

sva:
module my_module_sva (
    input logic X,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic B1
);
    // No clock/reset in RTL; combinational; sample on input posedges.

    // Canonical Boolean equality for X.
    check_canonical_equation: assert property (
        @(posedge A1 or posedge A2 or posedge A3 or posedge B1)
        (X == ((!B1) & (A2 & (A1 | A3))))
    );

    // When B1 is HIGH, X must be 0.
    check_b1_forces_zero: assert property (
        @(posedge A1 or posedge A2 or posedge A3 or posedge B1)
        B1 |-> (X == 1'b0)
    );

    // When B1 is LOW, X equals (A1&A2)|(A2&A3).
    check_b1_low_function: assert property (
        @(posedge A1 or posedge A2 or posedge A3 or posedge B1)
        (!B1) |-> (X == ((A1 & A2) | (A2 & A3)))
    );

    // With B1 LOW and A2 LOW, X must be 0.
    check_a2_zero_forces_zero: assert property (
        @(posedge A1 or posedge A2 or posedge A3 or posedge B1)
        (!B1 && !A2) |-> (X == 1'b0)
    );

    // With B1 LOW and A2&A1 HIGH, X must be 1.
    check_a1_a2_set_x: assert property (
        @(posedge A1 or posedge A2 or posedge A3 or posedge B1)
        (!B1 && A1 && A2) |-> (X == 1'b1)
    );

    // With B1 LOW and A2&A3 HIGH, X must be 1.
    check_a2_a3_set_x: assert property (
        @(posedge A1 or posedge A2 or posedge A3 or posedge B1)
        (!B1 && A2 && A3) |-> (X == 1'b1)
    );

    // With B1 LOW, A2 HIGH, and A1/A3 both LOW, X must be 0.
    check_no_neighbors_zero: assert property (
        @(posedge A1 or posedge A2 or posedge A3 or posedge B1)
        (!B1 && A2 && !A1 && !A3) |-> (X == 1'b0)
    );

    // If X is 1, then B1 must be LOW and A2=1 and (A1 or A3)=1.
    check_x_one_implies_inputs: assert property (
        @(posedge A1 or posedge A2 or posedge A3 or posedge B1)
        X |-> (!B1 && A2 && (A1 || A3))
    );

    // With B1 LOW and A2 LOW even if A1 or A3 is HIGH, X must be 0.
    check_a2_gating_effect: assert property (
        @(posedge A1 or posedge A2 or posedge A3 or posedge B1)
        (!B1 && !A2 && (A1 || A3)) |-> (X == 1'b0)
    );

    // With B1 LOW and A2 HIGH and exactly one of A1/A3 HIGH, X must be 1.
    check_single_neighbor_sets_x: assert property (
        @(posedge A1 or posedge A2 or posedge A3 or posedge B1)
        (!B1 && A2 && (A1 ^ A3)) |-> (X == 1'b1)
    );

endmodule

rtl:
module adder_with_carry(
    input [3:0] a,
    input [3:0] b,
    input cin,
    output [3:0] sum,
    output cout
);

wire [3:0] temp_sum; // intermediate sum
wire c1, c2, c3; // carry signals

// full adder for least significant bit
full_adder fa0(.a(a[0]), .b(b[0]), .cin(cin), .sum(temp_sum[0]), .cout(c1));

// full adder for second bit
full_adder fa1(.a(a[1]), .b(b[1]), .cin(c1), .sum(temp_sum[1]), .cout(c2));

// full adder for third bit
full_adder fa2(.a(a[2]), .b(b[2]), .cin(c2), .sum(temp_sum[2]), .cout(c3));

// full adder for most significant bit
full_adder fa3(.a(a[3]), .b(b[3]), .cin(c3), .sum(temp_sum[3]), .cout(cout));

assign sum = temp_sum; // assign intermediate sum to output

endmodule

// full adder module
module full_adder(
    input a,
    input b,
    input cin,
    output sum,
    output cout
);

wire s1, s2, s3; // intermediate signals

// XOR gate for sum
assign s1 = a ^ b;
assign sum = s1 ^ cin;

// AND gate for carry-out
assign s2 = a & b;
assign s3 = cin & s1;
assign cout = s2 | s3;

endmodule

