module mux16to1 (
  input [15:0] data_in,
  input [3:0] select,
  output reg data_out
);

always @(*)
begin
  case (select)
    0: data_out = data_in[0];
    1: data_out = data_in[1];
    2: data_out = data_in[2];
    3: data_out = data_in[3];
    4: data_out = data_in[4];
    5: data_out = data_in[5];
    6: data_out = data_in[6];
    7: data_out = data_in[7];
    8: data_out = data_in[8];
    9: data_out = data_in[9];
    10: data_out = data_in[10];
    11: data_out = data_in[11];
    12: data_out = data_in[12];
    13: data_out = data_in[13];
    14: data_out = data_in[14];
    15: data_out = data_in[15];
    default: data_out = 1'b0;
  endcase
end

endmodule

sva:
module mux16to1_sva (
    input logic clk,          // sampling clock for SVA only
    input logic [15:0] data_in,
    input logic [3:0] select,
    input logic data_out
);

    // For known select values (no X/Z), output equals the selected input bit.
    pass_through_known_select: assert property (
        @(posedge clk) !$isunknown(select) |=> (data_out === data_in[select])
    );

    // If select contains X/Z, default branch drives output LOW.
    default_on_unknown_select: assert property (
        @(posedge clk) $isunknown(select) |=> (data_out === 1'b0)
    );

    // When select==0, output equals data_in[0].
    pass_through_sel0: assert property (
        @(posedge clk) (select == 4'd0) |=> (data_out === data_in[0])
    );

    // When select==1, output equals data_in[1].
    pass_through_sel1: assert property (
        @(posedge clk) (select == 4'd1) |=> (data_out === data_in[1])
    );

    // When select==7, output equals data_in[7].
    pass_through_sel7: assert property (
        @(posedge clk) (select == 4'd7) |=> (data_out === data_in[7])
    );

    // When select==8, output equals data_in[8].
    pass_through_sel8: assert property (
        @(posedge clk) (select == 4'd8) |=> (data_out === data_in[8])
    );

    // When select==15, output equals data_in[15].
    pass_through_sel15: assert property (
        @(posedge clk) (select == 4'd15) |=> (data_out === data_in[15])
    );

    // If all inputs are 0, output must be 0 for any select (known or unknown).
    zero_inputs_drive_zero: assert property (
        @(posedge clk) (data_in == 16'b0) |=> (data_out === 1'b0)
    );

    // If all inputs are 1 and select is known, output is 1.
    ones_inputs_drive_one_when_select_known: assert property (
        @(posedge clk) (!$isunknown(select) && (data_in == 16'hFFFF)) |=> (data_out === 1'b1)
    );

    // With select and the selected input bit stable across cycles, output stays stable.
    stable_output_when_select_and_selected_input_stable: assert property (
        @(posedge clk) (!$isunknown(select) && !$isunknown($past(select)) && (select == $past(select)) && ($past(data_in[select]) === data_in[select])) |=> (data_out === $past(data_out))
    );

endmodule

rtl:
module ones_complement (
    input [3:0] binary,
    input clk,
    output reg [3:0] ones_comp
);

reg [3:0] stage1_out;
reg [3:0] stage2_out;

// Pipeline stage 1
always @(*) begin
    stage1_out = ~binary;
end

// Pipeline stage 2
always @(*) begin
    stage2_out = ~stage1_out;
end

// Output stage
always @(posedge clk) begin
    ones_comp <= stage2_out;
end

endmodule

sva:
module ones_complement_sva (
    input logic clk,
    input logic [3:0] binary,
    input logic [3:0] ones_comp
);
    // Clock: clk (posedge). No reset in RTL.
    // Mixed logic: combinational double inversion feeding a registered output.
    // Behavior: ones_comp captures binary (one-cycle latency).

    // Output captures the previous cycle's input value.
    check_output_captures_prev_input: assert property (
        @(posedge clk) $past(1'b1) |-> (ones_comp == $past(binary))
    );

    // If input is stable over the last cycle, output equals current input.
    check_equal_when_input_stable: assert property (
        @(posedge clk) $past(1'b1) && $stable(binary) |-> (ones_comp == binary)
    );

    // If input changed over the last cycle, output differs from current input.
    check_inequal_when_input_changed: assert property (
        @(posedge clk) $past(1'b1) && !$stable(binary) |-> (ones_comp != binary)
    );

    // Any output change implies a change on the input in the prior cycle.
    check_output_change_implies_prior_input_change: assert property (
        @(posedge clk) $past(1'b1,2) && $changed(ones_comp) |-> $changed($past(binary))
    );

    // If input was constant for two consecutive prior cycles, output does not change.
    check_no_output_change_if_input_constant_two_cycles: assert property (
        @(posedge clk) $past(1'b1,2) && ($past(binary) == $past(binary,2)) |-> !$changed(ones_comp)
    );

    // A change on the input in the prior cycle causes an output change this cycle.
    check_prior_input_change_implies_output_change: assert property (
        @(posedge clk) $past(1'b1,2) && $changed($past(binary)) |-> $changed(ones_comp)
    );
endmodule

rtl:
module bin_to_gray (
  input [3:0] bin,
  output reg [3:0] gray
);

  always @* begin
    gray[3] = bin[3];
    gray[2] = bin[3] ^ bin[2];
    gray[1] = bin[2] ^ bin[1];
    gray[0] = bin[1] ^ bin[0];
  end

endmodule

sva:
module bin_to_gray_sva (
    input logic CLK,
    input logic [3:0] bin,
    input logic [3:0] gray
);
    // Gray vector matches combinational mapping from bin.
    check_gray_vector_mapping: assert property (
        @(posedge CLK) gray == { bin[3], (bin[3] ^ bin[2]), (bin[2] ^ bin[1]), (bin[1] ^ bin[0]) }
    );

    // MSB maps directly.
    check_gray_bit3_mapping: assert property (
        @(posedge CLK) gray[3] == bin[3]
    );

    // Next bit is XOR of bin[3] and bin[2].
    check_gray_bit2_mapping: assert property (
        @(posedge CLK) gray[2] == (bin[3] ^ bin[2])
    );

    // Next bit is XOR of bin[2] and bin[1].
    check_gray_bit1_mapping: assert property (
        @(posedge CLK) gray[1] == (bin[2] ^ bin[1])
    );

    // LSB is XOR of bin[1] and bin[0].
    check_gray_bit0_mapping: assert property (
        @(posedge CLK) gray[0] == (bin[1] ^ bin[0])
    );

    // If inputs are stable, outputs are stable (pure combinational function).
    check_stable_input_implies_stable_output: assert property (
        @(posedge CLK) $stable(bin) |-> $stable(gray)
    );

    // Only bin[3] changes -> gray[3] and gray[2] change; others stable.
    check_only_bin3_change_propagation: assert property (
        @(posedge CLK)
            ($changed(bin[3]) && $stable(bin[2]) && $stable(bin[1]) && $stable(bin[0]))
        |-> ($changed(gray[3]) && $changed(gray[2]) && $stable(gray[1]) && $stable(gray[0]))
    );

    // Only bin[2] changes -> gray[2] and gray[1] change; others stable.
    check_only_bin2_change_propagation: assert property (
        @(posedge CLK)
            ($changed(bin[2]) && $stable(bin[3]) && $stable(bin[1]) && $stable(bin[0]))
        |-> ($stable(gray[3]) && $changed(gray[2]) && $changed(gray[1]) && $stable(gray[0]))
    );

    // Only bin[1] changes -> gray[1] and gray[0] change; others stable.
    check_only_bin1_change_propagation: assert property (
        @(posedge CLK)
            ($changed(bin[1]) && $stable(bin[3]) && $stable(bin[2]) && $stable(bin[0]))
        |-> ($stable(gray[3]) && $stable(gray[2]) && $changed(gray[1]) && $changed(gray[0]))
    );

    // Only bin[0] changes -> only gray[0] changes.
    check_only_bin0_change_propagation: assert property (
        @(posedge CLK)
            ($changed(bin[0]) && $stable(bin[3]) && $stable(bin[2]) && $stable(bin[1]))
        |-> ($stable(gray[3]) && $stable(gray[2]) && $stable(gray[1]) && $changed(gray[0]))
    );
endmodule

rtl:
module binary_counter(
  input clk,
  input rst,
  output reg [3:0] q
);

  always @(posedge clk or negedge rst) begin
    if(!rst) begin
      q <= 4'b0;
    end else begin
      q <= q + 1;
    end
  end

endmodule

sva:
module binary_counter_sva (
    input logic clk,
    input logic rst,
    input logic [3:0] q
);
    // When reset is asserted LOW at a clock edge, q must be 0.
    check_reset_forces_zero: assert property (
        @(posedge clk) !rst |-> (q == 4'h0)
    );

    // On reset deassertion (LOW->HIGH) at a clock edge, q moves from 0 to 1.
    check_q_is_one_on_reset_release: assert property (
        @(posedge clk) $rose(rst) |-> (q == 4'h1)
    );

    // If previous q was 0xF and reset is HIGH at consecutive edges, q is 0 (normal wrap) or 1 (reset glitch then increment).
    check_wrap_or_reset_after_prev_F: assert property (
        @(posedge clk) disable iff (!rst) $past(rst) && ($past(q) == 4'hF) && rst |-> (q == 4'h0) || (q == 4'h1)
    );

    // When out of reset at consecutive edges, q==0 can only come from previous q==0xF.
    check_zero_only_after_prev_F: assert property (
        @(posedge clk) disable iff (!rst) $past(rst) && rst && (q == 4'h0) |-> ($past(q) == 4'hF)
    );

    // When out of reset at consecutive edges, q cannot remain 0xF.
    check_no_F_repeat_without_reset: assert property (
        @(posedge clk) disable iff (!rst) $past(rst) && rst && ($past(q) == 4'hF) |-> (q != 4'hF)
    );
endmodule

rtl:
module t_flip_flop(input t, input clk, output reg q);

  always @(posedge clk) begin
    q <= q ^ t;
  end

endmodule

sva:
module t_flip_flop_sva (
    input logic clk,
    input logic t,
    input logic q
);
    // Analysis: clock=clk (posedge), no reset; sequential TFF with q_next = q ^ t.

    // q updates to previous q XOR previous t each rising edge.
    check_next_state_function: assert property (
        @(posedge clk) disable iff ($initstate) q == ($past(q) ^ $past(t))
    );

    // When previous t is 0, q holds its value.
    check_hold_when_t0: assert property (
        @(posedge clk) disable iff ($initstate) ($past(t) == 1'b0) |-> (q == $past(q))
    );

    // When previous t is 1, q toggles.
    check_toggle_when_t1: assert property (
        @(posedge clk) disable iff ($initstate) ($past(t) == 1'b1) |-> (q != $past(q))
    );

    // Any change in q implies previous t was 1.
    check_change_implies_t1: assert property (
        @(posedge clk) disable iff ($initstate) (q != $past(q)) |-> ($past(t) == 1'b1)
    );
endmodule

