module sky130_fd_sc_ls__a311o (
    X ,
    A1,
    A2,
    A3,
    B1,
    C1
);

    output X ;
    input  A1;
    input  A2;
    input  A3;
    input  B1;
    input  C1;

    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    wire and0_out ;
    wire or0_out_X;

    and and0 (and0_out , A3, A1, A2      );
    or  or0  (or0_out_X, and0_out, C1, B1);
    buf buf0 (X        , or0_out_X       );

endmodule

sva:
module sky130_fd_sc_ls__a311o_sva (
    input logic X,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic B1,
    input logic C1
);
    // No clock/reset in DUT; combinational logic. Sample on any port edge.
    // Event: any edge on ports to evaluate combinational relationships.
    // Core function: X == (A1 & A2 & A3) | B1 | C1
    check_function_equivalence: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge A3 or negedge A3
          or posedge B1 or negedge B1 or posedge C1 or negedge C1 or posedge X or negedge X)
        X == ((A1 && A2 && A3) || B1 || C1)
    );

    // B1 high forces X high in the same cycle.
    check_b1_forces_x: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge A3 or negedge A3
          or posedge B1 or negedge B1 or posedge C1 or negedge C1 or posedge X or negedge X)
        B1 |=> (X == 1'b1)
    );

    // C1 high forces X high in the same cycle.
    check_c1_forces_x: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge A3 or negedge A3
          or posedge B1 or negedge B1 or posedge C1 or negedge C1 or posedge X or negedge X)
        C1 |=> (X == 1'b1)
    );

    // A1&A2&A3 high forces X high in the same cycle.
    check_and_term_forces_x: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge A3 or negedge A3
          or posedge B1 or negedge B1 or posedge C1 or negedge C1 or posedge X or negedge X)
        (A1 && A2 && A3) |=> (X == 1'b1)
    );

    // With B1==0 and C1==0, X equals A1&A2&A3.
    check_bc_zero_passes_and: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge A3 or negedge A3
          or posedge B1 or negedge B1 or posedge C1 or negedge C1 or posedge X or negedge X)
        (B1 == 1'b0 && C1 == 1'b0) |=> (X == (A1 && A2 && A3))
    );

    // With B1==0 and C1==0, any A low makes X low.
    check_bc_zero_any_a_low_makes_x_low: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge A3 or negedge A3
          or posedge B1 or negedge B1 or posedge C1 or negedge C1 or posedge X or negedge X)
        (B1 == 1'b0 && C1 == 1'b0 && (!A1 || !A2 || !A3)) |=> (X == 1'b0)
    );

    // If X is high while B1==0 and C1==0, then all A's must be high.
    check_x_high_bc_zero_requires_all_a_high: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge A3 or negedge A3
          or posedge B1 or negedge B1 or posedge C1 or negedge C1 or posedge X or negedge X)
        (X == 1'b1 && B1 == 1'b0 && C1 == 1'b0) |=> (A1 && A2 && A3)
    );

    // X high implies at least one product/sum term is true.
    check_x_high_implies_some_term_true: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge A3 or negedge A3
          or posedge B1 or negedge B1 or posedge C1 or negedge C1 or posedge X or negedge X)
        (X == 1'b1) |=> (B1 || C1 || (A1 && A2 && A3))
    );

    // X low implies all terms are false.
    check_x_low_implies_all_terms_false: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge A3 or negedge A3
          or posedge B1 or negedge B1 or posedge C1 or negedge C1 or posedge X or negedge X)
        (X == 1'b0) |=> ((B1 == 1'b0) && (C1 == 1'b0) && !(A1 && A2 && A3))
    );

    // All inputs low force X low.
    check_all_inputs_low_force_x_low: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge A3 or negedge A3
          or posedge B1 or negedge B1 or posedge C1 or negedge C1 or posedge X or negedge X)
        (!A1 && !A2 && !A3 && !B1 && !C1) |=> (X == 1'b0)
    );
endmodule

rtl:
module adder_4bit_carry(
  input [3:0] a,
  input [3:0] b,
  input cin,
  output [3:0] sum,
  output cout
);

  wire [3:0] temp_sum;
  wire carry1, carry2, carry3;

  assign {carry1, temp_sum[0]} = a[0] + b[0] + cin;
  assign {carry2, temp_sum[1]} = a[1] + b[1] + carry1;
  assign {carry3, temp_sum[2]} = a[2] + b[2] + carry2;
  assign {cout, temp_sum[3]} = a[3] + b[3] + carry3;

  assign sum = temp_sum;

endmodule

sva:
module adder_4bit_carry_sva (
    input  logic [3:0] a,
    input  logic [3:0] b,
    input  logic       cin,
    input  logic [3:0] sum,
    input  logic       cout,
    input  logic [3:0] temp_sum,
    input  logic       carry1,
    input  logic       carry2,
    input  logic       carry3
);
    // LSB stage: carry1 and temp_sum[0] reflect a[0]+b[0]+cin (2-bit result).
    check_stage0_add: assert property (
        @(posedge a[0] or posedge b[0] or posedge cin or posedge a[1] or posedge b[1] or posedge a[2] or posedge b[2] or posedge a[3] or posedge b[3])
        {carry1, temp_sum[0]} == ({1'b0, a[0]} + {1'b0, b[0]} + cin)
    );

    // Bit1 stage: carry2 and temp_sum[1] reflect a[1]+b[1]+carry1 (2-bit result).
    check_stage1_add: assert property (
        @(posedge a[0] or posedge b[0] or posedge cin or posedge a[1] or posedge b[1] or posedge a[2] or posedge b[2] or posedge a[3] or posedge b[3])
        {carry2, temp_sum[1]} == ({1'b0, a[1]} + {1'b0, b[1]} + carry1)
    );

    // Bit2 stage: carry3 and temp_sum[2] reflect a[2]+b[2]+carry2 (2-bit result).
    check_stage2_add: assert property (
        @(posedge a[0] or posedge b[0] or posedge cin or posedge a[1] or posedge b[1] or posedge a[2] or posedge b[2] or posedge a[3] or posedge b[3])
        {carry3, temp_sum[2]} == ({1'b0, a[2]} + {1'b0, b[2]} + carry2)
    );

    // MSB stage: cout and temp_sum[3] reflect a[3]+b[3]+carry3 (2-bit result).
    check_stage3_add: assert property (
        @(posedge a[0] or posedge b[0] or posedge cin or posedge a[1] or posedge b[1] or posedge a[2] or posedge b[2] or posedge a[3] or posedge b[3])
        {cout, temp_sum[3]} == ({1'b0, a[3]} + {1'b0, b[3]} + carry3)
    );

    // Sum output mirrors temp_sum.
    check_sum_assign: assert property (
        @(posedge a[0] or posedge b[0] or posedge cin or posedge a[1] or posedge b[1] or posedge a[2] or posedge b[2] or posedge a[3] or posedge b[3])
        sum == temp_sum
    );

    // Overall 5-bit result equals a + b + cin.
    check_full_sum: assert property (
        @(posedge a[0] or posedge b[0] or posedge cin or posedge a[1] or posedge b[1] or posedge a[2] or posedge b[2] or posedge a[3] or posedge b[3])
        {cout, sum} == ({1'b0, a} + {1'b0, b} + cin)
    );

    // Carry1 is the majority of a[0], b[0], and cin.
    check_carry1_majority: assert property (
        @(posedge a[0] or posedge b[0] or posedge cin or posedge a[1] or posedge b[1] or posedge a[2] or posedge b[2] or posedge a[3] or posedge b[3])
        carry1 == ((a[0] & b[0]) | (a[0] & cin) | (b[0] & cin))
    );

    // Carry2 is the majority of a[1], b[1], and carry1.
    check_carry2_majority: assert property (
        @(posedge a[0] or posedge b[0] or posedge cin or posedge a[1] or posedge b[1] or posedge a[2] or posedge b[2] or posedge a[3] or posedge b[3])
        carry2 == ((a[1] & b[1]) | (a[1] & carry1) | (b[1] & carry1))
    );

    // Carry3 is the majority of a[2], b[2], and carry2.
    check_carry3_majority: assert property (
        @(posedge a[0] or posedge b[0] or posedge cin or posedge a[1] or posedge b[1] or posedge a[2] or posedge b[2] or posedge a[3] or posedge b[3])
        carry3 == ((a[2] & b[2]) | (a[2] & carry2) | (b[2] & carry2))
    );

    // Cout is the majority of a[3], b[3], and carry3.
    check_cout_majority: assert property (
        @(posedge a[0] or posedge b[0] or posedge cin or posedge a[1] or posedge b[1] or posedge a[2] or posedge b[2] or posedge a[3] or posedge b[3])
        cout == ((a[3] & b[3]) | (a[3] & carry3) | (b[3] & carry3))
    );
endmodule

rtl:
module and_module(A, B, output_signal);

  input [7:0] A;
  input [7:0] B;
  output output_signal;

  wire [7:0] and_result;

  and and_gate_0 (and_result[0], A[0], B[0]);
  and and_gate_1 (and_result[1], A[1], B[1]);
  and and_gate_2 (and_result[2], A[2], B[2]);
  and and_gate_3 (and_result[3], A[3], B[3]);
  and and_gate_4 (and_result[4], A[4], B[4]);
  and and_gate_5 (and_result[5], A[5], B[5]);
  and and_gate_6 (and_result[6], A[6], B[6]);
  and and_gate_7 (and_result[7], A[7], B[7]);

  assign output_signal = and_result[0] & and_result[1] & and_result[2] & and_result[3] & and_result[4] & and_result[5] & and_result[6] & and_result[7];

endmodule

sva:
module and_module_sva (
    input  logic        CLK,            // sampling clock for SVA
    input  logic [7:0]  A,
    input  logic [7:0]  B,
    input  logic        output_signal,
    input  logic [7:0]  and_result      // internal wire from RTL
);
    // Internal and_result equals bitwise A & B.
    check_and_result_bitwise_and: assert property (
        @(posedge CLK) disable iff (1'b0) and_result == (A & B)
    );

    // Output equals AND-reduction of internal and_result.
    check_output_equals_reduction_of_internal: assert property (
        @(posedge CLK) disable iff (1'b0) output_signal == (&and_result)
    );

    // Output equals AND-reduction across bitwise pairs A & B.
    check_output_equals_and_of_pairs: assert property (
        @(posedge CLK) disable iff (1'b0) output_signal == &(A & B)
    );

    // If output is 1, then all bits of A and B are 1.
    check_output_one_implies_all_ones: assert property (
        @(posedge CLK) disable iff (1'b0) output_signal |-> ((&A) && (&B))
    );

    // If all bits of A and B are 1, then output is 1.
    check_all_ones_implies_output_one: assert property (
        @(posedge CLK) disable iff (1'b0) ((&A) && (&B)) |-> (output_signal == 1'b1)
    );

    // If any bit of A is 0, output must be 0.
    check_any_zero_in_A_forces_zero: assert property (
        @(posedge CLK) disable iff (1'b0) (~&A) |-> (output_signal == 1'b0)
    );

    // If any bit of B is 0, output must be 0.
    check_any_zero_in_B_forces_zero: assert property (
        @(posedge CLK) disable iff (1'b0) (~&B) |-> (output_signal == 1'b0)
    );
endmodule

rtl:
module and_gate(
    input a, 
    input b,
    output reg out
);

always @ (a, b) begin
    out = a & b;
end

endmodule

sva:
module and_gate_sva (
    input logic clk,
    input logic a,
    input logic b,
    input logic out
);
    // Output equals bitwise AND of inputs at every sample.
    check_out_equals_and: assert property (
        @(posedge clk) out == (a & b)
    );

    // Output high implies both inputs are high.
    check_out_high_implies_inputs_high: assert property (
        @(posedge clk) out |-> (a & b)
    );

    // If input a is 0, output must be 0.
    check_zero_a_forces_zero_out: assert property (
        @(posedge clk) !a |-> !out
    );

    // If input b is 0, output must be 0.
    check_zero_b_forces_zero_out: assert property (
        @(posedge clk) !b |-> !out
    );

    // If input a is 1, output equals b.
    check_a_one_equals_b: assert property (
        @(posedge clk) a |-> (out == b)
    );

    // If input b is 1, output equals a.
    check_b_one_equals_a: assert property (
        @(posedge clk) b |-> (out == a)
    );

    // If both inputs are 1, output must be 1.
    check_both_one_outputs_one: assert property (
        @(posedge clk) (a & b) |-> out
    );

    // If inputs are stable across samples, output is stable too.
    check_stability_when_inputs_stable: assert property (
        @(posedge clk) ((a == $past(a)) && (b == $past(b))) |-> (out == $past(out))
    );

    // Output can only change if at least one input changes.
    check_out_changes_only_on_input_change: assert property (
        @(posedge clk) (out != $past(out)) |-> ((a != $past(a)) || (b != $past(b)))
    );
endmodule

rtl:
module mux
  #(
    parameter INIT_VAL = 8'hB8
  )
  (
    input ctrl,
    input D0,
    input D1,
    output S
  );

  assign S = ctrl ? D1 : D0;

  // Verilog-XL specific way of implementing this MUX
  wire mux_out = INIT_VAL[ctrl ? 0 : 4];

endmodule

sva:
module mux_sva #(
    parameter [7:0] INIT_VAL = 8'hB8
) (
    input logic ctrl,
    input logic D0,
    input logic D1,
    input logic S,
    input logic mux_out
);

    // S equals selected input on any input/control edge.
    check_mux_output_function: assert property (
        @(posedge ctrl or negedge ctrl or posedge D0 or negedge D0 or posedge D1 or negedge D1)
            S == (ctrl ? D1 : D0)
    );

    // On ctrl rising edge, S follows D1.
    check_ctrl_rise_select_D1: assert property (
        @(posedge ctrl) S == D1
    );

    // On ctrl falling edge, S follows D0.
    check_ctrl_fall_select_D0: assert property (
        @(negedge ctrl) S == D0
    );

    // When ctrl=1, S equals D1 at D1 edges.
    check_D1_edges_when_selected: assert property (
        @(posedge D1 or negedge D1) (ctrl == 1'b1) |-> (S == D1)
    );

    // When ctrl=0, S equals D0 at D0 edges.
    check_D0_edges_when_selected: assert property (
        @(posedge D0 or negedge D0) (ctrl == 1'b0) |-> (S == D0)
    );

    // When ctrl=0, D1 edges leave S equal to D0.
    check_unselected_D1_no_effect: assert property (
        @(posedge D1 or negedge D1) (ctrl == 1'b0) |-> (S == D0)
    );

    // When ctrl=1, D0 edges leave S equal to D1.
    check_unselected_D0_no_effect: assert property (
        @(posedge D0 or negedge D0) (ctrl == 1'b1) |-> (S == D1)
    );

    // S changes only if ctrl or the currently selected input changes.
    check_output_changes_only_on_ctrl_or_selected_input: assert property (
        @(posedge ctrl or negedge ctrl or posedge D0 or negedge D0 or posedge D1 or negedge D1)
            $changed(S) |-> ($changed(ctrl) || (ctrl && $changed(D1)) || (!ctrl && $changed(D0)))
    );

    // Internal mux_out reflects INIT_VAL bit indexed by ctrl on any edge.
    check_verilog_xl_mux_out_mapping: assert property (
        @(posedge ctrl or negedge ctrl or posedge D0 or negedge D0 or posedge D1 or negedge D1)
            mux_out == (ctrl ? INIT_VAL[0] : INIT_VAL[4])
    );

endmodule

module up_down_counter_sva (
    input logic clk,
    input logic reset,
    input logic load,
    input logic up_down,
    input logic [15:0] q
);
    // Reset drives q to zero (synchronous, active-high).
    reset_sets_zero: assert property (
        @(posedge clk) reset |-> (q == 16'd0)
    );

    // When load is asserted, q holds its previous value (load path is identity).
    hold_on_load: assert property (
        @(posedge clk) disable iff (reset) load |=> (q == $past(q))
    );

    // When not loading and up_down=1, next q increments by 1.
    count_up_when_up: assert property (
        @(posedge clk) disable iff (reset) (!load && up_down) |=> (q == $past(q) + 16'd1)
    );

    // When not loading and up_down=0, next q decrements by 1.
    count_down_when_down: assert property (
        @(posedge clk) disable iff (reset) (!load && !up_down) |=> (q == $past(q) - 16'd1)
    );

    // If q changed from last cycle, load must have been deasserted.
    change_implies_no_load: assert property (
        @(posedge clk) disable iff (reset) (q != $past(q)) |-> (!$past(load))
    );

    // If q stayed the same (no reset), load must have been asserted.
    stable_implies_load: assert property (
        @(posedge clk) disable iff (reset) (q == $past(q)) |-> ($past(load))
    );

    // If q incremented, the previous cycle was up count without load.
    inc_implies_up_no_load: assert property (
        @(posedge clk) disable iff (reset) (q == $past(q) + 16'd1) |-> (!$past(load) && $past(up_down))
    );

    // If q decremented, the previous cycle was down count without load.
    dec_implies_down_no_load: assert property (
        @(posedge clk) disable iff (reset) (q == $past(q) - 16'd1) |-> (!$past(load) && !$past(up_down))
    );

    // Load has priority over up_down when both are asserted (q holds).
    load_has_priority_over_up_down: assert property (
        @(posedge clk) disable iff (reset) (load && up_down) |=> (q == $past(q))
    );

    // Full next-state relation when not in reset.
    next_state_functional: assert property (
        @(posedge clk) disable iff (reset)
            1'b1 |=> ( q == ( $past(load) ? $past(q)
                                            : ( $past(up_down) ? ($past(q) + 16'd1)
                                                               : ($past(q) - 16'd1) ) ) )
    );
endmodule

rtl:
module ripple_carry_adder (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] Sum,
    output Cout
);

    wire c0, c1, c2, c3; // intermediate carry signals

    // full adder for bit 0
    full_adder fa0 (.a(A[0]), .b(B[0]), .cin(Cin), .s(Sum[0]), .cout(c0));

    // full adder for bit 1
    full_adder fa1 (.a(A[1]), .b(B[1]), .cin(c0), .s(Sum[1]), .cout(c1));

    // full adder for bit 2
    full_adder fa2 (.a(A[2]), .b(B[2]), .cin(c1), .s(Sum[2]), .cout(c2));

    // full adder for bit 3
    full_adder fa3 (.a(A[3]), .b(B[3]), .cin(c2), .s(Sum[3]), .cout(c3));

    // carry-out calculation
    assign Cout = (A[3] & B[3]) | (c2 & (A[3] | B[3])) | (c1 & c0);

endmodule


module full_adder (
    input a,
    input b,
    input cin,
    output s,
    output cout
);

    wire w1, w2, w3;

    // XOR gate for sum
    assign s = a ^ b ^ cin;

    // AND gate for carry-out
    assign w1 = a & b;
    assign w2 = a & cin;
    assign w3 = b & cin;
    assign cout = w1 | w2 | w3;

endmodule

sva:
module ripple_carry_adder_sva (
    input logic       clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic       Cin,
    input logic [3:0] Sum,
    input logic       Cout
);

    // External sampling clock; the DUT itself is combinational and has no reset.

    // Bit 0 sum is the XOR of A[0], B[0], and Cin.
    check_sum_bit0_xor: assert property (
        @(posedge clk)
        Sum[0] == (A[0] ^ B[0] ^ Cin)
    );

    // Bit 1 sum uses the carry generated by bit 0.
    check_sum_bit1_with_carry0: assert property (
        @(posedge clk)
        Sum[1] == (A[1] ^ B[1] ^ ((A[0] & B[0]) | (Cin & (A[0] | B[0]))))
    );

    // Bit 2 sum uses the carry generated by bit 1.
    check_sum_bit2_with_carry1: assert property (
        @(posedge clk)
        Sum[2] == (A[2] ^ B[2] ^ (
            (A[1] & B[1]) |
            (((A[0] & B[0]) | (Cin & (A[0] | B[0]))) & (A[1] | B[1]))
        ))
    );

    // Bit 3 sum uses the carry generated by bit 2.
    check_sum_bit3_with_carry2: assert property (
        @(posedge clk)
        Sum[3] == (A[3] ^ B[3] ^ (
            (A[2] & B[2]) |
            (((A[1] & B[1]) | (((A[0] & B[0]) | (Cin & (A[0] | B[0]))) & (A[1] | B[1]))) & (A[2] | B[2]))
        ))
    );

    // Sum matches the low 4 bits of A + B + Cin.
    check_sum_matches_low_addition: assert property (
        @(posedge clk)
        ({1'b0, Sum} == (({1'b0, A} + {1'b0, B} + Cin) & 5'h0F))
    );

    // MSB generate alone forces Cout high.
    check_cout_from_msb_generate: assert property (
        @(posedge clk)
        (A[3] & B[3]) |-> Cout
    );

    // Propagating the derived bit-2 carry through bit 3 forces Cout high.
    check_cout_from_msb_propagate: assert property (
        @(posedge clk)
        (
            ((A[2] & B[2]) |
             (((A[1] & B[1]) |
               (((A[0] & B[0]) | (Cin & (A[0] | B[0]))) & (A[1] | B[1]))) & (A[2] | B[2])))
            &
            (A[3] | B[3])
        ) |-> Cout
    );

    // The extra lower-carry term in the RTL also forces Cout high.
    check_cout_from_lower_carry_term: assert property (
        @(posedge clk)
        (
            ((A[1] & B[1]) |
             (((A[0] & B[0]) | (Cin & (A[0] | B[0]))) & (A[1] | B[1])))
            &
            ((A[0] & B[0]) | (Cin & (A[0] | B[0])))
        ) |-> Cout
    );

    // Cout matches the explicit RTL carry-out expression.
    check_cout_matches_rtl_logic: assert property (
        @(posedge clk)
        Cout == (
            (A[3] & B[3]) |
            (
                (
                    (A[2] & B[2]) |
                    (
                        (
                            (A[1] & B[1]) |
                            (((A[0] & B[0]) | (Cin & (A[0] | B[0]))) & (A[1] | B[1]))
                        ) &
                        (A[2] | B[2])
                    )
                ) &
                (A[3] | B[3])
            ) |
            (
                (
                    (A[1] & B[1]) |
                    (((A[0] & B[0]) | (Cin & (A[0] | B[0]))) & (A[1] | B[1]))
                ) &
                ((A[0] & B[0]) | (Cin & (A[0] | B[0])))
            )
        )
    );

endmodule

