    check_lo_requires_no_pwrgood: assert property (
        @(posedge clk) LO |-> ~pwrgood_pp
    );

    // LO can only be high when pulldown0_out is low.
    check_lo_requires_no_pulldown: assert property (
        @(posedge clk) LO |-> ~pulldown0_out
    );

