module four_bit_adder (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    input reset,
    input Clk,
    input Clk_180,
    output [3:0] S,
    output Cout
);

reg [3:0] S_reg;
reg Cout_reg;

always @(posedge Clk, posedge reset) begin
    if (reset) begin
        S_reg <= 4'b0;
        Cout_reg <= 1'b0;
    end else begin
        S_reg <= A + B + Cin;
        Cout_reg <= ((A[3] & B[3]) | (Cin & (A[3] | B[3])));
    end
end

assign S = S_reg;
assign Cout = Cout_reg;

endmodule

sva:
module four_bit_adder_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic Cin,
    input logic reset,
    input logic Clk,
    input logic Clk_180,
    input logic [3:0] S,
    input logic Cout
);

    // While reset is asserted, both registered outputs are zero.
    check_reset_clears_outputs: assert property (
        @(posedge Clk) reset |-> ({Cout, S} == 5'b0)
    );

    // The first sampled clock after reset was high still sees cleared outputs.
    check_post_reset_sampled_outputs_zero: assert property (
        @(posedge Clk) disable iff (reset || $initstate)
        $past(reset) |-> ({Cout, S} == 5'b0)
    );

    // Outside reset, outputs are either reset-cleared or the prior clocked computation.
    check_outputs_are_zero_or_prior_computation: assert property (
        @(posedge Clk) disable iff (reset || $initstate)
        (({Cout, S} == 5'b0) ||
         ({Cout, S} == {
            $past(((A[3] & B[3]) | (Cin & (A[3] | B[3])))),
            $past(A + B + Cin)
         }))
    );

    // Any non-zero output state must come from the prior clocked computation.
    check_nonzero_outputs_match_prior_computation: assert property (
        @(posedge Clk) disable iff (reset || $initstate)
        ({Cout, S} != 5'b0) |-> ({Cout, S} == {
            $past(((A[3] & B[3]) | (Cin & (A[3] | B[3])))),
            $past(A + B + Cin)
        })
    );

endmodule

rtl:
module synchronous_counter(clock, reset, enable, load, data_in, data_out);

   parameter DataSize = 4;

   input wire clock;
   input wire reset;
   input wire enable;
   input wire load;
   input wire [DataSize-1:0] data_in;

   output reg [DataSize-1:0] data_out;

   always @ (posedge clock or negedge reset) begin
      if (reset == 0) begin
         data_out <= 0;
      end
      else if (enable == 1) begin
         if (load == 1) begin
            data_out <= data_in;
         end
         else begin
            data_out <= data_out + 1;
         end
      end
   end // always @ (posedge clock or negedge reset)

endmodule

sva:
module synchronous_counter_sva #(
    parameter DataSize = 4
) (
    input  logic                  clock,
    input  logic                  reset,
    input  logic                  enable,
    input  logic                  load,
    input  logic [DataSize-1:0]   data_in,
    input  logic [DataSize-1:0]   data_out
);

    // Active-low reset forces the counter output to zero.
    check_reset_clears_output: assert property (
        @(posedge clock)
        !reset |-> (data_out == '0)
    );

    // A sampled reset cycle leaves the next sampled output at zero.
    check_reset_keeps_output_zero_next_cycle: assert property (
        @(posedge clock)
        !reset |=> (data_out == '0)
    );

    // When enabled and load is high, the next output reflects the prior input unless reset intervened.
    check_load_updates_output: assert property (
        @(posedge clock) disable iff (!reset)
        (enable && load) |=> ((data_out == $past(data_in)) || (data_out == '0))
    );

    // When enabled and load is low, the next output increments unless reset intervened.
    check_enable_increments_output: assert property (
        @(posedge clock) disable iff (!reset)
        (enable && !load) |=> ((data_out == ($past(data_out) + {{(DataSize-1){1'b0}}, 1'b1})) || (data_out == '0))
    );

    // When enable is low, the output holds its value unless reset intervened.
    check_disable_holds_output: assert property (
        @(posedge clock) disable iff (!reset)
        (!enable) |=> ((data_out == $past(data_out)) || (data_out == '0))
    );

    // Load is ignored when enable is low.
    check_load_ignored_when_disabled: assert property (
        @(posedge clock) disable iff (!reset)
        (!enable && load) |=> ((data_out == $past(data_out)) || (data_out == '0))
    );

endmodule

module DAC_8BIT_sva (
