rtl:
module four_bit_adder (
    input [3:0] A,
    input [3:0] B,
    output [3:0] sum,
    output carry_out
);

    wire [3:0] xor_out;
    wire [3:0] and_out;
    wire [3:0] or_out;

    assign xor_out = A ^ B;
    assign and_out = A & B;
    assign sum = xor_out ^ or_out;
    assign or_out = {1'b0, and_out[3], and_out[2], and_out[1]} | {and_out[3], and_out[2], and_out[1], and_out[0]};
    assign carry_out = or_out[3];

endmodule

sva:
module four_bit_adder_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] sum,
    input logic carry_out
);

    // No RTL clock or reset; sample this combinational logic on $global_clock.

    // sum matches the exact combinational equation implemented in the RTL.
    check_sum_vector_equation: assert property (
        @($global_clock)
        sum == ((A ^ B) ^
                ({1'b0, (A[3] & B[3]), (A[2] & B[2]), (A[1] & B[1])} |
                 {(A[3] & B[3]), (A[2] & B[2]), (A[1] & B[1]), (A[0] & B[0])}))
    );

    // carry_out matches the RTL carry output equation.
    check_carry_out_equation: assert property (
        @($global_clock)
        carry_out == (A[3] & B[3])
    );

    // sum[3] matches xor_out[3] XOR the MSB carry term.
    check_sum_bit3_equation: assert property (
        @($global_clock)
        sum[3] == ((A[3] ^ B[3]) ^ (A[3] & B[3]))
    );

    // sum[2] matches xor_out[2] XOR the RTL OR of adjacent AND terms.
    check_sum_bit2_equation: assert property (
        @($global_clock)
        sum[2] == ((A[2] ^ B[2]) ^ ((A[3] & B[3]) | (A[2] & B[2])))
    );

    // sum[1] matches xor_out[1] XOR the RTL OR of adjacent AND terms.
    check_sum_bit1_equation: assert property (
        @($global_clock)
        sum[1] == ((A[1] ^ B[1]) ^ ((A[2] & B[2]) | (A[1] & B[1])))
    );

    // sum[0] matches xor_out[0] XOR the RTL OR of adjacent AND terms.
    check_sum_bit0_equation: assert property (
        @($global_clock)
        sum[0] == ((A[0] ^ B[0]) ^ ((A[1] & B[1]) | (A[0] & B[0])))
    );

endmodule

rtl:
module four_bit_adder (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] S,
    output Cout
);

    wire [3:0] sum;

    assign sum[0] = A[0] ^ B[0] ^ Cin;
    assign sum[1] = A[1] ^ B[1] ^ (sum[0] & Cin);
    assign sum[2] = A[2] ^ B[2] ^ (sum[1] & sum[0]);
    assign sum[3] = A[3] ^ B[3] ^ (sum[2] & sum[1]);

    assign Cout = (sum[3] & sum[2]) | (sum[3] & sum[1]) | (sum[2] & sum[1] & Cin);
    assign S = sum;

endmodule

sva:
module four_bit_adder_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic Cin,
    input logic [3:0] S,
    input logic Cout
);

    // S[0] matches the RTL XOR of A[0], B[0], and Cin.
    check_sum_bit0_function: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0] ^ Cin)
    );

    // S[1] matches the RTL function using S[0] and Cin.
    check_sum_bit1_function: assert property (
        @(posedge clk) S[1] == (A[1] ^ B[1] ^ (S[0] & Cin))
    );

    // S[2] matches the RTL function using S[1] and S[0].
    check_sum_bit2_function: assert property (
        @(posedge clk) S[2] == (A[2] ^ B[2] ^ (S[1] & S[0]))
    );

    // S[3] matches the RTL function using S[2] and S[1].
    check_sum_bit3_function: assert property (
        @(posedge clk) S[3] == (A[3] ^ B[3] ^ (S[2] & S[1]))
    );

    // Cout matches the RTL expression built from the sum bits and Cin.
    check_cout_function: assert property (
        @(posedge clk) Cout == ((S[3] & S[2]) | (S[3] & S[1]) | (S[2] & S[1] & Cin))
    );

    // Stable inputs must keep all outputs stable across sampled cycles.
    check_outputs_stable_when_inputs_stable: assert property (
        @(posedge clk) $stable({A, B, Cin}) |-> $stable({S, Cout})
    );

    // S[0] depends only on A[0], B[0], and Cin.
    check_sum_bit0_locality: assert property (
        @(posedge clk) $stable({A[0], B[0], Cin}) |-> $stable(S[0])
    );

    // S[1] depends only on A[1:0], B[1:0], and Cin.
    check_sum_bit1_locality: assert property (
        @(posedge clk) $stable({A[1:0], B[1:0], Cin}) |-> $stable(S[1])
    );

    // S[2] depends only on A[2:0], B[2:0], and Cin.
    check_sum_bit2_locality: assert property (
        @(posedge clk) $stable({A[2:0], B[2:0], Cin}) |-> $stable(S[2])
    );

    // Cout depends only on S[3:1] and Cin.
    check_cout_locality: assert property (
        @(posedge clk) $stable({S[3:1], Cin}) |-> $stable(Cout)
    );

endmodule

rtl:
module priority_encoder (
    input [3:0] in,
    output reg [1:0] pos
);

reg [3:0] temp;

always @* begin
    if (in[3] == 1) temp = 3;
    else if (in[2] == 1) temp = 2;
    else if (in[1] == 1) temp = 1;
    else if (in[0] == 1) temp = 0;
    else temp = 4'b0000;
end

always @* begin
    case (temp)
        4'b0001: pos = 2'b00;
        4'b0010: pos = 2'b01;
        4'b0100: pos = 2'b10;
        4'b1000: pos = 2'b11;
        default: pos = 2'b00;
    endcase
end

endmodule

