module nand4_assertions (
    input logic clk,
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic Y,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB
);

    // Y implements the 4-input AND of A, B, C, and D.
    check_output_matches_and: assert property (
        @(posedge clk) Y == (A && B && C && D)
    );

    // All four inputs high drives Y high.
    check_all_high_implies_y_high: assert property (
        @(posedge clk) (A && B && C && D) |-> Y
    );

    // Y can be high only when all four inputs are high.
    check_y_high_requires_all_high: assert property (
        @(posedge clk) Y |-> (A && B && C && D)
    );

    // Any low input forces Y low.
    check_any_low_implies_y_low: assert property (
        @(posedge clk) (!A || !B || !C || !D) |-> !Y
    );

    // A rising Y edge requires all four inputs to be high.
    check_y_rise_requires_all_high: assert property (
        @(posedge clk) $rose(Y) |-> (A && B && C && D)
    );

    // A falling Y edge requires at least one input to be low.
    check_y_fall_requires_low_input: assert property (
        @(posedge clk) $fell(Y) |-> (!A || !B || !C || !D)
    );

endmodule

rtl:
module up_counter (
    input clk,
    input rst,
    output reg [3:0] count,
    output reg overflow
);

    always @(posedge clk) begin
        if (rst) begin
            count <= 4'b0;
            overflow <= 1'b0;
        end
        else if (count == 4'b1111) begin
            count <= 4'b0;
            overflow <= 1'b1;
        end
        else begin
            count <= count + 1;
            overflow <= 1'b0;
        end
    end

endmodule

sva:
module up_counter_sva (
    input logic       clk,
    input logic       rst,
    input logic [3:0] count,
    input logic       overflow
);

    // Reset drives count to zero on the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk) disable iff ($initstate)
        rst |=> (count == 4'h0)
    );

    // Reset clears overflow on the next clock.
    check_reset_clears_overflow: assert property (
        @(posedge clk) disable iff ($initstate)
        rst |=> (overflow == 1'b0)
    );

    // A non-max count increments by one.
    check_count_increments_below_max: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        (count != 4'hF) |=> (count == ($past(count) + 4'h1))
    );

    // A non-max count keeps overflow low.
    check_overflow_low_below_max: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        (count != 4'hF) |=> (overflow == 1'b0)
    );

    // A max count wraps back to zero.
    check_count_wraps_at_max: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        (count == 4'hF) |=> (count == 4'h0)
    );

    // A max count raises overflow.
    check_overflow_asserts_at_max: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        (count == 4'hF) |=> (overflow == 1'b1)
    );

    // Overflow is only asserted when count is zero.
    check_overflow_implies_zero_count: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        overflow |-> (count == 4'h0)
    );

    // Overflow only follows a previous max count.
    check_overflow_implies_previous_max: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        overflow |-> ($past(count) == 4'hF)
    );

endmodule

