module inverter (
  input wire in,
  output wire out
);
  assign out = ~in;
endmodule

module ring_oscillator (
  input wire in,
  output wire out
);

  wire stage1, stage2, stage3, stage4, stage5;

  // Instantiate the inverter stages
  inverter inv1 (.in(in), .out(stage1));
  inverter inv2 (.in(stage1), .out(stage2));
  inverter inv3 (.in(stage2), .out(stage3));
  inverter inv4 (.in(stage3), .out(stage4));
  inverter inv5 (.in(stage4), .out(stage5));

  // Connect the output signal to the last stage in the ring
  assign out = stage5;

endmodule

sva:
module ring_oscillator_sva (
    input wire clk,
    input wire in,
    input wire out,
    input wire stage1,
    input wire stage2,
    input wire stage3,
    input wire stage4,
    input wire stage5
);

    // First inverter stage complements the module input.
    check_stage1_inverts_input: assert property (
        @(posedge clk) stage1 == ~in
    );

    // Second inverter stage complements stage1.
    check_stage2_inverts_stage1: assert property (
        @(posedge clk) stage2 == ~stage1
    );

    // Third inverter stage complements stage2.
    check_stage3_inverts_stage2: assert property (
        @(posedge clk) stage3 == ~stage2
    );

    // Fourth inverter stage complements stage3.
    check_stage4_inverts_stage3: assert property (
        @(posedge clk) stage4 == ~stage3
    );

    // Fifth inverter stage complements stage4.
    check_stage5_inverts_stage4: assert property (
        @(posedge clk) stage5 == ~stage4
    );

    // Output is wired directly to the fifth stage.
    check_out_matches_stage5: assert property (
        @(posedge clk) out == stage5
    );

    // End-to-end behavior is an inversion of the input.
    check_out_inverts_input: assert property (
        @(posedge clk) out == ~in
    );

endmodule

rtl:
module mux_2to1(
    input sel,
    input in0,
    input in1,
    output out
    );

    wire not_sel;
    assign not_sel = ~sel;

    wire and0;
    assign and0 = in0 & not_sel;

    wire and1;
    assign and1 = in1 & sel;

    assign out = and0 | and1;

endmodule

sva:
module mux_2to1_sva(
    input logic clk,
    input logic sel,
    input logic in0,
    input logic in1,
    input logic out
);

    // Out must match the 2:1 mux Boolean equation.
    check_mux_equation: assert property (
        @(posedge clk) out == ((~sel & in0) | (sel & in1))
    );

    // When sel is LOW, out must follow in0.
    check_selects_in0: assert property (
        @(posedge clk) (sel == 1'b0) |-> (out == in0)
    );

    // When sel is HIGH, out must follow in1.
    check_selects_in1: assert property (
        @(posedge clk) (sel == 1'b1) |-> (out == in1)
    );

    // If both inputs are LOW, out must be LOW.
    check_both_inputs_low: assert property (
        @(posedge clk) ((in0 == 1'b0) && (in1 == 1'b0)) |-> (out == 1'b0)
    );

    // If both inputs are HIGH, out must be HIGH.
    check_both_inputs_high: assert property (
        @(posedge clk) ((in0 == 1'b1) && (in1 == 1'b1)) |-> (out == 1'b1)
    );

    // With in0 LOW and in1 HIGH, out must equal sel.
    check_output_equals_sel_for_01: assert property (
        @(posedge clk) ((in0 == 1'b0) && (in1 == 1'b1)) |-> (out == sel)
    );

    // With in0 HIGH and in1 LOW, out must equal inverse of sel.
    check_output_equals_not_sel_for_10: assert property (
        @(posedge clk) ((in0 == 1'b1) && (in1 == 1'b0)) |-> (out == ~sel)
    );

endmodule

rtl:
module adder_32bit(
  input [31:0] A,
  input [31:0] B,
  input Cin,
  output [31:0] Sum,
  output Cout
  );

  wire [31:0] carry; // intermediate carry values
  wire [31:0] sum; // intermediate sum values

  // full adder for bit 0
  full_adder fa0(A[0], B[0], Cin, sum[0], carry[0]);

  // carry chain for bits 1-30
  genvar i;
  generate
    for (i = 1; i < 31; i = i + 1) begin
      full_adder fa(
        A[i], B[i], carry[i-1], sum[i], carry[i]);
    end
  endgenerate

  // full adder for bit 31 with Cout as output
  full_adder fa31(A[31], B[31], carry[30], Sum[31], Cout);

  // assign intermediate sum values to output Sum
  assign Sum = sum;

endmodule

// full adder module
module full_adder(
  input A,
  input B,
  input Cin,
  output Sum,
  output Cout
  );

  assign Sum = A ^ B ^ Cin;
  assign Cout = (A & B) | (Cin & (A ^ B));

endmodule

sva:
module adder_32bit_sva (
    input logic        clk,
    input logic [31:0] A,
    input logic [31:0] B,
    input logic        Cin,
    input logic [31:0] Sum,
    input logic        Cout,
    input logic [31:0] carry,
    input logic [31:0] sum
);

    // Bit 0 sum follows the first full-adder XOR logic.
    check_bit0_sum_logic: assert property (
        @(posedge clk)
        sum[0] == (A[0] ^ B[0] ^ Cin)
    );

    // Bit 0 carry follows the first full-adder carry logic.
    check_bit0_carry_logic: assert property (
        @(posedge clk)
        carry[0] == ((A[0] & B[0]) | (Cin & (A[0] ^ B[0])))
    );

    genvar i;
    generate
        for (i = 1; i < 31; i = i + 1) begin : gen_full_adder_chain_checks
            // Each intermediate sum bit follows full-adder XOR logic.
            check_sum_bit_logic: assert property (
                @(posedge clk)
                sum[i] == (A[i] ^ B[i] ^ carry[i-1])
            );

            // Each intermediate carry bit follows full-adder carry logic.
            check_carry_bit_logic: assert property (
                @(posedge clk)
                carry[i] == ((A[i] & B[i]) | (carry[i-1] & (A[i] ^ B[i])))
            );
        end
    endgenerate

    // Lower output bits are driven from the intermediate sum bus.
    check_lower_sum_output_mapping: assert property (
        @(posedge clk)
        Sum[30:0] == sum[30:0]
    );

    // The MSB sum follows the final full-adder XOR logic.
    check_msb_sum_logic: assert property (
        @(posedge clk)
        Sum[31] == (A[31] ^ B[31] ^ carry[30])
    );

    // Carry-out follows the final full-adder carry logic.
    check_cout_logic: assert property (
        @(posedge clk)
        Cout == ((A[31] & B[31]) | (carry[30] & (A[31] ^ B[31])))
    );

endmodule

rtl:
module bar #(parameter OP_ADD = 2'b00) (
   input [3:0] a,
   input [3:0] b,
   input [1:0] sel,
   output reg [3:0] result
);

   always @(*) begin
      case(sel)
         2'b00: result = a + b;
         2'b01: result = a + ~b + 1;
         2'b10: result = a & b;
         2'b11: result = a | b;
         default: result = 4'b0;
      endcase
   end

   assign sel[1:0] = OP_ADD; // set sel value for addition operation

endmodule

sva:
module bar_assertions (
    input logic [3:0] a,
    input logic [3:0] b,
    input logic [1:0] sel,
    input logic [3:0] result
);

    // When sel is 00, result is the 4-bit sum of a and b.
    check_result_add: assert property (
        @($global_clock) (sel == 2'b00) |-> (result == ((a + b) & 4'hF))
    );

    // When sel is 01, result is the 4-bit value of a + ~b + 1.
    check_result_sub: assert property (
        @($global_clock) (sel == 2'b01) |-> (result == ((a + ~b + 1) & 4'hF))
    );

    // When sel is 10, result is the bitwise AND of a and b.
    check_result_and: assert property (
        @($global_clock) (sel == 2'b10) |-> (result == (a & b))
    );

    // When sel is 11, result is the bitwise OR of a and b.
    check_result_or: assert property (
        @($global_clock) (sel == 2'b11) |-> (result == (a | b))
    );

endmodule

rtl:
module counter_4bit (clk, rst_n, enable, count_up, q);

input clk;
input rst_n;
input enable;
input count_up;
output reg [3:0] q;

always @(posedge clk or negedge rst_n) begin
  if(!rst_n) begin
    q <= 4'b0000;
  end else if(enable) begin
    if(count_up) begin
      q <= q + 1;
    end else begin
      q <= q - 1;
    end
  end
end

endmodule

sva:
module counter_4bit_sva (
    input logic       clk,
    input logic       rst_n,
    input logic       enable,
    input logic       count_up,
    input logic [3:0] q
);

    // Sequential 4-bit counter on clk with active-low reset rst_n.

    // Active-low reset forces q to zero.
    check_reset_clears_q: assert property (
        @(posedge clk)
        (!rst_n) |-> (q == 4'b0000)
    );

    // q holds its value when enable is low.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (!rst_n)
        (!enable) |=> (q == $past(q))
    );

    // q increments by one when enabled and counting up.
    check_increment_when_enabled_up: assert property (
        @(posedge clk) disable iff (!rst_n)
        (enable && count_up) |=> (q == ($past(q) + 4'd1))
    );

    // q decrements by one when enabled and counting down.
    check_decrement_when_enabled_down: assert property (
        @(posedge clk) disable iff (!rst_n)
        (enable && !count_up) |=> (q == ($past(q) - 4'd1))
    );

    // Counting up wraps from 15 to 0.
    check_wrap_up_from_max: assert property (
        @(posedge clk) disable iff (!rst_n)
        (enable && count_up && (q == 4'hF)) |=> (q == 4'h0)
    );

    // Counting down wraps from 0 to 15.
    check_wrap_down_from_zero: assert property (
        @(posedge clk) disable iff (!rst_n)
        (enable && !count_up && (q == 4'h0)) |=> (q == 4'hF)
    );

endmodule

rtl:
module mux_4to1(input [3:0] in, input [1:0] sel, output reg out);

  always @(*) begin
    case(sel)
      2'b00: out = in[0];
      2'b01: out = in[1];
      2'b10: out = in[2];
      2'b11: out = in[3];
    endcase
  end

endmodule

sva:
module mux_4to1_sva (
