rtl:
`ifdef INCL_CDC_3FF
`else
`define INCL_CDC_3FF

module cdc_3ff #(
  parameter DATA_WIDTH = 1,
  parameter INIT_VALUE = 0
) (
  input      target_clk,
  input      reset,

  input      [DATA_WIDTH-1:0] input_signal,
  output reg [DATA_WIDTH-1:0] output_signal
);

 reg [DATA_WIDTH-1:0] signal_meta  ;
 reg [DATA_WIDTH-1:0] signal_d  ;

always @ (posedge target_clk or posedge reset) begin
  if (reset) begin
    signal_meta   <= INIT_VALUE;
    signal_d      <= INIT_VALUE;
    output_signal <= INIT_VALUE;
  end else begin
    signal_meta   <= input_signal;
    signal_d      <= signal_meta;
    output_signal <= signal_d;
  end
end

endmodule

`endif

sva:
module cdc_3ff_sva #(
    parameter DATA_WIDTH = 1,
    parameter INIT_VALUE = 0
) (
    input logic target_clk,
    input logic reset,
    input logic [DATA_WIDTH-1:0] input_signal,
    input logic [DATA_WIDTH-1:0] output_signal,
    input logic [DATA_WIDTH-1:0] signal_meta,
    input logic [DATA_WIDTH-1:0] signal_d
);

    // A sampled reset leaves all three stages at INIT_VALUE on the next clock.
    check_reset_clears_all_stages_next_clock: assert property (
        @(posedge target_clk)
        reset |=> (signal_meta == INIT_VALUE) &&
                  (signal_d == INIT_VALUE) &&
                  (output_signal == INIT_VALUE)
    );

    // The first stage captures input_signal on the next target clock.
    check_signal_meta_captures_input: assert property (
        @(posedge target_clk) disable iff (reset)
        1'b1 |=> (signal_meta == $past(input_signal))
    );

    // The second stage captures signal_meta on the next target clock.
    check_signal_d_captures_signal_meta: assert property (
        @(posedge target_clk) disable iff (reset)
        1'b1 |=> (signal_d == $past(signal_meta))
    );

    // The output stage captures signal_d on the next target clock.
    check_output_captures_signal_d: assert property (
        @(posedge target_clk) disable iff (reset)
        1'b1 |=> (output_signal == $past(signal_d))
    );

    // input_signal reaches signal_d after two target clocks.
    check_signal_d_matches_input_after_two_clocks: assert property (
        @(posedge target_clk) disable iff (reset)
        1'b1 |=> ##1 (signal_d == $past(input_signal, 2))
    );

    // input_signal reaches output_signal after three target clocks.
    check_output_matches_input_after_three_clocks: assert property (
        @(posedge target_clk) disable iff (reset)
        1'b1 |=> ##2 (output_signal == $past(input_signal, 3))
    );

    // signal_d stays at INIT_VALUE for two clocks after a reset sample.
    check_signal_d_stays_init_two_clocks_after_reset: assert property (
        @(posedge target_clk)
        reset |=> (signal_d == INIT_VALUE) ##1 (signal_d == INIT_VALUE)
    );

    // output_signal stays at INIT_VALUE for three clocks after a reset sample.
    check_output_stays_init_three_clocks_after_reset: assert property (
        @(posedge target_clk)
        reset |=> (output_signal == INIT_VALUE) ##1
                  (output_signal == INIT_VALUE) ##1
                  (output_signal == INIT_VALUE)
    );

endmodule

bind cdc_3ff cdc_3ff_sva #(
    .DATA_WIDTH(DATA_WIDTH),
    .INIT_VALUE(INIT_VALUE)
) cdc_3ff_sva_i (
    .target_clk(target_clk),
    .reset(reset),
    .input_signal(input_signal),
    .output_signal(output_signal),
    .signal_meta(signal_meta),
    .signal_d(signal_d)
);

rtl:
module bin2gray(
    input [2:0] bin_in,
    output [2:0] gray_out
);

// Implement the gray code conversion using behavioral modeling
assign gray_out[2] = bin_in[2];
assign gray_out[1] = bin_in[2] ^ bin_in[1];
assign gray_out[0] = bin_in[1] ^ bin_in[0];

endmodule

sva:
module bin2gray_sva (
    input logic       clk,
    input logic [2:0] bin_in,
    input logic [2:0] gray_out
);

    // gray_out[2] passes through the binary MSB.
    check_gray_msb_passthrough: assert property (
        @(posedge clk) gray_out[2] == bin_in[2]
    );

    // gray_out[1] is the XOR of bin_in[2] and bin_in[1].
    check_gray_bit1_xor: assert property (
        @(posedge clk) gray_out[1] == (bin_in[2] ^ bin_in[1])
    );

    // gray_out[0] is the XOR of bin_in[1] and bin_in[0].
    check_gray_bit0_xor: assert property (
        @(posedge clk) gray_out[0] == (bin_in[1] ^ bin_in[0])
    );

    // The full output matches the implemented binary-to-Gray conversion.
    check_gray_vector_conversion: assert property (
        @(posedge clk) gray_out == {bin_in[2], (bin_in[2] ^ bin_in[1]), (bin_in[1] ^ bin_in[0])}
    );

    // The Gray output reconstructs the original binary input.
    check_gray_inverse_reconstruction: assert property (
        @(posedge clk) bin_in == {gray_out[2], (gray_out[2] ^ gray_out[1]), (gray_out[2] ^ gray_out[1] ^ gray_out[0])}
    );

endmodule

rtl:
module ring_counter (
  input clk,
  output reg [m-1:0] out
);

parameter m = 4; // number of flip-flops in the counter

reg [m-1:0] counter;

always @(posedge clk) begin
  if (counter == {m{1'b1}}) begin
    counter <= {m{1'b0}};
  end else begin
    counter <= {counter[m-2:0], counter[m-1]};
  end
end

initial begin
    out <= 0;
end

always @* begin
    out = counter;
end

endmodule

sva:
module ring_counter_sva #(parameter int m = 4) (
    input logic clk,
    input logic [m-1:0] out
);

    localparam logic [m-1:0] ALL_ONES  = {m{1'b1}};
    localparam logic [m-1:0] ALL_ZEROS = {m{1'b0}};

    // An all-ones state clears to all zeros on the next clock.
    check_all_ones_wraps_to_zero: assert property (
        @(posedge clk) (out == ALL_ONES) |=> (out == ALL_ZEROS)
    );

    // An all-zero state remains all zero on the next clock.
    check_all_zero_holds: assert property (
        @(posedge clk) (out == ALL_ZEROS) |=> (out == ALL_ZEROS)
    );

    generate
        if (m > 1) begin : gen_multi_bit
            // On non-wrap cycles, bit 0 takes the previous MSB.
            check_lsb_wraparound: assert property (
                @(posedge clk) (out != ALL_ONES) |=> (out[0] == $past(out[m-1]))
            );

            for (genvar i = 1; i < m; i++) begin : gen_shift_bits
                // On non-wrap cycles, each upper bit takes the previous lower bit.
                check_shift_from_lower: assert property (
                    @(posedge clk) (out != ALL_ONES) |=> (out[i] == $past(out[i-1]))
                );
            end
        end else begin : gen_single_bit
            // A 1-bit instance always becomes zero after a clock edge.
            check_single_bit_clears: assert property (
                @(posedge clk) 1'b1 |=> (out == 1'b0)
            );
        end
    endgenerate

endmodule

rtl:
module counter_with_sum (
    input clk,
    input reset,      // Asynchronous active-high reset
    input [3:0] input1,
    input [3:0] input2,
    output [3:0] sum,
    output [3:0] counter_out);

    reg [3:0] counter;
    reg [3:0] input1_prev;
    reg [3:0] input2_prev;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            counter <= 4'b0000;
            input1_prev <= 4'b0000;
            input2_prev <= 4'b0000;
        end
        else begin
            counter <= counter + 1;
            if (counter == 4'b1111) begin
                counter <= 4'b0000;
            end

            input1_prev <= input1;
            input2_prev <= input2;
        end
    end

    assign sum = input1 + input2_prev;
    assign counter_out = counter;

endmodule

sva:
module counter_with_sum_sva (
    input logic       clk,
    input logic       reset,
    input logic [3:0] input1,
    input logic [3:0] input2,
    input logic [3:0] sum,
    input logic [3:0] counter_out
);

    // A sampled reset clears the counter by the next clock.
    check_counter_clears_after_reset: assert property (
        @(posedge clk) reset |=> (counter_out == 4'h0)
    );

    // A sampled reset clears the stored input2, so sum matches input1 next cycle.
    check_sum_matches_input1_after_reset: assert property (
        @(posedge clk) reset |=> (sum == input1)
    );

    // From any non-maximum value, the counter increments on the next active cycle.
    check_counter_increments_from_non_max: assert property (
        @(posedge clk) disable iff (reset)
        (counter_out != 4'hF) |=> (counter_out == ($past(counter_out) + 4'h1))
    );

    // From 4'hF, the counter wraps to zero on the next active cycle.
    check_counter_wraps_from_max: assert property (
        @(posedge clk) disable iff (reset)
        (counter_out == 4'hF) |=> (counter_out == 4'h0)
    );

    // On active cycles, sum uses the current input1 and the previous cycle's input2.
    check_sum_uses_previous_input2: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> (sum == (input1 + $past(input2)))
    );

endmodule

rtl:
module counter(input clk, reset, load, input [3:0] data, output reg [3:0] count);

    always @(posedge clk, negedge reset) begin
        if (~reset) begin
            count <= 4'b0000;
        end else if (load) begin
            count <= data;
        end else begin
            count <= count + 1;
        end
    end

endmodule

sva:
module counter_sva (
    input logic clk,
    input logic reset,
    input logic load,
    input logic [3:0] data,
    input logic [3:0] count
);

    // Active-low reset forces the counter to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) !reset |-> (count == 4'b0000)
    );

    // When load is high, count updates to the sampled data value.
    check_load_updates_count: assert property (
        @(posedge clk) disable iff (!reset)
        load |=> (count == $past(data))
    );

    // When load is low, count increments by one on the next cycle.
    check_increment_when_not_loading: assert property (
        @(posedge clk) disable iff (!reset)
        !load |=> (count == ($past(count) + 4'd1))
    );

    // Incrementing from 4'hF wraps the counter back to zero.
    check_wraps_from_max: assert property (
        @(posedge clk) disable iff (!reset)
        (!load && (count == 4'hF)) |=> (count == 4'h0)
    );

endmodule

module binary_counter_sva(
    input logic       clk,
    input logic       reset,
    input logic [3:0] out
);

    // A reset cycle clears the counter to zero.
    check_reset_clears_counter: assert property (
        @(posedge clk) reset |=> (out == 4'b0000)
    );

    // After reset deasserts, the next non-reset cycle counts from zero to one.
    check_first_count_after_reset: assert property (
        @(posedge clk) disable iff (reset)
        ($past(reset) == 1'b1) |=> (out == 4'b0001)
    );

    // In consecutive non-reset cycles, the counter increments by one.
    check_counter_increments: assert property (
        @(posedge clk) disable iff (reset)
        ($past(reset) == 1'b0) |-> (out == ($past(out) + 4'd1))
    );

    // The 4-bit counter wraps from 15 back to zero.
    check_counter_wraps: assert property (
        @(posedge clk) disable iff (reset)
        (($past(reset) == 1'b0) && ($past(out) == 4'hF)) |-> (out == 4'h0)
    );

endmodule

rtl:
module Chip_Decoder(
    input A9,A8,F,A3,A2,AEN,IORbar,IOWbar,
    output reg [3:0] CSbar,
    output reg Ebar,DIR
    );
    reg [1:0] A;
    parameter S0 = 0,S1 = 1,S2 = 2,S3 = 3;
    always @(A9 or A8 or AEN or F or IORbar or IOWbar)
    begin
        if((A9 == 1) & (A8 == 1) & (AEN == 0) & F & (IORbar != IOWbar))
            Ebar = 0;
        else
            Ebar = 1;
        if((IORbar == 0) & (IOWbar ==1))
            DIR = 0;
        else
            DIR = 1;
    end
    always @(A3 or A2)
    begin
        A = {A3,A2};
        case(A)
            S0 : CSbar = 4'b1110;
            S1 : CSbar = 4'b1101;
            S2 : CSbar = 4'b1011;
            S3 : CSbar = 4'b0111;
        endcase
    end
endmodule

sva:
module Chip_Decoder_sva(
    input logic clk,
    input logic A9,
    input logic A8,
    input logic F,
    input logic A3,
    input logic A2,
    input logic AEN,
    input logic IORbar,
    input logic IOWbar,
    input logic [3:0] CSbar,
    input logic Ebar,
    input logic DIR
);

    // Ebar is low only for the qualified decoded I/O access condition.
    check_ebar_low_on_qualified_access: assert property (
        @(posedge clk)
        ((A9 == 1'b1) & (A8 == 1'b1) & (AEN == 1'b0) & (F == 1'b1) & (IORbar != IOWbar)) |-> (Ebar == 1'b0)
    );

    // Ebar is high whenever the qualified decoded I/O access condition is false.
    check_ebar_high_without_qualified_access: assert property (
        @(posedge clk)
        !((A9 == 1'b1) & (A8 == 1'b1) & (AEN == 1'b0) & (F == 1'b1) & (IORbar != IOWbar)) |-> (Ebar == 1'b1)
    );

    // DIR is low only during an I/O read cycle.
    check_dir_low_on_read_cycle: assert property (
        @(posedge clk)
        ((IORbar == 1'b0) & (IOWbar == 1'b1)) |-> (DIR == 1'b0)
    );

    // DIR is high for all non-read combinations of IORbar and IOWbar.
    check_dir_high_otherwise: assert property (
        @(posedge clk)
        !((IORbar == 1'b0) & (IOWbar == 1'b1)) |-> (DIR == 1'b1)
    );

    // Address 00 selects CSbar[0] active low.
    check_csbar_decode_00: assert property (
        @(posedge clk)
        ((A3 == 1'b0) & (A2 == 1'b0)) |-> (CSbar == 4'b1110)
    );

    // Address 01 selects CSbar[1] active low.
    check_csbar_decode_01: assert property (
        @(posedge clk)
        ((A3 == 1'b0) & (A2 == 1'b1)) |-> (CSbar == 4'b1101)
    );

    // Address 10 selects CSbar[2] active low.
    check_csbar_decode_10: assert property (
        @(posedge clk)
        ((A3 == 1'b1) & (A2 == 1'b0)) |-> (CSbar == 4'b1011)
    );

    // Address 11 selects CSbar[3] active low.
    check_csbar_decode_11: assert property (
        @(posedge clk)
        ((A3 == 1'b1) & (A2 == 1'b1)) |-> (CSbar == 4'b0111)
    );

    // CSbar always has exactly one active-low chip select.
    check_csbar_one_active_low: assert property (
        @(posedge clk)
        $onehot(~CSbar)
    );

endmodule

rtl:
module adder(
    input [7:0] A,
    input [7:0] B,
    input Cin,
    output [7:0] S,
    output Cout
);

    assign {Cout, S} = A + B + Cin;

endmodule

sva:
module adder_sva (
    input logic clk,
    input logic [7:0] A,
    input logic [7:0] B,
    input logic Cin,
    input logic [7:0] S,
    input logic Cout
);

    // No RTL clock/reset; sample this combinational adder on an external clock.

    // Combined outputs must equal the 9-bit addition of A, B, and Cin.
    check_full_sum: assert property (
        @(posedge clk) {Cout, S} == ({1'b0, A} + {1'b0, B} + Cin)
    );

    // Sum bits must match the low 8 bits of the arithmetic result.
    check_sum_low_bits: assert property (
        @(posedge clk) S == (({1'b0, A} + {1'b0, B} + Cin)[7:0])
    );

    // Carry-out must match the top bit of the arithmetic result.
    check_carry_out: assert property (
        @(posedge clk) Cout == (({1'b0, A} + {1'b0, B} + Cin)[8])
    );

    // The least-significant sum bit must implement full-adder parity.
    check_lsb_parity: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0] ^ Cin)
    );

    // Stable inputs must produce stable outputs across samples.
    check_stable_inputs_hold_outputs: assert property (
        @(posedge clk) $stable({A, B, Cin}) |-> $stable({Cout, S})
    );

    // Output changes must be caused by an input change across samples.
    check_output_change_requires_input_change: assert property (
        @(posedge clk) !$stable({Cout, S}) |-> !$stable({A, B, Cin})
    );

endmodule

rtl:
module mux_2to1 (
    input A,
    input B,
    input S,
    output Y
);

    assign Y = (S == 1'b0) ? A : B;

endmodule

sva:
module mux_2to1_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic S,
    input logic Y
);

    // Output must match the implemented ternary mux expression.
    check_mux_function: assert property (
        @(posedge clk) Y === ((S == 1'b0) ? A : B)
    );

    // Select value 0 routes input A to the output.
    check_select_zero_routes_a: assert property (
        @(posedge clk) (S === 1'b0) |-> (Y === A)
    );

    // Select value 1 routes input B to the output.
    check_select_one_routes_b: assert property (
        @(posedge clk) (S === 1'b1) |-> (Y === B)
    );

    // Equal data inputs force the same value at the output.
    check_equal_inputs_propagate: assert property (
        @(posedge clk) (A === B) |-> (Y === A)
    );

    // Stable mux inputs keep the output stable.
    check_stable_inputs_keep_output_stable: assert property (
        @(posedge clk) ($stable(A) && $stable(B) && $stable(S)) |-> $stable(Y)
    );

endmodule

rtl:
module dual_edge_ff(input clk, input reset, input d, input select, output reg q);
    reg [1:0] ff_out;
    wire select_ff = select ? ff_out[1] : ff_out[0];

    always @(posedge clk) begin
        if (reset) begin
            ff_out <= 2'b0;
        end else begin
            ff_out <= {ff_out[0], d};
        end
    end

    always @(negedge clk) begin
        q <= select_ff;
    end
endmodule

sva:
module dual_edge_ff_sva (
    input logic       clk,
    input logic       reset,
    input logic       d,
    input logic       select,
    input logic       q,
    input logic [1:0] ff_out,
    input logic       select_ff
);

    // Reset clears both internal stages.
    check_ff_out_reset: assert property (
        @(posedge clk) reset |=> (ff_out == 2'b00)
    );

    // The low stage captures d on each rising edge.
    check_ff_out_lsb_captures_d: assert property (
        @(posedge clk) disable iff (reset) 1'b1 |=> (ff_out[0] == $past(d))
    );

    // The high stage shifts in the previous low stage.
    check_ff_out_msb_shifts_lsb: assert property (
        @(posedge clk) disable iff (reset) 1'b1 |=> (ff_out[1] == $past(ff_out[0]))
    );

    // select_ff reflects the selected internal stage.
    check_select_ff_mux: assert property (
        @(negedge clk) disable iff (reset) (select_ff == (select ? ff_out[1] : ff_out[0]))
    );

    // q captures select_ff on each falling edge.
    check_q_captures_select_ff: assert property (
        @(negedge clk) disable iff (reset) 1'b1 |=> (q == $past(select_ff))
    );

endmodule

module up_counter_sva (
    input logic       clock,
    input logic       reset,
    input logic [3:0] out
);

    // A high reset drives the counter to zero on the next clock.
    check_reset_clears_out: assert property (
        @(posedge clock) reset |=> (out == 4'b0000)
    );

    // On the first cycle after reset deasserts, the sampled counter value is zero.
    check_post_reset_zero: assert property (
        @(posedge clock) reset ##1 !reset |-> (out == 4'b0000)
    );

    // When not at 4'hF, the counter increments by one each cycle.
    check_count_increments: assert property (
        @(posedge clock) disable iff (reset)
        (out != 4'hF) |=> (out == ($past(out) + 4'd1))
    );

    // When at 4'hF, the counter wraps back to zero on the next cycle.
    check_count_wraps: assert property (
        @(posedge clock) disable iff (reset)
        (out == 4'hF) |=> (out == 4'h0)
    );

endmodule

rtl:
module decoder_4to16_pipeline (
    input [1:0] select,
    input en,
    input clk,
    output reg [15:0] out
);

reg [1:0] select_reg;
reg en_reg;

always @(posedge clk) begin
    select_reg <= select;
    en_reg <= en;
end

always @(posedge clk) begin
    if (en_reg == 0) begin
        case (select_reg)
            2'b00: out <= 16'b1111111111111110;
            2'b01: out <= 16'b1111111111111101;
            2'b10: out <= 16'b1111111111111011;
            2'b11: out <= 16'b1111111111110111;
        endcase;
    end else begin
        out <= 16'b1111111111111111;
    end
end

endmodule

sva:
module decoder_4to16_pipeline_assertions (
    input logic [1:0]  select,
    input logic        en,
    input logic        clk,
    input logic [15:0] out
);

    localparam [15:0] DEC_DISABLED = 16'hFFFF;
    localparam [15:0] DEC_SEL_00   = 16'hFFFE;
    localparam [15:0] DEC_SEL_01   = 16'hFFFD;
    localparam [15:0] DEC_SEL_10   = 16'hFFFB;
    localparam [15:0] DEC_SEL_11   = 16'hFFF7;

    // High enable drives all outputs high after the pipeline delay.
    check_enable_high_all_ones: assert property (
        @(posedge clk) en |-> ##2 (out == DEC_DISABLED)
    );

    // Low enable with select 00 clears bit 0 after the pipeline delay.
    check_decode_select_00: assert property (
        @(posedge clk) (!en && (select == 2'b00)) |-> ##2 (out == DEC_SEL_00)
    );

    // Low enable with select 01 clears bit 1 after the pipeline delay.
    check_decode_select_01: assert property (
        @(posedge clk) (!en && (select == 2'b01)) |-> ##2 (out == DEC_SEL_01)
    );

    // Low enable with select 10 clears bit 2 after the pipeline delay.
    check_decode_select_10: assert property (
        @(posedge clk) (!en && (select == 2'b10)) |-> ##2 (out == DEC_SEL_10)
    );

    // Low enable with select 11 clears bit 3 after the pipeline delay.
    check_decode_select_11: assert property (
        @(posedge clk) (!en && (select == 2'b11)) |-> ##2 (out == DEC_SEL_11)
    );

    // The upper 12 output bits are always high once the pipeline response appears.
    check_upper_bits_always_high: assert property (
        @(posedge clk) 1'b1 |-> ##2 (out[15:4] == 12'hFFF)
    );

    // Low enable produces exactly one active-low bit in the low nibble.
    check_low_enable_active_low_onehot: assert property (
        @(posedge clk) !en |-> ##2 ($onehot(~out[3:0]))
    );

    // Output is always one of the RTL-assigned encodings after the pipeline delay.
    check_output_encoding_legal: assert property (
        @(posedge clk) 1'b1 |-> ##2 (
            (out == DEC_DISABLED) ||
            (out == DEC_SEL_00)   ||
            (out == DEC_SEL_01)   ||
            (out == DEC_SEL_10)   ||
            (out == DEC_SEL_11)
        )
    );

endmodule

rtl:
module top_module (
    input clk,
    input reset,
    input [3:0] inputs, // 4-to-2 priority encoder inputs
    input up_down, // Up/Down input for the counter
    input load, // Load input for the counter
    input [3:0] D, // Input data for the counter
    output [3:0] Q // Output from the counter
);

wire [1:0] priority_encoder_output; // Output from the priority encoder

// Instantiate the 4-to-2 priority encoder module
priority_encoder priority_encoder_inst (
    .I(inputs),
    .O(priority_encoder_output)
);

// Instantiate the up/down counter module
up_down_counter up_down_counter_inst (
    .clk(clk),
    .reset(reset),
    .up_down(up_down),
    .load(load),
    .D(D), // Connect the input data to the input of the counter
    .Q(Q)
);

endmodule
module priority_encoder (
    input [3:0] I,
    output reg [1:0] O
);

    always @(*) begin
        case (I)
            4'b0001: O = 2'b01;
            4'b0010: O = 2'b10;
            4'b0100: O = 2'b11;
            default: O = 2'b00;
        endcase
    end

endmodule
module up_down_counter (
    input clk,
    input reset,
    input up_down,
    input load,
    input [3:0] D,
    output reg [3:0] Q
);

    always @(posedge clk) begin
        if (reset) begin
            Q <= 4'b0000;
        end else if (load) begin
            Q <= D;
        end else if (up_down) begin
            Q <= Q + 4'b0001;
        end else begin
            Q <= Q - 4'b0001;
        end
    end

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic reset,
    input logic [3:0] inputs,
    input logic up_down,
    input logic load,
    input logic [3:0] D,
    input logic [3:0] Q,
    input logic [1:0] priority_encoder_output
);

    // inputs 0001 must produce encoder output 01.
    check_encoder_map_0001: assert property (
        @(posedge clk) disable iff (reset)
        (inputs == 4'b0001) |-> (priority_encoder_output == 2'b01)
    );

    // inputs 0010 must produce encoder output 10.
    check_encoder_map_0010: assert property (
        @(posedge clk) disable iff (reset)
        (inputs == 4'b0010) |-> (priority_encoder_output == 2'b10)
    );

    // inputs 0100 must produce encoder output 11.
    check_encoder_map_0100: assert property (
        @(posedge clk) disable iff (reset)
        (inputs == 4'b0100) |-> (priority_encoder_output == 2'b11)
    );

    // All other input patterns must produce encoder output 00.
    check_encoder_default_map: assert property (
        @(posedge clk) disable iff (reset)
        !(inputs == 4'b0001 || inputs == 4'b0010 || inputs == 4'b0100) |-> (priority_encoder_output == 2'b00)
    );

    // A reset on this clock edge clears Q on the following sampled cycle.
    check_counter_reset_clears_q: assert property (
        @(posedge clk)
        reset |=> (Q == 4'b0000)
    );

    // When load is asserted out of reset, Q captures D.
    check_counter_load_captures_d: assert property (
        @(posedge clk) disable iff (reset)
        load |=> (Q == $past(D))
    );

    // When not loading and counting up, Q increments by one.
    check_counter_counts_up: assert property (
        @(posedge clk) disable iff (reset)
        (!load && up_down) |=> (Q == ($past(Q) + 4'b0001))
    );

    // When not loading and counting down, Q decrements by one.
    check_counter_counts_down: assert property (
        @(posedge clk) disable iff (reset)
        (!load && !up_down) |=> (Q == ($past(Q) - 4'b0001))
    );

endmodule

bind top_module top_module_sva top_module_sva_i (
    .clk(clk),
    .reset(reset),
    .inputs(inputs),
    .up_down(up_down),
    .load(load),
    .D(D),
    .Q(Q),
    .priority_encoder_output(priority_encoder_output)
);

rtl:
module binary_adder(
  input [3:0] A,
  input [3:0] B,
  output [3:0] S,
  output C_out
);

  wire [3:0] carry;

  wire [4:0] S_temp;
  assign S_temp = A + B;
  assign carry = (S_temp[4] == 1) ? 1 : 0;
  assign C_out = carry;
  assign S = S_temp[3:0];

endmodule

sva:
module binary_adder_sva (
    input logic        clk,
    input logic [3:0]  A,
    input logic [3:0]  B,
    input logic [3:0]  S,
    input logic        C_out
);

    // Full output matches the 5-bit sum of A and B.
    check_full_sum_match: assert property (
        @(posedge clk) {C_out, S} == ({1'b0, A} + {1'b0, B})
    );

    // Sum output matches the low 4 bits of the addition.
    check_sum_bits_match: assert property (
        @(posedge clk) S == ({1'b0, A} + {1'b0, B})[3:0]
    );

    // Carry output matches the high bit of the addition.
    check_carry_out_match: assert property (
        @(posedge clk) C_out == ({1'b0, A} + {1'b0, B})[4]
    );

    // Zero on A passes B through with no carry.
    check_a_zero_passthrough: assert property (
        @(posedge clk) (A == 4'h0) |-> ({C_out, S} == {1'b0, B})
    );

    // Zero on B passes A through with no carry.
    check_b_zero_passthrough: assert property (
        @(posedge clk) (B == 4'h0) |-> ({C_out, S} == {1'b0, A})
    );

    // Max plus max produces 0xE with carry asserted.
    check_max_plus_max: assert property (
        @(posedge clk) ((A == 4'hF) && (B == 4'hF)) |-> ((S == 4'hE) && (C_out == 1'b1))
    );

endmodule

rtl:
module sequence_detector (
  input inp,
  output reg out
);

parameter n = 4; // length of shift register
parameter seq = "1100"; // desired input sequence (binary string)

reg [n-1:0] shift_reg; // shift register

// Define the predefined states that correspond to the desired input sequence
parameter [n-1:0] state_1 = 4'b0011;
parameter [n-1:0] state_2 = 4'b0110;
parameter [n-1:0] state_3 = 4'b1100;
parameter [n-1:0] state_4 = 4'b1001;

always @(posedge inp) begin
  // Shift the input into the shift register
  shift_reg <= {shift_reg[n-2:0], inp};

  // Compare the current state of the shift register to the predefined states
  if (shift_reg == state_1 || shift_reg == state_2 || shift_reg == state_3 || shift_reg == state_4) begin
    out <= 1'b1; // Output a logic 1 if the current state matches one of the predefined states
  end else begin
    out <= 1'b0; // Output a logic 0 otherwise
  end
end

endmodule

sva:
module sequence_detector_sva #(parameter int n = 4) (
    input logic inp,
    input logic out,
    input logic [n-1:0] shift_reg
);

    localparam logic [n-1:0] state_1 = 4'b0011;
    localparam logic [n-1:0] state_2 = 4'b0110;
    localparam logic [n-1:0] state_3 = 4'b1100;
    localparam logic [n-1:0] state_4 = 4'b1001;

    // The sampled shift register is the previous sampled value shifted in with a 1.
    check_shift_reg_update: assert property (
        @(posedge inp)
        ($past(1'b1) === 1'b1) |-> (shift_reg == {$past(shift_reg[n-2:0]), 1'b1})
    );

    // After one prior inp edge, the LSB of the register is set.
    check_shift_reg_lsb_one: assert property (
        @(posedge inp)
        ($past(1'b1) === 1'b1) |-> (shift_reg[0] == 1'b1)
    );

    // After two prior inp edges, the two LSBs of the register are set.
    check_shift_reg_two_lsbs_one: assert property (
        @(posedge inp)
        ($past(1'b1, 2) === 1'b1) |-> (shift_reg[1:0] == 2'b11)
    );

    // After three prior inp edges, the three LSBs of the register are set.
    check_shift_reg_three_lsbs_one: assert property (
        @(posedge inp)
        ($past(1'b1, 3) === 1'b1) |-> (shift_reg[2:0] == 3'b111)
    );

    // After four prior inp edges, the register is all ones.
    check_shift_reg_all_ones: assert property (
        @(posedge inp)
        ($past(1'b1, 4) === 1'b1) |-> (shift_reg == 4'b1111)
    );

    // A matching prior shift register state drives out high on the next sampled edge.
    check_out_high_on_matching_prior_state: assert property (
        @(posedge inp)
        (($past(1'b1) === 1'b1) &&
         (($past(shift_reg) == state_1) ||
          ($past(shift_reg) == state_2) ||
          ($past(shift_reg) == state_3) ||
          ($past(shift_reg) == state_4))) |-> (out == 1'b1)
    );

    // A non-matching prior shift register state drives out low on the next sampled edge.
    check_out_low_on_nonmatching_prior_state: assert property (
        @(posedge inp)
        (($past(1'b1) === 1'b1) &&
         !(($past(shift_reg) == state_1) ||
           ($past(shift_reg) == state_2) ||
           ($past(shift_reg) == state_3) ||
           ($past(shift_reg) == state_4))) |-> (out == 1'b0)
    );

    // After three prior inp edges, the current register value cannot match any listed state.
    check_no_state_match_after_three_edges: assert property (
        @(posedge inp)
        ($past(1'b1, 3) === 1'b1) |-> !((shift_reg == state_1) ||
                                        (shift_reg == state_2) ||
                                        (shift_reg == state_3) ||
                                        (shift_reg == state_4))
    );

    // After four prior inp edges, the output must be low.
    check_out_low_after_four_edges: assert property (
        @(posedge inp)
        ($past(1'b1, 4) === 1'b1) |-> (out == 1'b0)
    );

endmodule

rtl:
module pio_egmenable (
                       // inputs:
                        address,
                        chipselect,
                        clk,
                        reset_n,
                        write_n,
                        writedata,

                       // outputs:
                        out_port,
                        readdata
                     )
;

  output           out_port;
  output           readdata;
  input   [  1: 0] address;
  input            chipselect;
  input            clk;
  input            reset_n;
  input            write_n;
  input            writedata;

  wire             clk_en;
  reg              data_out;
  wire             out_port;
  wire             read_mux_out;
  wire             readdata;

  // clock enable
  assign clk_en = 1;

  // read multiplexer
  assign read_mux_out = {1 {(address == 0)}} & data_out;

  // data_out register
  always @(posedge clk or negedge reset_n)
    begin
      if (reset_n == 0)
          data_out <= 0;
      else if (chipselect && ~write_n && (address == 0))
          data_out <= writedata;
    end

  // out_port output
  assign out_port = data_out;

  // readdata output
  assign readdata = read_mux_out;

endmodule

sva:
module pio_egmenable_sva (
    input logic [1:0] address,
    input logic       chipselect,
    input logic       clk,
    input logic       reset_n,
    input logic       write_n,
    input logic       writedata,
    input logic       out_port,
    input logic       readdata
);

    // Reset clears the stored output and therefore the readback value.
    check_reset_clears_outputs: assert property (
        @(posedge clk) !reset_n |-> (out_port == 1'b0) && (readdata == 1'b0)
    );

    // Address 0 reads back the stored output bit.
    check_read_addr0_returns_out_port: assert property (
        @(posedge clk) disable iff (!reset_n)
        (address == 2'b00) |-> (readdata == out_port)
    );

    // Any nonzero address reads back zero.
    check_read_nonzero_addr_returns_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (address != 2'b00) |-> (readdata == 1'b0)
    );

    // A selected write to address 0 updates the output on the next clock.
    check_write_addr0_updates_out_port: assert property (
        @(posedge clk) disable iff (!reset_n)
        (chipselect && !write_n && (address == 2'b00)) |=> (out_port == $past(writedata))
    );

    // Without a selected write to address 0, the output register holds its value.
    check_no_target_write_holds_out_port: assert property (
        @(posedge clk) disable iff (!reset_n)
        !(chipselect && !write_n && (address == 2'b00)) |=> (out_port == $past(out_port))
    );

    // Writes to nonzero addresses do not modify the output register.
    check_nonzero_address_write_is_ignored: assert property (
        @(posedge clk) disable iff (!reset_n)
        (chipselect && !write_n && (address != 2'b00)) |=> (out_port == $past(out_port))
    );

endmodule

rtl:
module shift_addsub (
    input clk,
    input reset,
    input SER,
    input [3:0] A,
    input [3:0] B,
    input sub,
    output [3:0] result
);

    reg [3:0] Q;
    wire [3:0] shifted_Q;
    wire [3:0] added_A;
    wire [3:0] subbed_A;

    shift_register shift_reg (
        .clk(clk),
        .reset(reset),
        .SER(SER),
        .SHIFT(shifted_Q),
        .LOAD(Q)
    );

    adder_subtractor addsub (
        .A(A),
        .B(shifted_Q),
        .sub(sub),
        .result(added_A),
        .sub_result(subbed_A)
    );

    always @(posedge clk or posedge reset)
    begin
        if (reset)
            Q <= 4'b0;
        else
            Q <= subbed_A;
    end

    assign result = (sub) ? subbed_A : added_A;

endmodule
module shift_register (
    input clk,
    input reset,
    input SER,
    output reg [3:0] SHIFT,
    input [3:0] LOAD
);

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            SHIFT <= 4'b0;
        end else begin
            SHIFT <= LOAD;
        end
    end

endmodule
module adder_subtractor (
    input [3:0] A,
    input [3:0] B,
    input sub,
    output [3:0] result,
    output [3:0] sub_result
);

    wire [3:0] subbed_A;
    wire [3:0] subtracted_result;

    assign subbed_A = (~A) + 1;
    assign subtracted_result = subbed_A + B;

    assign sub_result = subtracted_result[3:0];
    assign result = sub ? subtracted_result[3:0] : A + B;
endmodule

sva:
module shift_addsub_sva (
    input logic clk,
    input logic reset,
    input logic SER,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic sub,
    input logic [3:0] result,
    input logic [3:0] Q,
    input logic [3:0] shifted_Q,
    input logic [3:0] added_A,
    input logic [3:0] subbed_A
);

    // Reset clears the Q register.
    check_reset_clears_q: assert property (
        @(posedge clk) reset |-> (Q == 4'h0)
    );

    // Reset clears the shift register output.
    check_reset_clears_shifted_q: assert property (
        @(posedge clk) reset |-> (shifted_Q == 4'h0)
    );

    // The subtraction path computes shifted_Q minus A.
    check_subbed_a_difference: assert property (
        @(posedge clk) disable iff (reset)
        subbed_A == (shifted_Q - A)
    );

    // The add/sub output selects subtraction or addition based on sub.
    check_added_a_select: assert property (
        @(posedge clk) disable iff (reset)
        added_A == (sub ? subbed_A : (A + shifted_Q))
    );

    // The top-level result mux selects subbed_A or added_A.
    check_result_mux: assert property (
        @(posedge clk) disable iff (reset)
        result == (sub ? subbed_A : added_A)
    );

    // In subtract mode, result is shifted_Q minus A.
    check_result_sub_mode: assert property (
        @(posedge clk) disable iff (reset)
        sub |-> (result == (shifted_Q - A))
    );

    // In add mode, result is A plus shifted_Q.
    check_result_add_mode: assert property (
        @(posedge clk) disable iff (reset)
        !sub |-> (result == (A + shifted_Q))
    );

    // During reset, the subtraction path reduces to 0 minus A.
    check_reset_subbed_a_value: assert property (
        @(posedge clk) reset |-> (subbed_A == (4'h0 - A))
    );

    // During reset, result uses a zero shifted input.
    check_reset_result_value: assert property (
        @(posedge clk) reset |-> (result == (sub ? (4'h0 - A) : A))
    );

    // The top-level B input does not affect the datapath outputs.
    check_b_unused: assert property (
        @(posedge clk) disable iff (reset)
        ($changed(B) && $stable({A, sub, shifted_Q})) |-> $stable({subbed_A, added_A, result})
    );

    // SER does not affect the datapath outputs in this implementation.
    check_ser_unused: assert property (
        @(posedge clk) disable iff (reset)
        ($changed(SER) && $stable({A, sub, shifted_Q})) |-> $stable({subbed_A, added_A, result})
    );

endmodule

rtl:
module mux(opA,opB,sum,dsp_sel,out);
	input [3:0] opA,opB;
	input [4:0] sum;
	input [1:0] dsp_sel;
	output [3:0] out;

	reg [3:0] out;
	reg [3:0] temp_out;
	reg [3:0] opA_out;
	reg [3:0] opB_out;
	reg [3:0] sum_out;
	reg [3:0] cout_out;

	always @ (sum)
		begin
			if (sum[4] == 1)
				cout_out <= 4'b0001;
			else
				cout_out <= 4'b0000;
		end

	always @ (opA)
		begin
			opA_out <= opA;
		end

	always @ (opB)
		begin
			opB_out <= opB;
		end

	always @ (sum)
		begin
			sum_out <= sum[3:0];
		end

	always @ (dsp_sel, sum_out, cout_out, opB_out, opA_out)
		begin
			case (dsp_sel)
				2'b00: temp_out = sum_out;
				2'b01: temp_out = cout_out;
				2'b10: temp_out = opB_out;
				2'b11: temp_out = opA_out;
			endcase
			out <= temp_out;
		end

endmodule

sva:
module mux_sva (
    input logic        clk,
    input logic [3:0]  opA,
    input logic [3:0]  opB,
    input logic [4:0]  sum,
    input logic [1:0]  dsp_sel,
    input logic [3:0]  out,
    input logic [3:0]  opA_out,
    input logic [3:0]  opB_out,
    input logic [3:0]  sum_out,
    input logic [3:0]  cout_out
);

    // opA_out captures opA when opA changes.
    check_opa_mirror_updates: assert property (
        @(posedge clk) $changed(opA) |-> (opA_out == opA)
    );

    // opB_out captures opB when opB changes.
    check_opb_mirror_updates: assert property (
        @(posedge clk) $changed(opB) |-> (opB_out == opB)
    );

    // sum_out captures the low 4 bits of sum when sum changes.
    check_sum_low_mirror_updates: assert property (
        @(posedge clk) $changed(sum) |-> (sum_out == sum[3:0])
    );

    // cout_out encodes sum[4] into bit 0 when sum changes.
    check_sum_carry_mirror_updates: assert property (
        @(posedge clk) $changed(sum) |-> (cout_out == {3'b000, sum[4]})
    );

    // out selects sum_out on mux activity with dsp_sel = 00.
    check_out_selects_sum_path: assert property (
        @(posedge clk)
        (($changed(dsp_sel) || $changed(sum_out) || $changed(cout_out) ||
          $changed(opB_out) || $changed(opA_out)) && (dsp_sel == 2'b00))
        |-> (out == sum_out)
    );

    // out selects cout_out on mux activity with dsp_sel = 01.
    check_out_selects_carry_path: assert property (
        @(posedge clk)
        (($changed(dsp_sel) || $changed(sum_out) || $changed(cout_out) ||
          $changed(opB_out) || $changed(opA_out)) && (dsp_sel == 2'b01))
        |-> (out == cout_out)
    );

    // out selects opB_out on mux activity with dsp_sel = 10.
    check_out_selects_opb_path: assert property (
        @(posedge clk)
        (($changed(dsp_sel) || $changed(sum_out) || $changed(cout_out) ||
          $changed(opB_out) || $changed(opA_out)) && (dsp_sel == 2'b10))
        |-> (out == opB_out)
    );

    // out selects opA_out on mux activity with dsp_sel = 11.
    check_out_selects_opa_path: assert property (
        @(posedge clk)
        (($changed(dsp_sel) || $changed(sum_out) || $changed(cout_out) ||
          $changed(opB_out) || $changed(opA_out)) && (dsp_sel == 2'b11))
        |-> (out == opA_out)
    );

    // out holds its value when no mux sensitivity input changes.
    check_out_holds_without_mux_activity: assert property (
        @(posedge clk)
        !($changed(dsp_sel) || $changed(sum_out) || $changed(cout_out) ||
          $changed(opB_out) || $changed(opA_out))
        |-> $stable(out)
    );

endmodule

