module rs232in
   (input  wire        clock,

    input  wire        serial_in,
    output reg         attention = 0,
    output reg   [7:0] received_data = 0);

   parameter           bps        =     57_600;
   parameter           frequency  = 25_000_000;
   parameter           period     = (frequency + bps/2) / bps;

   reg  [16:0] ttyclk       = 0;
   wire [31:0] ttyclk_bit   = period - 2;
   wire [31:0] ttyclk_start = (3 * period) / 2 - 2;
   reg  [ 7:0] shift_in     = 0;
   reg  [ 4:0] count        = 0;

   reg         rxd          = 0;
   reg         rxd2         = 0;


   always @(posedge clock) begin
      attention <= 0;

      {rxd2,rxd} <= {rxd,serial_in};

      if (~ttyclk[16]) begin
         ttyclk <= ttyclk - 1'd1;
      end else if (count) begin
         if (count == 1) begin
            received_data <= {rxd2, shift_in[7:1]};
            attention     <= 1;
         end

         count       <= count - 1'd1;
         shift_in    <= {rxd2, shift_in[7:1]}; ttyclk      <= ttyclk_bit[16:0];
      end else if (~rxd2) begin
         ttyclk      <= ttyclk_start[16:0];
         count       <= 8;
      end
   end
endmodule

sva:
module rs232in_sva (
    input logic        clock,
    input logic        serial_in,
    input logic        attention,
    input logic [7:0]  received_data,
    input logic [16:0] ttyclk,
    input logic [31:0] ttyclk_bit,
    input logic [31:0] ttyclk_start,
    input logic [7:0]  shift_in,
    input logic [4:0]  count,
    input logic        rxd,
    input logic        rxd2
);

    // The two-stage input synchronizer shifts serial_in through rxd and rxd2.
    check_input_synchronizer: assert property (
        @(posedge clock)
        1'b1 |=> (rxd == $past(serial_in)) &&
                 (rxd2 == $past(rxd))
    );

    // While the timer is active, only ttyclk decrements and attention stays low.
    check_ttyclk_countdown: assert property (
        @(posedge clock)
        (!ttyclk[16]) |=> (ttyclk == ($past(ttyclk) - 17'd1)) &&
                          (count == $past(count)) &&
                          (shift_in == $past(shift_in)) &&
                          (received_data == $past(received_data)) &&
                          !attention
    );

    // On each non-final sample, the shift register captures rxd2 and count decrements.
    check_bit_sample_nonfinal: assert property (
        @(posedge clock)
        (ttyclk[16] && (count > 5'd1)) |=> (ttyclk == $past(ttyclk_bit[16:0])) &&
                                           (count == ($past(count) - 5'd1)) &&
                                           (shift_in == {$past(rxd2), $past(shift_in[7:1])}) &&
                                           (received_data == $past(received_data)) &&
                                           !attention
    );

    // On the final sample, the last shifted byte is presented and attention is asserted.
    check_bit_sample_final: assert property (
        @(posedge clock)
        (ttyclk[16] && (count == 5'd1)) |=> (ttyclk == $past(ttyclk_bit[16:0])) &&
                                            (count == 5'd0) &&
                                            (shift_in == {$past(rxd2), $past(shift_in[7:1])}) &&
                                            (received_data == {$past(rxd2), $past(shift_in[7:1])}) &&
                                            attention
    );

    // A low rxd2 when idle starts a new receive window and loads count with 8.
    check_start_bit_detect: assert property (
        @(posedge clock)
        (ttyclk[16] && (count == 5'd0) && !rxd2) |=> (ttyclk == $past(ttyclk_start[16:0])) &&
                                                    (count == 5'd8) &&
                                                    (shift_in == $past(shift_in)) &&
                                                    (received_data == $past(received_data)) &&
                                                    !attention
    );

    // When idle and no start bit is seen, the receiver state holds and attention stays low.
    check_idle_hold: assert property (
        @(posedge clock)
        (ttyclk[16] && (count == 5'd0) && rxd2) |=> (ttyclk == $past(ttyclk)) &&
                                                   (count == $past(count)) &&
                                                   (shift_in == $past(shift_in)) &&
                                                   (received_data == $past(received_data)) &&
                                                   !attention
    );

    // Attention is asserted exactly when the prior cycle sampled the final bit.
    check_attention_update: assert property (
        @(posedge clock)
        1'b1 |=> (attention == ($past(ttyclk[16]) && ($past(count) == 5'd1)))
    );

    // received_data changes only on the final bit sample and otherwise holds its value.
    check_received_data_update: assert property (
        @(posedge clock)
        1'b1 |=> (($past(ttyclk[16]) && ($past(count) == 5'd1)) ?
                  (received_data == {$past(rxd2), $past(shift_in[7:1])}) :
                  (received_data == $past(received_data)))
    );

endmodule

rtl:
module full_adder(input A, input B, input Cin, output S, output Cout);
    wire w1, w2, w3;
    assign w1 = A ^ B;
    assign w2 = A & B;
    assign w3 = w2 | (Cin & w1);
    assign S = w1 ^ Cin;
    assign Cout = w3;
endmodule

module adder_8bit(input [7:0] A, input [7:0] B, output [7:0] S, output Cout);
    wire [7:0] w1, w2, w3, w4, w5, w6, w7, w8;
    full_adder fa0(.A(A[0]), .B(B[0]), .Cin(1'b0), .S(w1[0]), .Cout(w2[0]));
    full_adder fa1(.A(A[1]), .B(B[1]), .Cin(w2[0]), .S(w1[1]), .Cout(w2[1]));
    full_adder fa2(.A(A[2]), .B(B[2]), .Cin(w2[1]), .S(w1[2]), .Cout(w2[2]));
    full_adder fa3(.A(A[3]), .B(B[3]), .Cin(w2[2]), .S(w1[3]), .Cout(w2[3]));
    full_adder fa4(.A(A[4]), .B(B[4]), .Cin(w2[3]), .S(w1[4]), .Cout(w2[4]));
    full_adder fa5(.A(A[5]), .B(B[5]), .Cin(w2[4]), .S(w1[5]), .Cout(w2[5]));
    full_adder fa6(.A(A[6]), .B(B[6]), .Cin(w2[5]), .S(w1[6]), .Cout(w2[6]));
    full_adder fa7(.A(A[7]), .B(B[7]), .Cin(w2[6]), .S(w1[7]), .Cout(w2[7]));
    assign S = {w1[7], w1[6], w1[5], w1[4], w1[3], w1[2], w1[1], w1[0]};
    assign Cout = w2[7];
endmodule

sva:
module adder_8bit_sva (
    input logic        clk,
    input logic [7:0]  A,
    input logic [7:0]  B,
    input logic [7:0]  S,
    input logic        Cout
);

    // Sampling clock for the combinational DUT; no reset exists in the RTL.

    // Entire 9-bit result must match the unsigned sum of A and B.
    check_total_sum: assert property (
        @(posedge clk) {Cout, S} == ({1'b0, A} + {1'b0, B})
    );

    // Bit 0 sum is XOR because the first carry-in is tied low.
    check_lsb_sum: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0])
    );

    // Bit 1 sum must include the carry generated by bit 0.
    check_bit1_ripple_sum: assert property (
        @(posedge clk) S[1] == (A[1] ^ B[1] ^ (A[0] & B[0]))
    );

    // Adding zero on A must pass B through with no carry.
    check_a_zero_passthrough: assert property (
        @(posedge clk) (A == 8'h00) |-> ({Cout, S} == {1'b0, B})
    );

    // Adding zero on B must pass A through with no carry.
    check_b_zero_passthrough: assert property (
        @(posedge clk) (B == 8'h00) |-> ({Cout, S} == {1'b0, A})
    );

    // Carry-out must indicate overflow of the 8-bit addition.
    check_carry_out: assert property (
        @(posedge clk) Cout == (({1'b0, A} + {1'b0, B}) > 9'h0FF)
    );

endmodule

module mux_2_to_1_sva (
    input logic clk,
    input logic data_in_0,
    input logic data_in_1,
    input logic select,
    input logic data_out
);

    // Output must implement the 2:1 mux expression.
    check_mux_function: assert property (
        @(posedge clk) data_out == (select ? data_in_1 : data_in_0)
    );

    // When select is low, output must follow data_in_0.
    check_select_low_path: assert property (
        @(posedge clk) !select |-> (data_out == data_in_0)
    );

    // When select is high, output must follow data_in_1.
    check_select_high_path: assert property (
        @(posedge clk) select |-> (data_out == data_in_1)
    );

    // If both inputs are equal, output must equal that shared value.
    check_equal_inputs_consistent_output: assert property (
        @(posedge clk) (data_in_0 == data_in_1) |-> (data_out == data_in_0)
    );

endmodule

