module and_gate (
    input a,
    input b,
    output y
);

    assign y = a & b;

endmodule

module a31oi_2 (
    output Y,
    input A1,
    input A2,
    input A3,
    input B1
);

    wire y1, y2;
    and_gate base (
        .a(A1),
        .b(A2),
        .y(y1)
    );

    and_gate second (
        .a(y1),
        .b(A3),
        .y(y2)
    );

    assign Y = ~(y2 | B1); 

endmodule

sva:
module a31oi_2_sva (
    input logic Y,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic B1
);

    // No clock or reset exists in the RTL; sample on the formal global clock.

    // Checks the exact implemented A31OI function.
    check_full_function: assert property (
        @($global_clock) Y == ~(((A1 & A2) & A3) | B1)
    );

    // B1 high forces the output low.
    check_b1_forces_low: assert property (
        @($global_clock) B1 |-> !Y
    );

    // All three A inputs high force the output low.
    check_all_a_high_forces_low: assert property (
        @($global_clock) (A1 && A2 && A3) |-> !Y
    );

    // With B1 low, the output is the inverse of the 3-input AND.
    check_b1_low_reduces_to_nand3: assert property (
        @($global_clock) (!B1) |-> (Y == ~(A1 & A2 & A3))
    );

    // If any A input is low, the output must equal ~B1.
    check_any_a_low_reduces_to_not_b1: assert property (
        @($global_clock) (!A1 || !A2 || !A3) |-> (Y == ~B1)
    );

    // B1 low and any A input low produce a high output.
    check_b1_low_and_any_a_low_yields_high: assert property (
        @($global_clock) (!B1 && (!A1 || !A2 || !A3)) |-> Y
    );

    // A high output means B1 is low and not all A inputs are high.
    check_y_high_characterization: assert property (
        @($global_clock) Y |-> (!B1 && (!A1 || !A2 || !A3))
    );

    // A low output means B1 is high or all A inputs are high.
    check_y_low_characterization: assert property (
        @($global_clock) (!Y) |-> (B1 || (A1 && A2 && A3))
    );

endmodule

rtl:
module bitwise_op (
    input [15:0] in1,
    input [15:0] in2,
    input [15:0] in3,
    input [15:0] in4,
    input reset,
    output reg [15:0] out1,
    output reg [15:0] out2
);

    always @(*) begin
        if (reset) begin
            out1 <= 16'b0;
            out2 <= 16'b0;
        end else begin
            out1 <= in1 & in2;
            out2 <= in3 ^ in4;
        end
    end

endmodule

sva:
module bitwise_op_sva (
    input logic [15:0] in1,
    input logic [15:0] in2,
    input logic [15:0] in3,
    input logic [15:0] in4,
    input logic        reset,
    input logic [15:0] out1,
    input logic [15:0] out2
);

    // No explicit RTL clock; sample on the formal global clock.
    // reset is active high and the RTL is purely combinational.

    // Reset forces both outputs to zero.
    check_reset_clears_outputs: assert property (
        @($global_clock) reset |-> ((out1 == 16'h0000) && (out2 == 16'h0000))
    );

    // Outside reset, out1 is the bitwise AND of in1 and in2.
    check_out1_bitwise_and: assert property (
        @($global_clock) disable iff (reset) (out1 == (in1 & in2))
    );

    // Outside reset, out2 is the bitwise XOR of in3 and in4.
    check_out2_bitwise_xor: assert property (
        @($global_clock) disable iff (reset) (out2 == (in3 ^ in4))
    );

    // Outside reset, a zero AND operand forces out1 to zero.
    check_out1_zero_when_operand_zero: assert property (
        @($global_clock) disable iff (reset)
        ((in1 == 16'h0000) || (in2 == 16'h0000)) |-> (out1 == 16'h0000)
    );

    // Outside reset, an all-ones AND operand passes the other operand through.
    check_out1_passthrough_when_operand_all_ones: assert property (
        @($global_clock) disable iff (reset)
        ((in1 == 16'hFFFF) || (in2 == 16'hFFFF)) |->
        (((in1 != 16'hFFFF) || (out1 == in2)) &&
         ((in2 != 16'hFFFF) || (out1 == in1)))
    );

    // Outside reset, equal XOR operands force out2 to zero.
    check_out2_zero_when_operands_equal: assert property (
        @($global_clock) disable iff (reset)
        (in3 == in4) |-> (out2 == 16'h0000)
    );

    // Outside reset, a zero XOR operand passes the other operand through.
    check_out2_passthrough_when_operand_zero: assert property (
        @($global_clock) disable iff (reset)
        ((in3 == 16'h0000) || (in4 == 16'h0000)) |->
        (((in3 != 16'h0000) || (out2 == in4)) &&
         ((in4 != 16'h0000) || (out2 == in3)))
    );

endmodule

module wasca_nios2_gen2_0_cpu_nios2_oci_td_mode_sva (
    input logic [8:0] ctrl,
    input logic [3:0] td_mode
);

    // ctrl 0 selects no trace.
    check_ctrl_0_maps_no_trace: assert property (
        @($global_clock) (ctrl == 9'b000000000) |-> (td_mode == 4'b0000)
    );

    // ctrl 1 selects record load address.
    check_ctrl_1_maps_load_address: assert property (
        @($global_clock) (ctrl == 9'b000000001) |-> (td_mode == 4'b0001)
    );

    // ctrl 2 selects record store address.
    check_ctrl_2_maps_store_address: assert property (
        @($global_clock) (ctrl == 9'b000000010) |-> (td_mode == 4'b0010)
    );

    // ctrl 3 selects record load data.
    check_ctrl_3_maps_load_data: assert property (
        @($global_clock) (ctrl == 9'b000000011) |-> (td_mode == 4'b0011)
    );

    // ctrl 4 selects record store data.
    check_ctrl_4_maps_store_data: assert property (
        @($global_clock) (ctrl == 9'b000000100) |-> (td_mode == 4'b0100)
    );

    // All other ctrl values select no trace.
    check_other_ctrl_values_map_no_trace: assert property (
        @($global_clock)
        !((ctrl == 9'b000000000) ||
          (ctrl == 9'b000000001) ||
          (ctrl == 9'b000000010) ||
          (ctrl == 9'b000000011) ||
          (ctrl == 9'b000000100))
        |-> (td_mode == 4'b0000)
    );

    // td_mode 1 only comes from ctrl 1.
    check_td_mode_1_has_unique_ctrl: assert property (
        @($global_clock) (td_mode == 4'b0001) |-> (ctrl == 9'b000000001)
    );

    // td_mode 2 only comes from ctrl 2.
    check_td_mode_2_has_unique_ctrl: assert property (
        @($global_clock) (td_mode == 4'b0010) |-> (ctrl == 9'b000000010)
    );

    // td_mode 3 only comes from ctrl 3.
    check_td_mode_3_has_unique_ctrl: assert property (
        @($global_clock) (td_mode == 4'b0011) |-> (ctrl == 9'b000000011)
    );

    // td_mode 4 only comes from ctrl 4.
    check_td_mode_4_has_unique_ctrl: assert property (
        @($global_clock) (td_mode == 4'b0100) |-> (ctrl == 9'b000000100)
    );

    // td_mode 0 only occurs when ctrl is not 1 through 4.
    check_td_mode_0_excludes_nonzero_modes: assert property (
        @($global_clock)
        (td_mode == 4'b0000)
        |-> !((ctrl == 9'b000000001) ||
              (ctrl == 9'b000000010) ||
              (ctrl == 9'b000000011) ||
              (ctrl == 9'b000000100))
    );

endmodule

module sbox2_sva (
    input logic clk,
    input logic [6:1] Bin,
    input logic [4:1] BSout
);

    // RTL is combinational with no native clock or reset; clk is a sampling clock.

    function automatic logic [4:1] sbox2_row00(input logic [3:0] col);
        begin
            case (col)
                4'h0: sbox2_row00 = 4'd15;
                4'h1: sbox2_row00 = 4'd1;
                4'h2: sbox2_row00 = 4'd8;
                4'h3: sbox2_row00 = 4'd14;
                4'h4: sbox2_row00 = 4'd6;
                4'h5: sbox2_row00 = 4'd11;
                4'h6: sbox2_row00 = 4'd3;
                4'h7: sbox2_row00 = 4'd4;
                4'h8: sbox2_row00 = 4'd9;
                4'h9: sbox2_row00 = 4'd7;
                4'hA: sbox2_row00 = 4'd2;
                4'hB: sbox2_row00 = 4'd13;
                4'hC: sbox2_row00 = 4'd12;
                4'hD: sbox2_row00 = 4'd0;
                4'hE: sbox2_row00 = 4'd5;
                4'hF: sbox2_row00 = 4'd10;
                default: sbox2_row00 = 4'd0;
            endcase
        end
    endfunction

    function automatic logic [4:1] sbox2_row01(input logic [3:0] col);
        begin
            case (col)
                4'h0: sbox2_row01 = 4'd3;
                4'h1: sbox2_row01 = 4'd13;
                4'h2: sbox2_row01 = 4'd4;
                4'h3: sbox2_row01 = 4'd7;
                4'h4: sbox2_row01 = 4'd15;
                4'h5: sbox2_row01 = 4'd2;
                4'h6: sbox2_row01 = 4'd8;
                4'h7: sbox2_row01 = 4'd14;
                4'h8: sbox2_row01 = 4'd12;
                4'h9: sbox2_row01 = 4'd0;
                4'hA: sbox2_row01 = 4'd1;
                4'hB: sbox2_row01 = 4'd10;
                4'hC: sbox2_row01 = 4'd6;
                4'hD: sbox2_row01 = 4'd9;
                4'hE: sbox2_row01 = 4'd11;
                4'hF: sbox2_row01 = 4'd5;
                default: sbox2_row01 = 4'd0;
            endcase
        end
    endfunction

    function automatic logic [4:1] sbox2_row10(input logic [3:0] col);
        begin
            case (col)
                4'h0: sbox2_row10 = 4'd0;
                4'h1: sbox2_row10 = 4'd14;
                4'h2: sbox2_row10 = 4'd7;
                4'h3: sbox2_row10 = 4'd11;
                4'h4: sbox2_row10 = 4'd10;
                4'h5: sbox2_row10 = 4'd4;
                4'h6: sbox2_row10 = 4'd13;
                4'h7: sbox2_row10 = 4'd1;
                4'h8: sbox2_row10 = 4'd5;
                4'h9: sbox2_row10 = 4'd8;
                4'hA: sbox2_row10 = 4'd12;
                4'hB: sbox2_row10 = 4'd6;
                4'hC: sbox2_row10 = 4'd9;
                4'hD: sbox2_row10 = 4'd3;
                4'hE: sbox2_row10 = 4'd2;
                4'hF: sbox2_row10 = 4'd15;
                default: sbox2_row10 = 4'd0;
            endcase
        end
    endfunction

    function automatic logic [4:1] sbox2_row11(input logic [3:0] col);
        begin
            case (col)
                4'h0: sbox2_row11 = 4'd13;
                4'h1: sbox2_row11 = 4'd8;
                4'h2: sbox2_row11 = 4'd10;
                4'h3: sbox2_row11 = 4'd1;
                4'h4: sbox2_row11 = 4'd3;
                4'h5: sbox2_row11 = 4'd15;
                4'h6: sbox2_row11 = 4'd4;
                4'h7: sbox2_row11 = 4'd2;
                4'h8: sbox2_row11 = 4'd11;
                4'h9: sbox2_row11 = 4'd6;
                4'hA: sbox2_row11 = 4'd7;
                4'hB: sbox2_row11 = 4'd12;
                4'hC: sbox2_row11 = 4'd0;
                4'hD: sbox2_row11 = 4'd5;
                4'hE: sbox2_row11 = 4'd14;
                4'hF: sbox2_row11 = 4'd9;
                default: sbox2_row11 = 4'd0;
            endcase
        end
    endfunction

    function automatic logic [4:1] sbox2_expected(input logic [6:1] bin);
        begin
            case ({bin[6], bin[1]})
                2'b00: sbox2_expected = sbox2_row00(bin[5:2]);
                2'b01: sbox2_expected = sbox2_row01(bin[5:2]);
                2'b10: sbox2_expected = sbox2_row10(bin[5:2]);
                2'b11: sbox2_expected = sbox2_row11(bin[5:2]);
                default: sbox2_expected = 4'd0;
            endcase
        end
    endfunction

    // Full S-box lookup matches the RTL case table.
    check_full_lookup_table: assert property (
        @(posedge clk) BSout === sbox2_expected(Bin)
    );

    // Row 00 entries match the first 16 case items.
    check_row_00_mapping: assert property (
        @(posedge clk) ({Bin[6], Bin[1]} === 2'b00) |-> (BSout === sbox2_row00(Bin[5:2]))
    );

    // Row 01 entries match the second 16 case items.
    check_row_01_mapping: assert property (
        @(posedge clk) ({Bin[6], Bin[1]} === 2'b01) |-> (BSout === sbox2_row01(Bin[5:2]))
    );

    // Row 10 entries match the third 16 case items.
    check_row_10_mapping: assert property (
        @(posedge clk) ({Bin[6], Bin[1]} === 2'b10) |-> (BSout === sbox2_row10(Bin[5:2]))
    );

    // Row 11 entries match the fourth 16 case items.
    check_row_11_mapping: assert property (
        @(posedge clk) ({Bin[6], Bin[1]} === 2'b11) |-> (BSout === sbox2_row11(Bin[5:2]))
    );

    // A stable input must preserve the same output across samples.
    check_output_stable_when_input_stable: assert property (
        @(posedge clk) (Bin === $past(Bin)) |-> (BSout === $past(BSout))
    );

endmodule

rtl:
module input_pulse_toggle(
   // Inputs
   clk, in, reset,
   // Outputs
   out
   );

   input clk, in, reset;
   output reg out;

   reg prev_in;
   wire toggle;

   always @(posedge clk or negedge reset) begin
      if (!reset) begin
         out <= 1'b0;
         prev_in <= 1'b0;
      end
      else begin
         prev_in <= in;
         out <= toggle;
      end
   end

   assign toggle = (in & ~prev_in) ? ~out : out;

endmodule

sva:
module input_pulse_toggle_sva (
    input logic clk,
    input logic in,
    input logic reset,
    input logic out
);

    // Active-low reset drives the output low.
    check_reset_forces_out_low: assert property (
        @(posedge clk) !$initstate && !reset |-> (out == 1'b0)
    );

    // First active cycle after reset with low input keeps output low.
    check_post_reset_low_input_keeps_out_low: assert property (
        @(posedge clk) disable iff (!reset)
        (!$initstate && !$past(reset) && !in) |=> (out == 1'b0)
    );

    // First active cycle after reset with high input sets output high.
    check_post_reset_high_input_sets_out_high: assert property (
        @(posedge clk) disable iff (!reset)
        (!$initstate && !$past(reset) && in) |=> (out == 1'b1)
    );

    // A sampled 0-to-1 input transition toggles the output.
    check_sampled_rise_toggles_out: assert property (
        @(posedge clk) disable iff (!reset)
        (!$initstate && $past(reset) && in && !$past(in)) |=> (out == ~$past(out))
    );

    // Low input on an active cycle leaves the output unchanged.
    check_low_input_holds_out: assert property (
        @(posedge clk) disable iff (!reset)
        (!$initstate && $past(reset) && !in) |=> (out == $past(out))
    );

    // High input held across active cycles leaves the output unchanged.
    check_steady_high_holds_out: assert property (
        @(posedge clk) disable iff (!reset)
        (!$initstate && $past(reset) && in && $past(in)) |=> (out == $past(out))
    );

endmodule

rtl:
module bitwise_and(
    input [31:0] a,
    input [31:0] b,
    output [31:0] out
);

    wire [31:0] carry;
    wire [31:0] g;
    wire [31:0] p;

    assign g = a & b;
    assign p = a | b;

    assign carry[0] = g[0];
    assign out[0] = g[0];

    genvar i;
    generate
        for (i = 1; i < 32; i = i + 1) begin
            assign carry[i] = g[i] | (p[i] & carry[i-1]);
            assign out[i] = g[i] ^ (p[i] & carry[i-1]);
        end
    endgenerate

endmodule

module control_logic(
    input [31:0] a,
    input [31:0] b,
    input enable,
    output [31:0] out
);

    wire [31:0] result;

    bitwise_and and1(a, b, result);

    assign out = enable ? result : 0;

endmodule

module top_module( 
    input [31:0] a, b,
    input enable,
    output [31:0] out
);

    wire [31:0] result;

    control_logic ctrl(a, b, enable, result);

    assign out = result;

endmodule

sva:
module top_module_sva(
    input logic [31:0] a,
    input logic [31:0] b,
    input logic        enable,
    input logic [31:0] out
);

    function automatic logic carry_prefix(
        input logic [31:0] a_i,
        input logic [31:0] b_i,
        input integer      idx
    );
        logic [31:0] g_i;
        logic [31:0] p_i;
        logic        carry_val;
        integer      j;
        begin
            g_i = a_i & b_i;
            p_i = a_i | b_i;
            carry_val = g_i[0];
            if (idx == 0) begin
                carry_prefix = carry_val;
            end else begin
                for (j = 1; j <= idx; j = j + 1) begin
                    carry_val = g_i[j] | (p_i[j] & carry_val);
                end
                carry_prefix = carry_val;
            end
        end
    endfunction

    // Disabling the control logic forces the top-level output low.
    check_disable_forces_zero: assert property (
        @($global_clock) !enable |-> (out == 32'h00000000)
    );

    // A zero operand produces a zero enabled result.
    check_zero_operand_yields_zero: assert property (
        @($global_clock) enable && ((a == 32'h00000000) || (b == 32'h00000000)) |-> (out == 32'h00000000)
    );

    // The least-significant bit matches the base assignment when enabled.
    check_enabled_lsb_base_case: assert property (
        @($global_clock) enable |-> (out[0] == (a[0] & b[0]))
    );

    generate
        genvar i;
        for (i = 1; i < 32; i = i + 1) begin : gen_recursive_output_bit_checks
            // Each higher bit follows the recursive carry-based expression when enabled.
            check_enabled_recursive_output_bit: assert property (
                @($global_clock) enable |-> (
                    out[i] == ((a[i] & b[i]) ^ ((a[i] | b[i]) & carry_prefix(a, b, i-1)))
                )
            );
        end
    endgenerate

endmodule

module up_down_counter_sva (
    input logic       clk,
    input logic       reset,
    input logic       up_down,
    input logic [2:0] count
);

    // Clock: clk; reset: active-low asynchronous reset; logic: sequential 3-bit up/down counter.

    // When reset is low, the counter must be at zero.
    check_reset_clears_count: assert property (
        @(posedge clk) !reset |-> (count == 3'b000)
    );

    // When counting up, the next count increments by one modulo 8.
    check_count_up_step: assert property (
        @(posedge clk) disable iff (!reset)
        up_down |=> (count == ($past(count) + 3'd1))
    );

    // When counting down, the next count decrements by one modulo 8.
    check_count_down_step: assert property (
        @(posedge clk) disable iff (!reset)
        !up_down |=> (count == ($past(count) - 3'd1))
    );

    // Incrementing from the maximum value wraps to zero.
    check_up_wraps_from_max: assert property (
        @(posedge clk) disable iff (!reset)
        (up_down && (count == 3'b111)) |=> (count == 3'b000)
    );

    // Decrementing from zero wraps to the maximum value.
    check_down_wraps_from_zero: assert property (
        @(posedge clk) disable iff (!reset)
        (!up_down && (count == 3'b000)) |=> (count == 3'b111)
    );

    // Outside reset, the counter changes on every clock edge.
    check_count_changes_each_cycle: assert property (
        @(posedge clk) disable iff (!reset)
        1'b1 |=> (count != $past(count))
    );

endmodule

rtl:
module adder_4bit(
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] Sum,
    output Cout
);

    wire [3:0] temp_sum;
    wire [4:0] temp_carry;

    // Full adder for the least significant bit
    full_adder FA0(
        .a(A[0]),
        .b(B[0]),
        .c(Cin),
        .sum(temp_sum[0]),
        .carry(temp_carry[0])
    );

    // Full adder for the second least significant bit
    full_adder FA1(
        .a(A[1]),
        .b(B[1]),
        .c(temp_carry[0]),
        .sum(temp_sum[1]),
        .carry(temp_carry[1])
    );

    // Full adder for the third least significant bit
    full_adder FA2(
        .a(A[2]),
        .b(B[2]),
        .c(temp_carry[1]),
        .sum(temp_sum[2]),
        .carry(temp_carry[2])
    );

    // Full adder for the most significant bit
    full_adder FA3(
        .a(A[3]),
        .b(B[3]),
        .c(temp_carry[2]),
        .sum(temp_sum[3]),
        .carry(Cout)
    );

    assign Sum = temp_sum;

endmodule

module full_adder(
    input a,
    input b,
    input c,
    output sum,
    output carry
);

    wire s1, c1, c2;

    // First XOR gate
    xor_gate XG1(
        .a(a),
        .b(b),
        .out(s1)
    );

    // Second XOR gate
    xor_gate XG2(
        .a(s1),
        .b(c),
        .out(sum)
    );

    // First AND gate
    and_gate AG1(
        .a(a),
        .b(b),
        .out(c1)
    );

    // Second AND gate
    and_gate AG2(
        .a(s1),
        .b(c),
        .out(c2)
    );

    // OR gate for the carry out
    or_gate OG1(
        .a(c1),
        .b(c2),
        .out(carry)
    );

endmodule

module xor_gate(
    input a,
    input b,
    output out
);

    assign out = a ^ b;

endmodule

module and_gate(
    input a,
    input b,
    output out
);

    assign out = a & b;

endmodule

module or_gate(
    input a,
    input b,
    output out
);

    assign out = a | b;

endmodule

sva:
module adder_4bit_sva (
    input logic       clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic       Cin,
    input logic [3:0] Sum,
    input logic       Cout
);

    // Sum and Cout must match 4-bit addition with carry in.
    check_overall_addition: assert property (
        @(posedge clk)
        {Cout, Sum} == ({1'b0, A} + {1'b0, B} + {4'b0, Cin})
    );

    // Bit 0 sum must be the XOR of A[0], B[0], and Cin.
    check_sum_bit0: assert property (
        @(posedge clk)
        Sum[0] == (A[0] ^ B[0] ^ Cin)
    );

    // Bit 1 sum must use the carry generated by bit 0.
    check_sum_bit1: assert property (
        @(posedge clk)
        Sum[1] == (
            A[1] ^ B[1] ^
            ((A[0] & B[0]) | ((A[0] ^ B[0]) & Cin))
        )
    );

    // Bit 2 sum must use the ripple carry generated through bit 1.
    check_sum_bit2: assert property (
        @(posedge clk)
        Sum[2] == (
            A[2] ^ B[2] ^
            (
                (A[1] & B[1]) |
                (
                    (A[1] ^ B[1]) &
                    (
                        (A[0] & B[0]) |
                        ((A[0] ^ B[0]) & Cin)
                    )
                )
            )
        )
    );

    // Bit 3 sum must use the ripple carry generated through bit 2.
    check_sum_bit3: assert property (
        @(posedge clk)
        Sum[3] == (
            A[3] ^ B[3] ^
            (
                (A[2] & B[2]) |
                (
                    (A[2] ^ B[2]) &
                    (
                        (A[1] & B[1]) |
                        (
                            (A[1] ^ B[1]) &
                            (
                                (A[0] & B[0]) |
                                ((A[0] ^ B[0]) & Cin)
                            )
                        )
                    )
                )
            )
        )
    );

    // Cout must be the final ripple carry from the most significant stage.
    check_cout_equation: assert property (
        @(posedge clk)
        Cout == (
            (A[3] & B[3]) |
            (
                (A[3] ^ B[3]) &
                (
                    (A[2] & B[2]) |
                    (
                        (A[2] ^ B[2]) &
                        (
                            (A[1] & B[1]) |
                            (
                                (A[1] ^ B[1]) &
                                (
                                    (A[0] & B[0]) |
                                    ((A[0] ^ B[0]) & Cin)
                                )
                            )
                        )
                    )
                )
            )
        )
    );

endmodule

rtl:
module barrel_shifter (
    input [7:0] DATA,
    input [2:0] SHIFT_AMOUNT,
    input SHIFT_DIRECTION,
    output [7:0] SHIFTED_DATA
);

reg [7:0] pipeline_reg [2:0];

// Pipeline stage 1
always @(*) begin
    if (SHIFT_DIRECTION == 1'b0) // Left shift
        pipeline_reg[0] = DATA << SHIFT_AMOUNT;
    else // Right shift
        pipeline_reg[0] = DATA >> SHIFT_AMOUNT;
end

// Pipeline stage 2
always @(*) begin
    pipeline_reg[1] = pipeline_reg[0];
end

// Pipeline stage 3
always @(*) begin
    pipeline_reg[2] = pipeline_reg[1];
end

assign SHIFTED_DATA = pipeline_reg[2];

endmodule

sva:
module barrel_shifter_sva (
    input logic [7:0] DATA,
    input logic [2:0] SHIFT_AMOUNT,
    input logic       SHIFT_DIRECTION,
    input logic [7:0] SHIFTED_DATA
);

    // No clock or reset exists in the RTL; sample this combinational logic on $global_clock.

    // Left-shift mode must match DATA shifted left by SHIFT_AMOUNT.
    check_left_shift_result: assert property (
        @($global_clock)
        (SHIFT_DIRECTION == 1'b0) |-> (SHIFTED_DATA == (DATA << SHIFT_AMOUNT))
    );

    // Right-shift mode must match DATA shifted right by SHIFT_AMOUNT.
    check_right_shift_result: assert property (
        @($global_clock)
        (SHIFT_DIRECTION == 1'b1) |-> (SHIFTED_DATA == (DATA >> SHIFT_AMOUNT))
    );

    // A zero shift amount must pass DATA through unchanged.
    check_zero_shift_passthrough: assert property (
        @($global_clock)
        (SHIFT_AMOUNT == 3'd0) |-> (SHIFTED_DATA == DATA)
    );

    // Nonzero left shifts must zero-fill the vacated low bits.
    check_left_shift_zero_fill_low_bits: assert property (
        @($global_clock)
        (SHIFT_DIRECTION == 1'b0 && SHIFT_AMOUNT != 3'd0) |->
        ((SHIFTED_DATA & ((8'h01 << SHIFT_AMOUNT) - 8'h01)) == 8'h00)
    );

    // Nonzero right shifts must zero-fill the vacated high bits.
    check_right_shift_zero_fill_high_bits: assert property (
        @($global_clock)
        (SHIFT_DIRECTION == 1'b1 && SHIFT_AMOUNT != 3'd0) |->
        ((SHIFTED_DATA & ~(8'hFF >> SHIFT_AMOUNT)) == 8'h00)
    );

    // A left shift by seven keeps only DATA[0] in the MSB position.
    check_left_shift_by_seven: assert property (
        @($global_clock)
        (SHIFT_DIRECTION == 1'b0 && SHIFT_AMOUNT == 3'd7) |->
        (SHIFTED_DATA == {DATA[0], 7'b0})
    );

    // A right shift by seven keeps only DATA[7] in the LSB position.
    check_right_shift_by_seven: assert property (
        @($global_clock)
        (SHIFT_DIRECTION == 1'b1 && SHIFT_AMOUNT == 3'd7) |->
        (SHIFTED_DATA == {7'b0, DATA[7]})
    );

endmodule

module adder_subtractor_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic       SUB,
    input logic [3:0] out
);

    // In add mode, out must be the 4-bit sum of A and B.
    check_add_mode_result: assert property (
        @($global_clock) (SUB == 1'b0) |-> (out == (A + B))
    );

    // In subtract mode, out must be the 4-bit difference of A and B.
    check_sub_mode_result: assert property (
        @($global_clock) (SUB == 1'b1) |-> (out == (A - B))
    );

    // If all inputs stay the same, the combinational output must stay the same.
    check_output_stable_when_inputs_stable: assert property (
        @($global_clock) !$initstate && $stable({A, B, SUB}) |-> $stable(out)
    );

endmodule

rtl:
module ripple_carry_adder (
  input [3:0] a, b,
  input cin,
  output [3:0] sum,
  output cout
);

  wire [3:0] c;

  assign c[0] = cin;
  assign c[1] = (a[0] & b[0]) | (a[0] & cin) | (b[0] & cin);
  assign c[2] = (a[1] & b[1]) | (a[1] & c[1]) | (b[1] & c[1]);
  assign c[3] = (a[2] & b[2]) | (a[2] & c[2]) | (b[2] & c[2]);

  assign sum = a + b + cin;
  assign cout = c[3];

endmodule

sva:
module ripple_carry_adder_sva (
    input logic [3:0] a,
    input logic [3:0] b,
    input logic       cin,
    input logic [3:0] sum,
    input logic       cout
);

    // Sum matches the RTL arithmetic assignment.
    check_sum_matches_add: assert property (
        @($global_clock) sum == (a + b + cin)
    );

    // sum[0] is the XOR of the LSB inputs and cin.
    check_sum_bit0: assert property (
        @($global_clock) sum[0] == (a[0] ^ b[0] ^ cin)
    );

    // sum[1] uses the carry generated from bit 0.
    check_sum_bit1: assert property (
        @($global_clock)
        sum[1] == (
            a[1] ^ b[1] ^
            ((a[0] & b[0]) | (a[0] & cin) | (b[0] & cin))
        )
    );

    // sum[2] uses the carry generated from bits 0 and 1.
    check_sum_bit2: assert property (
        @($global_clock)
        sum[2] == (
            a[2] ^ b[2] ^
            ((a[1] & b[1]) |
             (a[1] & ((a[0] & b[0]) | (a[0] & cin) | (b[0] & cin))) |
             (b[1] & ((a[0] & b[0]) | (a[0] & cin) | (b[0] & cin))))
        )
    );

    // cout is the carry generated by the lower three bits.
    check_cout_lower3_carry: assert property (
        @($global_clock)
        cout == (({1'b0, a[2:0]} + {1'b0, b[2:0]} + cin) >= 4'd8)
    );

    // sum[3] uses cout as the carry-in to the MSB.
    check_sum_bit3_uses_cout: assert property (
        @($global_clock) sum[3] == (a[3] ^ b[3] ^ cout)
    );

endmodule

rtl:
module openhmc_counter48 #(
        parameter DATASIZE  = 16    ) (
        input wire                  clk,
        input wire                  res_n,
        input wire                  increment,
        input wire                  load_enable,
        output wire [DATASIZE-1:0]  value
);

    reg [DATASIZE-1:0]  value_reg;
    reg                 load_enable_reg;

    assign value    = value_reg;

    `ifdef ASYNC_RES
    always @(posedge clk or negedge res_n) `else
    always @(posedge clk) `endif
    begin
        if(!res_n) begin
            value_reg               <= {DATASIZE{1'b0}};
            load_enable_reg         <= 1'b0;
        end else begin
            load_enable_reg         <= load_enable;
            case ({load_enable_reg,increment})
                    2'b00:
                        value_reg   <= value_reg;
                    2'b01:
                        value_reg   <= (value_reg + 1'b1);
                    2'b10:
                        value_reg   <= {DATASIZE{1'b0}};
                    2'b11:
                        value_reg   <= {DATASIZE{1'b0}} + 1'b1;
            endcase
        end
    end

endmodule

sva:
module openhmc_counter48_sva #(
    parameter DATASIZE = 16
) (
    input logic                 clk,
    input logic                 res_n,
    input logic                 increment,
    input logic                 load_enable,
    input logic [DATASIZE-1:0]  value
);

    // A sampled reset cycle forces the counter output to zero by the next sample.
    check_reset_clears_value: assert property (
        @(posedge clk)
        (!res_n) |=> (value == {DATASIZE{1'b0}})
    );

    // With no pending load and no increment, the counter holds its value.
    check_hold_when_no_load_pending_and_no_increment: assert property (
        @(posedge clk) disable iff (!res_n)
        ($past(res_n) && !$past(load_enable) && !increment) |=> (value == $past(value))
    );

    // With no pending load and increment asserted, the counter increments by one.
    check_increment_when_no_load_pending: assert property (
        @(posedge clk) disable iff (!res_n)
        ($past(res_n) && !$past(load_enable) && increment) |=> (value == ($past(value) + 1'b1))
    );

    // A pending load with no increment clears the counter to zero.
    check_clear_when_load_was_pending_and_no_increment: assert property (
        @(posedge clk) disable iff (!res_n)
        ($past(res_n) && $past(load_enable) && !increment) |=> (value == {DATASIZE{1'b0}})
    );

    // A pending load with increment asserted sets the counter to one.
    check_set_one_when_load_was_pending_and_increment: assert property (
        @(posedge clk) disable iff (!res_n)
        ($past(res_n) && $past(load_enable) && increment) |=> (value == ({DATASIZE{1'b0}} + 1'b1))
    );

endmodule

rtl:
module IBUFDS_GTE3 #(
  parameter REFCLK_EN_TX_PATH = 1'b0,
  parameter REFCLK_HROW_CK_SEL = 2'b00,
  parameter REFCLK_ICNTL_RX = 2'b00
)(
  output reg O,
  output reg ODIV2,

  input CEB,
  input I,
  input IB
);

  reg [2:0] edge_count = 0;
  reg allEqual = 0;
  reg ODIV2_out = 0;

  always @(posedge I) begin
    if (CEB == 1'b0) begin
      edge_count <= edge_count + 1;
    end
  end

  always @(edge_count) begin
    if (edge_count == REFCLK_ICNTL_RX) begin
      allEqual <= 1;
    end else begin
      allEqual <= 0;
    end
  end

  always @(*) begin
    case (REFCLK_HROW_CK_SEL)
      2'b00: begin
        if (REFCLK_EN_TX_PATH || CEB == 1'b0) begin
          O <= 1'b0;
        end else begin
          O <= I;
        end
        ODIV2_out <= O;
      end
      2'b01: begin
        O <= I;
        if (allEqual == 1 || REFCLK_EN_TX_PATH || CEB == 1'b0) begin
          ODIV2_out <= 1'b0;
        end else begin
          ODIV2_out <= 1'b1;
        end
      end
      2'b10, 2'b11: begin
        O <= I;
        ODIV2_out <= 1'b0;
      end
    endcase
  end

  always @* begin
    ODIV2 = ODIV2_out;
  end

endmodule

sva:
module IBUFDS_GTE3_sva #(
    parameter REFCLK_EN_TX_PATH = 1'b0,
    parameter REFCLK_HROW_CK_SEL = 2'b00,
    parameter REFCLK_ICNTL_RX = 2'b00
) (
    input logic O,
    input logic ODIV2,
    input logic CEB,
    input logic I,
    input logic IB
);

    generate
        if (REFCLK_HROW_CK_SEL == 2'b00) begin : gen_mode00
            // In mode 00, ODIV2 mirrors O.
            check_mode00_odiv2_matches_o: assert property (
                @(posedge I) ODIV2 == O
            );

            // In mode 00, TX path enable or low CEB forces O low.
            check_mode00_force_o_low: assert property (
                @(posedge I) ((REFCLK_EN_TX_PATH == 1'b1) || (CEB == 1'b0)) |-> (O == 1'b0)
            );

            // In mode 00, TX path enable or low CEB forces ODIV2 low.
            check_mode00_force_odiv2_low: assert property (
                @(posedge I) ((REFCLK_EN_TX_PATH == 1'b1) || (CEB == 1'b0)) |-> (ODIV2 == 1'b0)
            );
        end

        if (REFCLK_HROW_CK_SEL == 2'b01) begin : gen_mode01
            // In mode 01, TX path enable forces ODIV2 low.
            check_mode01_tx_path_forces_odiv2_low: assert property (
                @(posedge I) (REFCLK_EN_TX_PATH == 1'b1) |-> (ODIV2 == 1'b0)
            );

            // In mode 01, low CEB forces ODIV2 low.
            check_mode01_ceb_low_forces_odiv2_low: assert property (
                @(posedge I) (CEB == 1'b0) |-> (ODIV2 == 1'b0)
            );

            // In mode 01, ODIV2 can be high only with TX path disabled and CEB high.
            check_mode01_odiv2_high_requires_enabled_path: assert property (
                @(posedge I) (ODIV2 == 1'b1) |-> ((REFCLK_EN_TX_PATH == 1'b0) && (CEB == 1'b1))
            );
        end

        if ((REFCLK_HROW_CK_SEL == 2'b10) || (REFCLK_HROW_CK_SEL == 2'b11)) begin : gen_mode23
            // In modes 10 and 11, ODIV2 is tied low.
            check_mode23_odiv2_tied_low: assert property (
                @(posedge I) ODIV2 == 1'b0
            );
        end
    endgenerate

endmodule

