    // X must match the implemented AO221 logic function.
    check_full_function: assert property (
        @(posedge clk) X === (((A1 & A2) | (B1 & B2)) | C1)
    );

    // The A1/A2 product term must drive X high.
    check_a_term_drives_high: assert property (
