module UAdder (out,carry_out,overflow,A,B,C_in);
   output [31:0]out;
   output      carry_out,overflow;
   input [31:0] A,B;
   input       C_in;
   wire [6:0]  carry;

   CLA_4bit cc1(out[3:0],carry[0],A[3:0],B[3:0],C_in);
   CLA_4bit cc2(out[7:4],carry[1],A[7:4],B[7:4],carry[0]);
   CLA_4bit cc3(out[11:8],carry[2],A[11:8],B[11:8],carry[1]);
   CLA_4bit cc4(out[15:12],carry[3],A[15:12],B[15:12],carry[2]);
   CLA_4bit cc5(out[19:16],carry[4],A[19:16],B[19:16],carry[3]);
   CLA_4bit cc6(out[23:20],carry[5],A[23:20],B[23:20],carry[4]);
   CLA_4bit cc7(out[27:24],carry[6],A[27:24],B[27:24],carry[5]);
   CLA_4bito cc8(out[31:28],carry_out,overflow,A[31:28],B[31:28],carry[6]);
endmodule

module CLA_4bit(out,carry_out,A,B,C_in);
   output [3:0]out;
   output      carry_out;
   input [3:0] A,B;
   input       C_in;
   wire  [3:0] p,g;
   wire [9:0] andl1;
   wire [3:0] carry ;

   xor xx1(p[0],A[0],B[0]);
   xor xx2(p[1],A[1],B[1]);
   xor xx3(p[2],A[2],B[2]);
   xor xx4(p[3],A[3],B[3]);

   and aa1(g[0],A[0],B[0]);
   and aa2(g[1],A[1],B[1]);
   and aa3(g[2],A[2],B[2]);
   and aa4(g[3],A[3],B[3]);

   and al1(andl1[0],p[0],C_in);
   and al2(andl1[1],p[1],g[0]);
   and al3(andl1[2],p[1],p[0],C_in);
   and al4(andl1[3],p[2],g[1]);
   and al5(andl1[4],p[2],p[1],g[0]);
   and al6(andl1[5],p[2],p[1],p[0],C_in);
   and al7(andl1[6],p[3],g[2]);
   and al8(andl1[7],p[3],p[2],g[1]);
   and al9(andl1[8],p[3],p[2],p[1],g[0]);
   and al10(andl1[9],p[3],p[2],p[1],p[0],C_in);

   or oo1(carry[0],g[0],andl1[0]);
   or oo2(carry[1],g[1],andl1[1],andl1[2]);
   or oo3(carry[2],g[2],andl1[3],andl1[4],andl1[5]);
   or oo4(carry_out,g[3],andl1[6],andl1[7],andl1[8],andl1[9]);

   xor xs1(out[0],p[0],C_in);
   xor xs2(out[1],p[1],carry[0]);
   xor xs3(out[2],p[2],carry[1]);
   xor xs4(out[3],p[3],carry[2]);   
endmodule

module CLA_4bito(out,carry_out,overflow,A,B,C_in);
   output [3:0]out;
   output      carry_out,overflow;
   input [3:0] A,B;
   input       C_in;
   wire  [3:0] p,g;
   wire [9:0] andl1;
   wire [2:0] carry ;

   xor xx1(p[0],A[0],B[0]);
   xor xx2(p[1],A[1],B[1]);
   xor xx3(p[2],A[2],B[2]);
   xor xx4(p[3],A[3],B[3]);

   and aa1(g[0],A[0],B[0]);
   and aa2(g[1],A[1],B[1]);
   and aa3(g[2],A[2],B[2]);
   and aa4(g[3],A[3],B[3]);

   and al1(andl1[0],p[0],C_in);
   and al2(andl1[1],p[1],g[0]);
   and al3(andl1[2],p[1],p[0],C_in);
   and al4(andl1[3],p[2],g[1]);
   and al5(andl1[4],p[2],p[1],g[0]);
   and al6(andl1[5],p[2],p[1],p[0],C_in);
   and al7(andl1[6],p[3],g[2]);
   and al8(andl1[7],p[3],p[2],g[1]);
   and al9(andl1[8],p[3],p[2],p[1],g[0]);
   and al10(andl1[9],p[3],p[2],p[1],p[0],C_in);

   or oo1(carry[0],g[0],andl1[0]);
   or oo2(carry[1],g[1],andl1[1],andl1[2]);
   or oo3(carry[2],g[2],andl1[3],andl1[4],andl1[5]);
   or oo4(carry_out,g[3],andl1[6],andl1[7],andl1[8],andl1[9]);

   xor xs1(out[0],p[0],C_in);
   xor xs2(out[1],p[1],carry[0]);
   xor xs3(out[2],p[2],carry[1]);
   xor xs4(out[3],p[3],carry[2]);
   assign overflow=carry_out^carry[2];

endmodule

sva:
module UAdder_sva (
    input logic        clk,
    input logic [31:0] out,
    input logic        carry_out,
    input logic        overflow,
    input logic [31:0] A,
    input logic [31:0] B,
    input logic        C_in
);

    // Low nibble matches the first 4-bit CLA result.
    check_nibble0_sum: assert property (
        @(posedge clk) out[3:0] == (A[3:0] + B[3:0] + C_in)
    );

    // Second nibble matches a 4-bit add with carry from bits [3:0].
    check_nibble1_sum: assert property (
        @(posedge clk)
        out[7:4] == (A[7:4] + B[7:4] + (({1'b0, A[3:0]} + {1'b0, B[3:0]} + C_in) > 5'h0F))
    );

    // Nibble [15:12] matches a 4-bit add with carry from bits [11:0].
    check_nibble3_sum: assert property (
        @(posedge clk)
        out[15:12] == (A[15:12] + B[15:12] + (({1'b0, A[11:0]} + {1'b0, B[11:0]} + C_in) > 13'h0FFF))
    );

    // Nibble [23:20] matches a 4-bit add with carry from bits [19:0].
    check_nibble5_sum: assert property (
        @(posedge clk)
        out[23:20] == (A[23:20] + B[23:20] + (({1'b0, A[19:0]} + {1'b0, B[19:0]} + C_in) > 21'h0FFFFF))
    );

    // Top nibble matches the final 4-bit CLA result with propagated carry.
    check_nibble7_sum: assert property (
        @(posedge clk)
        out[31:28] == (A[31:28] + B[31:28] + (({1'b0, A[27:0]} + {1'b0, B[27:0]} + C_in) > 29'h0FFFFFFF))
    );

    // Combined carry_out and out equal the full 33-bit sum.
    check_full_sum: assert property (
        @(posedge clk) {carry_out, out} == ({1'b0, A} + {1'b0, B} + C_in)
    );

    // Overflow matches the signed-add overflow condition.
    check_overflow_equation: assert property (
        @(posedge clk)
        overflow == ((A[31] & B[31] & ~out[31]) | (~A[31] & ~B[31] & out[31]))
    );

    // Opposite-sign operands cannot produce signed overflow.
    check_opposite_sign_no_overflow: assert property (
        @(posedge clk) (A[31] ^ B[31]) |-> !overflow
    );

    // Adding zero on B with no carry-in passes A through unchanged.
    check_zero_b_passthrough: assert property (
        @(posedge clk)
        ((B == 32'h0000_0000) && !C_in) |-> ((out == A) && !carry_out && !overflow)
    );

    // Adding zero on A with no carry-in passes B through unchanged.
    check_zero_a_passthrough: assert property (
        @(posedge clk)
        ((A == 32'h0000_0000) && !C_in) |-> ((out == B) && !carry_out && !overflow)
    );

endmodule

rtl:
module logic_module (
    input A1,
    input A2,
    input B1,
    input B2,
    output Y
);

    assign Y = (A1 & A2) | ((A1 & ~B1 & ~B2) & ~(A2 | B1 | B2)) | (~A1 & ~A2 & B1 & B2);

endmodule

sva:
module logic_module_sva (
    input logic A1,
    input logic A2,
    input logic B1,
    input logic B2,
    input logic Y
);

    // Y must match the RTL combinational expression.
    check_y_matches_rtl: assert property (
        @($global_clock)
        Y == ((A1 & A2) |
              ((A1 & ~B1 & ~B2) & ~(A2 | B1 | B2)) |
              (~A1 & ~A2 & B1 & B2))
    );

    // A1 and A2 high forces Y high.
    check_y_high_when_a1_a2_high: assert property (
        @($global_clock)
        (A1 && A2) |-> Y
    );

    // A1 high with A2 low and both B inputs low forces Y high.
    check_y_high_when_a1_only_and_b_low: assert property (
        @($global_clock)
        (A1 && !A2 && !B1 && !B2) |-> Y
    );

    // Both A inputs low and both B inputs high forces Y high.
    check_y_high_when_a_low_and_b_high: assert property (
        @($global_clock)
        (!A1 && !A2 && B1 && B2) |-> Y
    );

    // A1 low with A2 high forces Y low.
    check_y_low_when_a1_low_a2_high: assert property (
        @($global_clock)
        (!A1 && A2) |-> !Y
    );

    // A1 high with A2 low and any B input high forces Y low.
    check_y_low_when_a1_high_a2_low_and_any_b_high: assert property (
        @($global_clock)
        (A1 && !A2 && (B1 || B2)) |-> !Y
    );

    // Both A inputs low require both B inputs high for Y to be high.
    check_y_low_when_a_low_without_b_pair: assert property (
        @($global_clock)
        (!A1 && !A2 && !(B1 && B2)) |-> !Y
    );

    // If Y is high while A1 is low, it must come from the B1/B2 term.
    check_y_high_with_a1_low_implies_b_term: assert property (
        @($global_clock)
        (Y && !A1) |-> (!A2 && B1 && B2)
    );

    // If Y is high while A1 is high and A2 is low, both B inputs must be low.
    check_y_high_with_a1_high_a2_low_implies_b_low: assert property (
        @($global_clock)
        (Y && A1 && !A2) |-> (!B1 && !B2)
    );

endmodule

module switch_reader_sva (
    input logic       clk,
    input logic       reset_n,
    input logic [3:0] switches,
    input logic [3:0] data_out
);

    // Active-low reset clears the registered output.
    check_reset_clears_data_out: assert property (
        @(posedge clk) !reset_n |-> (data_out == 4'b0000)
    );

    // Each active clock loads data_out with the prior sampled switches value.
    check_data_out_captures_switches: assert property (
        @(posedge clk) disable iff (!reset_n)
        1'b1 |=> (data_out == $past(switches))
    );

    // After reset deasserts, data_out remains cleared until the next clocked update.
    check_reset_release_holds_zero_until_update: assert property (
        @(posedge clk) disable iff (!reset_n)
        $rose(reset_n) |-> (data_out == 4'b0000)
    );

endmodule

rtl:
module GreaterThan(
    input clk,              // Clock input
    input reset,            // Synchronous reset
    input [7:0] A,          // 8-bit input A
    input [7:0] B,          // 8-bit input B
    output reg result       // Output result, reg type because it's driven by always block
);

// Sequential logic to compare A and B on clock edges, reset on reset signal
always @(posedge clk) begin
    if (reset) begin
        // Reset state, result can be set to 0 or any default value
        result <= 1'b0;
    end else begin
        // Compare A and B and update result accordingly
        result <= (A > B) ? 1'b1 : 1'b0;
    end
end

endmodule

sva:
module GreaterThan_sva(
    input logic        clk,
    input logic        reset,
    input logic [7:0]  A,
    input logic [7:0]  B,
    input logic        result
);

    // A reset cycle must drive result low by the next sampled cycle.
    check_reset_clears_result: assert property (
        @(posedge clk)
        reset |=> (result == 1'b0)
    );

    // Outside reset, a prior A>B comparison must set result high.
    check_gt_sets_result: assert property (
        @(posedge clk) disable iff (reset)
        !$initstate && !$past(reset) && ($past(A) > $past(B)) |-> (result == 1'b1)
    );

    // Outside reset, a prior A<=B comparison must clear result low.
    check_le_clears_result: assert property (
        @(posedge clk) disable iff (reset)
        !$initstate && !$past(reset) && ($past(A) <= $past(B)) |-> (result == 1'b0)
    );

    // Each sampled cycle must reflect the previous cycle's reset or compare result.
    check_registered_compare_behavior: assert property (
        @(posedge clk)
        !$initstate |-> (result == ($past(reset) ? 1'b0 : ($past(A) > $past(B))))
    );

endmodule

rtl:
module top_module (
    input clk,
    input load,
    input up_down,
    input [3:0] D,
    output [3:0] OUT
);

reg [3:0] up_counter;
reg [3:0] down_counter;
wire [3:0] xor_output;

// Up counter
always @(posedge clk) begin
    if (load) begin
        up_counter <= D;
    end else if (up_down) begin
        if (up_counter == 4'b1111) begin
            up_counter <= 4'b0;
        end else begin
            up_counter <= up_counter + 1;
        end
    end
end

// Down counter
always @(posedge clk) begin
    if (load) begin
        down_counter <= D;
    end else if (!up_down) begin
        if (down_counter == 4'b0000) begin
            down_counter <= 4'b1111;
        end else begin
            down_counter <= down_counter - 1;
        end
    end
end

// XOR module
assign xor_output = up_counter ^ down_counter;

// Output
assign OUT = xor_output;

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic load,
    input logic up_down,
    input logic [3:0] D,
    input logic [3:0] OUT,
    input logic [3:0] up_counter,
    input logic [3:0] down_counter
);

    // OUT is always the XOR of the two counters.
    check_out_is_counter_xor: assert property (
        @(posedge clk) OUT == (up_counter ^ down_counter)
    );

    // A load updates the up counter with D on the next cycle.
    check_load_updates_up_counter: assert property (
        @(posedge clk) load |=> (up_counter == $past(D))
    );

    // A load updates the down counter with D on the next cycle.
    check_load_updates_down_counter: assert property (
        @(posedge clk) load |=> (down_counter == $past(D))
    );

    // Loading both counters with the same value makes OUT zero.
    check_load_drives_zero_out: assert property (
        @(posedge clk) load |=> (OUT == 4'h0)
    );

    // In up mode, the up counter increments when not at 15.
    check_up_counter_increments: assert property (
        @(posedge clk) (!load && up_down && (up_counter != 4'hf)) |=> (up_counter == ($past(up_counter) + 4'h1))
    );

    // In up mode, the up counter wraps from 15 to 0.
    check_up_counter_wraps: assert property (
        @(posedge clk) (!load && up_down && (up_counter == 4'hf)) |=> (up_counter == 4'h0)
    );

    // In down mode, the up counter holds its value.
    check_up_counter_holds_in_down_mode: assert property (
        @(posedge clk) (!load && !up_down) |=> (up_counter == $past(up_counter))
    );

    // In down mode, the down counter decrements when not at 0.
    check_down_counter_decrements: assert property (
        @(posedge clk) (!load && !up_down && (down_counter != 4'h0)) |=> (down_counter == ($past(down_counter) - 4'h1))
    );

    // In down mode, the down counter wraps from 0 to 15.
    check_down_counter_wraps: assert property (
        @(posedge clk) (!load && !up_down && (down_counter == 4'h0)) |=> (down_counter == 4'hf)
    );

    // In up mode, the down counter holds its value.
    check_down_counter_holds_in_up_mode: assert property (
        @(posedge clk) (!load && up_down) |=> (down_counter == $past(down_counter))
    );

endmodule

rtl:
module top_module (
    input clk,
    input reset,
    input [7:0] a,
    input [7:0] b,
    input [7:0] c,
    input [7:0] d,
    output [7:0] out1,
    output [7:0] out2
);

    wire [15:0] sum;
    wire gt, lt, eq;

    comparator_8bit comp (
        .a(sum[7:0]),
        .b(8'h55),
        .gt(gt),
        .lt(lt),
        .eq(eq)
    );

    adder_16bit add (
        .a({8'b0, a}),
        .b({8'b0, b}),
        .sum(sum)
    );

    assign out1 = (gt) ? sum[7:0] : (lt) ? c : (eq) ? a : 8'b0;
    assign out2 = (gt) ? 8'b0 : (lt) ? d : (eq) ? b : 8'b0;

endmodule

module comparator_8bit (
    input [7:0] a,
    input [7:0] b,
    output gt,
    output lt,
    output eq
);

    assign gt = (a > b);
    assign lt = (a < b);
    assign eq = (a == b);

endmodule

module adder_16bit (
    input [15:0] a,
    input [15:0] b,
    output [15:0] sum
);

    assign sum = a + b;

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic reset,
    input logic [7:0] a,
    input logic [7:0] b,
    input logic [7:0] c,
    input logic [7:0] d,
    input logic [7:0] out1,
    input logic [7:0] out2
);

    // out1 follows the selected branch from the low byte of the adder result.
    check_out1_mux_function: assert property (
        @(posedge clk) disable iff (reset)
        (
            ((({8'b0, a} + {8'b0, b})[7:0] > 8'h55) && (out1 == ({8'b0, a} + {8'b0, b})[7:0])) ||
            ((({8'b0, a} + {8'b0, b})[7:0] < 8'h55) && (out1 == c)) ||
            ((({8'b0, a} + {8'b0, b})[7:0] == 8'h55) && (out1 == a))
        )
    );

    // out2 follows the selected branch from the low byte of the adder result.
    check_out2_mux_function: assert property (
        @(posedge clk) disable iff (reset)
        (
            ((({8'b0, a} + {8'b0, b})[7:0] > 8'h55) && (out2 == 8'b0)) ||
            ((({8'b0, a} + {8'b0, b})[7:0] < 8'h55) && (out2 == d)) ||
            ((({8'b0, a} + {8'b0, b})[7:0] == 8'h55) && (out2 == b))
        )
    );

    // Greater-than comparison drives sum low byte to out1 and zero to out2.
    check_gt_branch_outputs: assert property (
        @(posedge clk) disable iff (reset)
        (({8'b0, a} + {8'b0, b})[7:0] > 8'h55) |-> (
            (out1 == ({8'b0, a} + {8'b0, b})[7:0]) &&
            (out2 == 8'b0)
        )
    );

    // Less-than comparison drives c to out1 and d to out2.
    check_lt_branch_outputs: assert property (
        @(posedge clk) disable iff (reset)
        (({8'b0, a} + {8'b0, b})[7:0] < 8'h55) |-> (
            (out1 == c) &&
            (out2 == d)
        )
    );

    // Equality comparison drives a to out1 and b to out2.
    check_eq_branch_outputs: assert property (
        @(posedge clk) disable iff (reset)
        (({8'b0, a} + {8'b0, b})[7:0] == 8'h55) |-> (
            (out1 == a) &&
            (out2 == b)
        )
    );

endmodule

rtl:
module priority_encoder_twos_complement (
    input [3:0] in,
    output reg [1:0] X,
    output reg Y,
    output reg [3:0] out
);

reg [3:0] in_twos_comp;

// Two's complement module
always @(*) begin
    if (in[3] == 1) begin
        in_twos_comp = ~in + 1;
        Y = 1;
    end
    else begin
        in_twos_comp = in;
        Y = 0;
    end
end

// Priority encoder module
always @(*) begin
    case(in_twos_comp)
        4'b0001: X = 0;
        4'b0010: X = 1;
        4'b0100: X = 2;
        4'b1000: X = 3;
        default: X = 2'b11;
    endcase
end

// Output
always @(*) begin
    if (in[3] == 1) begin
        out = in_twos_comp;
    end
    else begin
        out = X;
    end
end

endmodule

module top_module (
    input [3:0] in,
    output reg [1:0] X,
    output reg Y,
    output reg [3:0] out,
    output reg [4:0] sum
);

priority_encoder_twos_complement encoder(in, X, Y, out);

// Adder module
always @(*) begin
    sum = out + X;
end

endmodule

sva:
module top_module_assertions (
    input logic [3:0] in,
    input logic [1:0] X,
    input logic Y,
    input logic [3:0] out,
    input logic [4:0] sum
);

    // Y follows the sign bit of in.
    check_y_matches_sign_bit: assert property (
        @($global_clock) (Y == in[3])
    );

    // Negative inputs drive out to the 4-bit two's complement of in.
    check_negative_out_is_twos_comp: assert property (
        @($global_clock) in[3] |-> (out == ((~in) + 4'b0001))
    );

    // Non-negative inputs drive out to the zero-extended encoded X value.
    check_nonnegative_out_is_zero_extended_x: assert property (
        @($global_clock) !in[3] |-> (out == {2'b00, X})
    );

    // Effective value 0001 encodes to X == 0.
    check_encode_eff_0001_to_x0: assert property (
        @($global_clock)
        (((in[3] ? ((~in) + 4'b0001) : in) == 4'b0001)) |-> (X == 2'd0)
    );

    // Effective value 0010 encodes to X == 1.
    check_encode_eff_0010_to_x1: assert property (
        @($global_clock)
        (((in[3] ? ((~in) + 4'b0001) : in) == 4'b0010)) |-> (X == 2'd1)
    );

    // Effective value 0100 encodes to X == 2.
    check_encode_eff_0100_to_x2: assert property (
        @($global_clock)
        (((in[3] ? ((~in) + 4'b0001) : in) == 4'b0100)) |-> (X == 2'd2)
    );

    // Effective value 1000 encodes to X == 3.
    check_encode_eff_1000_to_x3: assert property (
        @($global_clock)
        (((in[3] ? ((~in) + 4'b0001) : in) == 4'b1000)) |-> (X == 2'd3)
    );

    // Non-one-hot effective values fall into the default X == 3 case.
    check_encode_non_onehot_defaults_to_x3: assert property (
        @($global_clock)
        (((in[3] ? ((~in) + 4'b0001) : in) != 4'b0001) &&
         ((in[3] ? ((~in) + 4'b0001) : in) != 4'b0010) &&
         ((in[3] ? ((~in) + 4'b0001) : in) != 4'b0100) &&
         ((in[3] ? ((~in) + 4'b0001) : in) != 4'b1000)) |-> (X == 2'd3)
    );

    // sum is the zero-extended 4-bit result of out + X.
    check_sum_matches_out_plus_x: assert property (
        @($global_clock) (sum == {1'b0, (out + X)})
    );

    // The MSB of sum is always zero because the adder result is 4 bits wide.
    check_sum_msb_is_zero: assert property (
        @($global_clock) (sum[4] == 1'b0)
    );

endmodule

