module top_module(
    input wire a, b, c, // Inputs to the multiplexer
    input wire [15:0] in, // Input to the splitter
    output wire [7:0] out_hi, // Upper byte of the splitter output
    output wire [7:0] out_lo, // Lower byte of the splitter output
    output wire [23:0] final_out // Final 24-bit output from the functional module
);

// Multiplexer
wire w, x, y, z;
assign w = a;
assign x = b;
assign y = b;
assign z = c;

// Splitter
wire [7:0] in_hi, in_lo;
assign in_hi = in[15:8];
assign in_lo = in[7:0];

// Functional module
wire [23:0] sum;
assign sum = {8'b0, w} + {8'b0, x} + {8'b0, y} + {8'b0, z} + {8'b0, in_hi} + {8'b0, in_lo};

// Output assignments
assign out_hi = in_hi;
assign out_lo = in_lo;
assign final_out = sum;

endmodule

sva:
module top_module_assertions (
    input logic        a,
    input logic        b,
    input logic        c,
    input logic [15:0] in,
    input logic [7:0]  out_hi,
    input logic [7:0]  out_lo,
    input logic [23:0] final_out
);

    // Purely combinational DUT; assertions sample on the formal global clock.

    // out_hi must mirror the upper byte of in.
    check_out_hi_split: assert property (
        @($global_clock)
        out_hi == in[15:8]
    );

    // out_lo must mirror the lower byte of in.
    check_out_lo_split: assert property (
        @($global_clock)
        out_lo == in[7:0]
    );

    // final_out must equal the sum of a, b, b, c, and the two input bytes.
    check_final_out_function: assert property (
        @($global_clock)
        final_out == ({23'b0, a} +
                      {23'b0, b} +
                      {23'b0, b} +
                      {23'b0, c} +
                      {16'b0, in[15:8]} +
                      {16'b0, in[7:0]})
    );

    // The upper byte of final_out must remain zero.
    check_final_out_upper_byte_zero: assert property (
        @($global_clock)
        final_out[23:16] == 8'h00
    );

    // With no control-bit contribution, final_out must be the sum of the split bytes.
    check_data_only_sum: assert property (
        @($global_clock)
        (!a && !b && !c) |-> (final_out == ({16'b0, out_hi} + {16'b0, out_lo}))
    );

    // With zero input data, final_out must be the sum of the control-bit paths.
    check_control_only_sum: assert property (
        @($global_clock)
        (in == 16'h0000) |-> (final_out == ({23'b0, a} +
                                            {23'b0, b} +
                                            {23'b0, b} +
                                            {23'b0, c}))
    );

    // All-zero inputs must produce all-zero outputs.
    check_zero_inputs_zero_outputs: assert property (
        @($global_clock)
        (!a && !b && !c && (in == 16'h0000)) |->
            ((out_hi == 8'h00) && (out_lo == 8'h00) && (final_out == 24'h000000))
    );

    // If only b is high and in is zero, b must contribute twice.
    check_b_double_contribution: assert property (
        @($global_clock)
        (!a && b && !c && (in == 16'h0000)) |-> (final_out == 24'd2)
    );

endmodule

rtl:
module top_module (
    input [3:0] A,
    input [3:0] B,
    input [7:0] C,
    output [7:0] final_output
);

    wire [7:0] multiplier_output;
    wire [1:0] comparator_output;

    multiplier mult(A, B, multiplier_output);
    mag_comparator comp(multiplier_output, C, comparator_output);
    functional_module func(multiplier_output, comparator_output, final_output);

endmodule
module multiplier (
    input [3:0] A,
    input [3:0] B,
    output [7:0] product
);

    assign product = {4'b0, A} * {4'b0, B};

endmodule
module mag_comparator (
    input [7:0] comp_input,
    input [7:0] C,
    output reg [1:0] result
);

    always @(*) begin
        if (comp_input == C) begin
            result = 2'b00;
        end else if (comp_input > C) begin
            result = 2'b01;
        end else begin
            result = 2'b10;
        end
    end

endmodule
module functional_module (
    input [7:0] multiplier_output,
    input [1:0] comparator_output,
    output [7:0] final_output
);

    assign final_output = multiplier_output + {2'b0, comparator_output};

endmodule

sva:
module top_module_sva (
    input logic        clk,
    input logic [3:0]  A,
    input logic [3:0]  B,
    input logic [7:0]  C,
    input logic [7:0]  final_output,
    input logic [7:0]  multiplier_output,
    input logic [1:0]  comparator_output
);

    // multiplier_output is the unsigned product of A and B.
    check_multiplier_product: assert property (
        @(posedge clk) multiplier_output == (A * B)
    );

    // comparator_output is 00 when the product equals C.
    check_comparator_equal_code: assert property (
        @(posedge clk) (multiplier_output == C) |-> (comparator_output == 2'b00)
    );

    // comparator_output is 01 when the product is greater than C.
    check_comparator_greater_code: assert property (
        @(posedge clk) (multiplier_output > C) |-> (comparator_output == 2'b01)
    );

    // comparator_output is 10 when the product is less than C.
    check_comparator_less_code: assert property (
        @(posedge clk) (multiplier_output < C) |-> (comparator_output == 2'b10)
    );

    // comparator_output never uses the unused 11 encoding.
    check_comparator_valid_code: assert property (
        @(posedge clk) comparator_output != 2'b11
    );

    // final_output adds the comparator code to the multiplier output.
    check_final_output_sum: assert property (
        @(posedge clk) final_output == (multiplier_output + {2'b0, comparator_output})
    );

    // final_output matches the product when the product equals C.
    check_final_output_equal_case: assert property (
        @(posedge clk) ((A * B) == C) |-> (final_output == (A * B))
    );

    // final_output is product plus 1 when the product is greater than C.
    check_final_output_greater_case: assert property (
        @(posedge clk) ((A * B) > C) |-> (final_output == ((A * B) + 8'd1))
    );

    // final_output is product plus 2 when the product is less than C.
    check_final_output_less_case: assert property (
        @(posedge clk) ((A * B) < C) |-> (final_output == ((A * B) + 8'd2))
    );

    // final_output matches the complete top-level combinational function.
    check_top_level_function: assert property (
        @(posedge clk)
        final_output == ((A * B) + (((A * B) == C) ? 8'd0 : (((A * B) > C) ? 8'd1 : 8'd2)))
    );

endmodule

