        !clk_en |=> (st13 == $past(st13) &&
                     st14 == $past(st14) &&
                     st15 == $past(st15) &&
                     st16 == $past(st16))
    );

    // When disabled, stages 17-20 hold their values.
    check_hold_stage_17_to_20: assert property (
        @(posedge clk)
        !clk_en |=> (st17 == $past(st17) &&
                     st18 == $past(st18) &&
                     st19 == $past(st19) &&
                     st20 == $past(st20))
    );

    // When disabled, stages 21-24 hold their values.
    check_hold_stage_21_to_24: assert property (
        @(posedge clk)
        !clk_en |=> (st21 == $past(st21) &&
                     st22 == $past(st22) &&
                     st23 == $past(st23) &&
                     st24 == $past(st24))
    );

    sequence enabled_24_cycles;
        clk_en[*24];
    endsequence

    // After 24 consecutive enabled cycles, st24 reflects din from 24 cycles earlier.
    check_end_to_end_24_cycle_shift: assert property (
        @(posedge clk)
        enabled_24_cycles |=> (st24 == $past(din, 24))
    );

endmodule

rtl:
module arithmetic_operation(
  input ADDSUB,
  input [26:0] D_DATA,
  input INMODE2,
  input [26:0] PREADD_AB,
  output [26:0] AD
);

  wire [26:0] D_DATA_mux;

  assign D_DATA_mux = INMODE2 ? D_DATA : 27'b0;
  assign AD = ADDSUB ? (D_DATA_mux - PREADD_AB) : (D_DATA_mux + PREADD_AB);

endmodule

sva:
module arithmetic_operation_sva (
    input logic clk,
    input logic ADDSUB,
    input logic [26:0] D_DATA,
    input logic INMODE2,
    input logic [26:0] PREADD_AB,
    input logic [26:0] AD
);

    // AD must match the combinational add/sub result selected by ADDSUB and INMODE2.
    check_ad_matches_rtl_equation: assert property (
        @(posedge clk)
        AD == (ADDSUB ? ((INMODE2 ? D_DATA : 27'b0) - PREADD_AB)
                      : ((INMODE2 ? D_DATA : 27'b0) + PREADD_AB))
    );

    // With INMODE2 low and add selected, AD equals PREADD_AB.
    check_add_with_inmode2_low: assert property (
        @(posedge clk)
        (!INMODE2 && !ADDSUB) |-> (AD == PREADD_AB)
    );

    // With INMODE2 low and subtract selected, AD equals 0 minus PREADD_AB.
    check_sub_with_inmode2_low: assert property (
        @(posedge clk)
        (!INMODE2 && ADDSUB) |-> (AD == (27'b0 - PREADD_AB))
    );

    // With INMODE2 high and add selected, AD equals D_DATA plus PREADD_AB.
    check_add_with_inmode2_high: assert property (
        @(posedge clk)
        (INMODE2 && !ADDSUB) |-> (AD == (D_DATA + PREADD_AB))
    );

    // With INMODE2 high and subtract selected, AD equals D_DATA minus PREADD_AB.
    check_sub_with_inmode2_high: assert property (
        @(posedge clk)
        (INMODE2 && ADDSUB) |-> (AD == (D_DATA - PREADD_AB))
    );

endmodule

