    input  A2;
    input  B1;
    input  C1;
    input  D1;

    wire and0_out ;
    wire or0_out_X;

    and and0 (and0_out , A1, A2              );
    or  or0  (or0_out_X, C1, B1, and0_out, D1);
    buf buf0 (X        , or0_out_X           );

endmodule

sva:
module sky130_fd_sc_ms__a2111o_assertions (
    input logic clk,
    input logic X,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic C1,
    input logic D1
);

    // X matches the implemented OR-of-four function.
    check_exact_function: assert property (
        @(posedge clk) X == (C1 || B1 || D1 || (A1 && A2))
    );

    // Any asserted direct OR input forces X high.
    check_direct_or_inputs_drive_high: assert property (
        @(posedge clk) (C1 || B1 || D1) |-> X
    );

    // The A1/A2 product term forces X high.
    check_and_term_drives_high: assert property (
        @(posedge clk) (A1 && A2) |-> X
    );

    // If all contributing terms are low, X must be low.
    check_all_terms_low_drive_low: assert property (
        @(posedge clk) (!C1 && !B1 && !D1 && (!A1 || !A2)) |-> !X
    );

    // A low X means no input term is asserting the OR.
    check_low_output_implies_low_terms: assert property (
        @(posedge clk) !X |-> (!C1 && !B1 && !D1 && (!A1 || !A2))
    );

    // With direct OR inputs low, a high X must come from A1&A2.
    check_high_output_requires_and_term_without_direct_or: assert property (
        @(posedge clk) (X && !C1 && !B1 && !D1) |-> (A1 && A2)
    );

    // Stable sampled inputs imply a stable sampled output.
    check_sampled_stability: assert property (
        @(posedge clk) $stable({A1, A2, B1, C1, D1}) |-> $stable(X)
    );

endmodule

rtl:
module Adder4(
    input [3:0] A,
    input [3:0] B,
    output [4:0] S
);

  wire [0:0] Q1, Q2, Q3, Q4, Q5;
  wire [0:0] ready_add_subt1, ready_add_subt2, ready_add_subt3, ready_add_subt4;

  Adder Sub1(A[0], B[0], ready_add_subt1, Q1, ready_add_subt2);
  Adder Sub2(A[1], B[1], ready_add_subt2, Q2, ready_add_subt3);
  Adder Sub3(A[2], B[2], ready_add_subt3, Q3, ready_add_subt4);
  Adder Sub4(A[3], B[3], ready_add_subt4, Q4, S[4]);

  assign S[0] = Q1;
  assign S[1] = Q2;
  assign S[2] = Q3;
  assign S[3] = Q4;

  assign ready_add_subt1 = 1'b1;

endmodule

module Adder(
    input A,
    input B,
    input Cin,
    output S,
    output ready_add_subt
);

  wire Cn;

  xor (S, A, B);
  xor (Cn, S, Cin);
  not (ready_add_subt, Cn);

endmodule

sva:
module Adder4_sva (
    input logic       clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [4:0] S
);

    // S[0] is the XOR of A[0] and B[0].
    check_sum_bit0_xor: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0])
    );

    // S[1] is the XOR of A[1] and B[1].
    check_sum_bit1_xor: assert property (
        @(posedge clk) S[1] == (A[1] ^ B[1])
    );

    // S[2] is the XOR of A[2] and B[2].
    check_sum_bit2_xor: assert property (
        @(posedge clk) S[2] == (A[2] ^ B[2])
    );

    // S[3] is the XOR of A[3] and B[3].
    check_sum_bit3_xor: assert property (
        @(posedge clk) S[3] == (A[3] ^ B[3])
    );

    // S[4] is the reduction XNOR of the bitwise XOR result.
    check_msb_parity_xnor: assert property (
        @(posedge clk) S[4] == (~^(A ^ B))
    );

endmodule

rtl:
module ceespu_compare(
         input [31:0] I_dataA,
         input [31:0] I_dataB,
         input [2:0] I_branchOp,
         input I_Cin,
         output reg O_doBranch
       );

always @* begin
  case (I_branchOp)
    0: O_doBranch = (I_dataA == I_dataB);
    1: O_doBranch = (I_dataA != I_dataB);
    2: O_doBranch = (I_dataA > I_dataB);
    3: O_doBranch = (I_dataA >= I_dataB);
    4: O_doBranch = ($signed(I_dataA) > $signed(I_dataB));
    5: O_doBranch = ($signed(I_dataA) >= $signed(I_dataB));
    6: O_doBranch = I_Cin;
    7: O_doBranch = 1;
  endcase
end

endmodule

sva:
module ceespu_compare_sva (
    input logic [31:0] I_dataA,
    input logic [31:0] I_dataB,
    input logic [2:0]  I_branchOp,
    input logic        I_Cin,
    input logic        O_doBranch
);

    // No RTL clock or reset; sample properties on Jasper global clock.

    // Op 0 branches on equality.
    check_branch_eq: assert property (
        @($global_clock)
        (I_branchOp === 3'd0) |-> (O_doBranch === (I_dataA == I_dataB))
    );

    // Op 1 branches on inequality.
    check_branch_ne: assert property (
        @($global_clock)
        (I_branchOp === 3'd1) |-> (O_doBranch === (I_dataA != I_dataB))
    );

    // Op 2 branches on unsigned greater-than.
    check_branch_gt_unsigned: assert property (
        @($global_clock)
        (I_branchOp === 3'd2) |-> (O_doBranch === (I_dataA > I_dataB))
    );

    // Op 3 branches on unsigned greater-than-or-equal.
    check_branch_ge_unsigned: assert property (
        @($global_clock)
        (I_branchOp === 3'd3) |-> (O_doBranch === (I_dataA >= I_dataB))
    );

    // Op 4 branches on signed greater-than.
    check_branch_gt_signed: assert property (
        @($global_clock)
        (I_branchOp === 3'd4) |-> (O_doBranch === ($signed(I_dataA) > $signed(I_dataB)))
    );

    // Op 5 branches on signed greater-than-or-equal.
    check_branch_ge_signed: assert property (
        @($global_clock)
        (I_branchOp === 3'd5) |-> (O_doBranch === ($signed(I_dataA) >= $signed(I_dataB)))
    );

    // Op 6 forwards the carry-in.
    check_branch_cin: assert property (
        @($global_clock)
        (I_branchOp === 3'd6) |-> (O_doBranch === I_Cin)
    );

    // Op 7 always branches.
    check_branch_always: assert property (
        @($global_clock)
        (I_branchOp === 3'd7) |-> (O_doBranch === 1'b1)
    );

    // Stable inputs keep the combinational output stable.
    check_output_stable_when_inputs_stable: assert property (
        @($global_clock)
        (!$initstate &&
         $stable(I_dataA) &&
         $stable(I_dataB) &&
         $stable(I_branchOp) &&
         $stable(I_Cin)) |-> $stable(O_doBranch)
    );

    // For ops that do not use I_Cin, changing only I_Cin does not change the output.
    check_cin_irrelevant_for_non_cin_ops: assert property (
        @($global_clock)
        (!$initstate &&
         ((I_branchOp === 3'd0) ||
          (I_branchOp === 3'd1) ||
          (I_branchOp === 3'd2) ||
          (I_branchOp === 3'd3) ||
          (I_branchOp === 3'd4) ||
          (I_branchOp === 3'd5) ||
          (I_branchOp === 3'd7)) &&
         $stable(I_dataA) &&
         $stable(I_dataB) &&
         $stable(I_branchOp) &&
         !$stable(I_Cin)) |-> $stable(O_doBranch)
    );

    // In the carry-in op, data changes alone do not affect the output.
    check_data_irrelevant_for_cin_op: assert property (
        @($global_clock)
        (!$initstate &&
         (I_branchOp === 3'd6) &&
         $stable(I_branchOp) &&
         $stable(I_Cin) &&
         (!$stable(I_dataA) || !$stable(I_dataB))) |-> $stable(O_doBranch)
    );

endmodule

rtl:
module parity_calculator(
    input [15:0] data,
    output parity
);

    wire [7:0] data_low;
    wire [7:0] data_high;
    wire [3:0] parity_low;
    wire [3:0] parity_high;
    wire parity_odd;

    // Split the input data into two 8-bit parts
    assign data_low = data[7:0];
    assign data_high = data[15:8];

    // Calculate the parity for each 8-bit part
    assign parity_low = {data_low[0], data_low[1], data_low[2], data_low[3]} ^ {data_low[4], data_low[5], data_low[6], data_low[7]};
    assign parity_high = {data_high[0], data_high[1], data_high[2], data_high[3]} ^ {data_high[4], data_high[5], data_high[6], data_high[7]};

    // Calculate the parity for the entire 16-bit input data
    assign parity_odd = parity_low[0] ^ parity_low[1] ^ parity_low[2] ^ parity_low[3] ^ parity_high[0] ^ parity_high[1] ^ parity_high[2] ^ parity_high[3];

    // Set the parity bit to 1 if the number of 1's in the input data is odd, and 0 if it is even
    assign parity = (parity_odd == 1'b1) ? 1'b1 : 1'b0;

endmodule

sva:
module parity_calculator_sva (
    input logic        clk,
    input logic [15:0] data,
    input logic        parity
);

    // Parity equals the XOR reduction of all 16 data bits.
    check_parity_matches_reduction_xor: assert property (
        @(posedge clk) parity == (^data)
    );

    // Parity equals the XOR of the low-byte and high-byte parities.
    check_parity_matches_byte_parities: assert property (
        @(posedge clk) parity == ((^data[7:0]) ^ (^data[15:8]))
    );

    // Parity matches the pairwise XOR structure used in the RTL.
    check_parity_matches_pairwise_structure: assert property (
        @(posedge clk)
        parity == (
            (data[0]  ^ data[4])  ^
            (data[1]  ^ data[5])  ^
            (data[2]  ^ data[6])  ^
            (data[3]  ^ data[7])  ^
            (data[8]  ^ data[12]) ^
            (data[9]  ^ data[13]) ^
            (data[10] ^ data[14]) ^
            (data[11] ^ data[15])
        )
    );

    // All-zero input produces even parity.
    check_zero_data_even_parity: assert property (
        @(posedge clk) (data == 16'h0000) |-> (parity == 1'b0)
    );

    // All-one input produces even parity.
    check_all_ones_even_parity: assert property (
        @(posedge clk) (data == 16'hFFFF) |-> (parity == 1'b0)
    );

    // Any one-hot input produces odd parity.
    check_onehot_data_odd_parity: assert property (
        @(posedge clk) $onehot(data) |-> (parity == 1'b1)
    );

endmodule

