module calculator_sva (
    input logic       clk,
    input logic [7:0] in1,
    input logic [7:0] in2,
    input logic [1:0] op,
    input logic [7:0] out
);

    // RTL is combinational with no reset; clk is a sampling clock.

    // Addition mode drives the 8-bit sum.
    check_addition_mode: assert property (
        @(posedge clk)
        (op == 2'b00) |-> (out == ((in1 + in2) & 8'hFF))
    );

    // Subtraction mode drives the 8-bit difference.
    check_subtraction_mode: assert property (
        @(posedge clk)
        (op == 2'b01) |-> (out == ((in1 - in2) & 8'hFF))
    );

    // Multiplication mode drives the low 8 bits of the product.
    check_multiplication_mode: assert property (
        @(posedge clk)
        (op == 2'b10) |-> (out == ((in1 * in2) & 8'hFF))
    );

    // Division mode drives the quotient when the divisor is nonzero.
    check_division_mode: assert property (
        @(posedge clk)
        (op == 2'b11 && in2 != 8'h00) |-> (out == ((in1 / in2) & 8'hFF))
    );

endmodule

module counter_sva (
    input logic       clk,
    input logic       reset,
    input logic       enable,
    input logic [3:0] count
);

    // Clock: clk; reset: active-high synchronous reset.
    // Function: 4-bit counter that increments when enabled and wraps from 10 to 0.

    // Reset clears the counter to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'b0000)
    );

    // When disabled, the counter holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset)
        (!enable) |=> (count == $past(count))
    );

    // When enabled and not at 10, the counter increments by one.
    check_increment_when_enabled: assert property (
        @(posedge clk) disable iff (reset)
        (enable && (count != 4'b1010)) |=> (count == ($past(count) + 4'b0001))
    );

    // When enabled at 10, the counter wraps to zero.
    check_wrap_at_ten: assert property (
        @(posedge clk) disable iff (reset)
        (enable && (count == 4'b1010)) |=> (count == 4'b0000)
    );

endmodule

rtl:
module full_adder (
    input A,
    input B,
    input C_in,
    output S,
    output C_out
);

    assign S = A ^ B ^ C_in;
    assign C_out = (A & B) | (C_in & (A ^ B));

endmodule

module adder_4bit (
    input [3:0] A,
    input [3:0] B,
    output [3:0] S,
    output C_out
);

    wire [3:0] sum;
    wire carry_1, carry_2, carry_3;

    full_adder fa_1 (
        .A(A[0]),
        .B(B[0]),
        .C_in(1'b0),
        .S(sum[0]),
        .C_out(carry_1)
    );

    full_adder fa_2 (
        .A(A[1]),
        .B(B[1]),
        .C_in(carry_1),
        .S(sum[1]),
        .C_out(carry_2)
    );

    full_adder fa_3 (
        .A(A[2]),
        .B(B[2]),
        .C_in(carry_2),
        .S(sum[2]),
        .C_out(carry_3)
    );

    full_adder fa_4 (
        .A(A[3]),
        .B(B[3]),
        .C_in(carry_3),
        .S(sum[3]),
        .C_out(C_out)
    );

    assign S = sum;

endmodule

sva:
module adder_4bit_sva (
    input logic       clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] S,
    input logic       C_out
);

    // Combined outputs must equal the 5-bit sum of A and B.
    check_total_addition: assert property (
        @(posedge clk)
        {C_out, S} == ({1'b0, A} + {1'b0, B})
    );

    // Bit 0 sum is the XOR of the least-significant input bits.
    check_bit0_sum: assert property (
        @(posedge clk)
        S[0] == (A[0] ^ B[0])
    );

    // Bit 1 sum includes the carry generated by bit 0.
    check_bit1_ripple_sum: assert property (
        @(posedge clk)
        S[1] == (A[1] ^ B[1] ^ (A[0] & B[0]))
    );

    // Bit 2 sum includes the ripple carry from bits 0 and 1.
    check_bit2_ripple_sum: assert property (
        @(posedge clk)
        S[2] == (A[2] ^ B[2] ^ ((A[1] & B[1]) | ((A[0] & B[0]) & (A[1] ^ B[1]))))
    );

    // Bit 3 sum includes the ripple carry from bits 0 through 2.
    check_bit3_ripple_sum: assert property (
        @(posedge clk)
        S[3] == (A[3] ^ B[3] ^ ((A[2] & B[2]) | (((A[1] & B[1]) | ((A[0] & B[0]) & (A[1] ^ B[1]))) & (A[2] ^ B[2]))))
    );

    // Final carry-out follows the full-adder carry equation at bit 3.
    check_final_carry: assert property (
        @(posedge clk)
        C_out == ((A[3] & B[3]) | (((A[2] & B[2]) | (((A[1] & B[1]) | ((A[0] & B[0]) & (A[1] ^ B[1]))) & (A[2] ^ B[2]))) & (A[3] ^ B[3])))
    );

    // Adding zero on A leaves B unchanged and produces no carry.
    check_add_zero_from_a: assert property (
        @(posedge clk)
        (A == 4'b0000) |-> ((S == B) && (C_out == 1'b0))
    );

