    );

    // VGND low forces X low.
    check_output_low_when_vgnd_low: assert property (
        @($global_clock) !VGND |-> !X
    );

    // X high requires all three functional inputs high.
    check_output_high_requires_all_inputs: assert property (
        @($global_clock) X |-> (A && VPWR && VGND)
    );

endmodule

