module mux_4to1_structural (
  input [3:0] data_in,
  input [1:0] select,
  output reg data_out
);

  wire and1, and2, and3, and4;
  wire or1, or2;

  assign and1 = (select == 2'b00) ? data_in[0] : 1'b0;
  assign and2 = (select == 2'b01) ? data_in[1] : 1'b0;
  assign and3 = (select == 2'b10) ? data_in[2] : 1'b0;
  assign and4 = (select == 2'b11) ? data_in[3] : 1'b0;

  assign or1 = and1 | and2;
  assign or2 = and3 | and4;

  always @* begin
    if (select == 2'b00 || select == 2'b01)
      data_out = or1;
    else
      data_out = or2;
  end

endmodule

sva:
module mux_4to1_structural_sva (
    input logic [3:0] data_in,
    input logic [1:0] select,
    input logic data_out,
    input logic and1,
    input logic and2,
    input logic and3,
    input logic and4,
    input logic or1,
    input logic or2
);

