    // Sequential-only logic on clk; reset is active high and asynchronous.
    // count is a 4-bit output that increments and wraps from 9 to 0.

    // A sampled reset forces the counter to be 0 on the next clock.
    reset_forces_zero_next: assert property (
        @(posedge clk) reset |=> (count == 4'd0)
    );

    // A sampled value of 9 wraps back to 0 on the next clock.
    wrap_from_nine: assert property (
        @(posedge clk) disable iff (reset)
        (count == 4'd9) |=> (count == 4'd0)
    );

    // Any non-9 value increments, unless an async reset pulse clears count to 0 between clocks.
    increment_or_clear_from_non_nine: assert property (
        @(posedge clk) disable iff (reset)
        (count != 4'd9) |=> ((count == ($past(count) + 4'd1)) || (count == 4'd0))
    );

endmodule

rtl:
module ripple_carry_adder (
    input [3:0] A,
    input [3:0] B,
    output [3:0] SUM,
    output CARRY
);

reg [3:0] temp_SUM;
wire [3:0] temp_CARRY;

// Stage 1
always @ (*) begin
    {temp_CARRY[0], temp_SUM[0]} = A[0] + B[0];
end

// Stage 2
always @ (*) begin
    {temp_CARRY[1], temp_SUM[1]} = A[1] + B[1] + temp_CARRY[0];
end

// Stage 3
always @ (*) begin
    {temp_CARRY[2], temp_SUM[2]} = A[2] + B[2] + temp_CARRY[1];
end

// Stage 4
always @ (*) begin
    {CARRY, temp_SUM[3]} = A[3] + B[3] + temp_CARRY[2];
end

assign SUM = temp_SUM;

endmodule

sva:
module ripple_carry_adder_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] SUM,
    input logic CARRY
);

    // Full output matches the zero-extended sum of A and B.
    check_full_addition: assert property (
        @($global_clock) {CARRY, SUM} == ({1'b0, A} + {1'b0, B})
    );

    // SUM[0] is the stage-1 sum of A[0] and B[0].
    check_sum_bit0: assert property (
        @($global_clock) SUM[0] == (A[0] ^ B[0])
    );

    // SUM[1] includes the carry from bit 0.
    check_sum_bit1: assert property (
        @($global_clock) SUM[1] == (A[1] ^ B[1] ^ (A[0] & B[0]))
    );

    // SUM[2] includes the propagated carry from bits 0 and 1.
    check_sum_bit2: assert property (
        @($global_clock)
        SUM[2] == (A[2] ^ B[2] ^
                   ((A[1] & B[1]) |
                    ((A[1] ^ B[1]) & (A[0] & B[0]))))
    );

    // SUM[3] includes the propagated carry from bits 0 through 2.
    check_sum_bit3: assert property (
        @($global_clock)
        SUM[3] == (A[3] ^ B[3] ^
                   ((A[2] & B[2]) |
                    ((A[2] ^ B[2]) &
                     ((A[1] & B[1]) |
                      ((A[1] ^ B[1]) & (A[0] & B[0]))))))
    );

    // CARRY is the final carry-out of the 4-bit ripple chain.
    check_carry_out: assert property (
        @($global_clock)
        CARRY == ((A[3] & B[3]) |
                  ((A[3] ^ B[3]) &
                   ((A[2] & B[2]) |
                    ((A[2] ^ B[2]) &
                     ((A[1] & B[1]) |
                      ((A[1] ^ B[1]) & (A[0] & B[0])))))))
    );

endmodule

module add_4bit_sva (
    input logic       clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] SUM
);

    // SUM[0] matches the RTL XOR of the least-significant input bits.
    check_sum_bit0: assert property (
        @(posedge clk) SUM[0] == (A[0] ^ B[0])
    );

    // SUM[1] matches the RTL XOR with the bit-0 generate term.
    check_sum_bit1: assert property (
        @(posedge clk) SUM[1] == ((A[1] ^ B[1]) ^ (A[0] & B[0]))
    );

    // SUM[2] matches the RTL XOR with the OR of lower generate terms.
    check_sum_bit2: assert property (
        @(posedge clk) SUM[2] == ((A[2] ^ B[2]) ^ ((A[1] & B[1]) | (A[0] & B[0])))
    );

    // SUM[3] matches the RTL XOR with the OR of all lower generate terms.
    check_sum_bit3: assert property (
        @(posedge clk) SUM[3] == ((A[3] ^ B[3]) ^ ((A[2] & B[2]) | (A[1] & B[1]) | (A[0] & B[0])))
    );

    // The full SUM bus matches the combined RTL equations.
    check_sum_vector: assert property (
        @(posedge clk) SUM == {
            ((A[3] ^ B[3]) ^ ((A[2] & B[2]) | (A[1] & B[1]) | (A[0] & B[0]))),
            ((A[2] ^ B[2]) ^ ((A[1] & B[1]) | (A[0] & B[0]))),
            ((A[1] ^ B[1]) ^ (A[0] & B[0])),
            (A[0] ^ B[0])
        }
    );

endmodule

rtl:
module adder(
    input [7:0] A,
    input [7:0] B,
    output [7:0] sum
);

    wire [7:0] carry;

    // first full adder
    full_adder FA0(
        .a(A[0]),
        .b(B[0]),
        .c_in(1'b0),
        .sum(sum[0]),
        .c_out(carry[0])
    );

    // remaining full adders
    generate
        genvar i;
        for (i = 1; i < 8; i = i + 1) begin : FA_GEN
            full_adder FA(
                .a(A[i]),
                .b(B[i]),
                .c_in(carry[i-1]),
                .sum(sum[i]),
                .c_out(carry[i])
            );
        end
    endgenerate

endmodule

// full adder module
module full_adder(
    input a,
    input b,
    input c_in,
    output sum,
    output c_out
);

    assign sum = a ^ b ^ c_in;
    assign c_out = (a & b) | (a & c_in) | (b & c_in);

endmodule

sva:
module adder_sva (
    input logic       clk,
    input logic [7:0] A,
    input logic [7:0] B,
    input logic [7:0] sum
);

    // DUT is combinational; clk is the sampling clock for these assertions.

    // Sum must match the 8-bit addition of A and B.
    check_byte_addition: assert property (
        @(posedge clk) sum == (A + B)
    );

    // Bit 0 must be A[0] xor B[0] because the first carry-in is tied low.
    check_lsb_xor: assert property (
        @(posedge clk) sum[0] == (A[0] ^ B[0])
    );

    // The low nibble must match 4-bit addition of the low nibbles.
    check_low_nibble_addition: assert property (
        @(posedge clk) sum[3:0] == (A[3:0] + B[3:0])
    );

    // Adding zero on B must pass A through unchanged.
    check_b_zero_passthrough: assert property (
        @(posedge clk) (B == 8'h00) |-> (sum == A)
    );

    // Adding zero on A must pass B through unchanged.
    check_a_zero_passthrough: assert property (
        @(posedge clk) (A == 8'h00) |-> (sum == B)
    );

    // Zero plus zero must produce zero.
    check_zero_plus_zero: assert property (
        @(posedge clk) ((A == 8'h00) && (B == 8'h00)) |-> (sum == 8'h00)
    );

    // 0xFF plus 0x01 must wrap to 0x00 on the 8-bit output.
    check_ff_plus_one_wraps: assert property (
        @(posedge clk) ((A == 8'hFF) && (B == 8'h01)) |-> (sum == 8'h00)
    );

    // 0xFF plus 0xFF must produce 0xFE on the 8-bit output.
    check_ff_plus_ff: assert property (
        @(posedge clk) ((A == 8'hFF) && (B == 8'hFF)) |-> (sum == 8'hFE)
    );

    // Stable inputs must keep the sampled sum stable.
    check_stable_inputs_stable_sum: assert property (
        @(posedge clk) ($stable(A) && $stable(B)) |-> $stable(sum)
    );

endmodule

