module Contador_Ascendente_Descendente

	# (parameter N = 4) (
		input wire clk,
		input wire reset,
		input wire enUP,
		input wire enDOWN,
		output wire [N-1:0] q
    );

reg [N-1:0] q_act, q_next;


always@(posedge clk,posedge reset)
	if(reset)
		q_act <= 0;
	else
		q_act <= q_next;

always@*

	if(enUP)
		q_next = q_act + 1'b1;

	else if (enDOWN)
		q_next = q_act - 1'b1;

	else
		q_next = q_act;


assign q = q_act;

endmodule

sva:
module Contador_Ascendente_Descendente_sva
#(
    parameter N = 4
) (
    input logic clk,
    input logic reset,
    input logic enUP,
    input logic enDOWN,
    input logic [N-1:0] q
);

    // Reset forces the counter output to zero.
    check_reset_clears_q: assert property (
        @(posedge clk) reset |-> (q == '0)
    );

    // With both enables low, the counter holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset)
        (!enUP && !enDOWN) |=> (q == $past(q))
    );

    // enUP makes the counter increment on the next clock.
    check_increment_on_enUP: assert property (
        @(posedge clk) disable iff (reset)
        enUP |=> (q == ($past(q) + 1'b1))
    );

    // enDOWN alone makes the counter decrement on the next clock.
    check_decrement_on_enDOWN: assert property (
        @(posedge clk) disable iff (reset)
        (!enUP && enDOWN) |=> (q == ($past(q) - 1'b1))
    );

    // If both enables are high, enUP has priority over enDOWN.
    check_enUP_priority: assert property (
        @(posedge clk) disable iff (reset)
        (enUP && enDOWN) |=> (q == ($past(q) + 1'b1))
    );

endmodule

rtl:
module uart_rx #
(
    parameter DATA_WIDTH = 8
)
(
    input  wire                   clk,
    input  wire                   rst,


    output wire [DATA_WIDTH-1:0]  output_axis_tdata,
    output wire                   output_axis_tvalid,
    input  wire                   output_axis_tready,


    input  wire                   rxd,


    output wire                   busy,
    output wire                   overrun_error,
    output wire                   frame_error,


    input  wire [15:0]            prescale

);

reg [DATA_WIDTH-1:0] output_axis_tdata_reg = 0;
reg output_axis_tvalid_reg = 0;

reg rxd_reg = 1;

reg busy_reg = 0;
reg overrun_error_reg = 0;
reg frame_error_reg = 0;

reg [DATA_WIDTH-1:0] data_reg = 0;
reg [18:0] prescale_reg = 0;
reg [3:0] bit_cnt = 0;

assign output_axis_tdata = output_axis_tdata_reg;
assign output_axis_tvalid = output_axis_tvalid_reg;

assign busy = busy_reg;
assign overrun_error = overrun_error_reg;
assign frame_error = frame_error_reg;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        output_axis_tdata_reg <= 0;
        output_axis_tvalid_reg <= 0;
        rxd_reg <= 1;
        prescale_reg <= 0;
        bit_cnt <= 0;
        busy_reg <= 0;
        overrun_error_reg <= 0;
        frame_error_reg <= 0;
    end else begin
        rxd_reg <= rxd;
        overrun_error_reg <= 0;
        frame_error_reg <= 0;

        if (output_axis_tvalid & output_axis_tready) begin
            output_axis_tvalid_reg <= 0;
        end

        if (prescale_reg > 0) begin
            prescale_reg <= prescale_reg - 1;
        end else if (bit_cnt > 0) begin
            if (bit_cnt > DATA_WIDTH+1) begin
                if (~rxd_reg) begin
                    bit_cnt <= bit_cnt - 1;
                    prescale_reg <= (prescale << 3)-1;
                end else begin
                    bit_cnt <= 0;
                    prescale_reg <= 0;
                end
            end else if (bit_cnt > 1) begin
                bit_cnt <= bit_cnt - 1;
                prescale_reg <= (prescale << 3)-1;
                data_reg <= {rxd_reg, data_reg[DATA_WIDTH-1:1]};
            end else if (bit_cnt == 1) begin
                bit_cnt <= bit_cnt - 1;
                if (rxd_reg) begin
                    output_axis_tdata_reg <= data_reg;
                    output_axis_tvalid_reg <= 1;
                    overrun_error_reg <= output_axis_tvalid_reg;
                end else begin
                    frame_error_reg <= 1;
                end
            end
        end else begin
            busy_reg <= 0;
            if (~rxd_reg) begin
                prescale_reg <= (prescale << 2)-2;
                bit_cnt <= DATA_WIDTH+2;
                data_reg <= 0;
                busy_reg <= 1;
            end
        end
    end
end

endmodule

