    // The sampled state remains zero on the first clock after a sampled reset cycle.
    check_sample_after_reset_is_zero: assert property (
        @(posedge clk) disable iff (!rst_n || $initstate)
        !$past(rst_n) |-> (Q == 4'b0000)
