sva:
module sky130_fd_sc_ls__nor4bb_sva (
    input logic clk,
    input logic Y,
    input logic A,
    input logic B,
    input logic C_N,
    input logic D_N
);

    // Y equals the implemented NOR/AND function of the inputs.
    check_y_matches_function: assert property (
        @(posedge clk) Y == ((~A) & (~B) & C_N & D_N)
    );

    // A high forces the NOR term low and keeps Y low.
    check_a_blocks_output: assert property (
        @(posedge clk) A |-> !Y
    );

    // B high forces the NOR term low and keeps Y low.
    check_b_blocks_output: assert property (
        @(posedge clk) B |-> !Y
    );

    // C_N low blocks the final AND and keeps Y low.
    check_c_n_low_blocks_output: assert property (
        @(posedge clk) !C_N |-> !Y
    );

    // D_N low blocks the final AND and keeps Y low.
    check_d_n_low_blocks_output: assert property (
        @(posedge clk) !D_N |-> !Y
    );

    // When all enabling conditions are met, Y is high.
    check_output_high_condition: assert property (
        @(posedge clk) ((~A) & (~B) & C_N & D_N) |-> Y
    );

    // Y high implies the exact enabling input combination.
    check_output_high_implies_inputs: assert property (
        @(posedge clk) Y |-> ((~A) & (~B) & C_N & D_N)
    );

endmodule

rtl:
module xor_lut (
    input a,
    input b,
    output reg out
);
    always @(*)
    begin
        case ({a,b})
            2'b00: out = 1'b0;
            2'b01: out = 1'b1;
            2'b10: out = 1'b1;
            2'b11: out = 1'b0;
        endcase
    end
endmodule
module bitwise_ops (
    input [1:0] in,
    output [1:0] out_and,
    output [1:0] out_or,
    output [1:0] out_xor
);
    assign out_and = in[1:0] & in[1:0];
    assign out_or = in[1:0] | in[1:0];
    assign out_xor = in[1:0] ^ in[1:0];
endmodule
module final_module (
    input out_lut,
    input [1:0] out_and,
    input [1:0] out_or,
    input [1:0] out_xor,
    output final_output
);
    assign final_output = out_lut | out_and[0] | out_and[1] | out_or[0] | out_or[1] | out_xor[0] | out_xor[1];
endmodule
module top_module (
    input a,
    input b,
    input [1:0] in,
    output reg out_lut,
    output [1:0] out_and,
    output [1:0] out_or,
    output [1:0] out_xor,
    output final_output
);
    wire xor_out;
    wire [1:0] bitwise_and_out;
    wire [1:0] bitwise_or_out;
    wire [1:0] bitwise_xor_out;

    xor_lut xor_inst (
        .a(a),
        .b(b),
        .out(xor_out)
    );

    bitwise_ops bitwise_inst (
        .in(in),
        .out_and(bitwise_and_out),
        .out_or(bitwise_or_out),
        .out_xor(bitwise_xor_out)
    );

    final_module final_inst (
        .out_lut(out_lut),
        .out_and(out_and),
        .out_or(out_or),
        .out_xor(out_xor),
        .final_output(final_output)
    );

    always @(*)
    begin
        out_lut = xor_out;
    end

    assign out_and = bitwise_and_out;
    assign out_or = bitwise_or_out;
    assign out_xor = bitwise_xor_out;
endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic a,
    input logic b,
    input logic [1:0] in,
    input logic out_lut,
    input logic [1:0] out_and,
    input logic [1:0] out_or,
    input logic [1:0] out_xor,
    input logic final_output
);

    // External sampling clock; the RTL has no native clock or reset.

    // out_lut implements XOR of a and b.
    check_out_lut_is_xor: assert property (
        @(posedge clk) out_lut == (a ^ b)
    );

    // out_and matches the self-AND of in.
    check_out_and_self_and: assert property (
        @(posedge clk) out_and == (in & in)
    );

    // out_or matches the self-OR of in.
    check_out_or_self_or: assert property (
        @(posedge clk) out_or == (in | in)
    );

    // out_xor matches the self-XOR of in.
    check_out_xor_self_xor: assert property (
        @(posedge clk) out_xor == (in ^ in)
    );

    // final_output is the OR of all final_module inputs.
    check_final_output_or_of_sources: assert property (
        @(posedge clk) final_output == (out_lut | out_and[0] | out_and[1] | out_or[0] | out_or[1] | out_xor[0] | out_xor[1])
    );

    // The composed top-level function reduces to XOR(a,b) or either input bit.
    check_top_level_end_to_end_function: assert property (
        @(posedge clk) final_output == ((a ^ b) | in[0] | in[1])
    );

endmodule

rtl:
module d_flip_flop_chain (
    input clk,
    input [7:0] d,
    output [7:0] q
);

reg [7:0] q_reg;
wire [7:0] d_wire;

assign d_wire = {q_reg[6:0], d};

always @(negedge clk) begin
    q_reg <= d_wire;
end

assign q = q_reg;

endmodule

module top_module (
    input clk,
    input [7:0] d,
    output [7:0] q
);

d_flip_flop_chain flip_flop_chain (
    .clk(clk),
    .d(d),
    .q(q)
);

endmodule

