module top_module_sva (
    input logic clk,
    input logic [7:0] d,
    input logic [7:0] q
);

    property capture_bus;
        logic [7:0] d_sample;
        @(negedge clk) (1'b1, d_sample = d) |=> (q == d_sample);
    endproperty

    // The output bus matches the input bus sampled on the prior falling edge.
    check_capture_bus: assert property (capture_bus);

    property capture_bit0;
        logic d_sample;
        @(negedge clk) (1'b1, d_sample = d[0]) |=> (q[0] == d_sample);
    endproperty

    // Bit 0 matches the prior falling-edge sample of d[0].
    check_capture_bit0: assert property (capture_bit0);

    property capture_bit1;
        logic d_sample;
        @(negedge clk) (1'b1, d_sample = d[1]) |=> (q[1] == d_sample);
    endproperty

    // Bit 1 matches the prior falling-edge sample of d[1].
    check_capture_bit1: assert property (capture_bit1);

    property capture_bit2;
        logic d_sample;
        @(negedge clk) (1'b1, d_sample = d[2]) |=> (q[2] == d_sample);
    endproperty

    // Bit 2 matches the prior falling-edge sample of d[2].
    check_capture_bit2: assert property (capture_bit2);

    property capture_bit3;
        logic d_sample;
        @(negedge clk) (1'b1, d_sample = d[3]) |=> (q[3] == d_sample);
    endproperty

    // Bit 3 matches the prior falling-edge sample of d[3].
    check_capture_bit3: assert property (capture_bit3);

    property capture_bit4;
        logic d_sample;
        @(negedge clk) (1'b1, d_sample = d[4]) |=> (q[4] == d_sample);
    endproperty

    // Bit 4 matches the prior falling-edge sample of d[4].
    check_capture_bit4: assert property (capture_bit4);

    property capture_bit5;
        logic d_sample;
        @(negedge clk) (1'b1, d_sample = d[5]) |=> (q[5] == d_sample);
    endproperty

    // Bit 5 matches the prior falling-edge sample of d[5].
    check_capture_bit5: assert property (capture_bit5);

    property capture_bit6;
        logic d_sample;
        @(negedge clk) (1'b1, d_sample = d[6]) |=> (q[6] == d_sample);
    endproperty

    // Bit 6 matches the prior falling-edge sample of d[6].
    check_capture_bit6: assert property (capture_bit6);

    property capture_bit7;
        logic d_sample;
        @(negedge clk) (1'b1, d_sample = d[7]) |=> (q[7] == d_sample);
    endproperty

    // Bit 7 matches the prior falling-edge sample of d[7].
    check_capture_bit7: assert property (capture_bit7);

endmodule

module mux2to1_sva (
    input logic clk,
    input logic a,
    input logic b,
    input logic sel,
    input logic out
);

    // sel equal to 0 routes a to out.
    check_sel_zero_routes_a: assert property (
        @(posedge clk) (sel === 1'b0) |-> (out === a)
    );

    // Any sel value other than 0 routes b to out.
    check_sel_not_zero_routes_b: assert property (
        @(posedge clk) (sel !== 1'b0) |-> (out === b)
    );

    // Equal data inputs must appear unchanged at out.
    check_equal_inputs_preserved: assert property (
        @(posedge clk) (a === b) |-> (out === a)
    );

    // With different inputs, out matching a means sel is 0.
    check_output_a_requires_sel_zero: assert property (
        @(posedge clk) ((a !== b) && (out === a)) |-> (sel === 1'b0)
    );

    // With different inputs, out matching b means sel is not 0.
    check_output_b_requires_sel_not_zero: assert property (
        @(posedge clk) ((a !== b) && (out === b)) |-> (sel !== 1'b0)
    );

endmodule

rtl:
module binary_counter (
    input clk,
    input rst,
    output reg [3:0] Q
);

always @(posedge clk) begin
    if (rst) begin
        Q <= 4'b0;
    end else begin
        Q <= Q + 1;
    end
end

endmodule

sva:
module binary_counter_sva (
    input logic clk,
    input logic rst,
    input logic [3:0] Q
);

    // Reset drives Q to zero.
    check_reset_clears_q: assert property (
        @(posedge clk) rst |=> (Q == 4'b0000)
    );

    // Q remains zero while reset stays asserted.
    check_q_zero_while_reset_held: assert property (
        @(posedge clk) disable iff ($initstate) (rst && $past(rst)) |-> (Q == 4'b0000)
    );

    // Q increments by one on each active cycle.
    check_q_increments: assert property (
        @(posedge clk) disable iff (rst) 1'b1 |=> (Q == ($past(Q) + 4'd1))
    );

    // Q wraps from 4'hF back to 4'h0.
    check_q_wraps: assert property (
        @(posedge clk) disable iff (rst) (Q == 4'hF) |=> (Q == 4'h0)
    );

    // The first count after reset release is 1.
    check_first_count_after_reset: assert property (
        @(posedge clk) disable iff ($initstate) (!rst && $past(rst)) |=> (Q == 4'h1)
    );

endmodule

rtl:
module top_module (
    input clk,
    input reset,
    input signed [7:0] A,
    input signed [7:0] B,
    input signed [3:0] C,
    input select,
    output signed [3:0] D
);

    wire signed [15:0] prod;
    wire signed [15:0] sum;

    booth_multiplier booth_inst (
        .a(A),
        .b(B),
        .prod(prod)
    );

    adder adder_inst (
        .a(prod),
        .b(C),
        .sum(sum)
    );

    control_logic control_inst (
        .select(select),
        .sum(sum),
        .out(D)
    );

endmodule

module booth_multiplier (
    input signed [7:0] a,
    input signed [7:0] b,
    output signed [15:0] prod
);

    reg signed [7:0] A;
    reg signed [7:0] B;
    reg signed [15:0] P;

    always @(*) begin
        A = a;
        B = b;
        P = A * B;
    end

    assign prod = P;

endmodule

module adder (
    input signed [15:0] a,
    input signed [3:0] b,
    output signed [15:0] sum
);

    reg signed [15:0] A;
    reg signed [3:0] B;
    reg signed [15:0] S;

    always @(*) begin
        A = a;
        B = b;
        S = A + B;
    end

    assign sum = S;

endmodule

module control_logic (
    input select,
    input signed [15:0] sum,
    output reg signed [3:0] out
);

    always @(*) begin
        if (select == 0) begin
            out = sum[3:0];
        end else begin
            out = sum[7:4];
        end
    end

endmodule

sva:
module top_module_assertions (
    input logic clk,
    input logic reset,
    input logic signed [7:0] A,
    input logic signed [7:0] B,
    input logic signed [3:0] C,
    input logic select,
    input logic signed [3:0] D
);

    // select=0 chooses the low nibble of the sum.
    check_select_low_uses_sum_low_nibble: assert property (
        @(posedge clk) disable iff (reset)
        (select == 1'b0) |-> (D == (((A * B) + C)[3:0]))
    );

    // select=1 chooses the upper nibble of the sum.
    check_select_high_uses_sum_high_nibble: assert property (
        @(posedge clk) disable iff (reset)
        (select == 1'b1) |-> (D == (((A * B) + C)[7:4]))
    );

    // With C=0, select=0 returns the low nibble of the product.
    check_zero_c_low_nibble_is_product: assert property (
        @(posedge clk) disable iff (reset)
        ((C == 4'sd0) && (select == 1'b0)) |-> (D == ((A * B)[3:0]))
    );

    // With C=0, select=1 returns the upper nibble of the product.
    check_zero_c_high_nibble_is_product: assert property (
        @(posedge clk) disable iff (reset)
        ((C == 4'sd0) && (select == 1'b1)) |-> (D == ((A * B)[7:4]))
    );

    // If either multiplier input is zero, select=0 returns C directly.
    check_zero_product_low_nibble_matches_c: assert property (
        @(posedge clk) disable iff (reset)
        (((A == 8'sd0) || (B == 8'sd0)) && (select == 1'b0)) |-> (D == C)
    );

    // If either multiplier input is zero, select=1 returns C sign extension.
    check_zero_product_high_nibble_is_c_sign_extension: assert property (
        @(posedge clk) disable iff (reset)
        (((A == 8'sd0) || (B == 8'sd0)) && (select == 1'b1)) |-> (D == {4{C[3]}})
    );

endmodule

module synchronous_counter_sva (
    input logic clk,
    input logic rst,
    input logic [3:0] count
);

    // Reset clears the counter to zero on the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |=> (count == 4'd0)
    );

    // A count of nine rolls over to zero on the next clock.
    check_wrap_from_nine: assert property (
        @(posedge clk) (count == 4'd9) |=> (count == 4'd0)
    );

    // Any non-reset state other than nine increments by one.
    check_increment_otherwise: assert property (
        @(posedge clk) disable iff (rst)
        (count != 4'd9) |=> (count == ($past(count) + 4'd1))
    );

    // When not in reset, the counter value changes every clock.
    check_count_changes_without_reset: assert property (
        @(posedge clk) disable iff (rst)
        1'b1 |=> (count != $past(count))
    );

endmodule

rtl:
module counter (
  input clk,
  input reset,
  input enable,
  input [31:0] max_count,
  output reg [31:0] count
);

  always @(posedge clk or posedge reset)
    if (reset)
      count <= 0;
    else if (enable && count == max_count)
      count <= 0;
    else if (enable)
      count <= count + 1;

endmodule

sva:
module counter_sva (
    input logic        clk,
    input logic        reset,
    input logic        enable,
    input logic [31:0] max_count,
    input logic [31:0] count
);

    // A reset cycle leaves count at zero on the following cycle.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 32'd0)
    );

    // Count holds when enable is low.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset)
        !enable |=> (count == $past(count))
    );

    // Count wraps to zero when enabled at max_count.
    check_wrap_when_at_max: assert property (
        @(posedge clk) disable iff (reset)
        enable && (count == max_count) |=> (count == 32'd0)
    );

    // Count increments by one when enabled away from max_count.
    check_increment_when_enabled: assert property (
        @(posedge clk) disable iff (reset)
        enable && (count != max_count) |=> (count == ($past(count) + 32'd1))
    );

endmodule

module clock_gate_sva (
    input logic CLK,
    input logic EN,
    input logic TE,
    input logic ENCLK
);

    // ENCLK reflects the prior cycle's EN && !TE value.
    check_enclk_matches_registered_gate: assert property (
        @(posedge CLK) 1'b1 |=> (ENCLK == ($past(EN) && !$past(TE)))
    );

    // EN high with TE low makes ENCLK high on the next clock.
    check_enable_sets_enclk: assert property (
        @(posedge CLK) (EN && !TE) |=> ENCLK
    );

    // EN low or TE high makes ENCLK low on the next clock.
    check_disable_clears_enclk: assert property (
        @(posedge CLK) (!EN || TE) |=> !ENCLK
    );

endmodule

module parity_check_sva (
    input logic clk,
    input logic reset,
    input logic [7:0] data_in,
    input logic parity_out
);

    // After reset deasserts, parity_out is still cleared on that clock edge.
    check_reset_release_clears_output: assert property (
        @(posedge clk) disable iff (reset)
        $fell(reset) |-> (parity_out == 1'b0)
    );

    // Even input parity drives parity_out high on the next clock.
    check_even_parity_sets_output: assert property (
        @(posedge clk) disable iff (reset)
        (~^data_in) |=> (parity_out == 1'b1)
    );

    // Odd input parity drives parity_out low on the next clock.
    check_odd_parity_clears_output: assert property (
        @(posedge clk) disable iff (reset)
        (^data_in) |=> (parity_out == 1'b0)
    );

endmodule

rtl:
module max_selector (
  input clk,
  input [4:0] a,
  input [4:0] b,
  input [4:0] c,
  output reg [1:0] out
);

always @(posedge clk) begin
  if (a >= b && a >= c)
    out <= 2'b00;
  else if (b >= a && b >= c)
    out <= 2'b01;
  else if (c >= a && c >= b)
    out <= 2'b10;
  else
    out <= 2'b11;
end

endmodule

sva:
module max_selector_assertions (
    input logic clk,
    input logic [4:0] a,
    input logic [4:0] b,
    input logic [4:0] c,
    input logic [1:0] out
);

    // A is selected when it was at least as large as B and C.
    check_a_selected_when_a_is_max: assert property (
        @(posedge clk) disable iff ($initstate)
        (($past(a) >= $past(b)) && ($past(a) >= $past(c))) |-> (out == 2'b00)
    );

    // B is selected when it beat A and was at least as large as C.
    check_b_selected_when_b_is_priority_max: assert property (
        @(posedge clk) disable iff ($initstate)
        (($past(b) > $past(a)) && ($past(b) >= $past(c))) |-> (out == 2'b01)
    );

    // C is selected when it was strictly larger than A and B.
    check_c_selected_when_c_is_strict_max: assert property (
        @(posedge clk) disable iff ($initstate)
        (($past(c) > $past(a)) && ($past(c) > $past(b))) |-> (out == 2'b10)
    );

    // Output code 00 means A was the selected maximum.
    check_out_00_implies_a_was_max: assert property (
        @(posedge clk) disable iff ($initstate)
        (out == 2'b00) |-> (($past(a) >= $past(b)) && ($past(a) >= $past(c)))
    );

    // Output code 01 means B beat A and was at least C.
    check_out_01_implies_b_was_priority_max: assert property (
        @(posedge clk) disable iff ($initstate)
        (out == 2'b01) |-> (($past(b) > $past(a)) && ($past(b) >= $past(c)))
    );

    // Output code 10 means C was the strict maximum.
    check_out_10_implies_c_was_strict_max: assert property (
        @(posedge clk) disable iff ($initstate)
        (out == 2'b10) |-> (($past(c) > $past(a)) && ($past(c) > $past(b)))
    );

    // The RTL never assigns the unreachable 2'b11 code.
    check_out_never_11: assert property (
        @(posedge clk) disable iff ($initstate)
        (out != 2'b11)
    );

endmodule

module LCB_sva #(
    parameter integer pwm_width = 8,
    parameter integer pwm_frequency = 100
) (
    input logic clk,
    input logic [1:0] analog_signal,
    input logic enable,
    input logic reset,
    input logic pwm_out,
    input logic [pwm_width-1:0] pwm_counter,
    input logic [pwm_width-1:0] pwm_threshold
);

    localparam logic [pwm_width-1:0] PWM_ZERO  = {pwm_width{1'b0}};
    localparam logic [pwm_width-1:0] PWM_ONE   = {{(pwm_width-1){1'b0}}, 1'b1};
    localparam logic [pwm_width-1:0] PWM_MAX   = {pwm_width{1'b1}};
    localparam logic [pwm_width-1:0] THRESH_00 = pwm_width / 8;
    localparam logic [pwm_width-1:0] THRESH_01 = pwm_width / 4;
    localparam logic [pwm_width-1:0] THRESH_10 = pwm_width / 2;
    localparam logic [pwm_width-1:0] THRESH_11 = pwm_width - 1;

    // Reset drives the counter to zero.
    check_reset_clears_counter: assert property (
        @(posedge clk) reset |-> (pwm_counter == PWM_ZERO)
    );

    // Reset drives the threshold to zero.
    check_reset_clears_threshold: assert property (
        @(posedge clk) reset |-> (pwm_threshold == PWM_ZERO)
    );

    // Reset drives the PWM output low.
    check_reset_clears_pwm_out: assert property (
        @(posedge clk) reset |-> (pwm_out == 1'b0)
    );

    // The counter holds when enable is low.
    check_counter_holds_when_disabled: assert property (
        @(posedge clk) disable iff (reset)
        !enable |=> (pwm_counter == $past(pwm_counter))
    );

    // The counter increments by one when enabled below max.
    check_counter_increments_when_enabled: assert property (
        @(posedge clk) disable iff (reset)
        enable && (pwm_counter != PWM_MAX) |=> (pwm_counter == ($past(pwm_counter) + PWM_ONE))
    );

    // The counter wraps to zero when enabled at max.
    check_counter_wraps_at_max: assert property (
        @(posedge clk) disable iff (reset)
        enable && (pwm_counter == PWM_MAX) |=> (pwm_counter == PWM_ZERO)
    );

    // analog_signal 00 selects pwm_width/8 as the threshold.
    check_threshold_for_analog_00: assert property (
        @(posedge clk) disable iff (reset)
        (analog_signal == 2'b00) |=> (pwm_threshold == THRESH_00)
    );

    // analog_signal 01 selects pwm_width/4 as the threshold.
    check_threshold_for_analog_01: assert property (
        @(posedge clk) disable iff (reset)
        (analog_signal == 2'b01) |=> (pwm_threshold == THRESH_01)
    );

    // analog_signal 10 selects pwm_width/2 as the threshold.
    check_threshold_for_analog_10: assert property (
        @(posedge clk) disable iff (reset)
        (analog_signal == 2'b10) |=> (pwm_threshold == THRESH_10)
    );

    // analog_signal 11 selects pwm_width-1 as the threshold.
    check_threshold_for_analog_11: assert property (
        @(posedge clk) disable iff (reset)
        (analog_signal == 2'b11) |=> (pwm_threshold == THRESH_11)
    );

    // The PWM output holds when enable is low.
    check_pwm_out_holds_when_disabled: assert property (
        @(posedge clk) disable iff (reset)
        !enable |=> (pwm_out == $past(pwm_out))
    );

    // The PWM output goes high when enabled and counter meets the threshold.
    check_pwm_out_high_when_counter_ge_threshold: assert property (
        @(posedge clk) disable iff (reset)
        enable && (pwm_counter >= pwm_threshold) |=> (pwm_out == 1'b1)
    );

    // The PWM output goes low when enabled and counter is below the threshold.
    check_pwm_out_low_when_counter_lt_threshold: assert property (
        @(posedge clk) disable iff (reset)
        enable && (pwm_counter < pwm_threshold) |=> (pwm_out == 1'b0)
    );

endmodule

rtl:
module my_module (
    HI,
    LO,
    VPWR,
    VGND,
    VPB,
    VNB
);

    output HI;
    output LO;
    input VPWR;
    input VGND;
    input VPB;
    input VNB;

    wire HI_temp;
    wire LO_temp;

    assign HI = HI_temp;
    assign LO = LO_temp;

    assign HI_temp = (VPWR && !VPB) ? 1'b1 : 1'b0;
    assign LO_temp = (!VPWR && !VNB) ? 1'b1 : 1'b0;

endmodule

sva:
module my_module_sva (
    input logic HI,
    input logic LO,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB
);

    // No RTL clock or reset; sample combinational behavior on the formal global clock.

    // HI must match the implemented VPWR/VPB decode.
    check_hi_function: assert property (
        @($global_clock) HI === ((VPWR && !VPB) ? 1'b1 : 1'b0)
    );

    // LO must match the implemented VPWR/VNB decode.
    check_lo_function: assert property (
        @($global_clock) LO === ((!VPWR && !VNB) ? 1'b1 : 1'b0)
    );

    // VPWR high with VPB low must drive HI high.
    check_hi_assert_condition: assert property (
        @($global_clock) (VPWR && !VPB) |-> (HI === 1'b1)
    );

    // VPWR low with VNB low must drive LO high.
    check_lo_assert_condition: assert property (
        @($global_clock) (!VPWR && !VNB) |-> (LO === 1'b1)
    );

    // VPB high must block HI.
    check_vpb_blocks_hi: assert property (
        @($global_clock) VPB |-> (HI === 1'b0)
    );

    // VPWR high must block LO.
    check_vpwr_blocks_lo: assert property (
        @($global_clock) VPWR |-> (LO === 1'b0)
    );

    // HI and LO cannot be high at the same time.
    check_hi_lo_mutex: assert property (
        @($global_clock) !((HI === 1'b1) && (LO === 1'b1))
    );

endmodule

rtl:
module up_down_counter (
    input clk,
    input rst,
    input up_down,
    output reg [2:0] count
);

    always @(posedge clk) begin
        if (rst) begin
            count <= 3'b000;
        end else if (up_down) begin
            count <= count + 1;
        end else begin
            count <= count - 1;
        end
    end

endmodule

sva:
module up_down_counter_sva (
    input logic       clk,
    input logic       rst,
    input logic       up_down,
    input logic [2:0] count
);

    // A high reset clears the counter on the next clock.
    reset_clears_count: assert property (
        @(posedge clk) disable iff ($initstate)
        rst |=> (count == 3'b000)
    );

    // When up_down is high, the counter increments by one.
    check_count_increments: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        up_down |=> (count == ($past(count) + 3'b001))
    );

    // When up_down is low, the counter decrements by one.
    check_count_decrements: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        !up_down |=> (count == ($past(count) - 3'b001))
    );

    // Counting up wraps from 7 back to 0.
    check_wrap_up: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        (up_down && (count == 3'b111)) |=> (count == 3'b000)
    );

    // Counting down wraps from 0 back to 7.
    check_wrap_down: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        (!up_down && (count == 3'b000)) |=> (count == 3'b111)
    );

    // Outside reset, the counter value changes on every clock.
    check_count_changes_each_cycle: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        1'b1 |=> (count != $past(count))
    );

endmodule

rtl:
module triangular_wave(clk, out);

  // declare inputs and outputs
  input clk;
  output reg [7:0] out;

  // declare internal variables
  reg [7:0] count = 0;
  reg [7:0] slope = 1;
  reg [7:0] peak = 255;

  // generate triangular wave
  always @(posedge clk) begin
    if (count == 0) begin
      out <= 0;
    end else if (count == peak) begin
      out <= 2*peak;
    end else if (count == 2*peak) begin
      out <= 0;
      count <= 0;
    end else begin
      out <= out + slope;
    end
    count <= count + 1;
  end

endmodule

sva:
module triangular_wave_sva (
    input logic       clk,
    input logic [7:0] out,
    input logic [7:0] count,
    input logic [7:0] slope,
    input logic [7:0] peak
);

    // Slope is initialized to 1 and never changes.
    check_slope_is_one: assert property (
        @(posedge clk) slope == 8'd1
    );

    // Peak is initialized to 255 and never changes.
    check_peak_is_ff: assert property (
        @(posedge clk) peak == 8'hFF
    );

    // Count increments by one on every clock, wrapping modulo 256.
    check_count_advances: assert property (
        @(posedge clk) 1'b1 |=> count == ($past(count) + 8'd1)
    );

    // When count is zero, the next cycle drives out to zero and count to one.
    check_zero_branch: assert property (
        @(posedge clk) (count == 8'd0) |=> (out == 8'd0) && (count == 8'd1)
    );

    // When count reaches peak, the next cycle drives truncated 2*peak and wraps count.
    check_peak_branch: assert property (
        @(posedge clk) (count == peak) |=> (out == (peak + peak)) && (count == 8'd0)
    );

    // Outside the special count values, out increments by slope.
    check_increment_branch: assert property (
        @(posedge clk) (count != 8'd0 && count != peak) |=> (out == ($past(out) + $past(slope)))
    );

    // For nonzero count values, out matches count minus one.
    check_nonzero_count_matches_out: assert property (
        @(posedge clk) (count != 8'd0) |-> (out == (count - 8'd1))
    );

endmodule

rtl:
module simple_multiplier (
    input  wire        clk,
    input  wire [ 7:0] A,
    input  wire [ 7:0] B,
    output wire [15:0] Z
);

    reg [15:0] Z_sync;

    always @(posedge clk)
        Z_sync <= A * B;

    assign Z = Z_sync;

endmodule

sva:
module simple_multiplier_sva (
    input logic        clk,
    input logic [7:0]  A,
    input logic [7:0]  B,
    input logic [15:0] Z
);

    // Z is the registered product of A and B from the previous clock.
    check_registered_product: assert property (
        @(posedge clk) 1'b1 |=> (Z == $past(A * B))
    );

    // A zero operand produces a zero product on the next clock.
    check_zero_operand: assert property (
        @(posedge clk) ((A == 8'h00) || (B == 8'h00)) |=> (Z == 16'h0000)
    );

    // A value of one on A passes B through on the next clock.
    check_a_is_one: assert property (
        @(posedge clk) (A == 8'h01) |=> (Z == {8'h00, $past(B)})
    );

    // A value of one on B passes A through on the next clock.
    check_b_is_one: assert property (
        @(posedge clk) (B == 8'h01) |=> (Z == {8'h00, $past(A)})
    );

    // Maximum 8-bit operands produce the expected 16-bit product.
    check_max_operands: assert property (
        @(posedge clk) ((A == 8'hFF) && (B == 8'hFF)) |=> (Z == 16'hFE01)
    );

endmodule

