module full_adder (
    input  a,
    input  b,
    input  cin,
    output cout,
    output sum
);

    wire ps, pc; // pc2 is not used

    half_adder ha1 (
        .A(a),
        .B(b),
        .SUM(ps),
        .COUT(pc)
    );

    half_adder ha2 (
        .A(ps),
        .B(cin),
        .SUM(sum),
        .COUT(cout)
    );

endmodule

module half_adder(
    input A,
    input B,
    output SUM,
    output COUT
    );

    assign SUM = A ^ B;
    assign COUT = A & B;

endmodule

sva:
module full_adder_assertions (
    input logic clk,
    input logic a,
    input logic b,
    input logic cin,
    input logic cout,
    input logic sum
);

    // sum matches the chained XOR implementation.
    check_sum_xor_chain: assert property (
        @(posedge clk) (sum === (a ^ b ^ cin))
    );

    // cout is high only when cin is high and a/b differ.
    check_cout_xor_and_cin: assert property (
        @(posedge clk) (cout === ((a ^ b) & cin))
    );

    // With cin low, sum is a^b and cout stays low.
    check_cin_low_behavior: assert property (
        @(posedge clk) (!cin) |-> ((sum === (a ^ b)) && (cout === 1'b0))
    );

    // With cin high, sum inverts a^b and cout mirrors a^b.
    check_cin_high_behavior: assert property (
        @(posedge clk) (cin) |-> ((sum === ~(a ^ b)) && (cout === (a ^ b)))
    );

    // Equal a/b inputs make sum follow cin and force cout low.
    check_equal_ab_behavior: assert property (
        @(posedge clk) (!(a ^ b)) |-> ((sum === cin) && (cout === 1'b0))
    );

    // Different a/b inputs make sum invert cin and cout follow cin.
    check_unequal_ab_behavior: assert property (
        @(posedge clk) (a ^ b) |-> ((sum === ~cin) && (cout === cin))
    );

endmodule

rtl:
module shift_register_counter (
    input clk,
    input rst,
    input en,
    input load,
    input [3:0] data_in,
    input sel,
    output [3:0] out
);

reg [3:0] shift_reg;
reg [3:0] counter;

always @(posedge clk) begin
    if (rst) begin
        shift_reg <= 4'b0000;
        counter <= 4'b0000;
    end else if (en) begin
        if (load) begin
            shift_reg <= data_in;
        end else begin
            counter <= counter + 1;
        end
    end
end

assign out = sel ? counter : shift_reg;

endmodule

module adder (
    input [3:0] in1,
    input [3:0] in2,
    output [3:0] sum
);

assign sum = in1 + in2;

endmodule

module top_module (
    input clk,
    input rst,
    input en,
    input load,
    input [3:0] data_in,
    input sel,
    output [3:0] out
);

wire [3:0] shift_reg_out;
wire [3:0] counter_out;
wire [3:0] sum_out;

shift_register_counter shift_counter (
    .clk(clk),
    .rst(rst),
    .en(en),
    .load(load),
    .data_in(data_in),
    .sel(sel),
    .out(shift_reg_out)
);

shift_register_counter counter (
    .clk(clk),
    .rst(rst),
    .en(en),
    .load(1'b0),
    .data_in(4'b0000),
    .sel(sel),
    .out(counter_out)
);

adder sum (
    .in1(shift_reg_out),
    .in2(counter_out),
    .sum(sum_out)
);

assign out = sum_out;

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic rst,
    input logic en,
    input logic load,
    input logic [3:0] data_in,
    input logic sel,
    input logic [3:0] out,
    input logic [3:0] shift_reg_out,
    input logic [3:0] counter_out,
    input logic [3:0] sum_out
);

    // Clock: clk
    // Reset: rst, active-high synchronous
    // Mixed sequential and combinational checks

    // Top output must match the adder output.
    check_top_out_follows_sum_out: assert property (
        @(posedge clk) disable iff (rst)
        out == sum_out
    );

    // The adder output must equal the sum of the two instance outputs.
    check_sum_out_matches_inputs: assert property (
        @(posedge clk) disable iff (rst)
        sum_out == (shift_reg_out + counter_out)
    );

    // One cycle after reset, all visible data outputs are cleared.
    check_reset_clears_visible_outputs: assert property (
        @(posedge clk) disable iff (rst)
        $past(rst) |-> (shift_reg_out == 4'b0000) &&
                       (counter_out   == 4'b0000) &&
                       (sum_out       == 4'b0000) &&
                       (out           == 4'b0000)
    );

    // A load updates the first instance shift-register path with data_in.
    check_shift_output_loads_data: assert property (
        @(posedge clk) disable iff (rst)
        !$past(rst) && $past(en && load) && !sel |-> (shift_reg_out == $past(data_in))
    );

    // Without a load, the first instance shift-register path holds when sel stays low.
    check_shift_output_holds_when_sel_low: assert property (
        @(posedge clk) disable iff (rst)
        !$past(rst) && $past(!sel) && !sel && !$past(en && load) |-> (shift_reg_out == $past(shift_reg_out))
    );

    // The second instance low-selected path holds its previous value.
    check_counter_low_path_holds: assert property (
        @(posedge clk) disable iff (rst)
        !$past(rst) && $past(!sel) && !sel |-> (counter_out == $past(counter_out))
    );

    // The second instance counter increments by one iff en was high when sel stays high.
    check_counter_high_path_behavior: assert property (
        @(posedge clk) disable iff (rst)
        !$past(rst) && $past(sel) && sel |-> (counter_out == ($past(counter_out) + ($past(en) ? 4'b0001 : 4'b0000)))
    );

    // The first instance counter increments by one only when en was high and load was low.
    check_shift_counter_high_path_behavior: assert property (
        @(posedge clk) disable iff (rst)
        !$past(rst) && $past(sel) && sel |-> (shift_reg_out == ($past(shift_reg_out) + ($past(en && !load) ? 4'b0001 : 4'b0000)))
    );

    // The top output holds when sel stays low and there was no prior load.
    check_top_output_holds_when_sel_low: assert property (
        @(posedge clk) disable iff (rst)
        !$past(rst) && $past(!sel) && !sel && !$past(en && load) |-> (out == $past(out))
    );

    // With sel high, the top output changes by 0, 1, or 2 based on en and load.
    check_top_output_high_path_behavior: assert property (
        @(posedge clk) disable iff (rst)
        !$past(rst) && $past(sel) && sel |-> (out == ($past(out) + ($past(en) ? ($past(load) ? 4'b0001 : 4'b0010) : 4'b0000)))
    );

endmodule

module d_ff_assertions (
    input logic Q,
    input logic Q_N,
    input logic CLK,
    input logic D,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB
);

    // Q_N remains the complement of Q outside reset.
    check_qn_complement: assert property (
        @(posedge CLK) disable iff (VPB == 1'b0) Q_N == ~Q
    );

    // A low VPB on a clock edge clears Q by the next sampled cycle.
    check_reset_clears_q: assert property (
        @(posedge CLK) (VPB == 1'b0) |=> Q == 1'b0
    );

    // Outside reset, Q captures D on the following sampled cycle.
    check_q_captures_d: assert property (
        @(posedge CLK) disable iff (VPB == 1'b0) 1'b1 |=> Q == $past(D)
    );

    // A low VPB on a clock edge drives Q_N high by the next sampled cycle.
    check_reset_sets_qn_high: assert property (
        @(posedge CLK) (VPB == 1'b0) |=> Q_N == 1'b1
    );

endmodule

rtl:
module bitwise_or_and_adder(
    input  [15:0] in1,
    input  [15:0] in2,
    output [16:0] res
);

// Bitwise OR operation
assign res[0] = in1[0] | in2[0];
assign res[1] = in1[1] | in2[1];
assign res[2] = in1[2] | in2[2];
assign res[3] = in1[3] | in2[3];
assign res[4] = in1[4] | in2[4];
assign res[5] = in1[5] | in2[5];
assign res[6] = in1[6] | in2[6];
assign res[7] = in1[7] | in2[7];
assign res[8] = in1[8] | in2[8];
assign res[9] = in1[9] | in2[9];
assign res[10] = in1[10] | in2[10];
assign res[11] = in1[11] | in2[11];
assign res[12] = in1[12] | in2[12];
assign res[13] = in1[13] | in2[13];
assign res[14] = in1[14] | in2[14];
assign res[15] = in1[15] | in2[15];
assign res[16] = 0;

endmodule

sva:
module bitwise_or_and_adder_assertions (
    input logic [15:0] in1,
    input logic [15:0] in2,
    input logic [16:0] res
);

    // No RTL clock or reset; this DUT is purely combinational and sampled on the global clock.

    // Full result must be the zero-extended bitwise OR of the inputs.
    check_full_result_matches_or: assert property (
        @($global_clock) res == {1'b0, (in1 | in2)}
    );

    // Lower 16 result bits must match the bitwise OR of the inputs.
    check_lower_bits_match_or: assert property (
        @($global_clock) res[15:0] == (in1 | in2)
    );

    // The top result bit is tied low.
    check_msb_tied_low: assert property (
        @($global_clock) res[16] == 1'b0
    );

    // When in2 is zero, the result must pass through in1 with a zero MSB.
    check_in1_passthrough_when_in2_zero: assert property (
        @($global_clock) (in2 == 16'h0000) |-> (res == {1'b0, in1})
    );

    // When in1 is zero, the result must pass through in2 with a zero MSB.
    check_in2_passthrough_when_in1_zero: assert property (
        @($global_clock) (in1 == 16'h0000) |-> (res == {1'b0, in2})
    );

endmodule

rtl:
module calculator(
    input [7:0] num1,
    input [7:0] num2,
    input [1:0] op_sel,
    output reg [15:0] result
);

always @* begin
    case(op_sel)
        2'b00: result = num1 + num2;
        2'b01: result = num1 - num2;
        2'b10: result = num1 * num2;
        2'b11: result = num1 / num2;
    endcase
end

endmodule

sva:
module calculator_sva (
    input logic [7:0] num1,
    input logic [7:0] num2,
    input logic [1:0] op_sel,
    input logic [15:0] result,
    input logic clk
);

    // op_sel 00 selects zero-extended 8-bit addition.
    check_addition_result: assert property (
        @(posedge clk)
        (op_sel == 2'b00) |-> ((result[7:0] == (num1 + num2)) && (result[15:8] == 8'h00))
    );

    // op_sel 01 selects zero-extended 8-bit subtraction.
    check_subtraction_result: assert property (
        @(posedge clk)
        (op_sel == 2'b01) |-> ((result[7:0] == (num1 - num2)) && (result[15:8] == 8'h00))
    );

    // op_sel 10 selects the full 16-bit product.
    check_multiplication_result: assert property (
        @(posedge clk)
        (op_sel == 2'b10) |-> (result == ({8'h00, num1} * {8'h00, num2}))
    );

    // op_sel 11 with a nonzero divisor selects zero-extended division.
    check_division_result: assert property (
        @(posedge clk)
        ((op_sel == 2'b11) && (num2 != 8'h00)) |-> ((result[7:0] == (num1 / num2)) && (result[15:8] == 8'h00))
    );

    // Stable sampled inputs keep the sampled result stable.
    check_stable_inputs_hold_result: assert property (
        @(posedge clk)
        ($stable({num1, num2, op_sel}) && !((op_sel == 2'b11) && (num2 == 8'h00))) |-> $stable(result)
    );

endmodule

module toggle_output_sva (
    input logic        clk,
    input logic        out,
    input logic [31:0] count,
    input logic        clk_divider
);

    // The divider flips on every rising edge of clk.
    check_clk_divider_toggles: assert property (
        @(posedge clk) 1'b1 |=> (clk_divider == ~$past(clk_divider))
    );

    // The counter stays within its programmed terminal range.
    check_count_range: assert property (
        @(posedge clk) (count <= 32'd50000000)
    );

    // When the divider is high, the next clk edge must not update the counter.
    check_count_stable_on_divider_fall: assert property (
        @(posedge clk) (clk_divider == 1'b1) |=> (count == $past(count))
    );

    // When the divider is high, the next clk edge must not update the output.
    check_out_stable_on_divider_fall: assert property (
        @(posedge clk) (clk_divider == 1'b1) |=> (out === $past(out))
    );

    // On an active divider edge below terminal count, the counter increments.
    check_count_increments_on_divider_rise: assert property (
        @(posedge clk) ((clk_divider == 1'b0) && (count != 32'd50000000)) |=> (count == ($past(count) + 32'd1))
    );

    // On an active divider edge at terminal count, the counter wraps to zero.
    check_count_wraps_on_terminal: assert property (
        @(posedge clk) ((clk_divider == 1'b0) && (count == 32'd50000000)) |=> (count == 32'd0)
    );

    // Below terminal count, the output holds through an active divider edge.
    check_out_holds_below_terminal: assert property (
        @(posedge clk) ((clk_divider == 1'b0) && (count != 32'd50000000)) |=> (out === $past(out))
    );

    // At terminal count, the output inverts through an active divider edge.
    check_out_toggles_on_terminal: assert property (
        @(posedge clk) ((clk_divider == 1'b0) && (count == 32'd50000000)) |=> (out === ~$past(out))
    );

    // Any counter change must come from a divider rise on the prior clk.
    check_count_changes_only_on_divider_rise: assert property (
        @(posedge clk) 1'b1 |=> ((count != $past(count)) |-> ($past(clk_divider) == 1'b0))
    );

    // Any output change must come from terminal count on a divider rise.
    check_out_changes_only_on_terminal: assert property (
        @(posedge clk) 1'b1 |=> ((out !== $past(out)) |-> (($past(clk_divider) == 1'b0) && ($past(count) == 32'd50000000)))
    );

endmodule

bind toggle_output toggle_output_sva toggle_output_sva_inst (
    .clk(clk),
    .out(out),
    .count(count),
    .clk_divider(clk_divider)
);

