module sky130_fd_sc_hvl__inv (
    Y,
    A
);

    output Y;
    input  A;

    wire not0_out_Y;

    not not0 (not0_out_Y, A              );
    buf buf0 (Y         , not0_out_Y     );

endmodule

sva:
module sky130_fd_sc_hvl__inv_sva (
    input logic A,
    input logic Y
);

    // Y always reflects the inversion of A.
    check_inverter_function: assert property (
        @($global_clock) Y === (~A)
    );

    // A low input produces a high output.
    check_low_input_high_output: assert property (
        @($global_clock) (A == 1'b0) |-> (Y == 1'b1)
    );

    // A high input produces a low output.
    check_high_input_low_output: assert property (
        @($global_clock) (A == 1'b1) |-> (Y == 1'b0)
    );

endmodule

module mux_2to1_enable_sva (
    input logic clk,
    input logic a,
    input logic b,
    input logic enable,
    input logic mux_out
);

    // When enable is high, the output follows input a.
    check_select_a: assert property (
        @(posedge clk) (enable === 1'b1) |-> (mux_out === a)
    );

    // When enable is not high, the output follows input b.
    check_select_b: assert property (
        @(posedge clk) (enable !== 1'b1) |-> (mux_out === b)
    );

    // When both inputs match, the output matches that common value.
    check_equal_inputs_common_value: assert property (
        @(posedge clk) (a === b) |-> (mux_out === a)
    );

endmodule

rtl:
module mux_2to1 (
    input [1:0] data_in,
    input sel,
    output data_out
);

    assign data_out = (sel == 1'b0) ? data_in[0] : data_in[1];

endmodule

sva:
module mux_2to1_sva (
    input logic clk,
    input logic [1:0] data_in,
    input logic sel,
    input logic data_out
);

    // When sel is 0, the output matches data_in[0].
    check_select_low: assert property (
        @(posedge clk) (sel === 1'b0) |-> (data_out === data_in[0])
    );

    // When sel is 1, the output matches data_in[1].
    check_select_high: assert property (
        @(posedge clk) (sel === 1'b1) |-> (data_out === data_in[1])
    );

    // The output always matches the RTL mux equation.
    check_mux_equation: assert property (
        @(posedge clk) data_out === ((sel == 1'b0) ? data_in[0] : data_in[1])
    );

endmodule

rtl:
module split_16bit_input(
    input wire [15:0] in,
    output wire [7:0] out_hi,
    output wire [7:0] out_lo
);

wire [1:0] sel;
assign sel = in[8];

// Decoder
wire [3:0] dec_out;
assign dec_out = (sel == 2'b00) ? 4'b0001 :
                 (sel == 2'b01) ? 4'b0010 :
                 (sel == 2'b10) ? 4'b0100 :
                                  4'b1000 ;

// Multiplexer
wire [7:0] mux_out_lo;
wire [7:0] mux_out_hi;

assign mux_out_lo = (dec_out[0]) ? in[7:0] : in[15:8];
assign mux_out_hi = (dec_out[1]) ? in[7:0] : in[15:8];

assign out_lo = mux_out_lo;
assign out_hi = mux_out_hi;

endmodule

sva:
module split_16bit_input_sva (
    input logic        clk,
    input logic [15:0] in,
    input logic [7:0]  out_hi,
    input logic [7:0]  out_lo
);

    // out_lo selects the low or high input byte based on in[8].
    check_out_lo_selected_byte: assert property (
        @(posedge clk) out_lo == (in[8] ? in[15:8] : in[7:0])
    );

    // out_hi selects the complementary input byte based on in[8].
    check_out_hi_selected_byte: assert property (
        @(posedge clk) out_hi == (in[8] ? in[7:0] : in[15:8])
    );

    // When in[8] is low, the outputs preserve the original byte order.
    check_original_order_when_sel_low: assert property (
        @(posedge clk) !in[8] |-> ({out_hi, out_lo} == {in[15:8], in[7:0]})
    );

    // When in[8] is high, the outputs swap the input byte order.
    check_swapped_order_when_sel_high: assert property (
        @(posedge clk) in[8] |-> ({out_hi, out_lo} == {in[7:0], in[15:8]})
    );

    // The outputs are always the two input bytes in one of the two possible orders.
    check_outputs_form_input_byte_permutation: assert property (
        @(posedge clk) (({out_hi, out_lo} == {in[15:8], in[7:0]}) ||
                        ({out_hi, out_lo} == {in[7:0], in[15:8]}))
    );

    // The two outputs are equal exactly when the two input bytes are equal.
    check_output_equality_matches_input_equality: assert property (
        @(posedge clk) ((out_hi == out_lo) == (in[15:8] == in[7:0]))
    );

endmodule

rtl:
module top_module(
    input wire [15:0] in,
    output wire [7:0] out_hi,
    output wire [7:0] out_lo,
    input wire clk
);

    // Pipeline registers
    reg [15:0] stage1_out;
    reg [7:0] stage2_out_hi, stage2_out_lo;

    // Barrel shifter
    wire [15:0] shifted_data = in >> 8;

    // Clocked register for stage1_out
    always @(posedge clk) begin
        stage1_out <= shifted_data;
    end

    // Output registers
    always @(posedge clk) begin
        stage2_out_hi <= stage1_out[15:8];
        stage2_out_lo <= in[7:0];
    end

    // Output assignments
    assign out_hi = stage2_out_hi;
    assign out_lo = stage2_out_lo;

endmodule

sva:
module top_module_assertions(
    input logic [15:0] in,
    input logic [7:0]  out_hi,
    input logic [7:0]  out_lo,
    input logic        clk,
    input logic [15:0] stage1_out,
    input logic [7:0]  stage2_out_hi,
    input logic [7:0]  stage2_out_lo,
    input logic [15:0] shifted_data
);

    // shifted_data is the input shifted right by 8 bits.
    check_shifted_data_definition: assert property (
        @(posedge clk) (shifted_data == (in >> 8))
    );

    // stage1_out captures shifted_data on the previous clock.
    check_stage1_captures_shifted_data: assert property (
        @(posedge clk) (!$initstate) |-> (stage1_out == $past(shifted_data))
    );

    // stage1_out low byte comes from the previous input high byte.
    check_stage1_lower_byte_mapping: assert property (
        @(posedge clk) (!$initstate) |-> (stage1_out[7:0] == $past(in[15:8]))
    );

    // stage1_out high byte is zero after the right shift by 8.
    check_stage1_upper_byte_zero: assert property (
        @(posedge clk) (!$initstate) |-> (stage1_out[15:8] == 8'h00)
    );

    // stage2_out_hi captures the previous stage1_out high byte.
    check_stage2_hi_captures_stage1_upper: assert property (
        @(posedge clk) (!$initstate) |-> (stage2_out_hi == $past(stage1_out[15:8]))
    );

    // stage2_out_lo captures the previous input low byte.
    check_stage2_lo_captures_input_lower: assert property (
        @(posedge clk) (!$initstate) |-> (stage2_out_lo == $past(in[7:0]))
    );

    // out_hi is directly driven by stage2_out_hi.
    check_out_hi_matches_stage2: assert property (
        @(posedge clk) (out_hi == stage2_out_hi)
    );

    // out_lo is directly driven by stage2_out_lo.
    check_out_lo_matches_stage2: assert property (
        @(posedge clk) (out_lo == stage2_out_lo)
    );

    // out_lo reflects the previous input low byte.
    check_out_lo_one_cycle_latency: assert property (
        @(posedge clk) (!$initstate) |-> (out_lo == $past(in[7:0]))
    );

    // A zero high byte in stage1_out reaches out_hi on the next clock.
    check_zero_high_byte_propagates_to_output: assert property (
        @(posedge clk) (stage1_out[15:8] == 8'h00) |=> (out_hi == 8'h00)
    );

endmodule

rtl:
module arithmetic_module(
    input [7:0] A,
    input [7:0] B,
    output reg [15:0] C
);

    always @ (A, B) begin
        C = A + B;
        if (C > 16'hFFFF) begin
            C = C[15:0];
        end
    end

endmodule

sva:
module arithmetic_module_sva(
    input logic [7:0] A,
    input logic [7:0] B,
    input logic [15:0] C
);

    // Low byte matches the addition result modulo 256.
    check_sum_low_byte: assert property (
        @($global_clock) C[7:0] == ((A + B) & 8'hFF)
    );

    // Upper byte stays zero after the assignment to C.
    check_sum_high_byte_zero: assert property (
        @($global_clock) C[15:8] == 8'h00
    );

    // When A is zero, C passes B through in the low byte.
    check_a_zero_passthrough: assert property (
        @($global_clock) (A == 8'h00) |-> (C == {8'h00, B})
    );

    // When B is zero, C passes A through in the low byte.
    check_b_zero_passthrough: assert property (
        @($global_clock) (B == 8'h00) |-> (C == {8'h00, A})
    );

    // FF + 01 wraps in the low byte.
    check_ff_plus_01_wraps: assert property (
        @($global_clock) ((A == 8'hFF) && (B == 8'h01)) |-> (C == 16'h0000)
    );

    // FF + FF produces FE in the low byte.
    check_ff_plus_ff_truncates: assert property (
        @($global_clock) ((A == 8'hFF) && (B == 8'hFF)) |-> (C == 16'h00FE)
    );

endmodule

rtl:
module and_gate (
    A,
    B,
    C,
    D,
    Y
);

    // Module ports
    input  A, B, C, D;
    output Y;

    // Local signals
    wire  not_A, not_B, not_C, not_D;
    wire  and1_out, and2_out, and3_out;

    //  Name  Output      Other arguments
    not not_A_gate (not_A, A);
    not not_B_gate (not_B, B);
    not not_C_gate (not_C, C);
    not not_D_gate (not_D, D);

    and and1_gate (and1_out, not_A, not_B);
    and and2_gate (and2_out, not_C, not_D);
    and and3_gate (Y, and1_out, and2_out);

endmodule

sva:
module and_gate_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic Y
);

    // External clk samples this combinational DUT; the RTL has no reset.

    // Y matches the implemented AND of the four inverted inputs.
    check_output_function: assert property (
        @(posedge clk) Y == ((~A) & (~B) & (~C) & (~D))
    );

    // All inputs low must drive Y high.
    check_all_low_drives_y_high: assert property (
        @(posedge clk) (!A && !B && !C && !D) |-> Y
    );

    // Y high means all inputs are low.
    check_y_high_requires_all_low: assert property (
        @(posedge clk) Y |-> (!A && !B && !C && !D)
    );

    // Y low means at least one input is high.
    check_y_low_requires_some_input_high: assert property (
        @(posedge clk) (!Y) |-> (A || B || C || D)
    );

    // A high forces Y low.
    check_a_high_forces_y_low: assert property (
        @(posedge clk) A |-> !Y
    );

    // B high forces Y low.
    check_b_high_forces_y_low: assert property (
        @(posedge clk) B |-> !Y
    );

    // C high forces Y low.
    check_c_high_forces_y_low: assert property (
        @(posedge clk) C |-> !Y
    );

    // D high forces Y low.
    check_d_high_forces_y_low: assert property (
        @(posedge clk) D |-> !Y
    );

endmodule

rtl:
module karnaugh_map(
  input wire A, B, C, D,
  output reg F
);

  always @* begin
    case ({A,B})
      2'b00: F = D ^ C;
      2'b01: F = B ^ C;
      2'b11: F = C ^ D;
      2'b10: F = A ^ D;
    endcase
  end

endmodule

sva:
module karnaugh_map_sva (
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic F
);

    // AB=00 selects D xor C.
    check_case_00_d_xor_c: assert property (
        @($global_clock) ({A,B} === 2'b00) |-> (F === (D ^ C))
    );

    // AB=01 selects B xor C.
    check_case_01_b_xor_c: assert property (
        @($global_clock) ({A,B} === 2'b01) |-> (F === (B ^ C))
    );

    // AB=11 selects C xor D.
    check_case_11_c_xor_d: assert property (
        @($global_clock) ({A,B} === 2'b11) |-> (F === (C ^ D))
    );

    // AB=10 selects A xor D.
    check_case_10_a_xor_d: assert property (
        @($global_clock) ({A,B} === 2'b10) |-> (F === (A ^ D))
    );

endmodule

rtl:
module binary_counter(clk, reset, count);

  input clk, reset;
  output reg [7:0] count;

  always @(posedge clk or negedge reset) begin
    if (reset == 0) begin
      count <= 0;
    end else begin
      count <= count + 1;
    end
  end

endmodule

sva:
module binary_counter_sva (
    input logic       clk,
    input logic       reset,
    input logic [7:0] count
);

    // A sampled low reset forces count to zero by the next sampled cycle.
    check_reset_clears_by_next_cycle: assert property (
        @(posedge clk) disable iff ($initstate)
        !reset |=> (count == 8'h00)
    );

    // The first sampled cycle after reset release still has count at zero.
    check_release_from_reset_starts_at_zero: assert property (
        @(posedge clk) disable iff (!reset || $initstate)
        !$past(reset) |-> (count == 8'h00)
    );

    // Any nonzero sampled count value comes from incrementing the prior value.
    check_nonzero_values_come_from_increment: assert property (
        @(posedge clk) disable iff (!reset || $initstate)
        ($past(reset) && (count != 8'h00)) |-> (count == ($past(count) + 8'd1))
    );

    // A sampled 8'hFF count wraps to zero on the next sampled cycle.
    check_ff_wraps_to_zero: assert property (
        @(posedge clk) disable iff (!reset || $initstate)
        ($past(reset) && ($past(count) == 8'hFF)) |-> (count == 8'h00)
    );

endmodule

rtl:
module my_or_gate (
    X,
    A,
    B,
    C
);

    output X;
    input  A;
    input  B;
    input  C;

    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

