sva:
module my_or_gate_assertions (
    input logic X,
    input logic A,
    input logic B,
    input logic C
);

    // X must always equal the OR of A, B, and C.
    check_or_function: assert property (
        @($global_clock) X === (A | B | C)
    );

    // A high must force X high.
    check_a_high_drives_x_high: assert property (
        @($global_clock) (A === 1'b1) |-> (X === 1'b1)
    );

    // B high must force X high.
    check_b_high_drives_x_high: assert property (
        @($global_clock) (B === 1'b1) |-> (X === 1'b1)
    );

    // C high must force X high.
    check_c_high_drives_x_high: assert property (
        @($global_clock) (C === 1'b1) |-> (X === 1'b1)
    );

    // X high must be caused by at least one high input.
    check_x_high_has_high_input: assert property (
        @($global_clock) (X === 1'b1) |-> ((A === 1'b1) || (B === 1'b1) || (C === 1'b1))
    );

    // All inputs low must force X low.
    check_all_inputs_low_drive_x_low: assert property (
        @($global_clock) ((A === 1'b0) && (B === 1'b0) && (C === 1'b0)) |-> (X === 1'b0)
    );

    // X low requires all inputs to be low.
    check_x_low_requires_all_inputs_low: assert property (
        @($global_clock) (X === 1'b0) |-> ((A === 1'b0) && (B === 1'b0) && (C === 1'b0))
    );

endmodule

rtl:
module JAND4B(A1, A2, A3, A4, O);
input   A1;
input   A2;
input   A3;
input   A4;
output  O;

wire n1, n2, n3;

JNAND3B g1(n1, A1, A2, A3);
JNAND3B g2(n2, n1, A4, n1);
JNAND3B g3(n3, n2, n2, n2);
JNAND3B g4(O, n3, n3, n3);

endmodule

module JNAND3B(
    output O,
    input A1,
    input A2,
    input A3
);

// Implement the NAND operation
assign O = ~(A1 & A2 & A3);

endmodule

sva:
module JAND4B_assertions (
    input logic A1,
    input logic A2,
    input logic A3,
    input logic A4,
    input logic O
);

    // Output equals the implemented NAND-chain function.
    check_output_function: assert property (
        @($global_clock) (O === ((A1 & A2 & A3) | ~A4))
    );

    // A low A4 forces the output high.
    check_a4_low_forces_output_high: assert property (
        @($global_clock) (A4 === 1'b0) |-> (O === 1'b1)
    );

    // High A1, A2, and A3 force the output high.
    check_a123_high_forces_output_high: assert property (
        @($global_clock) ((A1 === 1'b1) && (A2 === 1'b1) && (A3 === 1'b1)) |-> (O === 1'b1)
    );

    // With A4 high, a low A1 forces the output low.
    check_a4_high_a1_low_forces_output_low: assert property (
        @($global_clock) ((A4 === 1'b1) && (A1 === 1'b0)) |-> (O === 1'b0)
    );

    // With A4 high, a low A2 forces the output low.
    check_a4_high_a2_low_forces_output_low: assert property (
        @($global_clock) ((A4 === 1'b1) && (A2 === 1'b0)) |-> (O === 1'b0)
    );

    // With A4 high, a low A3 forces the output low.
    check_a4_high_a3_low_forces_output_low: assert property (
        @($global_clock) ((A4 === 1'b1) && (A3 === 1'b0)) |-> (O === 1'b0)
    );

    // A low output requires A4 to be high.
    check_output_low_requires_a4_high: assert property (
        @($global_clock) (O === 1'b0) |-> (A4 === 1'b1)
    );

    // A high output with A4 high requires A1, A2, and A3 high.
    check_output_high_with_a4_high_requires_a123_high: assert property (
        @($global_clock) ((O === 1'b1) && (A4 === 1'b1)) |-> ((A1 === 1'b1) && (A2 === 1'b1) && (A3 === 1'b1))
    );

endmodule

rtl:
module top_module (
    input clk,
    input reset,      // Asynchronous active-high reset
    output [3:0] q,
    output reg [2:0] count_ones
);

    reg [3:0] counter;

    // Binary counter
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            counter <= 4'b0000;
        end else begin
            counter <= counter + 1;
        end
    end

    // Count the number of '1's in the binary representation of the count value
    always @(counter) begin
        count_ones <= {counter[0], counter[1], counter[2], counter[3]} 
                        - ((counter[0] & counter[1]) | (counter[0] & counter[2]) | (counter[0] & counter[3]) | (counter[1] & counter[2]) | (counter[1] & counter[3]) | (counter[2] & counter[3]));
    end

    assign q = counter;

endmodule

sva:
module top_module_sva (
    input logic       clk,
    input logic       reset,
    input logic [3:0] q,
    input logic [2:0] count_ones
);

    // While reset remains asserted across sampled clocks, both outputs stay zero.
    check_reset_holds_zero: assert property (
        @(posedge clk)
        (($past(reset) === 1'b1) && reset) |-> ((q == 4'b0000) && (count_ones == 3'b000))
    );

    // On the first sampled clock after reset deasserts, the visible state is still zero.
    check_reset_release_starts_zero: assert property (
        @(posedge clk) disable iff (reset)
        ($past(reset) === 1'b1) |-> ((q == 4'b0000) && (count_ones == 3'b000))
    );

    // On consecutive sampled non-reset clocks, any nonzero q must be the prior value plus one.
    check_counter_nonzero_is_increment: assert property (
        @(posedge clk) disable iff (reset)
        (($past(reset) === 1'b0) && (q != 4'h0)) |-> (q == ($past(q) + 4'd1))
    );

    // On consecutive sampled non-reset clocks, a prior maximum count wraps to zero.
    check_counter_wraps_from_max: assert property (
        @(posedge clk) disable iff (reset)
        (($past(reset) === 1'b0) && ($past(q) == 4'hf)) |-> (q == 4'h0)
    );

    // When q has no pair of high bits, count_ones matches the implemented 3-bit reversed slice.
    check_count_ones_no_pair: assert property (
        @(posedge clk) disable iff (reset)
        (($past(reset) === 1'b0) &&
         !((q[0] & q[1]) | (q[0] & q[2]) | (q[0] & q[3]) |
           (q[1] & q[2]) | (q[1] & q[3]) | (q[2] & q[3])))
        |-> (count_ones == {q[1], q[2], q[3]})
    );

    // When q has any pair of high bits, count_ones is that 3-bit reversed slice minus one.
    check_count_ones_with_pair: assert property (
        @(posedge clk) disable iff (reset)
        (($past(reset) === 1'b0) &&
         ((q[0] & q[1]) | (q[0] & q[2]) | (q[0] & q[3]) |
          (q[1] & q[2]) | (q[1] & q[3]) | (q[2] & q[3])))
        |-> (count_ones == ({q[1], q[2], q[3]} - 3'd1))
    );

endmodule

rtl:
module comparator (
    input [3:0] a,
    input [3:0] b,
    output reg equal,
    output reg greater,
    output reg less
);

    always @(*) begin
        if (a == b) begin
            equal = 1;
            greater = 0;
            less = 0;
        end else if (a > b) begin
            equal = 0;
            greater = 1;
            less = 0;
        end else begin
            equal = 0;
            greater = 0;
            less = 1;
        end
    end

endmodule

sva:
module comparator_sva (
    input logic clk,
    input logic [3:0] a,
    input logic [3:0] b,
    input logic equal,
    input logic greater,
    input logic less
);

    // When inputs are equal, only equal is asserted.
    check_equal_case: assert property (
        @(posedge clk) (a == b) |-> (equal && !greater && !less)
    );

    // When a is greater than b, only greater is asserted.
    check_greater_case: assert property (
        @(posedge clk) (a > b) |-> (!equal && greater && !less)
    );

    // When a is less than b, only less is asserted.
    check_less_case: assert property (
        @(posedge clk) (a < b) |-> (!equal && !greater && less)
    );

    // equal high means the inputs must match.
    check_equal_implies_inputs_equal: assert property (
        @(posedge clk) equal |-> (a == b)
    );

    // greater high means a must be larger than b.
    check_greater_implies_a_gt_b: assert property (
        @(posedge clk) greater |-> (a > b)
    );

    // less high means a must be smaller than b.
    check_less_implies_a_lt_b: assert property (
        @(posedge clk) less |-> (a < b)
    );

    // Exactly one comparison result is asserted at a time.
    check_outputs_onehot: assert property (
        @(posedge clk)
        (equal || greater || less) &&
        !(equal && greater) &&
        !(equal && less) &&
        !(greater && less)
    );

endmodule

rtl:
module four_input_module (
    input A1,
    input A2,
    input A3,
    input B1,
    output X
);

    assign X = (A1 & A2 & A3) ? 1 : (B1 ? 0 : 0);

endmodule

sva:
module four_input_module_sva (
    input logic A1,
    input logic A2,
    input logic A3,
    input logic B1,
    input logic X
);

    // X matches the exact RTL expression.
    check_x_matches_rtl_expression: assert property (
        @($global_clock) X === ((A1 & A2 & A3) ? 1'b1 : (B1 ? 1'b0 : 1'b0))
    );

    // X is functionally the AND of A1, A2, and A3.
    check_x_equals_three_input_and: assert property (
        @($global_clock) X === (A1 & A2 & A3)
    );

    // All three A inputs high force X high.
    check_all_a_high_drives_x_high: assert property (
        @($global_clock) ((A1 & A2 & A3) === 1'b1) |-> (X === 1'b1)
    );

    // Any low A input forces X low.
    check_any_a_low_drives_x_low: assert property (
        @($global_clock) ((A1 === 1'b0) || (A2 === 1'b0) || (A3 === 1'b0)) |-> (X === 1'b0)
    );

    // X can only be high when all three A inputs are high.
    check_x_high_requires_all_a_high: assert property (
        @($global_clock) (X === 1'b1) |-> ((A1 & A2 & A3) === 1'b1)
    );

endmodule

rtl:
module clock_divider(
    input clk_50,
    output reg clk_1
);

    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    reg [31:0] counter = 0;

    always @(posedge clk_50) begin
        counter <= counter + 1;
        if (counter == 50000000) begin
            counter <= 0;
            clk_1 <= ~clk_1;
        end
    end

endmodule

sva:
module clock_divider_sva (
    input logic        clk_50,
    input logic        clk_1,
    input logic [31:0] counter
);

    // Counter increments by one when it is not at the terminal count.
    check_counter_increments: assert property (
        @(posedge clk_50)
        (counter != 32'd50000000) |=> (counter == ($past(counter) + 32'd1))
    );

    // Counter resets to zero after reaching the terminal count.
    check_counter_wraps_to_zero: assert property (
        @(posedge clk_50)
        (counter == 32'd50000000) |=> (counter == 32'd0)
    );

    // clk_1 toggles after the terminal count is reached.
    check_clk1_toggles_on_terminal_count: assert property (
        @(posedge clk_50)
        (counter == 32'd50000000) |=> (clk_1 === ~$past(clk_1))
    );

    // clk_1 holds its value when the counter is not at the terminal count.
    check_clk1_holds_when_not_terminal: assert property (
        @(posedge clk_50)
        (counter != 32'd50000000) |=> (clk_1 === $past(clk_1))
    );

endmodule

module reg_4bit_async_reset_enable_sva (
    input logic clk,
    input logic rst,
    input logic en,
    input logic [3:0] din,
    input logic [3:0] dout
);

    // Active-low reset forces dout to zero on any sampled clock.
    check_reset_clears_dout: assert property (
        @(posedge clk) (!rst) |-> (dout == 4'b0000)
    );

    // A sampled reset low leaves dout at zero on the following sampled clock.
    check_post_reset_stays_zero: assert property (
        @(posedge clk) (!rst) |=> (dout == 4'b0000)
    );

    // With enable low, dout either holds its value or has been asynchronously cleared to zero.
    check_disabled_cycle_holds_or_resets: assert property (
        @(posedge clk) disable iff (!rst)
        (!en) |=> ((dout == 4'b0000) || (dout == $past(dout)))
    );

    // With enable high, dout either captures the prior din or has been asynchronously cleared to zero.
    check_enabled_cycle_loads_or_resets: assert property (
        @(posedge clk) disable iff (!rst)
        en |=> ((dout == 4'b0000) || (dout == $past(din)))
    );

endmodule

rtl:
module logic_or(A1, A2, A3, O);
input   A1;
input   A2;
input   A3;
output  O;

wire or1;

assign or1 = A1 | A2 | A3;
assign O = or1;

endmodule

sva:
module logic_or_sva (
    input logic clk,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic O
);

    // Output equals the OR of the three inputs.
    check_output_matches_or: assert property (
        @(posedge clk) O == (A1 | A2 | A3)
    );

    // Output is low when all inputs are low.
    check_all_inputs_low_drives_output_low: assert property (
        @(posedge clk) (!(A1 | A2 | A3)) |-> (!O)
    );

    // A high A1 input forces the output high.
    check_a1_high_drives_output_high: assert property (
        @(posedge clk) A1 |-> O
    );

    // A high A2 input forces the output high.
    check_a2_high_drives_output_high: assert property (
        @(posedge clk) A2 |-> O
    );

    // A high A3 input forces the output high.
    check_a3_high_drives_output_high: assert property (
        @(posedge clk) A3 |-> O
    );

endmodule

rtl:
module binary_to_gray (
    input [3:0] A,
    output [3:0] G
);

    assign G[3] = A[3];
    assign G[2] = A[3] ^ A[2];
    assign G[1] = A[2] ^ A[1];
    assign G[0] = A[1] ^ A[0];

endmodule

sva:
module binary_to_gray_sva (
    input logic [3:0] A,
    input logic [3:0] G
);

    // G[3] is a direct copy of A[3].
    check_gray_bit3_passthrough: assert property (
        @($global_clock) G[3] == A[3]
    );

    // G[2] is the XOR of A[3] and A[2].
    check_gray_bit2_xor: assert property (
        @($global_clock) G[2] == (A[3] ^ A[2])
    );

    // G[1] is the XOR of A[2] and A[1].
    check_gray_bit1_xor: assert property (
        @($global_clock) G[1] == (A[2] ^ A[1])
    );

    // G[0] is the XOR of A[1] and A[0].
    check_gray_bit0_xor: assert property (
        @($global_clock) G[0] == (A[1] ^ A[0])
    );

    // The full Gray output matches the implemented conversion.
    check_gray_vector_mapping: assert property (
        @($global_clock) G == {A[3], (A[3] ^ A[2]), (A[2] ^ A[1]), (A[1] ^ A[0])}
    );

endmodule

rtl:
module switch (
    input [1:0] address,
    input clk,
    input [7:0] in_port,
    input reset_n,
    output reg [31:0] readdata
);

wire clk_en;
wire [7:0] data_in;
wire [7:0] read_mux_out;

assign clk_en = 1;

assign read_mux_out = {8 {(address == 0)}} & data_in;

always @(posedge clk or negedge reset_n) begin
    if (reset_n == 0) begin
        readdata <= 0;
    end else if (clk_en) begin
        readdata <= {32'b0 | read_mux_out};
    end
end

assign data_in = in_port;

endmodule

sva:
module switch_sva (
    input logic [1:0]  address,
    input logic        clk,
    input logic [7:0]  in_port,
    input logic        reset_n,
    input logic [31:0] readdata
);

    // When reset is sampled low, readdata is cleared.
    check_reset_clears_readdata: assert property (
        @(posedge clk) (!$initstate && !reset_n) |-> (readdata == 32'h0000_0000)
    );

    // Address 0 causes the next registered read to return the input byte.
    check_address_zero_captures_input: assert property (
        @(posedge clk) disable iff (!reset_n)
        (address == 2'b00) |=> (readdata == {24'h000000, $past(in_port)})
    );

    // Nonzero addresses cause the next registered read to return zero.
    check_nonzero_address_returns_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (address != 2'b00) |=> (readdata == 32'h0000_0000)
    );

    // Each active clock loads the muxed read value into readdata.
    check_registered_read_data: assert property (
        @(posedge clk) disable iff (!reset_n)
        1'b1 |=> (readdata == (($past(address) == 2'b00) ? {24'h000000, $past(in_port)} : 32'h0000_0000))
    );

    // The registered read value is always zero-extended on the next cycle.
    check_zero_extended_readdata: assert property (
        @(posedge clk) disable iff (!reset_n)
        1'b1 |=> (readdata[31:8] == 24'h000000)
    );

endmodule

rtl:
module ripple_carry_adder(
    input [3:0] A,
    input [3:0] B,
    output [3:0] S,
    output Cout
);
    wire [3:0] C;

    assign C[0] = 1'b0; // Initialize the carry-in to 0

    // Full adder for bit 0
    full_adder FA0(A[0], B[0], C[0], S[0], C[1]);

    // Full adder for bit 1
    full_adder FA1(A[1], B[1], C[1], S[1], C[2]);

    // Full adder for bit 2
    full_adder FA2(A[2], B[2], C[2], S[2], C[3]);

    // Full adder for bit 3
    full_adder FA3(A[3], B[3], C[3], S[3], Cout);

endmodule

module full_adder(
    input A,
    input B,
    input Cin,
    output S,
    output Cout
);
    assign S = A ^ B ^ Cin;
    assign Cout = (A & B) | (A & Cin) | (B & Cin);
endmodule

sva:
module ripple_carry_adder_sva (
    input logic       clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] S,
    input logic       Cout
);

    // The 4-bit adder output must equal A + B with zero carry-in.
    check_total_sum: assert property (
        @(posedge clk) {Cout, S} == ({1'b0, A} + {1'b0, B})
    );

    // Bit 0 sum is the XOR of A[0] and B[0] because the initial carry-in is 0.
    check_lsb_sum: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0])
    );

    // Without a carry from bit 0, the upper bits sum without an added carry-in.
    check_upper_sum_without_bit0_carry: assert property (
        @(posedge clk) !(A[0] & B[0]) |-> ({Cout, S[3:1]} == ({1'b0, A[3:1]} + {1'b0, B[3:1]}))
    );

    // With a carry from bit 0, the upper bits sum includes a carry-in of 1.
    check_upper_sum_with_bit0_carry: assert property (
        @(posedge clk) (A[0] & B[0]) |-> ({Cout, S[3:1]} == ({1'b0, A[3:1]} + {1'b0, B[3:1]} + 4'd1))
    );

    // A value of zero on A passes B through unchanged with no overflow.
    check_zero_a_passthrough: assert property (
        @(posedge clk) (A == 4'b0000) |-> ({Cout, S} == {1'b0, B})
    );

    // A value of zero on B passes A through unchanged with no overflow.
    check_zero_b_passthrough: assert property (
        @(posedge clk) (B == 4'b0000) |-> ({Cout, S} == {1'b0, A})
    );

    // When A and B have no overlapping 1s, the result is their XOR with no carry-out.
    check_disjoint_inputs_xor: assert property (
        @(posedge clk) ((A & B) == 4'b0000) |-> ({Cout, S} == {1'b0, (A ^ B)})
    );

    // Adding 1 to 4'hF must ripple a carry through all four stages.
    check_full_ripple_propagation: assert property (
        @(posedge clk) (((A == 4'hF) && (B == 4'h1)) || ((A == 4'h1) && (B == 4'hF))) |-> ({Cout, S} == 5'h10)
    );

    // The maximum input pair must produce the expected overflowed sum.
    check_max_plus_max: assert property (
        @(posedge clk) ((A == 4'hF) && (B == 4'hF)) |-> ({Cout, S} == 5'h1E)
    );

endmodule

rtl:
module UDM_2x2
   (
        input wire [1:0] in1,
        input wire [1:0] in2,
       output reg [2:0] res
    );

  always @* begin
       case ({in1,in2})
          4'b0000 : begin
                      res = 3'b000;
                   end
          4'b0001 : begin
                      res = 3'b000;
                   end
          4'b0010 : begin
                      res = 3'b000;
                   end
          4'b0011 : begin
                      res = 3'b000;
                   end
          4'b0100 : begin
                      res = 3'b000;
                   end
          4'b0101 : begin
                      res = 3'b001;
                   end
          4'b0110 : begin
                      res = 3'b010;
                   end
          4'b0111 : begin
                      res = 3'b011;
                   end
          4'b1000 : begin
                      res = 3'b000;
                   end
          4'b1001 : begin
                      res = 3'b010;
                   end
          4'b1010 : begin
                      res = 3'b100;
                   end
          4'b1011 : begin
                      res = 3'b110;
                   end
          4'b1100 : begin
                     res = 3'b000;
                   end
          4'b1101 : begin
                      res = 3'b110;
                   end
          4'b1110 : begin
                      res = 3'b011;
                   end
          4'b1111 : begin
                      res = 3'b111;
                   end
       endcase

  end

endmodule

sva:
module UDM_2x2_sva (
    input logic clk,
    input logic [1:0] in1,
    input logic [1:0] in2,
    input logic [2:0] res
);

    // in1=00 always produces zero.
    check_in1_zero_forces_zero: assert property (
        @(posedge clk) (in1 == 2'b00) |-> (res == 3'b000)
    );

    // in2=00 always produces zero.
    check_in2_zero_forces_zero: assert property (
        @(posedge clk) (in2 == 2'b00) |-> (res == 3'b000)
    );

    // in1=01 maps res to zero-extended in2.
    check_in1_one_maps_in2_direct: assert property (
        @(posedge clk) (in1 == 2'b01) |-> (res == {1'b0, in2})
    );

    // in1=10 maps res to in2 shifted left by one.
    check_in1_two_maps_in2_shifted: assert property (
        @(posedge clk) (in1 == 2'b10) |-> (res == {in2, 1'b0})
    );

    // in1=11 and in2=00 produces zero.
    check_in1_three_in2_zero: assert property (
        @(posedge clk) ((in1 == 2'b11) && (in2 == 2'b00)) |-> (res == 3'b000)
    );

    // in1=11 and in2=01 produces 110.
    check_in1_three_in2_one: assert property (
        @(posedge clk) ((in1 == 2'b11) && (in2 == 2'b01)) |-> (res == 3'b110)
    );

    // in1=11 and in2=10 produces 011.
    check_in1_three_in2_two: assert property (
        @(posedge clk) ((in1 == 2'b11) && (in2 == 2'b10)) |-> (res == 3'b011)
    );

    // in1=11 and in2=11 produces 111.
    check_in1_three_in2_three: assert property (
        @(posedge clk) ((in1 == 2'b11) && (in2 == 2'b11)) |-> (res == 3'b111)
    );

endmodule

rtl:
module shift_register (
    input clk,
    input reset,
    input load,
    input [7:0] data_in,
    output reg [15:0] q
);

always @(posedge clk, posedge reset) begin
    if (reset) begin
        q <= 0;
    end else if (load) begin
        q <= {data_in, q[15:8]};
    end else begin
        q <= {q[14:0], q[15]};
    end
end

endmodule

module d_flip_flop (
    input clk,
    input reset,
    input d,
    output reg q
);

always @(negedge clk, posedge reset) begin
    if (reset) begin
        q <= 0;
    end else begin
        q <= d;
    end
end

endmodule

module functional_module (
    input [15:0] shift_register_out,
    input [0:0] d_flip_flop_out,
    output reg [15:0] q
);

always @(shift_register_out, d_flip_flop_out) begin
    q <= {shift_register_out, d_flip_flop_out};
end

endmodule

module top_module (
    input clk,
    input reset,
    input load,
    input [7:0] data_in,
    input d,
    output [15:0] q
);

wire [15:0] shift_register_out;
wire [0:0] d_flip_flop_out;

shift_register shift_reg(clk, reset, load, data_in, shift_register_out);
d_flip_flop d_ff(clk, reset, d, d_flip_flop_out);
functional_module func_mod(shift_register_out, d_flip_flop_out, q);

endmodule

sva:
module top_module_sva (
    input logic        clk,
    input logic        reset,
    input logic        load,
    input logic [7:0]  data_in,
    input logic        d,
    input logic [15:0] q
);

    // Reset drives the top-level output low on rising clock edges.
    check_reset_clears_output_on_posedge: assert property (
        @(posedge clk) reset |-> (q == 16'h0000)
    );

    // Reset drives the top-level output low on falling clock edges.
    check_reset_clears_output_on_negedge: assert property (
        @(negedge clk) reset |-> (q == 16'h0000)
    );

    // A load places data_in[6:0] into the visible upper q bits.
    check_load_copies_data_into_visible_upper_bits: assert property (
        @(posedge clk) disable iff (reset)
        load |=> (q[15:9] == $past(data_in[6:0]))
    );

    // A load moves the prior visible upper slice down into q[7:1].
    check_load_shifts_prior_visible_bits_down: assert property (
        @(posedge clk) disable iff (reset)
        load |=> (q[7:1] == $past(q[15:9]))
    );

    // Without load, the visible shift-register bits rotate forward.
    check_shift_rotates_visible_bits_when_not_loading: assert property (
        @(posedge clk) disable iff (reset)
        !load |=> (q[15:2] == $past(q[14:1]))
    );

    // The output LSB reflects the previous falling-edge sample of d.
    check_falling_edge_captures_d_into_output_lsb: assert property (
        @(negedge clk) disable iff (reset)
        1'b1 |=> (q[0] == $past(d))
    );

endmodule

rtl:
module clk_div(
	input clk,
	input wire rst,
	input wire SW2,
	output reg[31:0] clkdiv,
	output wire Clk_CPU
    );


always @(posedge clk or posedge rst)begin
	if (rst) begin
		clkdiv <= 0;
	end else begin
		clkdiv <= clkdiv + 1'b1;
	end
end

assign Clk_CPU = clk;

endmodule

sva:
module clk_div_assertions (
    input logic        clk,
    input logic        rst,
    input logic        SW2,
    input logic [31:0] clkdiv,
    input logic        Clk_CPU
);

    // Clk_CPU is wired directly to clk.
    check_clk_cpu_mirrors_clk: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        (Clk_CPU == clk)
    );

    // A sampled reset must leave clkdiv at zero on the next sampled clock.
    check_clkdiv_zero_after_sampled_reset: assert property (
        @(posedge clk) disable iff ($initstate)
        $past(rst) |-> (clkdiv == 32'd0)
    );

    // Any nonzero sampled count must be the prior sampled count plus one.
    check_clkdiv_increments_for_nonzero_values: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        (clkdiv != 32'd0) |-> (clkdiv == ($past(clkdiv) + 32'd1))
    );

    // A sampled maximum count must wrap back to zero.
    check_clkdiv_wraps_after_max: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        ($past(clkdiv) == 32'hFFFF_FFFF) |-> (clkdiv == 32'd0)
    );

endmodule

rtl:
module sky130_fd_sc_hdll__o22a (
    X ,
    A1,
    A2,
    B1,
    B2
);

    output X ;
    input  A1;
    input  A2;
    input  B1;
    input  B2;

    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    wire or0_out   ;
    wire or1_out   ;
    wire and0_out_X;

    or  or0  (or0_out   , A2, A1          );
    or  or1  (or1_out   , B2, B1          );
    and and0 (and0_out_X, or0_out, or1_out);
    buf buf0 (X         , and0_out_X      );

endmodule

sva:
module sky130_fd_sc_hdll__o22a_sva (
    input logic clk,
    input logic X,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic B2
);

    // X matches the implemented OR-OR-AND function.
    check_o22a_equation: assert property (
        @(posedge clk) X == ((A1 | A2) & (B1 | B2))
    );

    // Both A-side inputs low force X low.
    check_a_side_low_forces_x_low: assert property (
        @(posedge clk) ((A1 == 1'b0) && (A2 == 1'b0)) |-> (X == 1'b0)
    );

    // Both B-side inputs low force X low.
    check_b_side_low_forces_x_low: assert property (
        @(posedge clk) ((B1 == 1'b0) && (B2 == 1'b0)) |-> (X == 1'b0)
    );

    // Any high on both sides drives X high.
    check_any_a_and_any_b_drive_x_high: assert property (
        @(posedge clk) (((A1 | A2) & (B1 | B2)) == 1'b1) |-> (X == 1'b1)
    );

    // X high requires at least one A-side input high.
    check_x_high_requires_a_side_high: assert property (
        @(posedge clk) (X == 1'b1) |-> ((A1 | A2) == 1'b1)
    );

    // X high requires at least one B-side input high.
    check_x_high_requires_b_side_high: assert property (
        @(posedge clk) (X == 1'b1) |-> ((B1 | B2) == 1'b1)
    );

endmodule

rtl:
module xor_gate (
    input wire a,
    input wire b,
    output wire  out
);

    assign out = a ^ b;

endmodule
module byte_reversal (
    input wire [31:0] in,
    output wire  [31:0] out
);

    assign out = {in[7:0], in[15:8], in[23:16], in[31:24]};

endmodule
module functional_module (
    input wire  in1,
    input wire [31:0] in2,
    output wire  [31:0] out
);

    assign out = {31'b0, in1} | in2;

endmodule
module top_module (
    input wire a,
    input wire b,
    input wire [31:0] in,
    input wire select,
    output wire [31:0] out
);

    wire out_xor;
    wire [31:0] byte_rev_out;
    wire [31:0] func_out;

    xor_gate xor_inst (
        .a(a),
        .b(b),
        .out(out_xor)
    );

    byte_reversal byte_rev_inst (
        .in(in),
        .out(byte_rev_out)
    );

    functional_module func_inst (
        .in1(out_xor),
        .in2(byte_rev_out),
        .out(func_out)
    );

    assign out = (select) ? func_out : {31'b0, out_xor};

endmodule

sva:
module top_module_sva (
    input logic        clk,
    input logic        a,
    input logic        b,
    input logic [31:0] in,
    input logic        select,
    input logic [31:0] out
);

    // When select is low, output is the zero-extended XOR result.
    check_select_low_full: assert property (
        @(posedge clk) (!select) |-> (out == {31'b0, (a ^ b)})
    );

    // When select is low, upper bits are all zero.
    check_select_low_upper_zero: assert property (
        @(posedge clk) (!select) |-> (out[31:1] == 31'b0)
    );

    // When select is low, bit 0 matches a XOR b.
    check_select_low_lsb_xor: assert property (
        @(posedge clk) (!select) |-> (out[0] == (a ^ b))
    );

    // When select is high, output matches the functional path result.
    check_select_high_full: assert property (
        @(posedge clk) select |-> (out == ({31'b0, (a ^ b)} | {in[7:0], in[15:8], in[23:16], in[31:24]}))
    );

    // When select is high, the top byte is in[7:0].
    check_select_high_byte_3: assert property (
        @(posedge clk) select |-> (out[31:24] == in[7:0])
    );

    // When select is high, bits [23:16] are in[15:8].
    check_select_high_byte_2: assert property (
        @(posedge clk) select |-> (out[23:16] == in[15:8])
    );

    // When select is high, bits [15:8] are in[23:16].
    check_select_high_byte_1: assert property (
        @(posedge clk) select |-> (out[15:8] == in[23:16])
    );

    // When select is high, bits [7:1] come from in[31:25].
    check_select_high_low_slice: assert property (
        @(posedge clk) select |-> (out[7:1] == in[31:25])
    );

    // When select is high, bit 0 is reversed bit 0 OR the XOR result.
    check_select_high_lsb_or: assert property (
        @(posedge clk) select |-> (out[0] == (in[24] | (a ^ b)))
    );

    // Output always follows the top-level select mux expression.
    check_top_mux_expression: assert property (
        @(posedge clk) out == (select ? ({31'b0, (a ^ b)} | {in[7:0], in[15:8], in[23:16], in[31:24]}) : {31'b0, (a ^ b)})
    );

endmodule

rtl:
module Debouncer(
  input clk, // clock signal
  input rst_n, // asynchronous reset
  input in, // input signal
  output reg out // output signal
);

parameter COUNT_MAX = 1000; // maximum count value
parameter WAIT_TIME = 10; // wait time in ms

reg [9:0] count; // counter to count up to COUNT_MAX
reg [1:0] state; // state machine to control the debouncing process

always @(posedge clk or negedge rst_n) begin
  if (~rst_n) begin
    count <= 0;
    state <= 2'b00;
    out <= 1'b0;
  end
  else begin
    case (state)
      2'b00: // idle state
        if (in != out) begin
          count <= 0;
          state <= 2'b01;
        end
        else begin
          out <= in;
        end
      2'b01: // waiting state
        if (count >= COUNT_MAX) begin
          out <= in;
          state <= 2'b10;
        end
        else begin
          count <= count + 1;
        end
      2'b10: // debounce state
        if (in != out) begin
          count <= 0;
          state <= 2'b01;
        end
        else begin
          state <= 2'b00;
        end
    endcase
  end
end

endmodule

sva:
module Debouncer_sva #(
    parameter int COUNT_MAX = 1000
) (
    input logic clk,
    input logic rst_n,
    input logic in,
    input logic out,
    input logic [9:0] count,
    input logic [1:0] state
);

    // Reset forces count, state, and output to zero.
    check_reset_values: assert property (
        @(posedge clk) !rst_n |-> (count == 10'd0 && state == 2'b00 && out == 1'b0)
    );

    // In idle, a matching input keeps the FSM in idle and preserves count.
    check_idle_match_stays_idle: assert property (
        @(posedge clk) disable iff (!rst_n)
        ($past(rst_n) && $past(state) == 2'b00 && $past(in) == $past(out))
        |-> (state == 2'b00 && count == $past(count) && out == $past(in))
    );

    // In idle, an input mismatch starts the wait state and clears count.
    check_idle_mismatch_starts_wait: assert property (
        @(posedge clk) disable iff (!rst_n)
        ($past(rst_n) && $past(state) == 2'b00 && $past(in) != $past(out))
        |-> (state == 2'b01 && count == 10'd0 && out == $past(out))
    );

    // In wait, count increments until the threshold is reached.
    check_wait_increments_count: assert property (
        @(posedge clk) disable iff (!rst_n)
        ($past(rst_n) && $past(state) == 2'b01 && $past(count) < COUNT_MAX)
        |-> (state == 2'b01 && count == ($past(count) + 10'd1) && out == $past(out))
    );

    // At the threshold, wait captures the input and moves to debounce state.
    check_wait_threshold_updates_output: assert property (
        @(posedge clk) disable iff (!rst_n)
        ($past(rst_n) && $past(state) == 2'b01 && $past(count) >= COUNT_MAX)
        |-> (state == 2'b10 && count == $past(count) && out == $past(in))
    );

    // The wait state never transitions directly back to idle.
    check_wait_never_goes_directly_idle: assert property (
        @(posedge clk) disable iff (!rst_n)
        ($past(rst_n) && $past(state) == 2'b01)
        |-> (state != 2'b00)
    );

    // In debounce, a new mismatch restarts the wait and clears count.
    check_debounce_mismatch_restarts_wait: assert property (
        @(posedge clk) disable iff (!rst_n)
        ($past(rst_n) && $past(state) == 2'b10 && $past(in) != $past(out))
        |-> (state == 2'b01 && count == 10'd0 && out == $past(out))
    );

    // In debounce, a stable input returns the FSM to idle.
    check_debounce_match_returns_idle: assert property (
        @(posedge clk) disable iff (!rst_n)
        ($past(rst_n) && $past(state) == 2'b10 && $past(in) == $past(out))
        |-> (state == 2'b00 && count == $past(count) && out == $past(out))
    );

    // The debounce state always exits on the next clock.
    check_debounce_exits_next_cycle: assert property (
        @(posedge clk) disable iff (!rst_n)
        ($past(rst_n) && $past(state) == 2'b10)
        |-> (state != 2'b10)
    );

    // Output changes only when wait has reached the threshold.
    check_output_changes_only_after_wait_threshold: assert property (
        @(posedge clk) disable iff (!rst_n)
        ($past(rst_n) && out != $past(out))
        |-> ($past(state) == 2'b01 && $past(count) >= COUNT_MAX && out == $past(in))
    );

endmodule

