module sparc_ifu_incr46(a, a_inc, ofl);
   input  [45:0]  a;
   output [45:0]  a_inc;
   output 	  ofl;

   reg [45:0] 	  a_inc;
   reg 		  ofl;

   always @ (a)
     begin
	      a_inc = a + (46'b1);
	      ofl = (~a[45]) & a_inc[45];
     end



endmodule

sva:
module sparc_ifu_incr46_sva (
    input logic        clk,
    input logic [45:0] a,
    input logic [45:0] a_inc,
    input logic        ofl
);

    // a_inc must always be the 46-bit input incremented by one.
    check_increment_result: assert property (
        @(posedge clk) a_inc == (a + 46'd1)
    );

    // ofl must follow the RTL overflow expression.
    check_overflow_definition: assert property (
        @(posedge clk) ofl == ((~a[45]) & a_inc[45])
    );

    // Overflow occurs only when incrementing the largest positive 46-bit value.
    check_overflow_condition: assert property (
        @(posedge clk) ofl == ((~a[45]) & (&a[44:0]))
    );

    // Zero must increment to one without overflow.
    check_zero_case: assert property (
        @(posedge clk) (a == 46'd0) |-> (a_inc == 46'd1) && (ofl == 1'b0)
    );

    // The largest positive value must roll to the sign bit and assert overflow.
    check_positive_max_case: assert property (
        @(posedge clk) (a == {1'b0, {45{1'b1}}}) |-> (a_inc == {1'b1, {45{1'b0}}}) && (ofl == 1'b1)
    );

    // All ones must wrap to zero without overflow.
    check_all_ones_wrap_case: assert property (
        @(posedge clk) (a == {46{1'b1}}) |-> (a_inc == 46'd0) && (ofl == 1'b0)
    );

endmodule

module Register_sva (
    input logic        clk,
    input logic        reset,
    input logic        en,
    input logic        byte_lo,
    input logic        byte_hi,
    input logic [15:0] d,
    input logic [15:0] q
);

    // Synchronous reset clears the full register.
    check_reset_clears_q: assert property (
        @(posedge clk)
        reset |=> (q == 16'h0000)
    );

    // Low byte updates from d when enabled and selected.
    check_low_byte_write: assert property (
        @(posedge clk) disable iff (reset)
        (en && byte_lo) |=> (q[7:0] == $past(d[7:0]))
    );

    // Low byte holds its value when not written.
    check_low_byte_hold: assert property (
        @(posedge clk) disable iff (reset)
        (!en || !byte_lo) |=> (q[7:0] == $past(q[7:0]))
    );

    // High byte updates from d when enabled and selected.
    check_high_byte_write: assert property (
        @(posedge clk) disable iff (reset)
        (en && byte_hi) |=> (q[15:8] == $past(d[15:8]))
    );

    // High byte holds its value when not written.
    check_high_byte_hold: assert property (
        @(posedge clk) disable iff (reset)
        (!en || !byte_hi) |=> (q[15:8] == $past(q[15:8]))
    );

endmodule

