rtl:
module accumulator #(
  parameter n = 4 // number of input signals
)(
  input [n-1:0] in,
  output reg [n:0] out
);

integer i;

always @(*) begin
  out = 0;
  for (i = 0; i < n; i = i + 1) begin
    out = out + in[i];
  end
end

endmodule

sva:
module accumulator_sva #(
    parameter int unsigned n = 4
)(
    input logic clk,
    input logic [n-1:0] in,
    input logic [n:0] out
);

    // out equals the number of asserted input bits.
    check_out_matches_input_popcount: assert property (
        @(posedge clk) out == $countones(in)
    );

    // out never exceeds the number of inputs.
    check_out_within_valid_range: assert property (
        @(posedge clk) out <= n
    );

    // A zero input vector produces a zero output.
    check_zero_input_gives_zero_output: assert property (
        @(posedge clk) (in == '0) |-> (out == '0)
    );

    // A zero output implies no input bits are set.
    check_zero_output_implies_zero_input: assert property (
        @(posedge clk) (out == '0) |-> (in == '0)
    );

    // A one-hot input vector produces an output of one.
    check_onehot_input_gives_one: assert property (
        @(posedge clk) $onehot(in) |-> (out == 1)
    );

    // An all-ones input vector produces an output of n.
    check_all_ones_input_gives_n: assert property (
        @(posedge clk) (in == {n{1'b1}}) |-> (out == n)
    );

    // If the sampled input is unchanged, the sampled output is unchanged.
    check_stable_input_keeps_stable_output: assert property (
        @(posedge clk) !$initstate && (in == $past(in)) |-> (out == $past(out))
    );

endmodule

module logic_gate_assertions (
    input logic clk,
    input logic Y,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic B1,
    input logic VPWR,
    input logic VGND
);

    // Y must match the RTL equation.
    check_y_matches_rtl_equation: assert property (
        @(posedge clk)
        Y == (((A1 & A2 & A3) | (A1 & ~B1) | (~A1 & B1) | (~A1 & ~A2 & ~A3 & B1)) ? 1'b1 : 1'b0)
    );

    // With A1 low, Y must follow B1.
    check_a1_low_y_follows_b1: assert property (
        @(posedge clk)
        (A1 == 1'b0) |-> (Y == B1)
    );

    // With A1 high and B1 low, Y must be high.
    check_a1_high_b1_low_y_high: assert property (
        @(posedge clk)
        ((A1 == 1'b1) && (B1 == 1'b0)) |-> (Y == 1'b1)
    );

    // With A1 high and B1 high, Y must equal A2 & A3.
    check_a1_high_b1_high_y_equals_a2_and_a3: assert property (
        @(posedge clk)
        ((A1 == 1'b1) && (B1 == 1'b1)) |-> (Y == (A2 & A3))
    );

    // With A1 and B1 low, Y must be low.
    check_a1_low_b1_low_y_low: assert property (
        @(posedge clk)
        ((A1 == 1'b0) && (B1 == 1'b0)) |-> (Y == 1'b0)
    );

    // With A1 and B1 high and A2 low, Y must be low.
    check_a1_b1_high_a2_low_y_low: assert property (
        @(posedge clk)
        ((A1 == 1'b1) && (B1 == 1'b1) && (A2 == 1'b0)) |-> (Y == 1'b0)
    );

    // With A1 and B1 high and A3 low, Y must be low.
    check_a1_b1_high_a3_low_y_low: assert property (
        @(posedge clk)
        ((A1 == 1'b1) && (B1 == 1'b1) && (A3 == 1'b0)) |-> (Y == 1'b0)
    );

    // With A1, B1, A2, and A3 high, Y must be high.
    check_a1_b1_a2_a3_high_y_high: assert property (
        @(posedge clk)
        ((A1 == 1'b1) && (B1 == 1'b1) && (A2 == 1'b1) && (A3 == 1'b1)) |-> (Y == 1'b1)
    );

endmodule

rtl:
module toggle_module #(
   parameter WIDTH = 1
)(
   input clk,
   input toggle,
   output reg [WIDTH-1:0] out
);


always @(posedge clk) begin
   if (toggle && !out) begin
      out <= 1;
   end else if (toggle && out) begin
      out <= 0;
   end
end

endmodule

sva:
module toggle_module_sva #(
    parameter WIDTH = 1
)(
    input logic clk,
    input logic toggle,
    input logic [WIDTH-1:0] out
);

    // When toggle is low, out holds its previous value.
    check_hold_when_no_toggle: assert property (
        @(posedge clk) !toggle |=> $stable(out)
    );

    // A toggle from zero drives out to 1 on the next cycle.
    check_toggle_from_zero_sets_one: assert property (
        @(posedge clk) (toggle && !out) |=> (out == {{(WIDTH-1){1'b0}}, 1'b1})
    );

    // A toggle from any non-zero value drives out to 0 on the next cycle.
    check_toggle_from_nonzero_clears_out: assert property (
        @(posedge clk) (toggle && out) |=> (out == '0)
    );

endmodule

rtl:
module multiplier_divider(
    input [3:0] in,
    output reg [3:0] out
);

always @(*) begin
    if (in <= 4) begin
        out = in * 2;
    end else begin
        out = in / 2;
    end
end

endmodule

sva:
module multiplier_divider_assertions (
    input logic [3:0] in,
    input logic [3:0] out
);

    // Inputs 0 through 4 take the multiply-by-two branch.
    check_multiply_branch: assert property (
        @($global_clock)
        (in <= 4'd4) |-> (out == (in << 1))
    );

    // Inputs above 4 take the divide-by-two branch.
    check_divide_branch: assert property (
        @($global_clock)
        (in > 4'd4) |-> (out == (in >> 1))
    );

    // Input 4 is included in the multiply-by-two condition.
    check_boundary_at_four: assert property (
        @($global_clock)
        (in == 4'd4) |-> (out == 4'd8)
    );

    // Input 5 is the first value that uses divide-by-two.
    check_boundary_at_five: assert property (
        @($global_clock)
        (in == 4'd5) |-> (out == 4'd2)
    );

endmodule

rtl:
module ring_counter (
    input Clk,
    output reg [3:0] Q
);

always @(posedge Clk) begin
    Q <= {Q[2:0], Q[3]};
end

endmodule

sva:
module ring_counter_sva (
    input logic       Clk,
    input logic [3:0] Q
);

    // Q rotates by one bit on each rising edge.
    check_rotate_vector: assert property (
        @(posedge Clk) 1'b1 |=> (Q == $past({Q[2:0], Q[3]}))
    );

    // Q[3] takes the previous value of Q[2].
    check_q3_from_prev_q2: assert property (
        @(posedge Clk) 1'b1 |=> (Q[3] == $past(Q[2]))
    );

    // Q[2] takes the previous value of Q[1].
    check_q2_from_prev_q1: assert property (
        @(posedge Clk) 1'b1 |=> (Q[2] == $past(Q[1]))
    );

    // Q[1] takes the previous value of Q[0].
    check_q1_from_prev_q0: assert property (
        @(posedge Clk) 1'b1 |=> (Q[1] == $past(Q[0]))
    );

    // Q[0] takes the previous value of Q[3].
    check_q0_from_prev_q3: assert property (
        @(posedge Clk) 1'b1 |=> (Q[0] == $past(Q[3]))
    );

    // Four rotations return Q to its earlier value.
    check_period_four: assert property (
        @(posedge Clk) 1'b1 |=> ##3 (Q == $past(Q, 4))
    );

endmodule

rtl:
module binary_adder(A, B, S, CO);
input A;
input B;
output S;
output CO;

wire w1, w2;
xor x1(w1, A, B);
and a1(w2, A, B);
xor x2(S, w1, CO);
and a2(CO, w2, w1);

endmodule

sva:
module binary_adder_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic S,
    input logic CO
);

    // Carry matches the implemented AND of A&B and A^B.
    check_carry_equation: assert property (
        @(posedge clk) CO == ((A & B) & (A ^ B))
    );

    // Sum matches the implemented XOR of A^B with CO.
    check_sum_equation: assert property (
        @(posedge clk) S == ((A ^ B) ^ CO)
    );

    // The implemented carry term is mutually exclusive and always low.
    check_carry_always_low: assert property (
        @(posedge clk) CO == 1'b0
    );

    // With carry low, the sum reduces to A XOR B.
    check_sum_reduces_to_xor: assert property (
        @(posedge clk) S == (A ^ B)
    );

endmodule

rtl:
module johnson_counter #(
  parameter m = 4 // number of output signals
)(
  input clk,
  output [m-1:0] out
);


reg [m-1:0] shift_reg;
assign out = shift_reg;

always @(posedge clk) begin
  shift_reg <= {shift_reg[m-2:0], shift_reg[m-1]};
end

endmodule

sva:
module johnson_counter_sva #(
    parameter int m = 4
) (
    input logic clk,
    input logic [m-1:0] out
);

generate
    if (m > 1) begin : gen_multi_bit
        // Output is a one-bit circular shift of its previous value.
        check_rotate_vector: assert property (
            @(posedge clk) !$initstate |-> (out == {$past(out[m-2:0]), $past(out[m-1])})
        );

        // The low bit comes from the previous high bit.
        check_wrap_bit: assert property (
            @(posedge clk) !$initstate |-> (out[0] == $past(out[m-1]))
        );

        // Upper bits come from the previous lower bits.
        check_shift_upper_bits: assert property (
            @(posedge clk) !$initstate |-> (out[m-1:1] == $past(out[m-2:0]))
        );
    end else begin : gen_single_bit
        // A 1-bit instance holds its value on each clock.
        check_single_bit_hold: assert property (
            @(posedge clk) !$initstate |-> (out == $past(out))
        );
    end
endgenerate

// Bit parity is preserved by the circular shift.
check_parity_preserved: assert property (
    @(posedge clk) !$initstate |-> ((^out) == (^($past(out))))
);

// The all-zero state remains all zero.
check_zero_state_stable: assert property (
    @(posedge clk) (!$initstate && ($past(out) == {m{1'b0}})) |-> (out == {m{1'b0}})
);

// The all-one state remains all one.
check_one_state_stable: assert property (
    @(posedge clk) (!$initstate && ($past(out) == {m{1'b1}})) |-> (out == {m{1'b1}})
);

endmodule

rtl:
module uart_sync_flops
(
  // internal signals
  rst_i,
  clk_i,
  stage1_rst_i,
  stage1_clk_en_i,
  async_dat_i,
  sync_dat_o
);

parameter width         = 1;
parameter init_value    = 1'b0;

input                           rst_i;                  // reset input
input                           clk_i;                  // clock input
input                           stage1_rst_i;           // synchronous reset for stage 1 FF
input                           stage1_clk_en_i;        // synchronous clock enable for stage 1 FF
input   [width-1:0]             async_dat_i;            // asynchronous data input
output  [width-1:0]             sync_dat_o;             // synchronous data output



reg     [width-1:0]             sync_dat_o;
reg     [width-1:0]             flop_0;


// first stage
always @ (posedge clk_i or posedge rst_i)
begin
    if (rst_i)
        flop_0 <= {width{init_value}};
    else
        flop_0 <= async_dat_i;    
end

// second stage
always @ (posedge clk_i or posedge rst_i)
begin
    if (rst_i)
        sync_dat_o <= {width{init_value}};
    else if (stage1_rst_i)
        sync_dat_o <= {width{init_value}};
    else if (stage1_clk_en_i)
        sync_dat_o <= flop_0;       
end

endmodule

sva:
module uart_sync_flops_sva #(
    parameter int width = 1,
    parameter bit init_value = 1'b0
) (
    input logic                 rst_i,
    input logic                 clk_i,
    input logic                 stage1_rst_i,
    input logic                 stage1_clk_en_i,
    input logic [width-1:0]     async_dat_i,
    input logic [width-1:0]     sync_dat_o,
    input logic [width-1:0]     flop_0
);

    // clk_i is the only clock; rst_i is an active-high asynchronous reset.
    // flop_0 is the internal first-stage synchronizer register.

    // After reset was active, the first stage is still at the init value.
    check_stage0_init_after_reset: assert property (
        @(posedge clk_i) disable iff (rst_i)
        $past(rst_i) |-> (flop_0 == {width{init_value}})
    );

    // After reset was active, the second stage is still at the init value.
    check_stage1_init_after_reset: assert property (
        @(posedge clk_i) disable iff (rst_i)
        $past(rst_i) |-> (sync_dat_o == {width{init_value}})
    );

    // The first stage samples async_dat_i on every non-reset clock.
    check_stage0_samples_async: assert property (
        @(posedge clk_i) disable iff (rst_i)
        1'b1 |=> (flop_0 == $past(async_dat_i))
    );

    // stage1_rst_i synchronously clears the second stage.
    check_stage1_sync_reset: assert property (
        @(posedge clk_i) disable iff (rst_i)
        stage1_rst_i |=> (sync_dat_o == {width{init_value}})
    );

    // With stage1 reset inactive and clock enable low, the second stage holds.
    check_stage1_hold_when_disabled: assert property (
        @(posedge clk_i) disable iff (rst_i)
        (!stage1_rst_i && !stage1_clk_en_i) |=> (sync_dat_o == $past(sync_dat_o))
    );

    // With stage1 reset inactive and clock enable high, the second stage captures flop_0.
    check_stage1_captures_stage0: assert property (
        @(posedge clk_i) disable iff (rst_i)
        (!stage1_rst_i && stage1_clk_en_i) |=> (sync_dat_o == $past(flop_0))
    );

    // stage1_rst_i has priority over stage1_clk_en_i in the second stage.
    check_stage1_reset_priority_over_enable: assert property (
        @(posedge clk_i) disable iff (rst_i)
        (stage1_rst_i && stage1_clk_en_i) |=> (sync_dat_o == {width{init_value}})
    );

endmodule

rtl:
module clock_divider (
  input clk_in,
  input reset,
  output reg clk_out
);

parameter divide_by = 2;

reg [31:0] counter;

always @(posedge clk_in or posedge reset) begin
  if (reset) begin
    clk_out <= 1'b0;
    counter <= 0;
  end
  else begin
    if (counter == divide_by - 1) begin
      clk_out <= ~clk_out;
      counter <= 0;
    end
    else begin
      counter <= counter + 1;
    end
  end
end

endmodule

sva:
module clock_divider_sva #(
    parameter integer divide_by = 2
) (
    input logic        clk_in,
    input logic        reset,
    input logic        clk_out,
    input logic [31:0] counter
);

    // Reset clears the counter by the next sampled clock.
    check_reset_clears_counter: assert property (
        @(posedge clk_in) reset |=> (counter == 32'd0)
    );

    // Reset drives clk_out low by the next sampled clock.
    check_reset_clears_clk_out: assert property (
        @(posedge clk_in) reset |=> (clk_out == 1'b0)
    );

    // Terminal count resets the counter on the following clock.
    check_terminal_count_resets_counter: assert property (
        @(posedge clk_in) disable iff (reset)
        (counter == divide_by - 1) |=> (counter == 32'd0)
    );

    // Terminal count toggles clk_out on the following clock.
    check_terminal_count_toggles_clk_out: assert property (
        @(posedge clk_in) disable iff (reset)
        (counter == divide_by - 1) |=> (clk_out == ~$past(clk_out))
    );

    // Non-terminal count increments the counter by one.
    check_nonterminal_count_increments_counter: assert property (
        @(posedge clk_in) disable iff (reset)
        (counter != divide_by - 1) |=> (counter == ($past(counter) + 32'd1))
    );

    // Non-terminal count holds clk_out steady.
    check_nonterminal_count_holds_clk_out: assert property (
        @(posedge clk_in) disable iff (reset)
        (counter != divide_by - 1) |=> (clk_out == $past(clk_out))
    );

endmodule

rtl:
module DEMUX (
  input in,
  output out0,
  output out1,
  output out2,
  output out3
);

  wire d0, d1, d2, d3;
  wire a0, a1, a2, a3;

  // 2-to-4 decoder
  decoder_2to4 decoder (
    .in(in),
    .out0(d0),
    .out1(d1),
    .out2(d2),
    .out3(d3)
  );

  // AND gates
  assign a0 = d0 & ~d1 & ~d2 & ~d3;
  assign a1 = ~d0 & d1 & ~d2 & ~d3;
  assign a2 = ~d0 & ~d1 & d2 & ~d3;
  assign a3 = ~d0 & ~d1 & ~d2 & d3;

  // Output signals
  assign out0 = a0;
  assign out1 = a1;
  assign out2 = a2;
  assign out3 = a3;

endmodule

// 2-to-4 decoder module
module decoder_2to4 (
  input in,
  output out0,
  output out1,
  output out2,
  output out3
);

  assign out0 = ~in & ~in;
  assign out1 = ~in & in;
  assign out2 = in & ~in;
  assign out3 = in & in;

endmodule

sva:
module DEMUX_sva (
    input logic clk,
    input logic in,
    input logic out0,
    input logic out1,
    input logic out2,
    input logic out3
);

    // out0 is driven as the inverse of the input.
    check_out0_inverse_of_in: assert property (
        @(posedge clk) out0 == ~in
    );

    // out3 directly follows the input.
    check_out3_matches_in: assert property (
        @(posedge clk) out3 == in
    );

    // out1 is always low.
    check_out1_constant_low: assert property (
        @(posedge clk) out1 == 1'b0
    );

    // out2 is always low.
    check_out2_constant_low: assert property (
        @(posedge clk) out2 == 1'b0
    );

    // Exactly one output is high on every sampled cycle.
    check_outputs_onehot: assert property (
        @(posedge clk) $onehot({out0, out1, out2, out3})
    );

    // A low input selects only out0.
    check_input_low_selects_out0: assert property (
        @(posedge clk) (in == 1'b0) |-> (out0 && !out1 && !out2 && !out3)
    );

    // A high input selects only out3.
    check_input_high_selects_out3: assert property (
        @(posedge clk) (in == 1'b1) |-> (!out0 && !out1 && !out2 && out3)
    );

endmodule

rtl:
module mux_6to1 (
    input [2:0] sel,
    input [3:0] data0,
    input [3:0] data1,
    input [3:0] data2,
    input [3:0] data3,
    output [3:0] out
);

reg [3:0] out_reg;

always @(*) begin
    case (sel)
        3'b000: out_reg = data0;
        3'b001: out_reg = data1;
        3'b010: out_reg = data2;
        3'b011: out_reg = data3;
        default: out_reg = 4'b0000;
    endcase
end

assign out = out_reg;

endmodule
module priority_encoder_min (
    input [7:0] a,
    input [7:0] b,
    input [7:0] c,
    input [7:0] d,
    output [1:0] out
);

wire [3:0] min_index;

assign min_index = (a <= b && a <= c && a <= d) ? 2'b00 :
                  (b <= c && b <= d) ? 2'b01 :
                  (c <= d) ? 2'b10 : 2'b11;

assign out = min_index;

endmodule
module top_module (
    input [2:0] sel,
    input [3:0] data0,
    input [3:0] data1,
    input [3:0] data2,
    input [3:0] data3,
    input [7:0] a,
    input [7:0] b,
    input [7:0] c,
    input [7:0] d,
    output [7:0] sum
);

wire [3:0] mux_out;
wire [1:0] min_index;

mux_6to1 mux_inst (
    .sel(sel),
    .data0(data0),
    .data1(data1),
    .data2(data2),
    .data3(data3),
    .out(mux_out)
);

priority_encoder_min priority_inst (
    .a(a),
    .b(b),
    .c(c),
    .d(d),
    .out(min_index)
);

assign sum = mux_out + min_index;

endmodule

sva:
module top_module_sva (
    input logic        clk,
    input logic [2:0]  sel,
    input logic [3:0]  data0,
    input logic [3:0]  data1,
    input logic [3:0]  data2,
    input logic [3:0]  data3,
    input logic [7:0]  a,
    input logic [7:0]  b,
    input logic [7:0]  c,
    input logic [7:0]  d,
    input logic [7:0]  sum
);

    function automatic [3:0] exp_mux_out (
        input logic [2:0] sel_f,
        input logic [3:0] data0_f,
        input logic [3:0] data1_f,
        input logic [3:0] data2_f,
        input logic [3:0] data3_f
    );
    begin
        case (sel_f)
            3'b000: exp_mux_out = data0_f;
            3'b001: exp_mux_out = data1_f;
            3'b010: exp_mux_out = data2_f;
            3'b011: exp_mux_out = data3_f;
            default: exp_mux_out = 4'b0000;
        endcase
    end
    endfunction

    function automatic [1:0] exp_min_index (
        input logic [7:0] a_f,
        input logic [7:0] b_f,
        input logic [7:0] c_f,
        input logic [7:0] d_f
    );
    begin
        if ((a_f <= b_f) && (a_f <= c_f) && (a_f <= d_f))
            exp_min_index = 2'b00;
        else if ((b_f <= c_f) && (b_f <= d_f))
            exp_min_index = 2'b01;
        else if (c_f <= d_f)
            exp_min_index = 2'b10;
        else
            exp_min_index = 2'b11;
    end
    endfunction

    function automatic [7:0] exp_sum_from_parts (
        input logic [3:0] mux_f,
        input logic [1:0] min_f
    );
        logic [3:0] add_f;
    begin
        add_f = mux_f + min_f;
        exp_sum_from_parts = {4'b0000, add_f};
    end
    endfunction

    function automatic [7:0] exp_sum (
        input logic [2:0] sel_f,
        input logic [3:0] data0_f,
        input logic [3:0] data1_f,
        input logic [3:0] data2_f,
        input logic [3:0] data3_f,
        input logic [7:0] a_f,
        input logic [7:0] b_f,
        input logic [7:0] c_f,
        input logic [7:0] d_f
    );
        logic [3:0] mux_f;
        logic [1:0] min_f;
    begin
        mux_f   = exp_mux_out(sel_f, data0_f, data1_f, data2_f, data3_f);
        min_f   = exp_min_index(a_f, b_f, c_f, d_f);
        exp_sum = exp_sum_from_parts(mux_f, min_f);
    end
    endfunction

    // Sum matches the implemented mux-plus-min-index function.
    check_sum_matches_combined_logic: assert property (
        @(posedge clk) sum == exp_sum(sel, data0, data1, data2, data3, a, b, c, d)
    );

    // The upper nibble of sum is always zero because the addition is 4 bits wide.
    check_sum_upper_bits_zero: assert property (
        @(posedge clk) sum[7:4] == 4'b0000
    );

    // sel 000 selects data0 into the adder.
    check_sel_000_uses_data0: assert property (
        @(posedge clk) (sel == 3'b000) |-> (sum == exp_sum_from_parts(data0, exp_min_index(a, b, c, d)))
    );

    // sel 001 selects data1 into the adder.
    check_sel_001_uses_data1: assert property (
        @(posedge clk) (sel == 3'b001) |-> (sum == exp_sum_from_parts(data1, exp_min_index(a, b, c, d)))
    );

    // sel 010 selects data2 into the adder.
    check_sel_010_uses_data2: assert property (
        @(posedge clk) (sel == 3'b010) |-> (sum == exp_sum_from_parts(data2, exp_min_index(a, b, c, d)))
    );

    // sel 011 selects data3 into the adder.
    check_sel_011_uses_data3: assert property (
        @(posedge clk) (sel == 3'b011) |-> (sum == exp_sum_from_parts(data3, exp_min_index(a, b, c, d)))
    );

    // sel values 100 through 111 force the mux contribution to zero.
    check_sel_default_zeros_mux: assert property (
        @(posedge clk) sel[2] |-> (sum == exp_sum_from_parts(4'b0000, exp_min_index(a, b, c, d)))
    );

    // When a is minimal or tied for minimal, the encoded index is 0.
    check_a_priority_when_a_is_min: assert property (
        @(posedge clk) ((a <= b) && (a <= c) && (a <= d)) |-> (sum == exp_sum_from_parts(exp_mux_out(sel, data0, data1, data2, data3), 2'b00))
    );

    // When a is not minimal and b is minimal or tied, the encoded index is 1.
    check_b_priority_when_b_is_min: assert property (
        @(posedge clk) (!((a <= b) && (a <= c) && (a <= d)) && ((b <= c) && (b <= d))) |-> (sum == exp_sum_from_parts(exp_mux_out(sel, data0, data1, data2, data3), 2'b01))
    );

    // When a and b are not minimal and c is less than or equal to d, the encoded index is 2.
    check_c_priority_when_c_is_min: assert property (
        @(posedge clk) (!((a <= b) && (a <= c) && (a <= d)) && !((b <= c) && (b <= d)) && (c <= d)) |-> (sum == exp_sum_from_parts(exp_mux_out(sel, data0, data1, data2, data3), 2'b10))
    );

    // When d is the remaining minimum case, the encoded index is 3.
    check_d_selected_when_only_d_is_min: assert property (
        @(posedge clk) (!((a <= b) && (a <= c) && (a <= d)) && !((b <= c) && (b <= d)) && !(c <= d)) |-> (sum == exp_sum_from_parts(exp_mux_out(sel, data0, data1, data2, data3), 2'b11))
    );

endmodule

