module top_module(
    input [3:0] data,
    input in,
    output reg out
);

    wire [5:0] mux_input;
    wire not_in;

    not_gate not_gate_inst(
        .in(in),
        .out(not_in)
    );

    mux_6to1 mux_inst(
        .data_in(mux_input),
        .sel({2'b0, not_in}),
        .out(out)
    );

    assign mux_input = {2'b0, data};

endmodule
module mux_6to1(
    input [5:0] data_in,
    input [2:0] sel,
    output reg out
);

    always @(*) begin
        case(sel)
            3'b000: out = data_in[0];
            3'b001: out = data_in[1];
            3'b010: out = data_in[2];
            3'b011: out = data_in[3];
            3'b100: out = data_in[4];
            3'b101: out = data_in[5];
            default: out = 1'b0;
        endcase
    end

endmodule
module not_gate(
    input in,
    output reg out
);

    always @(in) begin
        out = ~in;
    end

endmodule

sva:
module top_module_sva(
    input logic [3:0] data,
    input logic       in,
    input logic       out
);

    // Out implements the top-level combinational function.
    check_out_matches_function: assert property (
        @($global_clock) (out == (in ? data[0] : data[1]))
    );

    // High in selects data[0] through the inverted mux select.
    check_select_data0_when_in_high: assert property (
        @($global_clock) in |-> (out == data[0])
    );

    // Low in selects data[1] through the inverted mux select.
    check_select_data1_when_in_low: assert property (
        @($global_clock) !in |-> (out == data[1])
    );

    // Matching selectable inputs must propagate regardless of in.
    check_equal_lower_bits_propagate: assert property (
        @($global_clock) (data[0] == data[1]) |-> (out == data[0])
    );

    // Out stays stable when in and the two selectable data bits stay stable.
    check_out_stable_when_relevant_inputs_stable: assert property (
        @($global_clock) disable iff ($initstate)
        ($stable(in) && $stable(data[1:0])) |-> $stable(out)
    );

endmodule

rtl:
module four_bit_adder(
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] S,
    output Cout
);

    wire [3:0] sum;
    wire [3:0] carry;

    assign sum[0] = A[0] ^ B[0] ^ Cin;
    assign carry[0] = (A[0] & B[0]) | (Cin & (A[0] ^ B[0]));

    assign sum[1] = A[1] ^ B[1] ^ carry[0];
    assign carry[1] = (A[1] & B[1]) | (carry[0] & (A[1] ^ B[1]));

    assign sum[2] = A[2] ^ B[2] ^ carry[1];
    assign carry[2] = (A[2] & B[2]) | (carry[1] & (A[2] ^ B[2]));

    assign sum[3] = A[3] ^ B[3] ^ carry[2];
    assign Cout = (A[3] & B[3]) | (carry[2] & (A[3] ^ B[3]));
    assign S = sum;

endmodule

sva:
module four_bit_adder_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic Cin,
    input logic [3:0] S,
    input logic Cout
);

    // The concatenated carry and sum match the 5-bit arithmetic result.
    check_full_result_matches_addition: assert property (
        @($global_clock)
        {Cout, S} == ({1'b0, A} + {1'b0, B} + {4'b0000, Cin})
    );

    // Bit 0 sum implements a full-adder sum with Cin.
    check_sum_bit0_equation: assert property (
        @($global_clock)
        S[0] == (A[0] ^ B[0] ^ Cin)
    );

    // Bit 1 sum uses the ripple carry generated from bit 0.
    check_sum_bit1_equation: assert property (
        @($global_clock)
        S[1] == (A[1] ^ B[1] ^ ((A[0] & B[0]) | (Cin & (A[0] ^ B[0]))))
    );

    // Bit 2 sum uses the ripple carry generated from bits 0 and 1.
    check_sum_bit2_equation: assert property (
        @($global_clock)
        S[2] == (A[2] ^ B[2] ^
                 ((A[1] & B[1]) |
                  (((A[0] & B[0]) | (Cin & (A[0] ^ B[0]))) & (A[1] ^ B[1]))))
    );

    // Bit 3 sum uses the ripple carry generated from bits 0 through 2.
    check_sum_bit3_equation: assert property (
        @($global_clock)
        S[3] == (A[3] ^ B[3] ^
                 ((A[2] & B[2]) |
                  (((A[1] & B[1]) |
                    (((A[0] & B[0]) | (Cin & (A[0] ^ B[0]))) & (A[1] ^ B[1]))) &
                   (A[2] ^ B[2]))))
    );

    // Cout implements the final ripple-carry equation from the MSB stage.
    check_cout_equation: assert property (
        @($global_clock)
        Cout == ((A[3] & B[3]) |
                 (((A[2] & B[2]) |
                   (((A[1] & B[1]) |
                     (((A[0] & B[0]) | (Cin & (A[0] ^ B[0]))) & (A[1] ^ B[1]))) &
                    (A[2] ^ B[2]))) &
                  (A[3] ^ B[3])))
    );

endmodule

