sva:
module cycle_counter_sva (
    input logic [2:0] cycle,
    input logic       clk,
    input logic       enn
);

    // Clock: clk. No reset is present in the RTL.
    // Mixed logic: registered modulo-8 counter with combinational output cycle.

    // enn high synchronously clears the counter to zero.
    check_clear_on_enn: assert property (
        @(posedge clk) enn |=> cycle == 3'b000
    );

    // With enn low and no rollover, the counter increments by one.
    check_increment_when_enn_low: assert property (
        @(posedge clk) (!enn && cycle != 3'b111) |=> cycle == ($past(cycle) + 3'b001)
    );

    // With enn low at the maximum value, the counter wraps to zero.
    check_wrap_from_max: assert property (
        @(posedge clk) (!enn && cycle == 3'b111) |=> cycle == 3'b000
    );

    // Eight consecutive count cycles return to the starting value.
    check_full_modulo_cycle: assert property (
        @(posedge clk) (!enn)[*8] |=> cycle == $past(cycle, 8)
    );

    // A clear followed by one count cycle produces a value of one.
    check_clear_then_count: assert property (
        @(posedge clk) enn ##1 !enn |=> cycle == 3'b001
    );

endmodule

rtl:
module alu8b (input wire [7:0] A_in,
              input wire [7:0] B_in,
              input wire       C_in,
              input wire [2:0] Opcode_in,
              output wire [7:0] Result_out,
              output wire       C_out);

  reg [7:0] reg_result;
  reg reg_cout;
  wire [7:0] temp_sum;
  wire temp_cout;

  assign Result_out = reg_result;
  assign C_out = reg_cout;

  assign {temp_cout, temp_sum} = A_in + B_in + C_in;

  always @ ( * ) begin
  reg_cout = 1'b0;  case (Opcode_in)
      3'b000: begin
                reg_cout = temp_cout;
                reg_result = temp_sum;
              end
      3'b001: reg_result =  A_in - B_in;
      3'b010: reg_result = A_in & B_in;
      3'b011: reg_result = A_in | B_in;
      3'b100: reg_result = A_in % B_in;
      default:
              reg_result = 8'b0;
    endcase
  end
endmodule

sva:
module alu8b_sva (
    input logic [7:0] A_in,
    input logic [7:0] B_in,
    input logic       C_in,
    input logic [2:0] Opcode_in,
    input logic [7:0] Result_out,
    input logic       C_out
);

    // Add opcode returns the 9-bit sum across carry and result.
    check_add_operation: assert property (
        @($global_clock)
        (Opcode_in == 3'b000) |-> ({C_out, Result_out} == ({1'b0, A_in} + {1'b0, B_in} + {{8{1'b0}}, C_in}))
    );

    // Subtract opcode returns A minus B in the result.
    check_sub_operation: assert property (
        @($global_clock)
        (Opcode_in == 3'b001) |-> (Result_out == (A_in - B_in))
    );

    // AND opcode returns the bitwise AND of the inputs.
    check_and_operation: assert property (
        @($global_clock)
        (Opcode_in == 3'b010) |-> (Result_out == (A_in & B_in))
    );

    // OR opcode returns the bitwise OR of the inputs.
    check_or_operation: assert property (
        @($global_clock)
        (Opcode_in == 3'b011) |-> (Result_out == (A_in | B_in))
    );

    // Modulo opcode returns A modulo B when the divisor is nonzero.
    check_mod_operation: assert property (
        @($global_clock)
        ((Opcode_in == 3'b100) && (B_in != 8'b0)) |-> (Result_out == (A_in % B_in))
    );

    // Unimplemented opcodes drive a zero result and zero carry.
    check_default_zero_outputs: assert property (
        @($global_clock)
        ((Opcode_in == 3'b101) || (Opcode_in == 3'b110) || (Opcode_in == 3'b111)) |-> ((Result_out == 8'b0) && (C_out == 1'b0))
    );

    // All non-add operations force the carry output low.
    check_non_add_carry_zero: assert property (
        @($global_clock)
        (Opcode_in != 3'b000) |-> (C_out == 1'b0)
    );

endmodule

module top_module_sva (
    input logic        clk,
    input logic [31:0] a,
    input logic [31:0] b,
    input logic        select,
    input logic [7:0]  out,
    input logic [31:0] sum,
    input logic [7:0]  upper_byte,
    input logic [7:0]  lower_byte,
    input logic [7:0]  product,
    input logic [15:0] sum_low,
    input logic [15:0] sum_high,
    input logic        carry_out_low,
    input logic        carry_out_high
);

    // Lower ripple adder output matches a[15:0] + b[15:0].
    check_ripple_low_add: assert property (
        @(posedge clk) ({carry_out_low, sum_low} == (a[15:0] + b[15:0]))
    );

    // Upper ripple adder output matches a[31:16] + b[31:16].
    check_ripple_high_add: assert property (
        @(posedge clk) ({carry_out_high, sum_high} == (a[31:16] + b[31:16]))
    );

    // Lower half of sum follows the carry-select lower assignment.
    check_carry_select_lower_half: assert property (
        @(posedge clk) (sum[15:0] == (carry_out_low ? sum_high : sum_low))
    );

    // Upper half of sum follows the carry-select upper assignment.
    check_carry_select_upper_half: assert property (
        @(posedge clk) (sum[31:16] == (carry_out_high ? (sum_high + 16'd1) : sum_high))
    );

    // upper_byte is sum[15:8].
    check_decoder_upper_byte: assert property (
        @(posedge clk) (upper_byte == sum[15:8])
    );

    // lower_byte is sum[7:0].
    check_decoder_lower_byte: assert property (
        @(posedge clk) (lower_byte == sum[7:0])
    );

    // product is the low 8 bits of upper_byte * lower_byte.
    check_functional_product: assert property (
        @(posedge clk) ({8'h00, product} == ((upper_byte * lower_byte) & 16'h00ff))
    );

    // When select is high, out follows product.
    check_output_select_product: assert property (
        @(posedge clk) select |-> (out == product)
    );

    // When select is low, the 16-bit decoder path truncates to lower_byte.
    check_output_select_decoder_low_byte: assert property (
        @(posedge clk) !select |-> (out == lower_byte)
    );

    // out matches the implemented 8-bit mux behavior.
    check_output_mux_behavior: assert property (
        @(posedge clk) (out == (select ? product : lower_byte))
    );

endmodule

rtl:
module digital_clock(
    input clk,
    input reset,
    output [5:0] sec,
    output [5:0] min,
    output [4:0] hr,
    output ampm
);

    // Counters for seconds, minutes, and hours
    reg [5:0] sec_count = 6'b0;
    reg [5:0] min_count = 6'b0;
    reg [4:0] hr_count = 5'b0;

    // Flag to toggle AM/PM
    reg toggle_ampm = 1'b0;

    // Synchronous reset
    always @(posedge clk) begin
        if (reset) begin
            sec_count <= 6'b0;
            min_count <= 6'b0;
            hr_count <= 5'b0;
            toggle_ampm <= 1'b0;
        end else begin
            // Increment second counter every second
            if (sec_count == 6'd49) begin
                sec_count <= 6'b0;
                // Increment minute counter every minute
                if (min_count == 6'd59) begin
                    min_count <= 6'b0;
                    // Increment hour counter every hour
                    if (hr_count == 5'd11 && toggle_ampm == 1'b0) begin
                        hr_count <= 5'b0;
                        toggle_ampm <= 1'b1;
                    end else if (hr_count == 5'd11 && toggle_ampm == 1'b1) begin
                        hr_count <= 5'b0;
                        toggle_ampm <= 1'b0;
                    end else begin
                        hr_count <= hr_count + 5'b1;
                    end
                end else begin
                    min_count <= min_count + 6'b1;
                end
            end else begin
                sec_count <= sec_count + 6'b1;
            end
        end
    end

    // Output values
    assign sec = sec_count;
    assign min = min_count;
    assign ampm = toggle_ampm;
    assign hr = (hr_count == 5'b0) ? 5'd12 :
                (hr_count < 5'd10) ? {4'b0, hr_count} :
                (hr_count < 5'd12) ? hr_count :
                (hr_count == 5'd12) ? 5'b0 :
                (hr_count < 5'd22) ? {4'b0, hr_count - 5'd12} : hr_count - 5'd12;

endmodule

sva:
module digital_clock_sva (
    input logic       clk,
    input logic       reset,
    input logic [5:0] sec,
    input logic [5:0] min,
    input logic [4:0] hr,
    input logic       ampm
);

    // Reset drives the observable clock state to 00:00:12 AM by the next sampled cycle.
    check_reset_state: assert property (
        @(posedge clk) reset |=> (sec == 6'd0 && min == 6'd0 && hr == 5'd12 && ampm == 1'b0)
    );

    // Seconds stay within the implemented 0 to 49 range.
    check_sec_range: assert property (
        @(posedge clk) disable iff (reset) sec <= 6'd49
    );

    // Minutes stay within the implemented 0 to 59 range.
    check_min_range: assert property (
        @(posedge clk) disable iff (reset) min <= 6'd59
    );

    // Hours are always presented as 1 through 12.
    check_hr_range: assert property (
        @(posedge clk) disable iff (reset) (hr >= 5'd1) && (hr <= 5'd12)
    );

    // When seconds have not wrapped, only seconds increment.
    check_second_increment: assert property (
        @(posedge clk) disable iff (reset)
        (sec < 6'd49) |=> (sec == ($past(sec) + 6'd1) &&
                           min == $past(min) &&
                           hr == $past(hr) &&
                           ampm == $past(ampm))
    );

    // At second wrap, minutes increment and hours/AMPM hold when minutes have not wrapped.
    check_minute_increment: assert property (
        @(posedge clk) disable iff (reset)
        (sec == 6'd49 && min < 6'd59) |=> (sec == 6'd0 &&
                                           min == ($past(min) + 6'd1) &&
                                           hr == $past(hr) &&
                                           ampm == $past(ampm))
    );

    // At 12:59:49, the next hour becomes 1 and AM/PM does not change.
    check_hour_increment_from_12: assert property (
        @(posedge clk) disable iff (reset)
        (sec == 6'd49 && min == 6'd59 && hr == 5'd12) |=> (sec == 6'd0 &&
                                                            min == 6'd0 &&
                                                            hr == 5'd1 &&
                                                            ampm == $past(ampm))
    );

    // At 1 through 10 with full rollover, the hour increments by one and AM/PM holds.
    check_hour_increment_midrange: assert property (
        @(posedge clk) disable iff (reset)
        (sec == 6'd49 && min == 6'd59 && hr >= 5'd1 && hr <= 5'd10) |=> (sec == 6'd0 &&
                                                                           min == 6'd0 &&
                                                                           hr == ($past(hr) + 5'd1) &&
                                                                           ampm == $past(ampm))
    );

    // At 11:59:49, the next hour becomes 12 and AM/PM toggles.
    check_hour_rollover_toggles_ampm: assert property (
        @(posedge clk) disable iff (reset)
        (sec == 6'd49 && min == 6'd59 && hr == 5'd11) |=> (sec == 6'd0 &&
                                                            min == 6'd0 &&
                                                            hr == 5'd12 &&
                                                            ampm == !$past(ampm))
    );

endmodule

