    );

    // D=A must decode to the active-low seven-segment pattern for A.
    check_decode_a: assert property (
        @(posedge clk) (D == 4'hA) |-> (S == 7'b0001000)
    );

    // D=B must decode to the active-low seven-segment pattern for B.
