rtl:
module decoder_3to8 (
    input [2:0] in,
    input ena,
    output reg [7:0] out
);

always @ (in or ena) begin
    if (ena == 0) begin
        out <= 8'b0;
    end else begin
        case (in)
            3'b000: out <= 8'b00000001;
            3'b001: out <= 8'b00000010;
            3'b010: out <= 8'b00000100;
            3'b011: out <= 8'b00001000;
            3'b100: out <= 8'b00010000;
            3'b101: out <= 8'b00100000;
            3'b110: out <= 8'b01000000;
            3'b111: out <= 8'b10000000;
            default: out <= 8'b0;
        endcase
    end
end

endmodule

sva:
module decoder_3to8_sva (
    input logic [2:0] in,
    input logic       ena,
    input logic [7:0] out
);

    // Output is all zeros when the decoder is disabled.
    check_disabled_clears_out: assert property (
        @($global_clock) (ena == 1'b0) |-> (out == 8'b00000000)
    );

    // Input 000 decodes to bit 0 when enabled.
    check_decode_000: assert property (
        @($global_clock) ((ena == 1'b1) && (in == 3'b000)) |-> (out == 8'b00000001)
    );

    // Input 001 decodes to bit 1 when enabled.
    check_decode_001: assert property (
        @($global_clock) ((ena == 1'b1) && (in == 3'b001)) |-> (out == 8'b00000010)
    );

    // Input 010 decodes to bit 2 when enabled.
    check_decode_010: assert property (
        @($global_clock) ((ena == 1'b1) && (in == 3'b010)) |-> (out == 8'b00000100)
    );

    // Input 011 decodes to bit 3 when enabled.
    check_decode_011: assert property (
        @($global_clock) ((ena == 1'b1) && (in == 3'b011)) |-> (out == 8'b00001000)
    );

    // Input 100 decodes to bit 4 when enabled.
    check_decode_100: assert property (
        @($global_clock) ((ena == 1'b1) && (in == 3'b100)) |-> (out == 8'b00010000)
    );

    // Input 101 decodes to bit 5 when enabled.
    check_decode_101: assert property (
        @($global_clock) ((ena == 1'b1) && (in == 3'b101)) |-> (out == 8'b00100000)
    );

    // Input 110 decodes to bit 6 when enabled.
    check_decode_110: assert property (
        @($global_clock) ((ena == 1'b1) && (in == 3'b110)) |-> (out == 8'b01000000)
    );

    // Input 111 decodes to bit 7 when enabled.
    check_decode_111: assert property (
        @($global_clock) ((ena == 1'b1) && (in == 3'b111)) |-> (out == 8'b10000000)
    );

endmodule

rtl:
module d_flip_flop_with_en_and_reset(input D, C, E, R, output Q);
reg Q;

always @(posedge C) begin
    if (R) begin
        Q <= 1'b0;
    end
    else if (E) begin
        Q <= D;
    end
end

endmodule

sva:
module d_flip_flop_with_en_and_reset_assertions (
    input logic D,
    input logic C,
    input logic E,
    input logic R,
    input logic Q
);

    // Reset clears Q on the clock edge.
    check_reset_clears_q: assert property (
        @(posedge C) R |=> (Q == 1'b0)
    );

    // When enabled outside reset, Q captures D on the clock edge.
    check_enable_captures_d: assert property (
        @(posedge C) disable iff (R) E |=> (Q == $past(D))
    );

    // When disabled outside reset, Q holds its previous value.
    check_disable_holds_q: assert property (
        @(posedge C) disable iff (R) !E |=> (Q == $past(Q))
    );

endmodule

rtl:
module ones_complement (
    input [3:0] binary,
    output reg [3:0] ones_comp
);

    always @ (binary) begin
        ones_comp <= ~binary;
    end

endmodule

sva:
module ones_complement_sva (
    input logic clk,
    input logic [3:0] binary,
    input logic [3:0] ones_comp
);

    // Output is always the bitwise inverse of the input.
    check_output_matches_inverse: assert property (
        @(posedge clk) ones_comp == ~binary
    );

    // Output bit 0 is the inverse of input bit 0.
    check_bit0_inverse: assert property (
        @(posedge clk) ones_comp[0] == ~(binary[0])
    );

    // Output bit 1 is the inverse of input bit 1.
    check_bit1_inverse: assert property (
        @(posedge clk) ones_comp[1] == ~(binary[1])
    );

    // Output bit 2 is the inverse of input bit 2.
    check_bit2_inverse: assert property (
        @(posedge clk) ones_comp[2] == ~(binary[2])
    );

    // Output bit 3 is the inverse of input bit 3.
    check_bit3_inverse: assert property (
        @(posedge clk) ones_comp[3] == ~(binary[3])
    );

endmodule

module mux_2to1_controlled_sva (
    input logic clk,
    input logic a,
    input logic b,
    input logic c,
    input logic d,
    input logic sel_a,
    input logic sel_b1,
    input logic sel_b2,
    input logic out_mux
);

    // sel_a has highest priority and selects a.
    check_sel_a_priority: assert property (
        @(posedge clk) sel_a |-> (out_mux == a)
    );

    // When sel_a is low and both sel_b controls are low, b is selected.
    check_select_b_when_sel_b_low: assert property (
        @(posedge clk) (!sel_a && !sel_b1 && !sel_b2) |-> (out_mux == b)
    );

    // When sel_a is low and both sel_b controls are high, c is selected.
    check_select_c_when_sel_b_high: assert property (
        @(posedge clk) (!sel_a && sel_b1 && sel_b2) |-> (out_mux == c)
    );

    // When sel_a is low and the sel_b controls differ, d is selected.
    check_select_d_when_sel_b_mixed: assert property (
        @(posedge clk) (!sel_a && ((sel_b1 && !sel_b2) || (!sel_b1 && sel_b2))) |-> (out_mux == d)
    );

endmodule

rtl:
module logic_circuit(
    input a,
    input b,
    input c,
    output x,
    output y,
    output z
    );

    assign x = a;
    assign y = (a == 1'b0 && b == 1'b1);
    assign z = (a == 1'b0 && b == 1'b0 && c == 1'b1);

endmodule

sva:
module logic_circuit_sva(
    input logic a,
    input logic b,
    input logic c,
    input logic x,
    input logic y,
    input logic z
);

    // x directly mirrors a.
    check_x_matches_a: assert property (
        @($global_clock) (x == a)
    );

    // y matches the a==0 and b==1 decode.
    check_y_decode: assert property (
        @($global_clock) (y == ((a == 1'b0) && (b == 1'b1)))
    );

    // z matches the a==0, b==0, c==1 decode.
    check_z_decode: assert property (
        @($global_clock) (z == ((a == 1'b0) && (b == 1'b0) && (c == 1'b1)))
    );

    // When a is high, only x can be high.
    check_a_high_forces_x_only: assert property (
        @($global_clock) (a == 1'b1) |-> ((x == 1'b1) && (y == 1'b0) && (z == 1'b0))
    );

    // y high implies the y decode state and excludes the other outputs.
    check_y_high_state: assert property (
        @($global_clock) (y == 1'b1) |-> ((a == 1'b0) && (b == 1'b1) && (x == 1'b0) && (z == 1'b0))
    );

    // z high implies the z decode state and excludes the other outputs.
    check_z_high_state: assert property (
        @($global_clock) (z == 1'b1) |-> ((a == 1'b0) && (b == 1'b0) && (c == 1'b1) && (x == 1'b0) && (y == 1'b0))
    );

    // y and z are mutually exclusive decodes.
    check_y_z_mutex: assert property (
        @($global_clock) !((y == 1'b1) && (z == 1'b1))
    );

endmodule

rtl:
module bit_shift (
  input [31:0] in,
  input [4:0] shift_amount,
  input [1:0] shift_type,
  output reg [31:0] out
);

always @(*) begin
  case (shift_type)
    2'b00: out = in << shift_amount;
    2'b01: out = in >> shift_amount;
    2'b10: out = $signed(in) >>> shift_amount;
    default: out = in;
  endcase
end

endmodule

sva:
module bit_shift_sva (
    input logic clk,
    input logic [31:0] in,
    input logic [4:0] shift_amount,
    input logic [1:0] shift_type,
    input logic [31:0] out
);

    // Left-shift mode matches in shifted left by shift_amount.
    check_logical_left_shift: assert property (
        @(posedge clk)
        (shift_type == 2'b00) |-> (out == (in << shift_amount))
    );

    // Right-shift mode matches in shifted right by shift_amount.
    check_logical_right_shift: assert property (
        @(posedge clk)
        (shift_type == 2'b01) |-> (out == (in >> shift_amount))
    );

    // Arithmetic right-shift mode matches signed in shifted right by shift_amount.
    check_arithmetic_right_shift: assert property (
        @(posedge clk)
        (shift_type == 2'b10) |-> (out == ($signed(in) >>> shift_amount))
    );

    // Default mode passes the input through unchanged.
    check_default_passthrough: assert property (
        @(posedge clk)
        (shift_type == 2'b11) |-> (out == in)
    );

    // A zero shift amount leaves the output equal to the input.
    check_zero_shift_passthrough: assert property (
        @(posedge clk)
        (shift_amount == 5'd0) |-> (out == in)
    );

    // Arithmetic right shift preserves a 1 sign bit for negative inputs.
    check_arith_shift_negative_sign_fill: assert property (
        @(posedge clk)
        (shift_type == 2'b10 && shift_amount != 5'd0 && in[31] == 1'b1) |-> (out[31] == 1'b1)
    );

    // Arithmetic right shift preserves a 0 sign bit for non-negative inputs.
    check_arith_shift_positive_sign_fill: assert property (
        @(posedge clk)
        (shift_type == 2'b10 && shift_amount != 5'd0 && in[31] == 1'b0) |-> (out[31] == 1'b0)
    );

endmodule

module decoder_3to8_sva (
    input logic       clk,
    input logic [2:0] abc,
