module signal_combiner (
    input A1,
    input A2,
    input A3,
    input B1,
    input B2,
    output X
);

    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    // Combinational logic block
    assign X = (A1 & A2) | (A3 & B1) | (B1 & B2);

endmodule

sva:
module signal_combiner_sva (
    input logic A1,
    input logic A2,
    input logic A3,
    input logic B1,
    input logic B2,
    input logic X
);

    // X must match the implemented OR-of-products equation.
    check_output_equation: assert property (
        @($global_clock) X == ((A1 & A2) | (A3 & B1) | (B1 & B2))
    );

    // The A1&A2 product term must force X high.
    check_a1_a2_term: assert property (
        @($global_clock) (A1 & A2) |-> X
    );

    // The A3&B1 product term must force X high.
    check_a3_b1_term: assert property (
        @($global_clock) (A3 & B1) |-> X
    );

    // The B1&B2 product term must force X high.
    check_b1_b2_term: assert property (
        @($global_clock) (B1 & B2) |-> X
    );

    // If X is high, at least one product term must be high.
    check_output_high_has_source: assert property (
        @($global_clock) X |-> ((A1 & A2) | (A3 & B1) | (B1 & B2))
    );

    // If no product term is high, X must be low.
    check_no_term_low_output: assert property (
        @($global_clock) (!((A1 & A2) | (A3 & B1) | (B1 & B2))) |-> !X
    );

    // With B1 low, X reduces to the A1&A2 term only.
    check_b1_low_reduction: assert property (
        @($global_clock) (!B1) |-> (X == (A1 & A2))
    );

endmodule

module counter_assertions (
    input logic       clk,
    input logic       areset,
    input logic       enable,
    input logic [3:0] count
);

    // Counter is zero on the cycle after reset was asserted.
    check_reset_clears_count: assert property (
        @(posedge clk) disable iff (areset)
        (!$initstate && $past(areset)) |-> (count == 4'b0000)
    );

    // Reset has priority over enable.
    check_reset_priority_over_enable: assert property (
        @(posedge clk) disable iff (areset)
        (!$initstate && $past(areset && enable)) |-> (count == 4'b0000)
    );

    // Counter increments by one when enabled outside reset.
    check_increment_when_enabled: assert property (
        @(posedge clk) disable iff (areset)
        (!$initstate && !$past(areset) && $past(enable)) |-> (count == ($past(count) + 4'd1))
    );

    // Counter holds its value when not enabled outside reset.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (areset)
        (!$initstate && !$past(areset) && !$past(enable)) |-> (count == $past(count))
    );

    // Any count change outside reset requires enable.
    check_count_changes_require_enable: assert property (
        @(posedge clk) disable iff (areset)
        (!$initstate && !$past(areset) && (count != $past(count))) |-> $past(enable)
    );

    // The 4-bit counter wraps from 15 to 0 when enabled.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (areset)
        (!$initstate && !$past(areset) && $past(enable) && ($past(count) == 4'hF)) |-> (count == 4'h0)
    );

endmodule

