module nand3b_inverted (
    Y,
    A,
    B,
    C,
    invert,
    out_inv
);

    output Y;
    input A;
    input B;
    input C;
    input invert;
    output out_inv;

    wire A_inverted;

    assign out_inv = ~A & invert | A & ~invert;
    assign A_inverted = ~A;

    nand (Y, A_inverted, B, C);

endmodule

sva:
module nand3b_inverted_sva (
    input logic clk,
    input logic Y,
    input logic A,
    input logic B,
    input logic C,
    input logic invert,
    input logic out_inv
);

    // out_inv matches its combinational equation.
    check_out_inv_equation: assert property (
        @(posedge clk) out_inv == ((~A & invert) | (A & ~invert))
    );

    // out_inv passes A through when invert is low.
    check_out_inv_passthrough: assert property (
        @(posedge clk) !invert |-> (out_inv == A)
    );

    // out_inv inverts A when invert is high.
    check_out_inv_inverted: assert property (
        @(posedge clk) invert |-> (out_inv == ~A)
    );

    // Y matches the NAND of ~A, B, and C.
    check_y_equation: assert property (
        @(posedge clk) Y == ~(~A & B & C)
    );

    // Y is high whenever A is high.
    check_y_high_when_a_high: assert property (
        @(posedge clk) A |-> Y
    );

    // Y is high whenever B is low.
    check_y_high_when_b_low: assert property (
        @(posedge clk) !B |-> Y
    );

    // Y is high whenever C is low.
    check_y_high_when_c_low: assert property (
        @(posedge clk) !C |-> Y
    );

    // Y goes low when ~A, B, and C are all high.
    check_y_low_when_nand_inputs_high: assert property (
        @(posedge clk) (!A && B && C) |-> !Y
    );

    // Y low implies the NAND input term is true.
    check_y_low_only_when_nand_inputs_high: assert property (
        @(posedge clk) !Y |-> (!A && B && C)
    );

endmodule

rtl:
module lfsr(
    input CLK,
    input RST_N,
    input START,
    input STOP,
    output reg [15:0] DATA_OUT
);

reg [15:0] state;

always @(posedge CLK) begin
    if (RST_N == 0) begin
        state <= 16'h0000;
        DATA_OUT <= 16'h0000;
    end else if (START) begin
        state <= 16'h0000;
        DATA_OUT <= state;
    end else if (STOP) begin
        state <= 16'h0000;
        DATA_OUT <= 16'h0000;
    end else begin
        state <= {state[13:0], state[15]^state[13]};
        DATA_OUT <= state;
    end
end

endmodule

sva:
module lfsr_sva(
    input logic        CLK,
    input logic        RST_N,
    input logic        START,
    input logic        STOP,
    input logic [15:0] DATA_OUT,
    input logic [15:0] state
);

    // Reset clears state and DATA_OUT on the next clock.
    check_reset_clears_registers: assert property (
        @(posedge CLK) !RST_N |=> (state == 16'h0000) && (DATA_OUT == 16'h0000)
    );

    // START clears state on the next clock.
    check_start_clears_state: assert property (
        @(posedge CLK) disable iff (!RST_N) START |=> (state == 16'h0000)
    );

    // START makes DATA_OUT capture the previous state value.
    check_start_captures_previous_state: assert property (
        @(posedge CLK) disable iff (!RST_N) START |=> (DATA_OUT == $past(state))
    );

    // STOP clears both registers when START is low.
    check_stop_clears_registers: assert property (
        @(posedge CLK) disable iff (!RST_N) (!START && STOP) |=> (state == 16'h0000) && (DATA_OUT == 16'h0000)
    );

    // With no START or STOP, state follows the implemented concatenation update.
    check_run_updates_state: assert property (
        @(posedge CLK) disable iff (!RST_N) (!START && !STOP) |=> 
            (state == {1'b0, $past(state[13:0]), ($past(state[15]) ^ $past(state[13]))})
    );

    // With no START or STOP, DATA_OUT captures the previous state.
    check_run_updates_data_out: assert property (
        @(posedge CLK) disable iff (!RST_N) (!START && !STOP) |=> (DATA_OUT == $past(state))
    );

endmodule

rtl:
module binary_to_bcd (
    input [3:0] BIN,
    output [3:0] BCD_HI,
    output [3:0] BCD_LO
);

reg [3:0] stage1_out;
reg [3:0] stage2_out;

always @(*) begin
    stage1_out = BIN + 6'd30;
end

always @(*) begin
    stage2_out = stage1_out + (stage1_out >= 5'd10 ? 3'd6 : 3'd0);
end

// Fix: Use blocking assignments to assign values to reg outputs
assign BCD_HI = stage2_out[3:2];
assign BCD_LO = stage2_out[1:0];

endmodule

sva:
module binary_to_bcd_sva (
    input logic clk,
    input logic [3:0] BIN,
    input logic [3:0] BCD_HI,
    input logic [3:0] BCD_LO
);

    // BCD_HI is zero-extended from a 2-bit slice.
    check_bcd_hi_zero_extended: assert property (
        @(posedge clk) disable iff (1'b0)
        BCD_HI[3:2] == 2'b00
    );

    // BCD_LO is zero-extended from a 2-bit slice.
    check_bcd_lo_zero_extended: assert property (
        @(posedge clk) disable iff (1'b0)
        BCD_LO[3:2] == 2'b00
    );

    // The output slices reconstruct the computed 4-bit transformed value.
    check_output_matches_combinational_transform: assert property (
        @(posedge clk) disable iff (1'b0)
