module min_shift_reg(
    input clk, 
    input areset,  // Async active-high reset to zero
    input load,
    input ena,
    input [7:0] a, b, c, d,    // Four 8-bit unsigned numbers as input
    output [3:0] q);           // 4-bit output from the shift register

    // Priority Encoder module to find the minimum of four inputs
    priority_encoder pe(
        .in({a, b, c, d}),
        .out(min_val)
    );

    // 4-bit shift register with asynchronous reset, synchronous load and enable
    reg [3:0] shift_reg;

    always @(posedge clk or posedge areset) begin
        if (areset) begin
            shift_reg <= 0;
        end else if (load) begin
            shift_reg <= min_val;
        end else if (ena) begin
            shift_reg <= {shift_reg[2:0], 1'b0};
        end
    end

    // Functional module to feed priority encoder output to shift register
    wire [1:0] min_val;

    assign q = shift_reg;

endmodule
module priority_encoder(
    input [31:0] in,
    output reg [1:0] out
);

    always @* begin
        if (in[7:0] < in[15:8]) begin
            out = 2'b00;
        end else if (in[15:8] < in[23:16]) begin
            out = 2'b01;
        end else if (in[23:16] < in[31:24]) begin
            out = 2'b10;
        end else begin
            out = 2'b11;
        end
    end

endmodule

sva:
module min_shift_reg_sva (
    input logic        clk,
    input logic        areset,
    input logic        load,
    input logic        ena,
    input logic [7:0]  a,
    input logic [7:0]  b,
    input logic [7:0]  c,
    input logic [7:0]  d,
    input logic [3:0]  q
);

    // Sampled reset forces the register output to zero.
    check_reset_clears_q: assert property (
        @(posedge clk)
        areset |-> (q == 4'b0000)
    );

    // Load writes 00 when the first encoder comparison d<c is true.
    check_load_selects_00_d_lt_c: assert property (
        @(posedge clk) disable iff (areset)
        load && (d < c) |=> (q == 4'b0000)
    );

    // Load writes 01 when d<c is false and c<b is true.
    check_load_selects_01_c_lt_b: assert property (
        @(posedge clk) disable iff (areset)
        load && !(d < c) && (c < b) |=> (q == 4'b0001)
    );

    // Load writes 10 when earlier comparisons fail and b<a is true.
    check_load_selects_10_b_lt_a: assert property (
        @(posedge clk) disable iff (areset)
        load && !(d < c) && !(c < b) && (b < a) |=> (q == 4'b0010)
    );

    // Load writes 11 when all encoder comparisons fail.
    check_load_selects_11_default: assert property (
        @(posedge clk) disable iff (areset)
        load && !(d < c) && !(c < b) && !(b < a) |=> (q == 4'b0011)
    );

    // Enable shifts the register left and inserts 0 into bit 0.
    check_shift_on_enable: assert property (
        @(posedge clk) disable iff (areset)
        (!load && ena) |=> (q == {$past(q[2:0]), 1'b0})
    );

    // With neither load nor enable, the register holds its value.
    check_hold_when_idle: assert property (
        @(posedge clk) disable iff (areset)
        (!load && !ena) |=> (q == $past(q))
    );

endmodule

