module square_wave_generator (
    input clk,
    input reset,
    output reg square_wave
);

reg [31:0] counter;

always @(posedge clk, posedge reset) begin
    if (reset) begin
        square_wave <= 1'b0;
        counter <= 32'd0;
    end else begin
        if (counter == 32'd49999999) begin
            counter <= 32'd0;
            square_wave <= ~square_wave;
        end else begin
            counter <= counter + 1;
        end
    end
end

endmodule

