    and and1 (and1_out  , A1, A2                );
    nor nor0 (nor0_out_Y, and0_out, C1, and1_out);
    buf buf0 (Y         , nor0_out_Y            );

endmodule

sva:
module my_module_sva (
    input logic Y,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic B2,
    input logic C1
);

    // No RTL clock or reset; sample combinational behavior on the formal global clock.

    // Y must match the NOR of (B1&B2), C1, and (A1&A2).
    check_full_boolean_function: assert property (
        @($global_clock) Y == !((B1 & B2) | C1 | (A1 & A2))
    );

    // C1 high must force the NOR output low.
    check_c1_forces_low: assert property (
        @($global_clock) C1 |-> !Y
    );

    // A1 and A2 both high must force the NOR output low.
    check_a_pair_forces_low: assert property (
        @($global_clock) (A1 & A2) |-> !Y
    );

    // B1 and B2 both high must force the NOR output low.
    check_b_pair_forces_low: assert property (
        @($global_clock) (B1 & B2) |-> !Y
    );

    // If all NOR inputs are low, Y must be high.
    check_all_nor_inputs_low_drives_high: assert property (
        @($global_clock) (!C1 && !(A1 & A2) && !(B1 & B2)) |-> Y
    );

    // A high Y means every NOR input is low.
    check_high_output_means_all_nor_inputs_low: assert property (
        @($global_clock) Y |-> (!C1 && !(A1 & A2) && !(B1 & B2))
    );

endmodule

module top_module_sva (
    input logic clk,
    input logic reset,
    input logic enable,
    input logic [3:0] a,
    input logic [3:0] b,
    input logic cin,
    input logic cout,
    input logic [3:0] sum,
    input logic [7:0] count,
    input logic [11:0] result
);

    // Count is zero whenever reset is asserted low.
    check_reset_clears_count: assert property (
        @(posedge clk) !reset |-> (count == 8'h00)
    );

    // Count increments by one on each enabled clock.
    check_count_increments_when_enabled: assert property (
        @(posedge clk) disable iff (!reset)
        enable |=> (count == ($past(count) + 8'd1))
    );

    // Count holds its value when enable is low.
    check_count_holds_when_disabled: assert property (
        @(posedge clk) disable iff (!reset)
        !enable |=> (count == $past(count))
    );

    // Adder outputs match the implemented zero-extended 4-bit sum.
    check_adder_outputs_match_rtl: assert property (
        @(posedge clk) disable iff (!reset)
        {cout, sum} == {1'b0, (a + b + cin)}
    );

    // Carry-out remains low in the implemented adder logic.
    check_adder_cout_zero: assert property (
        @(posedge clk) disable iff (!reset)
        cout == 1'b0
    );

    // Result matches the implemented zero-extended 8-bit addition.
    check_result_matches_rtl: assert property (
        @(posedge clk) disable iff (!reset)
        result == {4'b0, ({4'b0, sum} + count)}
    );

    // Result upper nibble stays zero in the implemented logic.
    check_result_upper_nibble_zero: assert property (
        @(posedge clk) disable iff (!reset)
        result[11:8] == 4'b0
    );

endmodule

rtl:
module xor_gate(
    input clk,
    input a,
    input b,
    output wire out_xor
);
    assign out_xor = a ^ b;
endmodule

module decoder_4to16(
    input [3:0] in,
    input [2:0] sel,
    output reg [15:0] out_decoder
);
    always @(*) begin
        case (sel)
            3'b000: out_decoder = {16'b0000000000000001};
            3'b001: out_decoder = {16'b0000000000000010};
            3'b010: out_decoder = {16'b0000000000000100};
            3'b011: out_decoder = {16'b0000000000001000};
            3'b100: out_decoder = {16'b0000000000010000};
            3'b101: out_decoder = {16'b0000000000100000};
            3'b110: out_decoder = {16'b0000000001000000};
            3'b111: out_decoder = {16'b0000000010000000};
            default: out_decoder = 16'b0;
        endcase
    end
endmodule

module functional_module(
    input clk,
    input a,
    input b,
    input [3:0] in,
    input [2:0] sel,
    output wire out_func
);
    wire out_xor;
    wire [15:0] out_decoder;

    xor_gate xor_inst(
        .clk(clk),
        .a(a),
        .b(b),
        .out_xor(out_xor)
    );

    decoder_4to16 decoder_inst(
        .in(in),
        .sel(sel),
        .out_decoder(out_decoder)
    );

    assign out_func = out_xor ^ out_decoder[sel];
endmodule

module top_module(
    input clk,
    input a,
    input b,
    input [255:0] in,
    input [2:0] sel,
    output wire out_func
);
    functional_module func_inst(
        .clk(clk),
        .a(a),
        .b(b),
        .in(in[3:0]),
        .sel(sel),
        .out_func(out_func)
    );
endmodule

sva:
module top_module_sva(
    input logic clk,
    input logic a,
    input logic b,
    input logic [255:0] in,
    input logic [2:0] sel,
    input logic out_func
);

    // out_func always equals the XNOR of a and b.
    check_out_func_matches_xnor: assert property (
        @(posedge clk) disable iff (1'b0)
        out_func == (a ~^ b)
    );

    // Equal input bits drive the output high.
    check_equal_inputs_drive_high: assert property (
        @(posedge clk) disable iff (1'b0)
        (a == b) |-> (out_func == 1'b1)
    );

    // Different input bits drive the output low.
    check_different_inputs_drive_low: assert property (
        @(posedge clk) disable iff (1'b0)
        (a != b) |-> (out_func == 1'b0)
    );

    // Holding a and b stable keeps the output stable.
    check_stable_ab_keep_output_stable: assert property (
        @(posedge clk) disable iff (1'b0)
        !$initstate && (a == $past(a)) && (b == $past(b)) |-> (out_func == $past(out_func))
    );

    // Changing sel alone does not affect the output.
    check_sel_change_does_not_affect_output: assert property (
        @(posedge clk) disable iff (1'b0)
        !$initstate && (a == $past(a)) && (b == $past(b)) &&
        (in == $past(in)) && (sel != $past(sel)) |-> (out_func == $past(out_func))
    );

    // Changing the input bus alone does not affect the output.
    check_in_change_does_not_affect_output: assert property (
        @(posedge clk) disable iff (1'b0)
        !$initstate && (a == $past(a)) && (b == $past(b)) &&
        (sel == $past(sel)) && (in != $past(in)) |-> (out_func == $past(out_func))
    );

    // Toggling a alone flips the output.
    check_a_toggle_flips_output: assert property (
        @(posedge clk) disable iff (1'b0)
        !$initstate && $changed(a) && (b == $past(b)) |-> (out_func != $past(out_func))
    );

    // Toggling b alone flips the output.
    check_b_toggle_flips_output: assert property (
        @(posedge clk) disable iff (1'b0)
        !$initstate && $changed(b) && (a == $past(a)) |-> (out_func != $past(out_func))
    );

    // Toggling a and b together keeps the output unchanged.
    check_ab_toggle_together_keep_output: assert property (
        @(posedge clk) disable iff (1'b0)
        !$initstate && $changed(a) && $changed(b) |-> (out_func == $past(out_func))
    );

endmodule

module mux8to1_assertions (
    input logic [7:0] A,
    input logic [2:0] S,
    input logic X
);

    // No RTL clock or reset; sample the combinational mux on the global formal clock.

    // S=000 selects A[0].
    check_select_0: assert property (
        @($global_clock) (S == 3'b000) |-> (X == A[0])
    );

    // S=001 selects A[1].
    check_select_1: assert property (
        @($global_clock) (S == 3'b001) |-> (X == A[1])
    );

    // S=010 selects A[2].
    check_select_2: assert property (
        @($global_clock) (S == 3'b010) |-> (X == A[2])
    );

    // S=011 selects A[3].
    check_select_3: assert property (
        @($global_clock) (S == 3'b011) |-> (X == A[3])
    );

    // S=100 selects A[4].
    check_select_4: assert property (
        @($global_clock) (S == 3'b100) |-> (X == A[4])
    );

    // S=101 selects A[5].
    check_select_5: assert property (
        @($global_clock) (S == 3'b101) |-> (X == A[5])
    );

    // S=110 selects A[6].
    check_select_6: assert property (
        @($global_clock) (S == 3'b110) |-> (X == A[6])
    );

    // S=111 selects A[7].
    check_select_7: assert property (
        @($global_clock) (S == 3'b111) |-> (X == A[7])
    );

    // X matches the RTL sum-of-products mux equation.
    check_output_sum_of_products: assert property (
        @($global_clock)
        X == ((~S[2] & ~S[1] & ~S[0] & A[0]) |
              (~S[2] & ~S[1] &  S[0] & A[1]) |
              (~S[2] &  S[1] & ~S[0] & A[2]) |
              (~S[2] &  S[1] &  S[0] & A[3]) |
              ( S[2] & ~S[1] & ~S[0] & A[4]) |
              ( S[2] & ~S[1] &  S[0] & A[5]) |
              ( S[2] &  S[1] & ~S[0] & A[6]) |
              ( S[2] &  S[1] &  S[0] & A[7]))
    );

    // Stable select and selected input keep X stable.
    check_output_stable_when_selected_path_stable: assert property (
        @($global_clock)
        (!$initstate &&
         $stable(S) &&
         (((S == 3'b000) && $stable(A[0])) ||
          ((S == 3'b001) && $stable(A[1])) ||
          ((S == 3'b010) && $stable(A[2])) ||
          ((S == 3'b011) && $stable(A[3])) ||
          ((S == 3'b100) && $stable(A[4])) ||
          ((S == 3'b101) && $stable(A[5])) ||
          ((S == 3'b110) && $stable(A[6])) ||
          ((S == 3'b111) && $stable(A[7]))))
        |-> $stable(X)
    );

    // With stable select, a selected-input change must change X.
    check_output_tracks_selected_input_change: assert property (
        @($global_clock)
        (!$initstate &&
         $stable(S) &&
         (((S == 3'b000) && (A[0] != $past(A[0]))) ||
          ((S == 3'b001) && (A[1] != $past(A[1]))) ||
          ((S == 3'b010) && (A[2] != $past(A[2]))) ||
          ((S == 3'b011) && (A[3] != $past(A[3]))) ||
          ((S == 3'b100) && (A[4] != $past(A[4]))) ||
          ((S == 3'b101) && (A[5] != $past(A[5]))) ||
          ((S == 3'b110) && (A[6] != $past(A[6]))) ||
          ((S == 3'b111) && (A[7] != $past(A[7])))))
        |-> (X != $past(X))
    );

endmodule

rtl:
module shift_register (
    input CLK,
    input SI,
    output SO,
    output [3:0] Q
);

reg [3:0] pipeline_reg;

always @(posedge CLK) begin
    if (SI) begin
        pipeline_reg <= 1'b1;
    end else begin
        pipeline_reg <= {pipeline_reg[2:0], SO};
    end
end

assign Q = pipeline_reg;
assign SO = pipeline_reg[0];

endmodule

sva:
module shift_register_sva (
    input logic       CLK,
    input logic       SI,
    input logic       SO,
    input logic [3:0] Q
);

    // SO always reflects the LSB of Q.
    check_so_matches_q_lsb: assert property (
        @(posedge CLK) SO == Q[0]
    );

    // SI high loads 4'b0001 into Q on the next clock.
    check_si_high_loads_one: assert property (
        @(posedge CLK) SI |=> Q == 4'b0001
    );

    // SI high makes SO high on the next clock.
    check_si_high_sets_so: assert property (
        @(posedge CLK) SI |=> SO == 1'b1
    );

    // SI high clears the upper three bits on the next clock.
    check_si_high_clears_upper_bits: assert property (
        @(posedge CLK) SI |=> Q[3:1] == 3'b000
    );

    // SI low updates Q from the previous Q[2:0] and SO.
    check_si_low_updates_q: assert property (
        @(posedge CLK) !SI |=> Q == {$past(Q[2:0]), $past(SO)}
    );

    // SI low shifts the previous Q[2:0] into Q[3:1].
    check_si_low_updates_upper_bits: assert property (
        @(posedge CLK) !SI |=> Q[3:1] == $past(Q[2:0])
    );

    // SI low keeps SO equal to its previous value.
    check_si_low_holds_so: assert property (
        @(posedge CLK) !SI |=> SO == $past(SO)
    );

    // SI low duplicates the previous SO into Q[1:0].
    check_si_low_duplicates_so_into_low_bits: assert property (
        @(posedge CLK) !SI |=> Q[1:0] == {$past(SO), $past(SO)}
    );

endmodule

rtl:
module mag_comparator (
  input [2:0] A,
  input [2:0] B,
  output reg [1:0] result
);

  always @(*) begin
    if (A == B) begin
      result = 2'b00;
    end else if (A > B) begin
      result = 2'b01;
    end else begin
      result = 2'b10;
    end
  end

endmodule

sva:
module mag_comparator_sva (
    input logic clk,
    input logic [2:0] A,
    input logic [2:0] B,
    input logic [1:0] result
);

    // Result matches the implemented comparator function.
    check_function_map: assert property (
        @(posedge clk) result == ((A == B) ? 2'b00 : ((A > B) ? 2'b01 : 2'b10))
    );

    // Equal inputs produce 00.
    check_equal_case: assert property (
        @(posedge clk) (A == B) |-> (result == 2'b00)
    );

    // A greater than B produces 01.
    check_greater_case: assert property (
        @(posedge clk) (A > B) |-> (result == 2'b01)
    );

    // A less than B produces 10.
    check_less_case: assert property (
        @(posedge clk) (A < B) |-> (result == 2'b10)
    );

    // 00 indicates equal inputs.
    check_result_equal_encoding: assert property (
        @(posedge clk) (result == 2'b00) |-> (A == B)
    );

    // 01 indicates A is greater than B.
    check_result_greater_encoding: assert property (
        @(posedge clk) (result == 2'b01) |-> (A > B)
    );

    // 10 indicates A is less than B.
    check_result_less_encoding: assert property (
        @(posedge clk) (result == 2'b10) |-> (A < B)
    );

    // 11 is never a valid output encoding.
    check_no_invalid_encoding: assert property (
        @(posedge clk) (result != 2'b11)
    );

    // Stable inputs keep the output stable.
    check_stable_inputs_stable_result: assert property (
        @(posedge clk) ($stable(A) && $stable(B)) |-> $stable(result)
    );

endmodule

module binary_counter_sva #(
    parameter [3:0] start_value = 4'd4
) (
    input logic       clk,
    input logic       cen,
    input logic       dir,
    input logic       rst,
    input logic [3:0] out
);

    // Synchronous reset overrides counting and loads start_value.
    check_reset_load_start_value: assert property (
        @(posedge clk) rst |=> (out == start_value)
    );

    // When count enable is low, the counter holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (rst)
        (!cen) |=> (out == $past(out))
    );

    // When enabled with dir low, the counter increments by one.
    check_increment_when_enabled: assert property (
        @(posedge clk) disable iff (rst)
        (cen && (dir == 1'b0)) |=> (out == ($past(out) + 4'd1))
    );

    // When enabled with dir high, the counter decrements by one.
    check_decrement_when_enabled: assert property (
        @(posedge clk) disable iff (rst)
        (cen && (dir == 1'b1)) |=> (out == ($past(out) - 4'd1))
    );

endmodule

rtl:
module and_gate_with_inverter (
    output Y,
    input  A1,
    input  A2,
    input  A3,
    input  B1,
    input  C1
);

    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;

    wire B1_inv;
    assign B1_inv = ~B1;

    wire and_gate_output;
    and (and_gate_output, A1, A2, A3);

    assign Y = (C1 == 1'b1) ? 1'b0 : (and_gate_output & B1_inv);

endmodule

sva:
module and_gate_with_inverter_sva (
    input logic clk,
    input logic Y,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic B1,
    input logic C1
);

    // C1 high forces the output low.
    check_c1_forces_output_low: assert property (
        @(posedge clk)
        (C1 === 1'b1) |-> (Y === 1'b0)
    );

    // All A inputs high with B1 low and C1 low drives the output high.
    check_all_enables_drive_output_high: assert property (
        @(posedge clk)
        ((C1 === 1'b0) && (A1 === 1'b1) && (A2 === 1'b1) && (A3 === 1'b1) && (B1 === 1'b0))
        |-> (Y === 1'b1)
    );

    // With C1 low, any low A input or high B1 forces the output low.
    check_blocking_conditions_drive_output_low: assert property (
        @(posedge clk)
        ((C1 === 1'b0) &&
         ((A1 === 1'b0) || (A2 === 1'b0) || (A3 === 1'b0) || (B1 === 1'b1)))
        |-> (Y === 1'b0)
    );

    // A high output requires C1 low, all A inputs high, and B1 low.
    check_output_high_requires_enables: assert property (
        @(posedge clk)
        (Y === 1'b1)
        |-> ((C1 === 1'b0) && (A1 === 1'b1) && (A2 === 1'b1) && (A3 === 1'b1) && (B1 === 1'b0))
    );

endmodule

rtl:
module binary_counter(clk, rst, count);

  input clk, rst;
  output reg [3:0] count;

  always @(posedge clk) begin
    if (rst) begin
      count <= 4'b0000;
    end else begin
      count <= count + 1;
    end
  end

endmodule

sva:
module binary_counter_sva (
    input logic       clk,
    input logic       rst,
    input logic [3:0] count
);

    // Reset forces count to zero by the next clock sample.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |=> (count == 4'b0000)
    );

    // On reset release, the sampled count is still zero on that clock edge.
    check_reset_release_starts_from_zero: assert property (
        @(posedge clk) disable iff (rst)
        $fell(rst) |-> (count == 4'b0000)
    );

    // Without reset, count increments by one on each clock.
    check_count_increments: assert property (
        @(posedge clk) disable iff (rst)
        1'b1 |=> (count == ($past(count) + 4'd1))
    );

    // A maximum count value wraps back to zero on the next clock.
    check_count_wraps_from_max: assert property (
        @(posedge clk) disable iff (rst)
        (count == 4'hf) |=> (count == 4'h0)
    );

endmodule

rtl:
module four_bit_adder(
    input [3:0] A,
    input [3:0] B,
    output Cout,
    output [3:0] S
);

    wire [2:0] carry;  // Internal carry wires

    // Full adder for bit 0
    xor(S[0], A[0], B[0], 0);   
    and(carry[0], A[0], B[0]);

    // Full adder for bit 1
    xor(S[1], A[1], B[1], carry[0]);

    majority maj0 (carry[1], A[1], B[1], carry[0]);

    // Full adder for bit 2
    xor(S[2], A[2], B[2], carry[1]);

    majority maj1 (carry[2], A[2], B[2], carry[1]);

    // Full adder for bit 3
    xor(S[3], A[3], B[3], carry[2]);
    majority maj2 (Cout, A[3], B[3], carry[2]);

endmodule
module majority(output out, input a, input b, input c);
    wire ab, bc, ac;
    and(ab, a, b);
    and(bc, b, c);
    and(ac, a, c);
    or(out, ab, bc, ac);
endmodule

sva:
module four_bit_adder_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic Cout,
    input logic [3:0] S
);

    function automatic logic maj3(input logic a, input logic b, input logic c);
        maj3 = (a & b) | (b & c) | (a & c);
    endfunction

    // The concatenated outputs equal the 5-bit sum of A and B.
    check_full_sum: assert property (
        @(posedge clk) {Cout, S} == ({1'b0, A} + {1'b0, B})
    );

    // Sum bit 0 is the xor of the least-significant input bits.
    check_sum_bit0: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0])
    );

    // Sum bit 1 includes the carry generated by bit 0.
    check_sum_bit1: assert property (
        @(posedge clk) S[1] == (A[1] ^ B[1] ^ (A[0] & B[0]))
    );

    // Sum bit 2 includes the majority carry from bit 1.
    check_sum_bit2: assert property (
        @(posedge clk) S[2] == (A[2] ^ B[2] ^ maj3(A[1], B[1], (A[0] & B[0])))
    );

    // Sum bit 3 includes the majority carry from bit 2.
    check_sum_bit3: assert property (
        @(posedge clk) S[3] == (A[3] ^ B[3] ^ maj3(A[2], B[2], maj3(A[1], B[1], (A[0] & B[0]))))
    );

    // Cout is the majority of the top input bits and the carry into bit 3.
    check_cout: assert property (
        @(posedge clk) Cout == maj3(A[3], B[3], maj3(A[2], B[2], maj3(A[1], B[1], (A[0] & B[0]))))
    );

endmodule

rtl:
module ripple_carry_adder(
    input wire [3:0] A,
    input wire [3:0] B,
    input wire Cin,
    input wire Load,
    input wire Clear,
    input wire clock,
    output reg [3:0] S,
    output reg Cout
);

always @(posedge clock) begin
    if (Clear) begin
        S <= 4'b0;
        Cout <= 1'b0;
    end else if (Load) begin
        S <= A;
        Cout <= Cin;
    end else begin
        {Cout, S} <= A + B + Cin;
    end
end

endmodule

sva:
module ripple_carry_adder_assertions(
    input logic [3:0] A,
    input logic [3:0] B,
    input logic Cin,
    input logic Load,
    input logic Clear,
    input logic clock,
    input logic [3:0] S,
    input logic Cout
);

    // Clock: clock; reset: Clear (synchronous active high); logic is sequential.

    // After a clear cycle, both registered outputs are zero.
    check_clear_clears_outputs: assert property (
        @(posedge clock) disable iff (Clear || $initstate)
        $past(Clear) |-> ({Cout, S} == 5'b00000)
    );

    // Load captures A into S and Cin into Cout on the next cycle.
    check_load_captures_inputs: assert property (
        @(posedge clock) disable iff (Clear || $initstate)
        (!Clear && Load) |=> ({Cout, S} == {$past(Cin), $past(A)})
    );

    // With neither Clear nor Load asserted, the next cycle holds A + B + Cin.
    check_add_computes_result: assert property (
        @(posedge clock) disable iff (Clear || $initstate)
        (!Clear && !Load) |=> ({Cout, S} == ({1'b0, $past(A)} + {1'b0, $past(B)} + $past(Cin)))
    );

    // Clear has priority over Load when both were asserted in the prior cycle.
    check_clear_has_priority_over_load: assert property (
        @(posedge clock) disable iff (Clear || $initstate)
        $past(Clear && Load) |-> ({Cout, S} == 5'b00000)
    );

    // The registered outputs match the operation selected in the prior cycle.
    check_output_matches_selected_operation: assert property (
        @(posedge clock) disable iff (Clear || $initstate)
        ({Cout, S} == ($past(Clear) ? 5'b00000 :
                      ($past(Load) ? {$past(Cin), $past(A)} :
                                     ({1'b0, $past(A)} + {1'b0, $past(B)} + $past(Cin)))))
    );

endmodule

module bcd_converter_assertions (
    input logic [3:0]  input_val,
    input logic [15:0] bcd_val
);

    function automatic logic [15:0] expected_bcd(input logic [3:0] val);
        case (val)
            4'b0000: expected_bcd = 16'b0000000000000000;
            4'b0001: expected_bcd = 16'b0000000000000001;
            4'b0010: expected_bcd = 16'b0000000000000010;
            4'b0011: expected_bcd = 16'b0000000000000011;
            4'b0100: expected_bcd = 16'b0000000000000100;
            4'b0101: expected_bcd = 16'b0000000000000101;
            4'b0110: expected_bcd = 16'b0000000000000110;
            4'b0111: expected_bcd = 16'b0000000000000111;
            4'b1000: expected_bcd = 16'b0000000000010000;
            4'b1001: expected_bcd = 16'b0000000000010001;
            default: expected_bcd = 16'b0000000000000000;
        endcase
    endfunction

    // Output matches the implemented case mapping for every input value.
    check_exact_case_mapping: assert property (
        @($global_clock) bcd_val == expected_bcd(input_val)
    );

    // Inputs 0 through 7 map directly into the low nibble with upper bits clear.
    check_zero_to_seven_direct_mapping: assert property (
        @($global_clock) (input_val <= 4'd7) |-> ((bcd_val[15:4] == 12'h000) && (bcd_val[3:0] == input_val))
    );

    // Input 8 maps to 16'h0010.
    check_input_eight_mapping: assert property (
        @($global_clock) (input_val == 4'd8) |-> (bcd_val == 16'h0010)
    );

    // Input 9 maps to 16'h0011.
    check_input_nine_mapping: assert property (
        @($global_clock) (input_val == 4'd9) |-> (bcd_val == 16'h0011)
    );

    // Inputs 10 through 15 select the default zero output.
    check_default_zero_for_ten_to_fifteen: assert property (
        @($global_clock) (input_val >= 4'd10) |-> (bcd_val == 16'h0000)
    );

    // The upper byte is always zero for all implemented outputs.
    check_upper_byte_zero: assert property (
        @($global_clock) (bcd_val[15:8] == 8'h00)
    );

endmodule

rtl:
module Registro_Universal
#(parameter N = 8) (
	input wire hold,
	input wire [N-1:0]in_rtc_dato,
	input wire [N-1:0]in_count_dato,
	input wire clk, input wire reset, input wire chip_select, output wire [N-1:0]out_dato
);
reg [N-1:0]reg_dato;
reg [N-1:0]next_dato;

always@(negedge clk, posedge reset)
begin
	if(reset) reg_dato <= 0;
	else reg_dato <= next_dato;
end

always@*
	begin
	if (~hold) begin
	case(chip_select)
	1'b0: next_dato = in_rtc_dato;
	1'b1: next_dato = in_count_dato;
	endcase
	end
	else next_dato = reg_dato;
	end

assign out_dato = reg_dato;

endmodule

sva:
module Registro_Universal_sva
#(parameter N = 8) (
    input logic hold,
    input logic [N-1:0] in_rtc_dato,
    input logic [N-1:0] in_count_dato,
    input logic clk,
    input logic reset,
    input logic chip_select,
    input logic [N-1:0] out_dato
);

    // A sampled reset leaves the output cleared by the next clock sample.
    check_reset_clears_output: assert property (
        @(negedge clk) reset |=> (out_dato == '0)
    );

    // Hold keeps the register output unchanged.
    check_hold_preserves_value: assert property (
        @(negedge clk) disable iff (reset)
        hold |=> (out_dato == $past(out_dato))
    );

    // With hold low and chip_select low, the RTC input is loaded.
    check_loads_rtc_input: assert property (
        @(negedge clk) disable iff (reset)
        (!hold && (chip_select == 1'b0)) |=> (out_dato == $past(in_rtc_dato))
    );

    // With hold low and chip_select high, the count input is loaded.
    check_loads_count_input: assert property (
        @(negedge clk) disable iff (reset)
        (!hold && (chip_select == 1'b1)) |=> (out_dato == $past(in_count_dato))
    );

endmodule

rtl:
module top_module (
    input clk,
    input reset,
    input [31:0] in,
    input load,
    input ena,
    input [3:0] data,
    output [3:0] out
);

    // Transition detector
    reg [1:0] det;
    always @(posedge clk) begin
        det <= {det[0], in[0] ^ det[1]};
    end

    // Shift register
    reg [3:0] q;
    always @(posedge clk) begin
        if (reset) begin
            q <= 4'b0;
        end else if (load) begin
            q <= data;
        end else if (ena) begin
            q <= {q[2:0], det[1]};
        end
    end

    assign out = q;

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic reset,
    input logic [31:0] in,
    input logic load,
    input logic ena,
    input logic [3:0] data,
    input logic [3:0] out,
    input logic [1:0] det,
    input logic [3:0] q
);

    // out is a direct reflection of q.
    check_output_matches_q: assert property (
        @(posedge clk) disable iff ($initstate) out === q
    );

    // det[1] takes the previous det[0] each cycle.
    check_detector_msb_update: assert property (
        @(posedge clk) disable iff ($initstate) det[1] == $past(det[0])
    );

    // det[0] takes in[0] XOR the previous det[1].
    check_detector_lsb_update: assert property (
        @(posedge clk) disable iff ($initstate) det[0] == ($past(in[0]) ^ $past(det[1]))
    );

    // A reset cycle clears q on the following cycle.
    check_reset_clears_q: assert property (
        @(posedge clk) reset |=> q == 4'b0000
    );

    // load captures data, regardless of ena.
    check_load_captures_data: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        $past(!reset && load) |-> q == $past(data)
    );

    // With no reset, load, or enable, q holds its value.
    check_hold_without_load_or_enable: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        $past(!reset && !load && !ena) |-> q == $past(q)
    );

    // With ena and no load, q shifts left and appends det[1].
    check_shift_register_update: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        $past(!reset && !load && ena) |-> q == {$past(q[2:0]), $past(det[1])}
    );

endmodule

bind top_module top_module_sva top_module_sva_inst (
    .clk(clk),
    .reset(reset),
    .in(in),
    .load(load),
    .ena(ena),
    .data(data),
    .out(out),
    .det(det),
    .q(q)
);

