module bit_counter(
    input [3:0] in,
    output [3:0] out
);

wire [3:0] in_and_1;
wire [3:0] in_and_2;
wire [3:0] in_and_3;
wire [3:0] in_and_4;
wire [3:0] in_and_5;
wire [3:0] in_and_6;
wire [3:0] in_and_7;
wire [3:0] in_and_8;
wire [3:0] in_and_9;
wire [3:0] in_and_10;
wire [3:0] in_and_11;
wire [3:0] in_and_12;
wire [3:0] in_and_13;
wire [3:0] in_and_14;
wire [3:0] in_and_15;

assign in_and_1 = {4{1'b1}} & {in};
assign in_and_2 = {2{1'b1}} & {in[3:2]};
assign in_and_3 = {2{1'b1}} & {in[2:1]};
assign in_and_4 = {2{1'b1}} & {in[1:0]};
assign in_and_5 = {4{1'b0}} & {in};
assign in_and_6 = {2{1'b0}} & {in[3:2]};
assign in_and_7 = {2{1'b0}} & {in[2:1]};
assign in_and_8 = {2{1'b0}} & {in[1:0]};
assign in_and_9 = {3{1'b1}} & {in[3:1]};
assign in_and_10 = {3{1'b1}} & {in[2:0]};
assign in_and_11 = {3{1'b0}} & {in[3:1]};
assign in_and_12 = {3{1'b0}} & {in[2:0]};
assign in_and_13 = {2{1'b1}} & {in[3], in[1]};
assign in_and_14 = {2{1'b0}} & {in[3], in[1]};
assign in_and_15 = {2{1'b1}} & {in[2], in[0]};

assign out = in_and_1 + in_and_2 + in_and_3 + in_and_4 + in_and_5 + in_and_6 + in_and_7 + in_and_8 + in_and_9 + in_and_10 + in_and_11 + in_and_12 + in_and_13 + in_and_14 + in_and_15;

endmodule

sva:
module bit_counter_sva (
    input logic       clk,
    input logic [3:0] in,
    input logic [3:0] out
);

    // out matches the implemented sum of the selected input slices.
    check_output_matches_rtl_sum: assert property (
        @(posedge clk)
        out == (
            in +
            {2'b00, in[3:2]} +
            {2'b00, in[2:1]} +
            {2'b00, in[1:0]} +
            {1'b0,  in[3:1]} +
            {1'b0,  in[2:0]} +
            {2'b00, in[3], in[1]} +
            {2'b00, in[2], in[0]}
        )
    );

    // Lower bits 000 produce 0 regardless of in[3].
    check_lower3_000_maps_to_0: assert property (
        @(posedge clk)
        (in[2:0] == 3'b000) |-> (out == 4'h0)
    );

    // Lower bits 001 produce 4 regardless of in[3].
    check_lower3_001_maps_to_4: assert property (
        @(posedge clk)
        (in[2:0] == 3'b001) |-> (out == 4'h4)
    );

    // Lower bits 010 produce 9 regardless of in[3].
    check_lower3_010_maps_to_9: assert property (
        @(posedge clk)
        (in[2:0] == 3'b010) |-> (out == 4'h9)
    );

    // Lower bits 011 produce D regardless of in[3].
    check_lower3_011_maps_to_d: assert property (
        @(posedge clk)
        (in[2:0] == 3'b011) |-> (out == 4'hD)
    );

    // Lower bits 100 produce F regardless of in[3].
    check_lower3_100_maps_to_f: assert property (
        @(posedge clk)
        (in[2:0] == 3'b100) |-> (out == 4'hF)
    );

    // Lower bits 101 produce 3 regardless of in[3].
    check_lower3_101_maps_to_3: assert property (
        @(posedge clk)
        (in[2:0] == 3'b101) |-> (out == 4'h3)
    );

    // Lower bits 110 produce 8 regardless of in[3].
    check_lower3_110_maps_to_8: assert property (
        @(posedge clk)
        (in[2:0] == 3'b110) |-> (out == 4'h8)
    );

    // Lower bits 111 produce C regardless of in[3].
    check_lower3_111_maps_to_c: assert property (
        @(posedge clk)
        (in[2:0] == 3'b111) |-> (out == 4'hC)
    );

    // Toggling only in[3] does not change out.
    check_msb_toggle_does_not_change_output: assert property (
        @(posedge clk)
        (!$initstate && (in[2:0] == $past(in[2:0])) && (in[3] != $past(in[3]))) |-> (out == $past(out))
    );

endmodule

rtl:
module xor_gate_pipeline(
    input a,
    input b,
    output reg out_comb
);

    reg [1:0] stage1;
    reg [1:0] stage2;

    always @ (a, b) begin
        stage1[0] <= a ^ b;
        stage1[1] <= stage1[0];
        stage2[0] <= stage1[1];
        stage2[1] <= stage2[0];
        out_comb <= stage2[1];
    end

endmodule

sva:
module xor_gate_pipeline_sva (
    input logic       a,
    input logic       b,
    input logic       out_comb,
    input logic [1:0] stage1,
    input logic [1:0] stage2
);

    // No explicit clock or reset exists in the RTL; sample on the formal global clock.

    // stage1[0] captures the current XOR whenever an input changes.
    check_stage1_capture: assert property (
        @($global_clock)
        (!$initstate && ($changed(a) || $changed(b))) |-> (stage1[0] == (a ^ b))
    );

    // stage1[1] shifts in the previous stage1[0] value on an input change.
    check_stage1_shift: assert property (
        @($global_clock)
        (!$initstate && ($changed(a) || $changed(b))) |-> (stage1[1] == $past(stage1[0]))
    );

    // stage2[0] shifts in the previous stage1[1] value on an input change.
    check_stage2_shift0: assert property (
        @($global_clock)
        (!$initstate && ($changed(a) || $changed(b))) |-> (stage2[0] == $past(stage1[1]))
    );

    // stage2[1] shifts in the previous stage2[0] value on an input change.
    check_stage2_shift1: assert property (
        @($global_clock)
        (!$initstate && ($changed(a) || $changed(b))) |-> (stage2[1] == $past(stage2[0]))
    );

    // out_comb captures the previous stage2[1] value on an input change.
    check_output_shift: assert property (
        @($global_clock)
        (!$initstate && ($changed(a) || $changed(b))) |-> (out_comb == $past(stage2[1]))
    );

    // All pipeline state holds when neither input changes.
    check_state_holds_without_input_change: assert property (
        @($global_clock)
        (!$initstate && !$changed(a) && !$changed(b)) |-> ($stable(stage1) && $stable(stage2) && $stable(out_comb))
    );

    // out_comb can only change when an input changes.
    check_output_change_requires_input_change: assert property (
        @($global_clock)
        (!$initstate && $changed(out_comb)) |-> ($changed(a) || $changed(b))
    );

    // stage1 can only change when an input changes.
    check_stage1_change_requires_input_change: assert property (
        @($global_clock)
        (!$initstate && $changed(stage1)) |-> ($changed(a) || $changed(b))
    );

    // stage2 can only change when an input changes.
    check_stage2_change_requires_input_change: assert property (
        @($global_clock)
        (!$initstate && $changed(stage2)) |-> ($changed(a) || $changed(b))
    );

endmodule

bind xor_gate_pipeline xor_gate_pipeline_sva xor_gate_pipeline_sva_inst (
    .a(a),
    .b(b),
    .out_comb(out_comb),
    .stage1(stage1),
    .stage2(stage2)
);

rtl:
module axis_red_pitaya_adc #
(
  parameter integer ADC_DATA_WIDTH = 14,
  parameter integer AXIS_TDATA_WIDTH = 32
)
(
  input  wire                        aclk,

  output wire                        adc_csn,
  input  wire [ADC_DATA_WIDTH-1:0]   adc_dat_a,
  input  wire [ADC_DATA_WIDTH-1:0]   adc_dat_b,

  output wire                        m_axis_tvalid,
  output wire [AXIS_TDATA_WIDTH-1:0] m_axis_tdata
);
  localparam PADDING_WIDTH = AXIS_TDATA_WIDTH/2 - ADC_DATA_WIDTH;

  reg  [ADC_DATA_WIDTH-1:0] int_dat_a_reg;
  reg  [ADC_DATA_WIDTH-1:0] int_dat_b_reg;

  always @(posedge aclk)
  begin
    int_dat_a_reg <= adc_dat_a;
    int_dat_b_reg <= adc_dat_b;
  end

  assign adc_csn = 1'b1;

  assign m_axis_tvalid = 1'b1;

  assign m_axis_tdata = {
    {(PADDING_WIDTH+1){int_dat_b_reg[ADC_DATA_WIDTH-1]}}, ~int_dat_b_reg[ADC_DATA_WIDTH-2:0],
    {(PADDING_WIDTH+1){int_dat_a_reg[ADC_DATA_WIDTH-1]}}, ~int_dat_a_reg[ADC_DATA_WIDTH-2:0]};

endmodule

sva:
module axis_red_pitaya_adc_sva #(
    parameter integer ADC_DATA_WIDTH   = 14,
    parameter integer AXIS_TDATA_WIDTH = 32
) (
    input logic                        aclk,
    input logic                        adc_csn,
    input logic [ADC_DATA_WIDTH-1:0]   adc_dat_a,
    input logic [ADC_DATA_WIDTH-1:0]   adc_dat_b,
    input logic                        m_axis_tvalid,
    input logic [AXIS_TDATA_WIDTH-1:0] m_axis_tdata
);

    localparam integer PADDING_WIDTH = AXIS_TDATA_WIDTH/2 - ADC_DATA_WIDTH;
    localparam integer HALF_WIDTH    = AXIS_TDATA_WIDTH/2;

    // adc_csn is tied high.
    check_adc_csn_high: assert property (
        @(posedge aclk) adc_csn == 1'b1
    );

    // m_axis_tvalid is tied high.
    check_m_axis_tvalid_high: assert property (
        @(posedge aclk) m_axis_tvalid == 1'b1
    );

    // Upper AXIS half encodes the previous adc_dat_b sample.
    check_tdata_upper_half_from_prev_b: assert property (
        @(posedge aclk)
        !$initstate |-> m_axis_tdata[AXIS_TDATA_WIDTH-1:HALF_WIDTH] ==
                        {{(PADDING_WIDTH+1){$past(adc_dat_b[ADC_DATA_WIDTH-1])}},
                         ~($past(adc_dat_b[ADC_DATA_WIDTH-2:0]))}
    );

    // Lower AXIS half encodes the previous adc_dat_a sample.
    check_tdata_lower_half_from_prev_a: assert property (
        @(posedge aclk)
        !$initstate |-> m_axis_tdata[HALF_WIDTH-1:0] ==
                        {{(PADDING_WIDTH+1){$past(adc_dat_a[ADC_DATA_WIDTH-1])}},
                         ~($past(adc_dat_a[ADC_DATA_WIDTH-2:0]))}
    );

    // Upper sign bits replicate the previous adc_dat_b sign bit.
    check_upper_sign_extension_from_prev_b: assert property (
        @(posedge aclk)
        !$initstate |-> m_axis_tdata[AXIS_TDATA_WIDTH-1:HALF_WIDTH+ADC_DATA_WIDTH-1] ==
                        {(PADDING_WIDTH+1){$past(adc_dat_b[ADC_DATA_WIDTH-1])}}
    );

    // Upper payload bits invert the previous adc_dat_b lower bits.
    check_upper_payload_inverted_from_prev_b: assert property (
        @(posedge aclk)
        !$initstate |-> m_axis_tdata[HALF_WIDTH+ADC_DATA_WIDTH-2:HALF_WIDTH] ==
                        ~($past(adc_dat_b[ADC_DATA_WIDTH-2:0]))
    );

    // Lower sign bits replicate the previous adc_dat_a sign bit.
    check_lower_sign_extension_from_prev_a: assert property (
        @(posedge aclk)
        !$initstate |-> m_axis_tdata[HALF_WIDTH-1:ADC_DATA_WIDTH-1] ==
                        {(PADDING_WIDTH+1){$past(adc_dat_a[ADC_DATA_WIDTH-1])}}
    );

    // Lower payload bits invert the previous adc_dat_a lower bits.
    check_lower_payload_inverted_from_prev_a: assert property (
        @(posedge aclk)
        !$initstate |-> m_axis_tdata[ADC_DATA_WIDTH-2:0] ==
                        ~($past(adc_dat_a[ADC_DATA_WIDTH-2:0]))
    );

endmodule

