module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output reg out
);

    wire sel0_inv, sel1_inv;

    assign sel0_inv = ~sel[0];
    assign sel1_inv = ~sel[1];

    always @(*) begin
        if (sel == 2'b00) begin
            out = in[0];
        end else if (sel == 2'b01) begin
            out = in[1];
        end else if (sel == 2'b10) begin
            out = in[2];
        end else begin
            out = in[3];
        end
    end

endmodule

sva:
module mux4to1_sva (
    input logic [3:0] in,
    input logic [1:0] sel,
    input logic out
);

    // No RTL clock or reset; sample this combinational mux on the formal global clock.
    // Pure combinational 4:1 mux: sel selects which in bit drives out.

    // sel 00 routes in[0] to out.
    check_sel_00_routes_in0: assert property (
        @($global_clock) (sel === 2'b00) |-> (out === in[0])
    );

    // sel 01 routes in[1] to out.
    check_sel_01_routes_in1: assert property (
        @($global_clock) (sel === 2'b01) |-> (out === in[1])
    );

    // sel 10 routes in[2] to out.
    check_sel_10_routes_in2: assert property (
        @($global_clock) (sel === 2'b10) |-> (out === in[2])
    );

    // All remaining select values take the default in[3] branch.
    check_default_routes_in3: assert property (
        @($global_clock) (sel !== 2'b00 && sel !== 2'b01 && sel !== 2'b10) |-> (out === in[3])
    );

endmodule

module calculator_sva (
    input logic [7:0] A,
    input logic [7:0] B,
    input logic [1:0] op,
    input logic [7:0] result
);

    // Opcode 00 produces the 8-bit sum.
    check_addition_result: assert property (
        @($global_clock) (op == 2'b00) |-> (result == ((A + B) & 8'hFF))
    );

    // Opcode 01 produces the 8-bit difference.
    check_subtraction_result: assert property (
        @($global_clock) (op == 2'b01) |-> (result == ((A - B) & 8'hFF))
    );

    // Opcode 10 produces the low 8 bits of the product.
    check_multiplication_result: assert property (
        @($global_clock) (op == 2'b10) |-> (result == ((A * B) & 8'hFF))
    );

    // Opcode 11 with a nonzero divisor produces the quotient.
    check_division_result: assert property (
        @($global_clock) ((op == 2'b11) && (B != 8'h00)) |-> (result == (A / B))
    );

endmodule

