rtl:
module xor_module(
    input [3:0] a,
    input [3:0] b,
    output reg [3:0] out_comb_logic
);

always @* begin
    out_comb_logic = a ^ b;
end

endmodule

sva:
module xor_module_sva (
    input logic clk,
    input logic [3:0] a,
    input logic [3:0] b,
    input logic [3:0] out_comb_logic
);

    // Combinational DUT with no native reset; clk is the formal sampling clock.

    // Output vector matches the XOR of the two inputs.
    check_output_matches_xor: assert property (
        @(posedge clk) out_comb_logic == (a ^ b)
    );

    // Bit 0 of the output is a[0] XOR b[0].
    check_bit0_matches_xor: assert property (
        @(posedge clk) out_comb_logic[0] == (a[0] ^ b[0])
    );

    // Bit 1 of the output is a[1] XOR b[1].
    check_bit1_matches_xor: assert property (
        @(posedge clk) out_comb_logic[1] == (a[1] ^ b[1])
    );

    // Bit 2 of the output is a[2] XOR b[2].
    check_bit2_matches_xor: assert property (
        @(posedge clk) out_comb_logic[2] == (a[2] ^ b[2])
    );

    // Bit 3 of the output is a[3] XOR b[3].
    check_bit3_matches_xor: assert property (
        @(posedge clk) out_comb_logic[3] == (a[3] ^ b[3])
    );

    // Equal inputs produce a zero output.
    check_equal_inputs_zero: assert property (
        @(posedge clk) (a == b) |-> (out_comb_logic == 4'b0000)
    );

    // Zero on b passes a through to the output.
    check_b_zero_passes_a: assert property (
        @(posedge clk) (b == 4'b0000) |-> (out_comb_logic == a)
    );

    // Zero on a passes b through to the output.
    check_a_zero_passes_b: assert property (
        @(posedge clk) (a == 4'b0000) |-> (out_comb_logic == b)
    );

endmodule

module four_to_one_assertions (
    input logic clk,
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic Y
);

    // Y must match the RTL Boolean equation.
    check_output_equation: assert property (
        @(posedge clk) Y == (A && B && !C && !D)
    );

    // When A, B, !C, and !D are all true, Y must be high.
    check_y_high_on_match: assert property (
        @(posedge clk) (A && B && !C && !D) |-> Y
    );

    // When the required input combination is not present, Y must be low.
    check_y_low_off_match: assert property (
        @(posedge clk) !(A && B && !C && !D) |-> !Y
    );

endmodule

rtl:
module top_module (
    input   clk,
    input   [15:0] A,
    input   [15:0] B,
    input   [3:0] shift_amt,
    output  wire less_than,
    output  wire equal_to,
    output  wire greater_than,
    output  wire [15:0] shifted_A,
    output  wire [15:0] shifted_B,
    output  wire [15:0] final_output
);

    // Instantiate the magnitude comparator module
    magnitude_comparator mag_comp(
        .A(A),
        .B(B),
        .less_than(less_than),
        .equal_to(equal_to),
        .greater_than(greater_than)
    );

    // Instantiate the barrel shifter module for input A
    barrel_shifter bar_shifter_A(
        .data_in(A),
        .shift_amt(shift_amt),
        .data_out(shifted_A)
    );

    // Instantiate the barrel shifter module for input B
    barrel_shifter bar_shifter_B(
        .data_in(B),
        .shift_amt(shift_amt),
        .data_out(shifted_B)
    );

    // Instantiate the functional module for final output calculation
    final_output_calculator final_calc(
        .less_than(less_than),
        .equal_to(equal_to),
        .greater_than(greater_than),
        .shifted_A(shifted_A),
        .shifted_B(shifted_B),
        .final_output(final_output)
    );

endmodule
module magnitude_comparator (
    input   [15:0] A,
    input   [15:0] B,
    output  wire less_than,
    output  wire equal_to,
    output  wire greater_than
);

    wire    less_than_int;
    wire    equal_to_int;
    wire    greater_than_int;

    assign  less_than_int = (A < B);
    assign  equal_to_int = (A == B);
    assign  greater_than_int = (A > B);

    assign  less_than = less_than_int;
    assign  equal_to = equal_to_int;
    assign  greater_than = greater_than_int;

endmodule
module barrel_shifter (
    input   [15:0] data_in,
    input   [3:0] shift_amt,
    output  wire [15:0] data_out
);

    assign  data_out = (shift_amt == 4'b0000) ? data_in :
                        (shift_amt == 4'b0001) ? {data_in[14:0], 1'b0} :
                        (shift_amt == 4'b0010) ? {data_in[13:0], 2'b00} :
                        (shift_amt == 4'b0011) ? {data_in[12:0], 3'b000} :
                        (shift_amt == 4'b0100) ? {data_in[11:0], 4'b0000} :
                        (shift_amt == 4'b0101) ? {data_in[10:0], 5'b00000} :
                        (shift_amt == 4'b0110) ? {data_in[9:0], 6'b000000} :
                        (shift_amt == 4'b0111) ? {data_in[8:0], 7'b0000000} :
                        (shift_amt == 4'b1000) ? {data_in[7:0], 8'b00000000} :
                        (shift_amt == 4'b1001) ? {data_in[6:0], 9'b000000000} :
                        (shift_amt == 4'b1010) ? {data_in[5:0], 10'b0000000000} :
                        (shift_amt == 4'b1011) ? {data_in[4:0], 11'b00000000000} :
                        (shift_amt == 4'b1100) ? {data_in[3:0], 12'b000000000000} :
                        (shift_amt == 4'b1101) ? {data_in[2:0], 13'b0000000000000} :
                        (shift_amt == 4'b1110) ? {data_in[1:0], 14'b00000000000000} :
                                                {data_in[0], 15'b000000000000000};

endmodule
module final_output_calculator (
    input   wire less_than,
    input   wire equal_to,
    input   wire greater_than,
    input   wire [15:0] shifted_A,
    input   wire [15:0] shifted_B,
    output  wire [15:0] final_output
);

    assign  final_output = (less_than) ? (shifted_A - shifted_B) :
                            (equal_to) ? shifted_A :
                            (greater_than) ? (shifted_A + shifted_B) : 16'b0;

endmodule

sva:
module top_module_sva (
    input  logic        clk,
    input  logic [15:0] A,
    input  logic [15:0] B,
    input  logic [3:0]  shift_amt,
    input  logic        less_than,
    input  logic        equal_to,
    input  logic        greater_than,
    input  logic [15:0] shifted_A,
    input  logic [15:0] shifted_B,
    input  logic [15:0] final_output
);

    // less_than reflects the unsigned A < B comparison.
    check_less_than_definition: assert property (
        @(posedge clk) less_than == (A < B)
    );

    // equal_to reflects the A == B comparison.
    check_equal_to_definition: assert property (
        @(posedge clk) equal_to == (A == B)
    );

    // greater_than reflects the unsigned A > B comparison.
    check_greater_than_definition: assert property (
        @(posedge clk) greater_than == (A > B)
    );

    // Exactly one comparator result is asserted each cycle.
    check_comparator_onehot: assert property (
        @(posedge clk) $onehot({less_than, equal_to, greater_than})
    );

    // shifted_A is A logically shifted left by shift_amt.
    check_shifted_a_definition: assert property (
        @(posedge clk) shifted_A == (A << shift_amt)
    );

    // shifted_B is B logically shifted left by shift_amt.
    check_shifted_b_definition: assert property (
        @(posedge clk) shifted_B == (B << shift_amt)
    );

    // In the less-than case, final_output is shifted_A minus shifted_B.
    check_final_output_less_case: assert property (
        @(posedge clk) less_than |-> (final_output == (shifted_A - shifted_B))
    );

    // In the equality case, final_output passes through shifted_A.
    check_final_output_equal_case: assert property (
        @(posedge clk) equal_to |-> (final_output == shifted_A)
    );

    // In the greater-than case, final_output is shifted_A plus shifted_B.
    check_final_output_greater_case: assert property (
        @(posedge clk) greater_than |-> (final_output == (shifted_A + shifted_B))
    );

    // final_output matches the full top-level combinational definition.
    check_final_output_full_definition: assert property (
        @(posedge clk)
        final_output ==
            ((A < B)  ? ((A << shift_amt) - (B << shift_amt)) :
             ((A == B) ?  (A << shift_amt) :
             ((A > B)  ? ((A << shift_amt) + (B << shift_amt)) : 16'b0)))
    );

endmodule

module binary_counter_sva (
    input logic clk,
    input logic reset,
    input logic load,
    input logic [3:0] target,
    input logic [3:0] count,
    input logic equal
);

    // After a non-reset load cycle, count takes the previous target value.
    check_load_updates_count: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        $past(!reset && load) |-> (count == $past(target))
    );

    // Without reset or load, count increments from non-maximum values.
    check_increments_from_nonmax: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        ($past(!reset && !load) && ($past(count) != 4'hF)) |-> (count == ($past(count) + 4'd1))
    );

    // Without reset or load, count wraps from 4'hF to 4'h0.
    check_wraps_after_max: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        ($past(!reset && !load) && ($past(count) == 4'hF)) |-> (count == 4'h0)
    );

    // On the first non-reset cycle after reset, count is zero.
    check_reset_release_clears_count: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        $past(reset) |-> (count == 4'h0)
    );

    // equal is high when count matches target.
    check_equal_high_on_match: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        (count == target) |-> (equal == 1'b1)
    );

    // equal is low when count differs from target.
    check_equal_low_on_mismatch: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        (count != target) |-> (equal == 1'b0)
    );

endmodule

rtl:
module full_adder (
  input a,
  input b,
  input cin,
  output sum,
  output cout
);

  assign sum = a ^ b ^ cin;
  assign cout = (a & b) | (a & cin) | (b & cin);

endmodule
module ripple_carry_adder (
  input [3:0] A,
  input [3:0] B,
  input cin,
  output [3:0] sum,
  output cout
);

  wire [3:0] carry;
  full_adder FA0(A[0], B[0], cin, sum[0], carry[0]);
  full_adder FA1(A[1], B[1], carry[0], sum[1], carry[1]);
  full_adder FA2(A[2], B[2], carry[1], sum[2], carry[2]);
  full_adder FA3(A[3], B[3], carry[2], sum[3], cout);

endmodule

sva:
module ripple_carry_adder_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic cin,
    input logic [3:0] sum,
    input logic cout
);

    function automatic logic fa_carry(input logic x, input logic y, input logic z);
        fa_carry = (x & y) | (x & z) | (y & z);
    endfunction

    // Sum bit 0 is the XOR of the least-significant inputs and carry-in.
    check_sum_bit0: assert property (
        @(posedge clk) sum[0] == (A[0] ^ B[0] ^ cin)
    );

    // Sum bit 1 uses the carry generated by bit 0.
    check_sum_bit1: assert property (
        @(posedge clk) sum[1] == (A[1] ^ B[1] ^ fa_carry(A[0], B[0], cin))
    );

    // Sum bit 2 uses the carry propagated through bits 0 and 1.
    check_sum_bit2: assert property (
        @(posedge clk) sum[2] == (A[2] ^ B[2] ^ fa_carry(A[1], B[1], fa_carry(A[0], B[0], cin)))
    );

    // Sum bit 3 uses the carry propagated through bits 0 to 2.
    check_sum_bit3: assert property (
        @(posedge clk) sum[3] == (A[3] ^ B[3] ^ fa_carry(A[2], B[2], fa_carry(A[1], B[1], fa_carry(A[0], B[0], cin))))
    );

    // Carry-out is the final carry generated by the most-significant stage.
    check_cout: assert property (
        @(posedge clk) cout == fa_carry(A[3], B[3], fa_carry(A[2], B[2], fa_carry(A[1], B[1], fa_carry(A[0], B[0], cin))))
    );

    // The concatenated outputs match a 5-bit addition of the inputs and carry-in.
    check_total_result: assert property (
        @(posedge clk) {cout, sum} == ({1'b0, A} + {1'b0, B} + cin)
    );

endmodule

rtl:
module clkdlybuf4s (
    input CLK, RST,
    output reg CLK_OUT
);

    parameter DELAY_CYCLES = 4;
    reg [DELAY_CYCLES-1:0] delay_reg;
    integer i;

    always @(posedge CLK or posedge RST) begin
        if (RST) begin
            CLK_OUT <= 0;
            delay_reg <= 0;
        end else begin
            delay_reg[0] <= CLK;
            for (i = 1; i < DELAY_CYCLES; i = i+1) begin
                delay_reg[i] <= delay_reg[i-1];
            end
            CLK_OUT <= delay_reg[DELAY_CYCLES-1];
        end
    end

endmodule

sva:
module clkdlybuf4s_sva #(
    parameter int DELAY_CYCLES = 4
) (
    input logic CLK,
    input logic RST,
    input logic CLK_OUT
);

    // A sampled reset cycle forces CLK_OUT low by the next clock.
    check_reset_forces_low_on_next_clock: assert property (
        @(posedge CLK) disable iff ($initstate)
        RST |=> !CLK_OUT
    );

    // After reset release, the first active clock still sees CLK_OUT low.
    check_clk_out_low_on_first_clock_after_reset_release: assert property (
        @(posedge CLK) disable iff (RST || $initstate)
        $fell(RST) |-> !CLK_OUT
    );

    // After reset release, CLK_OUT stays low for DELAY_CYCLES+1 sampled clocks.
    check_clk_out_low_for_delay_after_reset_release: assert property (
        @(posedge CLK) disable iff (RST || $initstate)
        $fell(RST) |-> (!CLK_OUT)[* (DELAY_CYCLES+1)]
    );

    // After that delay, CLK_OUT rises and remains high on the following clock.
    check_clk_out_rises_and_sticks_after_delay: assert property (
        @(posedge CLK) disable iff (RST || $initstate)
        $fell(RST) |-> ((!CLK_OUT)[* (DELAY_CYCLES+1)] ##1 $rose(CLK_OUT) ##1 CLK_OUT)
    );

endmodule

module greater_of_two_assertions (
    input logic       clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] G
);

    // If A is greater than B, G must equal A.
    check_select_a_when_a_gt_b: assert property (
        @(posedge clk) (A > B) |-> (G == A)
    );

    // If A is less than or equal to B, G must equal B.
    check_select_b_when_a_le_b: assert property (
        @(posedge clk) (A <= B) |-> (G == B)
    );

    // G must never be smaller than A.
    check_g_not_less_than_a: assert property (
        @(posedge clk) (G >= A)
    );

    // G must never be smaller than B.
    check_g_not_less_than_b: assert property (
        @(posedge clk) (G >= B)
    );

    // G must always match one of the two inputs.
    check_g_matches_one_input: assert property (
        @(posedge clk) ((G == A) || (G == B))
    );

    // If A and B are equal, G must equal that shared value.
    check_equal_inputs_return_that_value: assert property (
        @(posedge clk) (A == B) |-> (G == A)
    );

endmodule

rtl:
module combinational_circuit (
    input A1,
    input A2,
    input A3,
    input B1,
    input B2,
    output X
);

    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    assign X = (A1 == 1'b1) ? B1 : ((A2 == 1'b1) && (A3 == 1'b0)) ? B2 : B1;

endmodule

sva:
module combinational_circuit_sva (
    input logic clk,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic B1,
    input logic B2,
    input logic X
);

    // X must always match the RTL mux expression.
    check_output_matches_rtl_expression: assert property (
        @(posedge clk)
        X === ((A1 == 1'b1) ? B1 : (((A2 == 1'b1) && (A3 == 1'b0)) ? B2 : B1))
    );

    // A1 high selects B1 regardless of A2 and A3.
    check_a1_selects_b1: assert property (
        @(posedge clk)
        (A1 === 1'b1) |-> (X === B1)
    );

    // With A1 low, A2 high, and A3 low, X selects B2.
    check_secondary_condition_selects_b2: assert property (
        @(posedge clk)
        ((A1 === 1'b0) && (A2 === 1'b1) && (A3 === 1'b0)) |-> (X === B2)
    );

    // With A1 low and the secondary condition false, X selects B1.
    check_default_path_selects_b1: assert property (
        @(posedge clk)
        ((A1 === 1'b0) && ((A2 === 1'b0) || (A3 === 1'b1))) |-> (X === B1)
    );

    // A1 has priority over the secondary select condition.
    check_a1_priority_over_secondary_path: assert property (
        @(posedge clk)
        ((A1 === 1'b1) && (A2 === 1'b1) && (A3 === 1'b0)) |-> (X === B1)
    );

endmodule

rtl:
module and_or_xor_adder (
    input [7:0] in1,
    input [7:0] in2,
    output reg [7:0] out
);

    // Step 1: Compute the bitwise AND of in1 and in2
    wire [7:0] and_result = in1 & in2;

    // Step 2: Compute the bitwise OR of in1 and in2
    wire [7:0] or_result = in1 | in2;

    // Step 3: Add the results of step 1 and step 2
    wire [8:0] add_result = and_result + or_result;

    // Step 4: Compute the bitwise XOR of the results of step 1 and step 2
    wire [7:0] xor_result = and_result ^ or_result;

    // Step 5: Add 1 to the result of step 4
    wire [7:0] add_one = 1;
    wire [7:0] add_one_result = xor_result + add_one;

    // Step 6: Assign the result of step 5 to out
    always @(*) begin
        out = add_one_result;
    end

endmodule

sva:
module and_or_xor_adder_sva (
    input logic       clk,
    input logic [7:0] in1,
    input logic [7:0] in2,
    input logic [7:0] out
);

    // RTL is combinational; clk is only used to sample assertions.
    // The RTL has no reset.

    // out must equal the XOR of the AND/OR intermediates plus one.
    check_output_equation: assert property (
        @(posedge clk) out == (((in1 & in2) ^ (in1 | in2)) + 8'h01)
    );

    // Equal inputs make the XOR term zero, so out must be one.
    check_equal_inputs_result_one: assert property (
        @(posedge clk) (in1 == in2) |-> (out == 8'h01)
    );

    // If in1 is zero, the logic reduces to in2 plus one.
    check_zero_in1_behavior: assert property (
        @(posedge clk) (in1 == 8'h00) |-> (out == (in2 + 8'h01))
    );

    // If in2 is zero, the logic reduces to in1 plus one.
    check_zero_in2_behavior: assert property (
        @(posedge clk) (in2 == 8'h00) |-> (out == (in1 + 8'h01))
    );

    // Complementary inputs produce 8'hFF before increment, so out wraps to zero.
    check_complementary_inputs_wrap: assert property (
        @(posedge clk) (in1 == ~in2) |-> (out == 8'h00)
    );

endmodule

rtl:
module full_adder (A, B, Ci, S, Co);
  input A, B, Ci;
  output S, Co;
  wire n1, n2, n3, n4, n5, n6, n7, n8, n9, n10, n11;

  assign n11 = ~(A ^ B);
  assign S = ~(Ci ^ n11);
  assign n10 = ~(A & B & Ci);
  assign n9 = ~(A & B);
  assign Co = ~(n10 & n9);
  assign n1 = ~(Ci & n11);
  assign n2 = ~(B & n11);
  assign n3 = ~(A & Ci);
  assign n4 = ~(n1 & n2);
  assign n5 = ~(n3 & n9);
  assign n6 = ~(n3 & n2);
  assign n7 = ~(n1 & n9);
  assign n8 = ~(n6 & n7);
endmodule

sva:
module full_adder_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic Ci,
    input logic S,
    input logic Co
);

    // Combinational DUT sampled on clk; no reset is present in the RTL.

    // Sum output implements three-input XOR.
    check_sum_matches_three_input_xor: assert property (
        @(posedge clk) S == (A ^ B ^ Ci)
    );

    // Carry output is asserted only by A and B both being high.
    check_carry_matches_ab_and: assert property (
        @(posedge clk) Co == (A & B)
    );

    // With Ci low, sum reduces to A xor B.
    check_sum_when_cin_low: assert property (
        @(posedge clk) (!Ci) |-> (S == (A ^ B))
    );

    // With Ci high, sum is the inversion of A xor B.
    check_sum_when_cin_high: assert property (
        @(posedge clk) Ci |-> (S == ~(A ^ B))
    );

    // When A and B are equal, sum follows Ci.
    check_sum_tracks_cin_when_ab_equal: assert property (
        @(posedge clk) (A == B) |-> (S == Ci)
    );

    // When A and B differ, sum is the inverse of Ci.
    check_sum_inverts_cin_when_ab_different: assert property (
        @(posedge clk) (A != B) |-> (S == ~Ci)
    );

    // Carry must be high whenever both A and B are high.
    check_carry_high_when_ab_high: assert property (
        @(posedge clk) (A && B) |-> Co
    );

    // Carry must be low whenever either A or B is low.
    check_carry_low_when_either_operand_low: assert property (
        @(posedge clk) ((!A) || (!B)) |-> (!Co)
    );

endmodule

rtl:
module mux_4to1 (
    input in0,
    input in1,
    input in2,
    input in3,
    input sel1,
    input sel0,
    output reg out
);

    wire not_sel1;
    wire not_sel0;
    wire and1;
    wire and2;
    wire and3;
    wire and4;
    wire or1;

    // Invert select wires
    assign not_sel1 = ~sel1;
    assign not_sel0 = ~sel0;

    // AND gates to create all possible combinations
    assign and1 = in0 & not_sel1 & not_sel0;
    assign and2 = in1 & not_sel1 & sel0;
    assign and3 = in2 & sel1 & not_sel0;
    assign and4 = in3 & sel1 & sel0;

    // OR gates to combine the AND gates
    assign or1 = and1 | and2 | and3 | and4;

    // Output
    always @* begin
        out = or1;
    end

endmodule

sva:
module mux_4to1_sva (
    input logic clk,
    input logic in0,
    input logic in1,
    input logic in2,
    input logic in3,
    input logic sel1,
    input logic sel0,
    input logic out
);

    // Output matches the RTL sum-of-products implementation.
    check_mux_sum_of_products: assert property (
        @(posedge clk)
        out == ((in0 & ~sel1 & ~sel0) |
                (in1 & ~sel1 &  sel0) |
                (in2 &  sel1 & ~sel0) |
                (in3 &  sel1 &  sel0))
    );

    // Select 00 routes in0 to the output.
    check_select_00_routes_in0: assert property (
        @(posedge clk)
        (!sel1 && !sel0) |-> (out == in0)
    );

    // Select 01 routes in1 to the output.
    check_select_01_routes_in1: assert property (
        @(posedge clk)
        (!sel1 && sel0) |-> (out == in1)
    );

    // Select 10 routes in2 to the output.
    check_select_10_routes_in2: assert property (
        @(posedge clk)
        (sel1 && !sel0) |-> (out == in2)
    );

    // Select 11 routes in3 to the output.
    check_select_11_routes_in3: assert property (
        @(posedge clk)
        (sel1 && sel0) |-> (out == in3)
    );

    // If all inputs and selects are stable, the output remains stable.
    check_stable_inputs_keep_output_stable: assert property (
        @(posedge clk)
        (!$initstate && $stable({in0, in1, in2, in3, sel1, sel0})) |-> $stable(out)
    );

endmodule

