rtl:
module four_bit_adder (A, B, Cin, S, Cout);

  input [3:0] A, B;
  input Cin;
  output [3:0] S;
  output Cout;

  wire [3:0] C;

  // Instantiate full-adder modules
  full_adder FA0(.A(A[0]), .B(B[0]), .Cin(Cin), .S(S[0]), .Cout(C[0]));
  full_adder FA1(.A(A[1]), .B(B[1]), .Cin(C[0]), .S(S[1]), .Cout(C[1]));
  full_adder FA2(.A(A[2]), .B(B[2]), .Cin(C[1]), .S(S[2]), .Cout(C[2]));
  full_adder FA3(.A(A[3]), .B(B[3]), .Cin(C[2]), .S(S[3]), .Cout(Cout));

endmodule

module full_adder (A, B, Cin, S, Cout);

  input A, B, Cin;
  output S, Cout;

  assign S = A ^ B ^ Cin;
  assign Cout = (A & B) | (Cin & (A ^ B));

endmodule

sva:
module four_bit_adder_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic Cin,
    input logic [3:0] S,
    input logic Cout
);

    // The concatenated output matches 4-bit addition with carry-in.
    check_total_addition: assert property (
        @(posedge clk) {Cout, S} == ({1'b0, A} + {1'b0, B} + Cin)
    );

    // Sum bit 0 is the XOR of the LSB inputs and carry-in.
    check_lsb_sum: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0] ^ Cin)
    );

    // Sum bit 1 uses the carry generated by bit 0.
    check_bit1_sum_from_carry0: assert property (
        @(posedge clk)
        S[1] == (A[1] ^ B[1] ^ ((A[0] & B[0]) | (Cin & (A[0] ^ B[0]))))
    );

    // Sum bit 2 uses the carry generated by bit 1.
    check_bit2_sum_from_carry1: assert property (
        @(posedge clk)
        S[2] == (A[2] ^ B[2] ^
                 ((A[1] & B[1]) |
                  (((A[0] & B[0]) | (Cin & (A[0] ^ B[0]))) &
                   (A[1] ^ B[1]))))
    );

    // Sum bit 3 uses the carry generated by bit 2.
    check_bit3_sum_from_carry2: assert property (
        @(posedge clk)
        S[3] == (A[3] ^ B[3] ^
                 ((A[2] & B[2]) |
                  (((A[1] & B[1]) |
                    (((A[0] & B[0]) | (Cin & (A[0] ^ B[0]))) &
                     (A[1] ^ B[1]))) &
                   (A[2] ^ B[2]))))
    );

    // Carry-out is the final carry from the ripple-carry chain.
    check_final_carry: assert property (
        @(posedge clk)
        Cout == ((A[3] & B[3]) |
                 (((A[2] & B[2]) |
                   (((A[1] & B[1]) |
                     (((A[0] & B[0]) | (Cin & (A[0] ^ B[0]))) &
                      (A[1] ^ B[1]))) &
                    (A[2] ^ B[2]))) &
                  (A[3] ^ B[3])))
    );

endmodule

rtl:
module sky130_fd_sc_ms__fa (
    input A,
    input B,
    input CIN,
    input VPWR,
    input VGND,
    input VPB,
    input VNB,
    output COUT,
    output SUM
);

    // Implementing full adder using behavioral modeling
    assign SUM = A ^ B ^ CIN;
    assign COUT = (A & B) | (B & CIN) | (A & CIN);

endmodule

sva:
module sky130_fd_sc_ms__fa_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic CIN,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB,
    input logic COUT,
    input logic SUM
);

    // SUM must equal the XOR of the three inputs.
    check_sum_equation: assert property (
        @(posedge clk) SUM == (A ^ B ^ CIN)
    );

    // COUT must equal the full-adder carry equation.
    check_cout_equation: assert property (
        @(posedge clk) COUT == ((A & B) | (B & CIN) | (A & CIN))
    );

    // All-zero inputs must produce zero sum and zero carry.
    check_all_zero_case: assert property (
        @(posedge clk) (!A && !B && !CIN) |-> (!SUM && !COUT)
    );

    // All-one inputs must produce sum one and carry one.
    check_all_one_case: assert property (
        @(posedge clk) (A && B && CIN) |-> (SUM && COUT)
    );

    // Exactly one high input must produce sum one and carry zero.
    check_one_hot_input_case: assert property (
        @(posedge clk)
        ((A && !B && !CIN) || (!A && B && !CIN) || (!A && !B && CIN))
        |-> (SUM && !COUT)
    );

    // Exactly two high inputs must produce sum zero and carry one.
    check_two_hot_input_case: assert property (
        @(posedge clk)
        ((A && B && !CIN) || (A && !B && CIN) || (!A && B && CIN))
        |-> (!SUM && COUT)
    );

    // When A and B are both high, carry must be asserted.
    check_ab_generates_carry: assert property (
        @(posedge clk) (A && B) |-> COUT
    );

    // When B and CIN are both high, carry must be asserted.
    check_bcin_generates_carry: assert property (
        @(posedge clk) (B && CIN) |-> COUT
    );

    // When A and CIN are both high, carry must be asserted.
    check_acin_generates_carry: assert property (
        @(posedge clk) (A && CIN) |-> COUT
    );

endmodule

module mux2to1_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic sel,
    input logic out,
    input logic VPB,
    input logic VPWR,
    input logic VGND,
    input logic VNB
);

    // When sel is low, out passes A.
    check_selects_a_when_sel_low: assert property (
        @(posedge clk) (sel === 1'b0) |-> (out === A)
    );

    // When sel is high, out passes B.
    check_selects_b_when_sel_high: assert property (
        @(posedge clk) (sel === 1'b1) |-> (out === B)
    );

    // A rising sel switches the output to B.
    check_sel_rise_switches_to_b: assert property (
        @(posedge clk) $rose(sel) |-> (out === B)
    );

    // A falling sel switches the output to A.
    check_sel_fall_switches_to_a: assert property (
        @(posedge clk) $fell(sel) |-> (out === A)
    );

    // A change on unselected B does not affect out when sel stays low.
    check_unselected_b_has_no_effect: assert property (
        @(posedge clk) (sel === 1'b0 && $stable(sel) && $stable(A) && $changed(B)) |-> $stable(out)
    );

    // A change on unselected A does not affect out when sel stays high.
    check_unselected_a_has_no_effect: assert property (
        @(posedge clk) (sel === 1'b1 && $stable(sel) && $stable(B) && $changed(A)) |-> $stable(out)
    );

    // A change on selected A is reflected at out when sel stays low.
    check_selected_a_change_reaches_out: assert property (
        @(posedge clk) (sel === 1'b0 && $stable(sel) && $changed(A)) |-> $changed(out)
    );

    // A change on selected B is reflected at out when sel stays high.
    check_selected_b_change_reaches_out: assert property (
        @(posedge clk) (sel === 1'b1 && $stable(sel) && $changed(B)) |-> $changed(out)
    );

    // Stable mux inputs keep the output stable.
    check_stable_inputs_keep_output_stable: assert property (
        @(posedge clk) $stable({A, B, sel}) |-> $stable(out)
    );

    // Supply-pin changes alone do not affect the RTL output.
    check_supply_pins_do_not_affect_output: assert property (
        @(posedge clk) ($stable({A, B, sel}) && $changed({VPB, VPWR, VGND, VNB})) |-> $stable(out)
    );

endmodule

rtl:
module three_input_op (
    output reg Y,
    input A,
    input B,
    input C,
    input [1:0] op,
    input sel
);

    reg [2:0] input_signals;
    reg [1:0] selected_signals;
    reg [2:0] and_results;
    reg [2:0] or_results;
    reg [2:0] xor_results;
    reg [2:0] xnor_results;

    // Assign the input signals based on the sel signal
    always @* begin
        case (sel)
            0: begin
                input_signals[0] = A;
                input_signals[1] = B;
                input_signals[2] = B;
            end
            1: begin
                input_signals[0] = B;
                input_signals[1] = B;
                input_signals[2] = C;
            end
        endcase
    end

    // Perform the AND operation on the input signals
    always @* begin
        and_results[0] = input_signals[0] & input_signals[1];
        and_results[1] = input_signals[1] & input_signals[2];
        and_results[2] = input_signals[2] & input_signals[0];
    end

    // Perform the OR operation on the input signals
    always @* begin
        or_results[0] = input_signals[0] | input_signals[1];
        or_results[1] = input_signals[1] | input_signals[2];
        or_results[2] = input_signals[2] | input_signals[0];
    end

    // Perform the XOR operation on the input signals
    always @* begin
        xor_results[0] = input_signals[0] ^ input_signals[1];
        xor_results[1] = input_signals[1] ^ input_signals[2];
        xor_results[2] = input_signals[2] ^ input_signals[0];
    end

    // Perform the XNOR operation on the input signals
    always @* begin
        xnor_results[0] = ~(input_signals[0] ^ input_signals[1]);
        xnor_results[1] = ~(input_signals[1] ^ input_signals[2]);
        xnor_results[2] = ~(input_signals[2] ^ input_signals[0]);
    end

    // Determine which two input signals to use based on the sel signal
    always @* begin
        selected_signals = (sel == 0) ? 2'b00 : 2'b10;
    end

    // Perform the operation based on the op signal
    always @* begin
        case (op)
            2'b00: Y = and_results[selected_signals];
            2'b01: Y = or_results[selected_signals];
            2'b10: Y = xor_results[selected_signals];
            2'b11: Y = xnor_results[selected_signals];
            default: Y = 1'b0;
        endcase
    end

endmodule

sva:
module three_input_op_sva (
    input logic Y,
    input logic A,
    input logic B,
    input logic C,
    input logic [1:0] op,
    input logic sel,
    input logic [2:0] input_signals,
    input logic [1:0] selected_signals,
    input logic [2:0] and_results,
    input logic [2:0] or_results,
    input logic [2:0] xor_results,
    input logic [2:0] xnor_results
);

    // sel=0 drives input_signals[0]=A, [1]=B, [2]=B.
    check_input_map_sel0: assert property (
        @($global_clock) (sel == 1'b0) |-> (input_signals == {B, B, A})
    );

    // sel=1 drives input_signals[0]=B, [1]=B, [2]=C.
    check_input_map_sel1: assert property (
        @($global_clock) (sel == 1'b1) |-> (input_signals == {C, B, B})
    );

    // sel=0 selects result index 0.
    check_selected_signals_sel0: assert property (
        @($global_clock) (sel == 1'b0) |-> (selected_signals == 2'b00)
    );

    // sel=1 selects result index 2.
    check_selected_signals_sel1: assert property (
        @($global_clock) (sel == 1'b1) |-> (selected_signals == 2'b10)
    );

    // and_results holds the three pairwise AND terms.
    check_and_results: assert property (
        @($global_clock)
        (and_results == {
            (input_signals[2] & input_signals[0]),
            (input_signals[1] & input_signals[2]),
            (input_signals[0] & input_signals[1])
        })
    );

    // or_results holds the three pairwise OR terms.
    check_or_results: assert property (
        @($global_clock)
        (or_results == {
            (input_signals[2] | input_signals[0]),
            (input_signals[1] | input_signals[2]),
            (input_signals[0] | input_signals[1])
        })
    );

    // xor_results holds the three pairwise XOR terms.
    check_xor_results: assert property (
        @($global_clock)
        (xor_results == {
            (input_signals[2] ^ input_signals[0]),
            (input_signals[1] ^ input_signals[2]),
            (input_signals[0] ^ input_signals[1])
        })
    );

    // xnor_results holds the three pairwise XNOR terms.
    check_xnor_results: assert property (
        @($global_clock)
        (xnor_results == {
            ~(input_signals[2] ^ input_signals[0]),
            ~(input_signals[1] ^ input_signals[2]),
            ~(input_signals[0] ^ input_signals[1])
        })
    );

    // op=00 drives Y from the selected AND result.
    check_output_and: assert property (
        @($global_clock) (op == 2'b00) |-> (Y == and_results[selected_signals])
    );

    // op=01 drives Y from the selected OR result.
    check_output_or: assert property (
        @($global_clock) (op == 2'b01) |-> (Y == or_results[selected_signals])
    );

    // op=10 drives Y from the selected XOR result.
    check_output_xor: assert property (
        @($global_clock) (op == 2'b10) |-> (Y == xor_results[selected_signals])
    );

    // op=11 drives Y from the selected XNOR result.
    check_output_xnor: assert property (
        @($global_clock) (op == 2'b11) |-> (Y == xnor_results[selected_signals])
    );

endmodule

module dff_en_sr_sva (
    input logic CLK,
    input logic D,
    input logic EN,
    input logic SET,
    input logic RESET,
    input logic Q,
    input logic Q_bar
);

    // Q_bar is always the inverse of Q.
    check_qbar_complement: assert property (
        @(posedge CLK) disable iff (1'b0)
        1'b1 |-> (Q_bar == ~Q)
    );

    // When enabled, SET drives the set state and overrides RESET.
    check_set_path: assert property (
        @(posedge CLK) disable iff (1'b0)
        (EN && SET) |=> (Q == 1'b1 && Q_bar == 1'b0)
    );

    // When enabled and SET is low, RESET drives the reset state.
    check_reset_path: assert property (
        @(posedge CLK) disable iff (1'b0)
        (EN && !SET && RESET) |=> (Q == 1'b0 && Q_bar == 1'b1)
    );

    // When enabled with no set/reset, the flop captures D.
    check_data_capture_path: assert property (
        @(posedge CLK) disable iff (1'b0)
        (EN && !SET && !RESET) |=> (Q == $past(D) && Q_bar == (~$past(D)))
    );

    // When not enabled, both outputs hold their previous values.
    check_hold_when_disabled: assert property (
        @(posedge CLK) disable iff (1'b0)
        (!EN) |=> ($stable(Q) && $stable(Q_bar))
    );

endmodule

rtl:
module three_input_module (
    input input_a,
    input input_b,
    input input_c,
    output output_y
);

    wire a_and_b = input_a & input_b;
    wire a_and_c = input_a & input_c;
    wire b_and_c = input_b & input_c;
    wire a_or_b_or_c = input_a | input_b | input_c;

    assign output_y = (a_or_b_or_c && !b_and_c) || (input_a && !a_and_b && !a_and_c) || (input_b && !a_and_b && !b_and_c) || (input_c && !a_and_c && !b_and_c);

endmodule

sva:
module three_input_module_sva (
    input logic clk,
    input logic input_a,
    input logic input_b,
    input logic input_c,
    input logic output_y
);

    // Output matches the implemented combinational equation.
    check_output_matches_rtl: assert property (
        @(posedge clk)
        output_y == (((input_a | input_b | input_c) && !(input_b & input_c)) ||
                     (input_a && !(input_a & input_b) && !(input_a & input_c)) ||
                     (input_b && !(input_a & input_b) && !(input_b & input_c)) ||
                     (input_c && !(input_a & input_c) && !(input_b & input_c)))
    );

    // Output is LOW when all inputs are LOW.
    check_all_inputs_low: assert property (
        @(posedge clk)
        (!input_a && !input_b && !input_c) |-> !output_y
    );

    // Output is HIGH when input_a is HIGH and input_b/input_c are not both HIGH.
    check_input_a_without_bc_pair: assert property (
        @(posedge clk)
        (input_a && !(input_b && input_c)) |-> output_y
    );

    // Output is HIGH when input_a is LOW and exactly one of input_b/input_c is HIGH.
    check_exactly_one_of_b_or_c_without_a: assert property (
        @(posedge clk)
        (!input_a && ((input_b && !input_c) || (!input_b && input_c))) |-> output_y
    );

    // Output is LOW whenever input_b and input_c are both HIGH.
    check_b_and_c_force_low: assert property (
        @(posedge clk)
        (input_b && input_c) |-> !output_y
    );

endmodule

module my_module_sva (
    input logic clk,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic A4,
    input logic B1,
    input logic X
);

    // When both input pairs compare equal, X follows B1.
    check_true_branch_selects_b1: assert property (
        @(posedge clk) (((A1 == A2) && (A3 == A4)) === 1'b1) |-> (X == B1)
    );

    // When either input pair does not compare equal, X follows A1 & A2.
    check_false_branch_selects_a1_a2_and: assert property (
        @(posedge clk) (((A1 == A2) && (A3 == A4)) !== 1'b1) |-> (X == (A1 & A2))
    );

    // In the AND branch, a low A1 forces X low.
    check_false_branch_a1_low_forces_zero: assert property (
        @(posedge clk) ((((A1 == A2) && (A3 == A4)) !== 1'b1) && (A1 == 1'b0)) |-> (X == 1'b0)
    );

    // In the AND branch, a low A2 forces X low.
    check_false_branch_a2_low_forces_zero: assert property (
        @(posedge clk) ((((A1 == A2) && (A3 == A4)) !== 1'b1) && (A2 == 1'b0)) |-> (X == 1'b0)
    );

    // In the AND branch, high A1 and A2 drive X high.
    check_false_branch_both_high_drive_one: assert property (
        @(posedge clk) ((((A1 == A2) && (A3 == A4)) !== 1'b1) && (A1 == 1'b1) && (A2 == 1'b1)) |-> (X == 1'b1)
    );

endmodule

rtl:
module ripple_carry_adder #(parameter WIDTH = 4) (input [WIDTH-1:0] A, input [WIDTH-1:0] B, input CI, output [WIDTH-1:0] S, output CO);

    wire [WIDTH:0] C;
    assign C[0] = CI;

    genvar i;
    generate
        for (i = 0; i < WIDTH; i = i + 1) begin:adder
            full_adder FA(
                .A(A[i]),
                .B(B[i]),
                .CI(C[i]),
                .S(S[i]),
                .CO(C[i+1])
            );
        end
    endgenerate

    assign CO = C[WIDTH];

endmodule

module full_adder (input A, input B, input CI, output S, output CO);

    assign S = A ^ B ^ CI;
    assign CO = (A & B) | (CI & (A ^ B));

endmodule

sva:
module ripple_carry_adder_sva #(parameter int WIDTH = 4) (
    input logic clk,
    input logic [WIDTH-1:0] A,
    input logic [WIDTH-1:0] B,
    input logic CI,
    input logic [WIDTH-1:0] S,
    input logic CO
);

    genvar i;
    generate
        for (i = 0; i < WIDTH; i = i + 1) begin : gen_prefix_checks
            // Lower sum bits match addition of the corresponding input slices.
            check_prefix_sum: assert property (
                @(posedge clk) S[i:0] == (A[i:0] + B[i:0] + CI)
            );
        end

        if (WIDTH > 0) begin : gen_lsb_checks
            // The least-significant sum bit matches the full-adder XOR function.
            check_lsb_sum: assert property (
                @(posedge clk) S[0] == (A[0] ^ B[0] ^ CI)
            );
        end

        if (WIDTH == 1) begin : gen_single_bit_checks
            // In the 1-bit case, carry-out matches the full-adder carry function.
            check_single_bit_carry: assert property (
                @(posedge clk) CO == ((A[0] & B[0]) | (CI & (A[0] ^ B[0])))
            );
        end
    endgenerate

    // The concatenated outputs equal the full WIDTH+1-bit sum.
    check_full_sum: assert property (
        @(posedge clk) {CO, S} == ({1'b0, A} + {1'b0, B} + CI)
    );

    // Zero inputs produce zero outputs.
    check_zero_inputs: assert property (
        @(posedge clk) (A == {WIDTH{1'b0}} && B == {WIDTH{1'b0}} && CI == 1'b0) |-> (S == {WIDTH{1'b0}} && CO == 1'b0)
    );

    // Adding zero with no carry-in passes A through unchanged.
    check_pass_a_through: assert property (
        @(posedge clk) (B == {WIDTH{1'b0}} && CI == 1'b0) |-> (S == A && CO == 1'b0)
    );

    // Adding zero with no carry-in passes B through unchanged.
    check_pass_b_through: assert property (
        @(posedge clk) (A == {WIDTH{1'b0}} && CI == 1'b0) |-> (S == B && CO == 1'b0)
    );

    // Carry-in increments an all-ones operand and raises carry-out.
    check_all_ones_plus_carry_in: assert property (
        @(posedge clk) (A == {WIDTH{1'b1}} && B == {WIDTH{1'b0}} && CI == 1'b1) |-> (S == {WIDTH{1'b0}} && CO == 1'b1)
    );

endmodule

rtl:
module majority_3 (
    input A,
    input B,
    input C,
    output X
);

    wire AB, AC, BC;

    assign AB = A & B;
    assign AC = A & C;
    assign BC = B & C;

    assign X = (AB | AC | BC);

endmodule

sva:
module majority_3_assertions (
    input logic clk,
    input logic A,
    input logic B,
    input logic C,
    input logic X
);

    // X must equal the majority-of-three function.
    check_output_matches_majority: assert property (
        @(posedge clk) X == ((A & B) | (A & C) | (B & C))
    );

    // A and B high together must drive X high.
    check_ab_pair_sets_x: assert property (
        @(posedge clk) (A & B) |-> X
    );

    // A and C high together must drive X high.
    check_ac_pair_sets_x: assert property (
        @(posedge clk) (A & C) |-> X
    );

    // B and C high together must drive X high.
    check_bc_pair_sets_x: assert property (
        @(posedge clk) (B & C) |-> X
    );

    // With no input pair high, X must be low.
    check_no_pair_clears_x: assert property (
        @(posedge clk) (!(A & B) && !(A & C) && !(B & C)) |-> !X
    );

    // A high X requires at least one input pair to be high.
    check_x_requires_two_high_inputs: assert property (
        @(posedge clk) X |-> ((A & B) | (A & C) | (B & C))
    );

endmodule

module barrel_shifter_sva (
    input logic       clk,
    input logic [3:0] data_in,
    input logic [1:0] shift_amount,
    input logic       mode,
    input logic [3:0] data_out
);

    // mode=0 selects the reachable left-shift case item.
    check_mode0_left_shift: assert property (
        @(posedge clk)
        (mode === 1'b0) |-> (data_out === (data_in << shift_amount))
    );

    // mode=1 selects the reachable right-shift case item.
    check_mode1_right_shift: assert property (
        @(posedge clk)
        (mode === 1'b1) |-> (data_out === (data_in >> shift_amount))
    );

    // mode=0 with shift_amount=0 leaves the input unchanged.
    check_left_shift_0: assert property (
        @(posedge clk)
        (mode === 1'b0 && shift_amount === 2'd0) |-> (data_out === data_in)
    );

    // mode=0 with shift_amount=1 shifts left by one bit.
    check_left_shift_1: assert property (
        @(posedge clk)
        (mode === 1'b0 && shift_amount === 2'd1) |-> (data_out === {data_in[2:0], 1'b0})
    );

    // mode=0 with shift_amount=2 shifts left by two bits.
    check_left_shift_2: assert property (
        @(posedge clk)
        (mode === 1'b0 && shift_amount === 2'd2) |-> (data_out === {data_in[1:0], 2'b00})
    );

    // mode=0 with shift_amount=3 shifts left by three bits.
    check_left_shift_3: assert property (
        @(posedge clk)
        (mode === 1'b0 && shift_amount === 2'd3) |-> (data_out === {data_in[0], 3'b000})
    );

    // mode=1 with shift_amount=0 leaves the input unchanged.
    check_right_shift_0: assert property (
        @(posedge clk)
        (mode === 1'b1 && shift_amount === 2'd0) |-> (data_out === data_in)
    );

    // mode=1 with shift_amount=1 shifts right by one bit.
    check_right_shift_1: assert property (
        @(posedge clk)
        (mode === 1'b1 && shift_amount === 2'd1) |-> (data_out === {1'b0, data_in[3:1]})
    );

    // mode=1 with shift_amount=2 shifts right by two bits.
    check_right_shift_2: assert property (
        @(posedge clk)
        (mode === 1'b1 && shift_amount === 2'd2) |-> (data_out === {2'b00, data_in[3:2]})
    );

    // mode=1 with shift_amount=3 shifts right by three bits.
    check_right_shift_3: assert property (
        @(posedge clk)
        (mode === 1'b1 && shift_amount === 2'd3) |-> (data_out === {3'b000, data_in[3]})
    );

endmodule

rtl:
module dff_asynchronous_set_reset(clk, rst, set, d, q, qn);

input clk, rst, set, d;
output q, qn;
reg q;

always @(posedge clk or negedge rst) begin
    if (~rst)
        q <= 1'b0;
    else if (~set)
        q <= 1'b1;
    else
        q <= d;
end

assign qn = ~q;

endmodule

sva:
module dff_asynchronous_set_reset_sva (
    input logic clk,
    input logic rst,
    input logic set,
    input logic d,
    input logic q,
    input logic qn
);

    // qn complements q during normal operation.
    check_qn_complements_q: assert property (
        @(posedge clk) disable iff (!rst) (qn == ~q)
    );

    // Active-low reset forces q low.
    check_reset_forces_q_low: assert property (
        @(posedge clk) (!rst) |-> (q == 1'b0)
    );

    // Active-low reset forces qn high.
    check_reset_forces_qn_high: assert property (
        @(posedge clk) (!rst) |-> (qn == 1'b1)
    );

    // q remains low on the first clock after reset was active.
    check_post_reset_q_stays_low: assert property (
        @(posedge clk) disable iff (!rst) (!$initstate && $past(!rst)) |-> (q == 1'b0)
    );

    // qn remains high on the first clock after reset was active.
    check_post_reset_qn_stays_high: assert property (
        @(posedge clk) disable iff (!rst) (!$initstate && $past(!rst)) |-> (qn == 1'b1)
    );

endmodule

rtl:
module sky130_fd_sc_ls__nor4bb (
    Y  ,
    A  ,
    B  ,
    C_N,
    D_N
);

    output Y  ;
    input  A  ;
    input  B  ;
    input  C_N;
    input  D_N;

    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    wire nor0_out  ;
    wire and0_out_Y;

    nor nor0 (nor0_out  , A, B              );
    and and0 (and0_out_Y, nor0_out, C_N, D_N);
    buf buf0 (Y         , and0_out_Y        );

endmodule

sva:
module sky130_fd_sc_ls__nor4bb_sva (
    input logic Y,
    input logic A,
    input logic B,
    input logic C_N,
    input logic D_N
);

    // Y must match the implemented NOR followed by AND function.
    check_y_function: assert property (
        @($global_clock) Y === ((~(A | B)) & C_N & D_N)
    );

    // A high forces the NOR output low, so Y must be low.
    check_a_high_forces_y_low: assert property (
        @($global_clock) (A === 1'b1) |-> (Y === 1'b0)
    );

    // B high forces the NOR output low, so Y must be low.
    check_b_high_forces_y_low: assert property (
        @($global_clock) (B === 1'b1) |-> (Y === 1'b0)
    );

    // C_N low blocks the final AND, so Y must be low.
    check_cn_low_forces_y_low: assert property (
        @($global_clock) (C_N === 1'b0) |-> (Y === 1'b0)
    );

    // D_N low blocks the final AND, so Y must be low.
    check_dn_low_forces_y_low: assert property (
        @($global_clock) (D_N === 1'b0) |-> (Y === 1'b0)
    );

    // The only high-output input combination must drive Y high.
    check_all_conditions_true_drive_y_high: assert property (
        @($global_clock)
        ((A === 1'b0) && (B === 1'b0) && (C_N === 1'b1) && (D_N === 1'b1)) |-> (Y === 1'b1)
    );

    // If Y is high, all required input conditions must be present.
    check_y_high_implies_required_inputs: assert property (
        @($global_clock)
        (Y === 1'b1) |-> ((A === 1'b0) && (B === 1'b0) && (C_N === 1'b1) && (D_N === 1'b1))
    );

    // With A and B low, Y reduces to C_N AND D_N.
    check_ab_low_reduces_to_cn_and_dn: assert property (
        @($global_clock)
        ((A === 1'b0) && (B === 1'b0)) |-> (Y === (C_N & D_N))
    );

    // With C_N and D_N high, Y reduces to NOR(A,B).
    check_cn_dn_high_reduces_to_nor_ab: assert property (
        @($global_clock)
        ((C_N === 1'b1) && (D_N === 1'b1)) |-> (Y === ~(A | B))
    );

endmodule

rtl:
module up_down_counter (
    input clk,
    input async_reset,
    input [1:0] enable,
    output reg [1:0] count
);

    always @(posedge clk or negedge async_reset) begin
        if (!async_reset) begin
            count <= 2'b00;
        end else begin
            case (enable)
                2'b00: count <= count;
                2'b01: count <= count + 2'b01;
                2'b10: count <= count - 2'b01;
                default: count <= count;
            endcase
        end
    end

endmodule

sva:
module up_down_counter_sva (
    input logic clk,
    input logic async_reset,
    input logic [1:0] enable,
    input logic [1:0] count
);

    // Low reset forces count to zero.
    check_reset_low_clears_count: assert property (
        @(posedge clk) !async_reset |-> (count == 2'b00)
    );

    // First clock after reset release starts from zero.
    check_reset_release_starts_from_zero: assert property (
        @(posedge clk) ($past(!async_reset) && async_reset) |-> (count == 2'b00)
    );

    // Enable 00 holds the count value.
    check_hold_on_enable_00: assert property (
        @(posedge clk) disable iff (!async_reset)
        (enable == 2'b00) |=> (count == $past(count))
    );

    // Enable 01 increments the count by one.
    check_increment_on_enable_01: assert property (
        @(posedge clk) disable iff (!async_reset)
        (enable == 2'b01) |=> (count == ($past(count) + 2'b01))
    );

    // Enable 10 decrements the count by one.
    check_decrement_on_enable_10: assert property (
        @(posedge clk) disable iff (!async_reset)
        (enable == 2'b10) |=> (count == ($past(count) - 2'b01))
    );

    // Enable 11 follows the default hold behavior.
    check_hold_on_enable_11: assert property (
        @(posedge clk) disable iff (!async_reset)
        (enable == 2'b11) |=> (count == $past(count))
    );

endmodule

rtl:
module and_or_gate(
    input a,
    input b,
    input c,
    output reg out
);

    always @ (a, b, c) begin
        out = (a & b) | c;
    end

endmodule

sva:
module and_or_gate_sva(
    input logic a,
    input logic b,
    input logic c,
    input logic out
);

    // Output always implements (a & b) | c.
    check_out_matches_function: assert property (
        @($global_clock) out == ((a & b) | c)
    );

    // When c is high, the output must be high.
    check_c_high_forces_out_high: assert property (
        @($global_clock) c |-> out
    );

    // When both a and b are high, the output must be high.
    check_a_and_b_high_force_out_high: assert property (
        @($global_clock) (a && b) |-> out
    );

    // With c low and a low, the output must be low.
    check_c_low_and_a_low_force_out_low: assert property (
        @($global_clock) (!c && !a) |-> !out
    );

    // With c low and b low, the output must be low.
    check_c_low_and_b_low_force_out_low: assert property (
        @($global_clock) (!c && !b) |-> !out
    );

endmodule

rtl:
module binary_up_counter (input clk, input reset, output reg [3:0] count);

	always @(posedge clk) begin
		if (reset) begin
			count <= 4'd0;
		end else begin
			count <= count + 1;
		end
	end

endmodule

sva:
module binary_up_counter_assertions (
    input logic       clk,
    input logic       reset,
    input logic [3:0] count
);

    // Clock: clk
    // Reset: reset, active high synchronous
    // Logic: sequential 4-bit binary up counter

    // While reset stays asserted across clocks, the observed count remains zero.
    check_zero_while_reset_held: assert property (
        @(posedge clk) disable iff ($initstate)
        (reset && $past(reset)) |-> (count == 4'd0)
    );

    // On the first cycle after reset was asserted, the observed count is zero.
    check_zero_after_reset_release: assert property (
        @(posedge clk) disable iff ($initstate)
        (!reset && $past(reset)) |-> (count == 4'd0)
    );

    // After any non-reset cycle, the counter increments by one modulo 16.
    check_count_increments_after_non_reset_cycle: assert property (
        @(posedge clk) disable iff ($initstate)
        !$past(reset) |-> (count == ($past(count) + 4'd1))
    );

    // A previous count of 15 wraps to 0 on the next observed cycle.
    check_wraps_from_f_to_0: assert property (
        @(posedge clk) disable iff ($initstate)
        (!$past(reset) && ($past(count) == 4'hF)) |-> (count == 4'h0)
    );

endmodule

rtl:
module regSR #(
    parameter INIT = 1'bX,
    parameter SRMODE = 1'b0
) (
    input D,
    input CLK,
    input RST,
    output reg Q
);

    always @(posedge CLK or posedge RST) begin
        if (RST) begin
            Q <= INIT;
        end else if (SRMODE) begin
            Q <= ~Q;
        end else begin
            Q <= D;
        end
    end

endmodule

sva:
module regSR_sva #(
    parameter INIT   = 1'bX,
    parameter SRMODE = 1'b0
) (
    input logic D,
    input logic CLK,
    input logic RST,
    input logic Q
);

    localparam bit INIT_KNOWN  = ((INIT === 1'b0) || (INIT === 1'b1));
    localparam bit DATA_MODE   = (SRMODE === 1'b0);
    localparam bit TOGGLE_MODE = (SRMODE === 1'b1);

    // Reset pulses must remain asserted until a clock edge.
    env_reset_pulse_visible_at_clk: assume property (
        @(posedge RST) 1'b1 |=> @(posedge CLK) RST
    );

    generate
        if (INIT_KNOWN) begin : gen_known_init
            // After a sampled reset cycle, Q is held at INIT at the next clock sample.
            check_reset_forces_init: assert property (
                @(posedge CLK) $past(RST) |-> (Q === INIT)
            );
        end
    endgenerate

    generate
        if (DATA_MODE) begin : gen_data_mode
            // In data mode, each non-reset clock loads the previous sampled D into Q.
            check_data_mode_captures_d: assert property (
                @(posedge CLK) disable iff (RST) !$past(RST) |-> (Q === $past(D))
            );
        end
        else if (TOGGLE_MODE) begin : gen_toggle_mode
            // In toggle mode, each non-reset clock inverts Q.
            check_toggle_mode_toggles_q: assert property (
                @(posedge CLK) disable iff (RST) !$past(RST) |-> (Q === ~$past(Q))
            );
        end
    endgenerate

endmodule

rtl:
module one_bit_adder(
    input xi,
    input yi,
    output Si,
    output Co
);

    assign Si = xi ^ yi;
    assign Co = xi & yi;

endmodule

sva:
module one_bit_adder_sva (
    input logic xi,
    input logic yi,
    input logic Si,
    input logic Co
);

    // Sum output must be the XOR of the two inputs.
    check_sum_matches_xor: assert property (
        @($global_clock) Si === (xi ^ yi)
    );

    // Carry output must be the AND of the two inputs.
    check_carry_matches_and: assert property (
        @($global_clock) Co === (xi & yi)
    );

    // Combined outputs must match 1-bit addition.
    check_outputs_match_addition: assert property (
        @($global_clock) {Co, Si} === ({1'b0, xi} + {1'b0, yi})
    );

    // Both low inputs must produce zero sum and zero carry.
    check_zero_plus_zero: assert property (
        @($global_clock) ((xi === 1'b0) && (yi === 1'b0)) |-> ((Si === 1'b0) && (Co === 1'b0))
    );

    // Mixed inputs must produce sum one and carry zero.
    check_mixed_inputs: assert property (
        @($global_clock) (((xi === 1'b0) && (yi === 1'b1)) || ((xi === 1'b1) && (yi === 1'b0)))
        |-> ((Si === 1'b1) && (Co === 1'b0))
    );

    // Both high inputs must produce sum zero and carry one.
    check_one_plus_one: assert property (
        @($global_clock) ((xi === 1'b1) && (yi === 1'b1)) |-> ((Si === 1'b0) && (Co === 1'b1))
    );

endmodule

rtl:
module calculator(input [3:0] a, input [3:0] b, input [1:0] op, output [3:0] add_out, output [3:0] sub_out, output [3:0] mul_out, output [3:0] div_out);

  wire [7:0] prod;

  assign add_out = a + b;
  assign sub_out = a - b;
  assign prod = a * b;
  assign mul_out = prod[7:4];
  assign div_out = (b == 4'h0) ? 4'h0 : a / b;

endmodule

sva:
module calculator_sva (
    input logic        clk,
    input logic [3:0]  a,
    input logic [3:0]  b,
    input logic [1:0]  op,
    input logic [3:0]  add_out,
    input logic [3:0]  sub_out,
    input logic [3:0]  mul_out,
    input logic [3:0]  div_out
);

    // add_out always equals the 4-bit sum of a and b.
    check_add_matches_sum: assert property (
        @(posedge clk) add_out == (a + b)
    );

    // sub_out always equals the 4-bit difference of a and b.
    check_sub_matches_difference: assert property (
        @(posedge clk) sub_out == (a - b)
    );

    // mul_out is the upper nibble of the 8-bit product of a and b.
    check_mul_matches_upper_product_nibble: assert property (
        @(posedge clk) mul_out == ((a * b) >> 4)
    );

    // div_out is zero whenever b is zero.
    check_div_zero_returns_zero: assert property (
        @(posedge clk) (b == 4'h0) |-> (div_out == 4'h0)
    );

    // div_out equals a divided by b whenever b is nonzero.
    check_div_nonzero_matches_quotient: assert property (
        @(posedge clk) (b != 4'h0) |-> (div_out == (a / b))
    );

    // Outputs remain stable when a and b remain stable.
    check_outputs_stable_when_operands_stable: assert property (
        @(posedge clk) (!$initstate && $stable(a) && $stable(b)) |-> $stable({add_out, sub_out, mul_out, div_out})
    );

    // Changing op alone does not affect any output.
    check_op_change_has_no_effect: assert property (
        @(posedge clk) (!$initstate && $stable(a) && $stable(b) && !$stable(op)) |-> $stable({add_out, sub_out, mul_out, div_out})
    );

endmodule

rtl:
module multiply_subtract(input [31:0] data_in, output [31:0] data_out);
    wire [31:0] mul_out;
    wire [31:0] sub_out;

    assign mul_out = data_in * 5;
    assign sub_out = mul_out - 7;

    assign data_out = sub_out;
endmodule

sva:
module multiply_subtract_assertions (
    input logic        clk,
    input logic [31:0] data_in,
    input logic [31:0] data_out
);

    // RTL has no clock or reset; clk is used only to sample combinational behavior.

    // Output matches multiply-by-5 followed by subtract-7 modulo 2^32.
    check_functional_relation: assert property (
        @(posedge clk) data_out == (((data_in << 2) + data_in) - 32'd7)
    );

    // A stable input across samples must produce a stable output.
    check_stable_input_gives_stable_output: assert property (
        @(posedge clk) $stable(data_in) |-> $stable(data_out)
    );

    // Zero input produces -7 modulo 2^32.
    check_zero_input_case: assert property (
        @(posedge clk) (data_in == 32'd0) |-> (data_out == 32'hFFFF_FFF9)
    );

    // One input produces -2 modulo 2^32.
    check_one_input_case: assert property (
        @(posedge clk) (data_in == 32'd1) |-> (data_out == 32'hFFFF_FFFE)
    );

    // All-ones input produces 0xFFFF_FFF4 modulo 2^32.
    check_all_ones_input_case: assert property (
        @(posedge clk) (data_in == 32'hFFFF_FFFF) |-> (data_out == 32'hFFFF_FFF4)
    );

endmodule

rtl:
module mux_2_1_en(
    input in0,
    input in1,
    input en,
    output reg out
);

always @(*) begin
    out = en ? in1 : in0;
end

endmodule

sva:
module mux_2_1_en_assertions(
    input logic in0,
    input logic in1,
    input logic en,
    input logic out
);

    // Output always matches the mux select function.
    check_mux_function: assert property (
        @($global_clock) out == (en ? in1 : in0)
    );

    // When en is high, output follows in1.
    check_select_in1: assert property (
        @($global_clock) en |-> (out == in1)
    );

    // When en is low, output follows in0.
    check_select_in0: assert property (
        @($global_clock) !en |-> (out == in0)
    );

    // If both inputs are equal, output matches that common value.
    check_equal_inputs: assert property (
        @($global_clock) (in0 == in1) |-> (out == in0)
    );

endmodule

rtl:
module nor_and (
    Y  ,
    A  ,
    B  ,
    C_N,
    D_N
);

    // Module ports
    output Y  ;
    input  A  ;
    input  B  ;
    input  C_N;
    input  D_N;

    // Local signals
    wire nor0_out  ;
    wire and0_out_Y;

    //  Name  Output      Other arguments
    nor nor0 (nor0_out  , A, B              );
    and and0 (and0_out_Y, C_N, D_N          );
    buf buf0 (Y         , nor0_out & and0_out_Y);

endmodule

sva:
module nor_and_sva (
    input logic Y,
    input logic A,
    input logic B,
    input logic C_N,
    input logic D_N
);

    // Y must match the implemented NOR-then-AND logic.
    check_output_matches_gate_function: assert property (
        @($global_clock) Y == ((~(A | B)) & C_N & D_N)
    );

    // A high forces the NOR term low, so Y must be low.
    check_a_high_forces_y_low: assert property (
        @($global_clock) A |-> !Y
    );

    // B high forces the NOR term low, so Y must be low.
    check_b_high_forces_y_low: assert property (
        @($global_clock) B |-> !Y
    );

    // C_N low clears the AND term, so Y must be low.
    check_c_n_low_forces_y_low: assert property (
        @($global_clock) !C_N |-> !Y
    );

    // D_N low clears the AND term, so Y must be low.
    check_d_n_low_forces_y_low: assert property (
        @($global_clock) !D_N |-> !Y
    );

    // When all enabling inputs are asserted, Y must be high.
    check_all_enabling_inputs_drive_y_high: assert property (
        @($global_clock) (!A && !B && C_N && D_N) |-> Y
    );

    // A high Y requires both NOR inputs low and both AND inputs high.
    check_y_high_requires_all_terms_true: assert property (
        @($global_clock) Y |-> (!A && !B && C_N && D_N)
    );

    // With A and B low, Y reduces to C_N AND D_N.
    check_ab_low_reduces_to_cd_and: assert property (
        @($global_clock) (!A && !B) |-> (Y == (C_N & D_N))
    );

    // With C_N and D_N high, Y reduces to NOR(A,B).
    check_cd_high_reduces_to_ab_nor: assert property (
        @($global_clock) (C_N && D_N) |-> (Y == (~(A | B)))
    );

endmodule

rtl:
module register_adder_clock_gate (
  input CLK,
  input EN,
  input TE,
  output ENCLK
);

  reg gated_clk;

  always @(posedge CLK) begin
    if (EN && !TE) begin
      gated_clk <= 1'b1;
    end else begin
      gated_clk <= 1'b0;
    end
  end

  assign ENCLK = gated_clk & CLK;

endmodule

sva:
module register_adder_clock_gate_assertions (
    input logic CLK,
    input logic EN,
    input logic TE,
    input logic ENCLK
);

    // A high pulse appears on the next high phase when EN is high and TE is low.
    check_pulse_when_enabled: assert property (
        @(posedge CLK) (EN && !TE) |=> @(negedge CLK) (ENCLK == 1'b1)
    );

    // No high pulse appears on the next high phase when the gate condition is false.
    check_no_pulse_when_blocked: assert property (
        @(posedge CLK) (!(EN && !TE)) |=> @(negedge CLK) (ENCLK == 1'b0)
    );

    // TE overrides EN and suppresses the gated clock pulse.
    check_test_enable_overrides_enable: assert property (
        @(posedge CLK) (EN && TE) |=> @(negedge CLK) (ENCLK == 1'b0)
    );

    // ENCLK is low at every sampled rising edge.
    check_enclk_low_on_rising_edge: assert property (
        @(posedge CLK) (ENCLK == 1'b0)
    );

endmodule

rtl:
module two_bit_counter (
    input CLK,
    input RST,
    output reg Q1,
    output reg Q0
);

always @(posedge CLK) begin
    if (RST) begin
        Q1 <= 0;
        Q0 <= 0;
    end else if (Q1 == 1 && Q0 == 1) begin
        Q1 <= 0;
        Q0 <= 0;
    end else if (Q0 == 1) begin
        Q1 <= 1;
        Q0 <= 0;
    end else begin
        Q1 <= 0;
        Q0 <= 1;
    end
end

endmodule

sva:
module two_bit_counter_assertions (
    input logic CLK,
    input logic RST,
    input logic Q1,
    input logic Q0
);

    // Synchronous reset clears the counter to 00 on the next clock.
    check_reset_clears_to_zero: assert property (
        @(posedge CLK) RST |=> ((Q1 == 1'b0) && (Q0 == 1'b0))
    );

    // State 00 advances to 01 when reset is not asserted.
    check_state_00_to_01: assert property (
        @(posedge CLK) disable iff (RST)
        ((Q1 == 1'b0) && (Q0 == 1'b0)) |=> ((Q1 == 1'b0) && (Q0 == 1'b1))
    );

    // State 01 advances to 10 when reset is not asserted.
    check_state_01_to_10: assert property (
        @(posedge CLK) disable iff (RST)
        ((Q1 == 1'b0) && (Q0 == 1'b1)) |=> ((Q1 == 1'b1) && (Q0 == 1'b0))
    );

    // State 10 advances to 01 when reset is not asserted.
    check_state_10_to_01: assert property (
        @(posedge CLK) disable iff (RST)
        ((Q1 == 1'b1) && (Q0 == 1'b0)) |=> ((Q1 == 1'b0) && (Q0 == 1'b1))
    );

    // State 11 is forced back to 00 on the next clock.
    check_state_11_to_00: assert property (
        @(posedge CLK) disable iff (RST)
        ((Q1 == 1'b1) && (Q0 == 1'b1)) |=> ((Q1 == 1'b0) && (Q0 == 1'b0))
    );

    // The next sampled state is never 11 outside of reset.
    check_next_state_not_11: assert property (
        @(posedge CLK) disable iff (RST)
        1'b1 |=> !((Q1 == 1'b1) && (Q0 == 1'b1))
    );

endmodule

module shift_register_4bit_sva (
    input logic [3:0] A,
    input logic       LOAD,
    input logic       CLK,
    input logic [3:0] Q
);

    // A high LOAD transfers A into Q on the next sampled cycle.
    check_load_captures_a: assert property (
        @(posedge CLK) LOAD |=> (Q == $past(A))
    );

    // A low LOAD causes Q to retain its previous value.
    check_hold_when_load_low: assert property (
        @(posedge CLK) !LOAD |=> (Q == $past(Q))
    );

    // Q follows the prior cycle's LOAD-controlled update rule.
    check_q_transition_rule: assert property (
        @(posedge CLK) 1'b1 |=> ($past(LOAD) ? (Q == $past(A)) : (Q == $past(Q)))
    );

endmodule

rtl:
module byte_reversal(
    input [31:0] in,
    output [31:0] out
    );
    assign out = {in[7:0], in[15:8], in[23:16], in[31:24]};
endmodule
module adder(
    input [31:0] in1,
    input [31:0] in2,
    output [31:0] out
    );
    assign out = in1 + in2;
endmodule
module top_module( 
    input [255:0] in,
    input [7:0] sel,
    output [31:0] out );

    wire [31:0] byte_reversal_out;
    wire [31:0] selected_input;
    wire [31:0] mux_inputs [7:0];

    genvar i;
    wire [7:0] decoder_out;

    assign decoder_out = {8{~sel}};

    for (i = 0; i < 8; i = i + 1) begin
        assign mux_inputs[i] = in[i * 32 +: 32];
    end

    assign selected_input = mux_inputs[decoder_out];

    // Byte reversal
    byte_reversal byte_reversal_inst(
        .in(selected_input),
        .out(byte_reversal_out)
        );

    // Adder
    adder adder_inst(
        .in1(selected_input),
        .in2(byte_reversal_out),
        .out(out)
        );

endmodule

sva:
module top_module_sva(
    input logic         clk,
    input logic [255:0] in,
    input logic [7:0]   sel,
    input logic [31:0]  out
);

    function automatic logic [31:0] byte_reverse32(input logic [31:0] data);
        byte_reverse32 = {data[7:0], data[15:8], data[23:16], data[31:24]};
    endfunction

    // sel=8'hFF selects in[31:0], reverses its bytes, and adds the two values.
    check_sel_ff_selects_word0: assert property (
        @(posedge clk) (sel == 8'hFF) |-> (out == (in[31:0] + byte_reverse32(in[31:0])))
    );

    // sel=8'hFE selects in[63:32], reverses its bytes, and adds the two values.
    check_sel_fe_selects_word1: assert property (
        @(posedge clk) (sel == 8'hFE) |-> (out == (in[63:32] + byte_reverse32(in[63:32])))
    );

    // sel=8'hFD selects in[95:64], reverses its bytes, and adds the two values.
    check_sel_fd_selects_word2: assert property (
        @(posedge clk) (sel == 8'hFD) |-> (out == (in[95:64] + byte_reverse32(in[95:64])))
    );

    // sel=8'hFC selects in[127:96], reverses its bytes, and adds the two values.
    check_sel_fc_selects_word3: assert property (
        @(posedge clk) (sel == 8'hFC) |-> (out == (in[127:96] + byte_reverse32(in[127:96])))
    );

    // sel=8'hFB selects in[159:128], reverses its bytes, and adds the two values.
    check_sel_fb_selects_word4: assert property (
        @(posedge clk) (sel == 8'hFB) |-> (out == (in[159:128] + byte_reverse32(in[159:128])))
    );

    // sel=8'hFA selects in[191:160], reverses its bytes, and adds the two values.
    check_sel_fa_selects_word5: assert property (
        @(posedge clk) (sel == 8'hFA) |-> (out == (in[191:160] + byte_reverse32(in[191:160])))
    );

    // sel=8'hF9 selects in[223:192], reverses its bytes, and adds the two values.
    check_sel_f9_selects_word6: assert property (
        @(posedge clk) (sel == 8'hF9) |-> (out == (in[223:192] + byte_reverse32(in[223:192])))
    );

    // sel=8'hF8 selects in[255:224], reverses its bytes, and adds the two values.
    check_sel_f8_selects_word7: assert property (
        @(posedge clk) (sel == 8'hF8) |-> (out == (in[255:224] + byte_reverse32(in[255:224])))
    );

    // With a valid selection held constant, out depends only on the selected 32-bit word.
    check_out_stable_for_stable_valid_selection: assert property (
        @(posedge clk)
        (
            ((sel == 8'hFF) && $stable(sel) && $stable(in[31:0]))     ||
            ((sel == 8'hFE) && $stable(sel) && $stable(in[63:32]))    ||
            ((sel == 8'hFD) && $stable(sel) && $stable(in[95:64]))    ||
            ((sel == 8'hFC) && $stable(sel) && $stable(in[127:96]))   ||
            ((sel == 8'hFB) && $stable(sel) && $stable(in[159:128]))  ||
            ((sel == 8'hFA) && $stable(sel) && $stable(in[191:160]))  ||
            ((sel == 8'hF9) && $stable(sel) && $stable(in[223:192]))  ||
            ((sel == 8'hF8) && $stable(sel) && $stable(in[255:224]))
        ) |-> $stable(out)
    );

endmodule

rtl:
module binary_adder (SUM, COUT, A, B, CIN);
input [3:0] A, B;
input CIN;
output [3:0] SUM;
output COUT;

wire [4:0] temp_sum;
wire carry;

assign temp_sum = A + B + CIN;

assign SUM = temp_sum[3:0];
assign COUT = temp_sum[4];

endmodule

sva:
module binary_adder_sva (
    input logic [3:0] SUM,
    input logic COUT,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic CIN,
    input logic clk
);

    // No reset in RTL; assertions are sampled on an external clock.

    // The concatenated outputs equal the 5-bit sum of A, B, and CIN.
    check_full_sum_function: assert property (
        @(posedge clk) {COUT, SUM} == ({1'b0, A} + {1'b0, B} + {4'b0, CIN})
    );

    // COUT is asserted exactly when the addition overflows 4 bits.
    check_cout_matches_overflow: assert property (
        @(posedge clk) COUT == (({1'b0, A} + {1'b0, B} + {4'b0, CIN}) >= 5'd16)
    );

    // With B and CIN low, the adder passes A through with no carry.
    check_a_passthrough_zero_addend: assert property (
        @(posedge clk) (B == 4'h0 && CIN == 1'b0) |-> (SUM == A && COUT == 1'b0)
    );

    // With A and CIN low, the adder passes B through with no carry.
    check_b_passthrough_zero_addend: assert property (
        @(posedge clk) (A == 4'h0 && CIN == 1'b0) |-> (SUM == B && COUT == 1'b0)
    );

    // All-zero inputs produce an all-zero result.
    check_zero_inputs_zero_outputs: assert property (
        @(posedge clk) (A == 4'h0 && B == 4'h0 && CIN == 1'b0) |-> (SUM == 4'h0 && COUT == 1'b0)
    );

    // A carry-in alone increments zero to one without overflow.
    check_cin_only_case: assert property (
        @(posedge clk) (A == 4'h0 && B == 4'h0 && CIN == 1'b1) |-> (SUM == 4'h1 && COUT == 1'b0)
    );

    // The maximum input combination produces 5'h1f.
    check_maximum_input_case: assert property (
        @(posedge clk) (A == 4'hf && B == 4'hf && CIN == 1'b1) |-> (SUM == 4'hf && COUT == 1'b1)
    );

endmodule

rtl:
module adder (
  input [3:0] A,
  input [3:0] B,
  output [3:0] sum
);

  assign sum = A + B;

endmodule

sva:
module adder_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] sum
);

    // sum must equal the 4-bit addition of A and B.
    check_sum_matches_addition: assert property (
        @($global_clock) sum == (A + B)
    );

    // Bit 0 must be the XOR of the input LSBs.
    check_sum_bit0: assert property (
        @($global_clock) sum[0] == (A[0] ^ B[0])
    );

    // Bit 1 must include the carry from bit 0.
    check_sum_bit1: assert property (
        @($global_clock) sum[1] == (A[1] ^ B[1] ^ (A[0] & B[0]))
    );

    // Bit 2 must include the carry from bit 1.
    check_sum_bit2: assert property (
        @($global_clock) sum[2] == (A[2] ^ B[2] ^
            ((A[1] & B[1]) | ((A[1] ^ B[1]) & (A[0] & B[0])))
        )
    );

    // Bit 3 must include the carry from bit 2.
    check_sum_bit3: assert property (
        @($global_clock) sum[3] == (A[3] ^ B[3] ^
            ((A[2] & B[2]) | ((A[2] ^ B[2]) &
            ((A[1] & B[1]) | ((A[1] ^ B[1]) & (A[0] & B[0])))))
        )
    );

    // Zero on A must pass B through to sum.
    check_zero_a_passthrough: assert property (
        @($global_clock) (A == 4'h0) |-> (sum == B)
    );

    // Zero on B must pass A through to sum.
    check_zero_b_passthrough: assert property (
        @($global_clock) (B == 4'h0) |-> (sum == A)
    );

endmodule

