module sky130_fd_sc_ms__o22ai (
    Y ,
    A1,
    A2,
    B1,
    B2
);

    output Y ;
    input  A1;
    input  A2;
    input  B1;
    input  B2;

    wire nor0_out ;
    wire nor1_out ;
    wire or0_out_Y;

    nor nor0 (nor0_out , B1, B2            );
    nor nor1 (nor1_out , A1, A2            );
    or  or0  (or0_out_Y, nor1_out, nor0_out);
    buf buf0 (Y        , or0_out_Y         );

endmodule

sva:
module sky130_fd_sc_ms__o22ai_sva (
    input logic clk,
    input logic Y,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic B2
);

    // Y matches the implemented O22AI combinational function.
    check_o22ai_function: assert property (
        @(posedge clk) Y === (~((A1 | A2) & (B1 | B2)))
    );

    // If one A input and one B input are high, Y must be low.
    check_low_when_both_input_groups_active: assert property (
        @(posedge clk) ((A1 | A2) & (B1 | B2)) |-> (Y === 1'b0)
    );

    // If both A inputs are low, Y must be high.
    check_high_when_a_group_inactive: assert property (
        @(posedge clk) ((~A1) & (~A2)) |-> (Y === 1'b1)
    );

    // If both B inputs are low, Y must be high.
    check_high_when_b_group_inactive: assert property (
        @(posedge clk) ((~B1) & (~B2)) |-> (Y === 1'b1)
    );

    // A low Y requires at least one A input to be high.
    check_low_output_requires_a_group_active: assert property (
        @(posedge clk) (Y === 1'b0) |-> (A1 | A2)
    );

    // A low Y requires at least one B input to be high.
    check_low_output_requires_b_group_active: assert property (
        @(posedge clk) (Y === 1'b0) |-> (B1 | B2)
    );

    // A high Y means at least one input group is entirely low.
    check_high_output_has_inactive_group: assert property (
        @(posedge clk) (Y === 1'b1) |-> (((~A1) & (~A2)) | ((~B1) & (~B2)))
    );

endmodule

module up_counter_assertions (
    input logic       clk,
    input logic       rst,
    input logic       en,
    input logic [3:0] count
);

    // When reset is asserted low, the counter is cleared.
    reset_clears_count: assert property (
        @(posedge clk)
        !rst |-> (count == 4'd0)
    );

    // When enabled outside reset, the counter increments by one.
    enable_increments_count: assert property (
        @(posedge clk) disable iff (!rst)
        en |=> (count == ($past(count) + 4'd1))
    );

    // When not enabled outside reset, the counter holds its value.
    disable_holds_count: assert property (
        @(posedge clk) disable iff (!rst)
        !en |=> (count == $past(count))
    );

endmodule

rtl:
module sky130_fd_sc_lp__nand4b (
    Y  ,
    A_N,
    B  ,
    C  ,
    D
);

    output Y  ;
    input  A_N;
    input  B  ;
    input  C  ;
    input  D  ;

    wire not0_out   ;
    wire nand0_out_Y;

    not  not0  (not0_out   , A_N              );
    nand nand0 (nand0_out_Y, D, C, B, not0_out);
    buf  buf0  (Y          , nand0_out_Y      );

endmodule

sva:
module sky130_fd_sc_lp__nand4b_sva (
    input logic clk,
    input logic Y,
    input logic A_N,
    input logic B,
    input logic C,
    input logic D
);

    // Y implements the RTL gate function.
    check_function_implemented: assert property (
        @(posedge clk) Y == ~(D & C & B & ~A_N)
    );

    // All active inputs drive the NAND output low.
    check_all_active_inputs_drive_low: assert property (
        @(posedge clk) (!A_N && B && C && D) |-> !Y
    );

    // A low output only occurs for the active input combination.
    check_low_output_only_when_all_active: assert property (
        @(posedge clk) !Y |-> (!A_N && B && C && D)
    );

    // With B, C, and D high, Y follows A_N.
    check_a_n_controls_output_when_bcd_high: assert property (
        @(posedge clk) (B && C && D) |-> (Y == A_N)
    );

    // With A_N low and C/D high, Y is the inverse of B.
    check_b_controls_output_when_a_ncd_active: assert property (
        @(posedge clk) (!A_N && C && D) |-> (Y == !B)
    );

    // With A_N low and B/D high, Y is the inverse of C.
    check_c_controls_output_when_a_nbd_active: assert property (
        @(posedge clk) (!A_N && B && D) |-> (Y == !C)
    );

    // With A_N low and B/C high, Y is the inverse of D.
    check_d_controls_output_when_a_nbc_active: assert property (
        @(posedge clk) (!A_N && B && C) |-> (Y == !D)
    );

    // A high output means at least one input is in its inactive state.
    check_high_output_has_valid_cause: assert property (
        @(posedge clk) Y |-> (A_N || !B || !C || !D)
    );

endmodule

rtl:
module xor_gate(
    input a,
    input b,
    output wire xor_out
);

assign xor_out = a ^ b;

endmodule

module functional_module(
    input xor_out,
    output reg func_out
);

always @(*) begin
    if(xor_out == 1'b1) begin
        func_out = 1'b1;
    end else begin
        func_out = 1'b0;
    end
end

endmodule

module control_logic(
    input a,
    input b,
    input select,
    output reg out
);

wire xor_out;
wire func_out;

xor_gate xor_inst(
    .a(a),
    .b(b),
    .xor_out(xor_out)
);

functional_module func_inst(
    .xor_out(xor_out),
    .func_out(func_out)
);

always @(*) begin
    if(select == 1'b1) begin
        out = func_out;
    end else begin
        out = xor_out;
    end
end

endmodule

module top_module(
    input a, 
    input b,
    input select,
    output wire out
);

control_logic control_inst(
    .a(a),
    .b(b),
    .select(select),
    .out(out)
);

endmodule

