rtl:
module DLL (
  input ref_clk,
  input feedback_clk,
  input [7:0] delay,
  output out_clk
);

  reg [7:0] delay_reg;
  reg [7:0] delay_next;
  reg [7:0] error;
  reg [7:0] error_filtered;
  reg [7:0] error_integrated;
  reg [7:0] error_integrated_next;
  reg [7:0] error_filtered_next;
  reg [7:0] phase_detector_out;
  reg [7:0] delay_line_out;
  reg [7:0] out_clk_reg;
  reg [7:0] out_clk_next;

  always @(posedge ref_clk) begin
    delay_reg <= delay;
    delay_next <= delay_reg;
    error <= phase_detector_out;
    error_filtered <= error_filtered_next;
    error_integrated <= error_integrated_next;
    out_clk_reg <= out_clk_next;
  end

  always @(posedge feedback_clk) begin
    delay_line_out <= delay_reg[7] ? feedback_clk : delay_line_out;
    delay_line_out <= delay_reg[6] ? delay_line_out : feedback_clk;
    delay_line_out <= delay_reg[5] ? delay_line_out : feedback_clk;
    delay_line_out <= delay_reg[4] ? delay_line_out : feedback_clk;
    delay_line_out <= delay_reg[3] ? delay_line_out : feedback_clk;
    delay_line_out <= delay_reg[2] ? delay_line_out : feedback_clk;
    delay_line_out <= delay_reg[1] ? delay_line_out : feedback_clk;
    delay_line_out <= delay_reg[0] ? delay_line_out : feedback_clk;

    phase_detector_out <= delay_line_out ^ feedback_clk;

    error_filtered_next <= (error_filtered + error) >> 1;
    error_integrated_next <= error_integrated + error_filtered_next;

    delay_next <= delay_reg + error_integrated_next;

    out_clk_next <= delay_reg[7] ? delay_line_out : out_clk_reg;
    out_clk_next <= delay_reg[6] ? out_clk_reg : delay_line_out;
    out_clk_next <= delay_reg[5] ? out_clk_reg : delay_line_out;
    out_clk_next <= delay_reg[4] ? out_clk_reg : delay_line_out;
    out_clk_next <= delay_reg[3] ? out_clk_reg : delay_line_out;
    out_clk_next <= delay_reg[2] ? out_clk_reg : delay_line_out;
    out_clk_next <= delay_reg[1] ? out_clk_reg : delay_line_out;
    out_clk_next <= delay_reg[0] ? out_clk_reg : delay_line_out;
  end

  assign out_clk = out_clk_reg;

endmodule

sva:
module DLL_sva (
    input logic       ref_clk,
    input logic       feedback_clk,
    input logic [7:0] delay,
    input logic       out_clk,
    input logic [7:0] delay_reg,
    input logic [7:0] error,
    input logic [7:0] error_filtered,
    input logic [7:0] error_integrated,
    input logic [7:0] error_integrated_next,
    input logic [7:0] error_filtered_next,
    input logic [7:0] phase_detector_out,
    input logic [7:0] delay_line_out,
    input logic [7:0] out_clk_reg,
    input logic [7:0] out_clk_next
);

    // delay_reg samples delay on ref_clk.
    check_delay_reg_captures_delay: assert property (
        @(posedge ref_clk) 1'b1 |=> (delay_reg == $past(delay))
    );

    // error samples phase_detector_out on ref_clk.
    check_error_captures_phase_detector: assert property (
        @(posedge ref_clk) 1'b1 |=> (error == $past(phase_detector_out))
    );

    // error_filtered samples error_filtered_next on ref_clk.
    check_error_filtered_updates: assert property (
        @(posedge ref_clk) 1'b1 |=> (error_filtered == $past(error_filtered_next))
    );

    // error_integrated samples error_integrated_next on ref_clk.
    check_error_integrated_updates: assert property (
        @(posedge ref_clk) 1'b1 |=> (error_integrated == $past(error_integrated_next))
    );

    // out_clk_reg samples out_clk_next on ref_clk.
    check_out_clk_reg_updates: assert property (
        @(posedge ref_clk) 1'b1 |=> (out_clk_reg == $past(out_clk_next))
    );

    // out_clk is the truncated LSB of out_clk_reg.
    check_out_clk_matches_out_clk_reg_lsb: assert property (
        @(posedge ref_clk) (out_clk == out_clk_reg[0])
    );

    // delay_line_out follows the final feedback-clock assignment controlled by delay_reg[0].
    check_delay_line_out_final_assignment: assert property (
        @(posedge feedback_clk) 1'b1 |=> (delay_line_out == ($past(delay_reg[0]) ? $past(delay_line_out) : 8'h01))
    );

    // phase_detector_out is delay_line_out XORed with a logic 1 at feedback_clk edges.
    check_phase_detector_out_xor: assert property (
        @(posedge feedback_clk) 1'b1 |=> (phase_detector_out == ($past(delay_line_out) ^ 8'h01))
    );

    // error_filtered_next is the averaged sum of error_filtered and error.
    check_error_filtered_next_computation: assert property (
        @(posedge feedback_clk) 1'b1 |=> (error_filtered_next == (($past(error_filtered) + $past(error)) >> 1))
    );

    // error_integrated_next accumulates error_integrated and error_filtered_next.
    check_error_integrated_next_computation: assert property (
        @(posedge feedback_clk) 1'b1 |=> (error_integrated_next == ($past(error_integrated) + $past(error_filtered_next)))
    );

    // out_clk_next follows the final feedback-clock assignment controlled by delay_reg[0].
    check_out_clk_next_final_assignment: assert property (
        @(posedge feedback_clk) 1'b1 |=> (out_clk_next == ($past(delay_reg[0]) ? $past(out_clk_reg) : $past(delay_line_out)))
    );

endmodule

rtl:
module softusb_timer(
	input usb_clk,
	input usb_rst,

	input io_we,
	input [5:0] io_a,
	output reg [7:0] io_do
);

reg [31:0] counter;

always @(posedge usb_clk) begin
	if(usb_rst) begin
		counter <= 32'd0;
		io_do <= 32'd0;
	end else begin
		io_do <= 32'd0;
		case(io_a)
			6'h11: io_do <= counter[7:0];
			6'h12: io_do <= counter[15:8];
			6'h13: io_do <= counter[23:16];
			6'h14: io_do <= counter[31:24];
		endcase
		if(io_we & ((io_a == 6'h11)|(io_a == 6'h12)|(io_a == 6'h13)|(io_a == 6'h14)))
			counter <= 32'd0;
		else
			counter <= counter + 32'd1;
	end
end

endmodule

sva:
module softusb_timer_sva(
    input logic        usb_clk,
    input logic        usb_rst,
    input logic        io_we,
    input logic [5:0]  io_a,
    input logic [7:0]  io_do,
    input logic [31:0] counter
);

    // Counter is zero after a reset cycle.
    check_counter_zero_after_reset: assert property (
        @(posedge usb_clk) disable iff (usb_rst || $initstate)
        $past(usb_rst) |-> (counter == 32'd0)
    );

    // Output data is zero after a reset cycle.
    check_io_do_zero_after_reset: assert property (
        @(posedge usb_clk) disable iff (usb_rst || $initstate)
        $past(usb_rst) |-> (io_do == 8'd0)
    );

    // A write to any mapped timer address clears the counter.
    check_counter_clears_on_valid_write: assert property (
        @(posedge usb_clk) disable iff (usb_rst || $initstate)
        !$past(usb_rst) &&
        $past(io_we) &&
        (
            ($past(io_a) == 6'h11) ||
            ($past(io_a) == 6'h12) ||
            ($past(io_a) == 6'h13) ||
            ($past(io_a) == 6'h14)
        )
        |-> (counter == 32'd0)
    );

    // All other non-reset cycles increment the counter by one.
    check_counter_increments_without_valid_write: assert property (
        @(posedge usb_clk) disable iff (usb_rst || $initstate)
        !$past(usb_rst) &&
        !(
            $past(io_we) &&
            (
                ($past(io_a) == 6'h11) ||
                ($past(io_a) == 6'h12) ||
                ($past(io_a) == 6'h13) ||
                ($past(io_a) == 6'h14)
            )
        )
        |-> (counter == ($past(counter) + 32'd1))
    );

    // Address 0x11 returns the low byte of the prior counter value.
    check_io_do_addr_11: assert property (
        @(posedge usb_clk) disable iff (usb_rst || $initstate)
        !$past(usb_rst) && ($past(io_a) == 6'h11)
        |-> (io_do == $past(counter[7:0]))
    );

    // Address 0x12 returns the next byte of the prior counter value.
    check_io_do_addr_12: assert property (
        @(posedge usb_clk) disable iff (usb_rst || $initstate)
        !$past(usb_rst) && ($past(io_a) == 6'h12)
        |-> (io_do == $past(counter[15:8]))
    );

    // Address 0x13 returns the third byte of the prior counter value.
    check_io_do_addr_13: assert property (
        @(posedge usb_clk) disable iff (usb_rst || $initstate)
        !$past(usb_rst) && ($past(io_a) == 6'h13)
        |-> (io_do == $past(counter[23:16]))
    );

    // Address 0x14 returns the high byte of the prior counter value.
    check_io_do_addr_14: assert property (
        @(posedge usb_clk) disable iff (usb_rst || $initstate)
        !$past(usb_rst) && ($past(io_a) == 6'h14)
        |-> (io_do == $past(counter[31:24]))
    );

    // Unmapped addresses drive zero on the data output.
    check_io_do_zero_on_unmapped_address: assert property (
        @(posedge usb_clk) disable iff (usb_rst || $initstate)
        !$past(usb_rst) &&
        ($past(io_a) != 6'h11) &&
        ($past(io_a) != 6'h12) &&
        ($past(io_a) != 6'h13) &&
        ($past(io_a) != 6'h14)
        |-> (io_do == 8'd0)
    );

endmodule

rtl:
module my_buffer (
    input i,
