    check_q3_three_cycle_delay_of_q: assert property (
        @(posedge clk) 1'b1 |-> ##3 (q3 == $past(q, 3))
    );

    // q repeats its sampled value every four clocks.
    check_q_four_cycle_repeat: assert property (
        @(posedge clk) 1'b1 |-> ##4 (q == $past(q, 4))
    );

