// Behavioral XOR gate
assign out_behavioral = a ^ b;

// Structural XOR gate using pipeline approach
xor_gate p1(.a(a), .b(b), .out(p1_out));
xor_gate p2(.a(p1_out), .b(b), .out(p2_out));
assign out_structural = p2_out;

