module abs_val (
    input [3:0] num_in,
    input clk,
    input rst,
    output reg [3:0] abs_val_out
);

reg [3:0] neg_num;
reg [3:0] pos_num;

// 2's complement conversion
always @ (*) begin
    neg_num = ~num_in + 4'b1;
end

// Comparator to check if num_in is negative
wire is_neg = (num_in[3] == 1);

// Multiplexer to choose between num_in and neg_num
wire [3:0] mux_out;
assign mux_out = is_neg ? neg_num : num_in;

// Adder/subtractor to convert negative number to positive
always @ (*) begin
    pos_num = {1'b0, mux_out[2:0]} + 4'b1;
end

// Output register to synchronize output
always @(posedge clk, posedge rst) begin
    if (rst) begin
        abs_val_out <= 4'b0;
    end else begin
        abs_val_out <= pos_num[3:0];
    end
end

endmodule

sva:
module abs_val_sva (
    input logic [3:0] num_in,
    input logic       clk,
    input logic       rst,
    input logic [3:0] abs_val_out
);

    // clk is the sampling clock; rst is active-high in the DUT.
    // The DUT has combinational datapath logic feeding a registered output.

    logic [3:0] neg_num;
    logic       is_neg;
    logic [3:0] mux_out;
    logic [3:0] pos_num;

    assign neg_num = ~num_in + 4'b0001;
    assign is_neg  = (num_in[3] == 1'b1);
    assign mux_out = is_neg ? neg_num : num_in;
    assign pos_num = {1'b0, mux_out[2:0]} + 4'b0001;

    // A sampled reset forces the next sampled output to zero.
    check_reset_cycle_clears_next_sample: assert property (
        @(posedge clk) rst |=> (abs_val_out == 4'b0000)
    );

    // The registered output can only be 0 through 8 on the next sample.
    check_next_output_stays_in_0_to_8_range: assert property (
        @(posedge clk) disable iff (rst)
        1'b1 |=> (abs_val_out <= 4'b1000)
    );

    // Next sample is either the prior computed pos_num or reset zero.
    check_next_output_is_loaded_pos_num_or_reset_zero: assert property (
        @(posedge clk) disable iff (rst)
        1'b1 |=> ((abs_val_out == $past(pos_num)) || (abs_val_out == 4'b0000))
    );

    // A non-negative input loads its zero-extended low 3 bits plus 1, unless reset drives zero.
    check_non_negative_input_loads_incremented_value_or_zero: assert property (
        @(posedge clk) disable iff (rst)
        !is_neg |=> ((abs_val_out == ({1'b0, $past(num_in[2:0])} + 4'b0001)) || (abs_val_out == 4'b0000))
    );

    // A negative input loads the low 3 bits of its two's complement plus 1, unless reset drives zero.
    check_negative_input_loads_negated_low_bits_plus_one_or_zero: assert property (
        @(posedge clk) disable iff (rst)
        is_neg |=> ((abs_val_out == ({1'b0, $past(neg_num[2:0])} + 4'b0001)) || (abs_val_out == 4'b0000))
    );

    // Input 0 loads 1 on the next sample, unless reset drives zero.
    check_zero_input_maps_to_one_or_zero: assert property (
        @(posedge clk) disable iff (rst)
        (num_in == 4'b0000) |=> ((abs_val_out == 4'b0001) || (abs_val_out == 4'b0000))
    );

    // Input 7 loads 8 on the next sample, unless reset drives zero.
    check_seven_input_maps_to_eight_or_zero: assert property (
        @(posedge clk) disable iff (rst)
        (num_in == 4'b0111) |=> ((abs_val_out == 4'b1000) || (abs_val_out == 4'b0000))
    );

    // Input 8 loads 1 on the next sample, unless reset drives zero.
    check_most_negative_input_maps_to_one_or_zero: assert property (
        @(posedge clk) disable iff (rst)
        (num_in == 4'b1000) |=> ((abs_val_out == 4'b0001) || (abs_val_out == 4'b0000))
    );

    // Input 15 loads 2 on the next sample, unless reset drives zero.
    check_minus_one_input_maps_to_two_or_zero: assert property (
        @(posedge clk) disable iff (rst)
        (num_in == 4'b1111) |=> ((abs_val_out == 4'b0010) || (abs_val_out == 4'b0000))
    );

    // Input 9 loads 8 on the next sample, unless reset drives zero.
    check_minus_seven_input_maps_to_eight_or_zero: assert property (
        @(posedge clk) disable iff (rst)
        (num_in == 4'b1001) |=> ((abs_val_out == 4'b1000) || (abs_val_out == 4'b0000))
    );

endmodule

rtl:
module crc8_single_bit (
  input data,
  input enable_crc,
  input reset,
  input sync_reset_crc,
  input clk,
  output reg [7:0] crc_out
);

  // polynomial: (0 1 2 8)
  // data width: 1
  function [7:0] nextCRC8_D1;
    input data;
    input [7:0] crc;

    reg [0:0] d;
    reg [7:0] c;
    reg [7:0] new_crc;

    begin
      d[0] = data;
      c = crc;

      new_crc[0] = d[0] ^ c[7];
      new_crc[1] = d[0] ^ c[0] ^ c[7];
      new_crc[2] = d[0] ^ c[1] ^ c[7];
      new_crc[3] = c[2];
      new_crc[4] = c[3];
      new_crc[5] = c[4];
      new_crc[6] = c[5];
      new_crc[7] = c[6];

      nextCRC8_D1 = new_crc;
    end
  endfunction

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      crc_out <= 0;
    end else if (sync_reset_crc) begin
      crc_out <= 0;
    end else if (enable_crc) begin
      crc_out <= nextCRC8_D1(data, crc_out);
    end
  end

endmodule

sva:
module crc8_single_bit_sva (
  input logic       data,
  input logic       enable_crc,
  input logic       reset,
  input logic       sync_reset_crc,
  input logic       clk,
  input logic [7:0] crc_out
);

  // Clock: clk
  // Reset: reset is active high and asynchronous; sync_reset_crc is a synchronous clear
  // Logic: combinational next-state CRC function driving a sequential crc_out register

  // Async reset forces the CRC output to zero.
  check_async_reset_clears_crc: assert property (
    @(posedge clk)
    reset |-> (crc_out == 8'h00)
  );

  // A sampled sync reset clears the CRC on the following cycle.
  check_sync_reset_clears_crc: assert property (
    @(posedge clk) disable iff (reset)
    sync_reset_crc |=> (crc_out == 8'h00)
  );

  // Sync reset takes priority over an enabled CRC update.
  check_sync_reset_priority_over_enable: assert property (
    @(posedge clk) disable iff (reset)
    (sync_reset_crc && enable_crc) |=> (crc_out == 8'h00)
  );

  // Without enable or sync reset, the CRC register holds its value.
  check_crc_holds_when_disabled: assert property (
    @(posedge clk) disable iff (reset)
    (!sync_reset_crc && !enable_crc) |=> (crc_out == $past(crc_out))
  );

  // Bit 0 updates with the implemented feedback equation.
  check_crc_bit0_update: assert property (
    @(posedge clk) disable iff (reset)
    (!sync_reset_crc && enable_crc) |=> (crc_out[0] == ($past(data) ^ $past(crc_out[7])))
  );

  // Bit 1 updates with the implemented feedback equation.
  check_crc_bit1_update: assert property (
    @(posedge clk) disable iff (reset)
    (!sync_reset_crc && enable_crc) |=> (crc_out[1] == ($past(data) ^ $past(crc_out[0]) ^ $past(crc_out[7])))
  );

  // Bit 2 updates with the implemented feedback equation.
  check_crc_bit2_update: assert property (
    @(posedge clk) disable iff (reset)
    (!sync_reset_crc && enable_crc) |=> (crc_out[2] == ($past(data) ^ $past(crc_out[1]) ^ $past(crc_out[7])))
  );

  // Upper CRC bits shift from the previous state when enabled.
  check_crc_upper_bits_shift: assert property (
    @(posedge clk) disable iff (reset)
    (!sync_reset_crc && enable_crc) |=> (crc_out[7:3] == $past(crc_out[6:2]))
  );

endmodule

rtl:
module clk_gen(
    input clk_in1,
    input reset,
    output clk_out1
);

parameter DIVIDER = 4; // Change this to 2, 4, 8, 16 for different clock frequencies
reg [31:0] counter = 0;
reg clk_out1_reg = 0;

always @(posedge clk_in1, posedge reset) begin
    if (reset) begin
        counter <= 0;
        clk_out1_reg <= 0;
    end else begin
        counter <= counter + 1;
        if (counter == (clk_in1 / DIVIDER) - 1) begin
            counter <= 0;
            clk_out1_reg <= ~clk_out1_reg;
        end
    end
end

assign clk_out1 = clk_out1_reg;

endmodule

sva:
module clk_gen_assertions #(
    parameter int DIVIDER = 4
) (
    input logic        clk_in1,
    input logic        reset,
    input logic        clk_out1,
    input logic [31:0] counter,
    input logic        clk_out1_reg
);

    // Reset clears the counter and drives the generated clock low.
    check_reset_clears_state: assert property (
        @(posedge clk_in1)
        reset |-> ((counter == 32'd0) && (clk_out1_reg == 1'b0) && (clk_out1 == 1'b0))
    );

    // The output port must mirror the internal clock register.
    check_output_matches_reg: assert property (
        @(posedge clk_in1) disable iff (reset)
        clk_out1 == clk_out1_reg
    );

    // Before the terminal count, the counter increments and the output holds.
    check_counter_increments_before_terminal: assert property (
        @(posedge clk_in1) disable iff (reset || $initstate)
        (counter != ((1 / DIVIDER) - 1)) |=> ((counter == ($past(counter) + 32'd1)) &&
                                              (clk_out1_reg == $past(clk_out1_reg)) &&
                                              (clk_out1 == $past(clk_out1)))
    );

    // At the terminal count, the counter clears and the output toggles.
    check_terminal_count_wraps_and_toggles: assert property (
        @(posedge clk_in1) disable iff (reset || $initstate)
        (counter == ((1 / DIVIDER) - 1)) |=> ((counter == 32'd0) &&
                                              (clk_out1_reg == ~$past(clk_out1_reg)) &&
                                              (clk_out1 == ~$past(clk_out1)))
    );

    // Any output transition must be caused by the previous terminal count.
    check_output_toggle_requires_terminal_count: assert property (
        @(posedge clk_in1) disable iff (reset || $initstate)
        (clk_out1 != $past(clk_out1)) |-> ($past(counter) == ((1 / DIVIDER) - 1))
    );

    // A nonzero-to-zero counter transition must come from the terminal count.
    check_counter_clear_requires_terminal_count: assert property (
        @(posedge clk_in1) disable iff (reset || $initstate)
        ((counter == 32'd0) && ($past(counter) != 32'd0)) |-> ($past(counter) == ((1 / DIVIDER) - 1))
    );

endmodule

rtl:
module four_bit_adder (
    input [3:0] A,
    input [3:0] B,
    input C_in,
    output [3:0] S,
    output C_out
);

    wire [3:0] c1, c2, c3;

    // First column
    assign c1[0] = A[0] & B[0];
    assign S[0] = A[0] ^ B[0] ^ C_in;

    // Second column
    assign c1[1] = A[1] ^ B[1];
    assign c2[1] = c1[0] & c1[1];
    assign S[1] = A[1] ^ B[1] ^ C_in;
    assign C_out = c1[0] & c1[1] | A[1] & B[1];

    // Third column
    assign c1[2] = A[2] ^ B[2];
    assign c2[2] = c1[1] & c1[2];
    assign c3[2] = c2[1] ^ c2[2];
    assign S[2] = A[2] ^ B[2] ^ C_in;

    // Fourth column
    assign c1[3] = A[3] ^ B[3];
    assign c2[3] = c1[2] & c1[3];
    assign c3[3] = c2[2] ^ c2[3];
    assign S[3] = A[3] ^ B[3] ^ C_in;

endmodule

sva:
module four_bit_adder_sva (
    input logic        clk,
    input logic [3:0]  A,
    input logic [3:0]  B,
    input logic        C_in,
    input logic [3:0]  S,
    input logic        C_out
);

    // S[0] matches the first sum assignment.
    check_sum_bit0_equation: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0] ^ C_in)
    );

    // S[1] matches the second sum assignment.
    check_sum_bit1_equation: assert property (
        @(posedge clk) S[1] == (A[1] ^ B[1] ^ C_in)
    );

    // S[2] matches the third sum assignment.
    check_sum_bit2_equation: assert property (
        @(posedge clk) S[2] == (A[2] ^ B[2] ^ C_in)
    );

    // S[3] matches the fourth sum assignment.
    check_sum_bit3_equation: assert property (
        @(posedge clk) S[3] == (A[3] ^ B[3] ^ C_in)
    );

    // The full sum bus matches the per-bit XOR structure.
    check_sum_vector_equation: assert property (
        @(posedge clk) S == ((A ^ B) ^ {4{C_in}})
    );

    // With C_in low, S reduces to A XOR B.
    check_sum_when_cin_low: assert property (
        @(posedge clk) (C_in == 1'b0) |-> (S == (A ^ B))
    );

    // With C_in high, S is the inverse of A XOR B.
    check_sum_when_cin_high: assert property (
        @(posedge clk) (C_in == 1'b1) |-> (S == ~(A ^ B))
    );

    // C_out matches the RTL carry expression.
    check_cout_equation: assert property (
        @(posedge clk) C_out == ((((A[0] & B[0]) & (A[1] ^ B[1])) | (A[1] & B[1])))
    );

    // A generate on bit 1 forces C_out high.
    check_cout_from_bit1_generate: assert property (
        @(posedge clk) (A[1] & B[1]) |-> (C_out == 1'b1)
    );

    // The lower carry-propagate term forces C_out high.
    check_cout_from_low_propagate: assert property (
        @(posedge clk) ((A[0] & B[0]) & (A[1] ^ B[1])) |-> (C_out == 1'b1)
    );

    // If neither carry term is present, C_out stays low.
    check_cout_low_when_no_carry_term: assert property (
        @(posedge clk) (!(A[1] & B[1]) && !((A[0] & B[0]) & (A[1] ^ B[1]))) |-> (C_out == 1'b0)
    );

endmodule

rtl:
module clk_counter(
    input clk,
    input reset,
    output reg [3:0] counter
);

always @(posedge clk, negedge reset) begin
    if(!reset) begin
        counter <= 4'b0000;
    end else begin
        counter <= counter + 1;
    end
end

endmodule

sva:
module clk_counter_sva(
    input logic       clk,
    input logic       reset,
    input logic [3:0] counter
);

    // Each sampled count is either reset-cleared to zero or increments by one.
    check_counter_advances_or_clears: assert property (
        @(posedge clk) disable iff (!reset || $initstate)
        (counter == 4'b0000) || (counter == ($past(counter) + 4'b0001))
    );

    // Any nonzero sampled count must come from incrementing the prior sampled count.
    check_nonzero_samples_increment: assert property (
        @(posedge clk) disable iff (!reset || $initstate)
        (counter != 4'b0000) |-> (counter == ($past(counter) + 4'b0001))
    );

    // A sampled maximum count must wrap to zero on the next sampled cycle.
    check_wrap_from_max_to_zero: assert property (
        @(posedge clk) disable iff (!reset || $initstate)
        ($past(counter) == 4'hF) |-> (counter == 4'h0)
    );

    // A sampled count of one can only follow a sampled count of zero.
    check_one_follows_zero: assert property (
        @(posedge clk) disable iff (!reset || $initstate)
        (counter == 4'h1) |-> ($past(counter) == 4'h0)
    );

    // A nonzero sampled count cannot directly follow a sampled maximum count.
    check_nonzero_not_after_max: assert property (
        @(posedge clk) disable iff (!reset || $initstate)
        (counter != 4'b0000) |-> ($past(counter) != 4'hF)
    );

endmodule

rtl:
module adder_parameterized #(
    parameter N = 4,
    parameter M = 4
) (
    input [N-1:0] A,
    input [N-1:0] B,
    input Cin,
    output [M-1:0] S,
    output Cout
);

parameter W = 4;

wire [N:0] C;
wire [N-1:0] S_int;
assign S_int = A ^ B ^ Cin;
assign C[0] = Cin;
genvar i;
generate
    for (i = 0; i < N; i = i + 1) begin : gen_adder
        assign C[i+1] = (A[i] & B[i]) | (A[i] & C[i]) | (B[i] & C[i]);
        assign S[i] = A[i] ^ B[i] ^ C[i]; //Output is registered
    end
endgenerate

assign Cout = C[N];

endmodule

sva:
module adder_parameterized_sva #(
    parameter int N = 4,
    parameter int M = 4
) (
    input logic clk,
    input logic [N-1:0] A,
    input logic [N-1:0] B,
    input logic Cin,
    input logic [M-1:0] S,
    input logic Cout
);

    localparam int SUM_BITS = (N < M) ? N : M;

    function automatic logic [N:0] full_add_result (
        input logic [N-1:0] a,
        input logic [N-1:0] b,
        input logic cin
    );
        full_add_result = {1'b0, a} + {1'b0, b} + cin;
    endfunction

    generate
        if (SUM_BITS > 0) begin : gen_sum_checks
            for (genvar i = 0; i < SUM_BITS; i++) begin : gen_sum_bit_checks
                // Each visible sum bit matches the corresponding addition result bit.
                check_sum_bit_matches_addition: assert property (
                    @(posedge clk) S[i] == full_add_result(A, B, Cin)[i]
                );
            end
        end
    endgenerate

    // Carry-out matches the addition result carry bit.
    check_cout_matches_addition: assert property (
        @(posedge clk) Cout == full_add_result(A, B, Cin)[N]
    );

    generate
        if (M == N) begin : gen_full_result_check
            // Full output vector matches A + B + Cin when widths align.
            check_full_result_matches_addition: assert property (
                @(posedge clk) {Cout, S} == full_add_result(A, B, Cin)
            );
        end
    endgenerate

    generate
        if (SUM_BITS > 0) begin : gen_add_zero_preserves_a_check
            // Adding zero with no carry preserves the visible bits of A.
            check_add_zero_preserves_a: assert property (
                @(posedge clk) (B == '0 && Cin == 1'b0) |-> (S[SUM_BITS-1:0] == A[SUM_BITS-1:0])
            );
        end
    endgenerate

    // Adding zero with no carry never produces a carry-out.
    check_add_zero_clears_cout: assert property (
        @(posedge clk) (B == '0 && Cin == 1'b0) |-> (Cout == 1'b0)
    );

    generate
        if (SUM_BITS > 0) begin : gen_add_zero_preserves_b_check
            // Adding zero with no carry preserves the visible bits of B.
            check_add_zero_preserves_b: assert property (
                @(posedge clk) (A == '0 && Cin == 1'b0) |-> (S[SUM_BITS-1:0] == B[SUM_BITS-1:0])
            );
        end
    endgenerate

    // Zero operands do not produce a carry-out.
    check_zero_operands_no_carry: assert property (
        @(posedge clk) (A == '0 && B == '0) |-> (Cout == 1'b0)
    );

    generate
        if (SUM_BITS > 0) begin : gen_zero_operands_lsb_check
            // With zero operands, the least-significant visible sum bit follows Cin.
            check_zero_operands_pass_cin_to_lsb: assert property (
                @(posedge clk) (A == '0 && B == '0) |-> (S[0] == Cin)
            );
        end
    endgenerate

endmodule

rtl:
module BCD_to_Binary (
  input [3:0] bcd,
  output reg [7:0] bin
);

  always @(*) begin
    case(bcd)
      4'b0000: bin = 8'b00000000;
      4'b0001: bin = 8'b00000001;
      4'b0010: bin = 8'b00000010;
      4'b0011: bin = 8'b00000011;
      4'b0100: bin = 8'b00000100;
      4'b0101: bin = 8'b00000101;
      4'b0110: bin = 8'b00000110;
      4'b0111: bin = 8'b00000111;
      4'b1000: bin = 8'b00001000;
      4'b1001: bin = 8'b00001001;
      default: bin = 8'b11111111; // The default case should output all 1s (binary 255) to indicate an error.
    endcase
  end

endmodule

sva:
module BCD_to_Binary_sva (
    input logic clk,
    input logic [3:0] bcd,
    input logic [7:0] bin
);

    // BCD 0 maps to binary 0.
    check_bcd_0_maps_to_0: assert property (
        @(posedge clk) (bcd == 4'd0) |-> (bin == 8'd0)
    );

    // BCD 1 maps to binary 1.
    check_bcd_1_maps_to_1: assert property (
        @(posedge clk) (bcd == 4'd1) |-> (bin == 8'd1)
    );

    // BCD 2 maps to binary 2.
    check_bcd_2_maps_to_2: assert property (
        @(posedge clk) (bcd == 4'd2) |-> (bin == 8'd2)
    );

    // BCD 3 maps to binary 3.
    check_bcd_3_maps_to_3: assert property (
        @(posedge clk) (bcd == 4'd3) |-> (bin == 8'd3)
    );

    // BCD 4 maps to binary 4.
    check_bcd_4_maps_to_4: assert property (
        @(posedge clk) (bcd == 4'd4) |-> (bin == 8'd4)
    );

    // BCD 5 maps to binary 5.
    check_bcd_5_maps_to_5: assert property (
        @(posedge clk) (bcd == 4'd5) |-> (bin == 8'd5)
    );

    // BCD 6 maps to binary 6.
    check_bcd_6_maps_to_6: assert property (
        @(posedge clk) (bcd == 4'd6) |-> (bin == 8'd6)
    );

    // BCD 7 maps to binary 7.
    check_bcd_7_maps_to_7: assert property (
        @(posedge clk) (bcd == 4'd7) |-> (bin == 8'd7)
    );

    // BCD 8 maps to binary 8.
    check_bcd_8_maps_to_8: assert property (
        @(posedge clk) (bcd == 4'd8) |-> (bin == 8'd8)
    );

    // BCD 9 maps to binary 9.
    check_bcd_9_maps_to_9: assert property (
        @(posedge clk) (bcd == 4'd9) |-> (bin == 8'd9)
    );

    // Invalid BCD values map to the error code 8'hFF.
    check_invalid_bcd_maps_to_error: assert property (
        @(posedge clk) (bcd >= 4'd10) |-> (bin == 8'hFF)
    );

    // The error code is only produced for invalid BCD values.
    check_error_code_only_for_invalid_bcd: assert property (
        @(posedge clk) (bin == 8'hFF) |-> (bcd >= 4'd10)
    );

endmodule

rtl:
module logic_circuit (
  input a,
  input b,
  input c,
  input d,
  output out
);

  wire out;

  assign out = (a & b & c & d);

endmodule

sva:
module logic_circuit_assertions (
    input logic clk,
    input logic a,
    input logic b,
    input logic c,
    input logic d,
    input logic out
);

    // Sample the combinational DUT on an external verification clock.

    // Output must match the four-input AND expression.
    check_out_matches_and: assert property (
        @(posedge clk) out === (a & b & c & d)
    );

    // All inputs high drives the output high.
    check_all_high_drives_out_high: assert property (
        @(posedge clk) ((a === 1'b1) && (b === 1'b1) && (c === 1'b1) && (d === 1'b1)) |-> (out === 1'b1)
    );

    // A high output requires all inputs high.
    check_out_high_requires_all_high: assert property (
        @(posedge clk) (out === 1'b1) |-> ((a === 1'b1) && (b === 1'b1) && (c === 1'b1) && (d === 1'b1))
    );

    // Any low input forces the output low.
    check_any_low_forces_out_low: assert property (
        @(posedge clk) ((a === 1'b0) || (b === 1'b0) || (c === 1'b0) || (d === 1'b0)) |-> (out === 1'b0)
    );

    // Stable inputs keep the sampled output stable.
    check_stable_inputs_keep_stable_output: assert property (
        @(posedge clk) $stable({a, b, c, d}) |-> $stable(out)
    );

endmodule

module binary_counter_assertions (
    input logic       clk,
    input logic       rst,
    input logic       up_down,
    input logic [3:0] count
);

    // A sampled reset cycle leaves the count at zero on the next sampled clock.
    reset_leaves_count_zero_next_cycle: assert property (
        @(posedge clk) !rst |=> (count == 4'b0000)
    );

    // When reset is released, count is still zero before counting resumes.
    reset_release_starts_from_zero: assert property (
        @(posedge clk) disable iff (!rst) $rose(rst) |-> (count == 4'b0000)
    );

    // With up_down high, count increments by one on the next clock.
    count_increments_when_up: assert property (
        @(posedge clk) disable iff (!rst) up_down |=> (count == ($past(count) + 4'b0001))
    );

    // With up_down low, count decrements by one on the next clock.
    count_decrements_when_down: assert property (
        @(posedge clk) disable iff (!rst) !up_down |=> (count == ($past(count) - 4'b0001))
    );

    // Counting up wraps from 4'hF back to 4'h0.
    up_wraps_from_f_to_zero: assert property (
        @(posedge clk) disable iff (!rst) up_down && (count == 4'hF) |=> (count == 4'h0)
    );

    // Counting down wraps from 4'h0 back to 4'hF.
    down_wraps_from_zero_to_f: assert property (
        @(posedge clk) disable iff (!rst) !up_down && (count == 4'h0) |=> (count == 4'hF)
    );

endmodule

rtl:
module barrel_shifter (
    input [3:0] in,
    input [1:0] shift_amt,
    output reg [3:0] out
);

    always @(*) begin
        case(shift_amt)
            2'b00: out = in;
            2'b01: out = {in[3], in[0], in[1], in[2]};
            2'b10: out = {in[2], in[3], in[0], in[1]};
            2'b11: out = {in[1], in[2], in[3], in[0]};
        endcase
    end

endmodule

sva:
module barrel_shifter_sva (
    input logic [3:0] in,
    input logic [1:0] shift_amt,
    input logic [3:0] out
);

    // When shift_amt is 00, out must equal in.
    check_shift_amt_00: assert property (
        @($global_clock) (shift_amt == 2'b00) |-> (out == in)
    );

    // When shift_amt is 01, out must match the RTL permutation.
    check_shift_amt_01: assert property (
        @($global_clock) (shift_amt == 2'b01) |-> (out == {in[3], in[0], in[1], in[2]})
    );

    // When shift_amt is 10, out must match the RTL permutation.
    check_shift_amt_10: assert property (
        @($global_clock) (shift_amt == 2'b10) |-> (out == {in[2], in[3], in[0], in[1]})
    );

    // When shift_amt is 11, out must match the RTL permutation.
    check_shift_amt_11: assert property (
        @($global_clock) (shift_amt == 2'b11) |-> (out == {in[1], in[2], in[3], in[0]})
    );

endmodule

rtl:
module binary_adder (
  input [3:0] A,
  input [3:0] B,
  input C_in,
  output [3:0] S
);

  wire [3:0] sum_wire;

  assign sum_wire = A + B + C_in;

  assign S = sum_wire;

endmodule

sva:
module binary_adder_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic       C_in,
    input logic [3:0] S
);

    // S always reflects the 4-bit sum of A, B, and C_in.
    check_output_matches_sum: assert property (
        @($global_clock) S == (A + B + C_in)
    );

    // With B and C_in low, S passes A unchanged.
    check_a_passthrough_when_b_and_cin_zero: assert property (
        @($global_clock) (B == 4'b0000 && C_in == 1'b0) |-> (S == A)
    );

    // With A and C_in low, S passes B unchanged.
    check_b_passthrough_when_a_and_cin_zero: assert property (
        @($global_clock) (A == 4'b0000 && C_in == 1'b0) |-> (S == B)
    );

    // With both operands low, S equals the zero-extended carry-in.
    check_cin_only_result: assert property (
        @($global_clock) (A == 4'b0000 && B == 4'b0000) |-> (S == {3'b000, C_in})
    );

    // The least-significant sum bit follows full-adder parity.
    check_lsb_full_adder_behavior: assert property (
        @($global_clock) S[0] == (A[0] ^ B[0] ^ C_in)
    );

endmodule

rtl:
module counter(input clk, input reset, input en, output reg [3:0] count);

	always @(posedge clk) begin
		if (reset) begin
			count <= 0;
		end
		else if (en) begin
			count <= count + 1;
		end
	end

endmodule

sva:
module counter_sva (
    input logic       clk,
    input logic       reset,
    input logic       en,
    input logic [3:0] count
);

    // A sampled reset clears the count on the following cycle.
    check_reset_clears_count: assert property (
        @(posedge clk) disable iff ($initstate)
        $past(reset) |-> (count == 4'd0)
    );

    // When enabled without reset, count increments by one on the following cycle.
    check_enable_increments_count: assert property (
        @(posedge clk) disable iff ($initstate)
        (!$past(reset) && $past(en)) |-> (count == ($past(count) + 4'd1))
    );

    // When not enabled and not in reset, count holds its previous value.
    check_disable_holds_count: assert property (
        @(posedge clk) disable iff ($initstate)
        (!$past(reset) && !$past(en)) |-> (count == $past(count))
    );

    // Any count change must be caused by a sampled reset or enable.
    check_count_change_has_cause: assert property (
        @(posedge clk) disable iff ($initstate)
        (count != $past(count)) |-> ($past(reset) || $past(en))
    );

endmodule

rtl:
module my_module (
    output Y,
    input A1,
    input A2,
    input A3,
    input B1
);

    // Module supplies
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB;
    supply0 VNB;

    // Local signals
    wire and_out;
    wire nor_out;

    // AND gate
    and and_gate(
        and_out,
        A1,
        A2,
        A3
    );

    // NOR gate
    nor nor_gate(
        nor_out,
        and_out,
        B1
    );

    // Output buffer
    buf buf_gate(
        Y,
        nor_out
    );

endmodule

sva:
module my_module_sva (
    input logic Y,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic B1
);

    // Y must equal the NOR of B1 and the 3-input AND of A1/A2/A3.
    check_output_function: assert property (
        @($global_clock) disable iff (1'b0)
        Y == ~((A1 & A2 & A3) | B1)
    );

    // B1 high forces the NOR output low.
    check_b1_forces_y_low: assert property (
        @($global_clock) disable iff (1'b0)
        B1 |-> !Y
    );

    // All three A inputs high force the AND term high and Y low.
    check_all_a_high_forces_y_low: assert property (
        @($global_clock) disable iff (1'b0)
        (A1 & A2 & A3) |-> !Y
    );

    // With B1 low, A1 low keeps the AND term low and Y high.
    check_a1_low_with_b1_low_forces_y_high: assert property (
        @($global_clock) disable iff (1'b0)
        ((!B1) & (!A1)) |-> Y
    );

    // With B1 low, A2 low keeps the AND term low and Y high.
    check_a2_low_with_b1_low_forces_y_high: assert property (
        @($global_clock) disable iff (1'b0)
        ((!B1) & (!A2)) |-> Y
    );

    // With B1 low, A3 low keeps the AND term low and Y high.
    check_a3_low_with_b1_low_forces_y_high: assert property (
        @($global_clock) disable iff (1'b0)
        ((!B1) & (!A3)) |-> Y
    );

    // Y high implies B1 is low.
    check_y_high_implies_b1_low: assert property (
        @($global_clock) disable iff (1'b0)
        Y |-> !B1
    );

    // Y high implies the 3-input AND term is low.
    check_y_high_implies_not_all_a_high: assert property (
        @($global_clock) disable iff (1'b0)
        Y |-> !(A1 & A2 & A3)
    );

    // Y low must be caused by B1 high or all A inputs high.
    check_y_low_has_valid_cause: assert property (
        @($global_clock) disable iff (1'b0)
        (!Y) |-> (B1 | (A1 & A2 & A3))
    );

    // If B1 is low and Y is low, all A inputs must be high.
    check_b1_low_and_y_low_implies_all_a_high: assert property (
        @($global_clock) disable iff (1'b0)
        ((!B1) & (!Y)) |-> (A1 & A2 & A3)
    );

endmodule

rtl:
module decoder_3to8 (
    input [2:0] in,
    output [7:0] out
);

assign out = 8'b00000001 << in;

endmodule

sva:
module decoder_3to8_sva (
    input logic        clk,
    input logic [2:0]  in,
    input logic [7:0]  out
);

    // Output matches the decoder equation.
    check_decode_equation: assert property (
        @(posedge clk) out == (8'b00000001 << in)
    );

    // Decoder output is always one-hot.
    check_out_is_onehot: assert property (
        @(posedge clk) $onehot(out)
    );

    // Input 0 selects output bit 0.
    check_in_0_decodes_bit0: assert property (
        @(posedge clk) (in == 3'd0) |-> (out == 8'b00000001)
    );

    // Input 1 selects output bit 1.
    check_in_1_decodes_bit1: assert property (
        @(posedge clk) (in == 3'd1) |-> (out == 8'b00000010)
    );

    // Input 2 selects output bit 2.
    check_in_2_decodes_bit2: assert property (
        @(posedge clk) (in == 3'd2) |-> (out == 8'b00000100)
    );

    // Input 3 selects output bit 3.
    check_in_3_decodes_bit3: assert property (
        @(posedge clk) (in == 3'd3) |-> (out == 8'b00001000)
    );

    // Input 4 selects output bit 4.
    check_in_4_decodes_bit4: assert property (
        @(posedge clk) (in == 3'd4) |-> (out == 8'b00010000)
    );

    // Input 5 selects output bit 5.
    check_in_5_decodes_bit5: assert property (
        @(posedge clk) (in == 3'd5) |-> (out == 8'b00100000)
    );

    // Input 6 selects output bit 6.
    check_in_6_decodes_bit6: assert property (
        @(posedge clk) (in == 3'd6) |-> (out == 8'b01000000)
    );

    // Input 7 selects output bit 7.
    check_in_7_decodes_bit7: assert property (
        @(posedge clk) (in == 3'd7) |-> (out == 8'b10000000)
    );

endmodule

rtl:
module multiplexer_256to1(
    input [255:0] in,
    input [7:0] sel,
    output out
);

wire [7:0] sel_inv;
assign sel_inv = ~sel;

wire [255:0] in_sel;
assign in_sel = {in[255:0], in[255:0], in[255:0], in[255:0], in[255:0], in[255:0], in[255:0], in[255:0]} & {sel_inv[7], sel_inv[6], sel_inv[5], sel_inv[4], sel_inv[3], sel_inv[2], sel_inv[1], sel_inv[0]};

assign out = in_sel[0];

endmodule

module top_module( 
    input [255:0] in,
    input [7:0] sel,
    output out
);

multiplexer_256to1 mux(
    .in(in),
    .sel(sel),
    .out(out)
);

endmodule

sva:
module top_module_sva(
    input logic [255:0] in,
    input logic [7:0] sel,
    input logic out
);

    // Output matches the RTL's effective combinational function.
    check_out_matches_effective_logic: assert property (
        @($global_clock) out == (in[0] & ~sel[0])
    );

    // sel[0] high forces the output low.
    check_sel0_high_forces_out_low: assert property (
        @($global_clock) (sel[0] == 1'b1) |-> (out == 1'b0)
    );

    // sel[0] low makes the output follow in[0].
    check_sel0_low_passes_in0: assert property (
        @($global_clock) (sel[0] == 1'b0) |-> (out == in[0])
    );

    // A high output requires in[0] high and sel[0] low.
    check_out_high_requires_in0_and_sel0_low: assert property (
        @($global_clock) (out == 1'b1) |-> ((in[0] == 1'b1) && (sel[0] == 1'b0))
    );

    // Changes in other input bits do not affect the output.
    check_other_bits_do_not_affect_out: assert property (
        @($global_clock)
        ($stable(in[0]) && $stable(sel[0]) && $changed({in[255:1], sel[7:1]})) |-> $stable(out)
    );

    // Output changes only when in[0] or sel[0] changes.
    check_out_change_depends_only_on_low_bits: assert property (
        @($global_clock) $changed(out) |-> ($changed(in[0]) || $changed(sel[0]))
    );

endmodule

rtl:
module top_module ( 
    input clk, 
    input reset,      // Synchronous active-high reset
    input a,           // Input for the shift register
    input b,           // Input for the shift register
    output out         // Output from the functional module
);

    // Define the shift register module
    reg [7:0] shift_reg;
    always @(posedge clk) begin
        if (reset) begin
            shift_reg <= 8'h34;
        end else begin
            shift_reg <= {shift_reg[6:0], a};
        end
    end

    // Define the XOR module
    wire xor_out = a ^ b;

    // Define the functional module
    assign out = shift_reg & xor_out;

endmodule

sva:
module top_module_sva (
    input logic       clk,
    input logic       reset,
    input logic       a,
    input logic       b,
    input logic       out,
    input logic [7:0] shift_reg
);

    // Reset loads the shift register with 8'h34.
    check_reset_loads_shift_reg: assert property (
        @(posedge clk) reset |=> (shift_reg == 8'h34)
    );

    // A non-reset cycle shifts left and loads a into bit 0.
    check_shift_reg_updates: assert property (
        @(posedge clk) disable iff (reset)
        (!$initstate && !$past(reset)) |-> (shift_reg == {$past(shift_reg[6:0]), $past(a)})
    );

    // out is the truncated LSB of shift_reg & (a ^ b).
    check_out_matches_truncated_and: assert property (
        @(posedge clk) disable iff (reset)
        out == (shift_reg[0] & (a ^ b))
    );

    // Equal inputs make the XOR term low, so out must be low.
    check_out_low_when_inputs_equal: assert property (
        @(posedge clk) disable iff (reset)
        (a == b) |-> (out == 1'b0)
    );

    // out can only be high when the XOR term is high.
    check_out_requires_xor_high: assert property (
        @(posedge clk) disable iff (reset)
        out |-> (a ^ b)
    );

    // out can only be high when shift_reg bit 0 is high.
    check_out_requires_shift_reg_lsb_high: assert property (
        @(posedge clk) disable iff (reset)
        out |-> shift_reg[0]
    );

    // The reset value has bit 0 low, so out is low after reset.
    check_reset_forces_out_low: assert property (
        @(posedge clk) reset |=> (out == 1'b0)
    );

endmodule

rtl:
module not_gate( input in, output out );
    assign out = ~(in & in);
endmodule

sva:
module not_gate_sva (
    input logic in,
    input logic out
);

    // Output must match the RTL continuous-assignment function.
    check_out_matches_rtl_function: assert property (
        @($global_clock) out === ~(in & in)
    );

    // A low input must drive the output high.
    check_low_input_drives_high_output: assert property (
        @($global_clock) (in == 1'b0) |-> (out === 1'b1)
    );

    // A high input must drive the output low.
    check_high_input_drives_low_output: assert property (
        @($global_clock) (in == 1'b1) |-> (out === 1'b0)
    );

endmodule

rtl:
module clk_gen(
    input wire clk100MHz,
    input wire rst,
    output reg clk1MHz,
    output reg clk5KHz,
    output reg clk200Hz
);

integer count;
integer ledmux;
integer highspeed;

always@(posedge clk100MHz or posedge rst)
begin
	if(rst) begin
		count = 0;   
		highspeed = 0;
		ledmux = 0;
		clk1MHz = 0;
		clk5KHz = 0;
		clk200Hz = 0;
	end
	else begin
	  	if(count == 250000) begin clk200Hz = ~clk200Hz;
			count = 0;
		end
	  	if(ledmux == 5000) begin clk5KHz = ~clk5KHz;
			ledmux = 0;
		end
	  	if(highspeed == 50) begin clk1MHz = ~clk1MHz;
			highspeed = 0;
		end
		count = count + 1;
		highspeed = highspeed + 1;
		ledmux = ledmux + 1;  
	end
end 
endmodule // end clk_gen

sva:
module clk_gen_sva (
    input logic clk100MHz,
    input logic rst,
    input logic clk1MHz,
    input logic clk5KHz,
    input logic clk200Hz,
    input integer count,
    input integer ledmux,
    input integer highspeed
);

    // Formal analysis starts from reset asserted.
    init_reset_assumption: assume property (
        @(posedge clk100MHz) $initstate |-> rst
    );

    // Reset clears all counters and generated clocks.
    check_reset_clears_state: assert property (
        @(posedge clk100MHz)
        rst |-> ((count == 0) && (ledmux == 0) && (highspeed == 0) &&
                 (clk1MHz == 1'b0) && (clk5KHz == 1'b0) && (clk200Hz == 1'b0))
    );

    // count stays within its reachable non-reset range.
    check_count_range: assert property (
        @(posedge clk100MHz) disable iff (rst)
        (count >= 1) && (count <= 250000)
    );

    // ledmux stays within its reachable non-reset range.
    check_ledmux_range: assert property (
        @(posedge clk100MHz) disable iff (rst)
        (ledmux >= 1) && (ledmux <= 5000)
    );

    // highspeed stays within its reachable non-reset range.
    check_highspeed_range: assert property (
        @(posedge clk100MHz) disable iff (rst)
        (highspeed >= 1) && (highspeed <= 50)
    );

    // clk200Hz toggles and count wraps to 1 after reaching 250000.
    check_count_wrap_and_toggle: assert property (
        @(posedge clk100MHz) disable iff (rst)
        (count == 250000) |=> ((count == 1) && (clk200Hz != $past(clk200Hz)))
    );

    // count increments and clk200Hz holds below the wrap point.
    check_count_increment_and_hold: assert property (
        @(posedge clk100MHz) disable iff (rst)
        ((count >= 1) && (count < 250000)) |=> ((count == ($past(count) + 1)) &&
                                                (clk200Hz == $past(clk200Hz)))
    );

    // clk5KHz toggles and ledmux wraps to 1 after reaching 5000.
    check_ledmux_wrap_and_toggle: assert property (
        @(posedge clk100MHz) disable iff (rst)
        (ledmux == 5000) |=> ((ledmux == 1) && (clk5KHz != $past(clk5KHz)))
    );

    // ledmux increments and clk5KHz holds below the wrap point.
    check_ledmux_increment_and_hold: assert property (
        @(posedge clk100MHz) disable iff (rst)
        ((ledmux >= 1) && (ledmux < 5000)) |=> ((ledmux == ($past(ledmux) + 1)) &&
                                                (clk5KHz == $past(clk5KHz)))
    );

    // clk1MHz toggles and highspeed wraps to 1 after reaching 50.
    check_highspeed_wrap_and_toggle: assert property (
        @(posedge clk100MHz) disable iff (rst)
        (highspeed == 50) |=> ((highspeed == 1) && (clk1MHz != $past(clk1MHz)))
    );

    // highspeed increments and clk1MHz holds below the wrap point.
    check_highspeed_increment_and_hold: assert property (
        @(posedge clk100MHz) disable iff (rst)
        ((highspeed >= 1) && (highspeed < 50)) |=> ((highspeed == ($past(highspeed) + 1)) &&
                                                    (clk1MHz == $past(clk1MHz)))
    );

endmodule

rtl:
module xor_gate (
    input  A,
    input  B,
    output Y,
    input  VDD,
    input  VSS
);

wire A_bar, B_bar;
assign A_bar = ~A;
assign B_bar = ~B;

wire Y1, Y2;
assign Y1 = A & B_bar;
assign Y2 = A_bar & B;
assign Y  = Y1 | Y2;

endmodule

sva:
module xor_gate_sva (
    input logic A,
    input logic B,
    input logic Y,
    input logic VDD,
    input logic VSS
);

    // Y must equal A XOR B.
    check_y_matches_xor_function: assert property (
        @($global_clock) Y == (A ^ B)
    );

    // A high output implies the inputs differ.
    check_high_output_requires_different_inputs: assert property (
        @($global_clock) Y |-> (A ^ B)
    );

    // A low output implies the inputs are equal.
    check_low_output_requires_equal_inputs: assert property (
        @($global_clock) !Y |-> !(A ^ B)
    );

    // Both low inputs must drive Y low.
    check_00_inputs_drive_low: assert property (
        @($global_clock) (!A && !B) |-> !Y
    );

    // A low and B high must drive Y high.
    check_01_inputs_drive_high: assert property (
        @($global_clock) (!A && B) |-> Y
    );

    // A high and B low must drive Y high.
    check_10_inputs_drive_high: assert property (
        @($global_clock) (A && !B) |-> Y
    );

    // Both high inputs must drive Y low.
    check_11_inputs_drive_low: assert property (
        @($global_clock) (A && B) |-> !Y
    );

endmodule

rtl:
module magnitude_comparator (
    input [3:0] a,
    input [3:0] b,
    output eq,
    output gt
);

    assign eq = (a == b);
    assign gt = (a > b);

endmodule

sva:
module magnitude_comparator_sva (
    input logic clk,
    input logic [3:0] a,
    input logic [3:0] b,
    input logic eq,
    input logic gt
);

    // eq must match the equality comparison of a and b.
    check_eq_matches_comparison: assert property (
        @(posedge clk) eq == (a == b)
    );

    // gt must match the greater-than comparison of a and b.
    check_gt_matches_comparison: assert property (
        @(posedge clk) gt == (a > b)
    );

    // eq and gt cannot both be asserted at the same time.
    check_eq_gt_mutex: assert property (
        @(posedge clk) !(eq && gt)
    );

    // When a is less than b, neither eq nor gt may be asserted.
    check_lt_case_outputs: assert property (
        @(posedge clk) (a < b) |-> (!eq && !gt)
    );

    // If eq is asserted, the inputs must be equal.
    check_eq_implies_equal_inputs: assert property (
        @(posedge clk) eq |-> (a == b)
    );

    // If gt is asserted, a must be greater than b.
    check_gt_implies_input_order: assert property (
        @(posedge clk) gt |-> (a > b)
    );

endmodule

rtl:
module four_bit_converter(
  input [2:0] in,
  output reg [3:0] out
);

  always @(*) begin
    case(in)
      3'b000: out = 4'b0000;
      3'b001: out = 4'b0001;
      3'b010: out = 4'b0010;
      3'b011: out = 4'b0100;
      3'b100: out = 4'b1000;
      3'b101: out = 4'b0001;
      3'b110: out = 4'b0010;
      3'b111: out = 4'b0100;
      default: out = 4'b0000;
    endcase
  end

endmodule

sva:
module four_bit_converter_sva(
    input logic clk,
    input logic [2:0] in,
    input logic [3:0] out
);

    // 000 converts to 0000.
    check_map_000_to_0000: assert property (
        @(posedge clk) (in == 3'b000) |-> (out == 4'b0000)
    );

    // 001 and 101 convert to 0001.
    check_map_001_101_to_0001: assert property (
        @(posedge clk) ((in == 3'b001) || (in == 3'b101)) |-> (out == 4'b0001)
    );

    // 010 and 110 convert to 0010.
    check_map_010_110_to_0010: assert property (
        @(posedge clk) ((in == 3'b010) || (in == 3'b110)) |-> (out == 4'b0010)
    );

    // 011 and 111 convert to 0100.
    check_map_011_111_to_0100: assert property (
        @(posedge clk) ((in == 3'b011) || (in == 3'b111)) |-> (out == 4'b0100)
    );

    // 100 converts to 1000.
    check_map_100_to_1000: assert property (
        @(posedge clk) (in == 3'b100) |-> (out == 4'b1000)
    );

    // 0000 can only come from 000.
    check_rev_0000_from_000: assert property (
        @(posedge clk) (out == 4'b0000) |-> (in == 3'b000)
    );

    // 0001 can only come from 001 or 101.
    check_rev_0001_from_001_101: assert property (
        @(posedge clk) (out == 4'b0001) |-> ((in == 3'b001) || (in == 3'b101))
    );

    // 0010 can only come from 010 or 110.
    check_rev_0010_from_010_110: assert property (
        @(posedge clk) (out == 4'b0010) |-> ((in == 3'b010) || (in == 3'b110))
    );

    // 0100 can only come from 011 or 111.
    check_rev_0100_from_011_111: assert property (
        @(posedge clk) (out == 4'b0100) |-> ((in == 3'b011) || (in == 3'b111))
    );

    // 1000 can only come from 100.
    check_rev_1000_from_100: assert property (
        @(posedge clk) (out == 4'b1000) |-> (in == 3'b100)
    );

endmodule

rtl:
module max_value (
  input a,
  input b,
  input c,
  output out
);

  assign out = (a > b) ? ((a > c) ? a : c) : ((b > c) ? b : c);

endmodule

sva:
module max_value_sva (
    input logic a,
    input logic b,
    input logic c,
    input logic out
);

    // No RTL clock or reset; sample this pure combinational logic on $global_clock.

    // out must match the exact RTL max-selection expression.
    check_function_matches_rtl: assert property (
        @($global_clock)
        out == ((a > b) ? ((a > c) ? a : c) : ((b > c) ? b : c))
    );

    // If a is greater than both b and c, out must select a.
    check_select_a_when_a_is_largest: assert property (
        @($global_clock)
        ((a > b) && (a > c)) |-> (out == a)
    );

    // If a is greater than b but not greater than c, out must select c.
    check_select_c_when_c_beats_a_in_a_branch: assert property (
        @($global_clock)
        ((a > b) && !(a > c)) |-> (out == c)
    );

    // If a is not greater than b and b is greater than c, out must select b.
    check_select_b_when_b_is_largest_in_else_branch: assert property (
        @($global_clock)
        (!(a > b) && (b > c)) |-> (out == b)
    );

    // If a is not greater than b and b is not greater than c, out must select c.
    check_select_c_when_c_wins_else_branch: assert property (
        @($global_clock)
        (!(a > b) && !(b > c)) |-> (out == c)
    );

endmodule

rtl:
module TLATCH (
  input E, SE, CK, D,
  output ECK
);

  reg d;
  always @(posedge CK or negedge E) begin
    if (!E) begin
      d <= 1'b0;
    end else begin
      if (SE) begin
        d <= D;
      end
    end
  end

  assign ECK = E & d;

endmodule

sva:
module TLATCH_sva (
    input logic E,
    input logic SE,
    input logic CK,
    input logic D,
    input logic ECK
);

    // When E is low, the output must be low.
    check_output_low_when_e_low: assert property (
        @(posedge CK) !E |-> !ECK
    );

    // A sampled low E clears the stored state by the next clock sample.
    check_clear_visible_next_clock: assert property (
        @(posedge CK) !E |=> !ECK
    );

    // Sampling D=0 with SE high forces the next sampled output low.
    check_capture_zero_drives_low: assert property (
        @(posedge CK) disable iff (!E) (SE && !D) |=> !ECK
    );

    // In hold mode, a sampled low output stays low on the next clock sample.
    check_hold_preserves_low: assert property (
        @(posedge CK) disable iff (!E) (!SE && !ECK) |=> !ECK
    );

    // A sampled low-to-high output transition requires SE high at the prior sample.
    check_rise_requires_sample_enable: assert property (
        @(posedge CK) disable iff (!E) (!ECK ##1 ECK) |-> SE
    );

    // A sampled low-to-high output transition requires D high at the prior sample.
    check_rise_requires_data_one: assert property (
        @(posedge CK) disable iff (!E) (!ECK ##1 ECK) |-> D
    );

endmodule

module top_module_sva (
    input logic       clk,
    input logic       reset,
    input logic [7:0] a,
    input logic [7:0] b,
    input logic       select,
    input logic [7:0] sum,
    input logic [7:0] mux_out,
    input logic [7:0] final_out
);

    // Reset forces all registered outputs low.
    check_reset_clears_registered_outputs: assert property (
        @(posedge clk) reset |-> ((sum == 8'h00) && (mux_out == 8'h00) && (final_out == 8'h00))
    );

    // First clock after reset release still shows the cleared state.
    check_post_reset_cleared_state: assert property (
        @(posedge clk) disable iff (reset)
        (!$initstate && $past(reset)) |-> ((sum == 8'h00) && (mux_out == 8'h00) && (final_out == 8'h00))
    );

    // Adder output reflects the previous cycle's inputs.
    check_sum_register_update: assert property (
        @(posedge clk) disable iff (reset)
        (!$initstate && !$past(reset)) |-> (sum == ($past(a) + $past(b)))
    );

    // Mux output reflects the previous cycle's selected input.
    check_mux_register_update: assert property (
        @(posedge clk) disable iff (reset)
        (!$initstate && !$past(reset) &&
         (($past(select) === 1'b0) || ($past(select) === 1'b1))) |->
            (mux_out == ($past(select) ? $past(b) : $past(a)))
    );

    // Mux selects a when select was low.
    check_mux_select_low_path: assert property (
        @(posedge clk) disable iff (reset)
        (!$initstate && !$past(reset) && ($past(select) === 1'b0)) |-> (mux_out == $past(a))
    );

    // Mux selects b when select was high.
    check_mux_select_high_path: assert property (
        @(posedge clk) disable iff (reset)
        (!$initstate && !$past(reset) && ($past(select) === 1'b1)) |-> (mux_out == $past(b))
    );

    // OR stage output reflects the previous cycle's sum and mux_out.
    check_final_out_register_update: assert property (
        @(posedge clk) disable iff (reset)
        (!$initstate && !$past(reset)) |-> (final_out == ($past(sum) | $past(mux_out)))
    );

    // Final output matches the two-stage pipeline from primary inputs.
    check_final_out_end_to_end_pipeline: assert property (
        @(posedge clk) disable iff (reset)
        (!$initstate && !$past($initstate) && !$past(reset) && !$past(reset, 2) &&
         (($past(select, 2) === 1'b0) || ($past(select, 2) === 1'b1))) |->
            (final_out == (($past(a, 2) + $past(b, 2)) |
                           ($past(select, 2) ? $past(b, 2) : $past(a, 2))))
    );

endmodule

rtl:
module adder(
    input [3:0] a, 
    input [3:0] b, 
    input cin, 
    output [3:0] sum, 
    output cout
);

    wire c1, c2, c3;
    full_adder fa1(a[0], b[0], cin, sum[0], c1);
    full_adder fa2(a[1], b[1], c1, sum[1], c2);
    full_adder fa3(a[2], b[2], c2, sum[2], c3);
    full_adder fa4(a[3], b[3], c3, sum[3], cout);

endmodule

module full_adder(
    input a, 
    input b, 
    input cin, 
    output sum, 
    output cout
);

    assign sum = a ^ b ^ cin;
    assign cout = (a & b) | (a & cin) | (b & cin);

endmodule

sva:
module adder_sva (
    input logic       clk,
    input logic [3:0] a,
    input logic [3:0] b,
    input logic       cin,
    input logic [3:0] sum,
    input logic       cout
);

    // Concatenated carry and sum match 5-bit addition.
    check_total_sum: assert property (
        @(posedge clk)
        {cout, sum} == ({1'b0, a} + {1'b0, b} + {4'b0, cin})
    );

    // Bit 0 sum matches the full-adder XOR equation.
    check_sum0_equation: assert property (
        @(posedge clk)
        sum[0] == (a[0] ^ b[0] ^ cin)
    );

    // Bit 1 sum uses the carry generated by bit 0.
    check_sum1_equation: assert property (
        @(posedge clk)
        sum[1] == (a[1] ^ b[1] ^
                   ((a[0] & b[0]) | (a[0] & cin) | (b[0] & cin)))
    );

    // With b at zero, the adder reduces to a plus carry-in.
    check_b_zero_increment: assert property (
        @(posedge clk)
        (b == 4'h0) |-> ({cout, sum} == ({1'b0, a} + {4'b0, cin}))
    );

    // With a at zero, the adder reduces to b plus carry-in.
    check_a_zero_increment: assert property (
        @(posedge clk)
        (a == 4'h0) |-> ({cout, sum} == ({1'b0, b} + {4'b0, cin}))
    );

    // All-zero inputs produce an all-zero result.
    check_zero_result: assert property (
        @(posedge clk)
        (a == 4'h0 && b == 4'h0 && cin == 1'b0) |-> ({cout, sum} == 5'h00)
    );

    // 0xF plus carry-in overflows to zero with carry out.
    check_boundary_ff_plus_one: assert property (
        @(posedge clk)
        (a == 4'hF && b == 4'h0 && cin == 1'b1) |-> ({cout, sum} == 5'h10)
    );

    // Adding 0x8 and 0x8 generates a carry with zero sum.
    check_msb_carry_case: assert property (
        @(posedge clk)
        (a == 4'h8 && b == 4'h8 && cin == 1'b0) |-> ({cout, sum} == 5'h10)
    );

    // Maximum operands with carry-in produce 0x1F.
    check_max_plus_max_plus_cin: assert property (
        @(posedge clk)
        (a == 4'hF && b == 4'hF && cin == 1'b1) |-> ({cout, sum} == 5'h1F)
    );

endmodule

rtl:
module johnson_counter #(
  parameter n = 4 // number of output signals
)(
  input clk,
  input rst,
  output reg [n-1:0] out
);


reg [n-1:0] q;

always @(posedge clk, posedge rst) begin
  if (rst) begin
    q <= 0;
    out <= 0;
  end
  else begin
    q <= {q[n-2:0], q[n-1]};
    out <= q;
  end
end

endmodule

sva:
module johnson_counter_sva #(
    parameter int n = 4
)(
    input logic         clk,
    input logic         rst,
    input logic [n-1:0] out,
    input logic [n-1:0] q
);

    // Sampled reset clears both registers by the next clock.
    check_reset_clears_state: assert property (
        @(posedge clk)
        rst |=> ((q == {n{1'b0}}) && (out == {n{1'b0}}))
    );

    // The all-zero state is absorbing in normal operation.
    check_zero_state_is_absorbing: assert property (
        @(posedge clk) disable iff (rst)
        ((q == {n{1'b0}}) && (out == {n{1'b0}})) |=> ((q == {n{1'b0}}) && (out == {n{1'b0}}))
    );

    // Outside sampled reset, q is always the rotated form of out on the next cycle.
    check_q_matches_rotated_out: assert property (
        @(posedge clk) disable iff (rst)
        1'b1 |=> (q == {out[n-2:0], out[n-1]})
    );

    // Outside sampled reset, out either captures the previous q or both registers are reset to zero.
    check_out_tracks_previous_q_or_zero: assert property (
        @(posedge clk) disable iff (rst)
        1'b1 |=> ((out == $past(q)) || ((q == {n{1'b0}}) && (out == {n{1'b0}})))
    );

    // The next sampled state is either the normal shift/capture update or the zeroed reset state.
    check_full_state_update_or_zero: assert property (
        @(posedge clk) disable iff (rst)
        1'b1 |=> (((q == {n{1'b0}}) && (out == {n{1'b0}})) ||
                  ((q == {$past(q[n-2:0]), $past(q[n-1])}) && (out == $past(q))))
    );

endmodule

module comparator_4bit_assertions (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [1:0] COMP
);

    // Less-than comparison must encode as 00.
    check_less_than_encoding: assert property (
        @($global_clock) (A < B) |-> (COMP == 2'b00)
    );

    // Equality comparison must encode as 01.
    check_equal_encoding: assert property (
        @($global_clock) (A == B) |-> (COMP == 2'b01)
    );

    // Greater-than comparison must encode as 10.
    check_greater_than_encoding: assert property (
        @($global_clock) (A > B) |-> (COMP == 2'b10)
    );

    // Output 00 must only occur when A is less than B.
    check_comp_00_means_less_than: assert property (
        @($global_clock) (COMP == 2'b00) |-> (A < B)
    );

    // Output 01 must only occur when A equals B.
    check_comp_01_means_equal: assert property (
        @($global_clock) (COMP == 2'b01) |-> (A == B)
    );

    // Output 10 must only occur when A is greater than B.
    check_comp_10_means_greater_than: assert property (
        @($global_clock) (COMP == 2'b10) |-> (A > B)
    );

    // The unused 11 encoding must never be driven.
    check_comp_never_11: assert property (
        @($global_clock) COMP != 2'b11
    );

    // COMP must always match the full comparator function.
    check_full_compare_function: assert property (
        @($global_clock) COMP == ((A < B) ? 2'b00 : ((A == B) ? 2'b01 : 2'b10))
    );

endmodule

rtl:
module dps_main_counter(		
		input wire iCLOCK,
		input wire inRESET,
		input wire iCONF_WRITE,
		input wire iCONF_ENA,
		input wire iCOUNT_WRITE,
		input wire [1:0] inCOUNT_DQM,
		input wire [63:0] iCOUNT_COUNTER,
		output wire oWORKING,
		output wire [63:0] oCOUNTER
	);


	reg b_working;
	reg [63:0] b_counter;
	always@(posedge iCLOCK or negedge inRESET)begin
		if(!inRESET)begin
			b_working <= 1'b0;
			b_counter <= {64{1'b0}};
		end
		else begin
			if(iCONF_WRITE)begin
				b_working <= iCONF_ENA;
			end
			begin
				if(b_working)begin
					b_counter <= b_counter + 64'h00000001;
				end
				else begin
					if(iCOUNT_WRITE)begin
						b_counter[31:0] <= (!inCOUNT_DQM[0])? iCOUNT_COUNTER[31:0] : b_counter[31:0];
						b_counter[63:32] <= (!inCOUNT_DQM[1])? iCOUNT_COUNTER[63:32] : b_counter[63:32];
					end
				end
			end
		end
	end

	assign oCOUNTER = b_counter;
	assign oWORKING = b_working;

endmodule

sva:
module dps_main_counter_sva (
    input logic        iCLOCK,
    input logic        inRESET,
    input logic        iCONF_WRITE,
    input logic        iCONF_ENA,
    input logic        iCOUNT_WRITE,
    input logic [1:0]  inCOUNT_DQM,
    input logic [63:0] iCOUNT_COUNTER,
    input logic        oWORKING,
    input logic [63:0] oCOUNTER
);

    // Reset clears working and counter.
    check_reset_clears_state: assert property (
        @(posedge iCLOCK) !inRESET |-> (oWORKING == 1'b0 && oCOUNTER == 64'h0)
    );

    // A configuration write updates working from iCONF_ENA.
    check_conf_write_updates_working: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        iCONF_WRITE |=> (oWORKING == $past(iCONF_ENA))
    );

    // Without a configuration write, working holds its value.
    check_working_holds_without_conf_write: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        !iCONF_WRITE |=> (oWORKING == $past(oWORKING))
    );

    // When working is set, the counter increments by one.
    check_working_increments_counter: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        oWORKING |=> (oCOUNTER == ($past(oCOUNTER) + 64'd1))
    );

    // When stopped and not writing, the counter holds.
    check_stopped_no_write_holds_counter: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (!oWORKING && !iCOUNT_WRITE) |=> (oCOUNTER == $past(oCOUNTER))
    );

    // When stopped and low word is unmasked, bits [31:0] load from iCOUNT_COUNTER.
    check_stopped_write_loads_low_half: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (!oWORKING && iCOUNT_WRITE && !inCOUNT_DQM[0]) |=> (oCOUNTER[31:0] == $past(iCOUNT_COUNTER[31:0]))
    );

    // When stopped and low word is masked, bits [31:0] hold.
    check_stopped_write_masks_low_half: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (!oWORKING && iCOUNT_WRITE && inCOUNT_DQM[0]) |=> (oCOUNTER[31:0] == $past(oCOUNTER[31:0]))
    );

    // When stopped and high word is unmasked, bits [63:32] load from iCOUNT_COUNTER.
    check_stopped_write_loads_high_half: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (!oWORKING && iCOUNT_WRITE && !inCOUNT_DQM[1]) |=> (oCOUNTER[63:32] == $past(iCOUNT_COUNTER[63:32]))
    );

    // When stopped and high word is masked, bits [63:32] hold.
    check_stopped_write_masks_high_half: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (!oWORKING && iCOUNT_WRITE && inCOUNT_DQM[1]) |=> (oCOUNTER[63:32] == $past(oCOUNTER[63:32]))
    );

endmodule

rtl:
module SNPS_CLOCK_GATE_HIGH_d_ff_en_W64_0_32 (
  input CLK, EN, TE,
  output reg ENCLK
);

  // Implement a D flip-flop with enable
  reg D, Q;
  always @(posedge CLK) begin
    if (EN) begin
      Q <= D;
    end
  end

  // Implement a transparent latch
  reg TL;
  always @(posedge CLK) begin
    if (TE) begin
      TL <= Q;
    end
  end

  // Implement the clock gate
  always @(posedge CLK) begin
    if (TE) begin
      ENCLK <= 1'b1;
    end else if (EN) begin
      ENCLK <= CLK;
    end else begin
      ENCLK <= 1'b0;
    end
  end
endmodule

sva:
module SNPS_CLOCK_GATE_HIGH_d_ff_en_W64_0_32_sva (
    input logic CLK,
    input logic EN,
    input logic TE,
    input logic ENCLK,
    input logic D,
    input logic Q,
    input logic TL
);

    // Q captures D when EN is high.
    check_q_captures_d_when_en: assert property (
        @(posedge CLK) EN |=> (Q === $past(D))
    );

    // Q holds its value when EN is low.
    check_q_holds_when_en_low: assert property (
        @(posedge CLK) !EN |=> (Q === $past(Q))
    );

    // TL captures the prior Q value when TE is high.
    check_tl_captures_q_when_te: assert property (
        @(posedge CLK) TE |=> (TL === $past(Q))
    );

    // TL holds its value when TE is low.
    check_tl_holds_when_te_low: assert property (
        @(posedge CLK) !TE |=> (TL === $past(TL))
    );

    // TE forces ENCLK high.
    check_enclk_high_when_te: assert property (
        @(posedge CLK) TE |=> (ENCLK == 1'b1)
    );

    // EN drives ENCLK high when TE is low.
    check_enclk_high_when_en_only: assert property (
        @(posedge CLK) (!TE && EN) |=> (ENCLK == 1'b1)
    );

    // With both controls low, ENCLK is driven low.
    check_enclk_low_when_disabled: assert property (
        @(posedge CLK) (!TE && !EN) |=> (ENCLK == 1'b0)
    );

endmodule

