sva:
module sky130_fd_sc_ls__xor3_sva (
    input logic clk,
    input logic X,
    input logic A,
    input logic B,
    input logic C
);

    // Output equals the three-input XOR of A, B, and C.
    check_x_matches_xor3_function: assert property (
        @(posedge clk) X === (A ^ B ^ C)
    );

    // When A and B are equal known bits, output matches C.
    check_ab_equal_output_matches_c: assert property (
        @(posedge clk)
        (((A === 1'b0) && (B === 1'b0)) || ((A === 1'b1) && (B === 1'b1)))
        |-> (X === C)
    );

    // When A and B differ as known bits, output inverts C.
    check_ab_different_output_inverts_c: assert property (
        @(posedge clk)
        (((A === 1'b0) && (B === 1'b1)) || ((A === 1'b1) && (B === 1'b0)))
        |-> (X === ~C)
    );

    // When B and C are equal known bits, output matches A.
    check_bc_equal_output_matches_a: assert property (
        @(posedge clk)
        (((B === 1'b0) && (C === 1'b0)) || ((B === 1'b1) && (C === 1'b1)))
        |-> (X === A)
    );

    // When B and C differ as known bits, output inverts A.
    check_bc_different_output_inverts_a: assert property (
        @(posedge clk)
        (((B === 1'b0) && (C === 1'b1)) || ((B === 1'b1) && (C === 1'b0)))
        |-> (X === ~A)
    );

    // When A and C are equal known bits, output matches B.
    check_ac_equal_output_matches_b: assert property (
        @(posedge clk)
        (((A === 1'b0) && (C === 1'b0)) || ((A === 1'b1) && (C === 1'b1)))
        |-> (X === B)
    );

    // When A and C differ as known bits, output inverts B.
    check_ac_different_output_inverts_b: assert property (
        @(posedge clk)
        (((A === 1'b0) && (C === 1'b1)) || ((A === 1'b1) && (C === 1'b0)))
        |-> (X === ~B)
    );

endmodule

rtl:
module or4 (
    output X,
    input A,
    input B,
    input C,
    input D
);

    wire [3:0] or_input;
    assign or_input = {A, B, C, D};

    or base (
        X,
        or_input[0],
        or_input[1],
        or_input[2],
        or_input[3]
    );

endmodule

sva:
module or4_assertions (
    input logic X,
    input logic A,
    input logic B,
    input logic C,
    input logic D
);

    // X must equal the OR of all four inputs.
    check_or_function: assert property (
        @($global_clock) X == (A | B | C | D)
    );

    // A high must drive X high.
    check_a_drives_x_high: assert property (
        @($global_clock) A |-> X
    );

    // B high must drive X high.
    check_b_drives_x_high: assert property (
        @($global_clock) B |-> X
    );

    // C high must drive X high.
    check_c_drives_x_high: assert property (
        @($global_clock) C |-> X
    );

    // D high must drive X high.
    check_d_drives_x_high: assert property (
        @($global_clock) D |-> X
    );

    // All inputs low must drive X low.
    check_all_low_drives_x_low: assert property (
        @($global_clock) (!A && !B && !C && !D) |-> !X
    );

    // X low implies no input is high.
    check_x_low_means_all_inputs_low: assert property (
        @($global_clock) !X |-> (!A && !B && !C && !D)
    );

endmodule

rtl:
module adder(
    input [3:0] A,
    input [3:0] B,
    input C_in,
    output [3:0] S,
    output C_out
);

    wire [4:0] sum;
    wire C_out1;

    assign sum = A + B + C_in;
    assign S = sum[3:0];
    assign C_out = sum[4] | C_out1;
    assign C_out1 = sum[3] & sum[2] | (sum[3] | sum[2]) & sum[1] | (sum[3] | sum[2] | sum[1]) & sum[0];

endmodule

sva:
module adder_sva(
    input logic [3:0] A,
    input logic [3:0] B,
    input logic C_in,
    input logic [3:0] S,
    input logic C_out,
    input logic [4:0] sum,
    input logic C_out1
);

    // No clock or reset exists in the RTL; sample on the global formal clock.
    // The DUT is purely combinational.

    // S matches the low four bits of A + B + C_in.
    check_sum_low_bits: assert property (
        @($global_clock)
        ({1'b0, S} == (({1'b0, A} + {1'b0, B} + C_in) & 5'h0F))
    );

    // S is driven directly from sum[3:0].
    check_sum_slice_to_s: assert property (
        @($global_clock)
        (S == sum[3:0])
    );

    // C_out is the OR of sum[4] and C_out1.
    check_cout_or_relation: assert property (
        @($global_clock)
        (C_out == (sum[4] | C_out1))
    );

    // C_out1 matches the implemented reduction of sum[3:0].
    check_cout1_formula: assert property (
        @($global_clock)
        (C_out1 == (
            (sum[3] & sum[2]) |
            ((sum[3] | sum[2]) & sum[1]) |
            ((sum[3] | sum[2] | sum[1]) & sum[0])
        ))
    );

    // An arithmetic carry from A + B + C_in must raise C_out.
    check_cout_on_arithmetic_carry: assert property (
        @($global_clock)
        ((({1'b0, A} + {1'b0, B} + C_in) & 5'h10) != 5'h00) |-> C_out
    );

    // sum[4] alone is sufficient to raise C_out.
    check_cout_on_sum_msb: assert property (
        @($global_clock)
        sum[4] |-> C_out
    );

    // sum[3] and sum[2] high force C_out1 high.
    check_cout1_on_top_pair: assert property (
        @($global_clock)
        (sum[3] & sum[2]) |-> C_out1
    );

    // sum[1] with either sum[3] or sum[2] high forces C_out1 high.
    check_cout1_on_mid_pair: assert property (
        @($global_clock)
        ((sum[3] | sum[2]) & sum[1]) |-> C_out1
    );

    // sum[0] with any higher sum bit high forces C_out1 high.
    check_cout1_on_low_pair: assert property (
        @($global_clock)
        ((sum[3] | sum[2] | sum[1]) & sum[0]) |-> C_out1
    );

    // With neither source active, C_out must stay low.
    check_cout_low_without_sources: assert property (
        @($global_clock)
        (!sum[4] && !C_out1) |-> !C_out
    );

endmodule

module binary_counter_sva (
    input logic       clk,
    input logic       rst,
    input logic       en,
    input logic [3:0] count
);

    // Reset clears the counter.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |=> (count == 4'b0000)
    );

    // Enable increments the counter by one modulo 16.
    check_increment_when_enabled: assert property (
        @(posedge clk) disable iff (rst) en |=> (count == ($past(count) + 4'd1))
    );

    // When not enabled, the counter holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (rst) !en |=> (count == $past(count))
    );

    // Reset has priority even if enable is also high.
    check_reset_priority_over_enable: assert property (
        @(posedge clk) (rst && en) |=> (count == 4'b0000)
    );

endmodule

rtl:
module five_input_gate (in1, in2, in3, in4, in5, out);

input in1, in2, in3, in4, in5;
output out;

wire temp1, temp2;

// AND the first two inputs
and and1(temp1, in1, in2);

// AND the third and fourth inputs
and and2(temp2, in3, in4);

// OR the two temporary outputs and the fifth input
or or1(out, temp1, temp2, in5);

endmodule

sva:
module five_input_gate_sva (
    input logic clk,
    input logic in1,
    input logic in2,
    input logic in3,
    input logic in4,
    input logic in5,
    input logic out
);

    // Output matches the implemented OR-of-ANDs function.
    check_out_matches_boolean_function: assert property (
        @(posedge clk) out == ((in1 & in2) | (in3 & in4) | in5)
    );

    // Fifth input directly forces the output high.
    check_in5_forces_out_high: assert property (
        @(posedge clk) in5 |-> out
    );

    // First input pair forces the output high when both are high.
    check_first_pair_forces_out_high: assert property (
        @(posedge clk) (in1 & in2) |-> out
    );

    // Second input pair forces the output high when both are high.
    check_second_pair_forces_out_high: assert property (
        @(posedge clk) (in3 & in4) |-> out
    );

    // A high output must come from at least one implemented source term.
    check_out_high_has_active_source: assert property (
        @(posedge clk) out |-> ((in1 & in2) | (in3 & in4) | in5)
    );

    // Output stays low when all three OR terms are low.
    check_out_low_when_all_terms_low: assert property (
        @(posedge clk) ((!(in1 & in2)) && (!(in3 & in4)) && (!in5)) |-> (!out)
    );

endmodule

rtl:
module adder_subtractor (input [15:0] A, B, input C, CLK, output reg [15:0] R);

always @(posedge CLK) begin
    if (C == 0) // addition
        R <= A + B;
    else // subtraction
        R <= A - B;
end

endmodule

sva:
module adder_subtractor_sva (
    input logic [15:0] A,
    input logic [15:0] B,
    input logic        C,
    input logic        CLK,
    input logic [15:0] R
);

    // R must hold the prior cycle's selected add/sub result.
    check_registered_result: assert property (
        @(posedge CLK) disable iff ($initstate)
        R == (($past(C) == 1'b1) ? ($past(A) - $past(B)) : ($past(A) + $past(B)))
    );

    // In add mode, R captures the prior cycle sum.
    check_addition_mode_result: assert property (
        @(posedge CLK) disable iff ($initstate)
        ($past(C) == 1'b0) |-> (R == ($past(A) + $past(B)))
    );

    // In subtract mode, R captures the prior cycle difference.
    check_subtraction_mode_result: assert property (
        @(posedge CLK) disable iff ($initstate)
        ($past(C) == 1'b1) |-> (R == ($past(A) - $past(B)))
    );

    // Subtracting equal prior operands must produce zero.
    check_equal_operands_subtract_zero: assert property (
        @(posedge CLK) disable iff ($initstate)
        (($past(C) == 1'b1) && ($past(A) == $past(B))) |-> (R == 16'h0000)
    );

endmodule

module ODDR_sva (
    input logic D1,
    input logic D2,
    input logic C,
    input logic CE,
    input logic R,
    input logic Q
);

    // Clock is posedge C; this RTL has no reset.
    // With CE high and R low, Q loads D1.
    check_capture_d1: assert property (
        @(posedge C) disable iff (1'b0)
        (CE === 1'b1 && R === 1'b0) |=> (Q === $past(D1))
    );

    // With CE high and R not low, Q loads D2.
    check_capture_d2: assert property (
        @(posedge C) disable iff (1'b0)
        (CE === 1'b1 && R !== 1'b0) |=> (Q === $past(D2))
    );

    // With CE not high, Q holds its previous value.
    check_hold_when_ce_not_high: assert property (
        @(posedge C) disable iff (1'b0)
        (CE !== 1'b1) |=> (Q === $past(Q))
    );

endmodule

rtl:
module zet_next_or_not (
    input [1:0] prefix,
    input [7:1] opcode,
    input cx_zero,
    input zf,
    input ext_int,
    output next_in_opco,
    output next_in_exec,
    output use_eintp
  );

  wire exit_z, cmp_sca, exit_rep, valid_ops;

  assign cmp_sca = opcode[7] & opcode[2] & opcode[1];
  assign exit_z = prefix[0] ?  (cmp_sca ? ~zf : 1'b0 )
                            :  (cmp_sca ? zf : 1'b0 );
  assign exit_rep = cx_zero | exit_z;
  assign valid_ops = (opcode[7:1]==7'b1010_010   || opcode[7:1]==7'b1010_011   || opcode[7:1]==7'b1010_101   || opcode[7:1]==7'b0110_110   || opcode[7:1]==7'b0110_111   || opcode[7:1]==7'b1010_110   || opcode[7:1]==7'b1010_111); assign next_in_exec = prefix[1] && valid_ops && !exit_rep && !ext_int;
  assign next_in_opco = prefix[1] && valid_ops && cx_zero;
  assign use_eintp    = prefix[1] && valid_ops && !exit_z;

endmodule

sva:
module zet_next_or_not_sva (
    input logic [1:0] prefix,
    input logic [7:1] opcode,
    input logic cx_zero,
    input logic zf,
    input logic ext_int,
    input logic next_in_opco,
    input logic next_in_exec,
    input logic use_eintp
);

    wire cmp_sca;
    wire exit_z;
    wire exit_rep;
    wire valid_ops;

    assign cmp_sca  = opcode[7] & opcode[2] & opcode[1];
    assign exit_z   = prefix[0] ? (cmp_sca ? ~zf : 1'b0)
                                : (cmp_sca ?  zf : 1'b0);
    assign exit_rep = cx_zero | exit_z;
    assign valid_ops = (opcode[7:1] == 7'b1010_010) ||
                       (opcode[7:1] == 7'b1010_011) ||
                       (opcode[7:1] == 7'b1010_101) ||
                       (opcode[7:1] == 7'b0110_110) ||
                       (opcode[7:1] == 7'b0110_111) ||
                       (opcode[7:1] == 7'b1010_110) ||
                       (opcode[7:1] == 7'b1010_111);

    // Purely combinational DUT; sample on the formal global clock.

    // next_in_exec must match its combinational definition.
    check_next_in_exec_definition: assert property (
        @($global_clock) disable iff (1'b0)
        next_in_exec == (prefix[1] && valid_ops && !exit_rep && !ext_int)
    );

    // next_in_opco must match its combinational definition.
    check_next_in_opco_definition: assert property (
        @($global_clock) disable iff (1'b0)
        next_in_opco == (prefix[1] && valid_ops && cx_zero)
    );

    // use_eintp must match its combinational definition.
    check_use_eintp_definition: assert property (
        @($global_clock) disable iff (1'b0)
        use_eintp == (prefix[1] && valid_ops && !exit_z)
    );

    // Without prefix[1], all outputs must be low.
    check_outputs_low_without_prefix1: assert property (
        @($global_clock) disable iff (1'b0)
        !prefix[1] |-> (!next_in_exec && !next_in_opco && !use_eintp)
    );

    // Invalid opcodes must not assert any output.
    check_outputs_low_for_invalid_opcode: assert property (
        @($global_clock) disable iff (1'b0)
        !valid_ops |-> (!next_in_exec && !next_in_opco && !use_eintp)
    );

    // cx_zero always blocks next_in_exec through exit_rep.
    check_cx_zero_blocks_exec: assert property (
        @($global_clock) disable iff (1'b0)
        cx_zero |-> !next_in_exec
    );

    // ext_int always blocks next_in_exec.
    check_ext_int_blocks_exec: assert property (
        @($global_clock) disable iff (1'b0)
        ext_int |-> !next_in_exec
    );

    // next_in_exec implies use_eintp is also asserted.
    check_exec_implies_use_eintp: assert property (
        @($global_clock) disable iff (1'b0)
        next_in_exec |-> use_eintp
    );

    // next_in_exec and next_in_opco cannot be high together.
    check_exec_opco_mutex: assert property (
        @($global_clock) disable iff (1'b0)
        !(next_in_exec && next_in_opco)
    );

    // When cmp_sca is low, use_eintp depends only on prefix[1] and valid_ops.
    check_use_eintp_when_not_cmp_sca: assert property (
        @($global_clock) disable iff (1'b0)
        !cmp_sca |-> (use_eintp == (prefix[1] && valid_ops))
    );

endmodule

rtl:
module johnson_counter (
    input wire clk,
    input wire rst_n,
    output reg [7:0] out_vec
);

reg [7:0] state;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        state <= 8'b00000000;
    end else begin
        state <= {state[6:0], state[7]};
    end
end

always @* begin
    case(state)
        8'b00000000: out_vec = 8'b00000000;
        8'b10000000: out_vec = 8'b10000000;
        8'b11000000: out_vec = 8'b11000000;
        8'b11100000: out_vec = 8'b11100000;
        8'b11110000: out_vec = 8'b11110000;
        8'b01111000: out_vec = 8'b01111000;
        8'b00111100: out_vec = 8'b00111100;
        8'b00011110: out_vec = 8'b00011110;
        8'b00001111: out_vec = 8'b00001111;
        default: out_vec = 8'b00000000;
    endcase
end

endmodule
module binary_number_module (
    input wire [3:0] in_vec,
    output reg [3:0] out_vec,
    output reg msb_out,
    output reg mid_out,
    output reg lsb_out
);

wire [3:0] temp_vec;

assign temp_vec = in_vec;

always @* begin
    out_vec = temp_vec;
    msb_out = temp_vec[3];
    mid_out = temp_vec[2];
    lsb_out = temp_vec[1];
end

endmodule
module functional_module (
    input wire [7:0] in_vec_1,
    input wire [3:0] in_vec_2,
    output reg [7:0] out_vec
);

always @* begin
    out_vec = in_vec_1 | {4'b0000, in_vec_2};
end

endmodule
module top_module ( 
    input wire clk, 
    input wire rst_n, 
    input wire [3:0] in_vec, 
    output wire [7:0] out_vec, 
    output wire msb_out, 
    output wire mid_out, 
    output wire lsb_out 
);

wire [7:0] jc_out;
wire [3:0] bn_out;
wire bn_msb_out;
wire bn_mid_out;
wire bn_lsb_out;

johnson_counter jc_inst (
    .clk(clk),
    .rst_n(rst_n),
    .out_vec(jc_out)
);

binary_number_module bn_inst (
    .in_vec(in_vec),
    .out_vec(bn_out),
    .msb_out(bn_msb_out),
    .mid_out(bn_mid_out),
    .lsb_out(bn_lsb_out)
);

functional_module fm_inst (
    .in_vec_1(jc_out),
    .in_vec_2(bn_out),
    .out_vec(out_vec)
);

assign msb_out = bn_msb_out;
assign mid_out = bn_mid_out;
assign lsb_out = bn_lsb_out;

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic rst_n,
    input logic [3:0] in_vec,
    input logic [7:0] out_vec,
    input logic msb_out,
    input logic mid_out,
    input logic lsb_out,
    input logic [7:0] jc_out,
    input logic [3:0] bn_out,
    input logic [7:0] state
);

    // A sampled low reset leaves the counter state cleared on the next clock.
    check_reset_clears_state: assert property (
        @(posedge clk) !rst_n |=> (state == 8'b00000000)
    );

    // A sampled low reset leaves the decoded counter output cleared on the next clock.
    check_reset_clears_jc_out: assert property (
        @(posedge clk) !rst_n |=> (jc_out == 8'b00000000)
    );

    // The listed decode states pass through unchanged to jc_out.
    check_jc_decode_known_states: assert property (
        @(posedge clk) disable iff (!rst_n)
        (state inside {8'b00000000, 8'b10000000, 8'b11000000, 8'b11100000,
                       8'b11110000, 8'b01111000, 8'b00111100, 8'b00011110,
                       8'b00001111}) |-> (jc_out == state)
    );

    // Any unlisted decode state drives jc_out to zero.
    check_jc_decode_default_zero: assert property (
        @(posedge clk) disable iff (!rst_n)
        !(state inside {8'b00000000, 8'b10000000, 8'b11000000, 8'b11100000,
                        8'b11110000, 8'b01111000, 8'b00111100, 8'b00011110,
                        8'b00001111}) |-> (jc_out == 8'b00000000)
    );

    // Once the counter state is zero, it stays zero on later clocks.
    check_zero_state_sticky: assert property (
        @(posedge clk) disable iff (!rst_n)
        (state == 8'b00000000) |=> (state == 8'b00000000)
    );

    // The binary-number block copies in_vec directly to bn_out.
    check_binary_vector_copy: assert property (
        @(posedge clk) disable iff (!rst_n)
        (bn_out == in_vec)
    );

    // The top MSB output reflects bit 3 of in_vec.
    check_msb_output_matches_input: assert property (
        @(posedge clk) disable iff (!rst_n)
        (msb_out == in_vec[3])
    );

    // The top MID output reflects bit 2 of in_vec.
    check_mid_output_matches_input: assert property (
        @(posedge clk) disable iff (!rst_n)
        (mid_out == in_vec[2])
    );

    // The top LSB output reflects bit 1 of in_vec.
    check_lsb_output_matches_input: assert property (
        @(posedge clk) disable iff (!rst_n)
        (lsb_out == in_vec[1])
    );

    // The functional block ORs jc_out with the zero-extended binary vector.
    check_functional_or_result: assert property (
        @(posedge clk) disable iff (!rst_n)
        (out_vec == (jc_out | {4'b0000, bn_out}))
    );

    // When the counter state is zero, out_vec is just in_vec in the low nibble.
    check_zero_state_top_output: assert property (
        @(posedge clk) disable iff (!rst_n)
        (state == 8'b00000000) |-> (out_vec == {4'b0000, in_vec})
    );

    // A sampled low reset leaves out_vec equal to the low-nibble input on the next clock.
    check_reset_top_output: assert property (
        @(posedge clk) !rst_n |=> (out_vec == {4'b0000, in_vec})
    );

endmodule

rtl:
module clk_phase_shifter (
  input clk,
  input [7:0] shift,
  output reg clk_shifted
);

parameter n = 8; // number of bits in the phase shift value

reg [n-1:0] shift_reg;
reg [n-1:0] shift_reg_next;
reg [n-1:0] shift_reg_last;
reg clk_shifted_last;
integer i;

always @(posedge clk) begin
  shift_reg_last <= shift_reg;
  clk_shifted_last <= clk_shifted;
end

always @(posedge clk) begin
  shift_reg_next[0] <= clk;
  for (i = 1; i < n; i = i + 1) begin
    shift_reg_next[i] <= shift_reg[i-1];
  end
end

always @(posedge clk) begin
  if (shift == 0) begin
    clk_shifted <= clk;
  end else begin
    clk_shifted <= shift_reg_last[n-1];
  end
end

always @(posedge clk) begin
  shift_reg <= shift_reg_next;
end

endmodule

sva:
module clk_phase_shifter_sva (
    input logic clk,
    input logic [7:0] shift,
    input logic clk_shifted,
    input logic [7:0] shift_reg,
    input logic [7:0] shift_reg_next,
    input logic [7:0] shift_reg_last,
    input logic clk_shifted_last
);
    localparam int n = 8;

    // shift_reg_last captures the previous cycle's shift_reg.
    check_shift_reg_last_tracks_shift_reg: assert property (
        @(posedge clk) 1'b1 |=> (shift_reg_last === $past(shift_reg))
    );

    // clk_shifted_last captures the previous cycle's clk_shifted.
    check_clk_shifted_last_tracks_clk_shifted: assert property (
        @(posedge clk) 1'b1 |=> (clk_shifted_last === $past(clk_shifted))
    );

    // The LSB of shift_reg_next is loaded HIGH because clk is HIGH at posedge.
    check_shift_reg_next_lsb_loads_clock_high: assert property (
        @(posedge clk) 1'b1 |=> (shift_reg_next[0] === 1'b1)
    );

    // The upper bits of shift_reg_next shift in the previous shift_reg value.
    check_shift_reg_next_upper_bits_shift_previous_reg: assert property (
        @(posedge clk) 1'b1 |=> (shift_reg_next[n-1:1] === $past(shift_reg[n-2:0]))
    );

    // shift_reg captures the previous cycle's shift_reg_next.
    check_shift_reg_tracks_previous_next: assert property (
        @(posedge clk) 1'b1 |=> (shift_reg === $past(shift_reg_next))
    );

    // A zero shift selection forces clk_shifted HIGH on the next sampled cycle.
    check_zero_shift_drives_high_next_cycle: assert property (
        @(posedge clk) (shift == 8'h00) |=> (clk_shifted === 1'b1)
    );

    // A nonzero shift selection uses the previous cycle's shift_reg_last MSB.
    check_nonzero_shift_uses_delayed_tap: assert property (
        @(posedge clk) (shift != 8'h00) |=> (clk_shifted === $past(shift_reg_last[n-1]))
    );

    // After 16 cycles, shift_reg is fully filled with ones.
    check_shift_reg_eventually_all_ones: assert property (
        @(posedge clk) 1'b1 |=> ##15 (shift_reg === 8'hFF)
    );

    // After 17 cycles, shift_reg_last is fully filled with ones.
    check_shift_reg_last_eventually_all_ones: assert property (
        @(posedge clk) 1'b1 |=> ##16 (shift_reg_last === 8'hFF)
    );

    // After 18 cycles, clk_shifted is driven HIGH regardless of shift.
    check_clk_shifted_eventually_high: assert property (
        @(posedge clk) 1'b1 |=> ##17 (clk_shifted === 1'b1)
    );

endmodule

rtl:
module pipelined_nor_gate(
    input a,
    input b,
    output out
);

reg pipe1, pipe2;

always @(a or b) begin
    pipe1 <= ~(a & b);
end

always @(pipe1) begin
    pipe2 <= ~pipe1;
end

assign out = pipe2;

endmodule

module top_module(
    input a,
    input b,
    output out
);

wire pipe1, pipe2;
pipelined_nor_gate g1(a, b, pipe1);
pipelined_nor_gate g2(pipe1, pipe1, pipe2);
pipelined_nor_gate g3(pipe2, pipe2, out);

endmodule

sva:
module top_module_sva (
    input logic a,
    input logic b,
    input logic pipe1,
    input logic pipe2,
    input logic out,
    input logic g1_pipe1,
    input logic g2_pipe1,
    input logic g3_pipe1
);

    // Primary input changes update g1's first stage to ~(a & b).
    check_g1_input_updates_first_stage: assert property (
        @($global_clock) (!$initstate && ($changed(a) || $changed(b))) |-> (g1_pipe1 == ~(a & b))
    );

    // A g1 first-stage change updates the top-level pipe1 output to ~g1_pipe1.
    check_g1_first_stage_updates_pipe1: assert property (
        @($global_clock) (!$initstate && $changed(g1_pipe1)) |-> (pipe1 == ~g1_pipe1)
    );

    // A pipe1 change updates g2's first stage to ~(pipe1 & pipe1).
    check_g2_input_updates_first_stage: assert property (
        @($global_clock) (!$initstate && $changed(pipe1)) |-> (g2_pipe1 == ~(pipe1 & pipe1))
    );

    // A g2 first-stage change updates the top-level pipe2 output to ~g2_pipe1.
    check_g2_first_stage_updates_pipe2: assert property (
        @($global_clock) (!$initstate && $changed(g2_pipe1)) |-> (pipe2 == ~g2_pipe1)
    );

    // A pipe2 change updates g3's first stage to ~(pipe2 & pipe2).
    check_g3_input_updates_first_stage: assert property (
        @($global_clock) (!$initstate && $changed(pipe2)) |-> (g3_pipe1 == ~(pipe2 & pipe2))
    );

    // A g3 first-stage change updates out to ~g3_pipe1.
    check_g3_first_stage_updates_out: assert property (
        @($global_clock) (!$initstate && $changed(g3_pipe1)) |-> (out == ~g3_pipe1)
    );

endmodule

rtl:
module adder_overflow (
    input [7:0] a,
    input [7:0] b,
    output [7:0] s,
    output overflow
);

    wire [7:0] sum;
    wire carry;

    assign sum = a + b;
    assign carry = sum[7] ^ a[7] ^ b[7];

    assign s = sum;
    assign overflow = carry;

endmodule

sva:
module adder_overflow_assertions (
    input logic       clk,
    input logic [7:0] a,
    input logic [7:0] b,
    input logic [7:0] s,
    input logic       overflow
);

    // Sum output matches the 8-bit addition of the inputs.
    check_sum_matches_addition: assert property (
        @(posedge clk) s == (a + b)
    );

    // Lower 7 sum bits match the lower 7-bit addition result.
    check_lower_bits_match_addition: assert property (
        @(posedge clk) s[6:0] == (a[6:0] + b[6:0])
    );

    // Overflow output matches the RTL XOR equation.
    check_overflow_matches_xor_equation: assert property (
        @(posedge clk) overflow == (s[7] ^ a[7] ^ b[7])
    );

    // Overflow equals the carry generated by adding the lower 7 bits.
    check_overflow_matches_lower_carry: assert property (
        @(posedge clk) overflow == (({1'b0, a[6:0]} + {1'b0, b[6:0]})[7])
    );

    // A zero on input a passes b through and clears overflow.
    check_a_zero_passthrough: assert property (
        @(posedge clk) (a == 8'h00) |-> ((s == b) && (overflow == 1'b0))
    );

    // A zero on input b passes a through and clears overflow.
    check_b_zero_passthrough: assert property (
        @(posedge clk) (b == 8'h00) |-> ((s == a) && (overflow == 1'b0))
    );

endmodule

rtl:
module sirv_aon_porrst(
  input  clk,
  output reg porrst_n
);

  reg [31:0] counter = 0;

  `ifdef FPGA_SOURCE
      // In FPGA, we have no PORRST circuit
      assign porrst_n = 1'b1;
  `else
      // Generate PORRST signal using circuit
      always @(posedge clk) begin
        if (counter < 100) begin
          counter <= counter + 1;
          porrst_n <= 1'b0;
        end else begin
          porrst_n <= 1'b1;
        end
      end
  `endif

endmodule

sva:
module sirv_aon_porrst_sva (
    input logic        clk,
    input logic        porrst_n,
    input logic [31:0] counter
);

    // The counter can only hold its value or increment by one each cycle.
    check_counter_hold_or_increment: assert property (
        @(posedge clk) disable iff (1'b0)
        1'b1 |=> ((counter == $past(counter)) || (counter == ($past(counter) + 32'd1)))
    );

`ifdef FPGA_SOURCE
    // In FPGA builds, POR reset is tied permanently high.
    check_porrst_tied_high_fpga: assert property (
        @(posedge clk) disable iff (1'b0)
        porrst_n == 1'b1
    );
`else
    // While the counter is below 100, the next cycle increments it and keeps POR reset low.
    check_counting_phase_increment_and_low: assert property (
        @(posedge clk) disable iff (1'b0)
        (counter < 32'd100) |=> ((counter == ($past(counter) + 32'd1)) && (porrst_n == 1'b0))
    );

    // Once the counter is 100 or more, the next cycle holds it and drives POR reset high.
    check_saturated_phase_hold_and_high: assert property (
        @(posedge clk) disable iff (1'b0)
        (counter >= 32'd100) |=> ((counter == $past(counter)) && (porrst_n == 1'b1))
    );

    // Transitioning from 99 to 100 still leaves POR reset low in that next cycle.
    check_reaching_100_keeps_porrst_low: assert property (
        @(posedge clk) disable iff (1'b0)
        (counter == 32'd99) |=> ((counter == 32'd100) && (porrst_n == 1'b0))
    );

    // With the counter at 100, the following cycle keeps 100 and deasserts POR reset high.
    check_holding_100_keeps_porrst_high: assert property (
        @(posedge clk) disable iff (1'b0)
        (counter == 32'd100) |=> ((counter == 32'd100) && (porrst_n == 1'b1))
    );
`endif

endmodule

rtl:
module dff_chain (
    input clk,
    input reset,            // Asynchronous reset
    input [7:0] d,
    output reg [7:0] q
);

reg [7:0] q1, q2, q3;

always @(posedge clk or negedge reset) begin
    if (reset == 0) begin
        q1 <= 1'b0;
        q2 <= 1'b0;
        q3 <= 1'b0;
        q <= 1'b0;
    end else begin
        q1 <= d;
        q2 <= q1;
        q3 <= q2;
        q <= q3;
    end
end

endmodule

module top_module (
    input clk,
    input reset,            // Asynchronous reset
    input [7:0] d,
    output [7:0] q
);

dff_chain dff_inst (
    .clk(clk),
    .reset(reset),
    .d(d),
    .q(q)
);

endmodule

sva:
module dff_chain_sva (
    input logic        clk,
    input logic        reset,
    input logic [7:0]  d,
    input logic [7:0]  q,
    input logic [7:0]  q1,
    input logic [7:0]  q2,
    input logic [7:0]  q3
);

    // A sampled low reset leaves every stage cleared by the next clock.
    check_reset_clears_all_stages: assert property (
        @(posedge clk)
        !reset |=> ((q1 == 8'h00) && (q2 == 8'h00) && (q3 == 8'h00) && (q == 8'h00))
    );

    // On the first clock after reset deassertion, all stages are still zero.
    check_release_all_stages_zero: assert property (
        @(posedge clk) disable iff (!reset)
        $rose(reset) |-> ((q1 == 8'h00) && (q2 == 8'h00) && (q3 == 8'h00) && (q == 8'h00))
    );

    // One clock after reset deassertion, the tail stages remain zero.
    check_release_second_clock_zero_tail: assert property (
        @(posedge clk) disable iff (!reset)
        $rose(reset) |=> ((q2 == 8'h00) && (q3 == 8'h00) && (q == 8'h00))
    );

    // Two clocks after reset deassertion, q3 and q remain zero.
    check_release_third_clock_zero_tail: assert property (
        @(posedge clk) disable iff (!reset)
        $rose(reset) |=> ##1 ((q3 == 8'h00) && (q == 8'h00))
    );

    // Three clocks after reset deassertion, q is still zero.
    check_release_fourth_clock_q_zero: assert property (
        @(posedge clk) disable iff (!reset)
        $rose(reset) |=> ##2 (q == 8'h00)
    );

    // A zero input sample reaches q1 on the next clock.
    check_zero_input_captured_into_q1: assert property (
        @(posedge clk) disable iff (!reset)
        (d == 8'h00) |=> (q1 == 8'h00)
    );

    // A zero in q1 shifts into q2 on the next clock.
    check_zero_q1_shifts_into_q2: assert property (
        @(posedge clk) disable iff (!reset)
        (q1 == 8'h00) |=> (q2 == 8'h00)
    );

    // A zero in q2 shifts into q3 on the next clock.
    check_zero_q2_shifts_into_q3: assert property (
        @(posedge clk) disable iff (!reset)
        (q2 == 8'h00) |=> (q3 == 8'h00)
    );

    // A zero in q3 shifts into q on the next clock.
    check_zero_q3_shifts_into_q: assert property (
        @(posedge clk) disable iff (!reset)
        (q3 == 8'h00) |=> (q == 8'h00)
    );

    // Four consecutive zero input samples force a zero at the output.
    check_four_zero_inputs_produce_zero_q: assert property (
        @(posedge clk) disable iff (!reset)
        ((d == 8'h00) ##1 (d == 8'h00) ##1 (d == 8'h00) ##1 (d == 8'h00)) |=> (q == 8'h00)
    );

endmodule

bind dff_chain dff_chain_sva dff_chain_sva_i (
    .clk(clk),
    .reset(reset),
    .d(d),
    .q(q),
    .q1(q1),
    .q2(q2),
    .q3(q3)
);

rtl:
module touch_sensor_interface (
  input touch_signal,
  output touch_detected
);

parameter sensor_type = 0; // 0 for capacitive, 1 for resistive
parameter threshold = 64; // threshold for touch detection

reg touch_detected_reg;
assign touch_detected = touch_detected_reg;

// Capacitive touch sensor implementation
reg [31:0] rc_time_constant;
always @(posedge touch_signal) begin
  if (touch_signal) begin
    rc_time_constant <= rc_time_constant + 1;
  end else begin
    rc_time_constant <= 0;
  end
end

always @(posedge touch_signal) begin
  if (sensor_type == 0) begin
    if (rc_time_constant > threshold) begin // Fix: Convert '5.000000e+01' to binary
      touch_detected_reg <= 1;
    end else begin
      touch_detected_reg <= 0;
    end
  end
end

// Resistive touch sensor implementation
reg [7:0] adc_value;
always @(posedge touch_signal) begin
  if (sensor_type == 1) begin
    adc_value <= touch_signal * 255;
    if (adc_value > threshold) begin // Fix: Convert '5.000000e+01' to binary
      touch_detected_reg <= 1;
    end else begin
      touch_detected_reg <= 0;
    end
  end
end

endmodule

sva:
module touch_sensor_interface_sva #(
    parameter int sensor_type = 0,
    parameter int threshold   = 64
) (
    input logic        touch_signal,
    input logic        touch_detected,
    input logic [31:0] rc_time_constant,
    input logic [7:0]  adc_value
);

    // RC time constant increments on every touch_signal rising edge.
    check_rc_time_constant_increments: assert property (
        @(posedge touch_signal) 1'b1 |=> rc_time_constant == ($past(rc_time_constant) + 32'd1)
    );

    // ADC value holds when resistive mode is not selected.
    check_adc_value_holds_when_not_resistive: assert property (
        @(posedge touch_signal) sensor_type != 1 |=> adc_value == $past(adc_value)
    );

    // Resistive mode loads the ADC value to full scale.
    check_adc_value_loads_full_scale_in_resistive: assert property (
        @(posedge touch_signal) sensor_type == 1 |=> adc_value == 8'hFF
    );

    // Capacitive mode drives touch_detected from the prior RC comparison.
    check_touch_detected_from_rc_threshold: assert property (
        @(posedge touch_signal) sensor_type == 0 |=> touch_detected == ($past(rc_time_constant) > threshold)
    );

    // Resistive mode drives touch_detected from the prior ADC comparison.
    check_touch_detected_from_adc_threshold: assert property (
        @(posedge touch_signal) sensor_type == 1 |=> touch_detected == ($past(adc_value) > threshold)
    );

    // Unsupported sensor_type values leave touch_detected unchanged.
    check_touch_detected_holds_for_invalid_mode: assert property (
        @(posedge touch_signal) (sensor_type != 0) && (sensor_type != 1) |=> touch_detected == $past(touch_detected)
    );

endmodule

module top_module_sva (
    input logic clk,
    input logic a,
    input logic b,
    input logic [1:0] select,
    input logic [2:0] mux_in,
    input logic out_comb_ff,
    input logic [3:0] mux_out,
    input logic out_final
);

    // XOR output matches the two input bits.
    check_xor_output: assert property (
        @(posedge clk) out_comb_ff == (a ^ b)
    );

    // Mux output matches the select==00 mapping.
    check_mux_select_00: assert property (
        @(posedge clk) (select == 2'b00) |-> (mux_out == {1'b0, mux_in[2:1]})
    );

    // Mux output matches the select==01 mapping.
    check_mux_select_01: assert property (
        @(posedge clk) (select == 2'b01) |-> (mux_out == {1'b0, mux_in[1:0], 1'b0})
    );

    // Mux output matches the select==10 mapping.
    check_mux_select_10: assert property (
        @(posedge clk) (select == 2'b10) |-> (mux_out == {mux_in[2], 1'b0, mux_in[0]})
    );

    // Mux output matches the select==11 mapping.
    check_mux_select_11: assert property (
        @(posedge clk) (select == 2'b11) |-> (mux_out == {mux_in[2:0], 1'b0})
    );

    // A 0001 mux output causes out_final to capture the XOR result.
    check_out_final_capture_xor: assert property (
        @(posedge clk) (mux_out == 4'b0001) |=> (out_final == $past(out_comb_ff))
    );

    // A 0010 mux output causes out_final to capture the inverted XOR result.
    check_out_final_capture_inv_xor: assert property (
        @(posedge clk) (mux_out == 4'b0010) |=> (out_final == ~$past(out_comb_ff))
    );

    // A 0100 mux output causes out_final to become 0.
    check_out_final_force_zero: assert property (
        @(posedge clk) (mux_out == 4'b0100) |=> (out_final == 1'b0)
    );

    // A 1000 mux output causes out_final to become 1.
    check_out_final_force_one: assert property (
        @(posedge clk) (mux_out == 4'b1000) |=> (out_final == 1'b1)
    );

    // Any other mux output leaves out_final unchanged.
    check_out_final_hold_unmatched: assert property (
        @(posedge clk)
        (mux_out != 4'b0001 && mux_out != 4'b0010 && mux_out != 4'b0100 && mux_out != 4'b1000)
        |=> (out_final == $past(out_final))
    );

endmodule

rtl:
module counter_2bit (
    Q      ,
    CLK    ,
    RESET_B
);

    output reg [1:0] Q;
    input  CLK;
    input  RESET_B;

    always @(posedge CLK or negedge RESET_B) begin
        if (!RESET_B) begin
            Q <= 2'b00;
        end else begin
            Q <= Q + 1;
        end
    end

endmodule

sva:
module counter_2bit_sva (
    input  logic [1:0] Q,
    input  logic       CLK,
    input  logic       RESET_B
);

    // Reset low forces the counter output to 00.
    check_reset_forces_zero: assert property (
        @(posedge CLK) !RESET_B |-> (Q == 2'b00)
    );

    // A sampled reset keeps the counter at 00 through the next sample.
    check_reset_holds_zero_to_next_sample: assert property (
        @(posedge CLK) !RESET_B |=> (Q == 2'b00)
    );

    // From 00, the counter advances to 01 unless an async reset returns it to 00.
    check_count_00_advances_or_resets: assert property (
        @(posedge CLK) disable iff (!RESET_B)
        (Q == 2'b00) |=> ((Q == 2'b01) || (Q == 2'b00))
    );

    // From 01, the counter advances to 10 unless an async reset returns it to 00.
    check_count_01_advances_or_resets: assert property (
        @(posedge CLK) disable iff (!RESET_B)
        (Q == 2'b01) |=> ((Q == 2'b10) || (Q == 2'b00))
    );

    // From 10, the counter advances to 11 unless an async reset returns it to 00.
    check_count_10_advances_or_resets: assert property (
        @(posedge CLK) disable iff (!RESET_B)
        (Q == 2'b10) |=> ((Q == 2'b11) || (Q == 2'b00))
    );

    // From 11, the counter wraps back to 00.
    check_count_11_wraps_to_zero: assert property (
        @(posedge CLK) disable iff (!RESET_B)
        (Q == 2'b11) |=> (Q == 2'b00)
    );

endmodule

rtl:
module nor2_gate(
    input A,
    input B_N,
    output Y
    );

    assign Y = ~(A | B_N);

endmodule

sva:
module nor2_gate_sva(
    input logic clk,
    input logic A,
    input logic B_N,
    input logic Y
);

    // Y must equal the NOR of A and B_N.
    check_nor_equation: assert property (
        @(posedge clk) disable iff (1'b0) Y == ~(A | B_N)
    );

    // When both inputs are low, Y must be high.
    check_both_low_drives_high: assert property (
        @(posedge clk) disable iff (1'b0) (!A && !B_N) |-> Y
    );

    // A high must force Y low.
    check_a_high_drives_low: assert property (
        @(posedge clk) disable iff (1'b0) A |-> !Y
    );

    // B_N high must force Y low.
    check_b_high_drives_low: assert property (
        @(posedge clk) disable iff (1'b0) B_N |-> !Y
    );

    // Y high implies both inputs are low.
    check_high_output_requires_both_low: assert property (
        @(posedge clk) disable iff (1'b0) Y |-> (!A && !B_N)
    );

endmodule

rtl:
module oh_oddr #(parameter DW  = 1) (
    input 	    clk, input [DW-1:0]  din1, input [DW-1:0]  din2, output [DW-1:0] out   );

   reg [DW-1:0]    q1_sl;   
   reg [DW-1:0]    q2_sl;
   reg [DW-1:0]    q2_sh;

   always @ (posedge clk)
     begin
	q1_sl[DW-1:0] <= din1[DW-1:0];
	q2_sl[DW-1:0] <= din2[DW-1:0];
     end

   always @ (negedge clk)
     q2_sh[DW-1:0] <= q2_sl[DW-1:0];

   assign out[DW-1:0] = clk ? q1_sl[DW-1:0] : 
	                      q2_sh[DW-1:0];

endmodule

sva:
module oh_oddr_assertions #(parameter DW = 1) (
    input logic           clk,
    input logic [DW-1:0]  din1,
    input logic [DW-1:0]  din2,
    input logic [DW-1:0]  out
);

    // A din1 sample on a rising edge must be observed on out at the following falling edge.
    check_din1_sample_reaches_next_negedge: assert property (
        @(posedge clk)
        1'b1 |=> @(negedge clk) (out == $past(din1, 1, 1'b1, @(posedge clk)))
    );

    // A din2 sample on a rising edge must be observed on out at the next rising edge.
    check_din2_sample_reaches_next_posedge: assert property (
        @(posedge clk)
        1'b1 |=> (out == $past(din2))
    );

endmodule

rtl:
module xor3 (
    output Y,
    input A,
    input B,
    input C
);

    wire nand1_out, nand2_out, nand3_out;

    nand nand1 (nand1_out, A, B);
    nand nand2 (nand2_out, nand1_out, C);
    nand nand3 (Y, nand2_out, nand2_out);

endmodule

sva:
module xor3_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic C,
    input logic Y,
    input logic nand1_out,
    input logic nand2_out
);

    // First NAND implements ~(A & B).
    check_nand1_function: assert property (
        @(posedge clk) nand1_out == ~(A & B)
    );

    // Second NAND implements ~(nand1_out & C).
    check_nand2_function: assert property (
        @(posedge clk) nand2_out == ~(nand1_out & C)
    );

    // Final self-NAND inverts nand2_out onto Y.
    check_output_inverter_function: assert property (
        @(posedge clk) Y == ~(nand2_out & nand2_out)
    );

    // Y is the AND of C and nand1_out.
    check_output_equals_c_and_nand1: assert property (
        @(posedge clk) Y == (nand1_out & C)
    );

    // End-to-end output is C & ~(A & B).
    check_output_boolean_function: assert property (
        @(posedge clk) Y == (C & ~(A & B))
    );

    // C low forces Y low.
    check_c_low_forces_y_low: assert property (
        @(posedge clk) (C == 1'b0) |-> (Y == 1'b0)
    );

    // With C high, Y reduces to ~(A & B).
    check_c_high_reduces_to_not_ab: assert property (
        @(posedge clk) (C == 1'b1) |-> (Y == ~(A & B))
    );

    // A and B both high force Y low.
    check_ab_high_forces_y_low: assert property (
        @(posedge clk) ((A == 1'b1) && (B == 1'b1)) |-> (Y == 1'b0)
    );

    // C high with either A or B low forces Y high.
    check_c_high_and_not_ab_drives_y_high: assert property (
        @(posedge clk) ((C == 1'b1) && ((A == 1'b0) || (B == 1'b0))) |-> (Y == 1'b1)
    );

endmodule

rtl:
module data_module (
    input [7:0] data_in,
    input [3:0] selector,
    output reg [7:0] data_out
);

// Define masks for use in operations
parameter [7:0] MASK_AND = 8'hF0;
parameter [7:0] MASK_OR = 8'h0F;
parameter [7:0] MASK_XOR = 8'h55;

// Define intermediate signals for use in operations
wire [7:0] not_data;
wire [7:0] shifted_left;
wire [7:0] shifted_right;
wire [7:0] anded_data;
wire [7:0] ored_data;
wire [7:0] xored_data;

// Perform operations based on selector input
assign not_data = ~data_in;
assign shifted_left = {data_in[6:0], 1'b0};
assign shifted_right = {1'b0, data_in[7:1]};
assign anded_data = data_in & MASK_AND;
assign ored_data = data_in | MASK_OR;
assign xored_data = data_in ^ MASK_XOR;

always @(*) begin
    case (selector)
        4'b0000: data_out = data_in;
        4'b0001: data_out = not_data;
        4'b0010: data_out = shifted_left;
        4'b0011: data_out = shifted_right;
        4'b0100: data_out = anded_data;
        4'b0101: data_out = ored_data;
        4'b0110: data_out = xored_data;
        4'b0111: data_out = ~data_in + 1;
        default: data_out = data_in;
    endcase
end

endmodule

sva:
module data_module_sva #(
    parameter [7:0] MASK_AND = 8'hF0,
    parameter [7:0] MASK_OR  = 8'h0F,
    parameter [7:0] MASK_XOR = 8'h55
) (
    input logic [7:0] data_in,
    input logic [3:0] selector,
    input logic [7:0] data_out
);

    // No DUT clock or reset; sample combinational behavior on the formal global clock.

    // Selector 0 passes data_in through unchanged.
    check_selector_identity: assert property (
        @($global_clock) (selector == 4'h0) |-> (data_out == data_in)
    );

    // Selector 1 outputs the bitwise inverse of data_in.
    check_selector_invert: assert property (
        @($global_clock) (selector == 4'h1) |-> (data_out == ~data_in)
    );

    // Selector 2 shifts data_in left by one and inserts 0 in the LSB.
    check_selector_shift_left: assert property (
        @($global_clock) (selector == 4'h2) |-> (data_out == {data_in[6:0], 1'b0})
    );

    // Selector 3 shifts data_in right by one and inserts 0 in the MSB.
    check_selector_shift_right: assert property (
        @($global_clock) (selector == 4'h3) |-> (data_out == {1'b0, data_in[7:1]})
    );

    // Selector 4 ANDs data_in with MASK_AND.
    check_selector_and_mask: assert property (
        @($global_clock) (selector == 4'h4) |-> (data_out == (data_in & MASK_AND))
    );

    // Selector 5 ORs data_in with MASK_OR.
    check_selector_or_mask: assert property (
        @($global_clock) (selector == 4'h5) |-> (data_out == (data_in | MASK_OR))
    );

    // Selector 6 XORs data_in with MASK_XOR.
    check_selector_xor_mask: assert property (
        @($global_clock) (selector == 4'h6) |-> (data_out == (data_in ^ MASK_XOR))
    );

    // Selector 7 outputs the two's complement of data_in.
    check_selector_twos_complement: assert property (
        @($global_clock) (selector == 4'h7) |-> (data_out == ((~data_in) + 8'h01))
    );

    // Selectors 8 through F use the default pass-through behavior.
    check_selector_default_passthrough: assert property (
        @($global_clock) selector[3] |-> (data_out == data_in)
    );

endmodule

