module sky130_fd_sc_lp__xor3_sva (
    input logic clk,
    input logic X,
    input logic A,
    input logic B,
    input logic C
);

    // X must equal the three-input XOR of A, B, and C.
    check_x_matches_xor3: assert property (
        @(posedge clk) X == (A ^ B ^ C)
    );

    // If B and C match, X reduces to A.
    check_x_reduces_to_a_when_b_eq_c: assert property (
        @(posedge clk) (B == C) |-> (X == A)
    );

