rtl:
module top_module (
    input [3:0] A,
    input [3:0] B,
    input [3:0] C,
    input SEL1,
    input SEL2,
    output [3:0] OUT
);

    wire [3:0] add_sub_out;
    wire [3:0] mux_out;

    adder_subtractor_module add_sub (
        .A(A),
        .B(B),
        .SUB(SEL1),
        .OUT(add_sub_out)
    );

    mux4to1_module mux (
        .IN0(4'b0),
        .IN1(4'b0),
        .IN2(4'b0),
        .IN3(C),
        .SEL(SEL1),
        .OUT(mux_out)
    );

    assign OUT = SEL2 ? mux_out : 4'b0;

endmodule
module adder_subtractor_module (
    input [3:0] A,
    input [3:0] B,
    input SUB,
    output [3:0] OUT
);

    assign OUT = SUB ? A - B : A + B;

endmodule
module mux4to1_module (
    input [3:0] IN0,
    input [3:0] IN1,
    input [3:0] IN2,
    input [3:0] IN3,
    input SEL,
    output [3:0] OUT
);

    assign OUT = SEL ? IN3 : (SEL ? IN2 : (SEL ? IN1 : IN0));

endmodule

sva:
module top_module_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] C,
    input logic       SEL1,
    input logic       SEL2,
    input logic [3:0] OUT
);

    // OUT matches the implemented top-level function.
    check_output_function: assert property (
        @($global_clock) OUT == (SEL2 ? (SEL1 ? C : 4'b0000) : 4'b0000)
    );

    // Any low select forces OUT to zero.
    check_any_low_select_forces_zero: assert property (
        @($global_clock) (!SEL1 || !SEL2) |-> (OUT == 4'b0000)
    );

    // Both selects high pass C through to OUT.
    check_both_selects_pass_c: assert property (
        @($global_clock) (SEL1 && SEL2) |-> (OUT == C)
    );

    // A does not affect OUT when other controlling inputs are unchanged.
    check_a_independent_of_out: assert property (
        @($global_clock)
        ($changed(A) && $stable(B) && $stable(C) && $stable(SEL1) && $stable(SEL2))
        |-> $stable(OUT)
    );

    // B does not affect OUT when other controlling inputs are unchanged.
    check_b_independent_of_out: assert property (
        @($global_clock)
        ($changed(B) && $stable(A) && $stable(C) && $stable(SEL1) && $stable(SEL2))
        |-> $stable(OUT)
    );

    // C is blocked from OUT when either select is low.
    check_c_blocked_when_select_disabled: assert property (
        @($global_clock)
        ($changed(C) && $stable(A) && $stable(B) && $stable(SEL1) && $stable(SEL2) && (!SEL1 || !SEL2))
        |-> $stable(OUT)
    );

    // C propagates to OUT when both selects are high.
    check_c_propagates_when_enabled: assert property (
        @($global_clock)
        ($changed(C) && $stable(A) && $stable(B) && $stable(SEL1) && $stable(SEL2) && SEL1 && SEL2)
        |-> ($changed(OUT) && (OUT == C))
    );

endmodule

rtl:
module up_down_counter (
    input clk,
    input UP,
    input DOWN,
    input LOAD,
    input [3:0] DIN,
    output [3:0] Q
);

reg [3:0] Q_reg1, Q_reg2, Q_reg3;

always @(posedge clk) begin
    if (LOAD) begin
        Q_reg1 <= DIN;
        Q_reg2 <= DIN;
        Q_reg3 <= DIN;
    end else if (UP) begin
        if (Q_reg1 == 4'b1111) begin
            Q_reg1 <= 4'b0000;
            Q_reg2 <= 4'b0000;
            Q_reg3 <= 4'b0000;
        end else begin
            Q_reg1 <= Q_reg1 + 1;
            Q_reg2 <= Q_reg2 + 1;
            Q_reg3 <= Q_reg3 + 1;
        end
    end else if (DOWN) begin
        if (Q_reg1 == 4'b0000) begin
            Q_reg1 <= 4'b1111;
            Q_reg2 <= 4'b1111;
            Q_reg3 <= 4'b1111;
        end else begin
            Q_reg1 <= Q_reg1 - 1;
            Q_reg2 <= Q_reg2 - 1;
            Q_reg3 <= Q_reg3 - 1;
        end
    end
end

assign Q = Q_reg3;

endmodule

sva:
module up_down_counter_sva (
    input logic clk,
    input logic UP,
    input logic DOWN,
    input logic LOAD,
    input logic [3:0] DIN,
    input logic [3:0] Q,
    input logic [3:0] Q_reg1,
    input logic [3:0] Q_reg2,
    input logic [3:0] Q_reg3
);

    // Q is driven directly from Q_reg3.
    check_output_matches_reg3: assert property (
        @(posedge clk) Q == Q_reg3
    );

    // LOAD has highest priority and copies DIN into all registers.
    check_load_copies_din_to_regs: assert property (
        @(posedge clk)
        LOAD |=> (Q_reg1 == $past(DIN)) &&
                 (Q_reg2 == $past(DIN)) &&
                 (Q_reg3 == $past(DIN))
    );

    // LOAD also updates the visible output on the next cycle.
    check_load_updates_output: assert property (
        @(posedge clk)
        LOAD |=> (Q == $past(DIN))
    );

    // UP has priority over DOWN and increments all registers when not at 15.
    check_up_increments_regs: assert property (
        @(posedge clk)
        (!LOAD && UP && (Q_reg1 != 4'hF)) |=> (Q_reg1 == ($past(Q_reg1) + 4'h1)) &&
                                              (Q_reg2 == ($past(Q_reg2) + 4'h1)) &&
                                              (Q_reg3 == ($past(Q_reg3) + 4'h1))
    );

    // UP wraps all registers to 0 when Q_reg1 is 15.
    check_up_wraps_regs: assert property (
        @(posedge clk)
        (!LOAD && UP && (Q_reg1 == 4'hF)) |=> (Q_reg1 == 4'h0) &&
                                              (Q_reg2 == 4'h0) &&
                                              (Q_reg3 == 4'h0)
    );

    // DOWN decrements all registers when selected and Q_reg1 is not 0.
    check_down_decrements_regs: assert property (
        @(posedge clk)
        (!LOAD && !UP && DOWN && (Q_reg1 != 4'h0)) |=> (Q_reg1 == ($past(Q_reg1) - 4'h1)) &&
                                                       (Q_reg2 == ($past(Q_reg2) - 4'h1)) &&
                                                       (Q_reg3 == ($past(Q_reg3) - 4'h1))
    );

    // DOWN wraps all registers to 15 when Q_reg1 is 0.
    check_down_wraps_regs: assert property (
        @(posedge clk)
        (!LOAD && !UP && DOWN && (Q_reg1 == 4'h0)) |=> (Q_reg1 == 4'hF) &&
                                                       (Q_reg2 == 4'hF) &&
                                                       (Q_reg3 == 4'hF)
    );

    // With no active control, all registers hold their value.
    check_hold_without_controls: assert property (
        @(posedge clk)
        (!LOAD && !UP && !DOWN) |=> (Q_reg1 == $past(Q_reg1)) &&
                                    (Q_reg2 == $past(Q_reg2)) &&
                                    (Q_reg3 == $past(Q_reg3))
    );

endmodule

rtl:
module traffic_light_fsm(
  input clk,
  input reset,
  output reg NSG_LED,
  output reg EWG_LED,
  output reg yellow_LED
);

  // Define the states
  parameter NSG = 2'b00;
  parameter NSG_YELLOW = 2'b01;
  parameter EWG = 2'b10;
  parameter EWG_YELLOW = 2'b11;

  // Define the state register and initialize to NSG
  reg [1:0] state_reg = NSG;

  // Define the state output logic
  always @ (state_reg) begin
    case (state_reg)
      NSG: begin
        NSG_LED = 1;
        EWG_LED = 0;
        yellow_LED = 0;
      end
      NSG_YELLOW: begin
        NSG_LED = 0;
        EWG_LED = 0;
        yellow_LED = 1;
      end
      EWG: begin
        NSG_LED = 0;
        EWG_LED = 1;
        yellow_LED = 0;
      end
      EWG_YELLOW: begin
        NSG_LED = 0;
        EWG_LED = 0;
        yellow_LED = 1;
      end
    endcase
  end

  // Define the state transition logic
  always @ (posedge clk, posedge reset) begin
    if (reset) begin
      state_reg <= NSG;
    end else begin
      case (state_reg)
        NSG: begin
          if (count == 30) begin
            state_reg <= NSG_YELLOW;
            count <= 0;
          end else begin
            count <= count + 1;
          end
        end
        NSG_YELLOW: begin
          if (count == 5) begin
            state_reg <= EWG;
            count <= 0;
          end else begin
            count <= count + 1;
          end
        end
        EWG: begin
          if (count == 20) begin
            state_reg <= EWG_YELLOW;
            count <= 0;
          end else begin
            count <= count + 1;
          end
        end
        EWG_YELLOW: begin
          if (count == 5) begin
            state_reg <= NSG;
            count <= 0;
          end else begin
            count <= count + 1;
          end
        end
      endcase
    end
  end

  // Define the count register and initialize to 0
  reg [5:0] count = 0;

endmodule

sva:
module traffic_light_fsm_sva (
    input logic       clk,
    input logic       reset,
    input logic       NSG_LED,
    input logic       EWG_LED,
    input logic       yellow_LED,
    input logic [1:0] state_reg,
    input logic [5:0] count
);

    localparam logic [1:0] NSG        = 2'b00;
    localparam logic [1:0] NSG_YELLOW = 2'b01;
    localparam logic [1:0] EWG        = 2'b10;
    localparam logic [1:0] EWG_YELLOW = 2'b11;

    // Reset forces the FSM into NSG.
    check_reset_state_nsg: assert property (
        @(posedge clk) reset |=> (state_reg == NSG)
    );

    // After reset, the NSG output pattern is driven.
    check_reset_outputs_nsg: assert property (
        @(posedge clk) reset |=> (NSG_LED == 1'b1 && EWG_LED == 1'b0 && yellow_LED == 1'b0)
    );

    // NSG lights only the north-south green LED.
    check_nsg_outputs: assert property (
        @(posedge clk) disable iff (reset)
        (state_reg == NSG) |-> (NSG_LED == 1'b1 && EWG_LED == 1'b0 && yellow_LED == 1'b0)
    );

    // NSG_YELLOW lights only the yellow LED.
    check_nsg_yellow_outputs: assert property (
        @(posedge clk) disable iff (reset)
        (state_reg == NSG_YELLOW) |-> (NSG_LED == 1'b0 && EWG_LED == 1'b0 && yellow_LED == 1'b1)
    );

    // EWG lights only the east-west green LED.
    check_ewg_outputs: assert property (
        @(posedge clk) disable iff (reset)
        (state_reg == EWG) |-> (NSG_LED == 1'b0 && EWG_LED == 1'b1 && yellow_LED == 1'b0)
    );

    // EWG_YELLOW lights only the yellow LED.
    check_ewg_yellow_outputs: assert property (
        @(posedge clk) disable iff (reset)
        (state_reg == EWG_YELLOW) |-> (NSG_LED == 1'b0 && EWG_LED == 1'b0 && yellow_LED == 1'b1)
    );

    // NSG transitions to NSG_YELLOW when count reaches 30.
    check_nsg_timeout_transition: assert property (
        @(posedge clk) disable iff (reset)
        (state_reg == NSG && count == 6'd30) |=> (state_reg == NSG_YELLOW && count == 6'd0)
    );

    // NSG holds state and increments count before 30.
    check_nsg_count_increment: assert property (
        @(posedge clk) disable iff (reset)
        (state_reg == NSG && count != 6'd30) |=> (state_reg == NSG && count == ($past(count) + 6'd1))
    );

    // NSG_YELLOW transitions to EWG when count reaches 5.
    check_nsg_yellow_timeout_transition: assert property (
        @(posedge clk) disable iff (reset)
        (state_reg == NSG_YELLOW && count == 6'd5) |=> (state_reg == EWG && count == 6'd0)
    );

    // NSG_YELLOW holds state and increments count before 5.
    check_nsg_yellow_count_increment: assert property (
        @(posedge clk) disable iff (reset)
        (state_reg == NSG_YELLOW && count != 6'd5) |=> (state_reg == NSG_YELLOW && count == ($past(count) + 6'd1))
    );

    // EWG transitions to EWG_YELLOW when count reaches 20.
    check_ewg_timeout_transition: assert property (
        @(posedge clk) disable iff (reset)
        (state_reg == EWG && count == 6'd20) |=> (state_reg == EWG_YELLOW && count == 6'd0)
    );

    // EWG holds state and increments count before 20.
    check_ewg_count_increment: assert property (
        @(posedge clk) disable iff (reset)
        (state_reg == EWG && count != 6'd20) |=> (state_reg == EWG && count == ($past(count) + 6'd1))
    );

    // EWG_YELLOW transitions to NSG when count reaches 5.
    check_ewg_yellow_timeout_transition: assert property (
        @(posedge clk) disable iff (reset)
        (state_reg == EWG_YELLOW && count == 6'd5) |=> (state_reg == NSG && count == 6'd0)
    );

    // EWG_YELLOW holds state and increments count before 5.
    check_ewg_yellow_count_increment: assert property (
        @(posedge clk) disable iff (reset)
        (state_reg == EWG_YELLOW && count != 6'd5) |=> (state_reg == EWG_YELLOW && count == ($past(count) + 6'd1))
    );

endmodule

