sva:
module and2b_sva (
    input logic X,
    input logic A,
    input logic B,
    input logic VPWR,
    input logic VGND
);

    // X implements the combinational function (~A) & B.
    check_x_function: assert property (
        @($global_clock) X === ((~A) & B)
    );

    // When B is low, X must be low.
    check_b_low_forces_x_low: assert property (
        @($global_clock) (B === 1'b0) |-> (X === 1'b0)
