rtl:
module binary_counter (
    input clk,
    input reset,
    input load,
    input [3:0] data_in,
    output [3:0] count
);

reg [3:0] count_reg;
reg [3:0] count_next;

always @(posedge clk) begin
    if (reset) begin
        count_reg <= 4'b0;
    end
    else if (load) begin
        count_reg <= data_in;
    end
    else begin
        count_reg <= count_next;
    end
end

always @(*) begin
    if (load) begin
        count_next = data_in;
    end
    else begin
        count_next = count_reg + 4'b1;
    end
end

assign count = count_reg;

endmodule

sva:
module binary_counter_sva (
    input logic       clk,
    input logic       reset,
    input logic       load,
    input logic [3:0] data_in,
    input logic [3:0] count
);

    // Reset clears the counter on the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'b0000)
    );

    // Reset has priority over load.
    check_reset_overrides_load: assert property (
        @(posedge clk) (reset && load) |=> (count == 4'b0000)
    );

    // A load updates the counter with data_in.
    check_load_updates_count: assert property (
        @(posedge clk) disable iff (reset)
        load |=> (count == $past(data_in))
    );

    // Without load, the counter increments by one.
    check_increment_updates_count: assert property (
        @(posedge clk) disable iff (reset)
        !load |=> (count == ($past(count) + 4'b0001))
    );

    // The counter wraps from 15 back to 0.
    check_wraparound_from_max: assert property (
        @(posedge clk) disable iff (reset)
        (!load && (count == 4'hF)) |=> (count == 4'h0)
    );

    // Every non-reset cycle follows the load-or-increment next-state rule.
    check_exact_nonreset_transition: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> (count == ($past(load) ? $past(data_in) : ($past(count) + 4'b0001)))
    );

endmodule

rtl:
module top_module (
    input [3:0] A,
    input [3:0] B,
    input [2:0] OP,
    output [3:0] Y
);

    wire [3:0] S;
    wire [3:0] bitwise_Y;
    wire [3:0] functional_Z;

    adder adder_inst (
        .A(A),
        .B(B),
        .S(S)
    );

    bitwise bitwise_inst (
        .A(A),
        .B(B),
        .OP(OP),
        .Y(bitwise_Y)
    );

    functional functional_inst (
        .S(S),
        .Y(bitwise_Y),
        .OP(OP),
        .Z(functional_Z)
    );

    assign Y = (OP == 3'b000) ? S :
               (OP == 3'b001) ? S :
               (OP == 3'b010) ? bitwise_Y :
               (OP == 3'b011) ? bitwise_Y :
               (OP == 3'b100) ? bitwise_Y :
               4'b0;

endmodule

module adder (
    input [3:0] A,
    input [3:0] B,
    output [3:0] S
);

    assign S = A + B;

endmodule

module bitwise (
    input [3:0] A,
    input [3:0] B,
    input [2:0] OP,
    output [3:0] Y
);

    assign Y = (OP == 3'b010) ? A & B :
               (OP == 3'b011) ? A | B :
               (OP == 3'b100) ? A ^ B :
               4'b0;

endmodule

module functional (
    input [3:0] S,
    input [3:0] Y,
    input [2:0] OP,
    output [3:0] Z
);

    assign Z = (OP == 3'b000) ? S :
               (OP == 3'b001) ? S :
               (OP == 3'b010) ? Y :
               (OP == 3'b011) ? Y :
               (OP == 3'b100) ? Y :
               4'b0;

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [2:0] OP,
    input logic [3:0] Y
);

    // No RTL clock or reset exists; clk is only a sampling clock for these checks.

    // Y must follow the top-level opcode decode.
    check_output_decode: assert property (
        @(posedge clk)
        Y == ((OP == 3'b000) ? (A + B) :
              (OP == 3'b001) ? (A + B) :
              (OP == 3'b010) ? (A & B) :
              (OP == 3'b011) ? (A | B) :
              (OP == 3'b100) ? (A ^ B) :
                               4'b0000)
    );

    // Opcodes 000 and 001 select the adder result.
    check_add_opcodes: assert property (
        @(posedge clk) ((OP == 3'b000) || (OP == 3'b001)) |-> (Y == (A + B))
    );

    // Opcode 010 selects bitwise AND.
    check_and_opcode: assert property (
        @(posedge clk) (OP == 3'b010) |-> (Y == (A & B))
    );

    // Opcode 011 selects bitwise OR.
    check_or_opcode: assert property (
        @(posedge clk) (OP == 3'b011) |-> (Y == (A | B))
    );

    // Opcode 100 selects bitwise XOR.
    check_xor_opcode: assert property (
        @(posedge clk) (OP == 3'b100) |-> (Y == (A ^ B))
    );

    // Unused opcodes drive zero.
    check_default_zero_opcodes: assert property (
        @(posedge clk) ((OP == 3'b101) || (OP == 3'b110) || (OP == 3'b111)) |-> (Y == 4'b0000)
    );

    // Stable inputs must produce a stable output.
    check_output_stable_when_inputs_stable: assert property (
        @(posedge clk) ($stable(A) && $stable(B) && $stable(OP)) |-> $stable(Y)
    );

endmodule

