        @($global_clock) ((A2 === 1'b0) && (B1 === 1'b0)) |-> (Y === 1'b0)
    );

    // A2 low and B2 low force Y low.
    check_a2_b2_low_force_y_low: assert property (
        @($global_clock) ((A2 === 1'b0) && (B2 === 1'b0)) |-> (Y === 1'b0)
    );

