    // sum1 captures the previous sampled addition result.
    check_sum1_captures_add: assert property (
        @(posedge control)
        (!$isunknown($past({a, b}))) |-> (sum1 == $past(a + b))
    );

    // diff1 captures the previous sampled subtraction result.
    check_diff1_captures_sub: assert property (
        @(posedge control)
        (!$isunknown($past({a, b}))) |-> (diff1 == $past(a - b))
    );

    // sum2 captures the previous sampled sum1 value.
    check_sum2_pipelines_sum1: assert property (
        @(posedge control)
        (!$isunknown($past(sum1))) |-> (sum2 == $past(sum1))
    );

    // diff2 captures the previous sampled diff1 value.
    check_diff2_pipelines_diff1: assert property (
        @(posedge control)
        (!$isunknown($past(diff1))) |-> (diff2 == $past(diff1))
    );

    // sum2 matches the addition result from two control edges earlier.
    check_sum2_matches_two_cycle_add: assert property (
        @(posedge control)
        (!$isunknown($past({a, b}, 2))) |-> (sum2 == $past(a + b, 2))
    );

    // diff2 matches the subtraction result from two control edges earlier.
    check_diff2_matches_two_cycle_sub: assert property (
        @(posedge control)
        (!$isunknown($past({a, b}, 2))) |-> (diff2 == $past(a - b, 2))
    );

    // out captures the previous sampled sum2 value.
    check_out_pipelines_sum2: assert property (
        @(posedge control)
        (!$isunknown($past(sum2))) |-> (out == $past(sum2))
    );

    // out matches the addition result from three control edges earlier.
    check_out_matches_three_cycle_add: assert property (
        @(posedge control)
        (!$isunknown($past({a, b}, 3))) |-> (out == $past(a + b, 3))
    );

    // out does not follow the delayed subtraction path when add and subtract differ.
    check_out_not_delayed_sub_when_distinct: assert property (
        @(posedge control)
        (!$isunknown($past({a, b}, 3)) && ($past(a + b, 3) != $past(a - b, 3)))
        |-> (out != $past(a - b, 3))
    );

    // equal delayed sums keep the sampled output stable.
    check_out_stable_when_delayed_sum_stable: assert property (
        @(posedge control)
        (!$isunknown($past({a, b}, 4)) && ($past(a + b, 3) == $past(a + b, 4)))
        |-> $stable(out)
    );

endmodule

bind adder_subtractor adder_subtractor_assertions adder_subtractor_assertions_i (
    .a(a),
    .b(b),
    .control(control),
    .out(out),
    .sum1(sum1),
    .sum2(sum2),
    .diff1(diff1),
    .diff2(diff2)
);

rtl:
module twos_complement (
    input [3:0] A,
    output reg [3:0] OUT
);

    always @ (A) begin
        OUT <= ~A + 1;
    end

endmodule

sva:
module twos_complement_sva (
    input logic clk,        // sampling clock for combinational DUT
    input logic [3:0] A,
    input logic [3:0] OUT
);

    // OUT must equal the 4-bit two's complement of A.
    check_twos_complement_function: assert property (
        @(posedge clk) OUT == (~A + 4'b0001)
    );

    // A and OUT must add to zero modulo 16.
    check_additive_inverse: assert property (
        @(posedge clk) (A + OUT) == 4'b0000
    );

    // Zero input must produce zero output.
    check_zero_maps_to_zero: assert property (
        @(posedge clk) (A == 4'b0000) |-> (OUT == 4'b0000)
    );

    // 4'b1000 must map to itself in 4-bit two's complement.
    check_min_value_self_inverse: assert property (
        @(posedge clk) (A == 4'b1000) |-> (OUT == 4'b1000)
    );

    // Two's complement preserves the least-significant bit.
    check_lsb_preserved: assert property (
        @(posedge clk) OUT[0] == A[0]
    );

endmodule

rtl:
module ir_recieve(
clk, rst, sda, recieve_status,recieved_data
);
input clk;
input rst;
input sda;
output recieve_status;
output [10:0] recieved_data;

reg[1:0] sda_reg;
wire falling_edge;
wire rising_edge;
reg[10:0] recieved_data;
reg[7:0] cyc_cnt;
reg[7:0] start_cnt;
reg recieve_status;
reg [31:0] time_cnt;
reg [2:0] start_bits;
reg data_start;

always @(posedge clk or negedge rst)begin
	if(!rst)begin
		start_bits <= 'h0;
		start_cnt <= 'h0;
		end
	else begin
		if(falling_edge && start_cnt < 'd3)begin
			start_bits[start_cnt]<= 1'b1;
			start_cnt <= start_cnt + 1'b1;
		end
		else begin
			start_bits <= start_bits;
			start_cnt <= start_cnt;
		end
	end
end

always @(posedge clk or negedge rst)begin
	if(!rst)begin
		time_cnt <= 'h0;
		cyc_cnt <= 'h0;
		data_start <= 'h0;
	end
	else begin
		if(start_bits == 3'b111 && data_start == 0 && time_cnt < 'd44500)
			time_cnt <= time_cnt + 1'b1;
		else if(start_bits == 3'b111 && data_start == 0 && time_cnt == 'd44500)begin
			time_cnt <= 'h0;
			data_start <= 'h1;
		end
		else begin
		if(start_bits == 3'b111 && time_cnt < 'd89000 && cyc_cnt < 'd11 && data_start == 1)begin
			time_cnt <= time_cnt + 1'b1;
			end
		else if(start_bits == 3'b111 && time_cnt == 'd89000 && cyc_cnt < 'd11 && data_start == 1)begin
			time_cnt <= 'h0;
			cyc_cnt <= cyc_cnt + 1'b1;
			end
		 else begin
			time_cnt <= time_cnt;
			cyc_cnt <= cyc_cnt;
			data_start <= data_start;
		 end
		 end
	end
end

always @(posedge clk or negedge rst)begin
	if(!rst)
		sda_reg <= 2'b11;
	else begin
		sda_reg[0] <= sda;
		sda_reg[1] <= sda_reg[0];
	end
end

assign falling_edge = (sda_reg[1:0] == 2'b10) ? 1'b1 : 1'b0;
assign rising_edge = (sda_reg[1:0] == 2'b01) ? 1'b1 : 1'b0;

always @(posedge clk or negedge rst)begin
	if(!rst)begin
		recieved_data <= 'h0;
	end
	else begin
		if(falling_edge && time_cnt > 'd30000 && time_cnt < 'd60000 && cyc_cnt < 'd11)begin
			recieved_data[cyc_cnt] <= 1'b1;
		end
		else if(rising_edge && time_cnt > 'd30000 && time_cnt < 'd60000 && cyc_cnt < 'd11)begin
			recieved_data[cyc_cnt] <= 1'b0;
		end
		else begin
			recieved_data <= recieved_data;
		end
	end
end

always @(posedge clk or negedge rst)begin
	if(!rst)
		recieve_status <= 1'b0;
	else
		recieve_status <= ( recieved_data == 11'b00011110101) ? 1'b1 : 1'b0;
		end 
endmodule

sva:
module ir_recieve_assertions (
    input logic        clk,
    input logic        rst,
    input logic        sda,
    input logic        recieve_status,
    input logic [10:0] recieved_data,
    input logic [1:0]  sda_reg,
    input logic        falling_edge,
    input logic        rising_edge,
    input logic [7:0]  cyc_cnt,
    input logic [7:0]  start_cnt,
    input logic [31:0] time_cnt,
    input logic [2:0]  start_bits,
    input logic        data_start
);

    // Active-low reset forces all state to its initialized value.
    check_reset_state: assert property (
        @(posedge clk)
        !rst |-> (start_bits      == 3'b000)  &&
                 (start_cnt       == 8'd0)    &&
                 (time_cnt        == 32'd0)   &&
                 (cyc_cnt         == 8'd0)    &&
                 (data_start      == 1'b0)    &&
                 (sda_reg         == 2'b11)   &&
                 (recieved_data   == 11'd0)   &&
                 (recieve_status  == 1'b0)
    );

    // The SDA synchronizer shifts in the sampled SDA value each clock.
    check_sda_shift_register: assert property (
        @(posedge clk) disable iff (!rst)
        (sda_reg[0] == $past(sda)) &&
        (sda_reg[1] == $past(sda_reg[0]))
    );

    // falling_edge is asserted only for the 2'b10 SDA history pattern.
    check_falling_edge_decode: assert property (
        @(posedge clk) disable iff (!rst)
        (falling_edge == (sda_reg == 2'b10))
    );

    // rising_edge is asserted only for the 2'b01 SDA history pattern.
    check_rising_edge_decode: assert property (
        @(posedge clk) disable iff (!rst)
        (rising_edge == (sda_reg == 2'b01))
    );

    // A qualifying falling edge sets the indexed start bit and increments start_cnt.
    check_start_capture_update: assert property (
        @(posedge clk) disable iff (!rst)
        ($past(falling_edge) && ($past(start_cnt) < 8'd3)) |->
            (start_cnt == ($past(start_cnt) + 8'd1)) &&
            (start_bits == ($past(start_bits) | (3'b001 << $past(start_cnt))))
    );

    // Without a qualifying falling edge, start_bits and start_cnt hold their values.
    check_start_capture_hold: assert property (
        @(posedge clk) disable iff (!rst)
        !($past(falling_edge) && ($past(start_cnt) < 8'd3)) |->
            (start_cnt == $past(start_cnt)) &&
            (start_bits == $past(start_bits))
    );

    // The timing state stays idle until all three start bits have been seen.
    check_timer_idle_before_start: assert property (
        @(posedge clk) disable iff (!rst)
        ($past(start_bits) != 3'b111) |->
            (time_cnt == $past(time_cnt)) &&
            (cyc_cnt == $past(cyc_cnt)) &&
            (data_start == $past(data_start))
    );

    // Before data_start, time_cnt increments up to 44500.
    check_preamble_timer_increment: assert property (
        @(posedge clk) disable iff (!rst)
        ($past(start_bits) == 3'b111 && !$past(data_start) && ($past(time_cnt) < 32'd44500)) |->
            (time_cnt == ($past(time_cnt) + 32'd1)) &&
            (cyc_cnt == $past(cyc_cnt)) &&
            (data_start == 1'b0)
    );

    // At 44500 counts, the preamble timer resets and data_start asserts.
    check_preamble_done_sets_data_start: assert property (
        @(posedge clk) disable iff (!rst)
        ($past(start_bits) == 3'b111 && !$past(data_start) && ($past(time_cnt) == 32'd44500)) |->
            (time_cnt == 32'd0) &&
            (cyc_cnt == $past(cyc_cnt)) &&
            (data_start == 1'b1)
    );

    // During data collection, time_cnt increments until the bit period completes.
    check_bit_timer_increment: assert property (
        @(posedge clk) disable iff (!rst)
        ($past(start_bits) == 3'b111 && $past(data_start) &&
         ($past(cyc_cnt) < 8'd11) && ($past(time_cnt) < 32'd89000)) |->
            (time_cnt == ($past(time_cnt) + 32'd1)) &&
            (cyc_cnt == $past(cyc_cnt)) &&
            (data_start == 1'b1)
    );

    // At 89000 counts, the bit timer resets and cyc_cnt increments.
    check_bit_timer_wrap_advances_cycle: assert property (
        @(posedge clk) disable iff (!rst)
        ($past(start_bits) == 3'b111 && $past(data_start) &&
         ($past(cyc_cnt) < 8'd11) && ($past(time_cnt) == 32'd89000)) |->
            (time_cnt == 32'd0) &&
            (cyc_cnt == ($past(cyc_cnt) + 8'd1)) &&
            (data_start == 1'b1)
    );

    // A falling edge in the valid sample window writes a 1 into the current bit.
    check_falling_edge_samples_one: assert property (
        @(posedge clk) disable iff (!rst)
        ($past(falling_edge) &&
         ($past(time_cnt) > 32'd30000) && ($past(time_cnt) < 32'd60000) &&
         ($past(cyc_cnt) < 8'd11)) |->
            (recieved_data == ($past(recieved_data) | (11'h001 << $past(cyc_cnt))))
    );

    // A rising edge in the valid sample window writes a 0 into the current bit.
    check_rising_edge_samples_zero: assert property (
        @(posedge clk) disable iff (!rst)
        ($past(rising_edge) &&
         ($past(time_cnt) > 32'd30000) && ($past(time_cnt) < 32'd60000) &&
         ($past(cyc_cnt) < 8'd11)) |->
            (recieved_data == ($past(recieved_data) & ~(11'h001 << $past(cyc_cnt))))
    );

    // Without a valid sample edge, recieved_data holds its value.
    check_data_hold_without_sample_edge: assert property (
        @(posedge clk) disable iff (!rst)
        !(($past(falling_edge) &&
           ($past(time_cnt) > 32'd30000) && ($past(time_cnt) < 32'd60000) &&
           ($past(cyc_cnt) < 8'd11)) ||
          ($past(rising_edge) &&
           ($past(time_cnt) > 32'd30000) && ($past(time_cnt) < 32'd60000) &&
           ($past(cyc_cnt) < 8'd11))) |->
            (recieved_data == $past(recieved_data))
    );

    // recieve_status reflects whether the previous recieved_data matched the fixed pattern.
    check_status_matches_previous_data: assert property (
        @(posedge clk) disable iff (!rst)
        (recieve_status == ((($past(recieved_data) == 11'b00011110101) ? 1'b1 : 1'b0)))
    );

endmodule

rtl:
module and_module(
    input wire a,
    input wire b,
    input wire c,
    input wire d,
    output wire out0,
    output wire out1,
    output wire out2,
    output wire out3
);

    assign out0 = a & b;
    assign out1 = b & c;
    assign out2 = (a == 1) ? d : 1'b0;
    assign out3 = b & d;

endmodule

sva:
module and_module_sva (
    input logic a,
    input logic b,
    input logic c,
    input logic d,
    input logic out0,
    input logic out1,
    input logic out2,
    input logic out3
);

    // out0 is the AND of a and b.
    check_out0_is_and_ab: assert property (
        @($global_clock) out0 == (a & b)
    );

    // out1 is the AND of b and c.
    check_out1_is_and_bc: assert property (
        @($global_clock) out1 == (b & c)
    );

    // out2 follows the conditional assignment from a and d.
    check_out2_is_conditional_ad: assert property (
        @($global_clock) out2 == ((a == 1'b1) ? d : 1'b0)
    );

    // out3 is the AND of b and d.
    check_out3_is_and_bd: assert property (
        @($global_clock) out3 == (b & d)
    );

endmodule

rtl:
module twos_complement(
    input [3:0] num_in,
    output [3:0] num_out
);

    wire [3:0] inverted_num;
    wire [3:0] one = 4'b0001;

    assign inverted_num = ~num_in;
    assign num_out = inverted_num + one;

endmodule

sva:
module twos_complement_sva (
    input logic [3:0] num_in,
    input logic [3:0] num_out
);

    // Sample the combinational function on the formal global clock.
    // Output must equal bitwise inversion of input plus one.
    check_twos_complement_equation: assert property (
        @($global_clock) num_out == (~num_in + 4'b0001)
    );

    // Applying two's complement to the output must recover the input.
    check_twos_complement_involution: assert property (
        @($global_clock) ((~num_out) + 4'b0001) == num_in
    );

    // Input and output must sum to zero modulo 16.
    check_additive_inverse: assert property (
        @($global_clock) (num_in + num_out) == 4'b0000
    );

    // Zero must remain unchanged.
    check_zero_fixed_point: assert property (
        @($global_clock) (num_in == 4'b0000) |-> (num_out == 4'b0000)
    );

    // 4'b1000 must remain unchanged.
    check_most_negative_fixed_point: assert property (
        @($global_clock) (num_in == 4'b1000) |-> (num_out == 4'b1000)
    );

    // All other inputs must produce a different output value.
    check_non_fixed_points_change: assert property (
        @($global_clock) ((num_in != 4'b0000) && (num_in != 4'b1000)) |-> (num_out != num_in)
    );

endmodule

rtl:
module usb_system_clocks_dffpipe_l2c(
    input clock,
    input clrn,
    input d,
    output q
);

    reg q_reg;

    always @(posedge clock or negedge clrn) begin
        if (~clrn) begin
            q_reg <= 1'b0;
        end else begin
            q_reg <= d;
        end
    end

    assign q = q_reg;

endmodule

module latch_module(
    input clk,
    input din,
    input reset_n,
    output dout
);

    reg dff_input;
    wire dff_output;

    always @ (posedge clk or negedge reset_n) begin
        if (~reset_n) begin
            dff_input <= 1'b0;
        end else begin
            dff_input <= din;
        end
    end

    assign dout = dff_output;

    usb_system_clocks_dffpipe_l2c dff_inst(
        .clock(clk),
        .clrn(reset_n),
        .d(dff_input),
        .q(dff_output)
    );

endmodule

sva:
module latch_module_sva (
    input logic clk,
    input logic din,
    input logic reset_n,
    input logic dout
);

    // Reset clears the output on any sampled clock while reset is active.
    check_reset_forces_dout_low: assert property (
        @(posedge clk) !reset_n |-> (dout == 1'b0)
    );

    // A sampled active reset keeps the output low on the next clock.
    check_reset_keeps_dout_low_next_cycle: assert property (
        @(posedge clk) !reset_n |=> (dout == 1'b0)
    );

    // A sampled active reset keeps the output low for one additional clock.
    check_reset_keeps_dout_low_two_cycles_later: assert property (
        @(posedge clk) !reset_n |=> ##1 (dout == 1'b0)
    );

    // A high output requires reset to have been inactive on the prior sampled clock.
    check_high_dout_requires_reset_inactive_prev_cycle: assert property (
        @(posedge clk) disable iff (!reset_n)
        (!$initstate && (dout == 1'b1)) |-> $past(reset_n)
    );

    // A high output requires reset to have been inactive two sampled clocks earlier.
    check_high_dout_requires_reset_inactive_two_cycles_back: assert property (
        @(posedge clk) disable iff (!reset_n)
        (!$initstate && !$past($initstate) && (dout == 1'b1)) |-> $past(reset_n, 2)
    );

    // A high output can only come from a high input sampled two clocks earlier.
    check_high_dout_matches_high_din_two_cycles_back: assert property (
        @(posedge clk) disable iff (!reset_n)
        (!$initstate && !$past($initstate) && (dout == 1'b1)) |-> $past(din, 2)
    );

endmodule

rtl:
module binary_adder (
    input [7:0] a,
    input [7:0] b,
    output [7:0] sum,
    output carry
);

    assign {carry, sum} = a + b;

endmodule

module bitwise_and (
    input [7:0] a,
    input [7:0] b,
    output [7:0] result
);

    assign result = a & b;

endmodule

module top_module (
    input clk,
    input reset, // Synchronous active-high reset
    input [7:0] a, // 8-bit input for the binary adder
    input [7:0] b, // 8-bit input for the binary adder
    output [8:0] sum_and_carry // 9-bit output with MSB representing the carry bit
);

    wire [7:0] and_result;
    wire [7:0] adder_sum;
    wire adder_carry;

    binary_adder adder_inst (
        .a(a),
        .b(b),
        .sum(adder_sum),
        .carry(adder_carry)
    );

    bitwise_and and_inst (
        .a(a),
        .b(b),
        .result(and_result)
    );

    assign sum_and_carry = {adder_carry, and_result & adder_sum};

endmodule

sva:
module top_module_assertions (
    input logic clk,
    input logic reset,
    input logic [7:0] a,
    input logic [7:0] b,
    input logic [8:0] sum_and_carry
);

    // Output matches the masked 9-bit addition implemented by the RTL.
    check_output_matches_masked_add: assert property (
        @(posedge clk) disable iff (reset)
        sum_and_carry == (({1'b0, a} + {1'b0, b}) & {1'b1, (a & b)})
    );

    // Carry bit matches the carry-out of the 8-bit addition.
    check_carry_matches_addition: assert property (
        @(posedge clk) disable iff (reset)
        sum_and_carry[8] == (({1'b0, a} + {1'b0, b}) > 9'h0ff)
    );

    // Low byte equals the bitwise-AND result masked by the adder sum.
    check_low_byte_matches_and_of_sum: assert property (
        @(posedge clk) disable iff (reset)
        sum_and_carry[7:0] == ((a & b) & (a + b))
    );

    // Low byte can only set bits that are set in both inputs.
    check_low_byte_subset_of_input_and: assert property (
        @(posedge clk) disable iff (reset)
        (sum_and_carry[7:0] & ~(a & b)) == 8'h00
    );

    // If either operand is zero, the combined output is zero.
    check_zero_operand_gives_zero_output: assert property (
        @(posedge clk) disable iff (reset)
        ((a == 8'h00) || (b == 8'h00)) |-> (sum_and_carry == 9'h000)
    );

    // All-ones operands produce carry with a low byte of 8'hfe.
    check_all_ones_corner_case: assert property (
        @(posedge clk) disable iff (reset)
        ((a == 8'hff) && (b == 8'hff)) |-> (sum_and_carry == 9'h1fe)
    );

endmodule

rtl:
module bitwise_logic(
  input in1,
  input in2,
  input in3,
  output out1
);

  wire not_in3;
  wire and_in1_in2;
  wire or_and_not;

  assign not_in3 = ~in3;
  assign and_in1_in2 = in1 & in2;
  assign or_and_not = and_in1_in2 | not_in3;

  assign out1 = or_and_not;

endmodule

sva:
module bitwise_logic_sva (
    input logic clk,
    input logic in1,
    input logic in2,
    input logic in3,
    input logic out1
);

    // out1 must implement (in1 & in2) | ~in3.
    check_output_equation: assert property (
        @(posedge clk) out1 == ((in1 & in2) | (~in3))
    );

    // A low in3 forces out1 high.
    check_in3_low_forces_out1_high: assert property (
        @(posedge clk) (in3 == 1'b0) |-> (out1 == 1'b1)
    );

    // With in3 high, out1 reduces to in1 & in2.
    check_in3_high_reduces_to_and: assert property (
        @(posedge clk) (in3 == 1'b1) |-> (out1 == (in1 & in2))
    );

    // Both data inputs high force out1 high.
    check_both_inputs_high_force_out1_high: assert property (
        @(posedge clk) ((in1 == 1'b1) && (in2 == 1'b1)) |-> (out1 == 1'b1)
    );

    // With in3 high, a low in1 forces out1 low.
    check_in3_high_and_in1_low_force_out1_low: assert property (
        @(posedge clk) ((in3 == 1'b1) && (in1 == 1'b0)) |-> (out1 == 1'b0)
    );

    // With in3 high, a low in2 forces out1 low.
    check_in3_high_and_in2_low_force_out1_low: assert property (
        @(posedge clk) ((in3 == 1'b1) && (in2 == 1'b0)) |-> (out1 == 1'b0)
    );

    // A low out1 can occur only when in3 is high and one input is low.
    check_low_output_characterization: assert property (
        @(posedge clk) (out1 == 1'b0) |-> ((in3 == 1'b1) && ((in1 == 1'b0) || (in2 == 1'b0)))
    );

    // If out1 is high while in3 is high, both inputs must be high.
    check_high_output_with_in3_high_requires_both_inputs: assert property (
        @(posedge clk) ((out1 == 1'b1) && (in3 == 1'b1)) |-> ((in1 == 1'b1) && (in2 == 1'b1))
    );

