rtl:
module top_module (
    input clk,
    input reset,
    input [7:0] d,
    input [7:0] in,
    output [7:0] q,
    output [7:0] rising_edge,
    output [7:0] sum_output
);

    // 8 D flip-flops with active high synchronous reset
    reg [7:0] q_reg;
    always @(posedge clk) begin
        if (reset) begin
            q_reg <= 8'b11111111;
        end else begin
            q_reg <= d;
        end
    end
    assign q = q_reg;

    // Module that detects the rising edges of an 8-bit binary number
    reg [7:0] in_reg;
    reg [7:0] rising_edge_reg;
    always @(posedge clk) begin
        in_reg <= in;
        rising_edge_reg <= (in_reg ^ (in_reg >> 1)) & (in_reg >> 1);
    end
    assign rising_edge = rising_edge_reg;

    // Additional functional module that outputs the sum of the rising edge detection module and the 8 D flip-flops module
    reg [7:0] sum_output_reg;
    always @(posedge clk) begin
        sum_output_reg <= q_reg + rising_edge_reg;
    end
    assign sum_output = sum_output_reg;

endmodule

sva:
module top_module_sva (
    input logic        clk,
    input logic        reset,
    input logic [7:0]  d,
    input logic [7:0]  in,
    input logic [7:0]  q,
    input logic [7:0]  rising_edge,
    input logic [7:0]  sum_output
);

    // q goes to all 1s one cycle after reset is sampled high.
    check_q_resets_to_ones: assert property (
        @(posedge clk)
        reset |=> (q == 8'hFF)
    );

    // q captures d one cycle after reset is sampled low.
    check_q_captures_d: assert property (
        @(posedge clk)
        (!reset) |=> (q == $past(d))
    );

    // rising_edge matches the implemented two-cycle delayed detection function of in.
    check_rising_edge_matches_function: assert property (
        @(posedge clk)
        1'b1 |-> ##2 (rising_edge == (($past(in,2) ^ ($past(in,2) >> 1)) & ($past(in,2) >> 1)))
    );

    // While not in reset, the MSB of rising_edge is always 0 after the pipeline delay.
    check_rising_edge_msb_zero: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |-> ##2 (rising_edge[7] == 1'b0)
    );

    // sum_output is the registered sum of the previous cycle's q and rising_edge.
    check_sum_output_matches_previous_sum: assert property (
        @(posedge clk)
        1'b1 |=> (sum_output == ($past(q) + $past(rising_edge)))
    );

endmodule

rtl:
module binary_counter(clk, reset, count, overflow);
  input clk, reset;
  output reg [3:0] count;
  output reg overflow;

  always @(posedge clk) begin
    if (reset) begin
      count <= 4'b0000;
      overflow <= 1'b0;
    end
    else if (count == 4'b1111) begin
      count <= 4'b0000;
      overflow <= 1'b1;
    end
    else begin
      count <= count + 1;
      overflow <= 1'b0;
    end
  end
endmodule

sva:
module binary_counter_sva (
    input logic       clk,
    input logic       reset,
    input logic [3:0] count,
    input logic       overflow
);

    // Reset drives the counter state and overflow low on the next cycle.
    check_reset_clears_state: assert property (
        @(posedge clk) disable iff ($initstate)
        (reset == 1'b1) |=> (count == 4'b0000 && overflow == 1'b0)
    );

    // A non-max count increments by one and keeps overflow low.
    check_increment_path: assert property (
        @(posedge clk) disable iff ($initstate)
        ((reset == 1'b0) && (count != 4'hF)) |=> (count == ($past(count) + 4'd1) && overflow == 1'b0)
    );

    // A max count wraps to zero and raises overflow on the next cycle.
    check_wrap_path: assert property (
        @(posedge clk) disable iff ($initstate)
        ((reset == 1'b0) && (count == 4'hF)) |=> (count == 4'h0 && overflow == 1'b1)
    );

    // Overflow can only be high when the count value is zero.
    check_overflow_implies_zero_count: assert property (
        @(posedge clk) disable iff ($initstate)
        (overflow == 1'b1) |-> (count == 4'h0)
    );

    // Overflow only comes from a non-reset wrap from 4'hF.
    check_overflow_only_after_wrap: assert property (
        @(posedge clk) disable iff ($initstate)
        (overflow == 1'b1) |-> ($past(reset) == 1'b0 && $past(count) == 4'hF)
    );

    // Overflow is a one-cycle pulse.
    check_overflow_single_cycle: assert property (
        @(posedge clk) disable iff ($initstate)
        (overflow == 1'b1) |=> (overflow == 1'b0)
    );

endmodule

