rtl:
module alu (
    input [3:0] data1,
    input [3:0] data2,
    input [1:0] op,
    output reg [3:0] q,
    input clk
);

reg [3:0] stage1_out;
reg [3:0] stage2_out;

always @(*) begin
    case(op)
        2'b00: stage1_out = data1 + data2;
        2'b01: stage1_out = data1 - data2;
        2'b10: stage1_out = data1 & data2;
        2'b11: stage1_out = data1 | data2;
    endcase
end

always @(posedge clk) begin
    q <= stage2_out;
    stage2_out <= stage1_out;
end

endmodule

sva:
module alu_sva (
    input logic [3:0] data1,
    input logic [3:0] data2,
    input logic [1:0] op,
    input logic [3:0] q,
    input logic clk
);

    // q reflects the add result from two cycles earlier.
    check_q_add_two_cycle_latency: assert property (
        @(posedge clk)
        (op == 2'b00) |-> ##2 (q == (($past(data1, 2) + $past(data2, 2)) & 4'hF))
    );

    // q reflects the subtract result from two cycles earlier.
    check_q_sub_two_cycle_latency: assert property (
        @(posedge clk)
        (op == 2'b01) |-> ##2 (q == (($past(data1, 2) - $past(data2, 2)) & 4'hF))
    );

    // q reflects the bitwise AND result from two cycles earlier.
    check_q_and_two_cycle_latency: assert property (
        @(posedge clk)
        (op == 2'b10) |-> ##2 (q == ($past(data1, 2) & $past(data2, 2)))
    );

    // q reflects the bitwise OR result from two cycles earlier.
    check_q_or_two_cycle_latency: assert property (
        @(posedge clk)
        (op == 2'b11) |-> ##2 (q == ($past(data1, 2) | $past(data2, 2)))
    );

    // q always matches the operation selected two cycles earlier.
    check_q_matches_selected_operation: assert property (
        @(posedge clk)
        1'b1 |-> ##2 (
            q == (
                ($past(op, 2) == 2'b00) ? ((($past(data1, 2) + $past(data2, 2)) & 4'hF)) :
                ($past(op, 2) == 2'b01) ? ((($past(data1, 2) - $past(data2, 2)) & 4'hF)) :
                ($past(op, 2) == 2'b10) ? (($past(data1, 2) & $past(data2, 2))) :
                                          (($past(data1, 2) | $past(data2, 2)))
            )
        )
    );

endmodule

module var11_multi_sva (
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic E,
    input logic F,
    input logic G,
    input logic H,
    input logic I,
    input logic J,
    input logic K,
    input logic valid
);

    wire [7:0] min_value  = 8'd107;
    wire [7:0] max_weight = 8'd60;
    wire [7:0] max_volume = 8'd60;

    wire [7:0] total_value =
          A * 8'd4
        + B * 8'd8
        + C * 8'd0
        + D * 8'd20
        + E * 8'd10
        + F * 8'd12
        + G * 8'd18
        + H * 8'd14
        + I * 8'd6
        + J * 8'd15
        + K * 8'd30;

    wire [7:0] total_weight =
          A * 8'd28
        + B * 8'd8
        + C * 8'd27
        + D * 8'd18
        + E * 8'd27
        + F * 8'd28
        + G * 8'd6
        + H * 8'd1
        + I * 8'd20
        + J * 8'd0
        + K * 8'd5;

    wire [7:0] total_volume =
          A * 8'd27
        + B * 8'd27
        + C * 8'd4
        + D * 8'd4
        + E * 8'd0
        + F * 8'd24
        + G * 8'd4
        + H * 8'd20
        + I * 8'd12
        + J * 8'd15
        + K * 8'd5;

    // valid must match the implemented threshold comparison.
    check_valid_definition: assert property (
        @($global_clock)
        valid == ((total_value >= min_value) &&
                  (total_weight <= max_weight) &&
                  (total_volume <= max_volume))
    );

    // Value below the minimum must force valid low.
    check_invalid_if_value_below_min: assert property (
        @($global_clock)
        (total_value < min_value) |-> !valid
    );

    // Weight above the maximum must force valid low.
    check_invalid_if_weight_above_max: assert property (
        @($global_clock)
        (total_weight > max_weight) |-> !valid
    );

    // Volume above the maximum must force valid low.
    check_invalid_if_volume_above_max: assert property (
        @($global_clock)
        (total_volume > max_volume) |-> !valid
    );

    // Meeting all three constraints must make valid high.
    check_valid_if_all_constraints_met: assert property (
        @($global_clock)
        ((total_value >= min_value) &&
         (total_weight <= max_weight) &&
         (total_volume <= max_volume)) |-> valid
    );

    // Selecting no items must be invalid.
    check_empty_selection_invalid: assert property (
        @($global_clock)
        (!A && !B && !C && !D && !E && !F && !G && !H && !I && !J && !K) |-> !valid
    );

    // This bundle is under the value threshold while staying within limits.
    check_low_value_bundle_invalid: assert property (
        @($global_clock)
        (!A && !B && !C && D && !E && !F && G && H && !I && J && K) |-> !valid
    );

    // This bundle exactly reaches the minimum value within both limits.
    check_threshold_bundle_valid: assert property (
        @($global_clock)
        (!A && !B && !C && D && E && !F && G && H && !I && J && K) |-> valid
    );

    // This bundle exceeds weight while volume remains within the limit.
    check_overweight_bundle_invalid: assert property (
        @($global_clock)
        (!A && !B && !C && D && E && !F && G && H && I && J && K) |-> !valid
    );

    // This bundle exceeds volume while weight remains within the limit.
    check_overvolume_bundle_invalid: assert property (
        @($global_clock)
        (!A && B && !C && D && !E && !F && G && H && I && J && K) |-> !valid
    );

endmodule

rtl:
module top_module( 
    input clk,
    input [3:0] a,
    input [3:0] b,
    input d,
    output [3:0] out_nand_bitwise,
    output out_nand_logical,
    output [3:0] out_xor_bitwise,
    output out_xor_logical,
    output q
);

    // Logical Operations Module
    wire [3:0] nand_bitwise;
    wire nand_logical;
    wire [3:0] xor_bitwise;
    wire xor_logical;

    nand_4bit nand_inst(
        .a(a),
        .b(b),
        .out(nand_bitwise)
    );

    nand_logical_4bit nand_logical_inst(
        .a(a),
        .b(b),
        .out(nand_logical)
    );

    xor_4bit xor_inst(
        .a(a),
        .b(b),
        .out(xor_bitwise)
    );

    xor_logical_4bit xor_logical_inst(
        .a(a),
        .b(b),
        .out(xor_logical)
    );

    // Shift Register
    reg [3:0] shift_reg;

    always @(posedge clk) begin
        shift_reg <= {shift_reg[2:0], d};
    end

    // Functional Module
    assign out_nand_bitwise = nand_bitwise;
    assign out_nand_logical = nand_logical;
    assign out_xor_bitwise = xor_bitwise;
    assign out_xor_logical = xor_logical;
    assign q = shift_reg[3] & (nand_logical & shift_reg[0] & shift_reg[1] & shift_reg[2]);

endmodule

module nand_4bit(
    input [3:0] a,
    input [3:0] b,
    output [3:0] out
);

    assign out = ~(a & b);

endmodule

module nand_logical_4bit(
    input [3:0] a,
    input [3:0] b,
    output out
);

    assign out = ~(a & b) == 4'b1111;

endmodule

module xor_4bit(
    input [3:0] a,
    input [3:0] b,
    output [3:0] out
);

    assign out = a ^ b;

endmodule

module xor_logical_4bit(
    input [3:0] a,
    input [3:0] b,
    output out
);

    assign out = (a ^ b) == 4'b0000;

endmodule

