    input logic [3:0] quot
);

    // Addition mode updates sum and clears the other outputs.
    check_addition_mode: assert property (
        @(posedge clk)
        (op == 2'b00) |-> ((sum  == ((A + B) & 4'hF)) &&
                           (diff == 4'h0) &&
                           (prod == 4'h0) &&
                           (quot == 4'h0))
    );

    // Subtraction mode updates diff and clears the other outputs.
    check_subtraction_mode: assert property (
        @(posedge clk)
        (op == 2'b01) |-> ((sum  == 4'h0) &&
                           (diff == ((A - B) & 4'hF)) &&
                           (prod == 4'h0) &&
                           (quot == 4'h0))
    );

    // Multiplication mode updates prod and clears the other outputs.
    check_multiplication_mode: assert property (
        @(posedge clk)
        (op == 2'b10) |-> ((sum  == 4'h0) &&
                           (diff == 4'h0) &&
                           (prod == ((A * B) & 4'hF)) &&
                           (quot == 4'h0))
    );

    // Division by zero forces quot low and clears the other outputs.
    check_division_by_zero_mode: assert property (
        @(posedge clk)
        ((op == 2'b11) && (B == 4'h0)) |-> ((sum  == 4'h0) &&
                                            (diff == 4'h0) &&
                                            (prod == 4'h0) &&
                                            (quot == 4'h0))
    );

    // Division mode updates quot for nonzero divisor and clears the other outputs.
    check_division_mode: assert property (
        @(posedge clk)
        ((op == 2'b11) && (B != 4'h0)) |-> ((sum  == 4'h0) &&
                                            (diff == 4'h0) &&
                                            (prod == 4'h0) &&
                                            (quot == ((A / B) & 4'hF)))
    );

endmodule

rtl:
module calculator (
    input [3:0] reg_a,
    input [3:0] reg_b,
    input [1:0] op,
    input start,
    output reg [3:0] result
);

    always @ (op or start or reg_a or reg_b)
    begin
        case (op)
            2'b00: result = reg_a + reg_b;
            2'b01: result = reg_a - reg_b;
            2'b10: result = reg_a * reg_b;
            2'b11: result = reg_a / reg_b;
        endcase
    end

endmodule

sva:
module calculator_sva (
    input logic clk,
    input logic [3:0] reg_a,
    input logic [3:0] reg_b,
    input logic [1:0] op,
    input logic start,
    input logic [3:0] result
);

    // clk is an external sampling clock because the RTL has no native clock or reset.

    // op=00 returns the truncated sum.
    check_add_result: assert property (
        @(posedge clk)
        (op == 2'b00) |-> (result == ((reg_a + reg_b) & 4'hf))
    );

    // op=01 returns the truncated difference.
    check_subtract_result: assert property (
        @(posedge clk)
        (op == 2'b01) |-> (result == ((reg_a - reg_b) & 4'hf))
    );

    // op=10 returns the low 4 bits of the product.
    check_multiply_result: assert property (
        @(posedge clk)
        (op == 2'b10) |-> (result == ((reg_a * reg_b) & 4'hf))
    );

    // op=11 returns the quotient when the divisor is nonzero.
    check_divide_result: assert property (
        @(posedge clk)
        (op == 2'b11 && reg_b != 4'b0000) |-> (result == ((reg_a / reg_b) & 4'hf))
    );

    // With op and operands unchanged, the sampled result stays unchanged.
    check_result_stable_when_function_inputs_stable: assert property (
        @(posedge clk)
        ($stable(op) && $stable(reg_a) && $stable(reg_b) &&
         !((op == 2'b11) && (reg_b == 4'b0000))) |-> $stable(result)
    );

    // Changing start alone does not change the sampled result.
    check_start_does_not_change_result: assert property (
        @(posedge clk)
        ($changed(start) && $stable(op) && $stable(reg_a) && $stable(reg_b) &&
         !((op == 2'b11) && (reg_b == 4'b0000))) |-> $stable(result)
    );

endmodule

module shift_left_register_sva (
    input logic clk,
    input logic reset,
    input logic parallel_load,
    input logic shift,
    input logic [3:0] input_data,
    input logic [3:0] output_data
);

    // Reset drives the register output to zero.
    check_reset_clears_output: assert property (
        @(posedge clk) reset |=> (output_data == 4'b0000)
    );

    // Parallel load captures input_data on the next clock.
    check_parallel_load: assert property (
        @(posedge clk) disable iff (reset)
        parallel_load |=> (output_data == $past(input_data))
    );

    // Shift moves the stored value left and inserts zero in the LSB.
    check_shift_left: assert property (
        @(posedge clk) disable iff (reset)
        (shift && !parallel_load) |=> (output_data == {$past(output_data[2:0]), 1'b0})
    );

    // Parallel load has priority over shift when both are asserted.
    check_load_priority: assert property (
        @(posedge clk) disable iff (reset)
        (parallel_load && shift) |=> (output_data == $past(input_data))
    );

    // The register holds its value when neither control is asserted.
    check_hold_when_idle: assert property (
        @(posedge clk) disable iff (reset)
        (!parallel_load && !shift) |=> (output_data == $past(output_data))
    );

endmodule

rtl:
module barrel_shifter_register (
    input wire [15:0] in,
    input wire clk,
    input wire reset,
    output wire [7:0] q
);

reg [7:0] register;

always @(posedge clk) begin
    if (reset) begin
        register <= 8'b0;
    end else begin
        register <= in[15:8];
    end
end

assign q = register;

endmodule

module top_module (
    input wire [15:0] in,
    input wire clk,
    input wire reset,
    output wire [7:0] q
);

wire [7:0] register_output;

barrel_shifter_register barrel_shifter_register_inst (
    .in(in),
    .clk(clk),
    .reset(reset),
    .q(register_output)
);

assign q = register_output;

endmodule

sva:
module top_module_sva (
    input logic [15:0] in,
    input logic clk,
    input logic reset,
    input logic [7:0] q
);

    // A reset cycle clears q by the next clock.
    check_reset_clears_q: assert property (
        @(posedge clk) reset |=> (q == 8'h00)
    );

    // While reset is held, q remains zero.
    check_held_reset_keeps_q_zero: assert property (
        @(posedge clk) (reset && $past(reset)) |-> (q == 8'h00)
    );

    // A non-reset cycle loads the upper byte of in into q.
    check_loads_upper_byte: assert property (
        @(posedge clk) disable iff (reset)
        !reset |=> (q == $past(in[15:8]))
    );

    // Changing only the lower byte of in does not change q.
    check_lower_byte_is_ignored: assert property (
        @(posedge clk) disable iff (reset)
        (!$past(reset) && !$past(reset,2) &&
         ($past(in[15:8]) == $past(in[15:8],2)) &&
         ($past(in[7:0]) != $past(in[7:0],2)))
        |-> (q == $past(q))
    );

endmodule

rtl:
module mux2to1 (
    input I0,
    input I1,
    input S,
    output reg Y
);

    always @ (*) begin
        if (S == 1'b0)
            Y = I0;
        else
            Y = I1;
    end

endmodule

module mux4to1(
    input D0,
    input D1,
    input D2,
    input D3,
    input S0,
    input S1,
    output Y
);

    wire w1, w2, w3;

    mux2to1 m1 (
        .I0(D0),
        .I1(D1),
        .S(S0),
        .Y(w1)
    );

    mux2to1 m2 (
        .I0(D2),
        .I1(D3),
        .S(S0),
        .Y(w2)
    );

    mux2to1 m3 (
        .I0(w1),
        .I1(w2),
        .S(S1),
        .Y(w3)
    );

    assign Y = w3;

endmodule

sva:
module mux4to1_sva (
    input logic clk,
    input logic D0,
    input logic D1,
    input logic D2,
    input logic D3,
    input logic S0,
    input logic S1,
    input logic Y
);

    // Select 00 routes D0 to Y.
    check_select_d0: assert property (
        @(posedge clk) (S1 === 1'b0 && S0 === 1'b0) |-> (Y === D0)
    );

    // Select 01 routes D1 to Y.
    check_select_d1: assert property (
        @(posedge clk) (S1 === 1'b0 && S0 === 1'b1) |-> (Y === D1)
    );

    // Select 10 routes D2 to Y.
    check_select_d2: assert property (
        @(posedge clk) (S1 === 1'b1 && S0 === 1'b0) |-> (Y === D2)
    );

    // Select 11 routes D3 to Y.
    check_select_d3: assert property (
        @(posedge clk) (S1 === 1'b1 && S0 === 1'b1) |-> (Y === D3)
    );

    // If all inputs are stable, the output must remain stable.
    check_stable_inputs_hold_output: assert property (
        @(posedge clk) $stable({D0, D1, D2, D3, S0, S1}) |-> $stable(Y)
    );

    // With select 00 held and D0 stable, unselected inputs must not affect Y.
    check_only_d0_matters_when_sel00: assert property (
        @(posedge clk) (S1 === 1'b0 && S0 === 1'b0 && $stable({S1, S0, D0})) |-> $stable(Y)
    );

    // With select 01 held and D1 stable, unselected inputs must not affect Y.
    check_only_d1_matters_when_sel01: assert property (
        @(posedge clk) (S1 === 1'b0 && S0 === 1'b1 && $stable({S1, S0, D1})) |-> $stable(Y)
    );

    // With select 10 held and D2 stable, unselected inputs must not affect Y.
    check_only_d2_matters_when_sel10: assert property (
        @(posedge clk) (S1 === 1'b1 && S0 === 1'b0 && $stable({S1, S0, D2})) |-> $stable(Y)
    );

    // With select 11 held and D3 stable, unselected inputs must not affect Y.
    check_only_d3_matters_when_sel11: assert property (
        @(posedge clk) (S1 === 1'b1 && S0 === 1'b1 && $stable({S1, S0, D3})) |-> $stable(Y)
    );

endmodule

rtl:
module my_logic_gate (
    X ,
    A1,
    A2,
    B1,
    C1
);

    output X ;
    input  A1;
    input  A2;
    input  B1;
    input  C1;

    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;

    assign X = ((A1 & A2 & ~B1 & ~C1) | (A1 | A2 | (B1 & C1)) | (~A1 & A2 & B1 & C1)) ? 1'b1 : 1'b0;

endmodule

sva:
module my_logic_gate_sva (
    input logic X,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic C1
);

    // No RTL clock or reset; sample the combinational behavior on $global_clock.

    // Output matches the implemented combinational equation.
    check_output_matches_rtl: assert property (
        @($global_clock)
        X == (((A1 & A2 & ~B1 & ~C1) | (A1 | A2 | (B1 & C1)) | (~A1 & A2 & B1 & C1)) ? 1'b1 : 1'b0)
    );

    // A1 high forces the output high.
    check_a1_forces_high: assert property (
        @($global_clock)
        A1 |-> (X == 1'b1)
    );

    // A2 high forces the output high.
    check_a2_forces_high: assert property (
        @($global_clock)
        A2 |-> (X == 1'b1)
    );

    // B1 and C1 high together force the output high.
    check_b1_c1_force_high: assert property (
        @($global_clock)
        (B1 && C1) |-> (X == 1'b1)
    );

    // Without A1 or A2, the output stays low unless both B1 and C1 are high.
    check_low_when_no_enabling_term: assert property (
        @($global_clock)
        (!A1 && !A2 && (!B1 || !C1)) |-> (X == 1'b0)
    );

endmodule

bind my_logic_gate my_logic_gate_sva my_logic_gate_sva_inst (
    .X(X),
    .A1(A1),
    .A2(A2),
    .B1(B1),
    .C1(C1)
);

rtl:
module binary_to_gray(
  input [7:0] bin_in,
  output [7:0] gray_out
);

  wire [7:0] bin_to_gray; // Temporary variable to calculate binary code

  // Calculate binary code by xoring gray_out with shifted bin_to_gray
  assign gray_out = bin_in ^ ({bin_in[7], bin_in[7:1]});
  assign bin_to_gray = gray_out ^ ({gray_out[7], gray_out[7:1]});

endmodule

sva:
module binary_to_gray_sva (
    input logic       clk,
    input logic [7:0] bin_in,
    input logic [7:0] gray_out
);

    // gray_out must match the implemented XOR/shift equation.
    check_gray_equation: assert property (
        @(posedge clk) gray_out == (bin_in ^ {bin_in[7], bin_in[7:1]})
    );

    // The implemented MSB equation forces gray_out[7] low.
    check_gray_msb_zero: assert property (
        @(posedge clk) gray_out[7] == 1'b0
    );

    // The lower seven bits must match adjacent-bit XORs from bin_in.
    check_gray_lower_bits_equation: assert property (
        @(posedge clk) gray_out[6:0] == (bin_in[6:0] ^ bin_in[7:1])
    );

    // gray_out[6] is bin_in[6] XOR bin_in[7].
    check_gray_bit6_xor: assert property (
        @(posedge clk) gray_out[6] == (bin_in[6] ^ bin_in[7])
    );

    // gray_out[5] is bin_in[5] XOR bin_in[6].
    check_gray_bit5_xor: assert property (
        @(posedge clk) gray_out[5] == (bin_in[5] ^ bin_in[6])
    );

    // gray_out[4] is bin_in[4] XOR bin_in[5].
    check_gray_bit4_xor: assert property (
        @(posedge clk) gray_out[4] == (bin_in[4] ^ bin_in[5])
    );

    // gray_out[3] is bin_in[3] XOR bin_in[4].
    check_gray_bit3_xor: assert property (
        @(posedge clk) gray_out[3] == (bin_in[3] ^ bin_in[4])
    );

    // gray_out[2] is bin_in[2] XOR bin_in[3].
    check_gray_bit2_xor: assert property (
        @(posedge clk) gray_out[2] == (bin_in[2] ^ bin_in[3])
    );

    // gray_out[1] is bin_in[1] XOR bin_in[2].
    check_gray_bit1_xor: assert property (
        @(posedge clk) gray_out[1] == (bin_in[1] ^ bin_in[2])
    );

    // gray_out[0] is bin_in[0] XOR bin_in[1].
    check_gray_bit0_xor: assert property (
        @(posedge clk) gray_out[0] == (bin_in[0] ^ bin_in[1])
    );

endmodule

rtl:
module bitwise_and(
  input [3:0] X,
  input [3:0] Y,
  output reg [3:0] result,
  output reg greater_than_or_equal_to_5
);

  always @* begin
    result = X & Y;

    if (result >= 5) begin
      greater_than_or_equal_to_5 = 1;
    end else begin
      greater_than_or_equal_to_5 = 0;
    end
  end

endmodule

sva:
module bitwise_and_sva (
    input logic clk,
    input logic [3:0] X,
    input logic [3:0] Y,
    input logic [3:0] result,
    input logic greater_than_or_equal_to_5
);

    // result must equal the bitwise AND of X and Y.
    check_result_matches_bitwise_and: assert property (
        @(posedge clk) result == (X & Y)
    );

    // The flag must reflect whether result is at least 5.
    check_flag_matches_result_threshold: assert property (
        @(posedge clk) greater_than_or_equal_to_5 == (result >= 4'd5)
    );

    // A high flag implies the result is 5 or greater.
    check_flag_high_implies_result_ge_5: assert property (
        @(posedge clk) greater_than_or_equal_to_5 |-> (result >= 4'd5)
    );

    // A low flag implies the result is less than 5.
    check_flag_low_implies_result_lt_5: assert property (
        @(posedge clk) !greater_than_or_equal_to_5 |-> (result < 4'd5)
    );

    // The flag must also match the threshold of the ANDed inputs directly.
    check_flag_matches_and_threshold: assert property (
        @(posedge clk) greater_than_or_equal_to_5 == ((X & Y) >= 4'd5)
    );

endmodule

rtl:
module INSTRUCTION_FETCH_STAGE #(
        parameter   ADDRESS_WIDTH           = 32                            ,

        parameter   HIGH                    = 1'b1                          ,
        parameter   LOW                     = 1'b0
    ) (
        input                               CLK                             ,
        input                               STALL_INSTRUCTION_FETCH_STAGE   ,
        input                               CLEAR_INSTRUCTION_FETCH_STAGE   ,
        input   [ADDRESS_WIDTH - 1  : 0]    PC_IN                           ,
        input                               PC_VALID_IN                     ,
        output  [ADDRESS_WIDTH - 1  : 0]    PC_OUT                          ,
        output                              PC_VALID_OUT     
    );

    reg     [ADDRESS_WIDTH - 1  : 0]    pc_reg                              ;
    reg                                 pc_valid_reg                        ;

    always@(posedge CLK) 
    begin
        if(CLEAR_INSTRUCTION_FETCH_STAGE == LOW)
        begin
            if(STALL_INSTRUCTION_FETCH_STAGE == LOW) 
            begin
                pc_reg          <= PC_IN        ;
                pc_valid_reg    <= PC_VALID_IN  ;
            end
        end
        else
        begin
            pc_reg          <= 32'b0;
            pc_valid_reg    <= LOW  ;
        end
    end

    assign PC_OUT       = pc_reg        ;
    assign PC_VALID_OUT = pc_valid_reg  ;

endmodule

sva:
module INSTRUCTION_FETCH_STAGE_sva #(
    parameter ADDRESS_WIDTH = 32,
    parameter HIGH          = 1'b1,
    parameter LOW           = 1'b0
) (
    input logic                         CLK,
    input logic                         STALL_INSTRUCTION_FETCH_STAGE,
    input logic                         CLEAR_INSTRUCTION_FETCH_STAGE,
    input logic [ADDRESS_WIDTH-1:0]     PC_IN,
    input logic                         PC_VALID_IN,
    input logic [ADDRESS_WIDTH-1:0]     PC_OUT,
    input logic                         PC_VALID_OUT
);

    // Clear drives the stored PC to zero on the following cycle.
    check_clear_zeroes_pc: assert property (
        @(posedge CLK) disable iff (1'b0)
        (CLEAR_INSTRUCTION_FETCH_STAGE == HIGH) |=> (PC_OUT == {ADDRESS_WIDTH{1'b0}})
    );

    // Clear drives the stored valid bit low on the following cycle.
    check_clear_zeroes_valid: assert property (
        @(posedge CLK) disable iff (1'b0)
        (CLEAR_INSTRUCTION_FETCH_STAGE == HIGH) |=> (PC_VALID_OUT == LOW)
    );

    // When enabled, the stage captures the incoming PC.
    check_loads_pc_when_not_stalled: assert property (
        @(posedge CLK) disable iff (1'b0)
        (CLEAR_INSTRUCTION_FETCH_STAGE == LOW && STALL_INSTRUCTION_FETCH_STAGE == LOW)
        |=> (PC_OUT == $past(PC_IN))
    );

    // When enabled, the stage captures the incoming valid bit.
    check_loads_valid_when_not_stalled: assert property (
        @(posedge CLK) disable iff (1'b0)
        (CLEAR_INSTRUCTION_FETCH_STAGE == LOW && STALL_INSTRUCTION_FETCH_STAGE == LOW)
        |=> (PC_VALID_OUT == $past(PC_VALID_IN))
    );

    // When stalled without clear, the stored PC is held.
    check_stall_holds_pc: assert property (
        @(posedge CLK) disable iff (1'b0)
        (CLEAR_INSTRUCTION_FETCH_STAGE == LOW && STALL_INSTRUCTION_FETCH_STAGE == HIGH)
        |=> (PC_OUT == $past(PC_OUT))
    );

    // When stalled without clear, the stored valid bit is held.
    check_stall_holds_valid: assert property (
        @(posedge CLK) disable iff (1'b0)
        (CLEAR_INSTRUCTION_FETCH_STAGE == LOW && STALL_INSTRUCTION_FETCH_STAGE == HIGH)
        |=> (PC_VALID_OUT == $past(PC_VALID_OUT))
    );

    // Clear has priority over stall when both are asserted.
    check_clear_overrides_stall: assert property (
        @(posedge CLK) disable iff (1'b0)
        (CLEAR_INSTRUCTION_FETCH_STAGE == HIGH && STALL_INSTRUCTION_FETCH_STAGE == HIGH)
        |=> (PC_OUT == {ADDRESS_WIDTH{1'b0}} && PC_VALID_OUT == LOW)
    );

endmodule

rtl:
module Test (
   input [3:0] cnt,
   input [6:0] decr,
   output [3:0] next
);

   // Implement the Test module here
   reg [3:0] next_reg;

   always @(*) begin
      next_reg = cnt ^ decr[3:0];
   end

   assign next = next_reg;

endmodule

sva:
module Test_sva (
    input logic [3:0] cnt,
    input logic [6:0] decr,
    input logic [3:0] next
);

    // Combinational DUT with no explicit clock or reset; sample on $global_clock.

    // next must always equal cnt XOR decr[3:0].
    check_next_matches_xor: assert property (
        @($global_clock) next == (cnt ^ decr[3:0])
    );

    // A zero low nibble in decr passes cnt through unchanged.
    check_zero_low_nibble_passthrough: assert property (
        @($global_clock) (decr[3:0] == 4'h0) |-> (next == cnt)
    );

    // Matching cnt and decr[3:0] must produce zero.
    check_equal_operands_zero_out: assert property (
        @($global_clock) (cnt == decr[3:0]) |-> (next == 4'h0)
    );

    // A low nibble of all ones in decr must invert cnt.
    check_all_ones_low_nibble_inverts_cnt: assert property (
        @($global_clock) (decr[3:0] == 4'hF) |-> (next == ~cnt)
    );

    // If cnt and decr[3:0] do not change, next must not change.
    check_stable_relevant_inputs_hold_output: assert property (
        @($global_clock)
        (!$initstate && (cnt == $past(cnt)) && (decr[3:0] == $past(decr[3:0])))
        |-> (next == $past(next))
    );

    // Changes only in decr[6:4] must not affect next.
    check_upper_bits_ignored: assert property (
        @($global_clock)
        (!$initstate && (cnt == $past(cnt)) && (decr[3:0] == $past(decr[3:0])) &&
         (decr[6:4] != $past(decr[6:4])))
        |-> (next == $past(next))
    );

    // Any change on next must come from cnt or decr[3:0].
    check_output_change_requires_relevant_input_change: assert property (
        @($global_clock)
        (!$initstate && (next != $past(next)))
        |-> ((cnt != $past(cnt)) || (decr[3:0] != $past(decr[3:0])))
    );

endmodule

rtl:
module t_ff_pipeline (
    input clk,
    input d,
    output reg q
);

reg t1, t2;

always @(posedge clk) begin
    t1 <= d;
end

always @(posedge clk) begin
    t2 <= t1;
end

always @(posedge clk) begin
    q <= t2 ^ q;
end

endmodule

sva:
module t_ff_pipeline_sva (
    input logic clk,
    input logic d,
    input logic q
);

    // q equals prior q XOR d delayed by three sampled clocks.
    check_q_matches_three_cycle_delayed_xor: assert property (
        @(posedge clk) $past(1'b1,3) |-> (q == ($past(q) ^ $past(d,3)))
    );

    // A delayed high d sample toggles q.
    check_q_toggles_on_delayed_high_d: assert property (
        @(posedge clk) ($past(1'b1,3) && $past(d,3)) |-> (q != $past(q))
    );

    // A delayed low d sample leaves q unchanged.
    check_q_holds_on_delayed_low_d: assert property (
        @(posedge clk) ($past(1'b1,3) && !$past(d,3)) |-> (q == $past(q))
    );

endmodule

rtl:
module clock_gate (CLK, EN, TE, ENCLK);
  input CLK, EN, TE;
  output ENCLK;

  reg ENCLK;

  always @ (posedge CLK) begin
    if (EN && TE) begin
      ENCLK <= 1'b1;
    end else begin
      ENCLK <= 1'b0;
    end
  end

endmodule

sva:
module clock_gate_sva (
    input logic CLK,
    input logic EN,
    input logic TE,
    input logic ENCLK
);

    // ENCLK is asserted on the next clock when both EN and TE are high.
    check_enclk_asserts_when_en_and_te_high: assert property (
        @(posedge CLK) (EN && TE) |=> (ENCLK == 1'b1)
    );

    // ENCLK is deasserted on the next clock when either EN or TE is low.
    check_enclk_deasserts_when_en_or_te_low: assert property (
        @(posedge CLK) (!EN || !TE) |=> (ENCLK == 1'b0)
    );

endmodule

module binary_counter_sva
#(parameter n = 4)
(
    input logic rst,
    input logic clk,
    input logic [n-1:0] count
);

    localparam logic [n-1:0] ZERO_COUNT = '0;
    localparam logic [n-1:0] ONE_COUNT  = {{(n-1){1'b0}}, 1'b1};
    localparam logic [n-1:0] MAX_COUNT  = {n{1'b1}};

    // Reset drives the counter to zero on the following clock.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |=> (count == ZERO_COUNT)
    );

    // The sampled count matches the RTL next-state function.
    check_state_update_matches_rtl: assert property (
        @(posedge clk) disable iff ($initstate)
        count == ($past(rst) ? ZERO_COUNT :
                 (($past(count) == MAX_COUNT) ? ZERO_COUNT : ($past(count) + ONE_COUNT)))
    );

    // A non-maximum count increments by one on the next non-reset clock.
    check_increment_below_max: assert property (
        @(posedge clk) disable iff (rst)
        (count != MAX_COUNT) |=> (count == ($past(count) + ONE_COUNT))
    );

    // The counter wraps to zero after reaching the maximum value.
    check_wrap_at_max: assert property (
        @(posedge clk) disable iff (rst)
        (count == MAX_COUNT) |=> (count == ZERO_COUNT)
    );

    // Zero advances to one on the next non-reset clock.
    check_zero_advances_to_one: assert property (
        @(posedge clk) disable iff (rst)
        (count == ZERO_COUNT) |=> (count == ONE_COUNT)
    );

    // The count changes on every non-reset clock edge.
    check_count_changes_without_reset: assert property (
        @(posedge clk) disable iff (rst)
        1'b1 |=> (count != $past(count))
    );

endmodule

module up_down_counter_sva (
    input logic       CLK,
    input logic       UP,
    input logic       DOWN,
    input logic       LOAD,
    input logic [3:0] in,
    input logic [3:0] OUT
);

    // LOAD has highest priority and copies in to OUT.
    check_load_captures_input: assert property (
        @(posedge CLK) LOAD |=> (OUT == $past(in))
    );

    // UP increments OUT when LOAD is low and OUT is not at max.
    check_count_up_step: assert property (
        @(posedge CLK) (!LOAD && UP && (OUT != 4'hF)) |=> (OUT == ($past(OUT) + 4'd1))
    );

    // UP wraps OUT from 15 to 0 when LOAD is low.
    check_count_up_wrap: assert property (
        @(posedge CLK) (!LOAD && UP && (OUT == 4'hF)) |=> (OUT == 4'h0)
    );

    // DOWN decrements OUT when selected and OUT is not zero.
    check_count_down_step: assert property (
        @(posedge CLK) (!LOAD && !UP && DOWN && (OUT != 4'h0)) |=> (OUT == ($past(OUT) - 4'd1))
    );

    // DOWN wraps OUT from 0 to 15 when selected.
    check_count_down_wrap: assert property (
        @(posedge CLK) (!LOAD && !UP && DOWN && (OUT == 4'h0)) |=> (OUT == 4'hF)
    );

    // OUT holds its value when no control input is asserted.
    check_hold_when_idle: assert property (
        @(posedge CLK) (!LOAD && !UP && !DOWN) |=> (OUT == $past(OUT))
    );

endmodule

rtl:
module ddr3_s4_uniphy_p0_hr_to_fr(
	clk,
	d_h0,
	d_h1,
	d_l0,
	d_l1,
	q0,
	q1
);

input	clk;
input	d_h0;
input	d_h1;
input	d_l0;
input	d_l1;
output	q0;
output	q1;

reg	q_h0;
reg	q_h1;
reg	q_l0;
reg	q_l1;
reg	q_l0_neg;
reg	q_l1_neg;

	always @(posedge clk)
	begin
		q_h0 <= d_h0;
		q_l0 <= d_l0;
		q_h1 <= d_h1;
		q_l1 <= d_l1;
	end

	always @(negedge clk)
	begin
		q_l0_neg <= q_l0;
		q_l1_neg <= q_l1;
	end

	assign q0 = clk ? q_l0_neg : q_h0;
	assign q1 = clk ? q_l1_neg : q_h1;

endmodule

sva:
module ddr3_s4_uniphy_p0_hr_to_fr_sva (
    input logic clk,
    input logic d_h0,
    input logic d_h1,
    input logic d_l0,
    input logic d_l1,
    input logic q0,
    input logic q1
);

    property p_q0_from_d_h0;
        logic sampled_d_h0;
        @(posedge clk)
            (1'b1, sampled_d_h0 = d_h0) |=> (q0 == sampled_d_h0);
    endproperty

    property p_q1_from_d_h1;
        logic sampled_d_h1;
        @(posedge clk)
            (1'b1, sampled_d_h1 = d_h1) |=> (q1 == sampled_d_h1);
    endproperty

    property p_q0_from_d_l0;
        logic sampled_d_l0;
        @(posedge clk)
            (1'b1, sampled_d_l0 = d_l0) |=> @(negedge clk) (q0 == sampled_d_l0);
    endproperty

    property p_q1_from_d_l1;
        logic sampled_d_l1;
        @(posedge clk)
            (1'b1, sampled_d_l1 = d_l1) |=> @(negedge clk) (q1 == sampled_d_l1);
    endproperty

    // q0 shows the prior captured d_h0 value at the next posedge sample.
    check_q0_from_d_h0: assert property (p_q0_from_d_h0);

    // q1 shows the prior captured d_h1 value at the next posedge sample.
    check_q1_from_d_h1: assert property (p_q1_from_d_h1);

    // q0 shows the captured d_l0 value at the following high-phase negedge sample.
    check_q0_from_d_l0: assert property (p_q0_from_d_l0);

    // q1 shows the captured d_l1 value at the following high-phase negedge sample.
    check_q1_from_d_l1: assert property (p_q1_from_d_l1);

endmodule

module priority_encoder_sva (
    input logic clk,
    input logic [254:0] in,
    input logic [7:0] out
);

    // Exact 0xFF low-byte pattern maps to 255.
    check_ff_maps_to_255: assert property (
        @(posedge clk)
        ((in[254:8] == 247'd0) && (in[7:0] == 8'hFF)) |-> (out == 8'd255)
    );

    // Exact 0xFE low-byte pattern maps to 254.
    check_fe_maps_to_254: assert property (
        @(posedge clk)
        ((in[254:8] == 247'd0) && (in[7:0] == 8'hFE)) |-> (out == 8'd254)
    );

    // Exact 0xFC low-byte pattern maps to 253.
    check_fc_maps_to_253: assert property (
        @(posedge clk)
        ((in[254:8] == 247'd0) && (in[7:0] == 8'hFC)) |-> (out == 8'd253)
    );

    // Exact 0xF8 low-byte pattern maps to 252.
    check_f8_maps_to_252: assert property (
        @(posedge clk)
        ((in[254:8] == 247'd0) && (in[7:0] == 8'hF8)) |-> (out == 8'd252)
    );

    // Exact 0xF0 low-byte pattern maps to 251.
    check_f0_maps_to_251: assert property (
        @(posedge clk)
        ((in[254:8] == 247'd0) && (in[7:0] == 8'hF0)) |-> (out == 8'd251)
    );

    // Exact 0xE0 low-byte pattern maps to 250.
    check_e0_maps_to_250: assert property (
        @(posedge clk)
        ((in[254:8] == 247'd0) && (in[7:0] == 8'hE0)) |-> (out == 8'd250)
    );

    // Any unlisted input pattern maps to 0.
    check_default_maps_to_0: assert property (
        @(posedge clk)
        !((in[254:8] == 247'd0) &&
          ((in[7:0] == 8'hFF) ||
           (in[7:0] == 8'hFE) ||
           (in[7:0] == 8'hFC) ||
           (in[7:0] == 8'hF8) ||
           (in[7:0] == 8'hF0) ||
           (in[7:0] == 8'hE0))) |-> (out == 8'd0)
    );

endmodule

rtl:
module priority_encoder_4to2 (
    input [3:0] I,
    output reg [1:0] Y
);

always @* begin
    case (I)
        4'b0001: Y = 2'b00;
        4'b0010: Y = 2'b01;
        4'b0100: Y = 2'b10;
        4'b1000: Y = 2'b11;
        default: Y = 2'b00;
    endcase
end

endmodule

sva:
module priority_encoder_4to2_sva (
    input logic [3:0] I,
    input logic [1:0] Y
);

    // No RTL clock or reset; sample this combinational mapping on $global_clock.

    // Input 0001 produces output 00.
    check_input_0001_maps_to_00: assert property (
        @($global_clock) (I == 4'b0001) |-> (Y == 2'b00)
    );

    // Input 0010 produces output 01.
    check_input_0010_maps_to_01: assert property (
        @($global_clock) (I == 4'b0010) |-> (Y == 2'b01)
    );

    // Input 0100 produces output 10.
    check_input_0100_maps_to_10: assert property (
        @($global_clock) (I == 4'b0100) |-> (Y == 2'b10)
    );

    // Input 1000 produces output 11.
    check_input_1000_maps_to_11: assert property (
        @($global_clock) (I == 4'b1000) |-> (Y == 2'b11)
    );

    // All other input patterns produce the default output 00.
    check_other_inputs_default_to_00: assert property (
        @($global_clock)
        ((I != 4'b0001) && (I != 4'b0010) && (I != 4'b0100) && (I != 4'b1000))
        |-> (Y == 2'b00)
    );

    // Output 01 can only come from input 0010.
    check_output_01_only_from_0010: assert property (
        @($global_clock) (Y == 2'b01) |-> (I == 4'b0010)
    );

    // Output 10 can only come from input 0100.
    check_output_10_only_from_0100: assert property (
        @($global_clock) (Y == 2'b10) |-> (I == 4'b0100)
    );

    // Output 11 can only come from input 1000.
    check_output_11_only_from_1000: assert property (
        @($global_clock) (Y == 2'b11) |-> (I == 4'b1000)
    );

    // Output 00 never occurs for inputs that map to nonzero codes.
    check_output_00_excludes_nonzero_mappings: assert property (
        @($global_clock) (Y == 2'b00) |-> ((I != 4'b0010) && (I != 4'b0100) && (I != 4'b1000))
    );

endmodule

rtl:
module four_bit_adder(
    input [3:0] A,
    input [3:0] B,
    output [3:0] S,
    output Cout
);

    wire [3:0] carry;
    wire [3:0] sum;

    full_adder FA0(A[0], B[0], 1'b0, sum[0], carry[0]);
    full_adder FA1(A[1], B[1], carry[0], sum[1], carry[1]);
    full_adder FA2(A[2], B[2], carry[1], sum[2], carry[2]);
    full_adder FA3(A[3], B[3], carry[2], sum[3], Cout);

    assign S = sum;

endmodule

module full_adder(
    input A,
    input B,
    input Cin,
    output S,
    output Cout
);

    wire sum;
    wire carry;

    assign sum = A ^ B;
    assign carry = A & B;

    assign S = sum ^ Cin;
    assign Cout = carry | (sum & Cin);

endmodule

sva:
module four_bit_adder_sva (
    input logic       clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] S,
    input logic       Cout
);

    // The 5-bit output must equal the arithmetic sum of A and B.
    check_full_sum_match: assert property (
        @(posedge clk) {Cout, S} == ({1'b0, A} + {1'b0, B})
    );

    // The least-significant sum bit has no carry-in and is just A[0] xor B[0].
    check_lsb_has_no_carry_in: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0])
    );

    // Adding zero on B must pass A through with no carry-out.
    check_b_zero_passthrough: assert property (
        @(posedge clk) (B == 4'b0000) |-> ({Cout, S} == {1'b0, A})
    );

    // Adding zero on A must pass B through with no carry-out.
    check_a_zero_passthrough: assert property (
        @(posedge clk) (A == 4'b0000) |-> ({Cout, S} == {1'b0, B})
    );

    // If both operands are less than 8, the 4-bit adder cannot overflow.
    check_no_carry_when_msb_clear: assert property (
        @(posedge clk) (!A[3] && !B[3]) |-> (Cout == 1'b0)
    );

    // The maximum input pair must produce 30 decimal as 1_1110.
    check_max_operands_result: assert property (
        @(posedge clk) ((A == 4'hF) && (B == 4'hF)) |-> ({Cout, S} == 5'h1E)
    );

    // Adding 1 to 15 must roll over the sum and assert carry-out.
    check_rollover_on_ff_plus_one: assert property (
        @(posedge clk) (((A == 4'hF) && (B == 4'h1)) || ((A == 4'h1) && (B == 4'hF))) |-> ({Cout, S} == 5'h10)
    );

endmodule

rtl:
module adder_4bit (
    input [3:0] A,
    input [3:0] B,
    input CIN,
    output [3:0] S,
    output COUT
);

    wire [3:0] sum;
    wire carry_out;

    assign {carry_out, sum} = A + B + CIN;

    assign S = sum;
    assign COUT = carry_out;

endmodule

sva:
module adder_4bit_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic CIN,
    input logic [3:0] S,
    input logic COUT
);

    // Outputs match the RTL addition assignment.
    check_outputs_match_assigned_addition: assert property (
        @(posedge clk) {COUT, S} == (A + B + CIN)
    );

    // Sum matches the low 4 bits of the arithmetic result.
    check_sum_matches_low_4bits_of_extended_add: assert property (
        @(posedge clk) S == ({1'b0, A} + {1'b0, B} + CIN)[3:0]
    );

    // Zero inputs produce zero outputs.
    check_zero_inputs_produce_zero_outputs: assert property (
        @(posedge clk) (A == 4'h0 && B == 4'h0 && CIN == 1'b0) |-> (S == 4'h0 && COUT == 1'b0)
    );

    // With B and CIN low, the output passes A through.
    check_a_passthrough_when_b_and_cin_are_zero: assert property (
        @(posedge clk) (B == 4'h0 && CIN == 1'b0) |-> (S == A && COUT == 1'b0)
    );

    // With A and CIN low, the output passes B through.
    check_b_passthrough_when_a_and_cin_are_zero: assert property (
        @(posedge clk) (A == 4'h0 && CIN == 1'b0) |-> (S == B && COUT == 1'b0)
    );

    // With both operands low, CIN drives the least-significant sum bit.
    check_cin_only_when_a_and_b_are_zero: assert property (
        @(posedge clk) (A == 4'h0 && B == 4'h0) |-> (S == {3'b000, CIN} && COUT == 1'b0)
    );

    // No carry is produced when the full arithmetic result fits in 4 bits.
    check_no_carry_when_extended_sum_fits_in_4_bits: assert property (
        @(posedge clk) (({1'b0, A} + {1'b0, B} + CIN) < 5'd16) |-> (COUT == 1'b0)
    );

endmodule

rtl:
module MUX4 (
    A,
    B,
    C,
    D,
    S0,
    S1,
    Y
);
  input A, B, C, D, S0, S1;
  output Y;

  wire MUX0_out, MUX1_out;

  // Instantiating 2-to-1 multiplexers
  MUX2x1 MUX0 (
      .A (A),
      .B (B),
      .S (S0),
      .Q (MUX0_out)
  );

  MUX2x1 MUX1 (
      .A (C),
      .B (D),
      .S (S0),
      .Q (MUX1_out)
  );

  // Final 2-to-1 multiplexer
  MUX2x1 MUX2 (
      .A (MUX0_out),
      .B (MUX1_out),
      .S (S1),
      .Q (Y)
  );

endmodule

// 2-to-1 multiplexer building block
module MUX2x1 (
    A,
    B,
    S,
    Q
);
  input A, B, S;
  output Q;

  assign Q = (S == 1'b0) ? A : B;

endmodule

sva:
module MUX4_assertions (
    input logic clk,
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic S0,
    input logic S1,
    input logic Y
);

    // Y matches the nested mux equation implemented by the RTL.
    check_full_mux_equation: assert property (
        @(posedge clk)
        Y === ((S1 == 1'b0) ? ((S0 == 1'b0) ? A : B)
                            : ((S0 == 1'b0) ? C : D))
    );

    // When S1 is low, Y must come from the A/B mux selected by S0.
    check_lower_pair_when_s1_low: assert property (
        @(posedge clk)
        (S1 === 1'b0) |-> (Y === ((S0 == 1'b0) ? A : B))
    );

    // When S1 is high, Y must come from the C/D mux selected by S0.
    check_upper_pair_when_s1_high: assert property (
        @(posedge clk)
        (S1 === 1'b1) |-> (Y === ((S0 == 1'b0) ? C : D))
    );

    // Selecting S1=0 and S0=0 routes A to Y.
    check_select_a_path: assert property (
        @(posedge clk)
        ((S1 === 1'b0) && (S0 === 1'b0)) |-> (Y === A)
    );

    // Selecting S1=0 and S0=1 routes B to Y.
    check_select_b_path: assert property (
        @(posedge clk)
        ((S1 === 1'b0) && (S0 === 1'b1)) |-> (Y === B)
    );

    // Selecting S1=1 and S0=0 routes C to Y.
    check_select_c_path: assert property (
        @(posedge clk)
        ((S1 === 1'b1) && (S0 === 1'b0)) |-> (Y === C)
    );

    // Selecting S1=1 and S0=1 routes D to Y.
    check_select_d_path: assert property (
        @(posedge clk)
        ((S1 === 1'b1) && (S0 === 1'b1)) |-> (Y === D)
    );

endmodule

rtl:
module mux_4to1(
    input [7:0] in1,
    input [7:0] in2,
    input [7:0] in3,
    input [7:0] in4,
    input sel0,
    input sel1,
    output reg [7:0] out
);

always @ (sel0 or sel1 or in1 or in2 or in3 or in4)
begin
    if (sel0 == 0 && sel1 == 0)
        out = in1;
    else if (sel0 == 1 && sel1 == 0)
        out = in2;
    else if (sel0 == 0 && sel1 == 1)
        out = in3;
    else if (sel0 == 1 && sel1 == 1)
        out = in4;
end

