module and_gate (
    input  A1,
    input  A2,
    input  A3,
    input  A4,
    output Y
);

    // Logic to check if all inputs are high
    assign Y = A1 & A2 & A3 & A4;

endmodule

sva:
module and_gate_sva (
    input logic clk,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic A4,
    input logic Y
);

    // Y must equal the AND of all four inputs.
    check_y_matches_four_input_and: assert property (
        @(posedge clk) Y == (A1 & A2 & A3 & A4)
    );

