    .in1(in1),
    .clk(clk),
    .out(out),
    .reg_in0(reg_in0),
    .reg_in1(reg_in1),
    .reg_out(reg_out)
);

rtl:
module four_to_one (
    input [3:0] in,
    output out
);

    assign out = |in;

endmodule

sva:
module four_to_one_sva (
    input logic clk,
    input logic [3:0] in,
    input logic out
);

    // Output must equal the reduction-OR of the input bus.
    check_out_matches_reduction_or: assert property (
        @(posedge clk) out == (|in)
    );

    // A zero input vector must drive the output low.
    check_zero_input_drives_low: assert property (
        @(posedge clk) (in == 4'b0000) |-> (out == 1'b0)
    );

    // Any non-zero input vector must drive the output high.
    check_nonzero_input_drives_high: assert property (
        @(posedge clk) (in != 4'b0000) |-> (out == 1'b1)
    );

endmodule

module three_input_gate_sva (
    input logic A1,
    input logic A2,
    input logic B1,
    input logic X
);

    // No clock or reset is present in the RTL.
    // The logic is purely combinational: X is high only when A1, A2, and B1 are all high.

    // On an input edge, any low input requires X low.
    check_any_low_drives_x_low: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge B1 or negedge B1)
        (!A1 || !A2 || !B1) |-> !X
    );

    // On an input edge, all high inputs require X high.
    check_all_high_drives_x_high: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge B1 or negedge B1)
        (A1 && A2 && B1) |-> X
    );

    // X can rise only when all three inputs are high.
    check_x_rises_only_for_all_high: assert property (
        @(posedge X)
        (A1 && A2 && B1)
    );

    // X can fall only when at least one input is low.
    check_x_falls_only_when_input_low: assert property (
        @(negedge X)
        (!A1 || !A2 || !B1)
    );

endmodule

rtl:
module nand4b (
    Y,
    A,
    B,
    C,
    D
);

    // Module ports
    output Y;
    input A;
    input B;
    input C;
    input D;

    // Local signals
    wire not0_out;
    wire not1_out;
    wire and0_out;
    wire and1_out;
    wire or0_out;

    //   Name   Output       Other arguments
    not  not0  (not0_out   , A             );
    not  not1  (not1_out   , B             );
    and  and0  (and0_out   , A, B          );
    and  and1  (and1_out   , C, D          );
    or   or0   (or0_out    , and0_out, and1_out);
    not  not2  (Y          , or0_out       );

endmodule

sva:
module nand4b_sva (
    input logic clk,
    input logic Y,
    input logic A,
    input logic B,
    input logic C,
    input logic D
);

    // Y must implement ~( (A & B) | (C & D) ).
    check_output_equation: assert property (
        @(posedge clk) Y == ~((A & B) | (C & D))
    );

    // If A and B are both HIGH, Y must be LOW.
    check_ab_pair_forces_low: assert property (
        @(posedge clk) ((A & B) == 1'b1) |-> (Y == 1'b0)
    );

    // If C and D are both HIGH, Y must be LOW.
    check_cd_pair_forces_low: assert property (
        @(posedge clk) ((C & D) == 1'b1) |-> (Y == 1'b0)
    );

    // If neither pair is HIGH together, Y must be HIGH.
    check_no_pair_high_drives_high: assert property (
        @(posedge clk) (((A & B) == 1'b0) && ((C & D) == 1'b0)) |-> (Y == 1'b1)
    );

    // A LOW Y requires at least one HIGH input pair.
    check_low_output_has_active_pair: assert property (
        @(posedge clk) (Y == 1'b0) |-> (((A & B) == 1'b1) || ((C & D) == 1'b1))
    );

endmodule

module karnaugh_map_sva(
    input logic clk,
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic E,
    input logic F
);

    function automatic logic expected_f(
        input logic a,
        input logic b,
        input logic c,
        input logic d,
        input logic e
    );
        begin
            case ({a,b,c,d,e})
                5'b00000: expected_f = 1'b0;
                5'b00001: expected_f = 1'b1;
                5'b00011: expected_f = 1'b0;
                5'b00010: expected_f = 1'b0;
                5'b00110: expected_f = 1'b1;
                5'b00111: expected_f = 1'b0;
                5'b00101: expected_f = 1'b1;
                5'b00100: expected_f = 1'b1;
                5'b01100: expected_f = 1'b1;
                5'b01101: expected_f = 1'b1;
                5'b01111: expected_f = 1'b0;
                5'b01110: expected_f = 1'b1;
                5'b01010: expected_f = 1'b0;
                5'b01011: expected_f = 1'b1;
                5'b01001: expected_f = 1'b0;
                5'b01000: expected_f = 1'b1;
                5'b11000: expected_f = 1'b1;
                5'b11001: expected_f = 1'b0;
                5'b11011: expected_f = 1'b0;
                5'b11010: expected_f = 1'b1;
                5'b11110: expected_f = 1'b0;
                5'b11111: expected_f = 1'b1;
                5'b11101: expected_f = 1'b0;
                5'b11100: expected_f = 1'b1;
                5'b10100: expected_f = 1'b0;
                5'b10101: expected_f = 1'b1;
                5'b10111: expected_f = 1'b0;
                5'b10110: expected_f = 1'b1;
                5'b10010: expected_f = 1'b0;
                5'b10011: expected_f = 1'b1;
                5'b10001: expected_f = 1'b0;
                5'b10000: expected_f = 1'b1;
                default:  expected_f = 1'b0;
            endcase
        end
    endfunction

    // F must match the implemented case table for every sampled input combination.
    check_truth_table_match: assert property (
        @(posedge clk) F == expected_f(A, B, C, D, E)
    );

    // Unknown inputs must select the default branch and drive F low.
    check_default_on_unknown_inputs: assert property (
        @(posedge clk) $isunknown({A, B, C, D, E}) |-> (F == 1'b0)
    );

    // F is always driven to a known value by the case statement and default.
    check_output_known: assert property (
        @(posedge clk) !$isunknown(F)
    );

endmodule

rtl:
module four_bit_adder(
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] Z,
    output Cout
);

    wire [3:0] sum;
    wire [3:0] c;

    assign sum[0] = A[0] ^ B[0] ^ Cin;
    assign c[0] = (A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin);

    assign sum[1] = A[1] ^ B[1] ^ c[0];
    assign c[1] = (A[1] & B[1]) | (A[1] & c[0]) | (B[1] & c[0]);

    assign sum[2] = A[2] ^ B[2] ^ c[1];
    assign c[2] = (A[2] & B[2]) | (A[2] & c[1]) | (B[2] & c[1]);

    assign sum[3] = A[3] ^ B[3] ^ c[2];
    assign c[3] = (A[3] & B[3]) | (A[3] & c[2]) | (B[3] & c[2]);

    assign Cout = c[3];
    assign Z = sum;

endmodule

sva:
module four_bit_adder_sva(
    input logic [3:0] A,
    input logic [3:0] B,
    input logic       Cin,
    input logic [3:0] Z,
    input logic       Cout
);

    // Full output matches the 4-bit addition with carry-in.
    check_full_addition: assert property (
        @($global_clock)
        {Cout, Z} == ({1'b0, A} + {1'b0, B} + {{4{1'b0}}, Cin})
    );

    // Bit 0 sum matches XOR of the inputs and carry-in.
    check_sum_bit0: assert property (
        @($global_clock)
        Z[0] == (A[0] ^ B[0] ^ Cin)
    );

    // Bit 1 sum uses the carry generated by bit 0.
    check_sum_bit1: assert property (
        @($global_clock)
        Z[1] == (
            A[1] ^ B[1] ^
            ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin))
        )
    );

    // Bit 2 sum uses the carry generated by bit 1.
    check_sum_bit2: assert property (
        @($global_clock)
        Z[2] == (
            A[2] ^ B[2] ^
            (
                (A[1] & B[1]) |
                (A[1] & ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin))) |
                (B[1] & ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin)))
            )
        )
    );

    // Bit 3 sum uses the carry generated by bit 2.
    check_sum_bit3: assert property (
        @($global_clock)
        Z[3] == (
            A[3] ^ B[3] ^
            (
                (A[2] & B[2]) |
                (A[2] & (
                    (A[1] & B[1]) |
                    (A[1] & ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin))) |
                    (B[1] & ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin)))
                )) |
                (B[2] & (
                    (A[1] & B[1]) |
                    (A[1] & ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin))) |
                    (B[1] & ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin)))
                ))
            )
        )
    );

    // Carry-out matches the carry generated by bit 3.
    check_cout_formula: assert property (
        @($global_clock)
        Cout == (
            (A[3] & B[3]) |
            (A[3] & (
                (A[2] & B[2]) |
                (A[2] & (
                    (A[1] & B[1]) |
                    (A[1] & ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin))) |
                    (B[1] & ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin)))
                )) |
                (B[2] & (
                    (A[1] & B[1]) |
                    (A[1] & ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin))) |
                    (B[1] & ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin)))
                ))
            )) |
            (B[3] & (
                (A[2] & B[2]) |
                (A[2] & (
                    (A[1] & B[1]) |
                    (A[1] & ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin))) |
                    (B[1] & ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin)))
                )) |
                (B[2] & (
                    (A[1] & B[1]) |
                    (A[1] & ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin))) |
                    (B[1] & ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin)))
                ))
            ))
        )
    );

endmodule

rtl:
module chatgpt_generate_edge_detect(
  input               clk,
  input               rst_n,
  input               a,
  output reg          rise,
  output reg          down
);

  parameter DELAY = 1;

  reg a_dly;
  reg a_dly_dly;
  reg a_dly_dly_dly;

  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      a_dly <= 1'b0;
      a_dly_dly <= 1'b0;
      a_dly_dly_dly <= 1'b0;
    end else begin
      a_dly <= a;
      a_dly_dly <= a_dly;
      a_dly_dly_dly <= a_dly_dly;
    end
  end

  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      rise <= 1'b0;
      down <= 1'b0;
    end else begin
      if ((a_dly_dly_dly == 1'b0) & (a_dly_dly == 1'b1) & (a_dly == 1'b1)) begin
        rise <= 1'b1;
        down <= 1'b0;
      end else if ((a_dly_dly_dly == 1'b1) & (a_dly_dly == 1'b1) & (a_dly == 1'b0)) begin
        rise <= 1'b0;
        down <= 1'b1;
      end else begin
        rise <= 1'b0;
        down <= 1'b0;
      end
    end
  end

endmodule

sva:
module chatgpt_generate_edge_detect_sva (
    input logic clk,
    input logic rst_n,
    input logic a,
    input logic rise,
    input logic down,
    input logic a_dly,
    input logic a_dly_dly,
    input logic a_dly_dly_dly
);

    // Reset forces the delay pipeline low.
    check_reset_pipeline_low: assert property (
        @(posedge clk) disable iff ($initstate)
        !rst_n |-> (a_dly == 1'b0) && (a_dly_dly == 1'b0) && (a_dly_dly_dly == 1'b0)
    );

    // Reset forces both outputs low.
    check_reset_outputs_low: assert property (
        @(posedge clk) disable iff ($initstate)
        !rst_n |-> (rise == 1'b0) && (down == 1'b0)
    );

    // State and outputs remain low immediately after a reset cycle.
    check_post_reset_state_low: assert property (
        @(posedge clk) disable iff (!rst_n || $initstate)
        !$past(rst_n) |-> (a_dly == 1'b0) && (a_dly_dly == 1'b0) && (a_dly_dly_dly == 1'b0) &&
                          (rise == 1'b0) && (down == 1'b0)
    );

    // First delay stage captures input a.
    check_a_dly_captures_a: assert property (
        @(posedge clk) disable iff (!rst_n || $initstate)
        $past(rst_n) |-> (a_dly == $past(a))
    );

    // Second delay stage captures the first delay stage.
    check_a_dly_dly_captures_a_dly: assert property (
        @(posedge clk) disable iff (!rst_n || $initstate)
        $past(rst_n) |-> (a_dly_dly == $past(a_dly))
    );

    // Third delay stage captures the second delay stage.
    check_a_dly_dly_dly_captures_a_dly_dly: assert property (
        @(posedge clk) disable iff (!rst_n || $initstate)
        $past(rst_n) |-> (a_dly_dly_dly == $past(a_dly_dly))
    );

    // Rise output matches the registered 0,1,1 detect pattern.
    check_rise_decode: assert property (
        @(posedge clk) disable iff (!rst_n || $initstate)
        $past(rst_n) |-> (rise == (($past(a_dly_dly_dly) == 1'b0) &&
                                   ($past(a_dly_dly) == 1'b1) &&
                                   ($past(a_dly) == 1'b1)))
    );

    // Down output matches the registered 1,1,0 detect pattern.
    check_down_decode: assert property (
        @(posedge clk) disable iff (!rst_n || $initstate)
        $past(rst_n) |-> (down == (($past(a_dly_dly_dly) == 1'b1) &&
                                   ($past(a_dly_dly) == 1'b1) &&
                                   ($past(a_dly) == 1'b0)))
    );

    // Rise and down are never asserted together.
    check_outputs_mutex: assert property (
        @(posedge clk) disable iff (!rst_n || $initstate)
        !((rise == 1'b1) && (down == 1'b1))
    );

    // Rise is a single-cycle pulse.
    check_rise_single_cycle: assert property (
        @(posedge clk) disable iff (!rst_n || $initstate)
        (rise == 1'b1) |=> (rise == 1'b0)
    );

    // Down is a single-cycle pulse.
    check_down_single_cycle: assert property (
        @(posedge clk) disable iff (!rst_n || $initstate)
        (down == 1'b1) |=> (down == 1'b0)
    );

endmodule

module mux_4to1_sva (
    input logic [7:0] A,
    input logic [7:0] B,
    input logic [7:0] C,
    input logic [7:0] D,
    input logic [1:0] S,
    input logic [7:0] Y
);

    // Y selects A when S is 00.
    check_select_a: assert property (
        @($global_clock) (S == 2'b00) |-> (Y == A)
    );

    // Y selects B when S is 01.
    check_select_b: assert property (
        @($global_clock) (S == 2'b01) |-> (Y == B)
    );

    // Y selects C when S is 10.
    check_select_c: assert property (
        @($global_clock) (S == 2'b10) |-> (Y == C)
    );

    // Y selects D when S is 11.
    check_select_d: assert property (
        @($global_clock) (S == 2'b11) |-> (Y == D)
    );

    // Y always matches the RTL mux equation.
    check_mux_function: assert property (
        @($global_clock)
        Y == ((S == 2'b00) ? A :
              (S == 2'b01) ? B :
              (S == 2'b10) ? C :
              D)
    );

endmodule

rtl:
module Round_Sgf_Dec(

    input wire [1:0] Data_i,
    input wire [1:0] Round_Type_i,
    input wire Sign_Result_i,
    output reg Round_Flag_o
    );

    always @*
    	case ({Sign_Result_i,Round_Type_i,Data_i})






    	5'b10101: Round_Flag_o <=1;  
    	5'b10110: Round_Flag_o <=1;  
    	5'b10111: Round_Flag_o <=1;  

    	5'b01001: Round_Flag_o <=1;  
    	5'b01010: Round_Flag_o <=1;  
    	5'b01011: Round_Flag_o <=1;  




    	default: Round_Flag_o <=0;

    	endcase

endmodule

sva:
module Round_Sgf_Dec_sva(
    input logic [1:0] Data_i,
    input logic [1:0] Round_Type_i,
    input logic Sign_Result_i,
    input logic Round_Flag_o
);

    // Round_Flag_o matches the full decode truth table.
    check_round_flag_truth_table: assert property (
        @($global_clock)
        Round_Flag_o == (
            (((Sign_Result_i == 1'b1) && (Round_Type_i == 2'b01)) ||
             ((Sign_Result_i == 1'b0) && (Round_Type_i == 2'b10))) &&
            (Data_i != 2'b00)
        )
    );

    // Zero data never asserts the round flag.
    check_zero_data_clears_flag: assert property (
        @($global_clock)
        (Data_i == 2'b00) |-> (Round_Flag_o == 1'b0)
    );

    // Sign_Result_i=1 with Round_Type_i=01 and nonzero data asserts the flag.
    check_sign1_round01_nonzero_sets_flag: assert property (
        @($global_clock)
        ((Sign_Result_i == 1'b1) && (Round_Type_i == 2'b01) && (Data_i != 2'b00)) |-> (Round_Flag_o == 1'b1)
    );

    // Sign_Result_i=0 with Round_Type_i=10 and nonzero data asserts the flag.
    check_sign0_round10_nonzero_sets_flag: assert property (
        @($global_clock)
        ((Sign_Result_i == 1'b0) && (Round_Type_i == 2'b10) && (Data_i != 2'b00)) |-> (Round_Flag_o == 1'b1)
    );

    // A high round flag requires nonzero data.
    check_flag_requires_nonzero_data: assert property (
        @($global_clock)
        (Round_Flag_o == 1'b1) |-> (Data_i != 2'b00)
    );

    // When Sign_Result_i is 1, a high flag only occurs in round type 01.
    check_sign1_flag_only_in_round01: assert property (
        @($global_clock)
        ((Round_Flag_o == 1'b1) && (Sign_Result_i == 1'b1)) |-> (Round_Type_i == 2'b01)
    );

    // When Sign_Result_i is 0, a high flag only occurs in round type 10.
    check_sign0_flag_only_in_round10: assert property (
        @($global_clock)
        ((Round_Flag_o == 1'b1) && (Sign_Result_i == 1'b0)) |-> (Round_Type_i == 2'b10)
    );

    // Round types 00 and 11 never assert the round flag.
    check_unused_round_types_clear_flag: assert property (
        @($global_clock)
        ((Round_Type_i == 2'b00) || (Round_Type_i == 2'b11)) |-> (Round_Flag_o == 1'b0)
    );

    // Sign_Result_i=1 with round type 10 never asserts the flag.
    check_sign1_round10_clears_flag: assert property (
        @($global_clock)
        ((Sign_Result_i == 1'b1) && (Round_Type_i == 2'b10)) |-> (Round_Flag_o == 1'b0)
    );

    // Sign_Result_i=0 with round type 01 never asserts the flag.
    check_sign0_round01_clears_flag: assert property (
        @($global_clock)
        ((Sign_Result_i == 1'b0) && (Round_Type_i == 2'b01)) |-> (Round_Flag_o == 1'b0)
    );

endmodule

rtl:
module SaturationEnhancement (
  input signed [15:0] in1,
  input signed [15:0] in2,
  input signed [15:0] T,
  output signed [15:0] out1,
  output signed [15:0] out2
);

  wire signed [15:0] abs_in1 = (in1 < 0) ? -in1 : in1;
  wire signed [15:0] abs_in2 = (in2 < 0) ? -in2 : in2;

  assign out1 = (abs_in1 <= T) ? in1 : $signed((in1 < 0) ? -T : T);
  assign out2 = (abs_in2 <= T) ? in2 : $signed((in2 < 0) ? -T : T);

endmodule

sva:
module SaturationEnhancement_sva (
    input logic clk,
    input logic signed [15:0] in1,
    input logic signed [15:0] in2,
    input logic signed [15:0] T,
    input logic signed [15:0] out1,
    input logic signed [15:0] out2
);

    // out1 must match the RTL expression driven from in1 and T.
    check_out1_matches_rtl: assert property (
        @(posedge clk)
        out1 == (($signed(((in1 < 0) ? -in1 : in1)) <= T) ? in1 : $signed(((in1 < 0) ? -T : T)))
    );

    // out2 must match the RTL expression driven from in2 and T.
    check_out2_matches_rtl: assert property (
        @(posedge clk)
        out2 == (($signed(((in2 < 0) ? -in2 : in2)) <= T) ? in2 : $signed(((in2 < 0) ? -T : T)))
    );

    // If in1 is within the signed threshold comparison, out1 passes through.
    check_out1_passthrough: assert property (
        @(posedge clk)
        ($signed(((in1 < 0) ? -in1 : in1)) <= T) |-> (out1 == in1)
    );

    // If in2 is within the signed threshold comparison, out2 passes through.
    check_out2_passthrough: assert property (
        @(posedge clk)
        ($signed(((in2 < 0) ? -in2 : in2)) <= T) |-> (out2 == in2)
    );

    // If in1 exceeds the signed threshold comparison, out1 selects T or -T.
    check_out1_clamps_to_threshold_value: assert property (
        @(posedge clk)
        ($signed(((in1 < 0) ? -in1 : in1)) > T) |-> (out1 == $signed(((in1 < 0) ? -T : T)))
    );

    // If in2 exceeds the signed threshold comparison, out2 selects T or -T.
    check_out2_clamps_to_threshold_value: assert property (
        @(posedge clk)
        ($signed(((in2 < 0) ? -in2 : in2)) > T) |-> (out2 == $signed(((in2 < 0) ? -T : T)))
    );

    // Equal channel inputs must produce equal channel outputs.
    check_equal_inputs_produce_equal_outputs: assert property (
        @(posedge clk)
        (in1 == in2) |-> (out1 == out2)
    );

endmodule

rtl:
module my_flipflop (
    input in,
    input clock,
    input enable_l,
    input reset,
    input clear,
    output reg out
);

    reg q1, q2, q3, q4;

    always @(posedge clock) begin
        if (enable_l == 0) begin
            q1 <= in;
            q2 <= q1;
            q3 <= q2;
            q4 <= q3;
        end
    end

    always @(*) begin
        if (reset == 1) begin
            out <= 0;
        end else if (clear == 1) begin
            out <= 1;
        end else if (q4 == 1 && q3 == 0 && q2 == 1 && q1 == 0) begin
            out <= 0;
        end else if (q4 == 0 && q3 == 1 && q2 == 0 && q1 == 1) begin
            out <= 1;
        end else begin
            out <= q4;
        end
    end

endmodule

sva:
module my_flipflop_sva (
    input logic in,
    input logic clock,
    input logic enable_l,
    input logic reset,
    input logic clear,
    input logic out,
    input logic q1,
    input logic q2,
    input logic q3,
    input logic q4
);

    // q1 loads input on an enabled clock.
    check_shift_q1: assert property (
        @(posedge clock) disable iff (reset)
        (enable_l == 1'b0) |=> (q1 == $past(in))
    );

    // q2 loads the previous q1 on an enabled clock.
    check_shift_q2: assert property (
        @(posedge clock) disable iff (reset)
        (enable_l == 1'b0) |=> (q2 == $past(q1))
    );

    // q3 loads the previous q2 on an enabled clock.
    check_shift_q3: assert property (
        @(posedge clock) disable iff (reset)
        (enable_l == 1'b0) |=> (q3 == $past(q2))
    );

    // q4 loads the previous q3 on an enabled clock.
    check_shift_q4: assert property (
        @(posedge clock) disable iff (reset)
        (enable_l == 1'b0) |=> (q4 == $past(q3))
    );

    // The shift registers hold when the active-low enable is deasserted.
    check_hold_when_disabled: assert property (
        @(posedge clock) disable iff (reset)
        (enable_l == 1'b1) |=> (
            q1 == $past(q1) &&
            q2 == $past(q2) &&
            q3 == $past(q3) &&
            q4 == $past(q4)
        )
    );

    // Reset forces out low.
    check_reset_forces_out_low: assert property (
        @(posedge clock)
        (reset == 1'b1) |-> (out == 1'b0)
    );

    // Clear forces out high when reset is not asserted.
    check_clear_forces_out_high: assert property (
        @(posedge clock) disable iff (reset)
        (clear == 1'b1) |-> (out == 1'b1)
    );

    // The 1010 q-pattern forces out low.
    check_pattern_1010_forces_out_low: assert property (
        @(posedge clock) disable iff (reset)
        (clear == 1'b0 &&
         q4 == 1'b1 &&
         q3 == 1'b0 &&
         q2 == 1'b1 &&
         q1 == 1'b0) |-> (out == 1'b0)
    );

    // The 0101 q-pattern forces out high.
    check_pattern_0101_forces_out_high: assert property (
        @(posedge clock) disable iff (reset)
        (clear == 1'b0 &&
         q4 == 1'b0 &&
         q3 == 1'b1 &&
         q2 == 1'b0 &&
         q1 == 1'b1) |-> (out == 1'b1)
    );

    // Outside reset, clear, and special patterns, out follows q4.
    check_default_out_follows_q4: assert property (
        @(posedge clock) disable iff (reset)
        (clear == 1'b0 &&
         !(q4 == 1'b1 && q3 == 1'b0 && q2 == 1'b1 && q1 == 1'b0) &&
         !(q4 == 1'b0 && q3 == 1'b1 && q2 == 1'b0 && q1 == 1'b1)) |-> (out == q4)
    );

endmodule

module up_down_counter_assertions (
    input logic clk,
    input logic [2:0] D,
    input logic L,
    input logic U,
    input logic [2:0] out
);

    // When L was high, out must load the previous D value.
    check_load_behavior: assert property (
        @(posedge clk) disable iff ($initstate)
        $past(L) |-> (out == $past(D))
    );

    // When L was low and U was high, out must increment.
    check_count_up_behavior: assert property (
        @(posedge clk) disable iff ($initstate)
        (!$past(L) && $past(U)) |-> (out == ($past(out) + 3'd1))
    );

    // When both L and U were low, out must decrement.
    check_count_down_behavior: assert property (
        @(posedge clk) disable iff ($initstate)
        (!$past(L) && !$past(U)) |-> (out == ($past(out) - 3'd1))
    );

    // out must always match the RTL next-state function.
    check_next_state_function: assert property (
        @(posedge clk) disable iff ($initstate)
        out == ($past(L) ? $past(D) : ($past(U) ? ($past(out) + 3'd1) : ($past(out) - 3'd1)))
    );

endmodule

rtl:
module my_mux2 (
    X   ,
    A0  ,
    A1  ,
    S   
);

    output X   ;
    input  A0  ;
    input  A1  ;
    input  S   ;

    wire notS;
    wire and1;
    wire and2;

    not #(1) inv1(notS, S);
    and #(1) gate1(and1, A0, notS);
    and #(1) gate2(and2, A1, S);
    or #(1) gate3(X, and1, and2);

endmodule

sva:
module my_mux2_assertions (
    input logic clk,
    input logic X,
    input logic A0,
    input logic A1,
    input logic S
);

    // X matches the implemented mux equation.
    check_mux_equation: assert property (
        @(posedge clk) X == ((A0 & ~S) | (A1 & S))
    );

    // When S is low, X selects A0.
    check_select_a0_when_s_low: assert property (
        @(posedge clk) (S == 1'b0) |-> (X == A0)
    );

    // When S is high, X selects A1.
    check_select_a1_when_s_high: assert property (
        @(posedge clk) (S == 1'b1) |-> (X == A1)
    );

    // If both data inputs are low, X is low.
    check_output_low_when_both_inputs_low: assert property (
        @(posedge clk) ((A0 == 1'b0) && (A1 == 1'b0)) |-> (X == 1'b0)
    );

    // If both data inputs are high, X is high.
    check_output_high_when_both_inputs_high: assert property (
        @(posedge clk) ((A0 == 1'b1) && (A1 == 1'b1)) |-> (X == 1'b1)
    );

    // If both data inputs match, X equals that common value.
    check_output_matches_common_input: assert property (
        @(posedge clk) (A0 == A1) |-> (X == A0)
    );

    // With A0 low and A1 high, X follows S.
    check_output_follows_s_for_01_inputs: assert property (
        @(posedge clk) ((A0 == 1'b0) && (A1 == 1'b1)) |-> (X == S)
    );

    // With A0 high and A1 low, X follows inverted S.
    check_output_follows_not_s_for_10_inputs: assert property (
        @(posedge clk) ((A0 == 1'b1) && (A1 == 1'b0)) |-> (X == ~S)
    );

endmodule

rtl:
module my_module (
    Y ,
    A1,
    A2,
    A3,
    B1
);

    // Module ports
    output Y ;
    input  A1;
    input  A2;
    input  A3;
    input  B1;

    // Module supplies
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    // Local signals
    wire or0_out    ;
    wire nand0_out_Y;

    //   Name   Output       Other arguments
    or   or0   (or0_out    , A2, A1, A3     );
    nand nand0 (nand0_out_Y, B1, or0_out    );
    buf  buf0  (Y          , nand0_out_Y    );

endmodule

sva:
module my_module_sva (
    input logic Y,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic B1
);

    default clocking cb @(posedge A1 or negedge A1 or
                          posedge A2 or negedge A2 or
                          posedge A3 or negedge A3 or
                          posedge B1 or negedge B1 or
                          posedge Y  or negedge Y);
        input #0 Y, A1, A2, A3, B1;
    endclocking

    // Y implements the buffered NAND of B1 and the OR of A1/A2/A3.
    check_y_function: assert property (
        @(cb) Y == ~(B1 & (A1 | A2 | A3))
    );

    // If B1 is low, Y must be high.
    check_b1_low_forces_y_high: assert property (
        @(cb) !B1 |-> Y
    );

    // If all A inputs are low, Y must be high.
    check_all_a_low_forces_y_high: assert property (
        @(cb) !(A1 | A2 | A3) |-> Y
    );

    // If B1 is high and any A input is high, Y must be low.
    check_active_inputs_force_y_low: assert property (
        @(cb) (B1 && (A1 | A2 | A3)) |-> !Y
    );

    // A falling Y can only occur when both NAND inputs are high.
    check_y_fall_has_valid_cause: assert property (
        @(cb) $fell(Y) |-> (B1 && (A1 | A2 | A3))
    );

    // A rising Y can only occur when B1 is low or all A inputs are low.
    check_y_rise_has_valid_cause: assert property (
        @(cb) $rose(Y) |-> (!B1 || !(A1 | A2 | A3))
    );

endmodule

rtl:
module multiplexer_4to1 (
    input [7:0] data_in0,
    input [7:0] data_in1,
    input [7:0] data_in2,
    input [7:0] data_in3,
    input [1:0] select,
    output reg [7:0] data_out
);

always @(*) begin
    case (select)
        2'b00: data_out = data_in0;
        2'b01: data_out = data_in1;
        2'b10: data_out = data_in2;
        2'b11: data_out = data_in3;
    endcase
end

endmodule

