    check_s0_low_path: assert property (
        @(posedge clk) !s0 |-> (y == (s1 ? c : a))
    );

    // When s0 is high, y selects between b and d using s1.
    check_s0_high_path: assert property (
        @(posedge clk) s0 |-> (y == (s1 ? d : b))
    );

