    input logic in0,
    input logic in1,
    input logic in2,
    input logic in3,
    input logic sel0,
    input logic sel1,
    input logic out
);

    // Select value 00 routes in0 to out.
    check_sel_00_routes_in0: assert property (
        @(posedge clk) ({sel1, sel0} === 2'b00) |-> (out === in0)
    );

    // Select value 01 routes in1 to out.
    check_sel_01_routes_in1: assert property (
        @(posedge clk) ({sel1, sel0} === 2'b01) |-> (out === in1)
    );

    // Select value 10 routes in2 to out.
    check_sel_10_routes_in2: assert property (
        @(posedge clk) ({sel1, sel0} === 2'b10) |-> (out === in2)
    );

    // Select value 11 routes in3 to out.
    check_sel_11_routes_in3: assert property (
        @(posedge clk) ({sel1, sel0} === 2'b11) |-> (out === in3)
    );

endmodule

rtl:
`define OVERVOLT_GRACE 4'd10
`define UNDERVOLT_GRACE 16'd50000

module power_management (
  output reg kill_sw,
  output reg [2:0] sel,
  output error,
  input ack,
  input data,
  input start, 
  input clk 
);

  reg [9:0] wait_cnt; 
  reg [3:0] overvolt_grace_cnt;
  reg [15:0] undervolt_grace_cnt;
  reg error_reg;

  always @(posedge clk)
  if (start == 1'd0)
  begin
    kill_sw <= 1'b0;
    sel <= 3'b111;
    wait_cnt = 10'd0;
    error_reg = 1'b0;
    overvolt_grace_cnt = `OVERVOLT_GRACE;
    undervolt_grace_cnt = `UNDERVOLT_GRACE;
  end
  else
  begin
    kill_sw <= 1'b1;
    if (!error_reg)
      wait_cnt <= wait_cnt + 10'd1;
    if (ack)
      error_reg <= 1'b0;
    if (!error_reg && wait_cnt == 10'd0)
    begin
      if (overvolt_grace_cnt != 4'd0)
        overvolt_grace_cnt <= overvolt_grace_cnt - 4'd1;
      if (undervolt_grace_cnt != 16'd0)
        undervolt_grace_cnt <= undervolt_grace_cnt - 16'd1;
      if (sel == 3'd6)
      begin
        sel <= 3'b000;
      end
      else
        sel <= sel + 3'b001;
    end
    if (&wait_cnt && !(&sel)
        && ((data == 1'b0 && sel[0] == 1'b0 && undervolt_grace_cnt == 6'd0)
        || (data == 1'b1 && sel[0] == 1'b1 && overvolt_grace_cnt == 20'd0)))
    begin
      error_reg <= 1'd1;
    end
  end

  assign error = error_reg;

endmodule

sva:
module power_management_sva (
    input logic kill_sw,
    input logic [2:0] sel,
    input logic error,
    input logic ack,
    input logic data,
    input logic start,
    input logic clk,
    input logic [9:0] wait_cnt,
    input logic [3:0] overvolt_grace_cnt,
    input logic [15:0] undervolt_grace_cnt,
    input logic error_reg
);

    // Start low initializes the full state.
    check_start_low_resets_state: assert property (
        @(posedge clk)
        !start |=> (
            kill_sw == 1'b0 &&
            sel == 3'b111 &&
            wait_cnt == 10'd0 &&
            error_reg == 1'b0 &&
            error == 1'b0 &&
            overvolt_grace_cnt == 4'd10 &&
            undervolt_grace_cnt == 16'd50000
        )
    );

    // Start high drives the kill switch on the next cycle.
    check_start_high_sets_kill_sw: assert property (
        @(posedge clk)
        start |=> (kill_sw == 1'b1)
    );

    // Wait counter increments while no error is latched.
    check_wait_cnt_increments_when_clear: assert property (
        @(posedge clk) disable iff (!start)
        !error_reg |=> (wait_cnt == $past(wait_cnt) + 10'd1)
    );

    // Wait counter holds when an error is latched.
    check_wait_cnt_holds_when_error: assert property (
        @(posedge clk) disable iff (!start)
        error_reg |=> (wait_cnt == $past(wait_cnt))
    );

    // Select wraps from 6 back to 0 on a scan step.
    check_sel_wraps_from_six: assert property (
        @(posedge clk) disable iff (!start)
        (!error_reg && (wait_cnt == 10'd0) && (sel == 3'd6)) |=> (sel == 3'd0)
    );

    // Select increments on other scan steps.
    check_sel_advances_on_scan_step: assert property (
        @(posedge clk) disable iff (!start)
        (!error_reg && (wait_cnt == 10'd0) && (sel != 3'd6)) |=> (sel == $past(sel) + 3'd1)
    );

    // Overvoltage grace decrements on a scan step while nonzero.
    check_overvolt_grace_decrements: assert property (
        @(posedge clk) disable iff (!start)
        (!error_reg && (wait_cnt == 10'd0) && (overvolt_grace_cnt != 4'd0))
        |=> (overvolt_grace_cnt == $past(overvolt_grace_cnt) - 4'd1)
    );

    // Undervoltage grace decrements on a scan step while nonzero.
    check_undervolt_grace_decrements: assert property (
        @(posedge clk) disable iff (!start)
        (!error_reg && (wait_cnt == 10'd0) && (undervolt_grace_cnt != 16'd0))
        |=> (undervolt_grace_cnt == $past(undervolt_grace_cnt) - 16'd1)
    );

    // Ack clears error when no new fault condition is present.
    check_ack_clears_error_without_new_fault: assert property (
        @(posedge clk) disable iff (!start)
        (ack &&
         !(&wait_cnt && !(&sel) &&
           (((data == 1'b0) && (sel[0] == 1'b0) && (undervolt_grace_cnt == 16'd0)) ||
            ((data == 1'b1) && (sel[0] == 1'b1) && (overvolt_grace_cnt == 4'd0)))))
        |=> (!error_reg && !error)
    );

    // An eligible undervoltage match sets error.
    check_undervolt_fault_sets_error: assert property (
        @(posedge clk) disable iff (!start)
        (&wait_cnt && !(&sel) &&
         (data == 1'b0) && (sel[0] == 1'b0) && (undervolt_grace_cnt == 16'd0))
        |=> (error_reg == 1'b1 && error == 1'b1)
    );

    // An eligible overvoltage match sets error.
    check_overvolt_fault_sets_error: assert property (
        @(posedge clk) disable iff (!start)
        (&wait_cnt && !(&sel) &&
         (data == 1'b1) && (sel[0] == 1'b1) && (overvolt_grace_cnt == 4'd0))
        |=> (error_reg == 1'b1 && error == 1'b1)
    );

endmodule

rtl:
module logic_gate (
    input  A1  ,
    input  A2  ,
    input  B1  ,
    input  C1  ,
    output Y   ,
    input  VPB ,
    input  VPWR,
    input  VGND,
    input  VNB
);

    // Rule 1: If A1 is high and A2 is low, Y should be equal to B1.
    assign Y = (A1 && !A2) ? B1 :

    // Rule 2: If A1 is low and A2 is high, Y should be equal to C1.
               (!A1 && A2) ? C1 :

    // Rule 3: If both A1 and A2 are high, Y should be equal to B1 and C1 ORed together.
               (A1 && A2) ? (B1 | C1) :

    // Rule 4: If both A1 and A2 are low, Y should be set to 0.
               0;

endmodule

sva:
module logic_gate_assertions (
    input logic A1,
    input logic A2,
    input logic B1,
    input logic C1,
    input logic Y,
    input logic VPB,
    input logic VPWR,
    input logic VGND,
    input logic VNB
);

    // Y matches the full combinational function in the RTL.
    check_y_matches_full_function: assert property (
        @($global_clock)
        Y == ((A1 && !A2) ? B1 :
              ((!A1 && A2) ? C1 :
              ((A1 && A2) ? (B1 | C1) : 1'b0)))
    );

    // When A1 is high and A2 is low, Y follows B1.
    check_y_equals_b1_when_a1_high_a2_low: assert property (
        @($global_clock)
        (A1 && !A2) |-> (Y == B1)
    );

    // When A1 is low and A2 is high, Y follows C1.
    check_y_equals_c1_when_a1_low_a2_high: assert property (
        @($global_clock)
        (!A1 && A2) |-> (Y == C1)
    );

    // When both selects are high, Y is the OR of B1 and C1.
    check_y_equals_b1_or_c1_when_both_selects_high: assert property (
        @($global_clock)
        (A1 && A2) |-> (Y == (B1 | C1))
    );

    // When both selects are low, Y is driven low.
    check_y_low_when_both_selects_low: assert property (
        @($global_clock)
        (!A1 && !A2) |-> (Y == 1'b0)
    );

endmodule

rtl:
module xor_gate(
    input a, b,
    output out
    );

    assign out = a ^ b;

endmodule

module four_output_module(
    input a, b, c,
    output w, x, y, z
    );

    assign w = a;
    assign x = b;
    assign y = c;
    assign z = a & b;

endmodule

module final_module(
    input clk, a, b, c,
    output reg out
    );

    wire xor_out;
    wire w, x, y, z;

    xor_gate xor_inst(
        .a(a),
        .b(b),
        .out(xor_out)
    );

    four_output_module four_out_inst(
        .a(a),
        .b(b),
        .c(c),
        .w(w),
        .x(x),
        .y(y),
        .z(z)
    );

    always @(posedge clk)
        out <= xor_out & w & y;

endmodule

module top_module(
    input clk,
    input a, b, c,
    output w, x, y, z,
    output out
);

    wire xor_out;

    final_module final_inst(
        .clk(clk),
        .a(a),
        .b(b),
        .c(c),
        .out(out)
    );

    four_output_module four_out_inst(
        .a(a),
        .b(b),
        .c(c),
        .w(w),
        .x(x),
        .y(y),
        .z(z)
    );

endmodule

sva:
module top_module_assertions(
    input logic clk,
    input logic a,
    input logic b,
    input logic c,
    input logic w,
    input logic x,
    input logic y,
    input logic z,
    input logic out
);

    // w directly mirrors input a.
    check_w_passthrough: assert property (
        @(posedge clk) w == a
    );

    // x directly mirrors input b.
    check_x_passthrough: assert property (
        @(posedge clk) x == b
    );

    // y directly mirrors input c.
    check_y_passthrough: assert property (
        @(posedge clk) y == c
    );

    // z is the AND of a and b.
    check_z_and_function: assert property (
        @(posedge clk) z == (a & b)
    );

    // z is consistent with the mirrored outputs w and x.
    check_z_matches_w_and_x: assert property (
        @(posedge clk) z == (w & x)
    );

    // A true sampled function drives out high on the next cycle.
    check_out_set_on_function_true: assert property (
        @(posedge clk) ((a ^ b) & a & c) |=> out
    );

    // A false sampled function drives out low on the next cycle.
    check_out_clear_on_function_false: assert property (
        @(posedge clk) !((a ^ b) & a & c) |=> !out
    );

endmodule

module counter_sva (
    input logic       clk,
    input logic       rst,
    input logic [3:0] count
);

    // Reset clears the counter on the next clocked state.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |=> (count == 4'b0000)
    );

    // When not in reset, the counter increments by one each cycle.
    check_count_increments: assert property (
        @(posedge clk) disable iff (rst)
        1'b1 |=> (count == ($past(count) + 4'd1))
    );

    // When not in reset, the counter wraps from 15 back to 0.
    check_count_wraps: assert property (
        @(posedge clk) disable iff (rst)
        (count == 4'hF) |=> (count == 4'h0)
    );

endmodule

rtl:
module DFF_with_CLR_E(input D, C, E, CLR, output Q);
    wire CLR_bar;
    assign CLR_bar = ~CLR;
    DFFNE _TECHMAP_REPLACE_ (.D(D), .Q(Q), .CLK(C), .CE(~E), .CLR(CLR_bar));
endmodule

module DFFNE(D, Q, CLK, CE, CLR);
    input D, CLK, CE, CLR;
    output reg Q;

    always @(posedge CLK or negedge CLR)
    begin
        if (~CLR)
            Q <= 1'b0;
        else if (CE)
            Q <= D;
    end
endmodule

sva:
module DFF_with_CLR_E_sva (
    input logic D,
    input logic C,
    input logic E,
    input logic CLR,
    input logic Q
);

    // A sampled high clear forces Q low by the next clock sample.
    check_clear_forces_low: assert property (
        @(posedge C) CLR |=> (Q == 1'b0)
    );

    // With E low, loading D=0 drives Q low on the next clock sample.
    check_enabled_zero_load: assert property (
        @(posedge C) disable iff (CLR) (!E && !D) |=> (Q == 1'b0)
    );

    // A low Q stays low unless E is low and D is high.
    check_low_q_stays_low_without_enabled_one: assert property (
        @(posedge C) disable iff (CLR) ((Q == 1'b0) && (E || !D)) |=> (Q == 1'b0)
    );

    // Any observed rise of Q must come from a prior enabled load of D=1.
    check_rise_requires_enabled_one: assert property (
        @(posedge C) disable iff (CLR || $initstate) $rose(Q) |-> $past(!CLR && !E && D)
    );

endmodule

rtl:
module dffsr(clk, reset, set, d, q, qn);
    input clk, reset, set, d;
    output reg q, qn;

    always @(posedge clk) begin
        if (reset) begin
            q <= 0;
            qn <= 1;
        end else if (set) begin
            q <= 1;
            qn <= 0;
        end else begin
            q <= d;
            qn <= ~d;
        end
    end

endmodule

sva:
module dffsr_assertions (
    input logic clk,
    input logic reset,
    input logic set,
    input logic d,
    input logic q,
    input logic qn
);

    // Reset forces q low and qn high.
    check_reset_values: assert property (
        @(posedge clk) reset |=> (q == 1'b0 && qn == 1'b1)
    );

    // Set forces q high and qn low when reset is not asserted.
    check_set_values: assert property (
        @(posedge clk) disable iff (reset) set |=> (q == 1'b1 && qn == 1'b0)
    );

    // Data 1 is captured when neither reset nor set is asserted.
    check_capture_d_high: assert property (
        @(posedge clk) disable iff (reset) (!set && d) |=> (q == 1'b1 && qn == 1'b0)
    );

    // Data 0 is captured when neither reset nor set is asserted.
    check_capture_d_low: assert property (
        @(posedge clk) disable iff (reset) (!set && !d) |=> (q == 1'b0 && qn == 1'b1)
    );

    // q and qn remain complementary after each non-reset clock.
    check_complementary_outputs: assert property (
        @(posedge clk) disable iff (reset) 1'b1 |=> (qn == ~q)
    );

endmodule

rtl:
module top_module (
    input [7:0] a,
    input [7:0] b,
    input select,
    output [7:0] out_xor,
    output [7:0] out_and,
    output [7:0] out_not
);

    wire [7:0] b_not;
    assign b_not = ~b;

    wire [7:0] xor_result;
    assign xor_result = a ^ b;

    wire [7:0] and_result;
    assign and_result = a & b;

    assign out_xor = select ? xor_result : and_result;
    assign out_and = select ? and_result : xor_result;
    assign out_not = {8'b0, b_not};

endmodule

sva:
module top_module_sva (
    input logic [7:0] a,
    input logic [7:0] b,
    input logic       select,
    input logic [7:0] out_xor,
    input logic [7:0] out_and,
    input logic [7:0] out_not
);

    // No explicit clock or reset exists in the RTL; sample on the formal global clock.

    // out_xor must implement the select-controlled XOR/AND mux.
    check_out_xor_function: assert property (
        @($global_clock) out_xor == (select ? (a ^ b) : (a & b))
    );

    // out_and must implement the complementary select-controlled AND/XOR mux.
    check_out_and_function: assert property (
        @($global_clock) out_and == (select ? (a & b) : (a ^ b))
    );

    // out_not must equal the bitwise inversion of b.
    check_out_not_function: assert property (
        @($global_clock) out_not == ~b
    );

    // When select is high, out_xor is XOR and out_and is AND.
    check_select_high_routing: assert property (
        @($global_clock) select |-> ((out_xor == (a ^ b)) && (out_and == (a & b)))
    );

    // When select is low, out_xor is AND and out_and is XOR.
    check_select_low_routing: assert property (
        @($global_clock) !select |-> ((out_xor == (a & b)) && (out_and == (a ^ b)))
    );

endmodule

rtl:
module mux_4to1(
    input A,
    input B,
    input C,
    input D,
    input S0,
    input S1,
    output Y
);

    wire notS0, notS1;
    not (notS0, S0);
    not (notS1, S1);

    wire and1, and2, and3, and4;
    and (and1, A, notS1, notS0);
    and (and2, B, notS1, S0);
    and (and3, C, S1, notS0);
    and (and4, D, S1, S0);

    or (Y, and1, and2, and3, and4);

endmodule

sva:
module mux_4to1_sva(
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic S0,
    input logic S1,
    input logic Y
);

    // No RTL clock or reset; sample on the formal global clock.

    // When select is 00, output matches A.
    check_select_00: assert property (
        @($global_clock) ((S1 === 1'b0) && (S0 === 1'b0)) |-> (Y === A)
    );

    // When select is 01, output matches B.
    check_select_01: assert property (
        @($global_clock) ((S1 === 1'b0) && (S0 === 1'b1)) |-> (Y === B)
    );

    // When select is 10, output matches C.
    check_select_10: assert property (
        @($global_clock) ((S1 === 1'b1) && (S0 === 1'b0)) |-> (Y === C)
    );

    // When select is 11, output matches D.
    check_select_11: assert property (
        @($global_clock) ((S1 === 1'b1) && (S0 === 1'b1)) |-> (Y === D)
    );

    // Output matches the implemented 4-to-1 mux equation.
    check_mux_equation: assert property (
        @($global_clock) Y === ((A & ~S1 & ~S0) | (B & ~S1 & S0) | (C & S1 & ~S0) | (D & S1 & S0))
    );

endmodule

rtl:
module comparator_4bit (
    input [3:0] A,
    input [3:0] B,
    output EQ
);

    wire [3:0] equal_bits;

    assign equal_bits = A ^ B;

    assign EQ = ~(|equal_bits);

endmodule

sva:
module comparator_4bit_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic EQ
);

    // EQ must match the RTL compare equation.
    check_eq_matches_rtl_equation: assert property (
        @(posedge clk) EQ === ~(|(A ^ B))
    );

    // No bit differences must drive EQ high.
    check_no_bit_difference_sets_eq: assert property (
        @(posedge clk) (~(|(A ^ B))) |-> (EQ === 1'b1)
    );

    // Any bit difference must drive EQ low.
    check_any_bit_difference_clears_eq: assert property (
        @(posedge clk) (|(A ^ B)) |-> (EQ === 1'b0)
    );

    // EQ high implies the inputs have no differing bits.
    check_eq_high_implies_no_bit_difference: assert property (
        @(posedge clk) (EQ === 1'b1) |-> (~(|(A ^ B)))
    );

    // EQ low implies at least one input bit differs.
    check_eq_low_implies_bit_difference: assert property (
        @(posedge clk) (EQ === 1'b0) |-> (|(A ^ B))
    );

    // Stable inputs must keep EQ stable at sampled clock edges.
    check_stable_inputs_keep_eq_stable: assert property (
        @(posedge clk) ($stable(A) && $stable(B)) |-> $stable(EQ)
    );

endmodule

rtl:
module decoder_3to8 (
    input [2:0] in,
    output [7:0] out
);

assign out[0] = ~(in[2] | in[1] | in[0]);
assign out[1] = ~(in[2] | in[1] | ~in[0]);
assign out[2] = ~(in[2] | ~in[1] | in[0]);
assign out[3] = ~(in[2] | ~in[1] | ~in[0]);
assign out[4] = ~(~in[2] | in[1] | in[0]);
assign out[5] = ~(~in[2] | in[1] | ~in[0]);
assign out[6] = ~(~in[2] | ~in[1] | in[0]);
assign out[7] = ~(~in[2] | ~in[1] | ~in[0]);

endmodule

sva:
module decoder_3to8_sva (
    input logic       clk,
    input logic [2:0] in,
    input logic [7:0] out
);

    // out[0] is asserted only for input 3'b000.
    check_out0_decode: assert property (
        @(posedge clk) out[0] == (~in[2] & ~in[1] & ~in[0])
    );

    // out[1] is asserted only for input 3'b001.
    check_out1_decode: assert property (
        @(posedge clk) out[1] == (~in[2] & ~in[1] &  in[0])
    );

    // out[2] is asserted only for input 3'b010.
    check_out2_decode: assert property (
        @(posedge clk) out[2] == (~in[2] &  in[1] & ~in[0])
    );

    // out[3] is asserted only for input 3'b011.
    check_out3_decode: assert property (
        @(posedge clk) out[3] == (~in[2] &  in[1] &  in[0])
    );

    // out[4] is asserted only for input 3'b100.
    check_out4_decode: assert property (
        @(posedge clk) out[4] == ( in[2] & ~in[1] & ~in[0])
    );

    // out[5] is asserted only for input 3'b101.
    check_out5_decode: assert property (
        @(posedge clk) out[5] == ( in[2] & ~in[1] &  in[0])
    );

    // out[6] is asserted only for input 3'b110.
    check_out6_decode: assert property (
        @(posedge clk) out[6] == ( in[2] &  in[1] & ~in[0])
    );

    // out[7] is asserted only for input 3'b111.
    check_out7_decode: assert property (
        @(posedge clk) out[7] == ( in[2] &  in[1] &  in[0])
    );

    // The decoder output is always exactly one-hot.
    check_output_onehot: assert property (
        @(posedge clk) $onehot(out)
    );

    // The full output vector matches a left-shifted one-hot decode of input.
    check_full_vector_decode: assert property (
        @(posedge clk) out == (8'b0000_0001 << in)
    );

endmodule

module clock_gate_4bit_up_counter_sva (
    input logic CLK,
    input logic EN,
    input logic TE,
    input logic ENCLK
);

    // TE has priority and drives ENCLK low on the next cycle.
    check_te_forces_enclk_low: assert property (
        @(posedge CLK) disable iff ($initstate)
        TE |=> (ENCLK == 1'b0)
    );

    // A low-to-high EN transition with TE low raises ENCLK for the next cycle.
    check_en_rise_sets_enclk: assert property (
        @(posedge CLK) disable iff ($initstate)
        (!TE && EN && !$past(EN)) |=> (ENCLK == 1'b1)
    );

    // A sustained high EN with TE low does not generate another ENCLK pulse.
    check_en_high_no_repeat_pulse: assert property (
        @(posedge CLK) disable iff ($initstate)
        (!TE && EN && $past(EN)) |=> (ENCLK == 1'b0)
    );

    // A low EN with TE low keeps ENCLK low on the next cycle.
    check_en_low_clears_enclk: assert property (
        @(posedge CLK) disable iff ($initstate)
        (!TE && !EN) |=> (ENCLK == 1'b0)
    );

    // ENCLK can only be high if TE was low and EN was high on the prior clock.
    check_enclk_requires_prev_en_and_te_low: assert property (
        @(posedge CLK) disable iff ($initstate)
        ENCLK |-> (!$past(TE) && $past(EN))
    );

    // ENCLK is a single-cycle pulse once the sampled history is established.
    check_enclk_is_single_cycle_pulse: assert property (
        @(posedge CLK) disable iff ($initstate)
        ENCLK |=> (ENCLK == 1'b0)
    );

endmodule

rtl:
module half_subtractor (
  input A,
  input B,
  output D,
  output Bout
);

  assign D = A ^ B;
  assign Bout = ~A & B;

endmodule


module full_subtractor (
  input A,
  input B,
  input Bin,
  output D,
  output Bout
);

  wire D1, Bout1, D2, Bout2;

  half_subtractor HS1(.A(A), .B(B), .D(D1), .Bout(Bout1));
  half_subtractor HS2(.A(D1), .B(Bin), .D(D), .Bout(Bout2));
  assign Bout = Bout1 | Bout2;

endmodule

sva:
module full_subtractor_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic Bin,
    input logic D,
    input logic Bout
);

    // No RTL reset is present; clk is a sampling clock for combinational checks.

    // Difference is the xor of A, B, and Bin.
    check_difference_equation: assert property (
        @(posedge clk) D == (A ^ B ^ Bin)
    );

    // Borrow matches the implemented two-half-subtractor expression.
    check_borrow_equation: assert property (
        @(posedge clk) Bout == (((~A) & B) | ((~(A ^ B)) & Bin))
    );

    // 0 - 0 - 0 gives zero difference and no borrow.
    check_zero_minus_zero_no_borrowin: assert property (
        @(posedge clk) (!A && !B && !Bin) |-> (D == 1'b0 && Bout == 1'b0)
    );

    // 0 - 0 - 1 gives difference one and borrow one.
    check_zero_minus_zero_with_borrowin: assert property (
        @(posedge clk) (!A && !B && Bin) |-> (D == 1'b1 && Bout == 1'b1)
    );

    // 0 - 1 - 0 gives difference one and borrow one.
    check_zero_minus_one_no_borrowin: assert property (
        @(posedge clk) (!A && B && !Bin) |-> (D == 1'b1 && Bout == 1'b1)
    );

    // 0 - 1 - 1 gives zero difference and borrow one.
    check_zero_minus_one_with_borrowin: assert property (
        @(posedge clk) (!A && B && Bin) |-> (D == 1'b0 && Bout == 1'b1)
    );

    // 1 - 0 - 0 gives difference one and no borrow.
    check_one_minus_zero_no_borrowin: assert property (
        @(posedge clk) (A && !B && !Bin) |-> (D == 1'b1 && Bout == 1'b0)
    );

    // 1 - 0 - 1 gives zero difference and no borrow.
    check_one_minus_zero_with_borrowin: assert property (
        @(posedge clk) (A && !B && Bin) |-> (D == 1'b0 && Bout == 1'b0)
    );

    // 1 - 1 - 0 gives zero difference and no borrow.
    check_one_minus_one_no_borrowin: assert property (
        @(posedge clk) (A && B && !Bin) |-> (D == 1'b0 && Bout == 1'b0)
    );

    // 1 - 1 - 1 gives difference one and borrow one.
    check_one_minus_one_with_borrowin: assert property (
        @(posedge clk) (A && B && Bin) |-> (D == 1'b1 && Bout == 1'b1)
    );

endmodule

rtl:
module mux3(
    input in0,
    input in1,
    input in2,
    input [1:0] sel,
    input clr,
    input set,
    output reg out
);

always @(*) begin
    if(set) begin
        out <= 1'b1;
    end
    else if(clr) begin
        out <= 1'b0;
    end
    else begin
        case(sel)
            2'b00: out = in0;
            2'b01: out = in1;
            2'b10: out = in2;
            2'b11: out = 1'b0;
        endcase
    end
end

endmodule

sva:
module mux3_sva (
    input logic clk,
    input logic in0,
    input logic in1,
    input logic in2,
    input logic [1:0] sel,
    input logic clr,
    input logic set,
    input logic out
);

    // out matches the combinational priority mux function.
    check_mux_function: assert property (
        @(posedge clk)
        out == (set ? 1'b1 :
                (clr ? 1'b0 :
                 ((sel == 2'b00) ? in0 :
                  ((sel == 2'b01) ? in1 :
                   ((sel == 2'b10) ? in2 : 1'b0)))))
    );

    // set has highest priority and forces out high.
    check_set_priority: assert property (
        @(posedge clk)
        set |-> (out == 1'b1)
    );

    // clr forces out low when set is low.
    check_clr_priority: assert property (
        @(posedge clk)
        (!set && clr) |-> (out == 1'b0)
    );

    // sel 00 passes in0 when set and clr are low.
    check_sel_in0: assert property (
        @(posedge clk)
        (!set && !clr && (sel == 2'b00)) |-> (out == in0)
    );

    // sel 01 passes in1 when set and clr are low.
    check_sel_in1: assert property (
        @(posedge clk)
        (!set && !clr && (sel == 2'b01)) |-> (out == in1)
    );

    // sel 10 passes in2 when set and clr are low.
    check_sel_in2: assert property (
        @(posedge clk)
        (!set && !clr && (sel == 2'b10)) |-> (out == in2)
    );

    // sel 11 forces out low when set and clr are low.
    check_sel_11_zero: assert property (
        @(posedge clk)
        (!set && !clr && (sel == 2'b11)) |-> (out == 1'b0)
    );

endmodule

rtl:
module jt51_lin2exp(
  input      [15:0] lin,
  output reg [9:0] man,
  output reg [2:0] exp
);

always @(*) begin
  casez( lin[15:9] )
    7'b10?????: begin
        man = lin[15:6];
        exp = 3'd7;
      end
    7'b110????: begin
        man = lin[14:5];
        exp = 3'd6;
      end
    7'b1110???: begin
        man = lin[13:4];
        exp = 3'd5;
      end
    7'b11110??: begin
        man = lin[12:3];
        exp = 3'd4;
      end
    7'b111110?: begin
        man = lin[11:2];
        exp = 3'd3;
      end
    7'b1111110: begin
        man = lin[10:1];
        exp = 3'd2;
      end
    7'b1111111: begin
        man = lin[ 9:0];
        exp = 3'd1;
      end    
    7'b01?????: begin
        man = lin[15:6];
        exp = 3'd7;
      end
    7'b001????: begin
        man = lin[14:5];
        exp = 3'd6;
      end
    7'b0001???: begin
        man = lin[13:4];
        exp = 3'd5;
      end
    7'b00001??: begin
        man = lin[12:3];
        exp = 3'd4;
      end
    7'b000001?: begin
        man = lin[11:2];
        exp = 3'd3;
      end
    7'b0000001: begin
        man = lin[10:1];
        exp = 3'd2;
      end
    7'b0000000: begin
        man = lin[ 9:0];
        exp = 3'd1;
      end

    default: begin
        man = lin[9:0];
        exp = 3'd1;
      end
  endcase
end

endmodule

sva:
module jt51_lin2exp_sva (
    input logic        clk,
    input logic [15:0] lin,
    input logic [9:0]  man,
    input logic [2:0]  exp
);

    // Prefix 10 or 01 maps to exp 7 and lin[15:6].
    check_exp7_class: assert property (
        @(posedge clk)
        (((lin[15:14] == 2'b10) || (lin[15:14] == 2'b01)) |-> ((man == lin[15:6]) && (exp == 3'd7)))
    );

    // Prefix 110 or 001 maps to exp 6 and lin[14:5].
    check_exp6_class: assert property (
        @(posedge clk)
        (((lin[15:13] == 3'b110) || (lin[15:13] == 3'b001)) |-> ((man == lin[14:5]) && (exp == 3'd6)))
    );

    // Prefix 1110 or 0001 maps to exp 5 and lin[13:4].
    check_exp5_class: assert property (
        @(posedge clk)
        (((lin[15:12] == 4'b1110) || (lin[15:12] == 4'b0001)) |-> ((man == lin[13:4]) && (exp == 3'd5)))
    );

    // Prefix 11110 or 00001 maps to exp 4 and lin[12:3].
    check_exp4_class: assert property (
        @(posedge clk)
        (((lin[15:11] == 5'b11110) || (lin[15:11] == 5'b00001)) |-> ((man == lin[12:3]) && (exp == 3'd4)))
    );

    // Prefix 111110 or 000001 maps to exp 3 and lin[11:2].
    check_exp3_class: assert property (
        @(posedge clk)
        (((lin[15:10] == 6'b111110) || (lin[15:10] == 6'b000001)) |-> ((man == lin[11:2]) && (exp == 3'd3)))
    );

    // Prefix 1111110 or 0000001 maps to exp 2 and lin[10:1].
    check_exp2_class: assert property (
        @(posedge clk)
        (((lin[15:9] == 7'b1111110) || (lin[15:9] == 7'b0000001)) |-> ((man == lin[10:1]) && (exp == 3'd2)))
    );

    // Prefix 1111111 or 0000000 maps to exp 1 and lin[9:0].
    check_exp1_class: assert property (
        @(posedge clk)
        (((lin[15:9] == 7'b1111111) || (lin[15:9] == 7'b0000000)) |-> ((man == lin[9:0]) && (exp == 3'd1)))
    );

    // The outputs must match one of the seven implemented prefix classes.
    check_complete_mapping: assert property (
        @(posedge clk)
        (
            ((((lin[15:14] == 2'b10) || (lin[15:14] == 2'b01)) && (man == lin[15:6]) && (exp == 3'd7))) ||
            ((((lin[15:13] == 3'b110) || (lin[15:13] == 3'b001)) && (man == lin[14:5]) && (exp == 3'd6))) ||
            ((((lin[15:12] == 4'b1110) || (lin[15:12] == 4'b0001)) && (man == lin[13:4]) && (exp == 3'd5))) ||
            ((((lin[15:11] == 5'b11110) || (lin[15:11] == 5'b00001)) && (man == lin[12:3]) && (exp == 3'd4))) ||
            ((((lin[15:10] == 6'b111110) || (lin[15:10] == 6'b000001)) && (man == lin[11:2]) && (exp == 3'd3))) ||
            ((((lin[15:9]  == 7'b1111110) || (lin[15:9]  == 7'b0000001)) && (man == lin[10:1]) && (exp == 3'd2))) ||
            ((((lin[15:9]  == 7'b1111111) || (lin[15:9]  == 7'b0000000)) && (man == lin[9:0])  && (exp == 3'd1)))
        )
    );

    // The exponent is never driven to zero.
    check_exp_nonzero: assert property (
        @(posedge clk)
        (exp != 3'd0)
    );

    // If the input is unchanged, the sampled outputs remain unchanged.
    check_outputs_stable_when_input_stable: assert property (
        @(posedge clk)
        $stable(lin) |-> $stable({man, exp})
    );

endmodule

rtl:
module shift_register (
    input [3:0] D0,
    input [3:0] D1,
    input [3:0] D2,
    input [3:0] D3,
    input CLK,
    input LOAD,
    input RESET,
    output reg [3:0] Q0,
    output reg [3:0] Q1,
    output reg [3:0] Q2,
    output reg [3:0] Q3
);

    always @ (posedge CLK) begin
        if (RESET) begin
            Q0 <= 4'b0000;
            Q1 <= 4'b0000;
            Q2 <= 4'b0000;
            Q3 <= 4'b0000;
        end
        else if (LOAD) begin
            Q0 <= D0;
            Q1 <= D1;
            Q2 <= D2;
            Q3 <= D3;
        end
        else begin
            Q0 <= Q1;
            Q1 <= Q2;
            Q2 <= Q3;
            Q3 <= D0;
        end
    end

endmodule

sva:
module shift_register_assertions (
    input logic [3:0] D0,
    input logic [3:0] D1,
    input logic [3:0] D2,
    input logic [3:0] D3,
    input logic CLK,
    input logic LOAD,
    input logic RESET,
    input logic [3:0] Q0,
    input logic [3:0] Q1,
    input logic [3:0] Q2,
    input logic [3:0] Q3
);

    // Reset clears Q0 by the next clock sample.
    reset_clears_Q0: assert property (
        @(posedge CLK)
        RESET |=> (Q0 == 4'b0000)
    );

    // Reset clears Q1 by the next clock sample.
    reset_clears_Q1: assert property (
        @(posedge CLK)
        RESET |=> (Q1 == 4'b0000)
    );

    // Reset clears Q2 by the next clock sample.
    reset_clears_Q2: assert property (
        @(posedge CLK)
        RESET |=> (Q2 == 4'b0000)
    );

    // Reset clears Q3 by the next clock sample.
    reset_clears_Q3: assert property (
        @(posedge CLK)
        RESET |=> (Q3 == 4'b0000)
    );

    // LOAD causes Q0 to capture D0.
    load_captures_D0_into_Q0: assert property (
        @(posedge CLK) disable iff (RESET)
        LOAD |=> (Q0 == $past(D0))
    );

    // LOAD causes Q1 to capture D1.
    load_captures_D1_into_Q1: assert property (
        @(posedge CLK) disable iff (RESET)
        LOAD |=> (Q1 == $past(D1))
    );

    // LOAD causes Q2 to capture D2.
    load_captures_D2_into_Q2: assert property (
        @(posedge CLK) disable iff (RESET)
        LOAD |=> (Q2 == $past(D2))
    );

    // LOAD causes Q3 to capture D3.
    load_captures_D3_into_Q3: assert property (
        @(posedge CLK) disable iff (RESET)
        LOAD |=> (Q3 == $past(D3))
    );

    // Shift mode moves Q1 into Q0.
    shift_moves_Q1_into_Q0: assert property (
        @(posedge CLK) disable iff (RESET)
        !LOAD |=> (Q0 == $past(Q1))
    );

    // Shift mode moves Q2 into Q1.
    shift_moves_Q2_into_Q1: assert property (
        @(posedge CLK) disable iff (RESET)
        !LOAD |=> (Q1 == $past(Q2))
    );

    // Shift mode moves Q3 into Q2.
    shift_moves_Q3_into_Q2: assert property (
        @(posedge CLK) disable iff (RESET)
        !LOAD |=> (Q2 == $past(Q3))
    );

    // Shift mode moves D0 into Q3.
    shift_moves_D0_into_Q3: assert property (
        @(posedge CLK) disable iff (RESET)
        !LOAD |=> (Q3 == $past(D0))
    );

endmodule

rtl:
module FSM #(
  parameter n = 4, // number of input signals
  parameter m = 2, // number of output signals
  parameter s = 8 // number of states in the FSM
)(
  input [n-1:0] in,
  input rst,
  input clk,
  output [m-1:0] out,
  output [s-1:0] state
);

reg [s-1:0] state_reg = STATE_RESET;
reg [m-1:0] out_reg = 2'b00;

// Define the states
parameter STATE_RESET = 3'b000;
parameter STATE_A = 3'b001;
parameter STATE_B = 3'b010;
parameter STATE_C = 3'b011;
parameter STATE_D = 3'b100;
parameter STATE_E = 3'b101;
parameter STATE_F = 3'b110;
parameter STATE_G = 3'b111;

// Define the outputs for each state
always @(*) begin
  case (state_reg)
    STATE_RESET: out_reg = 2'b00;
    STATE_A: out_reg = 2'b01;
    STATE_B: out_reg = 2'b10;
    STATE_C: out_reg = 2'b11;
    STATE_D: out_reg = 2'b01;
    STATE_E: out_reg = 2'b10;
    STATE_F: out_reg = 2'b11;
    STATE_G: out_reg = 2'b00;
    default: out_reg = 2'b00;
  endcase
end

// Define the transitions between states
always @ (posedge clk or posedge rst) begin
  if (rst) begin
    state_reg <= STATE_RESET;
  end else begin
    case (state_reg)
      STATE_RESET: begin
        if (in == 4'b0000) begin
          state_reg <= STATE_A;
        end
      end
      STATE_A: begin
        if (in == 4'b0001) begin
          state_reg <= STATE_B;
        end else if (in == 4'b0010) begin
          state_reg <= STATE_C;
        end
      end
      STATE_B: begin
        if (in == 4'b0011) begin
          state_reg <= STATE_D;
        end else if (in == 4'b0100) begin
          state_reg <= STATE_E;
        end
      end
      STATE_C: begin
        if (in == 4'b0101) begin
          state_reg <= STATE_E;
        end else if (in == 4'b0110) begin
          state_reg <= STATE_F;
        end
      end
      STATE_D: begin
        if (in == 4'b0111) begin
          state_reg <= STATE_G;
        end
      end
      STATE_E: begin
        if (in == 4'b1000) begin
          state_reg <= STATE_G;
        end
      end
      STATE_F: begin
        if (in == 4'b1001) begin
          state_reg <= STATE_G;
        end
      end
      STATE_G: begin
        if (in == 4'b1010) begin
          state_reg <= STATE_RESET;
        end
      end
    endcase
  end
end

assign out = out_reg;
assign state = state_reg;

endmodule

