module my_logic (
    X,
    A1,
    A2,
    B1,
    C1
);

    output X;
    input A1, A2, B1, C1;

    wire and_out;
    wire or_out;

    and #(1) and_gate (and_out, A1, A2);
    or  #(3) or_gate  (or_out,  C1, B1, and_out);
    buf #(1) buf_gate (X,      or_out);

endmodule

sva:
module my_logic_sva (
    input logic clk,
    input logic X,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic C1
);

    // X must equal C1 OR B1 OR (A1 AND A2).
    check_output_equation: assert property (
        @(posedge clk) X == (C1 | B1 | (A1 & A2))
    );

    // C1 high must drive X high through the OR gate.
    check_c1_drives_x_high: assert property (
        @(posedge clk) C1 |-> X
    );

    // B1 high must drive X high through the OR gate.
    check_b1_drives_x_high: assert property (
        @(posedge clk) B1 |-> X
    );

    // A1 and A2 high together must drive X high through the AND term.
    check_a1_a2_drive_x_high: assert property (
        @(posedge clk) (A1 & A2) |-> X
    );

    // If all OR inputs are low, X must be low.
    check_all_terms_low_drive_x_low: assert property (
        @(posedge clk) (!C1 && !B1 && !(A1 & A2)) |-> !X
    );

endmodule

rtl:
module comparator_3bit (
  input [2:0] A,
  input [2:0] B,
  output reg [1:0] result
);

  always @* begin
    if (A > B)
      result = 2'b01;
    else if (A == B)
      result = 2'b00;
    else
      result = 2'b11;
  end

endmodule

sva:
module comparator_3bit_assertions (
    input logic clk,
    input logic [2:0] A,
    input logic [2:0] B,
    input logic [1:0] result
);

    // A greater than B produces 01.
    check_a_gt_b_encoding: assert property (
        @(posedge clk) (A > B) |-> (result == 2'b01)
    );

    // Equal inputs produce 00.
    check_a_eq_b_encoding: assert property (
        @(posedge clk) (A == B) |-> (result == 2'b00)
    );

    // A less than B produces 11.
    check_a_lt_b_encoding: assert property (
        @(posedge clk) (A < B) |-> (result == 2'b11)
    );

    // The LSB is high when A and B differ.
    check_result_lsb_matches_inequality: assert property (
        @(posedge clk) (result[0] == (A != B))
    );

    // The MSB is high only when A is less than B.
    check_result_msb_matches_less_than: assert property (
        @(posedge clk) (result[1] == (A < B))
    );

    // The unused encoding 10 is never generated.
    check_no_unused_encoding: assert property (
        @(posedge clk) (result != 2'b10)
    );

    // Stable inputs keep the result stable.
    check_stable_inputs_hold_result: assert property (
        @(posedge clk) ($stable(A) && $stable(B)) |-> $stable(result)
    );

endmodule

rtl:
module sky130_fd_sc_hdll__dlxtn (
    input D,
    input VPWR,
    input VGND,
    input VPB,
    input VNB,
    output Q,
    input GATE_N
);

wire D_0;
wire VPWR_1;
wire VGND_1;
wire VPB_1;
wire VNB_1;
wire Q_0;

assign D_0 = (D == 1'b0);
assign VPWR_1 = (VPWR == 1'b1);
assign VGND_1 = (VGND == 1'b1);
assign VPB_1 = (VPB == 1'b1);
assign VNB_1 = (VNB == 1'b1);

and and_gate_1 (Q_0, D_0, VPWR_1, VGND_1, VPB_1, VNB_1);

assign Q = (GATE_N == 1'b0) ? Q_0 : D;

endmodule

sva:
module sky130_fd_sc_hdll__dlxtn_sva (
    input logic clk,
    input logic D,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB,
    input logic Q,
    input logic GATE_N
);

    // Q matches the exact combinational equation implemented by the RTL.
    check_full_function: assert property (
        @(posedge clk)
        Q === (
            (GATE_N == 1'b0) ?
            ((D == 1'b0) & (VPWR == 1'b1) & (VGND == 1'b1) & (VPB == 1'b1) & (VNB == 1'b1)) :
            D
        )
    );

    // When GATE_N is high, Q passes D through.
    check_gate_high_passthrough: assert property (
        @(posedge clk)
        ((GATE_N === 1'b1)) |-> (Q === D)
    );

    // When GATE_N is low and all power pins are high, Q matches the qualified inversion of D.
    check_gate_low_valid_power_behavior: assert property (
        @(posedge clk)
        ((GATE_N === 1'b0) &&
         (VPWR === 1'b1) &&
         (VGND === 1'b1) &&
         (VPB  === 1'b1) &&
         (VNB  === 1'b1)) |-> (Q === (D == 1'b0))
    );

    // When GATE_N is low and D is high, Q is forced low.
    check_gate_low_data_high_forces_low: assert property (
        @(posedge clk)
        ((GATE_N === 1'b0) &&
         (D === 1'b1)) |-> (Q === 1'b0)
    );

    // When GATE_N is low and any power pin is low, Q is forced low.
    check_gate_low_power_low_forces_low: assert property (
        @(posedge clk)
        ((GATE_N === 1'b0) &&
         ((VPWR === 1'b0) ||
          (VGND === 1'b0) ||
          (VPB  === 1'b0) ||
          (VNB  === 1'b0))) |-> (Q === 1'b0)
    );

    // When GATE_N is low, D is low, and all power pins are high, Q is high.
    check_gate_low_data_low_with_valid_power_drives_high: assert property (
        @(posedge clk)
        ((GATE_N === 1'b0) &&
         (D === 1'b0) &&
         (VPWR === 1'b1) &&
         (VGND === 1'b1) &&
         (VPB  === 1'b1) &&
         (VNB  === 1'b1)) |-> (Q === 1'b1)
    );

endmodule

rtl:
module binary_adder (
    input [3:0] A,
    input [3:0] B,
    output reg [3:0] S
);

wire [4:0] temp_sum;

assign temp_sum = A + B; //sum of A and B

always @(*) begin
    if(temp_sum > 15) //truncate if sum is greater than 15
        S = temp_sum[3:0];
    else
        S = temp_sum[3:0];
end

endmodule

sva:
module binary_adder_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] S
);

    // When the 5-bit sum is 15 or less, S matches the exact sum.
    check_sum_no_overflow: assert property (
        @(posedge clk)
        (({1'b0, A} + {1'b0, B}) <= 5'd15) |-> ({1'b0, S} == ({1'b0, A} + {1'b0, B}))
    );

    // When the 5-bit sum exceeds 15, S wraps to the low 4 bits.
    check_sum_overflow_wrap: assert property (
        @(posedge clk)
        (({1'b0, A} + {1'b0, B}) > 5'd15) |-> ({1'b0, S} == (({1'b0, A} + {1'b0, B}) - 5'd16))
    );

    // A zero B input leaves the output equal to A.
    check_b_zero_identity: assert property (
        @(posedge clk)
        (B == 4'd0) |-> (S == A)
    );

    // A zero A input leaves the output equal to B.
    check_a_zero_identity: assert property (
        @(posedge clk)
        (A == 4'd0) |-> (S == B)
    );

    // The largest non-overflowing sum passes through unchanged.
    check_boundary_sum_fifteen: assert property (
        @(posedge clk)
        (({1'b0, A} + {1'b0, B}) == 5'd15) |-> (S == 4'd15)
    );

    // The first overflowing sum wraps to zero.
    check_boundary_sum_sixteen: assert property (
        @(posedge clk)
        (({1'b0, A} + {1'b0, B}) == 5'd16) |-> (S == 4'd0)
    );

    // Stable inputs keep the sampled output stable.
    check_stable_inputs_stable_output: assert property (
        @(posedge clk)
        ($stable(A) && $stable(B)) |-> $stable(S)
    );

endmodule

rtl:
module delay_1ms(input clk, input reset, input in, output out);
	reg [19:0] r;
	always @(posedge clk or posedge reset) begin
		if(reset)
			r <= 0;
		else begin
			if(in)
				r <= r + 20'b1;
			else
				r <= 0;
		end
	end
	assign out = r >= 1000;
endmodule

sva:
module delay_1ms_sva (
    input logic        clk,
    input logic        reset,
    input logic        in,
    input logic        out,
    input logic [19:0] r
);

    // Reset clears the counter and output by the next sampled clock.
    check_reset_clears_state: assert property (
        @(posedge clk) reset |=> (r == 20'd0 && out == 1'b0)
    );

    // The first cycle after reset release still sees a cleared state.
    check_reset_release_starts_cleared: assert property (
        @(posedge clk) reset ##1 !reset |-> (r == 20'd0 && out == 1'b0)
    );

    // The output reflects whether the counter has reached the 1000-count threshold.
    check_output_matches_threshold: assert property (
        @(posedge clk) disable iff (reset) out == (r >= 20'd1000)
    );

    // A low input clears the counter and deasserts the output on the next clock.
    check_input_low_clears_state: assert property (
        @(posedge clk) disable iff (reset) !in |=> (r == 20'd0 && out == 1'b0)
    );

    // A high input increments the counter by one on the next clock.
    check_input_high_increments_counter: assert property (
        @(posedge clk) disable iff (reset) in |=> (r == ($past(r) + 20'd1))
    );

    // Reaching 999 with input high makes the output assert on the next cycle.
    check_threshold_crossing_sets_output: assert property (
        @(posedge clk) disable iff (reset) (in && (r == 20'd999)) |=> out
    );

endmodule

rtl:
module ripple_carry_adder (
    input clk,
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output reg [3:0] S,
    output reg V
);

    wire [3:0] C;
    wire [3:0] X;
    full_adder FA0(.a(A[0]), .b(B[0]), .c_in(Cin), .s(X[0]), .c(C[0]));
    full_adder FA1(.a(A[1]), .b(B[1]), .c_in(C[0]), .s(X[1]), .c(C[1]));
    full_adder FA2(.a(A[2]), .b(B[2]), .c_in(C[1]), .s(X[2]), .c(C[2]));
    full_adder FA3(.a(A[3]), .b(B[3]), .c_in(C[2]), .s(X[3]), .c(C[3]));

    always @(posedge clk) begin
        S <= X;
        V <= C[3];
    end

endmodule
module full_adder (
    input a,
    input b,
    input c_in,
    output s,
    output c
);

    assign s = a ^ b ^ c_in;
    assign c = (a & b) | (a & c_in) | (b & c_in);

endmodule

sva:
module ripple_carry_adder_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic Cin,
    input logic [3:0] S,
    input logic V
);

    // Registered outputs equal the previous cycle's 5-bit addition.
    check_registered_sum_and_carry: assert property (
        @(posedge clk)
        !$initstate |-> ({V, S} == ($past({1'b0, A}) + $past({1'b0, B}) + $past(Cin)))
    );

    // Bit 0 sum follows the first full-adder XOR equation from the previous cycle.
    check_lsb_sum_equation: assert property (
        @(posedge clk)
        !$initstate |-> (S[0] == ($past(A[0]) ^ $past(B[0]) ^ $past(Cin)))
    );

    // Carry-out matches whether the previous addition exceeded 4 bits.
    check_carry_out_threshold: assert property (
        @(posedge clk)
        !$initstate |-> (V == (($past({1'b0, A}) + $past({1'b0, B}) + $past(Cin)) >= 5'd16))
    );

    // Zero inputs with zero carry-in produce zero output on the next cycle.
    check_zero_addition_case: assert property (
        @(posedge clk)
        (!$initstate && ($past(A) == 4'b0000) && ($past(B) == 4'b0000) && ($past(Cin) == 1'b0))
        |-> ({V, S} == 5'b00000)
    );

    // All-ones inputs with carry-in produce all-ones output and carry-out on the next cycle.
    check_max_addition_case: assert property (
        @(posedge clk)
        (!$initstate && ($past(A) == 4'b1111) && ($past(B) == 4'b1111) && ($past(Cin) == 1'b1))
        |-> ({V, S} == 5'b11111)
    );

    // Repeating the same inputs across cycles keeps the registered output unchanged one cycle later.
    check_output_stable_when_inputs_repeat: assert property (
        @(posedge clk)
        (!$initstate && (A == $past(A)) && (B == $past(B)) && (Cin == $past(Cin)))
        |=> ({V, S} == $past({V, S}))
    );

endmodule

rtl:
module sky130_fd_sc_ms__maj3 (
    X,
    A,
    B,
    C
);

    output X;
    input  A;
    input  B;
    input  C;

    wire or0_out  ;
    wire and0_out ;
    wire and1_out ;
    wire or1_out_X;

    or  or0  (or0_out  , B, A              );
    and and0 (and0_out , or0_out, C        );
    and and1 (and1_out , A, B              );
    or  or1  (or1_out_X, and1_out, and0_out);
    buf buf0 (X        , or1_out_X         );

endmodule

sva:
module sky130_fd_sc_ms__maj3_sva (
    input logic clk,
    input logic X,
    input logic A,
    input logic B,
    input logic C
);

    // X matches the implemented gate equation.
    check_implemented_majority_equation: assert property (
        @(posedge clk) (X == ((A & B) | ((A | B) & C)))
    );

    // A and B high force X high.
    check_ab_high_sets_x: assert property (
        @(posedge clk) ((A == 1'b1) && (B == 1'b1)) |-> (X == 1'b1)
    );

    // A and C high force X high.
    check_ac_high_sets_x: assert property (
        @(posedge clk) ((A == 1'b1) && (C == 1'b1)) |-> (X == 1'b1)
    );

    // B and C high force X high.
    check_bc_high_sets_x: assert property (
        @(posedge clk) ((B == 1'b1) && (C == 1'b1)) |-> (X == 1'b1)
    );

    // A and B low force X low.
    check_ab_low_clears_x: assert property (
        @(posedge clk) ((A == 1'b0) && (B == 1'b0)) |-> (X == 1'b0)
    );

    // A and C low force X low.
    check_ac_low_clears_x: assert property (
        @(posedge clk) ((A == 1'b0) && (C == 1'b0)) |-> (X == 1'b0)
    );

    // B and C low force X low.
    check_bc_low_clears_x: assert property (
        @(posedge clk) ((B == 1'b0) && (C == 1'b0)) |-> (X == 1'b0)
    );

endmodule

rtl:
module forwarding_unit (
  input [4:0] rt_addr_IDEX,
  input [4:0] rs_addr_IDEX,
  input [4:0] rd_addr_EXMEM,
  input [4:0] rd_addr_MEMWB,
  input regwrite_EXMEM,
  input regwrite_MEMWB,
  output [1:0] forwardA,
  output [1:0] forwardB
);

  wire rs_from_mem, rt_from_mem, rs_from_ex, rt_from_ex;

  // Check for forwarding from memory stage
  assign rs_from_mem = (rd_addr_MEMWB == rs_addr_IDEX) && (regwrite_MEMWB == 1);
  assign rt_from_mem = (rd_addr_MEMWB == rt_addr_IDEX) && (regwrite_MEMWB == 1);

  // Check for forwarding from execution stage
  assign rs_from_ex = (rd_addr_EXMEM == rs_addr_IDEX) && (regwrite_EXMEM == 1);
  assign rt_from_ex = (rd_addr_EXMEM == rt_addr_IDEX) && (regwrite_EXMEM == 1);

  // Determine which forwarding signals to use
  assign forwardA = (rs_from_mem | rs_from_ex) ? 2'b10 : 2'b00;
  assign forwardB = (rt_from_mem | rt_from_ex) ? 2'b10 : 2'b00;

endmodule

sva:
module forwarding_unit_sva (
    input logic [4:0] rt_addr_IDEX,
    input logic [4:0] rs_addr_IDEX,
    input logic [4:0] rd_addr_EXMEM,
    input logic [4:0] rd_addr_MEMWB,
    input logic regwrite_EXMEM,
    input logic regwrite_MEMWB,
    input logic [1:0] forwardA,
    input logic [1:0] forwardB
);

    wire rs_from_mem, rt_from_mem, rs_from_ex, rt_from_ex;

    assign rs_from_mem = (rd_addr_MEMWB == rs_addr_IDEX) && (regwrite_MEMWB == 1'b1);
    assign rt_from_mem = (rd_addr_MEMWB == rt_addr_IDEX) && (regwrite_MEMWB == 1'b1);
    assign rs_from_ex  = (rd_addr_EXMEM == rs_addr_IDEX) && (regwrite_EXMEM == 1'b1);
    assign rt_from_ex  = (rd_addr_EXMEM == rt_addr_IDEX) && (regwrite_EXMEM == 1'b1);

    // forwardA must match the implemented rs forwarding equation.
    check_forwardA_equation: assert property (
        @($global_clock) forwardA == ((rs_from_mem | rs_from_ex) ? 2'b10 : 2'b00)
    );

    // forwardB must match the implemented rt forwarding equation.
    check_forwardB_equation: assert property (
        @($global_clock) forwardB == ((rt_from_mem | rt_from_ex) ? 2'b10 : 2'b00)
    );

    // forwardA uses only the encodings produced by the RTL.
    check_forwardA_valid_encoding: assert property (
        @($global_clock) (forwardA == 2'b00) || (forwardA == 2'b10)
    );

    // forwardB uses only the encodings produced by the RTL.
    check_forwardB_valid_encoding: assert property (
        @($global_clock) (forwardB == 2'b00) || (forwardB == 2'b10)
    );

    // An EX/MEM rs match with write enable must drive forwardA active.
    check_forwardA_exmem_match_sets_forward: assert property (
        @($global_clock) rs_from_ex |-> (forwardA == 2'b10)
    );

    // A MEM/WB rs match with write enable must drive forwardA active.
    check_forwardA_memwb_match_sets_forward: assert property (
        @($global_clock) rs_from_mem |-> (forwardA == 2'b10)
    );

    // With no rs match from either stage, forwardA must be inactive.
    check_forwardA_no_match_clears_forward: assert property (
        @($global_clock) !(rs_from_mem | rs_from_ex) |-> (forwardA == 2'b00)
    );

    // An EX/MEM rt match with write enable must drive forwardB active.
    check_forwardB_exmem_match_sets_forward: assert property (
        @($global_clock) rt_from_ex |-> (forwardB == 2'b10)
    );

    // A MEM/WB rt match with write enable must drive forwardB active.
    check_forwardB_memwb_match_sets_forward: assert property (
        @($global_clock) rt_from_mem |-> (forwardB == 2'b10)
    );

    // With no rt match from either stage, forwardB must be inactive.
    check_forwardB_no_match_clears_forward: assert property (
        @($global_clock) !(rt_from_mem | rt_from_ex) |-> (forwardB == 2'b00)
    );

endmodule

