module dff_64 ( clk, d, rst, q );

    input clk, rst;
    input [63:0] d;
    output [63:0] q;
    reg [63:0] q;

    always @(posedge clk or negedge rst) begin
        if (rst == 0) begin
            q <= 0;
        end else begin
            q <= d;
        end
    end

endmodule

sva:
module dff_64_sva (
    input logic        clk,
    input logic        rst,
    input logic [63:0] d,
    input logic [63:0] q
);

    // Sampled active-low reset keeps q cleared.
    check_reset_forces_zero: assert property (
        @(posedge clk) disable iff ($initstate)
            !rst |-> (q == 64'b0)
    );

    // The first clock after a sampled reset still sees q cleared.
    check_post_reset_zero: assert property (
        @(posedge clk) disable iff (!rst || $initstate)
            $past(!rst) |-> (q == 64'b0)
    );

    // A previously sampled zero input must produce a zero output.
    check_zero_data_captures_zero: assert property (
        @(posedge clk) disable iff (!rst || $initstate)
            ($past(rst) && ($past(d) == 64'b0)) |-> (q == 64'b0)
    );

    // Out of reset, q is either cleared by reset or equal to the prior d.
    check_q_is_zero_or_prior_d: assert property (
        @(posedge clk) disable iff (!rst || $initstate)
            ((q == 64'b0) || (q == $past(d)))
    );

    // Any nonzero q value must match the previously sampled d.
    check_nonzero_q_matches_prior_d: assert property (
        @(posedge clk) disable iff (!rst || $initstate)
            (q != 64'b0) |-> (q == $past(d))
    );

    // Any nonzero q value implies reset was high on the prior sample.
    check_nonzero_q_requires_prior_rst_high: assert property (
        @(posedge clk) disable iff (!rst || $initstate)
            (q != 64'b0) |-> $past(rst)
    );

endmodule

rtl:
module transition_detector (
    input clk,
    input reset,
    input [31:0] in,
    output reg [31:0] out
);

reg [31:0] prev_in;

always @(posedge clk) begin
    if (reset) begin
        out <= 0;
        prev_in <= 0;
    end else begin
        if (in != prev_in) begin
            out <= out | (~in & prev_in);
        end
        prev_in <= in;
    end
end

endmodule

module shift_register (
    input clk,
    input reset,
    input [31:0] in,
    output reg [31:0] q
);

reg [2:0] counter;

always @(posedge clk) begin
    if (reset) begin
        q <= 0;
        counter <= 0;
    end else begin
        q <= {q[30:0], in};
        counter <= counter + 1;
        if (counter == 3) begin
            counter <= 0;
        end
    end
end

endmodule

module or_module (
    input [31:0] in1,
    input [31:0] in2,
    output reg [31:0] out
);

always @(*) begin
    out = in1 | in2;
end

endmodule

module top_module (
    input clk,
    input reset,
    input [31:0] in,
    output [31:0] out
);

wire [31:0] trans_out;
wire [31:0] shift_out;

transition_detector trans_detector (
    .clk(clk),
    .reset(reset),
    .in(in),
    .out(trans_out)
);

shift_register shift_reg (
    .clk(clk),
    .reset(reset),
    .in(trans_out),
    .q(shift_out)
);

or_module or_gate (
    .in1(trans_out),
    .in2(shift_out),
    .out(out)
);

endmodule

sva:
module top_module_sva (
    input logic        clk,
    input logic        reset,
    input logic [31:0] in,
    input logic [31:0] out,
    input logic [31:0] trans_out,
    input logic [31:0] shift_out
);

    // Reset clears the sequential outputs on the next clock.
    check_reset_clears_outputs: assert property (
        @(posedge clk)
        reset |=> (trans_out == 32'h00000000 && shift_out == 32'h00000000 && out == 32'h00000000)
    );

    // The top-level output is the OR of the two internal paths.
    check_or_output_function: assert property (
        @(posedge clk) disable iff (reset)
        out == (trans_out | shift_out)
    );

    // The shift-register output matches the prior transition-detector output.
    check_shift_out_tracks_prev_trans_out: assert property (
        @(posedge clk) disable iff (reset)
        $past(!reset) |-> (shift_out == $past(trans_out))
    );

    // The transition detector accumulates prior-cycle 1->0 transitions on in.
    check_trans_out_update: assert property (
        @(posedge clk) disable iff (reset)
        ($past(!reset) && $past(!reset, 2)) |-> (trans_out == ($past(trans_out) | ($past(in, 2) & ~$past(in))))
    );

    // Once set, transition-detector bits do not clear until reset.
    check_trans_out_monotonic: assert property (
        @(posedge clk) disable iff (reset)
        $past(!reset) |-> (($past(trans_out) & ~trans_out) == 32'h00000000)
    );

    // Any prior-cycle falling input bit must be reflected in trans_out.
    check_falling_bits_captured: assert property (
        @(posedge clk) disable iff (reset)
        ($past(!reset) && $past(!reset, 2)) |-> ((trans_out & ($past(in, 2) & ~$past(in))) == ($past(in, 2) & ~$past(in)))
    );

    // After a non-reset cycle, the OR stage adds no bits beyond trans_out.
    check_out_matches_trans_out: assert property (
        @(posedge clk) disable iff (reset)
        $past(!reset) |-> (out == trans_out)
    );

endmodule

bind top_module top_module_sva top_module_sva_inst (
    .clk(clk),
    .reset(reset),
    .in(in),
    .out(out),
    .trans_out(trans_out),
    .shift_out(shift_out)
);

module decoder_sva (
    input logic [3:0] in,
    input logic enable,
    input logic [2:0] select,
    input logic [15:0] out
);

    // Output is zero when the decoder is disabled.
    check_disable_forces_zero: assert property (
        @($global_clock) (enable == 1'b0) |-> (out == 16'h0000)
    );

    // Upper output bits are always zero.
    check_upper_bits_zero: assert property (
        @($global_clock) (out[15:8] == 8'h00)
    );

    // Select 000 drives bit 0 when enabled.
    check_select_000_decodes_bit0: assert property (
        @($global_clock) (enable == 1'b1 && select == 3'b000) |-> (out == 16'h0001)
    );

    // Select 001 drives bit 1 when enabled.
    check_select_001_decodes_bit1: assert property (
        @($global_clock) (enable == 1'b1 && select == 3'b001) |-> (out == 16'h0002)
    );

    // Select 010 drives bit 2 when enabled.
    check_select_010_decodes_bit2: assert property (
        @($global_clock) (enable == 1'b1 && select == 3'b010) |-> (out == 16'h0004)
    );

    // Select 011 drives bit 3 when enabled.
    check_select_011_decodes_bit3: assert property (
        @($global_clock) (enable == 1'b1 && select == 3'b011) |-> (out == 16'h0008)
    );

    // Select 100 drives bit 4 when enabled.
    check_select_100_decodes_bit4: assert property (
        @($global_clock) (enable == 1'b1 && select == 3'b100) |-> (out == 16'h0010)
    );

    // Select 101 drives bit 5 when enabled.
    check_select_101_decodes_bit5: assert property (
        @($global_clock) (enable == 1'b1 && select == 3'b101) |-> (out == 16'h0020)
    );

    // Select 110 drives bit 6 when enabled.
    check_select_110_decodes_bit6: assert property (
        @($global_clock) (enable == 1'b1 && select == 3'b110) |-> (out == 16'h0040)
    );

    // Select 111 drives bit 7 when enabled.
    check_select_111_decodes_bit7: assert property (
        @($global_clock) (enable == 1'b1 && select == 3'b111) |-> (out == 16'h0080)
    );

endmodule

rtl:
module calculator (
    A,
    B,
    OPCODE,
    RESET,
    RESULT
);

    input [31:0] A;
    input [31:0] B;
    input [1:0] OPCODE;
    input RESET;
    output [31:0] RESULT;

    reg [31:0] result;

    always @(*) begin
        case(OPCODE)
            2'b00: result = A + B; // addition
            2'b01: result = A - B; // subtraction
            2'b10: result = A * B; // multiplication
            2'b11: result = A / B; // division
            default: result = 0; // default case
        endcase

        if(RESET) begin
            result = 0; // reset result to 0
        end
    end

    assign RESULT = result;

endmodule

sva:
module calculator_sva (
    input logic        clk,
    input logic [31:0] A,
    input logic [31:0] B,
    input logic [1:0]  OPCODE,
    input logic        RESET,
    input logic [31:0] RESULT
);

    // Reset forces the output to zero.
    check_reset_forces_zero: assert property (
        @(posedge clk) RESET |-> (RESULT == 32'd0)
    );

    // Opcode 00 selects addition.
    check_add_operation: assert property (
        @(posedge clk) disable iff (RESET)
        (OPCODE == 2'b00) |-> (RESULT == (A + B))
    );

    // Opcode 01 selects subtraction.
    check_sub_operation: assert property (
        @(posedge clk) disable iff (RESET)
        (OPCODE == 2'b01) |-> (RESULT == (A - B))
    );

    // Opcode 10 selects multiplication.
    check_mul_operation: assert property (
        @(posedge clk) disable iff (RESET)
        (OPCODE == 2'b10) |-> (RESULT == (A * B))
    );

    // Opcode 11 selects division when the divisor is nonzero.
    check_div_operation: assert property (
        @(posedge clk) disable iff (RESET)
        ((OPCODE == 2'b11) && (B != 32'd0)) |-> (RESULT == (A / B))
    );

endmodule

rtl:
module signal_combiner (
    input A1,
    input A2,
    input A3,
    input B1,
    input C1,
    output Y
);

    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    assign Y = (A1) ? 1 : ((A2) ? B1 : ((A3) ? C1 : 0));

endmodule

sva:
module signal_combiner_sva (
    input logic A1,
    input logic A2,
    input logic A3,
    input logic B1,
    input logic C1,
    input logic Y
);

    // Y must match the implemented priority-combine equation.
    check_y_equation: assert property (
        @($global_clock)
        Y == (A1 ? 1'b1 : (A2 ? B1 : (A3 ? C1 : 1'b0)))
    );

    // A1 has highest priority and forces Y high.
    check_a1_priority: assert property (
        @($global_clock)
        A1 |-> (Y == 1'b1)
    );

    // With A1 low, A2 selects B1 onto Y.
    check_a2_selects_b1: assert property (
        @($global_clock)
        (!A1 && A2) |-> (Y == B1)
    );

    // With A1 and A2 low, A3 selects C1 onto Y.
    check_a3_selects_c1: assert property (
        @($global_clock)
        (!A1 && !A2 && A3) |-> (Y == C1)
    );

    // With all select inputs low, Y must be low.
    check_default_zero: assert property (
        @($global_clock)
        (!A1 && !A2 && !A3) |-> (Y == 1'b0)
    );

endmodule

rtl:
module sdram_init (
    input       sdram_clk,
    input       sdram_rst_,
    output  reg PAA = 0,
    output  reg SET_MODE
);

parameter
    INIT_CNT        = 16'h4000,
    INIT_HALF_CNT   = INIT_CNT >> 1;


reg     [15:0]  init_counter;
wire    init_counter_done;
assign init_counter_done = (init_counter == INIT_CNT);
always @(posedge sdram_clk) begin
    if (!sdram_rst_)
        init_counter <= 'b0;
    else if (!init_counter_done)
        init_counter <= init_counter + 1'b1;
end

always @(posedge sdram_clk) begin
        PAA <= init_counter_done;
end        

always @(posedge sdram_clk) begin
        SET_MODE <= 1'b1;
end


endmodule

sva:
module sdram_init_sva #(
    parameter INIT_CNT = 16'h4000
) (
    input logic        sdram_clk,
    input logic        sdram_rst_,
    input logic        PAA,
    input logic        SET_MODE,
    input logic [15:0] init_counter,
    input logic        init_counter_done
);

    localparam [15:0] INIT_CNT_MINUS_ONE = INIT_CNT - 16'd1;

    // init_counter_done matches the terminal-count compare.
    check_done_flag_definition: assert property (
        @(posedge sdram_clk) disable iff (!sdram_rst_)
        (init_counter_done == (init_counter == INIT_CNT))
    );

    // A reset clock clears the counter to zero.
    check_counter_resets_to_zero: assert property (
        @(posedge sdram_clk)
        (!sdram_rst_) |=> (init_counter == 16'h0000)
    );

    // The counter increments by one while not done.
    check_counter_increments_before_done: assert property (
        @(posedge sdram_clk) disable iff (!sdram_rst_)
        (!init_counter_done) |=> (init_counter == ($past(init_counter) + 16'd1))
    );

    // The counter stops changing once done is high.
    check_counter_holds_when_done: assert property (
        @(posedge sdram_clk) disable iff (!sdram_rst_)
        init_counter_done |=> (init_counter == $past(init_counter))
    );

    // INIT_CNT-1 advances to the done condition on the next cycle.
    check_done_after_penultimate_count: assert property (
        @(posedge sdram_clk) disable iff (!sdram_rst_)
        (init_counter == INIT_CNT_MINUS_ONE) |=> init_counter_done
    );

    // PAA stays low when done was low on the prior clock.
    check_paa_low_after_not_done: assert property (
        @(posedge sdram_clk) disable iff (!sdram_rst_)
        (!init_counter_done) |=> (!PAA)
    );

    // PAA goes high when done was high on the prior clock.
    check_paa_high_after_done: assert property (
        @(posedge sdram_clk) disable iff (!sdram_rst_)
        init_counter_done |=> PAA
    );

    // SET_MODE is driven high after every clock edge.
    check_set_mode_driven_high: assert property (
        @(posedge sdram_clk)
        1'b1 |=> (SET_MODE == 1'b1)
    );

endmodule

bind sdram_init sdram_init_sva #(
    .INIT_CNT(INIT_CNT)
) sdram_init_sva_inst (
    .sdram_clk(sdram_clk),
    .sdram_rst_(sdram_rst_),
    .PAA(PAA),
    .SET_MODE(SET_MODE),
    .init_counter(init_counter),
    .init_counter_done(init_counter_done)
);

rtl:
module full_adder (
    input A,
    input B,
    input Cin,
    output Sum,
    output Cout
);
    assign {Cout, Sum} = A + B + Cin;
endmodule

module ripple_adder (
    input [3:0] A,
    input [3:0] B,
    output [3:0] C
);

    wire [3:0] sum;
    wire [3:0] carry;

    full_adder fa0(A[0], B[0], 1'b0, sum[0], carry[0]);
    full_adder fa1(A[1], B[1], carry[0], sum[1], carry[1]);
    full_adder fa2(A[2], B[2], carry[1], sum[2], carry[2]);
    full_adder fa3(A[3], B[3], carry[2], sum[3], carry[3]);

    assign C = sum;

endmodule

module mux (
    input [3:0] in0,
    input [3:0] in1,
    input [3:0] in2,
    input [3:0] in3,
    input [1:0] sel,
    output reg [3:0] out
);

    always @(*) begin
        case (sel)
            2'b00: out = in0;
            2'b01: out = in1;
            2'b10: out = in2;
            2'b11: out = in3;
        endcase
    end

endmodule

module and_gate (
    input [3:0] in1,
    input [3:0] in2,
    output [3:0] out
);

    assign out = in1 & in2;

endmodule

module top_module (
    input [3:0] A,
    input [3:0] B,
    input [3:0] in0,
    input [3:0] in1,
    input [3:0] in2,
    input [3:0] in3,
    input [1:0] sel,
    output [3:0] out
);

    wire [3:0] adder_out;
    wire [3:0] mux_out;

    ripple_adder adder(A, B, adder_out);
    mux mux_inst(in0, in1, in2, in3, sel, mux_out);
    and_gate and_gate_inst(adder_out, mux_out, out);

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] in0,
    input logic [3:0] in1,
    input logic [3:0] in2,
    input logic [3:0] in3,
    input logic [1:0] sel,
    input logic [3:0] out
);

    // Top output must equal the truncated sum masked by the selected mux input.
    check_out_matches_selected_sum: assert property (
        @(posedge clk)
        out == ((({1'b0, A} + {1'b0, B})[3:0]) &
                ((sel == 2'b00) ? in0 :
                 ((sel == 2'b01) ? in1 :
                  ((sel == 2'b10) ? in2 : in3))))
    );

    // sel=00 must route in0 through the final AND with the adder result.
    check_sel0_uses_in0: assert property (
        @(posedge clk)
        (sel == 2'b00) |-> (out == ((({1'b0, A} + {1'b0, B})[3:0]) & in0))
    );

    // sel=01 must route in1 through the final AND with the adder result.
    check_sel1_uses_in1: assert property (
        @(posedge clk)
        (sel == 2'b01) |-> (out == ((({1'b0, A} + {1'b0, B})[3:0]) & in1))
    );

    // sel=10 must route in2 through the final AND with the adder result.
    check_sel2_uses_in2: assert property (
        @(posedge clk)
        (sel == 2'b10) |-> (out == ((({1'b0, A} + {1'b0, B})[3:0]) & in2))
    );

    // sel=11 must route in3 through the final AND with the adder result.
    check_sel3_uses_in3: assert property (
        @(posedge clk)
        (sel == 2'b11) |-> (out == ((({1'b0, A} + {1'b0, B})[3:0]) & in3))
    );

    // A zero selected mux input must force the output low.
    check_zero_selected_input_forces_zero_out: assert property (
        @(posedge clk)
        (((sel == 2'b00) ? in0 :
          ((sel == 2'b01) ? in1 :
           ((sel == 2'b10) ? in2 : in3))) == 4'b0000) |-> (out == 4'b0000)
    );

    // A zero low-order adder sum must force the output low.
    check_zero_sum_forces_zero_out: assert property (
        @(posedge clk)
        ((({1'b0, A} + {1'b0, B})[3:0]) == 4'b0000) |-> (out == 4'b0000)
    );

    // An all-ones selected mux input must pass the low-order adder sum unchanged.
    check_all_ones_selected_input_passes_sum: assert property (
        @(posedge clk)
        (((sel == 2'b00) ? in0 :
          ((sel == 2'b01) ? in1 :
           ((sel == 2'b10) ? in2 : in3))) == 4'b1111)
        |-> (out == (({1'b0, A} + {1'b0, B})[3:0]))
    );

    // Output bits can only be high where the selected mux input is high.
    check_out_is_masked_by_selected_input: assert property (
        @(posedge clk)
        (out & ~((sel == 2'b00) ? in0 :
                 ((sel == 2'b01) ? in1 :
                  ((sel == 2'b10) ? in2 : in3)))) == 4'b0000
    );

    // Output bits can only be high where the low-order adder sum is high.
    check_out_is_masked_by_sum: assert property (
        @(posedge clk)
        (out & ~((({1'b0, A} + {1'b0, B})[3:0]))) == 4'b0000
    );

endmodule

rtl:
module shift_add(
  input [15:0] a,
  output [15:0] y
);

  assign y = a + (a >> 2);

endmodule

sva:
module shift_add_sva (
    input logic        clk,
    input logic [15:0] a,
    input logic [15:0] y
);

    // y must equal a plus a shifted right by two.
    check_shift_add_function: assert property (
        @(posedge clk) y == (a + (a >> 2))
    );

    // Zero input must produce zero output.
    check_zero_input: assert property (
        @(posedge clk) (a == 16'h0000) |-> (y == 16'h0000)
    );

    // Inputs below four are unchanged because a>>2 is zero.
    check_small_input_identity: assert property (
        @(posedge clk) (a <= 16'd3) |-> (y == a)
    );

    // Up to 16'hCCCC, the 16-bit sum does not wrap and cannot be less than a.
    check_nonoverflow_region_ge_input: assert property (
        @(posedge clk) (a <= 16'hCCCC) |-> (y >= a)
    );

    // From 16'hCCCD upward, the 16-bit sum wraps and becomes less than a.
    check_overflow_region_lt_input: assert property (
        @(posedge clk) (a >= 16'hCCCD) |-> (y < a)
    );

    // The largest non-overflowing input produces all ones.
    check_max_nonoverflow_case: assert property (
        @(posedge clk) (a == 16'hCCCC) |-> (y == 16'hFFFF)
    );

