module logic_function ( A, B, Ci, S, Co );
  input A, B, Ci;
  output S, Co;
  wire   n1, n2, n3, n4, n5, n6, n7, n8, n9, n10;

  xor ( n1, A, B );
  xor ( S, n1, Ci );
  and ( n2, A, B );
  and ( n3, n2, Ci );
  not ( n4, A );
  not ( n5, B );
  and ( n6, n4, n5 );
  and ( n7, n6, Ci );
  and ( n8, n4, B );
  and ( n9, A, n5 );
  and ( n10, n8, n9 );
  or ( Co, n3, n7, n10 );
endmodule

sva:
module logic_function_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic Ci,
    input logic S,
    input logic Co
);

    // Sum output matches the XOR of A, B, and Ci.
    check_sum_function: assert property (
        @(posedge clk) S == (A ^ B ^ Ci)
    );

    // Carry output matches Ci gated by A and B being equal.
    check_carry_function: assert property (
        @(posedge clk) Co == (Ci & ~(A ^ B))
    );

    // Carry must be LOW whenever carry-in is LOW.
    check_carry_requires_ci: assert property (
        @(posedge clk) !Ci |-> !Co
    );

    // Carry must be LOW whenever A and B differ.
    check_carry_low_when_inputs_differ: assert property (
        @(posedge clk) (A ^ B) |-> !Co
    );

    // Carry follows Ci whenever A and B are equal.
    check_carry_follows_ci_when_inputs_equal: assert property (
        @(posedge clk) (A == B) |-> (Co == Ci)
    );

    // Sum follows Ci whenever A and B are equal.
    check_sum_follows_ci_when_inputs_equal: assert property (
        @(posedge clk) (A == B) |-> (S == Ci)
    );

    // Sum is the inverse of Ci whenever A and B differ.
    check_sum_inverts_ci_when_inputs_differ: assert property (
        @(posedge clk) (A != B) |-> (S == ~Ci)
    );

endmodule

rtl:
module add_sub (
    input [3:0] A,
    input [3:0] B,
    input SUB,
    output [3:0] result,
    output carry
);
    assign result = SUB ? A - B : A + B;
    assign carry = SUB ? A < B : 0;
endmodule
module multiplier (
    input [7:0] a,
    input [7:0] b,
    output [15:0] result
);
    assign result = a * b;
endmodule
module functional_module (
    input [3:0] add_sub_result,
    input [15:0] multiplier_result,
    input select,
    output [15:0] result
);
    assign result = select ? multiplier_result : {12'b0, add_sub_result};
endmodule
module top_module (
    input clk,
    input reset,
    input [3:0] A,
    input [3:0] B,
    input [7:0] a,
    input [7:0] b,
    input select,
    output [15:0] result
);
    wire [3:0] add_sub_result;
    wire carry;
    add_sub add_sub_inst (
        .A(A),
        .B(B),
        .SUB(select),
        .result(add_sub_result),
        .carry(carry)
    );
    wire [15:0] multiplier_result;
    multiplier multiplier_inst (
        .a(a),
        .b(b),
        .result(multiplier_result)
    );
    functional_module functional_inst (
        .add_sub_result(add_sub_result),
        .multiplier_result(multiplier_result),
        .select(select),
        .result(result)
    );
endmodule

sva:
module top_module_sva (
    input logic        clk,
    input logic        reset,
    input logic [3:0]  A,
    input logic [3:0]  B,
    input logic [7:0]  a,
    input logic [7:0]  b,
    input logic        select,
    input logic [15:0] result
);

    // Multiplier path drives the output when select is high.
    check_multiplier_selected: assert property (
        @(posedge clk) disable iff (reset)
        select |-> (result == (a * b))
    );

    // Add path drives the output when select is low.
    check_add_selected: assert property (
        @(posedge clk) disable iff (reset)
        !select |-> (result == {12'b0, (A + B)})
    );

    // Add path zero-extends the 4-bit add/sub result.
    check_add_zero_extended: assert property (
        @(posedge clk) disable iff (reset)
        !select |-> (result[15:4] == 12'b0)
    );

    // Add path low nibble matches the 4-bit sum.
    check_add_low_nibble: assert property (
        @(posedge clk) disable iff (reset)
        !select |-> (result[3:0] == (A + B))
    );

    // A rising select switches the observed output to the multiplier path.
    check_select_rise_multiplier: assert property (
        @(posedge clk) disable iff (reset)
        $rose(select) |-> (result == (a * b))
    );

    // A falling select switches the observed output to the add path.
    check_select_fall_add: assert property (
        @(posedge clk) disable iff (reset)
        $fell(select) |-> (result == {12'b0, (A + B)})
    );

    // Multiplier input changes do not affect result while add path stays selected.
    check_add_path_ignores_multiplier_inputs: assert property (
        @(posedge clk) disable iff (reset)
        (!select && $stable(select) && $stable(A) && $stable(B) &&
         (!$stable(a) || !$stable(b))) |-> $stable(result)
    );

    // Add input changes do not affect result while multiplier path stays selected.
    check_multiplier_path_ignores_add_inputs: assert property (
        @(posedge clk) disable iff (reset)
        (select && $stable(select) && $stable(a) && $stable(b) &&
         (!$stable(A) || !$stable(B))) |-> $stable(result)
    );

endmodule

rtl:
module binary_counter
#(
    parameter WIDTH = 4
)
(
    input clk,
    input rst,
    input en,
    input load,
    input [WIDTH-1:0] data,
    output [WIDTH-1:0] count,
    output max_flag
);

    reg [WIDTH-1:0] counter;

    assign max_flag = (counter == {WIDTH{1'b1}});

    always @(posedge clk or negedge rst) begin
        if (!rst) begin
            counter <= 0;
        end else if (load) begin
            counter <= data;
        end else if (en) begin
            counter <= counter + 1;
        end
    end

    assign count = counter;

endmodule

sva:
module binary_counter_sva
#(
    parameter WIDTH = 4
)
(
    input logic clk,
    input logic rst,
    input logic en,
    input logic load,
    input logic [WIDTH-1:0] data,
    input logic [WIDTH-1:0] count,
    input logic max_flag
);

    // Reset clears the count and deasserts max_flag.
    check_reset_clears_outputs: assert property (
        @(posedge clk)
        !rst |-> ((count == {WIDTH{1'b0}}) && (max_flag == 1'b0))
    );

    // max_flag must match whether count is all ones.
    check_max_flag_matches_count: assert property (
        @(posedge clk) disable iff (!rst)
        (max_flag == (count == {WIDTH{1'b1}}))
    );

    // load updates count with data on the next cycle.
    check_load_updates_count: assert property (
        @(posedge clk) disable iff (!rst)
        load |=> (count == $past(data))
    );

    // load determines max_flag from the loaded data on the next cycle.
    check_load_updates_max_flag: assert property (
        @(posedge clk) disable iff (!rst)
        load |=> (max_flag == ($past(data) == {WIDTH{1'b1}}))
    );

    // load has priority over enable when both are asserted.
    check_load_priority_over_enable: assert property (
        @(posedge clk) disable iff (!rst)
        (load && en) |=> (count == $past(data))
    );

    // enable increments count when load is low.
    check_enable_increments_count: assert property (
        @(posedge clk) disable iff (!rst)
        (en && !load) |=> (count == ($past(count) + 1'b1))
    );

    // Incrementing from the maximum value wraps count to zero.
    check_enable_wraps_from_max: assert property (
        @(posedge clk) disable iff (!rst)
        (en && !load && (count == {WIDTH{1'b1}})) |=> ((count == {WIDTH{1'b0}}) && (max_flag == 1'b0))
    );

    // Without load or enable, count holds its value.
    check_idle_holds_count: assert property (
        @(posedge clk) disable iff (!rst)
        (!load && !en) |=> (count == $past(count))
    );

endmodule

module binary_up_counter_sva (
    input logic       clk,
    input logic       reset,
    input logic       enable,
    input logic [3:0] count
);

    // Reset clears the counter to zero on the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'h0)
    );

    // When disabled without reset, the counter holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset)
        (!enable) |=> (count == $past(count))
    );

    // When enabled below max, the counter increments by one.
    check_increment_when_enabled: assert property (
        @(posedge clk) disable iff (reset)
        (enable && (count != 4'hF)) |=> (count == ($past(count) + 4'h1))
    );

    // When enabled at max, the counter wraps back to zero.
    check_wrap_when_max: assert property (
        @(posedge clk) disable iff (reset)
        (enable && (count == 4'hF)) |=> (count == 4'h0)
    );

endmodule

rtl:
module calculator(
    input  [31:0] a,
    input  [31:0] b,
    input  reset_n,
    output  reg [31:0] add,
    output  reg [31:0] sub,
    output  reg [31:0] mul,
    output  reg [31:0] div
);

    always @(a, b, reset_n) begin
        if(!reset_n) begin
            add <= 0;
            sub <= 0;
            mul <= 0;
            div <= 0;
        end else begin
            add <= a + b;
            sub <= a - b;
            mul <= a * b;
            if(b != 0) begin
                div <= a / b;
            end else begin
                div <= 0;
            end
        end
    end

endmodule

sva:
module calculator_sva (
    input logic        clk,
    input logic [31:0] a,
    input logic [31:0] b,
    input logic        reset_n,
    input logic [31:0] add,
    input logic [31:0] sub,
    input logic [31:0] mul,
    input logic [31:0] div
);

    // External sampling clock; DUT logic is combinational with active-low reset_n.

    // Active-low reset forces all outputs to zero.
    check_reset_clears_outputs: assert property (
        @(posedge clk)
        (!reset_n) |-> ((add == 32'd0) && (sub == 32'd0) && (mul == 32'd0) && (div == 32'd0))
    );

    // add must match the sum of a and b outside reset.
    check_add_matches_sum: assert property (
        @(posedge clk) disable iff (!reset_n)
        (add == (a + b))
    );

    // sub must match the difference of a and b outside reset.
    check_sub_matches_difference: assert property (
        @(posedge clk) disable iff (!reset_n)
        (sub == (a - b))
    );

    // mul must match the low 32 bits of the product outside reset.
    check_mul_matches_product: assert property (
        @(posedge clk) disable iff (!reset_n)
        (mul == ((a * b) & 64'h0000_0000_FFFF_FFFF))
    );

    // div must match a / b when the divisor is nonzero.
    check_div_matches_quotient: assert property (
        @(posedge clk) disable iff (!reset_n)
        (b != 32'd0) |-> (div == (a / b))
    );

    // div must be zero when the divisor is zero.
    check_div_zero_on_zero_divisor: assert property (
        @(posedge clk) disable iff (!reset_n)
        (b == 32'd0) |-> (div == 32'd0)
    );

    // Stable inputs keep all outputs stable outside reset.
    check_outputs_stable_when_inputs_stable: assert property (
        @(posedge clk) disable iff (!reset_n)
        ($stable({a, b})) |-> ($stable({add, sub, mul, div}))
    );

endmodule

