module addsub_8bit(A, B, op, sum, carry_out);

input [7:0] A;
input [7:0] B;
input op;
output [7:0] sum;
output carry_out;

wire [7:0] twos_comp_B;
wire [7:0] temp_sum;

assign carry_out = 1'b0;
assign twos_comp_B = ~B + 1;

addsub_1bit addsub_inst_0(A[0], twos_comp_B[0], op, temp_sum[0]);
addsub_1bit addsub_inst_1(A[1], twos_comp_B[1], op, temp_sum[1]);
addsub_1bit addsub_inst_2(A[2], twos_comp_B[2], op, temp_sum[2]);
addsub_1bit addsub_inst_3(A[3], twos_comp_B[3], op, temp_sum[3]);
addsub_1bit addsub_inst_4(A[4], twos_comp_B[4], op, temp_sum[4]);
addsub_1bit addsub_inst_5(A[5], twos_comp_B[5], op, temp_sum[5]);
addsub_1bit addsub_inst_6(A[6], twos_comp_B[6], op, temp_sum[6]);
addsub_1bit addsub_inst_7(A[7], twos_comp_B[7], op, temp_sum[7]);

assign sum = op ? twos_comp_B : temp_sum;

endmodule
module addsub_1bit(A, B, op, sum);

input A;
input B;
input op;
output sum;

assign sum = A ^ B ^ op;

endmodule

sva:
module addsub_8bit_sva (
    input logic [7:0] A,
    input logic [7:0] B,
    input logic       op,
    input logic [7:0] sum,
    input logic       carry_out
);

    // carry_out is hard-wired low.
    check_carry_out_tied_low: assert property (
        @($global_clock) disable iff (1'b0)
        carry_out == 1'b0
    );

    // sum follows the top-level conditional expression.
    check_sum_matches_top_level_function: assert property (
        @($global_clock) disable iff (1'b0)
        sum == (op ? ((~B) + 8'h01) : (A ^ ((~B) + 8'h01)))
    );

    // op high selects the two's complement of B.
    check_sum_equals_twos_comp_b_when_op_high: assert property (
        @($global_clock) disable iff (1'b0)
        (op == 1'b1) |-> (sum == ((~B) + 8'h01))
    );

    // op low selects the XOR path with A and two's complement of B.
    check_sum_equals_xor_path_when_op_low: assert property (
        @($global_clock) disable iff (1'b0)
        (op == 1'b0) |-> (sum == (A ^ ((~B) + 8'h01)))
    );

    // With B equal to zero, op high produces zero.
    check_zero_b_gives_zero_when_op_high: assert property (
        @($global_clock) disable iff (1'b0)
        ((op == 1'b1) && (B == 8'h00)) |-> (sum == 8'h00)
    );

    // With B equal to zero, op low passes A through.
    check_zero_b_passes_a_when_op_low: assert property (
        @($global_clock) disable iff (1'b0)
        ((op == 1'b0) && (B == 8'h00)) |-> (sum == A)
    );

    // With A equal to zero, op low reduces to two's complement of B.
    check_zero_a_reduces_to_twos_comp_b_when_op_low: assert property (
        @($global_clock) disable iff (1'b0)
        ((op == 1'b0) && (A == 8'h00)) |-> (sum == ((~B) + 8'h01))
    );

endmodule

rtl:
module adder (
    input [7:0] a,
    input [7:0] b,
    output [7:0] s,
    output carry_out
);

wire [7:0] sum1, sum2;
wire carry1, carry2;

assign {carry1, sum1} = a + b;
assign {carry2, sum2} = a + ~b + 1;

assign s = carry1 ? sum2 : sum1;
assign carry_out = carry1 ^ (a[7] ^ b[7]);

endmodule
module top_module (
    input [7:0] a,
    input [7:0] b,
    output [7:0] s,
    output overflow
);

wire [7:0] sum, sum1, sum2;
wire carry_out1, carry_out2;

adder adder1(
    .a(a),
    .b(b),
    .s(sum1),
    .carry_out(carry_out1)
);

adder adder2(
    .a(a),
    .b(~b + 1'b1),
    .s(sum2),
    .carry_out(carry_out2)
);

assign s = carry_out1 ? sum2 : sum1;
assign overflow = carry_out1 ^ carry_out2;

endmodule

sva:
module top_module_sva (
    input logic        clk,
    input logic [7:0]  a,
    input logic [7:0]  b,
    input logic [7:0]  s,
    input logic        overflow
);

    // No clock or reset exists in the RTL; clk only samples this combinational DUT.

    function automatic logic [7:0] neg8_fn(input logic [7:0] x);
        begin
            neg8_fn = ~x + 8'h01;
        end
    endfunction

    function automatic logic [7:0] adder_sum_fn(input logic [7:0] x, input logic [7:0] y);
        logic [8:0] add_res;
        logic [8:0] sub_res;
        begin
            add_res = {1'b0, x} + {1'b0, y};
            sub_res = {1'b0, x} + {1'b0, ~y} + 9'h001;
            adder_sum_fn = add_res[8] ? sub_res[7:0] : add_res[7:0];
        end
    endfunction

    function automatic logic adder_carry_fn(input logic [7:0] x, input logic [7:0] y);
        logic [8:0] add_res;
        begin
            add_res = {1'b0, x} + {1'b0, y};
            adder_carry_fn = add_res[8] ^ (x[7] ^ y[7]);
        end
    endfunction

    function automatic logic [7:0] top_sum_fn(input logic [7:0] x, input logic [7:0] y);
        logic [7:0] y_neg;
        begin
            y_neg = neg8_fn(y);
            top_sum_fn = adder_carry_fn(x, y) ? adder_sum_fn(x, y_neg) : adder_sum_fn(x, y);
        end
    endfunction

    function automatic logic top_overflow_fn(input logic [7:0] x, input logic [7:0] y);
        logic [7:0] y_neg;
        begin
            y_neg = neg8_fn(y);
            top_overflow_fn = adder_carry_fn(x, y) ^ adder_carry_fn(x, y_neg);
        end
    endfunction

    // s must match the top-level select between the two adder outputs.
    check_sum_matches_top_logic: assert property (
        @(posedge clk) s == top_sum_fn(a, b)
    );

    // overflow must match the XOR of the two internal adder carry_out values.
    check_overflow_matches_top_logic: assert property (
        @(posedge clk) overflow == top_overflow_fn(a, b)
    );

    // When the first adder carry_out is low, top selects the first adder sum.
    check_select_sum1_when_first_carry_low: assert property (
        @(posedge clk) !adder_carry_fn(a, b) |-> s == adder_sum_fn(a, b)
    );

    // When the first adder carry_out is high, top selects the second adder sum.
    check_select_sum2_when_first_carry_high: assert property (
        @(posedge clk) adder_carry_fn(a, b) |-> s == adder_sum_fn(a, neg8_fn(b))
    );

    // Matching internal carry_out values force overflow low.
    check_overflow_low_when_carries_match: assert property (
        @(posedge clk) (adder_carry_fn(a, b) == adder_carry_fn(a, neg8_fn(b))) |-> !overflow
    );

    // Different internal carry_out values force overflow high.
    check_overflow_high_when_carries_differ: assert property (
        @(posedge clk) (adder_carry_fn(a, b) != adder_carry_fn(a, neg8_fn(b))) |-> overflow
    );

    // With b equal to zero, the design passes a through and does not overflow.
    check_zero_b_passthrough: assert property (
        @(posedge clk) (b == 8'h00) |-> (s == a && overflow == 1'b0)
    );

    // 8'h80 is self-negating, so both adder instances produce the same carry_out.
    check_self_negating_b_has_no_overflow: assert property (
        @(posedge clk) (b == 8'h80) |-> (s == adder_sum_fn(a, 8'h80) && overflow == 1'b0)
    );

    // Stable sampled inputs must keep the sampled outputs stable.
    check_outputs_stable_when_inputs_stable: assert property (
        @(posedge clk) ($stable(a) && $stable(b)) |-> ($stable(s) && $stable(overflow))
    );

endmodule

