module shift_register(
    input clk,
    input reset,
    input serial_in,
    output reg full,
    output [7:0] parallel_out
);

    reg serial_p;
    reg serial_s;
    reg [3:0] state;
    reg [8:0] shift;
    reg [10:0] count;

    assign parallel_out[7:0] = shift[7:0];

    always @(posedge clk) begin
        serial_p <= serial_in;
        serial_s <= serial_p;
    end

    always @(posedge clk) begin
        if (reset == 1) begin
            state <= 4'h0;
            full <= 0;
        end else begin
            if (state == 4'h0) begin
                full <= 0;
                if (serial_s == 0) begin
                    state <= 4'h1;
                    count <= 651;
                end
            end else if (state == 4'h1) begin
                if (count == 0) begin
                    state <= 4'h2;
                    shift[8:0] <= { serial_s, shift[8:1] };
                    count <= 1302;
                end else begin
                    count <= count - 1;
                end
            end else if (state == 4'h2) begin
                if (count == 0) begin
                    state <= 4'h3;
                    shift[8:0] <= { serial_s, shift[8:1] };
                    count <= 1302;
                end else begin
                    count <= count - 1;
                end
            end else if (state == 4'h3) begin
                if (count == 0) begin
                    state <= 4'h4;
                    shift[8:0] <= { serial_s, shift[8:1] };
                    count <= 1302;
                end else begin
                    count <= count - 1;
                end
            end else if (state == 4'h4) begin
                if (count == 0) begin
                    state <= 4'h5;
                    shift[8:0] <= { serial_s, shift[8:1] };
                    count <= 1302;
                end else begin
                    count <= count - 1;
                end
            end else if (state == 4'h5) begin
                if (count == 0) begin
                    state <= 4'h6;
                    shift[8:0] <= { serial_s, shift[8:1] };
                    count <= 1302;
                end else begin
                    count <= count - 1;
                end
            end else if (state == 4'h6) begin
                if (count == 0) begin
                    state <= 4'h7;
                    shift[8:0] <= { serial_s, shift[8:1] };
                    count <= 1302;
                end else begin
                    count <= count - 1;
                end
            end else if (state == 4'h7) begin
                if (count == 0) begin
                    state <= 4'h8;
                    shift[8:0] <= { serial_s, shift[8:1] };
                    count <= 1302;
                end else begin
                    count <= count - 1;
                end
            end else if (state == 4'h8) begin
                if (count == 0) begin
                    state <= 4'h9;
                    shift[8:0] <= { serial_s, shift[8:1] };
                    count <= 1302;
                end else begin
                    count <= count - 1;
                end
            end else if (state == 4'h9) begin
                if (count == 0) begin
                    state <= 4'ha;
                    shift[8:0] <= { serial_s, shift[8:1] };
                    count <= 1302;
                end else begin
                    count <= count - 1;
                end
            end else if (state == 4'ha) begin
                if (count == 0) begin
                    state <= 4'hb;
                    shift[8:0] <= { serial_s, shift[8:1] };
                    count <= 651;
                end else begin
                    count <= count - 1;
                end
            end else if (state == 4'hb) begin
                state <= 4'h0;
                full <= 1;
            end
        end
    end

endmodule

sva:
module shift_register_sva (
    input logic        clk,
    input logic        reset,
    input logic        serial_in,
    input logic        full,
    input logic [7:0]  parallel_out,
    input logic        serial_p,
    input logic        serial_s,
    input logic [3:0]  state,
    input logic [8:0]  shift,
    input logic [10:0] count
);

    // parallel_out reflects the low 8 bits of shift.
    check_parallel_out_mapping: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        parallel_out == shift[7:0]
    );

    // serial_p captures serial_in on each clock.
    check_serial_p_pipeline: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        serial_p == $past(serial_in)
    );

    // serial_s captures serial_p on each clock.
    check_serial_s_pipeline: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        serial_s == $past(serial_p)
    );

    // Synchronous reset returns to idle and clears full.
    check_reset_state_and_full: assert property (
        @(posedge clk)
        reset |=> (state == 4'h0 && full == 1'b0)
    );

    // Idle with a high sampled input stays in state 0 and keeps full low.
    check_idle_hold_without_start: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        (state == 4'h0 && serial_s == 1'b1) |=> (state == 4'h0 && full == 1'b0)
    );

    // Idle with a low sampled input starts the sequence and loads 651.
    check_idle_start_transition: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        (state == 4'h0 && serial_s == 1'b0) |=> (state == 4'h1 && count == 11'd651 && full == 1'b0)
    );

    // Active states hold state and decrement count while count is nonzero.
    check_active_count_decrement: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        ((state inside {4'h1,4'h2,4'h3,4'h4,4'h5,4'h6,4'h7,4'h8,4'h9,4'ha}) && (count != 11'd0))
        |=> (state == $past(state) && count == ($past(count) - 11'd1))
    );

    // Shift stays unchanged during active countdown cycles.
    check_shift_stable_while_counting: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        ((state inside {4'h1,4'h2,4'h3,4'h4,4'h5,4'h6,4'h7,4'h8,4'h9,4'ha}) && (count != 11'd0))
        |=> (shift == $past(shift))
    );

    // States 1 through 9 shift in serial_s and advance when count reaches zero.
    check_mid_state_shift_and_advance: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        ((state inside {4'h1,4'h2,4'h3,4'h4,4'h5,4'h6,4'h7,4'h8,4'h9}) && (count == 11'd0))
        |=> (state == ($past(state) + 4'h1) &&
             shift == { $past(serial_s), $past(shift[8:1]) } &&
             count == 11'd1302)
    );

    // State a performs the last shift and loads the final 651 count.
    check_last_shift_to_done: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        (state == 4'ha && count == 11'd0)
        |=> (state == 4'hb &&
             shift == { $past(serial_s), $past(shift[8:1]) } &&
             count == 11'd651)
    );

    // State b returns to idle and raises full.
    check_done_to_idle_with_full: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        (state == 4'hb) |=> (state == 4'h0 && full == 1'b1)
    );

endmodule

rtl:
module sm_clk_divider
#(
    parameter shift  = 16,
              bypass = 0
)
(
    input           clkIn,
    input           rst_n,
    input   [ 3:0 ] devide,
    input           enable,
    output          clkOut
);
    wire [31:0] cntr;
    wire [31:0] cntrNext = cntr + 1;
    sm_register_we r_cntr(clkIn, rst_n, enable, cntrNext, cntr);

    assign clkOut = bypass ? clkIn 
                           : cntr[shift + devide];
endmodule

module sm_register_we
(
    input clk,
    input reset_n,
    input we,
    input [31:0] d,
    output reg [31:0] q
);

    always @(posedge clk or negedge reset_n) begin
        if (~reset_n) begin
            q <= 0;
        end else if (we) begin
            q <= d;
        end
    end

endmodule

sva:
module sm_clk_divider_sva
#(
    parameter integer shift  = 16,
    parameter integer bypass = 0
)
(
    input logic         clkIn,
    input logic         rst_n,
    input logic [3:0]   devide,
    input logic         enable,
    input logic         clkOut,
    input logic [31:0]  cntr
);

    // Counter must be zero whenever reset is asserted.
    check_counter_zero_during_reset: assert property (
        @(posedge clkIn)
        !rst_n |-> (cntr == 32'd0)
    );

    // Enabled cycles increment the counter by one.
    check_counter_increments_when_enabled: assert property (
        @(posedge clkIn) disable iff (!rst_n)
        enable |=> (cntr == ($past(cntr) + 32'd1))
    );

    // Disabled cycles hold the counter value.
    check_counter_holds_when_disabled: assert property (
        @(posedge clkIn) disable iff (!rst_n)
        !enable |=> $stable(cntr)
    );

    generate
        if (bypass != 0) begin : gen_bypass_asserts
            // Bypass mode forwards clkIn to clkOut at the sampled edge.
            check_clkout_bypass_matches_clkin: assert property (
                @(posedge clkIn) disable iff (!rst_n)
                (clkOut == clkIn)
            );
        end else begin : gen_divide_asserts
            // Divide mode drives clkOut from the selected counter bit.
            check_clkout_matches_selected_counter_bit: assert property (
                @(posedge clkIn) disable iff (!rst_n)
                ((shift + devide) < 32) |-> (clkOut == cntr[shift + devide])
            );

            // Reset drives the divided output low for any valid selected bit.
            check_clkout_low_during_reset: assert property (
                @(posedge clkIn)
                (!rst_n && ((shift + devide) < 32)) |-> (clkOut == 1'b0)
            );

            // With no count update, a stable select keeps clkOut stable.
            check_clkout_holds_when_disabled_and_select_stable: assert property (
                @(posedge clkIn) disable iff (!rst_n)
                !enable |=> (!$stable(devide) || $stable(clkOut))
            );
        end
    endgenerate

