module divide_by12_sva (
    input logic [5:0] numer,
    input logic [2:0] quotient,
    input logic [3:0] remain
);

    // No RTL clock or reset; sample on the formal global clock.

    // Quotient matches division by 12.
    check_quotient_div12: assert property (
        @($global_clock) quotient == (numer / 6'd12)
    );

    // Remainder matches modulo 12.
    check_remain_mod12: assert property (
        @($global_clock) remain == (numer % 6'd12)
    );

    // Low remainder bits copy directly from the input.
    check_remain_low_bits_copy: assert property (
        @($global_clock) remain[1:0] == numer[1:0]
    );

    // High remainder bits equal the upper input bits modulo 3.
    check_remain_high_bits_mod3: assert property (
        @($global_clock) remain[3:2] == (numer[5:2] % 4'd3)
    );

    // Quotient equals the upper input bits divided by 3.
    check_quotient_upper_div3: assert property (
        @($global_clock) quotient == (numer[5:2] / 4'd3)
    );

    // Quotient stays within the implemented output range.
    check_quotient_range: assert property (
        @($global_clock) quotient <= 3'd5
    );

    // Upper remainder bits never exceed decimal 2.
    check_remain_high_range: assert property (
        @($global_clock) remain[3:2] <= 2'd2
    );

    // Quotient and remainder reconstruct the input.
    check_division_identity: assert property (
        @($global_clock) {1'b0, numer} == ((quotient * 4'd12) + remain)
    );

    // The lowest input value maps to zero quotient and remainder.
    check_zero_input_case: assert property (
        @($global_clock) (numer == 6'd0) |-> ((quotient == 3'd0) && (remain == 4'd0))
    );

    // The highest input value maps to quotient 5 and remainder 3.
    check_max_input_case: assert property (
        @($global_clock) (numer == 6'd63) |-> ((quotient == 3'd5) && (remain == 4'd3))
    );

endmodule

rtl:
module OverallController(Clock, IncrementData, LoadData, Reset, AddOne, WriteOrRead);
    input Clock, IncrementData, LoadData, Reset;
    output reg AddOne, WriteOrRead;
    parameter InitialState = 2'b00;
    parameter LoadState = 2'b01;
    parameter ReadState = 2'b10;
    parameter IncrementState = 2'b11;
    reg [2:0] State;
    reg [2:0] NextState;
    initial State = InitialState;
    initial NextState = InitialState;

    always @ (State)
        case (State)
            InitialState: begin AddOne <= 0; WriteOrRead <= 0; end
            LoadState: begin AddOne <= 0; WriteOrRead <= 1; end
            ReadState: begin AddOne <= 0; WriteOrRead <= 0; end
            IncrementState: begin AddOne <= 1; WriteOrRead <= 1; end
        endcase

    always @ (posedge Clock or posedge Reset)
        if (Reset == 1) State <= InitialState;
        else State <= NextState;

    always @ (State or IncrementData or LoadData)
        if (IncrementData == 1) NextState <= IncrementState;
        else if (LoadData == 1) NextState <= LoadState;
        else NextState <= ReadState;
endmodule

sva:
module OverallController_sva (
    input logic Clock,
    input logic IncrementData,
    input logic LoadData,
    input logic Reset,
    input logic AddOne,
    input logic WriteOrRead
);

    // Increment requests decode to increment outputs on the next cycle.
    check_increment_request_to_increment_outputs: assert property (
        @(posedge Clock) disable iff (Reset)
        IncrementData |=> (AddOne && WriteOrRead)
    );

    // Load-only requests decode to load outputs on the next cycle.
    check_load_only_request_to_load_outputs: assert property (
        @(posedge Clock) disable iff (Reset)
        (!IncrementData && LoadData) |=> (!AddOne && WriteOrRead)
    );

    // No request decodes to read outputs on the next cycle.
    check_no_request_to_read_outputs: assert property (
        @(posedge Clock) disable iff (Reset)
        (!IncrementData && !LoadData) |=> (!AddOne && !WriteOrRead)
    );

    // IncrementData has priority when both requests are asserted.
    check_increment_priority_over_load: assert property (
        @(posedge Clock) disable iff (Reset)
        (IncrementData && LoadData) |=> (AddOne && WriteOrRead)
    );

    // Any request drives WriteOrRead high on the next cycle.
    check_request_sets_writeorread: assert property (
        @(posedge Clock) disable iff (Reset)
        (IncrementData || LoadData) |=> WriteOrRead
    );

    // AddOne is never asserted without WriteOrRead.
    check_addone_implies_writeorread: assert property (
        @(posedge Clock) disable iff (Reset)
        AddOne |-> WriteOrRead
    );

    // After reset is released, outputs still reflect the initial decode.
    check_outputs_idle_after_reset_release: assert property (
        @(posedge Clock) disable iff (Reset)
        $fell(Reset) |-> (!AddOne && !WriteOrRead)
    );

endmodule

