    // If en is low on a clock edge, enclk is low on the next clock edge.
    check_en_low_clears_enclk: assert property (
        @(posedge clk) (en === 1'b0) |=> (enclk === 1'b0)
    );

    // enclk reflects the en value sampled on the previous clock edge.
    check_enclk_tracks_previous_en: assert property (
        @(posedge clk) ((en === 1'b1) || (en === 1'b0)) |=> (enclk === $past(en))
    );

endmodule

rtl:
module sky130_fd_sc_ms__fahcon (
    COUT_N,
    SUM   ,
    A     ,
    B     ,
    CI
);

    output COUT_N;
    output SUM   ;
    input  A     ;
    input  B     ;
    input  CI    ;

    wire xor0_out_SUM ;
    wire a_b          ;
    wire a_ci         ;
    wire b_ci         ;
    wire or0_out_coutn;

    xor xor0 (xor0_out_SUM , A, B, CI       );
    buf buf0 (SUM          , xor0_out_SUM   );
    nor nor0 (a_b          , A, B           );
    nor nor1 (a_ci         , A, CI          );
    nor nor2 (b_ci         , B, CI          );
    or  or0  (or0_out_coutn, a_b, a_ci, b_ci);
    buf buf1 (COUT_N       , or0_out_coutn  );

endmodule

sva:
module sky130_fd_sc_ms__fahcon_sva (
    input logic clk,
    input logic COUT_N,
    input logic SUM,
    input logic A,
    input logic B,
    input logic CI
);

    // SUM is the parity of A, B, and CI.
    check_sum_parity: assert property (
        @(posedge clk) (SUM == (A ^ B ^ CI))
    );

    // COUT_N matches the implemented OR-of-NOR carry complement logic.
    check_cout_n_nor_or_function: assert property (
        @(posedge clk) (COUT_N == ((~(A | B)) | (~(A | CI)) | (~(B | CI))))
    );

    // All-zero inputs produce SUM low and COUT_N high.
    check_zero_input_case: assert property (
        @(posedge clk)
        ((A == 1'b0) && (B == 1'b0) && (CI == 1'b0))
        |-> ((SUM == 1'b0) && (COUT_N == 1'b1))
    );

    // Exactly one high input produces SUM high and COUT_N high.
    check_single_high_case: assert property (
        @(posedge clk)
        (((A == 1'b1) && (B == 1'b0) && (CI == 1'b0)) ||
         ((A == 1'b0) && (B == 1'b1) && (CI == 1'b0)) ||
         ((A == 1'b0) && (B == 1'b0) && (CI == 1'b1)))
        |-> ((SUM == 1'b1) && (COUT_N == 1'b1))
    );

    // Exactly two high inputs produce SUM low and COUT_N low.
    check_double_high_case: assert property (
        @(posedge clk)
        (((A == 1'b1) && (B == 1'b1) && (CI == 1'b0)) ||
         ((A == 1'b1) && (B == 1'b0) && (CI == 1'b1)) ||
         ((A == 1'b0) && (B == 1'b1) && (CI == 1'b1)))
        |-> ((SUM == 1'b0) && (COUT_N == 1'b0))
    );

    // All-high inputs produce SUM high and COUT_N low.
    check_all_high_case: assert property (
        @(posedge clk)
        ((A == 1'b1) && (B == 1'b1) && (CI == 1'b1))
        |-> ((SUM == 1'b1) && (COUT_N == 1'b0))
    );

endmodule

rtl:
  module ded_ca_top
    #(parameter BYTES = 4)
    (
     input           mclock,
     input           mc_push,
     `ifdef BYTE16 input [2:0]     mc_addr,
     `elsif BYTE8  input [3:0]     mc_addr,
     `else         input [4:0]     mc_addr,
     `endif

     input           hclock,
     input           hb_we,
     input [4:0]     hb_addr,
     input [(BYTES*8)-1:0] hb_dout_ram,

     `ifdef BYTE16 input [2:0]     rad,
     `elsif BYTE8  input [3:0]     rad,
     `else         input [4:0]     rad, `endif

     `ifdef BYTE16 output [3:0] ca_enable,
     `elsif BYTE8  output [1:0] ca_enable,
     `else         output       ca_enable,
     `endif
     output     [31:0]          hb_dout,
     output     [4:0]           hb_ram_addr,
     output [4:0]           ca_ram_addr0,
     output [4:0]           ca_ram_addr1
     );


`ifdef BYTE16
  wire [2:0]            radp1;
  assign  radp1 = rad + 3'h1;
  assign  hb_dout   = hb_dout_ram[hb_addr[1:0]*32 +: 32];
  assign  ca_enable[0] = hb_we & (hb_addr[1:0] == 2'd0);
  assign  ca_enable[1] = hb_we & (hb_addr[1:0] == 2'd1);
  assign  ca_enable[2] = hb_we & (hb_addr[1:0] == 2'd2);
  assign  ca_enable[3] = hb_we & (hb_addr[1:0] == 2'd3);
  assign  hb_ram_addr = {2'b0, hb_addr[4:2]};
  assign  ca_ram_addr0 = (mc_push) ? {2'b0, mc_addr} : {2'b0, rad};
  assign  ca_ram_addr1 = (mc_push) ? {2'b0, mc_addr} : {2'b0, radp1};
`elsif BYTE8
  wire [3:0]            radp1;
  assign  radp1 = rad + 1;
  assign  hb_dout   = hb_dout_ram[hb_addr[0]*32 +: 32];
  assign  ca_enable[0] = hb_we & (hb_addr[0] == 1'b0);
  assign  ca_enable[1] = hb_we & (hb_addr[0] == 1'b1);
  assign  hb_ram_addr = {1'b0, hb_addr[4:1]};
  assign  ca_ram_addr0 = (mc_push) ? {1'b0, mc_addr} : {1'b0, rad};
  assign  ca_ram_addr1 = (mc_push) ? {1'b0, mc_addr} : {1'b0, radp1};
`else
  wire [4:0]            radp1;
  assign  radp1 = rad + 1;
  assign  hb_dout = hb_dout_ram[31:0];
  assign  ca_enable  = hb_we;
  assign  hb_ram_addr = hb_addr[4:0];
  assign  ca_ram_addr0 = (mc_push) ? mc_addr : rad;
  assign  ca_ram_addr1 = (mc_push) ? mc_addr : radp1;
`endif

endmodule

sva:
module ded_ca_top_sva
  #(parameter BYTES = 4)
  (
    input logic mclock,
    input logic mc_push,
`ifdef BYTE16
    input logic [2:0] mc_addr,
`elsif BYTE8
    input logic [3:0] mc_addr,
`else
    input logic [4:0] mc_addr,
`endif

    input logic hclock,
    input logic hb_we,
    input logic [4:0] hb_addr,
    input logic [(BYTES*8)-1:0] hb_dout_ram,

`ifdef BYTE16
    input logic [2:0] rad,
`elsif BYTE8
    input logic [3:0] rad,
`else
    input logic [4:0] rad,
`endif

`ifdef BYTE16
    input logic [3:0] ca_enable,
`elsif BYTE8
    input logic [1:0] ca_enable,
`else
    input logic       ca_enable,
`endif
    input logic [31:0] hb_dout,
    input logic [4:0]  hb_ram_addr,
    input logic [4:0]  ca_ram_addr0,
    input logic [4:0]  ca_ram_addr1
  );

`ifdef BYTE16

  // hb_dout selects a 32-bit lane from hb_dout_ram using hb_addr[1:0].
  check_hb_dout_lane_select: assert property (
    @(posedge hclock)
    hb_dout == hb_dout_ram[hb_addr[1:0]*32 +: 32]
  );

  // ca_enable decodes hb_we into a one-hot byte-group enable.
  check_ca_enable_decode: assert property (
    @(posedge hclock)
    ca_enable == {
      (hb_we & (hb_addr[1:0] == 2'd3)),
      (hb_we & (hb_addr[1:0] == 2'd2)),
      (hb_we & (hb_addr[1:0] == 2'd1)),
      (hb_we & (hb_addr[1:0] == 2'd0))
    }
  );

  // hb_ram_addr zero-extends hb_addr[4:2].
  check_hb_ram_addr_map: assert property (
    @(posedge hclock)
    hb_ram_addr == {2'b0, hb_addr[4:2]}
  );

  // ca_ram_addr0 selects mc_addr on push, otherwise rad.
  check_ca_ram_addr0_select: assert property (
    @(posedge mclock)
    ca_ram_addr0 == (mc_push ? {2'b0, mc_addr} : {2'b0, rad})
  );

  // ca_ram_addr1 selects mc_addr on push, otherwise rad plus one.
  check_ca_ram_addr1_select: assert property (
    @(posedge mclock)
    ca_ram_addr1 == (mc_push ? {2'b0, mc_addr} : {2'b0, (rad + 3'h1)})
  );

  // During push, both CA RAM addresses match mc_addr.
  check_ca_ram_addrs_match_on_push: assert property (
    @(posedge mclock)
    mc_push |-> ((ca_ram_addr0 == {2'b0, mc_addr}) && (ca_ram_addr1 == {2'b0, mc_addr}))
  );

`elsif BYTE8

  // hb_dout selects a 32-bit lane from hb_dout_ram using hb_addr[0].
  check_hb_dout_lane_select: assert property (
    @(posedge hclock)
    hb_dout == hb_dout_ram[hb_addr[0]*32 +: 32]
  );

  // ca_enable decodes hb_we into a one-hot byte-group enable.
  check_ca_enable_decode: assert property (
    @(posedge hclock)
    ca_enable == {
      (hb_we & (hb_addr[0] == 1'b1)),
      (hb_we & (hb_addr[0] == 1'b0))
    }
  );

  // hb_ram_addr zero-extends hb_addr[4:1].
  check_hb_ram_addr_map: assert property (
    @(posedge hclock)
    hb_ram_addr == {1'b0, hb_addr[4:1]}
  );

  // ca_ram_addr0 selects mc_addr on push, otherwise rad.
  check_ca_ram_addr0_select: assert property (
    @(posedge mclock)
    ca_ram_addr0 == (mc_push ? {1'b0, mc_addr} : {1'b0, rad})
  );

  // ca_ram_addr1 selects mc_addr on push, otherwise rad plus one.
  check_ca_ram_addr1_select: assert property (
    @(posedge mclock)
    ca_ram_addr1 == (mc_push ? {1'b0, mc_addr} : {1'b0, (rad + 4'h1)})
  );

  // During push, both CA RAM addresses match mc_addr.
  check_ca_ram_addrs_match_on_push: assert property (
    @(posedge mclock)
    mc_push |-> ((ca_ram_addr0 == {1'b0, mc_addr}) && (ca_ram_addr1 == {1'b0, mc_addr}))
  );

`else

  // hb_dout passes through the low 32 bits of hb_dout_ram.
  check_hb_dout_passthrough: assert property (
    @(posedge hclock)
    hb_dout == hb_dout_ram[31:0]
  );

  // ca_enable matches hb_we directly.
  check_ca_enable_passthrough: assert property (
    @(posedge hclock)
    ca_enable == hb_we
  );

  // hb_ram_addr matches hb_addr directly.
  check_hb_ram_addr_map: assert property (
    @(posedge hclock)
    hb_ram_addr == hb_addr[4:0]
  );

  // ca_ram_addr0 selects mc_addr on push, otherwise rad.
  check_ca_ram_addr0_select: assert property (
    @(posedge mclock)
    ca_ram_addr0 == (mc_push ? mc_addr : rad)
  );

  // ca_ram_addr1 selects mc_addr on push, otherwise rad plus one.
  check_ca_ram_addr1_select: assert property (
    @(posedge mclock)
    ca_ram_addr1 == (mc_push ? mc_addr : (rad + 5'h1))
  );

  // During push, both CA RAM addresses match mc_addr.
  check_ca_ram_addrs_match_on_push: assert property (
    @(posedge mclock)
    mc_push |-> ((ca_ram_addr0 == mc_addr) && (ca_ram_addr1 == mc_addr))
  );

`endif

endmodule

rtl:
module mux_and (
    input [7:0] a,
    input [7:0] b,
    input sel_b1,
    input sel_b2,
    input [3:0] c,
    output [7:0] out
);

wire [7:0] selected_input;
assign selected_input = (sel_b1 & sel_b2) ? b : a;

assign out = selected_input & c;

endmodule

sva:
module mux_and_sva (
    input logic        clk,
    input logic [7:0]  a,
    input logic [7:0]  b,
    input logic        sel_b1,
    input logic        sel_b2,
    input logic [3:0]  c,
    input logic [7:0]  out
);

    // Output matches the selected input masked by zero-extended c.
    check_out_matches_rtl_function: assert property (
        @(posedge clk)
        out == (((sel_b1 & sel_b2) ? b : a) & {4'b0000, c})
    );

    // When both select inputs are high, b drives the masked output.
    check_selects_choose_b: assert property (
        @(posedge clk)
        (sel_b1 & sel_b2) |-> (out == (b & {4'b0000, c}))
    );

    // When either select input is low, a drives the masked output.
    check_selects_choose_a: assert property (
        @(posedge clk)
        !(sel_b1 & sel_b2) |-> (out == (a & {4'b0000, c}))
    );

    // Upper output bits are always zero because c is only 4 bits wide.
    check_upper_nibble_forced_zero: assert property (
        @(posedge clk)
        out[7:4] == 4'b0000
    );

    // A zero mask clears the entire output.
    check_zero_mask_clears_output: assert property (
        @(posedge clk)
        (c == 4'h0) |-> (out == 8'h00)
    );

endmodule

rtl:
module clock_100kHz(clk,rst_n,out_100kHz);

input clk,rst_n;
output reg out_100kHz;

reg [15:0] counter;

always @ (posedge clk or negedge rst_n)
    if (!rst_n)
        begin
            out_100kHz <= 0;
            counter <= 0;
        end
    else
        if (counter == 16'd499) begin
                out_100kHz <= !out_100kHz;
                counter <= 0;
            end
        else 
            begin
                out_100kHz <= out_100kHz;
                counter <= counter + 1;
            end

endmodule

sva:
module clock_100kHz_sva (
    input logic        clk,
    input logic        rst_n,
    input logic        out_100kHz,
    input logic [15:0] counter
);

    // Reset drives both registers low.
    check_reset_clears_registers: assert property (
        @(posedge clk)
        !rst_n |-> ((out_100kHz == 1'b0) && (counter == 16'd0))
    );

    // Counter never exceeds the terminal count.
    check_counter_range: assert property (
        @(posedge clk) disable iff (!rst_n)
        (counter <= 16'd499)
    );

    // Counter increments by one when not at terminal count.
    check_counter_increments_below_terminal: assert property (
        @(posedge clk) disable iff (!rst_n)
        (counter != 16'd499) |=> (counter == ($past(counter) + 16'd1))
    );

    // Output holds its value when not at terminal count.
    check_output_holds_below_terminal: assert property (
        @(posedge clk) disable iff (!rst_n)
        (counter != 16'd499) |=> (out_100kHz == $past(out_100kHz))
    );

    // Counter wraps to zero at terminal count.
    check_counter_wraps_at_terminal: assert property (
        @(posedge clk) disable iff (!rst_n)
        (counter == 16'd499) |=> (counter == 16'd0)
    );

    // Output toggles when terminal count is reached.
    check_output_toggles_at_terminal: assert property (
        @(posedge clk) disable iff (!rst_n)
        (counter == 16'd499) |=> (out_100kHz == !$past(out_100kHz))
    );

endmodule

rtl:
module fourBitCounter(clk, reset, count);
  input clk, reset;
  output reg [3:0] count;

  always @(posedge clk) begin
    if (reset) begin
      count <= 4'b0;
    end else if (count == 4'b1111) begin
      count <= 4'b0;
    end else begin
      count <= count + 1;
    end
  end
endmodule

sva:
module fourBitCounter_sva (
    input logic       clk,
    input logic       reset,
    input logic [3:0] count
);

    // Reset clears the counter to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'h0)
    );

    // When below 15, the counter increments by one.
    check_increment_when_not_max: assert property (
        @(posedge clk) disable iff (reset)
        (count != 4'hF) |=> (count == ($past(count) + 4'h1))
    );

    // A count of 15 wraps back to zero.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (reset)
        (count == 4'hF) |=> (count == 4'h0)
    );

    // Zero advances to one when reset is low.
    check_zero_advances_to_one: assert property (
        @(posedge clk) disable iff (reset)
        (count == 4'h0) |=> (count == 4'h1)
    );

    // Fourteen advances to fifteen when reset is low.
    check_fourteen_advances_to_fifteen: assert property (
        @(posedge clk) disable iff (reset)
        (count == 4'hE) |=> (count == 4'hF)
    );

endmodule

rtl:
module three_input_gate (
    input A1,
    input A2,
    input B1,
    output X
);

    wire A1_not;
    wire A2_not;
    wire A1_and_A2;
    wire A1_nand_A2;
    wire B1_not;
    wire A1_and_A2_nand_B1;

    assign A1_not = ~A1;
    assign A2_not = ~A2;
    assign A1_and_A2 = A1 & A2;
    assign A1_nand_A2 = ~(A1 & A2);
    assign B1_not = ~B1;
    assign A1_and_A2_nand_B1 = ~(A1 & A2 & B1);

    assign X = (A1 & A2_not) | (A1_not & A2) | (B1_not & A1_and_A2_nand_B1);

endmodule

sva:
module three_input_gate_sva (
    input logic A1,
    input logic A2,
    input logic B1,
    input logic X
);

    // No clock or reset in the DUT; sample combinational behavior on the global clock.

    // X must match the exact RTL equation.
    check_output_matches_rtl_equation: assert property (
        @($global_clock)
        X == ((A1 & ~A2) | (~A1 & A2) | (~B1 & ~(A1 & A2 & B1)))
    );

    // X is equivalent to XOR(A1,A2) OR NOT(B1).
    check_output_matches_simplified_equation: assert property (
        @($global_clock)
        X == ((A1 ^ A2) | ~B1)
    );

    // A low B1 forces X high.
    check_b1_low_forces_x_high: assert property (
        @($global_clock)
        (!B1) |-> X
    );

    // Different A inputs force X high.
    check_a_inputs_mismatch_forces_x_high: assert property (
        @($global_clock)
        (A1 ^ A2) |-> X
    );

    // With B1 high, X reduces to A1 XOR A2.
    check_b1_high_reduces_to_xor: assert property (
        @($global_clock)
        B1 |-> (X == (A1 ^ A2))
    );

    // With B1 high and equal A inputs, X must be low.
    check_b1_high_equal_a_inputs_force_x_low: assert property (
        @($global_clock)
        (B1 && (A1 == A2)) |-> (!X)
    );

endmodule

rtl:
module sky130_fd_sc_ls__or2b (
    input  A  ,
    input  B_N,
    output X
);

    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    assign X = ~(A & B_N);

endmodule

sva:
module sky130_fd_sc_ls__or2b_sva (
    input logic clk,
    input logic A,
    input logic B_N,
    input logic X
);

    // X must match the implemented NAND of A and B_N.
    check_nand_function: assert property (
        @(posedge clk) X == ~(A & B_N)
    );

    // A low forces X high.
    check_a_low_forces_x_high: assert property (
        @(posedge clk) (A == 1'b0) |-> (X == 1'b1)
    );

    // B_N low forces X high.
    check_bn_low_forces_x_high: assert property (
        @(posedge clk) (B_N == 1'b0) |-> (X == 1'b1)
    );

    // Both inputs high force X low.
    check_both_high_drive_x_low: assert property (
        @(posedge clk) ((A == 1'b1) && (B_N == 1'b1)) |-> (X == 1'b0)
    );

endmodule

module mux4_sva
  #(parameter width = 16)
  (
    input logic                   clk,
    input logic [width-1:0]       in0,
    input logic [width-1:0]       in1,
    input logic [width-1:0]       in2,
    input logic [width-1:0]       in3,
    input logic [1:0]             sel,
    input logic [width-1:0]       out
  );

    // Output must match the RTL's mux expression on every sampled cycle.
    check_output_matches_rtl_mux_expression: assert property (
        @(posedge clk) disable iff (1'b0)
        out === ((sel == 2'b00) ? in0 :
                 (sel == 2'b01) ? in1 :
                 (sel == 2'b10) ? in2 :
                 (sel == 2'b11) ? in3 :
                 {width{1'b0}})
    );

    // Select 00 routes input 0 to the output.
    check_sel_00_routes_in0: assert property (
        @(posedge clk) disable iff (1'b0)
        (sel === 2'b00) |-> (out === in0)
    );

    // Select 01 routes input 1 to the output.
    check_sel_01_routes_in1: assert property (
        @(posedge clk) disable iff (1'b0)
        (sel === 2'b01) |-> (out === in1)
    );

    // Select 10 routes input 2 to the output.
    check_sel_10_routes_in2: assert property (
        @(posedge clk) disable iff (1'b0)
        (sel === 2'b10) |-> (out === in2)
    );

    // Select 11 routes input 3 to the output.
    check_sel_11_routes_in3: assert property (
        @(posedge clk) disable iff (1'b0)
        (sel === 2'b11) |-> (out === in3)
    );

endmodule

rtl:
module MUXn_2_1(
  input [MuxLen:0] mux_in0,
  input [MuxLen:0] mux_in1,
  input mux_sel,
  output reg [MuxLen:0] mux_out
);

  parameter MuxLen = 63;

  always @(*) begin
    if (mux_sel == 1'b1) begin
      mux_out <= mux_in1;
    end else begin
      mux_out <= mux_in0;
    end
  end

endmodule

sva:
module MUXn_2_1_sva #(
    parameter int MuxLen = 63
) (
    input logic clk,
    input logic [MuxLen:0] mux_in0,
    input logic [MuxLen:0] mux_in1,
    input logic mux_sel,
    input logic [MuxLen:0] mux_out
);

    // Combinational DUT sampled on clk; no reset is present in the RTL.

    // When select is high, the output must match input 1.
    check_select_high_routes_in1: assert property (
        @(posedge clk) (mux_sel === 1'b1) |-> (mux_out === mux_in1)
    );

    // When select is anything other than high, the output must match input 0.
    check_select_not_high_routes_in0: assert property (
        @(posedge clk) (mux_sel !== 1'b1) |-> (mux_out === mux_in0)
    );

    // The output must always match one of the two inputs.
    check_output_matches_one_input: assert property (
        @(posedge clk) (mux_out === mux_in0) || (mux_out === mux_in1)
    );

    // A change on unselected input 0 must not affect the output when input 1 is selected.
    check_unselected_in0_change_ignored: assert property (
        @(posedge clk)
        (mux_sel === 1'b1 && $stable(mux_sel) && $stable(mux_in1) && $changed(mux_in0))
        |-> $stable(mux_out)
    );

    // A change on unselected input 1 must not affect the output when input 0 is selected.
    check_unselected_in1_change_ignored: assert property (
        @(posedge clk)
        (mux_sel !== 1'b1 && $stable(mux_sel) && $stable(mux_in0) && $changed(mux_in1))
        |-> $stable(mux_out)
    );

    // If both inputs and select are stable, the output must stay stable.
    check_output_stable_when_inputs_stable: assert property (
        @(posedge clk) $stable({mux_in0, mux_in1, mux_sel}) |-> $stable(mux_out)
    );

endmodule

rtl:
module four_bit_adder(
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] S,
    output Cout
);

    wire C1, C2, C3;

    // Calculation of the sum bits
    xor(S[0], A[0], B[0], Cin);
    xor(S[1], A[1], B[1], C1);
    xor(S[2], A[2], B[2], C2);
    xor(S[3], A[3], B[3], C3);

    // Calculation of the carry out bit
    and(C1, A[0], B[0]);
    and(C2, A[1], B[1]);
    and(C3, A[2], B[2]);
    or(Cout, C1, C2, C3);

endmodule

sva:
module four_bit_adder_sva(
    input logic [3:0] A,
    input logic [3:0] B,
    input logic Cin,
    input logic [3:0] S,
    input logic Cout
);

    // S[0] is the XOR of A[0], B[0], and Cin.
    check_sum_bit0: assert property (
        @($global_clock) S[0] == (A[0] ^ B[0] ^ Cin)
    );

    // S[1] is the XOR of A[1], B[1], and A[0]&B[0].
    check_sum_bit1: assert property (
        @($global_clock) S[1] == (A[1] ^ B[1] ^ (A[0] & B[0]))
    );

    // S[2] is the XOR of A[2], B[2], and A[1]&B[1].
    check_sum_bit2: assert property (
        @($global_clock) S[2] == (A[2] ^ B[2] ^ (A[1] & B[1]))
    );

    // S[3] is the XOR of A[3], B[3], and A[2]&B[2].
    check_sum_bit3: assert property (
        @($global_clock) S[3] == (A[3] ^ B[3] ^ (A[2] & B[2]))
    );

    // Cout is the OR of the three carry wires from bits 0 through 2.
    check_cout_equation: assert property (
        @($global_clock) Cout == ((A[0] & B[0]) | (A[1] & B[1]) | (A[2] & B[2]))
    );

endmodule

rtl:
module mux_4to1 (
    input [3:0] A, B, C, D,
    input [1:0] S,
    output reg [3:0] OUT
);

always @(*) begin
    case(S)
        2'b00: OUT = A;
        2'b01: OUT = B;
        2'b10: OUT = C;
        2'b11: OUT = D;
    endcase
end

endmodule

sva:
module mux_4to1_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] C,
    input logic [3:0] D,
    input logic [1:0] S,
    input logic [3:0] OUT
);

    // When S selects A, OUT must equal A.
    check_select_00_routes_a: assert property (
        @(posedge clk) (S == 2'b00) |-> (OUT == A)
    );

    // When S selects B, OUT must equal B.
    check_select_01_routes_b: assert property (
        @(posedge clk) (S == 2'b01) |-> (OUT == B)
    );

    // When S selects C, OUT must equal C.
    check_select_10_routes_c: assert property (
        @(posedge clk) (S == 2'b10) |-> (OUT == C)
    );

    // When S selects D, OUT must equal D.
    check_select_11_routes_d: assert property (
        @(posedge clk) (S == 2'b11) |-> (OUT == D)
    );

    // If A and S stay on 00, OUT must remain stable.
    check_stable_a_keeps_out_stable: assert property (
        @(posedge clk) (S == 2'b00 && $stable(S) && $stable(A)) |-> $stable(OUT)
    );

    // If B and S stay on 01, OUT must remain stable.
    check_stable_b_keeps_out_stable: assert property (
        @(posedge clk) (S == 2'b01 && $stable(S) && $stable(B)) |-> $stable(OUT)
    );

    // If C and S stay on 10, OUT must remain stable.
    check_stable_c_keeps_out_stable: assert property (
        @(posedge clk) (S == 2'b10 && $stable(S) && $stable(C)) |-> $stable(OUT)
    );

    // If D and S stay on 11, OUT must remain stable.
    check_stable_d_keeps_out_stable: assert property (
        @(posedge clk) (S == 2'b11 && $stable(S) && $stable(D)) |-> $stable(OUT)
    );

endmodule

rtl:
module full_adder(
    input A, B, Cin,
    output S, Cout
);

assign S = A ^ B ^ Cin;
assign Cout = (A & B) | (Cin & (A ^ B));

endmodule

module four_bit_adder(
    input [3:0] A, B,
    input Cin,
    output [3:0] S,
    output Cout
);

wire c1, c2, c3;
full_adder fa1(.A(A[0]), .B(B[0]), .Cin(Cin), .S(S[0]), .Cout(c1));
full_adder fa2(.A(A[1]), .B(B[1]), .Cin(c1), .S(S[1]), .Cout(c2));
full_adder fa3(.A(A[2]), .B(B[2]), .Cin(c2), .S(S[2]), .Cout(c3));
full_adder fa4(.A(A[3]), .B(B[3]), .Cin(c3), .S(S[3]), .Cout(Cout));

endmodule

sva:
module four_bit_adder_sva (
    input logic        clk,
    input logic [3:0]  A,
    input logic [3:0]  B,
    input logic        Cin,
    input logic [3:0]  S,
    input logic        Cout
);

    // External clk samples a combinational DUT; the RTL has no reset.

    // The concatenated carry and sum match 5-bit unsigned addition.
    check_total_sum: assert property (
        @(posedge clk) ({Cout, S} == ({1'b0, A} + {1'b0, B} + {4'b0000, Cin}))
    );

    // The least-significant sum bit follows the first full-adder XOR equation.
    check_lsb_sum: assert property (
        @(posedge clk) (S[0] == (A[0] ^ B[0] ^ Cin))
    );

    // The sum bus matches the low four bits of the arithmetic result.
    check_sum_bus: assert property (
        @(posedge clk) (S == (({1'b0, A} + {1'b0, B} + {4'b0000, Cin})[3:0]))
    );

    // Cout matches the carry-out bit of the arithmetic result.
    check_carry_out: assert property (
        @(posedge clk) (Cout == (({1'b0, A} + {1'b0, B} + {4'b0000, Cin})[4]))
    );

    // Adding zero with no carry-in passes A through unchanged.
    check_add_zero_passes_a: assert property (
        @(posedge clk) (((B == 4'b0000) && (Cin == 1'b0)) |-> ((S == A) && (Cout == 1'b0)))
    );

    // Adding zero with no carry-in passes B through unchanged.
    check_add_zero_passes_b: assert property (
        @(posedge clk) (((A == 4'b0000) && (Cin == 1'b0)) |-> ((S == B) && (Cout == 1'b0)))
    );

endmodule

rtl:
module MUX2to1 (data0, data1, sel, out);
input data0;
input data1;
input sel;
output out;

wire not_sel;
assign not_sel = ~sel;

assign out = (data0 & not_sel) | (data1 & sel);

endmodule

sva:
module MUX2to1_sva (
    input logic clk,
    input logic data0,
    input logic data1,
    input logic sel,
    input logic out
);

    // Output must implement the mux equation.
    check_mux_equation: assert property (
        @(posedge clk) out == ((data0 & ~sel) | (data1 & sel))
    );

    // When select is low, output must follow data0.
    check_select_low: assert property (
        @(posedge clk) !sel |-> (out == data0)
    );

    // When select is high, output must follow data1.
    check_select_high: assert property (
        @(posedge clk) sel |-> (out == data1)
    );

    // If both inputs are low, output must be low.
    check_both_inputs_low: assert property (
        @(posedge clk) (!data0 && !data1) |-> !out
    );

    // If both inputs are high, output must be high.
    check_both_inputs_high: assert property (
        @(posedge clk) (data0 && data1) |-> out
    );

endmodule

rtl:
module GrayCode #(
  parameter n = 4, // number of flip-flops
  parameter m = 4 // number of output signals
)(
  input clk, // clock input
  input [n-1:0] in,
  output [m-1:0] out
);


reg [n-1:0] flip_flops;
reg [m-1:0] gray_code;

function [m-1:0] binary_to_gray;
  input [n-1:0] binary_value;
  begin
    binary_to_gray = binary_value ^ (binary_value >> 1);
  end
endfunction

always @(posedge clk) begin
  flip_flops <= in;
  gray_code <= binary_to_gray(flip_flops);
end

assign out = gray_code;

endmodule

sva:
module GrayCode_sva #(
  parameter n = 4,
  parameter m = 4
)(
  input logic         clk,
  input logic [n-1:0] in,
  input logic [m-1:0] out
);

  function automatic [m-1:0] binary_to_gray(input logic [n-1:0] binary_value);
    begin
      binary_to_gray = binary_value ^ (binary_value >> 1);
    end
  endfunction

  // out is the Gray code of the input sampled on the previous clock.
  check_out_is_previous_input_gray: assert property (
    @(posedge clk) ##1 out == binary_to_gray($past(in))
  );

  // A stable sampled input keeps the output stable on the following clock.
  check_stable_input_keeps_output_stable: assert property (
    @(posedge clk) $stable(in) |=> $stable(out)
  );

  genvar i;
  generate
    for (i = 0; i < m; i = i + 1) begin : gen_out_bits
      if (i < n-1) begin : gen_xor_bit
        // Lower Gray bits are XORs of adjacent prior input bits.
        check_gray_xor_bit: assert property (
          @(posedge clk) ##1 out[i] == ($past(in[i+1]) ^ $past(in[i]))
        );
      end else if (i == n-1) begin : gen_msb_bit
        // The Gray MSB matches the prior input MSB.
        check_gray_msb_bit: assert property (
          @(posedge clk) ##1 out[i] == $past(in[i])
        );
      end else begin : gen_zero_bit
        // Output bits above the input width remain zero.
        check_gray_zero_extended_bit: assert property (
          @(posedge clk) ##1 out[i] == 1'b0
        );
      end
    end
  endgenerate

endmodule

rtl:
module top_module(
    input wire clk,
    input wire [7:0] in1,
    input wire [7:0] in2,
    input wire sel,
    output wire [7:0] sum
);

    wire [7:0] add_out;
    wire carry_out;
    wire [7:0] mux_out;

    genvar i;
    generate
        for (i=0; i<8; i=i+1) begin: adder_loop
            full_adder adder_inst(
                .a(in1[i]),
                .b(in2[i]),
                .cin(sel),
                .sum(add_out[i]),
                .cout() // Disconnect carry out
            );

            mux2to1 mux_inst(
                .a(in1[i]),
                .b(in2[i]),
                .sel(sel),
                .out(mux_out[i])
            );
        end
    endgenerate

    assign sum = sel ? mux_out : add_out;

endmodule
module full_adder(
    input wire a,
    input wire b,
    input wire cin,
    output wire sum,
    output wire cout
);

    assign {cout, sum} = a + b + cin;

endmodule
module mux2to1(
    input wire  a,
    input wire  b,
    input wire sel,
    output wire  out
);

    assign out = sel ? b : a;

endmodule

sva:
module top_module_sva (
    input logic        clk,
    input logic [7:0]  in1,
    input logic [7:0]  in2,
    input logic        sel,
    input logic [7:0]  sum
);

    // Sum must match the selected top-level datapath.
    check_sum_selected_function: assert property (
        @(posedge clk) sum == (sel ? in2 : (in1 ^ in2))
    );

    // When sel is high, the output must route in2.
    check_sel_high_routes_in2: assert property (
        @(posedge clk) sel |-> (sum == in2)
    );

    // When sel is low, the output must be the bitwise XOR path.
    check_sel_low_routes_bitwise_xor: assert property (
        @(posedge clk) !sel |-> (sum == (in1 ^ in2))
    );

    // Equal inputs on the XOR path must produce zero.
    check_sel_low_equal_inputs_zero: assert property (
        @(posedge clk) (!sel && (in1 == in2)) |-> (sum == 8'h00)
    );

    // Zero on in2 must pass in1 through the XOR path.
    check_sel_low_in2_zero_passthrough: assert property (
        @(posedge clk) (!sel && (in2 == 8'h00)) |-> (sum == in1)
    );

    // Zero on in1 must pass in2 through the XOR path.
    check_sel_low_in1_zero_passthrough: assert property (
        @(posedge clk) (!sel && (in1 == 8'h00)) |-> (sum == in2)
    );

    // All ones on in2 must invert in1 on the XOR path.
    check_sel_low_in2_ones_inverts_in1: assert property (
        @(posedge clk) (!sel && (in2 == 8'hFF)) |-> (sum == ~in1)
    );

endmodule

rtl:
module dut(
    input a,
    input b,
    input c,
    output true_val,
    output false_val,
    output and1,
    output and2,
    output and3,
    output or1,
    output or2,
    output or3,
    output not1,
    output not2
);

assign true_val = 1'b1;
assign false_val = 1'b0;
assign and1 = a & b & c;
assign and2 = a & b;
assign and3 = a & c;
assign or1 = a | b | c;
assign or2 = a | b;
assign or3 = a | c;
assign not1 = !a;
assign not2 = !b;

endmodule

sva:
module dut_sva(
    input logic a,
    input logic b,
    input logic c,
    input logic true_val,
    input logic false_val,
    input logic and1,
    input logic and2,
    input logic and3,
    input logic or1,
    input logic or2,
    input logic or3,
    input logic not1,
    input logic not2
);

    // true_val is tied high.
    check_true_val_const: assert property (
        @($global_clock) (true_val === 1'b1)
    );

    // false_val is tied low.
    check_false_val_const: assert property (
        @($global_clock) (false_val === 1'b0)
    );

    // and1 matches a & b & c.
    check_and1_function: assert property (
        @($global_clock) (and1 === (a & b & c))
    );

    // and2 matches a & b.
    check_and2_function: assert property (
        @($global_clock) (and2 === (a & b))
    );

    // and3 matches a & c.
    check_and3_function: assert property (
        @($global_clock) (and3 === (a & c))
    );

    // or1 matches a | b | c.
    check_or1_function: assert property (
        @($global_clock) (or1 === (a | b | c))
    );

    // or2 matches a | b.
    check_or2_function: assert property (
        @($global_clock) (or2 === (a | b))
    );

    // or3 matches a | c.
    check_or3_function: assert property (
        @($global_clock) (or3 === (a | c))
    );

    // not1 matches logical negation of a.
    check_not1_function: assert property (
        @($global_clock) (not1 === (!a))
    );

    // not2 matches logical negation of b.
    check_not2_function: assert property (
        @($global_clock) (not2 === (!b))
    );

endmodule

module counter_assertions (
    input logic       clk,
    input logic       rst,
    input logic       enable,
    input logic [3:0] out
);

    // Synchronous reset clears the counter on the following clock.
    check_reset_clears_out: assert property (
        @(posedge clk) rst |=> (out == 4'h0)
    );

    // When enabled below 15, the counter increments by one.
    check_increment_when_enabled: assert property (
        @(posedge clk) disable iff (rst)
        enable && (out != 4'hF) |=> (out == ($past(out) + 4'h1))
    );

    // When enabled at 15, the counter wraps back to zero.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (rst)
        enable && (out == 4'hF) |=> (out == 4'h0)
    );

    // When not enabled, the counter holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (rst)
        !enable |=> (out == $past(out))
    );

endmodule

rtl:
module half_subtractor (
  input A,
  input B,
  output D,
  output Bout
);
  assign D = A ^ B;
  assign Bout = ~A & B;
endmodule

module full_subtractor (
  input A,
  input B,
  input Bin,
  output D,
  output Bout
);
  wire half_sub1_D, half_sub1_Bout, half_sub2_D, half_sub2_Bout;

  half_subtractor half_sub1 (
    .A(A),
    .B(B),
    .D(half_sub1_D),
    .Bout(half_sub1_Bout)
  );

  half_subtractor half_sub2 (
    .A(half_sub1_D),
    .B(Bin),
    .D(half_sub2_D),
    .Bout(half_sub2_Bout)
  );

  assign D = half_sub2_D;
  assign Bout = half_sub1_Bout | half_sub2_Bout;
endmodule

sva:
module full_subtractor_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic Bin,
    input logic D,
    input logic Bout
);

    // D must equal the full-subtractor difference.
    check_difference_function: assert property (
        @(posedge clk) D == (A ^ B ^ Bin)
    );

    // Bout must equal the full-subtractor borrow equation.
    check_borrow_function: assert property (
        @(posedge clk) Bout == ((~A & B) | (~(A ^ B) & Bin))
    );

    // With Bin low, the block reduces to a half subtractor on A and B.
    check_no_borrow_in_reduction: assert property (
        @(posedge clk) !Bin |-> ((D == (A ^ B)) && (Bout == (~A & B)))
    );

    // With B low, the block subtracts only Bin from A.
    check_b_zero_reduction: assert property (
        @(posedge clk) !B |-> ((D == (A ^ Bin)) && (Bout == (~A & Bin)))
    );

    // When A and B are equal, both outputs must match Bin.
    check_equal_inputs_reduction: assert property (
        @(posedge clk) (A == B) |-> ((D == Bin) && (Bout == Bin))
    );

    // When A is low, borrow is the OR of B and Bin.
    check_a_zero_reduction: assert property (
        @(posedge clk) !A |-> ((D == (B ^ Bin)) && (Bout == (B | Bin)))
    );

    // When A is high, borrow occurs only if both B and Bin are high.
    check_a_one_reduction: assert property (
        @(posedge clk) A |-> ((D == (~(B ^ Bin))) && (Bout == (B & Bin)))
    );

endmodule

rtl:
module Multiplexer4(
    i_data0,
    i_data1,
    i_data2,
    i_data3,
    i_select0,
    i_select1,
    i_select2,
    i_select3,
    o_data,
    o_error);
  parameter width = 1;

  input  [width - 1:0] i_data0;
  input  [width - 1:0] i_data1;
  input  [width - 1:0] i_data2;
  input  [width - 1:0] i_data3;
  input                i_select0;
  input                i_select1;
  input                i_select2;
  input                i_select3;

  output [width - 1:0] o_data;
  output               o_error;

  wire   [        2:0] w_sum;

  assign o_data  = i_select0 ? i_data0 :
                   i_select1 ? i_data1 :
                   i_select2 ? i_data2 :
                   i_select3 ? i_data3 : 0;
  assign w_sum   = i_select0 + i_select1 + i_select2 + i_select3;
  assign o_error = w_sum[2] | w_sum[1] | (w_sum == 3'h0);
endmodule

sva:
module Multiplexer4_sva #(
    parameter int width = 1
) (
    input logic                   clk,
    input logic [width-1:0]       i_data0,
    input logic [width-1:0]       i_data1,
    input logic [width-1:0]       i_data2,
    input logic [width-1:0]       i_data3,
    input logic                   i_select0,
    input logic                   i_select1,
    input logic                   i_select2,
    input logic                   i_select3,
    input logic [width-1:0]       o_data,
    input logic                   o_error
);

    // Select0 has highest priority on o_data.
    check_select0_priority: assert property (
        @(posedge clk) i_select0 |-> (o_data == i_data0)
    );

    // Select1 drives o_data when select0 is low.
    check_select1_priority: assert property (
        @(posedge clk) (!i_select0 && i_select1) |-> (o_data == i_data1)
    );

    // Select2 drives o_data when higher-priority selects are low.
    check_select2_priority: assert property (
        @(posedge clk) (!i_select0 && !i_select1 && i_select2) |-> (o_data == i_data2)
    );

    // Select3 drives o_data when all higher-priority selects are low.
    check_select3_priority: assert property (
        @(posedge clk) (!i_select0 && !i_select1 && !i_select2 && i_select3) |-> (o_data == i_data3)
    );

    // No active select drives zero on o_data.
    check_no_select_data_zero: assert property (
        @(posedge clk) (!i_select0 && !i_select1 && !i_select2 && !i_select3) |-> (o_data == {width{1'b0}})
    );

    // o_data matches the implemented priority mux function.
    check_o_data_function: assert property (
        @(posedge clk)
        o_data == (i_select0 ? i_data0 :
                   i_select1 ? i_data1 :
                   i_select2 ? i_data2 :
                   i_select3 ? i_data3 : {width{1'b0}})
    );

    // No active select asserts o_error.
    check_no_select_error: assert property (
        @(posedge clk) (!i_select0 && !i_select1 && !i_select2 && !i_select3) |-> o_error
    );

    // Exactly one active select clears o_error.
    check_onehot_select_no_error: assert property (
        @(posedge clk)
        (( i_select0 && !i_select1 && !i_select2 && !i_select3) ||
         (!i_select0 &&  i_select1 && !i_select2 && !i_select3) ||
         (!i_select0 && !i_select1 &&  i_select2 && !i_select3) ||
         (!i_select0 && !i_select1 && !i_select2 &&  i_select3)) |-> !o_error
    );

    // Two or more active selects assert o_error.
    check_multiple_selects_error: assert property (
        @(posedge clk)
        ((i_select0 && i_select1) ||
         (i_select0 && i_select2) ||
         (i_select0 && i_select3) ||
         (i_select1 && i_select2) ||
         (i_select1 && i_select3) ||
         (i_select2 && i_select3)) |-> o_error
    );

    // o_error matches the implemented select-count behavior.
    check_o_error_function: assert property (
        @(posedge clk)
        o_error == ((!i_select0 && !i_select1 && !i_select2 && !i_select3) ||
                    (i_select0 && i_select1) ||
                    (i_select0 && i_select2) ||
                    (i_select0 && i_select3) ||
                    (i_select1 && i_select2) ||
                    (i_select1 && i_select3) ||
                    (i_select2 && i_select3))
    );

endmodule

