module top_module_sva (
    input logic       clk,
    input logic       reset,
    input logic [7:0] d,
    input logic [7:0] in,
    input logic [7:0] q
);

    // clk is the only clock; reset is active-high and synchronous.

    // q matches the previously stored value masked by the current input.
    check_sampled_top_function: assert property (
        @(posedge clk) disable iff ($initstate)
        q == ((($past(reset)) ? 8'h00 : $past(d)) & in)
    );

    // A reset cycle clears the stored value, so q is zero on the next sample.
    check_reset_clears_output_next: assert property (
        @(posedge clk) reset |=> (q == 8'h00)
    );

    // q can only contain bits enabled by the current input mask.
    check_output_masked_by_input: assert property (
        @(posedge clk) disable iff (reset)
        ((q & ~in) == 8'h00)
    );

    // A zero mask forces q low.
    check_zero_mask_forces_zero_output: assert property (
        @(posedge clk) disable iff (reset)
        (in == 8'h00) |-> (q == 8'h00)
    );

    // Capturing zero data forces q low on the next sample.
    check_zero_data_clears_next_output: assert property (
        @(posedge clk) (!reset && (d == 8'h00)) |=> (q == 8'h00)
    );

    // Capturing all ones makes q mirror the current input on the next sample.
    check_all_ones_data_passes_input_next: assert property (
        @(posedge clk) (!reset && (d == 8'hFF)) |=> (q == in)
    );

    // With an all-ones mask, q exposes the previously captured data.
    check_all_ones_mask_reveals_previous_data: assert property (
        @(posedge clk) disable iff ($initstate)
        ((!$past(reset)) && (in == 8'hFF)) |-> (q == $past(d))
    );

endmodule

rtl:
module add_sub_16bit (
    input [15:0] minuend,
    input [15:0] subtrahend,
    input control,
    output reg [15:0] result
);

    wire [15:0] twos_complement_subtrahend;
    assign twos_complement_subtrahend = (~subtrahend) + 1;

    always @(*) begin
        if (control) begin
            result <= minuend + twos_complement_subtrahend;
        end else begin
            result <= minuend + subtrahend;
        end
    end

endmodule

sva:
module add_sub_16bit_sva (
    input logic        clk,
    input logic [15:0] minuend,
    input logic [15:0] subtrahend,
    input logic        control,
    input logic [15:0] result
);

    // Add mode outputs the 16-bit sum.
    check_add_mode_function: assert property (
        @(posedge clk) !control |-> (result == (minuend + subtrahend))
    );

    // Subtract mode adds the 16-bit two's complement of subtrahend.
    check_sub_mode_function: assert property (
        @(posedge clk) control |-> (result == (minuend + ((~subtrahend) + 16'h0001)))
    );

    // Adding zero leaves the minuend unchanged.
    check_add_zero_subtrahend_identity: assert property (
        @(posedge clk) (!control && (subtrahend == 16'h0000)) |-> (result == minuend)
    );

    // Subtracting zero leaves the minuend unchanged.
    check_sub_zero_subtrahend_identity: assert property (
        @(posedge clk) (control && (subtrahend == 16'h0000)) |-> (result == minuend)
    );

    // With zero minuend in add mode, result matches subtrahend.
    check_add_zero_minuend_passthrough: assert property (
        @(posedge clk) (!control && (minuend == 16'h0000)) |-> (result == subtrahend)
    );

    // Subtracting equal operands produces zero.
    check_sub_equal_operands_zero: assert property (
        @(posedge clk) (control && (minuend == subtrahend)) |-> (result == 16'h0000)
    );

    // With zero minuend in subtract mode, result is the two's complement of subtrahend.
    check_sub_zero_minuend_twos_complement: assert property (
        @(posedge clk) (control && (minuend == 16'h0000)) |-> (result == ((~subtrahend) + 16'h0001))
    );

endmodule

rtl:
module rca_top(
    output reg [15:0] final_output,
    output reg carry_output,
    input [15:0]input1, input2
    );

reg carry_in;		task CRAFA_module(
    output reg sum,carry,
    input in1,in2,carry_in
    );

reg intermediate, gen, propagate;
begin
propagate = in1 ^ in2;
sum = propagate ^ carry_in;
gen = in1 & in2;
intermediate = propagate & carry_in;
carry = intermediate | gen;
end
endtask

task CRA4bit(
    output reg [3:0] cra_sum,
    output reg cra_carry_out,
    input [3:0] in1,in2,
    input carry_in
    );
reg carry1,carry2,carry3;
begin
CRAFA_module 	(cra_sum[0],carry1,in1[0],in2[0],carry_in);
CRAFA_module	(cra_sum[1],carry2,in1[1],in2[1],carry1);
CRAFA_module	(cra_sum[2],carry3,in1[2],in2[2],carry2);
CRAFA_module	(cra_sum[3],cra_carry_out,in1[3],in2[3],carry3);
end
endtask

task CRA16bit(
    output reg [15:0] cra_sum,
    output reg cra_carry_out,
    input [15:0] in1,in2,
    input carry_in
    );
reg carry1,carry2,carry3;
begin
CRA4bit	(cra_sum[3:0],carry1,in1[3:0],in2[3:0],carry_in);
CRA4bit	(cra_sum[7:4],carry2,in1[7:4],in2[7:4],carry1);
CRA4bit	(cra_sum[11:8],carry3,in1[11:8],in2[11:8],carry2);
CRA4bit	(cra_sum[15:12],cra_carry_out,in1[15:12],in2[15:12],carry3);
end
endtask

always@*
begin
	carry_in = 1'b0;
	CRA16bit(final_output, carry_output, input1, input2, carry_in);

end	
endmodule

sva:
module rca_top_sva (
    input logic [15:0] final_output,
    input logic        carry_output,
    input logic [15:0] input1,
    input logic [15:0] input2
);

    // Combined carry and sum match the 17-bit unsigned addition.
    check_full_sum: assert property (
        @($global_clock)
        ({carry_output, final_output} == ({1'b0, input1} + {1'b0, input2}))
    );

    // Sum output is the low 16 bits of the unsigned addition.
    check_sum_truncation: assert property (
        @($global_clock)
        (final_output == (input1 + input2))
    );

    // Carry output matches unsigned overflow relative to input1.
    check_carry_overflow_input1: assert property (
        @($global_clock)
        (carry_output == (final_output < input1))
    );

    // Carry output matches unsigned overflow relative to input2.
    check_carry_overflow_input2: assert property (
        @($global_clock)
        (carry_output == (final_output < input2))
    );

    // Bit 0 sum is XOR because the adder carry-in is tied low.
    check_lsb_sum_xor: assert property (
        @($global_clock)
        (final_output[0] == (input1[0] ^ input2[0]))
    );

    // Zero on input1 passes input2 through with no carry.
    check_zero_input1_passthrough: assert property (
        @($global_clock)
        ((input1 == 16'h0000) |-> ((final_output == input2) && (carry_output == 1'b0)))
    );

    // Zero on input2 passes input1 through with no carry.
    check_zero_input2_passthrough: assert property (
        @($global_clock)
        ((input2 == 16'h0000) |-> ((final_output == input1) && (carry_output == 1'b0)))
    );

    // If both MSBs are clear, the addition cannot overflow.
    check_no_overflow_when_msbs_clear: assert property (
        @($global_clock)
        (((input1[15] == 1'b0) && (input2[15] == 1'b0)) |-> (carry_output == 1'b0))
    );

endmodule

rtl:
module binary_counter(
    input clk,
    input rst,
    output reg [3:0] count
);

always @(posedge clk or negedge rst) begin
    if (~rst) begin
        count <= 4'b0;
    end else begin
        count <= count + 1;
    end
end

endmodule

sva:
module binary_counter_sva (
    input logic clk,
    input logic rst,
    input logic [3:0] count
);

    // Reset drives count to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) !rst |-> (count == 4'b0000)
    );

    // A sampled reset cycle is followed by count still being zero on the next clock.
    check_reset_holds_count_zero: assert property (
        @(posedge clk) !rst |=> (count == 4'b0000)
    );

    // Outside reset, count increments by one every clock.
    check_count_increments: assert property (
        @(posedge clk) disable iff (!rst) 1'b1 |=> (count == ($past(count) + 4'd1))
    );

    // Count wraps from 4'hF back to 4'h0.
    check_count_wraps: assert property (
        @(posedge clk) disable iff (!rst) (count == 4'hF) |=> (count == 4'h0)
    );

    // Count advances from zero to one when running.
    check_count_advances_from_zero: assert property (
        @(posedge clk) disable iff (!rst) (count == 4'h0) |=> (count == 4'h1)
    );

    // Any nonzero count value can only occur when reset is inactive.
    check_nonzero_count_requires_reset_inactive: assert property (
        @(posedge clk) (count != 4'b0000) |-> rst
    );

endmodule

rtl:
module adder(A, B, Cin, S, Cout);
    parameter WIDTH = 4;
    input [WIDTH-1:0] A, B;
    input Cin;
    output [WIDTH-1:0] S;
    output Cout;

    wire [WIDTH:0] C;

    full_adder fa0(.a(A[0]), .b(B[0]), .c(Cin), .sum(S[0]), .carry(C[0]));
    full_adder fa1(.a(A[1]), .b(B[1]), .c(C[0]), .sum(S[1]), .carry(C[1]));
    full_adder fa2(.a(A[2]), .b(B[2]), .c(C[1]), .sum(S[2]), .carry(C[2]));
    full_adder fa3(.a(A[3]), .b(B[3]), .c(C[2]), .sum(S[3]), .carry(C[3]));

    assign Cout = C[WIDTH-1];
endmodule
module full_adder(a, b, c, sum, carry);
    input a, b, c;
    output sum, carry;

    assign sum = a ^ b ^ c;
    assign carry = (a & b) | (b & c) | (a & c);
endmodule

sva:
module adder_sva #(
    parameter WIDTH = 4
) (
    input logic clk,
    input logic [WIDTH-1:0] A,
    input logic [WIDTH-1:0] B,
    input logic Cin,
    input logic [WIDTH-1:0] S,
    input logic Cout
);

    function automatic logic maj3(input logic x, input logic y, input logic z);
        maj3 = (x & y) | (y & z) | (x & z);
    endfunction

    generate
        if (WIDTH == 4) begin : gen_width4_assertions
            // The concatenated outputs must equal the 5-bit addition result.
            check_full_sum_relation: assert property (
                @(posedge clk) disable iff (1'b0)
                {Cout, S} == ({1'b0, A} + {1'b0, B} + Cin)
            );

            // Sum bit 0 must match the first full-adder XOR.
            check_sum_bit0: assert property (
                @(posedge clk) disable iff (1'b0)
                S[0] == (A[0] ^ B[0] ^ Cin)
            );

            // Sum bit 1 must use the carry from bit 0.
            check_sum_bit1: assert property (
                @(posedge clk) disable iff (1'b0)
                S[1] == (A[1] ^ B[1] ^ maj3(A[0], B[0], Cin))
            );

            // Sum bit 2 must use the carry from bit 1.
            check_sum_bit2: assert property (
                @(posedge clk) disable iff (1'b0)
                S[2] == (A[2] ^ B[2] ^ maj3(A[1], B[1], maj3(A[0], B[0], Cin)))
            );

            // Sum bit 3 must use the carry from bit 2.
            check_sum_bit3: assert property (
                @(posedge clk) disable iff (1'b0)
                S[3] == (A[3] ^ B[3] ^ maj3(A[2], B[2], maj3(A[1], B[1], maj3(A[0], B[0], Cin))))
            );

            // Cout must match the carry out of the final full adder.
            check_cout_chain: assert property (
                @(posedge clk) disable iff (1'b0)
                Cout == maj3(A[3], B[3], maj3(A[2], B[2], maj3(A[1], B[1], maj3(A[0], B[0], Cin))))
            );
        end
    endgenerate

endmodule

module up_counter_sva (
    input logic       clk,
    input logic       reset,
    input logic       load,
    input logic [3:0] load_value,
    input logic [3:0] count
);

    // A low reset forces the counter to zero by the next sampled clock.
    check_reset_clears_count: assert property (
        @(posedge clk) (!reset) |=> (count == 4'b0000)
    );

    // A load cycle copies load_value into count.
    check_load_updates_count: assert property (
        @(posedge clk) disable iff (!reset)
        (load == 1'b1) |=> (count == $past(load_value))
    );

    // A non-load cycle increments count when it is not at maximum.
    check_increment_no_wrap: assert property (
        @(posedge clk) disable iff (!reset)
        ((load == 1'b0) && (count != 4'hF)) |=> (count == ($past(count) + 4'd1))
    );

    // A non-load cycle wraps count from 4'hF to 4'h0.
    check_increment_wraps_to_zero: assert property (
        @(posedge clk) disable iff (!reset)
        ((load == 1'b0) && (count == 4'hF)) |=> (count == 4'h0)
    );

    // Every active cycle follows the RTL next-state relation.
    check_next_state_relation: assert property (
        @(posedge clk) disable iff (!reset)
        1'b1 |=> (
            (($past(load) == 1'b1) && (count == $past(load_value))) ||
            (($past(load) == 1'b0) && (count == ($past(count) + 4'd1)))
        )
    );

endmodule

rtl:
module CLKSKW(
	input CLKI,
	input [3:0] SKW,
	input RST,
	output reg CLKO
);

	reg [3:0] delay_reg;

	always @(posedge CLKI or posedge RST) begin
		if (RST) begin
			CLKO <= 1'b0;
			delay_reg <= 4'b0;
		end
		else begin
			delay_reg <= {delay_reg[2:0], CLKI};
			if (SKW[3]) begin
				CLKO <= delay_reg[SKW[2:0]] & ~delay_reg[SKW[2:0]-1];
			end
			else begin
				CLKO <= delay_reg[SKW[2:0]] & ~delay_reg[SKW[2:0]+1];
			end
		end
	end

endmodule

sva:
module CLKSKW_sva (
    input logic       CLKI,
    input logic [3:0] SKW,
    input logic       RST,
    input logic       CLKO,
    input logic [3:0] delay_reg
);

    // A sampled reset leaves both registers cleared at the next clock sample.
    check_state_zero_after_sampled_reset: assert property (
        @(posedge CLKI) disable iff ($initstate)
        $past(RST) |-> ((CLKO == 1'b0) && (delay_reg == 4'b0000))
    );

    // Without a sampled reset, delay_reg shifts in a 1 or is asynchronously cleared to zero.
    check_delay_reg_update_or_async_reset: assert property (
        @(posedge CLKI) disable iff ($initstate || RST)
        !$past(RST) |-> ((delay_reg == {$past(delay_reg[2:0]), 1'b1}) || (delay_reg == 4'b0000))
    );

    // Any nonzero delay_reg value must have a 1 in bit 0.
    check_nonzero_delay_reg_has_lsb_one: assert property (
        @(posedge CLKI) disable iff ($initstate || RST)
        (delay_reg != 4'b0000) |-> (delay_reg[0] == 1'b1)
    );

    // A cleared delay register also keeps CLKO low.
    check_zero_delay_reg_implies_zero_clko: assert property (
        @(posedge CLKI) disable iff ($initstate || RST)
        (delay_reg == 4'b0000) |-> (CLKO == 1'b0)
    );

    // For SKW=0000, CLKO reflects delay_reg[0] & ~delay_reg[1] from the prior cycle.
    check_clko_skw_0000_select: assert property (
        @(posedge CLKI) disable iff ($initstate || RST)
        (!$past(RST) && ($past(SKW) == 4'b0000)) |->
        (((delay_reg == 4'b0000) && (CLKO == 1'b0)) ||
         (CLKO == ($past(delay_reg[0]) & ~$past(delay_reg[1]))))
    );

    // For SKW=0001, CLKO reflects delay_reg[1] & ~delay_reg[2] from the prior cycle.
    check_clko_skw_0001_select: assert property (
        @(posedge CLKI) disable iff ($initstate || RST)
        (!$past(RST) && ($past(SKW) == 4'b0001)) |->
        (((delay_reg == 4'b0000) && (CLKO == 1'b0)) ||
         (CLKO == ($past(delay_reg[1]) & ~$past(delay_reg[2]))))
    );

    // For SKW=0010, CLKO reflects delay_reg[2] & ~delay_reg[3] from the prior cycle.
    check_clko_skw_0010_select: assert property (
        @(posedge CLKI) disable iff ($initstate || RST)
        (!$past(RST) && ($past(SKW) == 4'b0010)) |->
        (((delay_reg == 4'b0000) && (CLKO == 1'b0)) ||
         (CLKO == ($past(delay_reg[2]) & ~$past(delay_reg[3]))))
    );

    // For SKW=1001, CLKO reflects delay_reg[1] & ~delay_reg[0] from the prior cycle.
    check_clko_skw_1001_select: assert property (
        @(posedge CLKI) disable iff ($initstate || RST)
        (!$past(RST) && ($past(SKW) == 4'b1001)) |->
        (((delay_reg == 4'b0000) && (CLKO == 1'b0)) ||
         (CLKO == ($past(delay_reg[1]) & ~$past(delay_reg[0]))))
    );

    // For SKW=1010, CLKO reflects delay_reg[2] & ~delay_reg[1] from the prior cycle.
    check_clko_skw_1010_select: assert property (
        @(posedge CLKI) disable iff ($initstate || RST)
        (!$past(RST) && ($past(SKW) == 4'b1010)) |->
        (((delay_reg == 4'b0000) && (CLKO == 1'b0)) ||
         (CLKO == ($past(delay_reg[2]) & ~$past(delay_reg[1]))))
    );

    // For SKW=1011, CLKO reflects delay_reg[3] & ~delay_reg[2] from the prior cycle.
    check_clko_skw_1011_select: assert property (
        @(posedge CLKI) disable iff ($initstate || RST)
        (!$past(RST) && ($past(SKW) == 4'b1011)) |->
        (((delay_reg == 4'b0000) && (CLKO == 1'b0)) ||
         (CLKO == ($past(delay_reg[3]) & ~$past(delay_reg[2]))))
    );

endmodule

module d_flip_flop_sva (
    input logic D,
    input logic CLK,
    input logic RESET,
    input logic SET,
    input logic Q
);

    // Active-low reset clears Q by the next sampled clock.
    check_reset_clears_q: assert property (
        @(posedge CLK) !RESET |=> (Q == 1'b0)
    );

    // With reset inactive and SET low, D=0 is captured into Q.
    check_capture_zero_when_set_low: assert property (
        @(posedge CLK) disable iff (!RESET) (!SET && !D) |=> (Q == 1'b0)
    );

    // A high Q must come from a prior SET or a prior D=1 when reset was inactive.
    check_q_high_has_valid_source: assert property (
        @(posedge CLK) disable iff (!RESET)
        (!$initstate && Q) |-> ($past(RESET) && ($past(SET) || $past(D)))
    );

    // If prior D was 0, a high Q must have been caused by SET.
    check_q_high_with_d_zero_requires_set: assert property (
        @(posedge CLK) disable iff (!RESET)
        (!$initstate && Q && !$past(D)) |-> ($past(RESET) && $past(SET))
    );

    // If prior SET was 0, a high Q must have come from D=1.
    check_q_high_with_set_low_requires_d: assert property (
        @(posedge CLK) disable iff (!RESET)
        (!$initstate && Q && !$past(SET)) |-> ($past(RESET) && $past(D))
    );

endmodule

rtl:
module pcmb_tables(
		input [3:0] TABLE_B1_ADDR,
		output reg [4:0] TABLE_B1_OUT,
		input [2:0] TABLE_B2_ADDR,		output reg [7:0] TABLE_B2_OUT
	);

	always @(TABLE_B1_ADDR)
	begin
		case (TABLE_B1_ADDR)
			4'h0 : TABLE_B1_OUT <= 5'd1;
			4'h1 : TABLE_B1_OUT <= 5'd3;
			4'h2 : TABLE_B1_OUT <= 5'd5;
			4'h3 : TABLE_B1_OUT <= 5'd7;
			4'h4 : TABLE_B1_OUT <= 5'd9;
			4'h5 : TABLE_B1_OUT <= 5'd11;
			4'h6 : TABLE_B1_OUT <= 5'd13;
			4'h7 : TABLE_B1_OUT <= 5'd15;
			4'h8 : TABLE_B1_OUT <= -5'd1;
			4'h9 : TABLE_B1_OUT <= -5'd3;
			4'hA : TABLE_B1_OUT <= -5'd5;
			4'hB : TABLE_B1_OUT <= -5'd7;
			4'hC : TABLE_B1_OUT <= -5'd9;
			4'hD : TABLE_B1_OUT <= -5'd11;
			4'hE : TABLE_B1_OUT <= -5'd13;
			4'hF : TABLE_B1_OUT <= -5'd15;
		endcase
	end

	always @(TABLE_B2_ADDR)
	begin
		case (TABLE_B2_ADDR)
			3'h0 : TABLE_B2_OUT <= 8'd57;		3'h1 : TABLE_B2_OUT <= 8'd57;
			3'h2 : TABLE_B2_OUT <= 8'd57;
			3'h3 : TABLE_B2_OUT <= 8'd57;
			3'h4 : TABLE_B2_OUT <= 8'd77;
			3'h5 : TABLE_B2_OUT <= 8'd102;
			3'h6 : TABLE_B2_OUT <= 8'd128;
			3'h7 : TABLE_B2_OUT <= 8'd153;
		endcase
	end

endmodule

