rtl:
module memmap(

    input a15, a14, // Z80 address signals

    input mreq_n, rd_n, wr_n, // Z80 bus control signals

    input mode_ramro, mode_norom, // control signals for read-only memory and ROM mode, respectively

    input [7:0] mode_pg0, mode_pg1, mode_pg2, mode_pg3, // page select signals for the lower 16KB of memory

    output reg mema14, mema15, mema16, mema17, mema18, mema21, // memory address signals

    output reg ram0cs_n, ram1cs_n, ram2cs_n, ram3cs_n, // chip select signals for the four RAM chips

    output reg romcs_n, // chip select signal for the ROM chip

    output reg memoe_n, memwe_n // memory control signals

);

    // internal vars and regs

    reg [7:0] high_addr;

    // addresses mapping

    always @*
    begin
        case( {a15,a14} )
            2'b00: // $0000-$3FFF
                high_addr <= mode_pg0;
            2'b01: // $4000-$7FFF
                high_addr <= mode_pg1;
            2'b10: // $8000-$BFFF
                high_addr <= mode_pg2;
            2'b11: // $C000-$FFFF
                high_addr <= mode_pg3;
        endcase
    end

    // memory addresses

    always @*
    begin
        { mema21, mema18, mema17, mema16, mema15, mema14 } <= { high_addr[7], high_addr[4:0] };
    end

    // memory chip selects

    always @*
    begin
        if( (mode_norom==1'b0) && ( {a15,a14}!=2'b01 ) ) // ROM selected
        begin
            romcs_n <= 1'b0;

            ram0cs_n <= 1'b1;
            ram1cs_n <= 1'b1;
            ram2cs_n <= 1'b1;
            ram3cs_n <= 1'b1;
        end
        else // RAM
        begin
            romcs_n <= 1'b1;

            ram0cs_n <= ( high_addr[6:5]==2'b00 ) ? 1'b0 : 1'b1;
            ram1cs_n <= ( high_addr[6:5]==2'b01 ) ? 1'b0 : 1'b1;
            ram2cs_n <= ( high_addr[6:5]==2'b10 ) ? 1'b0 : 1'b1;
            ram3cs_n <= ( high_addr[6:5]==2'b11 ) ? 1'b0 : 1'b1;
        end
    end

    // memory /OE and /WE

    always @*
    begin
        memoe_n <= mreq_n | rd_n;

        if( (high_addr[6:1] == 6'd0) && (mode_ramro==1'b1) && (mode_norom==1'b1) ) // R/O
            memwe_n <= 1'b1;
        else // no R/O
            memwe_n <= mreq_n | wr_n;
    end

endmodule

sva:
module memmap_sva(
    input logic a15,
    input logic a14,
    input logic mreq_n,
    input logic rd_n,
    input logic wr_n,
    input logic mode_ramro,
    input logic mode_norom,
    input logic [7:0] mode_pg0,
    input logic [7:0] mode_pg1,
    input logic [7:0] mode_pg2,
    input logic [7:0] mode_pg3,
    input logic mema14,
    input logic mema15,
    input logic mema16,
    input logic mema17,
    input logic mema18,
    input logic mema21,
    input logic ram0cs_n,
    input logic ram1cs_n,
    input logic ram2cs_n,
    input logic ram3cs_n,
    input logic romcs_n,
    input logic memoe_n,
    input logic memwe_n
);

    function automatic logic [7:0] selected_page(
        input logic a15_i,
        input logic a14_i,
        input logic [7:0] pg0_i,
        input logic [7:0] pg1_i,
        input logic [7:0] pg2_i,
        input logic [7:0] pg3_i
    );
        begin
            case ({a15_i, a14_i})
                2'b00: selected_page = pg0_i;
                2'b01: selected_page = pg1_i;
                2'b10: selected_page = pg2_i;
                default: selected_page = pg3_i;
            endcase
        end
    endfunction

    function automatic logic [5:0] expected_mema(
        input logic a15_i,
        input logic a14_i,
        input logic [7:0] pg0_i,
        input logic [7:0] pg1_i,
        input logic [7:0] pg2_i,
        input logic [7:0] pg3_i
    );
        logic [7:0] page;
        begin
            page = selected_page(a15_i, a14_i, pg0_i, pg1_i, pg2_i, pg3_i);
            expected_mema = {page[7], page[4:0]};
        end
    endfunction

    function automatic logic [1:0] expected_ram_bank(
        input logic a15_i,
        input logic a14_i,
        input logic [7:0] pg0_i,
        input logic [7:0] pg1_i,
        input logic [7:0] pg2_i,
        input logic [7:0] pg3_i
    );
        logic [7:0] page;
        begin
            page = selected_page(a15_i, a14_i, pg0_i, pg1_i, pg2_i, pg3_i);
            expected_ram_bank = page[6:5];
        end
    endfunction

    function automatic logic rom_path_selected(
        input logic a15_i,
        input logic a14_i,
        input logic mode_norom_i
    );
        begin
            rom_path_selected = (mode_norom_i == 1'b0) && ({a15_i, a14_i} != 2'b01);
        end
    endfunction

    function automatic logic ro_block_active(
        input logic a15_i,
        input logic a14_i,
        input logic mode_ramro_i,
        input logic mode_norom_i,
        input logic [7:0] pg0_i,
        input logic [7:0] pg1_i,
        input logic [7:0] pg2_i,
        input logic [7:0] pg3_i
    );
        logic [7:0] page;
        begin
            page = selected_page(a15_i, a14_i, pg0_i, pg1_i, pg2_i, pg3_i);
            ro_block_active = (page[6:1] == 6'd0) && (mode_ramro_i == 1'b1) && (mode_norom_i == 1'b1);
        end
    endfunction

    // Checks memory address outputs use the selected page bits.
    check_mema_mapping: assert property (
        @($global_clock)
        {mema21, mema18, mema17, mema16, mema15, mema14} ==
        expected_mema(a15, a14, mode_pg0, mode_pg1, mode_pg2, mode_pg3)
    );

    // Checks ROM path forces ROM active and all RAM chips inactive.
    check_rom_select: assert property (
        @($global_clock)
        rom_path_selected(a15, a14, mode_norom) |->
        ((romcs_n == 1'b0) &&
         (ram0cs_n == 1'b1) &&
         (ram1cs_n == 1'b1) &&
         (ram2cs_n == 1'b1) &&
         (ram3cs_n == 1'b1))
    );

    // Checks ROM stays inactive whenever the RAM path is selected.
    check_rom_deselected_in_ram_path: assert property (
        @($global_clock)
        (!rom_path_selected(a15, a14, mode_norom)) |->
        (romcs_n == 1'b1)
    );

    // Checks RAM0 select decodes bank 00 on the RAM path.
    check_ram0_decode: assert property (
        @($global_clock)
        (!rom_path_selected(a15, a14, mode_norom)) |->
        (ram0cs_n == ((expected_ram_bank(a15, a14, mode_pg0, mode_pg1, mode_pg2, mode_pg3) == 2'b00) ? 1'b0 : 1'b1))
    );

    // Checks RAM1 select decodes bank 01 on the RAM path.
    check_ram1_decode: assert property (
        @($global_clock)
        (!rom_path_selected(a15, a14, mode_norom)) |->
        (ram1cs_n == ((expected_ram_bank(a15, a14, mode_pg0, mode_pg1, mode_pg2, mode_pg3) == 2'b01) ? 1'b0 : 1'b1))
    );

    // Checks RAM2 select decodes bank 10 on the RAM path.
    check_ram2_decode: assert property (
        @($global_clock)
        (!rom_path_selected(a15, a14, mode_norom)) |->
        (ram2cs_n == ((expected_ram_bank(a15, a14, mode_pg0, mode_pg1, mode_pg2, mode_pg3) == 2'b10) ? 1'b0 : 1'b1))
    );

    // Checks RAM3 select decodes bank 11 on the RAM path.
    check_ram3_decode: assert property (
        @($global_clock)
        (!rom_path_selected(a15, a14, mode_norom)) |->
        (ram3cs_n == ((expected_ram_bank(a15, a14, mode_pg0, mode_pg1, mode_pg2, mode_pg3) == 2'b11) ? 1'b0 : 1'b1))
    );

    // Checks /OE is the OR of MREQ and RD.
    check_memoe_decode: assert property (
        @($global_clock)
        memoe_n == (mreq_n | rd_n)
    );

    // Checks read-only pages block writes when RAM R/O mode is enabled.
    check_memwe_ro_block: assert property (
        @($global_clock)
        ro_block_active(a15, a14, mode_ramro, mode_norom, mode_pg0, mode_pg1, mode_pg2, mode_pg3) |->
        (memwe_n == 1'b1)
    );

    // Checks /WE otherwise follows the OR of MREQ and WR.
    check_memwe_decode: assert property (
        @($global_clock)
        (!ro_block_active(a15, a14, mode_ramro, mode_norom, mode_pg0, mode_pg1, mode_pg2, mode_pg3)) |->
        (memwe_n == (mreq_n | wr_n))
    );

endmodule

rtl:
module priority_encoder (
  input clk, rst,
  input [3:0] in,
  output reg [1:0] out
);

  always @(posedge clk, posedge rst) begin
    if (rst) begin
      out <= 2'b00;
    end else begin
      casez(in)
        4'b0001: out <= 2'b00;
        4'b0010: out <= 2'b01;
        4'b0100: out <= 2'b10;
        4'b1000: out <= 2'b11;
        default: out <= 2'b00;
      endcase
    end
  end

endmodule

sva:
module priority_encoder_sva (
    input logic       clk,
    input logic       rst,
    input logic [3:0] in,
    input logic [1:0] out
);

    // Reset forces the registered output to 00.
    check_reset_drives_out_zero: assert property (
        @(posedge clk) rst |=> (out == 2'b00)
    );

    // Input 0001 updates the output to 00 on the next clock.
    check_input_0001_maps_to_00: assert property (
        @(posedge clk) disable iff (rst)
        (in == 4'b0001) |=> (out == 2'b00)
    );

    // Input 0010 updates the output to 01 on the next clock.
    check_input_0010_maps_to_01: assert property (
        @(posedge clk) disable iff (rst)
        (in == 4'b0010) |=> (out == 2'b01)
    );

    // Input 0100 updates the output to 10 on the next clock.
    check_input_0100_maps_to_10: assert property (
        @(posedge clk) disable iff (rst)
        (in == 4'b0100) |=> (out == 2'b10)
    );

    // Input 1000 updates the output to 11 on the next clock.
    check_input_1000_maps_to_11: assert property (
        @(posedge clk) disable iff (rst)
        (in == 4'b1000) |=> (out == 2'b11)
    );

    // Any other input pattern updates the output to 00 on the next clock.
    check_all_other_inputs_map_to_00: assert property (
        @(posedge clk) disable iff (rst)
        ((in != 4'b0001) && (in != 4'b0010) && (in != 4'b0100) && (in != 4'b1000)) |=> (out == 2'b00)
    );

endmodule

rtl:
module comparator #(
  parameter n = 8 // number of bits in input numbers

) (
  input [n-1:0] num1,
  input [n-1:0] num2,
  input cmp_mode,
  output gt,
  output eq,
  output lt
);


reg signed [n-1:0] signed_num1;
reg signed [n-1:0] signed_num2;
reg [n-1:0] unsigned_num1;
reg [n-1:0] unsigned_num2;

assign gt = (cmp_mode == 0) ? (unsigned_num1 > unsigned_num2) : (signed_num1 > signed_num2);
assign eq = (cmp_mode == 0) ? (unsigned_num1 == unsigned_num2) : (signed_num1 == signed_num2);
assign lt = (cmp_mode == 0) ? (unsigned_num1 < unsigned_num2) : (signed_num1 < signed_num2);

always @(*) begin
  if (cmp_mode == 0) begin // unsigned comparison
    unsigned_num1 = num1;
    unsigned_num2 = num2;
    signed_num1 = {1'b0, num1};
    signed_num2 = {1'b0, num2};
  end else begin // signed comparison
    unsigned_num1 = num1;
    unsigned_num2 = num2;
    signed_num1 = num1;
    signed_num2 = num2;
  end
end

endmodule

sva:
module comparator_sva #(
  parameter n = 8
) (
  input logic clk,
  input logic [n-1:0] num1,
  input logic [n-1:0] num2,
  input logic cmp_mode,
  input logic gt,
  input logic eq,
  input logic lt
);

  // In unsigned mode, gt matches the unsigned comparison.
  check_unsigned_gt: assert property (
    @(posedge clk) (cmp_mode === 1'b0) |-> (gt === (num1 > num2))
  );

  // In unsigned mode, eq matches the unsigned comparison.
  check_unsigned_eq: assert property (
    @(posedge clk) (cmp_mode === 1'b0) |-> (eq === (num1 == num2))
  );

  // In unsigned mode, lt matches the unsigned comparison.
  check_unsigned_lt: assert property (
    @(posedge clk) (cmp_mode === 1'b0) |-> (lt === (num1 < num2))
  );

  // In signed mode, gt matches the signed comparison.
  check_signed_gt: assert property (
    @(posedge clk) (cmp_mode === 1'b1) |-> (gt === ($signed(num1) > $signed(num2)))
  );

  // In signed mode, eq matches the signed comparison.
  check_signed_eq: assert property (
    @(posedge clk) (cmp_mode === 1'b1) |-> (eq === ($signed(num1) == $signed(num2)))
  );

  // In signed mode, lt matches the signed comparison.
  check_signed_lt: assert property (
    @(posedge clk) (cmp_mode === 1'b1) |-> (lt === ($signed(num1) < $signed(num2)))
  );

  // Equality is independent of comparison mode.
  check_eq_mode_independent: assert property (
    @(posedge clk) (eq === (num1 == num2))
  );

  // Exactly one comparison result is asserted.
  check_results_complete_and_exclusive: assert property (
    @(posedge clk) ((gt || eq || lt) && !(gt && eq) && !(gt && lt) && !(eq && lt))
  );

  // Equal inputs produce only the equality result.
  check_equal_inputs_select_eq_only: assert property (
    @(posedge clk) (num1 == num2) |-> (eq && !gt && !lt)
  );

endmodule

rtl:
module nios_dut_nios2_gen2_0_cpu_nios2_oci_fifo_wrptr_inc (
  input ge2_free,
  input ge3_free,
  input [1:0] input_tm_cnt,
  output reg [3:0] fifo_wrptr_inc
);

  always @(*) begin
    if (ge3_free && (input_tm_cnt == 2'b11))
      fifo_wrptr_inc = 4'b0011;
    else if (ge2_free && (input_tm_cnt >= 2))
      fifo_wrptr_inc = 4'b0010;
    else if (input_tm_cnt >= 1)
      fifo_wrptr_inc = 4'b0001;
    else
      fifo_wrptr_inc = 4'b0000;
  end

endmodule

sva:
module nios_dut_nios2_gen2_0_cpu_nios2_oci_fifo_wrptr_inc_sva (
    input logic       ge2_free,
    input logic       ge3_free,
    input logic [1:0] input_tm_cnt,
    input logic [3:0] fifo_wrptr_inc
);

    // Output must match the RTL's combinational branch ordering.
    check_output_matches_rtl: assert property (
        @($global_clock)
        fifo_wrptr_inc == (
            (ge3_free && (input_tm_cnt == 2'b11)) ? 4'b0011 :
            (ge2_free && (input_tm_cnt >= 2'd2)) ? 4'b0010 :
            (input_tm_cnt >= 2'd1)               ? 4'b0001 :
                                                   4'b0000
        )
    );

    // The ge3_free path has highest priority when the count is 3.
    check_ge3_priority: assert property (
        @($global_clock)
        (ge3_free && (input_tm_cnt == 2'b11)) |-> (fifo_wrptr_inc == 4'b0011)
    );

    // The ge2_free path selects an increment of 2 when the ge3_free path is not taken.
    check_ge2_branch: assert property (
        @($global_clock)
        (!(ge3_free && (input_tm_cnt == 2'b11)) &&
         ge2_free &&
         (input_tm_cnt >= 2'd2)) |-> (fifo_wrptr_inc == 4'b0010)
    );

    // The fallback nonzero path selects an increment of 1 when earlier paths are not taken.
    check_single_increment_branch: assert property (
        @($global_clock)
        (!(ge3_free && (input_tm_cnt == 2'b11)) &&
         !(ge2_free && (input_tm_cnt >= 2'd2)) &&
         (input_tm_cnt >= 2'd1)) |-> (fifo_wrptr_inc == 4'b0001)
    );

    // A zero input count produces a zero increment.
    check_zero_count_branch: assert property (
        @($global_clock)
        (input_tm_cnt == 2'd0) |-> (fifo_wrptr_inc == 4'b0000)
    );

    // The upper two output bits are always zero.
    check_upper_bits_zero: assert property (
        @($global_clock)
        fifo_wrptr_inc[3:2] == 2'b00
    );

endmodule

