    check_output_low_when_vpwr_low: assert property (
        @($global_clock) (VPWR === 1'b0) |-> (X === 1'b0)
    );

    // X must be low when VGND is low.
    check_output_low_when_vgnd_low: assert property (
        @($global_clock) (VGND === 1'b0) |-> (X === 1'b0)
    );

