    check_vnb_independent_of_output: assert property (
        @($global_clock)
        (!$initstate && $changed(VNB) && $stable(A) && $stable(B) && $stable(C) && $stable(VPWR) && $stable(VGND) && $stable(VPB))
        |-> $stable(X)
    );

