	assign cts_n = 1'b0;

	wire	tx_busy;
`ifdef	USE_LITE_UART
	txuartlite #(24'd868)
		transmitter(i_clk, rx_stb, rx_data, o_uart_tx, tx_busy);
`else
	txuart	transmitter(i_clk, pwr_reset, i_setup, rx_break,
			rx_stb, rx_data, rts, o_uart_tx, tx_busy);
`endif
	`endif	endmodule

sva:
module echotest_sva (
    input logic i_clk,
    input logic i_uart_rx,
    input logic o_uart_tx
);

    // TX is the prior sampled value of RX.
    check_registered_echo: assert property (
        @(posedge i_clk) 1'b1 |=> (o_uart_tx == $past(i_uart_rx))
    );

    // An RX rising edge appears on TX one clock later.
    check_rise_propagates: assert property (
        @(posedge i_clk) $rose(i_uart_rx) |=> $rose(o_uart_tx)
    );

    // An RX falling edge appears on TX one clock later.
    check_fall_propagates: assert property (
        @(posedge i_clk) $fell(i_uart_rx) |=> $fell(o_uart_tx)
    );

    // Stable RX across a cycle yields stable TX on the next cycle.
    check_stable_propagates: assert property (
        @(posedge i_clk) $stable(i_uart_rx) |=> $stable(o_uart_tx)
    );

    // Changed RX across a cycle yields changed TX on the next cycle.
    check_change_propagates: assert property (
        @(posedge i_clk) $changed(i_uart_rx) |=> $changed(o_uart_tx)
    );

endmodule

rtl:
module up_counter(reset, clk, q);
input reset, clk;
output [15:0] q;

reg [15:0] count;

always @(posedge clk) begin
    if (reset) begin
        count <= 0;
    end else begin
        count <= count + 1;
    end
end

assign q = count;

endmodule

sva:
module up_counter_sva (
    input logic        reset,
    input logic        clk,
    input logic [15:0] q
);

    // q is zero on the first cycle after a reset cycle.
    check_q_zero_after_reset: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        $past(reset) |-> (q == 16'd0)
    );

    // q increments by one across consecutive non-reset cycles.
    check_q_increments_each_cycle: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        !$past(reset) |-> (q == ($past(q) + 16'd1))
    );

    // A non-reset increment from all ones wraps q to zero.
    check_q_wraps_from_max: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        (!$past(reset) && ($past(q) == 16'hFFFF)) |-> (q == 16'd0)
    );

    // A non-reset increment below the maximum increases q.
    check_q_increases_below_max: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        (!$past(reset) && ($past(q) != 16'hFFFF)) |-> (q > $past(q))
    );

endmodule

rtl:
module mux2to1 (
    input A,
    input B,
    input SEL,
    output X
);

    wire not_sel;
    wire and1, and2;
    wire or1;

    assign not_sel = ~SEL;
    assign and1 = A & not_sel;
    assign and2 = B & SEL;
    assign or1 = and1 | and2;
    assign X = or1;

endmodule

sva:
module mux2to1_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic SEL,
    input logic X
);

    // X must equal the selected input.
    check_mux_function: assert property (
        @(posedge clk) X == (SEL ? B : A)
    );

    // SEL low must route A to X.
    check_sel_low_routes_a: assert property (
        @(posedge clk) !SEL |-> (X == A)
    );

    // SEL high must route B to X.
    check_sel_high_routes_b: assert property (
        @(posedge clk) SEL |-> (X == B)
    );

    // Equal inputs must pass through regardless of SEL.
    check_equal_inputs_passthrough: assert property (
        @(posedge clk) (A == B) |-> (X == A)
    );

    // A=0 and B=1 makes X follow SEL.
    check_01_case: assert property (
        @(posedge clk) (!A && B) |-> (X == SEL)
    );

    // A=1 and B=0 makes X follow inverted SEL.
    check_10_case: assert property (
        @(posedge clk) (A && !B) |-> (X == ~SEL)
    );

endmodule

module jcarrylookaheadadder_sva (
    input logic        clk,
    input logic [3:0]  Y,
    input logic        carryout,
    input logic [3:0]  A,
    input logic [3:0]  B,
    input logic        carryin
);

    // Y[0] is the XOR of the LSB inputs and carryin.
    check_y0_lsb_sum: assert property (
        @(posedge clk) Y[0] == (A[0] ^ B[0] ^ carryin)
    );

    // Y[1] uses the carry generated or propagated from bit 0.
    check_y1_sum_with_bit0_carry: assert property (
        @(posedge clk)
        Y[1] == (A[1] ^ B[1] ^ ((A[0] & B[0]) | ((A[0] ^ B[0]) & carryin)))
    );

    // Y[2] uses the carry generated or propagated through bits 1:0.
    check_y2_sum_with_bit1to0_carry: assert property (
        @(posedge clk)
        Y[2] == (A[2] ^ B[2] ^
                 ((A[1] & B[1]) |
                  ((A[1] ^ B[1]) &
                   ((A[0] & B[0]) | ((A[0] ^ B[0]) & carryin)))))
    );

    // Y[3] uses the carry generated or propagated through bits 2:0.
    check_y3_sum_with_bit2to0_carry: assert property (
        @(posedge clk)
        Y[3] == (A[3] ^ B[3] ^
                 ((A[2] & B[2]) |
                  ((A[2] ^ B[2]) &
                   ((A[1] & B[1]) |
                    ((A[1] ^ B[1]) &
                     ((A[0] & B[0]) | ((A[0] ^ B[0]) & carryin)))))))
    );

    // Y matches the 4-bit sum of A, B, and carryin.
    check_y_matches_4bit_sum: assert property (
        @(posedge clk) Y == (A + B + carryin)
    );

    // carryout matches the RTL's c[4] equation.
    check_carryout_equation: assert property (
        @(posedge clk)
        carryout == ((A[0] & B[0]) |
                     ((A[0] ^ B[0]) &
                      ((A[2] & B[2]) |
                       ((A[2] ^ B[2]) &
                        ((A[1] & B[1]) |
                         ((A[1] ^ B[1]) &
                          ((A[0] & B[0]) |
                           ((A[0] ^ B[0]) & carryin))))))))
    );

    // carryout is low when bit 0 is 00.
    check_carryout_low_when_bit0_is_zero_zero: assert property (
        @(posedge clk) ((A[0] == 1'b0) && (B[0] == 1'b0)) |-> (carryout == 1'b0)
    );

    // carryout is high when bit 0 is 11.
    check_carryout_high_when_bit0_is_one_one: assert property (
        @(posedge clk) ((A[0] == 1'b1) && (B[0] == 1'b1)) |-> (carryout == 1'b1)
    );

endmodule

module mux_2to1_comb_sva (
    input logic clk,
    input logic a,
    input logic b,
    input logic sel_b1,
    input logic sel_b2,
    input logic out_always
);

    // Output must implement the mux function defined by the select inputs.
    check_mux_function_exact: assert property (
        @(posedge clk) out_always === (((sel_b1 === 1'b1) && (sel_b2 === 1'b1)) ? b : a)
    );

    // When both select inputs are high, the output must follow b.
    check_select_b_when_both_high: assert property (
        @(posedge clk) ((sel_b1 === 1'b1) && (sel_b2 === 1'b1)) |-> (out_always === b)
    );

    // In every other select case, the output must follow a.
    check_select_a_otherwise: assert property (
        @(posedge clk) ((sel_b1 !== 1'b1) || (sel_b2 !== 1'b1)) |-> (out_always === a)
    );

endmodule

rtl:
module full_adder(
    input A,
    input B,
    input Cin,
    output S,
    output Cout
);

assign S = A ^ B ^ Cin;
assign Cout = (A & B) | (Cin & (A ^ B));

endmodule

module adder_4bit(
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] S,
    output Cout
);

wire c1, c2, c3;

full_adder fa1(
    .A(A[0]),
    .B(B[0]),
    .Cin(Cin),
    .S(S[0]),
    .Cout(c1)
);

full_adder fa2(
    .A(A[1]),
    .B(B[1]),
    .Cin(c1),
    .S(S[1]),
    .Cout(c2)
);

full_adder fa3(
    .A(A[2]),
    .B(B[2]),
    .Cin(c2),
    .S(S[2]),
    .Cout(c3)
);

full_adder fa4(
    .A(A[3]),
    .B(B[3]),
    .Cin(c3),
    .S(S[3]),
    .Cout(Cout)
);

endmodule

sva:
module adder_4bit_sva(
    input logic [3:0] A,
    input logic [3:0] B,
    input logic Cin,
    input logic [3:0] S,
    input logic Cout,
    input logic clk
);

    // Combinational adder sampled on an external assertion clock; no reset is present in the RTL.

    // Combined sum and carry-out match 4-bit addition with carry-in.
    check_total_sum_value: assert property (
        @(posedge clk)
        {Cout, S} == ({1'b0, A} + {1'b0, B} + {4'b0000, Cin})
    );

    // Bit 0 sum matches the first full-adder XOR equation.
    check_sum_bit0_logic: assert property (
        @(posedge clk)
        S[0] == (A[0] ^ B[0] ^ Cin)
    );

    // Bit 1 sum uses the carry generated from bit 0.
    check_sum_bit1_logic: assert property (
        @(posedge clk)
        S[1] == (
            A[1] ^ B[1] ^
            ((A[0] & B[0]) | (Cin & (A[0] ^ B[0])))
        )
    );

    // Bit 2 sum uses the ripple carry generated through bit 1.
    check_sum_bit2_logic: assert property (
        @(posedge clk)
        S[2] == (
            A[2] ^ B[2] ^
            (
                (A[1] & B[1]) |
                (((A[0] & B[0]) | (Cin & (A[0] ^ B[0]))) & (A[1] ^ B[1]))
            )
        )
    );

    // Bit 3 sum uses the ripple carry generated through bit 2.
    check_sum_bit3_logic: assert property (
        @(posedge clk)
        S[3] == (
            A[3] ^ B[3] ^
            (
                (A[2] & B[2]) |
                (
                    (
                        (A[1] & B[1]) |
                        (((A[0] & B[0]) | (Cin & (A[0] ^ B[0]))) & (A[1] ^ B[1]))
                    ) &
                    (A[2] ^ B[2])
                )
            )
        )
    );

    // Carry-out matches the final full-adder carry equation.
    check_carry_out_logic: assert property (
        @(posedge clk)
        Cout == (
            (A[3] & B[3]) |
            (
                (
                    (A[2] & B[2]) |
                    (
                        (
                            (A[1] & B[1]) |
                            (((A[0] & B[0]) | (Cin & (A[0] ^ B[0]))) & (A[1] ^ B[1]))
                        ) &
                        (A[2] ^ B[2])
                    )
                ) &
                (A[3] ^ B[3])
            )
        )
    );

endmodule

rtl:
module decoder (
    input [3:0] in,
    output [15:0] out
);

    assign out = 16'b0000000000000001 << in;

endmodule

sva:
module decoder_sva (
    input logic clk,
    input logic [3:0] in,
    input logic [15:0] out
);

    // Output must equal the one-hot decode of the input.
    check_decode_equation: assert property (
        @(posedge clk) out == (16'h0001 << in)
    );

    // Decoder output must always be one-hot.
    check_output_onehot: assert property (
        @(posedge clk) $onehot(out)
    );

    // The bit selected by the input must be high.
    check_selected_bit_high: assert property (
        @(posedge clk) out[in] == 1'b1
    );

    // Input value 0 must select bit 0.
    check_decode_zero: assert property (
        @(posedge clk) (in == 4'd0) |-> (out == 16'h0001)
    );

    // Input value 15 must select bit 15.
    check_decode_fifteen: assert property (
        @(posedge clk) (in == 4'd15) |-> (out == 16'h8000)
    );

endmodule

rtl:
module logic_operation (
    input  A,
    input  B,
    input  C,
    input  D,
    output Y
);

    assign Y = (A & ~B) | (C & ~D);

endmodule

sva:
module logic_operation_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic Y
);

    // Y must match the implemented OR-of-ANDs logic.
    check_output_definition: assert property (
        @(posedge clk) Y == ((A & ~B) | (C & ~D))
    );

    // A high and B low must drive Y high.
    check_ab_term_sets_output: assert property (
        @(posedge clk) (A && !B) |-> Y
    );

    // C high and D low must drive Y high.
    check_cd_term_sets_output: assert property (
        @(posedge clk) (C && !D) |-> Y
    );

    // Y must be low when both product terms are false.
    check_output_low_when_both_terms_false: assert property (
        @(posedge clk) (!(A && !B) && !(C && !D)) |-> !Y
    );

endmodule

rtl:
module write_axi_8bit(
		 input clock_recovery,
		 input clock_50,
		 input reset_n,
		 input [7:0] data_rec,
		 output reg [7:0] data_stand	
		);


always@(posedge clock_50 or negedge reset_n )
begin

	if(!reset_n)
	begin
		data_stand <= 8'd0;
	end
	else
	begin
		if(clock_recovery)
			data_stand <= data_rec;
		else
			data_stand <= data_stand;
	end
end

endmodule

sva:
module write_axi_8bit_sva (
    input logic        clock_recovery,
    input logic        clock_50,
    input logic        reset_n,
    input logic [7:0]  data_rec,
    input logic [7:0]  data_stand
);

    // clock_50 is the sequential clock.
    // reset_n is an active-low reset.
    // data_stand conditionally captures data_rec when clock_recovery is high.

    // When reset is sampled low, data_stand is zero by the next clock sample.
    check_reset_clears_data_stand: assert property (
        @(posedge clock_50) !reset_n |=> (data_stand == 8'd0)
    );

    // The registered next value follows the RTL update function.
    check_registered_update_function: assert property (
        @(posedge clock_50) disable iff (!reset_n)
        1'b1 |=> (data_stand == ($past(clock_recovery) ? $past(data_rec) : $past(data_stand)))
    );

    // When clock_recovery is high, data_stand captures data_rec.
    check_capture_when_recovery_high: assert property (
        @(posedge clock_50) disable iff (!reset_n)
        clock_recovery |=> (data_stand == $past(data_rec))
    );

    // When clock_recovery is low, data_stand holds its previous value.
    check_hold_when_recovery_low: assert property (
        @(posedge clock_50) disable iff (!reset_n)
        !clock_recovery |=> (data_stand == $past(data_stand))
    );

endmodule

rtl:
module RegisterAdder
   (D,
    Q_reg_0,
    Q,
    Q_reg_2,
    CLK,
    AR);
  output [1:0] D;
  output [0:0] Q_reg_0;
  input [1:0] Q;
  input [1:0] Q_reg_2;
  input CLK;
  input AR;

  wire [1:0] D;
  wire [0:0] Q_reg_0;
  reg [1:0] Q_reg_temp; // Changed wire to reg

  assign D = Q + Q_reg_2;

  always @(posedge CLK, negedge AR) begin
    if (!AR) begin
      Q_reg_temp <= 2'b0;
    end else begin
      Q_reg_temp <= D; // Corrected the assignment
    end
  end

  assign Q_reg_0 = Q_reg_temp[0];

endmodule

sva:
module RegisterAdder_sva (
    input logic [1:0] D,
    input logic [0:0] Q_reg_0,
    input logic [1:0] Q,
    input logic [1:0] Q_reg_2,
    input logic CLK,
    input logic AR
);

    // D is always the 2-bit sum of Q and Q_reg_2.
    check_d_matches_sum: assert property (
        @(posedge CLK) disable iff (!AR) D == (Q + Q_reg_2)
    );

    // D[0] is the sum LSB of the two input words.
    check_d_lsb_matches_input_lsb_sum: assert property (
        @(posedge CLK) disable iff (!AR) D[0] == (Q[0] ^ Q_reg_2[0])
    );

    // D[1] includes the carry from bit 0.
    check_d_msb_matches_input_msb_sum: assert property (
        @(posedge CLK) disable iff (!AR) D[1] == (Q[1] ^ Q_reg_2[1] ^ (Q[0] & Q_reg_2[0]))
    );

    // Q_reg_0 captures the previous cycle's D[0] when not in reset.
    check_q_reg_0_captures_previous_d0: assert property (
        @(posedge CLK) disable iff (!AR) 1'b1 |=> (Q_reg_0[0] == $past(D[0]))
    );

    // After a sampled reset cycle, Q_reg_0 is still 0 on the next active clock.
    check_q_reg_0_zero_after_sampled_reset: assert property (
        @(posedge CLK) disable iff (!AR) $past(!AR) |-> (Q_reg_0[0] == 1'b0)
    );

endmodule

rtl:
module weak_not (
  input Z,
  output Y
);

  assign Y = ~Z;

endmodule

sva:
module weak_not_sva (
    input logic clk,
    input logic Z,
    input logic Y
);

    // Y must always be the bitwise inverse of Z.
    check_output_is_bitwise_inverse: assert property (
        @(posedge clk) (Y === ~Z)
    );

    // A high Z must produce a low Y.
    check_high_input_drives_low_output: assert property (
        @(posedge clk) (Z === 1'b1) |-> (Y === 1'b0)
    );

    // A low Z must produce a high Y.
    check_low_input_drives_high_output: assert property (
        @(posedge clk) (Z === 1'b0) |-> (Y === 1'b1)
    );

endmodule

rtl:
module full_adder(input A, input B, input Cin, output S, output Cout);
  assign S = A ^ B ^ Cin;
  assign Cout = (A & B) | (Cin & (A ^ B));
endmodule

sva:
module full_adder_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic Cin,
    input logic S,
    input logic Cout
);

    // Sum matches the three-input XOR equation.
    check_sum_equation: assert property (
        @(posedge clk) (S == (A ^ B ^ Cin))
    );

    // Carry matches the implemented carry equation.
    check_carry_equation: assert property (
        @(posedge clk) (Cout == ((A & B) | (Cin & (A ^ B))))
    );

    // 000 produces zero sum and zero carry.
    check_all_zero_case: assert property (
        @(posedge clk) (!A && !B && !Cin) |-> (!S && !Cout)
    );

    // 100 produces sum one and no carry.
    check_only_a_high_case: assert property (
        @(posedge clk) (A && !B && !Cin) |-> (S && !Cout)
    );

    // 010 produces sum one and no carry.
    check_only_b_high_case: assert property (
        @(posedge clk) (!A && B && !Cin) |-> (S && !Cout)
    );

    // 001 produces sum one and no carry.
    check_only_cin_high_case: assert property (
        @(posedge clk) (!A && !B && Cin) |-> (S && !Cout)
    );

    // 110 produces zero sum and carry one.
    check_a_b_high_case: assert property (
        @(posedge clk) (A && B && !Cin) |-> (!S && Cout)
    );

    // 101 produces zero sum and carry one.
    check_a_cin_high_case: assert property (
        @(posedge clk) (A && !B && Cin) |-> (!S && Cout)
    );

    // 011 produces zero sum and carry one.
    check_b_cin_high_case: assert property (
        @(posedge clk) (!A && B && Cin) |-> (!S && Cout)
    );

    // 111 produces sum one and carry one.
    check_all_high_case: assert property (
        @(posedge clk) (A && B && Cin) |-> (S && Cout)
    );

endmodule

rtl:
module MUX4X1 (A, B, C, D, S0, S1, Z);
input  A ;
input  B ;
input  C ;
input  D ;
input  S0 ;
input  S1 ;
output Z ;

wire  notS0, notS1, and1, and2, and3, and4;

not (notS0, S0);
not (notS1, S1);

and (and1, A, notS1, notS0);
and (and2, B, notS1, S0);
and (and3, C, S1, notS0);
and (and4, D, S1, S0);

or (Z, and1, and2, and3, and4);

endmodule

sva:
module MUX4X1_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic S0,
    input logic S1,
    input logic Z
);

    // Combinational 4:1 mux; RTL has no clock or reset, so clk is the sampling clock.

    // Z matches the RTL sum-of-products equation.
    check_output_matches_sop: assert property (
        @(posedge clk)
        Z == ((A & ~S1 & ~S0) |
              (B & ~S1 &  S0) |
              (C &  S1 & ~S0) |
              (D &  S1 &  S0))
    );

    // Z matches the selected input.
    check_output_matches_selected_input: assert property (
        @(posedge clk)
        Z == (S1 ? (S0 ? D : C) : (S0 ? B : A))
    );

    // When S1S0 is 00, Z routes A.
    check_select_00_routes_a: assert property (
        @(posedge clk)
        (!S1 && !S0) |-> (Z == A)
    );

    // When S1S0 is 01, Z routes B.
    check_select_01_routes_b: assert property (
        @(posedge clk)
        (!S1 && S0) |-> (Z == B)
    );

    // When S1S0 is 10, Z routes C.
    check_select_10_routes_c: assert property (
        @(posedge clk)
        (S1 && !S0) |-> (Z == C)
    );

    // When S1S0 is 11, Z routes D.
    check_select_11_routes_d: assert property (
        @(posedge clk)
        (S1 && S0) |-> (Z == D)
    );

endmodule

rtl:
module top_module(
    input [31:0] a,
    input [31:0] b,
    input sub,
    output [31:0] sum
);

wire [31:0] inverted_b;

assign inverted_b = sub ? ~b : b;

cla_adder_32bit adder(
    .a(a),
    .b(inverted_b),
    .cin(sub),
    .sum(sum)
);

endmodule
module cla_adder_32bit(
    input [31:0] a,
    input [31:0] b,
    input cin,
    output [31:0] sum
);

wire [31:0] g;
wire [31:0] p;
wire [31:0] c;

assign g = a & b;
assign p = a ^ b;
assign c[0] = cin;

genvar i;
generate
    for (i = 0; i < 31; i = i + 1) begin : gen
        assign c[i+1] = g[i] | (p[i] & c[i]);
        assign sum[i] = p[i] ^ c[i];
    end
endgenerate

assign sum[31] = p[31] ^ c[31]; // Driver for the last bit of sum

endmodule

sva:
module top_module_sva (
    input logic [31:0] a,
    input logic [31:0] b,
    input logic        sub,
    input logic [31:0] sum
);

    // Sum matches the add/subtract datapath function.
    check_functional_equivalence: assert property (
        @($global_clock) sum == (a + (sub ? ~b : b) + {{31{1'b0}}, sub})
    );

    // In add mode, the result is a + b.
    check_add_mode: assert property (
        @($global_clock) !sub |-> (sum == (a + b))
    );

    // In subtract mode, the result is a - b.
    check_sub_mode: assert property (
        @($global_clock) sub |-> (sum == (a - b))
    );

    // The least significant sum bit is always a[0] XOR b[0].
    check_lsb_xor: assert property (
        @($global_clock) sum[0] == (a[0] ^ b[0])
    );

    // Subtracting equal operands yields zero.
    check_equal_operands_subtract_zero: assert property (
        @($global_clock) (sub && (a == b)) |-> (sum == 32'h00000000)
    );

    // A zero b operand passes a through in both modes.
    check_zero_b_passthrough: assert property (
        @($global_clock) (b == 32'h00000000) |-> (sum == a)
    );

    // With a equal to zero in add mode, the result is b.
    check_zero_a_add_mode: assert property (
        @($global_clock) (!sub && (a == 32'h00000000)) |-> (sum == b)
    );

    // With a equal to zero in subtract mode, the result is two's complement of b.
    check_zero_a_sub_mode: assert property (
        @($global_clock) (sub && (a == 32'h00000000)) |-> (sum == (~b + 32'h00000001))
    );

    // Zero minus or plus zero yields zero.
    check_zero_operands_zero_sum: assert property (
        @($global_clock) ((a == 32'h00000000) && (b == 32'h00000000)) |-> (sum == 32'h00000000)
    );

    // Adding complementary operands yields all ones.
    check_add_complement_all_ones: assert property (
        @($global_clock) (!sub && (a == ~b)) |-> (sum == 32'hFFFFFFFF)
    );

endmodule

rtl:
module my_module (
    output X   ,
    input  A1  ,
    input  A2  ,
    input  B1  ,
    input  B2  ,
    input  VPWR,
    input  VGND,
    input  VPB ,
    input  VNB
);

    wire or0_out;
    wire or1_out;
    wire and0_out_X;

    or or0 (or0_out, A2, A1);
    or or1 (or1_out, B2, B1);
    and and0 (and0_out_X, or0_out, or1_out);
    assign X = and0_out_X & VPWR & ~VGND;

endmodule

sva:
module my_module_sva (
    input logic X,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic B2,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB
);

    // No RTL clock or reset is present; sample on the global formal clock.

    // X must match the implemented combinational logic.
    check_x_matches_logic: assert property (
        @($global_clock)
        X == (((A2 | A1) & (B2 | B1)) & VPWR & ~VGND)
    );

    // Ground asserted forces X low.
    check_vgnd_forces_x_low: assert property (
        @($global_clock)
        VGND |-> !X
    );

    // Power removed forces X low.
    check_vpwr_required_for_x: assert property (
        @($global_clock)
        !VPWR |-> !X
    );

    // If both A inputs are low, X must be low.
    check_a_or_required: assert property (
        @($global_clock)
        !(A2 | A1) |-> !X
    );

    // If both B inputs are low, X must be low.
    check_b_or_required: assert property (
        @($global_clock)
        !(B2 | B1) |-> !X
    );

    // When both input OR terms are high and power is good, X must be high.
    check_all_conditions_drive_x_high: assert property (
        @($global_clock)
        ((A2 | A1) & (B2 | B1) & VPWR & ~VGND) |-> X
    );

    // A high X requires both input OR terms and good power conditions.
    check_x_high_requires_valid_conditions: assert property (
        @($global_clock)
        X |-> ((A2 | A1) & (B2 | B1) & VPWR & ~VGND)
    );

endmodule

rtl:
module buffer_3input (
    Z   ,
    A   ,
    B   ,
    C   ,
    TE_B
);

    output Z   ;
    input  A   ;
    input  B   ;
    input  C   ;
    input  TE_B;

    wire sel1, sel2;

    assign sel1 = (A & ~B & ~C) | (~A & B & ~C) | (~A & ~B & C);
    assign sel2 = (A & B & ~C) | (A & ~B & C) | (~A & B & C);

    assign Z = TE_B & (sel1 | sel2) & (A | B | C);

endmodule

sva:
module buffer_3input_sva (
    input logic clk,
    input logic Z,
    input logic A,
    input logic B,
    input logic C,
    input logic TE_B
);

    // Z matches the implemented combinational equation.
    check_output_equation: assert property (
        @(posedge clk) Z == (TE_B & (A | B | C) & ~(A & B & C))
    );

    // TE_B low forces Z low.
    check_teb_low_forces_z_low: assert property (
        @(posedge clk) (TE_B == 1'b0) |-> (Z == 1'b0)
    );

    // All-zero inputs force Z low.
    check_all_zero_inputs_force_z_low: assert property (
        @(posedge clk) ((A == 1'b0) && (B == 1'b0) && (C == 1'b0)) |-> (Z == 1'b0)
    );

    // All-one inputs force Z low.
    check_all_one_inputs_force_z_low: assert property (
        @(posedge clk) ((A == 1'b1) && (B == 1'b1) && (C == 1'b1)) |-> (Z == 1'b0)
    );

    // With TE_B high, mixed data inputs drive Z high.
    check_enabled_mixed_inputs_force_z_high: assert property (
        @(posedge clk)
        ((TE_B == 1'b1) && ((A | B | C) == 1'b1) && ((A & B & C) == 1'b0))
        |-> (Z == 1'b1)
    );

    // A high output requires TE_B to be high.
    check_z_requires_teb_high: assert property (
        @(posedge clk) (Z == 1'b1) |-> (TE_B == 1'b1)
    );

    // A high output requires inputs to be neither all-zero nor all-one.
    check_z_requires_mixed_inputs: assert property (
        @(posedge clk) (Z == 1'b1) |-> (((A | B | C) == 1'b1) && ((A & B & C) == 1'b0))
    );

endmodule

rtl:
module xnor_nand( 
    input a, 
    input b, 
    output out );

    wire nand1, nand2, nand3;

    nand n1(nand1, a, b);
    nand n2(nand2, a, nand1);
    nand n3(nand3, b, nand1);
    nand n4(out, nand2, nand3);

endmodule

sva:
module xnor_nand_assertions (
    input logic a,
    input logic b,
    input logic out
);

    // Output is low when both inputs are low.
    check_00_drives_low: assert property (
        @($global_clock) ((a == 1'b0) && (b == 1'b0)) |-> (out == 1'b0)
    );

    // Output is high when only b is high.
    check_01_drives_high: assert property (
        @($global_clock) ((a == 1'b0) && (b == 1'b1)) |-> (out == 1'b1)
    );

    // Output is high when only a is high.
    check_10_drives_high: assert property (
        @($global_clock) ((a == 1'b1) && (b == 1'b0)) |-> (out == 1'b1)
    );

    // Output is low when both inputs are high.
    check_11_drives_low: assert property (
        @($global_clock) ((a == 1'b1) && (b == 1'b1)) |-> (out == 1'b0)
    );

    // Output always matches the XOR of the inputs.
    check_out_matches_xor: assert property (
        @($global_clock) out == (a ^ b)
    );

endmodule

rtl:
module dff_sr (
    input clk,
    input d,
    input set,
    input reset,
    output reg q,
    output reg q_n
);

always @(posedge clk) begin
    if (reset) begin
        q <= 0;
        q_n <= 1;
    end else if (set) begin
        q <= 1;
        q_n <= 0;
    end else begin
        q <= d;
        q_n <= ~d;
    end
end

endmodule

sva:
module dff_sr_sva (
    input logic clk,
    input logic d,
    input logic set,
    input logic reset,
    input logic q,
    input logic q_n
);

    // Clock: posedge clk.
    // Reset: synchronous active-high.
    // Behavior: reset has priority over set, then d is captured.

    // Reset drives q low and q_n high.
    check_reset_state: assert property (
        @(posedge clk) reset |=> (q == 1'b0 && q_n == 1'b1)
    );

    // Set drives q high and q_n low when reset is inactive.
    check_set_state: assert property (
        @(posedge clk) disable iff (reset) set |=> (q == 1'b1 && q_n == 1'b0)
    );

    // A low d is captured when set and reset are low.
    check_capture_zero: assert property (
        @(posedge clk) disable iff (reset) (!set && !d) |=> (q == 1'b0 && q_n == 1'b1)
    );

    // A high d is captured when set and reset are low.
    check_capture_one: assert property (
        @(posedge clk) disable iff (reset) (!set && d) |=> (q == 1'b1 && q_n == 1'b0)
    );

    // The outputs remain complementary after each clocked update.
    check_complementary_outputs: assert property (
        @(posedge clk) 1'b1 |=> (q_n == ~q)
    );

endmodule

rtl:
module ripple_carry_adder (
    input [3:0] A,
    input [3:0] B,
    output reg [3:0] OUT
);

    always @(*) begin
        OUT = A + B;
    end

endmodule

module barrel_shifter (
    input [15:0] data,
    input [3:0] shift_amount,
    input direction,
    output reg [15:0] q
);

    always @(*) begin
        if (direction == 1'b0) begin // shift left
            q = data << shift_amount;
        end else begin // shift right
            q = data >> shift_amount;
        end
    end

endmodule

module top_module (
    input [3:0] A,
    input [3:0] B,
    input [15:0] data,
    input [3:0] shift_amount,
    input direction,
    output reg [15:0] q
);

    wire [3:0] adder_out;
    wire [15:0] shifted_data;

    ripple_carry_adder adder_inst (
        .A(A),
        .B(B),
        .OUT(adder_out)
    );

    barrel_shifter shifter_inst (
        .data(data),
        .shift_amount(shift_amount),
        .direction(direction),
        .q(shifted_data)
    );

    always @(*) begin
        q = adder_out + shifted_data;
    end

endmodule

sva:
module top_module_assertions (
    input logic        clk,
    input logic [3:0]  A,
    input logic [3:0]  B,
    input logic [15:0] data,
    input logic [3:0]  shift_amount,
    input logic        direction,
    input logic [15:0] q
);

    // No DUT clock or reset; clk is an external sampling clock for this combinational RTL.
    // A and B form a 4-bit sum, data is shifted by shift_amount based on direction, and q adds both results.

    // In left mode, q is the left-shifted data plus the 4-bit sum of A and B.
    check_left_mode_result: assert property (
        @(posedge clk) (direction == 1'b0) |-> (q == ((data << shift_amount) + (A + B)))
    );

    // In right mode, q is the right-shifted data plus the 4-bit sum of A and B.
    check_right_mode_result: assert property (
        @(posedge clk) (direction == 1'b1) |-> (q == ((data >> shift_amount) + (A + B)))
    );

    // A zero shift amount passes data unchanged into the final addition.
    check_zero_shift_result: assert property (
        @(posedge clk) (shift_amount == 4'd0) |-> (q == (data + (A + B)))
    );

    // When the 4-bit sum is zero, left mode depends only on the shifter result.
    check_zero_sum_left_result: assert property (
        @(posedge clk) ((direction == 1'b0) && ((A + B) == 4'd0)) |-> (q == (data << shift_amount))
    );

    // When the 4-bit sum is zero, right mode depends only on the shifter result.
    check_zero_sum_right_result: assert property (
        @(posedge clk) ((direction == 1'b1) && ((A + B) == 4'd0)) |-> (q == (data >> shift_amount))
    );

    // With zero shift and zero 4-bit sum, q matches data exactly.
    check_zero_shift_zero_sum_passthrough: assert property (
        @(posedge clk) ((shift_amount == 4'd0) && ((A + B) == 4'd0)) |-> (q == data)
    );

    // With zero adder inputs in left mode, q is just the left-shifted data.
    check_zero_operands_left_result: assert property (
        @(posedge clk) ((direction == 1'b0) && (A == 4'd0) && (B == 4'd0)) |-> (q == (data << shift_amount))
    );

    // With zero adder inputs in right mode, q is just the right-shifted data.
    check_zero_operands_right_result: assert property (
        @(posedge clk) ((direction == 1'b1) && (A == 4'd0) && (B == 4'd0)) |-> (q == (data >> shift_amount))
    );

    // Stable inputs keep the combinational output stable.
    check_stable_inputs_hold_output: assert property (
        @(posedge clk) $stable({A, B, data, shift_amount, direction}) |-> $stable(q)
    );

endmodule

