module up_down_counter (
    input clk,
    input up_down,
    input reset,
    output reg [2:0] Q
);

    always @(posedge clk) begin
        if (reset) begin
            Q <= 3'b0;
        end else if (up_down) begin
            Q <= Q + 1;
        end else begin
            Q <= Q - 1;
        end
    end

endmodule

sva:
module up_down_counter_sva (
    input logic       clk,
    input logic       up_down,
    input logic       reset,
    input logic [2:0] Q
);

    // Reset clears the counter on the next clock.
    check_reset_clears_q: assert property (
        @(posedge clk) reset |=> (Q == 3'b000)
    );

    // When not in reset and counting up, Q increments by one.
    check_count_up: assert property (
        @(posedge clk) disable iff (reset)
        up_down |=> (Q == ($past(Q) + 3'd1))
    );

    // When not in reset and counting down, Q decrements by one.
    check_count_down: assert property (
        @(posedge clk) disable iff (reset)
        !up_down |=> (Q == ($past(Q) - 3'd1))
    );

    // Counting up from 7 wraps back to 0.
    check_wrap_up_from_max: assert property (
        @(posedge clk) disable iff (reset)
        (Q == 3'b111 && up_down) |=> (Q == 3'b000)
    );

    // Counting down from 0 wraps back to 7.
    check_wrap_down_from_zero: assert property (
        @(posedge clk) disable iff (reset)
        (Q == 3'b000 && !up_down) |=> (Q == 3'b111)
    );

endmodule

module calculator_sva (
    input logic       clk,
    input logic       rst,
    input logic [7:0] a,
    input logic [7:0] b,
    input logic       op,
    input logic [7:0] result
);

    // A sampled reset cycle leaves result cleared through the next clock edge.
    check_reset_clears_result: assert property (
        @(posedge clk) rst |=> (result == 8'h00)
    );

    // When add is selected, result updates to the prior cycle's a + b.
    check_add_result: assert property (
        @(posedge clk) disable iff (rst)
        (op == 1'b0) |=> (result == ($past(a) + $past(b)))
    );

    // When subtract is selected, result updates to the prior cycle's a - b.
    check_sub_result: assert property (
        @(posedge clk) disable iff (rst)
        (op == 1'b1) |=> (result == ($past(a) - $past(b)))
    );

endmodule

