module RCB_FRL_count_to_16x(
		input	clk, 
		input	rst, 
		input	count, 
		output [3:0]	counter_value
	);

reg [3:0] counter_value_preserver;

assign counter_value = counter_value_preserver;

always@(posedge clk or posedge rst) begin
	if(rst == 1'b1) begin
		counter_value_preserver = 4'h0;
	end else if ( count == 1'b1 ) begin
		counter_value_preserver = counter_value_preserver + 1;
	end else begin
		counter_value_preserver = counter_value;
	end
end

endmodule

sva:
module RCB_FRL_count_to_16x_sva (
    input logic       clk,
    input logic       rst,
    input logic       count,
    input logic [3:0] counter_value
);

    // A sampled reset must leave the counter at zero on the next sampled clock.
    check_reset_forces_zero_next_cycle: assert property (
        @(posedge clk) rst |=> (counter_value == 4'h0)
    );

    // Without count, the counter either holds or has been asynchronously cleared to zero.
    check_hold_or_async_reset_zero: assert property (
        @(posedge clk) disable iff (rst)
        (!count) |=> ((counter_value == $past(counter_value)) || (counter_value == 4'h0))
    );

    // With count asserted below 15, the counter either increments or has been asynchronously cleared to zero.
    check_increment_or_async_reset_zero: assert property (
        @(posedge clk) disable iff (rst)
        (count && (counter_value != 4'hf)) |=> ((counter_value == ($past(counter_value) + 4'h1)) || (counter_value == 4'h0))
    );

    // Counting from 15 wraps the 4-bit counter back to zero.
    check_wrap_from_f_to_zero: assert property (
        @(posedge clk) disable iff (rst)
        (count && (counter_value == 4'hf)) |=> (counter_value == 4'h0)
    );

    // Any nonzero change between sampled clocks must be a single-step increment caused by count.
    check_nonzero_change_is_increment: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        ((counter_value != 4'h0) && (counter_value != $past(counter_value))) |->
            ($past(count) && (counter_value == ($past(counter_value) + 4'h1)))
    );

    // Any retained nonzero value between sampled clocks must come from count being low.
    check_nonzero_hold_requires_no_count: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        ((counter_value != 4'h0) && (counter_value == $past(counter_value))) |->
            (!$past(count))
    );

endmodule

rtl:
module barrel_shift_encoder (
    input [3:0] A,
    input [1:0] shift,
    input enable,
    output [1:0] pos,
    output [3:0] out
);

reg [3:0] shifted_value;

always @(*) begin
    case(shift)
        2'b00: shifted_value = A;
        2'b01: shifted_value = {A[2:0], A[3]};
        2'b10: shifted_value = {A[1:0], A[3:2]};
        2'b11: shifted_value = {A[0], A[3:1]};
    endcase
end

priority_encoder pe(shifted_value, enable, pos);

assign out = shifted_value | (pos != 0);

endmodule

module priority_encoder (
    input [3:0] in,
    input enable,
    output reg [1:0] pos
);

always @(*) begin
    if (enable) begin
        case(in)
            4'b0001: pos = 0;
            4'b0010: pos = 1;
            4'b0100: pos = 2;
            4'b1000: pos = 3;
            default: pos = 0;
        endcase
    end
    else begin
        pos = 0;
    end
end

endmodule

module top_module (
    input [3:0] A,
    input [1:0] shift,
    input [3:0] in,
    input enable,
    output [1:0] pos,
    output [3:0] out
);

barrel_shift_encoder bse(A, shift, enable, pos, out);

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [1:0] shift,
    input logic [3:0] in,
    input logic enable,
    input logic [1:0] pos,
    input logic [3:0] out
);

    function automatic logic [3:0] rotated_value(input logic [3:0] a, input logic [1:0] s);
        case (s)
            2'b00: rotated_value = a;
            2'b01: rotated_value = {a[2:0], a[3]};
            2'b10: rotated_value = {a[1:0], a[3:2]};
            2'b11: rotated_value = {a[0], a[3:1]};
        endcase
    endfunction

    function automatic logic [1:0] encoded_pos(input logic [3:0] v, input logic en);
        if (en) begin
            case (v)
                4'b0001: encoded_pos = 2'd0;
                4'b0010: encoded_pos = 2'd1;
                4'b0100: encoded_pos = 2'd2;
                4'b1000: encoded_pos = 2'd3;
                default: encoded_pos = 2'd0;
            endcase
        end
        else begin
            encoded_pos = 2'd0;
        end
    endfunction

    // pos matches the priority encoder result on the rotated input.
    check_pos_matches_priority_encoder: assert property (
        @(posedge clk)
        pos == encoded_pos(rotated_value(A, shift), enable)
    );

    // out matches the rotated value ORed with the nonzero-pos flag.
    check_out_matches_rtl_equation: assert property (
        @(posedge clk)
        out == (rotated_value(A, shift) | {3'b000, (encoded_pos(rotated_value(A, shift), enable) != 2'b00)})
    );

    // Disabling the encoder forces pos to zero.
    check_disable_clears_pos: assert property (
        @(posedge clk)
        !enable |-> (pos == 2'b00)
    );

    // Disabled operation leaves out equal to the rotated input value.
    check_disable_out_is_rotated_value: assert property (
        @(posedge clk)
        !enable |-> (out == rotated_value(A, shift))
    );

    // A nonzero pos only occurs for enabled 0010, 0100, or 1000 rotated inputs.
    check_nonzero_pos_requires_valid_pattern: assert property (
        @(posedge clk)
        (pos != 2'b00) |-> (enable &&
                            ((rotated_value(A, shift) == 4'b0010) ||
                             (rotated_value(A, shift) == 4'b0100) ||
                             (rotated_value(A, shift) == 4'b1000)))
    );

    // All other enabled rotated inputs produce a zero position.
    check_other_enabled_patterns_drive_zero_pos: assert property (
        @(posedge clk)
        (enable &&
         (rotated_value(A, shift) != 4'b0010) &&
         (rotated_value(A, shift) != 4'b0100) &&
         (rotated_value(A, shift) != 4'b1000)) |-> (pos == 2'b00)
    );

endmodule

