module zet_fulladd16 (
    input  [15:0] x,
    input  [15:0] y,
    input         ci,
    output        co,
    output [15:0] z,
    input         s
  );

  assign {co,z} = {1'b0, x} + {s, y} + ci;
endmodule

sva:
module zet_fulladd16_sva (
    input logic [15:0] x,
    input logic [15:0] y,
    input logic        ci,
    input logic        co,
    input logic [15:0] z,
    input logic        s
);

    // No RTL clock or reset; combinational behavior is sampled on $global_clock.

    // Combined carry-out and sum must match the implemented 17-bit addition.
    check_full_sum_match: assert property (
        @($global_clock) {co, z} == ({1'b0, x} + {s, y} + ci)
    );

    // With s low, the block behaves as x + y + ci.
    check_plain_add_when_s_low: assert property (
        @($global_clock) !s |-> {co, z} == ({1'b0, x} + {1'b0, y} + ci)
    );

    // With x and ci low, the output equals the s-extended y operand.
    check_y_pass_through_when_x_zero_and_ci_zero: assert property (
        @($global_clock) (x == 16'h0000 && !ci) |-> {co, z} == {s, y}
    );

    // With y and ci low, the output equals x with co matching s.
    check_x_pass_through_when_y_zero_and_ci_zero: assert property (
        @($global_clock) (y == 16'h0000 && !ci) |-> {co, z} == {s, x}
    );

    // Zero operands and no carry-in produce zero sum and co equal to s.
    check_zero_operands_no_carry_in: assert property (
        @($global_clock) (x == 16'h0000 && y == 16'h0000 && !ci) |-> (z == 16'h0000 && co == s)
    );

endmodule

rtl:
module adder_subtractor(
  input [3:0] A,
  input [3:0] B,
  input Sub,
  input clk,
  output reg [3:0] result
);

  wire [3:0] add_result;
  wire [3:0] sub_result;

  // Adder logic
  assign add_result = A + B;

  // Subtractor logic
  assign sub_result = A - B;

  // Result selection logic
  always @ (posedge clk) begin
    if (Sub == 1'b0) begin
      result <= add_result;
    end else begin
      result <= sub_result;
    end
  end

endmodule

sva:
module adder_subtractor_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic Sub,
    input logic clk,
    input logic [3:0] result
);

    // In add mode, result captures A + B on the next clock.
    check_add_mode_result: assert property (
        @(posedge clk) (Sub == 1'b0) |=> (result == ($past(A) + $past(B)))
    );

    // In subtract mode, result captures A - B on the next clock.
    check_sub_mode_result: assert property (
        @(posedge clk) (Sub == 1'b1) |=> (result == ($past(A) - $past(B)))
    );

    // Result always reflects the operation selected on the previous clock.
    check_selected_operation_result: assert property (
        @(posedge clk) 1'b1 |=> (result == ($past(Sub) ? ($past(A) - $past(B)) : ($past(A) + $past(B))))
    );

    // Subtracting equal operands produces zero on the next clock.
    check_equal_operands_subtract_zero: assert property (
        @(posedge clk) (Sub == 1'b1 && A == B) |=> (result == 4'b0000)
    );

    // Adding zero on B passes A through on the next clock.
    check_add_zero_passthrough: assert property (
        @(posedge clk) (Sub == 1'b0 && B == 4'b0000) |=> (result == $past(A))
    );

endmodule

rtl:
module bitwise_and (
    input [3:0] in1,
    input [3:0] in2,
    output [3:0] out,
    input VPWR, VGND, VPB, VNB
);

wire [3:0] not_in1;
wire [3:0] not_in2;
wire [3:0] not_out;

// invert the inputs
assign not_in1 = ~in1;
assign not_in2 = ~in2;

// perform the OR operation on the inverted inputs
assign not_out[0] = not_in1[0] | not_in2[0];
assign not_out[1] = not_in1[1] | not_in2[1];
assign not_out[2] = not_in1[2] | not_in2[2];
assign not_out[3] = not_in1[3] | not_in2[3];

// invert the output of the OR gate to get the AND result
assign out = ~not_out;

endmodule

sva:
module bitwise_and_sva (
    input logic [3:0] in1,
    input logic [3:0] in2,
    input logic [3:0] out,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB
);

    // The output vector equals the bitwise AND of the two input vectors.
    check_out_matches_bitwise_and: assert property (
        @($global_clock) out == (in1 & in2)
    );

    // Output bit 0 equals the AND of input bit 0.
    check_out_bit0_matches_inputs: assert property (
        @($global_clock) out[0] == (in1[0] & in2[0])
    );

    // Output bit 1 equals the AND of input bit 1.
    check_out_bit1_matches_inputs: assert property (
        @($global_clock) out[1] == (in1[1] & in2[1])
    );

    // Output bit 2 equals the AND of input bit 2.
    check_out_bit2_matches_inputs: assert property (
        @($global_clock) out[2] == (in1[2] & in2[2])
    );

    // Output bit 3 equals the AND of input bit 3.
    check_out_bit3_matches_inputs: assert property (
        @($global_clock) out[3] == (in1[3] & in2[3])
    );

    // Output bit 0 stays stable when its corresponding inputs stay stable.
    check_out_bit0_stable_when_inputs_stable: assert property (
        @($global_clock) ($stable(in1[0]) && $stable(in2[0])) |-> $stable(out[0])
    );

    // Output bit 1 stays stable when its corresponding inputs stay stable.
    check_out_bit1_stable_when_inputs_stable: assert property (
        @($global_clock) ($stable(in1[1]) && $stable(in2[1])) |-> $stable(out[1])
    );

    // Output bit 2 stays stable when its corresponding inputs stay stable.
    check_out_bit2_stable_when_inputs_stable: assert property (
        @($global_clock) ($stable(in1[2]) && $stable(in2[2])) |-> $stable(out[2])
    );

    // Output bit 3 stays stable when its corresponding inputs stay stable.
    check_out_bit3_stable_when_inputs_stable: assert property (
        @($global_clock) ($stable(in1[3]) && $stable(in2[3])) |-> $stable(out[3])
    );

endmodule

rtl:
module ripple_carry_adder (
    input [3:0] A,
    input [3:0] B,
    output [3:0] S,
    output overflow
);

    wire [4:0] sum;
    wire carry;

    assign sum = A + B;
    assign carry = sum[4];

    assign S = sum[3:0];
    assign overflow = carry;

endmodule

sva:
module ripple_carry_adder_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] S,
    input logic overflow
);

    // Combinational DUT with no explicit clock or reset; assertions sample on $global_clock.
    // A and B are 4-bit operands; S is the low 4 bits of A+B and overflow is the carry-out.

    // Combined outputs must equal the 5-bit addition result.
    check_full_addition_result: assert property (
        @($global_clock) ({overflow, S} == ({1'b0, A} + {1'b0, B}))
    );

    // Zero on A must pass B through with no carry.
    check_zero_a_passthrough: assert property (
        @($global_clock) (A == 4'h0) |-> ({overflow, S} == {1'b0, B})
    );

    // Zero on B must pass A through with no carry.
    check_zero_b_passthrough: assert property (
        @($global_clock) (B == 4'h0) |-> ({overflow, S} == {1'b0, A})
    );

    // The maximum input pair must produce 0x1E.
    check_max_plus_max: assert property (
        @($global_clock) ((A == 4'hF) && (B == 4'hF)) |-> ((S == 4'hE) && (overflow == 1'b1))
    );

    // Adding 1 to 0xF must wrap the sum and raise carry-out.
    check_f_plus_one_boundary: assert property (
        @($global_clock) ((A == 4'hF) && (B == 4'h1)) |-> ((S == 4'h0) && (overflow == 1'b1))
    );

    // Adding 0x8 and 0x8 must produce a carry-out with zero low bits.
    check_eight_plus_eight_boundary: assert property (
        @($global_clock) ((A == 4'h8) && (B == 4'h8)) |-> ((S == 4'h0) && (overflow == 1'b1))
    );

    // Sums that fit in 4 bits must not assert overflow.
    check_no_overflow_for_in_range_sum: assert property (
        @($global_clock) (({1'b0, A} + {1'b0, B}) <= 5'd15) |-> (overflow == 1'b0)
    );

    // Sums above 4-bit range must assert overflow.
    check_overflow_for_out_of_range_sum: assert property (
        @($global_clock) (({1'b0, A} + {1'b0, B}) >= 5'd16) |-> (overflow == 1'b1)
    );

endmodule

rtl:
module top_module (
    input [2:0] in,
    output reg [7:0] O
);

    wire [7:0] priority_out;
    wire [3:0] binary_out;
    wire [7:0] final_out;

    priority_encoder pe(in, priority_out);
    binary_to_one_hot btoh(priority_out[3:0], binary_out);
    final_output fo(priority_out, binary_out, final_out);

    always @(*) begin
        O = final_out;
    end

endmodule
module priority_encoder (
    input [2:0] in,
    output reg [7:0] out
);

    always @(*) begin
        case(in)
            3'b000: out = 8'b00000001;
            3'b001: out = 8'b00000010;
            3'b010: out = 8'b00000100;
            3'b011: out = 8'b00001000;
            3'b100: out = 8'b00010000;
            3'b101: out = 8'b00100000;
            3'b110: out = 8'b01000000;
            3'b111: out = 8'b10000000;
        endcase
    end

endmodule
module binary_to_one_hot (
    input [3:0] B,
    output reg [3:0] O
);

    always @(*) begin
        case(B)
            4'b0000: O = 4'b1000;
            4'b0001: O = 4'b0100;
            4'b0010: O = 4'b0010;
            4'b0011: O = 4'b0001;
            default: O = 4'b0000;
        endcase
    end

endmodule
module final_output (
    input [7:0] priority_input,
    input [3:0] one_hot_input,
    output reg [7:0] output_val
);

    always @(*) begin
        case(one_hot_input)
            4'b1000: output_val = priority_input[7:0];
            4'b0100: output_val = priority_input[6:0];
            4'b0010: output_val = priority_input[5:0];
            4'b0001: output_val = priority_input[4:0];
            default: output_val = 8'b0;
        endcase
    end

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic [2:0] in,
    input logic [7:0] O
);

    // Output is always either zero or a single asserted bit.
    check_output_is_onehot0: assert property (
        @(posedge clk) $onehot0(O)
    );

    // Input 000 maps to bit 0.
    check_in_000_maps_to_01: assert property (
        @(posedge clk) (in == 3'b000) |-> (O == 8'b00000001)
    );

    // Input 001 maps to bit 1.
    check_in_001_maps_to_02: assert property (
        @(posedge clk) (in == 3'b001) |-> (O == 8'b00000010)
    );

    // Input 010 produces the default zero output.
    check_in_010_maps_to_00: assert property (
        @(posedge clk) (in == 3'b010) |-> (O == 8'b00000000)
    );

    // Input 011 produces the default zero output.
    check_in_011_maps_to_00: assert property (
        @(posedge clk) (in == 3'b011) |-> (O == 8'b00000000)
    );

    // Input 100 maps to bit 4.
    check_in_100_maps_to_10: assert property (
        @(posedge clk) (in == 3'b100) |-> (O == 8'b00010000)
    );

    // Input 101 maps to bit 5.
    check_in_101_maps_to_20: assert property (
        @(posedge clk) (in == 3'b101) |-> (O == 8'b00100000)
    );

    // Input 110 maps to bit 6.
    check_in_110_maps_to_40: assert property (
        @(posedge clk) (in == 3'b110) |-> (O == 8'b01000000)
    );

    // Input 111 maps to bit 7.
    check_in_111_maps_to_80: assert property (
        @(posedge clk) (in == 3'b111) |-> (O == 8'b10000000)
    );

endmodule

rtl:
module not_gate_using_nand(input in, output out);
  wire nand_out;
  assign nand_out = ~(in & in);
  assign out = nand_out;
endmodule

sva:
module not_gate_using_nand_sva (
    input logic clk,
    input logic in,
    input logic out
);

    // RTL has no clock or reset; sample the combinational logic on an external clock.

    // Output matches the NAND of the input with itself.
    check_self_nand_function: assert property (
        @(posedge clk) out === ~(in & in)
    );

    // Output behaves as the inversion of the input.
    check_inverter_function: assert property (
        @(posedge clk) out === ~in
    );

    // A low input drives the output high.
    check_low_input_drives_high: assert property (
        @(posedge clk) (in == 1'b0) |-> (out == 1'b1)
    );

    // A high input drives the output low.
    check_high_input_drives_low: assert property (
        @(posedge clk) (in == 1'b1) |-> (out == 1'b0)
    );

    // A rising input corresponds to a falling output.
    check_input_rise_output_fall: assert property (
        @(posedge clk) $rose(in) |-> $fell(out)
    );

    // A falling input corresponds to a rising output.
    check_input_fall_output_rise: assert property (
        @(posedge clk) $fell(in) |-> $rose(out)
    );

    // If the input is stable across samples, the output is also stable.
    check_stable_input_stable_output: assert property (
        @(posedge clk) $stable(in) |-> $stable(out)
    );

endmodule

rtl:
module sky130_fd_sc_ms__a21boi (
    Y   ,
    A1  ,
    A2  ,
    B1_N
);

    output Y   ;
    input  A1  ;
    input  A2  ;
    input  B1_N;

    wire b         ;
    wire and0_out  ;
    wire nor0_out_Y;

    not not0 (b         , B1_N           );
    and and0 (and0_out  , A1, A2         );
    nor nor0 (nor0_out_Y, b, and0_out    );
    buf buf0 (Y         , nor0_out_Y     );

endmodule

sva:
module sky130_fd_sc_ms__a21boi_sva (
    input logic clk,
    input logic Y,
    input logic A1,
    input logic A2,
    input logic B1_N
);

    // Y must match the implemented NOT/AND/NOR/BUF logic.
    check_y_matches_implemented_logic: assert property (
        @(posedge clk) (Y == (~((~B1_N) | (A1 & A2))))
    );

    // A low B1_N forces the NOR output, and therefore Y, low.
    check_b1n_low_forces_y_low: assert property (
        @(posedge clk) (B1_N == 1'b0) |-> (Y == 1'b0)
    );

    // High A1 and A2 drive the AND term high and force Y low.
    check_a1_a2_high_force_y_low: assert property (
        @(posedge clk) ((A1 == 1'b1) && (A2 == 1'b1)) |-> (Y == 1'b0)
    );

    // With B1_N high and A1 low, the NOR output must be high.
    check_b1n_high_a1_low_drives_y_high: assert property (
        @(posedge clk) ((B1_N == 1'b1) && (A1 == 1'b0)) |-> (Y == 1'b1)
    );

    // With B1_N high and A2 low, the NOR output must be high.
    check_b1n_high_a2_low_drives_y_high: assert property (
        @(posedge clk) ((B1_N == 1'b1) && (A2 == 1'b0)) |-> (Y == 1'b1)
    );

endmodule

rtl:
module minimum_value (
  input [7:0] a,
  input [7:0] b,
  input [7:0] c,
  output reg [7:0] min
);

  always @ (a, b, c) begin
    if (a <= b && a <= c)
      min = a;
    else if (b <= a && b <= c)
      min = b;
    else
      min = c;
  end

endmodule

sva:
module minimum_value_sva (
    input logic [7:0] a,
    input logic [7:0] b,
    input logic [7:0] c,
    input logic [7:0] min
);

    // Sample the combinational behavior on the formal global clock.
    // min must follow the RTL's minimum-selection function.
    check_min_function: assert property (
        @($global_clock)
        min == (((a <= b) && (a <= c)) ? a :
                (((b <= a) && (b <= c)) ? b : c))
    );

    // When a is smallest or tied for smallest, min must be a.
    check_select_a: assert property (
        @($global_clock)
        ((a <= b) && (a <= c)) |-> (min == a)
    );

    // When a is not selected and b is smallest or tied, min must be b.
    check_select_b: assert property (
        @($global_clock)
        (!((a <= b) && (a <= c)) && ((b <= a) && (b <= c))) |-> (min == b)
    );

    // When neither a nor b is selected, min must be c.
    check_select_c: assert property (
        @($global_clock)
        (!((a <= b) && (a <= c)) && !((b <= a) && (b <= c))) |-> (min == c)
    );

    // The selected minimum must not exceed a.
    check_min_le_a: assert property (
        @($global_clock)
        (min <= a)
    );

    // The selected minimum must not exceed b.
    check_min_le_b: assert property (
        @($global_clock)
        (min <= b)
    );

    // The selected minimum must not exceed c.
    check_min_le_c: assert property (
        @($global_clock)
        (min <= c)
    );

    // The output must match one of the three inputs.
    check_min_matches_input: assert property (
        @($global_clock)
        ((min == a) || (min == b) || (min == c))
    );

endmodule

rtl:
module top_module (
    input CLK,
    input CLR,
    input LD,
    input [3:0] DATA,
    output [3:0] Y
);
// Temp Reg
wire [3:0] counter_output;
wire [3:0] bitwise_and_output;

// Sub Modules
counter counter_inst (
    .CLK(CLK),
    .CLR(CLR),
    .LD(LD),
    .DATA(DATA),
    // Output Ports
    .Q(counter_output)
);

bitwise_and bitwise_and_inst (
    .A(counter_output),
    .B(DATA),
    // Output Ports
    .Y(bitwise_and_output)
);

functional_module functional_module_inst (
    .counter_output(counter_output),
    .bitwise_and_output(bitwise_and_output),
    // Output Ports
    .final_output(Y)
);

endmodule

module counter (
    input CLK,
    input CLR,
    input LD,
    input [3:0] DATA,
    // Output Ports
    output reg [3:0] Q
);

always @(posedge CLK or negedge CLR) begin
    if (CLR == 0) begin
        Q <= 0;
    end else if (LD == 1) begin
        Q <= DATA;
    end else begin
        Q <= Q + 1;
        if (Q == 16) begin
            Q <= 0;
        end
    end
end

endmodule

module bitwise_and (
    input [3:0] A,
    input [3:0] B,
    // Output Ports
    output reg [3:0] Y
);

always @(A or B) begin
  Y = A & B;
end

endmodule

module functional_module (
    input [3:0] counter_output,
    input [3:0] bitwise_and_output,
    // Output Ports
    output reg [3:0] final_output
);

always @(counter_output or bitwise_and_output) begin
  final_output = bitwise_and_output & counter_output;
end

endmodule

sva:
module top_module_assertions (
    input logic CLK,
    input logic CLR,
    input logic LD,
    input logic [3:0] DATA,
    input logic [3:0] Y,
    input logic [3:0] counter_output,
    input logic [3:0] bitwise_and_output
);

    // Active-low reset forces the counter and both combinational outputs to zero.
    check_reset_clears_all: assert property (
        @(posedge CLK) !CLR |-> (counter_output == 4'd0 && bitwise_and_output == 4'd0 && Y == 4'd0)
    );

    // The first sampled cycle after reset release still reflects the cleared state.
    check_reset_release_starts_zero: assert property (
        @(posedge CLK) disable iff (!CLR)
        $rose(CLR) |-> (counter_output == 4'd0 && bitwise_and_output == 4'd0 && Y == 4'd0)
    );

    // The bitwise_and block outputs counter_output AND DATA.
    check_bitwise_and_function: assert property (
        @(posedge CLK) disable iff (!CLR)
        bitwise_and_output == (counter_output & DATA)
    );

    // The functional_module outputs bitwise_and_output AND counter_output.
    check_final_output_function: assert property (
        @(posedge CLK) disable iff (!CLR)
        Y == (bitwise_and_output & counter_output)
    );

    // The final output matches the intermediate AND result.
    check_output_matches_intermediate: assert property (
        @(posedge CLK) disable iff (!CLR)
        Y == bitwise_and_output
    );

    // The top-level output equals counter_output masked by DATA.
    check_output_mask_relation: assert property (
        @(posedge CLK) disable iff (!CLR)
        Y == (counter_output & DATA)
    );

    // Zero DATA forces both combinational outputs low.
    check_zero_data_forces_zero_output: assert property (
        @(posedge CLK) disable iff (!CLR)
        (DATA == 4'd0) |-> (bitwise_and_output == 4'd0 && Y == 4'd0)
    );

    // All-ones DATA passes counter_output through both combinational stages.
    check_all_ones_data_passes_counter: assert property (
        @(posedge CLK) disable iff (!CLR)
        (DATA == 4'hF) |-> (bitwise_and_output == counter_output && Y == counter_output)
    );

    // All-ones counter_output passes DATA through both combinational stages.
    check_all_ones_counter_passes_data: assert property (
        @(posedge CLK) disable iff (!CLR)
        (counter_output == 4'hF) |-> (bitwise_and_output == DATA && Y == DATA)
    );

endmodule

bind top_module top_module_assertions top_module_assertions_inst (
    .CLK(CLK),
    .CLR(CLR),
    .LD(LD),
    .DATA(DATA),
    .Y(Y),
    .counter_output(counter_output),
    .bitwise_and_output(bitwise_and_output)
);

rtl:
module erosion_sys_cycle_time
	(
		input 		clock,
		input 		resetn,
		output [31:0] 		cur_cycle
	);

	reg [31:0] cur_count_NO_SHIFT_REG;

	assign cur_cycle = cur_count_NO_SHIFT_REG;

	always @(posedge clock or negedge resetn)
	begin
		if (~(resetn))
		begin
			cur_count_NO_SHIFT_REG <= 32'h0;
		end
		else
		begin
			cur_count_NO_SHIFT_REG <= (cur_count_NO_SHIFT_REG + 32'h1);
		end
	end

endmodule

sva:
module erosion_sys_cycle_time_sva (
    input logic        clock,
    input logic        resetn,
    input logic [31:0] cur_cycle
);

    // Counter output is zero whenever reset is asserted.
    check_reset_drives_zero: assert property (
        @(posedge clock) !resetn |-> (cur_cycle == 32'h0000_0000)
    );

    // First sampled cycle after reset release still shows zero.
    check_release_starts_from_zero: assert property (
        @(posedge clock) disable iff (!resetn)
        $rose(resetn) |-> (cur_cycle == 32'h0000_0000)
    );

    // One active clock after reset release, the counter becomes one.
    check_first_increment_after_release: assert property (
        @(posedge clock) disable iff (!resetn)
        $rose(resetn) |=> (cur_cycle == 32'h0000_0001)
    );

    // While continuously out of reset, the counter increments by one each cycle.
    check_increment_each_cycle: assert property (
        @(posedge clock) disable iff (!resetn)
        (!$initstate && $past(resetn)) |-> (cur_cycle == ($past(cur_cycle) + 32'h0000_0001))
    );

    // The 32-bit counter wraps to zero after reaching all ones.
    check_wraps_after_max: assert property (
        @(posedge clock) disable iff (!resetn)
        (!$initstate && $past(resetn) && ($past(cur_cycle) == 32'hFFFF_FFFF)) |-> (cur_cycle == 32'h0000_0000)
    );

endmodule

rtl:
module and_ctrl (
    input A1,
    input A2,
    input A3,
    input B1,
    input C1,
    input CTRL,
    output Y
);

    wire cond1, cond2, cond3, cond4;

    assign cond1 = (CTRL == 0) && A1 && A2 && A3;
    assign cond2 = (CTRL == 1) && A1 && A2 && A3 && B1 && !C1;
    assign cond3 = (CTRL == 1) && A1 && A2 && A3 && B1 && C1;
    assign cond4 = (CTRL == 1) && A1 && A2 && A3 && !B1 && C1;

    assign Y = cond1 || cond2 || cond3 || cond4;

endmodule

sva:
module and_ctrl_sva (
    input logic clk,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic B1,
    input logic C1,
    input logic CTRL,
    input logic Y
);

    // Y must match the exact combinational equation implemented in the RTL.
    check_y_matches_rtl_equation: assert property (
        @(posedge clk)
        Y == (((CTRL == 1'b0) && A1 && A2 && A3) ||
              ((CTRL == 1'b1) && A1 && A2 && A3 && B1 && !C1) ||
              ((CTRL == 1'b1) && A1 && A2 && A3 && B1 && C1) ||
              ((CTRL == 1'b1) && A1 && A2 && A3 && !B1 && C1))
    );

    // Y can only be high when all three A inputs are high.
    check_y_requires_all_a_inputs: assert property (
        @(posedge clk)
        (!A1 || !A2 || !A3) |-> !Y
    );

    // With CTRL low, Y is the AND of A1, A2, and A3.
    check_ctrl_low_function: assert property (
        @(posedge clk)
        (CTRL == 1'b0) |-> (Y == (A1 && A2 && A3))
    );

    // With CTRL high and B1 high, C1 does not affect Y.
    check_ctrl_high_b1_high_function: assert property (
        @(posedge clk)
        ((CTRL == 1'b1) && B1) |-> (Y == (A1 && A2 && A3))
    );

    // With CTRL high and B1 low, Y depends on C1 along with A1, A2, and A3.
    check_ctrl_high_b1_low_function: assert property (
        @(posedge clk)
        ((CTRL == 1'b1) && !B1) |-> (Y == (A1 && A2 && A3 && C1))
    );

    // With CTRL high and both B1 and C1 low, Y must be low.
    check_ctrl_high_b1_c1_low_blocks_y: assert property (
        @(posedge clk)
        ((CTRL == 1'b1) && !B1 && !C1) |-> !Y
    );

endmodule

rtl:
module adder_ovf (
    A,
    B,
    SUM,
    OVF
);

    input [1:0] A;
    input [1:0] B;
    output [1:0] SUM;
    output OVF;

    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;

    wire [2:0] temp_sum;

    // 2-bit adder
    assign temp_sum = {1'b0, A} + {1'b0, B};

    // Overflow detection
    assign OVF = (temp_sum[2] == 1);

    // Output SUM
    assign SUM = temp_sum[1:0];

endmodule

sva:
module adder_ovf_sva (
    input logic [1:0] A,
    input logic [1:0] B,
    input logic [1:0] SUM,
    input logic OVF
);

    // No RTL clock or reset; assertions sample on the formal global clock.
    // The DUT is a combinational 2-bit unsigned adder with carry-out overflow.

    // Full 3-bit output matches zero-extended addition of A and B.
    check_full_add_result: assert property (
        @($global_clock) {OVF, SUM} == ({1'b0, A} + {1'b0, B})
    );

    // Overflow is asserted exactly when the unsigned sum is 4 or greater.
    check_overflow_threshold: assert property (
        @($global_clock) OVF == (({1'b0, A} + {1'b0, B}) >= 3'd4)
    );

    // A zero A input passes B through with no overflow.
    check_a_zero_passthrough: assert property (
        @($global_clock) (A == 2'b00) |-> (!OVF && (SUM == B))
    );

    // A zero B input passes A through with no overflow.
    check_b_zero_passthrough: assert property (
        @($global_clock) (B == 2'b00) |-> (!OVF && (SUM == A))
    );

    // The maximum input combination wraps to 2 with overflow.
    check_max_input_case: assert property (
        @($global_clock) ((A == 2'b11) && (B == 2'b11)) |-> (OVF && (SUM == 2'b10))
    );

    // Adding 2 and 2 wraps to 0 with overflow.
    check_two_plus_two_case: assert property (
        @($global_clock) ((A == 2'b10) && (B == 2'b10)) |-> (OVF && (SUM == 2'b00))
    );

endmodule

rtl:
module ddr3_int_ex_lfsr8 (
clk, reset_n, enable, pause, load, data, ldata);

   parameter seed  = 32;
   input clk;
   input reset_n;
   input enable;
   input pause;
   input load;
   output[8 - 1:0] data;
   wire[8 - 1:0] data;
   input[8 - 1:0] ldata;

   reg[8 - 1:0] lfsr_data;

   assign data = lfsr_data ;

   always @(posedge clk or negedge reset_n)
   begin
      if (!reset_n)
      begin
         lfsr_data <= seed[7:0] ;
      end
      else
      begin
         if (!enable)
         begin
            lfsr_data <= seed[7:0];
         end
         else
         begin
            if (load)
            begin
               lfsr_data <= ldata ;
            end
            else
            begin
               if (!pause)
               begin
                  lfsr_data[0] <= lfsr_data[7] ;
                  lfsr_data[1] <= lfsr_data[0] ;
                  lfsr_data[2] <= lfsr_data[1] ^ lfsr_data[7] ;
                  lfsr_data[3] <= lfsr_data[2] ^ lfsr_data[7] ;
                  lfsr_data[4] <= lfsr_data[3] ^ lfsr_data[7] ;
                  lfsr_data[5] <= lfsr_data[4] ;
                  lfsr_data[6] <= lfsr_data[5] ;
                  lfsr_data[7] <= lfsr_data[6] ;
               end
            end
         end
      end
   end
endmodule

sva:
module ddr3_int_ex_lfsr8_sva #(
    parameter logic [31:0] seed = 32
) (
    input logic       clk,
    input logic       reset_n,
    input logic       enable,
    input logic       pause,
    input logic       load,
    input logic [7:0] data,
    input logic [7:0] ldata
);

    localparam logic [7:0] SEED8 = seed[7:0];

    // Active-low reset forces the output to the seed value.
    check_reset_forces_seed: assert property (
        @(posedge clk) !reset_n |-> (data == SEED8)
    );

    // When enable is low, the next state reloads the seed regardless of load or pause.
    check_disable_reloads_seed: assert property (
        @(posedge clk) disable iff (!reset_n)
        (!enable) |=> (data == SEED8)
    );

    // When enabled with load asserted, the next state becomes the load data.
    check_load_updates_state: assert property (
        @(posedge clk) disable iff (!reset_n)
        (enable && load) |=> (data == $past(ldata))
    );

    // When paused without load, the state holds its current value.
    check_pause_holds_state: assert property (
        @(posedge clk) disable iff (!reset_n)
        (enable && !load && pause) |=> (data == $past(data))
    );

    // When enabled and not paused or loaded, the LFSR advances with the implemented tap mapping.
    check_lfsr_advance: assert property (
        @(posedge clk) disable iff (!reset_n)
        (enable && !load && !pause) |=> (
            data == {
                $past(data[6]),
                $past(data[5]),
                $past(data[4]),
                $past(data[3]) ^ $past(data[7]),
                $past(data[2]) ^ $past(data[7]),
                $past(data[1]) ^ $past(data[7]),
                $past(data[0]),
                $past(data[7])
            }
        )
    );

endmodule

rtl:
module full_adder (
    input a,
    input b,
    input cin,
    output sum,
    output cout
);

    assign sum = a ^ b ^ cin;
    assign cout = (a & b) | (a & cin) | (b & cin);

endmodule
module four_bit_adder (
    input [3:0] a,
    input [3:0] b,
    input cin,
    output [3:0] sum,
    output cout
);

    wire [3:0] s;
    wire c1, c2, c3;

    full_adder fa0 (.a(a[0]), .b(b[0]), .cin(cin), .sum(s[0]), .cout(c1));
    full_adder fa1 (.a(a[1]), .b(b[1]), .cin(c1), .sum(s[1]), .cout(c2));
    full_adder fa2 (.a(a[2]), .b(b[2]), .cin(c2), .sum(s[2]), .cout(c3));
    full_adder fa3 (.a(a[3]), .b(b[3]), .cin(c3), .sum(s[3]), .cout(cout));

    assign sum = s;

endmodule

sva:
module four_bit_adder_sva (
    input logic [3:0] a,
    input logic [3:0] b,
    input logic       cin,
    input logic [3:0] sum,
    input logic       cout
);

    // Combinational DUT with no RTL clock or reset; sample on the formal global clock.

    // Bit 0 sum is the XOR of a[0], b[0], and cin.
    check_sum_bit0: assert property (
        @($global_clock) sum[0] == (a[0] ^ b[0] ^ cin)
    );

    // Lower two sum bits match a 2-bit addition with carry-in.
    check_sum_low2: assert property (
        @($global_clock) sum[1:0] == (a[1:0] + b[1:0] + cin)
    );

    // Lower three sum bits match a 3-bit addition with carry-in.
    check_sum_low3: assert property (
        @($global_clock) sum[2:0] == (a[2:0] + b[2:0] + cin)
    );

    // The 4-bit sum bus matches the low 4 bits of the addition.
    check_sum_bus: assert property (
        @($global_clock) sum == (a + b + cin)
    );

    // Carry-out matches the fifth bit of the zero-extended addition.
    check_carry_out: assert property (
        @($global_clock) cout == (({1'b0, a} + {1'b0, b} + {4'b0, cin})[4])
    );

    // The combined carry and sum equal the full 5-bit addition result.
    check_full_result: assert property (
        @($global_clock) {cout, sum} == ({1'b0, a} + {1'b0, b} + {4'b0, cin})
    );

    // Adding zero on b with no carry-in returns a and no carry-out.
    check_identity_b_zero: assert property (
        @($global_clock) (b == 4'b0000 && cin == 1'b0) |-> ({cout, sum} == {1'b0, a})
    );

    // Adding zero on a with no carry-in returns b and no carry-out.
    check_identity_a_zero: assert property (
        @($global_clock) (a == 4'b0000 && cin == 1'b0) |-> ({cout, sum} == {1'b0, b})
    );

    // Zero operands with carry-in one produce a value of one.
    check_zero_operands_with_carry: assert property (
        @($global_clock) (a == 4'b0000 && b == 4'b0000 && cin == 1'b1) |-> ({cout, sum} == 5'b00001)
    );

endmodule

rtl:
module four_input_and_gate (
    Y   ,
    A1  ,
    A2  ,
    B1  ,
    VPWR,
    VGND,
    VPB ,
    VNB
);

    output Y   ;
    input  A1  ;
    input  A2  ;
    input  B1  ;
    input  VPWR;
    input  VGND;
    input  VPB ;
    input  VNB ;

    assign Y = A1 & A2 & B1;

endmodule

sva:
module four_input_and_gate_sva (
    input logic Y,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB
);

    // No explicit clock or reset in the RTL; use $global_clock for this combinational module.

    // Y must always match the implemented three-input AND function.
    check_y_matches_and_function: assert property (
        @($global_clock) (Y === (A1 & A2 & B1))
    );

    // All three logic inputs high must drive Y high.
    check_all_inputs_high_drive_y_high: assert property (
        @($global_clock)
        ((A1 === 1'b1) && (A2 === 1'b1) && (B1 === 1'b1)) |-> (Y === 1'b1)
    );

    // A1 low must force Y low.
    check_a1_low_forces_y_low: assert property (
        @($global_clock) (A1 === 1'b0) |-> (Y === 1'b0)
    );

    // A2 low must force Y low.
    check_a2_low_forces_y_low: assert property (
        @($global_clock) (A2 === 1'b0) |-> (Y === 1'b0)
    );

    // B1 low must force Y low.
    check_b1_low_forces_y_low: assert property (
        @($global_clock) (B1 === 1'b0) |-> (Y === 1'b0)
    );

    // A high Y requires A1 to be high.
    check_y_high_requires_a1_high: assert property (
        @($global_clock) (Y === 1'b1) |-> (A1 === 1'b1)
    );

    // A high Y requires A2 to be high.
    check_y_high_requires_a2_high: assert property (
        @($global_clock) (Y === 1'b1) |-> (A2 === 1'b1)
    );

    // A high Y requires B1 to be high.
    check_y_high_requires_b1_high: assert property (
        @($global_clock) (Y === 1'b1) |-> (B1 === 1'b1)
    );

    // If A1, A2, and B1 are stable, Y must remain stable.
    check_y_stable_when_logic_inputs_stable: assert property (
        @($global_clock) ($stable(A1) && $stable(A2) && $stable(B1)) |-> $stable(Y)
    );

    // Changes on unused power pins alone must not affect Y.
    check_power_pin_changes_do_not_affect_y: assert property (
        @($global_clock)
        ($stable(A1) && $stable(A2) && $stable(B1) &&
         (!$stable(VPWR) || !$stable(VGND) || !$stable(VPB) || !$stable(VNB)))
        |-> $stable(Y)
    );

endmodule

rtl:
module parity_checker (
    input [3:0] IN,
    output OUT,
    input VPWR,
    input VGND,
    input VPB ,
    input VNB 
);

    wire [3:0] nand_out;
    wire [2:0] level1_out;
    wire [1:0] level2_out;
    wire level3_out;

    nand nand1 (nand_out[0], IN[0], IN[1], IN[2]);
    nand nand2 (nand_out[1], IN[1], IN[2], IN[3]);
    nand nand3 (nand_out[2], IN[2], IN[3], IN[0]);
    nand nand4 (nand_out[3], IN[3], IN[0], IN[1]);

    assign level1_out[0] = nand_out[0] & nand_out[1];
    assign level1_out[1] = nand_out[1] & nand_out[2];
    assign level1_out[2] = nand_out[2] & nand_out[3];

    assign level2_out[0] = level1_out[0] & level1_out[1];
    assign level2_out[1] = level1_out[1] & level1_out[2];

    assign level3_out = level2_out[0] & level2_out[1];

    assign OUT = ~level3_out;

endmodule

sva:
module parity_checker_sva (
    input logic [3:0] IN,
    input logic OUT,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB
);

    // OUT matches the implemented logic function.
    check_out_matches_three_input_and_or_function: assert property (
        @($global_clock)
        OUT == ((IN[0] & IN[1] & IN[2]) |
                (IN[1] & IN[2] & IN[3]) |
                (IN[2] & IN[3] & IN[0]) |
                (IN[3] & IN[0] & IN[1]))
    );

    // OUT is low when no three-input product term is true.
    check_no_three_high_keeps_out_low: assert property (
        @($global_clock)
        !((IN[0] & IN[1] & IN[2]) |
          (IN[1] & IN[2] & IN[3]) |
          (IN[2] & IN[3] & IN[0]) |
          (IN[3] & IN[0] & IN[1])) |-> !OUT
    );

    // OUT is high when all four inputs are high.
    check_all_four_high_sets_out: assert property (
        @($global_clock)
        (&IN) |-> OUT
    );

    // OUT is high when IN[1], IN[2], and IN[3] are high.
    check_in123_high_sets_out: assert property (
        @($global_clock)
        (!IN[0] && IN[1] && IN[2] && IN[3]) |-> OUT
    );

    // OUT is high when IN[0], IN[2], and IN[3] are high.
    check_in023_high_sets_out: assert property (
        @($global_clock)
        (IN[0] && !IN[1] && IN[2] && IN[3]) |-> OUT
    );

    // OUT is high when IN[0], IN[1], and IN[3] are high.
    check_in013_high_sets_out: assert property (
        @($global_clock)
        (IN[0] && IN[1] && !IN[2] && IN[3]) |-> OUT
    );

    // OUT is high when IN[0], IN[1], and IN[2] are high.
    check_in012_high_sets_out: assert property (
        @($global_clock)
        (IN[0] && IN[1] && IN[2] && !IN[3]) |-> OUT
    );

endmodule

rtl:
module clock_gating (
    input CLK,
    input EN,
    input TE,
    output ENCLK
);

reg Q;
wire G;

assign G = EN & ~TE;
assign ENCLK = G & CLK;

always @(posedge CLK or negedge TE) begin
    if (!TE) begin
        Q <= 1'b0;
    end else begin
        Q <= G ^ Q;
    end
end

endmodule

sva:
module clock_gating_sva (
    input logic CLK,
    input logic EN,
    input logic TE,
    input logic ENCLK
);

    // ENCLK must be low while CLK is low.
    check_enclk_low_on_low_clk_phase: assert property (
        @(posedge CLK) ENCLK == 1'b0
    );

    // During CLK high, ENCLK must equal EN masked by active-low TE.
    check_enclk_matches_gate_on_high_clk_phase: assert property (
        @(negedge CLK) ENCLK == (EN & ~TE)
    );

    // Outside TE-low reset, TE high must block the gated clock.
    check_te_high_blocks_enclk: assert property (
        @(negedge CLK) disable iff (!TE) ENCLK == 1'b0
    );

    // With TE low, ENCLK must follow EN during CLK high.
    check_te_low_passes_en_to_enclk: assert property (
        @(negedge CLK) !TE |-> (ENCLK == EN)
    );

    // A high ENCLK requires EN high and TE low.
    check_enclk_high_has_valid_controls: assert property (
        @(negedge CLK) ENCLK |-> (EN && !TE)
    );

endmodule

