module gray_code (
    input [3:0] in,
    output reg [5:0] out
);

always @ (in) begin
    out[0] = in[0];
    out[1] = in[0] ^ in[1];
    out[2] = in[1] ^ in[2];
    out[3] = in[2] ^ in[3];
    out[4] = in[3] ^ out[3];
    out[5] = in[3] ^ out[2];
end

endmodule

sva:
module gray_code_sva (
    input logic [3:0] in,
    input logic [5:0] out
);

    // out[0] mirrors in[0].
    check_out0_mirrors_in0: assert property (
        @($global_clock) out[0] == in[0]
    );

    // out[1] is the XOR of in[0] and in[1].
    check_out1_is_xor_in0_in1: assert property (
        @($global_clock) out[1] == (in[0] ^ in[1])
    );

    // out[2] is the XOR of in[1] and in[2].
    check_out2_is_xor_in1_in2: assert property (
        @($global_clock) out[2] == (in[1] ^ in[2])
    );

    // out[3] is the XOR of in[2] and in[3].
    check_out3_is_xor_in2_in3: assert property (
        @($global_clock) out[3] == (in[2] ^ in[3])
    );

    // out[4] simplifies to in[2].
    check_out4_equals_in2: assert property (
        @($global_clock) out[4] == in[2]
    );

    // out[5] is the XOR of in[1], in[2], and in[3].
    check_out5_is_xor_in1_in2_in3: assert property (
        @($global_clock) out[5] == (in[1] ^ in[2] ^ in[3])
    );

    // The full output vector matches the implemented combinational mapping.
    check_full_output_mapping: assert property (
        @($global_clock)
        out == { (in[1] ^ in[2] ^ in[3]),
                 in[2],
                 (in[2] ^ in[3]),
                 (in[1] ^ in[2]),
                 (in[0] ^ in[1]),
                 in[0] }
    );

endmodule

module up_counter_assertions (
    input logic       clock,
    input logic       reset,
    input logic       count_enable,
    input logic [3:0] Q
);

    // Reset clears the counter on the next clock sample.
    check_reset_clears_q: assert property (
        @(posedge clock) reset |=> (Q == 4'b0000)
    );

    // Reset has priority even when count enable is high.
    check_reset_priority_over_enable: assert property (
        @(posedge clock) reset && count_enable |=> (Q == 4'b0000)
    );

    // When enabled without reset, the counter increments by one.
    check_increment_when_enabled: assert property (
        @(posedge clock) disable iff (reset) count_enable |=> (Q == ($past(Q) + 4'd1))
    );

    // When disabled without reset, the counter holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clock) disable iff (reset) !count_enable |=> (Q == $past(Q))
    );

endmodule

rtl:
module multiplier #(
  parameter n = 8 // number of bits in the input and output signals
)(
  input [n-1:0] a,
  input [n-1:0] b,
  output reg [n-1:0] result
);

parameter signed_mode = 1; // 1 for signed multiplication, 0 for unsigned multiplication.

reg [2*n-1:0] signed_a, signed_b;
wire [2*n-1:0] signed_result;

assign signed_result = signed_a * signed_b;

always @(*) begin
  if (signed_mode == 1) begin
    signed_a = {a[n-1], {n-1{a[n-1]}}, a};
    signed_b = {b[n-1], {n-1{b[n-1]}}, b};
    result <= signed_result[n-1:0];
  end else begin
    result <= a * b;
  end
end

endmodule

sva:
module multiplier_sva #(
    parameter int n = 8,
    parameter int signed_mode = 1
) (
    input logic clk,
    input logic [n-1:0] a,
    input logic [n-1:0] b,
    input logic [n-1:0] result
);

    generate
        if (signed_mode == 1) begin : gen_signed_mode
            // Signed mode uses the low n bits of the sign-extended product.
            check_signed_mode_result: assert property (
                @(posedge clk)
                result == (({a[n-1], {n-1{a[n-1]}}, a} * {b[n-1], {n-1{b[n-1]}}, b}) & {n{1'b1}})
            );
        end else begin : gen_unsigned_mode
            // Unsigned mode uses the low n bits of the direct product.
            check_unsigned_mode_result: assert property (
                @(posedge clk)
                result == ((a * b) & {n{1'b1}})
            );
        end
    endgenerate

    // The observable result matches the low n bits of a*b.
    check_result_matches_low_product: assert property (
        @(posedge clk)
        result == ((a * b) & {n{1'b1}})
    );

    // Zero on a forces a zero result.
    check_zero_a: assert property (
        @(posedge clk)
        (a == '0) |-> (result == '0)
    );

    // Zero on b forces a zero result.
    check_zero_b: assert property (
        @(posedge clk)
        (b == '0) |-> (result == '0)
    );

    // Multiplying by one on b returns a.
    check_one_on_b: assert property (
        @(posedge clk)
        (b == {{n-1{1'b0}}, 1'b1}) |-> (result == a)
    );

    // Multiplying by one on a returns b.
    check_one_on_a: assert property (
        @(posedge clk)
        (a == {{n-1{1'b0}}, 1'b1}) |-> (result == b)
    );

    // The product LSB is the AND of the operand LSBs.
    check_lsb_product_rule: assert property (
        @(posedge clk)
        result[0] == (a[0] & b[0])
    );

    // Stable sampled inputs keep the sampled result stable.
    check_stable_inputs_keep_result_stable: assert property (
        @(posedge clk)
        (!$initstate && $stable(a) && $stable(b)) |-> $stable(result)
    );

    // A sampled result change requires a sampled input change.
    check_result_change_requires_input_change: assert property (
        @(posedge clk)
        (!$initstate && !$stable(result)) |-> (!$stable(a) || !$stable(b))
    );

endmodule

module sky130_fd_sc_hd__nor4b_sva (
    input logic A,
    input logic B,
    input logic C,
    input logic D_N,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB,
    input logic Y
);

`define NOR4B_ANY_EDGE \
    posedge A or negedge A or \
    posedge B or negedge B or \
    posedge C or negedge C or \
    posedge D_N or negedge D_N or \
    posedge VPWR or negedge VPWR or \
    posedge VGND or negedge VGND or \
    posedge VPB or negedge VPB or \
    posedge VNB or negedge VNB or \
    posedge Y or negedge Y

// Y must match the RTL NOR equation.
check_y_matches_nor_function: assert property (
    @(`NOR4B_ANY_EDGE) disable iff (1'b0)
    Y == ~(A | B | C | D_N)
);

// All logic inputs low drives Y high.
check_all_inputs_low_drive_y_high: assert property (
    @(`NOR4B_ANY_EDGE) disable iff (1'b0)
    (!A && !B && !C && !D_N) |-> Y
);

// A high forces Y low.
check_a_high_forces_y_low: assert property (
    @(`NOR4B_ANY_EDGE) disable iff (1'b0)
    A |-> !Y
);

// B high forces Y low.
check_b_high_forces_y_low: assert property (
    @(`NOR4B_ANY_EDGE) disable iff (1'b0)
    B |-> !Y
);

// C high forces Y low.
check_c_high_forces_y_low: assert property (
    @(`NOR4B_ANY_EDGE) disable iff (1'b0)
    C |-> !Y
);

// D_N high forces Y low.
check_d_n_high_forces_y_low: assert property (
    @(`NOR4B_ANY_EDGE) disable iff (1'b0)
    D_N |-> !Y
);

// Stable logic inputs must keep Y stable.
check_stable_logic_inputs_hold_y: assert property (
    @(`NOR4B_ANY_EDGE) disable iff (1'b0)
    ($stable(A) && $stable(B) && $stable(C) && $stable(D_N)) |-> $stable(Y)
);

// Power-pin changes alone cannot affect Y in this RTL.
check_power_pin_activity_does_not_change_y: assert property (
    @(posedge VPWR or negedge VPWR or
      posedge VGND or negedge VGND or
      posedge VPB  or negedge VPB  or
      posedge VNB  or negedge VNB) disable iff (1'b0)
    ($stable(A) && $stable(B) && $stable(C) && $stable(D_N)) |-> $stable(Y)
);

endmodule

rtl:
module nand_mux_4to1 (
    input [3:0] A,
    input [1:0] S,
    output  out
);

wire nand1, nand2, nand3, nand4, nand5, nand6;

assign nand1 = ~(S[1] & S[0]);
assign nand2 = ~(S[1] & ~S[0]);
assign nand3 = ~(~S[1] & S[0]);
assign nand4 = ~(~S[1] & ~S[0]);

assign nand5 = ~(nand1 & A[0] & A[1]);
assign nand6 = ~(nand2 & A[1] & A[2]);

assign out = nand3 & nand4 & nand5 & nand6;

endmodule

sva:
module nand_mux_4to1_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [1:0] S,
    input logic out
);

    // out matches the implemented NAND network.
    check_out_equation: assert property (
        @(posedge clk)
        out == (
            (~((~S[1]) & S[0])) &
            (~((~S[1]) & (~S[0]))) &
            (~((~(S[1] & S[0])) & A[0] & A[1])) &
            (~((~(S[1] & (~S[0]))) & A[1] & A[2]))
        )
    );

    // When S[1] is low, the output is forced low.
    check_s1_low_forces_out_low: assert property (
        @(posedge clk)
        (S[1] == 1'b0) |-> (out == 1'b0)
    );

    // For select 2'b10, out is the NAND of A[0] and A[1].
    check_sel_10_function: assert property (
        @(posedge clk)
        (S == 2'b10) |-> (out == ~(A[0] & A[1]))
    );

    // For select 2'b11, out is the NAND of A[1] and A[2].
    check_sel_11_function: assert property (
        @(posedge clk)
        (S == 2'b11) |-> (out == ~(A[1] & A[2]))
    );

    // With S[1] high and A[1] low, the output must be high.
    check_s1_high_a1_low_forces_out_high: assert property (
        @(posedge clk)
        ((S[1] == 1'b1) && (A[1] == 1'b0)) |-> (out == 1'b1)
    );

    // For select 2'b10, A[0] and A[1] both high drive out low.
    check_sel_10_pair_high_forces_out_low: assert property (
        @(posedge clk)
        ((S == 2'b10) && (A[0] == 1'b1) && (A[1] == 1'b1)) |-> (out == 1'b0)
    );

    // For select 2'b10, if A[0:1] are not both high then out is high.
    check_sel_10_pair_not_high_forces_out_high: assert property (
        @(posedge clk)
        ((S == 2'b10) && !(A[0] & A[1])) |-> (out == 1'b1)
    );

    // For select 2'b11, A[1] and A[2] both high drive out low.
    check_sel_11_pair_high_forces_out_low: assert property (
        @(posedge clk)
        ((S == 2'b11) && (A[1] == 1'b1) && (A[2] == 1'b1)) |-> (out == 1'b0)
    );

    // For select 2'b11, if A[1:2] are not both high then out is high.
    check_sel_11_pair_not_high_forces_out_high: assert property (
        @(posedge clk)
        ((S == 2'b11) && !(A[1] & A[2])) |-> (out == 1'b1)
    );

endmodule

rtl:
module up_counter (
  input clk,
  input reset,
  output reg [3:0] count
);

  reg [3:0] next_count;

  always @(posedge clk) begin
    if (reset) begin
      count <= 4'b0000;
    end
    else begin
      count <= count + 1;
    end
  end

endmodule

sva:
module up_counter_sva (
    input logic clk,
    input logic reset,
    input logic [3:0] count
);

    // Count matches the previous cycle's reset-or-increment update.
    check_state_transition: assert property (
        @(posedge clk) disable iff ($initstate)
        count == ($past(reset) ? 4'b0000 : ($past(count) + 4'd1))
    );

    // A reset cycle clears the counter to zero on the next sampled cycle.
    check_reset_clears_count: assert property (
        @(posedge clk) disable iff ($initstate)
        reset |=> (count == 4'b0000)
    );

    // A non-reset cycle increments the counter by one on the next sampled cycle.
    check_increment_on_non_reset: assert property (
        @(posedge clk) disable iff ($initstate)
        !reset |=> (count == ($past(count) + 4'd1))
    );

    // After reset is released, the first observed count value is zero.
    check_release_from_reset_zero: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        $past(reset) |-> (count == 4'b0000)
    );

    // The 4-bit counter rolls over from 15 back to 0.
    check_rollover_from_max: assert property (
        @(posedge clk) disable iff ($initstate)
        (!reset && (count == 4'hF)) |=> (count == 4'h0)
    );

endmodule

