module MIO_BUS( input wire clk, input wire rst,
	input wire [3:0] BTN,
	input wire [7:0]SW,
	input wire mem_w,
	input wire [31:0] Cpu_data2bus,
	input wire [31:0] addr_bus, //data from CPU
	input wire [31:0] ram_data_out,
	input wire [7:0] led_out,
	input wire [31:0] counter_out,
	input wire counter0_out,
	input wire counter1_out,
	input wire counter2_out,
	output reg [31:0] Cpu_data4bus, //write to CPU
	output reg [31:0] ram_data_in, //from CPU write to Memory
	output reg [9: 0] ram_addr, //Memory Address signals
	output reg data_ram_we, 
	output reg GPIOf0000000_we,
	output reg GPIOe0000000_we,
	output reg counter_we,
	output reg [31: 0] Peripheral_in
);

	reg [7:0] led_in;

	always @(*) begin
		data_ram_we = 0;
		counter_we = 0;
		GPIOe0000000_we = 0;
		GPIOf0000000_we = 0;
		ram_addr = 10'h0;
		ram_data_in = 32'h0;
		Peripheral_in = 32'h0;
		Cpu_data4bus = 32'h0;
		case(addr_bus[31:28])
			4'h0: begin
				data_ram_we = mem_w	;
				ram_addr = addr_bus[11:2];
				ram_data_in = Cpu_data2bus;
				Cpu_data4bus = ram_data_out;
			end
			4'he: begin
				GPIOf0000000_we = mem_w;
				Peripheral_in = Cpu_data2bus;
				Cpu_data4bus = counter_out;
			end
			4'hf: begin
				if(addr_bus[2]) begin
					counter_we = mem_w;
					Peripheral_in = Cpu_data2bus;
					Cpu_data4bus = counter_out;
				end else begin
					GPIOf0000000_we = mem_w;
					Peripheral_in = Cpu_data2bus;
					Cpu_data4bus = {counter0_out, counter1_out, counter2_out, 9'h00, led_out, BTN, SW};
				end
			end
		endcase
	end
endmodule

module binary_to_gray (
    input [3:0] B,
    input clk,
    output [3:0] G
);

reg [3:0] G_reg1, G_reg2, G_reg3;

assign G = G_reg3;

// Pipeline stage 1
always @(*) begin
    G_reg1[0] = B[0];
    G_reg1[1] = B[0] ^ B[1];
    G_reg1[2] = B[1] ^ B[2];
    G_reg1[3] = B[2] ^ B[3];
end

// Pipeline stage 2
always @(posedge clk) begin
    G_reg2[0] <= G_reg1[0];
    G_reg2[1] <= G_reg1[1] ^ G_reg1[0];
    G_reg2[2] <= G_reg1[2] ^ G_reg1[1];
    G_reg2[3] <= G_reg1[3] ^ G_reg1[2];
end

// Pipeline stage 3
always @(posedge clk) begin
    G_reg3[0] <= G_reg2[0];
    G_reg3[1] <= G_reg2[1] ^ G_reg2[0];
    G_reg3[2] <= G_reg2[2] ^ G_reg2[1];
    G_reg3[3] <= G_reg2[3] ^ G_reg2[2];
end

endmodule

sva:
module binary_to_gray_sva (
    input logic [3:0] B,
    input logic       clk,
    input logic [3:0] G
);

    // Output matches the implemented two-stage registered prefix-XOR transform of B.
    check_output_vector_transform: assert property (
        @(posedge clk)
        1'b1 |-> ##2
        (G == {($past(B[3],2) ^ $past(B[2],2) ^ $past(B[1],2) ^ $past(B[0],2)),
               ($past(B[2],2) ^ $past(B[1],2) ^ $past(B[0],2)),
               ($past(B[1],2) ^ $past(B[0],2)),
               $past(B[0],2)})
    );

    // G[0] is B[0] delayed through the registered pipeline.
    check_g0_pipeline_mapping: assert property (
        @(posedge clk)
        1'b1 |-> ##2
        (G[0] == $past(B[0],2))
    );

    // G[1] is the prefix XOR of sampled B[1:0].
    check_g1_prefix_xor_mapping: assert property (
        @(posedge clk)
        1'b1 |-> ##2
        (G[1] == ($past(B[1],2) ^ $past(B[0],2)))
    );

    // G[2] is the prefix XOR of sampled B[2:0].
    check_g2_prefix_xor_mapping: assert property (
        @(posedge clk)
        1'b1 |-> ##2
        (G[2] == ($past(B[2],2) ^ $past(B[1],2) ^ $past(B[0],2)))
    );

    // G[3] is the prefix XOR of sampled B[3:0].
    check_g3_prefix_xor_mapping: assert property (
        @(posedge clk)
        1'b1 |-> ##2
        (G[3] == ($past(B[3],2) ^ $past(B[2],2) ^ $past(B[1],2) ^ $past(B[0],2)))
    );

endmodule

