sva:
module mux_4to1_sva (
    input logic clk,
    input logic [7:0] in0,
    input logic [7:0] in1,
    input logic [7:0] in2,
    input logic [7:0] in3,
    input logic [1:0] sel,
    input logic [7:0] out
