         (((sel == 2'b00) && $stable(in0)) ||
          ((sel == 2'b01) && $stable(in1)) ||
          ((sel == 2'b10) && $stable(in2)) ||
          ((sel == 2'b11) && $stable(in3)))) |-> $stable(out)
