    // The DUT is purely combinational.

    // Output matches the exact RTL combinational expression.
    check_out_matches_rtl_function: assert property (
        @($global_clock)
        out == ((((sel_b1 & sel_b2) ? b : a) == a) ? in : (in & 8'b11100011))
    );

