    input logic [63:0] iCUUR_FRCR_DATA,
    input logic        oFDR_GR_VALID,
    input logic [31:0] oFDR_GR_DATA,
    input logic [4:0]  oFDR_GR_DEST,
    input logic        oFDR_GR_DEST_SYSREG,
    input logic        oFDR_SPR_VALID,
    input logic [31:0] oFDR_SPR_DATA,
    input logic        oFDR_FRCR_VALID,
    input logic [63:0] oFDR_FRCR_DATA
);

    // Low async reset clears all forwarding outputs by the next clock sample.
    check_async_reset_clears_outputs: assert property (
        @(posedge iCLOCK)
        !inRESET |=> (
            (oFDR_GR_VALID == 1'b0) &&
            (oFDR_GR_DATA == 32'h0) &&
            (oFDR_GR_DEST == 5'h0) &&
            (oFDR_GR_DEST_SYSREG == 1'b0) &&
            (oFDR_SPR_VALID == 1'b0) &&
            (oFDR_SPR_DATA == 32'h0) &&
            (oFDR_FRCR_VALID == 1'b0) &&
            (oFDR_FRCR_DATA == 64'h0)
        )
    );

    // High sync reset clears all forwarding outputs on the next clock.
    check_sync_reset_clears_outputs: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        iRESET_SYNC |=> (
            (oFDR_GR_VALID == 1'b0) &&
            (oFDR_GR_DATA == 32'h0) &&
            (oFDR_GR_DEST == 5'h0) &&
            (oFDR_GR_DEST_SYSREG == 1'b0) &&
            (oFDR_SPR_VALID == 1'b0) &&
            (oFDR_SPR_DATA == 32'h0) &&
            (oFDR_FRCR_VALID == 1'b0) &&
            (oFDR_FRCR_DATA == 64'h0)
        )
    );

    // A valid GR write captures data and destination.
    check_gr_capture_on_valid: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (!iRESET_SYNC && iWB_GR_VALID) |=> (
            (oFDR_GR_VALID == 1'b1) &&
            (oFDR_GR_DATA == $past(iWB_GR_DATA)) &&
            (oFDR_GR_DEST == $past(iWB_GR_DEST)) &&
            (oFDR_GR_DEST_SYSREG == $past(iWB_GR_DEST_SYSREG))
        )
    );

    // Without a valid GR write, the GR forwarding state holds.
    check_gr_hold_without_write: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (!iRESET_SYNC && !iWB_GR_VALID) |=> (
            $stable(oFDR_GR_VALID) &&
            $stable(oFDR_GR_DATA) &&
            $stable(oFDR_GR_DEST) &&
            $stable(oFDR_GR_DEST_SYSREG)
        )
    );

    // WB SPR write has priority and sets SPR valid.
    check_spr_capture_from_wb: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (!iRESET_SYNC && iWB_SPR_VALID) |=> (
            (oFDR_SPR_VALID == 1'b1) &&
            (oFDR_SPR_DATA == $past(iWB_SPR_DATA))
        )
    );

    // Auto SPR write forwards auto data and leaves valid low.
    check_spr_capture_from_auto: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (!iRESET_SYNC && !iWB_SPR_VALID && iWB_AUTO_SPR_VALID) |=> (
            (oFDR_SPR_VALID == 1'b0) &&
            (oFDR_SPR_DATA == $past(iWB_AUTO_SPR_DATA))
        )
    );

    // Without SPR writes, current SPR data is forwarded with valid high.
    check_spr_forward_current_data: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (!iRESET_SYNC && !iWB_SPR_VALID && !iWB_AUTO_SPR_VALID) |=> (
            (oFDR_SPR_VALID == 1'b1) &&
            (oFDR_SPR_DATA == $past(iCUUR_SPR_DATA))
        )
    );

    // A valid FRCR write captures FRCR data.
    check_frcr_capture_from_wb: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (!iRESET_SYNC && iWB_FRCR_VALID) |=> (
            (oFDR_FRCR_VALID == 1'b1) &&
            (oFDR_FRCR_DATA == $past(iWB_FRCR_DATA))
        )
    );

    // Without an FRCR write, current FRCR data is forwarded with valid high.
    check_frcr_forward_current_data: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (!iRESET_SYNC && !iWB_FRCR_VALID) |=> (
            (oFDR_FRCR_VALID == 1'b1) &&
            (oFDR_FRCR_DATA == $past(iCUUR_FRCR_DATA))
        )
    );

endmodule

rtl:
module add_sub (
    input clk,
    input reset,      // Synchronous active-low reset
    input [3:0] A,
    input [3:0] B,
    input sub,
    output [3:0] q
);
    reg [3:0] result;

    always @(posedge clk, negedge reset) begin
        if (reset == 0) begin
            result <= 4'b0;
        end else begin
            if (sub == 1) begin
                result <= A - B;
            end else begin
                result <= A + B;
            end
        end
    end

    assign q = result;

endmodule

module priority_encoder (
    input [3:0] I,
    input enable,     // Active high enable
    output [1:0] q
);
    assign q = (enable == 1) ? {I[3], I[2]} :
                              (enable == 1) ? {I[3], I[1]} :
                                               {I[3], I[0]};
endmodule

module functional_module (
    input [3:0] add_sub_result,
    input [1:0] priority_encoder_D,
    output [3:0] q
);
    assign q = add_sub_result & priority_encoder_D;
endmodule

module top_module (
    input clk,
    input reset,      // Synchronous active-low reset
    input [3:0] A,
    input [3:0] B,
    input sub,
    input [3:0] I,
    input enable,     // Active high enable for priority_encoder
    output [3:0] q
);
    wire [3:0] add_sub_result;
    wire [1:0] priority_encoder_D;

    add_sub add_sub_inst (
        .clk(clk),
        .reset(reset),
        .A(A),
        .B(B),
        .sub(sub),
        .q(add_sub_result)
    );

    priority_encoder priority_encoder_inst (
        .I(I),
        .enable(enable),
        .q(priority_encoder_D)
    );

    functional_module functional_module_inst (
        .add_sub_result(add_sub_result),
        .priority_encoder_D(priority_encoder_D),
        .q(q)
    );

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic reset,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic sub,
    input logic [3:0] I,
    input logic enable,
    input logic [3:0] q,
    input logic [3:0] add_sub_result,
    input logic [1:0] priority_encoder_D
);

    // Reset clears the registered add/sub result.
    check_reset_clears_add_sub_result: assert property (
        @(posedge clk) !reset |-> (add_sub_result == 4'b0000)
    );

    // Reset forces the top-level output low.
    check_reset_forces_q_low: assert property (
        @(posedge clk) !reset |-> (q == 4'b0000)
    );

    // The upper priority_encoder bit always reflects I[3].
    check_priority_encoder_bit1_follows_i3: assert property (
        @(posedge clk) disable iff (!reset)
        (priority_encoder_D[1] == I[3])
    );

    // With enable high, the lower priority_encoder bit uses I[2].
    check_priority_encoder_enable_high_path: assert property (
        @(posedge clk) disable iff (!reset)
        enable |-> (priority_encoder_D[0] == I[2])
    );

    // With enable low, the lower priority_encoder bit uses I[0].
    check_priority_encoder_enable_low_path: assert property (
        @(posedge clk) disable iff (!reset)
        !enable |-> (priority_encoder_D[0] == I[0])
    );

    // The top output is the add/sub result ANDed with zero-extended encoder bits.
    check_functional_module_and_behavior: assert property (
        @(posedge clk) disable iff (!reset)
        (q == (add_sub_result & {2'b00, priority_encoder_D}))
    );

    // The upper two output bits are always zero after the width-mismatched AND.
    check_q_upper_bits_zero: assert property (
        @(posedge clk) disable iff (!reset)
        (q[3:2] == 2'b00)
    );

    // Output bit 1 is add_sub_result[1] gated by I[3].
    check_q_bit1_behavior: assert property (
        @(posedge clk) disable iff (!reset)
        (q[1] == (add_sub_result[1] & I[3]))
    );

    // With enable high, output bit 0 is gated by I[2].
    check_q_bit0_enable_high_path: assert property (
        @(posedge clk) disable iff (!reset)
        enable |-> (q[0] == (add_sub_result[0] & I[2]))
    );

    // With enable low, output bit 0 is gated by I[0].
    check_q_bit0_enable_low_path: assert property (
        @(posedge clk) disable iff (!reset)
        !enable |-> (q[0] == (add_sub_result[0] & I[0]))
    );

endmodule

bind top_module top_module_sva top_module_sva_inst (
    .clk(clk),
    .reset(reset),
    .A(A),
    .B(B),
    .sub(sub),
    .I(I),
    .enable(enable),
    .q(q),
    .add_sub_result(add_sub_result),
    .priority_encoder_D(priority_encoder_D)
);

module add_sub_4bit_sva (
    input logic       clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic       SUB,
    input logic [3:0] SUM
);

    // In add mode, SUM matches A + B.
    check_add_mode_result: assert property (
        @(posedge clk) (SUB == 1'b0) |-> (SUM == (A + B))
    );

    // In subtract mode, SUM matches A - B.
    check_sub_mode_result: assert property (
        @(posedge clk) (SUB == 1'b1) |-> (SUM == (A - B))
    );

    // With B equal to zero, SUM must equal A in either mode.
    check_zero_b_identity: assert property (
        @(posedge clk) (B == 4'b0000) |-> (SUM == A)
    );

    // In subtract mode, equal operands must produce zero.
    check_sub_equal_operands_zero: assert property (
        @(posedge clk) (SUB == 1'b1 && A == B) |-> (SUM == 4'b0000)
    );

    // If all inputs are stable, the output must remain stable.
    check_stable_inputs_keep_sum_stable: assert property (
        @(posedge clk) $stable({A, B, SUB}) |-> $stable(SUM)
    );

endmodule

module calculator_assertions (
    input logic clk,
    input logic [7:0] A,
    input logic [7:0] B,
    input logic [1:0] opcode,
    input logic en,
    input logic [7:0] R
);

    // No RTL clock/reset; sample this combinational logic on an external clock.

    // When disabled, the result is forced to zero.
    check_disable_forces_zero: assert property (
        @(posedge clk) !en |-> (R == 8'h00)
    );

    // Opcode 00 performs 8-bit addition when enabled.
    check_addition_result: assert property (
        @(posedge clk) en && (opcode == 2'b00) |-> (R == ((A + B) & 8'hFF))
    );

    // Opcode 01 performs 8-bit subtraction when enabled.
    check_subtraction_result: assert property (
        @(posedge clk) en && (opcode == 2'b01) |-> (R == ((A - B) & 8'hFF))
    );

    // Opcode 10 performs 8-bit truncated multiplication when enabled.
    check_multiplication_result: assert property (
        @(posedge clk) en && (opcode == 2'b10) |-> (R == ((A * B) & 8'hFF))
    );

    // Opcode 11 performs division when enabled with a nonzero divisor.
    check_division_result: assert property (
        @(posedge clk) en && (opcode == 2'b11) && (B != 8'h00) |-> (R == ((A / B) & 8'hFF))
    );

endmodule

rtl:
module logic_gate (
  input a,
  input b,
  output g_out,
  output p_out
);

// XOR gate to produce p_out
wire p_wire;
assign p_wire = a ^ b;

// AND gate to produce g_out
wire g_wire;
assign g_wire = a & b;

// Output signals
assign p_out = p_wire;
assign g_out = g_wire;

endmodule

sva:
module logic_gate_sva (
    input logic a,
    input logic b,
    input logic g_out,
    input logic p_out
);

    // p_out must be the XOR of a and b.
    check_p_out_is_xor: assert property (
        @($global_clock) p_out == (a ^ b)
    );

    // g_out must be the AND of a and b.
    check_g_out_is_and: assert property (
        @($global_clock) g_out == (a & b)
    );

    // The two outputs can never be high together.
    check_outputs_mutually_exclusive: assert property (
        @($global_clock) !(p_out && g_out)
    );

    // Both low inputs must drive both outputs low.
    check_zero_zero_case: assert property (
        @($global_clock) (!a && !b) |-> (!p_out && !g_out)
    );

    // Different inputs must drive p_out high and g_out low.
    check_inputs_differ_case: assert property (
        @($global_clock) (a ^ b) |-> (p_out && !g_out)
    );

    // Both high inputs must drive g_out high and p_out low.
    check_one_one_case: assert property (
        @($global_clock) (a && b) |-> (g_out && !p_out)
    );

endmodule

rtl:
module pipelined_mux (
    input [2:0] sel,
    input [3:0] data0,
    input [3:0] data1,
    input [3:0] data2,
    input [3:0] data3,
    input [3:0] data4,
    input [3:0] data5,
    output [3:0] out
);

reg [3:0] stage1_out;
reg [3:0] stage2_out;
reg [3:0] stage3_out;
reg [3:0] stage4_out;
reg [3:0] stage5_out;
wire [3:0] stage6_out;
wire [3:0] temp_out;

always @(*) begin
    case(sel)
        0: stage1_out = data0;
        1: stage1_out = data1;
        2: stage1_out = data2;
        3: stage1_out = data3;
        4: stage1_out = data4;
        5: stage1_out = data5;
        default: stage1_out = 0;
    endcase
end

always @(*) begin
    stage2_out = stage1_out;
end

always @(*) begin
    stage3_out = stage2_out;
end

always @(*) begin
    stage4_out = stage3_out;
end

always @(*) begin
    stage5_out = stage4_out;
end

assign stage6_out = stage5_out;
assign temp_out = stage6_out;
assign out = temp_out;

endmodule

sva:
module pipelined_mux_sva (
    input logic [2:0] sel,
    input logic [3:0] data0,
    input logic [3:0] data1,
    input logic [3:0] data2,
    input logic [3:0] data3,
    input logic [3:0] data4,
    input logic [3:0] data5,
    input logic [3:0] out
);

    // sel 0 routes data0 to out.
    check_sel0_routes_data0: assert property (
        @($global_clock) (sel === 3'd0) |-> (out === data0)
    );

    // sel 1 routes data1 to out.
    check_sel1_routes_data1: assert property (
        @($global_clock) (sel === 3'd1) |-> (out === data1)
    );

    // sel 2 routes data2 to out.
    check_sel2_routes_data2: assert property (
        @($global_clock) (sel === 3'd2) |-> (out === data2)
    );

    // sel 3 routes data3 to out.
    check_sel3_routes_data3: assert property (
        @($global_clock) (sel === 3'd3) |-> (out === data3)
    );

    // sel 4 routes data4 to out.
    check_sel4_routes_data4: assert property (
        @($global_clock) (sel === 3'd4) |-> (out === data4)
    );

    // sel 5 routes data5 to out.
    check_sel5_routes_data5: assert property (
        @($global_clock) (sel === 3'd5) |-> (out === data5)
    );

    // Any unmapped sel value drives zero.
    check_default_routes_zero: assert property (
        @($global_clock)
        (!((sel === 3'd0) || (sel === 3'd1) || (sel === 3'd2) ||
           (sel === 3'd3) || (sel === 3'd4) || (sel === 3'd5)))
        |-> (out === 4'h0)
    );

    // Unselected inputs do not affect out when sel and the selected path are stable.
    check_unselected_inputs_do_not_affect_out: assert property (
        @($global_clock)
        ((((sel === 3'd0) && $stable(sel) && $stable(data0)) ||
          ((sel === 3'd1) && $stable(sel) && $stable(data1)) ||
          ((sel === 3'd2) && $stable(sel) && $stable(data2)) ||
          ((sel === 3'd3) && $stable(sel) && $stable(data3)) ||
          ((sel === 3'd4) && $stable(sel) && $stable(data4)) ||
          ((sel === 3'd5) && $stable(sel) && $stable(data5)) ||
          ((!((sel === 3'd0) || (sel === 3'd1) || (sel === 3'd2) ||
              (sel === 3'd3) || (sel === 3'd4) || (sel === 3'd5))) && $stable(sel))))
        |-> $stable(out)
    );

endmodule

rtl:
module sky130_fd_sc_hd__lpflow_isobufsrckapwr (
    X    ,
    SLEEP,
    A
);

    output X    ;
    input  SLEEP;
    input  A    ;

    wire not0_out  ;
    wire and0_out_X;

    not not0 (not0_out  , SLEEP          );
    and and0 (and0_out_X, not0_out, A    );
    buf buf0 (X         , and0_out_X     );

endmodule

sva:
module sky130_fd_sc_hd__lpflow_isobufsrckapwr_sva (
    input logic clk,
    input logic X,
    input logic SLEEP,
    input logic A
);

    // X equals A gated by the inverse of SLEEP.
    check_functional_equivalence: assert property (
        @(posedge clk) X == ((~SLEEP) & A)
    );

    // SLEEP high forces X low.
    check_sleep_forces_low: assert property (
        @(posedge clk) (SLEEP == 1'b1) |-> (X == 1'b0)
    );

    // When not sleeping, X matches A.
    check_awake_passes_a: assert property (
        @(posedge clk) (SLEEP == 1'b0) |-> (X == A)
    );

    // A low forces X low.
    check_a_low_forces_low: assert property (
        @(posedge clk) (A == 1'b0) |-> (X == 1'b0)
    );

    // X high requires SLEEP low and A high.
    check_x_high_requires_inputs: assert property (
        @(posedge clk) (X == 1'b1) |-> ((SLEEP == 1'b0) && (A == 1'b1))
    );

endmodule

rtl:
module mux_4to1_enable (
    input [3:0] in,
    input [1:0] sel,
    input enable,
    output reg out
);

    always @(*) 
        out = (enable & in[sel]);

endmodule

sva:
module mux_4to1_enable_sva (
    input logic [3:0] in,
    input logic [1:0] sel,
    input logic enable,
    input logic out
);

    // Output matches the RTL equation.
    check_output_matches_mux_equation: assert property (
        @($global_clock) out == (enable & in[sel])
    );

    // When disabled, the output is low.
    check_disable_forces_low: assert property (
        @($global_clock) (!enable) |-> (out == 1'b0)
    );

    // With sel=0 and enable high, output follows in[0].
    check_sel_0_routes_in0: assert property (
        @($global_clock) (enable && (sel == 2'b00)) |-> (out == in[0])
    );

    // With sel=1 and enable high, output follows in[1].
    check_sel_1_routes_in1: assert property (
        @($global_clock) (enable && (sel == 2'b01)) |-> (out == in[1])
    );

    // With sel=2 and enable high, output follows in[2].
    check_sel_2_routes_in2: assert property (
        @($global_clock) (enable && (sel == 2'b10)) |-> (out == in[2])
    );

    // With sel=3 and enable high, output follows in[3].
    check_sel_3_routes_in3: assert property (
        @($global_clock) (enable && (sel == 2'b11)) |-> (out == in[3])
    );

endmodule

rtl:
module boolean_func (
  input a,
  input b,
  input c,
  output z
);

  assign z = (a & b) ^ (c | ~b);

endmodule

sva:
module boolean_func_sva (
    input logic clk,
    input logic a,
    input logic b,
    input logic c,
    input logic z
);

    // z matches the RTL boolean expression.
    check_output_equation: assert property (
        @(posedge clk) z == ((a & b) ^ (c | ~b))
    );

    // When b is low, z is always high.
    check_b_low_forces_z_high: assert property (
        @(posedge clk) !b |-> (z == 1'b1)
    );

    // When b is high, z reduces to a XOR c.
    check_b_high_reduces_to_xor: assert property (
        @(posedge clk) b |-> (z == (a ^ c))
    );

    // With b high and equal inputs, z is low.
    check_b_high_equal_inputs_drive_low: assert property (
        @(posedge clk) (b && (a == c)) |-> (z == 1'b0)
    );

    // With b high and different inputs, z is high.
    check_b_high_different_inputs_drive_high: assert property (
        @(posedge clk) (b && (a != c)) |-> (z == 1'b1)
    );

    // z can be low only when b is high and a equals c.
    check_low_output_condition: assert property (
        @(posedge clk) !z |-> (b && (a == c))
    );

endmodule

rtl:
module and_enable(
    input in1,
    input in2,
    input en,
    output out
);

    assign out = (en == 1'b1) ? (in1 & in2) : 1'b0;

endmodule

sva:
module and_enable_sva (
    input logic clk,
    input logic in1,
    input logic in2,
    input logic en,
    input logic out
);

    // Output matches the RTL assign expression.
    check_out_definition: assert property (
        @(posedge clk) out === ((en == 1'b1) ? (in1 & in2) : 1'b0)
    );

    // When disabled, the output is forced low.
    check_disable_forces_zero: assert property (
        @(posedge clk) (en === 1'b0) |-> (out === 1'b0)
    );

    // When enabled, the output equals the AND of the inputs.
    check_enabled_matches_and: assert property (
        @(posedge clk) (en === 1'b1) |-> (out === (in1 & in2))
    );

    // A high output requires enable and both inputs high.
    check_out_high_requires_all_high: assert property (
        @(posedge clk) (out === 1'b1) |-> ((en === 1'b1) && (in1 === 1'b1) && (in2 === 1'b1))
    );

    // Enable high with both inputs high drives the output high.
    check_all_high_drives_high: assert property (
        @(posedge clk) ((en === 1'b1) && (in1 === 1'b1) && (in2 === 1'b1)) |-> (out === 1'b1)
    );

    // Enable high with in1 low drives the output low.
    check_in1_low_blocks_output: assert property (
        @(posedge clk) ((en === 1'b1) && (in1 === 1'b0)) |-> (out === 1'b0)
    );

    // Enable high with in2 low drives the output low.
    check_in2_low_blocks_output: assert property (
        @(posedge clk) ((en === 1'b1) && (in2 === 1'b0)) |-> (out === 1'b0)
    );

endmodule

rtl:
module adder_4bit ( A, B, Ci, S, Co );
  input [3:0] A, B;
  input Ci;
  output [3:0] S;
  output Co;

  wire [3:0] sum;
  wire c1, c2, c3;

  // Full-adder for least significant bit
  full_adder fa1(.a(A[0]), .b(B[0]), .c(Ci), .sum(sum[0]), .cout(c1));

  // Full-adder for second least significant bit
  full_adder fa2(.a(A[1]), .b(B[1]), .c(c1), .sum(sum[1]), .cout(c2));

  // Full-adder for third least significant bit
  full_adder fa3(.a(A[2]), .b(B[2]), .c(c2), .sum(sum[2]), .cout(c3));

  // Full-adder for most significant bit
  full_adder fa4(.a(A[3]), .b(B[3]), .c(c3), .sum(sum[3]), .cout(Co));

  assign S = sum;

endmodule

module full_adder (a, b, c, sum, cout);
  input a, b, c;
  output sum, cout;

  wire s1, c1, c2;

  // First half-adder
  half_adder ha1(.a(a), .b(b), .sum(s1), .cout(c1));

  // Second half-adder
  half_adder ha2(.a(s1), .b(c), .sum(sum), .cout(c2));

  // OR gate for carry-out
  assign cout = c1 | c2;

endmodule

module half_adder (a, b, sum, cout);
  input a, b;
  output sum, cout;

  // XOR gate for sum
  assign sum = a ^ b;

  // AND gate for carry-out
  assign cout = a & b;

endmodule

sva:
module adder_4bit_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic Ci,
    input logic [3:0] S,
    input logic Co
);

    function automatic logic carry3(input logic a, input logic b, input logic c);
        carry3 = (a & b) | ((a ^ b) & c);
    endfunction

    // Outputs must match 4-bit addition with carry-in.
    check_full_sum: assert property (
        @($global_clock) {Co, S} == ({1'b0, A} + {1'b0, B} + {4'b0, Ci})
    );

    // Sum bit 0 is the XOR of A[0], B[0], and Ci.
    check_sum_bit0: assert property (
        @($global_clock) S[0] == (A[0] ^ B[0] ^ Ci)
    );

    // Sum bit 1 uses the carry from bit 0.
    check_sum_bit1: assert property (
        @($global_clock) S[1] == (A[1] ^ B[1] ^ carry3(A[0], B[0], Ci))
    );

    // Sum bit 2 uses the carry from bit 1.
    check_sum_bit2: assert property (
        @($global_clock) S[2] == (A[2] ^ B[2] ^ carry3(A[1], B[1], carry3(A[0], B[0], Ci)))
    );

    // Sum bit 3 uses the carry from bit 2.
    check_sum_bit3: assert property (
        @($global_clock) S[3] == (A[3] ^ B[3] ^ carry3(A[2], B[2], carry3(A[1], B[1], carry3(A[0], B[0], Ci))))
    );

    // Carry-out is the carry from the most significant stage.
    check_carry_out: assert property (
        @($global_clock) Co == carry3(A[3], B[3], carry3(A[2], B[2], carry3(A[1], B[1], carry3(A[0], B[0], Ci))))
    );

    // Zero operands leave only the carry-in in the result.
    check_zero_operands: assert property (
        @($global_clock) (A == 4'b0000 && B == 4'b0000) |-> (S == {3'b000, Ci} && Co == 1'b0)
    );

    // With B and Ci low, the adder passes A through unchanged.
    check_pass_through_a: assert property (
        @($global_clock) (B == 4'b0000 && Ci == 1'b0) |-> (S == A && Co == 1'b0)
    );

    // With A and Ci low, the adder passes B through unchanged.
    check_pass_through_b: assert property (
        @($global_clock) (A == 4'b0000 && Ci == 1'b0) |-> (S == B && Co == 1'b0)
    );

    // With B low and Ci high, the adder increments A by one.
    check_increment_a: assert property (
        @($global_clock) (B == 4'b0000 && Ci == 1'b1) |-> ({Co, S} == ({1'b0, A} + 5'b00001))
    );

endmodule

