sva:
module my_module_sva (
    input logic clk,
    input logic Y,
    input logic A1,
    input logic A2,
    input logic B1
);

    // Y matches the implemented NOR-of-AND function.
    check_y_function: assert property (
        @(posedge clk) Y == ~(B1 | (A1 & A2))
    );

    // A high B1 forces the NOR output low.
    check_b1_high_forces_y_low: assert property (
        @(posedge clk) B1 |-> !Y
    );

    // A high A1/A2 product term forces the NOR output low.
    check_and_term_high_forces_y_low: assert property (
        @(posedge clk) (A1 && A2) |-> !Y
    );

    // Y is high when both inputs to the NOR are low.
    check_both_nor_inputs_low_gives_y_high: assert property (
        @(posedge clk) (!B1 && !(A1 && A2)) |-> Y
    );

    // A high Y implies B1 is low.
    check_y_high_implies_b1_low: assert property (
        @(posedge clk) Y |-> !B1
    );

    // With B1 low, a low Y implies the AND term is high.
    check_b1_low_and_y_low_implies_and_term_high: assert property (
        @(posedge clk) (!B1 && !Y) |-> (A1 && A2)
    );

endmodule

rtl:
module comparator_4bit (
  input [3:0] in1,
  input [3:0] in2,
  output eq,
  output gt,
  output lt
);

  assign eq = (in1 == in2);
  assign gt = (in1 > in2);
  assign lt = (in1 < in2);

endmodule

sva:
module comparator_4bit_sva (
    input logic       clk,
    input logic [3:0] in1,
    input logic [3:0] in2,
    input logic       eq,
    input logic       gt,
    input logic       lt
);

    // eq matches the equality comparison.
    check_eq_matches_inputs: assert property (
        @(posedge clk) (eq === (in1 == in2))
    );

    // gt matches the greater-than comparison.
    check_gt_matches_inputs: assert property (
        @(posedge clk) (gt === (in1 > in2))
    );

    // lt matches the less-than comparison.
    check_lt_matches_inputs: assert property (
        @(posedge clk) (lt === (in1 < in2))
    );

    // Comparison outputs never assert together.
    check_outputs_mutually_exclusive: assert property (
        @(posedge clk) (!(eq && gt) && !(eq && lt) && !(gt && lt))
    );

    // One comparison result is always indicated.
    check_outputs_complete: assert property (
        @(posedge clk) (eq || gt || lt)
    );

    // Equal inputs drive only eq high.
    check_equal_case_result: assert property (
        @(posedge clk) ((in1 == in2) |-> (eq && !gt && !lt))
    );

    // Larger in1 drives only gt high.
    check_greater_case_result: assert property (
        @(posedge clk) ((in1 > in2) |-> (!eq && gt && !lt))
    );

    // Smaller in1 drives only lt high.
    check_less_case_result: assert property (
        @(posedge clk) ((in1 < in2) |-> (!eq && !gt && lt))
    );

endmodule

