sva:
module sync_counter_assertions (
    input logic       clk_in,
    input logic       rstn,
    input logic [3:0] count_out
);

    // A sampled low reset must leave the counter at zero on the next clock.
    check_reset_clears_counter: assert property (
        @(posedge clk_in) !rstn |=> (count_out == 4'b0000)
    );

    // From an active sampled cycle, the next sampled value is either zero or the previous value plus one.
    check_count_transitions_are_reset_or_increment: assert property (
        @(posedge clk_in) disable iff (!rstn)
        (!$initstate && $past(rstn)) |-> ((count_out == 4'b0000) || (count_out == ($past(count_out) + 4'd1)))
    );

    // Any nonzero sampled count must come from incrementing the previous sampled value.
    check_nonzero_count_is_incremented: assert property (
        @(posedge clk_in) disable iff (!rstn)
        (!$initstate && (count_out != 4'b0000)) |-> (count_out == ($past(count_out) + 4'd1))
    );

    // A sampled value of 15 is followed by zero on the next sampled clock.
    check_count_wraps_from_max: assert property (
        @(posedge clk_in) disable iff (!rstn)
        (!$initstate && ($past(count_out) == 4'hF)) |-> (count_out == 4'h0)
    );

endmodule

rtl:
module barrel_shifter (
    input [15:0] in,
    input [3:0] shift_amount,
    output [15:0] out
);

    assign out = (shift_amount >= 0) ? (in << shift_amount) : (in >> -shift_amount);

endmodule

sva:
module barrel_shifter_sva (
    input logic [15:0] in,
    input logic [3:0]  shift_amount,
    input logic [15:0] out
);

    // Output always matches the implemented left shift.
    check_out_matches_left_shift: assert property (
        @($global_clock) out == (in << shift_amount)
    );

    // A zero shift leaves the input unchanged.
    check_zero_shift_passthrough: assert property (
        @($global_clock) (shift_amount == 4'd0) |-> (out == in)
    );

    // Any nonzero shift clears the least-significant output bit.
    check_nonzero_shift_clears_lsb: assert property (
        @($global_clock) (shift_amount != 4'd0) |-> (out[0] == 1'b0)
    );

    // A shift of two or more clears the two least-significant output bits.
    check_shift_two_or_more_clears_two_lsbs: assert property (
        @($global_clock) (shift_amount >= 4'd2) |-> (out[1:0] == 2'b00)
    );

    // A shift of eight or more clears the low output byte.
    check_large_shift_clears_low_byte: assert property (
        @($global_clock) (shift_amount >= 4'd8) |-> (out[7:0] == 8'h00)
    );

    // The maximum shift keeps only input bit 0 in the top output bit.
    check_max_shift_behavior: assert property (
        @($global_clock) (shift_amount == 4'd15) |-> (out == {in[0], 15'h0000})
    );

    // A zero input always produces a zero output.
    check_zero_input_produces_zero_output: assert property (
        @($global_clock) (in == 16'h0000) |-> (out == 16'h0000)
    );

endmodule

module up_down_counter_sva (
    input logic clk,
    input logic [3:0] D,
    input logic UD,
    input logic CE,
    input logic [3:0] Q
);

    // When enabled in up mode, Q increments on the next clock.
    check_increment_when_enabled_up: assert property (
        @(posedge clk)
        (CE && UD) |=> (Q == ($past(Q) + 4'd1))
    );

    // When enabled in down mode, Q decrements on the next clock.
    check_decrement_when_enabled_down: assert property (
        @(posedge clk)
        (CE && !UD) |=> (Q == ($past(Q) - 4'd1))
    );

    // When not enabled, Q loads D on the next clock.
    check_load_d_when_disabled: assert property (
        @(posedge clk)
        (!CE) |=> (Q == $past(D))
    );

    // Counting up from 4'hF wraps Q to 4'h0.
    check_up_wraparound: assert property (
        @(posedge clk)
        (CE && UD && (Q == 4'hF)) |=> (Q == 4'h0)
    );

    // Counting down from 4'h0 wraps Q to 4'hF.
    check_down_wraparound: assert property (
        @(posedge clk)
        (CE && !UD && (Q == 4'h0)) |=> (Q == 4'hF)
    );

    // Q always follows the RTL next-state function.
    check_complete_next_state: assert property (
        @(posedge clk)
        1'b1 |=> (Q == ($past(CE) ? ($past(UD) ? ($past(Q) + 4'd1) : ($past(Q) - 4'd1)) : $past(D)))
    );

endmodule

