rtl:
module barrel_shifter (
    input [3:0] data,
    input [1:0] shift,
    input shift_right,
    input shift_left,
    input rotate_right,
    input rotate_left,
    output reg [3:0] result
);

always @(*) begin
    case ({rotate_left, rotate_right, shift_left, shift_right})
        4'b0001: result = {data[2:0], data[3]};
        4'b0010: result = {data[1:0], data[3:2]};
        4'b0100: result = {data[0], data[3:1]};
        4'b1000: result = {data[3], data[2:0]};
        default: result = data;
    endcase
end

endmodule

sva:
module barrel_shifter_sva (
    input logic clk,
    input logic [3:0] data,
    input logic [1:0] shift,
    input logic shift_right,
    input logic shift_left,
    input logic rotate_right,
    input logic rotate_left,
    input logic [3:0] result
);

    // When only shift_right is asserted, result matches the 0001 case mapping.
    check_shift_right_case: assert property (
        @(posedge clk)
        ({rotate_left, rotate_right, shift_left, shift_right} == 4'b0001)
        |-> (result == {data[2:0], data[3]})
    );

    // When only shift_left is asserted, result matches the 0010 case mapping.
    check_shift_left_case: assert property (
        @(posedge clk)
        ({rotate_left, rotate_right, shift_left, shift_right} == 4'b0010)
        |-> (result == {data[1:0], data[3:2]})
    );

    // When only rotate_right is asserted, result matches the 0100 case mapping.
    check_rotate_right_case: assert property (
        @(posedge clk)
        ({rotate_left, rotate_right, shift_left, shift_right} == 4'b0100)
        |-> (result == {data[0], data[3:1]})
    );

    // When only rotate_left is asserted, result matches the 1000 case mapping.
    check_rotate_left_case: assert property (
        @(posedge clk)
        ({rotate_left, rotate_right, shift_left, shift_right} == 4'b1000)
        |-> (result == {data[3], data[2:0]})
    );

    // Any control pattern not explicitly decoded passes data through unchanged.
    check_default_passthrough: assert property (
        @(posedge clk)
        (({rotate_left, rotate_right, shift_left, shift_right} != 4'b0001) &&
         ({rotate_left, rotate_right, shift_left, shift_right} != 4'b0010) &&
         ({rotate_left, rotate_right, shift_left, shift_right} != 4'b0100) &&
         ({rotate_left, rotate_right, shift_left, shift_right} != 4'b1000))
        |-> (result == data)
    );

    // Changing shift alone does not change result because shift is unused.
    check_shift_input_unused: assert property (
        @(posedge clk)
        !$initstate &&
        $changed(shift) &&
        $stable(data) &&
        $stable({rotate_left, rotate_right, shift_left, shift_right})
        |-> $stable(result)
    );

endmodule

rtl:
module delay_element(
    input A,
    input VPWR,
    input VGND,
    input VPB,
    input VNB,
    output reg X
);

reg [31:0] count = 0;

always @(posedge VPWR)
begin
    if (count == 500)
        X <= A;
    else
        count <= count + 1;
end

endmodule

sva:
module delay_element_sva (
    input logic A,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB,
    input logic X,
    input logic [31:0] count
);

    // count starts from its declared initial value of zero.
    check_count_initializes_to_zero: assert property (
        @(posedge VPWR) $initstate |-> (count == 32'd0)
    );

    // count increments by one on each clock until it reaches 500.
    check_count_increments_before_500: assert property (
        @(posedge VPWR) disable iff ($initstate)
        ($past(count) < 32'd500) |-> (count == ($past(count) + 32'd1))
    );

    // count holds at 500 once the terminal value is reached.
    check_count_holds_at_500: assert property (
        @(posedge VPWR) disable iff ($initstate)
        ($past(count) == 32'd500) |-> (count == 32'd500)
    );

    // reaching count 500 can only come from 499 or remain at 500.
    check_count_500_has_valid_predecessor: assert property (
        @(posedge VPWR) disable iff ($initstate)
        (count == 32'd500) |-> (($past(count) == 32'd499) || ($past(count) == 32'd500))
    );

    // X is not updated while the previous count was below 500.
    check_x_stable_before_delay_expires: assert property (
        @(posedge VPWR) disable iff ($initstate)
        ($past(count) < 32'd500) |-> (X === $past(X))
    );

    // After count reaches 500, X reflects the previous sampled value of A.
    check_x_captures_a_after_delay_expires: assert property (
        @(posedge VPWR) disable iff ($initstate)
        ($past(count) == 32'd500) |-> (X === $past(A))
    );

    // Any observed change on X requires the previous count to have been 500.
    check_x_changes_only_after_delay_expires: assert property (
        @(posedge VPWR) disable iff ($initstate)
        (X !== $past(X)) |-> ($past(count) == 32'd500)
    );

endmodule

rtl:
module sync_load_counter (
    input clk,
    input reset,
    input load,
    input [3:0] L,
    input areset,
    output reg [3:0] count
);

reg [3:0] count_reg1;
reg [3:0] count_reg2;

always @(posedge clk or negedge areset) begin
    if (areset == 0) begin
        count_reg1 <= 0;
        count_reg2 <= 0;
    end
    else begin
        count_reg1 <= count_reg2;
        count_reg2 <= count;
    end
end

always @(posedge clk) begin
    if (reset == 1) begin
        count <= 0;
    end
    else if (load == 1) begin
        count <= L;
    end
    else begin
        count <= count_reg1 + 1;
    end
end

endmodule

sva:
module sync_load_counter_sva (
    input logic clk,
    input logic reset,
    input logic load,
    input logic [3:0] L,
    input logic areset,
    input logic [3:0] count,
    input logic [3:0] count_reg1,
    input logic [3:0] count_reg2
);

    // Sync reset forces count to zero on the next clock.
    check_sync_reset_clears_count: assert property (
        @(posedge clk) disable iff (!areset)
        reset |=> (count == 4'd0)
    );

    // Load copies L into count on the next clock when reset is low.
    check_load_captures_L: assert property (
        @(posedge clk) disable iff (!areset)
        (!reset && load) |=> (count == $past(L))
    );

    // Free-running mode increments from count_reg1 on the next clock.
    check_free_run_increments_from_count_reg1: assert property (
        @(posedge clk) disable iff (!areset)
        (!reset && !load) |=> (count == ($past(count_reg1) + 4'd1))
    );

    // Reset has priority over load in the count update logic.
    check_reset_overrides_load: assert property (
        @(posedge clk) disable iff (!areset)
        (reset && load) |=> (count == 4'd0)
    );

    // A sampled async reset leaves both pipeline registers cleared.
    check_async_reset_clears_pipe_regs: assert property (
        @(posedge clk) disable iff (!areset)
        (!$past(areset)) |-> ((count_reg1 == 4'd0) && (count_reg2 == 4'd0))
    );

    // The first free-running cycle after a sampled async reset produces 1.
    check_async_reset_recovery_counts_one: assert property (
        @(posedge clk) disable iff (!areset)
        ((!$past(areset)) && !reset && !load) |=> (count == 4'd1)
    );

endmodule

