    // anyedge matches the RTL equation using the two previous input samples.
    check_anyedge_matches_rtl: assert property (
        @(posedge clk)
        (!$isunknown($past(in,1)) && !$isunknown($past(in,2))) |->
        (anyedge == (($past(in,1) != $past(in,2)) ? 8'h00 : ($past(in,1) & ~$past(in,2))))
    );

    // A sampled input change causes anyedge to be cleared on the following cycle.
    check_change_branch_clears_output: assert property (
        @(posedge clk)
        (!$isunknown($past(in,1)) && !$isunknown($past(in,2)) && ($past(in,1) != $past(in,2))) |->
        (anyedge == 8'h00)
    );

    // When sampled inputs match, anyedge follows the in & ~prev_in branch.
    check_stable_branch_expression: assert property (
        @(posedge clk)
        (!$isunknown($past(in,1)) && !$isunknown($past(in,2)) && ($past(in,1) == $past(in,2))) |->
        (anyedge == ($past(in,1) & ~$past(in,2)))
    );

    // With two known prior samples, the implemented logic always drives anyedge low.
    check_anyedge_always_zero_after_startup: assert property (
        @(posedge clk)
        (!$isunknown($past(in,1)) && !$isunknown($past(in,2))) |->
        (anyedge == 8'h00)
    );

endmodule

module up_down_counter_assertions (
    input logic clk,
    input logic up_down,
    input logic load,
    input logic reset,
    input logic [3:0] D,
    input logic [3:0] Q
);

    // Reset drives Q to zero on the following clock.
    check_reset_clears_q: assert property (
        @(posedge clk) disable iff ($initstate)
        reset |=> (Q == 4'b0000)
    );

    // Outside reset, Q follows the RTL next-state function.
    check_nonreset_next_state: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        1'b1 |=> (Q == ($past(load) ? $past(D) :
                       ($past(up_down) ? ($past(Q) + 4'd1) :
                                         ($past(Q) - 4'd1))))
    );

    // Load updates Q with D on the next clock.
    check_load_updates_q: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        load |=> (Q == $past(D))
    );

    // When load is low and up_down is high, Q increments by one.
    check_count_up_updates_q: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        (!load && up_down) |=> (Q == ($past(Q) + 4'd1))
    );

    // When load is low and up_down is low, Q decrements by one.
    check_count_down_updates_q: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        (!load && !up_down) |=> (Q == ($past(Q) - 4'd1))
    );

endmodule

rtl:
module top_module (
    input CLK, RST,
    input UD1, LD1, input [7:0] LOAD_IN1, output wire [7:0] Q1,
    input UD2, LD2, input [7:0] LOAD_IN2, output wire [7:0] Q2,
    output [7:0] sum
);

reg [7:0] count1, count2;

always @(posedge CLK) begin
    if (RST) begin
        count1 <= 8'b0;
        count2 <= 8'b0;
    end else begin
        if (UD1) begin
            count1 <= count1 + 1;
        end else begin
            count1 <= count1 - 1;
        end

        if (UD2) begin
            count2 <= count2 + 1;
        end else begin
            count2 <= count2 - 1;
        end

        if (LD1) begin
            count1 <= LOAD_IN1;
        end

        if (LD2) begin
            count2 <= LOAD_IN2;
        end
    end
end

assign sum = count1 + count2;

assign Q1 = count1;
assign Q2 = count2;

endmodule

sva:
module top_module_sva (
    input logic CLK,
    input logic RST,
    input logic UD1,
    input logic LD1,
    input logic [7:0] LOAD_IN1,
    input logic [7:0] Q1,
    input logic UD2,
    input logic LD2,
    input logic [7:0] LOAD_IN2,
    input logic [7:0] Q2,
    input logic [7:0] sum
);

    // Synchronous reset clears both counters and the sum.
    check_reset_clears_outputs: assert property (
        @(posedge CLK) RST |=> (Q1 == 8'h00) && (Q2 == 8'h00) && (sum == 8'h00)
    );

    // The sum output matches the two counter outputs.
    check_sum_matches_q1_q2: assert property (
        @(posedge CLK) disable iff (RST) sum == (Q1 + Q2)
    );

    // LD1 overrides the count direction and loads LOAD_IN1.
    check_q1_load_priority: assert property (
        @(posedge CLK) disable iff (RST) LD1 |=> (Q1 == $past(LOAD_IN1))
    );

    // Without LD1, UD1 high increments Q1.
    check_q1_increment: assert property (
        @(posedge CLK) disable iff (RST) (!LD1 && UD1) |=> (Q1 == ($past(Q1) + 8'd1))
    );

    // Without LD1, UD1 low decrements Q1.
    check_q1_decrement: assert property (
        @(posedge CLK) disable iff (RST) (!LD1 && !UD1) |=> (Q1 == ($past(Q1) - 8'd1))
    );

    // LD2 overrides the count direction and loads LOAD_IN2.
    check_q2_load_priority: assert property (
        @(posedge CLK) disable iff (RST) LD2 |=> (Q2 == $past(LOAD_IN2))
    );

    // Without LD2, UD2 high increments Q2.
    check_q2_increment: assert property (
        @(posedge CLK) disable iff (RST) (!LD2 && UD2) |=> (Q2 == ($past(Q2) + 8'd1))
    );

    // Without LD2, UD2 low decrements Q2.
    check_q2_decrement: assert property (
        @(posedge CLK) disable iff (RST) (!LD2 && !UD2) |=> (Q2 == ($past(Q2) - 8'd1))
    );

endmodule

rtl:
module pipeline_register #(
  parameter n = 8 // width of the pipeline register
) (
  input clk,
  input rst,
  input [n-1:0] in,
  output reg [n-1:0] out
);

always @(posedge clk or posedge rst) begin
  if (rst) begin
    out <= 0;
  end else begin
    out <= in;
  end
end

endmodule

sva:
module pipeline_register_sva #(
  parameter n = 8
) (
  input logic clk,
  input logic rst,
  input logic [n-1:0] in,
  input logic [n-1:0] out
);

  // Reset forces the register output to zero.
  check_reset_forces_zero: assert property (
    @(posedge clk) rst |-> (out == '0)
  );

  // Continuous reset keeps the sampled output zero and unchanged.
  check_reset_holds_zero: assert property (
    @(posedge clk) ($past(rst) && rst) |-> ($stable(out) && (out == '0))
  );

  // The first non-reset clock still samples the reset value before loading input.
  check_first_clock_after_reset_samples_zero: assert property (
    @(posedge clk) disable iff (rst) $past(rst) |-> ($stable(out) && (out == '0))
  );

endmodule

rtl:
module adder_4bit(A, B, S, Cout);
input [3:0] A;
input [3:0] B;
output [3:0] S;
output Cout;

wire [4:0] temp_sum;
assign temp_sum = A + B;

assign Cout = temp_sum[4];
assign S = temp_sum[3:0];

endmodule

sva:
module adder_4bit_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] S,
    input logic Cout
);

    // The 5-bit output matches the zero-extended sum of A and B.
    check_full_sum_correct: assert property (
        @(posedge clk) disable iff (1'b0)
        ({Cout, S} == ({1'b0, A} + {1'b0, B}))
    );

    // Zero plus zero produces a zero result with no carry.
    check_zero_plus_zero: assert property (
        @(posedge clk) disable iff (1'b0)
        ((A == 4'h0) && (B == 4'h0)) |-> ({Cout, S} == 5'h00)
    );

    // Adding zero on A passes B directly to the output.
    check_a_zero_passthrough: assert property (
        @(posedge clk) disable iff (1'b0)
        (A == 4'h0) |-> ({Cout, S} == {1'b0, B})
    );

    // Adding zero on B passes A directly to the output.
    check_b_zero_passthrough: assert property (
        @(posedge clk) disable iff (1'b0)
        (B == 4'h0) |-> ({Cout, S} == {1'b0, A})
    );

    // Maximum inputs produce 30 with carry-out asserted.
    check_max_plus_max: assert property (
        @(posedge clk) disable iff (1'b0)
        ((A == 4'hf) && (B == 4'hf)) |-> ({Cout, S} == 5'h1e)
    );

endmodule

rtl:
module NIOS_SYSTEMV3_LCD (
  // inputs:
  address,
  begintransfer,
  clk,
  read,
  reset_n,
  write,
  writedata,

  // outputs:
  LCD_E,
  LCD_RS,
  LCD_RW,
  LCD_data
);

  output LCD_E;
  output LCD_RS;
  output LCD_RW;
  output [7:0] LCD_data;
  input [1:0] address;
  input begintransfer;
  input clk;
  input read;
  input reset_n;
  input write;
  input [7:0] writedata;

  reg [7:0] LCD_data;

  assign LCD_RW = ~address[0];
  assign LCD_RS = address[1];

  reg LCD_E;
  always @(posedge clk or negedge reset_n)
    if (~reset_n)
      LCD_E <= 1'b0;
    else if (read | write)
      LCD_E <= 1'b1;
    else
      LCD_E <= 1'b0;

  always @(posedge clk or negedge reset_n)
  begin
    if (~reset_n)
      LCD_data <= 0;
    else if (write)
      LCD_data <= writedata;
  end

endmodule

sva:
module NIOS_SYSTEMV3_LCD_sva (
    input logic [1:0] address,
    input logic       begintransfer,
    input logic       clk,
    input logic       read,
    input logic       reset_n,
    input logic       write,
    input logic [7:0] writedata,
    input logic       LCD_E,
    input logic       LCD_RS,
    input logic       LCD_RW,
    input logic [7:0] LCD_data
);

    // LCD_RW is the inverse of address[0].
    check_lcd_rw_decode: assert property (
        @(posedge clk) disable iff (!reset_n)
        (LCD_RW == ~address[0])
    );

    // LCD_RS follows address[1].
    check_lcd_rs_decode: assert property (
        @(posedge clk) disable iff (!reset_n)
        (LCD_RS == address[1])
    );

    // LCD_E is low while reset is asserted.
    check_lcd_e_reset_low: assert property (
        @(posedge clk)
        (!reset_n) |-> (LCD_E == 1'b0)
    );

    // LCD_data is zero while reset is asserted.
    check_lcd_data_reset_zero: assert property (
        @(posedge clk)
        (!reset_n) |-> (LCD_data == 8'h00)
    );

    // Any read or write drives LCD_E high on the next cycle.
    check_lcd_e_set_on_access: assert property (
        @(posedge clk) disable iff (!reset_n)
        (read || write) |=> (LCD_E == 1'b1)
    );

    // No read or write drives LCD_E low on the next cycle.
    check_lcd_e_clear_without_access: assert property (
        @(posedge clk) disable iff (!reset_n)
        (!read && !write) |=> (LCD_E == 1'b0)
    );

    // A write captures writedata into LCD_data on the next cycle.
    check_lcd_data_capture_on_write: assert property (
        @(posedge clk) disable iff (!reset_n)
        write |=> (LCD_data == $past(writedata))
    );

    // Without a write, LCD_data holds its previous value.
    check_lcd_data_hold_without_write: assert property (
        @(posedge clk) disable iff (!reset_n)
        !write |=> (LCD_data == $past(LCD_data))
    );

endmodule

module SIPO_sva (
    input logic       clk,
    input logic       rst,
    input logic       SerialIn,
    input logic [3:0] BusOut
);

    // A sampled reset cycle clears the parallel output by the next clock.
    check_reset_clears_busout: assert property (
        @(posedge clk) !rst |=> (BusOut == 4'b0000)
    );

    // The sampled output remains zero on the first cycle after reset release.
    check_reset_release_keeps_zero_before_shift: assert property (
        @(posedge clk) (!rst ##1 rst) |-> (BusOut == 4'b0000)
    );

    // In normal operation, the output shifts left and loads SerialIn into bit 0.
    check_shift_register_update: assert property (
        @(posedge clk) disable iff (!rst)
        1'b1 |=> (BusOut == { $past(BusOut[2:0]), $past(SerialIn) })
    );

    // Bit 3 takes the previous value of bit 2.
    check_bit3_shift_from_bit2: assert property (
        @(posedge clk) disable iff (!rst)
        1'b1 |=> (BusOut[3] == $past(BusOut[2]))
    );

    // Bit 2 takes the previous value of bit 1.
    check_bit2_shift_from_bit1: assert property (
        @(posedge clk) disable iff (!rst)
        1'b1 |=> (BusOut[2] == $past(BusOut[1]))
    );

    // Bit 1 takes the previous value of bit 0.
    check_bit1_shift_from_bit0: assert property (
        @(posedge clk) disable iff (!rst)
        1'b1 |=> (BusOut[1] == $past(BusOut[0]))
    );

    // Bit 0 captures the previous SerialIn value.
    check_bit0_captures_serialin: assert property (
        @(posedge clk) disable iff (!rst)
        1'b1 |=> (BusOut[0] == $past(SerialIn))
    );

endmodule

