    // Input 01 must produce q=0 and zero=0.
    check_encode_01: assert property (
        @($global_clock) (data == 2'b01) |-> (!q && !zero)
    );

    // Input 10 must produce q=1 and zero=0.
    check_encode_10: assert property (
        @($global_clock) (data == 2'b10) |-> (q && !zero)
    );

