module MUX2B (A, B, S, Y); 
input A, B;
input S;
output Y;
wire A_not, B_not;

// Invert the inputs
assign A_not = ~A;
assign B_not = ~B;

// Implement the multiplexer using AND-OR gates
assign Y = (A & S) | (B & A_not);

endmodule

