    check_state_001_to_011: assert property (
        @(posedge clk) disable iff (reset)
        (count == 3'b001) |=> (count == 3'b011)
    );

    // State 011 advances to 111.
    check_state_011_to_111: assert property (
        @(posedge clk) disable iff (reset)
        (count == 3'b011) |=> (count == 3'b111)
    );

    // State 111 advances to 110.
    check_state_111_to_110: assert property (
        @(posedge clk) disable iff (reset)
        (count == 3'b111) |=> (count == 3'b110)
    );

    // State 110 advances to 100.
    check_state_110_to_100: assert property (
        @(posedge clk) disable iff (reset)
        (count == 3'b110) |=> (count == 3'b100)
    );

    // State 100 advances to 000.
    check_state_100_to_000: assert property (
        @(posedge clk) disable iff (reset)
        (count == 3'b100) |=> (count == 3'b000)
    );

endmodule

rtl:
module ThermoGauge(
    gauge,
    value,
    enable,
    enforce
);

    parameter LOGWORD = 0;
    localparam WORD = (1<<LOGWORD);

    output wire [WORD-1:0] gauge;
    input [LOGWORD-1:0] value;
    input enable;
    input enforce;

    wire [WORD-1:0] shifted_value;
    wire [WORD-1:0] shifted_value_plus_one;

    assign shifted_value = {1'b0, value};
    assign shifted_value_plus_one = shifted_value + 1'b1;

    assign gauge = (enable && !enforce) ? shifted_value_plus_one : shifted_value;

endmodule

sva:
module ThermoGauge_sva #(
    parameter int LOGWORD = 0
)(
    input logic clk,
    input logic [(1<<LOGWORD)-1:0] gauge,
    input logic [((LOGWORD > 0) ? LOGWORD : 1)-1:0] value,
    input logic enable,
    input logic enforce
);

    localparam int WORD  = (1 << LOGWORD);
    localparam int PAD_W = (LOGWORD > 0) ? (WORD - (LOGWORD + 1)) : 0;

    generate
        if (LOGWORD > 0) begin : gen_logword_gt_0

            // Gauge matches the RTL's muxed combinational result.
            check_gauge_matches_rtl_nz: assert property (
                @(posedge clk) disable iff (1'b0)
                gauge == ((enable && !enforce) ?
                          ({{PAD_W{1'b0}}, 1'b0, value[LOGWORD-1:0]} + 1'b1) :
                          {{PAD_W{1'b0}}, 1'b0, value[LOGWORD-1:0]})
            );

            // Enforce selects the non-incremented value path.
            check_enforce_selects_base_nz: assert property (
                @(posedge clk) disable iff (1'b0)
                enforce |-> (gauge == {{PAD_W{1'b0}}, 1'b0, value[LOGWORD-1:0]})
            );

            // Disable selects the non-incremented value path.
            check_disable_selects_base_nz: assert property (
                @(posedge clk) disable iff (1'b0)
                (!enable) |-> (gauge == {{PAD_W{1'b0}}, 1'b0, value[LOGWORD-1:0]})
            );

            // Enable without enforce selects the incremented value path.
            check_enable_selects_increment_nz: assert property (
                @(posedge clk) disable iff (1'b0)
                (enable && !enforce) |-> (gauge == ({{PAD_W{1'b0}}, 1'b0, value[LOGWORD-1:0]} + 1'b1))
            );

            // On the base path, the low bits mirror value.
            check_base_path_low_bits_nz: assert property (
                @(posedge clk) disable iff (1'b0)
                ((!enable) || enforce) |-> (gauge[LOGWORD-1:0] == value[LOGWORD-1:0])
            );

            // On the base path, bit LOGWORD is forced low.
            check_base_path_inserted_zero_nz: assert property (
                @(posedge clk) disable iff (1'b0)
                ((!enable) || enforce) |-> (gauge[LOGWORD] == 1'b0)
            );

            // Incrementing an all-ones value creates a carry into bit LOGWORD.
            check_increment_carry_nz: assert property (
                @(posedge clk) disable iff (1'b0)
                (enable && !enforce && (&value[LOGWORD-1:0])) |->
                ((gauge[LOGWORD] == 1'b1) && (gauge[LOGWORD-1:0] == {LOGWORD{1'b0}}))
            );

            // Incrementing any other value does not set bit LOGWORD.
            check_increment_no_carry_nz: assert property (
                @(posedge clk) disable iff (1'b0)
                (enable && !enforce && !(|(~value[LOGWORD-1:0]))) && !(&value[LOGWORD-1:0]) |->
                (gauge[LOGWORD] == 1'b0)
            );

            if (WORD > (LOGWORD + 1)) begin : gen_upper_bits
                // Bits above LOGWORD remain zero.
                check_upper_bits_zero_nz: assert property (
                    @(posedge clk) disable iff (1'b0)
                    gauge[WORD-1:LOGWORD+1] == {(WORD-(LOGWORD+1)){1'b0}}
                );
            end

        end else begin : gen_logword_eq_0

            // With LOGWORD==0, gauge is high only when enable is high and enforce is low.
            check_gauge_matches_rtl_z0: assert property (
                @(posedge clk) disable iff (1'b0)
                gauge == (enable && !enforce)
            );

            // Enforce clears the one-bit output.
            check_enforce_clears_gauge_z0: assert property (
                @(posedge clk) disable iff (1'b0)
                enforce |-> (gauge == 1'b0)
            );

            // Disable clears the one-bit output.
            check_disable_clears_gauge_z0: assert property (
                @(posedge clk) disable iff (1'b0)
                (!enable) |-> (gauge == 1'b0)
            );

            // Enable without enforce sets the one-bit output.
            check_enable_sets_gauge_z0: assert property (
                @(posedge clk) disable iff (1'b0)
                (enable && !enforce) |-> (gauge == 1'b1)
            );

        end
    endgenerate

endmodule

rtl:
module address_operation (
    input   [8:0]   address_a,
    input   [8:0]   address_b,
    input   clock,
    output  [3:0]   q_a,
    output  [3:0]   q_b
);

    reg     [3:0]   q_a;
    reg     [3:0]   q_b;

    always @(posedge clock) begin
        if (address_a[8] == 1) begin
            q_a = address_a[3:0] + 1;
        end else begin
            q_a = address_a[3:0] + 2;
        end

        if (address_b[8] == 1) begin
            q_b = address_b[3:0] + 1;
        end else begin
            q_b = address_b[3:0] + 2;
        end
    end

endmodule

sva:
module address_operation_assertions (
    input logic [8:0] address_a,
    input logic [8:0] address_b,
    input logic       clock,
    input logic [3:0] q_a,
    input logic [3:0] q_b
);

    // q_a reflects the prior-cycle address_a computation.
    check_q_a_function: assert property (
        @(posedge clock)
        1'b1 |=> (q_a == ($past(address_a[8]) ? ($past(address_a[3:0]) + 4'd1)
                                              : ($past(address_a[3:0]) + 4'd2)))
    );

    // q_b reflects the prior-cycle address_b computation.
    check_q_b_function: assert property (
        @(posedge clock)
        1'b1 |=> (q_b == ($past(address_b[8]) ? ($past(address_b[3:0]) + 4'd1)
                                              : ($past(address_b[3:0]) + 4'd2)))
    );

    // q_a stays unchanged when its controlling address bits stay unchanged.
    check_q_a_stable_when_relevant_bits_stable: assert property (
        @(posedge clock)
        ((address_a[8] == $past(address_a[8])) &&
         (address_a[3:0] == $past(address_a[3:0])))
        |=> (q_a == $past(q_a))
    );

    // q_b stays unchanged when its controlling address bits stay unchanged.
    check_q_b_stable_when_relevant_bits_stable: assert property (
        @(posedge clock)
        ((address_b[8] == $past(address_b[8])) &&
         (address_b[3:0] == $past(address_b[3:0])))
        |=> (q_b == $past(q_b))
    );

    // Matching relevant bits on both inputs produce matching outputs.
    check_matching_inputs_produce_matching_outputs: assert property (
        @(posedge clock)
        ((address_a[8] == address_b[8]) &&
         (address_a[3:0] == address_b[3:0]))
        |=> (q_a == q_b)
    );

endmodule

module counter_sva (
    input logic       clk,
    input logic       rst_n,
    input logic       en,
    input logic [3:0] out
);

    // Active-low reset forces the counter output to zero.
    reset_clears_out: assert property (
        @(posedge clk) !rst_n |-> (out == 4'b0000)
    );

    // The first sampled cycle after reset release still shows zero.
    release_from_reset_zero: assert property (
        @(posedge clk) disable iff (!rst_n || $initstate)
        $past(!rst_n) |-> (out == 4'b0000)
    );

    // When disabled, the counter holds unless async reset cleared it.
    hold_when_disabled: assert property (
        @(posedge clk) disable iff (!rst_n)
        !en |=> ((out == $past(out)) || (out == 4'b0000))
    );

    // When enabled, the counter increments unless async reset cleared it.
    increment_when_enabled: assert property (
        @(posedge clk) disable iff (!rst_n)
        en |=> ((out == ($past(out) + 4'd1)) || (out == 4'b0000))
    );

    // Enabling at 4'hF wraps the 4-bit counter to zero.
    wrap_from_max: assert property (
        @(posedge clk) disable iff (!rst_n)
        en && (out == 4'hF) |=> (out == 4'h0)
    );

endmodule

rtl:
module binary_counter(clk, reset, count);
  input clk, reset;
  output reg [3:0] count;

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      count <= 4'b0;
    end else if (count == 4'b1111) begin
      count <= 4'b0;
    end else begin
      count <= count + 1;
    end
  end
endmodule

sva:
module binary_counter_sva (
    input logic       clk,
    input logic       reset,
    input logic [3:0] count
);

    // A sampled reset forces the counter to be zero by the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'b0000)
    );

    // A terminal count wraps back to zero on the next clock.
    check_wrap_from_max_count: assert property (
        @(posedge clk) disable iff (reset)
        (count == 4'b1111) |=> (count == 4'b0000)
    );

    // A non-terminal count advances by one unless an asynchronous reset drives it to zero.
    check_increment_from_nonmax_or_async_reset: assert property (
        @(posedge clk) disable iff (reset)
        (count != 4'b1111) |=> ((count == ($past(count) + 4'b0001)) || (count == 4'b0000))
    );

endmodule

rtl:
module ADC_INTERFACE(
    input clk,
    input reset_n,
    input [11:0] adc_data,
    output reg valid,
    output reg [15:0] data_out
);

always @(posedge clk, negedge reset_n) begin
    if (~reset_n) begin
        valid <= 0;
        data_out <= 0;
    end else begin
        if (adc_data != 0) begin
            valid <= 1;
            data_out <= {4'b0, adc_data};
        end
    end
end

endmodule

sva:
module ADC_INTERFACE_sva (
    input logic clk,
    input logic reset_n,
    input logic [11:0] adc_data,
    input logic valid,
    input logic [15:0] data_out
);

    // Active-low reset clears both outputs.
    check_reset_clears_outputs: assert property (
        @(posedge clk) !reset_n |-> (valid == 1'b0 && data_out == 16'h0000)
    );

    // A nonzero ADC sample sets valid on the next clock sample.
    check_nonzero_input_sets_valid: assert property (
        @(posedge clk) disable iff (!reset_n)
        (adc_data != 12'h000) |=> (valid == 1'b1)
    );

    // A nonzero ADC sample is zero-extended into data_out.
    check_nonzero_input_updates_data_out: assert property (
        @(posedge clk) disable iff (!reset_n)
        (adc_data != 12'h000) |=> (data_out == {4'b0000, $past(adc_data)})
    );

    // A zero ADC sample leaves valid unchanged.
    check_zero_input_holds_valid: assert property (
        @(posedge clk) disable iff (!reset_n)
        (adc_data == 12'h000) |=> (valid == $past(valid))
    );

    // A zero ADC sample leaves data_out unchanged.
    check_zero_input_holds_data_out: assert property (
        @(posedge clk) disable iff (!reset_n)
        (adc_data == 12'h000) |=> (data_out == $past(data_out))
    );

    // Once valid is high, it stays high until reset.
    check_valid_is_sticky: assert property (
        @(posedge clk) disable iff (!reset_n)
        valid |=> valid
    );

endmodule

