sva:
module db_lut_tc_sva (
    input logic       clk,
    input logic [5:0] qp_i,
    input logic       mb_type_i,
    input logic [4:0] tc_o
);

    logic [5:0] qp_w;
    assign qp_w = qp_i + {mb_type_i, 1'b0};

    function automatic [4:0] expected_tc;
        input [5:0] qpw;
        begin
            case (qpw)
                6'd18, 6'd19, 6'd20, 6'd21, 6'd22, 6'd23, 6'd24, 6'd25, 6'd26: expected_tc = 5'd1;
                6'd27, 6'd28, 6'd29, 6'd30: expected_tc = 5'd2;
                6'd31, 6'd32, 6'd33, 6'd34: expected_tc = 5'd3;
                6'd35, 6'd36, 6'd37: expected_tc = 5'd4;
                6'd38, 6'd39: expected_tc = 5'd5;
                6'd40, 6'd41: expected_tc = 5'd6;
                6'd42: expected_tc = 5'd7;
                6'd43: expected_tc = 5'd8;
                6'd44: expected_tc = 5'd9;
                6'd45: expected_tc = 5'd10;
                6'd46: expected_tc = 5'd11;
                6'd47: expected_tc = 5'd13;
                6'd48: expected_tc = 5'd14;
                6'd49: expected_tc = 5'd16;
                6'd50: expected_tc = 5'd18;
                6'd51: expected_tc = 5'd20;
                6'd52: expected_tc = 5'd22;
                6'd53: expected_tc = 5'd24;
                default: expected_tc = 5'd0;
            endcase
        end
    endfunction

    // tc_o must equal the LUT value selected by qp_i plus the mb_type offset.
    check_tc_lookup_exact: assert property (
        @(posedge clk) (tc_o == expected_tc(qp_w))
    );

    // Lookup indices below 18 or above 53 must select the default zero output.
    check_tc_default_zero_outside_table: assert property (
        @(posedge clk) (((qp_w < 6'd18) || (qp_w > 6'd53)) |-> (tc_o == 5'd0))
    );

    // Lookup indices within the programmed table must produce a nonzero output.
    check_tc_nonzero_inside_table: assert property (
        @(posedge clk) (((qp_w >= 6'd18) && (qp_w <= 6'd53)) |-> (tc_o != 5'd0))
    );

endmodule

rtl:
module gray_code(input clk, input reset, input [3:0] bin_in, output [3:0] gray_out);

    reg [3:0] gray_out_reg;

    always @(posedge clk) begin
        if (reset)
            gray_out_reg <= 4'b0000;
        else begin
            gray_out_reg[3] <= bin_in[3];
            gray_out_reg[2] <= bin_in[3] ^ bin_in[2];
            gray_out_reg[1] <= bin_in[2] ^ bin_in[1];
            gray_out_reg[0] <= bin_in[1] ^ bin_in[0];
        end
    end

    assign gray_out = gray_out_reg;

endmodule

sva:
module gray_code_sva (
    input logic       clk,
    input logic       reset,
    input logic [3:0] bin_in,
    input logic [3:0] gray_out
);

    // Reset clears the registered output on the next clock.
    check_reset_clears_output: assert property (
        @(posedge clk) reset |=> (gray_out == 4'b0000)
    );

    // Gray output matches the previous cycle's binary input encoding.
    check_gray_vector_encoding: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> (gray_out == {
            $past(bin_in[3]),
            ($past(bin_in[3]) ^ $past(bin_in[2])),
            ($past(bin_in[2]) ^ $past(bin_in[1])),
            ($past(bin_in[1]) ^ $past(bin_in[0]))
        })
    );

    // gray_out[3] captures the previous cycle's bin_in[3].
    check_gray_bit3_encoding: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> (gray_out[3] == $past(bin_in[3]))
    );

    // gray_out[2] is the previous cycle's bin_in[3] XOR bin_in[2].
    check_gray_bit2_encoding: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> (gray_out[2] == ($past(bin_in[3]) ^ $past(bin_in[2])))
    );

    // gray_out[1] is the previous cycle's bin_in[2] XOR bin_in[1].
    check_gray_bit1_encoding: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> (gray_out[1] == ($past(bin_in[2]) ^ $past(bin_in[1])))
    );

    // gray_out[0] is the previous cycle's bin_in[1] XOR bin_in[0].
    check_gray_bit0_encoding: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> (gray_out[0] == ($past(bin_in[1]) ^ $past(bin_in[0])))
    );

endmodule

rtl:
module eightbit_alu(a, b, sel, f, ovf, zero);
    input signed [7:0] a, b;
    input [2:0] sel;
    output reg signed [7:0] f;
    output reg ovf;
    output reg zero;

    always@(a, b, sel) begin
        zero = 0;
        ovf = 0;
        f = 0;

        case(sel)
            3'b000: begin // f = a + b
                f = a + b;
                ovf = ~(a[7] ^ b[7]) & (a[7] ^ f[7]);
            end
            3'b001: begin // f = ~b
                f = ~b;
            end
            3'b010: begin // f = a & b
                f = a & b;
            end
            3'b011: begin // f = a | b
                f = a | b;
            end
            3'b100: begin // f = a >>> 1
                f = a >>> 1;
            end
            3'b101: begin // f = a <<< 1
                f = a <<< 1;
            end
            3'b110: begin // zero = a == b
                zero = a == b;
            end
            3'b111: begin // zero = a != b
                zero = a != b;
            end

        endcase
    end
endmodule

sva:
module eightbit_alu_sva (
    input logic clk,
    input logic signed [7:0] a,
    input logic signed [7:0] b,
    input logic [2:0] sel,
    input logic signed [7:0] f,
    input logic ovf,
    input logic zero
);

    // RTL is purely combinational with no reset; clk is a sampling clock.

    // Add mode drives the sum, signed overflow, and zero low.
    check_add_mode_outputs: assert property (
        @(posedge clk)
        (sel == 3'b000) |-> ((f == (a + b)) &&
                             (ovf == (~(a[7] ^ b[7]) & (a[7] ^ f[7]))) &&
                             (zero == 1'b0))
    );

    // Invert mode drives bitwise not of b and keeps flags low.
    check_invert_mode_outputs: assert property (
        @(posedge clk)
        (sel == 3'b001) |-> ((f == (~b)) &&
                             (ovf == 1'b0) &&
                             (zero == 1'b0))
    );

    // AND mode drives a & b and keeps flags low.
    check_and_mode_outputs: assert property (
        @(posedge clk)
        (sel == 3'b010) |-> ((f == (a & b)) &&
                             (ovf == 1'b0) &&
                             (zero == 1'b0))
    );

    // OR mode drives a | b and keeps flags low.
    check_or_mode_outputs: assert property (
        @(posedge clk)
        (sel == 3'b011) |-> ((f == (a | b)) &&
                             (ovf == 1'b0) &&
                             (zero == 1'b0))
    );

    // Arithmetic right shift mode drives a >>> 1 and keeps flags low.
    check_arith_right_shift_mode_outputs: assert property (
        @(posedge clk)
        (sel == 3'b100) |-> ((f == (a >>> 1)) &&
                             (ovf == 1'b0) &&
                             (zero == 1'b0))
    );

    // Arithmetic left shift mode drives a <<< 1 and keeps flags low.
    check_arith_left_shift_mode_outputs: assert property (
        @(posedge clk)
        (sel == 3'b101) |-> ((f == (a <<< 1)) &&
                             (ovf == 1'b0) &&
                             (zero == 1'b0))
    );

    // Equal-compare mode drives zero from a == b and clears f and ovf.
    check_equal_compare_mode_outputs: assert property (
        @(posedge clk)
        (sel == 3'b110) |-> ((f == 8'sd0) &&
                             (ovf == 1'b0) &&
                             (zero == (a == b)))
    );

    // Not-equal-compare mode drives zero from a != b and clears f and ovf.
    check_not_equal_compare_mode_outputs: assert property (
        @(posedge clk)
        (sel == 3'b111) |-> ((f == 8'sd0) &&
                             (ovf == 1'b0) &&
                             (zero == (a != b)))
    );

    // Overflow can only be asserted in add mode.
    check_overflow_only_in_add_mode: assert property (
        @(posedge clk)
        ovf |-> (sel == 3'b000)
    );

    // A high zero flag must come from the active compare mode result.
    check_zero_high_matches_compare_mode: assert property (
        @(posedge clk)
        zero |-> (((sel == 3'b110) && (a == b)) ||
                  ((sel == 3'b111) && (a != b)))
    );

endmodule

rtl:
module concat_split_vectors (
  input [7:0] a,
  input [7:0] b,
  output reg [3:0] w,
  output reg [3:0] x,
  output reg [3:0] y,
  output reg [3:0] z
);

  reg [15:0] concat;

  always @ (a or b) begin
    concat = {a, b};
  end

  assign {w, x, y, z} = concat + 4'b11;

endmodule

sva:
module concat_split_vectors_sva (
    input logic [7:0] a,
    input logic [7:0] b,
    input logic [3:0] w,
    input logic [3:0] x,
    input logic [3:0] y,
    input logic [3:0] z
);

    // The full output vector is the concatenated inputs plus 3.
    check_full_vector_sum: assert property (
        @($global_clock) {w, x, y, z} == ({a, b} + 16'h0003)
    );

    // The low output byte is b plus 3.
    check_low_byte_sum: assert property (
        @($global_clock) {y, z} == (b + 8'h03)
    );

    // The high output byte is unchanged when b plus 3 does not overflow.
    check_high_byte_no_carry: assert property (
        @($global_clock) (b < 8'hFD) |-> ({w, x} == a)
    );

    // The high output byte increments when b plus 3 overflows.
    check_high_byte_with_carry: assert property (
        @($global_clock) (b >= 8'hFD) |-> ({w, x} == (a + 8'h01))
    );

    // The lowest nibble is the low nibble of b plus 3.
    check_z_nibble_sum: assert property (
        @($global_clock) z == (b[3:0] + 4'h3)
    );

    // The next nibble includes carry from the low nibble addition.
    check_y_nibble_sum: assert property (
        @($global_clock) y == (b[7:4] + ((b[3:0] >= 4'hD) ? 4'h1 : 4'h0))
    );

    // The x nibble matches a[3:0] when there is no carry from b.
    check_x_nibble_no_carry: assert property (
        @($global_clock) (b < 8'hFD) |-> (x == a[3:0])
    );

    // The x nibble increments a[3:0] when b generates a byte carry.
    check_x_nibble_with_carry: assert property (
        @($global_clock) (b >= 8'hFD) |-> (x == (a[3:0] + 4'h1))
    );

    // The w nibble stays equal to a[7:4] unless carry propagates through x.
    check_w_nibble_no_upper_carry: assert property (
        @($global_clock) ((b < 8'hFD) || (a[3:0] != 4'hF)) |-> (w == a[7:4])
    );

    // The w nibble increments when carry from b propagates through a[3:0].
    check_w_nibble_with_upper_carry: assert property (
        @($global_clock) ((b >= 8'hFD) && (a[3:0] == 4'hF)) |-> (w == (a[7:4] + 4'h1))
    );

endmodule

rtl:
module alu_16(
    input clk,
    input [15:0] a,
    input [15:0] b,
    input [7:0] ctrl,
    output reg [15:0] out,
    output reg n,
    output reg z,
    output reg c,
    output reg v
);

wire [15:0] add_out;
wire [15:0] sub_out;
wire [15:0] slt_out;
wire [15:0] sll_out;
wire [15:0] srl_out;
wire [15:0] sra_out;
wire [15:0] and_out;
wire [15:0] or_out;

// AND operation
assign and_out = a & b;
// OR operation
assign or_out = a | b;
// ADD operation
assign add_out = a + b;
// SUB operation
assign sub_out = a - b;
// SLT operation
assign slt_out = (a < b) ? 16'h0001 : 16'h0000;
// SLL operation
assign sll_out = a << b[3:0];
// SRL operation
assign srl_out = a >> b[3:0];
// SRA operation
assign sra_out = ($signed(a) >>> b[3:0]);

// Output selection based on control input
always @* begin
    case(ctrl)
        8'b000_0000: out = and_out;
        8'b000_0001: out = or_out;
        8'b000_0010: out = add_out;
        8'b000_0011: out = sub_out;
        8'b000_0100: out = slt_out;
        8'b000_0101: out = sll_out;
        8'b000_0110: out = srl_out;
        8'b000_0111: out = sra_out;
        default: out = 16'h0000;
    endcase
end

// Status flag generation
always @* begin
    n = (out[15] == 1) ? 1 : 0;
    z = (out == 16'h0000) ? 1 : 0;
    c = (out[15] == 1) ? 1 : 0;
    v = (((a[15] == 0) && (b[15] == 0) && (out[15] == 1)) || ((a[15] == 1) && (b[15] == 1) && (out[15] == 0))) ? 1 : 0;
end

endmodule

sva:
module alu_16_sva (
    input logic        clk,
    input logic [15:0] a,
    input logic [15:0] b,
    input logic [7:0]  ctrl,
    input logic [15:0] out,
    input logic        n,
    input logic        z,
    input logic        c,
    input logic        v
);

    // AND select drives the bitwise AND result.
    check_and_select: assert property (
        @(posedge clk) (ctrl == 8'h00) |-> (out == (a & b))
    );

    // OR select drives the bitwise OR result.
    check_or_select: assert property (
        @(posedge clk) (ctrl == 8'h01) |-> (out == (a | b))
    );

    // ADD select drives the sum result.
    check_add_select: assert property (
        @(posedge clk) (ctrl == 8'h02) |-> (out == (a + b))
    );

    // SUB select drives the difference result.
    check_sub_select: assert property (
        @(posedge clk) (ctrl == 8'h03) |-> (out == (a - b))
    );

    // SLT select drives 1 when a is less than b, else 0.
    check_slt_select: assert property (
        @(posedge clk) (ctrl == 8'h04) |-> (out == ((a < b) ? 16'h0001 : 16'h0000))
    );

    // SLL select shifts a left by b[3:0].
    check_sll_select: assert property (
        @(posedge clk) (ctrl == 8'h05) |-> (out == (a << b[3:0]))
    );

    // SRL select shifts a right logically by b[3:0].
    check_srl_select: assert property (
        @(posedge clk) (ctrl == 8'h06) |-> (out == (a >> b[3:0]))
    );

    // SRA select shifts a right arithmetically by b[3:0].
    check_sra_select: assert property (
        @(posedge clk) (ctrl == 8'h07) |-> (out == ($signed(a) >>> b[3:0]))
    );

    // Unrecognized control values drive zero on out.
    check_default_zero: assert property (
        @(posedge clk)
        ((ctrl != 8'h00) && (ctrl != 8'h01) && (ctrl != 8'h02) && (ctrl != 8'h03) &&
         (ctrl != 8'h04) && (ctrl != 8'h05) && (ctrl != 8'h06) && (ctrl != 8'h07))
        |-> (out == 16'h0000)
    );

    // n reflects the sign bit of out.
    check_negative_flag: assert property (
        @(posedge clk) (n == out[15])
    );

    // z is asserted only when out is zero.
    check_zero_flag: assert property (
        @(posedge clk) (z == (out == 16'h0000))
    );

    // c matches the sign bit of out in this RTL.
    check_carry_flag: assert property (
        @(posedge clk) (c == out[15])
    );

    // v follows the implemented sign-based overflow expression.
    check_overflow_flag: assert property (
        @(posedge clk)
        (v == ((((a[15] == 1'b0) && (b[15] == 1'b0) && (out[15] == 1'b1)) ||
                ((a[15] == 1'b1) && (b[15] == 1'b1) && (out[15] == 1'b0))) ? 1'b1 : 1'b0))
    );

endmodule

