rtl:
module adder4bit (A, B, Ci, S, Co);
  input [3:0] A, B;
  input Ci;
  output [3:0] S;
  output Co;

  wire [3:0] c;
  wire [3:0] x;
  wire [3:0] y;

  // Full adder for the least significant bit
  full_adder FA0 (.a(A[0]), .b(B[0]), .ci(Ci), .s(S[0]), .co(c[0]));

  // Full adders for the remaining bits
  genvar i;
  generate
    for (i = 1; i < 4; i = i + 1) begin
      full_adder FA (.a(A[i]), .b(B[i]), .ci(c[i-1]), .s(S[i]), .co(c[i]));
    end
  endgenerate

  // Invert carry out to get Co
  assign Co = ~c[3];

  // Invert B to get 2's complement
  assign y = ~B;
  assign y[0] = y[0] ^ 1'b1;

  // Add inverted B to A
  full_adder FA1 (.a(A[0]), .b(y[0]), .ci(Ci), .s(x[0]), .co());
  generate
    for (i = 1; i < 4; i = i + 1) begin
      full_adder FA (.a(A[i]), .b(y[i]), .ci(c[i-1]), .s(x[i]), .co());
    end
  endgenerate
endmodule
module full_adder (a, b, ci, s, co);
  input a, b, ci;
  output s, co;

  wire x1, x2, x3;

  // First XOR gate
  assign x1 = a ^ b;

  // Second XOR gate
  assign s = x1 ^ ci;

  // AND gate
  assign x2 = a & b;

  // Third XOR gate
  assign x3 = x1 & ci;

  // OR gate
  assign co = x2 | x3;
endmodule

sva:
module adder4bit_sva (
    input logic       clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic       Ci,
    input logic [3:0] S,
    input logic       Co
);

    function automatic logic fa_co (
        input logic a,
        input logic b,
        input logic ci
    );
        fa_co = (a & b) | ((a ^ b) & ci);
    endfunction

    // Bit 0 sum matches the least-significant full adder.
    check_bit0_sum: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0] ^ Ci)
    );

    // Bit 1 sum uses the carry from bit 0.
    check_bit1_sum: assert property (
        @(posedge clk) S[1] == (A[1] ^ B[1] ^ fa_co(A[0], B[0], Ci))
    );

    // Bit 2 sum uses the ripple carry from bit 1.
    check_bit2_sum: assert property (
        @(posedge clk) S[2] == (A[2] ^ B[2] ^ fa_co(A[1], B[1], fa_co(A[0], B[0], Ci)))
    );

    // Bit 3 sum uses the ripple carry from bit 2.
    check_bit3_sum: assert property (
        @(posedge clk) S[3] == (A[3] ^ B[3] ^ fa_co(A[2], B[2], fa_co(A[1], B[1], fa_co(A[0], B[0], Ci))))
    );

    // Co is the inverted carry out of the most-significant full adder.
    check_inverted_carry_out: assert property (
        @(posedge clk) Co == ~fa_co(A[3], B[3], fa_co(A[2], B[2], fa_co(A[1], B[1], fa_co(A[0], B[0], Ci))))
    );

    // Outputs match a 4-bit add with inverted carry out.
    check_full_add_result: assert property (
        @(posedge clk) {~Co, S} == ({1'b0, A} + {1'b0, B} + {4'b0, Ci})
    );

endmodule

