module chatgpt_generate_JC_counter(
  input                clk,
  input                rst_n,
  output reg  [3:0]    Q
);

  wire [5:0] temp;

  assign temp = {Q[3], Q[2], Q[1], Q[0], Q[3], Q[2]};

  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      Q <= 4'b0000;
    end else begin
      Q <= {temp[4], temp[5], temp[3], temp[2]};
    end
  end

endmodule

sva:
module chatgpt_generate_JC_counter_sva (
    input logic       clk,
    input logic       rst_n,
    input logic [3:0] Q
);

    // Reset drives Q to zero.
    check_reset_clears_q: assert property (
        @(posedge clk) !rst_n |-> (Q == 4'b0000)
    );

    // A sampled reset keeps the next clocked state at zero.
    check_reset_keeps_zero_next_cycle: assert property (
        @(posedge clk) !rst_n |=> (Q == 4'b0000)
    );

    // Each active clock follows the RTL bit rearrangement.
    check_next_state_rearrangement: assert property (
        @(posedge clk) disable iff (!rst_n)
        1'b1 |=> (Q == {$past(Q[2]), $past(Q[3]), $past(Q[1]), $past(Q[0])})
    );

    // The upper two bits swap on each active clock.
    check_upper_bits_swap: assert property (
        @(posedge clk) disable iff (!rst_n)
        1'b1 |=> (Q[3:2] == {$past(Q[2]), $past(Q[3])})
    );

    // The lower two bits hold their values on each active clock.
    check_lower_bits_hold: assert property (
        @(posedge clk) disable iff (!rst_n)
        1'b1 |=> (Q[1:0] == $past(Q[1:0]))
    );

    // Two active clocks return Q to its earlier value.
    check_two_cycle_repeat: assert property (
        @(posedge clk) disable iff (!rst_n)
        1'b1 |=> ##1 (Q == $past(Q, 2))
    );

endmodule

rtl:
module add_sub (
    input [3:0] a,
    input [3:0] b,
    input enable,
    output [3:0] sum,
    output [3:0] diff
);

    wire [3:0] a_inv;
    wire [3:0] b_inv;
    wire [3:0] borrow;

    assign a_inv = ~a;
    assign b_inv = ~b;

    assign sum = a + b;

    assign borrow[0] = a[0] & b_inv[0];
    assign borrow[1] = (a[1] & b_inv[1]) | (a[0] & b_inv[0]);
    assign borrow[2] = (a[2] & b_inv[2]) | (a[1] & b_inv[1]) | (a[0] & b_inv[0]);
    assign borrow[3] = (a[3] & b_inv[3]) | (a[2] & b_inv[2]) | (a[1] & b_inv[1]) | (a[0] & b_inv[0]);

    assign diff[0] = enable ? (a[0] ^ b[0] ^ borrow[0]) : 1'bx;
    assign diff[1] = enable ? (a[1] ^ b[1] ^ borrow[1]) : 1'bx;
    assign diff[2] = enable ? (a[2] ^ b[2] ^ borrow[2]) : 1'bx;
    assign diff[3] = enable ? (a[3] ^ b[3] ^ borrow[3]) : 1'bx;

endmodule

module top_module (
    input [3:0] a,
    input [3:0] b,
    input enable,
    output [3:0] out
);

    wire [3:0] sum;
    wire [3:0] diff;

    add_sub add_sub_inst (
        .a(a),
        .b(b),
        .enable(enable),
        .sum(sum),
        .diff(diff)
    );

    assign out = enable ? (enable & sum) | (~enable & diff) : 1'bx;

endmodule

sva:
module top_module_sva (
    input logic [3:0] a,
    input logic [3:0] b,
    input logic enable,
    input logic [3:0] sum,
    input logic [3:0] diff,
    input logic [3:0] out
);

    // No explicit RTL clock or reset; sample this combinational logic on $global_clock.

    // sum is always the 4-bit addition of a and b.
    check_sum_matches_addition: assert property (
        @($global_clock) (sum == (a + b))
    );

    // diff[0] follows the implemented XOR-with-borrow equation when enabled.
    check_diff_bit0_matches_formula: assert property (
        @($global_clock) enable |-> (diff[0] == (a[0] ^ b[0] ^ (a[0] & ~b[0])))
    );

    // diff[1] uses the cumulative borrow term from bits 1:0 when enabled.
    check_diff_bit1_matches_formula: assert property (
        @($global_clock) enable |-> (
            diff[1] == (a[1] ^ b[1] ^ ((a[1] & ~b[1]) | (a[0] & ~b[0])))
        )
    );

    // diff[2] uses the cumulative borrow term from bits 2:0 when enabled.
    check_diff_bit2_matches_formula: assert property (
        @($global_clock) enable |-> (
            diff[2] == (a[2] ^ b[2] ^ ((a[2] & ~b[2]) | (a[1] & ~b[1]) | (a[0] & ~b[0])))
        )
    );

    // diff[3] uses the cumulative borrow term from bits 3:0 when enabled.
    check_diff_bit3_matches_formula: assert property (
        @($global_clock) enable |-> (
            diff[3] == (a[3] ^ b[3] ^ ((a[3] & ~b[3]) | (a[2] & ~b[2]) | (a[1] & ~b[1]) | (a[0] & ~b[0])))
        )
    );

    // The top-level output selects sum when enable is high.
    check_out_selects_sum_when_enabled: assert property (
        @($global_clock) enable |-> (out == sum)
    );

    // The top-level output matches the 4-bit addition result when enabled.
    check_out_matches_addition_when_enabled: assert property (
        @($global_clock) enable |-> (out == (a + b))
    );

    // Equal operands produce a zero diff when enabled.
    check_diff_zero_when_inputs_equal: assert property (
        @($global_clock) (enable && (a == b)) |-> (diff == 4'h0)
    );

    // A zero a operand makes diff equal to b when enabled.
    check_diff_matches_b_when_a_is_zero: assert property (
        @($global_clock) (enable && (a == 4'h0)) |-> (diff == b)
    );

    // A zero b operand makes the enabled output equal to a.
    check_out_matches_a_when_b_is_zero: assert property (
        @($global_clock) (enable && (b == 4'h0)) |-> (out == a)
    );

