    xor_gate x1(.a(a), .b(b), .z(w1));
    xor_gate x2(.a(w1), .b(cin), .z(sum));

    and_gate a1(.a1(w1), .a2(cin), .zn(w2));
    and_gate a2(.a1(a), .a2(b), .zn(w3));

    or_gate o1(.o1(w2), .o2(w3), .zn(cout));

endmodule

