sva:
module adder_sva (
    input logic       clk,
    input logic [3:0] a,
    input logic [3:0] b,
    input logic       cin,
    input logic [3:0] sum,
    input logic       cout
);

    // Combined output matches 4-bit addition with carry-in.
    check_arithmetic_result: assert property (
        @(posedge clk)
        {cout, sum} == ({1'b0, a} + {1'b0, b} + {4'b0000, cin})
    );

    // Sum bit 0 follows the first full-adder XOR equation.
    check_sum_bit0: assert property (
        @(posedge clk)
        sum[0] == (a[0] ^ b[0] ^ cin)
    );

    // Sum bit 1 uses the carry from bit 0.
    check_sum_bit1: assert property (
        @(posedge clk)
        sum[1] == (
            a[1] ^ b[1] ^
            ((a[0] & b[0]) | (cin & (a[0] ^ b[0])))
        )
    );

    // Sum bit 2 uses the carry from bit 1.
    check_sum_bit2: assert property (
        @(posedge clk)
        sum[2] == (
            a[2] ^ b[2] ^
            (
                (a[1] & b[1]) |
                (
                    ((a[0] & b[0]) | (cin & (a[0] ^ b[0]))) &
                    (a[1] ^ b[1])
                )
            )
        )
    );

    // Sum bit 3 uses the carry from bit 2.
    check_sum_bit3: assert property (
        @(posedge clk)
        sum[3] == (
            a[3] ^ b[3] ^
            (
                (a[2] & b[2]) |
                (
                    (
                        (a[1] & b[1]) |
                        (
                            ((a[0] & b[0]) | (cin & (a[0] ^ b[0]))) &
                            (a[1] ^ b[1])
                        )
                    ) &
                    (a[2] ^ b[2])
                )
            )
        )
    );

    // Carry-out follows the final full-adder carry equation.
    check_cout_equation: assert property (
        @(posedge clk)
        cout == (
            (a[3] & b[3]) |
            (
                (
                    (a[2] & b[2]) |
                    (
                        (
                            (a[1] & b[1]) |
                            (
                                ((a[0] & b[0]) | (cin & (a[0] ^ b[0]))) &
                                (a[1] ^ b[1])
                            )
                        ) &
                        (a[2] ^ b[2])
                    )
                ) &
                (a[3] ^ b[3])
            )
        )
    );

    // Stable inputs must produce stable outputs.
    check_stable_inputs_stable_outputs: assert property (
        @(posedge clk)
        $stable({a, b, cin}) |-> $stable({sum, cout})
    );

    // Adding zero with no carry-in passes operand a through.
    check_b_zero_passthrough: assert property (
        @(posedge clk)
        (b == 4'b0000 && cin == 1'b0) |-> (sum == a && cout == 1'b0)
    );

    // Adding zero with no carry-in passes operand b through.
    check_a_zero_passthrough: assert property (
        @(posedge clk)
        (a == 4'b0000 && cin == 1'b0) |-> (sum == b && cout == 1'b0)
    );

endmodule

rtl:
module mux_2to1 (
    input A,
    input B,
    input S,
    output reg Y
);

always @(A, B, S) begin
    if (S == 0) begin
        Y <= A;
    end else if (S == 1) begin
        Y <= B;
    end else begin
        Y <= 0;
    end
end

endmodule

sva:
module mux_2to1_assertions (
    input logic A,
    input logic B,
    input logic S,
    input logic Y
);

    // The RTL has no clock or reset, so assertions use the formal global clock.

    // Output always matches the implemented mux function.
    check_mux_function: assert property (
        @($global_clock)
        Y === ((S === 1'b0) ? A : ((S === 1'b1) ? B : 1'b0))
    );

    // Select low routes input A to the output.
    check_select_low_routes_a: assert property (
        @($global_clock)
        (S === 1'b0) |-> (Y === A)
    );

    // Select high routes input B to the output.
    check_select_high_routes_b: assert property (
        @($global_clock)
        (S === 1'b1) |-> (Y === B)
    );

    // A non-binary select value drives the default zero output.
    check_invalid_select_drives_zero: assert property (
        @($global_clock)
        ((S !== 1'b0) && (S !== 1'b1)) |-> (Y === 1'b0)
    );

    // Changes on B do not affect Y when A is selected and stable.
    check_b_ignored_when_select_low: assert property (
        @($global_clock)
        ($stable(S) && (S === 1'b0) && $stable(A) && $changed(B)) |-> $stable(Y)
    );

    // Changes on A do not affect Y when B is selected and stable.
    check_a_ignored_when_select_high: assert property (
        @($global_clock)
        ($stable(S) && (S === 1'b1) && $stable(B) && $changed(A)) |-> $stable(Y)
    );

endmodule

rtl:
module four_input_one_output (
    input a,
    input b,
    input c,
    input d,
    output reg out
);

always @(*) begin
    if (a) begin
        out = 1;
    end else if (b) begin
        out = 1;
    end else if (c) begin
        out = 1;
    end else if (d) begin
        out = 1;
    end else begin
        out = 0;
    end
end

endmodule

sva:
module four_input_one_output_sva (
    input logic clk,
    input logic a,
    input logic b,
    input logic c,
    input logic d,
    input logic out
);

    // Input a HIGH drives the output HIGH.
    check_a_drives_out_high: assert property (
        @(posedge clk) (a == 1'b1) |-> (out == 1'b1)
    );

    // Input b HIGH drives the output HIGH.
    check_b_drives_out_high: assert property (
        @(posedge clk) (b == 1'b1) |-> (out == 1'b1)
    );

    // Input c HIGH drives the output HIGH.
    check_c_drives_out_high: assert property (
        @(posedge clk) (c == 1'b1) |-> (out == 1'b1)
    );

    // Input d HIGH drives the output HIGH.
    check_d_drives_out_high: assert property (
        @(posedge clk) (d == 1'b1) |-> (out == 1'b1)
    );

    // When all inputs are LOW, the output is LOW.
    check_all_inputs_low_drive_out_low: assert property (
        @(posedge clk)
        ((a == 1'b0) && (b == 1'b0) && (c == 1'b0) && (d == 1'b0)) |-> (out == 1'b0)
    );

    // Output equals the OR of the four inputs.
    check_out_matches_or_of_inputs: assert property (
        @(posedge clk) (out == (a || b || c || d))
