rtl:
module counter (
    input clk,
    input rst,
    output reg [3:0] out
);

always @(posedge clk) begin
    if (rst) begin
        out <= 4'b0;
    end else begin
        out <= out + 1;
    end
end

endmodule

sva:
module counter_sva (
    input logic       clk,
    input logic       rst,
    input logic [3:0] out
);

    // After a reset cycle, the counter is observed at zero.
    check_reset_release_clears_out: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        $past(rst) |-> (out == 4'h0)
    );

    // On consecutive non-reset cycles, values below 15 increment by one.
    check_counter_increments_below_max: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        !$past(rst) && ($past(out) != 4'hF) |-> (out == ($past(out) + 4'h1))
    );

    // On consecutive non-reset cycles, 15 wraps back to zero.
    check_counter_wraps_from_max: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        !$past(rst) && ($past(out) == 4'hF) |-> (out == 4'h0)
    );

    // One cycle after reset release, the counter advances to one.
    check_first_increment_after_reset: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        $past(rst) |=> (out == 4'h1)
    );

endmodule

rtl:
module parallel_load_shift (
    input [7:0] data_in,
    input [2:0] shift_amount,
    output [7:0] data_out,
    input clk
);

reg [7:0] reg1, reg2, reg3, reg4;
wire [7:0] shifted_reg1, shifted_reg2, shifted_reg3;

always @(posedge clk) begin
    reg1 <= data_in;
    reg2 <= reg1;
    reg3 <= reg2;
    reg4 <= reg3;
end

assign shifted_reg1 = reg1 >> shift_amount[2];
assign shifted_reg2 = reg2 >> shift_amount[1];
assign shifted_reg3 = reg3 >> shift_amount[0];
assign data_out = {shifted_reg3, shifted_reg2, shifted_reg1};

endmodule

sva:
module parallel_load_shift_sva (
    input logic        clk,
    input logic [7:0]  data_in,
    input logic [2:0]  shift_amount,
    input logic [7:0]  data_out,
    input logic [7:0]  reg1,
    input logic [7:0]  reg2,
    input logic [7:0]  reg3,
    input logic [7:0]  reg4,
    input logic [7:0]  shifted_reg1,
    input logic [7:0]  shifted_reg2,
    input logic [7:0]  shifted_reg3
);

    // Clock: clk; reset: none; pipeline regs plus combinational shifts.
    // reg1 captures data_in on the next clock.
    check_reg1_captures_data_in: assert property (
        @(posedge clk) 1'b1 |=> (reg1 == $past(data_in))
    );

    // reg2 captures reg1 on the next clock.
    check_reg2_captures_reg1: assert property (
        @(posedge clk) 1'b1 |=> (reg2 == $past(reg1))
    );

    // reg3 captures reg2 on the next clock.
    check_reg3_captures_reg2: assert property (
        @(posedge clk) 1'b1 |=> (reg3 == $past(reg2))
    );

    // reg4 captures reg3 on the next clock.
    check_reg4_captures_reg3: assert property (
        @(posedge clk) 1'b1 |=> (reg4 == $past(reg3))
    );

    // reg4 is a four-cycle delayed version of data_in.
    check_reg4_four_cycle_delay: assert property (
        @(posedge clk) 1'b1 |-> ##4 (reg4 == $past(data_in, 4))
    );

    // shifted_reg1 is reg1 shifted by shift_amount[2].
    check_shifted_reg1_definition: assert property (
        @(posedge clk) (shifted_reg1 == (reg1 >> shift_amount[2]))
    );

    // shifted_reg2 is reg2 shifted by shift_amount[1].
    check_shifted_reg2_definition: assert property (
        @(posedge clk) (shifted_reg2 == (reg2 >> shift_amount[1]))
    );

    // shifted_reg3 is reg3 shifted by shift_amount[0].
    check_shifted_reg3_definition: assert property (
        @(posedge clk) (shifted_reg3 == (reg3 >> shift_amount[0]))
    );

    // data_out equals shifted_reg1 after concatenation truncation.
    check_data_out_equals_shifted_reg1: assert property (
        @(posedge clk) (data_out == shifted_reg1)
    );

    // data_out reflects the prior data_in shifted by current shift_amount[2].
    check_data_out_matches_delayed_input_shift: assert property (
        @(posedge clk) 1'b1 |=> (data_out == ($past(data_in) >> shift_amount[2]))
    );

endmodule

rtl:
module comparator_mux (
    input [15:0] a,
    input [15:0] b,
    input [15:0] c,
    input sel,
    output [15:0] out,
    output equal
);

    wire [15:0] larger;
    assign larger = (a > b) ? a : b;

    assign out = (sel == 1'b0) ? larger : c;

    assign equal = (a == b) ? 1'b1 : 1'b0;

endmodule

sva:
module comparator_mux_sva (
    input logic [15:0] a,
    input logic [15:0] b,
    input logic [15:0] c,
    input logic        sel,
    input logic [15:0] out,
    input logic        equal
);

    // No explicit clock or reset exists in the RTL; use the global formal clock.

    // out matches the full comparator/mux expression from the RTL.
    check_out_matches_rtl: assert property (
        @($global_clock) out === ((sel == 1'b0) ? ((a > b) ? a : b) : c)
    );

    // equal matches the equality flag expression from the RTL.
    check_equal_matches_rtl: assert property (
        @($global_clock) equal === ((a == b) ? 1'b1 : 1'b0)
    );

    // When sel is low and a is greater than b, out selects a.
    check_out_selects_a_when_a_gt_b: assert property (
        @($global_clock) ((sel == 1'b0) && (a > b)) |-> (out === a)
    );

    // When sel is low and a is less than or equal to b, out selects b.
    check_out_selects_b_when_a_lte_b: assert property (
        @($global_clock) ((sel == 1'b0) && (a <= b)) |-> (out === b)
    );

    // When sel is high, out selects c.
    check_out_selects_c_when_sel_high: assert property (
        @($global_clock) (sel == 1'b1) |-> (out === c)
    );

    // When a and b are equal, the equal flag is asserted.
    check_equal_asserts_on_equal_inputs: assert property (
        @($global_clock) (a == b) |-> (equal === 1'b1)
    );

    // When a and b differ, the equal flag is deasserted.
    check_equal_deasserts_on_unequal_inputs: assert property (
        @($global_clock) (a != b) |-> (equal === 1'b0)
    );

endmodule

rtl:
module mux4to1 (
  input [3:0] data_in,
  input [1:0] select,
  input enable,
  output reg [3:0] data_out
);

always @(*) begin
  case (select)
    2'b00: data_out = enable ? data_in[0] : 4'b0000;
    2'b01: data_out = enable ? data_in[1] : 4'b0000;
    2'b10: data_out = enable ? data_in[2] : 4'b0000;
    2'b11: data_out = enable ? data_in[3] : 4'b0000;
  endcase
end

endmodule

sva:
module mux4to1_sva (
    input logic clk,
    input logic [3:0] data_in,
    input logic [1:0] select,
    input logic enable,
    input logic [3:0] data_out
);

    // When disabled, the output must be all zeros.
    check_output_zero_when_disabled: assert property (
        @(posedge clk) !enable |-> (data_out == 4'b0000)
    );

    // Select 00 forwards data_in[0] into the LSB and zero-extends the output.
    check_select_00_maps_bit0: assert property (
        @(posedge clk) enable && (select == 2'b00) |-> (data_out == {3'b000, data_in[0]})
    );

    // Select 01 forwards data_in[1] into the LSB and zero-extends the output.
    check_select_01_maps_bit1: assert property (
        @(posedge clk) enable && (select == 2'b01) |-> (data_out == {3'b000, data_in[1]})
    );

    // Select 10 forwards data_in[2] into the LSB and zero-extends the output.
    check_select_10_maps_bit2: assert property (
        @(posedge clk) enable && (select == 2'b10) |-> (data_out == {3'b000, data_in[2]})
    );

    // Select 11 forwards data_in[3] into the LSB and zero-extends the output.
    check_select_11_maps_bit3: assert property (
        @(posedge clk) enable && (select == 2'b11) |-> (data_out == {3'b000, data_in[3]})
    );

    // The upper three output bits are always zero due to 1-bit to 4-bit assignment.
    check_output_is_zero_extended: assert property (
        @(posedge clk) (data_out[3:1] == 3'b000)
    );

endmodule

module boolean_func_sva (
    input logic clk,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic B2,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB,
    input logic X
);

    // X must equal the implemented OR of the two product terms.
    check_x_matches_boolean_function: assert property (
        @(posedge clk) disable iff (1'b0)
            X == ((A1 & A2) | (B1 & B2 & VPWR & VGND & VPB & VNB))
    );

    // The A1/A2 product term alone is sufficient to drive X high.
    check_a_term_drives_x_high: assert property (
        @(posedge clk) disable iff (1'b0)
            (A1 & A2) |-> X
    );

    // The B1/B2 product term with all gating inputs high is sufficient to drive X high.
    check_b_term_drives_x_high: assert property (
        @(posedge clk) disable iff (1'b0)
            (B1 & B2 & VPWR & VGND & VPB & VNB) |-> X
    );

    // A high X must come from one of the two implemented product terms.
    check_x_high_has_valid_source: assert property (
        @(posedge clk) disable iff (1'b0)
            X |-> ((A1 & A2) | (B1 & B2 & VPWR & VGND & VPB & VNB))
    );

    // If neither product term is active, X must be low.
    check_x_low_without_active_terms: assert property (
        @(posedge clk) disable iff (1'b0)
            (!(A1 & A2) && !(B1 & B2 & VPWR & VGND & VPB & VNB)) |-> !X
    );

    // With the A term inactive, any low gating input blocks the B term from raising X.
    check_low_gate_blocks_b_term_when_a_term_inactive: assert property (
        @(posedge clk) disable iff (1'b0)
            (!(A1 & A2) && B1 && B2 && (!VPWR || !VGND || !VPB || !VNB)) |-> !X
    );

endmodule

rtl:
module register_counter (
    input clk,
    input reset, // Synchronous active-high reset
    input enable, // clock enable input to choose between register and counter
    input [7:0] d, // 8-bit input for the register
    output [7:0] q, // 8-bit output from the active module
    output [11:0] out_final // 12-bit output from the functional module
);

reg [7:0] reg_value;
reg [3:0] counter_value;

always @(posedge clk) begin
    if (reset) begin
        reg_value <= 8'h34;
        counter_value <= 4'b0;
    end else begin
        if (enable) begin
            counter_value <= counter_value + 1;
        end else begin
            reg_value <= d;
        end
    end
end

assign q = enable ? counter_value : reg_value;
assign out_final = {reg_value, counter_value};

endmodule

sva:
module register_counter_sva (
    input logic        clk,
    input logic        reset,
    input logic        enable,
    input logic [7:0]  d,
    input logic [7:0]  q,
    input logic [11:0] out_final
);

    // Reset sets the register and counter state to the defined values.
    check_reset_sets_out_final: assert property (
        @(posedge clk) disable iff ($initstate)
        reset |=> (out_final == 12'h340)
    );

    // After reset, q reflects the reset state through the current mux select.
    check_reset_sets_q: assert property (
        @(posedge clk) disable iff ($initstate)
        reset |=> (q == (enable ? 8'h00 : 8'h34))
    );

    // When enabled, the counter increments on the next cycle.
    check_counter_increments_on_enable: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        enable |=> (out_final[3:0] == ($past(out_final[3:0]) + 4'd1))
    );

    // When enabled, the register value holds on the next cycle.
    check_register_holds_on_enable: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        enable |=> (out_final[11:4] == $past(out_final[11:4]))
    );

    // When disabled, the register loads d on the next cycle.
    check_register_loads_d_on_disable: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        !enable |=> (out_final[11:4] == $past(d))
    );

    // When disabled, the counter holds on the next cycle.
    check_counter_holds_on_disable: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        !enable |=> (out_final[3:0] == $past(out_final[3:0]))
    );

    // q selects the zero-extended counter when enable is high.
    check_q_selects_counter_when_enabled: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        enable |-> (q == {4'b0000, out_final[3:0]})
    );

    // q selects the register value when enable is low.
    check_q_selects_register_when_disabled: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        !enable |-> (q == out_final[11:4])
    );

endmodule

rtl:
module velocityControlHdl_Dynamic_Saturation_block1
          (
           up,
           u,
           lo,
           y,
           sat_mode
          );


  input   signed [17:0] up;  // sfix18_En15
  input   signed [35:0] u;  // sfix36_En22
  input   signed [17:0] lo;  // sfix18_En15
  output  signed [35:0] y;  // sfix36_En22
  output  sat_mode;


  wire signed [35:0] LowerRelop1_1_cast;  // sfix36_En22
  wire LowerRelop1_relop1;
  wire signed [35:0] UpperRelop_1_cast;  // sfix36_En22
  wire UpperRelop_relop1;
  wire signed [35:0] lo_dtc;  // sfix36_En22
  wire signed [35:0] Switch_out1;  // sfix36_En22
  wire signed [35:0] up_dtc;  // sfix36_En22
  wire signed [35:0] Switch2_out1;  // sfix36_En22
  wire LowerRelop1_out1;


  // <S33>/LowerRelop1
  assign LowerRelop1_1_cast = {{11{up[17]}}, {up, 7'b0000000}};
  assign LowerRelop1_relop1 = (u > LowerRelop1_1_cast ? 1'b1 :
              1'b0);



  // <S33>/UpperRelop
  assign UpperRelop_1_cast = {{11{lo[17]}}, {lo, 7'b0000000}};
  assign UpperRelop_relop1 = (u < UpperRelop_1_cast ? 1'b1 :
              1'b0);



  assign lo_dtc = {{11{lo[17]}}, {lo, 7'b0000000}};



  // <S33>/Switch
  assign Switch_out1 = (UpperRelop_relop1 == 1'b0 ? u :
              lo_dtc);



  assign up_dtc = {{11{up[17]}}, {up, 7'b0000000}};



  // <S33>/Switch2
  assign Switch2_out1 = (LowerRelop1_relop1 == 1'b0 ? Switch_out1 :
              up_dtc);



  assign y = Switch2_out1;

  // <S33>/Logical Operator
  assign LowerRelop1_out1 = LowerRelop1_relop1 | UpperRelop_relop1;



  assign sat_mode = LowerRelop1_out1;

endmodule

sva:
module velocityControlHdl_Dynamic_Saturation_block1_sva (
    input  logic               clk,
    input  logic signed [17:0] up,
    input  logic signed [35:0] u,
    input  logic signed [17:0] lo,
    input  logic signed [35:0] y,
    input  logic               sat_mode
);

    wire signed [35:0] up_dtc;
    wire signed [35:0] lo_dtc;
    wire               LowerRelop1_relop1;
    wire               UpperRelop_relop1;
    wire signed [35:0] Switch_out1;
    wire signed [35:0] Switch2_out1;
    wire               LowerRelop1_out1;

    assign up_dtc            = {{11{up[17]}}, {up, 7'b0000000}};
    assign lo_dtc            = {{11{lo[17]}}, {lo, 7'b0000000}};
    assign LowerRelop1_relop1 = (u > up_dtc ? 1'b1 : 1'b0);
    assign UpperRelop_relop1  = (u < lo_dtc ? 1'b1 : 1'b0);
    assign Switch_out1        = (UpperRelop_relop1 == 1'b0 ? u : lo_dtc);
    assign Switch2_out1       = (LowerRelop1_relop1 == 1'b0 ? Switch_out1 : up_dtc);
    assign LowerRelop1_out1   = LowerRelop1_relop1 | UpperRelop_relop1;

    // y follows the RTL's two-stage saturation mux chain.
    check_y_matches_switch_chain: assert property (
        @(posedge clk) y == Switch2_out1
    );

    // sat_mode is the OR of the upper and lower limit compares.
    check_sat_mode_matches_compare_or: assert property (
        @(posedge clk) sat_mode == LowerRelop1_out1
    );

    // If u exceeds the upper limit, y clamps to the upper value.
    check_upper_limit_clamps_output: assert property (
        @(posedge clk) LowerRelop1_relop1 |-> (y == up_dtc)
    );

    // If only the lower limit compare hits, y clamps to the lower value.
    check_lower_limit_clamps_output: assert property (
        @(posedge clk) (!LowerRelop1_relop1 && UpperRelop_relop1) |-> (y == lo_dtc)
    );

    // If neither compare hits, u passes through and sat_mode stays low.
    check_in_range_passthrough: assert property (
        @(posedge clk) (!LowerRelop1_relop1 && !UpperRelop_relop1) |-> ((y == u) && (sat_mode == 1'b0))
    );

    // If both compares hit, the second switch gives upper clamp priority.
    check_overlap_prefers_upper_limit: assert property (
        @(posedge clk) (LowerRelop1_relop1 && UpperRelop_relop1) |-> ((y == up_dtc) && (sat_mode == 1'b1))
    );

    // Equality at the upper limit is not an upper saturation if the lower compare is clear.
    check_upper_boundary_no_saturation: assert property (
        @(posedge clk) ((u == up_dtc) && !UpperRelop_relop1) |-> ((y == u) && (sat_mode == 1'b0))
    );

    // Equality at the lower limit is not a lower saturation if the upper compare is clear.
    check_lower_boundary_no_saturation: assert property (
        @(posedge clk) ((u == lo_dtc) && !LowerRelop1_relop1) |-> ((y == u) && (sat_mode == 1'b0))
    );

endmodule

rtl:
module macc_simple (
    input  wire        clk,
    input  wire [ 7:0] A,
    input  wire [ 7:0] B,
    output reg  [15:0] Z
);

    always @(posedge clk)
        Z <= Z + (A * B);

endmodule

sva:
module macc_simple_sva (
    input logic        clk,
    input logic [7:0]  A,
    input logic [7:0]  B,
    input logic [15:0] Z
);

    // Z equals the previous cycle's accumulator expression.
    check_accumulate_step: assert property (
        @(posedge clk) !$initstate |-> (Z == $past(Z + (A * B)))
    );

    // A zero operand causes the accumulator to hold.
    check_zero_operand_holds: assert property (
        @(posedge clk) (!$initstate && (($past(A) == 8'h00) || ($past(B) == 8'h00))) |-> (Z == $past(Z))
    );

    // A value of 1 on A adds the previous B directly.
    check_a_one_adds_b: assert property (
        @(posedge clk) (!$initstate && ($past(A) == 8'h01)) |-> (Z == $past(Z + B))
    );

    // A value of 1 on B adds the previous A directly.
    check_b_one_adds_a: assert property (
        @(posedge clk) (!$initstate && ($past(B) == 8'h01)) |-> (Z == $past(Z + A))
    );

    // Nonzero operands produce a nonzero increment.
    check_nonzero_operands_change_z: assert property (
        @(posedge clk) (!$initstate && ($past(A) != 8'h00) && ($past(B) != 8'h00)) |-> (Z != $past(Z))
    );

    // 8'hFF times 8'hFF contributes 16'hFE01 on the next cycle.
    check_max_product_step: assert property (
        @(posedge clk) (!$initstate && ($past(A) == 8'hFF) && ($past(B) == 8'hFF)) |-> (Z == ($past(Z) + 16'hFE01))
    );

endmodule

rtl:
module priority_encoder (
  input clk,
  input reset,
  input [3:0] in,
  input [3:0] valid,
  output reg [1:0] pos
);

  always @(posedge clk, negedge reset) begin
    if (!reset) begin
      pos <= 2'b0;
    end else begin
      if (valid[3]) begin
        pos <= 2'b11;
      end else if (valid[2]) begin
        pos <= 2'b10;
      end else if (valid[1]) begin
        pos <= 2'b01;
      end else if (valid[0]) begin
        pos <= 2'b00;
      end else begin
        pos <= 2'b0;
      end
    end
  end

endmodule

sva:
module priority_encoder_sva (
    input logic       clk,
    input logic       reset,
    input logic [3:0] in,
    input logic [3:0] valid,
    input logic [1:0] pos
);

    // pos must be zero while reset is asserted low.
    check_reset_clears_pos: assert property (
        @(posedge clk) !reset |-> (pos == 2'b00)
    );

    // valid[3] has highest priority and selects position 3.
    check_valid3_priority: assert property (
        @(posedge clk) disable iff (!reset)
        valid[3] |=> (pos == 2'b11)
    );

    // valid[2] selects position 2 when valid[3] is not set.
    check_valid2_priority: assert property (
        @(posedge clk) disable iff (!reset)
        (!valid[3] && valid[2]) |=> (pos == 2'b10)
    );

    // valid[1] selects position 1 when higher priority valids are not set.
    check_valid1_priority: assert property (
        @(posedge clk) disable iff (!reset)
        (!valid[3] && !valid[2] && valid[1]) |=> (pos == 2'b01)
    );

    // valid[0] selects position 0 when it is the highest valid bit.
    check_valid0_priority: assert property (
        @(posedge clk) disable iff (!reset)
        (!valid[3] && !valid[2] && !valid[1] && valid[0]) |=> (pos == 2'b00)
    );

    // No valid bits set drives the encoded position to zero.
    check_no_valid_defaults_zero: assert property (
        @(posedge clk) disable iff (!reset)
        (!valid[3] && !valid[2] && !valid[1] && !valid[0]) |=> (pos == 2'b00)
    );

endmodule

rtl:
module control(
  input clk,
  input rst,
  input [143:0] flit0c,
  input [143:0] flit1c,
  input [143:0] flitl0,
  input [143:0] flitl1,
  output reg port0_co,
  output reg port1_co,
  output reg portl0_co,
  output reg portl1_co,
  output reg ack0,
  output reg ack1
);

  always @(posedge clk) begin
    if (rst) begin
      port0_co <= 0;
      port1_co <= 0;
      portl0_co <= 0;
      portl1_co <= 0;
      ack0 <= 0;
      ack1 <= 0;
    end else begin
      port0_co <= flit0c;
      port1_co <= flit1c;
      portl0_co <= flitl0;
      portl1_co <= flitl1;
      ack0 <= (flitl0 != 0);
      ack1 <= (flitl1 != 0);
    end
  end

endmodule

sva:
module control_sva (
    input logic         clk,
    input logic         rst,
    input logic [143:0] flit0c,
    input logic [143:0] flit1c,
    input logic [143:0] flitl0,
    input logic [143:0] flitl1,
    input logic         port0_co,
    input logic         port1_co,
    input logic         portl0_co,
    input logic         portl1_co,
    input logic         ack0,
    input logic         ack1
);

    // A reset cycle clears all registered outputs.
    check_reset_clears_outputs: assert property (
        @(posedge clk) disable iff ($initstate)
        $past(rst) |-> ((port0_co  === 1'b0) &&
                        (port1_co  === 1'b0) &&
                        (portl0_co === 1'b0) &&
                        (portl1_co === 1'b0) &&
                        (ack0      === 1'b0) &&
                        (ack1      === 1'b0))
    );

    // port0_co stores flit0c[0], or 0 after reset.
    check_port0_co_update: assert property (
        @(posedge clk) disable iff ($initstate)
        port0_co === ($past(rst) ? 1'b0 : $past(flit0c[0]))
    );

    // port1_co stores flit1c[0], or 0 after reset.
    check_port1_co_update: assert property (
        @(posedge clk) disable iff ($initstate)
        port1_co === ($past(rst) ? 1'b0 : $past(flit1c[0]))
    );

    // portl0_co stores flitl0[0], or 0 after reset.
    check_portl0_co_update: assert property (
        @(posedge clk) disable iff ($initstate)
        portl0_co === ($past(rst) ? 1'b0 : $past(flitl0[0]))
    );

    // portl1_co stores flitl1[0], or 0 after reset.
    check_portl1_co_update: assert property (
        @(posedge clk) disable iff ($initstate)
        portl1_co === ($past(rst) ? 1'b0 : $past(flitl1[0]))
    );

    // ack0 reflects whether flitl0 was nonzero, or 0 after reset.
    check_ack0_update: assert property (
        @(posedge clk) disable iff ($initstate)
        ack0 === ($past(rst) ? 1'b0 : ($past(flitl0) != 144'b0))
    );

    // ack1 reflects whether flitl1 was nonzero, or 0 after reset.
    check_ack1_update: assert property (
        @(posedge clk) disable iff ($initstate)
        ack1 === ($past(rst) ? 1'b0 : ($past(flitl1) != 144'b0))
    );

endmodule

rtl:
module top_module (
    input clk,
    input [7:0] d1,
    input [7:0] d2,
    input sel,
    input reset,
    output reg [7:0] q
);

    reg [7:0] flip_flop_out;
    wire [7:0] multiplier_out;

    // 2-to-1 multiplexer
    assign multiplier_out = (sel == 1'b0) ? 8'b0 : d2;

    // 8 D flip-flops
    always @(posedge clk, posedge reset) begin
        if (reset) begin
            flip_flop_out <= 8'b0;
        end else begin
            flip_flop_out <= (sel == 1'b0) ? d1 : multiplier_out;
        end
    end

    // 8-bit multiplier
    always @*
    begin
        q <= flip_flop_out;
    end

endmodule

sva:
module top_module_sva (
    input logic       clk,
    input logic [7:0] d1,
    input logic [7:0] d2,
    input logic       sel,
    input logic       reset,
    input logic [7:0] q,
    input logic [7:0] flip_flop_out,
    input logic [7:0] multiplier_out
);

    // Clock: clk; reset: reset (active-high asynchronous).
    // Mixed sequential/combinational datapath.

    // sel=0 forces multiplier_out to zero.
    check_multiplier_zero_when_sel_low: assert property (
        @(posedge clk) disable iff (reset)
        (sel == 1'b0) |-> (multiplier_out == 8'b0)
    );

    // sel=1 passes d2 onto multiplier_out.
    check_multiplier_passes_d2_when_sel_high: assert property (
        @(posedge clk) disable iff (reset)
        (sel == 1'b1) |-> (multiplier_out == d2)
    );

    // q mirrors the internal register value.
    check_q_matches_flip_flop_out: assert property (
        @(posedge clk) disable iff (reset)
        (q == flip_flop_out)
    );

    // With sel low, the register captures d1 on the next clock.
    check_load_d1_when_sel_low: assert property (
        @(posedge clk) disable iff (reset)
        (sel == 1'b0) |=> (flip_flop_out == $past(d1))
    );

    // With sel high, the register captures d2 on the next clock.
    check_load_d2_when_sel_high: assert property (
        @(posedge clk) disable iff (reset)
        (sel == 1'b1) |=> (flip_flop_out == $past(d2))
    );

    // With sel low, q shows the prior d1 value on the next clock.
    check_q_captures_d1_when_sel_low: assert property (
        @(posedge clk) disable iff (reset)
        (sel == 1'b0) |=> (q == $past(d1))
    );

    // With sel high, q shows the prior d2 value on the next clock.
    check_q_captures_d2_when_sel_high: assert property (
        @(posedge clk) disable iff (reset)
        (sel == 1'b1) |=> (q == $past(d2))
    );

    // A reset cycle leaves the internal register cleared on the next clock.
    check_flip_flop_out_cleared_after_reset: assert property (
        @(posedge clk)
        reset |=> (flip_flop_out == 8'b0)
    );

    // A reset cycle leaves q cleared on the next clock.
    check_q_cleared_after_reset: assert property (
        @(posedge clk)
        reset |=> (q == 8'b0)
    );

endmodule

rtl:
module four_to_one (
    input in1,
    input in2,
    input in3,
    input in4,
    output out
);

wire a = in1 & in2;
wire b = in1 & in3;
wire c = in1 & in4;
wire d = in2 & in3;
wire e = in2 & in4;
wire f = in3 & in4;

wire ab = a | b;
wire ac = a | c;
wire ad = a | d;
wire ae = a | e;
wire af = a | f;
wire bd = b | d;
wire be = b | e;
wire bf = b | f;
wire cd = c | d;
wire ce = c | e;
wire cf = c | f;
wire de = d | e;
wire df = d | f;
wire ef = e | f;

wire abc = ab | c;
wire abd = ab | d;
wire abe = ab | e;
wire abf = ab | f;
wire acd = ac | d;
wire ace = ac | e;
wire acf = ac | f;
wire ade = ad | e;
wire adf = ad | f;
wire aef = ae | f;
wire bcd = bd | c;
wire bce = bd | e;
wire bcf = bd | f;
wire bde = be | d;
wire bdf = bd | f;
wire bef = be | f;
wire cde = cd | e;
wire cdf = cd | f;
wire cef = ce | f;
wire def = de | f;

assign out = abc | abd | abe | abf | acd | ace | acf | ade | adf | aef | bcd | bce | bcf | bde | bdf | bef | cde | cdf | cef | def;

endmodule

sva:
module four_to_one_assertions (
    input logic in1,
    input logic in2,
    input logic in3,
    input logic in4,
    input logic out
);

    // out must equal the OR of all pairwise input AND terms.
    check_out_matches_pairwise_or: assert property (
        @($global_clock)
        out == ((in1 && in2) || (in1 && in3) || (in1 && in4) ||
                (in2 && in3) || (in2 && in4) || (in3 && in4))
    );

    // Any time at least one input pair is high, out must be high.
    check_at_least_one_pair_high_sets_out: assert property (
        @($global_clock)
        (((in1 && in2) || (in1 && in3) || (in1 && in4) ||
          (in2 && in3) || (in2 && in4) || (in3 && in4)) |-> out)
    );

    // If no input pair is high, out must be low.
    check_no_pair_high_clears_out: assert property (
        @($global_clock)
        ((!((in1 && in2) || (in1 && in3) || (in1 && in4) ||
            (in2 && in3) || (in2 && in4) || (in3 && in4))) |-> !out)
    );

    // All inputs low must produce a low output.
    check_all_zero_inputs_clear_out: assert property (
        @($global_clock)
        ((!in1 && !in2 && !in3 && !in4) |-> !out)
    );

    // Any one-hot input pattern must produce a low output.
    check_one_hot_inputs_clear_out: assert property (
        @($global_clock)
        ((( in1 && !in2 && !in3 && !in4) ||
          (!in1 &&  in2 && !in3 && !in4) ||
          (!in1 && !in2 &&  in3 && !in4) ||
          (!in1 && !in2 && !in3 &&  in4)) |-> !out)
    );

    // Any exactly-two-hot input pattern must produce a high output.
    check_exactly_two_high_sets_out: assert property (
        @($global_clock)
        ((( in1 &&  in2 && !in3 && !in4) ||
          ( in1 && !in2 &&  in3 && !in4) ||
          ( in1 && !in2 && !in3 &&  in4) ||
          (!in1 &&  in2 &&  in3 && !in4) ||
          (!in1 &&  in2 && !in3 &&  in4) ||
          (!in1 && !in2 &&  in3 &&  in4)) |-> out)
    );

    // Any exactly-three-hot input pattern must produce a high output.
    check_exactly_three_high_sets_out: assert property (
        @($global_clock)
        (((!in1 &&  in2 &&  in3 &&  in4) ||
          ( in1 && !in2 &&  in3 &&  in4) ||
          ( in1 &&  in2 && !in3 &&  in4) ||
          ( in1 &&  in2 &&  in3 && !in4)) |-> out)
    );

    // All inputs high must produce a high output.
    check_all_one_inputs_set_out: assert property (
        @($global_clock)
        ((in1 && in2 && in3 && in4) |-> out)
    );

    // A high output must be justified by at least one high input pair.
    check_out_high_implies_some_pair_high: assert property (
        @($global_clock)
        (out |-> ((in1 && in2) || (in1 && in3) || (in1 && in4) ||
                  (in2 && in3) || (in2 && in4) || (in3 && in4)))
    );

    // A low output means no input pair is simultaneously high.
    check_out_low_implies_no_pair_high: assert property (
        @($global_clock)
        ((!out) |-> !((in1 && in2) || (in1 && in3) || (in1 && in4) ||
                       (in2 && in3) || (in2 && in4) || (in3 && in4)))
    );

endmodule

rtl:
module inv (
    data,   // Data input to the inv. (Required)
    result  // inverted result. (Required)
);

// GLOBAL PARAMETER DECLARATION
    parameter lpm_width = 1; // Width of the data[] and result[] ports. (Required)
    parameter lpm_type = "lpm_inv";
    parameter lpm_hint = "UNUSED";

// INPUT PORT DECLARATION
    input  [lpm_width-1:0] data;

// OUTPUT PORT DECLARATION
    output [lpm_width-1:0] result;

// INTERNAL REGISTERS DECLARATION
    reg    [lpm_width-1:0] result;

// INITIAL CONSTRUCT BLOCK
    initial
    begin
        if (lpm_width <= 0)
        begin
            $display("Value of lpm_width parameter must be greater than 0 (ERROR)");
            $display("Time: %0t  Instance: %m", $time);
            $finish;
        end
    end

// ALWAYS CONSTRUCT BLOCK
    always @(data)
        result = ~data;

endmodule

sva:
module inv_assertions #(
    parameter integer lpm_width = 1,
    parameter lpm_type = "lpm_inv",
    parameter lpm_hint = "UNUSED"
) (
    input logic clk,
    input logic [lpm_width-1:0] data,
    input logic [lpm_width-1:0] result
);

    // Result matches the bitwise inversion of the current input.
    check_result_is_bitwise_inverse: assert property (
        @(posedge clk) result === ~data
    );

    // If the sampled input is unchanged, the sampled output is also unchanged.
    check_stable_input_gives_stable_output: assert property (
        @(posedge clk) $stable(data) |-> $stable(result)
    );

endmodule

rtl:
module controllerHdl_Wrap_2pi
          (
           x,
           wrap
          );


  input   signed [18:0] x;  output  signed [17:0] wrap;  wire signed [18:0] Two_Pi1_out1;  wire signed [18:0] Two_Pi3_out1;  wire Relational_Operator1_relop1;
  wire signed [19:0] x_dtc;  wire signed [18:0] Two_Pi2_out1;  wire signed [18:0] Two_Pi_out1;  wire Relational_Operator_relop1;
  wire signed [19:0] Add2_add_cast;  wire signed [19:0] Add2_add_cast_1;  wire signed [19:0] Add2_out1;  wire signed [19:0] Switch1_out1;  wire signed [17:0] Switch1_out1_dtc;  wire signed [19:0] Add1_sub_cast;  wire signed [19:0] Add1_sub_cast_1;  wire signed [19:0] Add1_out1;  wire signed [17:0] Add1_out1_dtc;  wire signed [17:0] Switch_out1;  assign Two_Pi1_out1 = 19'sb0011001001000100000;



  assign Two_Pi3_out1 = 19'sb0000000000000000000;



  assign Relational_Operator1_relop1 = (x < Two_Pi3_out1 ? 1'b1 :
              1'b0);



  assign x_dtc = x;



  assign Two_Pi2_out1 = 19'sb0011001001000100000;



  assign Two_Pi_out1 = 19'sb0011001001000100000;



  assign Relational_Operator_relop1 = (x >= Two_Pi1_out1 ? 1'b1 :
              1'b0);



  assign Add2_add_cast = x;
  assign Add2_add_cast_1 = Two_Pi2_out1;
  assign Add2_out1 = Add2_add_cast + Add2_add_cast_1;



  assign Switch1_out1 = (Relational_Operator1_relop1 == 1'b0 ? x_dtc :
              Add2_out1);



  assign Switch1_out1_dtc = Switch1_out1[17:0];



  assign Add1_sub_cast = x;
  assign Add1_sub_cast_1 = Two_Pi_out1;
  assign Add1_out1 = Add1_sub_cast - Add1_sub_cast_1;



  assign Add1_out1_dtc = Add1_out1[17:0];



  assign Switch_out1 = (Relational_Operator_relop1 == 1'b0 ? Switch1_out1_dtc :
              Add1_out1_dtc);



  assign wrap = Switch_out1;

endmodule

sva:
module controllerHdl_Wrap_2pi_assertions (
    input logic clk,
    input logic signed [18:0] x,
    input logic signed [17:0] wrap
);

    // Sampled on external clk because the RTL is combinational and has no reset.
    localparam logic signed [18:0] TWO_PI     = 19'sb0011001001000100000;
    localparam logic signed [19:0] TWO_PI_EXT = 20'sb00011001001000100000;

    // Output matches the RTL's full conditional datapath.
    check_full_wrap_function: assert property (
        @(posedge clk)
        wrap == (
            (x >= TWO_PI) ? logic signed [17:0]'($signed({x[18], x}) - TWO_PI_EXT) :
            ((x < 19'sd0) ? logic signed [17:0]'($signed({x[18], x}) + TWO_PI_EXT) :
                            logic signed [17:0]'(x))
        )
    );

    // Negative inputs take the add-constant path.
    check_negative_input_adds_two_pi: assert property (
        @(posedge clk)
        (x < 19'sd0) |-> (wrap == logic signed [17:0]'($signed({x[18], x}) + TWO_PI_EXT))
    );

    // Non-negative inputs below the constant pass through unchanged.
    check_midrange_input_passthrough: assert property (
        @(posedge clk)
        ((x >= 19'sd0) && (x < TWO_PI)) |-> (wrap == logic signed [17:0]'(x))
    );

    // Inputs at or above the constant take the subtract-constant path.
    check_large_input_subtracts_two_pi: assert property (
        @(posedge clk)
        (x >= TWO_PI) |-> (wrap == logic signed [17:0]'($signed({x[18], x}) - TWO_PI_EXT))
    );

    // Zero maps directly to zero.
    check_zero_maps_to_zero: assert property (
        @(posedge clk)
        (x == 19'sd0) |-> (wrap == 18'sd0)
    );

    // The constant itself maps to zero after one subtraction.
    check_two_pi_maps_to_zero: assert property (
        @(posedge clk)
        (x == TWO_PI) |-> (wrap == 18'sd0)
    );

    // Negative of the constant maps to zero after one addition.
    check_minus_two_pi_maps_to_zero: assert property (
        @(posedge clk)
        (x == -TWO_PI) |-> (wrap == 18'sd0)
    );

endmodule

rtl:
module d_latch_with_reset_and_enable (
    input clk,
    input D,
    input EN,
    input RESET,
    output reg Q,
    output reg Q_n
);

    always @(posedge clk) begin
        if (RESET) begin
            Q <= 1'b0;
            Q_n <= 1'b1;
        end else if (EN) begin
            Q <= D;
            Q_n <= ~D;
        end
    end

endmodule

sva:
module d_latch_with_reset_and_enable_sva (
    input logic clk,
    input logic D,
    input logic EN,
    input logic RESET,
    input logic Q,
    input logic Q_n
);

    // Reset drives Q low on the next sampled cycle.
    check_reset_forces_q_low: assert property (
        @(posedge clk) RESET |=> (Q == 1'b0)
    );

    // Reset drives Q_n high on the next sampled cycle.
    check_reset_forces_qn_high: assert property (
        @(posedge clk) RESET |=> (Q_n == 1'b1)
    );

    // When enabled, Q captures D.
    check_enable_loads_q_from_d: assert property (
        @(posedge clk) disable iff (RESET) EN |=> (Q == $past(D))
    );

    // When enabled, Q_n captures the inverse of D.
    check_enable_loads_qn_from_inverted_d: assert property (
        @(posedge clk) disable iff (RESET) EN |=> (Q_n == ~$past(D))
    );

    // When not enabled, Q holds its previous value.
    check_hold_q_when_disabled: assert property (
        @(posedge clk) disable iff (RESET) !EN |=> $stable(Q)
    );

    // When not enabled, Q_n holds its previous value.
    check_hold_qn_when_disabled: assert property (
        @(posedge clk) disable iff (RESET) !EN |=> $stable(Q_n)
    );

endmodule

rtl:
module mux4to1 (
    in0,
    in1,
    in2,
    in3,
    sel0,
    sel1,
    out
);

    input [3:0] in0, in1, in2, in3;
    input sel0, sel1;
    output [3:0] out;

    wire [3:0] sel;

    assign sel = {sel1, sel0};

    assign out = (sel == 2'b00) ? in0 :
                 (sel == 2'b01) ? in1 :
                 (sel == 2'b10) ? in2 :
                 in3;

endmodule

sva:
module mux4to1_sva (
    input logic        clk,
    input logic [3:0]  in0,
    input logic [3:0]  in1,
    input logic [3:0]  in2,
    input logic [3:0]  in3,
    input logic        sel0,
    input logic        sel1,
    input logic [3:0]  out
);

    // Output matches the implemented mux expression.
    check_mux_function: assert property (
        @(posedge clk)
        out == (({sel1, sel0} == 2'b00) ? in0 :
                ({sel1, sel0} == 2'b01) ? in1 :
                ({sel1, sel0} == 2'b10) ? in2 :
                in3)
