    check_sel_00_routes_in0: assert property (
        @(posedge clk)
        ({sel1, sel0} == 2'b00) |-> (out == in0)
    );

    // Select 01 routes in1 to out.
    check_sel_01_routes_in1: assert property (
        @(posedge clk)
        ({sel1, sel0} == 2'b01) |-> (out == in1)
    );

    // Select 10 routes in2 to out.
    check_sel_10_routes_in2: assert property (
        @(posedge clk)
        ({sel1, sel0} == 2'b10) |-> (out == in2)
    );

    // Select 11 routes in3 to out.
    check_sel_11_routes_in3: assert property (
        @(posedge clk)
        ({sel1, sel0} == 2'b11) |-> (out == in3)
    );

endmodule

module mux_4to1_sva (
    input logic in0,
    input logic in1,
    input logic in2,
    input logic in3,
    input logic sel1,
    input logic sel2,
    input logic out
);

    // Output matches the RTL mux equation.
    check_mux_equation: assert property (
        @($global_clock)
        out == ((sel1 & sel2) ? in3 :
                ((sel1 & ~sel2) ? in2 :
                 ((~sel1 & sel2) ? in1 : in0)))
    );

    // sel1=0 and sel2=0 selects in0.
    check_select_in0: assert property (
        @($global_clock)
        (!sel1 && !sel2) |-> (out == in0)
    );

    // sel1=0 and sel2=1 selects in1.
    check_select_in1: assert property (
        @($global_clock)
        (!sel1 && sel2) |-> (out == in1)
    );

    // sel1=1 and sel2=0 selects in2.
    check_select_in2: assert property (
        @($global_clock)
        (sel1 && !sel2) |-> (out == in2)
    );

    // sel1=1 and sel2=1 selects in3.
    check_select_in3: assert property (
        @($global_clock)
        (sel1 && sel2) |-> (out == in3)
    );

endmodule

rtl:
module and_gate (
    input wire [7:0] a,
    input wire [7:0] b,
    output wire [7:0] y
);
    assign y = a & b;
endmodule
module not_gate (
    input wire [7:0] a,
    output wire [7:0] y
);
    assign y = ~a;
endmodule
module mux8x1 (
    input wire [7:0] a,
    input wire [7:0] b,
    input wire sel,
    output wire [7:0] y
);
    assign y = (sel) ? b : a;
endmodule
module barrel_shifter (
    input wire [15:0] in,
    output reg [7:0] out1,
    output reg [7:0] out2
);
    always @(*) begin
        out1 = in[15:8];
        out2 = in[7:0];
    end
endmodule
module top_module(
    input wire [7:0] and_input,
    input wire [15:0] shifter_input,
    input wire select,
    output reg [7:0] functional_output
);
    wire [7:0] and_output;
    wire [7:0] shifter_output1;
    wire [7:0] shifter_output2;

    and_gate and_gate_inst (
        .a(and_input),
        .b(and_input),
        .y(and_output)
    );

    barrel_shifter barrel_shifter_inst (
        .in(shifter_input),
        .out1(shifter_output1),
        .out2(shifter_output2)
    );

    always @(*) begin
        if (select) begin
            functional_output = and_output | shifter_output1;
        end else begin
            functional_output = and_output | shifter_output2;
        end
    end
endmodule

sva:
module top_module_sva (
    input logic [7:0]  and_input,
    input logic [15:0] shifter_input,
    input logic        select,
    input logic [7:0]  functional_output
);

    // Output matches the top-level combinational definition.
    check_functional_output_definition: assert property (
        @($global_clock)
        functional_output == (and_input | ((select === 1'b1) ? shifter_input[15:8] : shifter_input[7:0]))
    );

    // A select value of 1 uses the upper shifter byte.
    check_select_one_uses_upper_byte: assert property (
        @($global_clock)
        (select === 1'b1) |-> (functional_output == (and_input | shifter_input[15:8]))
    );

    // Any non-1 select value uses the lower shifter byte.
    check_select_not_one_uses_lower_byte: assert property (
        @($global_clock)
        (select !== 1'b1) |-> (functional_output == (and_input | shifter_input[7:0]))
    );

    // Zero and_input passes the upper byte when select is 1.
    check_zero_and_input_upper_path: assert property (
        @($global_clock)
        ((select === 1'b1) && (and_input == 8'h00)) |-> (functional_output == shifter_input[15:8])
    );

    // Zero and_input passes the lower byte when select is not 1.
    check_zero_and_input_lower_path: assert property (
        @($global_clock)
        ((select !== 1'b1) && (and_input == 8'h00)) |-> (functional_output == shifter_input[7:0])
    );

    // A zero upper byte makes the output equal and_input on the upper path.
    check_zero_upper_byte_passes_and_input: assert property (
        @($global_clock)
        ((select === 1'b1) && (shifter_input[15:8] == 8'h00)) |-> (functional_output == and_input)
    );

    // A zero lower byte makes the output equal and_input on the lower path.
    check_zero_lower_byte_passes_and_input: assert property (
        @($global_clock)
        ((select !== 1'b1) && (shifter_input[7:0] == 8'h00)) |-> (functional_output == and_input)
    );

    // Equal shifter bytes make the output independent of select.
    check_equal_shifter_bytes_ignore_select: assert property (
        @($global_clock)
        (shifter_input[15:8] == shifter_input[7:0]) |-> (functional_output == (and_input | shifter_input[7:0]))
    );

endmodule

bind top_module top_module_sva top_module_sva_inst (
    .and_input(and_input),
    .shifter_input(shifter_input),
    .select(select),
    .functional_output(functional_output)
);

rtl:
module binary_to_gray_xor (
    input wire [2:0] in_vec,
    output wire [2:0] out_vec
);

    assign out_vec[0] = in_vec[0] ^ in_vec[1];
    assign out_vec[1] = in_vec[1] ^ in_vec[2];
    assign out_vec[2] = in_vec[2];

endmodule
module top_module (
    input wire [2:0] in_vec,
    output wire [2:0] out_vec
);
    wire [2:0] out_vec_int;

    binary_to_gray_xor gray_xor(
        .in_vec(in_vec),
        .out_vec(out_vec_int)
    );

    assign out_vec = out_vec_int ^ 3'b010;

endmodule

sva:
module top_module_sva (
    input logic [2:0] in_vec,
    input logic [2:0] out_vec,
    input logic [2:0] out_vec_int
);

    // Internal bit 0 is XOR of input bits 0 and 1.
    check_internal_bit0_xor: assert property (
        @($global_clock) out_vec_int[0] == (in_vec[0] ^ in_vec[1])
    );

    // Internal bit 1 is XOR of input bits 1 and 2.
    check_internal_bit1_xor: assert property (
        @($global_clock) out_vec_int[1] == (in_vec[1] ^ in_vec[2])
    );

    // Internal bit 2 passes through input bit 2.
    check_internal_bit2_passthrough: assert property (
        @($global_clock) out_vec_int[2] == in_vec[2]
    );

    // Top output is the internal vector XORed with constant 3'b010.
    check_output_mask_xor: assert property (
        @($global_clock) ((out_vec ^ out_vec_int) == 3'b010)
    );

    // End-to-end output matches the implemented mapping.
    check_end_to_end_mapping: assert property (
        @($global_clock) out_vec == {in_vec[2], (in_vec[1] ~^ in_vec[2]), (in_vec[0] ^ in_vec[1])}
    );

endmodule

bind top_module top_module_sva top_module_sva_inst (
    .in_vec(in_vec),
    .out_vec(out_vec),
    .out_vec_int(out_vec_int)
);

rtl:
module pulse_generator (
    input D,
    input Q,
    output reg pulse
);

reg D_prev;

always @(posedge Q) begin
    if (D == 1'b1 && D_prev == 1'b0) begin
        pulse <= 1'b1;
    end else begin
        pulse <= 1'b0;
    end
    D_prev <= D;
end

endmodule

sva:
module pulse_generator_sva (
    input logic D,
    input logic Q,
    input logic pulse
);

    // Clock: Q; reset: none; logic: sequential on posedge Q.

    // From the third sampled clock onward, pulse matches a prior sampled 0->1 on D.
    check_pulse_matches_prior_sampled_rise: assert property (
        @(posedge Q) (##2 1'b1) |-> (pulse == ($past(D) && !$past(D,2)))
    );

    // A prior sampled low-to-high transition on D produces pulse.
    check_prior_low_to_high_generates_pulse: assert property (
        @(posedge Q) (##2 ($past(D) && !$past(D,2))) |-> pulse
    );

    // Consecutive sampled highs on D do not retrigger pulse.
    check_prior_high_to_high_suppresses_pulse: assert property (
        @(posedge Q) (##2 ($past(D) && $past(D,2))) |-> !pulse
    );

    // If D was low on the prior sampled clock, pulse is low now.
    check_prior_low_clears_pulse: assert property (
        @(posedge Q) (##1 (!$past(D))) |-> !pulse
    );

    // pulse can only occur if D was high on the prior sampled clock.
    check_pulse_requires_prior_high_d: assert property (
        @(posedge Q) (##1 pulse) |-> $past(D)
    );

    // Once established, pulse is only one sampled clock wide.
    check_pulse_is_single_cycle: assert property (
        @(posedge Q) (##1 pulse) |-> ##1 !pulse
    );

endmodule

