module sky130_fd_sc_hdll__o211a (
    X ,
    A1,
    A2,
    B1,
    C1
);

    output X ;
    input  A1;
    input  A2;
    input  B1;
    input  C1;

    wire or0_out   ;
    wire and0_out_X;

    or  or0  (or0_out   , A2, A1         );
    and and0 (and0_out_X, or0_out, B1, C1);
    buf buf0 (X         , and0_out_X     );

endmodule

sva:
module sky130_fd_sc_hdll__o211a_sva (
    input logic clk,
    input logic X,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic C1
);

    // X matches the implemented O211A logic equation.
    check_output_equation: assert property (
        @(posedge clk) X === ((A1 | A2) & B1 & C1)
    );

    // B1 low forces X low.
    check_b1_low_forces_x_low: assert property (
        @(posedge clk) (B1 === 1'b0) |-> (X === 1'b0)
    );

    // C1 low forces X low.
    check_c1_low_forces_x_low: assert property (
        @(posedge clk) (C1 === 1'b0) |-> (X === 1'b0)
    );

    // Both A inputs low force X low.
    check_a_inputs_low_force_x_low: assert property (
        @(posedge clk) ((A1 === 1'b0) && (A2 === 1'b0)) |-> (X === 1'b0)
    );

    // High X requires both B1 and C1 high.
    check_x_high_requires_b1_and_c1: assert property (
        @(posedge clk) (X === 1'b1) |-> ((B1 === 1'b1) && (C1 === 1'b1))
    );

    // High X requires at least one A input high.
    check_x_high_requires_a1_or_a2: assert property (
        @(posedge clk) (X === 1'b1) |-> ((A1 === 1'b1) || (A2 === 1'b1))
    );

    // A1 can drive X high when B1 and C1 are high.
    check_a1_path_drives_x_high: assert property (
        @(posedge clk) ((A1 === 1'b1) && (B1 === 1'b1) && (C1 === 1'b1)) |-> (X === 1'b1)
    );

    // A2 can drive X high when B1 and C1 are high.
    check_a2_path_drives_x_high: assert property (
        @(posedge clk) ((A2 === 1'b1) && (B1 === 1'b1) && (C1 === 1'b1)) |-> (X === 1'b1)
    );

endmodule

rtl:
module up_counter(clk, rst, count);
  input clk;
  input rst;
  output reg [3:0] count;

  always @(posedge clk or negedge rst) begin
    if(!rst) begin
      count <= 4'b0;
    end else begin
      count <= count + 1;
    end
  end
endmodule

sva:
module up_counter_sva (
    input logic       clk,
    input logic       rst,
    input logic [3:0] count
);

    // Sequential 4-bit up-counter with asynchronous active-low reset.

    // A sampled reset cycle forces the next sampled count to zero.
    check_reset_drives_zero_next: assert property (
        @(posedge clk)
        !rst |=> (count == 4'h0)
    );

    // After a sampled low-to-high reset transition, count is still zero before incrementing.
    check_reset_release_starts_from_zero: assert property (
        @(posedge clk)
        (!rst ##1 rst) |-> (count == 4'h0)
    );

    // Below max, the next sampled count is either +1 or 0 if async reset intervenes.
    check_count_advances_or_resets: assert property (
        @(posedge clk) disable iff (!rst)
        (count != 4'hF) |=> ((count == ($past(count) + 4'd1)) || (count == 4'h0))
    );

    // At max, the 4-bit counter wraps to zero on the next sampled clock.
    check_count_wraps_from_max: assert property (
        @(posedge clk) disable iff (!rst)
        (count == 4'hF) |=> (count == 4'h0)
    );

    // From zero, the next sampled count is either 1 or 0 if async reset intervenes.
    check_zero_advances_or_resets: assert property (
        @(posedge clk) disable iff (!rst)
        (count == 4'h0) |=> ((count == 4'h1) || (count == 4'h0))
    );

endmodule

rtl:
module decoder_3to8(
  input [2:0] input_bits,
  output reg [7:0] output_bits
);

  always @(*)
  begin
    case(input_bits)
      3'b000: output_bits = 8'b00000001;
      3'b001: output_bits = 8'b00000010;
      3'b010: output_bits = 8'b00000100;
      3'b011: output_bits = 8'b00001000;
      3'b100: output_bits = 8'b00010000;
      3'b101: output_bits = 8'b00100000;
      3'b110: output_bits = 8'b01000000;
      3'b111: output_bits = 8'b10000000;
    endcase
  end

endmodule

sva:
module decoder_3to8_assertions (
    input logic [2:0] input_bits,
    input logic [7:0] output_bits
);

    // No explicit RTL clock or reset; sample combinational behavior on $global_clock.

    // Output bit 0 is high only for input 000.
    check_decode_bit0: assert property (
        @($global_clock) output_bits[0] == (input_bits == 3'b000)
    );

    // Output bit 1 is high only for input 001.
    check_decode_bit1: assert property (
        @($global_clock) output_bits[1] == (input_bits == 3'b001)
    );

    // Output bit 2 is high only for input 010.
    check_decode_bit2: assert property (
        @($global_clock) output_bits[2] == (input_bits == 3'b010)
    );

    // Output bit 3 is high only for input 011.
    check_decode_bit3: assert property (
        @($global_clock) output_bits[3] == (input_bits == 3'b011)
    );

    // Output bit 4 is high only for input 100.
    check_decode_bit4: assert property (
        @($global_clock) output_bits[4] == (input_bits == 3'b100)
    );

    // Output bit 5 is high only for input 101.
    check_decode_bit5: assert property (
        @($global_clock) output_bits[5] == (input_bits == 3'b101)
    );

    // Output bit 6 is high only for input 110.
    check_decode_bit6: assert property (
        @($global_clock) output_bits[6] == (input_bits == 3'b110)
    );

    // Output bit 7 is high only for input 111.
    check_decode_bit7: assert property (
        @($global_clock) output_bits[7] == (input_bits == 3'b111)
    );

    // The output bit selected by input_bits must be high.
    check_selected_output_bit_high: assert property (
        @($global_clock) output_bits[input_bits] == 1'b1
    );

    // All non-selected output bits must be low.
    check_unselected_output_bits_low: assert property (
        @($global_clock) (output_bits & ~(8'b00000001 << input_bits)) == 8'b00000000
    );

endmodule

module alu_assertions (
    input logic        clk,
    input logic [3:0]  A,
    input logic [3:0]  B,
    input logic [2:0]  OP,
    input logic [3:0]  Y
);

    // Addition opcode drives Y to A + B.
    check_add_result: assert property (
        @(posedge clk) (OP === 3'b000) |-> (Y == (A + B))
    );

    // Subtraction opcode drives Y to A - B.
    check_sub_result: assert property (
        @(posedge clk) (OP === 3'b001) |-> (Y == (A - B))
    );

    // AND opcode drives Y to A & B.
    check_and_result: assert property (
        @(posedge clk) (OP === 3'b010) |-> (Y == (A & B))
    );

    // OR opcode drives Y to A | B.
    check_or_result: assert property (
        @(posedge clk) (OP === 3'b011) |-> (Y == (A | B))
    );

    // XOR opcode drives Y to A ^ B.
    check_xor_result: assert property (
        @(posedge clk) (OP === 3'b100) |-> (Y == (A ^ B))
    );

endmodule

