sva:
module sky130_fd_sc_hvl__lsbuflv2hv_isosrchvaon_sva (
    input logic X,
    input logic A,
    input logic SLEEP_B
);

    // On any port transition, the current stable state must satisfy X = A & SLEEP_B.
    check_x_matches_and_relation_on_port_activity: assert property (
        @(posedge A or negedge A or posedge SLEEP_B or negedge SLEEP_B or posedge X or negedge X)
        X == (A & SLEEP_B)
    );

    // Before A rises, X must already be low because A was low.
    check_x_low_before_a_rise: assert property (
        @(posedge A)
        X == 1'b0
    );

    // Before A falls, X must match SLEEP_B because A was high.
    check_x_matches_sleep_b_before_a_fall: assert property (
        @(negedge A)
        X == SLEEP_B
    );

    // Before SLEEP_B rises, X must already be low because sleep was active.
    check_x_low_before_sleep_b_rise: assert property (
        @(posedge SLEEP_B)
        X == 1'b0
    );

    // Before SLEEP_B falls, X must match A because the output was ungated.
    check_x_matches_a_before_sleep_b_fall: assert property (
        @(negedge SLEEP_B)
        X == A
    );

endmodule

module calculator_sva (
    input logic [7:0] a,
    input logic [7:0] b,
    input logic [1:0] opcode,
    input logic [7:0] result
);

    localparam logic [1:0] OP_ADD = 2'b00;
    localparam logic [1:0] OP_SUB = 2'b01;
    localparam logic [1:0] OP_MUL = 2'b10;
    localparam logic [1:0] OP_DIV = 2'b11;

    // Addition opcode drives result to the 8-bit sum.
    check_addition_result: assert property (
        @($global_clock) (opcode == OP_ADD) |-> (result == 8'(a + b))
    );

    // Subtraction opcode drives result to the 8-bit difference.
    check_subtraction_result: assert property (
        @($global_clock) (opcode == OP_SUB) |-> (result == 8'(a - b))
    );

    // Multiplication opcode drives result to the low 8 bits of the product.
    check_multiplication_result: assert property (
        @($global_clock) (opcode == OP_MUL) |-> (result == 8'(a * b))
    );

    // Division opcode drives result to the quotient when the divisor is nonzero.
    check_division_result: assert property (
        @($global_clock) ((opcode == OP_DIV) && (b != 8'h00)) |-> (result == 8'(a / b))
    );

    // With defined inputs held constant, result remains constant.
    check_result_stable_when_inputs_stable: assert property (
        @($global_clock)
        ($stable(a) && $stable(b) && $stable(opcode) && !((opcode == OP_DIV) && (b == 8'h00)))
        |-> $stable(result)
    );

endmodule

rtl:
module alu(
	input clk,
	input [7:0] A,
	input [7:0] B,
	input [3:0] operation,
	output reg [7:0] result,
	output reg CF,
	output reg ZF,
	output reg SF
);

	localparam ALU_OP_ADD  = 4'b0000;
	localparam ALU_OP_SUB  = 4'b0001;
	localparam ALU_OP_ADC  = 4'b0010;
	localparam ALU_OP_SBC  = 4'b0011;

	localparam ALU_OP_AND  = 4'b0100;
	localparam ALU_OP_OR   = 4'b0101;
	localparam ALU_OP_NOT  = 4'b0110;
	localparam ALU_OP_XOR  = 4'b0111;

	localparam ALU_OP_SHL  = 4'b1000;
	localparam ALU_OP_SHR  = 4'b1001;
	localparam ALU_OP_SAL  = 4'b1010;
	localparam ALU_OP_SAR  = 4'b1011;

	localparam ALU_OP_ROL  = 4'b1100;
	localparam ALU_OP_ROR  = 4'b1101;
	localparam ALU_OP_RCL  = 4'b1110;
	localparam ALU_OP_RCR  = 4'b1111;

	reg [8:0] tmp;

	always @(posedge clk)
	begin
		case (operation)
			ALU_OP_ADD :
				tmp = A + B;
			ALU_OP_SUB :
				tmp = A - B;
			ALU_OP_ADC :
				tmp = A + B + { 7'b0000000, CF };
			ALU_OP_SBC :
				tmp = A - B - { 7'b0000000, CF };
			ALU_OP_AND :
				tmp = {1'b0, A & B };
			ALU_OP_OR :
				tmp = {1'b0, A | B };
			ALU_OP_NOT :
				tmp = {1'b0, ~B };
			ALU_OP_XOR :
				tmp = {1'b0, A ^ B};
			ALU_OP_SHL :
				tmp = { A[7], A[6:0], 1'b0};
			ALU_OP_SHR :
				tmp = { A[0], 1'b0, A[7:1]};
			ALU_OP_SAL :
				tmp = { A[7], A[6:0], 1'b0};
			ALU_OP_SAR :
				tmp = { A[0], A[7], A[7:1]};
			ALU_OP_ROL :
				tmp = { A[7], A[6:0], A[7]};
			ALU_OP_ROR :
				tmp = { A[0], A[0], A[7:1]};
			ALU_OP_RCL :
				tmp = { A[7], A[6:0], CF};
			ALU_OP_RCR :
				tmp = { A[0], CF, A[7:1]};
		endcase

		CF <= tmp[8];
		ZF <= tmp[7:0] == 0;
		SF <= tmp[7];

		result <= tmp[7:0];
	end
endmodule

sva:
module alu_sva (
    input logic clk,
    input logic [7:0] A,
    input logic [7:0] B,
    input logic [3:0] operation,
    input logic [7:0] result,
    input logic CF,
    input logic ZF,
    input logic SF
);

    localparam logic [3:0] ALU_OP_ADD  = 4'b0000;
    localparam logic [3:0] ALU_OP_SUB  = 4'b0001;
    localparam logic [3:0] ALU_OP_ADC  = 4'b0010;
    localparam logic [3:0] ALU_OP_SBC  = 4'b0011;

    localparam logic [3:0] ALU_OP_AND  = 4'b0100;
    localparam logic [3:0] ALU_OP_OR   = 4'b0101;
    localparam logic [3:0] ALU_OP_NOT  = 4'b0110;
    localparam logic [3:0] ALU_OP_XOR  = 4'b0111;

    localparam logic [3:0] ALU_OP_SHL  = 4'b1000;
    localparam logic [3:0] ALU_OP_SHR  = 4'b1001;
    localparam logic [3:0] ALU_OP_SAL  = 4'b1010;
    localparam logic [3:0] ALU_OP_SAR  = 4'b1011;

    localparam logic [3:0] ALU_OP_ROL  = 4'b1100;
    localparam logic [3:0] ALU_OP_ROR  = 4'b1101;
    localparam logic [3:0] ALU_OP_RCL  = 4'b1110;
    localparam logic [3:0] ALU_OP_RCR  = 4'b1111;

    function automatic logic [10:0] expected_outputs (
        input logic [7:0] a,
        input logic [7:0] b,
        input logic [3:0] op,
        input logic cf_in
    );
        logic [8:0] t;
        begin
            case (op)
                ALU_OP_ADD : t = a + b;
                ALU_OP_SUB : t = a - b;
                ALU_OP_ADC : t = a + b + {7'b0000000, cf_in};
                ALU_OP_SBC : t = a - b - {7'b0000000, cf_in};
                ALU_OP_AND : t = {1'b0, a & b};
                ALU_OP_OR  : t = {1'b0, a | b};
                ALU_OP_NOT : t = {1'b0, ~b};
                ALU_OP_XOR : t = {1'b0, a ^ b};
                ALU_OP_SHL : t = {a[7], a[6:0], 1'b0};
                ALU_OP_SHR : t = {a[0], 1'b0, a[7:1]};
                ALU_OP_SAL : t = {a[7], a[6:0], 1'b0};
                ALU_OP_SAR : t = {a[0], a[7], a[7:1]};
                ALU_OP_ROL : t = {a[7], a[6:0], a[7]};
                ALU_OP_ROR : t = {a[0], a[0], a[7:1]};
                ALU_OP_RCL : t = {a[7], a[6:0], cf_in};
                ALU_OP_RCR : t = {a[0], cf_in, a[7:1]};
                default    : t = 9'h000;
            endcase

            expected_outputs = {t[8], (t[7:0] == 8'h00), t[7], t[7:0]};
        end
    endfunction

    // ZF tracks whether the registered result is zero.
    check_zero_flag_matches_result: assert property (
        @(posedge clk) 1'b1 |=> (ZF == (result == 8'h00))
    );

    // SF tracks the MSB of the registered result.
    check_sign_flag_matches_result: assert property (
        @(posedge clk) 1'b1 |=> (SF == result[7])
    );

    // ADD updates outputs from A + B.
    check_add_outputs: assert property (
        @(posedge clk) (operation == ALU_OP_ADD) |=> ({CF, ZF, SF, result} == expected_outputs($past(A), $past(B), ALU_OP_ADD, $past(CF)))
    );

    // SUB updates outputs from A - B.
    check_sub_outputs: assert property (
        @(posedge clk) (operation == ALU_OP_SUB) |=> ({CF, ZF, SF, result} == expected_outputs($past(A), $past(B), ALU_OP_SUB, $past(CF)))
    );

    // ADC uses the previous CF as carry-in.
    check_adc_outputs_use_prior_cf: assert property (
        @(posedge clk) (operation == ALU_OP_ADC) |=> ({CF, ZF, SF, result} == expected_outputs($past(A), $past(B), ALU_OP_ADC, $past(CF)))
    );

    // SBC uses the previous CF as borrow-in.
    check_sbc_outputs_use_prior_cf: assert property (
        @(posedge clk) (operation == ALU_OP_SBC) |=> ({CF, ZF, SF, result} == expected_outputs($past(A), $past(B), ALU_OP_SBC, $past(CF)))
    );

    // AND updates outputs from A & B.
    check_and_outputs: assert property (
        @(posedge clk) (operation == ALU_OP_AND) |=> ({CF, ZF, SF, result} == expected_outputs($past(A), $past(B), ALU_OP_AND, $past(CF)))
    );

    // OR updates outputs from A | B.
    check_or_outputs: assert property (
        @(posedge clk) (operation == ALU_OP_OR) |=> ({CF, ZF, SF, result} == expected_outputs($past(A), $past(B), ALU_OP_OR, $past(CF)))
    );

    // NOT updates outputs from ~B.
    check_not_outputs: assert property (
        @(posedge clk) (operation == ALU_OP_NOT) |=> ({CF, ZF, SF, result} == expected_outputs($past(A), $past(B), ALU_OP_NOT, $past(CF)))
    );

    // XOR updates outputs from A ^ B.
    check_xor_outputs: assert property (
        @(posedge clk) (operation == ALU_OP_XOR) |=> ({CF, ZF, SF, result} == expected_outputs($past(A), $past(B), ALU_OP_XOR, $past(CF)))
    );

    // SHL shifts A left and moves A[7] into CF.
    check_shl_outputs: assert property (
        @(posedge clk) (operation == ALU_OP_SHL) |=> ({CF, ZF, SF, result} == expected_outputs($past(A), $past(B), ALU_OP_SHL, $past(CF)))
    );

    // SHR shifts A right and moves A[0] into CF.
    check_shr_outputs: assert property (
        @(posedge clk) (operation == ALU_OP_SHR) |=> ({CF, ZF, SF, result} == expected_outputs($past(A), $past(B), ALU_OP_SHR, $past(CF)))
    );

    // SAL behaves the same as SHL in this RTL.
    check_sal_outputs: assert property (
        @(posedge clk) (operation == ALU_OP_SAL) |=> ({CF, ZF, SF, result} == expected_outputs($past(A), $past(B), ALU_OP_SAL, $past(CF)))
    );

    // SAR shifts right arithmetically and moves A[0] into CF.
    check_sar_outputs: assert property (
        @(posedge clk) (operation == ALU_OP_SAR) |=> ({CF, ZF, SF, result} == expected_outputs($past(A), $past(B), ALU_OP_SAR, $past(CF)))
    );

    // ROL rotates A left and moves A[7] into CF.
    check_rol_outputs: assert property (
        @(posedge clk) (operation == ALU_OP_ROL) |=> ({CF, ZF, SF, result} == expected_outputs($past(A), $past(B), ALU_OP_ROL, $past(CF)))
    );

    // ROR rotates A right and moves A[0] into CF.
    check_ror_outputs: assert property (
        @(posedge clk) (operation == ALU_OP_ROR) |=> ({CF, ZF, SF, result} == expected_outputs($past(A), $past(B), ALU_OP_ROR, $past(CF)))
    );

    // RCL rotates A left through the previous CF.
    check_rcl_outputs_use_prior_cf: assert property (
        @(posedge clk) (operation == ALU_OP_RCL) |=> ({CF, ZF, SF, result} == expected_outputs($past(A), $past(B), ALU_OP_RCL, $past(CF)))
    );

    // RCR rotates A right through the previous CF.
    check_rcr_outputs_use_prior_cf: assert property (
        @(posedge clk) (operation == ALU_OP_RCR) |=> ({CF, ZF, SF, result} == expected_outputs($past(A), $past(B), ALU_OP_RCR, $past(CF)))
    );

endmodule

rtl:
module top_module (
    input clk,
    input reset,   // Synchronous active-high reset
    output [3:1] ena,
    output [15:0] q);

    wire [3:0] bcd_out;
    wire [15:0] binary_out;
    wire [3:1] ena_out;

    binary_to_bcd_converter bcd_converter(
        .binary_in(binary_out),
        .bcd_out(bcd_out)
    );

    priority_encoder priority_encoder_inst(
        .in(ena_out),
        .out(ena)
    );

    reg [15:0] count;
    reg [3:1] ena_reg;

    always @(posedge clk) begin
        if (reset) begin
            count <= 0;
            ena_reg <= 0;
        end
        else begin
            count <= count + 1;
            ena_reg <= ena_out;
        end
    end

    assign binary_out = count;
    assign ena_out = {3{1'b1}};

    assign q = {bcd_out[3], bcd_out[2], bcd_out[1], bcd_out[0], 12'b0};

endmodule

module binary_to_bcd_converter (
    input [15:0] binary_in,
    output [3:0] bcd_out
);

    reg [3:0] bcd_reg;

    always @* begin
        case (binary_in)
            0: bcd_reg = 4'b0000;
            1: bcd_reg = 4'b0001;
            2: bcd_reg = 4'b0010;
            3: bcd_reg = 4'b0011;
            4: bcd_reg = 4'b0100;
            5: bcd_reg = 4'b0101;
            6: bcd_reg = 4'b0110;
            7: bcd_reg = 4'b0111;
            8: bcd_reg = 4'b1000;
            9: bcd_reg = 4'b1001;
            10: bcd_reg = 4'b0001;
            11: bcd_reg = 4'b0010;
            12: bcd_reg = 4'b0011;
            13: bcd_reg = 4'b0100;
            14: bcd_reg = 4'b0101;
            15: bcd_reg = 4'b0110;
            16: bcd_reg = 4'b0111;
            17: bcd_reg = 4'b1000;
            18: bcd_reg = 4'b1001;
            19: bcd_reg = 4'b0001;
            20: bcd_reg = 4'b0010;
            21: bcd_reg = 4'b0011;
            22: bcd_reg = 4'b0100;
            23: bcd_reg = 4'b0101;
            24: bcd_reg = 4'b0110;
            25: bcd_reg = 4'b0111;
            26: bcd_reg = 4'b1000;
            27: bcd_reg = 4'b1001;
            28: bcd_reg = 4'b0001;
            29: bcd_reg = 4'b0010;
            30: bcd_reg = 4'b0011;
            31: bcd_reg = 4'b0100;
            32: bcd_reg = 4'b0101;
            33: bcd_reg = 4'b0110;
            34: bcd_reg = 4'b0111;
            35: bcd_reg = 4'b1000;
            default: bcd_reg = 4'b0000;
        endcase
    end

    assign bcd_out = bcd_reg;

endmodule

module priority_encoder (
    input [2:0] in,
    output [2:0] out
