module shift_register (
    input clk,
    input parallel_load,
    input serial_in,
    output serial_out,
    input [3:0] data_in
);

reg [3:0] pipeline [0:2];

always @(posedge clk) begin
    if (parallel_load) begin
        pipeline[0] <= data_in;
    end else begin
        pipeline[0] <= pipeline[1];
    end
    pipeline[1] <= pipeline[2];
    pipeline[2] <= serial_in;
end

assign serial_out = pipeline[2];

endmodule

sva:
module shift_register_sva (
    input logic clk,
    input logic parallel_load,
    input logic serial_in,
    input logic serial_out,
    input logic [3:0] data_in,
    input logic [3:0] pipeline [0:2]
);

    // serial_out mirrors the LSB of pipeline[2].
    check_serial_out_matches_pipeline2: assert property (
        @(posedge clk) serial_out == pipeline[2][0]
    );

    // pipeline[2] captures serial_in with zero extension on each clock.
    check_pipeline2_captures_serial_in: assert property (
        @(posedge clk) 1'b1 |=> pipeline[2] == {3'b000, $past(serial_in)}
    );

    // The upper bits of pipeline[2] are cleared after each update.
    check_pipeline2_upper_bits_zero: assert property (
        @(posedge clk) 1'b1 |=> pipeline[2][3:1] == 3'b000
    );

    // pipeline[1] captures the previous value of pipeline[2].
    check_pipeline1_captures_pipeline2: assert property (
        @(posedge clk) 1'b1 |=> pipeline[1] == $past(pipeline[2])
    );

    // pipeline[0] loads data_in when parallel_load is high.
    check_pipeline0_loads_data_in: assert property (
        @(posedge clk) parallel_load |=> pipeline[0] == $past(data_in)
    );

    // pipeline[0] shifts in pipeline[1] when parallel_load is low.
    check_pipeline0_shifts_pipeline1: assert property (
        @(posedge clk) !parallel_load |=> pipeline[0] == $past(pipeline[1])
    );

    // pipeline[0] always takes the selected source from the prior cycle.
    check_pipeline0_selected_source: assert property (
        @(posedge clk) 1'b1 |=> pipeline[0] == ($past(parallel_load) ? $past(data_in) : $past(pipeline[1]))
    );

    // serial_out reflects the serial_in value sampled on the prior clock.
    check_serial_out_tracks_serial_in: assert property (
        @(posedge clk) 1'b1 |=> serial_out == $past(serial_in)
    );

endmodule

module decoder_4to16_sva (
    input logic [3:0]  in,
    input logic        clk,
    input logic [15:0] out
);

    function automatic logic [15:0] decode_expected(input logic [3:0] val);
        begin
            case (val)
                4'h1:    decode_expected = 16'h0001;
                4'h2:    decode_expected = 16'h0002;
                4'h3:    decode_expected = 16'h0004;
                4'h4:    decode_expected = 16'h0008;
                4'h5:    decode_expected = 16'h0010;
                4'h6:    decode_expected = 16'h0020;
                4'h7:    decode_expected = 16'h0040;
                4'h8:    decode_expected = 16'h0080;
                4'h9:    decode_expected = 16'h0100;
                4'hA:    decode_expected = 16'h0200;
                4'hB:    decode_expected = 16'h0400;
                4'hC:    decode_expected = 16'h0800;
                4'hD:    decode_expected = 16'h1000;
                4'hE:    decode_expected = 16'h2000;
                4'hF:    decode_expected = 16'h4000;
                default: decode_expected = 16'h0000;
            endcase
        end
    endfunction

    // Output matches the decode of the input from two clocks earlier.
    check_two_cycle_decode: assert property (
        @(posedge clk) disable iff ($initstate || $past($initstate))
            out == decode_expected($past(in, 2))
    );

    // An input of zero decodes to all zeros two clocks later.
    check_zero_input_maps_to_zero: assert property (
        @(posedge clk) disable iff ($initstate || $past($initstate))
            ($past(in, 2) == 4'h0) |-> (out == 16'h0000)
    );

    // Any nonzero input decodes to exactly one active bit in out[14:0].
    check_nonzero_input_is_onehot: assert property (
        @(posedge clk) disable iff ($initstate || $past($initstate))
            ($past(in, 2) != 4'h0) |-> (!out[15] && $onehot(out[14:0]))
    );

    // Input value 1 maps to the least-significant output bit.
    check_input_one_maps_to_lsb: assert property (
        @(posedge clk) disable iff ($initstate || $past($initstate))
            ($past(in, 2) == 4'h1) |-> (out == 16'h0001)
    );

    // Input value F maps to bit 14 and never to bit 15.
    check_input_f_maps_to_bit14: assert property (
        @(posedge clk) disable iff ($initstate || $past($initstate))
            ($past(in, 2) == 4'hF) |-> (out == 16'h4000)
    );

endmodule

