    input logic X,
    input logic A0,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic S0,
    input logic S1
);

    // Output matches the implemented mux equation; A3 is unused.
    check_mux_equation: assert property (
        @(posedge clk) X == (S1 ? A2 : (S0 ? A1 : A0))
