    check_select_a2_s0_low: assert property (
        @(posedge clk) (S1 && !S0) |-> (X == A2)
    );

    // When S1 is high and S0 is high, the output still comes from A2.
    check_select_a2_s0_high: assert property (
        @(posedge clk) (S1 && S0) |-> (X == A2)
    );

