rtl:
module _4bit_down_counter_with_synch_load_enable_clear(
    input Clock, Clear, Enable, Load,
    output reg [3:0] Q
);

always @(posedge Clock) begin
    if (Clear) begin
        Q <= 4'b1111;
    end else if (Enable) begin
        Q <= Q - 1;
    end else if (Load) begin
        Q <= 4'b1111;
    end
end

endmodule

sva:
module _4bit_down_counter_with_synch_load_enable_clear_sva (
    input logic       Clock,
    input logic       Clear,
    input logic       Enable,
    input logic       Load,
    input logic [3:0] Q
);

    // Clear synchronously sets Q to all ones.
    check_clear_sets_q_to_ones: assert property (
        @(posedge Clock) disable iff (1'b0)
        Clear |=> (Q == 4'hF)
    );

    // Enable decrements Q when Load is low.
    check_enable_decrements_q: assert property (
        @(posedge Clock) disable iff (1'b0)
        (!Clear && Enable && !Load) |=> (Q == ($past(Q) - 4'd1))
    );

    // Enable takes priority over Load.
    check_enable_has_priority_over_load: assert property (
        @(posedge Clock) disable iff (1'b0)
        (!Clear && Enable && Load) |=> (Q == ($past(Q) - 4'd1))
    );

    // Load sets Q to all ones when selected.
    check_load_sets_q_to_ones: assert property (
        @(posedge Clock) disable iff (1'b0)
        (!Clear && !Enable && Load) |=> (Q == 4'hF)
    );

    // Q holds its value when no control is asserted.
    check_hold_without_controls: assert property (
        @(posedge Clock) disable iff (1'b0)
        (!Clear && !Enable && !Load) |=> (Q == $past(Q))
    );

    // Decrement wraps from zero back to all ones.
    check_decrement_wraps_from_zero: assert property (
        @(posedge Clock) disable iff (1'b0)
        (!Clear && Enable && (Q == 4'h0)) |=> (Q == 4'hF)
    );

endmodule

rtl:
module top_module (
    input [3:0] A,
    input [3:0] B,
    input enable,
    output [3:0] result
);

    wire [1:0] comp_out;
    wire [15:0] dec_out;
    wire [3:0] final_out;

    // Instantiate the magnitude comparator module
    comparator comp_inst (
        .A(A),
        .B(B),
        .EQ(comp_out[0]),
        .GT(comp_out[1])
    );

    // Instantiate the 2-to-4 decoder module
    decoder dec_inst (
        .in(comp_out),
        .out(dec_out)
    );

    // Instantiate the functional module
    functional func_inst (
        .in(dec_out),
        .out(final_out)
    );

    // Output assignment based on the enable input
    assign result = enable ? final_out : 4'b0000;

endmodule
module comparator (
    input [3:0] A,
    input [3:0] B,
    output reg EQ,
    output reg GT
);

    always @ (A, B) begin
        if (A == B) begin
            EQ <= 1'b1;
            GT <= 1'b0;
        end else if (A > B) begin
            EQ <= 1'b0;
            GT <= 1'b1;
        end else begin
            EQ <= 1'b0;
            GT <= 1'b0;
        end
    end

endmodule
module decoder (
    input [1:0] in,
    output [15:0] out
);

    assign out = { 15'b0,
                   ~in[1] & ~in[0], // 00
                   ~in[1] & in[0],  // 01
                   in[1] & ~in[0],  // 10
                   in[1] & in[0]   // 11
                 };

endmodule
module functional (
    input [15:0] in,
    output reg [3:0] out
);

    always @ (in) begin
        case (in)
            16'b0000000000000010: out <= 4'b0001; // A < B
            16'b0000000000000100: out <= 4'b0010; // A = B
            16'b0000000000001000: out <= 4'b0100; // A > B
            default: out <= 4'b0000; // Invalid input
        endcase
    end

endmodule

sva:
module top_module_sva (
    input logic        clk,
    input logic [3:0]  A,
    input logic [3:0]  B,
    input logic        enable,
    input logic [1:0]  comp_out,
    input logic [15:0] dec_out,
    input logic [3:0]  final_out,
    input logic [3:0]  result
);

    // EQ reflects A == B.
    check_comparator_eq_flag: assert property (
        @(posedge clk) comp_out[0] == (A == B)
    );

    // GT reflects A > B.
    check_comparator_gt_flag: assert property (
        @(posedge clk) comp_out[1] == (A > B)
    );

    // Comparator never produces the unused 11 code.
    check_comparator_valid_codes: assert property (
        @(posedge clk) comp_out != 2'b11
    );

    // Decoder drives the low nibble from comp_out and keeps upper bits zero.
    check_decoder_mapping: assert property (
        @(posedge clk)
        dec_out == {12'b0,
                    (~comp_out[1] & ~comp_out[0]),
                    (~comp_out[1] &  comp_out[0]),
                    ( comp_out[1] & ~comp_out[0]),
                    ( comp_out[1] &  comp_out[0])}
    );

    // Functional maps decoder code 2 to output 1.
    check_functional_eq_code: assert property (
        @(posedge clk)
        (dec_out == 16'b0000000000000010) |-> (final_out == 4'b0001)
    );

    // Functional maps decoder code 4 to output 2.
    check_functional_gt_code: assert property (
        @(posedge clk)
        (dec_out == 16'b0000000000000100) |-> (final_out == 4'b0010)
    );

    // Functional maps decoder code 8 to output 4.
    check_functional_11_code: assert property (
        @(posedge clk)
        (dec_out == 16'b0000000000001000) |-> (final_out == 4'b0100)
    );

    // Functional drives zero for all other decoder values.
    check_functional_default_zero: assert property (
        @(posedge clk)
        (dec_out != 16'b0000000000000010 &&
         dec_out != 16'b0000000000000100 &&
         dec_out != 16'b0000000000001000) |-> (final_out == 4'b0000)
    );

    // Result is zero when enable is low.
    check_result_disabled_zero: assert property (
        @(posedge clk) !enable |-> (result == 4'b0000)
    );

    // Result follows final_out when enable is high.
    check_result_enabled_follows_final: assert property (
        @(posedge clk) enable |-> (result == final_out)
    );

    // Top-level result matches the implemented compare/decode/function chain.
    check_result_end_to_end: assert property (
        @(posedge clk)
        result == (enable ? ((A == B) ? 4'b0001 :
                             ((A > B) ? 4'b0010 : 4'b0000)) :
                            4'b0000)
    );

endmodule

rtl:
module twos_complement(
  input [3:0] in,
  output [3:0] out
);

  assign out = ~in + 1;

endmodule

sva:
module twos_complement_sva (
    input logic clk,
    input logic [3:0] in,
    input logic [3:0] out
);

    // RTL has no native clock or reset; clk is an external sampling clock.
    // The design is purely combinational: out is the 4-bit two's complement of in.

    // Output must equal bitwise inversion plus one.
    check_twos_complement_relation: assert property (
        @(posedge clk) out == ((~in) + 4'b0001)
    );

    // Input and output must sum to zero modulo 4 bits.
    check_additive_inverse: assert property (
        @(posedge clk) (in + out) == 4'b0000
    );

    // Zero must map to zero.
    check_zero_maps_to_zero: assert property (
        @(posedge clk) (in == 4'b0000) |-> (out == 4'b0000)
    );

    // The most negative 4-bit value must map to itself.
    check_most_negative_maps_to_self: assert property (
        @(posedge clk) (in == 4'b1000) |-> (out == 4'b1000)
    );

endmodule

