module my_inverter (
    Y   ,
    A   ,
    VPWR,
    VGND,
    VPB ,
    VNB
);

    output Y   ;
    input  A   ;
    input  VPWR;
    input  VGND;
    input  VPB ;
    input  VNB ;

    wire A_bar;

    assign A_bar = ~A;

    assign Y = A_bar;

endmodule

sva:
module my_inverter_sva (
    input logic clk,
    input logic Y,
    input logic A,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB
);

    // Y must always be the inverse of A.
    check_output_is_inverted_input: assert property (
        @(posedge clk) Y == ~A
    );

    // A high input must produce a low output.
    check_high_input_drives_low_output: assert property (
        @(posedge clk) A |-> !Y
    );

    // A low input must produce a high output.
    check_low_input_drives_high_output: assert property (
        @(posedge clk) !A |-> Y
    );

endmodule

module bin_to_gray_sva (
    input logic       clk,
    input logic       rst,
    input logic [3:0] bin,
    input logic [3:0] gray
);

    // Reset drives gray to zero on the following clock.
    check_reset_clears_gray: assert property (
        @(posedge clk) rst |=> (gray == 4'b0000)
    );

    // Gray matches the registered binary-to-Gray conversion.
    check_gray_matches_registered_conversion: assert property (
        @(posedge clk) disable iff (rst)
        1'b1 |=> (gray == ($past(bin) ^ ($past(bin) >> 1)))
    );

    // Gray[3] equals the previous binary MSB.
    check_gray_bit3: assert property (
        @(posedge clk) disable iff (rst)
        1'b1 |=> (gray[3] == $past(bin[3]))
    );

    // Gray[2] equals the previous bin[3] xor bin[2].
    check_gray_bit2: assert property (
        @(posedge clk) disable iff (rst)
        1'b1 |=> (gray[2] == ($past(bin[3]) ^ $past(bin[2])))
    );

    // Gray[1] equals the previous bin[2] xor bin[1].
    check_gray_bit1: assert property (
        @(posedge clk) disable iff (rst)
        1'b1 |=> (gray[1] == ($past(bin[2]) ^ $past(bin[1])))
    );

    // Gray[0] equals the previous bin[1] xor bin[0].
    check_gray_bit0: assert property (
        @(posedge clk) disable iff (rst)
        1'b1 |=> (gray[0] == ($past(bin[1]) ^ $past(bin[0])))
    );

endmodule

rtl:
module sky130_fd_sc_hd__xor2 (
    X,
    A,
    B
);

    output X;
    input  A;
    input  B;

    wire xor0_out_X;

    xor xor0 (xor0_out_X, B, A           );
    buf buf0 (X         , xor0_out_X     );

endmodule

sva:
module sky130_fd_sc_hd__xor2_sva (
    input logic X,
    input logic A,
    input logic B
);

    // RTL has no explicit clock or reset; logic is purely combinational.

    // X must always equal A XOR B.
    check_x_matches_xor: assert property (
        @($global_clock) (X === (A ^ B))
    );

    // 00 must produce 0.
    check_x_low_when_a0_b0: assert property (
        @($global_clock) ((A === 1'b0) && (B === 1'b0)) |-> (X === 1'b0)
    );

    // 01 must produce 1.
    check_x_high_when_a0_b1: assert property (
        @($global_clock) ((A === 1'b0) && (B === 1'b1)) |-> (X === 1'b1)
    );

    // 10 must produce 1.
    check_x_high_when_a1_b0: assert property (
        @($global_clock) ((A === 1'b1) && (B === 1'b0)) |-> (X === 1'b1)
    );

    // 11 must produce 0.
    check_x_low_when_a1_b1: assert property (
        @($global_clock) ((A === 1'b1) && (B === 1'b1)) |-> (X === 1'b0)
    );

endmodule

rtl:
module phase_accumulator #
(
    parameter WIDTH = 32,
    parameter INITIAL_PHASE = 0,
    parameter INITIAL_PHASE_STEP = 0
)
(
    input  wire             clk,
    input  wire             rst,


    input  wire [WIDTH-1:0] input_phase_tdata,
    input  wire             input_phase_tvalid,
    output wire             input_phase_tready,


    input  wire [WIDTH-1:0] input_phase_step_tdata,
    input  wire             input_phase_step_tvalid,
    output wire             input_phase_step_tready,


    output wire [WIDTH-1:0] output_phase_tdata,
    output wire             output_phase_tvalid,
    input  wire             output_phase_tready
);

reg [WIDTH-1:0] phase_reg = INITIAL_PHASE;
reg [WIDTH-1:0] phase_step_reg = INITIAL_PHASE_STEP;

assign input_phase_tready = output_phase_tready;
assign input_phase_step_tready = 1;
assign output_phase_tdata = phase_reg;
assign output_phase_tvalid = 1;

always @(posedge clk) begin
    if (rst) begin
        phase_reg <= INITIAL_PHASE;
        phase_step_reg <= INITIAL_PHASE_STEP;
    end else begin
        if (input_phase_tready & input_phase_tvalid) begin
            phase_reg <= input_phase_tdata;
        end else if (output_phase_tready) begin
            phase_reg <= phase_reg + phase_step_reg;
        end

        if (input_phase_step_tvalid) begin
            phase_step_reg <= input_phase_step_tdata;
        end
    end
end

endmodule

sva:
module phase_accumulator_sva #
(
    parameter WIDTH = 32,
    parameter [WIDTH-1:0] INITIAL_PHASE = 0,
    parameter [WIDTH-1:0] INITIAL_PHASE_STEP = 0
)
(
    input logic             clk,
    input logic             rst,

    input logic [WIDTH-1:0] input_phase_tdata,
    input logic             input_phase_tvalid,
    input logic             input_phase_tready,

    input logic [WIDTH-1:0] input_phase_step_tdata,
    input logic             input_phase_step_tvalid,
    input logic             input_phase_step_tready,

    input logic [WIDTH-1:0] output_phase_tdata,
    input logic             output_phase_tvalid,
    input logic             output_phase_tready
);

    // input_phase_tready is a direct mirror of output_phase_tready.
    check_input_phase_ready_mirrors_output_ready: assert property (
        @(posedge clk) disable iff (rst)
        (input_phase_tready == output_phase_tready)
    );

    // input_phase_step_tready is permanently asserted.
    check_input_phase_step_ready_constant: assert property (
        @(posedge clk) disable iff (rst)
        (input_phase_step_tready == 1'b1)
    );

    // output_phase_tvalid is permanently asserted.
    check_output_phase_valid_constant: assert property (
        @(posedge clk) disable iff (rst)
        (output_phase_tvalid == 1'b1)
    );

    // The constant handshake outputs also hold during reset.
    check_reset_constant_outputs: assert property (
        @(posedge clk)
        rst |-> ((input_phase_tready == output_phase_tready) &&
                 (input_phase_step_tready == 1'b1) &&
                 (output_phase_tvalid == 1'b1))
    );

    // Reset reloads the phase output to INITIAL_PHASE.
    check_reset_loads_initial_phase: assert property (
        @(posedge clk)
        rst |=> (output_phase_tdata == INITIAL_PHASE)
    );

    // A valid input phase handshake loads the next output phase.
    check_phase_load_on_input_handshake: assert property (
        @(posedge clk) disable iff (rst)
        (input_phase_tready && input_phase_tvalid)
        |=> (output_phase_tdata == $past(input_phase_tdata))
    );

    // Without a phase load or ready advance, the phase output holds.
    check_phase_holds_without_load_or_advance: assert property (
        @(posedge clk) disable iff (rst)
        (!(input_phase_tready && input_phase_tvalid) && !output_phase_tready)
        |=> (output_phase_tdata == $past(output_phase_tdata))
    );

    // After reset releases, the first eligible advance uses INITIAL_PHASE_STEP.
    check_reset_step_used_on_first_increment: assert property (
        @(posedge clk)
        rst ##1 (!rst && !(input_phase_tready && input_phase_tvalid) && output_phase_tready)
        |=> (output_phase_tdata == $past(output_phase_tdata) + INITIAL_PHASE_STEP)
    );

    // A written phase step is used by the next eligible advance.
    check_updated_step_used_on_next_increment: assert property (
        @(posedge clk) disable iff (rst)
        input_phase_step_tvalid ##1 (!(input_phase_tready && input_phase_tvalid) && output_phase_tready)
        |=> (output_phase_tdata == $past(output_phase_tdata) + $past(input_phase_step_tdata, 2))
    );

endmodule

rtl:
module pipelined_vector (
    input wire [2:0] vec,
    input wire clk,  // Added clock input
    output wire [2:0] outv,
    output wire o2,
    output wire o1,
    output wire o0
);

reg [2:0] stage1_out;
reg [2:0] stage2_out;
reg [2:0] stage3_out;

assign o2 = vec[2];
assign o1 = vec[1];
assign o0 = vec[0];

always @ (posedge clk) begin  // Corrected always block
    stage1_out <= vec;
end

always @ (posedge clk) begin  // Corrected always block
    stage2_out <= stage1_out;
end

always @ (posedge clk) begin  // Corrected always block
    stage3_out <= stage2_out;
end

assign outv = stage3_out;

endmodule

sva:
module pipelined_vector_sva (
    input logic [2:0] vec,
    input logic clk,
    input logic [2:0] outv,
    input logic o2,
    input logic o1,
    input logic o0,
    input logic [2:0] stage1_out,
    input logic [2:0] stage2_out,
    input logic [2:0] stage3_out
);

    // Direct outputs mirror the input vector bits.
    check_passthrough_bits: assert property (
        @(posedge clk) {o2, o1, o0} == vec
    );

    // First pipeline stage captures vec on each clock.
    check_stage1_captures_vec: assert property (
        @(posedge clk) disable iff ($initstate)
        stage1_out == $past(vec)
    );

    // Second pipeline stage captures the previous stage1 value.
    check_stage2_captures_stage1: assert property (
        @(posedge clk) disable iff ($initstate)
        stage2_out == $past(stage1_out)
    );

    // Third pipeline stage captures the previous stage2 value.
    check_stage3_captures_stage2: assert property (
        @(posedge clk) disable iff ($initstate)
        stage3_out == $past(stage2_out)
    );

    // outv is a direct copy of the third pipeline stage.
    check_outv_matches_stage3: assert property (
        @(posedge clk) outv == stage3_out
    );

    // outv is vec delayed by three clock cycles.
    check_outv_three_cycle_delay: assert property (
        @(posedge clk) disable iff ($initstate || $past($initstate) || $past($initstate,2))
        outv == $past(vec,3)
    );

endmodule

rtl:
module twos_comp (
    X,
    A
);

    // Module ports
    output reg [3:0] X;
    input [3:0] A;

    // Local signals
    wire [3:0] inv_A;
    wire [3:0] one = 4'b0001;

    // Invert all the bits of A
    assign inv_A = ~A;

    // Add 1 to the inverted number
    always @* begin
        X = inv_A + one;
    end

endmodule

sva:
module twos_comp_sva (
    input logic clk,
    input logic [3:0] X,
    input logic [3:0] A
);

    // Sampling clock only; the RTL itself has no clock or reset.

    // X must equal bitwise inversion of A plus 1.
    check_twos_comp_definition: assert property (
        @(posedge clk) X == ((~A) + 4'b0001)
    );

    // Taking two's complement of X must recover A.
    check_reverse_twos_comp_definition: assert property (
        @(posedge clk) A == ((~X) + 4'b0001)
    );

    // A and X must sum to zero modulo 16.
    check_additive_inverse: assert property (
        @(posedge clk) (A + X) == 4'b0000
    );

    // Zero must map to zero.
    check_zero_maps_to_zero: assert property (
        @(posedge clk) (A == 4'b0000) |-> (X == 4'b0000)
    );

    // 4'b1000 must map to itself.
    check_min_negative_self_inverse: assert property (
        @(posedge clk) (A == 4'b1000) |-> (X == 4'b1000)
    );

    // Only 0 and 8 may equal their own two's complement.
    check_only_self_inverse_values: assert property (
        @(posedge clk) (A == X) |-> ((A == 4'b0000) || (A == 4'b1000))
    );

endmodule

module counter_sva (
    input logic        clk,
    input logic        rst,
    input logic        en,
    input logic [31:0] count_to,
    input logic [31:0] count
);

    // On the first cycle after reset, count is zero.
    check_count_zero_after_reset_cycle: assert property (
        @(posedge clk) disable iff (rst)
        (!$initstate && $past(rst)) |-> (count == 32'd0)
    );

    // When enable is low, count holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (rst)
        (!en) |=> (count == $past(count))
    );

    // When enabled below count_to, count increments by one.
    check_increment_when_enabled_below_limit: assert property (
        @(posedge clk) disable iff (rst)
        (en && (count != count_to)) |=> (count == ($past(count) + 32'd1))
    );

    // When enabled at count_to, count wraps to zero.
    check_wrap_to_zero_at_limit: assert property (
        @(posedge clk) disable iff (rst)
        (en && (count == count_to)) |=> (count == 32'd0)
    );

    // Any non-reset count change must come from an enabled prior cycle.
    check_change_requires_enable: assert property (
        @(posedge clk) disable iff (rst)
        (!$initstate && !$past(rst) && (count != $past(count))) |-> $past(en)
    );

    // Every non-reset transition follows the RTL update rules.
    check_nonreset_transition_matches_rtl: assert property (
        @(posedge clk) disable iff (rst)
        (!$initstate && !$past(rst)) |-> (
            ((!$past(en)) && (count == $past(count))) ||
            ($past(en) && ($past(count) == $past(count_to)) && (count == 32'd0)) ||
            ($past(en) && ($past(count) != $past(count_to)) && (count == ($past(count) + 32'd1)))
        )
    );

endmodule

rtl:
module even_parity_checker(
    input D0, D1, D2, D3, RST, ECLK, DQSW,
    output reg Q
);

    reg [3:0] data_reg;

    always @(posedge ECLK) begin
        if (RST) begin
            Q <= 1'b0;
            data_reg <= 4'b0;
        end
        else if (!DQSW) begin
            data_reg <= {data_reg[2:0], D3};
        end
        else begin
            Q <= ~^data_reg;
            data_reg <= {D3, D2, D1, D0};
        end
    end

endmodule

sva:
module even_parity_checker_assertions (
    input logic D0,
    input logic D1,
    input logic D2,
    input logic D3,
    input logic RST,
    input logic ECLK,
    input logic DQSW,
    input logic Q,
    input logic [3:0] data_reg
);

    // After reset is released, Q reflects the reset value.
    check_reset_state_after_release_q: assert property (
        @(posedge ECLK) disable iff (RST)
        !$initstate && $past(RST) |-> (Q == 1'b0)
    );

    // After reset is released, data_reg reflects the reset value.
    check_reset_state_after_release_data_reg: assert property (
        @(posedge ECLK) disable iff (RST)
        !$initstate && $past(RST) |-> (data_reg == 4'b0000)
    );

    // In shift mode, Q holds its previous value.
    check_shift_mode_holds_q: assert property (
        @(posedge ECLK) disable iff (RST)
        !DQSW |=> (Q == $past(Q))
    );

    // In shift mode, data_reg shifts and captures D3 into bit 0.
    check_shift_mode_updates_data_reg: assert property (
        @(posedge ECLK) disable iff (RST)
        !DQSW |=> (data_reg == { $past(data_reg[2:0]), $past(D3) })
    );

    // In load mode, Q becomes the even parity of the previous data_reg.
    check_load_mode_updates_q: assert property (
        @(posedge ECLK) disable iff (RST)
        DQSW |=> (Q == ~^$past(data_reg))
    );

    // In load mode, data_reg captures D3:D0 in order.
    check_load_mode_updates_data_reg: assert property (
        @(posedge ECLK) disable iff (RST)
        DQSW |=> (data_reg == { $past(D3), $past(D2), $past(D1), $past(D0) })
    );

    // Q can only change after a reset cycle or a load-mode cycle.
    check_q_changes_only_on_reset_or_load: assert property (
        @(posedge ECLK) disable iff (RST)
        !$initstate && (Q != $past(Q)) |-> ($past(RST) || $past(DQSW))
    );

endmodule

rtl:
module spw_babasu_DATA_I (
    // inputs:
    address,
    chipselect,
    clk,
    reset_n,
    write_n,
    writedata,

    // outputs:
    out_port,
    readdata
);

    output  [8:0] out_port;
    output  [31:0] readdata;
    input   [1:0] address;
    input   chipselect;
    input   clk;
    input   reset_n;
    input   write_n;
    input   [31:0] writedata;

    wire             clk_en;
    reg     [8:0] data_out;
    wire    [8:0] out_port;
    wire    [8:0] read_mux_out;
    wire    [31:0] readdata;

    assign clk_en = 1;
    assign read_mux_out = {9 {address == 0}} & data_out;

    always @(posedge clk or negedge reset_n) begin
        if (~reset_n) begin
            data_out <= 0;
        end else if (chipselect && ~write_n && (address == 0)) begin
            data_out <= writedata[8:0];
        end
    end

    assign readdata = {32'b0 | read_mux_out};
    assign out_port = data_out;

endmodule

sva:
module spw_babasu_DATA_I_sva (
    input logic [1:0]  address,
    input logic        chipselect,
    input logic        clk,
    input logic        reset_n,
    input logic        write_n,
    input logic [31:0] writedata,
    input logic [8:0]  out_port,
    input logic [31:0] readdata
);

    // Active-low reset clears the stored output value.
    reset_clears_out_port: assert property (
        @(posedge clk) !reset_n |-> (out_port == 9'b0)
    );

    // Active-low reset forces read data low.
    reset_clears_readdata: assert property (
        @(posedge clk) !reset_n |-> (readdata == 32'b0)
    );

    // A write to address 0 updates out_port with writedata[8:0] on the next cycle.
    write_addr0_updates_out_port: assert property (
        @(posedge clk) disable iff (!reset_n)
        (chipselect && !write_n && (address == 2'b00)) |=> (out_port == $past(writedata[8:0]))
    );

    // Without a write to address 0, out_port holds its value.
    no_write_addr0_holds_out_port: assert property (
        @(posedge clk) disable iff (!reset_n)
        !(chipselect && !write_n && (address == 2'b00)) |=> $stable(out_port)
    );

    // Address 0 reads back the stored value zero-extended to 32 bits.
    read_addr0_returns_out_port: assert property (
        @(posedge clk) disable iff (!reset_n)
        (address == 2'b00) |-> (readdata == {23'b0, out_port})
    );

    // Nonzero addresses read as zero.
    read_other_addresses_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (address != 2'b00) |-> (readdata == 32'b0)
    );

endmodule

rtl:
module binary_counter(
  input clk,
  input reset,
  output reg [3:0] count
);

reg [3:0] temp_count;

always @ (posedge clk or negedge reset) begin
  if (!reset) begin
    temp_count <= 4'b0000;
  end else begin
    temp_count <= temp_count + 4'b0001;
  end
end

always @*
  count = temp_count;

endmodule

sva:
module binary_counter_sva (
    input logic       clk,
    input logic       reset,
    input logic [3:0] count
);

    // Count is zero whenever reset is asserted low.
    check_reset_clears_count: assert property (
        @(posedge clk) !reset |-> (count == 4'b0000)
    );

    // The first sampled cycle after reset release still shows zero.
    check_post_reset_starts_at_zero: assert property (
        @(posedge clk) disable iff (!reset)
        ($past(reset) === 1'b0) |-> (count == 4'b0000)
    );

    // On consecutive enabled cycles, count increments by one.
    check_count_increments: assert property (
        @(posedge clk) disable iff (!reset)
        ($past(reset) === 1'b1) |-> (count == ($past(count) + 4'b0001))
    );

    // The 4-bit counter wraps from 15 back to 0.
    check_count_wraps: assert property (
        @(posedge clk) disable iff (!reset)
        (($past(reset) === 1'b1) && ($past(count) == 4'hF)) |-> (count == 4'h0)
    );

endmodule

rtl:
module nand_gate (
    input A,
    input B,
    output X
);

    assign X = ~(A & B);

endmodule
module or_gate (
    input A,
    input B,
    output X
);

    assign X = A | B;

endmodule
module not_gate (
    input A,
    output X
);

    assign X = ~A;

endmodule
module nand_or (
    input A,
    input B,
    input C,
    input D,
    output X
);

    wire nand1;
    wire nand2;
    wire or1;

    nand_gate nand_gate1 (
        .A(A),
        .B(B),
        .X(nand1)
    );

    nand_gate nand_gate2 (
        .A(nand1),
        .B(C),
        .X(nand2)
    );

    or_gate or_gate1 (
        .A(A),
        .B(B),
        .X(or1)
    );

    nand_gate nand_gate3 (
        .A(or1),
        .B(nand2),
        .X(X)
    );

endmodule

sva:
module nand_or_assertions (
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic X
);

    // No clock or reset exists in the RTL; sample on the formal global clock.

    // X must match the gate-level logic implemented in the RTL.
    check_structural_function: assert property (
        @($global_clock) disable iff (1'b0)
        X == ~((A | B) & ~(~(A & B) & C))
    );

    // When C is low, the logic reduces to NOR(A,B).
    check_c_low_nor_behavior: assert property (
        @($global_clock) disable iff (1'b0)
        (!C) |-> (X == ~(A | B))
    );

    // When C is high, the logic reduces to NAND(A,B).
    check_c_high_nand_behavior: assert property (
        @($global_clock) disable iff (1'b0)
        C |-> (X == ~(A & B))
    );

    // If both A and B are low, the output must be high.
    check_ab_both_low_sets_x_high: assert property (
        @($global_clock) disable iff (1'b0)
        (!A && !B) |-> (X == 1'b1)
    );

    // If both A and B are high, the output must be low.
    check_ab_both_high_sets_x_low: assert property (
        @($global_clock) disable iff (1'b0)
        (A && B) |-> (X == 1'b0)
    );

    // If A and B differ, the output must follow C.
    check_ab_different_x_matches_c: assert property (
        @($global_clock) disable iff (1'b0)
        (A ^ B) |-> (X == C)
    );

    // Holding A, B, and C constant must hold X constant, so D has no effect.
    check_output_depends_only_on_abc: assert property (
        @($global_clock) disable iff (1'b0)
        (!$initstate && $stable(A) && $stable(B) && $stable(C)) |-> $stable(X)
    );

endmodule

rtl:
module decoder_2to4_priority (
    input A, B,
    output reg [3:0] Y
);

    always @* begin
        if (A == 1 && B == 0) begin
            Y = 4'b0001;
        end else if (A == 0 && B == 1) begin
            Y = 4'b0010;
        end else if (A == 1 && B == 1) begin
            Y = 4'b0011;
        end else begin
            Y = 4'b0000;
        end
    end

endmodule

