rtl:
module parity_generator_checker #(
  parameter parity_type = "even" // even or odd parity
)
(
  input wire [7:0] data_in,
  input wire parity_in,
  output reg parity_out,
  output reg correct
);

  reg [7:0] temp_data;
  reg [3:0] count;
  reg parity_bit;

  always @(*) begin
    temp_data = data_in ^ (data_in >> 4);
    temp_data = temp_data ^ (temp_data >> 2);
    temp_data = temp_data ^ (temp_data >> 1);
    parity_bit = temp_data[0];

    if (parity_type == "even") begin
      parity_out <= parity_bit;
    end else begin
      parity_out <= ~parity_bit;
    end
  end

  always @(*) begin
    count = data_in[0] + data_in[1] + data_in[2] + data_in[3] + data_in[4] + data_in[5] + data_in[6] + data_in[7] + parity_in;

    if (parity_type == "even") begin
      correct <= (count % 2 == 0);
    end else begin
      correct <= (count % 2 == 1);
    end
  end

endmodule

sva:
module parity_generator_checker_sva #(
    parameter string parity_type = "even"
)(
    input logic clk,
    input logic [7:0] data_in,
    input logic parity_in,
    input logic parity_out,
    input logic correct
);

    localparam bit EVEN_MODE = (parity_type == "even");

    generate
        if (EVEN_MODE) begin : gen_even_asserts
            // Even mode outputs the reduction XOR of data_in.
            check_even_parity_out: assert property (
                @(posedge clk) parity_out == (^data_in)
            );

            // Even mode makes data_in and parity_out have even total parity.
            check_even_generated_total_parity: assert property (
                @(posedge clk) (^({data_in, parity_out})) == 1'b0
            );

            // Even mode accepts only even total received parity.
            check_even_correct_flag: assert property (
                @(posedge clk) correct == ~(^({data_in, parity_in}))
            );
        end else begin : gen_odd_asserts
            // Odd mode outputs the inverse of the data reduction XOR.
            check_odd_parity_out: assert property (
                @(posedge clk) parity_out == ~(^data_in)
            );

            // Odd mode makes data_in and parity_out have odd total parity.
            check_odd_generated_total_parity: assert property (
                @(posedge clk) (^({data_in, parity_out})) == 1'b1
            );

            // Odd mode accepts only odd total received parity.
            check_odd_correct_flag: assert property (
                @(posedge clk) correct == (^({data_in, parity_in}))
            );
        end
    endgenerate

    // Matching received and generated parity must be accepted.
    check_accept_matching_parity: assert property (
        @(posedge clk) (parity_in == parity_out) |-> correct
    );

    // Mismatched received and generated parity must be rejected.
    check_reject_mismatched_parity: assert property (
        @(posedge clk) (parity_in != parity_out) |-> !correct
    );

endmodule

rtl:
module math_op (
    A,
    B,
    C,
    X
);

    input A;
    input B;
    input C;
    output X;

    // Signals
    wire A_lt_B;
    wire A_gt_B;
    wire A_eq_B;
    wire A_times_C;
    wire B_plus_C;
    wire A_and_B;

    // Comparator
    assign A_lt_B = (A < B);
    assign A_gt_B = (A > B);
    assign A_eq_B = (A == B);

    // Operations
    assign A_times_C = A_lt_B ? (A & C) : 1'b0;
    assign B_plus_C = A_gt_B ? (B | C) : 1'b0;
    assign A_and_B = A_eq_B ? (A & B) : 1'b0;

    // Output
    assign X = A_times_C | B_plus_C | A_and_B;

endmodule

sva:
module math_op_assertions (
    input logic clk,
    input logic A,
    input logic B,
    input logic C,
    input logic X
);

    // Output must match the implemented combinational function.
    check_output_boolean_form: assert property (
        @(posedge clk) X == (A & (B | C))
    );

    // When A<B for 1-bit inputs, the output must be zero.
    check_lt_branch_forces_zero: assert property (
        @(posedge clk) (!A && B) |-> (X == 1'b0)
    );

    // When A>B for 1-bit inputs, the output must match C.
    check_gt_branch_matches_c: assert property (
        @(posedge clk) (A && !B) |-> (X == C)
    );

    // When A and B are both zero, the equality branch drives zero.
    check_eq_low_branch_forces_zero: assert property (
        @(posedge clk) (!A && !B) |-> (X == 1'b0)
    );

    // When A and B are both one, the equality branch drives one.
    check_eq_high_branch_sets_one: assert property (
        @(posedge clk) (A && B) |-> (X == 1'b1)
    );

endmodule

module binary_counter_sva(
    input logic clk,
    input logic rst,
    input logic [3:0] count
);

    // A reset seen on one clock leaves count at zero on the next clock.
    check_reset_drives_zero: assert property (
        @(posedge clk) disable iff ($initstate)
        $past(rst) |-> (count == 4'h0)
    );

    // A sampled 15 wraps to zero on the following clock when reset was low.
    check_wrap_from_fifteen: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        (!$past(rst) && ($past(count) == 4'hF)) |-> (count == 4'h0)
    );

    // Counts below 15 either increment or get cleared by an async reset pulse.
    check_increment_or_async_clear: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        (!$past(rst) && ($past(count) != 4'hF)) |-> ((count == 4'h0) || (count == ($past(count) + 4'h1)))
    );

    // Any nonzero count must come from the previous value plus one.
    check_nonzero_has_linear_predecessor: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        (count != 4'h0) |-> (!$past(rst) && ($past(count) == (count - 4'h1)))
    );

endmodule

rtl:
module ao22 (
  q,
  i0,
  i1,
  i2,
  i3
);
  output q;
  input i0;
  input i1;
  input i2;
  input i3;

  wire [1:0] int_0n;

  // AND gate for int_0n[0]
  and I0 (int_0n[0], i0, i1);

  // AND gate for int_0n[1]
  and I1 (int_0n[1], i2, i3);

  // OR gate for q
  or I2 (q, int_0n[0], int_0n[1]);
endmodule

sva:
module ao22_assertions (
    input logic clk,
    input logic q,
    input logic i0,
    input logic i1,
    input logic i2,
    input logic i3
);

    // q matches the AO22 combinational equation.
    check_q_matches_ao22_equation: assert property (
        @(posedge clk) q == ((i0 & i1) | (i2 & i3))
    );

    // The first AND term forces q high.
    check_first_and_term_forces_q_high: assert property (
        @(posedge clk) (i0 & i1) |-> q
    );

    // The second AND term forces q high.
    check_second_and_term_forces_q_high: assert property (
        @(posedge clk) (i2 & i3) |-> q
    );

    // q is low when both AND terms are low.
    check_no_and_terms_means_q_low: assert property (
        @(posedge clk) (!(i0 & i1) && !(i2 & i3)) |-> !q
    );

    // If q is high without the first term, the second term must be high.
    check_q_high_without_first_term_needs_second: assert property (
        @(posedge clk) (q && !(i0 & i1)) |-> (i2 & i3)
    );

    // If q is high without the second term, the first term must be high.
    check_q_high_without_second_term_needs_first: assert property (
        @(posedge clk) (q && !(i2 & i3)) |-> (i0 & i1)
    );

    // A low q implies the first AND term is low.
    check_q_low_implies_first_term_low: assert property (
        @(posedge clk) !q |-> !(i0 & i1)
    );

    // A low q implies the second AND term is low.
    check_q_low_implies_second_term_low: assert property (
        @(posedge clk) !q |-> !(i2 & i3)
    );

endmodule

rtl:
module binary_up_down_counter (
  input clk,
  input reset,
  input up_down,
  input clear,
  input load,
  input [3:0] data_in,
  output reg [3:0] count
);

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      count <= 4'b0;
    end else if (clear) begin
      count <= 4'b0;
    end else if (load) begin
      count <= data_in;
    end else if (up_down) begin
      count <= count + 1;
    end else begin
      count <= count - 1;
    end
  end

endmodule

sva:
module binary_up_down_counter_sva (
    input logic       clk,
    input logic       reset,
    input logic       up_down,
    input logic       clear,
    input logic       load,
    input logic [3:0] data_in,
    input logic [3:0] count
);

    // After reset deasserts, count remains zero until the next clocked update.
    check_post_reset_zero: assert property (
        @(posedge clk) disable iff (reset)
        $fell(reset) |-> (count == 4'b0000)
    );

    // Clear has highest priority and forces count to zero.
    check_clear_forces_zero: assert property (
        @(posedge clk) disable iff (reset)
        clear |=> (count == 4'b0000)
    );

    // Load updates count from data_in when clear is low.
    check_load_updates_count: assert property (
        @(posedge clk) disable iff (reset)
        (!clear && load) |=> (count == $past(data_in))
    );

    // Count increments when clear and load are low and up_down is high.
    check_increment_behavior: assert property (
        @(posedge clk) disable iff (reset)
        (!clear && !load && up_down) |=> (count == ($past(count) + 4'd1))
    );

    // Count decrements when clear and load are low and up_down is low.
    check_decrement_behavior: assert property (
        @(posedge clk) disable iff (reset)
        (!clear && !load && !up_down) |=> (count == ($past(count) - 4'd1))
    );

endmodule

