sva:
module sky130_fd_sc_lp__a221oi_sva (
    input logic clk,
    input logic Y,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic B2,
    input logic C1
);

    // Y matches the implemented NOR of C1 and the two AND terms.
    check_y_matches_logic: assert property (
        @(posedge clk) Y == ~((B1 & B2) | C1 | (A1 & A2))
    );

    // C1 high forces the output low.
    check_c1_forces_y_low: assert property (
        @(posedge clk) C1 |-> (Y == 1'b0)
    );

    // A1 and A2 high force the output low.
    check_a_pair_forces_y_low: assert property (
        @(posedge clk) (A1 & A2) |-> (Y == 1'b0)
    );

    // B1 and B2 high force the output low.
    check_b_pair_forces_y_low: assert property (
        @(posedge clk) (B1 & B2) |-> (Y == 1'b0)
    );

    // With all NOR inputs inactive, the output is high.
    check_all_terms_inactive_drive_y_high: assert property (
        @(posedge clk) (!C1 && !(A1 & A2) && !(B1 & B2)) |-> (Y == 1'b1)
    );

    // A high output implies none of the three NOR inputs is active.
    check_y_high_implies_all_terms_inactive: assert property (
        @(posedge clk) Y |-> (!C1 && !(A1 & A2) && !(B1 & B2))
    );

endmodule

rtl:
module decoderparam
	# (parameter WIDTH = 4)
	( output reg [2**WIDTH-1 : 0] code,
	  input [WIDTH-1 : 0] a,
	  input clken
    );

	localparam STAGE = WIDTH;

	integer i, s, r;

	reg [(STAGE+1)*(2**STAGE):0] p;

	always @(a, p, clken) begin

		p[STAGE*(2**STAGE)] <= clken;

		for(s=STAGE; s > 0; s = s - 1) begin
			for (r = 0; r < 2**(STAGE - s); r = r + 1) begin
				p[(s-1)*(2**STAGE) + 2*r]  <= !a[s-1] && p[s*(2**STAGE)+r];
				p[(s-1)*(2**STAGE) + 2*r+1]  <= a[s-1] && p[s*(2**STAGE)+r];
			end
		end

		for (i=0; i < 2**STAGE; i = i + 1) begin
			code[i] <= p[i]; 
		end
	end

endmodule

sva:
module decoderparam_sva
#(parameter int WIDTH = 4)
(
    input logic clk,
    input logic [(1<<WIDTH)-1:0] code,
    input logic [WIDTH-1:0] a,
    input logic clken
);

    localparam int OUTW = (1 << WIDTH);
    localparam logic [OUTW-1:0] DECODE_BASE = {{(OUTW-1){1'b0}}, 1'b1};
    localparam logic [OUTW-1:0] ZERO_VEC    = '0;

    // Output must equal the enabled one-hot decode of the address.
    check_code_matches_decode: assert property (
        @(posedge clk) code == (clken ? (DECODE_BASE << a) : ZERO_VEC)
    );

    // When disabled, all output bits must be low.
    check_disable_clears_code: assert property (
        @(posedge clk) !clken |-> (code == ZERO_VEC)
    );

    // The output must always be either all-zero or one-hot.
    check_code_is_onehot0: assert property (
        @(posedge clk) $onehot0(code)
    );

    genvar gi;
    generate
        for (gi = 0; gi < OUTW; gi = gi + 1) begin : gen_output_checks
            // Any asserted output bit must match the address and enable.
            check_output_bit_implies_address: assert property (
                @(posedge clk) code[gi] |-> (clken && (a == gi))
            );
        end
    endgenerate

endmodule

