module sky130_fd_sc_hdll__o32ai_sva (
    input logic clk,
    input logic Y,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic B1,
    input logic B2
);

    // External sampling clock; the DUT RTL is combinational and has no reset.

    // Y matches the OR of the two NOR terms.
    check_y_matches_or_of_nors: assert property (
        @(posedge clk) Y == ((~(A3 | A1 | A2)) | (~(B1 | B2)))
    );

    // If the A-group inputs are all low, Y must be high.
    check_a_group_all_low_forces_y_high: assert property (
        @(posedge clk) (!(A3 | A1 | A2)) |-> Y
    );

    // If the B-group inputs are all low, Y must be high.
    check_b_group_all_low_forces_y_high: assert property (
        @(posedge clk) (!(B1 | B2)) |-> Y
    );

    // If both input groups are active, Y must be low.
    check_both_groups_active_force_y_low: assert property (
        @(posedge clk) ((A3 | A1 | A2) && (B1 | B2)) |-> !Y
    );

    // A low Y requires at least one A-group input high.
    check_y_low_implies_a_group_active: assert property (
        @(posedge clk) (!Y) |-> (A3 | A1 | A2)
    );

    // A low Y requires at least one B-group input high.
    check_y_low_implies_b_group_active: assert property (
        @(posedge clk) (!Y) |-> (B1 | B2)
    );

    // If Y is high while the A-group is active, the B-group must be all low.
    check_y_high_with_a_group_active_implies_b_group_low: assert property (
        @(posedge clk) (Y && (A3 | A1 | A2)) |-> !(B1 | B2)
    );

    // If Y is high while the B-group is active, the A-group must be all low.
    check_y_high_with_b_group_active_implies_a_group_low: assert property (
        @(posedge clk) (Y && (B1 | B2)) |-> !(A3 | A1 | A2)
    );

endmodule

module SUB_sva (
    input logic [15:0] a,
    input logic [15:0] b,
    input logic [15:0] sub,
    input logic carry,
    input logic overflow
);

    // sub always reflects the 16-bit result of a - b.
    check_sub_matches_difference: assert property (
        @($global_clock) disable iff (1'b0)
        sub == (a - b)
    );

    // carry is high exactly when a is less than b.
    check_carry_matches_less_than: assert property (
        @($global_clock) disable iff (1'b0)
        carry == (a < b)
    );

    // overflow matches the implemented sign-comparison logic.
    check_overflow_matches_rtl_expression: assert property (
        @($global_clock) disable iff (1'b0)
        overflow == ((sub[15] != a[15]) && (sub[15] != b[15]))
    );

    // A borrow condition drives carry high.
    check_carry_high_on_borrow: assert property (
        @($global_clock) disable iff (1'b0)
        (a < b) |-> carry
    );

    // No borrow condition drives carry low.
    check_carry_low_without_borrow: assert property (
        @($global_clock) disable iff (1'b0)
        (a >= b) |-> !carry
    );

    // Equal operands produce zero and no carry.
    check_equal_inputs_zero_result: assert property (
        @($global_clock) disable iff (1'b0)
        (a == b) |-> (sub == 16'h0000 && !carry)
    );

    // Subtracting zero passes a through with no carry or overflow.
    check_zero_b_passthrough: assert property (
        @($global_clock) disable iff (1'b0)
        (b == 16'h0000) |-> (sub == a && !carry && !overflow)
    );

    // Matching sub and a sign forces overflow low.
    check_overflow_low_when_sub_sign_matches_a: assert property (
        @($global_clock) disable iff (1'b0)
        (sub[15] == a[15]) |-> !overflow
    );

    // Matching sub and b sign forces overflow low.
    check_overflow_low_when_sub_sign_matches_b: assert property (
        @($global_clock) disable iff (1'b0)
        (sub[15] == b[15]) |-> !overflow
    );

endmodule

