module mux_3to1_with_outputs (
    input wire [2:0] in_vec,
    input wire sel,
    output wire [2:0] out_vec,
    output wire o2,
    output wire o1,
    output wire o0
);

wire [2:0] mux_out;
wire in_0, in_1, in_2;

assign in_0 = in_vec[0];
assign in_1 = in_vec[1];
assign in_2 = in_vec[2];

assign o0 = in_0;
assign o1 = in_1;
assign o2 = in_2;

assign mux_out = sel ? in_vec[2:1] : in_vec[1:0];

assign out_vec[0] = mux_out[0] | in_0;
assign out_vec[1] = mux_out[1] | in_1;
assign out_vec[2] = mux_out[2] | in_2;

endmodule

sva:
module mux_3to1_with_outputs_sva (
    input logic [2:0] in_vec,
    input logic sel,
    input logic [2:0] out_vec,
    input logic o2,
    input logic o1,
    input logic o0,
    input logic clk
);

    // No RTL clock or reset; clk is only for assertion sampling.

    // o0 directly reflects in_vec[0].
    check_o0_pass_through: assert property (
        @(posedge clk) o0 == in_vec[0]
    );

    // o1 directly reflects in_vec[1].
    check_o1_pass_through: assert property (
        @(posedge clk) o1 == in_vec[1]
    );

    // o2 directly reflects in_vec[2].
    check_o2_pass_through: assert property (
        @(posedge clk) o2 == in_vec[2]
    );

    // With sel low, out_vec matches in_vec.
    check_out_vec_sel_low: assert property (
        @(posedge clk) !sel |-> (out_vec == in_vec)
    );

    // With sel high, out_vec preserves bit 2 and ORs adjacent lower bits.
    check_out_vec_sel_high: assert property (
        @(posedge clk) sel |-> (out_vec == {in_vec[2], (in_vec[2] | in_vec[1]), (in_vec[1] | in_vec[0])})
    );

endmodule

rtl:
module priority_encoder_4to2 (
    input [3:0] I,
    input clk,
    output reg [1:0] Y
);

reg [1:0] stage1_out;
reg [1:0] stage2_out;

always @ (posedge clk) begin
    stage1_out <= {I[1], I[0]};
    stage2_out <= {I[3], I[2]};
end

always @ (posedge clk) begin
    if (stage1_out[1] == 1'b1) begin
        Y <= stage1_out;
    end else if (stage2_out[1] == 1'b1) begin
        Y <= stage2_out;
    end else begin
        Y <= 2'b00;
    end
end

endmodule

sva:
module priority_encoder_4to2_sva (
    input logic [3:0] I,
    input logic clk,
    input logic [1:0] Y
);

    // Y reflects the previous cycle's selected input pair.
    check_output_from_prev_inputs: assert property (
        @(posedge clk)
        1'b1 |=> (Y == ($past(I[1]) ? {1'b1, $past(I[0])} :
                      ($past(I[3]) ? {1'b1, $past(I[2])} : 2'b00)))
    );

    // The lower input pair is selected whenever its valid bit is high.
    check_lower_pair_selected: assert property (
        @(posedge clk)
        (I[1] == 1'b1) |=> (Y == {1'b1, $past(I[0])})
    );

    // The upper input pair is selected when the lower pair is invalid.
    check_upper_pair_selected: assert property (
        @(posedge clk)
        ((I[1] == 1'b0) && (I[3] == 1'b1)) |=> (Y == {1'b1, $past(I[2])})
    );

    // The output clears when neither input pair is valid.
    check_zero_when_no_valid_pair: assert property (
        @(posedge clk)
        ((I[1] == 1'b0) && (I[3] == 1'b0)) |=> (Y == 2'b00)
    );

    // When both pairs are valid, the lower pair has priority.
    check_lower_pair_priority: assert property (
        @(posedge clk)
        ((I[1] == 1'b1) && (I[3] == 1'b1)) |=> (Y == {1'b1, $past(I[0])})
    );

    // Y[1] shows whether either pair was valid in the previous cycle.
    check_output_msb_valid: assert property (
        @(posedge clk)
        1'b1 |=> (Y[1] == ($past(I[1]) | $past(I[3])))
    );

    // Y[0] comes from the previously selected pair.
    check_output_lsb_source: assert property (
        @(posedge clk)
        1'b1 |=> (Y[0] == ($past(I[1]) ? $past(I[0]) :
                          ($past(I[3]) ? $past(I[2]) : 1'b0)))
    );

endmodule

module my_and3_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic C,
    input logic X,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB
);

    // X implements A & B & C.
    check_x_matches_and3: assert property (
        @(posedge clk) X == (A & B & C)
    );

    // A low forces X low.
    check_a_low_forces_x_low: assert property (
        @(posedge clk) !A |-> !X
    );

    // B low forces X low.
    check_b_low_forces_x_low: assert property (
        @(posedge clk) !B |-> !X
    );

    // C low forces X low.
    check_c_low_forces_x_low: assert property (
        @(posedge clk) !C |-> !X
    );

    // All three inputs high drive X high.
    check_all_inputs_high_drive_x_high: assert property (
        @(posedge clk) (A & B & C) |-> X
    );

    // X high requires all three inputs high.
    check_x_high_requires_all_inputs_high: assert property (
        @(posedge clk) X |-> (A & B & C)
    );

    // With B and C high, X follows A.
    check_x_follows_a_when_bc_high: assert property (
        @(posedge clk) (B & C) |-> (X == A)
    );

    // With A and C high, X follows B.
    check_x_follows_b_when_ac_high: assert property (
        @(posedge clk) (A & C) |-> (X == B)
    );

    // With A and B high, X follows C.
    check_x_follows_c_when_ab_high: assert property (
        @(posedge clk) (A & B) |-> (X == C)
    );

endmodule

rtl:
module top_module(
    input [3:0] in0,
    input [3:0] in1,
    input [3:0] in2,
    input [3:0] in3,
    input [1:0] sel,
    input       reset,
    output reg  [3:0] out_assign,
    output reg  [3:0] out_alwaysblock
);

wire [3:0] mux1_out, mux2_out;

assign mux1_out = (sel[0] == 1'b0) ? in0 : in1;
assign mux2_out = (sel[0] == 1'b0) ? in2 : in3;

always @(*) begin
    case (sel[1])
        1'b0: out_alwaysblock = mux1_out;
        1'b1: out_alwaysblock = mux2_out;
        default: out_alwaysblock = 4'b0;
    endcase
end

always @(posedge reset) begin
    if (reset) begin
        out_assign <= 4'b0;
    end else begin
        case (sel)
            2'b00: out_assign <= in0;
            2'b01: out_assign <= in1;
            2'b10: out_assign <= in2;
            2'b11: out_assign <= in3;
            default: out_assign <= 4'b0;
        endcase
    end
end

endmodule

sva:
module top_module_sva (
    input logic [3:0] in0,
    input logic [3:0] in1,
    input logic [3:0] in2,
    input logic [3:0] in3,
    input logic [1:0] sel,
    input logic       reset,
    input logic [3:0] out_assign,
    input logic [3:0] out_alwaysblock
);

    // reset is active high and is the only edge-triggered signal.
    // out_alwaysblock is combinational; out_assign only updates on posedge reset.

    // out_alwaysblock selects in0 when sel is 2'b00.
    check_out_alwaysblock_sel_00: assert property (
        @(negedge reset) disable iff (reset)
        (sel === 2'b00) |-> (out_alwaysblock == in0)
    );

    // out_alwaysblock selects in1 when sel is 2'b01.
    check_out_alwaysblock_sel_01: assert property (
        @(negedge reset) disable iff (reset)
        (sel === 2'b01) |-> (out_alwaysblock == in1)
    );

    // out_alwaysblock selects in2 when sel is 2'b10.
    check_out_alwaysblock_sel_10: assert property (
        @(negedge reset) disable iff (reset)
        (sel === 2'b10) |-> (out_alwaysblock == in2)
    );

    // out_alwaysblock selects in3 when sel is 2'b11.
    check_out_alwaysblock_sel_11: assert property (
        @(negedge reset) disable iff (reset)
        (sel === 2'b11) |-> (out_alwaysblock == in3)
    );

    // out_alwaysblock drives zero on the case default branch.
    check_out_alwaysblock_default: assert property (
        @(negedge reset) disable iff (reset)
        ((sel[1] !== 1'b0) && (sel[1] !== 1'b1)) |-> (out_alwaysblock == 4'b0000)
    );

    // After a prior reset assertion, out_assign is cleared to zero.
    check_out_assign_cleared_by_reset: assert property (
        @(negedge reset) disable iff (reset)
        !$isunknown($past(reset, 1, 1'b1, @(posedge reset))) |-> (out_assign == 4'b0000)
    );

endmodule

rtl:
module mux4to1(A, B, S0, S1, Y);
  input A, B, S0, S1;
  output Y;

  wire notS0, notS1;

  assign notS0 = ~S0;
  assign notS1 = ~S1;

  assign Y = (A & notS0 & notS1) | (B & notS0 & S1) | (A & S0 & notS1) | (B & S0 & S1);

endmodule

sva:
module mux4to1_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic S0,
    input logic S1,
    input logic Y
);

    // Y matches the RTL sum-of-products expression.
    check_output_equation: assert property (
        @(posedge clk)
        Y == ((A & ~S0 & ~S1) | (B & ~S0 & S1) | (A & S0 & ~S1) | (B & S0 & S1))
    );

    // When S1 is low, Y follows A.
    check_select_a_when_s1_low: assert property (
        @(posedge clk)
        (S1 == 1'b0) |-> (Y == A)
    );

    // When S1 is high, Y follows B.
    check_select_b_when_s1_high: assert property (
        @(posedge clk)
        (S1 == 1'b1) |-> (Y == B)
    );

    // Changing only S0 does not affect Y.
    check_s0_has_no_effect: assert property (
        @(posedge clk)
        !$initstate && $changed(S0) && $stable(A) && $stable(B) && $stable(S1) |-> $stable(Y)
    );

    // With S1 low, the unselected B input does not affect Y.
    check_b_unselected_when_s1_low: assert property (
        @(posedge clk)
        !$initstate && (S1 == 1'b0) && $changed(B) && $stable(A) && $stable(S0) && $stable(S1) |-> $stable(Y)
    );

    // With S1 high, the unselected A input does not affect Y.
    check_a_unselected_when_s1_high: assert property (
        @(posedge clk)
        !$initstate && (S1 == 1'b1) && $changed(A) && $stable(B) && $stable(S0) && $stable(S1) |-> $stable(Y)
    );

    // If A and B are equal, Y equals that common value.
    check_equal_inputs_same_output: assert property (
        @(posedge clk)
        (A == B) |-> (Y == A)
    );

endmodule

rtl:
module ring_delay (
    input clk,
    input d,
    input [3:0] delay,
    output reg q
);

reg [2:0] shift_reg;
reg [3:0] delay_counter;

always @(posedge clk) begin
    // Shift the register
    shift_reg <= {shift_reg[1:0], d};

    // Update the delay counter
    if (delay_counter == delay) begin
        // Output the delayed value
        q <= shift_reg[2];
        delay_counter <= 0;
    end else begin
        delay_counter <= delay_counter + 1;
    end
end

endmodule

sva:
module ring_delay_sva (
    input logic clk,
    input logic d,
    input logic [3:0] delay,
    input logic q,
    input logic [2:0] shift_reg,
    input logic [3:0] delay_counter
);

    // shift_reg[0] captures d every cycle.
    check_shift_reg_captures_d: assert property (
        @(posedge clk) 1'b1 |=> (shift_reg[0] == $past(d))
    );

    // shift_reg[1] takes the previous shift_reg[0].
    check_shift_reg_stage1: assert property (
        @(posedge clk) 1'b1 |=> (shift_reg[1] == $past(shift_reg[0]))
    );

    // shift_reg[2] takes the previous shift_reg[1].
    check_shift_reg_stage2: assert property (
        @(posedge clk) 1'b1 |=> (shift_reg[2] == $past(shift_reg[1]))
    );

    // delay_counter resets when it matches delay.
    check_counter_resets_on_match: assert property (
        @(posedge clk) (delay_counter == delay) |=> (delay_counter == 4'd0)
    );

    // delay_counter increments when it does not match delay.
    check_counter_increments_on_mismatch: assert property (
        @(posedge clk) (delay_counter != delay) |=> (delay_counter == ($past(delay_counter) + 4'd1))
    );

    // q updates from the previous shift_reg[2] on a match.
    check_q_updates_on_match: assert property (
        @(posedge clk) (delay_counter == delay) |=> (q == $past(shift_reg[2]))
    );

    // q holds its value when no delayed output is taken.
    check_q_holds_on_mismatch: assert property (
        @(posedge clk) (delay_counter != delay) |=> (q == $past(q))
    );

endmodule

rtl:
module keypad_scanner (
    input clk,
    input [3:0] col,
    output reg [3:0] row
);

reg [3:0] row_pipe1, row_pipe2, row_pipe3;

always @(posedge clk) begin
    row_pipe1 <= row;
    row_pipe2 <= row_pipe1;
    row_pipe3 <= row_pipe2;

    case (col)
        4'b1110: row <= 4'b1110;
        4'b1101: row <= 4'b1101;
        4'b1011: row <= 4'b1011;
        4'b0111: row <= 4'b0111;
        default: row <= 4'b0000;
    endcase
end

endmodule

sva:
module keypad_scanner_sva (
    input logic       clk,
    input logic [3:0] col,
    input logic [3:0] row
);

    // Column 1110 drives row 1110 on the following cycle.
    check_row_for_col_1110: assert property (
        @(posedge clk) (col == 4'b1110) |=> (row == 4'b1110)
    );

    // Column 1101 drives row 1101 on the following cycle.
    check_row_for_col_1101: assert property (
        @(posedge clk) (col == 4'b1101) |=> (row == 4'b1101)
    );

    // Column 1011 drives row 1011 on the following cycle.
    check_row_for_col_1011: assert property (
        @(posedge clk) (col == 4'b1011) |=> (row == 4'b1011)
    );

    // Column 0111 drives row 0111 on the following cycle.
    check_row_for_col_0111: assert property (
        @(posedge clk) (col == 4'b0111) |=> (row == 4'b0111)
    );

    // Any non-matching column value drives row to 0000 on the following cycle.
    check_row_default_for_other_cols: assert property (
        @(posedge clk)
        !((col == 4'b1110) ||
          (col == 4'b1101) ||
          (col == 4'b1011) ||
          (col == 4'b0111)) |=> (row == 4'b0000)
    );

    // Row only takes values produced by the case statement.
    check_row_legal_values: assert property (
        @(posedge clk) 1'b1 |=> (
            (row == 4'b1110) ||
            (row == 4'b1101) ||
            (row == 4'b1011) ||
            (row == 4'b0111) ||
            (row == 4'b0000)
        )
    );

endmodule

rtl:
module signal_processing(
    input A1_N,
    input A2_N,
    input B1,
    input B2,
    output Y,
    input VPB,
    input VPWR,
    input VGND,
    input VNB
);

    wire B1_OR_B2;

    assign B1_OR_B2 = B1 | B2;

    assign Y = (A1_N & A2_N) ? B1_OR_B2 : (A1_N & ~A2_N) ? B1 : (~A1_N & A2_N) ? B2 : 0;

endmodule

sva:
module signal_processing_sva (
    input logic clk,
    input logic A1_N,
    input logic A2_N,
    input logic B1,
    input logic B2,
    input logic Y,
    input logic VPB,
    input logic VPWR,
    input logic VGND,
    input logic VNB
);

    // No RTL reset exists; assertions are always active.
    // Y must match the RTL's full combinational expression.
    check_y_matches_rtl_expr: assert property (
        @(posedge clk) disable iff (1'b0)
        Y == ((A1_N & A2_N) ? (B1 | B2) :
              (A1_N & ~A2_N) ? B1 :
              (~A1_N & A2_N) ? B2 : 1'b0)
    );

    // When both select inputs are high, Y is B1 OR B2.
    check_or_path_selected: assert property (
        @(posedge clk) disable iff (1'b0)
        (A1_N && A2_N) |-> (Y == (B1 | B2))
    );

    // When only A1_N is high, Y follows B1.
    check_b1_path_selected: assert property (
        @(posedge clk) disable iff (1'b0)
        (A1_N && !A2_N) |-> (Y == B1)
    );

    // When only A2_N is high, Y follows B2.
    check_b2_path_selected: assert property (
        @(posedge clk) disable iff (1'b0)
        (!A1_N && A2_N) |-> (Y == B2)
    );

    // When both select inputs are low, Y is forced low.
    check_no_path_selected: assert property (
        @(posedge clk) disable iff (1'b0)
        (!A1_N && !A2_N) |-> (Y == 1'b0)
    );

endmodule

