rtl:
module byte_swap (
    input [7:0] in,
    output [7:0] out
);
    assign out = {in[7], in[6], in[5], in[4], in[3], in[2], in[1], in[0]};
endmodule

module edge_detect (
    input [7:0] in,
    input clk,
    output reg anyedge
);
    reg [7:0] prev_in;

    always @(posedge clk) begin
        if (in != prev_in) begin
            anyedge <= 1;
        end else begin
            anyedge <= 0;
        end
        prev_in <= in;
    end
endmodule

module top_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input [7:0] in,   // Input vector
    output reg anyedge    // Output signal indicating edge transition
);
    wire [7:0] swapped_in;
    wire edge_detected;

    byte_swap bs(in, swapped_in);
    edge_detect ed(swapped_in, clk, edge_detected);

    always @(posedge clk) begin
        if (reset) begin
            anyedge <= 0;
        end else begin
            anyedge <= edge_detected;
        end
    end
endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic reset,
    input logic [7:0] in,
    input logic anyedge,
    input logic [7:0] swapped_in,
    input logic edge_detected
);

    // Byte swap leaves the sampled byte unchanged.
    check_swapped_in_matches_in: assert property (
        @(posedge clk) disable iff (reset)
        (swapped_in === in)
    );

    // A change on swapped_in between the two previous samples sets current edge_detected.
    check_edge_detected_after_change: assert property (
        @(posedge clk) disable iff (reset)
        (!$isunknown($past(swapped_in)) &&
         !$isunknown($past(swapped_in, 2)) &&
         ($past(swapped_in) != $past(swapped_in, 2))) |-> (edge_detected == 1'b1)
    );

    // No change on swapped_in between the two previous samples clears current edge_detected.
    check_edge_detected_after_stable: assert property (
        @(posedge clk) disable iff (reset)
        (!$isunknown($past(swapped_in)) &&
         !$isunknown($past(swapped_in, 2)) &&
         ($past(swapped_in) == $past(swapped_in, 2))) |-> (edge_detected == 1'b0)
    );

    // Reset on the previous clock forces current anyedge low.
    check_anyedge_low_after_reset: assert property (
        @(posedge clk) disable iff (reset)
        (!$isunknown($past(reset)) && $past(reset)) |-> (anyedge == 1'b0)
    );

    // Previous high edge_detected propagates to current anyedge when reset was low.
    check_anyedge_after_edge_detected_high: assert property (
        @(posedge clk) disable iff (reset)
        (!$isunknown($past(reset)) &&
         !$past(reset) &&
         !$isunknown($past(edge_detected)) &&
         $past(edge_detected)) |-> (anyedge == 1'b1)
    );

    // Previous low edge_detected propagates to current anyedge when reset was low.
    check_anyedge_after_edge_detected_low: assert property (
        @(posedge clk) disable iff (reset)
        (!$isunknown($past(reset)) &&
         !$past(reset) &&
         !$isunknown($past(edge_detected)) &&
         !$past(edge_detected)) |-> (anyedge == 1'b0)
    );

    // An input change two cycles ago sets current anyedge when the previous cycle was not reset.
    check_anyedge_after_input_change: assert property (
        @(posedge clk) disable iff (reset)
        (!$isunknown($past(reset)) &&
         !$past(reset) &&
         !$isunknown($past(in, 2)) &&
         !$isunknown($past(in, 3)) &&
         ($past(in, 2) != $past(in, 3))) |-> (anyedge == 1'b1)
    );

    // Input stability two cycles ago clears current anyedge when the previous cycle was not reset.
    check_anyedge_after_input_stable: assert property (
        @(posedge clk) disable iff (reset)
        (!$isunknown($past(reset)) &&
         !$past(reset) &&
         !$isunknown($past(in, 2)) &&
         !$isunknown($past(in, 3)) &&
         ($past(in, 2) == $past(in, 3))) |-> (anyedge == 1'b0)
    );

    // A reset asserted on this clock drives anyedge low by the next sampled cycle.
    check_reset_clears_anyedge: assert property (
        @(posedge clk)
        reset |=> (anyedge == 1'b0)
    );

endmodule

rtl:
module clock_gate (
  input CLK,
  input EN,
  input TE,
  output reg ENCLK
);

 always @(posedge TE or posedge CLK) begin
    if (TE == 0) ENCLK <= EN;
     else ENCLK <= 0;
 end

endmodule

sva:
module clock_gate_sva (
    input logic CLK,
    input logic EN,
    input logic TE,
    input logic ENCLK
);

    // RTL updates on posedge CLK and posedge TE; there is no reset.

    // A high TE sampled on the prior CLK edge forces ENCLK low now.
    check_prev_te_forces_enclk_low: assert property (
        @(posedge CLK) !$initstate && $past(TE) |-> (ENCLK == 1'b0)
    );

    // A low EN sampled with TE low on the prior CLK edge forces ENCLK low now.
    check_prev_en_low_forces_enclk_low: assert property (
        @(posedge CLK) !$initstate && !$past(TE) && !$past(EN) |-> (ENCLK == 1'b0)
    );

    // A high ENCLK sample must come from a prior CLK edge with TE low.
    check_enclk_high_requires_prev_te_low: assert property (
        @(posedge CLK) !$initstate && ENCLK |-> ($past(TE) == 1'b0)
    );

    // A high ENCLK sample must come from a prior CLK edge with EN high.
    check_enclk_high_requires_prev_en_high: assert property (
        @(posedge CLK) !$initstate && ENCLK |-> ($past(EN) == 1'b1)
    );

