module add_module_assertions (
    input logic clk,
    input logic rst,
    input logic [15:0] in_data,
    input logic [15:0] out_data
);

    // Reset drives the output to zero by the next sampled clock.
    check_reset_clears_out_next: assert property (
        @(posedge clk) !rst |=> (out_data == 16'h0000)
    );

    // While reset stays asserted, the output remains zero.
    check_reset_holds_out_zero: assert property (
        @(posedge clk) (!rst && $past(!rst)) |-> (out_data == 16'h0000)
    );

    // Each active clock loads input plus 16'h1234 into the output register.
    check_active_cycle_updates_sum: assert property (
        @(posedge clk) disable iff (!rst) 1'b1 |=> (out_data == ($past(in_data) + 16'h1234))
    );

    // The first active cycle after reset release also loads the sum correctly.
    check_reset_release_updates_sum: assert property (
        @(posedge clk) disable iff (!rst) !$past(rst) |=> (out_data == ($past(in_data) + 16'h1234))
    );

    // Zero input produces 16'h1234 on the next sampled clock.
    check_zero_input_case: assert property (
        @(posedge clk) disable iff (!rst) (in_data == 16'h0000) |=> (out_data == 16'h1234)
    );

    // Max input wraps around to 16'h1233 on the next sampled clock.
    check_max_input_wraparound: assert property (
        @(posedge clk) disable iff (!rst) (in_data == 16'hFFFF) |=> (out_data == 16'h1233)
    );

endmodule

rtl:
module pg_49 ( g, p, g_prec, p_prec, p_out, g_out_BAR );
  input g, p, g_prec, p_prec;
  output p_out, g_out_BAR;

  // Implement logical AND between p and p_prec
  assign p_out = p & p_prec;

  // Implement logical NOR between g_prec and p
  assign g_out_BAR = ~(g_prec | p);

endmodule

sva:
module pg_49_sva (
    input logic clk,
    input logic g,
    input logic p,
    input logic g_prec,
    input logic p_prec,
    input logic p_out,
    input logic g_out_BAR
);

    // p_out implements p AND p_prec.
    check_p_out_and_function: assert property (
        @(posedge clk) p_out == (p & p_prec)
    );

    // g_out_BAR implements NOR of g_prec and p.
    check_g_out_bar_nor_function: assert property (
        @(posedge clk) g_out_BAR == ~(g_prec | p)
    );

    // p_out can only be high when both inputs are high.
    check_p_out_high_requires_inputs_high: assert property (
        @(posedge clk) p_out |-> (p && p_prec)
    );

    // p_out must be low if either input is low.
    check_p_out_low_when_any_input_low: assert property (
        @(posedge clk) (!p || !p_prec) |-> !p_out
    );

    // g_out_BAR can only be high when both NOR inputs are low.
    check_g_out_bar_high_requires_inputs_low: assert property (
        @(posedge clk) g_out_BAR |-> (!g_prec && !p)
    );

    // g_out_BAR must be low if either NOR input is high.
    check_g_out_bar_low_when_any_input_high: assert property (
        @(posedge clk) (g_prec || p) |-> !g_out_BAR
    );

    // A high p_out forces g_out_BAR low because p must be high.
    check_p_out_implies_g_out_bar_low: assert property (
        @(posedge clk) p_out |-> !g_out_BAR
    );

    // Changing only g does not affect either output.
    check_g_unused_in_output_logic: assert property (
        @(posedge clk) $changed(g) && $stable({p, g_prec, p_prec}) |-> $stable({p_out, g_out_BAR})
    );

    // Stable AND inputs keep p_out stable.
    check_p_out_stable_when_inputs_stable: assert property (
        @(posedge clk) $stable({p, p_prec}) |-> $stable(p_out)
    );

    // Stable NOR inputs keep g_out_BAR stable.
    check_g_out_bar_stable_when_inputs_stable: assert property (
        @(posedge clk) $stable({g_prec, p}) |-> $stable(g_out_BAR)
    );

endmodule

rtl:
module pwm_generator (
    input clk,
    input [3:0] duty_cycle,
    output reg pwm_out
);

reg [3:0] counter;

always @(posedge clk) begin
    counter <= counter + 1;
    if (counter >= 15) begin
        counter <= 0;
        pwm_out <= (counter < duty_cycle);
    end
end

endmodule

sva:
module pwm_generator_sva (
    input logic clk,
    input logic [3:0] duty_cycle,
    input logic pwm_out,
    input logic [3:0] counter
);

    // Counter increments by one on non-wrap cycles.
    check_counter_increments: assert property (
        @(posedge clk) (counter < 4'd15) |=> (counter == ($past(counter) + 4'd1))
    );

    // At the wrap point, counter returns to zero and pwm_out uses the sampled comparison.
    check_wrap_behavior: assert property (
        @(posedge clk) (counter == 4'd15) |=> ((counter == 4'd0) && (pwm_out == ($past(counter) < $past(duty_cycle))))
    );

    // pwm_out holds its value on cycles where the wrap condition is not met.
    check_pwm_holds_between_wraps: assert property (
        @(posedge clk) (counter < 4'd15) |=> (pwm_out == $past(pwm_out))
    );

    // The sampled wrap comparison always drives pwm_out low for a 4-bit duty_cycle.
    check_pwm_low_on_wrap: assert property (
        @(posedge clk) (counter == 4'd15) |=> (pwm_out == 1'b0)
    );

endmodule

rtl:
module dff_rst_set_clr (
  input clk, rst, set, clr, d,
  output reg q
);

always @(posedge clk or negedge rst) begin
  if (~rst) begin
    q <= 1'b0;
  end else if (set) begin
    q <= 1'b1;
  end else if (clr) begin
    q <= 1'b0;
  end else begin
    q <= d;
  end
end

endmodule

sva:
module dff_rst_set_clr_sva (
    input logic clk,
    input logic rst,
    input logic set,
    input logic clr,
    input logic d,
    input logic q
);

    // A low reset drives q low by the next clock sample.
    check_reset_clears_q: assert property (
        @(posedge clk)
        !rst |=> (q == 1'b0)
    );

    // Set drives q high on the next cycle.
    check_set_loads_high: assert property (
        @(posedge clk) disable iff (!rst)
        set |=> (q == 1'b1)
    );

    // Clear drives q low when set is not asserted.
    check_clear_loads_low: assert property (
        @(posedge clk) disable iff (!rst)
        (!set && clr) |=> (q == 1'b0)
    );

    // Data value 1 is loaded when set and clear are both low.
    check_data_one_loads_high: assert property (
        @(posedge clk) disable iff (!rst)
        (!set && !clr && d) |=> (q == 1'b1)
    );

    // Data value 0 is loaded when set and clear are both low.
    check_data_zero_loads_low: assert property (
        @(posedge clk) disable iff (!rst)
        (!set && !clr && !d) |=> (q == 1'b0)
    );

    // Set has priority over clear when both are asserted.
    check_set_priority_over_clear: assert property (
        @(posedge clk) disable iff (!rst)
        (set && clr) |=> (q == 1'b1)
    );

endmodule

