module a221o_2_sva (
    input logic clk,
    input logic X,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic B2,
    input logic C1,
    input logic Y
);

    // Y must match the implemented sum-of-products equation.
    check_output_equation: assert property (
        @(posedge clk)
        Y == ((A1 & B1 & C1) | (A2 & B2 & C1))
    );

    // C1 low forces Y low.
    check_c1_low_forces_y_low: assert property (
        @(posedge clk)
        !C1 |-> !Y
    );

    // The A1/B1 path is sufficient to drive Y high.
    check_first_product_term_drives_y: assert property (
        @(posedge clk)
        (A1 & B1 & C1) |-> Y
    );

    // The A2/B2 path is sufficient to drive Y high.
    check_second_product_term_drives_y: assert property (
        @(posedge clk)
        (A2 & B2 & C1) |-> Y
    );

    // Y high requires C1 to be high.
    check_y_implies_c1_high: assert property (
        @(posedge clk)
        Y |-> C1
    );

    // Y high requires at least one input pair product to be true.
    check_y_implies_product_term: assert property (
        @(posedge clk)
        Y |-> ((A1 & B1) | (A2 & B2))
    );

    // X is unused; changing only X cannot change Y.
    check_x_has_no_effect_on_y: assert property (
        @(posedge clk)
        ($changed(X) && $stable({A1, A2, B1, B2, C1})) |-> $stable(Y)
    );

endmodule

rtl:
module mux_2to1 #(
  parameter WIDTH = 1
) (
  input wire ctrl,
  input wire [WIDTH-1:0] D0,
  input wire [WIDTH-1:0] D1,
  output reg [WIDTH-1:0] S
);

  always @(*) begin
    if (ctrl == 1'b0) begin
      S = D0;
    end else begin
      S = D1;
    end
  end

endmodule

sva:
module mux_2to1_sva #(
    parameter WIDTH = 1
) (
    input logic ctrl,
    input logic [WIDTH-1:0] D0,
    input logic [WIDTH-1:0] D1,
    input logic [WIDTH-1:0] S
);

    // No clock or reset exists in the RTL; sample on the formal global clock.

    // When ctrl is exactly 0, the output selects D0.
    check_select_d0_when_ctrl_low: assert property (
        @($global_clock) (ctrl === 1'b0) |-> (S === D0)
    );

    // When ctrl is not exactly 0, the output selects D1.
    check_select_d1_when_ctrl_not_low: assert property (
        @($global_clock) (ctrl !== 1'b0) |-> (S === D1)
    );

    // The output always matches one of the two inputs.
    check_output_matches_one_input: assert property (
        @($global_clock) ((S === D0) || (S === D1))
    );

    // If both inputs are equal, the output matches that common value.
    check_equal_inputs_passthrough: assert property (
        @($global_clock) (D0 === D1) |-> (S === D0)
    );

endmodule

