    check_sel_low_routes_a: assert property (
        @(posedge clk) !SEL |-> (Y == A)
    );

    // Y must follow B when SEL is high.
    check_sel_high_routes_b: assert property (
        @(posedge clk) SEL |-> (Y == B)
    );

    // Y must always match the mux select equation.
    check_mux_equation: assert property (
        @(posedge clk) Y == (SEL ? B : A)
    );

endmodule

rtl:
module four_bit_adder(
    input [3:0] A,
    input [3:0] B,
    input CI,
    output [3:0] C,
    output CO
);

wire [3:0] sum;
wire [4:0] carry;

// Full adder
assign sum[0] = A[0] ^ B[0] ^ CI;
assign carry[0] = (A[0] & B[0]) | (A[0] & CI) | (B[0] & CI);

assign sum[1] = A[1] ^ B[1] ^ carry[0];
assign carry[1] = (A[1] & B[1]) | (A[1] & carry[0]) | (B[1] & carry[0]);

assign sum[2] = A[2] ^ B[2] ^ carry[1];
assign carry[2] = (A[2] & B[2]) | (A[2] & carry[1]) | (B[2] & carry[1]);

assign sum[3] = A[3] ^ B[3] ^ carry[2];
assign carry[3] = (A[3] & B[3]) | (A[3] & carry[2]) | (B[3] & carry[2]);

assign CO = carry[3];
assign C = sum;

endmodule

sva:
module four_bit_adder_sva (
    input logic       clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic       CI,
    input logic [3:0] C,
    input logic       CO
);

    // Full 5-bit result matches A + B + CI.
    check_total_sum: assert property (
        @(posedge clk) {CO, C} == ({1'b0, A} + {1'b0, B} + CI)
    );

    // Bit 0 matches the RTL full-adder XOR.
    check_bit0_sum: assert property (
        @(posedge clk) C[0] == (A[0] ^ B[0] ^ CI)
    );

    // Bit 1 matches the sum of the lower 2-bit slice plus carry-in.
    check_bit1_sum: assert property (
        @(posedge clk) C[1] == (({1'b0, A[1:0]} + {1'b0, B[1:0]} + CI)[1])
    );

    // Bit 2 matches the sum of the lower 3-bit slice plus carry-in.
    check_bit2_sum: assert property (
        @(posedge clk) C[2] == (({1'b0, A[2:0]} + {1'b0, B[2:0]} + CI)[2])
    );

    // Bit 3 matches the sum of the full 4-bit inputs plus carry-in.
    check_bit3_sum: assert property (
        @(posedge clk) C[3] == (({1'b0, A} + {1'b0, B} + CI)[3])
    );

    // Carry-out matches the overflow bit of the full addition.
    check_carry_out: assert property (
        @(posedge clk) CO == (({1'b0, A} + {1'b0, B} + CI)[4])
    );

endmodule

rtl:
module decoder_3to8 (
    input [2:0] in,
    output reg [7:0] out
);

    always @(*) begin
        case(in)
            3'b000: out = 8'b00000001;
            3'b001: out = 8'b00000010;
            3'b010: out = 8'b00000100;
            3'b011: out = 8'b00001000;
            3'b100: out = 8'b00010000;
            3'b101: out = 8'b00100000;
            3'b110: out = 8'b01000000;
            3'b111: out = 8'b10000000;
            default: out = 8'b00000000;
        endcase
    end

endmodule

sva:
module decoder_3to8_sva (
    input logic [2:0] in,
    input logic [7:0] out
);

    // No explicit clock or reset in RTL; sample on Jasper global clock.

    // Output matches the one-hot decode of the input value.
    check_decode_matches_input: assert property (
        @($global_clock) out == (8'b00000001 << in)
    );

    // out[0] is high only for input 000.
    check_out0_decode: assert property (
        @($global_clock) out[0] == (in == 3'b000)
    );

    // out[1] is high only for input 001.
    check_out1_decode: assert property (
        @($global_clock) out[1] == (in == 3'b001)
    );

    // out[2] is high only for input 010.
    check_out2_decode: assert property (
        @($global_clock) out[2] == (in == 3'b010)
    );

    // out[3] is high only for input 011.
    check_out3_decode: assert property (
        @($global_clock) out[3] == (in == 3'b011)
    );

    // out[4] is high only for input 100.
    check_out4_decode: assert property (
        @($global_clock) out[4] == (in == 3'b100)
    );

    // out[5] is high only for input 101.
    check_out5_decode: assert property (
        @($global_clock) out[5] == (in == 3'b101)
    );

    // out[6] is high only for input 110.
    check_out6_decode: assert property (
        @($global_clock) out[6] == (in == 3'b110)
    );

    // out[7] is high only for input 111.
    check_out7_decode: assert property (
        @($global_clock) out[7] == (in == 3'b111)
    );

    // The decoder output always has exactly one bit set.
    check_output_onehot: assert property (
        @($global_clock) $onehot(out)
    );

endmodule

rtl:
module two_bit_encoder
    ( 
    input   [1:0]  data,
    output  reg    q
    );

    always @(*)
    begin
        if (data == 2'b10)
            q = 1'b0;
        else
            q = data[1];
    end

endmodule

sva:
module two_bit_encoder_sva (
    input logic       clk,
    input logic [1:0] data,
    input logic       q
);

    // data 2'b00 drives q low.
    check_data_00_drives_q_low: assert property (
        @(posedge clk) (data == 2'b00) |-> (q == 1'b0)
    );

    // data 2'b01 drives q low.
    check_data_01_drives_q_low: assert property (
        @(posedge clk) (data == 2'b01) |-> (q == 1'b0)
    );

    // data 2'b10 drives q low.
    check_data_10_drives_q_low: assert property (
        @(posedge clk) (data == 2'b10) |-> (q == 1'b0)
    );

    // data 2'b11 drives q high.
    check_data_11_drives_q_high: assert property (
        @(posedge clk) (data == 2'b11) |-> (q == 1'b1)
    );

    // q can only be high for input 2'b11.
    check_q_high_only_for_data_11: assert property (
        @(posedge clk) (q == 1'b1) |-> (data == 2'b11)
    );

endmodule

rtl:
module bitwise_shifter (
  input [31:0] in,
  input [1:0] shift,
  output reg [31:0] out
);

  always @(*)
  begin
    case(shift)
      2'b00: out = in;
      2'b01: out = {in[30:0], 1'b0};
      2'b10: out = {1'b0, in[31:1]};
      2'b11: out = {2'b00, in[31:2]};
    endcase
  end

endmodule

sva:
module bitwise_shifter_sva (
    input logic clk,
    input logic [31:0] in,
    input logic [1:0] shift,
    input logic [31:0] out
);

    // shift=00 passes the input through unchanged.
    check_shift_00_passthrough: assert property (
        @(posedge clk) (shift == 2'b00) |-> (out == in)
    );

    // shift=01 shifts left by one and inserts zero into bit 0.
    check_shift_01_left_by_one: assert property (
        @(posedge clk) (shift == 2'b01) |-> (out == {in[30:0], 1'b0})
    );

    // shift=10 shifts right by one and inserts zero into bit 31.
    check_shift_10_right_by_one: assert property (
        @(posedge clk) (shift == 2'b10) |-> (out == {1'b0, in[31:1]})
    );

    // shift=11 shifts right by two and inserts zeros into bits 31:30.
    check_shift_11_right_by_two: assert property (
        @(posedge clk) (shift == 2'b11) |-> (out == {2'b00, in[31:2]})
    );

endmodule

rtl:
module sky130_fd_sc_lp__fahcon (
    COUT_N,
    SUM   ,
    A     ,
    B     ,
    CI
);

    output COUT_N;
    output SUM   ;
    input  A     ;
    input  B     ;
    input  CI    ;

    wire xor0_out_SUM ;
    wire a_b          ;
    wire a_ci         ;
    wire b_ci         ;
    wire or0_out_coutn;

    xor xor0 (xor0_out_SUM , A, B, CI       );
    buf buf0 (SUM          , xor0_out_SUM   );
    nor nor0 (a_b          , A, B           );
    nor nor1 (a_ci         , A, CI          );
    nor nor2 (b_ci         , B, CI          );
    or  or0  (or0_out_coutn, a_b, a_ci, b_ci);
    buf buf1 (COUT_N       , or0_out_coutn  );

endmodule

sva:
module sky130_fd_sc_lp__fahcon_sva (
    input logic clk,
    input logic COUT_N,
    input logic SUM,
    input logic A,
    input logic B,
    input logic CI
);

    // SUM is the three-input XOR of A, B, and CI.
    check_sum_parity: assert property (
        @(posedge clk) SUM == (A ^ B ^ CI)
    );

    // COUT_N matches the OR of the three pairwise NOR terms.
    check_coutn_function: assert property (
        @(posedge clk) COUT_N == (((~A) & (~B)) | ((~A) & (~CI)) | ((~B) & (~CI)))
    );

    // All-zero inputs produce SUM low and COUT_N high.
    check_all_zero_case: assert property (
        @(posedge clk) (!A && !B && !CI) |-> ((SUM == 1'b0) && (COUT_N == 1'b1))
    );

    // Any single high input produces SUM high and COUT_N high.
    check_one_high_case: assert property (
        @(posedge clk)
        (( A && !B && !CI) ||
         (!A &&  B && !CI) ||
         (!A && !B &&  CI)) |-> ((SUM == 1'b1) && (COUT_N == 1'b1))
    );

    // Any two high inputs produce SUM low and COUT_N low.
    check_two_high_case: assert property (
        @(posedge clk)
        (( A &&  B && !CI) ||
         ( A && !B &&  CI) ||
         (!A &&  B &&  CI)) |-> ((SUM == 1'b0) && (COUT_N == 1'b0))
    );

    // All-high inputs produce SUM high and COUT_N low.
    check_all_high_case: assert property (
        @(posedge clk) (A && B && CI) |-> ((SUM == 1'b1) && (COUT_N == 1'b0))
    );

endmodule

rtl:
module top_module (
    input [3:0] in0,
    input [3:0] in1,
    input DIR,
    input [1:0] AMT,
    output wire eq,
    output wire gt,
    output wire lt,
    output wire [3:0] out
);

wire [3:0] shifted_in0;

// Barrel shifter
barrel_shifter bs (
    .in(in0),
    .shift_dir(DIR),
    .shift_amt(AMT),
    .out(shifted_in0)
);

// Comparator
comparator cmp (
    .in1(shifted_in0),
    .in2(in1),
    .eq(eq),
    .gt(gt),
    .lt(lt)
);

// Output
assign out = shifted_in0;

endmodule

module barrel_shifter (
    input [3:0] in,
    input shift_dir,
    input [1:0] shift_amt,
    output [3:0] out
);

assign out = shift_dir ? in >> shift_amt : in << shift_amt;

endmodule

module comparator (
    input [3:0] in1,
    input [3:0] in2,
    output eq,
    output gt,
    output lt
);

assign eq = (in1 == in2);
assign gt = (in1 > in2);
assign lt = (in1 < in2);

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic [3:0] in0,
    input logic [3:0] in1,
    input logic DIR,
    input logic [1:0] AMT,
    input logic eq,
    input logic gt,
    input logic lt,
    input logic [3:0] out
);

    // RTL has no native clock or reset.
    // clk is only used to sample combinational behavior.

    // out must equal the barrel-shifted version of in0.
    check_out_matches_shift: assert property (
        @(posedge clk) out == (DIR ? (in0 >> AMT) : (in0 << AMT))
    );

    // A zero shift amount must pass in0 through unchanged.
    check_zero_shift_passthrough: assert property (
        @(posedge clk) (AMT == 2'b00) |-> (out == in0)
    );

    // DIR high selects a right shift.
    check_right_shift_behavior: assert property (
        @(posedge clk) DIR |-> (out == (in0 >> AMT))
    );

    // DIR low selects a left shift.
    check_left_shift_behavior: assert property (
        @(posedge clk) !DIR |-> (out == (in0 << AMT))
    );

    // eq must indicate equality between out and in1.
    check_eq_definition: assert property (
        @(posedge clk) eq == (out == in1)
    );

    // gt must indicate out is greater than in1.
    check_gt_definition: assert property (
        @(posedge clk) gt == (out > in1)
    );

    // lt must indicate out is less than in1.
    check_lt_definition: assert property (
        @(posedge clk) lt == (out < in1)
    );

    // eq cannot be high with gt or lt.
    check_eq_exclusive: assert property (
        @(posedge clk) !(eq && gt) && !(eq && lt)
    );

    // gt and lt cannot be high at the same time.
    check_gt_lt_mutex: assert property (
        @(posedge clk) !(gt && lt)
    );

    // The comparator must always report one relation.
    check_compare_complete: assert property (
        @(posedge clk) eq || gt || lt
    );

endmodule

rtl:
module mux_4to2 (
    input [3:0] A0,
    input [3:0] A1,
    input [3:0] A2,
    input [3:0] A3,
    input S0,
    input S1,
    output reg [3:0] X
);

always @* begin
    case ({S1, S0})
        2'b00: X = A0;
        2'b01: X = A1;
        2'b10: X = A2;
        2'b11: X = A3;
    endcase
end

endmodule

sva:
module mux_4to2_sva (
    input logic clk,
    input logic [3:0] A0,
    input logic [3:0] A1,
    input logic [3:0] A2,
    input logic [3:0] A3,
    input logic S0,
    input logic S1,
    input logic [3:0] X
);

    // External sampling clock; the RTL itself has no clock or reset.

    // X must match A0 when the select is 00.
    check_select_a0: assert property (
        @(posedge clk) ({S1, S0} == 2'b00) |-> (X == A0)
    );

    // X must match A1 when the select is 01.
    check_select_a1: assert property (
        @(posedge clk) ({S1, S0} == 2'b01) |-> (X == A1)
    );

    // X must match A2 when the select is 10.
    check_select_a2: assert property (
        @(posedge clk) ({S1, S0} == 2'b10) |-> (X == A2)
    );

    // X must match A3 when the select is 11.
    check_select_a3: assert property (
        @(posedge clk) ({S1, S0} == 2'b11) |-> (X == A3)
    );

endmodule

rtl:
module data_path(
    input [15:0] in_data,
    input in_valid,
    input out_ready,
    output reg [15:0] out_data,
    output reg out_valid,
    output reg out_error,
	input clk
);

wire [1:0] error_type;
assign error_type = 2'b00; // no errors

always @ (posedge clk) begin
    if (in_valid) begin
        if (out_ready) begin
            out_data <= in_data;
            out_valid <= 1'b1;
            out_error <= 1'b0;
        end else begin
            out_data <= 16'h0000;
            out_valid <= 1'b0;
            out_error <= 1'b1;
        end
    end else begin
        out_data <= 16'h0000;
        out_valid <= 1'b0;
        out_error <= 1'b0;
    end
end

endmodule

sva:
module data_path_sva (
    input logic [15:0] in_data,
    input logic        in_valid,
    input logic        out_ready,
    input logic [15:0] out_data,
    input logic        out_valid,
    input logic        out_error,
    input logic        clk
);

    // Valid input with ready forwards data on the next cycle.
    check_accept_forwards_data: assert property (
        @(posedge clk) (in_valid && out_ready) |=> (out_valid && !out_error && (out_data == $past(in_data)))
    );

    // Valid input without ready raises an error on the next cycle.
    check_stall_sets_error: assert property (
        @(posedge clk) (in_valid && !out_ready) |=> (!out_valid && out_error && (out_data == 16'h0000))
    );

    // No valid input clears outputs on the next cycle.
    check_idle_clears_outputs: assert property (
        @(posedge clk) (!in_valid) |=> (!out_valid && !out_error && (out_data == 16'h0000))
    );

    // out_valid is high only for a previous-cycle valid and ready handshake.
    check_out_valid_definition: assert property (
        @(posedge clk) 1'b1 |=> (out_valid == ($past(in_valid) && $past(out_ready)))
    );

    // out_error is high only for a previous-cycle valid input without ready.
    check_out_error_definition: assert property (
        @(posedge clk) 1'b1 |=> (out_error == ($past(in_valid) && !$past(out_ready)))
    );

    // out_data matches the previous input on accept, otherwise it is zero.
    check_out_data_definition: assert property (
        @(posedge clk) 1'b1 |=> (out_data == (($past(in_valid) && $past(out_ready)) ? $past(in_data) : 16'h0000))
    );

    // out_valid and out_error are never asserted together.
    check_status_mutex: assert property (
        @(posedge clk) 1'b1 |=> !(out_valid && out_error)
    );

    // Some status bit is set iff the previous cycle had a valid input.
    check_status_tracks_in_valid: assert property (
        @(posedge clk) 1'b1 |=> ((out_valid || out_error) == $past(in_valid))
    );

endmodule

rtl:
module nor4(
    output Y,
    input A,
    input B,
    input C,
    input D
);

    wire n1, n2;
    assign n1 = ~(A | B | C);
    assign n2 = ~(n1 | D | D);
    assign Y = ~n2;

endmodule

sva:
module nor4_sva (
    input logic clk,
    input logic Y,
    input logic A,
    input logic B,
    input logic C,
    input logic D
);

    // Y matches the implemented combinational equation.
    check_output_equation: assert property (
        @(posedge clk) Y == ((~(A | B | C)) | D)
    );

    // When D is low, Y reduces to the NOR of A, B, and C.
    check_d_low_reduces_to_nor3: assert property (
        @(posedge clk) !D |-> (Y == ~(A | B | C))
    );

    // A high D input forces Y high.
    check_d_high_forces_y_high: assert property (
        @(posedge clk) D |-> Y
    );

    // With D low, any high input among A, B, or C forces Y low.
    check_abc_high_with_d_low_forces_y_low: assert property (
        @(posedge clk) (!D && (A || B || C)) |-> !Y
    );

    // If all inputs are stable across samples, Y stays stable too.
    check_stable_inputs_keep_output_stable: assert property (
        @(posedge clk) $stable({A, B, C, D}) |-> $stable(Y)
    );

endmodule

rtl:
module adder_subtractor (
    input [3:0] A,
    input [3:0] B,
    input SUB,
    output [7:0] OUT
);

assign OUT = SUB ? (A - B) : (A + B);

endmodule

module multiplier (
    input [3:0] A,
    input [3:0] B,
    input clk,
    output [7:0] PRODUCT
);

wire [7:0] stage1_out;
wire [7:0] stage2_out;

adder_subtractor addsub1(.A(A), .B(B), .SUB(1'b0), .OUT(stage1_out));
adder_subtractor addsub2(.A(stage1_out[3:0]), .B(stage1_out[7:4]), .SUB(1'b0), .OUT(stage2_out));

reg [7:0] product_reg;

always @(posedge clk) begin
    product_reg <= stage2_out;
end

assign PRODUCT = product_reg;

endmodule

sva:
module multiplier_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic       clk,
    input logic [7:0] PRODUCT
);

    // PRODUCT is the registered previous-cycle zero-extended truncated A+B result.
    check_product_registered_sum: assert property (
        @(posedge clk) ##1 PRODUCT == {4'h0, (($past(A) + $past(B)) & 4'hf)}
    );

    // The upper nibble of PRODUCT is always zero after the first clocked update.
    check_product_upper_nibble_zero: assert property (
        @(posedge clk) ##1 PRODUCT[7:4] == 4'h0
    );

    // The lower nibble of PRODUCT matches the previous-cycle truncated A+B value.
    check_product_lower_nibble_sum: assert property (
        @(posedge clk) ##1 PRODUCT[3:0] == (($past(A) + $past(B)) & 4'hf)
    );

endmodule

rtl:
module power_check (
    input  VPWR,
    input  VGND,
    input  VPB,
    input  VNB,
    output reg power_ok
);

    wire w_power_ok;

    assign w_power_ok = (VPWR && VPB);
    always @(*) begin
        power_ok <= w_power_ok;
    end

endmodule

sva:
module power_check_sva (
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB,
    input logic power_ok
);

    // power_ok must always match the VPWR/VPB AND function.
    check_power_ok_matches_and: assert property (
        @($global_clock) power_ok == (VPWR && VPB)
    );

    // power_ok high requires VPWR to be high.
    check_power_ok_implies_vpwr: assert property (
        @($global_clock) power_ok |-> VPWR
    );

    // power_ok high requires VPB to be high.
    check_power_ok_implies_vpb: assert property (
        @($global_clock) power_ok |-> VPB
    );

    // A low VPWR must force power_ok low.
    check_low_vpwr_forces_power_not_ok: assert property (
        @($global_clock) !VPWR |-> !power_ok
    );

    // A low VPB must force power_ok low.
    check_low_vpb_forces_power_not_ok: assert property (
        @($global_clock) !VPB |-> !power_ok
    );

    // Changing VGND alone must not change power_ok.
    check_vgnd_unused: assert property (
        @($global_clock)
        !$initstate && $changed(VGND) && $stable(VPWR) && $stable(VPB) && $stable(VNB)
        |-> $stable(power_ok)
    );

    // Changing VNB alone must not change power_ok.
    check_vnb_unused: assert property (
        @($global_clock)
        !$initstate && $changed(VNB) && $stable(VPWR) && $stable(VPB) && $stable(VGND)
        |-> $stable(power_ok)
    );

endmodule

rtl:
module full_adder_en (
    input A,
    input B,
    input Cin,
    input En,
    output reg Sum,
    output reg Cout
);

always @(A or B or Cin or En) begin
    if (En == 1'b1) begin
        Sum  <= A ^ B ^ Cin;
        Cout <= (A & B) | (Cin & (A ^ B));
    end else begin
        Sum  <= 1'b0;
        Cout <= 1'b0;
    end
end

endmodule

sva:
module full_adder_en_sva (
    input logic A,
    input logic B,
    input logic Cin,
    input logic En,
    input logic Sum,
    input logic Cout
);

    // Combinational DUT with no explicit clock or reset; use the formal global clock.

    // When disabled, both outputs are forced low.
    check_disabled_outputs_zero: assert property (
        @($global_clock)
        (En == 1'b0) |-> (Sum == 1'b0 && Cout == 1'b0)
    );

    // When enabled, Sum matches the three-input XOR function.
    check_enabled_sum_function: assert property (
        @($global_clock)
        (En == 1'b1) |-> (Sum == (A ^ B ^ Cin))
    );

    // When enabled, Cout matches the RTL carry equation.
    check_enabled_carry_function: assert property (
        @($global_clock)
        (En == 1'b1) |-> (Cout == ((A & B) | (Cin & (A ^ B))))
    );

    // When enabled, the outputs equal the 2-bit sum of A, B, and Cin.
    check_enabled_full_adder_result: assert property (
        @($global_clock)
        (En == 1'b1) |-> ({Cout, Sum} == ({1'b0, A} + {1'b0, B} + {1'b0, Cin}))
    );

endmodule

rtl:
module sky130_fd_sc_ms__o2111ai (
    Y ,
    A1,
    A2,
    B1,
    C1,
    D1
);

    output Y ;
    input  A1;
    input  A2;
    input  B1;
    input  C1;
    input  D1;

    wire or0_out    ;
    wire nand0_out_Y;

    or   or0   (or0_out    , A2, A1             );
    nand nand0 (nand0_out_Y, C1, B1, D1, or0_out);
    buf  buf0  (Y          , nand0_out_Y        );

endmodule

sva:
module sky130_fd_sc_ms__o2111ai_sva (
    input logic clk,
    input logic Y,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic C1,
    input logic D1
);

    // Y must match the O2111AI Boolean function.
    check_y_matches_o2111ai_function: assert property (
        @(posedge clk) Y == ~(((A1 | A2) & B1 & C1 & D1))
    );

    // If every NAND input is high, Y must be low.
    check_y_low_when_all_terms_high: assert property (
        @(posedge clk) ((A1 | A2) & B1 & C1 & D1) |-> !Y
    );

    // A low Y means the OR term and all other NAND inputs are high.
    check_y_low_implies_all_terms_high: assert property (
        @(posedge clk) !Y |-> ((A1 | A2) & B1 & C1 & D1)
    );

    // If both A inputs are low, Y must be high.
    check_y_high_when_a_inputs_low: assert property (
        @(posedge clk) !(A1 | A2) |-> Y
    );

    // A low B1 forces Y high.
    check_y_high_when_b1_low: assert property (
        @(posedge clk) !B1 |-> Y
    );

    // A low C1 forces Y high.
    check_y_high_when_c1_low: assert property (
        @(posedge clk) !C1 |-> Y
    );

    // A low D1 forces Y high.
    check_y_high_when_d1_low: assert property (
        @(posedge clk) !D1 |-> Y
    );

endmodule

rtl:
module MEMWB_Stage(
    input  clock,
    input  reset,
    input  M_Flush,
    input  M_Stall,
    input  WB_Stall,
    // Control Signals
    input  M_RegWrite,
    input  M_MemtoReg,
    // Data Signals
    input  [31:0] M_ReadData,
    input  [31:0] M_ALU_Result,
    input  [4:0]  M_RtRd,
    // Voter Signals for Registers
    input WB_RegWrite,
    input WB_MemtoReg,
    input [31:0] WB_ReadData,
    input [31:0] WB_ALU_Result,
    input [4:0]  WB_RtRd,
    output reg vote_WB_RegWrite = 1'b0,
    output reg vote_WB_MemtoReg = 1'b0,
    output reg [31:0] vote_WB_ReadData = 32'b0,
    output reg [31:0] vote_WB_ALU_Result = 32'b0,
    output reg [4:0]  vote_WB_RtRd = 5'b0
);

    // Update the pipeline register
    always @(posedge clock) begin
        if (reset) begin
            vote_WB_RegWrite <= 1'b0;
            vote_WB_MemtoReg <= 1'b0;
            vote_WB_ReadData <= 32'b0;
            vote_WB_ALU_Result <= 32'b0;
            vote_WB_RtRd <= 5'b0;
        end
        else begin
            if (!WB_Stall) begin
                vote_WB_RegWrite <= WB_RegWrite;
                vote_WB_MemtoReg <= WB_MemtoReg;
                vote_WB_ReadData <= WB_ReadData;
                vote_WB_ALU_Result <= WB_ALU_Result;
                vote_WB_RtRd <= WB_RtRd;
            end
            else if (M_Stall | M_Flush) begin
                vote_WB_RegWrite <= 1'b0;
                vote_WB_MemtoReg <= 1'b0;
                vote_WB_ReadData <= 32'b0;
                vote_WB_ALU_Result <= 32'b0;
                vote_WB_RtRd <= 5'b0;
            end
            else begin
                vote_WB_RegWrite <= M_RegWrite;
                vote_WB_MemtoReg <= M_MemtoReg;
                vote_WB_ReadData <= M_ReadData;
                vote_WB_ALU_Result <= M_ALU_Result;
                vote_WB_RtRd <= M_RtRd;
            end
        end
    end

endmodule

sva:
module MEMWB_Stage_sva (
    input logic        clock,
    input logic        reset,
    input logic        M_Flush,
    input logic        M_Stall,
    input logic        WB_Stall,
    input logic        M_RegWrite,
    input logic        M_MemtoReg,
    input logic [31:0] M_ReadData,
    input logic [31:0] M_ALU_Result,
    input logic [4:0]  M_RtRd,
    input logic        WB_RegWrite,
    input logic        WB_MemtoReg,
    input logic [31:0] WB_ReadData,
    input logic [31:0] WB_ALU_Result,
    input logic [4:0]  WB_RtRd,
    input logic        vote_WB_RegWrite,
    input logic        vote_WB_MemtoReg,
    input logic [31:0] vote_WB_ReadData,
    input logic [31:0] vote_WB_ALU_Result,
    input logic [4:0]  vote_WB_RtRd
);

    // Reset clears all pipeline outputs on the next cycle.
    check_reset_clears_outputs: assert property (
        @(posedge clock)
        reset |=> (vote_WB_RegWrite  == 1'b0)  &&
                  (vote_WB_MemtoReg  == 1'b0)  &&
                  (vote_WB_ReadData  == 32'b0) &&
                  (vote_WB_ALU_Result == 32'b0) &&
                  (vote_WB_RtRd      == 5'b0)
    );

    // When WB is not stalled, control outputs capture WB inputs.
    check_wb_capture_control: assert property (
        @(posedge clock) disable iff (reset)
        (!WB_Stall) |=> (vote_WB_RegWrite == $past(WB_RegWrite)) &&
                        (vote_WB_MemtoReg == $past(WB_MemtoReg))
    );

    // When WB is not stalled, data outputs capture WB inputs.
    check_wb_capture_data: assert property (
        @(posedge clock) disable iff (reset)
        (!WB_Stall) |=> (vote_WB_ReadData   == $past(WB_ReadData)) &&
                        (vote_WB_ALU_Result == $past(WB_ALU_Result)) &&
                        (vote_WB_RtRd       == $past(WB_RtRd))
    );

    // When WB is stalled and M is stalled or flushed, control outputs clear.
    check_stall_flush_clear_control: assert property (
        @(posedge clock) disable iff (reset)
        (WB_Stall && (M_Stall || M_Flush)) |=> (vote_WB_RegWrite == 1'b0) &&
                                               (vote_WB_MemtoReg == 1'b0)
    );

    // When WB is stalled and M is stalled or flushed, data outputs clear.
    check_stall_flush_clear_data: assert property (
        @(posedge clock) disable iff (reset)
        (WB_Stall && (M_Stall || M_Flush)) |=> (vote_WB_ReadData   == 32'b0) &&
                                               (vote_WB_ALU_Result == 32'b0) &&
                                               (vote_WB_RtRd       == 5'b0)
    );

    // When only WB is stalled, control outputs capture M-stage inputs.
    check_m_capture_control: assert property (
        @(posedge clock) disable iff (reset)
        (WB_Stall && !M_Stall && !M_Flush) |=> (vote_WB_RegWrite == $past(M_RegWrite)) &&
                                               (vote_WB_MemtoReg == $past(M_MemtoReg))
    );

    // When only WB is stalled, data outputs capture M-stage inputs.
    check_m_capture_data: assert property (
        @(posedge clock) disable iff (reset)
        (WB_Stall && !M_Stall && !M_Flush) |=> (vote_WB_ReadData   == $past(M_ReadData)) &&
                                               (vote_WB_ALU_Result == $past(M_ALU_Result)) &&
                                               (vote_WB_RtRd       == $past(M_RtRd))
    );

endmodule

rtl:
module binary_adder (
    input A,
    input B,
    input CI,
    output SUM,
    output COUT_N,
    input VPB,
    input VPWR,
    input VGND,
    input VNB
);

wire a_xor_b = A ^ B;
wire sum = a_xor_b ^ CI;
wire carry_out = (A & B) | (a_xor_b & CI);

assign SUM = sum;
assign COUT_N = ~carry_out;

endmodule

sva:
module binary_adder_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic CI,
    input logic SUM,
    input logic COUT_N,
    input logic VPB,
    input logic VPWR,
    input logic VGND,
    input logic VNB
);

    // SUM matches the three-input XOR.
    check_sum_equation: assert property (
        @(posedge clk) SUM == (A ^ B ^ CI)
    );

    // COUT_N is the inverted full-adder carry.
    check_cout_n_equation: assert property (
        @(posedge clk) COUT_N == ~((A & B) | ((A ^ B) & CI))
    );

    // Outputs match the 2-bit arithmetic sum.
    check_full_adder_result: assert property (
        @(posedge clk) {~COUT_N, SUM} == ({1'b0, A} + {1'b0, B} + {1'b0, CI})
    );

    // With CI low, the block behaves as a half adder.
    check_half_adder_mode: assert property (
        @(posedge clk) !CI |-> (SUM == (A ^ B)) && (COUT_N == ~(A & B))
    );

    // With CI high, SUM inverts A^B and carry becomes A|B.
    check_carry_in_high_mode: assert property (
        @(posedge clk) CI |-> (SUM == ~(A ^ B)) && (COUT_N == ~(A | B))
    );

    // Zero inputs produce zero sum and no carry.
    check_zero_case: assert property (
        @(posedge clk) (!A && !B && !CI) |-> (!SUM && COUT_N)
    );

    // All-one inputs produce sum one with carry asserted.
    check_all_one_case: assert property (
        @(posedge clk) (A && B && CI) |-> (SUM && !COUT_N)
    );

    // Exactly one high input produces sum one and no carry.
    check_one_hot_case: assert property (
        @(posedge clk) (({1'b0, A} + {1'b0, B} + {1'b0, CI}) == 2'd1) |-> (SUM && COUT_N)
    );

    // Exactly two high inputs produce zero sum with carry asserted.
    check_two_hot_case: assert property (
        @(posedge clk) (({1'b0, A} + {1'b0, B} + {1'b0, CI}) == 2'd2) |-> (!SUM && !COUT_N)
    );

endmodule

