module sky130_fd_sc_ms__xnor3 (
    X,
    A,
    B,
    C
);

    output X;
    input  A;
    input  B;
    input  C;

    wire xnor0_out_X;

    xnor xnor0 (xnor0_out_X, A, B, C        );
