endmodule

sva:
module sky130_fd_sc_ms__xnor3_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic C,
    input logic X
);

    // X must implement the 3-input XNOR function.
    check_xnor_function: assert property (
        @(posedge clk) X == ~(A ^ B ^ C)
    );

    // All-zero inputs must drive X high.
    check_all_zero_drives_high: assert property (
        @(posedge clk) (!A && !B && !C) |-> X
    );

    // Exactly one high input must drive X low.
    check_single_one_drives_low: assert property (
        @(posedge clk)
        (( A && !B && !C) ||
         (!A &&  B && !C) ||
         (!A && !B &&  C)) |-> !X
    );

    // Exactly two high inputs must drive X high.
    check_double_one_drives_high: assert property (
        @(posedge clk)
        (( A &&  B && !C) ||
         ( A && !B &&  C) ||
         (!A &&  B &&  C)) |-> X
    );

    // All-one inputs must drive X low.
    check_all_one_drives_low: assert property (
        @(posedge clk) (A && B && C) |-> !X
    );

endmodule

rtl:
module dff_pn0 (input D, C, R, S, output Q);

    reg Q;

    always @(posedge C) begin
        if (!R) begin
            Q <= 0;
        end else if (S) begin
            Q <= 1;
        end else begin
            Q <= D;
        end
    end

endmodule

sva:
module dff_pn0_assertions (
    input logic D,
    input logic C,
    input logic R,
    input logic S,
    input logic Q
);

    // Active-low synchronous reset clears Q.
    check_reset_clears_q: assert property (
        @(posedge C) !R |=> (Q == 1'b0)
    );

    // With reset inactive, set forces Q high.
    check_set_forces_q_high: assert property (
        @(posedge C) disable iff (!R) S |=> (Q == 1'b1)
    );

    // With reset inactive and set low, D=0 is captured into Q.
    check_capture_d_zero: assert property (
        @(posedge C) disable iff (!R) (!S && !D) |=> (Q == 1'b0)
    );

    // With reset inactive and set low, D=1 is captured into Q.
    check_capture_d_one: assert property (
        @(posedge C) disable iff (!R) (!S && D) |=> (Q == 1'b1)
    );

endmodule

rtl:
module NAND8_reducer(
	InY,
	Reduced_NAND
);


input wire	[7:0] InY;
output wire	Reduced_NAND;

wire	SYNTHESIZED_WIRE_0;
wire	SYNTHESIZED_WIRE_1;
wire	SYNTHESIZED_WIRE_2;
wire	SYNTHESIZED_WIRE_3;
wire	SYNTHESIZED_WIRE_4;
wire	SYNTHESIZED_WIRE_5;
wire	SYNTHESIZED_WIRE_6;




assign	SYNTHESIZED_WIRE_5 = ~(InY[4] | InY[5]);

assign	SYNTHESIZED_WIRE_4 = ~(InY[2] | InY[3]);

assign	SYNTHESIZED_WIRE_2 =  ~InY[7];

assign	SYNTHESIZED_WIRE_3 = ~(InY[0] | InY[1]);

assign	Reduced_NAND = ~(SYNTHESIZED_WIRE_0 | SYNTHESIZED_WIRE_1);

assign	SYNTHESIZED_WIRE_6 = ~(InY[6] | SYNTHESIZED_WIRE_2);

assign	SYNTHESIZED_WIRE_0 = ~(SYNTHESIZED_WIRE_3 & SYNTHESIZED_WIRE_4);

assign	SYNTHESIZED_WIRE_1 = ~(SYNTHESIZED_WIRE_5 & SYNTHESIZED_WIRE_6);


endmodule

sva:
module NAND8_reducer_sva (
    input logic        clk,
    input logic [7:0]  InY,
    input logic        Reduced_NAND
);

    // Output matches the implemented combinational function.
    check_reduced_nand_matches_function: assert property (
        @(posedge clk) Reduced_NAND == (InY == 8'b1000_0000)
    );

    // A high output only occurs for input 8'b10000000.
    check_high_output_requires_exact_pattern: assert property (
        @(posedge clk) Reduced_NAND |-> (InY == 8'b1000_0000)
    );

    // Input 8'b10000000 must drive the output high.
    check_exact_pattern_drives_high_output: assert property (
        @(posedge clk) (InY == 8'b1000_0000) |-> Reduced_NAND
    );

    // Any other input pattern must drive the output low.
    check_nonmatching_pattern_drives_low_output: assert property (
        @(posedge clk) (InY != 8'b1000_0000) |-> !Reduced_NAND
    );

    // Any asserted lower input bit forces the output low.
    check_lower_bits_force_low_output: assert property (
        @(posedge clk) (|InY[6:0]) |-> !Reduced_NAND
    );

    // A low MSB forces the output low.
    check_msb_low_forces_low_output: assert property (
        @(posedge clk) !InY[7] |-> !Reduced_NAND
    );

endmodule

rtl:
module oh_mux #( parameter DW  = 1, parameter N   = 1  )
   (
    input [N-1:0]    sel, input [N*DW-1:0] in, output [DW-1:0]  out  );

   reg [DW-1:0]     mux;

   integer 	    i;   
   always @*
     begin
	mux[DW-1:0] = 'b0;
	for(i=0;i<N;i=i+1)
	  mux[DW-1:0] = mux[DW-1:0] | {(DW){sel[i]}} & in[((i+1)*DW-1)-:DW];
     end

   assign out[DW-1:0] = mux;

endmodule

sva:
module oh_mux_sva #(parameter DW = 1, parameter N = 1) (
    input logic [N-1:0]    sel,
    input logic [N*DW-1:0] in,
    input logic [DW-1:0]   out
);

    function automatic [DW-1:0] expected_out (
        input logic [N-1:0]    s,
        input logic [N*DW-1:0] d
    );
        integer k;
        begin
            expected_out = '0;
            for (k = 0; k < N; k = k + 1)
                expected_out = expected_out | ({DW{s[k]}} & d[((k+1)*DW-1)-:DW]);
        end
    endfunction

    // Output equals the OR of all selected input words.
    check_output_equation: assert property (
        @($global_clock) out == expected_out(sel, in)
    );

    // With no select bits set, the output is zero.
    check_no_select_zero: assert property (
        @($global_clock) (sel == '0) |-> (out == '0)
    );

    // A zero input bus forces a zero output.
    check_zero_input_zero_output: assert property (
        @($global_clock) (in == '0) |-> (out == '0)
    );

    // Stable inputs keep the output stable.
    check_stable_inputs_stable_output: assert property (
        @($global_clock) ($stable(sel) && $stable(in)) |-> $stable(out)
    );

    genvar i;
    generate
        for (i = 0; i < N; i = i + 1) begin : gen_onehot_checks
            // With only this select bit set, output matches this input word.
            check_onehot_select: assert property (
                @($global_clock) (sel[i] && $onehot(sel)) |-> (out == in[((i+1)*DW-1)-:DW])
            );
        end
    endgenerate

endmodule

rtl:
module dff_with_async_set_reset(input D, SET, RESET, CLK, output Q);

    reg Q_reg = 0;

    always @(posedge CLK) // , posedge SET, negedge RESET)
    begin
        if (SET)
            Q_reg <= 1'b1;
        else if(RESET)
            Q_reg <= 1'b0;
        else
            Q_reg <= D;
    end

    assign Q = Q_reg;

endmodule

sva:
module dff_with_async_set_reset_assertions (
    input logic D,
    input logic SET,
    input logic RESET,
    input logic CLK,
    input logic Q
);

    // CLK is the only clock; SET and RESET are synchronous active-high controls.
    // There is no separate assertion reset in this RTL.

    // Q starts low because Q_reg is initialized to 0.
    check_init_low: assert property (
        @(posedge CLK) disable iff (1'b0) $initstate |-> (Q == 1'b0)
    );

    // SET has highest priority and drives Q high on the next sampled cycle.
    check_set_forces_one: assert property (
        @(posedge CLK) disable iff (1'b0) SET |=> (Q == 1'b1)
    );

    // RESET drives Q low on the next sampled cycle when SET is low.
    check_reset_forces_zero: assert property (
        @(posedge CLK) disable iff (1'b0) (!SET && RESET) |=> (Q == 1'b0)
    );

    // With both controls low, Q captures D on the next sampled cycle.
    check_data_capture: assert property (
        @(posedge CLK) disable iff (1'b0) (!SET && !RESET) |=> (Q == $past(D))
    );

    // When both controls are high, SET takes priority over RESET.
    check_set_priority_over_reset: assert property (
        @(posedge CLK) disable iff (1'b0) (SET && RESET) |=> (Q == 1'b1)
    );

    // A rising Q must come from SET or from capturing a 1 on D.
    check_rise_has_valid_cause: assert property (
        @(posedge CLK) disable iff (1'b0)
        (!$initstate && $rose(Q)) |-> ($past(SET) || (!$past(SET) && !$past(RESET) && $past(D)))
    );

    // A falling Q must come from RESET or from capturing a 0 on D.
    check_fall_has_valid_cause: assert property (
        @(posedge CLK) disable iff (1'b0)
        (!$initstate && $fell(Q)) |-> (!$past(SET) && ($past(RESET) || (!$past(RESET) && !$past(D))))
    );

endmodule

rtl:
module mux4to1 (
    input A,
    input B,
    input C,
    input D,
    input S0,
    input S1,
    output Y
);

    wire notS0, notS1;

    assign notS0 = ~S0;
    assign notS1 = ~S1;

    wire AB, CD;

    assign AB = S0 & notS1;
    assign CD = notS0 & S1;

    assign Y = (A & notS0 & notS1) | (B & AB) | (C & CD) | (D & S0 & S1);

endmodule

sva:
module mux4to1_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic S0,
    input logic S1,
    input logic Y
);

    // Y must match the implemented 4-to-1 mux equation.
    check_mux_equation: assert property (
        @(posedge clk)
        Y == ((A & ~S0 & ~S1) | (B & S0 & ~S1) | (C & ~S0 & S1) | (D & S0 & S1))
    );

    // Select 2'b00 routes A to Y.
    check_select_00_routes_a: assert property (
        @(posedge clk)
        (!S1 && !S0) |-> (Y == A)
    );

    // Select 2'b01 routes B to Y.
    check_select_01_routes_b: assert property (
        @(posedge clk)
        (!S1 && S0) |-> (Y == B)
    );

    // Select 2'b10 routes C to Y.
    check_select_10_routes_c: assert property (
        @(posedge clk)
        (S1 && !S0) |-> (Y == C)
    );

    // Select 2'b11 routes D to Y.
    check_select_11_routes_d: assert property (
        @(posedge clk)
        (S1 && S0) |-> (Y == D)
    );

endmodule

rtl:
module add_sub_4bit(A, B, sub, result);

input [3:0] A, B;
input sub;
output [3:0] result;

wire [3:0] B_neg;
assign B_neg = (~B) + 1; //2's complement of B

//subtract B from A if sub is 1, else add A and B
assign result = sub ? A + B_neg : A + B;

endmodule

sva:
module add_sub_4bit_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic       sub,
    input logic [3:0] result
);

    // The output must follow the RTL's add/sub select equation.
    check_selected_operation_equation: assert property (
        @($global_clock) result == (sub ? (A + ((~B) + 4'd1)) : (A + B))
    );

    // In add mode, result must be the 4-bit sum of A and B.
    check_add_mode_result: assert property (
        @($global_clock) !sub |-> (result == (A + B))
    );

    // In subtract mode, result must be the 4-bit difference A - B.
    check_sub_mode_result: assert property (
        @($global_clock) sub |-> (result == (A - B))
    );

    // Adding zero on B must leave A unchanged.
    check_add_zero_b_passthrough_a: assert property (
        @($global_clock) (!sub && (B == 4'd0)) |-> (result == A)
    );

    // Adding with A at zero must pass B through.
    check_add_zero_a_passthrough_b: assert property (
        @($global_clock) (!sub && (A == 4'd0)) |-> (result == B)
    );

    // Subtracting zero on B must leave A unchanged.
    check_sub_zero_b_passthrough_a: assert property (
        @($global_clock) (sub && (B == 4'd0)) |-> (result == A)
    );

    // Subtracting equal operands must produce zero.
    check_sub_equal_operands_zero: assert property (
        @($global_clock) (sub && (A == B)) |-> (result == 4'd0)
    );

    // With A at zero, subtraction must produce the 2's complement of B.
    check_sub_zero_a_twos_complement_b: assert property (
        @($global_clock) (sub && (A == 4'd0)) |-> (result == ((~B) + 4'd1))
    );

    // 4-bit addition must wrap on overflow.
    check_add_overflow_wraparound: assert property (
        @($global_clock) (!sub && (A == 4'hF) && (B == 4'd1)) |-> (result == 4'd0)
    );

    // 4-bit subtraction must wrap on underflow.
    check_sub_underflow_wraparound: assert property (
        @($global_clock) (sub && (A == 4'd0) && (B == 4'd1)) |-> (result == 4'hF)
    );

endmodule

