module and_gate (
    // Inputs
    input A,
    input B,

    // Outputs
    output Y
);

    assign Y = ~(~A | ~B);

endmodule

sva:
module and_gate_sva (
    input logic A,
    input logic B,
    input logic Y
);

    // No clock/reset in RTL; sample on any input or output edge.
    // Y must implement the AND of A and B.
    check_output_matches_and_function: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge Y or negedge Y)
        Y == (A & B)
    );

    // If either input is low, Y must be low.
    check_low_input_forces_output_low: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge Y or negedge Y)
        ((!A) || (!B)) |-> (!Y)
    );

    // Y can only be high when both inputs are high.
    check_output_high_requires_both_inputs_high: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge Y or negedge Y)
        Y |-> (A && B)
    );

    // Both inputs high must drive Y high.
    check_both_inputs_high_drive_output_high: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge Y or negedge Y)
        (A && B) |-> Y
    );

endmodule

rtl:
module clock_gate (
  input CLK, EN, TE,
  output ENCLK
);

  wire gated_clk;
  reg ENCLK_reg; // Declare ENCLK_reg as a register

  // Gating logic
  assign gated_clk = (TE) ? CLK : (EN) ? CLK : 1'b0;

  // D flip-flop with enable
  always @(posedge CLK) begin
    if (EN) begin
      ENCLK_reg <= gated_clk; // Use ENCLK_reg as the l-value
    end
  end

  // Output assignment
  assign ENCLK = ENCLK_reg;

endmodule

sva:
module clock_gate_sva (
    input logic CLK,
    input logic EN,
    input logic TE,
    input logic ENCLK
);

    // EN high causes the registered output to be high by the next sampled cycle.
    check_en_sets_output_high: assert property (
        @(posedge CLK) EN |=> (ENCLK == 1'b1)
    );

    // EN low means the register is not updated, so the output holds its value.
    check_output_holds_when_disabled: assert property (
        @(posedge CLK) !EN |=> $stable(ENCLK)
    );

    // TE alone does not update the output when EN is low.
    check_te_has_no_effect_without_en: assert property (
        @(posedge CLK) (TE && !EN) |=> $stable(ENCLK)
    );

    // Any output rise must come from EN being high on the previous clock edge.
    check_rise_requires_prior_enable: assert property (
        @(posedge CLK) $rose(ENCLK) |-> $past(EN)
    );

    // Once the output is high, the RTL has no path that can drive it low.
    check_output_stays_high_once_set: assert property (
        @(posedge CLK) (ENCLK == 1'b1) |=> (ENCLK == 1'b1)
    );

endmodule

rtl:
module next_highest (
    input [3:0] in,
    input clk,
    output reg [3:0] out
);

reg [3:0] stage1_out;
reg [3:0] stage2_out;

always @(*) begin
    stage1_out = in + 1;
end

always @(*) begin
    if (stage1_out == 4'b1111) begin
        stage2_out = 4'b0000;
    end else begin
        stage2_out = stage1_out;
    end
end

always @(posedge clk) begin
    out <= stage2_out;
end

endmodule

sva:
module next_highest_sva (
    input logic [3:0] in,
    input logic clk,
    input logic [3:0] out
);

    // Clock: clk; no reset in RTL; logic is combinational pre-processing plus a registered output.
    function automatic logic [3:0] rtl_result(input logic [3:0] val);
        logic [3:0] stage1_calc;
        begin
            stage1_calc = val + 4'd1;
            if (stage1_calc == 4'hf)
                rtl_result = 4'h0;
            else
                rtl_result = stage1_calc;
        end
    endfunction

    // Output updates on the next clock to the value computed from the sampled input.
    check_registered_transfer: assert property (
        @(posedge clk) 1'b1 |=> (out == rtl_result($past(in)))
    );

    // Inputs 0 through 13 increment by one on the next clock.
    check_low_range_increment: assert property (
        @(posedge clk) (in <= 4'd13) |=> (out == ($past(in) + 4'd1))
    );

    // Input 13 reaches the upper non-zero boundary value 14 on the next clock.
    check_input_13_to_14: assert property (
        @(posedge clk) (in == 4'd13) |=> (out == 4'd14)
    );

    // Input 14 produces zero on the next clock because stage1 hits 4'hf.
    check_input_14_to_zero: assert property (
        @(posedge clk) (in == 4'd14) |=> (out == 4'd0)
    );

    // Input 15 also produces zero on the next clock because the 4-bit increment wraps.
    check_input_15_to_zero: assert property (
        @(posedge clk) (in == 4'd15) |=> (out == 4'd0)
    );

    // The registered output can never be 4'hf after a clocked update.
    check_output_never_fifteen: assert property (
        @(posedge clk) 1'b1 |=> (out != 4'hf)
    );

    // Zero output occurs only when the previously sampled input was 14 or 15.
    check_zero_output_source: assert property (
        @(posedge clk) 1'b1 |=> ((out == 4'd0) == (($past(in) == 4'd14) || ($past(in) == 4'd15)))
    );

endmodule

module dectohexstr24_sva (
    input logic clk,
    input logic [23:0] in,
    input logic [127:0] out
);

    function automatic logic [7:0] hex_ascii(input logic [3:0] nib);
        hex_ascii = (nib == 4'd0)  ? "0" :
                    (nib == 4'd1)  ? "1" :
                    (nib == 4'd2)  ? "2" :
                    (nib == 4'd3)  ? "3" :
                    (nib == 4'd4)  ? "4" :
                    (nib == 4'd5)  ? "5" :
                    (nib == 4'd6)  ? "6" :
                    (nib == 4'd7)  ? "7" :
                    (nib == 4'd8)  ? "8" :
                    (nib == 4'd9)  ? "9" :
                    (nib == 4'd10) ? "A" :
                    (nib == 4'd11) ? "B" :
                    (nib == 4'd12) ? "C" :
                    (nib == 4'd13) ? "D" :
                    (nib == 4'd14) ? "E" : "F";
    endfunction

    // Upper ten bytes are constant space padding.
    check_upper_space_padding: assert property (
        @(posedge clk) out[127:48] === 80'h20202020202020202020
    );

    // Output [15:0] is the ASCII hex encoding of input byte [7:0].
    check_low_byte_ascii_hex: assert property (
        @(posedge clk) out[15:0] === {hex_ascii(in[7:4]), hex_ascii(in[3:0])}
    );

    // Output [31:16] is the ASCII hex encoding of input byte [15:8].
    check_middle_byte_ascii_hex: assert property (
        @(posedge clk) out[31:16] === {hex_ascii(in[15:12]), hex_ascii(in[11:8])}
    );

    // Output [47:32] is the ASCII hex encoding of input byte [23:16].
    check_high_byte_ascii_hex: assert property (
        @(posedge clk) out[47:32] === {hex_ascii(in[23:20]), hex_ascii(in[19:16])}
    );

endmodule

rtl:
module mux4to1 (
    input [3:0] data_in,
    input [1:0] sel,
    output reg data_out
);

    reg data_out_temp0;
    reg data_out_temp1;

    // Instantiate the two 2:1 multiplexers
    mux2to1 mux0 (
        .data_0(data_in[0]),
        .data_1(data_in[1]),
        .sel(sel[0]),
        .data_out(data_out_temp0)
    );
    mux2to1 mux1 (
        .data_0(data_in[2]),
        .data_1(data_in[3]),
        .sel(sel[0]),
        .data_out(data_out_temp1)
    );

    // Instantiate another 2:1 multiplexer to select the output of the two 2:1 multiplexers
    mux2to1 mux2 (
        .data_0(data_out_temp0),
        .data_1(data_out_temp1),
        .sel(sel[1]),
        .data_out(data_out)
    );

endmodule
module mux2to1 (
    input data_0,
    input data_1,
    input sel,
    output reg data_out
);

    always @(*) begin
        case (sel)
            1'b0: data_out = data_0;
            1'b1: data_out = data_1;
        endcase
    end

endmodule

sva:
module mux4to1_sva (
    input logic       clk,
    input logic [3:0] data_in,
    input logic [1:0] sel,
    input logic       data_out,
    input logic       data_out_temp0,
    input logic       data_out_temp1
);

    // Combinational RTL with no native reset; sample on an external clock.

    // Lower 2:1 mux routes data_in[0] when sel[0] is low.
    check_temp0_selects_data0: assert property (
        @(posedge clk) (sel[0] == 1'b0) |-> (data_out_temp0 == data_in[0])
    );

    // Lower 2:1 mux routes data_in[1] when sel[0] is high.
    check_temp0_selects_data1: assert property (
        @(posedge clk) (sel[0] == 1'b1) |-> (data_out_temp0 == data_in[1])
    );

    // Upper 2:1 mux routes data_in[2] when sel[0] is low.
    check_temp1_selects_data2: assert property (
        @(posedge clk) (sel[0] == 1'b0) |-> (data_out_temp1 == data_in[2])
    );

    // Upper 2:1 mux routes data_in[3] when sel[0] is high.
    check_temp1_selects_data3: assert property (
        @(posedge clk) (sel[0] == 1'b1) |-> (data_out_temp1 == data_in[3])
    );

    // Final 2:1 mux routes data_out_temp0 when sel[1] is low.
    check_output_selects_temp0: assert property (
        @(posedge clk) (sel[1] == 1'b0) |-> (data_out == data_out_temp0)
    );

    // Final 2:1 mux routes data_out_temp1 when sel[1] is high.
    check_output_selects_temp1: assert property (
        @(posedge clk) (sel[1] == 1'b1) |-> (data_out == data_out_temp1)
    );

    // Top-level mux routes data_in[0] for select 2'b00.
    check_sel_00_routes_data0: assert property (
        @(posedge clk) (sel == 2'b00) |-> (data_out == data_in[0])
    );

    // Top-level mux routes data_in[1] for select 2'b01.
    check_sel_01_routes_data1: assert property (
        @(posedge clk) (sel == 2'b01) |-> (data_out == data_in[1])
    );

    // Top-level mux routes data_in[2] for select 2'b10.
    check_sel_10_routes_data2: assert property (
        @(posedge clk) (sel == 2'b10) |-> (data_out == data_in[2])
    );

    // Top-level mux routes data_in[3] for select 2'b11.
    check_sel_11_routes_data3: assert property (
        @(posedge clk) (sel == 2'b11) |-> (data_out == data_in[3])
    );

endmodule

rtl:
`ifndef _regr
`define _regr

module regr (clk, rst, clear, hold, in, out);

   parameter N = 1;

   input       clk;
   input       rst;
   input       clear;
   input       hold;   
   input wire [N-1:0]      in;
   output reg [N-1:0]      out;

	always @(posedge clk, negedge rst) begin
	   if (!rst) begin
	      out <= {N{1'b0}};
	   end
	   else if (clear) begin
	     out <= {N{1'b0}};
	   end
	   else if (hold) begin
	     out <= out;
	   end
	   else begin
	     out <= in;
	   end
	end
endmodule

`endif

sva:
module regr_sva #(parameter N = 1) (
    input logic         clk,
    input logic         rst,
    input logic         clear,
    input logic         hold,
    input logic [N-1:0] in,
    input logic [N-1:0] out
);

    // Active-low reset clears the register by the next sampled cycle.
    check_reset_forces_zero: assert property (
        @(posedge clk)
        !rst |=> (out == {N{1'b0}})
    );

    // Clear drives the register to zero.
    check_clear_forces_zero: assert property (
        @(posedge clk) disable iff (!rst)
        clear |=> (out == {N{1'b0}})
    );

    // Clear takes priority over hold.
    check_clear_overrides_hold: assert property (
        @(posedge clk) disable iff (!rst)
        (clear && hold) |=> (out == {N{1'b0}})
    );

    // Hold preserves the current register value when clear is low.
    check_hold_preserves_value: assert property (
        @(posedge clk) disable iff (!rst)
        (hold && !clear) |=> (out == $past(out))
    );

    // With neither clear nor hold, the input is captured.
    check_load_captures_input: assert property (
        @(posedge clk) disable iff (!rst)
        (!clear && !hold) |=> (out == $past(in))
    );

endmodule

rtl:
module input_output(
    input        clk,
    input  [6:0] a,
    input        a_msb,              
    output [14:0] b,              
    output       b_msb            
);

    wire c;

    reg [15:0] b_reg = 0;      

    assign c = a_msb & b_reg[0];

    always @(posedge clk) begin
        b_reg <= b_reg + {a_msb ? {8'd255, a} : {8'd0, a}};
    end

    assign b_msb = b_reg[15];
    assign b = {b_reg[14:0], c};

endmodule

sva:
module input_output_sva (
    input logic        clk,
    input logic [6:0]  a,
    input logic        a_msb,
    input logic [14:0] b,
    input logic        b_msb
);

    // b[0] is a_msb gated by the stored LSB carried on b[1].
    check_b_lsb_gate: assert property (
        @(posedge clk) b[0] == (a_msb & b[1])
    );

    // With a_msb low, the observable accumulator slice adds zero-extended a.
    check_slice_update_no_extend: assert property (
        @(posedge clk) (!a_msb) |=> (b[14:1] == ($past(b[14:1]) + {7'h00, $past(a)}))
    );

    // With a_msb high, the observable accumulator slice adds {7'h7F, a}.
    check_slice_update_with_extend: assert property (
        @(posedge clk) (a_msb) |=> (b[14:1] == ($past(b[14:1]) + {7'h7F, $past(a)}))
    );

    // The stored bit0, exposed on b[1], updates with the previous a[0].
    check_state_bit0_update: assert property (
        @(posedge clk) 1'b1 |=> (b[1] == ($past(b[1]) ^ $past(a[0])))
    );

    // A non-extended add without low-14 overflow leaves b_msb unchanged.
    check_b_msb_hold_without_low14_carry: assert property (
        @(posedge clk) ((!a_msb) && (({1'b0, b[14:1]} + {8'h00, a}) < 15'h4000)) |=> (b_msb == $past(b_msb))
    );

endmodule

rtl:
module shift_register (
    input CLK,
    input LOAD,
    input SHIFT,
    input [3:0] DATA_IN,
    output [3:0] DATA_OUT
);

reg [3:0] shift_reg;

always @(posedge CLK) begin
    if (LOAD) begin
        shift_reg <= DATA_IN;
    end else if (SHIFT) begin
        shift_reg <= {shift_reg[2:0], shift_reg[3]};
    end
end

assign DATA_OUT = shift_reg;

endmodule

sva:
module shift_register_sva (
    input logic       CLK,
    input logic       LOAD,
    input logic       SHIFT,
    input logic [3:0] DATA_IN,
    input logic [3:0] DATA_OUT
);

    // LOAD captures DATA_IN into the register on the next cycle.
    check_load_captures_data: assert property (
        @(posedge CLK)
        LOAD |=> (DATA_OUT == $past(DATA_IN))
    );

    // SHIFT rotates the stored value left when LOAD is low.
    check_shift_rotates_data: assert property (
        @(posedge CLK)
        (!LOAD && SHIFT) |=> (DATA_OUT == {$past(DATA_OUT[2:0]), $past(DATA_OUT[3])})
    );

    // The register holds its value when neither control is asserted.
    check_hold_without_control: assert property (
        @(posedge CLK)
        (!LOAD && !SHIFT) |=> (DATA_OUT == $past(DATA_OUT))
    );

    // LOAD takes priority over SHIFT when both are asserted.
    check_load_priority_over_shift: assert property (
        @(posedge CLK)
        (LOAD && SHIFT) |=> (DATA_OUT == $past(DATA_IN))
    );

endmodule

rtl:
module sky130_fd_sc_lp__and4bb (
    X  ,
    A_N,
    B_N,
    C  ,
    D
);

    output X  ;
    input  A_N;
    input  B_N;
    input  C  ;
    input  D  ;

    wire nor0_out  ;
    wire and0_out_X;

    nor nor0 (nor0_out  , A_N, B_N       );
    and and0 (and0_out_X, nor0_out, C, D );
    buf buf0 (X         , and0_out_X     );

endmodule

sva:
module sky130_fd_sc_lp__and4bb_sva (
    input logic clk,
    input logic X,
    input logic A_N,
    input logic B_N,
    input logic C,
    input logic D
);

    // No clock or reset exists in the RTL; clk is only for assertion sampling.

    // X must match the implemented combinational equation.
    check_boolean_function: assert property (
        @(posedge clk) X == ((~A_N) & (~B_N) & C & D)
    );

    // X can only be high when all enabling inputs are active.
    check_x_only_when_all_inputs_enable: assert property (
        @(posedge clk) X |-> ((A_N == 1'b0) && (B_N == 1'b0) && (C == 1'b1) && (D == 1'b1))
    );

    // X must be high when both active-low inputs are low and C and D are high.
    check_x_high_when_all_inputs_enable: assert property (
        @(posedge clk) ((A_N == 1'b0) && (B_N == 1'b0) && (C == 1'b1) && (D == 1'b1)) |-> (X == 1'b1)
    );

    // A_N high forces the NOR output low, so X must be low.
    check_a_n_high_forces_x_low: assert property (
        @(posedge clk) (A_N == 1'b1) |-> (X == 1'b0)
    );

    // B_N high forces the NOR output low, so X must be low.
    check_b_n_high_forces_x_low: assert property (
        @(posedge clk) (B_N == 1'b1) |-> (X == 1'b0)
    );

    // C low forces the AND output low, so X must be low.
    check_c_low_forces_x_low: assert property (
        @(posedge clk) (C == 1'b0) |-> (X == 1'b0)
    );

    // D low forces the AND output low, so X must be low.
    check_d_low_forces_x_low: assert property (
        @(posedge clk) (D == 1'b0) |-> (X == 1'b0)
    );

endmodule

rtl:
module taxicab_distance #(parameter N = 32)(
	input [N-1:0] x1, y1, x2, y2,
	output [N+1:0] dist
);

wire signed [N:0] dist_x12, dist_x21, dist_xabs, dist_y12, dist_y21, dist_yabs;

// Calculate the absolute difference between x1 and x2
assign dist_x12 = x1 - x2;
// Calculate the absolute difference between x2 and x1
assign dist_x21 = x2 - x1;

// Select the absolute difference between x1 and x2 if x1 > x2, otherwise select the absolute difference between x2 and x1
assign dist_xabs = (x1 > x2) ? dist_x12 : dist_x21;

// Calculate the absolute difference between y1 and y2
assign dist_y12 = y1 - y2;
// Calculate the absolute difference between y2 and y1
assign dist_y21 = y2 - y1;

// Select the absolute difference between y1 and y2 if y1 > y2, otherwise select the absolute difference between y2 and y1
assign dist_yabs = (y1 > y2) ? dist_y12 : dist_y21;

// Calculate the taxicab distance by adding the absolute differences of x and y coordinates
assign dist = dist_xabs + dist_yabs;

endmodule

sva:
module taxicab_distance_sva #(parameter N = 32) (
    input logic [N-1:0] x1,
    input logic [N-1:0] y1,
    input logic [N-1:0] x2,
    input logic [N-1:0] y2,
    input logic [N+1:0] dist
);

    function automatic logic signed [N:0] abs_diff_rtl (
        input logic [N-1:0] a,
        input logic [N-1:0] b
    );
        logic signed [N:0] d_ab;
        logic signed [N:0] d_ba;
        begin
            d_ab = a - b;
            d_ba = b - a;
            abs_diff_rtl = (a > b) ? d_ab : d_ba;
        end
    endfunction

    function automatic logic [N+1:0] dist_rtl (
        input logic [N-1:0] fx1,
        input logic [N-1:0] fy1,
        input logic [N-1:0] fx2,
        input logic [N-1:0] fy2
    );
        logic signed [N:0] xabs;
        logic signed [N:0] yabs;
        begin
            xabs = abs_diff_rtl(fx1, fx2);
            yabs = abs_diff_rtl(fy1, fy2);
            dist_rtl = xabs + yabs;
        end
    endfunction

    function automatic logic [N+1:0] branch_dist_x1_gt_x2_y1_gt_y2 (
        input logic [N-1:0] fx1,
        input logic [N-1:0] fy1,
        input logic [N-1:0] fx2,
        input logic [N-1:0] fy2
    );
        logic signed [N:0] dx;
        logic signed [N:0] dy;
        begin
            dx = fx1 - fx2;
            dy = fy1 - fy2;
            branch_dist_x1_gt_x2_y1_gt_y2 = dx + dy;
        end
    endfunction

    function automatic logic [N+1:0] branch_dist_x1_gt_x2_y1_le_y2 (
        input logic [N-1:0] fx1,
        input logic [N-1:0] fy1,
        input logic [N-1:0] fx2,
        input logic [N-1:0] fy2
    );
        logic signed [N:0] dx;
        logic signed [N:0] dy;
        begin
            dx = fx1 - fx2;
            dy = fy2 - fy1;
            branch_dist_x1_gt_x2_y1_le_y2 = dx + dy;
        end
    endfunction

    function automatic logic [N+1:0] branch_dist_x1_le_x2_y1_gt_y2 (
        input logic [N-1:0] fx1,
        input logic [N-1:0] fy1,
        input logic [N-1:0] fx2,
        input logic [N-1:0] fy2
    );
        logic signed [N:0] dx;
        logic signed [N:0] dy;
        begin
            dx = fx2 - fx1;
            dy = fy1 - fy2;
            branch_dist_x1_le_x2_y1_gt_y2 = dx + dy;
        end
    endfunction

    function automatic logic [N+1:0] branch_dist_x1_le_x2_y1_le_y2 (
        input logic [N-1:0] fx1,
        input logic [N-1:0] fy1,
        input logic [N-1:0] fx2,
        input logic [N-1:0] fy2
    );
        logic signed [N:0] dx;
        logic signed [N:0] dy;
        begin
            dx = fx2 - fx1;
            dy = fy2 - fy1;
            branch_dist_x1_le_x2_y1_le_y2 = dx + dy;
        end
    endfunction

    // No clock or reset exists in the RTL; sample on the formal global clock.

    // Output matches the implemented combinational arithmetic.
    check_dist_matches_rtl: assert property (
        @($global_clock) dist == dist_rtl(x1, y1, x2, y2)
    );

    // Identical points produce zero distance.
    check_zero_when_points_equal: assert property (
        @($global_clock) ((x1 == x2) && (y1 == y2)) |-> (dist == '0)
    );

    // Equal x coordinates leave only the y-axis difference.
    check_y_only_when_x_equal: assert property (
        @($global_clock) (x1 == x2) |-> (dist == dist_rtl({N{1'b0}}, y1, {N{1'b0}}, y2))
    );

    // Equal y coordinates leave only the x-axis difference.
    check_x_only_when_y_equal: assert property (
        @($global_clock) (y1 == y2) |-> (dist == dist_rtl(x1, {N{1'b0}}, x2, {N{1'b0}}))
    );

    // When x1>x2 and y1>y2, both forward differences are selected.
    check_branch_x1_gt_x2_y1_gt_y2: assert property (
        @($global_clock) ((x1 > x2) && (y1 > y2)) |-> (dist == branch_dist_x1_gt_x2_y1_gt_y2(x1, y1, x2, y2))
    );

    // When x1>x2 and y1<=y2, x forward and y reverse differences are selected.
    check_branch_x1_gt_x2_y1_le_y2: assert property (
        @($global_clock) ((x1 > x2) && (y1 <= y2)) |-> (dist == branch_dist_x1_gt_x2_y1_le_y2(x1, y1, x2, y2))
    );

    // When x1<=x2 and y1>y2, x reverse and y forward differences are selected.
    check_branch_x1_le_x2_y1_gt_y2: assert property (
        @($global_clock) ((x1 <= x2) && (y1 > y2)) |-> (dist == branch_dist_x1_le_x2_y1_gt_y2(x1, y1, x2, y2))
    );

    // When x1<=x2 and y1<=y2, both reverse differences are selected.
    check_branch_x1_le_x2_y1_le_y2: assert property (
        @($global_clock) ((x1 <= x2) && (y1 <= y2)) |-> (dist == branch_dist_x1_le_x2_y1_le_y2(x1, y1, x2, y2))
    );

    // Swapping the two endpoints leaves the computed distance unchanged.
    check_endpoint_swap_symmetry: assert property (
        @($global_clock) dist == dist_rtl(x2, y2, x1, y1)
    );

    // Swapping x and y roles leaves the computed distance unchanged.
    check_axis_swap_symmetry: assert property (
        @($global_clock) dist == dist_rtl(y1, x1, y2, x2)
    );

endmodule

rtl:
module half_subtractor (
  input A,
  input B,
  output DIFF,
  output BORROW
);

  assign DIFF = A ^ B;
  assign BORROW = A < B;

endmodule

module full_subtractor (
  input A,
  input B,
  input BORROW_IN,
  output DIFF,
  output BORROW
);

  wire DIFF1, BORROW1, DIFF2, BORROW2;

  half_subtractor HS1(.A(A), .B(B), .DIFF(DIFF1), .BORROW(BORROW1));
  half_subtractor HS2(.A(DIFF1), .B(BORROW_IN), .DIFF(DIFF2), .BORROW(BORROW2));

  assign DIFF = DIFF2;
  assign BORROW = BORROW1 | BORROW2;

endmodule

sva:
module half_subtractor_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic DIFF,
    input logic BORROW
);

    // DIFF is the XOR of A and B.
    check_diff_is_xor: assert property (
        @(posedge clk) disable iff (1'b0)
        DIFF == (A ^ B)
    );

    // BORROW matches the single-bit less-than result.
    check_borrow_is_less_than: assert property (
        @(posedge clk) disable iff (1'b0)
        BORROW == (A < B)
    );

    // When B is low, DIFF follows A and BORROW stays low.
    check_b_zero_behavior: assert property (
        @(posedge clk) disable iff (1'b0)
        !B |-> ((DIFF == A) && (BORROW == 1'b0))
    );

    // Subtracting 1 from 0 produces DIFF high with BORROW high.
    check_zero_minus_one_case: assert property (
        @(posedge clk) disable iff (1'b0)
        (!A && B) |-> ((DIFF == 1'b1) && (BORROW == 1'b1))
    );

endmodule

module full_subtractor_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic BORROW_IN,
    input logic DIFF,
    input logic BORROW
);

    // DIFF is the cascaded XOR of A, B, and BORROW_IN.
    check_diff_is_three_input_xor: assert property (
        @(posedge clk) disable iff (1'b0)
        DIFF == (A ^ B ^ BORROW_IN)
    );

    // BORROW is the OR of the two half-subtractor borrow terms.
    check_borrow_matches_composed_equation: assert property (
        @(posedge clk) disable iff (1'b0)
        BORROW == ((A < B) | ((A ^ B) < BORROW_IN))
    );

    // With no borrow-in, behavior reduces to subtracting B from A.
    check_no_borrow_in_reduces_to_half_subtractor: assert property (
        @(posedge clk) disable iff (1'b0)
        !BORROW_IN |-> ((DIFF == (A ^ B)) && (BORROW == (A < B)))
    );

    // With B low, behavior reduces to subtracting BORROW_IN from A.
    check_b_zero_reduces_to_a_minus_borrow_in: assert property (
        @(posedge clk) disable iff (1'b0)
        !B |-> ((DIFF == (A ^ BORROW_IN)) && (BORROW == (!A && BORROW_IN)))
    );

    // When A is low and B is high, a borrow is always generated.
    check_zero_minus_one_always_borrows: assert property (
        @(posedge clk) disable iff (1'b0)
        (!A && B) |-> (BORROW == 1'b1)
    );

endmodule

rtl:
module max_value (
  input [3:0] A,
  input [3:0] B,
  output reg [3:0] max
);

always @(*)
begin
  if(A > B)
    max = A;
  else
    max = B;
end

endmodule

sva:
module max_value_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] max
);

    // max must implement the RTL comparison result.
    check_max_function: assert property (
        @($global_clock) disable iff (1'b0) max == ((A > B) ? A : B)
    );

    // When A is greater than B, max must equal A.
    check_select_a_when_a_gt_b: assert property (
        @($global_clock) disable iff (1'b0) (A > B) |-> (max == A)
    );

    // When A is less than or equal to B, max must equal B.
    check_select_b_when_a_le_b: assert property (
        @($global_clock) disable iff (1'b0) (A <= B) |-> (max == B)
    );

    // The output must always be at least A.
    check_max_ge_a: assert property (
        @($global_clock) disable iff (1'b0) (max >= A)
    );

    // The output must always be at least B.
    check_max_ge_b: assert property (
        @($global_clock) disable iff (1'b0) (max >= B)
    );

    // Equal inputs must produce that shared value.
    check_equal_inputs: assert property (
        @($global_clock) disable iff (1'b0) (A == B) |-> ((max == A) && (max == B))
    );

endmodule

rtl:
module up_counter (
  input clk,
  input reset,
  output reg [3:0] count_out
);

reg j, k;

always @(posedge clk or posedge reset) begin
  if (reset) begin
    count_out <= 4'b0000;
    j <= 1'b0;
    k <= 1'b0;
  end
  else begin
    case ({j,k})
      2'b00: begin // Qn-1 = 0, Qn = 0
        count_out <= count_out + 1;
        j <= 1'b1;
      end
      2'b01: begin // Qn-1 = 0, Qn = 1
        j <= 1'b0;
        k <= 1'b1;
      end
      2'b10: begin // Qn-1 = 1, Qn = 0
        j <= 1'b1;
        k <= 1'b0;
      end
      2'b11: begin // Qn-1 = 1, Qn = 1
        j <= 1'b1;
        k <= 1'b1;
      end
    endcase
  end
end

endmodule

sva:
module up_counter_sva (
    input logic       clk,
    input logic       reset,
    input logic [3:0] count_out
);

    // A sampled reset assertion clears count_out by the next clock.
    reset_rise_clears_count_by_next_clk: assert property (
        @(posedge clk) disable iff ($initstate)
        $rose(reset) |=> (count_out == 4'b0000)
    );

    // While reset stays asserted across sampled clocks, count_out stays zero.
    reset_held_high_keeps_count_zero: assert property (
        @(posedge clk) disable iff ($initstate)
        (reset && $past(reset)) |-> (count_out == 4'b0000)
    );

    // On the sampled reset release edge, count_out is still zero.
    reset_fall_starts_from_zero: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        $fell(reset) |-> (count_out == 4'b0000)
    );

    // After reset release, count_out never exceeds one until reset is asserted again.
    post_reset_count_bounded: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        $fell(reset) |=> (count_out <= 4'd1)[*1:$]
    );

    // Each sampled transition is a hold, a +1 increment, or a move to zero.
    count_transition_is_hold_increment_or_zero: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        (count_out == 4'b0000) ||
        (count_out == $past(count_out)) ||
        (count_out == ($past(count_out) + 4'b0001))
    );

    // Any sampled change to a nonzero count_out value is a +1 increment.
    nonzero_count_change_is_increment: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        ($changed(count_out) && (count_out != 4'b0000)) |-> (count_out == ($past(count_out) + 4'b0001))
    );

    // After a nonzero increment is observed, the next sampled value holds or returns to zero.
    nonzero_increment_then_hold_or_zero: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        ($changed(count_out) && (count_out != 4'b0000)) |=> ((count_out == $past(count_out)) || (count_out == 4'b0000))
    );

endmodule

module decoder_4to16_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic [15:0] Y
);

    // External clk samples a purely combinational DUT with no reset.

    // 0000 decodes to Y[0].
    check_decode_0000: assert property (
        @(posedge clk) ({A,B,C,D} === 4'b0000) |-> (Y === 16'h0001)
    );

    // 0001 decodes to Y[1].
    check_decode_0001: assert property (
        @(posedge clk) ({A,B,C,D} === 4'b0001) |-> (Y === 16'h0002)
    );

    // 0010 decodes to Y[2].
    check_decode_0010: assert property (
        @(posedge clk) ({A,B,C,D} === 4'b0010) |-> (Y === 16'h0004)
    );

    // 0011 decodes to Y[3].
    check_decode_0011: assert property (
        @(posedge clk) ({A,B,C,D} === 4'b0011) |-> (Y === 16'h0008)
    );

    // 0100 decodes to Y[4].
    check_decode_0100: assert property (
        @(posedge clk) ({A,B,C,D} === 4'b0100) |-> (Y === 16'h0010)
    );

    // 0101 decodes to Y[5].
    check_decode_0101: assert property (
        @(posedge clk) ({A,B,C,D} === 4'b0101) |-> (Y === 16'h0020)
    );

    // 0110 decodes to Y[6].
    check_decode_0110: assert property (
        @(posedge clk) ({A,B,C,D} === 4'b0110) |-> (Y === 16'h0040)
    );

    // 0111 decodes to Y[7].
    check_decode_0111: assert property (
        @(posedge clk) ({A,B,C,D} === 4'b0111) |-> (Y === 16'h0080)
    );

    // 1000 decodes to Y[8].
    check_decode_1000: assert property (
        @(posedge clk) ({A,B,C,D} === 4'b1000) |-> (Y === 16'h0100)
    );

    // 1001 decodes to Y[9].
    check_decode_1001: assert property (
        @(posedge clk) ({A,B,C,D} === 4'b1001) |-> (Y === 16'h0200)
    );

    // 1010 decodes to Y[10].
    check_decode_1010: assert property (
        @(posedge clk) ({A,B,C,D} === 4'b1010) |-> (Y === 16'h0400)
    );

    // 1011 decodes to Y[11].
    check_decode_1011: assert property (
        @(posedge clk) ({A,B,C,D} === 4'b1011) |-> (Y === 16'h0800)
    );

    // 1100 decodes to Y[12].
    check_decode_1100: assert property (
        @(posedge clk) ({A,B,C,D} === 4'b1100) |-> (Y === 16'h1000)
    );

    // 1101 decodes to Y[13].
    check_decode_1101: assert property (
        @(posedge clk) ({A,B,C,D} === 4'b1101) |-> (Y === 16'h2000)
    );

    // 1110 decodes to Y[14].
    check_decode_1110: assert property (
        @(posedge clk) ({A,B,C,D} === 4'b1110) |-> (Y === 16'h4000)
    );

    // 1111 decodes to Y[15].
    check_decode_1111: assert property (
        @(posedge clk) ({A,B,C,D} === 4'b1111) |-> (Y === 16'h8000)
    );

    // Stable inputs keep the decoded output stable.
    check_stable_inputs_stable_output: assert property (
        @(posedge clk) $stable({A,B,C,D}) |-> $stable(Y)
    );

endmodule

module mux2_sva (
    input logic clk,
    input logic a,
    input logic b,
    input logic q
);

    // When b is 1, q follows a.
    check_b_high_selects_a: assert property (
        @(posedge clk) (b === 1'b1) |-> (q === a)
    );

    // When b is not 1, q follows b.
    check_b_not_high_selects_b: assert property (
        @(posedge clk) (b !== 1'b1) |-> (q === b)
    );

    // When b is 0, q is 0.
    check_b_low_forces_q_low: assert property (
        @(posedge clk) (b === 1'b0) |-> (q === 1'b0)
    );

    // When both a and b are 1, q is 1.
    check_a_and_b_high_drive_q_high: assert property (
        @(posedge clk) ((a === 1'b1) && (b === 1'b1)) |-> (q === 1'b1)
    );

    // When a is 0 and b is 1, q is 0.
    check_a_low_with_b_high_drives_q_low: assert property (
        @(posedge clk) ((a === 1'b0) && (b === 1'b1)) |-> (q === 1'b0)
    );

    // q can only be 1 when both inputs are 1.
    check_q_high_implies_a_and_b_high: assert property (
        @(posedge clk) (q === 1'b1) |-> ((a === 1'b1) && (b === 1'b1))
    );

endmodule

rtl:
module mux_2to1(
  input A,
  input B,
  input S,
  output MO
);

  assign MO = (S == 1'b1) ? B : A;

endmodule

sva:
module mux_2to1_sva(
    input logic clk,
    input logic A,
    input logic B,
    input logic S,
    input logic MO
);

    // MO must always match the implemented mux expression.
    check_mux_function: assert property (
        @(posedge clk) MO === ((S == 1'b1) ? B : A)
    );

    // When select is low, MO must follow A.
    check_select_low_routes_a: assert property (
        @(posedge clk) (S === 1'b0) |-> (MO === A)
    );

    // When select is high, MO must follow B.
    check_select_high_routes_b: assert property (
        @(posedge clk) (S === 1'b1) |-> (MO === B)
    );

    // If both inputs match, MO must match them regardless of select.
    check_equal_inputs_pass_through: assert property (
        @(posedge clk) (A === B) |-> (MO === A)
    );

endmodule

rtl:
module three_input_gate (
    A,
    B,
    C,
    Y
);

    input A, B, C;
    output Y;

    wire and1, and2, and3;
    wire or1, or2;

    assign and1 = A & B;
    assign and2 = A & C;
    assign and3 = B & C;
    assign or1 = and1 | and2;
    assign or2 = or1 | and3;
    assign Y = or2;

endmodule

sva:
module three_input_gate_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic C,
    input logic Y
);

    // No RTL clock or reset; sample combinational behavior on clk.

    // Y matches the RTL pairwise-AND OR function.
    check_majority_equation: assert property (
        @(posedge clk) Y == ((A & B) | (A & C) | (B & C))
    );

    // A and B high must drive Y high.
    check_ab_pair_sets_y: assert property (
        @(posedge clk) (A & B) |-> Y
    );

    // A and C high must drive Y high.
    check_ac_pair_sets_y: assert property (
        @(posedge clk) (A & C) |-> Y
    );

    // B and C high must drive Y high.
    check_bc_pair_sets_y: assert property (
        @(posedge clk) (B & C) |-> Y
    );

    // With A low, Y high requires B and C high.
    check_y_with_a_low_requires_bc: assert property (
        @(posedge clk) (Y & ~A) |-> (B & C)
    );

    // With B low, Y high requires A and C high.
    check_y_with_b_low_requires_ac: assert property (
        @(posedge clk) (Y & ~B) |-> (A & C)
    );

    // With C low, Y high requires A and B high.
    check_y_with_c_low_requires_ab: assert property (
        @(posedge clk) (Y & ~C) |-> (A & B)
    );

    // Zero or one high input must keep Y low.
    check_zero_or_single_high_keeps_y_low: assert property (
        @(posedge clk)
        ((~A & ~B & ~C) |
         ( A & ~B & ~C) |
         (~A &  B & ~C) |
         (~A & ~B &  C)) |-> ~Y
    );

endmodule

rtl:
module ring_counter #(
  parameter n = 4 // number of states
)(
  input clk,
  output [n-1:0] out
);

// define the sequence of states
reg [n-1:0] states;
wire [n-1:0] next_states;

assign next_states = {states[n-2:0], states[n-1]};

always @(posedge clk) begin
  states <= next_states; // moved the register assignment inside the always block
end

assign out = states; // moved the out assignment outside of the always block

endmodule

sva:
module ring_counter_sva #(
    parameter n = 4
)(
    input logic clk,
    input logic [n-1:0] out
);

    genvar i;
    generate
        if (n > 1) begin : gen_multi_bit_checks
            // Output rotates by one bit on each rising clock edge.
            check_out_rotates: assert property (
                @(posedge clk) 1'b1 |=> out == {$past(out[n-2:0]), $past(out[n-1])}
            );

            // Bit 0 takes the previous cycle's top bit.
            check_wrap_bit: assert property (
                @(posedge clk) 1'b1 |=> out[0] == $past(out[n-1])
            );

            for (i = 1; i < n; i++) begin : gen_shift_bit_checks
                // Each upper bit takes the previous cycle's next lower bit.
                check_shift_bit_relation: assert property (
                    @(posedge clk) 1'b1 |=> out[i] == $past(out[i-1])
                );
            end
        end else begin : gen_single_bit_checks
            // A 1-bit configuration holds its value each cycle.
            check_single_bit_holds: assert property (
                @(posedge clk) 1'b1 |=> out[0] == $past(out[0])
            );
        end
    endgenerate

endmodule

rtl:
module comparator (input [3:0] V, output z);

  assign z = (V[3] & (V[2] | V[1]));

endmodule

sva:
module comparator_sva (
    input logic       clk,
    input logic [3:0] V,
    input logic       z
);

    // z must match the RTL compare equation.
    check_output_equation: assert property (
        @(posedge clk) z == (V[3] & (V[2] | V[1]))
    );

    // z can only be high when V[3] is high.
    check_z_requires_v3: assert property (
        @(posedge clk) z |-> V[3]
    );

    // z can only be high when either V[2] or V[1] is high.
    check_z_requires_v2_or_v1: assert property (
        @(posedge clk) z |-> (V[2] | V[1])
    );

    // If V[3] is low, z must be low.
    check_v3_low_forces_z_low: assert property (
        @(posedge clk) !V[3] |-> !z
    );

    // If both V[2] and V[1] are low, z must be low.
    check_v2_v1_low_forces_z_low: assert property (
        @(posedge clk) !(V[2] | V[1]) |-> !z
    );

    // If V[3] and V[2] are high, z must be high.
    check_v3_and_v2_drive_z_high: assert property (
        @(posedge clk) (V[3] & V[2]) |-> z
    );

    // If V[3] and V[1] are high, z must be high.
    check_v3_and_v1_drive_z_high: assert property (
        @(posedge clk) (V[3] & V[1]) |-> z
    );

endmodule

rtl:
module parity_generator (
  input [3:0] data,
  output reg parity
);

  always @* begin
    parity = ~(data[0] ^ data[1] ^ data[2] ^ data[3]);
  end

endmodule

sva:
module parity_generator_sva (
    input logic [3:0] data,
    input logic parity
);

    // Parity must equal the inverted XOR of all four data bits.
    check_parity_matches_function: assert property (
        @($global_clock) parity == ~(data[0] ^ data[1] ^ data[2] ^ data[3])
    );

    // An even XOR result must produce a high parity output.
    check_even_xor_drives_high: assert property (
        @($global_clock) ((data[0] ^ data[1] ^ data[2] ^ data[3]) == 1'b0) |-> (parity == 1'b1)
    );

    // An odd XOR result must produce a low parity output.
    check_odd_xor_drives_low: assert property (
        @($global_clock) ((data[0] ^ data[1] ^ data[2] ^ data[3]) == 1'b1) |-> (parity == 1'b0)
    );

    // Stable input data must keep the combinational parity output stable.
    check_stable_data_keeps_parity_stable: assert property (
        @($global_clock) $stable(data) |-> $stable(parity)
    );

endmodule

rtl:
module Forwarding (
    input wire [4:0] EX_rs,
    input wire [4:0] EX_rt,
    input wire [4:0] MEM_rd,
    input wire [4:0] WB_rd,
    input wire MEM_RegWrite,
    input wire WB_RegWrite,
    output reg [1:0] ForwardA,
    output reg [1:0] ForwardB
    );
    // forwarding unit

    always @*
        // if ((MEM/WB.RegWrite == 1) and
        //     (MEM/WB.RegisterRd != 0) and
        //     (MEM/WB.RegisterRd == ID/EX.RegisterRs) and
        //     ((EX/MEM.RegisterRd != ID/EX.RegisterRs) or (EX/MEM.RegWrite == 0)))
        //         then ForwardA = 1
        if (WB_RegWrite && WB_rd && (WB_rd == EX_rs) &&
                ((MEM_rd != EX_rs) || (~MEM_RegWrite)))
            ForwardA = 2'b01;
        // if ((EX/MEM.RegWrite == 1) and
        //     (EX/MEM.RegisterRd != 0) and
        //     (EX/MEM.RegisterRd == ID/EX.RegisterRs))
        //         then ForwardA = 2
        else if (MEM_RegWrite && MEM_rd && (MEM_rd == EX_rs))
            ForwardA = 2'b10;
        else
            ForwardA = 2'b00;

    always @*
        // if ((MEM/WB.RegWrite == 1) and
        //     (MEM/WB.RegisterRd != 0) and
        //     (MEM/WB.RegisterRd == ID/EX.RegisterRt) and
        //     ((EX/MEM.RegisterRd != ID/EX.RegisterRt) or (EX/MEM.RegWrite == 0)))
        //         then ForwardB = 1
        if (WB_RegWrite && WB_rd && (WB_rd == EX_rt) &&
                ((MEM_rd != EX_rt) || (~MEM_RegWrite)))
            ForwardB = 2'b01;
        // if ((EX/MEM.RegWrite == 1) and
        //     (EX/MEM.RegisterRd != 0) and
        //     (EX/MEM.RegisterRd == ID/EX.RegisterRt))
        //         then ForwardB = 2
        else if (MEM_RegWrite && MEM_rd && (MEM_rd == EX_rt))
            ForwardB = 2'b10;
        else
            ForwardB = 2'b00;

endmodule

sva:
module Forwarding_sva (
    input logic clk,
    input logic [4:0] EX_rs,
    input logic [4:0] EX_rt,
    input logic [4:0] MEM_rd,
    input logic [4:0] WB_rd,
    input logic MEM_RegWrite,
    input logic WB_RegWrite,
    input logic [1:0] ForwardA,
    input logic [1:0] ForwardB
);

    // ForwardA selects WB forwarding when the WB condition is taken.
    check_forwarda_wb_select: assert property (
        @(posedge clk)
        ((WB_RegWrite && WB_rd && (WB_rd == EX_rs) &&
          ((MEM_rd != EX_rs) || (~MEM_RegWrite))) === 1'b1)
        |-> (ForwardA == 2'b01)
    );

    // ForwardA selects MEM forwarding when WB is not taken and the MEM condition is taken.
    check_forwarda_mem_select: assert property (
        @(posedge clk)
        (((WB_RegWrite && WB_rd && (WB_rd == EX_rs) &&
           ((MEM_rd != EX_rs) || (~MEM_RegWrite))) !== 1'b1) &&
         ((MEM_RegWrite && MEM_rd && (MEM_rd == EX_rs)) === 1'b1))
        |-> (ForwardA == 2'b10)
    );

    // ForwardA is zero when neither forwarding condition is taken.
    check_forwarda_default_zero: assert property (
        @(posedge clk)
        (((WB_RegWrite && WB_rd && (WB_rd == EX_rs) &&
           ((MEM_rd != EX_rs) || (~MEM_RegWrite))) !== 1'b1) &&
         ((MEM_RegWrite && MEM_rd && (MEM_rd == EX_rs)) !== 1'b1))
        |-> (ForwardA == 2'b00)
    );

    // ForwardA gives MEM priority when both MEM and WB match EX_rs.
    check_forwarda_mem_priority: assert property (
        @(posedge clk)
        (((MEM_RegWrite && MEM_rd && (MEM_rd == EX_rs)) === 1'b1) &&
         ((WB_RegWrite && WB_rd && (WB_rd == EX_rs)) === 1'b1))
        |-> (ForwardA == 2'b10)
    );

    // ForwardA only uses implemented encodings.
    check_forwarda_valid_encoding: assert property (
        @(posedge clk)
        (ForwardA inside {2'b00, 2'b01, 2'b10})
    );

    // ForwardB selects WB forwarding when the WB condition is taken.
    check_forwardb_wb_select: assert property (
        @(posedge clk)
        ((WB_RegWrite && WB_rd && (WB_rd == EX_rt) &&
          ((MEM_rd != EX_rt) || (~MEM_RegWrite))) === 1'b1)
        |-> (ForwardB == 2'b01)
    );

    // ForwardB selects MEM forwarding when WB is not taken and the MEM condition is taken.
    check_forwardb_mem_select: assert property (
        @(posedge clk)
        (((WB_RegWrite && WB_rd && (WB_rd == EX_rt) &&
           ((MEM_rd != EX_rt) || (~MEM_RegWrite))) !== 1'b1) &&
         ((MEM_RegWrite && MEM_rd && (MEM_rd == EX_rt)) === 1'b1))
        |-> (ForwardB == 2'b10)
    );

    // ForwardB is zero when neither forwarding condition is taken.
    check_forwardb_default_zero: assert property (
        @(posedge clk)
        (((WB_RegWrite && WB_rd && (WB_rd == EX_rt) &&
           ((MEM_rd != EX_rt) || (~MEM_RegWrite))) !== 1'b1) &&
         ((MEM_RegWrite && MEM_rd && (MEM_rd == EX_rt)) !== 1'b1))
        |-> (ForwardB == 2'b00)
    );

    // ForwardB gives MEM priority when both MEM and WB match EX_rt.
    check_forwardb_mem_priority: assert property (
        @(posedge clk)
        (((MEM_RegWrite && MEM_rd && (MEM_rd == EX_rt)) === 1'b1) &&
         ((WB_RegWrite && WB_rd && (WB_rd == EX_rt)) === 1'b1))
        |-> (ForwardB == 2'b10)
    );

    // ForwardB only uses implemented encodings.
    check_forwardb_valid_encoding: assert property (
        @(posedge clk)
        (ForwardB inside {2'b00, 2'b01, 2'b10})
    );

endmodule

module sky130_fd_sc_ms__o21ai_sva (
    input logic A1,
    input logic A2,
    input logic B1,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB,
    input logic Y
);

    // No RTL clock or reset; assertions sample on the formal global clock.

    // Y must match the implemented combinational equation.
    check_output_matches_logic: assert property (
        @($global_clock)
        Y == ((A1 & A2 & B1) | (VPWR & VGND & VPB & VNB))
    );

    // The A1/A2/B1 product term forces Y high.
    check_data_term_forces_high: assert property (
        @($global_clock)
        (A1 & A2 & B1) |-> Y
    );

    // The VPWR/VGND/VPB/VNB product term forces Y high.
    check_power_term_forces_high: assert property (
        @($global_clock)
        (VPWR & VGND & VPB & VNB) |-> Y
    );

    // Y must be low when both product terms are low.
    check_both_terms_low_force_low: assert property (
        @($global_clock)
        (!(A1 & A2 & B1) && !(VPWR & VGND & VPB & VNB)) |-> !Y
    );

    // A high Y must come from at least one implemented product term.
    check_high_output_has_source: assert property (
        @($global_clock)
        Y |-> ((A1 & A2 & B1) || (VPWR & VGND & VPB & VNB))
    );

    // A low Y means the A1/A2/B1 product term is low.
    check_low_output_means_data_term_low: assert property (
        @($global_clock)
        !Y |-> !(A1 & A2 & B1)
    );

    // A low Y means the VPWR/VGND/VPB/VNB product term is low.
    check_low_output_means_power_term_low: assert property (
        @($global_clock)
        !Y |-> !(VPWR & VGND & VPB & VNB)
    );

    // If Y is high without the power term, the data term must be high.
    check_high_without_power_term_comes_from_data_term: assert property (
        @($global_clock)
        (Y && !(VPWR & VGND & VPB & VNB)) |-> (A1 & A2 & B1)
    );

    // If Y is high without the data term, the power term must be high.
    check_high_without_data_term_comes_from_power_term: assert property (
        @($global_clock)
        (Y && !(A1 & A2 & B1)) |-> (VPWR & VGND & VPB & VNB)
    );

endmodule

