module alt_ddrx_clock_and_reset_sva #
(
    parameter CTL_RESET_SYNC_STAGES      = 4,
    parameter CTL_NUM_RESET_OUTPUT       = 1,
    parameter CTL_HALF_RESET_SYNC_STAGES = 4,
    parameter CTL_HALF_NUM_RESET_OUTPUT  = 1
