    // Binary inputs produce the Boolean AND result.
    check_binary_inputs_match_and: assert property (
        @(posedge clk)
        (((A === 1'b0) || (A === 1'b1)) &&
         ((B === 1'b0) || (B === 1'b1)))
        |-> (X === (A & B))
    );

    // Any low input forces the output low.
    check_any_low_forces_output_low: assert property (
        @(posedge clk)
        ((A === 1'b0) || (B === 1'b0))
        |-> (X === 1'b0)
