module addr_map(input[9:0] hcount,
                input[9:0] vcount,
                output[16:0] addr);

assign addr = (vcount[9:1] << 8) + (vcount[9:1] << 6) + (hcount >> 1);
endmodule

sva:
module addr_map_sva (
    input logic        clk,
    input logic [9:0]  hcount,
    input logic [9:0]  vcount,
    input logic [16:0] addr
);

    // addr must match the RTL continuous assignment.
    check_addr_equation: assert property (
        @(posedge clk)
        addr == ((vcount[9:1] << 8) + (vcount[9:1] << 6) + (hcount >> 1))
    );

    // The implemented expression only drives the low 10 bits of addr.
    check_addr_upper_bits_zero: assert property (
        @(posedge clk)
        addr[16:10] == 7'b0
    );

    // The low six addr bits come directly from hcount[6:1].
    check_addr_low_bits_from_hcount: assert property (
        @(posedge clk)
        addr[5:0] == hcount[6:1]
    );

    // Changing only hcount[0] must not change addr.
    check_addr_ignores_hcount_lsb: assert property (
        @(posedge clk)
        ($changed(hcount[0]) && $stable(hcount[9:1]) && $stable(vcount)) |-> $stable(addr)
    );

    // Changing only vcount[0] must not change addr.
    check_addr_ignores_vcount_lsb: assert property (
        @(posedge clk)
        ($changed(vcount[0]) && $stable(vcount[9:1]) && $stable(hcount)) |-> $stable(addr)
    );

    // Changing only vcount[9:4] must not change addr.
    check_addr_ignores_vcount_upper_bits: assert property (
        @(posedge clk)
        ($changed(vcount[9:4]) && $stable(vcount[3:0]) && $stable(hcount)) |-> $stable(addr)
    );

endmodule

rtl:
module Contador_AD(
    input rst,
    input [1:0] en,
    input [7:0] Cambio,
    input got_data,
    input clk,
    output reg [(N-1):0] Cuenta
    );

    parameter N = 6;
    parameter X = 59;

    always @(posedge clk)
    if (en == 2'd0)
    begin 
        if (rst)
            Cuenta <= 0;
        else
            Cuenta <= Cuenta;
    end
    else if (en == 2'd1 && Cambio == 8'h75 && got_data)
    begin
        if (Cuenta == X)
            Cuenta <= 0;
        else 
            Cuenta <= Cuenta + 1'd1;
    end
    else if (en == 2'd2 && Cambio == 8'h72 && got_data)
    begin
        if (Cuenta == 0)
            Cuenta <= X;
        else 
            Cuenta <= Cuenta - 1'd1;
    end
    else 
        Cuenta <= Cuenta;
endmodule

sva:
module Contador_AD_sva #(
    parameter int N = 6,
    parameter int X = 59
) (
    input logic rst,
    input logic [1:0] en,
    input logic [7:0] Cambio,
    input logic got_data,
    input logic clk,
    input logic [N-1:0] Cuenta
);

    localparam logic [N-1:0] X_VAL = X;
    localparam logic [N-1:0] ONE   = {{(N-1){1'b0}}, 1'b1};

    // en==0 with rst high clears Cuenta.
    check_reset_when_en_zero: assert property (
        @(posedge clk) (en == 2'd0 && rst) |=> (Cuenta == '0)
    );

    // en==0 with rst low holds Cuenta.
    check_hold_when_en_zero_without_reset: assert property (
        @(posedge clk) (en == 2'd0 && !rst) |=> $stable(Cuenta)
    );

    // Valid up command at X wraps Cuenta to zero.
    check_increment_wrap_at_x: assert property (
        @(posedge clk) (en == 2'd1 && Cambio == 8'h75 && got_data && Cuenta == X_VAL) |=> (Cuenta == '0)
    );

    // Valid up command below X increments Cuenta by one.
    check_increment_step_below_x: assert property (
        @(posedge clk) (en == 2'd1 && Cambio == 8'h75 && got_data && Cuenta != X_VAL) |=> (Cuenta == ($past(Cuenta) + ONE))
    );

    // Valid down command at zero wraps Cuenta to X.
    check_decrement_wrap_at_zero: assert property (
        @(posedge clk) (en == 2'd2 && Cambio == 8'h72 && got_data && Cuenta == '0) |=> (Cuenta == X_VAL)
    );

    // Valid down command above zero decrements Cuenta by one.
    check_decrement_step_above_zero: assert property (
        @(posedge clk) (en == 2'd2 && Cambio == 8'h72 && got_data && Cuenta != '0) |=> (Cuenta == ($past(Cuenta) - ONE))
    );

    // en==1 with any non-matching command holds Cuenta.
    check_hold_on_invalid_up_command: assert property (
        @(posedge clk) (en == 2'd1 && !(Cambio == 8'h75 && got_data)) |=> $stable(Cuenta)
    );

    // en==2 with any non-matching command holds Cuenta.
    check_hold_on_invalid_down_command: assert property (
        @(posedge clk) (en == 2'd2 && !(Cambio == 8'h72 && got_data)) |=> $stable(Cuenta)
    );

    // en==3 always holds Cuenta.
    check_hold_when_en_three: assert property (
        @(posedge clk) (en == 2'd3) |=> $stable(Cuenta)
    );

endmodule

module mux_2to1_sva (
    input logic in0,
    input logic in1,
    input logic sel,
    input logic out
);

    // No RTL clock or reset; sample this combinational mux on the formal global clock.
    // Output must always match the selected input.
    check_mux_function: assert property (
        @($global_clock) out === ((sel === 1'b0) ? in0 : in1)
    );

    // When select is exactly 0, out must route in0.
    check_sel_zero_routes_in0: assert property (
        @($global_clock) (sel === 1'b0) |-> (out === in0)
    );

    // When select is not exactly 0, out must route in1.
    check_sel_nonzero_routes_in1: assert property (
        @($global_clock) (sel !== 1'b0) |-> (out === in1)
    );

    // Changing the unselected in1 must not affect out when select is 0.
    check_in1_ignored_when_sel_zero: assert property (
        @($global_clock) (sel === 1'b0 && $stable(in0) && $changed(in1)) |-> $stable(out)
    );

    // Changing the unselected in0 must not affect out when select is not 0.
    check_in0_ignored_when_sel_nonzero: assert property (
        @($global_clock) (sel !== 1'b0 && $stable(in1) && $changed(in0)) |-> $stable(out)
    );

    // A select change to 0 must make out reflect in0 when inputs are stable.
    check_sel_change_to_zero_selects_in0: assert property (
        @($global_clock) ($changed(sel) && (sel === 1'b0) && $stable(in0) && $stable(in1)) |-> (out === in0)
    );

    // A select change away from 0 must make out reflect in1 when inputs are stable.
    check_sel_change_from_zero_selects_in1: assert property (
        @($global_clock) ($changed(sel) && (sel !== 1'b0) && $stable(in0) && $stable(in1)) |-> (out === in1)
    );

endmodule

