rtl:
module multiplier_32bit (
  input [15:0] a_1,
  input [15:0] b_1,
  input [15:0] a_2,
  input [15:0] b_2,
  input select,
  output reg [31:0] result
);

  wire [31:0] mul_result_1;
  wire [31:0] mul_result_2;

  // Multiplication module 1
  mult_1 mult_1_inst (
    .a(a_1),
    .b(b_1),
    .result(mul_result_1)
  );

  // Multiplication module 2
  mult_2 mult_2_inst (
    .a(a_2),
    .b(b_2),
    .result(mul_result_2)
  );

  // Control module
  always @ (select) begin
    if (select == 1'b0) begin
      result <= mul_result_1;
    end else begin
      result <= mul_result_2;
    end
  end

endmodule

// 16-bit multiplication module
module mult_1 (
  input [15:0] a,
  input [15:0] b,
  output reg [31:0] result
);

  always @ (a, b) begin
    result <= a * b;
  end

endmodule

// 16-bit multiplication module
module mult_2 (
  input [15:0] a,
  input [15:0] b,
  output reg [31:0] result
);

  always @ (a, b) begin
    result <= a * b;
  end

endmodule

sva:
module multiplier_32bit_sva (
    input logic        clk,
    input logic [15:0] a_1,
    input logic [15:0] b_1,
    input logic [15:0] a_2,
    input logic [15:0] b_2,
    input logic        select,
    input logic [31:0] result,
    input logic [31:0] mul_result_1,
    input logic [31:0] mul_result_2
);

    // mult_1 output matches a_1 multiplied by b_1.
    check_mul1_product: assert property (
        @(posedge clk) 1'b1 |=> (mul_result_1 == (a_1 * b_1))
    );

    // mult_2 output matches a_2 multiplied by b_2.
    check_mul2_product: assert property (
        @(posedge clk) 1'b1 |=> (mul_result_2 == (a_2 * b_2))
    );

    // Data input changes alone do not update result when select is unchanged.
    check_result_ignores_data_only_changes: assert property (
        @(posedge clk) ($stable(select) && $changed({a_1, b_1, a_2, b_2})) |-> $stable(result)
    );

    // A falling select chooses multiplier 1 when its inputs are unchanged.
    check_select_low_loads_mul1: assert property (
        @(posedge clk) $fell(select) && $stable(a_1) && $stable(b_1) |-> (result == mul_result_1)
    );

    // A rising select chooses multiplier 2 when its inputs are unchanged.
    check_select_high_loads_mul2: assert property (
        @(posedge clk) $rose(select) && $stable(a_2) && $stable(b_2) |-> (result == mul_result_2)
    );

endmodule

rtl:
module shift_register (
    input clk,
    input reset,
    input load,
    input shift,
    input [3:0] data_in,
    output [3:0] data_out
);

    reg [3:0] reg_data;

    always @(posedge clk) begin
        if (reset) begin
            reg_data <= 4'b0;
        end else if (load) begin
            reg_data <= data_in;
        end else if (shift) begin
            reg_data <= {reg_data[2:0], reg_data[3]};
        end
    end

    assign data_out = reg_data;

endmodule

sva:
module shift_register_sva (
    input logic clk,
    input logic reset,
    input logic load,
    input logic shift,
    input logic [3:0] data_in,
    input logic [3:0] data_out
);

    // Reset clears the register on the following cycle.
    check_reset_clears_data: assert property (
        @(posedge clk) reset |=> (data_out == 4'b0000)
    );

    // Load captures data_in when shift is not asserted.
    check_load_captures_data: assert property (
        @(posedge clk) disable iff (reset)
        (load && !shift) |=> (data_out == $past(data_in))
    );

    // Shift rotates the register left when load is low.
    check_shift_rotates_data: assert property (
        @(posedge clk) disable iff (reset)
        (!load && shift) |=> (data_out == {$past(data_out[2]), $past(data_out[1]), $past(data_out[0]), $past(data_out[3])})
    );

    // The register holds its value when neither control is active.
    check_hold_when_idle: assert property (
        @(posedge clk) disable iff (reset)
        (!load && !shift) |=> (data_out == $past(data_out))
    );

    // Load has priority over shift when both are asserted.
    check_load_priority_over_shift: assert property (
        @(posedge clk) disable iff (reset)
        (load && shift) |=> (data_out == $past(data_in))
    );

endmodule

module counter_sva (
    input logic       clk,
    input logic       rst,
    input logic       en,
    input logic       ctrl,
    input logic [3:0] count
);

    // Active-high reset keeps count at zero.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |-> (count == 4'b0000)
    );

    // Count holds its value when enable is low.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (rst)
        (!en) |=> (count == $past(count))
    );

    // Count increments by one when enabled and ctrl is low.
    check_increment_when_enabled: assert property (
        @(posedge clk) disable iff (rst)
        (en && !ctrl) |=> (count == ($past(count) + 4'd1))
    );

    // Count decrements by one when enabled and ctrl is high.
    check_decrement_when_enabled: assert property (
        @(posedge clk) disable iff (rst)
        (en && ctrl) |=> (count == ($past(count) - 4'd1))
    );

endmodule

rtl:
module multi_QI
   (CLK,
    reset,
    A,
    B,
    P);
   input CLK;
  input reset;
  input [15:0]A;
  input [15:0]B;
  output reg [31:0]P;

  always @(posedge CLK, posedge reset) begin
    if (reset) begin
      P <= 0;
    end else begin
      P <= A * B;
    end
  end

endmodule

sva:
module multi_QI_sva (
    input logic        CLK,
    input logic        reset,
    input logic [15:0] A,
    input logic [15:0] B,
    input logic [31:0] P
);

    // First clock after a sampled reset still sees P cleared.
    check_post_reset_clears_p: assert property (
        @(posedge CLK) disable iff (reset)
        (!$initstate && $past(reset)) |-> (P == 32'd0)
    );

    // Outside reset, P must be either zero or the previous cycle's product.
    check_p_is_zero_or_prev_product: assert property (
        @(posedge CLK) disable iff (reset)
        (!$initstate) |-> ((P == 32'd0) || (P == ($past(A) * $past(B))))
    );

    // Any nonzero P must come from the previous cycle's multiplication.
    check_nonzero_p_matches_prev_product: assert property (
        @(posedge CLK) disable iff (reset)
        (!$initstate && (P != 32'd0)) |-> (P == ($past(A) * $past(B)))
    );

    // A zero A operand on the previous active cycle forces P to zero.
    check_prev_a_zero_forces_zero: assert property (
        @(posedge CLK) disable iff (reset)
        (!$initstate && !$past(reset) && ($past(A) == 16'd0)) |-> (P == 32'd0)
    );

    // A zero B operand on the previous active cycle forces P to zero.
    check_prev_b_zero_forces_zero: assert property (
        @(posedge CLK) disable iff (reset)
        (!$initstate && !$past(reset) && ($past(B) == 16'd0)) |-> (P == 32'd0)
    );

    // Multiplying by one on A passes through the previous B value unless reset cleared P.
    check_prev_a_one_identity: assert property (
        @(posedge CLK) disable iff (reset)
        (!$initstate && !$past(reset) && ($past(A) == 16'd1)) |-> ((P == 32'd0) || (P == {16'd0, $past(B)}))
    );

    // Multiplying by one on B passes through the previous A value unless reset cleared P.
    check_prev_b_one_identity: assert property (
        @(posedge CLK) disable iff (reset)
        (!$initstate && !$past(reset) && ($past(B) == 16'd1)) |-> ((P == 32'd0) || (P == {16'd0, $past(A)}))
    );

    // If either previous operand was even, the stored result must be even.
    check_even_operand_gives_even_result: assert property (
        @(posedge CLK) disable iff (reset)
        (!$initstate && !$past(reset) && (!$past(A[0]) || !$past(B[0]))) |-> (P[0] == 1'b0)
    );

    // A nonzero result from two odd previous operands must also be odd.
    check_odd_operands_nonzero_result_is_odd: assert property (
        @(posedge CLK) disable iff (reset)
        (!$initstate && !$past(reset) && (P != 32'd0) && $past(A[0]) && $past(B[0])) |-> (P[0] == 1'b1)
    );

    // The maximum 16x16 product is either captured exactly or cleared by reset.
    check_max_operands_product: assert property (
        @(posedge CLK) disable iff (reset)
        (!$initstate && !$past(reset) && ($past(A) == 16'hffff) && ($past(B) == 16'hffff)) |-> ((P == 32'd0) || (P == 32'hfffe_0001))
    );

endmodule

rtl:
module top_module( 
    input [2:0] a,
    input [2:0] b,
    output [2:0] out_or_bitwise,
    output out_or_logical,
    output [5:0] out_not
);

    // instantiate the logical-OR and bitwise-OR module
    logic_or_bitwise_or_module lb_module(
        .a(a),
        .b(b),
        .out(out_or_bitwise)
    );

    // instantiate the inverter module
    inverter_module inv_module_a(
        .in(a),
        .out(out_not[2:0])
    );

    inverter_module inv_module_b(
        .in(b),
        .out(out_not[5:3])
    );

    // implement the logical-OR operation using XOR and AND gates
    assign out_or_logical = (a | b) == 3'b111 ? 1'b1 : 1'b0;

endmodule

// module for logical-OR and bitwise-OR
module logic_or_bitwise_or_module(
    input [2:0] a,
    input [2:0] b,
    output [2:0] out
);

    // implement the bitwise-OR operation using OR gates
    assign out = a | b;

endmodule

// module for inverter
module inverter_module(
    input [2:0] in,
    output [2:0] out
);

    // implement the inverter using NOT gates
    assign out = ~in;

endmodule

sva:
module top_module_assertions (
    input logic clk,
    input logic [2:0] a,
    input logic [2:0] b,
    input logic [2:0] out_or_bitwise,
    input logic out_or_logical,
    input logic [5:0] out_not
);

    // Bitwise OR output matches the OR of a and b.
    check_out_or_bitwise_matches_inputs: assert property (
        @(posedge clk) out_or_bitwise == (a | b)
    );

    // Lower half of out_not is the inversion of a.
    check_out_not_lower_matches_a_inversion: assert property (
        @(posedge clk) out_not[2:0] == ~a
    );

    // Upper half of out_not is the inversion of b.
    check_out_not_upper_matches_b_inversion: assert property (
        @(posedge clk) out_not[5:3] == ~b
    );

    // Full out_not bus matches the concatenated inversions of b and a.
    check_out_not_concatenation: assert property (
        @(posedge clk) out_not == {~b, ~a}
    );

    // out_or_logical is high only when the bitwise OR equals 3'b111.
    check_out_or_logical_matches_inputs: assert property (
        @(posedge clk) out_or_logical == ((a | b) == 3'b111)
    );

    // out_or_logical matches the reduction-AND of out_or_bitwise.
    check_out_or_logical_matches_out_or_bitwise: assert property (
        @(posedge clk) out_or_logical == (&out_or_bitwise)
    );

endmodule

rtl:
module my_circuit (
    output X,
    input A1,
    input A2,
    input A3,
    input A4,
    input B1
);

    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB;
    supply0 VNB;

    assign X = (A1) ? 1 : (A2) ? 0 : (A3) ? ~A4 : (B1) ? 0 : 1'b0;

endmodule

sva:
module my_circuit_sva (
    input logic X,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic A4,
    input logic B1
);

    // No RTL clock or reset; sample the combinational logic on the formal global clock.

    // X must always match the RTL mux expression.
    check_x_matches_rtl: assert property (
        @($global_clock)
        (X == ((A1) ? 1'b1 : (A2) ? 1'b0 : (A3) ? ~A4 : (B1) ? 1'b0 : 1'b0))
    );

    // A1 has highest priority and forces X high.
    check_a1_priority: assert property (
        @($global_clock)
        A1 |-> (X == 1'b1)
    );

    // A2 forces X low when A1 is low.
    check_a2_priority: assert property (
        @($global_clock)
        (!A1 && A2) |-> (X == 1'b0)
    );

    // A3 selects the inverted A4 value when A1 and A2 are low.
    check_a3_inverts_a4: assert property (
        @($global_clock)
        (!A1 && !A2 && A3) |-> (X == ~A4)
    );

    // With A1, A2, and A3 low, X is low regardless of B1.
