module up_counter_sva(
    input logic [3:0] Q,
    input logic       CLK,
    input logic       RST
);

    // When reset is low at a clock edge, the counter output is zero.
    check_reset_low_holds_zero: assert property (
        @(posedge CLK)
        !RST |-> (Q == 4'b0000)
    );

    // A falling reset clears the counter by the next sampled event.
    check_reset_fall_clears_q: assert property (
        @(posedge CLK or negedge RST)
        $fell(RST) |=> (Q == 4'b0000)
    );

    // The first active sample after reset still shows zero before counting.
    check_first_active_cycle_starts_from_zero: assert property (
        @(posedge CLK or negedge RST) disable iff (!RST)
        !$initstate && !$past(RST) |-> (Q == 4'b0000)
    );

    // On consecutive active samples, the counter increments by one modulo 16.
    check_counter_increments: assert property (
        @(posedge CLK or negedge RST) disable iff (!RST)
        !$initstate && $past(RST) |-> (Q == ($past(Q) + 4'd1))
    );

    // The counter wraps from 4'hF back to 4'h0.
    check_wrap_from_f_to_0: assert property (
        @(posedge CLK or negedge RST) disable iff (!RST)
        !$initstate && $past(RST) && ($past(Q) == 4'hF) |-> (Q == 4'h0)
    );

endmodule

rtl:
module dff (
    input CLK,
    input D,
    input SCD,
    input SCE,
    input RESET_B,
    output Q,
    output Q_B
);

    reg Q;
    reg Q_B;

    always @(posedge CLK or negedge RESET_B) begin
        if (!RESET_B) begin
            Q <= 1'b0;
            Q_B <= 1'b1;
        end else if (SCD) begin
            Q <= 1'b1;
            Q_B <= 1'b0;
        end else if (SCE) begin
            Q <= D;
            Q_B <= ~D;
        end
    end

endmodule

sva:
module dff_sva (
    input logic CLK,
    input logic D,
    input logic SCD,
    input logic SCE,
    input logic RESET_B,
    input logic Q,
    input logic Q_B
);

    // A sampled low reset forces the reset state by the next cycle.
    check_reset_state: assert property (
        @(posedge CLK)
        !RESET_B |=> ((Q == 1'b0) && (Q_B == 1'b1))
    );

    // SCD sets the outputs when asserted alone.
    check_scd_sets_outputs: assert property (
        @(posedge CLK) disable iff (!RESET_B)
        (SCD && !SCE) |=> ((Q == 1'b1) && (Q_B == 1'b0))
    );

    // SCD has priority over SCE when both are asserted.
    check_scd_priority_over_sce: assert property (
        @(posedge CLK) disable iff (!RESET_B)
        (SCD && SCE) |=> ((Q == 1'b1) && (Q_B == 1'b0))
    );

    // SCE loads a 1 from D when SCD is low.
    check_sce_loads_one: assert property (
        @(posedge CLK) disable iff (!RESET_B)
        (!SCD && SCE && D) |=> ((Q == 1'b1) && (Q_B == 1'b0))
    );

    // SCE loads a 0 from D when SCD is low.
    check_sce_loads_zero: assert property (
        @(posedge CLK) disable iff (!RESET_B)
        (!SCD && SCE && !D) |=> ((Q == 1'b0) && (Q_B == 1'b1))
    );

    // With both controls low, the current state is held.
    check_hold_when_controls_low: assert property (
        @(posedge CLK) disable iff (!RESET_B)
        (!SCD && !SCE) |=> ((Q == $past(Q)) && (Q_B == $past(Q_B)))
    );

endmodule

rtl:
module up_counter (
    input CLK,
    input CLR,
    output reg [3:0] Q
);

    always @(posedge CLK) begin
        if (CLR) begin
            Q <= 4'b0;
        end else begin
            Q <= Q + 1;
        end
    end

endmodule

sva:
module up_counter_sva (
    input logic       CLK,
    input logic       CLR,
    input logic [3:0] Q
);

    // Reset clears the counter on the following clock sample.
    check_reset_clears_q: assert property (
        @(posedge CLK)
        CLR |=> (Q == 4'h0)
    );

    // After reset is released, the counter value is zero.
    check_zero_after_reset_release: assert property (
        @(posedge CLK) disable iff (CLR || $initstate)
        $past(CLR) |-> (Q == 4'h0)
    );

    // In non-reset cycles, the counter increments by one until it reaches 15.
    check_counts_up_during_run: assert property (
        @(posedge CLK) disable iff (CLR || $initstate)
        (!$past(CLR) && ($past(Q) != 4'hF)) |-> (Q == ($past(Q) + 4'd1))
    );

    // The 4-bit counter wraps from 15 back to 0.
    check_wraps_from_max: assert property (
        @(posedge CLK) disable iff (CLR || $initstate)
        (!$past(CLR) && ($past(Q) == 4'hF)) |-> (Q == 4'h0)
    );

