sva:
module addition_sva (
    input logic [7:0] a,
    input logic [7:0] b,
    input logic [8:0] result
);

    // Result equals the zero-extended sum of the two inputs.
    check_result_matches_sum: assert property (
        @($global_clock) result == ({1'b0, a} + {1'b0, b})
    );

    // Zero plus zero produces zero.
    check_zero_inputs: assert property (
        @($global_clock) (a == 8'h00 && b == 8'h00) |-> (result == 9'h000)
    );

    // Adding zero on b passes a through unchanged.
    check_b_zero_passthrough: assert property (
        @($global_clock) (b == 8'h00) |-> (result == {1'b0, a})
    );

    // Adding zero on a passes b through unchanged.
    check_a_zero_passthrough: assert property (
        @($global_clock) (a == 8'h00) |-> (result == {1'b0, b})
    );

    // Stable inputs keep the combinational result stable.
    check_stable_inputs_stable_result: assert property (
        @($global_clock) ($stable(a) && $stable(b)) |-> $stable(result)
    );

    // Maximum inputs produce the maximum 9-bit sum.
    check_max_inputs_sum: assert property (
        @($global_clock) (a == 8'hFF && b == 8'hFF) |-> (result == 9'h1FE)
    );

endmodule

rtl:
module ripple_carry_adder (
    input [3:0] A,
    input [3:0] B,
    input cin,
    output [3:0] sum,
    output cout
);

    wire [4:0] carry;

    assign carry[0] = cin;

    genvar i;
    generate
        for (i = 0; i < 4; i = i + 1) begin : adder
            full_adder fa(
                .a(A[i]),
                .b(B[i]),
                .cin(carry[i]),
                .sum(sum[i]),
                .cout(carry[i+1])
            );
        end
    endgenerate

    assign cout = carry[4];

endmodule

module full_adder (
    input a,
    input b,
    input cin,
    output sum,
    output cout
);

    assign sum = a ^ b ^ cin;
    assign cout = (a & b) | (a & cin) | (b & cin);

endmodule

sva:
module ripple_carry_adder_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic cin,
    input logic [3:0] sum,
    input logic cout
);

    function automatic logic majority3 (
        input logic x,
        input logic y,
        input logic z
    );
        majority3 = (x & y) | (x & z) | (y & z);
    endfunction

    // Combined sum and carry match 4-bit addition with carry in.
    check_total_result: assert property (
        @(posedge clk) {cout, sum} == ({1'b0, A} + {1'b0, B} + cin)
    );

    // Sum bit 0 follows the full-adder XOR equation.
    check_sum_bit0: assert property (
        @(posedge clk) sum[0] == (A[0] ^ B[0] ^ cin)
    );

    // Sum bit 1 uses the carry generated from bit 0.
    check_sum_bit1: assert property (
        @(posedge clk) sum[1] == (A[1] ^ B[1] ^ majority3(A[0], B[0], cin))
    );

    // Sum bit 2 uses the carry generated from bits 0 and 1.
    check_sum_bit2: assert property (
        @(posedge clk) sum[2] == (A[2] ^ B[2] ^ majority3(A[1], B[1], majority3(A[0], B[0], cin)))
    );

    // Sum bit 3 uses the carry generated from bits 0 through 2.
    check_sum_bit3: assert property (
        @(posedge clk) sum[3] == (A[3] ^ B[3] ^ majority3(A[2], B[2], majority3(A[1], B[1], majority3(A[0], B[0], cin))))
    );

    // Final carry out follows the ripple-carry chain.
    check_carry_out: assert property (
        @(posedge clk) cout == majority3(A[3], B[3], majority3(A[2], B[2], majority3(A[1], B[1], majority3(A[0], B[0], cin))))
    );

endmodule

