rtl:
module bitwise_operations (
  input [31:0] a,
  input [31:0] b,
  input [1:0] operation_select,
  input [4:0] shift_amount,
  output [31:0] result
);

  wire [31:0] and_output;
  wire [31:0] or_output;
  wire [31:0] xor_output;
  wire [31:0] shifted_a;

  and_module and_inst(
    .a(a),
    .b(b),
    .result(and_output)
  );

  or_module or_inst(
    .a(a),
    .b(b),
    .result(or_output)
  );

  xor_module xor_inst(
    .a(a),
    .b(b),
    .result(xor_output)
  );

  assign shifted_a = a << shift_amount;

  reg [31:0] temp;

  always @(*) begin
    case(operation_select)
      2'b00: temp = and_output & or_output ^ shifted_a;
      2'b01: temp = and_output;
      2'b10: temp = or_output;
      2'b11: temp = xor_output;
    endcase
  end

  assign result = temp;

endmodule
module and_module (
  input [31:0] a,
  input [31:0] b,
  output [31:0] result
);

  assign result = a & b;

endmodule
module or_module (
  input [31:0] a,
  input [31:0] b,
  output [31:0] result
);

  assign result = a | b;

endmodule
module xor_module (
  input [31:0] a,
  input [31:0] b,
  output [31:0] result
);

  assign result = a ^ b;

endmodule

sva:
module bitwise_operations_sva (
    input logic        clk,
    input logic [31:0] a,
    input logic [31:0] b,
    input logic [1:0]  operation_select,
    input logic [4:0]  shift_amount,
    input logic [31:0] result
);

    // No reset in RTL; sample this combinational DUT on clk.

    // Select 00 computes the combined AND/OR term XORed with a left shift of a.
    check_result_select_00: assert property (
        @(posedge clk)
        (operation_select == 2'b00) |-> (result == (((a & b) & (a | b)) ^ (a << shift_amount)))
    );

    // Select 01 forwards the bitwise AND of a and b.
    check_result_select_01: assert property (
        @(posedge clk)
        (operation_select == 2'b01) |-> (result == (a & b))
    );

    // Select 10 forwards the bitwise OR of a and b.
    check_result_select_10: assert property (
        @(posedge clk)
        (operation_select == 2'b10) |-> (result == (a | b))
    );

    // Select 11 forwards the bitwise XOR of a and b.
    check_result_select_11: assert property (
        @(posedge clk)
        (operation_select == 2'b11) |-> (result == (a ^ b))
    );

endmodule

