rtl:
module program_counter(
    input clk,
    input rst,
    output [5:0] address,
    output [31:0] Inst_code
);

reg [31:0] PC;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        PC <= 32'd0;
    end else begin
        PC <= PC + 32'd4;
    end
end

assign address = PC[7:2];
assign Inst_code = PC;

endmodule

sva:
module program_counter_sva(
    input logic        clk,
    input logic        rst,
    input logic [5:0]  address,
    input logic [31:0] Inst_code
);

    // When sampled reset is high, the instruction output is zero.
    check_reset_inst_code_zero: assert property (
        @(posedge clk) disable iff ($initstate)
        rst |-> (Inst_code == 32'd0)
    );

    // When sampled reset is high, the address output is zero.
    check_reset_address_zero: assert property (
        @(posedge clk) disable iff ($initstate)
        rst |-> (address == 6'd0)
    );

    // Address always reflects instruction bits [7:2].
    check_address_tracks_inst_code: assert property (
        @(posedge clk) disable iff (rst)
        address == Inst_code[7:2]
    );

    // After a sampled reset cycle, the next sampled instruction is still zero.
    check_post_reset_inst_code_zero: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        $past(rst) |-> (Inst_code == 32'd0)
    );

    // After a sampled reset cycle, the next sampled address is still zero.
    check_post_reset_address_zero: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        $past(rst) |-> (address == 6'd0)
    );

    // Between sampled cycles, Inst_code either increments by 4 or has been reset to zero.
    check_inst_code_steps_by_four_or_resets: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        (Inst_code == ($past(Inst_code) + 32'd4)) || (Inst_code == 32'd0)
    );

    // Between sampled cycles, address either increments by 1 or has been reset to zero.
    check_address_steps_by_one_or_resets: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        (address == ($past(address) + 6'd1)) || (address == 6'd0)
    );

    // Adding 4 preserves Inst_code[1:0] unless reset drives them to zero.
    check_inst_code_low_bits_hold_or_reset: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        (Inst_code[1:0] == $past(Inst_code[1:0])) || (Inst_code[1:0] == 2'b00)
    );

endmodule

rtl:
module RGB_color_set(
	input clk,
	input [1:0] button,
	output [23:0] RGBcolor
    );

	reg [1:0] cunt = 2'd0;
	reg [7:0] red;
	reg [7:0] gre;
	reg [7:0] blu;

	always @ (posedge button[0])
		begin
			cunt <= cunt+1;
		end

	always @ (posedge clk)
		begin

		if(button[1]) begin
			red <= 8'b01011111;
			gre <= 8'b01011111;
			blu <= 8'b01011111;
		end

		else if (cunt == 1)begin
			red <= 8'b01111111;
			gre <= 8'b00000000;
			blu <= 8'b00000000;
			end

		else if (cunt == 2)begin
			red <= 8'b00000000;
			gre <= 8'b01111111;
			blu <= 8'b00000000;
			end

		else if (cunt == 3)begin
			red <= 8'b00000000;
			gre <= 8'b00000000;
			blu <= 8'b01111111;
			end

		else begin
			red <= 8'b00111111;
			gre <= 8'b00111111;
			blu <= 8'b00111111;
			end

		end

	assign RGBcolor = {red, gre, blu};

endmodule

sva:
module RGB_color_set_sva(
    input logic clk,
    input logic [1:0] button,
    input logic [23:0] RGBcolor,
    input logic [1:0] cunt,
    input logic [7:0] red,
    input logic [7:0] gre,
    input logic [7:0] blu
);

    // RGBcolor is always the concatenation of the three channel registers.
    check_rgbcolor_concat: assert property (
        @(posedge clk) RGBcolor === {red, gre, blu}
    );

    // The 2-bit color selector increments on each rising edge of button[0].
    check_selector_increments_on_button0: assert property (
        @(posedge button[0]) 1'b1 |=> (cunt == ($past(cunt) + 2'd1))
    );

    // button[1] has priority and selects the 0x5F gray value.
    check_button1_override_color: assert property (
        @(posedge clk) button[1] |=> (RGBcolor == 24'h5F5F5F)
    );

    // With button[1] low and selector 1, the next color is red.
    check_selector1_red: assert property (
        @(posedge clk) (!button[1] && (cunt == 2'd1)) |=> (RGBcolor == 24'h7F0000)
    );

    // With button[1] low and selector 2, the next color is green.
    check_selector2_green: assert property (
        @(posedge clk) (!button[1] && (cunt == 2'd2)) |=> (RGBcolor == 24'h007F00)
    );

    // With button[1] low and selector 3, the next color is blue.
    check_selector3_blue: assert property (
        @(posedge clk) (!button[1] && (cunt == 2'd3)) |=> (RGBcolor == 24'h00007F)
    );

    // With button[1] low and selector 0, the next color is the default gray.
    check_selector0_default_gray: assert property (
        @(posedge clk) (!button[1] && (cunt == 2'd0)) |=> (RGBcolor == 24'h3F3F3F)
    );

    // Each clk update produces one of the five implemented RGB encodings.
    check_rgbcolor_valid_encoding: assert property (
        @(posedge clk) 1'b1 |=> (
            (RGBcolor == 24'h5F5F5F) ||
            (RGBcolor == 24'h7F0000) ||
            (RGBcolor == 24'h007F00) ||
            (RGBcolor == 24'h00007F) ||
            (RGBcolor == 24'h3F3F3F)
        )
    );

endmodule

module Adder_with_reset_sva (
    input logic [3:0] A,
    input logic       B,
    input logic       RST,
    input logic       clk,
    input logic [4:0] Q
);

    // A reset cycle clears Q.
    check_reset_clears_q: assert property (
        @(posedge clk) disable iff (RST || $initstate)
        $past(RST) |-> (Q == 5'd0)
    );

    // Q stores the previous cycle's zero-extended 4-bit sum when not in reset.
    check_q_matches_registered_sum: assert property (
        @(posedge clk) disable iff (RST || $initstate)
        !$past(RST) |-> (Q == {1'b0, ($past(A) + $past(B))})
    );

    // The MSB of Q is always zero after an update.
    check_q_msb_zero: assert property (
        @(posedge clk) disable iff (RST || $initstate)
        1'b1 |-> (Q[4] == 1'b0)
    );

    // With B low, Q passes through the previous A value.
    check_b_zero_passthrough: assert property (
        @(posedge clk) disable iff (RST || $initstate)
        (!$past(RST) && ($past(B) == 1'b0)) |-> (Q == {1'b0, $past(A)})
    );

    // Adding 1 to 4'hF wraps in the 4-bit sum stored into Q.
    check_wrap_on_max_plus_one: assert property (
        @(posedge clk) disable iff (RST || $initstate)
        (!$past(RST) && ($past(A) == 4'hF) && ($past(B) == 1'b1)) |-> (Q == 5'd0)
    );

endmodule

