    check_n8_inverts_n5: assert property (
        @(posedge CK) n8 === ~n5
    );

    // n9 captures n8 on the next rising edge.
    check_n9_dff_behavior: assert property (
        @(posedge CK) 1'b1 |=> (n9 === $past(n8))
    );

