module top_module (
    input [7:0] in,
    output [2:0] pos,
    input wire [15:0] in2,
    output wire [7:0] out_hi,
    output wire [7:0] out_lo,
    input enable,
    output reg [15:0] out_sum
);

wire [2:0] pos_wire;

priority_encoder pe(
    .in(in),
    .pos(pos_wire)
);

barrel_shifter_mux bsm(
    .in(in2),
    .out_hi(out_hi),
    .out_lo(out_lo)
);

always @(posedge enable) begin
    out_sum <= {pos_wire, 3'b000} + {out_hi, out_lo};
end

