    // PADOEN alone does not affect PAD_drv_reg.
    check_drv_reg_ignores_padoen_changes: assert property (
        @($global_clock) (!$initstate && $changed(PADOEN) && $stable(PADOUT)) |-> $stable(PAD_drv_reg)
    );

    // PADOEN alone does not affect PADIN.
