rtl:
module calculator (
  input clk,
  input reset_n,
  input [31:0] operand1,
  input [31:0] operand2,
  input [1:0] operation,
  output reg [31:0] result
);

  always @(posedge clk or negedge reset_n) begin
    if (~reset_n) begin
      result <= 0;
    end else begin
      case (operation)
        2'b00: result <= operand1 + operand2;
        2'b01: result <= operand1 - operand2;
        2'b10: result <= operand1 * operand2;
        2'b11: result <= operand1 / operand2;
      endcase
    end
  end

endmodule

sva:
module calculator_sva (
    input logic        clk,
    input logic        reset_n,
    input logic [31:0] operand1,
    input logic [31:0] operand2,
    input logic [1:0]  operation,
    input logic [31:0] result
);

    // A clock sampled during reset forces result to zero by the next sample.
    check_reset_clears_result: assert property (
        @(posedge clk) !reset_n |=> (result == 32'd0)
    );

    // Addition updates result with operand1 + operand2.
    check_add_result: assert property (
        @(posedge clk) disable iff (!reset_n)
        (operation == 2'b00) |=> (result == (($past(operand1) + $past(operand2)) & 32'hFFFF_FFFF))
    );

    // Subtraction updates result with operand1 - operand2.
    check_sub_result: assert property (
        @(posedge clk) disable iff (!reset_n)
        (operation == 2'b01) |=> (result == (($past(operand1) - $past(operand2)) & 32'hFFFF_FFFF))
    );

    // Multiplication updates result with the low 32 bits of operand1 * operand2.
    check_mul_result: assert property (
        @(posedge clk) disable iff (!reset_n)
        (operation == 2'b10) |=> (result == (($past(operand1) * $past(operand2)) & 32'hFFFF_FFFF))
    );

    // Division updates result with operand1 / operand2 when the divisor is nonzero.
    check_div_result_nonzero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (operation == 2'b11 && operand2 != 32'd0) |=> (result == ($past(operand1) / $past(operand2)))
    );

endmodule

module or4bb_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic C_N,
    input logic D_N,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB,
    input logic X
);

    // Sampling clock only; RTL has no native clock or reset.

    // X must equal the implemented OR of all input terms.
    check_functional_equivalence: assert property (
        @(posedge clk)
        X == (A | B | ~C_N | ~D_N | VPWR | VGND | VPB | VNB)
    );

    // A or B high forces X high.
    check_a_or_b_drives_high: assert property (
        @(posedge clk)
        (A || B) |-> (X == 1'b1)
    );

    // C_N low is an active-low term that drives X high.
    check_c_n_active_low: assert property (
        @(posedge clk)
        (!C_N) |-> (X == 1'b1)
    );

    // D_N low is an active-low term that drives X high.
    check_d_n_active_low: assert property (
        @(posedge clk)
        (!D_N) |-> (X == 1'b1)
    );

    // Any power or bulk input high forces X high in this RTL.
    check_power_or_bulk_drives_high: assert property (
        @(posedge clk)
        (VPWR || VGND || VPB || VNB) |-> (X == 1'b1)
    );

    // With all OR terms inactive, X must be low.
    check_all_terms_inactive_drives_low: assert property (
        @(posedge clk)
        (!A && !B && C_N && D_N && !VPWR && !VGND && !VPB && !VNB) |-> (X == 1'b0)
    );

    // If X is low, every OR term must be inactive.
    check_x_low_implies_all_terms_inactive: assert property (
        @(posedge clk)
        (X == 1'b0) |-> (!A && !B && C_N && D_N && !VPWR && !VGND && !VPB && !VNB)
    );

endmodule

rtl:
module sync_counter (
    input clk,
    input rst,
    input load,
    input [3:0] data_in,
    output [3:0] count_out
);

reg [3:0] count;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        count <= 4'b0000;
    end else if (load) begin
        count <= data_in;
    end else begin
        count <= count + 1;
    end
end

assign count_out = count;

endmodule

sva:
module sync_counter_sva (
    input logic       clk,
    input logic       rst,
    input logic       load,
    input logic [3:0] data_in,
    input logic [3:0] count_out
);

    // A sampled reset forces the next sampled count to zero.
    check_reset_seen_last_cycle_clears_count: assert property (
        @(posedge clk) disable iff ($initstate)
            $past(rst) |-> (count_out == 4'b0000)
    );

    // A nonzero value after a load cycle must match the loaded data.
    check_loaded_nonzero_value_appears_next_cycle: assert property (
        @(posedge clk) disable iff (rst || $initstate)
            ($past(load) && (count_out != 4'b0000)) |-> (count_out == $past(data_in))
    );

    // A nonzero value after a non-load cycle must be the incremented count.
    check_incremented_nonzero_value_appears_next_cycle: assert property (
        @(posedge clk) disable iff (rst || $initstate)
            (!$past(load) && (count_out != 4'b0000)) |-> (count_out == ($past(count_out) + 4'b0001))
    );

    // Loading zero makes the next sampled count zero.
    check_zero_load_appears_next_cycle: assert property (
        @(posedge clk) disable iff (rst || $initstate)
            ($past(load) && ($past(data_in) == 4'b0000)) |-> (count_out == 4'b0000)
    );

    // Incrementing from 4'hF rolls the next sampled count to zero.
    check_rollover_appears_as_zero: assert property (
        @(posedge clk) disable iff (rst || $initstate)
            (!$past(load) && ($past(count_out) == 4'hF)) |-> (count_out == 4'b0000)
    );

    // The next sampled count matches load, increment, or a reset-driven zero.
    check_next_state_matches_rtl_choices: assert property (
        @(posedge clk) disable iff (rst || $initstate)
            (count_out == 4'b0000) ||
            ($past(load) && (count_out == $past(data_in))) ||
            (!$past(load) && (count_out == ($past(count_out) + 4'b0001)))
    );

endmodule

