module top_module (
    input [1:0] a,
    input [49:0] in,
    output [5:0] out
);

    wire xor_out;
    wire [2:0] comb_out;

    xor_gate xor_inst (
        .a(a[0]),
        .b(a[1]),
        .out(xor_out)
    );

    comb_circuit_50_input comb_inst (
        .in(in),
        .out(comb_out)
    );

    assign out = {xor_out, comb_out, 2'b00};

endmodule

module xor_gate (
    input a,
    input b,
    output out
);

    assign out = (a ^ b);

endmodule

module comb_circuit_50_input (
    input [49:0] in,
    output [2:0] out
);

    assign out[0] = ~(&in);
    assign out[1] = ~(|in);
    assign out[2] = ~(^in);

endmodule

sva:
module top_module_assertions (
    input logic [1:0] a,
    input logic [49:0] in,
    input logic [5:0] out
);

    (* gclk *) logic clk;

    // out[1:0] are tied low.
    check_out_low_bits_zero: assert property (
        @(posedge clk) out[1:0] == 2'b00
    );

    // out[5] matches the XOR of a[0] and a[1].
    check_out_xor_bit: assert property (
        @(posedge clk) out[5] == (a[0] ^ a[1])
    );

    // out[4] matches the inverted AND-reduction of in.
    check_out_inverted_and_bit: assert property (
        @(posedge clk) out[4] == ~(&in)
    );

    // out[3] matches the inverted OR-reduction of in.
    check_out_inverted_or_bit: assert property (
        @(posedge clk) out[3] == ~(|in)
    );

    // out[2] matches the inverted XOR-reduction of in.
    check_out_inverted_xor_bit: assert property (
        @(posedge clk) out[2] == ~(^in)
    );

    // out matches the complete concatenated expression.
    check_out_full_mapping: assert property (
        @(posedge clk) out == {(a[0] ^ a[1]), ~(&in), ~(|in), ~(^in), 2'b00}
    );

endmodule

rtl:
module bitwise_and_or(
	input [7:0] x,
	input [7:0] y,
	output out
);

wire [9:0] and_outputs;
wire [4:0] or_outputs;

genvar i;

generate
	// Create 8 AND gates
	for(i = 0; i < 8; i = i + 1)
	begin: and_1st_row
		assign and_outputs[i] = x[i] & y[i];
	end

	// Create 4 OR gates
	for(i = 0; i < 4; i = i + 1)
	begin: or_2nd_row
		assign or_outputs[i] = and_outputs[2 * i] | and_outputs[2 * i + 1];
	end

	// Create 2 AND gates
	assign and_outputs[8] = or_outputs[0] & or_outputs[1];
	assign and_outputs[9] = or_outputs[2] & or_outputs[3];

	// Create 1 OR gate
	assign out = and_outputs[8] | and_outputs[9];

endgenerate

endmodule

sva:
module bitwise_and_or_sva (
    input logic        clk,
    input logic [7:0]  x,
    input logic [7:0]  y,
    input logic        out
);

    // Out matches the implemented AND/OR reduction tree.
    check_out_matches_tree: assert property (
        @(posedge clk)
        out == ((((x[0] & y[0]) | (x[1] & y[1])) & ((x[2] & y[2]) | (x[3] & y[3])))
             | (((x[4] & y[4]) | (x[5] & y[5])) & ((x[6] & y[6]) | (x[7] & y[7]))))
    );

    // A true first reduction branch must drive out high.
    check_first_branch_drives_out_high: assert property (
        @(posedge clk)
        ((((x[0] & y[0]) | (x[1] & y[1])) & ((x[2] & y[2]) | (x[3] & y[3]))) |-> (out == 1'b1)
    );

    // A true second reduction branch must drive out high.
    check_second_branch_drives_out_high: assert property (
        @(posedge clk)
        ((((x[4] & y[4]) | (x[5] & y[5])) & ((x[6] & y[6]) | (x[7] & y[7]))) |-> (out == 1'b1)
    );

    // A high out must come from one of the two reduction branches.
    check_out_high_has_valid_source: assert property (
        @(posedge clk)
        (out == 1'b1) |-> (((((x[0] & y[0]) | (x[1] & y[1])) & ((x[2] & y[2]) | (x[3] & y[3])))
                         | (((x[4] & y[4]) | (x[5] & y[5])) & ((x[6] & y[6]) | (x[7] & y[7])))) == 1'b1)
    );

    // If neither reduction branch is true, out must be low.
    check_no_active_branch_drives_out_low: assert property (
        @(posedge clk)
        (!((((x[0] & y[0]) | (x[1] & y[1])) & ((x[2] & y[2]) | (x[3] & y[3])))) &&
         !((((x[4] & y[4]) | (x[5] & y[5])) & ((x[6] & y[6]) | (x[7] & y[7]))))) |-> (out == 1'b0)
    );

    // The first branch needs both of its OR groups when the second branch is inactive.
    check_first_branch_requires_both_or_groups: assert property (
        @(posedge clk)
        ((((x[0] & y[0]) | (x[1] & y[1])) ^ ((x[2] & y[2]) | (x[3] & y[3]))) &&
         !((((x[4] & y[4]) | (x[5] & y[5])) & ((x[6] & y[6]) | (x[7] & y[7]))))) |-> (out == 1'b0)
    );

    // The second branch needs both of its OR groups when the first branch is inactive.
    check_second_branch_requires_both_or_groups: assert property (
        @(posedge clk)
        ((((x[4] & y[4]) | (x[5] & y[5])) ^ ((x[6] & y[6]) | (x[7] & y[7]))) &&
         !((((x[0] & y[0]) | (x[1] & y[1])) & ((x[2] & y[2]) | (x[3] & y[3]))))) |-> (out == 1'b0)
    );

    // A zero x input forces all pairwise AND terms low.
    check_zero_x_forces_out_low: assert property (
        @(posedge clk)
        (x == 8'h00) |-> (out == 1'b0)
    );

    // A zero y input forces all pairwise AND terms low.
    check_zero_y_forces_out_low: assert property (
        @(posedge clk)
        (y == 8'h00) |-> (out == 1'b0)
    );

endmodule

