module dual_edge_triggered_ff (
  input clk,
  input data,
  output reg q,
  output reg q_bar
);

reg [1:0] state;

always @(posedge clk) // fix the negative edge detection here
begin
  case (state)
    2'b00: begin
      q <= data;
      q_bar <= ~data;
      state <= 2'b01;
    end
    2'b01: begin
      q <= data;
      q_bar <= ~data;
      state <= 2'b10;
    end
    2'b10: begin
      q <= data;
      q_bar <= ~data;
      state <= 2'b11;
    end
    2'b11: begin
      q <= data;
      q_bar <= ~data;
      state <= 2'b00;
    end
    default: state <= 2'b00;
  endcase
end

endmodule

sva:
module dual_edge_triggered_ff_sva (
    input logic clk,
    input logic data,
    input logic q,
    input logic q_bar
);

    // q matches the data sampled on the prior rising edge after startup settles.
    check_q_tracks_prior_data: assert property (
        @(posedge clk) (!$initstate && !$past($initstate)) |-> (q === $past(data))
    );

    // q_bar matches the inverted data sampled on the prior rising edge after startup settles.
    check_qbar_tracks_prior_data_inv: assert property (
        @(posedge clk) (!$initstate && !$past($initstate)) |-> (q_bar === ~$past(data))
    );

    // q and q_bar are complementary after startup settles.
    check_outputs_complementary: assert property (
        @(posedge clk) (!$initstate && !$past($initstate)) |-> (q_bar === ~q)
    );

    // Stable input data keeps q stable on the following clock.
    check_q_stable_when_data_stable: assert property (
        @(posedge clk) ((!$initstate && !$past($initstate)) && (data === $past(data))) |=> (q === $past(q))
    );

    // Stable input data keeps q_bar stable on the following clock.
    check_qbar_stable_when_data_stable: assert property (
        @(posedge clk) ((!$initstate && !$past($initstate)) && (data === $past(data))) |=> (q_bar === $past(q_bar))
    );

endmodule

rtl:
module mux_adder (
    input [2:0] sel,
    input [3:0] data0,
    input [3:0] data1,
    input [3:0] data2,
    input [3:0] data3,
    input [3:0] data4,
    input [3:0] data5,
    input [1:0] add_in,
    input clk,
    input reset,
    input select,
    output reg [7:0] out
);

reg [3:0] mux_out;
reg [1:0] add_out;

always @ (sel or data0 or data1 or data2 or data3 or data4 or data5) begin
    case (sel)
        3'b000: mux_out = data0;
        3'b001: mux_out = data1;
        3'b010: mux_out = data2;
        3'b011: mux_out = data3;
        3'b100: mux_out = data4;
        3'b101: mux_out = data5;
        default: mux_out = 4'b0;
    endcase
end

always @ (add_in or select) begin
    if (select == 1'b0) begin
        add_out = 2'b0;
    end else begin
        add_out = add_in;
    end
end

always @ (posedge clk or posedge reset) begin
    if (reset) begin
        out <= 8'b0;
    end else begin
        if (select == 1'b0) begin
            out <= mux_out;
        end else begin
            out <= {2'b0, mux_out} + {2'b0, add_out};
        end
    end
end

endmodule

sva:
module mux_adder_sva (
    input logic [2:0] sel,
    input logic [3:0] data0,
    input logic [3:0] data1,
    input logic [3:0] data2,
    input logic [3:0] data3,
    input logic [3:0] data4,
    input logic [3:0] data5,
    input logic [1:0] add_in,
    input logic clk,
    input logic reset,
    input logic select,
    input logic [7:0] out
);

    function automatic logic [3:0] selected_data (
        input logic [2:0] sel_f,
        input logic [3:0] data0_f,
        input logic [3:0] data1_f,
        input logic [3:0] data2_f,
        input logic [3:0] data3_f,
        input logic [3:0] data4_f,
        input logic [3:0] data5_f
    );
        begin
            case (sel_f)
                3'b000: selected_data = data0_f;
                3'b001: selected_data = data1_f;
                3'b010: selected_data = data2_f;
                3'b011: selected_data = data3_f;
                3'b100: selected_data = data4_f;
                3'b101: selected_data = data5_f;
                default: selected_data = 4'b0000;
            endcase
        end
    endfunction

    // Reset forces the registered output low.
    check_reset_clears_out: assert property (
        @(posedge clk) reset |-> (out == 8'b00000000)
    );

    // In bypass mode, out captures the zero-extended muxed data.
    check_bypass_mode_output: assert property (
        @(posedge clk) disable iff (reset)
        (select == 1'b0) |=> (
            out == {
                4'b0000,
                selected_data(
                    $past(sel),
                    $past(data0),
                    $past(data1),
                    $past(data2),
                    $past(data3),
                    $past(data4),
                    $past(data5)
                )
            }
        )
    );

    // In add mode, out captures the muxed data plus add_in.
    check_add_mode_output: assert property (
        @(posedge clk) disable iff (reset)
        (select == 1'b1) |=> (
            out == (
                {
                    4'b0000,
                    selected_data(
                        $past(sel),
                        $past(data0),
                        $past(data1),
                        $past(data2),
                        $past(data3),
                        $past(data4),
                        $past(data5)
                    )
                } + {6'b000000, $past(add_in)}
            )
        )
    );

    // Bypass mode always zero-extends into the upper nibble.
    check_bypass_zero_extension: assert property (
        @(posedge clk) disable iff (reset)
        (select == 1'b0) |=> (out[7:4] == 4'b0000)
    );

    // Add mode always zero-extends into the upper two bits.
    check_add_mode_zero_extension: assert property (
        @(posedge clk) disable iff (reset)
        (select == 1'b1) |=> (out[7:6] == 2'b00)
    );

    // Invalid mux select codes produce zero in bypass mode.
    check_invalid_sel_bypass_zero: assert property (
        @(posedge clk) disable iff (reset)
        ((select == 1'b0) && ((sel == 3'b110) || (sel == 3'b111))) |=> (out == 8'b00000000)
    );

    // Invalid mux select codes add only add_in in add mode.
    check_invalid_sel_add_uses_add_in_only: assert property (
        @(posedge clk) disable iff (reset)
        ((select == 1'b1) && ((sel == 3'b110) || (sel == 3'b111))) |=> (out == {6'b000000, $past(add_in)})
    );

endmodule

