sva:
module reduce_and_sva (
    input logic [3:0] in_vec,
    input logic out_bit
);

    // Output must equal the reduction-AND of the input vector.
    check_reduce_and_equation: assert property (
        @($global_clock) out_bit === (&in_vec)
    );

    // All input bits high must drive the output high.
    check_all_inputs_high_drives_output_high: assert property (
        @($global_clock) (in_vec === 4'b1111) |-> (out_bit === 1'b1)
    );

    // A high output requires all input bits to be high.
    check_output_high_requires_all_inputs_high: assert property (
        @($global_clock) (out_bit === 1'b1) |-> (in_vec === 4'b1111)
    );

    // A low bit 0 must force the output low.
    check_bit0_low_forces_output_low: assert property (
        @($global_clock) (in_vec[0] === 1'b0) |-> (out_bit === 1'b0)
    );

    // A low bit 1 must force the output low.
    check_bit1_low_forces_output_low: assert property (
        @($global_clock) (in_vec[1] === 1'b0) |-> (out_bit === 1'b0)
    );

    // A low bit 2 must force the output low.
    check_bit2_low_forces_output_low: assert property (
        @($global_clock) (in_vec[2] === 1'b0) |-> (out_bit === 1'b0)
    );

    // A low bit 3 must force the output low.
    check_bit3_low_forces_output_low: assert property (
        @($global_clock) (in_vec[3] === 1'b0) |-> (out_bit === 1'b0)
    );

endmodule

rtl:
module priority_encoder_4bit (
    input [3:0] I,
    output reg valid,
    output reg [1:0] encoded_value
);

always @(*) begin
    case (I)
        4'b0001: encoded_value = 2'b00;
        4'b0010: encoded_value = 2'b01;
        4'b0100: encoded_value = 2'b10;
        4'b1000: encoded_value = 2'b11;
        default: encoded_value = 2'b00;
    endcase

    valid = (I != 4'b0000);
end

endmodule

sva:
module priority_encoder_4bit_sva (
    input logic clk,
    input logic [3:0] I,
    input logic valid,
    input logic [1:0] encoded_value
);

    // valid is high exactly when the input is nonzero.
    check_valid_matches_input: assert property (
        @(posedge clk) (valid == (I != 4'b0000))
    );

    // Zero input produces an invalid result with default encoding.
    check_zero_input_outputs: assert property (
        @(posedge clk) (I == 4'b0000) |-> (valid == 1'b0 && encoded_value == 2'b00)
    );

    // 0001 encodes to 00 and is valid.
    check_encode_0001: assert property (
        @(posedge clk) (I == 4'b0001) |-> (valid == 1'b1 && encoded_value == 2'b00)
    );

    // 0010 encodes to 01 and is valid.
    check_encode_0010: assert property (
        @(posedge clk) (I == 4'b0010) |-> (valid == 1'b1 && encoded_value == 2'b01)
    );

    // 0100 encodes to 10 and is valid.
    check_encode_0100: assert property (
        @(posedge clk) (I == 4'b0100) |-> (valid == 1'b1 && encoded_value == 2'b10)
    );

    // 1000 encodes to 11 and is valid.
    check_encode_1000: assert property (
        @(posedge clk) (I == 4'b1000) |-> (valid == 1'b1 && encoded_value == 2'b11)
    );

    // Any non-one-hot nonzero input uses the default encoding.
    check_default_output_on_non_onehot: assert property (
        @(posedge clk)
        ((I != 4'b0000) &&
         (I != 4'b0001) &&
         (I != 4'b0010) &&
         (I != 4'b0100) &&
         (I != 4'b1000)) |-> (valid == 1'b1 && encoded_value == 2'b00)
    );

endmodule

rtl:
module full_adder_4bit(
    input [3:0] A,
    input [3:0] B,
    input CIN,
    output [3:0] SUM,
    output COUT
);

    wire [3:0] sum, carry;

    assign carry[0] = CIN;
    assign {carry[1], sum[0]} = A[0] + B[0] + carry[0];
    assign {carry[2], sum[1]} = A[1] + B[1] + carry[1];
    assign {carry[3], sum[2]} = A[2] + B[2] + carry[2];
    assign {COUT, sum[3]} = A[3] + B[3] + carry[3];

    assign SUM = sum;

endmodule

sva:
module full_adder_4bit_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic CIN,
    input logic [3:0] SUM,
    input logic COUT,
    input logic clk
);

    function automatic logic fa_carry (
        input logic a,
        input logic b,
        input logic cin_i
    );
        fa_carry = (a & b) | (a & cin_i) | (b & cin_i);
    endfunction

    // Outputs equal the 5-bit sum of A, B, and CIN.
    check_total_addition: assert property (
        @(posedge clk) {COUT, SUM} == ({1'b0, A} + {1'b0, B} + CIN)
    );

    // SUM[0] is the XOR of the LSB inputs and carry-in.
    check_sum_bit0: assert property (
        @(posedge clk) SUM[0] == (A[0] ^ B[0] ^ CIN)
    );

    // SUM[1] uses the carry generated from bit 0.
    check_sum_bit1: assert property (
        @(posedge clk) SUM[1] == (A[1] ^ B[1] ^ fa_carry(A[0], B[0], CIN))
    );

    // SUM[2] uses the carry generated from bit 1.
    check_sum_bit2: assert property (
        @(posedge clk) SUM[2] == (A[2] ^ B[2] ^ fa_carry(A[1], B[1], fa_carry(A[0], B[0], CIN)))
    );

    // SUM[3] uses the carry generated from bit 2.
    check_sum_bit3: assert property (
        @(posedge clk) SUM[3] == (A[3] ^ B[3] ^ fa_carry(A[2], B[2], fa_carry(A[1], B[1], fa_carry(A[0], B[0], CIN))))
    );

    // COUT is the carry generated from the MSB addition.
    check_cout_formula: assert property (
        @(posedge clk) COUT == fa_carry(A[3], B[3], fa_carry(A[2], B[2], fa_carry(A[1], B[1], fa_carry(A[0], B[0], CIN))))
    );

    // Zero inputs with no carry-in produce a zero result.
    check_zero_case: assert property (
        @(posedge clk) (A == 4'h0 && B == 4'h0 && CIN == 1'b0) |-> ({COUT, SUM} == 5'h00)
    );

    // Carry-in propagates through all one bits to produce a carry-out.
    check_full_carry_chain: assert property (
        @(posedge clk) (A == 4'hF && B == 4'h0 && CIN == 1'b1) |-> ({COUT, SUM} == 5'h10)
    );

endmodule

rtl:
module my_module (
    A1,
    A2,
    A3,
    A4,
    B1,
    X
);

    // Module ports
    input  A1;
    input  A2;
    input  A3;
    input  A4;
    input  B1;
    output X;

    // Local signals
    wire and0_out ;
    wire or0_out;

    //  Name  Output     Other arguments
    and and0 (and0_out , A1, A2, A3, A4 );
    or  or0  (or0_out  , and0_out, B1   );
    buf buf0 (X        , or0_out      );

endmodule

sva:
module my_module_sva (
    input logic clk,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic A4,
    input logic B1,
    input logic X
);

    // X implements B1 OR the 4-input AND of A1-A4.
    check_x_matches_function: assert property (
        @(posedge clk) X == (B1 || (A1 && A2 && A3 && A4))
    );

    // B1 being high is sufficient to drive X high.
    check_b1_forces_x_high: assert property (
        @(posedge clk) B1 |-> X
    );

    // All four A inputs high is sufficient to drive X high.
    check_all_a_high_forces_x_high: assert property (
        @(posedge clk) (A1 && A2 && A3 && A4) |-> X
    );

    // With B1 low, any low A input forces X low.
    check_no_b1_and_any_a_low_forces_x_low: assert property (
        @(posedge clk) (!B1 && (!A1 || !A2 || !A3 || !A4)) |-> !X
    );

    // If X is high, it must come from B1 or the 4-input AND.
    check_x_high_implies_valid_source: assert property (
        @(posedge clk) X |-> (B1 || (A1 && A2 && A3 && A4))
    );

    // If X is low, B1 is low and the 4-input AND is not satisfied.
    check_x_low_implies_no_valid_source: assert property (
        @(posedge clk) !X |-> (!B1 && (!A1 || !A2 || !A3 || !A4))
    );

endmodule

module adder_subtractor_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic       subtract,
    input logic [3:0] result
);

    // When subtract is selected, result is A minus B.
    check_subtract_mode: assert property (
        @($global_clock) (subtract === 1'b1) |-> (result === (A - B))
    );

    // When subtract is not selected, result is A plus B.
    check_add_mode: assert property (
        @($global_clock) (subtract !== 1'b1) |-> (result === (A + B))
    );

    // With unchanged inputs, the combinational result stays unchanged.
    check_stateless_output: assert property (
        @($global_clock) ($stable(A) && $stable(B) && $stable(subtract)) |-> $stable(result)
    );

endmodule

rtl:
module four_bit_arithmetic (
    input [3:0] A,
    input [3:0] B,
    input [1:0] opcode,
    output reg [3:0] result
);

    wire [3:0] add_result;
    wire [3:0] sub_result;
    wire [3:0] and_result;
    wire [3:0] or_result;

    assign add_result = A + B;
    assign sub_result = A - B;
    assign and_result = A & B;
    assign or_result = A | B;

    always @(*) begin
        case (opcode)
            2'b00: result = add_result;
            2'b01: result = sub_result;
            2'b10: result = and_result;
            2'b11: result = or_result;
            default: result = 4'bxxxx;
        endcase
    end

endmodule

sva:
module four_bit_arithmetic_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [1:0] opcode,
    input logic [3:0] result
);

    // Opcode 00 selects the 4-bit sum.
    check_add_opcode_selects_sum: assert property (
        @(posedge clk) disable iff (1'b0)
        (opcode == 2'b00) |-> (result == (A + B))
    );

    // Opcode 01 selects the 4-bit difference.
    check_sub_opcode_selects_difference: assert property (
        @(posedge clk) disable iff (1'b0)
        (opcode == 2'b01) |-> (result == (A - B))
    );

    // Opcode 10 selects the bitwise AND.
    check_and_opcode_selects_and: assert property (
        @(posedge clk) disable iff (1'b0)
        (opcode == 2'b10) |-> (result == (A & B))
    );

    // Opcode 11 selects the bitwise OR.
    check_or_opcode_selects_or: assert property (
        @(posedge clk) disable iff (1'b0)
        (opcode == 2'b11) |-> (result == (A | B))
    );

endmodule

