sva:
module sky130_fd_sc_ms__or3_sva (
    input logic clk,
    input logic X,
    input logic A,
    input logic B,
    input logic C
);

    // X matches the OR of A, B, and C.
    check_or_function: assert property (
        @(posedge clk) X == (A | B | C)
    );

    // X is low when all inputs are low.
    check_all_inputs_low_drive_low: assert property (
        @(posedge clk) (!A && !B && !C) |-> !X
