rtl:
module cpu_ctr(
input [5:0]opcode,
output wire  RegDst,ALUsrcB,MemToReg,WriteReg,MemWrite,Branch,ALUop1,ALUop0,JMP );
wire j,r,lw,sw,beq;
and JP(JMP,~opcode[5],~opcode[4],~opcode[3],~opcode[2],opcode[1],~opcode[0]),
R(r,~opcode[5],~opcode[4],~opcode[3],~opcode[2],~opcode[1],~opcode[0]),
LW(lw,opcode[5],~opcode[4],~opcode[3],~opcode[2],opcode[1],opcode[0]),
SW(sw,opcode[5],~opcode[4],opcode[3],~opcode[2],opcode[1],opcode[0]),
BEQ(beq,~opcode[5],~opcode[4],~opcode[3],opcode[2],~opcode[1],~opcode[0]);
or ALUsrc(ALUsrcB,lw,sw),
writeReg(WriteReg,r,lw);
assign RegDst=r;
assign MemToReg=lw;
assign MemWrite=sw;
assign Branch=beq;
assign ALUop1=r;
assign ALUop0=beq;

endmodule

sva:
module cpu_ctr_sva (
    input logic        clk,
    input logic [5:0]  opcode,
    input logic        RegDst,
    input logic        ALUsrcB,
    input logic        MemToReg,
    input logic        WriteReg,
    input logic        MemWrite,
    input logic        Branch,
    input logic        ALUop1,
    input logic        ALUop0,
    input logic        JMP
);

    // Clock: external sampling clk. Reset: none in RTL. Logic: combinational decode.

    // JMP decodes opcode 000010.
    check_jmp_decode: assert property (
        @(posedge clk) (JMP == (opcode == 6'b000010))
    );

    // RegDst decodes opcode 000000.
    check_regdst_decode: assert property (
        @(posedge clk) (RegDst == (opcode == 6'b000000))
    );

    // MemToReg decodes opcode 100011.
    check_memtoreg_decode: assert property (
        @(posedge clk) (MemToReg == (opcode == 6'b100011))
    );

    // MemWrite decodes opcode 101011.
    check_memwrite_decode: assert property (
        @(posedge clk) (MemWrite == (opcode == 6'b101011))
    );

    // Branch decodes opcode 000100.
    check_branch_decode: assert property (
        @(posedge clk) (Branch == (opcode == 6'b000100))
    );

    // ALUop1 matches the R-type decode.
    check_aluop1_decode: assert property (
        @(posedge clk) (ALUop1 == (opcode == 6'b000000))
    );

    // ALUop0 matches the BEQ decode.
    check_aluop0_decode: assert property (
        @(posedge clk) (ALUop0 == (opcode == 6'b000100))
    );

    // WriteReg is asserted for R-type and LW only.
    check_writereg_decode: assert property (
        @(posedge clk) (WriteReg == ((opcode == 6'b000000) || (opcode == 6'b100011)))
    );

    // ALUsrcB is asserted for LW and SW only.
    check_alusrcb_decode: assert property (
        @(posedge clk) (ALUsrcB == ((opcode == 6'b100011) || (opcode == 6'b101011)))
    );

    // RegDst and ALUop1 are driven by the same decode.
    check_aluop1_matches_regdst: assert property (
        @(posedge clk) (ALUop1 == RegDst)
    );

    // Branch and ALUop0 are driven by the same decode.
    check_aluop0_matches_branch: assert property (
        @(posedge clk) (ALUop0 == Branch)
    );

    // WriteReg is the OR of RegDst and MemToReg.
    check_writereg_relation: assert property (
        @(posedge clk) (WriteReg == (RegDst || MemToReg))
    );

    // ALUsrcB is the OR of MemToReg and MemWrite.
    check_alusrcb_relation: assert property (
        @(posedge clk) (ALUsrcB == (MemToReg || MemWrite))
    );

endmodule

rtl:
module calculator(
    input [3:0] A,
    input [3:0] B,
    input mode,
    output reg [3:0] Y
);

    reg [3:0] temp1;
    reg [3:0] temp2;

    always @ (A, B, mode)
    begin
        temp1 = A;
        temp2 = B;

        case (mode)
            0: Y = temp1 + temp2;
            1: Y = temp1 - temp2;
            default: Y = 4'b0000;
        endcase

        if (mode == 1)
            Y = -Y;
    end

endmodule

sva:
module calculator_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic       mode,
    input logic [3:0] Y
);

    // No clock or reset exists in the RTL; assertions are sampled on $global_clock.
    // The design is purely combinational from A, B, and mode to Y.

    // In mode 0, Y is the 4-bit sum of A and B.
    check_add_mode_result: assert property (
        @($global_clock) (mode === 1'b0) |-> (Y == (A + B))
    );

    // In mode 1, the subtraction result is negated, so Y equals B minus A.
    check_mode1_result: assert property (
        @($global_clock) (mode === 1'b1) |-> (Y == (B - A))
    );

    // Non-0/1 mode values take the default branch and clear Y.
    check_default_mode_clears_y: assert property (
        @($global_clock) ((mode !== 1'b0) && (mode !== 1'b1)) |-> (Y == 4'b0000)
    );

    // Equal operands cancel to zero in mode 1.
    check_mode1_equal_operands_zero: assert property (
        @($global_clock) ((mode === 1'b1) && (A == B)) |-> (Y == 4'b0000)
    );

    // A zero left operand passes B through in add mode.
    check_add_mode_zero_a_passthrough_b: assert property (
        @($global_clock) ((mode === 1'b0) && (A == 4'b0000)) |-> (Y == B)
    );

    // A zero right operand passes A through in add mode.
    check_add_mode_zero_b_passthrough_a: assert property (
        @($global_clock) ((mode === 1'b0) && (B == 4'b0000)) |-> (Y == A)
    );

    // A zero left operand passes B through in mode 1 because Y = B - A.
    check_mode1_zero_a_returns_b: assert property (
        @($global_clock) ((mode === 1'b1) && (A == 4'b0000)) |-> (Y == B)
    );

    // A zero right operand in mode 1 makes Y the two's complement of A.
    check_mode1_zero_b_returns_neg_a: assert property (
        @($global_clock) ((mode === 1'b1) && (B == 4'b0000)) |-> (Y == (4'b0000 - A))
    );

endmodule

rtl:
module counter(
    input clk,
    input reset,
    output reg [3:0] count
);

    always @(posedge clk) begin
        if (reset) begin
            count <= 4'b0;
        end else begin
            count <= count + 1;
        end
    end

endmodule

sva:
module counter_assertions (
    input logic       clk,
    input logic       reset,
    input logic [3:0] count
);

    // A reset clock edge clears the counter by the next sampled cycle.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'b0000)
    );

    // On consecutive non-reset cycles, the counter increments by one.
    check_count_increments: assert property (
        @(posedge clk) disable iff (reset)
        (!reset ##1 !reset) |-> (count == ($past(count) + 4'd1))
    );

    // A max count value wraps to zero on the next non-reset cycle.
    check_count_wraps_from_max: assert property (
        @(posedge clk) disable iff (reset)
        ((count == 4'hF) ##1 !reset) |-> (count == 4'h0)
    );

endmodule

rtl:
module sparc_ffu_part_add32 (
   z, 
   a, b, cin, add32
   ) ;
   input [31:0] a;
   input [31:0] b;
   input        cin;
   input        add32;

   output [31:0] z;

   wire          cout15; wire          cin16; assign        cin16 = (add32)? cout15: cin;

   assign      {cout15, z[15:0]} = a[15:0]+b[15:0]+{15'b0,cin};   
   assign      z[31:16] = a[31:16]+b[31:16]+{15'b0,cin16};   

endmodule

