module nios_system_alu_carry_out (
  input [1:0] address,
  input clk,
  input in_port,
  input reset_n,
  output reg [31:0] readdata
);

  wire clk_en = 1;
  wire data_in = in_port;
  wire read_mux_out = (address == 0) ? data_in : 32'b0;

  always @(posedge clk or negedge reset_n) begin
    if (!reset_n) begin
      readdata <= 0;
    end else if (clk_en) begin
      readdata <= {32'b0, read_mux_out};
    end
  end

endmodule

sva:
module nios_system_alu_carry_out_assertions (
    input logic [1:0]  address,
    input logic        clk,
    input logic        in_port,
    input logic        reset_n,
    input logic [31:0] readdata
);

    // Reset forces readdata to zero.
    check_reset_clears_readdata: assert property (
        @(posedge clk) !reset_n |-> (readdata == 32'b0)
    );

    // Address 0 with in_port high updates readdata to 1 on the next cycle.
    check_addr0_high_sets_one: assert property (
        @(posedge clk) disable iff (!reset_n)
        (address == 2'b00 && in_port) |=> (readdata == 32'h00000001)
    );

    // Address 0 with in_port low updates readdata to 0 on the next cycle.
    check_addr0_low_sets_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (address == 2'b00 && !in_port) |=> (readdata == 32'h00000000)
    );

    // Any nonzero address updates readdata to 0 on the next cycle.
    check_nonzero_address_sets_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (address != 2'b00) |=> (readdata == 32'h00000000)
    );

    // Active updates always clear the upper 31 bits.
    check_upper_bits_zero_after_update: assert property (
        @(posedge clk) disable iff (!reset_n)
        1'b1 |=> (readdata[31:1] == 31'b0)
    );

endmodule

rtl:
module flag_domain_crossing_ce(
    input wire      CLK_A,
    input wire      CLK_A_CE,
    input wire      CLK_B,
    input wire      CLK_B_CE,
    input wire      FLAG_IN_CLK_A,
    output wire     FLAG_OUT_CLK_B
);

reg         FLAG_TOGGLE_CLK_A;
initial     FLAG_TOGGLE_CLK_A = 0;
reg [2:0]   SYNC_CLK_B;

always @ (posedge CLK_A)
begin
    if (CLK_A_CE)
    begin
        if (FLAG_IN_CLK_A)
        begin
            FLAG_TOGGLE_CLK_A <= ~FLAG_TOGGLE_CLK_A;
        end
    end
end

always @ (posedge CLK_B)
begin
    if (CLK_B_CE)
    begin
        SYNC_CLK_B <= {SYNC_CLK_B[1:0], FLAG_TOGGLE_CLK_A};
    end
end

assign FLAG_OUT_CLK_B = (SYNC_CLK_B[2] ^ SYNC_CLK_B[1]); // XOR

endmodule

sva:
module flag_domain_crossing_ce_sva (
    input logic       CLK_A,
    input logic       CLK_A_CE,
    input logic       CLK_B,
    input logic       CLK_B_CE,
    input logic       FLAG_IN_CLK_A,
    input logic       FLAG_OUT_CLK_B,
    input logic       FLAG_TOGGLE_CLK_A,
    input logic [2:0] SYNC_CLK_B
);

    // Enabled CLK_A cycles XOR FLAG_IN into the toggle bit.
    check_toggle_update_when_ce_high: assert property (
        @(posedge CLK_A)
        CLK_A_CE |=> FLAG_TOGGLE_CLK_A === ($past(FLAG_TOGGLE_CLK_A) ^ $past(FLAG_IN_CLK_A))
    );

    // Disabled CLK_A cycles leave the toggle bit unchanged.
    check_toggle_hold_when_ce_low: assert property (
        @(posedge CLK_A)
        !CLK_A_CE |=> FLAG_TOGGLE_CLK_A === $past(FLAG_TOGGLE_CLK_A)
    );

    // Enabled CLK_B cycles shift in the sampled toggle bit.
    check_sync_shift_when_ce_high: assert property (
        @(posedge CLK_B)
        CLK_B_CE |=> SYNC_CLK_B === { $past(SYNC_CLK_B[1:0]), $past(FLAG_TOGGLE_CLK_A) }
    );

    // Disabled CLK_B cycles leave the synchronizer unchanged.
    check_sync_hold_when_ce_low: assert property (
        @(posedge CLK_B)
        !CLK_B_CE |=> SYNC_CLK_B === $past(SYNC_CLK_B)
    );

    // FLAG_OUT_CLK_B is the XOR of the top two synchronizer stages.
    check_flag_out_is_xor: assert property (
        @(posedge CLK_B)
        FLAG_OUT_CLK_B === (SYNC_CLK_B[2] ^ SYNC_CLK_B[1])
    );

    // After an enabled CLK_B shift, FLAG_OUT reflects the prior lower two stages.
    check_flag_out_updates_from_prior_sync_stages: assert property (
        @(posedge CLK_B)
        CLK_B_CE |=> FLAG_OUT_CLK_B === ($past(SYNC_CLK_B[1]) ^ $past(SYNC_CLK_B[0]))
    );

    // Without CLK_B_CE, FLAG_OUT_CLK_B remains unchanged.
    check_flag_out_holds_when_ce_low: assert property (
        @(posedge CLK_B)
        !CLK_B_CE |=> FLAG_OUT_CLK_B === $past(FLAG_OUT_CLK_B)
    );

endmodule

