    check_full_add_result: assert property (
        @(posedge clk) {cout, sum} == (cin + a + b)
    );

    // Zero inputs produce a zero result.
    check_zero_inputs: assert property (
        @(posedge clk) ((a == 4'b0000) && (b == 4'b0000) && (cin == 1'b0)) |-> ({cout, sum} == 5'b00000)
    );

