module top_module_sva (
    input logic [15:0] in0,
    input logic [15:0] in1,
    input logic control,
    input logic [1:0] OUT,
    input logic [15:0] addsub_out,
    input logic [3:0] comp_out
);

    // addsub_out follows the selected add/sub operation.
    check_addsub_function: assert property (
        @($global_clock) disable iff (1'b0)
        addsub_out == (control ? (in0 + in1) : (in0 - in1))
    );

    // Comparator reports greater when addsub_out low nibble exceeds in0 low nibble.
    check_comp_gt: assert property (
        @($global_clock) disable iff (1'b0)
        (addsub_out[3:0] > in0[3:0]) |-> (comp_out == 4'b0001)
    );

    // Comparator reports less when addsub_out low nibble is below in0 low nibble.
    check_comp_lt: assert property (
        @($global_clock) disable iff (1'b0)
        (addsub_out[3:0] < in0[3:0]) |-> (comp_out == 4'b0010)
    );

    // Comparator reports equal when the compared low nibbles match.
    check_comp_eq: assert property (
        @($global_clock) disable iff (1'b0)
        (addsub_out[3:0] == in0[3:0]) |-> (comp_out == 4'b0111)
    );

    // Comparator output is restricted to the implemented encodings.
    check_comp_valid_codes: assert property (
        @($global_clock) disable iff (1'b0)
        (comp_out == 4'b0001) || (comp_out == 4'b0010) || (comp_out == 4'b0111)
    );

    // OUT maps greater comparator result to 01.
    check_out_from_comp_gt: assert property (
        @($global_clock) disable iff (1'b0)
        (comp_out == 4'b0001) |-> (OUT == 2'b01)
    );

    // OUT maps less comparator result to 10.
    check_out_from_comp_lt: assert property (
        @($global_clock) disable iff (1'b0)
        (comp_out == 4'b0010) |-> (OUT == 2'b10)
    );

    // OUT maps equal comparator result to 11.
    check_out_from_comp_eq: assert property (
        @($global_clock) disable iff (1'b0)
        (comp_out == 4'b0111) |-> (OUT == 2'b11)
    );

    // OUT is restricted to the implemented encodings.
    check_out_valid_codes: assert property (
        @($global_clock) disable iff (1'b0)
        (OUT == 2'b01) || (OUT == 2'b10) || (OUT == 2'b11)
    );

    // OUT=01 implies the addsub low nibble is greater than in0 low nibble.
    check_out_gt_meaning: assert property (
        @($global_clock) disable iff (1'b0)
        (OUT == 2'b01) |-> (addsub_out[3:0] > in0[3:0])
    );

    // OUT=10 implies the addsub low nibble is less than in0 low nibble.
    check_out_lt_meaning: assert property (
        @($global_clock) disable iff (1'b0)
        (OUT == 2'b10) |-> (addsub_out[3:0] < in0[3:0])
    );

    // OUT=11 implies the compared low nibbles are equal.
    check_out_eq_meaning: assert property (
        @($global_clock) disable iff (1'b0)
        (OUT == 2'b11) |-> (addsub_out[3:0] == in0[3:0])
    );

endmodule

rtl:
module segClkDevider(
input clk,
    input rst,
    output reg clk_div
    );

 localparam constantNumber = 10000;
 reg [31:0] count;

always @ (posedge(clk), posedge(rst))
begin
    if (rst == 1'b1)
        count <= 32'b0;
    else if (count == constantNumber - 1)
        count <= 32'b0;               
    else
        count <= count + 1;
end

always @ (posedge(clk), posedge(rst))
begin
    if (rst == 1'b1)
        clk_div <= 1'b0;
    else if (count == constantNumber - 1)
        clk_div <= ~clk_div;
    else
        clk_div <= clk_div;
end
endmodule

sva:
module segClkDevider_sva (
    input logic        clk,
    input logic        rst,
    input logic        clk_div,
    input logic [31:0] count
);

    localparam logic [31:0] constantNumber = 32'd10000;

    // Reset clears both state elements by the next sampled clock.
    check_reset_clears_state: assert property (
        @(posedge clk) rst |=> (count == 32'd0) && (clk_div == 1'b0)
    );

    // Terminal count wraps back to zero.
    check_count_wraps_at_terminal: assert property (
        @(posedge clk) disable iff (rst)
        (count == (constantNumber - 32'd1)) |=> (count == 32'd0)
    );

    // Non-terminal count either increments or is asynchronously cleared.
    check_count_increments_or_clears: assert property (
        @(posedge clk) disable iff (rst)
        (count != (constantNumber - 32'd1)) |=> ((count == ($past(count) + 32'd1)) || (count == 32'd0))
    );

    // Terminal count makes clk_div toggle, unless async reset clears it low.
    check_clk_div_toggles_or_clears_at_terminal: assert property (
        @(posedge clk) disable iff (rst)
        (count == (constantNumber - 32'd1)) |=> ((clk_div == ~$past(clk_div)) || (clk_div == 1'b0))
    );

    // Below terminal count, a low clk_div must remain low.
    check_clk_div_low_holds_below_terminal: assert property (
        @(posedge clk) disable iff (rst)
        (count != (constantNumber - 32'd1) && (clk_div == 1'b0)) |=> (clk_div == 1'b0)
    );

    // At terminal count, a high clk_div must go low on the next cycle.
    check_clk_div_high_goes_low_at_terminal: assert property (
        @(posedge clk) disable iff (rst)
        (count == (constantNumber - 32'd1) && (clk_div == 1'b1)) |=> (clk_div == 1'b0)
    );

endmodule

rtl:
module and_module (
    output X   ,
    input  A_N ,
    input  B_N ,
    input  C   ,
    input  D   ,
    input  VPWR,
    input  VGND,
    input  VPB ,
    input  VNB
);

    wire AB, CD, ABCD;
    and (AB, A_N, B_N);
    and (CD, C, D);
    and (ABCD, AB, CD);
    assign X = ABCD;

endmodule

sva:
module and_module_sva (
    input logic X,
    input logic A_N,
    input logic B_N,
    input logic C,
    input logic D,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB
);

    // Combinational DUT with no explicit clock or reset; sample on the global formal clock.

    // X must equal the AND of the four functional inputs.
    check_x_equation: assert property (
        @($global_clock) X == (A_N & B_N & C & D)
    );

    // A high X requires all four functional inputs to be high.
    check_x_high_requires_all_inputs_high: assert property (
        @($global_clock) X |-> (A_N & B_N & C & D)
    );

    // All four functional inputs high must drive X high.
    check_all_inputs_high_drive_x: assert property (
        @($global_clock) (A_N & B_N & C & D) |-> X
    );

    // If any functional input is low, X must be low.
    check_any_low_input_forces_x_low: assert property (
        @($global_clock) !(A_N & B_N & C & D) |-> !X
    );

    // With stable functional inputs, X must remain stable.
    check_stable_function_inputs_keep_x_stable: assert property (
        @($global_clock) $stable({A_N, B_N, C, D}) |-> $stable(X)
    );

    // Power pin changes alone must not affect X.
    check_power_pin_changes_do_not_affect_x: assert property (
        @($global_clock) $stable({A_N, B_N, C, D}) && $changed({VPWR, VGND, VPB, VNB}) |-> $stable(X)
    );

endmodule

rtl:
module halfword_separator(
    input wire [15:0] in,
    input wire select_upper,
    output wire [7:0] out_hi,
    output wire [7:0] out_lo);

    wire [7:0] shifted_in;

    // Barrel shifter to shift input to the right by 8 bits
    assign shifted_in = in >> 8;

    // Multiplexer to select upper or lower byte based on select_upper signal
    assign out_hi = select_upper ? shifted_in : in[15:8];
    assign out_lo = select_upper ? in[7:0] : shifted_in;

endmodule

sva:
module halfword_separator_sva (
    input logic        clk,
    input logic [15:0] in,
    input logic        select_upper,
    input logic [7:0]  out_hi,
    input logic [7:0]  out_lo
);

    // out_hi always equals the upper input byte.
    check_out_hi_matches_upper_byte: assert property (
        @(posedge clk) out_hi == in[15:8]
    );

    // out_lo selects the lower or upper byte based on select_upper.
    check_out_lo_matches_selected_byte: assert property (
        @(posedge clk) out_lo == (select_upper ? in[7:0] : in[15:8])
    );

    // With select_upper high, the outputs reproduce the input halfword.
    check_passthrough_when_select_upper: assert property (
        @(posedge clk) select_upper |-> ({out_hi, out_lo} == in)
    );

    // With select_upper low, both outputs equal the upper input byte.
    check_upper_byte_duplicated_when_select_lower: assert property (
        @(posedge clk) !select_upper |-> ({out_hi, out_lo} == {in[15:8], in[15:8]})
    );

    // With select_upper low, the two outputs must match.
    check_outputs_match_when_select_lower: assert property (
        @(posedge clk) !select_upper |-> (out_hi == out_lo)
    );

endmodule

rtl:
module DOWNCOUNTER_POSEDGE # (parameter SIZE=16)
(
input wire Clock, Reset,
input wire [SIZE-1:0] Initial,
input wire Enable,
output reg [SIZE-1:0] Q
);

  always @(posedge Clock )
  begin
      if (Reset)
        Q = Initial;
      else
		begin
		if (Enable)
			Q = Q - 1;
		end			
  end

endmodule

sva:
module DOWNCOUNTER_POSEDGE_assertions #(parameter SIZE=16) (
    input logic Clock,
    input logic Reset,
    input logic [SIZE-1:0] Initial,
    input logic Enable,
    input logic [SIZE-1:0] Q
);

    // Reset loads Q from Initial.
    check_reset_load: assert property (
        @(posedge Clock) Reset |=> (Q == $past(Initial))
    );

    // When enabled outside reset, Q decrements by one.
    check_decrement_when_enabled: assert property (
        @(posedge Clock) disable iff (Reset) Enable |=> (Q == ($past(Q) - 1'b1))
    );

    // When disabled outside reset, Q holds its value.
    check_hold_when_disabled: assert property (
        @(posedge Clock) disable iff (Reset) !Enable |=> (Q == $past(Q))
    );

    // Decrementing zero wraps around to all ones.
    check_wrap_on_underflow: assert property (
        @(posedge Clock) disable iff (Reset) Enable && (Q == '0) |=> (Q == {SIZE{1'b1}})
    );

endmodule

