`define ADDER_WIDTH 007
`define DUMMY_WIDTH 128

`define 2_LEVEL_ADDER

module adder_tree_top (
	clk,
	isum0_0_0_0, isum0_0_0_1, isum0_0_1_0, isum0_0_1_1, isum0_1_0_0, isum0_1_0_1, isum0_1_1_0, isum0_1_1_1,
	sum,
);
	input clk;
	input [`ADDER_WIDTH+0-1:0] isum0_0_0_0, isum0_0_0_1, isum0_0_1_0, isum0_0_1_1, isum0_1_0_0, isum0_1_0_1, isum0_1_1_0, isum0_1_1_1;
	output [`ADDER_WIDTH  :0] sum;
	reg    [`ADDER_WIDTH  :0] sum;

	wire [`ADDER_WIDTH+3-1:0] sum0;
	wire [`ADDER_WIDTH+2-1:0] sum0_0, sum0_1;
	wire [`ADDER_WIDTH+1-1:0] sum0_0_0, sum0_0_1, sum0_1_0, sum0_1_1;
	reg  [`ADDER_WIDTH+0-1:0] sum0_0_0_0, sum0_0_0_1, sum0_0_1_0, sum0_0_1_1, sum0_1_0_0, sum0_1_0_1, sum0_1_1_0, sum0_1_1_1;

	adder_tree_branch L1_0(sum0_0,     sum0_1,     sum0    );
	defparam L1_0.EXTRA_BITS = 2;

	adder_tree_branch L2_0(sum0_0_0,   sum0_0_1,   sum0_0  );
	adder_tree_branch L2_1(sum0_1_0,   sum0_1_1,   sum0_1  );
	defparam L2_0.EXTRA_BITS = 1;
	defparam L2_1.EXTRA_BITS = 1;

	adder_tree_branch L3_0(sum0_0_0_0, sum0_0_0_1, sum0_0_0);
	adder_tree_branch L3_1(sum0_0_1_0, sum0_0_1_1, sum0_0_1);
	adder_tree_branch L3_2(sum0_1_0_0, sum0_1_0_1, sum0_1_0);
	adder_tree_branch L3_3(sum0_1_1_0, sum0_1_1_1, sum0_1_1);
	defparam L3_0.EXTRA_BITS = 0;
	defparam L3_1.EXTRA_BITS = 0;
	defparam L3_2.EXTRA_BITS = 0;
	defparam L3_3.EXTRA_BITS = 0;

	always @(posedge clk) begin
		sum0_0_0_0 <= isum0_0_0_0;
		sum0_0_0_1 <= isum0_0_0_1;
		sum0_0_1_0 <= isum0_0_1_0;
		sum0_0_1_1 <= isum0_0_1_1;
		sum0_1_0_0 <= isum0_1_0_0;
		sum0_1_0_1 <= isum0_1_0_1;
		sum0_1_1_0 <= isum0_1_1_0;
		sum0_1_1_1 <= isum0_1_1_1;

		`ifdef 3_LEVEL_ADDER
			sum <= sum0;
		`endif
		`ifdef 2_LEVEL_ADDER
			sum <= sum0_0;
		`endif
	end

endmodule

module adder_tree_branch(a,b,sum);
	parameter EXTRA_BITS = 0;

	input [`ADDER_WIDTH+EXTRA_BITS-1:0] a;
	input [`ADDER_WIDTH+EXTRA_BITS-1:0] b;
	output [`ADDER_WIDTH+EXTRA_BITS:0] sum;

	assign sum = a + b;
endmodule

sva:
module adder_tree_top_sva (
    input logic       clk,
    input logic [6:0] isum0_0_0_0,
    input logic [6:0] isum0_0_0_1,
    input logic [6:0] isum0_0_1_0,
    input logic [6:0] isum0_0_1_1,
    input logic [6:0] isum0_1_0_0,
    input logic [6:0] isum0_1_0_1,
    input logic [6:0] isum0_1_1_0,
    input logic [6:0] isum0_1_1_1,
    input logic [7:0] sum
);

    // Clock: clk; no reset in RTL.
    // Registered inputs feed combinational adders.
    // `2_LEVEL_ADDER makes sum use only the first four sampled inputs.

    function automatic [7:0] expected_sum4 (
        input logic [6:0] a,
        input logic [6:0] b,
        input logic [6:0] c,
        input logic [6:0] d
    );
        expected_sum4 = {1'b0, a} + {1'b0, b} + {1'b0, c} + {1'b0, d};
    endfunction

    // Sum matches the registered first four inputs one cycle later.
    check_sum_matches_registered_first_four: assert property (
        @(posedge clk) disable iff ($initstate)
        1'b1 |=> sum == expected_sum4(
            $past(isum0_0_0_0),
            $past(isum0_0_0_1),
            $past(isum0_0_1_0),
            $past(isum0_0_1_1)
        )
    );

    // All used inputs low produce a zero sum on the next cycle.
    check_zero_when_used_inputs_zero: assert property (
        @(posedge clk) disable iff ($initstate)
        (isum0_0_0_0 == 7'd0 &&
         isum0_0_0_1 == 7'd0 &&
         isum0_0_1_0 == 7'd0 &&
         isum0_0_1_1 == 7'd0) |=> (sum == 8'd0)
    );

    // The second group of four inputs does not affect sum in 2-level mode.
    check_upper_branch_unused: assert property (
        @(posedge clk) disable iff ($initstate)
        (isum0_0_0_0 == 7'd0 &&
         isum0_0_0_1 == 7'd0 &&
         isum0_0_1_0 == 7'd0 &&
         isum0_0_1_1 == 7'd0 &&
         (isum0_1_0_0 != 7'd0 ||
          isum0_1_0_1 != 7'd0 ||
          isum0_1_1_0 != 7'd0 ||
          isum0_1_1_1 != 7'd0)) |=> (sum == 8'd0)
    );

    // With only the first used input active, sum passes that value through.
    check_input0_passthrough: assert property (
        @(posedge clk) disable iff ($initstate)
        (isum0_0_0_1 == 7'd0 &&
         isum0_0_1_0 == 7'd0 &&
         isum0_0_1_1 == 7'd0) |=> (sum == {1'b0, $past(isum0_0_0_0)})
    );

    // With only the second used input active, sum passes that value through.
    check_input1_passthrough: assert property (
        @(posedge clk) disable iff ($initstate)
        (isum0_0_0_0 == 7'd0 &&
         isum0_0_1_0 == 7'd0 &&
         isum0_0_1_1 == 7'd0) |=> (sum == {1'b0, $past(isum0_0_0_1)})
    );

    // With only the third used input active, sum passes that value through.
    check_input2_passthrough: assert property (
        @(posedge clk) disable iff ($initstate)
        (isum0_0_0_0 == 7'd0 &&
         isum0_0_0_1 == 7'd0 &&
         isum0_0_1_1 == 7'd0) |=> (sum == {1'b0, $past(isum0_0_1_0)})
    );

    // With only the fourth used input active, sum passes that value through.
    check_input3_passthrough: assert property (
        @(posedge clk) disable iff ($initstate)
        (isum0_0_0_0 == 7'd0 &&
         isum0_0_0_1 == 7'd0 &&
         isum0_0_1_0 == 7'd0) |=> (sum == {1'b0, $past(isum0_0_1_1)})
    );

    // Full-scale used inputs overflow and truncate to the low 8 bits.
    check_full_scale_truncation: assert property (
        @(posedge clk) disable iff ($initstate)
        (isum0_0_0_0 == 7'h7f &&
         isum0_0_0_1 == 7'h7f &&
         isum0_0_1_0 == 7'h7f &&
         isum0_0_1_1 == 7'h7f) |=> (sum == 8'hfc)
    );

endmodule

module up_counter_assertions (
    input logic clk,
    input logic rst,
    input logic [3:0] count
);

    // Clock: clk
    // Reset: rst is active-high and asynchronous.
    // Logic: sequential 4-bit up-counter.

    // A sampled reset-high cycle forces count to zero by the next sampled clock.
    check_reset_forces_zero_next_cycle: assert property (
        @(posedge clk) disable iff ($initstate)
        rst |=> (count == 4'd0)
    );

    // Count stays zero while reset is sampled high across consecutive clocks.
    check_reset_hold_keeps_zero: assert property (
        @(posedge clk) disable iff ($initstate)
        (rst && $past(rst)) |-> (count == 4'd0)
    );

    // Any sampled nonzero count must come from a prior non-reset increment.
    check_nonzero_counts_advance_by_one: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        (count != 4'd0) |-> (!$past(rst) && (count == ($past(count) + 4'd1)))
    );

    // A sampled 15 must wrap to zero on the next sampled clock.
    check_wrap_from_max_to_zero: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        (!$past(rst) && ($past(count) == 4'hF)) |-> (count == 4'h0)
    );

endmodule

module sync_reset_dff_assertions (
    input logic clk,
    input logic rst,
    input logic d,
    input logic q
);

    // q must be low whenever reset is asserted.
    check_reset_clears_q: assert property (
        @(posedge clk) !rst |-> (q == 1'b0)
    );

    // q stays at the reset value on the first clock where reset is released.
    check_reset_release_holds_zero_on_sampled_edge: assert property (
        @(posedge clk) $rose(rst) |-> (q == 1'b0)
    );

    // A high d must be captured into q on the next active clock.
    check_capture_one: assert property (
        @(posedge clk) disable iff (!rst) d |=> (q == 1'b1)
    );

    // A low d must be captured into q on the next active clock.
    check_capture_zero: assert property (
        @(posedge clk) disable iff (!rst) !d |=> (q == 1'b0)
    );

endmodule

