module sky130_fd_sc_hs__o2bb2a_sva (
    input logic X,
    input logic A1_N,
    input logic A2_N,
    input logic B1,
    input logic B2
);

    // Combinational cell with no RTL clock or reset; sample on the formal global clock.

    // X must always match the implemented combinational equation.
    check_x_matches_rtl_function: assert property (
        @($global_clock) disable iff (1'b0)
        X == ((~A1_N & B1 & B2) | (~A2_N & (B1 | B2)))
    );

    // If both active-low A inputs are deasserted, X must be low.
    check_both_a_inputs_deasserted_force_low: assert property (
        @($global_clock) disable iff (1'b0)
        (A1_N && A2_N) |-> (!X)
    );

    // If both B inputs are low, neither product term can assert X.
    check_both_b_inputs_low_force_low: assert property (
        @($global_clock) disable iff (1'b0)
        ((!B1) && (!B2)) |-> (!X)
    );

    // With only the A1 path enabled, X reduces to B1 & B2.
    check_a1_only_path_behavior: assert property (
        @($global_clock) disable iff (1'b0)
        ((!A1_N) && A2_N) |-> (X == (B1 & B2))
    );

    // With only the A2 path enabled, X reduces to B1 | B2.
    check_a2_only_path_behavior: assert property (
        @($global_clock) disable iff (1'b0)
        (A1_N && (!A2_N)) |-> (X == (B1 | B2))
    );

    // With both paths enabled, X still reduces to B1 | B2.
    check_both_paths_enabled_behavior: assert property (
        @($global_clock) disable iff (1'b0)
        ((!A1_N) && (!A2_N)) |-> (X == (B1 | B2))
    );

    // If both B inputs are high, X depends only on whether either A path is enabled.
    check_both_b_inputs_high_behavior: assert property (
        @($global_clock) disable iff (1'b0)
        (B1 && B2) |-> (X == ((~A1_N) | (~A2_N)))
    );

    // Enabling the A2 term with either B input high must assert X.
    check_a2_term_asserts_x: assert property (
        @($global_clock) disable iff (1'b0)
        ((!A2_N) && (B1 || B2)) |-> X
    );

    // Enabling the A1 term with both B inputs high must assert X.
    check_a1_term_asserts_x: assert property (
        @($global_clock) disable iff (1'b0)
        ((!A1_N) && B1 && B2) |-> X
    );

endmodule

module barrel_shifter_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [1:0] SHIFT,
    input logic [3:0] Y
);

    // SHIFT=00 passes the input through unchanged.
    check_no_shift: assert property (
        @(posedge clk) (SHIFT == 2'b00) |-> (Y == A)
    );

    // SHIFT=01 shifts left by 1 and inserts 0 in bit 0.
    check_left_shift_by_1: assert property (
        @(posedge clk) (SHIFT == 2'b01) |-> (Y == {A[2:0], 1'b0})
    );

    // SHIFT=10 shifts right by 1 and inserts 0 in bit 3.
    check_right_shift_by_1: assert property (
        @(posedge clk) (SHIFT == 2'b10) |-> (Y == {1'b0, A[3:1]})
    );

    // SHIFT=11 maps the output to {A[1:0], A[3:2]}.
    check_shift_11_mapping: assert property (
        @(posedge clk) (SHIFT == 2'b11) |-> (Y == {A[1:0], A[3:2]})
    );

endmodule

module dectohexstr8_sva (
    input logic        clk,
    input logic [7:0]  in,
    input logic [15:0] out
);

    function automatic [7:0] hex_ascii(input logic [3:0] nibble);
        begin
            hex_ascii = (nibble == 4'd0)  ? "0" :
                        (nibble == 4'd1)  ? "1" :
                        (nibble == 4'd2)  ? "2" :
                        (nibble == 4'd3)  ? "3" :
                        (nibble == 4'd4)  ? "4" :
                        (nibble == 4'd5)  ? "5" :
                        (nibble == 4'd6)  ? "6" :
                        (nibble == 4'd7)  ? "7" :
                        (nibble == 4'd8)  ? "8" :
                        (nibble == 4'd9)  ? "9" :
                        (nibble == 4'd10) ? "A" :
                        (nibble == 4'd11) ? "B" :
                        (nibble == 4'd12) ? "C" :
                        (nibble == 4'd13) ? "D" :
                        (nibble == 4'd14) ? "E" : "F";
        end
    endfunction

    // Low nibble is converted to its ASCII hex character.
    check_low_nibble_ascii_encoding: assert property (
        @(posedge clk) out[7:0] == hex_ascii(in[3:0])
    );

    // High nibble is converted to its ASCII hex character.
    check_high_nibble_ascii_encoding: assert property (
        @(posedge clk) out[15:8] == hex_ascii(in[7:4])
    );

    // Full output is the concatenation of high and low ASCII hex characters.
    check_full_output_encoding: assert property (
        @(posedge clk) out == {hex_ascii(in[7:4]), hex_ascii(in[3:0])}
    );

    // Input 8'h00 maps to ASCII "00".
    check_zero_input_maps_to_ascii_00: assert property (
        @(posedge clk) (in == 8'h00) |-> (out == {"0", "0"})
    );

    // Input 8'hFF maps to ASCII "FF".
    check_ff_input_maps_to_ascii_ff: assert property (
        @(posedge clk) (in == 8'hFF) |-> (out == {"F", "F"})
    );

endmodule

