module d_ff_asynchronous_set_assertions (
    input logic D,
    input logic CLK,
    input logic SET,
    input logic NOTIFIER,
    input logic Q
);

    // Active-low SET must drive Q high by the next clock edge.
    check_set_forces_high_by_next_clk: assert property (
        @(posedge CLK) (!SET) |=> (Q == 1'b1)
    );

    // With SET inactive, capturing D=1 must make Q high on the next clock.
    check_capture_one_when_enabled: assert property (
        @(posedge CLK) disable iff (!SET) (NOTIFIER && D) |=> (Q == 1'b1)
    );

    // With SET inactive, Q=1 must hold when capture is disabled.
    check_hold_high_when_notifier_low: assert property (
        @(posedge CLK) disable iff (!SET) (!NOTIFIER && (Q == 1'b1)) |=> (Q == 1'b1)
    );

    // With SET inactive, Q=1 cannot clear when D is also 1.
    check_high_preserved_when_d_high: assert property (
        @(posedge CLK) disable iff (!SET) ((Q == 1'b1) && (D == 1'b1)) |=> (Q == 1'b1)
    );

endmodule

module calculator_sva (
    input logic clk,
    input logic [3:0] a,
    input logic [3:0] b,
    input logic [1:0] ctrl,
    input logic [3:0] result
);

    // Addition mode computes the 4-bit sum.
    check_addition_mode: assert property (
        @(posedge clk) (ctrl == 2'b00) |-> (result == ((a + b) & 4'hF))
    );

    // Subtraction mode computes the 4-bit difference.
    check_subtraction_mode: assert property (
        @(posedge clk) (ctrl == 2'b01) |-> (result == ((a - b) & 4'hF))
    );

    // Multiplication mode computes the low 4 bits of the product.
    check_multiplication_mode: assert property (
        @(posedge clk) (ctrl == 2'b10) |-> (result == ((a * b) & 4'hF))
    );

    // Division mode computes the quotient when the divisor is nonzero.
    check_division_mode_nonzero: assert property (
        @(posedge clk) ((ctrl == 2'b11) && (b != 4'h0)) |-> (result == ((a / b) & 4'hF))
    );

    // Stable sampled inputs imply a stable sampled result.
    check_result_stable_when_inputs_stable: assert property (
        @(posedge clk) (!$initstate && $stable(a) && $stable(b) && $stable(ctrl) && !((ctrl == 2'b11) && (b == 4'h0))) |-> $stable(result)
    );

endmodule

