sva:
module sky130_fd_sc_ms__a22oi_sva (
    input logic clk,
    input logic Y,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic B2
);

    // Y must equal the implemented AND-of-NANDs function.
    check_output_function: assert property (
        @(posedge clk)
        Y == ((~(A2 & A1)) & (~(B2 & B1)))
    );

    // If A1 and A2 are both high, the output must be low.
    check_a_pair_high_forces_y_low: assert property (
        @(posedge clk)
        ((A1 & A2) == 1'b1) |-> (Y == 1'b0)
    );

    // If B1 and B2 are both high, the output must be low.
    check_b_pair_high_forces_y_low: assert property (
        @(posedge clk)
        ((B1 & B2) == 1'b1) |-> (Y == 1'b0)
    );

    // If neither input pair is simultaneously high, the output must be high.
    check_no_pair_high_forces_y_high: assert property (
        @(posedge clk)
        (((A1 & A2) == 1'b0) && ((B1 & B2) == 1'b0)) |-> (Y == 1'b1)
    );

    // A high output means the A input pair is not simultaneously high.
    check_y_high_excludes_a_pair_high: assert property (
        @(posedge clk)
        (Y == 1'b1) |-> ((A1 & A2) == 1'b0)
    );

    // A high output means the B input pair is not simultaneously high.
    check_y_high_excludes_b_pair_high: assert property (
        @(posedge clk)
        (Y == 1'b1) |-> ((B1 & B2) == 1'b0)
    );

    // A low output means at least one input pair is simultaneously high.
    check_y_low_requires_some_pair_high: assert property (
        @(posedge clk)
        (Y == 1'b0) |-> (((A1 & A2) == 1'b1) || ((B1 & B2) == 1'b1))
    );

endmodule

rtl:
module flip_flop (
    input D,
    input CLK,
    input SET,
    input RESET,
    output reg Q,
    output reg Q_N
);

    always @(posedge CLK) begin
        if (SET) begin
            Q <= 1;
            Q_N <= 0;
        end else if (RESET) begin
            Q <= 0;
            Q_N <= 1;
        end else begin
            Q <= D;
            Q_N <= ~D;
        end
    end

endmodule

sva:
module flip_flop_sva (
    input logic D,
    input logic CLK,
    input logic SET,
    input logic RESET,
    input logic Q,
    input logic Q_N
);

    // SET drives the outputs high/low when RESET is low.
    check_set_state: assert property (
        @(posedge CLK) disable iff (1'b0)
        (SET && !RESET) |=> (Q == 1'b1 && Q_N == 1'b0)
    );

    // SET has priority over RESET when both are high.
    check_set_priority_over_reset: assert property (
        @(posedge CLK) disable iff (1'b0)
        (SET && RESET) |=> (Q == 1'b1 && Q_N == 1'b0)
    );

    // RESET drives the outputs low/high when SET is low.
    check_reset_state: assert property (
        @(posedge CLK) disable iff (1'b0)
        (!SET && RESET) |=> (Q == 1'b0 && Q_N == 1'b1)
    );

    // D=1 is captured when neither control input is asserted.
    check_data_capture_one: assert property (
        @(posedge CLK) disable iff (1'b0)
        (!SET && !RESET && D) |=> (Q == 1'b1 && Q_N == 1'b0)
    );

    // D=0 is captured when neither control input is asserted.
    check_data_capture_zero: assert property (
        @(posedge CLK) disable iff (1'b0)
        (!SET && !RESET && !D) |=> (Q == 1'b0 && Q_N == 1'b1)
    );

    // The outputs remain complementary after each clocked update.
    check_outputs_complementary: assert property (
        @(posedge CLK) disable iff (1'b0)
        1'b1 |=> (Q_N == ~Q)
    );

endmodule

rtl:
module sync_bits
(
	input [NUM_OF_BITS-1:0] in,
	input out_resetn,
	input out_clk,
	output [NUM_OF_BITS-1:0] out
);

parameter NUM_OF_BITS = 1;
parameter ASYNC_CLK = 1;

reg [NUM_OF_BITS-1:0] cdc_sync_stage1 = 'h0;
reg [NUM_OF_BITS-1:0] cdc_sync_stage2 = 'h0;

always @(posedge out_clk)
begin
	if (out_resetn == 1'b0) begin
		cdc_sync_stage1 <= 'b0;
		cdc_sync_stage2 <= 'b0;
	end else begin
		cdc_sync_stage1 <= in;
		cdc_sync_stage2 <= cdc_sync_stage1;
	end
end

assign out = ASYNC_CLK ? cdc_sync_stage2 : in;

endmodule

sva:
module sync_bits_sva
#(
    parameter NUM_OF_BITS = 1,
    parameter ASYNC_CLK   = 1
)
(
    input logic [NUM_OF_BITS-1:0] in,
    input logic                   out_resetn,
    input logic                   out_clk,
    input logic [NUM_OF_BITS-1:0] out,
    input logic [NUM_OF_BITS-1:0] cdc_sync_stage1,
    input logic [NUM_OF_BITS-1:0] cdc_sync_stage2
);

    // Stage1 captures the input on each active clock.
    check_stage1_captures_input: assert property (
        @(posedge out_clk) disable iff (!out_resetn)
        $past(out_resetn) |-> (cdc_sync_stage1 == $past(in))
    );

    // Stage2 captures the previous stage1 value on each active clock.
    check_stage2_captures_stage1: assert property (
        @(posedge out_clk) disable iff (!out_resetn)
        $past(out_resetn) |-> (cdc_sync_stage2 == $past(cdc_sync_stage1))
    );

    // Stage2 reflects the input after two active clocks.
    check_stage2_two_cycle_delay: assert property (
        @(posedge out_clk) disable iff (!out_resetn)
        ($past(out_resetn) && $past(out_resetn, 2)) |-> (cdc_sync_stage2 == $past(in, 2))
    );

    // A reset cycle clears both synchronizer stages.
    check_reset_clears_stages: assert property (
        @(posedge out_clk) disable iff (!out_resetn)
        $past(!out_resetn) |-> ((cdc_sync_stage1 == '0) && (cdc_sync_stage2 == '0))
    );

    generate
        if (ASYNC_CLK) begin : gen_async_clk_asserts
            // In async mode, output comes from the second synchronizer stage.
            check_async_out_from_stage2: assert property (
                @(posedge out_clk) disable iff (!out_resetn)
                (out == cdc_sync_stage2)
            );

            // In async mode, output reflects the input after two active clocks.
            check_async_out_two_cycle_delay: assert property (
                @(posedge out_clk) disable iff (!out_resetn)
                ($past(out_resetn) && $past(out_resetn, 2)) |-> (out == $past(in, 2))
            );

            // A reset cycle drives the async output low.
            check_async_reset_drives_out_low: assert property (
                @(posedge out_clk) disable iff (!out_resetn)
                $past(!out_resetn) |-> (out == '0)
            );
        end else begin : gen_direct_clk_asserts
            // In direct mode, output bypasses the synchronizer.
            check_direct_out_matches_input: assert property (
                @(posedge out_clk) disable iff (!out_resetn)
                (out == in)
            );
        end
    endgenerate

endmodule

rtl:
module binary_counter (
    input clk,
    input reset,
    output reg [3:0] count
);

always @(posedge clk) begin
    if (reset == 0) begin
        count <= 4'b0000;
    end else begin
        count <= count + 1;
    end
end

endmodule

sva:
module binary_counter_sva (
    input logic       clk,
    input logic       reset,
    input logic [3:0] count
);

    // Clock: clk
    // Reset: reset is active low
    // Logic: sequential 4-bit up-counter

    // A low reset on a clock edge clears the counter.
    check_reset_clears_count: assert property (
        @(posedge clk) (!reset) |=> (count == 4'b0000)
    );

    // When reset is high, the counter increments by one each cycle.
    check_count_increments: assert property (
        @(posedge clk) disable iff (!reset) 1'b1 |=> (count == ($past(count) + 4'd1))
    );

    // The 4-bit counter wraps from 15 back to 0.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (!reset) (count == 4'hF) |=> (count == 4'h0)
    );

endmodule

