sva:
module half_adder_sva (
    input logic A,
    input logic B,
    input logic SUM,
    input logic COUT
);

    // SUM implements XOR of the inputs.
    check_sum_matches_xor: assert property (
        @($global_clock) SUM == (A ^ B)
    );

    // COUT implements AND of the inputs.
    check_cout_matches_and: assert property (
        @($global_clock) COUT == (A & B)
    );

    // Inputs 00 produce SUM=0 and COUT=0.
    check_00_case: assert property (
        @($global_clock) (!A && !B) |-> (!SUM && !COUT)
    );

    // Inputs 01 produce SUM=1 and COUT=0.
    check_01_case: assert property (
        @($global_clock) (!A && B) |-> (SUM && !COUT)
    );

    // Inputs 10 produce SUM=1 and COUT=0.
    check_10_case: assert property (
        @($global_clock) (A && !B) |-> (SUM && !COUT)
    );

    // Inputs 11 produce SUM=0 and COUT=1.
    check_11_case: assert property (
        @($global_clock) (A && B) |-> (!SUM && COUT)
    );

endmodule

rtl:
module mux_1to2_async_rst(
    input clk,
    input rst,
    input din0,
    input din1,
    input sel,
    output dout
);

    reg dout_reg;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            dout_reg <= 0;
        end else begin
            if (sel) begin
                dout_reg <= din1;
            end else begin
                dout_reg <= din0;
            end
        end
    end

    assign dout = dout_reg;

endmodule

sva:
module mux_1to2_async_rst_sva (
    input logic clk,
    input logic rst,
    input logic din0,
    input logic din1,
    input logic sel,
    input logic dout
);

    // Reset drives the registered output low.
    check_reset_forces_dout_low: assert property (
        @(posedge clk) rst |-> (dout == 1'b0)
    );

    // After a sampled reset cycle, the output remains low until the next clocked update.
    check_post_reset_dout_low: assert property (
        @(posedge clk) disable iff (rst)
        $past(rst) |-> (dout == 1'b0)
    );

    // With sel low, the output reflects the prior cycle's din0 value.
    check_sel0_updates_from_din0: assert property (
        @(posedge clk) disable iff (rst)
        $past(!rst && !sel) |-> (dout == $past(din0))
    );

    // With sel high, the output reflects the prior cycle's din1 value.
    check_sel1_updates_from_din1: assert property (
        @(posedge clk) disable iff (rst)
        $past(!rst && sel) |-> (dout == $past(din1))
    );

    // Outside reset, the output always matches the prior cycle's selected input.
    check_output_matches_previous_selected_input: assert property (
        @(posedge clk) disable iff (rst)
        $past(!rst) |-> (dout == ($past(sel) ? $past(din1) : $past(din0)))
    );

endmodule

