rtl:
module priority_encoder_pipeline (
    input [3:0] in,
    input clk,  // Added clock signal as an input
    output reg [1:0] pos
);

reg [1:0] stage1_out, stage2_out;

always @ (posedge clk) begin
    stage1_out <= {in[1], in[0]};
    stage2_out <= {in[3], in[2]};
    pos <= 2'b00;
    if (stage2_out[1]) pos <= 2'b11;
    else if (stage2_out[0]) pos <= 2'b10;
    else if (stage1_out[1]) pos <= 2'b01;
    else if (stage1_out[0]) pos <= 2'b00;
end

endmodule

sva:
module priority_encoder_pipeline_sva (
    input logic [3:0] in,
    input logic clk,
    input logic [1:0] pos
);

    // Bit 3 has highest priority and reaches pos after one clock.
    check_priority_bit3: assert property (
        @(posedge clk) in[3] |=> (pos == 2'b11)
    );

    // Bit 2 selects pos when bit 3 is low, regardless of lower bits.
    check_priority_bit2: assert property (
        @(posedge clk) (!in[3] && in[2]) |=> (pos == 2'b10)
    );

    // Bit 1 selects pos when bits 3 and 2 are low, regardless of bit 0.
    check_priority_bit1: assert property (
        @(posedge clk) ((in[3:2] == 2'b00) && in[1]) |=> (pos == 2'b01)
    );

    // pos is 00 when bits 3, 2, and 1 are all low.
    check_default_zero: assert property (
        @(posedge clk) (in[3:1] == 3'b000) |=> (pos == 2'b00)
    );

endmodule

module fifo_counter_assertions (
    input logic clk,
    input logic empty,
    input logic ge2_free,
    input logic ge3_free,
    input logic [1:0] input_tm_cnt,
    input logic [4:0] fifo_cnt_inc
);

    // Empty passes the input count through with zero extension.
    check_empty_pass_through: assert property (
        @(posedge clk)
        empty |-> (fifo_cnt_inc == {3'b000, input_tm_cnt})
    );

    // Non-empty with zero input count returns 31.
    check_nonempty_count0_returns_31: assert property (
        @(posedge clk)
        (!empty && (input_tm_cnt == 2'd0)) |-> (fifo_cnt_inc == 5'd31)
    );

    // Non-empty with input count 1 returns 0.
    check_nonempty_count1_returns_0: assert property (
        @(posedge clk)
        (!empty && (input_tm_cnt == 2'd1)) |-> (fifo_cnt_inc == 5'd0)
    );

    // Non-empty with input count 2 and ge2_free set returns 1.
    check_nonempty_count2_ge2_returns_1: assert property (
        @(posedge clk)
        (!empty && (input_tm_cnt == 2'd2) && ge2_free) |-> (fifo_cnt_inc == 5'd1)
    );

    // Non-empty with input count 2 and ge2_free clear returns 0.
    check_nonempty_count2_no_ge2_returns_0: assert property (
        @(posedge clk)
        (!empty && (input_tm_cnt == 2'd2) && !ge2_free) |-> (fifo_cnt_inc == 5'd0)
    );

    // Non-empty with input count 3 and ge3_free set returns 2.
    check_nonempty_count3_ge3_returns_2: assert property (
        @(posedge clk)
        (!empty && (input_tm_cnt == 2'd3) && ge3_free) |-> (fifo_cnt_inc == 5'd2)
    );

    // Non-empty with input count 3 uses the ge2_free case when ge3_free is clear.
    check_nonempty_count3_ge2_only_returns_1: assert property (
        @(posedge clk)
        (!empty && (input_tm_cnt == 2'd3) && !ge3_free && ge2_free) |-> (fifo_cnt_inc == 5'd1)
    );

    // Non-empty with input count 3 returns 0 when neither free threshold applies.
    check_nonempty_count3_no_free_threshold_returns_0: assert property (
        @(posedge clk)
        (!empty && (input_tm_cnt == 2'd3) && !ge3_free && !ge2_free) |-> (fifo_cnt_inc == 5'd0)
    );

endmodule

module add_sub_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic       C,
    input logic [3:0] Q
);

    // When control is high, Q must be the 4-bit sum of A and B.
    check_add_mode_result: assert property (
        @($global_clock) (C == 1'b1) |-> (Q == (A + B))
    );

    // When control is low, Q must be the 4-bit difference of A and B.
    check_sub_mode_result: assert property (
        @($global_clock) (C == 1'b0) |-> (Q == (A - B))
    );

    // If all inputs are stable, the combinational output must remain stable.
    check_output_stable_when_inputs_stable: assert property (
        @($global_clock) $stable({A, B, C}) |-> $stable(Q)
    );

    // A rising control input selects the addition result.
    check_control_rise_selects_add: assert property (
        @($global_clock) $rose(C) |-> (Q == (A + B))
    );

    // A falling control input selects the subtraction result.
    check_control_fall_selects_sub: assert property (
        @($global_clock) $fell(C) |-> (Q == (A - B))
    );

endmodule

rtl:
module concat_AB(
    input [3:0] A,
    input [1:0] B,
    output reg [2:0] Z
    );

    always @(*) begin
        if (A > 7) begin
            Z = 3'b111;
        end else if (B > 3) begin
            Z = 3'b000;
        end else begin
            Z = {A[3:2], B, A[1:0]};
        end
    end

endmodule

sva:
module concat_AB_sva (
    input logic [3:0] A,
    input logic [1:0] B,
    input logic [2:0] Z
);

    // No clock or reset in RTL; sample combinational behavior on the formal global clock.

    // When A is greater than 7, Z must be forced to 3'b111.
    check_a_gt_7_forces_ones: assert property (
        @($global_clock) (A > 4'd7) |-> (Z == 3'b111)
    );

    // When A is 7 or less, Z must match the truncated concatenation result.
    check_a_le_7_truncated_concat: assert property (
        @($global_clock) !(A > 4'd7) |-> (Z == {B[0], A[1:0]})
    );

    // Z must always match the implemented combinational function.
    check_full_function: assert property (
        @($global_clock) Z == ((A > 4'd7) ? 3'b111 : {B[0], A[1:0]})
    );

