rtl:
module EchoCancellation #(
  parameter n = 16
) (
  input signed [n-1:0] s,
  input signed [n-1:0] e,
  output signed [n-1:0] f
);

assign f = s - e;

endmodule

sva:
module EchoCancellation_sva #(
  parameter n = 16
) (
  input logic clk,
  input logic signed [n-1:0] s,
  input logic signed [n-1:0] e,
  input logic signed [n-1:0] f
);

  // f must always equal s minus e.
  check_subtract_relation: assert property (
    @(posedge clk) f == (s - e)
  );

  // Adding e back to f must reconstruct s.
  check_reconstruct_source: assert property (
    @(posedge clk) (f + e) == s
  );

  // When e is zero, f must match s.
  check_passthrough_when_e_zero: assert property (
    @(posedge clk) (e == '0) |-> (f == s)
  );

  // When s equals e, the subtraction result must be zero.
  check_zero_output_when_inputs_equal: assert property (
    @(posedge clk) (s == e) |-> (f == '0)
  );

  // When s is zero, f must be the negation of e.
  check_negated_e_when_s_zero: assert property (
    @(posedge clk) (s == '0) |-> (f == -e)
  );

  // If s and e stay stable across samples, f must also stay stable.
  check_output_stable_when_inputs_stable: assert property (
    @(posedge clk) ($stable(s) && $stable(e)) |-> $stable(f)
  );

endmodule

rtl:
module shift_register(
    input clk,
    input load,
    input [3:0] data_in,
    input shift,
    output [3:0] data_out
);

reg [3:0] shift_reg;

always @(posedge clk) begin
    if (load) begin
        shift_reg <= data_in;
    end else if (shift) begin
        shift_reg <= {shift_reg[2:0], 1'b0};
    end
end

assign data_out = shift_reg;

endmodule

sva:
module shift_register_sva(
    input logic clk,
    input logic load,
    input logic [3:0] data_in,
    input logic shift,
    input logic [3:0] data_out
);

    // Load captures data_in into data_out on the next clock.
    check_load_captures_input: assert property (
        @(posedge clk) load |=> (data_out == $past(data_in))
    );

    // Load takes priority over shift when both are asserted.
    check_load_has_priority_over_shift: assert property (
        @(posedge clk) (load && shift) |=> (data_out == $past(data_in))
    );

    // Shift moves bits left and inserts 0 into bit 0 when load is low.
    check_shift_left_zero_fill: assert property (
        @(posedge clk) (!load && shift) |=> ((data_out[3:1] == $past(data_out[2:0])) && (data_out[0] == 1'b0))
    );

    // With neither load nor shift asserted, the register holds its value.
    check_hold_when_idle: assert property (
        @(posedge clk) (!load && !shift) |=> (data_out == $past(data_out))
    );

    // Any output change must come from a load or shift in the prior cycle.
    check_output_change_requires_command: assert property (
        @(posedge clk) !$initstate && (data_out != $past(data_out)) |-> ($past(load) || $past(shift))
    );

endmodule

rtl:
module addsub(clk, rst, a, b, sub, result);
  input clk, rst, sub;
  input [3:0] a, b;
  output reg [3:0] result;

  always @(posedge clk) begin
    if (rst) begin
      result <= 4'b0000;
    end else begin
      if (sub) begin
        result <= a - b;
      end else begin
        result <= a + b;
      end
    end
  end
endmodule

sva:
module addsub_assertions (
    input logic clk,
    input logic rst,
    input logic [3:0] a,
    input logic [3:0] b,
    input logic sub,
    input logic [3:0] result
);
    // Clock: posedge clk
    // Reset: synchronous active-high rst
    // Logic: sequential registered add/sub selected by sub

    // After a reset cycle, result is cleared to zero.
    check_reset_clears_result: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        $past(rst) |-> (result == 4'b0000)
    );

    // In add mode, result matches the prior cycle sum.
    check_add_result: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        !$past(rst) && !$past(sub) |-> (result == ($past(a) + $past(b)))
    );

    // In subtract mode, result matches the prior cycle difference.
    check_sub_result: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        !$past(rst) && $past(sub) |-> (result == ($past(a) - $past(b)))
    );

endmodule

rtl:
module bit_shift (
  input [31:0] in,
  input [4:0] shift,
  input [1:0] op,
  output [31:0] out
);

  reg [31:0] shift_reg;

  always @(*) begin
    case (op)
      2'b00: shift_reg = in << shift;
      2'b01: shift_reg = in >> shift;
      2'b10: shift_reg = $signed(in) >>> shift;
      default: shift_reg = in;
    endcase
  end

  assign out = shift_reg;

