module mux_4to1_using_2to1 (input [3:0] in, input [1:0] sel, output reg out);

   wire [1:0] s1, s2;
   wire [1:0] not_sel;

   // invert select signals
   assign not_sel = ~sel;

   // connect inputs to 2-to-1 muxes
   assign s1[0] = in[0];
   assign s1[1] = in[1];
   assign s2[0] = in[2];
   assign s2[1] = in[3];

   // connect select signals to 2-to-1 muxes
   always @ (sel or s1 or s2)  // Fix the sensitivity list
   begin
      out = (not_sel[1] & s1[sel[0]]) | (sel[1] & s2[not_sel[0]]);
   end

endmodule

sva:
module mux_4to1_using_2to1_sva (
    input logic       clk,
    input logic [3:0] in,
    input logic [1:0] sel,
    input logic       out
);

    // Combinational DUT sampled on an external formal clock.

    // Output matches the implemented mux function on every sample.
    check_output_matches_implemented_function: assert property (
        @(posedge clk)
        out == (sel[1] ? (sel[0] ? in[2] : in[3]) : (sel[0] ? in[1] : in[0]))
    );

    // When sel[1] is low, the output comes from the lower input pair.
    check_sel_msb_low_selects_lower_pair: assert property (
        @(posedge clk)
        (sel[1] == 1'b0) |-> (out == (sel[0] ? in[1] : in[0]))
    );

    // When sel[1] is high, the output comes from the upper input pair in reversed sel[0] order.
    check_sel_msb_high_selects_upper_pair_reversed: assert property (
        @(posedge clk)
        (sel[1] == 1'b1) |-> (out == (sel[0] ? in[2] : in[3]))
    );

    // Select 00 maps to input bit 0.
    check_sel_00_selects_in0: assert property (
        @(posedge clk)
        (sel == 2'b00) |-> (out == in[0])
    );

    // Select 01 maps to input bit 1.
    check_sel_01_selects_in1: assert property (
        @(posedge clk)
        (sel == 2'b01) |-> (out == in[1])
    );

    // Select 10 maps to input bit 3.
    check_sel_10_selects_in3: assert property (
        @(posedge clk)
        (sel == 2'b10) |-> (out == in[3])
    );

    // Select 11 maps to input bit 2.
    check_sel_11_selects_in2: assert property (
        @(posedge clk)
        (sel == 2'b11) |-> (out == in[2])
    );

    // If sel and the selected input stay stable, the output stays stable.
    check_output_stable_when_selected_input_stable: assert property (
        @(posedge clk)
        $stable(sel) &&
        (((sel == 2'b00) && $stable(in[0])) ||
         ((sel == 2'b01) && $stable(in[1])) ||
         ((sel == 2'b10) && $stable(in[3])) ||
         ((sel == 2'b11) && $stable(in[2])))
        |-> $stable(out)
    );

    // With a stable select, any output change must track the selected input.
    check_output_change_requires_selected_input_change: assert property (
        @(posedge clk)
        $stable(sel) && $changed(out)
        |-> (((sel == 2'b00) && $changed(in[0])) ||
             ((sel == 2'b01) && $changed(in[1])) ||
             ((sel == 2'b10) && $changed(in[3])) ||
             ((sel == 2'b11) && $changed(in[2])))
    );

endmodule

rtl:
module shift_and_check (
  input clk,
  input reset,
  input [31:0] input_data,
  output [31:0] shifted_data,
  output zero_flag
);

  reg [31:0] shifted_data_reg;
  reg zero_flag_reg;

  always @(posedge clk, posedge reset) begin
    if (reset) begin
      shifted_data_reg <= 32'h00000000;
      zero_flag_reg <= 1'b0;
    end else begin
      shifted_data_reg <= {input_data[30:0], 1'b0};
      zero_flag_reg <= (input_data == 32'h00000000) ? 1'b1 : 1'b0;
    end
  end

  assign shifted_data = shifted_data_reg;
  assign zero_flag = zero_flag_reg;

endmodule

sva:
module shift_and_check_sva (
    input logic        clk,
    input logic        reset,
    input logic [31:0] input_data,
    input logic [31:0] shifted_data,
    input logic        zero_flag
);

    // A reset cycle clears shifted_data.
    check_reset_clears_shifted_data: assert property (
        @(posedge clk) reset |=> (shifted_data == 32'h00000000)
    );

    // A reset cycle clears zero_flag.
    check_reset_clears_zero_flag: assert property (
        @(posedge clk) reset |=> (zero_flag == 1'b0)
    );

    // shifted_data updates to the prior input_data shifted left by one.
    check_shifted_data_update: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> (shifted_data == {$past(input_data[30:0]), 1'b0})
    );

    // A zero input sets zero_flag on the next clock.
    check_zero_flag_set_on_zero_input: assert property (
        @(posedge clk) disable iff (reset)
        (input_data == 32'h00000000) |=> (zero_flag == 1'b1)
    );

    // A nonzero input clears zero_flag on the next clock.
    check_zero_flag_clear_on_nonzero_input: assert property (
        @(posedge clk) disable iff (reset)
        (input_data != 32'h00000000) |=> (zero_flag == 1'b0)
    );

endmodule

rtl:
module binary_counter (
   input clk,
   input rst,
   input enable,
   output reg [3:0] count
);

   always @(posedge clk or negedge rst) begin
      if (!rst) begin
         count <= 4'b0;
      end else if (enable) begin
         count <= count + 1;
      end else if (count == 4'b1111) begin
         count <= 4'b0;
      end else begin
         count <= count + 1;
      end
   end

endmodule

sva:
module binary_counter_assertions (
    input logic       clk,
    input logic       rst,
    input logic       enable,
    input logic [3:0] count
);

    // Active-low reset forces count to zero.
    reset_forces_count_zero: assert property (
        @(posedge clk) !rst |-> (count == 4'b0000)
    );

    // When enabled, the counter increments by one on the next cycle.
    enable_branch_increments: assert property (
        @(posedge clk) disable iff (!rst)
        enable |=> (count == ($past(count) + 4'd1))
    );

    // When disabled below 15, the counter still increments by one.
    disabled_nonmax_branch_increments: assert property (
        @(posedge clk) disable iff (!rst)
        (!enable && (count != 4'hF)) |=> (count == ($past(count) + 4'd1))
    );

    // When disabled at 15, the counter wraps to zero on the next cycle.
    disabled_max_branch_wraps: assert property (
        @(posedge clk) disable iff (!rst)
        (!enable && (count == 4'hF)) |=> (count == 4'h0)
    );

    // Outside reset, the counter advances by one every cycle.
    counter_advances_each_cycle: assert property (
        @(posedge clk) disable iff (!rst)
        1'b1 |=> (count == ($past(count) + 4'd1))
    );

endmodule

rtl:
module pipeline_reg (
    input clk, 
    input rst, 
    input data, 
    output reg out
);

reg [2:0] pipeline;

always @(posedge clk) begin
    if (rst) begin
        pipeline <= 3'b0;
        out <= 1'b0;
    end else begin
        pipeline[2] <= pipeline[1];
        pipeline[1] <= pipeline[0];
        pipeline[0] <= data;
        out <= pipeline[2];
    end
end

endmodule

sva:
module pipeline_reg_sva (
    input logic clk,
    input logic rst,
    input logic data,
    input logic out
);

    // Reset makes the sampled output low on the next clock.
    check_reset_clears_output_next_cycle: assert property (
        @(posedge clk) rst |=> (out == 1'b0)
    );

    // Reset keeps the sampled output low two clocks later.
    check_reset_clears_output_two_cycles_later: assert property (
        @(posedge clk) rst |=> ##1 (out == 1'b0)
    );

    // Reset keeps the sampled output low three clocks later.
    check_reset_clears_output_three_cycles_later: assert property (
        @(posedge clk) rst |=> ##2 (out == 1'b0)
    );

    // Reset keeps the sampled output low four clocks later.
    check_reset_clears_output_four_cycles_later: assert property (
        @(posedge clk) rst |=> ##3 (out == 1'b0)
    );

    // After four reset-free samples, out matches data from four samples earlier.
    check_output_matches_four_cycle_old_data: assert property (
        @(posedge clk) disable iff (rst)
        (!$past(rst,1) && !$past(rst,2) && !$past(rst,3) && !$past(rst,4))
        |-> (out == $past(data,4))
    );

    // A delayed rising data transition causes a rising output transition.
    check_delayed_rise_reaches_output: assert property (
        @(posedge clk) disable iff (rst)
        (!$past(rst,1) && !$past(rst,2) && !$past(rst,3) && !$past(rst,4) && !$past(rst,5) &&
         !$past(data,5) && $past(data,4))
        |-> $rose(out)
    );

    // A delayed falling data transition causes a falling output transition.
    check_delayed_fall_reaches_output: assert property (
        @(posedge clk) disable iff (rst)
        (!$past(rst,1) && !$past(rst,2) && !$past(rst,3) && !$past(rst,4) && !$past(rst,5) &&
         $past(data,5) && !$past(data,4))
        |-> $fell(out)
    );

endmodule

rtl:
module sky130_fd_sc_hs__sedfxbp (
    input D,
    input DE,
    input SCD,
    input SCE,
    input VPWR,
    input VGND,
    output reg Q,
    output reg Q_N,
    input CLK
);

    always @(posedge CLK)
    begin
        if (SCD == 1'b0 && SCE == 1'b0 && DE == 1'b1 && VPWR == 1'b1 && VGND == 1'b0)
        begin
            if (D == 1'b1)
                Q <= 1'b1;
            else
                Q <= 1'b0;
        end
        else if (SCD == 1'b1 && SCE == 1'b1 && DE == 1'b0 && VPWR == 1'b0 && VGND == 1'b1)
        begin
            Q <= 1'b0;
        end
    end

    always @(posedge CLK)
    begin
        if (SCD == 1'b0 && SCE == 1'b0 && DE == 1'b1 && VPWR == 1'b1 && VGND == 1'b0)
        begin
            if (D == 1'b1)
                Q_N <= 1'b0;
            else
                Q_N <= 1'b1;
        end
        else if (SCD == 1'b1 && SCE == 1'b1 && DE == 1'b0 && VPWR == 1'b0 && VGND == 1'b1)
        begin
            Q_N <= 1'b1;
        end
    end

endmodule

sva:
module sky130_fd_sc_hs__sedfxbp_sva (
    input logic D,
    input logic DE,
    input logic SCD,
    input logic SCE,
    input logic VPWR,
    input logic VGND,
    input logic Q,
    input logic Q_N,
    input logic CLK
);

    // Q captures D on the enabled data-load condition.
    check_q_loads_d: assert property (
        @(posedge CLK)
        (SCD == 1'b0 && SCE == 1'b0 && DE == 1'b1 && VPWR == 1'b1 && VGND == 1'b0)
        |=> (Q == $past(D))
    );

    // Q_N captures the inverse of D on the enabled data-load condition.
    check_qn_loads_not_d: assert property (
        @(posedge CLK)
        (SCD == 1'b0 && SCE == 1'b0 && DE == 1'b1 && VPWR == 1'b1 && VGND == 1'b0)
        |=> (Q_N == ~$past(D))
    );

    // The alternate control pattern forces Q low.
    check_q_forced_low: assert property (
        @(posedge CLK)
        (SCD == 1'b1 && SCE == 1'b1 && DE == 1'b0 && VPWR == 1'b0 && VGND == 1'b1)
        |=> (Q == 1'b0)
    );

    // The alternate control pattern forces Q_N high.
    check_qn_forced_high: assert property (
        @(posedge CLK)
        (SCD == 1'b1 && SCE == 1'b1 && DE == 1'b0 && VPWR == 1'b0 && VGND == 1'b1)
        |=> (Q_N == 1'b1)
    );

    // Q holds its value when neither assignment branch is taken.
    check_q_holds_when_no_branch: assert property (
        @(posedge CLK)
        !((SCD == 1'b0 && SCE == 1'b0 && DE == 1'b1 && VPWR == 1'b1 && VGND == 1'b0) ||
          (SCD == 1'b1 && SCE == 1'b1 && DE == 1'b0 && VPWR == 1'b0 && VGND == 1'b1))
        |=> (Q == $past(Q))
    );

    // Q_N holds its value when neither assignment branch is taken.
    check_qn_holds_when_no_branch: assert property (
        @(posedge CLK)
        !((SCD == 1'b0 && SCE == 1'b0 && DE == 1'b1 && VPWR == 1'b1 && VGND == 1'b0) ||
          (SCD == 1'b1 && SCE == 1'b1 && DE == 1'b0 && VPWR == 1'b0 && VGND == 1'b1))
        |=> (Q_N == $past(Q_N))
    );

    // A data-load update produces complementary outputs.
    check_complement_after_data_load: assert property (
        @(posedge CLK)
        (SCD == 1'b0 && SCE == 1'b0 && DE == 1'b1 && VPWR == 1'b1 && VGND == 1'b0)
        |=> (Q_N == ~Q)
    );

    // The alternate control pattern also produces complementary outputs.
    check_complement_after_forced_state: assert property (
        @(posedge CLK)
        (SCD == 1'b1 && SCE == 1'b1 && DE == 1'b0 && VPWR == 1'b0 && VGND == 1'b1)
        |=> (Q_N == ~Q)
    );

endmodule

rtl:
module Modulo (
  input [31:0] a,
  input [31:0] b,
  output reg [31:0] result
);

  always @* begin
    result = a % b;
  end

endmodule

sva:
module Modulo_sva (
    input logic [31:0] a,
    input logic [31:0] b,
    input logic [31:0] result
);

    // No RTL clock or reset; sample this combinational logic on the formal global clock.

    // Result matches the modulo operation when the divisor is nonzero.
    check_result_matches_modulo: assert property (
        @($global_clock) (b != 32'd0) |-> (result == (a % b))
    );

    // For a nonzero divisor, the remainder is always smaller than the divisor.
    check_remainder_less_than_divisor: assert property (
        @($global_clock) (b != 32'd0) |-> (result < b)
    );

    // If the dividend is smaller than a nonzero divisor, the remainder equals the dividend.
    check_small_dividend_passthrough: assert property (
        @($global_clock) ((b != 32'd0) && (a < b)) |-> (result == a)
    );

    // Modulo by one always produces zero.
    check_modulo_by_one_zero: assert property (
        @($global_clock) (b == 32'd1) |-> (result == 32'd0)
    );

    // Equal nonzero operands produce a zero remainder.
    check_equal_operands_zero_result: assert property (
        @($global_clock) ((b != 32'd0) && (a == b)) |-> (result == 32'd0)
    );

    // A zero dividend with a nonzero divisor produces zero.
    check_zero_dividend_zero_result: assert property (
        @($global_clock) ((a == 32'd0) && (b != 32'd0)) |-> (result == 32'd0)
    );

endmodule

rtl:
module sky130_fd_sc_hd__o2bb2a (
    X   ,
    A1_N,
    A2_N,
    B1  ,
    B2
);

    // Module ports
    output X   ;
    input  A1_N;
    input  A2_N;
    input  B1  ;
    input  B2  ;

    // Local signals
    wire nand0_out ;
    wire or0_out   ;
    wire and0_out_X;

    //   Name   Output      Other arguments
    nand nand0 (nand0_out , A2_N, A1_N        );
    or   or0   (or0_out   , B2, B1            );
    and  and0  (and0_out_X, nand0_out, or0_out);
    buf  buf0  (X         , and0_out_X        );

endmodule

sva:
module sky130_fd_sc_hd__o2bb2a_sva (
    input logic clk,
    input logic X,
    input logic A1_N,
    input logic A2_N,
    input logic B1,
    input logic B2
);

    // X matches the implemented NAND/OR/AND logic.
    check_output_function: assert property (
        @(posedge clk)
        X == ((~(A1_N & A2_N)) & (B1 | B2))
    );

    // If both B inputs are low, X must be low.
    check_b_inputs_force_low: assert property (
        @(posedge clk)
        (!B1 && !B2) |-> !X
    );

    // If both A inputs are high, the NAND term is low and X must be low.
    check_a_inputs_force_low: assert property (
        @(posedge clk)
        (A1_N && A2_N) |-> !X
    );

    // If A1_N is low and either B input is high, X must be high.
    check_a1_low_with_b_high_sets_x: assert property (
        @(posedge clk)
        (!A1_N && (B1 || B2)) |-> X
    );

    // If A2_N is low and either B input is high, X must be high.
    check_a2_low_with_b_high_sets_x: assert property (
        @(posedge clk)
        (!A2_N && (B1 || B2)) |-> X
    );

    // A high X requires at least one B input to be high.
    check_x_high_requires_b_high: assert property (
        @(posedge clk)
        X |-> (B1 || B2)
    );

    // A high X requires at least one A input to be low.
    check_x_high_requires_a_low: assert property (
        @(posedge clk)
        X |-> (!A1_N || !A2_N)
    );

endmodule

module signal_combiner_sva (
    input logic A1,
    input logic A2,
    input logic B1,
    input logic B2,
    input logic C1,
    input logic Y,
    input logic VPWR,
    input logic VGND
);

    // Y must match the implemented combinational expression.
    check_y_matches_combiner_function: assert property (
        @($global_clock) Y == ((A1 & A2) | (B1 & B2) | C1)
    );

    // C1 alone is sufficient to drive Y high.
    check_c1_forces_y_high: assert property (
        @($global_clock) C1 |-> Y
    );

    // A1 and A2 high together are sufficient to drive Y high.
    check_a_term_forces_y_high: assert property (
        @($global_clock) (A1 & A2) |-> Y
    );

    // B1 and B2 high together are sufficient to drive Y high.
    check_b_term_forces_y_high: assert property (
        @($global_clock) (B1 & B2) |-> Y
    );

    // Y must be low when all three contributing terms are low.
    check_y_low_when_all_terms_low: assert property (
        @($global_clock) (!C1 && !(A1 & A2) && !(B1 & B2)) |-> !Y
    );

    // A high Y must come from at least one implemented term.
    check_y_high_requires_active_term: assert property (
        @($global_clock) Y |-> (C1 || (A1 & A2) || (B1 & B2))
    );

    // Without C1 and the B term, a high Y must come from the A term.
    check_y_high_without_c1_or_b_term_requires_a_term: assert property (
        @($global_clock) (Y && !C1 && !(B1 & B2)) |-> (A1 & A2)
    );

    // Without C1 and the A term, a high Y must come from the B term.
    check_y_high_without_c1_or_a_term_requires_b_term: assert property (
        @($global_clock) (Y && !C1 && !(A1 & A2)) |-> (B1 & B2)
    );

endmodule

rtl:
module full_adder(
    input a,
    input b,
    input cin,
    output sum,
    output cout
);

    assign sum = a ^ b ^ cin;
    assign cout = (a & b) | (a & cin) | (b & cin);

endmodule

module four_bit_adder(
    input [3:0] A,
    input [3:0] B,
    output [3:0] S,
    output C_out
);

    wire [3:0] carry;

    full_adder FA0(A[0], B[0], 1'b0, S[0], carry[0]);
    full_adder FA1(A[1], B[1], carry[0], S[1], carry[1]);
    full_adder FA2(A[2], B[2], carry[1], S[2], carry[2]);
    full_adder FA3(A[3], B[3], carry[2], S[3], C_out);

endmodule

sva:
module four_bit_adder_sva (
    input logic       clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] S,
    input logic       C_out
);

    // Pure combinational DUT with no RTL reset; sample on external clk.

    // Whole output equals the 5-bit sum of A and B.
    check_total_sum: assert property (
        @(posedge clk) disable iff (1'b0)
        ({C_out, S} == ({1'b0, A} + {1'b0, B}))
    );

    // Bit 0 sum is the XOR of the LSB inputs because cin is tied low.
    check_bit0_sum: assert property (
        @(posedge clk) disable iff (1'b0)
        (S[0] == (A[0] ^ B[0]))
    );

    // Bit 1 sum uses the carry generated by bit 0.
    check_bit1_sum: assert property (
        @(posedge clk) disable iff (1'b0)
        (S[1] == (A[1] ^ B[1] ^ (A[0] & B[0])))
    );

    // Bit 2 sum uses the ripple carry from bit 1.
    check_bit2_sum: assert property (
        @(posedge clk) disable iff (1'b0)
        (S[2] == (
            A[2] ^ B[2] ^
            ((A[1] & B[1]) | ((A[1] | B[1]) & (A[0] & B[0])))
        ))
    );

    // Bit 3 sum uses the ripple carry from bit 2.
    check_bit3_sum: assert property (
        @(posedge clk) disable iff (1'b0)
        (S[3] == (
            A[3] ^ B[3] ^
            ((A[2] & B[2]) | ((A[2] | B[2]) &
                ((A[1] & B[1]) | ((A[1] | B[1]) & (A[0] & B[0])))
            ))
        ))
    );

    // C_out matches the carry-out of the MSB full adder.
    check_final_carry: assert property (
        @(posedge clk) disable iff (1'b0)
        (C_out == (
            (A[3] & B[3]) | ((A[3] | B[3]) &
                ((A[2] & B[2]) | ((A[2] | B[2]) &
                    ((A[1] & B[1]) | ((A[1] | B[1]) & (A[0] & B[0])))
                ))
            )
        ))
    );

endmodule

rtl:
module consecutive_ones (
    input [3:0] in_signal,
    output reg [1:0] out_signal
);

always @*
begin
    case(in_signal)
        4'b0000: out_signal = 2'b00;
        4'b0001: out_signal = 2'b01;
        4'b0010: out_signal = 2'b01;
        4'b0011: out_signal = 2'b01;
        4'b0100: out_signal = 2'b01;
        4'b0101: out_signal = 2'b10;
        4'b0110: out_signal = 2'b10;
        4'b0111: out_signal = 2'b10;
        4'b1000: out_signal = 2'b00;
        4'b1001: out_signal = 2'b01;
        4'b1010: out_signal = 2'b01;
        4'b1011: out_signal = 2'b01;
        4'b1100: out_signal = 2'b01;
        4'b1101: out_signal = 2'b10;
        4'b1110: out_signal = 2'b10;
        4'b1111: out_signal = 2'b10;
    endcase
end

endmodule

sva:
module consecutive_ones_sva (
    input logic clk,
    input logic [3:0] in_signal,
    input logic [1:0] out_signal
);

    // out_signal is 00 when the lower three input bits are 000.
    check_out_zero_for_low3_000: assert property (
        @(posedge clk) (in_signal[2:0] == 3'b000) |-> (out_signal == 2'b00)
    );

    // out_signal is 01 when the lower three input bits are 001.
    check_out_one_for_low3_001: assert property (
        @(posedge clk) (in_signal[2:0] == 3'b001) |-> (out_signal == 2'b01)
    );

    // out_signal is 01 when the lower three input bits are 010.
    check_out_one_for_low3_010: assert property (
        @(posedge clk) (in_signal[2:0] == 3'b010) |-> (out_signal == 2'b01)
    );

    // out_signal is 01 when the lower three input bits are 011.
    check_out_one_for_low3_011: assert property (
        @(posedge clk) (in_signal[2:0] == 3'b011) |-> (out_signal == 2'b01)
    );

    // out_signal is 01 when the lower three input bits are 100.
    check_out_one_for_low3_100: assert property (
        @(posedge clk) (in_signal[2:0] == 3'b100) |-> (out_signal == 2'b01)
    );

    // out_signal is 10 when the lower three input bits are 101.
    check_out_two_for_low3_101: assert property (
        @(posedge clk) (in_signal[2:0] == 3'b101) |-> (out_signal == 2'b10)
    );

    // out_signal is 10 when the lower three input bits are 110.
    check_out_two_for_low3_110: assert property (
        @(posedge clk) (in_signal[2:0] == 3'b110) |-> (out_signal == 2'b10)
    );

    // out_signal is 10 when the lower three input bits are 111.
    check_out_two_for_low3_111: assert property (
        @(posedge clk) (in_signal[2:0] == 3'b111) |-> (out_signal == 2'b10)
    );

    // out_signal is 00 only for the lower-three-bits value 000.
    check_out_zero_only_for_low3_000: assert property (
        @(posedge clk) (out_signal == 2'b00) |-> (in_signal[2:0] == 3'b000)
    );

    // out_signal never takes the unused value 11.
    check_out_never_11: assert property (
        @(posedge clk) (out_signal != 2'b11)
    );

endmodule

module mux4to1_sva (
    input logic [1:0] sel,
    input logic [3:0] in0,
    input logic [3:0] in1,
    input logic [3:0] in2,
    input logic [3:0] in3,
