    );

    // sel=00 routes in0 to out.
    check_sel00_routes_in0: assert property (
        @($global_clock)
        (sel === 2'b00) |-> (out === in0)
    );

    // sel=01 routes in1 to out.
    check_sel01_routes_in1: assert property (
        @($global_clock)
        (sel === 2'b01) |-> (out === in1)
    );

    // sel=10 routes in2 to out.
    check_sel10_routes_in2: assert property (
        @($global_clock)
        (sel === 2'b10) |-> (out === in2)
    );

    // sel=11 routes in3 to out.
    check_sel11_routes_in3: assert property (
        @($global_clock)
        (sel === 2'b11) |-> (out === in3)
    );

endmodule

rtl:
module sel_to_bin(
    input wire [2:0] sel,
    output reg [1:0] bin
    );

    always @ (*) begin
        case (sel)
            3'b000 : bin = 2'b00;
            3'b001 : bin = 2'b01;
            3'b010 : bin = 2'b10;
            3'b011 : bin = 2'b11;
            default : bin = 2'b00;
        endcase
    end
endmodule

