module counter_4bit(
  input clk,
  input set_l,
  output [3:0] count
);

// Register for storing the count value
reg [3:0] count_reg;

// Sequential logic to update the count value
always @(posedge clk or negedge set_l)
  if (!set_l)
    count_reg <= 4'b0;
  else
    count_reg <= count_reg + 4'b1;

// Output the count value
assign count = count_reg;

endmodule

sva:
module counter_4bit_assertions (
    input logic       clk,
    input logic       set_l,
    input logic [3:0] count
);

    // Active-low reset forces the count output to zero.
    check_reset_forces_zero: assert property (
        @(posedge clk) !set_l |-> (count == 4'h0)
    );

    // The first sampled active cycle after reset still shows zero.
    check_first_cycle_after_reset_zero: assert property (
        @(posedge clk) disable iff (!set_l)
        (!$initstate && !$past(set_l)) |-> (count == 4'h0)
    );

    // On consecutive sampled active cycles, count either increments or reflects an async reset pulse.
    check_active_cycle_progression: assert property (
        @(posedge clk) disable iff (!set_l)
        (!$initstate && $past(set_l)) |-> ((count == 4'h0) || (count == (($past(count) + 4'h1) & 4'hF)))
    );

    // A sampled value of 15 wraps to 0 on the next sampled active cycle.
    check_wrap_from_f_to_zero: assert property (
        @(posedge clk) disable iff (!set_l)
        (!$initstate && $past(set_l) && ($past(count) == 4'hF)) |-> (count == 4'h0)
    );

endmodule

rtl:
module xor_pipeline(
  input a,
  input b,
  input clk,
  output reg out
);

  reg a_ff, b_ff;
  wire xor1, xor2;

  always @(posedge clk) begin
    a_ff <= a;
    b_ff <= b;
  end

  assign xor1 = a_ff ^ b_ff;
  assign xor2 = a ^ b;

  always @(posedge clk) begin
    out <= xor1 ^ xor2;
  end

endmodule

sva:
module xor_pipeline_sva (
    input logic a,
    input logic b,
    input logic clk,
    input logic out
);

    // out equals the XOR of the two previous sampled input parities.
    check_out_matches_prior_sampled_parities: assert property (
        @(posedge clk)
        $past(1'b1, 2) |-> (out == (($past(a, 2) ^ $past(b, 2)) ^ ($past(a) ^ $past(b))))
    );

    // Unchanged input parity produces a low out on the next cycle.
    check_out_low_when_parity_is_stable: assert property (
        @(posedge clk)
        ($past(1'b1) && ($past(a ^ b) == (a ^ b))) |=> (out == 1'b0)
    );

    // Changed input parity produces a high out on the next cycle.
    check_out_high_when_parity_changes: assert property (
        @(posedge clk)
        ($past(1'b1) && ($past(a ^ b) != (a ^ b))) |=> (out == 1'b1)
    );

    // Unchanged inputs keep parity stable and force out low on the next cycle.
    check_out_low_when_inputs_hold: assert property (
        @(posedge clk)
        ($past(1'b1) && ($past(a) == a) && ($past(b) == b)) |=> (out == 1'b0)
    );

    // Toggling both inputs together keeps parity stable and forces out low.
    check_out_low_when_both_inputs_toggle: assert property (
        @(posedge clk)
        ($past(1'b1) && ($past(a) != a) && ($past(b) != b)) |=> (out == 1'b0)
    );

    // Toggling only a changes parity and forces out high on the next cycle.
    check_out_high_when_only_a_toggles: assert property (
        @(posedge clk)
        ($past(1'b1) && ($past(a) != a) && ($past(b) == b)) |=> (out == 1'b1)
    );

    // Toggling only b changes parity and forces out high on the next cycle.
    check_out_high_when_only_b_toggles: assert property (
        @(posedge clk)
        ($past(1'b1) && ($past(a) == a) && ($past(b) != b)) |=> (out == 1'b1)
    );

endmodule

rtl:
module binary_counter(
    input clk,
    input reset,
    output reg [2:0] count
);

always @(posedge clk) begin
    if (reset) begin
        count <= 3'b0;
    end else begin
        count <= count + 1;
    end
end

endmodule

sva:
module binary_counter_sva(
    input logic       clk,
    input logic       reset,
    input logic [2:0] count
);

    // Reset clears the counter on the next clock edge.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 3'b000)
    );

    // Count advances from 0 to 1 when not in reset.
    check_count_0_to_1: assert property (
        @(posedge clk) disable iff (reset)
        (count == 3'b000) |=> (count == 3'b001)
    );

    // Count advances from 1 to 2 when not in reset.
    check_count_1_to_2: assert property (
        @(posedge clk) disable iff (reset)
        (count == 3'b001) |=> (count == 3'b010)
    );

    // Count advances from 2 to 3 when not in reset.
    check_count_2_to_3: assert property (
        @(posedge clk) disable iff (reset)
        (count == 3'b010) |=> (count == 3'b011)
    );

    // Count advances from 3 to 4 when not in reset.
    check_count_3_to_4: assert property (
        @(posedge clk) disable iff (reset)
        (count == 3'b011) |=> (count == 3'b100)
    );

    // Count advances from 4 to 5 when not in reset.
    check_count_4_to_5: assert property (
        @(posedge clk) disable iff (reset)
        (count == 3'b100) |=> (count == 3'b101)
    );

    // Count advances from 5 to 6 when not in reset.
    check_count_5_to_6: assert property (
        @(posedge clk) disable iff (reset)
        (count == 3'b101) |=> (count == 3'b110)
    );

    // Count advances from 6 to 7 when not in reset.
    check_count_6_to_7: assert property (
        @(posedge clk) disable iff (reset)
        (count == 3'b110) |=> (count == 3'b111)
    );

    // Count wraps from 7 back to 0 when not in reset.
    check_count_7_to_0: assert property (
        @(posedge clk) disable iff (reset)
        (count == 3'b111) |=> (count == 3'b000)
    );

