rtl:
module my_nand_gate (
    Y   ,
    A   ,
    B   ,
    C   ,
    D   
);

    // Module ports
    output Y   ;
    input  A   ;
    input  B   ;
    input  C   ;
    input  D   ;

    // Local signals
    wire nand0_out;
    wire nand1_out;
    wire nand2_out;
    wire nand3_out;
    wire or0_out;
    wire not0_out;
    wire not1_out;

    // Implement NAND gate using De Morgan's theorem
    nand nand0 (nand0_out, A, B);
    nand nand1 (nand1_out, C, D);
    nand nand2 (nand2_out, nand0_out, nand1_out);
    nand nand3 (nand3_out, nand2_out, nand2_out);
    not  not0  (not0_out, nand3_out);
    not  not1  (Y, not0_out);

endmodule

sva:
module my_nand_gate_sva (
    input logic Y,
    input logic A,
    input logic B,
    input logic C,
    input logic D
);

    // Y matches the implemented gate-level function.
    check_y_function: assert property (
        @($global_clock) Y == ~((A & B) | (C & D))
    );

    // A and B high force the output low.
    check_ab_pair_forces_low: assert property (
        @($global_clock) (A & B) |-> !Y
    );

    // C and D high force the output low.
    check_cd_pair_forces_low: assert property (
        @($global_clock) (C & D) |-> !Y
    );

    // If neither input pair is fully high, the output is high.
    check_no_active_pair_drives_high: assert property (
        @($global_clock) (!(A & B) && !(C & D)) |-> Y
    );

    // All inputs low produce a high output.
    check_all_inputs_low_case: assert property (
        @($global_clock) (!A && !B && !C && !D) |-> Y
    );

    // All inputs high produce a low output.
    check_all_inputs_high_case: assert property (
        @($global_clock) (A && B && C && D) |-> !Y
    );

endmodule

rtl:
module clk_gen(clk100MHz, rst, clk_4sec, clk_5KHz);
  input clk100MHz, rst;
  output clk_4sec, clk_5KHz;
  reg clk_4sec, clk_5KHz;
  integer count, count1;

  always @(posedge clk100MHz or negedge rst) begin
    if (!rst) begin
      count = 0;
      count1 = 0;
      clk_4sec = 0;
      clk_5KHz = 0;
    end else begin
      if (count == 200000000) begin
        clk_4sec = ~clk_4sec;
        count = 0;
      end
      if (count1 == 10000) begin
        clk_5KHz = ~clk_5KHz;
        count1 = 0;
      end
      count = count + 1;
      count1 = count1 + 1;
    end
  end
endmodule

sva:
module clk_gen_sva (
    input logic clk100MHz,
    input logic rst,
    input logic clk_4sec,
    input logic clk_5KHz,
    input integer count,
    input integer count1
);

    // Reset clears both counters and both generated clocks.
    check_reset_clears_state: assert property (
        @(posedge clk100MHz)
        (!rst) |-> ((count == 0) && (count1 == 0) && (clk_4sec == 1'b0) && (clk_5KHz == 1'b0))
    );

    // The first active clock after reset release increments both counters to 1.
    check_first_cycle_after_reset_release: assert property (
        @(posedge clk100MHz) disable iff (!rst)
        $rose(rst) |-> ((count == 1) && (count1 == 1) && (clk_4sec == 1'b0) && (clk_5KHz == 1'b0))
    );

    // count increments by one whenever it is not at its terminal value.
    check_count_increments_below_terminal: assert property (
        @(posedge clk100MHz) disable iff (!rst)
        (count != 200000000) |=> (count == ($past(count) + 1))
    );

    // clk_4sec stays unchanged whenever count is not at its terminal value.
    check_clk_4sec_stable_below_terminal: assert property (
        @(posedge clk100MHz) disable iff (!rst)
        (count != 200000000) |=> $stable(clk_4sec)
    );

    // count wraps to 1 after reaching its terminal value.
    check_count_wraps_at_terminal: assert property (
        @(posedge clk100MHz) disable iff (!rst)
        (count == 200000000) |=> (count == 1)
    );

    // clk_4sec toggles when count reaches its terminal value.
    check_clk_4sec_toggles_at_terminal: assert property (
        @(posedge clk100MHz) disable iff (!rst)
        (count == 200000000) |=> (clk_4sec != $past(clk_4sec))
    );

    // count1 increments by one whenever it is not at its terminal value.
    check_count1_increments_below_terminal: assert property (
        @(posedge clk100MHz) disable iff (!rst)
        (count1 != 10000) |=> (count1 == ($past(count1) + 1))
    );

    // clk_5KHz stays unchanged whenever count1 is not at its terminal value.
    check_clk_5khz_stable_below_terminal: assert property (
        @(posedge clk100MHz) disable iff (!rst)
        (count1 != 10000) |=> $stable(clk_5KHz)
    );

    // count1 wraps to 1 after reaching its terminal value.
    check_count1_wraps_at_terminal: assert property (
        @(posedge clk100MHz) disable iff (!rst)
        (count1 == 10000) |=> (count1 == 1)
    );

    // clk_5KHz toggles when count1 reaches its terminal value.
    check_clk_5khz_toggles_at_terminal: assert property (
        @(posedge clk100MHz) disable iff (!rst)
        (count1 == 10000) |=> (clk_5KHz != $past(clk_5KHz))
    );

endmodule

rtl:
module logical_operation (
    Y ,
    A1,
    A2,
    B1,
    C1,
    D1
);

    output Y ;
    input  A1;
    input  A2;
    input  B1;
    input  C1;
    input  D1;

    assign Y = (A1 & A2) ? 1 :
               (A1 & !A2) ? B1 :
               (!A1 & A2) ? C1 :
               (!A1 & !A2 & !B1 & !C1) ? D1 :
               0;

endmodule

sva:
module logical_operation_sva (
    input logic clk,
    input logic Y,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic C1,
    input logic D1
);

    // Overall output matches the RTL conditional expression.
    check_y_matches_rtl_expression: assert property (
        @(posedge clk)
        Y == ((A1 & A2) ? 1'b1 :
              (A1 & !A2) ? B1 :
              (!A1 & A2) ? C1 :
              (!A1 & !A2 & !B1 & !C1) ? D1 :
              1'b0)
    );

    // When A1 and A2 are high, Y is forced high.
    check_y_high_when_a1_a2_high: assert property (
        @(posedge clk) (A1 && A2) |-> (Y == 1'b1)
    );

    // When A1 is high and A2 is low, Y follows B1.
    check_y_follows_b1_when_a1_high_a2_low: assert property (
        @(posedge clk) (A1 && !A2) |-> (Y == B1)
    );

    // When A1 is low and A2 is high, Y follows C1.
    check_y_follows_c1_when_a1_low_a2_high: assert property (
        @(posedge clk) (!A1 && A2) |-> (Y == C1)
    );

    // When A1 and A2 are low and B1/C1 are low, Y follows D1.
    check_y_follows_d1_in_low_low_zero_case: assert property (
        @(posedge clk) (!A1 && !A2 && !B1 && !C1) |-> (Y == D1)
    );

    // When A1 and A2 are low and either B1 or C1 is high, Y is low.
    check_y_low_in_low_low_nonzero_bc_case: assert property (
        @(posedge clk) (!A1 && !A2 && (B1 || C1)) |-> (Y == 1'b0)
    );

endmodule

