        @($global_clock)
        ((addr == 4'b0000) || (addr == 4'b0111) || (addr == 4'b1101) || (addr == 4'b1110))
        |-> ({r, s, t, x, y, z} == 6'b000000)
    );

    // At most one decoded output is high at a time.
    check_outputs_onehot0: assert property (
        @($global_clock)
