    check_output_definition: assert property (
        @($global_clock)
        X === (((A1 & A2) | (A3 & B1)) ? 1'b1 : 1'b0)
    );

    // A1 and A2 high must drive X high.
    check_a1_a2_path: assert property (
        @($global_clock)
        ((A1 & A2) === 1'b1) |-> (X === 1'b1)
    );

    // A3 and B1 high must drive X high.
    check_a3_b1_path: assert property (
        @($global_clock)
        ((A3 & B1) === 1'b1) |-> (X === 1'b1)
