    check_high_output_has_source: assert property (
        @($global_clock)
        (X === 1'b1) |-> (((A1 & A2) === 1'b1) || ((A3 & B1) === 1'b1))
    );

    // A low X means neither implemented term is high.
    check_low_output_has_no_source: assert property (
        @($global_clock)
