    check_sum_bit2_definition: assert property (
        @(posedge clk) disable iff (1'b0)
        Sum[2] == (A[2] ^ B[2] ^ Sum[1])
    );

    // Sum[3] uses Sum[2] as the third XOR input.
    check_sum_bit3_definition: assert property (
        @(posedge clk) disable iff (1'b0)
        Sum[3] == (A[3] ^ B[3] ^ Sum[2])
