rtl:
module my_module (
    Y ,
    A1,
    A2,
    A3,
    B1,
    C1
);

    output Y ;
    input  A1;
    input  A2;
    input  A3;
    input  B1;
    input  C1;

    wire S1, S2, S3, S4, S5;

    // Implement S1 and S2
    assign S1 = A1 & ~A2;
    assign S2 = ~A1 & A2;

    // Implement S3 and S4
    assign S3 = ~B1 & C1;
    assign S4 = B1 & C1;

    // Implement S5
    assign S5 = ~S1 & ~S2 & ~S3 & ~S4;

    // Implement Y
    assign Y = (A1 & A2 & ~A3) | (B1 & ~C1) | (S1 & S2 & ~S3 & ~S4) | S5;

endmodule

sva:
module my_module_sva (
    input logic clk,
    input logic Y,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic B1,
    input logic C1
);

    // Y matches the implemented combinational function.
    check_y_functional_equivalence: assert property (
        @(posedge clk) disable iff (1'b0)
        Y == ((A1 & A2 & ~A3) | (B1 & ~C1) | (~C1 & (A1 ~^ A2)))
    );

    // When C1 is high, only the A1/A2/A3 term can drive Y.
    check_y_when_c1_high: assert property (
        @(posedge clk) disable iff (1'b0)
        C1 |-> (Y == (A1 & A2 & ~A3))
    );

    // When C1 is low, Y reduces to B1 OR equality of A1 and A2.
    check_y_when_c1_low: assert property (
        @(posedge clk) disable iff (1'b0)
        !C1 |-> (Y == (B1 | (A1 ~^ A2)))
    );

    // The explicit A1&A2&~A3 term always forces Y high.
    check_a_term_drives_y: assert property (
        @(posedge clk) disable iff (1'b0)
        (A1 & A2 & ~A3) |-> Y
    );

    // When C1 is low and A1 equals A2, the S5 path forces Y high.
    check_equal_a_inputs_drive_y_when_c1_low: assert property (
        @(posedge clk) disable iff (1'b0)
        (!C1 && (A1 ~^ A2)) |-> Y
    );

    // When C1 is low, B1 is low, and A1 differs from A2, Y must be low.
    check_unequal_a_inputs_need_b1_when_c1_low: assert property (
        @(posedge clk) disable iff (1'b0)
        (!C1 && !B1 && (A1 ^ A2)) |-> !Y
    );

    // With C1 high, A3 high blocks the A1&A2 term.
    check_a3_blocks_y_when_c1_high: assert property (
        @(posedge clk) disable iff (1'b0)
        (C1 && A1 && A2 && A3) |-> !Y
    );

    // With C1 high, A3 low enables the A1&A2 term.
    check_a3_enables_y_when_c1_high: assert property (
        @(posedge clk) disable iff (1'b0)
        (C1 && A1 && A2 && !A3) |-> Y
    );

endmodule

rtl:
module half_adder (
  input a,
  input b,
  output sum,
  output carry
);

  assign sum = a ^ b;
  assign carry = a & b;

endmodule

module full_adder (
  input a,
  input b,
  input c_in,
  output sum,
  output c_out
);

  wire s1, s2, c1, c2;

  half_adder ha1 (.a(a), .b(b), .sum(s1), .carry(c1));
  half_adder ha2 (.a(s1), .b(c_in), .sum(sum), .carry(c2));
  assign c_out = c1 | c2;

endmodule

sva:
module full_adder_sva (
    input logic clk,
    input logic a,
    input logic b,
    input logic c_in,
    input logic sum,
    input logic c_out
);

    // Sum matches the three-input XOR of the inputs.
    check_sum_xor_function: assert property (
        @(posedge clk) sum == (a ^ b ^ c_in)
    );

    // Carry-out is high when at least two inputs are high.
    check_carry_majority_function: assert property (
        @(posedge clk) c_out == ((a & b) | (a & c_in) | (b & c_in))
    );

    // The two output bits encode the arithmetic sum of the three inputs.
    check_arithmetic_encoding: assert property (
        @(posedge clk) {c_out, sum} == ({1'b0, a} + {1'b0, b} + {1'b0, c_in})
    );

    // Zero inputs produce zero sum and zero carry.
    check_all_zero_case: assert property (
        @(posedge clk) (!a && !b && !c_in) |-> (!sum && !c_out)
    );

    // Exactly one high input produces sum high and carry low.
    check_single_one_case: assert property (
        @(posedge clk) $onehot({a, b, c_in}) |-> (sum && !c_out)
    );

    // Exactly two high inputs produce sum low and carry high.
    check_two_ones_case: assert property (
        @(posedge clk) $onehot({~a, ~b, ~c_in}) |-> (!sum && c_out)
    );

    // All high inputs produce sum high and carry high.
    check_all_one_case: assert property (
        @(posedge clk) (a && b && c_in) |-> (sum && c_out)
    );

    // With c_in low, the full adder reduces to a half adder on a and b.
    check_no_cin_half_adder_behavior: assert property (
        @(posedge clk) (!c_in) |-> ((sum == (a ^ b)) && (c_out == (a & b)))
    );

    // With a low, the full adder reduces to a half adder on b and c_in.
    check_a_zero_reduction: assert property (
        @(posedge clk) (!a) |-> ((sum == (b ^ c_in)) && (c_out == (b & c_in)))
    );

    // With b low, the full adder reduces to a half adder on a and c_in.
    check_b_zero_reduction: assert property (
        @(posedge clk) (!b) |-> ((sum == (a ^ c_in)) && (c_out == (a & c_in)))
    );

endmodule

