    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    // Instances
    and and0 (AB_AND, A, B);
    and and1 (CD_AND, C, D);
    or or0 (AB_OR_CD_AND_E, AB_AND, CD_AND, E);
    buf buf0 (Z, AB_OR_CD_AND_E);

