rtl:
module half_adder(
    input a,
    input b,
    output sum,
    output carry
);

    assign sum = a ^ b;
    assign carry = a & b;

endmodule

module full_adder(
    input A,
    input B,
    input Cin,
    output S,
    output Cout
);

    wire sum1, carry1, sum2, carry2;

    half_adder ha1(.a(A), .b(B), .sum(sum1), .carry(carry1));
    half_adder ha2(.a(sum1), .b(Cin), .sum(sum2), .carry(carry2));

    assign S = sum2;
    assign Cout = carry1 | carry2;

endmodule

sva:
module full_adder_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic Cin,
    input logic S,
    input logic Cout
);

    // Sum matches the XOR of all three inputs.
    check_sum_xor: assert property (
        @(posedge clk) S == ((A ^ B) ^ Cin)
    );

    // Carry-out matches the implemented carry equation.
    check_cout_equation: assert property (
        @(posedge clk) Cout == ((A & B) | (Cin & (A ^ B)))
    );

    // The outputs equal the 2-bit arithmetic sum of the inputs.
    check_arithmetic_result: assert property (
        @(posedge clk) {Cout, S} == ({1'b0, A} + {1'b0, B} + {1'b0, Cin})
    );

    // No asserted inputs produces zero sum and zero carry.
    check_zero_case: assert property (
        @(posedge clk) (!A && !B && !Cin) |-> (!S && !Cout)
    );

    // Exactly one asserted input produces sum without carry.
    check_one_high_case: assert property (
        @(posedge clk) ((A && !B && !Cin) || (!A && B && !Cin) || (!A && !B && Cin)) |-> (S && !Cout)
    );

    // Exactly two asserted inputs produces carry without sum.
    check_two_high_case: assert property (
        @(posedge clk) ((A && B && !Cin) || (A && !B && Cin) || (!A && B && Cin)) |-> (!S && Cout)
    );

    // All three asserted inputs produces both sum and carry.
    check_all_high_case: assert property (
        @(posedge clk) (A && B && Cin) |-> (S && Cout)
    );

endmodule

rtl:
module calculator (
  input clk,
  input areset, // async active-high reset to zero
  input load,
  input ena,
  input [2:0] bin_in,  // Binary input for the binary to binary converter
  input shift_left,   // Control input to shift left instead of right
  input operation,    // 0 for addition, 1 for subtraction
  output [3:0] result // 4-bit output from the shift register
);

  wire [2:0] bin_out;
  wire o2, o1, o0;
  binary_to_binary b2b(.vec(bin_in), .outv(bin_out), .o2(o2), .o1(o1), .o0(o0));
  shift_register sr(.clk(clk), .areset(areset), .load(load), .ena(ena), .shift_left(shift_left), .data_in({bin_out[2], bin_out[1], bin_out[0], o2, o1, o0}), .result(result));

  reg [3:0] reg_result;

  always @(posedge clk or posedge areset) begin
    if (areset) begin
      reg_result <= 0;
    end else if (load) begin
      reg_result <= {1'b0, bin_out};
    end else if (ena) begin
      if (operation == 0) begin
        reg_result <= reg_result + {1'b0, bin_out};
      end else begin
        reg_result <= reg_result - {1'b0, bin_out};
      end
    end
  end

endmodule
module binary_to_binary (
  input wire [2:0] vec, // 3-bit binary input
  output wire [2:0] outv, // Binary output
  output wire o2, // Output corresponding to the input binary at bit position 2
  output wire o1, // Output corresponding to the input binary at bit position 1
  output wire o0 // Output corresponding to the input binary at bit position 0
);

  assign outv = vec;
  assign o2 = vec[2];
  assign o1 = vec[1];
  assign o0 = vec[0];

endmodule
module shift_register (
  input clk,
  input areset, // async active-high reset to zero
  input load,
  input ena,
  input shift_left,   // Control input to shift left instead of right
  input [5:0] data_in, // 6-bit input for the shift register
  output reg [3:0] result // 4-bit output from the shift register
);

  always @(posedge clk or posedge areset) begin
    if (areset) begin
      result <= 0;
    end else if (load) begin
      result <= data_in[3:0];
    end else if (ena) begin
      if (shift_left) begin
        result <= {result[2:0], data_in[5]};
      end else begin
        result <= {data_in[4], result[3:1]};
      end
    end
  end

endmodule

sva:
module calculator_sva (
    input logic clk,
    input logic areset,
    input logic load,
    input logic ena,
    input logic [2:0] bin_in,
    input logic shift_left,
    input logic operation,
    input logic [3:0] result
);

    // Reset forces the visible result to zero.
    check_reset_clears_result: assert property (
        @(posedge clk) areset |-> (result == 4'b0000)
    );

    // Load writes data_in[3:0], overriding any enabled shift.
    check_load_updates_result: assert property (
        @(posedge clk) disable iff (areset)
        load |=> (result == {$past(bin_in[0]), $past(bin_in[2]), $past(bin_in[1]), $past(bin_in[0])})
    );

    // Enabled left shift moves result left and inserts bin_in[2].
    check_shift_left_behavior: assert property (
        @(posedge clk) disable iff (areset)
        (!load && ena && shift_left) |=> (result == {$past(result[2:0]), $past(bin_in[2])})
    );

    // Enabled right shift moves result right and inserts bin_in[1].
    check_shift_right_behavior: assert property (
        @(posedge clk) disable iff (areset)
        (!load && ena && !shift_left) |=> (result == {$past(bin_in[1]), $past(result[3:1])})
    );

    // Without load or enable, result holds its value.
    check_idle_holds_result: assert property (
        @(posedge clk) disable iff (areset)
        (!load && !ena) |=> (result == $past(result))
    );

endmodule

rtl:
module accumulator (
  input clk, // clock signal
  input [15:0] data, // input data signal
  output [15:0] acc // accumulated value
);

  // Define a register to store the accumulated value
  reg [15:0] acc_reg;

  // Reset the accumulator to zero on power up or when a reset signal is received
  initial begin
    acc_reg <= 16'd0;
  end

  // On the rising edge of the clock signal, add the input data value to the previous accumulated value
  always @(posedge clk) begin
    acc_reg <= acc_reg + data;
  end

  // Assign the accumulated value to the output
  assign acc = acc_reg;

endmodule

sva:
module accumulator_assertions (
    input logic        clk,
    input logic [15:0] data,
    input logic [15:0] acc
);

    // Clock: clk
    // Reset: none
    // Sequential accumulator with registered output

    // The accumulator adds the previous cycle's data on each rising clock edge.
    check_accumulates_data: assert property (
        @(posedge clk) disable iff (1'b0)
        1'b1 |=> acc == ($past(acc) + $past(data))
    );

    // The cycle-to-cycle change in acc matches the previous cycle's data.
    check_cycle_delta_matches_data: assert property (
        @(posedge clk) disable iff (1'b0)
        1'b1 |=> (acc - $past(acc)) == $past(data)
    );

    // A zero input leaves the accumulator unchanged on the next cycle.
    check_hold_on_zero_data: assert property (
        @(posedge clk) disable iff (1'b0)
        data == 16'd0 |=> acc == $past(acc)
    );

    // An input of one increments the accumulator by one on the next cycle.
    check_increment_on_one: assert property (
        @(posedge clk) disable iff (1'b0)
        data == 16'd1 |=> acc == ($past(acc) + 16'd1)
    );

    // If the accumulator is zero, the next value equals the current input data.
    check_load_data_from_zero: assert property (
        @(posedge clk) disable iff (1'b0)
        acc == 16'd0 |=> acc == $past(data)
    );

    // Adding one to 16'hFFFF wraps the accumulator to zero.
    check_wrap_on_full_plus_one: assert property (
        @(posedge clk) disable iff (1'b0)
        (acc == 16'hFFFF) && (data == 16'd1) |=> acc == 16'd0
    );

    // An input of 16'hFFFF decrements the accumulator by one on the next cycle.
    check_decrement_on_all_ones_data: assert property (
        @(posedge clk) disable iff (1'b0)
        data == 16'hFFFF |=> acc == ($past(acc) - 16'd1)
    );

endmodule

rtl:
module binary_converter (
    input [3:0] D,
    output [2:0] Q
);

    wire [1:0] subtract;

    assign subtract = D[3:2] - 2'b11;

    assign Q = (D <= 4'b0111) ? D[2:0] : subtract;

endmodule

sva:
module binary_converter_sva (
    input logic        clk,
    input logic [3:0]  D,
    input logic [2:0]  Q
);

    // Q must follow the RTL's full combinational mapping.
    check_full_mapping: assert property (
        @(posedge clk)
        Q == ((D[3] == 1'b0) ? D[2:0] : {1'b0, (D[3:2] - 2'b11)})
    );

    // Inputs 0 through 7 pass D[2:0] directly to Q.
    check_low_range_passthrough: assert property (
        @(posedge clk)
        (D[3] == 1'b0) |-> (Q == D[2:0])
    );

    // Inputs 8 through 15 use the subtract result, zero-extended to 3 bits.
    check_high_range_conversion: assert property (
        @(posedge clk)
        (D[3] == 1'b1) |-> (Q == {1'b0, (D[3:2] - 2'b11)})
    );

    // For inputs 8 through 11, Q must be 3.
    check_range_8_to_11_value: assert property (
        @(posedge clk)
        (D[3:2] == 2'b10) |-> (Q == 3'b011)
    );

    // For inputs 12 through 15, Q must be 0.
    check_range_12_to_15_value: assert property (
        @(posedge clk)
        (D[3:2] == 2'b11) |-> (Q == 3'b000)
    );

    // The upper bit of Q is cleared whenever the subtract path is selected.
    check_high_range_msb_zero: assert property (
        @(posedge clk)
        (D[3] == 1'b1) |-> (Q[2] == 1'b0)
    );

endmodule

rtl:
module shift_register_combination (
    input CLK,
    input PL1,
    input CLR1,
    input PL2,
    input EN2,
    input [3:0] D1,
    input [3:0] D2,
    output [7:0] Q
);

reg [3:0] reg1;
reg [3:0] reg2;

always @(posedge CLK) begin
    if (CLR1) 
        reg1 <= 4'b0;
    else if (PL1) 
        reg1 <= D1;
    else 
        reg1 <= {reg1[2:0], reg1[3]};
end

always @(negedge CLK) begin
    if (EN2) 
        reg2 <= {reg2[2:0], D2};
end

assign Q = {reg1, reg2};

endmodule

sva:
module shift_register_combination_sva (
    input logic CLK,
    input logic PL1,
    input logic CLR1,
    input logic PL2,
    input logic EN2,
    input logic [3:0] D1,
    input logic [3:0] D2,
    input logic [7:0] Q
);

    // CLR1 clears the upper nibble on the next posedge sample.
    check_reg1_clear: assert property (
        @(posedge CLK) disable iff (1'b0)
        CLR1 |=> (Q[7:4] == 4'b0000)
    );

    // CLR1 has priority over PL1 when both are asserted.
    check_reg1_clear_priority: assert property (
        @(posedge CLK) disable iff (1'b0)
        (CLR1 && PL1) |=> (Q[7:4] == 4'b0000)
    );

    // PL1 loads D1 into the upper nibble when CLR1 is low.
    check_reg1_parallel_load: assert property (
        @(posedge CLK) disable iff (1'b0)
        (!CLR1 && PL1) |=> (Q[7:4] == $past(D1))
    );

    // Without CLR1 or PL1, the upper nibble rotates left by one bit.
    check_reg1_rotate: assert property (
        @(posedge CLK) disable iff (1'b0)
        (!CLR1 && !PL1) |=> (Q[7:4] == {$past(Q[6:4]), $past(Q[7])})
    );

    // EN2 loads the lower nibble with D2 on the next negedge sample.
    check_reg2_load_d2: assert property (
        @(negedge CLK) disable iff (1'b0)
        EN2 |=> (Q[3:0] == $past(D2))
    );

    // Without EN2, the lower nibble holds its value across negedges.
    check_reg2_hold: assert property (
        @(negedge CLK) disable iff (1'b0)
        (!EN2) |=> (Q[3:0] == $past(Q[3:0]))
    );

endmodule

