module sync_dff_en_W32 (clk, en, te, d, q);

  input clk, en, te;
  input [31:0] d;
  output reg [31:0] q;

  always @(posedge clk) begin
    if (en) begin
      if (te) begin
        q <= d;
      end else begin
        q <= #1 d;
      end
    end
  end

endmodule

sva:
module sync_dff_en_W32_sva (
    input logic        clk,
    input logic        en,
    input logic        te,
    input logic [31:0] d,
    input logic [31:0] q
);

    // When enabled in test mode, q captures d by the next clock.
    check_capture_te_branch: assert property (
        @(posedge clk) (en && te) |=> (q == $past(d))
    );

    // When enabled in normal mode, q captures d by the next clock.
    check_capture_normal_branch: assert property (
        @(posedge clk) (en && !te) |=> (q == $past(d))
    );

    // When disabled with te high, q holds its value.
    check_hold_disabled_te_high: assert property (
        @(posedge clk) (!en && te) |=> (q == $past(q))
    );

    // When disabled with te low, q holds its value.
    check_hold_disabled_te_low: assert property (
        @(posedge clk) (!en && !te) |=> (q == $past(q))
    );

    // If enabled and d differs from q, q updates to the new value on the next clock.
    check_update_when_enabled_and_data_differs: assert property (
        @(posedge clk) (en && (d != q)) |=> ((q == $past(d)) && (q != $past(q)))
    );

endmodule

rtl:
module t ( reset, a, b, c, en, o1, o2, o3, o4, o5);
   input  reset;
   input  a;
   input  b;
   input  c;
   input  en;
   output reg o1; output reg o2; output reg o3; output reg o4; output reg o5; always @(reset or en or a or b)
if (reset)
begin
    o1 = 1'b0;
    o2 = 1'b0;
    o3 = 1'b0;
    o4 = 1'b0;
    o5 <= 1'b0; end
else
begin
    o1 = 1'b1;
    if (en)
    begin
        o2 = 1'b0;

	    if (a)
	    begin
            o3 = a;
            o5 <= 1'b1; end
	    else
	    begin
            o3 = ~a;
            o5 <=  a; end

        if (c)
	    begin
            o2 = a ^ b;
            o4 = 1'b1;
        end
	    else
            o4 = ~a ^ b;

        o2 = 1'b1;
    end
    else
    begin
        o2 = 1'b1;
	    if (b)
        begin
            o3 = ~a | b;
            o5 <= ~b; end
	    else
	    begin
            o3 = a & ~b;
            end
        o4 <= 1'b0; end
end

endmodule

sva:
module t_assertions (
    input logic reset,
    input logic a,
    input logic b,
    input logic c,
    input logic en,
    input logic o1,
    input logic o2,
    input logic o3,
    input logic o4,
    input logic o5
);

    // A c-only change does not trigger this process.
    check_c_only_change_holds_outputs: assert property (
        @($global_clock) disable iff ($initstate)
        ($changed(c) && !$changed(reset) && !$changed(en) && !$changed(a) && !$changed(b))
        |-> $stable({o1, o2, o3, o4, o5})
    );

    // Any evaluation while reset is high clears all outputs.
    check_reset_clears_outputs: assert property (
        @($global_clock) disable iff ($initstate)
        (($changed(reset) || $changed(en) || $changed(a) || $changed(b)) && reset)
        |-> (o1 == 1'b0 && o2 == 1'b0 && o3 == 1'b0 && o4 == 1'b0 && o5 == 1'b0)
    );

    // Any non-reset evaluation drives o1 high.
    check_o1_high_out_of_reset: assert property (
        @($global_clock) disable iff (reset || $initstate)
        ($changed(reset) || $changed(en) || $changed(a) || $changed(b))
        |-> (o1 == 1'b1)
    );

    // Any non-reset evaluation leaves o2 high.
    check_o2_high_out_of_reset: assert property (
        @($global_clock) disable iff (reset || $initstate)
        ($changed(reset) || $changed(en) || $changed(a) || $changed(b))
        |-> (o2 == 1'b1)
    );

    // With en high, o3 is driven high.
    check_en_branch_o3_high: assert property (
        @($global_clock) disable iff (reset || $initstate)
        (($changed(reset) || $changed(en) || $changed(a) || $changed(b)) && en)
        |-> (o3 == 1'b1)
    );

    // With en high, o5 follows a.
    check_en_branch_o5_matches_a: assert property (
        @($global_clock) disable iff (reset || $initstate)
        (($changed(reset) || $changed(en) || $changed(a) || $changed(b)) && en)
        |-> (o5 == a)
    );

    // With en high, o4 follows the c-selected assignment.
    check_en_branch_o4_function: assert property (
        @($global_clock) disable iff (reset || $initstate)
        (($changed(reset) || $changed(en) || $changed(a) || $changed(b)) && en)
        |-> (o4 == (c ? 1'b1 : ((~a) ^ b)))
    );

    // With en low, o3 matches a OR b.
    check_dis_branch_o3_function: assert property (
        @($global_clock) disable iff (reset || $initstate)
        (($changed(reset) || $changed(en) || $changed(a) || $changed(b)) && !en)
        |-> (o3 == (a | b))
    );

    // With en low, o4 is driven low.
    check_dis_branch_o4_low: assert property (
        @($global_clock) disable iff (reset || $initstate)
        (($changed(reset) || $changed(en) || $changed(a) || $changed(b)) && !en)
        |-> (o4 == 1'b0)
    );

    // With en low and b high, o5 is driven low.
    check_dis_branch_b_high_o5_low: assert property (
        @($global_clock) disable iff (reset || $initstate)
        (($changed(reset) || $changed(en) || $changed(a) || $changed(b)) && !en && b)
        |-> (o5 == 1'b0)
    );

    // With en low and b low, o5 keeps its previous value.
    check_dis_branch_b_low_o5_holds: assert property (
        @($global_clock) disable iff (reset || $initstate)
        (($changed(reset) || $changed(en) || $changed(a) || $changed(b)) && !en && !b)
        |-> (o5 == $past(o5))
    );

endmodule

rtl:
module PIO_TO_CTRL    (

                        clk,
                        rst_n,

                        req_compl_i,
                        compl_done_i,

                        cfg_to_turnoff,
                        cfg_turnoff_ok

                        );

    input               clk;
    input               rst_n;

    input               req_compl_i;
    input               compl_done_i;

    input               cfg_to_turnoff;
    output              cfg_turnoff_ok;

    reg                 trn_pending;
    reg                 cfg_turnoff_ok;


   //  *  Check if completion is pending

    always @ ( posedge clk or negedge rst_n ) begin

        if (!rst_n ) begin

          trn_pending <= 0;

        end else begin

          if (!trn_pending && req_compl_i)

            trn_pending <= 1'b1;

          else if (compl_done_i)

            trn_pending <= 1'b0;

        end

    end

    // *  Turn-off OK if requested and no transaction is pending

     always @ ( posedge clk or negedge rst_n ) begin

      if (!rst_n ) begin

        cfg_turnoff_ok <= 1'b0;

      end else begin

        if ( cfg_to_turnoff  && !trn_pending)
          cfg_turnoff_ok <= 1'b1;
        else
          cfg_turnoff_ok <= 1'b0;

      end

    end


endmodule

sva:
module PIO_TO_CTRL_sva (
    input logic clk,
    input logic rst_n,
    input logic req_compl_i,
    input logic compl_done_i,
    input logic cfg_to_turnoff,
    input logic cfg_turnoff_ok,
    input logic trn_pending
);

    // trn_pending is cleared while reset is active.
    check_trn_pending_reset: assert property (
        @(posedge clk) !rst_n |-> (trn_pending == 1'b0)
    );

    // cfg_turnoff_ok is cleared while reset is active.
    check_cfg_turnoff_ok_reset: assert property (
        @(posedge clk) !rst_n |-> (cfg_turnoff_ok == 1'b0)
    );

    // A request sets trn_pending on the next cycle when no transaction is pending.
    check_trn_pending_set_on_request: assert property (
        @(posedge clk) disable iff (!rst_n)
        (!trn_pending && req_compl_i) |=> (trn_pending == 1'b1)
    );

    // trn_pending stays low without a request when already idle.
    check_trn_pending_stays_low_without_request: assert property (
        @(posedge clk) disable iff (!rst_n)
        (!trn_pending && !req_compl_i) |=> (trn_pending == 1'b0)
    );

    // compl_done_i clears trn_pending on the next cycle when a transaction is pending.
    check_trn_pending_clear_on_completion: assert property (
        @(posedge clk) disable iff (!rst_n)
        (trn_pending && compl_done_i) |=> (trn_pending == 1'b0)
    );

    // trn_pending stays high until compl_done_i is asserted.
    check_trn_pending_hold_while_waiting: assert property (
        @(posedge clk) disable iff (!rst_n)
        (trn_pending && !compl_done_i) |=> (trn_pending == 1'b1)
    );

    // Turnoff is acknowledged on the next cycle when requested with no pending transaction.
    check_turnoff_ok_when_requested_and_idle: assert property (
        @(posedge clk) disable iff (!rst_n)
        (cfg_to_turnoff && !trn_pending) |=> (cfg_turnoff_ok == 1'b1)
    );

    // Without a turnoff request, cfg_turnoff_ok is low on the next cycle.
    check_turnoff_ok_low_without_request: assert property (
        @(posedge clk) disable iff (!rst_n)
        (!cfg_to_turnoff) |=> (cfg_turnoff_ok == 1'b0)
    );

    // A pending transaction blocks turnoff acknowledgment.
    check_turnoff_ok_blocked_by_pending: assert property (
        @(posedge clk) disable iff (!rst_n)
        (cfg_to_turnoff && trn_pending) |=> (cfg_turnoff_ok == 1'b0)
    );

endmodule

rtl:
module RoboticVehicleController(DigitalLDir, DigitalRDir, reset_n, outputs);
    input DigitalLDir;
    input DigitalRDir;
    input reset_n;
    output [3:0]outputs;

    reg [3:0]outputs_reg;

    always @(*) begin
        if (reset_n == 1'b0) begin
            outputs_reg <= 4'b0000;
        end else begin
            case ({DigitalLDir, DigitalRDir})
                2'b11: outputs_reg <= 4'b1111;
                2'b10: outputs_reg <= 4'b1100;
                2'b01: outputs_reg <= 4'b0011;
                default: outputs_reg <= 4'b0000;
            endcase
        end
    end

    assign outputs = outputs_reg;

endmodule

sva:
module RoboticVehicleController_sva(
    input logic       DigitalLDir,
    input logic       DigitalRDir,
    input logic       reset_n,
    input logic [3:0] outputs
);

    // Active-low reset forces all outputs low.
    check_reset_forces_zero: assert property (
        @($global_clock)
        !reset_n |-> (outputs == 4'b0000)
    );

    // Upper output bits mirror the left direction input outside reset.
    check_upper_bits_follow_left: assert property (
        @($global_clock) disable iff (!reset_n)
        (outputs[3:2] == {2{DigitalLDir}})
    );

    // Lower output bits mirror the right direction input outside reset.
    check_lower_bits_follow_right: assert property (
        @($global_clock) disable iff (!reset_n)
        (outputs[1:0] == {2{DigitalRDir}})
    );

    // Both direction inputs high drive all outputs high.
    check_map_11_to_1111: assert property (
        @($global_clock) disable iff (!reset_n)
        ({DigitalLDir, DigitalRDir} == 2'b11) |-> (outputs == 4'b1111)
    );

    // Left high and right low drive only the upper outputs high.
    check_map_10_to_1100: assert property (
        @($global_clock) disable iff (!reset_n)
        ({DigitalLDir, DigitalRDir} == 2'b10) |-> (outputs == 4'b1100)
    );

    // Left low and right high drive only the lower outputs high.
    check_map_01_to_0011: assert property (
        @($global_clock) disable iff (!reset_n)
        ({DigitalLDir, DigitalRDir} == 2'b01) |-> (outputs == 4'b0011)
    );

    // Both direction inputs low drive all outputs low.
    check_map_00_to_0000: assert property (
        @($global_clock) disable iff (!reset_n)
        ({DigitalLDir, DigitalRDir} == 2'b00) |-> (outputs == 4'b0000)
    );

    // Outside reset, outputs always match the full combinational mapping.
    check_full_direction_mapping: assert property (
        @($global_clock) disable iff (!reset_n)
        (outputs == {DigitalLDir, DigitalLDir, DigitalRDir, DigitalRDir})
    );

endmodule

rtl:
module consecutive_zeros_counter (
    input [15:0] in,
    output reg [3:0] out
);

reg [3:0] stage1_out;
reg [15:0] stage2_out;
reg [3:0] stage3_out;

// Stage 1: Fetch input
always @(*) begin
    stage1_out = in[15:12];
end

// Stage 2: Split input into nibbles
always @(*) begin
    stage2_out[15:12] = in[11:8];
    stage2_out[11:8] = in[7:4];
    stage2_out[7:4] = in[3:0];
    stage2_out[3:0] = 4'b0;
end

// Stage 3: Detect consecutive 0's in each nibble
always @(*) begin
    stage3_out = 4'b0;
    if (stage2_out[15:12] == 4'b0000) stage3_out = stage3_out + 1;
    if (stage2_out[11:8] == 4'b0000) stage3_out = stage3_out + 1;
    if (stage2_out[7:4] == 4'b0000) stage3_out = stage3_out + 1;
    if (stage2_out[3:0] == 4'b0000) stage3_out = stage3_out + 1;
end

// Stage 4: Output total number of consecutive 0's found in input
always @(*) begin
    out <= stage1_out + stage3_out;
end

endmodule

sva:
module consecutive_zeros_counter_sva (
    input logic clk,
    input logic [15:0] in,
    input logic [3:0] out,
    input logic [3:0] stage1_out,
    input logic [15:0] stage2_out,
    input logic [3:0] stage3_out
);

    function automatic [3:0] expected_stage3_from_in(input logic [15:0] din);
        expected_stage3_from_in = 4'd1
                                + {3'b0, (din[11:8] == 4'b0000)}
                                + {3'b0, (din[7:4]  == 4'b0000)}
                                + {3'b0, (din[3:0]  == 4'b0000)};
    endfunction

    function automatic [3:0] zero_nibble_count(input logic [15:0] din);
        zero_nibble_count = {3'b0, (din[15:12] == 4'b0000)}
                          + {3'b0, (din[11:8]  == 4'b0000)}
                          + {3'b0, (din[7:4]   == 4'b0000)}
                          + {3'b0, (din[3:0]   == 4'b0000)};
    endfunction

    // Stage 1 copies the upper input nibble.
    check_stage1_upper_nibble: assert property (
        @(posedge clk) stage1_out == in[15:12]
    );

    // Stage 2 shifts the lower three nibbles up and pads the low nibble with zero.
    check_stage2_mapping: assert property (
        @(posedge clk) stage2_out == {in[11:8], in[7:4], in[3:0], 4'b0000}
    );

    // Stage 3 counts the zero-valued nibbles in stage2_out.
    check_stage3_zero_count: assert property (
        @(posedge clk) stage3_out == zero_nibble_count(stage2_out)
    );

    // Stage 3 matches the zero-count implied directly by the input.
    check_stage3_from_input: assert property (
        @(posedge clk) stage3_out == expected_stage3_from_in(in)
    );

    // Stage 3 is always between one and four.
    check_stage3_range: assert property (
        @(posedge clk) (stage3_out >= 4'd1) && (stage3_out <= 4'd4)
    );

    // The output is the sum of stage1_out and stage3_out.
    check_out_stage_sum: assert property (
        @(posedge clk) out == (stage1_out + stage3_out)
    );

    // The output matches the full input-derived expression.
    check_out_end_to_end: assert property (
        @(posedge clk) out == (in[15:12] + expected_stage3_from_in(in))
    );

    // If no lower input nibble is zero, the count is one.
    check_stage3_only_padded_zero: assert property (
        @(posedge clk)
        (in[11:8] != 4'b0000 && in[7:4] != 4'b0000 && in[3:0] != 4'b0000) |-> (stage3_out == 4'd1)
    );

    // If all lower input nibbles are zero, the count is four.
    check_stage3_all_zero_nibbles: assert property (
        @(posedge clk)
        (in[11:8] == 4'b0000 && in[7:4] == 4'b0000 && in[3:0] == 4'b0000) |-> (stage3_out == 4'd4)
    );

endmodule

rtl:
module counter_register (
    input clk,
    input reset,      // Synchronous active-high reset
    input [7:0] data, // 8-bit input for the register
    input select,     // Select input to choose between register and counter
    output reg [7:0] sum  // 8-bit output from the system
);

    reg [3:0] counter;  // 4-bit binary counter
    reg [7:0] register; // 8-bit register

    always @(posedge clk) begin
        if (reset) begin
            counter <= 4'b0;
            register <= 8'b0;
            sum <= 8'b0;
        end else begin
            if (select) begin
                register <= data;
                sum <= register + counter;
            end else begin
                counter <= counter + 1;
                sum <= register + counter;
            end
        end
    end

endmodule

module top_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input [7:0] data, // 8-bit input for the register
    input select,     // Select input to choose between register and counter
    output [7:0] sum  // 8-bit output from the system
);

    counter_register cr (
        .clk(clk),
        .reset(reset),
        .data(data),
        .select(select),
        .sum(sum)
    );

endmodule

sva:
module counter_register_sva (
    input logic       clk,
    input logic       reset,
    input logic [7:0] data,
    input logic       select,
    input logic [7:0] sum,
    input logic [3:0] counter,
    input logic [7:0] register
);

    // Synchronous reset clears all state on the next clock.
    check_reset_clears_state: assert property (
        @(posedge clk)
        reset |=> (counter == 4'h0) && (register == 8'h00) && (sum == 8'h00)
    );

    // A selected cycle loads the register from data.
    check_select_loads_register: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        $past(!reset && select) |-> (register == $past(data))
    );

    // A selected cycle leaves the counter unchanged.
    check_select_holds_counter: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        $past(!reset && select) |-> (counter == $past(counter))
    );

    // A selected cycle updates sum from the prior register and counter.
    check_select_sum_uses_prior_state: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        $past(!reset && select) |-> (sum == ($past(register) + {4'b0000, $past(counter)}))
    );

    // A count cycle increments the counter by one.
    check_count_increments_counter: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        $past(!reset && !select) |-> (counter == ($past(counter) + 4'h1))
    );

    // A count cycle leaves the register unchanged.
    check_count_holds_register: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        $past(!reset && !select) |-> (register == $past(register))
    );

    // A count cycle updates sum from the prior register and counter.
    check_count_sum_uses_prior_state: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        $past(!reset && !select) |-> (sum == ($past(register) + {4'b0000, $past(counter)}))
    );

endmodule

bind counter_register counter_register_sva counter_register_sva_inst (
    .clk(clk),
    .reset(reset),
    .data(data),
    .select(select),
    .sum(sum),
    .counter(counter),
    .register(register)
);

module counter_sva (
    input logic       clk,
    input logic       reset,
    input logic [3:0] count
);

    // A reset cycle forces count to zero on the following clock.
    check_reset_clears_count: assert property (
        @(posedge clk) disable iff (reset)
        $past(reset) |-> (count == 4'd0)
    );

    // Without reset, count increments by one when below the maximum value.
    check_count_increments_no_wrap: assert property (
        @(posedge clk) disable iff (reset)
        (!$past(reset) && ($past(count) < 4'hF)) |-> (count == ($past(count) + 4'd1))
    );

    // Without reset, count wraps from 15 back to zero.
    check_count_wraps_to_zero: assert property (
        @(posedge clk) disable iff (reset)
        (!$past(reset) && ($past(count) == 4'hF)) |-> (count == 4'd0)
    );

endmodule

rtl:
module lfsr_3bit (
    input CLK,
    output reg Q0,
    output reg Q1,
    output reg Q2
);

reg [2:0] lfsr_reg;

always @(posedge CLK) begin
    lfsr_reg <= {lfsr_reg[1:0], lfsr_reg[2] ^ lfsr_reg[1]};
end

always @* begin
    Q0 = lfsr_reg[0];
    Q1 = lfsr_reg[1];
    Q2 = lfsr_reg[2];
end

endmodule

sva:
module lfsr_3bit_sva (
    input logic CLK,
    input logic Q0,
    input logic Q1,
    input logic Q2
);

    // Q2 shifts in the previous Q1 value.
    check_q2_shift: assert property (
        @(posedge CLK) 1'b1 |=> (Q2 == $past(Q1))
    );

    // Q1 shifts in the previous Q0 value.
    check_q1_shift: assert property (
        @(posedge CLK) 1'b1 |=> (Q1 == $past(Q0))
    );

    // Q0 is the XOR of the previous Q2 and Q1 values.
    check_q0_feedback: assert property (
        @(posedge CLK) 1'b1 |=> (Q0 == ($past(Q2) ^ $past(Q1)))
    );

    // The full 3-bit output state follows the RTL next-state function.
    check_state_update: assert property (
        @(posedge CLK) 1'b1 |=> ({Q2, Q1, Q0} == {$past(Q1), $past(Q0), ($past(Q2) ^ $past(Q1))})
    );

    // Equal previous Q2 and Q1 drive Q0 low on the next cycle.
    check_feedback_zero_case: assert property (
        @(posedge CLK) (Q2 == Q1) |=> (Q0 == 1'b0)
    );

    // Different previous Q2 and Q1 drive Q0 high on the next cycle.
    check_feedback_one_case: assert property (
        @(posedge CLK) (Q2 != Q1) |=> (Q0 == 1'b1)
    );

    // The all-zero state remains all-zero on the next cycle.
    check_zero_lockup: assert property (
        @(posedge CLK) ({Q2, Q1, Q0} == 3'b000) |=> ({Q2, Q1, Q0} == 3'b000)
    );

endmodule

rtl:
module mux_2to1(
    input A,
    input B,
    input S,
    output Y
);

assign Y = (~S & A) | (S & B);

endmodule

sva:
module mux_2to1_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic S,
    input logic Y
);

    // Y must implement the 2:1 mux equation.
    check_mux_equation: assert property (
        @(posedge clk) Y == ((~S & A) | (S & B))
    );

    // When S is low, Y must select A.
    check_select_a: assert property (
        @(posedge clk) !S |-> (Y == A)
    );

    // When S is high, Y must select B.
    check_select_b: assert property (
        @(posedge clk) S |-> (Y == B)
    );

    // If both inputs are equal, Y must match that value.
    check_equal_inputs: assert property (
        @(posedge clk) (A == B) |-> (Y == A)
    );

    // With A=0 and B=1, Y must follow S.
    check_follow_s: assert property (
        @(posedge clk) (A == 1'b0 && B == 1'b1) |-> (Y == S)
    );

    // With A=1 and B=0, Y must follow inverted S.
    check_follow_not_s: assert property (
        @(posedge clk) (A == 1'b1 && B == 1'b0) |-> (Y == ~S)
    );

endmodule

rtl:
module four_bit_adder(
    input [3:0] A,
    input [3:0] B,
    input C_in,
    output [3:0] S,
    output C_out
);

wire [3:0] sum;
wire [3:0] carry;

// Full adder for the least significant bit
full_adder FA0(A[0], B[0], C_in, sum[0], carry[0]);

// Carry propagation for the remaining bits
genvar i;
generate
    for(i = 1; i < 4; i = i + 1) begin : carry_gen
        full_adder FA(A[i], B[i], carry[i-1], sum[i], carry[i]);
    end
endgenerate

assign S = sum;
assign C_out = carry[3];

endmodule

module full_adder(
    input A,
    input B,
    input C_in,
    output S,
    output C_out
);

wire sum1;
wire C1;
wire C2;

// First XOR gate
xor(sum1, A, B);

// Second XOR gate
xor(S, sum1, C_in);

// First AND gate
and(C1, A, B);

// Second AND gate
and(C2, sum1, C_in);

// OR gate
or(C_out, C1, C2);

endmodule

sva:
module four_bit_adder_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic       C_in,
    input logic [3:0] S,
    input logic       C_out
);

    // Combinational DUT; assertions are sampled on the formal global clock.
    function automatic logic fa_carry (
        input logic a,
        input logic b,
        input logic cin
    );
        fa_carry = (a & b) | ((a ^ b) & cin);
    endfunction

    // 5-bit result matches A + B + C_in.
    check_total_sum: assert property (
        @($global_clock) {C_out, S} == ({1'b0, A} + {1'b0, B} + C_in)
    );

    // Bit 0 sum is the XOR of A[0], B[0], and C_in.
    check_sum_bit0: assert property (
        @($global_clock) S[0] == (A[0] ^ B[0] ^ C_in)
    );

    // Bit 1 sum uses the carry generated by bit 0.
    check_sum_bit1: assert property (
        @($global_clock) S[1] == (A[1] ^ B[1] ^ fa_carry(A[0], B[0], C_in))
    );

    // Bit 2 sum uses the carry generated by bit 1.
    check_sum_bit2: assert property (
        @($global_clock) S[2] == (A[2] ^ B[2] ^ fa_carry(A[1], B[1], fa_carry(A[0], B[0], C_in)))
    );

    // Bit 3 sum uses the carry generated by bit 2.
    check_sum_bit3: assert property (
        @($global_clock) S[3] == (A[3] ^ B[3] ^ fa_carry(A[2], B[2], fa_carry(A[1], B[1], fa_carry(A[0], B[0], C_in))))
    );

    // Carry-out matches the final ripple-carry stage.
    check_carry_out: assert property (
        @($global_clock) C_out == fa_carry(A[3], B[3], fa_carry(A[2], B[2], fa_carry(A[1], B[1], fa_carry(A[0], B[0], C_in))))
    );

endmodule

rtl:
module reg_shifter(
	input [31:0] rt_out,
	input [1:0] mem_addr_in,
	input MemWrite,
	input [5:0] IR_out,
	output reg [31:0] rt_out_shift,
	output reg [3:0] mem_byte_write_out
);

	reg [3:0] mem_byte_write;

	always @ (*)
	begin
		case (IR_out)
			6'b101011: begin 
						rt_out_shift = rt_out;
						mem_byte_write = 4'b1111;
					  end
			default: begin
						case (mem_addr_in)
							2'b00: begin 
									rt_out_shift = {rt_out[7:0],  24'b0};
									mem_byte_write = 4'b1000;
								   end
							2'b01: begin 
									rt_out_shift = {rt_out[15:0], 16'b0};
									mem_byte_write = 4'b1100;
								   end
							2'b10: begin 
									rt_out_shift = {rt_out[23:0], 8'b0};
									mem_byte_write = 4'b1110;
								   end
							2'b11: begin 
									rt_out_shift = rt_out;
									mem_byte_write = 4'b1111;
								   end
						endcase
					  end
		endcase
		mem_byte_write_out = mem_byte_write & {4{MemWrite}};
	end

endmodule

sva:
module reg_shifter_sva(
    input logic        clk,
    input logic [31:0] rt_out,
    input logic [1:0]  mem_addr_in,
    input logic        MemWrite,
    input logic [5:0]  IR_out,
    input logic [31:0] rt_out_shift,
    input logic [3:0]  mem_byte_write_out
);

    // MemWrite low suppresses all byte write enables.
    check_memwrite_masks_all_bytes: assert property (
        @(posedge clk) !MemWrite |-> (mem_byte_write_out == 4'b0000)
    );

    // Store-word opcode passes rt_out through unchanged.
    check_sw_shift_passthrough: assert property (
        @(posedge clk) (IR_out == 6'b101011) |-> (rt_out_shift == rt_out)
    );

    // Store-word opcode enables all byte lanes when writing.
    check_sw_full_byte_enable: assert property (
        @(posedge clk) (IR_out == 6'b101011 && MemWrite) |-> (mem_byte_write_out == 4'b1111)
    );

    // Non-store-word at address 00 moves the low byte into the top byte lane.
    check_addr00_shift: assert property (
        @(posedge clk) (IR_out != 6'b101011 && mem_addr_in == 2'b00) |-> (rt_out_shift == {rt_out[7:0], 24'b0})
    );

    // Non-store-word at address 00 enables only the top byte lane when writing.
    check_addr00_byte_enable: assert property (
        @(posedge clk) (IR_out != 6'b101011 && mem_addr_in == 2'b00 && MemWrite) |-> (mem_byte_write_out == 4'b1000)
    );

    // Non-store-word at address 01 moves the low halfword into the top halfword lanes.
    check_addr01_shift: assert property (
        @(posedge clk) (IR_out != 6'b101011 && mem_addr_in == 2'b01) |-> (rt_out_shift == {rt_out[15:0], 16'b0})
    );

    // Non-store-word at address 01 enables the upper two byte lanes when writing.
    check_addr01_byte_enable: assert property (
        @(posedge clk) (IR_out != 6'b101011 && mem_addr_in == 2'b01 && MemWrite) |-> (mem_byte_write_out == 4'b1100)
    );

    // Non-store-word at address 10 moves the low 24 bits into the upper three byte lanes.
    check_addr10_shift: assert property (
        @(posedge clk) (IR_out != 6'b101011 && mem_addr_in == 2'b10) |-> (rt_out_shift == {rt_out[23:0], 8'b0})
    );

    // Non-store-word at address 10 enables the upper three byte lanes when writing.
    check_addr10_byte_enable: assert property (
        @(posedge clk) (IR_out != 6'b101011 && mem_addr_in == 2'b10 && MemWrite) |-> (mem_byte_write_out == 4'b1110)
    );

    // Non-store-word at address 11 passes rt_out through unchanged.
    check_addr11_shift_passthrough: assert property (
        @(posedge clk) (IR_out != 6'b101011 && mem_addr_in == 2'b11) |-> (rt_out_shift == rt_out)
    );

    // Non-store-word at address 11 enables all byte lanes when writing.
    check_addr11_full_byte_enable: assert property (
        @(posedge clk) (IR_out != 6'b101011 && mem_addr_in == 2'b11 && MemWrite) |-> (mem_byte_write_out == 4'b1111)
    );

endmodule

module binary_counter_sva (
    input logic [3:0] count,
    input logic clk,
    input logic rst
);

    // Synchronous reset clears the counter.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |=> (count == 4'b0000)
    );

    // The first cycle after reset release still reflects the reset value.
    check_post_reset_count_zero: assert property (
        @(posedge clk) disable iff (rst) $past(rst) |-> (count == 4'b0000)
    );

    // On consecutive non-reset cycles, the counter increments by one.
    check_increment_every_cycle: assert property (
        @(posedge clk) disable iff (rst) !$past(rst) |-> (count == ($past(count) + 4'b0001))
    );

    // A maximum count value wraps back to zero on the next cycle.
    check_wrap_from_f_to_zero: assert property (
        @(posedge clk) disable iff (rst) (!$past(rst) && ($past(count) == 4'b1111)) |-> (count == 4'b0000)
    );

endmodule

