module rsdec_syn (y0, y1, y2, y3, y4, y5, y6, y7, u, enable, shift, init, clk, clrn);
	input [8:0] u;
	input clk, clrn, shift, init, enable;
	output [8:0] y0;
	output [8:0] y1;
	output [8:0] y2;
	output [8:0] y3;
	output [8:0] y4;
	output [8:0] y5;
	output [8:0] y6;
	output [8:0] y7;
	reg [8:0] y0;
	reg [8:0] y1;
	reg [8:0] y2;
	reg [8:0] y3;
	reg [8:0] y4;
	reg [8:0] y5;
	reg [8:0] y6;
	reg [8:0] y7;

	wire [8:0] scale0;
	wire [8:0] scale1;
	wire [8:0] scale2;
	wire [8:0] scale3;
	wire [8:0] scale4;
	wire [8:0] scale5;
	wire [8:0] scale6;
	wire [8:0] scale7;

	rsdec_syn_m0 m0 (scale0, y0);
	rsdec_syn_m1 m1 (scale1, y1);
	rsdec_syn_m2 m2 (scale2, y2);
	rsdec_syn_m3 m3 (scale3, y3);
	rsdec_syn_m4 m4 (scale4, y4);
	rsdec_syn_m5 m5 (scale5, y5);
	rsdec_syn_m6 m6 (scale6, y6);
	rsdec_syn_m7 m7 (scale7, y7);

	always @ (posedge clk)// or negedge clrn)
	begin
		if (~clrn)
		begin
			y0 <= 0;
			y1 <= 0;
			y2 <= 0;
			y3 <= 0;
			y4 <= 0;
			y5 <= 0;
			y6 <= 0;
			y7 <= 0;
		end
		else if (init)
		begin
			y0 <= u;
			y1 <= u;
			y2 <= u;
			y3 <= u;
			y4 <= u;
			y5 <= u;
			y6 <= u;
			y7 <= u;
		end
		else if (enable)
		begin
			y0 <= scale0 ^ u;
			y1 <= scale1 ^ u;
			y2 <= scale2 ^ u;
			y3 <= scale3 ^ u;
			y4 <= scale4 ^ u;
			y5 <= scale5 ^ u;
			y6 <= scale6 ^ u;
			y7 <= scale7 ^ u;
		end
		else if (shift)
		begin
			y0 <= y1;
			y1 <= y2;
			y2 <= y3;
			y3 <= y4;
			y4 <= y5;
			y5 <= y6;
			y6 <= y7;
			y7 <= y0;
		end
	end

endmodule

module gated_D_flipflop(clk, clr, en, d, q, qn);
input clk, clr, en, d;
output q, qn;
reg q, qn;

always @(posedge clk) begin
  if (clr == 1'b0) begin
    q <= 1'b0;
    qn <= 1'b1;
  end
  else if (en == 1'b1) begin
    q <= d;
    qn <= ~d;
  end
end

endmodule

sva:
module gated_D_flipflop_sva (
    input logic clk,
    input logic clr,
    input logic en,
    input logic d,
    input logic q,
    input logic qn
);

    // Active-low clear forces q low and qn high.
    check_sync_clear_values: assert property (
        @(posedge clk) (!clr) |=> (q == 1'b0 && qn == 1'b1)
    );

    // Clear overrides enable when both are asserted.
    check_clear_priority_over_enable: assert property (
        @(posedge clk) ((!clr) && en) |=> (q == 1'b0 && qn == 1'b1)
    );

    // When enabled, q captures d.
    check_enable_captures_d_to_q: assert property (
        @(posedge clk) disable iff (!clr) en |=> (q == $past(d))
    );

    // When enabled, qn captures the inverse of d.
    check_enable_captures_inv_d_to_qn: assert property (
        @(posedge clk) disable iff (!clr) en |=> (qn == ~$past(d))
    );

    // When enabled, q and qn remain complementary.
    check_enable_outputs_complementary: assert property (
        @(posedge clk) disable iff (!clr) en |=> (qn == ~q)
    );

    // When disabled, q holds its value.
    check_hold_q_when_disabled: assert property (
        @(posedge clk) disable iff (!clr) (!en) |=> (q == $past(q))
    );

    // When disabled, qn holds its value.
    check_hold_qn_when_disabled: assert property (
        @(posedge clk) disable iff (!clr) (!en) |=> (qn == $past(qn))
    );

endmodule

