module decoder_8to64 (
    input [7:0] ABCDEFGH,
    output reg [63:0] Y
);

reg [5:0] stage;
reg [63:0] Y_reg;

always @(*) begin
    case(stage)
        6'b000001: Y_reg = 64'b00000001;
        6'b000010: Y_reg = 64'b00000010;
        6'b000100: Y_reg = 64'b00000100;
        6'b001000: Y_reg = 64'b00001000;
        6'b010000: Y_reg = 64'b00010000;
        6'b100000: Y_reg = 64'b00100000;
        6'b000000: Y_reg = 64'b01000000;
        default: Y_reg = 64'b00000000;
    endcase
end

always @(posedge ABCDEFGH[7]) begin  // Only respond to MSB of ABCDEFGH
    if (stage == 6'b000000) begin
        stage <= 6'b000001;
        Y <= Y_reg;
    end
    else begin
        stage <= {stage[4:0], 1'b0};
        Y <= Y_reg;
    end
end

endmodule

sva:
module decoder_8to64_sva (
    input logic [7:0] ABCDEFGH,
    input logic [63:0] Y,
    input logic [5:0] stage
);

    // A zero stage advances to the first active stage.
    check_stage_zero_advances: assert property (
        @(posedge ABCDEFGH[7]) (stage == 6'b000000) |=> (stage == 6'b000001)
    );

    // Any nonzero stage shifts left by one bit.
    check_stage_nonzero_shifts_left: assert property (
        @(posedge ABCDEFGH[7]) (stage != 6'b000000) |=> (stage == {$past(stage[4:0]), 1'b0})
    );

    // Stage 0 drives 64'h40 onto Y on the following clock.
    check_output_for_stage_zero: assert property (
        @(posedge ABCDEFGH[7]) (stage == 6'b000000) |=> (Y == 64'h0000000000000040)
    );

    // Stage 1 drives 64'h01 onto Y on the following clock.
    check_output_for_stage_one: assert property (
        @(posedge ABCDEFGH[7]) (stage == 6'b000001) |=> (Y == 64'h0000000000000001)
    );

    // Stage 2 drives 64'h02 onto Y on the following clock.
    check_output_for_stage_two: assert property (
        @(posedge ABCDEFGH[7]) (stage == 6'b000010) |=> (Y == 64'h0000000000000002)
    );

    // Stage 4 drives 64'h04 onto Y on the following clock.
    check_output_for_stage_four: assert property (
        @(posedge ABCDEFGH[7]) (stage == 6'b000100) |=> (Y == 64'h0000000000000004)
    );

    // Stage 8 drives 64'h08 onto Y on the following clock.
    check_output_for_stage_eight: assert property (
        @(posedge ABCDEFGH[7]) (stage == 6'b001000) |=> (Y == 64'h0000000000000008)
    );

    // Stage 16 drives 64'h10 onto Y on the following clock.
    check_output_for_stage_sixteen: assert property (
        @(posedge ABCDEFGH[7]) (stage == 6'b010000) |=> (Y == 64'h0000000000000010)
    );

    // Stage 32 drives 64'h20 onto Y on the following clock.
    check_output_for_stage_thirty_two: assert property (
        @(posedge ABCDEFGH[7]) (stage == 6'b100000) |=> (Y == 64'h0000000000000020)
    );

    // Any unmapped stage drives zero onto Y on the following clock.
    check_output_zero_for_invalid_stage: assert property (
        @(posedge ABCDEFGH[7])
        (stage != 6'b000000 &&
         stage != 6'b000001 &&
         stage != 6'b000010 &&
         stage != 6'b000100 &&
         stage != 6'b001000 &&
         stage != 6'b010000 &&
         stage != 6'b100000)
        |=> (Y == 64'h0000000000000000)
    );

endmodule

bind decoder_8to64 decoder_8to64_sva u_decoder_8to64_sva (
    .ABCDEFGH(ABCDEFGH),
    .Y(Y),
    .stage(stage)
);

rtl:
module full_adder(A, B, Cin, S, Cout);
    input A, B, Cin;
    output S, Cout;

    assign S = A ^ B ^ Cin;
    assign Cout = (A & B) | (Cin & (A ^ B));
endmodule

module ripple_carry_adder(A, B, Cin, S, Cout);
    input [3:0] A, B;
    input Cin;
    output [3:0] S;
    output Cout;

    wire [3:0] C;

    full_adder FA0(A[0], B[0], Cin, S[0], C[0]);
    full_adder FA1(A[1], B[1], C[0], S[1], C[1]);
    full_adder FA2(A[2], B[2], C[1], S[2], C[2]);
    full_adder FA3(A[3], B[3], C[2], S[3], Cout);
endmodule

module four_bit_adder(A, B, Cin, C, Cout);
    input [3:0] A, B;
    input Cin;
    output [3:0] C;
    output Cout;

    ripple_carry_adder RCA(A, B, Cin, C, Cout);
endmodule

sva:
module four_bit_adder_sva (
    input logic       clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic       Cin,
    input logic [3:0] C,
    input logic       Cout
);

    // Output bus and carry must equal A + B + Cin.
    check_total_sum: assert property (
        @(posedge clk) {Cout, C} == ({1'b0, A} + {1'b0, B} + {4'b0000, Cin})
    );

    // Sum bit 0 must implement the first full-adder sum.
    check_sum_bit0: assert property (
        @(posedge clk) C[0] == (A[0] ^ B[0] ^ Cin)
    );

    // Sum bit 1 must use the carry from bit 0.
    check_sum_bit1: assert property (
        @(posedge clk) C[1] == (A[1] ^ B[1] ^ ((A[0] & B[0]) | (Cin & (A[0] ^ B[0]))))
    );

    // Sum bit 2 must use the ripple carry from bits 0 and 1.
    check_sum_bit2: assert property (
        @(posedge clk)
        C[2] == (A[2] ^ B[2] ^
                 ((A[1] & B[1]) |
                  (((A[0] & B[0]) | (Cin & (A[0] ^ B[0]))) & (A[1] ^ B[1]))))
    );

    // Sum bit 3 must use the ripple carry from bits 0 through 2.
    check_sum_bit3: assert property (
        @(posedge clk)
        C[3] == (A[3] ^ B[3] ^
                 ((A[2] & B[2]) |
                  ((((A[1] & B[1]) |
                     (((A[0] & B[0]) | (Cin & (A[0] ^ B[0]))) & (A[1] ^ B[1])))) &
                   (A[2] ^ B[2])))))
    );

    // Cout must be the final carry of the 4-bit ripple chain.
    check_final_carry: assert property (
        @(posedge clk)
        Cout == ((A[3] & B[3]) |
                 ((((A[2] & B[2]) |
                    ((((A[1] & B[1]) |
                       (((A[0] & B[0]) | (Cin & (A[0] ^ B[0]))) & (A[1] ^ B[1])))) &
                     (A[2] ^ B[2])))) &
                  (A[3] ^ B[3]))))
    );

endmodule

rtl:
module d_flip_flop (
    input D,
    input CLK,
    input RESET,
    output Q
);

    reg Q_reg;

    always @(posedge CLK) begin
        if (RESET) begin
            Q_reg <= 1'b0;
        end else begin
            Q_reg <= D;
        end
    end

    assign Q = Q_reg;

endmodule

sva:
module d_flip_flop_sva (
    input logic D,
    input logic CLK,
    input logic RESET,
    input logic Q
);

    // Q matches the previous clock's reset-or-data update.
    check_state_update: assert property (
        @(posedge CLK)
        !$initstate |-> (Q == ($past(RESET) ? 1'b0 : $past(D)))
    );

    // On consecutive non-reset clocks, Q captures the previous D.
    check_capture_d_after_nonreset: assert property (
        @(posedge CLK) disable iff (RESET)
        !$initstate && !$past(RESET) |-> (Q == $past(D))
    );

    // A reset clock forces Q low by the next sampled cycle.
    check_reset_clears_q: assert property (
        @(posedge CLK)
        RESET |=> (Q == 1'b0)
    );

    // After reset is released, Q is still low on that sampled cycle.
    check_q_low_after_reset_release: assert property (
        @(posedge CLK) disable iff (RESET)
        !$initstate && $past(RESET) |-> (Q == 1'b0)
    );

endmodule

rtl:
module byte_order_reverse (
    input [31:0] in,
    output [31:0] out
);
    assign out = {in[7:0], in[15:8], in[23:16], in[31:24]};
endmodule

module mux_6to1 (
    input [2:0] sel,
    input [3:0] data0,
    input [3:0] data1,
    input [3:0] data2,
    input [3:0] data3,
    input [3:0] data4,
    input [3:0] data5,
    output [3:0] out
);
    reg [3:0] mux_out;
    always @*
        case (sel)
            3'b000: mux_out = data0;
            3'b001: mux_out = data1;
            3'b010: mux_out = data2;
            3'b011: mux_out = data3;
            3'b100: mux_out = data4;
            3'b101: mux_out = data5;
            default: mux_out = 4'b0000;
        endcase
    assign out = mux_out;
endmodule

module sum_module (
    input [31:0] byte_order_rev_out,
    input [3:0] mux_out,
    output [31:0] sum_out
);
    assign sum_out = byte_order_rev_out + {28'b0, mux_out};
endmodule

module top_module (
    input [31:0] in,
    input [2:0] sel,
    input [3:0] data0,
    input [3:0] data1,
    input [3:0] data2,
    input [3:0] data3,
    input [3:0] data4,
    input [3:0] data5,
    output [3:0] out
);
    wire [31:0] byte_order_rev_out;
    wire [3:0] mux_out;
    wire [31:0] sum_out;

    byte_order_reverse byte_order_rev(in, byte_order_rev_out);
    mux_6to1 mux(sel, data0, data1, data2, data3, data4, data5, mux_out);
    sum_module sum(byte_order_rev_out, mux_out, sum_out);

    assign out = sum_out[3:0];
endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic [31:0] in,
    input logic [2:0] sel,
    input logic [3:0] data0,
    input logic [3:0] data1,
    input logic [3:0] data2,
    input logic [3:0] data3,
    input logic [3:0] data4,
    input logic [3:0] data5,
    input logic [3:0] out,
    input logic [31:0] byte_order_rev_out,
    input logic [3:0] mux_out,
    input logic [31:0] sum_out
);

    // Combinational DUT sampled on clk; no reset in the RTL.

    // Byte reversal swaps the four input bytes.
    check_byte_order_reverse: assert property (
        @(posedge clk) byte_order_rev_out === {in[7:0], in[15:8], in[23:16], in[31:24]}
    );

    // sel 000 selects data0.
    check_mux_select_data0: assert property (
        @(posedge clk) (sel === 3'b000) |-> (mux_out === data0)
    );

    // sel 001 selects data1.
    check_mux_select_data1: assert property (
        @(posedge clk) (sel === 3'b001) |-> (mux_out === data1)
    );

    // sel 010 selects data2.
    check_mux_select_data2: assert property (
        @(posedge clk) (sel === 3'b010) |-> (mux_out === data2)
    );

    // sel 011 selects data3.
    check_mux_select_data3: assert property (
        @(posedge clk) (sel === 3'b011) |-> (mux_out === data3)
    );

    // sel 100 selects data4.
    check_mux_select_data4: assert property (
        @(posedge clk) (sel === 3'b100) |-> (mux_out === data4)
    );

    // sel 101 selects data5.
    check_mux_select_data5: assert property (
        @(posedge clk) (sel === 3'b101) |-> (mux_out === data5)
    );

    // Unused select values drive zero.
    check_mux_invalid_select_defaults_zero: assert property (
        @(posedge clk)
        ((sel !== 3'b000) && (sel !== 3'b001) && (sel !== 3'b010) &&
         (sel !== 3'b011) && (sel !== 3'b100) && (sel !== 3'b101))
        |-> (mux_out === 4'b0000)
    );

    // The sum adds the reversed word to the zero-extended mux output.
    check_sum_module_addition: assert property (
        @(posedge clk) sum_out === (byte_order_rev_out + {28'b0, mux_out})
    );

    // The top output is the low nibble of the sum.
    check_top_output_low_nibble: assert property (
        @(posedge clk) out === sum_out[3:0]
    );

endmodule

