    assign and2 = A3 & A4;
    assign or1 = B1 | and1;
    assign and3 = not2 & or1;
    assign not1 = ~A3;
    assign not2 = ~not1;

    o41ai_2 base (
        .Y(Y),
        .A1(and1),
        .A2(and2),
        .A3(not1),
        .A4(A4),
        .B1(and3)
