module sky130_fd_sc_hd__clkdlybuf4s15_sva #(
    parameter DELAY_SIZE  = 15,
    parameter BUFFER_WIDTH = 1,
    parameter BUFFER_SIZE = DELAY_SIZE * BUFFER_WIDTH
