module keypressed(clock, reset, enable_in, enable_out);

	input clock;				input	reset;				input enable_in;			output reg enable_out;	reg [1:0] key_state, next_key_state;

parameter [1:0] KEY_FREE = 2'b00, KEY_PRESSED = 2'b01, KEY_RELEASED = 2'b10;

always @(posedge clock or negedge reset) begin

	if (reset == 1'b0)
			key_state <= KEY_FREE;

	else
			key_state <= next_key_state;

	end

always @(key_state, enable_in) begin

	next_key_state = key_state;

	case (key_state)

		KEY_FREE: begin

			if (enable_in == 1'b0)
					next_key_state = KEY_PRESSED;
			end

		KEY_PRESSED: begin

			if (enable_in == 1'b1)
					next_key_state = KEY_RELEASED;
			end

		KEY_RELEASED: begin

			next_key_state = KEY_FREE;
			end

		default: begin
				next_key_state = 2'bxx;
			end

		endcase

	end

always @(key_state) begin

	enable_out = 1'b0;

	case (key_state)

		KEY_FREE: begin
				enable_out = 1'b0;
			end

		KEY_PRESSED: begin
				enable_out = 1'b0;
			end

		KEY_RELEASED: begin
				enable_out = 1'b1;
			end

		default: begin
				enable_out = 1'bx;
			end

		endcase

	end

endmodule

sva:
module keypressed_sva (
    input logic       clock,
    input logic       reset,
    input logic       enable_in,
    input logic       enable_out,
    input logic [1:0] key_state,
    input logic [1:0] next_key_state
);

    localparam [1:0] KEY_FREE     = 2'b00;
    localparam [1:0] KEY_PRESSED  = 2'b01;
    localparam [1:0] KEY_RELEASED = 2'b10;

    // Reset drives the state to KEY_FREE.
    check_reset_state: assert property (
        @(posedge clock) !reset |-> (key_state == KEY_FREE)
    );

    // Reset keeps the output low.
    check_reset_output: assert property (
        @(posedge clock) !reset |-> (enable_out == 1'b0)
    );

    // KEY_FREE with a low input decodes to KEY_PRESSED.
    check_next_free_to_pressed: assert property (
        @(posedge clock) disable iff (!reset)
        (key_state == KEY_FREE && enable_in == 1'b0) |-> (next_key_state == KEY_PRESSED)
    );

    // KEY_FREE with a high input stays in KEY_FREE.
    check_next_free_stays_free: assert property (
        @(posedge clock) disable iff (!reset)
        (key_state == KEY_FREE && enable_in == 1'b1) |-> (next_key_state == KEY_FREE)
    );

    // KEY_PRESSED with a low input stays in KEY_PRESSED.
    check_next_pressed_stays_pressed: assert property (
        @(posedge clock) disable iff (!reset)
        (key_state == KEY_PRESSED && enable_in == 1'b0) |-> (next_key_state == KEY_PRESSED)
    );

    // KEY_PRESSED with a high input decodes to KEY_RELEASED.
    check_next_pressed_to_released: assert property (
        @(posedge clock) disable iff (!reset)
        (key_state == KEY_PRESSED && enable_in == 1'b1) |-> (next_key_state == KEY_RELEASED)
    );

    // KEY_RELEASED always decodes back to KEY_FREE.
    check_next_released_to_free: assert property (
        @(posedge clock) disable iff (!reset)
        (key_state == KEY_RELEASED) |-> (next_key_state == KEY_FREE)
    );

    // KEY_FREE advances to KEY_PRESSED when the input is low.
    check_state_free_to_pressed: assert property (
        @(posedge clock) disable iff (!reset)
        (key_state == KEY_FREE && enable_in == 1'b0) |=> (key_state == KEY_PRESSED)
    );

    // KEY_FREE stays in KEY_FREE when the input is high.
    check_state_free_stays_free: assert property (
        @(posedge clock) disable iff (!reset)
        (key_state == KEY_FREE && enable_in == 1'b1) |=> (key_state == KEY_FREE)
    );

    // KEY_PRESSED stays in KEY_PRESSED while the input remains low.
    check_state_pressed_stays_pressed: assert property (
        @(posedge clock) disable iff (!reset)
        (key_state == KEY_PRESSED && enable_in == 1'b0) |=> (key_state == KEY_PRESSED)
    );

    // KEY_PRESSED advances to KEY_RELEASED when the input goes high.
    check_state_pressed_to_released: assert property (
        @(posedge clock) disable iff (!reset)
        (key_state == KEY_PRESSED && enable_in == 1'b1) |=> (key_state == KEY_RELEASED)
    );

    // KEY_RELEASED always returns to KEY_FREE on the next cycle.
    check_state_released_to_free: assert property (
        @(posedge clock) disable iff (!reset)
        (key_state == KEY_RELEASED) |=> (key_state == KEY_FREE)
    );

    // The output is low in KEY_FREE.
    check_output_low_in_free: assert property (
        @(posedge clock) disable iff (!reset)
        (key_state == KEY_FREE) |-> (enable_out == 1'b0)
    );

    // The output is low in KEY_PRESSED.
    check_output_low_in_pressed: assert property (
        @(posedge clock) disable iff (!reset)
        (key_state == KEY_PRESSED) |-> (enable_out == 1'b0)
    );

    // The output is high in KEY_RELEASED.
    check_output_high_in_released: assert property (
        @(posedge clock) disable iff (!reset)
        (key_state == KEY_RELEASED) |-> (enable_out == 1'b1)
    );

endmodule

module barrel_shifter_assertions (
    input logic        clk,
    input logic [15:0] data,
    input logic [3:0]  shift_amount,
    input logic        direction,
    input logic [15:0] q
);

    function automatic [15:0] rot_left16(input [15:0] d, input [3:0] s);
        begin
            case (s)
                4'b0000: rot_left16 = d;
                4'b0001: rot_left16 = {d[14:0], d[15]};
                4'b0010: rot_left16 = {d[13:0], d[15:14]};
                4'b0011: rot_left16 = {d[12:0], d[15:13]};
                4'b0100: rot_left16 = {d[11:0], d[15:12]};
                4'b0101: rot_left16 = {d[10:0], d[15:11]};
                4'b0110: rot_left16 = {d[9:0], d[15:10]};
                4'b0111: rot_left16 = {d[8:0], d[15:9]};
                4'b1000: rot_left16 = {d[7:0], d[15:8]};
                4'b1001: rot_left16 = {d[6:0], d[15:7]};
                4'b1010: rot_left16 = {d[5:0], d[15:6]};
                4'b1011: rot_left16 = {d[4:0], d[15:5]};
                4'b1100: rot_left16 = {d[3:0], d[15:4]};
                4'b1101: rot_left16 = {d[2:0], d[15:3]};
                4'b1110: rot_left16 = {d[1:0], d[15:2]};
                4'b1111: rot_left16 = {d[0], d[15:1]};
                default: rot_left16 = d;
            endcase
        end
    endfunction

    function automatic [15:0] rot_right16(input [15:0] d, input [3:0] s);
        begin
            case (s)
                4'b0000: rot_right16 = d;
                4'b0001: rot_right16 = {d[0], d[15:1]};
                4'b0010: rot_right16 = {d[1:0], d[15:2]};
                4'b0011: rot_right16 = {d[2:0], d[15:3]};
                4'b0100: rot_right16 = {d[3:0], d[15:4]};
                4'b0101: rot_right16 = {d[4:0], d[15:5]};
                4'b0110: rot_right16 = {d[5:0], d[15:6]};
                4'b0111: rot_right16 = {d[6:0], d[15:7]};
                4'b1000: rot_right16 = {d[7:0], d[15:8]};
                4'b1001: rot_right16 = {d[8:0], d[15:9]};
                4'b1010: rot_right16 = {d[9:0], d[15:10]};
                4'b1011: rot_right16 = {d[10:0], d[15:11]};
                4'b1100: rot_right16 = {d[11:0], d[15:12]};
                4'b1101: rot_right16 = {d[12:0], d[15:13]};
                4'b1110: rot_right16 = {d[13:0], d[15:14]};
                4'b1111: rot_right16 = {d[14:0], d[15]};
                default: rot_right16 = d;
            endcase
        end
    endfunction

    // Left direction must match the implemented rotation table.
    check_left_rotation_table: assert property (
        @(posedge clk) (direction == 1'b1) |-> (q == rot_left16(data, shift_amount))
    );

    // Right direction must match the implemented rotation table.
    check_right_rotation_table: assert property (
        @(posedge clk) (direction == 1'b0) |-> (q == rot_right16(data, shift_amount))
    );

    // Left rotation by zero returns the input unchanged.
    check_left_shift_zero_identity: assert property (
        @(posedge clk) (direction == 1'b1) && (shift_amount == 4'b0000) |-> (q == data)
    );

    // Right rotation by zero returns the input unchanged.
    check_right_shift_zero_identity: assert property (
        @(posedge clk) (direction == 1'b0) && (shift_amount == 4'b0000) |-> (q == data)
    );

    // Left rotation by one wraps the MSB into bit 0.
    check_left_shift_one_wraps_msb: assert property (
        @(posedge clk) (direction == 1'b1) && (shift_amount == 4'b0001) |-> (q == {data[14:0], data[15]})
    );

    // Right rotation by one wraps the LSB into bit 15.
    check_right_shift_one_wraps_lsb: assert property (
        @(posedge clk) (direction == 1'b0) && (shift_amount == 4'b0001) |-> (q == {data[0], data[15:1]})
    );

    // Left rotation by eight swaps the upper and lower bytes.
    check_left_shift_eight_swaps_bytes: assert property (
        @(posedge clk) (direction == 1'b1) && (shift_amount == 4'b1000) |-> (q == {data[7:0], data[15:8]})
    );

    // Right rotation by eight swaps the upper and lower bytes.
    check_right_shift_eight_swaps_bytes: assert property (
        @(posedge clk) (direction == 1'b0) && (shift_amount == 4'b1000) |-> (q == {data[7:0], data[15:8]})
    );

    // Left rotation by fifteen matches the RTL wrap-around mapping.
    check_left_shift_fifteen_wraps: assert property (
        @(posedge clk) (direction == 1'b1) && (shift_amount == 4'b1111) |-> (q == {data[0], data[15:1]})
    );

    // Right rotation by fifteen matches the RTL wrap-around mapping.
    check_right_shift_fifteen_wraps: assert property (
        @(posedge clk) (direction == 1'b0) && (shift_amount == 4'b1111) |-> (q == {data[14:0], data[15]})
    );

    // Stable inputs must produce a stable output across sampled cycles.
    check_output_stable_when_inputs_stable: assert property (
        @(posedge clk) $stable({data, shift_amount, direction}) |-> $stable(q)
    );

endmodule

