        @(posedge clk) o2 == vec[2]
    );

    // For vec=000, outv passes through unchanged.
    check_outv_when_vec_000: assert property (
        @(posedge clk) (vec == 3'b000) |-> (outv == vec)
    );

    // For vec=001, outv follows the specified permutation.
    check_outv_when_vec_001: assert property (
        @(posedge clk) (vec == 3'b001) |-> (outv == {vec[0], vec[2], vec[1]})
    );

    // For vec=010, outv follows the specified permutation.
    check_outv_when_vec_010: assert property (
        @(posedge clk) (vec == 3'b010) |-> (outv == {vec[1], vec[0], vec[2]})
    );

    // For vec=011, outv follows the specified permutation.
    check_outv_when_vec_011: assert property (
        @(posedge clk) (vec == 3'b011) |-> (outv == {vec[1], vec[2], vec[0]})
    );

    // For vec=100, outv follows the specified permutation.
    check_outv_when_vec_100: assert property (
        @(posedge clk) (vec == 3'b100) |-> (outv == {vec[2], vec[0], vec[1]})
    );

    // For vec=101, outv follows the specified permutation.
    check_outv_when_vec_101: assert property (
        @(posedge clk) (vec == 3'b101) |-> (outv == {vec[2], vec[1], vec[0]})
    );

    // For vec=110, the default case passes vec through unchanged.
    check_outv_when_vec_110: assert property (
        @(posedge clk) (vec == 3'b110) |-> (outv == vec)
    );

    // For vec=111, the default case passes vec through unchanged.
    check_outv_when_vec_111: assert property (
        @(posedge clk) (vec == 3'b111) |-> (outv == vec)
    );

endmodule

rtl:
module debounce_switch #(
    parameter WIDTH = 1, // width of the input and output signals
    parameter N = 3, // length of shift register
    parameter RATE = 125000 // clock division factor
)(
    input wire clk,
    input wire rst,
    input wire [WIDTH-1:0] in,
    output wire [WIDTH-1:0] out
);

    reg [23:0] cnt_reg = 24'd0;
    reg [N-1:0] debounce_reg[WIDTH-1:0];
    reg [WIDTH-1:0] state;


    assign out = state;

    integer k;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            cnt_reg <= 0;
            state <= 0;

            for (k = 0; k < WIDTH; k = k + 1) begin
                debounce_reg[k] <= 0;
            end
        end else begin
            if (cnt_reg < RATE) begin
                cnt_reg <= cnt_reg + 24'd1;
            end else begin
                cnt_reg <= 24'd0;
            end

            if (cnt_reg == 24'd0) begin
                for (k = 0; k < WIDTH; k = k + 1) begin
                    debounce_reg[k] <= {debounce_reg[k][N-2:0], in[k]};
                end
            end

            for (k = 0; k < WIDTH; k = k + 1) begin
                if (|debounce_reg[k] == 0) begin
                    state[k] <= 0;
                end else if (&debounce_reg[k] == 1) begin
                    state[k] <= 1;
                end else begin
                    state[k] <= state[k];
                end
            end
        end
    end

endmodule

sva:
module debounce_switch_sva #(
    parameter WIDTH = 1,
    parameter N = 3,
    parameter RATE = 125000
)(
    input logic clk,
    input logic rst,
    input logic [WIDTH-1:0] in,
    input logic [WIDTH-1:0] out,
    input logic [23:0] cnt_reg,
    input logic [N-1:0] debounce_reg [WIDTH-1:0],
    input logic [WIDTH-1:0] state
);

    // Clock: clk
    // Reset: rst is active-high and asynchronous in the RTL
    // Logic: sequential counter/state with combinational out = state

    genvar i;

    // Output always mirrors the internal state register.
    check_out_matches_state: assert property (
        @(posedge clk) disable iff (rst)
        out == state
    );

    // Reset clears the counter.
    check_reset_clears_counter: assert property (
        @(posedge clk)
        rst |-> (cnt_reg == 24'd0)
    );

    // Reset clears the state register.
    check_reset_clears_state: assert property (
        @(posedge clk)
        rst |-> (state == {WIDTH{1'b0}})
    );

    // Reset drives the output low.
    check_reset_clears_output: assert property (
        @(posedge clk)
        rst |-> (out == {WIDTH{1'b0}})
    );

    // Counter increments while it is below RATE.
    check_counter_increments: assert property (
        @(posedge clk) disable iff (rst)
        (cnt_reg < RATE) |=> (cnt_reg == ($past(cnt_reg) + 24'd1))
    );

    // Counter wraps to zero when it is not below RATE.
    check_counter_wraps: assert property (
        @(posedge clk) disable iff (rst)
        !(cnt_reg < RATE) |=> (cnt_reg == 24'd0)
    );

    generate
        for (i = 0; i < WIDTH; i = i + 1) begin : gen_width_checks

            // Reset clears each debounce history register.
            check_reset_clears_debounce: assert property (
                @(posedge clk)
                rst |-> (debounce_reg[i] == {N{1'b0}})
            );

            if (N > 1) begin : gen_n_gt_1
                // On a sample tick, the debounce history shifts in the input bit.
                check_debounce_shifts_on_tick: assert property (
                    @(posedge clk) disable iff (rst)
                    (cnt_reg == 24'd0) |=> (debounce_reg[i] == {$past(debounce_reg[i][N-2:0]), $past(in[i])})
                );
            end else begin : gen_n_eq_1
                // On a sample tick, the debounce history captures the input bit.
                check_debounce_captures_on_tick: assert property (
                    @(posedge clk) disable iff (rst)
                    (cnt_reg == 24'd0) |=> (debounce_reg[i] == $past(in[i]))
                );
            end

            // Between sample ticks, the debounce history holds.
            check_debounce_holds_between_ticks: assert property (
                @(posedge clk) disable iff (rst)
                (cnt_reg != 24'd0) |=> (debounce_reg[i] == $past(debounce_reg[i]))
            );

            // All-zero history clears the corresponding state bit.
            check_state_clears_on_zero_history: assert property (
                @(posedge clk) disable iff (rst)
                (debounce_reg[i] == {N{1'b0}}) |=> (state[i] == 1'b0)
            );

            // All-one history sets the corresponding state bit.
            check_state_sets_on_one_history: assert property (
                @(posedge clk) disable iff (rst)
                (debounce_reg[i] == {N{1'b1}}) |=> (state[i] == 1'b1)
            );

            // Mixed history preserves the corresponding state bit.
            check_state_holds_on_mixed_history: assert property (
                @(posedge clk) disable iff (rst)
                ((debounce_reg[i] != {N{1'b0}}) && (debounce_reg[i] != {N{1'b1}})) |=> (state[i] == $past(state[i]))
            );

        end
    endgenerate

endmodule

rtl:
module logic_circuit(
    input [1:0] in1,
    input [1:0] in2,
    output [1:0] out
);

    assign out = ~(in1 & in2); 

endmodule

sva:
module logic_circuit_sva (
    input logic       clk,
    input logic [1:0] in1,
    input logic [1:0] in2,
    input logic [1:0] out
);

    // Sample the combinational NAND relation on clk; RTL has no reset.
    check_out_matches_nand: assert property (
        @(posedge clk) disable iff (1'b0) out == ~(in1 & in2)
    );

    // Bit 0 must implement a NAND of in1[0] and in2[0].
    check_out0_matches_nand: assert property (
        @(posedge clk) disable iff (1'b0) out[0] == ~(in1[0] & in2[0])
    );

    // Bit 1 must implement a NAND of in1[1] and in2[1].
    check_out1_matches_nand: assert property (
        @(posedge clk) disable iff (1'b0) out[1] == ~(in1[1] & in2[1])
    );

    // If either bit-0 input is 0, bit-0 output must be 1.
    check_out0_high_when_any_input_low: assert property (
        @(posedge clk) disable iff (1'b0)
        ((in1[0] == 1'b0) || (in2[0] == 1'b0)) |-> (out[0] == 1'b1)
    );

    // If both bit-0 inputs are 1, bit-0 output must be 0.
    check_out0_low_when_both_inputs_high: assert property (
        @(posedge clk) disable iff (1'b0)
        ((in1[0] == 1'b1) && (in2[0] == 1'b1)) |-> (out[0] == 1'b0)
    );

    // If either bit-1 input is 0, bit-1 output must be 1.
    check_out1_high_when_any_input_low: assert property (
        @(posedge clk) disable iff (1'b0)
        ((in1[1] == 1'b0) || (in2[1] == 1'b0)) |-> (out[1] == 1'b1)
    );

    // If both bit-1 inputs are 1, bit-1 output must be 0.
    check_out1_low_when_both_inputs_high: assert property (
        @(posedge clk) disable iff (1'b0)
        ((in1[1] == 1'b1) && (in2[1] == 1'b1)) |-> (out[1] == 1'b0)
    );

    // Stable inputs must produce a stable output.
    check_out_stable_when_inputs_stable: assert property (
        @(posedge clk) disable iff (1'b0)
        ($stable(in1) && $stable(in2)) |-> $stable(out)
    );

endmodule

rtl:
module DecoGreytoBCD(
	entradas_i,	salidas_o );

	input [2:0] entradas_i;
	output [2:0] salidas_o;

	assign salidas_o[2] = entradas_i[2];
	xor xorB(salidas_o[1], entradas_i[2], entradas_i[1]);
	xor xorC(salidas_o[0], salidas_o[1], entradas_i[0]);


endmodule

sva:
module DecoGreytoBCD_sva (
    input logic       clk,
    input logic [2:0] entradas_i,
    input logic [2:0] salidas_o
);

    // Output bit 2 is a direct copy of input bit 2.
    check_bit2_passthrough: assert property (
        @(posedge clk) salidas_o[2] == entradas_i[2]
    );

    // Output bit 1 is the XOR of input bits 2 and 1.
    check_bit1_xor_decode: assert property (
        @(posedge clk) salidas_o[1] == (entradas_i[2] ^ entradas_i[1])
    );

    // Output bit 0 is the XOR of output bit 1 and input bit 0.
    check_bit0_chained_xor: assert property (
        @(posedge clk) salidas_o[0] == (salidas_o[1] ^ entradas_i[0])
    );

    // The full output vector matches the implemented Gray-to-binary decode.
    check_full_decode_vector: assert property (
        @(posedge clk) salidas_o == {entradas_i[2], (entradas_i[2] ^ entradas_i[1]), (entradas_i[2] ^ entradas_i[1] ^ entradas_i[0])}
    );

endmodule

rtl:
module four_to_sixteen_decoder (
    input [1:0] sel,
    output reg [15:0] out
);

    always @(*) begin
        case(sel)
            2'b00: out = 16'b0000000000000001;
            2'b01: out = 16'b0000000000000010;
            2'b10: out = 16'b0000000000000100;
            2'b11: out = 16'b0000000000001000;
            default: out = 16'b0000000000000000;
        endcase
    end

endmodule

sva:
module four_to_sixteen_decoder_sva (
    input logic clk,
    input logic [1:0] sel,
    input logic [15:0] out
);

    // Combinational decoder sampled on an external clock; no reset exists in the RTL.

    // sel=00 drives bit 0 high.
    check_sel_00_decodes_bit0: assert property (
        @(posedge clk) (sel == 2'b00) |-> (out == 16'b0000000000000001)
    );

    // sel=01 drives bit 1 high.
    check_sel_01_decodes_bit1: assert property (
        @(posedge clk) (sel == 2'b01) |-> (out == 16'b0000000000000010)
    );

    // sel=10 drives bit 2 high.
    check_sel_10_decodes_bit2: assert property (
        @(posedge clk) (sel == 2'b10) |-> (out == 16'b0000000000000100)
    );

    // sel=11 drives bit 3 high.
    check_sel_11_decodes_bit3: assert property (
        @(posedge clk) (sel == 2'b11) |-> (out == 16'b0000000000001000)
    );

    // The full output matches a 1 shifted by sel.
    check_full_output_matches_decode: assert property (
        @(posedge clk) out == (16'h0001 << sel)
    );

    // Upper output bits are always zero.
    check_upper_bits_zero: assert property (
        @(posedge clk) out[15:4] == 12'b0
    );

endmodule

rtl:
module edge_detect(
  input               clk,
  input               rst_n,
  input               a,
  output reg          rise,
  output reg          fall
);

  reg a_prev;

  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      a_prev <= 1'b0;
      rise <= 1'b0;
      fall <= 1'b0;
    end
    else begin
      a_prev <= a;
      if (a == 1'b1 && a_prev == 1'b0) begin
        rise <= 1'b1;
        fall <= 1'b0;
      end
      else if (a == 1'b0 && a_prev == 1'b1) begin
        rise <= 1'b0;
        fall <= 1'b1;
      end
      else begin
        rise <= 1'b0;
        fall <= 1'b0;
      end
    end
  end

endmodule

sva:
module edge_detect_assertions (
    input logic clk,
    input logic rst_n,
    input logic a,
    input logic rise,
    input logic fall
);

    // Outputs are cleared while reset is active.
    check_reset_clears_outputs: assert property (
        @(posedge clk) (rst_n == 1'b0) |-> ((rise == 1'b0) && (fall == 1'b0))
    );

    // A sampled 0->1 transition raises rise and clears fall.
    check_rise_detect_after_active_cycle: assert property (
        @(posedge clk) disable iff (!rst_n)
        (($past(rst_n) === 1'b1) && ($past(a) === 1'b0) && (a == 1'b1)) |-> ((rise == 1'b1) && (fall == 1'b0))
    );

    // A sampled 1->0 transition raises fall and clears rise.
    check_fall_detect_after_active_cycle: assert property (
        @(posedge clk) disable iff (!rst_n)
        (($past(rst_n) === 1'b1) && ($past(a) === 1'b1) && (a == 1'b0)) |-> ((rise == 1'b0) && (fall == 1'b1))
    );

    // If a stays low, neither edge output is asserted.
    check_no_edge_when_a_stays_low: assert property (
        @(posedge clk) disable iff (!rst_n)
        (($past(rst_n) === 1'b1) && ($past(a) === 1'b0) && (a == 1'b0)) |-> ((rise == 1'b0) && (fall == 1'b0))
    );

    // If a stays high, neither edge output is asserted.
    check_no_edge_when_a_stays_high: assert property (
        @(posedge clk) disable iff (!rst_n)
        (($past(rst_n) === 1'b1) && ($past(a) === 1'b1) && (a == 1'b1)) |-> ((rise == 1'b0) && (fall == 1'b0))
    );

    // On the first clock after reset, a high input produces rise.
    check_rise_after_reset_release_with_a_high: assert property (
        @(posedge clk) disable iff (!rst_n)
        (($past(rst_n) === 1'b0) && (a == 1'b1)) |-> ((rise == 1'b1) && (fall == 1'b0))
    );

    // On the first clock after reset, a low input produces no edge outputs.
    check_no_edge_after_reset_release_with_a_low: assert property (
        @(posedge clk) disable iff (!rst_n)
        (($past(rst_n) === 1'b0) && (a == 1'b0)) |-> ((rise == 1'b0) && (fall == 1'b0))
    );

    // rise and fall are never asserted together.
    check_rise_fall_mutually_exclusive: assert property (
        @(posedge clk) disable iff (!rst_n)
        !(rise && fall)
    );

    // rise can only be high when the current input is high.
    check_rise_requires_a_high: assert property (
        @(posedge clk) disable iff (!rst_n)
        (rise == 1'b1) |-> (a == 1'b1)
    );

    // fall can only be high when the current input is low.
    check_fall_requires_a_low: assert property (
        @(posedge clk) disable iff (!rst_n)
        (fall == 1'b1) |-> (a == 1'b0)
    );

endmodule

rtl:
module barrel_shifter (
    input [3:0] A,
    input [3:0] B,
    output [3:0] result
);

reg [3:0] stage1_out;
reg [3:0] stage2_out;

wire [3:0] abs_B;

assign abs_B = (B[3] == 1'b1) ? ~B + 1'b1 : B;

always @(*) begin
    stage1_out = (B[3] == 1'b0) ? (A << B) : (A >> abs_B);
end

always @(*) begin
    stage2_out = stage1_out;
end

assign result = stage2_out;

endmodule

sva:
module barrel_shifter_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] result,
    input logic [3:0] stage1_out,
    input logic [3:0] stage2_out,
    input logic [3:0] abs_B
);

    // No RTL clock or reset; sample combinational behavior on $global_clock.

    // abs_B matches B when B selects the left-shift path.
    check_abs_b_positive_case: assert property (
        @($global_clock) (B[3] == 1'b0) |-> (abs_B == B)
    );

    // abs_B is the two's-complement magnitude when B selects the right-shift path.
    check_abs_b_negative_case: assert property (
        @($global_clock) (B[3] == 1'b1) |-> (abs_B == (~B + 1'b1))
    );

    // stage1_out performs the left shift for non-negative B.
    check_stage1_left_shift: assert property (
        @($global_clock) (B[3] == 1'b0) |-> (stage1_out == (A << B))
    );

    // stage1_out performs the right shift by abs_B for negative B.
    check_stage1_right_shift: assert property (
        @($global_clock) (B[3] == 1'b1) |-> (stage1_out == (A >> abs_B))
    );

    // stage2_out is a direct copy of stage1_out.
    check_stage2_copies_stage1: assert property (
        @($global_clock) (stage2_out == stage1_out)
    );

    // result is a direct copy of stage2_out.
    check_result_copies_stage2: assert property (
        @($global_clock) (result == stage2_out)
    );

    // result matches the left shift path for non-negative B.
    check_result_left_shift: assert property (
        @($global_clock) (B[3] == 1'b0) |-> (result == (A << B))
    );

    // result matches the right shift path for negative B.
    check_result_right_shift: assert property (
        @($global_clock) (B[3] == 1'b1) |-> (result == (A >> abs_B))
    );

endmodule

rtl:
module division (
    input [3:0] dividend,
    input [3:0] divisor,
    output reg [3:0] quotient,
    output reg [3:0] remainder
);

    always @(*) begin
        if (divisor == 0) begin
            quotient <= 4'b0;
            remainder <= 4'b0;
        end else begin
            quotient <= dividend / divisor;
            remainder <= dividend % divisor;
        end
    end

endmodule

sva:
module division_sva (
    input logic       clk,
    input logic [3:0] dividend,
    input logic [3:0] divisor,
    input logic [3:0] quotient,
    input logic [3:0] remainder
);

    // Combinational divider sampled with external clk; RTL has no reset.

    // Divide-by-zero drives zero outputs.
    check_divide_by_zero_outputs_zero: assert property (
        @(posedge clk) (divisor == 4'b0000) |-> ((quotient == 4'b0000) && (remainder == 4'b0000))
    );

    // Nonzero divisor produces the integer quotient.
    check_nonzero_divisor_quotient: assert property (
        @(posedge clk) (divisor != 4'b0000) |-> (quotient == (dividend / divisor))
    );

    // Nonzero divisor produces the integer remainder.
    check_nonzero_divisor_remainder: assert property (
        @(posedge clk) (divisor != 4'b0000) |-> (remainder == (dividend % divisor))
    );

    // Remainder stays below the divisor.
    check_remainder_less_than_divisor: assert property (
        @(posedge clk) (divisor != 4'b0000) |-> (remainder < divisor)
    );

    // Quotient and remainder reconstruct the dividend.
    check_division_identity: assert property (
        @(posedge clk) (divisor != 4'b0000) |-> (((quotient * divisor) + remainder) == dividend)
    );

    // Smaller dividend gives zero quotient and pass-through remainder.
    check_smaller_dividend_behavior: assert property (
        @(posedge clk) ((divisor != 4'b0000) && (dividend < divisor)) |-> ((quotient == 4'b0000) && (remainder == dividend))
    );

    // Dividing by one passes dividend to quotient with zero remainder.
    check_divisor_one_behavior: assert property (
        @(posedge clk) (divisor == 4'b0001) |-> ((quotient == dividend) && (remainder == 4'b0000))
    );

    // Zero dividend produces zero outputs.
    check_zero_dividend_behavior: assert property (
        @(posedge clk) (dividend == 4'b0000) |-> ((quotient == 4'b0000) && (remainder == 4'b0000))
    );

endmodule

rtl:
module signed_magnitude_adder (
    input signed [3:0] A,
    input signed [3:0] B,
    output signed [3:0] sum
);
    assign sum = A + B;
endmodule

module signed_mag_comparator (
    input signed [3:0] A,
    output eq,
    output lt,
    output gt
);
    assign eq = (A == 0);
    assign lt = (A < 0);
    assign gt = (A > 0);
endmodule

module top_module (
    input clk,
    input reset,
    input signed [3:0] A,
    input signed [3:0] B,
    input select,
    output reg signed [3:0] out
);
    wire signed [3:0] sum;
    wire eq, lt, gt;
    signed_mag_comparator comparator(A, eq, lt, gt);
    signed_magnitude_adder adder(A, B, sum);

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            out <= 4'b0000;
        end else begin
            if (select) begin
                out <= {4'b0000, eq, lt, gt};
            end else begin
                out <= sum;
            end
        end
    end
endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic reset,
    input logic signed [3:0] A,
    input logic signed [3:0] B,
    input logic select,
    input logic signed [3:0] out
);

    // Reset forces the registered output to zero.
    check_reset_clears_out: assert property (
        @(posedge clk) reset |-> (out == 4'sd0)
    );

    // When select is low, out captures the 4-bit signed sum on the next cycle.
    check_add_path_updates_out: assert property (
        @(posedge clk) disable iff (reset)
        (!select) |=> (out == ($past(A) + $past(B)))
    );

    // When select is high and A is zero, out captures the zero-status encoding.
    check_select_zero_encoding: assert property (
        @(posedge clk) disable iff (reset)
        (select && (A == 4'sd0)) |=> (out == 4'b0100)
    );

    // When select is high and A is negative, out captures the negative-status encoding.
    check_select_negative_encoding: assert property (
        @(posedge clk) disable iff (reset)
        (select && (A < 4'sd0)) |=> (out == 4'b0010)
    );

    // When select is high and A is positive, out captures the positive-status encoding.
    check_select_positive_encoding: assert property (
        @(posedge clk) disable iff (reset)
        (select && (A > 4'sd0)) |=> (out == 4'b0001)
    );

endmodule

rtl:
module logic_function (
    X,
    A1,
    A2,
    B1,
    B2
);

    // Module ports
    output X;
    input A1;
    input A2;
    input B1;
    input B2;

    // Local signals
    wire or0_out;
    wire or1_out;
    wire and0_out_X;

    //  Name  Output      Other arguments
    or  or0  (or0_out   , A2, A1          );
    or  or1  (or1_out   , B2, B1          );
    and and0 (and0_out_X, or0_out, or1_out);
    buf buf0 (X         , and0_out_X      );

endmodule

sva:
module logic_function_sva (
    input logic clk,
    input logic X,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic B2
);

    // X must equal the AND of the two OR input groups.
    check_x_matches_or_and_function: assert property (
        @(posedge clk) X == ((A1 | A2) & (B1 | B2))
    );

    // If both A inputs are low, X must be low.
    check_a_group_low_forces_x_low: assert property (
        @(posedge clk) ((A1 == 1'b0) && (A2 == 1'b0)) |-> (X == 1'b0)
    );

    // If both B inputs are low, X must be low.
    check_b_group_low_forces_x_low: assert property (
        @(posedge clk) ((B1 == 1'b0) && (B2 == 1'b0)) |-> (X == 1'b0)
    );

    // If both OR groups are high, X must be high.
    check_both_or_groups_high_drive_x_high: assert property (
        @(posedge clk) ((A1 | A2) & (B1 | B2)) |-> (X == 1'b1)
    );

    // X high implies one A input and one B input are high.
    check_x_high_implies_both_groups_high: assert property (
        @(posedge clk) (X == 1'b1) |-> ((A1 | A2) & (B1 | B2))
    );

    // Stable sampled inputs must keep sampled X stable.
    check_stable_inputs_keep_x_stable: assert property (
        @(posedge clk) $stable({A1, A2, B1, B2}) |-> $stable(X)
    );

endmodule

rtl:
module barrel_shift_mag_comp (
    input [3:0] a, b,
    input [1:0] shift,
    output reg [2:0] comparison_result,
    output reg [3:0] final_output
);

reg [3:0] shifted_a;
reg [3:0] shifted_b;

// Barrel Shifter
always @(*) begin
    case (shift)
        2'b00: shifted_a = a;
        2'b01: shifted_a = {a[2:0], 1'b0};
        2'b10: shifted_a = {1'b0, a[3:1]};
        2'b11: shifted_a = {a[1:0], 2'b00};
    endcase
    shifted_b = b;
end

// Magnitude Comparator
always @(*) begin
    if (shifted_a > shifted_b) begin
        comparison_result = 3'b001;
    end else if (shifted_a < shifted_b) begin
        comparison_result = 3'b010;
    end else begin
        comparison_result = 3'b100;
    end
end

// Functional Module
always @(*) begin
    case (comparison_result)
        3'b001: final_output = shifted_a;
        3'b010: final_output = shifted_b;
        3'b100: final_output = shifted_a | shifted_b;
    endcase
end

endmodule

sva:
module barrel_shift_mag_comp_sva (
    input logic clk,
    input logic [3:0] a,
    input logic [3:0] b,
    input logic [1:0] shift,
    input logic [2:0] comparison_result,
    input logic [3:0] final_output
);

    // No RTL reset; assertions are always enabled.

    // comparison_result only uses the three implemented encodings.
    check_comparison_result_legal: assert property (
        @(posedge clk) disable iff (1'b0)
        (comparison_result == 3'b001) || (comparison_result == 3'b010) || (comparison_result == 3'b100)
    );

    // Shift 00 compares unshifted a against b.
    check_compare_shift_00: assert property (
        @(posedge clk) disable iff (1'b0)
        (shift == 2'b00) |-> (comparison_result == ((a > b) ? 3'b001 : ((a < b) ? 3'b010 : 3'b100)))
    );

    // Shift 01 compares a left-shifted by 1 against b.
    check_compare_shift_01: assert property (
        @(posedge clk) disable iff (1'b0)
        (shift == 2'b01) |-> (comparison_result == (({a[2:0], 1'b0} > b) ? 3'b001 : (({a[2:0], 1'b0} < b) ? 3'b010 : 3'b100)))
    );

    // Shift 10 compares a right-shifted by 1 against b.
    check_compare_shift_10: assert property (
        @(posedge clk) disable iff (1'b0)
        (shift == 2'b10) |-> (comparison_result == (({1'b0, a[3:1]} > b) ? 3'b001 : (({1'b0, a[3:1]} < b) ? 3'b010 : 3'b100)))
    );

    // Shift 11 compares a left-shifted by 2 against b.
    check_compare_shift_11: assert property (
        @(posedge clk) disable iff (1'b0)
        (shift == 2'b11) |-> (comparison_result == (({a[1:0], 2'b00} > b) ? 3'b001 : (({a[1:0], 2'b00} < b) ? 3'b010 : 3'b100)))
    );

    // Shift 00 drives final_output from the implemented compare/select logic.
    check_output_shift_00: assert property (
        @(posedge clk) disable iff (1'b0)
        (shift == 2'b00) |-> (final_output == ((a > b) ? a : ((a < b) ? b : (a | b))))
    );

    // Shift 01 drives final_output from the implemented compare/select logic.
    check_output_shift_01: assert property (
        @(posedge clk) disable iff (1'b0)
        (shift == 2'b01) |-> (final_output == (({a[2:0], 1'b0} > b) ? {a[2:0], 1'b0} : (({a[2:0], 1'b0} < b) ? b : ({a[2:0], 1'b0} | b))))
    );

    // Shift 10 drives final_output from the implemented compare/select logic.
    check_output_shift_10: assert property (
        @(posedge clk) disable iff (1'b0)
        (shift == 2'b10) |-> (final_output == (({1'b0, a[3:1]} > b) ? {1'b0, a[3:1]} : (({1'b0, a[3:1]} < b) ? b : ({1'b0, a[3:1]} | b))))
    );

    // Shift 11 drives final_output from the implemented compare/select logic.
    check_output_shift_11: assert property (
        @(posedge clk) disable iff (1'b0)
        (shift == 2'b11) |-> (final_output == (({a[1:0], 2'b00} > b) ? {a[1:0], 2'b00} : (({a[1:0], 2'b00} < b) ? b : ({a[1:0], 2'b00} | b))))
    );

endmodule

rtl:
module bitwise_and (
    input clk,
    input [31:0] A,
    input [31:0] B,
    output reg [31:0] Q
);

always @(posedge clk) begin
    Q <= A & B;
end

endmodule

sva:
module bitwise_and_sva (
    input logic        clk,
    input logic [31:0] A,
    input logic [31:0] B,
    input logic [31:0] Q
);

    // Q captures the previous cycle's bitwise AND of A and B.
    check_q_updates_to_prev_and: assert property (
        @(posedge clk) 1'b1 |=> (Q == ($past(A) & $past(B)))
    );

    // If A and B have no overlapping 1 bits, Q becomes zero on the next cycle.
    check_zero_when_no_bit_overlap: assert property (
        @(posedge clk) ((A & B) == 32'h0000_0000) |=> (Q == 32'h0000_0000)
    );

    // If A is all ones, Q captures the previous value of B.
    check_q_matches_prev_b_when_a_all_ones: assert property (
        @(posedge clk) (A == 32'hFFFF_FFFF) |=> (Q == $past(B))
    );

    // If B is all ones, Q captures the previous value of A.
    check_q_matches_prev_a_when_b_all_ones: assert property (
        @(posedge clk) (B == 32'hFFFF_FFFF) |=> (Q == $past(A))
    );

    // Q cannot contain 1 bits that were not set in the previous A value.
    check_q_subset_of_prev_a: assert property (
        @(posedge clk) 1'b1 |=> ((Q & ~$past(A)) == 32'h0000_0000)
    );

    // Q cannot contain 1 bits that were not set in the previous B value.
    check_q_subset_of_prev_b: assert property (
        @(posedge clk) 1'b1 |=> ((Q & ~$past(B)) == 32'h0000_0000)
    );

endmodule

rtl:
module dff_sr_clr (clk, d, set, reset, clr, q, qn);
  input clk, d, set, reset, clr;
  output reg q;
  output reg qn;

  always @(posedge clk) begin
    if (clr == 0) begin
      q <= 0;
    end else if (reset == 1) begin
      q <= 0;
    end else if (set == 1) begin
      q <= 1;
    end else begin
      q <= d;
    end
  end

  always @* begin
    qn = ~q;
  end

endmodule

sva:
module dff_sr_clr_sva (
    input logic clk,
    input logic d,
    input logic set,
    input logic reset,
    input logic clr,
    input logic q,
    input logic qn
);

    // Clock: clk
    // Synchronous controls: clr is active-low, reset is active-high, set is active-high
    // q is sequential and qn is combinational

    // Low clear has highest priority and drives q low.
    check_clear_priority_drives_q_low: assert property (
        @(posedge clk) disable iff (1'b0)
        (clr == 1'b0) |=> (q == 1'b0)
    );

    // High reset drives q low when clear is inactive.
    check_reset_drives_q_low: assert property (
        @(posedge clk) disable iff (1'b0)
        (clr == 1'b1 && reset == 1'b1) |=> (q == 1'b0)
    );

    // High set drives q high when clear and reset are inactive.
    check_set_drives_q_high: assert property (
        @(posedge clk) disable iff (1'b0)
        (clr == 1'b1 && reset == 1'b0 && set == 1'b1) |=> (q == 1'b1)
    );

    // d is captured when clear, reset, and set are inactive.
    check_d_captured_when_controls_inactive: assert property (
        @(posedge clk) disable iff (1'b0)
        (clr == 1'b1 && reset == 1'b0 && set == 1'b0) |=> (q == $past(d))
    );

    // q matches the previous cycle's prioritized input selection.
    check_q_matches_prioritized_next_state: assert property (
        @(posedge clk) disable iff (1'b0)
        1'b1 |=> (
            q == (
                ($past(clr) == 1'b0) ? 1'b0 :
                ($past(reset) == 1'b1) ? 1'b0 :
                ($past(set) == 1'b1) ? 1'b1 :
                                       $past(d)
            )
        )
    );

    // qn is always the inverse of q.
    check_qn_is_inverse_of_q: assert property (
        @(posedge clk) disable iff (1'b0)
        (qn == ~q)
    );

endmodule

rtl:
module sky130_fd_sc_hs__decap (input VPWR, input VGND, output decap);

    assign decap = (VPWR == 1'b0) && (VGND == 1'b1) ? 1'b1 : 1'b0;

endmodule

sva:
module sky130_fd_sc_hs__decap_sva (
    input logic clk,
    input logic VPWR,
    input logic VGND,
    input logic decap
);

    // decap matches the implemented combinational equation.
    check_decap_equation: assert property (
        @(posedge clk)
        decap === (((VPWR == 1'b0) && (VGND == 1'b1)) ? 1'b1 : 1'b0)
    );

    // decap can only be high when VPWR is low and VGND is high.
    check_decap_high_condition: assert property (
        @(posedge clk)
        (decap === 1'b1) |-> ((VPWR === 1'b0) && (VGND === 1'b1))
    );

    // VPWR low and VGND high must drive decap high.
    check_decap_asserted_for_active_combination: assert property (
        @(posedge clk)
        ((VPWR === 1'b0) && (VGND === 1'b1)) |-> (decap === 1'b1)
    );

    // VPWR high forces decap low.
    check_decap_low_when_vpwr_high: assert property (
        @(posedge clk)
        (VPWR === 1'b1) |-> (decap === 1'b0)
    );

    // VGND low forces decap low.
    check_decap_low_when_vgnd_low: assert property (
        @(posedge clk)
        (VGND === 1'b0) |-> (decap === 1'b0)
    );

endmodule

rtl:
module fifo36_demux
  #(parameter match_data = 0,
    parameter match_mask = 0)
   (input clk, input reset, input clear,
    input [35:0] data_i, input src_rdy_i, output dst_rdy_o,
    output [35:0] data0_o, output src0_rdy_o, input dst0_rdy_i,
    output [35:0] data1_o, output src1_rdy_o, input dst1_rdy_i);

   localparam DMX_IDLE = 0;
   localparam DMX_DATA0 = 1;
   localparam DMX_DATA1 = 2;

   reg [1:0] 	  state;

   wire 	  match = |( (data_i ^ match_data) & match_mask );
   wire 	  eof = data_i[33];

   always @(posedge clk)
     if(reset | clear)
       state <= DMX_IDLE;
     else
       case(state)
	 DMX_IDLE :
	   if(src_rdy_i)
	     if(match)
	       state <= DMX_DATA1;
	     else
	       state <= DMX_DATA0;
	 DMX_DATA0 :
	   if(src_rdy_i & dst0_rdy_i & eof)
	     state <= DMX_IDLE;
	 DMX_DATA1 :
	   if(src_rdy_i & dst1_rdy_i & eof)
	     state <= DMX_IDLE;
	 default :
	   state <= DMX_IDLE;
       endcase assign dst_rdy_o = (state==DMX_IDLE) ? 0 : (state==DMX_DATA0) ? dst0_rdy_i : dst1_rdy_i;
   assign src0_rdy_o = (state==DMX_DATA0) ? src_rdy_i : 0;
   assign src1_rdy_o = (state==DMX_DATA1) ? src_rdy_i : 0;

   assign data0_o = data_i;
   assign data1_o = data_i;

endmodule

sva:
module fifo36_demux_sva
  #(parameter logic [35:0] match_data = 36'd0,
    parameter logic [35:0] match_mask = 36'd0)
   (input logic        clk,
    input logic        reset,
    input logic        clear,
    input logic [35:0] data_i,
    input logic        src_rdy_i,
    input logic        dst_rdy_o,
    input logic [35:0] data0_o,
    input logic        src0_rdy_o,
    input logic        dst0_rdy_i,
    input logic [35:0] data1_o,
    input logic        src1_rdy_o,
    input logic        dst1_rdy_i,
    input logic [1:0]  state);

   localparam logic [1:0] DMX_IDLE  = 2'd0;
   localparam logic [1:0] DMX_DATA0 = 2'd1;
   localparam logic [1:0] DMX_DATA1 = 2'd2;

   wire match;
   wire eof;

   assign match = |((data_i ^ match_data) & match_mask);
   assign eof   = data_i[33];

   // Reset or clear forces the FSM back to IDLE.
   check_reset_or_clear_forces_idle: assert property (
      @(posedge clk)
      (reset || clear) |=> (state == DMX_IDLE)
   );

   // data0_o is always a direct copy of data_i.
   check_data0_passthrough: assert property (
      @(posedge clk) disable iff (reset || clear)
      (data0_o == data_i)
   );

   // data1_o is always a direct copy of data_i.
   check_data1_passthrough: assert property (
      @(posedge clk) disable iff (reset || clear)
      (data1_o == data_i)
   );

   // IDLE drives no ready signals downstream.
   check_idle_outputs: assert property (
      @(posedge clk) disable iff (reset || clear)
      (state == DMX_IDLE) |-> ((dst_rdy_o == 1'b0) && (src0_rdy_o == 1'b0) && (src1_rdy_o == 1'b0))
   );

   // DATA0 forwards src_rdy_i and dst0_rdy_i on the selected path.
   check_data0_outputs: assert property (
      @(posedge clk) disable iff (reset || clear)
      (state == DMX_DATA0) |-> ((dst_rdy_o == dst0_rdy_i) && (src0_rdy_o == src_rdy_i) && (src1_rdy_o == 1'b0))
   );

   // DATA1 forwards src_rdy_i and dst1_rdy_i on the selected path.
   check_data1_outputs: assert property (
      @(posedge clk) disable iff (reset || clear)
      (state == DMX_DATA1) |-> ((dst_rdy_o == dst1_rdy_i) && (src1_rdy_o == src_rdy_i) && (src0_rdy_o == 1'b0))
   );

   // IDLE selects DATA0 when src_rdy_i is high and the match expression is low.
   check_idle_to_data0: assert property (
      @(posedge clk) disable iff (reset || clear)
      ((state == DMX_IDLE) && src_rdy_i && !match) |=> (state == DMX_DATA0)
   );

   // IDLE selects DATA1 when src_rdy_i is high and the match expression is high.
   check_idle_to_data1: assert property (
      @(posedge clk) disable iff (reset || clear)
      ((state == DMX_IDLE) && src_rdy_i && match) |=> (state == DMX_DATA1)
   );

   // IDLE holds when no source data is ready.
   check_idle_hold_without_src: assert property (
      @(posedge clk) disable iff (reset || clear)
      ((state == DMX_IDLE) && !src_rdy_i) |=> (state == DMX_IDLE)
   );

   // DATA0 returns to IDLE on an accepted EOF beat.
   check_data0_to_idle_on_eof_handshake: assert property (
      @(posedge clk) disable iff (reset || clear)
      ((state == DMX_DATA0) && src_rdy_i && dst0_rdy_i && eof) |=> (state == DMX_IDLE)
   );

   // DATA0 holds until an accepted EOF beat occurs.
   check_data0_hold_without_eof_handshake: assert property (
      @(posedge clk) disable iff (reset || clear)
      ((state == DMX_DATA0) && !(src_rdy_i && dst0_rdy_i && eof)) |=> (state == DMX_DATA0)
   );

   // DATA1 returns to IDLE on an accepted EOF beat.
   check_data1_to_idle_on_eof_handshake: assert property (
      @(posedge clk) disable iff (reset || clear)
      ((state == DMX_DATA1) && src_rdy_i && dst1_rdy_i && eof) |=> (state == DMX_IDLE)
   );

   // DATA1 holds until an accepted EOF beat occurs.
   check_data1_hold_without_eof_handshake: assert property (
      @(posedge clk) disable iff (reset || clear)
      ((state == DMX_DATA1) && !(src_rdy_i && dst1_rdy_i && eof)) |=> (state == DMX_DATA1)
   );

   // Any unrecognized state is corrected to IDLE on the next cycle.
   check_illegal_state_recovers_to_idle: assert property (
      @(posedge clk) disable iff (reset || clear)
      ((state != DMX_IDLE) && (state != DMX_DATA0) && (state != DMX_DATA1)) |=> (state == DMX_IDLE)
   );

endmodule

rtl:
module data_control(
    input [15:0] data_in,
    input [3:0] control_in,
    output [15:0] data_out,
    output [3:0] control_out
);

assign data_out = data_in + 1;
assign control_out = control_in << 1;

endmodule

sva:
module data_control_sva (
    input logic clk,
    input logic [15:0] data_in,
    input logic [3:0]  control_in,
    input logic [15:0] data_out,
    input logic [3:0]  control_out
);

    // data_out always matches data_in incremented by one.
    check_data_increment: assert property (
        @(posedge clk) data_out == (data_in + 16'd1)
    );

    // data_out wraps to zero when data_in is all ones.
    check_data_wraparound: assert property (
        @(posedge clk) (data_in == 16'hFFFF) |-> (data_out == 16'h0000)
    );

    // Incrementing by one always toggles the least-significant bit.
    check_data_lsb_toggle: assert property (
        @(posedge clk) data_out[0] == ~data_in[0]
    );

    // control_out always matches control_in shifted left by one.
    check_control_shift: assert property (
        @(posedge clk) control_out == (control_in << 1)
    );

    // A left shift by one always drives the low bit to zero.
    check_control_lsb_zero: assert property (
        @(posedge clk) control_out[0] == 1'b0
    );

    // Shifted control bits map to the next higher positions.
    check_control_shifted_bits: assert property (
        @(posedge clk) control_out[3:1] == control_in[2:0]
    );

endmodule

rtl:
module counter (
  input clk,
  input reset,
  input load,
  input [3:0] data_in,
  output reg [3:0] count_out,
  output reg wrap_around
);

  always @(posedge clk, posedge reset) begin
    if (reset) begin
      count_out <= 4'b0;
      wrap_around <= 1'b0;
    end else if (load) begin
      count_out <= data_in;
      wrap_around <= 1'b0;
    end else begin
      if (count_out == 4'b1111) begin
        count_out <= 4'b0;
        wrap_around <= 1'b1;
      end else begin
        count_out <= count_out + 1;
        wrap_around <= 1'b0;
      end
    end
  end

endmodule

sva:
module counter_assertions (
    input logic clk,
    input logic reset,
    input logic load,
    input logic [3:0] data_in,
    input logic [3:0] count_out,
    input logic wrap_around
);

    // Reset drives both outputs low by the next clock.
    check_reset_clears_outputs: assert property (
        @(posedge clk)
        reset |=> (count_out == 4'h0 && wrap_around == 1'b0)
    );

    // A load updates count_out from data_in and clears wrap_around.
    check_load_updates_count: assert property (
        @(posedge clk) disable iff (reset)
        load |=> (count_out == $past(data_in) && wrap_around == 1'b0)
    );

    // Without load, non-max values increment and keep wrap_around low.
    check_increment_when_not_max: assert property (
        @(posedge clk) disable iff (reset)
        (!load && (count_out != 4'hF)) |=> (count_out == ($past(count_out) + 4'h1) && wrap_around == 1'b0)
    );

    // Without load, 4'hF wraps to zero and asserts wrap_around.
    check_wrap_at_max: assert property (
        @(posedge clk) disable iff (reset)
        (!load && (count_out == 4'hF)) |=> (count_out == 4'h0 && wrap_around == 1'b1)
    );

endmodule

rtl:
module flip_flop_async_reset_set (
    input D,
    input RESET_B,
    input SET_B,
    input CLK,
    output reg Q,
    output reg Q_B
);

    always @(posedge CLK) begin
        if (!RESET_B) begin
            Q <= 1'b0;
            Q_B <= 1'b1;
        end else if (!SET_B) begin
            Q <= 1'b1;
            Q_B <= 1'b0;
        end else begin
            Q <= D;
            Q_B <= ~D;
        end
    end

endmodule

sva:
module flip_flop_async_reset_set_sva (
    input logic D,
    input logic RESET_B,
    input logic SET_B,
    input logic CLK,
    input logic Q,
    input logic Q_B
);

    // Low RESET_B forces the reset state on the next cycle.
    check_reset_value: assert property (
        @(posedge CLK)
        !RESET_B |=> (Q == 1'b0 && Q_B == 1'b1)
    );

    // Low RESET_B overrides low SET_B.
    check_reset_priority_over_set: assert property (
        @(posedge CLK)
        (!RESET_B && !SET_B) |=> (Q == 1'b0 && Q_B == 1'b1)
    );

    // Low SET_B forces the set state when reset is inactive.
    check_set_value: assert property (
        @(posedge CLK) disable iff (!RESET_B)
        !SET_B |=> (Q == 1'b1 && Q_B == 1'b0)
    );

    // With reset and set inactive, D=1 is captured on the next cycle.
    check_capture_d_high: assert property (
        @(posedge CLK) disable iff (!RESET_B)
        (SET_B && D) |=> (Q == 1'b1 && Q_B == 1'b0)
    );

    // With reset and set inactive, D=0 is captured on the next cycle.
    check_capture_d_low: assert property (
        @(posedge CLK) disable iff (!RESET_B)
        (SET_B && !D) |=> (Q == 1'b0 && Q_B == 1'b1)
    );

    // The two outputs remain complementary after each clocked update.
    check_outputs_complementary: assert property (
        @(posedge CLK)
        1'b1 |=> (Q_B == ~Q)
    );

endmodule

rtl:
module four_input_logic (input A, input B, input C, input D, output Z);

    assign Z = (A & ~B) ? 1 : ((~A & B) ? 0 : ((A & B) ? C : D));

endmodule

sva:
module four_input_logic_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic Z
);

    // Z matches the RTL's nested conditional expression.
    check_z_matches_rtl_expression: assert property (
        @(posedge clk)
        Z == ((A & ~B) ? 1'b1 : ((~A & B) ? 1'b0 : ((A & B) ? C : D)))
    );

    // When A is high and B is low, Z is forced high.
    check_a1_b0_forces_z_high: assert property (
        @(posedge clk)
        (A && !B) |-> (Z == 1'b1)
    );

    // When A is low and B is high, Z is forced low.
    check_a0_b1_forces_z_low: assert property (
        @(posedge clk)
        (!A && B) |-> (Z == 1'b0)
    );

    // When both A and B are high, Z follows C.
    check_a1_b1_selects_c: assert property (
        @(posedge clk)
        (A && B) |-> (Z == C)
    );

    // When both A and B are low, Z follows D.
    check_a0_b0_selects_d: assert property (
        @(posedge clk)
        (!A && !B) |-> (Z == D)
    );

endmodule

rtl:
module adder4(input [3:0] a, input [3:0] b, output reg [3:0] sum);
    wire [4:0] temp_sum;

    assign temp_sum = a + b;

    always @(*) begin
        if (temp_sum > 15) begin
            sum <= temp_sum - 16;
        end
        else begin
            sum <= temp_sum;
        end
    end
endmodule

sva:
module adder4_assertions(
    input logic [3:0] a,
    input logic [3:0] b,
    input logic [3:0] sum
);

    // Sum matches a+b modulo 16.
    check_sum_mod16: assert property (
        @($global_clock) {1'b0, sum} == (({1'b0, a} + {1'b0, b}) & 5'h0f)
    );

    // No-overflow additions pass through unchanged.
    check_no_overflow_result: assert property (
        @($global_clock) (({1'b0, a} + {1'b0, b}) <= 5'd15) |-> ({1'b0, sum} == ({1'b0, a} + {1'b0, b}))
    );

    // Overflow additions wrap by subtracting 16.
    check_overflow_wrap_result: assert property (
        @($global_clock) (({1'b0, a} + {1'b0, b}) > 5'd15) |-> ({1'b0, sum} == (({1'b0, a} + {1'b0, b}) - 5'd16))
    );

    // Zero on a leaves b unchanged at the output.
    check_zero_a_passthrough: assert property (
        @($global_clock) (a == 4'h0) |-> (sum == b)
    );

    // Zero on b leaves a unchanged at the output.
    check_zero_b_passthrough: assert property (
        @($global_clock) (b == 4'h0) |-> (sum == a)
    );

    // A full sum of 15 is preserved.
    check_fullsum_fifteen: assert property (
        @($global_clock) (({1'b0, a} + {1'b0, b}) == 5'd15) |-> (sum == 4'hf)
    );

    // A full sum of 16 wraps to zero.
    check_fullsum_sixteen_wrap: assert property (
        @($global_clock) (({1'b0, a} + {1'b0, b}) == 5'd16) |-> (sum == 4'h0)
    );

    // Zero plus zero produces zero.
    check_zero_plus_zero: assert property (
        @($global_clock) (a == 4'h0 && b == 4'h0) |-> (sum == 4'h0)
    );

    // Fifteen plus fifteen wraps to fourteen.
    check_max_plus_max_wrap: assert property (
        @($global_clock) (a == 4'hf && b == 4'hf) |-> (sum == 4'he)
    );

endmodule

module barrel_shifter_sva (
    input logic clk,
    input logic [3:0] data_in,
    input logic [1:0] shift,
    input logic [3:0] out
);

    // Shift 00 passes the input through unchanged.
    check_pass_through: assert property (
        @(posedge clk) (shift == 2'b00) |-> (out == data_in)
    );

    // Shift 01 performs a left shift by 1 with zero fill.
    check_shift_left_by_1: assert property (
        @(posedge clk) (shift == 2'b01) |-> (out == {data_in[2:0], 1'b0})
    );

    // Shift 10 performs a right shift by 1 with zero fill.
    check_shift_right_by_1: assert property (
        @(posedge clk) (shift == 2'b10) |-> (out == {1'b0, data_in[3:1]})
    );

    // Shift 11 performs a left shift by 2 with zero fill.
    check_shift_left_by_2: assert property (
        @(posedge clk) (shift == 2'b11) |-> (out == {data_in[1:0], 2'b00})
    );

    // Output always matches the selected shift operation.
    check_functional_mapping: assert property (
        @(posedge clk)
        (out == ((shift == 2'b00) ? data_in :
                 (shift == 2'b01) ? {data_in[2:0], 1'b0} :
                 (shift == 2'b10) ? {1'b0, data_in[3:1]} :
                                    {data_in[1:0], 2'b00}))
    );

endmodule

