    );

    // A low output with known inputs requires at least one low input.
    check_output_low_requires_low_input_when_inputs_known: assert property (
        @(posedge clk) (!$isunknown({A, B, C, D}) && X === 1'b0) |-> (A === 1'b0 || B === 1'b0 || C === 1'b0 || D === 1'b0)
    );

