    input [n-1:0] bin,
    output [n-1:0] gray
    );

    wire [n-1:0] temp;
    assign temp = {bin[n-1], bin[n-1:1] ^ bin[n-2:0]};

    assign gray = temp;

endmodule

sva:
module bin_to_gray_sva #(
    parameter int n = 4
) (
    input logic [n-1:0] bin,
    input logic [n-1:0] gray
);

    genvar i;

    // No explicit clock or reset exists in the RTL; sample on $global_clock.
    // The RTL is purely combinational and implements binary-to-Gray conversion.

    generate
        if (n == 1) begin : gen_single_bit
            // For 1-bit width, Gray code matches the binary input.
            check_gray_single_bit: assert property (
                @($global_clock) gray == bin
            );
        end else begin : gen_multi_bit
            // Gray output matches the RTL concatenation expression.
            check_gray_full_mapping: assert property (
                @($global_clock) gray == {bin[n-1], (bin[n-1:1] ^ bin[n-2:0])}
            );

            // The Gray MSB matches the binary MSB.
            check_gray_msb: assert property (
                @($global_clock) gray[n-1] == bin[n-1]
            );

            for (i = 0; i < n-1; i = i + 1) begin : gen_lower_bits
                // Each lower Gray bit is the XOR of adjacent binary bits.
                check_gray_adjacent_xor: assert property (
                    @($global_clock) gray[i] == (bin[i+1] ^ bin[i])
                );
            end
        end
    endgenerate

endmodule

module register16_with_enable_sva (
    input logic clk,
    input logic [15:0] in,
    input logic write,
    input logic reset,
    input logic enable,
    input logic [15:0] out
);

    // Reset clears the register on the next sampled cycle.
    check_reset_clears_out: assert property (
        @(posedge clk) reset |=> (out == 16'b0)
    );

    // Reset overrides a simultaneous enabled write.
    check_reset_priority_over_write: assert property (
        @(posedge clk) (reset && enable && write) |=> (out == 16'b0)
    );

    // An enabled write loads the input value.
    check_capture_on_write: assert property (
        @(posedge clk) disable iff (reset) (enable && write) |=> (out == $past(in))
    );

    // When disabled, the register holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset) (!enable) |=> (out == $past(out))
    );

    // When enabled without write, the register holds its value.
    check_hold_when_no_write: assert property (
        @(posedge clk) disable iff (reset) (enable && !write) |=> (out == $past(out))
    );

    // Write has no effect unless enable is high.
    check_write_ignored_without_enable: assert property (
        @(posedge clk) disable iff (reset) (!enable && write) |=> (out == $past(out))
    );

endmodule

module decoder_sva (
    input logic clk,
    input logic [3:0] in,
    input logic [15:0] out
);

    // Output matches the decoded input value.
    check_exact_decode: assert property (
        @(posedge clk) out == (16'h0001 << in)
    );

    // Exactly one output bit is asserted.
    check_output_onehot: assert property (
        @(posedge clk) $onehot(out)
    );

    // The selected output bit is high.
    check_selected_bit_high: assert property (
        @(posedge clk) out[in] == 1'b1
    );

    // All non-selected output bits are low.
    check_unselected_bits_low: assert property (
        @(posedge clk) (out & ~(16'h0001 << in)) == 16'h0000
    );

endmodule

rtl:
module top_module(
    input [31:0] a,
    input [31:0] b,
    input sub,
    output [31:0] sum
);

    wire [15:0] a_low = a[15:0];
    wire [15:0] a_high = a[31:16];
    wire [15:0] b_low = b[15:0];
    wire [15:0] b_high = b[31:16];
    wire [15:0] sum_low;
    wire [15:0] sum_high;
    wire carry;

    // Instantiate the two 16-bit adder modules
    adder16 adder_low(
        .a(a_low),
        .b(b_low),
        .cin(sub),
        .sum(sum_low),
        .cout(carry)
    );

    adder16 adder_high(
        .a(a_high),
        .b(b_high),
        .cin(carry),
        .sum(sum_high),
        .cout()
    );

    // Use a 32-bit multiplexer to select between the addition and subtraction outputs
    assign sum = sub ? {sum_high, sum_low} - 1 : {sum_high, sum_low};

endmodule

// 16-bit adder module
module adder16(
    input [15:0] a,
    input [15:0] b,
    input cin,
    output [15:0] sum,
    output cout
);

    assign {cout, sum} = a + b + cin;

endmodule

sva:
module top_module_assertions (
    input logic clk,
    input logic [31:0] a,
    input logic [31:0] b,
    input logic sub,
    input logic [31:0] sum
);

    // Output always matches 32-bit addition of a and b.
    check_sum_matches_addition: assert property (
        @(posedge clk) sum == (a + b)
    );

    // With sub low, the output matches addition.
    check_add_mode_matches_addition: assert property (
        @(posedge clk) !sub |-> (sum == (a + b))
    );

    // With sub high, the output still matches addition.
    check_sub_mode_still_matches_addition: assert property (
        @(posedge clk) sub |-> (sum == (a + b))
    );

    // The low 16 bits match the low-half addition result.
    check_low_half_matches_addition: assert property (
        @(posedge clk) sum[15:0] == (a[15:0] + b[15:0])
    );

    // A carry from the low half increments the high-half result.
    check_high_half_with_low_carry: assert property (
        @(posedge clk)
        (({1'b0, a[15:0]} + {1'b0, b[15:0]}) >= 17'h1_0000)
        |-> (sum[31:16] == (a[31:16] + b[31:16] + 16'd1))
    );

    // Without a low-half carry, the high half is a simple add.
    check_high_half_without_low_carry: assert property (
        @(posedge clk)
        (({1'b0, a[15:0]} + {1'b0, b[15:0]}) < 17'h1_0000)
        |-> (sum[31:16] == (a[31:16] + b[31:16]))
    );

    // Zero on a passes b through to the output.
    check_a_zero_passthrough: assert property (
        @(posedge clk) (a == 32'd0) |-> (sum == b)
    );

    // Zero on b passes a through to the output.
    check_b_zero_passthrough: assert property (
        @(posedge clk) (b == 32'd0) |-> (sum == a)
    );

    // Changing sub alone does not change the output.
    check_sub_toggle_no_effect: assert property (
        @(posedge clk) ($stable(a) && $stable(b) && $changed(sub)) |-> $stable(sum)
    );

endmodule

