module nor3 (
    output Y,
    input A,
    input B,
    input C_N
);

    wire Y_wire, A_wire, B_wire, C_N_wire;
    nor3_gate base (
        .Y(Y_wire),
        .A(A_wire),
        .B(B_wire),
        .C_N(C_N_wire)
    );

    assign Y = Y_wire;
    assign A = A_wire;
    assign B = B_wire;
    assign C_N = C_N_wire;

endmodule

module nor3_gate (
    output Y,
    input A,
    input B,
    input C_N
);

    assign Y = ~(A | B | C_N);

endmodule

sva:
module nor3_sva (
    input logic clk,
    input logic Y,
    input logic A,
    input logic B,
    input logic C_N,
    input logic Y_wire,
    input logic A_wire,
    input logic B_wire,
    input logic C_N_wire
);

    // Top output mirrors the internal Y wire.
    check_output_matches_internal: assert property (
        @(posedge clk) Y === Y_wire
    );

    // Internal gate output implements the coded 3-input NOR.
    check_internal_nor_equation: assert property (
        @(posedge clk) Y_wire === ~(A_wire | B_wire | C_N_wire)
    );

    // Top output matches the NOR of the internal gate inputs.
    check_output_nor_equation: assert property (
        @(posedge clk) Y === ~(A_wire | B_wire | C_N_wire)
    );

    // All internal inputs low drives the internal output high.
    check_internal_high_when_all_inputs_low: assert property (
        @(posedge clk)
        ((A_wire === 1'b0) && (B_wire === 1'b0) && (C_N_wire === 1'b0))
        |-> (Y_wire === 1'b1)
    );

    // Internal A high forces the internal output low.
    check_internal_low_when_a_high: assert property (
        @(posedge clk) (A_wire === 1'b1) |-> (Y_wire === 1'b0)
    );

    // Internal B high forces the internal output low.
    check_internal_low_when_b_high: assert property (
        @(posedge clk) (B_wire === 1'b1) |-> (Y_wire === 1'b0)
    );

    // Internal C_N high forces the internal output low.
    check_internal_low_when_c_n_high: assert property (
        @(posedge clk) (C_N_wire === 1'b1) |-> (Y_wire === 1'b0)
    );

    // Internal output high implies all internal inputs are low.
    check_inputs_low_when_internal_output_high: assert property (
        @(posedge clk) (Y_wire === 1'b1)
        |-> ((A_wire === 1'b0) && (B_wire === 1'b0) && (C_N_wire === 1'b0))
    );

    // Internal output low implies at least one internal input is high.
    check_some_input_high_when_internal_output_low: assert property (
        @(posedge clk) (Y_wire === 1'b0)
        |-> ((A_wire === 1'b1) || (B_wire === 1'b1) || (C_N_wire === 1'b1))
    );

    // All internal inputs low drives the top output high.
    check_output_high_when_all_inputs_low: assert property (
        @(posedge clk)
        ((A_wire === 1'b0) && (B_wire === 1'b0) && (C_N_wire === 1'b0))
        |-> (Y === 1'b1)
    );

    // Any internal input high forces the top output low.
    check_output_low_when_any_input_high: assert property (
        @(posedge clk)
        ((A_wire === 1'b1) || (B_wire === 1'b1) || (C_N_wire === 1'b1))
        |-> (Y === 1'b0)
    );

endmodule

rtl:
module absolute_value_calculator #(
  parameter n = 8 // number of bits in the input signal
) (
  input signed [n-1:0] input_signal,
  output reg [n-1:0] output_signal
);


always @(*) begin
  if (input_signal[n-1] == 0) begin // if sign bit is 0, output input signal as is
    output_signal = input_signal;
  end else begin // if sign bit is 1, negate input signal and output the result
    output_signal = ~input_signal + 1;
  end
end

endmodule

sva:
module absolute_value_calculator_sva #(
    parameter n = 8
) (
    input logic clk,
    input logic signed [n-1:0] input_signal,
    input logic [n-1:0] output_signal
);

    localparam logic [n-1:0] MIN_NEG = {1'b1, {n-1{1'b0}}};

    // Output always matches the implemented absolute-value expression.
    check_absolute_value_function: assert property (
        @(posedge clk)
        output_signal == (input_signal[n-1] ? (~input_signal + 1'b1) : input_signal)
    );

    // Non-negative inputs pass through unchanged.
    check_non_negative_passthrough: assert property (
        @(posedge clk)
        !input_signal[n-1] |-> (output_signal == input_signal)
    );

    // Negative inputs are converted with two's-complement negation.
    check_negative_twos_complement: assert property (
        @(posedge clk)
        input_signal[n-1] |-> (output_signal == (~input_signal + 1'b1))
    );

    // Zero maps to zero.
    check_zero_maps_to_zero: assert property (
        @(posedge clk)
        (input_signal == '0) |-> (output_signal == '0)
    );

    // The most-negative input remains unchanged by two's-complement negation.
    check_min_negative_corner: assert property (
        @(posedge clk)
        (input_signal == MIN_NEG) |-> (output_signal == MIN_NEG)
    );

    // Negative inputs other than the minimum value produce a non-negative result.
    check_negative_non_min_sign_clear: assert property (
        @(posedge clk)
        (input_signal[n-1] && (input_signal != MIN_NEG)) |-> (output_signal[n-1] == 1'b0)
    );

    // Non-negative inputs produce a non-negative result.
    check_non_negative_sign_clear: assert property (
        @(posedge clk)
        !input_signal[n-1] |-> (output_signal[n-1] == 1'b0)
    );

endmodule

