module MUX4 (
  input in0,
  input in1,
  input in2,
  input in3,
  input sel0,
  input sel1,
  output reg out
);

always @(*) begin
  case ({sel1, sel0})
    2'b00: out = in0;
    2'b01: out = in1;
    2'b10: out = in2;
    2'b11: out = in3;
  endcase
end

endmodule

sva:
module MUX4_sva (
    input logic in0,
    input logic in1,
    input logic in2,
    input logic in3,
    input logic sel0,
    input logic sel1,
    input logic out
);

