    check_sel_00_routes_in0: assert property (
        @($global_clock) ({sel1, sel0} == 2'b00) |-> (out == in0)
    );

    // out equals in1 when the select value is 01.
    check_sel_01_routes_in1: assert property (
        @($global_clock) ({sel1, sel0} == 2'b01) |-> (out == in1)
    );

    // out equals in2 when the select value is 10.
    check_sel_10_routes_in2: assert property (
        @($global_clock) ({sel1, sel0} == 2'b10) |-> (out == in2)
    );

    // out equals in3 when the select value is 11.
    check_sel_11_routes_in3: assert property (
        @($global_clock) ({sel1, sel0} == 2'b11) |-> (out == in3)
    );

endmodule

rtl:
module AND4X (IN1, IN2, IN3, IN4, Q);

  input IN1;
  input IN2;
  input IN3;
  input IN4;
  output Q;

  wire AND1;
  wire AND2;
  wire AND3;

  assign AND1 = IN1 & IN2;
  assign AND2 = IN3 & IN4;
  assign AND3 = AND1 & AND2;

  assign Q = AND3;

endmodule

sva:
module AND4X_sva (
    input logic IN1,
    input logic IN2,
    input logic IN3,
    input logic IN4,
    input logic Q
);

    // Q matches the 4-input AND of the inputs.
    check_q_matches_and4: assert property (
        @($global_clock) Q == (IN1 & IN2 & IN3 & IN4)
    );

    // Q is high when all inputs are high.
    check_q_high_when_all_inputs_high: assert property (
        @($global_clock) (IN1 & IN2 & IN3 & IN4) |-> Q
    );

    // IN1 low forces Q low.
    check_q_low_when_in1_low: assert property (
        @($global_clock) !IN1 |-> !Q
    );

    // IN2 low forces Q low.
    check_q_low_when_in2_low: assert property (
        @($global_clock) !IN2 |-> !Q
    );

    // IN3 low forces Q low.
    check_q_low_when_in3_low: assert property (
        @($global_clock) !IN3 |-> !Q
    );

    // IN4 low forces Q low.
    check_q_low_when_in4_low: assert property (
        @($global_clock) !IN4 |-> !Q
    );

    // Q high implies IN1 is high.
    check_q_implies_in1_high: assert property (
        @($global_clock) Q |-> IN1
    );

    // Q high implies IN2 is high.
    check_q_implies_in2_high: assert property (
        @($global_clock) Q |-> IN2
    );

    // Q high implies IN3 is high.
    check_q_implies_in3_high: assert property (
        @($global_clock) Q |-> IN3
    );

    // Q high implies IN4 is high.
