rtl:
module ripple_carry_adder(
    input [3:0] A,
    input [3:0] B,
    input CIN,
    output [3:0] S,
    output COUT
);

    wire [3:0] C;

    assign S = A + B + CIN;

    assign C[0] = (A[0] & B[0]) | (A[0] & CIN) | (B[0] & CIN);
    assign C[1] = (A[1] & B[1]) | (A[1] & C[0]) | (B[1] & C[0]);
    assign C[2] = (A[2] & B[2]) | (A[2] & C[1]) | (B[2] & C[1]);
    assign C[3] = (A[3] & B[3]) | (A[3] & C[2]) | (B[3] & C[2]);

    assign COUT = C[3];

endmodule

sva:
module ripple_carry_adder_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic CIN,
    input logic [3:0] S,
    input logic COUT
);

    // The concatenated carry-out and sum equal the 5-bit addition result.
    check_full_add_result: assert property (
        @(posedge clk)
        {COUT, S} == ({1'b0, A} + {1'b0, B} + CIN)
    );

    // Sum bit 0 matches a full-adder XOR of A[0], B[0], and CIN.
    check_sum_bit0: assert property (
        @(posedge clk)
        S[0] == (A[0] ^ B[0] ^ CIN)
    );

    // Sum bit 1 matches a full-adder XOR using the bit-0 carry.
    check_sum_bit1: assert property (
        @(posedge clk)
        S[1] == (A[1] ^ B[1] ^
                 ((A[0] & B[0]) | (A[0] & CIN) | (B[0] & CIN)))
    );

    // Sum bit 2 matches a full-adder XOR using the bit-1 carry.
    check_sum_bit2: assert property (
        @(posedge clk)
        S[2] == (A[2] ^ B[2] ^
                 ((A[1] & B[1]) |
                  (A[1] & ((A[0] & B[0]) | (A[0] & CIN) | (B[0] & CIN))) |
                  (B[1] & ((A[0] & B[0]) | (A[0] & CIN) | (B[0] & CIN)))))
    );

    // Sum bit 3 matches a full-adder XOR using the bit-2 carry.
    check_sum_bit3: assert property (
        @(posedge clk)
        S[3] == (A[3] ^ B[3] ^
                 ((A[2] & B[2]) |
                  (A[2] & ((A[1] & B[1]) |
                           (A[1] & ((A[0] & B[0]) | (A[0] & CIN) | (B[0] & CIN))) |
                           (B[1] & ((A[0] & B[0]) | (A[0] & CIN) | (B[0] & CIN))))) |
                  (B[2] & ((A[1] & B[1]) |
                           (A[1] & ((A[0] & B[0]) | (A[0] & CIN) | (B[0] & CIN))) |
                           (B[1] & ((A[0] & B[0]) | (A[0] & CIN) | (B[0] & CIN)))))))
    );

    // COUT matches the ripple-carry carry generated from the MSB stage.
    check_cout_equation: assert property (
        @(posedge clk)
        COUT == ((A[3] & B[3]) |
                 (A[3] & ((A[2] & B[2]) |
                          (A[2] & ((A[1] & B[1]) |
                                   (A[1] & ((A[0] & B[0]) | (A[0] & CIN) | (B[0] & CIN))) |
                                   (B[1] & ((A[0] & B[0]) | (A[0] & CIN) | (B[0] & CIN))))) |
                          (B[2] & ((A[1] & B[1]) |
                                   (A[1] & ((A[0] & B[0]) | (A[0] & CIN) | (B[0] & CIN))) |
                                   (B[1] & ((A[0] & B[0]) | (A[0] & CIN) | (B[0] & CIN))))))) |
                 (B[3] & ((A[2] & B[2]) |
                          (A[2] & ((A[1] & B[1]) |
                                   (A[1] & ((A[0] & B[0]) | (A[0] & CIN) | (B[0] & CIN))) |
                                   (B[1] & ((A[0] & B[0]) | (A[0] & CIN) | (B[0] & CIN))))) |
                          (B[2] & ((A[1] & B[1]) |
                                   (A[1] & ((A[0] & B[0]) | (A[0] & CIN) | (B[0] & CIN))) |
                                   (B[1] & ((A[0] & B[0]) | (A[0] & CIN) | (B[0] & CIN))))))))
    );

endmodule

rtl:
module bit_manipulation (
    input  wire [3:0] I,
    output wire [1:0] O
);

    assign O[0] = I[3] ? 0 : 1;
    assign O[1] = I[3] ? 1 : 0;

endmodule

sva:
module bit_manipulation_sva (
    input logic       clk,
    input logic [3:0] I,
    input logic [1:0] O
);

    // Output encoding is determined solely by I[3].
    check_output_matches_i3: assert property (
        @(posedge clk) disable iff (1'b0) O == {I[3], ~I[3]}
    );

    // O[0] is the inverse of I[3].
    check_o0_inverts_i3: assert property (
        @(posedge clk) disable iff (1'b0) O[0] == ~I[3]
    );

    // O[1] matches I[3].
    check_o1_matches_i3: assert property (
        @(posedge clk) disable iff (1'b0) O[1] == I[3]
    );

    // Exactly one output bit is high at all times.
    check_output_onehot: assert property (
        @(posedge clk) disable iff (1'b0) O[0] ^ O[1]
    );

    // I[3] low produces output 2'b01.
    check_i3_low_encoding: assert property (
        @(posedge clk) disable iff (1'b0) !I[3] |-> O == 2'b01
    );

    // I[3] high produces output 2'b10.
    check_i3_high_encoding: assert property (
        @(posedge clk) disable iff (1'b0) I[3] |-> O == 2'b10
    );

    // If I[3] is unchanged across samples, O stays unchanged.
    check_output_stable_when_i3_stable: assert property (
        @(posedge clk) disable iff (1'b0) (!$initstate && $stable(I[3])) |-> $stable(O)
    );

    // A rising I[3] drives the output to 2'b10.
    check_i3_rise_encoding: assert property (
        @(posedge clk) disable iff (1'b0) $rose(I[3]) |-> O == 2'b10
    );

    // A falling I[3] drives the output to 2'b01.
    check_i3_fall_encoding: assert property (
        @(posedge clk) disable iff (1'b0) $fell(I[3]) |-> O == 2'b01
    );

endmodule

module larger_number_sva (
    input logic        clk,
    input logic [3:0]  num1,
    input logic [3:0]  num2,
    input logic [3:0]  larger
);

    // When num1 is greater than num2, larger must equal num1.
    check_num1_selected_when_greater: assert property (
        @(posedge clk) (num1 > num2) |-> (larger == num1)
    );

    // When num2 is greater than num1, larger must equal num2.
    check_num2_selected_when_greater: assert property (
        @(posedge clk) (num2 > num1) |-> (larger == num2)
    );

    // When the inputs are equal, larger must equal that common value.
    check_equal_inputs_return_value: assert property (
        @(posedge clk) (num1 == num2) |-> (larger == num1)
    );

    // The output must always match the RTL's max-selection behavior.
    check_output_matches_max_function: assert property (
        @(posedge clk) larger == ((num1 >= num2) ? num1 : num2)
    );

    // The output must always be one of the input values.
    check_output_is_one_of_inputs: assert property (
        @(posedge clk) (larger == num1) || (larger == num2)
    );

    // The output must not be smaller than num1.
    check_output_not_smaller_than_num1: assert property (
        @(posedge clk) larger >= num1
    );

    // The output must not be smaller than num2.
    check_output_not_smaller_than_num2: assert property (
        @(posedge clk) larger >= num2
    );

endmodule

module accumulator_sva #(parameter n = 8) (
    input logic clk,
    input logic rst,
    input logic [n-1:0] in,
    input logic [n-1:0] out
);

    // Output is zero whenever reset is asserted.
    check_out_zero_during_reset: assert property (
        @(posedge clk) rst |-> (out == '0)
    );

    // A reset cycle clears the stored value for the next cycle.
    check_reset_clears_output: assert property (
        @(posedge clk) rst |=> (out == '0)
    );

    // In normal operation, output adds the previous input each cycle.
    check_accumulate_when_running: assert property (
        @(posedge clk) disable iff (rst)
        (!$initstate && !$past(rst)) |-> (out == ($past(out) + $past(in)))
    );

    // A zero input leaves the accumulated output unchanged.
    check_hold_on_zero_input: assert property (
        @(posedge clk) disable iff (rst)
        (!$initstate && !$past(rst) && ($past(in) == '0)) |-> (out == $past(out))
    );

    // The first accumulation after reset starts from zero.
    check_first_add_after_reset: assert property (
        @(posedge clk) disable iff (rst)
        (!$initstate && $past(rst)) |=> (out == $past(in))
    );

endmodule

rtl:
module xor3 (
    input A,
    input B,
    input C,
    output X
);

    assign X = A ^ B ^ C;

endmodule

sva:
module xor3_assertions (
    input logic A,
    input logic B,
    input logic C,
    input logic X
);

    // X must always equal the three-input XOR.
    check_x_matches_three_input_xor: assert property (
        @($global_clock) X == (A ^ B ^ C)
    );

    // If A and B are equal, X must equal C.
    check_x_equals_c_when_a_equals_b: assert property (
        @($global_clock) (A == B) |-> (X == C)
    );

    // If A and C are equal, X must equal B.
    check_x_equals_b_when_a_equals_c: assert property (
        @($global_clock) (A == C) |-> (X == B)
    );

    // If B and C are equal, X must equal A.
    check_x_equals_a_when_b_equals_c: assert property (
        @($global_clock) (B == C) |-> (X == A)
    );

    // If A and B differ, X must be the inverse of C.
    check_x_inverts_c_when_a_differs_b: assert property (
        @($global_clock) (A != B) |-> (X == ~C)
    );

    // If A and C differ, X must be the inverse of B.
    check_x_inverts_b_when_a_differs_c: assert property (
        @($global_clock) (A != C) |-> (X == ~B)
    );

    // If B and C differ, X must be the inverse of A.
    check_x_inverts_a_when_b_differs_c: assert property (
        @($global_clock) (B != C) |-> (X == ~A)
    );

endmodule

rtl:
module mux6 #(parameter WIREWIDTH = 1) (
    input wire [2:0] s,
    input wire [WIREWIDTH-1:0] d0, d1, d2, d3, d4, d5,
    output reg [WIREWIDTH-1:0] o
);
    always @* begin
        case(s)
            3'b000: o = d0;
            3'b001: o = d1;
            3'b010: o = d2;
            3'b011: o = d3;
            3'b100: o = d4;
            default: o = d5;
        endcase
    end

endmodule

sva:
module mux6_sva #(parameter WIREWIDTH = 1) (
    input logic [2:0] s,
    input logic [WIREWIDTH-1:0] d0,
    input logic [WIREWIDTH-1:0] d1,
    input logic [WIREWIDTH-1:0] d2,
    input logic [WIREWIDTH-1:0] d3,
    input logic [WIREWIDTH-1:0] d4,
    input logic [WIREWIDTH-1:0] d5,
    input logic [WIREWIDTH-1:0] o
);

    // Select 000 routes d0 to the output.
    check_select_000_routes_d0: assert property (
        @($global_clock) (s === 3'b000) |-> (o === d0)
    );

    // Select 001 routes d1 to the output.
    check_select_001_routes_d1: assert property (
        @($global_clock) (s === 3'b001) |-> (o === d1)
    );

    // Select 010 routes d2 to the output.
    check_select_010_routes_d2: assert property (
        @($global_clock) (s === 3'b010) |-> (o === d2)
    );

    // Select 011 routes d3 to the output.
    check_select_011_routes_d3: assert property (
        @($global_clock) (s === 3'b011) |-> (o === d3)
    );

    // Select 100 routes d4 to the output.
    check_select_100_routes_d4: assert property (
        @($global_clock) (s === 3'b100) |-> (o === d4)
    );

    // All other select values route d5 to the output.
    check_default_routes_d5: assert property (
        @($global_clock)
        !((s === 3'b000) || (s === 3'b001) || (s === 3'b010) || (s === 3'b011) || (s === 3'b100))
        |-> (o === d5)
    );

endmodule

rtl:
module sky130_fd_sc_ls__o2bb2ai (
    Y   ,
    A1_N,
    A2_N,
    B1  ,
    B2
);

    output Y   ;
    input  A1_N;
    input  A2_N;
    input  B1  ;
    input  B2  ;

    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    wire nand0_out  ;
    wire or0_out    ;
    wire nand1_out_Y;

    nand nand0 (nand0_out  , A2_N, A1_N        );
    or   or0   (or0_out    , B2, B1            );
    nand nand1 (nand1_out_Y, nand0_out, or0_out);
    buf  buf0  (Y          , nand1_out_Y       );

endmodule

sva:
module sky130_fd_sc_ls__o2bb2ai_sva (
    input logic clk,
    input logic Y,
    input logic A1_N,
    input logic A2_N,
    input logic B1,
    input logic B2
);

    // Y matches the implemented O2BB2AI boolean function.
    check_y_matches_logic: assert property (
        @(posedge clk) Y == ((A1_N & A2_N) | (~B1 & ~B2))
    );

    // Y is high whenever both B inputs are low.
    check_y_high_when_b_inputs_low: assert property (
        @(posedge clk) (~B1 & ~B2) |-> Y
    );

    // Y is high whenever both A inputs are high.
    check_y_high_when_a_inputs_high: assert property (
        @(posedge clk) (A1_N & A2_N) |-> Y
    );

    // Y is low when any B input is high and at least one A input is low.
    check_y_low_when_b_active_and_a_not_both_high: assert property (
        @(posedge clk) ((B1 | B2) & (~A1_N | ~A2_N)) |-> ~Y
    );

    // A low Y requires at least one B input to be high.
    check_y_low_requires_b_activity: assert property (
        @(posedge clk) (~Y) |-> (B1 | B2)
    );

    // A low Y requires at least one A input to be low.
    check_y_low_requires_one_a_low: assert property (
        @(posedge clk) (~Y) |-> (~A1_N | ~A2_N)
    );

endmodule

rtl:
module dual_toggle_flip_flop (
  input clk,
  input reset,
  input in,
  output reg out
);

reg q1, q2;

always @(posedge clk, negedge reset) begin
  if (!reset) begin
    q1 <= 0;
    q2 <= 0;
    out <= 0;
  end else begin
    q1 <= ~q1;
    q2 <= ~q2;
    out <= q1 ^ q2;
  end
end

endmodule

sva:
module dual_toggle_flip_flop_sva (
    input logic clk,
    input logic reset,
    input logic in,
    input logic out,
    input logic q1,
    input logic q2
);

    // Sampled low reset clears both flops and the output.
    check_reset_clears_state: assert property (
        @(posedge clk) !reset |-> (q1 == 1'b0) && (q2 == 1'b0) && (out == 1'b0)
    );

    // The reset release edge is sampled before the first active-clock update.
    check_release_cycle_samples_cleared_state: assert property (
        @(posedge clk) $rose(reset) |-> (q1 == 1'b0) && (q2 == 1'b0) && (out == 1'b0)
    );

    // q1 toggles on each active clock after a prior active cycle.
    check_q1_toggles_each_active_cycle: assert property (
        @(posedge clk) disable iff (!reset || $initstate)
        $past(reset) |-> (q1 == ~$past(q1))
    );

    // q2 toggles on each active clock after a prior active cycle.
    check_q2_toggles_each_active_cycle: assert property (
        @(posedge clk) disable iff (!reset || $initstate)
        $past(reset) |-> (q2 == ~$past(q2))
    );

    // out equals the previous cycle XOR of q1 and q2.
    check_out_matches_previous_xor: assert property (
        @(posedge clk) disable iff (!reset || $initstate)
        $past(reset) |-> (out == ($past(q1) ^ $past(q2)))
    );

    // Once q1 and q2 are equal, they stay equal and keep out low.
    check_equal_state_preserved_and_out_low: assert property (
        @(posedge clk) disable iff (!reset || $initstate)
        ($past(reset) && ($past(q1) == $past(q2))) |-> ((q1 == q2) && (out == 1'b0))
    );

    // One active cycle after reset release, both flops are high and out is low.
    check_first_active_cycle_after_reset: assert property (
        @(posedge clk) disable iff (!reset || $initstate)
        $rose(reset) |=> (q1 == 1'b1) && (q2 == 1'b1) && (out == 1'b0)
    );

endmodule

bind dual_toggle_flip_flop dual_toggle_flip_flop_sva dual_toggle_flip_flop_sva_i (
    .clk(clk),
    .reset(reset),
    .in(in),
    .out(out),
    .q1(q1),
    .q2(q2)
);

rtl:
module top(
			input wire CLK_24M,
			input wire USR_BTN,
			output wire [2:0]VGA_RGB,
			output wire HSYNC,
			output wire VSYNC
);

reg enVcnt;
reg [10:0] hzcount;
reg [10:0] vtcount;
reg RED;
reg BLU;
reg GRN;

initial begin
	enVcnt <= 0;
	hzcount <= 0;
	vtcount <= 0;
end

always @(posedge CLK_24M) begin
	if (hzcount < 799) begin
		hzcount <= hzcount + 1'b1;
		enVcnt <= 0;
	end
	else begin
		hzcount <= 0;
		enVcnt <= 1;
	end

	if (enVcnt == 1'b1) begin
		if (vtcount < 524) begin
			vtcount <= vtcount + 1'b1;
		end
		else begin
			vtcount <= 0;
		end
	end

	if (hzcount < 639 && vtcount < 479) begin
		RED <= vtcount[(hzcount >> 6) % 11];
	end
	else begin
		RED <= 0;
		GRN <= 0;
		BLU <= 0;
	end
end

assign VGA_RGB[0] = RED;
assign VGA_RGB[1] = GRN;
assign VGA_RGB[2] = BLU;
assign HSYNC = (hzcount > 655 && hzcount < 751) ? 1'b1 : 1'b0;
assign VSYNC = (vtcount > 489 && vtcount < 491) ? 1'b1 : 1'b0;

endmodule

sva:
module top_sva(
    input logic CLK_24M,
    input logic USR_BTN,
    input logic [2:0] VGA_RGB,
    input logic HSYNC,
    input logic VSYNC,
    input logic enVcnt,
    input logic [10:0] hzcount,
    input logic [10:0] vtcount,
    input logic RED,
    input logic BLU,
    input logic GRN
);

    // Initial state sets the counters and vertical enable low.
    check_initial_state: assert property (
        @(posedge CLK_24M)
        $initstate |-> (enVcnt == 1'b0 && hzcount == 11'd0 && vtcount == 11'd0)
    );

    // Horizontal counter increments and keeps vertical enable low before 799.
    check_hzcount_increment: assert property (
        @(posedge CLK_24M)
        (hzcount < 11'd799) |=> (hzcount == $past(hzcount) + 11'd1 && enVcnt == 1'b0)
    );

    // Horizontal counter wraps and pulses vertical enable at 799 or above.
    check_hzcount_wrap: assert property (
        @(posedge CLK_24M)
        (hzcount >= 11'd799) |=> (hzcount == 11'd0 && enVcnt == 1'b1)
    );

    // Vertical counter holds when the enable pulse is low.
    check_vtcount_hold: assert property (
        @(posedge CLK_24M)
        (!enVcnt) |=> (vtcount == $past(vtcount))
    );

    // Vertical counter increments when enabled and below 524.
    check_vtcount_increment: assert property (
        @(posedge CLK_24M)
        (enVcnt && vtcount < 11'd524) |=> (vtcount == $past(vtcount) + 11'd1)
    );

    // Vertical counter wraps when enabled at 524 or above.
    check_vtcount_wrap: assert property (
        @(posedge CLK_24M)
        (enVcnt && vtcount >= 11'd524) |=> (vtcount == 11'd0)
    );

    // VGA output bus mirrors the internal color registers.
    check_vga_rgb_mapping: assert property (
        @(posedge CLK_24M)
        (VGA_RGB[0] === RED) && (VGA_RGB[1] === GRN) && (VGA_RGB[2] === BLU)
    );

    // HSYNC matches the horizontal sync decode window.
    check_hsync_decode: assert property (
        @(posedge CLK_24M)
        HSYNC == ((hzcount > 11'd655) && (hzcount < 11'd751))
    );

    // VSYNC matches the vertical sync decode window.
    check_vsync_decode: assert property (
        @(posedge CLK_24M)
        VSYNC == ((vtcount > 11'd489) && (vtcount < 11'd491))
    );

    // Outside the active area, all colors are driven low on the next cycle.
    check_blank_rgb_low: assert property (
        @(posedge CLK_24M)
        ((hzcount >= 11'd639) || (vtcount >= 11'd479)) |=> (RED == 1'b0 && GRN == 1'b0 && BLU == 1'b0)
    );

    // Inside the active area, RED updates from the selected vtcount bit.
    check_red_active_update: assert property (
        @(posedge CLK_24M)
        ((hzcount < 11'd639) && (vtcount < 11'd479)) |=> (RED == $past(vtcount[((hzcount >> 6) % 11)]))
    );

endmodule

rtl:
module dff_with_set_reset(q, qbar, clock, data, PREbar, CLRbar);
    input  clock, data, PREbar, CLRbar;
    output q, qbar;
    reg    q;

    always @(posedge clock) begin
        if (PREbar == 0) begin
            q <= 1'b1;
        end else if (CLRbar == 0) begin
            q <= 1'b0;
        end else begin
            q <= data;
        end
    end

    assign qbar = ~q;

endmodule

sva:
module dff_with_set_reset_sva (
    input logic q,
    input logic qbar,
    input logic clock,
    input logic data,
    input logic PREbar,
    input logic CLRbar
);

    // qbar is always the inverse of q.
    check_qbar_complement: assert property (
        @(posedge clock) disable iff (1'b0)
        qbar == ~q
    );

    // Active-low preset forces q high on the following sampled cycle.
    check_preset_updates_q: assert property (
        @(posedge clock) disable iff (1'b0)
        !$initstate && $past(PREbar == 1'b0) |-> q == 1'b1
    );

    // Active-low clear forces q low when preset was inactive.
    check_clear_updates_q: assert property (
        @(posedge clock) disable iff (1'b0)
        !$initstate && $past(PREbar == 1'b1 && CLRbar == 1'b0) |-> q == 1'b0
    );

    // With preset and clear inactive, q captures data.
    check_data_capture_q: assert property (
        @(posedge clock) disable iff (1'b0)
        !$initstate && $past(PREbar == 1'b1 && CLRbar == 1'b1) |-> q == $past(data)
    );

    // Preset has priority over clear when both are active low.
    check_preset_priority_over_clear: assert property (
        @(posedge clock) disable iff (1'b0)
        !$initstate && $past(PREbar == 1'b0 && CLRbar == 1'b0) |-> q == 1'b1
    );

    // A prior preset cycle drives qbar low.
    check_preset_updates_qbar: assert property (
        @(posedge clock) disable iff (1'b0)
        !$initstate && $past(PREbar == 1'b0) |-> qbar == 1'b0
    );

    // A prior clear cycle drives qbar high when preset was inactive.
    check_clear_updates_qbar: assert property (
        @(posedge clock) disable iff (1'b0)
        !$initstate && $past(PREbar == 1'b1 && CLRbar == 1'b0) |-> qbar == 1'b1
    );

endmodule

rtl:
module two_to_one_mux(
    input A1_N,
    input A2_N,
    input B1,
    input B2,
    output reg Y
);

always @(*) begin
    if (A1_N == 0 && A2_N == 0) begin
        Y <= B1;
    end else if (A1_N == 0 && A2_N == 1) begin
        Y <= B2;
    end else if (A1_N == 1 && A2_N == 0) begin
        Y <= B1;
    end else if (A1_N == 1 && A2_N == 1) begin
        Y <= B2;
    end
end

endmodule

sva:
module two_to_one_mux_sva (
    input logic clk,
    input logic A1_N,
    input logic A2_N,
    input logic B1,
    input logic B2,
    input logic Y
);

    // A1_N=0 and A2_N=0 routes B1 to Y.
    check_case_00_routes_b1: assert property (
        @(posedge clk) ((A1_N == 1'b0) && (A2_N == 1'b0)) |-> (Y == B1)
    );

    // A1_N=0 and A2_N=1 routes B2 to Y.
    check_case_01_routes_b2: assert property (
        @(posedge clk) ((A1_N == 1'b0) && (A2_N == 1'b1)) |-> (Y == B2)
    );

    // A1_N=1 and A2_N=0 routes B1 to Y.
    check_case_10_routes_b1: assert property (
        @(posedge clk) ((A1_N == 1'b1) && (A2_N == 1'b0)) |-> (Y == B1)
    );

    // A1_N=1 and A2_N=1 routes B2 to Y.
    check_case_11_routes_b2: assert property (
        @(posedge clk) ((A1_N == 1'b1) && (A2_N == 1'b1)) |-> (Y == B2)
    );

    // With A2_N low, changing A1_N alone does not change Y.
    check_a1_irrelevant_when_a2_low: assert property (
        @(posedge clk) ($stable(A2_N) && (A2_N == 1'b0) && $changed(A1_N) && $stable(B1)) |-> $stable(Y)
    );

    // With A2_N high, changing A1_N alone does not change Y.
    check_a1_irrelevant_when_a2_high: assert property (
        @(posedge clk) ($stable(A2_N) && (A2_N == 1'b1) && $changed(A1_N) && $stable(B2)) |-> $stable(Y)
    );

endmodule

