sva:
module sky130_fd_sc_lp__nand3b_sva (
    input logic clk,
    input logic Y,
    input logic A_N,
    input logic B,
    input logic C
);

    // Combinational DUT sampled on an external formal clock.

    // Y matches the implemented NOT-then-NAND function.
    check_output_function: assert property (
        @(posedge clk) (Y == ~(B & ~A_N & C))
    );

    // A_N high forces the inverted NAND input low, so Y must be high.
    check_a_n_high_forces_y_high: assert property (
        @(posedge clk) (A_N == 1'b1) |-> (Y == 1'b1)
    );

    // B low forces the NAND output high.
    check_b_low_forces_y_high: assert property (
        @(posedge clk) (B == 1'b0) |-> (Y == 1'b1)
    );

    // C low forces the NAND output high.
    check_c_low_forces_y_high: assert property (
        @(posedge clk) (C == 1'b0) |-> (Y == 1'b1)
    );

    // The only way Y can be low is with A_N low, B high, and C high.
    check_y_low_only_for_active_input_combo: assert property (
        @(posedge clk) (Y == 1'b0) |-> ((A_N == 1'b0) && (B == 1'b1) && (C == 1'b1))
    );

    // With A_N low and both B and C high, Y must be low.
    check_active_input_combo_drives_y_low: assert property (
        @(posedge clk) ((A_N == 1'b0) && (B == 1'b1) && (C == 1'b1)) |-> (Y == 1'b0)
    );

endmodule

module sky130_fd_sc_hdll__or2_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB,
    input logic X
);

    // X must equal the implemented combinational expression.
    check_x_matches_rtl_expr: assert property (
        @(posedge clk)
        (X == (VPWR | (VPB & !VPWR) | (VNB & !VPB & !VPWR) | (VGND & !VNB & !VPB & !VPWR)))
    );

    // VPWR asserted drives X high.
    check_vpwr_forces_x_high: assert property (
        @(posedge clk)
        (VPWR) |-> (X)
    );

    // VPB asserted with VPWR low drives X high.
    check_vpb_forces_x_high_when_vpwr_low: assert property (
        @(posedge clk)
        (!VPWR && VPB) |-> (X)
    );

    // VNB asserted with VPWR and VPB low drives X high.
    check_vnb_forces_x_high_when_vpwr_vpb_low: assert property (
        @(posedge clk)
        (!VPWR && !VPB && VNB) |-> (X)
    );

    // VGND asserted with higher-priority pins low drives X high.
    check_vgnd_forces_x_high_when_others_low: assert property (
        @(posedge clk)
        (!VPWR && !VPB && !VNB && VGND) |-> (X)
    );

    // All power-related inputs low drives X low.
    check_all_power_low_forces_x_low: assert property (
        @(posedge clk)
        (!VPWR && !VPB && !VNB && !VGND) |-> (!X)
    );

    // Stable power pins keep X stable across samples.
    check_power_stable_keeps_x_stable: assert property (
        @(posedge clk)
        (!$initstate && $stable({VPWR, VPB, VNB, VGND})) |-> $stable(X)
    );

    // A or B changes do not affect X when power pins are stable.
    check_ab_change_does_not_affect_x: assert property (
        @(posedge clk)
        (!$initstate && $stable({VPWR, VPB, VNB, VGND}) && ($changed(A) || $changed(B))) |-> $stable(X)
    );

endmodule

