module sky130_fd_sc_hs__tapvgnd2_sva (
    input logic VPWR,
    input logic VGND,
    input logic tap,
    input logic tap_bar
);

    // No explicit clock or reset; sample this combinational cell on the formal global clock.

    // tap follows VGND when the supplies are known and complementary.
    check_tap_matches_vgnd_with_complementary_supplies: assert property (
        @($global_clock) disable iff (1'b0)
        (((VPWR === 1'b1) && (VGND === 1'b0)) ||
         ((VPWR === 1'b0) && (VGND === 1'b1)))
        |-> (tap === VGND)
    );

    // tap_bar follows VPWR when the supplies are known and complementary.
    check_tap_bar_matches_vpwr_with_complementary_supplies: assert property (
        @($global_clock) disable iff (1'b0)
        (((VPWR === 1'b1) && (VGND === 1'b0)) ||
         ((VPWR === 1'b0) && (VGND === 1'b1)))
        |-> (tap_bar === VPWR)
    );

    // tap and tap_bar are complements when the supplies are known and complementary.
    check_outputs_are_complements_with_complementary_supplies: assert property (
        @($global_clock) disable iff (1'b0)
        (((VPWR === 1'b1) && (VGND === 1'b0)) ||
         ((VPWR === 1'b0) && (VGND === 1'b1)))
        |-> (tap_bar === ~tap)
    );

    // With VPWR high and VGND low, tap must be low.
    check_tap_low_when_vpwr_high_and_vgnd_low: assert property (
        @($global_clock) disable iff (1'b0)
        ((VPWR === 1'b1) && (VGND === 1'b0))
        |-> (tap === 1'b0)
    );

    // With VPWR high and VGND low, tap_bar must be high.
    check_tap_bar_high_when_vpwr_high_and_vgnd_low: assert property (
        @($global_clock) disable iff (1'b0)
        ((VPWR === 1'b1) && (VGND === 1'b0))
        |-> (tap_bar === 1'b1)
    );

    // With VPWR low and VGND high, tap must be high.
    check_tap_high_when_vpwr_low_and_vgnd_high: assert property (
        @($global_clock) disable iff (1'b0)
        ((VPWR === 1'b0) && (VGND === 1'b1))
        |-> (tap === 1'b1)
    );

    // With VPWR low and VGND high, tap_bar must be low.
    check_tap_bar_low_when_vpwr_low_and_vgnd_high: assert property (
        @($global_clock) disable iff (1'b0)
        ((VPWR === 1'b0) && (VGND === 1'b1))
        |-> (tap_bar === 1'b0)
    );

endmodule

rtl:
module signal_converter (
    Y,
    VOUT,
    VREF,
    A1,
    A2,
    B1,
    B2,
    VPWR,
    VGND,
    VPB,
    VNB
);

    output reg [1:0] Y;
    output reg VOUT;
    output reg VREF;
    input A1;
    input A2;
    input B1;
    input B2;
    input VPWR;
    input VGND;
    input VPB;
    input VNB;

    always @* begin
        case ({A1, A2, B1, B2})
            4'b0000: Y = 2'b00;
            4'b0001: Y = 2'b01;
            4'b0010: Y = 2'b10;
            4'b0011: Y = 2'b11;
            4'b0100: Y = 2'b00;
            4'b0101: Y = 2'b01;
            4'b0110: Y = 2'b10;
            4'b0111: Y = 2'b11;
            4'b1000: Y = 2'b00;
            4'b1001: Y = 2'b01;
            4'b1010: Y = 2'b10;
            4'b1011: Y = 2'b11;
            4'b1100: Y = 2'b00;
            4'b1101: Y = 2'b01;
            4'b1110: Y = 2'b10;
            4'b1111: Y = 2'b11;
        endcase
    end

    always @* begin
        if (Y % 2 == 0)
            VOUT = VPWR;
        else
            VOUT = VGND;
    end

    always @* begin
        if (Y < 2)
            VREF = VPB;
        else
            VREF = VNB;
    end

endmodule

sva:
module signal_converter_sva (
    input logic clk,
    input logic [1:0] Y,
    input logic VOUT,
    input logic VREF,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic B2,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB
);

    // Y ignores A1/A2 and matches the B inputs.
    check_y_matches_b_inputs: assert property (
        @(posedge clk) Y == {B1, B2}
    );

    // VOUT selects VPWR for even Y and VGND for odd Y.
    check_vout_follows_y_lsb: assert property (
        @(posedge clk) VOUT == (Y[0] ? VGND : VPWR)
    );

    // VREF selects VPB for Y below 2 and VNB otherwise.
    check_vref_follows_y_msb: assert property (
        @(posedge clk) VREF == (Y[1] ? VNB : VPB)
    );

    // VOUT is ultimately controlled by B2 through Y.
    check_vout_matches_b2: assert property (
        @(posedge clk) VOUT == (B2 ? VGND : VPWR)
    );

    // VREF is ultimately controlled by B1 through Y.
    check_vref_matches_b1: assert property (
        @(posedge clk) VREF == (B1 ? VNB : VPB)
    );

endmodule

