module soc_system_jtag_uart_sim_scfifo_w (
  // inputs:
  clk,
  fifo_wdata,
  fifo_wr,

  // outputs:
  fifo_FF,
  r_dat,
  wfifo_empty,
  wfifo_used
);

  output fifo_FF;
  output [7:0] r_dat;
  output wfifo_empty;
  output [5:0] wfifo_used;
  input clk;
  input [7:0] fifo_wdata;
  input fifo_wr;

  wire fifo_FF;
  wire [7:0] r_dat;
  wire wfifo_empty;
  wire [5:0] wfifo_used;

  // Simulation-only contents
  integer write_cnt = 0;
  initial begin
    `ifdef SIM_TIME
      $display("%d: soc_system_jtag_uart_sim_scfifo_w", $time);
    `endif
  end

  always @(posedge clk) begin
    if (fifo_wr) begin
      `ifdef SIM_TIME
        $write("%c", fifo_wdata);
      `endif
      write_cnt = write_cnt + 1;
    end
  end

  assign wfifo_used = write_cnt; // only write, no read, used is the same as write count
  assign r_dat = 8'h00;
  assign fifo_FF = 1'b0;
  assign wfifo_empty = (write_cnt == 0);

endmodule

sva:
module soc_system_jtag_uart_sim_scfifo_w_sva (
    input logic        clk,
    input logic [7:0]  fifo_wdata,
    input logic        fifo_wr,
    input logic        fifo_FF,
    input logic [7:0]  r_dat,
    input logic        wfifo_empty,
    input logic [5:0]  wfifo_used
);

    // Read data is tied to zero.
    check_r_dat_zero: assert property (
        @(posedge clk) r_dat == 8'h00
    );

    // Full flag is tied low.
    check_fifo_ff_zero: assert property (
        @(posedge clk) fifo_FF == 1'b0
    );

    // Empty implies the visible used count is zero.
    check_empty_implies_zero_used: assert property (
        @(posedge clk) wfifo_empty |-> (wfifo_used == 6'd0)
    );

    // Without a write, the used count holds its value.
    check_used_holds_without_write: assert property (
        @(posedge clk) !fifo_wr |=> (wfifo_used == $past(wfifo_used))
    );

    // A write increments the used count modulo 64.
    check_used_increments_on_write: assert property (
        @(posedge clk) fifo_wr |=> (wfifo_used == ($past(wfifo_used) + 6'd1))
    );

    // Once non-empty, it stays non-empty.
    check_nonempty_sticky: assert property (
        @(posedge clk) !wfifo_empty |=> !wfifo_empty
    );

    // Empty remains asserted if no write occurs.
    check_empty_holds_without_write: assert property (
        @(posedge clk) (wfifo_empty && !fifo_wr) |=> wfifo_empty
    );

    // A write from empty makes the FIFO non-empty.
    check_write_from_empty_clears_empty: assert property (
        @(posedge clk) (wfifo_empty && fifo_wr) |=> !wfifo_empty
    );

    // A write from empty sets the used count to one.
    check_write_from_empty_sets_used_one: assert property (
        @(posedge clk) (wfifo_empty && fifo_wr) |=> (wfifo_used == 6'd1)
    );

endmodule

module twos_complement_sva (
    input logic [3:0] data_in,
    input logic       reset,
    input logic [3:0] data_out
);

    // Reset forces the output to zero.
    check_reset_forces_zero: assert property (
        @($global_clock) reset |-> (data_out == 4'b0000)
    );

    // Outside reset, output is the 4-bit two's complement of input.
    check_twos_complement_value: assert property (
        @($global_clock) disable iff (reset)
        (data_out == ((~data_in) + 4'd1))
    );

    // Zero remains zero after two's complement.
    check_zero_maps_to_zero: assert property (
        @($global_clock) disable iff (reset)
        (data_in == 4'b0000) |-> (data_out == 4'b0000)
    );

    // 4'b1000 is self-negating in 4-bit two's complement.
    check_msb_only_maps_to_self: assert property (
        @($global_clock) disable iff (reset)
        (data_in == 4'b1000) |-> (data_out == 4'b1000)
    );

    // Negating the output returns the original input.
    check_inverse_relation: assert property (
        @($global_clock) disable iff (reset)
        (((~data_out) + 4'd1) == data_in)
    );

    // With stable input and reset low, output stays stable.
    check_stable_input_holds_output: assert property (
        @($global_clock) disable iff (reset)
        ($stable(data_in) && $stable(reset)) |-> $stable(data_out)
    );

    // Input value 1 maps to 4'b1111.
    check_one_maps_to_minus_one: assert property (
        @($global_clock) disable iff (reset)
        (data_in == 4'b0001) |-> (data_out == 4'b1111)
    );

    // Input value 4'b1111 maps to 1.
    check_minus_one_maps_to_one: assert property (
        @($global_clock) disable iff (reset)
        (data_in == 4'b1111) |-> (data_out == 4'b0001)
    );

endmodule

rtl:
module up_down_counter (
    input CLK,
    input LOAD,
    input UP,
    input DOWN,
    output reg [3:0] Q
);

always @(posedge CLK) begin
    if (LOAD) begin
        Q <= 4'b0000;
    end else if (UP) begin
        Q <= (Q == 4'b1111) ? 4'b0000 : Q + 1;
    end else if (DOWN) begin
        Q <= (Q == 4'b0000) ? 4'b1111 : Q - 1;
    end
end

endmodule

module decoder (
    input [1:0] A,
    output reg [15:0] Y
);

always @* begin
    case ({A})
        2'b00: Y = 16'b0000000000000001;
        2'b01: Y = 16'b0000000000000010;
        2'b10: Y = 16'b0000000000000100;
        2'b11: Y = 16'b0000000000001000;
    endcase
end

endmodule

module and_gate (
    input [15:0] Y,
    input [3:0] Q,
    output reg [15:0] AND_output
);

always @* begin
    AND_output = Y & Q;
end

endmodule

module top_module (
    input CLK,
    input LOAD,
    input UP,
    input DOWN,
    output [15:0] Y
);

wire [3:0] Q;
wire [15:0] AND_output;

up_down_counter counter (
    .CLK(CLK),
    .LOAD(LOAD),
    .UP(UP),
    .DOWN(DOWN),
    .Q(Q)
);

decoder decoder (
    .A(Q[1:0]),
    .Y(Y)
);

and_gate and_gate (
    .Y(Y),
    .Q(Q),
    .AND_output(AND_output)
);

endmodule

sva:
module top_module_sva (
    input logic        CLK,
    input logic        LOAD,
    input logic        UP,
    input logic        DOWN,
    input logic [15:0] Y,
    input logic [3:0]  Q,
    input logic [15:0] AND_output
);

    // LOAD clears the counter on the next clock.
    check_load_clears_q: assert property (
        @(posedge CLK) LOAD |=> (Q == 4'b0000)
    );

    // With LOAD low, UP increments Q and has priority over DOWN.
    check_up_increments_q: assert property (
        @(posedge CLK) (!LOAD && UP && (Q != 4'hF)) |=> (Q == ($past(Q) + 4'h1))
    );

    // With LOAD low, UP wraps Q from 15 back to 0.
    check_up_wraps_q: assert property (
        @(posedge CLK) (!LOAD && UP && (Q == 4'hF)) |=> (Q == 4'h0)
    );

    // With LOAD and UP low, DOWN decrements Q.
    check_down_decrements_q: assert property (
        @(posedge CLK) (!LOAD && !UP && DOWN && (Q != 4'h0)) |=> (Q == ($past(Q) - 4'h1))
    );

    // With LOAD and UP low, DOWN wraps Q from 0 to 15.
    check_down_wraps_q: assert property (
        @(posedge CLK) (!LOAD && !UP && DOWN && (Q == 4'h0)) |=> (Q == 4'hF)
    );

    // With no control asserted, Q holds its value.
    check_q_holds_without_controls: assert property (
        @(posedge CLK) (!LOAD && !UP && !DOWN) |=> (Q == $past(Q))
    );

    // Y decodes Q[1:0] into a one-hot 16-bit value.
    check_decoder_matches_q: assert property (
        @(posedge CLK) Y == (16'h0001 << Q[1:0])
    );

    // AND_output is Y AND zero-extended Q.
    check_and_output_relation: assert property (
        @(posedge CLK) AND_output == (Y & {12'h000, Q})
    );

endmodule

module comparator_sva #(
    parameter int n = 4
) (
    input logic         clk,
    input logic [n-1:0] in1,
    input logic [n-1:0] in2,
    input logic [1:0]   comp
);

    // comp is 01 when in1 is less than in2.
    check_less_than_encoding: assert property (
        @(posedge clk) (in1 < in2) |-> (comp == 2'b01)
    );

    // comp is 10 when in1 equals in2.
    check_equal_encoding: assert property (
        @(posedge clk) (in1 == in2) |-> (comp == 2'b10)
    );

    // comp is 10 when in1 is greater than in2.
    check_greater_than_encoding: assert property (
        @(posedge clk) (in1 > in2) |-> (comp == 2'b10)
    );

    // 01 only appears for the less-than case.
    check_01_implies_less_than: assert property (
        @(posedge clk) (comp == 2'b01) |-> (in1 < in2)
    );

    // 10 only appears when in1 is not less than in2.
    check_10_implies_not_less_than: assert property (
        @(posedge clk) (comp == 2'b10) |-> (in1 >= in2)
    );

    // comp never drives 00.
    check_comp_not_00: assert property (
        @(posedge clk) (comp != 2'b00)
    );

    // comp never drives 11.
    check_comp_not_11: assert property (
        @(posedge clk) (comp != 2'b11)
    );

    // comp matches the implemented comparator function.
    check_comp_function: assert property (
        @(posedge clk) comp == ((in1 < in2) ? 2'b01 : 2'b10)
    );

endmodule

rtl:
module binary_adder (
    input [3:0] a,
    input [3:0] b,
    output reg [3:0] sum
);

always @(*) begin
    sum = a + b;
    if (sum > 15) begin
        sum = sum & 4'b1111;
    end
end

endmodule

sva:
module binary_adder_sva (
    input logic clk,
    input logic [3:0] a,
    input logic [3:0] b,
    input logic [3:0] sum
);

    // Sum is the low 4 bits of the full addition.
    check_sum_matches_low_nibble: assert property (
        @(posedge clk) {1'b0, sum} == (({1'b0, a} + {1'b0, b}) & 5'h0f)
    );

    // When there is no overflow, sum matches the full result.
    check_sum_no_overflow: assert property (
        @(posedge clk) (({1'b0, a} + {1'b0, b}) <= 5'd15) |-> ({1'b0, sum} == ({1'b0, a} + {1'b0, b}))
    );

    // When there is overflow, sum wraps modulo 16.
    check_sum_wraps_on_overflow: assert property (
        @(posedge clk) (({1'b0, a} + {1'b0, b}) > 5'd15) |-> ({1'b0, sum} == (({1'b0, a} + {1'b0, b}) - 5'd16))
    );

    // Adding zero on a leaves b unchanged.
    check_zero_a_identity: assert property (
        @(posedge clk) (a == 4'd0) |-> (sum == b)
    );

    // Adding zero on b leaves a unchanged.
    check_zero_b_identity: assert property (
        @(posedge clk) (b == 4'd0) |-> (sum == a)
    );

    // The least significant sum bit is the XOR of operand LSBs.
    check_lsb_xor: assert property (
        @(posedge clk) sum[0] == (a[0] ^ b[0])
    );

endmodule

