module sky130_fd_sc_ls__o41ai_sva (
    input logic clk,
    input logic Y,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic A4,
    input logic B1
);

    // Combinational DUT; clk is an external sampling clock and no reset exists.

    // Y must match the implemented OAI/NAND logic.
    check_boolean_function: assert property (
