    );

    // When all A inputs are low, the OR term is low and Y stays high.
    check_all_a_low_forces_y_high: assert property (
        @(posedge clk) (!A1 && !A2 && !A3 && !A4) |-> (Y == 1'b1)
    );

    // A high B1 with any high A input forces Y low.
    check_b1_and_any_a_force_y_low: assert property (
        @(posedge clk) (B1 && (A1 || A2 || A3 || A4)) |-> (Y == 1'b0)
    );

    // A low Y requires B1 to be high.
    check_y_low_requires_b1_high: assert property (
        @(posedge clk) (Y == 1'b0) |-> (B1 == 1'b1)
    );

    // A low Y requires at least one A input to be high.
    check_y_low_requires_any_a_high: assert property (
        @(posedge clk) (Y == 1'b0) |-> (A1 || A2 || A3 || A4)
    );

endmodule

rtl:
module binary_counter(
    input clk,
    input rst,
    output reg [3:0] count
);

always @(posedge clk) begin
    if (rst) begin
        count <= 0;
    end else if (count == 15) begin
        count <= 0;
    end else begin
        count <= count + 1;
    end
end

endmodule

sva:
module binary_counter_sva(
    input logic clk,
    input logic rst,
    input logic [3:0] count
);

    // A reset cycle clears the counter for the following sampled cycle.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |=> (count == 4'd0)
    );

    // The first non-reset cycle after reset still observes count at zero.
    check_reset_release_shows_zero: assert property (
        @(posedge clk) disable iff (rst) (($past(rst) === 1'b1)) |-> (count == 4'd0)
    );

    // When below 15 and not in reset, the counter increments by one.
    check_increment_when_below_max: assert property (
        @(posedge clk) disable iff (rst) (count < 4'd15) |=> (count == ($past(count) + 4'd1))
    );

    // When at 15 and not in reset, the counter wraps to zero.
    check_wrap_from_max_to_zero: assert property (
        @(posedge clk) disable iff (rst) (count == 4'd15) |=> (count == 4'd0)
    );

endmodule

rtl:
module adder(
    input [7:0] A,
    input [7:0] B,
    output reg [7:0] Y
);

always @(*) begin
    if (A + B > 255) begin
        Y <= 255;
    end else begin
        Y <= A + B;
    end
end

endmodule

sva:
module adder_sva (
    input logic clk,
    input logic [7:0] A,
    input logic [7:0] B,
    input logic [7:0] Y
);

    // DUT has no native clock or reset; clk is a formal sampling clock.

    // Y matches the RTL's 8-bit addition expression.
    check_output_matches_truncated_sum: assert property (
        @(posedge clk) Y == (A + B)
    );

    // Without 9-bit overflow, Y equals the exact mathematical sum.
    check_exact_sum_without_overflow: assert property (
        @(posedge clk)
        (({1'b0, A} + {1'b0, B}) <= 9'd255)
        |-> (Y == (({1'b0, A} + {1'b0, B})[7:0]))
    );

    // With 9-bit overflow, Y keeps only the low 8 bits.
    check_low_byte_on_overflow: assert property (
        @(posedge clk)
        (({1'b0, A} + {1'b0, B}) > 9'd255)
        |-> (Y == (({1'b0, A} + {1'b0, B})[7:0]))
    );

    // Overflow does not clamp Y to 8'hFF.
    check_no_clamp_on_overflow: assert property (
        @(posedge clk)
        (({1'b0, A} + {1'b0, B}) > 9'd255)
        |-> (Y != 8'hFF)
    );

endmodule

rtl:
module init(input wire clk, output ini);

reg ini = 0;

always @(posedge(clk))
  ini <= 1;

endmodule

sva:
module init_sva (
    input logic clk,
    input logic ini
);

    // ini starts low before the first clocked update.
    check_ini_initial_low: assert property (
        @(posedge clk) $initstate |-> (ini == 1'b0)
    );

    // If ini is low at a clock edge, it is high on the next clock edge.
    check_ini_low_becomes_high: assert property (
        @(posedge clk) (ini == 1'b0) |=> (ini == 1'b1)
    );

    // Once ini is high, it remains high on later clock edges.
    check_ini_stays_high: assert property (
        @(posedge clk) (ini == 1'b1) |=> (ini == 1'b1)
    );

endmodule

rtl:
module multiplier_2x2 (
    input [1:0] A,
    input [1:0] B,
    output reg [3:0] P,
    output reg [3:0] Q
);

    always @(*) begin
        P = A * B[0];
        Q = A * B[1];
    end

endmodule

sva:
module multiplier_2x2_sva (
    input logic clk,
    input logic [1:0] A,
    input logic [1:0] B,
    input logic [3:0] P,
    input logic [3:0] Q
);

    // P is A gated by B[0], zero-extended to 4 bits.
    check_p_matches_b0_product: assert property (
        @(posedge clk) P == {2'b00, (A & {2{B[0]}})}
    );

    // Q is A gated by B[1], zero-extended to 4 bits.
    check_q_matches_b1_product: assert property (
        @(posedge clk) Q == {2'b00, (A & {2{B[1]}})}
    );

    // P stays unchanged when A and B[0] stay unchanged.
    check_p_stable_when_a_and_b0_stable: assert property (
        @(posedge clk) ($stable(A) && $stable(B[0])) |-> $stable(P)
    );

    // Q stays unchanged when A and B[1] stay unchanged.
    check_q_stable_when_a_and_b1_stable: assert property (
        @(posedge clk) ($stable(A) && $stable(B[1])) |-> $stable(Q)
    );

endmodule

rtl:
module debounce_switch  #(
    parameter WIDTH=1, // width of the input and output signals
    parameter N=3, // length of shift register
    parameter RATE=125000 // clock division factor
)(
    input wire clk,
    input wire rst,
    input wire [WIDTH-1:0] in,
    output wire [WIDTH-1:0] out
);

reg [23:0] cnt_reg = 24'd0;

reg [N-1:0] debounce_reg[WIDTH-1:0];

reg [WIDTH-1:0] state;


assign out = state;

integer k;

always @(posedge clk) begin
    if (rst) begin
        cnt_reg <= 0;
        state <= 0;

        for (k = 0; k < WIDTH; k = k + 1) begin
            debounce_reg[k] <= 0;
        end
    end else begin
        if (cnt_reg < RATE) begin
            cnt_reg <= cnt_reg + 24'd1;
        end else begin
            cnt_reg <= 24'd0;
        end

        if (cnt_reg == 24'd0) begin
            for (k = 0; k < WIDTH; k = k + 1) begin
                debounce_reg[k] <= {debounce_reg[k][N-2:0], in[k]};
            end
        end

        for (k = 0; k < WIDTH; k = k + 1) begin
            if (|debounce_reg[k] == 0) begin
                state[k] <= 0;
            end else if (&debounce_reg[k] == 1) begin
                state[k] <= 1;
            end else begin
                state[k] <= state[k];
            end
        end
    end
end

endmodule

sva:
module debounce_switch_sva #(
    parameter int WIDTH = 1,
    parameter int N = 3,
    parameter int RATE = 125000
)(
    input logic clk,
    input logic rst,
    input logic [WIDTH-1:0] in,
    input logic [WIDTH-1:0] out,
    input logic [23:0] cnt_reg,
    input logic [N-1:0] debounce_reg [WIDTH-1:0],
    input logic [WIDTH-1:0] state
);

    // Reset clears the counter, state, and output on the next clock.
    check_reset_clears_main_regs: assert property (
        @(posedge clk) rst |=> (cnt_reg == 24'd0) && (state == {WIDTH{1'b0}}) && (out == {WIDTH{1'b0}})
    );

    // The counter increments while it is below RATE.
    check_counter_increments: assert property (
        @(posedge clk) disable iff (rst)
        (cnt_reg < RATE) |=> (cnt_reg == $past(cnt_reg) + 24'd1)
    );

    // The counter wraps to zero when it is not below RATE.
    check_counter_wraps_to_zero: assert property (
        @(posedge clk) disable iff (rst)
        (!(cnt_reg < RATE)) |=> (cnt_reg == 24'd0)
    );

    // The output always mirrors the internal state register.
    check_output_matches_state: assert property (
        @(posedge clk) disable iff (rst)
        (out == state)
    );

    genvar i;
    generate
        for (i = 0; i < WIDTH; i = i + 1) begin : gen_bit_asserts

            // Reset clears each debounce shift register.
            check_reset_clears_debounce: assert property (
                @(posedge clk) rst |=> (debounce_reg[i] == {N{1'b0}})
            );

            // A sample is shifted in only when the counter is zero.
            check_debounce_shifts_on_sample: assert property (
                @(posedge clk) disable iff (rst)
                (cnt_reg == 24'd0) |=> (debounce_reg[i] == {$past(debounce_reg[i][N-2:0]), $past(in[i])})
            );

            // The debounce shift register holds between sample points.
            check_debounce_holds_between_samples: assert property (
                @(posedge clk) disable iff (rst)
                (cnt_reg != 24'd0) |=> (debounce_reg[i] == $past(debounce_reg[i]))
            );

            // State clears when the sampled history is all zeros.
            check_state_clears_on_all_zero_history: assert property (
                @(posedge clk) disable iff (rst)
                (debounce_reg[i] == {N{1'b0}}) |=> (state[i] == 1'b0)
            );

            // State sets when the sampled history is all ones.
            check_state_sets_on_all_one_history: assert property (
                @(posedge clk) disable iff (rst)
                (debounce_reg[i] == {N{1'b1}}) |=> (state[i] == 1'b1)
            );

            // State holds when the sampled history is mixed.
            check_state_holds_on_mixed_history: assert property (
                @(posedge clk) disable iff (rst)
                ((debounce_reg[i] != {N{1'b0}}) && (debounce_reg[i] != {N{1'b1}})) |=> (state[i] == $past(state[i]))
            );

        end
    endgenerate

endmodule

module dff_ras_sva (
    input logic clk,
    input logic reset,
    input logic set,
    input logic d,
    input logic q
);

    // Reset drives q low.
    check_reset_clears_q: assert property (
        @(posedge clk) reset |=> (q == 1'b0)
    );

    // Reset has priority over set.
    check_reset_priority_over_set: assert property (
        @(posedge clk) (reset && set) |=> (q == 1'b0)
    );

    // Set drives q high when reset is low.
    check_set_drives_q_high: assert property (
        @(posedge clk) disable iff (reset) set |=> (q == 1'b1)
    );

    // Set overrides d when d is low.
    check_set_priority_over_d_low: assert property (
        @(posedge clk) disable iff (reset) (set && (d == 1'b0)) |=> (q == 1'b1)
    );

    // q captures d=1 when reset and set are low.
    check_data_capture_one: assert property (
        @(posedge clk) disable iff (reset) (!set && (d == 1'b1)) |=> (q == 1'b1)
    );

    // q captures d=0 when reset and set are low.
    check_data_capture_zero: assert property (
        @(posedge clk) disable iff (reset) (!set && (d == 1'b0)) |=> (q == 1'b0)
    );

endmodule

rtl:
module mux(opA,opB,sum,dsp_sel,out);
	input [3:0] opA,opB;
	input [4:0] sum;
	input [1:0] dsp_sel;
	output [3:0] out;

	reg cout;

	always @ (sum)
		begin
			if (sum[4] == 1)
				cout <= 4'b0001;
			else
				cout <= 4'b0000;
		end

	reg out;

	always @(dsp_sel,sum,cout,opB,opA)
		begin
			if (dsp_sel == 2'b00)
				out <= sum[3:0];
			else if (dsp_sel == 2'b01)
				out <= cout;
			else if (dsp_sel == 2'b10)
				out <= opB;
			else if (dsp_sel == 2'b11)
				out <= opA;
		end

endmodule

sva:
module mux_assertions (
    input logic [3:0] opA,
    input logic [3:0] opB,
    input logic [4:0] sum,
    input logic [1:0] dsp_sel,
    input logic [3:0] out
);

    // No reset is present in this RTL.

    // When dsp_sel selects sum, out matches sum[3:0].
    check_select_sum: assert property (
        @($global_clock) (dsp_sel == 2'b00) |-> (out == sum[3:0])
    );

    // When dsp_sel selects cout, out[0] matches sum[4].
    check_select_cout_lsb: assert property (
        @($global_clock) (dsp_sel == 2'b01) |-> (out[0] == sum[4])
    );

    // When dsp_sel selects cout, the upper output bits are zero.
    check_select_cout_upper_zero: assert property (
        @($global_clock) (dsp_sel == 2'b01) |-> (out[3:1] == 3'b000)
    );

    // When dsp_sel selects opB, out matches opB.
    check_select_opb: assert property (
        @($global_clock) (dsp_sel == 2'b10) |-> (out == opB)
    );

    // When dsp_sel selects opA, out matches opA.
    check_select_opa: assert property (
        @($global_clock) (dsp_sel == 2'b11) |-> (out == opA)
    );

endmodule

rtl:
module adder_4bit(
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] S,
    output Cout
);

wire [3:0] C; // intermediate carry bits

// full-adder for each bit
full_adder FA0(.A(A[0]), .B(B[0]), .Cin(Cin), .S(S[0]), .C(C[0]));
full_adder FA1(.A(A[1]), .B(B[1]), .Cin(C[0]), .S(S[1]), .C(C[1]));
full_adder FA2(.A(A[2]), .B(B[2]), .Cin(C[1]), .S(S[2]), .C(C[2]));
full_adder FA3(.A(A[3]), .B(B[3]), .Cin(C[2]), .S(S[3]), .C(Cout));

endmodule

// full-adder module
module full_adder(
    input A,
    input B,
    input Cin,
    output S,
    output C
);

assign S = A ^ B ^ Cin;
assign C = (A & B) | (A & Cin) | (B & Cin);

endmodule

sva:
module adder_4bit_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic Cin,
    input logic [3:0] S,
    input logic Cout
);

    // The combined outputs must equal A + B + Cin.
    check_total_sum: assert property (
        @(posedge clk) {Cout, S} == ({1'b0, A} + {1'b0, B} + Cin)
    );

    // The least-significant sum bit must match the first full-adder XOR.
    check_lsb_sum: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0] ^ Cin)
    );

    // When A is zero, the result must be B plus Cin.
    check_zero_a_passthrough: assert property (
        @(posedge clk) (A == 4'h0) |-> ({Cout, S} == ({1'b0, B} + Cin))
    );

    // When B is zero, the result must be A plus Cin.
    check_zero_b_passthrough: assert property (
        @(posedge clk) (B == 4'h0) |-> ({Cout, S} == ({1'b0, A} + Cin))
    );

    // Complementary operands with no carry-in must sum to all ones.
    check_complementary_no_carryin: assert property (
        @(posedge clk) ((A == ~B) && !Cin) |-> ((S == 4'hF) && !Cout)
    );

    // Complementary operands with carry-in must wrap to zero with carry-out.
    check_complementary_with_carryin: assert property (
        @(posedge clk) ((A == ~B) && Cin) |-> ((S == 4'h0) && Cout)
    );

    // Maximum inputs with carry-in must produce 5'b1_1111.
    check_maximum_sum: assert property (
        @(posedge clk) ((A == 4'hF) && (B == 4'hF) && Cin) |-> ((S == 4'hF) && Cout)
    );

    // Zero operands must only propagate Cin into bit 0.
    check_all_zero_inputs: assert property (
        @(posedge clk) ((A == 4'h0) && (B == 4'h0)) |-> ((S == {3'b000, Cin}) && !Cout)
    );

    // An extended sum of 16 or more must assert carry-out.
    check_overflow_sets_cout: assert property (
        @(posedge clk) (({1'b0, A} + {1'b0, B} + Cin) >= 5'd16) |-> Cout
    );

    // An extended sum below 16 must deassert carry-out.
    check_no_overflow_clears_cout: assert property (
        @(posedge clk) (({1'b0, A} + {1'b0, B} + Cin) <= 5'd15) |-> !Cout
    );

endmodule

module dff_16_sva (
    input logic clk,
    input logic reset,
    input logic [15:0] d,
    input logic [15:0] q
);

    // Reset forces q low on the next sampled cycle.
    check_reset_clears_q: assert property (
        @(posedge clk) reset |=> (q == 16'h0000)
    );

    // When reset is low, q captures d from the previous rising edge.
    check_q_captures_d: assert property (
        @(posedge clk) disable iff (reset) 1'b1 |=> (q == $past(d))
    );

endmodule

rtl:
module por (
	input			clk,
	output	reg		rst
);

reg	[31:0]	counter;

always @(posedge clk) begin
	if (counter < 32'hffffff) begin
		rst <= 1;
		counter <= counter + 1;
	end
	else begin
		rst <= 0;
	end
end

endmodule

sva:
module por_sva (
    input logic        clk,
    input logic        rst,
    input logic [31:0] counter
);

    localparam [31:0] POR_MAX    = 32'h00ffffff;
    localparam [31:0] POR_PREMAX = 32'h00fffffe;

    // Below the terminal count, the counter increments by one.
    check_counter_increments_below_max: assert property (
        @(posedge clk) (counter < POR_MAX) |=> (counter == ($past(counter) + 32'd1))
    );

    // Below the terminal count, rst is asserted on the next cycle.
    check_rst_asserted_below_max: assert property (
        @(posedge clk) (counter < POR_MAX) |=> (rst == 1'b1)
    );

    // At or above the terminal count, the counter stops changing.
    check_counter_holds_at_or_above_max: assert property (
        @(posedge clk) (counter >= POR_MAX) |=> (counter == $past(counter))
    );

    // At or above the terminal count, rst deasserts on the next cycle.
    check_rst_deasserted_at_or_above_max: assert property (
        @(posedge clk) (counter >= POR_MAX) |=> (rst == 1'b0)
    );

    // The final increment reaches the terminal count with rst still high.
    check_transition_into_terminal_count: assert property (
        @(posedge clk) (counter == POR_PREMAX) |=> ((counter == POR_MAX) && (rst == 1'b1))
    );

    // Once sampled at the terminal count, the next cycle stays there with rst low.
    check_terminal_count_behavior: assert property (
        @(posedge clk) (counter == POR_MAX) |=> ((counter == POR_MAX) && (rst == 1'b0))
    );

endmodule

rtl:
module NAND2_CLR (
  input A,
  input B,
  input CLR,
  output Y,
  output Yn
);

  wire nand_out;

  assign nand_out = ~(A & B);

  assign Y = CLR ? 1'b0 : nand_out;
  assign Yn = CLR ? 1'b1 : ~nand_out;

endmodule

sva:
module NAND2_CLR_assertions (
    input logic clk,
    input logic A,
    input logic B,
    input logic CLR,
    input logic Y,
    input logic Yn
);

    // Clear drives Y low.
    check_clear_forces_y_low: assert property (
        @(posedge clk) CLR |-> (Y == 1'b0)
    );

    // Clear drives Yn high.
    check_clear_forces_yn_high: assert property (
        @(posedge clk) CLR |-> (Yn == 1'b1)
    );

    // Without clear, Y is the NAND of A and B.
    check_y_matches_nand_when_not_cleared: assert property (
        @(posedge clk) disable iff (CLR) (Y == ~(A & B))
    );

    // Without clear, Yn is the AND of A and B.
    check_yn_matches_and_when_not_cleared: assert property (
        @(posedge clk) disable iff (CLR) (Yn == (A & B))
    );

    // The outputs are always complementary.
    check_outputs_are_complementary: assert property (
        @(posedge clk) (Y == ~Yn)
    );

endmodule

rtl:
module Multiplexer_1bit(
  input ctrl,
  input D0,
  input D1,
  output S
);

  assign S = ctrl ? D1 : D0;

endmodule

sva:
module Multiplexer_1bit_sva (
    input logic ctrl,
    input logic D0,
    input logic D1,
    input logic S
);

    // Combinational mux with no RTL clock or reset; sample on the formal global clock.

    // When ctrl is low, S must select D0.
    check_select_d0: assert property (
        @($global_clock) (ctrl == 1'b0) |-> (S == D0)
    );

    // When ctrl is high, S must select D1.
    check_select_d1: assert property (
        @($global_clock) (ctrl == 1'b1) |-> (S == D1)
    );

    // S must always match the mux equation.
    check_mux_equation: assert property (
        @($global_clock) S == (ctrl ? D1 : D0)
    );

endmodule

rtl:
module led_controller (
  input [1:0] address,
  input chipselect,
  input clk,
  input reset_n,
  input write_n,
  input [31:0] writedata,
  output [3:0] out_port,
  output [31:0] readdata
);

  wire clk_en;
  reg [3:0] data_out;
  wire [3:0] out_port;
  wire [3:0] read_mux_out;
  wire [31:0] readdata;

  assign clk_en = 1;

  assign read_mux_out = {4 {(address == 0)}} & data_out;

  always @(posedge clk or negedge reset_n) begin
    if (reset_n == 0) begin
      data_out <= 0;
    end else if (chipselect && ~write_n && (address == 0)) begin
      data_out <= writedata[3:0];
    end
  end

  assign readdata = {32'b0 | read_mux_out};
  assign out_port = data_out;

endmodule

sva:
module led_controller_sva (
    input logic [1:0]  address,
    input logic        chipselect,
    input logic        clk,
    input logic        reset_n,
    input logic        write_n,
    input logic [31:0] writedata,
    input logic [3:0]  out_port,
    input logic [31:0] readdata
);

    // Reset clears the LED output register.
    check_reset_clears_out_port: assert property (
        @(posedge clk) !reset_n |-> (out_port == 4'b0000)
    );

    // Reset clears the readback data.
    check_reset_clears_readdata: assert property (
        @(posedge clk) !reset_n |-> (readdata == 32'b0)
    );

    // Read data is always zero-extended.
    check_readdata_upper_bits_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (readdata[31:4] == 28'b0)
    );

    // Address 0 reads back the current output value.
    check_readback_at_address_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (address == 2'b00) |-> (readdata == {28'b0, out_port})
    );

    // Nonzero addresses read back zero.
    check_readback_at_other_addresses: assert property (
        @(posedge clk) disable iff (!reset_n)
        (address != 2'b00) |-> (readdata == 32'b0)
    );

    // A selected write to address 0 updates the output on the next cycle.
    check_write_updates_out_port: assert property (
        @(posedge clk) disable iff (!reset_n)
        (chipselect && !write_n && (address == 2'b00)) |=> (out_port == $past(writedata[3:0]))
    );

    // Without a selected write to address 0, the output holds its value.
    check_out_port_holds_without_valid_write: assert property (
        @(posedge clk) disable iff (!reset_n)
        !(chipselect && !write_n && (address == 2'b00)) |=> (out_port == $past(out_port))
    );

endmodule

rtl:
module top_module (
    input [7:0] in1,
    input [7:0] in2,
    output [8:0] out,
    output [7:0] sum
);

    wire [7:0] xor_result;
    wire parity_bit;

    // Calculate XOR result
    assign xor_result = in1 ^ in2;

    // Calculate parity bit
    assign parity_bit = ^xor_result;

    // Concatenate parity bit with XOR result
    assign out = {parity_bit, xor_result};

    // Add input bytes and output byte to get sum
    adder adder_inst(.a(in1), .b(in2), .c(out), .sum(sum));

endmodule

// Additive functional module
module adder (
    input [7:0] a,
    input [7:0] b,
    input [8:0] c,
    output [7:0] sum
);

    reg [7:0] temp_sum;

    always @(*) begin
        temp_sum = a + b + c[8];
    end

    assign sum = temp_sum;

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic [7:0] in1,
    input logic [7:0] in2,
    input logic [8:0] out,
    input logic [7:0] sum
);

    // Combinational RTL with no native clock or reset; sample on an external clock.

    // out[7:0] is the bitwise XOR of the two inputs.
    check_out_low_is_xor: assert property (
        @(posedge clk) out[7:0] == (in1 ^ in2)
    );

    // out[8] is the parity of the XOR result.
    check_out_msb_is_input_parity: assert property (
        @(posedge clk) out[8] == (^(in1 ^ in2))
    );

    // out[8] matches the parity of out[7:0].
    check_out_msb_matches_out_low_parity: assert property (
        @(posedge clk) out[8] == (^out[7:0])
    );

    // out concatenates the parity bit with the XOR result.
    check_out_concatenation: assert property (
        @(posedge clk) out == { (^(in1 ^ in2)), (in1 ^ in2) }
    );

    // sum equals in1 plus in2 plus the connected out[8] bit.
    check_sum_uses_out_msb: assert property (
        @(posedge clk) sum == (in1 + in2 + out[8])
    );

    // sum equals in1 plus in2 plus parity of the XOR result.
    check_sum_matches_input_parity: assert property (
        @(posedge clk) sum == (in1 + in2 + (^(in1 ^ in2)))
    );

endmodule

