module top_module (
    input clk,
    input slowena,     // Pause and resume counting signal
    input reset,       // Asynchronous reset
    input [1:0] a,     // 2-bit input for the decoder
    input [1:0] b,     // 2-bit input for the decoder
    output [7:0] q     // 8-bit output from the functional module
);

    // Decoder module
    wire [15:0] dec_out;
    decoder_4to16 dec_inst (
        .in(b),
        .out(dec_out)
    );

    // Counter module
    reg [3:0] count;
    always @(posedge clk or negedge reset) begin
        if (reset == 0) begin
            count <= 0;
        end else if (slowena == 1) begin
            count <= count + 1;
        end
    end

    // Functional module
    wire [3:0] dec_index;
    assign dec_index = dec_out[15:12];
    wire [3:0] count_index;
    assign count_index = count[3:0];
    wire [7:0] add_out;
    adder add_inst (
        .in1(dec_index),
        .in2(count_index),
        .out(add_out)
    );
    assign q = add_out;

endmodule
module decoder_4to16 (
    input [1:0] in,
    output [15:0] out
);

    assign out = 16'b0000000000000001 << {in[1], in[0]};

endmodule
module adder (
    input [3:0] in1,
    input [3:0] in2,
    output [7:0] out
);

    assign out = {4'b0, in1} + {4'b0, in2};

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic slowena,
    input logic reset,
    input logic [1:0] a,
    input logic [1:0] b,
    input logic [7:0] q
);

    // A low reset clears q by the next clock sample.
    check_reset_clears_q: assert property (
        @(posedge clk) !reset |=> (q == 8'h00)
    );

    // q is always a zero-extended 4-bit value.
    check_q_upper_nibble_zero: assert property (
        @(posedge clk) disable iff (!reset) (q[7:4] == 4'h0)
    );

    // When paused, q holds its value regardless of a or b.
    check_q_holds_when_paused: assert property (
        @(posedge clk) disable iff (!reset) (!slowena) |=> (q == $past(q))
    );

    // When enabled, q increments by one modulo 16.
    check_q_increments_when_enabled: assert property (
        @(posedge clk) disable iff (!reset) slowena |=> (q[3:0] == ($past(q[3:0]) + 4'd1))
    );

    // Releasing reset while paused keeps q at zero on the next cycle.
    check_reset_release_paused_keeps_zero: assert property (
        @(posedge clk) disable iff (!reset) ($rose(reset) && !slowena) |=> (q == 8'h00)
    );

    // Releasing reset while enabled starts counting from one on the next cycle.
    check_reset_release_enabled_starts_one: assert property (
        @(posedge clk) disable iff (!reset) ($rose(reset) && slowena) |=> (q == 8'h01)
    );

endmodule

rtl:
module decoder_4to16_pipeline (
    input A, B,
    output reg [15:0] Y
);

reg [1:0] stage1_A, stage1_B;
reg [3:0] stage2_A, stage2_B;
reg [7:0] stage3_A, stage3_B;

always @(A or B) begin
    stage1_A <= A;
    stage1_B <= B;
end

always @(stage1_A or stage1_B) begin
    stage2_A <= stage1_A;
    stage2_B <= stage1_B;
end

always @(stage2_A or stage2_B) begin
    stage3_A <= stage2_A;
    stage3_B <= stage2_B;
end

always @(stage3_A or stage3_B) begin
    if (stage3_A == 2'b00) begin
        Y <= 16'b0000000000000001;
    end else if (stage3_A == 2'b01) begin
        Y <= 16'b0000000000000010;
    end else if (stage3_A == 2'b10) begin
        Y <= 16'b0000000000000100;
    end else if (stage3_A == 2'b11) begin
        Y <= 16'b1000000000000000;
    end
end

endmodule

sva:
module decoder_4to16_pipeline_assertions (
    input logic        A,
    input logic        B,
    input logic [15:0] Y,
    input logic [1:0]  stage1_A,
    input logic [1:0]  stage1_B,
    input logic [3:0]  stage2_A,
    input logic [3:0]  stage2_B,
    input logic [7:0]  stage3_A,
    input logic [7:0]  stage3_B
);

    // Stage1 A captures the current A value with zero extension after input activity.
    check_stage1_a_capture: assert property (
        @($global_clock)
        ($changed(A) || $changed(B)) |=> ##[0:1] (stage1_A === {1'b0, A})
    );

    // Stage1 B captures the current B value with zero extension after input activity.
    check_stage1_b_capture: assert property (
        @($global_clock)
        ($changed(A) || $changed(B)) |=> ##[0:1] (stage1_B === {1'b0, B})
    );

    // Stage2 A captures the current stage1_A value with zero extension.
    check_stage2_a_capture: assert property (
        @($global_clock)
        ($changed(stage1_A) || $changed(stage1_B)) |=> ##[0:1] (stage2_A === {2'b00, stage1_A})
    );

    // Stage2 B captures the current stage1_B value with zero extension.
    check_stage2_b_capture: assert property (
        @($global_clock)
        ($changed(stage1_A) || $changed(stage1_B)) |=> ##[0:1] (stage2_B === {2'b00, stage1_B})
    );

    // Stage3 A captures the current stage2_A value with zero extension.
    check_stage3_a_capture: assert property (
        @($global_clock)
        ($changed(stage2_A) || $changed(stage2_B)) |=> ##[0:1] (stage3_A === {4'b0000, stage2_A})
    );

    // Stage3 B captures the current stage2_B value with zero extension.
    check_stage3_b_capture: assert property (
        @($global_clock)
        ($changed(stage2_A) || $changed(stage2_B)) |=> ##[0:1] (stage3_B === {4'b0000, stage2_B})
    );

    // Input activity eventually drives stage3_A to the zero-extended A value.
    check_stage3_a_from_input: assert property (
        @($global_clock)
        ($changed(A) || $changed(B)) |=> ##[0:3] (stage3_A === {7'b0000000, A})
    );

    // Input activity eventually drives stage3_B to the zero-extended B value.
    check_stage3_b_from_input: assert property (
        @($global_clock)
        ($changed(A) || $changed(B)) |=> ##[0:3] (stage3_B === {7'b0000000, B})
    );

    // When A is 0, input activity eventually produces the bit-0 decode output.
    check_decode_for_a_zero: assert property (
        @($global_clock)
        ($changed(A) || $changed(B)) && (A === 1'b0) |=> ##[0:4] (Y === 16'h0001)
    );

    // When A is 1, input activity eventually produces the bit-1 decode output.
    check_decode_for_a_one: assert property (
        @($global_clock)
        ($changed(A) || $changed(B)) && (A === 1'b1) |=> ##[0:4] (Y === 16'h0002)
    );

endmodule

rtl:
module fsm_consecutive_ones_counter (
  input clk,
  input reset,
  input data,
  output reg match
);

  // Define the states
  parameter S0 = 2'b00;
  parameter S1 = 2'b01;
  parameter S2 = 2'b10;
  parameter S3 = 2'b11;

  // Define the state register and initialize to S0
  reg [1:0] state = S0;

  // Define the next state logic
  always @(posedge clk, negedge reset) begin
    if (reset == 1'b0) begin
      state <= S0;
    end else begin
      case (state)
        S0: begin
          if (data == 1'b1) begin
            state <= S1;
          end else begin
            state <= S0;
          end
        end
        S1: begin
          if (data == 1'b1) begin
            state <= S2;
          end else begin
            state <= S0;
          end
        end
        S2: begin
          if (data == 1'b1) begin
            state <= S3;
          end else begin
            state <= S0;
          end
        end
        S3: begin
          if (data == 1'b1) begin
            state <= S0;
          end else begin
            state <= S3;
          end
        end
      endcase
    end
  end

  // Define the output logic
  always @(state, data) begin
    if (state == S3) begin
      match <= 1'b1;
    end else begin
      match <= 1'b0;
    end
  end

endmodule

sva:
module fsm_consecutive_ones_counter_sva (
    input logic clk,
    input logic reset,
    input logic data,
    input logic match,
    input logic [1:0] state
);

    localparam logic [1:0] S0 = 2'b00;
    localparam logic [1:0] S1 = 2'b01;
    localparam logic [1:0] S2 = 2'b10;
    localparam logic [1:0] S3 = 2'b11;

    // Reset forces the FSM to S0 and clears match.
    check_reset_state_and_match: assert property (
        @(posedge clk) !reset |-> (state == S0 && match == 1'b0)
    );

    // In S0 with data low, the FSM stays in S0.
    check_s0_data0_stays_s0: assert property (
        @(posedge clk) disable iff (!reset)
        (state == S0 && data == 1'b0) |=> (state == S0)
    );

    // In S0 with data high, the FSM advances to S1.
    check_s0_data1_to_s1: assert property (
        @(posedge clk) disable iff (!reset)
        (state == S0 && data == 1'b1) |=> (state == S1)
    );

    // In S1 with data low, the FSM returns to S0.
    check_s1_data0_to_s0: assert property (
        @(posedge clk) disable iff (!reset)
        (state == S1 && data == 1'b0) |=> (state == S0)
    );

    // In S1 with data high, the FSM advances to S2.
    check_s1_data1_to_s2: assert property (
        @(posedge clk) disable iff (!reset)
        (state == S1 && data == 1'b1) |=> (state == S2)
    );

    // In S2 with data low, the FSM returns to S0.
    check_s2_data0_to_s0: assert property (
        @(posedge clk) disable iff (!reset)
        (state == S2 && data == 1'b0) |=> (state == S0)
    );

    // In S2 with data high, the FSM advances to S3.
    check_s2_data1_to_s3: assert property (
        @(posedge clk) disable iff (!reset)
        (state == S2 && data == 1'b1) |=> (state == S3)
    );

    // In S3 with data low, the FSM stays in S3.
    check_s3_data0_stays_s3: assert property (
        @(posedge clk) disable iff (!reset)
        (state == S3 && data == 1'b0) |=> (state == S3)
    );

    // In S3 with data high, the FSM wraps back to S0.
    check_s3_data1_to_s0: assert property (
        @(posedge clk) disable iff (!reset)
        (state == S3 && data == 1'b1) |=> (state == S0)
    );

    // Match must be high whenever the FSM is in S3.
    check_match_high_in_s3: assert property (
        @(posedge clk) disable iff (!reset)
        (state == S3) |-> (match == 1'b1)
    );

    // Match must be low in all non-S3 states.
    check_match_low_outside_s3: assert property (
        @(posedge clk) disable iff (!reset)
        (state == S0 || state == S1 || state == S2) |-> (match == 1'b0)
    );

endmodule

