module full_adder (
    input A,
    input B,
    input C_in,
    output S,
    output C_out
);

    assign S = A ^ B ^ C_in;
    assign C_out = (A & B) | (A & C_in) | (B & C_in);

endmodule

module adder4 (
    input [3:0] A,
    input [3:0] B,
    output [3:0] S,
    output C
);

    wire [3:0] sum;
    wire [3:0] carry;

    full_adder fa0 (.A(A[0]), .B(B[0]), .C_in(1'b0), .S(sum[0]), .C_out(carry[0]));
    full_adder fa1 (.A(A[1]), .B(B[1]), .C_in(carry[0]), .S(sum[1]), .C_out(carry[1]));
    full_adder fa2 (.A(A[2]), .B(B[2]), .C_in(carry[1]), .S(sum[2]), .C_out(carry[2]));
    full_adder fa3 (.A(A[3]), .B(B[3]), .C_in(carry[2]), .S(sum[3]), .C_out(C));

    assign S = sum;

endmodule

sva:
module adder4_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] S,
    input logic C,
    input logic clk
);

    // Sum and carry must match A+B.
    check_total_sum: assert property (
        @(posedge clk) {C, S} == ({1'b0, A} + {1'b0, B})
    );

    // Bit 0 is the XOR of the LSB inputs.
    check_lsb_sum: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0])
    );

    // Bit 1 includes the carry from bit 0.
    check_bit1_sum: assert property (
        @(posedge clk) S[1] == (A[1] ^ B[1] ^ (A[0] & B[0]))
    );

    // Bit 2 includes the carry from the lower two bits.
    check_bit2_sum: assert property (
        @(posedge clk) S[2] == (A[2] ^ B[2] ^ (({1'b0, A[1:0]} + {1'b0, B[1:0]})[2]))
    );

    // Bit 3 includes the carry from the lower three bits.
    check_bit3_sum: assert property (
        @(posedge clk) S[3] == (A[3] ^ B[3] ^ (({1'b0, A[2:0]} + {1'b0, B[2:0]})[3]))
    );

    // C is the carry-out of the 4-bit addition.
    check_carry_out: assert property (
        @(posedge clk) C == (({1'b0, A} + {1'b0, B})[4])
    );

    // Zero on A passes B through.
    check_zero_a_identity: assert property (
        @(posedge clk) (A == 4'b0000) |-> (S == B && C == 1'b0)
    );

    // Zero on B passes A through.
    check_zero_b_identity: assert property (
        @(posedge clk) (B == 4'b0000) |-> (S == A && C == 1'b0)
    );

    // Stable inputs keep outputs stable.
    check_stable_inputs_stable_outputs: assert property (
        @(posedge clk) ($stable(A) && $stable(B)) |-> ($stable(S) && $stable(C))
    );

endmodule

rtl:
module adder_8bit(
    input [7:0] A,
    input [7:0] B,
    output [7:0] sum,
    output carry_out
);

    wire[8:0] temp_sum;

    assign temp_sum = {1'b0, A} + {1'b0, B};

    assign sum = temp_sum[7:0];
    assign carry_out = temp_sum[8];

endmodule

sva:
module adder_8bit_sva(
    input logic clk,
    input logic [7:0] A,
    input logic [7:0] B,
    input logic [7:0] sum,
    input logic carry_out
);

    // Outputs match the 9-bit zero-extended addition of A and B.
    check_result_matches_extended_addition: assert property (
        @(posedge clk) {carry_out, sum} == ({1'b0, A} + {1'b0, B})
    );

    // Zero on A passes B through with no carry.
    check_a_zero_passes_b: assert property (
        @(posedge clk) (A == 8'h00) |-> (sum == B && carry_out == 1'b0)
    );

    // Zero on B passes A through with no carry.
    check_b_zero_passes_a: assert property (
        @(posedge clk) (B == 8'h00) |-> (sum == A && carry_out == 1'b0)
    );

    // 8'hFF plus 8'h01 wraps sum and raises carry.
    check_overflow_boundary_ff_plus_01: assert property (
        @(posedge clk) (A == 8'hFF && B == 8'h01) |-> (sum == 8'h00 && carry_out == 1'b1)
    );

    // 8'hFF plus 8'hFF produces 8'hFE with carry high.
    check_max_operands_overflow: assert property (
        @(posedge clk) (A == 8'hFF && B == 8'hFF) |-> (sum == 8'hFE && carry_out == 1'b1)
    );

    // Stable inputs keep the outputs stable.
    check_stable_inputs_keep_outputs_stable: assert property (
        @(posedge clk) ($stable(A) && $stable(B)) |-> ($stable(sum) && $stable(carry_out))
    );

endmodule

