module PPgen(
	Single,
	Yi,
	Double,
	Negate,
	Yi_m1,
	PPi
);


input wire	Single;
input wire	Yi;
input wire	Double;
input wire	Negate;
input wire	Yi_m1;
output wire	PPi;

wire	SYNTHESIZED_WIRE_0;
wire	SYNTHESIZED_WIRE_1;
wire	SYNTHESIZED_WIRE_2;




assign	SYNTHESIZED_WIRE_1 = ~(Yi & Single);

assign	SYNTHESIZED_WIRE_0 = ~(Yi_m1 & Double);

assign	SYNTHESIZED_WIRE_2 = ~(SYNTHESIZED_WIRE_0 & SYNTHESIZED_WIRE_1);

assign	PPi = SYNTHESIZED_WIRE_2 ^ Negate;


endmodule

sva:
module PPgen_sva (
    input logic clk,
    input logic Single,
    input logic Yi,
    input logic Double,
    input logic Negate,
    input logic Yi_m1,
    input logic PPi
);

    // PPi must match the implemented combinational equation.
    check_ppi_matches_logic: assert property (
        @(posedge clk)
        PPi == (((Yi & Single) | (Yi_m1 & Double)) ^ Negate)
    );

    // With no active partial-product terms and no negate, PPi must be low.
    check_inactive_terms_no_negate: assert property (
        @(posedge clk)
        ((((Yi & Single) | (Yi_m1 & Double)) == 1'b0) && (Negate == 1'b0)) |-> (PPi == 1'b0)
    );

    // With no active partial-product terms and negate asserted, PPi must be high.
    check_inactive_terms_with_negate: assert property (
        @(posedge clk)
        ((((Yi & Single) | (Yi_m1 & Double)) == 1'b0) && (Negate == 1'b1)) |-> (PPi == 1'b1)
    );

    // With any active partial-product term and no negate, PPi must be high.
    check_active_term_no_negate: assert property (
        @(posedge clk)
        ((((Yi & Single) | (Yi_m1 & Double)) == 1'b1) && (Negate == 1'b0)) |-> (PPi == 1'b1)
    );

    // With any active partial-product term and negate asserted, PPi must be low.
    check_active_term_with_negate: assert property (
        @(posedge clk)
        ((((Yi & Single) | (Yi_m1 & Double)) == 1'b1) && (Negate == 1'b1)) |-> (PPi == 1'b0)
    );

endmodule

rtl:
module calculator (
  input op,
  input [3:0] a,
  input [3:0] b,
  output [3:0] result,
  output carry
);

  reg [4:0] temp_result;
  reg temp_carry;

  always @(*) begin
    if (op == 0) begin
      temp_result = a + b;
      temp_carry = (temp_result[4] == 1);
    end else begin
      temp_result = a - b;
      temp_carry = 0;
    end
  end

  assign result = temp_result[3:0];
  assign carry = temp_carry;

endmodule

sva:
module calculator_sva (
    input logic clk,
    input logic op,
    input logic [3:0] a,
    input logic [3:0] b,
    input logic [3:0] result,
    input logic carry
);

    // Result matches the selected add or subtract operation.
    check_result_matches_selected_operation: assert property (
        @(posedge clk) result == (op ? (a - b) : (a + b))
    );

    // Carry is asserted only for overflow during addition.
    check_carry_matches_add_overflow: assert property (
        @(posedge clk) carry == ((op == 1'b0) && (({1'b0, a} + {1'b0, b}) > 5'd15))
    );

    // In add mode, the outputs match the full 5-bit sum.
    check_add_outputs_match_sum: assert property (
        @(posedge clk) (op == 1'b0) |-> ({carry, result} == ({1'b0, a} + {1'b0, b}))
    );

    // In subtract mode, result matches the 4-bit difference.
    check_subtract_result_matches_difference: assert property (
        @(posedge clk) (op == 1'b1) |-> (result == (a - b))
    );

    // In subtract mode, carry is always low.
    check_subtract_carry_is_zero: assert property (
        @(posedge clk) (op == 1'b1) |-> (carry == 1'b0)
    );

endmodule

rtl:
module four_bit_adder (
    input [3:0] A,
    input [3:0] B,
    input mode,
    input reset,
    input carry_in,
    input CLK,
    output [3:0] C,
    output carry_out
);

    wire [3:0] sum;
    wire [4:0] full_sum;

    assign full_sum = {carry_in, A} + {mode, B};

    assign sum = full_sum[3:0];

    assign carry_out = full_sum[4];

    reg [3:0] C;

    always @(posedge CLK) begin
        if (reset) begin
            C <= 4'b0;
        end else begin
            C <= sum;
        end
    end

endmodule

sva:
module four_bit_adder_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic mode,
    input logic reset,
    input logic carry_in,
    input logic CLK,
    input logic [3:0] C,
    input logic carry_out
);

    // Reset clears the registered output on the following clock.
    check_reset_clears_c: assert property (
        @(posedge CLK) reset |=> (C == 4'b0000)
    );

    // carry_out matches the MSB of the current 5-bit addition.
    check_carry_out_matches_addition: assert property (
        @(posedge CLK) disable iff (reset)
            carry_out == (({carry_in, A} + {mode, B})[4])
    );

    // C captures the low 4 bits of the previous cycle's addition.
    check_c_registers_sum_low_bits: assert property (
        @(posedge CLK) disable iff (reset)
            1'b1 |=> ({1'b0, C} == ($past({carry_in, A} + {mode, B}) & 5'h0F))
    );

    // With held inputs across non-reset cycles, sampled outputs match the current addition.
    check_outputs_match_addition_when_inputs_hold: assert property (
        @(posedge CLK) disable iff (reset)
            (!$past(reset) && $stable({A, B, mode, carry_in})) |-> ({carry_out, C} == ({carry_in, A} + {mode, B}))
    );

endmodule

module _2bit_up_counter_with_synch_load_enable_clear_sva (
    input logic       Clock,
    input logic       Clear,
    input logic       Enable,
    input logic       Load,
    input logic [1:0] Q
);

    // Clear synchronously forces the counter to zero.
    check_clear_forces_zero: assert property (
        @(posedge Clock) Clear |=> (Q == 2'b00)
    );

    // Load sets the counter to 2'b11 when clear is inactive.
    check_load_sets_q_to_11: assert property (
        @(posedge Clock) disable iff (Clear) Load |=> (Q == 2'b11)
    );

    // With no control active, the counter holds its value.
    check_idle_holds_q: assert property (
        @(posedge Clock) disable iff (Clear) (!Load && !Enable) |=> (Q == $past(Q))
    );

    // Enable increments 2'b00 to 2'b01.
    check_enable_00_to_01: assert property (
        @(posedge Clock) disable iff (Clear) (!Load && Enable && (Q == 2'b00)) |=> (Q == 2'b01)
    );

    // Enable increments 2'b01 to 2'b10.
    check_enable_01_to_10: assert property (
        @(posedge Clock) disable iff (Clear) (!Load && Enable && (Q == 2'b01)) |=> (Q == 2'b10)
    );

    // Enable increments 2'b10 to 2'b11.
    check_enable_10_to_11: assert property (
        @(posedge Clock) disable iff (Clear) (!Load && Enable && (Q == 2'b10)) |=> (Q == 2'b11)
    );

    // Enable wraps 2'b11 back to 2'b00.
    check_enable_11_to_00: assert property (
        @(posedge Clock) disable iff (Clear) (!Load && Enable && (Q == 2'b11)) |=> (Q == 2'b00)
    );

endmodule

rtl:
module ad_iobuf (
  dio_t,
  dio_i,
  dio_o,
  dio_p
);

  parameter DATA_WIDTH = 1;

  input [(DATA_WIDTH-1):0] dio_t;
  input [(DATA_WIDTH-1):0] dio_i;
  output [(DATA_WIDTH-1):0] dio_o;
  output [(DATA_WIDTH-1):0] dio_p;

  genvar n;
  generate
    for (n = 0; n < DATA_WIDTH; n = n + 1) begin : g_iobuf
      wire const1 = 1'b1;  
      assign dio_o[n] = dio_p[n];
      assign dio_p[n] = dio_t[n] ? dio_i[n] : const1;
    end
  endgenerate

endmodule

sva:
module ad_iobuf_sva #(
    parameter DATA_WIDTH = 1
) (
    input logic clk,
    input logic [DATA_WIDTH-1:0] dio_t,
    input logic [DATA_WIDTH-1:0] dio_i,
    input logic [DATA_WIDTH-1:0] dio_o,
    input logic [DATA_WIDTH-1:0] dio_p
);

    genvar n;
    generate
        for (n = 0; n < DATA_WIDTH; n = n + 1) begin : g_iobuf_checks
            // dio_o always matches dio_p.
            check_dio_o_matches_dio_p: assert property (
                @(posedge clk) dio_o[n] == dio_p[n]
            );

            // High dio_t makes dio_p follow dio_i.
            check_dio_p_follows_dio_i_when_dio_t_high: assert property (
                @(posedge clk) dio_t[n] |-> (dio_p[n] == dio_i[n])
            );

            // Low dio_t forces dio_p high.
            check_dio_p_forced_high_when_dio_t_low: assert property (
                @(posedge clk) !dio_t[n] |-> (dio_p[n] == 1'b1)
            );

            // High dio_t makes dio_o follow dio_i.
            check_dio_o_follows_dio_i_when_dio_t_high: assert property (
                @(posedge clk) dio_t[n] |-> (dio_o[n] == dio_i[n])
            );

            // Low dio_t forces dio_o high.
            check_dio_o_forced_high_when_dio_t_low: assert property (
                @(posedge clk) !dio_t[n] |-> (dio_o[n] == 1'b1)
            );
        end
    endgenerate

endmodule

rtl:
module ldly1_5us(
    input clk, reset, in,
    output reg p,
    output reg l
);

    reg [7:0] r;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            r <= 0;
            l <= 0;
        end else begin
            if (in) begin
                r <= 1;
                l <= 1;
                p <= 0;
            end else if (p) begin
                r <= 0;
                l <= 0;
            end else if (r == 75) begin
                p <= 1;
            end else begin
                r <= r + 1;
                l <= 0;
            end
        end
    end

endmodule

sva:
module ldly1_5us_sva (
    input logic clk,
    input logic reset,
    input logic in,
    input logic p,
    input logic l,
    input logic [7:0] r
);

    // A sampled reset clears r and l.
    check_reset_clears_r_l: assert property (
        @(posedge clk) reset |=> (r == 8'd0 && l == 1'b0)
    );

    // An asserted input restarts the delay, raises l, and clears p.
    check_in_restarts_delay: assert property (
        @(posedge clk) disable iff (reset)
        in |=> (r == 8'd1 && l == 1'b1 && p == 1'b0)
    );

    // With no input, an asserted p clears r and l and stays asserted.
    check_p_branch_behavior: assert property (
        @(posedge clk) disable iff (reset)
        (!in && p) |=> (r == 8'd0 && l == 1'b0 && p == 1'b1)
    );

    // When the counter reaches 75 without input, p asserts and r holds.
    check_count_75_asserts_p: assert property (
        @(posedge clk) disable iff (reset)
        (!in && !p && (r == 8'd75)) |=> (p == 1'b1 && r == 8'd75)
    );

    // Before 75, the counter increments while l stays low and p stays low.
    check_counter_increments_before_75: assert property (
        @(posedge clk) disable iff (reset)
        (!in && !p && (r != 8'd75)) |=> (r == ($past(r) + 8'd1) && l == 1'b0 && p == 1'b0)
    );

endmodule

