module comb_logic(A, B, X, Y);
input A;
input B;
output X;
output Y;

wire X_wire;
wire Y_wire;

and(X_wire, A, B);
xor(Y_wire, A, B);

assign X = X_wire;
assign Y = Y_wire;

endmodule

sva:
module comb_logic_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic X,
    input logic Y
);

    // X must always be the AND of A and B.
    check_x_is_and: assert property (
        @(posedge clk) X == (A & B)
    );

    // Y must always be the XOR of A and B.
    check_y_is_xor: assert property (
        @(posedge clk) Y == (A ^ B)
    );

    // When both inputs are high, X is high and Y is low.
    check_both_high_outputs: assert property (
        @(posedge clk) (A && B) |-> (X && !Y)
    );

    // When both inputs are low, both outputs are low.
    check_both_low_outputs: assert property (
        @(posedge clk) (!A && !B) |-> (!X && !Y)
    );

    // When the inputs differ, X is low and Y is high.
    check_inputs_differ_outputs: assert property (
        @(posedge clk) (A ^ B) |-> (!X && Y)
    );

    // AND and XOR outputs can never both be high.
    check_outputs_not_both_high: assert property (
        @(posedge clk) !(X && Y)
    );

endmodule

rtl:
module pre_decoder (
    input [5:0] addr_i,
    output pre_dec_o,
    output pre_dec_err_o
);

reg pre_dec;
reg pre_dec_err;

assign pre_dec_o = pre_dec;
assign pre_dec_err_o = pre_dec_err;

always @ (addr_i) begin
    pre_dec <= 0;
    pre_dec_err <= 0;
    case (addr_i[5:2])
        // clock-domain #0 --> clk_a
        'h0, 'h8, 'ha: pre_dec <= 0;
        // clock-domain #1 --> clk_f20
        'h1, 'h2, 'h3, 'h4, 'h5, 'h6, 'h7: pre_dec <= 1;
        default: begin 
            pre_dec <= 0;
            pre_dec_err <= 1;
        end
    endcase
end

endmodule

sva:
module pre_decoder_sva (
    input logic [5:0] addr_i,
    input logic pre_dec_o,
    input logic pre_dec_err_o
);

    // DUT is combinational, so properties are sampled on the formal global clock.

    // Mapped clock-domain #0 addresses decode with no select and no error.
    check_clk_domain0_decode: assert property (
        @($global_clock)
        ((addr_i[5:2] == 4'h0) || (addr_i[5:2] == 4'h8) || (addr_i[5:2] == 4'ha))
        |-> ((pre_dec_o == 1'b0) && (pre_dec_err_o == 1'b0))
    );

    // Mapped clock-domain #1 addresses decode with select asserted and no error.
    check_clk_domain1_decode: assert property (
        @($global_clock)
        ((addr_i[5:2] >= 4'h1) && (addr_i[5:2] <= 4'h7))
        |-> ((pre_dec_o == 1'b1) && (pre_dec_err_o == 1'b0))
    );

    // Unmapped addresses decode as an error with no select asserted.
    check_unmapped_decode_error: assert property (
        @($global_clock)
        ((addr_i[5:2] == 4'h9) || ((addr_i[5:2] >= 4'hb) && (addr_i[5:2] <= 4'hf)))
        |-> ((pre_dec_o == 1'b0) && (pre_dec_err_o == 1'b1))
    );

    // pre_dec_o can only be high for clock-domain #1 address ranges.
    check_pre_dec_only_for_domain1: assert property (
        @($global_clock)
        (pre_dec_o == 1'b1)
        |-> (((addr_i[5:2] >= 4'h1) && (addr_i[5:2] <= 4'h7)) && (pre_dec_err_o == 1'b0))
    );

    // pre_dec_err_o can only be high for unmapped address ranges.
    check_error_only_for_unmapped: assert property (
        @($global_clock)
        (pre_dec_err_o == 1'b1)
        |-> (((addr_i[5:2] == 4'h9) || ((addr_i[5:2] >= 4'hb) && (addr_i[5:2] <= 4'hf))) &&
             (pre_dec_o == 1'b0))
    );

    // The no-select, no-error result only occurs for the explicit clock-domain #0 addresses.
    check_zero_decode_only_for_domain0: assert property (
        @($global_clock)
        ((pre_dec_o == 1'b0) && (pre_dec_err_o == 1'b0))
        |-> ((addr_i[5:2] == 4'h0) || (addr_i[5:2] == 4'h8) || (addr_i[5:2] == 4'ha))
    );

    // The two outputs are never asserted together.
    check_outputs_mutually_exclusive: assert property (
        @($global_clock)
        !((pre_dec_o == 1'b1) && (pre_dec_err_o == 1'b1))
    );

    // Changes in addr_i[1:0] alone cannot change the outputs.
    check_outputs_depend_only_on_addr_high: assert property (
        @($global_clock)
        (!$initstate && (addr_i[5:2] == $past(addr_i[5:2])))
        |-> ((pre_dec_o == $past(pre_dec_o)) && (pre_dec_err_o == $past(pre_dec_err_o)))
    );

endmodule

module decoder_3to8_sva (
    input logic clk,
    input logic [2:0] A,
    input logic [2:0] B,
    input logic [2:0] C,
    input logic EN,
    input logic [7:0] Y
);

    // EN low forces the output low.
    check_disabled_zero: assert property (
        @(posedge clk) (EN == 1'b0) |-> (Y == 8'b00000000)
    );

    // Enabled decode of A=0, B=0, C=0 sets bit 0.
    check_decode_c000: assert property (
        @(posedge clk) (EN == 1'b1 && A == 3'b000 && B == 3'b000 && C == 3'b000) |-> (Y == 8'b00000001)
    );

    // Enabled decode of A=0, B=0, C=1 sets bit 1.
    check_decode_c001: assert property (
        @(posedge clk) (EN == 1'b1 && A == 3'b000 && B == 3'b000 && C == 3'b001) |-> (Y == 8'b00000010)
    );

    // Enabled decode of A=0, B=0, C=2 sets bit 2.
    check_decode_c010: assert property (
        @(posedge clk) (EN == 1'b1 && A == 3'b000 && B == 3'b000 && C == 3'b010) |-> (Y == 8'b00000100)
    );

    // Enabled decode of A=0, B=0, C=3 sets bit 3.
    check_decode_c011: assert property (
        @(posedge clk) (EN == 1'b1 && A == 3'b000 && B == 3'b000 && C == 3'b011) |-> (Y == 8'b00001000)
    );

    // Enabled decode of A=0, B=0, C=4 sets bit 4.
    check_decode_c100: assert property (
        @(posedge clk) (EN == 1'b1 && A == 3'b000 && B == 3'b000 && C == 3'b100) |-> (Y == 8'b00010000)
    );

    // Enabled decode of A=0, B=0, C=5 sets bit 5.
    check_decode_c101: assert property (
        @(posedge clk) (EN == 1'b1 && A == 3'b000 && B == 3'b000 && C == 3'b101) |-> (Y == 8'b00100000)
    );

    // Enabled decode of A=0, B=0, C=6 sets bit 6.
    check_decode_c110: assert property (
        @(posedge clk) (EN == 1'b1 && A == 3'b000 && B == 3'b000 && C == 3'b110) |-> (Y == 8'b01000000)
    );

    // Enabled decode of A=0, B=0, C=7 sets bit 7.
    check_decode_c111: assert property (
        @(posedge clk) (EN == 1'b1 && A == 3'b000 && B == 3'b000 && C == 3'b111) |-> (Y == 8'b10000000)
    );

    // Any other enabled input combination drives zero.
    check_enabled_default_zero: assert property (
        @(posedge clk) (EN == 1'b1 && (A != 3'b000 || B != 3'b000)) |-> (Y == 8'b00000000)
    );

endmodule

