module complement_sva (
    input logic        clk,
    input logic [3:0]  A,
    input logic [3:0]  B
);

    // No reset in RTL; assertions are sampled on clk.

    // B matches the bitwise complement of A.
    check_vector_complement: assert property (
        @(posedge clk) B === ~A
    );

    // B[0] is the complement of A[0].
    check_bit0_complement: assert property (
        @(posedge clk) B[0] === ~A[0]
    );

    // B[1] is the complement of A[1].
    check_bit1_complement: assert property (
        @(posedge clk) B[1] === ~A[1]
    );

    // B[2] is the complement of A[2].
    check_bit2_complement: assert property (
        @(posedge clk) B[2] === ~A[2]
    );

    // B[3] is the complement of A[3].
    check_bit3_complement: assert property (
        @(posedge clk) B[3] === ~A[3]
    );

endmodule

rtl:
module top_module (
    input [3:0] in,
    input a,
    input b,
    input clk,
    input reset,
    output reg final_out
);

    // First given module
    wire [1:0] and1, and2, or1, or2, xor1, xor2;
    assign and1 = in[0] & in[1];
    assign and2 = in[2] & in[3];
    assign or1 = in[0] | in[1];
    assign or2 = in[2] | in[3];
    assign xor1 = in[0] ^ in[1];
    assign xor2 = in[2] ^ in[3];
    wire out_and, out_or, out_xor;
    assign out_and = and1 & and2;
    assign out_or = or1 | or2;
    assign out_xor = xor1 ^ xor2;

    // Second given module
    reg xor_gate_out;
    always @ (a or b) begin
        case ({a,b})
            2'b00: xor_gate_out = 1'b0;
            2'b01: xor_gate_out = 1'b1;
            2'b10: xor_gate_out = 1'b1;
            2'b11: xor_gate_out = 1'b0;
        endcase
    end

    // Functional module
    always @ (posedge clk, posedge reset) begin
        if (reset) begin
            final_out <= 1'b0;
        end else begin
            final_out <= (out_and & out_or) ^ (out_xor ^ xor_gate_out);
        end
    end

endmodule

sva:
module top_module_sva (
    input logic [3:0] in,
    input logic a,
    input logic b,
    input logic clk,
    input logic reset,
    input logic final_out
);

    logic [1:0] and1, and2, or1, or2, xor1, xor2;
    logic out_and, out_or, out_xor;
    logic xor_gate_out;

    assign and1 = in[0] & in[1];
    assign and2 = in[2] & in[3];
    assign or1  = in[0] | in[1];
    assign or2  = in[2] | in[3];
    assign xor1 = in[0] ^ in[1];
    assign xor2 = in[2] ^ in[3];

    assign out_and = and1 & and2;
    assign out_or  = or1 | or2;
    assign out_xor = xor1 ^ xor2;

    assign xor_gate_out = a ^ b;

    // A sampled reset must leave final_out low on the next clock.
    check_reset_clears_on_next_clock: assert property (
        @(posedge clk) reset |=> (final_out == 1'b0)
    );

    // On the first clock after reset deasserts, final_out is still low.
    check_reset_release_starts_low: assert property (
        @(posedge clk) reset ##1 !reset |-> (final_out == 1'b0)
    );

    // Without reset, final_out updates to the previous cycle's combinational result.
    check_registered_function_update: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> (final_out == $past((out_and & out_or) ^ (out_xor ^ xor_gate_out)))
    );

    // With all in bits low and a^b low, the next final_out is 0.
    check_zero_inputs_equal_ab: assert property (
        @(posedge clk) disable iff (reset)
        ((in == 4'b0000) && ((a ^ b) == 1'b0)) |=> (final_out == 1'b0)
    );

    // With all in bits low and a^b high, the next final_out is 1.
    check_zero_inputs_diff_ab: assert property (
        @(posedge clk) disable iff (reset)
        ((in == 4'b0000) && ((a ^ b) == 1'b1)) |=> (final_out == 1'b1)
    );

    // With all in bits high and a^b low, the next final_out is 1.
    check_all_ones_equal_ab: assert property (
        @(posedge clk) disable iff (reset)
        ((in == 4'b1111) && ((a ^ b) == 1'b0)) |=> (final_out == 1'b1)
    );

    // With all in bits high and a^b high, the next final_out is 0.
    check_all_ones_diff_ab: assert property (
        @(posedge clk) disable iff (reset)
        ((in == 4'b1111) && ((a ^ b) == 1'b1)) |=> (final_out == 1'b0)
    );

    // With exactly one in bit high and a^b low, the next final_out is 1.
    check_onehot_inputs_equal_ab: assert property (
        @(posedge clk) disable iff (reset)
        (((in == 4'b0001) || (in == 4'b0010) || (in == 4'b0100) || (in == 4'b1000)) &&
         ((a ^ b) == 1'b0)) |=> (final_out == 1'b1)
    );

    // With exactly one in bit high and a^b high, the next final_out is 0.
    check_onehot_inputs_diff_ab: assert property (
        @(posedge clk) disable iff (reset)
        (((in == 4'b0001) || (in == 4'b0010) || (in == 4'b0100) || (in == 4'b1000)) &&
         ((a ^ b) == 1'b1)) |=> (final_out == 1'b0)
    );

endmodule

rtl:
module bit_change_detector (
    input clk,
    input [15:0] in,
    input reset, // Added reset input
    output reg out
);

    reg [15:0] prev_in;

    always @(posedge clk) begin
        if (reset) begin
            out <= 0;
            prev_in <= 0;
        end else begin
            if (in != prev_in) begin
                out <= 1;
                prev_in <= in;
            end else begin
                out <= 0;
            end
        end
    end
endmodule

module register_module (
    input clk,
    input reset, // Added reset input
    input [15:0] in,
    output reg [15:0] out
);

    always @(posedge clk) begin
        if (reset) begin
            out <= 0;
        end else begin
            out <= in;
        end
    end
endmodule

module control_logic (
    input select,
    input bit_change_detector_out,
    input [15:0] register_out,
    output out
);

    assign out = select ? register_out : bit_change_detector_out;

endmodule

module top_module (
    input clk,
    input reset, // Added reset input
    input [15:0] in,
    input select,
    output out
);

    wire bit_change_detector_out;
    wire [15:0] register_out;

    bit_change_detector bit_change_detector_inst (
        .clk(clk),
        .in(in),
        .reset(reset), // Connected reset signal
        .out(bit_change_detector_out)
    );

    register_module register_inst (
        .clk(clk),
        .reset(reset), // Connected reset signal
        .in(in),
        .out(register_out)
    );

    control_logic control_logic_inst (
        .select(select),
        .bit_change_detector_out(bit_change_detector_out),
        .register_out(register_out),
        .out(out)
    );

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic reset,
    input logic [15:0] in,
    input logic select,
    input logic out,
    input logic bit_change_detector_out,
    input logic [15:0] register_out
);

    // Reset clears the registered data path.
    check_reset_clears_register: assert property (
        @(posedge clk) reset |=> (register_out == 16'h0000)
    );

    // Reset clears the change detector output.
    check_reset_clears_change_flag: assert property (
        @(posedge clk) reset |=> (bit_change_detector_out == 1'b0)
    );

    // Reset drives the top-level output low on the next cycle.
    check_reset_clears_top_out: assert property (
        @(posedge clk) reset |=> (out == 1'b0)
    );

    // While reset stays asserted, all stored outputs remain zero.
    check_sustained_reset_holds_zero: assert property (
        @(posedge clk) (reset && $past(reset)) |-> ((register_out == 16'h0000) && (bit_change_detector_out == 1'b0) && (out == 1'b0))
    );

    // The register captures the input on the next clock.
    check_register_captures_input: assert property (
        @(posedge clk) disable iff (reset) (!reset) |=> (register_out == $past(in))
    );

    // A change in input raises the detector output on the next cycle.
    check_change_detector_asserts_on_input_change: assert property (
        @(posedge clk) disable iff (reset) (!$past(reset) && (in != $past(in))) |=> (bit_change_detector_out == 1'b1)
    );

    // A stable input keeps the detector output low on the next cycle.
    check_change_detector_deasserts_on_stable_input: assert property (
        @(posedge clk) disable iff (reset) (!$past(reset) && (in == $past(in))) |=> (bit_change_detector_out == 1'b0)
    );

    // When selected, the top output matches the register LSB.
    check_mux_selects_register_lsb: assert property (
        @(posedge clk) disable iff (reset) select |-> (out == register_out[0])
    );

    // When not selected, the top output matches the change detector.
    check_mux_selects_change_detector: assert property (
        @(posedge clk) disable iff (reset) !select |-> (out == bit_change_detector_out)
    );

    // With register selected, output reflects the prior cycle input LSB.
    check_selected_register_reflects_prior_input_lsb: assert property (
        @(posedge clk) disable iff (reset) (select && !$past(reset)) |-> (out == $past(in[0]))
    );

endmodule

bind top_module top_module_sva top_module_sva_inst (
    .clk(clk),
    .reset(reset),
    .in(in),
    .select(select),
    .out(out),
    .bit_change_detector_out(bit_change_detector_out),
    .register_out(register_out)
);

rtl:
module logic_function (A, B, Ci, S, Co);
  input A, B, Ci;
  output S, Co;
  wire   n10, n11, n12;

  // XNOR2_X1 U1 ( .A(Ci), .B(n12), .ZN(S) );
  assign n12 = ~(A ^ B);
  assign S = ~(n12 ^ Ci);

  // NAND2_X1 U3 ( .A1(n11), .A2(n10), .ZN(Co) );
  assign n10 = ~(A & B);
  assign n11 = ~(A & Ci);
  assign Co = ~(n10 & n11);

  // XNOR2_X1 U2 ( .A(B), .B(A), .ZN(n12) );
  // NAND2_X1 U4 ( .A1(A), .A2(B), .ZN(n10) );
  // OAI21_X1 U5 ( .B1(A), .B2(B), .A(Ci), .ZN(n11) );
endmodule

sva:
module logic_function_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic Ci,
    input logic S,
    input logic Co
);

    // No clock or reset exists in the RTL; sample on an external clock.
    // Sum output matches the implemented XOR-of-three function.
    check_sum_function: assert property (
        @(posedge clk) S == (A ^ B ^ Ci)
    );

    // When A and B are equal, sum follows Ci.
    check_sum_equal_ab: assert property (
        @(posedge clk) (A == B) |-> (S == Ci)
    );

    // When A and B differ, sum is the inverse of Ci.
    check_sum_different_ab: assert property (
        @(posedge clk) (A != B) |-> (S == ~Ci)
    );

    // Carry output matches the implemented A & (B | Ci) function.
    check_carry_function: assert property (
        @(posedge clk) Co == (A & (B | Ci))
    );

    // Carry can only assert when A is high.
    check_carry_requires_a: assert property (
        @(posedge clk) Co |-> A
    );

    // A and B high must assert carry.
    check_carry_from_ab: assert property (
        @(posedge clk) (A & B) |-> Co
    );

    // A and Ci high must assert carry.
    check_carry_from_aci: assert property (
        @(posedge clk) (A & Ci) |-> Co
    );

    // A low must force carry low.
    check_no_carry_when_a_low: assert property (
        @(posedge clk) (!A) |-> (!Co)
    );

    // With only A high, carry must remain low.
    check_no_carry_with_a_only: assert property (
        @(posedge clk) (A & !B & !Ci) |-> (!Co)
    );

endmodule

