    // With B1, C1, and D1 high, A1 can drive the output high.
    check_a1_path_drives_output: assert property (
        @(posedge clk) (A1 & B1 & C1 & D1) |-> X
    );

    // With B1, C1, and D1 high, A2 can drive the output high.
    check_a2_path_drives_output: assert property (
        @(posedge clk) (A2 & B1 & C1 & D1) |-> X
    );

    // A high output implies all required product terms are satisfied.
    check_output_implies_inputs: assert property (
        @(posedge clk) X |-> (B1 & C1 & D1 & (A1 | A2))
    );

endmodule

rtl:
module barrel_shifter(
  input [3:0] data_in,
  input [1:0] shift_amt,
  output [3:0] data_out
);

  assign data_out = (shift_amt == 2'b00) ? data_in :
                    (shift_amt == 2'b01) ? {data_in[2:0], 1'b0} :
                    (shift_amt == 2'b10) ? {data_in[1:0], 2'b00} :
                                          {data_in[0], 3'b000};

endmodule

sva:
module barrel_shifter_sva(
    input logic clk,
    input logic [3:0] data_in,
    input logic [1:0] shift_amt,
    input logic [3:0] data_out
);

    // Shift amount 0 passes the input through unchanged.
    check_no_shift_passthrough: assert property (
        @(posedge clk) (shift_amt == 2'b00) |-> (data_out == data_in)
    );

    // Shift amount 1 shifts left by one and inserts 0 in bit 0.
    check_shift_by_one: assert property (
        @(posedge clk) (shift_amt == 2'b01) |-> (data_out == {data_in[2:0], 1'b0})
    );

    // Shift amount 2 shifts left by two and inserts 0s in bits [1:0].
    check_shift_by_two: assert property (
        @(posedge clk) (shift_amt == 2'b10) |-> (data_out == {data_in[1:0], 2'b00})
    );

    // Shift amount 3 shifts left by three and inserts 0s in bits [2:0].
    check_shift_by_three: assert property (
        @(posedge clk) (shift_amt == 2'b11) |-> (data_out == {data_in[0], 3'b000})
    );

endmodule

rtl:
module	Reset_Delay(iCLK,iRST,oRST_0,oRST_1,oRST_2);
input		iCLK;
input		iRST;
output reg	oRST_0;
output reg	oRST_1;
output reg	oRST_2;

reg	[31:0]	Cont;

always@(posedge iCLK or negedge iRST)
begin
	if(!iRST)
	begin
		Cont	<=	0;
		oRST_0	<=	0;
		oRST_1	<=	0;
		oRST_2	<=	0;
	end
	else
	begin
		if(Cont!=32'h114FFFF)
		Cont	<=	Cont+1;
		if(Cont>=32'h1FFFFF)
		oRST_0	<=	1;
		if(Cont>=32'h2FFFFF)
		oRST_1	<=	1;
		if(Cont>=32'h114FFFF)
		oRST_2	<=	1;
	end
end

endmodule

sva:
module Reset_Delay_sva (
    input logic iCLK,
    input logic iRST,
    input logic oRST_0,
    input logic oRST_1,
    input logic oRST_2
);

    // Formal starts with reset asserted.
    init_reset_assumption: assume property (
        @(posedge iCLK) $initstate |-> (iRST == 1'b0)
    );

    // Active-low reset clears all delayed reset outputs.
    check_reset_clears_outputs: assert property (
        @(posedge iCLK) (!iRST) |-> ((oRST_0 == 1'b0) && (oRST_1 == 1'b0) && (oRST_2 == 1'b0))
    );

    // The first sampled cycle after reset release still has all outputs low.
    check_release_keeps_outputs_low: assert property (
        @(posedge iCLK) disable iff (!iRST)
        $rose(iRST) |-> ((oRST_0 == 1'b0) && (oRST_1 == 1'b0) && (oRST_2 == 1'b0))
    );

    // oRST_0 stays high until reset once it has asserted.
    check_oRST_0_sticky_high: assert property (
        @(posedge iCLK) disable iff (!iRST)
        $past(oRST_0) |-> (oRST_0 == 1'b1)
    );

    // oRST_1 stays high until reset once it has asserted.
    check_oRST_1_sticky_high: assert property (
        @(posedge iCLK) disable iff (!iRST)
        $past(oRST_1) |-> (oRST_1 == 1'b1)
    );

    // oRST_2 stays high until reset once it has asserted.
    check_oRST_2_sticky_high: assert property (
        @(posedge iCLK) disable iff (!iRST)
        $past(oRST_2) |-> (oRST_2 == 1'b1)
    );

    // oRST_1 cannot be high unless oRST_0 is already high.
    check_oRST_1_requires_oRST_0: assert property (
        @(posedge iCLK) disable iff (!iRST)
        (oRST_1 == 1'b1) |-> (oRST_0 == 1'b1)
    );

    // oRST_2 cannot be high unless both earlier outputs are high.
    check_oRST_2_requires_lower_resets: assert property (
        @(posedge iCLK) disable iff (!iRST)
        (oRST_2 == 1'b1) |-> ((oRST_1 == 1'b1) && (oRST_0 == 1'b1))
    );

    // oRST_0 asserts before either later delayed reset asserts.
    check_oRST_0_rises_first: assert property (
        @(posedge iCLK) disable iff (!iRST)
        $rose(oRST_0) |-> ((oRST_1 == 1'b0) && (oRST_2 == 1'b0))
    );

    // oRST_1 asserts only after oRST_0 and before oRST_2.
    check_oRST_1_rises_second: assert property (
        @(posedge iCLK) disable iff (!iRST)
        $rose(oRST_1) |-> ((oRST_0 == 1'b1) && (oRST_2 == 1'b0))
    );

    // oRST_2 asserts only after both earlier delayed resets are high.
    check_oRST_2_rises_last: assert property (
        @(posedge iCLK) disable iff (!iRST)
        $rose(oRST_2) |-> ((oRST_0 == 1'b1) && (oRST_1 == 1'b1))
    );

endmodule

rtl:
module mux_2to1(
    input wire A0,
    input wire A1,
    input wire S,
    output wire X
);

assign X = (S == 0) ? A0 : A1;

endmodule

sva:
module mux_2to1_sva(
    input logic clk,
    input logic A0,
    input logic A1,
    input logic S,
    input logic X
);

    // When select is low, the output follows A0.
    check_select_low_routes_a0: assert property (
        @(posedge clk) (S === 1'b0) |-> (X === A0)
    );

    // When select is high, the output follows A1.
    check_select_high_routes_a1: assert property (
        @(posedge clk) (S === 1'b1) |-> (X === A1)
    );

    // With select held low, changes on A1 alone do not affect the output.
    check_a1_ignored_when_select_low: assert property (
        @(posedge clk)
        !$initstate &&
        (S === 1'b0) && ($past(S) === 1'b0) &&
        (A0 === $past(A0)) && (A1 !== $past(A1))
        |-> (X === $past(X))
    );

    // With select held high, changes on A0 alone do not affect the output.
    check_a0_ignored_when_select_high: assert property (
        @(posedge clk)
        !$initstate &&
        (S === 1'b1) && ($past(S) === 1'b1) &&
        (A1 === $past(A1)) && (A0 !== $past(A0))
        |-> (X === $past(X))
    );

    // A low-to-high select change switches the output to A1 when data inputs are stable.
    check_select_rise_routes_a1: assert property (
        @(posedge clk)
        !$initstate &&
        ($past(S) === 1'b0) && (S === 1'b1) &&
        (A0 === $past(A0)) && (A1 === $past(A1))
        |-> (X === A1)
    );

    // A high-to-low select change switches the output to A0 when data inputs are stable.
    check_select_fall_routes_a0: assert property (
        @(posedge clk)
        !$initstate &&
        ($past(S) === 1'b1) && (S === 1'b0) &&
        (A0 === $past(A0)) && (A1 === $past(A1))
        |-> (X === A0)
    );

    // With select held low, a change on A0 propagates to the output.
    check_a0_change_propagates_when_select_low: assert property (
        @(posedge clk)
        !$initstate &&
        (S === 1'b0) && ($past(S) === 1'b0) &&
        (A1 === $past(A1)) && (A0 !== $past(A0))
        |-> (X === A0) && (X !== $past(X))
    );

    // With select held high, a change on A1 propagates to the output.
    check_a1_change_propagates_when_select_high: assert property (
        @(posedge clk)
        !$initstate &&
        (S === 1'b1) && ($past(S) === 1'b1) &&
        (A0 === $past(A0)) && (A1 !== $past(A1))
        |-> (X === A1) && (X !== $past(X))
    );

endmodule

module bcd_to_binary_assertions (
    input logic        clk,
    input logic [3:0]  bcd0,
    input logic [3:0]  bcd1,
    input logic [3:0]  bcd2,
    input logic [3:0]  bcd3,
    input logic [3:0]  bin
);

    function automatic [3:0] expected_bin (
        input logic [3:0] d0,
        input logic [3:0] d1,
        input logic [3:0] d2,
        input logic [3:0] d3
    );
        begin
            expected_bin = (d3 * 1000) + (d2 * 100) + (d1 * 10) + d0;
        end
    endfunction

    // bin matches the RTL weighted sum with 4-bit truncation.
    check_weighted_sum: assert property (
        @(posedge clk) bin == expected_bin(bcd0, bcd1, bcd2, bcd3)
    );

    // All-zero inputs produce a zero output.
    check_zero_input_zero_output: assert property (
        @(posedge clk) (bcd0 == 4'd0 && bcd1 == 4'd0 && bcd2 == 4'd0 && bcd3 == 4'd0) |-> (bin == 4'd0)
    );

    // With only the ones digit active, bin equals bcd0.
    check_ones_digit_passthrough: assert property (
        @(posedge clk) (bcd1 == 4'd0 && bcd2 == 4'd0 && bcd3 == 4'd0) |-> (bin == bcd0)
    );

    // With only the tens digit active, bin matches the truncated tens contribution.
    check_tens_digit_only: assert property (
        @(posedge clk) (bcd0 == 4'd0 && bcd2 == 4'd0 && bcd3 == 4'd0) |-> (bin == expected_bin(4'd0, bcd1, 4'd0, 4'd0))
    );

    // With only the hundreds digit active, bin matches the truncated hundreds contribution.
    check_hundreds_digit_only: assert property (
        @(posedge clk) (bcd0 == 4'd0 && bcd1 == 4'd0 && bcd3 == 4'd0) |-> (bin == expected_bin(4'd0, 4'd0, bcd2, 4'd0))
    );

    // With only the thousands digit active, bin matches the truncated thousands contribution.
    check_thousands_digit_only: assert property (
        @(posedge clk) (bcd0 == 4'd0 && bcd1 == 4'd0 && bcd2 == 4'd0) |-> (bin == expected_bin(4'd0, 4'd0, 4'd0, bcd3))
    );

    // The output LSB is determined solely by the ones digit.
    check_lsb_depends_on_bcd0_only: assert property (
        @(posedge clk) bin[0] == bcd0[0]
    );

    // Stable inputs keep the combinational output stable across samples.
    check_stable_inputs_stable_output: assert property (
        @(posedge clk) $stable({bcd3, bcd2, bcd1, bcd0}) |-> $stable(bin)
    );

endmodule

rtl:
module and_nor (
    Y   ,
    A1  ,
    A2  ,
    B1_N
);

    // Module ports
    output Y   ;
    input  A1  ;
    input  A2  ;
    input  B1_N;

    // Module supplies
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    // Local signals
    wire b         ;
    wire and0_out  ;
    wire nor0_out_Y;

    //  Name  Output      Other arguments
    not not0 (b         , B1_N           );
    and and0 (and0_out  , A1, A2         );
    nor nor0 (nor0_out_Y, b, and0_out    );
    buf buf0 (Y         , nor0_out_Y     );

endmodule

sva:
module and_nor_sva (
    input logic clk,
    input logic Y,
    input logic A1,
    input logic A2,
    input logic B1_N
);

    // Y matches the implemented gate equation.
    check_y_matches_gate_equation: assert property (
        @(posedge clk) Y == ~(~B1_N | (A1 & A2))
    );

    // Low B1_N forces Y low.
    check_b1_n_low_forces_y_low: assert property (
        @(posedge clk) !B1_N |-> !Y
    );

    // A1 and A2 high together force Y low.
    check_a1_a2_high_force_y_low: assert property (
        @(posedge clk) (A1 && A2) |-> !Y
    );

    // High B1_N with low A1 makes Y high.
    check_b1_n_high_a1_low_drives_y_high: assert property (
        @(posedge clk) (B1_N && !A1) |-> Y
    );

    // High B1_N with low A2 makes Y high.
    check_b1_n_high_a2_low_drives_y_high: assert property (
        @(posedge clk) (B1_N && !A2) |-> Y
    );

    // Y high requires B1_N high.
    check_y_high_requires_b1_n_high: assert property (
        @(posedge clk) Y |-> B1_N
    );

    // Y high means A1 and A2 are not both high.
    check_y_high_requires_not_a1_a2_high: assert property (
        @(posedge clk) Y |-> !(A1 && A2)
    );

    // Low Y with high B1_N requires both A inputs high.
    check_y_low_with_b1_n_high_requires_a1_a2_high: assert property (
        @(posedge clk) (!Y && B1_N) |-> (A1 && A2)
    );

endmodule

rtl:
module counter(
    input clk,
    input rst,
    output reg [3:0] count
);

    always @(posedge clk or negedge rst) begin
        if (!rst) begin
            count <= 0;
        end else begin
            count <= count + 1;
        end
    end

endmodule

sva:
module counter_sva (
    input logic       clk,
    input logic       rst,
    input logic [3:0] count
);

    // Reset drives count to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) (!rst) |-> (count == 4'd0)
    );

    // When count is below 15, it increments by one on the next clock.
    check_count_increments: assert property (
        @(posedge clk) disable iff (!rst)
        (count != 4'hF) |=> (count == ($past(count) + 4'd1))
    );

    // When count reaches 15, it wraps to zero on the next clock.
    check_count_wraps: assert property (
        @(posedge clk) disable iff (!rst)
        (count == 4'hF) |=> (count == 4'h0)
    );

endmodule

rtl:
module data_modifier(
    input [31:0] reg_input,
    input [3:0] address,
    input reg_out_syn,
    input ack,
    input ack_syn,
    output reg [31:0] reg_out
);

reg [31:0] shifted_input;
reg [31:0] reversed_input;
reg [31:0] reg_out_nxt;

always @(*) begin
    if (ack && !ack_syn) begin
        shifted_input = {reg_input[30:0], 1'b0};
        reg_out_nxt     = shifted_input;
    end
    else if (!ack && ack_syn) begin
        shifted_input = {1'b0, reg_input[31:1]};
        reg_out_nxt     = shifted_input;
    end
    else if (ack && ack_syn) begin
        reversed_input = {reg_input[7:0], reg_input[15:8], reg_input[23:16], reg_input[31:24]};
        reg_out_nxt     = reversed_input;
    end
    else begin
        reg_out_nxt = reg_input;
    end
end

wire reg_out_syn_nxt;
assign reg_out_syn_nxt = ack || ack_syn;

reg reg_out_syn_nxt_r;
always @(*) begin
    reg_out_syn_nxt_r = reg_out_syn_nxt;
end

reg reg_out_syn_r;
always @(*) begin
    reg_out_syn_r <= reg_out_syn_nxt_r;
end

assign reg_out_syn = reg_out_syn_r;

always @(*) begin
    reg_out = reg_out_nxt;
end

endmodule

sva:
module data_modifier_sva (
    input logic        clk,
    input logic [31:0] reg_input,
    input logic [3:0]  address,
    input logic        reg_out_syn,
    input logic        ack,
    input logic        ack_syn,
    input logic [31:0] reg_out
);

    // Sampled on external clk because the RTL has no clock or reset.

    // ack=1 and ack_syn=0 selects a left shift by one bit.
    check_left_shift: assert property (
        @(posedge clk)
        $stable({reg_input, ack, ack_syn}) && ack && !ack_syn
        |-> reg_out == {reg_input[30:0], 1'b0}
    );

    // ack=0 and ack_syn=1 selects a right shift by one bit.
    check_right_shift: assert property (
        @(posedge clk)
        $stable({reg_input, ack, ack_syn}) && !ack && ack_syn
        |-> reg_out == {1'b0, reg_input[31:1]}
    );

    // ack=1 and ack_syn=1 selects the byte-reversed value.
    check_byte_reverse: assert property (
        @(posedge clk)
        $stable({reg_input, ack, ack_syn}) && ack && ack_syn
        |-> reg_out == {reg_input[7:0], reg_input[15:8], reg_input[23:16], reg_input[31:24]}
    );

    // ack=0 and ack_syn=0 passes reg_input through unchanged.
    check_passthrough: assert property (
        @(posedge clk)
        $stable({reg_input, ack, ack_syn}) && !ack && !ack_syn
        |-> reg_out == reg_input
    );

    // Stable data and control inputs keep reg_out stable.
    check_output_stable_for_stable_inputs: assert property (
        @(posedge clk)
        $stable({reg_input, ack, ack_syn})
        |-> $stable(reg_out)
    );

    // Changing address alone does not affect reg_out.
    check_address_no_effect: assert property (
        @(posedge clk)
        $changed(address) && $stable({reg_input, ack, ack_syn})
        |-> $stable(reg_out)
    );

    // Changing reg_out_syn alone does not affect reg_out.
    check_reg_out_syn_no_effect_on_reg_out: assert property (
        @(posedge clk)
        $changed(reg_out_syn) && $stable({reg_input, ack, ack_syn})
        |-> $stable(reg_out)
    );

endmodule

rtl:
module Counter(CLK, RST, Q_OUT, DATA_A, ADDA, DATA_B, ADDB, DATA_C, SETC, DATA_F, SETF);

   parameter width = 1;
   parameter init = 0;

   input CLK;
   input RST;
   input [width - 1 : 0] DATA_A;
   input ADDA;
   input [width - 1 : 0] DATA_B;
   input ADDB;
   input [width - 1 : 0] DATA_C;
   input SETC;
   input [width - 1 : 0] DATA_F;
   input SETF;

   output [width - 1 : 0] Q_OUT;

   reg [width - 1 : 0] q_state;

   assign Q_OUT = q_state;

   always @(posedge CLK) begin
      if (RST) begin
         q_state <= init;
      end else if (SETF) begin
         q_state <= DATA_F;
      end else if (SETC) begin
         q_state <= DATA_C;
      end else if (ADDA) begin
         q_state <= q_state + DATA_A;
      end else if (ADDB) begin
         q_state <= q_state + DATA_B;
      end
   end

endmodule

sva:
module Counter_sva #(
    parameter int width = 1,
    parameter logic [width - 1 : 0] init = '0
) (
    input logic CLK,
    input logic RST,
    input logic [width - 1 : 0] Q_OUT,
    input logic [width - 1 : 0] DATA_A,
    input logic ADDA,
    input logic [width - 1 : 0] DATA_B,
    input logic ADDB,
    input logic [width - 1 : 0] DATA_C,
    input logic SETC,
    input logic [width - 1 : 0] DATA_F,
    input logic SETF
);

    // Reset loads the counter to init.
    check_reset_loads_init: assert property (
        @(posedge CLK) RST |=> (Q_OUT == init)
    );

    // SETF has highest non-reset priority and loads DATA_F.
    check_setf_loads_data_f: assert property (
        @(posedge CLK) disable iff (RST)
        SETF |=> (Q_OUT == $past(DATA_F))
    );

    // SETC loads DATA_C when SETF is low.
    check_setc_loads_data_c: assert property (
        @(posedge CLK) disable iff (RST)
        !SETF && SETC |=> (Q_OUT == $past(DATA_C))
    );

    // ADDA adds DATA_A when no higher-priority control is active.
    check_adda_updates_counter: assert property (
        @(posedge CLK) disable iff (RST)
        !SETF && !SETC && ADDA |=> (Q_OUT == ($past(Q_OUT) + $past(DATA_A)))
    );

    // ADDB adds DATA_B when no higher-priority control is active.
    check_addb_updates_counter: assert property (
        @(posedge CLK) disable iff (RST)
        !SETF && !SETC && !ADDA && ADDB |=> (Q_OUT == ($past(Q_OUT) + $past(DATA_B)))
    );

    // Without reset or controls, the counter holds its value.
    check_holds_without_controls: assert property (
        @(posedge CLK) disable iff (RST)
        !SETF && !SETC && !ADDA && !ADDB |=> (Q_OUT == $past(Q_OUT))
    );

endmodule

module binary_latch_with_reset_sva(
    input logic CLK,
    input logic RST,
    input logic D,
    input logic Q
);

    // Reset forces Q low on the following clock sample.
    check_reset_forces_zero: assert property (
        @(posedge CLK) RST |=> (Q == 1'b0)
    );

    // A high D is captured into Q on the next clock when not in reset.
    check_capture_one: assert property (
        @(posedge CLK) disable iff (RST) D |=> (Q == 1'b1)
    );

    // A low D is captured into Q on the next clock when not in reset.
    check_capture_zero: assert property (
        @(posedge CLK) disable iff (RST) !D |=> (Q == 1'b0)
    );

endmodule

rtl:
module BinaryMultiplier (A, B, Z);
input  A ;
input  B ;
output Z ;

   wire A_not, B_not, AB;

   not (A_not, A);
   not (B_not, B);
   and (AB, A_not, B_not);
   not (Z, AB);

endmodule

sva:
module BinaryMultiplier_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic Z
);

    // External sampling clock for this combinational DUT.

    // Z matches the implemented OR of A and B.
    check_z_is_or_of_inputs: assert property (
        @(posedge clk) Z == (A | B)
    );

    // Input 00 drives Z low.
    check_zero_zero_case: assert property (
        @(posedge clk) (!A && !B) |-> !Z
    );

    // Input 01 drives Z high.
    check_zero_one_case: assert property (
        @(posedge clk) (!A && B) |-> Z
    );

    // Input 10 drives Z high.
    check_one_zero_case: assert property (
        @(posedge clk) (A && !B) |-> Z
    );

    // Input 11 drives Z high.
    check_one_one_case: assert property (
        @(posedge clk) (A && B) |-> Z
    );

    // Z low can only occur for input 00.
    check_z_low_requires_both_inputs_low: assert property (
        @(posedge clk) !Z |-> (!A && !B)
    );

endmodule

rtl:
module dual_edge_triggered_flip_flop (
    input clk,
    input d,
    output q
);

reg q1, q2;

always @(posedge clk) begin
    q1 <= d;
end

always @(negedge clk) begin
    q2 <= q1;
end

assign q = q2;

endmodule

