	pbdebounce p4(clk,addFlag[4],btn_out[4]);
	pbdebounce p5(clk,addFlag[5],btn_out[5]);
	pbdebounce p6(clk,addFlag[6],btn_out[6]);
	pbdebounce p7(clk,addFlag[7],btn_out[7]);

