    check_nibble1_follows_btn1_rise: assert property (
        @(posedge clk) disable iff ($initstate)
        number[7:4] == ($past(number[7:4]) + {3'd0, $rose(btn_out[1])})
    );

    // btn_out[2] increments number[11:8] modulo 16.
    check_nibble2_follows_btn2_rise: assert property (
        @(posedge clk) disable iff ($initstate)
        number[11:8] == ($past(number[11:8]) + {3'd0, $rose(btn_out[2])})
    );

    // btn_out[3] increments number[15:12] modulo 16.
    check_nibble3_follows_btn3_rise: assert property (
        @(posedge clk) disable iff ($initstate)
        number[15:12] == ($past(number[15:12]) + {3'd0, $rose(btn_out[3])})
    );

    // btn_out[4] increments number[19:16] modulo 16.
    check_nibble4_follows_btn4_rise: assert property (
        @(posedge clk) disable iff ($initstate)
        number[19:16] == ($past(number[19:16]) + {3'd0, $rose(btn_out[4])})
    );

    // btn_out[5] increments number[23:20] modulo 16.
    check_nibble5_follows_btn5_rise: assert property (
        @(posedge clk) disable iff ($initstate)
        number[23:20] == ($past(number[23:20]) + {3'd0, $rose(btn_out[5])})
    );

    // btn_out[6] increments number[27:24] modulo 16.
    check_nibble6_follows_btn6_rise: assert property (
        @(posedge clk) disable iff ($initstate)
        number[27:24] == ($past(number[27:24]) + {3'd0, $rose(btn_out[6])})
    );

    // btn_out[7] increments number[31:28] modulo 16.
    check_nibble7_follows_btn7_rise: assert property (
        @(posedge clk) disable iff ($initstate)
        number[31:28] == ($past(number[31:28]) + {3'd0, $rose(btn_out[7])})
    );

    // Without any debounced button rise, number must hold.
    check_number_stable_without_btn_rise: assert property (
        @(posedge clk) disable iff ($initstate)
        !($rose(btn_out[0]) || $rose(btn_out[1]) || $rose(btn_out[2]) || $rose(btn_out[3]) ||
          $rose(btn_out[4]) || $rose(btn_out[5]) || $rose(btn_out[6]) || $rose(btn_out[7]))
        |-> (number == $past(number))
    );

    // Any observed number change must come from a debounced button rise.
    check_number_change_requires_btn_rise: assert property (
        @(posedge clk) disable iff ($initstate)
        (number != $past(number))
        |-> ($rose(btn_out[0]) || $rose(btn_out[1]) || $rose(btn_out[2]) || $rose(btn_out[3]) ||
             $rose(btn_out[4]) || $rose(btn_out[5]) || $rose(btn_out[6]) || $rose(btn_out[7]))
    );

endmodule

bind NumIn NumIn_sva u_NumIn_sva (
    .clk(clk),
    .addFlag(addFlag),
    .number(number),
    .btn_out(btn_out)
);

module counter_sva (
    input logic       clk,
    input logic       rst,
    input logic [3:0] count
);

    // Count matches the previous cycle's reset-or-increment update.
    check_count_state_update: assert property (
        @(posedge clk)
        !$initstate |-> (count == ($past(rst) ? 4'b0000 : ($past(count) + 4'b0001)))
    );

    // A reset cycle drives count to zero on the next sampled cycle.
    check_reset_clears_count: assert property (
        @(posedge clk)
        rst |=> (count == 4'b0000)
    );

    // After a reset cycle, the first cycle out of reset still shows zero.
    check_count_zero_after_reset: assert property (
        @(posedge clk) disable iff (rst)
        (!$initstate && $past(rst)) |-> (count == 4'b0000)
    );

    // In consecutive non-reset cycles, count increments by one modulo 16.
    check_count_increments: assert property (
        @(posedge clk) disable iff (rst)
        (!$initstate && !$past(rst)) |-> (count == ($past(count) + 4'b0001))
    );

endmodule

rtl:
module oh_iddr #(parameter DW      = 1 // width of data inputs
		 )
   (
    input 		clk, // clock
    input 		ce0, // 1st cycle enable
    input 		ce1, // 2nd cycle enable
    input [DW/2-1:0] 	din, // data input sampled on both edges of clock
    output reg [DW-1:0] dout // iddr aligned
    );

   reg [DW/2-1:0]     din_sl;
   reg [DW/2-1:0]     din_sh;
   reg 		      ce0_negedge;

   //########################
   // Pipeline valid for negedge
   //########################
   always @(posedge clk)
     ce0_negedge <= ce0;

   //########################
   // Dual edge sampling
   //########################

   always @(posedge clk)
     if (ce0)
       din_sl <= din;
   always @(negedge clk)
     if (ce0_negedge)
       din_sh <= din;

   //########################
   // Aign pipeline
   //########################
   always @(posedge clk)
     if (ce1)
       dout <= {din_sh, din_sl};

endmodule

sva:
module oh_iddr_sva #(parameter DW = 1) (
    input logic              clk,
    input logic              ce0,
    input logic              ce1,
    input logic [DW/2-1:0]   din,
    input logic [DW-1:0]     dout,
    input logic [DW/2-1:0]   din_sl,
    input logic [DW/2-1:0]   din_sh,
    input logic              ce0_negedge
);

    typedef logic [DW-1:0] dout_t;

    // clk is the only clock; there is no reset in this RTL.
    // ce0_negedge is the prior posedge copy of ce0.
    check_ce0_negedge_pipeline: assert property (
        @(posedge clk)
        ($past(1'b1) === 1'b1) |-> (ce0_negedge === $past(ce0))
    );

    // din_sl captures din on a posedge when ce0 was asserted.
    check_din_sl_capture: assert property (
        @(posedge clk)
        (($past(1'b1) === 1'b1) && ($past(ce0) === 1'b1)) |-> (din_sl === $past(din))
    );

    // din_sl holds when ce0 was not asserted.
    check_din_sl_hold: assert property (
        @(posedge clk)
        (($past(1'b1) === 1'b1) && ($past(ce0) !== 1'b1)) |-> (din_sl === $past(din_sl))
    );

    // din_sh captures din on a negedge when ce0_negedge was asserted.
    check_din_sh_capture: assert property (
        @(negedge clk)
        (($past(1'b1) === 1'b1) && ($past(ce0_negedge) === 1'b1)) |-> (din_sh === $past(din))
    );

    // din_sh holds when ce0_negedge was not asserted.
    check_din_sh_hold: assert property (
        @(negedge clk)
        (($past(1'b1) === 1'b1) && ($past(ce0_negedge) !== 1'b1)) |-> (din_sh === $past(din_sh))
    );

    // dout captures the concatenated sampled halves when ce1 was asserted.
    check_dout_capture: assert property (
        @(posedge clk)
        (($past(1'b1) === 1'b1) && ($past(ce1) === 1'b1)) |-> (dout === dout_t'({$past(din_sh), $past(din_sl)}))
    );

    // dout holds when ce1 was not asserted.
    check_dout_hold: assert property (
        @(posedge clk)
        (($past(1'b1) === 1'b1) && ($past(ce1) !== 1'b1)) |-> (dout === $past(dout))
    );

endmodule

bind oh_iddr oh_iddr_sva #(.DW(DW)) oh_iddr_sva_bind (
    .clk(clk),
    .ce0(ce0),
    .ce1(ce1),
    .din(din),
    .dout(dout),
    .din_sl(din_sl),
    .din_sh(din_sh),
    .ce0_negedge(ce0_negedge)
);

rtl:
module and_or_array
# (parameter width = 8, sel=1) 


(input [width-1:0] a,   
output y);


genvar i;
wire [width-1:1] x;

generate    

		if (sel==1)
			for (i=1; i<width; i=i+1) begin:forloop
				if (i == 1)
					assign x[1] = a[0] & a[1];
				else
					assign x[i] = a[i] & x[i-1];
			end
		else
			for (i=1; i<width; i=i+1) begin:forloop
				if (i == 1)
					assign x[1] = a[0] | a[1];
				else
					assign x[i] = a[i] | x[i-1];
			end
endgenerate

	assign y = x[width-1];

endmodule

sva:
module and_or_array_sva
#(
    parameter int width = 8,
    parameter int sel = 1
)
(
    input logic clk,
    input logic [width-1:0] a,
    input logic y
);

generate
    if (width > 1) begin : gen_valid_width
        if (sel == 1) begin : gen_and_mode
            // y matches the reduction AND of a.
            check_and_reduction: assert property (
                @(posedge clk) y == (&a)
            );

            // All input bits high drives y high.
            check_and_all_ones_drive_high: assert property (
                @(posedge clk) (&a) |-> y
            );

            // Any low input bit forces y low.
            check_and_any_zero_forces_low: assert property (
                @(posedge clk) !(&a) |-> !y
            );
        end
        else begin : gen_or_mode
            // y matches the reduction OR of a.
            check_or_reduction: assert property (
                @(posedge clk) y == (|a)
            );

            // Any high input bit forces y high.
            check_or_any_one_forces_high: assert property (
                @(posedge clk) (|a) |-> y
            );

            // All input bits low drives y low.
            check_or_all_zeros_drive_low: assert property (
                @(posedge clk) !(|a) |-> !y
            );
        end
    end
endgenerate

endmodule

