module top_module(
    input [99:0] in,
    output [3:0] and_out,
    output [3:0] or_out,
    output [3:0] xor_out
);

    and_or_xor and_or_xor_inst(.a(in[3:0]), .b(in[7:4]), .and_out(and_out), .or_out(or_out), .xor_out(xor_out));

