sva:
module top_module_sva (
    input logic        clk,
    input logic [99:0] in,
    input logic [3:0]  and_out,
    input logic [3:0]  or_out,
    input logic [3:0]  xor_out
);

    // and_out is the bitwise AND of the two active input nibbles.
    check_and_matches_bitwise_and: assert property (
        @(posedge clk) and_out == (in[3:0] & in[7:4])
    );

    // or_out is the bitwise OR of the two active input nibbles.
    check_or_matches_bitwise_or: assert property (
        @(posedge clk) or_out == (in[3:0] | in[7:4])
    );

    // xor_out is the bitwise XOR of the two active input nibbles.
    check_xor_matches_bitwise_xor: assert property (
        @(posedge clk) xor_out == (in[3:0] ^ in[7:4])
    );

    // Any bit set in and_out must also be set in or_out.
    check_and_is_subset_of_or: assert property (
        @(posedge clk) (and_out & ~or_out) == 4'b0000
    );

    // xor_out and and_out cannot share a set bit.
    check_xor_and_and_do_not_overlap: assert property (
        @(posedge clk) (xor_out & and_out) == 4'b0000
    );

    // xor_out equals or_out with the common set bits removed.
    check_xor_matches_or_minus_and: assert property (
        @(posedge clk) xor_out == (or_out & ~and_out)
    );

    // Equal input nibbles force xor_out low.
    check_equal_inputs_force_zero_xor: assert property (
        @(posedge clk) (in[3:0] == in[7:4]) |-> (xor_out == 4'b0000)
    );

    // A zero nibble on either side forces and_out low.
    check_zero_input_forces_zero_and: assert property (
        @(posedge clk) ((in[3:0] == 4'b0000) || (in[7:4] == 4'b0000)) |-> (and_out == 4'b0000)
    );

    // All-zero active inputs force all outputs low.
    check_all_zero_inputs_force_zero_outputs: assert property (
        @(posedge clk) (in[7:0] == 8'b00000000) |-> ((and_out == 4'b0000) && (or_out == 4'b0000) && (xor_out == 4'b0000))
    );

    // All-one active inputs force AND and OR high and XOR low.
    check_all_one_inputs_force_expected_outputs: assert property (
        @(posedge clk) (in[7:0] == 8'b11111111) |-> ((and_out == 4'b1111) && (or_out == 4'b1111) && (xor_out == 4'b0000))
    );

endmodule

module mux2to1_sva (
    input logic clk,
    input logic a,
    input logic b,
    input logic sel,
    input logic out
);

    // When sel is low, the output must match a.
    check_sel_low_routes_a: assert property (
        @(posedge clk) (sel === 1'b0) |-> (out === a)
    );

    // When sel is high, the output must match b.
    check_sel_high_routes_b: assert property (
        @(posedge clk) (sel === 1'b1) |-> (out === b)
    );

endmodule

rtl:
module binary_counter (
   input clk,
   input reset,
   input enable,
   output reg [2:0] count
);

   reg [2:0] shift_reg;
   reg [1:0] flip_flop;

   always @(posedge clk) begin
      if (reset) begin
         shift_reg <= 3'b0;
         flip_flop <= 2'b0;
         count <= 3'b0;
      end else if (enable) begin
         flip_flop <= {flip_flop[0], shift_reg[2]};
         shift_reg <= {flip_flop[1], shift_reg[2:1]};
         count <= shift_reg;
      end
   end

endmodule

sva:
module binary_counter_sva (
    input logic       clk,
    input logic       reset,
    input logic       enable,
    input logic [2:0] count,
    input logic [2:0] shift_reg,
    input logic [1:0] flip_flop
);

    // Reset clears shift_reg.
    check_reset_clears_shift_reg: assert property (
        @(posedge clk) reset |=> (shift_reg == 3'b000)
    );

    // Reset clears flip_flop.
    check_reset_clears_flip_flop: assert property (
        @(posedge clk) reset |=> (flip_flop == 2'b00)
    );

    // Reset clears count.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 3'b000)
    );

    // Enable updates flip_flop from its previous LSB and shift_reg MSB.
    check_enable_updates_flip_flop: assert property (
        @(posedge clk) disable iff (reset)
        enable |=> (flip_flop == { $past(flip_flop[0]), $past(shift_reg[2]) })
    );

    // Enable updates shift_reg from previous flip_flop[1] and shift_reg[2:1].
    check_enable_updates_shift_reg: assert property (
        @(posedge clk) disable iff (reset)
        enable |=> (shift_reg == { $past(flip_flop[1]), $past(shift_reg[2:1]) })
    );

    // Enable updates count with the previous shift_reg value.
    check_enable_updates_count: assert property (
        @(posedge clk) disable iff (reset)
        enable |=> (count == $past(shift_reg))
    );

    // Without enable, flip_flop holds its value.
    check_idle_holds_flip_flop: assert property (
        @(posedge clk) disable iff (reset)
        !enable |=> (flip_flop == $past(flip_flop))
    );

    // Without enable, shift_reg holds its value.
    check_idle_holds_shift_reg: assert property (
        @(posedge clk) disable iff (reset)
        !enable |=> (shift_reg == $past(shift_reg))
    );

    // Without enable, count holds its value.
    check_idle_holds_count: assert property (
        @(posedge clk) disable iff (reset)
        !enable |=> (count == $past(count))
    );

endmodule

module binary_counter_sva (
    input logic       clk,
    input logic       rst_n,
    input logic [3:0] count
);

    // Reset drives the counter to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) !rst_n |-> (count == 4'b0000)
    );

    // The first sampled cycle after reset release still sees zero.
    check_reset_release_starts_from_zero: assert property (
        @(posedge clk) disable iff (!rst_n) (!$past(rst_n)) |-> (count == 4'b0000)
    );

    // The counter increments by one when the previous value was not 15.
    check_count_increments_no_rollover: assert property (
        @(posedge clk) disable iff (!rst_n)
        ($past(rst_n) && ($past(count) != 4'hF)) |-> (count == ($past(count) + 4'd1))
    );

    // The counter wraps from 15 back to zero.
    check_count_rolls_over: assert property (
        @(posedge clk) disable iff (!rst_n)
        ($past(rst_n) && ($past(count) == 4'hF)) |-> (count == 4'h0)
    );

endmodule

rtl:
module adder_4bit (
  input [3:0] a,
  input [3:0] b,
  input cin,
  output [3:0] sum,
  output cout
);

wire [3:0] c;
assign c[0] = cin;

full_adder fa0(a[0],b[0],c[0],sum[0],c[1]);
full_adder fa1(a[1],b[1],c[1],sum[1],c[2]);
full_adder fa2(a[2],b[2],c[2],sum[2],c[3]);
full_adder fa3(a[3],b[3],c[3],sum[3],cout);

endmodule
module full_adder (
  input a,
  input b,
  input cin,
  output sum,
  output cout
);

wire s1, s2;
assign s1 = a ^ b;
assign s2 = s1 ^ cin;
assign sum = s2;
assign cout = (a & b) | (s1 & cin);

endmodule

sva:
module adder_4bit_sva (
    input logic clk,
    input logic [3:0] a,
    input logic [3:0] b,
    input logic cin,
    input logic [3:0] sum,
    input logic cout
);

    // Full 5-bit output matches the arithmetic sum of the inputs.
    check_full_result: assert property (
        @(posedge clk) {cout, sum} == ({1'b0, a} + {1'b0, b} + {4'b0, cin})
    );

    // Bit 0 sum is the XOR of a[0], b[0], and cin.
    check_sum_bit0: assert property (
        @(posedge clk) sum[0] == (a[0] ^ b[0] ^ cin)
    );

    // Bit 1 sum uses the carry generated by bit 0.
    check_sum_bit1: assert property (
        @(posedge clk) sum[1] == (
            a[1] ^ b[1] ^
            ((a[0] & b[0]) | ((a[0] ^ b[0]) & cin))
        )
    );

    // Bit 2 sum uses the ripple carry from bits 0 and 1.
    check_sum_bit2: assert property (
        @(posedge clk) sum[2] == (
            a[2] ^ b[2] ^
            (
                (a[1] & b[1]) |
                (
                    (a[1] ^ b[1]) &
                    (
                        (a[0] & b[0]) |
                        ((a[0] ^ b[0]) & cin)
                    )
                )
            )
        )
    );

    // Bit 3 sum uses the ripple carry from bits 0 through 2.
    check_sum_bit3: assert property (
        @(posedge clk) sum[3] == (
            a[3] ^ b[3] ^
            (
                (a[2] & b[2]) |
                (
                    (a[2] ^ b[2]) &
                    (
                        (a[1] & b[1]) |
                        (
                            (a[1] ^ b[1]) &
                            (
                                (a[0] & b[0]) |
                                ((a[0] ^ b[0]) & cin)
                            )
                        )
                    )
                )
            )
        )
    );

    // Carry out is the final ripple carry from the MSB stage.
    check_carry_out: assert property (
        @(posedge clk) cout == (
            (a[3] & b[3]) |
            (
                (a[3] ^ b[3]) &
                (
                    (a[2] & b[2]) |
                    (
                        (a[2] ^ b[2]) &
                        (
                            (a[1] & b[1]) |
                            (
                                (a[1] ^ b[1]) &
                                (
                                    (a[0] & b[0]) |
                                    ((a[0] ^ b[0]) & cin)
                                )
                            )
                        )
                    )
                )
            )
        )
    );

endmodule

rtl:
module HallwayRight(clk_vga, CurrentX, CurrentY, mapData, wall);

	input clk_vga;
	input [9:0]CurrentX;
	input [8:0]CurrentY;
	input [7:0]wall;

	output [7:0]mapData;

	reg [7:0]mColor;

	always @(posedge clk_vga) begin
		if((CurrentY < 40) && ~(CurrentX < 0)) begin
			mColor[7:0] <= wall;
		end 
		else if(~(CurrentX < 600)) begin
			mColor[7:0] <= wall;
		end
		else if((~(CurrentY < 440) && (CurrentX < 260)) || (~(CurrentY < 440) && ~(CurrentX < 380))) begin
			mColor[7:0] <= wall;
		end else
			mColor[7:0] <= 8'b10110110;

	end


	assign mapData = mColor;


endmodule

sva:
module HallwayRight_sva (
    input logic        clk_vga,
    input logic [9:0]  CurrentX,
    input logic [8:0]  CurrentY,
    input logic [7:0]  wall,
    input logic [7:0]  mapData
);

    // Top strip uses the wall color.
    check_top_strip_wall: assert property (
        @(posedge clk_vga)
        (CurrentY < 9'd40) |=> (mapData == $past(wall))
    );

    // Right side uses the wall color.
    check_right_side_wall: assert property (
        @(posedge clk_vga)
        (CurrentX >= 10'd600) |=> (mapData == $past(wall))
    );

    // Bottom-left region uses the wall color.
    check_bottom_left_wall: assert property (
        @(posedge clk_vga)
        (CurrentY >= 9'd440 && CurrentX < 10'd260) |=> (mapData == $past(wall))
    );

    // Bottom-right region uses the wall color.
    check_bottom_right_wall: assert property (
        @(posedge clk_vga)
        (CurrentY >= 9'd440 && CurrentX >= 10'd380) |=> (mapData == $past(wall))
    );

    // Upper interior region uses the default color.
    check_upper_interior_default: assert property (
        @(posedge clk_vga)
        (CurrentY >= 9'd40 && CurrentY < 9'd440 && CurrentX < 10'd600) |=> (mapData == 8'b10110110)
    );

    // Lower center opening uses the default color.
    check_lower_center_default: assert property (
        @(posedge clk_vga)
        (CurrentY >= 9'd440 && CurrentX >= 10'd260 && CurrentX < 10'd380) |=> (mapData == 8'b10110110)
    );

endmodule

rtl:
module IF_ID(clk,rst,if_pcplus4, stall, BJ,
	if_instr,id_pcplus4, id_instr
    );
	input clk,rst,stall, BJ;
	input wire [31:0] if_pcplus4,if_instr;
	output reg [31:0] id_pcplus4,id_instr;

	always @(posedge clk or posedge rst)
	begin
		if(rst)
		begin
			id_pcplus4 <= 4;
			id_instr <= 32'b100000;
		end
		else if(stall | BJ)
		begin
			id_pcplus4 <= if_pcplus4;
			id_instr <= 32'b100000;
		end
		else
		begin
			id_pcplus4 <= if_pcplus4;
			id_instr <= if_instr;
		end
	end
endmodule

sva:
module IF_ID_sva (
    input logic        clk,
    input logic        rst,
    input logic        stall,
    input logic        BJ,
    input logic [31:0] if_pcplus4,
    input logic [31:0] if_instr,
    input logic [31:0] id_pcplus4,
    input logic [31:0] id_instr
);

    // Reset sets id_pcplus4 to 4.
    check_reset_pcplus4: assert property (
        @(posedge clk) rst |-> (id_pcplus4 == 32'd4)
    );

    // Reset sets id_instr to the defined bubble value.
    check_reset_instr: assert property (
        @(posedge clk) rst |-> (id_instr == 32'h0000_0020)
    );

    // Stall or BJ causes pcplus4 capture and bubble insertion.
    check_stall_or_bj_behavior: assert property (
        @(posedge clk) disable iff (rst)
        (stall || BJ) |=> ((id_pcplus4 == $past(if_pcplus4)) &&
                           (id_instr   == 32'h0000_0020))
    );

    // Without stall or BJ, both outputs capture the input values.
    check_normal_capture: assert property (
        @(posedge clk) disable iff (rst)
        !(stall || BJ) |=> ((id_pcplus4 == $past(if_pcplus4)) &&
                            (id_instr   == $past(if_instr)))
    );

endmodule

module reg3_sync_reset_sva (
    input logic CLK,
    input logic RST,
    input logic [2:0] D,
    input logic [2:0] Q
);

    // Reset clears Q on the following clock sample.
    check_reset_clears_q: assert property (
        @(posedge CLK) disable iff ($initstate) RST |=> (Q == 3'b000)
    );

    // Across non-reset cycles, Q captures the prior value of D.
    check_data_capture_between_nonreset_cycles: assert property (
        @(posedge CLK) disable iff (RST) !RST |=> (Q == $past(D))
    );

    // Q always reflects either the prior reset or the prior D sample.
    check_registered_equation: assert property (
        @(posedge CLK) disable iff ($initstate) Q == ($past(RST) ? 3'b000 : $past(D))
    );

endmodule

rtl:
module soc_system_pio_aliveTest_cpu_s0 (
  // inputs:
  address,
  chipselect,
  clk,
  reset_n,
  write_n,
  writedata,

  // outputs:
  out_port,
  readdata
);

  output  [  1: 0] out_port;
  output  [ 31: 0] readdata;
  input   [  1: 0] address;
  input            chipselect;
  input            clk;
  input            reset_n;
  input            write_n;
  input   [ 31: 0] writedata;

  wire             clk_en;
  reg     [  1: 0] data_out;
  wire    [  1: 0] out_port;
  wire    [  1: 0] read_mux_out;
  wire    [ 31: 0] readdata;
  assign clk_en = 1;

  //s1, which is an e_avalon_slave
  assign read_mux_out = {2 {(address == 0)}} & data_out;

  always @(posedge clk or negedge reset_n) begin
    if (reset_n == 0) begin
      data_out <= 0;
    end else if (chipselect && ~write_n && (address == 0)) begin
      data_out <= writedata[1 : 0];
    end
  end

  assign readdata = {30'b0, read_mux_out};

  assign out_port = data_out;

endmodule

sva:
module soc_system_pio_aliveTest_cpu_s0_sva (
    input logic [1:0]  address,
    input logic        chipselect,
    input logic        clk,
    input logic        reset_n,
    input logic        write_n,
    input logic [31:0] writedata,
    input logic [1:0]  out_port,
    input logic [31:0] readdata
);

    // Clock: clk; reset: reset_n active low; mixed sequential/combinational logic.

    // Reset forces the registered output low.
    reset_clears_out_port: assert property (
        @(posedge clk) !reset_n |-> (out_port == 2'b00)
    );

    // Reset forces the readback value low.
    reset_clears_readdata: assert property (
        @(posedge clk) !reset_n |-> (readdata == 32'b0)
    );

    // Read data is always zero-extended in the upper 30 bits.
    read_upper_bits_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (readdata[31:2] == 30'b0)
    );

    // Address 0 returns the current output register value.
    read_addr_zero_returns_out_port: assert property (
        @(posedge clk) disable iff (!reset_n)
        (address == 2'b00) |-> (readdata == {30'b0, out_port})
    );

    // Nonzero addresses return zero.
    read_nonzero_addr_returns_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (address != 2'b00) |-> (readdata == 32'b0)
    );

    // A write to address 0 updates the output register with writedata[1:0].
    write_addr_zero_captures_low_bits: assert property (
        @(posedge clk) disable iff (!reset_n)
        (chipselect && !write_n && (address == 2'b00)) |=> (out_port == $past(writedata[1:0]))
    );

    // When not selected, the output register holds its value.
    unselected_cycle_holds_out_port: assert property (
        @(posedge clk) disable iff (!reset_n)
        (!chipselect) |=> (out_port == $past(out_port))
    );

    // Read cycles do not modify the output register.
    read_cycle_holds_out_port: assert property (
        @(posedge clk) disable iff (!reset_n)
        (chipselect && write_n) |=> (out_port == $past(out_port))
    );

    // Writes to nonzero addresses do not modify the output register.
    write_nonzero_addr_holds_out_port: assert property (
        @(posedge clk) disable iff (!reset_n)
        (chipselect && !write_n && (address != 2'b00)) |=> (out_port == $past(out_port))
    );

endmodule

rtl:
module barrel_shifter_8bit(
    input [7:0] data_in,
    input [2:0] shift_amount,
    output reg [7:0] data_out
);

always @(*) begin
    if (shift_amount > 7) begin
        data_out = 8'b0;
    end else begin
        data_out = data_in << shift_amount;
    end
end

endmodule

sva:
module barrel_shifter_8bit_sva(
    input logic [7:0] data_in,
    input logic [2:0] shift_amount,
    input logic [7:0] data_out
);

    // Shift amount 0 passes the input through.
    check_shift_amt_0: assert property (
        @($global_clock) disable iff (1'b0)
        (shift_amount == 3'd0) |-> (data_out == data_in)
    );

    // Shift amount 1 shifts left by one and inserts a zero LSB.
    check_shift_amt_1: assert property (
        @($global_clock) disable iff (1'b0)
        (shift_amount == 3'd1) |-> (data_out == {data_in[6:0], 1'b0})
    );

    // Shift amount 2 shifts left by two and inserts two zero LSBs.
    check_shift_amt_2: assert property (
        @($global_clock) disable iff (1'b0)
        (shift_amount == 3'd2) |-> (data_out == {data_in[5:0], 2'b00})
    );

    // Shift amount 3 shifts left by three and inserts three zero LSBs.
    check_shift_amt_3: assert property (
        @($global_clock) disable iff (1'b0)
        (shift_amount == 3'd3) |-> (data_out == {data_in[4:0], 3'b000})
    );

    // Shift amount 4 shifts left by four and inserts four zero LSBs.
    check_shift_amt_4: assert property (
        @($global_clock) disable iff (1'b0)
        (shift_amount == 3'd4) |-> (data_out == {data_in[3:0], 4'b0000})
    );

    // Shift amount 5 shifts left by five and inserts five zero LSBs.
    check_shift_amt_5: assert property (
        @($global_clock) disable iff (1'b0)
        (shift_amount == 3'd5) |-> (data_out == {data_in[2:0], 5'b00000})
    );

    // Shift amount 6 shifts left by six and inserts six zero LSBs.
    check_shift_amt_6: assert property (
        @($global_clock) disable iff (1'b0)
        (shift_amount == 3'd6) |-> (data_out == {data_in[1:0], 6'b000000})
    );

    // Shift amount 7 leaves only bit 0 in the MSB position.
    check_shift_amt_7: assert property (
        @($global_clock) disable iff (1'b0)
        (shift_amount == 3'd7) |-> (data_out == {data_in[0], 7'b0000000})
    );

    // A zero input always produces a zero output.
    check_zero_input_zero_output: assert property (
        @($global_clock) disable iff (1'b0)
        (data_in == 8'h00) |-> (data_out == 8'h00)
    );

endmodule

rtl:
module password_protected_system (
    input clk,
    input d,
    input [255:0] password,
    input [2:0] sel,
    output out
);

    // Define the shift register
    reg [2:0] shift_reg;
    always @(posedge clk) begin
        shift_reg[0] <= d;
        shift_reg[1] <= shift_reg[0];
        shift_reg[2] <= shift_reg[1];
    end

    // Define the multiplexer for the shift register
    wire [2:0] shift_mux_sel = {1'b0, sel[1:0]};
    wire shift_mux_out;
    assign shift_mux_out = shift_reg[shift_mux_sel];

    // Define the multiplexer for the password
    wire [7:0] password_mux_sel = {1'b0, sel[1:0]};
    wire [2:0] password_mux_out;
    assign password_mux_out = password[password_mux_sel];

    // Define the comparator
    wire [2:0] comparator_out;
    assign comparator_out = (shift_mux_out == password_mux_out);

    // Generate the shifted password
    wire [255:0] shifted_password = password;
    wire [2:0] constant_sel = 3'b0;
    wire [7:0] shifted_password_mux_sel = {1'b0, constant_sel[1:0]};
    wire [2:0] shifted_password_mux_out;
    assign shifted_password_mux_out = shifted_password[shifted_password_mux_sel];

    // Define the AND gate
    assign out = (comparator_out & shifted_password_mux_out);

endmodule

sva:
module password_protected_system_sva (
    input logic clk,
    input logic d,
    input logic [255:0] password,
    input logic [2:0] sel,
    input logic out
);

    // password[0] low forces the final ANDed output low.
    check_password0_gates_output: assert property (
        @(posedge clk) (password[0] == 1'b0) |-> (out == 1'b0)
    );

    // Low selector bits 00 use the newest shifted data bit.
    check_sel0_uses_shift_stage0: assert property (
        @(posedge clk)
        (!$initstate && (sel[1:0] == 2'b00))
        |-> (out == (password[0] & ($past(d, 1) == password[0])))
    );

    // Low selector bits 01 use the next older shifted data bit.
    check_sel1_uses_shift_stage1: assert property (
        @(posedge clk)
        (!$initstate && !$past($initstate) && (sel[1:0] == 2'b01))
        |-> (out == (password[0] & ($past(d, 2) == password[1])))
    );

    // Low selector bits 10 use the oldest valid shifted data bit.
    check_sel2_uses_shift_stage2: assert property (
        @(posedge clk)
        (!$initstate && !$past($initstate) && !$past($initstate, 2) && (sel[1:0] == 2'b10))
        |-> (out == (password[0] & ($past(d, 3) == password[2])))
    );

endmodule

rtl:
module bw_io_cmos_edgelogic(
   // Outputs
   to_core, por, pad_up, bsr_up, pad_dn_l, bsr_dn_l,

   // Inputs
   data, oe, bsr_mode, por_l,
   bsr_data_to_core, se, rcvr_data
   );

input		data;
input		oe;
input		bsr_mode;
input		por_l;
input		se;
input		bsr_data_to_core;
input		rcvr_data;
supply0		vss;
output		pad_up;
output		pad_dn_l;
output		bsr_up;
output		bsr_dn_l;
output		por;
output		to_core;


// WIRES
wire pad_up;
wire pad_dn_l;
wire bsr_up;
wire bsr_dn_l;
wire por;
wire to_core;

assign bsr_up   = pad_up;
assign bsr_dn_l = pad_dn_l;
assign por      = ~por_l;
assign pad_up   =  data && oe;
assign pad_dn_l = ~(~data && oe);
assign to_core  = (bsr_mode && !se) ? bsr_data_to_core : rcvr_data;

endmodule

sva:
module bw_io_cmos_edgelogic_sva (
    input logic clk,
    input logic data,
    input logic oe,
    input logic bsr_mode,
    input logic por_l,
    input logic bsr_data_to_core,
    input logic se,
    input logic rcvr_data,
    input logic pad_up,
    input logic pad_dn_l,
    input logic bsr_up,
    input logic bsr_dn_l,
    input logic por,
    input logic to_core
);

    // por is the inverse of por_l.
    check_por_inversion: assert property (
        @(posedge clk) disable iff (1'b0) (por == ~por_l)
    );

    // pad_up is asserted only when data and oe are both high.
    check_pad_up_function: assert property (
        @(posedge clk) disable iff (1'b0) (pad_up == (data && oe))
    );

    // pad_dn_l follows the implemented active-low drive equation.
    check_pad_dn_l_function: assert property (
        @(posedge clk) disable iff (1'b0) (pad_dn_l == ~(~data && oe))
    );

    // bsr_up mirrors pad_up.
    check_bsr_up_mirror: assert property (
        @(posedge clk) disable iff (1'b0) (bsr_up == pad_up)
    );

    // bsr_dn_l mirrors pad_dn_l.
    check_bsr_dn_l_mirror: assert property (
        @(posedge clk) disable iff (1'b0) (bsr_dn_l == pad_dn_l)
    );

    // to_core follows the mux implemented in the RTL.
    check_to_core_mux_function: assert property (
        @(posedge clk) disable iff (1'b0)
        (to_core == ((bsr_mode && !se) ? bsr_data_to_core : rcvr_data))
    );

    // In boundary-scan mode with se low, to_core selects bsr_data_to_core.
    check_to_core_bsr_path: assert property (
        @(posedge clk) disable iff (1'b0)
        (bsr_mode && !se) |-> (to_core == bsr_data_to_core)
    );

    // Otherwise, to_core selects rcvr_data.
    check_to_core_rcvr_path: assert property (
        @(posedge clk) disable iff (1'b0)
        (!bsr_mode || se) |-> (to_core == rcvr_data)
    );

    // With output enable low, the pad outputs remain in their inactive state.
    check_outputs_when_oe_low: assert property (
        @(posedge clk) disable iff (1'b0)
        (!oe) |-> (!pad_up && pad_dn_l)
    );

    // With output enable high, both pad outputs track data as implemented.
    check_outputs_when_oe_high: assert property (
        @(posedge clk) disable iff (1'b0)
        oe |-> ((pad_up == data) && (pad_dn_l == data))
    );

endmodule

rtl:
module round_sat (
  input clk,
  input rst,
  input signed [15:0] in_val,
  input signed [15:0] min_val,
  input signed [15:0] max_val,
  output reg signed [15:0] out_round,
  output reg signed [15:0] out_sat
);

  always @(posedge clk) begin
    if (rst) begin
      out_round <= 0;
      out_sat <= 0;
    end
    else begin
      // Round block
      if (in_val[0]) begin
        out_round <= in_val + 1;
      end
      else begin
        out_round <= in_val;
      end

      // Saturation block
      if (in_val < min_val) begin
        out_sat <= min_val;
      end
      else if (in_val > max_val) begin
        out_sat <= max_val;
      end
      else begin
        out_sat <= in_val;
      end
    end
  end

endmodule

sva:
module round_sat_sva (
    input logic clk,
    input logic rst,
    input logic signed [15:0] in_val,
    input logic signed [15:0] min_val,
    input logic signed [15:0] max_val,
    input logic signed [15:0] out_round,
    input logic signed [15:0] out_sat
);

    // Synchronous reset clears both registered outputs.
    check_reset_clears_outputs: assert property (
        @(posedge clk)
        rst |=> (out_round == 16'sd0 && out_sat == 16'sd0)
    );

    // Odd input values are rounded up by one.
    check_round_odd_adds_one: assert property (
        @(posedge clk) disable iff (rst)
        in_val[0] |=> (out_round == ($past(in_val) + 16'sd1))
    );

    // Even input values pass through the round block unchanged.
    check_round_even_passthrough: assert property (
        @(posedge clk) disable iff (rst)
        !in_val[0] |=> (out_round == $past(in_val))
    );

    // Inputs below the minimum clamp to min_val.
    check_sat_low_clamps_to_min: assert property (
        @(posedge clk) disable iff (rst)
        (in_val < min_val) |=> (out_sat == $past(min_val))
    );

    // Inputs above the maximum clamp to max_val when not already below min_val.
    check_sat_high_clamps_to_max: assert property (
        @(posedge clk) disable iff (rst)
        (!(in_val < min_val) && (in_val > max_val)) |=> (out_sat == $past(max_val))
    );

    // Inputs within the range pass through the saturation block unchanged.
    check_sat_in_range_passthrough: assert property (
        @(posedge clk) disable iff (rst)
        (!(in_val < min_val) && !(in_val > max_val)) |=> (out_sat == $past(in_val))
    );

endmodule

rtl:
module sdio_function_template (
  input                     clk,
  input                     rst,
  output reg   [7:0]       o_reg_example,
  input         [7:0]       i_reg_example
);

  //local parameters
  localparam     PARAM1  = 32'h00000000;

  //registers/wires
  reg [7:0] temp_reg;

  //asynchronous logic
  always @ (posedge rst) begin
    temp_reg <= i_reg_example;
  end

  //synchronous logic
  always @ (posedge clk) begin
    o_reg_example <= temp_reg;
  end

endmodule

sva:
module sdio_function_template_assertions (
    input logic       clk,
    input logic       rst,
    input logic [7:0] o_reg_example,
    input logic [7:0] i_reg_example,
    input logic [7:0] temp_reg
);

    // Output reflects temp_reg sampled on the previous clk edge.
    check_output_captures_previous_temp_reg: assert property (
        @(posedge clk) disable iff (1'b0)
        1'b1 |=> (o_reg_example == $past(temp_reg))
    );

    // temp_reg reflects i_reg_example sampled on the previous rst edge.
    check_temp_reg_captures_previous_input_on_rst: assert property (
        @(posedge rst) disable iff (1'b0)
        1'b1 |=> (temp_reg == $past(i_reg_example))
    );

    // If temp_reg is unchanged across clk samples, output matches current temp_reg.
    check_output_matches_current_temp_when_temp_stable: assert property (
        @(posedge clk) disable iff (1'b0)
        1'b1 |=> ((temp_reg == $past(temp_reg)) |-> (o_reg_example == temp_reg))
    );

    // If temp_reg changes between clk samples, output still lags current temp_reg.
    check_output_lags_current_temp_when_temp_changes: assert property (
        @(posedge clk) disable iff (1'b0)
        1'b1 |=> ((temp_reg != $past(temp_reg)) |-> (o_reg_example != temp_reg))
    );

    // If input is unchanged across rst samples, temp_reg matches current input.
    check_temp_matches_current_input_when_input_stable: assert property (
        @(posedge rst) disable iff (1'b0)
        1'b1 |=> ((i_reg_example == $past(i_reg_example)) |-> (temp_reg == i_reg_example))
    );

    // If input changes between rst samples, temp_reg still lags current input.
    check_temp_lags_current_input_when_input_changes: assert property (
        @(posedge rst) disable iff (1'b0)
        1'b1 |=> ((i_reg_example != $past(i_reg_example)) |-> (temp_reg != i_reg_example))
    );

endmodule

