module logic_gate_sva (
    input logic A1,
    input logic A2,
    input logic A3,
    input logic A4,
    input logic B1,
    input logic Y
);

    // No clock or reset exists in the RTL; sample on the formal global clock.

    // Y must equal the implemented combinational expression.
    check_y_matches_logic_function: assert property (
        @($global_clock) Y == ((A1 & A2 & A3 & A4) | B1)
    );

    // B1 high forces Y high.
    check_b1_forces_y_high: assert property (
        @($global_clock) B1 |-> Y
    );

    // All A inputs high force Y high.
    check_all_a_inputs_force_y_high: assert property (
        @($global_clock) (A1 & A2 & A3 & A4) |-> Y
    );

    // If neither input term is active, Y must be low.
    check_no_active_term_means_y_low: assert property (
        @($global_clock) (!B1 && !(A1 & A2 & A3 & A4)) |-> !Y
    );

    // If Y is high while B1 is low, all A inputs must be high.
    check_y_high_without_b1_requires_all_a_high: assert property (
        @($global_clock) (Y && !B1) |-> (A1 & A2 & A3 & A4)
    );

endmodule

rtl:
module sync_ptr

    #(
    parameter ASIZE = 4
    )(
    input  wire              dest_clk,
    input  wire              dest_rst_n,
    input  wire [ASIZE:0] src_ptr,
    output reg  [ASIZE:0] dest_ptr
    );

    reg [ASIZE:0] ptr_x;

    always @(posedge dest_clk or negedge dest_rst_n) begin

        if (!dest_rst_n)
            {dest_ptr,ptr_x} <= 0;
        else
            {dest_ptr,ptr_x} <= {ptr_x,src_ptr};
    end

endmodule

`resetall

sva:
module sync_ptr_sva #(
    parameter ASIZE = 4
)(
    input logic              dest_clk,
    input logic              dest_rst_n,
    input logic [ASIZE:0]    src_ptr,
    input logic [ASIZE:0]    dest_ptr
);

    // Active-low reset clears the synchronized pointer.
    check_reset_clears_dest_ptr: assert property (
        @(posedge dest_clk)
        !dest_rst_n |-> (dest_ptr == '0)
    );

    // The first dest_clk after a sampled low reset still outputs zero.
    check_prev_reset_keeps_output_zero: assert property (
        @(posedge dest_clk) disable iff (!dest_rst_n)
        ($past(dest_rst_n,1) == 1'b0) |-> (dest_ptr == '0)
    );

    // With reset sampled high on consecutive clocks, output is prior src_ptr or zero.
    check_output_is_prev_src_or_zero: assert property (
        @(posedge dest_clk) disable iff (!dest_rst_n)
        ($past(dest_rst_n,1) == 1'b1) |-> ((dest_ptr == $past(src_ptr,1)) || (dest_ptr == '0))
    );

    // A nonzero output must match the previous sampled source pointer.
    check_nonzero_output_matches_prev_src: assert property (
        @(posedge dest_clk) disable iff (!dest_rst_n)
        (($past(dest_rst_n,1) == 1'b1) && (dest_ptr != '0)) |-> (dest_ptr == $past(src_ptr,1))
    );

    // A zero source sample propagates to a zero output on the next clock.
    check_zero_source_propagates: assert property (
        @(posedge dest_clk) disable iff (!dest_rst_n)
        (($past(dest_rst_n,1) == 1'b1) && ($past(src_ptr,1) == '0)) |-> (dest_ptr == '0)
    );

endmodule

module data_buffer_sva (
    input logic clk,
    input logic [7:0] A,
    input logic [15:0] Z,
    input logic TE_B,
    input logic VPB,
    input logic VPWR,
    input logic VGND,
    input logic VNB
);

    // When enabled, Z is A in the upper byte and zero in the lower byte.
    check_enabled_mapping: assert property (
        @(posedge clk) TE_B |-> (Z == {A, 8'h00})
    );

    // When disabled, Z is driven to zero.
    check_disabled_zero: assert property (
        @(posedge clk) !TE_B |-> (Z == 16'h0000)
    );

    // The upper byte of Z matches A whenever the buffer is enabled.
    check_enabled_upper_byte_matches_a: assert property (
        @(posedge clk) TE_B |-> (Z[15:8] == A)
    );

    // The lower byte of Z is always zero.
    check_lower_byte_always_zero: assert property (
        @(posedge clk) Z[7:0] == 8'h00
    );

    // A rising enable produces the enabled output mapping.
    check_enable_rise_sets_output: assert property (
        @(posedge clk) $rose(TE_B) |-> (Z == {A, 8'h00})
    );

    // A falling enable clears the output.
    check_enable_fall_clears_output: assert property (
        @(posedge clk) $fell(TE_B) |-> (Z == 16'h0000)
    );

endmodule

