sva:
module and_comb_sva (
    input logic clk,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic B2,
    input logic X
);

    // X must equal the AND of the two pairwise AND terms.
    check_x_matches_structural_and: assert property (
        @(posedge clk) X == ((A1 & A2) & (B1 & B2))
    );

    // Both input pairs high must drive X high.
    check_both_pairs_high_drive_x_high: assert property (
        @(posedge clk) ((A1 & A2) & (B1 & B2)) |-> X
    );

    // A low A-pair must force X low.
    check_a_pair_low_forces_x_low: assert property (
        @(posedge clk) !(A1 & A2) |-> !X
    );

    // A low B-pair must force X low.
    check_b_pair_low_forces_x_low: assert property (
        @(posedge clk) !(B1 & B2) |-> !X
    );

    // A high X requires both pairwise AND terms to be high.
    check_x_high_requires_both_pairs_high: assert property (
        @(posedge clk) X |-> ((A1 & A2) & (B1 & B2))
    );

endmodule

rtl:
module RegisterAdd_3
  (
    input clk,
    input rst,
    input load,
    input [0:0] D,
    output reg [0:0] Q
  );

  wire [0:0] Q_int;
  wire Q_int_n_0 ;

  assign Q_int = Q;

  assign Q_int_n_0 = load & Q;

  always @(posedge clk or posedge rst) begin
    if (rst) begin
      Q <= 1'b0;
    end else if (load) begin
      Q <= D;
    end
  end

endmodule

sva:
module RegisterAdd_3_sva (
    input logic clk,
    input logic rst,
    input logic load,
    input logic [0:0] D,
    input logic [0:0] Q
);

    // A sampled active reset must correspond to a low Q.
    check_reset_clears_q: assert property (
        @(posedge clk) disable iff ($initstate)
        rst |-> (Q == 1'b0)
    );

    // A reset cycle leaves Q low at the next clock sample.
    check_reset_keeps_q_low_next_cycle: assert property (
        @(posedge clk) disable iff ($initstate)
        rst |=> (Q == 1'b0)
    );

    // Loading a zero writes zero into Q.
    check_load_zero_captures_zero: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        (load && (D == 1'b0)) |=> (Q == 1'b0)
    );

    // With load low, a zero in Q stays zero.
    check_zero_holds_when_not_loading: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        (!load && (Q == 1'b0)) |=> (Q == 1'b0)
    );

    // A high Q must come from loading a one or holding a previous one.
    check_q_high_has_valid_source: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        (Q == 1'b1) |-> (
            !$past(rst) &&
            (($past(load) && ($past(D) == 1'b1)) ||
             (!$past(load) && ($past(Q) == 1'b1)))
        )
    );

    // A rise on Q can only be caused by loading a one on the prior cycle.
    check_q_rise_requires_load_one: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        (($past(Q) == 1'b0) && (Q == 1'b1)) |-> (
            !$past(rst) && $past(load) && ($past(D) == 1'b1)
        )
    );

endmodule

