module binary_counter (
    input clk,
    input reset,
    output reg [3:0] counter_out
);

    always @(posedge clk, posedge reset) begin
        if (reset) begin
            counter_out <= 4'b0000;
        end else begin
            counter_out <= counter_out + 1;
        end
    end

endmodule
module mux_2to1 (
    input [3:0] input_0,
    input [3:0] input_1,
    input select,
    output reg [3:0] mux_out
);

    always @(select) begin
        if (select) begin
            mux_out <= input_1;
        end else begin
            mux_out <= input_0;
        end
    end

endmodule
module comparator (
    input [3:0] in_0,
    input [3:0] in_1,
    output reg out
);

    always @(in_0, in_1) begin
        if (in_0 >= in_1) begin
            out <= 1;
        end else begin
            out <= 0;
        end
    end

endmodule
module pwm_generator (
    input clk,
    input reset,
    input [3:0] counter_out,
    input [3:0] adc_in,
    input select,
    output reg pwm_out
);

    wire [3:0] mux_out;
    wire comparator_out;

    mux_2to1 mux (
        .input_0(counter_out),
        .input_1(adc_in),
        .select(select),
        .mux_out(mux_out)
    );

    comparator comp (
        .in_0(mux_out),
        .in_1(adc_in),
        .out(comparator_out)
    );

    always @(posedge clk, posedge reset) begin
        if (reset) begin
            pwm_out <= 0;
        end else begin
            if (pwm_out == 1'b1 && comparator_out == 1'b0) begin
                pwm_out <= 1'b0;
            end else if (pwm_out == 1'b0 && comparator_out == 1'b1) begin
                pwm_out <= 1'b1;
            end
        end
    end

endmodule

sva:
module binary_counter_sva (
    input logic clk,
    input logic reset,
    input logic [3:0] counter_out
);

    // Clock: clk
    // Reset: reset, active-high asynchronous
    // Logic: sequential

    // Reset drives the counter output to zero.
    reset_clears_counter_out: assert property (
        @(posedge clk) disable iff ($initstate)
        reset |-> (counter_out == 4'b0000)
    );

    // Any nonzero sampled count must be the prior sampled count plus one.
    nonzero_count_is_prior_plus_one: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        (counter_out != 4'b0000) |-> (counter_out == ($past(counter_out) + 4'd1))
    );

    // A sampled decrease can only occur when the count lands at zero.
    sampled_decrease_only_to_zero: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        (counter_out < $past(counter_out)) |-> (counter_out == 4'b0000)
    );

endmodule

module pwm_generator_sva (
    input logic clk,
    input logic reset,
    input logic [3:0] counter_out,
    input logic [3:0] adc_in,
    input logic select,
    input logic pwm_out,
    input logic [3:0] mux_out,
    input logic comparator_out
);

    // Clock: clk
    // Reset: reset, active-high asynchronous
    // Logic: mixed; mux/comparator are combinational, pwm_out is sequential

    // Reset drives the PWM output low.
    reset_clears_pwm_out: assert property (
        @(posedge clk) disable iff ($initstate)
        reset |-> (pwm_out == 1'b0)
    );

    // Comparator output matches the greater-or-equal comparison.
    comparator_matches_ge_compare: assert property (
        @(posedge clk) disable iff (reset)
        comparator_out == (mux_out >= adc_in)
    );

    // A high PWM output turns off on the next cycle when comparator_out is low.
    turn_off_when_comparator_low: assert property (
        @(posedge clk) disable iff (reset)
        (pwm_out == 1'b1 && comparator_out == 1'b0) |=> (pwm_out == 1'b0)
    );

    // A low PWM output stays low on the next cycle when comparator_out is low.
    stay_low_when_comparator_low: assert property (
        @(posedge clk) disable iff (reset)
        (pwm_out == 1'b0 && comparator_out == 1'b0) |=> (pwm_out == 1'b0)
    );

    // A sampled high PWM state requires comparator_out to have been high previously.
    pwm_high_requires_prev_comparator_high: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        (pwm_out == 1'b1) |-> ($past(comparator_out) == 1'b1)
    );

    // PWM can only rise when comparator_out was high in the prior cycle.
    pwm_rise_requires_prev_comparator_high: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        $rose(pwm_out) |-> ($past(comparator_out) == 1'b1)
    );

endmodule

rtl:
module ripple_carry_adder(
    input [3:0] A,
    input [3:0] B,
    input CIN,
    output [3:0] SUM,
    output COUT
);

    wire [3:0] carry;

    full_adder fa0(.A(A[0]), .B(B[0]), .CIN(CIN), .SUM(SUM[0]), .COUT(carry[0]));
    full_adder fa1(.A(A[1]), .B(B[1]), .CIN(carry[0]), .SUM(SUM[1]), .COUT(carry[1]));
    full_adder fa2(.A(A[2]), .B(B[2]), .CIN(carry[1]), .SUM(SUM[2]), .COUT(carry[2]));
    full_adder fa3(.A(A[3]), .B(B[3]), .CIN(carry[2]), .SUM(SUM[3]), .COUT(COUT));

endmodule
module full_adder(
    input A,
    input B,
    input CIN,
    output SUM,
    output COUT
);

    assign SUM = A ^ B ^ CIN;
    assign COUT = (A & B) | (B & CIN) | (A & CIN);

endmodule

sva:
module ripple_carry_adder_sva(
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic CIN,
    input logic [3:0] SUM,
    input logic COUT
);

    // Full 5-bit result matches A + B + CIN.
    check_total_addition: assert property (
        @(posedge clk)
        {COUT, SUM} == ({1'b0, A} + {1'b0, B} + {4'b0, CIN})
    );

    // LSB sum matches the first full-adder XOR equation.
    check_lsb_xor: assert property (
        @(posedge clk)
        SUM[0] == (A[0] ^ B[0] ^ CIN)
    );

    // Carry-out matches arithmetic overflow.
    check_cout_overflow: assert property (
        @(posedge clk)
        COUT == (({1'b0, A} + {1'b0, B} + {4'b0, CIN}) >= 5'd16)
    );

    // Adding zero with no carry-in preserves A.
    check_add_zero_to_a: assert property (
        @(posedge clk)
        (B == 4'h0 && CIN == 1'b0) |-> (SUM == A && COUT == 1'b0)
    );

    // Adding zero with no carry-in preserves B.
    check_add_zero_to_b: assert property (
        @(posedge clk)
        (A == 4'h0 && CIN == 1'b0) |-> (SUM == B && COUT == 1'b0)
    );

    // With zero operands, only CIN contributes to the result.
    check_zero_operands_with_cin: assert property (
        @(posedge clk)
        (A == 4'h0 && B == 4'h0) |-> (SUM == {3'b000, CIN} && COUT == 1'b0)
    );

    // A carry-in can ripple through all four stages.
    check_full_carry_propagation: assert property (
        @(posedge clk)
        (A == 4'hF && B == 4'h0 && CIN == 1'b1) |-> (SUM == 4'h0 && COUT == 1'b1)
    );

    // Stable sampled inputs must keep sampled outputs stable.
    check_stable_inputs_stable_outputs: assert property (
        @(posedge clk)
        $stable({A, B, CIN}) |-> $stable({SUM, COUT})
    );

endmodule

