    );

    // S=10 selects the LSB of C onto Y.
    check_select_c_lsb: assert property (
        @($global_clock) (S == 2'b10) |-> (Y == C[0])
    );

    // S=11 selects the LSB of D onto Y.
    check_select_d_lsb: assert property (
        @($global_clock) (S == 2'b11) |-> (Y == D[0])
    );

