module xor2 (
    input A,
    input B,
    output X
);

    assign X = A ^ B;

endmodule

module xor4 (
    output X,
    input A,
    input B,
    input C,
    input D
);

    // Voltage supply signals
    wire X1, X2;
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB;
    supply0 VNB;

    xor2 u1 (.X(X1), .A(A), .B(B));
    xor2 u2 (.X(X2), .A(C), .B(D));
    xor2 u3 (.X(X), .A(X1), .B(X2));

endmodule

sva:
module xor4_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic X
);

    // X matches the XOR tree implemented in xor4.
    check_output_matches_xor_tree: assert property (
        @(posedge clk) disable iff ($initstate)
        X == ((A ^ B) ^ (C ^ D))
    );

    // An odd number of sampled input toggles makes X toggle.
    check_output_toggles_on_odd_input_toggle_parity: assert property (
        @(posedge clk) disable iff ($initstate)
        (((A ^ $past(A)) ^ (B ^ $past(B)) ^ (C ^ $past(C)) ^ (D ^ $past(D))) == 1'b1)
        |-> (X != $past(X))
    );

    // An even number of sampled input toggles keeps X unchanged.
    check_output_stable_on_even_input_toggle_parity: assert property (
        @(posedge clk) disable iff ($initstate)
        (((A ^ $past(A)) ^ (B ^ $past(B)) ^ (C ^ $past(C)) ^ (D ^ $past(D))) == 1'b0)
        |-> (X == $past(X))
    );

endmodule

rtl:
module mux4to1(
    input [3:0] in0,
    input [3:0] in1,
    input [3:0] in2,
    input [3:0] in3,
    input [1:0] sel,
    output reg [3:0] out
);

always @ (sel or in0 or in1 or in2 or in3) begin
    case (sel)
        2'b00: out = in0;
        2'b01: out = in1;
        2'b10: out = in2;
        2'b11: out = in3;
        default: out = 4'bx; // Handle the case of invalid selection
    endcase
end

endmodule

sva:
module mux4to1_sva (
    input logic [3:0] in0,
    input logic [3:0] in1,
    input logic [3:0] in2,
    input logic [3:0] in3,
    input logic [1:0] sel,
    input logic [3:0] out
);

    // No RTL clock or reset; sample this combinational mux on the formal global clock.

    // When sel is 00, out matches in0.
    check_select_in0: assert property (
        @($global_clock) (sel === 2'b00) |-> (out === in0)
    );

    // When sel is 01, out matches in1.
    check_select_in1: assert property (
