    // When sel is 10, out matches in2.
    check_select_in2: assert property (
        @($global_clock) (sel === 2'b10) |-> (out === in2)
    );

    // When sel is 11, out matches in3.
    check_select_in3: assert property (
        @($global_clock) (sel === 2'b11) |-> (out === in3)
    );

