rtl:
module shift_register (
    input clk,
    input reset,
    input d,
    output reg [2:0] q
);

    always @(posedge clk) begin
        if (reset) begin
            q <= 3'b000;
        end else begin
            q <= {q[1:0], d};
        end
    end

endmodule
module xor_gate (
    input a,
    input b,
    output wire y
);

    assign y = a ^ b;

endmodule
module functional_module (
    input [2:0] shift_reg_out,
    input a,
    input b,
    output wire y
);

    wire xor_out;

    xor_gate xor_gate_inst (
        .a(a),
        .b(b),
        .y(xor_out)
    );

    assign y = shift_reg_out[2] & xor_out;

endmodule
module top_module (
    input clk,
    input reset,
    input d,
    input a,
    input b,
    output reg out_always_ff,
    output [2:0] shift_reg_out,
    output wire functional_module_out
);

    shift_register shift_register_inst (
        .clk(clk),
        .reset(reset),
        .d(d),
        .q(shift_reg_out)
    );

    functional_module functional_module_inst (
        .shift_reg_out(shift_reg_out),
        .a(a),
        .b(b),
        .y(functional_module_out)
    );

    always @(posedge clk) begin
        if(reset) begin
            out_always_ff <= 1'b0;
        end else begin
            out_always_ff <= out_always_ff ? 1'b0 : functional_module_out;
        end
    end

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic reset,
    input logic d,
    input logic a,
    input logic b,
    input logic out_always_ff,
    input logic [2:0] shift_reg_out,
    input logic functional_module_out
);

    // Clock: clk; reset: active-high synchronous; logic: mixed sequential/combinational.

    // Reset clears the shift register on the following cycle.
    check_reset_clears_shift_register: assert property (
        @(posedge clk) reset |=> (shift_reg_out == 3'b000)
    );

    // Reset clears the top-level output flop on the following cycle.
    check_reset_clears_out_always_ff: assert property (
        @(posedge clk) reset |=> (out_always_ff == 1'b0)
    );

    // Reset forces the functional output low through the cleared shift register.
    check_reset_clears_functional_output: assert property (
        @(posedge clk) reset |=> (functional_module_out == 1'b0)
    );

    // The shift register shifts left and loads d into bit 0 each cycle.
    check_shift_register_update: assert property (
        @(posedge clk) disable iff (reset)
        (!$initstate && !$past(reset)) |-> (shift_reg_out == {$past(shift_reg_out[1:0]), $past(d)})
    );

    // The functional output matches shift_reg_out[2] AND (a XOR b).
    check_functional_module_logic: assert property (
        @(posedge clk) disable iff (reset)
        (functional_module_out == (shift_reg_out[2] & (a ^ b)))
    );

    // When the flop was low, it captures functional_module_out on the next cycle.
    check_out_ff_captures_functional_output: assert property (
        @(posedge clk) disable iff (reset)
        (!$initstate && !$past(reset) && !$past(out_always_ff)) |-> (out_always_ff == $past(functional_module_out))
    );

    // When the flop was high, it clears on the next cycle.
    check_out_ff_clears_after_high: assert property (
        @(posedge clk) disable iff (reset)
        (!$initstate && !$past(reset) && $past(out_always_ff)) |-> (out_always_ff == 1'b0)
    );

endmodule

rtl:
module r_RX_BUF_OBJ3_BYTE_3(output reg [7:0] reg_0x3F, input wire reset, input wire wenb, input wire [7:0] in_data, input wire clk);
	always@(posedge clk)
	begin
		if(reset==0) begin
			if(wenb==0)
				reg_0x3F<=in_data;
			else
				reg_0x3F<=reg_0x3F;
		end
		else
			reg_0x3F<=8'h00;
	end
endmodule

sva:
module r_RX_BUF_OBJ3_BYTE_3_sva (
    input logic [7:0] reg_0x3F,
    input logic reset,
    input logic wenb,
    input logic [7:0] in_data,
    input logic clk
);

    // Sampled state must match the RTL update function from the prior cycle.
    check_transition_matches_rtl: assert property (
        @(posedge clk) disable iff ($initstate)
        reg_0x3F == ($past(reset) ? 8'h00 : ($past(wenb) ? $past(reg_0x3F) : $past(in_data)))
    );

    // A reset cycle clears the register to zero.
    check_reset_clears_reg: assert property (
        @(posedge clk) disable iff ($initstate)
        reset |=> (reg_0x3F == 8'h00)
    );

    // When wenb is low, the register captures in_data.
    check_write_captures_input: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        !wenb |=> (reg_0x3F == $past(in_data))
    );

    // When wenb is high, the register holds its value.
    check_hold_when_wenb_high: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        wenb |=> (reg_0x3F == $past(reg_0x3F))
    );

    // The register only changes after reset or a write cycle.
    check_change_requires_reset_or_write: assert property (
        @(posedge clk) disable iff ($initstate)
        (reg_0x3F != $past(reg_0x3F)) |-> ($past(reset) || !$past(wenb))
    );

endmodule

