sva:
module Score_sva (
    input logic RESET,
    input logic [11:0] SCORE,
    input logic [6:0] DISP_SU,
    input logic [6:0] DISP_SD,
    input logic [6:0] DISP_SC,
    input logic [6:0] DISP_SM
);

    function automatic logic [6:0] sevenseg(input logic [3:0] digit);
        begin
            case (digit)
                4'd0: sevenseg = 7'b1111110;
                4'd1: sevenseg = 7'b0110000;
                4'd2: sevenseg = 7'b1101101;
                4'd3: sevenseg = 7'b1111001;
                4'd4: sevenseg = 7'b0110011;
                4'd5: sevenseg = 7'b1011011;
                4'd6: sevenseg = 7'b1011111;
                4'd7: sevenseg = 7'b1110000;
                4'd8: sevenseg = 7'b1111111;
                4'd9: sevenseg = 7'b1111011;
                default: sevenseg = 7'b0000000;
            endcase
        end
    endfunction

    function automatic logic [3:0] digit_m(input logic [11:0] s);
        int unsigned tmp;
        begin
            tmp = s;
            digit_m = tmp / 32'd1000;
        end
    endfunction

    function automatic logic [3:0] digit_c(input logic [11:0] s);
        int unsigned tmp;
        begin
            tmp = s;
            digit_c = (tmp % 32'd1000) / 32'd100;
        end
    endfunction

    function automatic logic [3:0] digit_d(input logic [11:0] s);
        int unsigned tmp;
        begin
            tmp = s;
            digit_d = (tmp % 32'd100) / 32'd10;
        end
    endfunction

    function automatic logic [3:0] digit_u(input logic [11:0] s);
        int unsigned tmp;
        begin
            tmp = s;
            digit_u = tmp % 32'd10;
        end
    endfunction

    // Reset forces all display outputs low.
    check_reset_blanks_all_displays: assert property (
        @($global_clock)
        RESET |-> (DISP_SU == 7'b0000000) &&
                  (DISP_SD == 7'b0000000) &&
                  (DISP_SC == 7'b0000000) &&
                  (DISP_SM == 7'b0000000)
    );

    // Thousands display decodes the thousands digit of SCORE.
    check_thousands_display_decode: assert property (
        @($global_clock) disable iff (RESET)
        DISP_SM == sevenseg(digit_m(SCORE))
    );

    // Hundreds display decodes the hundreds digit of SCORE.
    check_hundreds_display_decode: assert property (
        @($global_clock) disable iff (RESET)
        DISP_SC == sevenseg(digit_c(SCORE))
    );

    // Tens display decodes the tens digit of SCORE.
    check_tens_display_decode: assert property (
        @($global_clock) disable iff (RESET)
        DISP_SD == sevenseg(digit_d(SCORE))
    );

    // Units display decodes the ones digit of SCORE.
    check_units_display_decode: assert property (
        @($global_clock) disable iff (RESET)
        DISP_SU == sevenseg(digit_u(SCORE))
    );

    // Outside reset, the displays never use the blank default pattern.
    check_active_outputs_are_not_blank: assert property (
        @($global_clock) disable iff (RESET)
        (DISP_SU != 7'b0000000) &&
        (DISP_SD != 7'b0000000) &&
        (DISP_SC != 7'b0000000) &&
        (DISP_SM != 7'b0000000)
    );

    // A score of zero displays 0000 rather than blanking the digits.
    check_zero_score_shows_0000: assert property (
        @($global_clock) disable iff (RESET)
        (SCORE == 12'd0) |-> (DISP_SU == sevenseg(4'd0)) &&
                             (DISP_SD == sevenseg(4'd0)) &&
                             (DISP_SC == sevenseg(4'd0)) &&
                             (DISP_SM == sevenseg(4'd0))
    );

    // The maximum 12-bit score displays as 4095.
    check_max_score_shows_4095: assert property (
        @($global_clock) disable iff (RESET)
        (SCORE == 12'd4095) |-> (DISP_SM == sevenseg(4'd4)) &&
                                (DISP_SC == sevenseg(4'd0)) &&
                                (DISP_SD == sevenseg(4'd9)) &&
                                (DISP_SU == sevenseg(4'd5))
    );

endmodule

rtl:
module top_module (
    input a,
    input b,
    input c,
    output reg out
);

    wire nand1_out;
    wire nand2_out;
    wire nand3_out;

    // NAND gate behavioral model
    assign nand1_out = ~(a & b);

    // 2-input XOR gate designed using only NAND gates
    assign nand2_out = ~(a & ~(c));
    assign nand3_out = ~(~(c) & b);
    always @(*) begin
        out = ~(nand2_out & nand3_out);
    end

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic a,
    input logic b,
    input logic c,
    input logic out
);

    // Output matches the implemented combinational function.
    check_out_matches_function: assert property (
        @(posedge clk) out == ((a | b) & ~c)
    );

    // A high c forces the output low.
    check_c_high_forces_out_low: assert property (
        @(posedge clk) c |-> !out
    );

    // With c low, the output behaves as a OR b.
    check_c_low_reduces_to_a_or_b: assert property (
        @(posedge clk) !c |-> (out == (a | b))
    );

    // With c low and a high, the output is high.
    check_c_low_a_high_sets_out: assert property (
        @(posedge clk) (!c && a) |-> out
    );

    // With c low and b high, the output is high.
    check_c_low_b_high_sets_out: assert property (
        @(posedge clk) (!c && b) |-> out
    );

    // With both a and b low, the output is low.
    check_a_b_low_clear_out: assert property (
        @(posedge clk) (!a && !b) |-> !out
    );

    // A high output requires c to be low.
    check_out_high_requires_c_low: assert property (
        @(posedge clk) out |-> !c
    );

    // A high output requires at least one of a or b to be high.
    check_out_high_requires_a_or_b: assert property (
        @(posedge clk) out |-> (a | b)
    );

endmodule

rtl:
module top_module (
    input [7:0] in,
    input sel,
    output reg [2:0] pos,
    output reg [7:0] out_always );

    reg [7:0] in_reg;
    reg [2:0] pos_reg;

    always @(*) begin
        in_reg = in;
        pos_reg = 0;
        if (in_reg[7] == 1) pos_reg = 7;
        else if (in_reg[6] == 1) pos_reg = 6;
        else if (in_reg[5] == 1) pos_reg = 5;
        else if (in_reg[4] == 1) pos_reg = 4;
        else if (in_reg[3] == 1) pos_reg = 3;
        else if (in_reg[2] == 1) pos_reg = 2;
        else if (in_reg[1] == 1) pos_reg = 1;
        else if (in_reg[0] == 1) pos_reg = 0;
        pos = pos_reg;
    end

    always @(posedge sel) begin
        if (sel == 1) out_always = pos_reg;
        else out_always = in_reg;
    end

endmodule

sva:
module top_module_sva (
    input logic [7:0] in,
    input logic       sel,
    input logic [2:0] pos,
    input logic [7:0] out_always
);

    // Bit 7 has highest priority.
    check_pos_from_bit7: assert property (
        @(posedge sel) in[7] |-> (pos == 3'd7)
    );

    // Bit 6 is selected when bit 7 is clear.
    check_pos_from_bit6: assert property (
        @(posedge sel) ((!in[7]) && in[6]) |-> (pos == 3'd6)
    );

    // Bit 5 is selected when bits 7:6 are clear.
    check_pos_from_bit5: assert property (
        @(posedge sel) ((in[7:6] == 2'b00) && in[5]) |-> (pos == 3'd5)
    );

    // Bit 4 is selected when bits 7:5 are clear.
    check_pos_from_bit4: assert property (
        @(posedge sel) ((in[7:5] == 3'b000) && in[4]) |-> (pos == 3'd4)
    );

    // Bit 3 is selected when bits 7:4 are clear.
    check_pos_from_bit3: assert property (
        @(posedge sel) ((in[7:4] == 4'b0000) && in[3]) |-> (pos == 3'd3)
    );

    // Bit 2 is selected when bits 7:3 are clear.
    check_pos_from_bit2: assert property (
        @(posedge sel) ((in[7:3] == 5'b00000) && in[2]) |-> (pos == 3'd2)
    );

    // Bit 1 is selected when bits 7:2 are clear.
    check_pos_from_bit1: assert property (
        @(posedge sel) ((in[7:2] == 6'b000000) && in[1]) |-> (pos == 3'd1)
    );

    // Bit 0 is selected when bits 7:1 are clear.
    check_pos_from_bit0: assert property (
        @(posedge sel) ((in[7:1] == 7'b0000000) && in[0]) |-> (pos == 3'd0)
    );

    // No asserted input bits produce position 0.
    check_pos_when_no_bits_set: assert property (
        @(posedge sel) (in == 8'b00000000) |-> (pos == 3'd0)
    );

    // The registered output is zero-extended from a 3-bit value.
    check_out_always_zero_extended: assert property (
        @(posedge sel) 1'b1 |=> (out_always[7:3] == 5'b00000)
    );

endmodule

rtl:
module binary_to_gray (
    input [3:0] BIN,
    output reg [3:0] GRAY
);

always @ (BIN) begin
    GRAY[0] = BIN[0] ^ BIN[1];
    GRAY[1] = BIN[1] ^ BIN[2];
    GRAY[2] = BIN[2] ^ BIN[3];
    GRAY[3] = BIN[3];
end

endmodule

sva:
module binary_to_gray_sva (
    input logic clk,
    input logic [3:0] BIN,
    input logic [3:0] GRAY
);

    // GRAY[0] is the XOR of BIN[0] and BIN[1].
    check_gray_bit0_xor: assert property (
        @(posedge clk) GRAY[0] == (BIN[0] ^ BIN[1])
    );

    // GRAY[1] is the XOR of BIN[1] and BIN[2].
    check_gray_bit1_xor: assert property (
        @(posedge clk) GRAY[1] == (BIN[1] ^ BIN[2])
    );

    // GRAY[2] is the XOR of BIN[2] and BIN[3].
    check_gray_bit2_xor: assert property (
        @(posedge clk) GRAY[2] == (BIN[2] ^ BIN[3])
    );

    // GRAY[3] directly copies BIN[3].
    check_gray_bit3_copy: assert property (
        @(posedge clk) GRAY[3] == BIN[3]
    );

    // The full GRAY vector matches the implemented mapping.
    check_gray_vector_map: assert property (
        @(posedge clk) GRAY == {BIN[3], (BIN[2] ^ BIN[3]), (BIN[1] ^ BIN[2]), (BIN[0] ^ BIN[1])}
    );

    // A stable BIN keeps the full GRAY output stable.
    check_stable_bin_keeps_gray_stable: assert property (
        @(posedge clk) !$initstate && $stable(BIN) |-> $stable(GRAY)
    );

    // GRAY[0] only depends on BIN[1:0].
    check_gray0_dependency: assert property (
        @(posedge clk) !$initstate && $stable(BIN[1:0]) |-> $stable(GRAY[0])
    );

    // GRAY[1] only depends on BIN[2:1].
    check_gray1_dependency: assert property (
        @(posedge clk) !$initstate && $stable(BIN[2:1]) |-> $stable(GRAY[1])
    );

    // GRAY[2] only depends on BIN[3:2].
    check_gray2_dependency: assert property (
        @(posedge clk) !$initstate && $stable(BIN[3:2]) |-> $stable(GRAY[2])
    );

    // GRAY[3] only depends on BIN[3].
    check_gray3_dependency: assert property (
        @(posedge clk) !$initstate && $stable(BIN[3]) |-> $stable(GRAY[3])
    );

endmodule

rtl:
module bin_to_gray(
    input [3:0] bin,
    output [3:0] gray
);

    assign gray[3] = bin[3];
    assign gray[2] = bin[3] ^ bin[2];
    assign gray[1] = bin[2] ^ bin[1];
    assign gray[0] = bin[1] ^ bin[0];

endmodule

sva:
module bin_to_gray_sva (
    input logic [3:0] bin,
    input logic [3:0] gray
);

    // gray[3] passes through bin[3].
    check_gray_bit3_passthrough: assert property (
        @($global_clock) gray[3] == bin[3]
    );

    // gray[2] is bin[3] XOR bin[2].
    check_gray_bit2_xor: assert property (
        @($global_clock) gray[2] == (bin[3] ^ bin[2])
    );

    // gray[1] is bin[2] XOR bin[1].
    check_gray_bit1_xor: assert property (
        @($global_clock) gray[1] == (bin[2] ^ bin[1])
    );

    // gray[0] is bin[1] XOR bin[0].
    check_gray_bit0_xor: assert property (
        @($global_clock) gray[0] == (bin[1] ^ bin[0])
    );

    // The full Gray vector matches the implemented encoding.
    check_full_gray_encoding: assert property (
        @($global_clock) gray == {bin[3], (bin[3] ^ bin[2]), (bin[2] ^ bin[1]), (bin[1] ^ bin[0])}
    );

    // If bin is unchanged, gray is unchanged.
    check_stable_bin_implies_stable_gray: assert property (
        @($global_clock) $stable(bin) |-> $stable(gray)
    );

    // A change only on bin[0] affects only gray[0].
    check_bin0_change_effect: assert property (
        @($global_clock) ($stable(bin[3:1]) && $changed(bin[0])) |-> ($stable(gray[3:1]) && $changed(gray[0]))
    );

    // A change only on bin[1] affects gray[1:0] and not gray[3:2].
    check_bin1_change_effect: assert property (
        @($global_clock) ($stable({bin[3:2], bin[0]}) && $changed(bin[1])) |-> ($stable(gray[3:2]) && $changed(gray[1]) && $changed(gray[0]))
    );

    // A change only on bin[2] affects gray[2:1] and not gray[3] or gray[0].
    check_bin2_change_effect: assert property (
        @($global_clock) ($stable({bin[3], bin[1:0]}) && $changed(bin[2])) |-> ($stable(gray[3]) && $changed(gray[2]) && $changed(gray[1]) && $stable(gray[0]))
    );

    // A change only on bin[3] affects gray[3:2] and not gray[1:0].
    check_bin3_change_effect: assert property (
        @($global_clock) ($stable(bin[2:0]) && $changed(bin[3])) |-> ($changed(gray[3]) && $changed(gray[2]) && $stable(gray[1:0]))
    );

endmodule

rtl:
module fsm_3bit_binary_counter (
  input clk,
  input reset,
  output reg [2:0] counter
);

  always @(posedge clk, posedge reset) begin
    if (reset) begin
      counter <= 3'b0;
    end else if (counter == 3'b111) begin
      counter <= 3'b0;
    end else begin
      counter <= counter + 1;
    end
  end

endmodule

sva:
module fsm_3bit_binary_counter_sva (
    input logic       clk,
    input logic       reset,
    input logic [2:0] counter
);

    // 000 advances to 001 on the next clock.
    check_count_000_to_001: assert property (
        @(posedge clk) disable iff (reset)
        (counter == 3'b000) |=> (counter == 3'b001)
    );

    // 001 advances to 010 on the next clock.
    check_count_001_to_010: assert property (
        @(posedge clk) disable iff (reset)
        (counter == 3'b001) |=> (counter == 3'b010)
    );

    // 010 advances to 011 on the next clock.
    check_count_010_to_011: assert property (
        @(posedge clk) disable iff (reset)
        (counter == 3'b010) |=> (counter == 3'b011)
    );

    // 011 advances to 100 on the next clock.
    check_count_011_to_100: assert property (
        @(posedge clk) disable iff (reset)
        (counter == 3'b011) |=> (counter == 3'b100)
    );

    // 100 advances to 101 on the next clock.
    check_count_100_to_101: assert property (
        @(posedge clk) disable iff (reset)
        (counter == 3'b100) |=> (counter == 3'b101)
    );

    // 101 advances to 110 on the next clock.
    check_count_101_to_110: assert property (
        @(posedge clk) disable iff (reset)
        (counter == 3'b101) |=> (counter == 3'b110)
    );

    // 110 advances to 111 on the next clock.
    check_count_110_to_111: assert property (
        @(posedge clk) disable iff (reset)
        (counter == 3'b110) |=> (counter == 3'b111)
    );

    // 111 wraps back to 000 on the next clock.
    check_count_111_to_000: assert property (
        @(posedge clk) disable iff (reset)
        (counter == 3'b111) |=> (counter == 3'b000)
    );

