rtl:
module four_bit_adder(
    output [3:0] S,
    output C_out,
    input [3:0] A,
    input [3:0] B
);

    wire [3:0] XOR_out;
    wire [3:0] AND_out;
    wire [3:0] carry;

    xor_gate XOR0(.Y(XOR_out[0]), .A(A[0]), .B(B[0]));
    xor_gate XOR1(.Y(XOR_out[1]), .A(A[1]), .B(B[1]));
    xor_gate XOR2(.Y(XOR_out[2]), .A(A[2]), .B(B[2]));
    xor_gate XOR3(.Y(XOR_out[3]), .A(A[3]), .B(B[3]));

    and_gate AND0(.Y(AND_out[0]), .A(XOR_out[0]), .B(XOR_out[1]));
    and_gate AND1(.Y(AND_out[1]), .A(XOR_out[2]), .B(XOR_out[3]));
    and_gate AND2(.Y(AND_out[2]), .A(XOR_out[1]), .B(XOR_out[2]));
    and_gate AND3(.Y(AND_out[3]), .A(XOR_out[0]), .B(XOR_out[1]));

    xor_gate XOR4(.Y(S[0]), .A(XOR_out[0]), .B(XOR_out[1]));
    xor_gate XOR5(.Y(S[1]), .A(XOR_out[2]), .B(XOR_out[3]));
    xor_gate XOR6(.Y(S[2]), .A(XOR_out[1]), .B(XOR_out[2]));
    xor_gate XOR7(.Y(S[3]), .A(S[2]), .B(AND_out[0]));

    and_gate AND4(.Y(carry[0]), .A(AND_out[0]), .B(AND_out[1]));
    and_gate AND5(.Y(carry[1]), .A(AND_out[2]), .B(AND_out[3]));
    and_gate AND6(.Y(carry[2]), .A(AND_out[1]), .B(AND_out[2]));
    or_gate  OR0 (.Y(C_out), .A(carry[0]), .B(carry[1]), .C(carry[2]));

endmodule

module xor_gate(
    output Y,
    input A,
    input B
);
    assign Y = A ^ B;
endmodule

module and_gate(
    output Y,
    input A,
    input B
);
    assign Y = A & B;
endmodule

module or_gate(
    output Y,
    input A,
    input B,
    input C
);
    assign Y = A | B | C;
endmodule

sva:
module four_bit_adder_sva(
    input logic       clk,
    input logic [3:0] S,
    input logic       C_out,
    input logic [3:0] A,
    input logic [3:0] B
);

    // S[0] is the XOR of the first two input XOR terms.
    check_s0_equation: assert property (
        @(posedge clk)
        S[0] == ((A[0] ^ B[0]) ^ (A[1] ^ B[1]))
    );

    // S[1] is the XOR of the upper two input XOR terms.
    check_s1_equation: assert property (
        @(posedge clk)
        S[1] == ((A[2] ^ B[2]) ^ (A[3] ^ B[3]))
    );

    // S[2] is the XOR of the middle input XOR terms.
    check_s2_equation: assert property (
        @(posedge clk)
        S[2] == ((A[1] ^ B[1]) ^ (A[2] ^ B[2]))
    );

    // S[3] matches the final XOR of S[2] and the first AND term.
    check_s3_equation: assert property (
        @(posedge clk)
        S[3] == (((A[1] ^ B[1]) ^ (A[2] ^ B[2])) ^ ((A[0] ^ B[0]) & (A[1] ^ B[1])))
    );

    // C_out matches the OR of the three carry product terms.
    check_cout_equation: assert property (
        @(posedge clk)
        C_out == (
            (((A[0] ^ B[0]) & (A[1] ^ B[1])) & ((A[2] ^ B[2]) & (A[3] ^ B[3]))) |
            (((A[1] ^ B[1]) & (A[2] ^ B[2])) & ((A[0] ^ B[0]) & (A[1] ^ B[1]))) |
            (((A[2] ^ B[2]) & (A[3] ^ B[3])) & ((A[1] ^ B[1]) & (A[2] ^ B[2])))
        )
    );

    // Equal inputs drive all XOR-derived outputs low.
    check_equal_inputs_zero_outputs: assert property (
        @(posedge clk)
        (A == B) |-> ((S == 4'b0000) && (C_out == 1'b0))
    );

    // Any carry-out requires both middle XOR terms to be high.
    check_cout_requires_middle_terms: assert property (
        @(posedge clk)
        C_out |-> ((A[1] ^ B[1]) & (A[2] ^ B[2]))
    );

endmodule

rtl:
module mux4to1(
    input in0,
    input in1,
    input in2,
    input in3,
    input sel0,
    input sel1,
    output reg out
);

always @(*) begin
    case ({sel1, sel0})
        2'b00: out = in0;
        2'b01: out = in1;
        2'b10: out = in2;
        2'b11: out = in3;
    endcase
end

endmodule

sva:
module mux4to1_sva(
    input logic in0,
    input logic in1,
    input logic in2,
    input logic in3,
    input logic sel0,
    input logic sel1,
    input logic out
);

    // When select is 00, output routes in0.
    check_sel_00_routes_in0: assert property (
        @($global_clock) ({sel1, sel0} == 2'b00) |-> (out == in0)
    );

    // When select is 01, output routes in1.
    check_sel_01_routes_in1: assert property (
        @($global_clock) ({sel1, sel0} == 2'b01) |-> (out == in1)
    );

    // When select is 10, output routes in2.
    check_sel_10_routes_in2: assert property (
        @($global_clock) ({sel1, sel0} == 2'b10) |-> (out == in2)
    );

    // When select is 11, output routes in3.
    check_sel_11_routes_in3: assert property (
        @($global_clock) ({sel1, sel0} == 2'b11) |-> (out == in3)
    );

endmodule

rtl:
module system_vga_hessian_0_0_bindec_0 (
  output [2:0] enb_array,
  input enb,
  input [1:0] addrb
);

  wire [1:0] addrb_wire;
  wire enb_wire;
  wire [2:0] enb_array_wire;

  assign addrb_wire = addrb;
  assign enb_wire = enb;
  assign enb_array_wire = enb_array;

  assign enb_array[0] = ((addrb_wire[1] & ~addrb_wire[0]) | enb_wire);
  assign enb_array[1] = ((addrb_wire[0] & ~addrb_wire[1]) | enb_wire);
  assign enb_array[2] = ((enb_wire & ~addrb_wire[0]) | addrb_wire[1]);

endmodule

sva:
module system_vga_hessian_0_0_bindec_0_assertions (
    input logic clk,
    input logic [2:0] enb_array,
    input logic enb,
    input logic [1:0] addrb
);

    // Checks enb_array[0] matches its combinational equation.
    check_enb_array_bit0_function: assert property (
        @(posedge clk) enb_array[0] == ((addrb[1] & ~addrb[0]) | enb)
    );

    // Checks enb_array[1] matches its combinational equation.
    check_enb_array_bit1_function: assert property (
        @(posedge clk) enb_array[1] == ((addrb[0] & ~addrb[1]) | enb)
    );

    // Checks enb_array[2] matches its combinational equation.
    check_enb_array_bit2_function: assert property (
        @(posedge clk) enb_array[2] == ((enb & ~addrb[0]) | addrb[1])
    );

    // Checks enb forces enb_array[1:0] high.
    check_enable_sets_low_bits: assert property (
        @(posedge clk) enb |-> (enb_array[1:0] == 2'b11)
    );

    // Checks addrb[1] directly forces enb_array[2] high.
    check_addrb1_sets_bit2: assert property (
        @(posedge clk) addrb[1] |-> enb_array[2]
    );

    // Checks bits 0 and 1 are never both high when enb is low.
    check_disabled_low_bits_mutually_exclusive: assert property (
        @(posedge clk) (!enb) |-> !(enb_array[0] && enb_array[1])
    );

    // Checks the disabled decode for addrb == 2'b00.
    check_disabled_decode_00: assert property (
        @(posedge clk) ((!enb) && (addrb == 2'b00)) |-> (enb_array == 3'b000)
    );

    // Checks the disabled decode for addrb == 2'b01.
    check_disabled_decode_01: assert property (
        @(posedge clk) ((!enb) && (addrb == 2'b01)) |-> (enb_array == 3'b010)
    );

    // Checks the disabled decode for addrb == 2'b10.
    check_disabled_decode_10: assert property (
        @(posedge clk) ((!enb) && (addrb == 2'b10)) |-> (enb_array == 3'b101)
    );

    // Checks the disabled decode for addrb == 2'b11.
    check_disabled_decode_11: assert property (
        @(posedge clk) ((!enb) && (addrb == 2'b11)) |-> (enb_array == 3'b100)
    );

endmodule

module mux_2to1_assertions (
    input logic A,
    input logic B,
    input logic S,
    input logic CLK,
    input logic Y
);

    // When select is exactly 0, Y captures A on the following clock.
    check_capture_a_when_s_low: assert property (
        @(posedge CLK) (S === 1'b0) |=> (Y == $past(A))
    );

    // When select is not exactly 0, Y captures B on the following clock.
    check_capture_b_when_s_not_low: assert property (
        @(posedge CLK) (S !== 1'b0) |=> (Y == $past(B))
    );

    // Y always reflects the input selected on the previous clock edge.
    check_output_matches_previous_selection: assert property (
        @(posedge CLK) 1'b1 |=> (Y == (($past(S) === 1'b0) ? $past(A) : $past(B)))
    );

endmodule

rtl:
module sky130_fd_sc_lp__sdfrtp_4 (
    Q      ,
    CLK    ,
    D      ,
    SCD    ,
    SCE    ,
    RESET_B,
    VPWR   ,
    VGND   ,
    VPB    ,
    VNB
);

    output Q      ;
    input  CLK    ;
    input  D      ;
    input  SCD    ;
    input  SCE    ;
    input  RESET_B;
    input  VPWR   ;
    input  VGND   ;
    input  VPB    ;
    input  VNB    ;

    reg Q;

    always @(posedge CLK, negedge RESET_B) begin
        if (!RESET_B) begin
            Q <= 1'b0;
        end else if (SCD == 1'b0) begin
            Q <= 1'b0;
        end else if (SCE == 1'b1) begin
            Q <= D;
        end
    end

endmodule

sva:
module sky130_fd_sc_lp__sdfrtp_4_sva (
    input logic Q,
    input logic CLK,
    input logic D,
    input logic SCD,
    input logic SCE,
    input logic RESET_B,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB
);

    // Active-low reset forces Q low.
    check_reset_forces_q_low: assert property (
        @(posedge CLK)
        !RESET_B |-> (Q == 1'b0)
    );

    // Q is still low on the first sampled cycle after reset was active.
    check_post_reset_q_low: assert property (
        @(posedge CLK) disable iff (!RESET_B)
        (!$initstate && ($past(RESET_B) == 1'b0)) |-> (Q == 1'b0)
    );

    // SCD low clears Q on the next sampled clock.
    check_scd_low_clears_q: assert property (
        @(posedge CLK) disable iff (!RESET_B)
        (SCD == 1'b0) |=> (Q == 1'b0)
    );

    // With SCD high and SCE high, Q captures D.
    check_enabled_capture_updates_q: assert property (
        @(posedge CLK) disable iff (!RESET_B)
        ((SCD == 1'b1) && (SCE == 1'b1)) |=> (Q == $past(D))
    );

    // With SCD high and SCE low, Q holds its previous value.
    check_hold_when_capture_disabled: assert property (
        @(posedge CLK) disable iff (!RESET_B)
        ((SCD == 1'b1) && (SCE == 1'b0)) |=> (Q == $past(Q))
    );

    // A rising Q must come from an enabled capture of 1.
    check_q_rise_requires_capture_one: assert property (
        @(posedge CLK) disable iff (!RESET_B)
        (!$initstate && $rose(Q)) |-> (($past(RESET_B) == 1'b1) &&
                                       ($past(SCD) == 1'b1) &&
                                       ($past(SCE) == 1'b1) &&
                                       ($past(D) == 1'b1))
    );

    // A falling Q must come from reset, clear, or an enabled capture of 0.
    check_q_fall_requires_zero_update: assert property (
        @(posedge CLK) disable iff (!RESET_B)
        (!$initstate && $fell(Q)) |-> (($past(RESET_B) == 1'b0) ||
                                       ($past(SCD) == 1'b0) ||
                                       (($past(SCD) == 1'b1) &&
                                        ($past(SCE) == 1'b1) &&
                                        ($past(D) == 1'b0)))
    );

endmodule

rtl:
module Create (Init, creaenhe, D, rst, RS, RW, Out_display, MsbOD, clk, scrinit);
  input Init;
  input creaenhe;
	input clk;
	input [2:0] scrinit;
  input [6:0] D;
  input rst;
	output reg MsbOD;
	output reg [6:0] Out_display;
  output reg RS;
	output reg RW;

always @(negedge clk) begin
	if(rst) begin
		MsbOD=0;
		Out_display=7'b0;
	end
	else begin
		case (scrinit)
			3'b001: begin
				Out_display={7'b0111000};
				MsbOD=0;
				RW=0;
				RS=0;
			end
			3'b010: begin
				Out_display={7'b0000100};
				MsbOD=0;
				RW=0;
				RS=0;
			end
			3'b011: begin
				Out_display={7'b0001100};
				MsbOD=0;
				RW=0;
				RS=0;
			end
			3'b100: begin
				Out_display={7'b0000001};
				MsbOD=0;
				RW=0;
				RS=0;
			end
			3'b101: begin
				Out_display={7'b0110000};
				MsbOD=0;
				RW=0;
				RS=0;
			end
			default begin
				if (creaenhe) begin
					Out_display={7'b1101110};
					MsbOD=1;
					RW=0;
					RS=1;
				end
				else begin
					if(Init) begin
						Out_display={7'b0000001};
						MsbOD=0;
						RS=0;
						RW=0;
					end 
					else begin
						Out_display=D;
						MsbOD=0;
						RW=0;
						RS=1;
					end
				end
			end
		endcase
	end
end
endmodule

sva:
module Create_assertions (
    input logic Init,
    input logic creaenhe,
