sva:
module sky130_fd_sc_lp__a2111oi_sva (
    input logic clk,
    input logic Y,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic C1,
    input logic D1
);

    // Y matches the implemented A2111OI Boolean equation.
    check_y_equation: assert property (
        @(posedge clk) Y == ~(B1 | C1 | D1 | (A1 & A2))
    );

    // B1 high forces the NOR output low.
    check_b1_forces_y_low: assert property (
        @(posedge clk) B1 |-> !Y
    );

    // C1 high forces the NOR output low.
    check_c1_forces_y_low: assert property (
        @(posedge clk) C1 |-> !Y
    );

    // D1 high forces the NOR output low.
    check_d1_forces_y_low: assert property (
        @(posedge clk) D1 |-> !Y
    );

    // A1 and A2 high together force the NOR output low.
    check_a1_a2_force_y_low: assert property (
        @(posedge clk) (A1 && A2) |-> !Y
    );

    // Y is high when all NOR inputs are low.
    check_all_nor_inputs_low_force_y_high: assert property (
        @(posedge clk) (!B1 && !C1 && !D1 && !(A1 && A2)) |-> Y
    );

endmodule

rtl:
module sel_Data(
    CLK,
    RST,
    SW,
    xAxis,
    yAxis,
    zAxis,
    DOUT,
    LED
);

   input        CLK;
   input        RST;
   input [1:0]  SW;
   input [9:0]  xAxis;
   input [9:0]  yAxis;
   input [9:0]  zAxis;
   output [9:0] DOUT;
   output [2:0] LED;


   reg [9:0]    DOUT;
   reg [2:0]    LED;


        //-----------------------------------------------
        //  Select Display Data and Convert to Magnitude
        //-----------------------------------------------
        always @(posedge CLK or posedge RST)
            if (RST == 1'b1)
            begin
                LED <= 3'b000;
                DOUT <= 10'b0000000000;
            end
            else 
            begin
                // select xAxis data for display
                if (SW == 2'b00) begin
                    LED <= 3'b001;
                    if (xAxis[9] == 1'b1)
                        DOUT <= {xAxis[9], (9'b000000000 - xAxis[8:0])};
                    else
                        DOUT <= xAxis;
                end
                // select yAxis data for display
                else if (SW == 2'b01) begin
                    LED <= 3'b010;
                    if (yAxis[9] == 1'b1)
                        DOUT <= {yAxis[9], (9'b000000000 - yAxis[8:0])};
                    else
                        DOUT <= yAxis;
                end
                // select zAxis data for display
                else if (SW == 2'b10) begin
                    LED <= 3'b100;
                    if (zAxis[9] == 1'b1)
                        DOUT <= {zAxis[9], (9'b000000000 - zAxis[8:0])};
                    else
                        DOUT <= zAxis;
                end
                // Default select xAxis data for display
                else begin
                    LED <= 3'b001;
                    if (xAxis[9] == 1'b1)
                        DOUT <= {xAxis[9], (9'b000000000 - xAxis[8:0])};
                    else
                        DOUT <= xAxis;
                end
            end

endmodule

sva:
module sel_Data_sva (
    input logic        CLK,
    input logic        RST,
    input logic [1:0]  SW,
    input logic [9:0]  xAxis,
    input logic [9:0]  yAxis,
    input logic [9:0]  zAxis,
    input logic [9:0]  DOUT,
    input logic [2:0]  LED
);

    // SW=00 selects xAxis directly when xAxis is non-negative.
    check_select_x_positive: assert property (
        @(posedge CLK) disable iff (RST)
        (SW == 2'b00 && xAxis[9] == 1'b0)
        |=> (LED == 3'b001 && DOUT == $past(xAxis))
    );

    // SW=00 selects xAxis sign-plus-magnitude when xAxis is negative.
    check_select_x_negative: assert property (
        @(posedge CLK) disable iff (RST)
        (SW == 2'b00 && xAxis[9] == 1'b1)
        |=> (LED == 3'b001 &&
             DOUT == {$past(xAxis[9]), (9'b000000000 - $past(xAxis[8:0]))})
    );

    // SW=01 selects yAxis directly when yAxis is non-negative.
    check_select_y_positive: assert property (
        @(posedge CLK) disable iff (RST)
        (SW == 2'b01 && yAxis[9] == 1'b0)
        |=> (LED == 3'b010 && DOUT == $past(yAxis))
    );

    // SW=01 selects yAxis sign-plus-magnitude when yAxis is negative.
    check_select_y_negative: assert property (
        @(posedge CLK) disable iff (RST)
        (SW == 2'b01 && yAxis[9] == 1'b1)
        |=> (LED == 3'b010 &&
             DOUT == {$past(yAxis[9]), (9'b000000000 - $past(yAxis[8:0]))})
    );

    // SW=10 selects zAxis directly when zAxis is non-negative.
    check_select_z_positive: assert property (
        @(posedge CLK) disable iff (RST)
        (SW == 2'b10 && zAxis[9] == 1'b0)
        |=> (LED == 3'b100 && DOUT == $past(zAxis))
    );

    // SW=10 selects zAxis sign-plus-magnitude when zAxis is negative.
    check_select_z_negative: assert property (
        @(posedge CLK) disable iff (RST)
        (SW == 2'b10 && zAxis[9] == 1'b1)
        |=> (LED == 3'b100 &&
             DOUT == {$past(zAxis[9]), (9'b000000000 - $past(zAxis[8:0]))})
    );

    // SW=11 takes the default path and selects xAxis directly when xAxis is non-negative.
    check_default_x_positive: assert property (
        @(posedge CLK) disable iff (RST)
        (SW == 2'b11 && xAxis[9] == 1'b0)
        |=> (LED == 3'b001 && DOUT == $past(xAxis))
    );

    // SW=11 takes the default path and selects xAxis sign-plus-magnitude when xAxis is negative.
    check_default_x_negative: assert property (
        @(posedge CLK) disable iff (RST)
        (SW == 2'b11 && xAxis[9] == 1'b1)
        |=> (LED == 3'b001 &&
             DOUT == {$past(xAxis[9]), (9'b000000000 - $past(xAxis[8:0]))})
    );

endmodule

rtl:
module sky130_fd_sc_lp__a21bo_lp (
    X   ,
    A1  ,
    A2  ,
    B1_N,
    VPWR,
    VGND,
    VPB ,
    VNB
);

    output X   ;
    input  A1  ;
    input  A2  ;
    input  B1_N;
    input  VPWR;
    input  VGND;
    input  VPB ;
    input  VNB ;

    wire B1;

    nand (B1, A1, A2);

    not (X, B1);

    not (B1, B1_N);

endmodule

sva:
module sky130_fd_sc_lp__a21bo_lp_sva (
    input logic X,
    input logic A1,
    input logic A2,
    input logic B1_N,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB,
    input logic B1,
    input logic clk
);

    // External clk samples this combinational DUT; the RTL has no reset.

    // When the two B1 drivers agree, B1 must equal the shared driven value.
    check_b1_when_drivers_agree: assert property (
        @(posedge clk)
        (!$isunknown({A1, A2, B1_N}) && ((A1 & A2) == B1_N))
        |-> (B1 === ~B1_N)
    );

    // When the two B1 drivers agree, X must match B1_N through the final inverter.
    check_x_when_drivers_agree: assert property (
        @(posedge clk)
        (!$isunknown({A1, A2, B1_N}) && ((A1 & A2) == B1_N))
        |-> (X === B1_N)
    );

    // All three logical inputs high force B1 low and X high.
    check_all_high_case: assert property (
        @(posedge clk)
        ((A1 === 1'b1) && (A2 === 1'b1) && (B1_N === 1'b1))
        |-> ((B1 === 1'b0) && (X === 1'b1))
    );

    // B1_N low with either A1 or A2 low forces B1 high and X low.
    check_low_agree_case: assert property (
        @(posedge clk)
        (!$isunknown({A1, A2, B1_N}) && (B1_N === 1'b0) && ((A1 === 1'b0) || (A2 === 1'b0)))
        |-> ((B1 === 1'b1) && (X === 1'b0))
    );

    // A known low on B1 must invert to a high on X.
    check_x_high_when_b1_low: assert property (
        @(posedge clk)
        (B1 === 1'b0) |-> (X === 1'b1)
    );

    // A known high on B1 must invert to a low on X.
    check_x_low_when_b1_high: assert property (
        @(posedge clk)
        (B1 === 1'b1) |-> (X === 1'b0)
    );

endmodule

rtl:
module binary_divider (
    input [15:0] dividend,
    input [15:0] divisor,
    output reg [15:0] quotient,
    output reg [15:0] remainder
);

    always @(*) begin
        if (divisor == 0) begin
            quotient <= 65535; // maximum value for 16-bit unsigned integer
            remainder <= 65535;
        end else begin
            quotient <= dividend / divisor;
            remainder <= dividend % divisor;
        end
    end

endmodule

sva:
module binary_divider_sva (
    input logic [15:0] dividend,
    input logic [15:0] divisor,
    input logic [15:0] quotient,
    input logic [15:0] remainder
);

    // Division by zero drives both outputs to the maximum 16-bit value.
    check_divide_by_zero_outputs_max: assert property (
        @($global_clock)
        (divisor == 16'd0) |-> ((quotient == 16'hFFFF) && (remainder == 16'hFFFF))
    );

    // For a nonzero divisor, quotient and remainder match the arithmetic operators.
    check_nonzero_divisor_exact_results: assert property (
        @($global_clock)
        (divisor != 16'd0) |-> ((quotient == (dividend / divisor)) && (remainder == (dividend % divisor)))
    );

    // For a nonzero divisor, remainder is always less than the divisor.
    check_nonzero_divisor_remainder_range: assert property (
        @($global_clock)
        (divisor != 16'd0) |-> (remainder < divisor)
    );

    // For a nonzero divisor, quotient*divisor plus remainder reconstructs dividend.
    check_nonzero_divisor_reconstructs_dividend: assert property (
        @($global_clock)
        (divisor != 16'd0) |-> ({16'd0, dividend} == (({16'd0, quotient} * {16'd0, divisor}) + {16'd0, remainder}))
    );

    // If the divisor is larger than the dividend, quotient is zero and remainder is the dividend.
    check_divisor_larger_than_dividend: assert property (
        @($global_clock)
        ((divisor != 16'd0) && (divisor > dividend)) |-> ((quotient == 16'd0) && (remainder == dividend))
    );

    // Dividing by one returns the dividend with zero remainder.
    check_divisor_one_identity: assert property (
        @($global_clock)
        (divisor == 16'd1) |-> ((quotient == dividend) && (remainder == 16'd0))
    );

endmodule

rtl:
module mux_3to4 (
  input [2:0] data_in,
  input enable,
  input [1:0] select,
  output reg [3:0] data_out
);

always @ (enable, select, data_in)
begin
  if (enable)
  begin
    case (select)
      2'b00: data_out = {data_in[0], 1'b0, 1'b0, 1'b0};
      2'b01: data_out = {1'b0, data_in[1], 1'b0, 1'b0};
      2'b10: data_out = {1'b0, 1'b0, data_in[2], 1'b0};
      2'b11: data_out = {1'b0, 1'b0, 1'b0, 1'b0};
      default: data_out = {1'b0, 1'b0, 1'b0, 1'b0};
    endcase
  end
  else
    data_out = {1'b0, 1'b0, 1'b0, 1'b0};
end

endmodule

sva:
module mux_3to4_sva (
    input logic       clk,
    input logic [2:0] data_in,
    input logic       enable,
    input logic [1:0] select,
    input logic [3:0] data_out
);

    // Output matches the RTL mux function for all input combinations.
    check_functional_mapping: assert property (
        @(posedge clk)
        data_out ==
        (enable
            ? ((select == 2'b00) ? {data_in[0], 1'b0, 1'b0, 1'b0} :
               (select == 2'b01) ? {1'b0, data_in[1], 1'b0, 1'b0} :
               (select == 2'b10) ? {1'b0, 1'b0, data_in[2], 1'b0} :
                                   4'b0000)
            : 4'b0000)
    );

    // When disabled, all outputs are low.
    check_disabled_forces_zero: assert property (
        @(posedge clk)
        !enable |-> (data_out == 4'b0000)
    );

    // Select 00 routes only data_in[0] to data_out[3].
    check_select_00_route: assert property (
        @(posedge clk)
        enable && (select == 2'b00) |-> (data_out == {data_in[0], 1'b0, 1'b0, 1'b0})
    );

    // Select 01 routes only data_in[1] to data_out[2].
    check_select_01_route: assert property (
        @(posedge clk)
        enable && (select == 2'b01) |-> (data_out == {1'b0, data_in[1], 1'b0, 1'b0})
    );

    // Select 10 routes only data_in[2] to data_out[1].
    check_select_10_route: assert property (
        @(posedge clk)
        enable && (select == 2'b10) |-> (data_out == {1'b0, 1'b0, data_in[2], 1'b0})
    );

    // Select 11 forces all outputs low.
    check_select_11_zero: assert property (
        @(posedge clk)
        enable && (select == 2'b11) |-> (data_out == 4'b0000)
    );

    // The least significant output bit is always zero.
    check_lsb_always_zero: assert property (
        @(posedge clk)
        data_out[0] == 1'b0
    );

    // The output is always zero or a single active routed bit.
    check_legal_output_patterns: assert property (
        @(posedge clk)
        (data_out == 4'b0000) || (data_out == 4'b1000) || (data_out == 4'b0100) || (data_out == 4'b0010)
    );

    // data_out[3] can only be high for select 00 with data_in[0] high.
    check_bit3_source_condition: assert property (
        @(posedge clk)
        data_out[3] |-> enable && (select == 2'b00) && data_in[0]
    );

    // data_out[2] can only be high for select 01 with data_in[1] high.
    check_bit2_source_condition: assert property (
        @(posedge clk)
        data_out[2] |-> enable && (select == 2'b01) && data_in[1]
    );

    // data_out[1] can only be high for select 10 with data_in[2] high.
    check_bit1_source_condition: assert property (
        @(posedge clk)
        data_out[1] |-> enable && (select == 2'b10) && data_in[2]
    );

endmodule

module shift_register_sva (
    input logic       clk,
    input logic [3:0] DIN,
    input logic       LOAD,
    input logic       SHIFT,
    input logic       RESET,
    input logic [3:0] Q
);

    // RESET clears Q to zero.
    check_reset_clears_q: assert property (
        @(posedge clk) RESET |=> (Q == 4'b0000)
    );

    // LOAD captures DIN when SHIFT is low.
    check_load_captures_din: assert property (
        @(posedge clk) disable iff (RESET)
        (LOAD && !SHIFT) |=> (Q == $past(DIN))
    );

    // LOAD has priority over SHIFT when both are high.
    check_load_priority_over_shift: assert property (
        @(posedge clk) disable iff (RESET)
        (LOAD && SHIFT) |=> (Q == $past(DIN))
    );

    // SHIFT moves Q left and inserts zero when LOAD is low.
    check_shift_updates_q: assert property (
        @(posedge clk) disable iff (RESET)
        (!LOAD && SHIFT) |=> (
            (Q[3] == $past(Q[2])) &&
            (Q[2] == $past(Q[1])) &&
            (Q[1] == $past(Q[0])) &&
            (Q[0] == 1'b0)
        )
    );

    // Q holds its value when no control is asserted.
    check_hold_when_idle: assert property (
        @(posedge clk) disable iff (RESET)
        (!LOAD && !SHIFT) |=> (Q == $past(Q))
    );

endmodule

