                2'b01, 2'b10: tmp = tmp + 4'd13;
                default: ;
            endcase
            if (d_in) begin
                tmp = tmp + 4'd2;
                tmp = tmp + 4'd1;
            end
            case ({e_in, f_in})
                2'b11: tmp = tmp + 4'd8;
                2'b00: ;
                default: tmp = tmp + 4'd10;
            endcase
            tmp = tmp ^ 4'd7;
            uut_a_path_next = tmp + 4'd14;
        end
