module ALU(clk, rst, A, B, CTRL, RES);

input clk, rst;
input [31:0] A, B;
input [4:0] CTRL;
output reg [31:0] RES;

always @(posedge clk or posedge rst) begin
	if(rst) begin
		RES <= 0;
	end else begin
		case(CTRL)
			5'b00000: // addition
				RES <= A + B;
			5'b00001: // subtraction
				RES <= A - B;
			5'b00010: // bitwise AND
				RES <= A & B;
			5'b00011: // bitwise OR
				RES <= A | B;
			5'b00100: // bitwise XOR
				RES <= A ^ B;
			5'b00101: // logical shift left
				RES <= A << B;
			default:
				RES <= 0;
		endcase
	end
end

endmodule

sva:
module ALU_sva (
    input logic        clk,
    input logic        rst,
    input logic [31:0] A,
    input logic [31:0] B,
    input logic [4:0]  CTRL,
    input logic [31:0] RES
);

    // RES is zero whenever reset is asserted.
    check_reset_clears_res: assert property (
        @(posedge clk) rst |-> (RES == 32'b0)
    );

    // Addition result is registered on the next clock.
    check_addition_result: assert property (
        @(posedge clk) disable iff (rst)
        (CTRL == 5'b00000) |=> (RES == ($past(A) + $past(B)))
    );

    // Subtraction result is registered on the next clock.
    check_subtraction_result: assert property (
        @(posedge clk) disable iff (rst)
        (CTRL == 5'b00001) |=> (RES == ($past(A) - $past(B)))
    );

    // Bitwise AND result is registered on the next clock.
    check_and_result: assert property (
        @(posedge clk) disable iff (rst)
        (CTRL == 5'b00010) |=> (RES == ($past(A) & $past(B)))
    );

    // Bitwise OR result is registered on the next clock.
    check_or_result: assert property (
        @(posedge clk) disable iff (rst)
        (CTRL == 5'b00011) |=> (RES == ($past(A) | $past(B)))
    );

    // Bitwise XOR result is registered on the next clock.
    check_xor_result: assert property (
        @(posedge clk) disable iff (rst)
        (CTRL == 5'b00100) |=> (RES == ($past(A) ^ $past(B)))
    );

    // Logical left shift result is registered on the next clock.
    check_shift_left_result: assert property (
        @(posedge clk) disable iff (rst)
        (CTRL == 5'b00101) |=> (RES == ($past(A) << $past(B)))
    );

    // Unsupported control values drive zero on the next clock.
    check_default_zero_result: assert property (
        @(posedge clk) disable iff (rst)
        (CTRL >= 5'b00110) |=> (RES == 32'b0)
    );

endmodule

rtl:
module top_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input [3:0] load, // Input for synchronous parallel load of counter
    input [3:0] IN,   // Input for the barrel shifter
    input [1:0] SHIFT, // Shift amount input for the barrel shifter
    input MODE,        // Mode input for the barrel shifter
    output [3:0] q // Output from the functional module
);

wire [3:0] counter_out;
wire [3:0] shifted_out;

// Instantiate the counter module
counter counter_inst (
    .clk(clk),
    .reset(reset),
    .load(load),
    .q(counter_out)
);

// Instantiate the barrel shifter module
barrel_shifter shifter_inst (
    .IN(IN),
    .SHIFT(SHIFT),
    .MODE(MODE),
    .q(shifted_out)
);

// Perform logical left shift on the counter output by the shift amount specified in the barrel shifter mode input
assign q = shifted_out << SHIFT;

endmodule

module counter (
    input clk,
    input reset,      // Synchronous active-high reset
    input [3:0] load, // Input for synchronous parallel load of counter
    output reg [3:0] q // Output from the counter
);

always @ (posedge clk) begin
    if (reset) begin
        q <= 0;
    end else if (load) begin
        q <= load;
    end else begin
        q <= q + 1;
    end
end

endmodule

module barrel_shifter (
    input [3:0] IN,   // Input for the barrel shifter
    input [1:0] SHIFT, // Shift amount input for the barrel shifter
    input MODE,        // Mode input for the barrel shifter
    output reg [3:0] q // Output from the barrel shifter
);

always @ (*) begin
    case (MODE)
        2'b00: q = IN >> SHIFT; // Logical right shift
        2'b01: q = IN << SHIFT; // Logical left shift
        2'b10: q = {IN[3], IN[3], IN[3], IN} >> SHIFT; // Arithmetic right shift
        default: q = 0;
    endcase
end

endmodule

sva:
module top_module_sva (
    input logic       clk,
    input logic       reset,
    input logic [3:0] load,
    input logic [3:0] IN,
    input logic [1:0] SHIFT,
    input logic       MODE,
    input logic [3:0] q
);

    // MODE=0 applies a right shift before the final left shift.
    check_mode0_composed_shift: assert property (
        @(posedge clk) disable iff (reset)
        (MODE == 1'b0) |-> (q == ((IN >> SHIFT) << SHIFT))
    );

    // MODE=1 applies a left shift before the final left shift.
    check_mode1_composed_shift: assert property (
        @(posedge clk) disable iff (reset)
        (MODE == 1'b1) |-> (q == ((IN << SHIFT) << SHIFT))
    );

    // With MODE=0 and SHIFT=0, q passes IN through.
    check_mode0_shift0_passthrough: assert property (
        @(posedge clk) disable iff (reset)
        (MODE == 1'b0 && SHIFT == 2'd0) |-> (q == IN)
    );

    // With MODE=0 and SHIFT=1, only the LSB is cleared.
    check_mode0_shift1_result: assert property (
        @(posedge clk) disable iff (reset)
        (MODE == 1'b0 && SHIFT == 2'd1) |-> (q == {IN[3:1], 1'b0})
    );

    // With MODE=0 and SHIFT=2, only IN[3:2] remain.
    check_mode0_shift2_result: assert property (
        @(posedge clk) disable iff (reset)
        (MODE == 1'b0 && SHIFT == 2'd2) |-> (q == {IN[3:2], 2'b00})
    );

    // With MODE=0 and SHIFT=3, only IN[3] remains.
    check_mode0_shift3_result: assert property (
        @(posedge clk) disable iff (reset)
        (MODE == 1'b0 && SHIFT == 2'd3) |-> (q == {IN[3], 3'b000})
    );

    // With MODE=1 and SHIFT=0, q passes IN through.
    check_mode1_shift0_passthrough: assert property (
        @(posedge clk) disable iff (reset)
        (MODE == 1'b1 && SHIFT == 2'd0) |-> (q == IN)
    );

    // With MODE=1 and SHIFT=1, only IN[1:0] remain.
    check_mode1_shift1_result: assert property (
        @(posedge clk) disable iff (reset)
        (MODE == 1'b1 && SHIFT == 2'd1) |-> (q == {IN[1:0], 2'b00})
    );

    // With MODE=1 and SHIFT=2, the 4-bit result becomes zero.
    check_mode1_shift2_result: assert property (
        @(posedge clk) disable iff (reset)
        (MODE == 1'b1 && SHIFT == 2'd2) |-> (q == 4'b0000)
    );

    // With MODE=1 and SHIFT=3, the 4-bit result becomes zero.
    check_mode1_shift3_result: assert property (
        @(posedge clk) disable iff (reset)
        (MODE == 1'b1 && SHIFT == 2'd3) |-> (q == 4'b0000)
    );

endmodule

rtl:
module top_module ( 
    input wire [2:0] vec,
    input wire select,
    output wire [2:0] outv,
    output reg o2,
    output reg o1,
    output reg o0  );

    wire [2:0] mux_out;
    wire [7:0] decoder_out;

    // Multiplexers
    assign mux_out[0] = select ? vec[0] : 1'b0;
    assign mux_out[1] = select ? vec[1] : 1'b0;
    assign mux_out[2] = select ? vec[2] : 1'b0;

    // Decoders
    assign decoder_out[0] = ~(|vec);
    assign decoder_out[1] = (vec[1:0] == 2'b00) | (vec[1:0] == 2'b11);
    assign decoder_out[2] = vec[2];
    assign decoder_out[3] = (vec[1:0] == 2'b01) | (vec[1:0] == 2'b10);
    assign decoder_out[4] = vec[2] & (~vec[1]);
    assign decoder_out[5] = vec[0] & (~vec[2]);
    assign decoder_out[6] = vec[1] & (~vec[2]);
    assign decoder_out[7] = vec[1] & vec[0] & vec[2];

    // Output assignments
    assign outv = mux_out;
    always @(*) begin
        o2 = decoder_out[2];
        o1 = decoder_out[1];
        o0 = decoder_out[0];
    end

endmodule

sva:
module top_module_sva (
    input logic [2:0] vec,
