module isolator
(
	input                 rc_ackn_rr    ,
	output                rc_ackn       ,

	output                p_prdy        ,
	output     [31:0]     p_data        ,
	output                c_crdy        ,
	output                c_cerr        ,

	input                 p_prdy_rr     ,
	input      [31:0]     p_data_rr     ,
	input                 c_crdy_rr     ,
	input                 c_cerr_rr     ,

	input                 is_reconfn
);

assign rc_ackn    = (~is_reconfn)? 1'b1: rc_ackn_rr;
	assign p_prdy     = (~is_reconfn)? 1'b0: p_prdy_rr;
	assign p_data     = (~is_reconfn)? 32'h0: p_data_rr;
	assign c_crdy     = (~is_reconfn)? 1'b0: c_crdy_rr;

	assign c_cerr     = (~is_reconfn)? 1'b1: c_cerr_rr;

endmodule

sva:
module isolator_sva (
    input logic        rc_ackn_rr,
    input logic        rc_ackn,
    input logic        p_prdy,
    input logic [31:0] p_data,
    input logic        c_crdy,
    input logic        c_cerr,
    input logic        p_prdy_rr,
    input logic [31:0] p_data_rr,
    input logic        c_crdy_rr,
    input logic        c_cerr_rr,
    input logic        is_reconfn
);

    // rc_ackn is forced high when isolation is active.
    check_rc_ackn_isolated: assert property (
        @($global_clock) (!is_reconfn) |-> (rc_ackn == 1'b1)
    );

    // rc_ackn passes through in normal mode.
    check_rc_ackn_passthrough: assert property (
        @($global_clock) is_reconfn |-> (rc_ackn == rc_ackn_rr)
    );

    // p_prdy is forced low when isolation is active.
    check_p_prdy_isolated: assert property (
        @($global_clock) (!is_reconfn) |-> (p_prdy == 1'b0)
    );

    // p_prdy passes through in normal mode.
    check_p_prdy_passthrough: assert property (
        @($global_clock) is_reconfn |-> (p_prdy == p_prdy_rr)
    );

    // p_data is forced to zero when isolation is active.
    check_p_data_isolated: assert property (
        @($global_clock) (!is_reconfn) |-> (p_data == 32'h00000000)
    );

    // p_data passes through in normal mode.
    check_p_data_passthrough: assert property (
        @($global_clock) is_reconfn |-> (p_data == p_data_rr)
    );

    // c_crdy is forced low when isolation is active.
    check_c_crdy_isolated: assert property (
        @($global_clock) (!is_reconfn) |-> (c_crdy == 1'b0)
    );

    // c_crdy passes through in normal mode.
    check_c_crdy_passthrough: assert property (
        @($global_clock) is_reconfn |-> (c_crdy == c_crdy_rr)
    );

    // c_cerr is forced high when isolation is active.
    check_c_cerr_isolated: assert property (
        @($global_clock) (!is_reconfn) |-> (c_cerr == 1'b1)
    );

    // c_cerr passes through in normal mode.
    check_c_cerr_passthrough: assert property (
        @($global_clock) is_reconfn |-> (c_cerr == c_cerr_rr)
    );

endmodule

module counter_sva #(
    parameter HIGH = 1'b1,
    parameter LOW  = 1'b0
)(
    input logic       CLK,
    input logic       RESET,
    input logic       ENABLE,
    input logic [3:0] COUNT
);

    // Reset clears COUNT on the following clock.
    check_reset_clears_count: assert property (
        @(posedge CLK)
        (RESET == HIGH) |=> (COUNT == 4'h0)
    );

    // Reset overrides ENABLE when both are asserted.
    check_reset_priority_over_enable: assert property (
        @(posedge CLK)
        ((RESET == HIGH) && (ENABLE == HIGH)) |=> (COUNT == 4'h0)
    );

    // ENABLE causes COUNT to increment by one outside reset.
    check_increment_when_enabled: assert property (
        @(posedge CLK) disable iff (RESET == HIGH)
        (ENABLE == HIGH) |=> (COUNT == ($past(COUNT) + 4'd1))
    );

    // COUNT holds when ENABLE is low outside reset.
    check_hold_when_disabled: assert property (
        @(posedge CLK) disable iff (RESET == HIGH)
        (ENABLE == LOW) |=> (COUNT == $past(COUNT))
    );

    // The 4-bit counter wraps from 15 to 0 when enabled.
    check_wrap_from_max: assert property (
        @(posedge CLK) disable iff (RESET == HIGH)
        ((ENABLE == HIGH) && (COUNT == 4'hF)) |=> (COUNT == 4'h0)
    );

endmodule

rtl:
module barrel_shifter (
    input [3:0] DATA,
    input [1:0] SHIFT,
    output [3:0] OUT
);

    assign OUT[3] = SHIFT[1] ? DATA[1] : SHIFT[0] ? DATA[2] : SHIFT[0] ? DATA[2] : SHIFT[1] ? DATA[2] : SHIFT[1] ? DATA[0] : 1'b0;
    assign OUT[2] = SHIFT[1] ? DATA[0] : SHIFT[0] ? DATA[3] : SHIFT[0] ? DATA[3] : SHIFT[1] ? DATA[1] : SHIFT[1] ? DATA[3] : 1'b0;
    assign OUT[1] = SHIFT[1] ? DATA[3] : SHIFT[0] ? DATA[2] : SHIFT[0] ? DATA[2] : SHIFT[1] ? DATA[0] : SHIFT[1] ? DATA[1] : 1'b0;
    assign OUT[0] = SHIFT[1] ? DATA[2] : SHIFT[0] ? DATA[1] : SHIFT[0] ? DATA[1] : SHIFT[1] ? DATA[3] : SHIFT[1] ? DATA[2] : 1'b0;

endmodule

sva:
module barrel_shifter_sva (
    input logic [3:0] DATA,
    input logic [1:0] SHIFT,
    input logic [3:0] OUT
);

    // OUT[3] matches the implemented combinational expression.
    check_out3_function: assert property (
        @($global_clock)
        OUT[3] == (SHIFT[1] ? DATA[1] :
                  (SHIFT[0] ? DATA[2] :
                  (SHIFT[0] ? DATA[2] :
                  (SHIFT[1] ? DATA[2] :
                  (SHIFT[1] ? DATA[0] : 1'b0)))))
    );

    // OUT[2] matches the implemented combinational expression.
    check_out2_function: assert property (
        @($global_clock)
        OUT[2] == (SHIFT[1] ? DATA[0] :
                  (SHIFT[0] ? DATA[3] :
                  (SHIFT[0] ? DATA[3] :
                  (SHIFT[1] ? DATA[1] :
                  (SHIFT[1] ? DATA[3] : 1'b0)))))
    );

    // OUT[1] matches the implemented combinational expression.
    check_out1_function: assert property (
        @($global_clock)
        OUT[1] == (SHIFT[1] ? DATA[3] :
                  (SHIFT[0] ? DATA[2] :
                  (SHIFT[0] ? DATA[2] :
                  (SHIFT[1] ? DATA[0] :
                  (SHIFT[1] ? DATA[1] : 1'b0)))))
    );

    // OUT[0] matches the implemented combinational expression.
    check_out0_function: assert property (
        @($global_clock)
        OUT[0] == (SHIFT[1] ? DATA[2] :
                  (SHIFT[0] ? DATA[1] :
                  (SHIFT[0] ? DATA[1] :
                  (SHIFT[1] ? DATA[3] :
                  (SHIFT[1] ? DATA[2] : 1'b0)))))
    );

    // SHIFT=00 drives all outputs low.
    check_shift00_zero_output: assert property (
        @($global_clock)
        (SHIFT == 2'b00) |-> (OUT == 4'b0000)
    );

    // SHIFT=01 produces the implemented output mapping.
    check_shift01_output_map: assert property (
        @($global_clock)
        (SHIFT == 2'b01) |-> (OUT == {DATA[2], DATA[3], DATA[2], DATA[1]})
    );

    // SHIFT[1] has priority and selects the implemented output mapping.
    check_shift1_priority_output_map: assert property (
        @($global_clock)
        (SHIFT[1] == 1'b1) |-> (OUT == {DATA[1], DATA[0], DATA[3], DATA[2]})
    );

endmodule

rtl:
module ripple_carry_adder(
  input [3:0] A,
  input [3:0] B,
  input Cin,
  output [3:0] S,
  output Cout
);

wire [3:0] sum;
wire [3:0] carry;

// full-adder for least significant bit
full_adder fa0(
  .A(A[0]),
  .B(B[0]),
  .Cin(Cin),
  .S(sum[0]),
  .Cout(carry[0])
);

// full-adder for second bit
full_adder fa1(
  .A(A[1]),
  .B(B[1]),
  .Cin(carry[0]),
  .S(sum[1]),
  .Cout(carry[1])
);

// full-adder for third bit
full_adder fa2(
  .A(A[2]),
  .B(B[2]),
  .Cin(carry[1]),
  .S(sum[2]),
  .Cout(carry[2])
);

// full-adder for most significant bit
full_adder fa3(
  .A(A[3]),
  .B(B[3]),
  .Cin(carry[2]),
  .S(sum[3]),
  .Cout(Cout)
);

assign S = sum;

endmodule


module full_adder(
  input A,
  input B,
  input Cin,
  output S,
  output Cout
);

assign {Cout, S} = A + B + Cin;

endmodule

sva:
module ripple_carry_adder_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic Cin,
    input logic [3:0] S,
    input logic Cout
);

    // DUT is purely combinational and has no reset; clk is a sampling clock.

    // The 5-bit output must equal A + B + Cin.
    check_total_sum: assert property (
        @(posedge clk) {Cout, S} == ({1'b0, A} + {1'b0, B} + Cin)
    );

    // The least-significant sum bit is the XOR of the LSB inputs and carry-in.
    check_lsb_sum: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0] ^ Cin)
    );

    // Bit 1 must use the carry generated from bit 0.
    check_bit1_ripple: assert property (
        @(posedge clk) S[1] == (A[1] ^ B[1] ^ ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin)))
    );

    // Adding zero with no carry-in must reproduce A with no carry-out.
    check_add_zero_to_a: assert property (
        @(posedge clk) (B == 4'h0 && Cin == 1'b0) |-> ({Cout, S} == {1'b0, A})
    );

    // Adding zero with no carry-in must reproduce B with no carry-out.
    check_add_zero_to_b: assert property (
        @(posedge clk) (A == 4'h0 && Cin == 1'b0) |-> ({Cout, S} == {1'b0, B})
    );

    // All-zero inputs must produce a zero result.
    check_all_zero_inputs: assert property (
        @(posedge clk) (A == 4'h0 && B == 4'h0 && Cin == 1'b0) |-> ({Cout, S} == 5'h00)
    );

    // Carry-in alone must increment the zero input case to 1.
    check_cin_only: assert property (
        @(posedge clk) (A == 4'h0 && B == 4'h0 && Cin == 1'b1) |-> ({Cout, S} == 5'h01)
    );

    // Carry-out must be high exactly when the arithmetic result is 16 or more.
    check_cout_overflow: assert property (
        @(posedge clk) Cout == (({1'b0, A} + {1'b0, B} + Cin) >= 5'd16)
    );

    // Maximum operands without carry-in must produce 0xE with carry-out.
    check_max_operands_no_cin: assert property (
        @(posedge clk) (A == 4'hF && B == 4'hF && Cin == 1'b0) |-> ({Cout, S} == 5'h1E)
    );

    // Maximum operands with carry-in must produce 0xF with carry-out.
    check_max_operands_with_cin: assert property (
        @(posedge clk) (A == 4'hF && B == 4'hF && Cin == 1'b1) |-> ({Cout, S} == 5'h1F)
    );

endmodule

