module D2STR_B_sva #(
    parameter integer len = 16
) (
    input logic [127:0] str,
    input logic [len-1:0] d
);

    function automatic logic [127:0] bin_string(input logic [len-1:0] d_in);
        integer j;
        begin
            for (j = 0; j < len; j = j + 1) begin
                bin_string[8*j+7:8*j] = d_in[j] ? "1" : "0";
