module D2STR_H_sva #(
    parameter integer len = 16
) (
    input logic        GCLK,
    input logic [127:0] str,
    input logic [4*len-1:0] d
);

    function automatic logic [7:0] hex_char(input logic [3:0] nibble);
        begin
            case (nibble)
                4'd0:  hex_char = "0";
                4'd1:  hex_char = "1";
