module xnor3_2 (
    input A,
    input B,
    input C,
    output X
);

    wire AB_xor = A ^ B;
    wire ABC_xor = AB_xor ^ C;
    wire ABC_xor_not = ~ABC_xor;
    assign X = ABC_xor_not;

endmodule

sva:
module xnor3_2_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic C,
    input logic X
);

    // X must equal the 3-input XNOR of A, B, and C.
    check_x_matches_three_input_xnor: assert property (
        @(posedge clk) X == ~(A ^ B ^ C)
    );

    // Even input parity drives X high.
    check_x_high_on_even_parity: assert property (
        @(posedge clk) ((A ^ B ^ C) == 1'b0) |-> (X == 1'b1)
    );

    // Odd input parity drives X low.
    check_x_low_on_odd_parity: assert property (
        @(posedge clk) ((A ^ B ^ C) == 1'b1) |-> (X == 1'b0)
    );

    // X stays stable when all inputs stay stable.
    check_x_stable_when_inputs_stable: assert property (
        @(posedge clk) (!$initstate && $stable({A, B, C})) |-> $stable(X)
    );

    // Changing only A toggles X.
    check_x_toggles_when_a_changes_alone: assert property (
        @(posedge clk) (!$initstate && $changed(A) && $stable(B) && $stable(C)) |-> $changed(X)
    );

    // Changing only B toggles X.
    check_x_toggles_when_b_changes_alone: assert property (
        @(posedge clk) (!$initstate && $stable(A) && $changed(B) && $stable(C)) |-> $changed(X)
    );

    // Changing only C toggles X.
    check_x_toggles_when_c_changes_alone: assert property (
        @(posedge clk) (!$initstate && $stable(A) && $stable(B) && $changed(C)) |-> $changed(X)
    );

    // Changing any two inputs together keeps X stable.
    check_x_stable_when_two_inputs_change: assert property (
        @(posedge clk)
        (!$initstate &&
         (($changed(A) && $changed(B) && $stable(C)) ||
          ($changed(A) && $stable(B) && $changed(C)) ||
          ($stable(A) && $changed(B) && $changed(C))))
        |-> $stable(X)
    );

    // Changing all three inputs together toggles X.
    check_x_toggles_when_all_inputs_change: assert property (
        @(posedge clk) (!$initstate && $changed(A) && $changed(B) && $changed(C)) |-> $changed(X)
    );

endmodule

rtl:
module Register #(
    parameter Width = 32
)(
    input Clock, Reset, Set, Enable,
    input [Width-1:0] In,
    output reg [Width-1:0] Out
);

parameter Initial = {Width{1'bx}};
parameter AsyncReset = 0;
parameter AsyncSet = 0;
parameter ResetValue = {Width{1'b0}};
parameter SetValue = {Width{1'b1}};

always @ (posedge Clock) begin
    if (AsyncReset && !Reset) begin
        Out <= ResetValue;
    end else if (AsyncSet && Set) begin
        Out <= SetValue;
    end else if (Reset && Set) begin
        Out <= SetValue;
    end else if (Reset) begin
        Out <= ResetValue;
    end else if (Set) begin
        Out <= SetValue;
    end else if (Enable) begin
        Out <= In;
    end
end

endmodule

sva:
module Register_sva #(
    parameter int Width = 32,
    parameter AsyncReset = 0,
    parameter AsyncSet = 0,
    parameter [Width-1:0] ResetValue = {Width{1'b0}},
    parameter [Width-1:0] SetValue = {Width{1'b1}}
)(
    input logic Clock,
    input logic Reset,
    input logic Set,
    input logic Enable,
    input logic [Width-1:0] In,
    input logic [Width-1:0] Out
);

    // Low Reset with AsyncReset enabled loads ResetValue.
    check_asyncreset_low_loads_reset_value: assert property (
        @(posedge Clock) disable iff ($initstate)
        $past(AsyncReset && !Reset) |-> (Out == ResetValue)
    );

    // Set loads SetValue unless low-active AsyncReset took priority.
    check_set_loads_set_value: assert property (
        @(posedge Clock) disable iff ($initstate || $past(AsyncReset && !Reset))
        $past(Set) |-> (Out == SetValue)
    );

    // Reset high without Set loads ResetValue.
    check_reset_high_loads_reset_value: assert property (
        @(posedge Clock) disable iff ($initstate)
        $past(Reset && !Set) |-> (Out == ResetValue)
    );

    // Enable loads In when Set and Reset are low.
    check_enable_loads_input: assert property (
        @(posedge Clock) disable iff ($initstate || $past(AsyncReset && !Reset))
        $past(!Reset && !Set && Enable) |-> (Out == $past(In))
    );

    // No active control holds the previous value.
    check_no_control_holds_value: assert property (
        @(posedge Clock) disable iff ($initstate || $past(AsyncReset && !Reset))
        $past(!Reset && !Set && !Enable) |-> (Out == $past(Out))
    );

    // Set has priority over Reset when both are high.
    check_set_priority_over_reset: assert property (
        @(posedge Clock) disable iff ($initstate || $past(AsyncReset && !Reset))
        $past(Reset && Set) |-> (Out == SetValue)
    );

endmodule

module binary_counter_sva (
    input logic       clk,
    input logic       reset,
    input logic       enable,
    input logic [3:0] count_out
);

    // Reset drives the counter to zero on the following clock.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count_out == 4'b0000)
    );

    // Reset has priority over enable and still clears the counter.
    check_reset_priority_over_enable: assert property (
        @(posedge clk) (reset && enable) |=> (count_out == 4'b0000)
    );

    // When enabled outside reset, the counter increments by one.
    check_count_increments_when_enabled: assert property (
        @(posedge clk) disable iff (reset)
        enable |=> (count_out == ($past(count_out) + 4'd1))
    );

    // When disabled outside reset, the counter holds its value.
    check_count_holds_when_disabled: assert property (
        @(posedge clk) disable iff (reset)
        !enable |=> (count_out == $past(count_out))
    );

    // The 4-bit counter wraps from 15 back to 0 when enabled.
    check_wraps_from_max_to_zero: assert property (
        @(posedge clk) disable iff (reset)
        (enable && (count_out == 4'hF)) |=> (count_out == 4'h0)
    );

endmodule

