module register_bank (
  input clock,
  input [31:0] data,
  input [4:0] rdaddress,
  input [4:0] wraddress,
  input wren,
  output reg [31:0] q
);

  reg [31:0] ram_q;

  always @(posedge clock) begin
    if (wren) begin
      ram_q <= data;
    end
    q <= ram_q;
  end

endmodule

sva:
module register_bank_sva (
    input logic        clock,
    input logic [31:0] data,
    input logic [4:0]  rdaddress,
    input logic [4:0]  wraddress,
    input logic        wren,
    input logic [31:0] q
);

    // A write updates q with the written data two cycles later.
    check_write_reaches_q_after_two_cycles: assert property (
        @(posedge clock) wren |-> ##2 (q == $past(data, 2))
    );

    // Without a write, q holds its prior sampled value two cycles later.
    check_no_write_holds_q_after_two_cycles: assert property (
        @(posedge clock) !wren |-> ##2 (q == $past(q))
    );

    // Back-to-back writes appear on q in the same order, two cycles later.
    check_back_to_back_writes_preserve_order: assert property (
        @(posedge clock) (wren ##1 wren) |=> ((q == $past(data, 2)) ##1 (q == $past(data, 2)))
    );

    // A write followed by an idle cycle makes q take the write data, then hold it.
    check_write_then_idle_holds_value: assert property (
        @(posedge clock) (wren ##1 !wren) |=> ((q == $past(data, 2)) ##1 (q == $past(q)))
    );

    // An idle cycle before a write delays any q update until the write reaches q.
    check_idle_then_write_delays_update: assert property (
        @(posedge clock) (!wren ##1 wren) |=> ((q == $past(q)) ##1 (q == $past(data, 2)))
    );

endmodule

rtl:
module shift_reg_comb (
    input clk,          // Clock input
    input d,            // Input for shift register
    input [3:0] in,     // Input for combinational circuit
    output out_and,     // 2-level AND-OR circuit output
    output out_or,      // 2-level OR-AND circuit output
    output out_xor,     // 2-level XOR-AND circuit output
    output [7:0] sum    // Sum of shift register and combinational circuit outputs
);

reg [2:0] shift_reg;
wire q;

// Shift register
always @(posedge clk) begin
    shift_reg <= {shift_reg[1:0], d};
end

assign q = shift_reg[2];

// Combinational circuit
wire and1 = in[0] & in[1];
wire and2 = in[2] & in[3];
wire or1 = in[0] | in[1];
wire or2 = in[2] | in[3];
wire xor1 = in[0] ^ in[1];
wire xor2 = in[2] ^ in[3];

assign out_and = and1 | and2;
assign out_or = or1 & or2;
assign out_xor = xor1 & xor2;

// Sum module
wire [7:0] shift_sum = {1'b0, shift_reg};
wire [7:0] comb_sum = {1'b0, out_and, out_or, out_xor};

assign sum = shift_sum + comb_sum;

endmodule

sva:
module shift_reg_comb_sva (
    input logic clk,
    input logic d,
    input logic [3:0] in,
    input logic out_and,
    input logic out_or,
    input logic out_xor,
    input logic [7:0] sum
);

    // out_and matches the two-level AND-OR function.
    check_out_and_function: assert property (
        @(posedge clk)
        out_and == ((in[0] & in[1]) | (in[2] & in[3]))
    );

    // out_or matches the two-level OR-AND function.
    check_out_or_function: assert property (
        @(posedge clk)
        out_or == ((in[0] | in[1]) & (in[2] | in[3]))
    );

    // out_xor matches the two-level XOR-AND function.
    check_out_xor_function: assert property (
        @(posedge clk)
        out_xor == ((in[0] ^ in[1]) & (in[2] ^ in[3]))
    );

    // The sum never uses bits above bit 3.
    check_sum_upper_bits_zero: assert property (
        @(posedge clk)
        sum[7:4] == 4'b0000
    );

    // After one clock, sum bit 0 reflects the first shift stage plus out_xor.
    check_sum_bit0_tracks_shift_stage0: assert property (
        @(posedge clk)
        (!$initstate) |-> (sum[0] == ($past(d,1) ^ out_xor))
    );

    // After two clocks, sum bit 1 reflects the second shift stage and bit-0 carry.
    check_sum_bit1_tracks_shift_stage1_and_carry: assert property (
        @(posedge clk)
        (!$initstate && !$past($initstate,1)) |->
            (sum[1] == ($past(d,2) ^ out_or ^ ($past(d,1) & out_xor)))
    );

    // After three clocks, sum equals delayed d history plus the combinational outputs.
    check_sum_matches_shifted_d_and_comb_logic: assert property (
        @(posedge clk)
        (!$initstate && !$past($initstate,1) && !$past($initstate,2)) |->
            (sum == ({5'b0, $past(d,3), $past(d,2), $past(d,1)} +
                     {5'b0, out_and, out_or, out_xor}))
    );

    // With zero combinational contribution, sum is only the shifted d history.
    check_sum_equals_shift_value_when_comb_zero: assert property (
        @(posedge clk)
        (!$initstate && !$past($initstate,1) && !$past($initstate,2) &&
         (out_and == 1'b0) && (out_or == 1'b0) && (out_xor == 1'b0)) |->
            (sum == {5'b0, $past(d,3), $past(d,2), $past(d,1)})
    );

    // With three zero d samples, sum is only the combinational contribution.
    check_sum_equals_comb_value_when_shift_history_zero: assert property (
        @(posedge clk)
        (!$initstate && !$past($initstate,1) && !$past($initstate,2) &&
         ($past(d,1) == 1'b0) && ($past(d,2) == 1'b0) && ($past(d,3) == 1'b0)) |->
            (sum == {5'b0, out_and, out_or, out_xor})
    );

endmodule

rtl:
module FOURBITADDER
(
  input [3:0] A,
  input [3:0] B,
  input Cin,
  output [3:0] S,
  output Cout
);

  wire [3:0] c;

  FULLADDER fa0(A[0], B[0], Cin, c[0], S[0]);
  FULLADDER fa1(A[1], B[1], c[0], c[1], S[1]);
  FULLADDER fa2(A[2], B[2], c[1], c[2], S[2]);
  FULLADDER fa3(A[3], B[3], c[2], Cout, S[3]);

endmodule

module FULLADDER
(
  input A,
  input B,
  input Cin,
  output Cout,
  output S
);

  assign S = A^B^Cin;
  assign Cout = (A&B)|(B&Cin)|(A&Cin);

endmodule

sva:
module FOURBITADDER_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic Cin,
    input logic [3:0] S,
    input logic Cout
);

    function automatic logic fa_cout (
        input logic a,
        input logic b,
        input logic cin
    );
        fa_cout = (a & b) | (b & cin) | (a & cin);
    endfunction

    // The 5-bit result matches A + B + Cin.
    check_total_sum: assert property (
        @(posedge clk) {Cout, S} == ({1'b0, A} + {1'b0, B} + Cin)
    );

    // Sum bit 0 matches the first full-adder XOR.
    check_sum_bit0: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0] ^ Cin)
    );

    // Sum bit 1 uses the carry from bit 0.
    check_sum_bit1: assert property (
        @(posedge clk) S[1] == (A[1] ^ B[1] ^ fa_cout(A[0], B[0], Cin))
    );

    // Sum bit 2 uses the carry from bit 1.
    check_sum_bit2: assert property (
        @(posedge clk) S[2] == (A[2] ^ B[2] ^ fa_cout(A[1], B[1], fa_cout(A[0], B[0], Cin)))
    );

    // Sum bit 3 uses the carry from bit 2.
    check_sum_bit3: assert property (
        @(posedge clk) S[3] == (A[3] ^ B[3] ^ fa_cout(A[2], B[2], fa_cout(A[1], B[1], fa_cout(A[0], B[0], Cin))))
    );

    // Cout matches the last full-adder carry.
    check_cout: assert property (
        @(posedge clk) Cout == fa_cout(A[3], B[3], fa_cout(A[2], B[2], fa_cout(A[1], B[1], fa_cout(A[0], B[0], Cin))))
    );

endmodule

