module cond_sum(input [3:0] X,Y,input Cin,output [3:0] Sum,output C_out
    );
reg [1:0] c00sum00,c01sum01,c10sum10,c11sum11,c20sum20,c21sum21,c30sum30,c31sum31;

wire [1:0]mux_out01,mux_out02,mux_out03,mux_out04;
wire [2:0]mux_out11,mux_out12;
assign Sum = Cin? {mux_out12[1:0],mux_out02[0],c01sum01[0]}:{mux_out11[1:0],mux_out01[0],c00sum00[0]};
assign C_out = Cin?mux_out12[2]:mux_out11[2]; 
assign mux_out01=c00sum00[1]?c11sum11:c10sum10,
       mux_out02=c01sum01[1]?c11sum11:c10sum10,
		 mux_out03=c20sum20[1]?c31sum31:c30sum30,
		 mux_out04=c21sum21[1]?c31sum31:c30sum30;

assign mux_out11=mux_out01[1]?{mux_out04,c21sum21[0]}:{mux_out03,c20sum20[0]},
       mux_out12=mux_out02[1]?{mux_out04,c21sum21[0]}:{mux_out03,c20sum20[0]};
always @* begin	 
cond_cell(X[0],Y[0],c00sum00,c01sum01);
cond_cell(X[1],Y[1],c10sum10,c11sum11);
cond_cell(X[2],Y[2],c20sum20,c21sum21);
cond_cell(X[3],Y[3],c30sum30,c31sum31);	 
end	 

task cond_cell(input x,y, output [1:0] c0sum0,c1sum1);
reg xr;
begin 
       xr = x^y;
       c0sum0 ={x&y,xr};
       c1sum1 ={x|y,~xr}; 
		 end
endtask

endmodule

sva:
module cond_sum_sva (
    input logic [3:0] X,
    input logic [3:0] Y,
    input logic Cin,
    input logic [3:0] Sum,
    input logic C_out
);

    // Full output matches 4-bit addition with carry-in.
    check_full_add_result: assert property (
        @($global_clock)
        {C_out, Sum} == ({1'b0, X} + {1'b0, Y} + Cin)
    );

    // Sum[0] is the bit-0 full-adder sum.
    check_sum_bit0: assert property (
        @($global_clock)
        Sum[0] == (X[0] ^ Y[0] ^ Cin)
    );

    // Sum[1] uses the carry from bit 0.
    check_sum_bit1: assert property (
        @($global_clock)
        Sum[1] == (X[1] ^ Y[1] ^ ((X[0] & Y[0]) | (Cin & (X[0] ^ Y[0]))))
    );

    // Sum[2] uses the carry from the lower two bits.
    check_sum_bit2: assert property (
        @($global_clock)
        Sum[2] == (X[2] ^ Y[2] ^ (({1'b0, X[1:0]} + {1'b0, Y[1:0]} + Cin) > 3'd3))
    );

    // Sum[3] uses the carry from the lower three bits.
    check_sum_bit3: assert property (
        @($global_clock)
        Sum[3] == (X[3] ^ Y[3] ^ (({1'b0, X[2:0]} + {1'b0, Y[2:0]} + Cin) > 4'd7))
    );

    // C_out is the carry out of the 4-bit addition.
    check_carry_out: assert property (
        @($global_clock)
        C_out == (({1'b0, X} + {1'b0, Y} + Cin) > 5'd15)
    );

    // Cin low selects plain X + Y.
    check_no_carry_in_path: assert property (
        @($global_clock)
        !Cin |-> ({C_out, Sum} == ({1'b0, X} + {1'b0, Y}))
    );

    // Cin high selects X + Y + 1.
    check_carry_in_path: assert property (
        @($global_clock)
        Cin |-> ({C_out, Sum} == ({1'b0, X} + {1'b0, Y} + 5'd1))
    );

    // Stable inputs keep outputs stable.
    check_output_stable_when_inputs_stable: assert property (
        @($global_clock)
        (!$initstate && $stable({X, Y, Cin})) |-> $stable({C_out, Sum})
    );

    // Sum[1:0] depends only on X[1:0], Y[1:0], and Cin.
    check_low_two_bits_local: assert property (
        @($global_clock)
        (!$initstate && $stable({X[1:0], Y[1:0], Cin})) |-> $stable(Sum[1:0])
    );

    // Sum[2:0] depends only on X[2:0], Y[2:0], and Cin.
    check_low_three_bits_local: assert property (
        @($global_clock)
        (!$initstate && $stable({X[2:0], Y[2:0], Cin})) |-> $stable(Sum[2:0])
    );

endmodule

module addsub_4bit_sva (
    input logic        clk,
    input logic [3:0]  A,
    input logic [3:0]  B,
    input logic        S,
    input logic [3:0]  F
);

    // F matches the selected arithmetic operation every sampled cycle.
    check_selected_operation: assert property (
        @(posedge clk) F == (S ? (A - B) : (A + B))
    );

    // In add mode, F is the 4-bit sum of A and B.
    check_add_mode_result: assert property (
        @(posedge clk) (S == 1'b0) |-> (F == (A + B))
    );

    // In subtract mode, F is the 4-bit difference of A and B.
    check_sub_mode_result: assert property (
        @(posedge clk) (S == 1'b1) |-> (F == (A - B))
    );

    // Adding zero on B passes A through to F.
    check_add_zero_on_b: assert property (
        @(posedge clk) ((S == 1'b0) && (B == 4'h0)) |-> (F == A)
    );

    // Adding zero on A passes B through to F.
    check_add_zero_on_a: assert property (
        @(posedge clk) ((S == 1'b0) && (A == 4'h0)) |-> (F == B)
    );

    // Subtracting zero on B passes A through to F.
    check_sub_zero_on_b: assert property (
        @(posedge clk) ((S == 1'b1) && (B == 4'h0)) |-> (F == A)
    );

    // Subtracting equal operands produces zero.
    check_sub_equal_operands_zero: assert property (
        @(posedge clk) ((S == 1'b1) && (A == B)) |-> (F == 4'h0)
    );

endmodule

