module simple_calc(A, B, op, C);
	input [7:0] A;
	input [7:0] B;
	input [1:0] op;
	output reg [7:0] C;

	always @(*)
	begin
		case(op)
			2'b00: C = A + B;
			2'b01: C = A - B;
			2'b10: C = A * B;
			2'b11: C = A / B;
		endcase
	end
endmodule

sva:
module simple_calc_sva (
    input logic        clk,
    input logic [7:0]  A,
    input logic [7:0]  B,
    input logic [1:0]  op,
    input logic [7:0]  C
);

    // op=00 drives C with the 8-bit sum of A and B.
    check_add_result: assert property (
        @(posedge clk) (op == 2'b00) |-> (C == ((A + B) & 8'hFF))
    );

    // op=01 drives C with the 8-bit difference of A and B.
    check_sub_result: assert property (
        @(posedge clk) (op == 2'b01) |-> (C == ((A - B) & 8'hFF))
    );

    // op=10 drives C with the low 8 bits of the product of A and B.
    check_mul_result: assert property (
        @(posedge clk) (op == 2'b10) |-> (C == ((A * B) & 8'hFF))
    );

    // op=11 with a nonzero divisor drives C with A divided by B.
    check_div_result: assert property (
        @(posedge clk) ((op == 2'b11) && (B != 8'h00)) |-> (C == ((A / B) & 8'hFF))
    );

endmodule

rtl:
module Contador_AD_Minutos(
    input rst,
	 input [7:0]estado,
	 input [1:0] en,
    input [7:0] Cambio,
	 input got_data,
    input clk,
    output reg [(N-1):0] Cuenta
    );


	 parameter N = 6;
	 parameter X = 59;

    always @(posedge clk)
	 if (rst)
	    Cuenta <= 0;
    else	if (en == 2'd1 && (estado == 8'h6C || estado == 8'h75))
         begin
	         if (Cambio == 8'h73 && got_data)
				begin
				   if (Cuenta == X)
				      Cuenta <= 0;
					else 
				      Cuenta <= Cuenta + 1'd1;
				end
				else if (Cambio == 8'h72 && got_data)
					  begin
				        if (Cuenta == 0)
						     Cuenta <= X;
					     else 
						     Cuenta <= Cuenta - 1'd1;
				     end
					  else 
					     Cuenta <= Cuenta;
	      end
	      else 
			   Cuenta <= Cuenta;
endmodule

sva:
module Contador_AD_Minutos_sva #(
    parameter int N = 6,
    parameter [N-1:0] X = 59
) (
    input logic rst,
    input logic [7:0] estado,
    input logic [1:0] en,
    input logic [7:0] Cambio,
    input logic got_data,
    input logic clk,
    input logic [N-1:0] Cuenta
);

    // Reset clears the counter.
    check_reset_clears_cuenta: assert property (
        @(posedge clk) rst |=> (Cuenta == '0)
    );

    // Counter holds when enable is not 1.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (rst)
        (en != 2'd1) |=> (Cuenta == $past(Cuenta))
    );

    // Counter holds when estado is not 6C or 75.
    check_hold_when_estado_not_allowed: assert property (
        @(posedge clk) disable iff (rst)
        ((en == 2'd1) && !((estado == 8'h6C) || (estado == 8'h75)))
        |=> (Cuenta == $past(Cuenta))
    );

    // Counter holds in active states when got_data is low.
    check_hold_without_got_data: assert property (
        @(posedge clk) disable iff (rst)
        ((en == 2'd1) && ((estado == 8'h6C) || (estado == 8'h75)) && !got_data)
        |=> (Cuenta == $past(Cuenta))
    );

    // Counter holds when Cambio is not 73 or 72.
    check_hold_on_unrecognized_cambio: assert property (
        @(posedge clk) disable iff (rst)
        ((en == 2'd1) && ((estado == 8'h6C) || (estado == 8'h75)) && got_data &&
         !((Cambio == 8'h73) || (Cambio == 8'h72)))
        |=> (Cuenta == $past(Cuenta))
    );

    // Increment wraps from X to zero.
    check_increment_wraps_at_x: assert property (
        @(posedge clk) disable iff (rst)
        ((en == 2'd1) && ((estado == 8'h6C) || (estado == 8'h75)) &&
         (Cambio == 8'h73) && got_data && (Cuenta == X))
        |=> (Cuenta == '0)
    );

    // Increment advances by one below X.
    check_increment_advances_by_one: assert property (
        @(posedge clk) disable iff (rst)
        ((en == 2'd1) && ((estado == 8'h6C) || (estado == 8'h75)) &&
         (Cambio == 8'h73) && got_data && (Cuenta != X))
        |=> (Cuenta == ($past(Cuenta) + {{(N-1){1'b0}}, 1'b1}))
    );

    // Decrement wraps from zero to X.
    check_decrement_wraps_at_zero: assert property (
        @(posedge clk) disable iff (rst)
        ((en == 2'd1) && ((estado == 8'h6C) || (estado == 8'h75)) &&
         (Cambio == 8'h72) && got_data && (Cuenta == '0))
        |=> (Cuenta == X)
    );

    // Decrement decreases by one above zero.
    check_decrement_decreases_by_one: assert property (
        @(posedge clk) disable iff (rst)
        ((en == 2'd1) && ((estado == 8'h6C) || (estado == 8'h75)) &&
         (Cambio == 8'h72) && got_data && (Cuenta != '0))
        |=> (Cuenta == ($past(Cuenta) - {{(N-1){1'b0}}, 1'b1}))
    );

endmodule

