module AregLSBLog (AregSticky,
                   AregLSBSN,
                   AregLSBDB,
                   AregFPMSBP1,
                   SNnotDB,
                   TrueIEEEAregLSB,
                   StickyForSR1);
input [1:0] AregSticky; // Two LSBs of Areg
input [1:0] AregLSBSN;  // Two LSBs of Areg for IEEE single length
input [1:0] AregLSBDB;  // Two LSBs of Areg for IEEE double length
input AregFPMSBP1;      // Fraction overflow bit (ie 4.0 < Areg =< 2.0)
input SNnotDB;
output TrueIEEEAregLSB;
output StickyForSR1;

wire [1:0] selectedLSB;
assign selectedLSB = SNnotDB ? AregLSBSN : AregLSBDB;

// ME_OR2 stickyOR (AregSticky[1], AregSticky[0], StickyForSR1);

assign StickyForSR1 = AregSticky[1] || AregSticky[0];

assign TrueIEEEAregLSB = selectedLSB[0];

endmodule

sva:
module AregLSBLog_sva (
    input logic [1:0] AregSticky,
    input logic [1:0] AregLSBSN,
    input logic [1:0] AregLSBDB,
    input logic       AregFPMSBP1,
    input logic       SNnotDB,
    input logic       TrueIEEEAregLSB,
    input logic       StickyForSR1
);

    // StickyForSR1 is the OR of the two sticky bits.
    check_sticky_or: assert property (
        @($global_clock)
        StickyForSR1 == (AregSticky[1] || AregSticky[0])
    );

    // TrueIEEEAregLSB is the selected LSB based on SNnotDB.
    check_true_lsb_mux: assert property (
        @($global_clock)
        TrueIEEEAregLSB == (SNnotDB ? AregLSBSN[0] : AregLSBDB[0])
    );

    // In single-length mode, the single-length LSB drives the output.
    check_true_lsb_single_mode: assert property (
        @($global_clock)
        SNnotDB |-> (TrueIEEEAregLSB == AregLSBSN[0])
    );

    // In double-length mode, the double-length LSB drives the output.
    check_true_lsb_double_mode: assert property (
        @($global_clock)
        !SNnotDB |-> (TrueIEEEAregLSB == AregLSBDB[0])
    );

    // AregFPMSBP1 does not affect either output.
    check_fpmsbp1_has_no_effect: assert property (
        @($global_clock)
        !$initstate &&
        $changed(AregFPMSBP1) &&
        $stable({AregSticky, AregLSBSN, AregLSBDB, SNnotDB})
        |-> $stable({TrueIEEEAregLSB, StickyForSR1})
    );

endmodule

rtl:
module binary_operation_and_counter (
    input clk,
    input reset,
    input up_down,
    input load,
    input [3:0] load_data,
    input [2:0] a,
    input [2:0] b,
    output [2:0] out_and_bitwise,
    output out_and_logical,
    output [2:0] out_xor,
    output [5:0] out_not,
    output [3:0] q
);

    // Counter
    reg [3:0] count;
    wire [3:0] count_out;

    // Binary Operations
    wire [2:0] a_inv;
    wire [2:0] b_inv;
    wire [2:0] and_bitwise;
    wire and_logical;
    wire [2:0] xor_bitwise;

    // MUX
    wire [2:0] mux_out;

    // Inverter
    assign out_not = ~{a, b};

    // Counter
    always @(posedge clk or negedge reset) begin
        if (reset == 0) begin
            count <= 0;
        end else if (load == 1) begin
            count <= load_data;
        end else if (up_down == 1) begin
            count <= count + 1;
        end else begin
            count <= count - 1;
        end
    end

    // Binary Operations
    assign a_inv = ~a;
    assign b_inv = ~b;
    assign and_bitwise = a & b;
    assign and_logical = (a != 0) && (b != 0);
    assign xor_bitwise = a ^ b;

    // MUX
    assign mux_out = (count_out == 0) ? and_bitwise : count_out;

    // Outputs
    assign out_and_bitwise = and_bitwise;
    assign out_and_logical = and_logical;
    assign out_xor = xor_bitwise;
    assign q = count_out;

    // Counter Output
    assign count_out = count[3:0];

endmodule

sva:
module binary_operation_and_counter_sva (
    input logic clk,
    input logic reset,
    input logic up_down,
    input logic load,
    input logic [3:0] load_data,
    input logic [2:0] a,
    input logic [2:0] b,
    input logic [2:0] out_and_bitwise,
    input logic out_and_logical,
    input logic [2:0] out_xor,
    input logic [5:0] out_not,
    input logic [3:0] q
);

    // Reset drives the counter output to zero.
    check_reset_clears_q: assert property (
        @(posedge clk) !reset |-> (q == 4'd0)
    );

    // Load updates the counter on the next clock and overrides direction.
    check_load_updates_q: assert property (
        @(posedge clk) disable iff (!reset)
        load |=> (q == $past(load_data))
    );

    // When not loading, up_down high increments the counter.
    check_count_increment: assert property (
        @(posedge clk) disable iff (!reset)
        (!load && up_down) |=> (q == ($past(q) + 4'd1))
    );

    // When not loading, up_down low decrements the counter.
    check_count_decrement: assert property (
        @(posedge clk) disable iff (!reset)
        (!load && !up_down) |=> (q == ($past(q) - 4'd1))
    );

    // Bitwise AND output matches a & b.
    check_out_and_bitwise: assert property (
        @(posedge clk) disable iff (!reset)
        (out_and_bitwise == (a & b))
    );

    // Logical AND output is high only when both operands are non-zero.
    check_out_and_logical: assert property (
        @(posedge clk) disable iff (!reset)
        (out_and_logical == ((a != 3'd0) && (b != 3'd0)))
    );

    // XOR output matches a ^ b.
    check_out_xor: assert property (
        @(posedge clk) disable iff (!reset)
        (out_xor == (a ^ b))
    );

    // NOT output matches inversion of the concatenated operands.
    check_out_not: assert property (
        @(posedge clk) disable iff (!reset)
        (out_not == ~{a, b})
    );

