module sky130_fd_sc_lp__a41o_sva (
    input logic clk,
    input logic X,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic A4,
    input logic B1
);

    // X matches the OR of B1 and the 4-input A AND term.
    check_x_matches_function: assert property (
        @(posedge clk) disable iff (1'b0)
        X == (B1 || (A1 && A2 && A3 && A4))
