rtl:
module binary_adder_shift(
    input [3:0] A,
    input [3:0] B,
    input [1:0] SHIFT,
    output [3:0] S
);

    wire [4:0] sum;
    wire [3:0] shifted_sum;

    binary_adder adder(.A(A), .B(B), .S(sum));

    barrel_shifter shifter(.IN(sum[3:0]), .SHIFT(SHIFT), .OUT(shifted_sum));

    assign S = shifted_sum;

endmodule

module binary_adder(
    input [3:0] A,
    input [3:0] B,
    output [4:0] S
);

    assign S = A + B;

endmodule

module barrel_shifter(
    input [3:0] IN,
    input [1:0] SHIFT,
    output [3:0] OUT
);

    assign OUT = (SHIFT[1]) ? {IN[1:0], 2'b00} : (SHIFT[0]) ? {IN[2:0], 1'b0} : {1'b0, IN[3:1]};

endmodule

sva:
module binary_adder_shift_sva (
    input logic        clk,
    input logic [3:0]  A,
    input logic [3:0]  B,
    input logic [1:0]  SHIFT,
    input logic [3:0]  S
);

    // No clock or reset exists in the RTL; clk is only a sampling clock.
    // The design is purely combinational: add A and B, then shift the low 4 sum bits.

    // The top output matches the add-then-shift datapath.
    check_top_level_function: assert property (
        @(posedge clk)
        (S == (SHIFT[1] ? {({1'b0, A} + {1'b0, B})[1:0], 2'b00} :
              (SHIFT[0] ? {({1'b0, A} + {1'b0, B})[2:0], 1'b0} :
                          {1'b0, ({1'b0, A} + {1'b0, B})[3:1]})))
    );

    // SHIFT[1] selects the two-bit left-shift result.
    check_shift2_full_mapping: assert property (
        @(posedge clk)
        (SHIFT[1]) |-> (S == {({1'b0, A} + {1'b0, B})[1:0], 2'b00})
    );

    // SHIFT=01 selects the one-bit left-shift result.
    check_shift1_full_mapping: assert property (
        @(posedge clk)
        (!SHIFT[1] && SHIFT[0]) |-> (S == {({1'b0, A} + {1'b0, B})[2:0], 1'b0})
    );

    // SHIFT=00 selects the one-bit right-shift result.
    check_shift_right_full_mapping: assert property (
        @(posedge clk)
        (!SHIFT[1] && !SHIFT[0]) |-> (S == {1'b0, ({1'b0, A} + {1'b0, B})[3:1]})
    );

    // The two-bit left shift always zero-fills the low bits.
    check_shift2_zero_fill: assert property (
        @(posedge clk)
        (SHIFT[1]) |-> (S[1:0] == 2'b00)
    );

    // The one-bit left shift always zero-fills bit 0.
    check_shift1_zero_fill: assert property (
        @(posedge clk)
        (!SHIFT[1] && SHIFT[0]) |-> (S[0] == 1'b0)
    );

    // The right shift always zero-fills bit 3.
    check_shift_right_zero_fill: assert property (
        @(posedge clk)
        (!SHIFT[1] && !SHIFT[0]) |-> (S[3] == 1'b0)
    );

    // When both SHIFT bits are high, SHIFT[1] has priority.
    check_shift11_priority: assert property (
        @(posedge clk)
        (SHIFT == 2'b11) |-> (S == {({1'b0, A} + {1'b0, B})[1:0], 2'b00})
    );

endmodule

rtl:
module debounce_switch  #(
    parameter WIDTH=1, parameter N=3, parameter RATE=125000 )(
    input wire clk,
    input wire rst,
    input wire [WIDTH-1:0] in,
    output wire [WIDTH-1:0] out
);

reg [23:0] cnt_reg = 24'd0;

reg [N-1:0] debounce_reg[WIDTH-1:0];

reg [WIDTH-1:0] state;


assign out = state;

integer k;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        cnt_reg <= 0;
        state <= 0;

        for (k = 0; k < WIDTH; k = k + 1) begin
            debounce_reg[k] <= 0;
        end
    end else begin
        if (cnt_reg < RATE) begin
            cnt_reg <= cnt_reg + 24'd1;
        end else begin
            cnt_reg <= 24'd0;
        end

        if (cnt_reg == 24'd0) begin
            for (k = 0; k < WIDTH; k = k + 1) begin
                debounce_reg[k] <= {debounce_reg[k][N-2:0], in[k]};
            end
        end

        for (k = 0; k < WIDTH; k = k + 1) begin
            if (|debounce_reg[k] == 0) begin
                state[k] <= 0;
            end else if (&debounce_reg[k] == 1) begin
                state[k] <= 1;
            end else begin
                state[k] <= state[k];
            end
        end
    end
end

endmodule

sva:
module debounce_switch_sva #(
    parameter WIDTH = 1,
    parameter N = 3,
    parameter RATE = 125000
) (
    input logic clk,
    input logic rst,
    input logic [WIDTH-1:0] in,
    input logic [WIDTH-1:0] out,
    input logic [23:0] cnt_reg,
    input logic [N-1:0] debounce_reg [WIDTH-1:0],
    input logic [WIDTH-1:0] state
);

    // clk is the only clock; rst is an active-high asynchronous reset.
    // The logic is sequential with combinational out = state.

    // Reset forces the counter low.
    check_reset_clears_counter: assert property (
        @(posedge clk) rst |-> (cnt_reg == 24'd0)
    );

    // Reset forces the debounced state and output low.
    check_reset_clears_state_and_out: assert property (
        @(posedge clk) rst |-> (state == {WIDTH{1'b0}}) && (out == {WIDTH{1'b0}})
    );

    // Output always mirrors the internal state.
    check_out_matches_state: assert property (
        @(posedge clk) disable iff (rst) (out == state)
    );

    // Counter increments while below RATE.
    check_counter_increments_below_rate: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        ($past(!rst) && ($past(cnt_reg) < RATE)) |-> (cnt_reg == ($past(cnt_reg) + 24'd1))
    );

    // Counter wraps to zero when RATE is reached or exceeded.
    check_counter_wraps_at_rate: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        ($past(!rst) && !($past(cnt_reg) < RATE)) |-> (cnt_reg == 24'd0)
    );

    genvar i;
    generate
        for (i = 0; i < WIDTH; i = i + 1) begin : gen_bit_checks

            // Reset clears each debounce history register.
            check_reset_clears_debounce: assert property (
                @(posedge clk) rst |-> (debounce_reg[i] == {N{1'b0}})
            );

            // Debounce history holds when the sample counter is not zero.
            check_debounce_holds_without_sample: assert property (
                @(posedge clk) disable iff (rst || $initstate)
                ($past(!rst) && ($past(cnt_reg) != 24'd0)) |-> (debounce_reg[i] == $past(debounce_reg[i]))
            );

            if (N > 1) begin : gen_shift_multi
                // Debounce history shifts in the input when the sample counter is zero.
                check_debounce_shifts_on_sample: assert property (
                    @(posedge clk) disable iff (rst || $initstate)
                    ($past(!rst) && ($past(cnt_reg) == 24'd0)) |-> (debounce_reg[i] == { $past(debounce_reg[i][N-2:0]), $past(in[i]) })
                );
            end else begin : gen_shift_single
                // Single-bit debounce history captures the input when sampled.
                check_debounce_captures_on_sample: assert property (
                    @(posedge clk) disable iff (rst || $initstate)
                    ($past(!rst) && ($past(cnt_reg) == 24'd0)) |-> (debounce_reg[i] == $past(in[i]))
                );
            end

            // State clears when the previous debounce history is all zero.
            check_state_clears_on_all_zero_history: assert property (
                @(posedge clk) disable iff (rst || $initstate)
                ($past(!rst) && (~|$past(debounce_reg[i]))) |-> (state[i] == 1'b0)
            );

            // State sets when the previous debounce history is all one.
            check_state_sets_on_all_one_history: assert property (
                @(posedge clk) disable iff (rst || $initstate)
                ($past(!rst) && (&$past(debounce_reg[i]))) |-> (state[i] == 1'b1)
            );

            // State holds when the previous debounce history is mixed.
            check_state_holds_on_mixed_history: assert property (
                @(posedge clk) disable iff (rst || $initstate)
                ($past(!rst) && !(~|$past(debounce_reg[i])) && !(&$past(debounce_reg[i]))) |-> (state[i] == $past(state[i]))
            );

        end
    endgenerate

endmodule

