module sky130_fd_sc_lp__xnor3 (
    X,
    A,
    B,
    C
);

    output X;
    input  A;
    input  B;
    input  C;

    wire xnor0_out_X;

    xnor xnor0 (xnor0_out_X, A, B, C        );
    buf  buf0  (X          , xnor0_out_X    );

endmodule

sva:
module sky130_fd_sc_lp__xnor3_sva (
    input logic clk,
    input logic X,
    input logic A,
    input logic B,
    input logic C
);

    // X matches the 3-input XNOR of A, B, and C.
    check_xnor3_function: assert property (
        @(posedge clk) X === ~(A ^ B ^ C)
    );

    // With C low, X reduces to the XNOR of A and B.
    check_c_low_reduces_to_ab_xnor: assert property (
        @(posedge clk) (C == 1'b0) |-> (X === ~(A ^ B))
    );

    // With C high, X reduces to the XOR of A and B.
    check_c_high_reduces_to_ab_xor: assert property (
        @(posedge clk) (C == 1'b1) |-> (X === (A ^ B))
    );

    // When A and B are equal, X is the inversion of C.
    check_ab_equal_inverts_c: assert property (
        @(posedge clk) (A == B) |-> (X === ~C)
    );

    // When A and B differ, X follows C.
    check_ab_different_follows_c: assert property (
        @(posedge clk) (A != B) |-> (X === C)
    );

    // When B and C are equal, X is the inversion of A.
    check_bc_equal_inverts_a: assert property (
        @(posedge clk) (B == C) |-> (X === ~A)
    );

    // When B and C differ, X follows A.
    check_bc_different_follows_a: assert property (
        @(posedge clk) (B != C) |-> (X === A)
    );

    // When A and C are equal, X is the inversion of B.
    check_ac_equal_inverts_b: assert property (
        @(posedge clk) (A == C) |-> (X === ~B)
    );

    // When A and C differ, X follows B.
    check_ac_different_follows_b: assert property (
        @(posedge clk) (A != C) |-> (X === B)
    );

    // All-zero inputs must produce a high output.
    check_all_zero_case: assert property (
        @(posedge clk) (A == 1'b0 && B == 1'b0 && C == 1'b0) |-> (X === 1'b1)
    );

    // All-one inputs must produce a low output.
    check_all_one_case: assert property (
        @(posedge clk) (A == 1'b1 && B == 1'b1 && C == 1'b1) |-> (X === 1'b0)
    );

endmodule

rtl:
module syncflop(
                DEST_CLK,
		D_SET,
		D_RST,
		RESET,
                TOGGLE_IN,
                D_OUT
		);


   input   DEST_CLK;
   input   D_SET;
   input   D_RST;
   input   RESET;
   input   TOGGLE_IN;
   output  D_OUT;

   reg 	   sync1;
   reg 	   sync2;
   reg 	   syncprev;
   reg 	   srflop;

   wire    syncxor;
   wire    srinput;
   wire    D_OUT;

   assign  syncxor = sync2 ^ syncprev;
   assign  srinput = syncxor | D_SET;  
   assign  D_OUT = srflop | syncxor;

   always @ (posedge DEST_CLK or posedge RESET)
     begin
	if(RESET) sync1 <= 1'b0;
	else sync1 <= TOGGLE_IN;
     end


   always @ (posedge DEST_CLK or posedge RESET)
     begin
	if(RESET) sync2 <= 1'b0;
	else sync2 <= sync1;
     end


   always @ (posedge DEST_CLK or posedge RESET)
     begin
	if(RESET) syncprev <= 1'b0;
	else syncprev <= sync2;
     end


   always @ (posedge DEST_CLK or posedge RESET)
     begin
	if(RESET)         srflop <= 1'b0;
	else if(D_RST)    srflop <= 1'b0;
	else if (srinput) srflop <= 1'b1;
     end


endmodule

sva:
module syncflop_sva (
    input logic DEST_CLK,
    input logic D_SET,
    input logic D_RST,
    input logic RESET,
    input logic TOGGLE_IN,
    input logic D_OUT,
    input logic sync1,
    input logic sync2,
    input logic syncprev,
    input logic srflop,
    input logic syncxor,
    input logic srinput
);

    // syncxor is the XOR of the last two synchronizer stages.
    check_syncxor_definition: assert property (
        @(posedge DEST_CLK) disable iff (RESET)
        syncxor == (sync2 ^ syncprev)
    );

    // srinput is asserted by either D_SET or a syncxor pulse.
    check_srinput_definition: assert property (
        @(posedge DEST_CLK) disable iff (RESET)
        srinput == (syncxor | D_SET)
    );

    // D_OUT is the OR of srflop and syncxor.
    check_d_out_definition: assert property (
        @(posedge DEST_CLK) disable iff (RESET)
        D_OUT == (srflop | syncxor)
    );

    // A sampled reset leaves all sequential state cleared on the next clock sample.
    check_reset_release_clears_state: assert property (
        @(posedge DEST_CLK) disable iff (RESET)
        (!$initstate && $past(RESET)) |-> (!sync1 && !sync2 && !syncprev && !srflop)
    );

    // A sampled reset also leaves the pulse path and output low on the next clock sample.
    check_reset_release_clears_output: assert property (
        @(posedge DEST_CLK) disable iff (RESET)
        (!$initstate && $past(RESET)) |-> (!syncxor && !D_OUT)
    );

    // D_RST clears srflop by the next clock sample.
    check_d_rst_clears_srflop: assert property (
        @(posedge DEST_CLK) disable iff (RESET)
        D_RST |=> !srflop
    );

    // After D_RST, the output can only reflect the current syncxor pulse.
    check_d_rst_removes_latched_output: assert property (
        @(posedge DEST_CLK) disable iff (RESET)
        D_RST |=> (D_OUT == syncxor)
    );

endmodule

