module mux_counter (
    input clk,
    input [7:0] data_in1,
    input [7:0] data_in2,
    input select,
    input reset,
    output reg [7:0] sum_out
);

reg [3:0] count;
reg [7:0] output1;
reg [7:0] output2;

always @(posedge clk) begin
    if (reset) begin
        count <= 4'b0;
        output1 <= 8'b0;
        output2 <= 8'b0;
    end else begin
        count <= count + 1;
        output1 <= data_in1;
        output2 <= data_in2;
    end
end

always @(*) begin
    if (select) begin
        sum_out = output2 + (count * 2);
    end else begin
        sum_out = output1 + (count * 2);
    end
end

endmodule

sva:
module mux_counter_sva (
    input logic        clk,
    input logic [7:0]  data_in1,
    input logic [7:0]  data_in2,
    input logic        select,
    input logic        reset,
    input logic [7:0]  sum_out,
    input logic [3:0]  count,
    input logic [7:0]  output1,
    input logic [7:0]  output2
);

    // State registers are cleared after a reset cycle.
    check_state_clears_after_reset: assert property (
        @(posedge clk) disable iff (reset)
        (!$initstate && $past(reset)) |-> (count == 4'b0000 && output1 == 8'b00000000 && output2 == 8'b00000000)
    );

    // sum_out is zero once the cleared state from reset is visible.
    check_sum_clears_after_reset: assert property (
        @(posedge clk) disable iff (reset)
        (!$initstate && $past(reset)) |-> (sum_out == 8'b00000000)
    );

    // count increments by one on each non-reset cycle.
    check_count_increments: assert property (
        @(posedge clk) disable iff (reset)
        (!$initstate && !$past(reset)) |-> (count == ($past(count) + 4'b0001))
    );

    // output1 captures data_in1 on each non-reset cycle.
    check_output1_captures_data_in1: assert property (
        @(posedge clk) disable iff (reset)
        (!$initstate && !$past(reset)) |-> (output1 == $past(data_in1))
    );

    // output2 captures data_in2 on each non-reset cycle.
    check_output2_captures_data_in2: assert property (
        @(posedge clk) disable iff (reset)
        (!$initstate && !$past(reset)) |-> (output2 == $past(data_in2))
    );

    // When select is low, sum_out uses output1 plus twice count.
    check_sum_uses_output1_when_select_low: assert property (
        @(posedge clk) disable iff (reset)
        (select == 1'b0) |-> (sum_out == (output1 + {count, 1'b0}))
    );

    // When select is high, sum_out uses output2 plus twice count.
    check_sum_uses_output2_when_select_high: assert property (
        @(posedge clk) disable iff (reset)
        (select == 1'b1) |-> (sum_out == (output2 + {count, 1'b0}))
    );

endmodule

rtl:
module selector_module(
    input [1:0] SEL,
    input [7:0] A,
    input [7:0] B,
    output reg [7:0] OUT
);

    wire [7:0] sum, diff, prod, quo;

    assign sum = A + B;
    assign diff = A - B;
    assign prod = A * B;
    assign quo = A / B;

    always @* begin
        case (SEL)
            2'b00: OUT = sum;
            2'b01: OUT = diff;
            2'b10: OUT = prod;
            2'b11: OUT = quo;
        endcase
    end

endmodule

sva:
module selector_module_sva (
    input logic       clk,
    input logic [1:0] SEL,
    input logic [7:0] A,
    input logic [7:0] B,
    input logic [7:0] OUT
);

    wire [7:0] sum;
    wire [7:0] diff;
    wire [7:0] prod;
    wire [7:0] quo;

    assign sum  = A + B;
    assign diff = A - B;
    assign prod = A * B;
    assign quo  = A / B;

    // SEL=00 selects the sum result.
    check_select_sum: assert property (
        @(posedge clk) (SEL == 2'b00) |-> (OUT === sum)
    );

    // SEL=01 selects the difference result.
    check_select_diff: assert property (
        @(posedge clk) (SEL == 2'b01) |-> (OUT === diff)
    );

    // SEL=10 selects the product result.
    check_select_prod: assert property (
        @(posedge clk) (SEL == 2'b10) |-> (OUT === prod)
    );

    // SEL=11 selects the quotient result.
    check_select_quo: assert property (
        @(posedge clk) (SEL == 2'b11) |-> (OUT === quo)
    );

    // Stable inputs imply a stable sampled output.
    check_output_stable_when_inputs_stable: assert property (
        @(posedge clk) $stable({SEL, A, B}) |-> $stable(OUT)
    );

endmodule

rtl:
module top_module (
    input [7:0] A,
    input [7:0] B,
    input enable,
    output EQ,
    output GT,
    output OR
);

    wire [7:0] mux_output;
    wire EQ_int;
    wire GT_int;

    // 2-to-1 Multiplexer module
    mux_2to1 mux_inst (
        .in0(A),
        .in1(B),
        .sel(enable),
        .out(mux_output)
    );

    // 8-bit Comparator module
    comp_8bit comp_inst (
        .A(mux_output),
        .B(B),
        .EQ(EQ_int),
        .GT(GT_int)
    );

    // OR gate
    assign OR = EQ_int | GT_int;

    assign EQ = EQ_int;
    assign GT = GT_int;

endmodule

module mux_2to1 (
    input [7:0] in0,
    input [7:0] in1,
    input sel,
    output reg [7:0] out
);

    always @(*) begin
        if(sel == 0)
            out = in0;
        else
            out = in1;
    end
endmodule

module comp_8bit (
    input [7:0] A,
    input [7:0] B,
    output EQ,
    output GT
);

    assign EQ = (A == B);
    assign GT = (A > B);

endmodule

sva:
module top_module_assertions (
    input logic clk,
    input logic [7:0] A,
    input logic [7:0] B,
    input logic enable,
    input logic EQ,
    input logic GT,
    input logic OR
);

    // No reset in RTL; sample combinational behavior on clk.

    // EQ matches the selected input compared against B.
    check_eq_function: assert property (
        @(posedge clk) EQ == (enable ? 1'b1 : (A == B))
    );

    // GT matches the selected input compared against B.
    check_gt_function: assert property (
        @(posedge clk) GT == (enable ? 1'b0 : (A > B))
    );

    // OR is the OR of the comparator outputs.
    check_or_combination: assert property (
        @(posedge clk) OR == (EQ | GT)
    );

    // EQ and GT cannot both be high at the same time.
    check_compare_mutex: assert property (
        @(posedge clk) !(EQ && GT)
    );

    // When enable is high, the mux selects B so the compare is B vs B.
    check_enable_selects_b: assert property (
        @(posedge clk) enable |-> (EQ && !GT && OR)
    );

    // When enable is low and A is less than B, all compare outputs are low.
    check_disable_less_than_case: assert property (
        @(posedge clk) (!enable && (A < B)) |-> (!EQ && !GT && !OR)
    );

    // When enable is low and A equals B, EQ and OR are high and GT is low.
    check_disable_equal_case: assert property (
        @(posedge clk) (!enable && (A == B)) |-> (EQ && !GT && OR)
    );

    // When enable is low and A is greater than B, GT and OR are high and EQ is low.
    check_disable_greater_than_case: assert property (
        @(posedge clk) (!enable && (A > B)) |-> (!EQ && GT && OR)
    );

endmodule

rtl:
module rotator(
    input clk,
    input load,
    input [1:0] ena,
    input [99:0] data,
    output [99:0] q);

    reg [99:0] shift_reg;
    reg [5:0] shift_amt;

    always @(posedge clk) begin
        if(load) begin
            shift_reg <= data;
            shift_amt <= 0;
        end else begin
            if(ena == 2'b00) begin
                shift_reg <= shift_reg;
                shift_amt <= shift_amt;
            end else if(ena == 2'b01) begin
                shift_reg <= {shift_reg[98:0], shift_reg[99]};
                shift_amt <= shift_amt + 1;
            end else if(ena == 2'b10) begin
                shift_reg <= {shift_reg[0], shift_reg[99:1]};
                shift_amt <= shift_amt - 1;
            end
        end
    end

    assign q = shift_reg;

endmodule

sva:
module rotator_sva (
    input logic clk,
    input logic load,
    input logic [1:0] ena,
    input logic [99:0] data,
    input logic [99:0] q
);

    // Load captures data into q on the next cycle.
    check_load_captures_data: assert property (
        @(posedge clk) load |=> (q == $past(data))
    );

    // With ena=00 and no load, q holds its previous value.
    check_hold_when_ena_zero: assert property (
        @(posedge clk) (!load && (ena == 2'b00)) |=> (q == $past(q))
    );

    // With ena=01 and no load, q rotates left by one bit.
    check_rotate_left: assert property (
        @(posedge clk) (!load && (ena == 2'b01)) |=> (q == { $past(q[98:0]), $past(q[99]) })
    );

    // With ena=10 and no load, q rotates right by one bit.
    check_rotate_right: assert property (
        @(posedge clk) (!load && (ena == 2'b10)) |=> (q == { $past(q[0]), $past(q[99:1]) })
    );

    // With ena=11 and no load, q holds because no assignment occurs.
    check_hold_when_ena_three: assert property (
        @(posedge clk) (!load && (ena == 2'b11)) |=> (q == $past(q))
    );

    // A left rotation followed by a right rotation restores q.
    check_left_then_right_restore: assert property (
        @(posedge clk) (!load && (ena == 2'b01)) ##1 (!load && (ena == 2'b10)) |=> (q == $past(q,2))
    );

    // A right rotation followed by a left rotation restores q.
    check_right_then_left_restore: assert property (
        @(posedge clk) (!load && (ena == 2'b10)) ##1 (!load && (ena == 2'b01)) |=> (q == $past(q,2))
    );

endmodule

rtl:
module clock_gate_d_ff_en (
  input CLK, EN, TE,
  output reg ENCLK
);

  reg gated_clk;

  always @ (posedge CLK)
  begin
    if (TE)
      gated_clk <= EN;
  end

  always @*
  begin
    if (EN == 1'b0)
      ENCLK <= 1'b0;
    else
      ENCLK <= gated_clk;
  end

endmodule

sva:
module clock_gate_d_ff_en_sva (
    input logic CLK,
    input logic EN,
    input logic TE,
    input logic ENCLK
);

    // EN low forces ENCLK low.
    check_en_low_forces_enclk_low: assert property (
        @(posedge CLK) !EN |-> !ENCLK
    );

    // ENCLK can only be high when EN is high.
    check_enclk_high_requires_en: assert property (
        @(posedge CLK) ENCLK |-> EN
    );

    // When TE is high, the next-cycle ENCLK reflects the captured EN value.
    check_capture_when_te: assert property (
        @(posedge CLK) TE |=> (ENCLK == (EN ? $past(EN) : 1'b0))
    );

    // With EN high and TE low, ENCLK holds if EN stays high.
    check_hold_when_te_low_and_enabled: assert property (
        @(posedge CLK) (EN && !TE) |=> (!EN || (ENCLK == $past(ENCLK)))
    );

endmodule

