module adder(
    input [3:0] A,
    input [3:0] B,
    output reg [3:0] S,
    output reg C
);

always @* begin
    {C, S} = A + B;
end

endmodule

sva:
module adder_assertions (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] S,
    input logic C
);

    // Carry and sum must match the 5-bit addition of A and B.
    check_add_result: assert property (
        @($global_clock) {C, S} == ({1'b0, A} + {1'b0, B})
    );

    // Carry must indicate overflow beyond 4 bits.
    check_carry_overflow: assert property (
        @($global_clock) C == (({1'b0, A} + {1'b0, B}) > 5'd15)
    );

    // Adding zero on A must pass B through with no carry.
    check_zero_a_identity: assert property (
        @($global_clock) (A == 4'h0) |-> (S == B && C == 1'b0)
    );

    // Adding zero on B must pass A through with no carry.
    check_zero_b_identity: assert property (
        @($global_clock) (B == 4'h0) |-> (S == A && C == 1'b0)
    );

    // Maximum operands must produce the expected overflowed result.
    check_max_operands: assert property (
        @($global_clock) (A == 4'hF && B == 4'hF) |-> (C == 1'b1 && S == 4'hE)
    );

    // If inputs do not change, outputs must also remain unchanged.
    check_stable_inputs_hold_outputs: assert property (
        @($global_clock) ($stable(A) && $stable(B)) |-> ($stable(S) && $stable(C))
    );

    // Any observed output change must be caused by an input change.
    check_output_change_requires_input_change: assert property (
        @($global_clock) ($changed(S) || $changed(C)) |-> ($changed(A) || $changed(B))
    );

endmodule

rtl:
module comparator_4bit (
  input [3:0] a,
  input [3:0] b,
  output reg [1:0] res
);

  always @(*) begin
    if (a > b) begin
      res = 2'b01;
    end else if (a < b) begin
      res = 2'b10;
    end else begin
      res = 2'b11;
    end
  end

endmodule

sva:
module comparator_4bit_sva (
    input logic clk,
    input logic [3:0] a,
    input logic [3:0] b,
    input logic [1:0] res
);

    // Result matches the full comparator function.
    check_complete_result_mapping: assert property (
        @(posedge clk) res == ((a > b) ? 2'b01 : ((a < b) ? 2'b10 : 2'b11))
    );

    // Greater-than case produces 01.
    check_gt_result_encoding: assert property (
        @(posedge clk) (a > b) |-> (res == 2'b01)
    );

    // Less-than case produces 10.
    check_lt_result_encoding: assert property (
        @(posedge clk) (a < b) |-> (res == 2'b10)
    );

    // Equality case produces 11.
    check_eq_result_encoding: assert property (
        @(posedge clk) (a == b) |-> (res == 2'b11)
    );

    // Result 01 only occurs when a is greater than b.
    check_result_01_implies_gt: assert property (
        @(posedge clk) (res == 2'b01) |-> (a > b)
    );

    // Result 10 only occurs when a is less than b.
    check_result_10_implies_lt: assert property (
        @(posedge clk) (res == 2'b10) |-> (a < b)
    );

    // Result 11 only occurs when a equals b.
    check_result_11_implies_eq: assert property (
        @(posedge clk) (res == 2'b11) |-> (a == b)
    );

    // The RTL never drives the unused 00 encoding.
    check_result_never_zero: assert property (
        @(posedge clk) res != 2'b00
    );

endmodule

