    // sel=010 routes data2[3:1] to the outputs.
    check_sel_010_routes_data2: assert property (
        @($global_clock) (sel == 3'b010) |-> ({o2, o1, o0} == data2[3:1])
    );

    // sel=011 routes data3[3:1] to the outputs.
    check_sel_011_routes_data3: assert property (
        @($global_clock) (sel == 3'b011) |-> ({o2, o1, o0} == data3[3:1])
    );

    // sel=100 routes data4[3:1] to the outputs.
    check_sel_100_routes_data4: assert property (
        @($global_clock) (sel == 3'b100) |-> ({o2, o1, o0} == data4[3:1])
    );

    // sel=101 routes data5[3:1] to the outputs.
    check_sel_101_routes_data5: assert property (
        @($global_clock) (sel == 3'b101) |-> ({o2, o1, o0} == data5[3:1])
    );

    // Unhandled sel values fall back to data0[3:1].
    check_default_routes_data0: assert property (
        @($global_clock) ((sel == 3'b110) || (sel == 3'b111)) |-> ({o2, o1, o0} == data0[3:1])
    );

endmodule

rtl:
module oh_edgealign (
   firstedge,
   fastclk, slowclk
   );

   input  fastclk;
   input  slowclk;
   output firstedge;

   reg 	  clk45;
   reg 	  clk90;
   reg 	  firstedge;

   always @ (negedge fastclk) 
     clk45     <= slowclk;

   always @ (posedge fastclk) 
     begin
	clk90     <= clk45;
	firstedge <= ~clk45 & clk90;
     end

endmodule

sva:
module oh_edgealign_sva (
    input logic fastclk,
    input logic slowclk,
    input logic firstedge,
    input logic clk45,
    input logic clk90
);

    // clk45 captures slowclk on each fastclk falling edge.
    check_clk45_captures_slowclk: assert property (
        @(negedge fastclk) 1'b1 |=> (clk45 == $past(slowclk))
    );

    // clk90 captures clk45 on each fastclk rising edge.
    check_clk90_captures_clk45: assert property (
        @(posedge fastclk) 1'b1 |=> (clk90 == $past(clk45))
    );

    // firstedge captures the ~clk45 & clk90 detect term on each fastclk rising edge.
    check_firstedge_captures_detect_term: assert property (
        @(posedge fastclk) 1'b1 |=> (firstedge == ((!$past(clk45)) && $past(clk90)))
    );

    // A sampled clk45=0 and clk90=1 condition must assert firstedge.
    check_firstedge_assert_condition: assert property (
        @(posedge fastclk) ((!clk45) && clk90) |=> (firstedge == 1'b1)
    );

    // All other sampled clk45/clk90 combinations must clear firstedge.
    check_firstedge_clear_condition: assert property (
        @(posedge fastclk) (clk45 || (!clk90)) |=> (firstedge == 1'b0)
    );

endmodule

rtl:
module top_module( 
    input wire [15:0] in,
    output wire [3:0] in1_hi, in1_lo,
    output wire [3:0] in2_hi, in2_lo,
    output wire [7:0] out );

  wire [7:0] in1, in2;

  // Split the 16-bit input into two 8-bit outputs
  assign in1 = in[15:8];
  assign in2 = in[7:0];

  // Split each 8-bit input into two 4-bit inputs
  assign in1_hi = in1[7:4];
  assign in1_lo = in1[3:0];
  assign in2_hi = in2[7:4];
  assign in2_lo = in2[3:0];

  // Compute the absolute difference between each pair of corresponding 4-bit inputs
  wire [3:0] abs_diff_hi, abs_diff_lo;
  assign abs_diff_hi = (in1_hi >= in2_hi) ? (in1_hi - in2_hi) : (in2_hi - in1_hi);
  assign abs_diff_lo = (in1_lo >= in2_lo) ? (in1_lo - in2_lo) : (in2_lo - in1_lo);

  // Output the sum of the absolute differences
  assign out = abs_diff_hi + abs_diff_lo;

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic [15:0] in,
    input logic [3:0] in1_hi,
    input logic [3:0] in1_lo,
    input logic [3:0] in2_hi,
    input logic [3:0] in2_lo,
    input logic [7:0] out
);

    // in1_hi is the upper nibble of the upper input byte.
    check_in1_hi_slice: assert property (
        @(posedge clk) in1_hi == in[15:12]
    );

    // in1_lo is the lower nibble of the upper input byte.
    check_in1_lo_slice: assert property (
        @(posedge clk) in1_lo == in[11:8]
    );

    // in2_hi is the upper nibble of the lower input byte.
    check_in2_hi_slice: assert property (
        @(posedge clk) in2_hi == in[7:4]
    );

    // in2_lo is the lower nibble of the lower input byte.
    check_in2_lo_slice: assert property (
        @(posedge clk) in2_lo == in[3:0]
    );

    // out upper nibble is always zero from zero-extension of the 4-bit sum.
    check_out_upper_nibble_zero: assert property (
        @(posedge clk) out[7:4] == 4'h0
    );

    // out lower nibble is the truncated sum of the two absolute nibble differences.
    check_out_lower_nibble_absdiff_sum: assert property (
        @(posedge clk)
        out[3:0] ==
            (((in[15:12] >= in[7:4]) ? (in[15:12] - in[7:4]) : (in[7:4] - in[15:12])) +
             ((in[11:8]  >= in[3:0]) ? (in[11:8]  - in[3:0]) : (in[3:0]  - in[11:8])))
    );

    // Equal upper and lower bytes produce a zero output.
    check_equal_bytes_zero_out: assert property (
        @(posedge clk) (in[15:8] == in[7:0]) |-> (out == 8'h00)
    );

    // If the high nibbles match, only the low-nibble absolute difference remains.
    check_equal_high_nibbles_reduce_to_low_diff: assert property (
        @(posedge clk)
        (in[15:12] == in[7:4]) |->
            (out[3:0] == ((in[11:8] >= in[3:0]) ? (in[11:8] - in[3:0]) : (in[3:0] - in[11:8])))
    );

    // If the low nibbles match, only the high-nibble absolute difference remains.
    check_equal_low_nibbles_reduce_to_high_diff: assert property (
        @(posedge clk)
        (in[11:8] == in[3:0]) |->
            (out[3:0] == ((in[15:12] >= in[7:4]) ? (in[15:12] - in[7:4]) : (in[7:4] - in[15:12])))
    );

endmodule

module barrel_shifter_sva (
    input logic clk,
    input logic [7:0] in,
    input logic [2:0] shift_amt,
    input logic [7:0] out
);

    // External sampling clock; RTL itself is combinational and has no reset.

    // shift_amt 000 passes input through unchanged.
    check_no_shift: assert property (
        @(posedge clk) (shift_amt == 3'b000) |-> (out == in)
    );

    // shift_amt 001 shifts left by 1 and fills LSB with 0.
    check_shift_left_1: assert property (
        @(posedge clk) (shift_amt == 3'b001) |-> (out == {in[6:0], 1'b0})
    );

    // shift_amt 010 shifts left by 2 and fills low bits with 0.
    check_shift_left_2: assert property (
        @(posedge clk) (shift_amt == 3'b010) |-> (out == {in[5:0], 2'b00})
    );

    // shift_amt 011 shifts left by 3 and fills low bits with 0.
    check_shift_left_3: assert property (
        @(posedge clk) (shift_amt == 3'b011) |-> (out == {in[4:0], 3'b000})
    );

    // shift_amt 100 shifts left by 4 and fills low bits with 0.
    check_shift_left_4: assert property (
        @(posedge clk) (shift_amt == 3'b100) |-> (out == {in[3:0], 4'b0000})
    );

    // shift_amt 101 shifts right by 1 and fills MSB with 0.
    check_shift_right_1: assert property (
        @(posedge clk) (shift_amt == 3'b101) |-> (out == {1'b0, in[7:1]})
    );

    // shift_amt 110 shifts right by 2 and fills high bits with 0.
    check_shift_right_2: assert property (
        @(posedge clk) (shift_amt == 3'b110) |-> (out == {2'b00, in[7:2]})
    );

    // shift_amt 111 shifts right by 3 and fills high bits with 0.
    check_shift_right_3: assert property (
        @(posedge clk) (shift_amt == 3'b111) |-> (out == {3'b000, in[7:3]})
    );

endmodule

rtl:
module LCD_Driver (
  input clk,
  input [7:0] data,
  input RS,
  input RW,
  input E,
  output LCD_RS,
  output LCD_RW,
  output LCD_E,
  output [7:0] LCD_DATA
);

parameter width = 16; // width of the LCD screen
parameter height = 2; // height of the LCD screen

reg [7:0] lcd_data_reg;
reg lcd_rs_reg;
reg lcd_rw_reg;
reg lcd_e_reg;

assign LCD_DATA = lcd_data_reg;
assign LCD_RS = lcd_rs_reg;
assign LCD_RW = lcd_rw_reg;
assign LCD_E = lcd_e_reg;

always @(posedge clk) begin
  lcd_data_reg <= data;
  lcd_rs_reg <= RS;
  lcd_rw_reg <= RW;
  lcd_e_reg <= E;
end

endmodule

sva:
module LCD_Driver_sva (
    input logic clk,
    input logic [7:0] data,
    input logic RS,
    input logic RW,
    input logic E,
    input logic LCD_RS,
    input logic LCD_RW,
    input logic LCD_E,
    input logic [7:0] LCD_DATA
);

    // All LCD outputs are the prior cycle's sampled inputs.
    check_registered_outputs: assert property (
        @(posedge clk) disable iff ($initstate)
        {LCD_RS, LCD_RW, LCD_E, LCD_DATA} == $past({RS, RW, E, data})
    );

    // LCD_DATA captures data on each rising clock edge.
    check_data_capture: assert property (
        @(posedge clk) disable iff ($initstate)
        LCD_DATA == $past(data)
    );

    // LCD_RS captures RS on each rising clock edge.
    check_rs_capture: assert property (
        @(posedge clk) disable iff ($initstate)
        LCD_RS == $past(RS)
    );

    // LCD_RW captures RW on each rising clock edge.
    check_rw_capture: assert property (
        @(posedge clk) disable iff ($initstate)
        LCD_RW == $past(RW)
    );

    // LCD_E captures E on each rising clock edge.
    check_e_capture: assert property (
        @(posedge clk) disable iff ($initstate)
        LCD_E == $past(E)
    );

endmodule

module pcie_7x_0_core_top_gtx_cpllpd_ovrd_sva (
    input logic i_ibufds_gte2,
    input logic o_cpllpd_ovrd,
    input logic o_cpllreset_ovrd
);

    // Initial values reflect the register initializations.
    check_initial_outputs: assert property (
        @(posedge i_ibufds_gte2)
        $initstate |-> (o_cpllpd_ovrd && !o_cpllreset_ovrd)
    );

    // The CPLL powerdown override stays high for 96 clocks, then deasserts.
    check_cpllpd_init_duration: assert property (
        @(posedge i_ibufds_gte2)
        $initstate |-> (o_cpllpd_ovrd)[*96] ##1 (!o_cpllpd_ovrd)
    );

    // Once the CPLL powerdown override goes low, it stays low.
    check_cpllpd_stays_low: assert property (
        @(posedge i_ibufds_gte2)
        !o_cpllpd_ovrd |=> !o_cpllpd_ovrd
    );

    // The CPLL reset override stays low for 120 clocks, pulses high for 8 clocks, then goes low.
    check_cpllreset_init_pulse: assert property (
        @(posedge i_ibufds_gte2)
        $initstate |-> (!o_cpllreset_ovrd)[*120] ##1 (o_cpllreset_ovrd)[*8] ##1 (!o_cpllreset_ovrd)
    );

    // The reset override rises 24 clocks after the powerdown override falls.
    check_cpllreset_delay_after_cpllpd_fall: assert property (
        @(posedge i_ibufds_gte2)
        (!$initstate && $fell(o_cpllpd_ovrd)) |-> (!o_cpllreset_ovrd)[*24] ##1 $rose(o_cpllreset_ovrd)
    );

    // Once the reset override rises, it remains high for 8 total clocks and then deasserts.
    check_cpllreset_pulse_width: assert property (
        @(posedge i_ibufds_gte2)
        (!$initstate && $rose(o_cpllreset_ovrd)) |=> (o_cpllreset_ovrd)[*7] ##1 (!o_cpllreset_ovrd)
    );

    // The two override outputs are never high at the same time.
    check_outputs_do_not_overlap: assert property (
        @(posedge i_ibufds_gte2)
        !(o_cpllpd_ovrd && o_cpllreset_ovrd)
    );

endmodule

rtl:
module three_input_module (
    X ,
    A1,
    A2,
    B1
);

    output X ;
    input  A1;
    input  A2;
    input  B1;

    wire C1;
    wire C2;

    assign C1 = (A1 & A2) ? ~B1 : (A1 | A2);
    assign C2 = (A1 & A2) ? C1 : B1;
    assign X = (A1 & A2) ? C2 : (A1 & ~A2) ? ~B1 : (A1 | A2) ? B1 : 0;

endmodule

sva:
module three_input_module_sva (
    input logic clk,
    input logic X,
    input logic A1,
    input logic A2,
    input logic B1
);

    // X matches the implemented combinational function.
    check_x_matches_function: assert property (
        @(posedge clk)
        X == (A1 ? (~B1) : (A2 ? B1 : 1'b0))
    );

    // When A1 is high, X inverts B1.
    check_x_inverts_b1_when_a1_high: assert property (
        @(posedge clk)
        A1 |-> (X == (~B1))
    );

    // When A1 is low, X reduces to A2 AND B1.
    check_x_is_a2_and_b1_when_a1_low: assert property (
        @(posedge clk)
        (!A1) |-> (X == (A2 & B1))
    );

    // When A2 is low, X reduces to A1 AND not B1.
    check_x_is_a1_and_not_b1_when_a2_low: assert property (
        @(posedge clk)
        (!A2) |-> (X == (A1 & (~B1)))
    );

    // When only A2 is high, X equals B1.
    check_x_follows_b1_when_only_a2_high: assert property (
        @(posedge clk)
        (!A1 && A2) |-> (X == B1)
    );

    // When A1 and A2 are both low, X is low.
    check_x_low_when_a1_a2_low: assert property (
        @(posedge clk)
        (!A1 && !A2) |-> (X == 1'b0)
    );

    // When A1 is low and B1 is high, X equals A2.
    check_x_follows_a2_when_a1_low_b1_high: assert property (
        @(posedge clk)
        (!A1 && B1) |-> (X == A2)
    );

endmodule

rtl:
module dffsre(
    output reg Q,
    input D,
    input C,
    input E,
    input R,
    input S
);
    parameter [0:0] INIT = 1'b0;
    initial Q = INIT;
    always @(posedge C) begin
        if (E) begin
            if (S)
                Q <= 1'b1;
            else if (R)
                Q <= 1'b0;
            else
                Q <= D;
        end
    end
endmodule

sva:
module dffsre_sva (
    input logic Q,
    input logic D,
    input logic C,
    input logic E,
    input logic R,
    input logic S
);

    // Q holds its value when enable is low.
    check_hold_when_disabled: assert property (
        @(posedge C) (!E) |=> (Q == $past(Q))
    );

    // Q is set high when enabled with set asserted and reset deasserted.
    check_set_when_enabled: assert property (
        @(posedge C) (E && S && !R) |=> (Q == 1'b1)
    );

    // Q is cleared when enabled with reset asserted and set deasserted.
    check_reset_when_enabled: assert property (
        @(posedge C) (E && !S && R) |=> (Q == 1'b0)
    );

    // Q captures D when enabled with neither set nor reset asserted.
    check_data_capture_when_enabled: assert property (
        @(posedge C) (E && !S && !R) |=> (Q == $past(D))
    );

    // Set has priority over reset when both are asserted with enable.
    check_set_priority_over_reset: assert property (
        @(posedge C) (E && S && R) |=> (Q == 1'b1)
    );

endmodule

rtl:
module sky130_fd_sc_hdll__a32oi (
    Y ,
    A1,
    A2,
    A3,
    B1,
    B2
);

    output Y ;
    input  A1;
    input  A2;
    input  A3;
    input  B1;
    input  B2;

    wire nand0_out ;
    wire nand1_out ;
    wire and0_out_Y;

    nand nand0 (nand0_out , A2, A1, A3          );
    nand nand1 (nand1_out , B2, B1              );
    and  and0  (and0_out_Y, nand0_out, nand1_out);
    buf  buf0  (Y         , and0_out_Y          );

endmodule

sva:
module sky130_fd_sc_hdll__a32oi_sva (
    input logic clk,
    input logic Y,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic B1,
    input logic B2
);

    // Y matches the implemented OAI32 logic.
    check_oai32_function: assert property (
        @(posedge clk)
        Y == !((A1 && A2 && A3) || (B1 && B2))
    );

    // All three A inputs high force Y low.
    check_a_triplet_forces_low: assert property (
        @(posedge clk)
        (A1 && A2 && A3) |-> !Y
    );

    // Both B inputs high force Y low.
    check_b_pair_forces_low: assert property (
        @(posedge clk)
        (B1 && B2) |-> !Y
    );

    // Y is high when neither input product term is active.
    check_output_high_when_no_product_active: assert property (
        @(posedge clk)
        (!(A1 && A2 && A3) && !(B1 && B2)) |-> Y
    );

    // A low Y must be caused by at least one active product term.
    check_low_output_has_cause: assert property (
        @(posedge clk)
        !Y |-> ((A1 && A2 && A3) || (B1 && B2))
    );

    // Stable inputs keep the output stable.
    check_stable_inputs_hold_output: assert property (
        @(posedge clk)
        ($stable(A1) && $stable(A2) && $stable(A3) && $stable(B1) && $stable(B2)) |-> $stable(Y)
    );

    // A sampled output change requires a sampled input change.
    check_output_change_requires_input_change: assert property (
        @(posedge clk)
        $changed(Y) |-> ($changed(A1) || $changed(A2) || $changed(A3) || $changed(B1) || $changed(B2))
    );

endmodule

rtl:
module jt12_eg_final(
	input [ 6:0] lfo_mod,
	input        amsen,
	input [ 1:0] ams,
	input [ 6:0] tl,
	input [ 9:0] eg_pure_in,
	input 		 ssg_inv,
	output reg	[9:0] eg_limited
);

reg	[ 8:0]	am_final;
reg	[11:0]	sum_eg_tl;
reg	[11:0]	sum_eg_tl_am;
reg	[ 5:0]	am_inverted;
reg [ 9:0]	eg_pream;

always @(*) begin
	am_inverted = lfo_mod[6] ? ~lfo_mod[5:0] : lfo_mod[5:0];
end

always @(*) begin
	casez( {amsen, ams } )
		default: am_final = 9'd0;
		3'b1_01: am_final = { 5'd0, am_inverted[5:2]	};
		3'b1_10: am_final = { 3'd0, am_inverted 		};
		3'b1_11: am_final = { 2'd0, am_inverted, 1'b0	};
	endcase
	eg_pream = ssg_inv ? (10'h200-eg_pure_in) : eg_pure_in;
	sum_eg_tl = {  1'b0, tl,   3'd0 } + {1'b0, eg_pream}; sum_eg_tl_am = sum_eg_tl + { 3'd0, am_final };
end

always @(*)  
	eg_limited = sum_eg_tl_am[11:10]==2'd0 ? sum_eg_tl_am[9:0] : 10'h3ff;

endmodule // jt12_eg_final

sva:
module jt12_eg_final_sva (
    input logic [6:0] lfo_mod,
    input logic       amsen,
    input logic [1:0] ams,
    input logic [6:0] tl,
    input logic [9:0] eg_pure_in,
    input logic       ssg_inv,
    input logic [9:0] eg_limited
);

    function automatic logic [5:0] calc_am_inverted(
        input logic [6:0] lfo_mod_i
    );
    begin
        calc_am_inverted = lfo_mod_i[6] ? ~lfo_mod_i[5:0] : lfo_mod_i[5:0];
    end
    endfunction

    function automatic logic [8:0] calc_am_final(
        input logic [6:0] lfo_mod_i,
        input logic       amsen_i,
        input logic [1:0] ams_i
    );
        logic [5:0] am_inv;
    begin
        am_inv = calc_am_inverted(lfo_mod_i);
        casez ({amsen_i, ams_i})
            3'b1_01: calc_am_final = {5'd0, am_inv[5:2]};
            3'b1_10: calc_am_final = {3'd0, am_inv};
            3'b1_11: calc_am_final = {2'd0, am_inv, 1'b0};
            default: calc_am_final = 9'd0;
        endcase
    end
    endfunction

    function automatic logic [9:0] calc_eg_pream(
        input logic       ssg_inv_i,
        input logic [9:0] eg_pure_in_i
    );
    begin
        calc_eg_pream = ssg_inv_i ? (10'h200 - eg_pure_in_i) : eg_pure_in_i;
    end
    endfunction

    function automatic logic [11:0] calc_sum_no_am(
        input logic [6:0] tl_i,
        input logic       ssg_inv_i,
        input logic [9:0] eg_pure_in_i
    );
    begin
        calc_sum_no_am = {1'b0, tl_i, 3'd0} + {1'b0, calc_eg_pream(ssg_inv_i, eg_pure_in_i)};
    end
    endfunction

    function automatic logic [11:0] calc_sum_with_am(
        input logic [6:0] tl_i,
        input logic       ssg_inv_i,
        input logic [9:0] eg_pure_in_i,
        input logic [8:0] am_val_i
    );
        logic [11:0] sum_no_am_v;
    begin
        sum_no_am_v = calc_sum_no_am(tl_i, ssg_inv_i, eg_pure_in_i);
        calc_sum_with_am = sum_no_am_v + {3'd0, am_val_i};
    end
    endfunction

    function automatic logic [11:0] calc_sum_full(
        input logic [6:0] lfo_mod_i,
        input logic       amsen_i,
        input logic [1:0] ams_i,
        input logic [6:0] tl_i,
        input logic [9:0] eg_pure_in_i,
        input logic       ssg_inv_i
    );
    begin
        calc_sum_full = calc_sum_with_am(
            tl_i,
            ssg_inv_i,
            eg_pure_in_i,
            calc_am_final(lfo_mod_i, amsen_i, ams_i)
        );
    end
    endfunction

    function automatic logic [9:0] calc_limit(
        input logic [11:0] sum_i
    );
    begin
        calc_limit = (sum_i[11:10] == 2'd0) ? sum_i[9:0] : 10'h3ff;
    end
    endfunction

    function automatic logic [9:0] calc_eg_limited(
        input logic [6:0] lfo_mod_i,
        input logic       amsen_i,
        input logic [1:0] ams_i,
        input logic [6:0] tl_i,
        input logic [9:0] eg_pure_in_i,
        input logic       ssg_inv_i
    );
    begin
        calc_eg_limited = calc_limit(
            calc_sum_full(lfo_mod_i, amsen_i, ams_i, tl_i, eg_pure_in_i, ssg_inv_i)
        );
    end
    endfunction

    function automatic logic [9:0] calc_eg_limited_no_am(
        input logic [6:0] tl_i,
        input logic       ssg_inv_i,
        input logic [9:0] eg_pure_in_i
    );
    begin
        calc_eg_limited_no_am = calc_limit(calc_sum_no_am(tl_i, ssg_inv_i, eg_pure_in_i));
    end
    endfunction

    function automatic logic [9:0] calc_eg_limited_with_am(
        input logic [6:0] tl_i,
        input logic       ssg_inv_i,
        input logic [9:0] eg_pure_in_i,
        input logic [8:0] am_val_i
    );
    begin
        calc_eg_limited_with_am = calc_limit(calc_sum_with_am(tl_i, ssg_inv_i, eg_pure_in_i, am_val_i));
    end
    endfunction

    // Output matches the full combinational transfer function.
    check_full_transfer_function: assert property (
        @($global_clock)
        eg_limited == calc_eg_limited(lfo_mod, amsen, ams, tl, eg_pure_in, ssg_inv)
    );

    // Disabled AM contributes zero modulation.
    check_am_disabled_zero_contribution: assert property (
        @($global_clock)
        (!amsen) |-> (eg_limited == calc_eg_limited_no_am(tl, ssg_inv, eg_pure_in))
    );

    // AMS value 00 also contributes zero modulation.
    check_ams_zero_zero_contribution: assert property (
        @($global_clock)
        (amsen && (ams == 2'b00)) |-> (eg_limited == calc_eg_limited_no_am(tl, ssg_inv, eg_pure_in))
    );

    // AMS 01 uses the reduced AM contribution.
    check_ams_one_reduced_am: assert property (
        @($global_clock)
        (amsen && (ams == 2'b01)) |-> (
            eg_limited == calc_eg_limited_with_am(
                tl,
                ssg_inv,
                eg_pure_in,
                calc_am_final(lfo_mod, 1'b1, 2'b01)
            )
        )
    );

    // AMS 10 uses the full AM contribution.
    check_ams_two_full_am: assert property (
        @($global_clock)
        (amsen && (ams == 2'b10)) |-> (
            eg_limited == calc_eg_limited_with_am(
                tl,
                ssg_inv,
                eg_pure_in,
                calc_am_final(lfo_mod, 1'b1, 2'b10)
            )
        )
    );

    // AMS 11 uses the doubled AM contribution.
    check_ams_three_doubled_am: assert property (
        @($global_clock)
        (amsen && (ams == 2'b11)) |-> (
            eg_limited == calc_eg_limited_with_am(
                tl,
                ssg_inv,
                eg_pure_in,
                calc_am_final(lfo_mod, 1'b1, 2'b11)
            )
        )
    );

    // Without SSG inversion and without AM, eg_pure_in is used directly.
    check_ssg_passthrough_without_am: assert property (
        @($global_clock)
        ((!ssg_inv) && (!amsen || (ams == 2'b00))) |-> (
            eg_limited == calc_eg_limited_no_am(tl, 1'b0, eg_pure_in)
        )
    );

    // With SSG inversion and without AM, 0x200-eg_pure_in is used.
    check_ssg_inversion_without_am: assert property (
        @($global_clock)
        (ssg_inv && (!amsen || (ams == 2'b00))) |-> (
            eg_limited == calc_eg_limited_no_am(tl, 1'b1, eg_pure_in)
        )
    );

    // Non-overflowing sums pass through their low 10 bits.
    check_unsaturated_passthrough: assert property (
        @($global_clock)
        (calc_sum_full(lfo_mod, amsen, ams, tl, eg_pure_in, ssg_inv)[11:10] == 2'd0) |-> (
            eg_limited == calc_sum_full(lfo_mod, amsen, ams, tl, eg_pure_in, ssg_inv)[9:0]
        )
    );

    // Overflowing sums saturate to the maximum output value.
    check_saturates_to_max: assert property (
        @($global_clock)
        (calc_sum_full(lfo_mod, amsen, ams, tl, eg_pure_in, ssg_inv)[11:10] != 2'd0) |-> (
            eg_limited == 10'h3ff
        )
    );

endmodule

