module bdd_module (
    input [3:0] in_data,
    input [1:0] op_select,
    output reg [3:0] out_data
);

// BDD-based functional module
always @(*) begin
    case (op_select)
        2'b00: out_data = in_data & 4'b1111; // AND operation
        2'b01: out_data = in_data | 4'b0000; // OR operation
        2'b10: out_data = in_data ^ 4'b1010; // XOR operation
        default: out_data = 4'b0000; // default output
    endcase
end

endmodule
module top_module ( 
    input [2:0] select, 
    input [3:0] data0,
    input [3:0] data1,
    input [3:0] data2,
    input [3:0] data3,
    input [3:0] data4,
    input [3:0] data5,
    input [1:0] op_select, // Changed to 1:0
    output [3:0] out 
);

wire [3:0] mux_out;
wire [3:0] bdd_out;

// 6-to-1 multiplexer
assign mux_out = (select <= 5) ? 
    ((select == 0) ? data0 :
    (select == 1) ? data1 :
    (select == 2) ? data2 :
    (select == 3) ? data3 :
    (select == 4) ? data4 :
    (select == 5) ? data5 : 4'b0000) : 4'b0000;

// BDD-based functional module instantiation
bdd_module bdd_inst (
    .in_data(mux_out),
    .op_select(op_select),
    .out_data(bdd_out)
);

// Output selection based on select input
assign out = (select <= 5) ? mux_out : bdd_out;

endmodule

sva:
module top_module_sva (
    input logic [2:0] select,
    input logic [3:0] data0,
    input logic [3:0] data1,
    input logic [3:0] data2,
    input logic [3:0] data3,
    input logic [3:0] data4,
    input logic [3:0] data5,
    input logic [1:0] op_select,
    input logic [3:0] out
);

    // select 0 routes data0 directly to out.
    check_select0_routes_data0: assert property (
        @($global_clock) (select == 3'd0) |-> (out == data0)
    );

    // select 1 routes data1 directly to out.
    check_select1_routes_data1: assert property (
        @($global_clock) (select == 3'd1) |-> (out == data1)
    );

    // select 2 routes data2 directly to out.
    check_select2_routes_data2: assert property (
        @($global_clock) (select == 3'd2) |-> (out == data2)
    );

    // select 3 routes data3 directly to out.
    check_select3_routes_data3: assert property (
        @($global_clock) (select == 3'd3) |-> (out == data3)
    );

    // select 4 routes data4 directly to out.
    check_select4_routes_data4: assert property (
        @($global_clock) (select == 3'd4) |-> (out == data4)
    );

    // select 5 routes data5 directly to out.
    check_select5_routes_data5: assert property (
        @($global_clock) (select == 3'd5) |-> (out == data5)
    );

    // Invalid select with op 00 produces zero.
    check_invalid_select_op00_zero: assert property (
        @($global_clock) ((select > 3'd5) && (op_select == 2'b00)) |-> (out == 4'b0000)
    );

    // Invalid select with op 01 produces zero.
    check_invalid_select_op01_zero: assert property (
        @($global_clock) ((select > 3'd5) && (op_select == 2'b01)) |-> (out == 4'b0000)
    );

    // Invalid select with op 10 produces 1010.
    check_invalid_select_op10_xor_value: assert property (
        @($global_clock) ((select > 3'd5) && (op_select == 2'b10)) |-> (out == 4'b1010)
    );

    // Invalid select with op 11 produces zero.
    check_invalid_select_op11_zero: assert property (
        @($global_clock) ((select > 3'd5) && (op_select == 2'b11)) |-> (out == 4'b0000)
    );

endmodule

rtl:
module binary_to_gray (
    input [2:0] bin_in,
    output reg [2:0] gray_out
);

    always @(*) begin
        gray_out[0] = bin_in[0] ^ bin_in[1];
        gray_out[1] = bin_in[1] ^ bin_in[2];
        gray_out[2] = bin_in[2];
    end

endmodule

sva:
module binary_to_gray_sva (
    input logic clk,
    input logic [2:0] bin_in,
    input logic [2:0] gray_out
);

    // gray_out matches the binary-to-gray conversion.
    check_gray_encoding: assert property (
        @(posedge clk) gray_out == {bin_in[2], (bin_in[1] ^ bin_in[2]), (bin_in[0] ^ bin_in[1])}
    );

    // The MSB of gray_out passes through bin_in[2].
    check_gray_msb_passthrough: assert property (
        @(posedge clk) gray_out[2] == bin_in[2]
    );

    // gray_out[1] is the XOR of bin_in[1] and bin_in[2].
    check_gray_mid_xor: assert property (
        @(posedge clk) gray_out[1] == (bin_in[1] ^ bin_in[2])
    );

    // gray_out[0] is the XOR of bin_in[0] and bin_in[1].
    check_gray_lsb_xor: assert property (
        @(posedge clk) gray_out[0] == (bin_in[0] ^ bin_in[1])
    );

    // A stable binary input yields a stable gray output.
    check_stable_input_stable_output: assert property (
        @(posedge clk) $stable(bin_in) |-> $stable(gray_out)
    );

endmodule

module binary_counter_sva(
    input logic clk,
    input logic rst,
    input logic [2:0] count
);

    // Reset clears count to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |=> (count == 3'b000)
    );

    // Count increments from 0 to 1.
    check_count_0_to_1: assert property (
        @(posedge clk) disable iff (rst)
        (count == 3'b000) |=> (count == 3'b001)
    );

    // Count increments from 1 to 2.
    check_count_1_to_2: assert property (
        @(posedge clk) disable iff (rst)
        (count == 3'b001) |=> (count == 3'b010)
    );

    // Count increments from 2 to 3.
    check_count_2_to_3: assert property (
        @(posedge clk) disable iff (rst)
        (count == 3'b010) |=> (count == 3'b011)
    );

    // Count increments from 3 to 4.
    check_count_3_to_4: assert property (
        @(posedge clk) disable iff (rst)
        (count == 3'b011) |=> (count == 3'b100)
    );

    // Count increments from 4 to 5.
    check_count_4_to_5: assert property (
        @(posedge clk) disable iff (rst)
        (count == 3'b100) |=> (count == 3'b101)
    );

    // Count increments from 5 to 6.
    check_count_5_to_6: assert property (
        @(posedge clk) disable iff (rst)
        (count == 3'b101) |=> (count == 3'b110)
    );

    // Count increments from 6 to 7.
    check_count_6_to_7: assert property (
        @(posedge clk) disable iff (rst)
        (count == 3'b110) |=> (count == 3'b111)
    );

    // Count wraps from 7 to 0.
    check_count_7_to_0: assert property (
        @(posedge clk) disable iff (rst)
        (count == 3'b111) |=> (count == 3'b000)
    );

endmodule

rtl:
module mux4to1 (
    input  wire a,
    input  wire b,
    input  wire c,
    input  wire d,
    input  wire [1:0] s,
    output reg y
);

always @(*) begin
    case (s)
        2'b00: y = a;
        2'b01: y = b;
        2'b10: y = c;
        2'b11: y = d;
        default: y = 1'b0;
    endcase
end

endmodule

sva:
module mux4to1_sva (
    input logic a,
    input logic b,
    input logic c,
    input logic d,
    input logic [1:0] s,
