rtl:
module altera_std_synchronizer(
  input clk,
  input reset_n,
  input din,
  output dout
);

parameter depth = 2;

reg [depth-1:0] ff;
reg [depth-1:0] ff_next;

always @(posedge clk or negedge reset_n) begin
  if (~reset_n) begin
    ff <= {depth{1'b0}};
  end else begin
    ff <= {ff[depth-2:0], din};
  end
end

assign dout = ff[depth-1];

endmodule

sva:
module altera_std_synchronizer_sva #(
    parameter int depth = 2
) (
    input  logic             clk,
    input  logic             reset_n,
    input  logic             din,
    input  logic             dout,
    input  logic [depth-1:0] ff
);

    // Reset clears all synchronizer stages.
    check_reset_clears_ff: assert property (
        @(posedge clk) !reset_n |-> (ff == {depth{1'b0}})
    );

    // Reset drives the synchronized output low.
    check_reset_clears_dout: assert property (
        @(posedge clk) !reset_n |-> (dout == 1'b0)
    );

    // The output is the last stage of the synchronizer chain.
    check_dout_matches_last_stage: assert property (
        @(posedge clk) disable iff (!reset_n) (dout == ff[depth-1])
    );

    // A sampled reset keeps all stages at zero on the next sampled cycle.
    check_reset_holds_zero_ff_to_next_cycle: assert property (
        @(posedge clk) !reset_n |=> (ff == {depth{1'b0}})
    );

    // A sampled reset keeps the output low on the next sampled cycle.
    check_reset_holds_zero_dout_to_next_cycle: assert property (
        @(posedge clk) !reset_n |=> (dout == 1'b0)
    );

    // On the sampled release of reset, the state still starts from zero.
    check_release_starts_from_zero_ff: assert property (
        @(posedge clk) disable iff (!reset_n) $rose(reset_n) |-> (ff == {depth{1'b0}})
    );

    // On the sampled release of reset, the output still starts low.
    check_release_starts_from_zero_dout: assert property (
        @(posedge clk) disable iff (!reset_n) $rose(reset_n) |-> (dout == 1'b0)
    );

endmodule

rtl:
module two_input_gate (
    input A,
    input B,
    output Y
);

    wire not_A, not_B, and_1, and_2, or_1;

    assign not_A = ~A;
    assign not_B = ~B;
    assign and_1 = not_A & B;
    assign and_2 = A & not_B;
    assign or_1 = and_1 | and_2;
    assign Y = ~or_1;

endmodule

sva:
module two_input_gate_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic Y
);

    // Y matches the RTL boolean equation.
    check_output_equation: assert property (
        @(posedge clk) Y == ~((~A & B) | (A & ~B))
    );

    // 00 on the inputs drives Y high.
    check_00_high: assert property (
        @(posedge clk) (!A && !B) |-> (Y == 1'b1)
    );

    // 01 on the inputs drives Y low.
    check_01_low: assert property (
        @(posedge clk) (!A && B) |-> (Y == 1'b0)
    );

    // 10 on the inputs drives Y low.
    check_10_low: assert property (
        @(posedge clk) (A && !B) |-> (Y == 1'b0)
    );

    // 11 on the inputs drives Y high.
    check_11_high: assert property (
        @(posedge clk) (A && B) |-> (Y == 1'b1)
    );

    // Stable sampled inputs keep the sampled output stable.
    check_stable_inputs_stable_output: assert property (
        @(posedge clk) ($stable(A) && $stable(B)) |-> $stable(Y)
    );

endmodule

module calculator_sva (
    input logic signed [15:0] a,
    input logic signed [15:0] b,
    input logic [1:0] op,
    input logic signed [15:0] result
);
    typedef logic signed [15:0] s16_t;

    // Addition opcode drives the 16-bit signed sum.
    check_add_result: assert property (
        @($global_clock) (op == 2'b00) |-> (result == s16_t'(a + b))
    );

    // Subtraction opcode drives the 16-bit signed difference.
    check_sub_result: assert property (
        @($global_clock) (op == 2'b01) |-> (result == s16_t'(a - b))
    );

    // Multiplication opcode drives the truncated 16-bit signed product.
    check_mul_result: assert property (
        @($global_clock) (op == 2'b10) |-> (result == s16_t'(a * b))
    );

    // Division opcode drives the 16-bit signed quotient when the divisor is nonzero.
    check_div_result: assert property (
        @($global_clock) ((op == 2'b11) && (b != 16'sd0)) |-> (result == s16_t'(a / b))
    );

endmodule

rtl:
module minimum_value (
    input [7:0] a, b, c, d,
    output [7:0] min_val_out
);

// Logic to find the minimum value among a, b, c, and d
assign min_val_out = (a < b) ? ((a < c) ? ((a < d) ? a : d) : ((c < d) ? c : d)) : ((b < c) ? ((b < d) ? b : d) : ((c < d) ? c : d));

endmodule

sva:
module minimum_value_sva (
    input logic       clk,
    input logic [7:0] a,
    input logic [7:0] b,
    input logic [7:0] c,
    input logic [7:0] d,
    input logic [7:0] min_val_out
);

    // Combinational DUT sampled on clk; no reset is present in the RTL.

    // Checks the output matches the RTL min-selection expression.
    check_output_matches_rtl_expression: assert property (
        @(posedge clk)
        min_val_out == ((a < b) ? ((a < c) ? ((a < d) ? a : d) : ((c < d) ? c : d))
                                : ((b < c) ? ((b < d) ? b : d) : ((c < d) ? c : d)))
    );

    // Checks the output is not greater than input a.
    check_output_le_a: assert property (
        @(posedge clk)
        min_val_out <= a
    );

    // Checks the output is not greater than input b.
    check_output_le_b: assert property (
        @(posedge clk)
        min_val_out <= b
    );

    // Checks the output is not greater than input c.
    check_output_le_c: assert property (
        @(posedge clk)
        min_val_out <= c
    );

    // Checks the output is not greater than input d.
    check_output_le_d: assert property (
        @(posedge clk)
        min_val_out <= d
    );

    // Checks the output matches one of the input values.
    check_output_is_one_of_inputs: assert property (
        @(posedge clk)
        (min_val_out == a) || (min_val_out == b) || (min_val_out == c) || (min_val_out == d)
    );

    // Checks a is produced when a is less than or equal to all inputs.
    check_select_a_when_a_is_minimum: assert property (
        @(posedge clk)
        (a <= b && a <= c && a <= d) |-> (min_val_out == a)
    );

    // Checks b is produced when b is less than or equal to all inputs.
    check_select_b_when_b_is_minimum: assert property (
        @(posedge clk)
        (b <= a && b <= c && b <= d) |-> (min_val_out == b)
    );

    // Checks c is produced when c is less than or equal to all inputs.
    check_select_c_when_c_is_minimum: assert property (
        @(posedge clk)
        (c <= a && c <= b && c <= d) |-> (min_val_out == c)
    );

    // Checks d is produced when d is less than or equal to all inputs.
    check_select_d_when_d_is_minimum: assert property (
        @(posedge clk)
        (d <= a && d <= b && d <= c) |-> (min_val_out == d)
    );

endmodule

rtl:
module custom_op(
    input [15:0] in_value,
    input [15:0] mask_value,
    input [3:0] shift_value,
    input [2:0] op_select,
    output [15:0] out_value
);

reg [15:0] temp_value;

always @(*) begin
    case(op_select)
        3'b000: temp_value = in_value & mask_value;
        3'b001: temp_value = in_value | mask_value;
        3'b010: temp_value = in_value ^ mask_value;
        3'b011: temp_value = in_value << shift_value;
        3'b100: temp_value = in_value >> shift_value;
        default: temp_value = in_value;
    endcase
end

assign out_value = temp_value;

endmodule

sva:
module custom_op_sva (
    input logic        clk,
    input logic [15:0] in_value,
    input logic [15:0] mask_value,
    input logic [3:0]  shift_value,
    input logic [2:0]  op_select,
    input logic [15:0] out_value
);

    // AND selection produces a bitwise AND.
    check_and_result: assert property (
        @(posedge clk) (op_select == 3'b000) |-> (out_value == (in_value & mask_value))
    );

    // OR selection produces a bitwise OR.
    check_or_result: assert property (
        @(posedge clk) (op_select == 3'b001) |-> (out_value == (in_value | mask_value))
    );

    // XOR selection produces a bitwise XOR.
    check_xor_result: assert property (
        @(posedge clk) (op_select == 3'b010) |-> (out_value == (in_value ^ mask_value))
    );

    // Left-shift selection shifts by shift_value.
    check_left_shift_result: assert property (
        @(posedge clk) (op_select == 3'b011) |-> (out_value == (in_value << shift_value))
    );

    // Right-shift selection shifts by shift_value.
    check_right_shift_result: assert property (
        @(posedge clk) (op_select == 3'b100) |-> (out_value == (in_value >> shift_value))
    );

    // Unused op_select values pass the input through.
    check_default_passthrough: assert property (
        @(posedge clk) ((op_select == 3'b101) || (op_select == 3'b110) || (op_select == 3'b111)) |-> (out_value == in_value)
    );

    // Left shift by zero leaves the input unchanged.
    check_left_shift_zero_identity: assert property (
        @(posedge clk) ((op_select == 3'b011) && (shift_value == 4'h0)) |-> (out_value == in_value)
    );

    // Right shift by zero leaves the input unchanged.
    check_right_shift_zero_identity: assert property (
        @(posedge clk) ((op_select == 3'b100) && (shift_value == 4'h0)) |-> (out_value == in_value)
    );

    // AND with a zero mask yields zero.
    check_and_zero_mask: assert property (
        @(posedge clk) ((op_select == 3'b000) && (mask_value == 16'h0000)) |-> (out_value == 16'h0000)
    );

    // OR with a zero mask leaves the input unchanged.
    check_or_zero_mask_identity: assert property (
        @(posedge clk) ((op_select == 3'b001) && (mask_value == 16'h0000)) |-> (out_value == in_value)
    );

    // XOR with a zero mask leaves the input unchanged.
    check_xor_zero_mask_identity: assert property (
        @(posedge clk) ((op_select == 3'b010) && (mask_value == 16'h0000)) |-> (out_value == in_value)
    );

endmodule

rtl:
module XOR2(
    input a,
    input b,
    output c
);

    assign c = a ^ b;

endmodule

module XOR3(
    input i0,
    input i1,
    input i2,
    output o
);

    wire w1, w2;

    XOR2 x1(
        .a(i0),
        .b(i1),
        .c(w1)
    );

    XOR2 x2(
        .a(w1),
        .b(i2),
        .c(o)
    );

endmodule

sva:
module XOR3_sva(
    input logic clk,
    input logic i0,
    input logic i1,
    input logic i2,
    input logic o
);

    // No RTL clock or reset; clk is the assertion sampling clock.
    // XOR3 is purely combinational.

    // Output equals the XOR of all three inputs.
    check_output_is_three_input_xor: assert property (
        @(posedge clk) o == (i0 ^ i1 ^ i2)
    );

    // With i2 low, the output reduces to i0 XOR i1.
    check_reduce_when_i2_low: assert property (
        @(posedge clk) (i2 == 1'b0) |-> (o == (i0 ^ i1))
    );

    // With i2 high, the output is the inverse of i0 XOR i1.
    check_invert_when_i2_high: assert property (
        @(posedge clk) (i2 == 1'b1) |-> (o == ~(i0 ^ i1))
    );

    // Equal i0 and i1 make the output match i2.
    check_equal_inputs_pass_through_i2: assert property (
        @(posedge clk) (i0 == i1) |-> (o == i2)
    );

    // Different i0 and i1 make the output invert i2.
    check_different_inputs_invert_i2: assert property (
        @(posedge clk) (i0 != i1) |-> (o == ~i2)
    );

    // With i0 low, the output reduces to i1 XOR i2.
    check_reduce_when_i0_low: assert property (
        @(posedge clk) (i0 == 1'b0) |-> (o == (i1 ^ i2))
    );

    // With i1 low, the output reduces to i0 XOR i2.
    check_reduce_when_i1_low: assert property (
        @(posedge clk) (i1 == 1'b0) |-> (o == (i0 ^ i2))
    );

endmodule

rtl:
module accumulator (
  input clk,
  input [7:0] data_in,
  output reg [31:0] sum_out
);

  always @(posedge clk) begin
    sum_out <= sum_out + data_in;
  end

endmodule

sva:
module accumulator_assertions (
    input logic        clk,
    input logic [7:0]  data_in,
    input logic [31:0] sum_out
);

    // sum_out accumulates the previous cycle's data_in every clock.
    check_sum_accumulates: assert property (
        @(posedge clk) disable iff (1'b0)
        1'b1 |=> (sum_out == ($past(sum_out) + $past(data_in)))
    );

    // A zero input leaves sum_out unchanged on the next clock.
    check_zero_input_holds: assert property (
        @(posedge clk) disable iff (1'b0)
        1'b1 |=> (($past(data_in) == 8'h00) -> (sum_out == $past(sum_out)))
    );

    // The low byte updates as the previous low byte plus previous data_in.
    check_low_byte_updates: assert property (
        @(posedge clk) disable iff (1'b0)
        1'b1 |=> (sum_out[7:0] == ($past(sum_out[7:0]) + $past(data_in)))
    );

    // Without a low-byte carry, the upper 24 bits stay unchanged.
    check_no_low_byte_carry_keeps_upper: assert property (
        @(posedge clk) disable iff (1'b0)
        1'b1 |=> ((({1'b0, $past(sum_out[7:0])} + {1'b0, $past(data_in)}) < 9'h100) ->
                  (sum_out[31:8] == $past(sum_out[31:8])))
    );

    // A low-byte carry increments the upper 24 bits by one.
    check_low_byte_carry_increments_upper: assert property (
        @(posedge clk) disable iff (1'b0)
        1'b1 |=> ((({1'b0, $past(sum_out[7:0])} + {1'b0, $past(data_in)}) >= 9'h100) ->
                  (sum_out[31:8] == ($past(sum_out[31:8]) + 24'd1)))
    );

endmodule

rtl:
module multiplier (
    input [3:0] A,
    input [3:0] B,
    output reg [7:0] OUT
);

reg [7:0] result;
reg [3:0] temp_A;
reg [3:0] temp_B;

integer i;

always @(*) begin
    result = 8'b0;
    temp_A = A;
    temp_B = B;

    for (i = 0; i < 4; i = i + 1) begin
        if (temp_B[0]) begin
            result = result + (temp_A << i);
        end
        temp_B = temp_B >> 1;
    end

    OUT <= result;
end

endmodule

sva:
module multiplier_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [7:0] OUT
);

    // OUT must match the full 4x4 product.
    check_exact_product: assert property (
        @(posedge clk) {8'b0, OUT} == ({4'b0, A} * {4'b0, B})
    );

    // The product LSB must be the AND of the operand LSBs.
    check_lsb_product: assert property (
        @(posedge clk) OUT[0] == (A[0] & B[0])
    );

    // A equal to zero must force the product to zero.
    check_zero_operand_a: assert property (
        @(posedge clk) (A == 4'd0) |-> (OUT == 8'd0)
    );

    // B equal to zero must force the product to zero.
    check_zero_operand_b: assert property (
        @(posedge clk) (B == 4'd0) |-> (OUT == 8'd0)
    );

    // A equal to one must pass B through to the output.
    check_unit_operand_a: assert property (
        @(posedge clk) (A == 4'd1) |-> (OUT == {4'b0, B})
    );

    // B equal to one must pass A through to the output.
    check_unit_operand_b: assert property (
        @(posedge clk) (B == 4'd1) |-> (OUT == {4'b0, A})
    );

    // B equal to two must produce A shifted left by one.
    check_shift_by_one: assert property (
        @(posedge clk) (B == 4'd2) |-> (OUT == ({4'b0, A} << 1))
    );

    // B equal to four must produce A shifted left by two.
    check_shift_by_two: assert property (
        @(posedge clk) (B == 4'd4) |-> (OUT == ({4'b0, A} << 2))
    );

    // B equal to eight must produce A shifted left by three.
    check_shift_by_three: assert property (
        @(posedge clk) (B == 4'd8) |-> (OUT == ({4'b0, A} << 3))
    );

    // The maximum 4-bit operands must produce 225.
    check_max_operands: assert property (
        @(posedge clk) ((A == 4'hf) && (B == 4'hf)) |-> (OUT == 8'he1)
    );

endmodule

module xor_gate_sva (
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB,
    input logic XOR_output
);

    // Output matches the RTL XOR function after output changes and on isolated power-pin changes.
    check_xor_relation: assert property (
        @(posedge VPWR or negedge VPWR or posedge VGND or negedge VGND or
          posedge VPB or negedge VPB or posedge VNB or negedge VNB or
          posedge XOR_output or negedge XOR_output)
        (
            $changed(XOR_output) ||
            (($changed(VPWR) || $changed(VGND)) && $stable({VPB, VNB}))
        )
        |-> (XOR_output === (VPB ^ VNB))
    );

    // Equal known inputs drive the XOR output low.
    check_equal_known_inputs_drive_low: assert property (
        @(posedge VPWR or negedge VPWR or posedge VGND or negedge VGND or
          posedge VPB or negedge VPB or posedge VNB or negedge VNB or
          posedge XOR_output or negedge XOR_output)
        (
            $changed(XOR_output) ||
            (($changed(VPWR) || $changed(VGND)) && $stable({VPB, VNB}))
        ) &&
        (
            ((VPB === 1'b0) && (VNB === 1'b0)) ||
            ((VPB === 1'b1) && (VNB === 1'b1))
        )
        |-> (XOR_output === 1'b0)
    );

    // Different known inputs drive the XOR output high.
    check_different_known_inputs_drive_high: assert property (
        @(posedge VPWR or negedge VPWR or posedge VGND or negedge VGND or
          posedge VPB or negedge VPB or posedge VNB or negedge VNB or
          posedge XOR_output or negedge XOR_output)
        (
            $changed(XOR_output) ||
            (($changed(VPWR) || $changed(VGND)) && $stable({VPB, VNB}))
        ) &&
        (
            ((VPB === 1'b0) && (VNB === 1'b1)) ||
            ((VPB === 1'b1) && (VNB === 1'b0))
        )
        |-> (XOR_output === 1'b1)
    );

    // Known binary inputs produce a known binary output.
    check_known_inputs_produce_known_output: assert property (
        @(posedge VPWR or negedge VPWR or posedge VGND or negedge VGND or
          posedge VPB or negedge VPB or posedge VNB or negedge VNB or
          posedge XOR_output or negedge XOR_output)
        (
            $changed(XOR_output) ||
            (($changed(VPWR) || $changed(VGND)) && $stable({VPB, VNB}))
        ) &&
        ((VPB === 1'b0) || (VPB === 1'b1)) &&
        ((VNB === 1'b0) || (VNB === 1'b1))
        |-> ((XOR_output === 1'b0) || (XOR_output === 1'b1))
    );

    // VPWR and VGND changes alone do not change the output.
    check_power_pin_changes_do_not_toggle_output: assert property (
        @(posedge VPWR or negedge VPWR or posedge VGND or negedge VGND or
          posedge VPB or negedge VPB or posedge VNB or negedge VNB or
          posedge XOR_output or negedge XOR_output)
        (($changed(VPWR) || $changed(VGND)) && $stable({VPB, VNB}))
        |-> $stable(XOR_output)
    );

endmodule

rtl:
module four_bit_adder (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] S,
    output Cout
);

    wire [3:0] sum;
    wire Cout1, Cout2, Cout3;

    // First adder stage
    full_adder FA1 (.A(A[0]), .B(B[0]), .Cin(Cin), .S(sum[0]), .Cout(Cout1));

    // Second adder stage
    full_adder FA2 (.A(A[1]), .B(B[1]), .Cin(Cout1), .S(sum[1]), .Cout(Cout2));

    // Third adder stage
    full_adder FA3 (.A(A[2]), .B(B[2]), .Cin(Cout2), .S(sum[2]), .Cout(Cout3));

    // Fourth adder stage
    full_adder FA4 (.A(A[3]), .B(B[3]), .Cin(Cout3), .S(sum[3]), .Cout(Cout));

    assign S = sum;

endmodule

module full_adder (
    input A,
    input B,
    input Cin,
    output S,
    output Cout
);

    wire sum1, sum2, sum3;

    // XOR gates
    assign sum1 = A ^ B;
    assign sum2 = sum1 ^ Cin;

    // AND gates
    assign Cout = (A & B) | (Cin & sum1);
    assign S = sum2;

endmodule

sva:
module four_bit_adder_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic Cin,
    input logic [3:0] S,
    input logic Cout,
    input logic [3:0] sum,
    input logic Cout1,
    input logic Cout2,
    input logic Cout3
);

    // No RTL clock or reset; assertions are sampled on $global_clock.

    // The output S must always mirror the internal sum bus.
    check_sum_output_alias: assert property (
        @($global_clock) S == sum
    );

    // Stage 0 sum matches full-adder XOR behavior.
    check_stage0_sum: assert property (
        @($global_clock) sum[0] == (A[0] ^ B[0] ^ Cin)
    );

    // Stage 0 carry matches full-adder carry behavior.
    check_stage0_carry: assert property (
        @($global_clock) Cout1 == ((A[0] & B[0]) | (Cin & (A[0] ^ B[0])))
    );

    // Stage 1 sum uses Cout1 as its carry-in.
    check_stage1_sum: assert property (
        @($global_clock) sum[1] == (A[1] ^ B[1] ^ Cout1)
    );

    // Stage 1 carry matches full-adder carry behavior.
    check_stage1_carry: assert property (
        @($global_clock) Cout2 == ((A[1] & B[1]) | (Cout1 & (A[1] ^ B[1])))
    );

    // Stage 2 sum uses Cout2 as its carry-in.
    check_stage2_sum: assert property (
        @($global_clock) sum[2] == (A[2] ^ B[2] ^ Cout2)
    );

    // Stage 2 carry matches full-adder carry behavior.
    check_stage2_carry: assert property (
        @($global_clock) Cout3 == ((A[2] & B[2]) | (Cout2 & (A[2] ^ B[2])))
    );

    // Stage 3 sum uses Cout3 as its carry-in.
    check_stage3_sum: assert property (
        @($global_clock) sum[3] == (A[3] ^ B[3] ^ Cout3)
    );

    // Final carry-out matches the last full-adder stage.
    check_stage3_carry: assert property (
        @($global_clock) Cout == ((A[3] & B[3]) | (Cout3 & (A[3] ^ B[3])))
    );

    // The overall 5-bit result matches A + B + Cin.
    check_total_sum: assert property (
        @($global_clock) {Cout, S} == ({1'b0, A} + {1'b0, B} + {4'b0000, Cin})
    );

endmodule

module branch_hazard_detector_sva (
    input logic        clk,
    input logic [4:0]  ID_rs,
    input logic [4:0]  ID_rt,
    input logic        EX_regwe,
    input logic [4:0]  EX_RW,
    input logic        MEM_ramtoreg,
    input logic [4:0]  MEM_RW,
    input logic        ID_jmp_need_reg,
    input logic        ID_jmp_reg,
    input logic        ID_misprediction,
    input logic        branch_flushD,
    input logic        branch_flushE
);

    // branch_flushD is the OR of jump-register and misprediction.
    check_branch_flushD_equation: assert property (
        @(posedge clk)
        branch_flushD == (ID_jmp_reg || ID_misprediction)
    );

    // A jump-register request forces branch_flushD high.
    check_branch_flushD_on_jmp_reg: assert property (
        @(posedge clk)
        ID_jmp_reg |-> branch_flushD
    );

    // A misprediction forces branch_flushD high.
    check_branch_flushD_on_misprediction: assert property (
        @(posedge clk)
        ID_misprediction |-> branch_flushD
    );

    // branch_flushD is low when neither source requests a flush.
    check_branch_flushD_clear_without_cause: assert property (
        @(posedge clk)
        (!ID_jmp_reg && !ID_misprediction) |-> !branch_flushD
    );

    // branch_flushE matches the implemented EX/MEM hazard expression.
    check_branch_flushE_equation: assert property (
        @(posedge clk)
        branch_flushE == (
            (ID_jmp_need_reg && EX_regwe && (EX_RW != 5'd0) &&
             ((EX_RW == ID_rs) || (EX_RW == ID_rt))) ||
            (ID_jmp_need_reg && MEM_ramtoreg && (MEM_RW != 5'd0) &&
             ((MEM_RW == ID_rs) || (MEM_RW == ID_rt)))
        )
    );

    // An EX-stage register dependency forces branch_flushE high.
    check_branch_flushE_on_ex_dependency: assert property (
        @(posedge clk)
        (ID_jmp_need_reg && EX_regwe && (EX_RW != 5'd0) &&
         ((EX_RW == ID_rs) || (EX_RW == ID_rt))) |-> branch_flushE
    );

    // A MEM-stage load dependency forces branch_flushE high.
    check_branch_flushE_on_mem_dependency: assert property (
        @(posedge clk)
        (ID_jmp_need_reg && MEM_ramtoreg && (MEM_RW != 5'd0) &&
         ((MEM_RW == ID_rs) || (MEM_RW == ID_rt))) |-> branch_flushE
    );

    // branch_flushE can only be high for a real jump-register data hazard.
    check_branch_flushE_implies_valid_dependency: assert property (
        @(posedge clk)
        branch_flushE |-> (
            ID_jmp_need_reg &&
            (
                (EX_regwe && (EX_RW != 5'd0) &&
                 ((EX_RW == ID_rs) || (EX_RW == ID_rt))) ||
                (MEM_ramtoreg && (MEM_RW != 5'd0) &&
                 ((MEM_RW == ID_rs) || (MEM_RW == ID_rt)))
            )
        )
    );

    // branch_flushE is low when neither EX nor MEM hazard condition is present.
    check_branch_flushE_clear_without_dependency: assert property (
        @(posedge clk)
        (!(ID_jmp_need_reg && EX_regwe && (EX_RW != 5'd0) &&
           ((EX_RW == ID_rs) || (EX_RW == ID_rt))) &&
         !(ID_jmp_need_reg && MEM_ramtoreg && (MEM_RW != 5'd0) &&
           ((MEM_RW == ID_rs) || (MEM_RW == ID_rt)))) |-> !branch_flushE
    );

endmodule

