module bitwise_xor(
    input [31:0] a,
    input [31:0] b,
    output [31:0] result
);

assign result = a ^ b;

endmodule

sva:
module bitwise_xor_sva(
    input logic [31:0] a,
    input logic [31:0] b,
    input logic [31:0] result
);

    // No RTL clock or reset; sample combinational behavior on the global clock.

    // Result must always equal the bitwise XOR of a and b.
    check_result_is_xor: assert property (
        @($global_clock) result == (a ^ b)
    );

    // Equal inputs must produce an all-zero result.
    check_equal_inputs_zero_result: assert property (
        @($global_clock) (a == b) |-> (result == 32'h00000000)
    );

    // A zero value on a must pass b through unchanged.
    check_zero_a_passthrough_b: assert property (
        @($global_clock) (a == 32'h00000000) |-> (result == b)
    );

    // A zero value on b must pass a through unchanged.
    check_zero_b_passthrough_a: assert property (
        @($global_clock) (b == 32'h00000000) |-> (result == a)
    );

    // All ones on a must invert b.
    check_all_ones_a_inverts_b: assert property (
        @($global_clock) (a == 32'hFFFFFFFF) |-> (result == ~b)
    );

    // All ones on b must invert a.
    check_all_ones_b_inverts_a: assert property (
        @($global_clock) (b == 32'hFFFFFFFF) |-> (result == ~a)
    );

    // XORing result with a must recover b.
    check_result_xor_a_recovers_b: assert property (
        @($global_clock) (result ^ a) == b
    );

    // XORing result with b must recover a.
    check_result_xor_b_recovers_a: assert property (
        @($global_clock) (result ^ b) == a
    );

endmodule

module calculator_sva (
    input logic clk,
    input logic signed [3:0] op1,
    input logic signed [3:0] op2,
    input logic [1:0] op,
    input logic signed [3:0] result
);

    function automatic logic signed [3:0] calc_expected (
        input logic signed [3:0] f_op1,
        input logic signed [3:0] f_op2,
        input logic [1:0] f_op
    );
    begin
        calc_expected = 4'bxxxx;
        case (f_op)
            2'b00: calc_expected = f_op1 + f_op2;
            2'b01: calc_expected = f_op1 - f_op2;
            2'b10: calc_expected = f_op1 * f_op2;
            2'b11: begin
                if (f_op2 == 0)
                    calc_expected = 4'bxxxx;
                else if ((f_op1 == -8) && (f_op2 == -1))
                    calc_expected = 4'bxxxx;
                else
                    calc_expected = f_op1 / f_op2;
            end
            default: calc_expected = 4'bxxxx;
        endcase
    end
    endfunction

    // Addition mode returns the 4-bit signed sum.
    check_addition_result: assert property (
        @(posedge clk) (op == 2'b00) |-> (result === calc_expected(op1, op2, op))
    );

    // Subtraction mode returns the 4-bit signed difference.
    check_subtraction_result: assert property (
        @(posedge clk) (op == 2'b01) |-> (result === calc_expected(op1, op2, op))
    );

    // Multiplication mode returns the truncated 4-bit signed product.
    check_multiplication_result: assert property (
        @(posedge clk) (op == 2'b10) |-> (result === calc_expected(op1, op2, op))
    );

    // Division mode returns the signed quotient for non-exception cases.
    check_division_result: assert property (
        @(posedge clk)
        (op == 2'b11 && (op2 != 0) && !((op1 == -8) && (op2 == -1)))
        |-> (result === calc_expected(op1, op2, op))
    );

endmodule

rtl:

module axi_data_fifo_v2_1_8_ndeep_srl #
  (
   parameter         C_FAMILY  = "rtl", parameter         C_A_WIDTH = 1          )
  (
   input  wire                 CLK, input  wire [C_A_WIDTH-1:0] A,   input  wire                 CE,  input  wire                 D,   output wire                 Q    );

  localparam integer P_SRLASIZE = 5;
  localparam integer P_SRLDEPTH = 32;
  localparam integer P_NUMSRLS  = (C_A_WIDTH>P_SRLASIZE) ? (2**(C_A_WIDTH-P_SRLASIZE)) : 1;
  localparam integer P_SHIFT_DEPTH  = 2**C_A_WIDTH;

  wire [P_NUMSRLS:0]   d_i;
  wire [P_NUMSRLS-1:0] q_i;
  wire [(C_A_WIDTH>P_SRLASIZE) ? (C_A_WIDTH-1) : (P_SRLASIZE-1) : 0] a_i;

  genvar i;

  assign d_i[0] = D;
  assign a_i = A;

  generate

    if (C_FAMILY == "rtl") begin : gen_rtl_shifter
      if (C_A_WIDTH <= P_SRLASIZE) begin : gen_inferred_srl
        reg [P_SRLDEPTH-1:0] shift_reg = {P_SRLDEPTH{1'b0}};
        always @(posedge CLK)
          if (CE)
            shift_reg <= {shift_reg[P_SRLDEPTH-2:0], D};
        assign Q = shift_reg[a_i];
      end else begin : gen_logic_shifter  reg [P_SHIFT_DEPTH-1:0] shift_reg = {P_SHIFT_DEPTH{1'b0}};
        always @(posedge CLK)
          if (CE)
            shift_reg <= {shift_reg[P_SHIFT_DEPTH-2:0], D};
        assign Q = shift_reg[a_i];
      end
    end else begin : gen_primitive_shifter
      for (i=0;i<P_NUMSRLS;i=i+1) begin : gen_srls
        SRLC32E
          srl_inst
            (
             .CLK (CLK),
             .A   (a_i[P_SRLASIZE-1:0]),
             .CE  (CE),
             .D   (d_i[i]),
             .Q   (q_i[i]),
             .Q31 (d_i[i+1])
             );
      end

      if (C_A_WIDTH>P_SRLASIZE) begin : gen_srl_mux
        generic_baseblocks_v2_1_0_nto1_mux #
        (
          .C_RATIO         (2**(C_A_WIDTH-P_SRLASIZE)),
          .C_SEL_WIDTH     (C_A_WIDTH-P_SRLASIZE),
          .C_DATAOUT_WIDTH (1),
          .C_ONEHOT        (0)
        )
        srl_q_mux_inst
        (
          .SEL_ONEHOT ({2**(C_A_WIDTH-P_SRLASIZE){1'b0}}),
          .SEL        (a_i[C_A_WIDTH-1:P_SRLASIZE]),
          .IN         (q_i),
          .OUT        (Q)
        );
      end else begin : gen_no_srl_mux
        assign Q = q_i[0];
      end
    end
  endgenerate

endmodule

sva:
module axi_data_fifo_v2_1_8_ndeep_srl_sva #(
    parameter C_FAMILY = "rtl",
    parameter integer C_A_WIDTH = 1
) (
    input logic                 CLK,
    input logic [C_A_WIDTH-1:0] A,
    input logic                 CE,
    input logic                 D,
    input logic                 Q
);

    localparam logic [C_A_WIDTH-1:0] ADDR_0 = '0;
    localparam logic [C_A_WIDTH-1:0] ADDR_1 = 1;

    property p_addr0_after_shift;
        logic d_first;
        @(posedge CLK)
            (CE, d_first = D) |=> ((A == ADDR_0) |-> (Q == d_first));
    endproperty

    property p_addr1_after_two_shifts;
        logic d_first;
        @(posedge CLK)
            (CE, d_first = D) ##1 CE |=> ((A == ADDR_1) |-> (Q == d_first));
    endproperty

    property p_addr1_after_two_shifts_and_hold;
        logic d_first;
        @(posedge CLK)
            (CE, d_first = D) ##1 CE ##1 !CE |=> ((A == ADDR_1) |-> (Q == d_first));
    endproperty

    // Address 0 returns the bit shifted in on the prior enabled cycle.
    check_addr0_after_shift: assert property (p_addr0_after_shift);

    // With CE low, Q holds when the selected address stays the same.
    check_hold_when_disabled: assert property (
        @(posedge CLK)
            !CE |=> ($stable(A) |-> $stable(Q))
    );

    // Address 1 returns the bit shifted in two enabled cycles earlier.
    check_addr1_after_two_shifts: assert property (p_addr1_after_two_shifts);

    // A disabled cycle does not disturb the data already shifted to address 1.
    check_addr1_after_two_shifts_and_hold: assert property (p_addr1_after_two_shifts_and_hold);

    generate
        if (C_A_WIDTH > 1) begin : gen_deeper_address_checks
            localparam logic [C_A_WIDTH-1:0] ADDR_2 = 2;
            localparam logic [C_A_WIDTH-1:0] ADDR_3 = 3;

            property p_addr2_after_three_shifts;
                logic d_first;
                @(posedge CLK)
                    (CE, d_first = D) ##1 CE ##1 CE |=> ((A == ADDR_2) |-> (Q == d_first));
            endproperty

            property p_addr3_after_four_shifts;
                logic d_first;
                @(posedge CLK)
                    (CE, d_first = D) ##1 CE ##1 CE ##1 CE |=> ((A == ADDR_3) |-> (Q == d_first));
            endproperty

            // Address 2 returns the bit shifted in three enabled cycles earlier.
            check_addr2_after_three_shifts: assert property (p_addr2_after_three_shifts);

            // Address 3 returns the bit shifted in four enabled cycles earlier.
            check_addr3_after_four_shifts: assert property (p_addr3_after_four_shifts);
        end
    endgenerate

endmodule

rtl:
module bit_counter(
    input [3:0] in,
    output reg count
);

    reg [2:0] i;
    reg [3:0] current_bit;
    reg [2:0] ones_count;

    always @* begin
        ones_count = 0;
        for (i = 0; i < 4; i = i + 1) begin
            current_bit = in[i];
            if (current_bit == 1) begin
                ones_count = ones_count + 1;
            end
        end
        count = ones_count;
    end

endmodule

sva:
module bit_counter_sva (
    input logic clk,
    input logic [3:0] in,
    input logic count
);

    // Count is the parity of the four input bits.
    check_count_matches_parity: assert property (
        @(posedge clk) count == (in[0] ^ in[1] ^ in[2] ^ in[3])
    );

    // Zero or four asserted input bits drive count low.
    check_zero_or_four_ones_drive_low: assert property (
        @(posedge clk) ((in == 4'b0000) || (in == 4'b1111)) |-> (count == 1'b0)
    );

    // Any one-hot input drives count high.
    check_one_hot_drives_high: assert property (
        @(posedge clk) (in inside {4'b0001, 4'b0010, 4'b0100, 4'b1000}) |-> (count == 1'b1)
    );

    // Any two-hot input drives count low.
    check_two_ones_drive_low: assert property (
        @(posedge clk) (in inside {4'b0011, 4'b0101, 4'b0110, 4'b1001, 4'b1010, 4'b1100}) |-> (count == 1'b0)
    );

    // Any three-hot input drives count high.
    check_three_ones_drive_high: assert property (
        @(posedge clk) (in inside {4'b0111, 4'b1011, 4'b1101, 4'b1110}) |-> (count == 1'b1)
    );

endmodule

rtl:
module spi_slave(
    input clk,
    input rst_n,
    input sck,
    input mosi,
    input ssel,
    output miso,
    output recived_status
);

reg [2:0] sckr;
reg [2:0] sselr;
reg [1:0] mosir;
reg [2:0] bitcnt;
reg [7:0] bytecnt;
reg byte_received;  // high when a byte has been received
reg [7:0] byte_data_received;
reg [7:0] received_memory;
reg [7:0] byte_data_sent;
reg [7:0] cnt;
reg recived_status;

wire ssel_active;
wire sck_risingedge;
wire sck_fallingedge;
wire ssel_startmessage;
wire ssel_endmessage;
wire mosi_data;


always @(posedge clk or negedge rst_n) begin
  if(!rst_n)
    sckr <= 3'h0;
  else
    sckr <= {sckr[1:0],sck};
end

assign sck_risingedge = (sckr[2:1] == 2'b01) ? 1'b1 : 1'b0;
assign sck_fallingedge = (sckr[2:1] == 2'b10) ? 1'b1 : 1'b0;


always @(posedge clk or negedge rst_n) begin
  if(!rst_n)
    sselr <= 3'h0;
  else
    sselr <= {sselr[1:0],ssel};
end

assign  ssel_active = (~sselr[1]) ? 1'b1 : 1'b0;  // SSEL is active low
assign  ssel_startmessage = (sselr[2:1]==2'b10) ? 1'b1 : 1'b0;  // message starts at falling edge
assign  ssel_endmessage = (sselr[2:1]==2'b01) ? 1'b1 : 1'b0;  // message stops at rising edge


always @(posedge clk or negedge rst_n) begin
  if(!rst_n)
    mosir <= 2'h0;
  else
    mosir <= {mosir[0],mosi};
end

assign mosi_data = mosir[1];


always @(posedge clk or negedge rst_n) begin
  if(!rst_n) begin
    bitcnt <= 3'b000;
    byte_data_received <= 8'h0;
  end
  else begin
    if(~ssel_active)
      bitcnt <= 3'b000;
    else begin
      if(sck_risingedge) begin
        bitcnt <= bitcnt + 3'b001;
        byte_data_received <= {byte_data_received[6:0], mosi_data};
      end
    end
  end
end

always @(posedge clk or negedge rst_n) begin
  if(!rst_n)
    byte_received <= 1'b0;
  else
    byte_received <= ssel_active && sck_risingedge && (bitcnt == 3'b111);
end

always @(posedge clk or negedge rst_n) begin
  if(!rst_n) begin
    bytecnt <= 8'h0;
    received_memory <= 8'h0;
  end
  else begin
    if(byte_received) begin
      bytecnt <= bytecnt + 1'b1;
      received_memory <= (byte_data_received == bytecnt) ? (received_memory + 1'b1) : received_memory;
    end
  end
end

always @(posedge clk or negedge rst_n) begin
  if(!rst_n)
    recived_status <= 1'b0;
  else if(received_memory == 8'd64) begin
    recived_status <= 1'b1;
  end
end


always @(posedge clk or negedge rst_n) begin
  if(!rst_n)
    cnt <= 8'h0;
  else begin
    if(byte_received)
      cnt <= cnt + 8'h1;  // count the messages
  end
end

always @(posedge clk or negedge rst_n) begin
  if(!rst_n)
    byte_data_sent <= 8'h0;
  else begin
    if(ssel_active && sck_fallingedge) begin
      if(bitcnt == 3'b000)
        byte_data_sent <= cnt;  // after that, we send 0s
      else
        byte_data_sent <= {byte_data_sent[6:0], 1'b0};
    end
  end
end

assign miso = byte_data_sent[7];  // send MSB first

endmodule

sva:
module spi_slave_sva (
    input logic clk,
    input logic rst_n,
    input logic sck,
    input logic mosi,
    input logic ssel,
    input logic miso,
    input logic recived_status,
    input logic [2:0] sckr,
    input logic [2:0] sselr,
    input logic [1:0] mosir,
    input logic [2:0] bitcnt,
    input logic [7:0] bytecnt,
    input logic byte_received,
    input logic [7:0] byte_data_received,
    input logic [7:0] received_memory,
    input logic [7:0] byte_data_sent,
    input logic [7:0] cnt,
    input logic ssel_active,
    input logic sck_risingedge,
    input logic sck_fallingedge,
    input logic ssel_startmessage,
    input logic ssel_endmessage,
    input logic mosi_data
);

    // Reset drives all storage elements and outputs low.
    check_reset_state: assert property (
        @(posedge clk)
        !rst_n |-> (sckr == 3'h0) &&
                  (sselr == 3'h0) &&
                  (mosir == 2'h0) &&
                  (bitcnt == 3'b000) &&
                  (bytecnt == 8'h0) &&
                  (byte_received == 1'b0) &&
                  (byte_data_received == 8'h0) &&
                  (received_memory == 8'h0) &&
                  (byte_data_sent == 8'h0) &&
                  (cnt == 8'h0) &&
                  (recived_status == 1'b0) &&
                  (miso == 1'b0)
    );

    // sckr shifts in sck every clk.
    check_sckr_shift: assert property (
        @(posedge clk) disable iff (!rst_n)
        1'b1 |=> (sckr == {$past(sckr[1:0]), $past(sck)})
    );

    // sselr shifts in ssel every clk.
    check_sselr_shift: assert property (
        @(posedge clk) disable iff (!rst_n)
        1'b1 |=> (sselr == {$past(sselr[1:0]), $past(ssel)})
    );

    // mosir shifts in mosi every clk.
    check_mosir_shift: assert property (
        @(posedge clk) disable iff (!rst_n)
        1'b1 |=> (mosir == {$past(mosir[0]), $past(mosi)})
    );

    // sck_risingedge decodes 01 in sckr[2:1].
    check_sck_risingedge_decode: assert property (
        @(posedge clk) disable iff (!rst_n)
        (sck_risingedge == (sckr[2:1] == 2'b01))
    );

    // sck_fallingedge decodes 10 in sckr[2:1].
    check_sck_fallingedge_decode: assert property (
        @(posedge clk) disable iff (!rst_n)
        (sck_fallingedge == (sckr[2:1] == 2'b10))
    );

    // ssel_active is the inverted synchronized select.
    check_ssel_active_decode: assert property (
        @(posedge clk) disable iff (!rst_n)
        (ssel_active == ~sselr[1])
    );

    // ssel_startmessage decodes a falling ssel edge.
    check_ssel_startmessage_decode: assert property (
        @(posedge clk) disable iff (!rst_n)
        (ssel_startmessage == (sselr[2:1] == 2'b10))
    );

    // ssel_endmessage decodes a rising ssel edge.
    check_ssel_endmessage_decode: assert property (
        @(posedge clk) disable iff (!rst_n)
        (ssel_endmessage == (sselr[2:1] == 2'b01))
    );

    // mosi_data is the delayed MOSI sample.
    check_mosi_data_decode: assert property (
        @(posedge clk) disable iff (!rst_n)
        (mosi_data == mosir[1])
    );

    // bitcnt clears when inactive, increments on rising SCK, else holds.
    check_bitcnt_update: assert property (
        @(posedge clk) disable iff (!rst_n)
        1'b1 |=> (bitcnt == (!$past(ssel_active) ? 3'b000 :
                              ($past(sck_risingedge) ? ($past(bitcnt) + 3'b001) :
                                                       $past(bitcnt))))
    );

    // Receive shift register updates only on active rising SCK.
    check_byte_data_received_update: assert property (
        @(posedge clk) disable iff (!rst_n)
        1'b1 |=> (byte_data_received ==
                  (($past(ssel_active) && $past(sck_risingedge)) ?
                   {$past(byte_data_received[6:0]), $past(mosi_data)} :
                   $past(byte_data_received)))
    );

    // byte_received is the delayed pulse for bitcnt==7 on active rising SCK.
    check_byte_received_generation: assert property (
        @(posedge clk) disable iff (!rst_n)
        1'b1 |=> (byte_received ==
                  $past(ssel_active && sck_risingedge && (bitcnt == 3'b111)))
    );

    // bytecnt increments only when byte_received is high.
    check_bytecnt_update: assert property (
        @(posedge clk) disable iff (!rst_n)
        1'b1 |=> (bytecnt ==
                  ($past(byte_received) ? ($past(bytecnt) + 8'h1) :
                                          $past(bytecnt)))
    );

    // received_memory increments only for matching received bytes.
    check_received_memory_update: assert property (
        @(posedge clk) disable iff (!rst_n)
        1'b1 |=> (received_memory ==
                  (($past(byte_received) &&
                    ($past(byte_data_received) == $past(bytecnt))) ?
                   ($past(received_memory) + 8'h1) :
                   $past(received_memory)))
    );

    // cnt increments only when byte_received is high.
    check_cnt_update: assert property (
        @(posedge clk) disable iff (!rst_n)
        1'b1 |=> (cnt ==
                  ($past(byte_received) ? ($past(cnt) + 8'h1) :
                                          $past(cnt)))
    );

    // cnt and bytecnt move in lockstep.
    check_cnt_matches_bytecnt: assert property (
        @(posedge clk) disable iff (!rst_n)
        (cnt == bytecnt)
    );

    // recived_status sets at 64 and stays set until reset.
    check_recived_status_update: assert property (
        @(posedge clk) disable iff (!rst_n)
        1'b1 |=> (recived_status ==
                  ($past(recived_status) || ($past(received_memory) == 8'd64)))
    );

    // byte_data_sent loads cnt or shifts left on active falling SCK.
    check_byte_data_sent_update: assert property (
        @(posedge clk) disable iff (!rst_n)
        1'b1 |=> (byte_data_sent ==
                  (($past(ssel_active) && $past(sck_fallingedge)) ?
                   (($past(bitcnt) == 3'b000) ? $past(cnt) :
                                                {$past(byte_data_sent[6:0]), 1'b0}) :
                   $past(byte_data_sent)))
    );

    // miso is always the MSB of byte_data_sent.
    check_miso_mapping: assert property (
        @(posedge clk) disable iff (!rst_n)
        (miso == byte_data_sent[7])
    );

endmodule

