module clock_gate (
  input CLK,
  input EN,
  input TE,
  output ENCLK
);

  TLATNTSCAX2TS latch (
    .E(EN),
    .SE(TE),
    .CK(CLK),
    .ECK(ENCLK)
  );

endmodule

module TLATNTSCAX2TS (
  input E,
  input SE,
  input CK,
  output reg ECK
);

  always @(posedge CK)
    if (SE)
      ECK <= E;

endmodule

sva:
module clock_gate_assertions (
    input logic CLK,
    input logic EN,
    input logic TE,
    input logic ENCLK
);

    // TE high captures a high EN into ENCLK.
    check_capture_high: assert property (
        @(posedge CLK) (TE && EN) |=> ENCLK
    );

    // TE high captures a low EN into ENCLK.
    check_capture_low: assert property (
        @(posedge CLK) (TE && !EN) |=> !ENCLK
    );

    // TE low holds ENCLK high.
    check_hold_high_when_te_low: assert property (
        @(posedge CLK) (!TE && ENCLK) |=> ENCLK
    );

    // TE low holds ENCLK low.
    check_hold_low_when_te_low: assert property (
        @(posedge CLK) (!TE && !ENCLK) |=> !ENCLK
    );

    // With TE high, ENCLK matches the prior EN value.
    check_enabled_update_matches_en: assert property (
        @(posedge CLK) TE |=> (ENCLK == $past(EN))
    );

    // With TE low, ENCLK keeps its prior value.
    check_disabled_hold_matches_previous: assert property (
        @(posedge CLK) !TE |=> (ENCLK == $past(ENCLK))
    );

endmodule

rtl:
module final_module(
    input cout_adder, input [2:0] sum_adder,
    input [2:0] out_or_bitwise,
    input out_or_logical,
    input [5:0] out_not,
    output reg [5:0] final_output
);
    wire [2:0] sum_out;

    full_adder fa1(sum_adder[0], out_or_bitwise[0], cout_adder, sum_out[0], );
    full_adder fa2(sum_adder[1], out_or_bitwise[1], , sum_out[1], );
    full_adder fa3(sum_adder[2], out_or_bitwise[2], , sum_out[2], );

    always @(*) begin
        final_output <= sum_out + out_not;
    end
endmodule
module full_adder(
    input a, b, c_in,
    output sum, c_out
);
    assign sum = a ^ b ^ c_in;
    assign c_out = (a & b) | (b & c_in) | (c_in & a);
endmodule

sva:
module final_module_sva(
    input logic        cout_adder,
    input logic [2:0]  sum_adder,
    input logic [2:0]  out_or_bitwise,
    input logic        out_or_logical,
    input logic [5:0]  out_not,
    input logic [5:0]  final_output
);

    // No explicit clock or reset exists in the RTL; this logic is combinational.

    // final_output[0] is the implemented XOR/add result of the bit-0 inputs.
    check_final_output_bit0_function: assert property (
        @($global_clock)
        final_output[0] === (sum_adder[0] ^ out_or_bitwise[0] ^ cout_adder ^ out_not[0])
    );

    // Known bit-0 inputs must produce a known final_output[0].
    check_final_output_bit0_known_when_inputs_known: assert property (
        @($global_clock)
        (!$isunknown({sum_adder[0], out_or_bitwise[0], cout_adder, out_not[0]}))
        |-> (!$isunknown(final_output[0]))
    );

    // With all used inputs stable, the combinational output must stay stable.
    check_used_inputs_stable_keep_output_stable: assert property (
        @($global_clock)
        ($stable(cout_adder) &&
         $stable(sum_adder) &&
         $stable(out_or_bitwise) &&
         $stable(out_not))
        |-> $stable(final_output)
    );

    // final_output[0] depends only on the bit-0 contributors.
    check_output0_depends_only_on_bit0_inputs: assert property (
        @($global_clock)
        ($stable(sum_adder[0]) &&
         $stable(out_or_bitwise[0]) &&
         $stable(cout_adder) &&
         $stable(out_not[0]))
        |-> $stable(final_output[0])
    );

    // out_or_logical is unused and must not affect the output.
    check_out_or_logical_unused: assert property (
        @($global_clock)
        ($changed(out_or_logical) &&
         $stable(cout_adder) &&
         $stable(sum_adder) &&
         $stable(out_or_bitwise) &&
         $stable(out_not))
        |-> $stable(final_output)
    );

    // Toggling sum_adder[0] alone flips final_output[0].
    check_sum_adder0_toggle_flips_output0: assert property (
        @($global_clock)
        ((!$isunknown({$past(sum_adder[0]), sum_adder[0], out_or_bitwise[0], cout_adder, out_not[0]})) &&
         $changed(sum_adder[0]) &&
         $stable(out_or_bitwise[0]) &&
         $stable(cout_adder) &&
         $stable(out_not[0]))
        |-> $changed(final_output[0])
    );

    // Toggling out_or_bitwise[0] alone flips final_output[0].
    check_out_or_bitwise0_toggle_flips_output0: assert property (
        @($global_clock)
        ((!$isunknown({sum_adder[0], $past(out_or_bitwise[0]), out_or_bitwise[0], cout_adder, out_not[0]})) &&
         $stable(sum_adder[0]) &&
         $changed(out_or_bitwise[0]) &&
         $stable(cout_adder) &&
         $stable(out_not[0]))
        |-> $changed(final_output[0])
    );

    // Toggling cout_adder alone flips final_output[0].
    check_cout_adder_toggle_flips_output0: assert property (
        @($global_clock)
        ((!$isunknown({sum_adder[0], out_or_bitwise[0], $past(cout_adder), cout_adder, out_not[0]})) &&
         $stable(sum_adder[0]) &&
         $stable(out_or_bitwise[0]) &&
         $changed(cout_adder) &&
         $stable(out_not[0]))
        |-> $changed(final_output[0])
    );

    // Toggling out_not[0] alone flips final_output[0].
    check_out_not0_toggle_flips_output0: assert property (
        @($global_clock)
        ((!$isunknown({sum_adder[0], out_or_bitwise[0], cout_adder, $past(out_not[0]), out_not[0]})) &&
         $stable(sum_adder[0]) &&
         $stable(out_or_bitwise[0]) &&
         $stable(cout_adder) &&
         $changed(out_not[0]))
        |-> $changed(final_output[0])
    );

endmodule

rtl:
module top_module (
    input [3:0] in,
    input [1:0] ctrl,
    output reg [5:0] out
);

    reg [3:0] shifted;
    reg [1:0] shift_amt;
    reg [3:0] one_count;
    reg [1:0] i;

    // Barrel Shifter
    always @ (in, ctrl) begin
        case (ctrl)
            2'b00: shifted = in << 1;
            2'b01: shifted = in << 2;
            2'b10: shifted = in << 3;
            2'b11: shifted = in << 4;
        endcase
    end

    // One Counter
    always @ (shifted) begin
        one_count = 0;
        for (i = 0; i < 4; i = i + 1) begin
            if (shifted[i] == 1) begin
                one_count = one_count + 1;
            end
        end
    end

    // Output
    always @ (one_count, shifted) begin
        out = one_count + shifted;
    end

endmodule

sva:
module top_module_sva (
    input logic [3:0] in,
    input logic [1:0] ctrl,
    input logic [5:0] out
);

    function automatic logic [3:0] calc_shifted (
        input logic [3:0] in_f,
        input logic [1:0] ctrl_f
    );
        begin
            case (ctrl_f)
                2'b00: calc_shifted = in_f << 1;
                2'b01: calc_shifted = in_f << 2;
                2'b10: calc_shifted = in_f << 3;
                default: calc_shifted = in_f << 4;
            endcase
        end
    endfunction

    function automatic logic [3:0] calc_one_count (
        input logic [3:0] shifted_f
    );
        int idx;
        begin
            calc_one_count = 4'd0;
            for (idx = 0; idx < 4; idx = idx + 1) begin
                if (shifted_f[idx] == 1'b1) begin
                    calc_one_count = calc_one_count + 4'd1;
                end
            end
        end
    endfunction

    function automatic logic [5:0] calc_out (
        input logic [3:0] in_f,
        input logic [1:0] ctrl_f
    );
        logic [3:0] shifted_f;
        logic [3:0] one_count_f;
        begin
            shifted_f   = calc_shifted(in_f, ctrl_f);
            one_count_f = calc_one_count(shifted_f);
            calc_out    = {2'b00, (shifted_f + one_count_f)};
        end
    endfunction

    // No RTL clock or reset; sample the combinational logic on $global_clock.

    // The output must match the RTL's full shift, count, and add function.
    check_full_function: assert property (
        @($global_clock) disable iff (1'b0)
        out == calc_out(in, ctrl)
    );

    // ctrl=00 shifts left by 1 before counting ones and adding.
    check_shift_by1: assert property (
        @($global_clock) disable iff (1'b0)
        (ctrl == 2'b00) |-> (out == {2'b00, ((in << 1) + calc_one_count(in << 1))})
    );

    // ctrl=01 shifts left by 2 before counting ones and adding.
    check_shift_by2: assert property (
        @($global_clock) disable iff (1'b0)
        (ctrl == 2'b01) |-> (out == {2'b00, ((in << 2) + calc_one_count(in << 2))})
    );

    // ctrl=10 shifts left by 3 before counting ones and adding.
    check_shift_by3: assert property (
        @($global_clock) disable iff (1'b0)
        (ctrl == 2'b10) |-> (out == {2'b00, ((in << 3) + calc_one_count(in << 3))})
    );

    // ctrl=11 shifts a 4-bit value left by 4, which forces the output to zero.
    check_shift_by4_zero: assert property (
        @($global_clock) disable iff (1'b0)
        (ctrl == 2'b11) |-> (out == 6'd0)
    );

    // The 4-bit addition result is zero-extended into the 6-bit output.
    check_output_zero_extended: assert property (
        @($global_clock) disable iff (1'b0)
        out[5:4] == 2'b00
    );

    // A zero input must produce a zero output for every control value.
    check_zero_input_zero_output: assert property (
        @($global_clock) disable iff (1'b0)
        (in == 4'b0000) |-> (out == 6'd0)
    );

endmodule

rtl:
module fadder(
  input [WIDTH-1 : 0] a,
  input [WIDTH - 1 : 0] b,
  input sub_enable,
  input carry_in,
  output [WIDTH - 1 : 0] res,
  output carry_out);

  parameter WIDTH = 8;
  wire [WIDTH - 1 : 0] carry;
  wire [WIDTH - 1 : 0] b_in;

  assign carry_out = carry[WIDTH-1];
  assign b_in = sub_enable ? ~(b) : b;

  genvar i;
  generate
    for (i = 0; i < WIDTH; i = i + 1) begin
      if (i == 0) begin
        assign res[i] = (a[i] ^ b_in[i]) ^ carry_in;
        assign carry[i] = ((a[i] ^ b_in[i]) & carry_in) | (a[i] & b_in[i]);
      end else begin
        assign res[i] = (a[i] ^ b_in[i]) ^ carry[i-1];
        assign carry[i] = ((a[i] ^ b_in[i]) & carry[i-1]) | (a[i] & b_in[i]);
      end
    end
  endgenerate

endmodule

sva:
module fadder_sva #(parameter WIDTH = 8) (
    input logic clk,
    input logic [WIDTH-1:0] a,
    input logic [WIDTH-1:0] b,
    input logic sub_enable,
    input logic carry_in,
    input logic [WIDTH-1:0] res,
    input logic carry_out
);

    // Add mode matches a + b + carry_in.
    check_add_mode_full_sum: assert property (
        @(posedge clk)
        !sub_enable |-> ({carry_out, res} == ({1'b0, a} + {1'b0, b} + carry_in))
    );

    // Invert-b mode matches a + ~b + carry_in.
    check_invert_b_mode_full_sum: assert property (
        @(posedge clk)
        sub_enable |-> ({carry_out, res} == ({1'b0, a} + {1'b0, ~b} + carry_in))
    );

    // The LSB sum bit follows the full-adder XOR equation.
    check_lsb_sum_bit: assert property (
        @(posedge clk)
        res[0] == (a[0] ^ (sub_enable ? ~b[0] : b[0]) ^ carry_in)
    );

    // Zero b with no carry passes a through in add mode.
    check_add_zero_b_identity: assert property (
        @(posedge clk)
        !sub_enable && (b == {WIDTH{1'b0}}) && !carry_in |-> ((res == a) && (carry_out == 1'b0))
    );

    // Zero a with no carry passes b through in add mode.
    check_add_zero_a_identity: assert property (
        @(posedge clk)
        !sub_enable && (a == {WIDTH{1'b0}}) && !carry_in |-> ((res == b) && (carry_out == 1'b0))
    );

    // All-ones b plus carry wraps and leaves a in add mode.
    check_add_all_ones_b_wrap: assert property (
        @(posedge clk)
        !sub_enable && (b == {WIDTH{1'b1}}) && carry_in |-> ((res == a) && (carry_out == 1'b1))
    );

    // Equal operands cancel in invert-b mode when carry_in is high.
    check_invert_b_equal_operands_with_carry_cancel: assert property (
        @(posedge clk)
        sub_enable && carry_in && (a == b) |-> ((res == {WIDTH{1'b0}}) && (carry_out == 1'b1))
    );

    // Equal operands produce all ones in invert-b mode when carry_in is low.
    check_invert_b_equal_operands_without_carry_all_ones: assert property (
        @(posedge clk)
        sub_enable && !carry_in && (a == b) |-> ((res == {WIDTH{1'b1}}) && (carry_out == 1'b0))
    );

    // Zero b with carry_in high leaves a unchanged in invert-b mode.
    check_invert_b_zero_b_with_carry_identity: assert property (
        @(posedge clk)
        sub_enable && (b == {WIDTH{1'b0}}) && carry_in |-> ((res == a) && (carry_out == 1'b1))
    );

    // All-ones b with no carry leaves a unchanged in invert-b mode.
    check_invert_b_all_ones_b_without_carry_identity: assert property (
        @(posedge clk)
        sub_enable && (b == {WIDTH{1'b1}}) && !carry_in |-> ((res == a) && (carry_out == 1'b0))
    );

    generate
        if (WIDTH == 1) begin : g_width1
            // For WIDTH=1, carry_out follows the single-bit carry equation.
            check_single_bit_carry_formula: assert property (
                @(posedge clk)
                carry_out == (((a[0] ^ (sub_enable ? ~b[0] : b[0])) & carry_in) |
                              (a[0] & (sub_enable ? ~b[0] : b[0])))
            );
        end
    endgenerate

endmodule

