module clock_gate (
  input CLK,
  input EN,
  input TE,
  output ENCLK
);

  reg gated_clk;

  always @(posedge CLK) begin
    if (EN && !TE) begin
      gated_clk <= 1;
    end else begin
      gated_clk <= 0;
    end
  end

  assign ENCLK = gated_clk;

