rtl:
module Test (
  input clk,
  input [7:0] operand_a,
  input [7:0] operand_b,
  output reg [6:0] out
);

always @(posedge clk) begin
  out <= operand_a + operand_b;
end

endmodule

sva:
module Test_sva (
    input logic clk,
    input logic [7:0] operand_a,
    input logic [7:0] operand_b,
    input logic [6:0] out
);

    // clk is the only clock; the RTL has no reset.
    // out is the registered low 7 bits of operand_a + operand_b.

    // out captures the lower 7 bits of the previous cycle sum.
    check_registered_truncated_sum: assert property (
        @(posedge clk) 1'b1 |=> ({1'b0, out} == (($past(operand_a) + $past(operand_b)) & 8'h7f))
    );

    // Zero plus zero produces zero on the next cycle.
    check_zero_plus_zero: assert property (
        @(posedge clk) (operand_a == 8'h00 && operand_b == 8'h00) |=> (out == 7'h00)
    );

    // A zero operand_a passes operand_b's low 7 bits to out on the next cycle.
    check_zero_a_passthrough: assert property (
        @(posedge clk) (operand_a == 8'h00) |=> ({1'b0, out} == ($past(operand_b) & 8'h7f))
    );

    // A zero operand_b passes operand_a's low 7 bits to out on the next cycle.
    check_zero_b_passthrough: assert property (
        @(posedge clk) (operand_b == 8'h00) |=> ({1'b0, out} == ($past(operand_a) & 8'h7f))
    );

    // Stable inputs across cycles keep the registered output stable on the following cycle.
    check_stable_inputs_hold_output: assert property (
        @(posedge clk) ($stable(operand_a) && $stable(operand_b)) |=> $stable(out)
    );

    // out[0] is the XOR of the previous cycle operand LSBs.
    check_lsb_xor: assert property (
        @(posedge clk) 1'b1 |=> (out[0] == ($past(operand_a[0]) ^ $past(operand_b[0])))
    );

    // When the previous 8-bit sum has bit 7 clear, out matches that full 8-bit sum.
    check_sum_without_bit7_matches_out: assert property (
        @(posedge clk) (((operand_a + operand_b) & 8'h80) == 8'h00) |=> ({1'b0, out} == ($past(operand_a) + $past(operand_b)))
    );

    // When the previous 8-bit sum has bit 7 set, out drops that bit on the next cycle.
    check_sum_with_bit7_drops_msb: assert property (
        @(posedge clk) (((operand_a + operand_b) & 8'h80) == 8'h80) |=> ({1'b0, out} == (($past(operand_a) + $past(operand_b)) - 8'h80))
    );

endmodule

module lcd_driver_sva #(
    parameter int n = 8
)(
    input logic       clk,
    input logic [7:0] ascii,
    input logic [n-1:0] seg
);

generate
if (n >= 8) begin : gen_lcd_driver_checks

    // seg[0] matches the ASCII decode for segment a.
    check_seg_a_decode: assert property (
        @(posedge clk)
        seg[0] == (ascii == 8'h41 || ascii == 8'h61 || ascii == 8'hC1 || ascii == 8'hE1)
    );

    // seg[1] matches the ASCII decode for segment b.
    check_seg_b_decode: assert property (
        @(posedge clk)
        seg[1] == (ascii == 8'h42 || ascii == 8'h62 || ascii == 8'hC2 || ascii == 8'hE2)
    );

    // seg[2] matches the ASCII decode for segment c.
    check_seg_c_decode: assert property (
        @(posedge clk)
        seg[2] == (ascii == 8'h43 || ascii == 8'h63 || ascii == 8'hC3 || ascii == 8'hE3)
    );

    // seg[3] matches the ASCII decode for segment d.
    check_seg_d_decode: assert property (
        @(posedge clk)
        seg[3] == (ascii == 8'h44 || ascii == 8'h64 || ascii == 8'hC4 || ascii == 8'hE4)
    );

    // seg[4] matches the ASCII decode for segment e.
    check_seg_e_decode: assert property (
        @(posedge clk)
        seg[4] == (ascii == 8'h45 || ascii == 8'h65 || ascii == 8'hC5 || ascii == 8'hE5)
    );

    // seg[5] matches the ASCII decode for segment f.
    check_seg_f_decode: assert property (
        @(posedge clk)
        seg[5] == (ascii == 8'h46 || ascii == 8'h66 || ascii == 8'hC6 || ascii == 8'hE6)
    );

    // seg[6] matches the ASCII decode for segment g.
    check_seg_g_decode: assert property (
        @(posedge clk)
        seg[6] == (ascii == 8'h47 || ascii == 8'h67 || ascii == 8'hC7 || ascii == 8'hE7)
    );

    // seg[7] is asserted only for space.
    check_seg_space_decode: assert property (
        @(posedge clk)
        seg[7] == (ascii == 8'h20)
    );

    // The decoded segment outputs are mutually exclusive.
    check_segment_outputs_onehot0: assert property (
        @(posedge clk)
        $onehot0(seg[7:0])
    );

    // Unsupported ASCII values clear all defined segment outputs.
    check_unmapped_ascii_clears_segments: assert property (
        @(posedge clk)
        !(
            ascii == 8'h41 || ascii == 8'h61 || ascii == 8'hC1 || ascii == 8'hE1 ||
            ascii == 8'h42 || ascii == 8'h62 || ascii == 8'hC2 || ascii == 8'hE2 ||
            ascii == 8'h43 || ascii == 8'h63 || ascii == 8'hC3 || ascii == 8'hE3 ||
            ascii == 8'h44 || ascii == 8'h64 || ascii == 8'hC4 || ascii == 8'hE4 ||
            ascii == 8'h45 || ascii == 8'h65 || ascii == 8'hC5 || ascii == 8'hE5 ||
            ascii == 8'h46 || ascii == 8'h66 || ascii == 8'hC6 || ascii == 8'hE6 ||
            ascii == 8'h47 || ascii == 8'h67 || ascii == 8'hC7 || ascii == 8'hE7 ||
            ascii == 8'h20
        ) |-> (seg[7:0] == 8'b0000_0000)
    );

end
endgenerate

endmodule

rtl:
module nand_gate (
    Z,
    A,
    B
);

    output Z;
    input A;
    input B;

    assign Z = ~(A & B);

endmodule

sva:
module nand_gate_sva (
    input logic A,
    input logic B,
    input logic Z
);

    // Z always equals the NAND of A and B.
    check_nand_function: assert property (
        @($global_clock) Z == ~(A & B)
    );

    // If both inputs are high, Z must be low.
    check_both_high_drive_low: assert property (
        @($global_clock) ((A == 1'b1) && (B == 1'b1)) |-> (Z == 1'b0)
    );

    // If A is low, Z must be high.
    check_a_low_drive_high: assert property (
        @($global_clock) (A == 1'b0) |-> (Z == 1'b1)
    );

    // If B is low, Z must be high.
    check_b_low_drive_high: assert property (
        @($global_clock) (B == 1'b0) |-> (Z == 1'b1)
    );

endmodule

rtl:
module top_module (
    input wire clk,
    input wire reset,
    input wire [1023:0] in,
    input wire [2:0] sel,
    input wire [2:0] vec,
    output wire [3:0] out,
    output wire o2,
    output wire o1,
    output wire o0 );

    wire [3:0] mux_out;
    wire [3:0] shifter_out;

    // 256-to-1 Multiplexer
    mux_256to1 mux_inst (
        .in(in),
        .sel(sel),
        .out(mux_out)
    );

    // Barrel Shifter
    barrel_shifter bs_inst (
        .in(mux_out),
        .vec(vec),
        .out(shifter_out),
        .o0(o0),
        .o1(o1),
        .o2(o2)
    );

    // Functional Module
    function_module func_inst (
        .mux_out(mux_out),
        .shifter_out(shifter_out),
        .vec(vec),
        .out(out)
    );

endmodule

module mux_256to1 (
    input wire [1023:0] in,
    input wire [2:0] sel,
    output wire [3:0] out );

    assign out = in[sel*4 +: 4];

endmodule

module barrel_shifter (
    input wire [3:0] in,
    input wire [2:0] vec,
    output wire [3:0] out,
    output wire o0,
    output wire o1,
    output wire o2 );

    wire [3:0] shift_1, shift_2, shift_3;

    assign shift_1 = {in[2:0], 1'b0};
    assign shift_2 = {in[1:0], 2'b00};
    assign shift_3 = {1'b0, in[0], 2'b00};

    assign out = (vec == 3'b000) ? in :
                 (vec == 3'b001) ? shift_1 :
                 (vec == 3'b010) ? shift_2 :
                 (vec == 3'b011) ? shift_3 :
                 4'b0000;

    assign o0 = in[0];
    assign o1 = in[1];
    assign o2 = in[2];

endmodule

module function_module (
    input wire [3:0] mux_out,
    input wire [3:0] shifter_out,
    input wire [2:0] vec,
    output wire [3:0] out );

    assign out = (vec == 3'b000) ? mux_out : shifter_out;

endmodule

sva:
module top_module_assertions (
    input logic clk,
    input logic reset,
    input logic [1023:0] in,
    input logic [2:0] sel,
    input logic [2:0] vec,
    input logic [3:0] out,
    input logic o2,
    input logic o1,
    input logic o0
);

    // o0 reflects bit 0 of the selected 4-bit slice.
    check_o0_selected_bit: assert property (
        @(posedge clk) disable iff (reset)
        o0 == in[{sel, 2'b00}]
    );

    // o1 reflects bit 1 of the selected 4-bit slice.
    check_o1_selected_bit: assert property (
        @(posedge clk) disable iff (reset)
        o1 == in[{sel, 2'b00} + 1]
    );

    // o2 reflects bit 2 of the selected 4-bit slice.
    check_o2_selected_bit: assert property (
        @(posedge clk) disable iff (reset)
        o2 == in[{sel, 2'b00} + 2]
    );

    // vec=000 passes the selected 4-bit slice directly to out.
    check_out_passthrough_vec_000: assert property (
        @(posedge clk) disable iff (reset)
        (vec == 3'b000) |-> (out == in[{sel, 2'b00} +: 4])
    );

    // vec=001 produces the implemented shift_1 pattern.
    check_out_shift_vec_001: assert property (
        @(posedge clk) disable iff (reset)
        (vec == 3'b001) |-> (out == {o2, o1, o0, 1'b0})
    );

    // vec=010 produces the implemented shift_2 pattern.
    check_out_shift_vec_010: assert property (
        @(posedge clk) disable iff (reset)
        (vec == 3'b010) |-> (out == {o1, o0, 2'b00})
    );

    // vec=011 produces the implemented shift_3 pattern.
    check_out_shift_vec_011: assert property (
        @(posedge clk) disable iff (reset)
        (vec == 3'b011) |-> (out == {1'b0, o0, 2'b00})
    );

    // vec values with bit 2 set force out to zero.
    check_out_zero_for_vec_1xx: assert property (
        @(posedge clk) disable iff (reset)
        vec[2] |-> (out == 4'b0000)
    );

endmodule

rtl:
module adder (
   // Inputs
   clk,
   in0,
   in1,
   // Outputs
   out
   );
   input clk;
   input [7:0] in0;
   input [7:0] in1;
   output reg [15:0] out;

   always @ (posedge clk) begin
      out <= in0 + in1;
      if (out === 16'hfffe) begin
         out <= 0;
      end
   end

endmodule

sva:
module adder_assertions (
    input logic        clk,
    input logic [7:0]  in0,
    input logic [7:0]  in1,
    input logic [15:0] out
);

    // A previous out of 16'hfffe forces the next registered out to zero.
    check_fffe_forces_zero: assert property (
        @(posedge clk) disable iff ($initstate)
        ($past(out) === 16'hfffe) |-> (out === 16'h0000)
    );

    // Otherwise, the next low byte of out is the previous cycle's truncated input sum.
    check_registered_low_byte_sum: assert property (
        @(posedge clk) disable iff ($initstate)
        ($past(out) !== 16'hfffe) |-> ({1'b0, out[7:0]} === (({1'b0, $past(in0)} + {1'b0, $past(in1)}) & 9'h0ff))
    );

    // After the first clocked update, the upper byte of out is always zero.
    check_upper_byte_zero: assert property (
        @(posedge clk) disable iff ($initstate)
        out[15:8] === 8'h00
    );

endmodule

rtl:
module fsm_vending_machine (
  input clk,
  input reset,
  input coin_inserted,
  input [1:0] item_selected,
  input item_dispensed,
  output reg dispense_item,
  output reg return_coin
);

  // Define the states
  parameter IDLE = 2'b00;
  parameter ITEM_SELECTED = 2'b01;
  parameter ITEM_DISPENSED = 2'b10;

  // Define the current state
  reg [1:0] state;

  // Define the next state
  reg [1:0] next_state;

  // Define the state transition logic
  always @ (posedge clk, posedge reset) begin
    if (reset) begin
      state <= IDLE;
    end else begin
      state <= next_state;
    end
  end

  // Define the state output logic
  always @ (state, coin_inserted, item_selected, item_dispensed) begin
    case (state)
      IDLE: begin
        dispense_item <= 0;
        return_coin <= 0;
        if (coin_inserted && item_selected != 2'b00) begin
          next_state <= ITEM_SELECTED;
        end else begin
          next_state <= IDLE;
        end
      end
      ITEM_SELECTED: begin
        dispense_item <= 1;
        return_coin <= 0;
        if (item_dispensed) begin
          next_state <= ITEM_DISPENSED;
        end else begin
          next_state <= ITEM_SELECTED;
        end
      end
      ITEM_DISPENSED: begin
        dispense_item <= 0;
        return_coin <= 1;
        next_state <= IDLE;
      end
      default: begin
        dispense_item <= 0;
        return_coin <= 0;
        next_state <= IDLE;
      end
    endcase
  end

endmodule

sva:
module fsm_vending_machine_sva (
    input logic clk,
    input logic reset,
    input logic coin_inserted,
    input logic [1:0] item_selected,
    input logic item_dispensed,
    input logic dispense_item,
    input logic return_coin,
    input logic [1:0] state
);

    localparam [1:0] IDLE            = 2'b00;
    localparam [1:0] ITEM_SELECTED   = 2'b01;
    localparam [1:0] ITEM_DISPENSED  = 2'b10;

    // Reset holds the FSM in IDLE.
    check_reset_forces_idle: assert property (
        @(posedge clk) reset |-> (state == IDLE)
    );

    // Reset clears both outputs.
    check_reset_clears_outputs: assert property (
        @(posedge clk) reset |-> (!dispense_item && !return_coin)
    );

    // IDLE drives both outputs low.
    check_idle_outputs_low: assert property (
        @(posedge clk) disable iff (reset)
        (state == IDLE) |-> (!dispense_item && !return_coin)
    );

    // A valid coin and selection moves IDLE to ITEM_SELECTED.
    check_idle_advances_on_valid_request: assert property (
        @(posedge clk) disable iff (reset)
        (state == IDLE && coin_inserted && (item_selected != 2'b00)) |=> (state == ITEM_SELECTED)
    );

    // Without a valid request, IDLE remains IDLE.
    check_idle_stays_without_valid_request: assert property (
        @(posedge clk) disable iff (reset)
        (state == IDLE && !(coin_inserted && (item_selected != 2'b00))) |=> (state == IDLE)
    );

    // ITEM_SELECTED asserts dispense_item and deasserts return_coin.
    check_selected_outputs: assert property (
        @(posedge clk) disable iff (reset)
        (state == ITEM_SELECTED) |-> (dispense_item && !return_coin)
    );

    // dispense_item only occurs in ITEM_SELECTED.
    check_dispense_implies_selected_state: assert property (
        @(posedge clk) disable iff (reset)
        dispense_item |-> (state == ITEM_SELECTED)
    );

    // ITEM_SELECTED holds until item_dispensed is asserted.
    check_selected_holds_until_dispensed: assert property (
        @(posedge clk) disable iff (reset)
        (state == ITEM_SELECTED && !item_dispensed) |=> (state == ITEM_SELECTED)
    );

    // item_dispensed advances ITEM_SELECTED to ITEM_DISPENSED.
    check_selected_advances_when_dispensed: assert property (
        @(posedge clk) disable iff (reset)
        (state == ITEM_SELECTED && item_dispensed) |=> (state == ITEM_DISPENSED)
    );

    // ITEM_DISPENSED deasserts dispense_item and asserts return_coin.
    check_dispensed_outputs: assert property (
        @(posedge clk) disable iff (reset)
        (state == ITEM_DISPENSED) |-> (!dispense_item && return_coin)
    );

    // return_coin only occurs in ITEM_DISPENSED.
    check_return_implies_dispensed_state: assert property (
        @(posedge clk) disable iff (reset)
        return_coin |-> (state == ITEM_DISPENSED)
    );

    // ITEM_DISPENSED always returns to IDLE on the next cycle.
    check_dispensed_returns_to_idle: assert property (
        @(posedge clk) disable iff (reset)
        (state == ITEM_DISPENSED) |=> (state == IDLE)
    );

    // An invalid state drives safe outputs.
    check_invalid_state_outputs_safe: assert property (
        @(posedge clk) disable iff (reset)
        !(state inside {IDLE, ITEM_SELECTED, ITEM_DISPENSED}) |-> (!dispense_item && !return_coin)
    );

    // An invalid state recovers to IDLE on the next cycle.
    check_invalid_state_recovers_to_idle: assert property (
        @(posedge clk) disable iff (reset)
        !(state inside {IDLE, ITEM_SELECTED, ITEM_DISPENSED}) |=> (state == IDLE)
    );

endmodule

rtl:
module shift_comp (
    input clk,
    input reset,
    input [15:0] serial_in,
    input shift_direction,
    output [15:0] serial_out,
    output final_output
);

    // Define the 16-bit shift register module
    reg [15:0] shift_reg;
    always @(posedge clk) begin
        if (reset) begin
            shift_reg <= 16'b0;
        end else begin
            if (shift_direction) begin
                shift_reg <= {shift_reg[14:0], serial_in[0]};
            end else begin
                shift_reg <= {serial_in[15], shift_reg[15:1]};
            end
        end
    end
    assign serial_out = shift_reg;

    // Define the 4-bit magnitude comparator module
    reg [3:0] constant = 4'b1010;
    wire equal, greater;

    comparator comparator0 (
        .a(shift_reg[3:0]),
        .b(constant),
        .equal(equal),
        .greater(greater)
    );

    assign final_output = equal | greater;

endmodule

module comparator (
    input [3:0] a,
    input [3:0] b,
    output equal,
    output greater
);
    assign equal = (a == b);
    assign greater = (a > b);
endmodule

sva:
module shift_comp_sva (
    input logic        clk,
    input logic        reset,
    input logic [15:0] serial_in,
    input logic        shift_direction,
    input logic [15:0] serial_out,
    input logic        final_output
);

    // Reset clears the shift register output on the following clock.
    check_reset_clears_serial_out: assert property (
        @(posedge clk) reset |=> (serial_out == 16'b0)
    );

    // Reset drives the comparator-based output low on the following clock.
    check_reset_clears_final_output: assert property (
        @(posedge clk) reset |=> (final_output == 1'b0)
    );

    // shift_direction high shifts toward MSB and loads serial_in[0] into bit 0.
    check_shift_left_update: assert property (
        @(posedge clk) disable iff (reset)
        shift_direction |=> (serial_out == { $past(serial_out[14:0]), $past(serial_in[0]) })
    );

    // shift_direction low shifts toward LSB and loads serial_in[15] into bit 15.
    check_shift_right_update: assert property (
        @(posedge clk) disable iff (reset)
        !shift_direction |=> (serial_out == { $past(serial_in[15]), $past(serial_out[15:1]) })
    );

    // A low nibble equal to 4'b1010 makes final_output high.
    check_final_output_equal_case: assert property (
        @(posedge clk) disable iff (reset)
        (serial_out[3:0] == 4'b1010) |-> (final_output == 1'b1)
    );

    // A low nibble greater than 4'b1010 makes final_output high.
    check_final_output_greater_case: assert property (
        @(posedge clk) disable iff (reset)
        (serial_out[3:0] > 4'b1010) |-> (final_output == 1'b1)
    );

    // A low nibble less than 4'b1010 makes final_output low.
    check_final_output_less_case: assert property (
        @(posedge clk) disable iff (reset)
        (serial_out[3:0] < 4'b1010) |-> (final_output == 1'b0)
    );

endmodule

rtl:
module top_module (
    input clk,
    input rst,
    input [7:0] d1,
    input [7:0] d2,
    input sel,
    output reg [7:0] q,
    output reg [7:0] sum
);

reg [7:0] d_ff;

// 2-to-1 multiplexer
always @* begin
    d_ff = sel ? d2 : d1;
end

// 8 D flip-flops
always @(posedge clk or posedge rst) begin
    if (rst) begin
        q <= 8'h0;
    end
    else begin
        q <= d_ff;
    end
end

// Additive functional module
always @* begin
    sum <= d1 + d2;
end

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic rst,
    input logic [7:0] d1,
    input logic [7:0] d2,
    input logic sel,
    input logic [7:0] q,
    input logic [7:0] sum
);

    // sum reflects the combinational addition of d1 and d2.
    check_sum_matches_addition: assert property (
        @(posedge clk) disable iff (rst)
            sum == (d1 + d2)
    );

    // sum does not depend on sel.
    check_sum_independent_of_sel: assert property (
        @(posedge clk) disable iff (rst)
            $changed(sel) && $stable(d1) && $stable(d2) |-> $stable(sum)
    );

    // With sel low, q captures d1 on the next clock.
    check_q_captures_d1_when_sel_low: assert property (
        @(posedge clk) disable iff (rst)
            !sel |=> (q == $past(d1))
    );

    // With sel high, q captures d2 on the next clock.
    check_q_captures_d2_when_sel_high: assert property (
        @(posedge clk) disable iff (rst)
            sel |=> (q == $past(d2))
    );

    // If reset stays asserted across clocks, q remains zero.
    check_q_zero_while_reset_held: assert property (
        @(posedge clk)
            rst && $past(rst) |-> (q == 8'h00)
    );

    // On the first clock after reset deasserts, q is still zero.
    check_q_zero_on_reset_release: assert property (
        @(posedge clk) disable iff (rst)
            $fell(rst) |-> (q == 8'h00)
    );

endmodule

rtl:
module dff_asr (
    input  D,
    input  CLK,
    input  SET_B,
    input  RESET_B,
    output Q,
    output Q_N
);

    reg  Q;
    assign Q_N = ~Q;

    always @(posedge CLK) begin
        if (!SET_B) begin
            Q <= 1'b1;
        end else if (!RESET_B) begin
            Q <= 1'b0;
        end else begin
            Q <= D;
        end
    end

endmodule

sva:
module dff_asr_sva (
    input logic D,
    input logic CLK,
    input logic SET_B,
    input logic RESET_B,
    input logic Q,
    input logic Q_N
);

    // Q_N is the complement of Q when reset is inactive.
    check_qn_inverse: assert property (
        @(posedge CLK) disable iff (!RESET_B) (Q_N == ~Q)
    );

    // Active-low set drives Q high.
    check_set_forces_q_high: assert property (
        @(posedge CLK) (!SET_B) |=> (Q == 1'b1)
    );

    // Active-low set drives Q_N low.
    check_set_forces_qn_low: assert property (
        @(posedge CLK) (!SET_B) |=> (Q_N == 1'b0)
    );

    // Active-low reset drives Q low when set is inactive.
    check_reset_forces_q_low: assert property (
        @(posedge CLK) (SET_B && !RESET_B) |=> (Q == 1'b0)
    );

    // Active-low reset drives Q_N high when set is inactive.
    check_reset_forces_qn_high: assert property (
        @(posedge CLK) (SET_B && !RESET_B) |=> (Q_N == 1'b1)
    );

    // Set has priority when set and reset are both low.
    check_set_priority_over_reset: assert property (
        @(posedge CLK) (!SET_B && !RESET_B) |=> (Q == 1'b1)
    );

    // With set and reset inactive, Q captures D.
    check_data_capture: assert property (
        @(posedge CLK) (SET_B && RESET_B) |=> (Q == $past(D))
    );

    // With set and reset inactive, Q_N reflects the inverse of D.
    check_data_capture_qn: assert property (
        @(posedge CLK) (SET_B && RESET_B) |=> (Q_N == ~$past(D))
    );

endmodule

rtl:
module addsub8 (
    input [7:0] A,
    input [7:0] B,
    input add,
    input sub,
    output [7:0] Z
);

    reg [7:0] temp;

    always @(*) begin
        if (add) begin
            temp = A + B;
        end
        else if (sub) begin
            temp = A - B;
        end
        else begin
            temp = 8'b0;
        end
    end

    assign Z = temp;

endmodule

sva:
module addsub8_sva (
    input logic [7:0] A,
    input logic [7:0] B,
    input logic add,
    input logic sub,
    input logic [7:0] Z
);

    // Z always matches the RTL's selected arithmetic function.
    check_selected_function: assert property (
        @($global_clock) Z == (add ? (A + B) : (sub ? (A - B) : 8'b0))
    );

    // When add is asserted, Z is the sum of A and B.
    check_add_result: assert property (
        @($global_clock) add |-> (Z == (A + B))
    );

    // When only sub is asserted, Z is the difference A minus B.
    check_sub_result: assert property (
        @($global_clock) (!add && sub) |-> (Z == (A - B))
    );

    // When neither operation is selected, Z is zero.
    check_zero_when_no_op: assert property (
        @($global_clock) (!add && !sub) |-> (Z == 8'b0)
    );

    // When both controls are high, add has priority over sub.
    check_add_priority: assert property (
        @($global_clock) (add && sub) |-> (Z == (A + B))
    );

endmodule

rtl:
module barrel_shifter_alu (
    input [3:0] A,
    input [3:0] B,
    input dir,
    input [2:0] op,
    output [3:0] S
);

    // Barrel Shifter
    wire [3:0] shifted_value;
    assign shifted_value = (dir) ? {A[2:0], 1'b0} : {1'b0, A[3:1]};

    // ALU
    wire [3:0] alu_result;
    assign alu_result = (op == 3'b000) ? (A + shifted_value) :
                        (op == 3'b001) ? (A - shifted_value) :
                        (op == 3'b010) ? (A & shifted_value) :
                        (op == 3'b011) ? (A | shifted_value) :
                        (op == 3'b100) ? (A ^ shifted_value) :
                        (op == 3'b101) ? (shifted_value << 1) :
                        4'b0;

    // Output
    assign S = alu_result;

endmodule

sva:
module barrel_shifter_alu_sva (
    input logic        clk,
    input logic [3:0]  A,
    input logic [3:0]  B,
    input logic        dir,
    input logic [2:0]  op,
    input logic [3:0]  S
);

    // S must match the full barrel-shifter ALU function.
    check_output_matches_rtl: assert property (
        @(posedge clk) disable iff ($initstate)
        S == (
            (op == 3'b000) ? (A + (dir ? {A[2:0], 1'b0} : {1'b0, A[3:1]})) :
            (op == 3'b001) ? (A - (dir ? {A[2:0], 1'b0} : {1'b0, A[3:1]})) :
            (op == 3'b010) ? (A & (dir ? {A[2:0], 1'b0} : {1'b0, A[3:1]})) :
            (op == 3'b011) ? (A | (dir ? {A[2:0], 1'b0} : {1'b0, A[3:1]})) :
            (op == 3'b100) ? (A ^ (dir ? {A[2:0], 1'b0} : {1'b0, A[3:1]})) :
            (op == 3'b101) ? ((dir ? {A[2:0], 1'b0} : {1'b0, A[3:1]}) << 1) :
                             4'b0000
        )
    );

    // op 000 must add A and the shifted A value.
    check_add_operation: assert property (
        @(posedge clk) disable iff ($initstate)
        (op == 3'b000) |-> (S == (A + (dir ? {A[2:0], 1'b0} : {1'b0, A[3:1]})))
    );

    // op 001 must subtract the shifted A value from A.
    check_sub_operation: assert property (
        @(posedge clk) disable iff ($initstate)
        (op == 3'b001) |-> (S == (A - (dir ? {A[2:0], 1'b0} : {1'b0, A[3:1]})))
    );

    // op 010 must bitwise AND A with the shifted A value.
    check_and_operation: assert property (
        @(posedge clk) disable iff ($initstate)
        (op == 3'b010) |-> (S == (A & (dir ? {A[2:0], 1'b0} : {1'b0, A[3:1]})))
    );

    // op 011 must bitwise OR A with the shifted A value.
    check_or_operation: assert property (
        @(posedge clk) disable iff ($initstate)
        (op == 3'b011) |-> (S == (A | (dir ? {A[2:0], 1'b0} : {1'b0, A[3:1]})))
    );

    // op 100 must bitwise XOR A with the shifted A value.
    check_xor_operation: assert property (
        @(posedge clk) disable iff ($initstate)
        (op == 3'b100) |-> (S == (A ^ (dir ? {A[2:0], 1'b0} : {1'b0, A[3:1]})))
    );

    // op 101 must left shift the shifted A value once more.
    check_shift_twice_operation: assert property (
        @(posedge clk) disable iff ($initstate)
        (op == 3'b101) |-> (S == ((dir ? {A[2:0], 1'b0} : {1'b0, A[3:1]}) << 1))
    );

    // Unsupported opcodes must drive S to zero.
    check_default_zero_operation: assert property (
        @(posedge clk) disable iff ($initstate)
        ((op == 3'b110) || (op == 3'b111)) |-> (S == 4'b0000)
    );

    // The shift opcode with dir high must produce A shifted left by two.
    check_shift_opcode_left_dir: assert property (
        @(posedge clk) disable iff ($initstate)
        ((op == 3'b101) && dir) |-> (S == {A[1:0], 2'b00})
    );

    // The shift opcode with dir low must produce the RTL right-then-left result.
    check_shift_opcode_right_dir: assert property (
        @(posedge clk) disable iff ($initstate)
        ((op == 3'b101) && !dir) |-> (S == {A[3:1], 1'b0})
    );

    // B is unused, so changing only B must not change S.
    check_b_unused: assert property (
        @(posedge clk) disable iff ($initstate)
        ($changed(B) && $stable(A) && $stable(dir) && $stable(op)) |-> $stable(S)
    );

endmodule

rtl:
module sky130_fd_sc_hs__nand4(
    input A,
    input B,
    input C,
    input D,
    input VPWR,
    input VGND,
    output Y
);

    // Create internal signals
    wire nand1;
    wire nand2;
    wire nand3;

    // Implement NAND gate
    assign nand1 = ~(A & B);
    assign nand2 = ~(C & D);
    assign nand3 = ~(nand1 & nand2);
    assign Y = nand3;

endmodule

sva:
module sky130_fd_sc_hs__nand4_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic VPWR,
    input logic VGND,
    input logic Y
);

    // Y matches the implemented two-stage NAND expression.
    check_y_matches_implemented_logic: assert property (
        @(posedge clk) disable iff (1'b0)
        Y == ~(~(A & B) & ~(C & D))
    );

    // A and B both high force Y high.
    check_ab_pair_forces_high: assert property (
        @(posedge clk) disable iff (1'b0)
        (A & B) |-> Y
    );

    // C and D both high force Y high.
    check_cd_pair_forces_high: assert property (
        @(posedge clk) disable iff (1'b0)
        (C & D) |-> Y
    );

    // If neither input pair is fully high, Y is low.
    check_no_active_pair_forces_low: assert property (
        @(posedge clk) disable iff (1'b0)
        (!(A & B) && !(C & D)) |-> !Y
    );

    // Y can only be high when at least one input pair is fully high.
    check_y_high_requires_active_pair: assert property (
        @(posedge clk) disable iff (1'b0)
        Y |-> ((A & B) || (C & D))
    );

endmodule

