rtl:
module add_sub_shift (
    input [3:0] in0,
    input [3:0] in1,
    input SUB,
    input [1:0] SHIFT,
    input select,
    output reg [3:0] Y
);

    wire [3:0] add_sub_out;
    wire [3:0] shift_out;

    add_sub add_sub_inst (
        .in0(in0),
        .in1(in1),
        .SUB(SUB),
        .Y(add_sub_out)
    );

    barrel_shifter barrel_shifter_inst (
        .in(add_sub_out),
        .SHIFT(SHIFT),
        .Y(shift_out)
    );

    always @(*) begin
        if (select) begin
            Y <= shift_out;
        end else begin
            Y <= add_sub_out;
        end
    end

endmodule

module add_sub (
    input [3:0] in0,
    input [3:0] in1,
    input SUB,
    output reg [3:0] Y
);

    always @(*) begin
        if (SUB) begin
            Y <= in0 - in1;
        end else begin
            Y <= in0 + in1;
        end
    end

endmodule

module barrel_shifter (
    input [3:0] in,
    input [1:0] SHIFT,
    output [3:0] Y
);

    assign Y = (SHIFT[1]) ? (in >> SHIFT) : (in << SHIFT);

endmodule

sva:
module add_sub_shift_assertions (
    input logic clk,
    input logic [3:0] in0,
    input logic [3:0] in1,
    input logic SUB,
    input logic [1:0] SHIFT,
    input logic select,
    input logic [3:0] Y
);

    // No DUT clock or reset; assertions are sampled on external clk.

    // The top output must match the full add/sub, shift, and select behavior.
    check_top_function: assert property (
        @(posedge clk)
        Y == (
            select
                ? (SHIFT[1]
                    ? (((SUB ? (in0 - in1) : (in0 + in1)) >> SHIFT))
                    : (((SUB ? (in0 - in1) : (in0 + in1)) << SHIFT)))
                : (SUB ? (in0 - in1) : (in0 + in1))
        )
    );

    // When select is low and SUB is low, Y must be the 4-bit sum.
    check_bypass_add: assert property (
        @(posedge clk)
        (!select && !SUB) |-> (Y == (in0 + in1))
    );

    // When select is low and SUB is high, Y must be the 4-bit difference.
    check_bypass_sub: assert property (
        @(posedge clk)
        (!select && SUB) |-> (Y == (in0 - in1))
    );

    // When select is high and SHIFT[1] is low, Y must be the left-shifted add/sub result.
    check_selected_left_shift: assert property (
        @(posedge clk)
        (select && !SHIFT[1]) |-> (Y == ((SUB ? (in0 - in1) : (in0 + in1)) << SHIFT))
    );

    // When select is high and SHIFT[1] is high, Y must be the right-shifted add/sub result.
    check_selected_right_shift: assert property (
        @(posedge clk)
        (select && SHIFT[1]) |-> (Y == ((SUB ? (in0 - in1) : (in0 + in1)) >> SHIFT))
    );

    // A selected zero shift must leave the add/sub result unchanged.
    check_zero_shift_identity: assert property (
        @(posedge clk)
        (select && (SHIFT == 2'b00)) |-> (Y == (SUB ? (in0 - in1) : (in0 + in1)))
    );

    // If all inputs are stable, the combinational output must stay stable.
    check_stable_inputs_stable_output: assert property (
        @(posedge clk)
        $stable({in0, in1, SUB, SHIFT, select}) |-> $stable(Y)
    );

    // SHIFT changes must not affect Y while the unshifted path is selected.
    check_shift_ignored_when_bypassed: assert property (
        @(posedge clk)
        (!select && $stable({in0, in1, SUB, select}) && !$stable(SHIFT)) |-> $stable(Y)
    );

endmodule

rtl:
module adder4bit (A, B, Cin, CK, S, Cout);
input [3:0] A;
input [3:0] B;
input Cin;
input CK;
output [3:0] S;
output Cout;

reg [3:0] S;
reg Cout;

always @(posedge CK) begin
    {Cout, S} <= A + B + Cin;
end

endmodule

sva:
module adder4bit_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic       Cin,
    input logic       CK,
    input logic [3:0] S,
    input logic       Cout
);

    // CK is the only clock and the RTL has no reset.

    // Outputs equal the previous cycle's 5-bit sum.
    check_registered_sum: assert property (
        @(posedge CK) 1'b1 |=> ({Cout, S} == ({1'b0, $past(A)} + {1'b0, $past(B)} + $past(Cin)))
    );

    // Sum bits match the low 4 bits of the previous addition.
    check_sum_bits_match: assert property (
        @(posedge CK) 1'b1 |=> ({1'b0, S} == (({1'b0, $past(A)} + {1'b0, $past(B)} + $past(Cin)) & 5'h0F))
    );

    // Carry-out matches overflow from the previous addition.
    check_carry_bit_match: assert property (
        @(posedge CK) 1'b1 |=> (Cout == (({1'b0, $past(A)} + {1'b0, $past(B)} + $past(Cin)) > 5'h0F))
    );

    // Stable inputs across cycles keep the registered output stable.
    check_stable_inputs_hold_output: assert property (
        @(posedge CK) $stable({A, B, Cin}) |=> $stable({Cout, S})
    );

    // All-zero inputs produce an all-zero registered result.
    check_zero_inputs_produce_zero: assert property (
        @(posedge CK) (A == 4'h0 && B == 4'h0 && Cin == 1'b0) |=> ({Cout, S} == 5'h00)
    );

    // Maximum inputs produce the full-scale registered result.
    check_max_inputs_produce_full_scale: assert property (
        @(posedge CK) (A == 4'hF && B == 4'hF && Cin == 1'b1) |=> ({Cout, S} == 5'h1F)
    );

    // With B and Cin zero, the registered result passes A through.
    check_pass_through_a_when_b_and_cin_zero: assert property (
        @(posedge CK) (B == 4'h0 && Cin == 1'b0) |=> ({Cout, S} == {1'b0, $past(A)})
    );

    // With A and Cin zero, the registered result passes B through.
    check_pass_through_b_when_a_and_cin_zero: assert property (
        @(posedge CK) (A == 4'h0 && Cin == 1'b0) |=> ({Cout, S} == {1'b0, $past(B)})
    );

endmodule

rtl:
module and4_module (
    output X,
    input A,
    input B,
    input C,
    input D
);

    wire A_N;

    and4 and4_instance (
        .X(X),
        .a(A),
        .b(B),
        .c(C),
        .d(D)
    );

    assign A_N = ~A;

endmodule

module and4 (
    output X,
    input a,
    input b,
    input c,
    input d
);

    assign X = a & b & c & d;

endmodule

sva:
module and4_module_sva (
    input logic clk,
    input logic X,
    input logic A,
    input logic B,
    input logic C,
    input logic D
);

    // X must equal the AND of all four inputs.
    check_output_matches_and: assert property (
        @(posedge clk) X == (A & B & C & D)
    );

    // All HIGH inputs must drive X HIGH.
    check_all_inputs_high_drive_x_high: assert property (
        @(posedge clk) (A && B && C && D) |-> (X == 1'b1)
    );

    // A LOW input must drive X LOW.
    check_a_low_forces_x_low: assert property (
        @(posedge clk) (!A) |-> (X == 1'b0)
    );

    // B LOW input must drive X LOW.
    check_b_low_forces_x_low: assert property (
        @(posedge clk) (!B) |-> (X == 1'b0)
    );

    // C LOW input must drive X LOW.
    check_c_low_forces_x_low: assert property (
        @(posedge clk) (!C) |-> (X == 1'b0)
    );

    // D LOW input must drive X LOW.
    check_d_low_forces_x_low: assert property (
        @(posedge clk) (!D) |-> (X == 1'b0)
    );

    // X HIGH requires all inputs HIGH.
    check_x_high_requires_all_inputs_high: assert property (
        @(posedge clk) X |-> (A && B && C && D)
    );

    // Stable inputs must keep X stable.
    check_stable_inputs_keep_x_stable: assert property (
        @(posedge clk) $stable({A, B, C, D}) |-> $stable(X)
    );

endmodule

rtl:
module register_module (
  input clk,
  output reg [3:0] A,
  output reg [3:0] B,
  output reg [3:0] C
);

  initial begin
    A = 0;
    B = 0;
    C = 0;
  end

  always @(posedge clk) begin
    #2 A = A + 1;
    #3 B = B - 1;
  end

  always @(A or B) begin
    C = A + B;
  end

endmodule

sva:
module register_module_assertions (
    input logic       clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] C
);

    // Outputs start at zero from the initial block.
    check_initial_outputs_zero: assert property (
        @(posedge clk) $initstate |-> (A == 4'd0) && (B == 4'd0) && (C == 4'd0)
    );

    // A increments by one on each clock.
    check_a_increments_each_cycle: assert property (
        @(posedge clk) 1'b1 |=> (A == ($past(A) + 4'd1))
    );

    // B decrements by one on each clock.
    check_b_decrements_each_cycle: assert property (
        @(posedge clk) 1'b1 |=> (B == ($past(B) - 4'd1))
    );

    // C always reflects the sum of A and B.
    check_c_matches_sum: assert property (
        @(posedge clk) C == (A + B)
    );

    // The combined A+B value is preserved from cycle to cycle.
    check_sum_preserved_each_cycle: assert property (
        @(posedge clk) 1'b1 |=> ((A + B) == ($past(A) + $past(B)))
    );

endmodule

module var12_multi_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic E,
    input logic F,
    input logic G,
    input logic H,
    input logic I,
    input logic J,
    input logic K,
    input logic L,
    input logic valid
);

    wire [7:0] min_value;
    wire [7:0] max_weight;
    wire [7:0] max_volume;
    wire [7:0] total_value;
    wire [7:0] total_weight;
    wire [7:0] total_volume;

    assign min_value = 8'd107;
    assign max_weight = 8'd60;
    assign max_volume = 8'd60;

    assign total_value =
            A * 8'd4
          + B * 8'd8
          + C * 8'd0
          + D * 8'd20
          + E * 8'd10
          + F * 8'd12
          + G * 8'd18
          + H * 8'd14
          + I * 8'd6
          + J * 8'd15
          + K * 8'd30
          + L * 8'd8;

    assign total_weight =
            A * 8'd28
          + B * 8'd8
          + C * 8'd27
          + D * 8'd18
          + E * 8'd27
          + F * 8'd28
          + G * 8'd6
          + H * 8'd1
          + I * 8'd20
          + J * 8'd0
          + K * 8'd5
          + L * 8'd13;

    assign total_volume =
            A * 8'd27
          + B * 8'd27
          + C * 8'd4
          + D * 8'd4
          + E * 8'd0
          + F * 8'd24
          + G * 8'd4
          + H * 8'd20
          + I * 8'd12
          + J * 8'd15
          + K * 8'd5
          + L * 8'd2;

    // valid must match the RTL threshold expression.
    check_valid_definition: assert property (
        @(posedge clk)
        valid == ((total_value >= min_value) && (total_weight <= max_weight) && (total_volume <= max_volume))
    );

    // A valid result must meet the minimum value threshold.
    check_valid_requires_min_value: assert property (
        @(posedge clk)
        valid |-> (total_value >= min_value)
    );

    // A valid result must stay within the weight limit.
    check_valid_requires_weight_limit: assert property (
        @(posedge clk)
        valid |-> (total_weight <= max_weight)
    );

    // A valid result must stay within the volume limit.
    check_valid_requires_volume_limit: assert property (
        @(posedge clk)
        valid |-> (total_volume <= max_volume)
    );

    // An invalid result must violate at least one threshold.
    check_invalid_has_failing_constraint: assert property (
        @(posedge clk)
        (!valid) |-> ((total_value < min_value) || (total_weight > max_weight) || (total_volume > max_volume))
    );

    // Too little value must force valid low.
    check_low_value_forces_valid_low: assert property (
        @(posedge clk)
        (total_value < min_value) |-> (!valid)
    );

    // Too much weight must force valid low.
    check_overweight_forces_valid_low: assert property (
        @(posedge clk)
        (total_weight > max_weight) |-> (!valid)
    );

    // Too much volume must force valid low.
    check_overvolume_forces_valid_low: assert property (
        @(posedge clk)
        (total_volume > max_volume) |-> (!valid)
    );

    // Selecting no items must produce an invalid result.
    check_empty_selection_invalid: assert property (
        @(posedge clk)
        (!A && !B && !C && !D && !E && !F && !G && !H && !I && !J && !K && !L) |-> (!valid)
    );

    // A known threshold-meeting selection must produce a valid result.
    check_known_feasible_selection_valid: assert property (
        @(posedge clk)
        (!A && !B && !C && D && E && !F && G && H && !I && J && K && !L) |-> valid
    );

endmodule

rtl:
module barrel_shifter (
    input [3:0] A,
    input [1:0] S,
    input D,
    output reg [3:0] B
);

    reg [3:0] shift_reg;

    always @(*) begin
        case(S)
            2'b00: shift_reg = A;
            2'b01: shift_reg = {A[2:0], A[3]};
            2'b10: shift_reg = {A[1:0], A[3:2]};
            2'b11: shift_reg = {A[0], A[3:1]};
        endcase

        if(D == 1) begin
            B <= shift_reg >> S;
        end else begin
            B <= shift_reg << S;
        end
    end

endmodule

sva:
module barrel_shifter_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [1:0] S,
    input logic D,
    input logic [3:0] B
);

    // RTL is combinational; clk is an external sampling clock.
    // There is no reset in the DUT.

    // S=00 passes A directly to B.
    check_passthrough_when_s0: assert property (
        @(posedge clk)
        (S == 2'b00) |-> (B == A)
    );

    // D=1 and S=01 rotate then shift right by 1.
    check_right_path_when_s1: assert property (
        @(posedge clk)
        ((D == 1'b1) && (S == 2'b01)) |-> (B == {1'b0, A[2:0]})
    );

    // D=1 and S=10 rotate then shift right by 2.
    check_right_path_when_s2: assert property (
        @(posedge clk)
        ((D == 1'b1) && (S == 2'b10)) |-> (B == {2'b00, A[1:0]})
    );

    // D=1 and S=11 rotate then shift right by 3.
    check_right_path_when_s3: assert property (
        @(posedge clk)
        ((D == 1'b1) && (S == 2'b11)) |-> (B == {3'b000, A[0]})
    );

    // D=0 and S=01 rotate then shift left by 1.
    check_left_path_when_s1: assert property (
        @(posedge clk)
        ((D == 1'b0) && (S == 2'b01)) |-> (B == {A[1:0], A[3], 1'b0})
    );

    // D=0 and S=10 rotate then shift left by 2.
    check_left_path_when_s2: assert property (
        @(posedge clk)
        ((D == 1'b0) && (S == 2'b10)) |-> (B == {A[3:2], 2'b00})
    );

    // D=0 and S=11 rotate then shift left by 3.
    check_left_path_when_s3: assert property (
        @(posedge clk)
        ((D == 1'b0) && (S == 2'b11)) |-> (B == {A[1], 3'b000})
    );

endmodule

module cycloneive_dffe_sva (
    input logic D,
    input logic CLK,
    input logic ENA,
    input logic CLRN,
    input logic PRN,
    input logic Q
);

    // Active-low clear must force Q low when sampled low.
    check_clear_forces_q_low: assert property (
        @(posedge CLK) !CLRN |-> (Q == 1'b0)
    );

    // A sampled rise on Q must come from an enabled set or a captured 1.
    check_q_rise_requires_enabled_source: assert property (
        @(posedge CLK) disable iff (!CLRN || $initstate)
        $rose(Q) |-> ($past(CLRN) && $past(ENA) && ($past(PRN) || $past(D)))
    );

    // If Q rises without PRN set, the previous cycle must have captured D=1.
    check_q_rise_without_prn_requires_d_high: assert property (
        @(posedge CLK) disable iff (!CLRN || $initstate)
        ($rose(Q) && !$past(PRN)) |-> ($past(CLRN) && $past(ENA) && $past(D))
    );

    // If Q rises while previous D was 0, the rise must have come from PRN.
    check_q_rise_with_d_low_requires_prn_high: assert property (
        @(posedge CLK) disable iff (!CLRN || $initstate)
        ($rose(Q) && !$past(D)) |-> ($past(CLRN) && $past(ENA) && $past(PRN))
    );

    // Any sampled high Q must have a valid previous-cycle source.
    check_q_high_has_valid_previous_source: assert property (
        @(posedge CLK) disable iff (!CLRN || $initstate)
        Q |-> (
            $past(CLRN) &&
            (
                (!$past(ENA) && $past(Q)) ||
                ($past(ENA) && $past(PRN)) ||
                ($past(ENA) && !$past(PRN) && $past(D))
            )
        )
    );

endmodule

rtl:
module butterfly_4(
                clk,
				        rst,

                i_0,
                i_1,
                i_2,
                i_3,

                o_0,
                o_1,
                o_2,
                o_3
);

input                    clk;
input                    rst;

input     signed  [23:0] i_0;
input     signed  [23:0] i_1;
input     signed  [23:0] i_2;
input     signed  [23:0] i_3;

output reg signed [24:0] o_0;
output reg signed [24:0] o_1;
output reg signed [24:0] o_2;
output reg signed [24:0] o_3;

wire  signed [24:0]   b_0;
wire  signed [24:0]   b_1;
wire  signed [24:0]   b_2;
wire  signed [24:0]   b_3;

assign b_0=i_0+i_3;
assign b_1=i_1+i_2;
assign b_2=i_1-i_2;               
assign b_3=i_0-i_3;

always@(posedge clk or negedge rst)
if(!rst)
     begin
     o_0<=25'b0;
     o_1<=25'b0;
     o_2<=25'b0;
     o_3<=25'b0;
     end
else
     begin
     o_0<=b_0;
     o_1<=b_1;
     o_2<=b_2;
     o_3<=b_3;
     end

endmodule

sva:
module butterfly_4_sva (
    input logic clk,
    input logic rst,
    input logic signed [23:0] i_0,
    input logic signed [23:0] i_1,
    input logic signed [23:0] i_2,
    input logic signed [23:0] i_3,
    input logic signed [24:0] o_0,
    input logic signed [24:0] o_1,
    input logic signed [24:0] o_2,
    input logic signed [24:0] o_3
);

    // Outputs are zero whenever reset is asserted low.
    check_reset_clears_outputs: assert property (
        @(posedge clk)
        !rst |-> ((o_0 == 25'sd0) && (o_1 == 25'sd0) && (o_2 == 25'sd0) && (o_3 == 25'sd0))
    );

    // A sampled reset-low cycle leaves outputs at zero at the next sample.
    check_reset_holds_zero_to_next_sample: assert property (
        @(posedge clk)
        !rst |=> ((o_0 == 25'sd0) && (o_1 == 25'sd0) && (o_2 == 25'sd0) && (o_3 == 25'sd0))
    );

    // o_0 registers the previous-cycle i_0 + i_3 value.
    check_o0_registers_b0: assert property (
        @(posedge clk) disable iff (!rst)
        $past(rst) |-> (o_0 == $past(i_0 + i_3))
    );

    // o_1 registers the previous-cycle i_1 + i_2 value.
    check_o1_registers_b1: assert property (
        @(posedge clk) disable iff (!rst)
        $past(rst) |-> (o_1 == $past(i_1 + i_2))
    );

    // o_2 registers the previous-cycle i_1 - i_2 value.
    check_o2_registers_b2: assert property (
        @(posedge clk) disable iff (!rst)
        $past(rst) |-> (o_2 == $past(i_1 - i_2))
    );

    // o_3 registers the previous-cycle i_0 - i_3 value.
    check_o3_registers_b3: assert property (
        @(posedge clk) disable iff (!rst)
        $past(rst) |-> (o_3 == $past(i_0 - i_3))
    );

endmodule

rtl:
module fourbitmuxcase(in, s, out);
	input wire[3: 0] in;
	input wire[1: 0] s;
	output wire out;
	reg _out;
	always @(in or s)
		case (s)
			2'b00: _out = in[0];
			2'b01: _out = in[1];
			2'b10: _out = in[2];
			2'b11: _out = in[3];
			default: _out = 1'b0;
		endcase
	assign out = _out;
endmodule

sva:
module fourbitmuxcase_sva (
    input logic clk,
    input logic [3:0] in,
    input logic [1:0] s,
    input logic out
);

    // Output matches the mux truth table.
    check_mux_function: assert property (
        @(posedge clk)
        out == ((s == 2'b00) ? in[0] :
                (s == 2'b01) ? in[1] :
                (s == 2'b10) ? in[2] : in[3])
    );

    // Select 00 routes in[0] to out.
    check_sel_00: assert property (
        @(posedge clk)
        (s == 2'b00) |-> (out == in[0])
    );

    // Select 01 routes in[1] to out.
    check_sel_01: assert property (
        @(posedge clk)
        (s == 2'b01) |-> (out == in[1])
    );

    // Select 10 routes in[2] to out.
    check_sel_10: assert property (
        @(posedge clk)
        (s == 2'b10) |-> (out == in[2])
    );

    // Select 11 routes in[3] to out.
    check_sel_11: assert property (
        @(posedge clk)
        (s == 2'b11) |-> (out == in[3])
    );

    // If inputs are stable, output remains stable.
    check_output_stable_when_inputs_stable: assert property (
        @(posedge clk)
        ($stable(in) && $stable(s)) |-> $stable(out)
    );

endmodule

module IRDA_RECEIVE_Terasic_sva (
    input logic        iCLK,
    input logic        iRST_n,
    input logic        iIRDA,
    input logic        iREAD,
    input logic        oDATA_REAY,
    input logic [31:0] oDATA,
    input logic        DATA_REAY,
    input logic [17:0] idle_count,
    input logic        idle_count_flag,
    input logic [17:0] state_count,
    input logic        state_count_flag,
    input logic [17:0] data_count,
    input logic        data_count_flag,
    input logic [5:0]  bitcount,
    input logic [1:0]  state,
    input logic [31:0] DATA,
    input logic [31:0] DATA_BUF
);

    localparam logic [1:0] IDLE      = 2'b00;
    localparam logic [1:0] GUIDANCE  = 2'b01;
    localparam logic [1:0] DATAREAD  = 2'b10;

    localparam logic [17:0] IDLE_HIGH_DUR     = 18'd262143;
    localparam logic [17:0] GUIDE_LOW_DUR     = 18'd230000;
    localparam logic [17:0] GUIDE_HIGH_DUR    = 18'd210000;
    localparam logic [17:0] DATA_HIGH_DUR     = 18'd41500;
    localparam logic [17:0] BIT_AVAILABLE_DUR = 18'd20000;

    // Reset returns the registered control state and counters to their cleared values.
    reset_values_check: assert property (
        @(posedge iCLK)
        !iRST_n |=> ((idle_count == 18'd0) &&
                     (idle_count_flag == 1'b0) &&
                     (state_count == 18'd0) &&
                     (state_count_flag == 1'b0) &&
                     (data_count == 18'd0) &&
                     (data_count_flag == 1'b0) &&
                     (bitcount == 6'd0) &&
                     (state == IDLE) &&
                     (DATA == 32'd0) &&
                     (DATA_REAY == 1'b0) &&
                     (oDATA == 32'd0))
    );

    // The output ready port mirrors the internal ready register.
    ready_output_mirror_check: assert property (
        @(posedge iCLK) disable iff (!iRST_n)
        (oDATA_REAY == DATA_REAY)
    );

    // idle_count_flag is asserted after an IDLE cycle with iIRDA low.
    idle_flag_set_check: assert property (
        @(posedge iCLK) disable iff (!iRST_n)
        ((state == IDLE) && !iIRDA) |=> idle_count_flag
    );

    // idle_count_flag is cleared after any cycle that is not IDLE with iIRDA low.
    idle_flag_clear_check: assert property (
        @(posedge iCLK) disable iff (!iRST_n)
        !((state == IDLE) && !iIRDA) |=> !idle_count_flag
    );

    // idle_count increments when its enable flag is high.
    idle_count_increment_check: assert property (
        @(posedge iCLK) disable iff (!iRST_n)
        idle_count_flag |=> (idle_count == ($past(idle_count) + 18'd1))
    );

    // idle_count clears when its enable flag is low.
    idle_count_clear_check: assert property (
        @(posedge iCLK) disable iff (!iRST_n)
        !idle_count_flag |=> (idle_count == 18'd0)
    );

    // state_count_flag is asserted after a GUIDANCE cycle with iIRDA high.
    guidance_flag_set_check: assert property (
        @(posedge iCLK) disable iff (!iRST_n)
        ((state == GUIDANCE) && iIRDA) |=> state_count_flag
    );

    // state_count_flag is cleared outside GUIDANCE with iIRDA high.
    guidance_flag_clear_check: assert property (
        @(posedge iCLK) disable iff (!iRST_n)
        !((state == GUIDANCE) && iIRDA) |=> !state_count_flag
    );

    // state_count increments when its enable flag is high.
    state_count_increment_check: assert property (
        @(posedge iCLK) disable iff (!iRST_n)
        state_count_flag |=> (state_count == ($past(state_count) + 18'd1))
    );

    // state_count clears when its enable flag is low.
    state_count_clear_check: assert property (
        @(posedge iCLK) disable iff (!iRST_n)
        !state_count_flag |=> (state_count == 18'd0)
    );

    // IDLE moves to GUIDANCE once the low duration threshold is exceeded.
    idle_to_guidance_check: assert property (
        @(posedge iCLK) disable iff (!iRST_n)
        ((state == IDLE) && (idle_count > GUIDE_LOW_DUR)) |=> (state == GUIDANCE)
    );

    // IDLE remains IDLE while the low duration threshold is not exceeded.
    idle_hold_check: assert property (
        @(posedge iCLK) disable iff (!iRST_n)
        ((state == IDLE) && (idle_count <= GUIDE_LOW_DUR)) |=> (state == IDLE)
    );

    // GUIDANCE moves to DATAREAD once the high duration threshold is exceeded.
    guidance_to_dataread_check: assert property (
        @(posedge iCLK) disable iff (!iRST_n)
        ((state == GUIDANCE) && (state_count > GUIDE_HIGH_DUR)) |=> (state == DATAREAD)
    );

    // GUIDANCE holds until the high duration threshold is exceeded.
    guidance_hold_check: assert property (
        @(posedge iCLK) disable iff (!iRST_n)
        ((state == GUIDANCE) && (state_count <= GUIDE_HIGH_DUR)) |=> (state == GUIDANCE)
    );

    // DATAREAD returns to IDLE on long inactivity or after bitcount reaches 33 or more.
    dataread_to_idle_check: assert property (
        @(posedge iCLK) disable iff (!iRST_n)
        ((state == DATAREAD) && ((data_count >= IDLE_HIGH_DUR) || (bitcount >= 6'd33))) |=> (state == IDLE)
    );

    // DATAREAD holds while neither exit condition is met.
    dataread_hold_check: assert property (
        @(posedge iCLK) disable iff (!iRST_n)
        ((state == DATAREAD) && (data_count < IDLE_HIGH_DUR) && (bitcount < 6'd33)) |=> (state == DATAREAD)
    );

    // Any illegal state encoding returns to IDLE.
    illegal_state_return_check: assert property (
        @(posedge iCLK) disable iff (!iRST_n)
        (state == 2'b11) |=> (state == IDLE)
    );

    // data_count_flag is asserted after a DATAREAD cycle with iIRDA high.
    data_flag_set_check: assert property (
        @(posedge iCLK) disable iff (!iRST_n)
        ((state == DATAREAD) && iIRDA) |=> data_count_flag
    );

    // data_count_flag is cleared outside DATAREAD with iIRDA high.
    data_flag_clear_check: assert property (
        @(posedge iCLK) disable iff (!iRST_n)
        !((state == DATAREAD) && iIRDA) |=> !data_count_flag
    );

    // data_count increments when its enable flag is high.
    data_count_increment_check: assert property (
        @(posedge iCLK) disable iff (!iRST_n)
        data_count_flag |=> (data_count == ($past(data_count) + 18'd1))
    );

    // data_count clears when its enable flag is low.
    data_count_clear_check: assert property (
        @(posedge iCLK) disable iff (!iRST_n)
        !data_count_flag |=> (data_count == 18'd0)
    );

    // bitcount resets whenever the current state is not DATAREAD.
    bitcount_reset_outside_dataread_check: assert property (
        @(posedge iCLK) disable iff (!iRST_n)
        (state != DATAREAD) |=> (bitcount == 6'd0)
    );

    // bitcount increments when data_count hits the bit-available duration in DATAREAD.
    bitcount_increment_check: assert property (
        @(posedge iCLK) disable iff (!iRST_n)
        ((state == DATAREAD) && (data_count == BIT_AVAILABLE_DUR)) |=> (bitcount == ($past(bitcount) + 6'd1))
    );

    // bitcount holds in DATAREAD when the bit-available duration is not hit.
    bitcount_hold_check: assert property (
        @(posedge iCLK) disable iff (!iRST_n)
        ((state == DATAREAD) && (data_count != BIT_AVAILABLE_DUR)) |=> (bitcount == $past(bitcount))
    );

    // DATA clears whenever the current state is not DATAREAD.
    data_clear_outside_dataread_check: assert property (
        @(posedge iCLK) disable iff (!iRST_n)
        (state != DATAREAD) |=> (DATA == 32'd0)
    );

    // A valid complemented header at bitcount 32 captures DATA into DATA_BUF and raises ready.
    ready_set_check: assert property (
        @(posedge iCLK) disable iff (!iRST_n)
        ((bitcount == 6'd32) && (DATA[31:24] == (~DATA[23:16]))) |=> (DATA_REAY && (DATA_BUF == $past(DATA)))
    );

    // Ready clears whenever the valid complemented header condition is not met.
    ready_clear_check: assert property (
        @(posedge iCLK) disable iff (!iRST_n)
        !((bitcount == 6'd32) && (DATA[31:24] == (~DATA[23:16]))) |=> !DATA_REAY
    );

    // oDATA loads DATA_BUF when read is requested while ready is high.
    odata_load_check: assert property (
        @(posedge iCLK) disable iff (!iRST_n)
        (iREAD && DATA_REAY) |=> (oDATA == $past(DATA_BUF))
    );

    // oDATA holds its previous value when no read-ready handshake occurs.
    odata_hold_check: assert property (
        @(posedge iCLK) disable iff (!iRST_n)
        !(iREAD && DATA_REAY) |=> (oDATA == $past(oDATA))
    );

endmodule

rtl:
module sky130_fd_sc_hdll__nor4b (
    Y  ,
    A  ,
    B  ,
    C  ,
    D_N
);

    output Y  ;
    input  A  ;
    input  B  ;
    input  C  ;
    input  D_N;

    wire not0_out  ;
    wire nor0_out_Y;

    not not0 (not0_out  , D_N              );
    nor nor0 (nor0_out_Y, A, B, C, not0_out);
    buf buf0 (Y         , nor0_out_Y       );

endmodule

sva:
module sky130_fd_sc_hdll__nor4b_sva (
    input logic clk,
    input logic Y,
    input logic A,
    input logic B,
    input logic C,
    input logic D_N
);

    // Y implements the NOR4-with-inverted-D function.
    check_y_matches_function: assert property (
        @(posedge clk) Y == (!A && !B && !C && D_N)
    );

    // A asserted forces the NOR output low.
    check_a_high_forces_y_low: assert property (
        @(posedge clk) A |-> !Y
    );

    // B asserted forces the NOR output low.
    check_b_high_forces_y_low: assert property (
        @(posedge clk) B |-> !Y
    );

    // C asserted forces the NOR output low.
    check_c_high_forces_y_low: assert property (
        @(posedge clk) C |-> !Y
    );

    // D_N low makes the inverted D input high and forces Y low.
    check_dn_low_forces_y_low: assert property (
        @(posedge clk) !D_N |-> !Y
    );

    // Y high requires all three direct inputs low and D_N high.
    check_y_high_only_for_all_clear: assert property (
        @(posedge clk) Y |-> (!A && !B && !C && D_N)
    );

    // When all three direct inputs are low and D_N is high, Y is high.
    check_all_clear_drives_y_high: assert property (
        @(posedge clk) (!A && !B && !C && D_N) |-> Y
    );

endmodule

rtl:
module sky130_fd_sc_ms__nor3 (
    Y,
    A,
    B,
    C
);

    output Y;
    input  A;
    input  B;
    input  C;

    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    wire nor0_out_Y;

    nor nor0 (nor0_out_Y, C, A, B        );
    buf buf0 (Y         , nor0_out_Y     );

endmodule

sva:
module sky130_fd_sc_ms__nor3_sva (
    input logic Y,
    input logic A,
    input logic B,
    input logic C
);

    // Combinational NOR3 cell with no RTL clock or reset; sample on $global_clock.

    // Y must always equal the 3-input NOR of A, B, and C.
    check_output_matches_nor3_function: assert property (
        @($global_clock) (Y === ~(A | B | C))
    );

    // A asserted high forces Y low.
    check_a_high_forces_y_low: assert property (
        @($global_clock) (A === 1'b1) |-> (Y === 1'b0)
    );

    // B asserted high forces Y low.
    check_b_high_forces_y_low: assert property (
        @($global_clock) (B === 1'b1) |-> (Y === 1'b0)
    );

    // C asserted high forces Y low.
    check_c_high_forces_y_low: assert property (
        @($global_clock) (C === 1'b1) |-> (Y === 1'b0)
    );

    // All inputs low produce a high output.
    check_all_inputs_low_produces_y_high: assert property (
        @($global_clock) ((A === 1'b0) && (B === 1'b0) && (C === 1'b0)) |-> (Y === 1'b1)
    );

    // A high output means all three inputs are low.
    check_y_high_requires_all_inputs_low: assert property (
        @($global_clock) (Y === 1'b1) |-> ((A === 1'b0) && (B === 1'b0) && (C === 1'b0))
    );

endmodule

module my_clock_gate_sva (
    input logic clk,
    input logic en,
    input logic te,
    input logic enclk
);

    // enclk updates according to the registered enable/te equation.
    check_enclk_next_state: assert property (
        @(posedge clk) 1'b1 |=> (enclk == ($past(en) ? $past(te) : $past(enclk)))
    );

    // An enabled cycle with te high drives enclk high on the next clock.
    check_enclk_set_when_enabled_and_te_high: assert property (
        @(posedge clk) en && te |=> enclk
    );

    // An enabled cycle with te low drives enclk low on the next clock.
    check_enclk_clear_when_enabled_and_te_low: assert property (
        @(posedge clk) en && !te |=> !enclk
    );

    // A disabled cycle leaves enclk unchanged.
    check_enclk_holds_when_disabled: assert property (
        @(posedge clk) !en |=> $stable(enclk)
    );

endmodule

rtl:
module mux4to1 (
    input A0,
    input A1,
    input A2,
    input A3,
    input [1:0] S,
    output X
);

wire [1:0] notS;
assign notS = ~S;

wire w1, w2, w3, w4;
assign w1 = A0 & notS[1] & notS[0];
assign w2 = A1 & notS[1] & S[0];
assign w3 = A2 & S[1] & notS[0];
assign w4 = A3 & S[1] & S[0];

assign X = w1 | w2 | w3 | w4;

endmodule

sva:
module mux4to1_sva (
    input logic clk,
    input logic A0,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic [1:0] S,
    input logic X
);

    // X matches the RTL sum-of-products mux equation.
    check_mux_sum_of_products: assert property (
        @(posedge clk)
        X == ((A0 & ~S[1] & ~S[0]) |
              (A1 & ~S[1] &  S[0]) |
              (A2 &  S[1] & ~S[0]) |
              (A3 &  S[1] &  S[0]))
    );

    // When S is 00, X routes A0.
    check_sel_00_routes_a0: assert property (
        @(posedge clk) (S == 2'b00) |-> (X == A0)
    );

    // When S is 01, X routes A1.
    check_sel_01_routes_a1: assert property (
        @(posedge clk) (S == 2'b01) |-> (X == A1)
    );

    // When S is 10, X routes A2.
    check_sel_10_routes_a2: assert property (
        @(posedge clk) (S == 2'b10) |-> (X == A2)
    );

    // When S is 11, X routes A3.
    check_sel_11_routes_a3: assert property (
        @(posedge clk) (S == 2'b11) |-> (X == A3)
    );

endmodule

rtl:
module xor_8bit (
    input [7:0] A,
    input [7:0] B,
    output [7:0] Z
);

    assign Z = A ^ B;

endmodule

sva:
module xor_8bit_sva (
    input logic [7:0] A,
    input logic [7:0] B,
    input logic [7:0] Z
);

    // Z must always equal A XOR B.
    check_xor_function: assert property (
        @($global_clock) Z == (A ^ B)
    );

    // Bit 0 of Z must be A[0] XOR B[0].
    check_bit0_xor: assert property (
        @($global_clock) Z[0] == (A[0] ^ B[0])
    );

    // Bit 1 of Z must be A[1] XOR B[1].
    check_bit1_xor: assert property (
        @($global_clock) Z[1] == (A[1] ^ B[1])
    );

    // Bit 2 of Z must be A[2] XOR B[2].
    check_bit2_xor: assert property (
        @($global_clock) Z[2] == (A[2] ^ B[2])
    );

    // Bit 3 of Z must be A[3] XOR B[3].
    check_bit3_xor: assert property (
        @($global_clock) Z[3] == (A[3] ^ B[3])
    );

    // Bit 4 of Z must be A[4] XOR B[4].
    check_bit4_xor: assert property (
        @($global_clock) Z[4] == (A[4] ^ B[4])
    );

    // Bit 5 of Z must be A[5] XOR B[5].
    check_bit5_xor: assert property (
        @($global_clock) Z[5] == (A[5] ^ B[5])
    );

    // Bit 6 of Z must be A[6] XOR B[6].
    check_bit6_xor: assert property (
        @($global_clock) Z[6] == (A[6] ^ B[6])
    );

    // Bit 7 of Z must be A[7] XOR B[7].
    check_bit7_xor: assert property (
        @($global_clock) Z[7] == (A[7] ^ B[7])
    );

    // Equal inputs must produce zero.
    check_equal_inputs_zero: assert property (
        @($global_clock) (A == B) |-> (Z == 8'h00)
    );

    // Zero on A must pass B through to Z.
    check_a_zero_passthrough: assert property (
        @($global_clock) (A == 8'h00) |-> (Z == B)
    );

    // Zero on B must pass A through to Z.
    check_b_zero_passthrough: assert property (
        @($global_clock) (B == 8'h00) |-> (Z == A)
    );

    // All ones on A must invert B.
    check_a_all_ones_inverts_b: assert property (
        @($global_clock) (A == 8'hFF) |-> (Z == ~B)
    );

    // All ones on B must invert A.
    check_b_all_ones_inverts_a: assert property (
        @($global_clock) (B == 8'hFF) |-> (Z == ~A)
    );

endmodule

rtl:
module FULL_ADDER (A, B, CIN, S, COUT);
  input A, B, CIN;
  output S, COUT;

  wire x1, x2, x3, x4;

  assign x1 = A ^ B;
  assign x2 = x1 ^ CIN;
  assign x3 = A & B;
  assign x4 = CIN & x1;

  assign S = x2;
  assign COUT = x3 | x4;

endmodule

sva:
module FULL_ADDER_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic CIN,
    input logic S,
    input logic COUT
);

    // Sum output matches the XOR of the three inputs.
    check_sum_function: assert property (
        @(posedge clk) S == (A ^ B ^ CIN)
    );

    // Carry output matches the implemented generate/propagate logic.
    check_cout_function: assert property (
        @(posedge clk) COUT == ((A & B) | (CIN & (A ^ B)))
    );

    // All-zero inputs produce zero sum and zero carry.
    check_all_zero_case: assert property (
        @(posedge clk) (!A && !B && !CIN) |-> (!S && !COUT)
    );

    // Any one-hot input combination produces sum only.
    check_one_hot_case: assert property (
        @(posedge clk) $onehot({A, B, CIN}) |-> (S && !COUT)
    );

    // Any two-high input combination produces carry only.
    check_two_high_case: assert property (
        @(posedge clk) ((A && B && !CIN) || (A && CIN && !B) || (B && CIN && !A)) |-> (!S && COUT)
    );

    // All-high inputs produce both sum and carry.
    check_all_high_case: assert property (
        @(posedge clk) (A && B && CIN) |-> (S && COUT)
    );

endmodule

rtl:
module mux_2to1 (
    input a,
    input b,
    input sel,
    output reg out
);

always @ (sel or a or b) begin
    out = sel ? b : a;
end

endmodule
module top_module(
    input a,
    input b,
    input sel_b1,
    input sel_b2,
    output reg out_always
);

wire sel = (sel_b1 & sel_b2);

mux_2to1 mux (
    .a(a),
    .b(b),
    .sel(sel),
    .out(out_always)
);

endmodule

sva:
module top_module_sva (
    input logic a,
    input logic b,
    input logic sel_b1,
    input logic sel_b2,
    input logic out_always
);

    // When both select bits are high, the output must select b.
    check_output_selects_b_for_sel_11: assert property (
        @($global_clock) (sel_b1 && sel_b2) |-> (out_always == b)
    );

    // When sel_b1 is high and sel_b2 is low, the output must select a.
    check_output_selects_a_for_sel_10: assert property (
        @($global_clock) (sel_b1 && !sel_b2) |-> (out_always == a)
    );

    // When sel_b1 is low and sel_b2 is high, the output must select a.
    check_output_selects_a_for_sel_01: assert property (
        @($global_clock) (!sel_b1 && sel_b2) |-> (out_always == a)
    );

    // When both select bits are low, the output must select a.
    check_output_selects_a_for_sel_00: assert property (
        @($global_clock) (!sel_b1 && !sel_b2) |-> (out_always == a)
    );

    // The output must match the implemented AND-gated 2:1 mux equation.
    check_output_matches_mux_equation: assert property (
        @($global_clock) out_always == ((sel_b1 & sel_b2) ? b : a)
    );

endmodule

rtl:
module DEMUX (
  input in,
  input [m-1:0] sel, 
  output [2**m-1:0] out
);

parameter m = 3; // number of select bits

assign out[0] = sel == 0 ? in : 0; // Route input to out1 if sel is 0

// Use a loop to route input to the correct output based on sel
genvar i;
generate 
  for (i = 1; i < 2**m; i = i + 1) begin : ROUTE_OUTPUT
    assign out[i] = sel == i ? in : 0;
  end
endgenerate

endmodule

sva:
module DEMUX_sva #(parameter int m = 3) (
    input logic in,
    input logic [m-1:0] sel,
    input logic [(2**m)-1:0] out
);

    localparam int OUT_W = 2**m;
    genvar i;

    // No clock exists in the RTL; sample on the formal global clock.
    // No reset exists in the RTL.
    // The DUT is purely combinational.

    generate
        for (i = 0; i < OUT_W; i = i + 1) begin : gen_route_checks
            // The selected output bit mirrors the input.
            check_selected_route: assert property (
                @($global_clock) (sel == i) |-> (out[i] == in)
            );

            // Any unselected output bit remains low.
            check_unselected_low: assert property (
                @($global_clock) (sel != i) |-> (out[i] == 1'b0)
            );
        end
    endgenerate

    // A low input forces all outputs low.
    check_zero_input_clears_outputs: assert property (
        @($global_clock) (in == 1'b0) |-> (out == '0)
    );

    // A high input produces exactly one asserted output bit.
    check_high_input_onehot: assert property (
        @($global_clock) (in == 1'b1) |-> $onehot(out)
    );

    // The output bus is never multi-hot.
    check_output_onehot0: assert property (
        @($global_clock) $onehot0(out)
    );

    // Any asserted output requires the input to be high.
    check_nonzero_output_requires_high_input: assert property (
        @($global_clock) (out != '0) |-> (in == 1'b1)
    );

endmodule

rtl:
module data_manipulation (
  input [3:0] in_data,
  input [1:0] ctrl,
  output reg [3:0] out_data
);

  always @(*)
  begin
    case (ctrl)
      2'b00: out_data = ~in_data;
      2'b01: out_data = ~in_data + 1;
      2'b10: out_data = {in_data[2:0], 1'b0};
      2'b11: out_data = {1'b0, in_data[3:1]};
      default: out_data = 4'b0;
    endcase
  end

endmodule

sva:
module data_manipulation_sva (
    input logic clk,
    input logic [3:0] in_data,
    input logic [1:0] ctrl,
    input logic [3:0] out_data
);

    // Combinational RTL with no native clock or reset; clk is a sampling clock.

    // ctrl=00 inverts all input bits.
    check_invert_mode: assert property (
        @(posedge clk) (ctrl == 2'b00) |-> (out_data == ~in_data)
    );

    // ctrl=01 computes the two's complement of the input.
    check_twos_complement_mode: assert property (
        @(posedge clk) (ctrl == 2'b01) |-> (out_data == (~in_data + 4'b0001))
    );

    // ctrl=10 shifts left by one and inserts zero at the LSB.
    check_left_shift_mode: assert property (
        @(posedge clk) (ctrl == 2'b10) |-> (out_data == {in_data[2:0], 1'b0})
    );

    // ctrl=11 shifts right by one and inserts zero at the MSB.
    check_right_shift_mode: assert property (
        @(posedge clk) (ctrl == 2'b11) |-> (out_data == {1'b0, in_data[3:1]})
    );

endmodule

rtl:
module calculator(
    input [3:0] A,
    input [3:0] B,
    input op,
    output reg [3:0] result
);

    always @(*) begin
        if (op == 1'b0) begin
            // subtraction
            result = A - B;
        end else begin
            // addition
            result = A + B;
        end
    end
endmodule

sva:
module calculator_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic op,
    input logic [3:0] result
);

    // Addition mode drives result to A plus B.
    check_addition_mode: assert property (
        @(posedge clk) (op == 1'b1) |-> (result == (A + B))
    );

    // Subtraction mode drives result to A minus B.
    check_subtraction_mode: assert property (
        @(posedge clk) (op == 1'b0) |-> (result == (A - B))
    );

    // Result always matches the operation selected by op.
    check_selected_operation: assert property (
        @(posedge clk) result == (op ? (A + B) : (A - B))
    );

    // Adding zero on B leaves A unchanged.
    check_add_zero_identity: assert property (
        @(posedge clk) (op == 1'b1 && B == 4'h0) |-> (result == A)
    );

    // Subtracting zero leaves A unchanged.
    check_subtract_zero_identity: assert property (
        @(posedge clk) (op == 1'b0 && B == 4'h0) |-> (result == A)
    );

    // Subtracting equal operands produces zero.
    check_equal_operands_subtract_zero: assert property (
        @(posedge clk) (op == 1'b0 && A == B) |-> (result == 4'h0)
    );

endmodule

module power_fill_sva (
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB,
    input logic power_out
);

    // power_out matches the OR of all power pins.
    check_power_out_matches_or: assert property (
        @($global_clock) power_out == (VPWR || VGND || VPB || VNB)
    );

    // Any asserted power pin drives power_out high.
    check_any_input_high_sets_output: assert property (
        @($global_clock) (VPWR || VGND || VPB || VNB) |-> power_out
    );

    // With all power pins low, power_out is low.
    check_all_inputs_low_clears_output: assert property (
        @($global_clock) !(VPWR || VGND || VPB || VNB) |-> !power_out
    );

    // A high power_out requires at least one power pin high.
    check_output_high_implies_input_high: assert property (
        @($global_clock) power_out |-> (VPWR || VGND || VPB || VNB)
    );

    // A low power_out requires all power pins low.
    check_output_low_implies_inputs_low: assert property (
        @($global_clock) !power_out |-> !(VPWR || VGND || VPB || VNB)
    );

endmodule

rtl:
module top_module(
    input [3:0] binary_in, // 4-bit binary input
    output [3:0] final_out // 4-bit output from the functional module
);

    wire [3:0] gray_out;
    wire [1:0] xor_out;

    gray_code_converter gray_converter(
        .binary_in(binary_in),
        .gray_out(gray_out)
    );

    xor_gate xor_1(
        .a(gray_out[0]),
        .b(gray_out[1]),
        .out(xor_out[0])
    );

    xor_gate xor_2(
        .a(gray_out[2]),
        .b(gray_out[3]),
        .out(xor_out[1])
    );

    functional_module functional(
        .gray_in(gray_out),
        .xor_in(xor_out),
        .final_out(final_out)
    );

endmodule
module gray_code_converter(
    input [3:0] binary_in, // 4-bit binary input
    output [3:0] gray_out // 4-bit Gray code output
);

    assign gray_out[0] = binary_in[0];
    assign gray_out[1] = binary_in[0] ^ binary_in[1];
    assign gray_out[2] = binary_in[1] ^ binary_in[2];
    assign gray_out[3] = binary_in[2] ^ binary_in[3];

endmodule
module xor_gate(
    input a,
    input b,
    output reg out
);

    always @(a, b) begin
        out = a ^ b;
    end

endmodule
module functional_module(
    input [3:0] gray_in, // 4-bit Gray code input
    input [1:0] xor_in, // 2-bit XOR gate output input
    output [3:0] final_out // 4-bit output from the functional module
);

    assign final_out = gray_in ^ xor_in;

endmodule

