        @($global_clock) out_or === ((in_1[0] | in_2[0]) | (in_3[0] | in_4[0]))
    );

    // out_xor matches the LSB of the cascaded XOR computation.
    check_out_xor_matches_lsb_xor: assert property (
        @($global_clock) out_xor === ((in_1[0] ^ in_2[0]) ^ (in_3[0] ^ in_4[0]))
