wire [3:0] shl_a;
wire [3:0] shr_a;
wire ovf;

assign add_ab = a + b;
assign sub_ab = a - b;
assign and_ab = a & b;
assign or_ab = a | b;
assign xor_ab = a ^ b;
assign not_a = ~a;
assign shl_a = {a[2:0], 1'b0};
assign shr_a = {1'b0, a[3:1]};

assign zero = (out == 4'b0000);

assign ovf = (ctl == 4'b0000 || ctl == 4'b0001) ? (a[3] == b[3] && out[3] != a[3]) : 1'b0;

always @(*) begin
    case (ctl)
        4'b0000: out <= add_ab; // Addition
        4'b0001: out <= sub_ab; // Subtraction
        4'b0010: out <= and_ab; // Bitwise AND
        4'b0011: out <= or_ab; // Bitwise OR
        4'b0100: out <= xor_ab; // Bitwise XOR
        4'b0101: out <= not_a; // Bitwise NOT
        4'b0110: out <= shl_a; // Shift left
        4'b0111: out <= shr_a; // Shift right
        default: out <= 4'b0000;
    endcase
end

endmodule

sva:
module four_bit_alu_sva(
    input logic clk,
    input logic [3:0] ctl,
    input logic [3:0] a,
    input logic [3:0] b,
    input logic [3:0] out,
    input logic zero
);

    // Addition opcode drives out to a + b.
    check_addition_result: assert property (
        @(posedge clk) (ctl == 4'b0000) |-> (out == (a + b))
    );

    // Subtraction opcode drives out to a - b.
    check_subtraction_result: assert property (
        @(posedge clk) (ctl == 4'b0001) |-> (out == (a - b))
    );

    // AND opcode drives out to a & b.
    check_and_result: assert property (
        @(posedge clk) (ctl == 4'b0010) |-> (out == (a & b))
    );

    // OR opcode drives out to a | b.
    check_or_result: assert property (
        @(posedge clk) (ctl == 4'b0011) |-> (out == (a | b))
    );

    // XOR opcode drives out to a ^ b.
    check_xor_result: assert property (
        @(posedge clk) (ctl == 4'b0100) |-> (out == (a ^ b))
    );

    // NOT opcode drives out to ~a.
    check_not_result: assert property (
        @(posedge clk) (ctl == 4'b0101) |-> (out == (~a))
    );

    // Shift-left opcode drives out to a shifted left by one.
    check_shift_left_result: assert property (
        @(posedge clk) (ctl == 4'b0110) |-> (out == {a[2:0], 1'b0})
    );

    // Shift-right opcode drives out to a shifted right by one.
    check_shift_right_result: assert property (
        @(posedge clk) (ctl == 4'b0111) |-> (out == {1'b0, a[3:1]})
    );

    // Unused opcodes drive out to zero.
    check_default_result: assert property (
        @(posedge clk) ctl[3] |-> (out == 4'b0000)
    );

    // Zero flag matches whether out is all zeros.
    check_zero_flag: assert property (
        @(posedge clk) (zero == (out == 4'b0000))
    );

endmodule

rtl:
module top_module (
    input [3:0] A, B, // Two 4-bit inputs
    input carry_in, // Carry input for the ripple carry adder
    output [3:0] sum, // 4-bit output from the ripple carry adder
    output carry_out, // Carry output from the ripple carry adder
    output EQ, GT, LT // Comparison outputs from the functional module
);

    // Ripple carry adder
    wire [3:0] adder_out;
    wire carry_out_internal;
    ripple_carry_adder adder(.A(A), .B(B), .carry_in(carry_in), .sum(adder_out), .carry_out(carry_out_internal));

    // Output sum and carry_out from the adder
    assign sum = adder_out;
    assign carry_out = carry_out_internal;

    // Functional module for comparison
    assign EQ = (A == B);
    assign GT = (A > B);
    assign LT = (A < B);

endmodule

// Ripple carry adder module
module ripple_carry_adder (
    input [3:0] A, B, // Two 4-bit inputs
    input carry_in, // Carry input
    output [3:0] sum, // 4-bit output from the adder
    output carry_out // Carry output from the adder
);

    wire [3:0] sum_internal;
    wire [3:0] carry_out_internal;

    // Full adder for the least significant bit
    full_adder adder0(.A(A[0]), .B(B[0]), .carry_in(carry_in), .sum(sum_internal[0]), .carry_out(carry_out_internal[0]));

    // Ripple carry adder for the remaining bits
    genvar i;
    generate
        for (i = 1; i < 4; i = i + 1) begin : adder_loop
            full_adder adder(.A(A[i]), .B(B[i]), .carry_in(carry_out_internal[i-1]), .sum(sum_internal[i]), .carry_out(carry_out_internal[i]));
        end
    endgenerate

    // Output sum and carry_out from the adder
    assign sum = sum_internal;
    assign carry_out = carry_out_internal[3];

endmodule

// Full adder module
module full_adder (
    input A, B, carry_in, // Three inputs
    output sum, carry_out // Two outputs
);

    assign sum = A ^ B ^ carry_in;
    assign carry_out = (A & B) | (carry_in & (A ^ B));

endmodule

sva:
module top_module_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic       carry_in,
    input logic [3:0] sum,
    input logic       carry_out,
    input logic       EQ,
    input logic       GT,
    input logic       LT
);

    // Sum and carry_out match the 5-bit addition of A, B, and carry_in.
    check_adder_result: assert property (
        @($global_clock) {carry_out, sum} == ({1'b0, A} + {1'b0, B} + carry_in)
    );

    // The LSB sum matches the full-adder equation.
    check_sum_bit0: assert property (
        @($global_clock) sum[0] == (A[0] ^ B[0] ^ carry_in)
    );

    // EQ reflects whether A and B are equal.
    check_eq_definition: assert property (
        @($global_clock) EQ == (A == B)
    );

    // GT reflects whether A is greater than B.
    check_gt_definition: assert property (
        @($global_clock) GT == (A > B)
    );

    // LT reflects whether A is less than B.
    check_lt_definition: assert property (
        @($global_clock) LT == (A < B)
    );

    // Comparison outputs are never asserted together.
    check_compare_mutex: assert property (
        @($global_clock) !((EQ && GT) || (EQ && LT) || (GT && LT))
    );

    // One comparison output is always asserted.
    check_compare_complete: assert property (
        @($global_clock) EQ || GT || LT
    );

    // Equal inputs drive only EQ high.
    check_equal_case: assert property (
        @($global_clock) (A == B) |-> (EQ && !GT && !LT)
    );

    // Greater-than inputs drive only GT high.
    check_greater_case: assert property (
        @($global_clock) (A > B) |-> (!EQ && GT && !LT)
    );

    // Less-than inputs drive only LT high.
    check_less_case: assert property (
        @($global_clock) (A < B) |-> (!EQ && !GT && LT)
    );

endmodule

