module bit_checker (
   input [15:0] in,
   output reg out
);

   always @* begin
      out = |in;
   end

endmodule

sva:
module bit_checker_sva (
    input logic clk,
    input logic [15:0] in,
    input logic out
);

    // Out equals the reduction OR of the input bus.
    check_out_matches_reduction_or: assert property (
        @(posedge clk) out === (|in)
    );

    // Zero input drives the output low.
    check_zero_input_drives_low: assert property (
        @(posedge clk) ((|in) === 1'b0) |-> (out === 1'b0)
    );

    // Any set input bit drives the output high.
    check_nonzero_input_drives_high: assert property (
        @(posedge clk) ((|in) === 1'b1) |-> (out === 1'b1)
    );

    // A low output means no input bits are set.
    check_low_output_implies_zero_input: assert property (
        @(posedge clk) (out === 1'b0) |-> ((|in) === 1'b0)
    );

    // A high output means at least one input bit is set.
    check_high_output_implies_nonzero_input: assert property (
        @(posedge clk) (out === 1'b1) |-> ((|in) === 1'b1)
    );

endmodule

rtl:
module add_sub_pipeline(
    input [31:0] a,
    input [31:0] b,
    input sub,
    output [31:0] sum
);

    wire [15:0] a_lo, b_lo, sum_lo;
    wire [15:0] a_hi, b_hi, sum_hi;
    wire carry;

    // Instantiate the 16-bit adder module twice
    adder16bit adder_lo(.a(a_lo), .b(b_lo), .carry_in(sub), .sum(sum_lo), .carry_out(carry));
    adder16bit adder_hi(.a(a_hi), .b(b_hi), .carry_in(carry), .sum(sum_hi), .carry_out());

    // Connect the inputs to the 16-bit adders
    assign a_lo = a[15:0];
    assign b_lo = b[15:0] ^ (sub ? 32'hFFFF : 0);
    assign a_hi = a[31:16];
    assign b_hi = b[31:16] ^ (sub ? 32'hFFFF : 0);

    // Connect the outputs of the 16-bit adders to the output of the module
    assign sum = {sum_hi, sum_lo};

endmodule

module adder16bit(
    input [15:0] a,
    input [15:0] b,
    input carry_in,
    output [15:0] sum,
    output carry_out
);

    assign {carry_out, sum} = a + b + carry_in;

endmodule

sva:
module add_sub_pipeline_sva (
    input logic [31:0] a,
    input logic [31:0] b,
    input logic sub,
    input logic [31:0] sum
);

    // In add mode, sum matches 32-bit addition.
    check_add_mode_function: assert property (
        @($global_clock) (!sub) |-> (sum == (a + b))
    );

    // In subtract mode, sum matches 32-bit subtraction.
    check_sub_mode_function: assert property (
        @($global_clock) sub |-> (sum == (a - b))
    );

    // The low 16 bits in add mode come from the low adder stage.
    check_add_low_half: assert property (
        @($global_clock) (!sub) |-> (sum[15:0] == (a[15:0] + b[15:0]))
    );

    // The high 16 bits in add mode include carry from the low stage.
    check_add_high_half_carry: assert property (
        @($global_clock) (!sub) |-> (
            sum[31:16] == (a[31:16] + b[31:16] + (({1'b0, a[15:0]} + {1'b0, b[15:0]})[16]))
        )
    );

    // The low 16 bits in subtract mode use inverted b and carry_in of 1.
    check_sub_low_half_twos_complement: assert property (
        @($global_clock) sub |-> (
            sum[15:0] == (a[15:0] + (~b[15:0]) + 16'd1)
        )
    );

    // The high 16 bits in subtract mode include carry from the low stage.
    check_sub_high_half_carry: assert property (
        @($global_clock) sub |-> (
            sum[31:16] == (a[31:16] + (~b[31:16]) + (({1'b0, a[15:0]} + {1'b0, (~b[15:0])} + 17'd1)[16]))
        )
    );

    // Adding zero leaves a unchanged.
    check_add_zero_b_passthrough: assert property (
        @($global_clock) ((!sub) && (b == 32'h0000_0000)) |-> (sum == a)
    );

    // Subtracting zero leaves a unchanged.
    check_sub_zero_b_passthrough: assert property (
        @($global_clock) (sub && (b == 32'h0000_0000)) |-> (sum == a)
    );

    // Zero plus b returns b in add mode.
    check_add_zero_a_passthrough: assert property (
        @($global_clock) ((!sub) && (a == 32'h0000_0000)) |-> (sum == b)
    );

    // Subtracting equal operands yields zero.
    check_self_subtract_zero: assert property (
        @($global_clock) (sub && (a == b)) |-> (sum == 32'h0000_0000)
    );

endmodule

