module add_sub_4bit_sva (
    input logic [3:0] a,
    input logic [3:0] b,
    input logic       mode,
    input logic       clk,
    input logic [3:0] result
);

    // In addition mode, result captures the prior cycle sum.
    check_addition_mode: assert property (
        @(posedge clk) (mode == 1'b1) |=> (result == ($past(a) + $past(b)))
    );

    // In subtraction mode, result captures the prior cycle difference.
    check_subtraction_mode: assert property (
        @(posedge clk) (mode == 1'b0) |=> (result == ($past(a) - $past(b)))
    );

    // Result always matches the prior cycle operation selected by mode.
    check_selected_operation: assert property (
        @(posedge clk) 1'b1 |=> (result == ($past(mode) ? ($past(a) + $past(b)) : ($past(a) - $past(b))))
    );

    // Adding zero passes a through on the next cycle.
    check_add_zero_identity: assert property (
        @(posedge clk) ((mode == 1'b1) && (b == 4'b0000)) |=> (result == $past(a))
    );

    // Subtracting zero passes a through on the next cycle.
    check_sub_zero_identity: assert property (
        @(posedge clk) ((mode == 1'b0) && (b == 4'b0000)) |=> (result == $past(a))
    );

    // Subtracting equal operands yields zero on the next cycle.
    check_sub_equal_operands_zero: assert property (
        @(posedge clk) ((mode == 1'b0) && (a == b)) |=> (result == 4'b0000)
    );

endmodule

rtl:
module up_down_counter (
    input up_down,
    input load,
    input clock,
    input reset,
    output reg [3:0] count
);

    always @(posedge clock, negedge reset) begin
        if (reset == 0) begin
            count <= 4'b0000;
        end else if (load == 1) begin
            count <= 4'b0000;
        end else if (up_down == 1) begin
            count <= count + 4'b0001;
        end else begin
            count <= count - 4'b0001;
        end
    end

endmodule

sva:
module up_down_counter_sva (
    input logic       up_down,
    input logic       load,
    input logic       clock,
    input logic       reset,
    input logic [3:0] count
);

    // Count is zero whenever the active-low reset is asserted.
    check_reset_clears_count: assert property (
        @(posedge clock) !reset |-> (count == 4'h0)
    );

    // A load sampled on the prior clock drives the count to zero.
    check_load_clears_count: assert property (
        @(posedge clock) disable iff (!reset)
        ($past(reset) && $past(load)) |-> (count == 4'h0)
    );

    // An up-count step that ends nonzero must be previous count plus one.
    check_count_up_nonzero_step: assert property (
        @(posedge clock) disable iff (!reset)
        ($past(reset) && !$past(load) && $past(up_down) && (count != 4'h0))
        |-> (count == ($past(count) + 4'h1))
    );

    // Counting up from 4'hF wraps to 4'h0.
    check_count_up_wrap_to_zero: assert property (
        @(posedge clock) disable iff (!reset)
        ($past(reset) && !$past(load) && $past(up_down) && ($past(count) == 4'hF))
        |-> (count == 4'h0)
    );

    // A down-count step that ends nonzero must be previous count minus one.
    check_count_down_nonzero_step: assert property (
        @(posedge clock) disable iff (!reset)
        ($past(reset) && !$past(load) && !$past(up_down) && (count != 4'h0))
        |-> (count == ($past(count) - 4'h1))
    );

    // Counting down from 4'h1 reaches 4'h0.
    check_count_down_to_zero: assert property (
        @(posedge clock) disable iff (!reset)
        ($past(reset) && !$past(load) && !$past(up_down) && ($past(count) == 4'h1))
        |-> (count == 4'h0)
    );

endmodule

rtl:
module sky130_fd_sc_hd__lpflow_inputisolatch(
    input D,
    input SLEEP_B,
    input VPWR,
    input VGND,
    input VPB,
    input VNB,
    output Q
);

reg Q_reg;
reg D_reg;
reg SLEEP_B_reg;
reg VPWR_reg;
reg VGND_reg;
reg VPB_reg;
reg VNB_reg;

always @(posedge VPWR or negedge VGND) begin
    if (VGND == 0) begin
        Q_reg <= 1'b0;
    end else begin
        Q_reg <= D_reg;
    end
end

assign Q = Q_reg;

always @(D or SLEEP_B or VPWR or VGND or VPB or VNB) begin
    if (VGND == 0) begin
        D_reg <= 1'b0;
        SLEEP_B_reg <= 1'b0;
        VPWR_reg <= 1'b0;
        VGND_reg <= 1'b0;
        VPB_reg <= 1'b0;
        VNB_reg <= 1'b0;
    end else begin
        D_reg <= D;
        SLEEP_B_reg <= SLEEP_B;
        VPWR_reg <= VPWR;
        VGND_reg <= VGND;
        VPB_reg <= VPB;
        VNB_reg <= VNB;
    end
end

endmodule

sva:
module sky130_fd_sc_hd__lpflow_inputisolatch_sva (
    input logic D,
    input logic SLEEP_B,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB,
    input logic Q,
    input logic Q_reg,
    input logic D_reg,
    input logic SLEEP_B_reg,
    input logic VPWR_reg,
    input logic VGND_reg,
    input logic VPB_reg,
    input logic VNB_reg
);

    // Q is always the continuous image of Q_reg.
    check_q_matches_q_reg: assert property (
        @(posedge VPWR or negedge VGND) Q == Q_reg
    );

    // Ground low holds Q and Q_reg low.
    check_q_low_when_vgnd_low: assert property (
        @(posedge VPWR) (VGND == 1'b0) |-> ((Q == 1'b0) && (Q_reg == 1'b0))
    );

    // Ground low clears all mirrored input registers.
    check_mirror_regs_low_when_vgnd_low: assert property (
        @(posedge VPWR) (VGND == 1'b0) |->
            ((D_reg == 1'b0) &&
             (SLEEP_B_reg == 1'b0) &&
             (VPWR_reg == 1'b0) &&
             (VGND_reg == 1'b0) &&
             (VPB_reg == 1'b0) &&
             (VNB_reg == 1'b0))
    );

    // With ground high, D_reg follows D.
    check_d_reg_follows_d: assert property (
        @(posedge VPWR) disable iff (VGND == 1'b0) (D_reg == D)
    );

    // With ground high, the other mirrored inputs follow their pins.
    check_side_regs_follow_inputs: assert property (
        @(posedge VPWR) disable iff (VGND == 1'b0)
            ((SLEEP_B_reg == SLEEP_B) &&
             (VGND_reg == VGND) &&
             (VPB_reg == VPB) &&
             (VNB_reg == VNB))
    );

    // Each enabled power edge loads the sampled D_reg value into Q.
    check_q_captures_d_reg_on_power_edge: assert property (
        @(posedge VPWR or negedge VGND) disable iff (VGND == 1'b0)
            1'b1 |=> (Q == $past(D_reg))
    );

    // Each enabled power edge loads the sampled D_reg value into Q_reg.
    check_qreg_captures_d_reg_on_power_edge: assert property (
        @(posedge VPWR or negedge VGND) disable iff (VGND == 1'b0)
            1'b1 |=> (Q_reg == $past(D_reg))
    );

    // A falling ground event leaves Q and Q_reg low by the next sample.
    check_vgnd_fall_clears_q: assert property (
        @(posedge VPWR or negedge VGND) $fell(VGND) |=> ((Q == 1'b0) && (Q_reg == 1'b0))
    );

endmodule

