module sky130_fd_sc_ls__a311oi (
    Y ,
    A1,
    A2,
    A3,
    B1,
    C1
);

    output Y ;
    input  A1;
    input  A2;
    input  A3;
    input  B1;
    input  C1;

    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    wire and0_out  ;
    wire nor0_out_Y;

    and and0 (and0_out  , A3, A1, A2      );
    nor nor0 (nor0_out_Y, and0_out, B1, C1);
    buf buf0 (Y         , nor0_out_Y      );

endmodule

sva:
module sky130_fd_sc_ls__a311oi_sva (
    input logic clk,
    input logic Y,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic B1,
    input logic C1
);

    // Y must match the implemented AOI311 function.
    check_y_matches_a311oi_function: assert property (
        @(posedge clk) Y == ~((A1 & A2 & A3) | B1 | C1)
    );

    // B1 high must force Y low.
    check_b1_forces_y_low: assert property (
        @(posedge clk) B1 |-> !Y
    );

    // C1 high must force Y low.
    check_c1_forces_y_low: assert property (
        @(posedge clk) C1 |-> !Y
    );

    // All three A inputs high must force Y low.
    check_a_triplet_forces_y_low: assert property (
        @(posedge clk) (A1 && A2 && A3) |-> !Y
    );

    // With no asserted NOR inputs, Y must be high.
    check_y_high_when_no_or_term: assert property (
        @(posedge clk) (!B1 && !C1 && !(A1 && A2 && A3)) |-> Y
    );

    // A high Y implies none of the NOR inputs are asserted.
    check_y_high_implies_no_or_term: assert property (
        @(posedge clk) Y |-> (!B1 && !C1 && !(A1 && A2 && A3))
    );

    // If B1 and C1 are low and Y is low, the A triplet must be high.
    check_y_low_without_b1_c1_requires_a_triplet: assert property (
        @(posedge clk) (!B1 && !C1 && !Y) |-> (A1 && A2 && A3)
    );

endmodule

rtl:
module jt51_sh2 #(parameter width=5, stages=32 )
(
	input 							clk,
	input							en,
	input							ld,
	input		[width-1:0]			din,
   	output		[width-1:0]			drop
);

genvar i;
generate
	for( i=0; i<width; i=i+1) begin: shifter
		jt51_sh1 #(.stages(stages)) u_sh1(
			.clk	( clk 	 ),
			.en		( en  	 ),
			.ld		( ld	 ),
			.din	( din[i] ),
			.drop	( drop[i])
		);
	end
endgenerate

endmodule

module jt51_sh1 #(parameter stages=32)
(
	input 	clk,
	input	en,
	input	ld,
	input	din,
   	output	drop
);

reg	[stages-1:0] shift;
assign drop = shift[0];
wire next = ld ? din : drop;

always @(posedge clk ) 
	if( en )
		shift <= {next, shift[stages-1:1]};

endmodule

sva:
module jt51_sh1_sva #(
    parameter stages = 32
) (
    input logic              clk,
    input logic              en,
    input logic              ld,
    input logic              din,
    input logic              drop,
    input logic [stages-1:0] shift,
    input logic              next
);

    // next selects din when ld is asserted.
    check_next_from_din_when_load: assert property (
        @(posedge clk) ld |-> (next === din)
    );

    // next recirculates drop when ld is deasserted.
    check_next_from_drop_when_shift: assert property (
        @(posedge clk) !ld |-> (next === drop)
    );

    // drop is always driven from the shift register LSB.
    check_drop_matches_shift_lsb: assert property (
        @(posedge clk) drop === shift[0]
    );

    property p_shift_holds_when_disabled;
        logic [stages-1:0] prev_shift;
        @(posedge clk) (!en, prev_shift = shift) |=> (shift === prev_shift);
    endproperty
    // shift holds its state when en is low.
    check_shift_holds_when_disabled: assert property (p_shift_holds_when_disabled);

    property p_drop_holds_when_disabled;
        logic prev_drop;
        @(posedge clk) (!en, prev_drop = drop) |=> (drop === prev_drop);
    endproperty
    // drop holds its value when en is low.
    check_drop_holds_when_disabled: assert property (p_drop_holds_when_disabled);

    property p_load_captures_din_to_msb;
        logic prev_din;
        @(posedge clk) (en && ld, prev_din = din) |=> (shift[stages-1] === prev_din);
    endproperty
    // enabled load writes din into the MSB.
    check_load_captures_din_to_msb: assert property (p_load_captures_din_to_msb);

    property p_recirculate_captures_drop_to_msb;
        logic prev_drop;
        @(posedge clk) (en && !ld, prev_drop = drop) |=> (shift[stages-1] === prev_drop);
    endproperty
    // enabled shift without load recirculates drop into the MSB.
    check_recirculate_captures_drop_to_msb: assert property (p_recirculate_captures_drop_to_msb);

    generate
        if (stages > 1) begin : g_shift_checks
            genvar j;
            for (j = 0; j < stages-1; j = j + 1) begin : g_stage
                property p_shift_moves_down;
                    logic prev_bit;
                    @(posedge clk) (en, prev_bit = shift[j+1]) |=> (shift[j] === prev_bit);
                endproperty
                // enabled shift moves each bit down by one stage.
                check_shift_moves_down: assert property (p_shift_moves_down);
            end

            property p_enabled_drop_follows_stage1;
                logic prev_stage1;
                @(posedge clk) (en, prev_stage1 = shift[1]) |=> (drop === prev_stage1);
            endproperty
            // enabled shift updates drop from the next stage.
            check_enabled_drop_follows_stage1: assert property (p_enabled_drop_follows_stage1);
        end
    endgenerate

endmodule

rtl:
module dff_4 (
  input clk,
  input reset,
  input [3:0] d,
  output [3:0] q
);
  reg [3:0] q_reg;

  always @(posedge clk) begin
    if (reset) begin
      q_reg <= 4'b0;
    end else begin
      q_reg <= d;
    end
  end

  assign q = q_reg;
endmodule

sva:
module dff_4_assertions (
    input logic clk,
    input logic reset,
    input logic [3:0] d,
    input logic [3:0] q
);

    // Reset clears q on the following clock.
    check_reset_clears_q: assert property (
        @(posedge clk) reset |=> (q == 4'b0000)
    );

    // q stays zero across consecutive reset cycles.
    check_reset_holds_q_zero: assert property (
        @(posedge clk) reset ##1 reset |-> (q == 4'b0000)
    );

    // q is still zero on the clock where reset deasserts.
    check_reset_release_observes_zero: assert property (
        @(posedge clk) $fell(reset) |-> (q == 4'b0000)
    );

    // When not in reset, q captures d on the next clock.
    check_q_captures_d: assert property (
        @(posedge clk) disable iff (reset) 1'b1 |=> (q == $past(d))
    );

endmodule

rtl:
module addsub (
    input [3:0] A,
    input [3:0] B,
    input sub,
    output [3:0] S
);

    wire [3:0] B_neg;
    assign B_neg = ~B + 1;

    wire [3:0] add_out;
    assign add_out = A + B;

    wire [3:0] sub_out;
    assign sub_out = A + B_neg;

    assign S = sub ? sub_out : add_out;

endmodule

sva:
module addsub_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic sub,
    input logic [3:0] S
);

    // No reset in RTL; this combinational logic is sampled on clk.

    // Output matches the selected add/sub result.
    check_function_select: assert property (
        @(posedge clk) (S == (sub ? (A + (~B + 4'b0001)) : (A + B)))
    );

    // In add mode, S is A plus B.
    check_add_mode_result: assert property (
        @(posedge clk) (!sub) |-> (S == (A + B))
    );

    // In subtract mode, S is A plus two's complement of B.
    check_sub_mode_result: assert property (
        @(posedge clk) sub |-> (S == (A + (~B + 4'b0001)))
    );

    // B equal to zero leaves A unchanged in either mode.
    check_zero_b_passthrough: assert property (
        @(posedge clk) (B == 4'h0) |-> (S == A)
    );

    // In add mode, zero on A passes B through.
    check_add_zero_a_passthrough: assert property (
        @(posedge clk) ((!sub) && (A == 4'h0)) |-> (S == B)
    );

    // Subtracting equal operands yields zero.
    check_sub_equal_operands_zero: assert property (
        @(posedge clk) (sub && (A == B)) |-> (S == 4'h0)
    );

    // Subtraction result plus B reconstructs A modulo 16.
    check_sub_inverse_relation: assert property (
        @(posedge clk) sub |-> ((S + B) == A)
    );

    // Subtracting from zero yields the two's complement of B.
    check_sub_from_zero_twos_complement: assert property (
        @(posedge clk) (sub && (A == 4'h0)) |-> (S == (~B + 4'b0001))
    );

endmodule

rtl:
module binary_to_gray_converter (
  input [3:0] binary_input,
  output [3:0] gray_output
);

  assign gray_output[3] = binary_input[3];
  assign gray_output[2] = binary_input[3] ^ binary_input[2];
  assign gray_output[1] = binary_input[2] ^ binary_input[1];
  assign gray_output[0] = binary_input[1] ^ binary_input[0];

endmodule

sva:
module binary_to_gray_converter_sva (
    input logic       clk,
    input logic [3:0] binary_input,
    input logic [3:0] gray_output
);

    // MSB passes through unchanged.
    check_gray_msb_passthrough: assert property (
        @(posedge clk) gray_output[3] === binary_input[3]
    );

    // Bit 2 is binary_input[3] XOR binary_input[2].
    check_gray_bit2_xor: assert property (
        @(posedge clk) gray_output[2] === (binary_input[3] ^ binary_input[2])
    );

    // Bit 1 is binary_input[2] XOR binary_input[1].
    check_gray_bit1_xor: assert property (
        @(posedge clk) gray_output[1] === (binary_input[2] ^ binary_input[1])
    );

    // Bit 0 is binary_input[1] XOR binary_input[0].
    check_gray_lsb_xor: assert property (
        @(posedge clk) gray_output[0] === (binary_input[1] ^ binary_input[0])
    );

    // Full output matches the standard binary-to-Gray conversion.
    check_gray_vector_relation: assert property (
        @(posedge clk) gray_output === (binary_input ^ (binary_input >> 1))
    );

endmodule

rtl:
module my_or2 (output o, input i0, i1);
    wire n0, n1, n2, n3;
    not I0 (n0, i0);
    not I1 (n1, i1);
    and I2 (n2, n0, n1);
    not I3 (n3, n2);
    or I4 (o, i0, i1);
endmodule

sva:
module my_or2_sva (
    input logic clk,
    input logic o,
    input logic i0,
    input logic i1
);

    // Output equals the OR of the two inputs.
    check_or_function: assert property (
        @(posedge clk) o == (i0 | i1)
    );

    // Output is low when both inputs are low.
    check_both_inputs_low: assert property (
        @(posedge clk) (!i0 && !i1) |-> !o
    );

    // Output is high whenever i0 is high.
    check_i0_high_sets_output: assert property (
        @(posedge clk) i0 |-> o
    );

    // Output is high whenever i1 is high.
    check_i1_high_sets_output: assert property (
        @(posedge clk) i1 |-> o
    );

endmodule

rtl:
module my_module (
    Y ,
    A1,
    A2,
    B1,
    B2
);

    // Module ports
    output Y ;
    input  A1;
    input  A2;
    input  B1;
    input  B2;

    // Module supplies
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    // Local signals
    wire nand0_out ;
    wire nand1_out ;
    wire and0_out_Y;

    //   Name   Output      Other arguments
    nand nand0 (nand0_out , A2, A1              );
    nand nand1 (nand1_out , B2, B1              );
    and  and0  (and0_out_Y, nand0_out, nand1_out);
    buf  buf0  (Y         , and0_out_Y          );

endmodule

sva:
module my_module_sva (
    input logic Y,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic B2
);

    // Check the implemented combinational equation for Y.
    check_y_boolean_function: assert property (
        @($global_clock)
        Y == ((~(A1 & A2)) & (~(B1 & B2)))
    );

    // If A1 and A2 are both high, Y must be low.
    check_a_pair_high_forces_y_low: assert property (
        @($global_clock)
        (A1 && A2) |-> (Y == 1'b0)
    );

    // If B1 and B2 are both high, Y must be low.
    check_b_pair_high_forces_y_low: assert property (
        @($global_clock)
        (B1 && B2) |-> (Y == 1'b0)
    );

    // If neither input pair is simultaneously high, Y must be high.
    check_no_pair_high_forces_y_high: assert property (
        @($global_clock)
        (!(A1 && A2) && !(B1 && B2)) |-> (Y == 1'b1)
    );

    // Y high means A1 and A2 are not both high.
    check_y_high_excludes_a_pair_high: assert property (
        @($global_clock)
        (Y == 1'b1) |-> !(A1 && A2)
    );

    // Y high means B1 and B2 are not both high.
    check_y_high_excludes_b_pair_high: assert property (
        @($global_clock)
        (Y == 1'b1) |-> !(B1 && B2)
    );

    // Y low requires at least one input pair to be simultaneously high.
    check_y_low_requires_asserted_pair: assert property (
        @($global_clock)
        (Y == 1'b0) |-> ((A1 && A2) || (B1 && B2))
    );

endmodule

rtl:
module top_module (
    input clk,
    input reset,
    input [7:0] a,
    input [7:0] b,
    input select,
    output [7:0] sum,
    output [7:0] diff,
    output [7:0] abs_diff
);

    // Instantiate the adder module
    adder_module adder(
        .a(a),
        .b(b),
        .sum(sum)
    );

    // Calculate the difference between a and b
    assign diff = a - b;

    // Instantiate the multiplexer module
    mux2to1_module mux(
        .a(sum),
        .b(diff),
        .select(select),
        .out(abs_diff)
    );

endmodule
module adder_module (
    input [7:0] a,
    input [7:0] b,
    output reg [7:0] sum
);

    always @(*) begin
        sum = a + b;
    end

endmodule
module mux2to1_module (
    input [7:0] a,
    input [7:0] b,
    input select,
    output reg [7:0] out
);

    always @(select or a or b) begin
        out = (select == 1'b0) ? a : b;
    end

endmodule

