module float_add_sub_altpriority_encoder_qh8
    ( 
    input   [3:0]  data,
    output   [1:0]  q,
    output  zero
    );

    assign zero = (data[0] == 0) & (data[1] == 0) & (data[2] == 0) & (data[3] == 0);

    assign q[0] = data[0] | data[1];
    assign q[1] = data[2] | data[3];

endmodule

module float_add_sub_altpriority_encoder_q28
    ( 
    input   [3:0]  data,
    output   [1:0]  q
    );

    assign q[0] = data[0] | data[1];
    assign q[1] = data[2] | data[3];

