rtl:
module multi_input_module(
    input input1,
    input input2,
    input input3,
    input input4,
    input input5,
    input input6,
    input input7,
    input input8,
    output output1
);

    reg temp1, temp2, temp3, temp4, temp5, temp6;

    always @(*) begin
        if (input1 && input2) begin
            temp1 = 1;
        end else if (!input1 && input2) begin
            temp1 = 0;
        end else if (input1 && !input2) begin
            temp1 = 1;
        end else if (!input1 && !input2) begin
            if (!input3 && !input4 && !input5 && !input6 && !input7 && !input8) begin
                temp1 = 0;
            end else begin
                temp1 = 1;
            end
        end
    end

    assign output1 = temp1;

endmodule

sva:
module multi_input_module_sva(
    input logic input1,
    input logic input2,
    input logic input3,
    input logic input4,
    input logic input5,
    input logic input6,
    input logic input7,
    input logic input8,
    input logic output1
);

    // output1 is high whenever input1 is high.
    check_output_high_when_input1_high: assert property (
        @($global_clock) input1 |-> output1
    );

    // output1 is low when input1 is low and input2 is high.
    check_output_low_when_input1_low_and_input2_high: assert property (
        @($global_clock) (!input1 && input2) |-> !output1
    );

    // output1 is low when input1 and input2 are low and input3-input8 are all low.
    check_output_low_when_all_secondary_inputs_low: assert property (
        @($global_clock)
        (!input1 && !input2 && !input3 && !input4 && !input5 && !input6 && !input7 && !input8)
        |-> !output1
    );

    // output1 is high when input1 and input2 are low and any of input3-input8 is high.
    check_output_high_when_any_secondary_input_high: assert property (
        @($global_clock)
        (!input1 && !input2 && (input3 || input4 || input5 || input6 || input7 || input8))
        |-> output1
    );

    // output1 matches the complete combinational function implemented by the RTL.
    check_output_matches_rtl_function: assert property (
        @($global_clock)
        output1 == (input1 ? 1'b1 : (input2 ? 1'b0 : (input3 || input4 || input5 || input6 || input7 || input8)))
    );

endmodule

rtl:
module lfsr (Clk, Reset, Seed, Enable, Data, Done);

parameter Tp = 1;

input Clk;
input Reset;
input [15:0] Seed;
input Enable;

output reg [15:0] Data;
output reg Done;

reg [15:0] Lfsr;

always @ (posedge Clk or posedge Reset) begin
  if (Reset) begin
    Lfsr <= #Tp 16'b0;
    Data <= #Tp 16'h0000;
    Done <= #Tp 1'b0;
  end else if (Enable) begin
    Lfsr <= #Tp {Lfsr[14:0], Lfsr[0] ^ Lfsr[2] ^ Lfsr[3] ^ Lfsr[5]};
    Data <= #Tp Lfsr;
    Done <= #Tp 1'b1;
  end else begin
    Done <= #Tp 1'b0;
  end
end

endmodule

sva:
module lfsr_sva (
    input logic        Clk,
    input logic        Reset,
    input logic [15:0] Seed,
    input logic        Enable,
    input logic [15:0] Data,
    input logic        Done,
    input logic [15:0] Lfsr
);

    // Reset clears all registered state.
    check_reset_clears_state: assert property (
        @(posedge Clk) Reset |-> ((Lfsr == 16'h0000) && (Data == 16'h0000) && (Done == 1'b0))
    );

    // Enable drives Done high on the next cycle.
    check_enable_sets_done: assert property (
        @(posedge Clk) disable iff (Reset)
        Enable |=> (Done == 1'b1)
    );

    // Disable drives Done low on the next cycle.
    check_disable_clears_done: assert property (
        @(posedge Clk) disable iff (Reset)
        !Enable |=> (Done == 1'b0)
    );

    // Data holds its value when Enable is low.
    check_disable_holds_data: assert property (
        @(posedge Clk) disable iff (Reset)
        !Enable |=> $stable(Data)
    );

    // Lfsr holds its value when Enable is low.
    check_disable_holds_lfsr: assert property (
        @(posedge Clk) disable iff (Reset)
        !Enable |=> $stable(Lfsr)
    );

    // Data captures the previous Lfsr value when enabled.
    check_enable_captures_lfsr_into_data: assert property (
        @(posedge Clk) disable iff (Reset)
        Enable |=> (Data == $past(Lfsr))
    );

    // Lfsr updates with the implemented feedback taps when enabled.
    check_enable_updates_lfsr: assert property (
        @(posedge Clk) disable iff (Reset)
        Enable |=> (Lfsr == { $past(Lfsr[14:0]), $past(Lfsr[0] ^ Lfsr[2] ^ Lfsr[3] ^ Lfsr[5]) })
    );

endmodule

rtl:
module assert_time_assert (
    input clk,
    input reset_n,
    input start_event,
    input test_expr,
    input [31:0] window,
    input ignore_new_start,
    input reset_on_new_start,
    input error_on_new_start,
    input xzcheck_enable,
    output reg assertion
);

    parameter num_cks = 1000; // Default value for number of clock cycles

    reg [31:0] timer;
    reg active;
    reg [31:0] num_cks_counter;

    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            timer <= 0;
            active <= 0;
            assertion <= 0;
        end else begin
            num_cks_counter <= num_cks_counter + 1;
            if (num_cks_counter == num_cks) begin
                num_cks_counter <= 0;
                if (start_event) begin
                    timer <= 0;
                    active <= 1;
                end
                if (active) begin
                    timer <= timer + 1;
                    if (timer >= window) begin
                        assertion <= test_expr;
                        active <= 0;
                    end
                    if (start_event && !ignore_new_start) begin
                        if (reset_on_new_start) begin
                            assertion <= 0;
                        end
                        if (error_on_new_start) begin
                            assertion <= 0;
                        end
                        active <= 1;
                        timer <= 0;
                    end
                end
            end
        end
    end

endmodule

sva:
module assert_time_assert_sva #(
    parameter [31:0] num_cks = 32'd1000
) (
    input logic clk,
    input logic reset_n,
    input logic start_event,
    input logic test_expr,
    input logic [31:0] window,
    input logic ignore_new_start,
    input logic reset_on_new_start,
    input logic error_on_new_start,
    input logic xzcheck_enable,
    input logic assertion,
    input logic [31:0] timer,
    input logic active,
    input logic [31:0] num_cks_counter
);

    // Counter increments when it has not reached the terminal count.
    check_counter_increments: assert property (
        @(posedge clk) disable iff (!reset_n)
        (num_cks_counter != num_cks)
        |=> (num_cks_counter == ($past(num_cks_counter) + 32'd1))
    );

    // Counter resets to zero on the terminal count.
    check_counter_wraps_to_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (num_cks_counter == num_cks)
        |=> (num_cks_counter == 32'd0)
    );

    // State holds on cycles where the terminal count is not hit.
    check_state_holds_between_terminal_counts: assert property (
        @(posedge clk) disable iff (!reset_n)
        (num_cks_counter != num_cks)
        |=> (timer == $past(timer)) &&
            (active == $past(active)) &&
            (assertion == $past(assertion))
    );

    // A start_event from idle arms the timer and sets active.
    check_idle_start_arms_timer: assert property (
        @(posedge clk) disable iff (!reset_n)
        (num_cks_counter == num_cks && !active && start_event)
        |=> (timer == 32'd0) &&
            (active == 1'b1) &&
            (assertion == $past(assertion))
    );

    // Idle state holds on a terminal count without start_event.
    check_idle_without_start_holds_state: assert property (
        @(posedge clk) disable iff (!reset_n)
        (num_cks_counter == num_cks && !active && !start_event)
        |=> (timer == $past(timer)) &&
            (active == 1'b0) &&
            (assertion == $past(assertion))
    );

    // While active, the timer increments before the window is reached.
    check_active_increments_before_window: assert property (
        @(posedge clk) disable iff (!reset_n)
        (num_cks_counter == num_cks && active && !start_event && (timer < window))
        |=> (timer == ($past(timer) + 32'd1)) &&
            (active == 1'b1) &&
            (assertion == $past(assertion))
    );

    // While active, reaching the window updates assertion and clears active.
    check_active_completes_at_window: assert property (
        @(posedge clk) disable iff (!reset_n)
        (num_cks_counter == num_cks && active && !start_event && (timer >= window))
        |=> (timer == ($past(timer) + 32'd1)) &&
            (active == 1'b0) &&
            (assertion == $past(test_expr))
    );

    // A non-ignored new start while active rearms the timer.
    check_new_start_rearms_timer: assert property (
        @(posedge clk) disable iff (!reset_n)
        (num_cks_counter == num_cks && active && start_event && !ignore_new_start)
        |=> (timer == 32'd0) &&
            (active == 1'b1)
    );

    // A non-ignored new start can clear assertion when either clear flag is set.
    check_new_start_clears_assertion: assert property (
        @(posedge clk) disable iff (!reset_n)
        (num_cks_counter == num_cks && active && start_event && !ignore_new_start &&
         (reset_on_new_start || error_on_new_start))
        |=> (assertion == 1'b0)
    );

    // A non-ignored new start without clear flags keeps assertion before expiry.
    check_new_start_keeps_assertion_before_window: assert property (
        @(posedge clk) disable iff (!reset_n)
        (num_cks_counter == num_cks && active && start_event && !ignore_new_start &&
         !reset_on_new_start && !error_on_new_start && (timer < window))
        |=> (assertion == $past(assertion))
    );

    // A non-ignored new start without clear flags still samples test_expr at expiry.
    check_new_start_updates_assertion_at_window: assert property (
        @(posedge clk) disable iff (!reset_n)
        (num_cks_counter == num_cks && active && start_event && !ignore_new_start &&
         !reset_on_new_start && !error_on_new_start && (timer >= window))
        |=> (assertion == $past(test_expr))
    );

    // An ignored new start does not reset the timer before expiry.
    check_ignored_new_start_does_not_restart_before_window: assert property (
        @(posedge clk) disable iff (!reset_n)
        (num_cks_counter == num_cks && active && start_event && ignore_new_start &&
         (timer < window))
        |=> (timer == ($past(timer) + 32'd1)) &&
            (active == 1'b1) &&
            (assertion == $past(assertion))
    );

    // An ignored new start does not block completion at or beyond the window.
    check_ignored_new_start_allows_completion: assert property (
        @(posedge clk) disable iff (!reset_n)
        (num_cks_counter == num_cks && active && start_event && ignore_new_start &&
         (timer >= window))
        |=> (timer == ($past(timer) + 32'd1)) &&
            (active == 1'b0) &&
            (assertion == $past(test_expr))
    );

endmodule

rtl:
module top_module (
    input [15:0] in0,
    input [15:0] in1,
    input CTRL,
    input CLK,
    output [15:0] OUT_ADDSUB,
    output [15:0] OUT_DIFF
);

wire [15:0] add_out;
wire [15:0] sub_out;

adder adder_inst (
    .in0(in0),
    .in1(in1),
    .out(add_out)
);

subtractor sub_inst (
    .in0(in0),
    .in1(in1),
    .out(sub_out)
);

assign OUT_ADDSUB = CTRL ? sub_out : add_out;

absolute_diff diff_inst (
    .in0(add_out),
    .in1(sub_out),
    .out(OUT_DIFF)
);

endmodule
module adder (
    input [15:0] in0,
    input [15:0] in1,
    output [15:0] out
);

assign out = in0 + in1;

endmodule
module subtractor (
    input [15:0] in0,
    input [15:0] in1,
    output [15:0] out
);

assign out = in0 - in1;

endmodule
module absolute_diff (
    input [15:0] in0,
    input [15:0] in1,
    output [15:0] out
);

assign out = in0 > in1 ? in0 - in1 : in1 - in0;

endmodule

sva:
module top_module_sva (
    input logic [15:0] in0,
    input logic [15:0] in1,
    input logic        CTRL,
    input logic        CLK,
    input logic [15:0] OUT_ADDSUB,
    input logic [15:0] OUT_DIFF
);

    // Assertions are sampled on CLK; the RTL has no reset.

    // OUT_ADDSUB selects the adder result when CTRL is low.
    check_out_addsub_select_add: assert property (
        @(posedge CLK) (!CTRL) |-> (OUT_ADDSUB == (in0 + in1))
    );

    // OUT_ADDSUB selects the subtractor result when CTRL is high.
    check_out_addsub_select_sub: assert property (
        @(posedge CLK) CTRL |-> (OUT_ADDSUB == (in0 - in1))
    );

    // OUT_DIFF uses add_out - sub_out when add_out is larger.
    check_out_diff_add_greater_branch: assert property (
        @(posedge CLK) ((in0 + in1) > (in0 - in1)) |-> (OUT_DIFF == ((in0 + in1) - (in0 - in1)))
    );

    // OUT_DIFF uses sub_out - add_out when sub_out is larger or equal.
    check_out_diff_sub_greater_equal_branch: assert property (
        @(posedge CLK) ((in0 + in1) <= (in0 - in1)) |-> (OUT_DIFF == ((in0 - in1) - (in0 + in1)))
    );

    // Zero on in1 makes the absolute difference zero.
    check_zero_in1_zero_diff: assert property (
        @(posedge CLK) (in1 == 16'h0000) |-> (OUT_DIFF == 16'h0000)
    );

    // Zero on in1 makes OUT_ADDSUB pass through in0.
    check_zero_in1_addsub_passthrough: assert property (
        @(posedge CLK) (in1 == 16'h0000) |-> (OUT_ADDSUB == in0)
    );

    // Equal inputs make the subtractor-selected output zero.
    check_equal_inputs_sub_zero: assert property (
        @(posedge CLK) (CTRL && (in0 == in1)) |-> (OUT_ADDSUB == 16'h0000)
    );

    // Equal inputs make OUT_DIFF equal the adder result.
    check_equal_inputs_diff_matches_sum: assert property (
        @(posedge CLK) (in0 == in1) |-> (OUT_DIFF == (in0 + in1))
    );

endmodule

rtl:
module signal_process(
    input [7:0] input_signal,
    output [7:0] output_signal
);

    assign output_signal = {~input_signal[3:0], input_signal[7:4] << 2};

endmodule

sva:
module signal_process_sva (
    input logic       clk,
    input logic [7:0] input_signal,
    input logic [7:0] output_signal
);

    // Output matches the implemented bit transformation.
    check_full_output_transform: assert property (
        @(posedge clk)
        output_signal == {~input_signal[3:0], input_signal[5:4], 2'b00}
    );

    // Upper output nibble is the inverse of the lower input nibble.
    check_upper_nibble_inversion: assert property (
        @(posedge clk)
        output_signal[7:4] == ~input_signal[3:0]
    );

    // Lower output nibble is the shifted upper input nibble.
    check_lower_nibble_shift: assert property (
        @(posedge clk)
        output_signal[3:0] == {input_signal[5:4], 2'b00}
    );

    // Output bits [3:2] map directly from input bits [5:4].
    check_shifted_bit_mapping: assert property (
        @(posedge clk)
        output_signal[3:2] == input_signal[5:4]
    );

    // Output bits [1:0] are always zero.
    check_low_bits_zero: assert property (
        @(posedge clk)
        output_signal[1:0] == 2'b00
    );

endmodule

module adder_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] S
);
    localparam logic [3:0] B = 4'hA;

    // S must equal A plus the constant 4'hA.
    check_sum_matches_constant: assert property (
        @(posedge clk) S == (A + B)
    );

    // Bit 0 passes through because B[0] is 0.
    check_bit0_passthrough: assert property (
        @(posedge clk) S[0] == A[0]
    );

    // Bit 1 inverts because B[1] is 1 and bit 0 generates no carry.
    check_bit1_relation: assert property (
        @(posedge clk) S[1] == ~A[1]
    );

    // Bit 2 is A[2] XOR the carry from bit 1.
    check_bit2_relation: assert property (
        @(posedge clk) S[2] == (A[2] ^ A[1])
    );

    // Bit 3 includes the constant 1 and the carry from bit 2.
    check_bit3_relation: assert property (
        @(posedge clk) S[3] == (A[3] ^ 1'b1 ^ (A[2] & A[1]))
    );
endmodule

rtl:
module adder_4bit(
    input [3:0] a,
    input [3:0] b,
    output reg [3:0] sum
);

always @(*) begin
    sum = a + b;
end

endmodule

sva:
module adder_4bit_sva(
    input logic [3:0] a,
    input logic [3:0] b,
    input logic [3:0] sum
);

    // Sum must match the 4-bit addition of the inputs.
    check_sum_matches_addition: assert property (
        @($global_clock) sum == (a + b)
    );

    // Stable inputs must keep the sum stable.
    check_stable_inputs_keep_sum_stable: assert property (
        @($global_clock) ($stable(a) && $stable(b)) |-> $stable(sum)
    );

    // Adding zero on b must pass a through to sum.
    check_zero_b_passthrough: assert property (
        @($global_clock) (b == 4'h0) |-> (sum == a)
    );

    // Adding zero on a must pass b through to sum.
    check_zero_a_passthrough: assert property (
        @($global_clock) (a == 4'h0) |-> (sum == b)
    );

    // The least significant sum bit must be the xor of input LSBs.
    check_lsb_sum_behavior: assert property (
        @($global_clock) sum[0] == (a[0] ^ b[0])
    );

endmodule

rtl:
module register(CLK, RST, Q_OUT, D_IN, EN);

   parameter width = 1;
   parameter init = { width {1'b0}} ;

   input     CLK;
   input     RST;
   input     EN;
   input [width - 1 : 0] D_IN;
   output [width - 1 : 0] Q_OUT;

   reg [width - 1 : 0]    Q_OUT;

   always@(posedge CLK or posedge RST) begin
      if (RST) begin
        Q_OUT <= init;
      end else if (EN) begin
        Q_OUT <= D_IN;
      end
   end // always@ (posedge CLK or posedge RST)

endmodule

sva:
module register_sva #(
    parameter int width = 1,
    parameter logic [width-1:0] init = {width{1'b0}}
) (
    input logic CLK,
    input logic RST,
    input logic EN,
    input logic [width-1:0] D_IN,
    input logic [width-1:0] Q_OUT
);

    // A sampled reset leaves Q_OUT at the init value by the next clock.
    check_reset_forces_init: assert property (
        @(posedge CLK) RST |=> (Q_OUT == init)
    );

    // With EN high, Q_OUT loads D_IN unless reset forces init between clocks.
    check_load_when_enabled: assert property (
        @(posedge CLK) disable iff (RST)
        EN |=> ((Q_OUT == $past(D_IN)) || (Q_OUT == init))
    );

    // With EN low, Q_OUT holds its value unless reset forces init between clocks.
    check_hold_when_disabled: assert property (
        @(posedge CLK) disable iff (RST)
        !EN |=> ((Q_OUT == $past(Q_OUT)) || (Q_OUT == init))
    );

endmodule

rtl:
module or4b_2 (
    X   ,
    A   ,
    B   ,
    C   ,
    D   ,
    VPWR,
    VGND
);

    output X   ;
    input  A   ;
    input  B   ;
    input  C   ;
    input  D   ;
    input  VPWR;
    input  VGND;

    assign X = A | B | C | D;

endmodule

sva:
module or4b_2_sva (
    input logic X,
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic VPWR,
    input logic VGND
);

    // No explicit clock or reset exists in the RTL; sample on the formal global clock.

    // X must always equal the OR of A, B, C, and D.
    check_or_equivalence: assert property (
        @($global_clock) X == (A | B | C | D)
    );

    // X must be low when all four inputs are low.
    check_all_low_drives_low: assert property (
        @($global_clock)
        ((A == 1'b0) && (B == 1'b0) && (C == 1'b0) && (D == 1'b0)) |-> (X == 1'b0)
    );

    // A high must drive X high.
    check_a_high_drives_high: assert property (
        @($global_clock) (A == 1'b1) |-> (X == 1'b1)
    );

    // B high must drive X high.
    check_b_high_drives_high: assert property (
        @($global_clock) (B == 1'b1) |-> (X == 1'b1)
    );

    // C high must drive X high.
    check_c_high_drives_high: assert property (
        @($global_clock) (C == 1'b1) |-> (X == 1'b1)
    );

    // D high must drive X high.
    check_d_high_drives_high: assert property (
        @($global_clock) (D == 1'b1) |-> (X == 1'b1)
    );

    // If X is low, then all four inputs must be low.
    check_x_low_implies_all_low: assert property (
        @($global_clock)
        (X == 1'b0) |-> ((A == 1'b0) && (B == 1'b0) && (C == 1'b0) && (D == 1'b0))
    );

endmodule

