module FullAdder(input a,b,c, output sum, carry);
  wire s1, c1, c2;
  xor g1(s1, a, b);
  xor g2(sum, s1, c);
  and g3(c1, a, b);
  and g4(c2, s1, c);
  xor g5(carry, c1, c2);
endmodule

module RippleCarryAdder(input [3:0] A, input [3:0] B, output [3:0] S, output Cout);

  wire c1, c2, c3;

  FullAdder fa1(A[0], B[0], 0, S[0], c1);
  FullAdder fa2(A[1], B[1], c1, S[1], c2);
  FullAdder fa3(A[2], B[2], c2, S[2], c3);
  FullAdder fa4(A[3], B[3], c3, S[3], Cout);

endmodule

sva:
module RippleCarryAdder_sva (
    input logic       clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] S,
    input logic       Cout
);

    function automatic logic carry_bit(
        input logic x,
        input logic y,
        input logic cin
    );
        carry_bit = (x & y) | (x & cin) | (y & cin);
    endfunction

    // Full 5-bit result matches A + B.
    check_sum_vector: assert property (
        @(posedge clk) {Cout, S} == ({1'b0, A} + {1'b0, B})
    );

    // Bit 0 is the XOR of A[0] and B[0].
    check_lsb_sum: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0])
    );

    // Bit 1 includes the carry from bit 0.
    check_bit1_sum: assert property (
        @(posedge clk) S[1] == (A[1] ^ B[1] ^ carry_bit(A[0], B[0], 1'b0))
    );

    // Bit 2 includes the ripple carry from lower bits.
    check_bit2_sum: assert property (
        @(posedge clk) S[2] == (A[2] ^ B[2] ^ carry_bit(A[1], B[1], carry_bit(A[0], B[0], 1'b0)))
    );

    // Bit 3 includes the ripple carry from lower bits.
    check_bit3_sum: assert property (
        @(posedge clk) S[3] == (A[3] ^ B[3] ^ carry_bit(A[2], B[2], carry_bit(A[1], B[1], carry_bit(A[0], B[0], 1'b0))))
    );

    // Cout is the final carry out of the MSB stage.
    check_final_carry: assert property (
        @(posedge clk) Cout == carry_bit(A[3], B[3], carry_bit(A[2], B[2], carry_bit(A[1], B[1], carry_bit(A[0], B[0], 1'b0))))
    );

    // Adding zero on B passes A through with no carry.
    check_b_zero_passthrough: assert property (
        @(posedge clk) (B == 4'h0) |-> ({Cout, S} == {1'b0, A})
    );

    // Adding zero on A passes B through with no carry.
    check_a_zero_passthrough: assert property (
        @(posedge clk) (A == 4'h0) |-> ({Cout, S} == {1'b0, B})
    );

    // Complementary inputs sum to all ones with no carry out.
    check_complement_case: assert property (
        @(posedge clk) (B == ~A) |-> ((S == 4'hF) && (Cout == 1'b0))
    );

endmodule

rtl:
module top_module (
    input [15:0] a,
    input [15:0] b,
    input [3:0] shift,
    input select,
    output [15:0] out
);

    // 16-bit adder
    wire [15:0] adder_out;
    assign adder_out = a + b;

    // 4-bit shifter
    wire [15:0] shifter_out;
    assign shifter_out = (shift == 4'd0) ? adder_out : (shift == 4'd1) ? {adder_out[14:0], 1'b0} :
                         (shift == 4'd2) ? {adder_out[13:0], 2'b00} : (shift == 4'd3) ? {adder_out[12:0], 3'b000} :
                         (shift == 4'd4) ? {adder_out[11:0], 4'b0000} : (shift == 4'd5) ? {adder_out[10:0], 5'b00000} :
                         (shift == 4'd6) ? {adder_out[9:0], 6'b000000} : (shift == 4'd7) ? {adder_out[8:0], 7'b0000000} :
                         (shift == 4'd8) ? {adder_out[7:0], 8'b00000000} : (shift == 4'd9) ? {adder_out[6:0], 9'b000000000} :
                         (shift == 4'd10) ? {adder_out[5:0], 10'b0000000000} : (shift == 4'd11) ? {adder_out[4:0], 11'b00000000000} :
                         (shift == 4'd12) ? {adder_out[3:0], 12'b000000000000} : (shift == 4'd13) ? {adder_out[2:0], 13'b0000000000000} :
                         (shift == 4'd14) ? {adder_out[1:0], 14'b00000000000000} : (shift == 4'd15) ? {adder_out[0], 15'b000000000000000} : 16'b0;

    // Functional module for bitwise OR
    wire [15:0] or_out;
    assign or_out = adder_out | shifter_out;

    // Output selection
    assign out = (select) ? shifter_out | or_out : adder_out | or_out;

endmodule

sva:
module top_module_sva (
    input logic        clk,
    input logic [15:0] a,
    input logic [15:0] b,
    input logic [3:0]  shift,
    input logic        select,
    input logic [15:0] out
);

    // No reset exists in the RTL; properties are sampled on an external clock.

    // Output must equal the adder result ORed with its left-shifted version.
    check_output_function: assert property (
        @(posedge clk) (out == ((a + b) | ((a + b) << shift)))
    );

    // When select is high, output still matches the same implemented function.
    check_select_high_function: assert property (
        @(posedge clk) select |-> (out == ((a + b) | ((a + b) << shift)))
    );

    // When select is low, output still matches the same implemented function.
    check_select_low_function: assert property (
        @(posedge clk) !select |-> (out == ((a + b) | ((a + b) << shift)))
    );

    // A zero shift makes the output equal to the adder result.
    check_shift_zero_passthrough: assert property (
        @(posedge clk) (shift == 4'd0) |-> (out == (a + b))
    );

    // Every asserted bit of the adder result must appear in the output.
    check_output_contains_sum_bits: assert property (
        @(posedge clk) (((a + b) & ~out) == 16'h0000)
    );

    // Every asserted bit of the shifted adder result must appear in the output.
    check_output_contains_shifted_sum_bits: assert property (
        @(posedge clk) ((((a + b) << shift) & ~out) == 16'h0000)
    );

    // A zero adder result forces the output low.
    check_zero_sum_gives_zero_out: assert property (
        @(posedge clk) ((a + b) == 16'h0000) |-> (out == 16'h0000)
    );

    // A zero output implies the adder result is also zero.
    check_zero_out_implies_zero_sum: assert property (
        @(posedge clk) (out == 16'h0000) |-> ((a + b) == 16'h0000)
    );

    // Output bit 0 always matches bit 0 of the adder result.
    check_lsb_matches_sum_lsb: assert property (
        @(posedge clk) (out[0] == (a[0] ^ b[0]))
    );

    // For nonzero shifts, the shifted-off low bits remain equal to the adder result.
    check_shifted_off_low_bits_unchanged: assert property (
        @(posedge clk) (shift != 4'd0) |-> ((out & ((16'h0001 << shift) - 16'h0001)) == ((a + b) & ((16'h0001 << shift) - 16'h0001)))
    );

endmodule

rtl:
module DCSC(
	input CLK1, CLK0,
	input SEL1, SEL0,
	input MODESEL,
	output DCSOUT
);
	parameter DCSMODE = "POS";  // Default DCSMODE is "POS"

	reg DCS1, DCS0;   // Intermediate registers
	wire DCS_OR, DCS_XOR, DCS_AND;

	// Generate intermediate signals
	assign DCS_OR = CLK1 | CLK0;
	assign DCS_XOR = CLK1 ^ CLK0;
	assign DCS_AND = CLK1 & CLK0;

	// Generate DCSOUT based on MODESEL and SEL1/SEL0
	always @(*) begin
		if (MODESEL) begin
			DCS1 <= DCS_AND;
			DCS0 <= DCS_AND;
		end else begin
			if (SEL1 && !SEL0) begin
				DCS1 <= CLK1;
				DCS0 <= DCS_AND;
			end else if (!SEL1 && SEL0) begin
				DCS1 <= DCS_AND;
				DCS0 <= CLK0;
			end else if (SEL1 && SEL0) begin
				DCS1 <= DCS_OR;
				DCS0 <= DCS_AND;
			end else begin
				DCS1 <= DCS_XOR;
				DCS0 <= DCS_AND;
			end
		end
	end

	// Invert DCSOUT if DCSMODE is "NEG"
	assign DCSOUT = (DCSMODE == "NEG") ? (~DCS0) : (DCS1);  // Use DCS1 and DCS0 to generate the final DCSOUT

endmodule

sva:
module DCSC_sva #(
    parameter DCSMODE = "POS"
) (
    input logic CLK1,
    input logic CLK0,
    input logic SEL1,
    input logic SEL0,
    input logic MODESEL,
    input logic DCSOUT
);

    wire DCS_OR;
    wire DCS_XOR;
    wire DCS_AND;

    assign DCS_OR  = CLK1 | CLK0;
    assign DCS_XOR = CLK1 ^ CLK0;
    assign DCS_AND = CLK1 & CLK0;

    // Sample on both clock inputs; the RTL has no reset and is combinational.
    generate
        if (DCSMODE == "NEG") begin : gen_neg

            // MODESEL forces the inverted AND path.
            check_neg_modesel_forces_inv_and: assert property (
                @(posedge CLK1 or negedge CLK1 or posedge CLK0 or negedge CLK0)
                MODESEL |-> (DCSOUT == ~DCS_AND)
            );

            // SEL1=1, SEL0=0 still drives inverted AND in NEG mode.
            check_neg_sel10_forces_inv_and: assert property (
                @(posedge CLK1 or negedge CLK1 or posedge CLK0 or negedge CLK0)
                (!MODESEL && SEL1 && !SEL0) |-> (DCSOUT == ~DCS_AND)
            );

            // SEL1=0, SEL0=1 drives inverted CLK0 in NEG mode.
            check_neg_sel01_forces_inv_clk0: assert property (
                @(posedge CLK1 or negedge CLK1 or posedge CLK0 or negedge CLK0)
                (!MODESEL && !SEL1 && SEL0) |-> (DCSOUT == ~CLK0)
            );

            // SEL1=1, SEL0=1 still drives inverted AND in NEG mode.
            check_neg_sel11_forces_inv_and: assert property (
                @(posedge CLK1 or negedge CLK1 or posedge CLK0 or negedge CLK0)
                (!MODESEL && SEL1 && SEL0) |-> (DCSOUT == ~DCS_AND)
            );

            // SEL1=0, SEL0=0 still drives inverted AND in NEG mode.
            check_neg_sel00_forces_inv_and: assert property (
                @(posedge CLK1 or negedge CLK1 or posedge CLK0 or negedge CLK0)
                (!MODESEL && !SEL1 && !SEL0) |-> (DCSOUT == ~DCS_AND)
            );

        end else begin : gen_pos

            // MODESEL forces the AND path.
            check_pos_modesel_forces_and: assert property (
                @(posedge CLK1 or negedge CLK1 or posedge CLK0 or negedge CLK0)
                MODESEL |-> (DCSOUT == DCS_AND)
            );

            // SEL1=1, SEL0=0 routes CLK1 to the output.
            check_pos_sel10_routes_clk1: assert property (
                @(posedge CLK1 or negedge CLK1 or posedge CLK0 or negedge CLK0)
                (!MODESEL && SEL1 && !SEL0) |-> (DCSOUT == CLK1)
            );

            // SEL1=0, SEL0=1 routes the AND path to the output.
            check_pos_sel01_routes_and: assert property (
                @(posedge CLK1 or negedge CLK1 or posedge CLK0 or negedge CLK0)
                (!MODESEL && !SEL1 && SEL0) |-> (DCSOUT == DCS_AND)
            );

            // SEL1=1, SEL0=1 routes the OR path to the output.
            check_pos_sel11_routes_or: assert property (
                @(posedge CLK1 or negedge CLK1 or posedge CLK0 or negedge CLK0)
                (!MODESEL && SEL1 && SEL0) |-> (DCSOUT == DCS_OR)
            );

            // SEL1=0, SEL0=0 routes the XOR path to the output.
            check_pos_sel00_routes_xor: assert property (
                @(posedge CLK1 or negedge CLK1 or posedge CLK0 or negedge CLK0)
                (!MODESEL && !SEL1 && !SEL0) |-> (DCSOUT == DCS_XOR)
            );

        end
    endgenerate

endmodule

