module nand4bb (
    Y  ,
    A_N,
    B_N,
    C  ,
    D
);

    // Module ports
    output Y  ;
    input  A_N;
    input  B_N;
    input  C  ;
    input  D  ;

    // Local signals
    wire nand0_out;
    wire nand1_out;
    wire nand2_out;
    wire or0_out_Y;

    //   Name   Output     Other arguments
    nand nand0 (nand0_out, A_N, B_N);
    nand nand1 (nand1_out, C, D);
    nand nand2 (nand2_out, nand0_out, nand1_out);
    or   or0   (or0_out_Y, nand2_out, nand2_out);
    buf  buf0  (Y        , or0_out_Y          );

endmodule

sva:
module nand4bb_sva (
    input logic clk,
    input logic Y,
    input logic A_N,
    input logic B_N,
    input logic C,
    input logic D
);

    // Y implements (A_N & B_N) | (C & D).
    check_y_matches_boolean_function: assert property (
        @(posedge clk) Y == ((A_N & B_N) | (C & D))
    );

    // A_N and B_N both high force Y high.
    check_y_high_when_ab_high: assert property (
        @(posedge clk) (A_N & B_N) |-> (Y == 1'b1)
    );

    // C and D both high force Y high.
    check_y_high_when_cd_high: assert property (
        @(posedge clk) (C & D) |-> (Y == 1'b1)
    );

    // If neither input pair is high, Y must be low.
    check_y_low_when_no_pair_high: assert property (
        @(posedge clk) !((A_N & B_N) | (C & D)) |-> (Y == 1'b0)
    );

    // A high Y requires at least one high input pair.
    check_y_high_requires_ab_or_cd: assert property (
        @(posedge clk) (Y == 1'b1) |-> ((A_N & B_N) | (C & D))
    );

endmodule

module max3_sva (
    input logic [31:0] A,
    input logic [31:0] B,
    input logic [31:0] C,
    input logic [31:0] X
);

    // If A is strictly greater than both B and C, X must select A.
    check_select_a_when_a_is_strict_max: assert property (
        @($global_clock) ((A > B) && (A > C)) |-> (X == A)
    );

    // If B is at least A and strictly greater than C, X must select B.
    check_select_b_when_b_is_max: assert property (
        @($global_clock) ((B >= A) && (B > C)) |-> (X == B)
    );

    // If C is at least as large as both A and B, X must select C.
    check_select_c_when_c_is_max_or_tied: assert property (
        @($global_clock) ((C >= A) && (C >= B)) |-> (X == C)
    );

    // X must never be less than A.
    check_x_not_less_than_a: assert property (
        @($global_clock) (X >= A)
    );

    // X must never be less than B.
    check_x_not_less_than_b: assert property (
        @($global_clock) (X >= B)
    );

    // X must never be less than C.
    check_x_not_less_than_c: assert property (
        @($global_clock) (X >= C)
    );

    // X must always equal one of the three inputs.
    check_x_matches_one_input: assert property (
        @($global_clock) ((X == A) || (X == B) || (X == C))
    );

endmodule

module calculator_sva (
    input logic [7:0] A,
    input logic [7:0] B,
    input logic [2:0] op,
    input logic [7:0] Z
);

    // No explicit clock or reset exists in the RTL; sample on the global formal clock.
    // DUT behavior is purely combinational: A, B, and op fully determine Z.

    // Z must match the full case-based calculator function.
    check_functional_case_mapping: assert property (
        @($global_clock)
        Z == ((op == 3'b000) ? (A + B) :
              (op == 3'b001) ? (A - B) :
              (op == 3'b010) ? ((A * B) & 8'hFF) :
              (op == 3'b011) ? ((B == 8'h00) ? 8'h00 : (A / B)) :
                               8'h00)
    );

    // Addition opcode drives Z to A plus B.
    check_addition_result: assert property (
        @($global_clock) (op == 3'b000) |-> (Z == (A + B))
    );

    // Subtraction opcode drives Z to A minus B.
    check_subtraction_result: assert property (
        @($global_clock) (op == 3'b001) |-> (Z == (A - B))
    );

    // Multiplication opcode drives Z to the low 8 bits of the product.
    check_multiplication_result: assert property (
        @($global_clock) (op == 3'b010) |-> (Z == ((A * B) & 8'hFF))
    );

    // Division by zero returns zero.
    check_divide_by_zero_result: assert property (
        @($global_clock) ((op == 3'b011) && (B == 8'h00)) |-> (Z == 8'h00)
    );

    // Division with nonzero divisor returns the quotient.
    check_division_result: assert property (
        @($global_clock) ((op == 3'b011) && (B != 8'h00)) |-> (Z == (A / B))
    );

    // Unsupported opcodes drive zero.
    check_invalid_opcode_result: assert property (
        @($global_clock) (op[2] == 1'b1) |-> (Z == 8'h00)
    );

endmodule

module counter_sva (
    input logic clk,
    input logic start,
    input logic [2:0] count
);

    // Count increments by one when start is high below seven.
    check_count_increments: assert property (
        @(posedge clk) (start && (count != 3'd7)) |=> (count == ($past(count) + 3'd1))
    );

    // Count wraps to zero when start is high at seven.
    check_count_wraps_at_seven: assert property (
        @(posedge clk) (start && (count == 3'd7)) |=> (count == 3'd0)
    );

    // Count holds its value when start is low.
    check_count_holds_when_start_low: assert property (
        @(posedge clk) (!start) |=> (count == $past(count))
    );

    // Next-state behavior always matches the RTL update rule.
    check_count_next_state_rule: assert property (
        @(posedge clk) 1'b1 |=> (
            count == ($past(start) ? (($past(count) == 3'd7) ? 3'd0 : ($past(count) + 3'd1)) : $past(count))
        )
    );

endmodule

