module multiplexer #(parameter N = 1) (
    input ctrl,
    input [N-1:0] D0,
    input [N-1:0] D1,
    output [N-1:0] S
);

genvar i;
generate
    for (i = 0; i < N; i = i + 1) begin : mux_loop
        assign S[i] = (ctrl == 1'b0) ? D0[i] : D1[i];
    end
endgenerate

endmodule

sva:
module multiplexer_sva #(parameter N = 1) (
    input logic clk,
    input logic ctrl,
    input logic [N-1:0] D0,
    input logic [N-1:0] D1,
    input logic [N-1:0] S
);

    // Sampling clock only; the RTL has no clock or reset.
    // The DUT is a combinational N-bit 2:1 mux controlled by ctrl.

    // S matches the implemented mux expression on every sample.
    check_mux_function: assert property (
        @(posedge clk) disable iff (1'b0)
        S === ((ctrl == 1'b0) ? D0 : D1)
    );

    // When ctrl is low, S selects D0.
    check_select_d0: assert property (
        @(posedge clk) disable iff (1'b0)
        (ctrl === 1'b0) |-> (S === D0)
    );

    // When ctrl is high, S selects D1.
    check_select_d1: assert property (
        @(posedge clk) disable iff (1'b0)
        (ctrl === 1'b1) |-> (S === D1)
    );

    // If ctrl stays low and D0 is stable, S stays stable.
    check_stable_when_d0_selected: assert property (
        @(posedge clk) disable iff (1'b0)
        (ctrl === 1'b0) && $stable(ctrl) && $stable(D0) |-> $stable(S)
    );

    // If ctrl stays high and D1 is stable, S stays stable.
    check_stable_when_d1_selected: assert property (
        @(posedge clk) disable iff (1'b0)
        (ctrl === 1'b1) && $stable(ctrl) && $stable(D1) |-> $stable(S)
    );

endmodule

rtl:
module full_adder (sum, carry_out, a, b, carry_in);
	output sum, carry_out;
	input a, b, carry_in;

	assign sum = a ^ b ^ carry_in;
	assign carry_out = (a & b) | (a & carry_in) | (b & carry_in);
endmodule

module four_bit_adder (A, B, C);
	input [3:0] A, B;
	output [4:0] C;

	wire [3:0] sum;
	wire [4:0] carry;

	full_adder fa0 (sum[0], carry[1], A[0], B[0], 1'b0);
	full_adder fa1 (sum[1], carry[2], A[1], B[1], carry[1]);
	full_adder fa2 (sum[2], carry[3], A[2], B[2], carry[2]);
	full_adder fa3 (sum[3], carry[4], A[3], B[3], carry[3]);

	assign C[0] = sum[0];
	assign C[1] = sum[1];
	assign C[2] = sum[2];
	assign C[3] = sum[3];
	assign C[4] = carry[4];
endmodule

sva:
module four_bit_adder_sva (
    input logic       clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [4:0] C
);

    // RTL is combinational with no reset; sample behavior on clk.

    // The 5-bit output matches the zero-extended sum of A and B.
    check_total_sum: assert property (
        @(posedge clk) C == ({1'b0, A} + {1'b0, B})
    );

    // Bit 0 is the XOR of the least-significant input bits.
    check_sum_bit0: assert property (
        @(posedge clk) C[0] == (A[0] ^ B[0])
    );

    // Bit 1 includes the carry generated by bit 0.
    check_sum_bit1: assert property (
        @(posedge clk) C[1] == (A[1] ^ B[1] ^ (A[0] & B[0]))
    );

    // Bit 2 includes the propagated carry from bits 1:0.
    check_sum_bit2: assert property (
        @(posedge clk) C[2] == (A[2] ^ B[2] ^
            ((A[1] & B[1]) | ((A[1] ^ B[1]) & (A[0] & B[0]))))
    );

    // Bit 3 includes the propagated carry from bits 2:0.
    check_sum_bit3: assert property (
        @(posedge clk) C[3] == (A[3] ^ B[3] ^
            ((A[2] & B[2]) |
             ((A[2] ^ B[2]) &
              ((A[1] & B[1]) | ((A[1] ^ B[1]) & (A[0] & B[0]))))))
    );

    // Carry out is the final carry of the ripple-adder chain.
    check_carry_out: assert property (
        @(posedge clk) C[4] == (
            (A[3] & B[3]) |
            ((A[3] ^ B[3]) &
             ((A[2] & B[2]) |
              ((A[2] ^ B[2]) &
               ((A[1] & B[1]) | ((A[1] ^ B[1]) & (A[0] & B[0]))))))
        )
    );

    // Adding zero on A passes B through with no carry.
    check_zero_plus_b: assert property (
        @(posedge clk) (A == 4'b0000) |-> (C == {1'b0, B})
    );

    // Adding zero on B passes A through with no carry.
    check_a_plus_zero: assert property (
        @(posedge clk) (B == 4'b0000) |-> (C == {1'b0, A})
    );

    // The all-ones corner case produces decimal 30.
    check_max_plus_max: assert property (
        @(posedge clk) ((A == 4'b1111) && (B == 4'b1111)) |-> (C == 5'b11110)
    );

endmodule

