module sky130_fd_sc_ls__dlrtn_1_assertions (
    input logic Q,
    input logic RESET_B,
    input logic D,
    input logic GATE_N,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB
);

    // No RTL clock is present; assertions sample on $global_clock.
    // RESET_B is active-high in this RTL.

    // RESET_B high has highest priority and drives Q low.
    check_reset_forces_q_low: assert property (
        @($global_clock) RESET_B |-> (Q == 1'b0)
    );

    // With reset inactive, GATE_N high makes Q follow D.
    check_gate_high_passes_d: assert property (
        @($global_clock) disable iff (RESET_B) GATE_N |-> (Q == D)
    );

    // With reset inactive, GATE_N low forces Q high.
    check_gate_low_forces_q_high: assert property (
        @($global_clock) disable iff (RESET_B) !GATE_N |-> (Q == 1'b1)
    );

    // With reset inactive, Q low can only come from passing D=0.
    check_q_low_requires_gate_high_and_d_low: assert property (
        @($global_clock) disable iff (RESET_B) (Q == 1'b0) |-> (GATE_N && !D)
    );

    // Q always matches the implemented combinational truth table.
    check_q_matches_truth_table: assert property (
        @($global_clock) Q == (RESET_B ? 1'b0 : (GATE_N ? D : 1'b1))
    );

endmodule

module binary_counter_sva (
    input logic clk,
    input logic rst,
    input logic test_mode,
    input logic up,
    input logic down,
    input logic [3:0] count
);

    // Active-low reset forces the count to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) !rst |-> (count == 4'h0)
    );

    // Normal mode increments every cycle with wraparound.
    check_normal_mode_increment: assert property (
        @(posedge clk) disable iff (!rst)
        (!test_mode) |=> (count == (($past(count) == 4'hF) ? 4'h0 : ($past(count) + 4'd1)))
    );

    // In test mode, up increments the count and has priority over down.
    check_test_mode_up_increment: assert property (
        @(posedge clk) disable iff (!rst)
        (test_mode && up) |=> (count == (($past(count) == 4'hF) ? 4'h0 : ($past(count) + 4'd1)))
    );

    // In test mode, down decrements the count when up is not asserted.
    check_test_mode_down_decrement: assert property (
        @(posedge clk) disable iff (!rst)
        (test_mode && !up && down) |=> (count == (($past(count) == 4'h0) ? 4'hF : ($past(count) - 4'd1)))
    );

    // In test mode with no direction request, the count holds.
    check_test_mode_idle_hold: assert property (
        @(posedge clk) disable iff (!rst)
        (test_mode && !up && !down) |=> (count == $past(count))
    );

endmodule

