assign Z1 = OE ? D1 : 1'b0;
assign Z2 = OE ? D2 : 1'b0;
assign Z3 = OE ? D3 : 1'b0;

assign Y = (S == 2'b00) ? Z0 :
           (S == 2'b01) ? Z1 :
           (S == 2'b10) ? Z2 :
           (S == 2'b11) ? Z3 : 1'b0;

