module priority_encoder (
    input [3:0] I,
    output reg [1:0] encoded
);

always @* begin
    case (I)
        4'b0001: encoded = 2'b00;
        4'b0010: encoded = 2'b01;
        4'b0100: encoded = 2'b10;
        4'b1000: encoded = 2'b11;
        default: encoded = 2'b00;
    endcase
end

endmodule

module adder_subtractor (
    input [3:0] A,
    input [3:0] B,
    input SUB,
    output reg [3:0] result
);

always @* begin
    if (SUB) begin
        result = A - B;
    end else begin
        result = A + B;
    end
end

endmodule

module functional_module (
    input [1:0] encoded,
    input [3:0] adder_subtractor_output,
    output reg [3:0] result
);

always @* begin
    case (encoded)
        2'b00: result = adder_subtractor_output;
        2'b01: result = adder_subtractor_output + 1;
        2'b10: result = adder_subtractor_output + 2;
        2'b11: result = adder_subtractor_output + 3;
        default: result = adder_subtractor_output;
    endcase
end

endmodule

module top_module (
    input [3:0] I,
    input [3:0] A,
    input [3:0] B,
    input SUB,
    output [3:0] result
);

wire [1:0] encoded;
wire [3:0] adder_subtractor_output;

priority_encoder pe (
    .I(I),
    .encoded(encoded)
);

adder_subtractor as (
    .A(A),
    .B(B),
    .SUB(SUB),
    .result(adder_subtractor_output)
);

functional_module fm (
    .encoded(encoded),
    .adder_subtractor_output(adder_subtractor_output),
    .result(result)
);

endmodule

sva:
module top_module_sva (
    input logic [3:0] I,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic SUB,
    input logic [3:0] result
);

    // No explicit clock or reset exists in the RTL; sample combinational behavior on $global_clock.

    // I=0001 selects the base adder/subtractor result.
    check_result_i_0001: assert property (
        @($global_clock) (I == 4'b0001) |-> (result == (SUB ? (A - B) : (A + B)))
    );

    // I=0010 selects the base adder/subtractor result plus 1.
    check_result_i_0010: assert property (
        @($global_clock) (I == 4'b0010) |-> (result == ((SUB ? (A - B) : (A + B)) + 4'd1))
    );

    // I=0100 selects the base adder/subtractor result plus 2.
    check_result_i_0100: assert property (
        @($global_clock) (I == 4'b0100) |-> (result == ((SUB ? (A - B) : (A + B)) + 4'd2))
    );

    // I=1000 selects the base adder/subtractor result plus 3.
    check_result_i_1000: assert property (
        @($global_clock) (I == 4'b1000) |-> (result == ((SUB ? (A - B) : (A + B)) + 4'd3))
    );

    // All other I values use the encoder default and add no offset.
    check_result_i_default: assert property (
        @($global_clock)
        ((I != 4'b0001) && (I != 4'b0010) && (I != 4'b0100) && (I != 4'b1000))
        |-> (result == (SUB ? (A - B) : (A + B)))
    );

endmodule

