reg [7:0] not_reg;
reg [7:0] zero_reg;

always @ (posedge CLK or negedge RST)
begin
    if (!RST)
    begin
        shift_reg <= 8'b0;
        not_reg <= 8'b0;
        zero_reg <= 8'b0;
    end
    else if (ENA)
    begin
        case ({OPT, KEY})
            8'b00000010: shift_reg <= {RGA[6:0], 1'b0};
            8'b00000000: shift_reg <= {1'b0, RGA[7:1]};
            8'b00000011: shift_reg <= {RGA[5:0], 2'b00};
            8'b00000001: shift_reg <= {2'b00, RGA[7:2]};
            8'b00000100: not_reg <= ~RGA;
            8'b00000010: zero_reg <= 8'b0;
            default: shift_reg <= RGA;
        endcase
    end
end

always @*
begin
    RGZ = RGB ? not_reg : (KEY == 2'b10 ? zero_reg : shift_reg);
end

endmodule

sva:
module bridge_sva (
    input logic [7:0] RGA,
    input logic [0:0] RGB,
    input logic [7:0] OPT,
    input logic [1:0] KEY,
    input logic CLK,
    input logic RST,
    input logic ENA,
    input logic [7:0] RGZ,
    input logic [7:0] shift_reg,
    input logic [7:0] not_reg,
    input logic [7:0] zero_reg
);

    // Reset clears all registers and the output.
    check_reset_clears_state: assert property (
        @(posedge CLK)
        !RST |-> (shift_reg == 8'h00 && not_reg == 8'h00 && zero_reg == 8'h00 && RGZ == 8'h00)
    );

    // ENA low leaves all registers unchanged.
    check_hold_when_disabled: assert property (
        @(posedge CLK) disable iff (!RST)
        (!ENA) |=> ($stable(shift_reg) && $stable(not_reg) && $stable(zero_reg))
    );

    // OPT=0, KEY=2 updates shift_reg with a 1-bit left shift.
    check_shift_left_1: assert property (
        @(posedge CLK) disable iff (!RST)
        (ENA && OPT == 8'h00 && KEY == 2'b10) |=> (shift_reg == {$past(RGA[6:0]), 1'b0} &&
                                                    $stable(not_reg) &&
                                                    $stable(zero_reg))
    );

    // OPT=0, KEY=0 updates shift_reg with a 1-bit right shift.
    check_shift_right_1: assert property (
        @(posedge CLK) disable iff (!RST)
        (ENA && OPT == 8'h00 && KEY == 2'b00) |=> (shift_reg == {1'b0, $past(RGA[7:1])} &&
                                                    $stable(not_reg) &&
                                                    $stable(zero_reg))
    );

    // OPT=0, KEY=3 updates shift_reg with a 2-bit left shift.
    check_shift_left_2: assert property (
        @(posedge CLK) disable iff (!RST)
        (ENA && OPT == 8'h00 && KEY == 2'b11) |=> (shift_reg == {$past(RGA[5:0]), 2'b00} &&
                                                    $stable(not_reg) &&
                                                    $stable(zero_reg))
    );

    // OPT=0, KEY=1 updates shift_reg with a 2-bit right shift.
    check_shift_right_2: assert property (
        @(posedge CLK) disable iff (!RST)
        (ENA && OPT == 8'h00 && KEY == 2'b01) |=> (shift_reg == {2'b00, $past(RGA[7:2])} &&
                                                    $stable(not_reg) &&
                                                    $stable(zero_reg))
    );

    // OPT=1, KEY=0 updates not_reg with bitwise inversion of RGA.
    check_not_load: assert property (
        @(posedge CLK) disable iff (!RST)
        (ENA && OPT == 8'h01 && KEY == 2'b00) |=> (not_reg == ~$past(RGA) &&
                                                    $stable(shift_reg) &&
                                                    $stable(zero_reg))
    );

    // All other enabled cases load raw RGA into shift_reg.
    check_default_load: assert property (
        @(posedge CLK) disable iff (!RST)
        (ENA && !(OPT == 8'h00) && !((OPT == 8'h01) && (KEY == 2'b00))) |=> (shift_reg == $past(RGA) &&
                                                                               $stable(not_reg) &&
                                                                               $stable(zero_reg))
    );

    // RGB high selects not_reg onto RGZ.
    check_rgz_selects_not_reg: assert property (
        @(posedge CLK) disable iff (!RST)
        (RGB == 1'b1) |-> (RGZ == not_reg)
    );

    // RGB low with KEY=2 selects zero_reg onto RGZ.
    check_rgz_selects_zero_reg: assert property (
        @(posedge CLK) disable iff (!RST)
        (RGB == 1'b0 && KEY == 2'b10) |-> (RGZ == zero_reg)
    );

    // Otherwise RGZ reflects shift_reg.
    check_rgz_selects_shift_reg: assert property (
        @(posedge CLK) disable iff (!RST)
        (RGB == 1'b0 && KEY != 2'b10) |-> (RGZ == shift_reg)
    );

endmodule

bind bridge bridge_sva bridge_sva_i (
    .RGA(RGA),
    .RGB(RGB),
    .OPT(OPT),
    .KEY(KEY),
    .CLK(CLK),
    .RST(RST),
    .ENA(ENA),
    .RGZ(RGZ),
    .shift_reg(shift_reg),
    .not_reg(not_reg),
    .zero_reg(zero_reg)
);

rtl:
module shift_register (
  input clk,
  input reset,
  input load,
  input shift,
  input [7:0] data_in,
  input [7:0] parallel_in,
  output [7:0] data_out
);

  reg [7:0] shift_reg;
  wire [7:0] shifted_data;

  assign shifted_data = {shift_reg[6:0], 1'b0};

  always @(posedge clk) begin
    if (reset) begin
      shift_reg <= 8'b0;
    end else if (load) begin
      shift_reg <= parallel_in;
    end else if (shift) begin
      shift_reg <= shifted_data;
    end else begin
      shift_reg <= data_in;
    end
  end

  assign data_out = shift_reg;

endmodule

sva:
module shift_register_sva (
    input logic clk,
    input logic reset,
    input logic load,
    input logic shift,
    input logic [7:0] data_in,
    input logic [7:0] parallel_in,
    input logic [7:0] data_out
);

    // Reset clears the register by the next clock.
    check_reset_clears_register: assert property (
        @(posedge clk) reset |=> (data_out == 8'h00)
    );

    // Load captures parallel_in when shift is low.
    check_load_captures_parallel_in: assert property (
        @(posedge clk) disable iff (reset)
        (load && !shift) |=> (data_out == $past(parallel_in))
    );

    // Load has priority over shift when both are high.
    check_load_priority_over_shift: assert property (
        @(posedge clk) disable iff (reset)
        (load && shift) |=> (data_out == $past(parallel_in))
    );

    // Shift moves data left and inserts 0 into bit 0.
    check_shift_left_zero_fill: assert property (
        @(posedge clk) disable iff (reset)
        (!load && shift) |=> (data_out == {$past(data_out[6:0]), 1'b0})
    );

    // Without load or shift, data_in is captured.
    check_default_captures_data_in: assert property (
        @(posedge clk) disable iff (reset)
        (!load && !shift) |=> (data_out == $past(data_in))
    );

endmodule

rtl:
module binary_counter(clk, rst, count);
  input clk, rst;
  output reg [3:0] count;

  always @(posedge clk) begin
    if(rst) begin
      count <= 4'b0000;
    end else if(count == 4'b1111) begin
      count <= 4'b0000;
    end else begin
      count <= count + 1;
    end
  end
endmodule

sva:
module binary_counter_sva (
    input logic       clk,
    input logic       rst,
    input logic [3:0] count
);

    // Reset restarts the counter at zero.
    check_post_reset_zero: assert property (
        @(posedge clk) disable iff (rst)
        !$initstate && $past(rst) |-> (count == 4'h0)
    );

    // Counts below 15 increment by one each cycle.
    check_increment_from_non_max: assert property (
        @(posedge clk) disable iff (rst)
        !$initstate && !$past(rst) && ($past(count) != 4'hF) |-> (count == ($past(count) + 4'h1))
    );

    // Count 15 wraps back to zero.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (rst)
        !$initstate && !$past(rst) && ($past(count) == 4'hF) |-> (count == 4'h0)
    );

    // Zero can only result from reset or wraparound.
    check_zero_origin: assert property (
        @(posedge clk) disable iff (rst)
        !$initstate && (count == 4'h0) |-> ($past(rst) || ($past(count) == 4'hF))
    );

    // Any non-zero value comes from incrementing the prior count.
    check_nonzero_origin: assert property (
        @(posedge clk) disable iff (rst)
        !$initstate && (count != 4'h0) |-> (!$past(rst) && (count == ($past(count) + 4'h1)))
    );

endmodule

rtl:
module top_module(
    input clk,
    input reset,  // sync active-high reset
    input load,
    input ena,
    input [3:0] data_in,
    output [3:0] data_out);

    reg [3:0] shift_reg;
    wire [1:0] select;
    wire [3:0] shifted_data;

    // 2-to-4 decoder
    assign select[0] = ~shift_reg[3] & ~shift_reg[2];
    assign select[1] = ~shift_reg[3] & shift_reg[2];

    // 4-bit shift register
    always @(posedge clk) begin
        if (reset) begin
            shift_reg <= 4'b0;
        end else if (load) begin
            shift_reg <= data_in;
        end else if (ena) begin
            shift_reg <= {shift_reg[2:0], shift_reg[3]};
        end
    end

    // 2-to-1 multiplexer
    assign shifted_data = {shift_reg[1:0], 2'b0};
    assign data_out = load ? data_in : (select[1] ? shifted_data : shift_reg);

endmodule

sva:
module top_module_sva(
    input logic clk,
    input logic reset,
    input logic load,
    input logic ena,
    input logic [3:0] data_in,
    input logic [3:0] data_out,
    input logic [3:0] shift_reg,
    input logic [1:0] select,
    input logic [3:0] shifted_data
);

    // Synchronous reset clears the shift register.
    check_reset_clears_shift_reg: assert property (
        @(posedge clk) reset |=> (shift_reg == 4'b0000)
    );

    // Load takes priority and captures data_in.
    check_load_captures_data: assert property (
        @(posedge clk) disable iff (reset)
        load |=> (shift_reg == $past(data_in))
    );

    // Enable rotates the register when load is low.
    check_enable_rotates_shift_reg: assert property (
        @(posedge clk) disable iff (reset)
        (!load && ena) |=> (shift_reg == {$past(shift_reg[2:0]), $past(shift_reg[3])})
    );

    // The register holds its value when idle.
    check_idle_holds_shift_reg: assert property (
        @(posedge clk) disable iff (reset)
        (!load && !ena) |=> (shift_reg == $past(shift_reg))
    );

    // select[0] matches its decoder equation.
    check_select0_decode: assert property (
        @(posedge clk) disable iff (reset)
        (select[0] == (~shift_reg[3] & ~shift_reg[2]))
    );

    // select[1] matches its decoder equation.
    check_select1_decode: assert property (
        @(posedge clk) disable iff (reset)
        (select[1] == (~shift_reg[3] & shift_reg[2]))
    );

    // shifted_data is formed from shift_reg[1:0] with two zeros.
    check_shifted_data_value: assert property (
        @(posedge clk) disable iff (reset)
        (shifted_data == {shift_reg[1:0], 2'b00})
    );

    // data_out follows data_in during load.
    check_data_out_on_load: assert property (
        @(posedge clk) disable iff (reset)
        load |-> (data_out == data_in)
    );

    // data_out selects shifted_data when select[1] is high.
    check_data_out_shifted_path: assert property (
        @(posedge clk) disable iff (reset)
        (!load && select[1]) |-> (data_out == shifted_data)
    );

    // data_out selects shift_reg when select[1] is low.
    check_data_out_register_path: assert property (
        @(posedge clk) disable iff (reset)
        (!load && !select[1]) |-> (data_out == shift_reg)
    );

endmodule

module calculator_sva(
    input logic clk,
    input logic [3:0] a,
    input logic [3:0] b,
    input logic op,
    input logic [3:0] out
);

    // Addition mode drives out to a + b.
    check_addition_result: assert property (
        @(posedge clk) (op == 1'b0) |-> (out == (a + b))
    );

    // Subtraction mode drives out to a - b.
    check_subtraction_result: assert property (
        @(posedge clk) (op == 1'b1) |-> (out == (a - b))
    );

    // Stable inputs keep the sampled output stable.
    check_stable_inputs_stable_output: assert property (
        @(posedge clk) $stable({a, b, op}) |-> $stable(out)
    );

endmodule

rtl:
module chan_mux (
	data0x,
	data1x,
	data2x,
	sel,
	result);

	input [21:0] data0x;
	input [21:0] data1x;
	input [21:0] data2x;
	input [1:0] sel;
	output reg [21:0] result;

	always @(*) begin
		case (sel)
			2'b00: result = data0x;
			2'b01: result = data1x;
			2'b10: result = data2x;
			default: result = 22'hx; // undefined behavior
		endcase
	end

endmodule

sva:
module chan_mux_sva (
    input logic        clk,
    input logic [21:0] data0x,
    input logic [21:0] data1x,
    input logic [21:0] data2x,
    input logic [1:0]  sel,
    input logic [21:0] result
);

    // sel=00 routes data0x to result.
    check_sel_00_routes_data0: assert property (
        @(posedge clk) (sel === 2'b00) |-> (result === data0x)
    );

    // sel=01 routes data1x to result.
    check_sel_01_routes_data1: assert property (
        @(posedge clk) (sel === 2'b01) |-> (result === data1x)
    );

    // sel=10 routes data2x to result.
    check_sel_10_routes_data2: assert property (
        @(posedge clk) (sel === 2'b10) |-> (result === data2x)
    );

    // With sel=00, changes on unselected inputs do not change result.
    check_sel_00_ignores_unselected_inputs: assert property (
        @(posedge clk)
        ((sel === 2'b00) && $stable(sel) && $stable(data0x) && ($changed(data1x) || $changed(data2x)))
        |-> $stable(result)
    );

    // With sel=01, changes on unselected inputs do not change result.
    check_sel_01_ignores_unselected_inputs: assert property (
        @(posedge clk)
        ((sel === 2'b01) && $stable(sel) && $stable(data1x) && ($changed(data0x) || $changed(data2x)))
        |-> $stable(result)
    );

    // With sel=10, changes on unselected inputs do not change result.
    check_sel_10_ignores_unselected_inputs: assert property (
        @(posedge clk)
        ((sel === 2'b10) && $stable(sel) && $stable(data2x) && ($changed(data0x) || $changed(data1x)))
        |-> $stable(result)
    );

    // If sel and all inputs are stable, result remains stable.
    check_result_stable_when_inputs_and_sel_stable: assert property (
        @(posedge clk)
        ($stable(sel) && $stable(data0x) && $stable(data1x) && $stable(data2x))
        |-> $stable(result)
    );

endmodule

rtl:
module XOR_8(
  input [7:0] A,
  input [7:0] B,
  output reg [7:0] Z
);

  always @* begin
    Z = A ^ B;
  end

endmodule

sva:
module XOR_8_sva (
    input logic        clk,
    input logic [7:0]  A,
    input logic [7:0]  B,
    input logic [7:0]  Z
);

    // Z matches the bitwise XOR of A and B.
    check_z_matches_xor: assert property (
        @(posedge clk) Z === (A ^ B)
    );

    // Bit 0 of Z is A[0] XOR B[0].
    check_z_bit0_xor: assert property (
        @(posedge clk) Z[0] === (A[0] ^ B[0])
    );

    // Bit 1 of Z is A[1] XOR B[1].
    check_z_bit1_xor: assert property (
        @(posedge clk) Z[1] === (A[1] ^ B[1])
    );

    // Bit 2 of Z is A[2] XOR B[2].
    check_z_bit2_xor: assert property (
        @(posedge clk) Z[2] === (A[2] ^ B[2])
    );

    // Bit 3 of Z is A[3] XOR B[3].
    check_z_bit3_xor: assert property (
        @(posedge clk) Z[3] === (A[3] ^ B[3])
    );

    // Bit 4 of Z is A[4] XOR B[4].
    check_z_bit4_xor: assert property (
        @(posedge clk) Z[4] === (A[4] ^ B[4])
    );

    // Bit 5 of Z is A[5] XOR B[5].
    check_z_bit5_xor: assert property (
        @(posedge clk) Z[5] === (A[5] ^ B[5])
    );

    // Bit 6 of Z is A[6] XOR B[6].
    check_z_bit6_xor: assert property (
        @(posedge clk) Z[6] === (A[6] ^ B[6])
    );

    // Bit 7 of Z is A[7] XOR B[7].
    check_z_bit7_xor: assert property (
        @(posedge clk) Z[7] === (A[7] ^ B[7])
    );

    // Equal inputs produce zero.
    check_equal_inputs_zero: assert property (
        @(posedge clk) (A == B) |-> (Z == 8'h00)
    );

    // Zero on B passes A through.
    check_b_zero_passthrough_a: assert property (
        @(posedge clk) (B == 8'h00) |-> (Z === A)
    );

    // Zero on A passes B through.
    check_a_zero_passthrough_b: assert property (
        @(posedge clk) (A == 8'h00) |-> (Z === B)
    );

    // Complementary inputs produce all ones.
    check_complement_inputs_all_ones: assert property (
        @(posedge clk) (A == ~B) |-> (Z == 8'hFF)
    );

    // Stable inputs keep Z stable across samples.
    check_stable_inputs_stable_output: assert property (
        @(posedge clk) ($stable(A) && $stable(B)) |-> $stable(Z)
    );

endmodule

rtl:
module four_bit_adder(
  input [3:0] A,
  input [3:0] B,
  input Cin,
  output [3:0] Sum,
  output Cout
);

  wire [4:0] sum_wire;

  assign sum_wire = A + B + Cin;
  assign Cout = sum_wire[4];
  assign Sum = sum_wire[3:0];

endmodule

sva:
module four_bit_adder_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic       Cin,
    input logic [3:0] Sum,
    input logic       Cout
);

    // No RTL clock or reset; sample this combinational logic on Jasper's global clock.

    // Combined carry and sum must equal the 5-bit addition of A, B, and Cin.
    check_combined_addition: assert property (
        @($global_clock) {Cout, Sum} == ({1'b0, A} + {1'b0, B} + Cin)
    );

    // The least-significant sum bit must match the LSB full-adder equation.
    check_lsb_sum: assert property (
        @($global_clock) Sum[0] == (A[0] ^ B[0] ^ Cin)
    );

    // Zero operands with no carry-in must produce a zero result.
    check_zero_result: assert property (
        @($global_clock) ((A == 4'b0000) && (B == 4'b0000) && (Cin == 1'b0)) |-> ((Sum == 4'b0000) && (Cout == 1'b0))
    );

    // Carry-out must be asserted exactly when the 5-bit total is 16 or more.
    check_carry_threshold: assert property (
        @($global_clock) Cout == (({1'b0, A} + {1'b0, B} + Cin) >= 5'd16)
    );

endmodule

rtl:
module johnson_counter (
    input clk,
    input rst,
    input ena,
    output reg [3:0] q
);

reg [3:0] q_next;

always @(posedge clk) begin
    if (rst) begin
        q <= 4'b0000;
    end
    else if (ena) begin
        q <= q_next;
    end
end

always @(*) begin
    q_next[0] = q[3] ^ ~q[1];
    q_next[1] = q[0] ^ ~q[2];
    q_next[2] = q[1] ^ ~q[3];
    q_next[3] = q[2] ^ ~q[0];
end

endmodule

sva:
module johnson_counter_sva (
    input logic       clk,
    input logic       rst,
    input logic       ena,
    input logic [3:0] q
);

    // Synchronous active-high reset clears q on the next clock.
    check_reset_clears_q: assert property (
        @(posedge clk) rst |=> (q == 4'b0000)
    );

    // When disabled and not in reset, q holds its previous value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (rst) (!ena) |=> (q == $past(q))
    );

    // When enabled and not in reset, q[0] follows the RTL next-state equation.
    check_update_q0_when_enabled: assert property (
        @(posedge clk) disable iff (rst) ena |=> (q[0] == ($past(q[3]) ^ (~$past(q[1]))))
    );

    // When enabled and not in reset, q[1] follows the RTL next-state equation.
    check_update_q1_when_enabled: assert property (
        @(posedge clk) disable iff (rst) ena |=> (q[1] == ($past(q[0]) ^ (~$past(q[2]))))
    );

    // When enabled and not in reset, q[2] follows the RTL next-state equation.
    check_update_q2_when_enabled: assert property (
        @(posedge clk) disable iff (rst) ena |=> (q[2] == ($past(q[1]) ^ (~$past(q[3]))))
    );

    // When enabled and not in reset, q[3] follows the RTL next-state equation.
    check_update_q3_when_enabled: assert property (
        @(posedge clk) disable iff (rst) ena |=> (q[3] == ($past(q[2]) ^ (~$past(q[0]))))
    );

endmodule

rtl:
module alu_04(output reg [3:0]Z, input [1:0]op, input [3:0] A, B, C);
    always @(*)
    begin
        case(op)
            2'b00: Z = A + B + C;
            2'b01: Z = A - B - C;
            2'b10: Z = A & B & C;
            2'b11: Z = A | B | C;
        endcase
    end
endmodule

sva:
module alu_04_sva(
    input logic clk,
    input logic [3:0] Z,
    input logic [1:0] op,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] C
);

    // No reset in RTL; clk is a sampling clock for combinational checks.

    // op 00 selects 4-bit addition of A, B, and C.
    check_addition_result: assert property (
        @(posedge clk) (op == 2'b00) |-> (Z == (A + B + C))
    );

    // op 01 selects 4-bit subtraction of B and C from A.
    check_subtraction_result: assert property (
        @(posedge clk) (op == 2'b01) |-> (Z == (A - B - C))
    );

    // op 10 selects bitwise AND across A, B, and C.
    check_and_result: assert property (
        @(posedge clk) (op == 2'b10) |-> (Z == (A & B & C))
    );

    // op 11 selects bitwise OR across A, B, and C.
    check_or_result: assert property (
        @(posedge clk) (op == 2'b11) |-> (Z == (A | B | C))
    );

    // Stable inputs must keep the sampled output stable.
    check_stable_inputs_hold_output: assert property (
        @(posedge clk) $stable({op, A, B, C}) |-> $stable(Z)
    );

endmodule

rtl:
module alu(a,b,aluc,result
    );
	input wire [31:0] a,b;
	input wire [4:0] aluc;
	output reg [31:0] result;

	always @*
	begin
		case(aluc)
			5'd0:begin
				result=a+b;
			end
			5'd1:begin
				result=a-b;
			end
			5'd2:begin
				result=a&b;
			end
			5'd3:begin
				result=a|b;
			end
			5'd6:begin
				result=b<<a;end
			5'd10:begin
				result=b>>a;end
			5'd8:begin
				result=(b>>a)|({32{b[31]}}<<(32'd32));end
			default:
			begin
				result=0;
			end
		endcase
	end

endmodule

sva:
module alu_sva (
    input logic        clk,
    input logic [31:0] a,
    input logic [31:0] b,
    input logic [4:0]  aluc,
    input logic [31:0] result
);

    // Opcode 0 returns a + b.
    check_add_result: assert property (
        @(posedge clk) disable iff (1'b0)
        (aluc == 5'd0) |-> (result == (a + b))
    );

    // Opcode 1 returns a - b.
    check_sub_result: assert property (
        @(posedge clk) disable iff (1'b0)
        (aluc == 5'd1) |-> (result == (a - b))
    );

    // Opcode 2 returns a & b.
    check_and_result: assert property (
        @(posedge clk) disable iff (1'b0)
        (aluc == 5'd2) |-> (result == (a & b))
    );

    // Opcode 3 returns a | b.
    check_or_result: assert property (
        @(posedge clk) disable iff (1'b0)
        (aluc == 5'd3) |-> (result == (a | b))
    );

    // Opcode 6 returns b shifted left by a.
    check_shift_left_result: assert property (
        @(posedge clk) disable iff (1'b0)
        (aluc == 5'd6) |-> (result == (b << a))
    );

    // Opcode 10 returns b shifted right by a.
    check_shift_right_logical_result: assert property (
        @(posedge clk) disable iff (1'b0)
        (aluc == 5'd10) |-> (result == (b >> a))
    );

    // Opcode 8 returns the RTL's implemented shift expression.
    check_case8_result: assert property (
        @(posedge clk) disable iff (1'b0)
        (aluc == 5'd8) |-> (result == ((b >> a) | ({32{b[31]}} << (32'd32))))
    );

    // Unlisted opcodes drive zero.
    check_default_zero_result: assert property (
        @(posedge clk) disable iff (1'b0)
        ((aluc != 5'd0) &&
         (aluc != 5'd1) &&
         (aluc != 5'd2) &&
         (aluc != 5'd3) &&
         (aluc != 5'd6) &&
         (aluc != 5'd8) &&
         (aluc != 5'd10)) |-> (result == 32'd0)
    );

endmodule

