module test_LEDState(
input					rsi_MRST_reset,	input					csi_MCLK_clk,

output	[23:0]	aso_fled0_data,
output				aso_fled0_valid,

output	[23:0]	aso_fled1_data,
output				aso_fled1_valid,

output	[23:0]	aso_fled2_data,
output				aso_fled2_valid,

output	[23:0]	aso_fled3_data,
output				aso_fled3_valid
);

assign	aso_fled0_valid = 1;
assign	aso_fled0_data = {r_cnt, g_cnt, b_cnt};

assign	aso_fled1_valid = 1;
assign	aso_fled1_data = {g_cnt, b_cnt, r_cnt};

assign	aso_fled2_valid = 1;
assign	aso_fled2_data = {b_cnt, r_cnt, g_cnt};

assign	aso_fled3_valid = 1;
assign	aso_fled3_data = {g_cnt, r_cnt, b_cnt};

reg	[5:0]		state;
reg	[7:0]		r_cnt, g_cnt, b_cnt;
reg	[18:0]	delay_cnt;

always@(posedge csi_MCLK_clk or posedge rsi_MRST_reset)
begin
	if(rsi_MRST_reset) begin
		state <= 0;
		r_cnt <= 0;
		g_cnt <= 0;
		b_cnt <= 0;
		delay_cnt <= 0;
	end
	else begin
		case(state)
			0: begin 
				g_cnt <= 0;
				b_cnt <= 0;
				delay_cnt <= delay_cnt + 1;
				if(delay_cnt == 19'h7FFFF) r_cnt <= r_cnt + 1;
				if(r_cnt == 255) state <= 1;
			end

			1: begin
				delay_cnt <= 0;
				state <= 2;
			end

			2: begin 
				delay_cnt <= delay_cnt + 1;
				if(delay_cnt == 19'h7FFFF) r_cnt <= r_cnt - 1;
				if(r_cnt == 0) state <= 3;
			end

			3: begin
				r_cnt <= 0;
				g_cnt <= 0;
				b_cnt <= 0;
				delay_cnt <= 0;
				state <= 4;
			end

			4: begin 
				delay_cnt <= delay_cnt + 1;
				if(delay_cnt == 19'h7FFFF) g_cnt <= g_cnt + 1;
				if(g_cnt == 255) state <= 5;
			end

			5: begin
				delay_cnt <= 0;
				state <= 6;
			end

			6: begin 
				delay_cnt <= delay_cnt + 1;
				if(delay_cnt == 19'h7FFFF) g_cnt <= g_cnt - 1;
				if(g_cnt == 0) state <= 7;
			end

			7: begin
				r_cnt <= 0;
				g_cnt <= 0;
				b_cnt <= 0;
				delay_cnt <= 0;
				state <= 8;
			end

			8: begin 
				delay_cnt <= delay_cnt + 1;
				if(delay_cnt == 19'h7FFFF) b_cnt <= b_cnt + 1;
				if(b_cnt == 255) state <= 9;
			end

			9: begin
				delay_cnt <= 0;
				state <= 10;
			end

			10: begin 
				delay_cnt <= delay_cnt + 1;
				if(delay_cnt == 19'h7FFFF) b_cnt <= b_cnt - 1;
				if(b_cnt == 0) state <= 11;
			end

			11: begin
				r_cnt <= 0;
				g_cnt <= 0;
				b_cnt <= 0;
				delay_cnt <= 0;
				state <= 0;
			end

			default: begin
				state <= 0;
				r_cnt <= 0;
				g_cnt <= 0;
				b_cnt <= 0;
				delay_cnt <= 0;
			end

		endcase
	end
end

endmodule

module sky130_fd_sc_ls__o21ba (
    X   ,
    A1  ,
    A2  ,
    B1_N
);

    output X   ;
    input  A1  ;
    input  A2  ;
    input  B1_N;

    wire nor0_out  ;
    wire nor1_out_X;

    nor nor0 (nor0_out  , A1, A2         );
    nor nor1 (nor1_out_X, B1_N, nor0_out );
    buf buf0 (X         , nor1_out_X     );

endmodule

sva:
module sky130_fd_sc_ls__o21ba_sva (
    input logic clk,
    input logic X,
    input logic A1,
    input logic A2,
    input logic B1_N
);

    // X matches the implemented NOR/NOR/BUF logic.
    check_function: assert property (
        @(posedge clk) X == ((~B1_N) & (A1 | A2))
    );

    // A high B1_N forces X low.
    check_b1n_high_forces_low: assert property (
        @(posedge clk) (B1_N == 1'b1) |-> (X == 1'b0)
    );

    // With both A inputs low, X must be low.
    check_no_a_inputs_forces_low: assert property (
        @(posedge clk) ((A1 == 1'b0) && (A2 == 1'b0)) |-> (X == 1'b0)
    );

    // With B1_N low and A1 high, X must be high.
    check_a1_high_with_b1n_low_drives_high: assert property (
        @(posedge clk) ((B1_N == 1'b0) && (A1 == 1'b1)) |-> (X == 1'b1)
    );

    // With B1_N low and A2 high, X must be high.
    check_a2_high_with_b1n_low_drives_high: assert property (
        @(posedge clk) ((B1_N == 1'b0) && (A2 == 1'b1)) |-> (X == 1'b1)
    );

    // A high X requires B1_N to be low.
    check_high_output_requires_b1n_low: assert property (
        @(posedge clk) (X == 1'b1) |-> (B1_N == 1'b0)
    );

    // A high X requires at least one A input to be high.
    check_high_output_requires_a_input: assert property (
        @(posedge clk) (X == 1'b1) |-> ((A1 == 1'b1) || (A2 == 1'b1))
    );

    // If B1_N is low and X is low, both A inputs must be low.
    check_low_output_with_b1n_low_requires_no_a_input: assert property (
        @(posedge clk) ((B1_N == 1'b0) && (X == 1'b0)) |-> ((A1 == 1'b0) && (A2 == 1'b0))
    );

endmodule

rtl:
module adder4 (
    input [3:0] A,
    input [3:0] B,
    output [3:0] S,
    output Cout
);

    wire [3:0] C;
    wire [3:0] S1;
    wire [3:0] S2;
    wire [3:0] S3;

    full_adder fa1 (
        .A(A[0]),
        .B(B[0]),
        .Cin(1'b0),
        .S(S1[0]),
        .Cout(C[0])
    );

    full_adder fa2 (
        .A(A[1]),
        .B(B[1]),
        .Cin(C[0]),
        .S(S2[1]),
        .Cout(C[1])
    );

    full_adder fa3 (
        .A(A[2]),
        .B(B[2]),
        .Cin(C[1]),
        .S(S3[2]),
        .Cout(C[2])
    );

    full_adder fa4 (
        .A(A[3]),
        .B(B[3]),
        .Cin(C[2]),
        .S(S[3]),
        .Cout(Cout)
    );

    assign S[0] = S1[0];
    assign S[1] = S2[1];
    assign S[2] = S3[2];
    assign S[3] = S[3];

endmodule
module full_adder (
    input A,
    input B,
    input Cin,
    output S,
    output Cout
);

    assign {Cout, S} = A + B + Cin;

endmodule

sva:
module adder4_sva (
    input logic       clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] S,
    input logic       Cout
);

    // LSB sum is the XOR of A[0] and B[0].
    check_lsb_sum: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0])
    );

    // Bit 1 sum includes the carry from bit 0.
    check_bit1_sum: assert property (
        @(posedge clk) S[1] == (A[1] ^ B[1] ^ (A[0] & B[0]))
    );

    // Bit 2 sum includes the ripple carry from bits 1:0.
    check_bit2_sum: assert property (
        @(posedge clk)
        S[2] == (A[2] ^ B[2] ^
                 ((A[1] & B[1]) |
                  (A[1] & (A[0] & B[0])) |
                  (B[1] & (A[0] & B[0]))))
    );

    // The 4-bit sum and carry-out match zero-extended addition.
    check_full_sum: assert property (
        @(posedge clk) {Cout, S} == ({1'b0, A} + {1'b0, B})
    );

    // Zero on A passes B through with no carry-out.
    check_zero_a_passthrough: assert property (
        @(posedge clk) (A == 4'h0) |-> ({Cout, S} == {1'b0, B})
    );

    // Zero on B passes A through with no carry-out.
    check_zero_b_passthrough: assert property (
        @(posedge clk) (B == 4'h0) |-> ({Cout, S} == {1'b0, A})
    );

    // Adding 0xF and 0xF produces 0x1E.
    check_all_ones_addition: assert property (
        @(posedge clk) ((A == 4'hF) && (B == 4'hF)) |-> ({Cout, S} == 5'h1E)
    );

endmodule

module nand4b_sva (
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic Y,
    input logic VPB,
    input logic VPWR,
    input logic VGND,
    input logic VNB
);

    // If A is low, the NAND output must be high.
    check_a_low_forces_y_high: assert property (
        @($global_clock) (A == 1'b0) |-> (Y == 1'b1)
    );

    // If B is low, the NAND output must be high.
    check_b_low_forces_y_high: assert property (
        @($global_clock) (B == 1'b0) |-> (Y == 1'b1)
    );

    // If C is low, the NAND output must be high.
    check_c_low_forces_y_high: assert property (
        @($global_clock) (C == 1'b0) |-> (Y == 1'b1)
    );

    // If D is low, the NAND output must be high.
    check_d_low_forces_y_high: assert property (
        @($global_clock) (D == 1'b0) |-> (Y == 1'b1)
    );

    // If all four inputs are high, the NAND output must be low.
    check_all_high_forces_y_low: assert property (
        @($global_clock)
        ((A == 1'b1) && (B == 1'b1) && (C == 1'b1) && (D == 1'b1)) |-> (Y == 1'b0)
    );

    // A low output can only occur when all four inputs are high.
    check_y_low_implies_all_high: assert property (
        @($global_clock)
        (Y == 1'b0) |-> ((A == 1'b1) && (B == 1'b1) && (C == 1'b1) && (D == 1'b1))
    );

endmodule

rtl:
module	Register(Clock, Reset, Set, Enable, In, Out);
	parameter				Width = 				32,
							Initial =				{Width{1'bx}},
							AsyncReset =			0,
							AsyncSet =				0,
							ResetValue =			{Width{1'b0}},
							SetValue =				{Width{1'b1}};
	input					Clock, Enable, Reset, Set;
	input	[Width-1:0]		In;
	output reg [Width-1:0]	Out =					Initial;
	generate if (AsyncReset) begin:AR
		if (AsyncSet) begin:AS
			always @ (posedge Clock or posedge Reset or posedge Set) begin
				if (Reset) Out <=					ResetValue;
				else if (Set) Out <=				SetValue;
				else if (Enable) Out <=				In;
			end
		end else begin:SS
			always @ (posedge Clock or posedge Reset) begin
				if (Reset) Out <=					ResetValue;
				else if (Set) Out <=				SetValue;
				else if (Enable) Out <=				In;
			end
		end
	end else begin:SR
		if (AsyncSet) begin:AS
			always @ (posedge Clock or posedge Set) begin
				if (Reset) Out <=					ResetValue;
				else if (Set) Out <=				SetValue;
				else if (Enable) Out <=				In;
			end
		end else begin:SS
			always @ (posedge Clock) begin
				if (Reset) Out <=					ResetValue;
				else if (Set) Out <=				SetValue;
				else if (Enable) Out <=				In;
			end
		end
	end endgenerate
	endmodule

sva:
module Register_sva #(
    parameter               Width = 32,
                            Initial = {Width{1'bx}},
                            AsyncReset = 0,
                            AsyncSet = 0,
                            ResetValue = {Width{1'b0}},
                            SetValue = {Width{1'b1}}
) (
    input  logic             Clock,
    input  logic             Reset,
    input  logic             Set,
    input  logic             Enable,
    input  logic [Width-1:0] In,
    input  logic [Width-1:0] Out
);

generate
    if (!AsyncReset && !AsyncSet) begin : g_sync_sync
        // Reset loads ResetValue on the next sampled cycle.
        check_reset_value: assert property (
            @(posedge Clock) !$initstate && $past(Reset) |-> Out == ResetValue
        );

        // Set loads SetValue when reset was low.
        check_set_value: assert property (
            @(posedge Clock) disable iff (Reset)
            !$initstate && $past(!Reset && Set) |-> Out == SetValue
        );

        // Enable loads In when reset and set were low.
        check_enable_load: assert property (
            @(posedge Clock) disable iff (Reset)
            !$initstate && $past(!Reset && !Set && Enable) |-> Out == $past(In)
        );

        // Out holds its value when no control was active.
        check_hold_value: assert property (
            @(posedge Clock) disable iff (Reset)
            !$initstate && $past(!Reset && !Set && !Enable) |-> Out == $past(Out)
        );

        // Reset has priority over set.
        check_reset_over_set: assert property (
            @(posedge Clock) !$initstate && $past(Reset && Set) |-> Out == ResetValue
        );

    end else if (AsyncReset && !AsyncSet) begin : g_async_reset_sync_set
        // Any sampled reset leaves Out at ResetValue.
        check_async_reset_value: assert property (
            @(posedge Clock) !$initstate && $past(Reset) |-> Out == ResetValue
        );

    end else if (!AsyncReset && AsyncSet) begin : g_sync_reset_async_set
        // A sampled set request leaves Out at SetValue.
        check_async_set_value: assert property (
            @(posedge Clock) disable iff (Reset)
            !$initstate && $past(!Reset && Set) |-> Out == SetValue
        );

        // Set has priority over enable when reset was low.
        check_async_set_over_enable: assert property (
            @(posedge Clock) disable iff (Reset)
            !$initstate && $past(!Reset && Set && Enable) |-> Out == SetValue
        );

    end else begin : g_async_reset_async_set
        // Continuous reset keeps Out at ResetValue.
        check_async_controls_reset_holds_value: assert property (
            @(posedge Clock) !$initstate && Reset && $past(Reset) |-> Out == ResetValue
        );

        // Reset dominates set while both stay asserted.
        check_async_controls_reset_over_set: assert property (
            @(posedge Clock) !$initstate && Reset && Set && $past(Reset && Set) |-> Out == ResetValue
        );
    end
endgenerate

endmodule

rtl:
module up_down_counter (
  input clk,
  input reset,
  input enable,
  output reg [2:0] count
);

  always @(posedge clk, negedge reset) begin
    if (reset == 0) begin
      count <= 3'b0;
    end else if (enable == 1) begin
      count <= count + 1;
    end else begin
      count <= count - 1;
    end
  end

endmodule

sva:
module up_down_counter_sva (
    input logic clk,
    input logic reset,
    input logic enable,
    input logic [2:0] count
);

    // Active-low reset forces count to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) (reset == 1'b0) |-> (count == 3'b000)
    );

    // When enabled, count increments by one on the next clock.
    check_count_increments: assert property (
        @(posedge clk) disable iff (reset == 1'b0)
        (enable == 1'b1) |=> (count == ($past(count) + 3'b001))
    );

    // When not enabled, count decrements by one on the next clock.
    check_count_decrements: assert property (
        @(posedge clk) disable iff (reset == 1'b0)
        (enable != 1'b1) |=> (count == ($past(count) - 3'b001))
    );

    // Incrementing from 7 wraps back to 0.
    check_increment_wraps_to_zero: assert property (
        @(posedge clk) disable iff (reset == 1'b0)
        (enable == 1'b1) && (count == 3'b111) |=> (count == 3'b000)
    );

    // Decrementing from 0 wraps back to 7.
    check_decrement_wraps_to_seven: assert property (
        @(posedge clk) disable iff (reset == 1'b0)
        (enable != 1'b1) && (count == 3'b000) |=> (count == 3'b111)
    );

    // Outside reset, count must change every clock.
    check_count_never_stalls: assert property (
        @(posedge clk) disable iff (reset == 1'b0)
        1'b1 |=> (count != $past(count))
    );

endmodule

rtl:
module half_adder
(
    input       x_in,       // one bit input data
    input       y_in,       // one bit input data
    output      s_out,      // sum of two input
    output      c_out       // carry of two input
);

assign s_out = x_in ^ y_in;
assign c_out = x_in & y_in;

endmodule

module full_adder
(
    input       x_in,       // one bit input data
    input       y_in,       // one bit input data
    input       c_in,       // one bit carry data
    output      wire s_out, // sum of two input
    output      wire c_out  // carry of two input
);

wire wire_sum0;
wire wire_carry0;
wire wire_carry1;

half_adder U0_half_adder (
    .x_in(x_in),
    .y_in(y_in),
    .s_out(wire_sum0),
    .c_out(wire_carry0)
);

half_adder U1_half_adder (
    .x_in(wire_sum0),
    .y_in(c_in),
    .s_out(s_out),
    .c_out(wire_carry1)
);

assign c_out = wire_carry0 | wire_carry1;

endmodule

sva:
module full_adder_sva (
    input logic clk,
    input logic x_in,
    input logic y_in,
    input logic c_in,
    input logic s_out,
    input logic c_out,
    input logic wire_sum0,
    input logic wire_carry0,
    input logic wire_carry1
);

    // RTL is combinational with no native reset; clk is a sampling clock.

    // First half adder sum is x_in XOR y_in.
    check_u0_sum_xor: assert property (
        @(posedge clk) wire_sum0 == (x_in ^ y_in)
    );

    // First half adder carry is x_in AND y_in.
    check_u0_carry_and: assert property (
        @(posedge clk) wire_carry0 == (x_in & y_in)
    );

    // Second half adder sum is wire_sum0 XOR c_in.
    check_u1_sum_xor: assert property (
        @(posedge clk) s_out == (wire_sum0 ^ c_in)
    );

    // Second half adder carry is wire_sum0 AND c_in.
    check_u1_carry_and: assert property (
        @(posedge clk) wire_carry1 == (wire_sum0 & c_in)
    );

    // Final carry is the OR of the two internal carries.
    check_final_carry_or: assert property (
        @(posedge clk) c_out == (wire_carry0 | wire_carry1)
    );

    // End-to-end sum matches a 3-input XOR.
    check_full_sum_xor: assert property (
        @(posedge clk) s_out == (x_in ^ y_in ^ c_in)
    );

    // End-to-end carry is high when at least two inputs are high.
    check_full_carry_majority: assert property (
        @(posedge clk) c_out == ((x_in & y_in) | (x_in & c_in) | (y_in & c_in))
    );

    // Output pair equals the arithmetic sum of the three 1-bit inputs.
    check_full_adder_arithmetic: assert property (
        @(posedge clk) {c_out, s_out} == ({1'b0, x_in} + {1'b0, y_in} + {1'b0, c_in})
    );

endmodule

