sva:
module mux4to1_sva (
    input logic clk,
    input logic Y,
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic S0,
    input logic S1
);

    // Combinational RTL is sampled on an external verification clock.

    // Y is implemented as a 2:1 mux between C and D controlled by S1.
    check_output_function: assert property (
        @(posedge clk) Y == (S1 ? D : C)
    );

    // A is not used by the implemented output path.
    check_a_ignored: assert property (
        @(posedge clk)
        $changed(A) && $stable(B) && $stable(C) && $stable(D) && $stable(S0) && $stable(S1)
        |-> $stable(Y)
    );

    // B is not used by the implemented output path.
    check_b_ignored: assert property (
        @(posedge clk)
        $changed(B) && $stable(A) && $stable(C) && $stable(D) && $stable(S0) && $stable(S1)
        |-> $stable(Y)
    );

    // S0 does not affect the implemented output path.
    check_s0_ignored: assert property (
        @(posedge clk)
        $changed(S0) && $stable(A) && $stable(B) && $stable(C) && $stable(D) && $stable(S1)
        |-> $stable(Y)
    );

    // C is unselected when S1 is high.
    check_c_ignored_when_s1_high: assert property (
        @(posedge clk)
        S1 && $changed(C) && $stable(A) && $stable(B) && $stable(D) && $stable(S0) && $stable(S1)
        |-> $stable(Y)
    );

    // D is unselected when S1 is low.
    check_d_ignored_when_s1_low: assert property (
        @(posedge clk)
        !S1 && $changed(D) && $stable(A) && $stable(B) && $stable(C) && $stable(S0) && $stable(S1)
        |-> $stable(Y)
    );

endmodule

rtl:
module full_adder (
    input A,
    input B,
    input Cin,
    output S,
    output Cout
);

    assign {Cout, S} = A + B + Cin;

endmodule

module ripple_carry_adder (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] S,
    output Cout
);

    wire [3:0] S_i;
    wire [3:0] Cout_i;

    full_adder fa0 (.A(A[0]), .B(B[0]), .Cin(Cin), .S(S_i[0]), .Cout(Cout_i[0]));
    full_adder fa1 (.A(A[1]), .B(B[1]), .Cin(Cout_i[0]), .S(S_i[1]), .Cout(Cout_i[1]));
    full_adder fa2 (.A(A[2]), .B(B[2]), .Cin(Cout_i[1]), .S(S_i[2]), .Cout(Cout_i[2]));
    full_adder fa3 (.A(A[3]), .B(B[3]), .Cin(Cout_i[2]), .S(S_i[3]), .Cout(Cout));

    assign S = S_i;

endmodule

sva:
module ripple_carry_adder_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic Cin,
    input logic [3:0] S,
    input logic Cout
);

    function automatic logic carry_out (
        input logic a,
        input logic b,
        input logic cin
    );
        carry_out = (a & b) | (a & cin) | (b & cin);
    endfunction

    // Full 5-bit result matches A + B + Cin.
    check_total_sum: assert property (
        @(posedge clk) disable iff (1'b0)
        {Cout, S} == ({1'b0, A} + {1'b0, B} + Cin)
    );

    // Sum bit 0 matches the first full-adder stage.
    check_sum_bit0: assert property (
        @(posedge clk) disable iff (1'b0)
        S[0] == (A[0] ^ B[0] ^ Cin)
    );

    // Sum bit 1 uses the carry from bit 0.
    check_sum_bit1: assert property (
        @(posedge clk) disable iff (1'b0)
        S[1] == (A[1] ^ B[1] ^ carry_out(A[0], B[0], Cin))
    );

    // Sum bit 2 uses the carry propagated through bit 1.
    check_sum_bit2: assert property (
        @(posedge clk) disable iff (1'b0)
        S[2] == (A[2] ^ B[2] ^ carry_out(A[1], B[1], carry_out(A[0], B[0], Cin)))
    );

    // Sum bit 3 uses the carry propagated through bit 2.
    check_sum_bit3: assert property (
        @(posedge clk) disable iff (1'b0)
        S[3] == (A[3] ^ B[3] ^ carry_out(A[2], B[2], carry_out(A[1], B[1], carry_out(A[0], B[0], Cin))))
    );

    // Final carry-out matches the ripple-carry chain.
    check_final_carry: assert property (
        @(posedge clk) disable iff (1'b0)
        Cout == carry_out(A[3], B[3], carry_out(A[2], B[2], carry_out(A[1], B[1], carry_out(A[0], B[0], Cin))))
    );

endmodule

rtl:
module four_bit_adder(
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] Sum,
    output Cout
);

    wire [3:0] xor_out;
    wire [3:0] and_out;

    // XOR gates for the sum
    assign xor_out[0] = A[0] ^ B[0];
    assign xor_out[1] = A[1] ^ B[1];
    assign xor_out[2] = A[2] ^ B[2];
    assign xor_out[3] = A[3] ^ B[3];

    // AND gates for the carry
    assign and_out[0] = A[0] & B[0];
    assign and_out[1] = A[1] & B[1];
    assign and_out[2] = A[2] & B[2];
    assign and_out[3] = A[3] & B[3];

    // Generate carry out
    assign Cout = (and_out[0] & and_out[1]) | (and_out[1] & and_out[2]) | (and_out[2] & and_out[3]) | (and_out[3] & Cin);

    // Generate sum
    assign Sum[0] = xor_out[0] ^ Cin;
    assign Sum[1] = xor_out[1] ^ and_out[0];
    assign Sum[2] = xor_out[2] ^ and_out[1];
    assign Sum[3] = xor_out[3] ^ and_out[2];

endmodule

sva:
module four_bit_adder_sva (
    input logic       clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic       Cin,
    input logic [3:0] Sum,
    input logic       Cout
);

    // No clock or reset exists in the RTL; sample combinational behavior on clk.

    // Sum[0] matches the implemented XOR with Cin.
    check_sum_bit0_logic: assert property (
        @(posedge clk) Sum[0] == (A[0] ^ B[0] ^ Cin)
    );

    // Sum[1] matches the implemented XOR with bit-0 AND.
    check_sum_bit1_logic: assert property (
        @(posedge clk) Sum[1] == (A[1] ^ B[1] ^ (A[0] & B[0]))
    );

    // Sum[2] matches the implemented XOR with bit-1 AND.
    check_sum_bit2_logic: assert property (
        @(posedge clk) Sum[2] == (A[2] ^ B[2] ^ (A[1] & B[1]))
    );

    // Sum[3] matches the implemented XOR with bit-2 AND.
    check_sum_bit3_logic: assert property (
        @(posedge clk) Sum[3] == (A[3] ^ B[3] ^ (A[2] & B[2]))
    );

    // Cout matches the implemented carry equation.
    check_cout_logic: assert property (
        @(posedge clk) Cout == (
            ((A[0] & B[0]) & (A[1] & B[1])) |
            ((A[1] & B[1]) & (A[2] & B[2])) |
            ((A[2] & B[2]) & (A[3] & B[3])) |
            ((A[3] & B[3]) & Cin)
        )
    );

    // Upper sum bits do not depend on Cin when A and B are stable.
    check_upper_sum_independent_of_cin: assert property (
        @(posedge clk) ($stable(A) && $stable(B) && $changed(Cin)) |-> $stable(Sum[3:1])
    );

    // Sum[0] toggles with Cin when A[0] and B[0] are stable.
    check_sum0_follows_cin: assert property (
        @(posedge clk) ($stable(A[0]) && $stable(B[0]) && $changed(Cin)) |-> $changed(Sum[0])
    );

    // Cout is unchanged by Cin unless A[3] and B[3] are both high.
    check_cout_cin_gated_by_msb_and: assert property (
        @(posedge clk) ($stable(A) && $stable(B) && $changed(Cin) && !(A[3] & B[3])) |-> $stable(Cout)
    );

endmodule

rtl:
module sum_diff (
  input [7:0] A,
  input [7:0] B,
  output [7:0] S,
  output [7:0] D
);


  assign S = A + B;
  assign D = A - B;

endmodule

sva:
module sum_diff_sva (
    input logic       clk,
    input logic [7:0] A,
    input logic [7:0] B,
    input logic [7:0] S,
    input logic [7:0] D
);

    // S must equal the 8-bit sum of A and B.
    check_sum_function: assert property (
        @(posedge clk) S == (A + B)
    );

    // D must equal the 8-bit difference of A and B.
    check_diff_function: assert property (
        @(posedge clk) D == (A - B)
    );

    // Equal inputs must produce a zero difference.
    check_equal_inputs_zero_diff: assert property (
        @(posedge clk) (A == B) |-> (D == 8'h00)
    );

    // B equal to zero must pass A through both outputs.
    check_zero_b_passthrough: assert property (
        @(posedge clk) (B == 8'h00) |-> ((S == A) && (D == A))
    );

    // A equal to zero must make S equal B and D equal 0 minus B.
    check_zero_a_behavior: assert property (
        @(posedge clk) (A == 8'h00) |-> ((S == B) && (D == (8'h00 - B)))
    );

    // Stable inputs must keep both outputs stable.
    check_stable_inputs_stable_outputs: assert property (
        @(posedge clk) ($stable(A) && $stable(B)) |-> ($stable(S) && $stable(D))
    );

endmodule

rtl:
module next_higher_binary (
    input [3:0] in,
    input clk,
    output reg [3:0] out
);

reg [3:0] stage1_out;
reg [3:0] stage2_out;

always @(posedge clk) begin
    stage1_out <= in;
end

always @(posedge clk) begin
    stage2_out <= stage1_out;
end

always @(posedge clk) begin
    if (stage2_out == 4'b1111) begin
        out <= 4'b0000;
    end else begin
        out <= stage2_out + 1;
    end
end

endmodule

sva:
module next_higher_binary_sva (
    input logic [3:0] in,
    input logic       clk,
    input logic [3:0] out
);

    // Sequential clk-only pipeline; the RTL has no reset.
    // out is the next-higher value of in sampled two clocks earlier.

    // 4'hF wraps to 4'h0 after the two-cycle pipeline.
    check_wrap_after_two_cycles: assert property (
        @(posedge clk) ($past(1'b1,2) && ($past(in,2) == 4'hF)) |-> (out == 4'h0)
    );

    // All other input values increment by one after the two-cycle pipeline.
    check_increment_after_two_cycles: assert property (
        @(posedge clk) ($past(1'b1,2) && ($past(in,2) != 4'hF)) |-> (out == ($past(in,2) + 4'd1))
    );

    // Repeating the delayed input value keeps the output stable.
    check_output_stable_when_delayed_input_repeats: assert property (
        @(posedge clk) ($past(1'b1,3) && ($past(in,2) == $past(in,3))) |-> $stable(out)
    );

    // Changing the delayed input value changes the output.
    check_output_changes_when_delayed_input_changes: assert property (
        @(posedge clk) ($past(1'b1,3) && ($past(in,2) != $past(in,3))) |-> !$stable(out)
    );

endmodule

rtl:
module my_module (
    Y   ,
    A1  ,
    A2  ,
    B1  ,
    C1  ,
    D1  ,
    VPWR,
    VGND,
    VPB ,
    VNB
);

    output Y   ;
    input  A1  ;
    input  A2  ;
    input  B1  ;
    input  C1  ;
    input  D1  ;
    input  VPWR;
    input  VGND;
    input  VPB ;
    input  VNB ;

    assign Y = (A1 & A2) ? 1 :
               (B1) ? 0 :
               (C1) ? ~D1 :
               1;

endmodule

sva:
module my_module_sva (
    input logic Y,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic C1,
    input logic D1,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB
);

    // Y must match the RTL priority expression.
    check_y_matches_rtl_function: assert property (
        @($global_clock)
        Y == ((A1 & A2) ? 1'b1 :
              (B1 ? 1'b0 :
               (C1 ? ~D1 : 1'b1)))
    );

    // A1 and A2 high force Y high.
    check_a1_a2_path_forces_high: assert property (
        @($global_clock)
        (A1 & A2) |-> (Y == 1'b1)
    );

    // B1 high forces Y low when the A1/A2 path is inactive.
    check_b1_path_forces_low: assert property (
        @($global_clock)
        (!(A1 & A2) && B1) |-> (Y == 1'b0)
    );

    // C1 selects the inverted D1 value when higher-priority paths are inactive.
    check_c1_path_inverts_d1: assert property (
        @($global_clock)
        (!(A1 & A2) && !B1 && C1) |-> (Y == ~D1)
    );

    // The default path drives Y high when no earlier condition is selected.
    check_default_path_forces_high: assert property (
        @($global_clock)
        (!(A1 & A2) && !B1 && !C1) |-> (Y == 1'b1)
    );

endmodule

module power_management_sva (
    (* gclk *) input logic clk,
    input logic VIRTPWR,
    input logic SLEEP,
    input logic VPWR,
    input logic VPB,
    input logic VNB
);

    // SLEEP asserted forces virtual power low.
    check_sleep_forces_off: assert property (
        @(posedge clk) SLEEP |-> !VIRTPWR
    );

    // Loss of VPWR forces virtual power low.
    check_vpwr_loss_forces_off: assert property (
        @(posedge clk) !VPWR |-> !VIRTPWR
    );

    // Loss of VPB forces virtual power low.
    check_vpb_loss_forces_off: assert property (
        @(posedge clk) !VPB |-> !VIRTPWR
    );

    // Loss of VNB forces virtual power low.
    check_vnb_loss_forces_off: assert property (
        @(posedge clk) !VNB |-> !VIRTPWR
    );

    // All valid inputs drive virtual power high.
    check_all_conditions_enable_power: assert property (
        @(posedge clk) (!SLEEP && VPWR && VPB && VNB) |-> VIRTPWR
    );

    // Virtual power high requires all inputs to be valid.
    check_output_high_requires_valid_inputs: assert property (
        @(posedge clk) VIRTPWR |-> (!SLEEP && VPWR && VPB && VNB)
    );

    // Virtual power low requires at least one disabling condition.
    check_output_low_requires_disable_condition: assert property (
        @(posedge clk) !VIRTPWR |-> (SLEEP || !VPWR || !VPB || !VNB)
    );

    // Output matches the implemented combinational equation.
    check_output_matches_equation: assert property (
        @(posedge clk) VIRTPWR == (!SLEEP && VPWR && VPB && VNB)
    );

endmodule

rtl:
module comb_logic(
    input a,
    input b,
    input select,
    input clk,
    output reg out_always_ff
);

wire xor_out;
wire or_out;
wire not_select;

assign not_select = ~select;
assign xor_out = (a & ~b) | (~a & b);
assign or_out = a | b;

always @(posedge clk) begin
    if (not_select) begin
        out_always_ff <= xor_out;
    end else begin
        out_always_ff <= or_out;
    end
end

endmodule

sva:
module comb_logic_assertions (
    input logic a,
    input logic b,
    input logic select,
    input logic clk,
    input logic out_always_ff
);

    // Output captures the prior-cycle selected function of a and b.
    check_registered_mux_function: assert property (
        @(posedge clk)
        1'b1 |=> (out_always_ff == ($past(select)
                                   ? ($past(a) | $past(b))
                                   : (($past(a) & ~$past(b)) | (~$past(a) & $past(b))))
        )
    );

    // When select is low, output captures the prior XOR function.
    check_xor_path: assert property (
        @(posedge clk)
        !select |=> (out_always_ff == (($past(a) & ~$past(b)) | (~$past(a) & $past(b)))
        )
    );

    // When select is high, output captures the prior OR function.
    check_or_path: assert property (
        @(posedge clk)
        select |=> (out_always_ff == ($past(a) | $past(b)))
    );

    // With select low and equal inputs, output is low on the next clock.
    check_xor_equal_inputs_zero: assert property (
        @(posedge clk)
        (!select && (a == b)) |=> (out_always_ff == 1'b0)
    );

    // With select low and different inputs, output is high on the next clock.
    check_xor_different_inputs_one: assert property (
        @(posedge clk)
        (!select && (a != b)) |=> (out_always_ff == 1'b1)
    );

    // With select high and both inputs low, output is low on the next clock.
    check_or_both_low_zero: assert property (
        @(posedge clk)
        (select && !a && !b) |=> (out_always_ff == 1'b0)
    );

    // With select high and any input high, output is high on the next clock.
    check_or_any_high_one: assert property (
        @(posedge clk)
        (select && (a || b)) |=> (out_always_ff == 1'b1)
    );

endmodule

