sva:
module clock_gating_cell_sva (
    input logic clk,
    input logic enable,
    input logic gated_clk
);

    // Before clk rises, the gated clock must be low.
    check_gated_clk_low_on_posedge: assert property (
        @(posedge clk) gated_clk == 1'b0
    );

    // With enable low, the gated clock must be low before clk falls.
    check_gated_clk_blocked_when_disabled: assert property (
        @(negedge clk) !enable |-> (gated_clk == 1'b0)
    );

    // With enable high, the gated clock must be high before clk falls.
    check_gated_clk_passes_when_enabled: assert property (
        @(negedge clk) enable |-> (gated_clk == 1'b1)
    );

endmodule

module counter_sva #
(
    parameter integer WIDTH = 4
)
(
    input logic                 clk,
    input logic                 rst,
    input logic                 en,
    input logic [WIDTH-1:0]     count
);

    localparam [WIDTH-1:0] MAX_COUNT = {WIDTH{1'b1}};

    // Synchronous reset clears count on the following clock.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |=> (count == '0)
    );

    // When disabled, count holds its value.
    check_count_holds_when_disabled: assert property (
        @(posedge clk) disable iff (rst) !en |=> (count == $past(count))
    );

    // When enabled below max, count increments by one.
    check_count_increments_when_enabled: assert property (
        @(posedge clk) disable iff (rst) en && (count != MAX_COUNT) |=> (count == ($past(count) + 1'b1))
    );

    // When enabled at max, count wraps back to zero.
    check_count_wraps_at_max: assert property (
        @(posedge clk) disable iff (rst) en && (count == MAX_COUNT) |=> (count == '0)
    );

    // Reset takes priority even when enable is high.
    check_reset_priority_over_enable: assert property (
        @(posedge clk) rst && en |=> (count == '0)
    );

    // Any enabled cycle causes the count to change.
    check_count_changes_when_enabled: assert property (
        @(posedge clk) disable iff (rst) en |=> (count != $past(count))
    );

endmodule

rtl:
module axi_ethernet_ram_reader
   (state1a,
    goto_readDestAdrNib1,
    state0a,
    out_1,
    ram_valid_i,
    s_axi_aclk,
    AR,
    startReadDestAdrNib,
    Q );

  output state1a;
  output goto_readDestAdrNib1;
  output state0a;
  output out_1;

  input ram_valid_i;
  input s_axi_aclk;
  input [0:0]AR;
  input startReadDestAdrNib;
  input [7:0]Q;

  assign state1a = (state == 1'b1);
  assign goto_readDestAdrNib1 = (state == 1'b1);
  assign state0a = (state == 1'b0);
  assign out_1 = (state == 1'b0) && ram_valid_i;

  always @(posedge s_axi_aclk) begin
    if (state == 1'b1) begin
      if (startReadDestAdrNib) begin
        dest_addr_nibble <= AR;
        read_dest_addr_nibble <= 1'b1;
      end
      else begin
        ram_data <= {16'hdead, 16'hbeef};  // replaced $random with constants for simulation
        state <= 1'b0;
      end
    end
    else if (state == 1'b0) begin
      if (ram_valid_i) begin
        state <= 1'b1;
      end
    end
  end

  reg [15:0] ram_data;
  reg [3:0] dest_addr_nibble;
  reg read_dest_addr_nibble;
  reg [1:0] state = 2'b0;

endmodule

sva:
module axi_ethernet_ram_reader_sva (
    input logic state1a,
    input logic goto_readDestAdrNib1,
    input logic state0a,
    input logic out_1,
    input logic ram_valid_i,
    input logic s_axi_aclk,
    input logic [0:0] AR,
    input logic startReadDestAdrNib,
    input logic [7:0] Q
);

    // goto_readDestAdrNib1 is the same decode as state1a.
    check_goto_matches_state1a: assert property (
        @(posedge s_axi_aclk) goto_readDestAdrNib1 == state1a
    );

    // The two exported state decodes are never high together.
    check_state_decodes_mutex: assert property (
        @(posedge s_axi_aclk) !(state1a && state0a)
    );

    // out_1 matches the combinational definition from state0a and ram_valid_i.
    check_out1_definition: assert property (
        @(posedge s_axi_aclk) out_1 == (state0a && ram_valid_i)
    );

    // In state0a, ram_valid_i drives a transition to state1a on the next cycle.
    check_idle_to_state1_on_ram_valid: assert property (
        @(posedge s_axi_aclk) (state0a && ram_valid_i) |=> state1a
    );

    // In state0a without ram_valid_i, the state stays in state0a.
    check_idle_holds_without_ram_valid: assert property (
        @(posedge s_axi_aclk) (state0a && !ram_valid_i) |=> state0a
    );

    // In state1a with startReadDestAdrNib low, the next cycle returns to state0a.
    check_state1_to_state0_when_start_low: assert property (
        @(posedge s_axi_aclk) (state1a && !startReadDestAdrNib) |=> state0a
    );

    // In state1a with startReadDestAdrNib high, the state remains state1a.
    check_state1_holds_when_start_high: assert property (
        @(posedge s_axi_aclk) (state1a && startReadDestAdrNib) |=> state1a
    );

    // out_1 can only be high while the exported state decode is state0a.
    check_out1_only_in_state0: assert property (
        @(posedge s_axi_aclk) out_1 |-> state0a
    );

    // out_1 implies the machine will be in state1a on the next cycle.
    check_out1_leads_to_state1: assert property (
        @(posedge s_axi_aclk) out_1 |=> state1a
    );

endmodule

rtl:
module up_down_counter(
    input wire clk,        // Clock input
    input wire reset,      // Reset input
    input wire up_down,    // Control input for up or down counting
    output wire [3:0] out  // Counter output
);

    reg [3:0] counter;

    always @(posedge clk) begin
        if (reset) begin
            counter <= 4'b0000;
        end else begin
            if (up_down) begin
                counter <= counter + 1;
            end else begin
                counter <= counter - 1;
            end
        end
    end

    assign out = counter;

endmodule

module adder(
    input wire [3:0] a,        // First input to the adder
    input wire [3:0] b,        // Second input to the adder
    output wire [3:0] sum      // Sum output
);

    assign sum = a + b;

endmodule

module top_module(
    input wire clk,                // Clock input
    input wire reset,              // Reset input
    input wire up_down,            // Control input for up or down counting
    input wire [3:0] add_value,    // Fixed value to be added to the counter output
    output wire [3:0] out          // Final output, modified counter output
);

    wire [3:0] counter_out;
    wire [3:0] adder_out;

    up_down_counter udc(
        .clk(clk),
        .reset(reset),
        .up_down(up_down),
        .out(counter_out)
    );

    adder add(
        .a(counter_out),
        .b(add_value),
        .sum(adder_out)
    );

    assign out = adder_out;

endmodule

sva:
module top_module_sva(
    input logic clk,
    input logic reset,
    input logic up_down,
    input logic [3:0] add_value,
    input logic [3:0] out,
    input logic [3:0] counter_out,
    input logic [3:0] adder_out
);

    // Top-level output must mirror the adder output.
    check_output_matches_adder: assert property (
        @(posedge clk) disable iff (reset) out == adder_out
    );

    // Adder output must equal counter_out plus add_value.
    check_adder_function: assert property (
        @(posedge clk) disable iff (reset) adder_out == (counter_out + add_value)
    );

    // After a reset cycle, the counter output must be zero.
    check_counter_clears_after_reset: assert property (
        @(posedge clk) disable iff (reset)
        (!$initstate && $past(reset)) |-> (counter_out == 4'b0000)
    );

    // After a reset cycle, the final output must equal add_value.
    check_output_after_reset: assert property (
        @(posedge clk) disable iff (reset)
        (!$initstate && $past(reset)) |-> (out == add_value)
    );

    // When counting up, the counter increments by one.
    check_counter_counts_up: assert property (
        @(posedge clk) disable iff (reset)
        (!$initstate && !$past(reset) && $past(up_down)) |-> (counter_out == ($past(counter_out) + 4'd1))
    );

    // When counting down, the counter decrements by one.
    check_counter_counts_down: assert property (
        @(posedge clk) disable iff (reset)
        (!$initstate && !$past(reset) && !$past(up_down)) |-> (counter_out == ($past(counter_out) - 4'd1))
    );

endmodule

rtl:
module decoder_3to8 (
    input [2:0] in,
    output reg [7:0] out
);

wire in0_not, in1_not, in2_not;

not U1(in0_not, in[0]);
not U2(in1_not, in[1]);
not U3(in2_not, in[2]);

always @(*) begin
    case(in)
        3'b000: out <= 8'b00000001;
        3'b001: out <= 8'b00000010;
        3'b010: out <= 8'b00000100;
        3'b011: out <= 8'b00001000;
        3'b100: out <= 8'b00010000;
        3'b101: out <= 8'b00100000;
        3'b110: out <= 8'b01000000;
        3'b111: out <= 8'b10000000;
    endcase
end

endmodule

sva:
module decoder_3to8_sva (
    input logic clk,
    input logic [2:0] in,
    input logic [7:0] out
);

    // 000 selects bit 0.
    check_decode_000: assert property (
        @(posedge clk) (in === 3'b000) |-> (out === 8'b00000001)
    );

    // 001 selects bit 1.
    check_decode_001: assert property (
        @(posedge clk) (in === 3'b001) |-> (out === 8'b00000010)
    );

    // 010 selects bit 2.
    check_decode_010: assert property (
        @(posedge clk) (in === 3'b010) |-> (out === 8'b00000100)
    );

    // 011 selects bit 3.
    check_decode_011: assert property (
        @(posedge clk) (in === 3'b011) |-> (out === 8'b00001000)
    );

    // 100 selects bit 4.
    check_decode_100: assert property (
        @(posedge clk) (in === 3'b100) |-> (out === 8'b00010000)
    );

    // 101 selects bit 5.
    check_decode_101: assert property (
        @(posedge clk) (in === 3'b101) |-> (out === 8'b00100000)
    );

    // 110 selects bit 6.
    check_decode_110: assert property (
        @(posedge clk) (in === 3'b110) |-> (out === 8'b01000000)
    );

    // 111 selects bit 7.
    check_decode_111: assert property (
        @(posedge clk) (in === 3'b111) |-> (out === 8'b10000000)
    );

    // For known inputs, the output is one-hot.
    check_output_onehot: assert property (
        @(posedge clk) !$isunknown(in) |-> $onehot(out)
    );

    // For known inputs, the output matches a left-shifted decode.
    check_output_matches_shift: assert property (
        @(posedge clk) !$isunknown(in) |-> (out === (8'b00000001 << in))
    );

