module logic_circuit (
    input Q,
    input CLK,
    input D,
    input SCD,
    input SCE,
    output reg Q_out
);

    wire mux_out;
    wire D_delayed;
    wire SCD_delayed;
    wire SCE_delayed;

    // Assuming the mux selects between D and SCD based on SCE
    assign mux_out = SCE ? SCD : D;

    // Simple D Flip-Flop functionality with additional logic for SCE and SCD
    always @(posedge CLK) begin
        if (SCE == 1'b0) begin
            Q_out <= D; // Direct path when SCE is low
        end else if (SCE == 1'b1) begin
            Q_out <= mux_out; // Mux output when SCE is high
        end
    end

endmodule

sva:
module logic_circuit_sva (
    input logic Q,
    input logic CLK,
    input logic D,
    input logic SCD,
    input logic SCE,
    input logic Q_out
);

    // Clock: CLK
    // Reset: none
    // Mixed logic: combinational select feeding sequential Q_out

    // When SCE is low, Q_out captures D on the next clock.
    check_capture_d_when_sce_low: assert property (
        @(posedge CLK)
        (SCE === 1'b0) |=> (Q_out === $past(D))
    );

    // When SCE is high, Q_out captures SCD on the next clock.
    check_capture_scd_when_sce_high: assert property (
        @(posedge CLK)
        (SCE === 1'b1) |=> (Q_out === $past(SCD))
    );

    // When SCE is neither 0 nor 1, Q_out holds its previous value.
    check_hold_when_sce_unknown: assert property (
        @(posedge CLK)
        ((SCE !== 1'b0) && (SCE !== 1'b1)) |=> (Q_out === $past(Q_out))
    );

endmodule

rtl:
module lcd_driver (
  input [7:0] data,
  input [1:0] ctrl,
  output reg [15:0] display
);

parameter width = 80;
parameter height = 25;

reg [7:0] display_data;
reg [1:0] display_ctrl;

always @(data or ctrl) begin
  display_data <= data;
  display_ctrl <= ctrl;
end

always @(display_data or display_ctrl) begin
  case (display_ctrl)
    2'b00: display <= {8'b0, display_data}; // Display data at the beginning of the line
    2'b01: display <= {display_data, 8'b0}; // Display data at the end of the line
    2'b10: display <= {4'b0, display_data, 4'b0}; // Display data at the center of the line
    2'b11: display <= {8'b0, 8'b0}; // Clear the display
    default: display <= {8'b0, 8'b0}; // Clear the display
  endcase
end

endmodule

sva:
module lcd_driver_sva (
    input logic        clk,
    input logic [7:0]  data,
    input logic [1:0]  ctrl,
    input logic [15:0] display
