module GrayCodeConverter (
  input [n-1:0] bin,
  output [n-1:0] gray
);

parameter n = 4; // number of bits in the binary number and Gray code

assign gray = bin ^ ({1'b0, bin}) >> 1;

endmodule

sva:
module GrayCodeConverter_sva #(
    parameter n = 4
) (
    input logic         clk,
    input logic [n-1:0] bin,
    input logic [n-1:0] gray
);

    // Gray output matches the implemented conversion equation.
    check_gray_equation: assert property (
        @(posedge clk) gray == (bin ^ (bin >> 1))
    );

    // The Gray MSB is the same as the binary MSB.
    check_gray_msb_passthrough: assert property (
        @(posedge clk) gray[n-1] == bin[n-1]
    );

    // A stable binary input yields a stable Gray output.
    check_gray_stable_when_bin_stable: assert property (
        @(posedge clk) $stable(bin) |-> $stable(gray)
    );

    genvar i;
    generate
        for (i = 0; i < n-1; i = i + 1) begin : gen_gray_lower_bit_checks
            // Each lower Gray bit is the XOR of adjacent binary bits.
            check_gray_adjacent_xor: assert property (
                @(posedge clk) gray[i] == (bin[i+1] ^ bin[i])
            );
        end
    endgenerate

endmodule

module arithmetic_operations_sva (
    input logic clk,
    input logic [7:0] A,
    input logic [7:0] B,
    input logic [2:0] ctrl,
    input logic [7:0] out
);

    // ctrl 000 selects bitwise AND.
    check_and_operation: assert property (
        @(posedge clk) (ctrl == 3'b000) |-> (out == (A & B))
    );

    // ctrl 001 selects bitwise OR.
    check_or_operation: assert property (
        @(posedge clk) (ctrl == 3'b001) |-> (out == (A | B))
    );

    // ctrl 010 selects bitwise XOR.
    check_xor_operation: assert property (
        @(posedge clk) (ctrl == 3'b010) |-> (out == (A ^ B))
    );

    // ctrl 011 selects addition.
    check_add_operation: assert property (
        @(posedge clk) (ctrl == 3'b011) |-> (out == (A + B))
    );

    // ctrl 100 selects subtraction.
    check_sub_operation: assert property (
        @(posedge clk) (ctrl == 3'b100) |-> (out == (A - B))
    );

    // ctrl 101 selects multiplication with 8-bit truncation.
    check_mul_operation: assert property (
        @(posedge clk) (ctrl == 3'b101) |-> (out == ((A * B) & 16'h00FF))
    );

    // ctrl 110 selects division when the divisor is non-zero.
    check_div_operation: assert property (
        @(posedge clk) ((ctrl == 3'b110) && (B != 8'h00)) |-> (out == (A / B))
    );

    // ctrl 111 selects modulo when the divisor is non-zero.
    check_mod_operation: assert property (
        @(posedge clk) ((ctrl == 3'b111) && (B != 8'h00)) |-> (out == (A % B))
    );

endmodule

rtl:
module altpriority_encoder_6_3_lh (
    input [5:0] data,
    output reg [2:0] q
);

// Logic to implement the 6-to-3 priority encoder with least-hot encoding

always @(*) begin
    case (data)
        6'b000001: q = 3'b000;
        6'b000010: q = 3'b001;
        6'b000100: q = 3'b010;
        6'b001000: q = 3'b011;
        6'b010000: q = 3'b100;
        6'b100000: q = 3'b101;
        default: q = 3'b110; // Default encoding for unused inputs
    endcase
end

endmodule

sva:
module altpriority_encoder_6_3_lh_sva (
    input logic clk,
    input logic [5:0] data,
    input logic [2:0] q
);

    // 000001 maps to 000.
    check_encode_000001: assert property (
        @(posedge clk) (data == 6'b000001) |-> (q == 3'b000)
    );

    // 000010 maps to 001.
    check_encode_000010: assert property (
        @(posedge clk) (data == 6'b000010) |-> (q == 3'b001)
    );

    // 000100 maps to 010.
    check_encode_000100: assert property (
        @(posedge clk) (data == 6'b000100) |-> (q == 3'b010)
    );

    // 001000 maps to 011.
    check_encode_001000: assert property (
        @(posedge clk) (data == 6'b001000) |-> (q == 3'b011)
    );

    // 010000 maps to 100.
    check_encode_010000: assert property (
        @(posedge clk) (data == 6'b010000) |-> (q == 3'b100)
    );

    // 100000 maps to 101.
    check_encode_100000: assert property (
        @(posedge clk) (data == 6'b100000) |-> (q == 3'b101)
    );

    // All other inputs map to the default code.
    check_default_encoding: assert property (
        @(posedge clk)
        (data != 6'b000001 &&
         data != 6'b000010 &&
         data != 6'b000100 &&
         data != 6'b001000 &&
         data != 6'b010000 &&
         data != 6'b100000) |-> (q == 3'b110)
    );

    // The output never produces 111.
    check_q_never_111: assert property (
        @(posedge clk) (q != 3'b111)
    );

