module calculator(
  input clk,
  input reset,
  input [1:0] op,
  input [7:0] a,
  input [7:0] b,
  output reg [7:0] result
);

  always @(posedge clk) begin
    if (reset) begin
      result <= 0;
    end else begin
      case (op)
        2'b00: result <= a + b;
        2'b01: result <= a - b;
        2'b10: result <= a * b;
        2'b11: result <= a / b;
      endcase
    end
  end

endmodule

sva:
module calculator_sva (
    input logic clk,
    input logic reset,
    input logic [1:0] op,
    input logic [7:0] a,
    input logic [7:0] b,
    input logic [7:0] result
);

    // After reset deasserts, the sampled result is still zero.
    check_reset_release_zero: assert property (
        @(posedge clk) disable iff (reset)
        $fell(reset) |-> (result == 8'h00)
    );

    // op 00 loads the sum of a and b into result.
    check_addition_result: assert property (
        @(posedge clk) disable iff (reset)
        (op == 2'b00) |=> (result == (($past(a) + $past(b)) & 16'h00ff))
    );

    // op 01 loads the difference of a and b into result.
    check_subtraction_result: assert property (
        @(posedge clk) disable iff (reset)
        (op == 2'b01) |=> (result == (($past(a) - $past(b)) & 16'h00ff))
    );

    // op 10 loads the low 8 bits of the product of a and b into result.
    check_multiplication_result: assert property (
        @(posedge clk) disable iff (reset)
        (op == 2'b10) |=> (result == (($past(a) * $past(b)) & 16'h00ff))
    );

    // op 11 loads the quotient of a divided by b when b is nonzero.
    check_division_result: assert property (
        @(posedge clk) disable iff (reset)
        ((op == 2'b11) && (b != 8'h00)) |=> (result == ($past(a) / $past(b)))
    );

endmodule

module comparator_sva (
    input logic       clk,
    input logic [3:0] a,
    input logic [3:0] b,
    input logic       out
);

    // If a is greater than b, out must be high.
    check_a_gt_b_sets_out_high: assert property (
        @(posedge clk) (a > b) |-> (out == 1'b1)
    );

    // If a is less than b, out must be low.
    check_a_lt_b_sets_out_low: assert property (
        @(posedge clk) (a < b) |-> (out == 1'b0)
    );

    // For unequal inputs, out must match the a>b comparison.
    check_unequal_inputs_match_compare: assert property (
        @(posedge clk) (a != b) |-> (out == (a > b))
    );

    // For unequal inputs, a high out implies a is greater than b.
    check_unequal_out_high_implies_a_gt_b: assert property (
        @(posedge clk) ((a != b) && (out == 1'b1)) |-> (a > b)
    );

    // For unequal inputs, a low out implies a is less than b.
    check_unequal_out_low_implies_a_lt_b: assert property (
        @(posedge clk) ((a != b) && (out == 1'b0)) |-> (a < b)
    );

endmodule

module mux_2to1_enable_sva (
    input logic clk,
    input logic enable,
    input logic [7:0] in1,
    input logic [7:0] in2,
    input logic [7:0] out
);

    // DUT is combinational; clk is only used to sample assertions and there is no reset.

    // When enable is 0, out must select in1.
    check_select_in1: assert property (
        @(posedge clk) (enable === 1'b0) |-> (out === in1)
    );

    // When enable is not 0, out must select in2.
    check_select_in2: assert property (
        @(posedge clk) (enable !== 1'b0) |-> (out === in2)
    );

    // The output must always match the implemented mux branch.
    check_mux_function: assert property (
        @(posedge clk)
        (((enable === 1'b0) && (out === in1)) ||
         ((enable !== 1'b0) && (out === in2)))
    );

    // With the in1 path selected and unchanged, out stays unchanged.
    check_stable_in1_path: assert property (
        @(posedge clk) (enable === 1'b0 && $stable(enable) && $stable(in1)) |-> $stable(out)
    );

    // With the in2 path selected and unchanged, out stays unchanged.
    check_stable_in2_path: assert property (
        @(posedge clk) (enable !== 1'b0 && $stable(enable) && $stable(in2)) |-> $stable(out)
    );

endmodule

